window.QURAN_PAGES = {"1": [{"sura": 1, "sura_name": "الفاتحة", "revelation": "Makkiyah", "aya": 1, "text": "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ۝١", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "سورة الفاتحة سميت هذه السورة بالفاتحة؛ لأنه يفتتح بها القرآن العظيم، وتسمى المثاني؛ لأنها تقرأ في كل ركعة، ولها أسماء أخر. أبتدئ قراءة القرآن باسم الله مستعينا به، (اللهِ) علم على الرب -تبارك وتعالى- المعبود بحق دون سواه، وهو أخص أسماء الله تعالى، ولا يسمى به غيره سبحانه. (الرَّحْمَنِ) ذي الرحمة العامة الذي وسعت رحمته جميع الخلق، (الرَّحِيمِ) بالمؤمنين، وهما اسمان من أسمائه تعالى، يتضمنان إثبات صفة الرحمة لله تعالى كما يليق بجلاله.", "isBasmala": false, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": "المنزل الأول (م ف 1)"}, {"sura": 1, "sura_name": "الفاتحة", "revelation": "Makkiyah", "aya": 2, "text": "ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ ۝٢", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "(الحَمْدُ للهِ رَبِّ العَالَمِينَ) الثناء على الله بصفاته التي كلُّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، وفي ضمنه أَمْرٌ لعباده أن يحمدوه، فهو المستحق له وحده، وهو سبحانه المنشئ للخلق، القائم بأمورهم، المربي لجميع خلقه بنعمه، ولأوليائه بالإيمان والعمل الصالح.", "isBasmala": false, "translation_en": "Praise be to God, Lord of the Worlds.", "translation_id": "Segala puji bagi Allah, Tuhan semesta alam.", "manzil": 1, "manzil_display": ""}, {"sura": 1, "sura_name": "الفاتحة", "revelation": "Makkiyah", "aya": 3, "text": "ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ۝٣", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "(الرَّحْمَنِ) الذي وسعت رحمته جميع الخلق، (الرَّحِيمِ)، بالمؤمنين، وهما اسمان من أسماء الله تعالى.", "isBasmala": false, "translation_en": "The Most Gracious, the Most Merciful.", "translation_id": "Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 1, "sura_name": "الفاتحة", "revelation": "Makkiyah", "aya": 4, "text": "مَـٰلِكِ یَوۡمِ ٱلدِّینِ ۝٤", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "وهو سبحانه وحده مالك يوم القيامة، وهو يوم الجزاء على الأعمال. وفي قراءة المسلم لهذه الآية في كل ركعة من صلواته تذكير له باليوم الآخر، وحثٌّ له على الاستعداد بالعمل الصالح، والكف عن المعاصي والسيئات.", "isBasmala": false, "translation_en": "Master of the Day of Judgment.", "translation_id": "Yang menguasai di Hari Pembalasan.", "manzil": 1, "manzil_display": ""}, {"sura": 1, "sura_name": "الفاتحة", "revelation": "Makkiyah", "aya": 5, "text": "إِیَّاكَ نَعۡبُدُ وَإِیَّاكَ نَسۡتَعِینُ ۝٥", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "إنا نخصك وحدك بالعبادة، ونستعين بك وحدك في جميع أمورنا، فالأمر كله بيدك، لا يملك منه أحد مثقال ذرة. وفي هذه الآية دليل على أن العبد لا يجوز له أن يصرف شيئًا من أنواع العبادة كالدعاء والاستغاثة والذبح والطواف إلا لله وحده، وفيها شفاء القلوب من داء التعلق بغير الله، ومن أمراض الرياء والعجب، والكبرياء.", "isBasmala": false, "translation_en": "It is You we worship, and upon You we call for help.", "translation_id": "Hanya Engkaulah yang kami sembah, dan hanya kepada Engkaulah kami meminta pertolongan.", "manzil": 1, "manzil_display": ""}, {"sura": 1, "sura_name": "الفاتحة", "revelation": "Makkiyah", "aya": 6, "text": "ٱهۡدِنَا ٱلصِّرَ ٰطَ ٱلۡمُسۡتَقِیمَ ۝٦", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "دُلَّنا، وأرشدنا، ووفقنا إلى الطريق المستقيم، وثبتنا عليه حتى نلقاك، وهو الإسلام، الذي هو الطريق الواضح الموصل إلى رضوان الله وإلى جنته، الذي دلّ عليه خاتم رسله وأنبيائه محمد صلى الله عليه وسلم، فلا سبيل إلى سعادة العبد إلا بالاستقامة عليه.", "isBasmala": false, "translation_en": "Guide us to the straight path.", "translation_id": "Tunjukilah kami jalan yang lurus,", "manzil": 1, "manzil_display": ""}, {"sura": 1, "sura_name": "الفاتحة", "revelation": "Makkiyah", "aya": 7, "text": "صِرَ ٰطَ ٱلَّذِینَ أَنۡعَمۡتَ عَلَیۡهِمۡ غَیۡرِ ٱلۡمَغۡضُوبِ عَلَیۡهِمۡ وَلَا ٱلضَّاۤلِّینَ ۝٧", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "طريق الذين أنعمت عليهم من النبيين والصدِّيقين والشهداء والصالحين، فهم أهل الهداية والاستقامة، ولا تجعلنا ممن سلك طريق المغضوب عليهم، الذين عرفوا الحق ولم يعملوا به، وهم اليهود، ومن كان على شاكلتهم، والضالين، وهم الذين لم يهتدوا، فضلوا الطريق، وهم النصارى، ومن اتبع سنتهم. وفي هذا الدعاء شفاء لقلب المسلم من مرض الجحود والجهل والضلال، ودلالة على أن أعظم نعمة على الإطلاق هي نعمة الإسلام، فمن كان أعرف للحق وأتبع له، كان أولى بالصراط المستقيم، ولا ريب أن أصحاب رسول الله صلى الله عليه وسلم هم أولى الناس بذلك بعد الأنبياء عليهم السلام، فدلت الآية على فضلهم، وعظيم منزلتهم، رضي الله عنهم. ويستحب للقارئ أن يقول في الصلاة بعد قراءة الفاتحة: (آمين)، ومعناها: اللهم استجب، وليست آية من سورة الفاتحة باتفاق العلماء؛ ولهذا أجمعوا على عدم كتابتها في المصاحف.", "isBasmala": false, "translation_en": "The path of those You have blessed, not of those against whom there is anger, nor of those who are misguided.", "translation_id": "(yaitu) Jalan orang-orang yang telah Engkau beri nikmat kepada mereka; bukan (jalan) mereka yang dimurkai dan bukan (pula jalan) mereka yang sesat.", "manzil": 1, "manzil_display": ""}], "2": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 3, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 1, "text": "الۤمۤ ۝١", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "هذه الحروف وغيرها من الحروف المقطَّعة في أوائل السور فيها إشارة إلى إعجاز القرآن؛ فقد وقع به تحدي المشركين، فعجزوا عن معارضته، وهو مركَّب من هذه الحروف التي تتكون منها لغة العرب. فدَلَّ عجز العرب عن الإتيان بمثله -مع أنهم أفصح الناس- على أن القرآن وحي من الله.", "isBasmala": false, "translation_en": "Alif, Lam, Meem.", "translation_id": "Alif laam miim.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 2, "text": "ذَ ٰلِكَ ٱلۡكِتَـٰبُ لَا رَیۡبَۛ فِیهِۛ هُدࣰى لِّلۡمُتَّقِینَ ۝٢", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "ذلك القرآن هو الكتاب العظيم الذي لا شَكَّ أنه من عند الله، فلا يصح أن يرتاب فيه أحد لوضوحه، ينتفع به المتقون بالعلم النافع والعمل الصالح وهم الذين يخافون الله، ويتبعون أحكامه.", "isBasmala": false, "translation_en": "This is the Book in which there is no doubt, a guide for the righteous.", "translation_id": "Kitab (Al Quran) ini tidak ada keraguan padanya; petunjuk bagi mereka yang bertakwa,", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 3, "text": "ٱلَّذِینَ یُؤۡمِنُونَ بِٱلۡغَیۡبِ وَیُقِیمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ ۝٣", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "وهم الذين يُصَدِّقون بالغيب الذي لا تدركه حواسُّهم ولا عقولهم وحدها؛ لأنه لا يُعْرف إلا بوحي الله إلى رسله، مثل الإيمان بالملائكة، والجنة، والنار، وغير ذلك مما أخبر الله به أو أخبر به رسوله، (والإيمان: كلمة جامعة للإقرار بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره، وتصديق الإقرار بالقول والعمل بالقلب واللسان والجوارح) وهم مع تصديقهم بالغيب يحافظون على أداء الصلاة في مواقيتها أداءً صحيحًا وَفْق ما شرع الله لنبيه محمد صلى الله عليه وسلم، ومما أعطيناهم من المال يخرجون صدقة أموالهم الواجبة والمستحبة.", "isBasmala": false, "translation_en": "Those who believe in the unseen, and perform the prayers, and give from what We have provided for them.", "translation_id": "(yaitu) mereka yang beriman kepada yang ghaib, yang mendirikan shalat, dan menafkahkan sebahagian rezeki yang Kami anugerahkan kepada mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 4, "text": "وَٱلَّذِینَ یُؤۡمِنُونَ بِمَاۤ أُنزِلَ إِلَیۡكَ وَمَاۤ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡـَٔاخِرَةِ هُمۡ یُوقِنُونَ ۝٤", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "والذين يُصَدِّقون بما أُنزل إليك أيها الرسول من القرآن، وبما أنزل إليك من الحكمة، وهي السنة، وبكل ما أُنزل مِن قبلك على الرسل من كتب، كالتوراة والإنجيل وغيرهما، ويُصَدِّقون بدار الحياة بعد الموت وما فيها من الحساب والجزاء، تصديقا بقلوبهم يظهر على ألسنتهم وجوارحهم وخص يوم الآخرة؛ لأن الإيمان به من أعظم البواعث على فعل الطاعات، واجتناب المحرمات، ومحاسبة النفس.", "isBasmala": false, "translation_en": "And those who believe in what was revealed to you, and in what was revealed before you, and are certain of the Hereafter.", "translation_id": "dan mereka yang beriman kepada Kitab (Al Quran) yang telah diturunkan kepadamu dan Kitab-kitab yang telah diturunkan sebelummu, serta mereka yakin akan adanya (kehidupan) akhirat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 5, "text": "أُو۟لَـٰۤىِٕكَ عَلَىٰ هُدࣰى مِّن رَّبِّهِمۡۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝٥", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "أصحاب هذه الصفات يسيرون على نور من ربهم وبتوفيق مِن خالقهم وهاديهم، وهم الفائزون الذين أدركوا ما طلبوا، ونَجَوا من شرِّ ما منه هربوا.", "isBasmala": false, "translation_en": "These are upon guidance from their Lord. These are the successful.", "translation_id": "Mereka itulah yang tetap mendapat petunjuk dari Tuhan mereka, dan merekalah orang-orang yang beruntung.", "manzil": 1, "manzil_display": ""}], "3": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 6, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ سَوَاۤءٌ عَلَیۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا یُؤۡمِنُونَ ۝٦", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "إن الذين جحدوا ما أُنزل إليك من ربك استكبارًا وطغيانًا، لن يقع منهم الإيمان، سواء أخوَّفتهم وحذرتهم من عذاب الله، أم تركت ذلك؛ لإصرارهم على باطلهم.", "isBasmala": false, "translation_en": "As for those who disbelieve-it is the same for them, whether you have warned them, or have not warned them-they do not believe.", "translation_id": "Sesungguhnya orang-orang kafir, sama saja bagi mereka, kamu beri peringatan atau tidak kamu beri peringatan, mereka tidak juga akan beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 7, "text": "خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰۤ أَبۡصَـٰرِهِمۡ غِشَـٰوَةࣱۖ وَلَهُمۡ عَذَابٌ عَظِیمࣱ ۝٧", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "طبع الله على قلوب هؤلاء وعلى سمعهم، وجعل على أبصارهم غطاء؛ بسبب كفرهم وعنادهم مِن بعد ما تبيَّن لهم الحق، فلم يوفقهم للهدى، ولهم عذاب شديد في نار جهنم.", "isBasmala": false, "translation_en": "God has set a seal on their hearts and on their hearing, and over their vision is a veil. They will have a severe torment.", "translation_id": "Allah telah mengunci-mati hati dan pendengaran mereka, dan penglihatan mereka ditutup. Dan bagi mereka siksa yang amat berat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 8, "text": "وَمِنَ ٱلنَّاسِ مَن یَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَمَا هُم بِمُؤۡمِنِینَ ۝٨", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "ومن الناس فريق يتردد متحيِّرًا بين المؤمنين والكافرين، وهم المنافقون الذين يقولون بألسنتهم: صدَّقْنَا بالله وباليوم الآخر، وهم في باطنهم كاذبون لم يؤمنوا.", "isBasmala": false, "translation_en": "Among the people are those who say, \"We believe in God and in the Last Day,\" but they are not believers.", "translation_id": "Di antara manusia ada yang mengatakan: \"Kami beriman kepada Allah dan Hari kemudian,\" pada hal mereka itu sesungguhnya bukan orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 9, "text": "یُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِینَ ءَامَنُوا۟ وَمَا یَخۡدَعُونَ إِلَّاۤ أَنفُسَهُمۡ وَمَا یَشۡعُرُونَ ۝٩", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "يعتقدون بجهلهم أنهم يخادعون الله والذين آمنوا بإظهارهم الإيمان وإضمارهم الكفر، وما يخدعون إلا أنفسهم؛ لأن عاقبة خداعهم تعود عليهم. ومِن فرط جهلهم لا يُحِسُّون بذلك؛ لفساد قلوبهم.", "isBasmala": false, "translation_en": "They seek to deceive God and those who believe, but they deceive none but themselves, though they are not aware.", "translation_id": "Mereka hendak menipu Allah dan orang-orang yang beriman, padahal mereka hanya menipu dirinya sendiri sedang mereka tidak sadar.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 10, "text": "فِی قُلُوبِهِم مَّرَضࣱ فَزَادَهُمُ ٱللَّهُ مَرَضࣰاۖ وَلَهُمۡ عَذَابٌ أَلِیمُۢ بِمَا كَانُوا۟ یَكۡذِبُونَ ۝١٠", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "في قلوبهم شكٌّ وفساد فابْتُلوا بالمعاصي الموجبة لعقوبتهم، فزادهم الله شكًا، ولهم عقوبة موجعة بسبب كذبهم ونفاقهم.", "isBasmala": false, "translation_en": "In their hearts is sickness, and God has increased their sickness. They will have a painful punishment because of their denial.", "translation_id": "Dalam hati mereka ada penyakit, lalu ditambah Allah penyakitnya; dan bagi mereka siksa yang pedih, disebabkan mereka berdusta.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 11, "text": "وَإِذَا قِیلَ لَهُمۡ لَا تُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ قَالُوۤا۟ إِنَّمَا نَحۡنُ مُصۡلِحُونَ ۝١١", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "وإذا نُصحوا ليكفُّوا عن الإفساد في الأرض بالكفر والمعاصي، وإفشاء أسرار المؤمنين، وموالاة الكافرين، قالوا كذبًا وجدالا إنما نحن أهل الإصلاح.", "isBasmala": false, "translation_en": "And when it is said to them, \"Do not make trouble on earth,\" they say, \"We are only reformers.\"", "translation_id": "Dan bila dikatakan kepada mereka: \"Janganlah kamu membuat kerusakan di muka bumi\". Mereka menjawab: \"Sesungguhnya kami orang-orang yang mengadakan perbaikan\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 12, "text": "أَلَاۤ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ وَلَـٰكِن لَّا یَشۡعُرُونَ ۝١٢", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "إنَّ هذا الذي يفعلونه ويزعمون أنه إصلاح هو عين الفساد، لكنهم بسبب جهلهم وعنادهم لا يُحِسُّون.", "isBasmala": false, "translation_en": "In fact, they are the troublemakers, but they are not aware.", "translation_id": "Ingatlah, sesungguhnya mereka itulah orang-orang yang membuat kerusakan, tetapi mereka tidak sadar.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 13, "text": "وَإِذَا قِیلَ لَهُمۡ ءَامِنُوا۟ كَمَاۤ ءَامَنَ ٱلنَّاسُ قَالُوۤا۟ أَنُؤۡمِنُ كَمَاۤ ءَامَنَ ٱلسُّفَهَاۤءُۗ أَلَاۤ إِنَّهُمۡ هُمُ ٱلسُّفَهَاۤءُ وَلَـٰكِن لَّا یَعۡلَمُونَ ۝١٣", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "وإذا قيل للمنافقين: آمِنُوا -مثل إيمان الصحابة، وهو الإيمان بالقلب واللسان والجوارح-، جادَلوا وقالوا: أَنُصَدِّق مثل تصديق ضعاف العقل والرأي، فنكون نحن وهم في السَّفَهِ سواء؟ فردَّ الله عليهم بأن السَّفَهَ مقصور عليهم، وهم لا يعلمون أن ما هم فيه هو الضلال والخسران.", "isBasmala": false, "translation_en": "And when it is said to them, \"Believe as the people have believed,\" they say, \"Shall we believe as the fools have believed?\" In fact, it is they who are the fools, but they do not know.", "translation_id": "Apabila dikatakan kepada mereka: \"Berimanlah kamu sebagaimana orang-orang lain telah beriman\". Mereka menjawab: \"Akan berimankah kami sebagaimana orang-orang yang bodoh itu telah beriman?\" Ingatlah, sesungguhnya merekalah orang-orang yang bodoh; tetapi mereka tidak tahu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 14, "text": "وَإِذَا لَقُوا۟ ٱلَّذِینَ ءَامَنُوا۟ قَالُوۤا۟ ءَامَنَّا وَإِذَا خَلَوۡا۟ إِلَىٰ شَیَـٰطِینِهِمۡ قَالُوۤا۟ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ ۝١٤", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "هؤلاء المنافقون إذا قابلوا المؤمنين قالوا: صدَّقنا بالإسلام مثلكم، وإذا انصرفوا وذهبوا إلى زعمائهم الكفرة المتمردين على الله أكَّدوا لهم أنهم على ملة الكفر لم يتركوها، وإنما كانوا يَسْتَخِفُّون بالمؤمنين، ويسخرون منهم.", "isBasmala": false, "translation_en": "And when they come across those who believe, they say, \"We believe\"; but when they are alone with their devils, they say, \"We are with you; we were only ridiculing.\"", "translation_id": "Dan bila mereka berjumpa dengan orang-orang yang beriman, mereka mengatakan: \"Kami telah beriman\". Dan bila mereka kembali kepada syaitan-syaitan mereka, mereka mengatakan: \"Sesungguhnya kami sependirian dengan kamu, kami hanyalah berolok-olok\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 15, "text": "ٱللَّهُ یَسۡتَهۡزِئُ بِهِمۡ وَیَمُدُّهُمۡ فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ ۝١٥", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "الله يستهزئ بهم ويُمهلهم؛ ليزدادوا ضلالا وحَيْرة وترددًا، ويجازيهم على استهزائهم بالمؤمنين.", "isBasmala": false, "translation_en": "It is God who ridicules them, and leaves them bewildered in their transgression.", "translation_id": "Allah akan (membalas) olok-olokan mereka dan membiarkan mereka terombang-ambing dalam kesesatan mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 16, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ٱشۡتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمۡ وَمَا كَانُوا۟ مُهۡتَدِینَ ۝١٦", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "أولئك المنافقون باعوا أنفسهم في صفقة خاسرة، فأخذوا الكفر، وتركوا الإيمان، فما كسبوا شيئًا، بل خَسِروا الهداية. وهذا هو الخسران المبين.", "isBasmala": false, "translation_en": "Those are they who have bartered error for guidance; but their trade does not profit them, and they are not guided.", "translation_id": "Mereka itulah orang yang membeli kesesatan dengan petunjuk, maka tidaklah beruntung perniagaan mereka dan tidaklah mereka mendapat petunjuk.", "manzil": 1, "manzil_display": ""}], "4": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 17, "text": "مَثَلُهُمۡ كَمَثَلِ ٱلَّذِی ٱسۡتَوۡقَدَ نَارࣰا فَلَمَّاۤ أَضَاۤءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِی ظُلُمَـٰتࣲ لَّا یُبۡصِرُونَ ۝١٧", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "حال المنافقين الذين آمنوا -ظاهرًا لا باطنًا- برسالة محمد صلى الله عليه وسلم، ثم كفروا، فصاروا يتخبطون في ظلماتِ ضلالهم وهم لا يشعرون، ولا أمل لهم في الخروج منها، تُشْبه حالَ جماعة في ليلة مظلمة، وأوقد أحدهم نارًا عظيمة للدفء والإضاءة، فلما سطعت النار وأنارت ما حوله، انطفأت وأعتمت، فصار أصحابها في ظلمات لا يرون شيئًا، ولا يهتدون إلى طريق ولا مخرج.", "isBasmala": false, "translation_en": "Their likeness is that of a person who kindled a fire; when it illuminated all around him, God took away their light, and left them in darkness, unable to see.", "translation_id": "Perumpamaan mereka adalah seperti orang yang menyalakan api, maka setelah api itu menerangi sekelilingnya Allah hilangkan cahaya (yang menyinari) mereka, dan membiarkan mereka dalam kegelapan, tidak dapat melihat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 18, "text": "صُمُّۢ بُكۡمٌ عُمۡیࣱ فَهُمۡ لَا یَرۡجِعُونَ ۝١٨", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "هم صُمٌّ عن سماع الحق سماع تدبر، بُكْم عن النطق به، عُمْي عن إبصار نور الهداية؛ لذلك لا يستطيعون الرجوع إلى الإيمان الذي تركوه، واستعاضوا عنه بالضلال.", "isBasmala": false, "translation_en": "Deaf, dumb, blind. They will not return.", "translation_id": "Mereka tuli, bisu dan buta, maka tidaklah mereka akan kembali (ke jalan yang benar),", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 19, "text": "أَوۡ كَصَیِّبࣲ مِّنَ ٱلسَّمَاۤءِ فِیهِ ظُلُمَـٰتࣱ وَرَعۡدࣱ وَبَرۡقࣱ یَجۡعَلُونَ أَصَـٰبِعَهُمۡ فِیۤ ءَاذَانِهِم مِّنَ ٱلصَّوَ ٰعِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِیطُۢ بِٱلۡكَـٰفِرِینَ ۝١٩", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "أو تُشْبه حالُ فريق آخر من المنافقين يظهر لهم الحق تارة، ويشكون فيه تارة أخرى، حالَ جماعة يمشون في العراء، فينصب عليهم مطر شديد، تصاحبه ظلمات بعضها فوق بعض، مع قصف الرعد، ولمعان البرق، والصواعق المحرقة، التي تجعلهم من شدة الهول يضعون أصابعهم في آذانهم؛ خوفًا من الهلاك. والله تعالى محيط بالكافرين لا يفوتونه ولا يعجزونه.", "isBasmala": false, "translation_en": "Or like a cloudburst from the sky, in which is darkness, and thunder, and lightning. They press their fingers into their ears from the thunderbolts, in fear of death. But God surrounds the disbelievers.", "translation_id": "atau seperti (orang-orang yang ditimpa) hujan lebat dari langit disertai gelap gulita, guruh dan kilat; mereka menyumbat telinganya dengan anak jarinya, karena (mendengar suara) petir, sebab takut akan mati. Dan Allah meliputi orang-orang yang kafir.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 20, "text": "یَكَادُ ٱلۡبَرۡقُ یَخۡطَفُ أَبۡصَـٰرَهُمۡۖ كُلَّمَاۤ أَضَاۤءَ لَهُم مَّشَوۡا۟ فِیهِ وَإِذَاۤ أَظۡلَمَ عَلَیۡهِمۡ قَامُوا۟ۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَـٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٢٠", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "يقارب البرق -من شدة لمعانه- أن يسلب أبصارهم، ومع ذلك فكلَّما أضاء لهم مشَوْا في ضوئه، وإذا ذهب أظلم الطريق عليهم فيقفون في أماكنهم. ولولا إمهال الله لهم لسلب سمعهم وأبصارهم، وهو قادر على ذلك في كل وقتٍ، إنه على كل شيء قدير.", "isBasmala": false, "translation_en": "The lightning almost snatches their sight away. Whenever it illuminates for them, they walk in it; but when it grows dark over them, they stand still. Had God willed, He could have taken away their hearing and their sight. God is capable of everything.", "translation_id": "Hampir-hampir kilat itu menyambar penglihatan mereka. Setiap kali kilat itu menyinari mereka, mereka berjalan di bawah sinar itu, dan bila gelap menimpa mereka, mereka berhenti. Jikalau Allah menghendaki, niscaya Dia melenyapkan pendengaran dan penglihatan mereka. Sesungguhnya Allah berkuasa atas segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 21, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ ٱعۡبُدُوا۟ رَبَّكُمُ ٱلَّذِی خَلَقَكُمۡ وَٱلَّذِینَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ ۝٢١", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "نداء من الله للبشر جميعًا: أن اعبدوا الله الذي ربَّاكم بنعمه، وخافوه ولا تخالفوا دينه؛ فقد أوجدكم من العدم، وأوجد الذين من قبلكم؛ لتكونوا من المتقين الذين رضي الله عنهم ورضوا عنه.", "isBasmala": false, "translation_en": "O people! Worship your Lord who created you and those before you, that you may attain piety.", "translation_id": "Hai manusia, sembahlah Tuhanmu yang telah menciptakanmu dan orang-orang yang sebelummu, agar kamu bertakwa,", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 22, "text": "ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَ ٰشࣰا وَٱلسَّمَاۤءَ بِنَاۤءࣰ وَأَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَ ٰتِ رِزۡقࣰا لَّكُمۡۖ فَلَا تَجۡعَلُوا۟ لِلَّهِ أَندَادࣰا وَأَنتُمۡ تَعۡلَمُونَ ۝٢٢", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "ربكم الذي جعل لكم الأرض بساطًا؛ لتسهل حياتكم عليها، والسماء محكمة البناء، وأنزل المطر من السحاب فأخرج لكم به من ألوان الثمرات وأنواع النبات رزقًا لكم، فلا تجعلوا لله نظراء في العبادة، وأنتم تعلمون تفرُّده بالخلق والرزق، واستحقاقِه العبودية.", "isBasmala": false, "translation_en": "He who made the earth a habitat for you, and the sky a structure, and sends water down from the sky, and brings out fruits thereby, as a sustenance for you. Therefore, do not assign rivals to God while you know.", "translation_id": "Dialah yang menjadikan bumi sebagai hamparan bagimu dan langit sebagai atap, dan Dia menurunkan air (hujan) dari langit, lalu Dia menghasilkan dengan hujan itu segala buah-buahan sebagai rezeki untukmu; karena itu janganlah kamu mengadakan sekutu-sekutu bagi Allah, padahal kamu mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 23, "text": "وَإِن كُنتُمۡ فِی رَیۡبࣲ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُوا۟ بِسُورَةࣲ مِّن مِّثۡلِهِۦ وَٱدۡعُوا۟ شُهَدَاۤءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَـٰدِقِینَ ۝٢٣", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "وإن كنتم -أيها الكافرون المعاندون- في شَكٍّ من القرآن الذي نَزَّلناه على عبدنا محمد صلى الله عليه وسلم، وتزعمون أنه ليس من عند الله، فهاتوا سورة تماثل سورة من القرآن، واستعينوا بمن تقدرون عليه مِن أعوانكم، إن كنتم صادقين في دعواكم.", "isBasmala": false, "translation_en": "And if you are in doubt about what We have revealed to Our servant, then produce a chapter like these, and call your witnesses apart from God, if you are truthful.", "translation_id": "Dan jika kamu (tetap) dalam keraguan tentang Al Quran yang Kami wahyukan kepada hamba Kami (Muhammad), buatlah satu surat (saja) yang semisal Al Quran itu dan ajaklah penolong-penolongmu selain Allah, jika kamu orang-orang yang benar.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 24, "text": "فَإِن لَّمۡ تَفۡعَلُوا۟ وَلَن تَفۡعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِی وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَـٰفِرِینَ ۝٢٤", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "فإن عجَزتم الآن -وستعجزون مستقبلا لا محالة- فاتقوا النار بالإيمان بالنبي صلى الله عليه وسلم وطاعة الله تعالى. هذه النار التي حَطَبُها الناس والحجارة، أُعِدَّتْ للكافرين بالله ورسله.", "isBasmala": false, "translation_en": "But if you do not-and you will not-then beware the Fire whose fuel is people and stones, prepared for the disbelievers.", "translation_id": "Maka jika kamu tidak dapat membuat(nya) -- dan pasti kamu tidak akan dapat membuat(nya), peliharalah dirimu dari neraka yang bahan bakarnya manusia dan batu, yang disediakan bagi orang-orang kafir.", "manzil": 1, "manzil_display": ""}], "5": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 25, "text": "وَبَشِّرِ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ كُلَّمَا رُزِقُوا۟ مِنۡهَا مِن ثَمَرَةࣲ رِّزۡقࣰاۙ قَالُوا۟ هَـٰذَا ٱلَّذِی رُزِقۡنَا مِن قَبۡلُۖ وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهࣰاۖ وَلَهُمۡ فِیهَاۤ أَزۡوَ ٰجࣱ مُّطَهَّرَةࣱۖ وَهُمۡ فِیهَا خَـٰلِدُونَ ۝٢٥", "juz": 1, "hizb": "(* ح 1*)", "tafsir": "وأخبر -أيها الرسول- أهل الإيمان والعمل الصالح خبرًا يملؤهم سرورًا، بأن لهم في الآخرة حدائق عجيبة، تجري الأنهار تحت قصورها العالية وأشجارها الظليلة. كلَّما رزقهم الله فيها نوعًا من الفاكهة اللذيذة قالوا: قد رَزَقَنا الله هذا النوع من قبل، فإذا ذاقوه وجدوه شيئًا جديدًا في طعمه ولذته، وإن تشابه مع سابقه في اللون والمنظر والاسم. ولهم في الجنَّات زوجات مطهَّرات من كل ألوان الدنس الحسيِّ كالبول والحيض، والمعنوي كالكذب وسوء الخُلُق. وهم في الجنة ونعيمها دائمون، لا يموتون فيها ولا يخرجون منها.", "isBasmala": false, "translation_en": "And give good news to those who believe and do righteous deeds; that they will have gardens beneath which rivers flow. Whenever they are provided with fruit therefrom as sustenance, they will say, \"This is what we were provided with before,\" and they will be given the like of it. And they will have pure spouses therein, and they will abide therein forever.", "translation_id": "Dan sampaikanlah berita gembira kepada mereka yang beriman dan berbuat baik, bahwa bagi mereka disediakan surga-surga yang mengalir sungai-sungai di dalamnya. Setiap mereka diberi rezeki buah-buahan dalam surga-surga itu, mereka mengatakan: \"Inilah yang pernah diberikan kepada kami dahulu\". Mereka diberi buah-buahan yang serupa dan untuk mereka di dalamnya ada isteri-isteri yang suci dan mereka kekal di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 26, "text": "۞ إِنَّ ٱللَّهَ لَا یَسۡتَحۡیِۦۤ أَن یَضۡرِبَ مَثَلࣰا مَّا بَعُوضَةࣰ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ فَیَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِینَ كَفَرُوا۟ فَیَقُولُونَ مَاذَاۤ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلࣰاۘ یُضِلُّ بِهِۦ كَثِیرࣰا وَیَهۡدِی بِهِۦ كَثِیرࣰاۚ وَمَا یُضِلُّ بِهِۦۤ إِلَّا ٱلۡفَـٰسِقِینَ ۝٢٦", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "إن الله تعالى لا يستحيي من الحق أن يذكر شيئًا ما، قلَّ أو كثر، ولو كان تمثيلا بأصغر شيء، كالبعوضة والذباب ونحو ذلك، مما ضربه الله مثلا لِعَجْز كل ما يُعْبَد من دون الله. فأما المؤمنون فيعلمون حكمة الله في التمثيل بالصغير والكبير من خلقه، وأما الكفار فَيَسْخرون ويقولون: ما مراد الله مِن ضَرْب المثل بهذه الحشرات الحقيرة؟ ويجيبهم الله بأن المراد هو الاختبار، وتمييز المؤمن من الكافر؛ لذلك يصرف الله بهذا المثل ناسًا كثيرين عن الحق لسخريتهم منه، ويوفق به غيرهم إلى مزيد من الإيمان والهداية. والله تعالى لا يظلم أحدًا؛ لأنه لا يَصْرِف عن الحق إلا الخارجين عن طاعته.", "isBasmala": false, "translation_en": "God does not shy away from making an example of a gnat, or something above it. As for those who believe, they know that it is the Truth from their Lord. But as for those who disbelieve, they say, \"What did God intend by this example?\" He leads astray many thereby, and He guides many thereby; but He misleads thereby only the evildoers.", "translation_id": "Sesungguhnya Allah tiada segan membuat perumpamaan berupa nyamuk atau yang lebih rendah dari itu. Adapun orang-orang yang beriman, maka mereka yakin bahwa perumpamaan itu benar dari Tuhan mereka, tetapi mereka yang kafir mengatakan: \"Apakah maksud Allah menjadikan ini untuk perumpamaan?\". Dengan perumpamaan itu banyak orang yang disesatkan Allah, dan dengan perumpamaan itu (pula) banyak orang yang diberi-Nya petunjuk. Dan tidak ada yang disesatkan Allah kecuali orang-orang yang fasik,", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 27, "text": "ٱلَّذِینَ یَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِیثَـٰقِهِۦ وَیَقۡطَعُونَ مَاۤ أَمَرَ ٱللَّهُ بِهِۦۤ أَن یُوصَلَ وَیُفۡسِدُونَ فِی ٱلۡأَرۡضِۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ ۝٢٧", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "الذين ينكثون عهد الله الذي أخذه عليهم بالتوحيد والطاعة، وقد أكَّده بإرسال الرسل، وإنزال الكتب، ويخالفون دين الله كقطع الأرحام ونشر الفساد في الأرض، أولئك هم الخاسرون في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Those who violate God's covenant after its confirmation, and sever what God has commanded to be joined, and commit evil on earth. These are the losers.", "translation_id": "(yaitu) orang-orang yang melanggar perjanjian Allah sesudah perjanjian itu teguh, dan memutuskan apa yang diperintahkan Allah (kepada mereka) untuk menghubungkannya dan membuat kerusakan di muka bumi. Mereka itulah orang-orang yang rugi.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 28, "text": "كَیۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَ ٰتࣰا فَأَحۡیَـٰكُمۡۖ ثُمَّ یُمِیتُكُمۡ ثُمَّ یُحۡیِیكُمۡ ثُمَّ إِلَیۡهِ تُرۡجَعُونَ ۝٢٨", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "كيف تنكرون -أيُّها المشركون- وحدانية الله تعالى، وتشركون به غيره في العبادة مع البرهان القاطع عليها في أنفسكم؟ فلقد كنتم أمواتًا فأوجدكم ونفخ فيكم الحياة، ثم يميتكم بعد انقضاء آجالكم التي حددها لكم، ثم يعيدكم أحياء يوم البعث، ثم إليه ترجعون للحساب والجزاء.", "isBasmala": false, "translation_en": "How can you deny God, when you were dead and He gave you life, then He will put you to death, then He will bring you to life, then to Him you will be returned?", "translation_id": "Mengapa kamu kafir kepada Allah, padahal kamu tadinya mati, lalu Allah menghidupkan kamu, kemudian kamu dimatikan dan dihidupkan-Nya kembali, kemudian kepada-Nya-lah kamu dikembalikan?", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 29, "text": "هُوَ ٱلَّذِی خَلَقَ لَكُم مَّا فِی ٱلۡأَرۡضِ جَمِیعࣰا ثُمَّ ٱسۡتَوَىٰۤ إِلَى ٱلسَّمَاۤءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَـٰوَ ٰتࣲۚ وَهُوَ بِكُلِّ شَیۡءٍ عَلِیمࣱ ۝٢٩", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "اللهُ وحده الذي خَلَق لأجلكم كل ما في الأرض من النِّعم التي تنتفعون بها، ثم قصد إلى خلق السموات، فسوَّاهنَّ سبع سموات، وهو بكل شيء عليم. فعِلْمُه -سبحانه- محيط بجميع ما خلق.", "isBasmala": false, "translation_en": "It is He who created for you everything on earth, then turned to the heaven, and made them seven heavens. And He is aware of all things.", "translation_id": "Dialah Allah, yang menjadikan segala yang ada di bumi untuk kamu dan Dia berkehendak (menciptakan) langit, lalu dijadikan-Nya tujuh langit. Dan Dia Maha Mengetahui segala sesuatu.", "manzil": 1, "manzil_display": ""}], "6": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 30, "text": "وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰۤىِٕكَةِ إِنِّی جَاعِلࣱ فِی ٱلۡأَرۡضِ خَلِیفَةࣰۖ قَالُوۤا۟ أَتَجۡعَلُ فِیهَا مَن یُفۡسِدُ فِیهَا وَیَسۡفِكُ ٱلدِّمَاۤءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّیۤ أَعۡلَمُ مَا لَا تَعۡلَمُونَ ۝٣٠", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "واذكر -أيها الرسول- للناس حين قال ربك للملائكة: إني جاعل في الأرض قومًا يخلف بعضهم بعضًا لعمارتها. قالت: يا ربَّنا علِّمْنا وأَرْشِدْنا ما الحكمة في خلق هؤلاء، مع أنَّ من شأنهم الإفساد في الأرض واراقة الدماء ظلما وعدوانًا ونحن طوع أمرك، ننزِّهك التنزيه اللائق بحمدك وجلالك، ونمجِّدك بكل صفات الكمال والجلال؟ قال الله لهم: إني أعلم ما لا تعلمون من الحكمة البالغة في خلقهم.", "isBasmala": false, "translation_en": "When your Lord said to the angels, \"I am placing a successor on earth.\" They said, \"Will You place in it someone who will cause corruption in it and shed blood, while we declare Your praises and sanctify You?\" He said, \"I know what you do not know.\"", "translation_id": "Ingatlah ketika Tuhanmu berfirman kepada para Malaikat: \"Sesungguhnya Aku hendak menjadikan seorang khalifah di muka bumi\". Mereka berkata: \"Mengapa Engkau hendak menjadikan (khalifah) di bumi itu orang yang akan membuat kerusakan padanya dan menumpahkan darah, padahal kami senantiasa bertasbih dengan memuji Engkau dan mensucikan Engkau?\" Tuhan berfirman: \"Sesungguhnya Aku mengetahui apa yang tidak kamu ketahui\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 31, "text": "وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَاۤءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَـٰۤىِٕكَةِ فَقَالَ أَنۢبِـُٔونِی بِأَسۡمَاۤءِ هَـٰۤؤُلَاۤءِ إِن كُنتُمۡ صَـٰدِقِینَ ۝٣١", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "وبيانًا لفضل آدم عليه السلام علَّمه الله أسماء الأشياء كلها، ثم عرض مسمياتها على الملائكة قائلا لهم: أخبروني بأسماء هؤلاء الموجودات، إن كنتم صادقين في أنكم أَوْلى بالاستخلاف في الأرض منهم.", "isBasmala": false, "translation_en": "And He taught Adam the names, all of them; then he presented them to the angels, and said, \"Tell Me the names of these, if you are sincere.\"", "translation_id": "Dan Dia mengajarkan kepada Adam nama-nama (benda-benda) seluruhnya, kemudian mengemukakannya kepada para Malaikat lalu berfirman: \"Sebutkanlah kepada-Ku nama benda-benda itu jika kamu mamang benar orang-orang yang benar!\"", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 32, "text": "قَالُوا۟ سُبۡحَـٰنَكَ لَا عِلۡمَ لَنَاۤ إِلَّا مَا عَلَّمۡتَنَاۤۖ إِنَّكَ أَنتَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ ۝٣٢", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "قالت الملائكة: ننزِّهك يا ربَّنا، ليس لنا علم إلا ما علَّمتنا إياه. إنك أنت وحدك العليم بشئون خلقك، الحكيم في تدبيرك.", "isBasmala": false, "translation_en": "They said, \"Glory be to You! We have no knowledge except what You have taught us. It is you who are the Knowledgeable, the Wise.\"", "translation_id": "Mereka menjawab: \"Maha Suci Engkau, tidak ada yang kami ketahui selain dari apa yang telah Engkau ajarkan kepada kami; sesungguhnya Engkaulah Yang Maha Mengetahui lagi Maha Bijaksana\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 33, "text": "قَالَ یَـٰۤـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَاۤىِٕهِمۡۖ فَلَمَّاۤ أَنۢبَأَهُم بِأَسۡمَاۤىِٕهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّیۤ أَعۡلَمُ غَیۡبَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ ۝٣٣", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "قال الله: يا آدم أخبرهم بأسماء هذه الأشياء التي عجَزوا عن معرفتها. فلما أخبرهم آدم بها، قال الله للملائكة: لقد أخبرتكم أني أعلم ما خفي عنكم في السموات والأرض، وأعلم ما تظهرونه وما تخفونه.", "isBasmala": false, "translation_en": "He said, \"O Adam, tell them their names.\" And when he told them their names, He said, \"Did I not tell you that I know the secrets of the heavens and the earth, and that I know what you reveal and what you conceal?\"", "translation_id": "Allah berfirman: \"Hai Adam, beritahukanlah kepada mereka nama-nama benda ini\". Maka setelah diberitahukannya kepada mereka nama-nama benda itu, Allah berfirman: \"Bukankah sudah Ku-katakan kepadamu, bahwa sesungguhnya Aku mengetahui rahasia langit dan bumi dan mengetahui apa yang kamu lahirkan dan apa yang kamu sembunyikan?\"", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 34, "text": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَـٰفِرِینَ ۝٣٤", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "واذكر -أيها الرسول- للناس تكريم الله لآدم حين قال سبحانه للملائكة: اسجدوا لآدم إكرامًا له وإظهارًا لفضله، فأطاعوا جميعًا إلا إبليس امتنع عن السجود تكبرًا وحسدًا، فصار من الجاحدين بالله، العاصين لأمره.", "isBasmala": false, "translation_en": "And We said to the angels, \"Bow down to Adam.\" They bowed down, except for Satan. He refused, was arrogant, and was one of the disbelievers.", "translation_id": "Dan (ingatlah) ketika Kami berfirman kepada para malaikat: \"Sujudlah kamu kepada Adam,\" maka sujudlah mereka kecuali Iblis; ia enggan dan takabur dan adalah ia termasuk golongan orang-orang yang kafir.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 35, "text": "وَقُلۡنَا یَـٰۤـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَیۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِینَ ۝٣٥", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "وقال الله: يا آدم اسكن أنت وزوجك حواء الجنة، وتمتعا بثمارها تمتعًا هنيئًا واسعًا في أي مكان تشاءان فيها، ولا تقربا هذه الشجرة حتى لا تقعا في المعصية، فتصيرا من المتجاوزين أمر الله.", "isBasmala": false, "translation_en": "We said, \"O Adam, inhabit the Garden, you and your spouse, and eat from it freely as you please, but do not approach this tree, lest you become wrongdoers.\"", "translation_id": "Dan Kami berfirman: \"Hai Adam, diamilah oleh kamu dan isterimu surga ini, dan makanlah makanan-makanannya yang banyak lagi baik dimana saja yang kamu sukai, dan janganlah kamu dekati pohon ini, yang menyebabkan kamu termasuk orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 36, "text": "فَأَزَلَّهُمَا ٱلشَّیۡطَـٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِیهِۖ وَقُلۡنَا ٱهۡبِطُوا۟ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ وَلَكُمۡ فِی ٱلۡأَرۡضِ مُسۡتَقَرࣱّ وَمَتَـٰعٌ إِلَىٰ حِینࣲ ۝٣٦", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "فأوقعهما الشيطان في الخطيئة: بأنْ وسوس لهما حتى أكلا من الشجرة، فتسبب في إخراجهما من الجنة ونعيمها. وقال الله لهم: اهبطوا إلى الأرض، يعادي بعضكم بعضًا -أي آدم وحواء والشيطان- ولكم في الأرض استقرار وإقامة، وانتفاع بما فيها إلى وقت انتهاء آجالكم.", "isBasmala": false, "translation_en": "But Satan caused them to slip from it, and caused them to depart the state they were in. We said, \"Go down, some of you enemies of one another. And you will have residence on earth, and enjoyment for a while.\"", "translation_id": "Lalu keduanya digelincirkan oleh syaitan dari surga itu dan dikeluarkan dari keadaan semula dan Kami berfirman: \"Turunlah kamu! sebagian kamu menjadi musuh bagi yang lain, dan bagi kamu ada tempat kediaman di bumi, dan kesenangan hidup sampai waktu yang ditentukan\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 37, "text": "فَتَلَقَّىٰۤ ءَادَمُ مِن رَّبِّهِۦ كَلِمَـٰتࣲ فَتَابَ عَلَیۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِیمُ ۝٣٧", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "فتلقى آدمُ بالقبول كلماتٍ، ألهمه الله إياها توبة واستغفارًا، وهي قوله تعالى: {رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ (7:23)} فتاب الله عليه، وغفر له ذنبه إنه تعالى هو التواب لمن تاب مِن عباده، الرحيم بهم.", "isBasmala": false, "translation_en": "Then Adam received words from his Lord, so He relented towards him. He is the Relenting, the Merciful.", "translation_id": "Kemudian Adam menerima beberapa kalimat dari Tuhannya, maka Allah menerima taubatnya. Sesungguhnya Allah Maha Penerima taubat lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}], "7": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 38, "text": "قُلۡنَا ٱهۡبِطُوا۟ مِنۡهَا جَمِیعࣰاۖ فَإِمَّا یَأۡتِیَنَّكُم مِّنِّی هُدࣰى فَمَن تَبِعَ هُدَایَ فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝٣٨", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "قال الله لهم: اهبطوا من الجنة جميعًا، وسيأتيكم أنتم وذرياتكم المتعاقبة ما فيه هدايتكم إلى الحق. فمن عمل بها فلا خوف عليهم فيما يستقبلونه من أمر الآخرة ولا هم يحزنون على ما فاتهم من أمور الدنيا.", "isBasmala": false, "translation_en": "We said, \"Go down from it, all of you. Yet whenever guidance comes to you from Me, then whoever follows My guidance-they have nothing to fear, nor shall they grieve.", "translation_id": "Kami berfirman: \"Turunlah kamu semuanya dari surga itu! Kemudian jika datang petunjuk-Ku kepadamu, maka barang siapa yang mengikuti petunjuk-Ku, niscaya tidak ada kekhawatiran atas mereka, dan tidak (pula) mereka bersedih hati\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 39, "text": "وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٣٩", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "والذين جحدوا وكذبوا بآياتنا المتلوة ودلائل توحيدنا، أولئك الذين يلازمون النار، هم فيها خالدون، لا يخرجون منها.", "isBasmala": false, "translation_en": "But as for those who disbelieve and reject Our signs-these are the inmates of the Fire-wherein they will remain forever.\"", "translation_id": "Adapun orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itu penghuni neraka; mereka kekal di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 40, "text": "یَـٰبَنِیۤ إِسۡرَ ٰۤءِیلَ ٱذۡكُرُوا۟ نِعۡمَتِیَ ٱلَّتِیۤ أَنۡعَمۡتُ عَلَیۡكُمۡ وَأَوۡفُوا۟ بِعَهۡدِیۤ أُوفِ بِعَهۡدِكُمۡ وَإِیَّـٰیَ فَٱرۡهَبُونِ ۝٤٠", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "يا ذرية يعقوب اذكروا نعمي الكثيرة عليكم، واشكروا لي، وأتموا وصيتي لكم: بأن تؤمنوا بكتبي ورسلي جميعًا، وتعملوا بشرائعي. فإن فعلتم ذلك أُتمم لكم ما وعدتكم به من الرحمة في الدنيا، والنجاة في الآخرة. وإيَّايَ -وحدي- فخافوني، واحذروا نقمتي إن نقضتم العهد، وكفرتم بي.", "isBasmala": false, "translation_en": "O Children of Israel! Remember My blessings which I bestowed upon you, and fulfill your pledge to Me, and I will fulfill My pledge to you, and fear Me.", "translation_id": "Hai Bani Israil, ingatlah akan nikmat-Ku yang telah Aku anugerahkan kepadamu, dan penuhilah janjimu kepada-Ku, niscaya Aku penuhi janji-Ku kepadamu; dan hanya kepada-Ku-lah kamu harus takut (tunduk).", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 41, "text": "وَءَامِنُوا۟ بِمَاۤ أَنزَلۡتُ مُصَدِّقࣰا لِّمَا مَعَكُمۡ وَلَا تَكُونُوۤا۟ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُوا۟ بِـَٔایَـٰتِی ثَمَنࣰا قَلِیلࣰا وَإِیَّـٰیَ فَٱتَّقُونِ ۝٤١", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "وآمنوا- يا بني إسرائيل- بالقرآن الذي أنزَلْتُه على محمد نبي الله ورسوله، موافقًا لما تعلمونه من صحيح التوراة، ولا تكونوا أول فريق من أهل الكتاب يكفر به، ولا تستبدلوا بآياتي ثمنًا قليلا من حطام الدنيا الزائل، وإياي وحدي فاعملوا بطاعتي واتركوا معصيتي.", "isBasmala": false, "translation_en": "And believe in what I revealed, confirming what is with you; and do not be the first to deny it; and do not exchange My revelations for a small price; and be conscious of Me.", "translation_id": "Dan berimanlah kamu kepada apa yang telah Aku turunkan (Al Quran) yang membenarkan apa yang ada padamu (Taurat), dan janganlah kamu menjadi orang yang pertama kafir kepadanya, dan janganlah kamu menukarkan ayat-ayat-Ku dengan harga yang rendah, dan hanya kepada Akulah kamu harus bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 42, "text": "وَلَا تَلۡبِسُوا۟ ٱلۡحَقَّ بِٱلۡبَـٰطِلِ وَتَكۡتُمُوا۟ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ ۝٤٢", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "ولا تخلِطوا الحق الذي بيَّنته لكم بالباطل الذي افتريتموه، واحذروا كتمان الحق الصريح من صفة نبي الله ورسوله محمد صلى الله عليه وسلم التي في كتبكم، وأنتم تجدونها مكتوبة عندكم، فيما تعلمون من الكتب التي بأيديكم.", "isBasmala": false, "translation_en": "And do not mix truth with falsehood, and do not conceal the truth while you know.", "translation_id": "Dan janganlah kamu campur adukkan yang hak dengan yang bathil dan janganlah kamu sembunyikan yang hak itu, sedang kamu mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 43, "text": "وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرۡكَعُوا۟ مَعَ ٱلرَّ ٰكِعِینَ ۝٤٣", "juz": 1, "hizb": "(*¼ ح 1*)", "tafsir": "وادخلوا في دين الإسلام: بأن تقيموا الصلاة على الوجه الصحيح، كما جاء بها نبي الله ورسوله محمد صلى الله عليه وسلم، وتؤدوا الزكاة المفروضة على الوجه المشروع، وتكونوا مع الراكعين من أمته صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "And attend to your prayers, and practice regular charity, and kneel with those who kneel.", "translation_id": "Dan dirikanlah shalat, tunaikanlah zakat dan ruku'lah beserta orang-orang yang ruku'.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 44, "text": "۞ أَتَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبِرِّ وَتَنسَوۡنَ أَنفُسَكُمۡ وَأَنتُمۡ تَتۡلُونَ ٱلۡكِتَـٰبَۚ أَفَلَا تَعۡقِلُونَ ۝٤٤", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "ما أقبح حالَكم وحالَ علمائكم حين تأمرون الناس بعمل الخيرات، وتتركون أنفسكم، فلا تأمرونها بالخير العظيم، وهو الإسلام، وأنتم تقرءون التوراة، التي فيها صفات محمد صلى الله عليه وسلم، ووجوب الإيمان به!! أفلا تستعملون عقولكم استعمالا صحيحًا؟", "isBasmala": false, "translation_en": "Do you command people to virtuous conduct, and forget yourselves, even though you read the Scripture? Do you not understand?", "translation_id": "Mengapa kamu suruh orang lain (mengerjakan) kebaktian, sedang kamu melupakan diri (kewajiban)mu sendiri, padahal kamu membaca Al Kitab (Taurat)? Maka tidaklah kamu berpikir?", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 45, "text": "وَٱسۡتَعِینُوا۟ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِیرَةٌ إِلَّا عَلَى ٱلۡخَـٰشِعِینَ ۝٤٥", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "واستعينوا في كل أموركم بالصبر بجميع أنواعه، وكذلك الصلاة. وإنها لشاقة إلا على الخاشعين.", "isBasmala": false, "translation_en": "And seek help through patience and prayer. But it is difficult, except for the devout.", "translation_id": "Jadikanlah sabar dan shalat sebagai penolongmu. Dan sesungguhnya yang demikian itu sungguh berat, kecuali bagi orang-orang yang khusyu',", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 46, "text": "ٱلَّذِینَ یَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ رَبِّهِمۡ وَأَنَّهُمۡ إِلَیۡهِ رَ ٰجِعُونَ ۝٤٦", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "الذين يخشون الله ويرجون ما عنده، ويوقنون أنهم ملاقو ربِّهم جلَّ وعلا بعد الموت، وأنهم إليه راجعون يوم القيامة للحساب والجزاء.", "isBasmala": false, "translation_en": "Those who know that they will meet their Lord, and that to Him they will return.", "translation_id": "(yaitu) orang-orang yang meyakini, bahwa mereka akan menemui Tuhannya, dan bahwa mereka akan kembali kepada-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 47, "text": "یَـٰبَنِیۤ إِسۡرَ ٰۤءِیلَ ٱذۡكُرُوا۟ نِعۡمَتِیَ ٱلَّتِیۤ أَنۡعَمۡتُ عَلَیۡكُمۡ وَأَنِّی فَضَّلۡتُكُمۡ عَلَى ٱلۡعَـٰلَمِینَ ۝٤٧", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "يا ذرية يعقوب تذكَّروا نعمي الكثيرة عليكم، واشكروا لي عليها، وتذكروا أني فَضَّلْتكم على عالَمي زمانكم بكثرة الأنبياء، والكتب المنزَّلة كالتوراة والإنجيل.", "isBasmala": false, "translation_en": "O Children of Israel! Remember My favor which I bestowed upon you, and I that favored you over all nations.", "translation_id": "Hai Bani Israil, ingatlah akan nikmat-Ku yang telah Aku anugerahkan kepadamu dan (ingatlah pula) bahwasanya Aku telah melebihkan kamu atas segala umat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 48, "text": "وَٱتَّقُوا۟ یَوۡمࣰا لَّا تَجۡزِی نَفۡسٌ عَن نَّفۡسࣲ شَیۡـࣰٔا وَلَا یُقۡبَلُ مِنۡهَا شَفَـٰعَةࣱ وَلَا یُؤۡخَذُ مِنۡهَا عَدۡلࣱ وَلَا هُمۡ یُنصَرُونَ ۝٤٨", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "وخافوا يوم القيامة، يوم لا يغني أحد عن أحد شيئًا، ولا يقبل الله شفاعة في الكافرين، ولا يقبل منهم فدية، ولو كانت أموال الأرض جميعًا، ولا يملك أحد في هذا اليوم أن يتقدم لنصرتهم وإنقاذهم من العذاب.", "isBasmala": false, "translation_en": "And beware of a Day when no soul will avail another in the least, nor will any intercession be accepted on its behalf, nor will any ransom be taken from it, nor will they be helped.", "translation_id": "Dan jagalah dirimu dari (azab) hari (kiamat, yang pada hari itu) seseorang tidak dapat membela orang lain, walau sedikitpun; dan (begitu pula) tidak diterima syafa'at dan tebusan dari padanya, dan tidaklah mereka akan ditolong.", "manzil": 1, "manzil_display": ""}], "8": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 49, "text": "وَإِذۡ نَجَّیۡنَـٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ یَسُومُونَكُمۡ سُوۤءَ ٱلۡعَذَابِ یُذَبِّحُونَ أَبۡنَاۤءَكُمۡ وَیَسۡتَحۡیُونَ نِسَاۤءَكُمۡۚ وَفِی ذَ ٰلِكُم بَلَاۤءࣱ مِّن رَّبِّكُمۡ عَظِیمࣱ ۝٤٩", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "واذكروا نعمتنا عليكم حين أنقذناكم من بطش فرعون وأتباعه، وهم يُذيقونكم أشدَّ العذاب، فيُكثِرون مِن ذَبْح أبنائكم، وترك بناتكم للخدمة والامتهان. وفي ذلك اختبار لكم من ربكم، وفي إنجائكم منه نعمة عظيمة، تستوجب شكر الله تعالى في كل عصوركم وأجيالكم.", "isBasmala": false, "translation_en": "And recall that We delivered you from the people of Pharaoh. They inflicted on you terrible persecution, killing your sons and sparing your women. Therein was a tremendous trial from your Lord.", "translation_id": "Dan (ingatlah) ketika Kami selamatkan kamu dari (Fir'aun) dan pengikut-pengikutnya; mereka menimpakan kepadamu siksaan yang seberat-beratnya, mereka menyembelih anak-anakmu yang laki-laki dan membiarkan hidup anak-anakmu yang perempuan. Dan pada yang demikian itu terdapat cobaan-cobaan yang besar dari Tuhanmu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 50, "text": "وَإِذۡ فَرَقۡنَا بِكُمُ ٱلۡبَحۡرَ فَأَنجَیۡنَـٰكُمۡ وَأَغۡرَقۡنَاۤ ءَالَ فِرۡعَوۡنَ وَأَنتُمۡ تَنظُرُونَ ۝٥٠", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "واذكروا نعمتنا عليكم، حين فَصَلْنا بسببكم البحر، وجعلنا فيه طرقًا يابسةً، فعبرتم، وأنقذناكم من فرعون وجنوده، ومن الهلاك في الماء. فلما دخل فرعون وجنوده طرقكم أهلكناهم في الماء أمام أعينكم.", "isBasmala": false, "translation_en": "And recall that We parted the sea for you, so We saved you, and We drowned the people of Pharaoh as you looked on.", "translation_id": "Dan (ingatlah), ketika Kami belah laut untukmu, lalu Kami selamatkan kamu dan Kami tenggelamkan (Fir'aun) dan pengikut-pengikutnya sedang kamu sendiri menyaksikan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 51, "text": "وَإِذۡ وَ ٰعَدۡنَا مُوسَىٰۤ أَرۡبَعِینَ لَیۡلَةࣰ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَـٰلِمُونَ ۝٥١", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "واذكروا نعمتنا عليكم: حين واعدنا موسى أربعين ليلة لإنزال التوراة هدايةً ونورًا لكم، فإذا بكم تنتهزون فرصة غيابه هذه المدة القليلة، وتجعلون العجل الذي صنعتموه بأيديكم معبودًا لكم من دون الله - وهذا أشنع الكفر بالله- وأنتم ظالمون باتخاذكم العجل إلهًا.", "isBasmala": false, "translation_en": "And recall that We appointed for Moses forty nights. Then you took to worshiping the calf after him, and you turned wicked.", "translation_id": "Dan (ingatlah), ketika Kami berjanji kepada Musa (memberikan Taurat, sesudah) empat puluh malam, lalu kamu menjadikan anak lembu (sembahan) sepeninggalnya dan kamu adalah orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 52, "text": "ثُمَّ عَفَوۡنَا عَنكُم مِّنۢ بَعۡدِ ذَ ٰلِكَ لَعَلَّكُمۡ تَشۡكُرُونَ ۝٥٢", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "ثمَّ تجاوزنا عن هذه الفعلة المنكرة، وقَبِلْنَا توبتكم بعد عودة موسى؛ رجاءَ أن تشكروا الله على نعمه وأفضاله، ولا تتمادوا في الكفر والطغيان.", "isBasmala": false, "translation_en": "Then We pardoned you after that, so that you might be grateful.", "translation_id": "Kemudian sesudah itu Kami maafkan kesalahanmu, agar kamu bersyukur.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 53, "text": "وَإِذۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ ۝٥٣", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "واذكروا نعمتنا عليكم حين أعطينا موسى الكتاب الفارق بين الحق والباطل -وهو التوراة-؛ لكي تهتدوا من الضلالة.", "isBasmala": false, "translation_en": "And recall that We gave Moses the Scripture and the Criterion, so that you may be guided.", "translation_id": "Dan (ingatlah), ketika Kami berikan kepada Musa Al Kitab (Taurat) dan keterangan yang membedakan antara yang benar dan yang salah, agar kamu mendapat petunjuk.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 54, "text": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ یَـٰقَوۡمِ إِنَّكُمۡ ظَلَمۡتُمۡ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلۡعِجۡلَ فَتُوبُوۤا۟ إِلَىٰ بَارِىِٕكُمۡ فَٱقۡتُلُوۤا۟ أَنفُسَكُمۡ ذَ ٰلِكُمۡ خَیۡرࣱ لَّكُمۡ عِندَ بَارِىِٕكُمۡ فَتَابَ عَلَیۡكُمۡۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِیمُ ۝٥٤", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "واذكروا نعمتنا عليكم حين قال موسى لقومه: إنكم ظلمتم أنفسكم باتخاذكم العجل إلهًا، فتوبوا إلى خالقكم: بأن يَقْتل بعضكم بعضًا، وهذا خير لكم عند خالقكم من الخلود الأبدي في النار، فامتثلتم ذلك، فمنَّ الله عليكم بقَبول توبتكم. إنه تعالى هو التواب لمن تاب مِن عباده، الرحيم بهم.", "isBasmala": false, "translation_en": "And recall that Moses said to his people, \"O my people, you have done wrong to yourselves by worshiping the calf. So repent to your Maker, and kill your egos. That would be better for you with your Maker.\" So He turned to you in repentance. He is the Accepter of Repentance, the Merciful.", "translation_id": "Dan (ingatlah), ketika Musa berkata kepada kaumnya: \"Hai kaumku, sesungguhnya kamu telah menganiaya dirimu sendiri karena kamu telah menjadikan anak lembu (sembahanmu), maka bertaubatlah kepada Tuhan yang menjadikan kamu dan bunuhlah dirimu. Hal itu adalah lebih baik bagimu pada sisi Tuhan yang menjadikan kamu; maka Allah akan menerima taubatmu. Sesungguhnya Dialah Yang Maha Penerima taubat lagi Maha Penyayang\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 55, "text": "وَإِذۡ قُلۡتُمۡ یَـٰمُوسَىٰ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهۡرَةࣰ فَأَخَذَتۡكُمُ ٱلصَّـٰعِقَةُ وَأَنتُمۡ تَنظُرُونَ ۝٥٥", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "واذكروا إذ قلتم: يا موسى لن نصدقك في أن الكلام الذي نسمعه منك هو كلام الله، حتى نرى الله عِيَانًا، فنزلت نار من السماء رأيتموها بأعينكم، فقَتَلَتْكم بسبب ذنوبكم، وجُرْأتكم على الله تعالى.", "isBasmala": false, "translation_en": "And recall that you said, \"O Moses, we will not believe in you unless we see God plainly.\" Thereupon the thunderbolt struck you, as you looked on.", "translation_id": "Dan (ingatlah), ketika kamu berkata: \"Hai Musa, kami tidak akan beriman kepadamu sebelum kami melihat Allah dengan terang, karena itu kamu disambar halilintar, sedang kamu menyaksikannya\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 56, "text": "ثُمَّ بَعَثۡنَـٰكُم مِّنۢ بَعۡدِ مَوۡتِكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ ۝٥٦", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "ثم أحييناكم مِن بعد موتكم بالصاعقة؛ لتشكروا نعمة الله عليكم، فهذا الموت عقوبة لهم، ثم بعثهم الله لاستيفاء آجالهم.", "isBasmala": false, "translation_en": "Then We revived you after your death, so that you may be appreciative.", "translation_id": "Setelah itu Kami bangkitkan kamu sesudah kamu mati, supaya kamu bersyukur.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 57, "text": "وَظَلَّلۡنَا عَلَیۡكُمُ ٱلۡغَمَامَ وَأَنزَلۡنَا عَلَیۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُوا۟ مِن طَیِّبَـٰتِ مَا رَزَقۡنَـٰكُمۡۚ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ ۝٥٧", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "واذكروا نعمتنا عليكم حين كنتم تتيهون في الأرض؛ إذ جعلنا السحاب مظللا عليكم من حَرِّ الشمس، وأنزلنا عليكم المنَّ، وهو شيء يشبه الصَّمغ طعمه كالعسل، وأنزلنا عليكم السَّلوى وهو طير يشبه السُّمانَى، وقلنا لكم: كلوا من طيِّبات ما رزقناكم، ولا تخالفوا دينكم، فلم تمتثلوا. وما ظلمونا بكفران النعم، ولكن كانوا أنفسهم يظلمون؛ لأن عاقبة الظلم عائدة عليهم.", "isBasmala": false, "translation_en": "And We shaded you with clouds, and We sent down to you manna and quails: \"Eat of the good things We have provided for you.\" They did not wrong Us, but they used to wrong their own souls.", "translation_id": "Dan Kami naungi kamu dengan awan, dan Kami turunkan kepadamu \"manna\" dan \"salwa\". Makanlah dari makanan yang baik-baik yang telah Kami berikan kepadamu; dan tidaklah mereka menganiaya Kami; akan tetapi merekalah yang menganiaya diri mereka sendiri.", "manzil": 1, "manzil_display": ""}], "9": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 58, "text": "وَإِذۡ قُلۡنَا ٱدۡخُلُوا۟ هَـٰذِهِ ٱلۡقَرۡیَةَ فَكُلُوا۟ مِنۡهَا حَیۡثُ شِئۡتُمۡ رَغَدࣰا وَٱدۡخُلُوا۟ ٱلۡبَابَ سُجَّدࣰا وَقُولُوا۟ حِطَّةࣱ نَّغۡفِرۡ لَكُمۡ خَطَـٰیَـٰكُمۡۚ وَسَنَزِیدُ ٱلۡمُحۡسِنِینَ ۝٥٨", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "واذكروا نعمتنا عليكم حين قلنا: ادخلوا مدينة \"بيت المقدس\" فكلوا من طيباتها في أي مكان منها أكلا هنيئًا، وكونوا في دخولكم خاضعين لله، ذليلين له، وقولوا: ربَّنا ضَعْ عنَّا ذنوبنا، نستجب لكم ونعف ونسترها عليكم، وسنزيد المحسنين بأعمالهم خيرًا وثوابًا.", "isBasmala": false, "translation_en": "And recall that We said, \"Enter this town, and eat plentifully from it whatever you wish; but enter the gate humbly, and say, 'Pardon.' We will forgive your sins, and give increase to the virtuous.\"", "translation_id": "Dan (ingatlah), ketika Kami berfirman: \"Masuklah kamu ke negeri ini (Baitul Maqdis), dan makanlah dari hasil buminya, yang banyak lagi enak dimana yang kamu sukai, dan masukilah pintu gerbangnya sambil bersujud, dan katakanlah: \"Bebaskanlah kami dari dosa\", niscaya Kami ampuni kesalahan-kesalahanmu, dan kelak Kami akan menambah (pemberian Kami) kepada orang-orang yang berbuat baik\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 59, "text": "فَبَدَّلَ ٱلَّذِینَ ظَلَمُوا۟ قَوۡلًا غَیۡرَ ٱلَّذِی قِیلَ لَهُمۡ فَأَنزَلۡنَا عَلَى ٱلَّذِینَ ظَلَمُوا۟ رِجۡزࣰا مِّنَ ٱلسَّمَاۤءِ بِمَا كَانُوا۟ یَفۡسُقُونَ ۝٥٩", "juz": 1, "hizb": "(*½ ح 1*)", "tafsir": "فبدَّل الجائرون الضالون من بني إسرائيل قول الله، وحرَّفوا القول والفعل جميعًا، إذ دخلوا يزحفون على أستاههم وقالوا: حبة في شعرة، واستهزءوا بدين الله. فأنزل الله عليهم عذابًا من السماء؛ بسبب تمردهم وخروجهم عن طاعة الله.", "isBasmala": false, "translation_en": "But the wrongdoers among them substituted words other than those given to them, so We sent down on the wrongdoers a plague from heaven, because of their wicked behavior.", "translation_id": "Lalu orang-orang yang zalim mengganti perintah dengan (mengerjakan) yang tidak diperintahkan kepada mereka. Sebab itu Kami timpakan atas orang-orang yang zalim itu dari langit, karena mereka berbuat fasik.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 60, "text": "۞ وَإِذِ ٱسۡتَسۡقَىٰ مُوسَىٰ لِقَوۡمِهِۦ فَقُلۡنَا ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنفَجَرَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَیۡنࣰاۖ قَدۡ عَلِمَ كُلُّ أُنَاسࣲ مَّشۡرَبَهُمۡۖ كُلُوا۟ وَٱشۡرَبُوا۟ مِن رِّزۡقِ ٱللَّهِ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ ۝٦٠", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "واذكروا نعمتنا عليكم -وأنتم عطاش في التِّيْه- حين دعانا موسى -بضراعة- أن نسقي قومه، فقلنا: اضرب بعصاك الحجر، فضرب، فانفجرت منه اثنتا عشرة عينًا، بعدد القبائل، مع إعلام كل قبيلة بالعين الخاصة بها حتى لا يتنازعوا. وقلنا لهم: كلوا واشربوا من رزق الله، ولا تسعوا في الأرض مفسدين.", "isBasmala": false, "translation_en": "And recall when Moses prayed for water for his people. We said, \"Strike the rock with your staff.\" Thereupon twelve springs gushed out from it, and each tribe recognized its drinking-place. \"Eat and drink from God's provision, and do not corrupt the earth with disobedience.\"", "translation_id": "Dan (ingatlah) ketika Musa memohon air untuk kaumnya, lalu Kami berfirman: \"Pukullah batu itu dengan tongkatmu\". Lalu memancarlah daripadanya dua belas mata air. Sungguh tiap-tiap suku telah mengetahui tempat minumnya (masing-masing). Makan dan minumlah rezeki (yang diberikan) Allah, dan janganlah kamu berkeliaran di muka bumi dengan berbuat kerusakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 61, "text": "وَإِذۡ قُلۡتُمۡ یَـٰمُوسَىٰ لَن نَّصۡبِرَ عَلَىٰ طَعَامࣲ وَ ٰحِدࣲ فَٱدۡعُ لَنَا رَبَّكَ یُخۡرِجۡ لَنَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ مِنۢ بَقۡلِهَا وَقِثَّاۤىِٕهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَاۖ قَالَ أَتَسۡتَبۡدِلُونَ ٱلَّذِی هُوَ أَدۡنَىٰ بِٱلَّذِی هُوَ خَیۡرٌۚ ٱهۡبِطُوا۟ مِصۡرࣰا فَإِنَّ لَكُم مَّا سَأَلۡتُمۡۗ وَضُرِبَتۡ عَلَیۡهِمُ ٱلذِّلَّةُ وَٱلۡمَسۡكَنَةُ وَبَاۤءُو بِغَضَبࣲ مِّنَ ٱللَّهِۗ ذَ ٰلِكَ بِأَنَّهُمۡ كَانُوا۟ یَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَیَقۡتُلُونَ ٱلنَّبِیِّـۧنَ بِغَیۡرِ ٱلۡحَقِّۗ ذَ ٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ یَعۡتَدُونَ ۝٦١", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "واذكروا حين أنزلنا عليكم الطعام الحلو، والطير الشهي، فبطِرتم النعمة كعادتكم، وأصابكم الضيق والملل، فقلتم: يا موسى لن نصبر على طعام ثابت لا يتغير مع الأيام، فادع لنا ربك يخرج لنا من نبات الأرض طعامًا من البقول والخُضَر، والقثاء والحبوب التي تؤكل، والعدس، والبصل. قال موسى -مستنكرًا عليهم-: أتطلبون هذه الأطعمة التي هي أقل قدرًا، وتتركون هذا الرزق النافع الذي اختاره الله لكم؟ اهبطوا من هذه البادية إلى أي مدينة، تجدوا ما اشتهيتم كثيرًا في الحقول والأسواق. ولما هبطوا تبيَّن لهم أنهم يُقَدِّمون اختيارهم -في كل موطن- على اختيار الله، ويُؤْثِرون شهواتهم على ما اختاره الله لهم؛ لذلك لزمتهم صِفَةُ الذل وفقر النفوس، وانصرفوا ورجعوا بغضب من الله؛ لإعراضهم عن دين الله، ولأنهم كانوا يكفرون بآيات الله ويقتلون النبيين ظلمًا وعدوانًا؛ وذلك بسبب عصيانهم وتجاوزهم حدود ربهم.", "isBasmala": false, "translation_en": "And recall when you said, \"O Moses, we cannot endure one kind of food, so call to your Lord to produce for us of what the earth grows: of its herbs, and its cucumbers, and its garlic, and its lentils, and its onions.\" He said, \"Would you substitute worse for better? Go down to Egypt, where you will have what you asked for.\" They were struck with humiliation and poverty, and incurred wrath from God. That was because they rejected God's revelations and wrongfully killed the prophets. That was because they disobeyed and transgressed.", "translation_id": "Dan (ingatlah), ketika kamu berkata: \"Hai Musa, kami tidak bisa sabar (tahan) dengan satu macam makanan saja. Sebab itu mohonkanlah untuk kami kepada Tuhanmu, agar Dia mengeluarkan bagi kami dari apa yang ditumbuhkan bumi, yaitu sayur-mayurnya, ketimunnya, bawang putihnya, kacang adasnya, dan bawang merahnya\". Musa berkata: \"Maukah kamu mengambil yang rendah sebagai pengganti yang lebih baik? Pergilah kamu ke suatu kota, pasti kamu memperoleh apa yang kamu minta\". Lalu ditimpahkanlah kepada mereka nista dan kehinaan, serta mereka mendapat kemurkaan dari Allah. Hal itu (terjadi) karena mereka selalu mengingkari ayat-ayat Allah dan membunuh para Nabi yang memang tidak dibenarkan. Demikian itu (terjadi) karena mereka selalu berbuat durhaka dan melampaui batas.", "manzil": 1, "manzil_display": ""}], "10": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 62, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَٱلَّذِینَ هَادُوا۟ وَٱلنَّصَـٰرَىٰ وَٱلصَّـٰبِـِٔینَ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَعَمِلَ صَـٰلِحࣰا فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝٦٢", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "إن المؤمنين من هذه الأمة، الذين صدَّقوا بالله ورسله، وعملوا بشرعه، والذين كانوا قبل بعثة محمد صلى الله عليه وسلم من الأمم السالفة من اليهود، والنصارى، والصابئين- وهم قوم باقون على فطرتهم، ولا دين مقرر لهم يتبعونه- هؤلاء جميعًا إذا صدَّقوا بالله تصديقًا صحيحًا خالصًا، وبيوم البعث والجزاء، وعملوا عملا مرضيًا عند الله، فثوابهم ثابت لهم عند ربهم، ولا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على ما فاتهم من أمور الدنيا. وأما بعد بعثة محمد صلى الله عليه وسلم خاتمًا للنبيين والمرسلين إلى الناس كافة، فلا يقبل الله من أحد دينًا غير ما جاء به، وهو الإسلام.", "isBasmala": false, "translation_en": "Those who believe, and those who are Jewish, and the Christians, and the Sabeans-any who believe in God and the Last Day, and act righteously-will have their reward with their Lord; they have nothing to fear, nor will they grieve.", "translation_id": "Sesungguhnya orang-orang mukmin, orang-orang Yahudi, orang-orang Nasrani dan orang-orang Shabiin, siapa saja diantara mereka yang benar-benar beriman kepada Allah, hari kemudian dan beramal saleh, mereka akan menerima pahala dari Tuhan mereka, tidak ada kekhawatiran kepada mereka, dan tidak (pula) mereka bersedih hati.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 63, "text": "وَإِذۡ أَخَذۡنَا مِیثَـٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُوا۟ مَاۤ ءَاتَیۡنَـٰكُم بِقُوَّةࣲ وَٱذۡكُرُوا۟ مَا فِیهِ لَعَلَّكُمۡ تَتَّقُونَ ۝٦٣", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "واذكروا -يا بني إسرائيل- حين أَخَذْنا العهد المؤكَّد منكم بالإيمان بالله وإفراده بالعبادة، ورفعنا جبل الطور فوقكم، وقلنا لكم: خذوا الكتاب الذي أعطيناكم بجدٍ واجتهاد واحفظوه، وإلا أطبقنا عليكم الجبل، ولا تنسوا التوراة قولا وعملا كي تتقوني وتخافوا عقابي.", "isBasmala": false, "translation_en": "And recall when We received a pledge from you, and raised the Mount above you: \"Take what We have given you earnestly, and remember what is in it, that you may attain righteousness.\"", "translation_id": "Dan (ingatlah), ketika Kami mengambil janji dari kamu dan Kami angkatkan gunung (Thursina) di atasmu (seraya Kami berfirman): \"Peganglah teguh-teguh apa yang Kami berikan kepadamu dan ingatlah selalu apa yang ada didalamnya, agar kamu bertakwa\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 64, "text": "ثُمَّ تَوَلَّیۡتُم مِّنۢ بَعۡدِ ذَ ٰلِكَۖ فَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ لَكُنتُم مِّنَ ٱلۡخَـٰسِرِینَ ۝٦٤", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "ثم خالفتم وعصيتم مرة أخرى، بعد أَخْذِ الميثاق ورَفْع الجبل كشأنكم دائمًا. فلولا فَضْلُ الله عليكم ورحمته بالتوبة، والتجاوز عن خطاياكم، لصرتم من الخاسرين في الدنيا والآخرة.", "isBasmala": false, "translation_en": "But after that you turned away. Were it not for God's grace and mercy towards you, you would have been among the losers.", "translation_id": "Kemudian kamu berpaling setelah (adanya perjanjian) itu, maka kalau tidak ada karunia Allah dan rahmat-Nya atasmu, niscaya kamu tergolong orang yang rugi.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 65, "text": "وَلَقَدۡ عَلِمۡتُمُ ٱلَّذِینَ ٱعۡتَدَوۡا۟ مِنكُمۡ فِی ٱلسَّبۡتِ فَقُلۡنَا لَهُمۡ كُونُوا۟ قِرَدَةً خَـٰسِـِٔینَ ۝٦٥", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "ولقد علمتم -يا معشر اليهود- ما حلَّ من البأس بأسلافكم من أهل القرية التي عصت الله، فيما أخذه عليهم من تعظيم السبت، فاحتالوا لاصطياد السمك في يوم السبت، بوضع الشِّباك وحفر البِرَك، ثم اصطادوا السمك يوم الأحد حيلة إلى المحرم، فلما فعلوا ذلك، مسخهم الله قردة منبوذين.", "isBasmala": false, "translation_en": "And you surely knew those of you who violated the Sabbath. We said to them, \"Be despicable apes!\"", "translation_id": "Dan sesungguhnya telah kamu ketahui orang-orang yang melanggar diantaramu pada hari Sabtu, lalu Kami berfirman kepada mereka: \"Jadilah kamu kera yang hina\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 66, "text": "فَجَعَلۡنَـٰهَا نَكَـٰلࣰا لِّمَا بَیۡنَ یَدَیۡهَا وَمَا خَلۡفَهَا وَمَوۡعِظَةࣰ لِّلۡمُتَّقِینَ ۝٦٦", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "فجعلنا هذه القرية عبرة لمن بحضرتها من القرى، يبلغهم خبرها وما حلَّ بها، وعبرة لمن يعمل بعدها مثل تلك الذُّنوب، وجعلناها تذكرة للصالحين؛ ليعلموا أنهم على الحق، فيثبتوا عليه.", "isBasmala": false, "translation_en": "Thus We made it a deterrent for their generation, and for subsequent generations, and a lesson for the righteous.", "translation_id": "Maka Kami jadikan yang demikian itu peringatan bagi orang-orang dimasa itu, dan bagi mereka yang datang kemudian, serta menjadi pelajaran bagi orang-orang yang bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 67, "text": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦۤ إِنَّ ٱللَّهَ یَأۡمُرُكُمۡ أَن تَذۡبَحُوا۟ بَقَرَةࣰۖ قَالُوۤا۟ أَتَتَّخِذُنَا هُزُوࣰاۖ قَالَ أَعُوذُ بِٱللَّهِ أَنۡ أَكُونَ مِنَ ٱلۡجَـٰهِلِینَ ۝٦٧", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "واذكروا يا بني إسرائيل جناية أسلافكم، وكثرة تعنتهم وجدالهم لموسى عليه الصلاة والسلام، حين قال لهم: إن الله يأمركم أن تذبحوا بقرة، فقالوا -مستكبرين-: أتجعلنا موضعًا للسخرية والاستخفاف؟ فردَّ عليهم موسى بقوله: أستجير بالله أن أكون من المستهزئين.", "isBasmala": false, "translation_en": "And recall when Moses said to his people, \"God commands you to sacrifice a heifer.\" They said, \"Do you make a mockery of us?\" He said, \"God forbid that I should be so ignorant.\"", "translation_id": "Dan (ingatlah), ketika Musa berkata kepada kaumnya: \"Sesungguhnya Allah menyuruh kamu menyembelih seekor sapi betina\". Mereka berkata: \"Apakah kamu hendak menjadikan kami buah ejekan?\" Musa menjawab: \"Aku berlindung kepada Allah agar tidak menjadi salah seorang dari orang-orang yang jahil\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 68, "text": "قَالُوا۟ ٱدۡعُ لَنَا رَبَّكَ یُبَیِّن لَّنَا مَا هِیَۚ قَالَ إِنَّهُۥ یَقُولُ إِنَّهَا بَقَرَةࣱ لَّا فَارِضࣱ وَلَا بِكۡرٌ عَوَانُۢ بَیۡنَ ذَ ٰلِكَۖ فَٱفۡعَلُوا۟ مَا تُؤۡمَرُونَ ۝٦٨", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "قالوا: ادع لنا ربَّك يوضح لنا صفة هذه البقرة، فأجابهم: إن الله يقول لكم: صفتها ألا تكون مسنَّة هَرِمة، ولا صغيرة فَتِيَّة، وإنما هي متوسطة بينهما، فسارِعوا إلى امتثال أمر ربكم.", "isBasmala": false, "translation_en": "They said, \"Call upon your Lord to show us which one.\" He said, \"He says she is a heifer, neither too old, nor too young, but in between. So do what you are commanded.\"", "translation_id": "Mereka menjawab: \"Mohonkanlah kepada Tuhanmu untuk kami, agar Dia menerangkan kepada kami; sapi betina apakah itu\". Musa menjawab: \"Sesungguhnya Allah berfirman bahwa sapi betina itu adalah sapi betina yang tidak tua dan tidak muda; pertengahan antara itu; maka kerjakanlah apa yang diperintahkan kepadamu\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 69, "text": "قَالُوا۟ ٱدۡعُ لَنَا رَبَّكَ یُبَیِّن لَّنَا مَا لَوۡنُهَاۚ قَالَ إِنَّهُۥ یَقُولُ إِنَّهَا بَقَرَةࣱ صَفۡرَاۤءُ فَاقِعࣱ لَّوۡنُهَا تَسُرُّ ٱلنَّـٰظِرِینَ ۝٦٩", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "فعادوا إلى جدالهم قائلين: ادع لنا ربك يوضح لنا لونها. قال: إنه يقول: إنها بقرة صفراء شديدة الصُّفْرة، تَسُرُّ مَن ينظر إليها.", "isBasmala": false, "translation_en": "They said, \"Call upon your Lord to show us what her color is.\" He said, \"He says she is a yellow heifer, bright in color, pleasing to the beholders.\"", "translation_id": "Mereka berkata: \"Mohonkanlah kepada Tuhanmu untuk kami agar Dia menerangkan kepada kami apa warnanya\". Musa menjawab: \"Sesungguhnya Allah berfirman bahwa sapi betina itu adalah sapi betina yang kuning, yang kuning tua warnanya, lagi menyenangkan orang-orang yang memandangnya\".", "manzil": 1, "manzil_display": ""}], "11": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 70, "text": "قَالُوا۟ ٱدۡعُ لَنَا رَبَّكَ یُبَیِّن لَّنَا مَا هِیَ إِنَّ ٱلۡبَقَرَ تَشَـٰبَهَ عَلَیۡنَا وَإِنَّاۤ إِن شَاۤءَ ٱللَّهُ لَمُهۡتَدُونَ ۝٧٠", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "قال بنو إسرائيل لموسى: ادع لنا ربك يوضح لنا صفات أخرى غير ما سبق؛ لأن البقر -بهذه الصفات- كثير فاشْتَبَهَ علينا ماذا نختار؟ وإننا -إن شاء الله- لمهتدون إلى البقرة المأمور بذبحها.", "isBasmala": false, "translation_en": "They said, \"Call upon your Lord to show us which one; the heifers look alike to us; and God willing, we will be guided.\"", "translation_id": "Mereka berkata: \"Mohonkanlah kepada Tuhanmu untuk kami agar Dia menerangkan kepada kami bagaimana hakikat sapi betina itu, karena sesungguhnya sapi itu (masih) samar bagi kami dan sesungguhnya kami insya Allah akan mendapat petunjuk (untuk memperoleh sapi itu)\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 71, "text": "قَالَ إِنَّهُۥ یَقُولُ إِنَّهَا بَقَرَةࣱ لَّا ذَلُولࣱ تُثِیرُ ٱلۡأَرۡضَ وَلَا تَسۡقِی ٱلۡحَرۡثَ مُسَلَّمَةࣱ لَّا شِیَةَ فِیهَاۚ قَالُوا۟ ٱلۡـَٔـٰنَ جِئۡتَ بِٱلۡحَقِّۚ فَذَبَحُوهَا وَمَا كَادُوا۟ یَفۡعَلُونَ ۝٧١", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "قال لهم موسى: إن الله يقول: إنها بقرة غير مذللة للعمل في حراثة الأرض للزراعة، وغير معدة للسقي من الساقية، وخالية من العيوب جميعها، وليس فيها علامة من لون غير لون جلدها. قالوا: الآن جئت بحقيقة وصف البقرة، فاضطروا إلى ذبحها بعد طول المراوغة، وقد قاربوا ألا يفعلوا ذلك لعنادهم. وهكذا شددوا فشدَّد الله عليهم.", "isBasmala": false, "translation_en": "He said, \"He says she is a heifer, neither yoked to plow the earth, nor to irrigate the field; sound without blemish.\" They said, \"Now you have brought the truth.\" So they slew her; though they almost did not.", "translation_id": "Musa berkata: \"Sesungguhnya Allah berfirman bahwa sapi betina itu adalah sapi betina yang belum pernah dipakai untuk membajak tanah dan tidak pula untuk mengairi tanaman, tidak bercacat, tidak ada belangnya\". Mereka berkata: \"Sekarang barulah kamu menerangkan hakikat sapi betina yang sebenarnya\". Kemudian mereka menyembelihnya dan hampir saja mereka tidak melaksanakan perintah itu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 72, "text": "وَإِذۡ قَتَلۡتُمۡ نَفۡسࣰا فَٱدَّ ٰرَءۡتُمۡ فِیهَاۖ وَٱللَّهُ مُخۡرِجࣱ مَّا كُنتُمۡ تَكۡتُمُونَ ۝٧٢", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "واذكروا إذ قتلتم نفسًا فتنازعتم بشأنها، كلٌّ يدفع عن نفسه تهمة القتل، والله مخرج ما كنتم تخفون مِن قَتْل القتيل.", "isBasmala": false, "translation_en": "And recall when you killed a person, and disputed in the matter; but God was to expose what you were hiding.", "translation_id": "Dan (ingatlah), ketika kamu membunuh seorang manusia lalu kamu saling tuduh menuduh tentang itu. Dan Allah hendak menyingkapkan apa yang selama ini kamu sembunyikan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 73, "text": "فَقُلۡنَا ٱضۡرِبُوهُ بِبَعۡضِهَاۚ كَذَ ٰلِكَ یُحۡیِ ٱللَّهُ ٱلۡمَوۡتَىٰ وَیُرِیكُمۡ ءَایَـٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ ۝٧٣", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "فقلنا: اضربوا القتيل بجزء من هذه البقرة المذبوحة، فإن الله سيبعثه حيًا، ويخبركم عن قاتله. فضربوه ببعضها فأحياه الله وأخبر بقاتله. كذلك يُحيي الله الموتى يوم القيامة، ويريكم- يا بني إسرائيل- معجزاته الدالة على كمال قدرته تعالى؛ لكي تتفكروا بعقولكم، فتمتنعوا عن معاصيه.", "isBasmala": false, "translation_en": "We said, \"Strike him with part of it.\" Thus God brings the dead to life; and He shows you His signs, that you may understand.", "translation_id": "Lalu Kami berfirman: \"Pukullah mayat itu dengan sebahagian anggota sapi betina itu!\" Demikianlah Allah menghidupkan kembali orang-orang yang telah mati, dam memperlihatkan padamu tanda-tanda kekuasaan-Nya agar kamu mengerti.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 74, "text": "ثُمَّ قَسَتۡ قُلُوبُكُم مِّنۢ بَعۡدِ ذَ ٰلِكَ فَهِیَ كَٱلۡحِجَارَةِ أَوۡ أَشَدُّ قَسۡوَةࣰۚ وَإِنَّ مِنَ ٱلۡحِجَارَةِ لَمَا یَتَفَجَّرُ مِنۡهُ ٱلۡأَنۡهَـٰرُۚ وَإِنَّ مِنۡهَا لَمَا یَشَّقَّقُ فَیَخۡرُجُ مِنۡهُ ٱلۡمَاۤءُۚ وَإِنَّ مِنۡهَا لَمَا یَهۡبِطُ مِنۡ خَشۡیَةِ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ ۝٧٤", "juz": 1, "hizb": "(*¾ ح 1*)", "tafsir": "ولكنكم لم تنتفعوا بذلك؛ إذ بعد كل هذه المعجزات الخارقة اشتدت قلوبكم وغلظت، فلم يَنْفُذ إليها خير، ولم تَلِنْ أمام الآيات الباهرة التي أريتكموها، حتى صارت قلوبكم مثل الحجارة الصمَّاء، بل هي أشد منها غلظة؛ لأن من الحجارة ما يتسع وينفرج حتى تنصبَّ منه المياه صبًا، فتصير أنهارًا جاريةً، ومن الحجارة ما يتصدع فينشق، فتخرج منه العيون والينابيع، ومن الحجارة ما يسقط من أعالي الجبال مِن خشية الله تعالى وتعظيمه. وما الله بغافل عما تعملون.", "isBasmala": false, "translation_en": "Then after that your hearts hardened. They were as rocks, or even harder. For there are some rocks from which rivers gush out, and others that splinter and water comes out from them, and others that sink in awe of God. God is not unaware of what you do.", "translation_id": "Kemudian setelah itu hatimu menjadi keras seperti batu, bahkan lebih keras lagi. Padahal diantara batu-batu itu sungguh ada yang mengalir sungai-sungai dari padanya dan diantaranya sungguh ada yang terbelah lalu keluarlah mata air dari padanya dan diantaranya sungguh ada yang meluncur jatuh, karena takut kepada Allah. Dan Allah sekali-sekali tidak lengah dari apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 75, "text": "۞ أَفَتَطۡمَعُونَ أَن یُؤۡمِنُوا۟ لَكُمۡ وَقَدۡ كَانَ فَرِیقࣱ مِّنۡهُمۡ یَسۡمَعُونَ كَلَـٰمَ ٱللَّهِ ثُمَّ یُحَرِّفُونَهُۥ مِنۢ بَعۡدِ مَا عَقَلُوهُ وَهُمۡ یَعۡلَمُونَ ۝٧٥", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "أيها المسلمون أنسيتم أفعال بني إسرائيل، فطمعت نفوسكم أن يصدِّق اليهودُ بدينكم؟ وقد كان علماؤهم يسمعون كلام الله من التوراة، ثم يحرفونه بِصَرْفِه إلى غير معناه الصحيح بعد ما عقلوا حقيقته، أو بتحريف ألفاظه، وهم يعلمون أنهم يحرفون كلام رب العالمين عمدًا وكذبًا.", "isBasmala": false, "translation_en": "Do you hope that they will believe in you, when some of them used to hear the Word of God, and then deliberately distort it, even after understanding it?", "translation_id": "Apakah kamu masih mengharapkan mereka akan percaya kepadamu, padahal segolongan dari mereka mendengar firman Allah, lalu mereka mengubahnya setelah mereka memahaminya, sedang mereka mengetahui?.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 76, "text": "وَإِذَا لَقُوا۟ ٱلَّذِینَ ءَامَنُوا۟ قَالُوۤا۟ ءَامَنَّا وَإِذَا خَلَا بَعۡضُهُمۡ إِلَىٰ بَعۡضࣲ قَالُوۤا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَیۡكُمۡ لِیُحَاۤجُّوكُم بِهِۦ عِندَ رَبِّكُمۡۚ أَفَلَا تَعۡقِلُونَ ۝٧٦", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "هؤلاء اليهود إذا لقوا الذين آمنوا قالوا بلسانهم: آمنَّا بدينكم ورسولكم المبشَّر به في التوراة، وإذا خلا بعض هؤلاء المنافقين من اليهود إلى بعض قالوا في إنكار: أتحدِّثون المؤمنين بما بيَّن الله لكم في التوراة من أمر محمد؛ لتكون لهم الحجة عليكم عند ربكم يوم القيامة؟ أفلا تفقهون فتحذروا؟", "isBasmala": false, "translation_en": "And when they come across those who believe, they say, \"We believe,\" but when they come together privately, they say, \"Will you inform them of what God has disclosed to you, so that they might dispute with you concerning it before your Lord?\" Do you not understand?", "translation_id": "Dan apabila mereka berjumpa dengan orang-orang yang beriman, mereka berkata: \"Kamipun telah beriman,\" tetapi apabila mereka berada sesama mereka saja, lalu mereka berkata: \"Apakah kamu menceritakan kepada mereka (orang-orang mukmin) apa yang telah diterangkan Allah kepadamu, supaya dengan demikian mereka dapat mengalahkan hujjahmu di hadapan Tuhanmu; tidakkah kamu mengerti?\"", "manzil": 1, "manzil_display": ""}], "12": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 77, "text": "أَوَ لَا یَعۡلَمُونَ أَنَّ ٱللَّهَ یَعۡلَمُ مَا یُسِرُّونَ وَمَا یُعۡلِنُونَ ۝٧٧", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "أيفعلون كلَّ هذه الجرائم، ولا يعلمون أن الله يعلم جميع ما يخفونه وما يظهرونه؟", "isBasmala": false, "translation_en": "Do they not know that God knows what they conceal and what they reveal?", "translation_id": "Tidakkah mereka mengetahui bahwa Allah mengetahui segala yang mereka sembunyikan dan segala yang mereka nyatakan?", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 78, "text": "وَمِنۡهُمۡ أُمِّیُّونَ لَا یَعۡلَمُونَ ٱلۡكِتَـٰبَ إِلَّاۤ أَمَانِیَّ وَإِنۡ هُمۡ إِلَّا یَظُنُّونَ ۝٧٨", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "ومن اليهود جماعة يجهلون القراءة والكتابة، ولا يعلمون التوراة وما فيها من صفات نبي الله ورسوله محمد صلى الله عليه وسلم، وما عندهم من ذلك إلا أكاذيبُ وظنون فاسدة.", "isBasmala": false, "translation_en": "And among them are uneducated who know the Scripture only through hearsay, and they only speculate.", "translation_id": "Dan diantara mereka ada yang buta huruf, tidak mengetahui Al Kitab (Taurat), kecuali dongengan bohong belaka dan mereka hanya menduga-duga.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 79, "text": "فَوَیۡلࣱ لِّلَّذِینَ یَكۡتُبُونَ ٱلۡكِتَـٰبَ بِأَیۡدِیهِمۡ ثُمَّ یَقُولُونَ هَـٰذَا مِنۡ عِندِ ٱللَّهِ لِیَشۡتَرُوا۟ بِهِۦ ثَمَنࣰا قَلِیلࣰاۖ فَوَیۡلࣱ لَّهُم مِّمَّا كَتَبَتۡ أَیۡدِیهِمۡ وَوَیۡلࣱ لَّهُم مِّمَّا یَكۡسِبُونَ ۝٧٩", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "فهلاك ووعيد شديد لأحبار السوء من اليهود الذين يكتبون الكتاب بأيديهم، ثم يقولون: هذا من عند الله وهو مخالف لما أنزل الله على نبيِّه موسى عليه الصلاة والسلام؛ ليأخذوا في مقابل هذا عرض الدنيا. فلهم عقوبة مهلكة بسبب كتابتهم هذا الباطل بأيديهم، ولهم عقوبة مهلكة بسبب ما يأخذونه في المقابل من المال الحرام، كالرشوة وغيرها.", "isBasmala": false, "translation_en": "So woe to those who write the Scripture with their own hands, and then say, \"This is from God,\" that they may exchange it for a little price. Woe to them for what their hands have written, and woe to them for what they earn.", "translation_id": "Maka kecelakaan yAng besarlah bagi orang-orang yang menulis Al Kitab dengan tangan mereka sendiri, lalu dikatakannya; \"Ini dari Allah\", (dengan maksud) untuk memperoleh keuntungan yang sedikit dengan perbuatan itu. Maka kecelakaan yang besarlah bagi mereka, akibat apa yang ditulis oleh tangan mereka sendiri, dan kecelakaan yang besarlah bagi mereka, akibat apa yang mereka kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 80, "text": "وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّاۤ أَیَّامࣰا مَّعۡدُودَةࣰۚ قُلۡ أَتَّخَذۡتُمۡ عِندَ ٱللَّهِ عَهۡدࣰا فَلَن یُخۡلِفَ ٱللَّهُ عَهۡدَهُۥۤۖ أَمۡ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝٨٠", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "وقال بنو إسرائيل: لن تصيبنا النار في الآخرة إلا أيامًا قليلة العدد. قل لهم -أيها الرسول مبطلا دعواهم-: أعندكم عهد من الله بهذا، فإن الله لا يخلف عهده؟ بل إنكم تقولون على الله ما لا تعلمون بافترائكم الكذب.", "isBasmala": false, "translation_en": "And they say, \"The Fire will not touch us except for a number of days.\" Say, \"Have you received a promise from God-God never breaks His promise-or are you saying about God what you do not know?\"", "translation_id": "Dan mereka berkata: \"Kami sekali-kali tidak akan disentuh oleh api neraka, kecuali selama beberapa hari saja\". Katakanlah: \"Sudahkah kamu menerima janji dari Allah sehingga Allah tidak akan memungkiri janji-Nya, ataukah kamu hanya mengatakan terhadap Allah apa yang tidak kamu ketahui?\"", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 81, "text": "بَلَىٰۚ مَن كَسَبَ سَیِّئَةࣰ وَأَحَـٰطَتۡ بِهِۦ خَطِیۤـَٔتُهُۥ فَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٨١", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "فحُكْمُ الله ثابت: أن من ارتكب الآثام حتى جَرَّته إلى الكفر، واستولت عليه ذنوبه مِن جميع جوانبه وهذا لا يكون إلا فيمن أشرك بالله، فالمشركون والكفار هم الذين يلازمون نار جهنم ملازمة دائمةً لا تنقطع.", "isBasmala": false, "translation_en": "Indeed, whoever commits misdeeds, and becomes besieged by his iniquities-these are the inmates of the Fire, wherein they will dwell forever.", "translation_id": "(Bukan demikian), yang benar: barangsiapa berbuat dosa dan ia telah diliputi oleh dosanya, mereka itulah penghuni neraka, mereka kekal di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 82, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٨٢", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "وحكم الله الثابتُ في مقابل هذا: أنَّ الذين صدَّقوا بالله ورسله تصديقًا خالصًا، وعملوا الأعمال المتفقة مع شريعة الله التي أوحاها إلى رسله، هؤلاء يلازمون الجنة في الآخرة ملازمةً دائمةً لا تنقطع.", "isBasmala": false, "translation_en": "As for those who believe and do righteous deeds-these are the inhabitants of Paradise, wherein they will dwell forever.", "translation_id": "Dan orang-orang yang beriman serta beramal saleh, mereka itu penghuni surga; mereka kekal di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 83, "text": "وَإِذۡ أَخَذۡنَا مِیثَـٰقَ بَنِیۤ إِسۡرَ ٰۤءِیلَ لَا تَعۡبُدُونَ إِلَّا ٱللَّهَ وَبِٱلۡوَ ٰلِدَیۡنِ إِحۡسَانࣰا وَذِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَقُولُوا۟ لِلنَّاسِ حُسۡنࣰا وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّیۡتُمۡ إِلَّا قَلِیلࣰا مِّنكُمۡ وَأَنتُم مُّعۡرِضُونَ ۝٨٣", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "واذكروا يا بني إسرائيل حين أخَذْنا عليكم عهدًا مؤكدًا: بأن تعبدوا الله وحده لا شريك له، وأن تحسنوا للوالدين، وللأقربين، وللأولاد الذين مات آباؤهم وهم دون بلوغ الحلم، وللمساكين، وأن تقولوا للناس أطيب الكلام، مع أداء الصلاة وإيتاء الزكاة، ثم أَعْرَضْتم ونقضتم العهد -إلا قليلا منكم ثبت عليه- وأنتم مستمرون في إعراضكم.", "isBasmala": false, "translation_en": "We made a covenant with the Children of Israel: \"Worship none but God; and be good to parents, and relatives, and orphans, and the needy; and speak nicely to people; and pray regularly, and give alms.\" Then you turned away, except for a few of you, recanting.", "translation_id": "Dan (ingatlah), ketika Kami mengambil janji dari Bani Israil (yaitu): Janganlah kamu menyembah selain Allah, dan berbuat kebaikanlah kepada ibu bapa, kaum kerabat, anak-anak yatim, dan orang-orang miskin, serta ucapkanlah kata-kata yang baik kepada manusia, dirikanlah shalat dan tunaikanlah zakat. Kemudian kamu tidak memenuhi janji itu, kecuali sebahagian kecil daripada kamu, dan kamu selalu berpaling.", "manzil": 1, "manzil_display": ""}], "13": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 84, "text": "وَإِذۡ أَخَذۡنَا مِیثَـٰقَكُمۡ لَا تَسۡفِكُونَ دِمَاۤءَكُمۡ وَلَا تُخۡرِجُونَ أَنفُسَكُم مِّن دِیَـٰرِكُمۡ ثُمَّ أَقۡرَرۡتُمۡ وَأَنتُمۡ تَشۡهَدُونَ ۝٨٤", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "واذكروا -يا بني إسرائيل- حين أَخَذْنا عليكم عهدًا مؤكدًا في التوراة: يحرم سفك بعضكم دم بعض، وإخراج بعضكم بعضًا من دياركم، ثم اعترفتم بذلك، وأنتم تشهدون على صحته.", "isBasmala": false, "translation_en": "And We made a covenant with you: \"You shall not shed the blood of your own, nor shall you evict your own from your homes.\" You agreed, and were all witnesses.", "translation_id": "Dan (ingatlah), ketika Kami mengambil janji dari kamu (yaitu): kamu tidak akan menumpahkan darahmu (membunuh orang), dan kamu tidak akan mengusir dirimu (saudaramu sebangsa) dari kampung halamanmu, kemudian kamu berikrar (akan memenuhinya) sedang kamu mempersaksikannya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 85, "text": "ثُمَّ أَنتُمۡ هَـٰۤؤُلَاۤءِ تَقۡتُلُونَ أَنفُسَكُمۡ وَتُخۡرِجُونَ فَرِیقࣰا مِّنكُم مِّن دِیَـٰرِهِمۡ تَظَـٰهَرُونَ عَلَیۡهِم بِٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰنِ وَإِن یَأۡتُوكُمۡ أُسَـٰرَىٰ تُفَـٰدُوهُمۡ وَهُوَ مُحَرَّمٌ عَلَیۡكُمۡ إِخۡرَاجُهُمۡۚ أَفَتُؤۡمِنُونَ بِبَعۡضِ ٱلۡكِتَـٰبِ وَتَكۡفُرُونَ بِبَعۡضࣲۚ فَمَا جَزَاۤءُ مَن یَفۡعَلُ ذَ ٰلِكَ مِنكُمۡ إِلَّا خِزۡیࣱ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ یُرَدُّونَ إِلَىٰۤ أَشَدِّ ٱلۡعَذَابِۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ ۝٨٥", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "ثم أنتم يا هؤلاء يقتل بعضكم بعضًا، ويُخرج بعضكم بعضًا من ديارهم، ويَتَقَوَّى كل فريق منكم على إخوانه بالأعداء بغيًا وعدوانًا. وأن يأتوكم أسارى في يد الأعداء سعيتم في تحريرهم من الأسر، بدفع الفدية، مع أنه محرم عليكم إخراجهم من ديارهم. ما أقبح ما تفعلون حين تؤمنون ببعض أحكام التوراة وتكفرون ببعضها! فليس جزاء مَن يفعل ذلك منكم إلا ذُلا وفضيحة في الدنيا. ويوم القيامة يردُّهم الله إلى أفظع العذاب في النار. وما الله بغافل عما تعملون.", "isBasmala": false, "translation_en": "But here you are, killing your own, and expelling a group of your own from their homes-conspiring against them in wrongdoing and hostility. And if they come to you as captives, you ransom them, although it was forbidden to you. Is it that you believe in part of the Scripture, and disbelieve in part? What is the reward for those among you who do that but humiliation in this life? And on the Day of Resurrection, they will be assigned to the most severe torment. God is not unaware of what you do.", "translation_id": "Kemudian kamu (Bani Israil) membunuh dirimu (saudaramu sebangsa) dan mengusir segolongan daripada kamu dari kampung halamannya, kamu bantu membantu terhadap mereka dengan membuat dosa dan permusuhan; tetapi jika mereka datang kepadamu sebagai tawanan, kamu tebus mereka, padahal mengusir mereka itu (juga) terlarang bagimu. Apakah kamu beriman kepada sebahagian Al Kitab (Taurat) dan ingkar terhadap sebahagian yang lain? Tiadalah balasan bagi orang yang berbuat demikian daripadamu, melainkan kenistaan dalam kehidupan dunia, dan pada hari kiamat mereka dikembalikan kepada siksa yang sangat berat. Allah tidak lengah dari apa yang kamu perbuat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 86, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ٱشۡتَرَوُا۟ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا بِٱلۡـَٔاخِرَةِۖ فَلَا یُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ یُنصَرُونَ ۝٨٦", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "أولئك هم الذين آثروا الحياة الدنيا على الآخرة، فلا يخفف عنهم العذاب، وليس لهم ناصر ينصرهم مِن عذاب الله.", "isBasmala": false, "translation_en": "Those are they who bought the present life for the Hereafter, so the punishment will not be lightened for them, nor will they be helped.", "translation_id": "Itulah orang-orang yang membeli kehidupan dunia dengan (kehidupan) akhirat, maka tidak akan diringankan siksa mereka dan mereka tidak akan ditolong.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 87, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ وَقَفَّیۡنَا مِنۢ بَعۡدِهِۦ بِٱلرُّسُلِۖ وَءَاتَیۡنَا عِیسَى ٱبۡنَ مَرۡیَمَ ٱلۡبَیِّنَـٰتِ وَأَیَّدۡنَـٰهُ بِرُوحِ ٱلۡقُدُسِۗ أَفَكُلَّمَا جَاۤءَكُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰۤ أَنفُسُكُمُ ٱسۡتَكۡبَرۡتُمۡ فَفَرِیقࣰا كَذَّبۡتُمۡ وَفَرِیقࣰا تَقۡتُلُونَ ۝٨٧", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "ولقد أعطينا موسى التوراة، وأتبعناه برسل من بني إسرائيل، وأعطينا عيسى ابن مريم المعجزات الواضحات، وقوَّيناه بجبريل عليه السلام. أفكلما جاءكم رسول بوحي من عند الله لا يوافق أهواءكم، استعليتم عليه، فكذَّبتم فريقًا وتقتلون فريقًا؟", "isBasmala": false, "translation_en": "We gave Moses the Scripture, and sent a succession of messengers after him. And We gave Jesus son of Mary the clear proofs, and We supported him with the Holy Spirit. Is it that whenever a messenger comes to you with anything your souls do not desire, you grew arrogant, calling some impostors, and killing others?", "translation_id": "Dan sesungguhnya Kami telah mendatangkan Al Kitab (Taurat) kepada Musa, dan Kami telah menyusulinya (berturut-turut) sesudah itu dengan rasul-rasul, dan telah Kami berikan bukti-bukti kebenaran (mukjizat) kepada Isa putera Maryam dan Kami memperkuatnya dengan Ruhul Qudus. Apakah setiap datang kepadamu seorang rasul membawa sesuatu (pelajaran) yang tidak sesuai dengan keinginanmu lalu kamu menyombong; maka beberapa orang (diantara mereka) kamu dustakan dan beberapa orang (yang lain) kamu bunuh?", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 88, "text": "وَقَالُوا۟ قُلُوبُنَا غُلۡفُۢۚ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَقَلِیلࣰا مَّا یُؤۡمِنُونَ ۝٨٨", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "وقال بنو إسرائيل لنبي الله ورسوله محمد صلى الله عليه وسلم: قلوبنا مغطاة، لا يَنْفُذ إليها قولك. وليس الأمر كما ادَّعَوْا، بل قلوبهم ملعونة، مطبوع عليها، وهم مطرودون من رحمة الله بسبب جحودهم، فلا يؤمنون إلا إيمانًا قليلا لا ينفعهم.", "isBasmala": false, "translation_en": "And they said, \"Our hearts are sealed.\" Rather, God has cursed them for their ingratitude. They have little faith.", "translation_id": "Dan mereka berkata: \"Hati kami tertutup\". Tetapi sebenarnya Allah telah mengutuk mereka karena keingkaran mereka; maka sedikit sekali mereka yang beriman.", "manzil": 1, "manzil_display": ""}], "14": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 89, "text": "وَلَمَّا جَاۤءَهُمۡ كِتَـٰبࣱ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقࣱ لِّمَا مَعَهُمۡ وَكَانُوا۟ مِن قَبۡلُ یَسۡتَفۡتِحُونَ عَلَى ٱلَّذِینَ كَفَرُوا۟ فَلَمَّا جَاۤءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦۚ فَلَعۡنَةُ ٱللَّهِ عَلَى ٱلۡكَـٰفِرِینَ ۝٨٩", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "وحين جاءهم القرأن من عند الله مصدقا لما معهم من التوراة جحدوه، وأنكروا نبوة محمد صلى الله عليه وسلم، وكانوا قبل بعثته يستنصرون به على مشركي العرب، ويقولون: قَرُبَ مبعث نبيِّ آخرِ الزمان، وسنتبعه ونقاتلكم معه. فلمَّا جاءهم الرسول الذي عرفوا صفاتِه وصِدْقَه كفروا به وكذبوه. فلعنةُ الله على كل مَن كفر بنبي الله ورسوله محمد صلى الله عليه وسلم، وكتابه الذي أوحاه الله إليه.", "isBasmala": false, "translation_en": "And when a scripture came to them from God, confirming what they have-although previously they were seeking victory against those who disbelieved-but when there came to them what they recognized, they disbelieved in it. So God's curse is upon the disbelievers.", "translation_id": "Dan setelah datang kepada mereka Al Quran dari Allah yang membenarkan apa yang ada pada mereka, padahal sebelumnya mereka biasa memohon (kedatangan Nabi) untuk mendapat kemenangan atas orang-orang kafir, maka setelah datang kepada mereka apa yang telah mereka ketahui, mereka lalu ingkar kepadanya. Maka laknat Allah-lah atas orang-orang yang ingkar itu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 90, "text": "بِئۡسَمَا ٱشۡتَرَوۡا۟ بِهِۦۤ أَنفُسَهُمۡ أَن یَكۡفُرُوا۟ بِمَاۤ أَنزَلَ ٱللَّهُ بَغۡیًا أَن یُنَزِّلَ ٱللَّهُ مِن فَضۡلِهِۦ عَلَىٰ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۖ فَبَاۤءُو بِغَضَبٍ عَلَىٰ غَضَبࣲۚ وَلِلۡكَـٰفِرِینَ عَذَابࣱ مُّهِینࣱ ۝٩٠", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "قَبُحَ ما اختاره بنو إسرائيل لأنفسهم؛ إذ استبدلوا الكفر بالإيمان ظلمًا وحسدًا لإنزال الله من فضله القرآن على نبي الله ورسوله محمد صلى الله عليه وسلم، فرجعوا بغضب من الله عليهم بسبب جحودهم بالنبي محمد صلى الله عليه وسلم، بعد غضبه عليهم بسبب تحريفهم التوراة. وللجاحدين نبوَّة محمد صلى الله عليه وسلم عذابٌ يذلُّهم ويخزيهم.", "isBasmala": false, "translation_en": "Miserable is what they sold their souls for-rejecting what God has revealed, out of resentment that God would send down His grace upon whomever He chooses from among His servants. Thus they incurred wrath upon wrath. And there is a demeaning punishment for the disbelievers.", "translation_id": "Alangkah buruknya (hasil perbuatan) mereka yang menjual dirinya sendiri dengan kekafiran kepada apa yang telah diturunkan Allah, karena dengki bahwa Allah menurunkan karunia-Nya kepada siapa yang dikehendaki-Nya diantara hamba-hamba-Nya. Karena itu mereka mendapat murka sesudah (mendapat) kemurkaan. Dan untuk orang-orang kafir siksaan yang menghinakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 91, "text": "وَإِذَا قِیلَ لَهُمۡ ءَامِنُوا۟ بِمَاۤ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤۡمِنُ بِمَاۤ أُنزِلَ عَلَیۡنَا وَیَكۡفُرُونَ بِمَا وَرَاۤءَهُۥ وَهُوَ ٱلۡحَقُّ مُصَدِّقࣰا لِّمَا مَعَهُمۡۗ قُلۡ فَلِمَ تَقۡتُلُونَ أَنۢبِیَاۤءَ ٱللَّهِ مِن قَبۡلُ إِن كُنتُم مُّؤۡمِنِینَ ۝٩١", "juz": 1, "hizb": "(* ح 2*)", "tafsir": "وإذا قال بعض المسلمين لليهود: صدِّقوا بما أنزل الله من القرآن، قالوا: نحن نصدِّق بما أنزل الله على أنبيائنا، ويجحدون ما أنزل الله بعد ذلك، وهو الحق مصدقًا لما معهم. فلو كانوا يؤمنون بكتبهم حقًا لآمنوا بالقرآن الذي صدَّقها. قل لهم -يا محمد-: إن كنتم مؤمنين بما أنزل الله عليكم، فلماذا قتلتم أنبياء الله مِن قبل؟", "isBasmala": false, "translation_en": "And when it is said to them, \"Believe in what God has revealed,\" they say, \"We believe in what was revealed to us,\" and they reject anything beyond that, although it is the truth which confirms what they have. Say, \"Why did you kill God's prophets before, if you were believers?\"", "translation_id": "Dan apabila dikatakan kepada mereka: \"Berimanlah kepada Al Quran yang diturunkan Allah,\" mereka berkata: \"Kami hanya beriman kepada apa yang diturunkan kepada kami\". Dan mereka kafir kepada Al Quran yang diturunkan sesudahnya, sedang Al Quran itu adalah (Kitab) yang hak; yang membenarkan apa yang ada pada mereka. Katakanlah: \"Mengapa kamu dahulu membunuh nabi-nabi Allah jika benar kamu orang-orang yang beriman?\"", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 92, "text": "۞ وَلَقَدۡ جَاۤءَكُم مُّوسَىٰ بِٱلۡبَیِّنَـٰتِ ثُمَّ ٱتَّخَذۡتُمُ ٱلۡعِجۡلَ مِنۢ بَعۡدِهِۦ وَأَنتُمۡ ظَـٰلِمُونَ ۝٩٢", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "ولقد جاءكم نبي الله موسى بالمعجزات الواضحات الدالة على صدقه، كالطوفان والجراد والقُمَّل والضفادع، وغير ذلك مما ذكره الله في القرآن العظيم، ومع ذلك اتخذتم العجل معبودًا، بعد ذهاب موسى إلى ميقات ربه، وأنتم متجاوزون حدود الله.", "isBasmala": false, "translation_en": "Moses came to you with clear proofs, yet you adopted the calf in his absence, and you were in the wrong.", "translation_id": "Sesungguhnya Musa telah datang kepadamu membawa bukti-bukti kebenaran (mukjizat), kemudian kamu jadikan anak sapi (sebagai sembahan) sesudah (kepergian)nya, dan sebenarnya kamu adalah orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 93, "text": "وَإِذۡ أَخَذۡنَا مِیثَـٰقَكُمۡ وَرَفَعۡنَا فَوۡقَكُمُ ٱلطُّورَ خُذُوا۟ مَاۤ ءَاتَیۡنَـٰكُم بِقُوَّةࣲ وَٱسۡمَعُوا۟ۖ قَالُوا۟ سَمِعۡنَا وَعَصَیۡنَا وَأُشۡرِبُوا۟ فِی قُلُوبِهِمُ ٱلۡعِجۡلَ بِكُفۡرِهِمۡۚ قُلۡ بِئۡسَمَا یَأۡمُرُكُم بِهِۦۤ إِیمَـٰنُكُمۡ إِن كُنتُم مُّؤۡمِنِینَ ۝٩٣", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "واذكروا حين أَخَذْنا عليكم عهدًا مؤكدًا بقَبول ما جاءكم به موسى من التوراة، فنقضتم العهد، فرفعنا جبل الطور فوق رؤوسكم، وقلنا لكم: خذوا ما آتيناكم بجدٍّ، واسمعوا وأطيعوا، وإلا أسقطنا الجبل عليكم، فقلتم: سمعنا قولك وعصينا أمرك؛ لأن عبادة العجل قد امتزجت بقلوبكم بسبب تماديكم في الكفر. قل لهم -أيها الرسول-: قَبُحَ ما يأمركم به إيمانكم من الكفر والضلال، إن كنتم مصدِّقين بما أنزل الله عليكم.", "isBasmala": false, "translation_en": "And We made a covenant with you, and raised the Mount above you: \"Take what We have given you firmly, and listen.\" They said, \"We hear and disobey.\" And their hearts became filled with the love of the calf because of their disbelief. Say, \"Wretched is what your faith commands you to do, if you are believers.\"", "translation_id": "Dan (ingatlah), ketika Kami mengambil janji dari kamu dan Kami angkat bukit (Thursina) di atasmu (seraya Kami berfirman): \"Peganglah teguh-teguh apa yang Kami berikan kepadamu dan dengarkanlah!\" Mereka menjawab: \"Kami mendengar tetapi tidak mentaati\". Dan telah diresapkan ke dalam hati mereka itu (kecintaan menyembah) anak sapi karena kekafirannya. Katakanlah: \"Amat jahat perbuatan yang telah diperintahkan imanmu kepadamu jika betul kamu beriman (kepada Taurat).", "manzil": 1, "manzil_display": ""}], "15": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 94, "text": "قُلۡ إِن كَانَتۡ لَكُمُ ٱلدَّارُ ٱلۡـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةࣰ مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلۡمَوۡتَ إِن كُنتُمۡ صَـٰدِقِینَ ۝٩٤", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "قل -أيها الرسول- لليهود الذين يدَّعون أن الجنة خاصة بهم؛ لزعمهم أنهم أولياء الله من دون الناس، وأنهم أبناؤه وأحباؤه: إن كان الأمر كذلك فادْعُوا على الكاذبين منكم أو من غيركم بالموت، إن كنتم صادقين في دعواكم هذه.", "isBasmala": false, "translation_en": "Say, \"If the Final Home with God is yours alone, to the exclusion of all other people, then wish for death if you are sincere.\"", "translation_id": "Katakanlah: \"Jika kamu (menganggap bahwa) kampung akhirat (surga) itu khusus untukmu di sisi Allah, bukan untuk orang lain, maka inginilah kematian(mu), jika kamu memang benar.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 95, "text": "وَلَن یَتَمَنَّوۡهُ أَبَدَۢا بِمَا قَدَّمَتۡ أَیۡدِیهِمۡۚ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ ۝٩٥", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "ولن يفعلوا ذلك أبدًا؛ لما يعرفونه من صدق النبي محمد صلى الله عليه وسلم ومن كذبهم وافترائهم، وبسبب ما ارتكبوه من الكفر والعصيان، المؤَدِّيَيْن إلى حرمانهم من الجنة ودخول النار. والله تعالى عليم بالظالمين من عباده، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "But they will never wish for it, because of what their hands have forwarded. God is aware of the evildoers.", "translation_id": "Dan sekali-kali mereka tidak akan mengingini kematian itu selama-lamanya, karena kesalahan-kesalahan yang telah diperbuat oleh tangan mereka (sendiri), dan Allah Maha Mengetahui siapa orang-orang yang aniaya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 96, "text": "وَلَتَجِدَنَّهُمۡ أَحۡرَصَ ٱلنَّاسِ عَلَىٰ حَیَوٰةࣲ وَمِنَ ٱلَّذِینَ أَشۡرَكُوا۟ۚ یَوَدُّ أَحَدُهُمۡ لَوۡ یُعَمَّرُ أَلۡفَ سَنَةࣲ وَمَا هُوَ بِمُزَحۡزِحِهِۦ مِنَ ٱلۡعَذَابِ أَن یُعَمَّرَۗ وَٱللَّهُ بَصِیرُۢ بِمَا یَعۡمَلُونَ ۝٩٦", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "ولتعلمَنَّ -أيها الرسول- أن اليهود أشد الناس رغبة في طول الحياة أيًّا كانت هذه الحياة من الذلَّة والمهانة، بل تزيد رغبتهم في طول الحياة على رغبات المشركين. يتمنى اليهودي أن يعيش ألف سنة، ولا يُبْعده هذا العمر الطويل إن حصل من عذاب الله. والله تعالى لا يخفى عليه شيء من أعمالهم وسيجازيهم عليها بما يستحقون من العذاب.", "isBasmala": false, "translation_en": "You will find them, of all mankind, the most eager for life, even more than the polytheists. Every one of them wishes he could live a thousand years; but to be granted a long life will not nudge him from the punishment. God is Seeing of what they do.", "translation_id": "Dan sungguh kamu akan mendapati mereka, manusia yang paling loba kepada kehidupan (di dunia), bahkan (lebih loba lagi) dari orang-orang musyrik. Masing-masing mereka ingin agar diberi umur seribu tahun, padahal umur panjang itu sekali-kali tidak akan menjauhkannya daripada siksa. Allah Maha Mengetahui apa yang mereka kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 97, "text": "قُلۡ مَن كَانَ عَدُوࣰّا لِّجِبۡرِیلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلۡبِكَ بِإِذۡنِ ٱللَّهِ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ وَهُدࣰى وَبُشۡرَىٰ لِلۡمُؤۡمِنِینَ ۝٩٧", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "قل-أيها الرسول- لليهود حين قالوا: إن جبريل هو عدونا من الملائكة: من كان عدوًا لجبريل فإنه نزَّل القرآن على قلبك بإذن الله تعالى مصدِّقًا لما سبقه من كتب الله، وهاديًا إلى الحق، ومبشرًا للمصدِّقين به بكل خير في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Say, \"Whoever is hostile to Gabriel-it is he who revealed it to your heart by God's leave, confirming what preceded it, and guidance and good news for the believers.\"", "translation_id": "Katakanlah: \"Barang siapa yang menjadi musuh Jibril, maka Jibril itu telah menurunkannya (Al Quran) ke dalam hatimu dengan seizin Allah; membenarkan apa (kitab-kitab) yang sebelumnya dan menjadi petunjuk serta berita gembira bagi orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 98, "text": "مَن كَانَ عَدُوࣰّا لِّلَّهِ وَمَلَـٰۤىِٕكَتِهِۦ وَرُسُلِهِۦ وَجِبۡرِیلَ وَمِیكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوࣱّ لِّلۡكَـٰفِرِینَ ۝٩٨", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "من عادى الله وملائكته، ورسله من الملائكة أو البشر، وبخاصة المَلَكان جبريلُ وميكالُ؛ لأن اليهود زعموا أن جبريل عدوهم، وميكال وليُّهم، فأعلمهم الله أنه من عادى واحدًا منهما فقد عادى الآخر، وعادى الله أيضًا، فإن الله عدو للجاحدين ما أنزل على رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Whoever is hostile to God, and His angels, and His messengers, and Gabriel, and Michael-God is hostile to the faithless.", "translation_id": "Barang siapa yang menjadi musuh Allah, malaikat-malaikat-Nya, rasul-rasul-Nya, Jibril dan Mikail, maka sesungguhnya Allah adalah musuh orang-orang kafir.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 99, "text": "وَلَقَدۡ أَنزَلۡنَاۤ إِلَیۡكَ ءَایَـٰتِۭ بَیِّنَـٰتࣲۖ وَمَا یَكۡفُرُ بِهَاۤ إِلَّا ٱلۡفَـٰسِقُونَ ۝٩٩", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "ولقد أنزلنا إليك-أيها الرسول- آيات بينات واضحات تدل على أنّك رسول من الله صدقا وحقا، وما ينكر تلك الآيات إلا الخارجون عن دين الله.", "isBasmala": false, "translation_en": "We have revealed to you clear signs, and none rejects them except the sinners.", "translation_id": "Dan sesungguhnya Kami telah menurunkan kepadamu ayat-ayat yang jelas; dan tak ada yang ingkar kepadanya, melainkan orang-orang yang fasik.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 100, "text": "أَوَ كُلَّمَا عَـٰهَدُوا۟ عَهۡدࣰا نَّبَذَهُۥ فَرِیقࣱ مِّنۡهُمۚ بَلۡ أَكۡثَرُهُمۡ لَا یُؤۡمِنُونَ ۝١٠٠", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "ما أقبح حال بني إسرائيل في نقضهم للعهود!! فكلما عاهدوا عهدًا طرح ذلك العهد فريق منهم، ونقضوه، فتراهم يُبْرِمون العهد اليوم وينقضونه غدًا، بل أكثرهم لا يصدِّقون بما جاء به نبي الله ورسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Is it not that whenever they make a covenant, some of them toss it aside? In fact, most of them do not believe.", "translation_id": "Patutkah (mereka ingkar kepada ayat-ayat Allah), dan setiap kali mereka mengikat janji, segolongan mereka melemparkannya? Bahkan sebagian besar dari mereka tidak beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 101, "text": "وَلَمَّا جَاۤءَهُمۡ رَسُولࣱ مِّنۡ عِندِ ٱللَّهِ مُصَدِّقࣱ لِّمَا مَعَهُمۡ نَبَذَ فَرِیقࣱ مِّنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ كِتَـٰبَ ٱللَّهِ وَرَاۤءَ ظُهُورِهِمۡ كَأَنَّهُمۡ لَا یَعۡلَمُونَ ۝١٠١", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "ولما جاءهم محمد رسول الله صلى الله عليه وسلم بالقرآن الموافق لما معهم من التوراة طرح فريق منهم كتاب الله، وجعلوه وراء ظهورهم، شأنهم شأن الجهال الذين لا يعلمون حقيقته.", "isBasmala": false, "translation_en": "And when there came to them a messenger from God, confirming what they had, a faction of those who were given the Book threw the Book of God behind their backs, as if they do not know.", "translation_id": "Dan setelah datang kepada mereka seorang Rasul dari sisi Allah yang membenarkan apa (kitab) yang ada pada mereka, sebahagian dari orang-orang yang diberi kitab (Taurat) melemparkan kitab Allah ke belakang (punggung)nya, seolah-olah mereka tidak mengetahui (bahwa itu adalah kitab Allah).", "manzil": 1, "manzil_display": ""}], "16": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 102, "text": "وَٱتَّبَعُوا۟ مَا تَتۡلُوا۟ ٱلشَّیَـٰطِینُ عَلَىٰ مُلۡكِ سُلَیۡمَـٰنَۖ وَمَا كَفَرَ سُلَیۡمَـٰنُ وَلَـٰكِنَّ ٱلشَّیَـٰطِینَ كَفَرُوا۟ یُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحۡرَ وَمَاۤ أُنزِلَ عَلَى ٱلۡمَلَكَیۡنِ بِبَابِلَ هَـٰرُوتَ وَمَـٰرُوتَۚ وَمَا یُعَلِّمَانِ مِنۡ أَحَدٍ حَتَّىٰ یَقُولَاۤ إِنَّمَا نَحۡنُ فِتۡنَةࣱ فَلَا تَكۡفُرۡۖ فَیَتَعَلَّمُونَ مِنۡهُمَا مَا یُفَرِّقُونَ بِهِۦ بَیۡنَ ٱلۡمَرۡءِ وَزَوۡجِهِۦۚ وَمَا هُم بِضَاۤرِّینَ بِهِۦ مِنۡ أَحَدٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَیَتَعَلَّمُونَ مَا یَضُرُّهُمۡ وَلَا یَنفَعُهُمۡۚ وَلَقَدۡ عَلِمُوا۟ لَمَنِ ٱشۡتَرَىٰهُ مَا لَهُۥ فِی ٱلۡـَٔاخِرَةِ مِنۡ خَلَـٰقࣲۚ وَلَبِئۡسَ مَا شَرَوۡا۟ بِهِۦۤ أَنفُسَهُمۡۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ ۝١٠٢", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "واتبع اليهود ما تُحَدِّث الشياطينُ به السحرةَ على عهد ملك سليمان بن داود. وما كفر سليمان وما تَعَلَّم السِّحر، ولكنَّ الشياطين هم الذين كفروا بالله حين علَّموا الناس السحر؛ إفسادًا لدينهم. وكذلك اتبع اليهود السِّحر الذي أُنزل على الملَكَين هاروت وماروت، بأرض \"بابل\" في \"العراق\"؛ امتحانًا وابتلاء من الله لعباده، وما يعلِّم الملكان من أحد حتى ينصحاه ويحذِّراه من تعلم السحر، ويقولا له: لا تكفر بتعلم السِّحر وطاعة الشياطين. فيتعلم الناس من الملكين ما يُحْدِثون به الكراهية بين الزوجين حتى يتفرقا. ولا يستطيع السحرة أن يضروا به أحدًا إلا بإذن الله وقضائه. وما يتعلم السحرة إلا شرًا يضرهم ولا ينفعهم، وقد نقلته الشياطين إلى اليهود، فشاع فيهم حتى فضَّلوه على كتاب الله. ولقد علم اليهود أن من اختار السِّحر وترك الحق ما له في الآخرة من نصيب في الخير. ولبئس ما باعوا به أنفسهم من السحر والكفر عوضًا عن الإيمان ومتابعة الرسول، لو كان لهم عِلْمٌ يثمر العمل بما وُعِظوا به.", "isBasmala": false, "translation_en": "And they followed what the devils taught during the reign of Salomon. It was not Solomon who disbelieved, but it was the devils who disbelieved. They taught the people witchcraft and what was revealed in Babylon to the two angels Harut and Marut. They did not teach anybody until they had said, \"We are a test, so do not lose faith.\" But they learned from them the means to cause separation between man and his wife. But they cannot harm anyone except with God's permission. And they learned what would harm them and not benefit them. Yet they knew that whoever deals in it will have no share in the Hereafter. Miserable is what they sold their souls for, if they only knew.", "translation_id": "Dan mereka mengikuti apa yang dibaca oleh syaitan-syaitan pada masa kerajaan Sulaiman (dan mereka mengatakan bahwa Sulaiman itu mengerjakan sihir), padahal Sulaiman tidak kafir (tidak mengerjakan sihir), hanya syaitan-syaitan lah yang kafir (mengerjakan sihir). Mereka mengajarkan sihir kepada manusia dan apa yang diturunkan kepada dua orang malaikat di negeri Babil yaitu Harut dan Marut, sedang keduanya tidak mengajarkan (sesuatu) kepada seorangpun sebelum mengatakan: \"Sesungguhnya kami hanya cobaan (bagimu), sebab itu janganlah kamu kafir\". Maka mereka mempelajari dari kedua malaikat itu apa yang dengan sihir itu, mereka dapat menceraikan antara seorang (suami) dengan isterinya. Dan mereka itu (ahli sihir) tidak memberi mudharat dengan sihirnya kepada seorangpun, kecuali dengan izin Allah. Dan mereka mempelajari sesuatu yang tidak memberi mudharat kepadanya dan tidak memberi manfaat. Demi, sesungguhnya mereka telah meyakini bahwa barangsiapa yang menukarnya (kitab Allah) dengan sihir itu, tiadalah baginya keuntungan di akhirat, dan amat jahatlah perbuatan mereka menjual dirinya dengan sihir, kalau mereka mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 103, "text": "وَلَوۡ أَنَّهُمۡ ءَامَنُوا۟ وَٱتَّقَوۡا۟ لَمَثُوبَةࣱ مِّنۡ عِندِ ٱللَّهِ خَیۡرࣱۚ لَّوۡ كَانُوا۟ یَعۡلَمُونَ ۝١٠٣", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "ولو أن اليهود آمنوا وخافوا الله لأيقنوا أن ثواب الله خير لهم من السِّحر ومما اكتسبوه به، لو كانوا يعلمون ما يحصل بالإيمان والتقوى من الثواب والجزاء علما حقيقيا لآمنوا.", "isBasmala": false, "translation_en": "Had they believed and been righteous, the reward from God would have been better, if they only knew.", "translation_id": "Sesungguhnya kalau mereka beriman dan bertakwa, (niscaya mereka akan mendapat pahala), dan sesungguhnya pahala dari sisi Allah adalah lebih baik, kalau mereka mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 104, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَ ٰعِنَا وَقُولُوا۟ ٱنظُرۡنَا وَٱسۡمَعُوا۟ۗ وَلِلۡكَـٰفِرِینَ عَذَابٌ أَلِیمࣱ ۝١٠٤", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "يا أيها الذين آمنوا لا تقولوا للرسول محمد صلى الله عليه وسلم: راعنا، أي: راعنا سمعك، فافهم عنا وأفهمنا؛ لأن اليهود كانوا يقولونها للنبي صلى الله عليه وسلم يلوون ألسنتهم بها، يقصدون سبَّه ونسبته إلى الرعونة، وقولوا- أيها المؤمنون- بدلا منها: انظرنا، أي انظر إلينا وتعهَّدْنا، وهي تؤدي المعنى المطلوب نفسه واسمعوا ما يتلى عليكم من كتاب ربكم وافهموه. وللجاحدين عذاب موجع.", "isBasmala": false, "translation_en": "O you who believe! Do not say ambiguous words, but say words of respect, and listen. The disbelievers will have a painful torment.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu katakan (kepada Muhammad): \"Raa'ina\", tetapi katakanlah: \"Unzhurna\", dan \"dengarlah\". Dan bagi orang-orang yang kafir siksaan yang pedih.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 105, "text": "مَّا یَوَدُّ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ وَلَا ٱلۡمُشۡرِكِینَ أَن یُنَزَّلَ عَلَیۡكُم مِّنۡ خَیۡرࣲ مِّن رَّبِّكُمۡۚ وَٱللَّهُ یَخۡتَصُّ بِرَحۡمَتِهِۦ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ ۝١٠٥", "juz": 1, "hizb": "(*¼ ح 2*)", "tafsir": "ما يحب الكفار من أهل الكتاب والمشركين أن يُنزَّل عليكم أدنى خير من ربكم قرآنًا أو علمًا، أو نصرًا أو بشارة. والله يختص برحمته مَن يشاء مِن عباده بالنبوة والرسالة. والله ذو العطاء الكثير الواسع.", "isBasmala": false, "translation_en": "It is never the wish of the disbelievers from among the People of the Book, nor of the polytheists, that any good should be sent down to you from your Lord. But God chooses for His mercy whomever He wills. God is Possessor of Sublime Grace.", "translation_id": "Orang-orang kafir dari Ahli Kitab dan orang-orang musyrik tiada menginginkan diturunkannya sesuatu kebaikan kepadamu dari Tuhanmu. Dan Allah menentukan siapa yang dikehendaki-Nya (untuk diberi) rahmat-Nya (kenabian); dan Allah mempunyai karunia yang besar.", "manzil": 1, "manzil_display": ""}], "17": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 106, "text": "۞ مَا نَنسَخۡ مِنۡ ءَایَةٍ أَوۡ نُنسِهَا نَأۡتِ بِخَیۡرࣲ مِّنۡهَاۤ أَوۡ مِثۡلِهَاۤۗ أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝١٠٦", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "ما نبدِّل من آية أو نُزِلها من القلوب والأذهان نأت بأنفع لكم منها، أو نأت بمثلها في التكليف والثواب، ولكلٍ حكمة. ألم تعلم -أيها النبي- أنت وأمتك أن الله قادر لا يعجزه شيء؟", "isBasmala": false, "translation_en": "We never nullify a verse, nor cause it to be forgotten, unless We bring one better than it, or similar to it. Do you not know that God is capable of all things?", "translation_id": "Ayat mana saja yang Kami nasakhkan, atau Kami jadikan (manusia) lupa kepadanya, Kami datangkan yang lebih baik daripadanya atau yang sebanding dengannya. Tidakkah kamu mengetahui bahwa sesungguhnya Allah Maha Kuasa atas segala sesuatu?", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 107, "text": "أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۗ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرٍ ۝١٠٧", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "أما علمتَ -أيها النبي- أنت وأمتك أن الله تعالى هو المالك المتصرف في السموات والأرض؟ يفعل ما يشاء، ويحكم ما يريد، ويأمر عباده وينهاهم كيفما شاء، وعليهم الطاعة والقَبول. وليعلم من عصى أن ليس لأحد من دون الله من وليٍّ يتولاهم، ولا نصير يمنعهم من عذاب الله.", "isBasmala": false, "translation_en": "Do you not know that to God belongs the sovereignty of the heavens and the earth, and that apart from God you have no guardian or helper?", "translation_id": "Tiadakah kamu mengetahui bahwa kerajaan langit dan bumi adalah kepunyaan Allah? Dan tiada bagimu selain Allah seorang pelindung maupun seorang penolong.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 108, "text": "أَمۡ تُرِیدُونَ أَن تَسۡـَٔلُوا۟ رَسُولَكُمۡ كَمَا سُىِٕلَ مُوسَىٰ مِن قَبۡلُۗ وَمَن یَتَبَدَّلِ ٱلۡكُفۡرَ بِٱلۡإِیمَـٰنِ فَقَدۡ ضَلَّ سَوَاۤءَ ٱلسَّبِیلِ ۝١٠٨", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "بل أتريدون- أيها الناس- أن تطلبوا من رسولكم محمد صلى الله عليه وسلم أشياء بقصد العناد والمكابرة، كما طُلِبَ مثل ذلك من موسى. علموا أن من يختر الكفر ويترك الإيمان فقد خرج عن صراط الله المستقيم إلى الجهل والضَّلال.", "isBasmala": false, "translation_en": "Or do you want to question your Messenger as Moses was questioned before? Whoever exchanges faith for disbelief has strayed from the right path.", "translation_id": "Apakah kamu menghendaki untuk meminta kepada Rasul kamu seperti Bani Israil meminta kepada Musa pada jaman dahulu? Dan barangsiapa yang menukar iman dengan kekafiran, maka sungguh orang itu telah sesat dari jalan yang lurus.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 109, "text": "وَدَّ كَثِیرࣱ مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ لَوۡ یَرُدُّونَكُم مِّنۢ بَعۡدِ إِیمَـٰنِكُمۡ كُفَّارًا حَسَدࣰا مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَیَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُوا۟ وَٱصۡفَحُوا۟ حَتَّىٰ یَأۡتِیَ ٱللَّهُ بِأَمۡرِهِۦۤۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝١٠٩", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "تمنى كثير من أهل الكتاب أن يرجعوكم بعد إيمانكم كفارًا كما كنتم من قبلُ تعبدون الأصنام؛ بسبب الحقد الذي امتلأت به نفوسهم من بعد ما تبيَّن لهم صدق نبي الله ورسوله محمد صلى الله عليه وسلم فيما جاء به، فتجاوزوا عمَّا كان منهم من إساءة وخطأ، واصفحوا عن جهلهم، حتى يأتي الله بحكمه فيهم بقتالهم (وقد جاء ووقع)، وسيعاقبهم لسوء أفعالهم. إن الله على كل شيء قدير لا يعجزه شيء.", "isBasmala": false, "translation_en": "Many of the People of the Book wish to turn you back into unbelievers after you have believed, out of envy on their part, after the Truth has become clear to them. But pardon and overlook, until God brings His command. God has power over all things.", "translation_id": "Sebahagian besar Ahli Kitab menginginkan agar mereka dapat mengembalikan kamu kepada kekafiran setelah kamu beriman, karena dengki yang (timbul) dari diri mereka sendiri, setelah nyata bagi mereka kebenaran. Maka maafkanlah dan biarkanlah mereka, sampai Allah mendatangkan perintah-Nya. Sesungguhnya Allah Maha Kuasa atas segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 110, "text": "وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنۡ خَیۡرࣲ تَجِدُوهُ عِندَ ٱللَّهِۗ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِیرࣱ ۝١١٠", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "واشتغلوا -أيها المؤمنون- بأداء الصلاة على وجهها الصحيح، وإعطاء الزكاة المفروضة. واعلموا أنَّ كل خير تقدمونه لأنفسكم تجدون ثوابه عند الله في الآخرة. إنه تعالى بصير بكل أعمالكم، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "And perform the prayer, and give alms. Whatever good you forward for yourselves, you will find it with God. God is Seeing of everything you do.", "translation_id": "Dan dirikanlah shalat dan tunaikanlah zakat. Dan kebaikan apa saja yang kamu usahakan bagi dirimu, tentu kamu akan mendapat pahala nya pada sisi Allah. Sesungguhnya Alah Maha Melihat apa-apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 111, "text": "وَقَالُوا۟ لَن یَدۡخُلَ ٱلۡجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوۡ نَصَـٰرَىٰۗ تِلۡكَ أَمَانِیُّهُمۡۗ قُلۡ هَاتُوا۟ بُرۡهَـٰنَكُمۡ إِن كُنتُمۡ صَـٰدِقِینَ ۝١١١", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "ادَّعى كلٌّ من اليهود والنصارى أن الجنة خاصة بطائفته لا يدخلها غيرهم، تلك أوهامهم الفاسدة. قل لهم -أيها الرسول-: أحضروا دليلكم على صحة ما تدَّعون إن كنتم صادقين في دعواكم.", "isBasmala": false, "translation_en": "And they say, \"None will enter Heaven unless he is a Jew or a Christian.\" These are their wishes. Say, \"Produce your proof, if you are truthful.\"", "translation_id": "Dan mereka (Yahudi dan Nasrani) berkata: \"Sekali-kali tidak akan masuk surga kecuali orang-orang (yang beragama) Yahudi atau Nasrani\". Demikian itu (hanya) angan-angan mereka yang kosong belaka. Katakanlah: \"Tunjukkanlah bukti kebenaranmu jika kamu adalah orang yang benar\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 112, "text": "بَلَىٰۚ مَنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنࣱ فَلَهُۥۤ أَجۡرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝١١٢", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "ليس الأمر كما زعموا أنَّ الجنة تختص بطائفة دون غيرها، وإنما يدخل الجنَّة مَن أخلص لله وحده لا شريك له، وهو متبع للرسول محمد صلى الله عليه وسلم في كل أقواله وأعماله. فمن فعل ذلك فله ثواب عمله عند ربه في الآخرة، وهو دخول الجنة، وهم لا يخافون فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا.", "isBasmala": false, "translation_en": "In fact, whoever submits himself to God, and is a doer of good, will have his reward with his Lord-they have nothing to fear, nor shall they grieve.", "translation_id": "(Tidak demikian) bahkan barangsiapa yang menyerahkan diri kepada Allah, sedang ia berbuat kebajikan, maka baginya pahala pada sisi Tuhannya dan tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.", "manzil": 1, "manzil_display": ""}], "18": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 113, "text": "وَقَالَتِ ٱلۡیَهُودُ لَیۡسَتِ ٱلنَّصَـٰرَىٰ عَلَىٰ شَیۡءࣲ وَقَالَتِ ٱلنَّصَـٰرَىٰ لَیۡسَتِ ٱلۡیَهُودُ عَلَىٰ شَیۡءࣲ وَهُمۡ یَتۡلُونَ ٱلۡكِتَـٰبَۗ كَذَ ٰلِكَ قَالَ ٱلَّذِینَ لَا یَعۡلَمُونَ مِثۡلَ قَوۡلِهِمۡۚ فَٱللَّهُ یَحۡكُمُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ ۝١١٣", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "وقالت اليهود: ليست النصارى على شيء من الدين الصحيح، وكذلك قالت النصارى في اليهود وهم يقرؤون التوراة والإنجيل، وفيهما وجوب الإيمان بالأنبياء جميعًا. كذلك قال الذين لا يعلمون من مشركي العرب وغيرهم مثل قولهم، أي قالوا لكل ذي دين: لست على شيء، فالله يفصل بينهم يوم القيامة فيما اختلفوا فيه مِن أمر الدين، ويجازي كلا بعمله.", "isBasmala": false, "translation_en": "The Jews say, \"The Christians are not based on anything;\" and the Christians say, \"The Jews are not based on anything.\" Yet they both read the Scripture. Similarly, the ignorant said the same thing. God will judge between them on the Day of Resurrection regarding their differences.", "translation_id": "Dan orang-orang Yahudi berkata: \"Orang-orang Nasrani itu tidak mempunyai suatu pegangan\", dan orang-orang Nasrani berkata: \"Orang-orang Yahudi tidak mempunyai sesuatu pegangan,\" padahal mereka (sama-sama) membaca Al Kitab. Demikian pula orang-orang yang tidak mengetahui, mengatakan seperti ucapan mereka itu. Maka Allah akan mengadili diantara mereka pada hari Kiamat, tentang apa-apa yang mereka berselisih padanya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 114, "text": "وَمَنۡ أَظۡلَمُ مِمَّن مَّنَعَ مَسَـٰجِدَ ٱللَّهِ أَن یُذۡكَرَ فِیهَا ٱسۡمُهُۥ وَسَعَىٰ فِی خَرَابِهَاۤۚ أُو۟لَـٰۤىِٕكَ مَا كَانَ لَهُمۡ أَن یَدۡخُلُوهَاۤ إِلَّا خَاۤىِٕفِینَۚ لَهُمۡ فِی ٱلدُّنۡیَا خِزۡیࣱ وَلَهُمۡ فِی ٱلۡـَٔاخِرَةِ عَذَابٌ عَظِیمࣱ ۝١١٤", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "لا أحد أظلم من الذين منعوا ذِكْرَ الله في المساجد من إقام الصلاة، وتلاوة القرآن، ونحو ذلك، وجدُّوا في تخريبها بالهدم أو الإغلاق، أو بمنع المؤمنين منها. أولئك الظالمون ما كان ينبغي لهم أن يدخلوا المساجد إلا على خوف ووجل من العقوبة، لهم بذلك صَغار وفضيحة في الدنيا، ولهم في الآخرة عذاب شديد.", "isBasmala": false, "translation_en": "Who is more unjust than him who forbids the remembrance of God's name in places of worship, and contributes to their ruin? These ought not to enter them except in fear. For them is disgrace in this world, and for them is a terrible punishment in the Hereafter.", "translation_id": "Dan siapakah yang lebih aniaya daripada orang yang menghalanghalangi menyebut nama Allah dalam mesjid-mesjid-Nya, dan berusaha untuk merobohkannya? Mereka itu tidak sepatutnya masuk ke dalamnya (mesjid Allah), kecuali dengan rasa takut (kepada Allah). Mereka di dunia mendapat kehinaan dan di akhirat mendapat siksa yang berat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 115, "text": "وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَیۡنَمَا تُوَلُّوا۟ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَ ٰسِعٌ عَلِیمࣱ ۝١١٥", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "ولله جهتا شروق الشمس وغروبها وما بينهما، فهو مالك الأرض كلها. فأي جهة توجهتم إليها في الصلاة بأمر الله لكم فإنكم مبتغون وجهه، لم تخرجوا عن ملكه وطاعته. إن الله واسع الرحمة بعباده، عليم بأفعالهم، لا يغيب عنه منها شيء.", "isBasmala": false, "translation_en": "To God belong the East and the West. Whichever way you turn, there is God's presence. God is Omnipresent and Omniscient.", "translation_id": "Dan kepunyaan Allah-lah timur dan barat, maka kemanapun kamu menghadap di situlah wajah Allah. Sesungguhnya Allah Maha Luas (rahmat-Nya) lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 116, "text": "وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدࣰاۗ سُبۡحَـٰنَهُۥۖ بَل لَّهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ كُلࣱّ لَّهُۥ قَـٰنِتُونَ ۝١١٦", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "وقالت اليهود والنصارى والمشركون: اتخذ الله لنفسه ولدًا، تنزَّه الله -سبحانه- عن هذا القول الباطل، بل كل مَن في السموات والأرض ملكه وعبيده، وهم جميعًا خاضعون له، مسخَّرون تحت تدبيره.", "isBasmala": false, "translation_en": "And they say, \"God has begotten a son.\" Be He glorified. Rather, His is everything in the heavens and the earth; all are obedient to Him.", "translation_id": "Mereka (orang-orang kafir) berkata: \"Allah mempunyai anak\". Maha Suci Allah, bahkan apa yang ada di langit dan di bumi adalah kepunyaan Allah; semua tunduk kepada-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 117, "text": "بَدِیعُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ وَإِذَا قَضَىٰۤ أَمۡرࣰا فَإِنَّمَا یَقُولُ لَهُۥ كُن فَیَكُونُ ۝١١٧", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "والله تعالى هو خالق السموات والأرض على غير مثال سبق. وإذا قدَّر أمرًا وأراد كونه فإنما يقول له: \"كن\" فيكون.", "isBasmala": false, "translation_en": "Originator of the heavens and the earth. Whenever He decrees a thing, He says to it, \"Be,\" and it becomes.", "translation_id": "Allah Pencipta langit dan bumi, dan bila Dia berkehendak (untuk menciptakan) sesuatu, maka (cukuplah) Dia hanya mengatakan kepadanya: \"Jadilah!\" Lalu jadilah ia.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 118, "text": "وَقَالَ ٱلَّذِینَ لَا یَعۡلَمُونَ لَوۡلَا یُكَلِّمُنَا ٱللَّهُ أَوۡ تَأۡتِینَاۤ ءَایَةࣱۗ كَذَ ٰلِكَ قَالَ ٱلَّذِینَ مِن قَبۡلِهِم مِّثۡلَ قَوۡلِهِمۡۘ تَشَـٰبَهَتۡ قُلُوبُهُمۡۗ قَدۡ بَیَّنَّا ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یُوقِنُونَ ۝١١٨", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "وقال الجهلة من أهل الكتاب وغيرهم لنبي الله ورسوله محمد صلى الله عليه وسلم على سبيل العناد: هلا يكلمنا الله مباشرة ليخبرنا أنك رسوله، أو تأتينا معجزة من الله تدل على صدقك. ومثل هذا القول قالته الأمم من قبلُ لرسلها عنادًا ومكابرة؛ بسبب تشابه قلوب السابقين واللاحقين في الكفر والضَّلال، قد أوضحنا الآيات للذين يصدِّقون تصديقًا جازمًا؛ لكونهم مؤمنين بالله تعالى، متَّبعين ما شرعه لهم.", "isBasmala": false, "translation_en": "Those who do not know say, \"If only God would speak to us, or a sign would come to us.\" Thus said those who were before them. Their hearts are alike. We have made the signs clear for people who are certain.", "translation_id": "Dan orang-orang yang tidak mengetahui berkata: \"Mengapa Allah tidak (langsung) berbicara dengan kami atau datang tanda-tanda kekuasaan-Nya kepada kami?\" Demikian pula orang-orang yang sebelum mereka telah mengatakan seperti ucapan mereka itu; hati mereka serupa. Sesungguhnya Kami telah menjelaskan tanda-tanda kekuasaan Kami kepada kaum yang yakin.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 119, "text": "إِنَّاۤ أَرۡسَلۡنَـٰكَ بِٱلۡحَقِّ بَشِیرࣰا وَنَذِیرࣰاۖ وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَـٰبِ ٱلۡجَحِیمِ ۝١١٩", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "إنا أرسلناك -أيها الرسول- بالدين الحق المؤيد بالحجج والمعجزات، فبلِّغه للناس مع تبشير المؤمنين بخيري الدنيا والآخرة، وتخويف المعاندين بما ينتظرهم من عذاب الله، ولست -بعد البلاغ- مسئولا عن كفر مَن كفر بك؛ فإنهم يدخلون النار يوم القيامة، ولا يخرجون منها.", "isBasmala": false, "translation_en": "We have sent you with the truth-bringing good news, and giving warnings. You will not be questioned about the inmates of Hell.", "translation_id": "Sesungguhnya Kami telah mengutusmu (Muhammad) dengan kebenaran; sebagai pembawa berita gembira dan pemberi peringatan, dan kamu tidak akan diminta (pertanggungan jawab) tentang penghuni-penghuni neraka.", "manzil": 1, "manzil_display": ""}], "19": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 120, "text": "وَلَن تَرۡضَىٰ عَنكَ ٱلۡیَهُودُ وَلَا ٱلنَّصَـٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۗ وَلَىِٕنِ ٱتَّبَعۡتَ أَهۡوَاۤءَهُم بَعۡدَ ٱلَّذِی جَاۤءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرٍ ۝١٢٠", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "ولن ترضى عنك -أيها الرسول- اليهود ولا النصارى إلا إذا تركت دينك واتبعتَ دينهم. قل لهم: إن دين الإسلام هو الدين الصحيح. ولئن اتبعت أهواء هؤلاء بعد الذي جاءك من الوحي ما لك عند الله مِن وليٍّ ينفعك، ولا نصير ينصرك. هذا موجه إلى الأمّة عامة وإن كان خطابًا للنبي صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "The Jews and the Christians will not approve of you, unless you follow their creed. Say, \"God's guidance is the guidance.\" Should you follow their desires, after the knowledge that has come to you, you will have in God neither guardian nor helper.", "translation_id": "Orang-orang Yahudi dan Nasrani tidak akan senang kepada kamu hingga kamu mengikuti agama mereka. Katakanlah: \"Sesungguhnya petunjuk Allah itulah petunjuk (yang benar)\". Dan sesungguhnya jika kamu mengikuti kemauan mereka setelah pengetahuan datang kepadamu, maka Allah tidak lagi menjadi pelindung dan penolong bagimu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 121, "text": "ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَتۡلُونَهُۥ حَقَّ تِلَاوَتِهِۦۤ أُو۟لَـٰۤىِٕكَ یُؤۡمِنُونَ بِهِۦۗ وَمَن یَكۡفُرۡ بِهِۦ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ ۝١٢١", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "الذين أعطيناهم الكتاب من اليهود والنصارى، يقرؤونه القراءة الصحيحة، ويتبعونه حق الاتباع، ويؤمنون بما جاء فيه من الإيمان برسل الله، ومنهم خاتمهم نبينا ورسولنا محمد صلى الله عليه وسلم، ولا يحرفون ولا يبدِّلون ما جاء فيه. هؤلاء هم الذين يؤمنون بالنبي محمد صلى الله عليه وسلم وبما أنزل عليه، وأما الذين بدَّلوا بعض الكتاب وكتموا بعضه، فهؤلاء كفار بنبي الله محمد صلى الله عليه وسلم وبما أنزل عليه، ومن يكفر به فأولئك هم أشد الناس خسرانًا عند الله.", "isBasmala": false, "translation_en": "Those to whom We have given the Scripture follow it, as it ought to be followed-these believe in it. But as for those who reject it-these are the losers.", "translation_id": "Orang-orang yang telah Kami berikan Al Kitab kepadanya, mereka membacanya dengan bacaan yang sebenarnya, mereka itu beriman kepadanya. Dan barangsiapa yang ingkar kepadanya, maka mereka itulah orang-orang yang rugi.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 122, "text": "یَـٰبَنِیۤ إِسۡرَ ٰۤءِیلَ ٱذۡكُرُوا۟ نِعۡمَتِیَ ٱلَّتِیۤ أَنۡعَمۡتُ عَلَیۡكُمۡ وَأَنِّی فَضَّلۡتُكُمۡ عَلَى ٱلۡعَـٰلَمِینَ ۝١٢٢", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "يا ذرية يعقوب اذكروا نعمي الكثيرة عليكم، وأني فَضَّلتكم على عالَمي زمانكم بكثرة أنبيائكم، وما أُنزل عليهم من الكتب.", "isBasmala": false, "translation_en": "O Children of Israel! Remember My blessing which I bestowed upon you, and that I have favored you over all people.", "translation_id": "Hai Bani Israil, ingatlah akan nikmat-Ku yang telah Ku-anugerahkan kepadamu dan Aku telah melabihkan kamu atas segala umat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 123, "text": "وَٱتَّقُوا۟ یَوۡمࣰا لَّا تَجۡزِی نَفۡسٌ عَن نَّفۡسࣲ شَیۡـࣰٔا وَلَا یُقۡبَلُ مِنۡهَا عَدۡلࣱ وَلَا تَنفَعُهَا شَفَـٰعَةࣱ وَلَا هُمۡ یُنصَرُونَ ۝١٢٣", "juz": 1, "hizb": "(*½ ح 2*)", "tafsir": "وخافوا أهوال يوم الحساب إذ لا تغني نفس عن نفس شيئًا، ولا يقبل الله منها فدية تنجيها من العذاب، ولا تنفعها وساطة، ولا أحد ينصرها.", "isBasmala": false, "translation_en": "And beware of a Day when no soul will avail another soul in any way, and no ransom will be accepted from it, and no intercession will benefit it, and they will not be helped.", "translation_id": "Dan takutlah kamu kepada suatu hari di waktu seseorang tidak dapat menggantikan seseorang lain sedikitpun dan tidak akan diterima suatu tebusan daripadanya dan tidak akan memberi manfaat sesuatu syafa'at kepadanya dan tidak (pula) mereka akan ditolong.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 124, "text": "۞ وَإِذِ ٱبۡتَلَىٰۤ إِبۡرَ ٰهِـۧمَ رَبُّهُۥ بِكَلِمَـٰتࣲ فَأَتَمَّهُنَّۖ قَالَ إِنِّی جَاعِلُكَ لِلنَّاسِ إِمَامࣰاۖ قَالَ وَمِن ذُرِّیَّتِیۖ قَالَ لَا یَنَالُ عَهۡدِی ٱلظَّـٰلِمِینَ ۝١٢٤", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "واذكر-أيها النبي- حين اختبر الله إبراهيم بما شرع له من تكاليف، فأدَّاها وقام بها خير قيام. قال الله له: إني جاعلك قدوة للناس. قال إبراهيم: ربِّ اجعل بعض نسلي أئمة فضلا منك، فأجابه الله سبحانه أنه لا تحصل للظالمين الإمامةُ في الدين.", "isBasmala": false, "translation_en": "And when his Lord tested Abraham with certain words, and he fulfilled them. He said, \"I am making you a leader of humanity.\" He said, \"And my descendants?\" He said, \"My pledge does not include the wrongdoers.\"", "translation_id": "Dan (ingatlah), ketika Ibrahim diuji Tuhannya dengan beberapa kalimat (perintah dan larangan), lalu Ibrahim menunaikannya. Allah berfirman: \"Sesungguhnya Aku akan menjadikanmu imam bagi seluruh manusia\". Ibrahim berkata: \"(Dan saya mohon juga) dari keturunanku\". Allah berfirman: \"Janji-Ku (ini) tidak mengenai orang yang zalim\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 125, "text": "وَإِذۡ جَعَلۡنَا ٱلۡبَیۡتَ مَثَابَةࣰ لِّلنَّاسِ وَأَمۡنࣰا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبۡرَ ٰهِـۧمَ مُصَلࣰّىۖ وَعَهِدۡنَاۤ إِلَىٰۤ إِبۡرَ ٰهِـۧمَ وَإِسۡمَـٰعِیلَ أَن طَهِّرَا بَیۡتِیَ لِلطَّاۤىِٕفِینَ وَٱلۡعَـٰكِفِینَ وَٱلرُّكَّعِ ٱلسُّجُودِ ۝١٢٥", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "واذكر -أيها النبي- حين جعلنا الكعبة مرجعًا للناس، يأتونه، ثم يرجعون إلى أهليهم، ثم يعودون إليه، ومجمعًا لهم في الحج والعمرة والطواف والصلاة، وأمنًا لهم، لا يُغِير عليهم عدو فيه. وقلنا: اتخِذوا من مقام إبراهيم مكانًا للصلاة فيه، وهو الحجر الذي وقف عليه إبراهيم عند بنائه الكعبة. وأوحينا إلى إبراهيم وابنه إسماعيل: أن طهِّرا بيتي من كل رجس ودنس؛ للمتعبدين فيه بالطواف حول الكعبة، أو الاعتكاف في المسجد، والصلاة فيه.", "isBasmala": false, "translation_en": "And We made the House a focal point for the people, and a sanctuary. Use the shrine of Abraham as a place of prayer. And We commissioned Abraham and Ishmael, \"Sanctify My House for those who circle around it, and those who seclude themselves in it, and those who kneel and prostrate.\"", "translation_id": "Dan (ingatlah), ketika Kami menjadikan rumah itu (Baitullah) tempat berkumpul bagi manusia dan tempat yang aman. Dan jadikanlah sebahagian maqam Ibrahim tempat shalat. Dan telah Kami perintahkan kepada Ibrahim dan Ismail: \"Bersihkanlah rumah-Ku untuk orang-orang yang thawaf, yang i'tikaf, yang ruku' dan yang sujud\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 126, "text": "وَإِذۡ قَالَ إِبۡرَ ٰهِـۧمُ رَبِّ ٱجۡعَلۡ هَـٰذَا بَلَدًا ءَامِنࣰا وَٱرۡزُقۡ أَهۡلَهُۥ مِنَ ٱلثَّمَرَ ٰتِ مَنۡ ءَامَنَ مِنۡهُم بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِیلࣰا ثُمَّ أَضۡطَرُّهُۥۤ إِلَىٰ عَذَابِ ٱلنَّارِۖ وَبِئۡسَ ٱلۡمَصِیرُ ۝١٢٦", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "واذكر -أيها النبي- حين قال إبراهيم داعيًا: ربِّ اجعل \"مكة\" بلدًا آمنًا من الخوف، وارزق أهله من أنواع الثمرات، وخُصَّ بهذا الرزق مَن آمن منهم بالله واليوم الآخر. قال الله: ومن كفر منهم فأرزقه في الدنيا وأُمتعه متاعًا قليلا ثم أُلجئُه مرغمًا إلى عذاب النار. وبئس المرجع والمقام هذا المصير.", "isBasmala": false, "translation_en": "When Abraham said, \"O My Lord, make this a peaceful land, and provide its people with fruits-whoever of them believes in God and the Last Day.\" He said, \"And whoever disbelieves, I will give him a little enjoyment, then I will consign him to the punishment of the Fire; how miserable the destiny!\"", "translation_id": "Dan (ingatlah), ketika Ibrahim berdoa: \"Ya Tuhanku, jadikanlah negeri ini, negeri yang aman sentosa, dan berikanlah rezeki dari buah-buahan kepada penduduknya yang beriman diantara mereka kepada Allah dan hari kemudian. Allah berfirman: \"Dan kepada orang yang kafirpun Aku beri kesenangan sementara, kemudian Aku paksa ia menjalani siksa neraka dan itulah seburuk-buruk tempat kembali\".", "manzil": 1, "manzil_display": ""}], "20": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 127, "text": "وَإِذۡ یَرۡفَعُ إِبۡرَ ٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَیۡتِ وَإِسۡمَـٰعِیلُ رَبَّنَا تَقَبَّلۡ مِنَّاۤۖ إِنَّكَ أَنتَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝١٢٧", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "واذكر -أيها النبي- حين رفع إبراهيم وإسماعيل أسس الكعبة، وهما يدعوان الله في خشوع: ربنا تقبل منَّا صالح أعمالنا ودعاءنا، إنك أنت السميع لأقوال عبادك، العليم بأحوالهم.", "isBasmala": false, "translation_en": "As Abraham raises the foundations of the House, together with Ishmael, \"Our Lord, accept it from us, You are the Hearer, the Knower.", "translation_id": "Dan (ingatlah), ketika Ibrahim meninggikan (membina) dasar-dasar Baitullah bersama Ismail (seraya berdoa): \"Ya Tuhan kami terimalah daripada kami (amalan kami), sesungguhnya Engkaulah Yang Maha Mendengar lagi Maha Mengetahui\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 128, "text": "رَبَّنَا وَٱجۡعَلۡنَا مُسۡلِمَیۡنِ لَكَ وَمِن ذُرِّیَّتِنَاۤ أُمَّةࣰ مُّسۡلِمَةࣰ لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبۡ عَلَیۡنَاۤۖ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِیمُ ۝١٢٨", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "ربنا واجعلنا ثابتَيْن على الإسلام، منقادَيْن لأحكامك، واجعل من ذريتنا أمة منقادة لك، بالإيمان، وبصِّرْنا بمعالم عبادتنا لك، وتجاوز عن ذنوبنا. إنك أنت كثير التوبة والرحمة لعبادك.", "isBasmala": false, "translation_en": "Our Lord, and make us submissive to You, and from our descendants a community submissive to You. And show us our rites, and accept our repentance. You are the Acceptor of Repentance, the Merciful.", "translation_id": "Ya Tuhan kami, jadikanlah kami berdua orang yang tunduk patuh kepada Engkau dan (jadikanlah) diantara anak cucu kami umat yang tunduk patuh kepada Engkau dan tunjukkanlah kepada kami cara-cara dan tempat-tempat ibadat haji kami, dan terimalah taubat kami. Sesungguhnya Engkaulah Yang Maha Penerima taubat lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 129, "text": "رَبَّنَا وَٱبۡعَثۡ فِیهِمۡ رَسُولࣰا مِّنۡهُمۡ یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِكَ وَیُعَلِّمُهُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَیُزَكِّیهِمۡۖ إِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝١٢٩", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "ربنا وابعث في هذه الأمة رسولا من ذرية إسماعيل يتلو عليهم آياتك ويعلمهم القرآن والسنة، ويطهرهم من الشرك وسوء الأخلاق. إنك أنت العزيز الذي لا يمتنع عليه شيء، الحكيم الذي يضع الأشياء في مواضعها.", "isBasmala": false, "translation_en": "Our Lord, and raise up among them a messenger, of themselves, who will recite to them Your revelations, and teach them the Book and wisdom, and purify them. You are the Almighty, the Wise.\"", "translation_id": "Ya Tuhan kami, utuslah untuk mereka sesorang Rasul dari kalangan mereka, yang akan membacakan kepada mereka ayat-ayat Engkau, dan mengajarkan kepada mereka Al Kitab (Al Quran) dan Al-Hikmah (As-Sunnah) serta mensucikan mereka. Sesungguhnya Engkaulah yang Maha Kuasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 130, "text": "وَمَن یَرۡغَبُ عَن مِّلَّةِ إِبۡرَ ٰهِـۧمَ إِلَّا مَن سَفِهَ نَفۡسَهُۥۚ وَلَقَدِ ٱصۡطَفَیۡنَـٰهُ فِی ٱلدُّنۡیَاۖ وَإِنَّهُۥ فِی ٱلۡـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِینَ ۝١٣٠", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "ولا أحد يُعرض عن دين إبراهيم -وهو الإسلام- إلا سفيه جاهل، ولقد اخترنا إبراهيم في الدنيا نبيًّا ورسولا وإنه في الآخرة لمن الصالحين الذين لهم أعلى الدرجات.", "isBasmala": false, "translation_en": "Who would forsake the religion of Abraham, except he who fools himself? We chose him in this world, and in the Hereafter he will be among the righteous.", "translation_id": "Dan tidak ada yang benci kepada agama Ibrahim, melainkan orang yang memperbodoh dirinya sendiri, dan sungguh Kami telah memilihnya di dunia dan sesungguhnya dia di akhirat benar-benar termasuk orang-orang yang saleh.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 131, "text": "إِذۡ قَالَ لَهُۥ رَبُّهُۥۤ أَسۡلِمۡۖ قَالَ أَسۡلَمۡتُ لِرَبِّ ٱلۡعَـٰلَمِینَ ۝١٣١", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "وسبب هذا الاختيار مسارعته للإسلام دون تردد، حين قال له ربه: أخلص نفسك لله منقادًا له. فاستجاب إبراهيم وقال: أسلمت لرب العالمين إخلاصًا وتوحيدًا ومحبة وإنابة.", "isBasmala": false, "translation_en": "When his Lord said to him, \"Submit!\" He said, \"I have submitted to the Lord of the Worlds.\"", "translation_id": "Ketika Tuhannya berfirman kepadanya: \"Tunduk patuhlah!\" Ibrahim menjawab: \"Aku tunduk patuh kepada Tuhan semesta alam\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 132, "text": "وَوَصَّىٰ بِهَاۤ إِبۡرَ ٰهِـۧمُ بَنِیهِ وَیَعۡقُوبُ یَـٰبَنِیَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّینَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ ۝١٣٢", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "وحثَّ إبراهيمُ ويعقوبُ أبناءهما على الثبات على الإسلام قائلَيْن: يا أبناءنا إن الله اختار لكم هذا الدين- وهو دين الإسلام الذي جاء به محمد صلى الله عليه وسلم- فلا تفارقوه أيام حياتكم، ولا يأتكم الموت إلا وأنتم عليه.", "isBasmala": false, "translation_en": "And Abraham exhorted his sons, and Jacob, \"O my sons, God has chosen this religion for you, so do not die unless you have submitted.\"", "translation_id": "Dan Ibrahim telah mewasiatkan ucapan itu kepada anak-anaknya, demikian pula Ya'qub. (Ibrahim berkata): \"Hai anak-anakku! Sesungguhnya Allah telah memilih agama ini bagimu, maka janganlah kamu mati kecuali dalam memeluk agama Islam\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 133, "text": "أَمۡ كُنتُمۡ شُهَدَاۤءَ إِذۡ حَضَرَ یَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِیهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِیۖ قَالُوا۟ نَعۡبُدُ إِلَـٰهَكَ وَإِلَـٰهَ ءَابَاۤىِٕكَ إِبۡرَ ٰهِـۧمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ إِلَـٰهࣰا وَ ٰحِدࣰا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ۝١٣٣", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "أكنتم أيها اليهود حاضرين حين جاء الموتُ يعقوبَ، إذ جمع أبناءه وسألهم ما تعبدون من بعد موتي؟ قالوا: نعبد إلهك وإله آبائك إبراهيم وإسماعيل وإسحاق إلهًا واحدًا، ونحن له منقادون خاضعون.", "isBasmala": false, "translation_en": "Or were you witnesses when death approached Jacob, and he said to his sons, \"What will you worship after Me?\" They said, \"We will worship your God, and the God of your fathers, Abraham, Ishmael, and Isaac; One God; and to Him we submit.\"", "translation_id": "Adakah kamu hadir ketika Ya'qub kedatangan (tanda-tanda) maut, ketika ia berkata kepada anak-anaknya: \"Apa yang kamu sembah sepeninggalku?\" Mereka menjawab: \"Kami akan menyembah Tuhanmu dan Tuhan nenek moyangmu, Ibrahim, Ismail dan Ishaq, (yaitu) Tuhan Yang Maha Esa dan kami hanya tunduk patuh kepada-Nya\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 134, "text": "تِلۡكَ أُمَّةࣱ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُوا۟ یَعۡمَلُونَ ۝١٣٤", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "تلك أُمَّة من أسلافكم قد مضَتْ، لهم أعمالهم، ولكم أعمَالكم، ولا تُسْألون عن أعمالهم، وهم لا يُسْألون عن أعمالكم، وكلٌّ سيجازى بما فعله، لا يؤاخذ أحد بذنب أحد، ولا ينفعُ أحدًا إلا إيمانُه وتقواه.", "isBasmala": false, "translation_en": "That was a community that has passed; for them is what they have earned, and for you is what you have earned; and you will not be questioned about what they used to do.", "translation_id": "Itu adalah umat yang lalu; baginya apa yang telah diusahakannya dan bagimu apa yang sudah kamu usahakan, dan kamu tidak akan diminta pertanggungan jawab tentang apa yang telah mereka kerjakan.", "manzil": 1, "manzil_display": ""}], "21": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 135, "text": "وَقَالُوا۟ كُونُوا۟ هُودًا أَوۡ نَصَـٰرَىٰ تَهۡتَدُوا۟ۗ قُلۡ بَلۡ مِلَّةَ إِبۡرَ ٰهِـۧمَ حَنِیفࣰاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ ۝١٣٥", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "وقالت اليهود لأمَّة محمد صلى الله عليه وسلم: ادخلوا في دين اليهودية تجدوا الهداية، وقالت النصارى لهم مثل ذلك. قل لهم -أيها الرسول-: بل الهداية أن نتبع- جميعًا- ملة إبراهيم، الذي مال عن كل دين باطل إلى دين الحق، وما كان من المشركين بالله تعالى.", "isBasmala": false, "translation_en": "And they say, \"Be Jews or Christians, and you will be guided.\" Say, \"Rather, the religion of Abraham, the Monotheist; he was not an idolater.\"", "translation_id": "Dan mereka berkata: \"Hendaklah kamu menjadi penganut agama Yahudi atau Nasrani, niscaya kamu mendapat petunjuk\". Katakanlah: \"Tidak, melainkan (kami mengikuti) agama Ibrahim yang lurus. Dan bukanlah dia (Ibrahim) dari golongan orang musyrik\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 136, "text": "قُولُوۤا۟ ءَامَنَّا بِٱللَّهِ وَمَاۤ أُنزِلَ إِلَیۡنَا وَمَاۤ أُنزِلَ إِلَىٰۤ إِبۡرَ ٰهِـۧمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَاۤ أُوتِیَ مُوسَىٰ وَعِیسَىٰ وَمَاۤ أُوتِیَ ٱلنَّبِیُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَیۡنَ أَحَدࣲ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ۝١٣٦", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "قولوا -أيها المؤمنون- لهؤلاء اليهود والنَّصارى: صدَّقنا بالله الواحد المعبود بحق، وبما أنزل إلينا من القرآن الذي أوحاه الله إلى نبيه ورسوله محمد صلى الله عليه وسلم، وما أنزل من الصحف إلى إبراهيم وابنيه إسماعيل وإسحاق، وإلى يعقوب والأسباط -وهم الأنبياء مِن ولد يعقوب الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة- وما أُعطي موسى من التوراة، وعيسى من الإنجيل، وما أُعطي الأنبياء جميعًا من وحي ربهم، لا نفرق بين أحد منهم في الإيمان، ونحن خاضعون لله بالطاعة والعبادة.", "isBasmala": false, "translation_en": "Say, \"We believe in God; and in what was revealed to us; and in what was revealed to Abraham, and Ishmael, and Isaac, and Jacob, and the Patriarchs; and in what was given to Moses and Jesus; and in what was given to the prophets-from their Lord. We make no distinction between any of them, and to Him we surrender.\"", "translation_id": "Katakanlah (hai orang-orang mukmin): \"Kami beriman kepada Allah dan apa yang diturunkan kepada kami, dan apa yang diturunkan kepada Ibrahim, Isma'il, Ishaq, Ya'qub dan anak cucunya, dan apa yang diberikan kepada Musa dan Isa serta apa yang diberikan kepada nabi-nabi dari Tuhannya. Kami tidak membeda-bedakan seorangpun diantara mereka dan kami hanya tunduk patuh kepada-Nya\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 137, "text": "فَإِنۡ ءَامَنُوا۟ بِمِثۡلِ مَاۤ ءَامَنتُم بِهِۦ فَقَدِ ٱهۡتَدَوا۟ۖ وَّإِن تَوَلَّوۡا۟ فَإِنَّمَا هُمۡ فِی شِقَاقࣲۖ فَسَیَكۡفِیكَهُمُ ٱللَّهُۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝١٣٧", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "فإنْ آمن الكفار من اليهود والنصارى وغيرهم بمثل الذي آمنتم به، مما جاء به الرسول، فقد اهتدوا إلى الحق، وإن أعرضوا فإنما هم في خلاف شديد، فسيكفيك الله -أيها الرسول- شرَّهم وينصرك عليهم، وهو السميع لأقوالكم، العليم بأحوالكم.", "isBasmala": false, "translation_en": "If they believe in the same as you have believed in, then they have been guided. But if they turn away, then they are in schism. God will protect you against them; for He is the Hearer, the Knower.", "translation_id": "Maka jika mereka beriman kepada apa yang kamu telah beriman kepadanya, sungguh mereka telah mendapat petunjuk; dan jika mereka berpaling, sesungguhnya mereka berada dalam permusuhan (dengan kamu). Maka Allah akan memelihara kamu dari mereka. Dan Dialah Yang Maha Mendengar lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 138, "text": "صِبۡغَةَ ٱللَّهِ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ صِبۡغَةࣰۖ وَنَحۡنُ لَهُۥ عَـٰبِدُونَ ۝١٣٨", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "الزموا دين الله الذي فطركم عليه، فليس هناك أحسنُ مِن فطرة الله التي فطر الناس عليها، فالزموها وقولوا نحن خاضعون مطيعون لربنا في اتباعنا ملَّة إبراهيم.", "isBasmala": false, "translation_en": "God's coloring. And who gives better coloring than God? \"And we are devoted to Him.\"", "translation_id": "Shibghah Allah. Dan siapakah yang lebih baik shibghahnya dari pada Allah? Dan hanya kepada-Nya-lah kami menyembah.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 139, "text": "قُلۡ أَتُحَاۤجُّونَنَا فِی ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمۡ وَلَنَاۤ أَعۡمَـٰلُنَا وَلَكُمۡ أَعۡمَـٰلُكُمۡ وَنَحۡنُ لَهُۥ مُخۡلِصُونَ ۝١٣٩", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "قل -أيها الرسول لأهل الكتاب-: أتجادلوننا في توحيد الله والإخلاص له، وهو رب العالمين جميعًا، لا يختص بقوم دون قوم، ولنا أعمالنا ولكم أعمالكم، ونحن لله مخلصو العبادة والطَّاعة لا نشرك به شيئًا، ولا نعبد أحدًا غيره.", "isBasmala": false, "translation_en": "Say, \"Do you argue with us about God, when He is our Lord and your Lord, and We have our works, and you have your works, and we are sincere to Him?\"", "translation_id": "Katakanlah: \"Apakah kamu memperdebatkan dengan kami tentang Allah, padahal Dia adalah Tuhan kami dan Tuhan kamu; bagi kami amalan kami, dan bagi kamu amalan kamu dan hanya kepada-Nya kami mengikhlaskan hati,", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 140, "text": "أَمۡ تَقُولُونَ إِنَّ إِبۡرَ ٰهِـۧمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ وَٱلۡأَسۡبَاطَ كَانُوا۟ هُودًا أَوۡ نَصَـٰرَىٰۗ قُلۡ ءَأَنتُمۡ أَعۡلَمُ أَمِ ٱللَّهُۗ وَمَنۡ أَظۡلَمُ مِمَّن كَتَمَ شَهَـٰدَةً عِندَهُۥ مِنَ ٱللَّهِۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ ۝١٤٠", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "بل أتقولون مجادلين في الله: إن إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط- وهم الأنبياء الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة من ولد يعقوب- كانوا على دين اليهود أو النصارى؟ وهذا كذب؛ فقد بُعِثوا وماتوا قبل نزول التوراة والإنجيل. قل لهم -أيها الرسول-: أأنتم أعلم بدينهم أم الله تعالى؟ وقد أخبر في القرآن بأنهم كانوا حنفاء مسلمين، ولا أحد أظلم منكم حين تخفون شهادة ثابتة عندكم من الله تعالى، وتدَّعون خلافها افتراء على الله. وما الله بغافل عن شيء من أعمالكم، بل هو مُحْصٍ لها ومجازيكم عليها.", "isBasmala": false, "translation_en": "Or do you say that Abraham, Ishmael, Isaac, Jacob, and the Patriarchs were Jews or Christians? Say, \"Do you know better, or God?\" And who does greater wrong than he who conceals a testimony he has from God? God is not unaware of what you do.", "translation_id": "ataukah kamu (hai orang-orang Yahudi dan Nasrani) mengatakan bahwa Ibrahim, Isma'il, Ishaq, Ya'qub dan anak cucunya, adalah penganut agama Yahudi atau Nasrani?\" Katakanlah: \"Apakah kamu lebih mengetahui ataukah Allah, dan siapakah yang lebih zalim dari pada orang yang menyembunyikan syahadah dari Allah yang ada padanya?\" Dan Allah sekali-kali tiada lengah dari apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 141, "text": "تِلۡكَ أُمَّةࣱ قَدۡ خَلَتۡۖ لَهَا مَا كَسَبَتۡ وَلَكُم مَّا كَسَبۡتُمۡۖ وَلَا تُسۡـَٔلُونَ عَمَّا كَانُوا۟ یَعۡمَلُونَ ۝١٤١", "juz": 1, "hizb": "(*¾ ح 2*)", "tafsir": "تلك أُمَّة من أسلافكم قد مضَتْ، لهم أعمالهم ولكم أعمالكم، ولا تُسْألون عن أعمالهم، وهم لا يُسْألون عن أعمالكم. وفي الآية قطع للتعلق بالمخلوقين، وعدم الاغترار بالانتساب إليهم، وأن العبرة بالإيمان بالله وعبادته وحده، واتباع رسله، وأن من كفر برسول منهم فقد كفر بسائر الرسل.", "isBasmala": false, "translation_en": "That was a community that has passed. To them is what they have earned, and to you is what you have earned. And you will not be questioned about what they used to do.", "translation_id": "Itu adalah umat yang telah lalu; baginya apa yang diusahakannya dan bagimu apa yang kamu usahakan; dan kamu tidak akan diminta pertanggungan jawab tentang apa yang telah mereka kerjakan.", "manzil": 1, "manzil_display": ""}], "22": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 142, "text": "۞ سَیَقُولُ ٱلسُّفَهَاۤءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمۡ عَن قِبۡلَتِهِمُ ٱلَّتِی كَانُوا۟ عَلَیۡهَاۚ قُل لِّلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ یَهۡدِی مَن یَشَاۤءُ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝١٤٢", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "سيقول الجهال وضعاف العقول من اليهود وأمثالهم، في سخرية واعتراض: ما الذي صرف هؤلاء المسلمين عن قبلتهم التي كانوا يُصَلُّون إلى جهتها أول الإسلام؛ (وهي \"بيت المقدس\") قل لهم -أيها الرسول-: المشرق والمغرب وما بينهما ملك لله، فليست جهة من الجهات خارجة عن ملكه، يهدي مَن يشاء من عباده إلى طريق الهداية القويم. وفي هذا إشعار بأن الشأن كله لله في امتثال أوامره، فحيثما وَجَّهَنا تَوَجَّهْنا.", "isBasmala": false, "translation_en": "The ignorant among the people will say, \"What has turned them away from the direction of prayer they once followed?\" Say, \"To God belong the East and the West. He guides whom He wills to a straight path.\"", "translation_id": "Orang-orang yang kurang akalnya diantara manusia akan berkata: \"Apakah yang memalingkan mereka (umat Islam) dari kiblatnya (Baitul Maqdis) yang dahulu mereka telah berkiblat kepadanya?\" Katakanlah: \"Kepunyaan Allah-lah timur dan barat; Dia memberi petunjuk kepada siapa yang dikehendaki-Nya ke jalan yang lurus\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 143, "text": "وَكَذَ ٰلِكَ جَعَلۡنَـٰكُمۡ أُمَّةࣰ وَسَطࣰا لِّتَكُونُوا۟ شُهَدَاۤءَ عَلَى ٱلنَّاسِ وَیَكُونَ ٱلرَّسُولُ عَلَیۡكُمۡ شَهِیدࣰاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِی كُنتَ عَلَیۡهَاۤ إِلَّا لِنَعۡلَمَ مَن یَتَّبِعُ ٱلرَّسُولَ مِمَّن یَنقَلِبُ عَلَىٰ عَقِبَیۡهِۚ وَإِن كَانَتۡ لَكَبِیرَةً إِلَّا عَلَى ٱلَّذِینَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِیُضِیعَ إِیمَـٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفࣱ رَّحِیمࣱ ۝١٤٣", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "وكما هديناكم -أيها المسلمون- إلى الطريق الصحيح في الدين، جعلناكم أمة خيارًا عدولا لتشهدوا على الأمم في الآخرة أن رسلهم بلَّغتهم رسالات ربهم، ويكون الرسول في الآخرة كذلك شهيدًا عليكم أنَّه بلَّغكم رسالة ربه. وما جعلنا -أيها الرسول- قبلة \"بيت المقدس\" التي كنت عليها، ثم صرفناك عنها إلى الكعبة بـ \"مكة\"، إلا ليظهر ما علمناه في الأزل؛ علما يتعلق به الثواب والعقاب لنميز مَن يتبعك ويطيعك ويستقبل معك حيث توجهت، ومَن هو ضعيف الإيمان فينقلب مرتدًا عن دينه لشكه ونفاقه. وإن هذه الحال التي هي تحول المسلم في صلاته من استقبال بيت المقدس إلى استقبال الكعبة لثقيلة شاقة إلا على الذين هداهم ومنّ عليهم بالإيمان والتقوى وما كان الله ليضيع إيمانكم به واتباعكم لرسوله، ويبطل صلاتكم إلى القبلة السابقة. إنه سبحانه وتعالى بالناس لرءوف رحيم.", "isBasmala": false, "translation_en": "Thus We made you a moderate community, that you may be witnesses to humanity, and that the Messenger may be a witness to you. We only established the direction of prayer, which you once followed, that We may distinguish those who follow the Messenger from those who turn on their heels. It is indeed difficult, except for those whom God has guided. But God would never let your faith go to waste. God is Kind towards the people, Merciful.", "translation_id": "Dan demikian (pula) Kami telah menjadikan kamu (umat Islam), umat yang adil dan pilihan agar kamu menjadi saksi atas (perbuatan) manusia dan agar Rasul (Muhammad) menjadi saksi atas (perbuatan) kamu. Dan Kami tidak menetapkan kiblat yang menjadi kiblatmu (sekarang) melainkan agar Kami mengetahui (supaya nyata) siapa yang mengikuti Rasul dan siapa yang membelot. Dan sungguh (pemindahan kiblat) itu terasa amat berat, kecuali bagi orang-orang yang telah diberi petunjuk oleh Allah; dan Allah tidak akan menyia-nyiakan imanmu. Sesungguhnya Allah Maha Pengasih lagi Maha Penyayang kepada manusia.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 144, "text": "قَدۡ نَرَىٰ تَقَلُّبَ وَجۡهِكَ فِی ٱلسَّمَاۤءِۖ فَلَنُوَلِّیَنَّكَ قِبۡلَةࣰ تَرۡضَىٰهَاۚ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَیۡثُ مَا كُنتُمۡ فَوَلُّوا۟ وُجُوهَكُمۡ شَطۡرَهُۥۗ وَإِنَّ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ لَیَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا یَعۡمَلُونَ ۝١٤٤", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "قد نرى تحوُّل وجهك -أيها الرسول- في جهة السماء، مرة بعد مرة؛ انتظارًا لنزول الوحي إليك في شأن القبلة، فلنصرفنك عن \"بيت المقدس\" إلى قبلة تحبها وترضاها، وهي وجهة المسجد الحرام بـ \"مكة\"، فولِّ وجهك إليها. وفي أي مكان كنتم -أيها المسلمون- وأردتم الصلاة فتوجهوا نحو المسجد الحرام. وإن الذين أعطاهم الله علم الكتاب من اليهود والنصارى لَيعلمون أن تحويلك إلى الكعبة هو الحق الثابت في كتبهم. وما الله بغافل عما يعمل هؤلاء المعترضون المشككون، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "We have seen your face turned towards the heaven. So We will turn you towards a direction that will satisfy you. So turn your face towards the Sacred Mosque. And wherever you may be, turn your faces towards it. Those who were given the Book know that it is the Truth from their Lord; and God is not unaware of what they do.", "translation_id": "Sungguh Kami (sering) melihat mukamu menengadah ke langit, maka sungguh Kami akan memalingkan kamu ke kiblat yang kamu sukai. Palingkanlah mukamu ke arah Masjidil Haram. Dan dimana saja kamu berada, palingkanlah mukamu ke arahnya. Dan sesungguhnya orang-orang (Yahudi dan Nasrani) yang diberi Al Kitab (Taurat dan Injil) memang mengetahui, bahwa berpaling ke Masjidil Haram itu adalah benar dari Tuhannya; dan Allah sekali-kali tidak lengah dari apa yang mereka kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 145, "text": "وَلَىِٕنۡ أَتَیۡتَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ بِكُلِّ ءَایَةࣲ مَّا تَبِعُوا۟ قِبۡلَتَكَۚ وَمَاۤ أَنتَ بِتَابِعࣲ قِبۡلَتَهُمۡۚ وَمَا بَعۡضُهُم بِتَابِعࣲ قِبۡلَةَ بَعۡضࣲۚ وَلَىِٕنِ ٱتَّبَعۡتَ أَهۡوَاۤءَهُم مِّنۢ بَعۡدِ مَا جَاۤءَكَ مِنَ ٱلۡعِلۡمِ إِنَّكَ إِذࣰا لَّمِنَ ٱلظَّـٰلِمِینَ ۝١٤٥", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "ولئن جئت -أيها الرسول- الذين أُعطوا التوراة والإنجيل بكل حجة وبرهان على أن توجُّهك إلى الكعبة في الصلاة هو الحق من عند الله، ما تبعوا قبلتك عنادًا واستكبارًا، وما أنت بتابع قبلتهم مرة أخرى، وما بعضهم بتابع قبلة بعض. ولئن اتبعت أهواءهم في شأن القبلة وغيرها بعد ما جاءك من العلم بأنك على الحق وهم على الباطل، إنك حينئذ لمن الظالمين لأنفسهم. وهذا خطاب لجميع الأمة وهو تهديد ووعيد لمن يتبع أهواء المخالفين لشريعة الإسلام.", "isBasmala": false, "translation_en": "Even if you were to bring to those who were given the Book every proof, they would not follow your direction, nor are you to follow their direction, nor do they follow the direction of one another. And if you were to follow their desires, after the knowledge that has come to you, you would be in that case one of the wrongdoers.", "translation_id": "Dan sesungguhnya jika kamu mendatangkan kepada orang-orang (Yahudi dan Nasrani) yang diberi Al Kitab (Taurat dan Injil), semua ayat (keterangan), mereka tidak akan mengikuti kiblatmu, dan kamupun tidak akan mengikuti kiblat mereka, dan sebahagian merekapun tidak akan mengikuti kiblat sebahagian yang lain. Dan sesungguhnya jika kamu mengikuti keinginan mereka setelah datang ilmu kepadamu, sesungguhnya kamu -- kalau begitu -- termasuk golongan orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}], "23": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 146, "text": "ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَعۡرِفُونَهُۥ كَمَا یَعۡرِفُونَ أَبۡنَاۤءَهُمۡۖ وَإِنَّ فَرِیقࣰا مِّنۡهُمۡ لَیَكۡتُمُونَ ٱلۡحَقَّ وَهُمۡ یَعۡلَمُونَ ۝١٤٦", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "الذين أعطيناهم التوراة والإنجيل من أحبار اليهود وعلماء النصارى يعرفون أنَّ محمدًا صلى الله عليه وسلم رسول الله بأوصافه المذكورة في كتبهم، مثل معرفتهم بأبنائهم. وإن فريقًا منهم ليكتمون الحق وهم يعلمون صِدْقه، وثبوت أوصافه.", "isBasmala": false, "translation_en": "Those to whom We have given the Book recognize it as they recognize their own children. But some of them conceal the truth while they know.", "translation_id": "Orang-orang (Yahudi dan Nasrani) yang telah Kami beri Al Kitab (Taurat dan Injil) mengenal Muhammad seperti mereka mengenal anak-anaknya sendiri. Dan sesungguhnya sebahagian diantara mereka menyembunyikan kebenaran, padahal mereka mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 147, "text": "ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِینَ ۝١٤٧", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "الذي أنزل إليك -أيها النبي- هو الحق من ربك، فلا تكونن من الشاكين فيه. وهذا وإن كان خطابا للرسول صلى الله عليه وسلم فهو موجه للأمة.", "isBasmala": false, "translation_en": "The truth is from your Lord, so do not be a skeptic.", "translation_id": "Kebenaran itu adalah dari Tuhanmu, sebab itu jangan sekali-kali kamu termasuk orang-orang yang ragu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 148, "text": "وَلِكُلࣲّ وِجۡهَةٌ هُوَ مُوَلِّیهَاۖ فَٱسۡتَبِقُوا۟ ٱلۡخَیۡرَ ٰتِۚ أَیۡنَ مَا تَكُونُوا۟ یَأۡتِ بِكُمُ ٱللَّهُ جَمِیعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝١٤٨", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "ولكل أمة من الأمم قبلة يتوجَّه إليها كل واحد منها في صلاته، فبادروا - أيها المؤمنون- متسابقين إلى فِعْل الأعمال الصالحة التي شرعها الله لكم في دين الإسلام. وسيجمعكم الله جميعا يوم القيامة من أي موضع كنتم فيه. إن الله على كل شيء قدير.", "isBasmala": false, "translation_en": "To every community is a direction towards which it turns. Therefore, race towards goodness. Wherever you may be, God will bring you all together. God is capable of everything.", "translation_id": "Dan bagi tiap-tiap umat ada kiblatnya (sendiri) yang ia menghadap kepadanya. Maka berlomba-lombalah (dalam membuat) kebaikan. Di mana saja kamu berada pasti Allah akan mengumpulkan kamu sekalian (pada hari kiamat). Sesungguhnya Allah Maha Kuasa atas segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 149, "text": "وَمِنۡ حَیۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ وَإِنَّهُۥ لَلۡحَقُّ مِن رَّبِّكَۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ ۝١٤٩", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "ومن أي مكان خَرَجْتَ -أيها النبي- مسافرًا، وأردت الصلاة، فوجِّه وجهك نحو المسجد الحرام. وإنَّ توجُّهك إليه لهو الحق الثابت من ربك. وما الله بغافل عما تعملونه، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "And wherever you come from, turn your face towards the Sacred Mosque. This is the truth from your Lord, and God is not heedless of what you do.", "translation_id": "Dan dari mana saja kamu keluar (datang), maka palingkanlah wajahmu ke arah Masjidil Haram, sesungguhnya ketentuan itu benar-benar sesuatu yang hak dari Tuhanmu. Dan Allah sekali-kali tidak lengah dari apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 150, "text": "وَمِنۡ حَیۡثُ خَرَجۡتَ فَوَلِّ وَجۡهَكَ شَطۡرَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَحَیۡثُ مَا كُنتُمۡ فَوَلُّوا۟ وُجُوهَكُمۡ شَطۡرَهُۥ لِئَلَّا یَكُونَ لِلنَّاسِ عَلَیۡكُمۡ حُجَّةٌ إِلَّا ٱلَّذِینَ ظَلَمُوا۟ مِنۡهُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِی وَلِأُتِمَّ نِعۡمَتِی عَلَیۡكُمۡ وَلَعَلَّكُمۡ تَهۡتَدُونَ ۝١٥٠", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "ومن أى مكان خرجت -أيها النبي- فتوجَّه إلى المسجد الحرام، وحيثما كنتم -أيها المسلمون-، بأي قطر من أقطار الأرض فولُّوا وجوهكم نحو المسجد الحرام؛ لكي لا يكون للناس المخالفين لكم احتجاج عليكم بالمخاصمة والمجادلة، بعد هذا التوجه إليه، إلا أهل الظلم والعناد منهم، فسيظلُّون على جدالهم، فلا تخافوهم وخافوني بامتثال أمري، واجتناب نهيي؛ ولكي أتم نعمتي عليكم باختيار أكمل الشرائع لكم، ولعلكم تهتدون إلى الحق والصواب.", "isBasmala": false, "translation_en": "And wherever you come from, turn your face towards the Sacred Mosque. And wherever you may be, turn your faces towards it. So that the people may not have any argument against you-except those who do wrong among them. So do not fear them, but fear Me, that I may complete My blessings upon you, and that you may be guided.", "translation_id": "Dan dari mana saja kamu (keluar), maka palingkanlah wajahmu ke arah Masjidil Haram. Dan dimana saja kamu (sekalian) berada, maka palingkanlah wajahmu ke arahnya, agar tidak ada hujjah bagi manusia atas kamu, kecuali orang-orang yang zalim diantara mereka. Maka janganlah kamu takut kepada mereka dan takutlah kepada-Ku (saja). Dan agar Ku-sempurnakan nikmat-Ku atasmu, dan supaya kamu mendapat petunjuk.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 151, "text": "كَمَاۤ أَرۡسَلۡنَا فِیكُمۡ رَسُولࣰا مِّنكُمۡ یَتۡلُوا۟ عَلَیۡكُمۡ ءَایَـٰتِنَا وَیُزَكِّیكُمۡ وَیُعَلِّمُكُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَیُعَلِّمُكُم مَّا لَمۡ تَكُونُوا۟ تَعۡلَمُونَ ۝١٥١", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "كما أنعمنا عليكم باستقبال الكعبة أرسلنا فيكم رسولا منكم يتلو عليكم الآيات المبينة للحق من الباطل، ويطهركم من دنس الشرك وسوء الأخلاق، ويعلمكم الكتاب والسنة وأحكام الشريعة، ويعلمكم من أخبار الأنبياء، وقصص الأمم السابقة ما كنتم تجهلونه.", "isBasmala": false, "translation_en": "Just as We sent to you a messenger from among you, who recites Our revelations to you, and purifies you, and teaches you the Book and wisdom, and teaches you what you did not know.", "translation_id": "Sebagaimana (Kami telah menyempurnakan nikmat Kami kepadamu) Kami telah mengutus kepadamu Rasul diantara kamu yang membacakan ayat-ayat Kami kepada kamu dan mensucikan kamu dan mengajarkan kepadamu Al Kitab dan Al-Hikmah, serta mengajarkan kepada kamu apa yang belum kamu ketahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 152, "text": "فَٱذۡكُرُونِیۤ أَذۡكُرۡكُمۡ وَٱشۡكُرُوا۟ لِی وَلَا تَكۡفُرُونِ ۝١٥٢", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "أمر تعالى المؤمنين بذكره، ووعد عليه أفضل الجزاء، وهو الثناء في الملأ الأعلى على مَنْ ذكره، وخصوني -أيها المؤمنون- بالشكر قولا وعملا ولا تجحدوا نعمي عليكم.", "isBasmala": false, "translation_en": "So remember Me, and I will remember you. And thank Me, and do not be ungrateful.", "translation_id": "Karena itu, ingatlah kamu kepada-Ku niscaya Aku ingat (pula) kepadamu, dan bersyukurlah kepada-Ku, dan janganlah kamu mengingkari (nikmat)-Ku.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 153, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱسۡتَعِینُوا۟ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِینَ ۝١٥٣", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "يا أيها المؤمنون اطلبوا العون من الله في كل أموركم: بالصبر على النوائب والمصائب، وترك المعاصي والذنوب، والصبر على الطاعات والقربات، والصلاة التي تطمئن بها النفس، وتنهى عن الفحشاء والمنكر. إن الله مع الصابرين بعونه وتوفيقه وتسديده. وفي الآية: إثبات معيَّة الله الخاصة بالمؤمنين، المقتضية لما سلف ذكره؛ أما المعية العامة، المقتضية للعلم والإحاطة فهي لجميع الخلق.", "isBasmala": false, "translation_en": "O you who believe! Seek help through patience and prayers. God is with the steadfast.", "translation_id": "Hai orang-orang yang beriman, jadikanlah sabar dan shalat sebagai penolongmu, sesungguhnya Allah beserta orang-orang yang sabar.", "manzil": 1, "manzil_display": ""}], "24": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 154, "text": "وَلَا تَقُولُوا۟ لِمَن یُقۡتَلُ فِی سَبِیلِ ٱللَّهِ أَمۡوَ ٰتُۢۚ بَلۡ أَحۡیَاۤءࣱ وَلَـٰكِن لَّا تَشۡعُرُونَ ۝١٥٤", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "ولا تقولوا -أيها المؤمنون- فيمن يُقتلون مجاهدين في سبيل الله: هم أموات، بل هم أحياء حياة خاصة بهم في قبورهم، لا يعلم كيفيتها إلا الله - تعالى-، ولكنكم لا تُحسُّون بها. وفي هذا دليل على نعيم القبر.", "isBasmala": false, "translation_en": "And do not say of those who are killed in the cause of God, \"Dead.\" Rather, they are alive, but you do not perceive.", "translation_id": "Dan janganlah kamu mengatakan terhadap orang-orang yang gugur di jalan Allah, (bahwa mereka itu) mati; bahkan (sebenarnya) mereka itu hidup, tetapi kamu tidak menyadarinya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 155, "text": "وَلَنَبۡلُوَنَّكُم بِشَیۡءࣲ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصࣲ مِّنَ ٱلۡأَمۡوَ ٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَ ٰتِۗ وَبَشِّرِ ٱلصَّـٰبِرِینَ ۝١٥٥", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "ولنختبرنكم بشيء يسير من الخوف، ومن الجوع، وبنقص من الأموال بتعسر الحصول عليها، أو ذهابها، ومن الأنفس: بالموت أو الشهادة في سبيل الله، وبنقص من ثمرات النخيل والأعناب والحبوب، بقلَّة ناتجها أو فسادها. وبشِّر -أيها النبي- الصابرين على هذا وأمثاله بما يفرحهم ويَسُرُّهم من حسن العاقبة في الدنيا والآخرة.", "isBasmala": false, "translation_en": "We will certainly test you with some fear and hunger, and some loss of possessions and lives and crops. But give good news to the steadfast.", "translation_id": "Dan sungguh akan Kami berikan cobaan kepadamu, dengan sedikit ketakutan, kelaparan, kekurangan harta, jiwa dan buah-buahan. Dan berikanlah berita gembira kepada orang-orang yang sabar.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 156, "text": "ٱلَّذِینَ إِذَاۤ أَصَـٰبَتۡهُم مُّصِیبَةࣱ قَالُوۤا۟ إِنَّا لِلَّهِ وَإِنَّاۤ إِلَیۡهِ رَ ٰجِعُونَ ۝١٥٦", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "من صفة هؤلاء الصابرين أنهم إذا أصابهم شيء يكرهونه قالوا: إنَّا عبيد مملوكون لله، مدبَّرون بأمره وتصريفه، يفعل بنا ما يشاء، وإنا إليه راجعون بالموت، ثم بالبعث للحساب والجزاء.", "isBasmala": false, "translation_en": "Those who, when a calamity afflicts them, say, \"To God we belong, and to Him we will return.\"", "translation_id": "(yaitu) orang-orang yang apabila ditimpa musibah, mereka mengucapkan: \"Inna lillaahi wa innaa ilaihi raaji'uun\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 157, "text": "أُو۟لَـٰۤىِٕكَ عَلَیۡهِمۡ صَلَوَ ٰتࣱ مِّن رَّبِّهِمۡ وَرَحۡمَةࣱۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُهۡتَدُونَ ۝١٥٧", "juz": 2, "hizb": "(* ح 3*)", "tafsir": "أولئك الصابرون لهم ثناء من ربهم ورحمة عظيمة منه سبحانه، وأولئك هم المهتدون إلى الرشاد.", "isBasmala": false, "translation_en": "Upon these are blessings and mercy from their Lord. These are the guided ones.", "translation_id": "Mereka itulah yang mendapat keberkatan yang sempurna dan rahmat dari Tuhan mereka dan mereka itulah orang-orang yang mendapat petunjuk.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 158, "text": "۞ إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَاۤىِٕرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَیۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَیۡهِ أَن یَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَیۡرࣰا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِیمٌ ۝١٥٨", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "إن الصفا والمروة- وهما جبلان صغيران قرب الكعبة من جهة الشرق- من معالم دين الله الظاهرة التي تعبَّد الله عباده بالسعي بينهما. فمَن قصد الكعبة حاجًّا أو معتمرًا، فلا إثم عليه ولا حرج في أن يسعى بينهما، بل يجب عليه ذلك، ومن فعل الطاعات طواعية من نفسه مخلصًا بها لله تعالى، فإن الله تعالى شاكر يثيب على القليل بالكثير، عليم بأعمال عباده فلا يضعها، ولا يبخس أحدًا مثقال ذرة.", "isBasmala": false, "translation_en": "Safa and Marwa are among the rites of God. Whoever makes the Pilgrimage to the House, or performs the Umrah, commits no error by circulating between them. Whoever volunteers good-God is Appreciative and Cognizant.", "translation_id": "Sesungguhnya Shafaa dan Marwa adalah sebahagian dari syi'ar Allah. Maka barangsiapa yang beribadah haji ke Baitullah atau ber'umrah, maka tidak ada dosa baginya mengerjakan sa'i antara keduanya. Dan barangsiapa yang mengerjakan suatu kebajikan dengan kerelaan hati, maka sesungguhnya Allah Maha Mensyukuri kebaikan lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 159, "text": "إِنَّ ٱلَّذِینَ یَكۡتُمُونَ مَاۤ أَنزَلۡنَا مِنَ ٱلۡبَیِّنَـٰتِ وَٱلۡهُدَىٰ مِنۢ بَعۡدِ مَا بَیَّنَّـٰهُ لِلنَّاسِ فِی ٱلۡكِتَـٰبِ أُو۟لَـٰۤىِٕكَ یَلۡعَنُهُمُ ٱللَّهُ وَیَلۡعَنُهُمُ ٱللَّـٰعِنُونَ ۝١٥٩", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "إن الذين يُخْفون ما أنزلنا من الآيات الواضحات الدالة على نبوة محمد صلى الله عليه وسلم وما جاء به، وهم أحبار اليهود وعلماء النصارى وغيرهم ممن يكتم ما أنزل الله من بعد ما أظهرناه للناس في التوراة والإنجيل، أولئك يطردهم الله من رحمته، ويدعو عليهم باللعنة جميع الخليقة.", "isBasmala": false, "translation_en": "Those who suppress the proofs and the guidance We have revealed, after We have clarified them to humanity in the Scripture-those-God curses them, and the cursers curse them.", "translation_id": "Sesungguhnya orang-orang yang menyembunyikan apa yang telah Kami turunkan berupa keterangan-keterangan (yang jelas) dan petunjuk, setelah Kami menerangkannya kepada manusia dalam Al Kitab, mereka itu dilaknati Allah dan dilaknati (pula) oleh semua (mahluk) yang dapat melaknati,", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 160, "text": "إِلَّا ٱلَّذِینَ تَابُوا۟ وَأَصۡلَحُوا۟ وَبَیَّنُوا۟ فَأُو۟لَـٰۤىِٕكَ أَتُوبُ عَلَیۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِیمُ ۝١٦٠", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "إلا الذين رجعوا مستغفرين الله من خطاياهم، وأصلحوا ما أفسدوه، وبَيَّنوا ما كتموه، فأولئك أقبل توبتهم وأجازيهم بالمغفرة، وأنا التواب على من تاب من عبادي، الرحيم بهم؛ إذ وفقتُهم للتوبة وقبلتها منهم.", "isBasmala": false, "translation_en": "Except those who repent, and reform, and proclaim. Those-I will accept their repentance. I am the Acceptor of Repentance, the Merciful.", "translation_id": "kecuali mereka yang telah taubat dan mengadakan perbaikan dan menerangkan (kebenaran), maka terhadap mereka itulah Aku menerima taubatnya dan Akulah Yang Maha Menerima taubat lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 161, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمۡ كُفَّارٌ أُو۟لَـٰۤىِٕكَ عَلَیۡهِمۡ لَعۡنَةُ ٱللَّهِ وَٱلۡمَلَـٰۤىِٕكَةِ وَٱلنَّاسِ أَجۡمَعِینَ ۝١٦١", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "إن الذين جحدوا الإيمان وكتموا الحق، واستمروا على ذلك حتى ماتوا، أولئك عليهم لعنة الله والملائكة والناس أجمعين بالطرد من رحمته.", "isBasmala": false, "translation_en": "But as for those who reject faith, and die rejecting-those-upon them is the curse of God, and of the angels, and of all humanity.", "translation_id": "Sesungguhnya orang-orang kafir dan mereka mati dalam keadaan kafir, mereka itu mendapat laknat Allah, para Malaikat dan manusia seluruhnya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 162, "text": "خَـٰلِدِینَ فِیهَا لَا یُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ یُنظَرُونَ ۝١٦٢", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "دائمين في اللعنة والنار، لا يخفف عنهم العذاب، ولا هم يمهلون بمعذرة يعتذرون بها.", "isBasmala": false, "translation_en": "They will remain under it forever, and the torment will not be lightened for them, and they will not be reprieved.", "translation_id": "Mereka kekal di dalam laknat itu; tidak akan diringankan siksa dari mereka dan tidak (pula) mereka diberi tangguh.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 163, "text": "وَإِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰحِدࣱۖ لَّاۤ إِلَـٰهَ إِلَّا هُوَ ٱلرَّحۡمَـٰنُ ٱلرَّحِیمُ ۝١٦٣", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "وإلهكم -أيها الناس- إله واحد متفرد في ذاته وأسمائه وصفاته وأفعاله وعبودية خلقه له، لا معبود بحق إلا هو، الرحمن المتصف بالرحمة في ذاته وأفعاله لجميع الخلق، الرحيم بالمؤمنين.", "isBasmala": false, "translation_en": "Your God is one God. There is no god but He, the Benevolent, the Compassionate.", "translation_id": "Dan Tuhanmu adalah Tuhan Yang Maha Esa; tidak ada Tuhan melainkan Dia Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}], "25": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 164, "text": "إِنَّ فِی خَلۡقِ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَـٰفِ ٱلَّیۡلِ وَٱلنَّهَارِ وَٱلۡفُلۡكِ ٱلَّتِی تَجۡرِی فِی ٱلۡبَحۡرِ بِمَا یَنفَعُ ٱلنَّاسَ وَمَاۤ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَاۤءِ مِن مَّاۤءࣲ فَأَحۡیَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَبَثَّ فِیهَا مِن كُلِّ دَاۤبَّةࣲ وَتَصۡرِیفِ ٱلرِّیَـٰحِ وَٱلسَّحَابِ ٱلۡمُسَخَّرِ بَیۡنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَعۡقِلُونَ ۝١٦٤", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "إن في خلق السماوات بارتفاعها واتساعها، والأرض بجبالها وسهولها وبحارها، وفي اختلاف الليل والنهار من الطول والقصر، والظلمة والنور، وتعاقبهما بأن يخلف كل منهما الآخر، وفي السفن الجارية في البحار، التي تحمل ما ينفع الناس، وما أنزل الله من السماء من ماء المطر، فأحيا به الأرض، فصارت مخضرَّة ذات بهجة بعد أن كانت يابسة لا نبات فيها، وما نشره الله فيها من كل ما دبَّ على وجه الأرض، وما أنعم به عليكم من تقليب الرياح وتوجيهها، والسحاب المسيَّر بين السماء والأرض -إن في كل الدلائل السابقة لآياتٍ على وحدانية الله، وجليل نعمه، لقوم يعقلون مواضع الحجج، ويفهمون أدلته سبحانه على وحدانيته، واستحقاقه وحده للعبادة.", "isBasmala": false, "translation_en": "In the creation of the heavens and the earth; in the alternation of night and day; in the ships that sail the oceans for the benefit of mankind; in the water that God sends down from the sky, and revives the earth with it after it had died, and scatters in it all kinds of creatures; in the changing of the winds, and the clouds disposed between the sky and the earth; are signs for people who understand.", "translation_id": "Sesungguhnya dalam penciptaan langit dan bumi, silih bergantinya malam dan siang, bahtera yang berlayar di laut membawa apa yang berguna bagi manusia, dan apa yang Allah turunkan dari langit berupa air, lalu dengan air itu Dia hidupkan bumi sesudah mati (kering)-nya dan Dia sebarkan di bumi itu segala jenis hewan, dan pengisaran angin dan awan yang dikendalikan antara langit dan bumi; sungguh (terdapat) tanda-tanda (keesaan dan kebesaran Allah) bagi kaum yang memikirkan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 165, "text": "وَمِنَ ٱلنَّاسِ مَن یَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادࣰا یُحِبُّونَهُمۡ كَحُبِّ ٱللَّهِۖ وَٱلَّذِینَ ءَامَنُوۤا۟ أَشَدُّ حُبࣰّا لِّلَّهِۗ وَلَوۡ یَرَى ٱلَّذِینَ ظَلَمُوۤا۟ إِذۡ یَرَوۡنَ ٱلۡعَذَابَ أَنَّ ٱلۡقُوَّةَ لِلَّهِ جَمِیعࣰا وَأَنَّ ٱللَّهَ شَدِیدُ ٱلۡعَذَابِ ۝١٦٥", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "ومع هذه البراهين القاطعة يتخذ فريق من الناس من دون الله أصنامًا وأوثانًا وأولياء يجعلونهم نظراء لله تعالى، ويعطونهم من المحبة والتعظيم والطاعة، ما لا يليق إلا بالله وحده. والمؤمنون أعظم حبا لله من حب هؤلاء الكفار لله ولآلهتهم؛ لأن المؤمنين أخلصوا المحبة كلها لله، وأولئك أشركوا في المحبة. ولو يعلم الذين ظلموا أنفسهم بالشرك في الحياة الدنيا، حين يشاهدون عذاب الآخرة، أن الله هو المتفرد بالقوة جميعًا، وأن الله شديد العذاب، لما اتخذوا من دون الله آلهة يعبدونهم من دونه، ويتقربون بهم إليه.", "isBasmala": false, "translation_en": "Yet among the people are those who take other than God as equals to Him. They love them as the love of God. But those who believe have greater love for God. If only the wrongdoers would realize, when they see the torment; that all power is God's, and that God is severe in punishment.", "translation_id": "Dan diantara manusia ada orang-orang yang menyembah tandingan-tandingan selain Allah; mereka mencintainya sebagaimana mereka mencintai Allah. Adapun orang-orang yang beriman amat sangat cintanya kepada Allah. Dan jika seandainya orang-orang yang berbuat zalim itu mengetahui ketika mereka melihat siksa (pada hari kiamat), bahwa kekuatan itu kepunyaan Allah semuanya, dan bahwa Allah amat berat siksaan-Nya (niscaya mereka menyesal).", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 166, "text": "إِذۡ تَبَرَّأَ ٱلَّذِینَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِینَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلۡعَذَابَ وَتَقَطَّعَتۡ بِهِمُ ٱلۡأَسۡبَابُ ۝١٦٦", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "عند معاينتهم عذاب الآخرة يتبرأ الرؤساء المتبوعون ممن اتبعهم على الشرك، وتنقطع بينهم كل الصلات التي ارتبطوا بها في الدنيا: من القرابة، والاتِّباع، والدين، وغير ذلك.", "isBasmala": false, "translation_en": "Those who were followed will then disown those who followed them, and they will see the retribution, and ties between them will be severed.", "translation_id": "(Yaitu) ketika orang-orang yang diikuti itu berlepas diri dari orang-orang yang mengikutinya, dan mereka melihat siksa; dan (ketika) segala hubungan antara mereka terputus sama sekali.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 167, "text": "وَقَالَ ٱلَّذِینَ ٱتَّبَعُوا۟ لَوۡ أَنَّ لَنَا كَرَّةࣰ فَنَتَبَرَّأَ مِنۡهُمۡ كَمَا تَبَرَّءُوا۟ مِنَّاۗ كَذَ ٰلِكَ یُرِیهِمُ ٱللَّهُ أَعۡمَـٰلَهُمۡ حَسَرَ ٰتٍ عَلَیۡهِمۡۖ وَمَا هُم بِخَـٰرِجِینَ مِنَ ٱلنَّارِ ۝١٦٧", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "وقال التابعون: يا ليت لنا عودة إلى الدنيا، فنعلن براءتنا من هؤلاء الرؤساء، كما أعلنوا براءتهم مِنَّا. وكما أراهم الله شدة عذابه يوم القيامة يريهم أعمالهم الباطلة ندامات عليهم، وليسوا بخارجين من النار أبدًا.", "isBasmala": false, "translation_en": "Those who followed will say, \"If only we can have another chance, we will disown them, as they disowned us.\" Thus God will show them their deeds, as regrets to them, and they will not come out of the Fire.", "translation_id": "Dan berkatalah orang-orang yang mengikuti: \"Seandainya kami dapat kembali (ke dunia), pasti kami akan berlepas diri dari mereka, sebagaimana mereka berlepas diri dari kami\". Demikianlah Allah memperlihatkan kepada mereka amal perbuatannya menjadi sesalan bagi mereka; dan sekali-kali mereka tidak akan keluar dari api neraka.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 168, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِی ٱلۡأَرۡضِ حَلَـٰلࣰا طَیِّبࣰا وَلَا تَتَّبِعُوا۟ خُطُوَ ٰتِ ٱلشَّیۡطَـٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینٌ ۝١٦٨", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "يا أيها الناس كلوا من رزق الله الذي أباحه لكم في الأرض، وهو الطاهر غير النجس، النافع غير الضار، ولا تتبعوا طرق الشيطان في التحليل والتحريم، والبدع والمعاصي. إنه عدو لكم ظاهر العداوة.", "isBasmala": false, "translation_en": "O people! Eat of what is lawful and good on earth, and do not follow the footsteps of Satan. He is to you an open enemy.", "translation_id": "Hai sekalian manusia, makanlah yang halal lagi baik dari apa yang terdapat di bumi, dan janganlah kamu mengikuti langkah-langkah syaitan; karena sesungguhnya syaitan itu adalah musuh yang nyata bagimu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 169, "text": "إِنَّمَا یَأۡمُرُكُم بِٱلسُّوۤءِ وَٱلۡفَحۡشَاۤءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝١٦٩", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "إنما يأمركم الشيطان بكل ذنب قبيح يسوءُكم، وبكل معصية بالغة القبح، وبأن تفتروا على الله الكذب من تحريم الحلال وغيره بدون علم.", "isBasmala": false, "translation_en": "He commands you to do evil and vice, and to say about God what you do not know.", "translation_id": "Sesungguhnya syaitan itu hanya menyuruh kamu berbuat jahat dan keji, dan mengatakan terhadap Allah apa yang tidak kamu ketahui.", "manzil": 1, "manzil_display": ""}], "26": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 170, "text": "وَإِذَا قِیلَ لَهُمُ ٱتَّبِعُوا۟ مَاۤ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلۡ نَتَّبِعُ مَاۤ أَلۡفَیۡنَا عَلَیۡهِ ءَابَاۤءَنَاۤۚ أَوَ لَوۡ كَانَ ءَابَاۤؤُهُمۡ لَا یَعۡقِلُونَ شَیۡـࣰٔا وَلَا یَهۡتَدُونَ ۝١٧٠", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "وإذا قال المؤمنون ناصحين أهل الضلال: اتبعوا ما أنزل الله من القرآن والهدى، أصرُّوا على تقليد أسلافهم المشركين قائلين: لا نتبع دينكم، بل نتبع ما وجدنا عليه آباءنا. أيتبعون آباءهم ولو كانوا لا يعقلون عن الله شيئًا، ولا يدركون رشدًا؟", "isBasmala": false, "translation_en": "And when it is said to them, \"Follow what God has revealed,\" they say, \"We will follow what we found our ancestors following.\" Even if their ancestors understood nothing, and were not guided?", "translation_id": "Dan apabila dikatakan kepada mereka: \"Ikutilah apa yang telah diturunkan Allah,\" mereka menjawab: \"(Tidak), tetapi kami hanya mengikuti apa yang telah kami dapati dari (perbuatan) nenek moyang kami\". \"(Apakah mereka akan mengikuti juga), walaupun nenek moyang mereka itu tidak mengetahui suatu apapun, dan tidak mendapat petunjuk?\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 171, "text": "وَمَثَلُ ٱلَّذِینَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِی یَنۡعِقُ بِمَا لَا یَسۡمَعُ إِلَّا دُعَاۤءࣰ وَنِدَاۤءࣰۚ صُمُّۢ بُكۡمٌ عُمۡیࣱ فَهُمۡ لَا یَعۡقِلُونَ ۝١٧١", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "وصفة الذين كفروا وداعيهم إلى الهدى والإيمان كصفة الراعي الذي يصيح بالبهائم ويزجرها، وهي لا تفهم معاني كلامه، وإنما تسمع النداء ودَوِيَّ الصوت فقط. هؤلاء الكفار صُمٌّ سدُّوا أسماعهم عن الحق، بُكْم أخرسوا ألسنتهم عن النطق به، عُمْي لا ترى أعينهم براهينه الباهرة، فهم لا يعملون عقولهم فيما ينفعهم.", "isBasmala": false, "translation_en": "The parable of those who disbelieve is that of someone who calls upon someone who hears nothing except screaming and yelling. Deaf, dumb, and blind-they do not understand.", "translation_id": "Dan perumpamaan (orang-orang yang menyeru) orang-orang kafir adalah seperti penggembala yang memanggil binatang yang tidak mendengar selain panggilan dan seruan saja. Mereka tuli, bisu dan buta, maka (oleh sebab itu) mereka tidak mengerti.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 172, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُلُوا۟ مِن طَیِّبَـٰتِ مَا رَزَقۡنَـٰكُمۡ وَٱشۡكُرُوا۟ لِلَّهِ إِن كُنتُمۡ إِیَّاهُ تَعۡبُدُونَ ۝١٧٢", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "يا أيها المؤمنون كلوا من الأطعمة المستلَذَّة الحلال التي رزقناكم، ولا تكونوا كالكفار الذين يحرمون الطيبات، ويستحِلُّون الخبائث، واشكروا لله نعمه العظيمة عليكم بقلوبكم وألسنتكم وجوارحكم، إن كنتم حقًا منقادين لأمره، سامعين مطيعين له، تعبدونه وحده لا شريك له.", "isBasmala": false, "translation_en": "O you who believe! Eat of the good things We have provided for you, and give thanks to God, if it is Him that you serve.", "translation_id": "Hai orang-orang yang beriman, makanlah di antara rezeki yang baik-baik yang Kami berikan kepadamu dan bersyukurlah kepada Allah, jika benar-benar kepada-Nya kamu menyembah.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 173, "text": "إِنَّمَا حَرَّمَ عَلَیۡكُمُ ٱلۡمَیۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِیرِ وَمَاۤ أُهِلَّ بِهِۦ لِغَیۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَیۡرَ بَاغࣲ وَلَا عَادࣲ فَلَاۤ إِثۡمَ عَلَیۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ ۝١٧٣", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "إنما حرم الله عليكم ما يضركم كالميتة التي لم تذبح بطريقة شرعية، والدم المسفوح، ولحم الخنزير، والذبائح التي ذبحت لغير الله. ومِنْ فَضْلِ الله عليكم وتيسيره أنه أباح لكم أكل هذه المحرمات عند الضرورة. فمن ألجأته الضرورة إلى أكل شيء منها، غير ظالم في أكله فوق حاجته، ولا متجاوز حدود الله فيما أُبيح له، فلا ذنب عليه في ذلك. إن الله غفور لعباده، رحيم بهم.", "isBasmala": false, "translation_en": "He has forbidden you carrion, and blood, and the flesh of swine, and what was dedicated to other than God. But if anyone is compelled, without desiring or exceeding, he commits no sin. God is Forgiving and Merciful.", "translation_id": "Sesungguhnya Allah hanya mengharamkan bagimu bangkai, darah, daging babi, dan binatang yang (ketika disembelih) disebut (nama) selain Allah. Tetapi barangsiapa dalam keadaan terpaksa (memakannya) sedang dia tidak menginginkannya dan tidak (pula) melampaui batas, maka tidak ada dosa baginya. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 174, "text": "إِنَّ ٱلَّذِینَ یَكۡتُمُونَ مَاۤ أَنزَلَ ٱللَّهُ مِنَ ٱلۡكِتَـٰبِ وَیَشۡتَرُونَ بِهِۦ ثَمَنࣰا قَلِیلًا أُو۟لَـٰۤىِٕكَ مَا یَأۡكُلُونَ فِی بُطُونِهِمۡ إِلَّا ٱلنَّارَ وَلَا یُكَلِّمُهُمُ ٱللَّهُ یَوۡمَ ٱلۡقِیَـٰمَةِ وَلَا یُزَكِّیهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمٌ ۝١٧٤", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "إن الذين يُخْفون ما أنزل الله في كتبه من صفة محمد صلى الله عليه وسلم وغير ذلك من الحق، ويحرصون على أخذ عوض قليل من عرض الحياة الدنيا مقابل هذا الإخفاء، هؤلاء ما يأكلون في مقابلة كتمان الحق إلا نار جهنم تتأجج في بطونهم، ولا يكلمهم الله يوم القيامة لغضبه وسخطه عليهم، ولا يطهرهم من دنس ذنوبهم وكفرهم، ولهم عذاب موجع.", "isBasmala": false, "translation_en": "Those who conceal what God revealed in the Book, and exchange it for a small price-those swallow nothing but fire into their bellies. And God will not speak to them on the Day of Resurrection, nor will He purify them, and they will have a painful punishment.", "translation_id": "Sesungguhnya orang-orang yang menyembunyikan apa yang telah diturunkan Allah, yaitu Al Kitab dan menjualnya dengan harga yang sedikit (murah), mereka itu sebenarnya tidak memakan (tidak menelan) ke dalam perutnya melainkan api, dan Allah tidak akan berbicara kepada mereka pada hari kiamat dan tidak mensucikan mereka dan bagi mereka siksa yang amat pedih.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 175, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ٱشۡتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلۡهُدَىٰ وَٱلۡعَذَابَ بِٱلۡمَغۡفِرَةِۚ فَمَاۤ أَصۡبَرَهُمۡ عَلَى ٱلنَّارِ ۝١٧٥", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "أولئك المتصفون بهذه الصفات استبدلوا الضلالة بالهدى وعذاب الله بمغفرته، فما أشد جراءتهم على النار بعملهم أعمال أهل النار!! يعجب الله من إقدامهم على ذلك، فاعجبوا -أيها الناس- من جراءتهم، ومن صبرهم على النار ومكثهم فيها. وهذا على وجه الاستهانة بهم، والاستخفاف بأمرهم.", "isBasmala": false, "translation_en": "It is they who exchange guidance for error, and forgiveness for punishment. But why do they insist on the Fire?", "translation_id": "Mereka itulah orang-orang yang membeli kesesatan dengan petunjuk dan siksa dengan ampunan. Maka alangkah beraninya mereka menentang api neraka!", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 176, "text": "ذَ ٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّۗ وَإِنَّ ٱلَّذِینَ ٱخۡتَلَفُوا۟ فِی ٱلۡكِتَـٰبِ لَفِی شِقَاقِۭ بَعِیدࣲ ۝١٧٦", "juz": 2, "hizb": "(*¼ ح 3*)", "tafsir": "ذلك العذاب الذي استحقوه بسبب أن الله تعالى نزَّل كتبه على رسله مشتملة على الحق المبين، فكفروا به. وإن الذين اختلفوا في الكتاب فأمنوا ببعضه وكفروا ببعضه، لفي منازعة ومفارقة بعيدة عن الرشد والصواب.", "isBasmala": false, "translation_en": "That is because God has revealed the Book in truth; and those who differ about the Book are in deep discord.", "translation_id": "Yang demikian itu adalah karena Allah telah menurunkan Al Kitab dengan membawa kebenaran; dan sesungguhnya orang-orang yang berselisih tentang (kebenaran) Al Kitab itu, benar-benar dalam penyimpangan yang jauh (dari kebenaran).", "manzil": 1, "manzil_display": ""}], "27": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 177, "text": "۞ لَّیۡسَ ٱلۡبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَـٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَٱلۡمَلَـٰۤىِٕكَةِ وَٱلۡكِتَـٰبِ وَٱلنَّبِیِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینَ وَٱبۡنَ ٱلسَّبِیلِ وَٱلسَّاۤىِٕلِینَ وَفِی ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَـٰهَدُوا۟ۖ وَٱلصَّـٰبِرِینَ فِی ٱلۡبَأۡسَاۤءِ وَٱلضَّرَّاۤءِ وَحِینَ ٱلۡبَأۡسِۗ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ صَدَقُوا۟ۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُتَّقُونَ ۝١٧٧", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "ليس الخير عند الله- تعالى- في التوجه في الصلاة إلى جهة المشرق والمغرب إن لم يكن عن أمر الله وشرعه، وإنما الخير كل الخير هو إيمان من آمن بالله وصدَّق به معبودًا وحدَه لا شريك له، وآمن بيوم البعث والجزاء، وبالملائكة جميعًا، وبالكتب المنزلة كافة، وبجميع النبيين من غير تفريق، وأعطى المال تطوُّعًا -مع شدة حبه- ذوي القربى، واليتامى المحتاجين الذين مات آباؤهم وهم دون سن البلوغ، والمساكين الذين أرهقهم الفقر، والمسافرين المحتاجين الذين بَعُدوا عن أهلهم ومالهم، والسائلين الذين اضطروا إلى السؤال لشدة حاجتهم، وأنفق في تحرير الرقيق والأسرى، وأقام الصلاة، وأدى الزكاة المفروضة، والذين يوفون بالعهود، ومن صبر في حال فقره ومرضه، وفي شدة القتال. أولئك المتصفون بهذه الصفات هم الذين صدقوا في إيمانهم، وأولئك هم الذين اتقَوا عقاب الله فتجنبوا معاصيه.", "isBasmala": false, "translation_en": "Righteousness does not consist of turning your faces towards the East and the West. But righteous is he who believes in God, and the Last Day, and the angels, and the Scripture, and the prophets. Who gives money, though dear, to near relatives, and orphans, and the needy, and the homeless, and the beggars, and for the freeing of slaves; those who perform the prayers, and pay the obligatory charity, and fulfill their promise when they promise, and patiently persevere in the face of persecution, hardship, and in the time of conflict. These are the sincere; these are the pious.", "translation_id": "Bukanlah menghadapkan wajahmu ke arah timur dan barat itu suatu kebajikan, akan tetapi sesungguhnya kebajikan itu ialah beriman kepada Allah, hari kemudian, malaikat-malaikat, kitab-kitab, nabi-nabi dan memberikan harta yang dicintainya kepada kerabatnya, anak-anak yatim, orang-orang miskin, musafir (yang memerlukan pertolongan) dan orang-orang yang meminta-minta; dan (memerdekakan) hamba sahaya, mendirikan shalat, dan menunaikan zakat; dan orang-orang yang menepati janjinya apabila ia berjanji, dan orang-orang yang sabar dalam kesempitan, penderitaan dan dalam peperangan. Mereka itulah orang-orang yang benar (imannya); dan mereka itulah orang-orang yang bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 178, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُتِبَ عَلَیۡكُمُ ٱلۡقِصَاصُ فِی ٱلۡقَتۡلَىۖ ٱلۡحُرُّ بِٱلۡحُرِّ وَٱلۡعَبۡدُ بِٱلۡعَبۡدِ وَٱلۡأُنثَىٰ بِٱلۡأُنثَىٰۚ فَمَنۡ عُفِیَ لَهُۥ مِنۡ أَخِیهِ شَیۡءࣱ فَٱتِّبَاعُۢ بِٱلۡمَعۡرُوفِ وَأَدَاۤءٌ إِلَیۡهِ بِإِحۡسَـٰنࣲۗ ذَ ٰلِكَ تَخۡفِیفࣱ مِّن رَّبِّكُمۡ وَرَحۡمَةࣱۗ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَ ٰلِكَ فَلَهُۥ عَذَابٌ أَلِیمࣱ ۝١٧٨", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "يا أيها الذين صدقوا الله ورسوله وعملوا بشرعه فرض الله عليكم أن تقتصوا من القاتل عمدا بقتله، بشرط المساواة والمماثلة: يُقتل الحر بمثله، والعبد بمثله، والأنثى بمثلها. فمن سامحه ولي المقتول بالعفو عن الاقتصاص منه والاكتفاء بأخذ الدية -وهي قدر مالي محدد يدفعه الجاني مقابل العفو عنه- فليلتزم الطرفان بحسن الخلق، فيطالب الولي بالدية من غير عنف، ويدفع القاتل إليه حقه بإحسان، مِن غير تأخير ولا نقص. ذلك العفو مع أخذ الدية تخفيف من ربكم ورحمة بكم؛ لما فيه من التسهيل والانتفاع. فمَن قتل القاتل بعد العفو عنه وأَخْذِ الدية فله عذاب أليم بقتله قصاصًا في الدنيا، أو بالنار في الآخرة.", "isBasmala": false, "translation_en": "O you who believe! Retaliation for the murdered is ordained upon you: the free for the free, the slave for the slave, the female for the female. But if he is forgiven by his kin, then grant any reasonable demand, and pay with good will. This is a concession from your Lord, and a mercy. But whoever commits aggression after that, a painful torment awaits him.", "translation_id": "Hai orang-orang yang beriman, diwajibkan atas kamu qishaash berkenaan dengan orang-orang yang dibunuh; orang merdeka dengan orang merdeka, hamba dengan hamba, dan wanita dengan wanita. Maka barangsiapa yang mendapat suatu pemaafan dari saudaranya, hendaklah (yang memaafkan) mengikuti dengan cara yang baik, dan hendaklah (yang diberi maaf) membayar (diat) kepada yang memberi maaf dengan cara yang baik (pula). Yang demikian itu adalah suatu keringanan dari Tuhan kamu dan suatu rahmat. Barangsiapa yang melampaui batas sesudah itu, maka baginya siksa yang sangat pedih.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 179, "text": "وَلَكُمۡ فِی ٱلۡقِصَاصِ حَیَوٰةࣱ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ لَعَلَّكُمۡ تَتَّقُونَ ۝١٧٩", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "ولكم في تشريع القصاص وتنفيذه حياة آمنة -يا أصحاب العقول السليمة-؛ رجاء تقوى الله وخشيته بطاعته دائمًا.", "isBasmala": false, "translation_en": "There is life for you in retaliation, O people of understanding, so that you may refrain.", "translation_id": "Dan dalam qishaash itu ada (jaminan kelangsungan) hidup bagimu, hai orang-orang yang berakal, supaya kamu bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 180, "text": "كُتِبَ عَلَیۡكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ إِن تَرَكَ خَیۡرًا ٱلۡوَصِیَّةُ لِلۡوَ ٰلِدَیۡنِ وَٱلۡأَقۡرَبِینَ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِینَ ۝١٨٠", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "فرض الله عليكم إذا حضر أحدكم علامات الموت ومقدماته -إن ترك مالا- الوصية بجزء من ماله للوالدين والأقربين مع مراعاة العدل؛ فلا يدع الفقير ويوصي للغني، ولا يتجاوز الثلث، وذلك حق ثابت يعمل به أهل التقوى الذين يخافون الله. وكان هذا قبل نزول آيات المواريث التي حدَّد الله فيها نصيب كل وارث.", "isBasmala": false, "translation_en": "It is decreed for you: when death approaches one of you, and he leaves wealth, to make a testament in favor of the parents and the relatives, fairly and correctly-a duty upon the righteous.", "translation_id": "Diwajibkan atas kamu, apabila seorang di antara kamu kedatangan (tanda-tanda) maut, jika ia meninggalkan harta yang banyak, berwasiat untuk ibu-bapak dan karib kerabatnya secara ma'ruf, (ini adalah) kewajiban atas orang-orang yang bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 181, "text": "فَمَنۢ بَدَّلَهُۥ بَعۡدَ مَا سَمِعَهُۥ فَإِنَّمَاۤ إِثۡمُهُۥ عَلَى ٱلَّذِینَ یُبَدِّلُونَهُۥۤۚ إِنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ ۝١٨١", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "فمَن غَيَّر وصية الميت بعدما سمعها منه قبل موته، فإنما الذنب على مَن غيَّر وبدَّل. إن الله سميع لوصيتكم وأقوالكم، عليم بما تخفيه صدوركم من الميل إلى الحق والعدل أو الجور والحيف، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "But whoever changes it after he has heard it, the guilt is upon those who change it. God is All-Hearing, All-Knowing.", "translation_id": "Maka barangsiapa yang mengubah wasiat itu, setelah ia mendengarnya, maka sesungguhnya dosanya adalah bagi orang-orang yang mengubahnya. Sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}], "28": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 182, "text": "فَمَنۡ خَافَ مِن مُّوصࣲ جَنَفًا أَوۡ إِثۡمࣰا فَأَصۡلَحَ بَیۡنَهُمۡ فَلَاۤ إِثۡمَ عَلَیۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝١٨٢", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "فمَن علم مِن موصٍ ميلا عن الحق في وصيته على سبيل الخطأ أو العمد، فنصح الموصيَ وقت الوصية بما هو الأعدل، فإن لم يحصل له ذلك فأصلح بين الأطراف بتغيير الوصية؛ لتوافق الشريعة، فلا ذنب عليه في هذا الإصلاح. إن الله غفور لعباده، رحيم بهم.", "isBasmala": false, "translation_en": "Should someone suspect bias or injustice on the part of a testator, and then reconciles between them, he commits no sin. God is Forgiving and Merciful.", "translation_id": "(Akan tetapi) barangsiapa khawatir terhadap orang yang berwasiat itu, berlaku berat sebelah atau berbuat dosa, lalu ia mendamaikan antara mereka, maka tidaklah ada dosa baginya. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 183, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُتِبَ عَلَیۡكُمُ ٱلصِّیَامُ كَمَا كُتِبَ عَلَى ٱلَّذِینَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ ۝١٨٣", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، فرض الله عليكم الصيام كما فرضه على الأمم قبلكم؛ لعلكم تتقون ربكم، فتجعلون بينكم وبين المعاصي وقاية بطاعته وعبادته وحده.", "isBasmala": false, "translation_en": "O you who believe! Fasting is prescribed for you, as it was prescribed for those before you, that you may become righteous.", "translation_id": "Hai orang-orang yang beriman, diwajibkan atas kamu berpuasa sebagaimana diwajibkan atas orang-orang sebelum kamu agar kamu bertakwa,", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 184, "text": "أَیَّامࣰا مَّعۡدُودَ ٰتࣲۚ فَمَن كَانَ مِنكُم مَّرِیضًا أَوۡ عَلَىٰ سَفَرࣲ فَعِدَّةࣱ مِّنۡ أَیَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِینَ یُطِیقُونَهُۥ فِدۡیَةࣱ طَعَامُ مِسۡكِینࣲۖ فَمَن تَطَوَّعَ خَیۡرࣰا فَهُوَ خَیۡرࣱ لَّهُۥۚ وَأَن تَصُومُوا۟ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ۝١٨٤", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "فرض الله عليكم صيام أيام معلومة العدد وهي أيام شهر رمضان. فمن كان منكم مريضًا يشق عليه الصوم، أو مسافرًا فله أن يفطر، وعليه صيام عدد من أيام أُخَر بقدر التي أفطر فيها. وعلى الذين يتكلفون الصيام ويشقُّ عليهم مشقة غير محتملة كالشيخ الكبير، والمريض الذي لا يُرْجَى شفاؤه، فدية عن كل يوم يفطره، وهي طعام مسكين، فمن زاد في قدر الفدية تبرعًا منه فهو خير له، وصيامكم خير لكم -مع تحمُّل المشقة- من إعطاء الفدية، إن كنتم تعلمون الفضل العظيم للصوم عند الله تعالى.", "isBasmala": false, "translation_en": "For a specified number of days. But whoever among you is sick, or on a journey, then a number of other days. For those who are able: a ransom of feeding a needy person. But whoever volunteers goodness, it is better for him. But to fast is best for you, if you only knew.", "translation_id": "(yaitu) dalam beberapa hari yang tertentu. Maka barangsiapa diantara kamu ada yang sakit atau dalam perjalanan (lalu ia berbuka), maka (wajiblah baginya berpuasa) sebanyak hari yang ditinggalkan itu pada hari-hari yang lain. Dan wajib bagi orang-orang yang berat menjalankannya (jika mereka tidak berpuasa) membayar fidyah, (yaitu): memberi makan seorang miskin. Barangsiapa yang dengan kerelaan hati mengerjakan kebajikan, maka itulah yang lebih baik baginya. Dan berpuasa lebih baik bagimu jika kamu mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 185, "text": "شَهۡرُ رَمَضَانَ ٱلَّذِیۤ أُنزِلَ فِیهِ ٱلۡقُرۡءَانُ هُدࣰى لِّلنَّاسِ وَبَیِّنَـٰتࣲ مِّنَ ٱلۡهُدَىٰ وَٱلۡفُرۡقَانِۚ فَمَن شَهِدَ مِنكُمُ ٱلشَّهۡرَ فَلۡیَصُمۡهُۖ وَمَن كَانَ مَرِیضًا أَوۡ عَلَىٰ سَفَرࣲ فَعِدَّةࣱ مِّنۡ أَیَّامٍ أُخَرَۗ یُرِیدُ ٱللَّهُ بِكُمُ ٱلۡیُسۡرَ وَلَا یُرِیدُ بِكُمُ ٱلۡعُسۡرَ وَلِتُكۡمِلُوا۟ ٱلۡعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡ وَلَعَلَّكُمۡ تَشۡكُرُونَ ۝١٨٥", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "شهر رمضان الذي ابتدأ الله فيه إنزال القرآن في ليلة القدر؛ هداية للناس إلى الحق، فيه أوضح الدلائل على هدى الله، وعلى الفارق بين الحق والباطل. فمن حضر منكم الشهر وكان صحيحًا مقيمًا فليصم نهاره. ويُرخَّص للمريض والمسافر في الفطر، ثم يقضيان عدد تلك الأيام. يريد الله تعالى بكم اليسر والسهولة في شرائعه، ولا يريد بكم العسر والمشقة، ولتكملوا عدة الصيام شهرًا، ولتختموا الصيام بتكبير الله في عيد الفطر، ولتعظموه على هدايته لكم، ولكي تشكروا له على ما أنعم به عليكم من الهداية والتوفيق والتيسير.", "isBasmala": false, "translation_en": "Ramadan is the month in which the Quran was revealed. Guidance for humanity, and clear portents of guidance, and the Criterion. Whoever of you witnesses the month, shall fast it. But whoever is sick, or on a journey, then a number of other days. God desires ease for you, and does not desire hardship for you, that you may complete the number, and celebrate God for having guided you, so that you may be thankful.", "translation_id": "(Beberapa hari yang ditentukan itu ialah) bulan Ramadhan, bulan yang di dalamnya diturunkan (permulaan) Al Quran sebagai petunjuk bagi manusia dan penjelasan-penjelasan mengenai petunjuk itu dan pembeda (antara yang hak dan yang bathil). Karena itu, barangsiapa di antara kamu hadir (di negeri tempat tinggalnya) di bulan itu, maka hendaklah ia berpuasa pada bulan itu, dan barangsiapa sakit atau dalam perjalanan (lalu ia berbuka), maka (wajiblah baginya berpuasa), sebanyak hari yang ditinggalkannya itu, pada hari-hari yang lain. Allah menghendaki kemudahan bagimu, dan tidak menghendaki kesukaran bagimu. Dan hendaklah kamu mencukupkan bilangannya dan hendaklah kamu mengagungkan Allah atas petunjuk-Nya yang diberikan kepadamu, supaya kamu bersyukur.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 186, "text": "وَإِذَا سَأَلَكَ عِبَادِی عَنِّی فَإِنِّی قَرِیبٌۖ أُجِیبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡیَسۡتَجِیبُوا۟ لِی وَلۡیُؤۡمِنُوا۟ بِی لَعَلَّهُمۡ یَرۡشُدُونَ ۝١٨٦", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "وإذا سألك -أيها النبي- عبادي عني فقل لهم: إني قريب منهم، أُجيب دعوة الداعي إذا دعاني، فليطيعوني فيما أمرتهم به ونهيتهم عنه، وليؤمنوا بي، لعلهم يهتدون إلى مصالح دينهم ودنياهم. وفي هذه الآية إخبار منه سبحانه عن قربه من عباده، القرب اللائق بجلاله.", "isBasmala": false, "translation_en": "And when My servants ask you about Me, I Am near; I answer the call of the caller when he calls on Me. So let them answer Me, and have faith in Me, that they may be rightly guided.", "translation_id": "Dan apabila hamba-hamba-Ku bertanya kepadamu tentang Aku, maka (jawablah), bahwasanya Aku adalah dekat. Aku mengabulkan permohonan orang yang berdoa apabila ia memohon kepada-Ku, maka hendaklah mereka itu memenuhi (segala perintah-Ku) dan hendaklah mereka beriman kepada-Ku, agar mereka selalu berada dalam kebenaran.", "manzil": 1, "manzil_display": ""}], "29": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 187, "text": "أُحِلَّ لَكُمۡ لَیۡلَةَ ٱلصِّیَامِ ٱلرَّفَثُ إِلَىٰ نِسَاۤىِٕكُمۡۚ هُنَّ لِبَاسࣱ لَّكُمۡ وَأَنتُمۡ لِبَاسࣱ لَّهُنَّۗ عَلِمَ ٱللَّهُ أَنَّكُمۡ كُنتُمۡ تَخۡتَانُونَ أَنفُسَكُمۡ فَتَابَ عَلَیۡكُمۡ وَعَفَا عَنكُمۡۖ فَٱلۡـَٔـٰنَ بَـٰشِرُوهُنَّ وَٱبۡتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمۡۚ وَكُلُوا۟ وَٱشۡرَبُوا۟ حَتَّىٰ یَتَبَیَّنَ لَكُمُ ٱلۡخَیۡطُ ٱلۡأَبۡیَضُ مِنَ ٱلۡخَیۡطِ ٱلۡأَسۡوَدِ مِنَ ٱلۡفَجۡرِۖ ثُمَّ أَتِمُّوا۟ ٱلصِّیَامَ إِلَى ٱلَّیۡلِۚ وَلَا تُبَـٰشِرُوهُنَّ وَأَنتُمۡ عَـٰكِفُونَ فِی ٱلۡمَسَـٰجِدِۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَقۡرَبُوهَاۗ كَذَ ٰلِكَ یُبَیِّنُ ٱللَّهُ ءَایَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ یَتَّقُونَ ۝١٨٧", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "أباح الله لكم في ليالي شهر رمضان جماعَ نسائكم، هنَّ ستر وحفظ لكم، وأنتم ستر وحفظ لهن. علم الله أنكم كنتم تخونون أنفسكم؛ بمخالفة ما حرَّمه الله عليكم من مجامعة النساء بعد العشاء في ليالي الصيام -وكان ذلك في أول الإسلام-، فتاب الله عليكم ووسَّع لكم في الأمر، فالآن جامعوهن، واطلبوا ما قدَّره الله لكم من الأولاد، وكلوا واشربوا حتى يتبَيَّن ضياء الصباح من سواد الليل، بظهور الفجر الصادق، ثم أتموا الصيام بالإمساك عن المفطرات إلى دخول الليل بغروب الشمس. ولا تجامعوا نساءكم أو تتعاطوا ما يفضي إلى جماعهن إذا كنتم معتكفين في المساجد؛ لأن هذا يفسد الاعتكاف (وهو الإقامة في المسجد مدة معلومة بنيَّة التقرب إلى الله تعالى). تلك الأحكام التي شرعها الله لكم هي حدوده الفاصلة بين الحلال والحرام، فلا تقربوها حتى لا تقعوا في الحرام. بمثل هذا البيان الواضح يبين الله آياته وأحكامه للناس؛ كي يتقوه ويخشَوْه.", "isBasmala": false, "translation_en": "Permitted for you is intercourse with your wives on the night of the fast. They are a garment for you, and you are a garment for them. God knows that you used to betray yourselves, but He turned to you and pardoned you. So approach them now, and seek what God has ordained for you, and eat and drink until the white streak of dawn can be distinguished from the black streak. Then complete the fast until nightfall. But do not approach them while you are in retreat at the mosques. These are the limits of God, so do not come near them. God thus clarifies His revelations to the people, that they may attain piety.", "translation_id": "Dihalalkan bagi kamu pada malam hari bulan puasa bercampur dengan isteri-isteri kamu; mereka adalah pakaian bagimu, dan kamupun adalah pakaian bagi mereka. Allah mengetahui bahwasanya kamu tidak dapat menahan nafsumu, karena itu Allah mengampuni kamu dan memberi maaf kepadamu. Maka sekarang campurilah mereka dan ikutilah apa yang telah ditetapkan Allah untukmu, dan makan minumlah hingga terang bagimu benang putih dari benang hitam, yaitu fajar. Kemudian sempurnakanlah puasa itu sampai (datang) malam, (tetapi) janganlah kamu campuri mereka itu, sedang kamu beri'tikaf dalam mesjid. Itulah larangan Allah, maka janganlah kamu mendekatinya. Demikianlah Allah menerangkan ayat-ayat-Nya kepada manusia, supaya mereka bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 188, "text": "وَلَا تَأۡكُلُوۤا۟ أَمۡوَ ٰلَكُم بَیۡنَكُم بِٱلۡبَـٰطِلِ وَتُدۡلُوا۟ بِهَاۤ إِلَى ٱلۡحُكَّامِ لِتَأۡكُلُوا۟ فَرِیقࣰا مِّنۡ أَمۡوَ ٰلِ ٱلنَّاسِ بِٱلۡإِثۡمِ وَأَنتُمۡ تَعۡلَمُونَ ۝١٨٨", "juz": 2, "hizb": "(*½ ح 3*)", "tafsir": "ولا يأكل بعضكم مال بعض بسبب باطل كاليمين الكاذبة، والغصب، والسرقة، والرشوة، والربا ونحو ذلك، ولا تلقوا بالحجج الباطلة إلى الحكام؛ لتأكلوا عن طريق التخاصم أموال طائفة من الناس بالباطل، وأنتم تعلمون تحريم ذلك عليكم.", "isBasmala": false, "translation_en": "And do not consume one another's wealth by unjust means, nor offer it as bribes to the officials in order to consume part of other people's wealth illicitly, while you know.", "translation_id": "Dan janganlah sebahagian kamu memakan harta sebahagian yang lain di antara kamu dengan jalan yang bathil dan (janganlah) kamu membawa (urusan) harta itu kepada hakim, supaya kamu dapat memakan sebahagian daripada harta benda orang lain itu dengan (jalan berbuat) dosa, padahal kamu mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 189, "text": "۞ یَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِیَ مَوَ ٰقِیتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَیۡسَ ٱلۡبِرُّ بِأَن تَأۡتُوا۟ ٱلۡبُیُوتَ مِن ظُهُورِهَا وَلَـٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُوا۟ ٱلۡبُیُوتَ مِنۡ أَبۡوَ ٰبِهَاۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ۝١٨٩", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "يسألك أصحابك -أيها النبي-: عن الأهلة وتغيُّر أحوالها، قل لهم: جعل اللهُ الأهلة علامات يعرف بها الناس أوقات عباداتهم المحددة بوقت مثل الصيام والحج، ومعاملاتهم. وليس الخير ما تعودتم عليه في الجاهلية وأول الإسلام من دخول البيوت من ظهورها حين تُحْرِمون بالحج أو العمرة، ظانين أن ذلك قربة إلى الله، ولكن الخير هو فِعْلُ مَنِ اتقى الله واجتنب المعاصي، وادخلوا البيوت من أبوابها عند إحرامكم بالحج أو العمرة، واخشوا الله تعالى في كل أموركم، لتفوزوا بكل ما تحبون من خيري الدنيا والآخرة.", "isBasmala": false, "translation_en": "They ask you about the crescents. Say, \"They are timetables for people, and for the Hajj.\" It is not virtuous that you approach homes from their backs, but virtue is to be pious. So approach homes from their doors, and observe God, that you may succeed.", "translation_id": "Mereka bertanya kepadamu tentang bulan sabit. Katakanlah: \"Bulan sabit itu adalah tanda-tanda waktu bagi manusia dan (bagi ibadat) haji; Dan bukanlah kebajikan memasuki rumah-rumah dari belakangnya, akan tetapi kebajikan itu ialah kebajikan orang yang bertakwa. Dan masuklah ke rumah-rumah itu dari pintu-pintunya; dan bertakwalah kepada Allah agar kamu beruntung.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 190, "text": "وَقَـٰتِلُوا۟ فِی سَبِیلِ ٱللَّهِ ٱلَّذِینَ یُقَـٰتِلُونَكُمۡ وَلَا تَعۡتَدُوۤا۟ۚ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡمُعۡتَدِینَ ۝١٩٠", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "وقاتلوا -أيها المؤمنون- لنصرة دين الله الذين يقاتلونكم، ولا ترتكبوا المناهي من المُثْلة، والغُلول، وقَتْلِ من لا يحل قتله من النساء والصبيان والشيوخ، ومن في حكمهم. إن الله لا يحب الذين يجاوزون حدوده، فيستحلون ما حرَّم الله ورسوله.", "isBasmala": false, "translation_en": "And fight in the cause of God those who fight you, but do not commit aggression; God does not love the aggressors.", "translation_id": "Dan perangilah di jalan Allah orang-orang yang memerangi kamu, (tetapi) janganlah kamu melampaui batas, karena sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas.", "manzil": 1, "manzil_display": ""}], "30": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 191, "text": "وَٱقۡتُلُوهُمۡ حَیۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَیۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَـٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ یُقَـٰتِلُوكُمۡ فِیهِۖ فَإِن قَـٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَ ٰلِكَ جَزَاۤءُ ٱلۡكَـٰفِرِینَ ۝١٩١", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "واقتلوا الذين يقاتلونكم من المشركين حيث وجدتموهم، وأخرجوهم من المكان الذي أخرجوكم منه وهو \"مكة\". والفتنة -وهي الكفر والشرك والصد عن الإسلام- أشد من قتلكم إياهم. ولا تبدؤوهم بالقتال عند المسجد الحرام تعظيمًا لحرماته حتى يبدؤوكم بالقتال فيه، فإن قاتلوكم في المسجد الحرام فاقتلوهم فيه. مثل ذلك الجزاء الرادع يكون جزاء الكافرين.", "isBasmala": false, "translation_en": "And kill them wherever you overtake them, and expel them from where they had expelled you. Oppression is more serious than murder. But do not fight them at the Sacred Mosque, unless they fight you there. If they fight you, then kill them. Such is the retribution of the disbelievers.", "translation_id": "Dan bunuhlah mereka di mana saja kamu jumpai mereka, dan usirlah mereka dari tempat mereka telah mengusir kamu (Mekah); dan fitnah itu lebih besar bahayanya dari pembunuhan, dan janganlah kamu memerangi mereka di Masjidil Haram, kecuali jika mereka memerangi kamu di tempat itu. Jika mereka memerangi kamu (di tempat itu), maka bunuhlah mereka. Demikanlah balasan bagi orang-orang kafir.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 192, "text": "فَإِنِ ٱنتَهَوۡا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝١٩٢", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "فإن تركوا ما هم فيه من الكفر وقتالكم عند المسجد الحرام، ودخلوا في الإيمان، فإن الله غفور لعباده، رحيم بهم.", "isBasmala": false, "translation_en": "But if they cease, then God is Forgiving and Merciful.", "translation_id": "Kemudian jika mereka berhenti (dari memusuhi kamu), maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 193, "text": "وَقَـٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةࣱ وَیَكُونَ ٱلدِّینُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡا۟ فَلَا عُدۡوَ ٰنَ إِلَّا عَلَى ٱلظَّـٰلِمِینَ ۝١٩٣", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "واستمروا- أيها المؤمنون- في قتال المشركين المعتدين، حتى لا تكون فتنة للمسلمين عن دينهم ولا شرك بالله، ويبقى الدين لله وحده خالصًا لا يُعْبَد معه غيره. فإن كفُّوا عن الكفر والقتال فكُفُّوا عنهم؛ فالعقوبة لا تكون إلا على المستمرين على كفرهم وعدوانهم.", "isBasmala": false, "translation_en": "And fight them until there is no oppression, and worship becomes devoted to God alone. But if they cease, then let there be no hostility except against the oppressors.", "translation_id": "Dan perangilah mereka itu, sehingga tidak ada fitnah lagi dan (sehingga) ketaatan itu hanya semata-mata untuk Allah. Jika mereka berhenti (dari memusuhi kamu), maka tidak ada permusuhan (lagi), kecuali terhadap orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 194, "text": "ٱلشَّهۡرُ ٱلۡحَرَامُ بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَـٰتُ قِصَاصࣱۚ فَمَنِ ٱعۡتَدَىٰ عَلَیۡكُمۡ فَٱعۡتَدُوا۟ عَلَیۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَیۡكُمۡۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِینَ ۝١٩٤", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "قتالكم -أيها المؤمنون- للمشركين في الشهر الذي حرَّم الله القتال فيه هو جزاء لقتالهم لكم في الشهر الحرام. والذي يعتدي على ما حَرَّم الله من المكان والزمان، يعاقب بمثل فعله، ومن جنس عمله. فمن اعتدى عليكم بالقتال أو غيره فأنزلوا به عقوبة مماثلة لجنايته، ولا حرج عليكم في ذلك؛ لأنهم هم البادئون بالعدوان، وخافوا الله فلا تتجاوزوا المماثلة في العقوبة، واعلموا أن الله مع الذين يتقونه ويطيعونه بأداء فرائضه وتجنب محارمه.", "isBasmala": false, "translation_en": "The sacred month for the sacred month; and sacrilege calls for retaliation. Whoever commits aggression against you, retaliate against him in the same measure as he has committed against you. And be conscious of God, and know that God is with the righteous.", "translation_id": "Bulan haram dengan bulan haram, dan pada sesuatu yang patut dihormati, berlaku hukum qishaash. Oleh sebab itu barangsiapa yang menyerang kamu, maka seranglah ia, seimbang dengan serangannya terhadapmu. Bertakwalah kepada Allah dan ketahuilah, bahwa Allah beserta orang-orang yang bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 195, "text": "وَأَنفِقُوا۟ فِی سَبِیلِ ٱللَّهِ وَلَا تُلۡقُوا۟ بِأَیۡدِیكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوۤا۟ۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُحۡسِنِینَ ۝١٩٥", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "واستمروا- أيها المؤمنون- في إنفاق الأموال لنصرة دين الله تعالى، والجهاد في سبيله، ولا توقعوا أنفسكم في المهالك بترك الجهاد في سبيل الله، وعدم الإنفاق فيه، وأحسنوا في الانفاق والطاعة، واجعلوا عملكم كله خالصًا لوجه الله تعالى. إن الله يحب أهل الإخلاص والإحسان.", "isBasmala": false, "translation_en": "And spend in the cause of God, and do not throw yourselves with your own hands into ruin, and be charitable. God loves the charitable.", "translation_id": "Dan belanjakanlah (harta bendamu) di jalan Allah, dan janganlah kamu menjatuhkan dirimu sendiri ke dalam kebinasaan, dan berbuat baiklah, karena sesungguhnya Allah menyukai orang-orang yang berbuat baik.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 196, "text": "وَأَتِمُّوا۟ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَیۡسَرَ مِنَ ٱلۡهَدۡیِۖ وَلَا تَحۡلِقُوا۟ رُءُوسَكُمۡ حَتَّىٰ یَبۡلُغَ ٱلۡهَدۡیُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِیضًا أَوۡ بِهِۦۤ أَذࣰى مِّن رَّأۡسِهِۦ فَفِدۡیَةࣱ مِّن صِیَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكࣲۚ فَإِذَاۤ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ فَمَا ٱسۡتَیۡسَرَ مِنَ ٱلۡهَدۡیِۚ فَمَن لَّمۡ یَجِدۡ فَصِیَامُ ثَلَـٰثَةِ أَیَّامࣲ فِی ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةࣱ كَامِلَةࣱۗ ذَ ٰلِكَ لِمَن لَّمۡ یَكُنۡ أَهۡلُهُۥ حَاضِرِی ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ ۝١٩٦", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "وأدُّوا الحج والعمرة تامَّيْنِ، خالصين لوجه الله تعالى. فإن منعكم عن الذهاب لإتمامهما بعد الإحرام بهما مانع كالعدو والمرض، فالواجب عليكم ذَبْحُ ما تيسر لكم من الإبل أو البقر أو الغنم تقربًا إلى الله تعالى؛ لكي تَخْرُجوا من إحرامكم بحلق شعر الرأس أو تقصيره، ولا تحلقوا رؤوسكم إذا كنتم محصرين حتى ينحر المحصر هديه في الموضع الذي حُصر فيه ثم يحل من إحرامه، كما نحر النبي صلى الله عليه وسلم في \"الحديبية\" ثم حلق رأسه، وغير المحصر لا ينحر الهدي إلا في الحرم، الذي هو محله في يوم العيد، اليوم العاشر وما بعده من أيام التشريق. فمن كان منكم مريضًا، أو به أذى من رأسه يحتاج معه إلى الحلق -وهو مُحْرِم- حَلَق، وعليه فدية: بأن يصوم ثلاثة أيام، أو يتصدق على ستة مساكين لكل مسكين نصف صاع من طعام، أو يذبح شاة لفقراء الحرم. فإذا كنتم في أمن وصحَّة: فمن استمتع بالعمرة إلى الحج وذلك باستباحة ما حُرِّم عليه بسبب الإحرام بعد انتهاء عمرته، فعليه ذبح ما تيسر من الهدي، فمن لم يجد هَدْيًا يذبحه فعليه صيام ثلاثة أيام في أشهر الحج، وسبعة إذا فرغتم من أعمال الحج ورجعتم إلى أهليكم، تلك عشرة كاملة لا بد من صيامها. ذلك الهَدْيُ وما ترتب عليه من الصيام لمن لم يكن أهله من ساكني أرض الحرم، وخافوا الله تعالى وحافظوا على امتثال أوامره واجتناب نواهيه، واعلموا أن الله شديد العقاب لمن خالف أمره، وارتكب ما عنه زجر.", "isBasmala": false, "translation_en": "And carry out the Hajj and the Umrah for God. But if you are prevented, then whatever is feasible of offerings. And do not shave your heads until the offering has reached its destination. Whoever of you is sick, or has an injury of the head, then redemption of fasting, or charity, or worship. When you are secure: whoever continues the Umrah until the Hajj, then whatever is feasible of offering. But if he lacks the means, then fasting for three days during the Hajj and seven when you have returned, making ten in all. This is for he whose household is not present at the Sacred Mosque. And remain conscious of God, and know that God is stern in retribution.", "translation_id": "Dan sempurnakanlah ibadah haji dan 'umrah karena Allah. Jika kamu terkepung (terhalang oleh musuh atau karena sakit), maka (sembelihlah) korban yang mudah didapat, dan jangan kamu mencukur kepalamu, sebelum korban sampai di tempat penyembelihannya. Jika ada di antaramu yang sakit atau ada gangguan di kepalanya (lalu ia bercukur), maka wajiblah atasnya berfid-yah, yaitu: berpuasa atau bersedekah atau berkorban. Apabila kamu telah (merasa) aman, maka bagi siapa yang ingin mengerjakan 'umrah sebelum haji (di dalam bulan haji), (wajiblah ia menyembelih) korban yang mudah didapat. Tetapi jika ia tidak menemukan (binatang korban atau tidak mampu), maka wajib berpuasa tiga hari dalam masa haji dan tujuh hari (lagi) apabila kamu telah pulang kembali. Itulah sepuluh (hari) yang sempurna. Demikian itu (kewajiban membayar fidyah) bagi orang-orang yang keluarganya tidak berada (di sekitar) Masjidil Haram (orang-orang yang bukan penduduk kota Mekah). Dan bertakwalah kepada Allah dan ketahuilah bahwa Allah sangat keras siksaan-Nya.", "manzil": 1, "manzil_display": ""}], "31": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 197, "text": "ٱلۡحَجُّ أَشۡهُرࣱ مَّعۡلُومَـٰتࣱۚ فَمَن فَرَضَ فِیهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِی ٱلۡحَجِّۗ وَمَا تَفۡعَلُوا۟ مِنۡ خَیۡرࣲ یَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُوا۟ فَإِنَّ خَیۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ ۝١٩٧", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "وقت الحج أشهر معلومات، وهي: شوال، وذو القعدة، وعشر من ذي الحجة. فمن أوجب الحج على نفسه فيهن بالإحرام، فيحرم عليه الجماع ومقدماته القولية والفعلية، ويحرم عليه الخروج عن طاعة الله تعالى بفعل المعاصي، والجدال في الحج الذي يؤدي إلى الغضب والكراهية. وما تفعلوا من خير يعلمه الله، فيجازي كلا على عمله. وخذوا لأنفسكم زادًا من الطعام والشراب لسفر الحج، وزادًا من صالح الأعمال للدار الآخرة، فإن خير الزاد تقوى الله، وخافوني يا أصحاب العقول السليمة.", "isBasmala": false, "translation_en": "The Hajj is during specific months. Whoever decides to perform the Hajj-there shall be no sexual relations, nor misconduct, nor quarrelling during the Hajj. And whatever good you do, God knows it. And take provisions, but the best provision is righteousness. And be mindful of Me, O people of understanding.", "translation_id": "(Musim) haji adalah beberapa bulan yang dimaklumi, barangsiapa yang menetapkan niatnya dalam bulan itu akan mengerjakan haji, maka tidak boleh rafats, berbuat fasik dan berbantah-bantahan di dalam masa mengerjakan haji. Dan apa yang kamu kerjakan berupa kebaikan, niscaya Allah mengetahuinya. Berbekallah, dan sesungguhnya sebaik-baik bekal adalah takwa dan bertakwalah kepada-Ku hai orang-orang yang berakal.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 198, "text": "لَیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَن تَبۡتَغُوا۟ فَضۡلࣰا مِّن رَّبِّكُمۡۚ فَإِذَاۤ أَفَضۡتُم مِّنۡ عَرَفَـٰتࣲ فَٱذۡكُرُوا۟ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّاۤلِّینَ ۝١٩٨", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "ليس عليكم حرج في أن تطلبوا رزقًا من ربكم بالربح من التجارة في أيام الحج. فإذا دفعتم بعد غروب الشمس راجعين من \"عرفات\" -وهي المكان الذي يقف فيه الحجاج يوم التاسع من ذي الحجة- فاذكروا الله بالتسبيح والتلبية والدعاء عند المشعر الحرام -\"المزدلفة\"-، واذكروا الله على الوجه الصحيح الذي هداكم إليه، ولقد كنتم من قبل هذا الهدى في ضلال لا تعرفون معه الحق.", "isBasmala": false, "translation_en": "You commit no error by seeking bounty from your Lord. When you disperse from Arafat, remember God at the Sacred Landmark. And remember Him as He has guided you. Although, before that, you were of those astray.", "translation_id": "Tidak ada dosa bagimu untuk mencari karunia (rezeki hasil perniagaan) dari Tuhanmu. Maka apabila kamu telah bertolak dari 'Arafat, berdzikirlah kepada Allah di Masy'arilharam. Dan berdzikirlah (dengan menyebut) Allah sebagaimana yang ditunjukkan-Nya kepadamu; dan sesungguhnya kamu sebelum itu benar-benar termasuk orang-orang yang sesat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 199, "text": "ثُمَّ أَفِیضُوا۟ مِنۡ حَیۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝١٩٩", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "وليكن اندفاعكم من \"عرفات\" التي أفاض منها إبراهيم عليه السلام مخالفين بذلك من لا يقف بها من أهل الجاهلية، واسألوا الله أن يغفر لكم ذنوبكم. إن الله غفور لعباده المستغفرين التائبين، رحيم بهم.", "isBasmala": false, "translation_en": "Then disperse from where the people disperse, and ask God for forgiveness. God is Most Forgiving, Most Merciful.", "translation_id": "Kemudian bertolaklah kamu dari tempat bertolaknya orang-orang banyak ('Arafah) dan mohonlah ampun kepada Allah; sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 200, "text": "فَإِذَا قَضَیۡتُم مَّنَـٰسِكَكُمۡ فَٱذۡكُرُوا۟ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَاۤءَكُمۡ أَوۡ أَشَدَّ ذِكۡرࣰاۗ فَمِنَ ٱلنَّاسِ مَن یَقُولُ رَبَّنَاۤ ءَاتِنَا فِی ٱلدُّنۡیَا وَمَا لَهُۥ فِی ٱلۡـَٔاخِرَةِ مِنۡ خَلَـٰقࣲ ۝٢٠٠", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "فإذا أتممتم عبادتكم، وفرغتم من أعمال الحج، فأكثروا من ذكر الله والثناء عليه، مثل ذكركم مفاخر آبائكم وأعظم من ذلك. فمن الناس فريق يجعل همه الدنيا فقط، فيدعو قائلا ربنا آتنا في الدنيا صحة، ومالا وأولادًا، وهؤلاء ليس لهم في الآخرة حظ ولا نصيب؛ لرغبتهم عنها وقَصْرِ هَمِّهم على الدنيا.", "isBasmala": false, "translation_en": "When you have completed your rites, remember God as you remember your parents, or even more. Among the people is he who says, \"Our Lord, give us in this world,\" yet he has no share in the Hereafter.", "translation_id": "Apabila kamu telah menyelesaikan ibadah hajimu, maka berdzikirlah dengan menyebut Allah, sebagaimana kamu menyebut-nyebut (membangga-banggakan) nenek moyangmu, atau (bahkan) berdzikirlah lebih banyak dari itu. Maka di antara manusia ada orang yang bendoa: \"Ya Tuhan kami, berilah kami (kebaikan) di dunia\", dan tiadalah baginya bahagian (yang menyenangkan) di akhirat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 201, "text": "وَمِنۡهُم مَّن یَقُولُ رَبَّنَاۤ ءَاتِنَا فِی ٱلدُّنۡیَا حَسَنَةࣰ وَفِی ٱلۡـَٔاخِرَةِ حَسَنَةࣰ وَقِنَا عَذَابَ ٱلنَّارِ ۝٢٠١", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "ومن الناس فريق مؤمن يقول في دعائه: ربنا آتنا في الدنيا عافية ورزقًا وعلمًا نافعًا، وعملا صالحًا، وغير ذلك من أمور الدين والدنيا، وفي الآخرة الجنة، واصرف عنَّا عذاب النار. وهذا الدعاء من أجمع الأدعية، ولهذا كان أكثر دعاء النبي صلى الله عليه وسلم، كما ثبت في الصحيحين.", "isBasmala": false, "translation_en": "And among them is he who says, \"Our Lord, give us goodness in this world, and goodness in the Hereafter, and protect us from the torment of the Fire.\"", "translation_id": "Dan di antara mereka ada orang yang berdoa: \"Ya Tuhan kami, berilah kami kebaikan di dunia dan kebaikan di akhirat dan peliharalah kami dari siksa neraka\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 202, "text": "أُو۟لَـٰۤىِٕكَ لَهُمۡ نَصِیبࣱ مِّمَّا كَسَبُوا۟ۚ وَٱللَّهُ سَرِیعُ ٱلۡحِسَابِ ۝٢٠٢", "juz": 2, "hizb": "(*¾ ح 3*)", "tafsir": "أولئك الداعون بهذا الدعاء لهم ثواب عظيم بسبب ما كسبوه من الأعمال الصالحة. والله سريع الحساب، مُحْصٍ أعمال عباده، ومجازيهم بها.", "isBasmala": false, "translation_en": "These will have a share of what they have earned. God is swift in reckoning.", "translation_id": "Mereka itulah orang-orang yang mendapat bahagian daripada yang mereka usahakan; dan Allah sangat cepat perhitungan-Nya.", "manzil": 1, "manzil_display": ""}], "32": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 203, "text": "۞ وَٱذۡكُرُوا۟ ٱللَّهَ فِیۤ أَیَّامࣲ مَّعۡدُودَ ٰتࣲۚ فَمَن تَعَجَّلَ فِی یَوۡمَیۡنِ فَلَاۤ إِثۡمَ عَلَیۡهِ وَمَن تَأَخَّرَ فَلَاۤ إِثۡمَ عَلَیۡهِۖ لِمَنِ ٱتَّقَىٰۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّكُمۡ إِلَیۡهِ تُحۡشَرُونَ ۝٢٠٣", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "واذكروا الله تسبيحًا وتكبيرًا في أيام قلائل، وهي أيام التشريق: الحادي عشر والثاني عشر والثالث عشر من شهر ذي الحجة. فمن أراد التعجل وخرج من \"مِنى\" قبل غروب شمس اليوم الثاني عشر بعد رمي الجمار فلا ذنب عليه، ومن تأخر بأن بات بـ \"مِنى\" حتى يرمي الجمار في اليوم الثالث عشر فلا ذنب عليه، لمن اتقى الله في حجه. والتأخر أفضل؛ لأنه تزوُّد في العبادة واقتداء بفعل النبي صلى الله عليه وسلم. وخافوا الله- أيها المسلمون- وراقبوه في كل أعمالكم، واعلموا أنكم إليه وحده تُحْشَرون بعد موتكم للحساب والجزاء.", "isBasmala": false, "translation_en": "And remember God during the designated days. But whoever hurries on in two days commits no wrong, and whoever stays on commits no wrong-provided he maintains righteousness. And obey God, and know that to Him you will be gathered.", "translation_id": "Dan berdzikirlah (dengan menyebut) Allah dalam beberapa hari yang berbilang. Barangsiapa yang ingin cepat berangkat (dari Mina) sesudah dua hari, maka tiada dosa baginya. Dan barangsiapa yang ingin menangguhkan (keberangkatannya dari dua hari itu), maka tidak ada dosa pula baginya, bagi orang yang bertakwa. Dan bertakwalah kepada Allah, dan ketahuilah, bahwa kamu akan dikumpulkan kepada-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 204, "text": "وَمِنَ ٱلنَّاسِ مَن یُعۡجِبُكَ قَوۡلُهُۥ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَیُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِی قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ ۝٢٠٤", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "وبعض الناس من المنافقين يعجبك -أيها الرسول- كلامه الفصيح الذي يريد به حظًّا من حظوظ الدنيا لا الآخرة، ويحلف مستشهدًا بالله على ما في قلبه من محبة الإسلام، وفي هذا غاية الجرأة على الله، وهو شديد العداوة والخصومة للإسلام والمسلمين.", "isBasmala": false, "translation_en": "Among the people is he whose speech about the worldly life impresses you, and he calls God to witness what is in his heart, while he is the most hostile of adversaries.", "translation_id": "Dan di antara manusia ada orang yang ucapannya tentang kehidupan dunia menarik hatimu, dan dipersaksikannya kepada Allah (atas kebenaran) isi hatinya, padahal ia adalah penantang yang paling keras.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 205, "text": "وَإِذَا تَوَلَّىٰ سَعَىٰ فِی ٱلۡأَرۡضِ لِیُفۡسِدَ فِیهَا وَیُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۗ وَٱللَّهُ لَا یُحِبُّ ٱلۡفَسَادَ ۝٢٠٥", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "وإذا خرج من عندك أيها الرسول، جَدَّ ونَشِط في الأرض ليفسد فيها، ويتلف زروع الناس، ويقتل ماشيتهم. والله لا يحب الفساد.", "isBasmala": false, "translation_en": "When he gains power, he strives to spread corruption on earth, destroying properties and lives. God does not like corruption.", "translation_id": "Dan apabila ia berpaling (dari kamu), ia berjalan di bumi untuk mengadakan kerusakan padanya, dan merusak tanam-tanaman dan binatang ternak, dan Allah tidak menyukai kebinasaan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 206, "text": "وَإِذَا قِیلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ ۝٢٠٦", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "وإذا نُصِح ذلك المنافق المفسد، وقيل له: اتق الله واحذر عقابه، وكُفَّ عن الفساد في الأرض، لم يقبل النصيحة، بل يحمله الكبر وحميَّة الجاهلية على مزيد من الآثام، فَحَسْبُه جهنم وكافيته عذابًا، ولبئس الفراش هي.", "isBasmala": false, "translation_en": "And when he is told, \"Beware of God,\" his pride leads him to more sin. Hell is enough for him-a dreadful abode.", "translation_id": "Dan apabila dikatakan kepadanya: \"Bertakwalah kepada Allah\", bangkitlah kesombongannya yang menyebabkannya berbuat dosa. Maka cukuplah (balasannya) neraka Jahannam. Dan sungguh neraka Jahannam itu tempat tinggal yang seburuk-buruknya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 207, "text": "وَمِنَ ٱلنَّاسِ مَن یَشۡرِی نَفۡسَهُ ٱبۡتِغَاۤءَ مَرۡضَاتِ ٱللَّهِۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ ۝٢٠٧", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "وبعض الناس يبيع نفسه طلبًا لرضا الله عنه، بالجهاد في سبيله، والتزام طاعته. والله رءوف بالعباد، يرحم عباده المؤمنين رحمة واسعة في عاجلهم وآجلهم، فيجازبهم أحسن الجزاء.", "isBasmala": false, "translation_en": "And among the people is he who sells himself seeking God's approval. God is kind towards the servants.", "translation_id": "Dan di antara manusia ada orang yang mengorbankan dirinya karena mencari keridhaan Allah; dan Allah Maha Penyantun kepada hamba-hamba-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 208, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱدۡخُلُوا۟ فِی ٱلسِّلۡمِ كَاۤفَّةࣰ وَلَا تَتَّبِعُوا۟ خُطُوَ ٰتِ ٱلشَّیۡطَـٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینࣱ ۝٢٠٨", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "يا أيها الذين آمنوا بالله ربًا وبمحمد نبيًا ورسولا وبالإسلام دينًا، ادخلوا في جميع شرائع الإسلام، عاملين بجميع أحكامه، ولا تتركوا منها شيئًا، ولا تتبعوا طرق الشيطان فيما يدعوكم إليه من المعاصي. إنه لكم عدو ظاهر العداوة فاحذروه.", "isBasmala": false, "translation_en": "O you who believe! Enter into submission, wholeheartedly, and do not follow the footsteps of Satan; he is to you an outright enemy.", "translation_id": "Hai orang-orang yang beriman, masuklah kamu ke dalam Islam keseluruhan, dan janganlah kamu turut langkah-langkah syaitan. Sesungguhnya syaitan itu musuh yang nyata bagimu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 209, "text": "فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَاۤءَتۡكُمُ ٱلۡبَیِّنَـٰتُ فَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ عَزِیزٌ حَكِیمٌ ۝٢٠٩", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "فإن انحرفتم عن طريق الحق، من بعد ما جاءتكم الحجج الواضحة من القرآن والسنة، فاعلموا أن الله عزيز في ملكه لا يفوته شيء، حكيم في أمره ونهيه، يضع كل شيء في موضعه المناسب له.", "isBasmala": false, "translation_en": "But if you slip after the proofs have come to you, know that God is Powerful and Wise.", "translation_id": "Tetapi jika kamu menyimpang (dari jalan Allah) sesudah datang kepadamu bukti-bukti kebenaran, maka ketahuilah, bahwasanya Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 210, "text": "هَلۡ یَنظُرُونَ إِلَّاۤ أَن یَأۡتِیَهُمُ ٱللَّهُ فِی ظُلَلࣲ مِّنَ ٱلۡغَمَامِ وَٱلۡمَلَـٰۤىِٕكَةُ وَقُضِیَ ٱلۡأَمۡرُۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ۝٢١٠", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "ما ينتظر هؤلاء المعاندون الكافرون بعد قيام الأدلة البينة إلا أن يأتيهم الله عز وجل على الوجه اللائق به سبحانه في ظُلَل من السحاب يوم القيامة؛ ليفصل بينهم بالقضاء العادل، وأن تأتي الملائكة، وحينئذ يقضي الله تعالى فيهم قضاءه. وإليه وحده ترجع أمور الخلائق جميعها.", "isBasmala": false, "translation_en": "Are they waiting for God Himself to come to them in the shadows of the clouds, together with the angels, and thus the matter is settled? All things are returned to God.", "translation_id": "Tiada yang mereka nanti-nantikan melainkan datangnya Allah dan malaikat (pada hari kiamat) dalam naungan awan, dan diputuskanlah perkaranya. Dan hanya kepada Allah dikembalikan segala urusan.", "manzil": 1, "manzil_display": ""}], "33": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 211, "text": "سَلۡ بَنِیۤ إِسۡرَ ٰۤءِیلَ كَمۡ ءَاتَیۡنَـٰهُم مِّنۡ ءَایَةِۭ بَیِّنَةࣲۗ وَمَن یُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَاۤءَتۡهُ فَإِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ ۝٢١١", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "سل -أيها الرسول- بني إسرائيل المعاندين لك: كم أعطيناهم من آيات واضحات في كتبهم تهديهم إلى الحق، فكفروا بها كلها، وأعرضوا عنها، وحَرَّفوها عن مواضعها. ومن يبدل نعمة الله -وهي دينه- ويكفر بها من بعد معرفتها، وقيام الحجة عليه بها، فإن الله تعالى شديد العقاب له.", "isBasmala": false, "translation_en": "Ask the Children of Israel how many clear signs We have given them. Whoever alters the blessing of God after it has come to him-God is severe in retribution.", "translation_id": "Tanyakanlah kepada Bani Israil: \"Berapa banyaknya tanda-tanda (kebenaran) yang nyata, yang telah Kami berikan kepada mereka\". Dan barangsiapa yang menukar nikmat Allah setelah datang nikmat itu kepadanya, maka sesungguhnya Allah sangat keras siksa-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 212, "text": "زُیِّنَ لِلَّذِینَ كَفَرُوا۟ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَیَسۡخَرُونَ مِنَ ٱلَّذِینَ ءَامَنُوا۟ۘ وَٱلَّذِینَ ٱتَّقَوۡا۟ فَوۡقَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۗ وَٱللَّهُ یَرۡزُقُ مَن یَشَاۤءُ بِغَیۡرِ حِسَابࣲ ۝٢١٢", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "حُسِّن للذين جحدوا وحدانية الله الحياةُ الدنيا وما فيها من الشهوات والملذات، وهم يستهزئون بالمؤمنين. وهؤلاء الذين يخشون ربهم فوق جميع الكفار يوم القيامة؛ حيث يدخلهم الله أعلى درجات الجنة، وينزل الكافرين أسفل دركات النار. والله يرزق مَن يشاء مِن خلقه بغير حساب.", "isBasmala": false, "translation_en": "Beautified is the life of this world for those who disbelieve, and they ridicule those who believe. But the righteous will be above them on the Day of Resurrection. God provides to whomever He wills without measure.", "translation_id": "Kehidupan dunia dijadikan indah dalam pandangan orang-orang kafir, dan mereka memandang hina orang-orang yang beriman. Padahal orang-orang yang bertakwa itu lebih mulia daripada mereka di hari kiamat. Dan Allah memberi rezeki kepada orang-orang yang dikehendaki-Nya tanpa batas.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 213, "text": "كَانَ ٱلنَّاسُ أُمَّةࣰ وَ ٰحِدَةࣰ فَبَعَثَ ٱللَّهُ ٱلنَّبِیِّـۧنَ مُبَشِّرِینَ وَمُنذِرِینَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ لِیَحۡكُمَ بَیۡنَ ٱلنَّاسِ فِیمَا ٱخۡتَلَفُوا۟ فِیهِۚ وَمَا ٱخۡتَلَفَ فِیهِ إِلَّا ٱلَّذِینَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَاۤءَتۡهُمُ ٱلۡبَیِّنَـٰتُ بَغۡیَۢا بَیۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ لِمَا ٱخۡتَلَفُوا۟ فِیهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ یَهۡدِی مَن یَشَاۤءُ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمٍ ۝٢١٣", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "كان الناس جماعة واحدة، متفقين على الإيمان بالله ثم اختلفوا في دينهم، فبعث الله النبيين دعاة لدين الله، مبشرين مَن أطاع الله بالجنة، ومحذرين من كفر به وعصاه النار، وأنزل معهم الكتب السماوية بالحق الذي اشتملت عليه؛ ليحكموا بما فيها بين الناس فيما اختلفوا فيه، وما اخْتَلَف في أمر محمد صلى الله عليه وسلم وكتابه ظلمًا وحسدًا إلا الذين أعطاهم الله التوراة، وعرفوا ما فيها من الحجج والأحكام، فوفَّق الله المؤمنين بفضله إلى تمييز الحق من الباطل، ومعرفة ما اختلفوا فيه. والله يوفِّق من يشاء من عباده إلى طريق مستقيم.", "isBasmala": false, "translation_en": "Humanity used to be one community; then God sent the prophets, bringing good news and giving warnings. And He sent down with them the Scripture, with the truth, to judge between people regarding their differences. But none differed over it except those who were given it-after the proofs had come to them-out of mutual envy between them. Then God guided those who believed to the truth they had disputed, in accordance with His will. God guides whom He wills to a straight path.", "translation_id": "Manusia itu adalah umat yang satu. (setelah timbul perselisihan), maka Allah mengutus para nabi, sebagai pemberi peringatan, dan Allah menurunkan bersama mereka Kitab yang benar, untuk memberi keputusan di antara manusia tentang perkara yang mereka perselisihkan. Tidaklah berselisih tentang Kitab itu melainkan orang yang telah didatangkan kepada mereka Kitab, yaitu setelah datang kepada mereka keterangan-keterangan yang nyata, karena dengki antara mereka sendiri. Maka Allah memberi petunjuk orang-orang yang beriman kepada kebenaran tentang hal yang mereka perselisihkann itu dengan kehendak-Nya. Dan Allah selalu memberi petunjuk orang yang dikehendaki-Nya kepada jalan yang lurus.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 214, "text": "أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُوا۟ ٱلۡجَنَّةَ وَلَمَّا یَأۡتِكُم مَّثَلُ ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَاۤءُ وَٱلضَّرَّاۤءُ وَزُلۡزِلُوا۟ حَتَّىٰ یَقُولَ ٱلرَّسُولُ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَاۤ إِنَّ نَصۡرَ ٱللَّهِ قَرِیبࣱ ۝٢١٤", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "بل أظننتم -أيها المؤمنون- أن تدخلوا الجنة، ولمَّا يصبكم من الابتلاء مثل ما أصاب المؤمنين الذين مضوا من قبلكم: من الفقر والأمراض والخوف والرعب، وزُلزلوا بأنواع المخاوف، حتى قال رسولهم والمؤمنون معه -على سبيل الاستعجال للنصر من الله تعالى-: متى نصر الله؟ ألا إن نصر الله قريب من المؤمنين.", "isBasmala": false, "translation_en": "Or do you expect to enter Paradise before the example of those who came before you had reached you? Adversity and hardship had afflicted them, and they were so shaken up, that the Messenger and those who believed with him said, \"When is God's victory?\" Indeed, God's victory is near.", "translation_id": "Apakah kamu mengira bahwa kamu akan masuk surga, padahal belum datang kepadamu (cobaan) sebagaimana halnya orang-orang terdahulu sebelum kamu? Mereka ditimpa oleh malapetaka dan kesengsaraan, serta digoncangkan (dengan bermacam-macam cobaan) sehingga berkatalah Rasul dan orang-orang yang beriman bersamanya: \"Bilakah datangnya pertolongan Allah?\" Ingatlah, sesungguhnya pertolongan Allah itu amat dekat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 215, "text": "یَسۡـَٔلُونَكَ مَاذَا یُنفِقُونَۖ قُلۡ مَاۤ أَنفَقۡتُم مِّنۡ خَیۡرࣲ فَلِلۡوَ ٰلِدَیۡنِ وَٱلۡأَقۡرَبِینَ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَٱبۡنِ ٱلسَّبِیلِۗ وَمَا تَفۡعَلُوا۟ مِنۡ خَیۡرࣲ فَإِنَّ ٱللَّهَ بِهِۦ عَلِیمࣱ ۝٢١٥", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "يسألك أصحابك -أيها النبي- أي شيء ينفقون من أصناف أموالهم تقربًا إلى الله تعالى، وعلى مَن ينفقون؟ قل لهم: أنفقوا أيَّ خير يتيسر لكم من أصناف المال الحلال الطيب، واجعلوا نفقتكم للوالدين، والأقربين من أهلكم وذوي أرحامكم، واليتامى، والفقراء، والمسافر المحتاج الذي بَعُدَ عن أهله وماله. وما تفعلوا من خير فإن الله تعالى به عليم.", "isBasmala": false, "translation_en": "They ask you what they should give. Say, \"Whatever charity you give is for the parents, and the relatives, and the orphans, and the poor, and the wayfarer. Whatever good you do, God is aware of it.", "translation_id": "Mereka bertanya tentang apa yang mereka nafkahkan. Jawablah: \"Apa saja harta yang kamu nafkahkan hendaklah diberikan kepada ibu-bapak, kaum kerabat, anak-anak yatim, orang-orang miskin dan orang-orang yang sedang dalam perjalanan\". Dan apa saja kebaikan yang kamu buat, maka sesungguhnya Allah Maha Mengetahuinya.", "manzil": 1, "manzil_display": ""}], "34": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 216, "text": "كُتِبَ عَلَیۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهࣱ لَّكُمۡۖ وَعَسَىٰۤ أَن تَكۡرَهُوا۟ شَیۡـࣰٔا وَهُوَ خَیۡرࣱ لَّكُمۡۖ وَعَسَىٰۤ أَن تُحِبُّوا۟ شَیۡـࣰٔا وَهُوَ شَرࣱّ لَّكُمۡۗ وَٱللَّهُ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ۝٢١٦", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "فرض الله عليكم -أيها المؤمنون- قتال الكفار، والقتال مكروه لكم من جهة الطبع؛ لمشقته وكثرة مخاطره، وقد تكرهون شيئًا وهو في حقيقته خير لكم، وقد تحبون شيئًا لما فيه من الراحة أو اللذة العاجلة، وهو شر لكم. والله تعالى يعلم ما هو خير لكم، وأنتم لا تعلمون ذلك. فبادروا إلى الجهاد في سبيله.", "isBasmala": false, "translation_en": "Fighting is ordained for you, even though you dislike it. But it may be that you dislike something while it is good for you, and it may be that you like something while it is bad for you. God knows, and you do not know.", "translation_id": "Diwajibkan atas kamu berperang, padahal berperang itu adalah sesuatu yang kamu benci. Boleh jadi kamu membenci sesuatu, padahal ia amat baik bagimu, dan boleh jadi (pula) kamu menyukai sesuatu, padahal ia amat buruk bagimu; Allah mengetahui, sedang kamu tidak mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 217, "text": "یَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالࣲ فِیهِۖ قُلۡ قِتَالࣱ فِیهِ كَبِیرࣱۚ وَصَدٌّ عَن سَبِیلِ ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا یَزَالُونَ یُقَـٰتِلُونَكُمۡ حَتَّىٰ یَرُدُّوكُمۡ عَن دِینِكُمۡ إِنِ ٱسۡتَطَـٰعُوا۟ۚ وَمَن یَرۡتَدِدۡ مِنكُمۡ عَن دِینِهِۦ فَیَمُتۡ وَهُوَ كَافِرࣱ فَأُو۟لَـٰۤىِٕكَ حَبِطَتۡ أَعۡمَـٰلُهُمۡ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۖ وَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٢١٧", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "يسألك المشركون -أيها الرسول- عن الشهر الحرام: هل يحل فيه القتال؟ قل لهم: القتال في الشهر الحرام عظيم عند الله استحلاله وسفك الدماء فيه، ومَنْعكم الناس من دخول الإسلام بالتعذيب والتخويف، وجحودكم بالله وبرسوله وبدينه، ومَنْع المسلمين من دخول المسجد الحرام، وإخراج النبي والمهاجرين منه وهم أهله وأولياؤه، ذلك أكبر ذنبًا، وأعظم جرمًا عند الله من القتال في الشهر الحرام. والشرك الذي أنتم فيه أكبر وأشد من القتل في الشهر الحرام. وهؤلاء الكفار لم يرتدعوا عن جرائمهم، بل هم مستمرون عليها، ولا يزالون يقاتلونكم حتى يردوكم عن الإسلام إلى الكفر إن استطاعوا تحقيق ذلك. ومن أطاعهم منكم -أيها المسلمون- وارتدَّ عن دينه فمات على الكفر، فقد ذهب عمله في الدنيا والآخرة، وصار من الملازمين لنار جهنم لا يخرج منها أبدًا.", "isBasmala": false, "translation_en": "They ask you about fighting during the Holy Month. Say, \"Fighting during it is deplorable; but to bar others from God's path, and to disbelieve in Him, and to prevent access to the Holy Mosque, and to expel its people from it, are more deplorable with God. And persecution is more serious than killing. They will not cease to fight you until they turn you back from your religion, if they can. Whoever among you turns back from his religion, and dies a disbeliever-those are they whose works will come to nothing, in this life, and in the Hereafter. Those are the inmates of the Fire, abiding in it forever.", "translation_id": "Mereka bertanya kepadamu tentang berperang pada bulan Haram. Katakanlah: \"Berperang dalam bulan itu adalah dosa besar; tetapi menghalangi (manusia) dari jalan Allah, kafir kepada Allah, (menghalangi masuk) Masjidilharam dan mengusir penduduknya dari sekitarnya, lebih besar (dosanya) di sisi Allah. Dan berbuat fitnah lebih besar (dosanya) daripada membunuh. Mereka tidak henti-hentinya memerangi kamu sampai mereka (dapat) mengembalikan kamu dari agamamu (kepada kekafiran), seandainya mereka sanggup. Barangsiapa yang murtad di antara kamu dari agamanya, lalu dia mati dalam kekafiran, maka mereka itulah yang sia-sia amalannya di dunia dan di akhirat, dan mereka itulah penghuni neraka, mereka kekal di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 218, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَٱلَّذِینَ هَاجَرُوا۟ وَجَـٰهَدُوا۟ فِی سَبِیلِ ٱللَّهِ أُو۟لَـٰۤىِٕكَ یَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٢١٨", "juz": 2, "hizb": "(* ح 4*)", "tafsir": "إن الذين صَدَّقوا بالله ورسوله وعملوا بشرعه والذين تركوا ديارهم، وجاهدوا في سبيل الله، أولئك يطمعون في فضل الله وثوابه. والله غفور لذنوب عباده المؤمنين، رحيم بهم رحمة واسعة.", "isBasmala": false, "translation_en": "Those who believed, and those who migrated and fought for the sake of God-those look forward to God's mercy. God is Forgiving and Merciful.", "translation_id": "Sesungguhnya orang-orang yang beriman, orang-orang yang berhijrah dan berjihad di jalan Allah, mereka itu mengharapkan rahmat Allah, dan Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 219, "text": "۞ یَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَیۡسِرِۖ قُلۡ فِیهِمَاۤ إِثۡمࣱ كَبِیرࣱ وَمَنَـٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَاۤ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَیَسۡـَٔلُونَكَ مَاذَا یُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَ ٰلِكَ یُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ ۝٢١٩", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "يسألك المسلمون -أيها النبي- عن حكم تعاطي الخمر شربًا وبيعًا وشراءً، والخمر كل مسكر خامر العقل وغطاه مشروبًا كان أو مأكولا ويسألونك عن حكم القمار -وهو أَخْذُ المال أو إعطاؤه بالمقامرة وهي المغالبات التي فيها عوض من الطرفين-، قل لهم: في ذلك أضرار ومفاسد كثيرة في الدين والدنيا، والعقول والأموال، وفيهما منافع للناس من جهة كسب الأموال وغيرها، وإثمهما أكبر من نفعهما؛ إذ يصدَّان عن ذكر الله وعن الصلاة، ويوقعان العداوة والبغضاء بين الناس، ويتلفان المال. وكان هذا تمهيدًا لتحريمهما. ويسألونك عن القَدْر الذي ينفقونه من أموالهم تبرعًا وصدقة، قل لهم: أنفقوا القَدْر الذي يزيد على حاجتكم. مثل ذلك البيان الواضح يبيِّن الله لكم الآيات وأحكام الشريعة؛ لكي تتفكروا فيما ينفعكم في الدنيا والآخرة. ويسألونك -أيها النبي- عن اليتامى كيف يتصرفون معهم في معاشهم وأموالهم؟ قل لهم: إصلاحكم لهم خير، فافعلوا الأنفع لهم دائمًا، وإن تخالطوهم في سائر شؤون المعاش فهم إخوانكم في الدين. وعلى الأخ أن يرعى مصلحة أخيه. والله يعلم المضيع لأموال اليتامى من الحريص على إصلاحها. ولو شاء الله لضيَّق وشقَّ عليكم بتحريم المخالطة. إن الله عزيز في ملكه، حكيم في خلقه وتدبيره وتشريعه.", "isBasmala": false, "translation_en": "They ask you about intoxicants and gambling. Say, \"There is gross sin in them, and some benefits for people, but their sinfulness outweighs their benefit.\" And they ask you about what they should give: say, \"The surplus.\" Thus God explains the revelations to you, so that you may think.", "translation_id": "Mereka bertanya kepadamu tentang khamar dan judi. Katakanlah: \"Pada keduanya terdapat dosa yang besar dan beberapa manfaat bagi manusia, tetapi dosa keduanya lebih besar dari manfaatnya\". Dan mereka bertanya kepadamu apa yang mereka nafkahkan. Katakanlah: \"Yang lebih dari keperluan\". Demikianlah Allah menerangkan ayat-ayat-Nya kepadamu supaya kamu berfikir,", "manzil": 1, "manzil_display": ""}], "35": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 220, "text": "فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۗ وَیَسۡـَٔلُونَكَ عَنِ ٱلۡیَتَـٰمَىٰۖ قُلۡ إِصۡلَاحࣱ لَّهُمۡ خَیۡرࣱۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَ ٰنُكُمۡۚ وَٱللَّهُ یَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ ۝٢٢٠", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "يسألك المسلمون -أيها النبي- عن حكم تعاطي الخمر شربًا وبيعًا وشراءً، والخمر كل مسكر خامر العقل وغطاه مشروبًا كان أو مأكولا ويسألونك عن حكم القمار -وهو أَخْذُ المال أو إعطاؤه بالمقامرة وهي المغالبات التي فيها عوض من الطرفين-، قل لهم: في ذلك أضرار ومفاسد كثيرة في الدين والدنيا، والعقول والأموال، وفيهما منافع للناس من جهة كسب الأموال وغيرها، وإثمهما أكبر من نفعهما؛ إذ يصدَّان عن ذكر الله وعن الصلاة، ويوقعان العداوة والبغضاء بين الناس، ويتلفان المال. وكان هذا تمهيدًا لتحريمهما. ويسألونك عن القَدْر الذي ينفقونه من أموالهم تبرعًا وصدقة، قل لهم: أنفقوا القَدْر الذي يزيد على حاجتكم. مثل ذلك البيان الواضح يبيِّن الله لكم الآيات وأحكام الشريعة؛ لكي تتفكروا فيما ينفعكم في الدنيا والآخرة. ويسألونك -أيها النبي- عن اليتامى كيف يتصرفون معهم في معاشهم وأموالهم؟ قل لهم: إصلاحكم لهم خير، فافعلوا الأنفع لهم دائمًا، وإن تخالطوهم في سائر شؤون المعاش فهم إخوانكم في الدين. وعلى الأخ أن يرعى مصلحة أخيه. والله يعلم المضيع لأموال اليتامى من الحريص على إصلاحها. ولو شاء الله لضيَّق وشقَّ عليكم بتحريم المخالطة. إن الله عزيز في ملكه، حكيم في خلقه وتدبيره وتشريعه.", "isBasmala": false, "translation_en": "About this world and the next. And they ask you about orphans. Say, \"Improvement for them is best. And if you intermix with them, then they are your brethren.\" God knows the dishonest from the honest. Had God willed, He could have overburdened you. God is Mighty and Wise.", "translation_id": "tentang dunia dan akhirat. Dan mereka bertanya kepadamu tentang anak yatim, katakalah: \"Mengurus urusan mereka secara patut adalah baik, dan jika kamu bergaul dengan mereka, maka mereka adalah saudaramu; dan Allah mengetahui siapa yang membuat kerusakan dari yang mengadakan perbaikan. Dan jikalau Allah menghendaki, niscaya Dia dapat mendatangkan kesulitan kepadamu. Sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 221, "text": "وَلَا تَنكِحُوا۟ ٱلۡمُشۡرِكَـٰتِ حَتَّىٰ یُؤۡمِنَّۚ وَلَأَمَةࣱ مُّؤۡمِنَةٌ خَیۡرࣱ مِّن مُّشۡرِكَةࣲ وَلَوۡ أَعۡجَبَتۡكُمۡۗ وَلَا تُنكِحُوا۟ ٱلۡمُشۡرِكِینَ حَتَّىٰ یُؤۡمِنُوا۟ۚ وَلَعَبۡدࣱ مُّؤۡمِنٌ خَیۡرࣱ مِّن مُّشۡرِكࣲ وَلَوۡ أَعۡجَبَكُمۡۗ أُو۟لَـٰۤىِٕكَ یَدۡعُونَ إِلَى ٱلنَّارِۖ وَٱللَّهُ یَدۡعُوۤا۟ إِلَى ٱلۡجَنَّةِ وَٱلۡمَغۡفِرَةِ بِإِذۡنِهِۦۖ وَیُبَیِّنُ ءَایَـٰتِهِۦ لِلنَّاسِ لَعَلَّهُمۡ یَتَذَكَّرُونَ ۝٢٢١", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "ولا تتزوجوا -أيها المسلمون- المشركات عابدات الأوثان، حتى يدخلن في الإسلام. واعلموا أن امرأة مملوكة لا مال لها ولا حسب، مؤمنةً بالله، خير من امرأة مشركة، وإن أعجبتكم المشركة الحرة. ولا تُزَوِّجوا نساءكم المؤمنات -إماء أو حرائر- للمشركين حتى يؤمنوا بالله ورسوله. واعلموا أن عبدًا مؤمنًا مع فقره، خير من مشرك، وإن أعجبكم المشرك. أولئك المتصفون بالشرك رجالا ونساءً يدعون كل مَن يعاشرهم إلى ما يؤدي به إلى النار، والله سبحانه يدعو عباده إلى دينه الحق المؤدي بهم إلى الجنة ومغفرة ذنوبهم بإذنه، ويبين آياته وأحكامه للناس؛ لكي يتذكروا، فيعتبروا.", "isBasmala": false, "translation_en": "Do not marry idolatresses, unless they have believed. A believing maid is better than an idolatress, even if you like her. And do not marry idolaters, unless they have believed. A believing servant is better than an idolater, even if you like him. These call to the Fire, but God calls to the Garden and to forgiveness, by His leave. He makes clear His communications to the people, that they may be mindful.", "translation_id": "Dan janganlah kamu menikahi wanita-wanita musyrik, sebelum mereka beriman. Sesungguhnya wanita budak yang mukmin lebih baik dari wanita musyrik, walaupun dia menarik hatimu. Dan janganlah kamu menikahkan orang-orang musyrik (dengan wanita-wanita mukmin) sebelum mereka beriman. Sesungguhnya budak yang mukmin lebih baik dari orang musyrik, walaupun dia menarik hatimu. Mereka mengajak ke neraka, sedang Allah mengajak ke surga dan ampunan dengan izin-Nya. Dan Allah menerangkan ayat-ayat-Nya (perintah-perintah-Nya) kepada manusia supaya mereka mengambil pelajaran.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 222, "text": "وَیَسۡـَٔلُونَكَ عَنِ ٱلۡمَحِیضِۖ قُلۡ هُوَ أَذࣰى فَٱعۡتَزِلُوا۟ ٱلنِّسَاۤءَ فِی ٱلۡمَحِیضِ وَلَا تَقۡرَبُوهُنَّ حَتَّىٰ یَطۡهُرۡنَۖ فَإِذَا تَطَهَّرۡنَ فَأۡتُوهُنَّ مِنۡ حَیۡثُ أَمَرَكُمُ ٱللَّهُۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلتَّوَّ ٰبِینَ وَیُحِبُّ ٱلۡمُتَطَهِّرِینَ ۝٢٢٢", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "ويسألونك عن الحيض- وهو الدم الذي يسيل من أرحام النساء جِبِلَّة في أوقات مخصوصة-، قل لهم -أيها النبي-: هو أذى مستقذر يضر من يَقْرَبُه، فاجتنبوا جماع النساء مدة الحيض حتى ينقطع الدم، فإذا انقطع الدم، واغتسلن، فجامعوهن في الموضع الذي أحلَّه الله لكم، وهو القبل لا الدبر. إن الله يحب عباده المكثرين من الاستغفار والتوبة، ويحب عباده المتطهرين الذين يبتعدون عن الفواحش والأقذار.", "isBasmala": false, "translation_en": "And they ask you about menstruation: say, \"It is harmful, so keep away from women during menstruation. And do not approach them until they have become pure. Once they have become pure, approach them in the way God has directed you.\" God loves the repentant, and He loves those who keep clean.\"", "translation_id": "Mereka bertanya kepadamu tentang haidh. Katakanlah: \"Haidh itu adalah suatu kotoran\". Oleh sebab itu hendaklah kamu menjauhkan diri dari wanita di waktu haidh; dan janganlah kamu mendekati mereka, sebelum mereka suci. Apabila mereka telah suci, maka campurilah mereka itu di tempat yang diperintahkan Allah kepadamu. Sesungguhnya Allah menyukai orang-orang yang bertaubat dan menyukai orang-orang yang mensucikan diri.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 223, "text": "نِسَاۤؤُكُمۡ حَرۡثࣱ لَّكُمۡ فَأۡتُوا۟ حَرۡثَكُمۡ أَنَّىٰ شِئۡتُمۡۖ وَقَدِّمُوا۟ لِأَنفُسِكُمۡۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّكُم مُّلَـٰقُوهُۗ وَبَشِّرِ ٱلۡمُؤۡمِنِینَ ۝٢٢٣", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "نساؤكم موضع زرع لكم، تضعون النطفة في أرحامهن، فَيَخْرج منها الأولاد بمشيئة الله، فجامعوهن في محل الجماع فقط، وهو القبل بأي كيفية شئتم، وقَدِّموا لأنفسكم أعمالا صالحة بمراعاة أوامر الله، وخافوا الله، واعلموا أنكم ملاقوه للحساب يوم القيامة. وبشِّر المؤمنين -أيها النبي- بما يفرحهم ويسرُّهم من حسن الجزاء في الآخرة.", "isBasmala": false, "translation_en": "Your women are cultivation for you; so approach your cultivation whenever you like, and send ahead for yourselves. And fear God, and know that you will meet Him. And give good news to the believers.", "translation_id": "Isteri-isterimu adalah (seperti) tanah tempat kamu bercocok tanam, maka datangilah tanah tempat bercocok-tanammu itu bagaimana saja kamu kehendaki. Dan kerjakanlah (amal yang baik) untuk dirimu, dan bertakwalah kepada Allah dan ketahuilah bahwa kamu kelak akan menemui-Nya. Dan berilah kabar gembira orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 224, "text": "وَلَا تَجۡعَلُوا۟ ٱللَّهَ عُرۡضَةࣰ لِّأَیۡمَـٰنِكُمۡ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصۡلِحُوا۟ بَیۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِیعٌ عَلِیمࣱ ۝٢٢٤", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "ولا تجعلوا -أيها المسلمون- حلفكم بالله مانعًا لكم من البر وصلة الرحم والتقوى والإصلاح بين الناس: بأن تُدْعَوا إلى فعل شيء منها، فتحتجوا بأنكم أقسمتم بالله ألا تفعلوه، بل على الحالف أن يعدل عن حلفه، ويفعل أعمال البر، ويكفر عن يمينه، ولا يعتاد ذلك. والله سميع لأقوالكم، عليم بجميع أحوالكم.", "isBasmala": false, "translation_en": "And do not allow your oaths in God's name to hinder you from virtue, and righteousness, and making peace between people. God is Listener and Knower.", "translation_id": "Jangahlah kamu jadikan (nama) Allah dalam sumpahmu sebagai penghalang untuk berbuat kebajikan, bertakwa dan mengadakan ishlah di antara manusia. Dan Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}], "36": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 225, "text": "لَّا یُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِیۤ أَیۡمَـٰنِكُمۡ وَلَـٰكِن یُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِیمࣱ ۝٢٢٥", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "لا يعاقبكم الله بسبب أيمانكم التي تحلفونها بغير قصد، ولكن يعاقبكم بما قصدَتْه قلوبكم. والله غفور لمن تاب إليه، حليم بمن عصاه حيث لم يعاجله بالعقوبة.", "isBasmala": false, "translation_en": "God does not hold you responsible for your unintentional oaths, but He holds you responsible for your intentions. God is Forgiving and Forbearing.", "translation_id": "Allah tidak menghukum kamu disebabkan sumpahmu yang tidak dimaksud (untuk bersumpah), tetapi Allah menghukum kamu disebabkan (sumpahmu) yang disengaja (untuk bersumpah) oleh hatimu. Dan Allah Maha Pengampun lagi Maha Penyantun.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 226, "text": "لِّلَّذِینَ یُؤۡلُونَ مِن نِّسَاۤىِٕهِمۡ تَرَبُّصُ أَرۡبَعَةِ أَشۡهُرࣲۖ فَإِن فَاۤءُو فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝٢٢٦", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "للذين يحلفون بالله أن لا يجامعوا نساءهم، انتظار أربعة أشهر، فإن رجعوا قبل فوات الأشهر الأربعة، فإن الله غفور لما وقع منهم من الحلف بسبب رجوعهم، رحيم بهم.", "isBasmala": false, "translation_en": "Those who vow abstinence from their wives must wait for four months. But if they reconcile-God is Forgiving and Merciful.", "translation_id": "Kepada orang-orang yang meng-ilaa' isterinya diberi tangguh empat bulan (lamanya). Kemudian jika mereka kembali (kepada isterinya), maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 227, "text": "وَإِنۡ عَزَمُوا۟ ٱلطَّلَـٰقَ فَإِنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ ۝٢٢٧", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "وإن عقدوا عزمهم على الطلاق، باستمرارهم في اليمين، وترك الجماع، فإن الله سميع لأقوالهم، عليم بمقاصدهم، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "And if they resolve to divorce-God is Hearing and Knowing.", "translation_id": "Dan jika mereka berazam (bertetap hati untuk) talak, maka sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 228, "text": "وَٱلۡمُطَلَّقَـٰتُ یَتَرَبَّصۡنَ بِأَنفُسِهِنَّ ثَلَـٰثَةَ قُرُوۤءࣲۚ وَلَا یَحِلُّ لَهُنَّ أَن یَكۡتُمۡنَ مَا خَلَقَ ٱللَّهُ فِیۤ أَرۡحَامِهِنَّ إِن كُنَّ یُؤۡمِنَّ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِی ذَ ٰلِكَ إِنۡ أَرَادُوۤا۟ إِصۡلَـٰحࣰاۚ وَلَهُنَّ مِثۡلُ ٱلَّذِی عَلَیۡهِنَّ بِٱلۡمَعۡرُوفِۚ وَلِلرِّجَالِ عَلَیۡهِنَّ دَرَجَةࣱۗ وَٱللَّهُ عَزِیزٌ حَكِیمٌ ۝٢٢٨", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "والمطلقات ذوات الحيض، يجب أن ينتظرن دون نكاح بعد الطلاق مدة ثلاثة أطهار أو ثلاث حيضات على سبيل العدة؛ ليتأكدن من فراغ الرحم من الحمل. ولا يجوز لهن تزوج رجل آخر في أثناء هذه العدة حتى تنتهي. ولا يحل لهن أن يخفين ما خلق الله في أرحامهن من الحمل أو الحيض، إن كانت المطلقات مؤمنات حقًا بالله واليوم الآخر. وأزواج المطلقات أحق بمراجعتهن في العدة. وينبغي أن يكون ذلك بقصد الإصلاح والخير، وليس بقصد الإضرار تعذيبًا لهن بتطويل العدة. وللنساء حقوق على الأزواج، مثل التي عليهن، على الوجه المعروف، وللرجال على النساء منزلة زائدة من حسن الصحبة والعشرة بالمعروف والقِوامة على البيت وملك الطلاق. والله عزيز له العزة القاهرة، حكيم يضع كل شيء في موضعه المناسب.", "isBasmala": false, "translation_en": "Divorced women shall wait by themselves for three periods. And it is not lawful for them to conceal what God has created in their wombs, if they believe in God and the Last Day. Meanwhile, their husbands have the better right to take them back, if they desire reconciliation. And women have rights similar to their obligations, according to what is fair. But men have a degree over them. God is Mighty and Wise.", "translation_id": "Wanita-wanita yang ditalak handaklah menahan diri (menunggu) tiga kali quru'. Tidak boleh mereka menyembunyikan apa yang diciptakan Allah dalam rahimnya, jika mereka beriman kepada Allah dan hari akhirat. Dan suami-suaminya berhak merujukinya dalam masa menanti itu, jika mereka (para suami) menghendaki ishlah. Dan para wanita mempunyai hak yang seimbang dengan kewajibannya menurut cara yang ma'ruf. Akan tetapi para suami, mempunyai satu tingkatan kelebihan daripada isterinya. Dan Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 229, "text": "ٱلطَّلَـٰقُ مَرَّتَانِۖ فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِیحُۢ بِإِحۡسَـٰنࣲۗ وَلَا یَحِلُّ لَكُمۡ أَن تَأۡخُذُوا۟ مِمَّاۤ ءَاتَیۡتُمُوهُنَّ شَیۡـًٔا إِلَّاۤ أَن یَخَافَاۤ أَلَّا یُقِیمَا حُدُودَ ٱللَّهِۖ فَإِنۡ خِفۡتُمۡ أَلَّا یُقِیمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَیۡهِمَا فِیمَا ٱفۡتَدَتۡ بِهِۦۗ تِلۡكَ حُدُودُ ٱللَّهِ فَلَا تَعۡتَدُوهَاۚ وَمَن یَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ ۝٢٢٩", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "الطلاق الذي تحصل به الرجعة مرتان، واحدة بعد الأخرى، فحكم الله بعد كل طلقة هو إمساك المرأة بالمعروف، وحسن العشرة بعد مراجعتها، أو تخلية سبيلها مع حسن معاملتها بأداء حقوقها، وألا يذكرها مطلقها بسوء. ولا يحل لكم- أيها الأزواج- أن تأخذوا شيئًا مما أعطيتموهن من المهر ونحوه، إلا أن يخاف الزوجان ألا يقوما بالحقوق الزوجية، فحينئذ يعرضان أمرهما على الأولياء، فإن خاف الأولياء عدم إقامة الزوجين حدود الله، فلا حرج على الزوجين فيما تدفعه المرأة للزوج مقابل طلاقها. تلك الأحكام هي حدود الله الفاصلة بين الحلال والحرام، فلا تتجاوزوها، ومن يتجاوز حدود الله تعالى فأولئك هم الظالمون أنفسهم بتعريضها لعذاب الله.", "isBasmala": false, "translation_en": "Divorce is allowed twice. Then, either honorable retention, or setting free kindly. It is not lawful for you to take back anything you have given them, unless they fear that they cannot maintain God's limits. If you fear that they cannot maintain God's limits, then there is no blame on them if she sacrifices something for her release. These are God's limits, so do not transgress them. Those who transgress God's limits are the unjust.", "translation_id": "Talak (yang dapat dirujuki) dua kali. Setelah itu boleh rujuk lagi dengan cara yang ma'ruf atau menceraikan dengan cara yang baik. Tidak halal bagi kamu mengambil kembali sesuatu dari yang telah kamu berikan kepada mereka, kecuali kalau keduanya khawatir tidak akan dapat menjalankan hukum-hukum Allah. Jika kamu khawatir bahwa keduanya (suami isteri) tidak dapat menjalankan hukum-hukum Allah, maka tidak ada dosa atas keduanya tentang bayaran yang diberikan oleh isteri untuk menebus dirinya. Itulah hukum-hukum Allah, maka janganlah kamu melanggarnya. Barangsiapa yang melanggar hukum-hukum Allah mereka itulah orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 230, "text": "فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعۡدُ حَتَّىٰ تَنكِحَ زَوۡجًا غَیۡرَهُۥۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَیۡهِمَاۤ أَن یَتَرَاجَعَاۤ إِن ظَنَّاۤ أَن یُقِیمَا حُدُودَ ٱللَّهِۗ وَتِلۡكَ حُدُودُ ٱللَّهِ یُبَیِّنُهَا لِقَوۡمࣲ یَعۡلَمُونَ ۝٢٣٠", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "فإن طلَّق الرجل زوجته الطلقة الثالثة، فلا تحلُّ له إلا إذا تزوجت رجلا غيره زواجًا صحيحًا وجامعها فيه ويكون الزواج عن رغبة، لا بنية تحليل المرأة لزوجها الأول، فإن طلقها الزوج الآخر أو مات عنها وانقضت عدتها، فلا إثم على المرأة وزوجها الأول أن يتزوجا بعقد جديد، ومهر جديد، إن غلب على ظنهما أن يقيما أحكام الله التي شرعها للزوجين. وتلك أحكام الله المحددة يبينها لقوم يعلمون أحكامه وحدوده؛ لأنهم المنتفعون بها.", "isBasmala": false, "translation_en": "If he divorces her, she shall not be lawful for him again until she has married another husband. If the latter divorces her, then there is no blame on them for reuniting, provided they think they can maintain God's limits. These are God's limits; He makes them clear to people who know.", "translation_id": "Kemudian jika si suami mentalaknya (sesudah talak yang kedua), maka perempuan itu tidak lagi halal baginya hingga dia kawin dengan suami yang lain. Kemudian jika suami yang lain itu menceraikannya, maka tidak ada dosa bagi keduanya (bekas suami pertama dan isteri) untuk kawin kembali jika keduanya berpendapat akan dapat menjalankan hukum-hukum Allah. Itulah hukum-hukum Allah, diterangkan-Nya kepada kaum yang (mau) mengetahui.", "manzil": 1, "manzil_display": ""}], "37": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 231, "text": "وَإِذَا طَلَّقۡتُمُ ٱلنِّسَاۤءَ فَبَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ سَرِّحُوهُنَّ بِمَعۡرُوفࣲۚ وَلَا تُمۡسِكُوهُنَّ ضِرَارࣰا لِّتَعۡتَدُوا۟ۚ وَمَن یَفۡعَلۡ ذَ ٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ وَلَا تَتَّخِذُوۤا۟ ءَایَـٰتِ ٱللَّهِ هُزُوࣰاۚ وَٱذۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ عَلَیۡكُمۡ وَمَاۤ أَنزَلَ عَلَیۡكُم مِّنَ ٱلۡكِتَـٰبِ وَٱلۡحِكۡمَةِ یَعِظُكُم بِهِۦۚ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمࣱ ۝٢٣١", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "وإذا طَلَّقتم النساء فقاربن انتهاء عدتهن، فراجعوهن، ونيتكم القيام بحقوقهن على الوجه المستحسن شرعًا وعرفًا، أو اتركوهن حتى تنقضي عدتهن. واحذروا أن تكون مراجعتهن بقصد الإضرار بهن لأجل الاعتداء على حقوقهن. ومن يفعل ذلك فقد ظلم نفسه باستحقاقه العقوبة، ولا تتخذوا آيات الله وأحكامه لعبًا ولهوًا. واذكروا نعمة الله عليكم بالإسلام وتفصيل الأحكام. واذكروا ما أنزل الله عليكم من القرآن والسنة، واشكروا له سبحانه على هذه النعم الجليلة، يُذكِّركم الله بهذا، ويخوفكم من المخالفة، فخافوا الله وراقبوه، واعلموا أن الله عليم بكل شيء، لا يخفى عليه شيء، وسيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "When you divorce women, and they have reached their term, either retain them amicably, or release them amicably. But do not retain them to hurt them and commit aggression. Whoever does that has wronged himself. And do not take God's revelations for a joke. And remember God's favor to you, and that He revealed to you the Scripture and Wisdom to teach you. And fear God, and know that God is aware of everything.", "translation_id": "Apabila kamu mentalak isteri-isterimu, lalu mereka mendekati akhir iddahnya, maka rujukilah mereka dengan cara yang ma'ruf, atau ceraikanlah mereka dengan cara yang ma'ruf (pula). Janganlah kamu rujuki mereka untuk memberi kemudharatan, karena dengan demikian kamu menganiaya mereka. Barangsiapa berbuat demikian, maka sungguh ia telah berbuat zalim terhadap dirinya sendiri. Janganlah kamu jadikan hukum-hukum Allah permainan, dan ingatlah nikmat Allah padamu, dan apa yang telah diturunkan Allah kepadamu yaitu Al Kitab dan Al Hikmah (As Sunnah). Allah memberi pengajaran kepadamu dengan apa yang diturunkan-Nya itu. Dan bertakwalah kepada Allah serta ketahuilah bahwasanya Allah Maha Mengetahui segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 232, "text": "وَإِذَا طَلَّقۡتُمُ ٱلنِّسَاۤءَ فَبَلَغۡنَ أَجَلَهُنَّ فَلَا تَعۡضُلُوهُنَّ أَن یَنكِحۡنَ أَزۡوَ ٰجَهُنَّ إِذَا تَرَ ٰضَوۡا۟ بَیۡنَهُم بِٱلۡمَعۡرُوفِۗ ذَ ٰلِكَ یُوعَظُ بِهِۦ مَن كَانَ مِنكُمۡ یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۗ ذَ ٰلِكُمۡ أَزۡكَىٰ لَكُمۡ وَأَطۡهَرُۚ وَٱللَّهُ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ۝٢٣٢", "juz": 2, "hizb": "(*¼ ح 4*)", "tafsir": "واذا طلَّقتم نساءكم دون الثلاث وانتهت عدتهن من غير مراجعة لهن، فلا تضيقوا -أيها الأولياء- على المطلقات بمنعهن من العودة إلى أزواجهن بعقد جديد إذا أردن ذلك، وحدث التراضي شرعًا وعرفًا. ذلك يوعظ به من كان منكم صادق الإيمان بالله واليوم الآخر. إن تَرْكَ العضل وتمكين الأزواج من نكاح زوجاتهم أكثر نماء وطهارة لأعراضكم، وأعظم منفعة وثوابًا لكم. والله يعلم ما فيه صلاحكم وأنتم لا تعلمون ذلك.", "isBasmala": false, "translation_en": "When you divorce women, and they have reached their term, do not prevent them from marrying their husbands, provided they agree on fair terms. Thereby is advised whoever among you believes in God and the Last Day. That is better and more decent for you. God knows, and you do not know.", "translation_id": "Apabila kamu mentalak isteri-isterimu, lalu habis masa iddahnya, maka janganlah kamu (para wali) menghalangi mereka kawin lagi dengan bakal suaminya, apabila telah terdapat kerelaan di antara mereka dengan cara yang ma'ruf. Itulah yang dinasehatkan kepada orang-orang yang beriman di antara kamu kepada Allah dan hari kemudian. Itu lebih baik bagimu dan lebih suci. Allah mengetahui, sedang kamu tidak mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 233, "text": "۞ وَٱلۡوَ ٰلِدَ ٰتُ یُرۡضِعۡنَ أَوۡلَـٰدَهُنَّ حَوۡلَیۡنِ كَامِلَیۡنِۖ لِمَنۡ أَرَادَ أَن یُتِمَّ ٱلرَّضَاعَةَۚ وَعَلَى ٱلۡمَوۡلُودِ لَهُۥ رِزۡقُهُنَّ وَكِسۡوَتُهُنَّ بِٱلۡمَعۡرُوفِۚ لَا تُكَلَّفُ نَفۡسٌ إِلَّا وُسۡعَهَاۚ لَا تُضَاۤرَّ وَ ٰلِدَةُۢ بِوَلَدِهَا وَلَا مَوۡلُودࣱ لَّهُۥ بِوَلَدِهِۦۚ وَعَلَى ٱلۡوَارِثِ مِثۡلُ ذَ ٰلِكَۗ فَإِنۡ أَرَادَا فِصَالًا عَن تَرَاضࣲ مِّنۡهُمَا وَتَشَاوُرࣲ فَلَا جُنَاحَ عَلَیۡهِمَاۗ وَإِنۡ أَرَدتُّمۡ أَن تَسۡتَرۡضِعُوۤا۟ أَوۡلَـٰدَكُمۡ فَلَا جُنَاحَ عَلَیۡكُمۡ إِذَا سَلَّمۡتُم مَّاۤ ءَاتَیۡتُم بِٱلۡمَعۡرُوفِۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِیرࣱ ۝٢٣٣", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "وعلى الوالدات إرضاع أولادهن مدة سنتين كاملتين لمن أراد إتمام الرضاعة، ويجب على الآباء أن يكفُلوا للمرضعات المطلقات طعامهن وكسوتهن، على الوجه المستحسن شرعًا وعرفًا؛ لأن الله لا يكلف نفسًا إلا قدر طاقتها، ولا يحل للوالدين أن يجعلوا المولود وسيلة للمضارة بينهما، ويجب على الوارث عند موت الوالد مثل ما يجب على الوالد قبل موته من النفقة والكسوة. فإن أراد الوالدان فطام المولود قبل انتهاء السنتين فلا حرج عليهما إذا تراضيا وتشاورا في ذلك؛ ليصلا إلى ما فيه مصلحة المولود. وإن اتفق الوالدان على إرضاع المولود من مرضعة أخرى غير والدته فلا حرج عليهما، إذا سلَّم الوالد للأم حقَّها، وسلَّم للمرضعة أجرها بما يتعارفه الناس. وخافوا الله في جميع أحوالكم، واعلموا أن الله بما تعملون بصير، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "Mothers may nurse their infants for two whole years, for those who desire to complete the nursing-period. It is the duty of the father to provide for them and clothe them in a proper manner. No soul shall be burdened beyond its capacity. No mother shall be harmed on account of her child, and no father shall be harmed on account of his child. The same duty rests upon the heir. If the couple desire weaning, by mutual consent and consultation, they commit no error by doing so. You commit no error by hiring nursing-mothers, as long as you pay them fairly. And be wary of God, and know that God is Seeing of what you do.", "translation_id": "Para ibu hendaklah menyusukan anak-anaknya selama dua tahun penuh, yaitu bagi yang ingin menyempurnakan penyusuan. Dan kewajiban ayah memberi makan dan pakaian kepada para ibu dengan cara ma'ruf. Seseorang tidak dibebani melainkan menurut kadar kesanggupannya. Janganlah seorang ibu menderita kesengsaraan karena anaknya dan seorang ayah karena anaknya, dan warispun berkewajiban demikian. Apabila keduanya ingin menyapih (sebelum dua tahun) dengan kerelaan keduanya dan permusyawaratan, maka tidak ada dosa atas keduanya. Dan jika kamu ingin anakmu disusukan oleh orang lain, maka tidak ada dosa bagimu apabila kamu memberikan pembayaran menurut yang patut. Bertakwalah kamu kepada Allah dan ketahuilah bahwa Allah Maha Melihat apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}], "38": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 234, "text": "وَٱلَّذِینَ یُتَوَفَّوۡنَ مِنكُمۡ وَیَذَرُونَ أَزۡوَ ٰجࣰا یَتَرَبَّصۡنَ بِأَنفُسِهِنَّ أَرۡبَعَةَ أَشۡهُرࣲ وَعَشۡرࣰاۖ فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَیۡكُمۡ فِیمَا فَعَلۡنَ فِیۤ أَنفُسِهِنَّ بِٱلۡمَعۡرُوفِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ ۝٢٣٤", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "والذين يموتون منكم، ويتركون زوجات بعدهم، يجب عليهن الانتظار بأنفسهن مدة أربعة أشهر وعشرة أيام، لا يخرجن من منزل الزوجية، ولا يتزيَّنَّ، ولا يتزوجن، فإذا انتهت المدة المذكورة فلا إثم عليكم يا أولياء النساء فيما يفعلن في أنفسهن من الخروج، والتزين، والزواج على الوجه المقرر شرعًا. والله سبحانه وتعالى خبير بأعمالكم ظاهرها وباطنها، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "As for those among you who die and leave widows behind, their widows shall wait by themselves for four months and ten days. When they have reached their term, there is no blame on you regarding what they might honorably do with themselves. God is fully acquainted with what you do.", "translation_id": "Orang-orang yang meninggal dunia di antaramu dengan meninggalkan isteri-isteri (hendaklah para isteri itu) menangguhkan dirinya (ber'iddah) empat bulan sepuluh hari. Kemudian apabila telah habis 'iddahnya, maka tiada dosa bagimu (para wali) membiarkan mereka berbuat terhadap diri mereka menurut yang patut. Allah mengetahui apa yang kamu perbuat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 235, "text": "وَلَا جُنَاحَ عَلَیۡكُمۡ فِیمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَاۤءِ أَوۡ أَكۡنَنتُمۡ فِیۤ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَـٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّاۤ أَن تَقُولُوا۟ قَوۡلࣰا مَّعۡرُوفࣰاۚ وَلَا تَعۡزِمُوا۟ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ یَبۡلُغَ ٱلۡكِتَـٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِیۤ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِیمࣱ ۝٢٣٥", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "ولا إثم عليكم -أيها الرجال- فيما تُلَمِّحون به مِن طلب الزواج بالنساء المتوفَّى عنهنَّ أزواجهن، أو المطلقات طلاقًا بائنًا في أثناء عدتهن، ولا ذنب عليكم أيضًا فيما أضمرتموه في أنفسكم من نية الزواج بهن بعد انتهاء عدتهن. علم الله أنكم ستذكرون النساء المعتدَّات، ولن تصبروا على السكوت عنهن، لضعفكم؛ لذلك أباح لكم أن تذكروهن تلميحًا أو إضمارًا في النفس، واحذروا أن تواعدوهن على النكاح سرًا بالزنى أو الاتفاق على الزواج في أثناء العدة، إلا أن تقولوا قولا يُفْهَم منه أن مثلها يُرْغَبُ فيها الأزواج، ولا تعزموا على عقد النكاح في زمان العدة حتى تنقضي مدتها. واعلموا أن الله يعلم ما في أنفسكم فخافوه، واعلموا أن الله غفور لمن تاب من ذنوبه، حليم على عباده لا يعجل عليهم بالعقوبة.", "isBasmala": false, "translation_en": "You commit no error by announcing your engagement to women, or by keeping it to yourselves. God knows that you will be thinking about them. But do not meet them secretly, unless you have something proper to say. And do not confirm the marriage tie until the writing is fulfilled. And know that God knows what is in your souls, so beware of Him. And know that God is Forgiving and Forbearing.", "translation_id": "Dan tidak ada dosa bagi kamu meminang wanita-wanita itu dengan sindiran atau kamu menyembunyikan (keinginan mengawini mereka) dalam hatimu. Allah mengetahui bahwa kamu akan menyebut-nyebut mereka, dalam pada itu janganlah kamu mengadakan janji kawin dengan mereka secara rahasia, kecuali sekedar mengucapkan (kepada mereka) perkataan yang ma'ruf. Dan janganlah kamu berazam (bertetap hati) untuk beraqad nikah, sebelum habis 'iddahnya. Dan ketahuilah bahwasanya Allah mengetahui apa yang ada dalam hatimu; maka takutlah kepada-Nya, dan ketahuilah bahwa Allah Maha Pengampun lagi Maha Penyantun.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 236, "text": "لَّا جُنَاحَ عَلَیۡكُمۡ إِن طَلَّقۡتُمُ ٱلنِّسَاۤءَ مَا لَمۡ تَمَسُّوهُنَّ أَوۡ تَفۡرِضُوا۟ لَهُنَّ فَرِیضَةࣰۚ وَمَتِّعُوهُنَّ عَلَى ٱلۡمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلۡمُقۡتِرِ قَدَرُهُۥ مَتَـٰعَۢا بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُحۡسِنِینَ ۝٢٣٦", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "لا إثم عليكم -أيها الأزواج- إن طلقتم النساء بعد العقد عليهن، وقبل أن تجامعوهن، أو تحددوا مهرًا لهن، ومتِّعوهن بشيء ينتفعن به جبرًا لهن، ودفعًا لوحشة الطلاق، وإزالة للأحقاد. وهذه المتعة تجب بحسب حال الرجل المطلِّق: على الغني قَدْر سَعَة رزقه، وعلى الفقير قَدْر ما يملكه، متاعًا على الوجه المعروف شرعًا، وهو حق ثابت على الذين يحسنون إلى المطلقات وإلى أنفسهم بطاعة الله.", "isBasmala": false, "translation_en": "You commit no error by divorcing women before having touched them, or before having set the dowry for them. And compensate them-the wealthy according to his means, and the poor according to his means-with a fair compensation, a duty upon the doers of good.", "translation_id": "Tidak ada kewajiban membayar (mahar) atas kamu, jika kamu menceraikan isteri-isteri kamu sebelum kamu bercampur dengan mereka dan sebelum kamu menentukan maharnya. Dan hendaklah kamu berikan suatu mut'ah (pemberian) kepada mereka. Orang yang mampu menurut kemampuannya dan orang yang miskin menurut kemampuannya (pula), yaitu pemberian menurut yang patut. Yang demikian itu merupakan ketentuan bagi orang-orang yang berbuat kebajikan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 237, "text": "وَإِن طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ وَقَدۡ فَرَضۡتُمۡ لَهُنَّ فَرِیضَةࣰ فَنِصۡفُ مَا فَرَضۡتُمۡ إِلَّاۤ أَن یَعۡفُونَ أَوۡ یَعۡفُوَا۟ ٱلَّذِی بِیَدِهِۦ عُقۡدَةُ ٱلنِّكَاحِۚ وَأَن تَعۡفُوۤا۟ أَقۡرَبُ لِلتَّقۡوَىٰۚ وَلَا تَنسَوُا۟ ٱلۡفَضۡلَ بَیۡنَكُمۡۚ إِنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ بَصِیرٌ ۝٢٣٧", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "وإن طلَّقتم النساء بعد العقد عليهن، ولم تجامعوهن، ولكنكم ألزمتم أنفسكم بمهر محدد لهن، فيجب عليكم أن تعطوهن نصف المهر المتفق عليه، إلا أنْ تُسامِح المطلقات، فيتركن نصف المهر المستحق لهن، أو يسمح الزوج بأن يترك للمطلقة المهر كله، وتسامحكم أيها الرجال والنساء أقرب إلى خشية الله وطاعته، ولا تنسوا -أيها الناس- الفضل والإحسان بينكم، وهو إعطاء ما ليس بواجب عليكم، والتسامح في الحقوق. إن الله بما تعملون بصير، يُرغِّبكم في المعروف، ويحثُّكم على الفضل.", "isBasmala": false, "translation_en": "If you divorce them before you have touched them, but after you had set the dowry for them, give them half of what you specified-unless they forego the right, or the one in whose hand is the marriage contract foregoes it. But to forego is nearer to piety. And do not forget generosity between one another. God is seeing of everything you do.", "translation_id": "Jika kamu menceraikan isteri-isterimu sebelum kamu bercampur dengan mereka, padahal sesungguhnya kamu sudah menentukan maharnya, maka bayarlah seperdua dari mahar yang telah kamu tentukan itu, kecuali jika isteri-isterimu itu memaafkan atau dimaafkan oleh orang yang memegang ikatan nikah, dan pemaafan kamu itu lebih dekat kepada takwa. Dan janganlah kamu melupakan keutamaan di antara kamu. Sesungguhnya Allah Maha Melihat segala apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}], "39": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 238, "text": "حَـٰفِظُوا۟ عَلَى ٱلصَّلَوَ ٰتِ وَٱلصَّلَوٰةِ ٱلۡوُسۡطَىٰ وَقُومُوا۟ لِلَّهِ قَـٰنِتِینَ ۝٢٣٨", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "حافظوا -أيها المسلمون- على الصلوات الخمس المفروضة بالمداومة على أدائها في أوقاتها بشروطها وأركانها وواجباتها، وحافظوا على الصلاة المتوسطة بينها وهي صلاة العصر، وقوموا في صلاتكم مطيعين لله، خاشعين ذليلين.", "isBasmala": false, "translation_en": "Guard your prayers, and the middle prayer, and stand before God in devotion.", "translation_id": "Peliharalah semua shalat(mu), dan (peliharalah) shalat wusthaa. Berdirilah untuk Allah (dalam shalatmu) dengan khusyu'.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 239, "text": "فَإِنۡ خِفۡتُمۡ فَرِجَالًا أَوۡ رُكۡبَانࣰاۖ فَإِذَاۤ أَمِنتُمۡ فَٱذۡكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمۡ تَكُونُوا۟ تَعۡلَمُونَ ۝٢٣٩", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "فإن خفتم من عدو لكم فصلوا صلاة الخوف ماشين، أو راكبين، على أي هيئة تستطيعونها ولو بالإيماء، أو إلى غير جهة القبلة، فإذا زال خوفكم فصلُّوا صلاة الأمن، واذكروا الله فيها، ولا تنقصوها عن هيئتها الأصلية، واشكروا له على ما علَّمكم من أمور العبادات والأحكام ما لم تكونوا على علم به.", "isBasmala": false, "translation_en": "But if you are in fear, then on foot, or riding. And when you are safe, remember God, as He taught you what you did not know.", "translation_id": "Jika kamu dalam keadaan takut (bahaya), maka shalatlah sambil berjalan atau berkendaraan. Kemudian apabila kamu telah aman, maka sebutlah Allah (shalatlah), sebagaimana Allah telah mengajarkan kepada kamu apa yang belum kamu ketahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 240, "text": "وَٱلَّذِینَ یُتَوَفَّوۡنَ مِنكُمۡ وَیَذَرُونَ أَزۡوَ ٰجࣰا وَصِیَّةࣰ لِّأَزۡوَ ٰجِهِم مَّتَـٰعًا إِلَى ٱلۡحَوۡلِ غَیۡرَ إِخۡرَاجࣲۚ فَإِنۡ خَرَجۡنَ فَلَا جُنَاحَ عَلَیۡكُمۡ فِی مَا فَعَلۡنَ فِیۤ أَنفُسِهِنَّ مِن مَّعۡرُوفࣲۗ وَٱللَّهُ عَزِیزٌ حَكِیمࣱ ۝٢٤٠", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "والأزواج الذين يموتون ويتركون زوجات بعدهم، فعليهم وصيةً لهنَّ: أن يُمَتَّعن سنه تامة من يوم الوفاة، بالسكنى في منزل الزوج من غير إخراج الورثة لهن مدة السنة؛ جبرًا لخاطر الزوجة، وبرًا بالمتوفَّى. فإن خرجت الزوجات باختيارهن قبل انقضاء السنة فلا إثم عليكم -أيها الورثة- في ذلك، ولا حرج على الزوجات فيما فعلن في أنفسهن من أمور مباحة. والله عزيز في ملكه، حكيم في أمره ونهيه. وهذه الآية منسوخة بقوله تعالى: (والذين يتوفون منكم ويذرون أزواجًا يتربصن بأنفسهن أربعة أشهر وعشرًا).", "isBasmala": false, "translation_en": "Those of you who die and leave wives behind-a will shall provide their wives with support for a year, provided they do not leave. If they leave, you are not to blame for what they do with themselves, provided it is reasonable. God is Mighty and Wise.", "translation_id": "Dan orang-orang yang akan meninggal dunia di antara kamu dan meninggalkan isteri, hendaklah berwasiat untuk isteri-isterinya, (yaitu) diberi nafkah hingga setahun lamanya dan tidak disuruh pindah (dari rumahnya). Akan tetapi jika mereka pindah (sendiri), maka tidak ada dosa bagimu (wali atau waris dari yang meninggal) membiarkan mereka berbuat yang ma'ruf terhadap diri mereka. Dan Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 241, "text": "وَلِلۡمُطَلَّقَـٰتِ مَتَـٰعُۢ بِٱلۡمَعۡرُوفِۖ حَقًّا عَلَى ٱلۡمُتَّقِینَ ۝٢٤١", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "وللمطلقات متاع من كسوة ونفقة على الوجه المعروف المستحسن شرعًا، حقًا على الذين يخافون الله ويتقونه في أمره ونهيه.", "isBasmala": false, "translation_en": "And divorced women shall be provided for, equitably-a duty upon the righteous.", "translation_id": "Kepada wanita-wanita yang diceraikan (hendaklah diberikan oleh suaminya) mut'ah menurut yang ma'ruf, sebagai suatu kewajiban bagi orang-orang yang bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 242, "text": "كَذَ ٰلِكَ یُبَیِّنُ ٱللَّهُ لَكُمۡ ءَایَـٰتِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ ۝٢٤٢", "juz": 2, "hizb": "(*½ ح 4*)", "tafsir": "مثل ذلك البيان الواضح في أحكام الأولاد والنساء، يبيِّن الله لكم آياته وأحكامه في كل ما تحتاجونه في معاشكم ومعادكم؛ لكي تعقلوها وتعملوا بها.", "isBasmala": false, "translation_en": "God thus explains His revelations to you, so that you may understand.", "translation_id": "Demikianlah Allah menerangkan kepadamu ayat-ayat-Nya (hukum-hukum-Nya) supaya kamu memahaminya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 243, "text": "۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ خَرَجُوا۟ مِن دِیَـٰرِهِمۡ وَهُمۡ أُلُوفٌ حَذَرَ ٱلۡمَوۡتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحۡیَـٰهُمۡۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَشۡكُرُونَ ۝٢٤٣", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "ألم تعلم -أيها الرسول- قصة الذين فرُّوا من أرضهم ومنازلهم، وهم ألوف كثيرة؛ خشية الموت من الطاعون أو القتال، فقال لهم الله: موتوا، فماتوا دفعة واحدة عقوبة على فرارهم من قدر الله، ثم أحياهم الله تعالى بعد مدة؛ ليستوفوا آجالهم، وليتعظوا ويتوبوا؟ إن الله لذو فضل عظيم على الناس بنعمه الكثيرة، ولكن أكثر الناس لا يشكرون فضل الله عليهم.", "isBasmala": false, "translation_en": "Have you not considered those who fled their homes, by the thousands, fearful of death? God said to them, \"Die.\" Then He revived them. God is Gracious towards the people, but most people are not appreciative.", "translation_id": "Apakah kamu tidak memperhatikan orang-orang yang ke luar dari kampung halaman mereka, sedang mereka beribu-ribu (jumlahnya) karena takut mati; maka Allah berfirman kepada mereka: \"Matilah kamu\", kemudian Allah menghidupkan mereka. Sesungguhnya Allah mempunyai karunia terhadap manusia tetapi kebanyakan manusia tidak bersyukur.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 244, "text": "وَقَـٰتِلُوا۟ فِی سَبِیلِ ٱللَّهِ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ ۝٢٤٤", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "وقاتلوا -أيها المسلمون- الكفار لنصرة دين الله، واعلموا أن الله سميع لأقوالكم، عليم بنيَّاتكم وأعمالكم.", "isBasmala": false, "translation_en": "Fight in the cause of God, and know that God is Hearing and Knowing.", "translation_id": "Dan berperanglah kamu sekalian di jalan Allah, dan ketahuilah sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 245, "text": "مَّن ذَا ٱلَّذِی یُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنࣰا فَیُضَـٰعِفَهُۥ لَهُۥۤ أَضۡعَافࣰا كَثِیرَةࣰۚ وَٱللَّهُ یَقۡبِضُ وَیَبۡصُۜطُ وَإِلَیۡهِ تُرۡجَعُونَ ۝٢٤٥", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "من ذا الذي ينفق في سبيل الله إنفاقًا حسنًا احتسابًا للأجر، فيضاعفه له أضعافا كثيرة لا تحصى من الثواب وحسن الجزاء؟ والله يقبض ويبسط، فأنفقوا ولا تبالوا؛ فإنه هو الرزاق، يُضيِّق على مَن يشاء من عباده في الرزق، ويوسعه على آخرين، له الحكمة البالغة في ذلك، وإليه وحده ترجعون بعد الموت، فيجازيكم على أعمالكم.", "isBasmala": false, "translation_en": "Who is he who will offer God a generous loan, so He will multiply it for him manifold? God receives and amplifies, and to Him you will be returned.", "translation_id": "Siapakah yang mau memberi pinjaman kepada Allah, pinjaman yang baik (menafkahkan hartanya di jalan Allah), maka Allah akan meperlipat gandakan pembayaran kepadanya dengan lipat ganda yang banyak. Dan Allah menyempitkan dan melapangkan (rezeki) dan kepada-Nya-lah kamu dikembalikan.", "manzil": 1, "manzil_display": ""}], "40": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 246, "text": "أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِیۤ إِسۡرَ ٰۤءِیلَ مِنۢ بَعۡدِ مُوسَىٰۤ إِذۡ قَالُوا۟ لِنَبِیࣲّ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكࣰا نُّقَـٰتِلۡ فِی سَبِیلِ ٱللَّهِۖ قَالَ هَلۡ عَسَیۡتُمۡ إِن كُتِبَ عَلَیۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَـٰتِلُوا۟ۖ قَالُوا۟ وَمَا لَنَاۤ أَلَّا نُقَـٰتِلَ فِی سَبِیلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِیَـٰرِنَا وَأَبۡنَاۤىِٕنَاۖ فَلَمَّا كُتِبَ عَلَیۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡا۟ إِلَّا قَلِیلࣰا مِّنۡهُمۡۚ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ ۝٢٤٦", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "ألم تعلم -أيها الرسول- قصة الأشراف والوجهاء من بني إسرائيل من بعد زمان موسى؛ حين طلبوا من نبيهم أن يولي عليهم ملكا، يجتمعون تحت قيادته، ويقاتلون أعداءهم في سبيل الله. قال لهم نبيهم: هل الأمر كما أتوقعه إنْ فُرِض عليكم القتال في سبيل الله أنكم لا تقاتلون؛ فإني أتوقع جبنكم وفراركم من القتال، قالوا مستنكرين توقع نبيهم: وأي مانع يمنعنا عن القتال في سبيل الله، وقد أَخْرَجَنَا عدوُّنا من ديارنا، وأبعدنا عن أولادنا بالقتل والأسر؟ فلما فرض الله عليهم القتال مع الملِك الذي عيَّنه لهم جَبُنوا وفرُّوا عن القتال، إلا قليلا منهم ثبتوا بفضل الله. والله عليم بالظالمين الناكثين عهودهم.", "isBasmala": false, "translation_en": "Have you not considered the notables of the Children of Israel after Moses? When they said to a prophet of theirs, \"Appoint a king for us, and we will fight in the cause of God.\" He said, \"Is it possible that, if fighting was ordained for you, you would not fight?\" They said, \"Why would we not fight in the cause of God, when we were driven out of our homes, along with our children?\" But when fighting was ordained for them, they turned away, except for a few of them. But God is aware of the wrongdoers.", "translation_id": "Apakah kamu tidak memperhatikan pemuka-pemuka Bani Israil sesudah Nabi Musa, yaitu ketika mereka berkata kepada seorang Nabi mereka: \"Angkatlah untuk kami seorang raja supaya kami berperang (di bawah pimpinannya) di jalan Allah\". Nabi mereka menjawab: \"Mungkin sekali jika kamu nanti diwajibkan berperang, kamu tidak akan berperang\". Mereka menjawab: \"Mengapa kami tidak mau berperang di jalan Allah, padahal sesungguhnya kami telah diusir dari anak-anak kami?\". Maka tatkala perang itu diwajibkan atas mereka, merekapun berpaling, kecuali beberapa saja di antara mereka. Dan Allah Maha Mengetahui siapa orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 247, "text": "وَقَالَ لَهُمۡ نَبِیُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكࣰاۚ قَالُوۤا۟ أَنَّىٰ یَكُونُ لَهُ ٱلۡمُلۡكُ عَلَیۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ یُؤۡتَ سَعَةࣰ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَیۡكُمۡ وَزَادَهُۥ بَسۡطَةࣰ فِی ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ یُؤۡتِی مُلۡكَهُۥ مَن یَشَاۤءُۚ وَٱللَّهُ وَ ٰسِعٌ عَلِیمࣱ ۝٢٤٧", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "وقال لهم نبيهم: إن الله قد أرسل إليكم طالوت مَلِكًا إجابة لطلبكم، يقودكم لقتال عدوكم كما طلبتم. قال كبراء بني إسرائيل: كيف يكون طالوت مَلِكًا علينا، وهو لا يستحق ذلك؟ لأنه ليس من سبط الملوك، ولا من بيت النبوة، ولم يُعْط كثرة في الأموال يستعين بها في ملكه، فنحن أحق بالملك منه؛ لأننا من سبط الملوك ومن بيت النبوة. قال لهم نبيهم: إن الله اختاره عليكم وهو سبحانه أعلم بأمور عباده، وزاده سَعَة في العلم وقوة في الجسم ليجاهد العدو. والله مالك الملك يعطي ملكه مَن يشاء من عباده، والله واسع الفضل والعطاء، عليم بحقائق الأمور، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "Their prophet said to them, \"God has appointed Saul to be your king.\" They said, \"How can he have authority over us, when we are more worthy of authority than he, and he was not given plenty of wealth?\" He said, \"God has chosen him over you, and has increased him in knowledge and stature.\" God bestows His sovereignty upon whomever He wills. God is Embracing and Knowing.", "translation_id": "Nabi mereka mengatakan kepada mereka: \"Sesungguhnya Allah telah mengangkat Thalut menjadi rajamu\". Mereka menjawab: \"Bagaimana Thalut memerintah kami, padahal kami lebih berhak mengendalikan pemerintahan daripadanya, sedang diapun tidak diberi kekayaan yang cukup banyak?\" Nabi (mereka) berkata: \"Sesungguhnya Allah telah memilih rajamu dan menganugerahinya ilmu yang luas dan tubuh yang perkasa\". Allah memberikan pemerintahan kepada siapa yang dikehendaki-Nya. Dan Allah Maha Luas pemberian-Nya lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 248, "text": "وَقَالَ لَهُمۡ نَبِیُّهُمۡ إِنَّ ءَایَةَ مُلۡكِهِۦۤ أَن یَأۡتِیَكُمُ ٱلتَّابُوتُ فِیهِ سَكِینَةࣱ مِّن رَّبِّكُمۡ وَبَقِیَّةࣱ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَـٰرُونَ تَحۡمِلُهُ ٱلۡمَلَـٰۤىِٕكَةُۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِینَ ۝٢٤٨", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "وقال لهم نبيهم: إن علامة ملكه أن يأتيكم الصندوق الذي فيه التوراة -وكان أعداؤهم قد انتزعوه منهم- فيه طمأنينة من ربكم تثبت قلوب المخلصين، وفيه بقية من بعض أشياء تركها آل موسى وآل هارون، مثل العصا وفُتات الألواح تحمله الملائكة. إن في ذلك لأعظم برهان لكم على اختيار طالوت ملكًا عليكم بأمر الله، إن كنتم مصدقين بالله ورسله.", "isBasmala": false, "translation_en": "And their prophet said to them, \"The proof of his kingship is that the Ark will be restored to you, bringing tranquility from your Lord, and relics left by the family of Moses and the family of Aaron. It will be carried by the angels. In that is a sign for you, if you are believers.\"", "translation_id": "Dan Nabi mereka mengatakan kepada mereka: \"Sesungguhnya tanda ia akan menjadi raja, ialah kembalinya tabut kepadamu, di dalamnya terdapat ketenangan dari Tuhanmu dan sisa dari peninggalan keluarga Musa dan keluarga Harun; tabut itu dibawa malaikat. Sesungguhnya pada yang demikian itu terdapat tanda bagimu, jika kamu orang yang beriman.", "manzil": 1, "manzil_display": ""}], "41": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 249, "text": "فَلَمَّا فَصَلَ طَالُوتُ بِٱلۡجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبۡتَلِیكُم بِنَهَرࣲ فَمَن شَرِبَ مِنۡهُ فَلَیۡسَ مِنِّی وَمَن لَّمۡ یَطۡعَمۡهُ فَإِنَّهُۥ مِنِّیۤ إِلَّا مَنِ ٱغۡتَرَفَ غُرۡفَةَۢ بِیَدِهِۦۚ فَشَرِبُوا۟ مِنۡهُ إِلَّا قَلِیلࣰا مِّنۡهُمۡۚ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلۡیَوۡمَ بِجَالُوتَ وَجُنُودِهِۦۚ قَالَ ٱلَّذِینَ یَظُنُّونَ أَنَّهُم مُّلَـٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةࣲ قَلِیلَةٍ غَلَبَتۡ فِئَةࣰ كَثِیرَةَۢ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِینَ ۝٢٤٩", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "فلما خرج طالوت بجنوده لقتال العمالقة قال لهم: إن الله ممتحنكم على الصبر بنهر أمامكم تعبرونه؛ ليتميَّز المؤمن من المنافق، فمن شرب منكم من ماء النهر فليس مني، ولا يصلح للجهاد معي، ومن لم يذق الماء فإنه مني؛ لأنه مطيع لأمري وصالح للجهاد، إلا مَن ترخَّص واغترف غُرْفة واحدة بيده فلا لوم عليه. فلما وصلوا إلى النهر انكبوا على الماء، وأفرطوا في الشرب منه، إلا عددًا قليلا منهم صبروا على العطش والحر، واكتفوا بغُرْفة اليد، وحينئذ تخلف العصاة. ولما عبر طالوت النهر هو والقلة المؤمنة معه -وهم ثلاثمائة وبضعة عشر رجلا لملاقاة العدو، ورأوا كثرة عدوهم وعدَّتهم، قالوا: لا قدرة لنا اليوم بجالوت وجنوده الأشداء، فأجاب الذين يوقنون بلقاء الله، يُذَكِّرون إخوانهم بالله وقدرته قائلين: كم من جماعة قليلة مؤمنة صابرة، غلبت بإذن الله وأمره جماعة كثيرة كافرة باغية. والله مع الصابرين بتوفيقه ونصره، وحسن مثوبته.", "isBasmala": false, "translation_en": "When Saul set out with the troops, he said, \"God will be testing you with a river. Whoever drinks from it does not belong with me. But whoever does not drink from it, does belong with me, except for whoever scoops up a little with his hand.\" But they drank from it, except for a few of them. Then, when he crossed it, he and those who believed with him, they said, \"We have no strength to face Goliath and his troops today.\" But those who knew that they would meet God said, \"How many a small group has defeated a large group by God's will. God is with the steadfast.\"", "translation_id": "Maka tatkala Thalut keluar membawa tentaranya, ia berkata: \"Sesungguhnya Allah akan menguji kamu dengan suatu sungai. Maka siapa di antara kamu meminum airnya; bukanlah ia pengikutku. Dan barangsiapa tiada meminumnya, kecuali menceduk seceduk tangan, maka dia adalah pengikutku\". Kemudian mereka meminumnya kecuali beberapa orang di antara mereka. Maka tatkala Thalut dan orang-orang yang beriman bersama dia telah menyeberangi sungai itu, orang-orang yang telah minum berkata: \"Tak ada kesanggupan kami pada hari ini untuk melawan Jalut dan tentaranya\". Orang-orang yang meyakini bahwa mereka akan menemui Allah, berkata: \"Berapa banyak terjadi golongan yang sedikit dapat mengalahkan golongan yang banyak dengan izin Allah. Dan Allah beserta orang-orang yang sabar\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 250, "text": "وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَاۤ أَفۡرِغۡ عَلَیۡنَا صَبۡرࣰا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ ۝٢٥٠", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "ولما ظهروا لجالوت وجنوده، ورأوا الخطر رأي العين، فزعوا إلى الله بالدعاء والضراعة قائلين: ربنا أنزل على قلوبنا صبرًا عظيمًا، وثبت أقدامنا، واجعلها راسخة في قتال العدو، لا تفر مِن هول الحرب، وانصرنا بعونك وتأييدك على القوم الكافرين.", "isBasmala": false, "translation_en": "And when they confronted Goliath and his troops, they said, \"Our Lord, pour down patience on us, and strengthen our foothold, and support us against the faithless people.\"", "translation_id": "Tatkala Jalut dan tentaranya telah nampak oleh mereka, merekapun (Thalut dan tentaranya) berdoa: \"Ya Tuhan kami, tuangkanlah kesabaran atas diri kami, dan kokohkanlah pendirian kami dan tolonglah kami terhadap orang-orang kafir\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 251, "text": "فَهَزَمُوهُم بِإِذۡنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ وَٱلۡحِكۡمَةَ وَعَلَّمَهُۥ مِمَّا یَشَاۤءُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّفَسَدَتِ ٱلۡأَرۡضُ وَلَـٰكِنَّ ٱللَّهَ ذُو فَضۡلٍ عَلَى ٱلۡعَـٰلَمِینَ ۝٢٥١", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "فهزموهم بإذن الله، وقتل داود -عليه السلام- جالوتَ قائدَ الجبابرة، وأعطى الله عز وجل داود بعد ذلك الملك والنبوة في بني إسرائيل، وعَلَّمه مما يشاء من العلوم. ولولا أن يدفع الله ببعض الناس -وهم أهل الطاعة له والإيمان به- بعضًا، وهم أهل المعصية لله والشرك به، لفسدت الأرض بغلبة الكفر، وتمكُّن الطغيان، وأهل المعاصي، ولكن الله ذو فضل على المخلوقين جميعًا.", "isBasmala": false, "translation_en": "And they defeated them by God's leave, and David killed Goliath, and God gave him sovereignty and wisdom, and taught him as He willed. Were it not for God restraining the people, some by means of others, the earth would have gone to ruin. But God is gracious towards mankind.", "translation_id": "Mereka (tentara Thalut) mengalahkan tentara Jalut dengan izin Allah dan (dalam peperangan itu) Daud membunuh Jalut, kemudian Allah memberikan kepadanya (Daud) pemerintahan dan hikmah (sesudah meninggalnya Thalut) dan mengajarkan kepadanya apa yang dikehendaki-Nya. Seandainya Allah tidak menolak (keganasan) sebahagian umat manusia dengan sebagian yang lain, pasti rusaklah bumi ini. Tetapi Allah mempunyai karunia (yang dicurahkan) atas semesta alam.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 252, "text": "تِلۡكَ ءَایَـٰتُ ٱللَّهِ نَتۡلُوهَا عَلَیۡكَ بِٱلۡحَقِّۚ وَإِنَّكَ لَمِنَ ٱلۡمُرۡسَلِینَ ۝٢٥٢", "juz": 2, "hizb": "(*¾ ح 4*)", "tafsir": "تلك حجج الله وبراهينه، نقصُّها عليك -أيها النبي- بالصدق، وإنك لمن المرسلين الصادقين.", "isBasmala": false, "translation_en": "These are God's revelations, which We recite to you in truth. You are one of the messengers.", "translation_id": "Itu adalah ayat-ayat dari Allah, Kami bacakan kepadamu dengan hak (benar) dan sesungguhnya kamu benar-benar salah seorang di antara nabi-nabi yang diutus.", "manzil": 1, "manzil_display": ""}], "42": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 253, "text": "۞ تِلۡكَ ٱلرُّسُلُ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲۘ مِّنۡهُم مَّن كَلَّمَ ٱللَّهُۖ وَرَفَعَ بَعۡضَهُمۡ دَرَجَـٰتࣲۚ وَءَاتَیۡنَا عِیسَى ٱبۡنَ مَرۡیَمَ ٱلۡبَیِّنَـٰتِ وَأَیَّدۡنَـٰهُ بِرُوحِ ٱلۡقُدُسِۗ وَلَوۡ شَاۤءَ ٱللَّهُ مَا ٱقۡتَتَلَ ٱلَّذِینَ مِنۢ بَعۡدِهِم مِّنۢ بَعۡدِ مَا جَاۤءَتۡهُمُ ٱلۡبَیِّنَـٰتُ وَلَـٰكِنِ ٱخۡتَلَفُوا۟ فَمِنۡهُم مَّنۡ ءَامَنَ وَمِنۡهُم مَّن كَفَرَۚ وَلَوۡ شَاۤءَ ٱللَّهُ مَا ٱقۡتَتَلُوا۟ وَلَـٰكِنَّ ٱللَّهَ یَفۡعَلُ مَا یُرِیدُ ۝٢٥٣", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "هؤلاء الرسل الكرام فضَّل الله بعضهم على بعض، بحسب ما منَّ الله به عليهم: فمنهم مَن كلمه الله كموسى ومحمد عليهما الصلاة والسلام، وفي هذا إثبات صفة الكلام لله عز وجل على الوجه اللائق بجلاله، ومنهم مَن رفعه الله درجاتٍ عاليةً كمحمد صلى الله عليه وسلم، بعموم رسالته، وختم النبوة به، وتفضيل أمته على جميع الأمم، وغير ذلك. وآتى الله تعالى عيسى ابن مريم عليه السلام البينات المعجزات الباهرات، كإبراء مَن ولد أعمى بإذن الله تعالى، ومَن به برص بإذن الله، وكإحيائه الموتى بإذن الله، وأيده بجبريل عليه السلام. ولو شاء الله ألا يقتتل الذين جاؤوا مِن بعد هؤلاء الرسل مِن بعد ما جاءتهم البينات ما اقتتلوا، ولكن وقع الاختلاف بينهم: فمنهم مَن ثبت على إيمانه، ومنهم مَن أصر على كفره. ولو شاء الله بعد ما وقع الاختلاف بينهم، الموجب للاقتتال، ما اقتتلوا، ولكن الله يوفق مَن يشاء لطاعته والإيمان به، ويخذل مَن يشاء، فيعصيه ويكفر به، فهو يفعل ما يشاء ويختار.", "isBasmala": false, "translation_en": "These messengers: We gave some advantage over others. To some of them God spoke directly, and some He raised in rank. We gave Jesus son of Mary the clear miracles, and We strengthened him with the Holy Spirit. Had God willed, those who succeeded them would not have fought one another, after the clear signs had come to them; but they disputed; some of them believed, and some of them disbelieved. Had God willed, they would not have fought one another; but God does whatever He desires.", "translation_id": "Rasul-rasul itu Kami lebihkan sebagian (dari) mereka atas sebagian yang lain. Di antara mereka ada yang Allah berkata-kata (langsung dengan dia) dan sebagiannya Allah meninggikannya beberapa derajat. Dan Kami berikan kepada Isa putera Maryam beberapa mukjizat serta Kami perkuat dia dengan Ruhul Qudus. Dan kalau Allah menghendaki, niscaya tidaklah berbunuh-bunuhan orang-orang (yang datang) sesudah rasul-rasul itu, sesudah datang kepada mereka beberapa macam keterangan, akan tetapi mereka berselisih, maka ada di antara mereka yang beriman dan ada (pula) di antara mereka yang kafir. Seandainya Allah menghendaki, tidaklah mereka berbunuh-bunuhan. Akan tetapi Allah berbuat apa yang dikehendaki-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 254, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَنفِقُوا۟ مِمَّا رَزَقۡنَـٰكُم مِّن قَبۡلِ أَن یَأۡتِیَ یَوۡمࣱ لَّا بَیۡعࣱ فِیهِ وَلَا خُلَّةࣱ وَلَا شَفَـٰعَةࣱۗ وَٱلۡكَـٰفِرُونَ هُمُ ٱلظَّـٰلِمُونَ ۝٢٥٤", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "يا من آمنتم بالله وصدَّقتم رسوله وعملتم بهديه أخرجوا الزكاة المفروضة، وتصدَّقوا مما أعطاكم الله قبل مجيء يوم القيامة حين لا بيع فيكون ربح، ولا مال تفتدون به أنفسكم مِن عذاب الله، ولا صداقة صديق تُنقذكم، ولا شافع يملك تخفيف العذاب عنكم. والكافرون هم الظالمون المتجاوزون حدود الله.", "isBasmala": false, "translation_en": "O you who believe! Spend from what We have given you, before a Day comes in which there is neither trading, nor friendship, nor intercession. The disbelievers are the wrongdoers.", "translation_id": "Hai orang-orang yang beriman, belanjakanlah (di jalan Allah) sebagian dari rezeki yang telah Kami berikan kepadamu sebelum datang hari yang pada hari itu tidak ada lagi jual beli dan tidak ada lagi syafa'at. Dan orang-orang kafir itulah orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 255, "text": "ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡحَیُّ ٱلۡقَیُّومُۚ لَا تَأۡخُذُهُۥ سِنَةࣱ وَلَا نَوۡمࣱۚ لَّهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِی یَشۡفَعُ عِندَهُۥۤ إِلَّا بِإِذۡنِهِۦۚ یَعۡلَمُ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا یُحِیطُونَ بِشَیۡءࣲ مِّنۡ عِلۡمِهِۦۤ إِلَّا بِمَا شَاۤءَۚ وَسِعَ كُرۡسِیُّهُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَۖ وَلَا یَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِیُّ ٱلۡعَظِیمُ ۝٢٥٥", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "الله الذي لا يستحق الألوهية والعبودية إلا هو، الحيُّ الذي له جميع معاني الحياة الكاملة كما يليق بجلاله، القائم على كل شيء، لا تأخذه سِنَة أي: نعاس، ولا نوم، كل ما في السماوات وما في الأرض ملك له، ولا يتجاسر أحد أن يشفع عنده إلا بإذنه، محيط علمه بجميع الكائنات ماضيها وحاضرها ومستقبلها، يعلم ما بين أيدي الخلائق من الأمور المستقبلة، وما خلفهم من الأمور الماضية، ولا يَطَّلعُ أحد من الخلق على شيء من علمه إلا بما أعلمه الله وأطلعه عليه. وسع كرسيه السماوات والأرض، والكرسي: هو موضع قدمي الرب -جل جلاله- ولا يعلم كيفيته إلا الله سبحانه، ولا يثقله سبحانه حفظهما، وهو العلي بذاته وصفاته على جميع مخلوقاته، الجامع لجميع صفات العظمة والكبرياء. وهذه الآية أعظم آية في القرآن، وتسمى: (آية الكرسي).", "isBasmala": false, "translation_en": "God! There is no god except He, the Living, the Everlasting. Neither slumber overtakes Him, nor sleep. To Him belongs everything in the heavens and everything on earth. Who is he that can intercede with Him except with His permission? He knows what is before them, and what is behind them; and they cannot grasp any of His knowledge, except as He wills. His Throne extends over the heavens and the earth, and their preservation does not burden Him. He is the Most High, the Great.", "translation_id": "Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia Yang Hidup kekal lagi terus menerus mengurus (makhluk-Nya); tidak mengantuk dan tidak tidur. Kepunyaan-Nya apa yang di langit dan di bumi. Tiada yang dapat memberi syafa'at di sisi Allah tanpa izin-Nya? Allah mengetahui apa-apa yang di hadapan mereka dan di belakang mereka, dan mereka tidak mengetahui apa-apa dari ilmu Allah melainkan apa yang dikehendaki-Nya. Kursi Allah meliputi langit dan bumi. Dan Allah tidak merasa berat memelihara keduanya, dan Allah Maha Tinggi lagi Maha Besar.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 256, "text": "لَاۤ إِكۡرَاهَ فِی ٱلدِّینِۖ قَد تَّبَیَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَیِّۚ فَمَن یَكۡفُرۡ بِٱلطَّـٰغُوتِ وَیُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِیعٌ عَلِیمٌ ۝٢٥٦", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "لكمال هذا الدين واتضاح آياته لا يُحتاج إلى الإكراه عليه لمن تُقبل منهم الجزية، فالدلائل بينة يتضح بها الحق من الباطل، والهدى من الضلال. فَمَن يكفر بكل ما عُبِد من دون الله ويؤمن بالله، فقد ثبت واستقام على الطريقة المثلى، واستمسك من الدين بأقوى سبب لا انقطاع له. والله سميع لأقوال عباده، عليم بأفعالهم ونياتهم، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "There shall be no compulsion in religion; the right way has become distinct from the wrong way. Whoever renounces evil and believes in God has grasped the most trustworthy handle; which does not break. God is Hearing and Knowing.", "translation_id": "Tidak ada paksaan untuk (memasuki) agama (Islam); sesungguhnya telah jelas jalan yang benar daripada jalan yang sesat. Karena itu barangsiapa yang ingkar kepada Thaghut dan beriman kepada Allah, maka sesungguhnya ia telah berpegang kepada buhul tali yang amat kuat yang tidak akan putus. Dan Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}], "43": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 257, "text": "ٱللَّهُ وَلِیُّ ٱلَّذِینَ ءَامَنُوا۟ یُخۡرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِینَ كَفَرُوۤا۟ أَوۡلِیَاۤؤُهُمُ ٱلطَّـٰغُوتُ یُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَـٰتِۗ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٢٥٧", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "الله يتولى المؤمنين بنصره وتوفيقه وحفظه، يخرجهم من ظلمات الكفر، إلى نور الإيمان. والذين كفروا أنصارهم وأولياؤهم الأنداد والأوثان الذين يعبدونهم من دون الله، يُخرجونهم من نور الإيمان إلى ظلمات الكفر، أولئك أصحاب النار الملازمون لها، هم فيها باقون بقاء أبديًا لا يخرجون منها.", "isBasmala": false, "translation_en": "God is the Lord of those who believe; He brings them out of darkness and into light. As for those who disbelieve, their lords are the evil ones; they bring them out of light and into darkness-these are the inmates of the Fire, in which they will abide forever.", "translation_id": "Allah Pelindung orang-orang yang beriman; Dia mengeluarkan mereka dari kegelapan (kekafiran) kepada cahaya (iman). Dan orang-orang yang kafir, pelindung-pelindungnya ialah syaitan, yang mengeluarkan mereka daripada cahaya kepada kegelapan (kekafiran). Mereka itu adalah penghuni neraka; mereka kekal di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 258, "text": "أَلَمۡ تَرَ إِلَى ٱلَّذِی حَاۤجَّ إِبۡرَ ٰهِـۧمَ فِی رَبِّهِۦۤ أَنۡ ءَاتَىٰهُ ٱللَّهُ ٱلۡمُلۡكَ إِذۡ قَالَ إِبۡرَ ٰهِـۧمُ رَبِّیَ ٱلَّذِی یُحۡیِۦ وَیُمِیتُ قَالَ أَنَا۠ أُحۡیِۦ وَأُمِیتُۖ قَالَ إِبۡرَ ٰهِـۧمُ فَإِنَّ ٱللَّهَ یَأۡتِی بِٱلشَّمۡسِ مِنَ ٱلۡمَشۡرِقِ فَأۡتِ بِهَا مِنَ ٱلۡمَغۡرِبِ فَبُهِتَ ٱلَّذِی كَفَرَۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝٢٥٨", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "هل رأيت -أيها الرسول- أعجب مِن حال هذا الذي جادل إبراهيم عليه السلام في توحيد الله تعالى وربوبيته؛ لأن الله أعطاه المُلْك فتجبَّر وسأل إبراهيمَ: مَن ربُّك؟ فقال عليه السلام: ربي الذي يحيي الخلائق فتحيا، ويسلبها الحياة فتموت، فهو المتفرد بالإحياء والإماتة، قال: أنا أحيي وأميت، أي أقتل مَن أردتُ قَتْلَه، وأستبقي مَن أردت استبقاءه، فقال له إبراهيم: إن الله الذي أعبده يأتي بالشمس من المشرق، فهل تستطيع تغيير هذه السُّنَّة الإلهية بأن تجعلها تأتي من المغرب؛ فتحيَّر هذا الكافر وانقطعت حجته، شأنه شأن الظالمين لا يهديهم الله إلى الحق والصواب.", "isBasmala": false, "translation_en": "Have you not considered him who argued with Abraham about his Lord, because God had given him sovereignty? Abraham said, \"My Lord is He who gives life and causes death.\" He said, \"I give life and cause death.\" Abraham said, \"God brings the sun from the East, so bring it from the West,\" so the blasphemer was confounded. God does not guide the wrongdoing people.", "translation_id": "Apakah kamu tidak memperhatikan orang yang mendebat Ibrahim tentang Tuhannya (Allah) karena Allah telah memberikan kepada orang itu pemerintahan (kekuasaan). Ketika Ibrahim mengatakan: \"Tuhanku ialah Yang menghidupkan dan mematikan,\" orang itu berkata: \"Saya dapat menghidupkan dan mematikan\". Ibrahim berkata: \"Sesungguhnya Allah menerbitkan matahari dari timur, maka terbitkanlah dia dari barat,\" lalu terdiamlah orang kafir itu; dan Allah tidak memberi petunjuk kepada orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 259, "text": "أَوۡ كَٱلَّذِی مَرَّ عَلَىٰ قَرۡیَةࣲ وَهِیَ خَاوِیَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ یُحۡیِۦ هَـٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامࣲ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ یَوۡمًا أَوۡ بَعۡضَ یَوۡمࣲۖ قَالَ بَل لَّبِثۡتَ مِا۟ئَةَ عَامࣲ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ یَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَایَةࣰ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَیۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمࣰاۚ فَلَمَّا تَبَیَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٢٥٩", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "أو هل رأيت -أيها الرسول- مثل الذي مرَّ على قرية قد تهدَّمت دورها، وخَوَتْ على عروشها، فقال: كيف يحيي الله هذه القرية بعد موتها؟ فأماته الله مائة عام، ثم ردَّ إليه روحه، وقال له: كم قدر الزمان الذي لبثت ميتًا؟ قال: بقيت يومًا أو بعض يوم، فأخبره بأنه بقي ميتًا مائة عام، وأمره أن ينظر إلى طعامه وشرابه، وكيف حفظهما الله من التغيُّر هذه المدة الطويلة، وأمره أن ينظر إلى حماره كيف أحياه الله بعد أن كان عظامًا متفرقة؟ وقال له: ولنجعلك آية للناس، أي: دلالة ظاهرة على قدرة الله على البعث بعد الموت، وأمره أن ينظر إلى العظام كيف يرفع الله بعضها على بعض، ويصل بعضها ببعض، ثم يكسوها بعد الالتئام لحمًا، ثم يعيد فيها الحياة؟ فلما اتضح له ذلك عِيانًا اعترف بعظمة الله، وأنه على كل شيء قدير، وصار آية للناس.", "isBasmala": false, "translation_en": "Or like him who passed by a town collapsed on its foundations. He said, \"How can God revive this after its demise?\" Thereupon God caused him to die for a hundred years, and then resurrected him. He said, \"For how long have you tarried?\" He said, \"I have tarried for a day, or part of a day.\" He said, \"No. You have tarried for a hundred years. Now look at your food and your drink-it has not spoiled-and look at your donkey. We will make you a wonder for mankind. And look at the bones, how We arrange them, and then clothe them with flesh.\" So when it became clear to him, he said, \"I know that God has power over all things.\"", "translation_id": "Atau apakah (kamu tidak memperhatikan) orang yang melalui suatu negeri yang (temboknya) telah roboh menutupi atapnya. Dia berkata: \"Bagaimana Allah menghidupkan kembali negeri ini setelah hancur?\" Maka Allah mematikan orang itu seratus tahun, kemudian menghidupkannya kembali. Allah bertanya: \"Berapakah lamanya kamu tinggal di sini?\" Ia menjawab: \"Saya tinggal di sini sehari atau setengah hari\". Allah berfirman: \"Sebenarnya kamu telah tinggal di sini seratus tahun lamanya; lihatlah kepada makanan dan minumanmu yang belum lagi beubah; dan lihatlah kepada keledai kamu (yang telah menjadi tulang belulang); Kami akan menjadikan kamu tanda kekuasaan Kami bagi manusia; dan lihatlah kepada tulang belulang keledai itu, kemudian Kami menyusunnya kembali, kemudian Kami membalutnya dengan daging\". Maka tatkala telah nyata kepadanya (bagaimana Allah menghidupkan yang telah mati) diapun berkata: \"Saya yakin bahwa Allah Maha Kuasa atas segala sesuatu\".", "manzil": 1, "manzil_display": ""}], "44": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 260, "text": "وَإِذۡ قَالَ إِبۡرَ ٰهِـۧمُ رَبِّ أَرِنِی كَیۡفَ تُحۡیِ ٱلۡمَوۡتَىٰۖ قَالَ أَوَ لَمۡ تُؤۡمِنۖ قَالَ بَلَىٰ وَلَـٰكِن لِّیَطۡمَىِٕنَّ قَلۡبِیۖ قَالَ فَخُذۡ أَرۡبَعَةࣰ مِّنَ ٱلطَّیۡرِ فَصُرۡهُنَّ إِلَیۡكَ ثُمَّ ٱجۡعَلۡ عَلَىٰ كُلِّ جَبَلࣲ مِّنۡهُنَّ جُزۡءࣰا ثُمَّ ٱدۡعُهُنَّ یَأۡتِینَكَ سَعۡیࣰاۚ وَٱعۡلَمۡ أَنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ ۝٢٦٠", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "واذكر -أيها الرسول- طلب إبراهيم من ربه أن يريه كيفية البعث، فقال الله له: أَوَلم تؤمن؟ قال: بلى، ولكن أطلب ذلك لأزداد يقينًا على يقيني، قال: فخذ أربعة من الطير فاضممهن إليك واذبحهن وقطعهن، ثم اجعل على كل جبل منهن جزءًا، ثم نادِهن يأتينك مسرعات. فنادى إبراهيم عليه السلام، فإذا كل جزء يعود إلى موضعه، وإذا بها تأتي مسرعة. واعلم أن الله عزيز لا يغلبه شيء، حكيم في أقواله وأفعاله وشرعه وقدره.", "isBasmala": false, "translation_en": "And when Abraham said, \"My Lord, show me how You give life to the dead.\" He said, \"Have you not believed?\" He said, \"Yes, but to put my heart at ease.\" He said, \"Take four birds, and incline them to yourself, then place a part on each hill, then call to them; and they will come rushing to you. And know that God is Powerful and Wise.\"", "translation_id": "Dan (ingatlah) ketika Ibrahim berkata: \"Ya Tuhanku, perlihatkanlah kepadaku bagaimana Engkau menghidupkan orang-orang mati\". Allah berfirman: \"Belum yakinkah kamu?\" Ibrahim menjawab: \"Aku telah meyakinkannya, akan tetapi agar hatiku tetap mantap (dengan imanku) Allah berfirman: \"(Kalau demikian) ambillah empat ekor burung, lalu cincanglah semuanya olehmu. (Allah berfirman): \"Lalu letakkan diatas tiap-tiap satu bukit satu bagian dari bagian-bagian itu, kemudian panggillah mereka, niscaya mereka datang kepadamu dengan segera\". Dan ketahuilah bahwa Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 261, "text": "مَّثَلُ ٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰلَهُمۡ فِی سَبِیلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتۡ سَبۡعَ سَنَابِلَ فِی كُلِّ سُنۢبُلَةࣲ مِّا۟ئَةُ حَبَّةࣲۗ وَٱللَّهُ یُضَـٰعِفُ لِمَن یَشَاۤءُۚ وَٱللَّهُ وَ ٰسِعٌ عَلِیمٌ ۝٢٦١", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "ومِن أعظم ما ينتفع به المؤمنون الإنفاقُ في سبيل الله. ومثل المؤمنين الذين ينفقون أموالهم في سبيل الله كمثل حبة زُرِعتْ في أرض طيبة، فإذا بها قد أخرجت ساقًا تشعب منها سبع شعب، لكل واحدة سنبلة، في كل سنبلة مائة حبة. والله يضاعف الأجر لمن يشاء، بحسب ما يقوم بقلب المنفق من الإيمان والإخلاص التام. وفضل الله واسع، وهو سبحانه عليم بمن يستحقه، مطلع على نيات عباده.", "isBasmala": false, "translation_en": "The parable of those who spend their wealth in God's way is that of a grain that produces seven spikes; in each spike is a hundred grains. God multiplies for whom He wills. God is Bounteous and Knowing.", "translation_id": "Perumpamaan (nafkah yang dikeluarkan oleh) orang-orang yang menafkahkan hartanya di jalan Allah adalah serupa dengan sebutir benih yang menumbuhkan tujuh bulir, pada tiap-tiap bulir seratus biji. Allah melipat gandakan (ganjaran) bagi siapa yang Dia kehendaki. Dan Allah Maha Luas (karunia-Nya) lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 262, "text": "ٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰلَهُمۡ فِی سَبِیلِ ٱللَّهِ ثُمَّ لَا یُتۡبِعُونَ مَاۤ أَنفَقُوا۟ مَنࣰّا وَلَاۤ أَذࣰى لَّهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝٢٦٢", "juz": 3, "hizb": "(* ح 5*)", "tafsir": "الذين يخرجون أموالهم في الجهاد وأنواع الخير، ثم لا يتبعون ما أنفقوا من الخيرات مَنّاً على مَن أعطَوه ولا أذى بقول أو فِعْلٍ يشعره بالتفضل عليه، لهم ثوابهم العظيم عند ربهم، ولا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على شيء فاتهم في هذه الدنيا.", "isBasmala": false, "translation_en": "Those who spend their wealth in the way of God, and then do not follow up what they spent with reminders of their generosity or with insults, will have their reward with their Lord-they have nothing to fear, nor shall they grieve.", "translation_id": "Orang-orang yang menafkahkan hartanya di jalan Allah, kemudian mereka tidak mengiringi apa yang dinafkahkannya itu dengan menyebut-nyebut pemberiannya dan dengan tidak menyakiti (perasaan si penerima), mereka memperoleh pahala di sisi Tuhan mereka. Tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 263, "text": "۞ قَوۡلࣱ مَّعۡرُوفࣱ وَمَغۡفِرَةٌ خَیۡرࣱ مِّن صَدَقَةࣲ یَتۡبَعُهَاۤ أَذࣰىۗ وَٱللَّهُ غَنِیٌّ حَلِیمࣱ ۝٢٦٣", "juz": 3, "hizb": "(*¼ ح 5*)", "tafsir": "كلام طيب وعفو عما بدر مِن السائل مِن إلحافٍ في السؤال، خير من صدقة يتبعها من المتصدق أذى وإساءة. والله غني عن صدقات العباد، حليم لا يعاجلهم بالعقوبة.", "isBasmala": false, "translation_en": "Kind words and forgiveness are better than charity followed by insults. God is Rich and Clement.", "translation_id": "Perkataan yang baik dan pemberian maaf lebih baik dari sedekah yang diiringi dengan sesuatu yang menyakitkan (perasaan si penerima). Allah Maha Kaya lagi Maha Penyantun.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 264, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُبۡطِلُوا۟ صَدَقَـٰتِكُم بِٱلۡمَنِّ وَٱلۡأَذَىٰ كَٱلَّذِی یُنفِقُ مَالَهُۥ رِئَاۤءَ ٱلنَّاسِ وَلَا یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۖ فَمَثَلُهُۥ كَمَثَلِ صَفۡوَانٍ عَلَیۡهِ تُرَابࣱ فَأَصَابَهُۥ وَابِلࣱ فَتَرَكَهُۥ صَلۡدࣰاۖ لَّا یَقۡدِرُونَ عَلَىٰ شَیۡءࣲ مِّمَّا كَسَبُوا۟ۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡكَـٰفِرِینَ ۝٢٦٤", "juz": 3, "hizb": "(*¼ ح 5*)", "tafsir": "يا من آمنتم بالله واليوم الآخر لا تُذْهِبُوا ثواب ما تتصدقون به بالمنِّ والأذى، فهذا شبيه بالذي يخرج ماله ليراه الناس، فيُثنوا عليه، وهو لا يؤمن بالله ولا يوقن باليوم الآخر، فمثل ذلك مثل حجر أملس عليه تراب هطل عليه مطر غزير فأزاح عنه التراب، فتركه أملس لا شيء عليه، فكذلك هؤلاء المراؤون تضمحلُّ أعمالهم عند الله، ولا يجدون شيئًا من الثواب على ما أنفقوه. والله لا يوفق الكافرين لإصابة الحق في نفقاتهم وغيرها.", "isBasmala": false, "translation_en": "O you who believe! Do not nullify your charitable deeds with reminders and hurtful words, like him who spends his wealth to be seen by the people, and does not believe in God and the Last Day. His likeness is that of a smooth rock covered with soil: a downpour strikes it, and leaves it bare-they gain nothing from their efforts. God does not guide the disbelieving people.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu menghilangkan (pahala) sedekahmu dengan menyebut-nyebutnya dan menyakiti (perasaan si penerima), seperti orang yang menafkahkan hartanya karena riya kepada manusia dan dia tidak beriman kepada Allah dan hari kemudian. Maka perumpamaan orang itu seperti batu licin yang di atasnya ada tanah, kemudian batu itu ditimpa hujan lebat, lalu menjadilah dia bersih (tidak bertanah). Mereka tidak menguasai sesuatupun dari apa yang mereka usahakan; dan Allah tidak memberi petunjuk kepada orang-orang yang kafir.", "manzil": 1, "manzil_display": ""}], "45": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 265, "text": "وَمَثَلُ ٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰلَهُمُ ٱبۡتِغَاۤءَ مَرۡضَاتِ ٱللَّهِ وَتَثۡبِیتࣰا مِّنۡ أَنفُسِهِمۡ كَمَثَلِ جَنَّةِۭ بِرَبۡوَةٍ أَصَابَهَا وَابِلࣱ فَـَٔاتَتۡ أُكُلَهَا ضِعۡفَیۡنِ فَإِن لَّمۡ یُصِبۡهَا وَابِلࣱ فَطَلࣱّۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرٌ ۝٢٦٥", "juz": 3, "hizb": "(*¼ ح 5*)", "tafsir": "ومثل الذين ينفقون أموالهم طلبًا لرضا الله واعتقادًا راسخًا بصدق وعده، كمثل بستان عظيم بأرض عالية طيبة هطلت عليه أمطار غزيرة، فتضاعفت ثمراته، وإن لم تسقط عليه الأمطار الغزيرة فيكفيه رذاذ المطر ليعطي الثمرة المضاعفة، وكذلك نفقات المخلصين تُقبل عند الله وتُضاعف، قلَّت أم كثُرت، فالله المُطَّلِع على السرائر، البصير بالظواهر والبواطن، يثيب كلا بحسب إخلاصه.", "isBasmala": false, "translation_en": "And the parable of those who spend their wealth seeking God's approval, and to strengthen their souls, is that of a garden on a hillside. If heavy rain falls on it, its produce is doubled; and if no heavy rain falls, then dew is enough. God is seeing of everything you do.", "translation_id": "Dan perumpamaan orang-orang yang membelanjakan hartanya karena mencari keridhaan Allah dan untuk keteguhan jiwa mereka, seperti sebuah kebun yang terletak di dataran tinggi yang disiram oleh hujan lebat, maka kebun itu menghasilkan buahnya dua kali lipat. Jika hujan lebat tidak menyiraminya, maka hujan gerimis (pun memadai). Dan Allah Maha Melihat apa yang kamu perbuat.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 266, "text": "أَیَوَدُّ أَحَدُكُمۡ أَن تَكُونَ لَهُۥ جَنَّةࣱ مِّن نَّخِیلࣲ وَأَعۡنَابࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ لَهُۥ فِیهَا مِن كُلِّ ٱلثَّمَرَ ٰتِ وَأَصَابَهُ ٱلۡكِبَرُ وَلَهُۥ ذُرِّیَّةࣱ ضُعَفَاۤءُ فَأَصَابَهَاۤ إِعۡصَارࣱ فِیهِ نَارࣱ فَٱحۡتَرَقَتۡۗ كَذَ ٰلِكَ یُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ ۝٢٦٦", "juz": 3, "hizb": "(*¼ ح 5*)", "tafsir": "أيرغب الواحد منكم أن يكون له بستان فيه النخيل والأعناب، تجري من تحت أشجارِه المياه العذبة، وله فيه من كل ألوان الثمرات، وقد بلغ الكِبَر، ولا يستطيع أن يغرس مثل هذا الغرس، وله أولاد صغار في حاجة إلى هذا البستان وفي هذه الحالة هبَّت عليه ريح شديدة، فيها نار محرقة فأحرقته؛ وهكذا حال غير المخلصين في نفقاتهم، يأتون يوم القيامة ولا حسنة لهم. وبمثل هذا البيان يبيِّن الله لكم ما ينفعكم؛ كي تتأملوا، فتخلصوا نفقاتكم لله.", "isBasmala": false, "translation_en": "Would anyone of you like to have a garden of palms and vines, under which rivers flow-with all kinds of fruit in it for him, and old age has stricken him, and he has weak children-then a tornado with fire batters it, and it burns down? Thus God makes clear the signs for you, so that you may reflect.", "translation_id": "Apakah ada salah seorang di antaramu yang ingin mempunyai kebun kurma dan anggur yang mengalir di bawahnya sungai-sungai; dia mempunyai dalam kebun itu segala macam buah-buahan, kemudian datanglah masa tua pada orang itu sedang dia mempunyai keturunan yang masih kecil-kecil. Maka kebun itu ditiup angin keras yang mengandung api, lalu terbakarlah. Demikianlah Allah menerangkan ayat-ayat-Nya kepada kamu supaya kamu memikirkannya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 267, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَنفِقُوا۟ مِن طَیِّبَـٰتِ مَا كَسَبۡتُمۡ وَمِمَّاۤ أَخۡرَجۡنَا لَكُم مِّنَ ٱلۡأَرۡضِۖ وَلَا تَیَمَّمُوا۟ ٱلۡخَبِیثَ مِنۡهُ تُنفِقُونَ وَلَسۡتُم بِـَٔاخِذِیهِ إِلَّاۤ أَن تُغۡمِضُوا۟ فِیهِۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ غَنِیٌّ حَمِیدٌ ۝٢٦٧", "juz": 3, "hizb": "(*¼ ح 5*)", "tafsir": "يا من آمنتم بي واتبعتم رسلي أنفقوا من الحلال الطيب الذي كسبتموه ومما أخرجنا لكم من الأرض، ولا تقصدوا الرديء منه لتعطوه الفقراء، ولو أُعطِيتموه لم تأخذوه إلا إذا تغاضيتم عما فيه من رداءة ونقص. فكيف ترضون لله ما لا ترضونه لأنفسكم؟ واعلموا أن الله الذي رزقكم غني عن صدقاتكم، مستحق للثناء، محمود في كل حال.", "isBasmala": false, "translation_en": "O you who believe! Give of the good things you have earned, and from what We have produced for you from the earth. And do not pick the inferior things to give away, when you yourselves would not accept it except with eyes closed. And know that God is Sufficient and Praiseworthy.", "translation_id": "Hai orang-orang yang beriman, nafkahkanlah (di jalan allah) sebagian dari hasil usahamu yang baik-baik dan sebagian dari apa yang Kami keluarkan dari bumi untuk kamu. Dan janganlah kamu memilih yang buruk-buruk lalu kamu menafkahkan daripadanya, padahal kamu sendiri tidak mau mengambilnya melainkan dengan memincingkan mata terhadapnya. Dan ketahuilah, bahwa Allah Maha Kaya lagi Maha Terpuji.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 268, "text": "ٱلشَّیۡطَـٰنُ یَعِدُكُمُ ٱلۡفَقۡرَ وَیَأۡمُرُكُم بِٱلۡفَحۡشَاۤءِۖ وَٱللَّهُ یَعِدُكُم مَّغۡفِرَةࣰ مِّنۡهُ وَفَضۡلࣰاۗ وَٱللَّهُ وَ ٰسِعٌ عَلِیمࣱ ۝٢٦٨", "juz": 3, "hizb": "(*¼ ح 5*)", "tafsir": "هذا البخل واختيار الرديء للصدقة من الشيطان الذي يخوفكم الفقر، ويغريكم بالبخل، ويأمركم بالمعاصي ومخالفة الله تعالى، والله سبحانه وتعالى يعدكم على إنفاقكم غفرانًا لذنوبكم ورزقا واسعا. والله واسع الفضل، عليم بالأعمال والنيَّات.", "isBasmala": false, "translation_en": "Satan promises you poverty, and urges you to immorality; but God promises you forgiveness from Himself, and grace. God is Embracing and Knowing.", "translation_id": "Syaitan menjanjikan (menakut-nakuti) kamu dengan kemiskinan dan menyuruh kamu berbuat kejahatan (kikir); sedang Allah menjadikan untukmu ampunan daripada-Nya dan karunia. Dan Allah Maha Luas (karunia-Nya) lagi Maha Mengatahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 269, "text": "یُؤۡتِی ٱلۡحِكۡمَةَ مَن یَشَاۤءُۚ وَمَن یُؤۡتَ ٱلۡحِكۡمَةَ فَقَدۡ أُوتِیَ خَیۡرࣰا كَثِیرࣰاۗ وَمَا یَذَّكَّرُ إِلَّاۤ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ ۝٢٦٩", "juz": 3, "hizb": "(*¼ ح 5*)", "tafsir": "يؤتي الله الإصابة في القول والفعل مَن يشاء من عباده، ومن أنعم الله عليه بذلك فقد أعطاه خيرًا كثيرًا. وما يتذكر هذا وينتفع به إلا أصحاب العقول المستنيرة بنور الله وهدايته.", "isBasmala": false, "translation_en": "He gives wisdom to whomever He wills. Whoever is given wisdom has been given much good. But none pays heed except those with insight.", "translation_id": "Allah menganugerahkan al hikmah (kefahaman yang dalam tentang Al Quran dan As Sunnah) kepada siapa yang dikehendaki-Nya. Dan barangsiapa yang dianugerahi hikmah, ia benar-benar telah dianugerahi karunia yang banyak. Dan hanya orang-orang yang berakallah yang dapat mengambil pelajaran (dari firman Allah).", "manzil": 1, "manzil_display": ""}], "46": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 270, "text": "وَمَاۤ أَنفَقۡتُم مِّن نَّفَقَةٍ أَوۡ نَذَرۡتُم مِّن نَّذۡرࣲ فَإِنَّ ٱللَّهَ یَعۡلَمُهُۥۗ وَمَا لِلظَّـٰلِمِینَ مِنۡ أَنصَارٍ ۝٢٧٠", "juz": 3, "hizb": "(*¼ ح 5*)", "tafsir": "وما أعطيتم من مال أو غيره كثير أو قليل تتصدقون به ابتغاء مرضات الله أو أوجبتم على أنفسكم شيئًا من مال أو غيره، فإن الله يعلمه، وهو المُطَّلِع على نياتكم، وسوف يثيبكم على ذلك. ومَن منع حق الله فهو ظالم، والظالمون ليس لهم أنصار يمنعونهم من عذاب الله.", "isBasmala": false, "translation_en": "Whatever charity you give, or a pledge you fulfill, God knows it. The wrongdoers have no helpers.", "translation_id": "Apa saja yang kamu nafkahkan atau apa saja yang kamu nazarkan, maka sesungguhnya Allah mengetahuinya. Orang-orang yang berbuat zalim tidak ada seorang penolongpun baginya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 271, "text": "إِن تُبۡدُوا۟ ٱلصَّدَقَـٰتِ فَنِعِمَّا هِیَۖ وَإِن تُخۡفُوهَا وَتُؤۡتُوهَا ٱلۡفُقَرَاۤءَ فَهُوَ خَیۡرࣱ لَّكُمۡۚ وَیُكَفِّرُ عَنكُم مِّن سَیِّـَٔاتِكُمۡۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ ۝٢٧١", "juz": 3, "hizb": "(*¼ ح 5*)", "tafsir": "إن تظهروا ما تتصدقون به لله فنِعْمَ ما تصدقتم به، وإن تسرُّوا بها، وتعطوها الفقراء فهذا أفضل لكم؛ لأنه أبعد عن الرياء، وفي الصدقة -مع الإخلاص- محو لذنوبكم. والله الذي يعلم دقائق الأمور، لا يخفى عليه شيء من أحوالكم، وسيجازي كلا بعمله.", "isBasmala": false, "translation_en": "If you give charity openly, that is good. But if you keep it secret, and give it to the needy in private, that is better for you. It will atone for some of your misdeeds. God is cognizant of what you do.", "translation_id": "Jika kamu menampakkan sedekah(mu), maka itu adalah baik sekali. Dan jika kamu menyembunyikannya dan kamu berikan kepada orang-orang fakir, maka menyembunyikan itu lebih baik bagimu. Dan Allah akan menghapuskan dari kamu sebagian kesalahan-kesalahanmu; dan Allah mengetahui apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 272, "text": "۞ لَّیۡسَ عَلَیۡكَ هُدَىٰهُمۡ وَلَـٰكِنَّ ٱللَّهَ یَهۡدِی مَن یَشَاۤءُۗ وَمَا تُنفِقُوا۟ مِنۡ خَیۡرࣲ فَلِأَنفُسِكُمۡۚ وَمَا تُنفِقُونَ إِلَّا ٱبۡتِغَاۤءَ وَجۡهِ ٱللَّهِۚ وَمَا تُنفِقُوا۟ مِنۡ خَیۡرࣲ یُوَفَّ إِلَیۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ ۝٢٧٢", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "لست -أيها الرسول- مسئولا عن توفيق الكافرين للهداية، ولكن الله يشرح صدور مَن يشاء لدينه، ويوفقه له. وما تبذلوا من مال يَعُدْ عليكم نَفْعُه من الله، والمؤمنون لا ينفقون إلا طلبًا لمرضاة الله. وما تنفقوا من مال -مخلصين لله- توفوا ثوابه، ولا تُنْقَصُوا شيئا من ذلك. وفي الآية إثبات صفة الوجه لله تعالى على ما يليق به سبحانه.", "isBasmala": false, "translation_en": "Their guidance is not your responsibility, but God guides whom He wills. Any charity you give is for your own good. Any charity you give shall be for the sake of God. Any charity you give will be repaid to you in full, and you will not be wronged.", "translation_id": "Bukanlah kewajibanmu menjadikan mereka mendapat petunjuk, akan tetapi Allah-lah yang memberi petunjuk (memberi taufiq) siapa yang dikehendaki-Nya. Dan apa saja harta yang baik yang kamu nafkahkan (di jalan allah), maka pahalanya itu untuk kamu sendiri. Dan janganlah kamu membelanjakan sesuatu melainkan karena mencari keridhaan Allah. Dan apa saja harta yang baik yang kamu nafkahkan, niscaya kamu akan diberi pahalanya dengan cukup sedang kamu sedikitpun tidak akan dianiaya (dirugikan).", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 273, "text": "لِلۡفُقَرَاۤءِ ٱلَّذِینَ أُحۡصِرُوا۟ فِی سَبِیلِ ٱللَّهِ لَا یَسۡتَطِیعُونَ ضَرۡبࣰا فِی ٱلۡأَرۡضِ یَحۡسَبُهُمُ ٱلۡجَاهِلُ أَغۡنِیَاۤءَ مِنَ ٱلتَّعَفُّفِ تَعۡرِفُهُم بِسِیمَـٰهُمۡ لَا یَسۡـَٔلُونَ ٱلنَّاسَ إِلۡحَافࣰاۗ وَمَا تُنفِقُوا۟ مِنۡ خَیۡرࣲ فَإِنَّ ٱللَّهَ بِهِۦ عَلِیمٌ ۝٢٧٣", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "اجعلوا صدقاتكم لفقراء المسلمين الذين لا يستطيعون السفر؛ طلبًا للرزق لاشتغالهم بالجهاد في سبيل الله، يظنهم مَن لا يعرفهم غير محتاجين إلى الصدقة؛ لتعففهم عن السؤال، تعرفهم بعلاماتهم وآثار الحاجة فيهم، لا يسألون الناس بالكُليَّة، وإن سألوا اضطرارًا لم يُلِحُّوا في السؤال. وما تنفقوا مِن مال في سبيل الله فلا يخفى على الله شيء منه، وسيجزي عليه أوفر الجزاء وأتمَّه يوم القيامة.", "isBasmala": false, "translation_en": "It is for the poor; those who are restrained in the way of God, and unable to travel in the land. The unaware would think them rich, due to their dignity. You will recognize them by their features. They do not ask from people insistently. Whatever charity you give, God is aware of it.", "translation_id": "(Berinfaqlah) kepada orang-orang fakir yang terikat (oleh jihad) di jalan Allah; mereka tidak dapat (berusaha) di bumi; orang yang tidak tahu menyangka mereka orang kaya karena memelihara diri dari minta-minta. Kamu kenal mereka dengan melihat sifat-sifatnya, mereka tidak meminta kepada orang secara mendesak. Dan apa saja harta yang baik yang kamu nafkahkan (di jalan Allah), maka sesungguhnya Allah Maha Mengatahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 274, "text": "ٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰلَهُم بِٱلَّیۡلِ وَٱلنَّهَارِ سِرࣰّا وَعَلَانِیَةࣰ فَلَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝٢٧٤", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "الذين يُخْرجون أموالهم مرضاة لله ليلا ونهارًا مسرِّين ومعلنين، فلهم أجرهم عند ربهم، ولا خوف عليهم فيما يستقبلونه من أمر الآخرة، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا. ذلك التشريع الإلهي الحكيم هو منهاج الإسلام في الإنفاق لما فيه مِن سدِّ حاجة الفقراء في كرامة وعزة، وتطهير مال الأغنياء، وتحقيق التعاون على البر والتقوى؛ ابتغاء وجه الله دون قهر أو إكراه.", "isBasmala": false, "translation_en": "Those who spend their wealth by night and day, privately and publicly, will receive their reward from their Lord. They have nothing to fear, nor shall they grieve.", "translation_id": "Orang-orang yang menafkahkan hartanya di malam dan di siang hari secara tersembunyi dan terang-terangan, maka mereka mendapat pahala di sisi Tuhannya. Tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.", "manzil": 1, "manzil_display": ""}], "47": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 275, "text": "ٱلَّذِینَ یَأۡكُلُونَ ٱلرِّبَوٰا۟ لَا یَقُومُونَ إِلَّا كَمَا یَقُومُ ٱلَّذِی یَتَخَبَّطُهُ ٱلشَّیۡطَـٰنُ مِنَ ٱلۡمَسِّۚ ذَ ٰلِكَ بِأَنَّهُمۡ قَالُوۤا۟ إِنَّمَا ٱلۡبَیۡعُ مِثۡلُ ٱلرِّبَوٰا۟ۗ وَأَحَلَّ ٱللَّهُ ٱلۡبَیۡعَ وَحَرَّمَ ٱلرِّبَوٰا۟ۚ فَمَن جَاۤءَهُۥ مَوۡعِظَةࣱ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمۡرُهُۥۤ إِلَى ٱللَّهِۖ وَمَنۡ عَادَ فَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٢٧٥", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "الذين يتعاملون بالربا -وهو الزيادة على رأس المال- لا يقومون في الآخرة من قبورهم إلا كما يقوم الذي يتخبطه الشيطان من الجنون؛ ذلك لأنهم قالوا: إنما البيع مثل الربا، في أن كلا منهما حلال، ويؤدي إلى زيادة المال، فأكذبهم الله، وبيَّن أنه أحل البيع وحرَّم الربا؛ لما في البيع والشراء من نفع للأفراد والجماعات، ولما في الربا من استغلال وضياع وهلاك. فمن بلغه نهي الله عن الربا فارتدع، فله ما مضى قبل أن يبلغه التحريم لا إثم عليه فيه، وأمره إلى الله فيما يستقبل من زمانه، فإن استمرَّ على توبته فالله لا يضيع أجر المحسنين، ومن عاد إلى الربا ففعله بعد بلوغه نهي الله عنه، فقد استوجب العقوبة، وقامت عليه الحجة، ولهذا قال سبحانه: (فَأُولَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ)", "isBasmala": false, "translation_en": "Those who swallow usury will not rise, except as someone driven mad by Satan's touch. That is because they say, \"Commerce is like usury.\" But God has permitted commerce, and has forbidden usury. Whoever, on receiving advice from his Lord, refrains, may keep his past earnings, and his case rests with God. But whoever resumes-these are the dwellers of the Fire, wherein they will abide forever.", "translation_id": "Orang-orang yang makan (mengambil) riba tidak dapat berdiri melainkan seperti berdirinya orang yang kemasukan syaitan lantaran (tekanan) penyakit gila. Keadaan mereka yang demikian itu, adalah disebabkan mereka berkata (berpendapat), sesungguhnya jual beli itu sama dengan riba, padahal Allah telah menghalalkan jual beli dan mengharamkan riba. Orang-orang yang telah sampai kepadanya larangan dari Tuhannya, lalu terus berhenti (dari mengambil riba), maka baginya apa yang telah diambilnya dahulu (sebelum datang larangan); dan urusannya (terserah) kepada Allah. Orang yang kembali (mengambil riba), maka orang itu adalah penghuni-penghuni neraka; mereka kekal di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 276, "text": "یَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَیُرۡبِی ٱلصَّدَقَـٰتِۗ وَٱللَّهُ لَا یُحِبُّ كُلَّ كَفَّارٍ أَثِیمٍ ۝٢٧٦", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "يذهب الله الربا كله أو يحرم صاحبه بركة ماله، فلا ينتفع به، وينمي الصدقات ويكثرها، ويضاعف الأجر للمتصدقين، ويبارك لهم في أموالهم. والله لا يحب كل مُصِرٍّ على كفره، مُسْتَحِلٍّ أكل الربا، متمادٍ في الإثم والحرام ومعاصي الله.", "isBasmala": false, "translation_en": "God condemns usury, and He blesses charities. God does not love any sinful ingrate.", "translation_id": "Allah memusnahkan riba dan menyuburkan sedekah. Dan Allah tidak menyukai setiap orang yang tetap dalam kekafiran, dan selalu berbuat dosa.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 277, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡ وَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝٢٧٧", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "إن الذين صدقوا الله ورسوله، وعملوا الأعمال الطيبة، وأدَّوا الصلاة كما أمر الله ورسوله، وأخرجوا زكاة أموالهم، لهم ثواب عظيم خاص بهم عند ربهم ورازقهم، ولا يلحقهم خوف في آخرتهم، ولا حزن على ما فاتهم من حظوظ دنياهم.", "isBasmala": false, "translation_en": "Those who believe, and do good deeds, and pray regularly, and give charity-they will have their reward with their Lord; they will have no fear, nor shall they grieve.", "translation_id": "Sesungguhnya orang-orang yang beriman, mengerjakan amal saleh, mendirikan shalat dan menunaikan zakat, mereka mendapat pahala di sisi Tuhannya. Tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 278, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِیَ مِنَ ٱلرِّبَوٰۤا۟ إِن كُنتُم مُّؤۡمِنِینَ ۝٢٧٨", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "يا من آمنتم بالله واتبعتم رسوله خافوا الله، واتركوا طلب ما بقي لكم من زيادة على رؤوس أموالكم التي كانت لكم قبل تحريم الربا، إن كنتم محققين إيمانكم قولا وعملا.", "isBasmala": false, "translation_en": "O you who believe! Fear God, and forgo what remains of usury, if you are believers.", "translation_id": "Hai orang-orang yang beriman, bertakwalah kepada Allah dan tinggalkan sisa riba (yang belum dipungut) jika kamu orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 279, "text": "فَإِن لَّمۡ تَفۡعَلُوا۟ فَأۡذَنُوا۟ بِحَرۡبࣲ مِّنَ ٱللَّهِ وَرَسُولِهِۦۖ وَإِن تُبۡتُمۡ فَلَكُمۡ رُءُوسُ أَمۡوَ ٰلِكُمۡ لَا تَظۡلِمُونَ وَلَا تُظۡلَمُونَ ۝٢٧٩", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "فإن لم ترتدعوا عما نهاكم الله عنه فاستيقنوا بحرب من الله ورسوله، وإن رجعتم إلى ربكم وتركتم أَكْلَ الربا فلكم أَخْذُ ما لكم من ديون دون زيادة، لا تَظْلمون أحدًا بأخذ ما زاد على رؤوس أموالكم، ولا يظلمكم أحد بنقص ما أقرضتم.", "isBasmala": false, "translation_en": "If you do not, then take notice of a war by God and His Messenger. But if you repent, you may keep your capital, neither wronging, nor being wronged.", "translation_id": "Maka jika kamu tidak mengerjakan (meninggalkan sisa riba), maka ketahuilah, bahwa Allah dan Rasul-Nya akan memerangimu. Dan jika kamu bertaubat (dari pengambilan riba), maka bagimu pokok hartamu; kamu tidak menganiaya dan tidak (pula) dianiaya.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 280, "text": "وَإِن كَانَ ذُو عُسۡرَةࣲ فَنَظِرَةٌ إِلَىٰ مَیۡسَرَةࣲۚ وَأَن تَصَدَّقُوا۟ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ۝٢٨٠", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "وإن كان المدين غير قادر على السداد فأمهلوه إلى أن ييسِّر الله له رزقًا فيدفع إليكم مالكم، وإن تتركوا رأس المال كله أو بعضه وتضعوه عن المدين فهو أفضل لكم، إن كنتم تعلمون فَضْلَ ذلك، وأنَّه خير لكم في الدنيا والآخرة.", "isBasmala": false, "translation_en": "But if he is in hardship, then deferment until a time of ease. But to remit it as charity is better for you, if you only knew.", "translation_id": "Dan jika (orang yang berhutang itu) dalam kesukaran, maka berilah tangguh sampai dia berkelapangan. Dan menyedekahkan (sebagian atau semua utang) itu, lebih baik bagimu, jika kamu mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 281, "text": "وَٱتَّقُوا۟ یَوۡمࣰا تُرۡجَعُونَ فِیهِ إِلَى ٱللَّهِۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ لَا یُظۡلَمُونَ ۝٢٨١", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "واحذروا -أيها الناس- يومًا ترجعون فيه إلى الله، وهو يوم القيامة، حيث تعرضون على الله ليحاسبكم، فيجازي كل واحد منكم بما عمل من خير أو شر دون أن يناله ظلم. وفي الآية إشارة إلى أن اجتناب ما حرم الله من المكاسب الربوية، تكميل للإيمان وحقوقه من إقام الصلاة وإيتاء الزكاة وعمل الصالحات.", "isBasmala": false, "translation_en": "And guard yourselves against a Day when you will be returned to God; then each soul will be rewarded fully for what it has earned, and they will not be wronged.", "translation_id": "Dan peliharalah dirimu dari (azab yang terjadi pada) hari yang pada waktu itu kamu semua dikembalikan kepada Allah. Kemudian masing-masing diri diberi balasan yang sempurna terhadap apa yang telah dikerjakannya, sedang mereka sedikitpun tidak dianiaya (dirugikan).", "manzil": 1, "manzil_display": ""}], "48": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 282, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا تَدَایَنتُم بِدَیۡنٍ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى فَٱكۡتُبُوهُۚ وَلۡیَكۡتُب بَّیۡنَكُمۡ كَاتِبُۢ بِٱلۡعَدۡلِۚ وَلَا یَأۡبَ كَاتِبٌ أَن یَكۡتُبَ كَمَا عَلَّمَهُ ٱللَّهُۚ فَلۡیَكۡتُبۡ وَلۡیُمۡلِلِ ٱلَّذِی عَلَیۡهِ ٱلۡحَقُّ وَلۡیَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا یَبۡخَسۡ مِنۡهُ شَیۡـࣰٔاۚ فَإِن كَانَ ٱلَّذِی عَلَیۡهِ ٱلۡحَقُّ سَفِیهًا أَوۡ ضَعِیفًا أَوۡ لَا یَسۡتَطِیعُ أَن یُمِلَّ هُوَ فَلۡیُمۡلِلۡ وَلِیُّهُۥ بِٱلۡعَدۡلِۚ وَٱسۡتَشۡهِدُوا۟ شَهِیدَیۡنِ مِن رِّجَالِكُمۡۖ فَإِن لَّمۡ یَكُونَا رَجُلَیۡنِ فَرَجُلࣱ وَٱمۡرَأَتَانِ مِمَّن تَرۡضَوۡنَ مِنَ ٱلشُّهَدَاۤءِ أَن تَضِلَّ إِحۡدَىٰهُمَا فَتُذَكِّرَ إِحۡدَىٰهُمَا ٱلۡأُخۡرَىٰۚ وَلَا یَأۡبَ ٱلشُّهَدَاۤءُ إِذَا مَا دُعُوا۟ۚ وَلَا تَسۡـَٔمُوۤا۟ أَن تَكۡتُبُوهُ صَغِیرًا أَوۡ كَبِیرًا إِلَىٰۤ أَجَلِهِۦۚ ذَ ٰلِكُمۡ أَقۡسَطُ عِندَ ٱللَّهِ وَأَقۡوَمُ لِلشَّهَـٰدَةِ وَأَدۡنَىٰۤ أَلَّا تَرۡتَابُوۤا۟ إِلَّاۤ أَن تَكُونَ تِجَـٰرَةً حَاضِرَةࣰ تُدِیرُونَهَا بَیۡنَكُمۡ فَلَیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَلَّا تَكۡتُبُوهَاۗ وَأَشۡهِدُوۤا۟ إِذَا تَبَایَعۡتُمۡۚ وَلَا یُضَاۤرَّ كَاتِبࣱ وَلَا شَهِیدࣱۚ وَإِن تَفۡعَلُوا۟ فَإِنَّهُۥ فُسُوقُۢ بِكُمۡۗ وَٱتَّقُوا۟ ٱللَّهَۖ وَیُعَلِّمُكُمُ ٱللَّهُۗ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ ۝٢٨٢", "juz": 3, "hizb": "(*½ ح 5*)", "tafsir": "يا من آمنتم بالله واتبعتم رسوله محمدًا صلى الله عليه وسلم إذا تعاملتم بدَيْن إلى وقت معلوم فاكتبوه؛ حفظًا للمال ودفعًا للنزاع. ولْيقُم بالكتابة رجل أمين ضابط، ولا يمتنع مَن علَّمه الله الكتابة عن ذلك، ولْيقم المدين بإملاء ما عليه من الدَّيْن، وليراقب ربه، ولا ينقص من دينه شيئا. فإن كان المدين محجورًا عليه لتبذيره وإسرافه، أو كان صغيرًا أو مجنونًا، أو لا يستطيع النطق لخرس به أو عدم قدرة كاملة على الكلام، فليتولَّ الإملاء عن المدين القائم بأمره، واطلبوا شهادة رجلين مسلمَيْن بالِغَيْن عاقلَيْن من أهل العدالة. فإن لم يوجد رجلان، فاطلبوا شهادة رجل وامرأتين ترضون شهادتهم، حتى إذا نَسِيَتْ إحداهما ذكَّرتها الأخرى، وعلى الشهداء أن يجيبوا مَن دعاهم إلى الشهادة، وعليهم أداؤها إذا ما دعوا إليها، ولا تَمَلُّوا من كتابة الدَّين قليلا أو كثيرًا إلى وقته المعلوم. ذلكم أعدل في شرع الله وهديه، وأعظم عونًا على إقامة الشهادة وأدائها، وأقرب إلى نفي الشك في جنس الدَّين وقدره وأجله. لكن إن كانت المسألة مسألة بيع وشراء، بأخذ سلعة ودفع ثمنها في الحال، فلا حاجة إلى الكتابة، ويستحب الإشهاد على ذلك منعًا للنزاع والشقاق، ومن الواجب على الشاهد والكاتب أداء الشهادة على وجهها والكتابة كما أمر الله. ولا يجوز لصاحب الحق ومَن عليه الحق الإضرار بالكُتَّاب والشهود، وكذلك لا يجوز للكُتَّاب والشهود أن يضارُّوا بمن احتاج إلى كتابتهم أو شهادتهم، وإن تفعلوا ما نهيتم عنه فإنه خروج عن طاعة الله، وعاقبة ذلك حالَّة بكم. وخافوا الله في جميع ما أمركم به، ونهاكم عنه، ويعلمكم الله جميع ما يصلح دنياكم وأخراكم. والله بكل شيء عليم، فلا يخفى عليه شيء من أموركم، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "O you who believe! When you incur debt among yourselves for a certain period of time, write it down. And have a scribe write in your presence, in all fairness. And let no scribe refuse to write, as God has taught him. So let him write, and let the debtor dictate. And let him fear God, his Lord, and diminish nothing from it. But if the debtor is mentally deficient, or weak, or unable to dictate, then let his guardian dictate with honesty. And call to witness two men from among you. If two men are not available, then one man and two women whose testimony is acceptable to all-if one of them fails to remember, the other would remind her. Witnesses must not refuse when called upon. And do not think it too trivial to write down, whether small or large, including the time of repayment. That is more equitable with God, and stronger as evidence, and more likely to prevent doubt-except in the case of a spot transaction between you-then there is no blame on you if you do not write it down. And let there be witnesses whenever you conclude a contract, and let no harm be done to either scribe or witness. If you do that, it is corruption on your part. And fear God. God teaches you. God is aware of everything.", "translation_id": "Hai orang-orang yang beriman, apabila kamu bermu'amalah tidak secara tunai untuk waktu yang ditentukan, hendaklah kamu menuliskannya. Dan hendaklah seorang penulis di antara kamu menuliskannya dengan benar. Dan janganlah penulis enggan menuliskannya sebagaimana Allah mengajarkannya, meka hendaklah ia menulis, dan hendaklah orang yang berhutang itu mengimlakkan (apa yang akan ditulis itu), dan hendaklah ia bertakwa kepada Allah Tuhannya, dan janganlah ia mengurangi sedikitpun daripada hutangnya. Jika yang berhutang itu orang yang lemah akalnya atau lemah (keadaannya) atau dia sendiri tidak mampu mengimlakkan, maka hendaklah walinya mengimlakkan dengan jujur. Dan persaksikanlah dengan dua orang saksi dari orang-orang lelaki (di antaramu). Jika tak ada dua oang lelaki, maka (boleh) seorang lelaki dan dua orang perempuan dari saksi-saksi yang kamu ridhai, supaya jika seorang lupa maka yang seorang mengingatkannya. Janganlah saksi-saksi itu enggan (memberi keterangan) apabila mereka dipanggil; dan janganlah kamu jemu menulis hutang itu, baik kecil maupun besar sampai batas waktu membayarnya. Yang demikian itu, lebih adil di sisi Allah dan lebih menguatkan persaksian dan lebih dekat kepada tidak (menimbulkan) keraguanmu. (Tulislah mu'amalahmu itu), kecuali jika mu'amalah itu perdagangan tunai yang kamu jalankan di antara kamu, maka tidak ada dosa bagi kamu, (jika) kamu tidak menulisnya. Dan persaksikanlah apabila kamu berjual beli; dan janganlah penulis dan saksi saling sulit menyulitkan. Jika kamu lakukan (yang demikian), maka sesungguhnya hal itu adalah suatu kefasikan pada dirimu. Dan bertakwalah kepada Allah; Allah mengajarmu; dan Allah Maha Mengetahui segala sesuatu.", "manzil": 1, "manzil_display": ""}], "49": [{"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 283, "text": "۞ وَإِن كُنتُمۡ عَلَىٰ سَفَرࣲ وَلَمۡ تَجِدُوا۟ كَاتِبࣰا فَرِهَـٰنࣱ مَّقۡبُوضَةࣱۖ فَإِنۡ أَمِنَ بَعۡضُكُم بَعۡضࣰا فَلۡیُؤَدِّ ٱلَّذِی ٱؤۡتُمِنَ أَمَـٰنَتَهُۥ وَلۡیَتَّقِ ٱللَّهَ رَبَّهُۥۗ وَلَا تَكۡتُمُوا۟ ٱلشَّهَـٰدَةَۚ وَمَن یَكۡتُمۡهَا فَإِنَّهُۥۤ ءَاثِمࣱ قَلۡبُهُۥۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِیمࣱ ۝٢٨٣", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "وإن كنتم مسافرين ولم تجدوا مَن يكتب لكم فادفعوا إلى صاحب الحق شيئًا يكون عنده ضمانًا لحقِّه إلى أن يردَّ المدينُ ما عليه من دين، فإن وثق بعضكم ببعض فلا حرج في ترك الكتابة والإشهاد والرهن، ويبقى الدَّين أمانة في ذمَّة المدين، عليه أداؤه، وعليه أن يراقب الله فلا يخون صاحبه. فإن أنكر المدين ما عليه من دين، وكان هناك مَن حضر وشهد، فعليه أن يظهر شهادته، ومن أخفى هذه الشهادة فهو صاحب قلب غادر فاجر. والله المُطَّلِع على السرائر، المحيط علمه بكل أموركم، سيحاسبكم على ذلك.", "isBasmala": false, "translation_en": "If you are on a journey, and cannot find a scribe, then a security deposit should be handed over. But if you trust one another, let the trustee fulfill his trust, and let him fear God, his Lord. And do not conceal testimony. Whoever conceals it is sinner at heart. God is aware of what you do.", "translation_id": "Jika kamu dalam perjalanan (dan bermu'amalah tidak secara tunai) sedang kamu tidak memperoleh seorang penulis, maka hendaklah ada barang tanggungan yang dipegang (oleh yang berpiutang). Akan tetapi jika sebagian kamu mempercayai sebagian yang lain, maka hendaklah yang dipercayai itu menunaikan amanatnya (hutangnya) dan hendaklah ia bertakwa kepada Allah Tuhannya; dan janganlah kamu (para saksi) menyembunyikan persaksian. Dan barangsiapa yang menyembunyikannya, maka sesungguhnya ia adalah orang yang berdosa hatinya; dan Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 284, "text": "لِّلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۗ وَإِن تُبۡدُوا۟ مَا فِیۤ أَنفُسِكُمۡ أَوۡ تُخۡفُوهُ یُحَاسِبۡكُم بِهِ ٱللَّهُۖ فَیَغۡفِرُ لِمَن یَشَاۤءُ وَیُعَذِّبُ مَن یَشَاۤءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝٢٨٤", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "لله ملك السماوات والأرض وما فيهما ملكًا وتدبيرًا وإحاطة، لا يخفى عليه شيء. وما تظهروه مما في أنفسكم أو تخفوه فإن الله يعلمه، وسيحاسبكم به، فيعفو عمن يشاء، ويؤاخذ من يشاء. والله قادر على كل شيء، وقد أكرم الله المسلمين بعد ذلك فعفا عن حديث النفس وخطرات القلب ما لم يتبعها كلام أو عمل، كما ثبت ذلك عن رسول الله صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "To God belongs everything in the heavens and the earth. Whether you reveal what is within your selves, or conceal it, God will call you to account for it. He forgives whom He wills, and He punishes whom He wills. God is Able to do all things.", "translation_id": "Kepunyaan Allah-lah segala apa yang ada di langit dan apa yang ada di bumi. Dan jika kamu melahirkan apa yang ada di dalam hatimu atau kamu menyembunyikan, niscaya Allah akan membuat perhitungan dengan kamu tentang perbuatanmu itu. Maka Allah mengampuni siapa yang dikehendaki-Nya dan menyiksa siapa yang dikehendaki-Nya; dan Allah Maha Kuasa atas segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 285, "text": "ءَامَنَ ٱلرَّسُولُ بِمَاۤ أُنزِلَ إِلَیۡهِ مِن رَّبِّهِۦ وَٱلۡمُؤۡمِنُونَۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰۤىِٕكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَیۡنَ أَحَدࣲ مِّن رُّسُلِهِۦۚ وَقَالُوا۟ سَمِعۡنَا وَأَطَعۡنَاۖ غُفۡرَانَكَ رَبَّنَا وَإِلَیۡكَ ٱلۡمَصِیرُ ۝٢٨٥", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "صدَّق وأيقن رسول الله محمد صلى الله عليه وسلم بما أوحي إليه من ربه وحُقَّ له أن يُوقن، والمؤمنون كذلك صدقوا وعملوا بالقرآن العظيم، كل منهم صدَّق بالله رباً وإلهًا متصفًا بصفات الجلال والكمال، وأن لله ملائكة كرامًا، وأنه أنزل كتبًا، وأرسل إلى خلقه رسلا لا نؤمن -نحن المؤمنين- ببعضهم وننكر بعضهم، بل نؤمن بهم جميعًا. وقال الرسول والمؤمنون: سمعنا يا ربنا ما أوحيت به، وأطعنا في كل ذلك، نرجو أن تغفر -بفضلك- ذنوبنا، فأنت الذي ربَّيتنا بما أنعمت به علينا، وإليك -وحدك- مرجعنا ومصيرنا.", "isBasmala": false, "translation_en": "The Messenger has believed in what was revealed to him from his Lord, as did the believers. They all have believed in God, and His angels, and His scriptures, and His messengers: \"We make no distinction between any of His messengers.\" And they say, \"We hear and we obey. Your forgiveness, our Lord. To you is the destiny.\"", "translation_id": "Rasul telah beriman kepada Al Quran yang diturunkan kepadanya dari Tuhannya, demikian pula orang-orang yang beriman. Semuanya beriman kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya dan rasul-rasul-Nya. (Mereka mengatakan): \"Kami tidak membeda-bedakan antara seseorangpun (dengan yang lain) dari rasul-rasul-Nya\", dan mereka mengatakan: \"Kami dengar dan kami taat\". (Mereka berdoa): \"Ampunilah kami ya Tuhan kami dan kepada Engkaulah tempat kembali\".", "manzil": 1, "manzil_display": ""}, {"sura": 2, "sura_name": "البقرة", "revelation": "Madaniyah", "aya": 286, "text": "لَا یُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَیۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَاۤ إِن نَّسِینَاۤ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَیۡنَاۤ إِصۡرࣰا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِینَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۤۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ ۝٢٨٦", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "دين الله يسر لا مشقة فيه، فلا يطلب الله مِن عباده ما لا يطيقونه، فمن فعل خيرًا نال خيرًا، ومن فعل شرّاً نال شرّاً. ربنا لا تعاقبنا إن نسينا شيئًا مما افترضته علينا، أو أخطأنا في فِعْل شيء نهيتنا عن فعله، ربَّنا ولا تكلفنا من الأعمال الشاقة ما كلفته مَن قبلنا من العصاة عقوبة لهم، ربنا ولا تُحَمِّلْنَا ما لا نستطيعه من التكاليف والمصائب، وامح ذنوبنا، واستر عيوبنا، وأحسن إلينا، أنت مالك أمرنا ومدبره، فانصرنا على مَن جحدوا دينك وأنكروا وحدانيتك، وكذَّبوا نبيك محمدًا صلى الله عليه وسلم، واجعل العاقبة لنا عليهم في الدنيا والآخرة.", "isBasmala": false, "translation_en": "God does not burden any soul beyond its capacity. To its credit is what it earns, and against it is what it commits. \"Our Lord, do not condemn us if we forget or make a mistake. Our Lord, do not burden us as You have burdened those before us. Our Lord, do not burden us with more than we have strength to bear; and pardon us, and forgive us, and have mercy on us. You are our Lord and Master, so help us against the disbelieving people.\"", "translation_id": "Allah tidak membebani seseorang melainkan sesuai dengan kesanggupannya. Ia mendapat pahala (dari kebajikan) yang diusahakannya dan ia mendapat siksa (dari kejahatan) yang dikerjakannya. (Mereka berdoa): \"Ya Tuhan kami, janganlah Engkau hukum kami jika kami lupa atau kami tersalah. Ya Tuhan kami, janganlah Engkau bebankan kepada kami beban yang berat sebagaimana Engkau bebankan kepada orang-orang sebelum kami. Ya Tuhan kami, janganlah Engkau pikulkan kepada kami apa yang tak sanggup kami memikulnya. Beri maaflah kami; ampunilah kami; dan rahmatilah kami. Engkaulah Penolong kami, maka tolonglah kami terhadap kaum yang kafir\".", "manzil": 1, "manzil_display": ""}], "50": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 4, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 1, "text": "الۤمۤ ۝١", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "سبق الكلام عليها في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Meem.", "translation_id": "Alif laam miim.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 2, "text": "ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡحَیُّ ٱلۡقَیُّومُ ۝٢", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "هو الله، لا معبود بحق إلا هو، المتصف بالحياة الكاملة كما يليق بجلاله، القائم على كل شيء.", "isBasmala": false, "translation_en": "God, there is no god but He, the Living, the Eternal.", "translation_id": "Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia. Yang hidup kekal lagi terus menerus mengurus makhluk-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 3, "text": "نَزَّلَ عَلَیۡكَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ وَأَنزَلَ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَ ۝٣", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "نَزَّل عليك القرآن بالحق الذي لا ريب فيه، مصدِّقًا لما قبله من كتب ورسل، وأنزل التوراة على موسى علبه السلام، والإنجيل على عيسى عليه السلام من قبل نزول القرآن؛ لإرشاد المتقين إلى الإيمان، وصلاح دينهم ودنياهم، وأنزل ما يفرق بين الحق والباطل. والذين كفروا بآيات الله المنزلة، لهم عذاب عظيم. والله عزيز لا يُغَالَب، ذو انتقام بمن جحد حججه وأدلته، وتفرُّده بالألوهية.", "isBasmala": false, "translation_en": "He sent down to you the Book with the Truth, confirming what came before it; and He sent down the Torah and the Gospel.", "translation_id": "Dia menurunkan Al Kitab (Al Quran) kepadamu dengan sebenarnya; membenarkan kitab yang telah diturunkan sebelumnya dan menurunkan Taurat dan Injil,", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 4, "text": "مِن قَبۡلُ هُدࣰى لِّلنَّاسِ وَأَنزَلَ ٱلۡفُرۡقَانَۗ إِنَّ ٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ ٱللَّهِ لَهُمۡ عَذَابࣱ شَدِیدࣱۗ وَٱللَّهُ عَزِیزࣱ ذُو ٱنتِقَامٍ ۝٤", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "نَزَّل عليك القرآن بالحق الذي لا ريب فيه، مصدِّقًا لما قبله من كتب ورسل، وأنزل التوراة على موسى علبه السلام، والإنجيل على عيسى عليه السلام من قبل نزول القرآن؛ لإرشاد المتقين إلى الإيمان، وصلاح دينهم ودنياهم، وأنزل ما يفرق بين الحق والباطل. والذين كفروا بآيات الله المنزلة، لهم عذاب عظيم. والله عزيز لا يُغَالَب، ذو انتقام بمن جحد حججه وأدلته، وتفرُّده بالألوهية.", "isBasmala": false, "translation_en": "Aforetime, as guidance for mankind; and He sent down the Criterion. Those who have rejected God's signs will have a severe punishment. God is Mighty, Able to take revenge.", "translation_id": "sebelum (Al Quran), menjadi petunjuk bagi manusia, dan Dia menurunkan Al Furqaan. Sesungguhnya orang-orang yang kafir terhadap ayat-ayat Allah akan memperoleh siksa yang berat; dan Allah Maha Perkasa lagi mempunyai balasan (siksa).", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 5, "text": "إِنَّ ٱللَّهَ لَا یَخۡفَىٰ عَلَیۡهِ شَیۡءࣱ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَاۤءِ ۝٥", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "إن الله محيط علمه بالخلائق، لا يخفى عليه شيء في الأرض ولا في السماء، قلَّ أو كثر.", "isBasmala": false, "translation_en": "Nothing is hidden from God, on earth or in the heaven.", "translation_id": "Sesungguhnya bagi Allah tidak ada satupun yang tersembunyi di bumi dan tidak (pula) di langit.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 6, "text": "هُوَ ٱلَّذِی یُصَوِّرُكُمۡ فِی ٱلۡأَرۡحَامِ كَیۡفَ یَشَاۤءُۚ لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٦", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "هو وحده الذي يخلقكم في أرحام أمهاتكم كما يشاء، من ذكر وأنثى، وحسن وقبيح، وشقي وسعيد، لا معبود بحق سواه، العزيز الذي لا يُغالَب، الحكيم في أمره وتدبيره.", "isBasmala": false, "translation_en": "It is He who forms you in the wombs as He wills. There is no god except He, the Almighty, the Wise.", "translation_id": "Dialah yang membentuk kamu dalam rahim sebagaimana dikehendaki-Nya. Tak ada Tuhan (yang berhak disembah) melainkan Dia, Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 7, "text": "هُوَ ٱلَّذِیۤ أَنزَلَ عَلَیۡكَ ٱلۡكِتَـٰبَ مِنۡهُ ءَایَـٰتࣱ مُّحۡكَمَـٰتٌ هُنَّ أُمُّ ٱلۡكِتَـٰبِ وَأُخَرُ مُتَشَـٰبِهَـٰتࣱۚ فَأَمَّا ٱلَّذِینَ فِی قُلُوبِهِمۡ زَیۡغࣱ فَیَتَّبِعُونَ مَا تَشَـٰبَهَ مِنۡهُ ٱبۡتِغَاۤءَ ٱلۡفِتۡنَةِ وَٱبۡتِغَاۤءَ تَأۡوِیلِهِۦۖ وَمَا یَعۡلَمُ تَأۡوِیلَهُۥۤ إِلَّا ٱللَّهُۘ وَٱلرَّ ٰسِخُونَ فِی ٱلۡعِلۡمِ یَقُولُونَ ءَامَنَّا بِهِۦ كُلࣱّ مِّنۡ عِندِ رَبِّنَاۚ وَمَا یَذَّكَّرُ إِلَّاۤ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ ۝٧", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "هو وحده الذي أنزل عليك القرآن: منه آيات واضحات الدلالة، هن أصل الكتاب الذي يُرجع إليه عند الاشتباه، ويُرَدُّ ما خالفه إليه، ومنه آيات أخر متشابهات تحتمل بعض المعاني، لا يتعيَّن المراد منها إلا بضمها إلى المحكم، فأصحاب القلوب المريضة الزائغة، لسوء قصدهم يتبعون هذه الآيات المتشابهات وحدها؛ ليثيروا الشبهات عند الناس، كي يضلوهم، ولتأويلهم لها على مذاهبهم الباطلة. ولا يعلم حقيقة معاني هذه الآيات إلا الله. والمتمكنون في العلم يقولون: آمنا بهذا القرآن، كله قد جاءنا من عند ربنا على لسان رسوله محمد صلى الله عليه وسلم، ويردُّون متشابهه إلى محكمه، وإنما يفهم ويعقل ويتدبر المعاني على وجهها الصحيح أولو العقول السليمة.", "isBasmala": false, "translation_en": "It is He who revealed to you the Book. Some of its verses are definitive; they are the foundation of the Book, and others are unspecific. As for those in whose hearts is deviation, they follow the unspecific part, seeking descent, and seeking to derive an interpretation. But none knows its interpretation except God and those firmly rooted in knowledge say, \"We believe in it; all is from our Lord.\" But none recollects except those with understanding.", "translation_id": "Dialah yang menurunkan Al Kitab (Al Quran) kepada kamu. Di antara (isi)nya ada ayat-ayat yang muhkamaat, itulah pokok-pokok isi Al qur'an dan yang lain (ayat-ayat) mutasyaabihaat. Adapun orang-orang yang dalam hatinya condong kepada kesesatan, maka mereka mengikuti sebahagian ayat-ayat yang mutasyaabihaat daripadanya untuk menimbulkan fitnah untuk mencari-cari ta'wilnya, padahal tidak ada yang mengetahui ta'wilnya melainkan Allah. Dan orang-orang yang mendalam ilmunya berkata: \"Kami beriman kepada ayat-ayat yang mutasyaabihaat, semuanya itu dari sisi Tuhan kami\". Dan tidak dapat mengambil pelajaran (daripadanya) melainkan orang-orang yang berakal.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 8, "text": "رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَیۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ۝٨", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "ويقولون: يا ربنا لا تَصْرِف قلوبنا عن الإيمان بك بعد أن مننت علينا بالهداية لدينك، وامنحنا من فضلك رحمة واسعة، إنك أنت الوهاب: كثير الفضل والعطاء، تعطي مَن تشاء بغير حساب.", "isBasmala": false, "translation_en": "\"Our Lord, do not cause our hearts to swerve after You have guided us, and bestow on us mercy from Your presence; You are the Giver.\"", "translation_id": "(Mereka berdoa): \"Ya Tuhan kami, janganlah Engkau jadikan hati kami condong kepada kesesatan sesudah Engkau beri petunjuk kepada kami, dan karuniakanlah kepada kami rahmat dari sisi Engkau; karena sesungguhnya Engkau-lah Maha Pemberi (karunia)\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 9, "text": "رَبَّنَاۤ إِنَّكَ جَامِعُ ٱلنَّاسِ لِیَوۡمࣲ لَّا رَیۡبَ فِیهِۚ إِنَّ ٱللَّهَ لَا یُخۡلِفُ ٱلۡمِیعَادَ ۝٩", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "يا ربنا إنا نُقِرُّ ونشهد بأنك ستجمع الناس في يوم لا شَكَّ فيه، وهو يوم القيامة، إنَّك لا تُخلف ما وعَدْتَ به عبادك.", "isBasmala": false, "translation_en": "\"Our Lord, You will gather the people for a Day in which there is no doubt.\" God will never break His promise.", "translation_id": "\"Ya Tuhan kami, sesungguhnya Engkau mengumpulkan manusia untuk (menerima pembalasan pada) hari yang tak ada keraguan padanya\". Sesungguhnya Allah tidak menyalahi janji.", "manzil": 1, "manzil_display": ""}], "51": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 10, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ لَن تُغۡنِیَ عَنۡهُمۡ أَمۡوَ ٰلُهُمۡ وَلَاۤ أَوۡلَـٰدُهُم مِّنَ ٱللَّهِ شَیۡـࣰٔاۖ وَأُو۟لَـٰۤىِٕكَ هُمۡ وَقُودُ ٱلنَّارِ ۝١٠", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "إن الذين جحدوا الدين الحق وأنكروه، لن تنفعهم أموالهم ولا أولادهم من عذاب الله شيئًا إن وقع بهم في الدنيا، ولن تدفعه عنهم في الآخرة، وهؤلاء هم حطب النار يوم القيامة.", "isBasmala": false, "translation_en": "As for those who disbelieve, neither their wealth nor their children will avail them anything against God. These will be fuel for the Fire.", "translation_id": "Sesungguhnya orang-orang yang kafir, harta benda dan anak-anak mereka, sedikitpun tidak dapat menolak (siksa) Allah dari mereka. Dan mereka itu adalah bahan bakar api neraka,", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 11, "text": "كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَذَّبُوا۟ بِـَٔایَـٰتِنَا فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۗ وَٱللَّهُ شَدِیدُ ٱلۡعِقَابِ ۝١١", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "شأن الكافرين في تكذيبهم وما ينزل بهم، شأن آل فرعون والذين من قبلهم من الكافرين، أنكروا آيات الله الواضحة، فعاجلهم بالعقوبة بسبب تكذيبهم وعنادهم. والله شديد العقاب لمن كفر به وكذَّب رسله.", "isBasmala": false, "translation_en": "Like the behavior of Pharaoh's people and those before them. They rejected Our signs, so God seized them for their sins. God is Strict in retribution.", "translation_id": "(keadaan mereka) adalah sebagai keadaan kaum Fir'aun dan orang-orang yang sebelumnya; mereka mendustakan ayat-ayat Kami; karena itu Allah menyiksa mereka disebabkan dosa-dosa mereka. Dan Allah sangat keras siksa-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 12, "text": "قُل لِّلَّذِینَ كَفَرُوا۟ سَتُغۡلَبُونَ وَتُحۡشَرُونَ إِلَىٰ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمِهَادُ ۝١٢", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "قل -أيها الرسول-، للذين كفروا من اليهود وغيرهم والذين استهانوا بنصرك في \"بَدْر\": إنكم ستُهْزَمون في الدنيا وستموتون على الكفر، وتحشرون إلى نار جهنم؛ لتكون فراشًا دائمًا لكم، وبئس الفراش.", "isBasmala": false, "translation_en": "Say to those who disbelieve, \"You will be defeated, and rounded up into Hell-an awful resting-place.\"", "translation_id": "Katakanlah kepada orang-orang yang kafir: \"Kamu pasti akan dikalahkan (di dunia ini) dan akan digiring ke dalam neraka Jahannam. Dan itulah tempat yang seburuk-buruknya\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 13, "text": "قَدۡ كَانَ لَكُمۡ ءَایَةࣱ فِی فِئَتَیۡنِ ٱلۡتَقَتَاۖ فِئَةࣱ تُقَـٰتِلُ فِی سَبِیلِ ٱللَّهِ وَأُخۡرَىٰ كَافِرَةࣱ یَرَوۡنَهُم مِّثۡلَیۡهِمۡ رَأۡیَ ٱلۡعَیۡنِۚ وَٱللَّهُ یُؤَیِّدُ بِنَصۡرِهِۦ مَن یَشَاۤءُۚ إِنَّ فِی ذَ ٰلِكَ لَعِبۡرَةࣰ لِّأُو۟لِی ٱلۡأَبۡصَـٰرِ ۝١٣", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "قد كان لكم -أيها اليهود المتكبرون المعاندون- دلالة عظيمة في جماعتين تقابلتا في معركة \"بَدْر\": جماعة تقاتل من أجل دين الله، وهم محمد صلى الله عليه وسلم وأصحابه، وجماعة أخرى كافرة بالله، تقاتل من أجل الباطل، ترى المؤمنين في العدد مثليهم رأي العين، وقد جعل الله ذلك سببًا لنصر المسلمين عليهم. والله يؤيِّد بنصره من يشاء من عباده. إن في هذا الذي حدث لَعِظة عظيمة لأصحاب البصائر الذين يهتدون إلى حكم الله وأفعاله.", "isBasmala": false, "translation_en": "There was a sign for you in the two parties that met. One party fighting in the way of God, and the other was disbelieving. They saw them with their own eyes twice their number. But God supports with His help whomever He wills. In that is a lesson for those with insight.", "translation_id": "Sesungguhnya telah ada tanda bagi kamu pada dua golongan yang telah bertemu (bertempur). Segolongan berperang di jalan Allah dan (segolongan) yang lain kafir yang dengan mata kepala melihat (seakan-akan) orang-orang muslimin dua kali jumlah mereka. Allah menguatkan dengan bantuan-Nya siapa yang dikehendaki-Nya. Sesungguhnya pada yang demikian itu terdapat pelajaran bagi orang-orang yang mempunyai mata hati.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 14, "text": "زُیِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَ ٰتِ مِنَ ٱلنِّسَاۤءِ وَٱلۡبَنِینَ وَٱلۡقَنَـٰطِیرِ ٱلۡمُقَنطَرَةِ مِنَ ٱلذَّهَبِ وَٱلۡفِضَّةِ وَٱلۡخَیۡلِ ٱلۡمُسَوَّمَةِ وَٱلۡأَنۡعَـٰمِ وَٱلۡحَرۡثِۗ ذَ ٰلِكَ مَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلۡمَـَٔابِ ۝١٤", "juz": 3, "hizb": "(*¾ ح 5*)", "tafsir": "حُسِّن للناس حبُّ الشهوات من النساء والبنين، والأموال الكثيرة من الذهب والفضة، والخيل الحسان، والأنعام من الإبل والبقر والغنم، والأرض المتَّخَذة للغراس والزراعة. ذلك زهرة الحياة الدنيا وزينتها الفانية. والله عنده حسن المرجع والثواب، وهو الجنَّة.", "isBasmala": false, "translation_en": "Adorned for the people is the love of desires, such as women, and children, and piles upon piles of gold and silver, and branded horses, and livestock, and fields. These are the conveniences of the worldly life, but with God lies the finest resort.", "translation_id": "Dijadikan indah pada (pandangan) manusia kecintaan kepada apa-apa yang diingini, yaitu: wanita-wanita, anak-anak, harta yang banyak dari jenis emas, perak, kuda pilihan, binatang-binatang ternak dan sawah ladang. Itulah kesenangan hidup di dunia, dan di sisi Allah-lah tempat kembali yang baik (surga).", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 15, "text": "۞ قُلۡ أَؤُنَبِّئُكُم بِخَیۡرࣲ مِّن ذَ ٰلِكُمۡۖ لِلَّذِینَ ٱتَّقَوۡا۟ عِندَ رَبِّهِمۡ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا وَأَزۡوَ ٰجࣱ مُّطَهَّرَةࣱ وَرِضۡوَ ٰنࣱ مِّنَ ٱللَّهِۗ وَٱللَّهُ بَصِیرُۢ بِٱلۡعِبَادِ ۝١٥", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "قل -أيها الرسول-: أأخبركم بخير مما زُيِّن للنَّاس في هذه الحياة الدنيا، لمن راقب الله وخاف عقابه جنات تجري من تحت قصورها وأشجارها الأنهار، خالدين فيها، ولهم فيها أزواج مطهرات من الحيض والنفاس وسوء الخلق، ولهم أعظم من ذلك: رضوان من الله. والله مطَّلِع على سرائر خلقه، عالم بأحوالهم، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "Say, \"Shall I inform you of something better than that? For those who are righteous, with their Lord are Gardens beneath which rivers flow, where they will remain forever, and purified spouses, and acceptance from God.\" God is Observant of the servants.", "translation_id": "Katakanlah: \"Inginkah aku kabarkan kepadamu apa yang lebih baik dari yang demikian itu?\". Untuk orang-orang yang bertakwa (kepada Allah), pada sisi Tuhan mereka ada surga yang mengalir dibawahnya sungai-sungai; mereka kekal didalamnya. Dan (mereka dikaruniai) isteri-isteri yang disucikan serta keridhaan Allah. Dan Allah Maha Melihat akan hamba-hamba-Nya.", "manzil": 1, "manzil_display": ""}], "52": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 16, "text": "ٱلَّذِینَ یَقُولُونَ رَبَّنَاۤ إِنَّنَاۤ ءَامَنَّا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ ٱلنَّارِ ۝١٦", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "هؤلاء العباد المتقون يقولون: إننا آمنا بك، واتبعنا رسولك محمدًا صلى الله عليه وسلم، فامْحُ عنا ما اقترفناه من ذنوب، ونجنا من عذاب النار.", "isBasmala": false, "translation_en": "Those who say, \"Our Lord, we have believed, so forgive us our sins, and save us from the suffering of the Fire.\"", "translation_id": "(Yaitu) orang-orang yang berdoa: Ya Tuhan kami, sesungguhnya kami telah beriman, maka ampunilah segala dosa kami dan peliharalah kami dari siksa neraka,\"", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 17, "text": "ٱلصَّـٰبِرِینَ وَٱلصَّـٰدِقِینَ وَٱلۡقَـٰنِتِینَ وَٱلۡمُنفِقِینَ وَٱلۡمُسۡتَغۡفِرِینَ بِٱلۡأَسۡحَارِ ۝١٧", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "هم الذين اتصفوا بالصبر على الطاعات، وعن المعاصي، وعلى ما يصيبهم من أقدار الله المؤلمة، وبالصدق في الأقوال والأفعال وبالطاعة التامة، وبالإنفاق سرا وعلانية، وبالاستغفار في آخر الليل؛ لأنه مَظِنَّة القبول وإجابة الدعاء.", "isBasmala": false, "translation_en": "The patient, and the truthful, and the reverent, and the charitable, and the seekers of forgiveness at dawn.", "translation_id": "(yaitu) orang-orang yang sabar, yang benar, yang tetap taat, yang menafkahkan hartanya (di jalan Allah), dan yang memohon ampun di waktu sahur.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 18, "text": "شَهِدَ ٱللَّهُ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّا هُوَ وَٱلۡمَلَـٰۤىِٕكَةُ وَأُو۟لُوا۟ ٱلۡعِلۡمِ قَاۤىِٕمَۢا بِٱلۡقِسۡطِۚ لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝١٨", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "شهد الله أنه المتفرد بالإلهية، وقَرَنَ شهادته بشهادة الملائكة وأهل العلم، على أجلِّ مشهود عليه، وهو توحيده تعالى وقيامه بالعدل، لا إله إلا هو العزيز الذي لا يمتنع عليه شيء أراده، الحكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "God bears witness that there is no god but He, as do the angels, and those endowed with knowledge-upholding justice. There is no god but He, the Mighty, the Wise.", "translation_id": "Allah menyatakan bahwasanya tidak ada Tuhan melainkan Dia (yang berhak disembah), Yang menegakkan keadilan. Para Malaikat dan orang-orang yang berilmu (juga menyatakan yang demikian itu). Tak ada Tuhan melainkan Dia (yang berhak disembah), Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 19, "text": "إِنَّ ٱلدِّینَ عِندَ ٱللَّهِ ٱلۡإِسۡلَـٰمُۗ وَمَا ٱخۡتَلَفَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَاۤءَهُمُ ٱلۡعِلۡمُ بَغۡیَۢا بَیۡنَهُمۡۗ وَمَن یَكۡفُرۡ بِـَٔایَـٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ ۝١٩", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "إن الدين الذي ارتضاه الله لخلقه وأرسل به رسله، ولا يَقْبَل غيره هو الإسلام، وهو الانقياد لله وحده بالطاعة والاستسلام له بالعبودية، واتباع الرسل فيما بعثهم الله به في كل حين حتى خُتموا بمحمد صلى الله عليه وسلم، الذي لا يقبل الله مِن أحد بعد بعثته دينًا سوى الإسلام الذي أُرسل به. وما وقع الخلاف بين أهل الكتاب من اليهود والنصارى، فتفرقوا شيعًا وأحزابًا إلا من بعد ما قامت الحجة عليهم بإرسال الرسل وإنزال الكتب؛ بغيًا وحسدًا طلبًا للدنيا. ومن يجحد آيات الله المنزلة وآياته الدالة على ربوبيته وألوهيته، فإن الله سريع الحساب، وسيجزيهم بما كانوا يعملون.", "isBasmala": false, "translation_en": "Religion with God is Islam. Those to whom the Scripture was given differed only after knowledge came to them, out of envy among themselves. Whoever rejects the signs of God-God is quick to take account.", "translation_id": "Sesungguhnya agama (yang diridhai) disisi Allah hanyalah Islam. Tiada berselisih orang-orang yang telah diberi Al Kitab kecuali sesudah datang pengetahuan kepada mereka, karena kedengkian (yang ada) di antara mereka. Barangsiapa yang kafir terhadap ayat-ayat Allah maka sesungguhnya Allah sangat cepat hisab-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 20, "text": "فَإِنۡ حَاۤجُّوكَ فَقُلۡ أَسۡلَمۡتُ وَجۡهِیَ لِلَّهِ وَمَنِ ٱتَّبَعَنِۗ وَقُل لِّلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ وَٱلۡأُمِّیِّـۧنَ ءَأَسۡلَمۡتُمۡۚ فَإِنۡ أَسۡلَمُوا۟ فَقَدِ ٱهۡتَدَوا۟ۖ وَّإِن تَوَلَّوۡا۟ فَإِنَّمَا عَلَیۡكَ ٱلۡبَلَـٰغُۗ وَٱللَّهُ بَصِیرُۢ بِٱلۡعِبَادِ ۝٢٠", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "فإن جادلك -أيها الرسول- أهل الكتاب في التوحيد بعد أن أقمت الحجة عليهم فقل لهم: إنني أخلصت لله وحده فلا أشرك به أحدًا، وكذلك من اتبعني من المؤمنين، أخلصوا لله وانقادوا له. وقل لهم ولمشركي العرب وغيرهم: إن أسلمتم فأنتم على الطريق المستقيم والهدى والحق، وإن توليتم فحسابكم على الله، وليس عليَّ إلا البلاغ، وقد أبلغتكم وأقمت عليكم الحجة. والله بصير بالعباد، لا يخفى عليه من أمرهم شيء.", "isBasmala": false, "translation_en": "If they argue with you, say, \"I have surrendered myself to God, and those who follow me.\" And say to those who were given the Scripture, and to the unlearned, \"Have you surrendered?\" If they have surrendered, then they are guided; but if they turn away, then your duty is to convey. God is Seeing of the servants.", "translation_id": "Kemudian jika mereka mendebat kamu (tentang kebenaran Islam), maka katakanlah: \"Aku menyerahkan diriku kepada Allah dan (demikian pula) orang-orang yang mengikutiku\". Dan katakanlah kepada orang-orang yang telah diberi Al Kitab dan kepada orang-orang yang ummi: \"Apakah kamu (mau) masuk Islam\". Jika mereka masuk Islam, sesungguhnya mereka telah mendapat petunjuk, dan jika mereka berpaling, maka kewajiban kamu hanyalah menyampaikan (ayat-ayat Allah). Dan Allah Maha Melihat akan hamba-hamba-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 21, "text": "إِنَّ ٱلَّذِینَ یَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَیَقۡتُلُونَ ٱلنَّبِیِّـۧنَ بِغَیۡرِ حَقࣲّ وَیَقۡتُلُونَ ٱلَّذِینَ یَأۡمُرُونَ بِٱلۡقِسۡطِ مِنَ ٱلنَّاسِ فَبَشِّرۡهُم بِعَذَابٍ أَلِیمٍ ۝٢١", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "إن الذين يجحدون بالدلائل الواضحة وما جاء به المرسلون، ويقتلون أنبياء الله ظلمًا بغير حق، ويقتلون الذين يأمرون بالعدل واتباع طريق الأنبياء، فبشِّرهم بعذاب موجع.", "isBasmala": false, "translation_en": "As for those who defy God's revelations, and kill the prophets unjustly, and kill those who advocate justice among the people-promise them a painful retribution.", "translation_id": "Sesungguhnya orang-orang yang kafir kepada ayat-ayat Allah dan membunuh para nabi yang memamg tak dibenarkan dan membunuh orang-orang yang menyuruh manusia berbuat adil, maka gembirakanlah mereka bahwa mereka akan menerima siksa yg pedih.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 22, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ حَبِطَتۡ أَعۡمَـٰلُهُمۡ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِینَ ۝٢٢", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "أولئك الذين بطلت أعمالهم في الدنيا والآخرة، فلا يُقبل لهم عمل، وما لهم من ناصرٍ ينصرهم من عذاب الله.", "isBasmala": false, "translation_en": "They are those whose deeds will come to nothing, in this world and in the Hereafter; and they will have no saviors.", "translation_id": "Mereka itu adalah orang-orang yang lenyap (pahala) amal-amalnya di dunia dan akhirat, dan mereka sekali-kali tidak memperoleh penolong.", "manzil": 1, "manzil_display": ""}], "53": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 23, "text": "أَلَمۡ تَرَ إِلَى ٱلَّذِینَ أُوتُوا۟ نَصِیبࣰا مِّنَ ٱلۡكِتَـٰبِ یُدۡعَوۡنَ إِلَىٰ كِتَـٰبِ ٱللَّهِ لِیَحۡكُمَ بَیۡنَهُمۡ ثُمَّ یَتَوَلَّىٰ فَرِیقࣱ مِّنۡهُمۡ وَهُم مُّعۡرِضُونَ ۝٢٣", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "أرأيت -أيها الرسول- أعجب من حال هؤلاء اليهود الذين أتاهم الله حظا من الكتاب فعلموا أن ما جئت به هو الحق، يُدْعون إلى ما جاء في كتاب الله -وهو القرآن- ليفصل بينهم فيما اختلفوا فيه، فإن لم يوافق أهواءهم يَأْبَ كثير منهم حكم الله؛ لأن من عادتهم الإعراض عن الحق؟", "isBasmala": false, "translation_en": "Have you not considered those who were given a share of the Scripture, as they were called to the Scripture of God to arbitrate between them; then some of them turned back, and declined?", "translation_id": "Tidakkah kamu memperhatikan orang-orang yang telah diberi bahagian yaitu Al Kitab (Taurat), mereka diseru kepada kitab Allah supaya kitab itu menetapkan hukum diantara mereka; kemudian sebahagian dari mereka berpaling, dan mereka selalu membelakangi (kebenaran).", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 24, "text": "ذَ ٰلِكَ بِأَنَّهُمۡ قَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّاۤ أَیَّامࣰا مَّعۡدُودَ ٰتࣲۖ وَغَرَّهُمۡ فِی دِینِهِم مَّا كَانُوا۟ یَفۡتَرُونَ ۝٢٤", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "ذلك الانصراف عن الحق سببه اعتقاد فاسد لدى أهل الكتاب؛ بأنهم لن يعذَّبوا إلا أيامًا قليلة، وهذا الاعتقاد أدى إلى جرأتهم على الله واستهانتهم بدينه، واستمرارهم على دينهم الباطل الذي خَدَعوا به أنفسهم.", "isBasmala": false, "translation_en": "That is because they said, \"The Fire will not touch us except for a limited number of days.\" They have been misled in their religion by the lies they fabricated.", "translation_id": "Hal itu adalah karena mereka mengaku: \"Kami tidak akan disentuh oleh api neraka kecuali beberapa hari yang dapat dihitung\". Mereka diperdayakan dalam agama mereka oleh apa yang selalu mereka ada-adakan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 25, "text": "فَكَیۡفَ إِذَا جَمَعۡنَـٰهُمۡ لِیَوۡمࣲ لَّا رَیۡبَ فِیهِ وَوُفِّیَتۡ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ لَا یُظۡلَمُونَ ۝٢٥", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "فكيف يكون حالهم إذا جمعهم الله ليحاسَبوا في يوم لا شك في وقوعه -وهو يوم القيامة-، وأخذ كل واحد جزاءَ ما اكتسب، وهم لا يظلمون شيئا؟", "isBasmala": false, "translation_en": "How about when We gather them for a Day in which there is no doubt, and each soul will be paid in full for what it has earned, and they will not be wronged?", "translation_id": "Bagaimanakah nanti apabila mereka Kami kumpulkan di hari (kiamat) yang tidak ada keraguan tentang adanya. Dan disempurnakan kepada tiap-tiap diri balasan apa yang diusahakannya sedang mereka tidak dianiaya (dirugikan).", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 26, "text": "قُلِ ٱللَّهُمَّ مَـٰلِكَ ٱلۡمُلۡكِ تُؤۡتِی ٱلۡمُلۡكَ مَن تَشَاۤءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَاۤءُ وَتُعِزُّ مَن تَشَاۤءُ وَتُذِلُّ مَن تَشَاۤءُۖ بِیَدِكَ ٱلۡخَیۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٢٦", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "قل -أيها النبي متوجها إلى ربك بالدعاء-: يا مَن لك الملك كلُّه، أنت الذي تمنح الملك والمال والتمكين في الأرض مَن تشاء مِن خلقك، وتسلب الملك ممن تشاء، وتهب العزة في الدنيا والآخرة مَن تشاء، وتجعل الذلَّة على من تشاء، بيدك الخير، إنك -وحدك- على كل شيء قدير. وفي الآية إثبات لصفة اليد لله تعالى على ما يليق به سبحانه.", "isBasmala": false, "translation_en": "Say, \"O God, Owner of Sovereignty. You grant sovereignty to whom You will, and You strip sovereignty from whom you will. You honor whom you will, and You humiliate whom you will. In Your hand is all goodness. You are Capable of all things.\"", "translation_id": "Katakanlah: \"Wahai Tuhan Yang mempunyai kerajaan, Engkau berikan kerajaan kepada orang yang Engkau kehendaki dan Engkau cabut kerajaan dari orang yang Engkau kehendaki. Engkau muliakan orang yang Engkau kehendaki dan Engkau hinakan orang yang Engkau kehendaki. Di tangan Engkaulah segala kebajikan. Sesungguhnya Engkau Maha Kuasa atas segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 27, "text": "تُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَتُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِۖ وَتُخۡرِجُ ٱلۡحَیَّ مِنَ ٱلۡمَیِّتِ وَتُخۡرِجُ ٱلۡمَیِّتَ مِنَ ٱلۡحَیِّۖ وَتَرۡزُقُ مَن تَشَاۤءُ بِغَیۡرِ حِسَابࣲ ۝٢٧", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "ومن دلائل قدرتك أنك تُدخل الليل في النهار، وتُدخل النهار في الليل، فيطول هذا ويقصر ذاك، وتُخرج الحي من الميت الذي لا حياة فيه، كإخراج الزرع من الحب، والمؤمن من الكافر، وتُخرج الميت من الحي كإخراج البيض من الدجاج، وترزق من تشاء مَن خلقك بغير حساب.", "isBasmala": false, "translation_en": "\"You merge the night into the day, and You merge the day into the night; and you bring the living out of the dead, and You bring the dead out of the living; and You provide for whom you will without measure.\"", "translation_id": "Engkau masukkan malam ke dalam siang dan Engkau masukkan siang ke dalam malam. Engkau keluarkan yang hidup dari yang mati, dan Engkau keluarkan yang mati dari yang hidup. Dan Engkau beri rezeki siapa yang Engkau kehendaki tanpa hisab (batas)\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 28, "text": "لَّا یَتَّخِذِ ٱلۡمُؤۡمِنُونَ ٱلۡكَـٰفِرِینَ أَوۡلِیَاۤءَ مِن دُونِ ٱلۡمُؤۡمِنِینَۖ وَمَن یَفۡعَلۡ ذَ ٰلِكَ فَلَیۡسَ مِنَ ٱللَّهِ فِی شَیۡءٍ إِلَّاۤ أَن تَتَّقُوا۟ مِنۡهُمۡ تُقَىٰةࣰۗ وَیُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَإِلَى ٱللَّهِ ٱلۡمَصِیرُ ۝٢٨", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "ينهى الله المؤمنين أن يتخذوا الكافرين أولياء بالمحبة والنصرة من دون المؤمنين، ومَن يتولهم فقد برِئ من الله، والله برِيء منه، إلا أن تكونوا ضعافًا خائفين فقد رخَّص الله لكم في مهادنتهم اتقاء لشرهم، حتى تقوى شوكتكم، ويحذركم الله نفسه، فاتقوه وخافوه. وإلى الله وحده رجوع الخلائق للحساب والجزاء.", "isBasmala": false, "translation_en": "Believers are not to take disbelievers for friends instead of believers. Whoever does that has nothing to do with God, unless it is to protect your own selves against them. God warns you to beware of Him. To God is the destiny.", "translation_id": "Janganlah orang-orang mukmin mengambil orang-orang kafir menjadi wali dengan meninggalkan orang-orang mukmin. Barang siapa berbuat demikian, niscaya lepaslah ia dari pertolongan Allah, kecuali karena (siasat) memelihara diri dari sesuatu yang ditakuti dari mereka. Dan Allah memperingatkan kamu terhadap diri (siksa)-Nya. Dan hanya kepada Allah kembali(mu).", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 29, "text": "قُلۡ إِن تُخۡفُوا۟ مَا فِی صُدُورِكُمۡ أَوۡ تُبۡدُوهُ یَعۡلَمۡهُ ٱللَّهُۗ وَیَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٢٩", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "قل -أيها النبي- للمؤمنين: إن تكتموا ما استقر في قلوبكم من ممالاة الكافرين ونصرتهم أم تظهروا ذلك لا يَخْفَ على الله منه شيء، فإنَّ علمه محيط بكل ما في السماوات وما في الأرض، وله القدرة التامة على كل شيء.", "isBasmala": false, "translation_en": "Say, \"Whether you conceal what is in your hearts, or disclose it, God knows it.\" He knows everything in the heavens and the earth. God is Powerful over everything.", "translation_id": "Katakanlah: \"Jika kamu menyembunyikan apa yang ada dalam hatimu atau kamu melahirkannya, pasti Allah mengetahui\". Allah mengetahui apa-apa yang ada di langit dan apa-apa yang ada di bumi. Dan Allah Maha Kuasa atas segala sesuatu.", "manzil": 1, "manzil_display": ""}], "54": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 30, "text": "یَوۡمَ تَجِدُ كُلُّ نَفۡسࣲ مَّا عَمِلَتۡ مِنۡ خَیۡرࣲ مُّحۡضَرࣰا وَمَا عَمِلَتۡ مِن سُوۤءࣲ تَوَدُّ لَوۡ أَنَّ بَیۡنَهَا وَبَیۡنَهُۥۤ أَمَدَۢا بَعِیدࣰاۗ وَیُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ ۝٣٠", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "وفي يوم القيامة يوم الجزاء تجد كل نفس ما عملت من خير ينتظرها موفرًا لتُجزَى به، وما عملت من عمل سيِّئ تجده في انتظارها أيضًا، فتتمنى لو أن بينها وبين هذا العمل زمنًا بعيدًا. فاستعدوا لهذا اليوم، وخافوا بطش الإله الجبار. ومع شدَّة عقابه فإنه سبحانه رءوف بالعباد.", "isBasmala": false, "translation_en": "On the Day when every soul finds all the good it has done presented. And as for the evil it has done, it will wish there were a great distance between them. God cautions you of Himself. God is Kind towards the servants.", "translation_id": "Pada hari ketika tiap-tiap diri mendapati segala kebajikan dihadapkan (dimukanya), begitu (juga) kejahatan yang telah dikerjakannya; ia ingin kalau kiranya antara ia dengan hari itu ada masa yang jauh; dan Allah memperingatkan kamu terhadap siksa-Nya. Dan Allah sangat Penyayang kepada hamba-hamba-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 31, "text": "قُلۡ إِن كُنتُمۡ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِی یُحۡبِبۡكُمُ ٱللَّهُ وَیَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٣١", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "قل -أيها الرسول-: إن كنتم تحبون الله حقا فاتبعوني وآمنوا بي ظاهرًا وباطنًا، يحببكم الله، ويمحُ ذنوبكم، فإنه غفور لذنوب عباده المؤمنين، رحيم بهم. وهذه الآية الكريمة حاكمة على كل من ادعى محبة الله -تعالى- وليس متبعًا لنبيه محمد صلى الله عيه وسلم حق الاتباع، مطيعًا له في أمره ونهيه، فإنه كاذب في دعواه حتى يتابع الرسول صلى الله عليه وسلم حق الاتباع.", "isBasmala": false, "translation_en": "Say, \"If you love God, then follow me, and God will love you, and will forgive you your sins.\" God is Forgiving and Merciful.", "translation_id": "Katakanlah: \"Jika kamu (benar-benar) mencintai Allah, ikutilah aku, niscaya Allah mengasihi dan mengampuni dosa-dosamu\". Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 32, "text": "قُلۡ أَطِیعُوا۟ ٱللَّهَ وَٱلرَّسُولَۖ فَإِن تَوَلَّوۡا۟ فَإِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡكَـٰفِرِینَ ۝٣٢", "juz": 3, "hizb": "(* ح 6*)", "tafsir": "قل -أيها الرسول-: أطيعوا الله باتباع كتابه، وأطيعوا الرسول باتباع سنته في حياته وبعد مماته، فإن هم أعرضوا عنك، وأصروا على ما هم عليه مِن كفر وضلال، فليسوا أهلا لمحبة الله؛ فإن الله لا يحب الكافرين.", "isBasmala": false, "translation_en": "Say, \"Obey God and the Messenger.\" But if they turn away-God does not love the faithless.", "translation_id": "Katakanlah: \"Taatilah Allah dan Rasul-Nya; jika kamu berpaling, maka sesungguhnya Allah tidak menyukai orang-orang kafir\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 33, "text": "۞ إِنَّ ٱللَّهَ ٱصۡطَفَىٰۤ ءَادَمَ وَنُوحࣰا وَءَالَ إِبۡرَ ٰهِیمَ وَءَالَ عِمۡرَ ٰنَ عَلَى ٱلۡعَـٰلَمِینَ ۝٣٣", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "إن الله اختار آدم ونوحًا وآل إبراهيم وآل عمران، وجعلهم أفضل أهل زمانهم.", "isBasmala": false, "translation_en": "God chose Adam, and Noah, and the family of Abraham, and the family of Imran, over all mankind.", "translation_id": "Sesungguhnya Allah telah memilih Adam, Nuh, keluarga Ibrahim dan keluarga 'Imran melebihi segala umat (di masa mereka masing-masing),", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 34, "text": "ذُرِّیَّةَۢ بَعۡضُهَا مِنۢ بَعۡضࣲۗ وَٱللَّهُ سَمِیعٌ عَلِیمٌ ۝٣٤", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "هؤلاء الأنبياء والرسل سلسلة طُهْر متواصلة في الإخلاص لله وتوحيده والعمل بوحيه. والله سميع لأقوال عباده، عليم بأفعالهم، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "Offspring one of the other. God is Hearer and Knower.", "translation_id": "(sebagai) satu keturunan yang sebagiannya (turunan) dari yang lain. Dan Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 35, "text": "إِذۡ قَالَتِ ٱمۡرَأَتُ عِمۡرَ ٰنَ رَبِّ إِنِّی نَذَرۡتُ لَكَ مَا فِی بَطۡنِی مُحَرَّرࣰا فَتَقَبَّلۡ مِنِّیۤۖ إِنَّكَ أَنتَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٣٥", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "اذكر -أيها الرسول- ما كان من أمر مريم وأمها وابنها عيسى عليه السلام؛ لتردَّ بذلك على من ادعوا أُلوهية عيسى أو بنوَّته لله سبحانه، إذ قالت امرأة عمران حين حملت: يا ربِّ إني جعلت لك ما في بطني خالصا لك، لخدمة \"بيت المقدس\"، فتقبَّل مني؛ إنك أنت وحدك السميع لدعائي، العليم بنيتي.", "isBasmala": false, "translation_en": "The wife of Imran said, \"My Lord, I have vowed to You what is in my womb, dedicated, so accept from me; You are the Hearer and Knower.\"", "translation_id": "(Ingatlah), ketika isteri 'Imran berkata: \"Ya Tuhanku, sesungguhnya aku menazarkan kepada Engkau anak yang dalam kandunganku menjadi hamba yang saleh dan berkhidmat (di Baitul Maqdis). Karena itu terimalah (nazar) itu dari padaku. Sesungguhnya Engkaulah Yang Maha Mendengar lagi Maha Mengetahui\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 36, "text": "فَلَمَّا وَضَعَتۡهَا قَالَتۡ رَبِّ إِنِّی وَضَعۡتُهَاۤ أُنثَىٰ وَٱللَّهُ أَعۡلَمُ بِمَا وَضَعَتۡ وَلَیۡسَ ٱلذَّكَرُ كَٱلۡأُنثَىٰۖ وَإِنِّی سَمَّیۡتُهَا مَرۡیَمَ وَإِنِّیۤ أُعِیذُهَا بِكَ وَذُرِّیَّتَهَا مِنَ ٱلشَّیۡطَـٰنِ ٱلرَّجِیمِ ۝٣٦", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "فلما تمَّ حملها ووضعت مولودها قالت: ربِّ إني وضعتها أنثى لا تصلح للخدمة في \"بيت المقدس\" -والله أعلم بما وضَعَتْ، وسوف يجعل الله لها شأنًا- وقالت: وليس الذكر الذي أردت للخدمة كالأنثى في ذلك؛ لأن الذكر أقوى على الخدمة وأقْوَم بها، وإني سمَّيتها مريم، وإني حصَّنتها بك هي وذريَّتها من الشيطان المطرود من رحمتك.", "isBasmala": false, "translation_en": "And when she delivered her, she said, \"My Lord, I have delivered a female,\" and God was well aware of what she has delivered, \"and the male is not like the female, and I have named her Mary, and have commended her and her descendants to Your protection, from Satan the outcast.\"", "translation_id": "Maka tatkala isteri 'Imran melahirkan anaknya, diapun berkata: \"Ya Tuhanku, sesunguhnya aku melahirkannya seorang anak perempuan; dan Allah lebih mengetahui apa yang dilahirkannya itu; dan anak laki-laki tidaklah seperti anak perempuan. Sesungguhnya aku telah menamai dia Maryam dan aku mohon perlindungan untuknya serta anak-anak keturunannya kepada (pemeliharaan) Engkau daripada syaitan yang terkutuk\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 37, "text": "فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنࣲ وَأَنۢبَتَهَا نَبَاتًا حَسَنࣰا وَكَفَّلَهَا زَكَرِیَّاۖ كُلَّمَا دَخَلَ عَلَیۡهَا زَكَرِیَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقࣰاۖ قَالَ یَـٰمَرۡیَمُ أَنَّىٰ لَكِ هَـٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ یَرۡزُقُ مَن یَشَاۤءُ بِغَیۡرِ حِسَابٍ ۝٣٧", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "فاستجاب الله دعاءها وقبل منها نَذْرها أحسن قَبول، وتولَّى ابنتها مريم بالرعاية فأنبتها نباتًا حسنًا، ويسَّر الله لها زكريا عليه السلام كافلا فأسكنها في مكان عبادته، وكان كلَّما دخل عليها هذا المكان وجد عندها رزقًا هنيئًا معدّاً قال: يا مريم من أين لكِ هذا الرزق الطيب؟ قالت: هو رزق من عند الله. إن الله -بفضله- يرزق مَن يشاء مِن خلقه بغير حساب.", "isBasmala": false, "translation_en": "Her Lord accepted her with a gracious reception, and brought her a beautiful upbringing, and entrusted her to the care of Zechariah. Whenever Zechariah entered upon her in the sanctuary, he found her with provision. He said, \"O Mary, where did you get this from?\" She said, \"It is from God; God provides to whom He wills without reckoning.\"", "translation_id": "Maka Tuhannya menerimanya (sebagai nazar) dengan penerimaan yang baik, dan mendidiknya dengan pendidikan yang baik dan Allah menjadikan Zakariya pemeliharanya. Setiap Zakariya masuk untuk menemui Maryam di mihrab, ia dapati makanan di sisinya. Zakariya berkata: \"Hai Maryam dari mana kamu memperoleh (makanan) ini?\" Maryam menjawab: \"Makanan itu dari sisi Allah\". Sesungguhnya Allah memberi rezeki kepada siapa yang dikehendaki-Nya tanpa hisab.", "manzil": 1, "manzil_display": ""}], "55": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 38, "text": "هُنَالِكَ دَعَا زَكَرِیَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِی مِن لَّدُنكَ ذُرِّیَّةࣰ طَیِّبَةًۖ إِنَّكَ سَمِیعُ ٱلدُّعَاۤءِ ۝٣٨", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "عندما رأى زكريا ما أكرم الله به مريم مِن رزقه وفضله توجه إلى ربه قائلا يا ربِّ أعطني من عندك ولدًا صالحًا مباركًا، إنك سميع الدعاء لمن دعاك.", "isBasmala": false, "translation_en": "Thereupon Zechariah prayed to his Lord; he said, \"My Lord, bestow on me good offspring from Your presence; You are the Hearer of Prayers.\"", "translation_id": "Di sanalah Zakariya mendoa kepada Tuhannya seraya berkata: \"Ya Tuhanku, berilah aku dari sisi Engkau seorang anak yang baik. Sesungguhnya Engkau Maha Pendengar doa\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 39, "text": "فَنَادَتۡهُ ٱلۡمَلَـٰۤىِٕكَةُ وَهُوَ قَاۤىِٕمࣱ یُصَلِّی فِی ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ یُبَشِّرُكَ بِیَحۡیَىٰ مُصَدِّقَۢا بِكَلِمَةࣲ مِّنَ ٱللَّهِ وَسَیِّدࣰا وَحَصُورࣰا وَنَبِیࣰّا مِّنَ ٱلصَّـٰلِحِینَ ۝٣٩", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "فنادته الملائكة وهو واقف بين يدي الله في مكان صلاته يدعوه: أن الله يخبرك بخبر يسرُّك، وهو أنك سترزق بولد اسمه يحيى، يُصَدِّق بكلمة من الله -وهو عيسى ابن مريم عليه السلام-، ويكون يحيى سيدًا في قومه، له المكانة والمنزلة العالية، وحصورًا لا يأتي الذنوب والشهوات الضارة، ويكون نبيّاً من الصالحين الذين بلغوا في الصَّلاح ذروته.", "isBasmala": false, "translation_en": "Then the angels called out to him, as he stood praying in the sanctuary: \"God gives you good news of John; confirming a Word from God, and honorable, and moral, and a prophet; one of the upright.\"", "translation_id": "Kemudian Malaikat (Jibril) memanggil Zakariya, sedang ia tengah berdiri melakukan shalat di mihrab (katanya): \"Sesungguhnya Allah menggembirakan kamu dengan kelahiran (seorang puteramu) Yahya, yang membenarkan kalimat (yang datang) dari Allah, menjadi ikutan, menahan diri (dari hawa nafsu) dan seorang Nabi termasuk keturunan orang-orang saleh\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 40, "text": "قَالَ رَبِّ أَنَّىٰ یَكُونُ لِی غُلَـٰمࣱ وَقَدۡ بَلَغَنِیَ ٱلۡكِبَرُ وَٱمۡرَأَتِی عَاقِرࣱۖ قَالَ كَذَ ٰلِكَ ٱللَّهُ یَفۡعَلُ مَا یَشَاۤءُ ۝٤٠", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "قال زكريا فرحًا متعجبًا: ربِّ أنَّى يكون لي غلام مع أن الشيخوخة قد بلغت مني مبلغها، وامرأتي عقيم لا تلد؟ قال: كذلك يفعل الله ما يشاء من الأفعال العجيبة المخالفة للعادة.", "isBasmala": false, "translation_en": "He said, \"My Lord, how will I have a son, when old age has overtaken me, and my wife is barren?\" He said, \"Even so, God does whatever He wills.\"", "translation_id": "Zakariya berkata: \"Ya Tuhanku, bagaimana aku bisa mendapat anak sedang aku telah sangat tua dan isteriku pun seorang yang mandul?\". Berfirman Allah: \"Demikianlah, Allah berbuat apa yang dikehendaki-Nya\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 41, "text": "قَالَ رَبِّ ٱجۡعَل لِّیۤ ءَایَةࣰۖ قَالَ ءَایَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَـٰثَةَ أَیَّامٍ إِلَّا رَمۡزࣰاۗ وَٱذۡكُر رَّبَّكَ كَثِیرࣰا وَسَبِّحۡ بِٱلۡعَشِیِّ وَٱلۡإِبۡكَـٰرِ ۝٤١", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "قال زكريَّا: رب اجعل لي علامةً أستدلُّ بها على وجود الولد مني؛ ليحصل لي السرور والاستبشار، قال: علامتك التي طلبتها: ألا تستطيع التحدث إلى الناس ثلاثة أيام إلا بإشارة إليهم، مع أنك سويٌّ صحيح، وفي هذه المدة أكثِرْ من ذكر ربك، وصلِّ له أواخر النهار وأوائله.", "isBasmala": false, "translation_en": "He said, \"My Lord, give me a sign.\" He said, \"Your sign is that you shall not speak to the people for three days, except by gestures. And remember your Lord much, and praise in the evening and the morning.\"", "translation_id": "Berkata Zakariya: \"Berilah aku suatu tanda (bahwa isteriku telah mengandung)\". Allah berfirman: \"Tandanya bagimu, kamu tidak dapat berkata-kata dengan manusia selama tiga hari, kecuali dengan isyarat. Dan sebutlah (nama) Tuhanmu sebanyak-banyaknya serta bertasbihlah di waktu petang dan pagi hari\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 42, "text": "وَإِذۡ قَالَتِ ٱلۡمَلَـٰۤىِٕكَةُ یَـٰمَرۡیَمُ إِنَّ ٱللَّهَ ٱصۡطَفَىٰكِ وَطَهَّرَكِ وَٱصۡطَفَىٰكِ عَلَىٰ نِسَاۤءِ ٱلۡعَـٰلَمِینَ ۝٤٢", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "واذكر -أيها الرسول- حين قالت الملائكة: يا مريم إن الله اختاركِ لطاعته وطهَّركِ من الأخلاق الرذيلة، واختاركِ على نساء العالمين في زمانك.", "isBasmala": false, "translation_en": "The angels said, \"O Mary, God has chosen you, and has purified you. He has chosen you over all the women of the world.", "translation_id": "Dan (ingatlah) ketika Malaikat (Jibril) berkata: \"Hai Maryam, sesungguhnya Allah telah memilih kamu, mensucikan kamu dan melebihkan kamu atas segala wanita di dunia (yang semasa dengan kamu).", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 43, "text": "یَـٰمَرۡیَمُ ٱقۡنُتِی لِرَبِّكِ وَٱسۡجُدِی وَٱرۡكَعِی مَعَ ٱلرَّ ٰكِعِینَ ۝٤٣", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "يا مريم داومي على الطاعة لربك، وقومي في خشوع وتواضع، واسجدي واركعي مع الراكعين؛ شكرًا لله على ما أولاكِ من نعمه.", "isBasmala": false, "translation_en": "\"O Mary, be devoted to your Lord, and bow down, and kneel with those who kneel.\"", "translation_id": "Hai Maryam, taatlah kepada Tuhanmu, sujud dan ruku'lah bersama orang-orang yang ruku'.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 44, "text": "ذَ ٰلِكَ مِنۡ أَنۢبَاۤءِ ٱلۡغَیۡبِ نُوحِیهِ إِلَیۡكَۚ وَمَا كُنتَ لَدَیۡهِمۡ إِذۡ یُلۡقُونَ أَقۡلَـٰمَهُمۡ أَیُّهُمۡ یَكۡفُلُ مَرۡیَمَ وَمَا كُنتَ لَدَیۡهِمۡ إِذۡ یَخۡتَصِمُونَ ۝٤٤", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "ذلك الذي قصصناه عليك -أيها الرسول- من أخبار الغيب التي أوحاها الله إليك، إذ لم تكن معهم حين اختلفوا في كفالة مريم أيُّهم أحق بها وأولى، ووقع بينهم الخصام، فأجْرَوْا القرعة لإلقاء أقلامهم، ففاز زكريا عليه السلام بكفالتها.", "isBasmala": false, "translation_en": "These are accounts from the Unseen, which We reveal to you. You were not with them when they cast their lots as to which of them would take charge of Mary; nor were you with them as they quarreled.", "translation_id": "Yang demikian itu adalah sebagian dari berita-berita ghaib yang Kami wahyukan kepada kamu (ya Muhammad); padahal kamu tidak hadir beserta mereka, ketika mereka melemparkan anak-anak panah mereka (untuk mengundi) siapa di antara mereka yang akan memelihara Maryam. Dan kamu tidak hadir di sisi mereka ketika mereka bersengketa.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 45, "text": "إِذۡ قَالَتِ ٱلۡمَلَـٰۤىِٕكَةُ یَـٰمَرۡیَمُ إِنَّ ٱللَّهَ یُبَشِّرُكِ بِكَلِمَةࣲ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِیحُ عِیسَى ٱبۡنُ مَرۡیَمَ وَجِیهࣰا فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَمِنَ ٱلۡمُقَرَّبِینَ ۝٤٥", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "وما كنت - يا نبي الله - هناك حين قالت الملائكة: يا مريم إن الله يُبَشِّرْكِ بولد يكون وجوده بكلمة من الله، أي يقول له: \"كن\"، فيكون، اسمه المسيح عيسى ابن مريم، له الجاه العظيم في الدنيا والآخرة، ومن المقربين عند الله يوم القيامة.", "isBasmala": false, "translation_en": "The Angels said, \"O Mary, God gives you good news of a Word from Him. His name is the Messiah, Jesus, son of Mary, well-esteemed in this world and the next, and one of the nearest.", "translation_id": "(Ingatlah), ketika Malaikat berkata: \"Hai Maryam, seungguhnya Allah menggembirakan kamu (dengan kelahiran seorang putera yang diciptakan) dengan kalimat (yang datang) daripada-Nya, namanya Al Masih Isa putera Maryam, seorang terkemuka di dunia dan di akhirat dan termasuk orang-orang yang didekatkan (kepada Allah),", "manzil": 1, "manzil_display": ""}], "56": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 46, "text": "وَیُكَلِّمُ ٱلنَّاسَ فِی ٱلۡمَهۡدِ وَكَهۡلࣰا وَمِنَ ٱلصَّـٰلِحِینَ ۝٤٦", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "ويكلم الناس في المهد بعد ولادته، وكذلك يكلمهم في حال كهولته بما أوحاه الله إليه. وهذا تكليم النبوَّة والدعوة والإرشاد، وهو معدود من أهل الصلاح والفضل في قوله وعمله.", "isBasmala": false, "translation_en": "He will speak to the people from the crib, and in adulthood, and will be one of the righteous.\"", "translation_id": "dan dia berbicara dengan manusia dalam buaian dan ketika sudah dewasa dan dia adalah termasuk orang-orang yang saleh\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 47, "text": "قَالَتۡ رَبِّ أَنَّىٰ یَكُونُ لِی وَلَدࣱ وَلَمۡ یَمۡسَسۡنِی بَشَرࣱۖ قَالَ كَذَ ٰلِكِ ٱللَّهُ یَخۡلُقُ مَا یَشَاۤءُۚ إِذَا قَضَىٰۤ أَمۡرࣰا فَإِنَّمَا یَقُولُ لَهُۥ كُن فَیَكُونُ ۝٤٧", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "قالت مريم متعجبة من هذا الأمر: أنَّى يكون لي ولد وأنا لست بذات زوج ولا بَغِيٍّ؟ قال لها المَلَك: هذا الذي يحدث لكِ ليس بمستبعد على الإله القادر، الذي يوجِد ما يشاء من العدم، فإذا أراد إيجاد شيء فإنما يقول له: \"كُن\" فيكون.", "isBasmala": false, "translation_en": "She said, \"My Lord, how can I have a child, when no man has touched me?\" He said, \"It will be so. God creates whatever He wills. To have anything done, He only says to it, 'Be,' and it is.\"", "translation_id": "Maryam berkata: \"Ya Tuhanku, betapa mungkin aku mempunyai anak, padahal aku belum pernah disentuh oleh seorang laki-lakipun\". Allah berfirman (dengan perantaraan Jibril): \"Demikianlah Allah menciptakan apa yang dikehendaki-Nya. Apabila Allah berkehendak menetapkan sesuatu, maka Allah hanya cukup berkata kepadanya: \"Jadilah\", lalu jadilah dia.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 48, "text": "وَیُعَلِّمُهُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَ ۝٤٨", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "ويعلمه الكتابة، والسداد في القول والفعل، والتوراة التي أوحاها الله إلى موسى عليه السلام، والإنجيل الذي أنزل الله عليه.", "isBasmala": false, "translation_en": "And He will teach him the Scripture and wisdom, and the Torah and the Gospel.", "translation_id": "Dan Allah akan mengajarkan kepadanya Al Kitab, Hikmah, Taurat dan Injil.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 49, "text": "وَرَسُولًا إِلَىٰ بَنِیۤ إِسۡرَ ٰۤءِیلَ أَنِّی قَدۡ جِئۡتُكُم بِـَٔایَةࣲ مِّن رَّبِّكُمۡ أَنِّیۤ أَخۡلُقُ لَكُم مِّنَ ٱلطِّینِ كَهَیۡـَٔةِ ٱلطَّیۡرِ فَأَنفُخُ فِیهِ فَیَكُونُ طَیۡرَۢا بِإِذۡنِ ٱللَّهِۖ وَأُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ وَأُحۡیِ ٱلۡمَوۡتَىٰ بِإِذۡنِ ٱللَّهِۖ وَأُنَبِّئُكُم بِمَا تَأۡكُلُونَ وَمَا تَدَّخِرُونَ فِی بُیُوتِكُمۡۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِینَ ۝٤٩", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "ويجعله رسولا إلى بني إسرائيل، ويقول لهم: إني قد جئتكم بعلامة من ربكم تدلُّ على أني مرسل من الله، وهي أني أصنع لكم من الطين مثل شكل الطير، فأنفخ فيه فيكون طيرًا حقيقيا بإذن الله، وأَشفي مَن وُلِد أعمى، ومَن به برص، وأُحيي من كان ميتًا بإذن الله، وأخبركم بما تأكلون وتدَّخرون في بيوتكم من طعامكم. إن في هذه الأمور العظيمة التي ليست في قدرة البشر لدليلا على أني نبي الله ورسوله، إن كنتم مصدِّقين حجج الله وآياته، مقرِّين بتوحيده.", "isBasmala": false, "translation_en": "A messenger to the Children of Israel: \"I have come to you with a sign from your Lord. I make for you out of clay the figure of a bird; then I breathe into it, and it becomes a bird by God's leave. And I heal the blind and the leprous, and I revive the dead, by God's leave. And I inform you concerning what you eat, and what you store in your homes. In that is a sign for you, if you are believers.\"", "translation_id": "Dan (sebagai) Rasul kepada Bani Israil (yang berkata kepada mereka): \"Sesungguhnya aku telah datang kepadamu dengan membawa sesuatu tanda (mukjizat) dari Tuhanmu, yaitu aku membuat untuk kamu dari tanah berbentuk burung; kemudian aku meniupnya, maka ia menjadi seekor burung dengan seizin Allah; dan aku menyembuhkan orang yang buta sejak dari lahirnya dan orang yang berpenyakit sopak; dan aku menghidupkan orang mati dengan seizin Allah; dan aku kabarkan kepadamu apa yang kamu makan dan apa yang kamu simpan di rumahmu. Sesungguhnya pada yang demikian itu adalah suatu tanda (kebenaran kerasulanku) bagimu, jika kamu sungguh-sungguh beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 50, "text": "وَمُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیَّ مِنَ ٱلتَّوۡرَىٰةِ وَلِأُحِلَّ لَكُم بَعۡضَ ٱلَّذِی حُرِّمَ عَلَیۡكُمۡۚ وَجِئۡتُكُم بِـَٔایَةࣲ مِّن رَّبِّكُمۡ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝٥٠", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "وجئتكم مصدقًا بما في التوراة، ولأحلَّ لكم بوحي من الله بعض ما حرَّمه الله عليكم تخفيفًا من الله ورحمة، وجئتكم بحجة من ربكم على صدق ما أقول لكم، فاتقوا الله ولا تخالفوا أمره، وأطيعوني فيما أبلغكم به عن الله.", "isBasmala": false, "translation_en": "\"And verifying what lies before me of the Torah, and to make lawful for you some of what was forbidden to you. I have come to you with a sign from your Lord; so fear God, and obey me.\"", "translation_id": "Dan (aku datang kepadamu) membenarkan Taurat yang datang sebelumku, dan untuk menghalalkan bagimu sebagian yang telah diharamkan untukmu, dan aku datang kepadamu dengan membawa suatu tanda (mukjizat) daripada Tuhanmu. Karena itu bertakwalah kepada Allah dan taatlah kepadaku.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 51, "text": "إِنَّ ٱللَّهَ رَبِّی وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَـٰذَا صِرَ ٰطࣱ مُّسۡتَقِیمࣱ ۝٥١", "juz": 3, "hizb": "(*¼ ح 6*)", "tafsir": "إن الله الذي أدعوكم إليه هو وحده ربي وربكم فاعبدوه، فأنا وأنتم سواء في العبودية والخضوع له، وهذا هو الطريق الذي لا اعوجاج فيه.", "isBasmala": false, "translation_en": "\"God is my Lord and your Lord, so worship Him. That is a straight path.\"", "translation_id": "Sesungguhnya Allah, Tuhanku dan Tuhanmu, karena itu sembahlah Dia. Inilah jalan yang lurus\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 52, "text": "۞ فَلَمَّاۤ أَحَسَّ عِیسَىٰ مِنۡهُمُ ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِیۤ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِیُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ ۝٥٢", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "فلما استشعر عيسى منهم التصميم على الكفر نادى في أصحابه الخُلَّص: مَن يكون معي في نصرة دين الله؟ قال أصفياء عيسى: نحن أنصار دين الله والداعون إليه، صدَّقنا بالله واتبعناك، واشهد أنت يا عيسى بأنا مستسلمون لله بالتوحيد والطاعة.", "isBasmala": false, "translation_en": "When Jesus sensed disbelief on their part, he said, \"Who are my allies towards God?\" The disciples said, \"We are God's allies; we have believed in God, and bear witness that we submit.\"", "translation_id": "Maka tatkala Isa mengetahui keingkaran mereka (Bani lsrail) berkatalah dia: \"Siapakah yang akan menjadi penolong-penolongku untuk (menegakkan agama) Allah?\" Para hawariyyin (sahabat-sahabat setia) menjawab: \"Kamilah penolong-penolong (agama) Allah, kami beriman kepada Allah; dan saksikanlah bahwa sesungguhnya kami adalah orang-orang yang berserah diri.", "manzil": 1, "manzil_display": ""}], "57": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 53, "text": "رَبَّنَاۤ ءَامَنَّا بِمَاۤ أَنزَلۡتَ وَٱتَّبَعۡنَا ٱلرَّسُولَ فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِینَ ۝٥٣", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "ربنا صدَّقنا بما أنزلت من الإنجيل، واتبعنا رسولك عيسى عليه السلام، فاجعلنا ممن شهدوا لك بالوحدانية ولأنبيائك بالرسالة، وهم أمة محمد صلى الله عليه وسلم الذين يشهدون للرسل بأنهم بلَّغوا أممهم.", "isBasmala": false, "translation_en": "\"Our Lord, we have believed in what You have revealed, and we have followed the Messenger, so count us among the witnesses.\"", "translation_id": "Ya Tuhan kami, kami telah beriman kepada apa yang telah Engkau turunkan dan telah kami ikuti rasul, karena itu masukanlah kami ke dalam golongan orang-orang yang menjadi saksi (tentang keesaan Allah)\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 54, "text": "وَمَكَرُوا۟ وَمَكَرَ ٱللَّهُۖ وَٱللَّهُ خَیۡرُ ٱلۡمَـٰكِرِینَ ۝٥٤", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "ومكر الذين كفروا من بني إسرائيل بعيسى عليه السلام، بأن وكَّلوا به من يقتله غِيْلة، فألقى الله شَبَه عيسى على رجل دلَّهم عليه فأمسكوا به، وقتلوه وصلبوه ظناً منهم أنه عيسى عليه السلام، والله خير الماكرين. وفي هذا إثبات صفة المكر لله -تعالى- على ما يليق بجلاله وكماله؛ لأنه مكر بحق، وفي مقابلة مكر الماكرين.", "isBasmala": false, "translation_en": "They planned, and God planned; but God is the Best of planners.", "translation_id": "Orang-orang kafir itu membuat tipu daya, dan Allah membalas tipu daya mereka itu. Dan Allah sebaik-baik pembalas tipu daya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 55, "text": "إِذۡ قَالَ ٱللَّهُ یَـٰعِیسَىٰۤ إِنِّی مُتَوَفِّیكَ وَرَافِعُكَ إِلَیَّ وَمُطَهِّرُكَ مِنَ ٱلَّذِینَ كَفَرُوا۟ وَجَاعِلُ ٱلَّذِینَ ٱتَّبَعُوكَ فَوۡقَ ٱلَّذِینَ كَفَرُوۤا۟ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِۖ ثُمَّ إِلَیَّ مَرۡجِعُكُمۡ فَأَحۡكُمُ بَیۡنَكُمۡ فِیمَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ ۝٥٥", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "ومكر الله بهم حين قال الله لعيسى: إني قابضك من الأرض من غير أن ينالك سوء، ورافعك إليَّ ببدنك وروحك، ومخلصك من الذين كفروا بك، وجاعل الذين اتبعوك أي على دينك وما جئت به عن الله من الدين والبشارة بمحمد صلى الله عليه وسلم وآمَنوا بمحمد صلى الله عليه وسلم، بعد بعثنه، والتزموا شريعته ظاهرين على الذين جحدوا نبوتك إلى يوم القيامة، ثم إليّ مصيركم جميعًا يوم الحساب، فأفصِل بينكم فيما كنتم فيه تختلفون من أمر عيسى عليه السلام.", "isBasmala": false, "translation_en": "God said, \"O Jesus, I am terminating your life, and raising you to Me, and clearing you of those who disbelieve. And I will make those who follow you superior to those who disbelieve, until the Day of Resurrection. Then to Me is your return; then I will judge between you regarding what you were disputing.", "translation_id": "(Ingatlah), ketika Allah berfirman: \"Hai Isa, sesungguhnya Aku akan menyampaikan kamu kepada akhir ajalmu dan mengangkat kamu kepada-Ku serta membersihkan kamu dari orang-orang yang kafir, dan menjadikan orang-orang yang mengikuti kamu di atas orang-orang yang kafir hingga hari kiamat. Kemudian hanya kepada Akulah kembalimu, lalu Aku memutuskan diantaramu tentang hal-hal yang selalu kamu berselisih padanya\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 56, "text": "فَأَمَّا ٱلَّذِینَ كَفَرُوا۟ فَأُعَذِّبُهُمۡ عَذَابࣰا شَدِیدࣰا فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَمَا لَهُم مِّن نَّـٰصِرِینَ ۝٥٦", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "فأمَّا الذين كفروا بالمسيح من اليهود أو غَلَوا فيه من النصارى، فأعذبهم عذابًا شديدًا في الدنيا: بالقتل وسلْبِ الأموال وإزالة الملك، وفي الآخرة بالنار، وما لهم مِن ناصر ينصرهم ويدفع عنهم عذاب الله.", "isBasmala": false, "translation_en": "As for those who disbelieve, I will punish them with a severe punishment, in this world and the next, and they will have no helpers.", "translation_id": "Adapun orang-orang yang kafir, maka akan Ku-siksa mereka dengan siksa yang sangat keras di dunia dan di akhirat, dan mereka tidak memperoleh penolong.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 57, "text": "وَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَیُوَفِّیهِمۡ أُجُورَهُمۡۗ وَٱللَّهُ لَا یُحِبُّ ٱلظَّـٰلِمِینَ ۝٥٧", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "وأما الذين آمنوا بالله ورسله وعملوا الأعمال الصالحة، فيعطيهم الله ثواب أعمالهم كاملا غير منقوص. والله لا يحب الظالمين بالشرك والكفر.", "isBasmala": false, "translation_en": "And as for those who believe and do good works, He will give them their rewards in full. God does not love the unjust.\"", "translation_id": "Adapun orang-orang yang beriman dan mengerjakan amalan-amalan yang saleh, maka Allah akan memberikan kepada mereka dengan sempurna pahala amalan-amalan mereka; dan Allah tidak menyukai orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 58, "text": "ذَ ٰلِكَ نَتۡلُوهُ عَلَیۡكَ مِنَ ٱلۡـَٔایَـٰتِ وَٱلذِّكۡرِ ٱلۡحَكِیمِ ۝٥٨", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "ذلك الذي نقصُّه عليك في شأن عيسى، من الدلائل الواضحة على صحة رسالتك، وصحة القرآن الحكيم الذي يفصل بين الحق والباطل، فلا شك فيه ولا امتراء.", "isBasmala": false, "translation_en": "This is what We recite to you of the Verses and the Wise Reminder.", "translation_id": "Demikianlah (kisah Isa), Kami membacakannya kepada kamu sebagian dari bukti-bukti (kerasulannya) dan (membacakan) Al Quran yang penuh hikmah.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 59, "text": "إِنَّ مَثَلَ عِیسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَۖ خَلَقَهُۥ مِن تُرَابࣲ ثُمَّ قَالَ لَهُۥ كُن فَیَكُونُ ۝٥٩", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "إنَّ خَلْقَ الله لعيسى من غير أب مثَلُه كمثل خلق الله لآدم من غير أب ولا أم، إذ خلقه من تراب الأرض، ثم قال له: \"كن بشرًا\" فكان. فدعوى إلهية عيسى لكونه خلق من غير أب دعوى باطلة؛ فآدم عليه السلام خلق من غير أب ولا أم، واتفق الجميع على أنه عَبْد من عباد الله.", "isBasmala": false, "translation_en": "The likeness of Jesus in God's sight is that of Adam: He created him from dust, then said to him, \"Be,\" and he was.", "translation_id": "Sesungguhnya misal (penciptaan) Isa di sisi AllAh, adalah seperti (penciptaan) Adam. Allah menciptakan Adam dari tanah, kemudian Allah berfirman kepadanya: \"Jadilah\" (seorang manusia), maka jadilah dia.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 60, "text": "ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُن مِّنَ ٱلۡمُمۡتَرِینَ ۝٦٠", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "الحق الذي لا شك فيه في أمر عيسى هو الذي جاءك -أيها الرسول- من ربك، فدل على يقينك، وعلى ما أنت عليه من ترك الافتراء، ولا تكن من الشاكِّين، وفي هذا تثبيت وطمأنة لرسول الله صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "The truth is from your Lord, so do not be of those who doubt.", "translation_id": "(Apa yang telah Kami ceritakan itu), itulah yang benar, yang datang dari Tuhanmu, karena itu janganlah kamu termasuk orang-orang yang ragu-ragu.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 61, "text": "فَمَنۡ حَاۤجَّكَ فِیهِ مِنۢ بَعۡدِ مَا جَاۤءَكَ مِنَ ٱلۡعِلۡمِ فَقُلۡ تَعَالَوۡا۟ نَدۡعُ أَبۡنَاۤءَنَا وَأَبۡنَاۤءَكُمۡ وَنِسَاۤءَنَا وَنِسَاۤءَكُمۡ وَأَنفُسَنَا وَأَنفُسَكُمۡ ثُمَّ نَبۡتَهِلۡ فَنَجۡعَل لَّعۡنَتَ ٱللَّهِ عَلَى ٱلۡكَـٰذِبِینَ ۝٦١", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "فمَن جادلك -أيها الرسول- في المسيح عيسى ابن مريم من بعد ما جاءك من العلم في أمر عيسى عليه السلام، فقل لهم: تعالوا نُحْضِر أبناءنا وأبناءكم، ونساءنا ونساءكم، وأنفسنا وأنفسكم، ثم نتجه إلى الله بالدعاء أن يُنزل عقوبته ولعنته على الكاذبين في قولهم، المصرِّين على عنادهم.", "isBasmala": false, "translation_en": "And if anyone disputes with you about him, after the knowledge that has come to you, say, \"Come, let us call our children and your children, and our women and your women, and ourselves and yourselves, and let us invoke God's curse on the liars.\"", "translation_id": "Siapa yang membantahmu tentang kisah Isa sesudah datang ilmu (yang meyakinkan kamu), maka katakanlah (kepadanya): \"Marilah kita memanggil anak-anak kami dan anak-anak kamu, isteri-isteri kami dan isteri-isteri kamu, diri kami dan diri kamu; kemudian marilah kita bermubahalah kepada Allah dan kita minta supaya laknat Allah ditimpakan kepada orang-orang yang dusta.", "manzil": 1, "manzil_display": ""}], "58": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 62, "text": "إِنَّ هَـٰذَا لَهُوَ ٱلۡقَصَصُ ٱلۡحَقُّۚ وَمَا مِنۡ إِلَـٰهٍ إِلَّا ٱللَّهُۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٦٢", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "إن هذا الذي أنبأتك به من أمر عيسى لهو النبأ الحق الذي لا شك فيه، وما من معبود يستحق العبادة إلا الله وحده، وإن الله لهو العزيز في ملكه، الحكيم في تدبيره وفعله.", "isBasmala": false, "translation_en": "This is the narrative of truth: there is no god but God. God is the Mighty, the Wise.", "translation_id": "Sesungguhnya ini adalah kisah yang benar, dan tak ada Tuhan (yang berhak disembah) selain Allah; dan sesungguhnya Allah, Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 63, "text": "فَإِن تَوَلَّوۡا۟ فَإِنَّ ٱللَّهَ عَلِیمُۢ بِٱلۡمُفۡسِدِینَ ۝٦٣", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "فإن أعرضوا عن تصديقك واتباعك فهم المفسدون، والله عليم بهم، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "But if they turn away-God knows the corrupt.", "translation_id": "Kemudian jika mereka berpaling (dari kebenaran), maka sesunguhnya Allah Maha Mengetahui orang-orang yang berbuat kerusakan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 64, "text": "قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ تَعَالَوۡا۟ إِلَىٰ كَلِمَةࣲ سَوَاۤءِۭ بَیۡنَنَا وَبَیۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَیۡـࣰٔا وَلَا یَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابࣰا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡا۟ فَقُولُوا۟ ٱشۡهَدُوا۟ بِأَنَّا مُسۡلِمُونَ ۝٦٤", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "قل -أيها الرسول- لأهل الكتاب من اليهود والنصارى: تعالَوْا إلى كلمة عدل وحق نلتزم بها جميعًا: وهي أن نَخُص الله وحده بالعبادة، ولا نتخذ أي شريك معه، من وثن أو صنم أو صليب أو طاغوت أو غير ذلك، ولا يدين بعضنا لبعض بالطاعة من دون الله. فإن أعرضوا عن هذه الدعوة الطيبة فقولوا لهم - أيها المؤمنون -: اشهدوا علينا بأنا مسلمون منقادون لربنا بالعبودية والإخلاص. والدعوة إلى كلمة سواء، كما تُوجَّه إلى اليهود والنصارى، توجَّه إلى من جرى مجراهم.", "isBasmala": false, "translation_en": "Say, \"O People of the Book, come to terms common between us and you: that we worship none but God, and that we associate nothing with Him, and that none of us takes others as lords besides God.\" And if they turn away, say, \"Bear witness that we have submitted.\"", "translation_id": "Katakanlah: \"Hai Ahli Kitab, marilah (berpegang) kepada suatu kalimat (ketetapan) yang tidak ada perselisihan antara kami dan kamu, bahwa tidak kita sembah kecuali Allah dan tidak kita persekutukan Dia dengan sesuatupun dan tidak (pula) sebagian kita menjadikan sebagian yang lain sebagai tuhan selain Allah\". Jika mereka berpaling maka katakanlah kepada mereka: \"Saksikanlah, bahwa kami adalah orang-orang yang berserah diri (kepada Allah)\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 65, "text": "یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تُحَاۤجُّونَ فِیۤ إِبۡرَ ٰهِیمَ وَمَاۤ أُنزِلَتِ ٱلتَّوۡرَىٰةُ وَٱلۡإِنجِیلُ إِلَّا مِنۢ بَعۡدِهِۦۤۚ أَفَلَا تَعۡقِلُونَ ۝٦٥", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "يا أصحاب الكتب المنزلة من اليهود والنصارى، كيف يجادل كل منكم في أن إبراهيم عليه السلام كان على ملَّته، وما أُنزلت التوراة والإنجيل إلا من بعده؟ أفلا تفقهون خطأ قولكم: إن إبراهيم كان يهودياً أو نصرانياً، وقد علمتم أن اليهودية والنصرانية حدثت بعد وفاته بحين؟", "isBasmala": false, "translation_en": "O People of the Book! Why do you argue about Abraham, when the Torah and the Gospel were not revealed until after him? Will you not reason?", "translation_id": "Hai Ahli Kitab, mengapa kamu bantah membantah tentang hal Ibrahim, padahal Taurat dan Injil tidak diturunkan melainkan sesudah Ibrahim. Apakah kamu tidak berpikir?", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 66, "text": "هَـٰۤأَنتُمۡ هَـٰۤؤُلَاۤءِ حَـٰجَجۡتُمۡ فِیمَا لَكُم بِهِۦ عِلۡمࣱ فَلِمَ تُحَاۤجُّونَ فِیمَا لَیۡسَ لَكُم بِهِۦ عِلۡمࣱۚ وَٱللَّهُ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ۝٦٦", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "ها أنتم يا هؤلاء جادلتم رسول الله محمدًا صلى الله عليه وسلم فيما لكم به علم مِن أمر دينكم، مما تعتقدون صحته في كتبكم، فلِمَ تجادلون فيما ليس لكم به علم من أمر إبراهيم؟ والله يعلم الأمور على خفائها، وأنتم لا تعلمون.", "isBasmala": false, "translation_en": "Here you are-you argue about things you know, but why do you argue about things you do not know? God knows, and you do not know.", "translation_id": "Beginilah kamu, kamu ini (sewajarnya) bantah membantah tentang hal yang kamu ketahui, maka kenapa kamu bantah membantah tentang hal yang tidak kamu ketahui? Allah mengetahui sedang kamu tidak mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 67, "text": "مَا كَانَ إِبۡرَ ٰهِیمُ یَهُودِیࣰّا وَلَا نَصۡرَانِیࣰّا وَلَـٰكِن كَانَ حَنِیفࣰا مُّسۡلِمࣰا وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ ۝٦٧", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "ما كان إبراهيم يهودياً ولا نصرانياً، فلم تكن اليهودية ولا النصرانية إلا من بعده، ولكن كان متبعًا لأمر الله وطاعته، مستسلمًا لربه، وما كان من المشركين.", "isBasmala": false, "translation_en": "Abraham was neither a Jew nor a Christian, but he was a Monotheist, a Muslim. And he was not of the Polytheists.", "translation_id": "Ibrahim bukan seorang Yahudi dan bukan (pula) seorang Nasrani, akan tetapi dia adalah seorang yang lurus lagi berserah diri (kepada Allah) dan sekali-kali bukanlah dia termasuk golongan orang-orang musyrik.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 68, "text": "إِنَّ أَوۡلَى ٱلنَّاسِ بِإِبۡرَ ٰهِیمَ لَلَّذِینَ ٱتَّبَعُوهُ وَهَـٰذَا ٱلنَّبِیُّ وَٱلَّذِینَ ءَامَنُوا۟ۗ وَٱللَّهُ وَلِیُّ ٱلۡمُؤۡمِنِینَ ۝٦٨", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "إنَّ أحق الناس بإبراهيم وأخصهم به، الذين آمنوا به وصدقوا برسالته واتبعوه على دينه، وهذا النبي محمد صلى الله عليه وسلم والذين آمنوا به. والله وليُّ المؤمنين به المتبعين شرعه.", "isBasmala": false, "translation_en": "The people most deserving of Abraham are those who followed him, and this prophet, and those who believe. God is the Guardian of the believers.", "translation_id": "Sesungguhnya orang yang paling dekat kepada Ibrahim ialah orang-orang yang mengikutinya dan Nabi ini (Muhammad), beserta orang-orang yang beriman (kepada Muhammad), dan Allah adalah Pelindung semua orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 69, "text": "وَدَّت طَّاۤىِٕفَةࣱ مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ لَوۡ یُضِلُّونَكُمۡ وَمَا یُضِلُّونَ إِلَّاۤ أَنفُسَهُمۡ وَمَا یَشۡعُرُونَ ۝٦٩", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "تمنَّت جماعة من اليهود والنصارى لو يضلونكم - أيها المسلمون - عن الإسلام، وما يضلون إلا أنفسهم وأتباعهم، وما يدرون ذلك ولا يعلمونه.", "isBasmala": false, "translation_en": "A party of the People of the Book would love to lead you astray, but they only lead themselves astray, and they do not realize it.", "translation_id": "Segolongan dari Ahli Kitab ingin menyesatkan kamu, padahal mereka (sebenarnya) tidak menyesatkan melainkan dirinya sendiri, dan mereka tidak menyadarinya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 70, "text": "یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَأَنتُمۡ تَشۡهَدُونَ ۝٧٠", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "يا أهل التوراة والإنجيل لم تجحدون آيات الله التي أنزلها على رسله في كتبكم، وفيها أن محمدًا صلى الله عليه وسلم هو الرسول المنتظر، وأن ما جاءكم به هو الحق، وأنتم تشهدون بذلك؟ ولكنكم تنكرونه.", "isBasmala": false, "translation_en": "O People of the Book! Why do you reject the revelations of God, even as you witness?", "translation_id": "Hai Ahli Kitab, mengapa kamu mengingkari ayat-ayat Allah, padahal kamu mengetahui (kebenarannya).", "manzil": 1, "manzil_display": ""}], "59": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 71, "text": "یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تَلۡبِسُونَ ٱلۡحَقَّ بِٱلۡبَـٰطِلِ وَتَكۡتُمُونَ ٱلۡحَقَّ وَأَنتُمۡ تَعۡلَمُونَ ۝٧١", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "يا أهل التوراة والإنجيل لِمَ تخلطون الحق في كتبكم بما حرفتموه وكتبتموه من الباطل بأيديكم، وتُخْفون ما فيهما من صفة محمد صلى الله عليه وسلم، وأن دينه هو الحق، وأنتم تعلمون ذلك؟", "isBasmala": false, "translation_en": "O People of the Book! Why do you confound the truth with falsehood, and knowingly conceal the truth?", "translation_id": "Hai Ahli Kitab, mengapa kamu mencampur adukkan yang haq dengan yang bathil, dan menyembunyikan kebenaran, padahal kamu mengetahuinya?", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 72, "text": "وَقَالَت طَّاۤىِٕفَةࣱ مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ ءَامِنُوا۟ بِٱلَّذِیۤ أُنزِلَ عَلَى ٱلَّذِینَ ءَامَنُوا۟ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوۤا۟ ءَاخِرَهُۥ لَعَلَّهُمۡ یَرۡجِعُونَ ۝٧٢", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "وقالت جماعة من أهل الكتاب من اليهود: صدِّقوا بالذي أُنزل على الذين آمنوا أول النهار واكفروا آخره؛ لعلهم يتشككون في دينهم، ويرجعون عنه.", "isBasmala": false, "translation_en": "Some of the People of the Book say, \"Believe in what was revealed to the believers at the beginning of the day, and reject it at its end, so that they may return.\"", "translation_id": "Segolongan (lain) dari Ahli Kitab berkata (kepada sesamanya): \"Perlihatkanlah (seolah-olah) kamu beriman kepada apa yang diturunkan kepada orang-orang beriman (sahabat-sahabat Rasul) pada permulaan siang dan ingkarilah ia pada akhirnya, supaya mereka (orang-orang mukmin) kembali (kepada kekafiran).", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 73, "text": "وَلَا تُؤۡمِنُوۤا۟ إِلَّا لِمَن تَبِعَ دِینَكُمۡ قُلۡ إِنَّ ٱلۡهُدَىٰ هُدَى ٱللَّهِ أَن یُؤۡتَىٰۤ أَحَدࣱ مِّثۡلَ مَاۤ أُوتِیتُمۡ أَوۡ یُحَاۤجُّوكُمۡ عِندَ رَبِّكُمۡۗ قُلۡ إِنَّ ٱلۡفَضۡلَ بِیَدِ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۗ وَٱللَّهُ وَ ٰسِعٌ عَلِیمࣱ ۝٧٣", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "ولا تصدِّقوا تصديقًا صحيحًا إلا لمَن تبع دينكم فكان يهودياً، قل لهم -أيها الرسول-: إن الهدى والتوفيق هدى الله وتوفيقه للإيمان الصحيح. وقالوا: لا تظهروا ما عندكم من العلم للمسلمين فيتعلمون منكم فيساووكم في العلم به، وتكون لهم الأفضلية عليكم، أو أن يتخذوه حجة عند ربكم يغلبونكم بها. قل لهم -أيها الرسول-: إن الفضل والعطاء والأمور كلها بيد الله وتحت تصرفه، يؤتيها من يشاء ممن آمن به وبرسوله. والله واسع عليم، يَسَعُ بعلمه وعطائه جميع مخلوقاته، ممن يستحق فضله ونعمه.", "isBasmala": false, "translation_en": "And trust none except those who follow your religion.\" Say, \"Guidance is God's guidance. If someone is given the like of what you were given, or they argue with you before your Lord, say, \"All grace is in God's hand; He gives it to whomever He wills.\" God is Bounteous and Knowing.", "translation_id": "Dan janganlah kamu percaya melainkan kepada orang yang mengikuti agamamu. Katakanlah: \"Sesungguhnya petunjuk (yang harus diikuti) ialah petunjuk Allah, dan (janganlah kamu percaya) bahwa akan diberikan kepada seseorang seperti apa yang diberikan kepadamu, dan (jangan pula kamu percaya) bahwa mereka akan mengalahkan hujjahmu di sisi Tuhanmu\". Katakanlah: \"Sesungguhnya karunia itu di tangan Allah, Allah memberikan karunia-Nya kepada siapa yang dikehendaki-Nya; dan Allah Maha Luas karunia-Nya) lagi Maha Mengetahui\";", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 74, "text": "یَخۡتَصُّ بِرَحۡمَتِهِۦ مَن یَشَاۤءُۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ ۝٧٤", "juz": 3, "hizb": "(*½ ح 6*)", "tafsir": "إن الله يختص مِن خلقه مَن يشاء بالنبوة والهداية إلى أكمل الشرائع، والله ذو الفضل العظيم.", "isBasmala": false, "translation_en": "He specifies His mercy for whomever He wills. God is Possessor of Sublime Grace.", "translation_id": "Allah menentukan rahmat-Nya (kenabian) kepada siapa yang dikehendaki-Nya dan Allah mempunyai karunia yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 75, "text": "۞ وَمِنۡ أَهۡلِ ٱلۡكِتَـٰبِ مَنۡ إِن تَأۡمَنۡهُ بِقِنطَارࣲ یُؤَدِّهِۦۤ إِلَیۡكَ وَمِنۡهُم مَّنۡ إِن تَأۡمَنۡهُ بِدِینَارࣲ لَّا یُؤَدِّهِۦۤ إِلَیۡكَ إِلَّا مَا دُمۡتَ عَلَیۡهِ قَاۤىِٕمࣰاۗ ذَ ٰلِكَ بِأَنَّهُمۡ قَالُوا۟ لَیۡسَ عَلَیۡنَا فِی ٱلۡأُمِّیِّـۧنَ سَبِیلࣱ وَیَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ یَعۡلَمُونَ ۝٧٥", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "ومن أهل الكتاب من اليهود مَن إنْ تأمنه على كثير من المال يؤدِّه إليك من غير خيانة، ومنهم مَن إنْ تأمنه على دينار واحد لا يؤدِّه اليك، إلا إذا بذلت غاية الجهد في مطالبته. وسبب ذلك عقيدة فاسدة تجعلهم يستحلُّون أموال العرب بالباطل، ويقولون: ليس علينا في أكل أموالهم إثم ولا حرج؛ لأن الله أحلَّها لنا. وهذا كذب على الله، يقولونه بألسنتهم، وهم يعلمون أنهم كاذبون.", "isBasmala": false, "translation_en": "Among the People of the Book is he, who, if you entrust him with a heap of gold, he will give it back to you. And among them is he, who, if you entrust him with a single coin, he will not give it back to you, unless you keep after him. That is because they say, \"We are under no obligation towards the gentiles.\" They tell lies about God, and they know it.", "translation_id": "Di antara Ahli kitab ada orang yang jika kamu mempercayakan kepadanya harta yang banyak, dikembalikannya kepadamu; dan di antara mereka ada orang yang jika kamu mempercayakan kepadanya satu dinar, tidak dikembalikannya kepadamu kecuali jika kamu selalu menagihnya. Yang demikian itu lantaran mereka mengatakan: \"tidak ada dosa bagi kami terhadap orang-orang ummi. Mereka berkata dusta terhadap Allah, padahal mereka mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 76, "text": "بَلَىٰۚ مَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ وَٱتَّقَىٰ فَإِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُتَّقِینَ ۝٧٦", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "ليس الأمر كما زعم هؤلاء الكاذبون، فإن المتقي حقاً هو من أوفى بما عاهد الله عليه من أداء الأمانة والإيمان به وبرسله والتزم هديه وشرعه، وخاف الله عز وجل فامتثل أمره وانتهى عما نهى عنه. والله يحب المتقين الذين يتقون الشرك والمعاصي.", "isBasmala": false, "translation_en": "Indeed, whoever fulfills his commitments and maintains piety-God loves the pious.", "translation_id": "(Bukan demikian), sebenarnya siapa yang menepati janji (yang dibuat)nya dan bertakwa, maka sesungguhnya Allah menyukai orang-orang yang bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 77, "text": "إِنَّ ٱلَّذِینَ یَشۡتَرُونَ بِعَهۡدِ ٱللَّهِ وَأَیۡمَـٰنِهِمۡ ثَمَنࣰا قَلِیلًا أُو۟لَـٰۤىِٕكَ لَا خَلَـٰقَ لَهُمۡ فِی ٱلۡـَٔاخِرَةِ وَلَا یُكَلِّمُهُمُ ٱللَّهُ وَلَا یَنظُرُ إِلَیۡهِمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ وَلَا یُزَكِّیهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمࣱ ۝٧٧", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "إن الذين يستبدلون بعهد الله ووصيته التي أوصى بها في الكتب التي أنزلها على أنبيائهم، عوضًا وبدلا خسيسًا من عرض الدنيا وحطامها، أولئك لا نصيب لهم من الثواب في الآخرة، ولا يكلمهم الله بما يسرهم، ولا ينظر إليهم يوم القيامة بعين الرحمة، ولا يطهرهم من دنس الذنوب والكفر، ولهم عذاب موجع.", "isBasmala": false, "translation_en": "Those who exchange the covenant of God, and their vows, for a small price, will have no share in the Hereafter, and God will not speak to them, nor will He look at them on the Day of Resurrection, nor will He purify them. They will have a painful punishment.", "translation_id": "Sesungguhnya orang-orang yang menukar janji (nya dengan) Allah dan sumpah-sumpah mereka dengan harga yang sedikit, mereka itu tidak mendapat bahagian (pahala) di akhirat, dan Allah tidak akan berkata-kata dengan mereka dan tidak akan melihat kepada mereka pada hari kiamat dan tidak (pula) akan mensucikan mereka. Bagi mereka azab yang pedih.", "manzil": 1, "manzil_display": ""}], "60": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 78, "text": "وَإِنَّ مِنۡهُمۡ لَفَرِیقࣰا یَلۡوُۥنَ أَلۡسِنَتَهُم بِٱلۡكِتَـٰبِ لِتَحۡسَبُوهُ مِنَ ٱلۡكِتَـٰبِ وَمَا هُوَ مِنَ ٱلۡكِتَـٰبِ وَیَقُولُونَ هُوَ مِنۡ عِندِ ٱللَّهِ وَمَا هُوَ مِنۡ عِندِ ٱللَّهِ وَیَقُولُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُمۡ یَعۡلَمُونَ ۝٧٨", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "وإن مِن اليهود لَجماعةً يحرفون الكلام عن مواضعه، ويبدلون كلام الله؛ ليوهموا غيرهم أن هذا من الكلام المنزل، وهو التوراة، وما هو منها في شيء، ويقولون: هذا من عند الله أوحاه الله إلى نبيه موسى، وما هو من عند الله، وهم لأجل دنياهم يقولون على الله الكذب وهم يعلمون أنهم كاذبون.", "isBasmala": false, "translation_en": "And among them are those who twist the Scripture with their tongues, that you may think it from the Scripture, when it is not from the Scripture. And they say, \"It is from God,\" when it is not from God. They tell lies and attribute them to God, knowingly.", "translation_id": "Sesungguhnya diantara mereka ada segolongan yang memutar-mutar lidahnya membaca Al Kitab, supaya kamu menyangka yang dibacanya itu sebagian dari Al Kitab, padahal ia bukan dari Al Kitab dan mereka mengatakan: \"Ia (yang dibaca itu datang) dari sisi Allah\", padahal ia bukan dari sisi Allah. Mereka berkata dusta terhadap Allah sedang mereka mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 79, "text": "مَا كَانَ لِبَشَرٍ أَن یُؤۡتِیَهُ ٱللَّهُ ٱلۡكِتَـٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ ثُمَّ یَقُولَ لِلنَّاسِ كُونُوا۟ عِبَادࣰا لِّی مِن دُونِ ٱللَّهِ وَلَـٰكِن كُونُوا۟ رَبَّـٰنِیِّـۧنَ بِمَا كُنتُمۡ تُعَلِّمُونَ ٱلۡكِتَـٰبَ وَبِمَا كُنتُمۡ تَدۡرُسُونَ ۝٧٩", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "ما ينبغي لأحد من البشر أن يُنزِّل الله عليه كتابه ويجعله حكمًا بين خلقه ويختاره نبياً، ثم يقول للناس: اعبدوني من دون الله، ولكن يقول: كونوا حكماء فقهاء علماء بما كنتم تُعَلِّمونه غيركم من وحي الله تعالى، وبما تدرسونه منه حفظًا وعلمًا وفقهًا.", "isBasmala": false, "translation_en": "No person to whom God has given the Scripture, and wisdom, and prophethood would ever say to the people, \"Be my worshipers rather than God's.\" Rather, \"Be people of the Lord, according to the Scripture you teach, and the teachings you learn.\"", "translation_id": "Tidak wajar bagi seseorang manusia yang Allah berikan kepadanya Al Kitab, hikmah dan kenabian, lalu dia berkata kepada manusia: \"Hendaklah kamu menjadi penyembah-penyembahku bukan penyembah Allah\". Akan tetapi (dia berkata): \"Hendaklah kamu menjadi orang-orang rabbani, karena kamu selalu mengajarkan Al Kitab dan disebabkan kamu tetap mempelajarinya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 80, "text": "وَلَا یَأۡمُرَكُمۡ أَن تَتَّخِذُوا۟ ٱلۡمَلَـٰۤىِٕكَةَ وَٱلنَّبِیِّـۧنَ أَرۡبَابًاۗ أَیَأۡمُرُكُم بِٱلۡكُفۡرِ بَعۡدَ إِذۡ أَنتُم مُّسۡلِمُونَ ۝٨٠", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "وما كان لأحد منهم أن يأمركم باتخاذ الملائكة والنبيين أربابًا تعبدونهم من دون الله. أَيُعْقَلُ -أيها الناس- أن يأمركم بالكفر بالله بعد انقيادكم لأمره؟", "isBasmala": false, "translation_en": "Nor would he command you to take the angels and the prophets as lords. Would he command you to infidelity after you have submitted?", "translation_id": "dan (tidak wajar pula baginya) menyuruhmu menjadikan malaikat dan para nabi sebagai tuhan. Apakah (patut) dia menyuruhmu berbuat kekafiran di waktu kamu sudah (menganut agama) Islam?\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 81, "text": "وَإِذۡ أَخَذَ ٱللَّهُ مِیثَـٰقَ ٱلنَّبِیِّـۧنَ لَمَاۤ ءَاتَیۡتُكُم مِّن كِتَـٰبࣲ وَحِكۡمَةࣲ ثُمَّ جَاۤءَكُمۡ رَسُولࣱ مُّصَدِّقࣱ لِّمَا مَعَكُمۡ لَتُؤۡمِنُنَّ بِهِۦ وَلَتَنصُرُنَّهُۥۚ قَالَ ءَأَقۡرَرۡتُمۡ وَأَخَذۡتُمۡ عَلَىٰ ذَ ٰلِكُمۡ إِصۡرِیۖ قَالُوۤا۟ أَقۡرَرۡنَاۚ قَالَ فَٱشۡهَدُوا۟ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّـٰهِدِینَ ۝٨١", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "واذكر -أيها الرسول- إذ أخذ الله سبحانه العهد المؤكد على جميع الأنبياء: لَئِنْ آتيتكم من كتاب وحكمة، ثم جاءكم رسول من عندي، مصدق لما معكم لتؤمنن به ولتنصرنَّه. فهل أقررتم واعترفتم بذلك وأخذتم على ذلك عهدي الموثق؟ قالوا: أقررنا بذلك، قال: فليشهدْ بعضكم على بعض، واشهدوا على أممكم بذلك، وأنا معكم من الشاهدين عليكم وعليهم. وفي هذا أن الله أخذ الميثاق على كل نبي أن يؤمن بمحمد صلى الله عليه وسلم، وأخذ الميثاق على أمم الأنبياء بذلك.", "isBasmala": false, "translation_en": "God received the covenant of the prophets, \"Inasmuch as I have given you of scripture and wisdom; should a messenger come to you verifying what you have, you shall believe in him, and support him.\" He said, \"Do you affirm My covenant and take it upon yourselves?\" They said, \"We affirm it.\" He said, \"Then bear witness, and I am with you among the witnesses.\"", "translation_id": "Dan (ingatlah), ketika Allah mengambil perjanjian dari para nabi: \"Sungguh, apa saja yang Aku berikan kepadamu berupa kitab dan hikmah kemudian datang kepadamu seorang rasul yang membenarkan apa yang ada padamu, niscaya kamu akan sungguh-sungguh beriman kepadanya dan menolongnya\". Allah berfirman: \"Apakah kamu mengakui dan menerima perjanjian-Ku terhadap yang demikian itu?\" Mereka menjawab: \"Kami mengakui\". Allah berfirman: \"Kalau begitu saksikanlah (hai para nabi) dan Aku menjadi saksi (pula) bersama kamu\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 82, "text": "فَمَن تَوَلَّىٰ بَعۡدَ ذَ ٰلِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ ۝٨٢", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "فمن أعرض عن دعوة الإسلام بعد هذا البيان وهذا العهد الذي أخذه الله على أنبيائه، فأولئك هم الخارجون عن دين الله وطاعة ربهم.", "isBasmala": false, "translation_en": "Whoever turns away after that-these are the deceitful.", "translation_id": "Barang siapa yang berpaling sesudah itu, maka mereka itulah orang-orang yang fasik.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 83, "text": "أَفَغَیۡرَ دِینِ ٱللَّهِ یَبۡغُونَ وَلَهُۥۤ أَسۡلَمَ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ طَوۡعࣰا وَكَرۡهࣰا وَإِلَیۡهِ یُرۡجَعُونَ ۝٨٣", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "أيريد هؤلاء الفاسقون من أهل الكتاب غير دين الله -وهو الإسلام الذي بعث الله به محمدا صلى الله عليه وسلم-، مع أن كل مَن في السموات والأرض استسلم وانقاد وخضع لله طواعية -كالمؤمنين- ورغمًا عنهم عند الشدائد، حين لا ينفعهم ذلك وهم الكفار، كما خضع له سائر الكائنات، وإليه يُرجَعون يوم المعاد، فيجازي كلا بعمله. وهذا تحذير من الله تعالى لخلقه أن يرجع إليه أحد منهم على غير ملة الإسلام.", "isBasmala": false, "translation_en": "Do they desire other than the religion of God, when to Him has submitted everything in the heavens and the earth, willingly or unwillingly, and to Him they will be returned?", "translation_id": "Maka apakah mereka mencari agama yang lain dari agama Allah, padahal kepada-Nya-lah menyerahkan diri segala apa yang di langit dan di bumi, baik dengan suka maupun terpaksa dan hanya kepada Allahlah mereka dikembalikan.", "manzil": 1, "manzil_display": ""}], "61": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 84, "text": "قُلۡ ءَامَنَّا بِٱللَّهِ وَمَاۤ أُنزِلَ عَلَیۡنَا وَمَاۤ أُنزِلَ عَلَىٰۤ إِبۡرَ ٰهِیمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَمَاۤ أُوتِیَ مُوسَىٰ وَعِیسَىٰ وَٱلنَّبِیُّونَ مِن رَّبِّهِمۡ لَا نُفَرِّقُ بَیۡنَ أَحَدࣲ مِّنۡهُمۡ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ۝٨٤", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "قل لهم -أيها الرسول-: صدَّقنا بالله وأطعنا، فلا رب لنا غيره، ولا معبود لنا سواه، وآمنَّا بالوحي الذي أنزله الله علينا، والذي أنزله على إبراهيم خليل الله، وابنيه إسماعبل وإسحاق، وابن ابنه يعقوب بن إسحاق، والذي أنزله على الأسباط -وهم الأنبياء الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة مِن ولد يعقوب- وما أوتي موسى وعيسى من التوراة والإنجيل، وما أنزله الله على أنبيائه، نؤمن بذلك كله، ولا نفرق بين أحد منهم، ونحن لله وحده منقادون بالطاعة، مُقِرُّون له بالربوبية والألوهية والعبادة.", "isBasmala": false, "translation_en": "Say, \"We believe in God, and in what was revealed to us; and in what was revealed to Abraham, and Ishmael, and Isaac, and Jacob, and the Patriarchs; and in what was given to Moses, and Jesus, and the prophets from their Lord. We make no distinction between any of them, and to Him we submit.\"", "translation_id": "Katakanlah: \"Kami beriman kepada Allah dan kepada apa yang diturunkan kepada kami dan yang diturunkan kepada Ibrahim, Ismail, Ishaq, Ya'qub, dan anak-anaknya, dan apa yang diberikan kepada Musa, Isa dan para nabi dari Tuhan mereka. Kami tidak membeda-bedakan seorangpun di antara mereka dan hanya kepada-Nya-lah kami menyerahkan diri\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 85, "text": "وَمَن یَبۡتَغِ غَیۡرَ ٱلۡإِسۡلَـٰمِ دِینࣰا فَلَن یُقۡبَلَ مِنۡهُ وَهُوَ فِی ٱلۡـَٔاخِرَةِ مِنَ ٱلۡخَـٰسِرِینَ ۝٨٥", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "ومن يطلب دينًا غير دين الإسلام الذي هو الاستسلام لله بالتوحيد والانقياد له بالطاعة، والعبودية، ولرسوله النبي الخاتم محمد صلى الله عليه وسلم بالإيمان به وبمتابعته ومحبته ظاهرًا وباطنًا، فلن يُقبل منه ذلك، وهو في الآخرة من الخاسرين الذين بخسوا أنفسهم حظوظها.", "isBasmala": false, "translation_en": "Whoever seeks other than Islam as a religion, it will not be accepted from him, and in the Hereafter he will be among the losers.", "translation_id": "Barangsiapa mencari agama selain agama Islam, maka sekali-kali tidaklah akan diterima (agama itu)daripadanya, dan dia di akhirat termasuk orang-orang yang rugi.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 86, "text": "كَیۡفَ یَهۡدِی ٱللَّهُ قَوۡمࣰا كَفَرُوا۟ بَعۡدَ إِیمَـٰنِهِمۡ وَشَهِدُوۤا۟ أَنَّ ٱلرَّسُولَ حَقࣱّ وَجَاۤءَهُمُ ٱلۡبَیِّنَـٰتُۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝٨٦", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "كيف يوفق الله للإيمان به وبرسوله قومًا جحدوا نبوة محمد صلى الله عليه وسلم بعد إيمانهم به، وشهدوا أن محمدًا صلى الله عليه وسلم حق وما جاء به هو الحق، وجاءهم الحجج من عند الله والدلائل بصحة ذلك؟ والله لا يوفق للحق والصواب الجماعة الظلمة، وهم الذين عدلوا عن الحق إلى الباطل، فاختاروا الكفر على الإيمان.", "isBasmala": false, "translation_en": "How will God guide a people who disbelieved after having believed, and had witnessed that the Messenger is true, and the clear proofs had come to them? God does not guide the unjust people.", "translation_id": "Bagaimana Allah akan menunjuki suatu kaum yang kafir sesudah mereka beriman, serta mereka telah mengakui bahwa Rasul itu (Muhammad) benar-benar rasul, dan keterangan-keteranganpun telah datang kepada mereka? Allah tidak menunjuki orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 87, "text": "أُو۟لَـٰۤىِٕكَ جَزَاۤؤُهُمۡ أَنَّ عَلَیۡهِمۡ لَعۡنَةَ ٱللَّهِ وَٱلۡمَلَـٰۤىِٕكَةِ وَٱلنَّاسِ أَجۡمَعِینَ ۝٨٧", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "أولئك الظالمون جزاؤهم أنَّ عليهم لعنة الله والملائكة والناسِ أجمعين، فهم مطرودون من رحمة الله.", "isBasmala": false, "translation_en": "Those-their penalty is that upon them falls the curse of God, and of the angels, and of all mankind.", "translation_id": "Mereka itu, balasannya ialah: bahwasanya laknat Allah ditimpakan kepada mereka, (demikian pula) laknat para malaikat dan manusia seluruhnya,", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 88, "text": "خَـٰلِدِینَ فِیهَا لَا یُخَفَّفُ عَنۡهُمُ ٱلۡعَذَابُ وَلَا هُمۡ یُنظَرُونَ ۝٨٨", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "ماكثين في النار، لا يُرفع عنهم العذاب قليلا ليستريحوا، ولا يُؤخر عنهم لمعذرة يعتذرون بها.", "isBasmala": false, "translation_en": "Remaining in it eternally, without their punishment being eased from them, and without being reprieved.", "translation_id": "mereka kekal di dalamnya, tidak diringankan siksa dari mereka, dan tidak (pula) mereka diberi tangguh,", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 89, "text": "إِلَّا ٱلَّذِینَ تَابُوا۟ مِنۢ بَعۡدِ ذَ ٰلِكَ وَأَصۡلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ ۝٨٩", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "إلا الذين رجعوا إلى ربهم بالتوبة النصوح من بعد كفرهم وظلمهم، وأصلحوا ما أفسدوه بتوبتهم فإن الله يقبلها، فهو غفور لذنوب عباده، رحيم بهم.", "isBasmala": false, "translation_en": "Except those who repent afterwards, and reform; for God is Forgiving and Merciful.", "translation_id": "kecuali orang-orang yang taubat, sesudah (kafir) itu dan mengadakan perbaikan. Karena sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 90, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ بَعۡدَ إِیمَـٰنِهِمۡ ثُمَّ ٱزۡدَادُوا۟ كُفۡرࣰا لَّن تُقۡبَلَ تَوۡبَتُهُمۡ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلضَّاۤلُّونَ ۝٩٠", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "إن الذين كفروا بعد إيمانهم واستمروا على الكفر إلى الممات لن تُقبل لهم توبة عند حضور الموت، وأولئك هم الذين ضلُّوا السبيل، فأخطَؤُوا منهجه.", "isBasmala": false, "translation_en": "As for those who disbelieve after having believed, then plunge deeper into disbelief, their repentance will not be accepted; these are the lost.", "translation_id": "Sesungguhnya orang-orang kafir sesudah beriman, kemudian bertambah kekafirannya, sekali-kali tidak akan diterima taubatnya; dan mereka itulah orang-orang yang sesat.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 91, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمۡ كُفَّارࣱ فَلَن یُقۡبَلَ مِنۡ أَحَدِهِم مِّلۡءُ ٱلۡأَرۡضِ ذَهَبࣰا وَلَوِ ٱفۡتَدَىٰ بِهِۦۤۗ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابٌ أَلِیمࣱ وَمَا لَهُم مِّن نَّـٰصِرِینَ ۝٩١", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "إن الذين جحدوا نبوة محمد صلى الله عليه وسلم، وماتوا على الكفر بالله ورسوله، فلن يُقبل من أحدهم يوم القيامة ملء الأرض ذهبًا؛ ليفتدي به نفسه من عذاب الله، ولو افتدى به نفسه فِعْلا. أولئك لهم عذاب موجع، وما لهم من أحد ينقذهم من عذاب الله.", "isBasmala": false, "translation_en": "As for those who disbelieve and die disbelievers, even the earth full of gold would not be accepted from any of them, were he to offer it for ransom. These will have a painful torment, and will have no saviors.", "translation_id": "Sesungguhnya orang-orang yang kafir dan mati sedang mereka tetap dalam kekafirannya, maka tidaklah akan diterima dari seseorang diantara mereka emas sepenuh bumi, walaupun dia menebus diri dengan emas (yang sebanyak) itu. Bagi mereka itulah siksa yang pedih dan sekali-kali mereka tidak memperoleh penolong.", "manzil": 1, "manzil_display": ""}], "62": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 92, "text": "لَن تَنَالُوا۟ ٱلۡبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَۚ وَمَا تُنفِقُوا۟ مِن شَیۡءࣲ فَإِنَّ ٱللَّهَ بِهِۦ عَلِیمࣱ ۝٩٢", "juz": 3, "hizb": "(*¾ ح 6*)", "tafsir": "لن تدركوا الجنة حتى تتصدقوا مما تحبون، وأي شيء تتصدقوا به مهما كان قليلا أو كثيرًا فإن الله به عليم، وسيجازي كل منفق بحسب عمله.", "isBasmala": false, "translation_en": "You will not attain virtuous conduct until you give of what you cherish. Whatever you give away, God is aware of it.", "translation_id": "Kamu sekali-kali tidak sampai kepada kebajikan (yang sempurna), sebelum kamu menafkahkan sehahagian harta yang kamu cintai. Dan apa saja yang kamu nafkahkan maka sesungguhnya Allah mengetahuinya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 93, "text": "۞ كُلُّ ٱلطَّعَامِ كَانَ حِلࣰّا لِّبَنِیۤ إِسۡرَ ٰۤءِیلَ إِلَّا مَا حَرَّمَ إِسۡرَ ٰۤءِیلُ عَلَىٰ نَفۡسِهِۦ مِن قَبۡلِ أَن تُنَزَّلَ ٱلتَّوۡرَىٰةُۚ قُلۡ فَأۡتُوا۟ بِٱلتَّوۡرَىٰةِ فَٱتۡلُوهَاۤ إِن كُنتُمۡ صَـٰدِقِینَ ۝٩٣", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "كل الأطعمة الطيِّبة كانت حلالا لأبناء يعقوب عليه السلام إلا ما حرَّم يعقوب على نفسه لمرض نزل به، وذلك مِن قبل أن تُنَزَّل التوراة. فلما نُزِّلت التوراة حرَّم الله على بني إسرائيل بعض الأطعمة التي كانت حلالا لهم؛ وذلك لظلمهم وبغيهم. قل لهم -أيها الرسول-: هاتوا التوراة، واقرؤوا ما فيها إن كنتم محقين في دعواكم أن الله أنزل فيها تحريم ما حرَّمه يعقوب على نفسه، حتى تعلموا صدق ما جاء في القرآن من أن الله لم يحرم على بني إسرائيل شيئًا من قبل نزول التوراة، إلا ما حرَّمه يعقوب على نفسه.", "isBasmala": false, "translation_en": "All food was permissible to the Children of Israel, except what Israel forbade for itself before the Torah was revealed. Say, \"Bring the Torah, and read it, if you are truthful.\"", "translation_id": "Semua makanan adalah halal bagi Bani Israil melainkan makanan yang diharamkan oleh Israil (Ya'qub) untuk dirinya sendiri sebelum Taurat diturunkan. Katakanlah: \"(Jika kamu mengatakan ada makanan yang diharamkan sebelum turun Taurat), maka bawalah Taurat itu, lalu bacalah dia jika kamu orang-orang yang benar\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 94, "text": "فَمَنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ مِنۢ بَعۡدِ ذَ ٰلِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ ۝٩٤", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "فمَن كذب على الله من بعد قراءة التوراة ووضوح الحقيقة، فأولئك هم الظالمون القائلون على الله بالباطل.", "isBasmala": false, "translation_en": "Whoever forges lies about God after that-these are the unjust.", "translation_id": "Maka barangsiapa mengada-adakan dusta terhadap Allah sesudah itu, maka merekalah orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 95, "text": "قُلۡ صَدَقَ ٱللَّهُۗ فَٱتَّبِعُوا۟ مِلَّةَ إِبۡرَ ٰهِیمَ حَنِیفࣰاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ ۝٩٥", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "قل لهم -أيها الرسول- صَدَق الله فيما أخبر به وفيما شرعه. فإن كنتم صادقين في محبتكم وانتسابكم لخليل الله إبراهيم عليه السلام فاتبعوا ملَّته التي شرعها الله على لسان محمد صلى الله عليه وسلم، فإنها الحق الذي لا شك فيه. وما كان إبراهيم عليه السلام من المشركين بالله في توحيده وعبادته أحدًا.", "isBasmala": false, "translation_en": "Say, \"God has spoken the truth, so follow the religion of Abraham the Monotheist; he was not a Pagan.\"", "translation_id": "Katakanlah: \"Benarlah (apa yang difirmankan) Allah\". Maka ikutilah agama Ibrahim yang lurus, dan bukanlah dia termasuk orang-orang yang musyrik.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 96, "text": "إِنَّ أَوَّلَ بَیۡتࣲ وُضِعَ لِلنَّاسِ لَلَّذِی بِبَكَّةَ مُبَارَكࣰا وَهُدࣰى لِّلۡعَـٰلَمِینَ ۝٩٦", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "إن أول بيت بُني لعبادة الله في الأرض لهو بيت الله الحرام الذي في \"مكة\"، وهذا البيت مبارك تضاعف فيه الحسنات، وتتنزل فيه الرحمات، وفي استقباله في الصلاة، وقصده لأداء الحج والعمرة، صلاح وهداية للناس أجمعين.", "isBasmala": false, "translation_en": "The first house established for mankind is the one at Bekka; blessed, and guidance for all people.", "translation_id": "Sesungguhnya rumah yang mula-mula dibangun untuk (tempat beribadat) manusia, ialah Baitullah yang di Bakkah (Mekah) yang diberkahi dan menjadi petunjuk bagi semua manusia.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 97, "text": "فِیهِ ءَایَـٰتُۢ بَیِّنَـٰتࣱ مَّقَامُ إِبۡرَ ٰهِیمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنࣰاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَیۡتِ مَنِ ٱسۡتَطَاعَ إِلَیۡهِ سَبِیلࣰاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِیٌّ عَنِ ٱلۡعَـٰلَمِینَ ۝٩٧", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "في هذا البيت دلالات ظاهرات أنه من بناء إبراهيم، وأن الله عظَّمه وشرَّفه، منها: مقام إبراهيم عليه السلام، وهو الحَجَر الذي كان يقف عليه حين كان يرفع القواعد من البيت هو وابنه إسماعيل، ومن دخل هذا البيت أَمِنَ على نفسه فلا يناله أحد بسوء. وقد أوجب الله على المستطيع من الناس في أي مكان قَصْدَ هذا البيت لأداء مناسك الحج. ومن جحد فريضة الحج فقد كفر، والله غني عنه وعن حجِّه وعمله، وعن سائر خَلْقه.", "isBasmala": false, "translation_en": "In it are evident signs; the Station of Abraham. Whoever enters it attains security. Pilgrimage to the House is a duty to God for all who can make the journey. But as for those who refuse-God is Independent of the worlds.", "translation_id": "Padanya terdapat tanda-tanda yang nyata, (di antaranya) maqam Ibrahim; barangsiapa memasukinya (Baitullah itu) menjadi amanlah dia; mengerjakan haji adalah kewajiban manusia terhadap Allah, yaitu (bagi) orang yang sanggup mengadakan perjalanan ke Baitullah. Barangsiapa mengingkari (kewajiban haji), maka sesungguhnya Allah Maha Kaya (tidak memerlukan sesuatu) dari semesta alam.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 98, "text": "قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَٱللَّهُ شَهِیدٌ عَلَىٰ مَا تَعۡمَلُونَ ۝٩٨", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "قل -أيها الرسول- لأهل الكتاب من اليهود والنصارى: لِمَ تجحدون حجج الله التي دلَّتْ على أن دين الله هو الإسلام، وتنكرون ما في كتبهم من دلائل وبراهين على ذلك، وأنتم تعلمون؟ والله شهيد على صنيعكم. وفي ذلك تهديد ووعيد لهم.", "isBasmala": false, "translation_en": "Say, \"O People of the Scripture, why do you reject the Revelations of God, when God witnesses what you do?\"", "translation_id": "Katakanlah: \"Hai Ahli Kitab, mengapa kamu ingkari ayat-ayat Allah, padahal Allah Maha menyaksikan apa yang kamu kerjakan?\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 99, "text": "قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لِمَ تَصُدُّونَ عَن سَبِیلِ ٱللَّهِ مَنۡ ءَامَنَ تَبۡغُونَهَا عِوَجࣰا وَأَنتُمۡ شُهَدَاۤءُۗ وَمَا ٱللَّهُ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ ۝٩٩", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "قل -أيها الرسول- لليهود والنصارى: لِمَ تمنعون من الإسلام من يريد الدخول فيه تطلبون له زيغًا وميلا عن القصد والاستقامة، وأنتم تعلمون أن ما جئتُ به هو الحق؟ وما الله بغافل عما تعملون، وسوف يجازيكم على ذلك.", "isBasmala": false, "translation_en": "Say, \"O People of the Scripture, why do you hinder from God's path those who believe, seeking to distort it, even though you are witnesses? God is not unaware of what you do.\"", "translation_id": "Katakanlah: \"Hai Ahli Kitab, mengapa kamu menghalang-halangi dari jalan Allah orang-orang yang telah beriman, kamu menghendakinya menjadi bengkok, padahal kamu menyaksikan?\". Allah sekali-kali tidak lalai dari apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 100, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن تُطِیعُوا۟ فَرِیقࣰا مِّنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ یَرُدُّوكُم بَعۡدَ إِیمَـٰنِكُمۡ كَـٰفِرِینَ ۝١٠٠", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إن تطيعوا جماعة من اليهود والنصارى ممن آتاهم الله التوراة والإنجيل، يضلوكم، ويلقوا إليكم الشُّبَه في دينكم؛ لترجعوا جاحدين للحق بعد أن كنتم مؤمنين به، فلا تأمنوهم على دينكم، ولا تقبلوا لهم رأيًا أو مشورة.", "isBasmala": false, "translation_en": "O you who believe! If you obey a party of those who were given the Scripture, they will turn you, after your belief, into disbelievers.", "translation_id": "Hai orang-orang yang beriman, jika kamu mengikuti sebahagian dari orang-orang yang diberi Al Kitab, niscaya mereka akan mengembalikan kamu menjadi orang kafir sesudah kamu beriman.", "manzil": 1, "manzil_display": ""}], "63": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 101, "text": "وَكَیۡفَ تَكۡفُرُونَ وَأَنتُمۡ تُتۡلَىٰ عَلَیۡكُمۡ ءَایَـٰتُ ٱللَّهِ وَفِیكُمۡ رَسُولُهُۥۗ وَمَن یَعۡتَصِم بِٱللَّهِ فَقَدۡ هُدِیَ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝١٠١", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "وكيف تكفرون بالله -أيها المؤمنون -، وآيات القرآن تتلى عليكم، وفيكم رسول الله محمد صلى الله عليه وسلم يبلغها لكم؟ ومَن يتوكل على الله ويستمسك بالقرآن والسنة فقد وُفِّق لطريق واضح، ومنهاج مستقيم.", "isBasmala": false, "translation_en": "And how could you disbelieve, when God's revelations are being recited to you, and among you is His Messenger? Whoever cleaves to God has been guided to a straight path.", "translation_id": "Bagaimanakah kamu (sampai) menjadi kafir, padahal ayat-ayat Allah dibacakan kepada kamu, dan Rasul-Nya pun berada di tengah-tengah kamu? Barangsiapa yang berpegang teguh kepada (agama) Allah, maka sesungguhnya ia telah diberi petunjuk kepada jalan yang lurus.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 102, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ حَقَّ تُقَاتِهِۦ وَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ ۝١٠٢", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله، وعملوا بشرعه، خافوا الله حق خوفه: وذلك بأن يطاع فلا يُعصى، ويُشكَر فلا يكفر، ويُذكَر فلا ينسى، وداوموا على تمسككم بإسلامكم إلى آخر حياتكم؛ لتلقوا الله وأنتم عليه.", "isBasmala": false, "translation_en": "O you who believe! Revere God with due reverence, and do not die except as Muslims.", "translation_id": "Hai orang-orang yang beriman, bertakwalah kepada Allah sebenar-benar takwa kepada-Nya; dan janganlah sekali-kali kamu mati melainkan dalam keadaan beragama Islam.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 103, "text": "وَٱعۡتَصِمُوا۟ بِحَبۡلِ ٱللَّهِ جَمِیعࣰا وَلَا تَفَرَّقُوا۟ۚ وَٱذۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَاۤءࣰ فَأَلَّفَ بَیۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦۤ إِخۡوَ ٰنࣰا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةࣲ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَ ٰلِكَ یُبَیِّنُ ٱللَّهُ لَكُمۡ ءَایَـٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ ۝١٠٣", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "وتمسَّكوا جميعًا بكتاب ربكم وهدي نبيكم، ولا تفعلوا ما يؤدي إلى فرقتكم. واذكروا نعمة جليلة أنعم الله بها عليكم: إذ كنتم -أيها المؤمنون- قبل الإسلام أعداء، فجمع الله قلوبكم على محبته ومحبة رسوله، وألقى في قلوبكم محبة بعضكم لبعض، فأصبحتم -بفضله- إخوانا متحابين، وكنتم على حافة نار جهنم، فهداكم الله بالإسلام ونجَّاكم من النار. وكما بيَّن الله لكم معالم الإيمان الصحيح فكذلك يبيِّن لكم كل ما فيه صلاحكم؛ لتهتدوا إلى سبيل الرشاد، وتسلكوها، فلا تضلوا عنها.", "isBasmala": false, "translation_en": "And hold fast to the rope of God, altogether, and do not become divided. And remember God's blessings upon you; how you were enemies, and He reconciled your hearts, and by His grace you became brethren. And you were on the brink of a pit of fire, and He saved you from it. God thus clarifies His revelations for you, so that you may be guided.", "translation_id": "Dan berpeganglah kamu semuanya kepada tali (agama) Allah, dan janganlah kamu bercerai berai, dan ingatlah akan nikmat Allah kepadamu ketika kamu dahulu (masa Jahiliyah) bermusuh-musuhan, maka Allah mempersatukan hatimu, lalu menjadilah kamu karena nikmat Allah, orang-orang yang bersaudara; dan kamu telah berada di tepi jurang neraka, lalu Allah menyelamatkan kamu dari padanya. Demikianlah Allah menerangkan ayat-ayat-Nya kepadamu, agar kamu mendapat petunjuk.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 104, "text": "وَلۡتَكُن مِّنكُمۡ أُمَّةࣱ یَدۡعُونَ إِلَى ٱلۡخَیۡرِ وَیَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَیَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝١٠٤", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "ولتكن منكم -أيها المؤمنون- جماعة تدعو إلى الخير وتأمر بالمعروف، وهو ما عُرف حسنه شرعًا وعقلا وتنهى عن المنكر، وهو ما عُرف قبحه شرعًا وعقلا وأولئك هم الفائزون بجنات النعيم.", "isBasmala": false, "translation_en": "And let there be among you a community calling to virtue, and advocating righteousness, and deterring from evil. These are the successful.", "translation_id": "Dan hendaklah ada di antara kamu segolongan umat yang menyeru kepada kebajikan, menyuruh kepada yang ma'ruf dan mencegah dari yang munkar; merekalah orang-orang yang beruntung.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 105, "text": "وَلَا تَكُونُوا۟ كَٱلَّذِینَ تَفَرَّقُوا۟ وَٱخۡتَلَفُوا۟ مِنۢ بَعۡدِ مَا جَاۤءَهُمُ ٱلۡبَیِّنَـٰتُۚ وَأُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابٌ عَظِیمࣱ ۝١٠٥", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "ولا تكونوا -أيها المؤمنون- كأهل الكتاب الذين وقعت بينهم العداوة والبغضاء فتفرَّقوا شيعًا وأحزابًا، واختلفوا في أصول دينهم من بعد أن اتضح لهم الحق، وأولئك مستحقون لعذابٍ عظيم موجع.", "isBasmala": false, "translation_en": "And do not be like those who separated and disputed after the clear proofs came to them; for them is a great punishment.", "translation_id": "Dan janganlah kamu menyerupai orang-orang yang bercerai-berai dan berselisih sesudah datang keterangan yang jelas kepada mereka. Mereka itulah orang-orang yang mendapat siksa yang berat,", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 106, "text": "یَوۡمَ تَبۡیَضُّ وُجُوهࣱ وَتَسۡوَدُّ وُجُوهࣱۚ فَأَمَّا ٱلَّذِینَ ٱسۡوَدَّتۡ وُجُوهُهُمۡ أَكَفَرۡتُم بَعۡدَ إِیمَـٰنِكُمۡ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ۝١٠٦", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "يوم القيامة تَبْيَضُّ وجوه أهل السعادة الذين آمنوا بالله ورسوله، وامتثلوا أمره، وتَسْوَدُّ وجوه أهل الشقاوة ممن كذبوا رسوله، وعصوا أمره. فأما الذين اسودَّت وجوههم، فيقال لهم توبيخًا: أكفرتم بعد إيمانكم، فاخترتم الكفر على الإيمان؟ فذوقوا العذاب بسبب كفركم.", "isBasmala": false, "translation_en": "On the Day when some faces will be whitened, and some faces will be blackened. As for those whose faces are blackened: \"Did you disbelieve after your belief?\" Then taste the punishment for having disbelieved.", "translation_id": "pada hari yang di waktu itu ada muka yang putih berseri, dan ada pula muka yang hitam muram. Adapun orang-orang yang hitam muram mukanya (kepada mereka dikatakan): \"Kenapa kamu kafir sesudah kamu beriman? Karena itu rasakanlah azab disebabkan kekafiranmu itu\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 107, "text": "وَأَمَّا ٱلَّذِینَ ٱبۡیَضَّتۡ وُجُوهُهُمۡ فَفِی رَحۡمَةِ ٱللَّهِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝١٠٧", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "وأما الذين ابيضَّتْ وجوهم بنضرة النعيم، وما بُشِّروا به من الخير، فهم في جنة الله ونعيمها، وهم باقون فيها، لا يخرجون منها أبدًا.", "isBasmala": false, "translation_en": "But as for those whose faces are whitened: they are in God's mercy, remaining in it forever.", "translation_id": "Adapun orang-orang yang putih berseri mukanya, maka mereka berada dalam rahmat Allah (surga); mereka kekal di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 108, "text": "تِلۡكَ ءَایَـٰتُ ٱللَّهِ نَتۡلُوهَا عَلَیۡكَ بِٱلۡحَقِّۗ وَمَا ٱللَّهُ یُرِیدُ ظُلۡمࣰا لِّلۡعَـٰلَمِینَ ۝١٠٨", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "هذه آيات الله وبراهينه الساطعة، نتلوها ونقصُّها عليك -أيها الرسول- بالصدق واليقين. وما الله بظالم أحدًا من خلقه، ولا بمنقص شيئًا من أعمالهم؛ لأنه الحاكم العدل الذي لا يجور.", "isBasmala": false, "translation_en": "These are the revelations of God. We recite them to you in truth. God desires no injustice for mankind.", "translation_id": "Itulah ayat-ayat Allah. Kami bacakan ayat-ayat itu kepadamu dengan benar; dan tiadalah Allah berkehendak untuk menganiaya hamba-hamba-Nya.", "manzil": 1, "manzil_display": ""}], "64": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 109, "text": "وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ۝١٠٩", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "ولله ما في السموات وما في الأرض، ملكٌ له وحده خلقًا وتدبيرًا، ومصير جميع الخلائق إليه وحده، فيجازي كلا على قدر استحقاقه.", "isBasmala": false, "translation_en": "To God belongs everything in the heavens and everything on earth, and to God all events are referred.", "translation_id": "Kepunyaan Allah-lah segala yang ada di langit dan di bumi; dan kepada Allahlah dikembalikan segala urusan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 110, "text": "كُنتُمۡ خَیۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَـٰبِ لَكَانَ خَیۡرࣰا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَـٰسِقُونَ ۝١١٠", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "أنتم - يا أمة محمد - خير الأمم وأنفع الناس للناس، تأمرون بالمعروف، وهو ما عُرف حسنه شرعًا وعقلا وتنهون عن المنكر، وهو ما عُرف قبحه شرعًا وعقلا وتصدقون بالله تصديقًا جازمًا يؤيده العمل. ولو آمن أهل الكتاب من اليهود والنصارى بمحمد صلى الله عليه وسلم وما جاءهم به من عند الله كما آمنتم، لكان خيرا لهم في الدنيا والآخرة، منهم المؤمنون المصدقون برسالة محمد صلى الله عليه وسلم العاملون بها، وهم قليل، وأكثرهم الخارجون عن دين الله وطاعته.", "isBasmala": false, "translation_en": "You are the best community that ever emerged for humanity: you advocate what is moral, and forbid what is immoral, and believe in God. Had the People of the Scripture believed, it would have been better for them. Among them are the believers, but most of them are sinners.", "translation_id": "Kamu adalah umat yang terbaik yang dilahirkan untuk manusia, menyuruh kepada yang ma'ruf, dan mencegah dari yang munkar, dan beriman kepada Allah. Sekiranya Ahli Kitab beriman, tentulah itu lebih baik bagi mereka, di antara mereka ada yang beriman, dan kebanyakan mereka adalah orang-orang yang fasik.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 111, "text": "لَن یَضُرُّوكُمۡ إِلَّاۤ أَذࣰىۖ وَإِن یُقَـٰتِلُوكُمۡ یُوَلُّوكُمُ ٱلۡأَدۡبَارَ ثُمَّ لَا یُنصَرُونَ ۝١١١", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "لن يضركم هؤلاء الفاسقون من أهل الكتاب إلا ما يؤذي أسماعكم من ألفاظ الشرك والكفر وغير ذلك، فإن يقاتلوكم يُهْزَموا، ويهربوا مولِّين الأدبار، ثم لا ينصرون عليكم بأي حال.", "isBasmala": false, "translation_en": "They will do you no harm, beyond insulting you. And if they fight you, they will turn around and flee, then they will not be helped.", "translation_id": "Mereka sekali-kali tidak akan dapat membuat mudharat kepada kamu, selain dari gangguan-gangguan celaan saja, dan jika mereka berperang dengan kamu, pastilah mereka berbalik melarikan diri ke belakang (kalah). Kemudian mereka tidak mendapat pertolongan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 112, "text": "ضُرِبَتۡ عَلَیۡهِمُ ٱلذِّلَّةُ أَیۡنَ مَا ثُقِفُوۤا۟ إِلَّا بِحَبۡلࣲ مِّنَ ٱللَّهِ وَحَبۡلࣲ مِّنَ ٱلنَّاسِ وَبَاۤءُو بِغَضَبࣲ مِّنَ ٱللَّهِ وَضُرِبَتۡ عَلَیۡهِمُ ٱلۡمَسۡكَنَةُۚ ذَ ٰلِكَ بِأَنَّهُمۡ كَانُوا۟ یَكۡفُرُونَ بِـَٔایَـٰتِ ٱللَّهِ وَیَقۡتُلُونَ ٱلۡأَنۢبِیَاۤءَ بِغَیۡرِ حَقࣲّۚ ذَ ٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ یَعۡتَدُونَ ۝١١٢", "juz": 4, "hizb": "(* ح 7*)", "tafsir": "جعل الله الهوان والصغار أمرًا لازمًا لا يفارق اليهود، فهم أذلاء محتقرون أينما وُجِدوا، إلا بعهد من الله وعهد من الناس يأمنون به على أنفسهم وأموالهم، وذلك هو عقد الذمة لهم وإلزامهم أحكام الإسلام، ورجعوا بغضب من الله مستحقين له، وضُربت عليهم الذلَّة والمسكنة، فلا ترى اليهوديَّ إلا وعليه الخوف والرعب من أهل الإيمان؛ ذلك الذي جعله الله عليهم بسبب كفرهم بالله، وتجاوزهم حدوده، وقَتْلهم الأنبياء ظلمًا واعتداء، وما جرَّأهم على هذا إلا ارتكابهم للمعاصي، وتجاوزهم حدود الله.", "isBasmala": false, "translation_en": "They shall be humiliated wherever they are encountered, except through a rope from God, and a rope from the people; and they incurred wrath from God, and were stricken with misery. That is because they rejected God's revelations, and killed the prophets unjustly. That is because they rebelled and committed aggression.", "translation_id": "Mereka diliputi kehinaan di mana saja mereka berada, kecuali jika mereka berpegang kepada tali (agama) Allah dan tali (perjanjian) dengan manusia, dan mereka kembali mendapat kemurkaan dari Allah dan mereka diliputi kerendahan. Yang demikian itu karena mereka kafir kepada ayat-ayat Allah dan membunuh para nabi tanpa alasan yang benar. Yang demikian itu disebabkan mereka durhaka dan melampaui batas.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 113, "text": "۞ لَیۡسُوا۟ سَوَاۤءࣰۗ مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ أُمَّةࣱ قَاۤىِٕمَةࣱ یَتۡلُونَ ءَایَـٰتِ ٱللَّهِ ءَانَاۤءَ ٱلَّیۡلِ وَهُمۡ یَسۡجُدُونَ ۝١١٣", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "ليس أهل الكتاب متساوين: فمنهم جماعة مستقيمة على أمر الله مؤمنة برسوله محمد صلى الله عليه وسلم، يقومون الليل مرتلين آيات القرآن الكريم، مقبلين على مناجاة الله في صلواتهم.", "isBasmala": false, "translation_en": "They are not alike. Among the People of the Scripture is a community that is upright; they recite God's revelations throughout the night, and they prostrate themselves.", "translation_id": "Mereka itu tidak sama; di antara Ahli Kitab itu ada golongan yang berlaku lurus, mereka membaca ayat-ayat Allah pada beberapa waktu di malam hari, sedang mereka juga bersujud (sembahyang).", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 114, "text": "یُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَیَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَیَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَیُسَـٰرِعُونَ فِی ٱلۡخَیۡرَ ٰتِۖ وَأُو۟لَـٰۤىِٕكَ مِنَ ٱلصَّـٰلِحِینَ ۝١١٤", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "يؤمنون بالله واليوم الآخر، ويأمرون بالخير كله، وينهون عن الشر كلِّه، ويبادرون إلى فعل الخيرات، وأولئك مِن عباد الله الصالحين.", "isBasmala": false, "translation_en": "They believe in God and the Last Day, and advocate righteousness and forbid evil, and are quick to do good deeds. These are among the righteous.", "translation_id": "Mereka beriman kepada Allah dan hari penghabisan, mereka menyuruh kepada yang ma'ruf, dan mencegah dari yang munkar dan bersegera kepada (mengerjakan) pelbagai kebajikan; mereka itu termasuk orang-orang yang saleh.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 115, "text": "وَمَا یَفۡعَلُوا۟ مِنۡ خَیۡرࣲ فَلَن یُكۡفَرُوهُۗ وَٱللَّهُ عَلِیمُۢ بِٱلۡمُتَّقِینَ ۝١١٥", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "وأيُّ عمل قلَّ أو كَثُر من أعمال الخير تعمله هذه الطائفة المؤمنة فلن يضيع عند الله، بل يُشكر لهم، ويجازون عليه. والله عليم بالمتقين الذين فعلوا الخيرات وابتعدوا عن المحرمات؛ ابتغاء رضوان الله، وطلبًا لثوابه.", "isBasmala": false, "translation_en": "Whatever good they do, they will not be denied it. God knows the righteous.", "translation_id": "Dan apa saja kebajikan yang mereka kerjakan, maka sekali-kali mereka tidak dihalangi (menenerima pahala)nya; dan Allah Maha Mengetahui orang-orang yang bertakwa.", "manzil": 1, "manzil_display": ""}], "65": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 116, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ لَن تُغۡنِیَ عَنۡهُمۡ أَمۡوَ ٰلُهُمۡ وَلَاۤ أَوۡلَـٰدُهُم مِّنَ ٱللَّهِ شَیۡـࣰٔاۖ وَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝١١٦", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "إن الذين كفروا بآيات الله، وكذبوا رسله، لن تدفع عنهم أموالهم ولا أولادهم شيئًا من عذاب الله في الدنيا ولا في الآخرة، وأولئك أصحاب النار الملازمون لها، لا يخرجون منها.", "isBasmala": false, "translation_en": "As for those who disbelieve, neither their possessions nor their children will avail them anything against God. These are the inhabitants of the Fire, abiding therein forever.", "translation_id": "Sesungguhnya orang-orang yang kafir baik harta mereka maupun anak-anak mereka, sekali-kali tidak dapat menolak azab Allah dari mereka sedikitpun. Dan mereka adalah penghuni neraka; mereka kekal di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 117, "text": "مَثَلُ مَا یُنفِقُونَ فِی هَـٰذِهِ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا كَمَثَلِ رِیحࣲ فِیهَا صِرٌّ أَصَابَتۡ حَرۡثَ قَوۡمࣲ ظَلَمُوۤا۟ أَنفُسَهُمۡ فَأَهۡلَكَتۡهُۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَـٰكِنۡ أَنفُسَهُمۡ یَظۡلِمُونَ ۝١١٧", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "مَثَلُ ما ينفق الكافرون في وجوه الخير في هذه الحياة الدنيا وما يؤملونه من ثواب، كمثل ريح فيها برد شديد هَبَّتْ على زرع قوم كانوا يرجون خيره، وبسبب ذنوبهم لم تُبْقِ الريح منه شيئًا. وهؤلاء الكافرون لا يجدون في الآخرة ثوابًا، وما ظلمهم الله بذلك، ولكنهم ظلموا أنفسهم بكفرهم وعصيانهم.", "isBasmala": false, "translation_en": "The parable of what they spend in this worldly life is that of a frosty wind that strikes the harvest of a people who have wronged their souls, and destroys it. God did not wrong them, but they wronged their own selves.", "translation_id": "Perumpamaan harta yang mereka nafkahkan di dalam kehidupan dunia ini, adalah seperti perumpamaan angin yang mengandung hawa yang sangat dingin, yang menimpa tanaman kaum yang menganiaya diri sendiri, lalu angin itu merusaknya. Allah tidak menganiaya mereka, akan tetapi merekalah yang menganiaya diri mereka sendiri.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 118, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةࣰ مِّن دُونِكُمۡ لَا یَأۡلُونَكُمۡ خَبَالࣰا وَدُّوا۟ مَا عَنِتُّمۡ قَدۡ بَدَتِ ٱلۡبَغۡضَاۤءُ مِنۡ أَفۡوَ ٰهِهِمۡ وَمَا تُخۡفِی صُدُورُهُمۡ أَكۡبَرُۚ قَدۡ بَیَّنَّا لَكُمُ ٱلۡـَٔایَـٰتِۖ إِن كُنتُمۡ تَعۡقِلُونَ ۝١١٨", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تتخذوا الكافرين أولياء من دون المؤمنين، تُطْلعونهم على أسراركم، فهؤلاء لا يَفْتُرون عن إفساد حالكم، وهم يفرحون بما يصيبكم من ضرر ومكروه، وقد ظهرت شدة البغض في كلامهم، وما تخفي صدورهم من العداوة لكم أكبر وأعظم. قد بيَّنَّا لكم البراهين والحجج، لتتعظوا وتحذروا، إن كنتم تعقلون عن الله مواعظه وأمره ونهيه.", "isBasmala": false, "translation_en": "O you who believe! Do not befriend outsiders who never cease to wish you harm. They love to see you suffer. Hatred has already appeared from their mouths, but what their hearts conceal is worse. We have made the messages clear for you, if you understand.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu ambil menjadi teman kepercayaanmu orang-orang yang, di luar kalanganmu (karena) mereka tidak henti-hentinya (menimbulkan) kemudharatan bagimu. Mereka menyukai apa yang menyusahkan kamu. Telah nyata kebencian dari mulut mereka, dan apa yang disembunyikan oleh hati mereka adalah lebih besar lagi. Sungguh telah Kami terangkan kepadamu ayat-ayat (Kami), jika kamu memahaminya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 119, "text": "هَـٰۤأَنتُمۡ أُو۟لَاۤءِ تُحِبُّونَهُمۡ وَلَا یُحِبُّونَكُمۡ وَتُؤۡمِنُونَ بِٱلۡكِتَـٰبِ كُلِّهِۦ وَإِذَا لَقُوكُمۡ قَالُوۤا۟ ءَامَنَّا وَإِذَا خَلَوۡا۟ عَضُّوا۟ عَلَیۡكُمُ ٱلۡأَنَامِلَ مِنَ ٱلۡغَیۡظِۚ قُلۡ مُوتُوا۟ بِغَیۡظِكُمۡۗ إِنَّ ٱللَّهَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝١١٩", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "ها هوذا الدليل على خطئكم في محبتهم، فأنتم تحبونهم وتحسنون إليهم، وهم لا يحبونكم ويحملون لكم العداوة والبغضاء، وأنتم تؤمنون بالكتب المنزلة كلها ومنها كتابهم، وهم لا يؤمنون بكتابكم، فكيف تحبونهم؟ وإذا لقوكم قالوا -نفاقًا-: آمنَّا وصدَّقْنا، وإذا خلا بعضهم إلى بعض بدا عليهم الغم والحزن، فعَضُّوا أطراف أصابعهم من شدة الغضب، لما يرون من ألفة المسلمين واجتماع كلمتهم، وإعزاز الإسلام، وإذلالهم به. قل لهم -أيها الرسول-: موتوا بشدة غضبكم. إن الله مطَّلِع على ما تخفي الصدور، وسيجازي كلا على ما قدَّم مِن خير أو شر.", "isBasmala": false, "translation_en": "There you are, you love them, but they do not love you, and you believe in the entire scripture. And when they meet you, they say, \"We believe;\" but when they are alone, they bite their fingers in rage at you. Say, \"Die in your rage; God knows what is within the hearts.\"", "translation_id": "Beginilah kamu, kamu menyukai mereka, padahal mereka tidak menyukai kamu, dan kamu beriman kepada kitab-kitab semuanya. Apabila mereka menjumpai kamu, mereka berkata \"Kami beriman\", dan apabila mereka menyendiri, mereka menggigit ujung jari antaran marah bercampur benci terhadap kamu. Katakanlah (kepada mereka): \"Matilah kamu karena kemarahanmu itu\". Sesungguhnya Allah mengetahui segala isi hati.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 120, "text": "إِن تَمۡسَسۡكُمۡ حَسَنَةࣱ تَسُؤۡهُمۡ وَإِن تُصِبۡكُمۡ سَیِّئَةࣱ یَفۡرَحُوا۟ بِهَاۖ وَإِن تَصۡبِرُوا۟ وَتَتَّقُوا۟ لَا یَضُرُّكُمۡ كَیۡدُهُمۡ شَیۡـًٔاۗ إِنَّ ٱللَّهَ بِمَا یَعۡمَلُونَ مُحِیطࣱ ۝١٢٠", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "ومن عداوة هؤلاء أنكم -أيها المؤمنون- إن نزل بكم أمرٌ حسن مِن نصر وغنيمة ظهرت عليهم الكآبة والحزن، وإن وقع بكم مكروه من هزيمة أو نقص في الأموال والأنفس والثمرات فرحوا بذلك، وإن تصبروا على ما أصابكم، وتتقوا الله فيما أمركم به ونهاكم عنه، لا يضركم أذى مكرهم. والله بجميع ما يعمل هؤلاء الكفار من الفساد محيط، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "If something good happens to you, it upsets them; but if something bad befalls you, they rejoice at it. But if you persevere and maintain righteousness, their schemes will not harm you at all. God comprehends what they do.", "translation_id": "Jika kamu memperoleh kebaikan, niscaya mereka bersedih hati, tetapi Jika kamu mendapat bencana, mereka bergembira karenanya. Jika kamu bersabar dan bertakwa, niscaya tipu daya mereka sedikitpun tidak mendatangkan kemudharatan kepadamu. Sesungguhnya Allah mengetahui segala apa yang mereka kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 121, "text": "وَإِذۡ غَدَوۡتَ مِنۡ أَهۡلِكَ تُبَوِّئُ ٱلۡمُؤۡمِنِینَ مَقَـٰعِدَ لِلۡقِتَالِۗ وَٱللَّهُ سَمِیعٌ عَلِیمٌ ۝١٢١", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "واذكر -أيها الرسول- حين خَرَجْتَ من بيتك لابسًا عُدَّة الحرب، تنظم صفوف أصحابك، وتُنْزِل كل واحد في منزله للقاء المشركين في غزوة \"أُحُد\". والله سميع لأقوالكم، عليم بأفعالكم.", "isBasmala": false, "translation_en": "Remember when you left your home in the morning, to assign battle-positions for the believers. God is Hearing and Knowing.", "translation_id": "Dan (ingatlah), ketika kamu berangkat pada pagi hari dari (rumah) keluargamu akan menempatkan para mukmin pada beberapa tempat untuk berperang. Dan Allah Maha Mendengar lagi Maha Mengetahui,", "manzil": 1, "manzil_display": ""}], "66": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 122, "text": "إِذۡ هَمَّت طَّاۤىِٕفَتَانِ مِنكُمۡ أَن تَفۡشَلَا وَٱللَّهُ وَلِیُّهُمَاۗ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ۝١٢٢", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "اذكر -أيها الرسول- ما كان من أمر بني سَلِمة وبني حارثة حين حدثتهم أنفسهم بالرجوع مع زعيمهم المنافق عبد الله بن أُبيٍّ؛ خوفًا من لقاء العدو، ولكن الله عصمهم وحفظهم، فساروا معك متوكلين على الله. وعلى الله وحده فليتوكل المؤمنون.", "isBasmala": false, "translation_en": "When two groups among you almost faltered, but God was their Protector. So in God let the believers put their trust.", "translation_id": "ketika dua golongan dari padamu ingin (mundur) karena takut, padahal Allah adalah penolong bagi kedua golongan itu. Karena itu hendaklah kepada Allah saja orang-orang mukmin bertawakkal.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 123, "text": "وَلَقَدۡ نَصَرَكُمُ ٱللَّهُ بِبَدۡرࣲ وَأَنتُمۡ أَذِلَّةࣱۖ فَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تَشۡكُرُونَ ۝١٢٣", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "ولقد نصركم الله -أيها المؤمنون- بـ \"بدر\" على أعدائكم المشركين مع قلة عَدَدكم وعُدَدكم، فخافوا الله بفعل أوامره واجتناب نواهيه؛ لعلكم تشكرون له نعمه.", "isBasmala": false, "translation_en": "God had given you victory at Badr, when you were weak. So fear God, that you may be thankful.", "translation_id": "Sungguh Allah telah menolong kamu dalam peperangan Badar, padahal kamu adalah (ketika itu) orang-orang yang lemah. Karena itu bertakwalah kepada Allah, supaya kamu mensyukuri-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 124, "text": "إِذۡ تَقُولُ لِلۡمُؤۡمِنِینَ أَلَن یَكۡفِیَكُمۡ أَن یُمِدَّكُمۡ رَبُّكُم بِثَلَـٰثَةِ ءَالَـٰفࣲ مِّنَ ٱلۡمَلَـٰۤىِٕكَةِ مُنزَلِینَ ۝١٢٤", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "اذكر -أيها الرسول- ما كان من أمر أصحابك في \"بدر\" حين شقَّ عليهم أن يأتي مَدَد للمشركين، فأوحينا إليك أن تقول لهم: ألن تكفيكم معونة ربكم بأن يمدكم بثلاثة آلاف من الملائكة مُنْزَلين من السماء إلى أرض المعركة، يثبتونكم، ويقاتلون معكم؟", "isBasmala": false, "translation_en": "When you said to the believers, \"Is it not enough for you that your Lord has reinforced you with three thousand angels, sent down?\"", "translation_id": "(Ingatlah), ketika kamu mengatakan kepada orang mukmin: \"Apakah tidak cukup bagi kamu Allah membantu kamu dengan tiga ribu malaikat yang diturunkan (dari langit)?\"", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 125, "text": "بَلَىٰۤۚ إِن تَصۡبِرُوا۟ وَتَتَّقُوا۟ وَیَأۡتُوكُم مِّن فَوۡرِهِمۡ هَـٰذَا یُمۡدِدۡكُمۡ رَبُّكُم بِخَمۡسَةِ ءَالَـٰفࣲ مِّنَ ٱلۡمَلَـٰۤىِٕكَةِ مُسَوِّمِینَ ۝١٢٥", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "بلى يكفيكم هذا المَدَد. وبشارة أخرى لكم: إن تصبروا على لقاء العدو وتتقوا الله بفِعْل ما أمركم به واجتناب ما نهاكم عنه، ويأت كفار \"مكة\" على الفور مسرعين لقتالكم، يظنون أنهم يستأصلونكم، فإن الله يمدكم بخمسة آلاف من الملائكة مسوِّمين أي: قد أعلموا أنفسهم وخيولهم بعلامات واضحات.", "isBasmala": false, "translation_en": "It is; but if you persevere and remain cautious, and they attack you suddenly, your Lord will reinforce you with five thousand angels, well trained.", "translation_id": "Ya (cukup), jika kamu bersabar dan bersiap-siaga, dan mereka datang menyerang kamu dengan seketika itu juga, niscaya Allah menolong kamu dengan lima ribu Malaikat yang memakai tanda.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 126, "text": "وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ لَكُمۡ وَلِتَطۡمَىِٕنَّ قُلُوبُكُم بِهِۦۗ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ ۝١٢٦", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "وما جعل الله هذا الإمداد بالملائكة إلا بشرى لكم يبشركم بها ولتطمئن قلوبكم، وتطيب بوعد الله لكم. وما النصر إلا من عند الله العزيز الذي لا يغالَب، الحكيم في تدبيره وفعله.", "isBasmala": false, "translation_en": "God made it but a message of hope for you, and to reassure your hearts thereby. Victory comes only from God the Almighty, the Wise.", "translation_id": "Dan Allah tidak menjadikan pemberian bala bantuan itu melainkan sebagai khabar gembira bagi (kemenangan)mu, dan agar tenteram hatimu karenanya. Dan kemenanganmu itu hanyalah dari Allah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 127, "text": "لِیَقۡطَعَ طَرَفࣰا مِّنَ ٱلَّذِینَ كَفَرُوۤا۟ أَوۡ یَكۡبِتَهُمۡ فَیَنقَلِبُوا۟ خَاۤىِٕبِینَ ۝١٢٧", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "وكان نصر الله لكم بـ \"بدْر\" ليهلك فريقًا من الكفار بالقتل، ومن نجا منهم من القتل رجع حزينًا قد ضاقت عليه نفسه، يَظْهر عليه الخزي والعار.", "isBasmala": false, "translation_en": "He thus cuts off a section of those who disbelieved, or subdues them, so they retreat disappointed.", "translation_id": "(Allah menolong kamu dalam perang Badar dan memberi bala bantuan itu) untuk membinasakan segolongan orang-orang yang kafir, atau untuk menjadikan mereka hina, lalu mereka kembali dengan tiada memperoleh apa-apa.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 128, "text": "لَیۡسَ لَكَ مِنَ ٱلۡأَمۡرِ شَیۡءٌ أَوۡ یَتُوبَ عَلَیۡهِمۡ أَوۡ یُعَذِّبَهُمۡ فَإِنَّهُمۡ ظَـٰلِمُونَ ۝١٢٨", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "ليس لك -أيها الرسول- من أمر العباد شيء، بل الأمر كله لله تعالى وحده لا شريك له، ولعل بعض هؤلاء الذين قاتلوك تنشرح صدورهم للإسلام فيسلموا، فيتوب الله عليهم. ومن بقي على كفره يعذبه الله في الدنيا والآخرة بسبب ظلمه وبغيه.", "isBasmala": false, "translation_en": "It is no concern of yours whether He redeems them or punishes them. They are wrongdoers.", "translation_id": "Tak ada sedikitpun campur tanganmu dalam urusan mereka itu atau Allah menerima taubat mereka, atau mengazab mereka karena sesungguhnya mereka itu orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 129, "text": "وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۚ یَغۡفِرُ لِمَن یَشَاۤءُ وَیُعَذِّبُ مَن یَشَاۤءُۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝١٢٩", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "ولله وحده ما في السموات وما في الأرض، يغفر لمن يشاء من عباده برحمته، ويعذب من يشاء بعدله. والله غفور لذنوب عباده، رحيم بهم.", "isBasmala": false, "translation_en": "To God belongs everything in the heavens and the earth. He forgives whom He wills, and He punishes whom He wills. God is Most Forgiving, Most Merciful.", "translation_id": "Kepunyaan Allah apa yang ada di langit dan yang ada di bumi. Dia memberi ampun kepada siapa yang Dia kehendaki; Dia menyiksa siapa yang Dia kehendaki, dan Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 130, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَأۡكُلُوا۟ ٱلرِّبَوٰۤا۟ أَضۡعَـٰفࣰا مُّضَـٰعَفَةࣰۖ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ۝١٣٠", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "يا أيها الذين صدّقوا الله ورسوله وعملوا بشرعه احذروا الربا بجميع أنواعه، ولا تأخذوا في القرض زيادة على رؤوس أموالكم وإن قلَّت، فكيف إذا كانت هذه الزيادة تتضاعف كلما حان موعد سداد الدين؟ واتقوا الله بالتزام شرعه؛ لتفوزوا في الدنيا والآخرة.", "isBasmala": false, "translation_en": "O you who believe! Do not feed on usury, compounded over and over, and fear God, so that you may prosper.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu memakan riba dengan berlipat ganda] dan bertakwalah kamu kepada Allah supaya kamu mendapat keberuntungan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 131, "text": "وَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِیۤ أُعِدَّتۡ لِلۡكَـٰفِرِینَ ۝١٣١", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "اجعلوا لأنفسكم وقاية بينكم وبين النار التي هُيِّئت للكافرين.", "isBasmala": false, "translation_en": "And guard yourselves against the Fire that is prepared for the disbelievers.", "translation_id": "Dan peliharalah dirimu dari api neraka, yang disediakan untuk orang-orang yang kafir.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 132, "text": "وَأَطِیعُوا۟ ٱللَّهَ وَٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ ۝١٣٢", "juz": 4, "hizb": "(*¼ ح 7*)", "tafsir": "وأطيعوا الله -أيها المؤمنون- فيما أمركم به من الطاعات وفيما نهاكم عنه من أكل الربا وغيره من الأشياء، وأطيعوا الرسول؛ لترحموا، فلا تعذبوا.", "isBasmala": false, "translation_en": "And obey God and the Messenger, that you may obtain mercy.", "translation_id": "Dan taatilah Allah dan Rasul, supaya kamu diberi rahmat.", "manzil": 1, "manzil_display": ""}], "67": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 133, "text": "۞ وَسَارِعُوۤا۟ إِلَىٰ مَغۡفِرَةࣲ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَـٰوَ ٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِینَ ۝١٣٣", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "وبادروا بطاعتكم لله ورسوله لاغتنام مغفرة عظيمة من ربكم وجنة واسعة، عرضها السموات والأرض، أعدها الله للمتقين.", "isBasmala": false, "translation_en": "And race towards forgiveness from your Lord, and a Garden as wide as the heavens and the earth, prepared for the righteous.", "translation_id": "Dan bersegeralah kamu kepada ampunan dari Tuhanmu dan kepada surga yang luasnya seluas langit dan bumi yang disediakan untuk orang-orang yang bertakwa,", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 134, "text": "ٱلَّذِینَ یُنفِقُونَ فِی ٱلسَّرَّاۤءِ وَٱلضَّرَّاۤءِ وَٱلۡكَـٰظِمِینَ ٱلۡغَیۡظَ وَٱلۡعَافِینَ عَنِ ٱلنَّاسِۗ وَٱللَّهُ یُحِبُّ ٱلۡمُحۡسِنِینَ ۝١٣٤", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "الذين ينفقون أموالهم في اليسر والعسر، والذين يمسكون ما في أنفسهم من الغيظ بالصبر، وإذا قَدَروا عَفَوا عمَّن ظلمهم. وهذا هو الإحسان الذي يحب الله أصحابه.", "isBasmala": false, "translation_en": "Those who give in prosperity and adversity, and those who restrain anger, and those who forgive people. God loves the doers of good.", "translation_id": "(yaitu) orang-orang yang menafkahkan (hartanya), baik di waktu lapang maupun sempit, dan orang-orang yang menahan amarahnya dan memaafkan (kesalahan) orang. Allah menyukai orang-orang yang berbuat kebajikan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 135, "text": "وَٱلَّذِینَ إِذَا فَعَلُوا۟ فَـٰحِشَةً أَوۡ ظَلَمُوۤا۟ أَنفُسَهُمۡ ذَكَرُوا۟ ٱللَّهَ فَٱسۡتَغۡفَرُوا۟ لِذُنُوبِهِمۡ وَمَن یَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ وَلَمۡ یُصِرُّوا۟ عَلَىٰ مَا فَعَلُوا۟ وَهُمۡ یَعۡلَمُونَ ۝١٣٥", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "والذين إذا ارتكبوا ذنبًا كبيرًا أو ظلموا أنفسهم بارتكاب ما دونه، ذكروا وعد الله ووعيده فلجأوا إلى ربهم تائبين، يطلبون منه أن يغفر لهم ذنوبهم، وهم موقنون أنه لا يغفر الذنوب إلا الله، فهم لذلك لا يقيمون على معصية، وهم يعلمون أنهم إن تابوا تاب الله عليهم.", "isBasmala": false, "translation_en": "And those who, when they commit an indecency or wrong themselves, remember God and ask forgiveness for their sins-and who forgives sins except God? And they do not persist in their wrongdoing while they know.", "translation_id": "Dan (juga) orang-orang yang apabila mengerjakan perbuatan keji atau menganiaya diri sendiri, mereka ingat akan Allah, lalu memohon ampun terhadap dosa-dosa mereka dan siapa lagi yang dapat mengampuni dosa selain dari pada Allah? Dan mereka tidak meneruskan perbuatan kejinya itu, sedang mereka mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 136, "text": "أُو۟لَـٰۤىِٕكَ جَزَاۤؤُهُم مَّغۡفِرَةࣱ مِّن رَّبِّهِمۡ وَجَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ وَنِعۡمَ أَجۡرُ ٱلۡعَـٰمِلِینَ ۝١٣٦", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "أولئك الموصوفون بتلك الصفات العظيمة جزاؤهم أن يستر الله ذنوبهم، ولهم جنات تجري من تحت أشجارها وقصورها المياه العذبة، خالدين فيها لا يخرجون منها أبدًا. ونِعْمَ أجر العاملين المغفرة والجنة.", "isBasmala": false, "translation_en": "Those-their reward is forgiveness from their Lord, and gardens beneath which rivers flow, abiding therein forever. How excellent is the reward of the workers.", "translation_id": "Mereka itu balasannya ialah ampunan dari Tuhan mereka dan surga yang di dalamnya mengalir sungai-sungai, sedang mereka kekal di dalamnya; dan itulah sebaik-baik pahala orang-orang yang beramal.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 137, "text": "قَدۡ خَلَتۡ مِن قَبۡلِكُمۡ سُنَنࣱ فَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُكَذِّبِینَ ۝١٣٧", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "يخاطب الله المؤمنين لـمَّا أُصيبوا يوم \"أُحد\" تعزية لهم بأنه قد مضت من قبلكم أمم، ابتُلي المؤمنون منهم بقتال الكافرين فكانت العاقبة لهم، فسيروا في الأرض معتبرين بما آل إليه أمر أولئك المكذبين بالله ورسله.", "isBasmala": false, "translation_en": "Many societies have passed away before you. So travel the earth and note the fate of the deniers.", "translation_id": "Sesungguhnya telah berlalu sebelum kamu sunnah-sunnah Allah; Karena itu berjalanlah kamu di muka bumi dan perhatikanlah bagaimana akibat orang-orang yang mendustakan (rasul-rasul).", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 138, "text": "هَـٰذَا بَیَانࣱ لِّلنَّاسِ وَهُدࣰى وَمَوۡعِظَةࣱ لِّلۡمُتَّقِینَ ۝١٣٨", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "هذا القرآن بيان وإرشاد إلى طريق الحق، وتذكير تخشع له قلوب المتقين، وهم الذين يخشون الله، وخُصُّوا بذلك؛ لأنهم هم المنتفعون به دون غيرهم.", "isBasmala": false, "translation_en": "This is a proclamation to humanity, and guidance, and advice for the righteous.", "translation_id": "(Al Quran) ini adalah penerangan bagi seluruh manusia, dan petunjuk serta pelajaran bagi orang-orang yang bertakwa.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 139, "text": "وَلَا تَهِنُوا۟ وَلَا تَحۡزَنُوا۟ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ إِن كُنتُم مُّؤۡمِنِینَ ۝١٣٩", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "ولا تضْعُفوا -أيها المؤمنون- عن قتال عدوكم، ولا تحزنوا لما أصابكم في \"أُحد\"، وأنتم الغالبون والعاقبة لكم، إن كنتم مصدقين بالله ورسوله متَّبعين شرعه.", "isBasmala": false, "translation_en": "And do not waver, nor feel remorse. You are the superior ones, if you are believers.", "translation_id": "Janganlah kamu bersikap lemah, dan janganlah (pula) kamu bersedih hati, padahal kamulah orang-orang yang paling tinggi (derajatnya), jika kamu orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 140, "text": "إِن یَمۡسَسۡكُمۡ قَرۡحࣱ فَقَدۡ مَسَّ ٱلۡقَوۡمَ قَرۡحࣱ مِّثۡلُهُۥۚ وَتِلۡكَ ٱلۡأَیَّامُ نُدَاوِلُهَا بَیۡنَ ٱلنَّاسِ وَلِیَعۡلَمَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَیَتَّخِذَ مِنكُمۡ شُهَدَاۤءَۗ وَٱللَّهُ لَا یُحِبُّ ٱلظَّـٰلِمِینَ ۝١٤٠", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "إن أصابتكم -أيها المؤمنون- جراح أو قتل في غزوة \"أُحد\" فحزنتم لذلك، فقد أصاب المشركين جراح وقتل مثل ذلك في غزوة \"بدر\". وتلك الأيام يُصَرِّفها الله بين الناس، نصر مرة وهزيمة أخرى، لما في ذلك من الحكمة، حتى يظهر ما علمه الله في الأزل ليميز الله المؤمن الصادق مِن غيره، ويُكْرِمَ أقوامًا منكم بالشهادة. والله لا يحب الذين ظلموا أنفسهم، وقعدوا عن القتال في سبيله.", "isBasmala": false, "translation_en": "If a wound afflicts you, a similar wound has afflicted the others. Such days We alternate between the people, that God may know those who believe, and take martyrs from among you. God does not love the evildoers.", "translation_id": "Jika kamu (pada perang Uhud) mendapat luka, maka sesungguhnya kaum (kafir) itupun (pada perang Badar) mendapat luka yang serupa. Dan masa (kejayaan dan kehancuran) itu Kami pergilirkan diantara manusia (agar mereka mendapat pelajaran); dan supaya Allah membedakan orang-orang yang beriman (dengan orang-orang kafir) supaya sebagian kamu dijadikan-Nya (gugur sebagai) syuhada'. Dan Allah tidak menyukai orang-orang yang zalim,", "manzil": 1, "manzil_display": ""}], "68": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 141, "text": "وَلِیُمَحِّصَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَیَمۡحَقَ ٱلۡكَـٰفِرِینَ ۝١٤١", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "وهذه الهزيمة التي وقعت في \"أُحد\" كانت اختبارًا وتصفية للمؤمنين، وتخليصًا لهم من المنافقين وهلاكًا للكافرين.", "isBasmala": false, "translation_en": "So that God may prove those who believe, and eliminate the disbelievers.", "translation_id": "Dan agar Allah membersihkan orang-orang yang beriman (dari dosa mereka) dan membinasakan orang-orang yang kafir.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 142, "text": "أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُوا۟ ٱلۡجَنَّةَ وَلَمَّا یَعۡلَمِ ٱللَّهُ ٱلَّذِینَ جَـٰهَدُوا۟ مِنكُمۡ وَیَعۡلَمَ ٱلصَّـٰبِرِینَ ۝١٤٢", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "يا أصحاب محمد -صلى الله عليه وسلم- أظننتم أن تدخلوا الجنة، ولم تُبْتَلوا بالقتال والشدائد؟ لا يحصل لكم دخولها حتى تُبْتلوا، ويعلم الله -علما ظاهرا للخلق- المجاهدين منكم في سبيله، والصابرين على مقاومة الأعداء.", "isBasmala": false, "translation_en": "Or do you expect to enter Paradise, before God has distinguished those among you who strive, and before He has distinguished the steadfast?", "translation_id": "Apakah kamu mengira bahwa kamu akan masuk surga, padahal belum nyata bagi Allah orang-orang yang berjihad diantaramu dan belum nyata orang-orang yang sabar.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 143, "text": "وَلَقَدۡ كُنتُمۡ تَمَنَّوۡنَ ٱلۡمَوۡتَ مِن قَبۡلِ أَن تَلۡقَوۡهُ فَقَدۡ رَأَیۡتُمُوهُ وَأَنتُمۡ تَنظُرُونَ ۝١٤٣", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "ولقد كنتم -أيها المؤمنون- قبل غزوة \"أُحد\" تتمنون لقاء العدو؛ لتنالوا شرف الجهاد والاستشهاد في سبيل الله الذي حَظِي به إخوانكم في غزوة \"بدر\"، فها هو ذا قد حصل لكم الذي تمنيتموه وطلبتموه، فدونكم فقاتلوا وصابروا.", "isBasmala": false, "translation_en": "You used to wish for death before you have faced it. Now you have seen it before your own eyes.", "translation_id": "Sesungguhnya kamu mengharapkan mati (syahid) sebelum kamu menghadapinya; (sekarang) sungguh kamu telah melihatnya dan kamu menyaksikannya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 144, "text": "وَمَا مُحَمَّدٌ إِلَّا رَسُولࣱ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُۚ أَفَإِی۟ن مَّاتَ أَوۡ قُتِلَ ٱنقَلَبۡتُمۡ عَلَىٰۤ أَعۡقَـٰبِكُمۡۚ وَمَن یَنقَلِبۡ عَلَىٰ عَقِبَیۡهِ فَلَن یَضُرَّ ٱللَّهَ شَیۡـࣰٔاۗ وَسَیَجۡزِی ٱللَّهُ ٱلشَّـٰكِرِینَ ۝١٤٤", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "وما محمد إلا رسول من جنس الرسل الذين قبله يبلغ رسالة ربه. أفإن مات بانقضاء أجله أو قُتِل كما أشاعه الأعداء رجعتم عن دينكم،، تركتم ما جاءكم به نبيكم؟ ومن يرجِعُ منكم عن دينه فلن يضر الله شيئًا، إنما يضر نفسه ضررًا عظيمًا. أما مَن ثبت على الإيمان وشكر ربه على نعمة الإسلام، فإن الله يجزيه أحسن الجزاء.", "isBasmala": false, "translation_en": "Muhammad is no more than a messenger. Messengers have passed on before him. If he dies or gets killed, will you turn on your heels? He who turns on his heels will not harm God in any way. And God will reward the appreciative.", "translation_id": "Muhammad itu tidak lain hanyalah seorang rasul, sungguh telah berlalu sebelumnya beberapa orang rasul. Apakah Jika dia wafat atau dibunuh kamu berbalik ke belakang (murtad)? Barangsiapa yang berbalik ke belakang, maka ia tidak dapat mendatangkan mudharat kepada Allah sedikitpun, dan Allah akan memberi balasan kepada orang-orang yang bersyukur.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 145, "text": "وَمَا كَانَ لِنَفۡسٍ أَن تَمُوتَ إِلَّا بِإِذۡنِ ٱللَّهِ كِتَـٰبࣰا مُّؤَجَّلࣰاۗ وَمَن یُرِدۡ ثَوَابَ ٱلدُّنۡیَا نُؤۡتِهِۦ مِنۡهَا وَمَن یُرِدۡ ثَوَابَ ٱلۡـَٔاخِرَةِ نُؤۡتِهِۦ مِنۡهَاۚ وَسَنَجۡزِی ٱلشَّـٰكِرِینَ ۝١٤٥", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "لن يموت أحد إلا بإذن الله وقدره وحتى يستوفي المدة التي قدرها الله له كتابًا مؤجَّلا. ومن يطلب بعمله عَرَض الدنيا، نعطه ما قسمناه له من رزق، ولا حظَّ له في الآخرة، ومن يطلب بعمله الجزاء من الله في الآخرة نمنحه ما طلبه، ونؤته جزاءه وافرًا مع ما لَه في الدنيا من رزق مقسوم، فهذا قد شَكَرَنا بطاعته وجهاده، وسنجزي الشاكرين خيرًا.", "isBasmala": false, "translation_en": "No soul can die except by God's leave, at a predetermined time. Whoever desires the reward of the world, We will give him some of it; and whoever desires the reward of the Hereafter, We will give him some of it; and We will reward the appreciative.", "translation_id": "Sesuatu yang bernyawa tidak akan mati melainkan dengan izin Allah, sebagai ketetapan yang telah ditentukan waktunya. Barang siapa menghendaki pahala dunia, niscaya Kami berikan kepadanya pahala dunia itu, dan barang siapa menghendaki pahala akhirat, Kami berikan (pula) kepadanya pahala akhirat itu. Dan kami akan memberi balasan kepada orang-orang yang bersyukur.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 146, "text": "وَكَأَیِّن مِّن نَّبِیࣲّ قَـٰتَلَ مَعَهُۥ رِبِّیُّونَ كَثِیرࣱ فَمَا وَهَنُوا۟ لِمَاۤ أَصَابَهُمۡ فِی سَبِیلِ ٱللَّهِ وَمَا ضَعُفُوا۟ وَمَا ٱسۡتَكَانُوا۟ۗ وَٱللَّهُ یُحِبُّ ٱلصَّـٰبِرِینَ ۝١٤٦", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "كثير من الأنبياء السابقين قاتل معهم جموع كثيرة من أصحابهم، فما ضعفوا لِمَا نزل بهم من جروح أو قتل؛ لأن ذلك في سبيل ربهم، وما عَجَزوا، ولا خضعوا لعدوهم، إنما صبروا على ما أصابهم. والله يحب الصابرين.", "isBasmala": false, "translation_en": "How many a prophet fought alongside him numerous godly people? They did not waver for what afflicted them in the cause of God, nor did they weaken, nor did they give in. God loves those who endure.", "translation_id": "Dan berapa banyaknya nabi yang berperang bersama-sama mereka sejumlah besar dari pengikut(nya) yang bertakwa. Mereka tidak menjadi lemah karena bencana yang menimpa mereka di jalan Allah, dan tidak lesu dan tidak (pula) menyerah (kepada musuh). Allah menyukai orang-orang yang sabar.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 147, "text": "وَمَا كَانَ قَوۡلَهُمۡ إِلَّاۤ أَن قَالُوا۟ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِیۤ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ ۝١٤٧", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "وما كان قول هؤلاء الصابرين إلا أن قالوا: ربنا اغفر لنا ذنوبنا، وما وقع منا مِن تجاوزٍ في أمر ديننا، وثبِّت أقدامنا حتى لا نفرَّ من قتال عدونا، وانصرنا على مَن جحد وحدانيتك ونبوة أنبيائك.", "isBasmala": false, "translation_en": "Their only words were, \"Our Lord, forgive us our offences, and our excesses in our conduct, and strengthen our foothold, and help us against the disbelieving people.\"", "translation_id": "Tidak ada doa mereka selain ucapan: \"Ya Tuhan kami, ampunilah dosa-dosa kami dan tindakan-tindakan kami yang berlebih-lebihan dalam urusan kami dan tetapkanlah pendirian kami, dan tolonglah kami terhadap kaum yang kafir\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 148, "text": "فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡیَا وَحُسۡنَ ثَوَابِ ٱلۡـَٔاخِرَةِۗ وَٱللَّهُ یُحِبُّ ٱلۡمُحۡسِنِینَ ۝١٤٨", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "فأعطى الله أولئك الصابرين جزاءهم في الدنيا بالنصر على أعدائهم، وبالتمكين لهم في الأرض، وبالجزاء الحسن العظيم في الآخرة، وهو جنات النعيم. والله يحب كلَّ مَن أحسن عبادته لربه ومعاملته لخلقه.", "isBasmala": false, "translation_en": "So God gave them the reward of this world, and the excellent reward of the Hereafter. God loves the doers of good.", "translation_id": "Karena itu Allah memberikan kepada mereka pahala di dunia dan pahala yang baik di akhirat. Dan Allah menyukai orang-orang yang berbuat kebaikan.", "manzil": 1, "manzil_display": ""}], "69": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 149, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن تُطِیعُوا۟ ٱلَّذِینَ كَفَرُوا۟ یَرُدُّوكُمۡ عَلَىٰۤ أَعۡقَـٰبِكُمۡ فَتَنقَلِبُوا۟ خَـٰسِرِینَ ۝١٤٩", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إن تطيعوا الذين جحدوا ألوهيتي، ولم يؤمنوا برسلي من اليهود والنصارى والمنافقين والمشركين فيما يأمرونكم به وينهونكم عنه، يضلوكم عن طريق الحق، وترتدُّوا عن دينكم، فتعودوا بالخسران المبين والهلاك المحقق.", "isBasmala": false, "translation_en": "O you who believe! If you obey those who disbelieve, they will turn you back on your heels, and you end up losers.", "translation_id": "Hai orang-orang yang beriman, jika kamu mentaati orang-orang yang kafir itu, niscaya mereka mengembalikan kamu ke belakang (kepada kekafiran), lalu jadilah kamu orang-orang yang rugi.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 150, "text": "بَلِ ٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ خَیۡرُ ٱلنَّـٰصِرِینَ ۝١٥٠", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "إنهم لن ينصروكم، بل الله ناصركم، وهو خير ناصر، فلا يحتاج معه إلى نصرة أحد.", "isBasmala": false, "translation_en": "God is your Master, and He is the Best of Helpers.", "translation_id": "Tetapi (ikutilah Allah), Allahlah Pelindungmu, dan Dialah sebaik-baik Penolong.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 151, "text": "سَنُلۡقِی فِی قُلُوبِ ٱلَّذِینَ كَفَرُوا۟ ٱلرُّعۡبَ بِمَاۤ أَشۡرَكُوا۟ بِٱللَّهِ مَا لَمۡ یُنَزِّلۡ بِهِۦ سُلۡطَـٰنࣰاۖ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَبِئۡسَ مَثۡوَى ٱلظَّـٰلِمِینَ ۝١٥١", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "سنقذف في قلوب الذين كفروا أشدَّ الفزع والخوف بسبب إشراكهم بالله آلهة مزعومة، ليس لهم دليل أو برهان على استحقاقها للعبادة مع الله، فحالتهم في الدنيا: رعب وهلع من المؤمنين، أما مكانهم في الآخرة الذي يأوون إليه فهو النار؛ وذلك بسبب ظلمهم وعدوانهم، وساء هذا المقام مقامًا لهم.", "isBasmala": false, "translation_en": "We will throw terror into the hearts of those who disbelieve, because they attribute to God partners for which He revealed no sanction. Their lodging is the Fire. Miserable is the lodging of the evildoers.", "translation_id": "Akan Kami masukkan ke dalam hati orang-orang kafir rasa takut, disebabkan mereka mempersekutukan Allah dengan sesuatu yang Allah sendiri tidak menurunkan keterangan tentang itu. Tempat kembali mereka ialah neraka; dan itulah seburuk-buruk tempat tinggal orang-orang yang zalim.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 152, "text": "وَلَقَدۡ صَدَقَكُمُ ٱللَّهُ وَعۡدَهُۥۤ إِذۡ تَحُسُّونَهُم بِإِذۡنِهِۦۖ حَتَّىٰۤ إِذَا فَشِلۡتُمۡ وَتَنَـٰزَعۡتُمۡ فِی ٱلۡأَمۡرِ وَعَصَیۡتُم مِّنۢ بَعۡدِ مَاۤ أَرَىٰكُم مَّا تُحِبُّونَۚ مِنكُم مَّن یُرِیدُ ٱلدُّنۡیَا وَمِنكُم مَّن یُرِیدُ ٱلۡـَٔاخِرَةَۚ ثُمَّ صَرَفَكُمۡ عَنۡهُمۡ لِیَبۡتَلِیَكُمۡۖ وَلَقَدۡ عَفَا عَنكُمۡۗ وَٱللَّهُ ذُو فَضۡلٍ عَلَى ٱلۡمُؤۡمِنِینَ ۝١٥٢", "juz": 4, "hizb": "(*½ ح 7*)", "tafsir": "ولقد حقق الله لكم ما وعدكم به من نصر، حين كنتم تقتلون الكفار في غزوة \"أُحد\" بإذنه تعالى، حتى إذا جَبُنتم وضعفتم عن القتال واختلفتم: هل تبقون في مواقعكم أو تتركونها لجمع الغنانم مع مَن يجمعها؟ وعصيتم أمر رسولكم حين أمركم ألا تفارفوا أماكنكم بأي حال، حلَّت بكم الهزيمة من بعد ما أراكم ما تحبون من النصر، وتبيَّن أن منكم مَن يريد الغنائم، وأن منكم مَن يطلب الآخرة وثوابها، ثم صرف الله وجوهكم عن عدوكم؛ ليختبركم، وقد علم الله ندمكم وتوبتكم فعفا عنكم، والله ذو فضل عظيم على المؤمنين.", "isBasmala": false, "translation_en": "God has fulfilled His promise to you, and you defeated them by His leave; until when you faltered, and disputed the command, and disobeyed after He had shown you what you like. Some of you want this world, and some of you want the next. Then He turned you away from them, to test you; but He pardoned you. God is Gracious towards the believers.", "translation_id": "Dan sesungguhnya Allah telah memenuhi janji-Nya kepada kamu, ketika kamu membunuh mereka dengan izin-Nya sampai pada saat kamu lemah dan berselisih dalam urusan itu dan mendurhakai perintah (Rasul) sesudah Allah memperlihatkan kepadamu apa yang kamu sukai. Di antaramu ada orang yang menghendaki dunia dan diantara kamu ada orang yang menghendaki akhirat. Kemudian Allah memalingkan kamu dari mereka untuk menguji kamu, dan sesunguhnya Allah telah memaafkan kamu. Dan Allah mempunyai karunia (yang dilimpahkan) atas orang orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 153, "text": "۞ إِذۡ تُصۡعِدُونَ وَلَا تَلۡوُۥنَ عَلَىٰۤ أَحَدࣲ وَٱلرَّسُولُ یَدۡعُوكُمۡ فِیۤ أُخۡرَىٰكُمۡ فَأَثَـٰبَكُمۡ غَمَّۢا بِغَمࣲّ لِّكَیۡلَا تَحۡزَنُوا۟ عَلَىٰ مَا فَاتَكُمۡ وَلَا مَاۤ أَصَـٰبَكُمۡۗ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ ۝١٥٣", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "اذكروا -يا أصحاب محمد- ما كان مِن أمركم حين أخذتم تصعدون الجبل هاربين من أعدائكم، ولا تلتفتون إلى أحد لِمَا اعتراكم من الدهشة والخوف والرعب، ورسول الله صلى الله عليه وسلم ثابت في الميدان يناديكم من خلفكم قائلا إليَّ عبادَ الله، وأنتم لا تسمعون ولا تنظرون، فكان جزاؤكم أن أنزل الله بكم ألمًا وضيقًا وغمًّا؛ لكي لا تحزنوا على ما فاتكم من نصر وغنيمة، ولا ما حلَّ بكم من خوف وهزيمة. والله خبير بجميع أعمالكم، لا يخفى عليه منها شيء.", "isBasmala": false, "translation_en": "Remember when you fled, not caring for anyone, even though the Messenger was calling you from your rear. Then He repaid you with sorrow upon sorrow, so that you would not grieve over what you missed, or for what afflicted you. God is Informed of what you do.", "translation_id": "(Ingatlah) ketika kamu lari dan tidak menoleh kepada seseorangpun, sedang Rasul yang berada di antara kawan-kawanmu yang lain memanggil kamu, karena itu Allah menimpakan atas kamu kesedihan atas kesedihan, supaya kamu jangan bersedih hati terhadap apa yang luput dari pada kamu dan terhadap apa yang menimpa kamu. Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}], "70": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 154, "text": "ثُمَّ أَنزَلَ عَلَیۡكُم مِّنۢ بَعۡدِ ٱلۡغَمِّ أَمَنَةࣰ نُّعَاسࣰا یَغۡشَىٰ طَاۤىِٕفَةࣰ مِّنكُمۡۖ وَطَاۤىِٕفَةࣱ قَدۡ أَهَمَّتۡهُمۡ أَنفُسُهُمۡ یَظُنُّونَ بِٱللَّهِ غَیۡرَ ٱلۡحَقِّ ظَنَّ ٱلۡجَـٰهِلِیَّةِۖ یَقُولُونَ هَل لَّنَا مِنَ ٱلۡأَمۡرِ مِن شَیۡءࣲۗ قُلۡ إِنَّ ٱلۡأَمۡرَ كُلَّهُۥ لِلَّهِۗ یُخۡفُونَ فِیۤ أَنفُسِهِم مَّا لَا یُبۡدُونَ لَكَۖ یَقُولُونَ لَوۡ كَانَ لَنَا مِنَ ٱلۡأَمۡرِ شَیۡءࣱ مَّا قُتِلۡنَا هَـٰهُنَاۗ قُل لَّوۡ كُنتُمۡ فِی بُیُوتِكُمۡ لَبَرَزَ ٱلَّذِینَ كُتِبَ عَلَیۡهِمُ ٱلۡقَتۡلُ إِلَىٰ مَضَاجِعِهِمۡۖ وَلِیَبۡتَلِیَ ٱللَّهُ مَا فِی صُدُورِكُمۡ وَلِیُمَحِّصَ مَا فِی قُلُوبِكُمۡۚ وَٱللَّهُ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝١٥٤", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "ثم كان من رحمة الله بالمؤمنين المخلصين أن ألقى في قلوبهم من بعد ما نزل بها من همٍّ وغمٍّ اطمئنانًا وثقة في وعد الله، وكان من أثره نعاس غَشِي طائفة منهم، وهم أهل الإخلاص واليقين، وطائفة أُخرى أهمَّهم خلاص أنفسهم خاصة، وضَعُفَتْ عزيمتهم وشُغِلوا بأنفسهم، وأساؤوا الظن بربهم وبدينه وبنبيه، وظنوا أن الله لا يُتِمُّ أمر رسوله، وأن الإسلام لن تقوم له قائمة، ولذلك تراهم نادمين على خروجهم، يقول بعضهم لبعض: هل كان لنا من اختيار في الخروج للقتال؟ قل لهم -أيها الرسول-: إن الأمر كلَّه لله، فهو الذي قدَّر خروجكم وما حدث لكم، وهم يُخْفون في أنفسهم ما لا يظهرونه لك من الحسرة على خروجهم للقتال، يقولون: لو كان لنا أدنى اختيار ما قُتِلنا هاهنا. قل لهم: إن الآجال بيد الله، ولو كنتم في بيوتكم، وقدَّر الله أنكم تموتون، لخرج الذين كتب الله عليهم الموت إلى حيث يُقْتلون، وما جعل الله ذلك إلا ليختبر ما في صدوركم من الشك والنفاق، وليميز الخبيث من الطيب، ويظهر أمر المؤمن من المنافق للناس في الأقوال والأفعال. والله عليم بما في صدور خلقه، لا يخفى عليه شيء من أمورهم.", "isBasmala": false, "translation_en": "Then after the setback, He sent down security upon you. Slumber overcame some of you, while others cared only for themselves, thinking of God thoughts that were untrue-thoughts of ignorance-saying, \"Is anything up to us?\" Say, \"Everything is up to God.\" They conceal within themselves what they do not reveal to you. And they say, \"If it was up to us, none of us would have been killed here.\" Say, \"Even if you Had stayed in your homes, those destined to be killed would have marched into their death beds.\" God thus tests what is in your minds, and purifies what is in your hearts. God knows what the hearts contain.", "translation_id": "Kemudian setelah kamu berdukacita, Allah menurunkan kepada kamu keamanan (berupa) kantuk yang meliputi segolongan dari pada kamu, sedang segolongan lagi telah dicemaskan oleh diri mereka sendiri, mereka menyangka yang tidak benar terhadap Allah seperti sangkaan jahiliyah. Mereka berkata: \"Apakah ada bagi kita barang sesuatu (hak campur tangan) dalam urusan ini?\". Katakanlah: \"Sesungguhnya urusan itu seluruhnya di tangan Allah\". Mereka menyembunyikan dalam hati mereka apa yang tidak mereka terangkan kepadamu; mereka berkata: \"Sekiranya ada bagi kita barang sesuatu (hak campur tangan) dalam urusan ini, niscaya kita tidak akan dibunuh (dikalahkan) di sini\". Katakanlah: \"Sekiranya kamu berada di rumahmu, niscaya orang-orang yang telah ditakdirkan akan mati terbunuh itu keluar (juga) ke tempat mereka terbunuh\". Dan Allah (berbuat demikian) untuk menguji apa yang ada dalam dadamu dan untuk membersihkan apa yang ada dalam hatimu. Allah Maha Mengetahui isi hati.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 155, "text": "إِنَّ ٱلَّذِینَ تَوَلَّوۡا۟ مِنكُمۡ یَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّیۡطَـٰنُ بِبَعۡضِ مَا كَسَبُوا۟ۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ إِنَّ ٱللَّهَ غَفُورٌ حَلِیمࣱ ۝١٥٥", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "إن الذين فرُّوا منكم -يا أصحاب- محمد عن القتال يوم التقى المؤمنون والمشركون في غزوة \"أُحد\"، إنما أوقعهم الشيطان في هذا الذنب ببعض ما عملوا من الذنوب، ولقد تجاوز الله عنهم فلم يعاقبهم. إن الله غفور للمذنبين التائبين، حليم لا يعاجل من عصاه بالعقوبة.", "isBasmala": false, "translation_en": "Those of you who turned back on the day when the two armies clashed-it was Satan who caused them to backslide, on account of some of what they have earned. But God has forgiven them. God is Forgiving and Prudent.", "translation_id": "Sesungguhnya orang-orang yang berpaling di antaramu pada hari bertemu dua pasukan itu, hanya saja mereka digelincirkan oleh syaitan, disebabkan sebagian kesalahan yang telah mereka perbuat (di masa lampau) dan sesungguhnya Allah telah memberi maaf kepada mereka. Sesungguhnya Allah Maha Pengampun lagi Maha Penyantun.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 156, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِینَ كَفَرُوا۟ وَقَالُوا۟ لِإِخۡوَ ٰنِهِمۡ إِذَا ضَرَبُوا۟ فِی ٱلۡأَرۡضِ أَوۡ كَانُوا۟ غُزࣰّى لَّوۡ كَانُوا۟ عِندَنَا مَا مَاتُوا۟ وَمَا قُتِلُوا۟ لِیَجۡعَلَ ٱللَّهُ ذَ ٰلِكَ حَسۡرَةࣰ فِی قُلُوبِهِمۡۗ وَٱللَّهُ یُحۡیِۦ وَیُمِیتُۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ ۝١٥٦", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تُشابهوا الكافرين الذين لا يؤمنون بربهم، فهم يقولون لإخوانهم من أهل الكفر إذا خرجوا يبحثون في أرض الله عن معاشهم أو كانوا مع الغزاة المقاتلين فماتوا أو قُتِلوا: لو لم يخرج هؤلاء ولم يقاتلوا وأقاموا معنا ما ماتوا وما قُتلوا. وهذا القول يزيدهم ألمًا وحزنًا وحسرة تستقر في قلوبهم، أما المؤمنون فإنهم يعلمون أن ذلك بقدر الله فيهدي الله قلوبهم، ويخفف عنهم المصيبة، والله يحيي مَن قدَّر له الحياة -وإن كان مسافرًا أو غازيًا- ويميت مَنِ انتهى أجله -وإن كان مقيمًا- والله بكل ما تعملونه بصير، فيجازيكم به.", "isBasmala": false, "translation_en": "O you who believe! Do not be like those who disbelieved, and said of their brethren who marched in the land, or went on the offensive, \"Had they stayed with us, they would not have died or been killed.\" So that God may make it a cause of regret in their hearts. God gives life and causes death. God is Seeing of what you do.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu seperti orang-orang kafir (orang-orang munafik) itu, yang mengatakan kepada saudara-saudara mereka apabila mereka mengadakan perjalanan di muka bumi atau mereka berperang: \"Kalau mereka tetap bersama-sama kita tentulah mereka tidak mati dan tidak dibunuh\". Akibat (dari perkataan dan keyakinan mereka) yang demikian itu, Allah menimbulkan rasa penyesalan yang sangat di dalam hati mereka. Allah menghidupkan dan mematikan. Dan Allah melihat apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 157, "text": "وَلَىِٕن قُتِلۡتُمۡ فِی سَبِیلِ ٱللَّهِ أَوۡ مُتُّمۡ لَمَغۡفِرَةࣱ مِّنَ ٱللَّهِ وَرَحۡمَةٌ خَیۡرࣱ مِّمَّا یَجۡمَعُونَ ۝١٥٧", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "ولئن قُتِلتم -أيها المؤمنون- وأنتم تجاهدون في سبيل الله أو متم في أثناء القتال، ليغفرن الله لكم ذنوبكم، وليرحمنكم رحمة من عنده، فتفوزون بجنات النعيم، وذلك خير من الدنيا وما يجمعه أهلها.", "isBasmala": false, "translation_en": "If you are killed in the cause of God, or die-forgiveness and mercy from God are better than what they hoard.", "translation_id": "Dan sungguh kalau kamu gugur di jalan Allah atau meninggal, tentulah ampunan Allah dan rahmat-Nya lebih baik (bagimu) dari harta rampasan yang mereka kumpulkan.", "manzil": 1, "manzil_display": ""}], "71": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 158, "text": "وَلَىِٕن مُّتُّمۡ أَوۡ قُتِلۡتُمۡ لَإِلَى ٱللَّهِ تُحۡشَرُونَ ۝١٥٨", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "ولئن انقضت آجالكم في هذه الحياة الدنيا، فمتم على فُرُشكم، أو قتلتم في ساحة القتال، لإلى الله وحده تُحشرون، فيجازيكم بأعمالكم.", "isBasmala": false, "translation_en": "If you die, or are killed-to God you will be gathered up.", "translation_id": "Dan sungguh jika kamu meninggal atau gugur, tentulah kepada Allah saja kamu dikumpulkan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 159, "text": "فَبِمَا رَحۡمَةࣲ مِّنَ ٱللَّهِ لِنتَ لَهُمۡۖ وَلَوۡ كُنتَ فَظًّا غَلِیظَ ٱلۡقَلۡبِ لَٱنفَضُّوا۟ مِنۡ حَوۡلِكَۖ فَٱعۡفُ عَنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمۡ وَشَاوِرۡهُمۡ فِی ٱلۡأَمۡرِۖ فَإِذَا عَزَمۡتَ فَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُتَوَكِّلِینَ ۝١٥٩", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "فبرحمة من الله لك ولأصحابك -أيها النبي- منَّ الله عليك فكنت رفيقًا بهم، ولو كنت سيِّئ الخُلق قاسي القلب، لانْصَرَفَ أصحابك من حولك، فلا تؤاخذهم بما كان منهم في غزوة \"أُحد\"، واسأل الله -أيها النبي- أن يغفر لهم، وشاورهم في الأمور التي تحتاج إلى مشورة، فإذا عزمت على أمر من الأمور -بعد الاستشارة- فأَمْضِه معتمدًا على الله وحده، إن الله يحب المتوكلين عليه.", "isBasmala": false, "translation_en": "It is by of grace from God that you were gentle with them. Had you been harsh, hardhearted, they would have dispersed from around you. So pardon them, and ask forgiveness for them, and consult them in the conduct of affairs. And when you make a decision, put your trust in God; God loves the trusting.", "translation_id": "Maka disebabkan rahmat dari Allah-lah kamu berlaku lemah lembut terhadap mereka. Sekiranya kamu bersikap keras lagi berhati kasar, tentulah mereka menjauhkan diri dari sekelilingmu. Karena itu maafkanlah mereka, mohonkanlah ampun bagi mereka, dan bermusyawaratlah dengan mereka dalam urusan itu. Kemudian apabila kamu telah membulatkan tekad, maka bertawakkallah kepada Allah. Sesungguhnya Allah menyukai orang-orang yang bertawakkal kepada-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 160, "text": "إِن یَنصُرۡكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمۡۖ وَإِن یَخۡذُلۡكُمۡ فَمَن ذَا ٱلَّذِی یَنصُرُكُم مِّنۢ بَعۡدِهِۦۗ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ۝١٦٠", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "إن يمددكم الله بنصره ومعونته فلا أحد يستطيع أن يغلبكم، وإن يخذلكم فمن هذا الذي يستطيع أن ينصركم من بعد خذلانه لكم؟ وعلى الله وحده فليتوكل المؤمنون.", "isBasmala": false, "translation_en": "If God supports you, there is none who can overcome you. But if He fails you, who is there to help you after Him? So in God let the believers put their trust.", "translation_id": "Jika Allah menolong kamu, maka tak adalah orang yang dapat mengalahkan kamu; jika Allah membiarkan kamu (tidak memberi pertolongan), maka siapakah gerangan yang dapat menolong kamu (selain) dari Allah sesudah itu? Karena itu hendaklah kepada Allah saja orang-orang mukmin bertawakkal.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 161, "text": "وَمَا كَانَ لِنَبِیٍّ أَن یَغُلَّۚ وَمَن یَغۡلُلۡ یَأۡتِ بِمَا غَلَّ یَوۡمَ ٱلۡقِیَـٰمَةِۚ ثُمَّ تُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا كَسَبَتۡ وَهُمۡ لَا یُظۡلَمُونَ ۝١٦١", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "وما كان لنبيٍّ أن يَخُونَ أصحابه بأن يأخذ شيئًا من الغنيمة غير ما اختصه الله به، ومن يفعل ذلك منكم يأت بما أخذه حاملا له يوم القيامة؛ ليُفضَح به في الموقف المشهود، ثم تُعطى كل نفس جزاءَ ما كسبت وافيًا غير منقوص دون ظلم.", "isBasmala": false, "translation_en": "It is not for a prophet to act dishonestly. Whoever acts dishonestly will bring his dishonesty on the Day of Resurrection. Then every soul will be paid in full for what it has earned, and they will not be wronged.", "translation_id": "Tidak mungkin seorang nabi berkhianat dalam urusan harta rampasan perang. Barangsiapa yang berkhianat dalam urusan rampasan perang itu, maka pada hari kiamat ia akan datang membawa apa yang dikhianatkannya itu, kemudian tiap-tiap diri akan diberi pembalasan tentang apa yang ia kerjakan dengan (pembalasan) setimpal, sedang mereka tidak dianiaya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 162, "text": "أَفَمَنِ ٱتَّبَعَ رِضۡوَ ٰنَ ٱللَّهِ كَمَنۢ بَاۤءَ بِسَخَطࣲ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ ۝١٦٢", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "لا يستوي من كان قصده رضوان الله ومن هو مُكِبٌ على المعاصي، مسخط لربه، فاستحق بذلك سكن جهنم، وبئس المصير.", "isBasmala": false, "translation_en": "Is someone who pursues God's approval the same as someone who incurs God's wrath and his refuge is Hell-the miserable destination?", "translation_id": "Apakah orang yang mengikuti keridhaan Allah sama dengan orang yang kembali membawa kemurkaan (yang besar) dari Allah dan tempatnya adalah Jahannam? Dan itulah seburuk-buruk tempat kembali.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 163, "text": "هُمۡ دَرَجَـٰتٌ عِندَ ٱللَّهِۗ وَٱللَّهُ بَصِیرُۢ بِمَا یَعۡمَلُونَ ۝١٦٣", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "أصحاب الجنة المتبعون لما يرضي الله متفاوتون في الدرجات، وأصحاب النار المتبعون لما يسخط الله متفاوتون في الدركات، لا يستوون. والله بصير بأعمالهم لا يخفى عليه منها شيء.", "isBasmala": false, "translation_en": "They have different ranks with God, and God is Seeing of what they do.", "translation_id": "(Kedudukan) mereka itu bertingkat-tingkat di sisi Allah, dan Allah Maha Melihat apa yang mereka kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 164, "text": "لَقَدۡ مَنَّ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِینَ إِذۡ بَعَثَ فِیهِمۡ رَسُولࣰا مِّنۡ أَنفُسِهِمۡ یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِهِۦ وَیُزَكِّیهِمۡ وَیُعَلِّمُهُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُوا۟ مِن قَبۡلُ لَفِی ضَلَـٰلࣲ مُّبِینٍ ۝١٦٤", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "لقد أنعم الله على المؤمنين من العرب؛ إذ بعث فيهم رسولا من أنفسهم، يتلو عليهم آيات القرآن، ويطهرهم من الشرك والأخلاق الفاسدة، ويعلمهم القرآن والسنة، وإن كانوا من قبل هذا الرسول لفي غيٍّ وجهل ظاهر.", "isBasmala": false, "translation_en": "God has blessed the believers, as He raised up among them a messenger from among themselves, who recites to them His revelations, and purifies them, and teaches them the Scripture and wisdom; although before that they were in evident error.", "translation_id": "Sungguh Allah telah memberi karunia kepada orang-orang yang beriman ketika Allah mengutus diantara mereka seorang rasul dari golongan mereka sendiri, yang membacakan kepada mereka ayat-ayat Allah, membersihkan (jiwa) mereka, dan mengajarkan kepada mereka Al Kitab dan Al Hikmah. Dan sesungguhnya sebelum (kedatangan Nabi) itu, mereka adalah benar-benar dalam kesesatan yang nyata.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 165, "text": "أَوَ لَمَّاۤ أَصَـٰبَتۡكُم مُّصِیبَةࣱ قَدۡ أَصَبۡتُم مِّثۡلَیۡهَا قُلۡتُمۡ أَنَّىٰ هَـٰذَاۖ قُلۡ هُوَ مِنۡ عِندِ أَنفُسِكُمۡۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝١٦٥", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "أولما أصابتكم -أيها المؤمنون- مصيبة، وهي ما أُصيب منكم يوم \"أُحد\" قد أصبتم مثليها من المشركين في يوم \"بدْر\"، قلتم متعجبين: كيف يكون هذا ونحن مسلمون ورسول الله صلى الله عليه وسلم فينا وهؤلاء مشركون؟ قل لهم -أيها النبي-: هذا الذي أصابكم هو من عند أنفسكم بسبب مخالفتكم أمْرَ رسولكم وإقبالكم على جمع الغنائم. إن الله يفعل ما يشاء ويحكم ما يريد، لا معقِّب ‌‌‌‌لحكمه.", "isBasmala": false, "translation_en": "And when a calamity befell you, even after you had inflicted twice as much, you said, \"How is this?\" Say, \"It is from your own selves.\" God is Able to do all things.", "translation_id": "Dan mengapa ketika kamu ditimpa musibah (pada peperangan Uhud), padahal kamu telah menimpakan kekalahan dua kali lipat kepada musuh-musuhmu (pada peperangan Badar), kamu berkata: \"Darimana datangnya (kekalahan) ini?\" Katakanlah: \"Itu dari (kesalahan) dirimu sendiri\". Sesungguhnya Allah Maha Kuasa atas segala sesuatu.", "manzil": 1, "manzil_display": ""}], "72": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 166, "text": "وَمَاۤ أَصَـٰبَكُمۡ یَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ فَبِإِذۡنِ ٱللَّهِ وَلِیَعۡلَمَ ٱلۡمُؤۡمِنِینَ ۝١٦٦", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "وما وقع بكم مِن جراح أو قتل في غزوة \"أُحد\" يوم التقى جَمْعُ المؤمنين وجمع المشركين فكان النصر للمؤمنين أولا ثم للمشركين ثانيًا، فذلك كله بقضاء الله وقدره، وليظهر ما علمه الله في الأزل؛ ليميز المؤمنين الصادقين منكم.", "isBasmala": false, "translation_en": "What befell you on the day the two armies clashed was with God's permission; that He may know the believers.", "translation_id": "Dan apa yang menimpa kamu pada hari bertemunya dua pasukan, maka (kekalahan) itu adalah dengan izin (takdir) Allah, dan agar Allah mengetahui siapa orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 167, "text": "وَلِیَعۡلَمَ ٱلَّذِینَ نَافَقُوا۟ۚ وَقِیلَ لَهُمۡ تَعَالَوۡا۟ قَـٰتِلُوا۟ فِی سَبِیلِ ٱللَّهِ أَوِ ٱدۡفَعُوا۟ۖ قَالُوا۟ لَوۡ نَعۡلَمُ قِتَالࣰا لَّٱتَّبَعۡنَـٰكُمۡۗ هُمۡ لِلۡكُفۡرِ یَوۡمَىِٕذٍ أَقۡرَبُ مِنۡهُمۡ لِلۡإِیمَـٰنِۚ یَقُولُونَ بِأَفۡوَ ٰهِهِم مَّا لَیۡسَ فِی قُلُوبِهِمۡۚ وَٱللَّهُ أَعۡلَمُ بِمَا یَكۡتُمُونَ ۝١٦٧", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "وليعلم المنافقين الذين كشف الله ما في قلوبهم حين قال المؤمنون لهم: تعالوا قاتلوا معنا في سبيل الله، أو كونوا عونًا لنا بتكثيركم سوادنا، فقالوا: لو نعلم أنكم تقاتلون أحدًا لكنا معكم عليهم، هم للكفر في هذا اليوم أقرب منهم للإيمان؛ لأنهم يقولون بأفواههم ما ليس في قلوبهم. والله أعلم بما يُخفون في صدورهم.", "isBasmala": false, "translation_en": "And that He may know the hypocrites. And it was said to them, \"Come, fight in the cause of God, or contribute.\" They said, \"If we knew how to fight, we would have followed you.\" On that day they were closer to infidelity than they were to faith. They say with their mouths what is not in their hearts; but God knows what they hide.", "translation_id": "Dan supaya Allah mengetahui siapa orang-orang yang munafik. Kepada mereka dikatakan: \"Marilah berperang di jalan Allah atau pertahankanlah (dirimu)\". Mereka berkata: \"Sekiranya kami mengetahui akan terjadi peperangan, tentulah kami mengikuti kamu\". Mereka pada hari itu lebih dekat kepada kekafiran dari pada keimanan. Mereka mengatakan dengan mulutnya apa yang tidak terkandung dalam hatinya. Dan Allah lebih mengetahui dalam hatinya. Dan Allah lebih mengetahui apa yang mereka sembunyikan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 168, "text": "ٱلَّذِینَ قَالُوا۟ لِإِخۡوَ ٰنِهِمۡ وَقَعَدُوا۟ لَوۡ أَطَاعُونَا مَا قُتِلُوا۟ۗ قُلۡ فَٱدۡرَءُوا۟ عَنۡ أَنفُسِكُمُ ٱلۡمَوۡتَ إِن كُنتُمۡ صَـٰدِقِینَ ۝١٦٨", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "هؤلاء المنافقون هم الذين قعدوا وقالوا لإخوانهم الذين أصيبوا مع المسلمين في حربهم المشركين يوم \"أُحد\": لو أطاعَنا هؤلاء ما قتلوا. قل لهم -أيها الرسول-: فادفعوا عن أنفسكم الموت إن كنتم صادقين في دعواكم أنهم لو أطاعوكم ما قتلوا، وأنكم قد نجوتم منه بقعودكم عن القتال.", "isBasmala": false, "translation_en": "Those who said of their brethren, as they stayed behind, \"Had they obeyed us, they would not have been killed.\" Say, \"Then avert death from yourselves, if you are truthful.\"", "translation_id": "Orang-orang yang mengatakan kepada saudara-saudaranya dan mereka tidak turut pergi berperang: \"Sekiranya mereka mengikuti kita, tentulah mereka tidak terbunuh\". Katakanlah: \"Tolaklah kematian itu dari dirimu, jika kamu orang-orang yang benar\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 169, "text": "وَلَا تَحۡسَبَنَّ ٱلَّذِینَ قُتِلُوا۟ فِی سَبِیلِ ٱللَّهِ أَمۡوَ ٰتَۢاۚ بَلۡ أَحۡیَاۤءٌ عِندَ رَبِّهِمۡ یُرۡزَقُونَ ۝١٦٩", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "ولا تظنَّنَّ -أيها النبي- أن الذين قتلوا في سبيل الله أموات لا يُحِسُّون شيئًا، بل هم أحياء حياة برزخية في جوار ربهم الذي جاهدوا من أجله، وماتوا في سبيله، يجري عليهم رزقهم في الجنة، ويُنعَّمون.", "isBasmala": false, "translation_en": "Do not consider those killed in the cause of God as dead. In fact, they are alive, at their Lord, well provided for.", "translation_id": "Janganlah kamu mengira bahwa orang-orang yang gugur di jalan Allah itu mati; bahkan mereka itu hidup disisi Tuhannya dengan mendapat rezeki.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 170, "text": "فَرِحِینَ بِمَاۤ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ وَیَسۡتَبۡشِرُونَ بِٱلَّذِینَ لَمۡ یَلۡحَقُوا۟ بِهِم مِّنۡ خَلۡفِهِمۡ أَلَّا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝١٧٠", "juz": 4, "hizb": "(*¾ ح 7*)", "tafsir": "لقد عَمَّتهم السعادة حين مَنَّ الله عليهم، فأعطاهم مِن عظيم جوده وواسع كرمه من النعيم والرضا ما تَقَرُّ به أعينهم، وهم يفرحون بإخوانهم المجاهدين الذين فارقوهم وهم أحياء؛ ليفوزوا كما فازوا، لِعِلْمِهم أنهم سينالون من الخير الذي نالوه، إذا استشهدوا في سبيل الله مخلصين له، وأن لا خوف عليهم فيما يستقبلون من أمور الآخرة، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا.", "isBasmala": false, "translation_en": "Delighting in what God has given them out of His grace, and happy for those who have not yet joined them; that they have nothing to fear, nor will they grieve.", "translation_id": "Mereka dalam keadaan gembira disebabkan karunia Allah yang diberikan-Nya kepada mereka, dan mereka bergirang hati terhadap orang-orang yang masih tinggal di belakang yang belum menyusul mereka, bahwa tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 171, "text": "۞ یَسۡتَبۡشِرُونَ بِنِعۡمَةࣲ مِّنَ ٱللَّهِ وَفَضۡلࣲ وَأَنَّ ٱللَّهَ لَا یُضِیعُ أَجۡرَ ٱلۡمُؤۡمِنِینَ ۝١٧١", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "وإنهم في فرحة غامرة بما أُعطوا من نعم الله وجزيل عطائه، وأن الله لا يضيع أجر المؤمنين به، بل ينمِّيه ويزيده من فضله.", "isBasmala": false, "translation_en": "They rejoice in grace from God, and bounty, and that God will not waste the reward of the faithful.", "translation_id": "Mereka bergirang hati dengan nikmat dan karunia yang yang besar dari Allah, dan bahwa Allah tidak menyia-nyiakan pahala orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 172, "text": "ٱلَّذِینَ ٱسۡتَجَابُوا۟ لِلَّهِ وَٱلرَّسُولِ مِنۢ بَعۡدِ مَاۤ أَصَابَهُمُ ٱلۡقَرۡحُۚ لِلَّذِینَ أَحۡسَنُوا۟ مِنۡهُمۡ وَٱتَّقَوۡا۟ أَجۡرٌ عَظِیمٌ ۝١٧٢", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "الذين لبُّوا نداء الله ورسوله وخرجوا في أعقاب المشركين إلى \"حمراء الأسد\" بعد هزيمتهم في غزوة \"أُحد\" مع ما كان بهم من آلام وجراح، وبذلوا غاية جهدهم، والتزموا بهدي نبيهم، للمحسنين منهم والمتقين ثواب عظيم.", "isBasmala": false, "translation_en": "Those who responded to God and the Messenger, despite the persecution they had suffered. For the virtuous and the pious among them is a great reward.", "translation_id": "(Yaitu) orang-orang yang mentaati perintah Allah dan Rasul-Nya sesudah mereka mendapat luka (dalam peperangan Uhud). Bagi orang-orang yang berbuat kebaikan diantara mereka dan yang bertakwa ada pahala yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 173, "text": "ٱلَّذِینَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُوا۟ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِیمَـٰنࣰا وَقَالُوا۟ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِیلُ ۝١٧٣", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "وهم الذين قال لهم بعض المشركين: إن أبا سفيان ومن معه قد أجمعوا أمرهم على الرجوع إليكم لاستئصالكم، فاحذروهم واتقوا لقاءهم، فإنه لا طاقة لكم بهم، فزادهم ذلك التخويف يقينًا وتصديقًا بوعد الله لهم، ولم يَثْنِهم ذلك عن عزمهم، فساروا إلى حيث شاء الله، وقالوا: حسبنا الله أي: كافينا، ونِعْم الوكيل المفوَّض إليه تدبير عباده.", "isBasmala": false, "translation_en": "Those to whom the people have said, \"The people have mobilized against you, so fear them.\" But this only increased them in faith, and they said, \"God is enough for us; He is the Excellent Protector.\"", "translation_id": "(Yaitu) orang-orang (yang mentaati Allah dan Rasul) yang kepada mereka ada orang-orang yang mengatakan: \"Sesungguhnya manusia telah mengumpulkan pasukan untuk menyerang kamu, karena itu takutlah kepada mereka\", maka perkataan itu menambah keimanan mereka dan mereka menjawab: \"Cukuplah Allah menjadi Penolong kami dan Allah adalah sebaik-baik Pelindung\".", "manzil": 1, "manzil_display": ""}], "73": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 174, "text": "فَٱنقَلَبُوا۟ بِنِعۡمَةࣲ مِّنَ ٱللَّهِ وَفَضۡلࣲ لَّمۡ یَمۡسَسۡهُمۡ سُوۤءࣱ وَٱتَّبَعُوا۟ رِضۡوَ ٰنَ ٱللَّهِۗ وَٱللَّهُ ذُو فَضۡلٍ عَظِیمٍ ۝١٧٤", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "فرجعوا من \"حمراء الأسد\" إلى \"المدينة\" بنعمة من الله بالثواب الجزيل وبفضل منه بالمنزلة العالية، وقد ازدادوا إيمانًا ويقينًا، وأذلوا أعداء الله، وفازوا بالسلامة من القتل والقتال، واتبعوا رضوان الله بطاعتهم له ولرسوله. والله ذو فضل عظيم عليهم وعلى غيرهم.", "isBasmala": false, "translation_en": "So they came back with grace from God, and bounty, and no harm having touched them. They pursued what pleases God. God possesses immense grace.", "translation_id": "Maka mereka kembali dengan nikmat dan karunia (yang besar) dari Allah, mereka tidak mendapat bencana apa-apa, mereka mengikuti keridhaan Allah. Dan Allah mempunyai karunia yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 175, "text": "إِنَّمَا ذَ ٰلِكُمُ ٱلشَّیۡطَـٰنُ یُخَوِّفُ أَوۡلِیَاۤءَهُۥ فَلَا تَخَافُوهُمۡ وَخَافُونِ إِن كُنتُم مُّؤۡمِنِینَ ۝١٧٥", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "إنَّما المثبِّط لكم في ذلك هو الشيطان جاءكم يخوِّفكم أنصاره، فلا تخافوا المشركين؛ لأنّهم ضعاف لا ناصر لهم، وخافوني بالإقبال على طاعتي إن كنتم مصدِّقين بي، ومتبعين رسولي.", "isBasmala": false, "translation_en": "That is only Satan frightening his partisans; so do not fear them, but fear Me, if you are believers.", "translation_id": "Sesungguhnya mereka itu tidak lain hanyalah syaitan yang menakut-nakuti (kamu) dengan kawan-kawannya (orang-orang musyrik Quraisy), karena itu janganlah kamu takut kepada mereka, tetapi takutlah kepada-Ku, jika kamu benar-benar orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 176, "text": "وَلَا یَحۡزُنكَ ٱلَّذِینَ یُسَـٰرِعُونَ فِی ٱلۡكُفۡرِۚ إِنَّهُمۡ لَن یَضُرُّوا۟ ٱللَّهَ شَیۡـࣰٔاۗ یُرِیدُ ٱللَّهُ أَلَّا یَجۡعَلَ لَهُمۡ حَظࣰّا فِی ٱلۡـَٔاخِرَةِۖ وَلَهُمۡ عَذَابٌ عَظِیمٌ ۝١٧٦", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "لا يُدْخِل الحزنَ إلى قلبك -أيها الرسول- هؤلاء الكفارُ بمسارعتهم في الجحود والضلال، إنهم بذلك لن يضروا الله، إنما يضرون أنفسهم بحرمانها حلاوة الإيمان وعظيم الثواب، يريد الله ألا يجعل لهم ثوابًا في الآخرة؛ لأنهم انصرفوا عن دعوة الحق، ولهم عذاب شديد.", "isBasmala": false, "translation_en": "And do not be saddened by those who rush into disbelief. They will not harm God in the least. God desires to give them no share in the Hereafter. A terrible torment awaits them.", "translation_id": "Janganlah kamu disedihkan oleh orang-orang yang segera menjadi kafir; sesungguhnya mereka tidak sekali-kali dapat memberi mudharat kepada Allah sedikitpun. Allah berkehendak tidak akan memberi sesuatu bahagian (dari pahala) kepada mereka di hari akhirat, dan bagi mereka azab yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 177, "text": "إِنَّ ٱلَّذِینَ ٱشۡتَرَوُا۟ ٱلۡكُفۡرَ بِٱلۡإِیمَـٰنِ لَن یَضُرُّوا۟ ٱللَّهَ شَیۡـࣰٔاۖ وَلَهُمۡ عَذَابٌ أَلِیمࣱ ۝١٧٧", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "إن الذين استبدلوا الكفر بالإيمان لن يضروا الله شيئًا، بل ضرر فِعْلِهم يعود على أنفسهم، ولهم في الآخرة عذاب موجع.", "isBasmala": false, "translation_en": "Those who exchange blasphemy for faith will not harm God in the least. A painful torment awaits them.", "translation_id": "Sesungguhnya orang-orang yang menukar iman dengan kekafiran, sekali-kali mereka tidak dapat memberi mudharat kepada Allah sedikitpun; dan bagi mereka azab yang pedih.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 178, "text": "وَلَا یَحۡسَبَنَّ ٱلَّذِینَ كَفَرُوۤا۟ أَنَّمَا نُمۡلِی لَهُمۡ خَیۡرࣱ لِّأَنفُسِهِمۡۚ إِنَّمَا نُمۡلِی لَهُمۡ لِیَزۡدَادُوۤا۟ إِثۡمࣰاۖ وَلَهُمۡ عَذَابࣱ مُّهِینࣱ ۝١٧٨", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "ولا يظننَّ الجاحدون أننا إذا أَطَلْنا أعمارهم، ومتعناهم بمُتع الدنيا، ولم تؤاخذهم بكفرهم وذنوبهم، أنهم قد نالوا بذلك خيرًا لأنفسهم، إنما نؤخر عذابهم وآجالهم؛ ليزدادوا ظلمًا وطغيانًا، ولهم عذاب يهينهم ويذلُّهم.", "isBasmala": false, "translation_en": "Those who disbelieve should not assume that We respite them for their own good. In fact, We only respite them so that they may increase in sinfulness. A humiliating torment awaits them.", "translation_id": "Dan janganlah sekali-kali orang-orang kafir menyangka, bahwa pemberian tangguh Kami kepada mereka adalah lebih baik bagi mereka. Sesungguhnya Kami memberi tangguh kepada mereka hanyalah supaya bertambah-tambah dosa mereka; dan bagi mereka azab yang menghinakan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 179, "text": "مَّا كَانَ ٱللَّهُ لِیَذَرَ ٱلۡمُؤۡمِنِینَ عَلَىٰ مَاۤ أَنتُمۡ عَلَیۡهِ حَتَّىٰ یَمِیزَ ٱلۡخَبِیثَ مِنَ ٱلطَّیِّبِۗ وَمَا كَانَ ٱللَّهُ لِیُطۡلِعَكُمۡ عَلَى ٱلۡغَیۡبِ وَلَـٰكِنَّ ٱللَّهَ یَجۡتَبِی مِن رُّسُلِهِۦ مَن یَشَاۤءُۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۚ وَإِن تُؤۡمِنُوا۟ وَتَتَّقُوا۟ فَلَكُمۡ أَجۡرٌ عَظِیمࣱ ۝١٧٩", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "ما كان الله ليَدَعَكم أيها المصدقون بالله ورسوله العاملون بشرعه على ما أنتم عليه من التباس المؤمن منكم بالمنافق حتى يَمِيزَ الخبيث من الطيب، فيُعرف المنافق من المؤمن الصادق. وما كان مِن حكمة الله أن يطلعكم -أيها المؤمنون- على الغيب الذي يعلمه من عباده، فتعرفوا المؤمن منهم من المنافق، ولكنه يميزهم بالمحن والابتلاء، غير أن الله تعالى يصطفي من رسله مَن يشاء؛ ليطلعه على بعض علم الغيب بوحي منه، فآمنوا بالله ورسوله، وإن تؤمنوا إيمانًا صادقًا وتتقوا ربكم بطاعته، فلكم أجر عظيم عند الله.", "isBasmala": false, "translation_en": "God will not leave the believers as you are, without distinguishing the wicked from the sincere. Nor will God inform you of the future, but God elects from among His messengers whom He wills. So believe in God and His messengers. If you believe and practice piety, you will have a splendid reward.", "translation_id": "Allah sekali-kali tidak akan membiarkan orang-orang yang beriman dalam keadaan kamu sekarang ini, sehingga Dia menyisihkan yang buruk (munafik) dari yang baik (mukmin). Dan Allah sekali-kali tidak akan memperlihatkan kepada kamu hal-hal yang ghaib, akan tetapi Allah memilih siapa yang dikehendaki-Nya di antara rasul-rasul-Nya. Karena itu berimanlah kepada Allah dan rasul-rasul-Nya; dan jika kamu beriman dan bertakwa, maka bagimu pahala yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 180, "text": "وَلَا یَحۡسَبَنَّ ٱلَّذِینَ یَبۡخَلُونَ بِمَاۤ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦ هُوَ خَیۡرࣰا لَّهُمۖ بَلۡ هُوَ شَرࣱّ لَّهُمۡۖ سَیُطَوَّقُونَ مَا بَخِلُوا۟ بِهِۦ یَوۡمَ ٱلۡقِیَـٰمَةِۗ وَلِلَّهِ مِیرَ ٰثُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ ۝١٨٠", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "ولا يظنن الذين يبخلون بما أنعم الله به عليهم تفضلا منه أن هذا البخل خير لهم، بل هو شرٌّ لهم؛ لأن هذا المال الذي جمعوه سيكون طوقًا من نار يوضع في أعناقهم يوم القيامة. والله سبحانه وتعالى هو مالك الملك، وهو الباقي بعد فناء جميع خلقه، وهو خبير بأعمالكم جميعها، وسيجازي كلا على قدر استحقاقه.", "isBasmala": false, "translation_en": "Those who withhold what God has given them of his bounty should not assume that is good for them. In fact, it is bad for them. They will be encircled by their hoardings on the Day of Resurrection. To God belongs the inheritance of the heavens and the earth, and God is well acquainted with what you do.", "translation_id": "Sekali-kali janganlah orang-orang yang bakhil dengan harta yang Allah berikan kepada mereka dari karunia-Nya menyangka, bahwa kebakhilan itu baik bagi mereka. Sebenarnya kebakhilan itu adalah buruk bagi mereka. Harta yang mereka bakhilkan itu akan dikalungkan kelak di lehernya di hari kiamat. Dan kepunyaan Allah-lah segala warisan (yang ada) di langit dan di bumi. Dan Allah mengetahui apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}], "74": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 181, "text": "لَّقَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ فَقِیرࣱ وَنَحۡنُ أَغۡنِیَاۤءُۘ سَنَكۡتُبُ مَا قَالُوا۟ وَقَتۡلَهُمُ ٱلۡأَنۢبِیَاۤءَ بِغَیۡرِ حَقࣲّ وَنَقُولُ ذُوقُوا۟ عَذَابَ ٱلۡحَرِیقِ ۝١٨١", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "لقد سمع الله قول اليهود الذين قالوا: إن الله فقير إلينا يطلب منا أن نقرضه أموالا ونحن أغنياء. سنكتب هذا القول الذي قالوه، وسنكتب أنهم راضون بما كان مِن قَتْل آبائهم لأنبياء الله ظلمًا وعدوانًا، وسوف نؤاخذهم بذلك في الآخرة، ونقول لهم وهم في النار يعذبون: ذوقوا عذاب النار المحرقة.", "isBasmala": false, "translation_en": "God has heard the statement of those who said, \"God is poor, and we are rich.\" We will write down what they said, and their wrongful killing of the prophets; and We will say, \"Taste the torment of the burning.\"", "translation_id": "Sesungguhnya Allah telah mendengar perkatan orang-orang yang mengatakan: \"Sesunguhnya Allah miskin dan kami kaya\". Kami akan mencatat perkataan mereka itu dan perbuatan mereka membunuh nabi-nabi tanpa alasan yang benar, dan Kami akan mengatakan (kepada mereka): \"Rasakanlah olehmu azab yang mem bakar\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 182, "text": "ذَ ٰلِكَ بِمَا قَدَّمَتۡ أَیۡدِیكُمۡ وَأَنَّ ٱللَّهَ لَیۡسَ بِظَلَّامࣲ لِّلۡعَبِیدِ ۝١٨٢", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "ذلك العذاب الشديد بسبب ما قدَّمتموه في حياتكم الدنيا من المعاصي القولية والفعلية والاعتقادية، وأن الله ليس بظلام للعببد.", "isBasmala": false, "translation_en": "\"This is on account of what your hands have forwarded, and because God is not unjust towards the creatures.\"", "translation_id": "(Azab) yang demikian itu adalah disebabkan perbuatan tanganmu sendiri, dan bahwasanya Allah sekali-kali tidak menganiaya hamba-hamba-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 183, "text": "ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ عَهِدَ إِلَیۡنَاۤ أَلَّا نُؤۡمِنَ لِرَسُولٍ حَتَّىٰ یَأۡتِیَنَا بِقُرۡبَانࣲ تَأۡكُلُهُ ٱلنَّارُۗ قُلۡ قَدۡ جَاۤءَكُمۡ رُسُلࣱ مِّن قَبۡلِی بِٱلۡبَیِّنَـٰتِ وَبِٱلَّذِی قُلۡتُمۡ فَلِمَ قَتَلۡتُمُوهُمۡ إِن كُنتُمۡ صَـٰدِقِینَ ۝١٨٣", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "هؤلاء اليهود حين دُعُوا إلى الإسلام قالوا: إن الله أوصانا في التوراة ألا نصدِّق مَن جاءنا يقول: إنه رسول من الله، حتى يأتينا بصدقة يتقرب بها إلى الله، فتنزل نار من السماء فتحرقها. قل لهم -أيها الرسول-: أنتم كاذبون في قولكم؛ لأنه قد جاء آباءكم رسلٌ من قِبلي بالمعجزات والدلائل على صدقهم، وبالذي قلتم من الإتيان بالقربان الذي تأكله النار، فَلِمَ قَتَل آباؤكم هؤلاء الأنبياء إن كنتم صادقين في دعواكم؟", "isBasmala": false, "translation_en": "Those who said, \"God has made a covenant with us, that we shall not believe in any messenger unless he brings us an offering to be consumed by fire.\" Say, \"Messengers have come to you before me with proofs, and with what you asked for; so why did you assassinate them, if you are truthful?\"", "translation_id": "(Yaitu) orang-orang (Yahudi) yang mengatakan: \"Sesungguhnya Allah telah memerintahkan kepada kami, supaya kami jangan beriman kepada seseorang rasul, sebelum dia mendatangkan kepada kami korban yang dimakan api\". Katakanlah: \"Sesungguhnya telah datang kepada kamu beberapa orang rasul sebelumku membawa keterangan-keterangan yang nyata dan membawa apa yang kamu sebutkan, maka mengapa kamu membunuh mereka jika kamu adalah orang-orang yang benar\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 184, "text": "فَإِن كَذَّبُوكَ فَقَدۡ كُذِّبَ رُسُلࣱ مِّن قَبۡلِكَ جَاۤءُو بِٱلۡبَیِّنَـٰتِ وَٱلزُّبُرِ وَٱلۡكِتَـٰبِ ٱلۡمُنِیرِ ۝١٨٤", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "فإن كذَّبك -أيها الرسول- هؤلاء اليهود وغيرهم من أهل الكفر، فقد كذَّب المبطلون كثيرًا من المرسلين مِن قبلك، جاءوا أقوامهم بالمعجزات الباهرات والحجج الواضحات، والكتب السماوية التي هي نور يكشف الظلمات، والكتابِ البيِّن الواضح.", "isBasmala": false, "translation_en": "If they accuse you of lying, messengers before you were accused of lying. They came with the proofs, and the Psalms, and the Illuminating Scripture.", "translation_id": "Jika mereka mendustakan kamu, maka sesungguhnya rasul-rasul sebelum kamupun telah didustakan (pula), mereka membawa mukjizat-mukjizat yang nyata, Zabur dan kitab yang memberi penjelasan yang sempurna.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 185, "text": "كُلُّ نَفۡسࣲ ذَاۤىِٕقَةُ ٱلۡمَوۡتِۗ وَإِنَّمَا تُوَفَّوۡنَ أُجُورَكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۖ فَمَن زُحۡزِحَ عَنِ ٱلنَّارِ وَأُدۡخِلَ ٱلۡجَنَّةَ فَقَدۡ فَازَۗ وَمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا مَتَـٰعُ ٱلۡغُرُورِ ۝١٨٥", "juz": 4, "hizb": "(* ح 8*)", "tafsir": "كل نفس لا بدَّ أن تذوق الموت، وبهذا يرجع جميع الخلق إلى ربهم؛ ليحاسبهم. وإنما تُوفَّون أجوركم على أعمالكم وافية غير منقوصة يوم القيامة، فمن أكرمه ربه ونجَّاه من النار وأدخله الجنة فقد نال غاية ما يطلب. وما الحياة الدنيا إلا متعة زائلة، فلا تغترُّوا بها.", "isBasmala": false, "translation_en": "Every soul will have a taste of death, and you will receive your recompense on the Day of Resurrection. Whoever is swayed from the Fire, and admitted to Paradise, has won. The life of this world is merely enjoyment of delusion.", "translation_id": "Tiap-tiap yang berjiwa akan merasakan mati. Dan sesungguhnya pada hari kiamat sajalah disempurnakan pahalamu. Barangsiapa dijauhkan dari neraka dan dimasukkan ke dalam surga, maka sungguh ia telah beruntung. Kehidupan dunia itu tidak lain hanyalah kesenangan yang memperdayakan.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 186, "text": "۞ لَتُبۡلَوُنَّ فِیۤ أَمۡوَ ٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِینَ أَشۡرَكُوۤا۟ أَذࣰى كَثِیرࣰاۚ وَإِن تَصۡبِرُوا۟ وَتَتَّقُوا۟ فَإِنَّ ذَ ٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ ۝١٨٦", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "لَتُخْتَبَرُنَّ -أيها المؤمنون- في أموالكم بإخراج النفقات الواجبة والمستحبَّة، وبالجوائح التي تصيبها، وفي أنفسكم بما يجب عليكم من الطاعات، وما يحلُّ بكم من جراح أو قتل وفَقْد للأحباب، وذلك حتى يتميَّز المؤمن الصادق من غيره. ولتَسمعُنَّ من اليهود والنصارى والمشركين ما يؤذي أسماعكم من ألفاظ الشرك والطعن في دينكم. وإن تصبروا -أيها المؤمنون- على ذلك كله، وتتقوا الله بلزوم طاعته واجتناب معصيته، فإن ذلك من الأمور التي يُعزم عليها، وينافس فيها.", "isBasmala": false, "translation_en": "You will be tested through your possessions and your persons; and you will hear from those who received the Scripture before you, and from the idol worshipers, much abuse. But if you persevere and lead a righteous life-that indeed is a mark of great determination.", "translation_id": "Kamu sungguh-sungguh akan diuji terhadap hartamu dan dirimu. Dan (juga) kamu sungguh-sungguh akan mendengar dari orang-orang yang diberi kitab sebelum kamu dan dari orang-orang yang mempersekutukan Allah, gangguan yang banyak yang menyakitkan hati. Jika kamu bersabar dan bertakwa, maka sesungguhnya yang demikian itu termasuk urusan yang patut diutamakan.", "manzil": 1, "manzil_display": ""}], "75": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 187, "text": "وَإِذۡ أَخَذَ ٱللَّهُ مِیثَـٰقَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ لَتُبَیِّنُنَّهُۥ لِلنَّاسِ وَلَا تَكۡتُمُونَهُۥ فَنَبَذُوهُ وَرَاۤءَ ظُهُورِهِمۡ وَٱشۡتَرَوۡا۟ بِهِۦ ثَمَنࣰا قَلِیلࣰاۖ فَبِئۡسَ مَا یَشۡتَرُونَ ۝١٨٧", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "واذكر -أيها الرسول- إذ أخذ الله العهد الموثق على الذين آتاهم الله الكتاب من اليهود والنصارى، فلليهود التوراة وللنصارى الإنجيل؛ ليعملوا بهما، ويبينوا للناس ما فيهما، ولا يكتموا ذلك ولا يخفوه، فتركوا العهد ولم يلتزموا به، وأخذوا ثمنا بخسًا مقابل كتمانهم الحق وتحريفهم الكتاب، فبئس الشراء يشترون، في تضييعهم الميثاق، وتبديلهم الكتاب.", "isBasmala": false, "translation_en": "God received a pledge from those who were given the Scripture: \"You shall proclaim it to the people, and not conceal it.\" But they disregarded it behind their backs, and exchanged it for a small price. What a miserable exchange they made.", "translation_id": "Dan (ingatlah), ketika Allah mengambil janji dari orang-orang yang telah diberi kitab (yaitu): \"Hendaklah kamu menerangkan isi kitab itu kepada manusia, dan jangan kamu menyembunyikannya,\" lalu mereka melemparkan janji itu ke belakang punggung mereka dan mereka menukarnya dengan harga yang sedikit. Amatlah buruknya tukaran yang mereka terima.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 188, "text": "لَا تَحۡسَبَنَّ ٱلَّذِینَ یَفۡرَحُونَ بِمَاۤ أَتَوا۟ وَّیُحِبُّونَ أَن یُحۡمَدُوا۟ بِمَا لَمۡ یَفۡعَلُوا۟ فَلَا تَحۡسَبَنَّهُم بِمَفَازَةࣲ مِّنَ ٱلۡعَذَابِۖ وَلَهُمۡ عَذَابٌ أَلِیمࣱ ۝١٨٨", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "ولا تظنن الذين يفرحون بما أَتَوا من أفعال قبيحة كاليهود والمنافقين وغيرهم، ويحبون أن يثني عليهم الناس بما لم يفعلوا، فلا تظننهم ناجين من عذاب الله في الدنيا، ولهم في الآخرة عذاب موجع. وفي الآية وعيد شديد لكل آت لفعل السوء معجب به، ولكل مفتخر بما لم يعمل، ليُثنيَ عليه الناس ويحمدوه.", "isBasmala": false, "translation_en": "Do not think that those who rejoice in what they have done, and love to be praised for what they have not done-do not think they can evade the punishment. They will have a painful punishment.", "translation_id": "Janganlah sekali-kali kamu menyangka, hahwa orang-orang yang gembira dengan apa yang telah mereka kerjakan dan mereka suka supaya dipuji terhadap perbuatan yang belum mereka kerjakan janganlah kamu menyangka bahwa mereka terlepas dari siksa, dan bagi mereka siksa yang pedih.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 189, "text": "وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝١٨٩", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "ولله وحده ملك السموات والأرض وما فيهما، والله على كل شيء قدير.", "isBasmala": false, "translation_en": "To God belongs the sovereignty of the heavens and the earth. God has power over all things.", "translation_id": "kepunyaan Allah-lah kerajaan langit dan bumi, dan Allah Maha Perkasa atas segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 190, "text": "إِنَّ فِی خَلۡقِ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَـٰفِ ٱلَّیۡلِ وَٱلنَّهَارِ لَـَٔایَـٰتࣲ لِّأُو۟لِی ٱلۡأَلۡبَـٰبِ ۝١٩٠", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "إن في خلق السموات والأرض على غير مثال سابق، وفي تعاقُب الليل والنهار، واختلافهما طولا وقِصَرًا لدلائل وبراهين عظيمة على وحدانية الله لأصحاب العقول السليمة.", "isBasmala": false, "translation_en": "In the creation of the heavens and the earth, and in the alternation of night and day, are signs for people of understanding.", "translation_id": "Sesungguhnya dalam penciptaan langit dan bumi, dan silih bergantinya malam dan siang terdapat tanda-tanda bagi orang-orang yang berakal,", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 191, "text": "ٱلَّذِینَ یَذۡكُرُونَ ٱللَّهَ قِیَـٰمࣰا وَقُعُودࣰا وَعَلَىٰ جُنُوبِهِمۡ وَیَتَفَكَّرُونَ فِی خَلۡقِ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ رَبَّنَا مَا خَلَقۡتَ هَـٰذَا بَـٰطِلࣰا سُبۡحَـٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ ۝١٩١", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "الذين يذكرون الله في جميع أحوالهم: قيامًا وقعودًا وعلى جنوبهم، وهم يتدبرون في خلق السموات والأرض، قائلين: يا ربنا ما أوجدت هذا الخلق عبثًا، فأنت منزَّه عن ذلك، فاصْرِف عنا عذاب النار.", "isBasmala": false, "translation_en": "Those who remember God while standing, and sitting, and on their sides; and they reflect upon the creation of the heavens and the earth: \"Our Lord, You did not create this in vain, glory to You, so protect us from the punishment of the Fire.\"", "translation_id": "(yaitu) orang-orang yang mengingat Allah sambil berdiri atau duduk atau dalam keadan berbaring dan mereka memikirkan tentang penciptaan langit dan bumi (seraya berkata): \"Ya Tuhan kami, tiadalah Engkau menciptakan ini dengan sia-sia, Maha Suci Engkau, maka peliharalah kami dari siksa neraka.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 192, "text": "رَبَّنَاۤ إِنَّكَ مَن تُدۡخِلِ ٱلنَّارَ فَقَدۡ أَخۡزَیۡتَهُۥۖ وَمَا لِلظَّـٰلِمِینَ مِنۡ أَنصَارࣲ ۝١٩٢", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "يا ربنا نجِّنا من النار، فإنك -يا ألله- مَن تُدخِلْه النار بذنوبه فقد فضحته وأهنته، وما للمذنبين الظالمين لأنفسهم من أحد يدفع عنهم عقاب الله يوم القيامة.", "isBasmala": false, "translation_en": "\"Our Lord, whomever You commit to the Fire, You have disgraced. The wrongdoers will have no helpers.\"", "translation_id": "Ya Tuhan kami, sesungguhnya barangsiapa yang Engkau masukkan ke dalam neraka, maka sungguh telah Engkau hinakan ia, dan tidak ada bagi orang-orang yang zalim seorang penolongpun.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 193, "text": "رَّبَّنَاۤ إِنَّنَا سَمِعۡنَا مُنَادِیࣰا یُنَادِی لِلۡإِیمَـٰنِ أَنۡ ءَامِنُوا۟ بِرَبِّكُمۡ فَـَٔامَنَّاۚ رَبَّنَا فَٱغۡفِرۡ لَنَا ذُنُوبَنَا وَكَفِّرۡ عَنَّا سَیِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلۡأَبۡرَارِ ۝١٩٣", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "يا ربنا إننا سمعنا مناديا -هو نبيك محمد صلى الله عليه وسلم- ينادي الناس للتصديق بك، والإقرار بوحدانيتك، والعمل بشرعك، فأجبنا دعوته وصدَّقنا رسالته، فاغفر لنا ذنوبنا، واستر عيوبنا، وألحقنا بالصالحين.", "isBasmala": false, "translation_en": "\"Our Lord, we have heard a caller calling to the faith: `Believe in your Lord,' and we have believed. Our Lord! Forgive us our sins, and remit our misdeeds, and make us die in the company of the virtuous.\"", "translation_id": "Ya Tuhan kami, sesungguhnya kami mendengar (seruan) yang menyeru kepada iman, (yaitu): \"Berimanlah kamu kepada Tuhanmu\", maka kamipun beriman. Ya Tuhan kami, ampunilah bagi kami dosa-dosa kami dan hapuskanlah dari kami kesalahan-kesalahan kami, dan wafatkanlah kami beserta orang-orang yang banyak berbakti.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 194, "text": "رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخۡزِنَا یَوۡمَ ٱلۡقِیَـٰمَةِۖ إِنَّكَ لَا تُخۡلِفُ ٱلۡمِیعَادَ ۝١٩٤", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "يا ربنا أعطنا ما وعدتنا على ألسنة رسلك من نصر وتمكين وتوفيق وهداية، ولا تفضحنا بذنوبنا يوم القيامة، فإنك كريم لا تُخْلف وعدًا وَعَدْتَ به عبادك.", "isBasmala": false, "translation_en": "\"Our Lord, and give us what You have promised us through Your messengers, and do not disgrace us on the Day of Resurrection. Surely You never break a promise.\"", "translation_id": "Ya Tuhan kami, berilah kami apa yang telah Engkau janjikan kepada kami dengan perantaraan rasul-rasul Engkau. Dan janganlah Engkau hinakan kami di hari kiamat. Sesungguhnya Engkau tidak menyalahi janji\".", "manzil": 1, "manzil_display": ""}], "76": [{"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 195, "text": "فَٱسۡتَجَابَ لَهُمۡ رَبُّهُمۡ أَنِّی لَاۤ أُضِیعُ عَمَلَ عَـٰمِلࣲ مِّنكُم مِّن ذَكَرٍ أَوۡ أُنثَىٰۖ بَعۡضُكُم مِّنۢ بَعۡضࣲۖ فَٱلَّذِینَ هَاجَرُوا۟ وَأُخۡرِجُوا۟ مِن دِیَـٰرِهِمۡ وَأُوذُوا۟ فِی سَبِیلِی وَقَـٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنۡهُمۡ سَیِّـَٔاتِهِمۡ وَلَأُدۡخِلَنَّهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ ثَوَابࣰا مِّنۡ عِندِ ٱللَّهِۚ وَٱللَّهُ عِندَهُۥ حُسۡنُ ٱلثَّوَابِ ۝١٩٥", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "فأجاب الله دعاءهم بأنه لا يضيع جهد مَن عمل منهم عملا صالحًا ذكرًا كان أو أنثى، وهم في أُخُوَّة الدين وقَبول الأعمال والجزاء عليها سواء، فالذين هاجروا رغبةً في رضا الله تعالى، وأُخرجوا من ديارهم، وأوذوا في طاعة ربهم وعبادتهم إيّاه، وقاتلوا وقُتِلوا في سبيل الله لإعلاء كلمته، ليسترنَّ الله عليهم ما ارتكبوه من المعاصي، كما سترها عليهم في الدنيا، فلا يحاسبهم عليها، وليدخلنَّهم جنات تجري من تحت قصورها وأشجارها الأنهار جزاء من عند الله، والله عنده حسن الثواب.", "isBasmala": false, "translation_en": "And so their Lord answered them: \"I will not waste the work of any worker among you, whether male or female. You are one of another. For those who emigrated, and were expelled from their homes, and were persecuted because of Me, and fought and were killed-I will remit for them their sins, and will admit them into gardens beneath which rivers flow-a reward from God. With God is the ultimate reward.\"", "translation_id": "Maka Tuhan mereka memperkenankan permohonannya (dengan berfirman): \"Sesungguhnya Aku tidak menyia-nyiakan amal orang-orang yang beramal di antara kamu, baik laki-laki atau perempuan, (karena) sebagian kamu adalah turunan dari sebagian yang lain. Maka orang-orang yang berhijrah, yang diusir dari kampung halamannya, yang disakiti pada jalan-Ku, yang berperang dan yang dibunuh, pastilah akan Ku-hapuskan kesalahan-kesalahan mereka dan pastilah Aku masukkan mereka ke dalam surga yang mengalir sungai-sungai di bawahnya, sebagai pahala di sisi Allah. Dan Allah pada sisi-Nya pahala yang baik\".", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 196, "text": "لَا یَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِینَ كَفَرُوا۟ فِی ٱلۡبِلَـٰدِ ۝١٩٦", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "لا تغتر -أيها الرسول- بما عليه أهل الكفر بالله من بسطة في العيش، وسَعَة في الرزق، وانتقالهم من مكان إلى مكان للتجارات وطلب الأرباح والأموال، فعمَّا قليل يزول هذا كلُّه عنهم، ويصبحون مرتهنين بأعمالهم السيئة.", "isBasmala": false, "translation_en": "Do not be impressed by the disbelievers' movements in the land.", "translation_id": "Janganlah sekali-kali kamu terperdaya oleh kebebasan orang-orang kafir bergerak di dalam negeri.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 197, "text": "مَتَـٰعࣱ قَلِیلࣱ ثُمَّ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ ۝١٩٧", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "متاع قليل زائل، ثم يكون مصيرهم يوم القيامة إلى النار، وبئس الفراش.", "isBasmala": false, "translation_en": "A brief enjoyment, then their abode is Hell. What a miserable resort.", "translation_id": "Itu hanyalah kesenangan sementara, kemudian tempat tinggal mereka ialah Jahannam; dan Jahannam itu adalah tempat yang seburuk-buruknya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 198, "text": "لَـٰكِنِ ٱلَّذِینَ ٱتَّقَوۡا۟ رَبَّهُمۡ لَهُمۡ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا نُزُلࣰا مِّنۡ عِندِ ٱللَّهِۗ وَمَا عِندَ ٱللَّهِ خَیۡرࣱ لِّلۡأَبۡرَارِ ۝١٩٨", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "لكن الذين خافوا ربهم، وامتثلوا أوامره، واجتنبوا نواهيه، قد أعدَّ الله لهم جنات تجري من تحت أشجارها الأنهار، هي منزلهم الدائم لا يخرجون منه. وما عد الله أعظم وأفضل لأهل الطاعة مما يتقلب فيه الذين كفروا من نعيم الدنيا.", "isBasmala": false, "translation_en": "As for those who feared their Lord: for them will be gardens beneath which rivers flow, wherein they will abide forever-hospitality from God. What God possesses is best for the just.", "translation_id": "Akan tetapi orang-orang yang bertakwa kepada Tuhannya, bagi mereka surga yang mengalir sungai-sungai di dalamnya, sedang mereka kekal di dalamnya sebagai tempat tinggal (anugerah) dari sisi Allah. Dan apa yang di sisi Allah adalah lebih baik bagi orang-orang yang berbakti.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 199, "text": "وَإِنَّ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ لَمَن یُؤۡمِنُ بِٱللَّهِ وَمَاۤ أُنزِلَ إِلَیۡكُمۡ وَمَاۤ أُنزِلَ إِلَیۡهِمۡ خَـٰشِعِینَ لِلَّهِ لَا یَشۡتَرُونَ بِـَٔایَـٰتِ ٱللَّهِ ثَمَنࣰا قَلِیلًاۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ أَجۡرُهُمۡ عِندَ رَبِّهِمۡۗ إِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ ۝١٩٩", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "وإن بعضًا من أهل الكتاب لَيصدِّق بالله ربًّا واحدًا وإلهًا معبودًا، وبما أُنزِل إليكم من هذا القرآن، وبما أُنزِل إليهم من التوراة والإنجيل متذللين لله، خاضعين له، لا يشترون بآيات الله ثمنًا قليلا من حطام الدنيا، ولا يكتمون ما أنزل الله، ولا يحرفونه كغيرهم من أهل الكتاب. أولئك لهم ثواب عظيم عنده يوم يلقونه، فيوفيهم إياه غير منقوص. إنَّ الله سريع الحساب، لا يعجزه إحصاء أعمالهم، ومحاسبتهم عليها.", "isBasmala": false, "translation_en": "Among the People of the Scripture are those who believe in God, and in what was revealed to you, and in what was revealed to them. They are humble before God, and they do not sell God's revelations for a cheap price. These will have their reward with their Lord. God is swift in reckoning.", "translation_id": "Dan sesungguhnya diantara ahli kitab ada orang yang beriman kepada Allah dan kepada apa yang diturunkan kepada kamu dan yang diturunkan kepada mereka sedang mereka berendah hati kepada Allah dan mereka tidak menukarkan ayat-ayat Allah dengan harga yang sedikit. Mereka memperoleh pahala di sisi Tuhannya. Sesungguhnya Allah amat cepat perhitungan-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 3, "sura_name": "آل عمران", "revelation": "Madaniyah", "aya": 200, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱصۡبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ ۝٢٠٠", "juz": 4, "hizb": "(*¼ ح 8*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه اصبروا على طاعة ربكم، وعلى ما ينزل بكم من ضر وبلاء، وصابروا أعداءكم حتى لا يكونوا أشد صبرًا منكم، وأقيموا على جهاد عدوي وعدوكم، وخافوا الله في جميع أحوالكم؛ رجاء أن تفوزوا برضاه في الدنيا والآخرة.", "isBasmala": false, "translation_en": "O you who believe! Be patient, and advocate patience, and be united, and revere God, so that you may thrive.", "translation_id": "Hai orang-orang yang beriman, bersabarlah kamu dan kuatkanlah kesabaranmu dan tetaplah bersiap siaga (di perbatasan negerimu) dan bertakwalah kepada Allah, supaya kamu beruntung.", "manzil": 1, "manzil_display": ""}], "77": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 6, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 1, "text": "۞ یَـٰۤأَیُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمُ ٱلَّذِی خَلَقَكُم مِّن نَّفۡسࣲ وَ ٰحِدَةࣲ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالࣰا كَثِیرࣰا وَنِسَاۤءࣰۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِی تَسَاۤءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَیۡكُمۡ رَقِیبࣰا ۝١", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "يا أيها الناس خافوا الله والتزموا أوامره، واجتنبوا نواهيه؛ فهو الذي خلقكم من نفس واحدة هي آدم عليه السلام، وخلق منها زوجها وهي حواء، ونشر منهما في أنحاء الأرض رجالا كثيرًا ونساء كثيرات، وراقبوا الله الذي يَسْأل به بعضكم بعضًا، واحذروا أن تقطعوا أرحامكم. إن الله مراقب لجميع أحوالكم.", "isBasmala": false, "translation_en": "O people! Fear your Lord, who created you from a single soul, and created from it its mate, and propagated from them many men and women. And revere God whom you ask about, and the parents. Surely, God is Watchful over you.", "translation_id": "Hai sekalian manusia, bertakwalah kepada Tuhan-mu yang telah menciptakan kamu dari seorang diri, dan dari padanya Allah menciptakan isterinya; dan dari pada keduanya Allah memperkembang biakkan laki-laki dan perempuan yang banyak. Dan bertakwalah kepada Allah yang dengan (mempergunakan) nama-Nya kamu saling meminta satu sama lain, dan (peliharalah) hubungan silaturrahim. Sesungguhnya Allah selalu menjaga dan mengawasi kamu.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 2, "text": "وَءَاتُوا۟ ٱلۡیَتَـٰمَىٰۤ أَمۡوَ ٰلَهُمۡۖ وَلَا تَتَبَدَّلُوا۟ ٱلۡخَبِیثَ بِٱلطَّیِّبِۖ وَلَا تَأۡكُلُوۤا۟ أَمۡوَ ٰلَهُمۡ إِلَىٰۤ أَمۡوَ ٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبࣰا كَبِیرࣰا ۝٢", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "وأعطوا مَن مات آباؤهم وهم دون البلوغ، وكنتم عليهم أوصياء، أموالهم إذا وصلوا سن البلوغ، ورأيتم منهم قدرة على حفظ أموالهم، ولا تأخذوا الجيِّد من أموالهم، وتجعلوا مكانه الرديء من أموالكم، ولا تخلطوا أموالهم بأموالكم؛ لتحتالوا بذلك على أكل أموالهم. إن من تجرأ على ذلك فقد ارتكب إثمًا عظيمًا.", "isBasmala": false, "translation_en": "And give orphans their properties, and do not substitute the bad for the good. And do not consume their properties by combining them with yours, for that would be a serious sin.", "translation_id": "Dan berikanlah kepada anak-anak yatim (yang sudah balig) harta mereka, jangan kamu menukar yang baik dengan yang buruk dan jangan kamu makan harta mereka bersama hartamu. Sesungguhnya tindakan-tindakan (menukar dan memakan) itu, adalah dosa yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 3, "text": "وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُوا۟ فِی ٱلۡیَتَـٰمَىٰ فَٱنكِحُوا۟ مَا طَابَ لَكُم مِّنَ ٱلنِّسَاۤءِ مَثۡنَىٰ وَثُلَـٰثَ وَرُبَـٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُوا۟ فَوَ ٰحِدَةً أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُكُمۡۚ ذَ ٰلِكَ أَدۡنَىٰۤ أَلَّا تَعُولُوا۟ ۝٣", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "وإن خفتم ألا تعدلوا في يتامى النساء اللاتي تحت أيديكم بأن لا تعطوهن مهورهن كغيرهن، فاتركوهن وانكحوا ما طاب لكم من النساء من غيرهن: اثنتين أو ثلاثًا أو أربعًا، فإن خشيتم ألا تعدلوا بينهن فاكتفوا بواحدة، أو بما عندكم من الإماء. ذلك الذي شرعته لكم في اليتيمات والزواج من واحدة إلى أربع، أو الاقتصار على واحدة أو ملك اليمين، أقرب إلى عدم الجَوْرِ والتعدي.", "isBasmala": false, "translation_en": "If you fear you cannot act fairly towards the orphans-then marry the women you like-two, or three, or four. But if you fear you will not be fair, then one, or what you already have. That makes it more likely that you avoid bias.", "translation_id": "Dan jika kamu takut tidak akan dapat berlaku adil terhadap (hak-hak) perempuan yang yatim (bilamana kamu mengawininya), maka kawinilah wanita-wanita (lain) yang kamu senangi: dua, tiga atau empat. Kemudian jika kamu takut tidak akan dapat berlaku adil, maka (kawinilah) seorang saja, atau budak-budak yang kamu miliki. Yang demikian itu adalah lebih dekat kepada tidak berbuat aniaya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 4, "text": "وَءَاتُوا۟ ٱلنِّسَاۤءَ صَدُقَـٰتِهِنَّ نِحۡلَةࣰۚ فَإِن طِبۡنَ لَكُمۡ عَن شَیۡءࣲ مِّنۡهُ نَفۡسࣰا فَكُلُوهُ هَنِیۤـࣰٔا مَّرِیۤـࣰٔا ۝٤", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "وأعطوا النساء مهورهن، عطية واجبة وفريضة لازمة عن طيب نفس منكم. فإن طابت أنفسهن لكم عن شيء من المهر فوهَبْنه لكم فخذوه، وتصرَّفوا فيه، فهو حلال طيب.", "isBasmala": false, "translation_en": "Give women their dowries graciously. But if they willingly forego some of it, then consume it with enjoyment and pleasure.", "translation_id": "Berikanlah maskawin (mahar) kepada wanita (yang kamu nikahi) sebagai pemberian dengan penuh kerelaan. Kemudian jika mereka menyerahkan kepada kamu sebagian dari maskawin itu dengan senang hati, maka makanlah (ambillah) pemberian itu (sebagai makanan) yang sedap lagi baik akibatnya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 5, "text": "وَلَا تُؤۡتُوا۟ ٱلسُّفَهَاۤءَ أَمۡوَ ٰلَكُمُ ٱلَّتِی جَعَلَ ٱللَّهُ لَكُمۡ قِیَـٰمࣰا وَٱرۡزُقُوهُمۡ فِیهَا وَٱكۡسُوهُمۡ وَقُولُوا۟ لَهُمۡ قَوۡلࣰا مَّعۡرُوفࣰا ۝٥", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "ولا تؤتوا -أيها الأولياء- من يُبَذِّر من الرجال والنساء والصبيان أموالهم التي تحت أيديكم فيضعوها في غير وجهها، فهذه الأموال هي التي عليها قيام حياة الناس، وأنفقوا عليهم منها واكسوهم، وقولوا لهم قولا معروفًا من الكلام الطيب والخلق الحسن.", "isBasmala": false, "translation_en": "Do not give the immature your money which God has assigned to you for support. But provide for them from it, and clothe them, and speak to them with kind words.", "translation_id": "Dan janganlah kamu serahkan kepada orang-orang yang belum sempurna akalnya, harta (mereka yang ada dalam kekuasaanmu) yang dijadikan Allah sebagai pokok kehidupan. Berilah mereka belanja dan pakaian (dari hasil harta itu) dan ucapkanlah kepada mereka kata-kata yang baik.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 6, "text": "وَٱبۡتَلُوا۟ ٱلۡیَتَـٰمَىٰ حَتَّىٰۤ إِذَا بَلَغُوا۟ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدࣰا فَٱدۡفَعُوۤا۟ إِلَیۡهِمۡ أَمۡوَ ٰلَهُمۡۖ وَلَا تَأۡكُلُوهَاۤ إِسۡرَافࣰا وَبِدَارًا أَن یَكۡبَرُوا۟ۚ وَمَن كَانَ غَنِیࣰّا فَلۡیَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِیرࣰا فَلۡیَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَیۡهِمۡ أَمۡوَ ٰلَهُمۡ فَأَشۡهِدُوا۟ عَلَیۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِیبࣰا ۝٦", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "واختبروا مَن تحت أيديكم من اليتامى لمعرفة قدرتهم على حسن التصرف في أموالهم، حتى إذا وصلوا إلى سن البلوغ، وعَلمتم منهم صلاحًا في دينهم، وقدرة على حفظ أموالهم، فسلِّموها لهم، ولا تعتدوا عليها بإنفاقها في غير موضعها إسرافًا ومبادرة لأكلها قبل أن يأخذوها منكم. ومَن كان صاحب مال منكم فليستعفف بغناه، ولا يأخذ من مال اليتيم شيئًا، ومن كان فقيرًا فليأخذ بقدر حاجته عند الضرورة. فإذا علمتم أنهم قادرون على حفظ أموالهم بعد بلوغهم الحُلُم وسلمتموها إليهم، فأَشْهِدوا عليهم؛ ضمانًا لوصول حقهم كاملا إليهم؛ لئلا ينكروا ذلك. ويكفيكم أن الله شاهد عليكم، ومحاسب لكم على ما فعلتم.", "isBasmala": false, "translation_en": "Test the orphans until they reach the age of marriage. If you find them to be mature enough, hand over their properties to them. And do not consume it extravagantly or hastily before they grow up. The rich shall not charge any wage, but the poor may charge fairly. When you hand over their properties to them, have it witnessed for them. God suffices as a Reckoner.", "translation_id": "Dan ujilah anak yatim itu sampai mereka cukup umur untuk kawin. Kemudian jika menurut pendapatmu mereka telah cerdas (pandai memelihara harta), maka serahkanlah kepada mereka harta-hartanya. Dan janganlah kamu makan harta anak yatim lebih dari batas kepatutan dan (janganlah kamu) tergesa-gesa (membelanjakannya) sebelum mereka dewasa. Barang siapa (di antara pemelihara itu) mampu, maka hendaklah ia menahan diri (dari memakan harta anak yatim itu) dan barangsiapa yang miskin, maka bolehlah ia makan harta itu menurut yang patut. Kemudian apabila kamu menyerahkan harta kepada mereka, maka hendaklah kamu adakan saksi-saksi (tentang penyerahan itu) bagi mereka. Dan cukuplah Allah sebagai Pengawas (atas persaksian itu).", "manzil": 1, "manzil_display": ""}], "78": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 7, "text": "لِّلرِّجَالِ نَصِیبࣱ مِّمَّا تَرَكَ ٱلۡوَ ٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَاۤءِ نَصِیبࣱ مِّمَّا تَرَكَ ٱلۡوَ ٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِیبࣰا مَّفۡرُوضࣰا ۝٧", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "للذكور -صغارًا أو كبارًا- نصيب شرعه الله فيما تركه الوالدان والأقربون من المال، قليلا كان أو كثيرًا، في أنصبة محددة واضحة فرضها الله عز وجل لهؤلاء، وللنساء كذلك.", "isBasmala": false, "translation_en": "Men receive a share of what their parents and relatives leave, and women receive a share of what their parents and relatives leave; be it little or much-a legal share.", "translation_id": "Bagi orang laki-laki ada hak bagian dari harta peninggalan ibu-bapa dan kerabatnya, dan bagi orang wanita ada hak bagian (pula) dari harta peninggalan ibu-bapa dan kerabatnya, baik sedikit atau banyak menurut bahagian yang telah ditetapkan.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 8, "text": "وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُو۟لُوا۟ ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُوا۟ لَهُمۡ قَوۡلࣰا مَّعۡرُوفࣰا ۝٨", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "وإذا حضر قسمةَ الميراث أقاربُ الميت ممن لا حقَّ لهم في التركة، أو حضرها من مات آباؤهم وهم صغار، أو مَن لا مال لهم فأعطوهم شيئًا من المال على وجه الاستحباب قبل تقسيم التركة على أصحابها، وقولوا لهم قولا حسنًا غير فاحش ولا قبيح.", "isBasmala": false, "translation_en": "If the distribution is attended by the relatives, and the orphans, and the needy, give them something out of it, and speak to them kindly.", "translation_id": "Dan apabila sewaktu pembagian itu hadir kerabat, anak yatim dan orang miskin, maka berilah mereka dari harta itu (sekedarnya) dan ucapkanlah kepada mereka perkataan yang baik.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 9, "text": "وَلۡیَخۡشَ ٱلَّذِینَ لَوۡ تَرَكُوا۟ مِنۡ خَلۡفِهِمۡ ذُرِّیَّةࣰ ضِعَـٰفًا خَافُوا۟ عَلَیۡهِمۡ فَلۡیَتَّقُوا۟ ٱللَّهَ وَلۡیَقُولُوا۟ قَوۡلࣰا سَدِیدًا ۝٩", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "ولْيَخَفِ الذين لو ماتوا وتركوا من خلفهم أبناء صغارًا ضعافًا خافوا عليهم الظلم والضياع، فليراقبوا الله فيمن تحت أيديهم من اليتامى وغيرهم، وذلك بحفظ أموالهم، وحسن تربيتهم، ودَفْع الأذى عنهم، وليقولوا لهم قولا موافقا للعدل والمعروف.", "isBasmala": false, "translation_en": "Those who are concerned about the fate of their weak children, in case they leave them behind, should fear God, and speak appropriate words.", "translation_id": "Dan hendaklah takut kepada Allah orang-orang yang seandainya meninggalkan dibelakang mereka anak-anak yang lemah, yang mereka khawatir terhadap (kesejahteraan) mereka. Oleh sebab itu hendaklah mereka bertakwa kepada Allah dan hendaklah mereka mengucapkan perkataan yang benar.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 10, "text": "إِنَّ ٱلَّذِینَ یَأۡكُلُونَ أَمۡوَ ٰلَ ٱلۡیَتَـٰمَىٰ ظُلۡمًا إِنَّمَا یَأۡكُلُونَ فِی بُطُونِهِمۡ نَارࣰاۖ وَسَیَصۡلَوۡنَ سَعِیرࣰا ۝١٠", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "إن الذين يعْتَدون على أموال اليتامى، فيأخذونها بغير حق، إنما يأكلون نارًا تتأجّج في بطونهم يوم القيامة، وسيدخلون نارا يقاسون حرَّها.", "isBasmala": false, "translation_en": "Those who consume the wealth of orphans illicitly consume only fire into their bellies; and they will roast in a Blaze.", "translation_id": "Sesungguhnya orang-orang yang memakan harta anak yatim secara zalim, sebenarnya mereka itu menelan api sepenuh perutnya dan mereka akan masuk ke dalam api yang menyala-nyala (neraka).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 11, "text": "یُوصِیكُمُ ٱللَّهُ فِیۤ أَوۡلَـٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَیَیۡنِۚ فَإِن كُنَّ نِسَاۤءࣰ فَوۡقَ ٱثۡنَتَیۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَ ٰحِدَةࣰ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَیۡهِ لِكُلِّ وَ ٰحِدࣲ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدࣱۚ فَإِن لَّمۡ یَكُن لَّهُۥ وَلَدࣱ وَوَرِثَهُۥۤ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥۤ إِخۡوَةࣱ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِیَّةࣲ یُوصِی بِهَاۤ أَوۡ دَیۡنٍۗ ءَابَاۤؤُكُمۡ وَأَبۡنَاۤؤُكُمۡ لَا تَدۡرُونَ أَیُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعࣰاۚ فَرِیضَةࣰ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا ۝١١", "juz": 4, "hizb": "(*½ ح 8*)", "tafsir": "يوصيكم الله ويأمركم في شأن أولادكم: إذا مات أحد منكم وترك أولادًا: ذكورًا وإناثًا، فميراثه كله لهم: للذكر مثل نصيب الأنثيين، إذا لم يكن هناك وارث غيرهم. فإن ترك بنات فقط فللبنتين فأكثر ثلثا ما ترك، وإن كانت ابنة واحدة، فلها النصف. ولوالِدَي الميت لكل واحد منهما السدس إن كان له ولد: ذكرًا كان أو أنثى، واحدًا أو أكثر. فإن لم يكن له ولد وورثه والداه فلأمه الثلث ولأبيه الباقي. فإن كان للميت إخوة اثنان فأكثر، ذكورًا كانوا أو إناثًا، فلأمه السدس، وللأب الباقي ولا شيء للإخوة. وهذا التقسيم للتركة إنما يكون بعد إخراج وصية الميت في حدود الثلث أو إخراج ما عليه من دَيْن. آباؤكم وأبْناؤكم الذين فُرِض لهم الإرث لا تعرفون أيهم أقرب لكم نفعًا في دنياكم وأخراكم، فلا تفضلوا واحدًا منهم على الآخر. هذا الذي أوصيتكم به مفروض عليكم من الله. إن الله كان عليمًا بخلقه، حكيمًا فيما شرعه لهم.", "isBasmala": false, "translation_en": "God instructs you regarding your children: The male receives the equivalent of the share of two females. If they are daughters, more than two, they get two-thirds of what he leaves. If there is only one, she gets one-half. As for the parents, each gets one-sixth of what he leaves, if he had children. If he had no children, and his parents inherit from him, his mother gets one-third. If he has siblings, his mother gets one-sixth. After fulfilling any bequest and paying off debts. Your parents and your children-you do not know which are closer to you in welfare. This is God's Law. God is Knowing and Judicious.", "translation_id": "Allah mensyari'atkan bagimu tentang (pembagian pusaka untuk) anak-anakmu. Yaitu: bahagian seorang anak lelaki sama dengan bagahian dua orang anak perempuan; dan jika anak itu semuanya perempuan lebih dari dua, maka bagi mereka dua pertiga dari harta yang ditinggalkan; jika anak perempuan itu seorang saja, maka ia memperoleh separo harta. Dan untuk dua orang ibu-bapa, bagi masing-masingnya seperenam dari harta yang ditinggalkan, jika yang meninggal itu mempunyai anak; jika orang yang meninggal tidak mempunyai anak dan ia diwarisi oleh ibu-bapanya (saja), maka ibunya mendapat sepertiga; jika yang meninggal itu mempunyai beberapa saudara, maka ibunya mendapat seperenam. (Pembagian-pembagian tersebut di atas) sesudah dipenuhi wasiat yang ia buat atau (dan) sesudah dibayar hutangnya. (Tentang) orang tuamu dan anak-anakmu, kamu tidak mengetahui siapa di antara mereka yang lebih dekat (banyak) manfaatnya bagimu. Ini adalah ketetapan dari Allah. Sesungguhnya Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}], "79": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 12, "text": "۞ وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَ ٰجُكُمۡ إِن لَّمۡ یَكُن لَّهُنَّ وَلَدࣱۚ فَإِن كَانَ لَهُنَّ وَلَدࣱ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِیَّةࣲ یُوصِینَ بِهَاۤ أَوۡ دَیۡنࣲۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ یَكُن لَّكُمۡ وَلَدࣱۚ فَإِن كَانَ لَكُمۡ وَلَدࣱ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِیَّةࣲ تُوصُونَ بِهَاۤ أَوۡ دَیۡنࣲۗ وَإِن كَانَ رَجُلࣱ یُورَثُ كَلَـٰلَةً أَوِ ٱمۡرَأَةࣱ وَلَهُۥۤ أَخٌ أَوۡ أُخۡتࣱ فَلِكُلِّ وَ ٰحِدࣲ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوۤا۟ أَكۡثَرَ مِن ذَ ٰلِكَ فَهُمۡ شُرَكَاۤءُ فِی ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِیَّةࣲ یُوصَىٰ بِهَاۤ أَوۡ دَیۡنٍ غَیۡرَ مُضَاۤرࣲّۚ وَصِیَّةࣰ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِیمٌ حَلِیمࣱ ۝١٢", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "ولكم -أيها الرجال- نصف ما ترك أزواجكم بعد وفاتهن إن لم يكن لهن ولد ذكرًا كان أو أنثى، فإن كان لهن ولد فلكم الربع مما تركن، ترثونه من بعد إنفاذ وصيتهن الجائزة، أو ما يكون عليهن من دَيْن لمستحقيه. ولأزواجكم - أيها الرجال - الربع مما تركتم، إن لم يكن لكم ابن أو ابنة منهن أو من غيرهن، فإن كان لكم ابن أو ابنة فلهن الثمن مما تركتم، يقسم الربع أو الثمن بينهن، فإن كانت زوجة واحدة كان هذا ميراثًا لها، من بعد إنفاذ ما كنتم أوصيتم به من الوصايا الجائزة، أو قضاء ما يكون عليكم من دَيْن. وإن مات رجل أو امراة وليس له أو لها ولد ولا والد، وله أو لها أخ أو أخت من أم فلكل واحد منهما السدس. فإن كان الإخوة أو الأخوات لأم أكثر من ذلك فهم شركاء في الثلث يقسم بينهم بالسوية لا فرق بين الذكر والأنثى، وهذا الذي فرضه الله للإخوة والأخوات لأم يأخذونه ميراثًا لهم من بعد قضاء ديون الميت، وإنفاذ وصيته إن كان قد أوصى بشيء لا ضرر فيه على الورثة. بهذا أوصاكم ربكم وصية نافعة لكم. والله عليم بما يصلح خلقه، حليم لا يعاجلهم بالعقوبة.", "isBasmala": false, "translation_en": "You get one-half of what your wives leave behind, if they had no children. If they had children, you get one-fourth of what they leave. After fulfilling any bequest and paying off debts. They get one-fourth of what you leave behind, if you have no children. If you have children, they get one-eighth of what you leave. After fulfilling any bequest and paying off debts. If a man or woman leaves neither parents nor children, but has a brother or sister, each of them gets one-sixth. If there are more siblings, they share one-third. After fulfilling any bequest and paying off debts, without any prejudice. This is a will from God. God is Knowing and Clement.", "translation_id": "Dan bagimu (suami-suami) seperdua dari harta yang ditinggalkan oleh isteri-isterimu, jika mereka tidak mempunyai anak. Jika isteri-isterimu itu mempunyai anak, maka kamu mendapat seperempat dari harta yang ditinggalkannya sesudah dipenuhi wasiat yang mereka buat atau (dan) seduah dibayar hutangnya. Para isteri memperoleh seperempat harta yang kamu tinggalkan jika kamu tidak mempunyai anak. Jika kamu mempunyai anak, maka para isteri memperoleh seperdelapan dari harta yang kamu tinggalkan sesudah dipenuhi wasiat yang kamu buat atau (dan) sesudah dibayar hutang-hutangmu. Jika seseorang mati, baik laki-laki maupun perempuan yang tidak meninggalkan ayah dan tidak meninggalkan anak, tetapi mempunyai seorang saudara laki-laki (seibu saja) atau seorang saudara perempuan (seibu saja), maka bagi masing-masing dari kedua jenis saudara itu seperenam harta. Tetapi jika saudara-saudara seibu itu lebih dari seorang, maka mereka bersekutu dalam yang sepertiga itu, sesudah dipenuhi wasiat yang dibuat olehnya atau sesudah dibayar hutangnya dengan tidak memberi mudharat (kepada ahli waris). (Allah menetapkan yang demikian itu sebagai) syari'at yang benar-benar dari Allah, dan Allah Maha Mengetahui lagi Maha Penyantun.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 13, "text": "تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن یُطِعِ ٱللَّهَ وَرَسُولَهُۥ یُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ وَذَ ٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝١٣", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "تلك الأحكام الإلهية التي شرعها الله في اليتامى والنساء والمواريث، شرائعه الدالة على أنها مِن عند الله العليم الحكيم. ومَن يطع الله ورسوله فيما شرع لعباده من هذه الأحكام وغيرها، يدخله جنات كثيرة الأشجار والقصور، تجري من تحتها الأنهار بمياهها العذبة، وهم باقون في هذا النعيم، لا يخرجون منه، وذلك الثواب هو الفلاح العظيم.", "isBasmala": false, "translation_en": "These are the bounds set by God. Whoever obeys God and His Messenger, He will admit him into Gardens beneath which rivers flow, to abide therein forever. That is the great attainment.", "translation_id": "(Hukum-hukum tersebut) itu adalah ketentuan-ketentuan dari Allah. Barangsiapa taat kepada Allah dan Rasul-Nya, niscaya Allah memasukkannya kedalam surga yang mengalir didalamnya sungai-sungai, sedang mereka kekal di dalamnya; dan itulah kemenangan yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 14, "text": "وَمَن یَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَیَتَعَدَّ حُدُودَهُۥ یُدۡخِلۡهُ نَارًا خَـٰلِدࣰا فِیهَا وَلَهُۥ عَذَابࣱ مُّهِینࣱ ۝١٤", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "ومَن يَعْصِ الله ورسوله، بإنكاره لأحكام الله، وتجاوزه ما شرعه الله لعباده بتغييرها، أو تعطيل العمل بها، يدخله نارًا ماكثًا فيها، وله عذاب يخزيه ويهينه.", "isBasmala": false, "translation_en": "But whoever disobeys God and His Messenger, and oversteps His bounds, He will admit him into a Fire, wherein he abides forever, and he will have a shameful punishment.", "translation_id": "Dan barangsiapa yang mendurhakai Allah dan Rasul-Nya dan melanggar ketentuan-ketentuan-Nya, niscaya Allah memasukkannya ke dalam api neraka sedang ia kekal di dalamnya; dan baginya siksa yang menghinakan.", "manzil": 1, "manzil_display": ""}], "80": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 15, "text": "وَٱلَّـٰتِی یَأۡتِینَ ٱلۡفَـٰحِشَةَ مِن نِّسَاۤىِٕكُمۡ فَٱسۡتَشۡهِدُوا۟ عَلَیۡهِنَّ أَرۡبَعَةࣰ مِّنكُمۡۖ فَإِن شَهِدُوا۟ فَأَمۡسِكُوهُنَّ فِی ٱلۡبُیُوتِ حَتَّىٰ یَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ یَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِیلࣰا ۝١٥", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "واللاتي يزنين من نسائكم، فاستشهدوا -أيها الولاة والقضاة- عليهن أربعة رجال عدول من المسلمين، فإن شهدوا عليهن بذلك فاحبسوهن في البيوت حتى تنتهي حياتهن بالموت، أو يجعل الله لهن طريقًا للخلاص من ذلك.", "isBasmala": false, "translation_en": "Those of your women who commit lewdness, you must have four witnesses against them, from among you. If they testify, confine them to the homes until death claims them, or God makes a way for them.", "translation_id": "Dan (terhadap) para wanita yang mengerjakan perbuatan keji, hendaklah ada empat orang saksi diantara kamu (yang menyaksikannya). Kemudian apabila mereka telah memberi persaksian, maka kurunglah mereka (wanita-wanita itu) dalam rumah sampai mereka menemui ajalnya, atau sampai Allah memberi jalan lain kepadanya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 16, "text": "وَٱلَّذَانِ یَأۡتِیَـٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُوا۟ عَنۡهُمَاۤۗ إِنَّ ٱللَّهَ كَانَ تَوَّابࣰا رَّحِیمًا ۝١٦", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "واللذان يقعان في فاحشة الزنى، فآذُوهما بالضرب والهجر والتوبيخ، فإن تابا عمَّا وقع منهما وأصلحا بما يقدِّمان من الأعمال الصالحة فاصفحوا عن أذاهما. ويستفاد من هذه الآية والتي قبلها أن الرجال إذا فعلوا الفاحشة يُؤْذَوْن، والنساء يُحْبَسْنَ ويُؤذَيْنَ، فالحبس غايتة الموت، والأذية نهايتها إلى التوبة والصلاح. وكان هذا في صدر الإسلام، ثم نُسخ بما شرع الله ورسوله، وهو الرجم للمحصن والمحصنة، وهما الحران البالغان العاقلان، اللذان جامعا في نكاح صحيح، والجلدُ مائة جلدة، وتغريب عام لغيرهما. إن الله كان توابا على عباده التائبين، رحيمًا بهم.", "isBasmala": false, "translation_en": "If two men among you commit it, punish them both. But if they repent and reform, leave them alone. God is Redeemer, Full of Mercy.", "translation_id": "Dan terhadap dua orang yang melakukan perbuatan keji di antara kamu, maka berilah hukuman kepada keduanya, kemudian jika keduanya bertaubat dan memperbaiki diri, maka biarkanlah mereka. Sesungguhnya Allah Maha Penerima taubat lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 17, "text": "إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِینَ یَعۡمَلُونَ ٱلسُّوۤءَ بِجَهَـٰلَةࣲ ثُمَّ یَتُوبُونَ مِن قَرِیبࣲ فَأُو۟لَـٰۤىِٕكَ یَتُوبُ ٱللَّهُ عَلَیۡهِمۡۗ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا ۝١٧", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "إنَّما يقبل الله التوبة من الذين يرتكبون المعاصي والذنوب بجهل منهم لعاقبتها، وإيجابها لسخط الله -فكل عاص لله مخطئًا أو متعمِّدًا فهو جاهل بهذا الاعتبار، وإن كان عالمًا بالتحريم -ثم يرجعون إلى ربهم بالإنابة والطاعة قبل معاينة الموت، فأولئك يقبل الله توبتهم. وكان الله عليمًا بخلقه، حكيمًا في تدبيره وتقديره.", "isBasmala": false, "translation_en": "Repentance is available from God for those who commit evil out of ignorance, and then repent soon after. These-God will relent towards them. God is Knowing and Wise.", "translation_id": "Sesungguhnya taubat di sisi Allah hanyalah taubat bagi orang-orang yang mengerjakan kejahatan lantaran kejahilan, yang kemudian mereka bertaubat dengan segera, maka mereka itulah yang diterima Allah taubatnya; dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 18, "text": "وَلَیۡسَتِ ٱلتَّوۡبَةُ لِلَّذِینَ یَعۡمَلُونَ ٱلسَّیِّـَٔاتِ حَتَّىٰۤ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّی تُبۡتُ ٱلۡـَٔـٰنَ وَلَا ٱلَّذِینَ یَمُوتُونَ وَهُمۡ كُفَّارٌۚ أُو۟لَـٰۤىِٕكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِیمࣰا ۝١٨", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "وليس قَبول التوبة للذين يُصِرُّون على ارتكاب المعاصي، ولا يرجعون إلى ربهم إلى أن تأتيهم سكرات الموت، فيقول أحدهم: إني تبت الآن، كما لا تُقبل توبة الذين يموتون وهم جاحدون، منكرون لوحدانية الله ورسالة رسوله محمد صلى الله عليه وسلم. أولئك المصرُّون على المعاصي إلى أن ماتوا، والجاحدون الذين يموتون وهم كفار، أعتدنا لهم عذابًا موجعًا.", "isBasmala": false, "translation_en": "But repentance is not available for those who commit evils, until when death approaches one of them, he says, \"Now I repent,\" nor for those who die as disbelievers. These-We have prepared for them a painful torment.", "translation_id": "Dan tidaklah taubat itu diterima Allah dari orang-orang yang mengerjakan kejahatan (yang) hingga apabila datang ajal kepada seseorang di antara mereka, (barulah) ia mengatakan: \"Sesungguhnya saya bertaubat sekarang\". Dan tidak (pula diterima taubat) orang-orang yang mati sedang mereka di dalam kekafiran. Bagi orang-orang itu telah Kami sediakan siksa yang pedih.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 19, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا یَحِلُّ لَكُمۡ أَن تَرِثُوا۟ ٱلنِّسَاۤءَ كَرۡهࣰاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُوا۟ بِبَعۡضِ مَاۤ ءَاتَیۡتُمُوهُنَّ إِلَّاۤ أَن یَأۡتِینَ بِفَـٰحِشَةࣲ مُّبَیِّنَةࣲۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰۤ أَن تَكۡرَهُوا۟ شَیۡـࣰٔا وَیَجۡعَلَ ٱللَّهُ فِیهِ خَیۡرࣰا كَثِیرࣰا ۝١٩", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "يا أيها الذين آمنوا لا يجوز لكم أن تجعلوا نساء آبائكم من جملة تَرِكتهم، تتصرفون فيهن بالزواج منهن، أو المنع لهن، أو تزويجهن للآخرين، وهن كارهات لذلك كله، ولا يجوز لكم أن تضارُّوا أزواجكم وأنتم كارهون لهن؛ ليتنازلن عن بعض ما آتيتموهن من مهر ونحوه، إلا أن يرتكبن أمرا فاحشا كالزنى، فلكم حينئذ إمساكهن حتى تأخذوا ما أعطيتموهن. ولتكن مصاحبتكم لنسائكم مبنية على التكريم والمحبة، وأداء ما لهن من حقوق. فإن كرهتموهن لسبب من الأسباب الدنيوية فاصبروا؛ فعسى أن تكرهوا أمرًا من الأمور ويكون فيه خير كثير.", "isBasmala": false, "translation_en": "O you who believe! It is not permitted for you to inherit women against their will. And do not coerce them in order to take away some of what you had given them, unless they commit a proven adultery. And live with them in kindness. If you dislike them, it may be that you dislike something in which God has placed much good.", "translation_id": "Hai orang-orang yang beriman, tidak halal bagi kamu mempusakai wanita dengan jalan paksa dan janganlah kamu menyusahkan mereka karena hendak mengambil kembali sebagian dari apa yang telah kamu berikan kepadanya, terkecuali bila mereka melakukan pekerjaan keji yang nyata. Dan bergaullah dengan mereka secara patut. Kemudian bila kamu tidak menyukai mereka, (maka bersabarlah) karena mungkin kamu tidak menyukai sesuatu, padahal Allah menjadikan padanya kebaikan yang banyak.", "manzil": 1, "manzil_display": ""}], "81": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 20, "text": "وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجࣲ مَّكَانَ زَوۡجࣲ وَءَاتَیۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارࣰا فَلَا تَأۡخُذُوا۟ مِنۡهُ شَیۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَـٰنࣰا وَإِثۡمࣰا مُّبِینࣰا ۝٢٠", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "وإن أردتم استبدال زوجة مكان أخرى، وكنتم قد أعطيتم مَن تريدون طلاقها مالا كثيرًا مهرًا لها، فلا يحل لكم أن تأخذوا منه شيئًا، أتأخذونه كذبًا وافتراءً واضحًا؟", "isBasmala": false, "translation_en": "If you wish to replace one wife with another, and you have given one of them a fortune, take nothing back from it. Would you take it back fraudulently and sinfully?", "translation_id": "Dan jika kamu ingin mengganti isterimu dengan isteri yang lain, sedang kamu telah memberikan kepada seseorang di antara mereka harta yang banyak, maka janganlah kamu mengambil kembali dari padanya barang sedikitpun. Apakah kamu akan mengambilnya kembali dengan jalan tuduhan yang dusta dan dengan (menanggung) dosa yang nyata?", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 21, "text": "وَكَیۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضࣲ وَأَخَذۡنَ مِنكُم مِّیثَـٰقًا غَلِیظࣰا ۝٢١", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "وكيف يحلُّ لكم أن تأخذوا ما أعطيتموهن من مهر، وقد استمتع كل منكما بالآخر بالجماع، وأخَذْنَ منكم ميثاقًا غليظًا من إمساكهن بمعروف أو تسريحهن بإحسان؟", "isBasmala": false, "translation_en": "And how can you take it back, when you have been intimate with one another, and they have received from you a solid commitment?", "translation_id": "Bagaimana kamu akan mengambilnya kembali, padahal sebagian kamu telah bergaul (bercampur) dengan yang lain sebagai suami-isteri. Dan mereka (isteri-isterimu) telah mengambil dari kamu perjanjian yang kuat.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 22, "text": "وَلَا تَنكِحُوا۟ مَا نَكَحَ ءَابَاۤؤُكُم مِّنَ ٱلنِّسَاۤءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَـٰحِشَةࣰ وَمَقۡتࣰا وَسَاۤءَ سَبِیلًا ۝٢٢", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "ولا تتزوجوا مَن تزوجه آباؤكم من النساء إلا ما قد سلف منكم ومضى في الجاهلية فلا مؤاخذة فيه. إن زواج الأبناء من زوجات آبائهم أمر قبيح يفحش ويعظم قبحه، وبغيض يمقت الله فاعله، وبئس طريقًا ومنهجًا ما كنتم تفعلونه في جاهليتكم.", "isBasmala": false, "translation_en": "Do not marry women whom your fathers married, except what is already past. That is improper, indecent, and a bad custom.", "translation_id": "Dan janganlah kamu kawini wanita-wanita yang telah dikawini oleh ayahmu, terkecuali pada masa yang telah lampau. Sesungguhnya perbuatan itu amat keji dan dibenci Allah dan seburuk-buruk jalan (yang ditempuh).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 23, "text": "حُرِّمَتۡ عَلَیۡكُمۡ أُمَّهَـٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَ ٰتُكُمۡ وَعَمَّـٰتُكُمۡ وَخَـٰلَـٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَـٰتُكُمُ ٱلَّـٰتِیۤ أَرۡضَعۡنَكُمۡ وَأَخَوَ ٰتُكُم مِّنَ ٱلرَّضَـٰعَةِ وَأُمَّهَـٰتُ نِسَاۤىِٕكُمۡ وَرَبَـٰۤىِٕبُكُمُ ٱلَّـٰتِی فِی حُجُورِكُم مِّن نِّسَاۤىِٕكُمُ ٱلَّـٰتِی دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُوا۟ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَیۡكُمۡ وَحَلَـٰۤىِٕلُ أَبۡنَاۤىِٕكُمُ ٱلَّذِینَ مِنۡ أَصۡلَـٰبِكُمۡ وَأَن تَجۡمَعُوا۟ بَیۡنَ ٱلۡأُخۡتَیۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِیمࣰا ۝٢٣", "juz": 4, "hizb": "(*¾ ح 8*)", "tafsir": "حرَّم الله عليكم نكاح أمهاتكم، ويدخل في ذلك الجدَّات مِن جهة الأب أو الأم، وبناتكم: ويشمل بنات الأولاد وإن نزلن، وأخواتكم الشقيقات أو لأب أو لأم، وعماتكم: أخوات آبائكم وأجدادكم، وخالاتكم: أخوات أمهاتكم وجداتكم، وبنات الأخ، وبنات الأخت: ويدخل في ذلك أولادهن، وأمهاتكم اللاتي أرضعنكم، وأخواتكم من الرضاعة -وقد حرَّم رسول الله صلى الله عليه وسلم من الرضاع ما يحرم من النسب- وأمهات نسائكم، سواء دخلتم بنسائكم، أم لم تدخلوا بهن، وبنات نسائكم من غيركم اللاتي يتربَّيْنَ غالبًا في بيوتكم وتحت رعايتكم، وهن مُحرَّمَات فإن لم يكنَّ في حجوركم، ولكن بشرط الدخول بأمهاتهن، فإن لم تكونوا دخلتم بأمهاتهن وطلقتموهن أو متْنَ قبل الدخول فلا جناح عليكم أن تنكحوهن، كما حرَّم الله عليكم أن تنكحوا زوجات أبنائكم الذين من أصلابكم، ومن أُلحق بهم مِن أبنائكم من الرضاع، وهذا التحريم يكون بالعقد عليها، دخل الابن بها أم لم يدخل، وحرَّم عليكم كذلك الجمع في وقت واحد بين الأختين بنسب أو رضاع إلا ما قد سلف ومضى منكم في الجاهلية. ولا يجوز كذلك الجمع بين المرأة وعمتها أو خالتها كما جاء في السنة. إن الله كان غفورًا للمذنبين إذا تابوا، رحيمًا بهم، فلا يكلفهم ما لا يطيقون.", "isBasmala": false, "translation_en": "Forbidden for you are your mothers, your daughters, your sisters, your paternal aunts, your maternal aunts, your brother's daughters, your sister's daughters, your foster-mothers who nursed you, your sisters through nursing, your wives' mothers, and your stepdaughters in your guardianship-born of wives you have gone into-but if you have not gone into them, there is no blame on you. And the wives of your genetic sons, and marrying two sisters simultaneously. Except what is past. God is Oft-Forgiving, Most Merciful.", "translation_id": "Diharamkan atas kamu (mengawini) ibu-ibumu; anak-anakmu yang perempuan; saudara-saudaramu yang perempuan, saudara-saudara bapakmu yang perempuan; saudara-saudara ibumu yang perempuan; anak-anak perempuan dari saudara-saudaramu yang laki-laki; anak-anak perempuan dari saudara-saudaramu yang perempuan; ibu-ibumu yang menyusui kamu; saudara perempuan sepersusuan; ibu-ibu isterimu (mertua); anak-anak isterimu yang dalam pemeliharaanmu dari isteri yang telah kamu campuri, tetapi jika kamu belum campur dengan isterimu itu (dan sudah kamu ceraikan), maka tidak berdosa kamu mengawininya; (dan diharamkan bagimu) isteri-isteri anak kandungmu (menantu); dan menghimpunkan (dalam perkawinan) dua perempuan yang bersaudara, kecuali yang telah terjadi pada masa lampau; sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}], "82": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 24, "text": "۞ وَٱلۡمُحۡصَنَـٰتُ مِنَ ٱلنِّسَاۤءِ إِلَّا مَا مَلَكَتۡ أَیۡمَـٰنُكُمۡۖ كِتَـٰبَ ٱللَّهِ عَلَیۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَاۤءَ ذَ ٰلِكُمۡ أَن تَبۡتَغُوا۟ بِأَمۡوَ ٰلِكُم مُّحۡصِنِینَ غَیۡرَ مُسَـٰفِحِینَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِیضَةࣰۚ وَلَا جُنَاحَ عَلَیۡكُمۡ فِیمَا تَرَ ٰضَیۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِیضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا ۝٢٤", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "ويحرم عليكم نكاح المتزوجات من النساء، إلا مَنْ سَبَيْتُم منهن في الجهاد، فإنه يحل لكم نكاحهن، بعد استبراء أرحامهن بحيضة، كتب الله عليكم تحريم نكاح هؤلاء، وأجاز لكم نكاح مَن سواهن، ممَّا أحله الله لكم أن تطلبوا بأموالكم العفة عن اقتراف الحرام. فما استمتعتم به منهن بالنكاح الصحيح، فأعطوهن مهورهن، التي فرض الله لهن عليكم، ولا إثم عليكم فيما تمَّ التراضي به بينكم، من الزيادة أو النقصان في المهر، بعد ثبوت الفريضة. إن الله تعالى كان عليمًا بأمور عباده، حكيما في أحكامه وتدبيره.", "isBasmala": false, "translation_en": "And all married women, except those you rightfully possess. This is God's decree, binding upon you. Permitted for you are those that lie outside these limits, provided you seek them in legal marriage, with gifts from your property, seeking wedlock, not prostitution. If you wish to enjoy them, then give them their dowry-a legal obligation. You commit no error by agreeing to any change to the dowry. God is All-Knowing, Most Wise.", "translation_id": "dan (diharamkan juga kamu mengawini) wanita yang bersuami, kecuali budak-budak yang kamu miliki (Allah telah menetapkan hukum itu) sebagai ketetapan-Nya atas kamu. Dan dihalalkan bagi kamu selain yang demikian (yaitu) mencari isteri-isteri dengan hartamu untuk dikawini bukan untuk berzina. Maka isteri-isteri yang telah kamu nikmati (campuri) di antara mereka, berikanlah kepada mereka maharnya (dengan sempurna), sebagai suatu kewajiban; dan tiadalah mengapa bagi kamu terhadap sesuatu yang kamu telah saling merelakannya, sesudah menentukan mahar itu. Sesungguhnya Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 25, "text": "وَمَن لَّمۡ یَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن یَنكِحَ ٱلۡمُحۡصَنَـٰتِ ٱلۡمُؤۡمِنَـٰتِ فَمِن مَّا مَلَكَتۡ أَیۡمَـٰنُكُم مِّن فَتَیَـٰتِكُمُ ٱلۡمُؤۡمِنَـٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِیمَـٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضࣲۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَـٰتٍ غَیۡرَ مُسَـٰفِحَـٰتࣲ وَلَا مُتَّخِذَ ٰتِ أَخۡدَانࣲۚ فَإِذَاۤ أُحۡصِنَّ فَإِنۡ أَتَیۡنَ بِفَـٰحِشَةࣲ فَعَلَیۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَـٰتِ مِنَ ٱلۡعَذَابِۚ ذَ ٰلِكَ لِمَنۡ خَشِیَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُوا۟ خَیۡرࣱ لَّكُمۡۗ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٢٥", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "ومن لا قدرة له على مهور الحرائر المؤمنات، فله أن ينكح غيرهن، من فتياتكم المؤمنات المملوكات. والله تعالى هو العليم بحقيقة إيمانكم، بعضكم من بعض، فتزوجوهن بموافقة أهلهن، وأعطوهن مهورهن على ما تراضيتم به عن طيب نفس منكم، متعففات عن الحرام، غير مجاهرات بالزنى، ولا مسرات به باتخاذ أخلاء، فإذا تزوجن وأتين بفاحشة الزنى فعليهن من الحدِّ نصف ما على الحرائر. ذلك الذي أبيح مِن نكاح الإماء بالصفة المتقدمة إنما أبيح لمن خاف على نفسه الوقوع في الزنى، وشق عليه الصبر عن الجماع، والصبر عن نكاح الإماء مع العفة أولى وأفضل. والله تعالى غفور لكم، رحيم بكم إذ أذن لكم في نكاحهن عند العجز عن نكاح الحرائر.", "isBasmala": false, "translation_en": "If any of you lack the means to marry free believing women, he may marry one of the believing maids under your control. God is well aware of your faith. You are from one another. Marry them with the permission of their guardians, and give them their recompense fairly-to be protected-neither committing adultery, nor taking secret lovers. When they are married, if they commit adultery, their punishment shall be half that of free women. That is for those among you who fear falling into decadence. But to practice self-restraint is better for you. God is Most Forgiving, Most Merciful.", "translation_id": "Dan barangsiapa diantara kamu (orang merdeka) yang tidak cukup perbelanjaannya untuk mengawini wanita merdeka lagi beriman, ia boleh mengawini wanita yang beriman, dari budak-budak yang kamu miliki. Allah mengetahui keimananmu; sebahagian kamu adalah dari sebahagian yang lain, karena itu kawinilah mereka dengan seizin tuan mereka, dan berilah maskawin mereka menurut yang patut, sedang merekapun wanita-wanita yang memelihara diri, bukan pezina dan bukan (pula) wanita yang mengambil laki-laki lain sebagai piaraannya; dan apabila mereka telah menjaga diri dengan kawin, kemudian mereka melakukan perbuatan yang keji (zina), maka atas mereka separo hukuman dari hukuman wanita-wanita merdeka yang bersuami. (Kebolehan mengawini budak) itu, adalah bagi orang-orang yang takut kepada kemasyakatan menjaga diri (dari perbuatan zina) di antara kamu, dan kesabaran itu lebih baik bagimu. Dan Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 26, "text": "یُرِیدُ ٱللَّهُ لِیُبَیِّنَ لَكُمۡ وَیَهۡدِیَكُمۡ سُنَنَ ٱلَّذِینَ مِن قَبۡلِكُمۡ وَیَتُوبَ عَلَیۡكُمۡۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ ۝٢٦", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "يريد الله تعالى بهذه التشريعات، أن يوضح لكم معالم دينه القويم، وشرعه الحكيم، ويدلكم على طرق الأنبياء والصالحين من قبلكم في الحلال والحرام، ويتوب عليكم بالرجوع بكم إلى الطاعات، وهو سبحانه عليم بما يصلح شأن عباده، حكيم فيما شرعه لكم.", "isBasmala": false, "translation_en": "God intends to make things clear to you, and to guide you in the ways of those before you, and to redeem you. God is Most Knowing, Most Wise.", "translation_id": "Allah hendak menerangkan (hukum syari'at-Nya) kepadamu, dan menunjukimu kepada jalan-jalan orang yang sebelum kamu (para nabi dan shalihin) dan (hendak) menerima taubatmu. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}], "83": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 27, "text": "وَٱللَّهُ یُرِیدُ أَن یَتُوبَ عَلَیۡكُمۡ وَیُرِیدُ ٱلَّذِینَ یَتَّبِعُونَ ٱلشَّهَوَ ٰتِ أَن تَمِیلُوا۟ مَیۡلًا عَظِیمࣰا ۝٢٧", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "والله يريد أن يتوب عليكم، ويتجاوز عن خطاياكم، ويريد الذين ينقادون لشهواتهم وملذاتهم أن تنحرفوا عن الدين انحرافًا كبيرًا.", "isBasmala": false, "translation_en": "God intends to redeem you, but those who follow their desires want you to turn away utterly.", "translation_id": "Dan Allah hendak menerima taubatmu, sedang orang-orang yang mengikuti hawa nafsunya bermaksud supaya kamu berpaling sejauh-jauhnya (dari kebenaran).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 28, "text": "یُرِیدُ ٱللَّهُ أَن یُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَـٰنُ ضَعِیفࣰا ۝٢٨", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "يريد الله تعالى بما شرعه لكم التيسير، وعدم التشديد عليكم؛ لأنكم خلقتم ضعفاء.", "isBasmala": false, "translation_en": "God intends to lighten your burden, for the human being was created weak.", "translation_id": "Allah hendak memberikan keringanan kepadamu, dan manusia dijadikan bersifat lemah.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 29, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَأۡكُلُوۤا۟ أَمۡوَ ٰلَكُم بَیۡنَكُم بِٱلۡبَـٰطِلِ إِلَّاۤ أَن تَكُونَ تِجَـٰرَةً عَن تَرَاضࣲ مِّنكُمۡۚ وَلَا تَقۡتُلُوۤا۟ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِیمࣰا ۝٢٩", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا يحل لكم أن يأكل بعضكم مال بعض بغير حق، إلا أن يكون وَفْقَ الشرع والكسب الحلال عن تراض منكم، ولا يقتل بعضكم بعضًا فتهلكوا أنفسكم بارتكاب محارم الله ومعاصيه. إن الله كان بكم رحيمًا في كل ما أمركم به، ونهاكم عنه.", "isBasmala": false, "translation_en": "O you who believe! Do not consume each other's wealth illicitly, but trade by mutual consent. And do not kill yourselves, for God is Merciful towards you.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu saling memakan harta sesamamu dengan jalan yang batil, kecuali dengan jalan perniagaan yang berlaku dengan suka sama-suka di antara kamu. Dan janganlah kamu membunuh dirimu; sesungguhnya Allah adalah Maha Penyayang kepadamu.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 30, "text": "وَمَن یَفۡعَلۡ ذَ ٰلِكَ عُدۡوَ ٰنࣰا وَظُلۡمࣰا فَسَوۡفَ نُصۡلِیهِ نَارࣰاۚ وَكَانَ ذَ ٰلِكَ عَلَى ٱللَّهِ یَسِیرًا ۝٣٠", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "ومن يرتكب ما نهى الله عنه من أخذ المال الحرام كالسرقة والغصب والغش معتديًا متجاوزًا حد الشرع، فسوف يدخله الله نارًا يقاسي حرَّها، وكان ذلك على الله يسيرًا.", "isBasmala": false, "translation_en": "Whoever does that, out of hostility and wrongdoing, We will cast him into a Fire. And that would be easy for God.", "translation_id": "Dan barangsiapa berbuat demikian dengan melanggar hak dan aniaya, maka Kami kelak akan memasukkannya ke dalam neraka. Yang demikian itu adalah mudah bagi Allah.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 31, "text": "إِن تَجۡتَنِبُوا۟ كَبَاۤىِٕرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلࣰا كَرِیمࣰا ۝٣١", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "إن تبتعدوا -أيها المؤمنون- عن كبائر الذنوب كالإشراك بالله وعقوق الوالدين وقَتْلِ النفس بغير الحق وغير ذلك، نكفِّر عنكم ما دونها من الصغائر، وندخلكم مدخلا كريمًا، وهو الجنَّة.", "isBasmala": false, "translation_en": "If you avoid the worst of what you are forbidden, We will remit your sins, and admit you by a Gate of Honor.", "translation_id": "Jika kamu menjauhi dosa-dosa besar di antara dosa-dosa yang dilarang kamu mengerjakannya, niscaya Kami hapus kesalahan-kesalahanmu (dosa-dosamu yang kecil) dan Kami masukkan kamu ke tempat yang mulia (surga).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 32, "text": "وَلَا تَتَمَنَّوۡا۟ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضࣲۚ لِّلرِّجَالِ نَصِیبࣱ مِّمَّا ٱكۡتَسَبُوا۟ۖ وَلِلنِّسَاۤءِ نَصِیبࣱ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُوا۟ ٱللَّهَ مِن فَضۡلِهِۦۤۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَیۡءٍ عَلِیمࣰا ۝٣٢", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "ولا تتمنوا ما فضَّل الله به بعضكم على بعض، في المواهب والأرزاق وغير ذلك، فقد جعل الله للرجال نصيبًا مقدَّرًا من الجزاء بحسب عملهم، وجعل للنساء نصيبًا مما عملن، واسألوا الله الكريم الوهاب يُعْطِكم من فضله بدلا من التمني. إن الله كان بكل شيء عليمًا، وهو أعلم بما يصلح عباده فيما قسمه لهم من خير.", "isBasmala": false, "translation_en": "Do not covet what God has given to some of you in preference to others. For men is a share of what they have earned, and for women is a share of what they have earned. And ask God of his bounty. God has knowledge of everything.", "translation_id": "Dan janganlah kamu iri hati terhadap apa yang dikaruniakan Allah kepada sebahagian kamu lebih banyak dari sebahagian yang lain. (Karena) bagi orang laki-laki ada bahagian dari pada apa yang mereka usahakan, dan bagi para wanita (pun) ada bahagian dari apa yang mereka usahakan, dan mohonlah kepada Allah sebagian dari karunia-Nya. Sesungguhnya Allah Maha Mengetahui segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 33, "text": "وَلِكُلࣲّ جَعَلۡنَا مَوَ ٰلِیَ مِمَّا تَرَكَ ٱلۡوَ ٰلِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِینَ عَقَدَتۡ أَیۡمَـٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِیبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدًا ۝٣٣", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "ولكل واحد منكم جعلنا ورثة يرثون مما ترك الوالدان والأقربون، والذين تحالفتم معهم بالأيمان المؤكدة على النصرة وإعطائهم شيئًا من الميراث فأعطوهم ما قُدِّر لهم. والميراث بالتحالف كان في أول الإسلام، ثم رُفع حكمه بنزول آيات المواريث. إن الله كان مُطَّلِعًا على كل شيء من أعمالكم، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "To everyone We have assigned beneficiaries in what is left by parents and relatives. Those with whom you have made an agreement, give them their share. God is Witness over all things.", "translation_id": "Bagi tiap-tiap harta peninggalan dari harta yang ditinggalkan ibu bapak dan karib kerabat, Kami jadikan pewaris-pewarisnya. Dan (jika ada) orang-orang yang kamu telah bersumpah setia dengan mereka, maka berilah kepada mereka bahagiannya. Sesungguhnya Allah menyaksikan segala sesuatu.", "manzil": 1, "manzil_display": ""}], "84": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 34, "text": "ٱلرِّجَالُ قَوَّ ٰمُونَ عَلَى ٱلنِّسَاۤءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲ وَبِمَاۤ أَنفَقُوا۟ مِنۡ أَمۡوَ ٰلِهِمۡۚ فَٱلصَّـٰلِحَـٰتُ قَـٰنِتَـٰتٌ حَـٰفِظَـٰتࣱ لِّلۡغَیۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّـٰتِی تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِی ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُوا۟ عَلَیۡهِنَّ سَبِیلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِیࣰّا كَبِیرࣰا ۝٣٤", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "الرجال قوَّامون على توجيه النساء ورعايتهن، بما خصهم الله به من خصائص القِوامَة والتفضيل، وبما أعطوهن من المهور والنفقات. فالصالحات المستقيمات على شرع الله منهن، مطيعات لله تعالى ولأزواجهن، حافظات لكل ما غاب عن علم أزواجهن بما اؤتمنَّ عليه بحفظ الله وتوفيقه، واللاتي تخشون منهن ترفُّعهن عن طاعتكم، فانصحوهن بالكلمة الطيبة، فإن لم تثمر معهن الكلمة الطيبة، فاهجروهن في الفراش، ولا تقربوهن، فإن لم يؤثر فعل الهِجْران فيهن، فاضربوهن ضربًا لا ضرر فيه، فإن أطعنكم فاحذروا ظلمهن، فإن الله العليَّ الكبير وليُّهن، وهو منتقم ممَّن ظلمهنَّ وبغى عليهن.", "isBasmala": false, "translation_en": "Men are the protectors and maintainers of women, as God has given some of them an advantage over others, and because they spend out of their wealth. The good women are obedient, guarding what God would have them guard. As for those from whom you fear disloyalty, admonish them, and abandon them in their beds, then strike them. But if they obey you, seek no way against them. God is Sublime, Great.", "translation_id": "Kaum laki-laki itu adalah pemimpin bagi kaum wanita, oleh karena Allah telah melebihkan sebahagian mereka (laki-laki) atas sebahagian yang lain (wanita), dan karena mereka (laki-laki) telah menafkahkan sebagian dari harta mereka. Sebab itu maka wanita yang saleh, ialah yang taat kepada Allah lagi memelihara diri ketika suaminya tidak ada, oleh karena Allah telah memelihara (mereka). Wanita-wanita yang kamu khawatirkan nusyuznya, maka nasehatilah mereka dan pisahkanlah mereka di tempat tidur mereka, dan pukullah mereka. Kemudian jika mereka mentaatimu, maka janganlah kamu mencari-cari jalan untuk menyusahkannya. Sesungguhnya Allah Maha Tinggi lagi Maha Besar.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 35, "text": "وَإِنۡ خِفۡتُمۡ شِقَاقَ بَیۡنِهِمَا فَٱبۡعَثُوا۟ حَكَمࣰا مِّنۡ أَهۡلِهِۦ وَحَكَمࣰا مِّنۡ أَهۡلِهَاۤ إِن یُرِیدَاۤ إِصۡلَـٰحࣰا یُوَفِّقِ ٱللَّهُ بَیۡنَهُمَاۤۗ إِنَّ ٱللَّهَ كَانَ عَلِیمًا خَبِیرࣰا ۝٣٥", "juz": 5, "hizb": "(* ح 9*)", "tafsir": "وإن علمتم -يا أولياء الزوجين- شقاقًا بينهما يؤدي إلى الفراق، فأرسلوا إليهما حكمًا عدلا من أهل الزوج، وحكمًا عدلا من أهل الزوجة؛ لينظرا ويحكما بما فيه المصلحة لهما، وبسبب رغبة الحكمين في الإصلاح، واستعمالهما الأسلوب الطيب يوفق الله بين الزوجين. إن الله تعالى عليم، لا يخفى عليه شيء من أمر عباده، خبير بما تنطوي عليه نفوسهم.", "isBasmala": false, "translation_en": "If you fear a breach between the two, appoint an arbiter from his family and an arbiter from her family. If they wish to reconcile, God will bring them together. God is Knowledgeable, Expert.", "translation_id": "Dan jika kamu khawatirkan ada persengketaan antara keduanya, maka kirimlah seorang hakam dari keluarga laki-laki dan seorang hakam dari keluarga perempuan. Jika kedua orang hakam itu bermaksud mengadakan perbaikan, niscaya Allah memberi taufik kepada suami-isteri itu. Sesungguhnya Allah Maha Mengetahui lagi Maha Mengenal.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 36, "text": "۞ وَٱعۡبُدُوا۟ ٱللَّهَ وَلَا تُشۡرِكُوا۟ بِهِۦ شَیۡـࣰٔاۖ وَبِٱلۡوَ ٰلِدَیۡنِ إِحۡسَـٰنࣰا وَبِذِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَٱلۡجَارِ ذِی ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِیلِ وَمَا مَلَكَتۡ أَیۡمَـٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا یُحِبُّ مَن كَانَ مُخۡتَالࣰا فَخُورًا ۝٣٦", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "واعبدوا الله وانقادوا له وحده، ولا تجعلوا له شريكًا في الربوبية والعبادة، وأحسنوا إلى الوالدين، وأدُّوا حقوقهما، وحقوق الأقربين، واليتامى والمحتاجين، والجار القريب منكم والبعيد، والرفيق في السفر وفي الحضر، والمسافر المحتاج، والمماليك من فتيانكم وفتياتكم. إن الله تعالى لا يحب المتكبرين من عباده، المفتخرين على الناس.", "isBasmala": false, "translation_en": "Worship God, and ascribe no partners to Him, and be good to the parents, and the relatives, and the orphans, and the poor, and the neighbor next door, and the distant neighbor, and the close associate, and the traveler, and your servants. God does not love the arrogant showoff.", "translation_id": "Sembahlah Allah dan janganlah kamu mempersekutukan-Nya dengan sesuatupun. Dan berbuat baiklah kepada dua orang ibu-bapa, karib-kerabat, anak-anak yatim, orang-orang miskin, tetangga yang dekat dan tetangga yang jauh, dan teman sejawat, ibnu sabil dan hamba sahayamu. Sesungguhnya Allah tidak menyukai orang-orang yang sombong dan membangga-banggakan diri,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 37, "text": "ٱلَّذِینَ یَبۡخَلُونَ وَیَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَیَكۡتُمُونَ مَاۤ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَـٰفِرِینَ عَذَابࣰا مُّهِینࣰا ۝٣٧", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "الذين يمتنعون عن الإنفاق والعطاء مما رزقهم الله، ويأمرون غيرهم بالبخل، ويجحدون نِعَمَ الله عليهم، ويخفون فضله وعطاءه. وأعددنا للجاحدين عذابًا مخزيًا.", "isBasmala": false, "translation_en": "Those who are stingy, and exhort people to stinginess, and conceal what God has given them from His bounty. We have prepared for the disbelievers a disgraceful punishment.", "translation_id": "(yaitu) orang-orang yang kikir, dan menyuruh orang lain berbuat kikir, dan menyembunyikan karunia Allah yang telah diberikan-Nya kepada mereka. Dan Kami telah menyediakan untuk orang-orang kafir siksa yang menghinakan.", "manzil": 1, "manzil_display": ""}], "85": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 38, "text": "وَٱلَّذِینَ یُنفِقُونَ أَمۡوَ ٰلَهُمۡ رِئَاۤءَ ٱلنَّاسِ وَلَا یُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡیَوۡمِ ٱلۡـَٔاخِرِۗ وَمَن یَكُنِ ٱلشَّیۡطَـٰنُ لَهُۥ قَرِینࣰا فَسَاۤءَ قَرِینࣰا ۝٣٨", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "وأعتدنا هذا العذاب كذلك للذين ينفقون أموالهم رياءً وسمعةً، ولا يصدقون بالله اعتقادًا وعملا ولا بيوم القيامة. وهذه الأعمال السيئة مما يدعو إليها الشيطان. ومن يكن الشيطان له ملازمًا فبئس الملازم والقرين.", "isBasmala": false, "translation_en": "And those who spend their money to be seen by people, and believe neither in God nor in the Last Day. Whoever has Satan as a companion-what an evil companion.", "translation_id": "Dan (juga) orang-orang yang menafkahkan harta-harta mereka karena riya kepada manusia, dan orang-orang yang tidak beriman kepada Allah dan kepada hari kemudian. Barangsiapa yang mengambil syaitan itu menjadi temannya, maka syaitan itu adalah teman yang seburuk-buruknya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 39, "text": "وَمَاذَا عَلَیۡهِمۡ لَوۡ ءَامَنُوا۟ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَأَنفَقُوا۟ مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِیمًا ۝٣٩", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "وأيُّ ضرر يلحقهم لو صدَّقوا بالله واليوم الآخر اعتقادًا وعملا وأنفقوا مما أعطاهم الله باحتساب وإخلاص، والله تعالى عليم بهم وبما يعملون، وسيحاسبهم على ذلك.", "isBasmala": false, "translation_en": "What would they have lost, had they believed in God and the Last Day, and gave out of what God has provided for them? God knows them very well.", "translation_id": "Apakah kemudharatannya bagi mereka, kalau mereka beriman kepada Allah dan hari kemudian dan menafkahkan sebahagian rezeki yang telah diberikan Allah kepada mereka? Dan adalah Allah Maha Mengetahui keadaan mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 40, "text": "إِنَّ ٱللَّهَ لَا یَظۡلِمُ مِثۡقَالَ ذَرَّةࣲۖ وَإِن تَكُ حَسَنَةࣰ یُضَـٰعِفۡهَا وَیُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِیمࣰا ۝٤٠", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "إن الله تعالى لا ينقص أحدًا من جزاء عمله مقدار ذرة، وإن تكن زنة الذرة حسنة فإنه سبحانه يزيدها ويكثرها لصاحبها، ويتفضل عليه بالمزيد، فيعطيه من عنده ثوابًا كبيرًا هو الجنة.", "isBasmala": false, "translation_en": "God does not commit an atom's weight of injustice; and if there is a good deed, He doubles it, and gives from His Presence a sublime compensation.", "translation_id": "Sesungguhnya Allah tidak menganiaya seseorang walaupun sebesar zarrah, dan jika ada kebajikan sebesar zarrah, niscaya Allah akan melipat gandakannya dan memberikan dari sisi-Nya pahala yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 41, "text": "فَكَیۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِیدࣲ وَجِئۡنَا بِكَ عَلَىٰ هَـٰۤؤُلَاۤءِ شَهِیدࣰا ۝٤١", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "فكيف يكون حال الناس يوم القيامة، إذا جاء الله من كل أمة برسولها ليشهد عليها بما عملت، وجاء بك -أيها الرسول- لتكون شهيدًا على أمتك أنك بلغتهم رسالة ربِّك.", "isBasmala": false, "translation_en": "Then how will it be, when We bring a witness from every community, and We bring you as a witness against these?", "translation_id": "Maka bagaimanakah (halnya orang kafir nanti), apabila Kami mendatangkan seseorang saksi (rasul) dari tiap-tiap umat dan Kami mendatangkan kamu (Muhammad) sebagai saksi atas mereka itu (sebagai umatmu).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 42, "text": "یَوۡمَىِٕذࣲ یَوَدُّ ٱلَّذِینَ كَفَرُوا۟ وَعَصَوُا۟ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا یَكۡتُمُونَ ٱللَّهَ حَدِیثࣰا ۝٤٢", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "يوم يكون ذلك، يتمنى الذين كفروا بالله تعالى وخالفوا الرسول ولم يطيعوه، لو يجعلهم الله والأرض سواء، فيصيرون ترابًا، حتى لا يبعثوا وهم لا يستطيعون أن يُخفوا عن الله شيئًا مما في أنفسهم، إذ ختم الله على أفواههم، وشَهِدَتْ عليهم جوارحهم بما كانوا يعملون.", "isBasmala": false, "translation_en": "On that Day, those who disbelieved and disobeyed the Messenger will wish that the earth were leveled over them. They will conceal nothing from God.", "translation_id": "Di hari itu orang-orang kafir dan orang-orang yang mendurhakai rasul, ingin supaya mereka disamaratakan dengan tanah, dan mereka tidak dapat menyembunyikan (dari Allah) sesuatu kejadianpun.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 43, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَقۡرَبُوا۟ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَـٰرَىٰ حَتَّىٰ تَعۡلَمُوا۟ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِی سَبِیلٍ حَتَّىٰ تَغۡتَسِلُوا۟ۚ وَإِن كُنتُم مَّرۡضَىٰۤ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَاۤءَ أَحَدࣱ مِّنكُم مِّنَ ٱلۡغَاۤىِٕطِ أَوۡ لَـٰمَسۡتُمُ ٱلنِّسَاۤءَ فَلَمۡ تَجِدُوا۟ مَاۤءࣰ فَتَیَمَّمُوا۟ صَعِیدࣰا طَیِّبࣰا فَٱمۡسَحُوا۟ بِوُجُوهِكُمۡ وَأَیۡدِیكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا ۝٤٣", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "يا أيها الذين صدَّقوا بالله ورسوله وعملوا بشرعه، لا تقربوا الصلاة ولا تقوموا إليها حال السكر حتى تميزوا وتعلموا ما تقولون، وقد كان هذا قبل التحريم القاطع للخمر في كل حال، ولا تقربوا الصلاة في حال الجنابة، ولا تقربوا مواضعها وهي المساجد، إلا من كان منكم مجتازًا من باب إلى باب، حتى تتطهروا. وإن كنتم في حال مرض لا تقدرون معه على استعمال الماء، أو حال سفر، أو جاء أحد منكم من الغائط، أو جامعتم النساء، فلم تجدوا ماء للطهارة فاقصدوا ترابًا طاهرًا، فامسحوا بوجوهكم وأيديكم منه. إن الله تعالى كان عفوًّا عنكم، غفورًا لكم.", "isBasmala": false, "translation_en": "O you who believe! Do not approach the prayer while you are drunk, so that you know what you say; nor after sexual orgasm-unless you are travelling-until you have bathed. If you are sick, or traveling, or one of you comes from the toilet, or you have had intercourse with women, and cannot find water, find clean sand and wipe your faces and your hands with it. God is Pardoning and Forgiving.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu shalat, sedang kamu dalam keadaan mabuk, sehingga kamu mengerti apa yang kamu ucapkan, (jangan pula hampiri mesjid) sedang kamu dalam keadaan junub, terkecuali sekedar berlalu saja, hingga kamu mandi. Dan jika kamu sakit atau sedang dalam musafir atau datang dari tempat buang air atau kamu telah menyentuh perempuan, kemudian kamu tidak mendapat air, maka bertayamumlah kamu dengan tanah yang baik (suci); sapulah mukamu dan tanganmu. Sesungguhnya Allah Maha Pemaaf lagi Maha Pengampun.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 44, "text": "أَلَمۡ تَرَ إِلَى ٱلَّذِینَ أُوتُوا۟ نَصِیبࣰا مِّنَ ٱلۡكِتَـٰبِ یَشۡتَرُونَ ٱلضَّلَـٰلَةَ وَیُرِیدُونَ أَن تَضِلُّوا۟ ٱلسَّبِیلَ ۝٤٤", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "ألم تعلم -أيها الرسول- أمر اليهود الذين أُعطوا حظًّا من العلم مما جاءهم من التوراة، يستبدلون الضلالة بالهدى، ويتركون ما لديهم من الحجج والبراهين، الدالة على صدق رسالة الرسول محمد صلى الله عليه وسلم، ويتمنون لكم -أيها المؤمنون المهتدون- أن تنحرفوا عن الطريق المستقيم؛ لتكونوا ضالين مثلهم.", "isBasmala": false, "translation_en": "Have you not considered those who were given a share of the Book? They buy error, and wish you would lose the way.", "translation_id": "Apakah kamu tidak melihat orang-orang yang telah diberi bahagian dari Al Kitab (Taurat)? Mereka membeli (memilih) kesesatan (dengan petunjuk) dan mereka bermaksud supaya kamu tersesat (menyimpang) dari jalan (yang benar).", "manzil": 1, "manzil_display": ""}], "86": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 45, "text": "وَٱللَّهُ أَعۡلَمُ بِأَعۡدَاۤىِٕكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِیࣰّا وَكَفَىٰ بِٱللَّهِ نَصِیرࣰا ۝٤٥", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "والله سبحانه وتعالى أعلم منكم -أيها المؤمنون- بعداوة هؤلاء اليهود لكم، وكفى بالله وليًّا يتولاكم، وكفى به نصيرًا ينصركم على أعدائكم.", "isBasmala": false, "translation_en": "But God knows your enemies best. God is sufficient as a Protector, and God is sufficient as a Supporter.", "translation_id": "Dan Allah lebih mengetahui (dari pada kamu) tentang musuh-musuhmu. Dan cukuplah Allah menjadi Pelindung (bagimu). Dan cukuplah Allah menjadi Penolong (bagimu).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 46, "text": "مِّنَ ٱلَّذِینَ هَادُوا۟ یُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَیَقُولُونَ سَمِعۡنَا وَعَصَیۡنَا وَٱسۡمَعۡ غَیۡرَ مُسۡمَعࣲ وَرَ ٰعِنَا لَیَّۢا بِأَلۡسِنَتِهِمۡ وَطَعۡنࣰا فِی ٱلدِّینِۚ وَلَوۡ أَنَّهُمۡ قَالُوا۟ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا لَكَانَ خَیۡرࣰا لَّهُمۡ وَأَقۡوَمَ وَلَـٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا یُؤۡمِنُونَ إِلَّا قَلِیلࣰا ۝٤٦", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "من اليهود فريق دأبوا على تبديل كلام الله وتغييره عمَّا هو عليه افتراء على الله، ويقولون للرسول صلى الله عليه وسلم: سمعنا قولك وعصينا أمرك واسمع منَّا لا سمعت، ويقولون: راعنا سمعك أي: افهم عنا وأفهمنا، يلوون ألسنتهم بذلك، وهم يريدون الدعاء عليه بالرعونة حسب لغتهم، والطعن في دين الإسلام. ولو أنهم قالوا: سمعنا وأطعنا، بدل و\"عصينا\"، واسمع دون \"غير مسمع\"، وانظرنا بدل \"راعنا\" لكان ذلك خيرًا لهم عند الله وأعدل قولا ولكن الله طردهم من رحمته؛ بسبب كفرهم وجحودهم نبوة محمد صلى الله عليه وسلم، فلا يصدقون بالحق إلا تصديقًا قليلا لا ينفعهم.", "isBasmala": false, "translation_en": "Among the Jews are some who take words out of context, and say, \"We hear and we disobey\", and \"Hear without listening\", and \"Observe us,\" twisting with their tongues and slandering the religion. Had they said, \"We hear and we obey\", and \"Listen\", and \"Give us your attention,\" it would have been better for them, and more upright. But God has cursed them for their disbelief; they do not believe except a little.", "translation_id": "Yaitu orang-orang Yahudi, mereka mengubah perkataan dari tempat-tempatnya. Mereka berkata: \"Kami mendengar\", tetapi kami tidak mau menurutinya. Dan (mereka mengatakan pula): \"Dengarlah\" sedang kamu sebenarnya tidak mendengar apa-apa. Dan (mereka mengatakan): \"Raa'ina\", dengan memutar-mutar lidahnya dan mencela agama. Sekiranya mereka mengatakan: \"Kami mendengar dan menurut, dan dengarlah, dan perhatikanlah kami\", tentulah itu lebih baik bagi mereka dan lebih tepat, akan tetapi Allah mengutuk mereka, karena kekafiran mereka. Mereka tidak beriman kecuali iman yang sangat tipis.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 47, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ ءَامِنُوا۟ بِمَا نَزَّلۡنَا مُصَدِّقࣰا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهࣰا فَنَرُدَّهَا عَلَىٰۤ أَدۡبَارِهَاۤ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّاۤ أَصۡحَـٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا ۝٤٧", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "يا أهل الكتاب، صدِّقوا واعملوا بما نزَّلنا من القرآن، مصدقًا لما معكم من الكتب من قبل أن نأخذكم بسوء صنيعكم، فنمحو الوجوه ونحولها قِبَلَ الظهور، أو نلعن هؤلاء المفسدين بمسخهم قردة وخنازير، كما لعنَّا اليهود مِن أصحاب السبت، الذين نُهوا عن الصيد فيه فلم ينتهوا، فغضب الله عليهم، وطردهم من رحمته، وكان أمر الله نافذًا في كل حال.", "isBasmala": false, "translation_en": "O you who were given the Book! Believe in what We sent down, confirming what you have, before We obliterate faces and turn them inside out, or curse them as We cursed the Sabbath-breakers. The command of God is always done.", "translation_id": "Hai orang-orang yang telah diberi Al Kitab, berimanlah kamu kepada apa yang telah Kami turunkan (Al Quran) yang membenarkan Kitab yang ada pada kamu sebelum Kami mengubah muka(mu), lalu Kami putarkan ke belakang atau Kami kutuki mereka sebagaimana Kami telah mengutuki orang-orang (yang berbuat maksiat) pada hari Sabtu. Dan ketetapan Allah pasti berlaku.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 48, "text": "إِنَّ ٱللَّهَ لَا یَغۡفِرُ أَن یُشۡرَكَ بِهِۦ وَیَغۡفِرُ مَا دُونَ ذَ ٰلِكَ لِمَن یَشَاۤءُۚ وَمَن یُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰۤ إِثۡمًا عَظِیمًا ۝٤٨", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "إن الله تعالى لا يغفر ولا يتجاوز عمَّن أشرك به أحدًا من مخلوقاته، أو كفر بأي نوع من أنواع الكفر الأكبر، ويتجاوز ويعفو عمَّا دون الشرك من الذنوب، لمن يشاء من عباده، ومن يشرك بالله غيره فقد اختلق ذنبًا عظيمًا.", "isBasmala": false, "translation_en": "God does not forgive association with Him, but He forgives anything less than that to whomever He wills. Whoever associates anything with God has devised a monstrous sin.", "translation_id": "Sesungguhnya Allah tidak akan mengampuni dosa syirik, dan Dia mengampuni segala dosa yang selain dari (syirik) itu, bagi siapa yang dikehendaki-Nya. Barangsiapa yang mempersekutukan Allah, maka sungguh ia telah berbuat dosa yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 49, "text": "أَلَمۡ تَرَ إِلَى ٱلَّذِینَ یُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ یُزَكِّی مَن یَشَاۤءُ وَلَا یُظۡلَمُونَ فَتِیلًا ۝٤٩", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "ألم تعلم -أيها الرسول- أمر أولئك الذين يُثنون على أنفسهم وأعمالهم، ويصفونها بالطهر والبعد عن السوء؟ بل الله تعالى وحده هو الذي يثني على مَن يشاء مِن عباده، لعلمه بحقيقة أعمالهم، ولا يُنقَصون من أعمالهم شيئًا مقدار الخيط الذي يكون في شق نَواة التمرة.", "isBasmala": false, "translation_en": "Have you not considered those who claim purity for themselves? Rather, God purifies whom He wills, and they will not be wronged a whit.", "translation_id": "Apakah kamu tidak memperhatikan orang yang menganggap dirinya bersih?. Sebenarnya Allah membersihkan siapa yang dikehendaki-Nya dan mereka tidak aniaya sedikitpun.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 50, "text": "ٱنظُرۡ كَیۡفَ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَكَفَىٰ بِهِۦۤ إِثۡمࣰا مُّبِینًا ۝٥٠", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "انظر إليهم -أيها الرسول- متعجبًا من أمرهم، كيف يختلقون على الله الكذب، وهو المنزَّه عن كل ما لا يليق به؟ وكفى بهذا الاختلاق ذنبًا كبيرًا كاشفًا عن فساد معتقدهم.", "isBasmala": false, "translation_en": "See how they devise lies against God. That alone is an outright sin.", "translation_id": "Perhatikanlah, betapakah mereka mengada-adakan dusta terhadap Allah? Dan cukuplah perbuatan itu menjadi dosa yang nyata (bagi mereka).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 51, "text": "أَلَمۡ تَرَ إِلَى ٱلَّذِینَ أُوتُوا۟ نَصِیبࣰا مِّنَ ٱلۡكِتَـٰبِ یُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّـٰغُوتِ وَیَقُولُونَ لِلَّذِینَ كَفَرُوا۟ هَـٰۤؤُلَاۤءِ أَهۡدَىٰ مِنَ ٱلَّذِینَ ءَامَنُوا۟ سَبِیلًا ۝٥١", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "ألم تعلم -أيها الرسول- أمر أولئك اليهود الذين أُعطوا حظًّا من العلم يصدقون بكل ما يُعبد من دون الله من الأصنام وشياطين الإنس والجن تصديقا يحملهم على التحاكم إلى غير شرع الله، ويقولون للذين كفروا بالله تعالى وبرسوله محمد صلى الله عليه وسلم: هؤلاء الكافرون أقْومُ، وأعدلُ طريقًا من أولئك الذين آمنوا؟", "isBasmala": false, "translation_en": "Have you not considered those who were given a share of the Book? They believe in superstition and evil powers, and say of those who disbelieve, \"These are better guided on the way than the believers.\"", "translation_id": "Apakah kamu tidak memperhatikan orang-orang yang diberi bahagian dari Al kitab? Mereka percaya kepada jibt dan thaghut, dan mengatakan kepada orang-orang Kafir (musyrik Mekah), bahwa mereka itu lebih benar jalannya dari orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}], "87": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 52, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَعَنَهُمُ ٱللَّهُۖ وَمَن یَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِیرًا ۝٥٢", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "أولئك الذين كَثُرَ فسادهم وعمَّ ضلالهم، طردهم الله تعالى من رحمته، ومَن يطرده الله من رحمته فلن تجد له من ينصره، ويدفع عنه سوء العذاب.", "isBasmala": false, "translation_en": "Those are they whom God has cursed. Whomever God curses, you will find no savior for him.", "translation_id": "Mereka itulah orang yang dikutuki Allah. Barangsiapa yang dikutuki Allah, niscaya kamu sekali-kali tidak akan memperoleh penolong baginya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 53, "text": "أَمۡ لَهُمۡ نَصِیبࣱ مِّنَ ٱلۡمُلۡكِ فَإِذࣰا لَّا یُؤۡتُونَ ٱلنَّاسَ نَقِیرًا ۝٥٣", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "بل ألهم حظ من الملك، ولو أوتوه لما أعطوا أحدًا منه شيئًا، ولو كان مقدار النقرة التي تكون في ظهر النَّواة؟", "isBasmala": false, "translation_en": "Or do they own a share of the kingdom? Then they would not give people a speck.", "translation_id": "Ataukah ada bagi mereka bahagian dari kerajaan (kekuasaan)? Kendatipun ada, mereka tidak akan memberikan sedikitpun (kebajikan) kepada manusia.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 54, "text": "أَمۡ یَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَاۤ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَیۡنَاۤ ءَالَ إِبۡرَ ٰهِیمَ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَءَاتَیۡنَـٰهُم مُّلۡكًا عَظِیمࣰا ۝٥٤", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "بل أيحسدون محمدًا صلى الله عليه وسلم على ما أعطاه الله من نعمة النبوة والرسالة، ويحسدون أصحابه على نعمة التوفيق إلى الإيمان، والتصديق بالرسالة، واتباع الرسول، والتمكين في الأرض، ويتمنون زوال هذا الفضل عنهم؟ فقد أعطينا ذرية إبراهيم عليه السلام -من قَبْلُ- الكتب، التي أنزلها الله عليهم وما أوحي إليهم مما لم يكن كتابا مقروءا، وأعطيناهم مع ذلك ملكا واسعا.", "isBasmala": false, "translation_en": "Or do they envy the people for what God has given them of His grace? We have given the family of Abraham the Book and wisdom, and We have given them a great kingdom.", "translation_id": "ataukah mereka dengki kepada manusia (Muhammad) lantaran karunia yang Allah telah berikan kepadanya? Sesungguhnya Kami telah memberikan Kitab dan Hikmah kepada keluarga Ibrahim, dan Kami telah memberikan kepadanya kerajaan yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 55, "text": "فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِیرًا ۝٥٥", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "فمن هؤلاء الذين أوتوا حظًّا من العلم، مَن صدَّق برسالة محمد صلى الله عليه وسلم، وعمل بشرعه، ومنهم مَن أعرض ولم يستجب لدعوته، ومنع الناس من اتباعه. وحسبكم -أيها المكذبون- نار جهنم تسعَّر بكم.", "isBasmala": false, "translation_en": "Among them are those who believed in it, and among them are those who held back from it. Hell is a sufficient Inferno.", "translation_id": "Maka di antara mereka (orang-orang yang dengki itu), ada orang-orang yang beriman kepadanya, dan di antara mereka ada orang-orang yang menghalangi (manusia) dari beriman kepadanya. Dan cukuplah (bagi mereka) Jahannam yang menyala-nyala apinya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 56, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِنَا سَوۡفَ نُصۡلِیهِمۡ نَارࣰا كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَـٰهُمۡ جُلُودًا غَیۡرَهَا لِیَذُوقُوا۟ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ عَزِیزًا حَكِیمࣰا ۝٥٦", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "إن الذين جحدوا ما أنزل الله من آياته ووحي كتابه ودلائله وحججه، سوف ندخلهم نارًا يقاسون حرَّها، كلما احترقت جلودهم بدَّلْناهم جلودًا أخرى؛ ليستمر عذابهم وألمهم. إن الله تعالى كان عزيزًا لا يمتنع عليه شيء، حكيمًا في تدبيره وقضائه.", "isBasmala": false, "translation_en": "Those who reject Our revelations-We will scorch them in a Fire. Every time their skins are cooked, We will replace them with other skins, so they will experience the suffering. God is Most Powerful, Most Wise.", "translation_id": "Sesungguhnya orang-orang yang kafir kepada ayat-ayat Kami, kelak akan Kami masukkan mereka ke dalam neraka. Setiap kali kulit mereka hangus, Kami ganti kulit mereka dengan kulit yang lain, supaya mereka merasakan azab. Sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 57, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ لَّهُمۡ فِیهَاۤ أَزۡوَ ٰجࣱ مُّطَهَّرَةࣱۖ وَنُدۡخِلُهُمۡ ظِلࣰّا ظَلِیلًا ۝٥٧", "juz": 5, "hizb": "(*¼ ح 9*)", "tafsir": "والذين اطمأنت قلوبهم بالإيمان بالله تعالى والتصديق برسالة رسوله محمد صلى الله عليه وسلم، واستقاموا على الطاعة، سندخلهم جنات تجري من تحتها الأنهار، ينعمون فيها أبدًا ولا يخرجون منها، ولهم فيها أزواج طهرها الله مِن كل أذى، وندخلهم ظلا كثيفًا ممتدًا في الجنة.", "isBasmala": false, "translation_en": "As for those who believe and do good deeds, We will admit them into Gardens beneath which rivers flow, abiding therein forever. They will have purified spouses therein, and We will admit them into a shady shade.", "translation_id": "Dan orang-orang yang beriman dan mengerjakan amalan-amalan yang shaleh, kelak akan Kami masukkan mereka ke dalam surga yang di dalamnya mengalir sungai-sungai; kekal mereka di dalamnya; mereka di dalamnya mempunyai isteri-isteri yang suci, dan Kami masukkan mereka ke tempat yang teduh lagi nyaman.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 58, "text": "۞ إِنَّ ٱللَّهَ یَأۡمُرُكُمۡ أَن تُؤَدُّوا۟ ٱلۡأَمَـٰنَـٰتِ إِلَىٰۤ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَیۡنَ ٱلنَّاسِ أَن تَحۡكُمُوا۟ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا یَعِظُكُم بِهِۦۤۗ إِنَّ ٱللَّهَ كَانَ سَمِیعَۢا بَصِیرࣰا ۝٥٨", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "إن الله تعالى يأمركم بأداء مختلف الأمانات، التي اؤتمنتم عليها إلى أصحابها، فلا تفرطوا فيها، ويأمركم بالقضاء بين الناس بالعدل والقسط، إذا قضيتم بينهم، ونِعْمَ ما يعظكم الله به ويهديكم إليه. إن الله تعالى كان سميعًا لأقوالكم، مُطَّلعًا على سائر أعمالكم، بصيرًا بها.", "isBasmala": false, "translation_en": "God instructs you to give back things entrusted to you to their owners. And when you judge between people, judge with justice. God's instructions to you are excellent. God is All-Hearing, All-Seeing.", "translation_id": "Sesungguhnya Allah menyuruh kamu menyampaikan amanat kepada yang berhak menerimanya, dan (menyuruh kamu) apabila menetapkan hukum di antara manusia supaya kamu menetapkan dengan adil. Sesungguhnya Allah memberi pengajaran yang sebaik-baiknya kepadamu. Sesungguhnya Allah adalah Maha Mendengar lagi Maha Melihat.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 59, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَ وَأُو۟لِی ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَـٰزَعۡتُمۡ فِی شَیۡءࣲ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ ذَ ٰلِكَ خَیۡرࣱ وَأَحۡسَنُ تَأۡوِیلًا ۝٥٩", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، استجيبوا لأوامر الله تعالى ولا تعصوه، واستجيبوا للرسول صلى الله عليه وسلم فيما جاء به من الحق، وأطيعوا ولاة أمركم في غير معصية الله، فإن اختلفتم في شيء بينكم، فأرجعوا الحكم فيه إلى كتاب الله تعالى وسنة رسوله محمد صلى الله عليه وسلم، إن كنتم تؤمنون حق الإيمان بالله تعالى وبيوم الحساب. ذلك الردُّ إلى الكتاب والسنة خير لكم من التنازع والقول بالرأي، وأحسن عاقبة ومآلا.", "isBasmala": false, "translation_en": "O you who believe! Obey God and obey the Messenger and those in authority among you. And if you dispute over anything, refer it to God and the Messenger, if you believe in God and the Last Day. That is best, and a most excellent determination.", "translation_id": "Hai orang-orang yang beriman, taatilah Allah dan taatilah Rasul (Nya), dan ulil amri di antara kamu. Kemudian jika kamu berlainan pendapat tentang sesuatu, maka kembalikanlah ia kepada Allah (Al Quran) dan Rasul (sunnahnya), jika kamu benar-benar beriman kepada Allah dan hari kemudian. Yang demikian itu lebih utama (bagimu) dan lebih baik akibatnya.", "manzil": 1, "manzil_display": ""}], "88": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 60, "text": "أَلَمۡ تَرَ إِلَى ٱلَّذِینَ یَزۡعُمُونَ أَنَّهُمۡ ءَامَنُوا۟ بِمَاۤ أُنزِلَ إِلَیۡكَ وَمَاۤ أُنزِلَ مِن قَبۡلِكَ یُرِیدُونَ أَن یَتَحَاكَمُوۤا۟ إِلَى ٱلطَّـٰغُوتِ وَقَدۡ أُمِرُوۤا۟ أَن یَكۡفُرُوا۟ بِهِۦۖ وَیُرِیدُ ٱلشَّیۡطَـٰنُ أَن یُضِلَّهُمۡ ضَلَـٰلَۢا بَعِیدࣰا ۝٦٠", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "ألم تعلم -أيها الرسول- أمر أولئك المنافقين الذين يدَّعون الإيمان بما أُنزل إليك -وهو القرآن- وبما أُنزل إلى الرسل من قبلك، وهم يريدون أن يتحاكموا في فَصْل الخصومات بينهم إلى غير ما شرع الله من الباطل، وقد أُمروا أن يكفروا بالباطل؟ ويريد الشيطان أن يبعدهم عن طريق الحق، بعدًا شديدًا. وفي هذه الآية دليل على أن الإيمان الصادق، يقتضي الانقياد لشرع الله، والحكم به في كل أمر من الأمور، فمن زعم أنه مؤمن واختار حكم الطاغوت على حكم الله، فهو كاذب في زعمه.", "isBasmala": false, "translation_en": "Have you not observed those who claim that they believe in what was revealed to you, and in what was revealed before you, yet they seek Satanic sources for legislation, in spite of being commanded to reject them? Satan means to mislead them far away.", "translation_id": "Apakah kamu tidak memperhatikan orang-orang yang mengaku dirinya telah beriman kepada apa yang diturunkan kepadamu dan kepada apa yang diturunkan sebelum kamu? Mereka hendak berhakim kepada thaghut, padahal mereka telah diperintah mengingkari thaghut itu. Dan syaitan bermaksud menyesatkan mereka (dengan) penyesatan yang sejauh-jauhnya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 61, "text": "وَإِذَا قِیلَ لَهُمۡ تَعَالَوۡا۟ إِلَىٰ مَاۤ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَیۡتَ ٱلۡمُنَـٰفِقِینَ یَصُدُّونَ عَنكَ صُدُودࣰا ۝٦١", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "وإذا نُصح هؤلاء، وقيل لهم: تعالوا إلى ما أنزل الله، وإلى الرسول محمد صلى الله عليه وسلم، وهديه، أبصَرْتَ الذين يظهرون الإيمان ويبطنون الكفر، يعرضون عنك إعراضًا.", "isBasmala": false, "translation_en": "And when it is said to them, \"Come to what God has revealed, and to the Messenger,\" you see the hypocrites shunning you completely.", "translation_id": "Apabila dikatakan kepada mereka: \"Marilah kamu (tunduk) kepada hukum yang Allah telah turunkan dan kepada hukum Rasul\", niscaya kamu lihat orang-orang munafik menghalangi (manusia) dengan sekuat-kuatnya dari (mendekati) kamu.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 62, "text": "فَكَیۡفَ إِذَاۤ أَصَـٰبَتۡهُم مُّصِیبَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ ثُمَّ جَاۤءُوكَ یَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَاۤ إِلَّاۤ إِحۡسَـٰنࣰا وَتَوۡفِیقًا ۝٦٢", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "فكيف يكون حال أولئك المناففين، إذا حلَّت بهم مصيبة بسبب ما اقترفوه بأيديهم، ثم جاؤوك -أيها الرسول- يعتذرون، ويؤكدون لك أنهم ما قصدوا بأعمالهم تلك إلا الإحسان والتوفيق بين الخصوم؟", "isBasmala": false, "translation_en": "How about when a disaster strikes them because what their hands have put forward, and then they come to you swearing by God: \"We only intended goodwill and reconciliation\"?", "translation_id": "Maka bagaimanakah halnya apabila mereka (orang-orang munafik) ditimpa sesuatu musibah disebabkan perbuatan tangan mereka sendiri, kemudian mereka datang kepadamu sambil bersumpah: \"Demi Allah, kami sekali-kali tidak menghendaki selain penyelesaian yang baik dan perdamaian yang sempurna\".", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 63, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ یَعۡلَمُ ٱللَّهُ مَا فِی قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِیۤ أَنفُسِهِمۡ قَوۡلَۢا بَلِیغࣰا ۝٦٣", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "أولئك هم الذين يعلم الله حقيقة ما في قلوبهم من النفاق، فتولَّ عنهم، وحذِّرهم من سوء ما هم عليه، وقل لهم قولا مؤثرًا فيهم زاجرًا لهم.", "isBasmala": false, "translation_en": "They are those whom God knows what is in their hearts. So ignore them, and admonish them, and say to them concerning themselves penetrating words.", "translation_id": "Mereka itu adalah orang-orang yang Allah mengetahui apa yang di dalam hati mereka. Karena itu berpalinglah kamu dari mereka, dan berilah mereka pelajaran, dan katakanlah kepada mereka perkataan yang berbekas pada jiwa mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 64, "text": "وَمَاۤ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِیُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوۤا۟ أَنفُسَهُمۡ جَاۤءُوكَ فَٱسۡتَغۡفَرُوا۟ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُوا۟ ٱللَّهَ تَوَّابࣰا رَّحِیمࣰا ۝٦٤", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "وما بعَثْنَا من رسول من رسلنا، إلا ليستجاب له، بأمر الله تعالى وقضائه. ولو أن هؤلاء الذين ظلموا أنفسهم باقتراف السيئات، جاؤوك -أيها الرسول- في حياتك تائبين سائلين الله أن يغفر لهم ذنوبهم، واستغفرت لهم، لوجدوا الله توابًا رحيمًا.", "isBasmala": false, "translation_en": "We did not send any messenger except to be obeyed by God's leave. Had they, when they wronged themselves, come to you, and prayed for God's forgiveness, and the Messenger had prayed for their forgiveness, they would have found God Relenting and Merciful.", "translation_id": "Dan Kami tidak mengutus seseorang rasul melainkan untuk ditaati dengan seizin Allah. Sesungguhnya jikalau mereka ketika menganiaya dirinya datang kepadamu, lalu memohon ampun kepada Allah, dan Rasulpun memohonkan ampun untuk mereka, tentulah mereka mendapati Allah Maha Penerima Taubat lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 65, "text": "فَلَا وَرَبِّكَ لَا یُؤۡمِنُونَ حَتَّىٰ یُحَكِّمُوكَ فِیمَا شَجَرَ بَیۡنَهُمۡ ثُمَّ لَا یَجِدُوا۟ فِیۤ أَنفُسِهِمۡ حَرَجࣰا مِّمَّا قَضَیۡتَ وَیُسَلِّمُوا۟ تَسۡلِیمࣰا ۝٦٥", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "أقسم الله تعالى بنفسه الكريمة أن هؤلاء لا يؤمنون حقيقة حتى يجعلوك حكمًا فيما وقع بينهم من نزاع في حياتك، ويتحاكموا إلى سنتك بعد مماتك، ثم لا يجدوا في أنفسهم ضيقًا مما انتهى إليه حكمك، وينقادوا مع ذلك انقيادًا تاماً، فالحكم بما جاء به رسول الله صلى الله عليه وسلم من الكتاب والسنة في كل شأن من شؤون الحياة من صميم الإيمان مع الرضا والتسليم.", "isBasmala": false, "translation_en": "But no, by your Lord, they will not believe until they call you to arbitrate in their disputes, and then find within themselves no resentment regarding your decisions, and submit themselves completely.", "translation_id": "Maka demi Tuhanmu, mereka (pada hakekatnya) tidak beriman hingga mereka menjadikan kamu hakim terhadap perkara yang mereka perselisihkan, kemudian mereka tidak merasa dalam hati mereka sesuatu keberatan terhadap putusan yang kamu berikan, dan mereka menerima dengan sepenuhnya.", "manzil": 1, "manzil_display": ""}], "89": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 66, "text": "وَلَوۡ أَنَّا كَتَبۡنَا عَلَیۡهِمۡ أَنِ ٱقۡتُلُوۤا۟ أَنفُسَكُمۡ أَوِ ٱخۡرُجُوا۟ مِن دِیَـٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِیلࣱ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُوا۟ مَا یُوعَظُونَ بِهِۦ لَكَانَ خَیۡرࣰا لَّهُمۡ وَأَشَدَّ تَثۡبِیتࣰا ۝٦٦", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "ولو أوجبنا على هؤلاء المنافقين المتحاكمين إلى الطاغوت أن يقتل بعضهم بعضًا، أو أن يخرجوا من ديارهم، ما استجاب لذلك إلا عدد قليل منهم، ولو أنهم استجابوا لما يُنصحون به لكان ذلك نافعًا لهم، وأقوى لإيمانهم، ولأعطيناهم من عندنا ثوابًا عظيمًا في الدنيا والآخرة، ولأرشدناهم ووفقناهم إلى طريق الله القويم.", "isBasmala": false, "translation_en": "Had We decreed for them: \"Kill yourselves,\" or \"Leave your homes,\" they would not have done it, except for a few of them. But had they done what they were instructed to do, it would have been better for them, and a firmer confirmation.", "translation_id": "Dan sesungguhnya kalau Kami perintahkan kepada mereka: \"Bunuhlah dirimu atau keluarlah kamu dari kampungmu\", niscaya mereka tidak akan melakukannya kecuali sebagian kecil dari mereka. Dan sesungguhnya kalau mereka melaksanakan pelajaran yang diberikan kepada mereka, tentulah hal yang demikian itu lebih baik bagi mereka dan lebih menguatkan (iman mereka),", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 67, "text": "وَإِذࣰا لَّـَٔاتَیۡنَـٰهُم مِّن لَّدُنَّاۤ أَجۡرًا عَظِیمࣰا ۝٦٧", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "ولو أوجبنا على هؤلاء المنافقين المتحاكمين إلى الطاغوت أن يقتل بعضهم بعضًا، أو أن يخرجوا من ديارهم، ما استجاب لذلك إلا عدد قليل منهم، ولو أنهم استجابوا لما يُنصحون به لكان ذلك نافعًا لهم، وأقوى لإيمانهم، ولأعطيناهم من عندنا ثوابًا عظيمًا في الدنيا والآخرة، ولأرشدناهم ووفقناهم إلى طريق الله القويم.", "isBasmala": false, "translation_en": "And We would have given them from Our presence a rich compensation.", "translation_id": "dan kalau demikian, pasti Kami berikan kepada mereka pahala yang besar dari sisi Kami,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 68, "text": "وَلَهَدَیۡنَـٰهُمۡ صِرَ ٰطࣰا مُّسۡتَقِیمࣰا ۝٦٨", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "ولو أوجبنا على هؤلاء المنافقين المتحاكمين إلى الطاغوت أن يقتل بعضهم بعضًا، أو أن يخرجوا من ديارهم، ما استجاب لذلك إلا عدد قليل منهم، ولو أنهم استجابوا لما يُنصحون به لكان ذلك نافعًا لهم، وأقوى لإيمانهم، ولأعطيناهم من عندنا ثوابًا عظيمًا في الدنيا والآخرة، ولأرشدناهم ووفقناهم إلى طريق الله القويم.", "isBasmala": false, "translation_en": "And We would have guided them on a straight path.", "translation_id": "dan pasti Kami tunjuki mereka kepada jalan yang lurus.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 69, "text": "وَمَن یُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَـٰۤىِٕكَ مَعَ ٱلَّذِینَ أَنۡعَمَ ٱللَّهُ عَلَیۡهِم مِّنَ ٱلنَّبِیِّـۧنَ وَٱلصِّدِّیقِینَ وَٱلشُّهَدَاۤءِ وَٱلصَّـٰلِحِینَۚ وَحَسُنَ أُو۟لَـٰۤىِٕكَ رَفِیقࣰا ۝٦٩", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "ومن يستجب لأوامر الله تعالى وهدي رسوله محمد صلى الله عليه وسلم فأولئك الذين عَظُمَ شأنهم وقدرهم، فكانوا في صحبة مَن أنعم الله تعالى عليهم بالجنة من الأنبياء والصديقين الذين كمُل تصديقهم بما جاءت به الرسل، اعتقادًا وقولا وعملا والشهداء في سبيل الله وصالح المؤمنين، وحَسُنَ هؤلاء رفقاء في الجنة.", "isBasmala": false, "translation_en": "Whoever obeys God and the Messenger-these are with those whom God has blessed-among the prophets, and the sincere, and the martyrs, and the upright. Excellent are those as companions.", "translation_id": "Dan barangsiapa yang mentaati Allah dan Rasul(Nya), mereka itu akan bersama-sama dengan orang-orang yang dianugerahi nikmat oleh Allah, yaitu: Nabi-nabi, para shiddiiqiin, orang-orang yang mati syahid, dan orang-orang saleh. Dan mereka itulah teman yang sebaik-baiknya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 70, "text": "ذَ ٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِیمࣰا ۝٧٠", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "ذلك العطاء الجزيل من الله وحده. وكفى بالله عليما يعلم أحوال عباده، ومَن يَستحقُّ منهم الثواب الجزيل بما قام به من الأعمال الصالحة.", "isBasmala": false, "translation_en": "That is the grace from God. God suffices as Knower.", "translation_id": "Yang demikian itu adalah karunia dari Allah, dan Allah cukup mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 71, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ خُذُوا۟ حِذۡرَكُمۡ فَٱنفِرُوا۟ ثُبَاتٍ أَوِ ٱنفِرُوا۟ جَمِیعࣰا ۝٧١", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "يا أيها الذين آمنوا خذوا حذركم بالاستعداد لعدوكم، فاخرجوا لملاقاته جماعة بعد جماعة أو مجتمعين.", "isBasmala": false, "translation_en": "O you who believe! Take your precautions, and mobilize in groups, or mobilize altogether.", "translation_id": "Hai orang-orang yang beriman, bersiap siagalah kamu, dan majulah (ke medan pertempuran) berkelompok-kelompok, atau majulah bersama-sama!", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 72, "text": "وَإِنَّ مِنكُمۡ لَمَن لَّیُبَطِّئَنَّ فَإِنۡ أَصَـٰبَتۡكُم مُّصِیبَةࣱ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَیَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ شَهِیدࣰا ۝٧٢", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "وإنَّ منكم لنفرًا يتأخر عن الخروج لملاقاة الأعداء متثاقلا ويثبط غيره عن عمد وإصرار، فإن قُدِّر عليكم وأُصِبتم بقتل وهزيمة، قال مستبشرًا: قد حفظني الله، حين لم أكن حاضرًا مع أولئك الذين وقع لهم ما أكرهه لنفسي، وسرَّه تخلفه عنكم.", "isBasmala": false, "translation_en": "Among you is he who lags behind. Then, when a calamity befalls you, he says, \"God has favored me, that I was not martyred with them.\"", "translation_id": "Dan sesungguhnya di antara kamu ada orang yang sangat berlambat-lambat (ke medan pertempuran). Maka jika kamu ditimpa musibah ia berkata: \"Sesungguhnya Tuhan telah menganugerahkan nikmat kepada saya karena saya tidak ikut berperang bersama mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 73, "text": "وَلَىِٕنۡ أَصَـٰبَكُمۡ فَضۡلࣱ مِّنَ ٱللَّهِ لَیَقُولَنَّ كَأَن لَّمۡ تَكُنۢ بَیۡنَكُمۡ وَبَیۡنَهُۥ مَوَدَّةࣱ یَـٰلَیۡتَنِی كُنتُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِیمࣰا ۝٧٣", "juz": 5, "hizb": "(*½ ح 9*)", "tafsir": "ولئن نالكم فضل من الله وغنيمة، ليقولن -حاسدًا متحسرًا، كأن لم تكن بينكم وبينه مودة في الظاهر-: يا ليتني كنت معهم فأظفر بما ظَفِروا به من النجاة والنصرة والغنيمة.", "isBasmala": false, "translation_en": "But when some bounty from God comes to you, he says-as if no affection existed between you and him-\"If only I had been with them, I would have achieved a great victory.\"", "translation_id": "Dan sungguh jika kamu beroleh karunia (kemenangan) dari Allah, tentulah dia mengatakan seolah-oleh belum pernah ada hubungan kasih sayang antara kamu dengan dia: \"Wahai kiranya saya ada bersama-sama mereka, tentu saya mendapat kemenangan yang besar (pula)\".", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 74, "text": "۞ فَلۡیُقَـٰتِلۡ فِی سَبِیلِ ٱللَّهِ ٱلَّذِینَ یَشۡرُونَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا بِٱلۡـَٔاخِرَةِۚ وَمَن یُقَـٰتِلۡ فِی سَبِیلِ ٱللَّهِ فَیُقۡتَلۡ أَوۡ یَغۡلِبۡ فَسَوۡفَ نُؤۡتِیهِ أَجۡرًا عَظِیمࣰا ۝٧٤", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "فليجاهد في سبيل نصرة دين الله، وإعلاء كلمته، الذين يبيعون الحياة الدنيا بالدار الآخرة وثوابها. ومن يجاهد في سبيل الله مخلصًا، فيُقْتَلْ أو يَغْلِبْ، فسوف نؤتيه أجرًا عظيمًا.", "isBasmala": false, "translation_en": "Let those who sell the life of this world for the Hereafter fight in the cause of God. Whoever fights in the cause of God, and then is killed, or achieves victory, We will grant him a great compensation.", "translation_id": "Karena itu hendaklah orang-orang yang menukar kehidupan dunia dengan kehidupan akhirat berperang di jalan Allah. Barangsiapa yang berperang di jalan Allah, lalu gugur atau memperoleh kemenangan maka kelak akan Kami berikan kepadanya pahala yang besar.", "manzil": 1, "manzil_display": ""}], "90": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 75, "text": "وَمَا لَكُمۡ لَا تُقَـٰتِلُونَ فِی سَبِیلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِینَ مِنَ ٱلرِّجَالِ وَٱلنِّسَاۤءِ وَٱلۡوِلۡدَ ٰنِ ٱلَّذِینَ یَقُولُونَ رَبَّنَاۤ أَخۡرِجۡنَا مِنۡ هَـٰذِهِ ٱلۡقَرۡیَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِیࣰّا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِیرًا ۝٧٥", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "وما الذي يمنعكم -أيها المؤمنون- عن الجهاد في سبيل نصرة دين الله، ونصرة عباده المستضعفين من الرجال والنساء والصغار الذين اعتُدي عليهم، ولا حيلة لهم ولا وسيلة لديهم إلا الاستغاثة بربهم، يدعونه قائلين: ربنا أخرجنا من هذه القرية -يعني \"مكة \"- التي ظَلَم أهلها أنفسهم بالكفر والمؤمنين بالأذى، واجعل لنا من عندك وليّاً يتولى أمورنا، ونصيرًا ينصرنا على الظالمين؟", "isBasmala": false, "translation_en": "And why would you not fight in the cause of God, and the helpless men, and women, and children, cry out, \"Our Lord, deliver us from this town whose people are oppressive, and appoint for us from Your Presence a Protector, and appoint for us from Your Presence a Victor.\"", "translation_id": "Mengapa kamu tidak mau berperang di jalan Allah dan (membela) orang-orang yang lemah baik laki-laki, wanita-wanita maupun anak-anak yang semuanya berdoa: \"Ya Tuhan kami, keluarkanlah kami dari negeri ini (Mekah) yang zalim penduduknya dan berilah kami pelindung dari sisi Engkau, dan berilah kami penolong dari sisi Engkau!\".", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 76, "text": "ٱلَّذِینَ ءَامَنُوا۟ یُقَـٰتِلُونَ فِی سَبِیلِ ٱللَّهِۖ وَٱلَّذِینَ كَفَرُوا۟ یُقَـٰتِلُونَ فِی سَبِیلِ ٱلطَّـٰغُوتِ فَقَـٰتِلُوۤا۟ أَوۡلِیَاۤءَ ٱلشَّیۡطَـٰنِۖ إِنَّ كَیۡدَ ٱلشَّیۡطَـٰنِ كَانَ ضَعِیفًا ۝٧٦", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "الذين صدَقُوا في إيمانهم اعتقادًا وعملا يجاهدون في سبيل نصرة الحق وأهله، والذين كفروا يقاتلون في سبيل البغي والفساد في الأرض، فقاتلوا أيها المؤمنون أهل الكفر والشرك الذين يتولَّون الشيطان، ويطيعون أمره، إن تدبير الشيطان لأوليائه كان ضعيفًا.", "isBasmala": false, "translation_en": "Those who believe fight in the cause of God, while those who disbelieve fight in the cause of Evil. So fight the allies of the Devil. Surely the strategy of the Devil is weak.", "translation_id": "Orang-orang yang beriman berperang di jalan Allah, dan orang-orang yang kafir berperang di jalan thaghut, sebab itu perangilah kawan-kawan syaitan itu, karena sesungguhnya tipu daya syaitan itu adalah lemah.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 77, "text": "أَلَمۡ تَرَ إِلَى ٱلَّذِینَ قِیلَ لَهُمۡ كُفُّوۤا۟ أَیۡدِیَكُمۡ وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَیۡهِمُ ٱلۡقِتَالُ إِذَا فَرِیقࣱ مِّنۡهُمۡ یَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡیَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡیَةࣰۚ وَقَالُوا۟ رَبَّنَا لِمَ كَتَبۡتَ عَلَیۡنَا ٱلۡقِتَالَ لَوۡلَاۤ أَخَّرۡتَنَاۤ إِلَىٰۤ أَجَلࣲ قَرِیبࣲۗ قُلۡ مَتَـٰعُ ٱلدُّنۡیَا قَلِیلࣱ وَٱلۡـَٔاخِرَةُ خَیۡرࣱ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِیلًا ۝٧٧", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "ألم تعلم -أيها الرسول- أمر أولئك الذين قيل لهم قبل الإذن بالجهاد: امنعوا أيديكم عن قتال أعدائكم من المشركين، وعليكم أداء ما فرضه الله عليكم من الصلاة، والزكاة، فلما فرض عليهم القتال إذا جماعة منهم قد تغير حالهم، فأصبحوا يخافون الناس ويرهبونهم، كخوفهم من الله أو أشد، ويعلنون عما اعتراهم من شدة الخوف، فيقولون: ربنا لِمَ أَوْجَبْتَ علينا القتال؟ هلا أمهلتنا إلى وقت قريب، رغبة منهم في متاع الحياة الدنيا، قل لهم -أيها الرسول-: متاع الدنيا قليل، والآخرة وما فيها أعظم وأبقى لمن اتقى، فعمل بما أُمر به، واجتنب ما نُهي عنه.، لا يظلم ربك أحدًا شيئًا، ولو كان مقدار الخيط الذي يكون في شق نَواة التمرة.", "isBasmala": false, "translation_en": "Have you not considered those who were told, \"Restrain your hands, and perform your prayers, and spend in regular charity\"? But when fighting was ordained for them, a faction of them feared the people as God is ought to be feared, or even more. And they said, \"Our Lord, why did You ordain fighting for us? If only You would postpone it for us for a short while.\" Say, \"The enjoyments of this life are brief, but the Hereafter is better for the righteous, and you will not be wronged one bit.\"", "translation_id": "Tidakkah kamu perhatikan orang-orang yang dikatakan kepada mereka: \"Tahanlah tanganmu (dari berperang), dirikanlah sembahyang dan tunaikanlah zakat!\" Setelah diwajibkan kepada mereka berperang, tiba-tiba sebahagian dari mereka (golongan munafik) takut kepada manusia (musuh), seperti takutnya kepada Allah, bahkan lebih sangat dari itu takutnya. Mereka berkata: \"Ya Tuhan kami, mengapa Engkau wajibkan berperang kepada kami? Mengapa tidak Engkau tangguhkan (kewajiban berperang) kepada kami sampai kepada beberapa waktu lagi?\" Katakanlah: \"Kesenangan di dunia ini hanya sebentar dan akhirat itu lebih baik untuk orang-orang yang bertakwa, dan kamu tidak akan dianiaya sedikitpun.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 78, "text": "أَیۡنَمَا تَكُونُوا۟ یُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِی بُرُوجࣲ مُّشَیَّدَةࣲۗ وَإِن تُصِبۡهُمۡ حَسَنَةࣱ یَقُولُوا۟ هَـٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَیِّئَةࣱ یَقُولُوا۟ هَـٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلࣱّ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَـٰۤؤُلَاۤءِ ٱلۡقَوۡمِ لَا یَكَادُونَ یَفۡقَهُونَ حَدِیثࣰا ۝٧٨", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "أينما تكونوا يلحقكم الموت في أي مكان كنتم فيه عند حلول آجالكم، ولو كنتم في حصون منيعة بعيدة عن ساحة المعارك والقتال. وإن يحصل لهم ما يسرُّهم من متاع هذه الحياة، ينسبوا حصوله إلى الله تعالى، وإن وقع عليهم ما يكرهونه ينسبوه إلى الرسول محمد صلى الله عليه وسلم جهالة وتشاؤمًا، وما علموا أن ذلك كله من عند الله وحده، بقضائه وقدره، فما بالهم لا يقاربون فَهْمَ أيِّ حديث تحدثهم به؟", "isBasmala": false, "translation_en": "Wherever you may be, death will catch up with you, even if you were in fortified towers. When a good fortune comes their way, they say, \"This is from God.\" But when a misfortune befalls them, they say, \"This is from you.\" Say, \"All is from God.\" So what is the matter with these people, that they hardly understand a thing?", "translation_id": "Di mana saja kamu berada, kematian akan mendapatkan kamu, kendatipun kamu di dalam benteng yang tinggi lagi kokoh, dan jika mereka memperoleh kebaikan, mereka mengatakan: \"Ini adalah dari sisi Allah\", dan kalau mereka ditimpa sesuatu bencana mereka mengatakan: \"Ini (datangnya) dari sisi kamu (Muhammad)\". Katakanlah: \"Semuanya (datang) dari sisi Allah\". Maka mengapa orang-orang itu (orang munafik) hampir-hampir tidak memahami pembicaraan sedikitpun?", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 79, "text": "مَّاۤ أَصَابَكَ مِنۡ حَسَنَةࣲ فَمِنَ ٱللَّهِۖ وَمَاۤ أَصَابَكَ مِن سَیِّئَةࣲ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَـٰكَ لِلنَّاسِ رَسُولࣰاۚ وَكَفَىٰ بِٱللَّهِ شَهِیدࣰا ۝٧٩", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "ما أصابك -أيها الإنسان- مِن خير ونعمة فهو من الله تعالى وحده، فضلا وإحسانًا، وما أصابك من جهد وشدة فبسبب عملك السيئ، وما اقترفته يداك من الخطايا والسيئات. وبعثناك -أيها الرسول- لعموم الناس رسولا تبلغهم رسالة ربك، وكفى بالله شهيدًا على صدق رسالتك.", "isBasmala": false, "translation_en": "Whatever good happens to you is from God, and whatever bad happens to you is from your own self. We sent you to humanity as a messenger, and God is Witness enough.", "translation_id": "Apa saja nikmat yang kamu peroleh adalah dari Allah, dan apa saja bencana yang menimpamu, maka dari (kesalahan) dirimu sendiri. Kami mengutusmu menjadi Rasul kepada segenap manusia. Dan cukuplah Allah menjadi saksi.", "manzil": 1, "manzil_display": ""}], "91": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 80, "text": "مَّن یُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَاۤ أَرۡسَلۡنَـٰكَ عَلَیۡهِمۡ حَفِیظࣰا ۝٨٠", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "من يستجب للرسول صلى الله عليه وسلم، ويعمل بهديه، فقد استجاب لله تعالى وامتثل أمره، ومن أعرض عن طاعة الله ورسوله فما بعثناك -أيها الرسول- على هؤلاء المعترضين رقيبًا تحفظ أعمالهم وتحاسبهم عليها، فحسابهم علينا.", "isBasmala": false, "translation_en": "Whoever obeys the Messenger is obeying God. And whoever turns away-We did not send you as a watcher over them.", "translation_id": "Barangsiapa yang mentaati Rasul itu, sesungguhnya ia telah mentaati Allah. Dan barangsiapa yang berpaling (dari ketaatan itu), maka Kami tidak mengutusmu untuk menjadi pemelihara bagi mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 81, "text": "وَیَقُولُونَ طَاعَةࣱ فَإِذَا بَرَزُوا۟ مِنۡ عِندِكَ بَیَّتَ طَاۤىِٕفَةࣱ مِّنۡهُمۡ غَیۡرَ ٱلَّذِی تَقُولُۖ وَٱللَّهُ یَكۡتُبُ مَا یُبَیِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلًا ۝٨١", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "ويُظْهر هؤلاء المعرضون، وهم في مجلس رسول الله صلى الله عليه وسلم، طاعتهم للرسول وما جاء به، فإذا ابتعدوا عنه وانصرفوا عن مجلسه، دبَّر جماعة منهم ليلا غير ما أعلنوه من الطاعة، وما علموا أن الله يحصي عليهم ما يدبرون، وسيجازيهم عليه أتم الجزاء، فتول عنهم -أيها الرسول- ولا تبال بهم، فإنهم لن يضروك، وتوكل على الله، وحسبك به وليّاً وناصرًا.", "isBasmala": false, "translation_en": "They profess obedience, but when they leave your presence, some of them conspire something contrary to what you said. But God writes down what they conspire. So avoid them, and put your trust in God. God is Guardian enough.", "translation_id": "Dan mereka (orang-orang munafik) mengatakan: \"(Kewajiban kami hanyalah) taat\". Tetapi apabila mereka telah pergi dari sisimu, sebahagian dari mereka mengatur siasat di malam hari (mengambil keputusan) lain dari yang telah mereka katakan tadi. Allah menulis siasat yang mereka atur di malam hari itu, maka berpalinglah kamu dari mereka dan tawakallah kepada Allah. Cukuplah Allah menjadi Pelindung.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 82, "text": "أَفَلَا یَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَیۡرِ ٱللَّهِ لَوَجَدُوا۟ فِیهِ ٱخۡتِلَـٰفࣰا كَثِیرࣰا ۝٨٢", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "أفلا ينظر هؤلاء في القرآن، وما جاء به من الحق، نظر تأمل وتدبر، حيث جاء على نسق محكم يقطع بأنه من عند الله وحده؟ ولو كان مِن عند غيره لوجدوا فيه اختلافًا كثيرًا.", "isBasmala": false, "translation_en": "Do they not ponder the Quran? Had it been from any other than God, they would have found in it much discrepancy.", "translation_id": "Maka apakah mereka tidak memperhatikan Al Quran? Kalau kiranya Al Quran itu bukan dari sisi Allah, tentulah mereka mendapat pertentangan yang banyak di dalamnya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 83, "text": "وَإِذَا جَاۤءَهُمۡ أَمۡرࣱ مِّنَ ٱلۡأَمۡنِ أَوِ ٱلۡخَوۡفِ أَذَاعُوا۟ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰۤ أُو۟لِی ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِینَ یَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّیۡطَـٰنَ إِلَّا قَلِیلࣰا ۝٨٣", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "وإذا جاء هؤلاء الذين لم يستقر الإيمان في قلوبهم أمْرٌ يجب كتمانه متعلقًا بالأمن الذي يعود خيره على الإسلام والمسلمين، أو بالخوف الذي يلقي في قلوبهم عدم الاطمئنان، أفشوه وأذاعوا به في الناس، ولو ردَّ هؤلاء ما جاءهم إلى رسول الله صلى الله عليه وسلم وإلى أهل العلم والفقه لَعَلِمَ حقيقة معناه أهل الاستنباط منهم. ولولا أنْ تَفَضَّلَ الله عليكم ورحمكم لاتبعتم الشيطان ووساوسه إلا قليلا منكم.", "isBasmala": false, "translation_en": "When some news of security or alarm comes their way, they broadcast it. But had they referred it to the Messenger, and to those in authority among them, those who can draw conclusions from it would have comprehended it. Were it not for God's blessing and mercy upon you, you would have followed the Devil, except for a few.", "translation_id": "Dan apabila datang kepada mereka suatu berita tentang keamanan ataupun ketakutan, mereka lalu menyiarkannya. Dan kalau mereka menyerahkannya kepada Rasul dan Ulil Amri di antara mereka, tentulah orang-orang yang ingin mengetahui kebenarannya (akan dapat) mengetahuinya dari mereka (Rasul dan Ulil Amri). Kalau tidaklah karena karunia dan rahmat Allah kepada kamu, tentulah kamu mengikut syaitan, kecuali sebahagian kecil saja (di antaramu).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 84, "text": "فَقَـٰتِلۡ فِی سَبِیلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِینَۖ عَسَى ٱللَّهُ أَن یَكُفَّ بَأۡسَ ٱلَّذِینَ كَفَرُوا۟ۚ وَٱللَّهُ أَشَدُّ بَأۡسࣰا وَأَشَدُّ تَنكِیلࣰا ۝٨٤", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "فجاهد -أيها النبي- في سبيل الله لإعلاء كلمته، لا تلزم فعل غيرك ولا تؤاخذ به، وحُضَّ المؤمنين على القتال والجهاد، ورغِّبهم فيه، لعل الله يمنع بك وبهم بأس الكافرين وشدتهم. والله تعالى أشد قوة وأعظم عقوبة للكافرين.", "isBasmala": false, "translation_en": "So fight in the cause of God; you are responsible only for yourself. And rouse the believers. Perhaps God will restrain the might of those who disbelieve. God is Stronger in Might, and More Punishing.", "translation_id": "Maka berperanglah kamu pada jalan Allah, tidaklah kamu dibebani melainkan dengan kewajiban kamu sendiri. Kobarkanlah semangat para mukmin (untuk berperang). Mudah-mudahan Allah menolak serangan orang-orang yang kafir itu. Allah amat besar kekuatan dan amat keras siksaan(Nya).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 85, "text": "مَّن یَشۡفَعۡ شَفَـٰعَةً حَسَنَةࣰ یَكُن لَّهُۥ نَصِیبࣱ مِّنۡهَاۖ وَمَن یَشۡفَعۡ شَفَـٰعَةࣰ سَیِّئَةࣰ یَكُن لَّهُۥ كِفۡلࣱ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ مُّقِیتࣰا ۝٨٥", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "من يَسْعَ لحصول غيره على الخير يكن له بشفاعته نصيب من الثواب، ومن يَسْعَ لإيصال الشر إلى غيره يكن له نصيب من الوزر والإثم. وكان الله على كل شيء شاهدًا وحفيظًا.", "isBasmala": false, "translation_en": "Whoever intercedes for a good cause has a share in it, and whoever intercedes for an evil cause shares in its burdens. God keeps watch over everything.", "translation_id": "Barangsiapa yang memberikan syafa'at yang baik, niscaya ia akan memperoleh bahagian (pahala) dari padanya. Dan barangsiapa memberi syafa'at yang buruk, niscaya ia akan memikul bahagian (dosa) dari padanya. Allah Maha Kuasa atas segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 86, "text": "وَإِذَا حُیِّیتُم بِتَحِیَّةࣲ فَحَیُّوا۟ بِأَحۡسَنَ مِنۡهَاۤ أَوۡ رُدُّوهَاۤۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَیۡءٍ حَسِیبًا ۝٨٦", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "وإذا سلَّم عليكم المسلم فردُّوا عليه بأفضل مما سلَّم لفظًا وبشاشةً، أو ردوا عليه بمثل ما سلَّم، ولكل ثوابه وجزاؤه. إن الله تعالى كان على كل شيء مجازيًا.", "isBasmala": false, "translation_en": "When you are greeted with a greeting, respond with a better greeting, or return it. God keeps count of everything.", "translation_id": "Apabila kamu diberi penghormatan dengan sesuatu penghormatan, maka balaslah penghormatan itu dengan yang lebih baik dari padanya, atau balaslah penghormatan itu (dengan yang serupa). Sesungguhnya Allah memperhitungankan segala sesuatu.", "manzil": 1, "manzil_display": ""}], "92": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 87, "text": "ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ لَیَجۡمَعَنَّكُمۡ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ لَا رَیۡبَ فِیهِۗ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِیثࣰا ۝٨٧", "juz": 5, "hizb": "(*¾ ح 9*)", "tafsir": "الله وحده المتفرد بالألوهية لجميع الخلق، ليجمعنكم يوم القيامة، الذي لا شك فيه، للحساب والجزاء. ولا أحد أصدق من الله حديثًا فيما أخبر به.", "isBasmala": false, "translation_en": "God-there is no god except He. He will gather you to the Day of Resurrection, in which there is no doubt. And who speaks more truly than God?", "translation_id": "Allah, tidak ada Tuhan (yang berhak disembah) selain Dia. Sesungguhnya Dia akan mengumpulkan kamu di hari kiamat, yang tidak ada keraguan terjadinya. Dan siapakah orang yang lebih benar perkataan(nya) dari pada Allah?", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 88, "text": "۞ فَمَا لَكُمۡ فِی ٱلۡمُنَـٰفِقِینَ فِئَتَیۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوۤا۟ۚ أَتُرِیدُونَ أَن تَهۡدُوا۟ مَنۡ أَضَلَّ ٱللَّهُۖ وَمَن یُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِیلࣰا ۝٨٨", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "فما لكم -أيها المؤمنون- في شأن المنافقين إذ اختلفتم فرقتين: فرقة تقول بقتالهم وأخرى لا تقول بذلك؟ والله تعالى قد أوقعهم في الكفر والضلال بسبب سوء أعمالهم. أتودون هداية من صرف الله تعالى قلبه عن دينه؟ ومن خذله الله عن دينه، واتباع ما أمره به، فلا طريق له إلى الهدى.", "isBasmala": false, "translation_en": "What is the matter with you, divided into two factions regarding the hypocrites, when God Himself has overwhelmed them on account of what they did? Do you want to guide those whom God has led astray? Whomever God leads astray-you will never find for him a way.", "translation_id": "Maka mengapa kamu (terpecah) menjadi dua golongan dalam (menghadapi) orang-orang munafik, padahal Allah telah membalikkan mereka kepada kekafiran, disebabkan usaha mereka sendiri? Apakah kamu bermaksud memberi petunjuk kepada orang-orang yang telah disesatkan Allah? Barangsiapa yang disesatkan Allah, sekali-kali kamu tidak mendapatkan jalan (untuk memberi petunjuk) kepadanya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 89, "text": "وَدُّوا۟ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُوا۟ فَتَكُونُونَ سَوَاۤءࣰۖ فَلَا تَتَّخِذُوا۟ مِنۡهُمۡ أَوۡلِیَاۤءَ حَتَّىٰ یُهَاجِرُوا۟ فِی سَبِیلِ ٱللَّهِۚ فَإِن تَوَلَّوۡا۟ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَیۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُوا۟ مِنۡهُمۡ وَلِیࣰّا وَلَا نَصِیرًا ۝٨٩", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "تمنَّى المنافقون لكم أيها المؤمنون، لو تنكرون حقيقة ما آمنت به قلوبكم، مثلما أنكروه بقلوبهم، فتكونون معهم في الإنكار سواء، فلا تتخذوا منهم أصفياء لكم، حتى يهاجروا في سبيل الله، برهانًا على صدق إيمانهم، فإن أعرضوا عما دعوا إليه، فخذوهم أينما كانوا واقتلوهم، ولا تتخذوا منهم وليّاً من دون الله ولا نصيرًا تستنصرونه به.", "isBasmala": false, "translation_en": "They would love to see you disbelieve, just as they disbelieve, so you would become equal. So do not befriend any of them, unless they emigrate in the way of God. If they turn away, seize them and execute them wherever you may find them; and do not take from among them allies or supporters.", "translation_id": "Mereka ingin supaya kamu menjadi kafir sebagaimana mereka telah menjadi kafir, lalu kamu menjadi sama (dengan mereka). Maka janganlah kamu jadikan di antara mereka penolong-penolong(mu), hingga mereka berhijrah pada jalan Allah. Maka jika mereka berpaling, tawan dan bunuhlah mereka di mana saja kamu menemuinya, dan janganlah kamu ambil seorangpun di antara mereka menjadi pelindung, dan jangan (pula) menjadi penolong,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 90, "text": "إِلَّا ٱلَّذِینَ یَصِلُونَ إِلَىٰ قَوۡمِۭ بَیۡنَكُمۡ وَبَیۡنَهُم مِّیثَـٰقٌ أَوۡ جَاۤءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أَن یُقَـٰتِلُوكُمۡ أَوۡ یُقَـٰتِلُوا۟ قَوۡمَهُمۡۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَیۡكُمۡ فَلَقَـٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ یُقَـٰتِلُوكُمۡ وَأَلۡقَوۡا۟ إِلَیۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَیۡهِمۡ سَبِیلࣰا ۝٩٠", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "لكن الذين يتصلون بقوم بينكم وبينهم عهد وميثاق فلا تقاتلوهم، وكذلك الذين أتَوا إليكم وقد ضاقت صدورهم وكرهوا أن يقاتلوكم، كما كرهوا أن يقاتلوا قومهم، فلم يكونوا معكم ولا مع قومهم، فلا تقاتلوهم، ولو شاء الله تعالى لسلَّطهم عليكم، فلقاتلوكم مع أعدائكم من المشركين، ولكن الله تعالى صرفهم عنكم بفضله وقدرته، فإن تركوكم فلم يقاتلوكم، وانقادوا اليكم مستسلمين، فليس لكم عليهم من طريق لقتالهم.", "isBasmala": false, "translation_en": "Except those who join people with whom you have a treaty, or those who come to you reluctant to fight you or fight their own people. Had God willed, He would have given them power over you, and they would have fought you. If they withdraw from you, and do not fight you, and offer you peace, then God assigns no excuse for you against them.", "translation_id": "kecuali orang-orang yang meminta perlindungan kepada sesuatu kaum, yang antara kamu dan kaum itu telah ada perjanjian (damai) atau orang-orang yang datang kepada kamu sedang hati mereka merasa keberatan untuk memerangi kamu dan memerangi kaumnya. Kalau Allah menghendaki, tentu Dia memberi kekuasaan kepada mereka terhadap kamu, lalu pastilah mereka memerangimu. tetapi jika mereka membiarkan kamu, dan tidak memerangi kamu serta mengemukakan perdamaian kepadamu maka Allah tidak memberi jalan bagimu (untuk menawan dan membunuh) mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 91, "text": "سَتَجِدُونَ ءَاخَرِینَ یُرِیدُونَ أَن یَأۡمَنُوكُمۡ وَیَأۡمَنُوا۟ قَوۡمَهُمۡ كُلَّ مَا رُدُّوۤا۟ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُوا۟ فِیهَاۚ فَإِن لَّمۡ یَعۡتَزِلُوكُمۡ وَیُلۡقُوۤا۟ إِلَیۡكُمُ ٱلسَّلَمَ وَیَكُفُّوۤا۟ أَیۡدِیَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَیۡثُ ثَقِفۡتُمُوهُمۡۚ وَأُو۟لَـٰۤىِٕكُمۡ جَعَلۡنَا لَكُمۡ عَلَیۡهِمۡ سُلۡطَـٰنࣰا مُّبِینࣰا ۝٩١", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "ستجدون قومًا آخرين من المنافقين يودون الاطمئنان على أنفسهم من جانبكم، فيظهرون لكم الإيمان، ويودون الاطمئنان على أنفسهم من جانب قومهم الكافرين، فيظهرون لهم الكفر، كلما أعيدوا إلى موطن الكفر والكافرين، وقعوا في أسوأ حال. فهؤلاء إن لم ينصرفوا عنكم، ويقدموا إليكم الاستسلام التام، ويمنعوا أنفسهم عن قتالكم فخذوهم بقوة واقتلوهم أينما كانوا، وأولئك الذين بلغوا في هذا المسلك السيِّئ حدّاً يميزهم عمَّن عداهم، فهم الذين جعلنا لكم الحجة البينة على قتلهم وأسرهم.", "isBasmala": false, "translation_en": "You will find others who want security from you, and security from their own people. But whenever they are tempted into civil discord, they plunge into it. So if they do not withdraw from you, nor offer you peace, nor restrain their hands, seize them and execute them wherever you find them. Against these, We have given you clear authorization.", "translation_id": "Kelak kamu akan dapati (golongan-golongan) yang lain, yang bermaksud supaya mereka aman dari pada kamu dan aman (pula) dari kaumnya. Setiap mereka diajak kembali kepada fitnah (syirik), merekapun terjun kedalamnya. Karena itu jika mereka tidak membiarkan kamu dan (tidak) mau mengemukakan perdamaian kepadamu, serta (tidak) menahan tangan mereka (dari memerangimu), maka tawanlah mereka dan bunuhlah mereka dan merekalah orang-orang yang Kami berikan kepadamu alasan yang nyata (untuk menawan dan membunuh) mereka.", "manzil": 1, "manzil_display": ""}], "93": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 92, "text": "وَمَا كَانَ لِمُؤۡمِنٍ أَن یَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـࣰٔاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـࣰٔا فَتَحۡرِیرُ رَقَبَةࣲ مُّؤۡمِنَةࣲ وَدِیَةࣱ مُّسَلَّمَةٌ إِلَىٰۤ أَهۡلِهِۦۤ إِلَّاۤ أَن یَصَّدَّقُوا۟ۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوࣲّ لَّكُمۡ وَهُوَ مُؤۡمِنࣱ فَتَحۡرِیرُ رَقَبَةࣲ مُّؤۡمِنَةࣲۖ وَإِن كَانَ مِن قَوۡمِۭ بَیۡنَكُمۡ وَبَیۡنَهُم مِّیثَـٰقࣱ فَدِیَةࣱ مُّسَلَّمَةٌ إِلَىٰۤ أَهۡلِهِۦ وَتَحۡرِیرُ رَقَبَةࣲ مُّؤۡمِنَةࣲۖ فَمَن لَّمۡ یَجِدۡ فَصِیَامُ شَهۡرَیۡنِ مُتَتَابِعَیۡنِ تَوۡبَةࣰ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا ۝٩٢", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "ولا يحق لمؤمن الاعتداء على أخيه المؤمن وقتله بغير حق، إلا أن يقع منه ذلك على وجه الخطأ الذي لا عمد فيه، ومن وقع منه ذلك الخطأ فعليه عتق رقبة مؤمنة، وتسليم دية مقدرة إلى أوليائه، إلا أن يتصدقوا بها عليه ويعفوا عنه. فإن كان المقتول من قوم كفار أعداء للمؤمنين، وهو مؤمن بالله تعالى، وبما أنزل من الحق على رسوله محمد صلى الله عليه وسلم، فعلى قاتله عتق رقبة مؤمنة، وإن كان من قوم بينكم وبينهم عهد وميثاق، فعلى قاتله دية تسلم إلى أوليائه وعتق رقبة مؤمنة، فمن لم يجد القدرة على عتق رقبة مؤمنة، فعليه صيام شهرين متتابعين؛ ليتوب الله تعالى عليه. وكان الله تعالى عليما بحقيقة شأن عباده، حكيمًا فيما شرعه لهم.", "isBasmala": false, "translation_en": "Never should a believer kill another believer, unless by error. Anyone who kills a believer by error must set free a believing slave, and pay compensation to the victim's family, unless they remit it as charity. If the victim belonged to a people who are hostile to you, but is a believer, then the compensation is to free a believing slave. If he belonged to a people with whom you have a treaty, then compensation should be handed over to his family, and a believing slave set free. Anyone who lacks the means must fast for two consecutive months, by way of repentance to God. God is All-Knowing, Most Wise.", "translation_id": "Dan tidak layak bagi seorang mukmin membunuh seorang mukmin (yang lain), kecuali karena tersalah (tidak sengaja), dan barangsiapa membunuh seorang mukmin karena tersalah (hendaklah) ia memerdekakan seorang hamba sahaya yang beriman serta membayar diat yang diserahkan kepada keluarganya (si terbunuh itu), kecuali jika mereka (keluarga terbunuh) bersedekah. Jika ia (si terbunuh) dari kaum (kafir) yang ada perjanjian (damai) antara mereka dengan kamu, maka (hendaklah si pembunuh) membayar diat yang diserahkan kepada keluarganya (si terbunuh) serta memerdekakan hamba sahaya yang beriman. Barangsiapa yang tidak memperolehnya, maka hendaklah ia (si pembunuh) berpuasa dua bulan berturut-turut untuk penerimaan taubat dari pada Allah. Dan adalah Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 93, "text": "وَمَن یَقۡتُلۡ مُؤۡمِنࣰا مُّتَعَمِّدࣰا فَجَزَاۤؤُهُۥ جَهَنَّمُ خَـٰلِدࣰا فِیهَا وَغَضِبَ ٱللَّهُ عَلَیۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِیمࣰا ۝٩٣", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "ومن يَعْتَدِ على مؤمن فيقتله عن عمد بغير حق فعاقبته جهنم، خالدًا فيها مع سخط الله تعالى عليه وطَرْدِهِ من رحمته، إن جازاه على ذنبه وأعدَّ الله له أشد العذاب بسبب ما ارتكبه من هذه الجناية العظيمة. ولكنه سبحانه يعفو ويتفضل على أهل الإيمان فلا يجازيهم بالخلود في جهنم.", "isBasmala": false, "translation_en": "Whoever kills a believer deliberately, the penalty for him is Hell, where he will remain forever. And God will be angry with him, and will curse him, and will prepare for him a terrible punishment.", "translation_id": "Dan barangsiapa yang membunuh seorang mukmin dengan sengaja maka balasannya ialah Jahannam, kekal ia di dalamnya dan Allah murka kepadanya, dan mengutukinya serta menyediakan azab yang besar baginya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 94, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا ضَرَبۡتُمۡ فِی سَبِیلِ ٱللَّهِ فَتَبَیَّنُوا۟ وَلَا تَقُولُوا۟ لِمَنۡ أَلۡقَىٰۤ إِلَیۡكُمُ ٱلسَّلَـٰمَ لَسۡتَ مُؤۡمِنࣰا تَبۡتَغُونَ عَرَضَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِیرَةࣱۚ كَذَ ٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَیۡكُمۡ فَتَبَیَّنُوۤا۟ۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِیرࣰا ۝٩٤", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه إذا خرجتم في الأرض مجاهدين في سبيل الله فكونوا على بينة مما تأتون وتتركون، ولا تنفوا الإيمان عمن بدا منه شيء من علامات الإسلام ولم يقاتلكم؛ لاحتمال أن يكون مؤمنًا يخفي إيمانه، طالبين بذلك متاع الحياة الدنيا، والله تعالى عنده من الفضل والعطاء ما يغنيكم به، كذلك كنتم في بدء الإسلام تخفون إيمانكم عن قومكم من المشركين فمَنَّ الله عليكم، وأعزَّكم بالإيمان والقوة، فكونوا على بيِّنة ومعرفة في أموركم. إن الله تعالى عليم بكل أعمالكم، مطَّلع على دقائق أموركم، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "O you who believe! When you journey in the way of God, investigate, and do not say to him who offers you peace, \"You are not a believer,\" aspiring for the goods of this world. With God are abundant riches. You yourselves were like this before, and God bestowed favor on you; so investigate. God is well aware of what you do.", "translation_id": "Hai orang-orang yang beriman, apabila kamu pergi (berperang) di jalan Allah, maka telitilah dan janganlah kamu mengatakan kepada orang yang mengucapkan \"salam\" kepadamu: \"Kamu bukan seorang mukmin\" (lalu kamu membunuhnya), dengan maksud mencari harta benda kehidupan di dunia, karena di sisi Allah ada harta yang banyak. Begitu jugalah keadaan kamu dahulu, lalu Allah menganugerahkan nikmat-Nya atas kamu, maka telitilah. Sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}], "94": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 95, "text": "لَّا یَسۡتَوِی ٱلۡقَـٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِینَ غَیۡرُ أُو۟لِی ٱلضَّرَرِ وَٱلۡمُجَـٰهِدُونَ فِی سَبِیلِ ٱللَّهِ بِأَمۡوَ ٰلِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَـٰهِدِینَ بِأَمۡوَ ٰلِهِمۡ وَأَنفُسِهِمۡ عَلَى ٱلۡقَـٰعِدِینَ دَرَجَةࣰۚ وَكُلࣰّا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ ٱلۡمُجَـٰهِدِینَ عَلَى ٱلۡقَـٰعِدِینَ أَجۡرًا عَظِیمࣰا ۝٩٥", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "لا يتساوى المتخلفون عن الجهاد في سبيل الله -غير أصحاب الأعذار منهم- والمجاهدون في سبيل الله، بأموالهم وأنفسهم، فضَّل الله تعالى المجاهدين على القاعدين، ورفع منزلتهم درجة عالية في الجنة، وقد وعد الله كلا من المجاهدين بأموالهم وأنفسهم والقاعدين من أهل الأعذار الجنة لِما بذلوا وضحَّوا في سبيل الحق، وفضَّل الله تعالى المجاهدين على القاعدين ثوابًا جزيلا.", "isBasmala": false, "translation_en": "Not equal are the inactive among the believers-except the disabled-and the strivers in the cause of God with their possessions and their persons. God prefers the strivers with their possessions and their persons above the inactive, by a degree. But God has promised goodness to both. Yet God favors the strivers, over the inactive, with a great reward.", "translation_id": "Tidaklah sama antara mukmin yang duduk (yang tidak ikut berperang) yang tidak mempunyai 'uzur dengan orang-orang yang berjihad di jalan Allah dengan harta mereka dan jiwanya. Allah melebihkan orang-orang yang berjihad dengan harta dan jiwanya atas orang-orang yang duduk satu derajat. Kepada masing-masing mereka Allah menjanjikan pahala yang baik (surga) dan Allah melebihkan orang-orang yang berjihad atas orang yang duduk dengan pahala yang besar,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 96, "text": "دَرَجَـٰتࣲ مِّنۡهُ وَمَغۡفِرَةࣰ وَرَحۡمَةࣰۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمًا ۝٩٦", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "هذا الثواب الجزيل منازل عالية في الجنات من الله تعالى لخاصة عباده المجاهدين في سبيله، ومغفرة لذنوبهم ورحمة واسعة ينعمون فيها. وكان الله غفورًا لمن تاب إليه وأناب، رحيمًا بأهل طاعته، المجاهدين في سبيله.", "isBasmala": false, "translation_en": "Degrees from Him, and forgiveness, and mercy. God is Forgiving and Merciful.", "translation_id": "(yaitu) beberapa derajat dari pada-Nya, ampunan serta rahmat. Dan adalah Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 97, "text": "إِنَّ ٱلَّذِینَ تَوَفَّىٰهُمُ ٱلۡمَلَـٰۤىِٕكَةُ ظَالِمِیۤ أَنفُسِهِمۡ قَالُوا۟ فِیمَ كُنتُمۡۖ قَالُوا۟ كُنَّا مُسۡتَضۡعَفِینَ فِی ٱلۡأَرۡضِۚ قَالُوۤا۟ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَ ٰسِعَةࣰ فَتُهَاجِرُوا۟ فِیهَاۚ فَأُو۟لَـٰۤىِٕكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَاۤءَتۡ مَصِیرًا ۝٩٧", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "إن الذين توفَّاهم الملائكة وقد ظلموا أنفسهم بقعودهم في دار الكفر وترك الهجرة، تقول لهم الملائكة توبيخًا لهم: في أي شيء كنتم من أمر دينكم؟ فيقولون: كنا ضعفاء في أرضنا، عاجزين عن دفع الظلم والقهر عنا، فيقولون لهم توبيخا: ألم تكن أرض الله واسعة فتخرجوا من أرضكم إلى أرض أخرى بحيث تأمنون على دينكم؟ فأولئك مثواهم النار، وقبح هذا المرجع والمآب.", "isBasmala": false, "translation_en": "While the angels are removing the souls of those who have wronged themselves, they will say, \"What was the matter with you?\" They will say, \"We were oppressed in the land.\" They will say, \"Was God's earth not vast enough for you to emigrate in it?\" These-their refuge is Hell. What a wretched retreat!", "translation_id": "Sesungguhnya orang-orang yang diwafatkan malaikat dalam keadaan menganiaya diri sendiri, (kepada mereka) malaikat bertanya: \"Dalam keadaan bagaimana kamu ini?\". Mereka menjawab: \"Adalah kami orang-orang yang tertindas di negeri (Mekah)\". Para malaikat berkata: \"Bukankah bumi Allah itu luas, sehingga kamu dapat berhijrah di bumi itu?\". Orang-orang itu tempatnya neraka Jahannam, dan Jahannam itu seburuk-buruk tempat kembali,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 98, "text": "إِلَّا ٱلۡمُسۡتَضۡعَفِینَ مِنَ ٱلرِّجَالِ وَٱلنِّسَاۤءِ وَٱلۡوِلۡدَ ٰنِ لَا یَسۡتَطِیعُونَ حِیلَةࣰ وَلَا یَهۡتَدُونَ سَبِیلࣰا ۝٩٨", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "ويعذر من ذاك المصير العجزة من الرجال والنساء والصغار الذين لا يقدرون على دفع القهر والظلم عنهم، ولا يعرفون طريقًا يخلصهم مما هم فيه من المعاناة.", "isBasmala": false, "translation_en": "Except for the weak among men, and women, and children who have no means to act, and no means to find a way out.", "translation_id": "kecuali mereka yang tertindas baik laki-laki atau wanita ataupun anak-anak yang tidak mampu berdaya upaya dan tidak mengetahui jalan (untuk hijrah),", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 99, "text": "فَأُو۟لَـٰۤىِٕكَ عَسَى ٱللَّهُ أَن یَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورࣰا ۝٩٩", "juz": 5, "hizb": "(* ح 10*)", "tafsir": "فهؤلاء الضعفاء هم الذين يُرجى لهم من الله تعالى العفو؛ لعلمه تعالى بحقيقة أمرهم. وكان الله عفوًا غفورًا.", "isBasmala": false, "translation_en": "These-God may well pardon them. God is Pardoning and Forgiving.", "translation_id": "mereka itu, mudah-mudahan Allah memaafkannya. Dan adalah Allah Maha Pemaaf lagi Maha Pengampun.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 100, "text": "۞ وَمَن یُهَاجِرۡ فِی سَبِیلِ ٱللَّهِ یَجِدۡ فِی ٱلۡأَرۡضِ مُرَ ٰغَمࣰا كَثِیرࣰا وَسَعَةࣰۚ وَمَن یَخۡرُجۡ مِنۢ بَیۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ یُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا ۝١٠٠", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "ومَن يخرج من أرض الشرك إلى أرض الإسلام فرارًا بدينه، راجيًا فضل ربه، قاصدًا نصرة دينه، يجد في الأرض مكانًا ومتحولا ينعم فيه بما يكون سببًا في قوته وذلة أعدائه، مع السعة في رزقه وعيشه، ومن يخرج من بيته قاصدًا نصرة دين الله ورسوله صلى الله عليه وسلم، وإعلاء كلمة الله، ثم يدركه الموت قبل بلوغه مقصده، فقد ثبت له جزاء عمله على الله، فضلا منه وإحسانًا. وكان الله غفورًا رحيمًا بعباده.", "isBasmala": false, "translation_en": "Anyone who emigrates for the sake of God will find on earth many places of refuge, and plentitude. Anyone who leaves his home, emigrating to God and His Messenger, and then is overtaken by death, his compensation falls on God. God is Forgiver, Most Merciful.", "translation_id": "Barangsiapa berhijrah di jalan Allah, niscaya mereka mendapati di muka bumi ini tempat hijrah yang luas dan rezeki yang banyak. Barangsiapa keluar dari rumahnya dengan maksud berhijrah kepada Allah dan Rasul-Nya, kemudian kematian menimpanya (sebelum sampai ke tempat yang dituju), maka sungguh telah tetap pahalanya di sisi Allah. Dan adalah Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 101, "text": "وَإِذَا ضَرَبۡتُمۡ فِی ٱلۡأَرۡضِ فَلَیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَن تَقۡصُرُوا۟ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن یَفۡتِنَكُمُ ٱلَّذِینَ كَفَرُوۤا۟ۚ إِنَّ ٱلۡكَـٰفِرِینَ كَانُوا۟ لَكُمۡ عَدُوࣰّا مُّبِینࣰا ۝١٠١", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "وإذا سافرتم -أيها المؤمنون- في أرض الله، فلا حرج ولا إثم عليكم في قصر الصلاة إن خفتم من عدوان الكفار عليكم في حال صلاتكم، وكانت غالب أسفار المسلمين في بدء الإسلام مخوفة، والقصر رخصة في السفر حال الأمن أو الخوف. إن الكافرين مجاهرون لكم بعداوتهم، فاحذروهم.", "isBasmala": false, "translation_en": "When you travel in the land, there is no blame on you for shortening the prayers, if you fear that the disbelievers may harm you. The disbelievers are your manifest enemies.", "translation_id": "Dan apabila kamu bepergian di muka bumi, maka tidaklah mengapa kamu men-qashar sembahyang(mu), jika kamu takut diserang orang-orang kafir. Sesungguhnya orang-orang kafir itu adalah musuh yang nyata bagimu.", "manzil": 1, "manzil_display": ""}], "95": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 102, "text": "وَإِذَا كُنتَ فِیهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَاۤىِٕفَةࣱ مِّنۡهُم مَّعَكَ وَلۡیَأۡخُذُوۤا۟ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُوا۟ فَلۡیَكُونُوا۟ مِن وَرَاۤىِٕكُمۡ وَلۡتَأۡتِ طَاۤىِٕفَةٌ أُخۡرَىٰ لَمۡ یُصَلُّوا۟ فَلۡیُصَلُّوا۟ مَعَكَ وَلۡیَأۡخُذُوا۟ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِینَ كَفَرُوا۟ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَیَمِیلُونَ عَلَیۡكُم مَّیۡلَةࣰ وَ ٰحِدَةࣰۚ وَلَا جُنَاحَ عَلَیۡكُمۡ إِن كَانَ بِكُمۡ أَذࣰى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰۤ أَن تَضَعُوۤا۟ أَسۡلِحَتَكُمۡۖ وَخُذُوا۟ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَـٰفِرِینَ عَذَابࣰا مُّهِینࣰا ۝١٠٢", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "وإذا كنت -أيها النبي- في ساحة القتال، فأردت أن تصلي بهم، فلتقم جماعة منهم معك للصلاة، وليأخذوا سلاحهم، فإذا سجد هؤلاء فلتكن الجماعة الأخرى من خلفكم في مواجهة عدوكم، وتتم الجماعة الأولى ركعتهم الثانية ويُسلِّمون، ثم تأتي الجماعة الأخرى التي لم تبدأ الصلاة فليأتموا بك في ركعتهم الأولى، ثم يكملوا بأنفسهم ركعتهم الثانية، وليحذروا مِن عدوهم وليأخذوا أسلحتهم. ودَّ الجاحدون لدين الله أن تغفُلوا عن سلاحكم وزادكم؛ ليحملوا عليكم حملة واحلة فيقضوا عليكم، ولا إثم عليكم حيننذ إن كان بكم أذى من مطر، أو كنتم في حال مرض، أن تتركوا أسلحتكم، مع أخذ الحذر. إن الله تعالى أعدَّ للجاحدين لدينه عذابًا يهينهم، ويخزيهم.", "isBasmala": false, "translation_en": "When you are among them, and you stand to lead them in prayer, let a group of them stand with you, and let them hold their weapons. Then, when they have done their prostrations, let them withdraw to the rear, and let another group, that have not prayed yet, come forward and pray with you; and let them take their precautions and their weapons. Those who disbelieve would like you to neglect your weapons and your equipment, so they can attack you in a single assault. You commit no error, if you are hampered by rain or are sick, by putting down your weapons; but take precautions. Indeed, God has prepared for the disbelievers a demeaning punishment.", "translation_id": "Dan apabila kamu berada di tengah-tengah mereka (sahabatmu) lalu kamu hendak mendirikan shalat bersama-sama mereka, maka hendaklah segolongan dari mereka berdiri (shalat) besertamu dan menyandang senjata, kemudian apabila mereka (yang shalat besertamu) sujud (telah menyempurnakan serakaat), maka hendaklah mereka pindah dari belakangmu (untuk menghadapi musuh) dan hendaklah datang golongan yang kedua yang belum bersembahyang, lalu bersembahyanglah mereka denganmu], dan hendaklah mereka bersiap siaga dan menyandang senjata. Orang-orang kafir ingin supaya kamu lengah terhadap senjatamu dan harta bendamu, lalu mereka menyerbu kamu dengan sekaligus. Dan tidak ada dosa atasmu meletakkan senjata-senjatamu, jika kamu mendapat sesuatu kesusahan karena hujan atau karena kamu memang sakit; dan siap siagalah kamu. Sesungguhnya Allah telah menyediakan azab yang menghinakan bagi orang-orang kafir itu.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 103, "text": "فَإِذَا قَضَیۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُوا۟ ٱللَّهَ قِیَـٰمࣰا وَقُعُودࣰا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِیمُوا۟ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِینَ كِتَـٰبࣰا مَّوۡقُوتࣰا ۝١٠٣", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "فإذا أدَّيتم الصلاة، فأديموا ذكر الله في جميع أحوالكم، فإذا زال الخوف فأدُّوا الصلاة كاملة، ولا تفرِّطوا فيها فإنها واجبة في أوقات معلومة في الشرع.", "isBasmala": false, "translation_en": "When you have completed the prayer, remember God, standing, or sitting, or on your sides. And when you feel secure, perform the prayer. The prayer is obligatory for believers at specific times.", "translation_id": "Maka apabila kamu telah menyelesaikan shalat(mu), ingatlah Allah di waktu berdiri, di waktu duduk dan di waktu berbaring. Kemudian apabila kamu telah merasa aman, maka dirikanlah shalat itu (sebagaimana biasa). Sesungguhnya shalat itu adalah fardhu yang ditentukan waktunya atas orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 104, "text": "وَلَا تَهِنُوا۟ فِی ٱبۡتِغَاۤءِ ٱلۡقَوۡمِۖ إِن تَكُونُوا۟ تَأۡلَمُونَ فَإِنَّهُمۡ یَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا یَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمًا ۝١٠٤", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "ولا تضعفوا في طلب عدوكم وقتاله، إن تكونوا تتألمون من القتال وآثاره، فأعداؤكم كذلك يتألمون منه أشد الألم، ومع ذلك لا يكفون عن قتالكم، فأنتم أولى بذلك منهم، لما ترجونه من الثواب والنصر والتأييد، وهم لا يرجون ذلك. وكان الله عليمًا بكل أحوالكم، حكيمًا في أمره وتدبيره.", "isBasmala": false, "translation_en": "And do not falter in the pursuit of the enemy. If you are aching, they are aching as you are aching, but you expect from God what they cannot expect. God is Knowledgeable and Wise.", "translation_id": "Janganlah kamu berhati lemah dalam mengejar mereka (musuhmu). Jika kamu menderita kesakitan, maka sesungguhnya merekapun menderita kesakitan (pula), sebagaimana kamu menderitanya, sedang kamu mengharap dari pada Allah apa yang tidak mereka harapkan. Dan adalah Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 105, "text": "إِنَّاۤ أَنزَلۡنَاۤ إِلَیۡكَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَیۡنَ ٱلنَّاسِ بِمَاۤ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَاۤىِٕنِینَ خَصِیمࣰا ۝١٠٥", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "إنا أنزلنا إليك -أيها الرسول- القرآن مشتملا على الحق؛ لتفصل بين الناس جميعًا بما أوحى الله إليك، وبَصَّرك به، فلا تكن للذين يخونون أنفسهم -بكتمان الحق- مدافعًا عنهم بما أيدوه لك من القول المخالف للحقيقة.", "isBasmala": false, "translation_en": "We have revealed to you the Scripture, with the truth, so that you judge between people in accordance with what God has shown you. And do not be an advocate for the traitors.", "translation_id": "Sesungguhnya Kami telah menurunkan kitab kepadamu dengan membawa kebenaran, supaya kamu mengadili antara manusia dengan apa yang telah Allah wahyukan kepadamu, dan janganlah kamu menjadi penantang (orang yang tidak bersalah), karena (membela) orang-orang yang khianat,", "manzil": 1, "manzil_display": ""}], "96": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 106, "text": "وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِیمࣰا ۝١٠٦", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "واطلب من الله تعالى المغفرة في جميع أحوالك، إن الله تعالى كان غفورًا لمن يرجو فضله ونوال مغفرته، رحيمًا به.", "isBasmala": false, "translation_en": "And ask God for forgiveness. God is Forgiver and Merciful.", "translation_id": "dan mohonlah ampun kepada Allah. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 107, "text": "وَلَا تُجَـٰدِلۡ عَنِ ٱلَّذِینَ یَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا یُحِبُّ مَن كَانَ خَوَّانًا أَثِیمࣰا ۝١٠٧", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "ولا تدافع عن الذين يخونون أنفسهم بمعصية الله. إن الله -سبحانه- لا يحب مَن عَظُمَتْ خيانته، وكثر ذنبه.", "isBasmala": false, "translation_en": "And do not argue on behalf of those who deceive themselves. God does not love the deceitful sinner.", "translation_id": "Dan janganlah kamu berdebat (untuk membela) orang-orang yang mengkhianati dirinya. Sesungguhnya Allah tidak menyukai orang-orang yang selalu berkhianat lagi bergelimang dosa,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 108, "text": "یَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا یَسۡتَخۡفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ یُبَیِّتُونَ مَا لَا یَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ ٱللَّهُ بِمَا یَعۡمَلُونَ مُحِیطًا ۝١٠٨", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "يستترون من الناس خوفًا من اطلاعهم على أعمالهم السيئة، ولا يستترون من الله تعالى ولا يستحيون منه، وهو عزَّ شأنه معهم بعلمه، مطلع عليهم حين يدبِّرون -ليلا- ما لا يرضى من القول، وكان الله -تعالى- محيطًا بجميع أقوالهم وأفعالهم، لا يخفى عليه منها شيء.", "isBasmala": false, "translation_en": "They hide from the people, but they cannot hide from God. He is with them, as they plot by night with words He does not approve. God comprehends what they do.", "translation_id": "mereka bersembunyi dari manusia, tetapi mereka tidak bersembunyi dari Allah, padahal Allah beserta mereka, ketika pada suatu malam mereka menetapkan keputusan rahasia yang Allah tidak redlai. Dan adalah Allah Maha Meliputi (ilmu-Nya) terhadap apa yang mereka kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 109, "text": "هَـٰۤأَنتُمۡ هَـٰۤؤُلَاۤءِ جَـٰدَلۡتُمۡ عَنۡهُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا فَمَن یُجَـٰدِلُ ٱللَّهَ عَنۡهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ أَم مَّن یَكُونُ عَلَیۡهِمۡ وَكِیلࣰا ۝١٠٩", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "ها أنتم -أيها المؤمنون- قد حاججتم عن هؤلاء الخائنين لأنفسهم في هذه الحياة الدنيا، فمن يحاجج الله تعالى عنهم يوم البعث والحساب؟ ومن ذا الذي يكون على هؤلاء الخائنين وكيلا يوم القيامة؟", "isBasmala": false, "translation_en": "There you are, arguing on their behalf in the present life, but who will argue with God on their behalf on the Day of Resurrection? Or who will be their representative?", "translation_id": "Beginilah kamu, kamu sekalian adalah orang-orang yang berdebat untuk (membela) mereka dalam kehidupan dunia ini. Maka siapakah yang akan mendebat Allah untuk (membela) mereka pada hari kiamat? Atau siapakah yang menjadi pelindung mereka (terhadap siksa Allah)?", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 110, "text": "وَمَن یَعۡمَلۡ سُوۤءًا أَوۡ یَظۡلِمۡ نَفۡسَهُۥ ثُمَّ یَسۡتَغۡفِرِ ٱللَّهَ یَجِدِ ٱللَّهَ غَفُورࣰا رَّحِیمࣰا ۝١١٠", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "ومن يُقْدِمْ على عمل سيِّئ قبيح، أو يظلم نفسه بارتكاب ما يخالف حكم الله وشرعه، ثم يرجع إلى الله نادمًا على ما عمل، راجيًا مغفرته وستر ذنبه، يجد الله تعالى غفورًا له، رحيمًا به.", "isBasmala": false, "translation_en": "Whoever commits evil, or wrongs his soul, then implores God for forgiveness, will find God Forgiving and Merciful.", "translation_id": "Dan barangsiapa yang mengerjakan kejahatan dan menganiaya dirinya, kemudian ia mohon ampun kepada Allah, niscaya ia mendapati Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 111, "text": "وَمَن یَكۡسِبۡ إِثۡمࣰا فَإِنَّمَا یَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا ۝١١١", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "ومن يعمد إلى ارتكاب ذنب فإنما يضر بذلك نفسه وحدها، وكان الله تعالى عليمًا بحقيقة أمر عباده، حكيمًا فيما يقضي به بين خلقه.", "isBasmala": false, "translation_en": "And Whoever earns a sin, earns it against himself. God is Aware and Wise.", "translation_id": "Barangsiapa yang mengerjakan dosa, maka sesungguhnya ia mengerjakannya untuk (kemudharatan) dirinya sendiri. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 112, "text": "وَمَن یَكۡسِبۡ خَطِیۤـَٔةً أَوۡ إِثۡمࣰا ثُمَّ یَرۡمِ بِهِۦ بَرِیۤـࣰٔا فَقَدِ ٱحۡتَمَلَ بُهۡتَـٰنࣰا وَإِثۡمࣰا مُّبِینࣰا ۝١١٢", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "ومن يعمل خطيئة بغير عمد، أو يرتكب ذنبًا متعمدًا ثم يقذف بما ارتكبه نفسًا بريئة لا جناية لها، فقد تحمَّل كذبًا وذنبًا بيّنا.", "isBasmala": false, "translation_en": "And whoever commits a mistake, or a sin, and then blames it on an innocent person, has taken a slander and a clear sin.", "translation_id": "Dan barangsiapa yang mengerjakan kesalahan atau dosa, kemudian dituduhkannya kepada orang yang tidak bersalah, maka sesungguhnya ia telah berbuat suatu kebohongan dan dosa yang nyata.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 113, "text": "وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّاۤىِٕفَةࣱ مِّنۡهُمۡ أَن یُضِلُّوكَ وَمَا یُضِلُّونَ إِلَّاۤ أَنفُسَهُمۡۖ وَمَا یَضُرُّونَكَ مِن شَیۡءࣲۚ وَأَنزَلَ ٱللَّهُ عَلَیۡكَ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَیۡكَ عَظِیمࣰا ۝١١٣", "juz": 5, "hizb": "(*¼ ح 10*)", "tafsir": "ولولا أن الله تعالى قد مَنَّ عليك -أيها الرسول- ورحمك بنعمة النبوة، فعصمك بتوفيقه بما أوحى إليك، لعزمت جماعة من الذين يخونون أنفسهم أن يُزِلُّوكَ عن طريق الحق، وما يُزِلُّونَ بذلك إلا أنفسهم، وما يقدرون على إيذائك لعصمة الله لك، وأنزل الله عليك القرآن والسنة المبينة له، وهداك إلى علم ما لم تكن تعلمه مِن قبل، وكان ما خصَّك الله به من فضلٍ أمرًا عظيمًا.", "isBasmala": false, "translation_en": "Were it not for God's grace towards you, and His mercy, a faction of them would have managed to mislead you. But they only mislead themselves, and they cannot harm you in any way. God has revealed to you the Scripture and wisdom, and has taught you what you did not know. God's goodness towards you is great.", "translation_id": "Sekiranya bukan karena karunia Allah dan rahmat-Nya kepadamu, tentulah segolongan dari mereka berkeinginan keras untuk menyesatkanmu. Tetapi mereka tidak menyesatkan melainkan dirinya sendiri, dan mereka tidak dapat membahayakanmu sedikitpun kepadamu. Dan (juga karena) Allah telah menurunkan Kitab dan hikmah kepadamu, dan telah mengajarkan kepadamu apa yang belum kamu ketahui. Dan adalah karunia Allah sangat besar atasmu.", "manzil": 1, "manzil_display": ""}], "97": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 114, "text": "۞ لَّا خَیۡرَ فِی كَثِیرࣲ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَـٰحِۭ بَیۡنَ ٱلنَّاسِۚ وَمَن یَفۡعَلۡ ذَ ٰلِكَ ٱبۡتِغَاۤءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِیهِ أَجۡرًا عَظِیمࣰا ۝١١٤", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "لا نفع في كثير من كلام الناس سرّاً فيما بينهم، إلا إذا كان حديثًا داعيًا إلى بذل المعروف من الصدقة، أو الكلمة الطيبة، أو التوفيق بين الناس، ومن يفعل تلك الأمور طلبًا لرضا الله تعالى راجيًا ثوابه، فسوف نؤتيه ثوابًا جزيلا واسعًا.", "isBasmala": false, "translation_en": "There is no good in much of their private counsels, except for him who advocates charity, or kindness, or reconciliation between people. Whoever does that, seeking God's approval, We will give him a great compensation.", "translation_id": "Tidak ada kebaikan pada kebanyakan bisikan-bisikan mereka, kecuali bisikan-bisikan dari orang yang menyuruh (manusia) memberi sedekah, atau berbuat ma'ruf, atau mengadakan perdamaian di antara manusia. Dan barangsiapa yang berbuat demikian karena mencari keridhaan Allah, maka kelak Kami memberi kepadanya pahala yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 115, "text": "وَمَن یُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَیَّنَ لَهُ ٱلۡهُدَىٰ وَیَتَّبِعۡ غَیۡرَ سَبِیلِ ٱلۡمُؤۡمِنِینَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَاۤءَتۡ مَصِیرًا ۝١١٥", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "ومن يخالف الرسول صلى الله عليه وسلم من بعد ما ظهر له الحق، ويسلك طريقًا غير طريق المؤمنين، وما هم عليه من الحق، نتركه وما توجَّه إليه، فلا نوفقه للخير، وندخله نار جهنم يقاسي حرَّها، وبئس هذا المرجع والمآل.", "isBasmala": false, "translation_en": "Whoever makes a breach with the Messenger, after the guidance has become clear to him, and follows other than the path of the believers, We will direct him in the direction he has chosen, and commit him to Hell-what a terrible destination!", "translation_id": "Dan barangsiapa yang menentang Rasul sesudah jelas kebenaran baginya, dan mengikuti jalan yang bukan jalan orang-orang mukmin, Kami biarkan ia leluasa terhadap kesesatan yang telah dikuasainya itu dan Kami masukkan ia ke dalam Jahannam, dan Jahannam itu seburuk-buruk tempat kembali.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 116, "text": "إِنَّ ٱللَّهَ لَا یَغۡفِرُ أَن یُشۡرَكَ بِهِۦ وَیَغۡفِرُ مَا دُونَ ذَ ٰلِكَ لِمَن یَشَاۤءُۚ وَمَن یُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَـٰلَۢا بَعِیدًا ۝١١٦", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "إن الله تعالى لا يغفر أن يشرك به، ويغفر ما دون الشرك من الذنوب لمن يشاء من عباده. ومن يجعل لله تعالى الواحد الأحد شريكًا من خلقه، فقد بَعُدَ عن الحق بعدًا كبيرًا.", "isBasmala": false, "translation_en": "God will not forgive that partners be associated with Him; but will forgive anything less than that, to whomever He wills. Anyone who ascribes partners to God has strayed into far error.", "translation_id": "Sesungguhnya Allah tidak mengampuni dosa mempersekutukan (sesuatu) dengan Dia, dan dia mengampuni dosa yang selain syirik bagi siapa yang dikehendaki-Nya. Barangsiapa yang mempersekutukan (sesuatu) dengan Allah, maka sesungguhnya ia telah tersesat sejauh-jauhnya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 117, "text": "إِن یَدۡعُونَ مِن دُونِهِۦۤ إِلَّاۤ إِنَـٰثࣰا وَإِن یَدۡعُونَ إِلَّا شَیۡطَـٰنࣰا مَّرِیدࣰا ۝١١٧", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "ما يعبد المشركون من دون الله تعالى إلا أوثانًا لا تنفع ولا تضر، وما يعبدون إلا شيطانًا متمردًا على الله، بلغ في الفساد والإفساد حدّاً كبيرًا.", "isBasmala": false, "translation_en": "They invoke in His stead only females. In fact, they invoke none but a rebellious devil.", "translation_id": "Yang mereka sembah selain Allah itu, tidak lain hanyalah berhala, dan (dengan menyembah berhala itu) mereka tidak lain hanyalah menyembah syaitan yang durhaka,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 118, "text": "لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ نَصِیبࣰا مَّفۡرُوضࣰا ۝١١٨", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "طرده الله تعالى من رحمته. وقال الشيطان: لأتخذن مِن عبادك جزءًا معلومًا في إغوائهم قولا وعملا.", "isBasmala": false, "translation_en": "God has cursed him. And he said, \"I will take to myself my due share of Your servants.\"", "translation_id": "yang dilaknati Allah dan syaitan itu mengatakan: \"Saya benar-benar akan mengambil dari hamba-hamba Engkau bahagian yang sudah ditentukan (untuk saya),", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 119, "text": "وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّیَنَّهُمۡ وَلَـَٔامُرَنَّهُمۡ فَلَیُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَـٰمِ وَلَـَٔامُرَنَّهُمۡ فَلَیُغَیِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن یَتَّخِذِ ٱلشَّیۡطَـٰنَ وَلِیࣰّا مِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانࣰا مُّبِینࣰا ۝١١٩", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "ولأصرفَنَّ مَن تبعني منهم عن الحق، ولأعِدَنَّهم بالأماني الكاذبة، ولأدعونَّهم إلى تقطيع آذان الأنعام وتشقيقها لما أزينه لهم من الباطل، ولأدعونَّهم إلى تغيير خلق الله في الفطرة، وهيئة ما عليه الخلق. ومن يستجب للشيطان ويتخذه ناصرًا له من دون الله القوي العزيز، فقد هلك هلاكًا بيِّنًا.", "isBasmala": false, "translation_en": "\"And I will mislead them, and I will entice them, and I will prompt them to slit the ears of cattle, and I will prompt them to alter the creation of God.\" Whoever takes Satan as a lord, instead of God, has surely suffered a profound loss.", "translation_id": "dan aku benar-benar akan menyesatkan mereka, dan akan membangkitkan angan-angan kosong pada mereka dan menyuruh mereka (memotong telinga-telinga binatang ternak), lalu mereka benar-benar memotongnya, dan akan aku suruh mereka (mengubah ciptaan Allah), lalu benar-benar mereka meubahnya\". Barangsiapa yang menjadikan syaitan menjadi pelindung selain Allah, maka sesungguhnya ia menderita kerugian yang nyata.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 120, "text": "یَعِدُهُمۡ وَیُمَنِّیهِمۡۖ وَمَا یَعِدُهُمُ ٱلشَّیۡطَـٰنُ إِلَّا غُرُورًا ۝١٢٠", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "يعد الشيطان أتباعه بالوعود الكاذبة، ويغريهم بالأماني الباطلة الخادعة، وما يَعِدهم إلا خديعة لا صحة لها، ولا دليل عليها.", "isBasmala": false, "translation_en": "He promises them, and he raises their expectations, but Satan promises them nothing but delusions.", "translation_id": "Syaitan itu memberikan janji-janji kepada mereka dan membangkitkan angan-angan kosong pada mereka, padahal syaitan itu tidak menjanjikan kepada mereka selain dari tipuan belaka.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 121, "text": "أُو۟لَـٰۤىِٕكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا یَجِدُونَ عَنۡهَا مَحِیصࣰا ۝١٢١", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "أولئك مآلهم جهنم، ولا يجدون عنها معدلا ولا ملجأً.", "isBasmala": false, "translation_en": "These-their place is Hell, and they will find no escape from it.", "translation_id": "Mereka itu tempatnya Jahannam dan mereka tidak memperoleh tempat lari dari padanya.", "manzil": 1, "manzil_display": ""}], "98": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 122, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ وَعۡدَ ٱللَّهِ حَقࣰّاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِیلࣰا ۝١٢٢", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "والذين صَدَقوا في إيمانهم بالله تعالى، وأتبعوا الإيمان بالأعمال الصالحة سيدخلهم الله -بفضله- جنات تجري من تحت أشجارها الأنهار ماكثين فيها أبدًا، وعدا من الله تعالى الذي لا يخلف وعده. ولا أحد أصدق من الله تعالى في قوله ووعده.", "isBasmala": false, "translation_en": "But as for those who believe and do righteous deeds, We will admit them into gardens beneath which rivers flow, where they will abide forever. The promise of God is true-and who is more truthful in speech than God?", "translation_id": "Orang-orang yang beriman dan mengerjakan amalan saleh, kelak akan Kami masukkan ke dalam surga yang mengalir sungai-sungai di dalamnya, mereka kekal di dalamnya selama-lamanya. Allah telah membuat suatu janji yang benar. Dan siapakah yang lebih benar perkataannya dari pada Allah?", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 123, "text": "لَّیۡسَ بِأَمَانِیِّكُمۡ وَلَاۤ أَمَانِیِّ أَهۡلِ ٱلۡكِتَـٰبِۗ مَن یَعۡمَلۡ سُوۤءࣰا یُجۡزَ بِهِۦ وَلَا یَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِیࣰّا وَلَا نَصِیرࣰا ۝١٢٣", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "لا يُنال هذا الفضل العظيم بالأماني التي تتمنونها أيها المسلمون، ولا بأماني أهل الكتاب من اليهود والنصارى، وإنما يُنال بالإيمان الصادق بالله تعالى، وإحسان العمل الذي يرضيه. ومن يعمل عملا سيئًا يجز به، ولا يجد له سوى الله تعالى وليّاً يتولى أمره وشأنه، ولا نصيرًا ينصره، ويدفع عنه سوء العذاب.", "isBasmala": false, "translation_en": "It is not in accordance with your wishes, nor in accordance with the wishes of the People of the Scripture. Whoever works evil will pay for it, and will not find for himself, besides God, any protector or savior.", "translation_id": "(Pahala dari Allah) itu bukanlah menurut angan-anganmu yang kosong dan tidak (pula) menurut angan-angan Ahli Kitab. Barangsiapa yang mengerjakan kejahatan, niscaya akan diberi pembalasan dengan kejahatan itu dan ia tidak mendapat pelindung dan tidak (pula) penolong baginya selain dari Allah.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 124, "text": "وَمَن یَعۡمَلۡ مِنَ ٱلصَّـٰلِحَـٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ فَأُو۟لَـٰۤىِٕكَ یَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا یُظۡلَمُونَ نَقِیرࣰا ۝١٢٤", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "ومن يعمل من الأعمال الصالحة من ذكر أو أنثى، وهو مؤمن بالله تعالى وبما أنزل من الحق، فأولئك يدخلهم الله الجنة دار النعيم المقيم، ولا يُنْقَصون من ثواب أعمالهم شيئًا، ولو كان مقدار النقرة في ظهر النواة.", "isBasmala": false, "translation_en": "But whoever works righteousness, whether male or female, and is a believer-those will enter Paradise, and will not be wronged a whit.", "translation_id": "Barangsiapa yang mengerjakan amal-amal saleh, baik laki-laki maupun wanita sedang ia orang yang beriman, maka mereka itu masuk ke dalam surga dan mereka tidak dianiaya walau sedikitpun.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 125, "text": "وَمَنۡ أَحۡسَنُ دِینࣰا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنࣱ وَٱتَّبَعَ مِلَّةَ إِبۡرَ ٰهِیمَ حَنِیفࣰاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَ ٰهِیمَ خَلِیلࣰا ۝١٢٥", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "لا أحد أحسن دينًا ممن انقاد بقلبه وسائر جوارحه لله تعالى وحده، وهو محسن، واتبع دين إبراهيم وشرعه، مائلا عن العقائد الفاسدة والشرائع الباطلة. وقد اصطفى الله إبراهيم -عليه الصلاة والسلام- واتخذه صفيّاً من بين سائر خلقه. وفي هذه الآية، إثبات صفة الخُلّة لله -تعالى- وهي أعلى مقامات المحبة، والاصطفاء.", "isBasmala": false, "translation_en": "And who is better in religion than he who submits himself wholly to God, and is a doer of good, and follows the faith of Abraham the Monotheist? God has chosen Abraham for a friend.", "translation_id": "Dan siapakah yang lebih baik agamanya dari pada orang yang ikhlas menyerahkan dirinya kepada Allah, sedang diapun mengerjakan kebaikan, dan ia mengikuti agama Ibrahim yang lurus? Dan Allah mengambil Ibrahim menjadi kesayangan-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 126, "text": "وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَیۡءࣲ مُّحِیطࣰا ۝١٢٦", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "ولله جميع ما في هذا الكون من المخلوقات، فهي ملك له تعالى وحده. وكان الله تعالى بكل شيء محيطًا، لا يخفى عليه شيء من أمور خلقه.", "isBasmala": false, "translation_en": "To God belongs what is in the heavens and what is on earth, and God encompasses everything.", "translation_id": "Kepunyaan Allah-lah apa yang di langit dan apa yang di bumi, dan adalah (pengetahuan) Allah Maha Meliputi segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 127, "text": "وَیَسۡتَفۡتُونَكَ فِی ٱلنِّسَاۤءِۖ قُلِ ٱللَّهُ یُفۡتِیكُمۡ فِیهِنَّ وَمَا یُتۡلَىٰ عَلَیۡكُمۡ فِی ٱلۡكِتَـٰبِ فِی یَتَـٰمَى ٱلنِّسَاۤءِ ٱلَّـٰتِی لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ وَٱلۡمُسۡتَضۡعَفِینَ مِنَ ٱلۡوِلۡدَ ٰنِ وَأَن تَقُومُوا۟ لِلۡیَتَـٰمَىٰ بِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُوا۟ مِنۡ خَیۡرࣲ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِیمࣰا ۝١٢٧", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "يطلب الناس منك -أيها النبي- أن تبين لهم ما أشكل عليهم فَهْمُه من قضايا النساء وأحكامهن، قل الله تعالى يبيِّن لكم أمورهن، وما يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تعطونهن ما فرض الله تعالى لهن من المهر والميراث وغير ذلك من الحقوق، وتحبون نكاحهن أو ترغبون عن نكاحهن، ويبيِّن الله لكم أمر الضعفاء من الصغار، ووجوب القيام لليتامى بالعدل وترك الجور عليهم في حقوقهم. وما تفعلوا من خير فإن الله تعالى كان به عليمًا، لا يخفى عليه شيء منه ولا من غيره.", "isBasmala": false, "translation_en": "They ask you for a ruling about women. Say, \"God gives you a ruling about them, and so does what is stated to you in the Book about widowed women from whom you withhold what is decreed for them, yet you desire to marry them, and about helpless children: that you should treat the orphans fairly.\" Whatever good you do, God knows it.", "translation_id": "Dan mereka minta fatwa kepadamu tentang para wanita. Katakanlah: \"Allah memberi fatwa kepadamu tentang mereka, dan apa yang dibacakan kepadamu dalam Al Quran (juga memfatwakan) tentang para wanita yatim yang kamu tidak memberikan kepada mereka apa yang ditetapkan untuk mereka, sedang kamu ingin mengawini mereka dan tentang anak-anak yang masih dipandang lemah. Dan (Allah menyuruh kamu) supaya kamu mengurus anak-anak yatim secara adil. Dan kebajikan apa saja yang kamu kerjakan, maka sesungguhnya Allah adalah Maha Mengetahuinya.", "manzil": 1, "manzil_display": ""}], "99": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 128, "text": "وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضࣰا فَلَا جُنَاحَ عَلَیۡهِمَاۤ أَن یُصۡلِحَا بَیۡنَهُمَا صُلۡحࣰاۚ وَٱلصُّلۡحُ خَیۡرࣱۗ وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِیرࣰا ۝١٢٨", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "وإن علمت امرأة من زوجها ترفعًا عنها، وتعاليًا عليها أو انصرافًا عنها فلا إثم عليهما أن يتصالحا على ما تطيب به نفوسهما من القسمة أو النفقة، والصلح أولى وأفضل. وجبلت النفوس على الشح والبخل. وإن تحسنوا معاملة زوجاتكم وتخافوا الله فيهن، فإن الله كان بما تعملون من ذلك وغيره عالمًا لا يخفى عليه شيء، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "If a woman fears maltreatment or desertion from her husband, there is no fault in them if they reconcile their differences, for reconciliation is best. Souls are prone to avarice; yet if you do what is good, and practice piety-God is Cognizant of what you do.", "translation_id": "Dan jika seorang wanita khawatir akan nusyuz atau sikap tidak acuh dari suaminya, maka tidak mengapa bagi keduanya mengadakan perdamaian yang sebenar-benarnya, dan perdamaian itu lebih baik (bagi mereka) walaupun manusia itu menurut tabiatnya kikir. Dan jika kamu bergaul dengan isterimu secara baik dan memelihara dirimu (dari nusyuz dan sikap tak acuh), maka sesungguhnya Allah adalah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 129, "text": "وَلَن تَسۡتَطِیعُوۤا۟ أَن تَعۡدِلُوا۟ بَیۡنَ ٱلنِّسَاۤءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِیلُوا۟ كُلَّ ٱلۡمَیۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُوا۟ وَتَتَّقُوا۟ فَإِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِیمࣰا ۝١٢٩", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "ولن تقدروا -أيها الرجال- على تحقيق العدل التام بين النساء في المحبة وميل القلب، مهما بذلتم في ذلك من الجهد، فلا تعرضوا عن المرغوب عنها كل الإعراض، فتتركوها كالمرأة التي ليست بذات زوج ولا هي مطلقة فتأثموا. وإن تصلحوا أعمالكم فتعدلوا في قَسْمكم بين زوجاتكم، وتراقبوا الله تعالى وتخشوه فيهن، فإن الله تعالى كان غفورًا لعباده، رحيمًا بهم.", "isBasmala": false, "translation_en": "You will not be able to treat women with equal fairness, no matter how much you desire it. But do not be so biased as to leave another suspended. If you make amends, and act righteously-God is Forgiving and Merciful.", "translation_id": "Dan kamu sekali-kali tidak akan dapat berlaku adil di antara isteri-isteri(mu), walaupun kamu sangat ingin berbuat demikian, karena itu janganlah kamu terlalu cenderung (kepada yang kamu cintai), sehingga kamu biarkan yang lain terkatung-katung. Dan jika kamu mengadakan perbaikan dan memelihara diri (dari kecurangan), maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 130, "text": "وَإِن یَتَفَرَّقَا یُغۡنِ ٱللَّهُ كُلࣰّا مِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَ ٰسِعًا حَكِیمࣰا ۝١٣٠", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "وإن وقعت الفرقة بين الرجل وامرأته، فإن الله تعالى يغني كلا منهما من فضله وسعته؛ فإنه سبحانه وتعالى واسع الفضل والمنة، حكيم فيما يقضي به بين عباده.", "isBasmala": false, "translation_en": "And if they separate, God will enrich each from His abundance. God is Bounteous and Wise.", "translation_id": "Jika keduanya bercerai, maka Allah akan memberi kecukupan kepada masing-masingnya dari limpahan karunia-Nya. Dan adalah Allah Maha Luas (karunia-Nya) lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 131, "text": "وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّیۡنَا ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلِكُمۡ وَإِیَّاكُمۡ أَنِ ٱتَّقُوا۟ ٱللَّهَۚ وَإِن تَكۡفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِیًّا حَمِیدࣰا ۝١٣١", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "ولله ملك ما في السموات وما في الأرض وما بينهما. ولقد عهدنا إلى الذين أُعطوا الكتاب من قبلكم من اليهود والنصارى، وعهدنا إليكم كذلك -يا أمة محمد- بتقوى الله تعالى، والقيام بأمره واجتناب نهيه، وبيَّنَّا لكم أنكم إن تجحدوا وحدانية الله تعالى وشرعه فإنه سبحانه غني عنكم؛ لأن له جميع ما في السموات والأرض. وكان الله غنيّاً عن خلقه، حميدًا في صفاته وأفعاله.", "isBasmala": false, "translation_en": "To God belongs everything in the heavens and everything on earth. We have instructed those who were given the Book before you, and you, to be conscious of God. But if you refuse-to God belongs everything in the heavens and everything on earth. God is in no need, Praiseworthy.", "translation_id": "Dan kepunyaan Allah-lah apa yang di langit dan yang di bumi, dan sungguh Kami telah memerintahkan kepada orang-orang yang diberi kitab sebelum kamu dan (juga) kepada kamu; bertakwalah kepada Allah. Tetapi jika kamu kafir maka (ketahuilah), sesungguhnya apa yang di langit dan apa yang di bumi hanyalah kepunyaan Allah dan Allah Maha Kaya dan Maha Terpuji.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 132, "text": "وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلًا ۝١٣٢", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "ولله ملك ما في هذا الكون من الكائنات، وكفى به سبحانه قائمًا بشؤون خلقه حافظًا لها.", "isBasmala": false, "translation_en": "To God belongs everything in the heavens and everything on earth. God suffices as Manager.", "translation_id": "Dan kepunyaan Allah-lah apa yang di langit dan apa yang di bumi. Cukuplah Allah sebagai Pemelihara.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 133, "text": "إِن یَشَأۡ یُذۡهِبۡكُمۡ أَیُّهَا ٱلنَّاسُ وَیَأۡتِ بِـَٔاخَرِینَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَ ٰلِكَ قَدِیرࣰا ۝١٣٣", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "إن يشأ الله يُهلكُّم أيها الناس، ويأت بقوم آخرين غيركم. وكان الله على ذلك قديرًا.", "isBasmala": false, "translation_en": "If He wills, He can do away with you, O people, and bring others. God is Able to do that.", "translation_id": "Jika Allah menghendaki, niscaya Dia musnahkan kamu wahai manusia, dan Dia datangkan umat yang lain (sebagai penggantimu). Dan adalah Allah Maha Kuasa berbuat demikian.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 134, "text": "مَّن كَانَ یُرِیدُ ثَوَابَ ٱلدُّنۡیَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۚ وَكَانَ ٱللَّهُ سَمِیعَۢا بَصِیرࣰا ۝١٣٤", "juz": 5, "hizb": "(*½ ح 10*)", "tafsir": "من يرغب منكم -أيها الناس- في ثواب الدنيا ويعرض عن الآخرة، فعند الله وحده ثواب الدنيا والآخرة، فليطلب من الله وحده خيري الدنيا والآخرة، فهو الذي يملكهما. وكان الله سميعًا لأقوال عباده، بصيرًا بأعمالهم ونياتهم، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "Whoever desires the reward of this world-with God is the reward of this world and the next. God is All-Hearing, All-Seeing.", "translation_id": "Barangsiapa yang menghendaki pahala di dunia saja (maka ia merugi), karena di sisi Allah ada pahala dunia dan akhirat. Dan Allah Maha Mendengar lagi Maha Melihat.", "manzil": 1, "manzil_display": ""}], "100": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 135, "text": "۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُونُوا۟ قَوَّ ٰمِینَ بِٱلۡقِسۡطِ شُهَدَاۤءَ لِلَّهِ وَلَوۡ عَلَىٰۤ أَنفُسِكُمۡ أَوِ ٱلۡوَ ٰلِدَیۡنِ وَٱلۡأَقۡرَبِینَۚ إِن یَكُنۡ غَنِیًّا أَوۡ فَقِیرࣰا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُوا۟ ٱلۡهَوَىٰۤ أَن تَعۡدِلُوا۟ۚ وَإِن تَلۡوُۥۤا۟ أَوۡ تُعۡرِضُوا۟ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِیرࣰا ۝١٣٥", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، كونوا قائمين بالعدل، مؤدين للشهادة لوجه الله تعالى، ولو كانت على أنفسكم، أو على آبائكم وأمهاتكم، أو على أقاربكم، مهما كان شأن المشهود عليه غنيًّا أو فقيرًا؛ فإن الله تعالى أولى بهما منكم، وأعلم بما فيه صلاحهما، فلا يحملنَّكم الهوى والتعصب على ترك العدل، وإن تحرفوا الشهادة بألسنتكم فتأتوا بها على غير حقيقتها، أو تعرضوا عنها بترك أدائها أو بكتمانها، فإن الله تعالى كان عليمًا بدقائق أعمالكم، وسيجازيكم بها.", "isBasmala": false, "translation_en": "O you who believe! Stand firmly for justice, as witnesses to God, even if against yourselves, or your parents, or your relatives. Whether one is rich or poor, God takes care of both. So do not follow your desires, lest you swerve. If you deviate, or turn away-then God is Aware of what you do.", "translation_id": "Wahai orang-orang yang beriman, jadilah kamu orang yang benar-benar penegak keadilan, menjadi saksi karena Allah biarpun terhadap dirimu sendiri atau ibu bapa dan kaum kerabatmu. Jika ia kaya ataupun miskin, maka Allah lebih tahu kemaslahatannya. Maka janganlah kamu mengikuti hawa nafsu karena ingin menyimpang dari kebenaran. Dan jika kamu memutar balikkan (kata-kata) atau enggan menjadi saksi, maka sesungguhnya Allah adalah Maha Mengetahui segala apa yang kamu kerjakan.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 136, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَـٰبِ ٱلَّذِی نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَـٰبِ ٱلَّذِیۤ أَنزَلَ مِن قَبۡلُۚ وَمَن یَكۡفُرۡ بِٱللَّهِ وَمَلَـٰۤىِٕكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ فَقَدۡ ضَلَّ ضَلَـٰلَۢا بَعِیدًا ۝١٣٦", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه داوموا على ما أنتم عليه من التصديق الجازم بالله تعالى وبرسوله محمد صلى الله عليه وسلم، ومن طاعتهما، وبالقرآن الذي نزله عليه، وبجميع الكتب التي أنزلها الله على الرسل. ومن يكفر بالله تعالى، وملائكته المكرمين، وكتبه التي أنزلها لهداية خلقه، ورسله الذين اصطفاهم لتبليغ رسالته، واليوم الآخر الذي يقوم الناس فيه بعد موتهم للعرض والحساب، فقد خرج من الدين، وبَعُدَ بعدًا كبيرًا عن طريق الحق.", "isBasmala": false, "translation_en": "O you who believe! Believe in God and His messenger, and the Book He sent down to His messenger, and the Book He sent down before. Whoever rejects God, His angels, His Books, His messengers, and the Last Day, has strayed far in error.", "translation_id": "Wahai orang-orang yang beriman, tetaplah beriman kepada Allah dan Rasul-Nya dan kepada kitab yang Allah turunkan kepada Rasul-Nya serta kitab yang Allah turunkan sebelumnya. Barangsiapa yang kafir kepada Allah, malaikat-malaikat-Nya, kitab-kitab-Nya, rasul-rasul-Nya, dan hari kemudian, maka sesungguhnya orang itu telah sesat sejauh-jauhnya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 137, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ ثُمَّ ٱزۡدَادُوا۟ كُفۡرࣰا لَّمۡ یَكُنِ ٱللَّهُ لِیَغۡفِرَ لَهُمۡ وَلَا لِیَهۡدِیَهُمۡ سَبِیلَۢا ۝١٣٧", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "إن الذين دخلوا في الإيمان، ثم رجعوا عنه إلى الكفر، ثم عادوا إلى الإيمان، ثم رجعوا إلى الكفر مرة أخرى، ثم أصرُّوا على كفرهم واستمروا عليه، لم يكن الله ليغفر لهم، ولا ليدلهم على طريق من طرق الهداية، التي ينجون بها من سوء العاقبة.", "isBasmala": false, "translation_en": "Those who believe, then disbelieve, then believe, then disbelieve, then increase in disbelief, God will not forgive them, nor will He guide them to a way.", "translation_id": "Sesungguhnya orang-orang yang beriman kemudian kafir, kemudian beriman (pula), kamudian kafir lagi, kemudian bertambah kekafirannya, maka sekali-kali Allah tidak akan memberi ampunan kepada mereka, dan tidak (pula) menunjuki mereka kepada jalan yang lurus.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 138, "text": "بَشِّرِ ٱلۡمُنَـٰفِقِینَ بِأَنَّ لَهُمۡ عَذَابًا أَلِیمًا ۝١٣٨", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "بشّر -أيها الرسول- المنافقين -وهم الذين يظهرون الإيمان ويبطنون الكفر- بأن لهم عذابًا موجعًا.", "isBasmala": false, "translation_en": "Inform the hypocrites that they will have a painful punishment.", "translation_id": "Kabarkanlah kepada orang-orang munafik bahwa mereka akan mendapat siksaan yang pedih,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 139, "text": "ٱلَّذِینَ یَتَّخِذُونَ ٱلۡكَـٰفِرِینَ أَوۡلِیَاۤءَ مِن دُونِ ٱلۡمُؤۡمِنِینَۚ أَیَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِیعࣰا ۝١٣٩", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "الذين يوالون الكافرين، ويتخذونهم أعوانًا لهم، ويتركون ولاية المؤمنين، ولا يرغبون في مودتهم. أيطلبون بذلك النصرة والمنعة عند الكافرين؟ إنهم لا يملكون ذلك، فالنصرة والعزة والقوة جميعها لله تعالى وحده.", "isBasmala": false, "translation_en": "Those who ally themselves with the disbelievers instead of the believers. Do they seek glory in them? All glory belongs to God.", "translation_id": "(yaitu) orang-orang yang mengambil orang-orang kafir menjadi teman-teman penolong dengan meninggalkan orang-orang mukmin. Apakah mereka mencari kekuatan di sisi orang kafir itu? Maka sesungguhnya semua kekuatan kepunyaan Allah.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 140, "text": "وَقَدۡ نَزَّلَ عَلَیۡكُمۡ فِی ٱلۡكِتَـٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَایَـٰتِ ٱللَّهِ یُكۡفَرُ بِهَا وَیُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُوا۟ مَعَهُمۡ حَتَّىٰ یَخُوضُوا۟ فِی حَدِیثٍ غَیۡرِهِۦۤ إِنَّكُمۡ إِذࣰا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَـٰفِقِینَ وَٱلۡكَـٰفِرِینَ فِی جَهَنَّمَ جَمِیعًا ۝١٤٠", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "وقد نزل عليكم -أيها المؤمنون- في كتاب ربكم أنه إذا سمعتم الكفر بآيات الله والاستهزاء بها فلا تجلسوا مع الكافرين والمستهزئين، إلا إذا أخذوا في حديث غير حديث الكفر والاستهزاء بآيات الله. إنكم إذا جالستموهم، وهم على ما هم عليه، فأنتم مثلهم؛ لأنكم رضيتم بكفرهم واستهزائهم، والراضي بالمعصية كالفاعل لها. إن الله تعالى جامع المنافقين والكافرين في نار جهنم جميعًا، يلْقَون فيها سوء العذاب.", "isBasmala": false, "translation_en": "He has revealed to you in the Book that when you hear God's revelations being rejected, or ridiculed, do not sit with them until they engage in some other subject. Otherwise, you would be like them. God will gather the hypocrites and the disbelievers, into Hell, altogether.", "translation_id": "Dan sungguh Allah telah menurunkan kekuatan kepada kamu di dalam Al Quran bahwa apabila kamu mendengar ayat-ayat Allah diingkari dan diperolok-olokkan (oleh orang-orang kafir), maka janganlah kamu duduk beserta mereka, sehingga mereka memasuki pembicaraan yang lain. Karena sesungguhnya (kalau kamu berbuat demikian), tentulah kamu serupa dengan mereka. Sesungguhnya Allah akan mengumpulkan semua orang-orang munafik dan orang-orang kafir di dalam Jahannam,", "manzil": 1, "manzil_display": ""}], "101": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 141, "text": "ٱلَّذِینَ یَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحࣱ مِّنَ ٱللَّهِ قَالُوۤا۟ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَـٰفِرِینَ نَصِیبࣱ قَالُوۤا۟ أَلَمۡ نَسۡتَحۡوِذۡ عَلَیۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِینَۚ فَٱللَّهُ یَحۡكُمُ بَیۡنَكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۗ وَلَن یَجۡعَلَ ٱللَّهُ لِلۡكَـٰفِرِینَ عَلَى ٱلۡمُؤۡمِنِینَ سَبِیلًا ۝١٤١", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "المنافقون هم الذين ينتظرون ما يحلُّ بكم -أيها المؤمنون- من الفتن والحرب، فإن منَّ الله عليكم بفضله، ونصركم على عدوكم وغنمتم، قالوا لكم: ألم نكن معكم نؤازركم؟ وإن كان للجاحدين لهذا الدين قَدْرٌ من النصر والغنيمة، قالوا لهم: ألم نساعدكم بما قدَّمناه لكم ونَحْمِكُم من المؤمنين؟ فالله تعالى يقضي بينكم وبينهم يوم القيامة، ولن يجعل الله للكافرين طريقًا للغلبة على عباده الصالحين، فالعاقبة للمتقين في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Those who lie in wait for you: if you attain victory from God, they say, \"Were we not with you?\" But if the disbelievers get a turn, they say, \"Did we not side with you, and defend you from the believers?\" God will judge between you on the Day of Resurrection; and God will give the disbelievers no means of overcoming the believers.", "translation_id": "(yaitu) orang-orang yang menunggu-nunggu (peristiwa) yang akan terjadi pada dirimu (hai orang-orang mukmin). Maka jika terjadi bagimu kemenangan dari Allah mereka berkata: \"Bukankah kami (turut berperang) beserta kamu?\" Dan jika orang-orang kafir mendapat keberuntungan (kemenangan) mereka berkata: \"Bukankah kami turut memenangkanmu, dan membela kamu dari orang-orang mukmin?\" Maka Allah akan memberi keputusan di antara kamu di hari kiamat dan Allah sekali-kali tidak akan memberi jalan kepada orang-orang kafir untuk memusnahkan orang-orang yang beriman.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 142, "text": "إِنَّ ٱلۡمُنَـٰفِقِینَ یُخَـٰدِعُونَ ٱللَّهَ وَهُوَ خَـٰدِعُهُمۡ وَإِذَا قَامُوۤا۟ إِلَى ٱلصَّلَوٰةِ قَامُوا۟ كُسَالَىٰ یُرَاۤءُونَ ٱلنَّاسَ وَلَا یَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِیلࣰا ۝١٤٢", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "إنَّ طريقة هؤلاء المنافقين مخادعة الله تعالى، بما يظهرونه من الإيمان وما يبطنونه من الكفر، ظنًّا أنه يخفى على الله، والحال أن الله خادعهم ومجازيهم بمثل عملهم، وإذا قام هؤلاء المنافقون لأداء الصلاة، قاموا إليها في فتور، يقصدون بصلاتهم الرياء والسمعة، ولا يذكرون الله تعالى إلا ذكرًا قليلا.", "isBasmala": false, "translation_en": "The hypocrites try to deceive God, but He is deceiving them. And when they stand for prayer, they stand lazily, showing off in front of people, and remembering God only a little.", "translation_id": "Sesungguhnya orang-orang munafik itu menipu Allah, dan Allah akan membalas tipuan mereka. Dan apabila mereka berdiri untuk shalat mereka berdiri dengan malas. Mereka bermaksud riya (dengan shalat) di hadapan manusia. Dan tidaklah mereka menyebut Allah kecuali sedikit sekali.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 143, "text": "مُّذَبۡذَبِینَ بَیۡنَ ذَ ٰلِكَ لَاۤ إِلَىٰ هَـٰۤؤُلَاۤءِ وَلَاۤ إِلَىٰ هَـٰۤؤُلَاۤءِۚ وَمَن یُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِیلࣰا ۝١٤٣", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "إنَّ مِن شأن هؤلاء المنافقين التردد والحَيْرة والاضطراب، لا يستقرون على حال، فلا هم مع المؤمنين ولا هم مع الكافرين. ومن يصرف الله قلبه عن الإيمان به والاستمساك بهديه، فلن تجد له طريقًا إلى الهداية واليقين.", "isBasmala": false, "translation_en": "Wavering in between, neither with these, nor with those. Whomever God sends astray, you will never find for him a way.", "translation_id": "Mereka dalam keadaan ragu-ragu antara yang demikian (iman atau kafir): tidak masuk kepada golongan ini (orang-orang beriman) dan tidak (pula) kepada golongan itu (orang-orang kafir), maka kamu sekali-kali tidak akan mendapat jalan (untuk memberi petunjuk) baginya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 144, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلۡكَـٰفِرِینَ أَوۡلِیَاۤءَ مِن دُونِ ٱلۡمُؤۡمِنِینَۚ أَتُرِیدُونَ أَن تَجۡعَلُوا۟ لِلَّهِ عَلَیۡكُمۡ سُلۡطَـٰنࣰا مُّبِینًا ۝١٤٤", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا توالوا الجاحدين لدين الله، وتتركوا موالاة المؤمنين ومودتهم. أتريدون بمودَّة أعدائكم أن تجعلوا لله تعالى عليكم حجة ظاهرة على عدم صدقكم في إيمانكم؟", "isBasmala": false, "translation_en": "O you who believe! Do not befriend disbelievers rather than believers. Do you want to give God a clear case against you?", "translation_id": "Hai orang-orang yang beriman, janganlah kamu mengambil orang-orang kafir menjadi wali dengan meninggalkan orang-orang mukmin. Inginkah kamu mengadakan alasan yang nyata bagi Allah (untuk menyiksamu)?", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 145, "text": "إِنَّ ٱلۡمُنَـٰفِقِینَ فِی ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِیرًا ۝١٤٥", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "إن المنافقين في أسفل منازل النار يوم القيامة، ولن تجد لهم -أيها الرسول- ناصرًا يدفع عنهم سوء هذا المصير.", "isBasmala": false, "translation_en": "The hypocrites will be in the lowest level of the Fire, and you will find no helper for them.", "translation_id": "Sesungguhnya orang-orang munafik itu (ditempatkan) pada tingkatan yang paling bawah dari neraka. Dan kamu sekali-kali tidak akan mendapat seorang penolongpun bagi mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 146, "text": "إِلَّا ٱلَّذِینَ تَابُوا۟ وَأَصۡلَحُوا۟ وَٱعۡتَصَمُوا۟ بِٱللَّهِ وَأَخۡلَصُوا۟ دِینَهُمۡ لِلَّهِ فَأُو۟لَـٰۤىِٕكَ مَعَ ٱلۡمُؤۡمِنِینَۖ وَسَوۡفَ یُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِینَ أَجۡرًا عَظِیمࣰا ۝١٤٦", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "إلا الذين رجعوا إلى الله تعالى وتابوا إليه، وأصلحوا ما أفسدوا من أحوالهم باطنًا وظاهرًا، ووالوا عباده المؤمنين، واستمسكوا بدين الله، وأخلصوا له سبحانه، فأولئك مع المؤمنين في الدنيا والآخرة، وسوف يعطي الله المؤمنين ثوابًا عظيمًا.", "isBasmala": false, "translation_en": "Except those who repent, and reform, and hold fast to God, and dedicate their religion to God alone. These are with the believers; and God will give the believers a great reward.", "translation_id": "Kecuali orang-orang yang taubat dan mengadakan perbaikan dan berpegang teguh pada (agama) Allah dan tulus ikhlas (mengerjakan) agama mereka karena Allah. Maka mereka itu adalah bersama-sama orang yang beriman dan kelak Allah akan memberikan kepada orang-orang yang beriman pahala yang besar.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 147, "text": "مَّا یَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِیمࣰا ۝١٤٧", "juz": 5, "hizb": "(*¾ ح 10*)", "tafsir": "ما يفعل الله بعذابكم إن أصلحتم العمل وآمنتم بالله ورسوله، فإن الله سبحانه غني عمَّن سواه، وإنما يعذب العباد بذنوبهم. وكان الله شاكرًا لعباده على طاعتهم له، عليمًا بكل شيء.", "isBasmala": false, "translation_en": "What would God accomplish by your punishment, if you have given thanks, and have believed? God is Appreciative and Cognizant.", "translation_id": "Mengapa Allah akan menyiksamu, jika kamu bersyukur dan beriman? Dan Allah adalah Maha Mensyukuri lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}], "102": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 148, "text": "۞ لَّا یُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوۤءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ ٱللَّهُ سَمِیعًا عَلِیمًا ۝١٤٨", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "لا يُحِبُّ الله أن يَجهر أحدٌ بقول السوء، لكن يُباح للمظلوم أن يَذكُر ظالمه بما فيه من السوء؛ ليبيِّن مَظْلمته. وكان الله سميعًا لما تجهرون به، عليمًا بما تخفون من ذلك.", "isBasmala": false, "translation_en": "God does not like the public uttering of bad language, unless someone was wronged. God is Hearing and Knowing.", "translation_id": "Allah tidak menyukai ucapan buruk, (yang diucapkan) dengan terus terang kecuali oleh orang yang dianiaya. Allah adalah Maha Mendengar lagi Maha Mengetahui.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 149, "text": "إِن تُبۡدُوا۟ خَیۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُوا۟ عَن سُوۤءࣲ فَإِنَّ ٱللَّهَ كَانَ عَفُوࣰّا قَدِیرًا ۝١٤٩", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "نَدَب الله تعالى إلى العفو، ومهَّد له بأنَّ المؤمن: إمَّا أن يُظهر الخير، وإمَّا أن يُخفيه، وكذلك مع الإساءة: إما أن يظهرها في حال الانتصاف من المسيء، وإما أن يعفو ويصفح، والعفوُ أفضلُ؛ فإن من صفاته تعالى العفو عن عباده مع قدرته عليهم.", "isBasmala": false, "translation_en": "If you let a good deed be shown, or conceal it, or pardon an offense-God is Pardoning and Capable.", "translation_id": "Jika kamu melahirkan sesuatu kebaikan atau menyembunyikan atau memaafkan sesuatu kesalahan (orang lain), maka sesungguhnya Allah Maha Pemaaf lagi Maha Kuasa.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 150, "text": "إِنَّ ٱلَّذِینَ یَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَیُرِیدُونَ أَن یُفَرِّقُوا۟ بَیۡنَ ٱللَّهِ وَرُسُلِهِۦ وَیَقُولُونَ نُؤۡمِنُ بِبَعۡضࣲ وَنَكۡفُرُ بِبَعۡضࣲ وَیُرِیدُونَ أَن یَتَّخِذُوا۟ بَیۡنَ ذَ ٰلِكَ سَبِیلًا ۝١٥٠", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "إن الذين يكفرون بالله ورسله من اليهود والنصارى، ويريدون أن يفرقوا بين الله ورسله بأن يؤمنوا بالله ويكذبوا رسله الذين أرسلهم إلى خلقه، أو يعترفوا بصدق بعض الرسل دون بعض، ويزعموا أنَّ بعضهم افتروا على ربِّهم، ويريدون أن يتخذوا طريقًا إلى الضلالة التي أحدثوها والبدعة التي ابتدعوها.", "isBasmala": false, "translation_en": "Those who disbelieve in God and His messengers, and want to separate between God and His messengers, and say, \"We believe in some, and reject some,\" and wish to take a path in between.", "translation_id": "Sesungguhnya orang-orang yang kafir kepada Allah dan rasul-rasul-Nya, dan bermaksud memperbedakan antara (keimanan kepada) Allah dan rasul-rasul-Nya, dengan mengatakan: \"Kami beriman kepada yang sebahagian dan kami kafir terhadap sebahagian (yang lain)\", serta bermaksud (dengan perkataan itu) mengambil jalan (tengah) di antara yang demikian (iman atau kafir),", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 151, "text": "أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡكَـٰفِرُونَ حَقࣰّاۚ وَأَعۡتَدۡنَا لِلۡكَـٰفِرِینَ عَذَابࣰا مُّهِینࣰا ۝١٥١", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "أولئك هم أهل الكفر المحقَّق الذي لا شك فيه، وأعتدنا للكافرين عذابًا يخزيهم ويهينهم.", "isBasmala": false, "translation_en": "These are the unbelievers, truly. We have prepared for the unbelievers a shameful punishment.", "translation_id": "merekalah orang-orang yang kafir sebenar-benarnya. Kami telah menyediakan untuk orang-orang yang kafir itu siksaan yang menghinakan.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 152, "text": "وَٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ یُفَرِّقُوا۟ بَیۡنَ أَحَدࣲ مِّنۡهُمۡ أُو۟لَـٰۤىِٕكَ سَوۡفَ یُؤۡتِیهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا ۝١٥٢", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "والذين صَدَّقوا بوحدانية الله، وأقرُّوا بنبوَّة رسله أجمعين، ولم يفرقوا بين أحد منهم، وعملوا بشريعة الله، أولئك سوف يعطيهم جزاءهم وثوابهم على إيمانهم به وبرسله. وكان الله غفورًا رحيمًا.", "isBasmala": false, "translation_en": "As for those who believe in God and His messengers, and make no distinction between any of them-He will give them their rewards. God is Forgiver and Merciful.", "translation_id": "Orang-orang yang beriman kepada Allah dan para rasul-Nya dan tidak membeda-bedakan seorangpun di antara mereka, kelak Allah akan memberikan kepada mereka pahalanya. Dan adalah Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 153, "text": "یَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَـٰبِ أَن تُنَزِّلَ عَلَیۡهِمۡ كِتَـٰبࣰا مِّنَ ٱلسَّمَاۤءِۚ فَقَدۡ سَأَلُوا۟ مُوسَىٰۤ أَكۡبَرَ مِن ذَ ٰلِكَ فَقَالُوۤا۟ أَرِنَا ٱللَّهَ جَهۡرَةࣰ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُوا۟ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَاۤءَتۡهُمُ ٱلۡبَیِّنَـٰتُ فَعَفَوۡنَا عَن ذَ ٰلِكَۚ وَءَاتَیۡنَا مُوسَىٰ سُلۡطَـٰنࣰا مُّبِینࣰا ۝١٥٣", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "يسألك اليهود -أيها الرسول- معجزة مثل معجزة موسى تشهد لك بالصدق: بأن تنزل عليهم صُحُفًا من الله مكتوبةً، مثل مجيء موسى بالألواح من عند الله، فلا تعجب -أيها الرسول- فقد سأل أسلافهم موسى -عليه السلام- ما هو أعظم: سألوه أن يريهم الله علانيةً، فَصُعِقوا بسبب ظلمهم أنفسهم حين سألوا أمرًا ليس من حقِّهم. وبعد أن أحياهم الله بعد الصعق، وشاهدوا الآيات البينات على يد موسى القاطعة بنفي الشرك، عبدوا العجل من دون الله، فعَفونا عن عبادتهم العجل بسبب توبتهم، وآتينا موسى حجة عظيمة تؤيِّد صِدق نُبُوَّتِه.", "isBasmala": false, "translation_en": "The People of the Scripture challenge you to bring down to them a book from the sky. They had asked Moses for something even greater. They said, \"Show us God plainly.\" The thunderbolt struck them for their wickedness. Then they took the calf for worship, even after the clear proofs had come to them. Yet We pardoned that, and We gave Moses a clear authority.", "translation_id": "Ahli Kitab meminta kepadamu agar kamu menurunkan kepada mereka sebuah Kitab dari langit. Maka sesungguhnya mereka telah meminta kepada Musa yang lebih besar dari itu. Mereka berkata: \"Perlihatkanlah Allah kepada kami dengan nyata\". Maka mereka disambar petir karena kezalimannya, dan mereka menyembah anak sapi, sesudah datang kepada mereka bukti-bukti yang nyata, lalu Kami maafkan (mereka) dari yang demikian. Dan telah Kami berikan kepada Musa keterangan yang nyata.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 154, "text": "وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِیثَـٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُوا۟ ٱلۡبَابَ سُجَّدࣰا وَقُلۡنَا لَهُمۡ لَا تَعۡدُوا۟ فِی ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّیثَـٰقًا غَلِیظࣰا ۝١٥٤", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "ورفعنا فوق رؤوسهم جبل الطور حين امتنعوا عن الالتزام بالعهد المؤكد الذي أعطوه بالعمل بأحكام التوراة، وأمرناهم أن يدخلوا باب \"بيت المقدس\" سُجَّدًا، فدخلوا يزحفون على أستاههم، وأمرناهم ألا يَعْتَدُوا بالصيد في يوم السبت فاعتدَوا، وصادوا، وأخذنا عليهم عهدًا مؤكدًا، فنقضوه.", "isBasmala": false, "translation_en": "And We raised the Mount above them in accordance with their covenant, and We said to them, \"Enter the gate humbly\", and We said to them, \"Do not violate the Sabbath\", and We received from them a solemn pledge.", "translation_id": "Dan telah Kami angkat ke atas (kepala) mereka bukit Thursina untuk (menerima) perjanjian (yang telah Kami ambil dari) mereka. Dan kami perintahkan kepada mereka: \"Masuklah pintu gerbang itu sambil bersujud\", dan Kami perintahkan (pula) kepada mereka: \"Janganlah kamu melanggar peraturan mengenai hari Sabtu\", dan Kami telah mengambil dari mereka perjanjian yang kokoh.", "manzil": 1, "manzil_display": ""}], "103": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 155, "text": "فَبِمَا نَقۡضِهِم مِّیثَـٰقَهُمۡ وَكُفۡرِهِم بِـَٔایَـٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِیَاۤءَ بِغَیۡرِ حَقࣲّ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَیۡهَا بِكُفۡرِهِمۡ فَلَا یُؤۡمِنُونَ إِلَّا قَلِیلࣰا ۝١٥٥", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "فلعنَّاهم بسبب نقضهم للعهود، وكفرهم بآيات الله الدالة على صدق رسله، وقتلهم للأنبياء ظلمًا واعتداءً، وقولهم: قلوبنا عليها أغطية فلا تفقه ما تقول، بل طمس الله عليها بسبب كفرهم، فلا يؤمنون إلا إيمانًا قليلا لا ينفعهم.", "isBasmala": false, "translation_en": "But for their violation of their covenant, and their denial of God's revelations, and their killing of the prophets unjustly, and their saying, \"Our minds are closed.\" In fact, God has sealed them for their disbelief, so they do not believe, except for a few.", "translation_id": "Maka (Kami lakukan terhadap mereka beberapa tindakan), disebabkan mereka melanggar perjanjian itu, dan karena kekafiran mereka terhadap keterangan-keterangan Allah dan mereka membunuh nabi-nabi tanpa (alasan) yang benar dan mengatakan: \"Hati kami tertutup\". Bahkan, sebenarnya Allah telah mengunci mati hati mereka karena kekafirannya, karena itu mereka tidak beriman kecuali sebahagian kecil dari mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 156, "text": "وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡیَمَ بُهۡتَـٰنًا عَظِیمࣰا ۝١٥٦", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "وكذلك لعنَّاهم بسبب كفرهم وافترائهم على مريم بما نسبوه إليها من الزنى، وهي بريئة منه.", "isBasmala": false, "translation_en": "And for their faithlessness, and their saying against Mary a monstrous slander.", "translation_id": "Dan karena kekafiran mereka (terhadap Isa) dan tuduhan mereka terhadap Maryam dengan kedustaan besar (zina),", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 157, "text": "وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِیحَ عِیسَى ٱبۡنَ مَرۡیَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَـٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِینَ ٱخۡتَلَفُوا۟ فِیهِ لَفِی شَكࣲّ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ یَقِینَۢا ۝١٥٧", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "وبسبب قولهم -على سبيل التهكم والاستهزاء-: هذا الذي يدعي لنفسه هذا المنصب (قتلناه)، وما قتلوا عيسى وما صلبوه، بل صلبوا رجلا شبيهًا به ظنًّا منهم أنه عيسى. ومن ادَّعى قَتْلَهُ من اليهود، ومن أسلمه إليهم من النصارى، كلهم واقعون في شك وحَيْرَة، لا عِلْمَ لديهم إلا اتباع الظن، وما قتلوه متيقنين بل شاكين متوهمين.", "isBasmala": false, "translation_en": "And for their saying, \"We have killed the Messiah, Jesus, the son of Mary, the Messenger of God.\" In fact, they did not kill him, nor did they crucify him, but it appeared to them as if they did. Indeed, those who differ about him are in doubt about it. They have no knowledge of it, except the following of assumptions. Certainly, they did not kill him.", "translation_id": "dan karena ucapan mereka: \"Sesungguhnya kami telah membunuh Al Masih, Isa putra Maryam, Rasul Allah\", padahal mereka tidak membunuhnya dan tidak (pula) menyalibnya, tetapi (yang mereka bunuh ialah) orang yang diserupakan dengan Isa bagi mereka. Sesungguhnya orang-orang yang berselisih paham tentang (pembunuhan) Isa, benar-benar dalam keragu-raguan tentang yang dibunuh itu. Mereka tidak mempunyai keyakinan tentang siapa yang dibunuh itu, kecuali mengikuti persangkaan belaka, mereka tidak (pula) yakin bahwa yang mereka bunuh itu adalah Isa.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 158, "text": "بَل رَّفَعَهُ ٱللَّهُ إِلَیۡهِۚ وَكَانَ ٱللَّهُ عَزِیزًا حَكِیمࣰا ۝١٥٨", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "بل رفع الله عيسى إليه ببدنه وروحه حيًّا، وطهَّره من الذين كفروا. وكان الله عزيزًا في ملكه، حكيمًا في تدبيره وقضائه.", "isBasmala": false, "translation_en": "Rather, God raised him up to Himself. God is Mighty and Wise.", "translation_id": "Tetapi (yang sebenarnya), Allah telah mengangkat Isa kepada-Nya. Dan adalah Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 159, "text": "وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ إِلَّا لَیُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ یَكُونُ عَلَیۡهِمۡ شَهِیدࣰا ۝١٥٩", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "وإنه لا يبقى أحدٌ من أهل الكتاب بعد نزول عيسى آخر الزمان إلا آمن به قبل موته عليه السلام، ويوم القيامة يكون عيسى -عليه السلام- شهيدًا بتكذيب مَن كذَّبه، وتصديق مَن صدَّقه.", "isBasmala": false, "translation_en": "There is none from the People of the Scripture but will believe in him before his death, and on the Day of Resurrection he will be a witness against them.", "translation_id": "Tidak ada seorangpun dari Ahli Kitab, kecuali akan beriman kepadanya (Isa) sebelum kematiannya. Dan di hari kiamat nanti Isa itu akan menjadi saksi terhadap mereka.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 160, "text": "فَبِظُلۡمࣲ مِّنَ ٱلَّذِینَ هَادُوا۟ حَرَّمۡنَا عَلَیۡهِمۡ طَیِّبَـٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِیلِ ٱللَّهِ كَثِیرࣰا ۝١٦٠", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "فبسبب ظلم اليهود بما ارتكبوه من الذنوب العظيمة حَرَّم الله عليهم طيبات من المأكل كانت حلالا لهم، وبسبب صدِّهم أنفسهم وغيرهم عن دين الله القويم.", "isBasmala": false, "translation_en": "Due to wrongdoing on the part of the Jews, We forbade them good things that used to be lawful for them; and for deterring many from God's path.", "translation_id": "Maka disebabkan kezaliman orang-orang Yahudi, kami haramkan atas (memakan makanan) yang baik-baik (yang dahulunya) dihalalkan bagi mereka, dan karena mereka banyak menghalangi (manusia) dari jalan Allah,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 161, "text": "وَأَخۡذِهِمُ ٱلرِّبَوٰا۟ وَقَدۡ نُهُوا۟ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَ ٰلَ ٱلنَّاسِ بِٱلۡبَـٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَـٰفِرِینَ مِنۡهُمۡ عَذَابًا أَلِیمࣰا ۝١٦١", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "وبسبب تناولهم الربا الذي نهوا عنه، واستحلالهم أموال الناس بغير استحقاق، وأعتدنا للكافرين بالله ورسوله مِن هؤلاء اليهود عذابًا موجعًا في الآخرة.", "isBasmala": false, "translation_en": "And for their taking usury, although they were forbidden it; and for their consuming people's wealth dishonestly. We have prepared for the faithless among them a painful torment.", "translation_id": "dan disebabkan mereka memakan riba, padahal sesungguhnya mereka telah dilarang daripadanya, dan karena mereka memakan harta benda orang dengan jalan yang batil. Kami telah menyediakan untuk orang-orang yang kafir di antara mereka itu siksa yang pedih.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 162, "text": "لَّـٰكِنِ ٱلرَّ ٰسِخُونَ فِی ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ یُؤۡمِنُونَ بِمَاۤ أُنزِلَ إِلَیۡكَ وَمَاۤ أُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِیمِینَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ أُو۟لَـٰۤىِٕكَ سَنُؤۡتِیهِمۡ أَجۡرًا عَظِیمًا ۝١٦٢", "juz": 6, "hizb": "(* ح 11*)", "tafsir": "لكنِ المتمكنون في العلم بأحكام الله من اليهود، والمؤمنون بالله ورسوله، يؤمنون بالذي أنزله الله إليك -أيها الرسول- وهو القرآن، وبالذي أنزل إلى الرسل من قبلك كالتوراة والإنجيل، ويؤدُّون الصلاة في أوقاتها، ويخرجون زكاة أموالهم، ويؤمنون بالله وبالبعث والجزاء، أولئك سيعطيهم الله ثوابًا عظيمًا، وهو الجنة.", "isBasmala": false, "translation_en": "But those among them firmly rooted in knowledge, and the believers, believe in what was revealed to you, and in what was revealed before you; and the observers of prayers, and the givers of charity, and the believers in God and the Last Day-upon these We will bestow an immense reward.", "translation_id": "Tetapi orang-orang yang mendalam ilmunya di antara mereka dan orang-orang mukmin, mereka beriman kepada apa yang telah diturunkan kepadamu (Al Quran), dan apa yang telah diturunkan sebelummu dan orang-orang yang mendirikan shalat, menunaikan zakat, dan yang beriman kepada Allah dan hari kemudian. Orang-orang itulah yang akan Kami berikan kepada mereka pahala yang besar.", "manzil": 1, "manzil_display": ""}], "104": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 163, "text": "۞ إِنَّاۤ أَوۡحَیۡنَاۤ إِلَیۡكَ كَمَاۤ أَوۡحَیۡنَاۤ إِلَىٰ نُوحࣲ وَٱلنَّبِیِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَیۡنَاۤ إِلَىٰۤ إِبۡرَ ٰهِیمَ وَإِسۡمَـٰعِیلَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِیسَىٰ وَأَیُّوبَ وَیُونُسَ وَهَـٰرُونَ وَسُلَیۡمَـٰنَۚ وَءَاتَیۡنَا دَاوُۥدَ زَبُورࣰا ۝١٦٣", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "إنا أوحينا اليك -أيها الرسول- بتبليغ الرسالة كما أوحينا إلى نوح والنبيين من بعده، وأوحينا إلى إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط -وهم الأنبياء الذين كانوا في قبائل بني إسرائيل الاثنتي عشرة من ولد يعقوب- وعيسى وأيوب ويونس وهارون وسليمان. وآتينا داود زبورًا، وهو كتاب وصحف مكتوبة.", "isBasmala": false, "translation_en": "We have inspired you, as We had inspired Noah and the prophets after him. And We inspired Abraham, and Ishmael, and Isaac, and Jacob, and the Patriarchs, and Jesus, and Job, and Jonah, and Aaron, and Solomon. And We gave David the Psalms.", "translation_id": "Sesungguhnya Kami telah memberikan wahyu kepadamu sebagaimana Kami telah memberikan wahyu kepada Nuh dan nabi-nabi yang kemudiannya, dan Kami telah memberikan wahyu (pula) kepada Ibrahim, Isma'il, Ishak, Ya'qub dan anak cucunya, Isa, Ayyub, Yunus, Harun dan Sulaiman. Dan Kami berikan Zabur kepada Daud.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 164, "text": "وَرُسُلࣰا قَدۡ قَصَصۡنَـٰهُمۡ عَلَیۡكَ مِن قَبۡلُ وَرُسُلࣰا لَّمۡ نَقۡصُصۡهُمۡ عَلَیۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِیمࣰا ۝١٦٤", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "وأرسلنا رسلا قد قصصناهم عليك في القرآن من قبل هذه الآية، ورسلا لم نقصصهم عليك لحكمة أردناها. وكلم الله موسى تكليمًا؛ تشريفًا له بهذه الصفة. وفي هذه الآية الكريمة، إثبات صفة الكلام لله -تعالى- كما يليق بجلاله، وأنه سبحانه كلم نبيه موسى -عليه السلام- حقيقة بلا وساطة.", "isBasmala": false, "translation_en": "Some messengers We have already told you about, while some messengers We have not told you about. And God spoke to Moses directly.", "translation_id": "Dan (Kami telah mengutus) rasul-rasul yang sungguh telah Kami kisahkan tentang mereka kepadamu dahulu, dan rasul-rasul yang tidak Kami kisahkan tentang mereka kepadamu. Dan Allah telah berbicara kepada Musa dengan langsung.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 165, "text": "رُّسُلࣰا مُّبَشِّرِینَ وَمُنذِرِینَ لِئَلَّا یَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِیزًا حَكِیمࣰا ۝١٦٥", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "أرسَلْتُ رسلا إلى خَلْقي مُبشِّرين بثوابي، ومنذرين بعقابي؛ لئلا يكون للبشر حجة يعتذرون بها بعد إرسال الرسل. وكان الله عزيزًا في ملكه، حكيمًا في تدبيره.", "isBasmala": false, "translation_en": "Messengers delivering good news, and bringing warnings; so that people may have no excuse before God after the coming of the messengers. God is Powerful and Wise.", "translation_id": "(Mereka Kami utus) selaku rasul-rasul pembawa berita gembira dan pemberi peringatan agar supaya tidak ada alasan bagi manusia membantah Allah sesudah diutusnya rasul-rasul itu. Dan adalah Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 166, "text": "لَّـٰكِنِ ٱللَّهُ یَشۡهَدُ بِمَاۤ أَنزَلَ إِلَیۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ وَٱلۡمَلَـٰۤىِٕكَةُ یَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِیدًا ۝١٦٦", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "إن يكفر بك اليهود وغيرهم -أيها الرسول- فالله يشهد لك بأنك رسوله الذي أَنْزَلَ عليه القرآن العظيم، أنزله بعلمه، وكذلك الملائكة يشهدون بصدق ما أوحي إليك، وشهادة الله وحدها كافية.", "isBasmala": false, "translation_en": "But God bears witness to what He revealed to you. He revealed it with His knowledge. And the angels bear witness. Though God is a sufficient witness.", "translation_id": "(Mereka tidak mau mengakui yang diturunkan kepadamu itu), tetapi Allah mengakui Al Quran yang diturunkan-Nya kepadamu. Allah menurunkannya dengan ilmu-Nya; dan malaikat-malaikat pun menjadi saksi (pula). Cukuplah Allah yang mengakuinya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 167, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ قَدۡ ضَلُّوا۟ ضَلَـٰلَۢا بَعِیدًا ۝١٦٧", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "إن الذين جحدوا نُبُوَّتك، وصدوا الناس عن الإسلام، قد بَعُدوا عن طريق الحق بُعْدًا شديدًا.", "isBasmala": false, "translation_en": "Those who disbelieve and repel from God's path have gone far astray.", "translation_id": "Sesungguhnya orang-orang yang kafir dan menghalang-halangi (manusia) dari jalan Allah, benar-benar telah sesat sejauh-jauhnya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 168, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَظَلَمُوا۟ لَمۡ یَكُنِ ٱللَّهُ لِیَغۡفِرَ لَهُمۡ وَلَا لِیَهۡدِیَهُمۡ طَرِیقًا ۝١٦٨", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "إن الذين كفروا بالله وبرسوله، وظلموا باستمرارهم على الكفر، لم يكن الله ليغفر ذنوبهم، ولا ليدلهم على طريق ينجيهم.", "isBasmala": false, "translation_en": "Those who disbelieve and transgress; God is not about to forgive them, nor will He guide them to any path.", "translation_id": "Sesungguhnya orang-orang yang kafir dan melakukan kezaliman, Allah sekali-kali tidak akan mengampuni (dosa) mereka dan tidak (pula) akan menunjukkan jalan kepada mereka,", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 169, "text": "إِلَّا طَرِیقَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۚ وَكَانَ ذَ ٰلِكَ عَلَى ٱللَّهِ یَسِیرࣰا ۝١٦٩", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "إلا طريق جهنم ماكثين فيها أبدًا، وكان ذلك على الله يسيرًا، فلا يعجزه شيء.", "isBasmala": false, "translation_en": "Except to the path of Hell, where they will dwell forever. And that is easy for God.", "translation_id": "kecuali jalan ke neraka Jahannam; mereka kekal di dalamnya selama-lamanya. Dan yang demikian itu adalah mudah bagi Allah.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 170, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ قَدۡ جَاۤءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُوا۟ خَیۡرࣰا لَّكُمۡۚ وَإِن تَكۡفُرُوا۟ فَإِنَّ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا ۝١٧٠", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "يا أيها الناس قد جاءكم رسولنا محمد صلى الله عليه وسلم بالإسلام دين الحق من ربكم، فَصَدِّقوه واتبعوه، فإن الإيمان به خيرلكم، وإن تُصرُّوا على كفركم فإن الله غني عنكم وعن إيمانكم؛ لأنه مالك ما في السموات والأرض. وكان الله عليمًا بأقوالكم وأفعالكم، حكيمًا في تشريعه وأمره. فإذا كانت السموات والأرض قد خضعتا لله تعالى كونًا وقدرًا خضوع سائر ملكه، فأولى بكم أن تؤمنوا بالله وبرسوله محمد صلى الله عليه وسلم، وبالقرآن الذي أنزله عليه، وأن تنقادوا لذلك شرعًا حتى يكون الكون كلُّه خاضعًا لله قدرًا وشرعًا. وفي الآية دليل على عموم رسالة نبي الله ورسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "O people! The Messenger has come to you with the truth from your Lord, so believe-that is best for you. But if you disbelieve, to God belongs everything in the heavens and the earth. God is Omniscient and Wise.", "translation_id": "Wahai manusia, sesungguhnya telah datang Rasul (Muhammad) itu kepadamu dengan (membawa) kebenaran dari Tuhanmu, maka berimanlah kamu, itulah yang lebih baik bagimu. Dan jika kamu kafir, (maka kekafiran itu tidak merugikan Allah sedikitpun) karena sesungguhnya apa yang di langit dan di bumi itu adalah kepunyaan Allah. Dan adalah Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 1, "manzil_display": ""}], "105": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 171, "text": "یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لَا تَغۡلُوا۟ فِی دِینِكُمۡ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِیحُ عِیسَى ٱبۡنُ مَرۡیَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥۤ أَلۡقَىٰهَاۤ إِلَىٰ مَرۡیَمَ وَرُوحࣱ مِّنۡهُۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُوا۟ ثَلَـٰثَةٌۚ ٱنتَهُوا۟ خَیۡرࣰا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَـٰهࣱ وَ ٰحِدࣱۖ سُبۡحَـٰنَهُۥۤ أَن یَكُونَ لَهُۥ وَلَدࣱۘ لَّهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِیلࣰا ۝١٧١", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "يا أهل الإنجيل لا تتجاوزوا الاعتقاد الحق في دينكم، ولا تقولوا على الله إلا الحق، فلا تجعلوا له صاحبةً ولا ولدًا. إنما المسيح عيسى ابن مريم رسول الله أرسله الله بالحق، وخَلَقَه بالكلمة التي أرسل بها جبريل إلى مريم، وهي قوله: \"كن\"، فكان، وهي نفخة من الله تعالى نفخها جبريل بأمر ربه، فَصدِّقوا بأن الله واحد وأسلموا له، وصدِّقوا رسله فيما جاؤوكم به من عند الله واعملوا به، ولا تجعلوا عيسى وأمه مع الله شريكين. انتهوا عن هذه المقالة خيرًا لكم مما أنتم عليه، إنما الله إله واحد سبحانه. ما في السموات والأرض مُلْكُه، فكيف يكون له منهم صاحبة أو ولد؟ وكفى بالله وكيلا على تدبير خلقه وتصريف معاشهم، فتوكَّلوا عليه وحده فهو كافيكم.", "isBasmala": false, "translation_en": "O People of the Scripture! Do not exaggerate in your religion, and do not say about God except the truth. The Messiah, Jesus, the son of Mary, is the Messenger of God, and His Word that He conveyed to Mary, and a Spirit from Him. So believe in God and His messengers, and do not say, \"Three.\" Refrain-it is better for you. God is only one God. Glory be to Him-that He should have a son. To Him belongs everything in the heavens and the earth, and God is a sufficient Protector.", "translation_id": "Wahai Ahli Kitab, janganlah kamu melampaui batas dalam agamamu, dan janganlah kamu mengatakan terhadap Allah kecuali yang benar. Sesungguhnya Al Masih, Isa putera Maryam itu, adalah utusan Allah dan (yang diciptakan dengan) kalimat-Nya yang disampaikan-Nya kepada Maryam, dan (dengan tiupan) roh dari-Nya. Maka berimanlah kamu kepada Allah dan rasul-rasul-Nya dan janganlah kamu mengatakan: \"(Tuhan itu) tiga\", berhentilah (dari ucapan itu). (Itu) lebih baik bagimu. Sesungguhnya Allah Tuhan Yang Maha Esa, Maha Suci Allah dari mempunyai anak, segala yang di langit dan di bumi adalah kepunyaan-Nya. Cukuplah Allah menjadi Pemelihara.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 172, "text": "لَّن یَسۡتَنكِفَ ٱلۡمَسِیحُ أَن یَكُونَ عَبۡدࣰا لِّلَّهِ وَلَا ٱلۡمَلَـٰۤىِٕكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن یَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَیَسۡتَكۡبِرۡ فَسَیَحۡشُرُهُمۡ إِلَیۡهِ جَمِیعࣰا ۝١٧٢", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "لن يَأْنف ولن يمتنع المسيح أن يكون عبدًا لله، وكذلك لن يأنَفَ الملائكة المُقَرَّبون من الإقرار بالعبودية لله تعالى. ومن يأنف عن الانقياد والخضوع ويستكبر فسيحشرهم كلهم إليه يوم القيامة، ويفصلُ بينهم بحكمه العادل، ويجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "The Messiah does not disdain to be a servant of God, nor do the favored angels. Whoever disdains His worship, and is too arrogant-He will round them up to Himself altogether.", "translation_id": "Al Masih sekali-kali tidak enggan menjadi hamba bagi Allah, dan tidak (pula enggan) malaikat-malaikat yang terdekat (kepada Allah). Barangsiapa yang enggan dari menyembah-Nya, dan menyombongkan diri, nanti Allah akan mengumpulkan mereka semua kepada-Nya.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 173, "text": "فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَیُوَفِّیهِمۡ أُجُورَهُمۡ وَیَزِیدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِینَ ٱسۡتَنكَفُوا۟ وَٱسۡتَكۡبَرُوا۟ فَیُعَذِّبُهُمۡ عَذَابًا أَلِیمࣰا وَلَا یَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِیࣰّا وَلَا نَصِیرࣰا ۝١٧٣", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "فأمَّا الذين صَدَّقوا بالله اعتقادًا وقولا وعملا واستقاموا على شريعته فيوفيهم ثواب أعمالهم، ويزيدُهم من فضله، وأما الذين امتنعوا عن طاعة الله، واستكبروا عن التذلل له فيعذبهم عذابًا موجعًا، ولا يجدون لهم وليًّا ينجيهم من عذابه، ولا ناصرًا ينصرهم من دون الله.", "isBasmala": false, "translation_en": "But as for those who believe and do good works, He will pay them their wages in full, and will increase His grace for them. But as for those who disdain and are too proud, He will punish them with an agonizing punishment. And they will find for themselves, apart from God, no lord and no savior.", "translation_id": "Adapun orang-orang yang beriman dan berbuat amal saleh, maka Allah akan menyempurnakan pahala mereka dan menambah untuk mereka sebagian dari karunia-Nya. Adapun orang-orang yang enggan dan menyombongkan diri, maka Allah akan menyiksa mereka dengan siksaan yang pedih, dan mereka tidak akan memperoleh bagi diri mereka, pelindung dan penolong selain dari pada Allah.", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 174, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ قَدۡ جَاۤءَكُم بُرۡهَـٰنࣱ مِّن رَّبِّكُمۡ وَأَنزَلۡنَاۤ إِلَیۡكُمۡ نُورࣰا مُّبِینࣰا ۝١٧٤", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "يا أيها الناس قد جاءكم برهان من ربكم، وهو رسولنا محمد، وما جاء به من البينات والحجج القاطعة، وأعظمها القرآن الكريم، مما يشهد بصدق نبوته ورسالته الخاتمة، وأنزلنا إليكم القرآن هدًى ونورًا مبينًا.", "isBasmala": false, "translation_en": "O people! A proof has come to you from your Lord, and We sent down to you a clear light.", "translation_id": "Hai manusia, sesungguhnya telah datang kepadamu bukti kebenaran dari Tuhanmu. (Muhammad dengan mukjizatnya) dan telah Kami turunkan kepadamu cahaya yang terang benderang (Al Quran).", "manzil": 1, "manzil_display": ""}, {"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 175, "text": "فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَٱعۡتَصَمُوا۟ بِهِۦ فَسَیُدۡخِلُهُمۡ فِی رَحۡمَةࣲ مِّنۡهُ وَفَضۡلࣲ وَیَهۡدِیهِمۡ إِلَیۡهِ صِرَ ٰطࣰا مُّسۡتَقِیمࣰا ۝١٧٥", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "فأمَّا الذين صدَّقوا بالله اعتقادًا وقولا وعملا واستمسكوا بالنور الذي أُنزل إليهم، فسيدخلهم الجنة رحمة منه وفضلا ويوفقهم إلى سلوك الطريق المستقيم المفضي إلى روضات الجنات.", "isBasmala": false, "translation_en": "As for those who believe in God, and hold fast to Him, He will admit them into mercy and grace from Him, and will guide them to Himself in a straight path.", "translation_id": "Adapun orang-orang yang beriman kepada Allah dan berpegang teguh kepada (agama)-Nya niscaya Allah akan memasukkan mereka ke dalam rahmat yang besar dari-Nya (surga) dan limpahan karunia-Nya. Dan menunjuki mereka kepada jalan yang lurus (untuk sampai) kepada-Nya.", "manzil": 1, "manzil_display": ""}], "106": [{"sura": 4, "sura_name": "النساء", "revelation": "Madaniyah", "aya": 176, "text": "یَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ یُفۡتِیكُمۡ فِی ٱلۡكَلَـٰلَةِۚ إِنِ ٱمۡرُؤٌا۟ هَلَكَ لَیۡسَ لَهُۥ وَلَدࣱ وَلَهُۥۤ أُخۡتࣱ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ یَرِثُهَاۤ إِن لَّمۡ یَكُن لَّهَا وَلَدࣱۚ فَإِن كَانَتَا ٱثۡنَتَیۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوۤا۟ إِخۡوَةࣰ رِّجَالࣰا وَنِسَاۤءࣰ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَیَیۡنِۗ یُبَیِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّوا۟ۗ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمُۢ ۝١٧٦", "juz": 6, "hizb": "(*¼ ح 11*)", "tafsir": "يسألونك -أيها الرسول- عن حكم ميراث الكلالة، وهو من مات وليس له ولدٌ ولا والد، قل: الله يُبيِّن لكم الحكم فيها: إن مات امرؤ ليس له ولد ولا والد، وله أخت لأبيه وأمه، أو لأبيه فقط، فلها نصف تركته، ويرث أخوها شقيقًا كان أو لأب جميع مالها إذا ماتت وليس لها ولد ولا والد. فإن كان لمن مات كلالةً أختان فلهما الثلثان مما ترك. وإذا اجتمع الذكور من الإخوة لغير أم مع الإناث فللذكر مثل نصيب الأنثيين من أخواته. يُبيِّن الله لكم قسمة المواريث وحكم الكلالة، لئلا تضلوا عن الحقِّ في أمر المواريث. والله عالم بعواقب الأمور، وما فيها من الخير لعباده.", "isBasmala": false, "translation_en": "They ask you for a ruling. Say, \"God gives you a ruling concerning the person who has neither parents nor children.\" If a man dies, and leaves no children, and he had a sister, she receives one-half of what he leaves. And he inherits from her if she leaves no children. But if there are two sisters, they receive two-thirds of what he leaves. If the siblings are men and women, the male receives the share of two females.\" God makes things clear for you, lest you err. God is Aware of everything.", "translation_id": "Mereka meminta fatwa kepadamu (tentang kalalah). Katakanlah: \"Allah memberi fatwa kepadamu tentang kalalah (yaitu): jika seorang meninggal dunia, dan ia tidak mempunyai anak dan mempunyai saudara perempuan, maka bagi saudaranya yang perempuan itu seperdua dari harta yang ditinggalkannya, dan saudaranya yang laki-laki mempusakai (seluruh harta saudara perempuan), jika ia tidak mempunyai anak; tetapi jika saudara perempuan itu dua orang, maka bagi keduanya dua pertiga dari harta yang ditinggalkan oleh yang meninggal. Dan jika mereka (ahli waris itu terdiri dari) saudara-saudara laki dan perempuan, maka bahagian seorang saudara laki-laki sebanyak bahagian dua orang saudara perempuan. Allah menerangkan (hukum ini) kepadamu, supaya kamu tidak sesat. Dan Allah Maha Mengetahui segala sesuatu.", "manzil": 1, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 7, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 1, "text": "۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَوۡفُوا۟ بِٱلۡعُقُودِۚ أُحِلَّتۡ لَكُم بَهِیمَةُ ٱلۡأَنۡعَـٰمِ إِلَّا مَا یُتۡلَىٰ عَلَیۡكُمۡ غَیۡرَ مُحِلِّی ٱلصَّیۡدِ وَأَنتُمۡ حُرُمٌۗ إِنَّ ٱللَّهَ یَحۡكُمُ مَا یُرِیدُ ۝١", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، أتِمُّوا عهود الله الموثقة، من الإيمان بشرائع الدين، والانقياد لها، وأَدُّوا العهود لبعضكم على بعض من الأمانات، والبيوع وغيرها، مما لم يخالف كتاب الله، وسنة رسوله محمد صلى الله عليه وسلم. وقد أحَلَّ الله لكم البهيمة من الأنعام، وهي الإبلُ والبقر والغنم، إلا ما بيَّنه لكم من تحريم الميتة والدم وغير ذلك، ومن تحريم الصيد وأنتم محرمون. إن الله يحكم ما يشاء وَفْق حكمته وعدله.", "isBasmala": false, "translation_en": "O you who believe! Fulfill your commitments. Livestock animals are permitted for you, except those specified to you; but not wild game while you are in pilgrim sanctity. God decrees whatever He wills.", "translation_id": "Hai orang-orang yang beriman, penuhilah aqad-aqad itu. Dihalalkan bagimu binatang ternak, kecuali yang akan dibacakan kepadamu. (Yang demikian itu) dengan tidak menghalalkan berburu ketika kamu sedang mengerjakan haji. Sesungguhnya Allah menetapkan hukum-hukum menurut yang dikehendaki-Nya.", "manzil": 2, "manzil_display": "المنزل الثاني (م م 2)"}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 2, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُحِلُّوا۟ شَعَـٰۤىِٕرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡیَ وَلَا ٱلۡقَلَـٰۤىِٕدَ وَلَاۤ ءَاۤمِّینَ ٱلۡبَیۡتَ ٱلۡحَرَامَ یَبۡتَغُونَ فَضۡلࣰا مِّن رَّبِّهِمۡ وَرِضۡوَ ٰنࣰاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُوا۟ۚ وَلَا یَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُوا۟ۘ وَتَعَاوَنُوا۟ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُوا۟ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰنِۚ وَٱتَّقُوا۟ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ ۝٢", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تتعدَّوا حدود الله ومعالمه، ولا تستحِلُّوا القتال في الأشهر الحرم، وهي: ذو القعدة وذو الحجة والمحرم ورجب، وكان ذلك في صدر الإسلام، ولا تستحِلُّوا حرمة الهَدْي، ولا ما قُلِّدَ منه؛ إذ كانوا يضعون القلائد، وهي ضفائر من صوف أو وَبَر في الرقاب علامةً على أن البهيمة هَدْيٌ وأن الرجل يريد الحج، ولا تَسْتَحِلُّوا قتال قاصدي البيت الحرام الذين يبتغون من فضل الله ما يصلح معايشهم ويرضي ربهم. وإذا حللتم من إحرامكم حلَّ لكم الصيد، ولا يحمِلَنَّكم بُغْض قوم من أجل أن منعوكم من الوصول إلى المسجد الحرام -كما حدث عام \"الحديبية\"- على ترك العدل فيهم. وتعاونوا -أيها المؤمنون فيما بينكم- على فِعْل الخير، وتقوى الله، ولا تعاونوا على ما فيه إثم ومعصية وتجاوز لحدود الله، واحذروا مخالفة أمر الله فإنه شديد العقاب.", "isBasmala": false, "translation_en": "O you who believe! Do not violate God's sacraments, nor the Sacred Month, nor the offerings, nor the garlanded, nor those heading for the Sacred House seeking blessings from their Lord and approval. When you have left the pilgrim sanctity, you may hunt. And let not the hatred of people who barred you from the Sacred Mosque incite you to aggression. And cooperate with one another in virtuous conduct and conscience, and do not cooperate with one another in sin and hostility. And fear God. God is severe in punishment.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu melanggar syi'ar-syi'ar Allah, dan jangan melanggar kehormatan bulan-bulan haram, jangan (mengganggu) binatang-binatang had-ya, dan binatang-binatang qalaa-id, dan jangan (pula) mengganggu orang-orang yang mengunjungi Baitullah sedang mereka mencari kurnia dan keridhaan dari Tuhannya dan apabila kamu telah menyelesaikan ibadah haji, maka bolehlah berburu. Dan janganlah sekali-kali kebencian(mu) kepada sesuatu kaum karena mereka menghalang-halangi kamu dari Masjidilharam, mendorongmu berbuat aniaya (kepada mereka). Dan tolong-menolonglah kamu dalam (mengerjakan) kebajikan dan takwa, dan jangan tolong-menolong dalam berbuat dosa dan pelanggaran. Dan bertakwalah kamu kepada Allah, sesungguhnya Allah amat berat siksa-Nya.", "manzil": 2, "manzil_display": ""}], "107": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 3, "text": "حُرِّمَتۡ عَلَیۡكُمُ ٱلۡمَیۡتَةُ وَٱلدَّمُ وَلَحۡمُ ٱلۡخِنزِیرِ وَمَاۤ أُهِلَّ لِغَیۡرِ ٱللَّهِ بِهِۦ وَٱلۡمُنۡخَنِقَةُ وَٱلۡمَوۡقُوذَةُ وَٱلۡمُتَرَدِّیَةُ وَٱلنَّطِیحَةُ وَمَاۤ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّیۡتُمۡ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ وَأَن تَسۡتَقۡسِمُوا۟ بِٱلۡأَزۡلَـٰمِۚ ذَ ٰلِكُمۡ فِسۡقٌۗ ٱلۡیَوۡمَ یَىِٕسَ ٱلَّذِینَ كَفَرُوا۟ مِن دِینِكُمۡ فَلَا تَخۡشَوۡهُمۡ وَٱخۡشَوۡنِۚ ٱلۡیَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِینَكُمۡ وَأَتۡمَمۡتُ عَلَیۡكُمۡ نِعۡمَتِی وَرَضِیتُ لَكُمُ ٱلۡإِسۡلَـٰمَ دِینࣰاۚ فَمَنِ ٱضۡطُرَّ فِی مَخۡمَصَةٍ غَیۡرَ مُتَجَانِفࣲ لِّإِثۡمࣲ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝٣", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "حرَّم الله عليكم الميتة، وهي الحيوان الذي تفارقه الحياة بدون ذكاة، وحرَّم عليكم الدم السائل المُراق، ولحم الخنزير، وما ذُكِر عليه غير اسم الله عند الذبح، والمنخنقة التي حُبِس نَفَسُها حتى ماتت، والموقوذة وهي التي ضُربت بعصا أو حجر حتى ماتت، والمُتَرَدِّية وهي التي سقطت من مكان عال أو هَوَت في بئر فماتت، والنطيحة وهي التي ضَرَبَتْها أخرى بقرنها فماتت، وحرَّم الله عليكم البهيمة التي أكلها السبُع، كالأسد والنمر والذئب، ونحو ذلك. واستثنى -سبحانه- مما حرَّمه من المنخنقة وما بعدها ما أدركتم ذكاته قبل أن يموت فهو حلال لكم، وحرَّم الله عليكم ما ذُبِح لغير الله على ما يُنصب للعبادة من حجر أو غيره، وحرَّم الله عليكم أن تطلبوا عِلْم ما قُسِم لكم أو لم يقسم بالأزلام، وهي القداح التي كانوا يستقسمون بها إذا أرادوا أمرًا قبل أن يقدموا عليه. ذلكم المذكور في الآية من المحرمات -إذا ارتُكبت- خروج عن أمر الله وطاعته إلى معصيته. الآن انقطع طمع الكفار من دينكم أن ترتدوا عنه إلى الشرك بعد أن نصَرْتُكم عليهم، فلا تخافوهم وخافوني. اليوم أكملت لكم دينكم دين الإسلام بتحقيق النصر وإتمام الشريعة، وأتممت عليكم نعمتي بإخراجكم من ظلمات الجاهلية إلى نور الإيمان، ورضيت لكم الإسلام دينًا فالزموه، ولا تفارقوه. فمن اضطرَّ في مجاعة إلى أكل الميتة، وكان غير مائل عمدًا لإثم، فله تناوله، فإن الله غفور له، رحيم به.", "isBasmala": false, "translation_en": "Prohibited for you are carrion, blood, the flesh of swine, and animals dedicated to other than God; also the flesh of animals strangled, killed violently, killed by a fall, gored to death, mangled by wild animals-except what you rescue, and animals sacrificed on altars; and the practice of drawing lots. For it is immoral. Today, those who disbelieve have despaired of your religion, so do not fear them, but fear Me. Today I have perfected your religion for you, and have completed My favor upon you, and have approved Islam as a religion for you. But whoever is compelled by hunger, with no intent of wrongdoing-God is Forgiving and Merciful.", "translation_id": "Diharamkan bagimu (memakan) bangkai, darah, daging babi, (daging hewan) yang disembelih atas nama selain Allah, yang tercekik, yang terpukul, yang jatuh, yang ditanduk, dan diterkam binatang buas, kecuali yang sempat kamu menyembelihnya, dan (diharamkan bagimu) yang disembelih untuk berhala. Dan (diharamkan juga) mengundi nasib dengan anak panah, (mengundi nasib dengan anak panah itu) adalah kefasikan. Pada hari ini orang-orang kafir telah putus asa untuk (mengalahkan) agamamu, sebab itu janganlah kamu takut kepada mereka dan takutlah kepada-Ku. Pada hari ini telah Kusempurnakan untuk kamu agamamu, dan telah Ku-cukupkan kepadamu nikmat-Ku, dan telah Ku-ridhai Islam itu jadi agama bagimu. Maka barang siapa terpaksa karena kelaparan tanpa sengaja berbuat dosa, sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 4, "text": "یَسۡـَٔلُونَكَ مَاذَاۤ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّیِّبَـٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِینَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُوا۟ مِمَّاۤ أَمۡسَكۡنَ عَلَیۡكُمۡ وَٱذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ عَلَیۡهِۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ ۝٤", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "يسألك أصحابك -أيها النبي-: ماذا أُحِلَّ لهم أَكْلُه؟ قل لهم: أُحِلَّ لكم الطيبات وصيدُ ما دَرَّبتموه من ذوات المخالب والأنياب من الكلاب والفهود والصقور ونحوها مما يُعَلَّم، تعلمونهن طلب الصيد لكم، مما علمكم الله، فكلوا مما أمسكن لكم، واذكروا اسم الله عند إرسالها للصيد، وخافوا الله فيما أمركم به وفيما نهاكم عنه. إن الله سريع الحساب.", "isBasmala": false, "translation_en": "They ask you what is permitted for them. Say, \"Permitted for you are all good things, including what trained dogs and falcons catch for you.\" You train them according to what God has taught you. So eat from what they catch for you, and pronounce God's name over it. And fear God. God is Swift in reckoning.", "translation_id": "Mereka menanyakan kepadamu: \"Apakah yang dihalalkan bagi mereka?\". Katakanlah: \"Dihalalkan bagimu yang baik-baik dan (buruan yang ditangkap) oleh binatang buas yang telah kamu ajar dengan melatih nya untuk berburu; kamu mengajarnya menurut apa yang telah diajarkan Allah kepadamu. Maka makanlah dari apa yang ditangkapnya untukmu, dan sebutlah nama Allah atas binatang buas itu (waktu melepaskannya). Dan bertakwalah kepada Allah, sesungguhnya Allah amat cepat hisab-Nya.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 5, "text": "ٱلۡیَوۡمَ أُحِلَّ لَكُمُ ٱلطَّیِّبَـٰتُۖ وَطَعَامُ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ حِلࣱّ لَّكُمۡ وَطَعَامُكُمۡ حِلࣱّ لَّهُمۡۖ وَٱلۡمُحۡصَنَـٰتُ مِنَ ٱلۡمُؤۡمِنَـٰتِ وَٱلۡمُحۡصَنَـٰتُ مِنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلِكُمۡ إِذَاۤ ءَاتَیۡتُمُوهُنَّ أُجُورَهُنَّ مُحۡصِنِینَ غَیۡرَ مُسَـٰفِحِینَ وَلَا مُتَّخِذِیۤ أَخۡدَانࣲۗ وَمَن یَكۡفُرۡ بِٱلۡإِیمَـٰنِ فَقَدۡ حَبِطَ عَمَلُهُۥ وَهُوَ فِی ٱلۡـَٔاخِرَةِ مِنَ ٱلۡخَـٰسِرِینَ ۝٥", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "ومن تمام نعمة الله عليكم اليوم -أيها المؤمنون- أن أَحَلَّ لكم الحلال الطيب، وذبائحُ اليهود والنصارى -إن ذكَّوها حَسَبَ شرعهم- حلال لكم وذبائحكم حلال لهم. وأَحَلَّ لكم -أيها المؤمنون- نكاح المحصنات، وهُنَّ الحرائر من النساء المؤمنات، العفيفات عن الزنى، وكذلك نكاحَ الحرائر العفيفات من اليهود والنصارى إذا أعطيتموهُنَّ مهورهن، وكنتم أعِفَّاء غير مرتكبين للزنى، ولا متخذي عشيقات، وأمِنتم من التأثر بدينهن. ومن يجحد شرائع الإيمان فقد بطل عمله، وهو يوم القيامة من الخاسرين.", "isBasmala": false, "translation_en": "Today all good things are made lawful for you. And the food of those given the Scripture is lawful for you, and your food is lawful for them. So are chaste believing women, and chaste women from the people who were given the Scripture before you, provided you give them their dowries, and take them in marriage, not in adultery, nor as mistresses. But whoever rejects faith, his work will be in vain, and in the Hereafter he will be among the losers.", "translation_id": "Pada hari ini dihalalkan bagimu yang baik-baik. Makanan (sembelihan) orang-orang yang diberi Al Kitab itu halal bagimu, dan makanan kamu halal (pula) bagi mereka. (Dan dihalalkan mangawini) wanita yang menjaga kehormatan diantara wanita-wanita yang beriman dan wanita-wanita yang menjaga kehormatan di antara orang-orang yang diberi Al Kitab sebelum kamu, bila kamu telah membayar mas kawin mereka dengan maksud menikahinya, tidak dengan maksud berzina dan tidak (pula) menjadikannya gundik-gundik. Barangsiapa yang kafir sesudah beriman (tidak menerima hukum-hukum Islam) maka hapuslah amalannya dan ia di hari kiamat termasuk orang-orang merugi.", "manzil": 2, "manzil_display": ""}], "108": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 6, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُوا۟ وُجُوهَكُمۡ وَأَیۡدِیَكُمۡ إِلَى ٱلۡمَرَافِقِ وَٱمۡسَحُوا۟ بِرُءُوسِكُمۡ وَأَرۡجُلَكُمۡ إِلَى ٱلۡكَعۡبَیۡنِۚ وَإِن كُنتُمۡ جُنُبࣰا فَٱطَّهَّرُوا۟ۚ وَإِن كُنتُم مَّرۡضَىٰۤ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَاۤءَ أَحَدࣱ مِّنكُم مِّنَ ٱلۡغَاۤىِٕطِ أَوۡ لَـٰمَسۡتُمُ ٱلنِّسَاۤءَ فَلَمۡ تَجِدُوا۟ مَاۤءࣰ فَتَیَمَّمُوا۟ صَعِیدࣰا طَیِّبࣰا فَٱمۡسَحُوا۟ بِوُجُوهِكُمۡ وَأَیۡدِیكُم مِّنۡهُۚ مَا یُرِیدُ ٱللَّهُ لِیَجۡعَلَ عَلَیۡكُم مِّنۡ حَرَجࣲ وَلَـٰكِن یُرِیدُ لِیُطَهِّرَكُمۡ وَلِیُتِمَّ نِعۡمَتَهُۥ عَلَیۡكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ ۝٦", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "يا أيها الذين آمنوا إذا أردتم القيام إلى الصلاة، وأنتم على غير طهارة فاغسلوا وجوهكم وأيديكم مع المرافق (والمِرْفَق: المِفْصَل الذي بين الذراع والعَضُد) وامسحوا رؤوسكم، واغسلوا أرجلكم مع الكعبين (وهما: العظمان البارزان عند ملتقى الساق بالقدم). وإن أصابكم الحدث الأكبر فتطهروا بالاغتسال منه قبل الصلاة. فإن كنتم مرضى، أو على سفر في حال الصحة، أو قضى أحدكم حاجته، أو جامع زوجته فلم تجدوا ماء فاضربوا بأيديكم وجه الأرض، وامسحوا وجوهكم وأيديكم منه. ما يريد الله في أمر الطهارة أن يُضَيِّق عليكم، بل أباح التيمم توسعةً عليكم، ورحمة بكم، إذ جعله بديلا للماء في الطهارة، فكانت رخصة التيمُّم من تمام النعم التي تقتضي شكر المنعم؛ بطاعته فيما أمر وفيما نهى.", "isBasmala": false, "translation_en": "O you who believe! When you rise to pray, wash your faces and your hands and arms to the elbows, and wipe your heads, and your feet to the ankles. If you had intercourse, then purify yourselves. If you are ill, or travelling, or one of you returns from the toilet, or you had contact with women, and could not find water, then use some clean sand and wipe your faces and hands with it. God does not intend to burden you, but He intends to purify you, and to complete His blessing upon you, that you may be thankful.", "translation_id": "Hai orang-orang yang beriman, apabila kamu hendak mengerjakan shalat, maka basuhlah mukamu dan tanganmu sampai dengan siku, dan sapulah kepalamu dan (basuh) kakimu sampai dengan kedua mata kaki, dan jika kamu junub maka mandilah, dan jika kamu sakit atau dalam perjalanan atau kembali dari tempat buang air (kakus) atau menyentuh perempuan, lalu kamu tidak memperoleh air, maka bertayammumlah dengan tanah yang baik (bersih); sapulah mukamu dan tanganmu dengan tanah itu. Allah tidak hendak menyulitkan kamu, tetapi Dia hendak membersihkan kamu dan menyempurnakan nikmat-Nya bagimu, supaya kamu bersyukur.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 7, "text": "وَٱذۡكُرُوا۟ نِعۡمَةَ ٱللَّهِ عَلَیۡكُمۡ وَمِیثَـٰقَهُ ٱلَّذِی وَاثَقَكُم بِهِۦۤ إِذۡ قُلۡتُمۡ سَمِعۡنَا وَأَطَعۡنَاۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝٧", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "واذكروا نعمة الله عليكم فيما شَرَعه لكم، واذكروا عهده الذي أخذه تعالى عليكم من الإيمان بالله ورسوله محمد صلى الله عليه وسلم، والسمع والطاعة لهما، واتقوا الله فيما أمركم به ونهاكم عنه. إن الله عليمٌ بما تُسِرُّونه في نفوسكم.", "isBasmala": false, "translation_en": "And Remember God's blessings upon you, and His covenant which He covenanted with you; when you said, \"We hear and we obey.\" And remain conscious of God, for God knows what the hearts contain.", "translation_id": "Dan ingatlah karunia Allah kepadamu dan perjanjian-Nya yang telah diikat-Nya dengan kamu, ketika kamu mengatakan: \"Kami dengar dan kami taati\". Dan bertakwalah kepada Allah, sesungguhnya Allah Mengetahui isi hati(mu).", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 8, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُونُوا۟ قَوَّ ٰمِینَ لِلَّهِ شُهَدَاۤءَ بِٱلۡقِسۡطِۖ وَلَا یَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ عَلَىٰۤ أَلَّا تَعۡدِلُوا۟ۚ ٱعۡدِلُوا۟ هُوَ أَقۡرَبُ لِلتَّقۡوَىٰۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِیرُۢ بِمَا تَعۡمَلُونَ ۝٨", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "يا أيها الذين آمَنوا بالله ورسوله محمد صلى الله عليه وسلم كونوا قوَّامين بالحق، ابتغاء وجه الله، شُهداء بالعدل، ولا يحملنكم بُغْضُ قوم على ألا تعدلوا، اعدِلوا بين الأعداء والأحباب على درجة سواء، فذلك العدل أقرب لخشية الله، واحذروا أن تجوروا. إن الله خبير بما تعملون، وسيجازيكم به.", "isBasmala": false, "translation_en": "O you who believe! Be upright to God, witnessing with justice; and let not the hatred of a certain people prevent you from acting justly. Adhere to justice, for that is nearer to piety; and fear God. God is informed of what you do.", "translation_id": "Hai orang-orang yang beriman hendaklah kamu jadi orang-orang yang selalu menegakkan (kebenaran) karena Allah, menjadi saksi dengan adil. Dan janganlah sekali-kali kebencianmu terhadap sesuatu kaum, mendorong kamu untuk berlaku tidak adil. Berlaku adillah, karena adil itu lebih dekat kepada takwa. Dan bertakwalah kepada Allah, sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 9, "text": "وَعَدَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرٌ عَظِیمࣱ ۝٩", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "وعد الله الذين صدَّقوا الله ورسوله وعملوا الصالحات أن يغفر لهم ذنوبهم، وأن يثيبهم على ذلك الجنة، والله لا يخلف وعده.", "isBasmala": false, "translation_en": "God has promised those who believe and work righteousness: they will have forgiveness and a great reward.", "translation_id": "Allah telah menjanjikan kepada orang-orang yang beriman dan yang beramal saleh, (bahwa) untuk mereka ampunan dan pahala yang besar.", "manzil": 2, "manzil_display": ""}], "109": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 10, "text": "وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ ۝١٠", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "والذين جحدوا وحدانية الله الدالة على الحق المبين، وكذَّبوا بأدلته التي جاءت بها الرسل، هم أهل النار الملازمون لها.", "isBasmala": false, "translation_en": "As for those who disbelieve and reject Our revelations-these are the inmates of Hell.", "translation_id": "Adapun orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itu adalah penghuni neraka.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 11, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱذۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ هَمَّ قَوۡمٌ أَن یَبۡسُطُوۤا۟ إِلَیۡكُمۡ أَیۡدِیَهُمۡ فَكَفَّ أَیۡدِیَهُمۡ عَنكُمۡۖ وَٱتَّقُوا۟ ٱللَّهَۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ۝١١", "juz": 6, "hizb": "(*½ ح 11*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه اذكروا ما أنعم الله به عليكم من نعمة الأمنِ، وإلقاءِ الرعب في قلوب أعدائكم الذين أرادوا أن يبطشوا بكم، فصرفهم الله عنكم، وحال بينهم وبين ما أرادوه بكم، واتقوا الله واحذروه، وتوكلوا على الله وحده في أموركم الدينية والدنيوية، وثِقوا بعونه ونصره.", "isBasmala": false, "translation_en": "O you who believe! Remember God's blessings upon you; when certain people intended to extend their hands against you, and He restrained their hands from you. So reverence God, and in God let the believers put their trust.", "translation_id": "Hai orang-orang yang beriman, ingatlah kamu akan nikmat Allah (yang diberikan-Nya) kepadamu, di waktu suatu kaum bermaksud hendak menggerakkan tangannya kepadamu (untuk berbuat jahat), maka Allah menahan tangan mereka dari kamu. Dan bertakwalah kepada Allah, dan hanya kepada Allah sajalah orang-orang mukmin itu harus bertawakkal.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 12, "text": "۞ وَلَقَدۡ أَخَذَ ٱللَّهُ مِیثَـٰقَ بَنِیۤ إِسۡرَ ٰۤءِیلَ وَبَعَثۡنَا مِنۡهُمُ ٱثۡنَیۡ عَشَرَ نَقِیبࣰاۖ وَقَالَ ٱللَّهُ إِنِّی مَعَكُمۡۖ لَىِٕنۡ أَقَمۡتُمُ ٱلصَّلَوٰةَ وَءَاتَیۡتُمُ ٱلزَّكَوٰةَ وَءَامَنتُم بِرُسُلِی وَعَزَّرۡتُمُوهُمۡ وَأَقۡرَضۡتُمُ ٱللَّهَ قَرۡضًا حَسَنࣰا لَّأُكَفِّرَنَّ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَلَأُدۡخِلَنَّكُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۚ فَمَن كَفَرَ بَعۡدَ ذَ ٰلِكَ مِنكُمۡ فَقَدۡ ضَلَّ سَوَاۤءَ ٱلسَّبِیلِ ۝١٢", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "ولقد أخذ الله العهد المؤكَّد على بني إسرائيل أن يخلصوا له العبادة وحده، وأمر الله موسى أن يجعل عليهم اثني عشر عريفًا بعدد فروعهم، يأخذون عليهم العهد بالسمع والطاعة لله ولرسوله ولكتابه، وقال الله لبني إسرائيل: إني معكم بحفظي ونصري، لئن أقمتم الصلاة، وأعطيتم الزكاة المفروضة مستحقيها، وصدَّقتم برسلي فيما أخبروكم به ونصرتموهم، وأنفقتم في سبيلي، لأكفِّرنَّ عنكم سيئاتكم، ولأدْخِلَنَّكُم جناتٍ تجري من تحت قصورها الأنهار، فمن جحد هذا الميثاق منكم فقد عدل عن طريق الحق إلى طريق الضلال.", "isBasmala": false, "translation_en": "God received a pledge from the Children of Israel, and We raised among them twelve chiefs. God said, \"I am with you; if you perform the prayer, and pay the alms, and believe in My messengers and support them, and lend God a loan of righteousness; I will remit your sins, and admit you into Gardens beneath which rivers flow. But whoever among you disbelieves afterwards has strayed from the right way.\"", "translation_id": "Dan sesungguhnya Allah telah mengambil perjanjian (dari) Bani Israil dan telah Kami angkat diantara mereka 12 orang pemimpin dan Allah berfirman: \"Sesungguhnya Aku beserta kamu, sesungguhnya jika kamu mendirikan shalat dan menunaikan zakat serta beriman kepada rasul-rasul-Ku dan kamu bantu mereka dan kamu pinjamkan kepada Allah pinjaman yang baik sesungguhnya Aku akan menutupi dosa-dosamu. Dan sesungguhnya kamu akan Kumasukkan ke dalam surga yang mengalir air didalamnya sungai-sungai. Maka barangsiapa yang kafir di antaramu sesudah itu, sesungguhnya ia telah tersesat dari jalan yang lurus.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 13, "text": "فَبِمَا نَقۡضِهِم مِّیثَـٰقَهُمۡ لَعَنَّـٰهُمۡ وَجَعَلۡنَا قُلُوبَهُمۡ قَـٰسِیَةࣰۖ یُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَنَسُوا۟ حَظࣰّا مِّمَّا ذُكِّرُوا۟ بِهِۦۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَاۤىِٕنَةࣲ مِّنۡهُمۡ إِلَّا قَلِیلࣰا مِّنۡهُمۡۖ فَٱعۡفُ عَنۡهُمۡ وَٱصۡفَحۡۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُحۡسِنِینَ ۝١٣", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "فبسبب نقض هؤلاء اليهود لعهودهم المؤكَّدة طردناهم من رحمتنا، وجعلنا قلوبهم غليظة لا تلين للإيمان، يبدلون كلام الله الذي أنزله على موسى، وهو التوراة، وتركوا نصيبًا مما ذُكِّروا به، فلم يعملوا به. ولا تزال -أيها الرسول- تجد من اليهود خيانةً وغَدرًا، فهم على منهاج أسلافهم إلا قليلا منهم، فاعف عن سوء معاملتهم لك، واصفح عنهم، فإن الله يحب مَن أحسن العفو والصفح إلى من أساء إليه. (وهكذا يجد أهل الزيغ سبيلا إلى مقاصدهم السيئة بتحريف كلام الله وتأويله على غير وجهه، فإن عجَزوا عن التحريف والتأويل تركوا ما لا يتفق مع أهوائهم مِن شرع الله الذي لا يثبت عليه إلا القليل ممن عصمه الله منهم).", "isBasmala": false, "translation_en": "Because of their breaking their pledge, We cursed them, and made their hearts hard. They twist the words out of their context, and they disregarded some of what they were reminded of. You will always witness deceit from them, except for a few of them. But pardon them, and overlook. God loves the doers of good.", "translation_id": "(Tetapi) karena mereka melanggar janjinya, Kami kutuki mereka, dan Kami jadikan hati mereka keras membatu. Mereka suka merubah perkataan (Allah) dari tempat-tempatnya, dan mereka (sengaja) melupakan sebagian dari apa yang mereka telah diperingatkan dengannya, dan kamu (Muhammad) senantiasa akan melihat kekhianatan dari mereka kecuali sedikit diantara mereka (yang tidak berkhianat), maka maafkanlah mereka dan biarkan mereka, sesungguhnya Allah menyukai orang-orang yang berbuat baik.", "manzil": 2, "manzil_display": ""}], "110": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 14, "text": "وَمِنَ ٱلَّذِینَ قَالُوۤا۟ إِنَّا نَصَـٰرَىٰۤ أَخَذۡنَا مِیثَـٰقَهُمۡ فَنَسُوا۟ حَظࣰّا مِّمَّا ذُكِّرُوا۟ بِهِۦ فَأَغۡرَیۡنَا بَیۡنَهُمُ ٱلۡعَدَاوَةَ وَٱلۡبَغۡضَاۤءَ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِۚ وَسَوۡفَ یُنَبِّئُهُمُ ٱللَّهُ بِمَا كَانُوا۟ یَصۡنَعُونَ ۝١٤", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "وأخذنا على الذين ادَّعوا أنهم أتباع المسيح عيسى -وليسوا كذلك- العهد المؤكد الذي أخذناه على بني إسرائيل: بأن يُتابعوا رسولهم وينصروه ويؤازروه، فبدَّلوا دينهم، وتركوا نصيبًا مما ذكروا به، فلم يعملوا به، كما صنع اليهود، فألقينا بينهم العداوة والبغضاء إلى يوم القيامة، وسوف ينبئهم الله بما كانوا يصنعون يوم الحساب، وسيعاقبهم على صنيعهم.", "isBasmala": false, "translation_en": "And from those who say, \"We are Christians,\" We received their pledge, but they neglected some of what they were reminded of. So We provoked enmity and hatred among them until the Day of Resurrection; God will then inform them of what they used to craft.", "translation_id": "Dan diantara orang-orang yang mengatakan: \"Sesungguhnya kami ini orang-orang Nasrani\", ada yang telah kami ambil perjanjian mereka, tetapi mereka (sengaja) melupakan sebagian dari apa yang mereka telah diberi peringatan dengannya; maka Kami timbulkan di antara mereka permusuhan dan kebencian sampai hari kiamat. Dan kelak Allah akan memberitakan kepada mereka apa yang mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 15, "text": "یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ قَدۡ جَاۤءَكُمۡ رَسُولُنَا یُبَیِّنُ لَكُمۡ كَثِیرࣰا مِّمَّا كُنتُمۡ تُخۡفُونَ مِنَ ٱلۡكِتَـٰبِ وَیَعۡفُوا۟ عَن كَثِیرࣲۚ قَدۡ جَاۤءَكُم مِّنَ ٱللَّهِ نُورࣱ وَكِتَـٰبࣱ مُّبِینࣱ ۝١٥", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "يا أهل الكتاب من اليهود والنصارى، قد جاءكم رسولنا محمد صلى الله عليه وسلم يبيِّن لكم كثيرًا مما كنتم تُخْفونه عن الناس مما في التوراة والإنجيل، ويترك بيان ما لا تقتضيه الحكمة. قد جاءكم من الله نور وكتاب مبين: وهو القرآن الكريم.", "isBasmala": false, "translation_en": "O People of the Book! Our Messenger has come to you, clarifying for you much of what you kept hidden of the Book, and overlooking much. A light from God has come to you, and a clear Book.", "translation_id": "Hai Ahli Kitab, sesungguhnya telah datang kepadamu Rasul Kami, menjelaskan kepadamu banyak dari isi Al Kitab yang kamu sembunyi kan, dan banyak (pula yang) dibiarkannya. Sesungguhnya telah datang kepadamu cahaya dari Allah, dan Kitab yang menerangkan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 16, "text": "یَهۡدِی بِهِ ٱللَّهُ مَنِ ٱتَّبَعَ رِضۡوَ ٰنَهُۥ سُبُلَ ٱلسَّلَـٰمِ وَیُخۡرِجُهُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذۡنِهِۦ وَیَهۡدِیهِمۡ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝١٦", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "يهدي الله بهذا الكتاب المبين من اتبع رضا الله تعالى، طرق الأمن والسلامة، ويخرجهم بإذنه من ظلمات الكفر إلى نور الإيمان، ويوفقهم إلى دينه القويم.", "isBasmala": false, "translation_en": "God guides with it whoever follows His approval to the ways of peace, and He brings them out of darkness into light, by His permission, and He guides them in a straight path.", "translation_id": "Dengan kitab itulah Allah menunjuki orang-orang yang mengikuti keridhaan-Nya ke jalan keselamatan, dan (dengan kitab itu pula) Allah mengeluarkan orang-orang itu dari gelap gulita kepada cahaya yang terang benderang dengan seizin-Nya, dan menunjuki mereka ke jalan yang lurus.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 17, "text": "لَّقَدۡ كَفَرَ ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِیحُ ٱبۡنُ مَرۡیَمَۚ قُلۡ فَمَن یَمۡلِكُ مِنَ ٱللَّهِ شَیۡـًٔا إِنۡ أَرَادَ أَن یُهۡلِكَ ٱلۡمَسِیحَ ٱبۡنَ مَرۡیَمَ وَأُمَّهُۥ وَمَن فِی ٱلۡأَرۡضِ جَمِیعࣰاۗ وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۚ یَخۡلُقُ مَا یَشَاۤءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝١٧", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "لقد كفر النصارى القائلون بأن الله هو المسيح ابن مريم، قل -أيها الرسول- لهؤلاء الجهلة من النصارى: لو كان المسيح إلهًا كما يدَّعون لقَدرَ أن يدفع قضاء الله إذا جاءه بإهلاكه وإهلاك أُمِّه ومَن في الأرض جميعًا، وقد ماتت أم عيسى فلم يدفع عنها الموت، كذلك لا يستطيع أن يدفع عن نفسه؛ لأنهما عبدان من عباد الله لا يقدران على دفع الهلاك عنهما، فهذا دليلٌ على أنه بشر كسائر بني آدم. وجميع الموجودات في السماوات والأرض ملك لله، يخلق ما يشاء ويوجده، وهو على كل شيء قدير. فحقيقة التوحيد توجب تفرُّد الله تعالى بصفات الربوبية والألوهية، فلا يشاركه أحد من خلقه في ذلك، وكثيرًا ما يقع الناس في الشرك والضلال بغلوهم في الأنبياء والصالحين، كما غلا النصارى في المسيح، فالكون كله لله، والخلق بيده وحده، وما يظهر من خوارق وآيات مَرَدُّه إلى الله. يخلق سبحانه ما يشاء، ويفعل ما يريد.", "isBasmala": false, "translation_en": "They disbelieve those who say, \"God is the Christ, the son of Mary.\" Say, \"Who can prevent God, if He willed, from annihilating the Christ son of Mary, and his mother, and everyone on earth?\" To God belongs the sovereignty of the heavens and the earth and what is between them. He creates whatever He wills, and God has power over everything.", "translation_id": "Sesungguhnya telah kafirlah orang-orang yang berkata: \"Sesungguhnya Allah itu ialah Al Masih putera Maryam\". Katakanlah: \"Maka siapakah (gerangan) yang dapat menghalang-halangi kehendak Allah, jika Dia hendak membinasakan Al Masih putera Maryam itu beserta ibunya dan seluruh orang-orang yang berada di bumi kesemuanya?\". Kepunyaan Allahlah kerajaan langit dan bumi dan apa yang ada diantara keduanya; Dia menciptakan apa yang dikehendaki-Nya. Dan Allah Maha Kuasa atas segala sesuatu.", "manzil": 2, "manzil_display": ""}], "111": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 18, "text": "وَقَالَتِ ٱلۡیَهُودُ وَٱلنَّصَـٰرَىٰ نَحۡنُ أَبۡنَـٰۤؤُا۟ ٱللَّهِ وَأَحِبَّـٰۤؤُهُۥۚ قُلۡ فَلِمَ یُعَذِّبُكُم بِذُنُوبِكُمۖ بَلۡ أَنتُم بَشَرࣱ مِّمَّنۡ خَلَقَۚ یَغۡفِرُ لِمَن یَشَاۤءُ وَیُعَذِّبُ مَن یَشَاۤءُۚ وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۖ وَإِلَیۡهِ ٱلۡمَصِیرُ ۝١٨", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "وزعم اليهود والنصارى أنهم أبناء الله وأحباؤه، قل لهم -أيها الرسول-: فَلأيِّ شيء يعذِّبكم بذنوبكم؟ فلو كنتم أحبابه ما عذبكم، فالله لا يحب إلا من أطاعه، وقل لهم: بل أنتم خلقٌ مثلُ سائر بني آدم، إن أحسنتُم جوزيتم بإحسانكم خيرا، وإن أسَأْتُم جوزيتم بإساءتكم شرًّا، فالله يغفر لمن يشاء، ويعذب من يشاء، وهو مالك الملك، يُصَرِّفه كما يشاء، وإليه المرجع، فيحكم بين عباده، ويجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "The Jews and the Christians say, \"We are the children of God, and His beloved.\" Say, \"Why then does He punish you for your sins?\" In fact, you are humans from among those He created. He forgives whom He wills, and He punishes whom He wills. To God belongs the dominion of the heavens and the earth and what lies between them, and to Him is the return.", "translation_id": "Orang-orang Yahudi dan Nasrani mengatakan: \"Kami ini adalah anak-anak Allah dan kekasih-kekasih-Nya\". Katakanlah: \"Maka mengapa Allah menyiksa kamu karena dosa-dosamu?\" (Kamu bukanlah anak-anak Allah dan kekasih-kekasih-Nya), tetapi kamu adalah manusia(biasa) diantara orang-orang yang diciptakan-Nya. Dia mengampuni bagi siapa yang dikehendaki-Nya dan menyiksa siapa yang dikehendaki-Nya. Dan Kepunyaan Allah-lah kerajaan antara keduanya. Dan kepada Allah-lah kembali (segala sesuatu).", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 19, "text": "یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ قَدۡ جَاۤءَكُمۡ رَسُولُنَا یُبَیِّنُ لَكُمۡ عَلَىٰ فَتۡرَةࣲ مِّنَ ٱلرُّسُلِ أَن تَقُولُوا۟ مَا جَاۤءَنَا مِنۢ بَشِیرࣲ وَلَا نَذِیرࣲۖ فَقَدۡ جَاۤءَكُم بَشِیرࣱ وَنَذِیرࣱۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝١٩", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "يا أيها اليهود والنصارى قد جاءكم رسولنا محمد صلى الله عليه وسلم، يُبيِّن لكم الحق والهدى بعد مُدَّة من الزمن بين إرساله بإرسال عيسى ابن مريم؛ لئلا تقولوا: ما جاءنا من بشير ولا نذير، فلا عُذرَ لكم بعد إرساله إليكم، فقد جاءكم من الله رسولٌ يبشِّر مَن آمن به، ويُنذِز مَن عصاه. والله على كل شيء قدير من عقاب العاصي وثواب المطيع.", "isBasmala": false, "translation_en": "O People of the Book! Our Messenger has come to you, making things clear to you-after a cessation of messengers-so that you cannot say, \"No preacher has come to us, and no warner.\" In fact, a preacher has come to you, and a warner; and God is Capable of everything.", "translation_id": "Hai Ahli Kitab, sesungguhnya telah datang kepada kamu Rasul Kami, menjelaskan (syari'at Kami) kepadamu ketika terputus (pengiriman) rasul-rasul agar kamu tidak mengatakan: \"Tidak ada datang kepada kami baik seorang pembawa berita gembira maupun seorang pemberi peringatan\". Sesungguhnya telah datang kepadamu pembawa berita gembira dan pemberi peringatan. Allah Maha Kuasa atas segala sesuatu.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 20, "text": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ یَـٰقَوۡمِ ٱذۡكُرُوا۟ نِعۡمَةَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ جَعَلَ فِیكُمۡ أَنۢبِیَاۤءَ وَجَعَلَكُم مُّلُوكࣰا وَءَاتَىٰكُم مَّا لَمۡ یُؤۡتِ أَحَدࣰا مِّنَ ٱلۡعَـٰلَمِینَ ۝٢٠", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "واذكر -أيها الرسول- إذ قال موسى عليه السلام لقومه: يا بني إسرائيل اذكروا نعمة الله عليكم، إذ جعل فيكم أنبياء، وجعلكم ملوكًا تملكون أمركم بعد أن كنتم مملوكين لفرعون وقومه، وقد منحكم من نعمه صنوفًا لم يمنحها أحدًا من عالَمي زمانكم.", "isBasmala": false, "translation_en": "When Moses said to his people, \"O my people, remember God's blessings upon you, when He placed prophets among you, and made you kings, and gave you what He never gave any other people.\"", "translation_id": "Dan (ingatlah) ketika Musa berkata kepada kaumnya: \"Hai kaumku, ingatlah nikmat Allah atasmu ketika Dia mengangkat nabi nabi diantaramu, dan dijadikan-Nya kamu orang-orang merdeka, dan diberikan-Nya kepadamu apa yang belum pernah diberikan-Nya kepada seorangpun diantara umat-umat yang lain\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 21, "text": "یَـٰقَوۡمِ ٱدۡخُلُوا۟ ٱلۡأَرۡضَ ٱلۡمُقَدَّسَةَ ٱلَّتِی كَتَبَ ٱللَّهُ لَكُمۡ وَلَا تَرۡتَدُّوا۟ عَلَىٰۤ أَدۡبَارِكُمۡ فَتَنقَلِبُوا۟ خَـٰسِرِینَ ۝٢١", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "يا قوم ادخلوا الأرض المقدسة -أي المطهرة، وهي \"بيت المقدس\" وما حولها- التي وعد الله أن تدخلوها وتقاتلوا مَن فيها من الكفار، ولا ترجعوا عن قتال الجبارين، فتخسروا خير الدنيا وخير الآخرة.", "isBasmala": false, "translation_en": "\"O my people, enter the Holy Land which God has assigned for you, and do not turn back, lest you return as losers.\"", "translation_id": "Hai kaumku, masuklah ke tanah suci (Palestina) yang telah ditentukan Allah bagimu, dan janganlah kamu lari kebelakang (karena takut kepada musuh), maka kamu menjadi orang-orang yang merugi.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 22, "text": "قَالُوا۟ یَـٰمُوسَىٰۤ إِنَّ فِیهَا قَوۡمࣰا جَبَّارِینَ وَإِنَّا لَن نَّدۡخُلَهَا حَتَّىٰ یَخۡرُجُوا۟ مِنۡهَا فَإِن یَخۡرُجُوا۟ مِنۡهَا فَإِنَّا دَ ٰخِلُونَ ۝٢٢", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "قالوا: يا موسى، إن فيها قومًا أشداء أقوياء، لا طاقة لنا بحربهم، وإنَّا لن نستطيع دخولها وهم فيها، فإن يخرجوا منها فإنَّا داخلون.", "isBasmala": false, "translation_en": "They said, \"O Moses, there are tyrannical people in it; we will not enter it until they leave it. If they leave it, we will be entering.\"", "translation_id": "Mereka berkata: \"Hai Musa, sesungguhnya dalam negeri itu ada orang-orang yang gagah perkasa, sesungguhnya kami sekali-kali tidak akan memasukinya sebelum mereka ke luar daripadanya. Jika mereka ke luar daripadanya, pasti kami akan memasukinya\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 23, "text": "قَالَ رَجُلَانِ مِنَ ٱلَّذِینَ یَخَافُونَ أَنۡعَمَ ٱللَّهُ عَلَیۡهِمَا ٱدۡخُلُوا۟ عَلَیۡهِمُ ٱلۡبَابَ فَإِذَا دَخَلۡتُمُوهُ فَإِنَّكُمۡ غَـٰلِبُونَۚ وَعَلَى ٱللَّهِ فَتَوَكَّلُوۤا۟ إِن كُنتُم مُّؤۡمِنِینَ ۝٢٣", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "قال رجلان من الذين يخشون الله تعالى، أنعم الله عليهما بطاعته وطاعة نبيِّه، لبني إسرائيل: ادخلوا على هؤلاء الجبارين باب مدينتهم، أخْذًا بالأسباب، فإذا دخلتم الباب غلبتموهم، وعلى الله وحده فتوكَّلوا، إن كنتم مُصدِّقين رسوله فيما جاءكم به، عاملين بشرعه.", "isBasmala": false, "translation_en": "Two men of those who feared, but whom God had blessed, said, \"Go at them by the gate; and when you have entered it, you will prevail. And put your trust in God, if you are believers.\"", "translation_id": "Berkatalah dua orang diantara orang-orang yang takut (kepada Allah) yang Allah telah memberi nikmat atas keduanya: \"Serbulah mereka dengan melalui pintu gerbang (kota) itu, maka bila kamu memasukinya niscaya kamu akan menang. Dan hanya kepada Allah hendaknya kamu bertawakkal, jika kamu benar-benar orang yang beriman\".", "manzil": 2, "manzil_display": ""}], "112": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 24, "text": "قَالُوا۟ یَـٰمُوسَىٰۤ إِنَّا لَن نَّدۡخُلَهَاۤ أَبَدࣰا مَّا دَامُوا۟ فِیهَا فَٱذۡهَبۡ أَنتَ وَرَبُّكَ فَقَـٰتِلَاۤ إِنَّا هَـٰهُنَا قَـٰعِدُونَ ۝٢٤", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "قال قوم موسى له: إنا لن ندخل المدينة أبدًا ما دام الجبارون فيها، فاذهب أنت وربك فقاتلاهم، أما نحن فقاعدون هاهنا ولن نقاتلهم. وهذا إصرارٌ منهم على مخالفة موسى عليه السلام.", "isBasmala": false, "translation_en": "They said, \"O Moses, we will not enter it, ever, as long as they are in it. So go ahead, you and your Lord, and fight. We are staying right here.\"", "translation_id": "Mereka berkata: \"Hai Musa, kami sekali sekali tidak akan memasukinya selama-lamanya, selagi mereka ada didalamnya, karena itu pergilah kamu bersama Tuhanmu, dan berperanglah kamu berdua, sesungguhnya kami hanya duduk menanti disini saja\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 25, "text": "قَالَ رَبِّ إِنِّی لَاۤ أَمۡلِكُ إِلَّا نَفۡسِی وَأَخِیۖ فَٱفۡرُقۡ بَیۡنَنَا وَبَیۡنَ ٱلۡقَوۡمِ ٱلۡفَـٰسِقِینَ ۝٢٥", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "توجَّه موسى إلى ربه داعيًا: إني لا أقدر إلا على نفسي وأخي، فاحكم بيننا وبين القوم الفاسقين.", "isBasmala": false, "translation_en": "He said, \"My Lord! I have control only over myself and my brother, so separate between us and between the wicked people.\"", "translation_id": "Berkata Musa: \"Ya Tuhanku, aku tidak menguasai kecuali diriku sendiri dan saudaraku. Sebab itu pisahkanlah antara kami dengan orang-orang yang fasik itu\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 26, "text": "قَالَ فَإِنَّهَا مُحَرَّمَةٌ عَلَیۡهِمۡۛ أَرۡبَعِینَ سَنَةࣰۛ یَتِیهُونَ فِی ٱلۡأَرۡضِۚ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡفَـٰسِقِینَ ۝٢٦", "juz": 6, "hizb": "(*¾ ح 11*)", "tafsir": "قال الله لنبيه موسى عليه السلام: إن الأرض المقدَّسة محرَّم على هؤلاء اليهود دخولها أربعين سنة، يتيهون في الأرض حائرين، فلا تأسف -يا موسى- على القوم الخارجين عن طاعتي.", "isBasmala": false, "translation_en": "He said, \"It is forbidden for them for forty years. They will wander aimlessly in the land. So do not grieve over the defiant people.\"", "translation_id": "Allah berfirman: \"(Jika demikian), maka sesungguhnya negeri itu diharamkan atas mereka selama empat puluh tahun, (selama itu) mereka akan berputar-putar kebingungan di bumi (padang Tiih) itu. Maka janganlah kamu bersedih hati (memikirkan nasib) orang-orang yang fasik itu\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 27, "text": "۞ وَٱتۡلُ عَلَیۡهِمۡ نَبَأَ ٱبۡنَیۡ ءَادَمَ بِٱلۡحَقِّ إِذۡ قَرَّبَا قُرۡبَانࣰا فَتُقُبِّلَ مِنۡ أَحَدِهِمَا وَلَمۡ یُتَقَبَّلۡ مِنَ ٱلۡـَٔاخَرِ قَالَ لَأَقۡتُلَنَّكَۖ قَالَ إِنَّمَا یَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِینَ ۝٢٧", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "واقصص -أيها الرسول- على بني إسرائيل خَبَر ابنَيْ آدم قابيل وهابيل، وهو خبرٌ حقٌ: حين قَدَّم كلٌّ منهما قربانًا -وهو ما يُتَقرَّب به إلى الله تعالى - فتقبَّل الله قُربان هابيل؛ لأنه كان تقيًّا، ولم يتقبَّل قُربان قابيل؛ لأنه لم يكن تقيًّا، فحسد قابيلُ أخاه، وقال: لأقتلنَّك، فَردَّ هابيل: إنما يتقبل الله ممن يخشونه.", "isBasmala": false, "translation_en": "And relate to them the true story of Adam's two sons: when they offered an offering, and it was accepted from one of them, but it was not accepted from the other. He Said, \"I will kill you.\" He Said, \"God accepts only from the righteous.\"", "translation_id": "Ceritakanlah kepada mereka kisah kedua putera Adam (Habil dan Qabil) menurut yang sebenarnya, ketika keduanya mempersembahkan korban, maka diterima dari salah seorang dari mereka berdua (Habil) dan tidak diterima dari yang lain (Qabil). Ia berkata (Qabil): \"Aku pasti membunuhmu!\". Berkata Habil: \"Sesungguhnya Allah hanya menerima (korban) dari orang-orang yang bertakwa\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 28, "text": "لَىِٕنۢ بَسَطتَ إِلَیَّ یَدَكَ لِتَقۡتُلَنِی مَاۤ أَنَا۠ بِبَاسِطࣲ یَدِیَ إِلَیۡكَ لِأَقۡتُلَكَۖ إِنِّیۤ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَـٰلَمِینَ ۝٢٨", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "وقال هابيلُ واعظًا أخاه: لَئنْ مَدَدْتَ إليَّ يدكَ لتقتُلني لا تَجِدُ مني مثل فعْلك، وإني أخشى الله ربَّ الخلائق أجمعين.", "isBasmala": false, "translation_en": "\"If you extend your hand to kill me, I will not extend my hand to kill you; for I fear God, Lord of the Worlds.\"", "translation_id": "\"Sungguh kalau kamu menggerakkan tanganmu kepadaku untuk membunuhku, aku sekali-kali tidak akan menggerakkan tanganku kepadamu untuk membunuhmu. Sesungguhnya aku takut kepada Allah, Tuhan seru sekalian alam\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 29, "text": "إِنِّیۤ أُرِیدُ أَن تَبُوۤأَ بِإِثۡمِی وَإِثۡمِكَ فَتَكُونَ مِنۡ أَصۡحَـٰبِ ٱلنَّارِۚ وَذَ ٰلِكَ جَزَ ٰۤؤُا۟ ٱلظَّـٰلِمِینَ ۝٢٩", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "إني أريد أن ترجع حاملا إثم قَتْلي، وإثمك الذي عليك قبل ذلك، فتكون من أهل النار وملازميها، وذلك جزاء المعتدين.", "isBasmala": false, "translation_en": "\"I would rather you bear my sin and your sin, and you become among the inmates of the Fire. Such is the reward for the evildoers.\"", "translation_id": "\"Sesungguhnya aku ingin agar kamu kembali dengan (membawa) dosa (membunuh)ku dan dosamu sendiri, maka kamu akan menjadi penghuni neraka, dan yang demikian itulah pembalasan bagi orang-orang yang zalim\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 30, "text": "فَطَوَّعَتۡ لَهُۥ نَفۡسُهُۥ قَتۡلَ أَخِیهِ فَقَتَلَهُۥ فَأَصۡبَحَ مِنَ ٱلۡخَـٰسِرِینَ ۝٣٠", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "فَزَيَّنت لقابيلَ نفسُه أن يقتل أخاه، فقتله، فأصبح من الخاسرين الذين باعوا آخرتهم بدنياهم.", "isBasmala": false, "translation_en": "Then His soul prompted him to kill his brother, so he killed him, and became one of the losers.", "translation_id": "Maka hawa nafsu Qabil menjadikannya menganggap mudah membunuh saudaranya, sebab itu dibunuhnyalah, maka jadilah ia seorang diantara orang-orang yang merugi.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 31, "text": "فَبَعَثَ ٱللَّهُ غُرَابࣰا یَبۡحَثُ فِی ٱلۡأَرۡضِ لِیُرِیَهُۥ كَیۡفَ یُوَ ٰرِی سَوۡءَةَ أَخِیهِۚ قَالَ یَـٰوَیۡلَتَىٰۤ أَعَجَزۡتُ أَنۡ أَكُونَ مِثۡلَ هَـٰذَا ٱلۡغُرَابِ فَأُوَ ٰرِیَ سَوۡءَةَ أَخِیۖ فَأَصۡبَحَ مِنَ ٱلنَّـٰدِمِینَ ۝٣١", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "لما قتل قابيلُ أخاه لم يعرف ما يصنع بجسده، فأرسل الله غرابًا يحفر حفرةً في الأرض ليدفن فيها غرابًا مَيِّتًا؛ ليدل قابيل كيف يدفن جُثمان أخيه؟ فتعجَّب قابيل، وقال: أعجزتُ أن أصنع مثل صنيع هذا الغراب فأستُرَ عورة أخي؟ فدَفَنَ قابيل أخاه، فعاقبه الله بالندامة بعد أن رجع بالخسران.", "isBasmala": false, "translation_en": "Then God sent a raven digging the ground, to show him how to cover his brother's corpse. He said, \"Woe to me! I was unable to be like this raven, and bury my brother's corpse.\" So he became full of regrets.", "translation_id": "Kemudian Allah menyuruh seekor burung gagak menggali-gali di bumi untuk memperlihatkan kepadanya (Qabil) bagaimana seharusnya menguburkan mayat saudaranya. Berkata Qabil: \"Aduhai celaka aku, mengapa aku tidak mampu berbuat seperti burung gagak ini, lalu aku dapat menguburkan mayat saudaraku ini?\" Karena itu jadilah dia seorang diantara orang-orang yang menyesal.", "manzil": 2, "manzil_display": ""}], "113": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 32, "text": "مِنۡ أَجۡلِ ذَ ٰلِكَ كَتَبۡنَا عَلَىٰ بَنِیۤ إِسۡرَ ٰۤءِیلَ أَنَّهُۥ مَن قَتَلَ نَفۡسَۢا بِغَیۡرِ نَفۡسٍ أَوۡ فَسَادࣲ فِی ٱلۡأَرۡضِ فَكَأَنَّمَا قَتَلَ ٱلنَّاسَ جَمِیعࣰا وَمَنۡ أَحۡیَاهَا فَكَأَنَّمَاۤ أَحۡیَا ٱلنَّاسَ جَمِیعࣰاۚ وَلَقَدۡ جَاۤءَتۡهُمۡ رُسُلُنَا بِٱلۡبَیِّنَـٰتِ ثُمَّ إِنَّ كَثِیرࣰا مِّنۡهُم بَعۡدَ ذَ ٰلِكَ فِی ٱلۡأَرۡضِ لَمُسۡرِفُونَ ۝٣٢", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "بسبب جناية القتل هذه شَرَعْنا لبني اسرائيل أنه من قتل نفسا بغير سبب من قصاص، أو فساد في الأرض بأي نوع من أنواع الفساد، الموجب للقتل كالشرك والمحاربة فكأنما قتل الناس جميعًا فيما استوجب من عظيم العقوبة من الله، وأنه من امتنع عن قَتْل نفس حرَّمها الله فكأنما أحيا الناس جميعًا؛ فالحفاظ على حرمة إنسان واحد حفاظ على حرمات الناس كلهم. ولقد أتت بني إسرائيل رسلُنا بالحجج والدلائل على صحة ما دعَوهم إليه من الإيمان بربهم، وأداء ما فُرِضَ عليهم، ثم إن كثيرًا منهم بعد مجيء الرسل إليهم لمتجاوزون حدود الله بارتكاب محارم الله وترك أوامره.", "isBasmala": false, "translation_en": "Because of that We ordained for the Children of Israel: that whoever kills a person-unless it is for murder or corruption on earth-it is as if he killed the whole of mankind; and whoever saves it, it is as if he saved the whole of mankind. Our messengers came to them with clarifications, but even after that, many of them continue to commit excesses in the land.", "translation_id": "Oleh karena itu Kami tetapkan (suatu hukum) bagi Bani Israil, bahwa: barangsiapa yang membunuh seorang manusia, bukan karena orang itu (membunuh) orang lain, atau bukan karena membuat kerusakan dimuka bumi, maka seakan-akan dia telah membunuh manusia seluruhnya. Dan barangsiapa yang memelihara kehidupan seorang manusia, maka seolah-olah dia telah memelihara kehidupan manusia semuanya. Dan sesungguhnya telah datang kepada mereka rasul-rasul Kami dengan (membawa) keterangan-keterangan yang jelas, kemudian banyak diantara mereka sesudah itu sungguh-sungguh melampaui batas dalam berbuat kerusakan dimuka bumi.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 33, "text": "إِنَّمَا جَزَ ٰۤؤُا۟ ٱلَّذِینَ یُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَیَسۡعَوۡنَ فِی ٱلۡأَرۡضِ فَسَادًا أَن یُقَتَّلُوۤا۟ أَوۡ یُصَلَّبُوۤا۟ أَوۡ تُقَطَّعَ أَیۡدِیهِمۡ وَأَرۡجُلُهُم مِّنۡ خِلَـٰفٍ أَوۡ یُنفَوۡا۟ مِنَ ٱلۡأَرۡضِۚ ذَ ٰلِكَ لَهُمۡ خِزۡیࣱ فِی ٱلدُّنۡیَاۖ وَلَهُمۡ فِی ٱلۡـَٔاخِرَةِ عَذَابٌ عَظِیمٌ ۝٣٣", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "إنما جزاء الذين يحاربون الله، ويبارزونه بالعداوة، ويعتدون على أحكامه، وعلى أحكام رسوله، ويفسدون في الأرض بقتل الأنفس، وسلب الأموال، أن يُقَتَّلوا، أو يُصَلَّبوا مع القتل (والصلب: أن يُشَدَّ الجاني على خشبة) أو تُقْطَع يدُ المحارب اليمنى ورجله اليسرى، فإن لم يَتُبْ تُقطعْ يدُه اليسرى ورجلُه اليمنى، أو يُنفَوا إلى بلد غير بلدهم، ويُحبسوا في سجن ذلك البلد حتى تَظهر توبتُهم. وهذا الجزاء الذي أعدَّه الله للمحاربين هو ذلّ في الدنيا، ولهم في الآخرة عذاب شديد إن لم يتوبوا.", "isBasmala": false, "translation_en": "The punishment for those who fight God and His Messenger, and strive to spread corruption on earth, is that they be killed, or crucified, or have their hands and feet cut off on opposite sides, or be banished from the land. That is to disgrace them in this life; and in the Hereafter they will have a terrible punishment.", "translation_id": "Sesungguhnya pembalasan terhadap orang-orang yang memerangi Allah dan Rasul-Nya dan membuat kerusakan di muka bumi, hanyalah mereka dibunuh atau disalib, atau dipotong tangan dan kaki mereka dengan bertimbal balik, atau dibuang dari negeri (tempat kediamannya). Yang demikian itu (sebagai) suatu penghinaan untuk mereka didunia, dan di akhirat mereka beroleh siksaan yang besar,", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 34, "text": "إِلَّا ٱلَّذِینَ تَابُوا۟ مِن قَبۡلِ أَن تَقۡدِرُوا۟ عَلَیۡهِمۡۖ فَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝٣٤", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "لكن مَن أتى من المحاربين من قبل أن تقدروا عليهم وجاء طائعًا نادمًا فإنه يسقط عنه ما كان لله، فاعلموا -أيها المؤمنون- أن الله غفور لعباده، رحيم بهم.", "isBasmala": false, "translation_en": "Except for those who repent before you apprehend them. So know that God is Forgiving and Merciful.", "translation_id": "kecuali orang-orang yang taubat (di antara mereka) sebelum kamu dapat menguasai (menangkap) mereka; maka ketahuilah bahwasanya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 35, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَٱبۡتَغُوۤا۟ إِلَیۡهِ ٱلۡوَسِیلَةَ وَجَـٰهِدُوا۟ فِی سَبِیلِهِۦ لَعَلَّكُمۡ تُفۡلِحُونَ ۝٣٥", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، خافوا الله، وتَقَرَّبوا إليه بطاعته والعمل بما يرضيه، وجاهدوا في سبيله؛ كي تفوزوا بجناته.", "isBasmala": false, "translation_en": "O you who believe! Be conscious of God, and seek the means of approach to Him, and strive in His cause, so that you may succeed.", "translation_id": "Hai orang-orang yang beriman, bertakwalah kepada Allah dan carilah jalan yang mendekatkan diri kepada-Nya, dan berjihadlah pada jalan-Nya, supaya kamu mendapat keberuntungan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 36, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ لَوۡ أَنَّ لَهُم مَّا فِی ٱلۡأَرۡضِ جَمِیعࣰا وَمِثۡلَهُۥ مَعَهُۥ لِیَفۡتَدُوا۟ بِهِۦ مِنۡ عَذَابِ یَوۡمِ ٱلۡقِیَـٰمَةِ مَا تُقُبِّلَ مِنۡهُمۡۖ وَلَهُمۡ عَذَابٌ أَلِیمࣱ ۝٣٦", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "إن الذين جحدوا وحدانية الله، وشريعته، لو أنهم ملكوا جميع ما في الأرض، وملكوا مثله معه، وأرادوا أن يفتدوا أنفسهم يوم القيامة من عذاب الله بما ملكوا، ما تَقبَّل الله ذلك منهم، ولهم عذاب مُوجع.", "isBasmala": false, "translation_en": "As for those who disbelieve, even if they owned everything on earth, and the like of it with it, and they offered it to ransom themselves from the torment of the Day of Resurrection, it will not be accepted from them. For them is a painful punishment.", "translation_id": "Sesungguhnya orang-orang yang kafir sekiranya mereka mempunyai apa yang dibumi ini seluruhnya dan mempunyai yang sebanyak itu (pula) untuk menebusi diri mereka dengan itu dari azab hari kiamat, niscaya (tebusan itu) tidak akan diterima dari mereka, dan mereka beroleh azab yang pedih.", "manzil": 2, "manzil_display": ""}], "114": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 37, "text": "یُرِیدُونَ أَن یَخۡرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَـٰرِجِینَ مِنۡهَاۖ وَلَهُمۡ عَذَابࣱ مُّقِیمࣱ ۝٣٧", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "يريد هؤلاء الكافرون الخروج من النار لما يلاقونه من أهوالها، ولا سبيل لهم إلى ذلك، ولهم عذاب دائم.", "isBasmala": false, "translation_en": "They will want to leave the Fire, but they will not leave it. For them is a lasting punishment.", "translation_id": "Mereka ingin keluar dari neraka, padahal mereka sekali-kali tidak dapat keluar daripadanya, dan mereka beroleh azab yang kekal.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 38, "text": "وَٱلسَّارِقُ وَٱلسَّارِقَةُ فَٱقۡطَعُوۤا۟ أَیۡدِیَهُمَا جَزَاۤءَۢ بِمَا كَسَبَا نَكَـٰلࣰا مِّنَ ٱللَّهِۗ وَٱللَّهُ عَزِیزٌ حَكِیمࣱ ۝٣٨", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "والسارق والسارقة فاقطعوا -يا ولاة الأمر- أيديهما بمقتضى الشرع، مجازاة لهما على أَخْذهما أموال الناس بغير حق، وعقوبةً يمنع الله بها غيرهما أن يصنع مثل صنيعهما. والله عزيز في ملكه، حكيم في أمره ونهيه.", "isBasmala": false, "translation_en": "As for the thief, whether male or female, cut their hands as a penalty for what they have reaped-a deterrent from God. God is Mighty and Wise.", "translation_id": "Laki-laki yang mencuri dan perempuan yang mencuri, potonglah tangan keduanya (sebagai) pembalasan bagi apa yang mereka kerjakan dan sebagai siksaan dari Allah. Dan Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 39, "text": "فَمَن تَابَ مِنۢ بَعۡدِ ظُلۡمِهِۦ وَأَصۡلَحَ فَإِنَّ ٱللَّهَ یَتُوبُ عَلَیۡهِۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ ۝٣٩", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "فمن تاب مِن بعد سرقته، وأصلح في كل أعماله، فإن الله يقبل توبته. إن الله غفور لعباده، رحيم بهم.", "isBasmala": false, "translation_en": "But whoever repents after his crime, and reforms, God will accept his repentance. God is Forgiving and Merciful.", "translation_id": "Maka barangsiapa bertaubat (di antara pencuri-pencuri itu) sesudah melakukan kejahatan itu dan memperbaiki diri, maka sesungguhnya Allah menerima taubatnya. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 40, "text": "أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ یُعَذِّبُ مَن یَشَاۤءُ وَیَغۡفِرُ لِمَن یَشَاۤءُۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٤٠", "juz": 6, "hizb": "(* ح 12*)", "tafsir": "ألم تعلم -أيها الرسول- أن الله خالق الكون ومُدبِّره ومالكه، وأنه تعالى الفعَّال لما يريد، يعذب من يشاء، ويغفر لمن يشاء، وهو على كل شيء قدير.", "isBasmala": false, "translation_en": "Do you not know that to God belongs the kingdom of the heavens and the earth? He punishes whom He wills, and He forgives whom He wills. And God is Capable of everything.", "translation_id": "Tidakkah kamu tahu, sesungguhnya Allah-lah yang mempunyai kerajaan langit dan bumi, disiksa-Nya siapa yang dikehendaki-Nya dan diampuni-Nya bagi siapa yang dikehendaki-Nya. Dan Allah Maha Kuasa atas segala sesuatu.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 41, "text": "۞ یَـٰۤأَیُّهَا ٱلرَّسُولُ لَا یَحۡزُنكَ ٱلَّذِینَ یُسَـٰرِعُونَ فِی ٱلۡكُفۡرِ مِنَ ٱلَّذِینَ قَالُوۤا۟ ءَامَنَّا بِأَفۡوَ ٰهِهِمۡ وَلَمۡ تُؤۡمِن قُلُوبُهُمۡۛ وَمِنَ ٱلَّذِینَ هَادُوا۟ۛ سَمَّـٰعُونَ لِلۡكَذِبِ سَمَّـٰعُونَ لِقَوۡمٍ ءَاخَرِینَ لَمۡ یَأۡتُوكَۖ یُحَرِّفُونَ ٱلۡكَلِمَ مِنۢ بَعۡدِ مَوَاضِعِهِۦۖ یَقُولُونَ إِنۡ أُوتِیتُمۡ هَـٰذَا فَخُذُوهُ وَإِن لَّمۡ تُؤۡتَوۡهُ فَٱحۡذَرُوا۟ۚ وَمَن یُرِدِ ٱللَّهُ فِتۡنَتَهُۥ فَلَن تَمۡلِكَ لَهُۥ مِنَ ٱللَّهِ شَیۡـًٔاۚ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَمۡ یُرِدِ ٱللَّهُ أَن یُطَهِّرَ قُلُوبَهُمۡۚ لَهُمۡ فِی ٱلدُّنۡیَا خِزۡیࣱۖ وَلَهُمۡ فِی ٱلۡـَٔاخِرَةِ عَذَابٌ عَظِیمࣱ ۝٤١", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "يا أيها الرسول لا يحزنك الذين يسارعون في جحود نبوتك من المنافقين الذين أظهروا الإسلام وقلوبهم خالية منه، فإني ناصرك عليهم. ولا يحزنك تسرُّع اليهود إلى إنكار نبوتك، فإنهم قوم يستمعون للكذب، ويقبلون ما يَفْتَريه أحبارُهم، ويستجيبون لقوم آخرين لا يحضرون مجلسك، وهؤلاء الآخرون يُبَدِّلون كلام الله من بعد ما عَقَلوه، ويقولون: إن جاءكم من محمد ما يوافق الذي بدَّلناه وحرَّفناه من أحكام التوراة فاعملوا به، وإن جاءكم منه ما يخالفه فاحذروا قبوله، والعمل به. ومن يشأ الله ضلالته فلن تستطيع -أيها الرسول- دَفْعَ ذلك عنه، ولا تقدر على هدايته. وإنَّ هؤلاء المنافقين واليهود لم يُرِدِ الله أن يطهِّر قلوبهم من دنس الكفر، لهم الذلُّ والفضيحة في الدنيا، ولهم في الآخرة عذاب عظيم.", "isBasmala": false, "translation_en": "O Messenger! Do not let those who are quick to disbelief grieve you-from among those who say with their mouths, \"We believe,\" but their hearts do not believe; and from among the Jews-listeners to lies, listeners to other people who did not come to you. They distort words from their places, and they say, \"If you are given this, accept it; but if you are not given it, beware.\" Whomever God has willed to divert, you have nothing for him from God. Those are they whose hearts God does not intend to purify. For them is disgrace in this world, and for them is a great punishment in the Hereafter.", "translation_id": "Hari Rasul, janganlah hendaknya kamu disedihkan oleh orang-orang yang bersegera (memperlihatkan) kekafirannya, yaitu diantara orang-orang yang mengatakan dengan mulut mereka: \"Kami telah beriman\", padahal hati mereka belum beriman; dan (juga) di antara orang-orang Yahudi. (Orang-orang Yahudi itu) amat suka mendengar (berita-berita) bohong dan amat suka mendengar perkataan-perkataan orang lain yang belum pernah datang kepadamu; mereka merubah perkataan-perkataan (Taurat) dari tempat-tempatnya. Mereka mengatakan: \"Jika diberikan ini (yang sudah di rubah-rubah oleh mereka) kepada kamu, maka terimalah, dan jika kamu diberi yang bukan ini maka hati-hatilah\". Barangsiapa yang Allah menghendaki kesesatannya, maka sekali-kali kamu tidak akan mampu menolak sesuatupun (yang datang) daripada Allah. Mereka itu adalah orang-orang yang Allah tidak hendak mensucikan hati mereka. Mereka beroleh kehinaan di dunia dan di akhirat mereka beroleh siksaan yang besar.", "manzil": 2, "manzil_display": ""}], "115": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 42, "text": "سَمَّـٰعُونَ لِلۡكَذِبِ أَكَّـٰلُونَ لِلسُّحۡتِۚ فَإِن جَاۤءُوكَ فَٱحۡكُم بَیۡنَهُمۡ أَوۡ أَعۡرِضۡ عَنۡهُمۡۖ وَإِن تُعۡرِضۡ عَنۡهُمۡ فَلَن یَضُرُّوكَ شَیۡـࣰٔاۖ وَإِنۡ حَكَمۡتَ فَٱحۡكُم بَیۡنَهُم بِٱلۡقِسۡطِۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُقۡسِطِینَ ۝٤٢", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "هؤلاء اليهود يجمعون بين استماع الكذب وأكل الحرام، فإن جاؤوك يتحاكمون إليك فاقض بينهم، أو اتركهم، فإن لم تحكم بينهم فلن يقدروا على أن يضروك بشيء، وإن حكمت فاحكم بينهم بالعدل. إن الله يحب العادلين.", "isBasmala": false, "translation_en": "Listeners to falsehoods, eaters of illicit earnings. If they come to you, judge between them, or turn away from them. If you turn away from them, they will not harm you in the least. But if you judge, judge between them equitably. God loves the equitable.", "translation_id": "Mereka itu adalah orang-orang yang suka mendengar berita bohong, banyak memakan yang haram. Jika mereka (orang Yahudi) datang kepadamu (untuk meminta putusan), maka putuskanlah (perkara itu) diantara mereka, atau berpalinglah dari mereka; jika kamu berpaling dari mereka maka mereka tidak akan memberi mudharat kepadamu sedikitpun. Dan jika kamu memutuskan perkara mereka, maka putuskanlah (perkara itu) diantara mereka dengan adil, sesungguhnya Allah menyukai orang-orang yang adil.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 43, "text": "وَكَیۡفَ یُحَكِّمُونَكَ وَعِندَهُمُ ٱلتَّوۡرَىٰةُ فِیهَا حُكۡمُ ٱللَّهِ ثُمَّ یَتَوَلَّوۡنَ مِنۢ بَعۡدِ ذَ ٰلِكَۚ وَمَاۤ أُو۟لَـٰۤىِٕكَ بِٱلۡمُؤۡمِنِینَ ۝٤٣", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "إنَّ صنيع هؤلاء اليهود عجيب، فهم يحتكمون إليك -أيها الرسول- وهم لا يؤمنون بك، ولا بكتابك، مع أن التوراة التي يؤمنون بها عندهم، فيها حكم الله، ثم يتولَّون مِن بعد حكمك إذا لم يُرضهم، فجمعوا بين الكفر بشرعهم، والإعراض عن حكمك، وليس أولئك المتصفون بتلك الصفات، بالمؤمنين بالله وبك وبما تحكم به.", "isBasmala": false, "translation_en": "But why do they come to you for judgment, when they have the Torah, in which is God's Law? Yet they turn away after that. These are not believers.", "translation_id": "Dan bagaimanakah mereka mengangkatmu menjadi hakim mereka, padahal mereka mempunyai Taurat yang didalamnya (ada) hukum Allah, kemudian mereka berpaling sesudah itu (dari putusanmu)? Dan mereka sungguh-sungguh bukan orang yang beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 44, "text": "إِنَّاۤ أَنزَلۡنَا ٱلتَّوۡرَىٰةَ فِیهَا هُدࣰى وَنُورࣱۚ یَحۡكُمُ بِهَا ٱلنَّبِیُّونَ ٱلَّذِینَ أَسۡلَمُوا۟ لِلَّذِینَ هَادُوا۟ وَٱلرَّبَّـٰنِیُّونَ وَٱلۡأَحۡبَارُ بِمَا ٱسۡتُحۡفِظُوا۟ مِن كِتَـٰبِ ٱللَّهِ وَكَانُوا۟ عَلَیۡهِ شُهَدَاۤءَۚ فَلَا تَخۡشَوُا۟ ٱلنَّاسَ وَٱخۡشَوۡنِ وَلَا تَشۡتَرُوا۟ بِـَٔایَـٰتِی ثَمَنࣰا قَلِیلࣰاۚ وَمَن لَّمۡ یَحۡكُم بِمَاۤ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡكَـٰفِرُونَ ۝٤٤", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "إنا أنزلنا التوراة فيها إرشاد من الضلالة، وبيان للأحكام، وقد حكم بها النبيُّون -الذين انقادوا لحكم الله، وأقروا به- بين اليهود، ولم يخرجوا عن حكمها ولم يُحَرِّفوها، وحكم بها عُبَّاد اليهود وفقهاؤهم الذين يربُّون الناس بشرع الله؛ ذلك أن أنبياءهم قد استأمنوهم على تبليغ التوراة، وفِقْه كتاب الله والعمل به، وكان الربانيون والأحبار شهداء على أن أنبياءهم قد قضوا في اليهود بكتاب الله. ويقول تعالى لعلماء اليهود وأحبارهم: فلا تخشوا الناس في تنفيذ حكمي؛ فإنهم لا يقدرون على نفعكم ولا ضَرِّكم، ولكن اخشوني فإني أنا النافع الضار، ولا تأخذوا بترك الحكم بما أنزلتُ عوضًا حقيرًا. الحكم بغير ما أنزل الله من أعمال أهل الكفر، فالذين يبدلون حكم الله الذي أنزله في كتابه، فيكتمونه ويجحدونه ويحكمون بغيره معتقدين حله وجوازه فأولئك هم الكافرون.", "isBasmala": false, "translation_en": "We have revealed the Torah, wherein is guidance and light. The submissive prophets ruled the Jews according to it, so did the rabbis and the scholars, as they were required to protect God's Book, and were witnesses to it. So do not fear people, but fear Me. And do not sell My revelations for a cheap price. Those who do not rule according to what God revealed are the unbelievers.", "translation_id": "Sesungguhnya Kami telah menurunkan Kitab Taurat di dalamnya (ada) petunjuk dan cahaya (yang menerangi), yang dengan Kitab itu diputuskan perkara orang-orang Yahudi oleh nabi-nabi yang menyerah diri kepada Allah, oleh orang-orang alim mereka dan pendeta-pendeta mereka, disebabkan mereka diperintahkan memelihara kitab-kitab Allah dan mereka menjadi saksi terhadapnya. Karena itu janganlah kamu takut kepada manusia, (tetapi) takutlah kepada-Ku. Dan janganlah kamu menukar ayat-ayat-Ku dengan harga yang sedikit. Barangsiapa yang tidak memutuskan menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 45, "text": "وَكَتَبۡنَا عَلَیۡهِمۡ فِیهَاۤ أَنَّ ٱلنَّفۡسَ بِٱلنَّفۡسِ وَٱلۡعَیۡنَ بِٱلۡعَیۡنِ وَٱلۡأَنفَ بِٱلۡأَنفِ وَٱلۡأُذُنَ بِٱلۡأُذُنِ وَٱلسِّنَّ بِٱلسِّنِّ وَٱلۡجُرُوحَ قِصَاصࣱۚ فَمَن تَصَدَّقَ بِهِۦ فَهُوَ كَفَّارَةࣱ لَّهُۥۚ وَمَن لَّمۡ یَحۡكُم بِمَاۤ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ ۝٤٥", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "وفَرَضنا عليهم في التوراة أن النفس تُقْتَل بالنفس، والعين تُفْقَأ بالعين، والأنف يُجْدَع بالأنف، والأذُن تُقْطع بالأذُن، والسنَّ تُقْلَعُ بالسنِّ، وأنَّه يُقْتَصُّ في الجروح، فمن تجاوز عن حقه في الاقتصاص من المُعتدي فذلك تكفير لبعض ذنوب المعتدى عليه وإزالةٌ لها. ومن لم يحكم بما أنزل الله في القصاص وغيره، فأولئك هم المتجاوزون حدود الله.", "isBasmala": false, "translation_en": "And We wrote for them in it: a life for a life, an eye for an eye, a nose for a nose, an ear for an ear, a tooth for a tooth, and an equal wound for a wound; but whoever forgoes it in charity, it will serve as atonement for him. Those who do not rule according to what God revealed are the evildoers.", "translation_id": "Dan Kami telah tetapkan terhadap mereka di dalamnya (At Taurat) bahwasanya jiwa (dibalas) dengan jiwa, mata dengan mata, hidung dengan hidung, telinga dengan telinga, gigi dengan gigi, dan luka luka (pun) ada qishaashnya. Barangsiapa yang melepaskan (hak qishaash)nya, maka melepaskan hak itu (menjadi) penebus dosa baginya. Barangsiapa tidak memutuskan perkara menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang zalim.", "manzil": 2, "manzil_display": ""}], "116": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 46, "text": "وَقَفَّیۡنَا عَلَىٰۤ ءَاثَـٰرِهِم بِعِیسَى ٱبۡنِ مَرۡیَمَ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ مِنَ ٱلتَّوۡرَىٰةِۖ وَءَاتَیۡنَـٰهُ ٱلۡإِنجِیلَ فِیهِ هُدࣰى وَنُورࣱ وَمُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ مِنَ ٱلتَّوۡرَىٰةِ وَهُدࣰى وَمَوۡعِظَةࣰ لِّلۡمُتَّقِینَ ۝٤٦", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "وأتبعنا أنبياء بني إسرائيل عيسى ابن مريم مؤمنًا بما في التوراة، عاملا بما فيها مما لم ينسخه كتابه، وأنزلنا إليه الإنجيل هاديا إلى الحق، ومبيِّنًا لما جهله الناس مِن حكم الله، وشاهدًا على صدق التوراة بما اشتمل عليه من أحكامها، وقد جعلناه بيانًا للذين يخافون الله وزاجرًا لهم عن ارتكاب المحرَّمات.", "isBasmala": false, "translation_en": "In their footsteps, We sent Jesus son of Mary, fulfilling the Torah that preceded him; and We gave him the Gospel, wherein is guidance and light, and confirming the Torah that preceded him, and guidance and counsel for the righteous.", "translation_id": "Dan Kami iringkan jejak mereka (nabi nabi Bani Israil) dengan Isa putera Maryam, membenarkan Kitab yang sebelumnya, yaitu: Taurat. Dan Kami telah memberikan kepadanya Kitab Injil sedang didalamnya (ada) petunjuk dan dan cahaya (yang menerangi), dan membenarkan kitab yang sebelumnya, yaitu Kitab Taurat. Dan menjadi petunjuk serta pengajaran untuk orang-orang yang bertakwa.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 47, "text": "وَلۡیَحۡكُمۡ أَهۡلُ ٱلۡإِنجِیلِ بِمَاۤ أَنزَلَ ٱللَّهُ فِیهِۚ وَمَن لَّمۡ یَحۡكُم بِمَاۤ أَنزَلَ ٱللَّهُ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ ۝٤٧", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "وليحكم أهل الإنجيل الذين أُرسِل إليهم عيسى بما أنزل الله فيه. ومن لم يحكم بما أنزل الله فأولئك هم الخارجون عن أمره، العاصون له.", "isBasmala": false, "translation_en": "So let the people of the Gospel rule according to what God revealed in it. Those who do not rule according to what God revealed are the sinners.", "translation_id": "Dan hendaklah orang-orang pengikut Injil, memutuskan perkara menurut apa yang diturunkan Allah didalamnya. Barangsiapa tidak memutuskan perkara menurut apa yang diturunkan Allah, maka mereka itu adalah orang-orang yang fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 48, "text": "وَأَنزَلۡنَاۤ إِلَیۡكَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ مِنَ ٱلۡكِتَـٰبِ وَمُهَیۡمِنًا عَلَیۡهِۖ فَٱحۡكُم بَیۡنَهُم بِمَاۤ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَاۤءَهُمۡ عَمَّا جَاۤءَكَ مِنَ ٱلۡحَقِّۚ لِكُلࣲّ جَعَلۡنَا مِنكُمۡ شِرۡعَةࣰ وَمِنۡهَاجࣰاۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةࣰ وَ ٰحِدَةࣰ وَلَـٰكِن لِّیَبۡلُوَكُمۡ فِی مَاۤ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُوا۟ ٱلۡخَیۡرَ ٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِیعࣰا فَیُنَبِّئُكُم بِمَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ ۝٤٨", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "وأنزلنا إليك -أيها الرسول- القرآن، وكل ما فيه حقّ يشهد على صدق الكتب قبله، وأنها من عند الله، مصدقًا لما فيها من صحة، ومبيِّنًا لما فيها من تحريف، ناسخًا لبعض شرائعها، فاحكم بين المحتكمين إليك من اليهود بما أنزل الله إليك في هذا القرآن، ولا تنصرف عن الحق الذي أمرك الله به إلى أهوائهم وما اعتادوه، فقد جعلنا لكل أمة شريعة، وطريقة واضحة يعملون بها. ولو شاء الله لجعل شرائعكم واحدة، ولكنه تعالى خالف بينها ليختبركم، فيظهر المطيع من العاصي، فسارعوا إلى ما هو خير لكم في الدارين بالعمل بما في القرآن، فإن مصيركم إلى الله، فيخبركم بما كنتم فيه تختلفون، ويجزي كلا بعمله.", "isBasmala": false, "translation_en": "And We revealed to you the Book, with truth, confirming the Scripture that preceded it, and superseding it. So judge between them according to what God revealed, and do not follow their desires if they differ from the truth that has come to you. For each of you We have assigned a law and a method. Had God willed, He could have made you a single nation, but He tests you through what He has given you. So compete in righteousness. To God is your return, all of you; then He will inform you of what you had disputed.", "translation_id": "Dan Kami telah turunkan kepadamu Al Quran dengan membawa kebenaran, membenarkan apa yang sebelumnya, yaitu kitab-kitab (yang diturunkan sebelumnya) dan batu ujian terhadap kitab-kitab yang lain itu; maka putuskanlah perkara mereka menurut apa yang Allah turunkan dan janganlah kamu mengikuti hawa nafsu mereka dengan meninggalkan kebenaran yang telah datang kepadamu. Untuk tiap-tiap umat diantara kamu, Kami berikan aturan dan jalan yang terang. Sekiranya Allah menghendaki, niscaya kamu dijadikan-Nya satu umat (saja), tetapi Allah hendak menguji kamu terhadap pemberian-Nya kepadamu, maka berlomba-lombalah berbuat kebajikan. Hanya kepada Allah-lah kembali kamu semuanya, lalu diberitahukan-Nya kepadamu apa yang telah kamu perselisihkan itu,", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 49, "text": "وَأَنِ ٱحۡكُم بَیۡنَهُم بِمَاۤ أَنزَلَ ٱللَّهُ وَلَا تَتَّبِعۡ أَهۡوَاۤءَهُمۡ وَٱحۡذَرۡهُمۡ أَن یَفۡتِنُوكَ عَنۢ بَعۡضِ مَاۤ أَنزَلَ ٱللَّهُ إِلَیۡكَۖ فَإِن تَوَلَّوۡا۟ فَٱعۡلَمۡ أَنَّمَا یُرِیدُ ٱللَّهُ أَن یُصِیبَهُم بِبَعۡضِ ذُنُوبِهِمۡۗ وَإِنَّ كَثِیرࣰا مِّنَ ٱلنَّاسِ لَفَـٰسِقُونَ ۝٤٩", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "واحكم -أيها الرسول- بين اليهود بما أنزل الله إليك في القرآن، ولا تتبع أهواء الذين يحتكمون إليك، واحذرهم أن يصدُّوك عن بعض ما أنزل الله إليك فتترك العمل به، فإن أعرض هؤلاء عمَّا تحكم به فاعلم أن الله يريد أن يصرفهم عن الهدى بسبب ذنوبٍ اكتسبوها من قبل. وإن كثيرًا من الناس لَخارجون عن طاعة ربهم.", "isBasmala": false, "translation_en": "And judge between them according to what God revealed, and do not follow their desires. And beware of them, lest they lure you away from some of what God has revealed to you. But if they turn away, know that God intends to strike them with some of their sins. In fact, a great many people are corrupt.", "translation_id": "dan hendaklah kamu memutuskan perkara di antara mereka menurut apa yang diturunkan Allah, dan janganlah kamu mengikuti hawa nafsu mereka. Dan berhati-hatilah kamu terhadap mereka, supaya mereka tidak memalingkan kamu dari sebahagian apa yang telah diturunkan Allah kepadamu. Jika mereka berpaling (dari hukum yang telah diturunkan Allah), maka ketahuilah bahwa sesungguhnya Allah menghendaki akan menimpakan mushibah kepada mereka disebabkan sebahagian dosa-dosa mereka. Dan sesungguhnya kebanyakan manusia adalah orang-orang yang fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 50, "text": "أَفَحُكۡمَ ٱلۡجَـٰهِلِیَّةِ یَبۡغُونَۚ وَمَنۡ أَحۡسَنُ مِنَ ٱللَّهِ حُكۡمࣰا لِّقَوۡمࣲ یُوقِنُونَ ۝٥٠", "juz": 6, "hizb": "(*¼ ح 12*)", "tafsir": "أيريد هؤلاء اليهود أن تحكم بينهم بما تعارف عليه المشركون عبدةُ الأوثان من الضلالات والجهالات؟! لا يكون ذلك ولا يليق أبدًا ومَن أعدل مِن الله في حكمه لمن عقل عن الله شَرْعه، وآمن به، وأيقن أن حكم الله هو الحق؟", "isBasmala": false, "translation_en": "Is it the laws of the time of ignorance that they desire? Who is better than God in judgment for people who are certain?", "translation_id": "Apakah hukum Jahiliyah yang mereka kehendaki, dan (hukum) siapakah yang lebih baik daripada (hukum) Allah bagi orang-orang yang yakin?", "manzil": 2, "manzil_display": ""}], "117": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 51, "text": "۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلۡیَهُودَ وَٱلنَّصَـٰرَىٰۤ أَوۡلِیَاۤءَۘ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضࣲۚ وَمَن یَتَوَلَّهُم مِّنكُمۡ فَإِنَّهُۥ مِنۡهُمۡۗ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝٥١", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "يا أيها الذين آمنوا لا تتخذوا اليهود والنصارى حلفاءَ وأنصارًا على أهل الإيمان؛ ذلك أنهم لا يُوادُّون المؤمنين، فاليهود يوالي بعضهم بعضًا، وكذلك النصارى، وكلا الفريقين يجتمع على عداوتكم. وأنتم -أيها المؤمنون- أجدرُ بأن ينصر بعضُكم بعضًا. ومن يتولهم منكم فإنه يصير من جملتهم، وحكمه حكمهم. إن الله لا يوفق الظالمين الذين يتولون الكافرين.", "isBasmala": false, "translation_en": "O you who believe! Do not take the Jews and the Christians as allies; some of them are allies of one another. Whoever of you allies himself with them is one of them. God does not guide the wrongdoing people.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu mengambil orang-orang Yahudi dan Nasrani menjadi pemimpin-pemimpin(mu); sebahagian mereka adalah pemimpin bagi sebahagian yang lain. Barangsiapa diantara kamu mengambil mereka menjadi pemimpin, maka sesungguhnya orang itu termasuk golongan mereka. Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang zalim.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 52, "text": "فَتَرَى ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ یُسَـٰرِعُونَ فِیهِمۡ یَقُولُونَ نَخۡشَىٰۤ أَن تُصِیبَنَا دَاۤىِٕرَةࣱۚ فَعَسَى ٱللَّهُ أَن یَأۡتِیَ بِٱلۡفَتۡحِ أَوۡ أَمۡرࣲ مِّنۡ عِندِهِۦ فَیُصۡبِحُوا۟ عَلَىٰ مَاۤ أَسَرُّوا۟ فِیۤ أَنفُسِهِمۡ نَـٰدِمِینَ ۝٥٢", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "يخبر الله تعالى عن جماعة من المنافقين أنهم كانوا يبادرون في موادة اليهود لما في قلوبهم من الشكِّ والنفاق، ويقولون: إنما نوادُّهم خشية أن يظفروا بالمسلمين فيصيبونا معهم، قال الله تعالى ذكره: فعسى الله أن يأتي بالفتح -أي فتح \"مكة\"- وينصر نَبِيَّه، ويُظْهِر الإسلام والمسلمين على الكفار، أو يُهيِّئ من الأمور ما تذهب به قوةُ اليهود والنَّصارى، فيخضعوا للمسلمين، فحينئذٍ يندم المنافقون على ما أضمروا في أنفسهم من موالاتهم.", "isBasmala": false, "translation_en": "You will see those in whose hearts is sickness racing towards them. They say, \"We fear the wheel of fate may turn against us.\" But perhaps God will bring about victory, or some event of His making; thereupon they will regret what they concealed within themselves.", "translation_id": "Maka kamu akan melihat orang-orang yang ada penyakit dalam hatinya (orang-orang munafik) bersegera mendekati mereka (Yahudi dan Nasrani), seraya berkata: \"Kami takut akan mendapat bencana\". Mudah-mudahan Allah akan mendatangkan kemenangan (kepada Rasul-Nya), atau sesuatu keputusan dari sisi-Nya. Maka karena itu, mereka menjadi menyesal terhadap apa yang mereka rahasiakan dalam diri mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 53, "text": "وَیَقُولُ ٱلَّذِینَ ءَامَنُوۤا۟ أَهَـٰۤؤُلَاۤءِ ٱلَّذِینَ أَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ إِنَّهُمۡ لَمَعَكُمۡۚ حَبِطَتۡ أَعۡمَـٰلُهُمۡ فَأَصۡبَحُوا۟ خَـٰسِرِینَ ۝٥٣", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "وحينئذ يقول بعض المؤمنين لبعض مُتعجِّبين من حال المنافقين -إذا كُشِف أمرهم-: أهؤلاء الذين أقسموا بأغلظ الأيمان إنهم لَمَعَنا؟! بطلت أعمال المنافقين التي عملوها في الدنيا، فلا ثواب لهم عليها؛ لأنهم عملوها على غير إيمان، فخسروا الدنيا والآخرة.", "isBasmala": false, "translation_en": "Those who believe will say, \"Are these the ones who swore by God with their strongest oaths that they are with you?\" Their works have failed, so they became losers.", "translation_id": "Dan orang-orang yang beriman akan mengatakan: \"Inikah orang-orang yang bersumpah sungguh-sungguh dengan nama Allah, bahwasanya mereka benar-benar beserta kamu?\" Rusak binasalah segala amal mereka, lalu mereka menjadi orang-orang yang merugi.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 54, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ مَن یَرۡتَدَّ مِنكُمۡ عَن دِینِهِۦ فَسَوۡفَ یَأۡتِی ٱللَّهُ بِقَوۡمࣲ یُحِبُّهُمۡ وَیُحِبُّونَهُۥۤ أَذِلَّةٍ عَلَى ٱلۡمُؤۡمِنِینَ أَعِزَّةٍ عَلَى ٱلۡكَـٰفِرِینَ یُجَـٰهِدُونَ فِی سَبِیلِ ٱللَّهِ وَلَا یَخَافُونَ لَوۡمَةَ لَاۤىِٕمࣲۚ ذَ ٰلِكَ فَضۡلُ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ وَ ٰسِعٌ عَلِیمٌ ۝٥٤", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه من يرجع منكم عن دينه، ويستبدل به اليهودية أو النصرانية أو غير ذلك، فلن يضرُّوا الله شيئًا، وسوف يأتي الله بقوم خير منهم يُحِبُّهم ويحبونه، رحماء بالمؤمنين أشدَّاء على الكافرين، يجاهدون أعداء الله، ولا يخافون في ذات الله أحدًا. ذلك الإنعام مِن فضل الله يؤتيه من أراد، والله واسع الفضل، عليم بمن يستحقه من عباده.", "isBasmala": false, "translation_en": "O you who believe! Whoever of you goes back on his religion-God will bring a people whom He loves and who love Him, kind towards the believers, stern with the disbelievers. They strive in the way of God, and do not fear the blame of the critic. That is the grace of God; He bestows it upon whomever He wills. God is Embracing and Knowing.", "translation_id": "Hai orang-orang yang beriman, barangsiapa di antara kamu yang murtad dari agamanya, maka kelak Allah akan mendatangkan suatu kaum yang Allah mencintai mereka dan merekapun mencintai-Nya, yang bersikap lemah lembut terhadap orang yang mukmin, yang bersikap keras terhadap orang-orang kafir, yang berjihad dijalan Allah, dan yang tidak takut kepada celaan orang yang suka mencela. Itulah karunia Allah, diberikan-Nya kepada siapa yang dikehendaki-Nya, dan Allah Maha Luas (pemberian-Nya), lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 55, "text": "إِنَّمَا وَلِیُّكُمُ ٱللَّهُ وَرَسُولُهُۥ وَٱلَّذِینَ ءَامَنُوا۟ ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَهُمۡ رَ ٰكِعُونَ ۝٥٥", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "إنما ناصركم -أيُّها المؤمنون- الله ورسوله، والمؤمنون الذين يحافظون على الصلاة المفروضة، ويؤدون الزكاة عن رضا نفس، وهم خاضعون لله.", "isBasmala": false, "translation_en": "Your allies are God, and His Messenger, and those who believe-those who pray regularly, and give charity, and bow down.", "translation_id": "Sesungguhnya penolong kamu hanyalah Allah, Rasul-Nya, dan orang-orang yang beriman, yang mendirikan shalat dan menunaikan zakat, seraya mereka tunduk (kepada Allah).", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 56, "text": "وَمَن یَتَوَلَّ ٱللَّهَ وَرَسُولَهُۥ وَٱلَّذِینَ ءَامَنُوا۟ فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَـٰلِبُونَ ۝٥٦", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "ومن وثق بالله وتولَّى الله ورسوله والمؤمنين، فهو من حزب الله، وحزب الله هم الغالبون المنتصرون.", "isBasmala": false, "translation_en": "Whoever allies himself with God, and His Messenger, and those who believe-surely the Party of God is the victorious.", "translation_id": "Dan barangsiapa mengambil Allah, Rasul-Nya dan orang-orang yang beriman menjadi penolongnya, maka sesungguhnya pengikut (agama) Allah itulah yang pasti menang.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 57, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ ٱلَّذِینَ ٱتَّخَذُوا۟ دِینَكُمۡ هُزُوࣰا وَلَعِبࣰا مِّنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلِكُمۡ وَٱلۡكُفَّارَ أَوۡلِیَاۤءَۚ وَٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِینَ ۝٥٧", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تتخذوا الذين يستهزئون ويتلاعبون بدينكم من أهل الكتاب والكفارَ أولياءَ، وخافوا الله إن كنتم مؤمنين به وبشرعه.", "isBasmala": false, "translation_en": "O you who believe! Do not befriend those who take your religion in mockery and as a sport, be they from among those who were given the Scripture before you, or the disbelievers. And obey God, if you are believers.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu mengambil jadi pemimpinmu, orang-orang yang membuat agamamu jadi buah ejekan dan permainan, (yaitu) di antara orang-orang yang telah diberi kitab sebelummu, dan orang-orang yang kafir (orang-orang musyrik). Dan bertakwalah kepada Allah jika kamu betul-betul orang-orang yang beriman.", "manzil": 2, "manzil_display": ""}], "118": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 58, "text": "وَإِذَا نَادَیۡتُمۡ إِلَى ٱلصَّلَوٰةِ ٱتَّخَذُوهَا هُزُوࣰا وَلَعِبࣰاۚ ذَ ٰلِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَعۡقِلُونَ ۝٥٨", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "وإذا أذَّن مؤذنكم -أيها المؤمنون- بالصلاة سخر اليهود والنصارى والمشركون واستهزؤوا من دعوتكم إليها؛ وذلك بسبب جهلهم بربهم، وأنهم لا يعقلون حقيقة العبادة.", "isBasmala": false, "translation_en": "When you call to the prayer, they take it as a joke and a trifle. That is because they are people who do not reason.", "translation_id": "Dan apabila kamu menyeru (mereka) untuk (mengerjakan) sembahyang, mereka menjadikannya buah ejekan dan permainan. Yang demikian itu adalah karena mereka benar-benar kaum yang tidak mau mempergunakan akal.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 59, "text": "قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ هَلۡ تَنقِمُونَ مِنَّاۤ إِلَّاۤ أَنۡ ءَامَنَّا بِٱللَّهِ وَمَاۤ أُنزِلَ إِلَیۡنَا وَمَاۤ أُنزِلَ مِن قَبۡلُ وَأَنَّ أَكۡثَرَكُمۡ فَـٰسِقُونَ ۝٥٩", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "قل -أيها الرسول- لهؤلاء المستهزئين من أهل الكتاب: ما تَجِدُونه مطعنًا أو عيبًا هو محمدة لنا: من إيماننا بالله وكتبه المنزلة علينا، وعلى من كان قبلنا، وإيماننا بأن أكثركم خارجون عن الطريق المستقيم!", "isBasmala": false, "translation_en": "Say, \"O People of the Scripture! Do you resent us only because we believe in God, and in what was revealed to us, and in what was revealed previously; and most of you are sinners?\"", "translation_id": "Katakanlah: \"Hai Ahli Kitab, apakah kamu memandang kami salah, hanya lantaran kami beriman kepada Allah, kepada apa yang diturunkan kepada kami dan kepada apa yang diturunkan sebelumnya, sedang kebanyakan di antara kamu benar-benar orang-orang yang fasik?", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 60, "text": "قُلۡ هَلۡ أُنَبِّئُكُم بِشَرࣲّ مِّن ذَ ٰلِكَ مَثُوبَةً عِندَ ٱللَّهِۚ مَن لَّعَنَهُ ٱللَّهُ وَغَضِبَ عَلَیۡهِ وَجَعَلَ مِنۡهُمُ ٱلۡقِرَدَةَ وَٱلۡخَنَازِیرَ وَعَبَدَ ٱلطَّـٰغُوتَۚ أُو۟لَـٰۤىِٕكَ شَرࣱّ مَّكَانࣰا وَأَضَلُّ عَن سَوَاۤءِ ٱلسَّبِیلِ ۝٦٠", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "قل -أيها النبي- للمؤمنين: هل أخبركم بمن يُجازَى يوم القيامة جزاءً أشدَّ مِن جزاء هؤلاء الفاسقين؟ إنهم أسلافهم الذين طردهم الله من رحمته وغَضِب عليهم، ومَسَخَ خَلْقهم، فجعل منهم القردة والخنازير، بعصيانهم وافترائهم وتكبرهم، كما كان منهم عُبَّاد الطاغوت (وهو كل ما عُبِد من دون الله وهو راضٍ)، لقد ساء مكانهم في الآخرة، وضلَّ سَعْيُهم في الدنيا عن الطريق الصحيح.", "isBasmala": false, "translation_en": "Say, \"Shall I inform you of worse than that for retribution from God? He whom God has cursed, and with whom He became angry; and He turned some of them into apes, and swine, and idol worshipers. These are in a worse position, and further away from the right way.\"", "translation_id": "Katakanlah: \"Apakah akan aku beritakan kepadamu tentang orang-orang yang lebih buruk pembalasannya dari (orang-orang fasik) itu disisi Allah, yaitu orang-orang yang dikutuki dan dimurkai Allah, di antara mereka (ada) yang dijadikan kera dan babi dan (orang yang) menyembah thaghut?\". Mereka itu lebih buruk tempatnya dan lebih tersesat dari jalan yang lurus.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 61, "text": "وَإِذَا جَاۤءُوكُمۡ قَالُوۤا۟ ءَامَنَّا وَقَد دَّخَلُوا۟ بِٱلۡكُفۡرِ وَهُمۡ قَدۡ خَرَجُوا۟ بِهِۦۚ وَٱللَّهُ أَعۡلَمُ بِمَا كَانُوا۟ یَكۡتُمُونَ ۝٦١", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "وإذا جاءكم -أيها المؤمنون- منافقو اليهود، قالوا: آمنَّا، وهم مقيمون على كفرهم، قد دخلوا عليكم بكفرهم الذي يعتقدونه بقلوبهم، ثم خرجوا وهم مصرُّون عليه، والله أعلم بسرائرهم، وإن أظهروا خلاف ذلك.", "isBasmala": false, "translation_en": "When they come to you, they say, \"We believe,\" though they have entered with disbelief, and they have departed with it. But God is well aware of what they hide.", "translation_id": "Dan apabila orang-orang (Yahudi atau munafik) datang kepadamu, mereka mengatakan: \"Kami telah beriman\", padahal mereka datang kepadamu dengan kekafirannya dan mereka pergi (daripada kamu) dengan kekafirannya (pula); dan Allah lebih mengetahui apa yang mereka sembunyikan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 62, "text": "وَتَرَىٰ كَثِیرࣰا مِّنۡهُمۡ یُسَـٰرِعُونَ فِی ٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰنِ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُوا۟ یَعۡمَلُونَ ۝٦٢", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "وترى -أيها الرسول- كثيرًا من اليهود يبادرون إلى المعاصي من قول الكذب والزور، والاعتداء على أحكام الله، وأكْل أموال الناس بالباطل، لقد ساء عملهم واعتداؤهم.", "isBasmala": false, "translation_en": "You see many of them competing with one another in sin and hostility, and their consuming of what is illicit. What they have been doing is truly evil.", "translation_id": "Dan kamu akan melihat kebanyakan dari mereka (orang-orang Yahudi) bersegera membuat dosa, permusuhan dan memakan yang haram. Sesungguhnya amat buruk apa yang mereka telah kerjakan itu.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 63, "text": "لَوۡلَا یَنۡهَىٰهُمُ ٱلرَّبَّـٰنِیُّونَ وَٱلۡأَحۡبَارُ عَن قَوۡلِهِمُ ٱلۡإِثۡمَ وَأَكۡلِهِمُ ٱلسُّحۡتَۚ لَبِئۡسَ مَا كَانُوا۟ یَصۡنَعُونَ ۝٦٣", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "هلا ينهى هؤلاء الذين يسارعون في الإثم والعدوان أئمتُهم وعلماؤهم، عن قول الكذب والزور، وأكل أموال الناس بالباطل، لقد ساء صنيعهم حين تركوا النهي عن المنكر.", "isBasmala": false, "translation_en": "Why do the rabbis and the priests not prevent them from speaking sinfully and from consuming forbidden wealth? Evil is what they have been doing.", "translation_id": "Mengapa orang-orang alim mereka, pendeta-pendeta mereka tidak melarang mereka mengucapkan perkataan bohong dan memakan yang haram? Sesungguhnya amat buruk apa yang telah mereka kerjakan itu.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 64, "text": "وَقَالَتِ ٱلۡیَهُودُ یَدُ ٱللَّهِ مَغۡلُولَةٌۚ غُلَّتۡ أَیۡدِیهِمۡ وَلُعِنُوا۟ بِمَا قَالُوا۟ۘ بَلۡ یَدَاهُ مَبۡسُوطَتَانِ یُنفِقُ كَیۡفَ یَشَاۤءُۚ وَلَیَزِیدَنَّ كَثِیرࣰا مِّنۡهُم مَّاۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ طُغۡیَـٰنࣰا وَكُفۡرࣰاۚ وَأَلۡقَیۡنَا بَیۡنَهُمُ ٱلۡعَدَ ٰوَةَ وَٱلۡبَغۡضَاۤءَ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِۚ كُلَّمَاۤ أَوۡقَدُوا۟ نَارࣰا لِّلۡحَرۡبِ أَطۡفَأَهَا ٱللَّهُۚ وَیَسۡعَوۡنَ فِی ٱلۡأَرۡضِ فَسَادࣰاۚ وَٱللَّهُ لَا یُحِبُّ ٱلۡمُفۡسِدِینَ ۝٦٤", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "يُطلع الله نَبِيَّه على شيء من مآثم اليهود -وكان مما يُسرُّونه فيما بينهم- أنهم قالوا: يد الله محبوسة عن فعل الخيرات، بَخِلَ علينا بالرزق والتوسعة، وذلك حين لحقهم جَدْب وقحط. غُلَّتْ أيديهم، أي: حبست أيديهم هم عن فِعْلِ الخيرات، وطردهم الله من رحمته بسبب قولهم. وليس الأمر كما يفترونه على ربهم، بل يداه مبسوطتان لا حَجْرَ عليه، ولا مانع يمنعه من الإنفاق، فإنه الجواد الكريم، ينفق على مقتضى الحكمة وما فيه مصلحة العباد. وفي الآية إثبات لصفة اليدين لله سبحانه وتعالى كما يليق به من غير تشبيه ولا تكييف. لكنهم سوف يزدادون طغيانًا وكفرًا بسبب حقدهم وحسدهم؛ لأن الله قد اصطفاك بالرسالة. ويخبر تعالى أن طوائف اليهود سيظلون إلى يوم القيامة يعادي بعضهم بعضًا، وينفر بعضهم من بعض، كلما تآمروا على الكيد للمسلمين بإثارة الفتن وإشعال نار الحرب ردَّ الله كيدهم، وفرَّق شملهم، ولا يزال اليهود يعملون بمعاصي الله مما ينشأ عنها الفساد والاضطراب في الأرض. والله تعالى لا يحب المفسدين.", "isBasmala": false, "translation_en": "The Jews say, \"God's hand is tied.\" It is their hands that are tied, and they are cursed for what they say. In fact, His hands are outstretched; He gives as He wills. Certainly, what was revealed to your from your Lord will increase many of them in defiance and blasphemy. And We placed between them enmity and hatred, until the Day of Resurrection. Whenever they kindle the fire of war, God extinguishes it. And they strive to spread corruption on earth. God does not love the corrupters.", "translation_id": "Orang-orang Yahudi berkata: \"Tangan Allah terbelenggu\", sebenarnya tangan merekalah yang dibelenggu dan merekalah yang dilaknat disebabkan apa yang telah mereka katakan itu. (Tidak demikian), tetapi kedua-dua tangan Allah terbuka; Dia menafkahkan sebagaimana Dia kehendaki. Dan Al Quran yang diturunkan kepadamu dari Tuhanmu sungguh-sungguh akan menambah kedurhakaan dan kekafiran bagi kebanyakan di antara mereka. Dan Kami telah timbulkan permusuhan dan kebencian di antara mereka sampai hari kiamat. Setiap mereka menyalakan api peperangan Allah memadamkannya dan mereka berbuat kerusakan dimuka bumi dan Allah tidak menyukai orang-orang yang membuat kerusakan.", "manzil": 2, "manzil_display": ""}], "119": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 65, "text": "وَلَوۡ أَنَّ أَهۡلَ ٱلۡكِتَـٰبِ ءَامَنُوا۟ وَٱتَّقَوۡا۟ لَكَفَّرۡنَا عَنۡهُمۡ سَیِّـَٔاتِهِمۡ وَلَأَدۡخَلۡنَـٰهُمۡ جَنَّـٰتِ ٱلنَّعِیمِ ۝٦٥", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "ولو أن اليهود والنصارى صدَّقوا الله ورسوله، وامتثلوا أوامر الله واجتنبوا نواهيه، لكفَّرنا عنهم ذنوبهم، ولأدخلناهم جنات النعيم في الدار الآخرة.", "isBasmala": false, "translation_en": "Had the People of the Scriputure believed and been righteous, We would have remitted their sins, and admitted them into the Gardens of Bliss.", "translation_id": "Dan sekiranya Ahli Kitab beriman dan bertakwa, tentulah Kami tutup (hapus) kesalahan-kesalahan mereka dan tentulah Kami masukkan mereka kedalam surga-surga yang penuh kenikmatan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 66, "text": "وَلَوۡ أَنَّهُمۡ أَقَامُوا۟ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَ وَمَاۤ أُنزِلَ إِلَیۡهِم مِّن رَّبِّهِمۡ لَأَكَلُوا۟ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۚ مِّنۡهُمۡ أُمَّةࣱ مُّقۡتَصِدَةࣱۖ وَكَثِیرࣱ مِّنۡهُمۡ سَاۤءَ مَا یَعۡمَلُونَ ۝٦٦", "juz": 6, "hizb": "(*½ ح 12*)", "tafsir": "ولو أنَّهم عملوا بما في التوراة والإنجيل، وبما أُنْزِل عليك أيها الرسول - وهو القرآن الكريم - لرُزِقوا من كلِّ سبيلٍ، فأنزلنا عليهم المطر، وأنبتنا لهم الثمر، وهذا جزاء الدنيا. وإنَّ مِن أهل الكتاب فريقًا معتدلا ثابتًا على الحق، وكثير منهم ساء عملُه، وضل عن سواء السبيل.", "isBasmala": false, "translation_en": "Had they observed the Torah, and the Gospel, and what was revealed to them from their Lord, they would have consumed amply from above them, and from beneath their feet. Among them is a moderate community, but evil is what many of them are doing.", "translation_id": "Dan sekiranya mereka sungguh-sungguh menjalankan (hukum) Taurat dan Injil dan (Al Quran) yang diturunkan kepada mereka dari Tuhannya, niscaya mereka akan mendapat makanan dari atas dan dari bawah kaki mereka. Diantara mereka ada golongan yang pertengahan. Dan alangkah buruknya apa yang dikerjakan oleh kebanyakan mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 67, "text": "۞ یَـٰۤأَیُّهَا ٱلرَّسُولُ بَلِّغۡ مَاۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَۖ وَإِن لَّمۡ تَفۡعَلۡ فَمَا بَلَّغۡتَ رِسَالَتَهُۥۚ وَٱللَّهُ یَعۡصِمُكَ مِنَ ٱلنَّاسِۗ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡكَـٰفِرِینَ ۝٦٧", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "يا أيها الرسول بلِّغ وحي الله الذي أنزِل إليك من ربك، وإن قصَّرت في البلاغ فَكَتَمْتَ منه شيئًا، فإنك لم تُبَلِّغ رسالة ربِّك، وقد بلَّغ صلى الله عليه وسلم رسالة ربه كاملة، فمن زعم أنه كتم شيئًا مما أنزِل عليه، فقد أعظم على الله ورسوله الفرية. والله تعالى حافظك وناصرك على أعدائك، فليس عليك إلا البلاغ. إن الله لا يوفق للرشد مَن حاد عن سبيل الحق، وجحد ما جئت به من عند الله.", "isBasmala": false, "translation_en": "O Messenger, convey what was revealed to you from your Lord. But if you do not, then you would not have delivered His message. And God will protect you from the people. God does not guide the disbelieving people.", "translation_id": "Hai Rasul, sampaikanlah apa yang diturunkan kepadamu dari Tuhanmu. Dan jika tidak kamu kerjakan (apa yang diperintahkan itu, berarti) kamu tidak menyampaikan amanat-Nya. Allah memelihara kamu dari (gangguan) manusia. Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 68, "text": "قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لَسۡتُمۡ عَلَىٰ شَیۡءٍ حَتَّىٰ تُقِیمُوا۟ ٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَ وَمَاۤ أُنزِلَ إِلَیۡكُم مِّن رَّبِّكُمۡۗ وَلَیَزِیدَنَّ كَثِیرࣰا مِّنۡهُم مَّاۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ طُغۡیَـٰنࣰا وَكُفۡرࣰاۖ فَلَا تَأۡسَ عَلَى ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ ۝٦٨", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "قل -أيها الرسول- لليهود والنصارى: إنكم لستم على حظٍّ من الدين ما دمتم لم تعملوا بما في التوراة والإنجيل، وما جاءكم به محمد من القرآن، وإن كثيرًا من أهل الكتاب لا يزيدهم إنزالُ القرآن إليك إلا تجبُّرًا وجحودًا، فهم يحسدونك؛ لأن الله بعثك بهذه الرسالة الخاتمة، التي بَيَّن فيها معايبهم، فلا تحزن -أيها الرسول- على تكذيبهم لك.", "isBasmala": false, "translation_en": "Say, \"O People of the Scripture! You have no basis until you uphold the Torah, and the Gospel, and what is revealed to you from your Lord.\" But what is revealed to you from your Lord will increase many of them in rebellion and disbelief, so do not be sorry for the disbelieving people.", "translation_id": "Katakanlah: \"Hai Ahli Kitab, kamu tidak dipandang beragama sedikitpun hingga kamu menegakkan ajaran-ajaran Taurat, Injil, dan Al Quran yang diturunkan kepadamu dari Tuhanmu\". Sesungguhnya apa yang diturunkan kepadamu (Muhammad) dari Tuhanmu akan menambah kedurhakaan dan kekafiran kepada kebanyakan dari mereka; maka janganlah kamu bersedih hati terhadap orang-orang yang kafir itu.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 69, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَٱلَّذِینَ هَادُوا۟ وَٱلصَّـٰبِـُٔونَ وَٱلنَّصَـٰرَىٰ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَعَمِلَ صَـٰلِحࣰا فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝٦٩", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "إن الذين آمنوا (وهم المسلمون) واليهود، والصابئين (وهم قوم باقون على فطرتهم، ولا دين مقرر لهم يتبعونه) والنصارى (وهم أتباع المسيح) من آمن منهم بالله الإيمان الكامل، وهو توحيد الله والتصديق بمحمد صلى الله عليه وسلم وبما جاء به، وآمن باليوم الآخر، وعمل العمل الصالح، فلا خوف عليهم من أهوال يوم القيامة، ولا هم يحزنون على ما تركوه وراءهم في الدنيا.", "isBasmala": false, "translation_en": "Those who believe, and the Jews, and the Sabians, and the Christians-whoever believes in God and the Last Day, and does what is right-they have nothing to fear, nor shall they grieve.", "translation_id": "Sesungguhnya orang-orang mukmin, orang-orang Yahudi, Shabiin dan orang-orang Nasrani, siapa saja (diantara mereka) yang benar-benar saleh, maka tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 70, "text": "لَقَدۡ أَخَذۡنَا مِیثَـٰقَ بَنِیۤ إِسۡرَ ٰۤءِیلَ وَأَرۡسَلۡنَاۤ إِلَیۡهِمۡ رُسُلࣰاۖ كُلَّمَا جَاۤءَهُمۡ رَسُولُۢ بِمَا لَا تَهۡوَىٰۤ أَنفُسُهُمۡ فَرِیقࣰا كَذَّبُوا۟ وَفَرِیقࣰا یَقۡتُلُونَ ۝٧٠", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "لقد أخذنا العهد المؤكَّد على بني إسرائيل في التوراة بالسمع والطاعة، وأرسلنا إليهم بذلك رسلنا، فَنَقَضوا ما أُخذ عليهم من العهد، واتبعوا أهواءهم، وكانوا كلما جاءهم رسول من أولئك الرسل بما لا تشتهيه أنفسهم عادَوْه: فكذبوا فريقًا من الرسل، وقتلوا فريقًا آخر.", "isBasmala": false, "translation_en": "We made a covenant with the Children of Israel, and We sent to them messengers. Whenever a messenger came to them with what their souls did not desire, some of them they accused of lying, and others they put to death.", "translation_id": "Sesungguhnya Kami telah mengambil perjanjian dari Bani Israil, dan telah Kami utus kepada mereka rasul-rasul. Tetapi setiap datang seorang rasul kepada mereka dengan membawa apa yang yang tidak diingini oleh hawa nafsu mereka, (maka) sebagian dari rasul-rasul itu mereka dustakan dan sebagian yang lain mereka bunuh.", "manzil": 2, "manzil_display": ""}], "120": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 71, "text": "وَحَسِبُوۤا۟ أَلَّا تَكُونَ فِتۡنَةࣱ فَعَمُوا۟ وَصَمُّوا۟ ثُمَّ تَابَ ٱللَّهُ عَلَیۡهِمۡ ثُمَّ عَمُوا۟ وَصَمُّوا۟ كَثِیرࣱ مِّنۡهُمۡۚ وَٱللَّهُ بَصِیرُۢ بِمَا یَعۡمَلُونَ ۝٧١", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "وظنَّ هؤلاء العُصاة أن الله لن يأخذهم بالعذاب جزاء عصيانهم وعُتُوِّهم، فمضوا في شهواتهم، وعمُوا عن الهدى فلم يبصروه، وصَمُّوا عن سماع الحقِّ فلم ينتفعوا به، فأنزل الله بهم بأسه، فتابوا فتاب الله عليهم، ثم عَمِي كثيرٌ منهم، وصمُّوا، بعدما تبين لهم الحقُّ، والله بصير بأعمالهم خيرها وشرها وسيجازيهم عليها.", "isBasmala": false, "translation_en": "They assumed there would be no punishment, so they turned blind and deaf. Then God redeemed them, but then again many of them turned blind and deaf. But God is Seeing of what they do.", "translation_id": "Dan mereka mengira bahwa tidak akan terjadi suatu bencanapun (terhadap mereka dengan membunuh nabi-nabi itu), maka (karena itu) mereka menjadi buta dan pekak, kemudian Allah menerima taubat mereka, kemudian kebanyakan dari mereka buta dan tuli (lagi). Dan Allah Maha Melihat apa yang mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 72, "text": "لَقَدۡ كَفَرَ ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ هُوَ ٱلۡمَسِیحُ ٱبۡنُ مَرۡیَمَۖ وَقَالَ ٱلۡمَسِیحُ یَـٰبَنِیۤ إِسۡرَ ٰۤءِیلَ ٱعۡبُدُوا۟ ٱللَّهَ رَبِّی وَرَبَّكُمۡۖ إِنَّهُۥ مَن یُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَیۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ وَمَا لِلظَّـٰلِمِینَ مِنۡ أَنصَارࣲ ۝٧٢", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "يقسم الله تعالى بأن الذين قالوا: إن الله هو المسيح ابن مريم، قد كفروا بمقالتهم هذه، وأخبر تعالى أن المسيح قال لبني إسرائيل: اعبدوا الله وحده لا شريك له، فأنا وأنتم في العبودية سواء. إنه من يعبد مع الله غيره فقد حرَّم الله عليه الجنة، وجعل النار مُستَقَرَّه، وليس له ناصرٌ يُنقذُه منها.", "isBasmala": false, "translation_en": "They disbelieve those who say, \"God is the Messiah the son of Mary.\" But the Messiah himself said, \"O Children of Israel, worship God, my Lord and your Lord. Whoever associates others with God, God has forbidden him Paradise, and his dwelling is the Fire. The wrongdoers have no saviors.\"", "translation_id": "Sesungguhnya telah kafirlah orang-orang yang berkata: \"Sesungguhnya Allah ialah Al Masih putera Maryam\", padahal Al Masih (sendiri) berkata: \"Hai Bani Israil, sembahlah Allah Tuhanku dan Tuhanmu\". Sesungguhnya orang yang mempersekutukan (sesuatu dengan) Allah, maka pasti Allah mengharamkan kepadanya surga, dan tempatnya ialah neraka, tidaklah ada bagi orang-orang zalim itu seorang penolongpun.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 73, "text": "لَّقَدۡ كَفَرَ ٱلَّذِینَ قَالُوۤا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَـٰثَةࣲۘ وَمَا مِنۡ إِلَـٰهٍ إِلَّاۤ إِلَـٰهࣱ وَ ٰحِدࣱۚ وَإِن لَّمۡ یَنتَهُوا۟ عَمَّا یَقُولُونَ لَیَمَسَّنَّ ٱلَّذِینَ كَفَرُوا۟ مِنۡهُمۡ عَذَابٌ أَلِیمٌ ۝٧٣", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "لقد كفر من النصارى من قال: إنَّ الله مجموع ثلاثة أشياء: هي الأب، والابن، وروح القدس. أما عَلِمَ هؤلاء النصارى أنه ليس للناس سوى معبود واحد، لم يلد ولم يولد، وإن لم ينته أصحاب هذه المقالة عن افترائهم وكذبهم ليُصِيبَنَّهم عذاب مؤلم موجع بسبب كفرهم بالله.", "isBasmala": false, "translation_en": "They disbelieve those who say, \"God is the third of three.\" But there is no deity except the One God. If they do not refrain from what they say, a painful torment will befall those among them who disbelieve.", "translation_id": "Sesungguhnya kafirlah orang0orang yang mengatakan: \"Bahwasanya Allah salah seorang dari yang tiga\", padahal sekali-kali tidak ada Tuhan selain dari Tuhan Yang Esa. Jika mereka tidak berhenti dari apa yang mereka katakan itu, pasti orang-orang yang kafir diantara mereka akan ditimpa siksaan yang pedih.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 74, "text": "أَفَلَا یَتُوبُونَ إِلَى ٱللَّهِ وَیَسۡتَغۡفِرُونَهُۥۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٧٤", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "أفلا يرجع هؤلاء النصارى إلى الله تعالى، ويتولون عمَّا قالوا، ويسألون الله تعالى المغفرة؟ والله تعالى متجاوز عن ذنوب التائبين، رحيمٌ بهم", "isBasmala": false, "translation_en": "Will they not repent to God and ask His forgiveness? God is Forgiving and Merciful.", "translation_id": "Maka mengapa mereka tidak bertaubat kepada Allah dan memohon ampun kepada-Nya?. Dan Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 75, "text": "مَّا ٱلۡمَسِیحُ ٱبۡنُ مَرۡیَمَ إِلَّا رَسُولࣱ قَدۡ خَلَتۡ مِن قَبۡلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّیقَةࣱۖ كَانَا یَأۡكُلَانِ ٱلطَّعَامَۗ ٱنظُرۡ كَیۡفَ نُبَیِّنُ لَهُمُ ٱلۡـَٔایَـٰتِ ثُمَّ ٱنظُرۡ أَنَّىٰ یُؤۡفَكُونَ ۝٧٥", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "ما المسيح ابن مريم عليه السلام إلا رسولٌ كمن تقدمه من الرسل، وأُمُّه قد صَدَّقت تصديقًا جازمًا علمًا وعملا وهما كغيرهما من البشر يحتاجان إلى الطعام، ولا يكون إلهًا مَن يحتاج الى الطعام ليعيش. فتأمَّل -أيها الرسول- حال هؤلاء الكفار. لقد وضحنا العلاماتِ الدالةَ على وحدانيتنا، وبُطلان ما يَدَّعونه في أنبياء الله. ثم هم مع ذلك يَضِلُّون عن الحق الذي نَهديهم إليه، ثم انظر كيف يُصرفون عن الحق بعد هذا البيان؟", "isBasmala": false, "translation_en": "The Messiah son of Mary was only a messenger, before whom other Messengers had passed away, and his mother was a woman of truth. They both used to eat food. Note how We make clear the revelations to them; then note how deluded they are.", "translation_id": "Al Masih putera Maryam itu hanyalah seorang Rasul yang sesungguhnya telah berlalu sebelumnya beberapa rasul, dan ibunya seorang yang sangat benar, kedua-duanya biasa memakan makanan. Perhatikan bagaimana Kami menjelaskan kepada mereka (ahli kitab) tanda-tanda kekuasaan (Kami), kemudian perhatikanlah bagaimana mereka berpaling (dari memperhatikan ayat-ayat Kami itu).", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 76, "text": "قُلۡ أَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَمۡلِكُ لَكُمۡ ضَرࣰّا وَلَا نَفۡعࣰاۚ وَٱللَّهُ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٧٦", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "قل -أيها الرسول- لهؤلاء الكفرة: كيف تشركون مع الله من لا يَقْدِرُ على ضَرِّكم، ولا على جَلْبِ نفع لكم؟ والله هو السميع لأقوال عباده، العليم بأحوالهم.", "isBasmala": false, "translation_en": "Say, \"Do you worship, besides God, what has no power to harm or benefit you?\" But God: He is the Hearer, the Knower.", "translation_id": "Katakanlah: \"Mengapa kamu menyembah selain daripada Allah, sesuatu yang tidak dapat memberi mudharat kepadamu dan tidak (pula) memberi manfaat?\" Dan Allah-lah Yang Maha Mendengar lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}], "121": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 77, "text": "قُلۡ یَـٰۤأَهۡلَ ٱلۡكِتَـٰبِ لَا تَغۡلُوا۟ فِی دِینِكُمۡ غَیۡرَ ٱلۡحَقِّ وَلَا تَتَّبِعُوۤا۟ أَهۡوَاۤءَ قَوۡمࣲ قَدۡ ضَلُّوا۟ مِن قَبۡلُ وَأَضَلُّوا۟ كَثِیرࣰا وَضَلُّوا۟ عَن سَوَاۤءِ ٱلسَّبِیلِ ۝٧٧", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "قل -أيها الرسول- للنصارى: لا تتجاوزوا الحقَّ فيما تعتقدونه من أمر المسيح، ولا تتبعوا أهواءكم، كما اتَّبع اليهود أهواءهم في أمر الدين، فوقعوا في الضلال، وحملوا كثيرًا من الناس على الكفر بالله، وخرجوا عن طريق الاستقامة الى طريق الغَواية والضلال.", "isBasmala": false, "translation_en": "Say, \"O People of the Scripture! Do not exaggerate in your religion beyond the truth; and do not follow the opinions of people who went astray before, and misled many, and themselves strayed off the balanced way.\"", "translation_id": "Katakanlah: \"Hai Ahli Kitab, janganlah kamu berlebih-lebihan (melampaui batas) dengan cara tidak benar dalam agamamu. Dan janganlah kamu mengikuti hawa nafsu orang-orang yang telah sesat dahulunya (sebelum kedatangan Muhammad) dan mereka telah menyesatkan kebanyakan (manusia), dan mereka tersesat dari jalan yang lurus\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 78, "text": "لُعِنَ ٱلَّذِینَ كَفَرُوا۟ مِنۢ بَنِیۤ إِسۡرَ ٰۤءِیلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِیسَى ٱبۡنِ مَرۡیَمَۚ ذَ ٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ یَعۡتَدُونَ ۝٧٨", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "يخبر تعالى أنه طرد من رحمته الكافرين من بني إسرائيل في الكتاب الذي أنزله على داود -عليه السلام- وهو الزَّبور، وفي الكتاب الذي أنزله على عيسى - عليه السلام - وهو الإنجيل؛ بسبب عصيانهم واعتدائهم على حرمات الله.", "isBasmala": false, "translation_en": "Cursed were those who disbelieved from among the Children of Israel by the tongue of David and Jesus son of Mary. That is because they rebelled and used to transgress.", "translation_id": "Telah dilaknati orang-orang kafir dari Bani Israil dengan lisan Daud dan Isa putera Maryam. Yang demikian itu, disebabkan mereka durhaka dan selalu melampaui batas.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 79, "text": "كَانُوا۟ لَا یَتَنَاهَوۡنَ عَن مُّنكَرࣲ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُوا۟ یَفۡعَلُونَ ۝٧٩", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "كان هؤلاء اليهود يُجاهرون بالمعاصي ويرضونها، ولا يَنْهى بعضُهم بعضًا عن أيِّ منكر فعلوه، وهذا من أفعالهم السيئة، وبه استحقوا أن يُطْرَدُوا من رحمة الله تعالى.", "isBasmala": false, "translation_en": "They used not to prevent one another from the wrongs they used to commit. Evil is what they used to do.", "translation_id": "Mereka satu sama lain selalu tidak melarang tindakan munkar yang mereka perbuat. Sesungguhnya amat buruklah apa yang selalu mereka perbuat itu.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 80, "text": "تَرَىٰ كَثِیرࣰا مِّنۡهُمۡ یَتَوَلَّوۡنَ ٱلَّذِینَ كَفَرُوا۟ۚ لَبِئۡسَ مَا قَدَّمَتۡ لَهُمۡ أَنفُسُهُمۡ أَن سَخِطَ ٱللَّهُ عَلَیۡهِمۡ وَفِی ٱلۡعَذَابِ هُمۡ خَـٰلِدُونَ ۝٨٠", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "تَرَى -أيها الرسول- كثيرًا من هؤلاء اليهود يتخذون المشركين أولياء لهم، ساء ما عملوه من الموالاة التي كانت سببًا في غضب الله عليهم، وخلودهم في عذاب الله يوم القيامة.", "isBasmala": false, "translation_en": "You will see many of them befriending those who disbelieve. Terrible is what their souls prompts them to do. The wrath of God fell upon them, and in the torment they will remain.", "translation_id": "Kamu melihat kebanyakan dari mereka tolong-menolong dengan orang-orang yang kafir (musyrik). Sesungguhnya amat buruklah apa yang mereka sediakan untuk diri mereka, yaitu kemurkaan Allah kepada mereka; dan mereka akan kekal dalam siksaan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 81, "text": "وَلَوۡ كَانُوا۟ یُؤۡمِنُونَ بِٱللَّهِ وَٱلنَّبِیِّ وَمَاۤ أُنزِلَ إِلَیۡهِ مَا ٱتَّخَذُوهُمۡ أَوۡلِیَاۤءَ وَلَـٰكِنَّ كَثِیرࣰا مِّنۡهُمۡ فَـٰسِقُونَ ۝٨١", "juz": 6, "hizb": "(*¾ ح 12*)", "tafsir": "ولو أن هؤلاء اليهود الذين يناصرون المشركين كانوا قد آمنوا بالله تعالى والنبي محمد صلى الله عليه وسلم، وأقرُّوا بما أنزل إليه -وهو القرآن الكريم- ما اتخذوا الكفار أصحابًا وأنصارًا، ولكن كثيرًا منهم خارجون عن طاعة الله ورسوله.", "isBasmala": false, "translation_en": "Had they believed in God and the Prophet, and in what was revealed to him, they would not have befriended them. But many of them are immoral.", "translation_id": "Sekiranya mereka beriman kepada Allah, kepada Nabi (Musa) dan kepada apa yang diturunkan kepadanya (Nabi), niscaya mereka tidak akan mengambil orang-orang musyrikin itu menjadi penolong-penolong, tapi kebanyakan dari mereka adalah orang-orang yang fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 82, "text": "۞ لَتَجِدَنَّ أَشَدَّ ٱلنَّاسِ عَدَ ٰوَةࣰ لِّلَّذِینَ ءَامَنُوا۟ ٱلۡیَهُودَ وَٱلَّذِینَ أَشۡرَكُوا۟ۖ وَلَتَجِدَنَّ أَقۡرَبَهُم مَّوَدَّةࣰ لِّلَّذِینَ ءَامَنُوا۟ ٱلَّذِینَ قَالُوۤا۟ إِنَّا نَصَـٰرَىٰۚ ذَ ٰلِكَ بِأَنَّ مِنۡهُمۡ قِسِّیسِینَ وَرُهۡبَانࣰا وَأَنَّهُمۡ لَا یَسۡتَكۡبِرُونَ ۝٨٢", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "لتجدنَّ -أيها الرسول- أشدَّ الناس عداوة للذين صدَّقوك وآمنوا بك واتبعوك، اليهودَ؛ لعنادهم، وجحودهم، وغمطهم الحق، والذين أشركوا مع الله غيره، كعبدة الأوثان وغيرهم، ولتجدنَّ أقربهم مودة للمسلمين الذين قالوا: إنا نصارى، ذلك بأن منهم علماء بدينهم متزهدين وعبَّادًا في الصوامع متنسكين، وأنهم متواضعون لا يستكبرون عن قَبول الحق، وهؤلاء هم الذين قبلوا رسالة محمد صلى الله عليه وسلم، وآمنوا بها.", "isBasmala": false, "translation_en": "You will find that the people most hostile towards the believers are the Jews and the polytheists. And you will find that the nearest in affection towards the believers are those who say, \"We are Christians.\" That is because among them are priests and monks, and they are not arrogant.", "translation_id": "Sesungguhnya kamu dapati orang-orang yang paling keras permusuhannya terhadap orang-orang yang beriman ialah orang-orang Yahudi dan orang-orang musyrik. Dan sesungguhnya kamu dapati yang paling dekat persahabatannya dengan orang-orang yang beriman ialah orang-orang yang berkata: \"Sesungguhnya kami ini orang Nasrani\". Yang demikian itu disebabkan karena di antara mereka itu (orang-orang Nasrani) terdapat pendeta-pendeta dan rahib-rahib, (juga) karena sesungguhnya mereka tidak menymbongkan diri.", "manzil": 2, "manzil_display": ""}], "122": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 83, "text": "وَإِذَا سَمِعُوا۟ مَاۤ أُنزِلَ إِلَى ٱلرَّسُولِ تَرَىٰۤ أَعۡیُنَهُمۡ تَفِیضُ مِنَ ٱلدَّمۡعِ مِمَّا عَرَفُوا۟ مِنَ ٱلۡحَقِّۖ یَقُولُونَ رَبَّنَاۤ ءَامَنَّا فَٱكۡتُبۡنَا مَعَ ٱلشَّـٰهِدِینَ ۝٨٣", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "ومما يدل على قرب مودتهم للمسلمين أن فريقًا منهم (وهم وفد الحبشة لما سمعوا القرآن) فاضت أعينهم من الدمع فأيقنوا أنه حقٌّ منزل من عند الله تعالى، وصدَّقوا بالله واتبعوا رسوله، وتضرعوا إلى الله أن يكرمهم بشرف الشهادة مع أمَّة محمد عليه السلام على الأمم يوم القيامة.", "isBasmala": false, "translation_en": "And when they hear what was revealed to the Messenger, you see their eyes overflowing with tears, as they recognize the truth in it. They say, \"Our Lord, we have believed, so count us among the witnesses.\"", "translation_id": "Dan apabila mereka mendengarkan apa yang diturunkan kepada Rasul (Muhammad), kamu lihat mata mereka mencucurkan air mata disebabkan kebenaran (Al Quran) yang telah mereka ketahui (dari kitab-kitab mereka sendiri); seraya berkata: \"Ya Tuhan kami, kami telah beriman, maka catatlah kami bersama orang-orang yang menjadi saksi (atas kebenaran Al Quran dan kenabian Muhammad s. a. w.).", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 84, "text": "وَمَا لَنَا لَا نُؤۡمِنُ بِٱللَّهِ وَمَا جَاۤءَنَا مِنَ ٱلۡحَقِّ وَنَطۡمَعُ أَن یُدۡخِلَنَا رَبُّنَا مَعَ ٱلۡقَوۡمِ ٱلصَّـٰلِحِینَ ۝٨٤", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "وقالوا: وأيُّ لوم علينا في إيماننا بالله، وتصديقنا بالحق الذي جاءنا به محمد صلى الله عليه وسلم من عند الله، واتباعنا له، ونرجو أن يدخلنا ربنا مع أهل طاعته في جنته يوم القيامة؟", "isBasmala": false, "translation_en": "\"And why should we not believe in God, and in the truth that has come to us, and hope that our Lord will include us among the righteous people?\"", "translation_id": "Mengapa kami tidak akan beriman kepada Allah dan kepada kebenaran yang datang kepada kami, padahal kami sangat ingin agar Tuhan kami memasukkan kami ke dalam golongan orang-orang yang saleh?\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 85, "text": "فَأَثَـٰبَهُمُ ٱللَّهُ بِمَا قَالُوا۟ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ وَذَ ٰلِكَ جَزَاۤءُ ٱلۡمُحۡسِنِینَ ۝٨٥", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "فجزاهم الله بما قالوا من الاعتزاز بإيمانهم بالإسلام، وطلبهم أن يكونوا مع القوم الصالحين، جنات تجري من تحت أشجارها الأنهار، ماكثين فيها لا يخرجون منها، ولا يُحوَّلون عنها، وذلك جزاء إحسانهم في القول والعمل.", "isBasmala": false, "translation_en": "God will reward them for what they say-Gardens beneath which rivers flow, where they will stay forever. Such is the reward of the righteous.", "translation_id": "Maka Allah memberi mereka pahala terhadap perkataan yang mereka ucapkan, (yaitu) surga yang mengalir sungai-sungai di dalamnya, sedang mereka kekal di dalamnya. Dan itulah balasan (bagi) orang-orang yang berbuat kebaikan (yang ikhlas keimanannya).", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 86, "text": "وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ ۝٨٦", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "والذين جحدوا وحدانية الله وأنكروا نبوة محمد صلى الله عليه وسلم، وكذَّبوا بآياته المنزلة على رسله، أولئك هم أصحاب النار الملازمون لها.", "isBasmala": false, "translation_en": "But as for those who disbelieve and deny Our signs-these are the inmates of the Fire.", "translation_id": "Dan orang-orang kafir serta mendustakan ayat-ayat Kami, mereka itulah penghuni neraka.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 87, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُحَرِّمُوا۟ طَیِّبَـٰتِ مَاۤ أَحَلَّ ٱللَّهُ لَكُمۡ وَلَا تَعۡتَدُوۤا۟ۚ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡمُعۡتَدِینَ ۝٨٧", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "يا أيها الذين آمنوا لا تحرِّموا طيبات أحلَّها الله لكم من المطاعم والمشارب ونكاح النساء، فتضيقوا ما وسَّع الله عليكم، ولا تتجاوزوا حدود ما حرَّم الله. إن الله لا يحب المعتدين.", "isBasmala": false, "translation_en": "O you who believe! Do not prohibit the good things God has permitted for you, and do not commit aggression. God does not love the aggressors.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu haramkan apa-apa yang baik yang telah Allah halalkan bagi kamu, dan janganlah kamu melampaui batas. Sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 88, "text": "وَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَـٰلࣰا طَیِّبࣰاۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ أَنتُم بِهِۦ مُؤۡمِنُونَ ۝٨٨", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "وتمتعوا -أيها المؤمنون- بالحلال الطيب مما أعطاكم الله ومنحكم إياه، واتقوا الله بامتثال أوامره، واجتناب نواهيه؛ فإن إيمانكم بالله يوجب عليكم تقواه ومراقبته.", "isBasmala": false, "translation_en": "And eat of the lawful and good things God has provided for you; and be conscious of God, in whom you are believers.", "translation_id": "Dan makanlah makanan yang halal lagi baik dari apa yang Allah telah rezekikan kepadamu, dan bertakwalah kepada Allah yang kamu beriman kepada-Nya.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 89, "text": "لَا یُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِیۤ أَیۡمَـٰنِكُمۡ وَلَـٰكِن یُؤَاخِذُكُم بِمَا عَقَّدتُّمُ ٱلۡأَیۡمَـٰنَۖ فَكَفَّـٰرَتُهُۥۤ إِطۡعَامُ عَشَرَةِ مَسَـٰكِینَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِیكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِیرُ رَقَبَةࣲۖ فَمَن لَّمۡ یَجِدۡ فَصِیَامُ ثَلَـٰثَةِ أَیَّامࣲۚ ذَ ٰلِكَ كَفَّـٰرَةُ أَیۡمَـٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوۤا۟ أَیۡمَـٰنَكُمۡۚ كَذَ ٰلِكَ یُبَیِّنُ ٱللَّهُ لَكُمۡ ءَایَـٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ ۝٨٩", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "لا يعاقبكم الله -أيها المسلمون- فيما لا تقصدون عَقْدَه من الأيمان، مثل قول بعضكم: لا والله، وبلى والله، ولكن يعاقبكم فيما قصدتم عقده بقلوبكم، فإذا لم تَفُوا باليمين فإثم ذلك يمحوه الله بما تقدِّمونه مما شرعه الله لكم كفارة من إطعام عشرة مساكين، لكل مسكين نصف صاع من أوسط طعام أهل البلد، أو كسوتهم، لكل مسكين ما يكفي في الكسوة عُرفًا، أو إعتاق مملوك من الرق، فالحالف الذي لم يف بيمينه مخير بين هنا الأمور الثلاثة، فمن لم يجد شيئًا من ذلك فعليه صيام ثلاثة أيام. تلك مكفرات عدم الوفاء بأيمانكم، واحفظوا -أيها المسلمون- أيمانكم: باجتناب الحلف، أو الوفاء إن حلفتم، أو الكفارة إذا لم تفوا بها. وكما بيَّن الله لكم حكم الأيمان والتحلل منها يُبيِّن لكم أحكام دينه؛ لتشكروا له على هدايته إياكم إلى الطريق المستقيم.", "isBasmala": false, "translation_en": "God does not hold you accountable for your unintended oaths, but He holds you accountable for your binding oaths. The atonement for it is by feeding ten needy people from the average of what you feed your families, or by clothing them, or by freeing a slave. Anyone who lacks the means shall fast for three days. That is the atonement for breaking your oaths when you have sworn them. So keep your oaths. Thus God makes clear His Revelations to you, that you may be grateful.", "translation_id": "Allah tidak menghukum kamu disebabkan sumpah-sumpahmu yang tidak dimaksud (untuk bersumpah), tetapi Dia menghukum kamu disebabkan sumpah-sumpah yang kamu sengaja, maka kaffarat (melanggar) sumpah itu, ialah memberi makan sepuluh orang miskin, yaitu dari makanan yang biasa kamu berikan kepada keluargamu, atau memberi pakaian kepada mereka atau memerdekakan seorang budak. Barang siapa tidak sanggup melakukan yang demikian, maka kaffaratnya puasa selama tiga hari. Yang demikian itu adalah kaffarat sumpah-sumpahmu bila kamu bersumpah (dan kamu langgar). Dan jagalah sumpahmu. Demikianlah Allah menerangkan kepadamu hukum-hukum-Nya agar kamu bersyukur (kepada-Nya).", "manzil": 2, "manzil_display": ""}], "123": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 90, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَیۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَـٰمُ رِجۡسࣱ مِّنۡ عَمَلِ ٱلشَّیۡطَـٰنِ فَٱجۡتَنِبُوهُ لَعَلَّكُمۡ تُفۡلِحُونَ ۝٩٠", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إنما الخمر: وهي كل مسكر يغطي العقل، والميسر: وهو القمار، وذلك يشمل المراهنات ونحوها، مما فيه عوض من الجانبين، وصدٌّ عن ذكر الله، والأنصاب: وهي الحجارة التي كان المشركون يذبحون عندها تعظيمًا لها، وما ينصب للعبادة تقربًا إليه، والأزلام: وهي القِداح التي يستقسم بها الكفار قبل الإقدام على الشيء، أو الإحجام عنه، إن ذلك كله إثمٌ مِن تزيين الشيطان، فابتعدوا عن هذه الآثام، لعلكم تفوزون بالجنة.", "isBasmala": false, "translation_en": "O you who believe! Intoxicants, gambling, idolatry, and divination are abominations of Satan's doing. Avoid them, so that you may prosper.", "translation_id": "Hai orang-orang yang beriman, sesungguhnya (meminum) khamar, berjudi, (berkorban untuk) berhala, mengundi nasib dengan panah, adalah termasuk perbuatan syaitan. Maka jauhilah perbuatan-perbuatan itu agar kamu mendapat keberuntungan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 91, "text": "إِنَّمَا یُرِیدُ ٱلشَّیۡطَـٰنُ أَن یُوقِعَ بَیۡنَكُمُ ٱلۡعَدَ ٰوَةَ وَٱلۡبَغۡضَاۤءَ فِی ٱلۡخَمۡرِ وَٱلۡمَیۡسِرِ وَیَصُدَّكُمۡ عَن ذِكۡرِ ٱللَّهِ وَعَنِ ٱلصَّلَوٰةِۖ فَهَلۡ أَنتُم مُّنتَهُونَ ۝٩١", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "إنما يريد الشيطان بتزيين الآثام لكم أن يُلقِي بينكم ما يوجد العداوة والبغضاء، بسبب شرب الخمر ولعب الميسر، ويصرفكم عن ذكر الله وعن الصلاة بغياب العقل في شرب الخمر، والاشتغال باللهو في لعب الميسر، فانتهوا عن ذلك.", "isBasmala": false, "translation_en": "Satan wants to provoke strife and hatred among you through intoxicants and gambling, and to prevent you from the remembrance of God, and from prayer. Will you not desist?", "translation_id": "Sesungguhnya syaitan itu bermaksud hendak menimbulkan permusuhan dan kebencian di antara kamu lantaran (meminum) khamar dan berjudi itu, dan menghalangi kamu dari mengingat Allah dan sembahyang; maka berhentilah kamu (dari mengerjakan pekerjaan itu).", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 92, "text": "وَأَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَ وَٱحۡذَرُوا۟ۚ فَإِن تَوَلَّیۡتُمۡ فَٱعۡلَمُوۤا۟ أَنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ ۝٩٢", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "وامتثلوا -أيها المسلمون- طاعة الله وطاعة رسوله محمد صلى الله عليه وسلم في كل ما تفعلون وتتركون، واتقوا الله وراقبوه في ذلك، فإن أعرضتم عن الامتثال فعملتم ما نهيتم عنه، فاعلموا أنما على رسولنا محمد صلى الله عليه وسلم البلاغ المبين.", "isBasmala": false, "translation_en": "Obey God and obey the Messenger, and be cautious. If you turn away-know that the duty of Our Messenger is clear communication.", "translation_id": "Dan taatlah kamu kepada Allah dan taatlah kamu kepada Rasul-(Nya) dan berhati-hatilah. Jika kamu berpaling, maka ketahuilah bahwa sesungguhnya kewajiban Rasul Kami, hanyalah menyampaikan (amanat Allah) dengan terang.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 93, "text": "لَیۡسَ عَلَى ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جُنَاحࣱ فِیمَا طَعِمُوۤا۟ إِذَا مَا ٱتَّقَوا۟ وَّءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ ثُمَّ ٱتَّقَوا۟ وَّءَامَنُوا۟ ثُمَّ ٱتَّقَوا۟ وَّأَحۡسَنُوا۟ۚ وَٱللَّهُ یُحِبُّ ٱلۡمُحۡسِنِینَ ۝٩٣", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "ليس على المؤمنين الذين شربوا الخمر قبل تحريمها إثم في ذلك، إذا تركوها واتقوا سخط الله وآمنوا به، وقدَّموا الأعمال الصالحة التي تدل على إيمانهم ورغبتهم في رضوان الله تعالى عنهم، ثم ازدادوا بذلك مراقبة لله عز وجل وإيمانا به، حتى أصبحوا مِن يقينهم يعبدونه، وكأنهم يرونه. وإن الله تعالى يحب الذين بلغوا درجة الإحسان حتى أصبح إيمانهم بالغيب كالمشاهدة.", "isBasmala": false, "translation_en": "Those who believe and do righteous deeds will not be blamed for what they may have eaten, provided they obey, and believe, and do good deeds, then maintain piety and faith, then remain righteous and charitable. God loves the charitable.", "translation_id": "Tidak ada dosa bagi orang-orang yang beriman dan mengerjakan amalan yang saleh karena memakan makanan yang telah mereka makan dahulu, apabila mereka bertakwa serta beriman, dan mengerjakan amalan-amalan yang saleh, kemudian mereka tetap bertakwa dan beriman, kemudian mereka (tetap juga) bertakwa dan berbuat kebajikan. Dan Allah menyukai orang-orang yang berbuat kebajikan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 94, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَیَبۡلُوَنَّكُمُ ٱللَّهُ بِشَیۡءࣲ مِّنَ ٱلصَّیۡدِ تَنَالُهُۥۤ أَیۡدِیكُمۡ وَرِمَاحُكُمۡ لِیَعۡلَمَ ٱللَّهُ مَن یَخَافُهُۥ بِٱلۡغَیۡبِۚ فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَ ٰلِكَ فَلَهُۥ عَذَابٌ أَلِیمࣱ ۝٩٤", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "يا أيها الذين صدقوا الله ورسوله وعملوا بشرعه، ليبلونكم الله بشيء من الصيد يقترب منكم على غير المعتاد حيث تستطيعون أَخْذَ صغاره بغير سلاح وأخذ كباره بالسلاح؛ ليعلم الله علمًا ظاهرًا للخلق الذين يخافون ربهم بالغيب، ليقينهم بكمال علمه بهم، وذلك بإمساكهم عن الصيد، وهم محرمون. فمن تجاوز حَدَّه بعد هذا البيان فأقدم على الصيد -وهو مُحْرِم- فإنه يستحق العذاب الشديد.", "isBasmala": false, "translation_en": "O you who believe! God will test you with something of the game your hands and spears obtain, that God may know who fears Him at heart. Whoever commits aggression after that will have a painful punishment.", "translation_id": "Hai orang-orang yang beriman, sesungguhnya Allah akan menguji kamu dengan sesuatu dari binatang buruan yang mudah didapat oleh tangan dan tombakmu supaya Allah mengetahui orang yang takut kepada-Nya, biarpun ia tidak dapat melihat-Nya. Barang siapa yang melanggar batas sesudah itu, maka baginya azab yang pedih.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 95, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَقۡتُلُوا۟ ٱلصَّیۡدَ وَأَنتُمۡ حُرُمࣱۚ وَمَن قَتَلَهُۥ مِنكُم مُّتَعَمِّدࣰا فَجَزَاۤءࣱ مِّثۡلُ مَا قَتَلَ مِنَ ٱلنَّعَمِ یَحۡكُمُ بِهِۦ ذَوَا عَدۡلࣲ مِّنكُمۡ هَدۡیَۢا بَـٰلِغَ ٱلۡكَعۡبَةِ أَوۡ كَفَّـٰرَةࣱ طَعَامُ مَسَـٰكِینَ أَوۡ عَدۡلُ ذَ ٰلِكَ صِیَامࣰا لِّیَذُوقَ وَبَالَ أَمۡرِهِۦۗ عَفَا ٱللَّهُ عَمَّا سَلَفَۚ وَمَنۡ عَادَ فَیَنتَقِمُ ٱللَّهُ مِنۡهُۚ وَٱللَّهُ عَزِیزࣱ ذُو ٱنتِقَامٍ ۝٩٥", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تقتلوا صيد البر، وأنتم محرمون بحج أو عمرة، أو كنتم داخل الحرم ومَن قتل أيَّ نوعٍ من صيد البرِّ متعمدًا فجزاء ذلك أن يذبح مثل ذلك الصيد من بهيمة الأنعام: الإبل أو البقر أو الغنم، بعد أن يُقَدِّره اثنان عدلان، وأن يهديه لفقراء الحرم، أو أن يشتري بقيمة مثله طعامًا يهديه لفقراء الحرم لكل مسكين نصف صاع، أو يصوم بدلا من ذلك يوما عن كل نصف صاع من ذلك الطعام، فَرَضَ الله عليه هذا الجزاء؛ ليلقى بإيجاب الجزاء المذكور عاقبة فِعْله. والذين وقعوا في شيء من ذلك قبل التحريم فإن الله تعالى قد عفا عنهم، ومَن عاد إلى المخالفة متعمدًا بعد التحريم، فإنه مُعَرَّض لانتقام الله منه. والله تعالى عزيز قويٌّ منيع في سلطانه، ومِن عزته أنه ينتقم ممن عصاه إذا أراد، لا يمنعه من ذلك مانع.", "isBasmala": false, "translation_en": "O you who believe! do not kill game while you are in pilgrim sanctity. Whoever of you kills any intentionally, its penalty shall be a domestic animal comparable to what he killed, as determined by two honest persons among you-an offering delivered to the Kaabah. Or he may atone by feeding the needy, or its equivalent in fasting, so that he may taste the consequences of his conduct. God forgives what is past. But whoever repeats, God will take revenge on him. God is Almighty, Avenger.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu membunuh binatang buruan, ketika kamu sedang ihram. Barangsiapa di antara kamu membunuhnya dengan sengaja, maka dendanya ialah mengganti dengan binatang ternak seimbang dengan buruan yang dibunuhnya, menurut putusan dua orang yang adil di antara kamu sebagai had-yad yang dibawa sampai ke Ka'bah atau (dendanya) membayar kaffarat dengan memberi makan orang-orang miskin atau berpuasa seimbang dengan makanan yang dikeluarkan itu, supaya dia merasakan akibat buruk dari perbuatannya. Allah telah memaafkan apa yang telah lalu. Dan barangsiapa yang kembali mengerjakannya, niscaya Allah akan menyiksanya. Allah Maha Kuasa lagi mempunyai (kekuasaan untuk) menyiksa.", "manzil": 2, "manzil_display": ""}], "124": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 96, "text": "أُحِلَّ لَكُمۡ صَیۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَـٰعࣰا لَّكُمۡ وَلِلسَّیَّارَةِۖ وَحُرِّمَ عَلَیۡكُمۡ صَیۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمࣰاۗ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ إِلَیۡهِ تُحۡشَرُونَ ۝٩٦", "juz": 7, "hizb": "(* ح 13*)", "tafsir": "أحل الله لكم -أيها المسلمون- في حال إحرامكم صيد البحر، وهو ما يصاد منه حيًّا، وطعامه: وهو الميت منه؛ من أجل انتفاعكم به مقيمين أو مسافرين، وحرم عليكم صيد البَرِّ ما دمتم محرمين بحج أو عمرة. واخشوا الله ونفذوا جميع أوامِره، واجتنبوا جميع نواهيه؛ حتى تظفَروا بعظيم ثوابه، وتَسْلموا من أليم عقابه عندما تحشرون للحساب والجزاء.", "isBasmala": false, "translation_en": "Permitted for you is the catch of sea, and its food-as sustenance for you and for travelers. But forbidden for you is the game of land while you are in pilgrim sanctity. And fear God, to whom you will be gathered.", "translation_id": "Dihalalkan bagimu binatang buruan laut dan makanan (yang berasal) dari laut sebagai makanan yang lezat bagimu, dan bagi orang-orang yang dalam perjalanan; dan diharamkan atasmu (menangkap) binatang buruan darat, selama kamu dalam ihram. Dan bertakwalah kepada Allah Yang kepada-Nya-lah kamu akan dikumpulkan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 97, "text": "۞ جَعَلَ ٱللَّهُ ٱلۡكَعۡبَةَ ٱلۡبَیۡتَ ٱلۡحَرَامَ قِیَـٰمࣰا لِّلنَّاسِ وَٱلشَّهۡرَ ٱلۡحَرَامَ وَٱلۡهَدۡیَ وَٱلۡقَلَـٰۤىِٕدَۚ ذَ ٰلِكَ لِتَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِ وَأَنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمٌ ۝٩٧", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "امتنَّ الله على عباده بأن جعل الكعبة البيت الحرام صلاحًا لدينهم، وأمنًا لحياتهم؛ وذلك حيث آمنوا بالله ورسوله وأقاموا فرائضه، وحرَّم العدوان والقتال في الأشهر الحرم (وهي ذو القعدة وذو الحجة والمحرم ورجب) فلا يعتدي فيها أحد على أحد، وحرَّم تعالى الاعتداء على ما يُهدَى إلى الحرم من بهيمة الأنعام، وحرَّم كذلك الاعتداء على القلائد، وهي ما قُلِّد إشعارًا بأنه بقصد به النسك؛ ذلك لتعلموا أن الله يعلم جميع ما في السموات وما في الأرض، ومن ذلك ما شرعه لحماية خلقه بعضهم من بعض، وأن الله بكل شيء عليم، فلا تخفى عليه خافية.", "isBasmala": false, "translation_en": "God has appointed the Kaabah, the Sacred House, a sanctuary for the people, and the Sacred Month, and the offerings, and the garlanded. That you may know that God knows everything in the heavens and the earth, and that God is Cognizant of all things.", "translation_id": "Allah telah menjadikan Ka'bah, rumah suci itu sebagai pusat (peribadatan dan urusan dunia) bagi manusia, dan (demikian pula) bulan Haram, had-ya, qalaid. (Allah menjadikan yang) demikian itu agar kamu tahu, bahwa sesungguhnya Allah mengetahui apa yang ada di langit dan apa yang ada di bumi dan bahwa sesungguhnya Allah Maha Mengetahui segala sesuatu.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 98, "text": "ٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ وَأَنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝٩٨", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "اعلموا -أيها الناس- أن الله جل وعلا شديد العقاب لمن عصاه، وأن الله غفور رحيم لمن تاب وأناب.", "isBasmala": false, "translation_en": "Know that God is severe in retribution, and that God is Forgiving and Merciful.", "translation_id": "Ketahuilah, bahwa sesungguhnya Allah amat berat siksa-Nya dan bahwa sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 99, "text": "مَّا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَـٰغُۗ وَٱللَّهُ یَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ ۝٩٩", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "يبيِّن الله تعالى أن مهمة رسوله صلى الله عليه وسلم هداية الدلالة والتبليغ، وبيد الله -وحده- هداية التوفيق، وأن ما تنطوي عليه نفوس الناس مما يُسرون أو يعلنون من الهداية أو الضلال يعلمه الله.", "isBasmala": false, "translation_en": "The Messenger's sole duty is to convey. God knows what you reveal and what you conceal.", "translation_id": "Kewajiban Rasul tidak lain hanyalah menyampaikan, dan Allah mengetahui apa yang kamu lahirkan dan apa yang kamu sembunyikan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 100, "text": "قُل لَّا یَسۡتَوِی ٱلۡخَبِیثُ وَٱلطَّیِّبُ وَلَوۡ أَعۡجَبَكَ كَثۡرَةُ ٱلۡخَبِیثِۚ فَٱتَّقُوا۟ ٱللَّهَ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ لَعَلَّكُمۡ تُفۡلِحُونَ ۝١٠٠", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "قل -أيها الرسول-: لا يستوي الخبيث والطيب من كل شيء، فالكافر لا يساوي المؤمن، والعاصي لا يساوي المطيع، والجاهل لا يساوي العالم، والمبتدع لا يساوي المتبع، والمال الحرام لا يساوي الحلال، ولو أعجبك -أيها الإنسان- كثرة الخبيث وعدد أهله. فاتقوا الله يا أصحاب العقول الراجحة باجتناب الخبائث، وفعل الطيبات؛ لتفلحوا بنيل المقصود الأعظم، وهو رضا الله تعالى والفوز بالجنة.", "isBasmala": false, "translation_en": "Say: \"The bad and the good are not equal, even though the abundance of the bad may impress you. So be conscious of God, O you who possess intelligence, that you may succeed.\"", "translation_id": "Katakanlah: \"Tidak sama yang buruk dengan yang baik, meskipun banyaknya yang buruk itu menarik hatimu, maka bertakwalah kepada Allah hai orang-orang berakal, agar kamu mendapat keberuntungan\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 101, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَسۡـَٔلُوا۟ عَنۡ أَشۡیَاۤءَ إِن تُبۡدَ لَكُمۡ تَسُؤۡكُمۡ وَإِن تَسۡـَٔلُوا۟ عَنۡهَا حِینَ یُنَزَّلُ ٱلۡقُرۡءَانُ تُبۡدَ لَكُمۡ عَفَا ٱللَّهُ عَنۡهَاۗ وَٱللَّهُ غَفُورٌ حَلِیمࣱ ۝١٠١", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تسألوا عن أشياء من أمور الدين لم تؤمروا فيها بشيء، كالسؤال عن الأمور غير الواقعة، أو التي يترتب عليها تشديدات في الشرع، ولو كُلِّفتموها لشقَّتْ عليكم، وإن تسألوا عنها في حياة رسول الله صلى الله عليه وسلم وحين نزول القرآن عليه تُبيَّن لكم، وقد تُكلَّفونها فتعجزون عنها، تركها الله معافيًا لعباده منها. والله غفور لعباده إذا تابوا، حليم عليهم فلا يعاقبهم وقد أنابوا إليه.", "isBasmala": false, "translation_en": "O you who believe! Do not ask about things that would trouble you if disclosed to you. But if you were to ask about them while the Quran is being revealed, they will become obvious to you. God forgives that. God is Forgiving and Clement.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu menanyakan (kepada Nabimu) hal-hal yang jika diterangkan kepadamu akan menyusahkan kamu dan jika kamu menanyakan di waktu Al Quran itu diturunkan, niscaya akan diterangkan kepadamu, Allah memaafkan (kamu) tentang hal-hal itu. Allah Maha Pengampun lagi Maha Penyantun.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 102, "text": "قَدۡ سَأَلَهَا قَوۡمࣱ مِّن قَبۡلِكُمۡ ثُمَّ أَصۡبَحُوا۟ بِهَا كَـٰفِرِینَ ۝١٠٢", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "إن مثل تلك الأسئلة قد سألها قومٌ مِن قبلكم رسلَهم، فلما أُمِروا بها جحدوها، ولم ينفذوها، فاحذروا أن تكونوا مثلهم.", "isBasmala": false, "translation_en": "A people before you asked about them, but then came to reject them.", "translation_id": "Sesungguhnya telah ada segolongsn manusia sebelum kamu menanyakan hal-hal yang serupa itu (kepada Nabi mereka), kemudian mereka tidak percaya kepadanya.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 103, "text": "مَا جَعَلَ ٱللَّهُ مِنۢ بَحِیرَةࣲ وَلَا سَاۤىِٕبَةࣲ وَلَا وَصِیلَةࣲ وَلَا حَامࣲ وَلَـٰكِنَّ ٱلَّذِینَ كَفَرُوا۟ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَأَكۡثَرُهُمۡ لَا یَعۡقِلُونَ ۝١٠٣", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "ما شرع الله للمشركين ما ابتدعوه في بهيمة الأنعام مِن تَرْك الانتفاع ببعضها وجعلها للأصنام، وهي: البَحيرة التي تُقطع أذنها إذا ولدت عددًا من البطون، والسائبة وهي التي تُترك للأصنام، والوصيلة وهي التي تتصل ولادتها بأنثى بعد أنثى، والحامي وهو الذكر من الإبل إذا وُلد من صلبه عدد من الإبل، ولكن الكفار نسبوا ذلك إلى الله تعالى افتراء عليه، وأكثر الكافرين لا يميزون الحق من الباطل.", "isBasmala": false, "translation_en": "God did not institute the superstitions of Bahirah, Saibah, Wasilah, or of Hami; but those who disbelieve fabricate lies about God-most of them do not understand.", "translation_id": "Allah sekali-kali tidak pernah mensyari'atkan adanya bahiirah, saaibah, washiilah dan haam. Akan tetapi orang-orang kafir membuat-buat kedustaan terhadap Allah, dan kebanyakan mereka tidak mengerti.", "manzil": 2, "manzil_display": ""}], "125": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 104, "text": "وَإِذَا قِیلَ لَهُمۡ تَعَالَوۡا۟ إِلَىٰ مَاۤ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ قَالُوا۟ حَسۡبُنَا مَا وَجَدۡنَا عَلَیۡهِ ءَابَاۤءَنَاۤۚ أَوَ لَوۡ كَانَ ءَابَاۤؤُهُمۡ لَا یَعۡلَمُونَ شَیۡـࣰٔا وَلَا یَهۡتَدُونَ ۝١٠٤", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "وإذا قيل لهؤلاء الكفار المحرِّمين ما أحل الله: تعالوا إلى تنزيل الله وإلى رسوله ليتبين لكم الحلال والحرام، قالوا: يكفينا ما ورثناه عن آبائنا من قول وعمل، أيقولون ذلك ولو كان آباؤهم لا يعلمون شيئًا أي: لا يفهمون حقًّا ولا يعرفونه، ولا يهتدون إليه؟ فكيف يتبعونهم، والحالة هذه؟ فإنه لا يتبعهم إلا من هو أجهل منهم وأضل سبيلا.", "isBasmala": false, "translation_en": "And when it is said to them, \"Come to what God has revealed, and to the Messenger,\" they say, \"Sufficient for us is what we found our forefathers upon.\" Even if their forefathers knew nothing, and were not guided?", "translation_id": "Apabila dikatakan kepada mereka: \"Marilah mengikuti apa yang diturunkan Allah dan mengikuti Rasul\". Mereka menjawab: \"Cukuplah untuk kami apa yang kami dapati bapak-bapak kami mengerjakannya\". Dan apakah mereka itu akan mengikuti nenek moyang mereka walaupun nenek moyang mereka itu tidak mengetahui apa-apa dan tidak (pula) mendapat petunjuk?.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 105, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ عَلَیۡكُمۡ أَنفُسَكُمۡۖ لَا یَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَیۡتُمۡۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِیعࣰا فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ۝١٠٥", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه ألزموا أنفسكم بالعمل بطاعة الله واجتناب معصيته، وداوموا على ذلك وإن لم يستجب الناس لكم، فإذا فعلتم ذلك فلا يضركم ضلال مَن ضلَّ إذا لزمتم طريق الاستقامة، وأمرتم بالمعروف ونهيتم عن المنكر، إلى الله مرجعكم جميعًا في الآخرة، فيخبركم بأعمالكم، ويجازيكم عليها.", "isBasmala": false, "translation_en": "O you who believe! You are responsible for your own souls. He who has strayed cannot harm you if you are guided. To God is you return, all of you, and He will inform you of what you used to do.", "translation_id": "Hai orang-orang yang beriman, jagalah dirimu; tiadalah orang yang sesat itu akan memberi mudharat kepadamu apabila kamu telah mendapat petunjuk. Hanya kepada Allah kamu kembali semuanya, maka Dia akan menerangkan kepadamu apa yang telah kamu kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 106, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ شَهَـٰدَةُ بَیۡنِكُمۡ إِذَا حَضَرَ أَحَدَكُمُ ٱلۡمَوۡتُ حِینَ ٱلۡوَصِیَّةِ ٱثۡنَانِ ذَوَا عَدۡلࣲ مِّنكُمۡ أَوۡ ءَاخَرَانِ مِنۡ غَیۡرِكُمۡ إِنۡ أَنتُمۡ ضَرَبۡتُمۡ فِی ٱلۡأَرۡضِ فَأَصَـٰبَتۡكُم مُّصِیبَةُ ٱلۡمَوۡتِۚ تَحۡبِسُونَهُمَا مِنۢ بَعۡدِ ٱلصَّلَوٰةِ فَیُقۡسِمَانِ بِٱللَّهِ إِنِ ٱرۡتَبۡتُمۡ لَا نَشۡتَرِی بِهِۦ ثَمَنࣰا وَلَوۡ كَانَ ذَا قُرۡبَىٰ وَلَا نَكۡتُمُ شَهَـٰدَةَ ٱللَّهِ إِنَّاۤ إِذࣰا لَّمِنَ ٱلۡـَٔاثِمِینَ ۝١٠٦", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه إذا قرب الموت من أحدكم، فلْيُشْهِد على وصيته اثنين أمينين من المسلمين أو آخرين من غير المسلمين عند الحاجة، وعدم وجود غيرهما من المسلمين، تُشهدونهما إن أنتم سافرتم في الأرض فحلَّ بكم الموت، وإن ارتبتم في شهادتهما فقفوهما من بعد الصلاة -أي صلاة المسلمين، وبخاصة صلاة العصر-، فيقسمان بالله قسمًا خالصًا لا يأخذان به عوضًا من الدنيا، ولا يحابيان به ذا قرابة منهما، ولا يكتمان به شهادة لله عندهما، وأنهما إن فَعَلا ذلك فهما من المذنبين.", "isBasmala": false, "translation_en": "O you who believe! When death approaches one of you, let two reliable persons from among you act as witnesses to the making of a bequest, or two persons from another people if you are travelling in the land and the event of death approaches you. Engage them after the prayer. If you have doubts, let them swear by God: \"We will not sell our testimony for any price, even if he was a near relative, and we will not conceal God's testimony, for then we would be sinners.\"", "translation_id": "Hai orang-orang yang beriman, apabila salah seorang kamu menghadapi kematian, sedang dia akan berwasiat, maka hendaklah (wasiat itu) disaksikan oleh dua orang yang adil di antara kamu, atau dua orang yang berlainan agama dengan kamu, jika kamu dalam perjalanan dimuka bumi lalu kamu ditimpa bahaya kematian. Kamu tahan kedua saksi itu sesudah sembahyang (untuk bersumpah), lalu mereka keduanya bersumpah dengan nama Allah, jika kamu ragu-ragu: \"(Demi Allah) kami tidak akan membeli dengan sumpah ini harga yang sedikit (untuk kepentingan seseorang), walaupun dia karib kerabat, dan tidak (pula) kami menyembunyikan persaksian Allah; sesungguhnya kami kalau demikian tentulah termasuk orang-orang yang berdosa\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 107, "text": "فَإِنۡ عُثِرَ عَلَىٰۤ أَنَّهُمَا ٱسۡتَحَقَّاۤ إِثۡمࣰا فَـَٔاخَرَانِ یَقُومَانِ مَقَامَهُمَا مِنَ ٱلَّذِینَ ٱسۡتَحَقَّ عَلَیۡهِمُ ٱلۡأَوۡلَیَـٰنِ فَیُقۡسِمَانِ بِٱللَّهِ لَشَهَـٰدَتُنَاۤ أَحَقُّ مِن شَهَـٰدَتِهِمَا وَمَا ٱعۡتَدَیۡنَاۤ إِنَّاۤ إِذࣰا لَّمِنَ ٱلظَّـٰلِمِینَ ۝١٠٧", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "فإن اطلع أولياء الميت على أن الشاهدين المذكورين قد أثما بالخيانة في الشهادة أو الوصية فليقم مقامهما في الشهادة اثنان من أولياء الميت فيقسمان بالله: لَشهادتنا الصادقة أولى بالقبول من شهادتهما الكاذبة، وما تجاوزنا الحق في شهادتنا، إنا إن اعتدينا وشهدنا بغير الحق لمن الظالمين المتجاوزين حدود الله.", "isBasmala": false, "translation_en": "If it is discovered that they are guilty of perjury: let two others take their place, two from among those responsible for the claim, and have them swear by God, \"Our testimony is more truthful than their testimony, and we will not be biased, for then we would be wrongdoers.\"", "translation_id": "Jika diketahui bahwa kedua (saksi itu) membuat dosa, maka dua orang yang lain di antara ahli waris yang berhak yang lebih dekat kepada orang yang meninggal (memajukan tuntutan) untuk menggantikannya, lalu keduanya bersumpah dengan nama Allah: \"Sesungguhnya persaksian kami labih layak diterima daripada persaksian kedua saksi itu, dan kami tidak melanggar batas, sesungguhnya kami kalau demikian tentulah termasuk orang yang menganiaya diri sendiri\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 108, "text": "ذَ ٰلِكَ أَدۡنَىٰۤ أَن یَأۡتُوا۟ بِٱلشَّهَـٰدَةِ عَلَىٰ وَجۡهِهَاۤ أَوۡ یَخَافُوۤا۟ أَن تُرَدَّ أَیۡمَـٰنُۢ بَعۡدَ أَیۡمَـٰنِهِمۡۗ وَٱتَّقُوا۟ ٱللَّهَ وَٱسۡمَعُوا۟ۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ ۝١٠٨", "juz": 7, "hizb": "(*¼ ح 13*)", "tafsir": "ذلك الحكم عند الارتياب في الشاهدين من الحلف بعد الصلاة وعدم قبول شهادتهما، أقرب إلى أن يأتوا بالشهادة على حقيقتها خوفًا من عذاب الآخرة، أو خشية من أن ترد اليمين الكاذبة من قِبَل أصحاب الحق بعد حلفهم، فيفتضح الكاذب الذي ردت يمينه في الدنيا وقت ظهور خيانته. وخافوا الله -أيها الناس- وراقبوه أن تحلفوا كذبًا، وأن تقتطعوا بأيمانكم مالا حرامًا، واسمعوا ما توعظون به. والله لا يهدي القوم الفاسقين الخارجين عن طاعته.", "isBasmala": false, "translation_en": "That makes it more likely that they will give true testimony, fearing that their oaths might be contradicted by subsequent oaths. So fear God, and listen. God does not guide the disobedient people.", "translation_id": "Itu lebih dekat untuk (menjadikan para saksi) mengemukakan persaksiannya menurut apa yang sebenarnya, dan (lebih dekat untuk menjadikan mereka) merasa takut akan dikembalikan sumpahnya (kepada ahli waris) sesudah mereka bersumpah. Dan bertakwalah kepada Allah dan dengarkanlah (perintah-Nya). Allah tidak memberi petunjuk kepada orang-orang yang fasik.", "manzil": 2, "manzil_display": ""}], "126": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 109, "text": "۞ یَوۡمَ یَجۡمَعُ ٱللَّهُ ٱلرُّسُلَ فَیَقُولُ مَاذَاۤ أُجِبۡتُمۡۖ قَالُوا۟ لَا عِلۡمَ لَنَاۤۖ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُیُوبِ ۝١٠٩", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "واذكروا -أيها الناس- يوم القيامة يوم يجمع الله الرسل عليهم السلام، فيسألهم عن جواب أممهم لهم حينما دعوهم إلى التوحيد فيجيبون: لا علم لنا، فنحن لا نعلم ما في صدور الناس، ولا ما أحدثوا بعدنا. إنك أنت عليم بكل شيء مما ظهر وخفي.", "isBasmala": false, "translation_en": "On the Day when God will gather the messengers, then say, \"What response were you given?\" They will say, \"We have no knowledge; it is you who are the Knower of the unseen.\"", "translation_id": "(Ingatlah), hari di waktu Allah mengumpulkan para rasul lalu Allah bertanya (kepada mereka): \"Apa jawaban kaummu terhadap (seruan)mu?\". Para rasul menjawab: \"Tidak ada pengetahuan kami (tentang itu); sesungguhnya Engkau-lah yang mengetahui perkara yang ghaib\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 110, "text": "إِذۡ قَالَ ٱللَّهُ یَـٰعِیسَى ٱبۡنَ مَرۡیَمَ ٱذۡكُرۡ نِعۡمَتِی عَلَیۡكَ وَعَلَىٰ وَ ٰلِدَتِكَ إِذۡ أَیَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِی ٱلۡمَهۡدِ وَكَهۡلࣰاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِیلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّینِ كَهَیۡـَٔةِ ٱلطَّیۡرِ بِإِذۡنِی فَتَنفُخُ فِیهَا فَتَكُونُ طَیۡرَۢا بِإِذۡنِیۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِیۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِیۖ وَإِذۡ كَفَفۡتُ بَنِیۤ إِسۡرَ ٰۤءِیلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَیِّنَـٰتِ فَقَالَ ٱلَّذِینَ كَفَرُوا۟ مِنۡهُمۡ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینࣱ ۝١١٠", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "إذ قال الله يوم القيامة: يا عيسى ابن مريم اذكر نعمتي عليك إذ خلقتك من غير أب، وعلى والدتك حيث اصطفيتها على نساء العالمين، وبرأتها مما نُسِب إليها، ومن هذه النعم على عيسى أنه قوَّاه وأعانه بجبريل عليه السلام، يكلم الناس وهو رضيع، ويدعوهم إلى الله وهو كبير بما أوحاه الله إليه من التوحيد، ومنها أن الله تعالى علَّمه الكتابة والخط بدون معلم، ووهبه قوة الفهم والإدراك، وعَلَّمه التوراة التي أنزلها على موسى عليه السلام، والإنجيل الذي أنزل عليه هداية للناس، ومن هذه النعم أنه يصوِّر من الطين كهيئة الطير فينفخ في تلك الهيئة، فتكون طيرًا بإذن الله، ومنها أنه يشفي الذي وُلِد أعمى فيبصر، ويشفي الأبرص، فيعود جلده سليمًا بإذن الله، ومنها أنه يدعو الله أن يحييَ الموتى فيقومون من قبورهم أحياء، وذلك كله بإرادة الله تعالى وإذنه، وهي معجزات باهرة تؤيد نبوة عيسى عليه السلام، ثم يذكِّره الله جل وعلا نعمته عليه إذ منع بني إسرائيل حين همُّوا بقتله، وقد جاءهم بالمعجزات الواضحة الدالة على نبوته، فقال الذين كفروا منهم: إنَّ ما جاء به عيسى من البينات سحر ظاهر.", "isBasmala": false, "translation_en": "When God will say, \"O Jesus son of Mary, recall My favor upon you and upon your mother, how I supported you with the Holy Spirit. You spoke to the people from the crib, and in maturity. How I taught you the Scripture and wisdom, and the Torah and the Gospel. And recall that you molded from clay the shape of a bird, by My leave, and then you breathed into it, and it became a bird, by My leave. And you healed the blind and the leprous, by My leave; and you revived the dead, by My leave. And recall that I restrained the Children of Israel from you when you brought them the clear miracles. But those who disbelieved among them said, `This is nothing but obvious sorcery.'\"", "translation_id": "(Ingatlah), ketika Allah mengatakan: \"Hai Isa putra Maryam, ingatlah nikmat-Ku kepadamu dan kepada ibumu di waktu Aku menguatkan kamu dengan ruhul qudus. Kamu dapat berbicara dengan manusia di waktu masih dalam buaian dan sesudah dewasa; dan (ingatlah) di waktu Aku mengajar kamu menulis, hikmah, Taurat dan Injil, dan (ingatlah pula) diwaktu kamu membentuk dari tanah (suatu bentuk) yang berupa burung dengan ijin-Ku, kemudian kamu meniup kepadanya, lalu bentuk itu menjadi burung (yang sebenarnya) dengan seizin-Ku. Dan (ingatlah) di waktu kamu menyembuhkan orang yang buta sejak dalam kandungan ibu dan orang yang berpenyakit sopak dengan seizin-Ku, dan (ingatlah) di waktu kamu mengeluarkan orang mati dari kubur (menjadi hidup) dengan seizin-Ku, dan (ingatlah) di waktu Aku menghalangi Bani Israil (dari keinginan mereka membunuh kamu) di kala kamu mengemukakan kepada mereka keterangan-keterangan yang nyata, lalu orang-orang kafir diantara mereka berkata: \"Ini tidak lain melainkan sihir yang nyata\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 111, "text": "وَإِذۡ أَوۡحَیۡتُ إِلَى ٱلۡحَوَارِیِّـۧنَ أَنۡ ءَامِنُوا۟ بِی وَبِرَسُولِی قَالُوۤا۟ ءَامَنَّا وَٱشۡهَدۡ بِأَنَّنَا مُسۡلِمُونَ ۝١١١", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "واذكر نعمتي عليك، إذ ألهمتُ، وألقيتُ في قلوب جماعة من خلصائك أن يصدقوا بوحدانية الله تعالى ونبوتك، فقالوا: صدَّقنا يا ربنا، واشهد بأننا خاضعون لك منقادون لأمرك.", "isBasmala": false, "translation_en": "\"And when I inspired the disciples: `Believe in Me and in My Messenger.' They said, `We have believed, so bear witness that We have submitted.'\"", "translation_id": "Dan (ingatlah), ketika Aku ilhamkan kepada pengikut Isa yang setia: \"Berimanlah kamu kepada-Ku dan kepada rasul-Ku\". Mereka menjawab: Kami telah beriman dan saksikanlah (wahai rasul) bahwa sesungguhnya kami adalah orang-orang yang patuh (kepada seruanmu)\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 112, "text": "إِذۡ قَالَ ٱلۡحَوَارِیُّونَ یَـٰعِیسَى ٱبۡنَ مَرۡیَمَ هَلۡ یَسۡتَطِیعُ رَبُّكَ أَن یُنَزِّلَ عَلَیۡنَا مَاۤىِٕدَةࣰ مِّنَ ٱلسَّمَاۤءِۖ قَالَ ٱتَّقُوا۟ ٱللَّهَ إِن كُنتُم مُّؤۡمِنِینَ ۝١١٢", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "واذكر إذ قال الحواريون: يا عيسى ابن مريم هل يستطيع ربك إن سألته أن ينزل علينا مائدة طعام من السماء؟ فكان جوابه أن أمرهم بأن يتقوا عذاب الله تعالى، إن كانوا مؤمنين حقَّ الإيمان.", "isBasmala": false, "translation_en": "\"And when the disciples said, 'O Jesus son of Mary, is your Lord able to bring down for us a feast from heaven?' He said, 'Fear God, if you are believers.'\"", "translation_id": "(Ingatlah), ketika pengikut-pengikut Isa berkata: \"Hai Isa putera Maryam, sanggupkah Tuhanmu menurunkan hidangan dari langit kepada kami?\". Isa menjawab: \"Bertakwalah kepada Allah jika kamu betul-betul orang yang beriman\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 113, "text": "قَالُوا۟ نُرِیدُ أَن نَّأۡكُلَ مِنۡهَا وَتَطۡمَىِٕنَّ قُلُوبُنَا وَنَعۡلَمَ أَن قَدۡ صَدَقۡتَنَا وَنَكُونَ عَلَیۡهَا مِنَ ٱلشَّـٰهِدِینَ ۝١١٣", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "قال الحواريون: نريد أن نأكل من المائدة وتسكن قلوبنا لرؤيتها، ونعلم يقينا صدقك في نبوتك، وأن نكون من الشاهدين على هذه الآية أن الله أنزلها حجة له علينا في توحيده وقدرته على ما يشاء، وحجة لك على صدقك في نبوتك.", "isBasmala": false, "translation_en": "They said, \"We wish to eat from it, so that our hearts may be reassured, and know that you have told us the truth, and be among those who witness it.\"", "translation_id": "Mereka berkata: \"Kami ingin memakan hidangan itu dan supaya tenteram hati kami dan supaya kami yakin bahwa kamu telah berkata benar kepada kami, dan kami menjadi orang-orang yang menyaksikan hidangan itu\".", "manzil": 2, "manzil_display": ""}], "127": [{"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 114, "text": "قَالَ عِیسَى ٱبۡنُ مَرۡیَمَ ٱللَّهُمَّ رَبَّنَاۤ أَنزِلۡ عَلَیۡنَا مَاۤىِٕدَةࣰ مِّنَ ٱلسَّمَاۤءِ تَكُونُ لَنَا عِیدࣰا لِّأَوَّلِنَا وَءَاخِرِنَا وَءَایَةࣰ مِّنكَۖ وَٱرۡزُقۡنَا وَأَنتَ خَیۡرُ ٱلرَّ ٰزِقِینَ ۝١١٤", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "أجاب عيسى ابن مريم طلب الحواريين فدعا ربه جل وعلا قائلا ربنا أنزل علينا مائدة طعام من السماء، نتخذ يوم نزولها عيدًا لنا، نعظمه نحن ومَن بعدنا، وتكون المائدة علامة وحجة منك يا ألله على وحدانيتك وعلى صدق نبوتي، وامنحنا من عطائك الجزيل، وأنت خير الرازقين.", "isBasmala": false, "translation_en": "Jesus son of Mary said, \"O God, our Lord, send down for us a table from heaven, to be a festival for us, for the first of us, and the last of us, and a sign from You; and provide for us; You are the Best of providers.\"", "translation_id": "Isa putera Maryam berdoa: \"Ya Tuhan kami turunkanlah kiranya kepada kami suatu hidangan dari langit (yang hari turunnya) akan menjadi hari raya bagi kami yaitu orang-orang yang bersama kami dan yang datang sesudah kami, dan menjadi tanda bagi kekuasaan Engkau; beri rzekilah kami, dan Engkaulah pemberi rezeki Yang Paling Utama\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 115, "text": "قَالَ ٱللَّهُ إِنِّی مُنَزِّلُهَا عَلَیۡكُمۡۖ فَمَن یَكۡفُرۡ بَعۡدُ مِنكُمۡ فَإِنِّیۤ أُعَذِّبُهُۥ عَذَابࣰا لَّاۤ أُعَذِّبُهُۥۤ أَحَدࣰا مِّنَ ٱلۡعَـٰلَمِینَ ۝١١٥", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "قال الله تعالى: إني منزل مائدة الطعام عليكم، فمن يجحد منكم وحدانيتي ونبوة عيسى عليه السلام بعد نزول المائدة فإني أعذبه عذابًا شديدًا، لا أعذبه أحدًا من العالمين. وقد نزلت المائدة كما وعد الله.", "isBasmala": false, "translation_en": "God said, \"I will send it down to you. But whoever among you disbelieves thereafter, I will punish him with a punishment the like of which I never punish any other being.\"", "translation_id": "Allah berfirman: \"Sesungguhnya Aku akan menurunkan hidangan itu kepadamu, barangsiapa yang kafir di antaramu sesudah (turun hidangan itu), maka sesungguhnya Aku akan menyiksanya dengan siksaan yang tidak pernah Aku timpakan kepada seorangpun di antara umat manusia\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 116, "text": "وَإِذۡ قَالَ ٱللَّهُ یَـٰعِیسَى ٱبۡنَ مَرۡیَمَ ءَأَنتَ قُلۡتَ لِلنَّاسِ ٱتَّخِذُونِی وَأُمِّیَ إِلَـٰهَیۡنِ مِن دُونِ ٱللَّهِۖ قَالَ سُبۡحَـٰنَكَ مَا یَكُونُ لِیۤ أَنۡ أَقُولَ مَا لَیۡسَ لِی بِحَقٍّۚ إِن كُنتُ قُلۡتُهُۥ فَقَدۡ عَلِمۡتَهُۥۚ تَعۡلَمُ مَا فِی نَفۡسِی وَلَاۤ أَعۡلَمُ مَا فِی نَفۡسِكَۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلۡغُیُوبِ ۝١١٦", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "واذكر إذ قال الله تعالى يوم القيامة: يا عيسى ابن مريم أأنت قلت للناس اجعلوني وأمي معبودين من دون الله؟ فأجاب عيسى -منزِّهًا الله تعالى-: ما ينبغي لي أن أقول للناس غير الحق. إن كنتُ قلتُ هذا فقد علمتَه؛ لأنه لا يخفى عليك شيء، تعلم ما تضمره نفسي، ولا أعلم أنا ما في نفسك. إنك أنت عالمٌ بكل شيء مما ظهر أو خفي.", "isBasmala": false, "translation_en": "And God will say, \"O Jesus son of Mary, did you say to the people, `Take me and my mother as gods rather than God?'\" He will say, \"Glory be to You! It is not for me to say what I have no right to. Had I said it, You would have known it. You know what is in my soul, and I do not know what is in your soul. You are the Knower of the hidden.", "translation_id": "Dan (ingatlah) ketika Allah berfirman: \"Hai Isa putera Maryam, adakah kamu mengatakan kepada manusia: \"Jadikanlah aku dan ibuku dua orang tuhan selain Allah?\". Isa menjawab: \"Maha Suci Engkau, tidaklah patut bagiku mengatakan apa yang bukan hakku (mengatakannya). Jika aku pernah mengatakan maka tentulah Engkau mengetahui apa yang ada pada diriku dan aku tidak mengetahui apa yang ada pada diri Engkau. Sesungguhnya Engkau Maha Mengetahui perkara yang ghaib-ghaib\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 117, "text": "مَا قُلۡتُ لَهُمۡ إِلَّا مَاۤ أَمَرۡتَنِی بِهِۦۤ أَنِ ٱعۡبُدُوا۟ ٱللَّهَ رَبِّی وَرَبَّكُمۡۚ وَكُنتُ عَلَیۡهِمۡ شَهِیدࣰا مَّا دُمۡتُ فِیهِمۡۖ فَلَمَّا تَوَفَّیۡتَنِی كُنتَ أَنتَ ٱلرَّقِیبَ عَلَیۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ ۝١١٧", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "قال عيسى عليه السلام: يا ربِّ ما قلتُ لهم إلا ما أوحيته إليَّ، وأمرتني بتبليغه من إفرادك بالتوحيد والعبادة، وكنتُ على ما يفعلونه -وأنا بين أظهرهم- شاهدًا عليهم وعلى أفعالهم وأقوالهم، فلما وفيتني أجلي على الأرض، ورفعتني إلى السماء حيًّا، كنت أنت المطَّلِع على سرائرهم، وأنت على كل شيء شهيد، لا تخفى عليك خافية في الأرض ولا في السماء.", "isBasmala": false, "translation_en": "I only told them what You commanded me: that you shall worship God, my Lord and your Lord. And I was a witness over them while I was among them; but when You took me to Yourself, you became the Watcher over them-You are Witness over everything.", "translation_id": "Aku tidak pernah mengatakan kepada mereka kecuali apa yang Engkau perintahkan kepadaku (mengatakan)nya yaitu: \"Sembahlah Allah, Tuhanku dan Tuhanmu\", dan adalah aku menjadi saksi terhadap mereka, selama aku berada di antara mereka. Maka setelah Engkau wafatkan aku, Engkau-lah yang mengawasi mereka. Dan Engkau adalah Maha Menyaksikan atas segala sesuatu.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 118, "text": "إِن تُعَذِّبۡهُمۡ فَإِنَّهُمۡ عِبَادُكَۖ وَإِن تَغۡفِرۡ لَهُمۡ فَإِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝١١٨", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "إنك يا ألله إن تعذبهم فإنهم عبادك -وأنت أعلم بأحوالهم-، تفعل بهم ما تشاء بعدلك، وإن تغفر برحمتك لمن أتى منهم بأسباب المغفرة، فإنك أنت العزيز الذي لا يغالَبُ، الحكيم في تدبيره وأمره. وهذه الآية ثناء على الله -تعالى- بحكمته وعدله، وكمال علمه.", "isBasmala": false, "translation_en": "If You punish them, they are Your servants; but if You forgive them, You are the Mighty and Wise.\"", "translation_id": "Jika Engkau menyiksa mereka, maka sesungguhnya mereka adalah hamba-hamba Engkau, dan jika Engkau mengampuni mereka, maka sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 119, "text": "قَالَ ٱللَّهُ هَـٰذَا یَوۡمُ یَنفَعُ ٱلصَّـٰدِقِینَ صِدۡقُهُمۡۚ لَهُمۡ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ رَّضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُۚ ذَ ٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝١١٩", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "قال الله تعالى لعيسى عليه السلام يوم القيامة: هذا يوم الجزاء الذي ينفع الموحدين توحيدهم ربهم، وانقيادهم لشرعه، وصدقهم في نياتهم وأقوالهم وأعمالهم، لهم جنات تجري من تحت قصورها الأنهار، ماكثين فيها أبدًا، رضي الله عنهم فقبل حسناتهم، ورضوا عنه بما أعطاهم من جزيل ثوابه. ذلك الجزاء والرضا منه عليهم هو الفوز العظيم.", "isBasmala": false, "translation_en": "God will say, \"This is a Day when the truthful will benefit from their truthfulness.\" They will have Gardens beneath which rivers flow, wherein they will remain forever. God is pleased with them, and they are pleased with Him. That is the great attainment.", "translation_id": "Allah berfirman: \"Ini adalah suatu hari yang bermanfaat bagi orang-orang yang benar kebenaran mereka. Bagi mereka surga yang dibawahnya mengalir sungai-sungai; mereka kekal di dalamnya selama-lamanya; Allah ridha terhadap-Nya. Itulah keberuntungan yang paling besar\".", "manzil": 2, "manzil_display": ""}, {"sura": 5, "sura_name": "المائدة", "revelation": "Madaniyah", "aya": 120, "text": "لِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا فِیهِنَّۚ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرُۢ ۝١٢٠", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "لله وحده لا شريك له ملك السموات والأرض وما فيهن، وهو -سبحانه- على كل شيء قدير لا يعجزه شيء.", "isBasmala": false, "translation_en": "To God belongs the sovereignty of the heavens and the earth and what lies in them, and He has power over everything.", "translation_id": "Kepunyaan Allah-lah kerajaan langit dan bumi dan apa yang ada di dalamnya; dan Dia Maha Kuasa atas segala sesuatu.", "manzil": 2, "manzil_display": ""}], "128": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 8, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 1, "text": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَجَعَلَ ٱلظُّلُمَـٰتِ وَٱلنُّورَۖ ثُمَّ ٱلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡ یَعۡدِلُونَ ۝١", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "الثناء على الله بصفاته التي كلّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، الذي أنشأ السموات والأرض وما فيهن، وخلق الظلمات والنور، وذلك بتعاقب الليل والنهار. وفي هذا دلالة على عظمة الله تعالى، واستحقاقه وحده العبادة، فلا يجوز لأحد أن يشرك به غيره. ومع هذا الوضوح فإن الكافرين يسوون بالله غيره، ويشركون به.", "isBasmala": false, "translation_en": "Praise be to God, Who created the heavens and the earth, and made the darkness and the light. Yet those who disbelieve ascribe equals to their Lord.", "translation_id": "Segala puji bagi Allah Yang telah menciptakan langit dan bumi dan mengadakan gelap dan terang, namun orang-orang yang kafir mempersekutukan (sesuatu) dengan Tuhan mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 2, "text": "هُوَ ٱلَّذِی خَلَقَكُم مِّن طِینࣲ ثُمَّ قَضَىٰۤ أَجَلࣰاۖ وَأَجَلࣱ مُّسَمًّى عِندَهُۥۖ ثُمَّ أَنتُمۡ تَمۡتَرُونَ ۝٢", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "هو الذي خلق أباكم آدم من طين وأنتم سلالة منه، ثم كتب مدة بقائكم في هذه الحياة الدنيا، وكتب أجلا آخر محدَّدًا لا يعلمه إلا هو جل وعلا وهو يوم القيامة، ثم أنتم بعد هذا تشكُّون في قدرة الله تعالى على البعث بعد الموت.", "isBasmala": false, "translation_en": "It is He who created you from clay, then decided a term-a term determined by him. Yet you doubt.", "translation_id": "Dialah Yang menciptakan kamu dari tanah, sesudah itu ditentukannya ajal (kematianmu), dan ada lagi suatu ajal yang ada pada sisi-Nya (yang Dia sendirilah mengetahuinya), kemudian kamu masih ragu-ragu (tentang berbangkit itu).", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 3, "text": "وَهُوَ ٱللَّهُ فِی ٱلسَّمَـٰوَ ٰتِ وَفِی ٱلۡأَرۡضِ یَعۡلَمُ سِرَّكُمۡ وَجَهۡرَكُمۡ وَیَعۡلَمُ مَا تَكۡسِبُونَ ۝٣", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "والله سبحانه هو الإله المعبود في السموات والأرض. ومن دلائل ألوهيته أنه يعلم جميع ما تخفونه -أيها الناس- وما تعلنونه، ويعلم جميع أعمالكم من خير أو شر؛ ولهذا فإنه -جلَّ وعلا- وحده هو الإله المستحق للعبادة.", "isBasmala": false, "translation_en": "He is God in the heavens and the earth. He knows what you keep secret and what you make public; and He knows what you earn.", "translation_id": "Dan Dialah Allah (yang disembah), baik di langit maupun di bumi; Dia mengetahui apa yang kamu rahasiakan dan apa yang kamu lahirkan dan mengetahui (pula) apa yang kamu usahakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 4, "text": "وَمَا تَأۡتِیهِم مِّنۡ ءَایَةࣲ مِّنۡ ءَایَـٰتِ رَبِّهِمۡ إِلَّا كَانُوا۟ عَنۡهَا مُعۡرِضِینَ ۝٤", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "هؤلاء الكفار الذين يشركون مع الله تعالى غيره قد جاءتهم الحجج الواضحة والدلالات البينة على وحدانية الله -جل وعلا- وصِدْقِ محمد صلى الله عليه وسلم في نبوته، وما جاء به، ولكن ما إن جاءتهم حتى أعرضوا عن قبولها، ولم يؤمنوا بها.", "isBasmala": false, "translation_en": "Not one of their Lord's signs comes to them, but they turn away from it.", "translation_id": "Dan tidak ada suatu ayatpun dari ayat-ayat Tuhan sampai kepada mereka, melainkan mereka selalu berpaling dari padanya (mendustakannya).", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 5, "text": "فَقَدۡ كَذَّبُوا۟ بِٱلۡحَقِّ لَمَّا جَاۤءَهُمۡ فَسَوۡفَ یَأۡتِیهِمۡ أَنۢبَـٰۤؤُا۟ مَا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٥", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "لقد جحد هؤلاء الكفار الحقَّ الذي جاءهم به محمد صلى الله عليه وسلم وسخروا من دعائه؛ جهلا منهم بالله واغترارًا بإمهاله إياهم، فسوف يرون ما استهزءوا به أنه الحق والصدق، ويبين الله للمكذبين كذبهم وافتراءهم، ويجازيهم عليه.", "isBasmala": false, "translation_en": "They denied the truth when it has come to them; but soon will reach them the news of what they used to ridicule.", "translation_id": "Sesungguhnya mereka telah mendustakan yang haq (Al-Quran) tatkala sampai kepada mereka, maka kelak akan sampai kepada mereka (kenyataan dari) berita-berita yang selalu mereka perolok-olokkan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 6, "text": "أَلَمۡ یَرَوۡا۟ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنࣲ مَّكَّنَّـٰهُمۡ فِی ٱلۡأَرۡضِ مَا لَمۡ نُمَكِّن لَّكُمۡ وَأَرۡسَلۡنَا ٱلسَّمَاۤءَ عَلَیۡهِم مِّدۡرَارࣰا وَجَعَلۡنَا ٱلۡأَنۡهَـٰرَ تَجۡرِی مِن تَحۡتِهِمۡ فَأَهۡلَكۡنَـٰهُم بِذُنُوبِهِمۡ وَأَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِینَ ۝٦", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "ألم يعلم هؤلاء الذين يجحدون وحدانية الله تعالى واستحقاقه وحده العبادة، ويكذبون رسوله محمدًا صلى الله عليه وسلم ما حلَّ بالأمم المكذبة قبلهم من هلاك وتدمير، وقد مكنَّاهم في الأرض ما لم نمكن لكم أيها الكافرون، وأنعمنا عليهم بإنزال الأمطار وجريان الأنهار من تحت مساكنهم؛ استدراجًا وإملاءً لهم، فكفروا بنعم الله وكذبوا الرسل، فأهلكناهم بسبب ذنونهم، وأنشأنا من بعدهم أممًا أخرى خلفوهم في عمارة الأرض؟", "isBasmala": false, "translation_en": "Have they not considered how many generations We destroyed before them? We had established them on earth more firmly than We established you, and We sent the clouds pouring down abundant rain on them, and We made rivers flow beneath them. But We destroyed them for their sins, and established other civilizations after them.", "translation_id": "Apakah mereka tidak memperhatikan berapa banyak generasi yang telah Kami binasakan sebelum mereka, padahal (generasi itu) telah Kami teguhkan kedudukan mereka di muka bumi, yaitu keteguhan yang belum pernah Kami berikan kepadamu, dan Kami curahkan hujan yang lebat atas mereka dan Kami jadikan sungai-sungai mengalir di bawah mereka, kemudian Kami binasakan mereka karena dosa mereka sendiri, dan Kami ciptakan sesudah mereka generasi yang lain.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 7, "text": "وَلَوۡ نَزَّلۡنَا عَلَیۡكَ كِتَـٰبࣰا فِی قِرۡطَاسࣲ فَلَمَسُوهُ بِأَیۡدِیهِمۡ لَقَالَ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینࣱ ۝٧", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "ولو نزَّلنا عليك -أيها الرسول- كتابًا من السماء في أوراق فلمسه هؤلاء المشركون بأيديهم لقالوا: إنَّ ما جئت به -أيها الرسول- سحر واضح بيِّن.", "isBasmala": false, "translation_en": "Had We sent down upon you a book on paper, and they had touched it with their hands, those who disbelieve would have said, \"This is nothing but plain magic.\"", "translation_id": "Dan kalau Kami turunkan kepadamu tulisan di atas kertas, lalu mereka dapat menyentuhnya dengan tangan mereka sendiri, tentulah orang-orang kafir itu berkata: \"Ini tidak lain hanyalah sihir yang nyata\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 8, "text": "وَقَالُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ مَلَكࣱۖ وَلَوۡ أَنزَلۡنَا مَلَكࣰا لَّقُضِیَ ٱلۡأَمۡرُ ثُمَّ لَا یُنظَرُونَ ۝٨", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "وقال هؤلاء المشركون: هلا أنزل الله تعالى على محمد مَلَكًا من السماء؛ ليصدقه فيما جاء به من النبوة، ولوأنزلنا مَلَكًّا من السماء إجابة لطلبهم لقضي الأمر بإهلاكهم، ثم لا يمهلون لتوبة، فقد سبق في علم الله أنهم لا يؤمنون.", "isBasmala": false, "translation_en": "And they say, \"Why was an angel not sent down to him.\" Had We sent down an angel, the matter would have been settled, and they would not have been reprieved.", "translation_id": "Dan mereka berkata: \"Mengapa tidak diturunkan kepadanya (Muhammad) malaikat?\" dan kalau Kami turunkan (kepadanya) malaikat, tentulah selesai urusan itu, kemudian mereka tidak diberi tangguh (sedikitpun).", "manzil": 2, "manzil_display": ""}], "129": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 9, "text": "وَلَوۡ جَعَلۡنَـٰهُ مَلَكࣰا لَّجَعَلۡنَـٰهُ رَجُلࣰا وَلَلَبَسۡنَا عَلَیۡهِم مَّا یَلۡبِسُونَ ۝٩", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "ولو جعلنا الرسول المرسل إليهم مَلَكًا إذ لم يقتنعوا بمحمد صلى الله عليه وسلم، لجعلنا ذلك الملك في صورة البشر، حتى يستطيعوا السماع منه ومخاطبته؛ إذ ليس بإمكانهم رؤية الملك على صورته الملائكية، ولو جاءهم الملك بصورة رجل لاشتبه الأمر عليهم، كما اشتبه عليهم أمر محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Had We made him an angel, We would have made him a man, and confused them when they are already confused.", "translation_id": "Dan kalau Kami jadikan rasul itu malaikat, tentulah Kami jadikan dia seorang laki-laki dan (kalau Kami jadikan ia seorang laki-laki), tentulah Kami meragu-ragukan atas mereka apa yang mereka ragu-ragukan atas diri mereka sendiri.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 10, "text": "وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلࣲ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِینَ سَخِرُوا۟ مِنۡهُم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝١٠", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "ولمَّا كان طلبهم إنزال الملك على سبيل الاستهزاء بمحمد صلى الله عليه وسلم بيَّن الله تعالى له أن الاستهزاء بالرسل عليهم السلام ليس أمرا حادثا، بل قد وقع من الكفار السابقين مع أنبيائهم، فأحاط بهم العذاب الذي كانوا يهزؤون به وينكرون وقوعه.", "isBasmala": false, "translation_en": "Messengers before you were ridiculed, but those who mocked them became besieged by what they ridiculed.", "translation_id": "Dan sungguh telah diperolok-olokkan beberapa rasul sebelum kamu, maka turunlah kepada orang-orang yang mencemoohkan di antara mereka balasan (azab) olok-olokan mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 11, "text": "قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ ثُمَّ ٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُكَذِّبِینَ ۝١١", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "قل لهم -أيها الرسول-: سيروا في الأرض ثم انظروا كيف أعقب الله المكذبين الهلاك والخزي؟ فاحذروا مثل مصارعهم، وخافوا أن يحلَّ بكم مثل الذي حل بهم.", "isBasmala": false, "translation_en": "Say, \"Travel the earth and observe the final fate of the deniers.\"", "translation_id": "Katakanlah: \"Berjalanlah di muka bumi, kemudian perhatikanlah bagaimana kesudahan orang-orang yang mendustakan itu\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 12, "text": "قُل لِّمَن مَّا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ قُل لِّلَّهِۚ كَتَبَ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَۚ لَیَجۡمَعَنَّكُمۡ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ لَا رَیۡبَ فِیهِۚ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ فَهُمۡ لَا یُؤۡمِنُونَ ۝١٢", "juz": 7, "hizb": "(*½ ح 13*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: لمن مُلكُ السموات والأرض وما فيهن؟ قل: هو لله كما تقرون بذلك وتعلمونه، فاعبدوه وحده. كتب الله على نفسه الرحمة فلا يعجل على عباده بالعقوبة. ليجمعنكم إلى يوم القيامة الذي لا شك فيه للحساب والجزاء. الذين أشركوا بالله أهلكوا أنفسهم، فهم لا يوحدون الله، ولا يصدقون بوعده ووعيده، ولا يقرون بنبوة محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Say, \"To whom belongs what is in the heavens and the earth?\" Say, \"To God.\" He has inscribed for Himself mercy. He will gather you to the Day of Resurrection, in which there is no doubt. Those who lost their souls do not believe.", "translation_id": "Katakanlah: \"Kepunyaan siapakah apa yang ada di langit dan di bumi\". Katakanlah: \"Kepunyaan Allah\". Dia telah menetapkan atas Diri-Nya kasih sayang. Dia sungguh akan menghimpun kamu pada hari kiamat yang tidak ada keraguan padanya. Orang-orang yang meragukan dirinya mereka itu tidak beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 13, "text": "۞ وَلَهُۥ مَا سَكَنَ فِی ٱلَّیۡلِ وَٱلنَّهَارِۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝١٣", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "ولله ملك كل شيء في السموات والأرض، سكن أو تحرك، خفي أو ظهر، الجميع عبيده وخلقه، وتحت قهره وتصرفه وتدبيره، وهو السميع لأقوال عباده، الحليم بحركاتهم وسرائرهم.", "isBasmala": false, "translation_en": "To Him belongs whatever rests in the night and the day. He is the Hearing, the Knowing.", "translation_id": "Dan kepunyaan Allah-lah segala yang ada pada malam dan siang. Dan Dialah Yang Maha Mendengar lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 14, "text": "قُلۡ أَغَیۡرَ ٱللَّهِ أَتَّخِذُ وَلِیࣰّا فَاطِرِ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَهُوَ یُطۡعِمُ وَلَا یُطۡعَمُۗ قُلۡ إِنِّیۤ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِینَ ۝١٤", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين مع الله تعالى غيره: أغير الله تعالى أتخذ وليًّا ونصيرًا، وهو خالق السموات والأرض وما فيهن، وهو الذي يرزق خلقه ولا يرزقه أحد؟ قل -أيها الرسول-: إني أُمِرْتُ أن أكون أول مَن خضع وانقاد له بالعبودية من هذه الأمة، ونهيت أن أكون من المشركين معه غيره.", "isBasmala": false, "translation_en": "Say, \"Shall I take for myself a protector other than God, Originator of the heavens and the earth, and He feeds and is not fed?\" Say, \"I am instructed to be the first of those who submit.\" And do not be among the idolaters.", "translation_id": "Katakanlah: \"Apakah akan aku jadikan pelindung selain dari Allah yang menjadikan langit dan bumi, padahal Dia memberi makan dan tidak memberi makan?\" Katakanlah: \"Sesungguhnya aku diperintah supaya aku menjadi orang yang pertama kali menyerah diri (kepada Allah), dan jangan sekali-kali kamu masuk golongan orang musyrik\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 15, "text": "قُلۡ إِنِّیۤ أَخَافُ إِنۡ عَصَیۡتُ رَبِّی عَذَابَ یَوۡمٍ عَظِیمࣲ ۝١٥", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين مع الله غيره: إني أخاف إن عصيت ربي، فخالفت أمره، وأشركت معه غيره في عبادته، أن ينزل بي عذاب عظيم يوم القيامة.", "isBasmala": false, "translation_en": "Say, \"I fear, should I defy my Lord, the punishment of a tremendous Day.\"", "translation_id": "Katakanlah: \"Sesungguhnya aku takut akan azab hari yang besar (hari kiamat), jika aku mendurhakai Tuhanku\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 16, "text": "مَّن یُصۡرَفۡ عَنۡهُ یَوۡمَىِٕذࣲ فَقَدۡ رَحِمَهُۥۚ وَذَ ٰلِكَ ٱلۡفَوۡزُ ٱلۡمُبِینُ ۝١٦", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "من يصرف الله عنه ذلك العذاب الشديد فقد رحمه، وذلك الصرف هو الظفر البين بالنجاة من العذاب العظيم.", "isBasmala": false, "translation_en": "Whoever is spared on that Day-He had mercy on him. That is the clear victory.", "translation_id": "Barang siapa yang dijauhkan azab dari padanya pada hari itu, maka sungguh Allah telah memberikan rahmat kepadanya. Dan itulah keberuntungan yang nyata.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 17, "text": "وَإِن یَمۡسَسۡكَ ٱللَّهُ بِضُرࣲّ فَلَا كَاشِفَ لَهُۥۤ إِلَّا هُوَۖ وَإِن یَمۡسَسۡكَ بِخَیۡرࣲ فَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝١٧", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "وإن يصبك الله تعالى -أيها الإنسان- بشيء يضرك كالفقر والمرض فلا كاشف له إلا هو، وإن يصبك بخير كالغنى والصحة فلا راد لفضله ولا مانع لقضائه، فهو -جل وعلا- القادر على كل شيء.", "isBasmala": false, "translation_en": "If God touches you with adversity, none can remove it except He. And if He touches you with good-He is Capable of everything.", "translation_id": "Dan jika Allah menimpakan sesuatu kemudharatan kepadamu, maka tidak ada yang menghilangkannya melainkan Dia sendiri. Dan jika Dia mendatangkan kebaikan kepadamu, maka Dia Maha Kuasa atas tiap-tiap sesuatu.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 18, "text": "وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۚ وَهُوَ ٱلۡحَكِیمُ ٱلۡخَبِیرُ ۝١٨", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "والله سبحانه هو الغالب القاهر فوق عباده؛ خضعت له الرقاب وذَلَّتْ له الجبابرة، وهو الحكيم الذي يضع الأشياء مواضعها وَفْق حكمت، الخبير الذي لا يخفى عليه شيء. ومن اتصف بهذه الصفات يجب ألا يشرك به. وفي هذه الآية إثبات الفوقية لله -تعالى- على جميع خلقه، فوقية مطلقة تليق بجلاله سبحانه.", "isBasmala": false, "translation_en": "He is the Supreme over His servants. He is the Wise, the Expert.", "translation_id": "Dan Dialah yang berkuasa atas sekalian hamba-hamba-Nya. Dan Dialah Yang Maha Bijaksana lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}], "130": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 19, "text": "قُلۡ أَیُّ شَیۡءٍ أَكۡبَرُ شَهَـٰدَةࣰۖ قُلِ ٱللَّهُۖ شَهِیدُۢ بَیۡنِی وَبَیۡنَكُمۡۚ وَأُوحِیَ إِلَیَّ هَـٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَىِٕنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخۡرَىٰۚ قُل لَّاۤ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَـٰهࣱ وَ ٰحِدࣱ وَإِنَّنِی بَرِیۤءࣱ مِّمَّا تُشۡرِكُونَ ۝١٩", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "قل -أيها الرسول لهؤلاء المشركين-: أيُّ شيء أعظم شهادة في إثبات صدقي فيما أخبرتكم به أني رسول الله؟ قل: الله شهيد بيني وبينكم أي: هو العالم بما جئتكم به وما أنتم قائلونه لي، وأوحى الله إليَّ هذا القرآن مِن أجل أن أنذركم به عذابه أن يحلَّ بكم، وأنذر به مَن وصل إليه من الأمم. إنكم لتقرون أن مع الله معبودات أخرى تشركونها به. قل لهم -أيها الرسول-: إني لا أشهد على ما أقررتم به، إنما الله إله واحد لا شريك له، وإنني بريء من كل شريك تعبدونه معه.", "isBasmala": false, "translation_en": "Say, \"What thing is more solemn in testimony?\" Say, \"God is Witness between you and me. This Quran was revealed to me, that I may warn you with it, and whomever it may reach. Do you indeed testify that there are other gods with God?\" Say, \"I myself do not testify.\" Say, \"He is but One God, and I am innocent of your idolatry.\"", "translation_id": "Katakanlah: \"Siapakah yang lebih kuat persaksiannya?\" Katakanlah: \"Allah\". Dia menjadi saksi antara aku dan kamu. Dan Al Quran ini diwahyukan kepadaku supaya dengan dia aku memberi peringatan kepadamu dan kepada orang-orang yang sampai Al-Quran (kepadanya). Apakah sesungguhnya kamu mengakui bahwa ada tuhan-tuhan lain di samping Allah?\" Katakanlah: \"Aku tidak mengakui\". Katakanlah: \"Sesungguhnya Dia adalah Tuhan Yang Maha Esa dan sesungguhnya aku berlepas diri dari apa yang kamu persekutukan (dengan Allah)\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 20, "text": "ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَعۡرِفُونَهُۥ كَمَا یَعۡرِفُونَ أَبۡنَاۤءَهُمُۘ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ فَهُمۡ لَا یُؤۡمِنُونَ ۝٢٠", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "الذين آتيناهم التوراة والإنجيل، يعرفون محمدًا صلى الله عليه وسلم بصفاته المكتوبة عندهم كمعرفتهم أبناءهم، فكما أن أبناءهم لا يشتبهون أمامهم بغيرهم، فكذلك محمد صلى الله عليه وسلم لا يشتبه بغيره لدقة وصفه في كتبهم، ولكنهم اتبعوا أهواءهم، فخسروا أنفسهم حين كفروا بمحمد صلى الله عليه وسلم وبما جاء به.", "isBasmala": false, "translation_en": "Those to whom We have given the Book recognize it as they recognize their own children; but those who have lost their souls do not believe.", "translation_id": "Orang-orang yang telah Kami berikan kitab kepadanya, mereka mengenalnya (Muhammad) seperti mereka mengenal anak-anaknya sendiri. Orang-orang yang merugikan dirinya, mereka itu tidak beriman (kepada Allah).", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 21, "text": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔایَـٰتِهِۦۤۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلظَّـٰلِمُونَ ۝٢١", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "لا أحد أشد ظلمًا ممَّن تَقَوَّلَ الكذب على الله تعالى، فزعم أن له شركاء في العبادة، أو ادَّعى أن له ولدًا أو صاحبة، أو كذب ببراهينه وأدلته التي أيَّد بها رسله عليهم السلام. إنه لا يفلح الظالمون الذين افتروا الكذب على الله، ولا يظفرون بمطالبهم في الدنيا ولا في الآخرة.", "isBasmala": false, "translation_en": "Who does greater wrong than someone who fabricates lies against God, or denies His revelations? The wrongdoers will not succeed.", "translation_id": "Dan siapakah yang lebih aniaya daripada orang yang membuat-buat suatu kedustaan terhadap Allah, atau mendustakan ayat-ayat-Nya? Sesungguhnya orang-orang yang aniaya itu tidak mendapat keberuntungan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 22, "text": "وَیَوۡمَ نَحۡشُرُهُمۡ جَمِیعࣰا ثُمَّ نَقُولُ لِلَّذِینَ أَشۡرَكُوۤا۟ أَیۡنَ شُرَكَاۤؤُكُمُ ٱلَّذِینَ كُنتُمۡ تَزۡعُمُونَ ۝٢٢", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "وليحذر هؤلاء المشركون المكذبون بآيات الله تعالى يوم نحشرهم ثم نقول لهم: أين آلهتكم التي كنتم تدَّعون أنهم شركاء مع الله تعالى ليشفعوا لكم؟", "isBasmala": false, "translation_en": "On the Day when We gather them all together, then say to the idolaters, \"Where are your idols, those you used to claim?\"", "translation_id": "Dan (ingatlah), hari yang di waktu itu Kami menghimpun mereka semuanya kemudian Kami berkata kepada orang-orang musyrik: \"Di manakah sembahan-sembahan kamu yang dulu kamu katakan (sekutu-sekutu) Kami?\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 23, "text": "ثُمَّ لَمۡ تَكُن فِتۡنَتُهُمۡ إِلَّاۤ أَن قَالُوا۟ وَٱللَّهِ رَبِّنَا مَا كُنَّا مُشۡرِكِینَ ۝٢٣", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "ثم لم تكن إجابتهم حين فتنوا واختبروا بالسؤال عن شركائهم إلا أن تبرؤوا منهم، وأقسموا بالله ربهم أنهم لم يكونوا مشركين مع الله غيره.", "isBasmala": false, "translation_en": "Then their only argument will be to say, \"By God, our Lord, we were not idolaters.\"", "translation_id": "Kemudian tiadalah fitnah mereka, kecuali mengatakan: \"Demi Allah, Tuhan kami, tiadalah kami mempersekutukan Allah\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 24, "text": "ٱنظُرۡ كَیۡفَ كَذَبُوا۟ عَلَىٰۤ أَنفُسِهِمۡۚ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ ۝٢٤", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "تأمل -أيها الرسول- كيف كذب هؤلاء المشركون على أنفسهم وهم في الآخرة قد تبرؤوا من الشرك؟ وذهب وغاب عنهم ما كانوا يظنونه من شفاعة آلهتهم.", "isBasmala": false, "translation_en": "Look how they lied to themselves. And what they invented deserted them.", "translation_id": "Lihatlah bagaimana mereka telah berdusta kepada diri mereka sendiri dan hilanglah daripada mereka sembahan-sembahan yang dahulu mereka ada-adakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 25, "text": "وَمِنۡهُم مَّن یَسۡتَمِعُ إِلَیۡكَۖ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن یَفۡقَهُوهُ وَفِیۤ ءَاذَانِهِمۡ وَقۡرࣰاۚ وَإِن یَرَوۡا۟ كُلَّ ءَایَةࣲ لَّا یُؤۡمِنُوا۟ بِهَاۖ حَتَّىٰۤ إِذَا جَاۤءُوكَ یُجَـٰدِلُونَكَ یَقُولُ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ۝٢٥", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "ومن هؤلاء المشركين من يستمع إليك القرآن -أيها الرسول-، فلا يصل إلى قلوبهم؛ لأنهم بسبب اتباعهم أهواءهم جعلنا على قلوبهم أغطية؛ لئلا يفقهوا القرآن، وجعلنا في آذانهم ثقلا وصممًا فلا تسمع ولا تعي شيئًا، وإن يروا الآيات الكثيرة الدالة على صدق محمد صلى الله عليه وسلم لا يصدقوا بها، حتى إذا جاؤوك -أيها الرسول- بعد معاينة الآيات الدالة على صدقك يخاصمونك: يقول الذين جحدوا آيات الله: ما هذا الذي نسمع إلا ما تناقله الأولون من حكايات لا حقيقة لها.", "isBasmala": false, "translation_en": "Among them are those who listen to you; but We place covers over their hearts, to prevent them from understanding it, and heaviness in their ears. Even if they see every sign, they will not believe in it. Until, when they come to you, to argue with you, those who disbelieve will say, \"These are nothing but myths of the ancients.\"", "translation_id": "Dan di antara mereka ada orang yang mendengarkani (bacaan)mu, padahal Kami telah meletakkan tutupan di atas hati mereka (sehingga mereka tidak) memahaminya dan (Kami letakkan) sumbatan di telinganya. Dan jikapun mereka melihat segala tanda (kebenaran), mereka tetap tidak mau beriman kepadanya. Sehingga apabila mereka datang kepadamu untuk membantahmu, orang-orang kafir itu berkata: \"Al-Quran ini tidak lain hanyalah dongengan orang-orang dahulu\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 26, "text": "وَهُمۡ یَنۡهَوۡنَ عَنۡهُ وَیَنۡـَٔوۡنَ عَنۡهُۖ وَإِن یُهۡلِكُونَ إِلَّاۤ أَنفُسَهُمۡ وَمَا یَشۡعُرُونَ ۝٢٦", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "وهؤلاء المشركون ينهون الناس عن اتباع محمد صلى الله عليه وسلم والاستماع إليه، ويبتعدون بأنفسهم عنه، وما يهلكون -بصدهم عن سبيل الله- إلا أنفسهم، وما يحسون أنهم يعملون لهلاكها.", "isBasmala": false, "translation_en": "They keep others from it, and avoid it themselves; but they ruin only their own souls, and they do not realize.", "translation_id": "Dan mereka melarang (orang lain) mendengarkan Al-Quran dan mereka sendiri menjauhkan diri daripadanya, dan mereka hanyalah membinasakan diri mereka sendiri, sedang mereka tidak menyadari.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 27, "text": "وَلَوۡ تَرَىٰۤ إِذۡ وُقِفُوا۟ عَلَى ٱلنَّارِ فَقَالُوا۟ یَـٰلَیۡتَنَا نُرَدُّ وَلَا نُكَذِّبَ بِـَٔایَـٰتِ رَبِّنَا وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ ۝٢٧", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "ولو ترى -أيها الرسول- هؤلاء المشركين يوم القيامة لرأيت أمرًا عظيمًا، وذلك حين يُحْبَسون على النار، ويشاهدون ما فيها من السلاسل والأغلال، ورأوا بأعينهم تلك الأمور العظام والأهوال، فعند ذلك قالوا: ياليتنا نُعاد إلى الحياة الدنيا، فنصدق بآيات الله ونعمل بها، ونكون من المؤمنين.", "isBasmala": false, "translation_en": "If only you could see, when they are made to stand before the Fire; they will say, \"If only we could be sent back, and not reject the revelations of our Lord, and be among the faithful.\"", "translation_id": "Dan jika kamu (Muhammad) melihat ketika mereka dihadapkan ke neraka, lalu mereka berkata: \"Kiranya kami dikembalikan (ke dunia) dan tidak mendustakan ayat-ayat Tuhan kami, serta menjadi orang-orang yang beriman\", (tentulah kamu melihat suatu peristiwa yang mengharukan).", "manzil": 2, "manzil_display": ""}], "131": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 28, "text": "بَلۡ بَدَا لَهُم مَّا كَانُوا۟ یُخۡفُونَ مِن قَبۡلُۖ وَلَوۡ رُدُّوا۟ لَعَادُوا۟ لِمَا نُهُوا۟ عَنۡهُ وَإِنَّهُمۡ لَكَـٰذِبُونَ ۝٢٨", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "ليس الأمر كذلك، بل ظهر لهم يوم القيامة ما كانوا يعلمونه من أنفسهم من صدق ما جاءت به الرسل في الدنيا، وإن كانوا يظهرون لأتباعه خلافه. ولو فرض أن أعيدوا إلى الدنيا فأمهلوا لرجعوا إلى العناد بالكفر والتكذيب. وإنهم لكاذبون في قولهم: لو رددنا إلى الدنيا لم نكذب بآيات ربنا، وكنا من المؤمنين.", "isBasmala": false, "translation_en": "What they used to conceal before will become clear to them. And even if they were sent back, they would revert to what they were forbidden. They are liars.", "translation_id": "Tetapi (sebenarnya) telah nyata bagi mereka kejahatan yang mereka dahulu selalu menyembunyikannya. Sekiranya mereka dikembalikan ke dunia, tentulah mereka kembali kepada apa yang mereka telah dilarang mengerjakannya. Dan sesungguhnya mereka itu adalah pendusta belaka.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 29, "text": "وَقَالُوۤا۟ إِنۡ هِیَ إِلَّا حَیَاتُنَا ٱلدُّنۡیَا وَمَا نَحۡنُ بِمَبۡعُوثِینَ ۝٢٩", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "وقال هؤلاء المشركون المنكرون للبعث: ما الحياة إلا هذه الحياة التي نحن فيها، وما نحن بمبعوثين بعد موتنا.", "isBasmala": false, "translation_en": "And they say, \"There is nothing but our life in this world, and we will not be resurrected.\"", "translation_id": "Dan tentu mereka akan mengatakan (pula): \"Hidup hanyalah kehidupan kita di dunia ini saja, dan kita sekali-sekali tidak akan dibangkitkan\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 30, "text": "وَلَوۡ تَرَىٰۤ إِذۡ وُقِفُوا۟ عَلَىٰ رَبِّهِمۡۚ قَالَ أَلَیۡسَ هَـٰذَا بِٱلۡحَقِّۚ قَالُوا۟ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ۝٣٠", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "ولو ترى -أيها الرسول- منكري البعث إذ حُبسوا بين يدي الله تعالى لقضائه فيهم يوم القيامة، لرأيت أسوأ حال، إذ يقول الله جل وعلا أليس هذا بالحق، أي: أليس هذا البعث الذي كنتم تنكرونه في الدنيا حقًّا؟ قالوا: بلى وربنا إنه لحق، قال الله تعالى: فذوقوا العذاب بما كنتم تكفرون أي: العذاب الذي كنتم تكذبون به في الدنيا بسبب جحودكم بالله تعالى ورسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "If only you could see, when they are stationed before their Lord. He will say, \"Is this not real?\" They will say, \"Yes indeed, by our Lord.\" He will say, \"Then taste the torment for having disbelieved.\"", "translation_id": "Dan seandainya kamu melihat ketika mereka dihadapkan kepada Tuhannya (tentulah kamu melihat peristiwa yang mengharukan). Berfirman Allah: \"Bukankah (kebangkitan ini benar?\" Mereka menjawab: \"Sungguh benar, demi Tuhan kami\". Berfirman Allah: \"Karena itu rasakanlah azab ini, disebabkan kamu mengingkari(nya)\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 31, "text": "قَدۡ خَسِرَ ٱلَّذِینَ كَذَّبُوا۟ بِلِقَاۤءِ ٱللَّهِۖ حَتَّىٰۤ إِذَا جَاۤءَتۡهُمُ ٱلسَّاعَةُ بَغۡتَةࣰ قَالُوا۟ یَـٰحَسۡرَتَنَا عَلَىٰ مَا فَرَّطۡنَا فِیهَا وَهُمۡ یَحۡمِلُونَ أَوۡزَارَهُمۡ عَلَىٰ ظُهُورِهِمۡۚ أَلَا سَاۤءَ مَا یَزِرُونَ ۝٣١", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "قد خسر الكفار الذين أنكروا البعث بعد الموت، حتى إذا قامت القيامة، وفوجئوا بسوء المصير، نادَوا على أنفسهم بالحسرة على ما ضيَّعوه في حياتهم الدنيا، وهم يحملون آثامهم على ظهورهم، فما أسوأ الأحمال الثقيلة السيئة التي يحملونها!!", "isBasmala": false, "translation_en": "Losers are those who deny the encounter with God. Then, when the Hour comes upon them suddenly, they will say, \"Alas for us, how we have neglected it.\" And they will carry their burdens on their backs-evil is what they carry.", "translation_id": "Sungguh telah rugilah orang-orang yang mendustakan pertemuan mereka dengan Tuhan; sehingga apabila kiamat datang kepada mereka dengan tiba-tiba, mereka berkata: \"Alangkah besarnya penyesalan kami, terhadap kelalaian kami tentang kiamat itu!\", sambil mereka memikul dosa-dosa di atas punggungnya. Ingatlah, amat buruklah apa yang mereka pikul itu.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 32, "text": "وَمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا لَعِبࣱ وَلَهۡوࣱۖ وَلَلدَّارُ ٱلۡـَٔاخِرَةُ خَیۡرࣱ لِّلَّذِینَ یَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ۝٣٢", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "وما الحياة الدنيا في غالب أحوالها إلا غرور وباطل، والعمل الصالح للدار الآخرة خير للذين يخشون الله، فيتقون عذابه بطاعته واجتناب معاصيه. أفلا تعقلون -أيها المشركون المغترون بزينة الحياة الدنيا- فتقدِّموا ما يبقى على ما يفنى؟", "isBasmala": false, "translation_en": "The life of this world is nothing but game and distraction, but the Home of the Hereafter is better for those who are righteous. Do you not understand?", "translation_id": "Dan tiadalah kehidupan dunia ini, selain dari main-main dan senda gurau belaka. Dan sungguh kampung akhirat itu lebih baik bagi orang-orang yang bertakwa. Maka tidakkah kamu memahaminya?", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 33, "text": "قَدۡ نَعۡلَمُ إِنَّهُۥ لَیَحۡزُنُكَ ٱلَّذِی یَقُولُونَۖ فَإِنَّهُمۡ لَا یُكَذِّبُونَكَ وَلَـٰكِنَّ ٱلظَّـٰلِمِینَ بِـَٔایَـٰتِ ٱللَّهِ یَجۡحَدُونَ ۝٣٣", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "إنا نعلم إنه ليُدْخل الحزنَ إلى قلبك تكذيبُ قومك لك في الظاهر، فاصبر واطمئن؛ فإنهم لا يكذبونك في قرارة أنفسهم، بل يعتقدون صدقك، ولكنهم لظلمهم وعدوانهم يجحدون البراهين الواضحة على صدقك، فيكذبونك فيما جئت به.", "isBasmala": false, "translation_en": "We know that what they say grieves you. It is not you they reject, but it is God's revelations that the wicked deny.", "translation_id": "Sesungguhnya Kami mengetahui bahwasanya apa yang mereka katakan itu menyedihkan hatimu, (janganlah kamu bersedih hati), karena mereka sebenarnya bukan mendustakan kamu, akan tetapi orang-orang yang zalim itu mengingkari ayat-ayat Allah.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 34, "text": "وَلَقَدۡ كُذِّبَتۡ رُسُلࣱ مِّن قَبۡلِكَ فَصَبَرُوا۟ عَلَىٰ مَا كُذِّبُوا۟ وَأُوذُوا۟ حَتَّىٰۤ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَـٰتِ ٱللَّهِۚ وَلَقَدۡ جَاۤءَكَ مِن نَّبَإِی۟ ٱلۡمُرۡسَلِینَ ۝٣٤", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "ولقد كذَّب الكفارُ رسلا من قبلك أرسلهم الله تعالى إلى أممهم وأوذوا في سبيله، فصبروا على ذلك ومضوا في دعوتهم وجهادهم حتى أتاهم نصر الله. ولا مبدل لكلمات الله، وهي ما أنزل على نبيه محمد صلى الله عليه وسلم مِن وعده إياه بالنصر على مَن عاداه. ولقد جاءك -أيها الرسول- مِن خبر مَن كان قبلك من الرسل، وما تحقق لهم من نصر الله، وما جرى على مكذبيهم من نقمة الله منهم وغضبه عليهم، فلك فيمن تقدم من الرسل أسوة وقدوة. وفي هذا تسلية للرسول صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Other messengers before you were rejected, but they endured rejection and persecution until Our help came to them. There can be no change to God's words. News of the Messengers has already reached you.", "translation_id": "Dan sesungguhnya telah didustakan (pula) rasul-rasul sebelum kamu, akan tetapi mereka sabar terhadap pendustaan dan penganiayaan (yang dilakukan) terhadap mereka, sampai datang pertolongan Allah kepada mereka. Tak ada seorangpun yang dapat merubah kalimat-kalimat (janji-janji) Allah. Dan sesungguhnya telah datang kepadamu sebahagian dari berita rasul-rasul itu.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 35, "text": "وَإِن كَانَ كَبُرَ عَلَیۡكَ إِعۡرَاضُهُمۡ فَإِنِ ٱسۡتَطَعۡتَ أَن تَبۡتَغِیَ نَفَقࣰا فِی ٱلۡأَرۡضِ أَوۡ سُلَّمࣰا فِی ٱلسَّمَاۤءِ فَتَأۡتِیَهُم بِـَٔایَةࣲۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَجَمَعَهُمۡ عَلَى ٱلۡهُدَىٰۚ فَلَا تَكُونَنَّ مِنَ ٱلۡجَـٰهِلِینَ ۝٣٥", "juz": 7, "hizb": "(*¾ ح 13*)", "tafsir": "وإن كان عَظُمَ عليك -أيها الرسول- صدود هؤلاء المشركين وانصرافهم عن الاستجابة لدعوتك، فإن استطعت أن تتخذ نفقًا في الأرض، أو مصعدًا تصعد فيه إلى السماء، فتأتيهم بعلامة وبرهان على صحة قولك غير الذي جئناهم به فافعل. ولو شاء الله لَجَمعهم على الهدى الذي أنتم عليه ووفَّقهم للإيمان، ولكن لم يشأ ذلك لحكمة يعلمها سبحانه، فلا تكونن -أيها الرسول- من الجاهلين الذين اشتد حزنهم، وتحسَّروا حتى أوصلهم ذلك إلى الجزع الشديد.", "isBasmala": false, "translation_en": "If you find their rejection hard to bear, then if you can, seek a tunnel into the earth, or a stairway into the heaven, and bring them a sign. Had God willed, He could have gathered them to guidance. So do not be of the ignorant.", "translation_id": "Dan jika perpalingan mereka (darimu) terasa amat berat bagimu, maka jika kamu dapat membuat lobang di bumi atau tangga ke langit lalu kamu dapat mendatangkan mukjizat kepada mereka (maka buatlah). Kalau Allah menghendaki, tentu saja Allah menjadikan mereka semua dalam petunjuk sebab itu janganlah sekali-kali kamu termasuk orang-orang yang jahil", "manzil": 2, "manzil_display": ""}], "132": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 36, "text": "۞ إِنَّمَا یَسۡتَجِیبُ ٱلَّذِینَ یَسۡمَعُونَۘ وَٱلۡمَوۡتَىٰ یَبۡعَثُهُمُ ٱللَّهُ ثُمَّ إِلَیۡهِ یُرۡجَعُونَ ۝٣٦", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "إنما يجيبك -أيها الرسول- إلى ما دعوت إليه من الهدى الذين يسمعون الكلام سماع قبول. أما الكفار فهم في عداد الموتى؛ لأن الحياة الحقيقية إنما تكون بالإسلام. والموتى يخرجهم الله من قبورهم أحياء، ثم يعودون إليه يوم القيامة ليوفوا حسابهم وجزاءهم.", "isBasmala": false, "translation_en": "Only those who listen will respond. As for the dead, God will resurrect them; then to Him they will be returned.", "translation_id": "Hanya mereka yang mendengar sajalah yang mematuhi (seruan Allah), dan orang-orang yang mati (hatinya), akan dibangkitkan oleh Allah, kemudian kepada-Nya-lah mereka dikembalikan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 37, "text": "وَقَالُوا۟ لَوۡلَا نُزِّلَ عَلَیۡهِ ءَایَةࣱ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ قَادِرٌ عَلَىٰۤ أَن یُنَزِّلَ ءَایَةࣰ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ ۝٣٧", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "وقال المشركون -تعنتًا واستكبارًا-: هلا أنزل الله علامة تدل على صدق محمد صلى الله عليه وسلم من نوع العلامات الخارقة، قل لهم -أيها الرسول-: إن الله قادر على أن ينزل عليهم آية، ولكن أكثرهم لا يعلمون أن إنزال الآيات إنما يكون وَفْق حكمته تعالى.", "isBasmala": false, "translation_en": "And they say, \"If only a sign could come down to him from his Lord.\" Say, \"God is Able to send down a sign, but most of them do not know.\"", "translation_id": "Dan mereka (orang-orang musyrik Mekah) berkata: \"Mengapa tidak diturunkan kepadanya (Muhammad) suatu mukjizat dari Tuhannya?\" Katakanlah: \"Sesungguhnya Allah kuasa menurunkan suatu mukjizat, tetapi kebanyakan mereka tidak mengetahui\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 38, "text": "وَمَا مِن دَاۤبَّةࣲ فِی ٱلۡأَرۡضِ وَلَا طَـٰۤىِٕرࣲ یَطِیرُ بِجَنَاحَیۡهِ إِلَّاۤ أُمَمٌ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِی ٱلۡكِتَـٰبِ مِن شَیۡءࣲۚ ثُمَّ إِلَىٰ رَبِّهِمۡ یُحۡشَرُونَ ۝٣٨", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "ليس في الأرض حيوان يَدِبُّ على الأرض أو طائر يطير في السماء بجناحيه إلا جماعات متجانسة الخلق مثلكم. ما تركنا في اللوح المحفوظ شيئًا إلا أثبتناه، ثم إنهم إلى ربهم يحشرون يوم القيامة، فيحاسب الله كلا بما عمل.", "isBasmala": false, "translation_en": "There is no animal on land, nor a bird flying with its wings, but are communities like you. We neglected nothing in the Scripture. Then to their Lord they will be gathered.", "translation_id": "Dan tiadalah binatang-binatang yang ada di bumi dan burung-burung yang terbang dengan kedua sayapnya, melainkan umat (juga) seperti kamu. Tiadalah Kami alpakan sesuatupun dalam Al-Kitab, kemudian kepada Tuhanlah mereka dihimpunkan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 39, "text": "وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا صُمࣱّ وَبُكۡمࣱ فِی ٱلظُّلُمَـٰتِۗ مَن یَشَإِ ٱللَّهُ یُضۡلِلۡهُ وَمَن یَشَأۡ یَجۡعَلۡهُ عَلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٣٩", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "والذين كذبوا بحجج الله تعالى صمٌّ لا يسمعون ما ينفعهم، بُكْمٌ لا يتكلمون بالحق، فهم حائرون في الظلمات، لم يختاروا طريقة الاستقامة. من يشأ الله إضلاله يضلله، ومن يشأ هدايته يجعله على صراط مستقيم.", "isBasmala": false, "translation_en": "Those who reject Our revelations are deaf and dumb, in total darkness. Whomever God wills, He leaves astray; and whomever He wills, He sets on a straight path.", "translation_id": "Dan orang-orang yang mendustakan ayat-ayat Kami adalah pekak, bisu dan berada dalam gelap gulita. Barangsiapa yang dikehendaki Allah (kesesatannya), niscaya disesatkan-Nya. Dan barangsiapa yang dikehendaki Allah (untuk diberi-Nya petunjuk), niscaya Dia menjadikan-Nya berada di atas jalan yang lurus.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 40, "text": "قُلۡ أَرَءَیۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ أَوۡ أَتَتۡكُمُ ٱلسَّاعَةُ أَغَیۡرَ ٱللَّهِ تَدۡعُونَ إِن كُنتُمۡ صَـٰدِقِینَ ۝٤٠", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن جاءكم عذاب الله في الدنيا أو جاءتكم الساعة التي تبعثون فيها: أغير الله تدعون هناك لكشف ما نزل بكم من البلاء، إن كتم محقين في زعمكم أن آلهتكم التي تعبدونها من دون الله تنفع أو تضر؟", "isBasmala": false, "translation_en": "Say, \"Have you considered? if God's punishment came upon you, or the Hour overtook you, would you call upon any other than God, if you are sincere?\"", "translation_id": "Katakanlah: \"Terangkanlah kepadaku jika datang siksaan Allah kepadamu, atau datang kepadamu hari kiamat, apakah kamu menyeru (tuhan) selain Allah; jika kamu orang-orang yang benar!\"", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 41, "text": "بَلۡ إِیَّاهُ تَدۡعُونَ فَیَكۡشِفُ مَا تَدۡعُونَ إِلَیۡهِ إِن شَاۤءَ وَتَنسَوۡنَ مَا تُشۡرِكُونَ ۝٤١", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "بل تدعون -هناك- ربكم الذي خلقكم لا غيره، وتستغيثون به، فيفرج عنكم البلاء العظيم النازل بكم إن شاء؛ لأنه القادر على كل شيء، وتتركون حينئذ أصنامكم وأوثانكم وأولياءكم.", "isBasmala": false, "translation_en": "In fact, it is Him you will call upon; and if He wills, he will remove what you called Him for, and you will forget what you idolized.", "translation_id": "(Tidak), tetapi hanya Dialah yang kamu seru, maka Dia menghilangkan bahaya yang karenanya kamu berdoa kepada-Nya, jika Dia menghendaki, dan kamu tinggalkan sembahan-sembahan yang kamu sekutukan (dengan Allah).", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 42, "text": "وَلَقَدۡ أَرۡسَلۡنَاۤ إِلَىٰۤ أُمَمࣲ مِّن قَبۡلِكَ فَأَخَذۡنَـٰهُم بِٱلۡبَأۡسَاۤءِ وَٱلضَّرَّاۤءِ لَعَلَّهُمۡ یَتَضَرَّعُونَ ۝٤٢", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "ولقد بعثنا -أيها الرسول- إلى جماعات من الناس من قبلك رسلا يدعونهم إلى الله تعالى، فكذَّبوهم، فابتليناهم في أموالهم بشدة الفقر وضيق المعيشة، وابتليناهم في أجسامهم بالأمراض والآلام؛ رجاء أن يتذللوا لربهم، ويخضعوا له وحده بالعبادة.", "isBasmala": false, "translation_en": "We sent messengers to communities before you, and We afflicted them with suffering and hardship, that they may humble themselves.", "translation_id": "Dan sesungguhnya Kami telah mengutus (rasul-rasul) kepada umat-umat yang sebelum kamu, kemudian Kami siksa mereka dengan (menimpakan) kesengsaraan dan kemelaratan, supaya mereka memohon (kepada Allah) dengan tunduk merendahkan diri.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 43, "text": "فَلَوۡلَاۤ إِذۡ جَاۤءَهُم بَأۡسُنَا تَضَرَّعُوا۟ وَلَـٰكِن قَسَتۡ قُلُوبُهُمۡ وَزَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ مَا كَانُوا۟ یَعۡمَلُونَ ۝٤٣", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "فهلا إذ جاء هذه الأمم المكذبة بلاؤنا تذللوا لنا، ولكن قست قلوبهم، وزيَّن لهم الشيطان ما كانوا يعملون من المعاصي، ويأتون من الشرك.", "isBasmala": false, "translation_en": "If only, when Our calamity came upon them, they humbled themselves. But their hearts hardened, and Satan made their deeds appear good to them.", "translation_id": "Maka mengapa mereka tidak memohon (kepada Allah) dengan tunduk merendahkan diri ketika datang siksaan Kami kepada mereka, bahkan hati mereka telah menjadi keras, dan syaitanpun menampakkan kepada mereka kebagusan apa yang selalu mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 44, "text": "فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦ فَتَحۡنَا عَلَیۡهِمۡ أَبۡوَ ٰبَ كُلِّ شَیۡءٍ حَتَّىٰۤ إِذَا فَرِحُوا۟ بِمَاۤ أُوتُوۤا۟ أَخَذۡنَـٰهُم بَغۡتَةࣰ فَإِذَا هُم مُّبۡلِسُونَ ۝٤٤", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "فلما تركوا العمل بأوامر الله تعالى معرضين عنها، فتحنا عليهم أبواب كل شيء من الرزق فأبدلناهم بالبأساء رخاءً في العيش، وبالضراء صحة في الأجسام؛ استدراجا منا لهم، حتى إذا بطروا، وأعجبوا بما أعطيناهم من الخير والنعمة أخذناهم بالعذاب فجأة، فإذا هم آيسون منقطعون من كل خير.", "isBasmala": false, "translation_en": "Then, when they disregarded what they were reminded of, We opened for them the gates of all things. Until, when they delighted in what they were given, We seized them suddenly; and at once, they were in despair.", "translation_id": "Maka tatkala mereka melupakan peringatan yang telah diberikan kepada mereka, Kamipun membukakan semua pintu-pintu kesenangan untuk mereka; sehingga apabila mereka bergembira dengan apa yang telah diberikan kepada mereka, Kami siksa mereka dengan sekonyong-konyong, maka ketika itu mereka terdiam berputus asa.", "manzil": 2, "manzil_display": ""}], "133": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 45, "text": "فَقُطِعَ دَابِرُ ٱلۡقَوۡمِ ٱلَّذِینَ ظَلَمُوا۟ۚ وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ ۝٤٥", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "فاستؤصل هؤلاء القوم وأُهلكوا إذ كفروا بالله وكذَّبوا رسله، فلم يبق منهم أحد. والشكر والثناء لله تعالى -خالق كل شيء ومالكه- على نصرة أوليائه وهلاك أعدائه.", "isBasmala": false, "translation_en": "Thus the last remnant of the people who did wrong was cut off. And praise be to God, Lord of the Worlds.", "translation_id": "Maka orang-orang yang zalim itu dimusnahkan sampai ke akar-akarnya. Segala puji bagi Allah, Tuhan semesta alam.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 46, "text": "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَخَذَ ٱللَّهُ سَمۡعَكُمۡ وَأَبۡصَـٰرَكُمۡ وَخَتَمَ عَلَىٰ قُلُوبِكُم مَّنۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِ یَأۡتِیكُم بِهِۗ ٱنظُرۡ كَیۡفَ نُصَرِّفُ ٱلۡـَٔایَـٰتِ ثُمَّ هُمۡ یَصۡدِفُونَ ۝٤٦", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن أذهب الله سمعكم فأصمَّكم، وذهب بأبصاركم فأعماكم، وطبع على قلوبكم فأصبحتم لا تفقهون قولا أيُّ إله غير الله جل وعلا يقدر على ردِّ ذلك لكم؟! انظر -أيها الرسول- كيف ننوِّع لهم الحجج، ثم هم بعد ذلك يعرضون عن التذكر والاعتبار؟", "isBasmala": false, "translation_en": "Say, \"Have you considered? If God took away your hearing and your sight, and set a seal on your hearts, what god other than God would restore them to you?\" Note how We explain the revelations in various ways, yet they still turn away.", "translation_id": "Katakanlah: \"Terangkanlah kepadaku jika Allah mencabut pendengaran dan penglihatan serta menutup hatimu, siapakah tuhan selain Allah yang kuasa mengembalikannya kepadamu?\" Perhatikanlah bagaimana Kami berkali-kali memperlihatkan tanda-tanda kebesaran (Kami), kemudian mereka tetap berpaling (juga).", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 47, "text": "قُلۡ أَرَءَیۡتَكُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُ ٱللَّهِ بَغۡتَةً أَوۡ جَهۡرَةً هَلۡ یُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلظَّـٰلِمُونَ ۝٤٧", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن نزل بكم عقاب الله فجأة وأنتم لا تشعرون به، أو ظاهرًا عِيانًا وأنتم تنظرون إليه: هل يُهلك إلا القوم الظالمون الذين تجاوزوا الحد، بصرفهم العبادة لغير الله تعالى وبتكذيبهم رسله؟", "isBasmala": false, "translation_en": "Say, \"Have you considered? if God's punishment descended on you suddenly or gradually, would any be destroyed except the wrongdoing people?\"", "translation_id": "Katakanlah: \"Terangkanlah kepadaku jika datang siksaan Allah kepadamu dengan sekonyong-konyong, atau terang-terangan, maka adakah yang dibinasakan (Allah) selain dari orang yang zalim?\"", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 48, "text": "وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِینَ إِلَّا مُبَشِّرِینَ وَمُنذِرِینَۖ فَمَنۡ ءَامَنَ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝٤٨", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "وما نرسل رسلنا إلا مبشرين أهل طاعتنا بالنعيم المقيم، ومنذرين أهل المعصية بالعذاب الأليم، فمن آمن وصدَّق الرسل وعمل صالحًا فأولئك لا يخافون عند لقاء ربهم، ولا يحزنون على شيء فاتهم من حظوظ الدنيا.", "isBasmala": false, "translation_en": "We sent the messengers only as bearers of good news and as warners. Those who believe and reform have nothing to fear, nor shall they grieve.", "translation_id": "Dan tidaklah Kami mengutus para rasul itu melainkan untuk memberikan kabar gembira dan memberi peringatan. Barangsiapa yang beriman dan mengadakan perbaikan, maka tak ada kekhawatiran terhadap mereka dan tidak pula mereka bersedih hati.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 49, "text": "وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا یَمَسُّهُمُ ٱلۡعَذَابُ بِمَا كَانُوا۟ یَفۡسُقُونَ ۝٤٩", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "والذين كذَّبوا بآياتنا من القرآن والمعجزات فأولئك يصيبهم العذاب يوم القيامة، بسبب كفرهم وخروجهم عن طاعة الله تعالى.", "isBasmala": false, "translation_en": "But as for those who reject Our revelations, torment will afflict them because of their defiance.", "translation_id": "Dan orang-orang yang mendustakan ayat-ayat Kami, mereka akan ditimpa siksa disebabkan mereka selalu berbuat fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 50, "text": "قُل لَّاۤ أَقُولُ لَكُمۡ عِندِی خَزَاۤىِٕنُ ٱللَّهِ وَلَاۤ أَعۡلَمُ ٱلۡغَیۡبَ وَلَاۤ أَقُولُ لَكُمۡ إِنِّی مَلَكٌۖ إِنۡ أَتَّبِعُ إِلَّا مَا یُوحَىٰۤ إِلَیَّۚ قُلۡ هَلۡ یَسۡتَوِی ٱلۡأَعۡمَىٰ وَٱلۡبَصِیرُۚ أَفَلَا تَتَفَكَّرُونَ ۝٥٠", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: إني لا أدَّعي أني أملك خزائن السموات والأرض، فأتصرف فيها، ولا أدَّعي أني أعلم الغيب، ولا أدَّعي أني ملك، وإنما أنا رسول من عند الله، أتبع ما يوحى إليَّ، وأبلِّغ وحيه إلى الناس، قل -أيها الرسول- لهؤلاء المشركين: هل يستوي الكافر الذي عَمِي عن آيات الله تعالى فلم يؤمن بها والمؤمن الذي أبصر آيات الله فآمن بها؟ أفلا تتفكرون في آيات الله؛ لتبصروا الحق فتؤمنوا به؟", "isBasmala": false, "translation_en": "Say, \"I do not say to you that I possess the treasuries of God, nor do I know the future, nor do I say to you that I am an angel. I only follow what is inspired to me.\" Say, \"Are the blind and the seeing alike? Do you not think?\"", "translation_id": "Katakanlah: Aku tidak mengatakan kepadamu, bahwa perbendaharaan Allah ada padaku, dan tidak (pula) aku mengetahui yang ghaib dan tidak (pula) aku mengatakan kepadamu bahwa aku seorang malaikat. Aku tidak mengikuti kecuali apa yang diwahyukan kepadaku. Katakanlah: \"Apakah sama orang yang buta dengan yang melihat?\" Maka apakah kamu tidak memikirkan(nya)?\"", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 51, "text": "وَأَنذِرۡ بِهِ ٱلَّذِینَ یَخَافُونَ أَن یُحۡشَرُوۤا۟ إِلَىٰ رَبِّهِمۡ لَیۡسَ لَهُم مِّن دُونِهِۦ وَلِیࣱّ وَلَا شَفِیعࣱ لَّعَلَّهُمۡ یَتَّقُونَ ۝٥١", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "وخوِّف -أيها النبي- بالقرآن الذين يعلمون أنهم يُحشرون إلى ربهم، فهم مصدِّقون بوعد الله ووعيده، ليس لهم غير الله وليّ ينصرهم، ولا شفيع يشفع لهم عنده تعالى، فيخلصهم من عذابه؛ لعلهم يتقون الله تعالى بفعل الأوامر واجتناب النواهي.", "isBasmala": false, "translation_en": "And warn with it those who fear to be gathered before their Lord-they have no protector or intercessor apart from him-perhaps they will grow in piety.", "translation_id": "Dan berilah peringatan dengan apa yang diwahyukan itu kepada orang-orang yang takut akan dihimpunkan kepada Tuhannya (pada hari kiamat), sedang bagi mereka tidak ada seorang pelindung dan pemberi syafa'atpun selain daripada Allah, agar mereka bertakwa.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 52, "text": "وَلَا تَطۡرُدِ ٱلَّذِینَ یَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِیِّ یُرِیدُونَ وَجۡهَهُۥۖ مَا عَلَیۡكَ مِنۡ حِسَابِهِم مِّن شَیۡءࣲ وَمَا مِنۡ حِسَابِكَ عَلَیۡهِم مِّن شَیۡءࣲ فَتَطۡرُدَهُمۡ فَتَكُونَ مِنَ ٱلظَّـٰلِمِینَ ۝٥٢", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "ولا تُبْعد -أيها النبي- عن مجالستك ضعفاء المسلمين الذين يعبدون ربهم أول النهار وآخره، يريدون بأعمالهم الصالحة وجه الله، ما عليك من حساب هؤلاء الفقراء من شيء، إنما حسابهم على الله، وليس عليهم شيء من حسابك، فإن أبعدتهم فإنك تكون من المتجاوزين حدود الله، الذين يضعون الشيء في غير موضعه.", "isBasmala": false, "translation_en": "And do not drive away those who call upon their Lord, morning and evening, seeking His attention. You are not accountable for them in any way, nor are they accountable for you in any way. If you drive them away, you would be one of the unjust.", "translation_id": "Dan janganlah kamu mengusir orang-orang yang menyeru Tuhannya di pagi dan petang hari, sedang mereka menghendaki keridhaan-Nya. Kamu tidak memikul tanggung jawab sedikitpun terhadap perbuatan mereka dan merekapun tidak memikul tanggung jawab sedikitpun terhadap perbuatanmu, yang menyebabkan kamu (berhak) mengusir mereka, (sehingga kamu termasuk orang-orang yang zalim).", "manzil": 2, "manzil_display": ""}], "134": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 53, "text": "وَكَذَ ٰلِكَ فَتَنَّا بَعۡضَهُم بِبَعۡضࣲ لِّیَقُولُوۤا۟ أَهَـٰۤؤُلَاۤءِ مَنَّ ٱللَّهُ عَلَیۡهِم مِّنۢ بَیۡنِنَاۤۗ أَلَیۡسَ ٱللَّهُ بِأَعۡلَمَ بِٱلشَّـٰكِرِینَ ۝٥٣", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "وكذالك ابتلى الله تعالى بعض عباده ببعض بتباين حظوظهم من الأرزاق والأخلاق، فجعل بعضهم غنيًّا وبعضهم فقيرًا، وبعضهم قويًّا وبعضهم ضعيفًا، فأحوج بعضهم إلى بعض اختبارًا منه لهم بذلك؛ ليقول الكافرون الأغنياء: أهؤلاء الضعفاء مَنَّ الله عليهم بالهداية إلى الإسلام مِن بيننا؟ أليس الله تعالى بأعلم بمن يشكرون نعمته، فيوفقهم إلى الهداية لدينه؟", "isBasmala": false, "translation_en": "Thus We try some of them by means of others, that they may say, \"Are these the ones whom God has favored from among us?\" Is God not aware of the appreciative?", "translation_id": "Dan demikianlah telah Kami uji sebahagian mereka (orang-orang kaya) dengan sebahagian mereka (orang-orang miskin), supaya (orang-orang yang kaya itu) berkata: \"Orang-orang semacam inikah di antara kita yang diberi anugerah Allah kepada mereka?\" (Allah berfirman): \"Tidakkah Allah lebih mengetahui tentang orang-orang yang bersyukur (kepada-Nya)?\"", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 54, "text": "وَإِذَا جَاۤءَكَ ٱلَّذِینَ یُؤۡمِنُونَ بِـَٔایَـٰتِنَا فَقُلۡ سَلَـٰمٌ عَلَیۡكُمۡۖ كَتَبَ رَبُّكُمۡ عَلَىٰ نَفۡسِهِ ٱلرَّحۡمَةَ أَنَّهُۥ مَنۡ عَمِلَ مِنكُمۡ سُوۤءَۢا بِجَهَـٰلَةࣲ ثُمَّ تَابَ مِنۢ بَعۡدِهِۦ وَأَصۡلَحَ فَأَنَّهُۥ غَفُورࣱ رَّحِیمࣱ ۝٥٤", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "وإذا جاءك -أيها النبي- الذين صَدَّقوا بآيات الله الشاهدة على صدقك من القرآن وغيره مستفتين عن التوبة من ذنوبهم السابقة، فأكرِمْهم بردِّ السلام عليهم، وبَشِّرهم برحمة الله الواسعة؛ فإنه جلَّ وعلا قد كتب على نفسه الرحمة بعباده تفضلا أنه من اقترف ذنبًا بجهالة منه لعاقبتها وإيجابها لسخط الله -فكل عاص لله مخطئًا أو متعمدًا فهو جاهل بهذا الاعتبار وإن كان عالمًا بالتحريم- ثم تاب من بعده وداوم على العمل الصالح، فإنه تعالى يغفر ذنبه، فهو غفور لعباده التائبين، رحيم بهم.", "isBasmala": false, "translation_en": "When those who believe in Our revelations come to you, say, \"Peace be upon you, your Lord has prescribed mercy for Himself. Whoever among you does wrong out of ignorance, and then repents afterwards and reforms-He is Forgiving and Merciful.\"", "translation_id": "Apabila orang-orang yang beriman kepada ayat-ayat Kami itu datang kepadamu, maka katakanlah: \"Salaamun alaikum. Tuhanmu telah menetapkan atas diri-Nya kasih sayang, (yaitu) bahwasanya barang siapa yang berbuat kejahatan di antara kamu lantaran kejahilan, kemudian ia bertaubat setelah mengerjakannya dan mengadakan perbaikan, maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 55, "text": "وَكَذَ ٰلِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ وَلِتَسۡتَبِینَ سَبِیلُ ٱلۡمُجۡرِمِینَ ۝٥٥", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "ومثل هذا البيان الذي بيَّنَّاه لك -أيها الرسول- نبيِّن الحجج الواضحة على كل حق ينكره أهل الباطل؛ ليتبين الحق، وليظهر طريق أهل الباطل المخالفين للرسل.", "isBasmala": false, "translation_en": "Thus We explain the revelations, and expose the path of the unrighteous.", "translation_id": "Dan demikianlah Kami terangkan ayat-ayat Al-Quran (supaya jelas jalan orang-orang yang saleh, dan supaya jelas (pula) jalan orang-orang yang berdosa.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 56, "text": "قُلۡ إِنِّی نُهِیتُ أَنۡ أَعۡبُدَ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِۚ قُل لَّاۤ أَتَّبِعُ أَهۡوَاۤءَكُمۡ قَدۡ ضَلَلۡتُ إِذࣰا وَمَاۤ أَنَا۠ مِنَ ٱلۡمُهۡتَدِینَ ۝٥٦", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: إن الله عز وجل نهاني أن أعبد الأوثان التي تعبدونها من دونه، وقل لهم: لا أتبع أهواءكم قد ضللت عن الصراط المستقيم إن اتبعت أهواءَكم، وما أنا من المهتدين.", "isBasmala": false, "translation_en": "Say, \"I am forbidden from worshiping those you pray to besides God.\" Say, \"I will not follow your desires; else I would be lost and not be of those guided.\"", "translation_id": "Katakanlah: \"Sesungguhnya aku dilarang menyembah tuhan-tuhan yang kamu sembah selain Allah\". Katakanlah: \"Aku tidak akan mengikuti hawa nafsumu, sungguh tersesatlah aku jika berbuat demikian dan tidaklah (pula) aku termasuk orang-orang yang mendapat petunjuk\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 57, "text": "قُلۡ إِنِّی عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّی وَكَذَّبۡتُم بِهِۦۚ مَا عِندِی مَا تَسۡتَعۡجِلُونَ بِهِۦۤۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ یَقُصُّ ٱلۡحَقَّۖ وَهُوَ خَیۡرُ ٱلۡفَـٰصِلِینَ ۝٥٧", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "قل -أيها الرسول لهؤلاء المشركين-: إني على بصيرة واضحة من شريعة الله التي أوحاها إليَّ، وذلك بإفراده وحده بالعبادة، وقد كذَّبتم بهذا، وليس في قدرتي إنزال العذاب الذي تستعجلون به، وما الحكم في تأخر ذلك إلا إلى الله تعالى، يقصُّ الحقَّ، وهو خير مَن يفصل بين الحق والباطل بقضائه وحكمه.", "isBasmala": false, "translation_en": "Say, \"I stand on clear evidence from my Lord, and you have rejected Him. I do not possess what you seek me to hasten; the decision belongs solely to God. He states the truth, and He is the Best of Judges.\"", "translation_id": "Katakanlah: \"Sesungguhnya aku berada di atas hujjah yang nyata (Al Quran) dari Tuhanku, sedang kamu mendustakannya. Tidak ada padaku apa (azab) yang kamu minta supaya disegerakan kedatangannya. Menetapkan hukum itu hanyalah hak Allah. Dia menerangkan yang sebenarnya dan Dia Pemberi keputusan yang paling baik\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 58, "text": "قُل لَّوۡ أَنَّ عِندِی مَا تَسۡتَعۡجِلُونَ بِهِۦ لَقُضِیَ ٱلۡأَمۡرُ بَیۡنِی وَبَیۡنَكُمۡۗ وَٱللَّهُ أَعۡلَمُ بِٱلظَّـٰلِمِینَ ۝٥٨", "juz": 7, "hizb": "(* ح 14*)", "tafsir": "قل -أيها الرسول-: لو أنني أملك إنزال العذاب الذي تستحجلونه لأنزلته بكم، وقضي الأمر بيني وبينكم، ولكن ذلك إلى الله تعالى، وهو أعلم بالظالمين الذين تجاوزوا حدَّهم فأشركوا معه غيره.", "isBasmala": false, "translation_en": "Say, \"If I possessed what you seek me to hasten, the matter between you and me would have been settled. God is well aware of the unjust.\"", "translation_id": "Katakanlah: \"Kalau sekiranya ada padaku apa (azab) yang kamu minta supaya disegerakan, tentu telah diselesaikan Allah urusan yang ada antara aku dan kamu. Dan Allah lebih mengetahui tentang orang-orang yang zalim.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 59, "text": "۞ وَعِندَهُۥ مَفَاتِحُ ٱلۡغَیۡبِ لَا یَعۡلَمُهَاۤ إِلَّا هُوَۚ وَیَعۡلَمُ مَا فِی ٱلۡبَرِّ وَٱلۡبَحۡرِۚ وَمَا تَسۡقُطُ مِن وَرَقَةٍ إِلَّا یَعۡلَمُهَا وَلَا حَبَّةࣲ فِی ظُلُمَـٰتِ ٱلۡأَرۡضِ وَلَا رَطۡبࣲ وَلَا یَابِسٍ إِلَّا فِی كِتَـٰبࣲ مُّبِینࣲ ۝٥٩", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "وعند الله -جل وعلا- مفاتح الغيب أي: خزائن الغيب، لا يعلمها إلا هو، ومنها: علم الساعة، ونزول الغيث، وما في الأرحام، والكسب في المستقبل، ومكان موت الإنسان، ويعلم كل ما في البر والبحر، وما تسقط من ورقة من نبتة إلا يعلمها، فكل حبة في خفايا الأرض، وكل رطب ويابس، مثبت في كتاب واضح لا لَبْس فيه، وهو اللوح المحفوظ.", "isBasmala": false, "translation_en": "With Him are the keys of the unseen; none knows them except He. And He knows everything on land and in the sea. Not a leaf falls but He knows it; and there is not a single grain in the darkness of earth, nor is there anything wet or dry, but is in a clear record.", "translation_id": "Dan pada sisi Allah-lah kunci-kunci semua yang ghaib; tidak ada yang mengetahuinya kecuali Dia sendiri, dan Dia mengetahui apa yang di daratan dan di lautan, dan tiada sehelai daun pun yang gugur melainkan Dia mengetahuinya (pula), dan tidak jatuh sebutir biji-pun dalam kegelapan bumi, dan tidak sesuatu yang basah atau yang kering, melainkan tertulis dalam kitab yang nyata (Lauh Mahfudz)\"", "manzil": 2, "manzil_display": ""}], "135": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 60, "text": "وَهُوَ ٱلَّذِی یَتَوَفَّىٰكُم بِٱلَّیۡلِ وَیَعۡلَمُ مَا جَرَحۡتُم بِٱلنَّهَارِ ثُمَّ یَبۡعَثُكُمۡ فِیهِ لِیُقۡضَىٰۤ أَجَلࣱ مُّسَمࣰّىۖ ثُمَّ إِلَیۡهِ مَرۡجِعُكُمۡ ثُمَّ یُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٦٠", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "وهو سبحانه الذي يقبض أرواحكم بالليل بما يشبه قبضها عند الموت، ويعلم ما اكتسبتم في النهار من الأعمال، ثم يعيد أرواحكم إلى أجسامكم باليقظة من النوم نهارًا بما يشبه الأحياء بعد الموت؛ لتُقضى آجالكم المحددة في الدنيا، ثم إلى الله تعالى معادكم بعد بعثكم من قبوركم أحياءً، ثم يخبركم بما كنتم تعملون في حياتكم الدنيا، ثم يجازيكم بذلك.", "isBasmala": false, "translation_en": "It is He Who takes you by night, and He knows what you earn by day. Then He raises you up in it, until a fixed term is fulfilled. Then to Him is your return, then He will inform you of what you used to do.", "translation_id": "Dan Dialah yang menidurkan kamu di malam hari dan Dia mengetahui apa yang kamu kerjakan di siang hari, kemudian Dia membangunkan kamu pada siang hari untuk disempurnakan umur(mu) yang telah ditentukan, kemudian kepada Allah-lah kamu kembali, lalu Dia memberitahukan kepadamu apa yang dahulu kamu kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 61, "text": "وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَیُرۡسِلُ عَلَیۡكُمۡ حَفَظَةً حَتَّىٰۤ إِذَا جَاۤءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا یُفَرِّطُونَ ۝٦١", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "والله تعالى هو القاهر فوق عباده، فوقية مطلقة من كل وجه، تليق بجلاله سبحانه وتعالى. كل شيء خاضع لجلاله وعظمته، ويرسل على عباده ملائكة، يحفظون أعمالهم ويُحْصونها، حتى إذا نزل الموت بأحدهم قبض روحَه مَلكُ الموت وأعوانه، وهم لا يضيعون ما أُمروا به.", "isBasmala": false, "translation_en": "He is the Conqueror over His servants, and He sends guardians over you, until, when death overtakes one of you, Our envoys take him away, and they never fail.", "translation_id": "Dan Dialah yang mempunyai kekuasaan tertinggi di atas semua hamba-Nya, dan diutus-Nya kepadamu malaikat-malaikat penjaga, sehingga apabila datang kematian kepada salah seorang di antara kamu, ia diwafatkan oleh malaikat-malaikat Kami, dan malaikat-malaikat Kami itu tidak melalaikan kewajibannya.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 62, "text": "ثُمَّ رُدُّوۤا۟ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۚ أَلَا لَهُ ٱلۡحُكۡمُ وَهُوَ أَسۡرَعُ ٱلۡحَـٰسِبِینَ ۝٦٢", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "ثم أعيد هؤلاء المتوفون إلى الله تعالى مولاهم الحق. ألا له القضاء والفصل يوم القيامة بين عباده وهو أسرع الحاسبين.", "isBasmala": false, "translation_en": "Then they are brought back to God, their True Master. Unquestionably, His is the judgment, and He is the Swiftest of reckoners.", "translation_id": "Kemudian mereka (hamba Allah) dikembalikan kepada Allah, Penguasa mereka yang sebenarnya. Ketahuilah bahwa segala hukum (pada hari itu) kepunyaan-Nya. Dan Dialah Pembuat Perhitungan yang paling cepat.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 63, "text": "قُلۡ مَن یُنَجِّیكُم مِّن ظُلُمَـٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ تَدۡعُونَهُۥ تَضَرُّعࣰا وَخُفۡیَةࣰ لَّىِٕنۡ أَنجَىٰنَا مِنۡ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِینَ ۝٦٣", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: من ينقذكم من مخاوف ظلمات البر والبحر؟ أليس هو الله تعالى الذي تدعونه في الشدائد متذللين جهرًا وسرًّا؟ تقولون: لئن أنجانا ربنا من هذه المخاوف لنكونن من الشاكرين بعبادته عز وجل وحده لا شريك له.", "isBasmala": false, "translation_en": "Say, \"Who delivers you from the darkness of land and sea?\" You call upon Him humbly and inwardly: \"If He delivers us from this, We will surely be among the thankful.\"", "translation_id": "Katakanlah: \"Siapakah yang dapat menyelamatkan kamu dari bencana di darat dan di laut, yang kamu berdoa kepada-Nya dengan rendah diri dengan suara yang lembut (dengan mengatakan: \"Sesungguhnya jika Dia menyelamatkan kami dari (bencana) ini, tentulah kami menjadi orang-orang yang bersyukur\"\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 64, "text": "قُلِ ٱللَّهُ یُنَجِّیكُم مِّنۡهَا وَمِن كُلِّ كَرۡبࣲ ثُمَّ أَنتُمۡ تُشۡرِكُونَ ۝٦٤", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "قل لهم -أيها الرسول-: الله وحده هو الذي ينقذكم من هذه المخاوف ومن كل شدة، ثم أنتم بعد ذلك تشركون معه في العبادة غيره.", "isBasmala": false, "translation_en": "Say, \"It is God who delivers you from it, and from every disaster. Yet then you associate others with Him.\"", "translation_id": "Katakanlah: \"Allah menyelamatkan kamu dari bencana itu dan dari segala macam kesusahan, kemudian kamu kembali mempersekutukan-Nya\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 65, "text": "قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰۤ أَن یَبۡعَثَ عَلَیۡكُمۡ عَذَابࣰا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ یَلۡبِسَكُمۡ شِیَعࣰا وَیُذِیقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَیۡفَ نُصَرِّفُ ٱلۡـَٔایَـٰتِ لَعَلَّهُمۡ یَفۡقَهُونَ ۝٦٥", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "قل -أيها الرسول-: الله عز وجل هو القادر وحده على أن يرسل عليكم عذابًا مِن فوقكم كالرَّجْم أو الطوفان، وما أشبه ذلك، أو من تحت أرجلكم كالزلازل والخسف، أو يخلط أمركم عليكم فتكونوا فرقًا متناحرة يقتل بعضكم بعضًا. انظر -أيها الرسول- كيف نُنوِّع حججنا الواضحات لهؤلاء المشركين لعلهم يفهمون فيعتبروا؟", "isBasmala": false, "translation_en": "Say, \"He is Able to send upon you an affliction, from above you, or from under your feet. Or He can divide you into factions, and make you taste the violence of one another. Note how We explain the revelations, so that they may understand.\"", "translation_id": "Katakanlah: \"Dialah yang berkuasa untuk mengirimkan azab kepadamu, dari atas kamu atau dari bawah kakimu atau Dia mencampurkan kamu dalam golongan-golongan (yang saling bertentangan) dan merasakan kepada sebahagian kamu keganasan sebahagian yang lain. Perhatikanlah, betapa Kami mendatangkan tanda-tanda kebesaran Kami silih berganti agar mereka memahami(nya)\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 66, "text": "وَكَذَّبَ بِهِۦ قَوۡمُكَ وَهُوَ ٱلۡحَقُّۚ قُل لَّسۡتُ عَلَیۡكُم بِوَكِیلࣲ ۝٦٦", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "وكذَّب بهذا القرآن الكفارُ مِن قومك أيها الرسول، وهو الكتاب الصادق في كل ما جاء به. قل لهم: لست عليكم بحفيظ ولا رقيب، وإنما أنا رسول الله أبلغكم ما أرسلت به.", "isBasmala": false, "translation_en": "But your people rejected it, though it is the truth. Say, \"I am not responsible for you.\"", "translation_id": "Dan kaummu mendustakannya (azab) padahal azab itu benar adanya. Katakanlah: \"Aku ini bukanlah orang yang diserahi mengurus urusanmu\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 67, "text": "لِّكُلِّ نَبَإࣲ مُّسۡتَقَرࣱّۚ وَسَوۡفَ تَعۡلَمُونَ ۝٦٧", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "لكل خبر قرار يستقر عنده، ونهاية ينتهي إليها، فيتبيَّن الحق من الباطل، وسوف تعلمون -أيها الكفار- عاقبة أمركم عند حلول عذاب الله بكم.", "isBasmala": false, "translation_en": "For every happening is a finality, and you will surely know.", "translation_id": "Untuk setiap berita (yang dibawa oleh rasul-rasul) ada (waktu) terjadinya dan kelak kamu akan mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 68, "text": "وَإِذَا رَأَیۡتَ ٱلَّذِینَ یَخُوضُونَ فِیۤ ءَایَـٰتِنَا فَأَعۡرِضۡ عَنۡهُمۡ حَتَّىٰ یَخُوضُوا۟ فِی حَدِیثٍ غَیۡرِهِۦۚ وَإِمَّا یُنسِیَنَّكَ ٱلشَّیۡطَـٰنُ فَلَا تَقۡعُدۡ بَعۡدَ ٱلذِّكۡرَىٰ مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝٦٨", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "وإذا رأيت -أيها الرسول- المشركين الذين يتكلمون في آيات القرآن بالباطل والاستهزاء، فابتعد عنهم حتى يأخذوا في حديث آخر، وإن أنساك الشيطان هذا الأمر فلا تقعد بعد تذكرك مع القوم المعتدين، الذين تكلموا في آيات الله بالباطل.", "isBasmala": false, "translation_en": "When you encounter those who gossip about Our revelations, turn away from them, until they engage in another topic. But should Satan make you forget, do not sit after the recollection with the wicked people.", "translation_id": "Dan apabila kamu melihat orang-orang memperolok-olokkan ayat-ayat Kami, maka tinggalkanlah mereka sehingga mereka membicarakan pembicaraan yang lain. Dan jika syaitan menjadikan kamu lupa (akan larangan ini), maka janganlah kamu duduk bersama orang-orang yang zalim itu sesudah teringat (akan larangan itu).", "manzil": 2, "manzil_display": ""}], "136": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 69, "text": "وَمَا عَلَى ٱلَّذِینَ یَتَّقُونَ مِنۡ حِسَابِهِم مِّن شَیۡءࣲ وَلَـٰكِن ذِكۡرَىٰ لَعَلَّهُمۡ یَتَّقُونَ ۝٦٩", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "وما على المؤمنين الذين يخافون الله تعالى، فيطيعون أوامره، ويجتنبون نواهيه من حساب الله للخائضين المستهزئين بآيات الله من شيء، ولكن عليهم أن يعظوهم ليمسكوا عن ذلك الكلام الباطل، لعلهم يتقون الله تعالى.", "isBasmala": false, "translation_en": "The righteous are in no way accountable for them; it is only a reminder, that they may be careful.", "translation_id": "Dan tidak ada pertanggungjawaban sedikitpun atas orang-orang yang bertakwa terhadap dosa mereka; akan tetapi (kewajiban mereka ialah) mengingatkan agar mereka bertakwa.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 70, "text": "وَذَرِ ٱلَّذِینَ ٱتَّخَذُوا۟ دِینَهُمۡ لَعِبࣰا وَلَهۡوࣰا وَغَرَّتۡهُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۚ وَذَكِّرۡ بِهِۦۤ أَن تُبۡسَلَ نَفۡسُۢ بِمَا كَسَبَتۡ لَیۡسَ لَهَا مِن دُونِ ٱللَّهِ وَلِیࣱّ وَلَا شَفِیعࣱ وَإِن تَعۡدِلۡ كُلَّ عَدۡلࣲ لَّا یُؤۡخَذۡ مِنۡهَاۤۗ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ أُبۡسِلُوا۟ بِمَا كَسَبُوا۟ۖ لَهُمۡ شَرَابࣱ مِّنۡ حَمِیمࣲ وَعَذَابٌ أَلِیمُۢ بِمَا كَانُوا۟ یَكۡفُرُونَ ۝٧٠", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "واترك -أيها الرسول- هؤلاء المشركين الذين جعلوا دين الإسلام لعبًا ولهوًا؛ مستهزئين بآيات الله تعالى، وغرَّتهم الحياة الدنيا بزينتها، وذكّر بالقرآن هؤلاء المشركين وغيرهم؛ كي لا ترتهن نفس بذنوبها وكفرها بربها، ليس لها غير الله ناصر ينصرها، فينقذها من عذابه، ولا شافع يشفع لها عنده، وإن تَفْتَدِ بأي فداء لا يُقْبَل منها. أولئك الذين ارتُهِنوا بذنوبهم، لهم في النار شراب شديد الحرارة وعذاب موجع؛ بسبب كفرهم بالله تعالى ورسوله محمَّد صلى الله عليه وسلم وبدين الإسلام.", "isBasmala": false, "translation_en": "So leave alone those who take their religion for play and pastime, and whom the worldly life has deceived. But remind with it, lest a soul becomes damned on account of what it has earned. It has no helper or intercessor besides God. Even if it offers every equivalent, none will be accepted from it. These are the ones who are delivered to perdition by their actions. They will have a drink of scalding water, and a painful punishment, because they used to disbelieve.", "translation_id": "Dan tinggalkan lah orang-orang yang menjadikan agama mereka sebagai main-main dan senda gurau, dan mereka telah ditipu oleh kehidupan dunia. Peringatkanlah (mereka) dengan Al-Quran itu agar masing-masing diri tidak dijerumuskan ke dalam neraka, karena perbuatannya sendiri. Tidak akan ada baginya pelindung dan tidak pula pemberi syafa'at selain daripada Allah. Dan jika ia menebus dengan segala macam tebusanpun, niscaya tidak akan diterima itu daripadanya. Mereka itulah orang-orang yang dijerumuskan ke dalam neraka. Bagi mereka (disediakan) minuman dari air yang sedang mendidih dan azab yang pedih disebabkan kekafiran mereka dahulu.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 71, "text": "قُلۡ أَنَدۡعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا یَنفَعُنَا وَلَا یَضُرُّنَا وَنُرَدُّ عَلَىٰۤ أَعۡقَابِنَا بَعۡدَ إِذۡ هَدَىٰنَا ٱللَّهُ كَٱلَّذِی ٱسۡتَهۡوَتۡهُ ٱلشَّیَـٰطِینُ فِی ٱلۡأَرۡضِ حَیۡرَانَ لَهُۥۤ أَصۡحَـٰبࣱ یَدۡعُونَهُۥۤ إِلَى ٱلۡهُدَى ٱئۡتِنَاۗ قُلۡ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلۡهُدَىٰۖ وَأُمِرۡنَا لِنُسۡلِمَ لِرَبِّ ٱلۡعَـٰلَمِینَ ۝٧١", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: أنعبد من دون الله تعالى أوثانًا لا تنفع ولا تضر؟ ونرجع إلى الكفر بعد هداية الله تعالى لنا إلى الإسلام، فنشبه -في رجوعنا إلى الكفر- مَن فسد عقله باستهواء الشياطين له، فَضَلَّ في الأرض، وله رفقة عقلاء مؤمنون يدعونه إلى الطريق الصحيح الذي هم عليه فيأبى. قل -أيها الرسول- لهؤلاء المشركين: إنَّ هدى الله الذي بعثني به هو الهدى الحق، وأُمِرنا جميعًا لنسلم لله تعالى رب العالمين بعبادته وحده لا شريك له، فهو رب كل شيء ومالكه.", "isBasmala": false, "translation_en": "Say, \"Shall we invoke besides God something that can neither benefit us nor harm us, and turn back on our heels after God has guided us; like someone seduced by the devils and confused on earth, who has friends calling him to guidance: 'Come to us'?\" Say, \"The guidance of God is the guidance, and we are commanded to surrender to the Lord of the Universe.\"", "translation_id": "Katakanlah: \"Apakah kita akan menyeru selain daripada Allah, sesuatu yang tidak dapat mendatangkan kemanfaatan kepada kita dan tidak (pula) mendatangkan kemudharatan kepada kita dan (apakah) kita akan kembali ke belakang, sesudah Allah memberi petunjuk kepada kita, seperti orang yang telah disesatkan oleh syaitan di pesawangan yang menakutkan; dalam keadaan bingung, dia mempunyai kawan-kawan yang memanggilnya kepada jalan yang lurus (dengan mengatakan): \"Marilah ikuti kami\". Katakanlah: \"Sesungguhnya petunjuk Allah itulah (yang sebenarnya) petunjuk; dan kita disuruh agar menyerahkan diri kepada Tuhan semesta alam,", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 72, "text": "وَأَنۡ أَقِیمُوا۟ ٱلصَّلَوٰةَ وَٱتَّقُوهُۚ وَهُوَ ٱلَّذِیۤ إِلَیۡهِ تُحۡشَرُونَ ۝٧٢", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "وكذلك أُمرنا بأن نقيم الصلاة كاملة، وأن نخشاه بفعل أوامره واجتناب نواهيه. وهو -جل وعلا- الذي إليه تُحْشَرُ جميع الخلائق يوم القيامة.", "isBasmala": false, "translation_en": "\"And to perform the prayers, and to revere Him; it is to Him that you will be gathered.\"", "translation_id": "dan agar mendirikan sembahyang serta bertakwa kepada-Nya\". Dan Dialah Tuhan yang kepada-Nya-lah kamu akan dihimpunkan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 73, "text": "وَهُوَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ وَیَوۡمَ یَقُولُ كُن فَیَكُونُۚ قَوۡلُهُ ٱلۡحَقُّۚ وَلَهُ ٱلۡمُلۡكُ یَوۡمَ یُنفَخُ فِی ٱلصُّورِۚ عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِۚ وَهُوَ ٱلۡحَكِیمُ ٱلۡخَبِیرُ ۝٧٣", "juz": 7, "hizb": "(*¼ ح 14*)", "tafsir": "والله سبحانه هو الذي خلق السموات والأرض بالحق، واذكر -أيها الرسول- يوم القيامة إذ يقول الله: \"كن\"، فيكون عن أمره كلمح البصر أو هو أقرب، قوله هو الحق الكامل، وله الملك سبحانه وحده، يوم ينفخ المَلَك في \"القرن\" النفخة الثانية التي تكون بها عودة الأرواح إلى الأجسام. وهو سبحانه الذي يعلم ما غاب عن حواسكم -أيها الناس - وما تشاهدونه، وهو الحكيم الذي يضع الأمور في مواضعها، الخبير بأمور خلقه. والله تعالى هو الذي يختص بهذه الأمور وغيرها بدءًا ونهاية، نشأة ومصيرًا، وهو وحده الذي يجب على العباد الانقياد لشرعه، والتسليم لحكمه، والتطلع لرضوانه ومغفرته.", "isBasmala": false, "translation_en": "It is He who created the heavens and the earth in truth. On the Day when He says: \"Be,\" it will be. His saying is the truth, and His is the sovereignty on the Day when the trumpet is blown. The Knower of secrets and declarations. He is the Wise, the Expert.", "translation_id": "Dan Dialah yang menciptakan langit dan bumi dengan benar. Dan benarlah perkataan-Nya di waktu Dia mengatakan: \"Jadilah, lalu terjadilah\", dan di tangan-Nya-lah segala kekuasaan di waktu sangkakala ditiup. Dia mengetahui yang ghaib dan yang nampak. Dan Dialah Yang Maha Bijaksana lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}], "137": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 74, "text": "۞ وَإِذۡ قَالَ إِبۡرَ ٰهِیمُ لِأَبِیهِ ءَازَرَ أَتَتَّخِذُ أَصۡنَامًا ءَالِهَةً إِنِّیۤ أَرَىٰكَ وَقَوۡمَكَ فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٧٤", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "واذكر -أيها الرسول- مُحاجَّة إبراهيم عليه السلام لأبيه آزر، إذ قال له: أتجعل من الأصنام آلهة تعبدها من دون الله تعالى؟ إني أراك وقومك في ضلال بيِّن عن طريق الحق.", "isBasmala": false, "translation_en": "Abraham said to his father Azar, \"Do you take idols for gods? I see that you and your people are in evident error.\"", "translation_id": "Dan (ingatlah) di waktu Ibrahim berkata kepada bapaknya, Aazar, \"Pantaskah kamu menjadikan berhala-berhala sebagai tuhan-tuhan? Sesungguhnya aku melihat kamu dan kaummu dalam kesesatan yang nyata\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 75, "text": "وَكَذَ ٰلِكَ نُرِیۤ إِبۡرَ ٰهِیمَ مَلَكُوتَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَلِیَكُونَ مِنَ ٱلۡمُوقِنِینَ ۝٧٥", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "وكما هدينا إبراهيم عليه السلام إلى الحق في أمر العبادة نُريه ما تحتوي عليه السموات والأرض من ملك عظيم، وقدرة باهرة، ليكون من الراسخين في الإيمان.", "isBasmala": false, "translation_en": "Thus We showed Abraham the empire of the heavens and the earth, that he might be one of those with certainty.", "translation_id": "Dan demikianlah Kami perlihatkan kepada Ibrahim tanda-tanda keagungan (Kami yang terdapat) di langit dan bumi dan (Kami memperlihatkannya) agar dia termasuk orang yang yakin.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 76, "text": "فَلَمَّا جَنَّ عَلَیۡهِ ٱلَّیۡلُ رَءَا كَوۡكَبࣰاۖ قَالَ هَـٰذَا رَبِّیۖ فَلَمَّاۤ أَفَلَ قَالَ لَاۤ أُحِبُّ ٱلۡـَٔافِلِینَ ۝٧٦", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "فلما أظلم على إبراهيم عليه السلام الليل وغطَّاه ناظر قومه؛ ليثبت لهم أن دينهم باطل، وكانوا يعبدون النجوم. رأى إبراهيم عليه السلام كوكبًا، فقال -مستدرجا قومه لإلزامهم بالتوحيد-: هذا ربي، فلما غاب الكوكب، قال: لا أحب الآلهة التي تغيب.", "isBasmala": false, "translation_en": "When the night fell over him, he saw a planet. He said, \"This is my lord.\" But when it set, he said, \"I do not love those that set.\"", "translation_id": "Ketika malam telah gelap, dia melihat sebuah bintang (lalu) dia berkata: \"Inilah Tuhanku\", tetapi tatkala bintang itu tenggelam dia berkata: \"Saya tidak suka kepada yang tenggelam\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 77, "text": "فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغࣰا قَالَ هَـٰذَا رَبِّیۖ فَلَمَّاۤ أَفَلَ قَالَ لَىِٕن لَّمۡ یَهۡدِنِی رَبِّی لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّاۤلِّینَ ۝٧٧", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "فلما رأى إبراهيم القمر طالعًا قال لقومه -على سبيل استدراج الخصم-: هذا ربي، فلما غاب، قال -مفتقرا إلى هداية ربه-: لئن لم يوفقني ربي إلى الصواب في توحيده، لأكونن من القوم الضالين عن سواء السبيل بعبادة غير الله تعالى.", "isBasmala": false, "translation_en": "Then, when he saw the moon rising, he said, \"This is my lord.\" But when it set, he said, \"If my Lord does not guide me, I will be one of the erring people.\"", "translation_id": "Kemudian tatkala dia melihat bulan terbit dia berkata: \"Inilah Tuhanku\". Tetapi setelah bulan itu terbenam, dia berkata: \"Sesungguhnya jika Tuhanku tidak memberi petunjuk kepadaku, pastilah aku termasuk orang yang sesat\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 78, "text": "فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةࣰ قَالَ هَـٰذَا رَبِّی هَـٰذَاۤ أَكۡبَرُۖ فَلَمَّاۤ أَفَلَتۡ قَالَ یَـٰقَوۡمِ إِنِّی بَرِیۤءࣱ مِّمَّا تُشۡرِكُونَ ۝٧٨", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "فلما رأى الشمس طالعة قال لقومه: هذا ربي، هذا أكبر من الكوكب والقمر، فلما غابت، قال لقومه: إني بريء مما تشركون من عبادة الأوثان والنجوم والأصنام التي تعبدونها من دون الله تعالى.", "isBasmala": false, "translation_en": "Then, when he saw the sun rising, he said, \"This is my lord, this is bigger.\" But when it set, he said, \"O my people, I am innocent of your idolatry.", "translation_id": "Kemudian tatkala ia melihat matahari terbit, dia berkata: \"Inilah Tuhanku, ini yang lebih besar\". Maka tatkala matahari itu terbenam, dia berkata: \"Hai kaumku, sesungguhnya aku berlepas diri dari apa yang kamu persekutukan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 79, "text": "إِنِّی وَجَّهۡتُ وَجۡهِیَ لِلَّذِی فَطَرَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ حَنِیفࣰاۖ وَمَاۤ أَنَا۠ مِنَ ٱلۡمُشۡرِكِینَ ۝٧٩", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "إني توجَّهت بوجهي في العبادة لله عز وجل وحده، فهو الذي خلق السموات والأرض، مائلا عن الشرك إلى التوحيد، وما أنا من المشركين مع الله غيره.", "isBasmala": false, "translation_en": "I have directed my attention towards Him Who created the heavens and the earth-a monotheist-and I am not of the idolaters.\"", "translation_id": "Sesungguhnya aku menghadapkan diriku kepada Rabb yang menciptakan langit dan bumi, dengan cenderung kepada agama yang benar, dan aku bukanlah termasuk orang-orang yang mempersekutukan Tuhan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 80, "text": "وَحَاۤجَّهُۥ قَوۡمُهُۥۚ قَالَ أَتُحَـٰۤجُّوۤنِّی فِی ٱللَّهِ وَقَدۡ هَدَىٰنِۚ وَلَاۤ أَخَافُ مَا تُشۡرِكُونَ بِهِۦۤ إِلَّاۤ أَن یَشَاۤءَ رَبِّی شَیۡـࣰٔاۚ وَسِعَ رَبِّی كُلَّ شَیۡءٍ عِلۡمًاۚ أَفَلَا تَتَذَكَّرُونَ ۝٨٠", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "وجادله قومه في توحيد الله تعالى قال: أتجادلونني في توحيدي لله بالعبادة، وقد وفقني إلى معرفة وحدانيته، فإن كنتم تخوفونني بآلهتكم أن توقع بي ضررًا فإنني لا أرهبها فلن تضرني، إلا أن يشاء ربي شيئًا. وسع ربي كل شيء علمًا. أفلا تتذكرون فتعلموا أنه وحده المعبود المستحق للعبودية؟", "isBasmala": false, "translation_en": "And his people argued with him. He said, \"Do you argue with me about God, when He has guided me? I do not fear what you associate with Him, unless my Lord wills it. My Lord comprehends all things in knowledge. Will you not reconsider?", "translation_id": "Dan dia dibantah oleh kaumnya. Dia berkata: \"Apakah kamu hendak membantah tentang Allah, padahal sesungguhnya Allah telah memberi petunjuk kepadaku\". Dan aku tidak takut kepada (malapetaka dari) sembahan-sembahan yang kamu persekutukan dengan Allah, kecuali di kala Tuhanku menghendaki sesuatu (dari malapetaka) itu. Pengetahuan Tuhanku meliputi segala sesuatu. Maka apakah kamu tidak dapat mengambil pelajaran (daripadanya)?\"", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 81, "text": "وَكَیۡفَ أَخَافُ مَاۤ أَشۡرَكۡتُمۡ وَلَا تَخَافُونَ أَنَّكُمۡ أَشۡرَكۡتُم بِٱللَّهِ مَا لَمۡ یُنَزِّلۡ بِهِۦ عَلَیۡكُمۡ سُلۡطَـٰنࣰاۚ فَأَیُّ ٱلۡفَرِیقَیۡنِ أَحَقُّ بِٱلۡأَمۡنِۖ إِن كُنتُمۡ تَعۡلَمُونَ ۝٨١", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "وكيف أخاف أوثانكم وأنتم لا تخافون ربي الذي خلقكم، وخلق أوثانكم التي أشركتموها معه في العبادة، من غير حجة لكم على ذلك؟ فأي الفريقين: فريق المشركين وفريق الموحدين أحق بالطمأنينة والسلامة والأمن من عذاب الله؟ إن كنتم تعلمون صدق ما أقول فأخبروني.", "isBasmala": false, "translation_en": "And why should I fear those you associate with Him, and you do not fear associating others with God for which He sent down to you no authority? Which side is more entitled to security, if you are aware?\"", "translation_id": "Bagaimana aku takut kepada sembahan-sembahan yang kamu persekutukan (dengan Allah), padahal kamu tidak mempersekutukan Allah dengan sembahan-sembahan yang Allah sendiri tidak menurunkan hujjah kepadamu untuk mempersekutukan-Nya. Maka manakah di antara dua golongan itu yang lebih berhak memperoleh keamanan (dari malapetaka), jika kamu mengetahui?", "manzil": 2, "manzil_display": ""}], "138": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 82, "text": "ٱلَّذِینَ ءَامَنُوا۟ وَلَمۡ یَلۡبِسُوۤا۟ إِیمَـٰنَهُم بِظُلۡمٍ أُو۟لَـٰۤىِٕكَ لَهُمُ ٱلۡأَمۡنُ وَهُم مُّهۡتَدُونَ ۝٨٢", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "الذين صدَّقوا الله ورسوله وعملوا بشرعه ولم يخلطوا إيمانهم بشرك، أولئك لهم الطمأنينة والسلامة، وهم الموفقون إلى طريق الحق.", "isBasmala": false, "translation_en": "Those who believe, and do not obscure their faith with wrongdoing-those will have security, and they are guided.", "translation_id": "Orang-orang yang beriman dan tidak mencampuradukkan iman mereka dengan kezaliman (syirik), mereka itulah yang mendapat keamanan dan mereka itu adalah orang-orang yang mendapat petunjuk.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 83, "text": "وَتِلۡكَ حُجَّتُنَاۤ ءَاتَیۡنَـٰهَاۤ إِبۡرَ ٰهِیمَ عَلَىٰ قَوۡمِهِۦۚ نَرۡفَعُ دَرَجَـٰتࣲ مَّن نَّشَاۤءُۗ إِنَّ رَبَّكَ حَكِیمٌ عَلِیمࣱ ۝٨٣", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "وتلك الحجة التي حاجَّ بها إبراهيم عليه السلام قومه هي حجتنا التي وفقناه إليها حتى انقطعت حجتهم. نرفع مَن نشاء من عبادنا مراتب في الدنيا والآخرة. إن ربك حكيم في تدبير خلقه، عليم بهم.", "isBasmala": false, "translation_en": "That was Our argument which We gave to Abraham against his people. We elevate by degrees whomever We will. Your Lord is Wise and Informed.", "translation_id": "Dan itulah hujjah Kami yang Kami berikan kepada Ibrahim untuk menghadapi kaumnya. Kami tinggikan siapa yang Kami kehendaki beberapa derajat. Sesungguhnya Tuhanmu Maha Bijaksana lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 84, "text": "وَوَهَبۡنَا لَهُۥۤ إِسۡحَـٰقَ وَیَعۡقُوبَۚ كُلًّا هَدَیۡنَاۚ وَنُوحًا هَدَیۡنَا مِن قَبۡلُۖ وَمِن ذُرِّیَّتِهِۦ دَاوُۥدَ وَسُلَیۡمَـٰنَ وَأَیُّوبَ وَیُوسُفَ وَمُوسَىٰ وَهَـٰرُونَۚ وَكَذَ ٰلِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ ۝٨٤", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "ومننَّا على إبراهيم عليه السلام بأن رزقناه إسحاق ابنًا ويعقوب حفيدًا، ووفَّقنا كلا منهما لسبيل الرشاد، وكذلك وفَّقنا للحق نوحًا -من قبل إبراهيم وإسحاق ويعقوب- وكذلك وفَّقنا للحق من ذرية نوح داود وسليمان وأيوب ويوسف وموسى وهارون عليهم السلام، وكما جزينا هؤلاء الأنبياء لإحسانهم نجزي كل محسن.", "isBasmala": false, "translation_en": "And We gave him Isaac and Jacob-each of them We guided. And We guided Noah previously; and from his descendants David, and Solomon, and Job, and Joseph, and Moses, and Aaron. Thus We reward the righteous.", "translation_id": "Dan Kami telah menganugerahkan Ishak dan Ya'qub kepadanya. Kepada keduanya masing-masing telah Kami beri petunjuk; dan kepada Nuh sebelum itu (juga) telah Kami beri petunjuk, dan kepada sebahagian dari keturunannya (Nuh) yaitu Daud, Sulaiman, Ayyub, Yusuf, Musa dan Harun. Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 85, "text": "وَزَكَرِیَّا وَیَحۡیَىٰ وَعِیسَىٰ وَإِلۡیَاسَۖ كُلࣱّ مِّنَ ٱلصَّـٰلِحِینَ ۝٨٥", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "وكذلك هدينا زكريا ويحيى وعيسى وإلياس، وكل هؤلاء الأنبياء عليهم السلام من الصالحين.", "isBasmala": false, "translation_en": "And Zechariah, and John, and Jesus, and Elias-every one of them was of the upright.", "translation_id": "dan Zakaria, Yahya, Isa dan Ilyas. Semuanya termasuk orang-orang yang shaleh.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 86, "text": "وَإِسۡمَـٰعِیلَ وَٱلۡیَسَعَ وَیُونُسَ وَلُوطࣰاۚ وَكُلࣰّا فَضَّلۡنَا عَلَى ٱلۡعَـٰلَمِینَ ۝٨٦", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "وهدينا كذلك إسماعيل واليسع ويونس ولوطا، وكل هؤلاء الرسل فضَّلناهم على أهل زمانهم.", "isBasmala": false, "translation_en": "And Ishmael, and Elijah, and Jonah, and Lot-We favored each one of them over all other people.", "translation_id": "dan Ismail, Alyasa', Yunus dan Luth. Masing-masing Kami lebihkan derajatnya di atas umat (di masanya),", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 87, "text": "وَمِنۡ ءَابَاۤىِٕهِمۡ وَذُرِّیَّـٰتِهِمۡ وَإِخۡوَ ٰنِهِمۡۖ وَٱجۡتَبَیۡنَـٰهُمۡ وَهَدَیۡنَـٰهُمۡ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٨٧", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "وكذلك وفَّقنا للحق من شئنا هدايته من آباء هؤلاء وذرياتهم وإخوانهم، واخترناهم لديننا وإبلاغ رسالتنا إلى مَن أرسلناهم إليهم، وأرشدناهم إلى طريق صحيح، لا عوج فيه، وهو توحيد الله تعالى وتنزيهه عن الشرك.", "isBasmala": false, "translation_en": "And of their ancestors, and their descendants, and their siblings-We chose them, and guided them to a straight path.", "translation_id": "Dan Kami lebihkan (pula) derajat sebahagian dari bapak-bapak mereka, keturunan dan saudara-saudara mereka. Dan Kami telah memilih mereka (untuk menjadi nabi-nabi dan rasul-rasul) dan Kami menunjuki mereka ke jalan yang lurus.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 88, "text": "ذَ ٰلِكَ هُدَى ٱللَّهِ یَهۡدِی بِهِۦ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۚ وَلَوۡ أَشۡرَكُوا۟ لَحَبِطَ عَنۡهُم مَّا كَانُوا۟ یَعۡمَلُونَ ۝٨٨", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "ذلك الهدى هو توفيق الله، الذي يوفق به من يشاء من عباده. ولو أن هؤلاء الأنبياء أشركوا بالله -على سبيل الفرض والتقدير- لبطل عملهم؛ لأن الله تعالى لا يقبل مع الشرك عملا.", "isBasmala": false, "translation_en": "Such is God's guidance. He guides with it whomever He wills of His servants. Had they associated, their deeds would have gone in vain.", "translation_id": "Itulah petunjuk Allah, yang dengannya Dia memberi petunjuk kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya. Seandainya mereka mempersekutukan Allah, niscaya lenyaplah dari mereka amalan yang telah mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 89, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن یَكۡفُرۡ بِهَا هَـٰۤؤُلَاۤءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمࣰا لَّیۡسُوا۟ بِهَا بِكَـٰفِرِینَ ۝٨٩", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "أولئك الأنبياء الذين أنعمنا عليهم بالهداية والنبوة هم الذين آتيناهم الكتاب كصحف إبراهيم وتوراة موسى وزبور داود وإنجيل عيسى، وآتيناهم فَهْمَ هذه الكتب، واخترناهم لإبلاغ وحينا، فإن يجحد -أيها الرسول- بآيات هذا القرآن الكفارُ من قومك، فقد وكلنا بها قومًا آخرين -أي: المهاجرين والأنصار وأتباعهم إلى يوم القيامة- ليسوا بها بكافرين، بل مؤمنون بها، عاملون بما تدل عليه.", "isBasmala": false, "translation_en": "Those are they to whom We gave the Book, and wisdom, and prophethood. If these reject them, We have entrusted them to others who do not reject them.", "translation_id": "Mereka itulah orang-orang yang telah Kami berikan kitab, hikmat dan kenabian Jika orang-orang (Quraisy) itu mengingkarinya, maka sesungguhnya Kami akan menyerahkannya kepada kaum yang sekali-kali tidak akan mengingkarinya.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 90, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡۗ قُل لَّاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ أَجۡرًاۖ إِنۡ هُوَ إِلَّا ذِكۡرَىٰ لِلۡعَـٰلَمِینَ ۝٩٠", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "أولئك الأنبياء المذكورون هم الذين وفقهم الله تعالى لدينه الحق، فاتبع هداهم -أيها الرسول- واسلك سبيلهم. قل للمشركين: لا أطلب منكم على تبليغ الإسلام عوضًا من الدنيا، إنْ أجري إلا على الله، وما الإسلام إلا دعوة جميع الناس إلى الطريق المستقيم وتذكير لكم ولكل مَن كان مثلكم، ممن هو مقيم على باطل، لعلكم تتذكرون به ما ينفعكم.", "isBasmala": false, "translation_en": "Those are they whom God has guided, so follow their guidance. Say, \"I ask of you no compensation for it; it is just a reminder for all mankind.\"", "translation_id": "Mereka itulah orang-orang yang telah diberi petunjuk oleh Allah, maka ikutilah petunjuk mereka. Katakanlah: \"Aku tidak meminta upah kepadamu dalam menyampaikan (Al-Quran)\". Al-Quran itu tidak lain hanyalah peringatan untuk seluruh ummat.", "manzil": 2, "manzil_display": ""}], "139": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 91, "text": "وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدۡرِهِۦۤ إِذۡ قَالُوا۟ مَاۤ أَنزَلَ ٱللَّهُ عَلَىٰ بَشَرࣲ مِّن شَیۡءࣲۗ قُلۡ مَنۡ أَنزَلَ ٱلۡكِتَـٰبَ ٱلَّذِی جَاۤءَ بِهِۦ مُوسَىٰ نُورࣰا وَهُدࣰى لِّلنَّاسِۖ تَجۡعَلُونَهُۥ قَرَاطِیسَ تُبۡدُونَهَا وَتُخۡفُونَ كَثِیرࣰاۖ وَعُلِّمۡتُم مَّا لَمۡ تَعۡلَمُوۤا۟ أَنتُمۡ وَلَاۤ ءَابَاۤؤُكُمۡۖ قُلِ ٱللَّهُۖ ثُمَّ ذَرۡهُمۡ فِی خَوۡضِهِمۡ یَلۡعَبُونَ ۝٩١", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "وما عَظَّم هؤلاء المشركون الله حق تعظيمه؛ إذ أنكروا أن يكون الله تعالى قد أنزل على أحد من البشر شيئًا من وحيه. قل لهم -أيها الرسول-: إذا كان الأمر كما تزعمون، فمن الذي أنزل الكتاب الذي جاء به موسى إلى قومه نورًا للناس وهداية لهم؟ ثم توجه الخطاب إلى اليهود زَجْرًا لهم بقوله: تجعلون هذا الكتاب في قراطيس متفرقة، تظهرون بعضها، وتكتمون كثيرًا منها، ومما كتموه الإخبار عن صفة محمد صلى الله عليه وسلم ونبوته، وعلَّمكم الله معشر العرب بالقرآنِ -الذي أنزله عليكم، فيه خبر مَن قبلكم ومَن بعدكم، وما يكون بعد موتكم- ما لم تعلموه أنتم ولا آباؤكم، قل: الله هو الذي أنزله، ثم دع هؤلاء في حديثهم الباطل يخوضون ويلعبون.", "isBasmala": false, "translation_en": "They do not value God as He should be valued, when they say, \"God did not reveal anything to any human being.\" Say, \"Who revealed the Scripture which Moses brought-a light and guidance for humanity?\" You put it on scrolls, displaying them, yet concealing much. And you were taught what you did not know-neither you, nor your ancestors. Say, \"God;\" then leave them toying away in their speculation.", "translation_id": "Dan mereka tidak menghormati Allah dengan penghormatan yang semestinya, di kala mereka berkata: \"Allah tidak menurunkan sesuatupun kepada manusia\". Katakanlah: \"Siapakah yang menurunkan kitab (Taurat) yang dibawa oleh Musa sebagai cahaya dan petunjuk bagi manusia, kamu jadikan kitab itu lembaran-lembaran kertas yang bercerai-berai, kamu perlihatkan (sebahagiannya) dan kamu sembunyikan sebahagian besarnya, padahal telah diajarkan kepadamu apa yang kamu dan bapak-bapak kamu tidak mengetahui(nya)?\" Katakanlah: \"Allah-lah (yang menurunkannya)\", kemudian (sesudah kamu menyampaikan Al Quran kepada mereka), biarkanlah mereka bermain-main dalam kesesatannya.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 92, "text": "وَهَـٰذَا كِتَـٰبٌ أَنزَلۡنَـٰهُ مُبَارَكࣱ مُّصَدِّقُ ٱلَّذِی بَیۡنَ یَدَیۡهِ وَلِتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَاۚ وَٱلَّذِینَ یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ یُؤۡمِنُونَ بِهِۦۖ وَهُمۡ عَلَىٰ صَلَاتِهِمۡ یُحَافِظُونَ ۝٩٢", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "وهذا القرآن كتاب أنزلناه إليك -أيها الرسول- عظيم النفع، مصدق لما تقدمه من الكتب السماوية، أنزلناه لنخوِّف به من عذاب الله وبأسه أهل \"مكة\" ومن حولها من أهل أقطار الأرض كلها. والذين يصدقون بالحياة الآخرة، يصدقون بأن القرآن كلام الله، ويحافظون على إقام الصلاة في أوقاتها.", "isBasmala": false, "translation_en": "This too is a Scripture that We revealed-blessed-verifying what preceded it, that you may warn the Mother of Cities and all around it. Those who believe in the Hereafter believe in it, and are dedicated to their prayers.", "translation_id": "Dan ini (Al Quran) adalah kitab yang telah Kami turunkan yang diberkahi; membenarkan kitab-kitab yang (diturunkan) sebelumnya dan agar kamu memberi peringatan kepada (penduduk) Ummul Qura (Mekah) dan orang-orang yang di luar lingkungannya. Orang-orang yang beriman kepada adanya kehidupan akhirat tentu beriman kepadanya (Al Quran) dan mereka selalu memelihara sembahyangnya.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 93, "text": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ قَالَ أُوحِیَ إِلَیَّ وَلَمۡ یُوحَ إِلَیۡهِ شَیۡءࣱ وَمَن قَالَ سَأُنزِلُ مِثۡلَ مَاۤ أَنزَلَ ٱللَّهُۗ وَلَوۡ تَرَىٰۤ إِذِ ٱلظَّـٰلِمُونَ فِی غَمَرَ ٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَـٰۤىِٕكَةُ بَاسِطُوۤا۟ أَیۡدِیهِمۡ أَخۡرِجُوۤا۟ أَنفُسَكُمُۖ ٱلۡیَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَقُولُونَ عَلَى ٱللَّهِ غَیۡرَ ٱلۡحَقِّ وَكُنتُمۡ عَنۡ ءَایَـٰتِهِۦ تَسۡتَكۡبِرُونَ ۝٩٣", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "ومَن أشدُّ ظلمَّا ممَّن اختلق على الله تعالى قولا كذبًا، فادعى أنه لم يبعث رسولا من البشر، أو ادعى كذبًا أن الله أوحى إليه ولم يُوحِ إليه شيئًا، أو ادَّعى أنه قادر على أن يُنْزل مثل ما أنزل الله من القرآن؟ ولو أنك أبصرت -أيها الرسول- هؤلاء المتجاوزين الحدَّ وهم في أهوال الموت لرأيت أمرًا هائلا والملائكة الذين يقبضون أرواحهم باسطو أيديهم بالعذاب قائلين لهم: أخرجوا أنفسكم، اليوم تهانون غاية الإهانة، كما كنتم تكذبون على الله، وتستكبرون عن اتباع آياته والانقياد لرسله.", "isBasmala": false, "translation_en": "Who does greater wrong than someone who invents falsehood against God, or says, \"It was revealed to me,\" when nothing was revealed to him, or says, \"I will reveal the like of what God revealed\"? If only you could see the wrongdoers in the floods of death, as the angels with arms outstretched: \"Give up your souls. Today you are being repaid with the torment of shame for having said about God other than the truth, and for being too proud to accept His revelations.\"", "translation_id": "Dan siapakah yang lebih zalim daripada orang yang membuat kedustaan terhadap Allah atau yang berkata: \"Telah diwahyukan kepada saya\", padahal tidak ada diwahyukan sesuatupun kepadanya, dan orang yang berkata: \"Saya akan menurunkan seperti apa yang diturunkan Allah\". Alangkah dahsyatnya sekiranya kamu melihat di waktu orang-orang yang zalim berada dalam tekanan sakratul maut, sedang para malaikat memukul dengan tangannya, (sambil berkata): \"Keluarkanlah nyawamu\" Di hari ini kamu dibalas dengan siksa yang sangat menghinakan, karena kamu selalu mengatakan terhadap Allah (perkataan) yang tidak benar dan (karena) kamu selalu menyombongkan diri terhadap ayat-ayat-Nya.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 94, "text": "وَلَقَدۡ جِئۡتُمُونَا فُرَ ٰدَىٰ كَمَا خَلَقۡنَـٰكُمۡ أَوَّلَ مَرَّةࣲ وَتَرَكۡتُم مَّا خَوَّلۡنَـٰكُمۡ وَرَاۤءَ ظُهُورِكُمۡۖ وَمَا نَرَىٰ مَعَكُمۡ شُفَعَاۤءَكُمُ ٱلَّذِینَ زَعَمۡتُمۡ أَنَّهُمۡ فِیكُمۡ شُرَكَـٰۤؤُا۟ۚ لَقَد تَّقَطَّعَ بَیۡنَكُمۡ وَضَلَّ عَنكُم مَّا كُنتُمۡ تَزۡعُمُونَ ۝٩٤", "juz": 7, "hizb": "(*½ ح 14*)", "tafsir": "ولقد جئتمونا للحساب والجزاء فرادى كما أوجدناكم في الدنيا أول مرة حفاة عراة، وتركتم وراء ظهوركم ما مكنَّاكم فيه مما تتباهون به من أموال في الدنيا، وما نرى معكم في الآخرة أوثانكم التي كنتم تعتقدون أنها تشفع لكم، وتَدَّعون أنها شركاء مع الله في العبادة، لقد زال تَواصُلُكم الذي كان بينكم في الدنيا، وذهب عنكم ما كنتم تَدَّعون من أن آلهتكم شركاء لله في العبادة، وظهر أنكم الخاسرون لأنفسكم وأهليكم وأموالكم.", "isBasmala": false, "translation_en": "\"You have come to Us individually, just as We created you the first time, leaving behind you everything We gave you. We do not see with you your intercessors-those you claimed were your partners. The link between you is cut, and what you had asserted has failed you.\"", "translation_id": "Dan sesungguhnya kamu datang kepada Kami sendiri-sendiri sebagaimana kamu Kami ciptakan pada mulanya, dan kamu tinggalkan di belakangmu (di dunia) apa yang telah Kami karuniakan kepadamu; dan Kami tiada melihat besertamu pemberi syafa'at yang kamu anggap bahwa mereka itu sekutu-sekutu Tuhan di antara kamu. Sungguh telah terputuslah (pertalian) antara kamu dan telah lenyap daripada kamu apa yang dahulu kamu anggap (sebagai sekutu Allah).", "manzil": 2, "manzil_display": ""}], "140": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 95, "text": "۞ إِنَّ ٱللَّهَ فَالِقُ ٱلۡحَبِّ وَٱلنَّوَىٰۖ یُخۡرِجُ ٱلۡحَیَّ مِنَ ٱلۡمَیِّتِ وَمُخۡرِجُ ٱلۡمَیِّتِ مِنَ ٱلۡحَیِّۚ ذَ ٰلِكُمُ ٱللَّهُۖ فَأَنَّىٰ تُؤۡفَكُونَ ۝٩٥", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "إن الله تعالى يشق الحب، فيخرج منه الزرع، ويشق النوى، فيخرج منه الشجر، يخرج الحي من الميت كالإنسان والحيوان مثلا من النطفة، ويخرج الميت من الحي كالنطفة من الإنسان والحيوان، ذلكم الله أي: فاعل هذا هو الله وحده لا شريك له المستحق للعبادة، فكيف تُصْرَفون عن الحق إلى الباطل فتعبدون معه غيره؟", "isBasmala": false, "translation_en": "It is God Who splits the grain and the seed. He brings the living from the dead, and He brings the dead from the living. Such is God. So how could you deviate?", "translation_id": "Sesungguhnya Allah menumbuhkan butir tumbuh-tumbuhan dan biji buah-buahan. Dia mengeluarkan yang hidup dari yang mati dan mengeluarkan yang mati dari yang hidup. (Yang memiliki sifat-sifat) demikian ialah Allah, maka mengapa kamu masih berpaling?", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 96, "text": "فَالِقُ ٱلۡإِصۡبَاحِ وَجَعَلَ ٱلَّیۡلَ سَكَنࣰا وَٱلشَّمۡسَ وَٱلۡقَمَرَ حُسۡبَانࣰاۚ ذَ ٰلِكَ تَقۡدِیرُ ٱلۡعَزِیزِ ٱلۡعَلِیمِ ۝٩٦", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "والله سبحانه وتعالى هو الذي شق ضياء الصباح من ظلام الليل، وجعل الليل مستقرًا، يسكن فيه كل متحرك ويهدأ، وجعل الشمس والقمر يجريان في فلكيهما بحساب متقن مقدَّر، لا يتغير ولا يضطرب، ذلك تقدير العزيز الذي عزَّ سلطانه، العليم بمصالح خلقه وتدبير شئونهم. والعزيز والعليم من أسماء الله الحسنى يدلان على كمال العز والعلم.", "isBasmala": false, "translation_en": "It is He Who breaks the dawn. And He made the night for rest, and the sun and the moon for calculation. Such is the disposition of the Almighty, the All-Knowing.", "translation_id": "Dia menyingsingkan pagi dan menjadikan malam untuk beristirahat, dan (menjadikan) matahari dan bulan untuk perhitungan. Itulah ketentuan Allah Yang Maha Perkasa lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 97, "text": "وَهُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلنُّجُومَ لِتَهۡتَدُوا۟ بِهَا فِی ظُلُمَـٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِۗ قَدۡ فَصَّلۡنَا ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡلَمُونَ ۝٩٧", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "والله سبحانه هو الذي جعل لكم أيها الناس النجوم علامات، تعرفون بها الطرق ليلا إذا ضللتم بسبب الظلمة الشديدة في البر والبحر، قد بيَّنَّا البراهين الواضحة؛ ليتدبرها منكم أولو العلم بالله وشرعه.", "isBasmala": false, "translation_en": "And it is He Who created the stars for you, that you may be guided by them in the darkness of land and sea. We thus explain the revelations for people who know.", "translation_id": "Dan Dialah yang menjadikan bintang-bintang bagimu, agar kamu menjadikannya petunjuk dalam kegelapan di darat dan di laut. Sesungguhnya Kami telah menjelaskan tanda-tanda kebesaran (Kami) kepada orang-orang yang mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 98, "text": "وَهُوَ ٱلَّذِیۤ أَنشَأَكُم مِّن نَّفۡسࣲ وَ ٰحِدَةࣲ فَمُسۡتَقَرࣱّ وَمُسۡتَوۡدَعࣱۗ قَدۡ فَصَّلۡنَا ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَفۡقَهُونَ ۝٩٨", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "والله سبحانه هو الذي ابتدأ خلقكم أيها الناس من آدم عليه السلام؛ إذ خلقه من طين، ثم كنتم سلالة ونسلا منه، فجعل لكم مستقَرًا تستقرون فيه، وهو أرحام النساء، ومُستودعًا تُحفَظُون فيه، وهو أصلاب الرجال، قد بينا الحجج وميزنا الأدلة، وأحكمناها لقوم يفهمون مواقع الحجج ومواضع العبر.", "isBasmala": false, "translation_en": "And it is He who produced you from a single person, then a repository, then a depository. We have detailed the revelations for people who understand.", "translation_id": "Dan Dialah yang menciptakan kamu dari seorang diri, maka (bagimu) ada tempat tetap dan tempat simpanan. Sesungguhnya telah Kami jelaskan tanda-tanda kebesaran Kami kepada orang-orang yang mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 99, "text": "وَهُوَ ٱلَّذِیۤ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجۡنَا بِهِۦ نَبَاتَ كُلِّ شَیۡءࣲ فَأَخۡرَجۡنَا مِنۡهُ خَضِرࣰا نُّخۡرِجُ مِنۡهُ حَبࣰّا مُّتَرَاكِبࣰا وَمِنَ ٱلنَّخۡلِ مِن طَلۡعِهَا قِنۡوَانࣱ دَانِیَةࣱ وَجَنَّـٰتࣲ مِّنۡ أَعۡنَابࣲ وَٱلزَّیۡتُونَ وَٱلرُّمَّانَ مُشۡتَبِهࣰا وَغَیۡرَ مُتَشَـٰبِهٍۗ ٱنظُرُوۤا۟ إِلَىٰ ثَمَرِهِۦۤ إِذَاۤ أَثۡمَرَ وَیَنۡعِهِۦۤۚ إِنَّ فِی ذَ ٰلِكُمۡ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝٩٩", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "والله سبحانه هو الذي أنزل من السحاب مطرًا فأخرج به نبات كل شيء، فأخرج من النبات زرعًا وشجرًا أخضر، ثم أخرج من الزرع حَبًّا يركب بعضه بعضًا، كسنابل القمح والشعير والأرز، وأخرج من طلع النخل -وهو ما تنشأ فيه عذوق الرطب- عذوقًا قريبة التناول، وأخرج سبحانه بساتين من أعناب، وأخرج شجر الزيتون والرمان الذي يتشابه في ورقه ويختلف في ثمره شكلا وطعمًا وطبعًا. انظروا أيها الناس إلى ثمر هذا النبات إذا أثمر، وإلى نضجه وبلوغه حين يبلغ. إن في ذلكم - أيها الناس - لدلالات على كمال قدرة خالق هذه الأشياء وحكمته ورحمته لقوم يصدقون به تعالى ويعملون بشرعه.", "isBasmala": false, "translation_en": "And it is He who sends down water from the sky. With it We produce vegetation of all kinds, from which We bring greenery, from which We produce grains in clusters. And palm-trees with hanging clusters, and vineyards, and olives, and pomegranates-similar and dissimilar. Watch their fruits as they grow and ripen. Surely in this are signs for people who believe.", "translation_id": "Dan Dialah yang menurunkan air hujan dari langit, lalu Kami tumbuhkan dengan air itu segala macam tumbuh-tumbuhan maka Kami keluarkan dari tumbuh-tumbuhan itu tanaman yang menghijau. Kami keluarkan dari tanaman yang menghijau itu butir yang banyak; dan dari mayang korma mengurai tangkai-tangkai yang menjulai, dan kebun-kebun anggur, dan (Kami keluarkan pula) zaitun dan delima yang serupa dan yang tidak serupa. Perhatikanlah buahnya di waktu pohonnya berbuah dan (perhatikan pulalah) kematangannya. Sesungguhnya pada yang demikian itu ada tanda-tanda (kekuasaan Allah) bagi orang-orang yang beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 100, "text": "وَجَعَلُوا۟ لِلَّهِ شُرَكَاۤءَ ٱلۡجِنَّ وَخَلَقَهُمۡۖ وَخَرَقُوا۟ لَهُۥ بَنِینَ وَبَنَـٰتِۭ بِغَیۡرِ عِلۡمࣲۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یَصِفُونَ ۝١٠٠", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "وجعل هؤلاء المشركون الجن شركاء لله تعالى في العبادة؛ اعتقادًا منهم أنهم ينفعون أو يضرون، وقد خلقهم الله تعالى وما يعبدون من العدم، فهو المستقل بالخلق وحده، فيجب أن يستقل بالعبادة وحده لا شريك له. ولقد كذب هؤلاء المشركون على الله تعالى حين نسبوا إليه البنين والبنات؛ جهلا منهم بما يجب له من صفات الكمال، تنزَّه وعلا عما نسبه إليه المشركون من ذلك الكذب والافتراء.", "isBasmala": false, "translation_en": "Yet they attributed to God partners-the sprites-although He created them. And they invented for Him sons and daughters, without any knowledge. Glory be to Him. He is exalted, beyond what they describe.", "translation_id": "Dan mereka (orang-orang musyrik) menjadikan jin itu sekutu bagi Allah, padahal Allah-lah yang menciptakan jin-jin itu, dan mereka membohong (dengan mengatakan): \"Bahwasanya Allah mempunyai anak laki-laki dan perempuan\", tanpa (berdasar) ilmu pengetahuan. Maha Suci Allah dan Maha Tinggi dari sifat-sifat yang mereka berikan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 101, "text": "بَدِیعُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ یَكُونُ لَهُۥ وَلَدࣱ وَلَمۡ تَكُن لَّهُۥ صَـٰحِبَةࣱۖ وَخَلَقَ كُلَّ شَیۡءࣲۖ وَهُوَ بِكُلِّ شَیۡءٍ عَلِیمࣱ ۝١٠١", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "والله تعالى هو الذي أوجد السموات والأرض وما فيهن على غير مثال سابق. كيف يكون له ولد ولم تكن له صاحبة؟ تعالى الله عما يقول المشركون علوًّا كبيرًا، وهو الذي خلق كل شيء من العدم، ولا يخفى عليه شيء من أمور الخلق.", "isBasmala": false, "translation_en": "Originator of the heavens and the earth-how can He have a son when He never had a companion? He created all things, and He has knowledge of all things.", "translation_id": "Dia Pencipta langit dan bumi. Bagaimana Dia mempunyai anak padahal Dia tidak mempunyai isteri. Dia menciptakan segala sesuatu; dan Dia mengetahui segala sesuatu.", "manzil": 2, "manzil_display": ""}], "141": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 102, "text": "ذَ ٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ خَـٰلِقُ كُلِّ شَیۡءࣲ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ وَكِیلࣱ ۝١٠٢", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "ذلكم -أيها المشركون- هو ربكم جل وعلا لا معبود بحق سواه، خالق كل شيء فانقادوا واخضعوا له بالطاعة والعبادة. وهو سبحانه على كل شيء وكيل وحفيظ، يدبر أمور خلقه.", "isBasmala": false, "translation_en": "Such is God, your Lord. There is no god except He, the Creator of all things; so worship Him. He is responsible for everything.", "translation_id": "(Yang memiliki sifat-sifat yang) demikian itu ialah Allah Tuhan kamu; tidak ada Tuhan selain Dia; Pencipta segala sesuatu, maka sembahlah Dia; dan Dia adalah Pemelihara segala sesuatu.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 103, "text": "لَّا تُدۡرِكُهُ ٱلۡأَبۡصَـٰرُ وَهُوَ یُدۡرِكُ ٱلۡأَبۡصَـٰرَۖ وَهُوَ ٱللَّطِیفُ ٱلۡخَبِیرُ ۝١٠٣", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "لا ترى اللهَ الأبصارُ في الدنيا، أما في الدار الآخرة فإن المؤمنين يرون ربهم بغير إحاطة، وهو سبحانه يدرك الأبصار ويحيط بها، ويعلمها على ما هي عليه، وهو اللطيف بأوليائه الذي يعلم دقائق الأشياء، الخبير الذي يعلم بواطنها.", "isBasmala": false, "translation_en": "No vision can grasp Him, but His grasp is over all vision. He is the Subtle, the Expert.", "translation_id": "Dia tidak dapat dicapai oleh penglihatan mata, sedang Dia dapat melihat segala yang kelihatan; dan Dialah Yang Maha Halus lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 104, "text": "قَدۡ جَاۤءَكُم بَصَاۤىِٕرُ مِن رَّبِّكُمۡۖ فَمَنۡ أَبۡصَرَ فَلِنَفۡسِهِۦۖ وَمَنۡ عَمِیَ فَعَلَیۡهَاۚ وَمَاۤ أَنَا۠ عَلَیۡكُم بِحَفِیظࣲ ۝١٠٤", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: قد جاءتكم براهين ظاهرة تبصرون بها الهدى من الضلال، مما اشتمل عليها القرآن، وجاء بها الرسول عليه الصلاة والسلام، فمَن تبيَّن هذه البراهين وآمن بمدلولها فنَفْعُ ذلك لنفسه، ومَن لم يبصر الهدى بعد ظهور الحجة عليه فعلى نفسه جنى، وما أنا عليكم بحافظ أحصي أعمالكم، وإنما أنا مبلغ، والله يهدي مَن يشاء ويضل مَن يشاء وَفْق علمه وحكمته.", "isBasmala": false, "translation_en": "\"Insights have come to you from your Lord. Whoever sees, it is to the benefit of his soul; and whoever remains blind, it is to its detriment. I am not a guardian over you.\"", "translation_id": "Sesungguhnya telah datang dari Tuhanmu bukti-bukti yang terang; maka barangsiapa melihat (kebenaran itu), maka (manfaatnya) bagi dirinya sendiri; dan barangsiapa buta (tidak melihat kebenaran itu), maka kemudharatannya kembali kepadanya. Dan aku (Muhammad) sekali-kali bukanlah pemelihara(mu).", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 105, "text": "وَكَذَ ٰلِكَ نُصَرِّفُ ٱلۡـَٔایَـٰتِ وَلِیَقُولُوا۟ دَرَسۡتَ وَلِنُبَیِّنَهُۥ لِقَوۡمࣲ یَعۡلَمُونَ ۝١٠٥", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "وكما بيَّنَّا في هذا القرآن للمشركين البراهين الظاهرة في أمر التوحيد والنبوة والمعاد نبيِّن لهم البراهين في كل ما جهلوه فيقولون عند ذلك كذبًا: تعلمت من أهل الكتاب، ولنبين -بتصريفنا الآيات- الحقَّ لقوم يعلمونه، فيقبلونه ويتبعونه، وهم المؤمنون برسول الله محمد صلى الله عليه وسلم وما أنزل عليه.", "isBasmala": false, "translation_en": "We thus diversify the revelations, lest they say, \"You have studied,\" and to clarify them for people who know.", "translation_id": "Demikianlah Kami mengulang-ulangi ayat-ayat Kami supaya (orang-orang yang beriman mendapat petunjuk) dan supaya orang-orang musyrik mengatakan: \"Kamu telah mempelajari ayat-ayat itu (dari Ahli Kitab)\", dan supaya Kami menjelaskan Al Quran itu kepada orang-orang yang mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 106, "text": "ٱتَّبِعۡ مَاۤ أُوحِیَ إِلَیۡكَ مِن رَّبِّكَۖ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِینَ ۝١٠٦", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "اتبع -أيها الرسول- ما أوحيناه إليك من الأوامر والنواهي التي أعظمُها توحيد الله سبحانه والدعوة إليه، ولا تُبال بعناد المشركين، وادعائهم الباطل.", "isBasmala": false, "translation_en": "Follow what was revealed to you from your Lord. There is no god but He. And turn away from the polytheists.", "translation_id": "Ikutilah apa yang telah diwahyukan kepadamu dari Tuhanmu; tidak ada Tuhan selain Dia; dan berpalinglah dari orang-orang musyrik.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 107, "text": "وَلَوۡ شَاۤءَ ٱللَّهُ مَاۤ أَشۡرَكُوا۟ۗ وَمَا جَعَلۡنَـٰكَ عَلَیۡهِمۡ حَفِیظࣰاۖ وَمَاۤ أَنتَ عَلَیۡهِم بِوَكِیلࣲ ۝١٠٧", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "ولو شاء الله تعالى أن لا يشرك هؤلاء المشركون لما أشركوا، لكنه تعالى عليم بما سيكون من سوء اختيارهم واتباعهم أهواءهم المنحرفة. وما جعلناك -أيها الرسول- عليهم رقيبًا تحفظ عليهم أعمالهم، وما أنت بقَيِّمٍ عليهم تدبر مصالحهم.", "isBasmala": false, "translation_en": "Had God willed, they would not have practiced idolatry. We did not appoint you as a guardian over them, and you are not a manager over them.", "translation_id": "Dan kalau Allah menghendaki, niscaya mereka tidak memperkutukan(Nya). Dan Kami tidak menjadikan kamu pemelihara bagi mereka; dan kamu sekali-kali bukanlah pemelihara bagi mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 108, "text": "وَلَا تَسُبُّوا۟ ٱلَّذِینَ یَدۡعُونَ مِن دُونِ ٱللَّهِ فَیَسُبُّوا۟ ٱللَّهَ عَدۡوَۢا بِغَیۡرِ عِلۡمࣲۗ كَذَ ٰلِكَ زَیَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَیُنَبِّئُهُم بِمَا كَانُوا۟ یَعۡمَلُونَ ۝١٠٨", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "ولا تسبوا -أيها المسلمون- الأوثان التي يعبدها المشركون -سدًّا للذريعة- حتى لا يتسبب ذلك في سبهم الله جهلا واعتداءً: بغير علم. وكما حسَّنَّا لهؤلاء عملهم السيئ عقوبة لهم على سوء اختيارهم، حسَّنَّا لكل أمة أعمالها، ثم إلى ربهم معادهم جميعًا فيخبرهم بأعمالهم التي كانوا يعملونها في الدنيا، ثم يجازيهم بها.", "isBasmala": false, "translation_en": "Do not insult those they call upon besides God, lest they insult God out of hostility and ignorance. We made attractive to every community their deeds. Then to their Lord is their return, and He will inform them of what they used to do.", "translation_id": "Dan janganlah kamu memaki sembahan-sembahan yang mereka sembah selain Allah, karena mereka nanti akan memaki Allah dengan melampaui batas tanpa pengetahuan. Demikianlah Kami jadikan setiap umat menganggap baik pekerjaan mereka. Kemudian kepada Tuhan merekalah kembali mereka, lalu Dia memberitakan kepada mereka apa yang dahulu mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 109, "text": "وَأَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ لَىِٕن جَاۤءَتۡهُمۡ ءَایَةࣱ لَّیُؤۡمِنُنَّ بِهَاۚ قُلۡ إِنَّمَا ٱلۡـَٔایَـٰتُ عِندَ ٱللَّهِۖ وَمَا یُشۡعِرُكُمۡ أَنَّهَاۤ إِذَا جَاۤءَتۡ لَا یُؤۡمِنُونَ ۝١٠٩", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "وأقسم هؤلاء المشركون بأيمان مؤكَّدة: لئن جاءنا محمد بعلامة خارقة لنصدقنَّ بما جاء به، قل -أيها الرسول-: إنما مجيء المعجزات الخارقة من عند الله تعالى، هو القادر على المجيء بها إذا شاء، وما يدريكم أيها المؤمنون: لعل هذه المعجزات إذا جاءت لا يصدِّق بها هؤلاء المشركون.", "isBasmala": false, "translation_en": "They swear by God, with their most solemn oaths, that if a miracle were to come to them, they would believe in it. Say, \"The miracles are only with God.\" But how do you know? Even if it did come, they still would not believe.", "translation_id": "Mereka bersumpah dengan nama Allah dengan segala kesungguhan, bahwa sungguh jika datang kepada mereka sesuatu mu jizat, pastilah mereka beriman kepada-Nya. Katakanlah: \"Sesungguhnya mukjizat-mukjizat itu hanya berada di sisi Allah\". Dan apakah yang memberitahukan kepadamu bahwa apabila mukjizat datang mereka tidak akan beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 110, "text": "وَنُقَلِّبُ أَفۡـِٔدَتَهُمۡ وَأَبۡصَـٰرَهُمۡ كَمَا لَمۡ یُؤۡمِنُوا۟ بِهِۦۤ أَوَّلَ مَرَّةࣲ وَنَذَرُهُمۡ فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ ۝١١٠", "juz": 7, "hizb": "(*¾ ح 14*)", "tafsir": "ونقلب أفئدتهم وأبصارهم، فنحول بينها وبين الانتفاع بآيات الله، فلا يؤمنون بها كما لم يؤمنوا بآيات القرآن عند نزولها أول مرة، ونتركهم في تمرُّدهم على الله متحيِّرين، لا يهتدون إلى الحق والصواب.", "isBasmala": false, "translation_en": "And We turn away their hearts and their visions, as they refused to believe in it the first time, and We leave them blundering in their rebellion.", "translation_id": "Dan (begitu pula) Kami memalingkan hati dan penglihatan mereka seperti mereka belum pernah beriman kepadanya (Al Quran) pada permulaannya, dan Kami biarkan mereka bergelimang dalam kesesatannya yang sangat.", "manzil": 2, "manzil_display": ""}], "142": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 111, "text": "۞ وَلَوۡ أَنَّنَا نَزَّلۡنَاۤ إِلَیۡهِمُ ٱلۡمَلَـٰۤىِٕكَةَ وَكَلَّمَهُمُ ٱلۡمَوۡتَىٰ وَحَشَرۡنَا عَلَیۡهِمۡ كُلَّ شَیۡءࣲ قُبُلࣰا مَّا كَانُوا۟ لِیُؤۡمِنُوۤا۟ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُ وَلَـٰكِنَّ أَكۡثَرَهُمۡ یَجۡهَلُونَ ۝١١١", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "ولو أننا أجبنا طلب هؤلاء، فنزَّلنا إليهم الملائكة من السماء، وأحيينا لهم الموتى، فكلموهم، وجمعنا لهم كل شيء طلبوه فعاينوه مواجهة، لم يصدِّقوا بما دعوتهم إليه -أيها الرسول- ولم يعملوا به، إلا من شاء الله له الهداية، ولكن أكثر هؤلاء الكفار يجهلون الحق الذي جئت به من عند الله تعالى.", "isBasmala": false, "translation_en": "Even if We sent down the angels to them, and the dead spoke to them, and We gathered all things before them, they still would not believe, unless God wills; but most of them are ignorant.", "translation_id": "Kalau sekiranya Kami turunkan malaikat kepada mereka, dan orang-orang yang telah mati berbicara dengan mereka dan Kami kumpulkan (pula) segala sesuatu ke hadapan mereka, niscaya mereka tidak (juga) akan beriman, kecuali jika Allah menghendaki, tetapi kebanyakan mereka tidak mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 112, "text": "وَكَذَ ٰلِكَ جَعَلۡنَا لِكُلِّ نَبِیٍّ عَدُوࣰّا شَیَـٰطِینَ ٱلۡإِنسِ وَٱلۡجِنِّ یُوحِی بَعۡضُهُمۡ إِلَىٰ بَعۡضࣲ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورࣰاۚ وَلَوۡ شَاۤءَ رَبُّكَ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا یَفۡتَرُونَ ۝١١٢", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "وكما ابتليناك -أيها الرسول- بأعدائك من المشركين ابتلينا جميع الأنبياء -عليهم السلام- بأعداء مِن مردة قومهم وأعداء من مردة الجن، يُلقي بعضهم إلى بعض القول الذي زيَّنوه بالباطل؛ ليغتر به سامعه، فيضل عن سبيل الله. ولو أراد ربك -جلَّ وعلا- لحال بينهم وبين تلك العداوة، ولكنه الابتلاء من الله، فدعهم وما يختلقون مِن كذب وزور.", "isBasmala": false, "translation_en": "Likewise, We have assigned for every prophet an enemy-human and jinn devils-inspiring one another with fancy words in order to deceive. But had your Lord willed, they would not have done it. So leave them to their fabrications.", "translation_id": "Dan demikianlah Kami jadikan bagi tiap-tiap nabi itu musuh, yaitu syaitan-syaitan (dari jenis) manusia dan (dan jenis) jin, sebahagian mereka membisikkan kepada sebahagian yang lain perkataan-perkataan yang indah-indah untuk menipu (manusia). Jikalau Tuhanmu menghendaki, niscaya mereka tidak mengerjakannya, maka tinggalkanlah mereka dan apa yang mereka ada-adakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 113, "text": "وَلِتَصۡغَىٰۤ إِلَیۡهِ أَفۡـِٔدَةُ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ وَلِیَرۡضَوۡهُ وَلِیَقۡتَرِفُوا۟ مَا هُم مُّقۡتَرِفُونَ ۝١١٣", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "ولِتميل إليه قلوب الكفار الذين لا يصدقون بالحياة الآخرة ولا يعملون لها، ولتحبَّه أنفسهم، وليكتسبوا من الأعمال السيئة ما هم مكتسبون. وفي هذا تهديد عظيم لهم.", "isBasmala": false, "translation_en": "So that the hearts of those who do not believe in the Hereafter may incline to it, and be content with it, and that they may perpetrate whatever they perpetrate.", "translation_id": "Dan (juga) agar hati kecil orang-orang yang tidak beriman kepada kehidupan akhirat cenderung kepada bisikan itu, mereka merasa senang kepadanya dan supaya mereka mengerjakan apa yang mereka (syaitan) kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 114, "text": "أَفَغَیۡرَ ٱللَّهِ أَبۡتَغِی حَكَمࣰا وَهُوَ ٱلَّذِیۤ أَنزَلَ إِلَیۡكُمُ ٱلۡكِتَـٰبَ مُفَصَّلࣰاۚ وَٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَعۡلَمُونَ أَنَّهُۥ مُنَزَّلࣱ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِینَ ۝١١٤", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: أغير الله إلهي وإلهكم أطلب حَكَمًا بيني وبينكم، وهو سبحانه الذي أنزل إليكم القرآن مبينًا فيه الحكم فيما تختصمون فيه من أمري وأمركم؟ وبنو إسرائيل الذين آتاهم الله التوراة والإنجيل يعلمون علمًا يقينًا أن هذا القرآن منزل عليك -أيها الرسول- من ربك بالحق، فلا تكونن من الشاكِّين في شيء مما أوحينا إليك.", "isBasmala": false, "translation_en": "\"Shall I seek a judge other than God, when He is the One who revealed to you the Book, explained in detail?\" Those to whom We gave the Book know that it is the truth revealed from your Lord. So do not be of those who doubt.", "translation_id": "Maka patutkah aku mencari hakim selain daripada Allah, padahal Dialah yang telah menurunkan kitab (Al Quran) kepadamu dengan terperinci? Orang-orang yang telah Kami datangkan kitab kepada mereka, mereka mengetahui bahwa Al Quran itu diturunkan dari Tuhanmu dengan sebenarnya. Maka janganlah kamu sekali-kali termasuk orang yang ragu-ragu.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 115, "text": "وَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقࣰا وَعَدۡلࣰاۚ لَّا مُبَدِّلَ لِكَلِمَـٰتِهِۦۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝١١٥", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "وتمت كلمة ربك -وهي القرآن- صدقًا في الأخبار والأقوال، وعدلا في الأحكام، فلا يستطيع أحد أن يبدِّل كلماته الكاملة. والله تعالى هو السميع لما يقول عباده، الحليم بظواهر أمورهم وبواطنها.", "isBasmala": false, "translation_en": "The Word of your Lord has been completed, in truth and justice. There is no changing to His words. He is the Hearer, the Knower.", "translation_id": "Telah sempurnalah kalimat Tuhanmu (Al-Quran) sebagai kalimat yang benar dan adil. Tidak ada yang dapat merubah rubah kalimat-kalimat-Nya dan Dialah yang Maha Mendenyar lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 116, "text": "وَإِن تُطِعۡ أَكۡثَرَ مَن فِی ٱلۡأَرۡضِ یُضِلُّوكَ عَن سَبِیلِ ٱللَّهِۚ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا یَخۡرُصُونَ ۝١١٦", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "ولو فُرض -أيها الرسول- أنك أطعت أكثر أهل الأرض لأضلُّوك عن دين الله، ما يسيرون إلا على ما ظنوه حقًّا بتقليدهم أسلافهم، وما هم إلا يظنون ويكذبون.", "isBasmala": false, "translation_en": "If you were to obey most of those on earth, they would divert you from God's path. They follow nothing but assumptions, and they only conjecture.", "translation_id": "Dan jika kamu menuruti kebanyakan orang-orang yang di muka bumi ini, niscaya mereka akan menyesatkanmu dari jalan Allah. Mereka tidak lain hanyalah mengikuti persangkaan belaka, dan mereka tidak lain hanyalah berdusta (terhadap Allah).", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 117, "text": "إِنَّ رَبَّكَ هُوَ أَعۡلَمُ مَن یَضِلُّ عَن سَبِیلِهِۦۖ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ ۝١١٧", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "إن ربك هو أعلم بالضالين عن سبيل الرشاد، وهو أعلم منكم ومنهم بمن كان على استقامة وسداد، لا يخفى عليه منهم أحد.", "isBasmala": false, "translation_en": "Your Lord knows best who strays from His path, and He knows best the guided ones.", "translation_id": "Sesungguhnya Tuhanmu, Dialah yang lebih mengetahui tentang orang yang tersesat dari jalan-Nya dan Dia lebih mengetahui tentang orang orang yang mendapat petunjuk.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 118, "text": "فَكُلُوا۟ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَیۡهِ إِن كُنتُم بِـَٔایَـٰتِهِۦ مُؤۡمِنِینَ ۝١١٨", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "فكلوا من الذبائح التي ذُكِرَ اسم الله عليها، إن كنتم ببراهين الله تعالى الواضحة مصدقين.", "isBasmala": false, "translation_en": "So eat of that over which the Name of God was pronounced, if you indeed believe in His revelations.", "translation_id": "Maka makanlah binatang-binatang (yang halal) yang disebut nama Allah ketika menyembelihnya, jika kamu beriman kepada ayat-ayat-Nya.", "manzil": 2, "manzil_display": ""}], "143": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 119, "text": "وَمَا لَكُمۡ أَلَّا تَأۡكُلُوا۟ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَیۡهِ وَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَیۡكُمۡ إِلَّا مَا ٱضۡطُرِرۡتُمۡ إِلَیۡهِۗ وَإِنَّ كَثِیرࣰا لَّیُضِلُّونَ بِأَهۡوَاۤىِٕهِم بِغَیۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِینَ ۝١١٩", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "وأيُّ شيء يمنعكم أيها المسلمون من أن تأكلوا مما ذكر اسم الله عليه، وقد بيَّن الله سبحانه لكم جميع ما حرَّم عليكم؟ لكن ما دعت إليه الضرورة بسبب المجاعة، مما هو محرم عليكم كالميتة، فإنه مباح لكم. وإنَّ كثيرًا من الضالين ليضلون عن سبيل الله أشياعهم في تحليل الحرام وتحريم الحلال بأهوائهم؛ جهلا منهم. إن ربك -أيها الرسول- هو أعلم بمن تجاوز حده في ذلك، وهو الذي يتولى حسابه وجزاءه.", "isBasmala": false, "translation_en": "And why should you not eat of that over which the Name of God is pronounced, when He has detailed for you what is prohibited for you, unless you are compelled by necessity? Many lead astray with their opinions, through lack of knowledge. Your Lord knows best the transgressors.", "translation_id": "Mengapa kamu tidak mau memakan (binatang-binatang yang halal) yang disebut nama Allah ketika menyembelihnya, padahal sesungguhnya Allah telah menjelaskan kepada kamu apa yang diharamkan-Nya atasmu, kecuali apa yang terpaksa kamu memakannya. Dan sesungguhnya kebanyakan (dari manusia) benar benar hendak menyesatkan (orang lain) dengan hawa nafsu mereka tanpa pengetahuan. Sesungguhnya Tuhanmu, Dialah yang lebih mengetahui orang-orang yang melampaui batas.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 120, "text": "وَذَرُوا۟ ظَـٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥۤۚ إِنَّ ٱلَّذِینَ یَكۡسِبُونَ ٱلۡإِثۡمَ سَیُجۡزَوۡنَ بِمَا كَانُوا۟ یَقۡتَرِفُونَ ۝١٢٠", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "واتركوا -أيها الناس- جميع المعاصي، ما كان منها علانية وما كان سرًّا. إن الذين يفعلون المعاصي سيعاقبهم ربهم؛ بسبب ما كانوا يعملونه من السيئات.", "isBasmala": false, "translation_en": "So abandon sin, outward and inward. Those who commit sins will be repaid for what they used to perpetrate.", "translation_id": "Dan tinggalkanlah dosa yang nampak dan yang tersembunyi. Sesungguhnya orang yang mengerjakan dosa, kelak akan diberi pembalasan (pada hari kiamat), disebabkan apa yang mereka telah kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 121, "text": "وَلَا تَأۡكُلُوا۟ مِمَّا لَمۡ یُذۡكَرِ ٱسۡمُ ٱللَّهِ عَلَیۡهِ وَإِنَّهُۥ لَفِسۡقࣱۗ وَإِنَّ ٱلشَّیَـٰطِینَ لَیُوحُونَ إِلَىٰۤ أَوۡلِیَاۤىِٕهِمۡ لِیُجَـٰدِلُوكُمۡۖ وَإِنۡ أَطَعۡتُمُوهُمۡ إِنَّكُمۡ لَمُشۡرِكُونَ ۝١٢١", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "ولا تأكلوا -أيها المسلمون- من الذبائح التي لم يذكر اسم الله عليها عند الذبح، كالميتة وما ذبح للأوثان والجن، وغير ذلك، وإن الأكل من تلك الذبائح لخروج عن طاعة الله تعالى. وإن مردة الجن لَيُلْقون إلى أوليائهم من شياطين الإنس بالشبهات حول تحريم أكل الميتة، فيأمرونهم أن يقولوا للمسلمين في جدالهم معهم: إنكم بعدم أكلكم الميتة لا تأكلون ما قتله الله، بينما تأكلون مما تذبحونه، وإن أطعتموهم -أيها المسلمون في تحليل الميتة- فأنتم وهم في الشرك سواء.", "isBasmala": false, "translation_en": "And do not eat from that over which the Name of God was not pronounced, for it is abomination. The devils inspire their followers to argue with you; but if you obey them, you would be polytheists.", "translation_id": "Dan janganlah kamu memakan binatang-binatang yang tidak disebut nama Allah ketika menyembelihnya. Sesungguhnya perbuatan yang semacam itu adalah suatu kefasikan. Sesungguhnya syaitan itu membisikkan kepada kawan-kawannya agar mereka membantah kamu; dan jika kamu menuruti mereka, sesungguhnya kamu tentulah menjadi orang-orang yang musyrik.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 122, "text": "أَوَ مَن كَانَ مَیۡتࣰا فَأَحۡیَیۡنَـٰهُ وَجَعَلۡنَا لَهُۥ نُورࣰا یَمۡشِی بِهِۦ فِی ٱلنَّاسِ كَمَن مَّثَلُهُۥ فِی ٱلظُّلُمَـٰتِ لَیۡسَ بِخَارِجࣲ مِّنۡهَاۚ كَذَ ٰلِكَ زُیِّنَ لِلۡكَـٰفِرِینَ مَا كَانُوا۟ یَعۡمَلُونَ ۝١٢٢", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "أوَمن كان ميتًا في الضلالة هالكا حائرا، فأحيينا قلبه بالإيمان، وهديناه له، ووفقناه لاتباع رسله، فأصبح يعيش في أنوار الهداية، كمن مثله في الجهالات والأهواء والضلالات المتفرقة، لا يهتدي إلى منفذ ولا مخلص له مما هو فيه؟ لا يستويان، وكما خذلتُ هذا الكافر الذي يجادلكم -أيها المؤمنون- فزيَّنْتُ له سوء عمله، فرآه حسنًا، زيَّنْتُ للجاحدين أعمالهم السيئة؛ ليستوجبوا بذلك العذاب.", "isBasmala": false, "translation_en": "Is he who was dead, then We gave him life, and made for him a light by which he walks among the people, like he who is in total darkness, and cannot get out of it? Thus the doings of disbelievers are made to appear good to them.", "translation_id": "Dan apakah orang yang sudah mati kemudian dia Kami hidupkan dan Kami berikan kepadanya cahaya yang terang, yang dengan cahaya itu dia dapat berjalan di tengah-tengah masyarakat manusia, serupa dengan orang yang keadaannya berada dalam gelap gulita yang sekali-kali tidak dapat keluar dari padanya? Demikianlah Kami jadikan orang yang kafir itu memandang baik apa yang telah mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 123, "text": "وَكَذَ ٰلِكَ جَعَلۡنَا فِی كُلِّ قَرۡیَةٍ أَكَـٰبِرَ مُجۡرِمِیهَا لِیَمۡكُرُوا۟ فِیهَاۖ وَمَا یَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا یَشۡعُرُونَ ۝١٢٣", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "ومثل هذا الذي حصل مِن زعماء الكفار في \"مكة\" من الصدِّ عن دين الله تعالى، جعلنا في كل قرية مجرمين يتزعمهم أكابرهم؛ ليمكروا فيها بالصد عن دين الله، وما يكيدون إلا أنفسهم، وما يُحِسُّون بذلك.", "isBasmala": false, "translation_en": "And thus We set up in every city its leading wicked sinners, to conspire in it, but they conspire only against themselves, and they do not realize it.", "translation_id": "Dan demikianlah Kami adakan pada tiap-tiap negeri penjahat-penjahat yang terbesar agar mereka melakukan tipu daya dalam negeri itu. Dan mereka tidak memperdayakan melainkan dirinya sendiri, sedang mereka tidak menyadarinya.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 124, "text": "وَإِذَا جَاۤءَتۡهُمۡ ءَایَةࣱ قَالُوا۟ لَن نُّؤۡمِنَ حَتَّىٰ نُؤۡتَىٰ مِثۡلَ مَاۤ أُوتِیَ رُسُلُ ٱللَّهِۘ ٱللَّهُ أَعۡلَمُ حَیۡثُ یَجۡعَلُ رِسَالَتَهُۥۗ سَیُصِیبُ ٱلَّذِینَ أَجۡرَمُوا۟ صَغَارٌ عِندَ ٱللَّهِ وَعَذَابࣱ شَدِیدُۢ بِمَا كَانُوا۟ یَمۡكُرُونَ ۝١٢٤", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "وإذا جاءت هؤلاء المشركين من أهل \"مكة\" حجة ظاهرة على نبوة محمد صلى الله عليه وسلم، قال بعض كبرائهم: لن نصدِّق بنبوته حتى يعطينا الله من النبوة والمعجزات مثل ما أعطى رسله السابقين. فردَّ الله تعالى عليهم بقوله: الله أعلم حيث يجعل رسالته أي: بالذين هم أهل لحمل رسالته وتبليغها إلى الناس. سينال هؤلاء الطغاة الذل، ولهم عذاب موجع في نار جهنم؛ بسبب كيدهم للإسلام وأهله.", "isBasmala": false, "translation_en": "When a sign comes to them, they say, \"We will not believe unless we are given the like of what was given to God's messengers.\" God knows best where to place His message. Humiliation from God and severe torment will afflict the criminals for their scheming.", "translation_id": "Apabila datang sesuatu ayat kepada mereka, mereka berkata: \"Kami tidak akan beriman sehingga diberikan kepada kami yang serupa dengan apa yang telah diberikan kepada utusan-utusan Allah\". Allah lebih mengetahui di mana Dia menempatkan tugas kerasulan. Orang-orang yang berdosa, nanti akan ditimpa kehinaan di sisi Allah dan siksa yang keras disebabkan mereka selalu membuat tipu daya.", "manzil": 2, "manzil_display": ""}], "144": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 125, "text": "فَمَن یُرِدِ ٱللَّهُ أَن یَهۡدِیَهُۥ یَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَـٰمِۖ وَمَن یُرِدۡ أَن یُضِلَّهُۥ یَجۡعَلۡ صَدۡرَهُۥ ضَیِّقًا حَرَجࣰا كَأَنَّمَا یَصَّعَّدُ فِی ٱلسَّمَاۤءِۚ كَذَ ٰلِكَ یَجۡعَلُ ٱللَّهُ ٱلرِّجۡسَ عَلَى ٱلَّذِینَ لَا یُؤۡمِنُونَ ۝١٢٥", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "فمن يشأ الله أن يوفقه لقَبول الحق يشرح صدره للتوحيد والإيمان، ومن يشأ أن يضله يجعل صدره في حال شديدة من الانقباض عن قَبول الهدى، كحال مَن يصعد في طبقات الجو العليا، فيصاب بضيق شديد في التنفس. وكما يجعل الله صدور الكافرين شديدة الضيق والانقباض، كذلك يجعل العذاب على الذين لا يؤمنون به.", "isBasmala": false, "translation_en": "Whomever God desires to guide, He spreads open his heart to Islam; and whomever He desires to misguide, He makes his heart narrow, constricted, as though he were climbing up the sky. God thus lays defilement upon those who do not believe.", "translation_id": "Barangsiapa yang Allah menghendaki akan memberikan kepadanya petunjuk, niscaya Dia melapangkan dadanya untuk (memeluk agama) Islam. Dan barangsiapa yang dikehendaki Allah kesesatannya, niscaya Allah menjadikan dadanya sesak lagi sempit, seolah-olah ia sedang mendaki langit. Begitulah Allah menimpakan siksa kepada orang-orang yang tidak beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 126, "text": "وَهَـٰذَا صِرَ ٰطُ رَبِّكَ مُسۡتَقِیمࣰاۗ قَدۡ فَصَّلۡنَا ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَذَّكَّرُونَ ۝١٢٦", "juz": 8, "hizb": "(* ح 15*)", "tafsir": "وهذا الذي بيَّنَّاه لك -أيها الرسول- هو الطريق الموصل إلى رضا ربك وجنته. قد بينَّا البراهين لمن يتذكر من أهل العقول الراجحة.", "isBasmala": false, "translation_en": "This is the straight path of your Lord. We have explained the revelations in detail for people who recollect.", "translation_id": "Dan inilah jalan Tuhanmu; (jalan) yang lurus. Sesungguhnya Kami telah menjelaskan ayat-ayat (Kami) kepada orang-orang yang mengambil pelajaran.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 127, "text": "۞ لَهُمۡ دَارُ ٱلسَّلَـٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِیُّهُم بِمَا كَانُوا۟ یَعۡمَلُونَ ۝١٢٧", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "للمتذكرين عند ربهم جل وعلا يوم القيامة دار السلامة والأمان من كل مكروه وهي الجنة، وهو سبحانه ناصرهم وحافظهم جزاءً لهم؛ بسبب أعمالهم الصالحة.", "isBasmala": false, "translation_en": "For them is the Home of Peace with their Lord, and He is their Master-because of what they used to do.", "translation_id": "Bagi mereka (disediakan) darussalam (surga) pada sisi Tuhannya dan Dialah Pelindung mereka disebabkan amal-amal saleh yang selalu mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 128, "text": "وَیَوۡمَ یَحۡشُرُهُمۡ جَمِیعࣰا یَـٰمَعۡشَرَ ٱلۡجِنِّ قَدِ ٱسۡتَكۡثَرۡتُم مِّنَ ٱلۡإِنسِۖ وَقَالَ أَوۡلِیَاۤؤُهُم مِّنَ ٱلۡإِنسِ رَبَّنَا ٱسۡتَمۡتَعَ بَعۡضُنَا بِبَعۡضࣲ وَبَلَغۡنَاۤ أَجَلَنَا ٱلَّذِیۤ أَجَّلۡتَ لَنَاۚ قَالَ ٱلنَّارُ مَثۡوَىٰكُمۡ خَـٰلِدِینَ فِیهَاۤ إِلَّا مَا شَاۤءَ ٱللَّهُۗ إِنَّ رَبَّكَ حَكِیمٌ عَلِیمࣱ ۝١٢٨", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "واذكر -أيها الرسول- يوم يحشر الله تعالى الكفار وأولياءهم من شياطين الجن فيقول: يا معشر الجن قد أضللتم كثيرًا من الإنس، وقال أولياؤهم من كفار الإنس: ربنا قد انتفع بعضنا من بعض، وبلغنا الأجل الذي أجَّلْتَه لنا بانقضاء حياتنا الدنيا، قال الله تعالى لهم: النار مثواكم، أي: مكان إقامتكم خالدين فيها، إلا مَن شاء الله عدم خلوده فيها من عصاة الموحدين. إن ربك حكيم في تدبيره وصنعه، عليم بجميع أمور عباده.", "isBasmala": false, "translation_en": "On the Day when He gathers them all together: \"O assembly of jinn, you have exploited multitudes of humans.\" Their adherents among mankind will say, \"Our Lord, we have profited from one another, but we have reached the term that you have assigned for us.\" He will say, \"The Fire is your dwelling, wherein you will remain, except as God wills. Your Lord is Wise and Informed.", "translation_id": "Dan (ingatlah) hari diwaktu Allah menghimpunkan mereka semuanya (dan Allah berfirman): \"Hai golongan jin, sesungguhnya kamu telah banyak menyesatkan manusia\", lalu berkatalah kawan-kawan meraka dari golongan manusia: \"Ya Tuhan kami, sesungguhnya sebahagian daripada kami telah dapat kesenangan dari sebahagian (yang lain) dan kami telah sampai kepada waktu yang telah Engkau tentukan bagi kami\". Allah berfirman: \"Neraka itulah tempat diam kamu, sedang kamu kekal di dalamnya, kecuali kalau Allah menghendaki (yang lain)\". Sesungguhnya Tuhanmu Maha Bijaksana lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 129, "text": "وَكَذَ ٰلِكَ نُوَلِّی بَعۡضَ ٱلظَّـٰلِمِینَ بَعۡضَۢا بِمَا كَانُوا۟ یَكۡسِبُونَ ۝١٢٩", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "وكما سلَّطْنا شياطين الجن على كفار الإنس، فكانوا أولياء لهم، نسلِّط الظالمين من الإنس بعضهم على بعض في الدنيا؛ بسبب ما يعملونه من المعاصي.", "isBasmala": false, "translation_en": "Thus We make some of the wrongdoers befriend one another, because of what they used to do.", "translation_id": "Dan demikianlah Kami jadikan sebahagian orang-orang yang zalim itu menjadi teman bagi sebahagian yang lain disebabkan apa yang mereka usahakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 130, "text": "یَـٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ یَأۡتِكُمۡ رُسُلࣱ مِّنكُمۡ یَقُصُّونَ عَلَیۡكُمۡ ءَایَـٰتِی وَیُنذِرُونَكُمۡ لِقَاۤءَ یَوۡمِكُمۡ هَـٰذَاۚ قَالُوا۟ شَهِدۡنَا عَلَىٰۤ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَشَهِدُوا۟ عَلَىٰۤ أَنفُسِهِمۡ أَنَّهُمۡ كَانُوا۟ كَـٰفِرِینَ ۝١٣٠", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "أيها المشركون من الجن والإنس، ألم يأتكم رسل من جملتكم -وظاهر النصوص يدلُّ على أنَّ الرسل من الإنس فقط-، يخبرونكم بآياتي الواضحة المشتملة على الأمر والنهي وبيان الخير والشر، ويحذرونكم لقاء عذابي في يوم القيامة؟ قال هؤلاء المشركون من الإنس والجن: شَهِدْنا على أنفسنا بأن رسلك قد بلغونا آياتك، وأنذرونا لقاء يومنا هذا، فكذبناهم، وخدعت هؤلاء المشركين زينةُ الحياة الدنيا، وشهدوا على أنفسهم أنهم كانوا جاحدين وحدانية الله تعالى ومكذبين لرسله عليهم السلام.", "isBasmala": false, "translation_en": "\"O assembly of jinn and humans, did there not come to you messengers from among you, relating to you My revelations, and warning you of the meeting of this Day of yours?\" They will say, \"We testify against ourselves.\" The life of the world seduced them. They will testify against themselves that they were disbelievers.", "translation_id": "Hai golongan jin dan manusia, apakah belum datang kepadamu rasul-rasul dari golongan kamu sendiri, yang menyampaikan kepadamu ayat-ayat-Ku dan memberi peringatan kepadamu terhadap pertemuanmu dengan hari ini? Mereka berkata: \"Kami menjadi saksi atas diri kami sendiri\", kehidupan dunia telah menipu mereka, dan mereka menjadi saksi atas diri mereka sendiri, bahwa mereka adalah orang-orang yang kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 131, "text": "ذَ ٰلِكَ أَن لَّمۡ یَكُن رَّبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمࣲ وَأَهۡلُهَا غَـٰفِلُونَ ۝١٣١", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "إنما أعذرنا إلى الثقلين بإرسال الرسل وإنزال الكتب، لئلا يؤاخَذَ أحد بظلمه، وهو لم تبلغه دعوة، ولكن أعذرنا إلى الأمم، وما عذَّبنا أحدًا إلا بعد إرسال الرسل إليهم.", "isBasmala": false, "translation_en": "That is because your Lord would not destroy towns for injustice while their inhabitants are unaware.", "translation_id": "Yang demikian itu adalah karena Tuhanmu tidaklah membinasakan kota-kota secara aniaya, sedang penduduknya dalam keadaan lengah.", "manzil": 2, "manzil_display": ""}], "145": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 132, "text": "وَلِكُلࣲّ دَرَجَـٰتࣱ مِّمَّا عَمِلُوا۟ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا یَعۡمَلُونَ ۝١٣٢", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "ولكل عامل في طاعة الله تعالى أو معصيته مراتب من عمله، يبلِّغه الله إياها، ويجازيه عليها. وما ربك -أيها الرسول- بغافل عما يعمل عباده.", "isBasmala": false, "translation_en": "They all have ranks according to what they did; and your Lord is not unaware of what they do.", "translation_id": "Dan masing-masing orang memperoleh derajat-derajat (seimbang) dengan apa yang dikerjakannya. Dan Tuhanmu tidak lengah dari apa yang mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 133, "text": "وَرَبُّكَ ٱلۡغَنِیُّ ذُو ٱلرَّحۡمَةِۚ إِن یَشَأۡ یُذۡهِبۡكُمۡ وَیَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا یَشَاۤءُ كَمَاۤ أَنشَأَكُم مِّن ذُرِّیَّةِ قَوۡمٍ ءَاخَرِینَ ۝١٣٣", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "وربك -أيها الرسول- الذي أمر الناس بعبادته، هو الغني وحده، وكل خلقه محتاجون إليه، وهو سبحانه ذو الرحمة الواسعة، لو أراد لأهلككم، وأوجد قومًا غيركم يخلفونكم من بعد فنائكم، ويعملون بطاعته تعالى، كما أوجدكم من نسل قوم آخرين كانوا قبلكم.", "isBasmala": false, "translation_en": "Your Lord is the Rich Beyond Need, the Possessor of Mercy. If He wills, he can do away with you, and substitute whomever He wills in your place, just as He produced you from the descendants of another people.", "translation_id": "Dan Tuhanmu Maha Kaya lagi mempunyai rahmat. Jika Dia menghendaki niscaya Dia memusnahkan kamu dan menggantimu dengan siapa yang dikehendaki-Nya setelah kamu (musnah), sebagaimana Dia telah menjadikan kamu dari keturunan orang-orang lain.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 134, "text": "إِنَّ مَا تُوعَدُونَ لَـَٔاتࣲۖ وَمَاۤ أَنتُم بِمُعۡجِزِینَ ۝١٣٤", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "إن الذي يوعدكم به ربكم - أيها المشركون - من العقاب على كفركم واقع بكم، ولن تُعجِزوا ربكم هربًا، فهو قادر على إعادتكم، وإن صرتم ترابًا وعظامًا.", "isBasmala": false, "translation_en": "What you are promised is coming, and you cannot thwart it.", "translation_id": "Sesungguhnya apa yang dijanjikan kepadamu pasti datang, dan kamu sekali-kali tidak sanggup menolaknya.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 135, "text": "قُلۡ یَـٰقَوۡمِ ٱعۡمَلُوا۟ عَلَىٰ مَكَانَتِكُمۡ إِنِّی عَامِلࣱۖ فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلظَّـٰلِمُونَ ۝١٣٥", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "قل -أيها الرسول-: يا قوم اعملوا على طريقتكم فإني عامل على طريقتي التي شرعها لي ربي جل وعلا فسوف تعلمون -عند حلول النقمة بكم- مَنِ الذي تكون له العاقبة الحسنة؟ إنه لا يفوز برضوان الله تعالى والجنة مَن تجاوز حده وظلم، فأشرك مع الله غيره.", "isBasmala": false, "translation_en": "Say, \"O my people! Work according to your ability, and so will I.\" You will come to know to whom will belong the sequel of the abode.\" The wrongdoers will not prevail.", "translation_id": "Katakanlah: \"Hai kaumku, berbuatlah sepenuh kemampuanmu, sesungguhnya akupun berbuat (pula). Kelak kamu akan mengetahui, siapakah (di antara kita) yang akan memperoleh hasil yang baik di dunia ini. Sesungguhnya orang-orang yang zalim itu tidak akan mendapatkan keberuntungan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 136, "text": "وَجَعَلُوا۟ لِلَّهِ مِمَّا ذَرَأَ مِنَ ٱلۡحَرۡثِ وَٱلۡأَنۡعَـٰمِ نَصِیبࣰا فَقَالُوا۟ هَـٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَـٰذَا لِشُرَكَاۤىِٕنَاۖ فَمَا كَانَ لِشُرَكَاۤىِٕهِمۡ فَلَا یَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ یَصِلُ إِلَىٰ شُرَكَاۤىِٕهِمۡۗ سَاۤءَ مَا یَحۡكُمُونَ ۝١٣٦", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "وجعل المشركون لله -جلَّ وعلا- جزءًا مما خلق من الزروع والثمار والأنعام يقدمونه للضيوف والمساكين، وجعلوا قسمًا آخر من هذه الأشياء لشركائهم من الأوثان والأنصاب، فما كان مخصصًا لشركائهم فإنه يصل إليها وحدها، ولا يصل إلى الله، وما كان مخصصا لله تعالى فإنه يصل إلى شركائهم. بئس حكم القوم وقسمتهم.", "isBasmala": false, "translation_en": "And they set aside for God a share of the crops and the livestock He created, and they say, \"This is for God,\" according to their claim, \"and this is for our idols.\" But the share of their idols does not reach God, yet the share of God reaches their idols. Evil is their judgment.", "translation_id": "Dan mereka memperuntukkan bagi Allah satu bagian dari tanaman dan ternak yang telah diciptakan Allah, lalu mereka berkata sesuai dengan persangkaan mereka: \"Ini untuk Allah dan ini untuk berhala-berhala kami\". Maka saji-sajian yang diperuntukkan bagi berhala-berhala mereka tidak sampai kepada Allah; dan saji-sajian yang diperuntukkan bagi Allah, maka sajian itu sampai kepada berhala-berhala mereka. Amat buruklah ketetapan mereka itu.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 137, "text": "وَكَذَ ٰلِكَ زَیَّنَ لِكَثِیرࣲ مِّنَ ٱلۡمُشۡرِكِینَ قَتۡلَ أَوۡلَـٰدِهِمۡ شُرَكَاۤؤُهُمۡ لِیُرۡدُوهُمۡ وَلِیَلۡبِسُوا۟ عَلَیۡهِمۡ دِینَهُمۡۖ وَلَوۡ شَاۤءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا یَفۡتَرُونَ ۝١٣٧", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "وكما زيَّن الشيطان للمشركين أن يجعلوا لله تعالى من الحرث والأنعام نصيبًا، ولشركائهم نصيبًا، زيَّنت الشياطين لكثير من المشركين قَتْلَ أولادهم خشية الفقر؛ ليوقعوا هؤلاء الآباء في الهلاك بقتل النفس التي حرم الله قتلها إلا بالحق، وليخلطوا عليهم دينهم فيلتبس، فيضلوا ويهلكوا، ولو شاء الله ألا يفعلوا ذلك ما فعلوه، ولكنه قدَّر ذلك لعلمه بسوء حالهم ومآلهم، فاتركهم -أيها الرسول- وشأنهم فيما يفترون من كذب، فسيحكم الله بينك وبينهم.", "isBasmala": false, "translation_en": "Likewise, their idols entice many idolaters to kill their children, in order to lead them to their ruin, and confuse them in their religion. Had God willed, they would not have done it; so leave them to their fraud.", "translation_id": "Dan demikianlah pemimpin-pemimpin mereka telah menjadikan kebanyakan dari orang-orang musyrik itu memandang baik membunuh anak-anak mereka untuk membinasakan mereka dan untuk mengaburkan bagi mereka agama-Nya. Dan kalau Allah menghendaki, niscaya mereka tidak mengerjakannya, maka tinggallah mereka dan apa yang mereka ada-adakan.", "manzil": 2, "manzil_display": ""}], "146": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 138, "text": "وَقَالُوا۟ هَـٰذِهِۦۤ أَنۡعَـٰمࣱ وَحَرۡثٌ حِجۡرࣱ لَّا یَطۡعَمُهَاۤ إِلَّا مَن نَّشَاۤءُ بِزَعۡمِهِمۡ وَأَنۡعَـٰمٌ حُرِّمَتۡ ظُهُورُهَا وَأَنۡعَـٰمࣱ لَّا یَذۡكُرُونَ ٱسۡمَ ٱللَّهِ عَلَیۡهَا ٱفۡتِرَاۤءً عَلَیۡهِۚ سَیَجۡزِیهِم بِمَا كَانُوا۟ یَفۡتَرُونَ ۝١٣٨", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "وقال المشركون: هذه إبل وزرع حرام، لا يأكلها إلا مَن يأذنون له -حسب ادعائهم- مِن سدنة الأوثان وغيرهم. وهذه إبل حُرِّمت ظهورها، فلا يحل ركوبها والحملُ عليها بحال من الأحوال. وهذه إبل لا يَذكرون اسم الله تعالى عليها في أي شأن من شئونها. فعلوا ذلك كذبًا منهم على الله، سيجزيهم الله بسبب ما كانوا يفترون من كذبٍ عليه سبحانه.", "isBasmala": false, "translation_en": "And they say, \"These animals and crops are restricted; none may eat them except those we permit,\" by their claims, and animals whose backs are forbidden, and animals over which they do not pronounce the name of God-fabricating lies against Him. He will repay them for what they used to invent.", "translation_id": "Dan mereka mengatakan: \"Inilah hewan ternak dan tanaman yang dilarang; tidak boleh memakannya, kecuali orang yang kami kehendaki\", menurut anggapan mereka, dan ada binatang ternak yang diharamkan menungganginya dan ada binatang ternak yang mereka tidak menyebut nama Allah waktu menyembelihnya, semata-mata membuat-buat kedustaan terhadap Allah. Kelak Allah akan membalas mereka terhadap apa yang selalu mereka ada-adakan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 139, "text": "وَقَالُوا۟ مَا فِی بُطُونِ هَـٰذِهِ ٱلۡأَنۡعَـٰمِ خَالِصَةࣱ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰۤ أَزۡوَ ٰجِنَاۖ وَإِن یَكُن مَّیۡتَةࣰ فَهُمۡ فِیهِ شُرَكَاۤءُۚ سَیَجۡزِیهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِیمٌ عَلِیمࣱ ۝١٣٩", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "وقال المشركون: ما في بطون الأنعام من أجنَّة مباح لرجالنا، ومحرم على نسائنا، إذا ولد حيًّا، ويشتركون فيه إذا ولد ميتًا. سيعاقبهم الله إذ شرَّعوا لأنفسهم من التحليل والتحريم ما لم يأذن به الله. إنه تعالى حكيم في تدبير أمور خلقه، عليم بهم.", "isBasmala": false, "translation_en": "And they say, \"What lies in the wombs of these animals is exclusively for our males, and prohibited to our wives.\" But if it is stillborn, they can share in it. He will surely punish them for their allegations. He is Wise and Knowing.", "translation_id": "Dan mereka mengatakan: \"Apa yang ada dalam perut binatang ternak ini adalah khusus untuk pria kami dan diharamkan atas wanita kami,\" dan jika yang dalam perut itu dilahirkan mati, maka pria dan wanita sama-sama boleh memakannya. Kelak Allah akan membalas mereka terhadap ketetapan mereka. Sesungguhnya Allah Maha Bijaksana lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 140, "text": "قَدۡ خَسِرَ ٱلَّذِینَ قَتَلُوۤا۟ أَوۡلَـٰدَهُمۡ سَفَهَۢا بِغَیۡرِ عِلۡمࣲ وَحَرَّمُوا۟ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَاۤءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّوا۟ وَمَا كَانُوا۟ مُهۡتَدِینَ ۝١٤٠", "juz": 8, "hizb": "(*¼ ح 15*)", "tafsir": "قد خسر وهلك الذين قتلوا أولادهم لضعف عقولهم وجهلهم، وحرموا ما رزقهم الله كذبًا على الله. قد بَعُدوا عن الحق، وما كانوا من أهل الهدى والرشاد. فالتحليل والتحريم من خصائص الألوهية في التشريع، والحلال ما أحله الله، والحرام ما حرَّمه الله، وليس لأحد من خَلْقه فردًا كان أو جماعة أن يشرع لعباده ما لم يأذن به الله.", "isBasmala": false, "translation_en": "Lost are those who kill their children foolishly, with no basis in knowledge, and forbid what God has provided for them-innovations about God. They have gone astray. They are not guided.", "translation_id": "Sesungguhnya rugilah orang yang membunuh anak-anak mereka, karena kebodohan lagi tidak mengetahui dan mereka mengharamkan apa yang Allah telah rezeki-kan pada mereka dengan semata-mata mengada-adakan terhadap Allah. Sesungguhnya mereka telah sesat dan tidaklah mereka mendapat petunjuk.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 141, "text": "۞ وَهُوَ ٱلَّذِیۤ أَنشَأَ جَنَّـٰتࣲ مَّعۡرُوشَـٰتࣲ وَغَیۡرَ مَعۡرُوشَـٰتࣲ وَٱلنَّخۡلَ وَٱلزَّرۡعَ مُخۡتَلِفًا أُكُلُهُۥ وَٱلزَّیۡتُونَ وَٱلرُّمَّانَ مُتَشَـٰبِهࣰا وَغَیۡرَ مُتَشَـٰبِهࣲۚ كُلُوا۟ مِن ثَمَرِهِۦۤ إِذَاۤ أَثۡمَرَ وَءَاتُوا۟ حَقَّهُۥ یَوۡمَ حَصَادِهِۦۖ وَلَا تُسۡرِفُوۤا۟ۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡمُسۡرِفِینَ ۝١٤١", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "والله سبحانه وتعالى هو الذي أوجد لكم بساتين: منها ما هو مرفوع عن الأرض كالأعناب، ومنها ما هو غير مرفوع، ولكنه قائم على سوقه كالنخل والزرع، متنوعًا طعمه، والزيتون والرمان متشابهًا منظره، ومختلفًا ثمره وطعمه. كلوا -أيها الناس- مِن ثمره إذا أثمر، وأعطوا زكاته المفروضة عليكم يوم حصاده وقطافه، ولا تتجاوزوا حدود الاعتدال في إخراج المال وأكل الطعام وغير ذلك. إنه تعالى لا يحب المتجاوزين حدوده بإنفاق المال في غير وجهه.", "isBasmala": false, "translation_en": "It is He who produces gardens, both cultivated and wild, and date-palms, and crops of diverse tastes, and olives and pomegranates, similar and dissimilar. Eat of its fruit when it yields, and give its due on the day of its harvest, and do not waste. He does not love the wasteful.", "translation_id": "Dan Dialah yang menjadikan kebun-kebun yang berjunjung dan yang tidak berjunjung, pohon korma, tanam-tanaman yang bermacam-macam buahnya, zaitun dan delima yang serupa (bentuk dan warnanya) dan tidak sama (rasanya). Makanlah dari buahnya (yang bermacam-macam itu) bila dia berbuah, dan tunaikanlah haknya di hari memetik hasilnya (dengan disedekahkan kepada fakir miskin); dan janganlah kamu berlebih-lebihan. Sesungguhnya Allah tidak menyukai orang yang berlebih-lebihan.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 142, "text": "وَمِنَ ٱلۡأَنۡعَـٰمِ حَمُولَةࣰ وَفَرۡشࣰاۚ كُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ وَلَا تَتَّبِعُوا۟ خُطُوَ ٰتِ ٱلشَّیۡطَـٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینࣱ ۝١٤٢", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "وأوجد من الأنعام ما هو مهيَّأ للحمل عليه لكبره وارتفاعه كالإبل، ومنها ما هو مهيَّأ لغير الحمل لصغره وقربه من الأرض كالبقر والغنم، كلوا مما أباحه الله لكم وأعطاكموه من هذه الأنعام، ولا تحرموا ما أحلَّ الله منها اتباعًا لطرق الشيطان، كما فعل المشركون. إن الشيطان لكم عدو ظاهر العداوة.", "isBasmala": false, "translation_en": "Among the livestock are some for transportation, and some for clothing. Eat of what God has provided for you, and do not follow the footsteps of Satan. He is to you an outright enemy.", "translation_id": "Dan di antara hewan ternak itu ada yang dijadikan untuk pengangkutan dan ada yang untuk disembelih. Makanlah dari rezeki yang telah diberikan Allah kepadamu, dan janganlah kamu mengikuti langkah-langkah syaitan. Sesungguhnya syaitan itu musuh yang nyata bagimu.", "manzil": 2, "manzil_display": ""}], "147": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 143, "text": "ثَمَـٰنِیَةَ أَزۡوَ ٰجࣲۖ مِّنَ ٱلضَّأۡنِ ٱثۡنَیۡنِ وَمِنَ ٱلۡمَعۡزِ ٱثۡنَیۡنِۗ قُلۡ ءَاۤلذَّكَرَیۡنِ حَرَّمَ أَمِ ٱلۡأُنثَیَیۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَیۡهِ أَرۡحَامُ ٱلۡأُنثَیَیۡنِۖ نَبِّـُٔونِی بِعِلۡمٍ إِن كُنتُمۡ صَـٰدِقِینَ ۝١٤٣", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "هذه الأنعام التي رزقها الله عباده من الإبل والبقر والغنم ثمانية أصناف: أربعة منها من الغنم، وهي الضأن ذكورًا وإناثًا، والمعز ذكورًا وإناثًا. قل -أيها الرسول- لأولئك المشركين: هل حَرَّم الله الذكرين من الغنم؟ فإن قالوا: نعم، فقد كذبوا في ذلك؛ لأنهم لا يحرمون كل ذكر من الضأن والمعز، وقل لهم: هل حَرَّم الله الأنثيين من الغنم؟ فإن قالوا: نعم، فقد كذبوا أيضًا؛ لأنهم لا يحرمون كل أنثى من ولد الضأن والمعز، وقل لهم: هل حَرَّم الله ما اشتملت عليه أرحام الأنثيين من الضأن والمعز من الحمل؟ فإن قالوا: نعم، فقد كذبوا أيضًا؛ لأنهم لا يحرمون كل حَمْل مِن ذلك، خبِّروني بعلم يدل على صحة ما ذهبتم إليه، إن كنتم صادقين فيما تنسبونه إلى ربكم.", "isBasmala": false, "translation_en": "Eight pairs: two of the sheep, and two of the goats. Say, \"Did He forbid the two males, or the two females, or what the wombs of the two females contain? Inform me with knowledge, if you are truthful.\"", "translation_id": "(yaitu) delapan binatang yang berpasangan, sepasang domba, sepasang dari kambing. Katakanlah: \"Apakah dua yang jantan yang diharamkan Allah ataukah dua yang betina, ataukah yang ada dalam kandungan dua betinanya?\" Terangkanlah kepadaku dengan berdasar pengetahuan jika kamu memang orang-orang yang benar,", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 144, "text": "وَمِنَ ٱلۡإِبِلِ ٱثۡنَیۡنِ وَمِنَ ٱلۡبَقَرِ ٱثۡنَیۡنِۗ قُلۡ ءَاۤلذَّكَرَیۡنِ حَرَّمَ أَمِ ٱلۡأُنثَیَیۡنِ أَمَّا ٱشۡتَمَلَتۡ عَلَیۡهِ أَرۡحَامُ ٱلۡأُنثَیَیۡنِۖ أَمۡ كُنتُمۡ شُهَدَاۤءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَـٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰا لِّیُضِلَّ ٱلنَّاسَ بِغَیۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝١٤٤", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "والأصناف الأربعة الأخرى: هي اثنان من الإبل ذكورًا وإناثًا، واثنان من البقر ذكورًا وإناثًا. قل -أيها الرسول- لأولئك المشركين: أحَرَّم الله الذكرين أم الأنثيين؟ أم حرَّم ما اشتملت عليه أرحام الأنثيين ذكورًا وإناثًا؟ أم كنتم أيها المشركون حاضرين، إذ وصاكم الله بهذا التحريم للأنعام، فلا أحد أشد ظلمًا ممن اختلق على الله الكذب؛ ليصرف الناس بجهله عن طريق الهدى. إن الله تعالى لا يوفق للرشد مَن تجاوز حدَّه، فكذب على ربه، وأضلَّ الناس.", "isBasmala": false, "translation_en": "And two of the camels, and two of the cattle. Say, \"Did He forbid the two males, or the two females, or what the wombs of the two females contain? Were you present when God enjoined this upon you?\" Who does greater wrong than he who invents lies and attributes them to God, in order to mislead people without knowledge? God does not guide the wicked people.", "translation_id": "dan sepasang dari unta dan sepasang dari lembu. Katakanlah: \"Apakah dua yang jantan yang diharamkan ataukah dua yang betina, ataukah yang ada dalam kandungan dua betinanya? Apakah kamu menyaksikan di waktu Allah menetapkan ini bagimu? Maka siapakah yang lebih zalim daripada orang-orang yang membuat-buat dusta terhadap Allah untuk menyesatkan manusia tanpa pengetahuan?\" Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang zalim.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 145, "text": "قُل لَّاۤ أَجِدُ فِی مَاۤ أُوحِیَ إِلَیَّ مُحَرَّمًا عَلَىٰ طَاعِمࣲ یَطۡعَمُهُۥۤ إِلَّاۤ أَن یَكُونَ مَیۡتَةً أَوۡ دَمࣰا مَّسۡفُوحًا أَوۡ لَحۡمَ خِنزِیرࣲ فَإِنَّهُۥ رِجۡسٌ أَوۡ فِسۡقًا أُهِلَّ لِغَیۡرِ ٱللَّهِ بِهِۦۚ فَمَنِ ٱضۡطُرَّ غَیۡرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ رَبَّكَ غَفُورࣱ رَّحِیمࣱ ۝١٤٥", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "قل -أيها الرسول-: إني لا أجد فيما أوحى الله إليَّ شيئًا محرمًا على من يأكله مما تذكرون أنه حُرِّم من الأنعام، إلا أن يكون قد مات بغير تذكية، أو يكون دمًا مراقًا، أو يكون لحم خنزير فإنه نجس، أو الذي كانت ذكاته خروجًا عن طاعة الله تعالى؛ كما إذا كان المذبوح قد ذكر عليه اسم غير الله عند الذبح. فمن اضطر إلى الأكل من هذه المحرمات بسبب الجوع الشديد غير طالب بأكله منها تلذذًا، ولا متجاوز حد الضرورة، فإن الله تعالى غفور له، رحيم به. وقد ثبت - فيما بعد - بالسنة تحريم كل ذي ناب من السباع، ومخلب من الطير، والحمر الأهلية، والكلاب.", "isBasmala": false, "translation_en": "Say, \"In what was revealed to me, I find nothing forbidden to a consumer who eats it, except carrion, or spilled blood, or the flesh of swine-because it is impure-or a sinful offering dedicated to other than God. But if someone is compelled by necessity, without being deliberate or malicious-your Lord is Forgiving and Merciful.", "translation_id": "Katakanlah: \"Tiadalah aku peroleh dalam wahyu yang diwahyukan kepadaku, sesuatu yang diharamkan bagi orang yang hendak memakannya, kecuali kalau makanan itu bangkai, atau darah yang mengalir atau daging babi -- karena sesungguhnya semua itu kotor -- atau binatang yang disembelih atas nama selain Allah. Barangsiapa yang dalam keadaan terpaksa, sedang dia tidak menginginkannya dan tidak (pula) melampaui batas, maka sesungguhnya Tuhanmu Maha Pengampun lagi Maha Penyayang\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 146, "text": "وَعَلَى ٱلَّذِینَ هَادُوا۟ حَرَّمۡنَا كُلَّ ذِی ظُفُرࣲۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَیۡهِمۡ شُحُومَهُمَاۤ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَاۤ أَوِ ٱلۡحَوَایَاۤ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمࣲۚ ذَ ٰلِكَ جَزَیۡنَـٰهُم بِبَغۡیِهِمۡۖ وَإِنَّا لَصَـٰدِقُونَ ۝١٤٦", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "واذكر -أيها الرسول- لهؤلاء المشركين ما حرمَّنا على اليهود من البهائم والطير: وهو كل ما لم يكن مشقوق الأصابع كالإبل والنَّعام، وشحوم البقر والغنم، إلا ما عَلِق من الشحم بظهورها أو أمعائها، أو اختلط بعظم الألْية والجنب ونحو ذلك. ذلك التحرم المذكور على اليهود عقوبة مِنَّا لهم بسبب أعمالهم السيئة، وإنَّا لصادقون فيما أخبرنا به عنهم.", "isBasmala": false, "translation_en": "For the Jews We forbade everything with claws. As of cattle and sheep: We forbade them their fat, except what adheres to their backs, or the entrails, or what is mixed with bone. This is how We penalized them for their inequity. We are indeed truthful.", "translation_id": "Dan kepada orang-orang Yahudi, Kami haramkan segala binatang yang berkuku dan dari sapi dan domba, Kami haramkan atas mereka lemak dari kedua binatang itu, selain lemak yang melekat di punggung keduanya atau yang di perut besar dan usus atau yang bercampur dengan tulang. Demikianlah Kami hukum mereka disebabkan kedurhakaan mereka; dan sesungguhnya Kami adalah Maha Benar.", "manzil": 2, "manzil_display": ""}], "148": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 147, "text": "فَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةࣲ وَ ٰسِعَةࣲ وَلَا یُرَدُّ بَأۡسُهُۥ عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِینَ ۝١٤٧", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "فإن كذبك -أيها الرسول- مخالفوك من المشركين واليهود، وغيرهم، فقل لهم: ربكم جل وعلا ذو رحمة واسعة، ولا يُدْفع عقابه عن القوم الذين أجرموا، فاكتسبوا الذنوب، واجترحوا السيئات. وفي هذا تهديد لهم لمخالفتهم الرسول صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "If they accuse you of lying, say, \"Your Lord is Possessor of infinite mercy, but His wrath cannot be averted from the guilty people.\"", "translation_id": "Maka jika mereka mendustakan kamu, katakanlah: \"Tuhanmu mempunyai rahmat yang luas; dan siksa-Nya tidak dapat ditolak dari kaum yang berdosa\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 148, "text": "سَیَقُولُ ٱلَّذِینَ أَشۡرَكُوا۟ لَوۡ شَاۤءَ ٱللَّهُ مَاۤ أَشۡرَكۡنَا وَلَاۤ ءَابَاۤؤُنَا وَلَا حَرَّمۡنَا مِن شَیۡءࣲۚ كَذَ ٰلِكَ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ حَتَّىٰ ذَاقُوا۟ بَأۡسَنَاۗ قُلۡ هَلۡ عِندَكُم مِّنۡ عِلۡمࣲ فَتُخۡرِجُوهُ لَنَاۤۖ إِن تَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ أَنتُمۡ إِلَّا تَخۡرُصُونَ ۝١٤٨", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "سيقول الذين أشركوا: لو أراد الله أن لا نشرك -نحن وآباؤنا- وأن لا نحرم شيئًا مِن دونه ما فعلنا ذلك، وردَّ الله عليهم ببيان أن هذه الشبهة قد أثارها الكفار مِن قبلهم، وكذَّبوا بها دعوة رسلهم، واستمَرُّوا على ذلك، حتى نزل بهم عذاب الله. قل لهم -أيها الرسول-: هل عندكم -فيما حرَّمتم من الأنعام والحرث، وفيما زعمتم من أن الله قد شاء لكم الكفر، ورضيه منكم وأحبه لكم- من علم صحيح فتظهروه لنا؟ إن تتبعون في أمور هذا الدين إلا مجرد الظن، وإن أنتم إلا تكذبون.", "isBasmala": false, "translation_en": "The polytheists will say, \"Had God willed, we would not have practiced idolatry, nor would have our forefathers, nor would we have prohibited anything.\" Likewise those before them lied, until they tasted Our might. Say, \"Do you have any knowledge that you can produce for us? You follow nothing but conjecture, and you only guess.\"", "translation_id": "Orang-orang yang mempersekutukan Tuhan, akan mengatakan: \"Jika Allah menghendaki, niscaya kami dan bapak-bapak kami tidak mempersekutukan-Nya dan tidak (pula) kami mengharamkan barang sesuatu apapun\". Demikian pulalah orang-orang sebelum mereka telah mendustakan (para rasul) sampai mereka merasakan siksaan Kami. Katakanlah: \"Adakah kamu mempunyai sesuatu pengetahuan sehingga dapat kamu mengemukakannya kepada Kami?\" Kamu tidak mengikuti kecuali persangkaan belaka, dan kamu tidak lain hanyalah berdusta.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 149, "text": "قُلۡ فَلِلَّهِ ٱلۡحُجَّةُ ٱلۡبَـٰلِغَةُۖ فَلَوۡ شَاۤءَ لَهَدَىٰكُمۡ أَجۡمَعِینَ ۝١٤٩", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "قل -أيها الرسول- لهم: فلله جل وعلا الحجة القاطعة التي يقطع بها ظنونكم، فلو شاء لوفَّقكم جميعًا إلى طريق الاستقامة.", "isBasmala": false, "translation_en": "Say, \"To God belongs the conclusive argument. Had He willed, He would have guided you all.\"", "translation_id": "Katakanlah: \"Allah mempunyai hujjah yang jelas lagi kuat; maka jika Dia menghendaki, pasti Dia memberi petunjuk kepada kamu semuanya\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 150, "text": "قُلۡ هَلُمَّ شُهَدَاۤءَكُمُ ٱلَّذِینَ یَشۡهَدُونَ أَنَّ ٱللَّهَ حَرَّمَ هَـٰذَاۖ فَإِن شَهِدُوا۟ فَلَا تَشۡهَدۡ مَعَهُمۡۚ وَلَا تَتَّبِعۡ أَهۡوَاۤءَ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ وَهُم بِرَبِّهِمۡ یَعۡدِلُونَ ۝١٥٠", "juz": 8, "hizb": "(*½ ح 15*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: هاتوا شهداءكم الذين يشهدون أن الله تعالى هو الذي حرَّم ما حرَّمتم من الحرث والأنعام، فإن شهدوا -كذبًا وزورًا- فلا تصدقهم، ولا توافق الذين حكَّموا أهواءهم، فكذبوا بآيات الله فيما ذهبوا إليه من تحريم ما أحل الله، وتحليل ما حرم الله، ولا تتبع الذين لا يصدقون بالحياة الآخرة ولا يعملون لها، والذين هم بربهم يشركون فيعبدون معه غيره.", "isBasmala": false, "translation_en": "Say, \"Produce your witnesses who would testify that God has prohibited this.\" If they testify, do not testify with them. And do not follow the whims of those who deny Our revelation, and those who do not believe in the Hereafter, and those who equate others with their Lord.", "translation_id": "Katakanlah: \"Bawalah kemari saksi-saksi kamu yang dapat mempersaksikan bahwasanya Allah telah mengharamkan (makanan yang kamu) haramkan ini\" Jika mereka mempersaksikan, maka janganlah kamu ikut pula menjadi saksi bersama mereka; dan janganlah kamu mengikuti hawa nafsu orang-orang yang mendustakan ayat-ayat Kami, dan orang-orang yang tidak beriman kepada kehidupan akhirat, sedang mereka mempersekutukan Tuhan mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 151, "text": "۞ قُلۡ تَعَالَوۡا۟ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَیۡكُمۡۖ أَلَّا تُشۡرِكُوا۟ بِهِۦ شَیۡـࣰٔاۖ وَبِٱلۡوَ ٰلِدَیۡنِ إِحۡسَـٰنࣰاۖ وَلَا تَقۡتُلُوۤا۟ أَوۡلَـٰدَكُم مِّنۡ إِمۡلَـٰقࣲ نَّحۡنُ نَرۡزُقُكُمۡ وَإِیَّاهُمۡۖ وَلَا تَقۡرَبُوا۟ ٱلۡفَوَ ٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُوا۟ ٱلنَّفۡسَ ٱلَّتِی حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ ذَ ٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَعۡقِلُونَ ۝١٥١", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "قل -أيها الرسول- لهم: تعالوا أتل ما حرم ربكم عليكم: أن لا تشركوا معه شيئًا من مخلوقاته في عبادته، بل اصرفوا جميع أنواع العبادة له وحده، كالخوف والرجاء والدعاء، وغير ذلك، وأن تحسنوا إلى الوالدين بالبر والدعاء ونحو ذلك من الإحسان، ولا تقتلوا أولادكم مِن أجل فقر نزل بكم؛ فإن الله يرزقكم وإياهم، ولا تقربوا ما كان ظاهرًا من كبير الآثام، وما كان خفيًّا، ولا تقتلوا النفس التي حرم الله قتلها إلا بالحق، وذلك في حال القصاص من القاتل أو الزنى بعد الإحصان أو الردة عن الإسلام، ذلكم المذكور مما نهاكم الله عنه، وعهد إليكم باجتنابه، ومما أمركم به، وصَّاكم به ربكم؛ لعلكم تعقلون أوامره ونواهيه.", "isBasmala": false, "translation_en": "Say, \"Come, let me tell you what your Lord has forbidden you: that you associate nothing with Him; that you honor your parents; that you do not kill your children because of poverty-We provide for you and for them; that you do not come near indecencies, whether outward or inward; and that you do not kill the soul which God has sanctified-except in the course of justice. All this He has enjoined upon you, so that you may understand.\"", "translation_id": "Katakanlah: \"Marilah kubacakan apa yang diharamkan atas kamu oleh Tuhanmu yaitu: janganlah kamu mempersekutukan sesuatu dengan Dia, berbuat baiklah terhadap kedua orang ibu bapa, dan janganlah kamu membunuh anak-anak kamu karena takut kemiskinan, Kami akan memberi rezeki kepadamu dan kepada mereka, dan janganlah kamu mendekati perbuatan-perbuatan yang keji, baik yang nampak di antaranya maupun yang tersembunyi, dan janganlah kamu membunuh jiwa yang diharamkan Allah (membunuhnya) melainkan dengan sesuatu (sebab) yang benar\". Demikian itu yang diperintahkan kepadamu supaya kamu memahami(nya).", "manzil": 2, "manzil_display": ""}], "149": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 152, "text": "وَلَا تَقۡرَبُوا۟ مَالَ ٱلۡیَتِیمِ إِلَّا بِٱلَّتِی هِیَ أَحۡسَنُ حَتَّىٰ یَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُوا۟ ٱلۡكَیۡلَ وَٱلۡمِیزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ وَإِذَا قُلۡتُمۡ فَٱعۡدِلُوا۟ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُوا۟ۚ ذَ ٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ ۝١٥٢", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "ولا تقربوا أيها الأوصياء مال اليتيم إلا بالحال التي تصلح بها أمواله ويَنْتَفِع بها، حتى يصل إلى سن البلوغ ويكون راشدًا، فإذا بلغ ذلك فسلموا إليه ماله، وأوفوا الكيل والوزن بالعدل الذي يكون به تمام الوفاء. وإذا بذلتم جهدكم فلا حرج عليكم فيما قد يكون من نقص، لا نكلف نفسًا إلا وسعها. وإذا قلتم فتحرَّوا في قولكم العدل دون ميل عن الحق في خبر أو شهادة أو حكم أو شفاعة، ولو كان الذي تعلق به القول ذا قرابة منكم، فلا تميلوا معه بغير حق، وأوفوا بما عهد الله به إليكم من الالتزام بشريعته. ذلكم المتلوُّ عليكم من الأحكام، وصَّاكم به ربكم؛ رجاء أن تتذكروا عاقبة أمركم.", "isBasmala": false, "translation_en": "And do not come near the property of the orphan, except with the best intentions, until he reaches maturity. And give full weight and full measure, equitably. We do not burden any soul beyond its capacity. And when you speak, be fair, even if it concerns a close relative. And fulfill your covenant with God. All this He has enjoined upon you, so that you may take heed.", "translation_id": "Dan janganlah kamu dekati harta anak yatim, kecuali dengan cara yang lebih bermanfaat, hingga sampai ia dewasa. Dan sempurnakanlah takaran dan timbangan dengan adil. Kami tidak memikulkan beban kepada sesorang melainkan sekedar kesanggupannya. Dan apabila kamu berkata, maka hendaklah kamu berlaku adil, kendatipun ia adalah kerabat(mu), dan penuhilah janji Allah. Yang demikian itu diperintahkan Allah kepadamu agar kamu ingat.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 153, "text": "وَأَنَّ هَـٰذَا صِرَ ٰطِی مُسۡتَقِیمࣰا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُوا۟ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِیلِهِۦۚ ذَ ٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ ۝١٥٣", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "ومما وصاكم الله به أن هذا الإسلام هو طريق الله تعالى المستقيم فاسلكوه، ولا تسلكوا سبل الضلال، فتفرقكم، وتبعدكم عن سبيل الله المستقيم. ذلكم التوجه نحو الطريق المستقيم هو الذي وصَّاكم الله به؛ لتتقوا عذابه بفعل أوامره، واجتناب نواهيه.", "isBasmala": false, "translation_en": "This is My path, straight, so follow it. And do not follow the other paths, lest they divert you from His path. All this He has enjoined upon you, that you may refrain from wrongdoing.", "translation_id": "dan bahwa (yang Kami perintahkan ini) adalah jalan-Ku yang lurus, maka ikutilah dia, dan janganlah kamu mengikuti jalan-jalan (yang lain), karena jalan-jalan itu mencerai beraikan kamu dari jalan-Nya. Yang demikian itu diperintahkan Allah agar kamu bertakwa.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 154, "text": "ثُمَّ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ تَمَامًا عَلَى ٱلَّذِیۤ أَحۡسَنَ وَتَفۡصِیلࣰا لِّكُلِّ شَیۡءࣲ وَهُدࣰى وَرَحۡمَةࣰ لَّعَلَّهُم بِلِقَاۤءِ رَبِّهِمۡ یُؤۡمِنُونَ ۝١٥٤", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "ثم قل -أيها الرسول- لهؤلاء المشركين: إن الله تعالى هو الذي أتى موسى التوراة تمامًا لنعمته على المحسنين من أهل ملته، وتفصيلا لكل شيء من أمور دينهم، وهدى ودلالة على الطريق المستقيم ورحمة لهم؛ رجاء أن يصدِّقوا بالبعث بعد الموت والحساب والجزاء، ويعملوا لذلك.", "isBasmala": false, "translation_en": "Then We gave Moses the Scripture, perfect for the righteous, and explaining everything clearly, and a beacon, and mercy, that they may believe in the encounter with their Lord.", "translation_id": "Kemudian Kami telah memberikan Al Kitab (Taurat) kepada Musa untuk menyempurnakan (nikmat Kami) kepada orang yang berbuat kebaikan, dan untuk menjelaskan segala sesuatu dan sebagai petunjuk dan rahmat, agar mereka beriman (bahwa) mereka akan menemui Tuhan mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 155, "text": "وَهَـٰذَا كِتَـٰبٌ أَنزَلۡنَـٰهُ مُبَارَكࣱ فَٱتَّبِعُوهُ وَٱتَّقُوا۟ لَعَلَّكُمۡ تُرۡحَمُونَ ۝١٥٥", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "وهذا القرآن كتاب أنزلناه على نبينا محمد صلى الله عليه وسلم، خيره كثير فاتبعوه فيما يأمر به وينهى عنه، واتقوا الله أن تخالفوا له أمرًا؛ رجاء أن ترحموا فتنجوا من عذابه، وتظفروا بثوابه.", "isBasmala": false, "translation_en": "This too is a blessed Scripture that We revealed; so follow it, and be righteous, that you may receive mercy.", "translation_id": "Dan Al-Quran itu adalah kitab yang Kami turunkan yang diberkati, maka ikutilah dia dan bertakwalah agar kamu diberi rahmat.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 156, "text": "أَن تَقُولُوۤا۟ إِنَّمَاۤ أُنزِلَ ٱلۡكِتَـٰبُ عَلَىٰ طَاۤىِٕفَتَیۡنِ مِن قَبۡلِنَا وَإِن كُنَّا عَن دِرَاسَتِهِمۡ لَغَـٰفِلِینَ ۝١٥٦", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "وأنزلنا هذا القرآن؛ لئلا تقولوا -يا كفار العرب-: إنما أُنزل الكتاب من السماء على اليهود والنصارى، وقد كنا عن قراءة كتبهم في شغل، ونحن ليس لنا بها علم ولا معرفة.", "isBasmala": false, "translation_en": "Lest you say, \"The Scripture was revealed to two parties before us, and we were unaware of their teachings.\"", "translation_id": "(Kami turunkan al-Quran itu) agar kamu (tidak) mengatakan: \"Bahwa kitab itu hanya diturunkan kepada dua golongan saja sebelum kami, dan sesungguhnya kami tidak memperhatikan apa yang mereka baca.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 157, "text": "أَوۡ تَقُولُوا۟ لَوۡ أَنَّاۤ أُنزِلَ عَلَیۡنَا ٱلۡكِتَـٰبُ لَكُنَّاۤ أَهۡدَىٰ مِنۡهُمۡۚ فَقَدۡ جَاۤءَكُم بَیِّنَةࣱ مِّن رَّبِّكُمۡ وَهُدࣰى وَرَحۡمَةࣱۚ فَمَنۡ أَظۡلَمُ مِمَّن كَذَّبَ بِـَٔایَـٰتِ ٱللَّهِ وَصَدَفَ عَنۡهَاۗ سَنَجۡزِی ٱلَّذِینَ یَصۡدِفُونَ عَنۡ ءَایَـٰتِنَا سُوۤءَ ٱلۡعَذَابِ بِمَا كَانُوا۟ یَصۡدِفُونَ ۝١٥٧", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "ولئلا تقولوا -أيها المشركون-: لو أنَّا أُنزل علينا كتاب من السماء، كما أُنزل على اليهود والنصارى، لكنَّا أشدَّ استقامة على طريق الحق منهم، فقد جاءكم كتاب بلسانكم عربي مبين، وذلك حجة واضحة مِن ربكم وإرشاد إلى طريق الحق، ورحمةٌ لهذه الأمة. فلا أحد أشد ظلمًا وعدوانًا ممن كذَّب بحجج الله تعالى وأعرض عنها!! فهؤلاء المعرضون سنعاقبهم عقابًا شديدًا في نار جهنم؛ بسبب إعراضهم عن آياتنا، وصدِّهم عن سبيلنا.", "isBasmala": false, "translation_en": "Or lest you say, \"Had the Scripture been revealed to us, we would have been better guided than they.\" Clarification has come to you from your Lord, and guidance, and mercy. Who then does greater wrong than he who gives the lie to God's messages, and turns away from them? We will repay those who turn away from Our messages with the worst kind of punishment, because of their turning away.", "translation_id": "Atau agar kamu (tidak) mengatakan: \"Sesungguhnya jikalau kitab ini diturunkan kepada kami, tentulah kami lebih mendapat petunjuk dari mereka\". Sesungguhnya telah datang kepada kamu keterangan yang nyata dari Tuhanmu, petunjuk dan rahmat. Maka siapakah yang lebih zalim daripada orang yang mendustakan ayat-ayat Allah dan berpaling daripadanya? Kelak Kami akan memberi balasan kepada orang-orang yang berpaling dari ayat-ayat Kami dengan siksa yang buruk, disebabkan mereka selalu berpaling.", "manzil": 2, "manzil_display": ""}], "150": [{"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 158, "text": "هَلۡ یَنظُرُونَ إِلَّاۤ أَن تَأۡتِیَهُمُ ٱلۡمَلَـٰۤىِٕكَةُ أَوۡ یَأۡتِیَ رَبُّكَ أَوۡ یَأۡتِیَ بَعۡضُ ءَایَـٰتِ رَبِّكَۗ یَوۡمَ یَأۡتِی بَعۡضُ ءَایَـٰتِ رَبِّكَ لَا یَنفَعُ نَفۡسًا إِیمَـٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِیۤ إِیمَـٰنِهَا خَیۡرࣰاۗ قُلِ ٱنتَظِرُوۤا۟ إِنَّا مُنتَظِرُونَ ۝١٥٨", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "هل ينتظر الذين أعرضوا وصدوا عن سبيل الله إلا أن يأتيهم ملك الموت وأعوانه لقبض أرواحهم، أو يأتي ربك -أيها الرسول- للفصل بين عباده يوم القيامة، أو يأتي بعض أشراط الساعة وعلاماتها الدالة على مجيئها، وهي طلوع الشمس من مغربها؟ فحين يكون ذلك لا ينفع نفسا إيمانها، إن لم تكن آمنت من قبل، ولا يُقبل منها إن كانت مؤمنة كسب عمل صالح إن لم تكن عاملة به قبل ذلك. قل لهم -أيها الرسول-: انتظروا مجيء ذلك؛ لتعلموا المحق من المبطل، والمسيء من المحسن، إنا منتظرون ذلك.", "isBasmala": false, "translation_en": "Are they waiting for anything but for the angels to come to them, or for your Lord to arrive, or for some of your Lord's signs to come? On the Day when some of your Lord's signs come, no soul will benefit from its faith unless it had believed previously, or had earned goodness through its faith. Say, \"Wait, we too are waiting.\"", "translation_id": "Yang mereka nanti-nanti tidak lain hanyalah kedatangan malaikat kepada mereka (untuk mencabut nyawa mereka) atau kedatangan (siksa) Tuhanmu atau kedatangan beberapa ayat Tuhanmu. Pada hari datangnya ayat dari Tuhanmu, tidaklah bermanfaat lagi iman seseorang kepada dirinya sendiri yang belum beriman sebelum itu, atau dia (belum) mengusahakan kebaikan dalam masa imannya. Katakanlah: \"Tunggulah olehmu sesungguhnya Kamipun menunggu (pula)\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 159, "text": "إِنَّ ٱلَّذِینَ فَرَّقُوا۟ دِینَهُمۡ وَكَانُوا۟ شِیَعࣰا لَّسۡتَ مِنۡهُمۡ فِی شَیۡءٍۚ إِنَّمَاۤ أَمۡرُهُمۡ إِلَى ٱللَّهِ ثُمَّ یُنَبِّئُهُم بِمَا كَانُوا۟ یَفۡعَلُونَ ۝١٥٩", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "إن الذين فرقوا دينهم بعد ما كانوا مجتمعين على توحيد الله والعمل بشرعه، فأصبحوا فرقا وأحزابا، إنك -أيها الرسول- بريء منهم، إنما حكمهم إلى الله تعالى، ثم يخبرهم بأعمالهم، فيجازي من تاب منهم وأحسن بإحسانه، ويعاقب المسيء بإساءته.", "isBasmala": false, "translation_en": "As for those who divided their religion and became sects-you have nothing to do with them. Their case rests with God; then He will inform them of what they used to do.", "translation_id": "Sesungguhnya orang-orang yang memecah belah agama-Nya dan mereka menjadi bergolongan, tidak ada sedikitpun tanggung jawabmu kepada mereka. Sesungguhnya urusan mereka hanyalah terserah kepada Allah, kemudian Allah akan memberitahukan kepada mereka apa yang telah mereka perbuat.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 160, "text": "مَن جَاۤءَ بِٱلۡحَسَنَةِ فَلَهُۥ عَشۡرُ أَمۡثَالِهَاۖ وَمَن جَاۤءَ بِٱلسَّیِّئَةِ فَلَا یُجۡزَىٰۤ إِلَّا مِثۡلَهَا وَهُمۡ لَا یُظۡلَمُونَ ۝١٦٠", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "من لقي ربه يوم القيامة بحسنة من الأعمال الصالحة فله عشر حسنات أمثالها، ومن لقي ربه بسيئة فلا يعاقب إلا بمثلها، وهم لا يظلمون مثقال ذرة.", "isBasmala": false, "translation_en": "Whoever comes up with a good deed will have ten times its like; and whoever comes up with an evil deed will be repaid only with its equivalent-they will not be wronged.", "translation_id": "Barangsiapa membawa amal yang baik, maka baginya (pahala) sepuluh kali lipat amalnya; dan barangsiapa yang membawa perbuatan jahat maka dia tidak diberi pembalasan melainkan seimbang dengan kejahatannya, sedang mereka sedikitpun tidak dianiaya (dirugikan).", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 161, "text": "قُلۡ إِنَّنِی هَدَىٰنِی رَبِّیۤ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ دِینࣰا قِیَمࣰا مِّلَّةَ إِبۡرَ ٰهِیمَ حَنِیفࣰاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ ۝١٦١", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: إنني أرشدني ربي إلى الطريق القويم الموصل إلى جنته، وهو دين الإسلام القائم بأمر الدنيا والآخرة، وهو دين التوحيد دين إبراهيم عليه السلام، وما كان إبراهيم عليه السلام من المشركين مع الله غيره.", "isBasmala": false, "translation_en": "Say, \"My Lord has guided me to a straight path, an upright religion, the creed of Abraham the Monotheist, who was not a polytheist.\"", "translation_id": "Katakanlah: \"Sesungguhnya aku telah ditunjuki oleh Tuhanku kepada jalan yang lurus, (yaitu) agama yang benar, agama Ibrahim yang lurus, dan Ibrahim itu bukanlah termasuk orang-orang musyrik\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 162, "text": "قُلۡ إِنَّ صَلَاتِی وَنُسُكِی وَمَحۡیَایَ وَمَمَاتِی لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٦٢", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: إن صلاتي، ونسكي، أي: ذبحي لله وحده، لا للأصنام، ولا للأموات، ولا للجن، ولا لغير ذلك مما تذبحونه لغير الله، وعلى غير اسمه كما تفعلون، وحياتي وموتي لله تعالى رب العالمين.", "isBasmala": false, "translation_en": "Say, \"My prayer and my worship, and my life and my death, are devoted to God, the Lord of the Worlds.", "translation_id": "Katakanlah: sesungguhnya sembahyangku, ibadatku, hidupku dan matiku hanyalah untuk Allah, Tuhan semesta alam.", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 163, "text": "لَا شَرِیكَ لَهُۥۖ وَبِذَ ٰلِكَ أُمِرۡتُ وَأَنَا۠ أَوَّلُ ٱلۡمُسۡلِمِینَ ۝١٦٣", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "لا شريك له في ألوهيته ولا في ربوبيته ولا في صفاته وأسمائه، وبذلك التوحيد الخالص أمرني ربي جل وعلا وأنا أول من أقر وانقاد لله من هذه الأمة.", "isBasmala": false, "translation_en": "No associate has He. Thus I am commanded, and I am the first of those who submit.", "translation_id": "Tiada sekutu bagi-Nya; dan demikian itulah yang diperintahkan kepadaku dan aku adalah orang yang pertama-tama menyerahkan diri (kepada Allah)\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 164, "text": "قُلۡ أَغَیۡرَ ٱللَّهِ أَبۡغِی رَبࣰّا وَهُوَ رَبُّ كُلِّ شَیۡءࣲۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَیۡهَاۚ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَیُنَبِّئُكُم بِمَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ ۝١٦٤", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "قل -أيها الرسول-: أغير الله أطلب إلها، وهو خالق كل شيء ومالكه ومدبره؟ ولا يعمل أي إنسان عملا سيئا إلا كان إثمه عليه، ولا تحمل نفس آثمة إثم نفس أخرى، ثم إلى ربكم معادكم يوم القيامة، فيخبركم بما كنتم تختلفون فيه من أمر الدين.", "isBasmala": false, "translation_en": "Say, \"Am I to seek a Lord other than God, when He is the Lord of all things?\" No soul gets except what it is due, and no soul bears the burdens of another. Then to your Lord is your return, then He will inform you regarding your disputes.", "translation_id": "Katakanlah: \"Apakah aku akan mencari Tuhan selain Allah, padahal Dia adalah Tuhan bagi segala sesuatu. Dan tidaklah seorang membuat dosa melainkan kemudharatannya kembali kepada dirinya sendiri; dan seorang yang berdosa tidak akan memikul dosa orang lain. Kemudian kepada Tuhanmulah kamu kembali, dan akan diberitakan-Nya kepadamu apa yang kamu perselisihkan\".", "manzil": 2, "manzil_display": ""}, {"sura": 6, "sura_name": "الأنعام", "revelation": "Makkiyah", "aya": 165, "text": "وَهُوَ ٱلَّذِی جَعَلَكُمۡ خَلَـٰۤىِٕفَ ٱلۡأَرۡضِ وَرَفَعَ بَعۡضَكُمۡ فَوۡقَ بَعۡضࣲ دَرَجَـٰتࣲ لِّیَبۡلُوَكُمۡ فِی مَاۤ ءَاتَىٰكُمۡۗ إِنَّ رَبَّكَ سَرِیعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورࣱ رَّحِیمُۢ ۝١٦٥", "juz": 8, "hizb": "(*¾ ح 15*)", "tafsir": "والله سبحانه هو الذي جعلكم تخلفون من سبقكم في الأرض بعد أن أهلكهم الله، واستخلفكم فيها؛ لتعمروها بعدهم بطاعة ربكم، ورفع بعضكم في الرزق والقوة فوق بعض درجات، ليبلوكم فيما أعطاكم من نعمه، فيظهر للناس الشاكر من غيره. إن ربك سريع العقاب لمن كفر به وعصاه، وإنه لغفور لمن آمن به وعمل صالحا وتاب من الموبقات، رحيم به، والغفور والرحيم اسمان كريمان من أسماء الله الحسنى.", "isBasmala": false, "translation_en": "It is He who made you successors on the earth, and raised some of you in ranks over others, in order to test you through what He has given you. Your Lord is Quick in retribution, and He is Forgiving and Merciful.", "translation_id": "Dan Dialah yang menjadikan kamu penguasa-penguasa di bumi dan Dia meninggikan sebahagian kamu atas sebahagian (yang lain) beberapa derajat, untuk mengujimu tentang apa yang diberikan-Nya kepadamu. Sesungguhnya Tuhanmu amat cepat siksaan-Nya dan sesungguhnya Dia Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}], "151": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 9, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 1, "text": "۞ الۤمۤصۤ ۝١", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Meem, Saad.", "translation_id": "Alif laam mim shaad.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 2, "text": "كِتَـٰبٌ أُنزِلَ إِلَیۡكَ فَلَا یَكُن فِی صَدۡرِكَ حَرَجࣱ مِّنۡهُ لِتُنذِرَ بِهِۦ وَذِكۡرَىٰ لِلۡمُؤۡمِنِینَ ۝٢", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "هذا القرآن كتاب عظيم أنزله الله عليك -أيها الرسول- فلا يكن في صدرك شك منه في أنه أنزل من عند الله، ولا تتحرج في إبلاغه والإنذار به، أنزلناه إليك؛ لتخوف به الكافرين وتذكر المؤمنين.", "isBasmala": false, "translation_en": "A Scripture was revealed to you, so let there be no anxiety in your heart because of it. You are to warn with it-and a reminder for the believers.", "translation_id": "Ini adalah sebuah kitab yang diturunkan kepadamu, maka janganlah ada kesempitan di dalam dadamu karenanya, supaya kamu memberi peringatan dengan kitab itu (kepada orang kafir), dan menjadi pelajaran bagi orang-orang yang beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 3, "text": "ٱتَّبِعُوا۟ مَاۤ أُنزِلَ إِلَیۡكُم مِّن رَّبِّكُمۡ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦۤ أَوۡلِیَاۤءَۗ قَلِیلࣰا مَّا تَذَكَّرُونَ ۝٣", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "اتبعوا -أيها الناس- ما أُنزل إليكم من ربكم من الكتاب والسنة بامتثال الأوامر واجتناب النواهي، ولا تتبعوا من دون الله أولياء كالشياطين والأحبار والرهبان. إنكم قليلا ما تتعظون، وتعتبرون، فترجعون إلى الحق.", "isBasmala": false, "translation_en": "Follow what is revealed to you from your Lord, and do not follow other masters beside Him. Little you recollect.", "translation_id": "Ikutilah apa yang diturunkan kepadamu dari Tuhanmu dan janganlah kamu mengikuti pemimpin-pemimpin selain-Nya. Amat sedikitlah kamu mengambil pelajaran (daripadanya).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 4, "text": "وَكَم مِّن قَرۡیَةٍ أَهۡلَكۡنَـٰهَا فَجَاۤءَهَا بَأۡسُنَا بَیَـٰتًا أَوۡ هُمۡ قَاۤىِٕلُونَ ۝٤", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "وكثير من القرى أهلكنا أهلها بسبب مخالفة رسلنا وتكذيبهم، فأعقبهم ذلك خزي الدنيا موصولا بذلِّ الآخرة، فجاءهم عذابنا مرة وهم نائمون ليلا ومرة وهم نائمون نهارًا. وخَصَّ الله هذين الوقتين؛ لأنهما وقتان للسكون والاستراحة، فمجيء العذاب فيهما أفظع وأشد.", "isBasmala": false, "translation_en": "How many a town have We destroyed? Our might came upon them by night, or while they were napping.", "translation_id": "Betapa banyaknya negeri yang telah Kami binasakan, maka datanglah siksaan Kami (menimpa penduduk)nya di waktu mereka berada di malam hari, atau di waktu mereka beristirahat di tengah hari.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 5, "text": "فَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَاۤءَهُم بَأۡسُنَاۤ إِلَّاۤ أَن قَالُوۤا۟ إِنَّا كُنَّا ظَـٰلِمِینَ ۝٥", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "فما كان قولهم عند مجيء العذاب إلا الإقرار بالذنوب والإساءة، وأنهم حقيقون بالعذاب الذي نزل بهم.", "isBasmala": false, "translation_en": "When Our might came upon them, their only cry was, \"We were indeed wrongdoers.\"", "translation_id": "Maka tidak adalah keluhan mereka di waktu datang kepada mereka siksaan Kami, kecuali mengatakan: \"Sesungguhnya kami adalah orang-orang yang zalim\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 6, "text": "فَلَنَسۡـَٔلَنَّ ٱلَّذِینَ أُرۡسِلَ إِلَیۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِینَ ۝٦", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "فلنسألن الأمم الذي أرسل إليهم المرسلون: ماذا أجبتم رسلنا إليكم؟ ولنسْألَنَّ المرسلين عن تبليغهم لرسالات ربهم، وعمَّا أجابتهم به أممهم.", "isBasmala": false, "translation_en": "We will question those to whom messengers were sent, and We will question the messengers.", "translation_id": "Maka sesungguhnya Kami akan menanyai umat-umat yang telah diutus rasul-rasul kepada mereka dan sesungguhnya Kami akan menanyai (pula) rasul-rasul (Kami),", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 7, "text": "فَلَنَقُصَّنَّ عَلَیۡهِم بِعِلۡمࣲۖ وَمَا كُنَّا غَاۤىِٕبِینَ ۝٧", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "فلَنقُصَّنَّ على الخلق كلهم ما عملوا بعلم منا لأعمالهم في الدنيا فيما أمرناهم به، وما نهيناهم عنه، وما كنا غائبين عنهم في حال من الأحوال.", "isBasmala": false, "translation_en": "We will narrate to them with knowledge, for We were never absent.", "translation_id": "maka sesungguhnya akan Kami kabarkan kepada mereka (apa-apa yang telah mereka perbuat), sedang (Kami) mengetahui (keadaan mereka), dan Kami sekali-kali tidak jauh (dari mereka).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 8, "text": "وَٱلۡوَزۡنُ یَوۡمَىِٕذٍ ٱلۡحَقُّۚ فَمَن ثَقُلَتۡ مَوَ ٰزِینُهُۥ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝٨", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "ووزن أعمال الناس يوم القيامة يكون بميزان حقيقي بالعدل والقسط الذي لا ظلم فيه، فمن ثقلت موازين أعماله -لكثرة حسناته- فأولئك هم الفائزون.", "isBasmala": false, "translation_en": "The scales on that Day will be just. Those whose weights are heavy-it is they who are the successful.", "translation_id": "Timbangan pada hari itu ialah kebenaran (keadilan), maka barangsiapa berat timbangan kebaikannya, maka mereka itulah orang-orang yang beruntung.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 9, "text": "وَمَنۡ خَفَّتۡ مَوَ ٰزِینُهُۥ فَأُو۟لَـٰۤىِٕكَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔایَـٰتِنَا یَظۡلِمُونَ ۝٩", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "ومن خَفَّتْ موازين أعماله -لكثرة سيئاته- فأولئك هم الذين أضاعوا حظَّهم من رضوان الله تعالى، بسبب تجاوزهم الحد بجحد آيات الله تعالى وعدم الانقياد لها.", "isBasmala": false, "translation_en": "But as for those whose weights are light-it is they who have lost their souls, because they used to mistreat Our revelations.", "translation_id": "Dan siapa yang ringan timbangan kebaikannya, maka itulah orang-orang yang merugikan dirinya sendiri, disebabkan mereka selalu mengingkari ayat-ayat Kami.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 10, "text": "وَلَقَدۡ مَكَّنَّـٰكُمۡ فِی ٱلۡأَرۡضِ وَجَعَلۡنَا لَكُمۡ فِیهَا مَعَـٰیِشَۗ قَلِیلࣰا مَّا تَشۡكُرُونَ ۝١٠", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "ولقد مكَّنَّا لكم -أيها الناس- في الأرض، وجعلناها قرارًا لكم، وجعلنا لكم فيها ما تعيشون به من مطاعم ومشارب، ومع ذلك فشكركم لنعم الله قليل.", "isBasmala": false, "translation_en": "We have established you firmly on earth, and made for you in it livelihood-but rarely do you give thanks.", "translation_id": "Sesungguhnya Kami telah menempatkan kamu sekalian di muka bumi dan Kami adakan bagimu di muka bumi (sumber) penghidupan. Amat sedikitlah kamu bersyukur.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 11, "text": "وَلَقَدۡ خَلَقۡنَـٰكُمۡ ثُمَّ صَوَّرۡنَـٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ لَمۡ یَكُن مِّنَ ٱلسَّـٰجِدِینَ ۝١١", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "ولقد أنعمنا عليكم بخلق أصلكم -وهو أبوكم آدم من العدم- ثم صوَّرناه على هيئته المفضلة على كثير من الخلق، ثم أمرنا ملائكتنا عليهم السلام بالسجود له -إكرامًا واحترامًا وإظهارًا لفضل آدم- فسجدوا جميعًا، لكنَّ إبليس الذي كان معهم لم يكن من الساجدين لآدم؛ حسدًا له على هذا التكريم العظيم.", "isBasmala": false, "translation_en": "We created you, then We shaped you, then We said to the angels, \"Bow down before Adam;\" so they bowed down, except for Satan; he was not of those who bowed down.", "translation_id": "Sesungguhnya Kami telah menciptakan kamu (Adam), lalu Kami bentuk tubuhmu, kemudian Kami katakan kepada para malaikat: \"Bersujudlah kamu kepada Adam\", maka merekapun bersujud kecuali iblis. Dia tidak termasuk mereka yang bersujud.", "manzil": 2, "manzil_display": ""}], "152": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 12, "text": "قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَیۡرࣱ مِّنۡهُ خَلَقۡتَنِی مِن نَّارࣲ وَخَلَقۡتَهُۥ مِن طِینࣲ ۝١٢", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قال تعالى منكرًا على إبليس تَرْكَ السجود: ما منعك ألا تسجد إذ أمرتك؟ فقال إبليس: أنا أفضل منه خلقًا؛ لأني مخلوق من نار، وهو مخلوق من طين. فرأى أن النار أشرف من الطين.", "isBasmala": false, "translation_en": "He said, \"What prevented you from bowing down when I have commanded you?\" He said, \"I am better than he; You created me from fire, and You created him from mud.\"", "translation_id": "Allah berfirman: \"Apakah yang menghalangimu untuk bersujud (kepada Adam) di waktu Aku menyuruhmu?\" Menjawab iblis \"Saya lebih baik daripadanya: Engkau ciptakan saya dari api sedang dia Engkau ciptakan dari tanah\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 13, "text": "قَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا یَكُونُ لَكَ أَن تَتَكَبَّرَ فِیهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّـٰغِرِینَ ۝١٣", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قال الله لإبليس: فاهبط من الجنة، فما يصح لك أن تتكبر فيها، فاخرج من الجنة، إنك من الذليلين الحقيرين.", "isBasmala": false, "translation_en": "He said, \"Get down from it! It is not for you to act arrogantly in it. Get out! You are one of the lowly!\"", "translation_id": "Allah berfirman: \"Turunlah kamu dari surga itu; karena kamu sepatutnya menyombongkan diri di dalamnya, maka keluarlah, sesungguhnya kamu termasuk orang-orang yang hina\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 14, "text": "قَالَ أَنظِرۡنِیۤ إِلَىٰ یَوۡمِ یُبۡعَثُونَ ۝١٤", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قال إبليس لله -جل وعلا- حينما يئس من رحمته: أمهلني إلى يوم البعث؛ وذلك لأتمكن من إغواء مَن أقدر عليه من بني آدم.", "isBasmala": false, "translation_en": "He said, \"Give me respite, until the Day they are resurrected.\"", "translation_id": "Iblis menjawab: \"Beri tangguhlah saya sampai waktu mereka dibangkitkan\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 15, "text": "قَالَ إِنَّكَ مِنَ ٱلۡمُنظَرِینَ ۝١٥", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قال الله تعالى: إنك ممن كتبتُ عليهم تأخير الأجل إلى النفخة الأولى في القرن، إذ يموت الخلق كلهم.", "isBasmala": false, "translation_en": "He said, \"You are of those given respite.\"", "translation_id": "Allah berfirman: \"Sesungguhnya kamu termasuk mereka yang diberi tangguh\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 16, "text": "قَالَ فَبِمَاۤ أَغۡوَیۡتَنِی لَأَقۡعُدَنَّ لَهُمۡ صِرَ ٰطَكَ ٱلۡمُسۡتَقِیمَ ۝١٦", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قال إبليس لعنه الله: فبسبب ما أضللتني لأجتهدنَّ في إغواء بني آدم عن طريقك القويم، ولأصدَّنَّهم عن الإسلام الذي فطرتهم عليه.", "isBasmala": false, "translation_en": "He said, \"Because you have lured me, I will waylay them on Your straight path.", "translation_id": "Iblis menjawab: \"Karena Engkau telah menghukum saya tersesat, saya benar-benar akan (menghalang-halangi) mereka dari jalan Engkau yang lurus,", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 17, "text": "ثُمَّ لَـَٔاتِیَنَّهُم مِّنۢ بَیۡنِ أَیۡدِیهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَیۡمَـٰنِهِمۡ وَعَن شَمَاۤىِٕلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَـٰكِرِینَ ۝١٧", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "ثم لآتينَّهم من جميع الجهات والجوانب، فأصدهم عن الحق، وأُحسِّن لهم الباطل، وأرغبهم في الدنيا، وأشككهم في الآخرة، ولا تجد أكثر بني آدم شاكرين لك نعمتك.", "isBasmala": false, "translation_en": "Then I will come at them from before them, and from behind them, and from their right, and from their left; and you will not find most of them appreciative.\"", "translation_id": "kemudian saya akan mendatangi mereka dari muka dan dari belakang mereka, dari kanan dan dari kiri mereka. Dan Engkau tidak akan mendapati kebanyakan mereka bersyukur (taat).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 18, "text": "قَالَ ٱخۡرُجۡ مِنۡهَا مَذۡءُومࣰا مَّدۡحُورࣰاۖ لَّمَن تَبِعَكَ مِنۡهُمۡ لَأَمۡلَأَنَّ جَهَنَّمَ مِنكُمۡ أَجۡمَعِینَ ۝١٨", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قال الله تعالى لإبليس: اخرج من الجنة ممقوتًا مطرودًا، لأملأنَّ جهنم منك وممن تبعك من بني آدم أجمعين.", "isBasmala": false, "translation_en": "He said, \"Get out of it, despised and vanquished. Whoever among them follows you-I will fill up Hell with you all.", "translation_id": "Allah berfirman: \"Keluarlah kamu dari surga itu sebagai orang terhina lagi terusir. Sesungguhnya barangsiapa di antara mereka mengikuti kamu, benar-benar Aku akan mengisi neraka Jahannam dengan kamu semuanya\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 19, "text": "وَیَـٰۤـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَیۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِینَ ۝١٩", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "ويا آدم اسكن أنت وزوجك حواء الجنة، فكُلا من ثمارها حيث شئتما، ولا تأكلا من ثمرة شجرة (عَيَّنها لهما)، فإن فعلتما ذلك كنتما من الظالمين المتجاوزين حدود الله.", "isBasmala": false, "translation_en": "And you, Adam, inhabit the Garden, you and your wife, and eat whatever you wish; but do not approach this tree, lest you become sinners.\"", "translation_id": "(Dan Allah berfirman): \"Hai Adam bertempat tinggallah kamu dan isterimu di surga serta makanlah olehmu berdua (buah-buahan) di mana saja yang kamu sukai, dan janganlah kamu berdua mendekati pohon ini, lalu menjadilah kamu berdua termasuk orang-orang yang zalim\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 20, "text": "فَوَسۡوَسَ لَهُمَا ٱلشَّیۡطَـٰنُ لِیُبۡدِیَ لَهُمَا مَا وُۥرِیَ عَنۡهُمَا مِن سَوۡءَ ٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَـٰذِهِ ٱلشَّجَرَةِ إِلَّاۤ أَن تَكُونَا مَلَكَیۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَـٰلِدِینَ ۝٢٠", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "فألقى الشيطان لآدم وحواء وسوسة لإيقاعهما في معصية الله تعالى بالأكل من تلك الشجرة التي نهاهما الله عنها؛ لتكون عاقبتهما انكشاف ما سُتر من عوراتهما، وقال لهما في محاولة المكر بهما: إنما نهاكما ربكما عن الأكل مِن ثمر هذه الشجرة مِن أجل أن لا تكونا ملَكين، ومِن أجل أن لا تكونا من الخالدين في الحياة.", "isBasmala": false, "translation_en": "But Satan whispered to them, to reveal to them their nakedness, which was invisible to them. He said, \"Your Lord has only forbidden you this tree, lest you become angels, or become immortals.\"", "translation_id": "Maka syaitan membisikkan pikiran jahat kepada keduanya untuk menampakkan kepada keduanya apa yang tertutup dari mereka yaitu auratnya dan syaitan berkata: \"Tuhan kamu tidak melarangmu dan mendekati pohon ini, melainkan supaya kamu berdua tidak menjadi malaikat atau tidak menjadi orang-orang yang kekal (dalam surga)\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 21, "text": "وَقَاسَمَهُمَاۤ إِنِّی لَكُمَا لَمِنَ ٱلنَّـٰصِحِینَ ۝٢١", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "وأقسم الشيطان لآدم وحواء بالله إنه ممن ينصح لهما في مشورته عليهما بالأكل من الشجرة، وهو كاذب في ذلك.", "isBasmala": false, "translation_en": "And he swore to them, \"I am a sincere advisor to you.\"", "translation_id": "Dan dia (syaitan) bersumpah kepada keduanya. \"Sesungguhnya saya adalah termasuk orang yang memberi nasehat kepada kamu berdua\",", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 22, "text": "فَدَلَّىٰهُمَا بِغُرُورࣲۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَ ٰتُهُمَا وَطَفِقَا یَخۡصِفَانِ عَلَیۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَاۤ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَاۤ إِنَّ ٱلشَّیۡطَـٰنَ لَكُمَا عَدُوࣱّ مُّبِینࣱ ۝٢٢", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "فجرَّأهما وغرَّهما، فأكلا من الشجرة التي نهاهما الله عن الاقتراب منها، فلما أكلا منها انكشفت لهما عوراتهما، وزال ما سترهما الله به قبل المخالفة، فأخذا يلزقان بعض ورق الجنة على عوراتهما، وناداهما ربهما جل وعلا ألم أنهكما عن الأكل من تلك الشجرة، وأقل لكما: إن الشيطان لكما عدو ظاهر العداوة؟ وفي هذه الآية دليل على أن كشف العورة من عظائم الأمور، وأنه كان ولم يزل مستهجَنًا في الطباع، مستقبَحًا في العقول.", "isBasmala": false, "translation_en": "So he lured them with deceit. And when they tasted the tree, their nakedness became evident to them, and they began covering themselves with the leaves of the Garden. And their Lord called out to them, \"Did I not forbid you from this tree, and say to you that Satan is a sworn enemy to you?\"", "translation_id": "maka syaitan membujuk keduanya (untuk memakan buah itu) dengan tipu daya. Tatkala keduanya telah merasai buah kayu itu, nampaklah bagi keduanya aurat-auratnya, dan mulailah keduanya menutupinya dengan daun-daun surga. Kemudian Tuhan mereka menyeru mereka: \"Bukankah Aku telah melarang kamu berdua dari pohon kayu itu dan Aku katakan kepadamu: \"Sesungguhnya syaitan itu adalah musuh yang nyata bagi kamu berdua?\"", "manzil": 2, "manzil_display": ""}], "153": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 23, "text": "قَالَا رَبَّنَا ظَلَمۡنَاۤ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَـٰسِرِینَ ۝٢٣", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قال آدم وحواء: ربنا ظلمنا أنفسنا بالأكل من الشجرة، وإن لم تغفر لنا وترحمنا لنكونن ممن أضاعوا حظَّهم في دنياهم وأخراهم. (وهذه الكلمات هي التي تلقاها آدم من ربه، فدعا بها فتاب الله عليه).", "isBasmala": false, "translation_en": "They said, \"Our Lord, we have done wrong to ourselves. Unless You forgive us, and have mercy on us, we will be among the losers.\"", "translation_id": "Keduanya berkata: \"Ya Tuhan kami, kami telah menganiaya diri kami sendiri, dan jika Engkau tidak mengampuni kami dan memberi rahmat kepada kami, niscaya pastilah kami termasuk orang-orang yang merugi.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 24, "text": "قَالَ ٱهۡبِطُوا۟ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ وَلَكُمۡ فِی ٱلۡأَرۡضِ مُسۡتَقَرࣱّ وَمَتَـٰعٌ إِلَىٰ حِینࣲ ۝٢٤", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قال تعالى مخاطبًا آدم وحواء لإبليس: اهبطوا من السماء إلى الأرض، وسيكون بعضكم لبعض عدوًا، ولكم في الأرض مكان تستقرون فيه، وتتمتعون إلى انقضاء آجالكم.", "isBasmala": false, "translation_en": "He said, \"Fall, some of you enemies to one another. On earth you will have residence and livelihood for a while.\"", "translation_id": "Allah berfirman: \"Turunlah kamu sekalian, sebahagian kamu menjadi musuh bagi sebahagian yang lain. Dan kamu mempunyai tempat kediaman dan kesenangan (tempat mencari kehidupan) di muka bumi sampai waktu yang telah ditentukan\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 25, "text": "قَالَ فِیهَا تَحۡیَوۡنَ وَفِیهَا تَمُوتُونَ وَمِنۡهَا تُخۡرَجُونَ ۝٢٥", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قال الله تعالى لآدم وحوَّاء وذريتهما: فيها تحيون، أي: في الأرض تقضون أيام حياتكم الدنيا، وفيها تكون وفاتكم، ومنها يخرجكم ربكم، ويحشركم أحياء يوم البعث.", "isBasmala": false, "translation_en": "He said, \"In it you will live, and in it you will die, and from it you will be brought out.\"", "translation_id": "Allah berfirman: \"Di bumi itu kamu hidup dan di bumi itu kamu mati, dan dari bumi itu (pula) kamu akan dibangkitkan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 26, "text": "یَـٰبَنِیۤ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَیۡكُمۡ لِبَاسࣰا یُوَ ٰرِی سَوۡءَ ٰتِكُمۡ وَرِیشࣰاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَ ٰلِكَ خَیۡرࣱۚ ذَ ٰلِكَ مِنۡ ءَایَـٰتِ ٱللَّهِ لَعَلَّهُمۡ یَذَّكَّرُونَ ۝٢٦", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "يا بني آدم قد جعلنا لكم لباسًا يستر عوراتكم، وهو لباس الضرورة، ولباسًا للزينة والتجمل، وهو من الكمال والتنعم. ولباسُ تقوى الله تعالى بفعل الأوامر واجتناب النواهي هو خير لباس للمؤمن. ذلك الذي مَنَّ الله به عليكم من الدلائل على ربوبية الله تعالى ووحدانيته وفضله ورحمته بعباده؛ لكي تتذكروا هذه النعم، فتشكروا لله عليها. وفي ذلك امتنان من الله تعالى على خَلْقه بهذه النعم.", "isBasmala": false, "translation_en": "O children of Adam! We have provided you with clothing to cover your bodies, and for luxury. But the clothing of piety-that is best. These are some of God's revelations, so that they may take heed.", "translation_id": "Hai anak Adam, sesungguhnya Kami telah menurunkan kepadamu pakaian untuk menutup auratmu dan pakaian indah untuk perhiasan. Dan pakaian takwa itulah yang paling baik. Yang demikian itu adalah sebahagian dari tanda-tanda kekuasaan Allah, mudah-mudahan mereka selalu ingat.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 27, "text": "یَـٰبَنِیۤ ءَادَمَ لَا یَفۡتِنَنَّكُمُ ٱلشَّیۡطَـٰنُ كَمَاۤ أَخۡرَجَ أَبَوَیۡكُم مِّنَ ٱلۡجَنَّةِ یَنزِعُ عَنۡهُمَا لِبَاسَهُمَا لِیُرِیَهُمَا سَوۡءَ ٰتِهِمَاۤۚ إِنَّهُۥ یَرَىٰكُمۡ هُوَ وَقَبِیلُهُۥ مِنۡ حَیۡثُ لَا تَرَوۡنَهُمۡۗ إِنَّا جَعَلۡنَا ٱلشَّیَـٰطِینَ أَوۡلِیَاۤءَ لِلَّذِینَ لَا یُؤۡمِنُونَ ۝٢٧", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "يا بني آدم لا يخدعنَّكم الشيطان، فيزين لكم المعصية، كما زيَّنها لأبويكم آدم وحواء، فأخرجهما بسببها من الجنة، ينزع عنهما لباسهما الذي سترهما الله به؛ لتنكشف لهما عوراتهما. إن الشيطان يراكم هو وذريته وجنسه وأنتم لا ترونهم فاحذروهم. إنَّا جعلنا الشياطين أولياء للكفار الذين لا يوحدون الله، ولا يصدقون رسله، ولا يعملون بهديه.", "isBasmala": false, "translation_en": "O Children of Adam! Do not let Satan seduce you, as he drove your parents out of the Garden, stripping them of their garments, to show them their nakedness. He sees you, him and his clan, from where you cannot see them. We have made the devils friends of those who do not believe.", "translation_id": "Hai anak Adam, janganlah sekali-kali kamu dapat ditipu oleh syaitan sebagaimana ia telah mengeluarkan kedua ibu bapamu dari surga, ia menanggalkan dari keduanya pakaiannya untuk memperlihatkan kepada keduanya auratnya. Sesungguhnya ia dan pengikut-pengikutnya melihat kamu dan suatu tempat yang kamu tidak bisa melihat mereka. Sesungguhnya Kami telah menjadikan syaitan-syaitan itu pemimpin-pemimpim bagi orang-orang yang tidak beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 28, "text": "وَإِذَا فَعَلُوا۟ فَـٰحِشَةࣰ قَالُوا۟ وَجَدۡنَا عَلَیۡهَاۤ ءَابَاۤءَنَا وَٱللَّهُ أَمَرَنَا بِهَاۗ قُلۡ إِنَّ ٱللَّهَ لَا یَأۡمُرُ بِٱلۡفَحۡشَاۤءِۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝٢٨", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "وإذا أتى الكفار قبيحًا من الفعل اعتذروا عن فعله بأنه مما ورثوه عن آبائهم، وأنه مما أمر الله به. قل لهم -أيها الرسول-: إن الله تعالى لا يأمر عباده بقبائح الأفعال ومساوئها، أتقولون على الله -أيها المشركون- ما لا تعلمون كذبًا وافتراءً؟", "isBasmala": false, "translation_en": "And when they commit an indecency, they say, \"We found our parents doing this, and God has commanded us to do it.\" Say, \"God does not command indecencies. Are you attributing to God what you do not know?\"", "translation_id": "Dan apabila mereka melakukan perbuatan keji, mereka berkata: \"Kami mendapati nenek moyang kami mengerjakan yang demikian itu, dan Allah menyuruh kami mengerjakannya\". Katakanlah: \"Sesungguhnya Allah tidak menyuruh (mengerjakan) perbuatan yang keji\". Mengapa kamu mengada-adakan terhadap Allah apa yang tidak kamu ketahui?", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 29, "text": "قُلۡ أَمَرَ رَبِّی بِٱلۡقِسۡطِۖ وَأَقِیمُوا۟ وُجُوهَكُمۡ عِندَ كُلِّ مَسۡجِدࣲ وَٱدۡعُوهُ مُخۡلِصِینَ لَهُ ٱلدِّینَۚ كَمَا بَدَأَكُمۡ تَعُودُونَ ۝٢٩", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: أمر ربي بالعدل، وأمركم بأن تخلصوا له العبادة في كل موضع من مواضعها، وبخاصة في المساجد، وأن تدعوه مخلصين له الطاعة والعبادة، وأن تؤمنوا بالبعث بعد الموت. وكما أن الله أوجدكم من العدم فإنه قادر على إعادة الحياة إليكم مرة أخرى.", "isBasmala": false, "translation_en": "Say, \"My Lord commands justice, and to stand devoted at every place of worship. So call upon Him, and dedicate your faith to Him alone. Just as He originated you, so you will return.\"", "translation_id": "Katakanlah: \"Tuhanku menyuruh menjalankan keadilan\". Dan (katakanlah): \"Luruskanlah muka (diri)mu di setiap sembahyang dan sembahlah Allah dengan mengikhlaskan ketaatanmu kepada-Nya. Sebagaimana Dia telah menciptakan kamu pada permulaan (demikian pulalah kamu akan kembali kepada-Nya)\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 30, "text": "فَرِیقًا هَدَىٰ وَفَرِیقًا حَقَّ عَلَیۡهِمُ ٱلضَّلَـٰلَةُۚ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّیَـٰطِینَ أَوۡلِیَاۤءَ مِن دُونِ ٱللَّهِ وَیَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ۝٣٠", "juz": 8, "hizb": "(* ح 16*)", "tafsir": "جعل الله عباده فريقين: فريقًا وفَّقهم للهداية إلى الصراط المستقيم، وفريقًا وجبت عليهم الضلالة عن الطريق المستقيم، إنهم اتخذوا الشياطين أولياء من دون الله، فأطاعوهم جهلا منهم وظنًا بأنهم قد سلكوا سبيل الهداية.", "isBasmala": false, "translation_en": "Some He has guided, and some have deserved misguidance. They have adopted the devils for patrons rather than God, and they assume that they are guided.", "translation_id": "Sebahagian diberi-Nya petunjuk dan sebahagian lagi telah pasti kesesatan bagi mereka. Sesungguhnya mereka menjadikan syaitan-syaitan pelindung (mereka) selain Allah, dan mereka mengira bahwa mereka mendapat petunjuk.", "manzil": 2, "manzil_display": ""}], "154": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 31, "text": "۞ یَـٰبَنِیۤ ءَادَمَ خُذُوا۟ زِینَتَكُمۡ عِندَ كُلِّ مَسۡجِدࣲ وَكُلُوا۟ وَٱشۡرَبُوا۟ وَلَا تُسۡرِفُوۤا۟ۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡمُسۡرِفِینَ ۝٣١", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "يا بني آدم كونوا عند أداء كل صلاة على حالة من الزينة المشروعة من ثياب ساترة لعوراتكم ونظافة وطهارة ونحو ذلك، وكلوا واشربوا من طيبات ما رزقكم الله، ولا تتجاوزوا حدود الاعتدال في ذلك. إن الله لا يحب المتجاوزين المسرفين في الطعام والشراب وغير ذلك.", "isBasmala": false, "translation_en": "O Children of Adam! Dress properly at every place of worship, and eat and drink, but do not be excessive. He does not love the excessive.", "translation_id": "Hai anak Adam, pakailah pakaianmu yang indah di setiap (memasuki) mesjid, makan dan minumlah, dan janganlah berlebih-lebihan. Sesungguhnya Allah tidak menyukai orang-orang yang berlebih-lebihan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 32, "text": "قُلۡ مَنۡ حَرَّمَ زِینَةَ ٱللَّهِ ٱلَّتِیۤ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّیِّبَـٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِیَ لِلَّذِینَ ءَامَنُوا۟ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا خَالِصَةࣰ یَوۡمَ ٱلۡقِیَـٰمَةِۗ كَذَ ٰلِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡلَمُونَ ۝٣٢", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "قل -أيها الرسول- لهؤلاء الجهلة من المشركين: مَن الذي حرم عليكم اللباس الحسن الذي جعله الله تعالى زينة لكم؟ ومَن الذي حرَّم عليكم التمتع بالحلال الطيب من رزق الله تعالى؟ قل -أيها الرسول- لهؤلاء المشركين: إنَّ ما أحله الله من الملابس والطيبات من المطاعم والمشارب حق للذين آمنوا في الحياة الدنيا يشاركهم فيها غيرهم، خالصة لهم يوم القيامة. مثل ذلك التفصيل يفصِّل الله الآيات لقوم يعلمون ما يبيِّن لهم، ويفقهون ما يميز لهم.", "isBasmala": false, "translation_en": "Say, \"Who forbade God's finery which He has produced for His servants, and the delights of livelihood?\" Say, \"They are for those who believe, in this present world, but exclusively theirs on the Day of Resurrection.\" We thus detail the revelations for people who know.", "translation_id": "Katakanlah: \"Siapakah yang mengharamkan perhiasan dari Allah yang telah dikeluarkan-Nya untuk hamba-hamba-Nya dan (siapa pulakah yang mengharamkan) rezeki yang baik?\" Katakanlah: \"Semuanya itu (disediakan) bagi orang-orang yang beriman dalam kehidupan dunia, khusus (untuk mereka saja) di hari kiamat\". Demikianlah Kami menjelaskan ayat-ayat itu bagi orang-orang yang mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 33, "text": "قُلۡ إِنَّمَا حَرَّمَ رَبِّیَ ٱلۡفَوَ ٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡیَ بِغَیۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُوا۟ بِٱللَّهِ مَا لَمۡ یُنَزِّلۡ بِهِۦ سُلۡطَـٰنࣰا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝٣٣", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: إنما حَرَّم الله القبائح من الأعمال، ما كان منها ظاهرًا، وما كان خفيًّا، وحَرَّم المعاصي كلها، ومِن أعظمها الاعتداء على الناس، فإن ذلك مجانب للحق، وحرَّم أن تعبدوا مع الله تعالى غيره مما لم يُنَزِّل به دليلا وبرهانًا، فإنه لا حجة لفاعل ذلك، وحرَّم أن تنسبوا إلى الله تعالى ما لم يشرعه افتراءً وكذبًا، كدعوى أن لله ولدًا، وتحريم بعض الحلال من الملابس والمآكل.", "isBasmala": false, "translation_en": "Say, \"My Lord has forbidden immoralities-both open and secret-and sin, and unjustified aggression, and that you associate with God anything for which He revealed no sanction, and that you say about God what you do not know.\"", "translation_id": "Katakanlah: \"Tuhanku hanya mengharamkan perbuatan yang keji, baik yang nampak ataupun yang tersembunyi, dan perbuatan dosa, melanggar hak manusia tanpa alasan yang benar, (mengharamkan) mempersekutukan Allah dengan sesuatu yang Allah tidak menurunkan hujjah untuk itu dan (mengharamkan) mengada-adakan terhadap Allah apa yang tidak kamu ketahui\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 34, "text": "وَلِكُلِّ أُمَّةٍ أَجَلࣱۖ فَإِذَا جَاۤءَ أَجَلُهُمۡ لَا یَسۡتَأۡخِرُونَ سَاعَةࣰ وَلَا یَسۡتَقۡدِمُونَ ۝٣٤", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "ولكل جماعة اجتمعت على الكفر بالله تعالى وتكذيب رسله -عليهم الصلاة والسلام- وقت لحلول العقوبة بهم، فإذا جاء الوقت الذي وقَّته الله لإهلاكهم لا يتأخرون عنه لحظة، ولا يتقدمون عليه.", "isBasmala": false, "translation_en": "For every nation is an appointed time. When their time has come, they cannot delay it by one hour, nor can they advance it.", "translation_id": "Tiap-tiap umat mempunyai batas waktu; maka apabila telah datang waktunya mereka tidak dapat mengundurkannya barang sesaatpun dan tidak dapat (pula) memajukannya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 35, "text": "یَـٰبَنِیۤ ءَادَمَ إِمَّا یَأۡتِیَنَّكُمۡ رُسُلࣱ مِّنكُمۡ یَقُصُّونَ عَلَیۡكُمۡ ءَایَـٰتِی فَمَنِ ٱتَّقَىٰ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝٣٥", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "يا بني آدم إذا جاءكم رسلي من أقوامكم، يتلون عليكم آيات كتابي، ويبينون لكم البراهين على صدق ما جاؤوكم به فأطيعوهم، فإنه من اتقى سخطي وأصلح عمله فلا خوف عليهم يوم القيامة من عقاب الله تعالى، ولا ههم يحزنون على ما فاتهم من حظوظ الدنيا.", "isBasmala": false, "translation_en": "O Children of Adam! When messengers from among you come to you, relating to you My revelations-whoever practices piety and reforms-upon them shall be no fear, nor shall they grieve.", "translation_id": "Hai anak-anak Adam, jika datang kepadamu rasul-rasul daripada kamu yang menceritakan kepadamu ayat-ayat-Ku, maka barangsiapa yang bertakwa dan mengadakan perbaikan, tidaklah ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 36, "text": "وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَٱسۡتَكۡبَرُوا۟ عَنۡهَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٣٦", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "والكفار الذين كذَّبوا بالدلائل على توحيد الله، واستعلَوا عن اتباعها، أولئك أصحاب النار ماكثين فيها، لا يخرجون منها أبدًا.", "isBasmala": false, "translation_en": "But as for those who reject Our revelations, and are too proud to accept them-these are the inmates of the Fire, where they will remain forever.", "translation_id": "Dan orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri terhadapnya, mereka itu penghuni-penghuni neraka; mereka kekal di dalamnya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 37, "text": "فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔایَـٰتِهِۦۤۚ أُو۟لَـٰۤىِٕكَ یَنَالُهُمۡ نَصِیبُهُم مِّنَ ٱلۡكِتَـٰبِۖ حَتَّىٰۤ إِذَا جَاۤءَتۡهُمۡ رُسُلُنَا یَتَوَفَّوۡنَهُمۡ قَالُوۤا۟ أَیۡنَ مَا كُنتُمۡ تَدۡعُونَ مِن دُونِ ٱللَّهِۖ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰۤ أَنفُسِهِمۡ أَنَّهُمۡ كَانُوا۟ كَـٰفِرِینَ ۝٣٧", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "لا أحد أشد ظلمًا ممن اختلق على الله تعالى الكذب، أو كذَّب بآياته المنزلة، أولئك يصل إليهم حظُّهم من العذاب مما كتب لهم في اللوح المحفوظ، حتى إذا جاءهم ملك الموت وأعوانه يقبضون أرواحهم قالوا لهم: أين الذين كنتم تعبدونهم من دون الله من الشركاء والأولياء والأوثان ليخلِّصوكم مما أنتم فيه؟ قالوا: ذهبوا عنا، واعترفوا على أنفسهم حينئذ أنهم كانوا في الدنيا جاحدين مكذبين وحدانية الله تعالى.", "isBasmala": false, "translation_en": "Who does greater wrong than he who invents lies about God, or denies His revelations? These-their share of the decree will reach them. Until, when Our envoys come to them, to take their souls away, they will say, \"Where are they whom you used to pray to besides God?\" They will say, \"They have abandoned us,\" and they will testify against themselves that they were faithless.", "translation_id": "Maka siapakah yang lebih zalim daripada orang yang membuat-buat dusta terhadap Allah atau mendustakan ayat-ayat-Nya? Orang-orang itu akan memperoleh bahagian yang telah ditentukan untuknya dalam Kitab (Lauh Mahfuzh); hingga bila datang kepada mereka utusan-utusan Kami (malaikat) untuk mengambil nyawanya, (di waktu itu) utusan Kami bertanya: \"Di mana (berhala-berhala) yang biasa kamu sembah selain Allah?\" Orang-orang musyrik itu menjawab: \"Berhala-berhala itu semuanya telah lenyap dari kami,\" dan mereka mengakui terhadap diri mereka bahwa mereka adalah orang-orang yang kafir.", "manzil": 2, "manzil_display": ""}], "155": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 38, "text": "قَالَ ٱدۡخُلُوا۟ فِیۤ أُمَمࣲ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ فِی ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةࣱ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰۤ إِذَا ٱدَّارَكُوا۟ فِیهَا جَمِیعࣰا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَـٰۤؤُلَاۤءِ أَضَلُّونَا فَـَٔاتِهِمۡ عَذَابࣰا ضِعۡفࣰا مِّنَ ٱلنَّارِۖ قَالَ لِكُلࣲّ ضِعۡفࣱ وَلَـٰكِن لَّا تَعۡلَمُونَ ۝٣٨", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "قال الله تعالى -لهؤلاء المشركين المفترين-: ادخلوا النار في جملة جماعات من أمثالكم في الكفر، قد سلفت من قبلكم من الجن والإنس، كلما دخلت النارَ جماعةٌ من أهل ملة لعنت نظيرتها التي ضلَّتْ بالاقتداء بها، حتى إذا تلاحق في النار الأولون من أهل الملل الكافرة والآخرون منهم جميعًا، قال الآخرون المتبعون في الدنيا لقادتهم: ربنا هؤلاء هم الذين أضلونا عن الحق، فآتهم عذابًا مضاعفا من النار، قال الله تعالى: لكل ضعف، أي: لكل منكم ومنهم عذاب مضاعف من النار، ولكن لا تدركون أيها الأتباع ما لكل فريق منكم من العذاب والآلام.", "isBasmala": false, "translation_en": "He will say, \"Join the crowds of jinn and humans who have gone into the Fire before you.\" Every time a crowd enters, it will curse its sister-crowd. Until, when they are all in it, the last of them will say to the first of them, \"Our Lord, these are the ones who misled us, so inflict on them a double punishment in the Fire.\" He will say, \"Each will have a double, but you do not know.\"", "translation_id": "Allah berfirman: \"Masuklah kamu sekalian ke dalam neraka bersama umat-umat jin dan manusia yang telah terdahulu sebelum kamu. Setiap suatu umat masuk (ke dalam neraka), dia mengutuk kawannya (menyesatkannya); sehingga apabila mereka masuk semuanya berkatalah orang-orang yang masuk kemudian di antara mereka kepada orang-orang yang masuk terdahulu: \"Ya Tuhan kami, mereka telah menyesatkan kami, sebab itu datangkanlah kepada mereka siksaan yang berlipat ganda dari neraka\". Allah berfirman: \"Masing-masing mendapat (siksaan) yang berlipat ganda, akan tetapi kamu tidak mengetahui\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 39, "text": "وَقَالَتۡ أُولَىٰهُمۡ لِأُخۡرَىٰهُمۡ فَمَا كَانَ لَكُمۡ عَلَیۡنَا مِن فَضۡلࣲ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡسِبُونَ ۝٣٩", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "وقال المتبوعون من الرؤساء وغيرهم لأتباعهم: نحن وأنتم متساوون في الغيِّ والضلال، وفي فِعْلِ أسباب العذاب فلا فَضْلَ لكم علينا، قال الله تعالى لهم جميعًا: فذوقوا العذاب أي عذاب جهنم؛ بسبب ما كسبتم من المعاصي.", "isBasmala": false, "translation_en": "The first of them will say to the last of them, \"You have no advantage over us, so taste the torment for what you used to earn.\"", "translation_id": "Dan berkata orang-orang yang masuk terdahulu di antara mereka kepada orang-orang yang masuk kemudian: \"Kamu tidak mempunyai kelebihan sedikitpun atas kami, maka rasakanlah siksaan karena perbuatan yang telah kamu lakukan\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 40, "text": "إِنَّ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَٱسۡتَكۡبَرُوا۟ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَ ٰبُ ٱلسَّمَاۤءِ وَلَا یَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ یَلِجَ ٱلۡجَمَلُ فِی سَمِّ ٱلۡخِیَاطِۚ وَكَذَ ٰلِكَ نَجۡزِی ٱلۡمُجۡرِمِینَ ۝٤٠", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "إن الكفار الذين لم يصدِّقوا بحججنا وآياتنا الدالة على وحدانيتنا، ولم يعملوا بشرعنا تكبرًا واستعلاءً، لا تُفتَّح لأعمالهم في الحياة ولا لأرواحهم عند الممات أبواب السماء، ولا يمكن أن يدخل هؤلاء الكفار الجنة إلا إذا دخل الجمل في ثقب الإبرة، وهذا مستحيل. ومثل ذلك الجزاء نجزي الذين كثر إجرامهم، واشتدَّ طغيانهم.", "isBasmala": false, "translation_en": "Those who reject Our revelations and are too arrogant to uphold them-the doors of Heaven will not be opened for them, nor will they enter Paradise, until the camel passes through the eye of the needle. Thus We repay the guilty.", "translation_id": "Sesungguhnya orang-orang yang mendustakan ayat-ayat Kami dan menyombongkan diri terhadapnya, sekali-kali tidak akan dibukakan bagi mereka pintu-pintu langit dan tidak (pula) mereka masuk surga, hingga unta masuk ke lubang jarum. Demikianlah Kami memberi pembalasan kepada orang-orang yang berbuat kejahatan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 41, "text": "لَهُم مِّن جَهَنَّمَ مِهَادࣱ وَمِن فَوۡقِهِمۡ غَوَاشࣲۚ وَكَذَ ٰلِكَ نَجۡزِی ٱلظَّـٰلِمِینَ ۝٤١", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "هؤلاء الكفار مخلدون في النار، لهم مِن جهنم فراش مِن تحتهم، ومن فوقهم أغطية تغشاهم. وبمثل هذا العقاب الشديد يعاقب الله تعالى الظالمين الذين تجاوزوا حدوده فكفروا به وعصَوْه.", "isBasmala": false, "translation_en": "For them is a couch of hell, and above them are sheets of fire. Thus We repay the wrongdoers.", "translation_id": "Mereka mempunyai tikar tidur dari api neraka dan di atas mereka ada selimut (api neraka). Demikianlah Kami memberi balasan kepada orang-orang yang zalim,", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 42, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٤٢", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "والذين آمنوا بالله وعملوا الأعمال الصالحة في حدود طاقاتهم -لا يكلف الله نفسًا من الأعمال إلا ما تطيق- أولئك أهل الجنة، هم فيها ماكثون أبدًا لا يخرجون منها.", "isBasmala": false, "translation_en": "As for those who believe and do righteous works-We never burden any soul beyond its capacity-these are the inhabitants of the Garden; abiding therein eternally.", "translation_id": "dan orang-orang yang beriman dan mengerjakan amal-amal yang saleh, Kami tidak memikulkan kewajiban kepada diri seseorang melainkan sekedar kesanggupannya, mereka itulah penghuni-penghuni surga; mereka kekal di dalamnya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 43, "text": "وَنَزَعۡنَا مَا فِی صُدُورِهِم مِّنۡ غِلࣲّ تَجۡرِی مِن تَحۡتِهِمُ ٱلۡأَنۡهَـٰرُۖ وَقَالُوا۟ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی هَدَىٰنَا لِهَـٰذَا وَمَا كُنَّا لِنَهۡتَدِیَ لَوۡلَاۤ أَنۡ هَدَىٰنَا ٱللَّهُۖ لَقَدۡ جَاۤءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّۖ وَنُودُوۤا۟ أَن تِلۡكُمُ ٱلۡجَنَّةُ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٤٣", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "وأذهب الله تعالى ما في صدور أهل الجنة من حقد وضغائن، ومن كمال نعيمهم أن الأنهار تجري في الجنة من تحتهم. وقال أهل الجنة حينما دخلوها: الحمد لله الذي وفَّقنا للعمل الصالح الذي أكسبنا ما نحن فيه من النعيم، وما كنا لنوفَّق إلى سلوك الطريق المستقيم لولا أَنْ هدانا الله سبحانه لسلوك هذا الطريق، ووفَّقنا للثبات عليه، لقد جاءت رسل ربنا بالحق من الإخبار بوعد أهل طاعته ووعيد أهل معصيته، ونُودوا تهنئة لهم وإكرامًا: أن تلكم الجنة أورثكم الله إياها برحمته، وبما قدَّمتموه من الإيمان والعمل الصالح.", "isBasmala": false, "translation_en": "We will remove whatever rancor is in their hearts. Rivers will flow beneath them. And they will say, \"Praise be to God, who has guided us to this. Had God not guided us, we would never be guided. The messengers of our Lord did come with the truth.\" And it will be proclaimed to them, \"This is the Garden you are made to inherit, on account of what you used to do.\"", "translation_id": "Dan Kami cabut segala macam dendam yang berada di dalam dada mereka; mengalir di bawah mereka sungai-sungai dan mereka berkata: \"Segala puji bagi Allah yang telah menunjuki kami kepada (surga) ini. Dan kami sekali-kali tidak akan mendapat petunjuk kalau Allah tidak memberi kami petunjuk. Sesungguhnya telah datang rasul-rasul Tuhan kami, membawa kebenaran\". Dan diserukan kepada mereka: \"ltulah surga yang diwariskan kepadamu, disebabkan apa yang dahulu kamu kerjakan\".", "manzil": 2, "manzil_display": ""}], "156": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 44, "text": "وَنَادَىٰۤ أَصۡحَـٰبُ ٱلۡجَنَّةِ أَصۡحَـٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقࣰّا فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقࣰّاۖ قَالُوا۟ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَیۡنَهُمۡ أَن لَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِینَ ۝٤٤", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "ونادى أصحاب الجنة -بعد دخولهم فيها- أهلَ النار قائلين لهم: إنا قد وجدنا ما وعدنا ربنا على ألسنة رسله حقًا من إثابة أهل طاعته، فهل وجدتم ما وعدكم ربكم على ألسنة رسله حقًا من عقاب أهل معصيته؟ فأجابهم أهل النار قائلين: نعم قد وجدنا ما وعدنا ربنا حقًا. فأذَّن مؤذن بين أهل الجنة وأهل النار: أنْ لعنة الله على الظالمين الذين تجاوزوا حدود الله، وكفروا بالله ورسله.", "isBasmala": false, "translation_en": "And the inhabitants of the Garden will call out to the inmates of the Fire, \"We found what our Lord promised us to be true; did you find what your Lord promised you to be true?\" They will say, \"Yes.\" Thereupon a caller will announce in their midst, \"The curse of God is upon the wrongdoers.\"", "translation_id": "Dan penghuni-penghuni surga berseru kepada Penghuni-penghuni neraka (dengan mengatakan): \"Sesungguhnya kami dengan sebenarnya telah memperoleh apa yang Tuhan kami menjanjikannya kepada kami. Maka apakah kamu telah memperoleh dengan sebenarnya apa (azab) yang Tuhan kamu menjanjikannya (kepadamu)?\" Mereka (penduduk neraka) menjawab: \"Betul\". Kemudian seorang penyeru (malaikat) mengumumkan di antara kedua golongan itu: \"Kutukan Allah ditimpakan kepada orang-orang yang zalim,", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 45, "text": "ٱلَّذِینَ یَصُدُّونَ عَن سَبِیلِ ٱللَّهِ وَیَبۡغُونَهَا عِوَجࣰا وَهُم بِٱلۡـَٔاخِرَةِ كَـٰفِرُونَ ۝٤٥", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "هؤلاء الكافرون هم الذين كانوا يُعْرِضون عن طريق الله المستقيم، ويمنعون الناس من سلوكه، ويطلبون أن تكون السبيل معوجة حتى لا يتبينها أحد، وهم بالآخرة -وما فيها- جاحدون.", "isBasmala": false, "translation_en": "\"Those who hinder from the path of God, and seek to distort it, and who deny the Hereafter.\"", "translation_id": "(yaitu) orang-orang yang menghalang-halangi (manusia) dari jalan Allah dan menginginkan agar jalan itu menjadi bengkok, dan mereka kafir kepada kehidupan akhirat\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 46, "text": "وَبَیۡنَهُمَا حِجَابࣱۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالࣱ یَعۡرِفُونَ كُلَّۢا بِسِیمَىٰهُمۡۚ وَنَادَوۡا۟ أَصۡحَـٰبَ ٱلۡجَنَّةِ أَن سَلَـٰمٌ عَلَیۡكُمۡۚ لَمۡ یَدۡخُلُوهَا وَهُمۡ یَطۡمَعُونَ ۝٤٦", "juz": 8, "hizb": "(*¼ ح 16*)", "tafsir": "وبين أصحاب الجنة وأصحاب النار حاجز عظيم يقال له الأعراف، وعلى هذا الحاجز رجال يعرفون أهل الجنة وأهل النار بعلاماتهم، كبياض وجوه أهل الجنة، وسواد وجوه أهل النار، وهؤلاء الرجال قوم استوت حسناتهم وسيئاتهم يرجون رحمة الله تعالى. ونادى رجال الأعراف أهل الجنة بالتحية قائلين لهم: سلام عليكم، وأهل الأعراف لم يدخلوا الجنة بعد، وهم يرجون دخولها.", "isBasmala": false, "translation_en": "And between them is a partition, and on the Elevations are men who recognize everyone by their features. They will call to the inhabitants of the Garden, \"Peace be upon you.\" They have not entered it, but they are hoping.", "translation_id": "Dan di antara keduanya (penghuni surga dan neraka) ada batas; dan di atas A'raaf itu ada orang-orang yang mengenal masing-masing dari dua golongan itu dengan tanda-tanda mereka. Dan mereka menyeru penduduk surga: \"Salaamun 'alaikum\". Mereka belum lagi memasukinya, sedang mereka ingin segera (memasukinya).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 47, "text": "۞ وَإِذَا صُرِفَتۡ أَبۡصَـٰرُهُمۡ تِلۡقَاۤءَ أَصۡحَـٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝٤٧", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "وإذا حُوِّلَتْ أبصار رجال الأعراف جهة أهل النار قالوا: ربنا لا تُصيِّرنا مع القوم الظالمين بشركهم وكفرهم.", "isBasmala": false, "translation_en": "And when their eyes are directed towards the inmates of the Fire, they will say, \"Our Lord, do not place us among the wrongdoing people.\"", "translation_id": "Dan apabila pandangan mereka dialihkan ke arah penghuni neraka, mereka berkata: \"Ya Tuhan kami, janganlah Engkau tempatkan kami bersama-sama orang-orang yang zalim itu\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 48, "text": "وَنَادَىٰۤ أَصۡحَـٰبُ ٱلۡأَعۡرَافِ رِجَالࣰا یَعۡرِفُونَهُم بِسِیمَىٰهُمۡ قَالُوا۟ مَاۤ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ ۝٤٨", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "ونادى أهل الأعراف رجالا من قادة الكفار الذين في النار، يعرفونهم بعلامات خاصة تميزهم، قالوا لهم: ما نفعكم ما كنتم تجمعون من الأموال والرجال في الدنيا، وما نفعكم استعلاؤكم عن الإيمان بالله وقَبول الحق.", "isBasmala": false, "translation_en": "And the dwellers of the Elevations will call to men they recognize by their features, saying, \"Your hoardings did not avail you, nor did your arrogance.\"", "translation_id": "Dan orang-orang yang di atas A'raaf memanggil beberapa orang (pemuka-pemuka orang kafir) yang mereka mengenalnya dengan tanda-tandanya dengan mengatakan: \"Harta yang kamu kumpulkan dan apa yang selalu kamu sombongkan itu, tidaklah memberi manfaat kepadamu\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 49, "text": "أَهَـٰۤؤُلَاۤءِ ٱلَّذِینَ أَقۡسَمۡتُمۡ لَا یَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ ٱدۡخُلُوا۟ ٱلۡجَنَّةَ لَا خَوۡفٌ عَلَیۡكُمۡ وَلَاۤ أَنتُمۡ تَحۡزَنُونَ ۝٤٩", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "أهؤلاء الضعفاء والفقراء من أهل الجنة الذين أقسمتم في الدنيا أن الله لا يشملهم يوم القيامة برحمة، ولن يدخلهم الجنة؟ ادخلوا الجنة يا أصحاب الأعراف فقد غُفِرَ لكم، لا خوف عليكم من عذاب الله، ولا أنتم تحزنون على ما فاتكم من حظوظ الدنيا.", "isBasmala": false, "translation_en": "\"Are these the ones you swore God will not touch with mercy?\" \"Enter the Garden; you have nothing to fear, and you will not grieve.\"", "translation_id": "(Orang-orang di atas A'raaf bertanya kepada penghuni neraka): \"Itukah orang-orang yang kamu telah bersumpah bahwa mereka tidak akan mendapat rahmat Allah?\". (Kepada orang mukmin itu dikatakan): \"Masuklah ke dalam surga, tidak ada kekhawatiran terhadapmu dan tidak (pula) kamu bersedih hati\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 50, "text": "وَنَادَىٰۤ أَصۡحَـٰبُ ٱلنَّارِ أَصۡحَـٰبَ ٱلۡجَنَّةِ أَنۡ أَفِیضُوا۟ عَلَیۡنَا مِنَ ٱلۡمَاۤءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوۤا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَـٰفِرِینَ ۝٥٠", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "واستغاث أهل النار بأهل الجنة طالبين منهم أن يُفيضوا عليهم من الماء، أو مما رزقهم الله من الطعام، فأجابوهم بأن الله تعالى قد حَرَّم الشراب والطعام على الذين جحدوا توحيده، وكذَّبوا رسله.", "isBasmala": false, "translation_en": "The inmates of the Fire will call on the inhabitants of the Garden, \"Pour some water over us, or some of what God has provided for you.\" They will say, \"God has forbidden them for the disbelievers.\"", "translation_id": "Dan penghuni neraka menyeru penghuni surga: \"Limpahkanlah kepada kami sedikit air atau makanan yang telah direzekikan Allah kepadamu\". Mereka (penghuni surga) menjawab: \"Sesungguhnya Allah telah mengharamkan keduanya itu atas orang-orang kafir,", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 51, "text": "ٱلَّذِینَ ٱتَّخَذُوا۟ دِینَهُمۡ لَهۡوࣰا وَلَعِبࣰا وَغَرَّتۡهُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۚ فَٱلۡیَوۡمَ نَنسَىٰهُمۡ كَمَا نَسُوا۟ لِقَاۤءَ یَوۡمِهِمۡ هَـٰذَا وَمَا كَانُوا۟ بِـَٔایَـٰتِنَا یَجۡحَدُونَ ۝٥١", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "الذين حَرَمهم الله تعالى من نعيم الآخرة هم الذين جعلوا الدين الذي أمرهم الله باتباعه باطلا ولهوًا، وخدعتهم الحياة الدنيا وشغلوا بزخارفها عن العمل للآخرة، فيوم القيامة ينساهم الله تعالى ويتركهم في العذاب الموجع، كما تركوا العمل للقاء يومهم هذا، ولكونهم بأدلة الله وبراهينه ينكرون مع علمهم بأنها حق.", "isBasmala": false, "translation_en": "Those who took their religion lightly, and in jest, and whom the worldly life deceived. Today We will ignore them, as they ignored the meeting on this Day of theirs, and they used to deny Our revelations.", "translation_id": "(yaitu) orang-orang yang menjadikan agama mereka sebagai main-main dan senda gurau, dan kehidupan dunia telah menipu mereka\". Maka pada hari (kiamat) ini, Kami melupakan mereka sebagaimana mereka melupakan pertemuan mereka dengan hari ini, dan (sebagaimana) mereka selalu mengingkari ayat-ayat Kami.", "manzil": 2, "manzil_display": ""}], "157": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 52, "text": "وَلَقَدۡ جِئۡنَـٰهُم بِكِتَـٰبࣲ فَصَّلۡنَـٰهُ عَلَىٰ عِلۡمٍ هُدࣰى وَرَحۡمَةࣰ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝٥٢", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "ولقد جئنا الكفار بقرآن أنزلناه عليك -أيها الرسول- بيَّنَّاه مشتملا على علم عظيم، هاديًا من الضلالة إلى الرشد ورحمة لقوم يؤمنون بالله ويعملون بشرعه. وخصَّهم دون غيرهم؛ لأنهم هم المنتفعون به.", "isBasmala": false, "translation_en": "We have given them a Scripture, which We detailed with knowledge-guidance and mercy for people who believe.", "translation_id": "Dan sesungguhnya Kami telah mendatangkan sebuah Kitab (Al Quran) kepada mereka yang Kami telah menjelaskannya atas dasar pengetahuan Kami; menjadi petunjuk dan rahmat bagi orang-orang yang beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 53, "text": "هَلۡ یَنظُرُونَ إِلَّا تَأۡوِیلَهُۥۚ یَوۡمَ یَأۡتِی تَأۡوِیلُهُۥ یَقُولُ ٱلَّذِینَ نَسُوهُ مِن قَبۡلُ قَدۡ جَاۤءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّ فَهَل لَّنَا مِن شُفَعَاۤءَ فَیَشۡفَعُوا۟ لَنَاۤ أَوۡ نُرَدُّ فَنَعۡمَلَ غَیۡرَ ٱلَّذِی كُنَّا نَعۡمَلُۚ قَدۡ خَسِرُوۤا۟ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ ۝٥٣", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "هل ينتظر الكفار إلا ما وُعِدوا به في القرآن من العقاب الذي يؤول إليه أمرهم؟ يوم يأتي ما يئول إليه الأمر من الحساب والثواب والعقاب يوم القيامة يقول الكفار الذين تركوا القرآن، وكفروا به في الحياة الدنيا: قد تبيَّن لنا الآن أنَّ رسل ربنا قد جاؤوا بالحق، ونصحوا لنا، فهل لنا من أصدقاء وشفعاء، فيشفعوا لنا عند ربنا، أو نعاد إلى الدنيا مرة أخرى فنعمل فيها بما يرضي الله عنا؟ قد خسروا أنفسهم بدخولهم النار وخلودهم فيها، وذهب عنهم ما كانوا يعبدونه من دون الله، ويفترونه في الدنيا مما يَعِدُهم به الشيطان.", "isBasmala": false, "translation_en": "Are they waiting for anything but its fulfillment? The Day its fulfillment comes true, those who disregarded it before will say, \"The messengers of our Lord did come with the truth. Have we any intercessors to intercede for us? Or, could we be sent back, to behave differently from the way we behaved before?\" They ruined their souls, and what they used to invent has failed them.", "translation_id": "Tiadalah mereka menunggu-nunggu kecuali (terlaksananya kebenaran) Al Quran itu. Pada hari datangnya kebenaran pemberitaan Al Quran itu, berkatalah orang-orang yang melupakannya sebelum itu: \"Sesungguhnya telah datang rasul-rasul Tuhan kami membawa yang hak, maka adakah bagi kami pemberi syafa'at yang akan memberi syafa'at bagi kami, atau dapatkah kami dikembalikan (ke dunia) sehingga kami dapat beramal yang lain dari yang pernah kami amalkan?\". Sungguh mereka telah merugikan diri mereka sendiri dan telah lenyaplah dari mereka tuhan-tuhan yang mereka ada-adakan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 54, "text": "إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ یُغۡشِی ٱلَّیۡلَ ٱلنَّهَارَ یَطۡلُبُهُۥ حَثِیثࣰا وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَ ٰتِۭ بِأَمۡرِهِۦۤۗ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَـٰلَمِینَ ۝٥٤", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "إن ربكم -أيها الناس- هو الله الذي أوجد السموات والأرض من العدم في ستة أيام، ثم استوى -سبحانه- على العرش -أي علا وارتفع- استواءً يليق بجلاله وعظمته، يُدخل سبحانه الليل على النهار، فيلبسه إياه حتى يذهب نوره، ويُدخل النهار على الليل فيذهب ظلامه، وكل واحد منهما يطلب الآخر سريعًا دائمًا، وهو -سبحانه- الذي خلق الشمس والقمر والنجوم مذللات له يسخرهن -سبحانه- كما يشاء، وهنَّ من آيات الله العظيمة. ألا له سبحانه وتعالى الخلق كله وله الأمر كله، تعالى الله وتعاظم وتنزَّه عن كل نقص، رب الخلق أجمعين.", "isBasmala": false, "translation_en": "Your Lord is God; He who created the heavens and the earth in six days, then established Himself on the Throne. The night overtakes the day, as it pursues it persistently; and the sun, and the moon, and the stars are subservient by His command. His is the creation, and His is the command. Blessed is God, Lord of all beings.", "translation_id": "Sesungguhnya Tuhan kamu ialah Allah yang telah menciptakan langit dan bumi dalam enam masa, lalu Dia bersemayam di atas 'Arsy. Dia menutupkan malam kepada siang yang mengikutinya dengan cepat, dan (diciptakan-Nya pula) matahari, bulan dan bintang-bintang (masing-masing) tunduk kepada perintah-Nya. Ingatlah, menciptakan dan memerintah hanyalah hak Allah. Maha Suci Allah, Tuhan semesta alam.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 55, "text": "ٱدۡعُوا۟ رَبَّكُمۡ تَضَرُّعࣰا وَخُفۡیَةًۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡمُعۡتَدِینَ ۝٥٥", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "ادعوا -أيها المؤمنون- ربكم متذللين له خفية وسرًّا، وليكن الدعاء بخشوع وبُعْدٍ عن الرياء. إن الله تعالى لا يحب المتجاوزين حدود شرعه، وأعظم التجاوز الشرك بالله، كدعاء غير الله من الأموات والأوثان، ونحو ذلك.", "isBasmala": false, "translation_en": "Call upon your Lord humbly and privately. He does not love the aggressors.", "translation_id": "Berdoalah kepada Tuhanmu dengan berendah diri dan suara yang lembut. Sesungguhnya Allah tidak menyukai orang-orang yang melampaui batas.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 56, "text": "وَلَا تُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ بَعۡدَ إِصۡلَـٰحِهَا وَٱدۡعُوهُ خَوۡفࣰا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِیبࣱ مِّنَ ٱلۡمُحۡسِنِینَ ۝٥٦", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "ولا تُفْسدوا في الأرض بأيِّ نوع من أنواع الفساد، بعد إصلاح الله إياها ببعثة الرسل -عليهم السلام- وعُمْرانها بطاعة الله، وادعوه -سبحانه- مخلصين له الدعاء؛ خوفًا من عقابه ورجاء لثوابه. إن رحمة الله قريب من المحسنين.", "isBasmala": false, "translation_en": "And do not corrupt on earth after its reformation, and pray to Him with fear and hope. God's mercy is close to the doers of good.", "translation_id": "Dan janganlah kamu membuat kerusakan di muka bumi, sesudah (Allah) memperbaikinya dan berdoalah kepada-Nya dengan rasa takut (tidak akan diterima) dan harapan (akan dikabulkan). Sesungguhnya rahmat Allah amat dekat kepada orang-orang yang berbuat baik.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 57, "text": "وَهُوَ ٱلَّذِی یُرۡسِلُ ٱلرِّیَـٰحَ بُشۡرَۢا بَیۡنَ یَدَیۡ رَحۡمَتِهِۦۖ حَتَّىٰۤ إِذَاۤ أَقَلَّتۡ سَحَابࣰا ثِقَالࣰا سُقۡنَـٰهُ لِبَلَدࣲ مَّیِّتࣲ فَأَنزَلۡنَا بِهِ ٱلۡمَاۤءَ فَأَخۡرَجۡنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَ ٰتِۚ كَذَ ٰلِكَ نُخۡرِجُ ٱلۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّرُونَ ۝٥٧", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "والله تعالى هو الذي يرسل الرياح الطيبة اللينة مبشرات بالغيث الذي تثيره بإذن الله، فيستبشر الخلق برحمة الله، حتى إذا حملت الريح السحاب المحمل بالمطر ساقه الله بها لإحياء بلد، قد أجدبت أرضه، ويَبِست أشجاره وزرعه، فأنزل الله به المطر، فأخرج به الكلأ والأشجار والزروع، فعادت أشجاره محملة بأنواع الثمرات. كما نحيي هذا البلد الميت بالمطر نخرج الموتى من قبورهم أحياءً بعد فنائهم؛ لتتعظوا، فتستدلوا على توحيد الله وقدرته على البعث.", "isBasmala": false, "translation_en": "It is He who sends the wind ahead of His mercy. Then, when they have gathered up heavy clouds, We drive them to a dead land, where We make water come down, and with it We bring out all kinds of fruits. Thus We bring out the dead-perhaps you will reflect.", "translation_id": "Dan Dialah yang meniupkan angin sebagai pembawa berita gembira sebelum kedatangan rahmat-Nya (hujan); hingga apabila angin itu telah membawa awan mendung, Kami halau ke suatu daerah yang tandus, lalu Kami turunkan hujan di daerah itu, maka Kami keluarkan dengan sebab hujan itu pelbagai macam buah-buahan. Seperti itulah Kami membangkitkan orang-orang yang telah mati, mudah-mudahan kamu mengambil pelajaran.", "manzil": 2, "manzil_display": ""}], "158": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 58, "text": "وَٱلۡبَلَدُ ٱلطَّیِّبُ یَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِی خَبُثَ لَا یَخۡرُجُ إِلَّا نَكِدࣰاۚ كَذَ ٰلِكَ نُصَرِّفُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَشۡكُرُونَ ۝٥٨", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "والأرض النقية إذا نزل عليها المطر تُخْرج نباتًا -بإذن الله ومشيئته- طيبًا ميسرًا، وكذلك المؤمن إذا نزلت عليه آيات الله انتفع بها، وأثمرت فيه حياة صالحة، أما الأرض السَّبِخة الرديئة فإنها لا تُخرج النبات إلا عسرًا رديئا لا نفع فيه، ولا تُخرج نباتًا طيبًا، وكذلك الكافر لا ينتفع بآيات الله. مثل ذلك التنويع البديع في البيان نُنوِّع الحجج والبراهين لإثبات الحق لأناس يشكرون نعم الله، ويطيعونه.", "isBasmala": false, "translation_en": "As for the good land, it yields its produce by the leave of its Lord. But as for the bad, it produces nothing but hardship and misery. Thus We explain the revelations in various ways for people who are thankful.", "translation_id": "Dan tanah yang baik, tanaman-tanamannya tumbuh subur dengan seizin Allah; dan tanah yang tidak subur, tanaman-tanamannya hanya tumbuh merana. Demikianlah Kami mengulangi tanda-tanda kebesaran (Kami) bagi orang-orang yang bersyukur.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 59, "text": "لَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤ إِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمٍ عَظِیمࣲ ۝٥٩", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "لقد بعثنا نوحًا إلى قومه؛ ليدعوهم إلى توحيد الله سبحانه وإخلاص العبادة له، فقال: يا قوم اعبدوا الله وحده، ليس لكم من إله يستحق العبادة غيره جل وعلا فأخلصوا له العبادة فإن لم تفعلوا وبقيتم على عبادة أوثانكم، فإنني أخاف أن يحلَّ عليكم عذاب يوم يعظم فيه بلاؤكم، وهو يوم القيامة.", "isBasmala": false, "translation_en": "We sent Noah to his people. He said, \"O my people! Worship God; you have no god other than Him. I fear for you the punishment of a tremendous Day.\"", "translation_id": "Sesungguhnya Kami telah mengutus Nuh kepada kaumnya lalu ia berkata: \"Wahai kaumku sembahlah Allah, sekali-kali tak ada Tuhan bagimu selain-Nya\". Sesungguhnya (kalau kamu tidak menyembah Allah), aku takut kamu akan ditimpa azab hari yang besar (kiamat).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 60, "text": "قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦۤ إِنَّا لَنَرَىٰكَ فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٦٠", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "قال له سادتهم وكبراؤهم: إنا لنعتقد -يا نوح- أنك في ضلال بيِّن عن طريق الصواب.", "isBasmala": false, "translation_en": "The dignitaries among his people said, \"We see that you are in obvious error.\"", "translation_id": "Pemuka-pemuka dari kaumnya berkata: \"Sesungguhnya kami memandang kamu berada dalam kesesatan yang nyata\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 61, "text": "قَالَ یَـٰقَوۡمِ لَیۡسَ بِی ضَلَـٰلَةࣱ وَلَـٰكِنِّی رَسُولࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ ۝٦١", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "قال نوح: يا قوم لست ضالا في مسألة من المسائل بوجه من الوجوه، ولكني رسول من رب العالمين ربي وربكم ورب جميع الخلق.", "isBasmala": false, "translation_en": "He said, \"O my people, I am not in error, but I am a messenger from the Lord of the Worlds.\"", "translation_id": "Nuh menjawab: \"Hai kaumku, tak ada padaku kesesatan sedikitpun tetapi aku adalah utusan dari Tuhan semesta alam\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 62, "text": "أُبَلِّغُكُمۡ رِسَـٰلَـٰتِ رَبِّی وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝٦٢", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "أُبلِّغكم ما أُرسلت به من ربي، وأنصح لكم محذرًا لكم من عذاب الله ومبشرًا بثوابه، وأعلم من شريعته ما لا تعلمون.", "isBasmala": false, "translation_en": "\"I deliver to you the messages of my Lord, and I advise you, and I know from God what you do not know.\"", "translation_id": "\"Aku sampaikan kepadamu amanat-amanat Tuhanku dan aku memberi nasehat kepadamu. dan aku mengetahui dari Allah apa yang tidak kamu ketahui\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 63, "text": "أَوَعَجِبۡتُمۡ أَن جَاۤءَكُمۡ ذِكۡرࣱ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلࣲ مِّنكُمۡ لِیُنذِرَكُمۡ وَلِتَتَّقُوا۟ وَلَعَلَّكُمۡ تُرۡحَمُونَ ۝٦٣", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "وهل أثار عجبكم أن أنزل الله تعالى إليكم ما يذكركم بما فيه الخير لكم، على لسان رجل منكم، تعرفون نسبه وصدقه؛ ليخوِّفكم بأس الله تعالى وعقابه، ولتتقوا سخطه بالإيمان به، ورجاء أن تظفروا برحمته وجزيل ثوابه؟", "isBasmala": false, "translation_en": "\"Do you wonder that a reminder has come to you from your Lord, through a man from among you, to warn you, and to lead you to righteousness, so that you may attain mercy?\"", "translation_id": "Dan apakah kamu (tidak percaya) dan heran bahwa datang kepada kamu peringatan dari Tuhanmu dengan perantaraan seorang laki-laki dari golonganmu agar dia memberi peringatan kepadamu dan mudah-mudahan kamu bertakwa dan supaya kamu mendapat rahmat?", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 64, "text": "فَكَذَّبُوهُ فَأَنجَیۡنَـٰهُ وَٱلَّذِینَ مَعَهُۥ فِی ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمًا عَمِینَ ۝٦٤", "juz": 8, "hizb": "(*½ ح 16*)", "tafsir": "فكذبوا نوحًا فأنجيناه ومَن آمن معه في السفينة، وأغرقنا الكفار الذين كذبوا بحججنا الواضحة. إنهم كانوا عُمْيَ القلوب عن رؤية الحق.", "isBasmala": false, "translation_en": "But they called him a liar. So We saved him and those with him in the Ark, and We drowned those who rejected Our revelations. They were blind people.", "translation_id": "Maka mereka mendustakan Nuh, kemudian Kami selamatkan dia dan orang-orang yang bersamanya dalam bahtera, dan Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami. Sesungguhnya mereka adalah kaum yang buta (mata hatinya).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 65, "text": "۞ وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤۚ أَفَلَا تَتَّقُونَ ۝٦٥", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "ولقد أرسلنا إلى قبيلة عاد أخاهم هودا حين عبدوا الأوثان من دون الله، فقال لهم: اعبدوا الله وحده، ليس لكم من إله يستحق العبادة غيره جل وعلا فأخلصوا له العبادة أفلا تتقون عذاب الله وسخطه عليكم؟", "isBasmala": false, "translation_en": "And to Aad, their brother Hud. He said, \"O my people! Worship God; you have no god other than Him. Will you not take heed?\"", "translation_id": "Dan (Kami telah mengutus) kepada kaum 'Aad saudara mereka, Hud. Ia berkata: \"Hai kaumku, sembahlah Allah, sekali-kali tidak ada Tuhan bagimu selain dari-Nya. Maka mengapa kamu tidak bertakwa kepada-Nya?\"", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 66, "text": "قَالَ ٱلۡمَلَأُ ٱلَّذِینَ كَفَرُوا۟ مِن قَوۡمِهِۦۤ إِنَّا لَنَرَىٰكَ فِی سَفَاهَةࣲ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَـٰذِبِینَ ۝٦٦", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "قال الكبراء الذين كفروا من قوم هود: إنا لنعلم أنك بدعوتك إيانا إلى ترك عبادة آلهتنا وعبادة الله وحده ناقص العقل، وإنا لنعتقد أنك من الكاذبين على الله فيما تقول.", "isBasmala": false, "translation_en": "The elite of his people who disbelieved said, \"We see foolishness in you, and we think that you are a liar.\"", "translation_id": "Pemuka-pemuka yang kafir dari kaumnya berkata: \"Sesungguhnya kami benar benar memandang kamu dalam keadaan kurang akal dan sesungguhnya kami menganggap kamu termasuk orang orang yang berdusta\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 67, "text": "قَالَ یَـٰقَوۡمِ لَیۡسَ بِی سَفَاهَةࣱ وَلَـٰكِنِّی رَسُولࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ ۝٦٧", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "قال هود: يا قوم ليس بي نقص في عقلي، ولكني رسول إليكم من رب الخلق أجمعين.", "isBasmala": false, "translation_en": "He said, \"O my people! There is no foolishness in me, but I am a messenger from the Lord of the Worlds.", "translation_id": "Hud herkata \"Hai kaumku, tidak ada padaku kekurangan akal sedikitpun, tetapi aku ini adalah utusan dari Tuhan semesta alam.", "manzil": 2, "manzil_display": ""}], "159": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 68, "text": "أُبَلِّغُكُمۡ رِسَـٰلَـٰتِ رَبِّی وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِینٌ ۝٦٨", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "أُبلِّغكم ما أرسلني به ربي إليكم، وأنا لكم - فيما دعوتكم إليه من توحيد الله والعمل بشريعته - ناصح، أمين على وحي الله تعالى.", "isBasmala": false, "translation_en": "\"I convey to you the messages of my Lord, and I am a trustworthy adviser to you.\"", "translation_id": "Aku menyampaikan amanat-amanat Tuhanku kepadamu dan aku hanyalah pemberi nasehat yang terpercaya bagimu\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 69, "text": "أَوَعَجِبۡتُمۡ أَن جَاۤءَكُمۡ ذِكۡرࣱ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلࣲ مِّنكُمۡ لِیُنذِرَكُمۡۚ وَٱذۡكُرُوۤا۟ إِذۡ جَعَلَكُمۡ خُلَفَاۤءَ مِنۢ بَعۡدِ قَوۡمِ نُوحࣲ وَزَادَكُمۡ فِی ٱلۡخَلۡقِ بَصۜۡطَةࣰۖ فَٱذۡكُرُوۤا۟ ءَالَاۤءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ ۝٦٩", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "وهل أثار عجبكم أن أنزل الله تعالى إليكم ما يذكركم بما فيه الخير لكم، على لسان رجل منكم، تعرفون نسبه وصدقه؛ ليخوِّفكم بأس الله وعقابه؟ واذكروا نعمة الله عليكم إذ جعلكم تخلفون في الأرض مَن قبلكم من بعد ما أهلك قوم نوح، وزاد في أجسامكم قوة وضخامة، فاذكروا نِعَمَ الله الكثيرة عليكم؛ رجاء أن تفوزوا الفوز العظيم في الدنيا والآخرة.", "isBasmala": false, "translation_en": "\"Are you surprised that a reminder has come to you from your Lord, through a man from among you, to warn you? Remember how He made you successors after the people of Noah, and increased you greatly in stature. And remember God's blessings, so that you may prosper.\"", "translation_id": "Apakah kamu (tidak percaya) dan heran bahwa datang kepadamu peringatan dari Tuhanmu yang dibawa oleh seorang laki-laki di antaramu untuk memberi peringatan kepadamu? Dan ingatlah oleh kamu sekalian di waktu Allah menjadikan kamu sebagai pengganti-pengganti (yang berkuasa) sesudah lenyapnya kaum Nuh, dan Tuhan telah melebihkan kekuatan tubuh dan perawakanmu (daripada kaum Nuh itu). Maka ingatlah nikmat-nikmat Allah supaya kamu mendapat keberuntungan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 70, "text": "قَالُوۤا۟ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ یَعۡبُدُ ءَابَاۤؤُنَا فَأۡتِنَا بِمَا تَعِدُنَاۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ ۝٧٠", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "قالت عاد لهود عليه السلام: أدعوتنا لعبادة الله وحده وهَجْر عبادة الأصنام التي ورثنا عبادتها عن آبائنا؟ فأتنا بالعذاب الذي تخوفنا به إن كنت من أهل الصدق فيما تقول.", "isBasmala": false, "translation_en": "They said, \"Did you come to us to make us worship God alone, and abandon what our ancestors used to worship? Then bring us what you threaten us with, if you are truthful.\"", "translation_id": "Mereka berkata: \"Apakah kamu datang kepada kami, agar kami hanya menyembah Allah saja dan meninggalkan apa yang biasa disembah oleh bapak-bapak kami? maka datangkanlah azab yang kamu ancamkan kepada kami jika kamu termasuk orang-orang yang benar\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 71, "text": "قَالَ قَدۡ وَقَعَ عَلَیۡكُم مِّن رَّبِّكُمۡ رِجۡسࣱ وَغَضَبٌۖ أَتُجَـٰدِلُونَنِی فِیۤ أَسۡمَاۤءࣲ سَمَّیۡتُمُوهَاۤ أَنتُمۡ وَءَابَاۤؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَـٰنࣲۚ فَٱنتَظِرُوۤا۟ إِنِّی مَعَكُم مِّنَ ٱلۡمُنتَظِرِینَ ۝٧١", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "قال هود لقومه: قد حلَّ بكم عذاب وغضب من ربكم جل وعلا أتجادلونني في هذه الأصنام التي سميتموها آلهة أنتم وآباؤكم؟ ما نزَّل الله بها من حجة ولا برهان؛ لأنها مخلوقة لا تضر ولا تنفع، وإنما المعبود وحده هو الخالق سبحانه، فانتظروا نزول العذاب عليكم فإني منتظر معكم نزوله، وهذا غاية في التهديد والوعيد.", "isBasmala": false, "translation_en": "He said, \"Condemnation and wrath have befallen you from your Lord. Are you arguing with me over names, which you and your ancestors invented, for which God sent down no authority? Just wait; I am waiting with you.\"", "translation_id": "Ia berkata: \"Sungguh sudah pasti kamu akan ditimpa azab dan kemarahan dari Tuhanmu\". Apakah kamu sekalian hendak berbantah dengan aku tentang nama-nama (berhala) yang kamu beserta nenek moyangmu menamakannya, padahal Allah sekali-kali tidak menurunkan hujjah untuk itu? Maka tunggulah (azab itu), sesungguhnya aku juga termasuk orang yamg menunggu bersama kamu\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 72, "text": "فَأَنجَیۡنَـٰهُ وَٱلَّذِینَ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَقَطَعۡنَا دَابِرَ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۖ وَمَا كَانُوا۟ مُؤۡمِنِینَ ۝٧٢", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "فوقع عذاب الله بإرسال الريح الشديدة عليهم، فأنجى الله هودًا والذين آمنوا معه برحمة عظيمة منه تعالى، وأهلك الكفار من قومه جميعا ودمَّرهم عن آخرهم، وما كانوا مؤمنين لجمعهم بين التكذيب بآيات الله وترك العمل الصالح.", "isBasmala": false, "translation_en": "So We saved him and those with him, by mercy from Us, and We cut off the roots of those who rejected Our revelations and were not believers.", "translation_id": "Maka kami selamatkan Hud beserta orang-orang yang bersamanya dengan rahmat yang besar dari Kami, dan Kami tumpas orang-orang yang mendustakan ayat-ayat Kami, dan tiadalah mereka orang-orang yang beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 73, "text": "وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَـٰلِحࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۖ قَدۡ جَاۤءَتۡكُم بَیِّنَةࣱ مِّن رَّبِّكُمۡۖ هَـٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَایَةࣰۖ فَذَرُوهَا تَأۡكُلۡ فِیۤ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوۤءࣲ فَیَأۡخُذَكُمۡ عَذَابٌ أَلِیمࣱ ۝٧٣", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "ولقد أرسلنا إلى قبيلة ثمود أخاهم صالحًا لـمَّا عبدوا الأوثان من دون الله تعالى. فقال صالح لهم: يا قوم اعبدوا الله وحده؛ ليس لكم من إله يستحق العبادة غيره جل وعلا، فأخلصوا له العبادة، قد جئتكم بالبرهان على صدق ما أدعوكم إليه، إذ دعوتُ الله أمامكم، فأخرج لكم من الصخرة ناقة عظيمة كما سألتم، فاتركوها تأكل في أرض الله من المراعي، ولا تتعرضوا لها بأي أذى، فيصيبكم بسبب ذلك عذاب موجع.", "isBasmala": false, "translation_en": "And to Thamood, their brother Saleh. He said, \"O my people! Worship God; you have no god other than Him. Clarification has come to you from your Lord. This she-camel of God is a sign for you. So leave her to graze on God's earth, and do her no harm, lest a painful penalty seizes you.\"", "translation_id": "Dan (Kami telah mengutus) kepada kaum Tsamud saudara mereka Shaleh. Ia berkata: \"Hai kaumku, sembahlah Allah, sekali-kali tidak ada Tuhan bagimu selain-Nya. Sesungguhnya telah datang bukti yang nyata kepadamu dari Tuhanmu. Unta betina Allah ini menjadi tanda bagimu, maka biarkanlah dia makan di bumi Allah, dan janganlah kamu mengganggunya dengan gangguan apapun, (yang karenanya) kamu akan ditimpa siksaan yang pedih\".", "manzil": 2, "manzil_display": ""}], "160": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 74, "text": "وَٱذۡكُرُوۤا۟ إِذۡ جَعَلَكُمۡ خُلَفَاۤءَ مِنۢ بَعۡدِ عَادࣲ وَبَوَّأَكُمۡ فِی ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورࣰا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُیُوتࣰاۖ فَٱذۡكُرُوۤا۟ ءَالَاۤءَ ٱللَّهِ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ ۝٧٤", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "واذكروا نعمة الله عليكم، إذ جعلكم تَخْلُفون في الأرض مَن قبلكم، من بعد قبيلة عاد، ومكَّن لكم في الأرض الطيبة تنزلونها، فتبنون في سهولها البيوت العظيمة، وتنحتون من جبالها بيوتًا أخرى، فاذكروا نِعَمَ الله عليكم، ولا تَسْعَوا في الأرض بالإفساد.", "isBasmala": false, "translation_en": "\"And remember how He made you successors after Aad, and settled you in the land. You make for yourselves mansions on its plains, and carve out dwellings in the mountains. So remember God's benefits, and do not roam the earth corruptingly.\"", "translation_id": "Dan ingatlah olehmu di waktu Tuhan menjadikam kamu pengganti-pengganti (yang berkuasa) sesudah kaum 'Aad dan memberikan tempat bagimu di bumi. Kamu dirikan istana-istana di tanah-tanahnya yang datar dan kamu pahat gunung-gunungnya untuk dijadikan rumah; maka ingatlah nikmat-nikmat Allah dan janganlah kamu merajalela di muka bumi membuat kerusakan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 75, "text": "قَالَ ٱلۡمَلَأُ ٱلَّذِینَ ٱسۡتَكۡبَرُوا۟ مِن قَوۡمِهِۦ لِلَّذِینَ ٱسۡتُضۡعِفُوا۟ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَـٰلِحࣰا مُّرۡسَلࣱ مِّن رَّبِّهِۦۚ قَالُوۤا۟ إِنَّا بِمَاۤ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ ۝٧٥", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "قال السادة والكبراء من الذين استعلَوا -من قوم صالح- للمؤمنين الذين استضعفوهم، واستهانوا بهم: أتعلمون حقيقة أن صالحًا قد أرسله الله إلينا؟ قال الذين آمنوا: إنا مصدقون بما أرسله الله به، متَّبعون لشرعه.", "isBasmala": false, "translation_en": "The elite of his people, who were arrogant, said to the common people who had believed, \"Do you know that Saleh is sent from his Lord?\" They said, \"We are believers in what he was sent with.\"", "translation_id": "Pemuka-pemuka yang menyombongkan diri di antara kaumnya berkata kepada orang-orang yang dianggap lemah yang telah beriman di antara mereka: \"Tahukah kamu bahwa Shaleh di utus (menjadi rasul) oleh Tuhannya?\". Mereka menjawab: \"Sesungguhnya kami beriman kepada wahyu, yang Shaleh diutus untuk menyampaikannya\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 76, "text": "قَالَ ٱلَّذِینَ ٱسۡتَكۡبَرُوۤا۟ إِنَّا بِٱلَّذِیۤ ءَامَنتُم بِهِۦ كَـٰفِرُونَ ۝٧٦", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "قال الذين استعلَوْا: إنَّا بالذي صدَّقتم به واتبعتموه من نبوة صالح جاحدون.", "isBasmala": false, "translation_en": "Those who were arrogant said, \"We reject what you believe in.\"", "translation_id": "Orang-orang yang menyombongkan diri berkata: \"Sesungguhnya kami adalah orang yang tidak percaya kepada apa yang kamu imani itu\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 77, "text": "فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوۡا۟ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُوا۟ یَـٰصَـٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَاۤ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِینَ ۝٧٧", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "فنحروا الناقة استخفافا منهم بوعيد صالح، واستكبروا عن امتثال أمر ربهم، وقالوا على سبيل الاستهزاء واستبعاد العذاب: يا صالح ائتنا بما تتوعَّدنا به من العذاب، إن كنت مِن رسل الله.", "isBasmala": false, "translation_en": "So they hamstrung the she-camel, and defied the command of their Lord, and said, \"O Saleh, bring upon us what you threaten us with, if you are one of the messengers.\"", "translation_id": "Kemudian mereka sembelih unta betina itu, dan mereka berlaku angkuh terhadap perintah Tuhan. Dan mereka berkata: \"Hai Shaleh, datangkanlah apa yang kamu ancamkan itu kepada kami, jika (betul) kamu termasuk orang-orang yang diutus (Allah)\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 78, "text": "فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُوا۟ فِی دَارِهِمۡ جَـٰثِمِینَ ۝٧٨", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "فأخذَت الذين كفروا الزلزلةُ الشديدة التي خلعت قلوبهم، فأصبحوا في بلدهم هالكين، لاصقين بالأرض على رُكَبهم ووجوههم، لم يُفْلِت منهم أحد.", "isBasmala": false, "translation_en": "Whereupon the quake overtook them, and they became lifeless bodies in their homes.", "translation_id": "Karena itu mereka ditimpa gempa, maka jadilah mereka mayat-mayat yang bergelimpangan di tempat tinggal mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 79, "text": "فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ یَـٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّی وَنَصَحۡتُ لَكُمۡ وَلَـٰكِن لَّا تُحِبُّونَ ٱلنَّـٰصِحِینَ ۝٧٩", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "فأعرض صالح عليه السلام عن قومه -حين عقروا الناقة وحل بهم الهلاك- وقال لهم: يا قوم لقد أبلغتكم ما أمرني ربي بإبلاغه من أمره ونهيه، وبَذَلْت لكم وسعي في الترغيب والترهيب والنصح، ولكنكم لا تحبون الناصحين، فرددتم قولهم، وأطعتم كل شيطان رجيم.", "isBasmala": false, "translation_en": "Then he turned away from them, and said, \"O my people, I have delivered to you the message of my Lord, and I have advised you, but you do not like those who give advice.\"", "translation_id": "Maka Shaleh meninggalkan mereka seraya berkata: \"Hai kaumku sesungguhnya aku telah menyampaikan kepadamu amanat Tuhanku, dan aku telah memberi nasehat kepadamu, tetapi kamu tidak menyukai orang-orang yang memberi nasehat\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 80, "text": "وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦۤ أَتَأۡتُونَ ٱلۡفَـٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدࣲ مِّنَ ٱلۡعَـٰلَمِینَ ۝٨٠", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "واذكر -أيها الرسول- لوطًا عليه السلام حين قال لقومه: أتفعلون الفعلة المنكرة التي بلغت نهاية القبح؟ ما فعلها مِن أحد قبلكم من المخلوقين.", "isBasmala": false, "translation_en": "And Lot, when he said to his people, \"Do you commit lewdness no people anywhere have ever committed before you?\"", "translation_id": "Dan (Kami juga telah mengutus) Luth (kepada kaumnya). (Ingatlah) tatkala dia berkata kepada mereka: \"Mengapa kamu mengerjakan perbuatan faahisyah itu, yang belum pernah dikerjakan oleh seorangpun (di dunia ini) sebelummu?\"", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 81, "text": "إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةࣰ مِّن دُونِ ٱلنِّسَاۤءِۚ بَلۡ أَنتُمۡ قَوۡمࣱ مُّسۡرِفُونَ ۝٨١", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "إنكم لتأتون الذكور في أدبارهم، شهوة منكم لذلك، غير مبالين بقبحها، تاركين الذي أحلَّه الله لكم من نسائكم، بل أنتم قوم متجاوزون لحدود الله في الإسراف. إن إتيان الذكور دون الإناث من الفواحش التي ابتدعها قوم لوط، ولم يسبقهم بها أحد من الخلق.", "isBasmala": false, "translation_en": "\"You lust after men rather than women. You are an excessive people.\"", "translation_id": "Sesungguhnya kamu mendatangi lelaki untuk melepaskan nafsumu (kepada mereka), bukan kepada wanita, malah kamu ini adalah kaum yang melampaui batas.", "manzil": 2, "manzil_display": ""}], "161": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 82, "text": "وَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوۤا۟ أَخۡرِجُوهُم مِّن قَرۡیَتِكُمۡۖ إِنَّهُمۡ أُنَاسࣱ یَتَطَهَّرُونَ ۝٨٢", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "وما كان جواب قوم لوط حين أنكر عليهم فعلهم الشنيع إلا أن قال بعضهم لبعض: أخرجوا لوطًا وأهله من بلادكم، إنه ومن تبعه أناس يتنزهون عن إتيان أدبار الرجال والنساء.", "isBasmala": false, "translation_en": "And his people's only answer was to say, \"Expel them from your town; they are purist people.\"", "translation_id": "Jawab kaumnya tidak lain hanya mengatakan: \"Usirlah mereka (Luth dan pengikut-pengikutnya) dari kotamu ini; sesungguhnya mereka adalah orang-orang yang berpura-pura mensucikan diri\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 83, "text": "فَأَنجَیۡنَـٰهُ وَأَهۡلَهُۥۤ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَـٰبِرِینَ ۝٨٣", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "فأنجى الله لوطًا وأهله من العذاب حيث أمره بمغادرة ذلك البلد، إلا امرأته، فإنها كانت من الهالكين الباقين في عذاب الله.", "isBasmala": false, "translation_en": "But We saved him and his family, except for his wife; she was of those who lagged behind.", "translation_id": "Kemudian Kami selamatkan dia dan pengikut-pengikutnya kecuali isterinya; dia termasuk orang-orang yang tertinggal (dibinasakan).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 84, "text": "وَأَمۡطَرۡنَا عَلَیۡهِم مَّطَرࣰاۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُجۡرِمِینَ ۝٨٤", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "وعذَّب الله الكفار من قوم لوط بأن أنزل عليهم مطرًا من الحجارة، وقلب بلادهم، فجعل عاليها سافلها، فانظر -أيها الرسول- كيف صارت عاقبة الذين اجترؤوا على معاصي الله وكذبوا رسله.", "isBasmala": false, "translation_en": "And We rained down on them a rain; note the consequences for the sinners.", "translation_id": "Dan Kami turunkan kepada mereka hujan (batu); maka perhatikanlah bagaimana kesudahan orang-orang yang berdosa itu.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 85, "text": "وَإِلَىٰ مَدۡیَنَ أَخَاهُمۡ شُعَیۡبࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۖ قَدۡ جَاۤءَتۡكُم بَیِّنَةࣱ مِّن رَّبِّكُمۡۖ فَأَوۡفُوا۟ ٱلۡكَیۡلَ وَٱلۡمِیزَانَ وَلَا تَبۡخَسُوا۟ ٱلنَّاسَ أَشۡیَاۤءَهُمۡ وَلَا تُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ بَعۡدَ إِصۡلَـٰحِهَاۚ ذَ ٰلِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِینَ ۝٨٥", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "ولقد أرسلنا إلى قبيلة \"مدين\" أخاهم شعيبًا عليه السلام، فقال لهم: يا قوم اعبدوا الله وحده لا شريك له؛ ليس لكم مِن إله يستحق العبادة غيره جل وعلا فأخلصوا له العبادة، قد جاءكم برهان من ربكم على صِدْق ما أدعوكم إليه، فأدوا للناس حقوقهم بإيفاء الكيل والميزان، ولا تنقصوهم حقوقهم فتظلموهم، ولا تفسدوا في الأرض -بالكفر والظلم- بعد إصلاحها بشرائع الأنبياء السابقين عليهم السلام. ذلك الذي دعوتكم إليه خير لكم في دنياكم وأخراكم، إن كنتم مصدقيَّ فيما دعوتكم إليه، عاملين بشرع الله.", "isBasmala": false, "translation_en": "And to Median, their brother Shuaib. He said, \"O my people, worship God; you have no god other than Him. A clear proof has come to you from your Lord. Give full measure and weight, and do not cheat people out of their rights, and do not corrupt the land once it has been set right. This is better for you, if you are believers.\"", "translation_id": "Dan (Kami telah mengutus) kepada penduduk Mad-yan saudara mereka, Syu'aib. Ia berkata: \"Hai kaumku, sembahlah Allah, sekali-kali tidak ada Tuhan bagimu selain-Nya. Sesungguhnya telah datang kepadamu bukti yang nyata dari Tuhanmu. Maka sempurnakanlah takaran dan timbangan dan janganlah kamu kurangkan bagi manusia barang-barang takaran dan timbangannya, dan janganlah kamu membuat kerusakan di muka bumi sesudah Tuhan memperbaikinya. Yang demikian itu lebih baik bagimu jika betul-betul kamu orang-orang yang beriman\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 86, "text": "وَلَا تَقۡعُدُوا۟ بِكُلِّ صِرَ ٰطࣲ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِیلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجࣰاۚ وَٱذۡكُرُوۤا۟ إِذۡ كُنتُمۡ قَلِیلࣰا فَكَثَّرَكُمۡۖ وَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُفۡسِدِینَ ۝٨٦", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "ولا تقعدوا بكل طريق تتوعدون الناس بالقتل، إن لم يعطوكم أموالهم، وتصدُّون عن سبيل الله القويم من صدَّق به عز وجل، وعمل صالحًا، وتبغون سبيل الله أن تكون معوجة، وتميلونها اتباعًا لأهوائكم، وتنفِّرون الناس عن اتباعها. واذكروا نعمة الله تعالى عليكم إذ كان عددكم قليلا فكثَّركم، فأصبحتم أقوياء عزيزين، وانظروا كيف كان عاقبة المفسدين في الأرض، وما حلَّ بهم من الهلاك والدمار؟", "isBasmala": false, "translation_en": "\"And do not lurk on every path, making threats and turning away from the path of God those who believe in Him, seeking to distort it. And remember how you were few, and how He made you numerous. So note the consequences for the corrupters.\"", "translation_id": "Dan janganlah kamu duduk di tiap-tiap jalan dengan menakut-nakuti dan menghalang-halangi orang yang beriman dari jalan Allah, dan menginginkan agar jalan Allah itu menjadi bengkok. Dan ingatlah di waktu dahulunya kamu berjumlah sedikit, lalu Allah memperbanyak jumlah kamu. Dan perhatikanlah bagaimana kesudahan orang-orang yang berbuat kerusakan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 87, "text": "وَإِن كَانَ طَاۤىِٕفَةࣱ مِّنكُمۡ ءَامَنُوا۟ بِٱلَّذِیۤ أُرۡسِلۡتُ بِهِۦ وَطَاۤىِٕفَةࣱ لَّمۡ یُؤۡمِنُوا۟ فَٱصۡبِرُوا۟ حَتَّىٰ یَحۡكُمَ ٱللَّهُ بَیۡنَنَاۚ وَهُوَ خَیۡرُ ٱلۡحَـٰكِمِینَ ۝٨٧", "juz": 8, "hizb": "(*¾ ح 16*)", "tafsir": "وإن كان جماعة منكم صدَّقوا بالذي أرسلني الله به، وجماعة لم يصدِّقوا بذلك، فانتظروا أيها المكذبون قضاء الله الفاصل بيننا وبينكم حين يحلُّ عليكم عذابه الذي أنذرتكم به. والله -جلَّ وعلا- هو خير الحاكمين بين عباده.", "isBasmala": false, "translation_en": "\"Since some of you believed in what I was sent with, and some did not believe, be patient until God judges between us; for He is the Best of Judges.\"", "translation_id": "Jika ada segolongan daripada kamu beriman kepada apa yang aku diutus untuk menyampaikannya dan ada (pula) segolongan yang tidak beriman, maka bersabarlah, hingga Allah menetapkan hukumnya di antara kita; dan Dia adalah Hakim yang sebaik-baiknya.", "manzil": 2, "manzil_display": ""}], "162": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 88, "text": "۞ قَالَ ٱلۡمَلَأُ ٱلَّذِینَ ٱسۡتَكۡبَرُوا۟ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ یَـٰشُعَیۡبُ وَٱلَّذِینَ ءَامَنُوا۟ مَعَكَ مِن قَرۡیَتِنَاۤ أَوۡ لَتَعُودُنَّ فِی مِلَّتِنَاۚ قَالَ أَوَ لَوۡ كُنَّا كَـٰرِهِینَ ۝٨٨", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "قال السادة والكبراء من قوم شعيب الذين تكبروا عن الإيمان بالله واتباع رسوله شعيب عليه السلام: لنخرجنك يا شعيب ومَن معك من المؤمنين من ديارنا، إلا إذا صرتم إلى ديننا، قال شُعيب منكرًا ومتعجبًا من قولهم: أنتابعكم على دينكم ومِلَّتكم الباطلة، ولو كنا كارهين لها لعِلْمِنا ببطلانها؟", "isBasmala": false, "translation_en": "The arrogant elite among his people said, \"O Shuaib, We will evict you from our town, along with those who believe with you, unless you return to our religion.\" He said, \"Even if we are unwilling?\"", "translation_id": "Pemuka-pemuka dan kaum Syu'aib yang menyombongkan dan berkata: \"Sesungguhnya kami akan mengusir kamu hai Syu'aib dan orang-orang yang beriman bersamamu dari kota kami, atau kamu kembali kepada agama kami\". Berkata Syu'aib: \"Dan apakah (kamu akan mengusir kami), kendatipun kami tidak menyukainya?\"", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 89, "text": "قَدِ ٱفۡتَرَیۡنَا عَلَى ٱللَّهِ كَذِبًا إِنۡ عُدۡنَا فِی مِلَّتِكُم بَعۡدَ إِذۡ نَجَّىٰنَا ٱللَّهُ مِنۡهَاۚ وَمَا یَكُونُ لَنَاۤ أَن نَّعُودَ فِیهَاۤ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُ رَبُّنَاۚ وَسِعَ رَبُّنَا كُلَّ شَیۡءٍ عِلۡمًاۚ عَلَى ٱللَّهِ تَوَكَّلۡنَاۚ رَبَّنَا ٱفۡتَحۡ بَیۡنَنَا وَبَیۡنَ قَوۡمِنَا بِٱلۡحَقِّ وَأَنتَ خَیۡرُ ٱلۡفَـٰتِحِینَ ۝٨٩", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "وقال شعيب لقومه مستدركًا: قد اختلقنا على الله الكذب إن عُدْنا إلى دينكم بعد أن أنقذنا الله منه، وليس لنا أن نتحول إلى غير دين ربنا إلا أن يشاء الله ربنا، وقد وسع ربنا كل شيء علمًا، فيعلم ما يصلح للعباد، على الله وحده اعتمادنا هداية ونصرة، ربنا احكم بيننا وبين قومنا بالحق، وأنت خير الحاكمين.", "isBasmala": false, "translation_en": "\"We would be fabricating falsehood against God, if we were to return to your religion, after God has saved us from it. It is not for us to return to it, unless God, our Lord, wills. Our Lord embraces all things in knowledge. In God we place our trust. Our Lord, decide between us and our people in truth, for You are the Best of Deciders.\"", "translation_id": "Sungguh kami mengada-adakan kebohongan yang benar terhadap Allah, jika kami kembali kepada agamamu, sesudah Allah melepaskan kami dari padanya. Dan tidaklah patut kami kembali kepadanya, kecuali jika Allah, Tuhan kami menghendaki(nya). Pengetahuan Tuhan kami meliputi segala sesuatu. Kepada Allah sajalah kami bertawakkal. Ya Tuhan kami, berilah keputusan antara kami dan kaum kami dengan hak (adil) dan Engkaulah Pemberi keputusan yang sebaik-baiknya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 90, "text": "وَقَالَ ٱلۡمَلَأُ ٱلَّذِینَ كَفَرُوا۟ مِن قَوۡمِهِۦ لَىِٕنِ ٱتَّبَعۡتُمۡ شُعَیۡبًا إِنَّكُمۡ إِذࣰا لَّخَـٰسِرُونَ ۝٩٠", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "وقال السادة والكبراء المكذبون الرافضون لدعوة التوحيد إمعانًا في العتوِّ والتمرد، محذرين من اتباع شعيب: لئن اتبعتم شعيبًا إنكم إذًا لهالكون.", "isBasmala": false, "translation_en": "The elite of his people who disbelieved said, \"If you follow Shuaib, you will be losers.\"", "translation_id": "Pemuka-pemuka kaum Syu'aib yang kafir berkata (kepada sesamanya): \"Sesungguhnya jika kamu mengikuti Syu'aib, tentu kamu jika berbuat demikian (menjadi) orang-orang yang merugi\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 91, "text": "فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُوا۟ فِی دَارِهِمۡ جَـٰثِمِینَ ۝٩١", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "فأخذَتْ قومَ شعيب الزلزلةُ الشديدة، فأصبحوا في دارهم صرعى ميتين.", "isBasmala": false, "translation_en": "Thereupon, the quake struck them; and they became lifeless bodies in their homes.", "translation_id": "Kemudian mereka ditimpa gempa, maka jadilah mereka mayat-mayat yang bergelimpangan di dalam rumah-rumah mereka,", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 92, "text": "ٱلَّذِینَ كَذَّبُوا۟ شُعَیۡبࣰا كَأَن لَّمۡ یَغۡنَوۡا۟ فِیهَاۚ ٱلَّذِینَ كَذَّبُوا۟ شُعَیۡبࣰا كَانُوا۟ هُمُ ٱلۡخَـٰسِرِینَ ۝٩٢", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "الذين كذَّبوا شعيبًا كأنهم لم يقيموا في ديارهم، ولم يتمتعوا فيها، حيث استؤصلوا، فلم يبق لهم أثر، وأصابهم الخسران والهلاك في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Those who rejected Shuaib-as if they never prospered therein. Those who rejected Shuaib-it was they who were the losers.", "translation_id": "(yaitu) orang-orang yang mendustakan Syu'aib seolah-olah mereka belum pernah berdiam di kota itu; orang-orang yang mendustakan Syu'aib mereka itulah orang-orang yang merugi.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 93, "text": "فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ یَـٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَـٰلَـٰتِ رَبِّی وَنَصَحۡتُ لَكُمۡۖ فَكَیۡفَ ءَاسَىٰ عَلَىٰ قَوۡمࣲ كَـٰفِرِینَ ۝٩٣", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "فأعرض شعيب عنهم حينما أيقن بحلول العذاب بهم، وقال: يا قوم لقد أبلغتكم رسالات ربي، ونصحت لكم بالدخول في دين الله والإقلاع عما أنتم عليه، فلم تسمعوا ولم تطيعوا، فكيف أحزن على قوم جحدوا وحدانية الله وكذبوا رسله؟", "isBasmala": false, "translation_en": "So he turned away from them, and said, \"O my people, I have delivered to you the messages of my Lord, and I have advised you, so why should I grieve over a disbelieving people?\"", "translation_id": "Maka Syu'aib meninggalkan mereka seraya berkata: \"Hai kaumku, sesungguhnya aku telah menyampaikan kepadamu amanat-amanat Tuhanku dan aku telah memberi nasehat kepadamu. Maka bagaimana aku akan bersedih hati terhadap orang-orang yang kafir?\"", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 94, "text": "وَمَاۤ أَرۡسَلۡنَا فِی قَرۡیَةࣲ مِّن نَّبِیٍّ إِلَّاۤ أَخَذۡنَاۤ أَهۡلَهَا بِٱلۡبَأۡسَاۤءِ وَٱلضَّرَّاۤءِ لَعَلَّهُمۡ یَضَّرَّعُونَ ۝٩٤", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "وما أرسلنا في قرية من نبي يدعوهم إلى عبادة الله، وينهاهم عمَّا هم فيه من الشرك، فكذَّبه قومه، إلا ابتليناهم بالبأساء والضراء، فأصبناهم في أبدانهم بالأمراض والأسقام، وفي أموالهم بالفقر والحاجة؛ رجاء أن يستكينوا، وينيبوا إلى الله، ويرجعوا إلى الحق.", "isBasmala": false, "translation_en": "We did not send any prophet to any town but We afflicted its people with misery and adversity, so that they may humble themselves.", "translation_id": "Kami tidaklah mengutus seseorang nabipun kepada sesuatu negeri, (lalu penduduknya mendustakan nabi itu), melainkan Kami timpakan kepada penduduknya kesempitan dan penderitaan supaya mereka tunduk dengan merendahkan diri.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 95, "text": "ثُمَّ بَدَّلۡنَا مَكَانَ ٱلسَّیِّئَةِ ٱلۡحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدۡ مَسَّ ءَابَاۤءَنَا ٱلضَّرَّاۤءُ وَٱلسَّرَّاۤءُ فَأَخَذۡنَـٰهُم بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ ۝٩٥", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "ثم بدَّلنا الحالة الطيبة الأولى مكان الحالة السيئة، فأصبحوا في عافية في أبدانهم، وسَعَة ورخاء في أموالهم؛ إمهالا لهم، ولعلهم يشكرون، فلم يُفِد معهم كل ذلك، ولم يعتبروا ولم ينتهوا عمَّا هم فيه، وقالوا: هذه عادة الدهر في أهله، يوم خير ويوم شر، وهو ما جرى لآبائنا من قبل، فأخذناهم بالعذاب فجأة وهم آمنون، لا يخطر لهم الهلاك على بال.", "isBasmala": false, "translation_en": "Then We substituted prosperity in place of hardship. Until they increased in number, and said, \"Adversity and prosperity has touched our ancestors.\" Then We seized them suddenly, while they were unaware.", "translation_id": "Kemudian Kami ganti kesusahan itu dengan kesenangan hingga keturunan dan harta mereka bertambah banyak, dan mereka berkata: \"Sesungguhnya nenek moyang kamipun telah merasai penderitaan dan kesenangan\", maka Kami timpakan siksaan atas mereka dengan sekonyong-konyong sedang mereka tidak menyadarinya.", "manzil": 2, "manzil_display": ""}], "163": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 96, "text": "وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰۤ ءَامَنُوا۟ وَٱتَّقَوۡا۟ لَفَتَحۡنَا عَلَیۡهِم بَرَكَـٰتࣲ مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ وَلَـٰكِن كَذَّبُوا۟ فَأَخَذۡنَـٰهُم بِمَا كَانُوا۟ یَكۡسِبُونَ ۝٩٦", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "ولو أنَّ أهل القرى صدَّقوا رسلهم واتبعوهم واجتنبوا ما نهاهم الله عنه، لفتح الله لهم أبواب الخير من كلِّ وجه، ولكنهم كذَّبوا، فعاقبهم الله بالعذاب المهلك بسبب كفرهم ومعاصيهم.", "isBasmala": false, "translation_en": "Had the people of the towns believed and turned righteous, We would have opened for them the blessings of the heaven and the earth; but they rejected the truth, so We seized them by what they were doing.", "translation_id": "Jikalau sekiranya penduduk negeri-negeri beriman dan bertakwa, pastilah Kami akan melimpahkan kepada mereka berkah dari langit dan bumi, tetapi mereka mendustakan (ayat-ayat Kami) itu, maka Kami siksa mereka disebabkan perbuatannya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 97, "text": "أَفَأَمِنَ أَهۡلُ ٱلۡقُرَىٰۤ أَن یَأۡتِیَهُم بَأۡسُنَا بَیَـٰتࣰا وَهُمۡ نَاۤىِٕمُونَ ۝٩٧", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "أيظن أهل القرى أنهم في منجاة ومأمن من عذاب الله، أن يأتيهم ليلا وهم نائمون؟", "isBasmala": false, "translation_en": "Do the people of the towns feel secure that Our might will not come upon them by night, while they sleep?", "translation_id": "Maka apakah penduduk negeri-negeri itu merasa aman dari kedatangan siksaan Kami kepada mereka di malam hari di waktu mereka sedang tidur?", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 98, "text": "أَوَ أَمِنَ أَهۡلُ ٱلۡقُرَىٰۤ أَن یَأۡتِیَهُم بَأۡسُنَا ضُحࣰى وَهُمۡ یَلۡعَبُونَ ۝٩٨", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "أوَأمن أهل القرى أن يأتيهم عذاب الله وقت الضحى، وهم غافلون متشاغلون بأمور دنياهم؟ وخصَّ الله هذين الوقتين بالذكر، لأن الإنسان يكون أغْفَل ما يكون فيهما، فمجيء العذاب فيهما أفظع وأشد.", "isBasmala": false, "translation_en": "Do the people of the towns feel secure that Our might will not come upon them by day, while they play?", "translation_id": "Atau apakah penduduk negeri-negeri itu merasa aman dari kedatangan siksaan Kami kepada mereka di waktu matahari sepenggalahan naik ketika mereka sedang bermain?", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 99, "text": "أَفَأَمِنُوا۟ مَكۡرَ ٱللَّهِۚ فَلَا یَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَـٰسِرُونَ ۝٩٩", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "أفأمن أهل القرى المكذبة مَكْرَ الله وإمهاله لهم؛ استدراجًا لهم بما أنعم عليهم في دنياهم عقوبة لمكرهم؟ فلا يأمن مكر الله إلا القوم الهالكون.", "isBasmala": false, "translation_en": "Do they feel safe from God's plan? None feel safe from God's plan except the losing people.", "translation_id": "Maka apakah mereka merasa aman dari azab Allah (yang tidak terduga-duga)? Tiada yang merasa aman dan azab Allah kecuali orang-orang yang merugi.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 100, "text": "أَوَ لَمۡ یَهۡدِ لِلَّذِینَ یَرِثُونَ ٱلۡأَرۡضَ مِنۢ بَعۡدِ أَهۡلِهَاۤ أَن لَّوۡ نَشَاۤءُ أَصَبۡنَـٰهُم بِذُنُوبِهِمۡۚ وَنَطۡبَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَسۡمَعُونَ ۝١٠٠", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "أوَلم يتبين للذين سكنوا الأرض من بعد إهلاك أهلها السابقين بسبب معاصيهم، فساروا سيرتهم، أن لو نشاء أصبناهم بسبب ذنوبهم كما فعلنا بأسلافهم، ونختم على قلوبهم، فلا يدخلها الحق، ولا يسمعون موعظة ولا تذكيرًا؟", "isBasmala": false, "translation_en": "Is it not guidance for those who inherit the land after its inhabitants, that if We willed, We could strike them for their sins? And seal up their hearts, so that they would not hear?", "translation_id": "Dan apakah belum jelas bagi orang-orang yang mempusakai suatu negeri sesudah (lenyap) penduduknya, bahwa kalau Kami menghendaki tentu Kami azab mereka karena dosa-dosanya; dan Kami kunci mati hati mereka sehingga mereka tidak dapat mendengar (pelajaran lagi)?", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 101, "text": "تِلۡكَ ٱلۡقُرَىٰ نَقُصُّ عَلَیۡكَ مِنۡ أَنۢبَاۤىِٕهَاۚ وَلَقَدۡ جَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَمَا كَانُوا۟ لِیُؤۡمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبۡلُۚ كَذَ ٰلِكَ یَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلۡكَـٰفِرِینَ ۝١٠١", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "تلك القرى التي تَقَدَّم ذِكْرُها، وهي قرى قوم نوح وهود وصالح ولوط وشعيب، نقصُّ عليك -أيها الرسول- من أخبارها، وما كان من أَمْر رسل الله التي أرسلت إليهم، ما يحصل به عبرة للمعتبرين وازدجار للظالمين. ولقد جاءت أهلَ القرى رسلنا بالحجج البينات على صدقهم، فما كانوا ليؤمنوا بما جاءتهم به الرسل؛ بسبب طغيانهم وتكذيبهم بالحق، ومثل خَتْمِ الله على قلوب هؤلاء الكافرين المذكورين يختم الله على قلوب الكافرين بمحمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "These towns-We narrate to you some of their tales. Their messengers came to them with the clear signs, but they would not believe in what they had rejected previously. Thus God seals the hearts of the disbelievers.", "translation_id": "Negeri-negeri (yang telah Kami binasakan) itu, Kami ceritakan sebagian dari berita-beritanya kepadamu. Dan sungguh telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti yang nyata, maka mereka (juga) tidak beriman kepada apa yang dahulunya mereka telah mendustakannya. Demikianlah Allah mengunci mata hati orang-orang kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 102, "text": "وَمَا وَجَدۡنَا لِأَكۡثَرِهِم مِّنۡ عَهۡدࣲۖ وَإِن وَجَدۡنَاۤ أَكۡثَرَهُمۡ لَفَـٰسِقِینَ ۝١٠٢", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "وما وَجَدْنا لأكثر الأم الماضية من أمانة ولا وفاء بالعهد، وما وجدنا أكثرهم إلا فسقة عن طاعة الله وامتثال أمره.", "isBasmala": false, "translation_en": "We found most of them untrue to their covenants; We found most of them corrupt.", "translation_id": "Dan Kami tidak mendapati kebanyakan mereka memenuhi janji. Sesungguhnya Kami mendapati kebanyakan mereka orang-orang yang fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 103, "text": "ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ بِـَٔایَـٰتِنَاۤ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ فَظَلَمُوا۟ بِهَاۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُفۡسِدِینَ ۝١٠٣", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "ثم بعثنا من بعد الرسل المتقدم ذِكْرهم موسى بن عمران بمعجزاتنا البينة إلى فرعون وقومه، فجحدوا وكفروا بها ظلمًا منهم وعنادًا، فانظر -أيها الرسول- متبصرًا كيف فعلنا بهم وأغرقناهم عن آخرهم بمرأى من موسى وقومه؟ وتلك نهاية المفسدين.", "isBasmala": false, "translation_en": "Then, after them, We sent Moses with Our miracles to Pharaoh and his establishment, but they denounced them. So consider the end of the evildoers.", "translation_id": "Kemudian Kami utus Musa sesudah rasul-rasul itu dengan membawa ayat-ayat Kami kepada Fir'aun dan pemuka-pemuka kaumnya, lalu mereka mengingkari ayat-ayat itu. Maka perhatikanlah bagaimana akibat orang-orang yang membuat kerusakan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 104, "text": "وَقَالَ مُوسَىٰ یَـٰفِرۡعَوۡنُ إِنِّی رَسُولࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ ۝١٠٤", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "وقال موسى لفرعون محاورًا مبلِّغًا: إني رسولٌ من الله خالق الخلق أجمعين، ومدبِّر أحوالهم ومآلهم.", "isBasmala": false, "translation_en": "Moses said, \"O Pharaoh, I am a messenger from the Lord of the Worlds.\"", "translation_id": "Dan Musa berkata: \"Hai Fir'aun, sesungguhnya aku ini adalah seorang utusan dari Tuhan semesta alam,", "manzil": 2, "manzil_display": ""}], "164": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 105, "text": "حَقِیقٌ عَلَىٰۤ أَن لَّاۤ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ قَدۡ جِئۡتُكُم بِبَیِّنَةࣲ مِّن رَّبِّكُمۡ فَأَرۡسِلۡ مَعِیَ بَنِیۤ إِسۡرَ ٰۤءِیلَ ۝١٠٥", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "جدير بأن لا أقول على الله إلا الحق، وحريٌّ بي أن ألتزمه، قد جئتكم ببرهان وحجة باهرة من ربكم على صِدْق ما أذكره لكم، فأطلق -يا فرعون- معي بني إسرائيل مِن أَسْرك وقَهْرك، وخلِّ سبيلهم لعبادة الله.", "isBasmala": false, "translation_en": "\"It is only proper that I should not say about God anything other than the truth. I have come to you with clear evidence from your Lord, so let the Children of Israel go with me.\"", "translation_id": "wajib atasku tidak mengatakan sesuatu terhadap Allah, kecuali yang hak. Sesungguhnya aku datang kepadamu dengan membawa bukti yang nyata dari Tuhanmu, maka lepaskanlah Bani Israil (pergi) bersama aku\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 106, "text": "قَالَ إِن كُنتَ جِئۡتَ بِـَٔایَةࣲ فَأۡتِ بِهَاۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ ۝١٠٦", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "قال فرعرن لموسى: إن كنتَ جئتَ بآية حسب زعمك فأتني بها، وأحضرها عندي؛ لتصحَّ دعواك ويثبت صدقك، إن كنت صادقًا فيما ادَّعيت أنك رسول رب العالمين.", "isBasmala": false, "translation_en": "He said, \"If you brought a miracle, then present it, if you are truthful.\"", "translation_id": "Fir'aun menjawab: \"Jika benar kamu membawa sesuatu bukti, maka datangkanlah bukti itu jika (betul) kamu termasuk orang-orang yang benar\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 107, "text": "فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِیَ ثُعۡبَانࣱ مُّبِینࣱ ۝١٠٧", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "فألقى موسى عصاه، فتحولت حيَّة عظيمة ظاهرة للعيان.", "isBasmala": false, "translation_en": "So he threw his staff, and it was an apparent serpent.", "translation_id": "Maka Musa menjatuhkan tongkat-nya, lalu seketika itu juga tongkat itu menjadi ular yang sebenarnya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 108, "text": "وَنَزَعَ یَدَهُۥ فَإِذَا هِیَ بَیۡضَاۤءُ لِلنَّـٰظِرِینَ ۝١٠٨", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "وجذب يده من جيبه أو من جناحه فإذا هي بيضاء كاللبن من غير برص آية لفرعون، فإذا ردَّها عادت إلى لونها الأول، كسائر بدنه.", "isBasmala": false, "translation_en": "And He pulled out his hand, and it was white to the onlookers.", "translation_id": "Dan ia mengeluarkan tangannya, maka ketika itu juga tangan itu menjadi putih bercahaya (kelihatan) oleh orang-orang yang melihatnya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 109, "text": "قَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ إِنَّ هَـٰذَا لَسَـٰحِرٌ عَلِیمࣱ ۝١٠٩", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "قال الأشراف من قوم فرعون: إن موسى لساحر يأخذ بأعين الناس بخداعه إياهم، حتى يخيل إليهم أن العصا حية، والشيء بخلاف ما هو عليه، وهو واسع العلم بالسحر ماهر به.", "isBasmala": false, "translation_en": "The notables among Pharaoh's people said, \"This is really a skilled magician.\"", "translation_id": "Pemuka-pemuka kaum Fir'aun berkata: \"Sesungguhnya Musa ini adalah ahli sihir yang pandai,", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 110, "text": "یُرِیدُ أَن یُخۡرِجَكُم مِّنۡ أَرۡضِكُمۡۖ فَمَاذَا تَأۡمُرُونَ ۝١١٠", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "يريد أن يخرجكم جميعًا من أرضكم، قال فرعون: فبماذا تشيرون عليَّ أيها الملأ في أمر موسى؟", "isBasmala": false, "translation_en": "\"He wants to evict you from your land, so what do you recommend?\"", "translation_id": "yang bermaksud hendak mengeluarkan kamu dari negerimu\". (Fir'aun berkata): \"Maka apakah yang kamu anjurkan?\"", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 111, "text": "قَالُوۤا۟ أَرۡجِهۡ وَأَخَاهُ وَأَرۡسِلۡ فِی ٱلۡمَدَاۤىِٕنِ حَـٰشِرِینَ ۝١١١", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "قال مَن حضر مناظرة موسى مِن سادة قوم فرعون وكبرائهم: أَخِّر موسى وأخاه هارون، وابعث في مدائن \"مصر\" وأقاليمها الشُّرَط.", "isBasmala": false, "translation_en": "They said, \"Put him off, and his brother, and send heralds to the cities.\"", "translation_id": "Pemuka-pemuka itu menjawab: \"Beri tangguhlah dia dan saudaranya serta kirimlah ke kota-kota beberapa orang yang akan mengumpulkan (ahli-ahli sihir),", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 112, "text": "یَأۡتُوكَ بِكُلِّ سَـٰحِرٍ عَلِیمࣲ ۝١١٢", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "ليجمعوا لك كل ساحر واسع العلم بالسحر.", "isBasmala": false, "translation_en": "\"And let them bring you every skillful magician.\"", "translation_id": "supaya mereka membawa kepadamu semua ahli sihir yang pandai\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 113, "text": "وَجَاۤءَ ٱلسَّحَرَةُ فِرۡعَوۡنَ قَالُوۤا۟ إِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَـٰلِبِینَ ۝١١٣", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "وجاء السحرة فرعون قالوا: أئنَّ لنا لجائزة ومالا إن غَلَبْنا موسى؟", "isBasmala": false, "translation_en": "The magicians came to Pharaoh, and said, \"Surely there is a reward for us, if we are the victors.\"", "translation_id": "Dan beberapa ahli sihir itu datang kepada Fir'aun mengatakan: \"(Apakah) sesungguhnya kami akan mendapat upah, jika kamilah yang menang?\"", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 114, "text": "قَالَ نَعَمۡ وَإِنَّكُمۡ لَمِنَ ٱلۡمُقَرَّبِینَ ۝١١٤", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "قال فرعون: نعم لكم الأجر والقرب مني إن غَلَبْتُموه.", "isBasmala": false, "translation_en": "He said, \"Yes, and you will be among my favorites.\"", "translation_id": "Fir'aun menjawab: \"Ya, dan sesungguhnya kamu benar-benar akan termasuk orang-orang yang dekat (kepadaku)\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 115, "text": "قَالُوا۟ یَـٰمُوسَىٰۤ إِمَّاۤ أَن تُلۡقِیَ وَإِمَّاۤ أَن نَّكُونَ نَحۡنُ ٱلۡمُلۡقِینَ ۝١١٥", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "قال سحرة فرعون لموسى على سبيل التكبر وعدم المبالاة: يا موسى اختر أن تُلقي عصاك أولا أو نُلقي نحن أولا.", "isBasmala": false, "translation_en": "They said, \"O Moses! Either you throw, or we are the ones to throw.\"", "translation_id": "Ahli-ahli sihir berkata: \"Hai Musa, kamukah yang akan melemparkan lebih dahulu, ataukah kami yang akan melemparkan?\"", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 116, "text": "قَالَ أَلۡقُوا۟ۖ فَلَمَّاۤ أَلۡقَوۡا۟ سَحَرُوۤا۟ أَعۡیُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ وَجَاۤءُو بِسِحۡرٍ عَظِیمࣲ ۝١١٦", "juz": 9, "hizb": "(* ح 17*)", "tafsir": "قال موسى للسحرة: ألقوا أنتم، فلما ألقَوا الحبال والعصيَّ سحروا أعين الناس، فخُيِّل إلى الأبصار أن ما فعلوه حقيقة، ولم يكن إلا مجرد صنعة وخيال، وأرهبوا الناس إرهابًا شديدًا، وجاؤوا بسحر قوي كثير.", "isBasmala": false, "translation_en": "He said, \"You throw!\" And when they threw, they beguiled the eyes of the people, and intimidated them, and produced a mighty magic.", "translation_id": "Musa menjawab: \"Lemparkanlah (lebih dahulu)!\" Maka tatkala mereka melemparkan, mereka menyulap mata orang dan menjadikan orang banyak itu takut, serta mereka mendatangkan sihir yang besar (mena'jubkan).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 117, "text": "۞ وَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ أَنۡ أَلۡقِ عَصَاكَۖ فَإِذَا هِیَ تَلۡقَفُ مَا یَأۡفِكُونَ ۝١١٧", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "وأوحى الله إلى عبده ورسوله موسى عليه السلام في ذلك الموقف العظيم الذي فرَّق الله فيه بين الحق والباطل، يأمره بأن يُلقي ما في يمينه وهي عصاه، فألقاها فإذا هي تبلع ما يلقونه، ويوهمون الناس أنه حق وهو باطل.", "isBasmala": false, "translation_en": "And We inspired Moses: \"Throw your staff.\" And at once, it swallowed what they were faking.", "translation_id": "Dan Kami wahyukan kepada Musa: \"Lemparkanlah tongkatmu!\". Maka sekonyong-konyong tongkat itu menelan apa yang mereka sulapkan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 118, "text": "فَوَقَعَ ٱلۡحَقُّ وَبَطَلَ مَا كَانُوا۟ یَعۡمَلُونَ ۝١١٨", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "فظهر الحق واستبان لمن شهده وحضره في أمر موسى عليه السلام، وأنه رسول الله يدعو إلى الحق، وبطل الكذب الذي كانوا يعملونه.", "isBasmala": false, "translation_en": "So the truth came to pass, and what they were producing came to nothing.", "translation_id": "Karena itu nyatalah yang benar dan batallah yang selalu mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 119, "text": "فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَـٰغِرِینَ ۝١١٩", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "فغُلِبَ جميع السحرة في مكان اجتماعهم، وانصرف فرعون وقومه أذلاء مقهورين مغلوبين.", "isBasmala": false, "translation_en": "There they were defeated, and utterly reduced.", "translation_id": "Maka mereka kalah di tempat itu dan jadilah mereka orang-orang yang hina.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 120, "text": "وَأُلۡقِیَ ٱلسَّحَرَةُ سَـٰجِدِینَ ۝١٢٠", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "وخَرَّ السحرة سُجَّدًا على وجوههم لله رب العالمين لِمَا عاينوا من عظيم قدرة الله.", "isBasmala": false, "translation_en": "And the magicians fell to their knees.", "translation_id": "Dan ahli-ahli sihir itu serta merta meniarapkan diri dengan bersujud.", "manzil": 2, "manzil_display": ""}], "165": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 121, "text": "قَالُوۤا۟ ءَامَنَّا بِرَبِّ ٱلۡعَـٰلَمِینَ ۝١٢١", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "قالوا: آمنا برب العالمين.", "isBasmala": false, "translation_en": "They said, \"We have believed in the Lord of the Worlds.\"", "translation_id": "Mereka berkata: \"Kami beriman kepada Tuhan semesta alam,", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 122, "text": "رَبِّ مُوسَىٰ وَهَـٰرُونَ ۝١٢٢", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "وهو رب موسى وهارون، وهو الذي يجب أن تصرف له العبادة وحده دون مَن سواه.", "isBasmala": false, "translation_en": "\"The Lord of Moses and Aaron.\"", "translation_id": "\"(yaitu) Tuhan Musa dan Harun\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 123, "text": "قَالَ فِرۡعَوۡنُ ءَامَنتُم بِهِۦ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّ هَـٰذَا لَمَكۡرࣱ مَّكَرۡتُمُوهُ فِی ٱلۡمَدِینَةِ لِتُخۡرِجُوا۟ مِنۡهَاۤ أَهۡلَهَاۖ فَسَوۡفَ تَعۡلَمُونَ ۝١٢٣", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "قال فرعون للسحرة: آمنتم بالله قبل أن آذن لكم بالإيمان به؟ إن إيمانكم بالله وتصديقكم لموسى وإقراركم بنبوته لحيلة احتلتموها أنتم وموسى؛ لتخرجوا أهل مدينتكم منها، وتكونوا المستأثرين بخيراتها، فسوف تعلمون -أيها السحرة- ما يحلُّ بكم من العذاب والنكال.", "isBasmala": false, "translation_en": "Pharaoh said, \"Did you believe in Him before I have given you permission? This is surely a conspiracy you schemed in the city, in order to expel its people from it. You will surely know.\"", "translation_id": "Fir'aun berkata: \"Apakah kamu beriman kepadanya sebelum aku memberi izin kepadamu?, sesungguhnya (perbuatan ini) adalah suatu muslihat yang telah kamu rencanakan di dalam kota ini, untuk mengeluarkan penduduknya dari padanya; maka kelak kamu akan mengetahui (akibat perbuatanmu ini);", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 124, "text": "لَأُقَطِّعَنَّ أَیۡدِیَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَـٰفࣲ ثُمَّ لَأُصَلِّبَنَّكُمۡ أَجۡمَعِینَ ۝١٢٤", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "لأقطعنَّ أيديكم وأرجلكم -أيها السحرة- من خلاف: بقطع اليد اليمنى والرجل اليسرى، أو اليد اليسرى والرجل اليمنى، ثم لأعلقنَّكم جميعًا على جذوع النخل؛ تنكيلا بكم وإرهابًا للناس.", "isBasmala": false, "translation_en": "\"I will cut off your hands and your feet on opposite sides; then I will crucify you all.\"", "translation_id": "demi, sesungguhnya aku akan memotong tangan dan kakimu dengan bersilang secara bertimbal balik, kemudian sungguh-sungguh aku akan menyalib kamu semuanya\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 125, "text": "قَالُوۤا۟ إِنَّاۤ إِلَىٰ رَبِّنَا مُنقَلِبُونَ ۝١٢٥", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "قال السحرة لفرعون: قد تحققنا أنَّا إلى الله راجعون، وأن عذابه أشد من عذابك، فلنصبرنَّ اليوم على عذابك؛ لِننجو من عذاب الله يوم القيامة.", "isBasmala": false, "translation_en": "They said, \"It is to our Lord that we will return.\"", "translation_id": "Ahli-ahli sihir itu menjawab: \"Sesungguhnya kepada Tuhanlah kami kembali.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 126, "text": "وَمَا تَنقِمُ مِنَّاۤ إِلَّاۤ أَنۡ ءَامَنَّا بِـَٔایَـٰتِ رَبِّنَا لَمَّا جَاۤءَتۡنَاۚ رَبَّنَاۤ أَفۡرِغۡ عَلَیۡنَا صَبۡرࣰا وَتَوَفَّنَا مُسۡلِمِینَ ۝١٢٦", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "ولستَ تعيب منا وتنكر -يا فرعون- إلا إيماننا وتصديقنا بحجج ربنا وأدلته التي جاء بها موسى ولا تقدر على مثلها أنت ولا أحد آخر سوى الله الذي له ملك السموات والأرض، ربنا أَفِضْ علينا صبرًا عظيمًا وثباتا عليه، وتوفَّنا منقادين لأمرك متبعين رسولك.", "isBasmala": false, "translation_en": "\"You are taking vengeance on us only because we have believed in the signs of our Lord when they have come to us.\" \"Our Lord! Pour out patience upon us, and receive our souls in submission.\"", "translation_id": "Dan kamu tidak menyalahkan kami, melainkan karena kami telah beriman kepada ayat-ayat Tuhan kami ketika ayat-ayat itu datang kepada kami\". (Mereka berdoa): \"Ya Tuhan kami, limpahkanlah kesabaran kepada kami dan wafatkanlah kami dalam keadaan berserah diri (kepada-Mu)\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 127, "text": "وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ أَتَذَرُ مُوسَىٰ وَقَوۡمَهُۥ لِیُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ وَیَذَرَكَ وَءَالِهَتَكَۚ قَالَ سَنُقَتِّلُ أَبۡنَاۤءَهُمۡ وَنَسۡتَحۡیِۦ نِسَاۤءَهُمۡ وَإِنَّا فَوۡقَهُمۡ قَـٰهِرُونَ ۝١٢٧", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "وقال السادة والكبراء من قوم فرعون لفرعون: أَتَدَعُ موسى وقومه من بني إسرائيل ليفسدوا الناس في أرض \"مصر\" بتغيير دينهم بعبادة الله وحده لا شريك له، وترك عبادتك وعبادة آلهتك؟ قال فرعون: سنُقَتِّل أبناء بني إسرائيل ونستبقي نساءهم أحياء للخدمة، وإنَّا عالون عليهم بقهر المُلْكِ والسلطان.", "isBasmala": false, "translation_en": "The chiefs of Pharaoh's people said, \"Will you let Moses and his people cause trouble in the land, and forsake you and your gods?\" He said, \"We will kill their sons, and spare their women. We have absolute power over them.\"", "translation_id": "Berkatalah pembesar-pembesar dari kaum Fir'aun (kepada Fir'aun): \"Apakah kamu membiarkan Musa dan kaumnya untuk membuat kerusakan di negeri ini (Mesir) dan meninggalkan kamu serta tuhan-tuhanmu?\". Fir'aun menjawab: \"Akan kita bunuh anak-anak lelaki mereka dan kita biarkan hidup perempuan-perempuan mereka; dan sesungguhnya kita berkuasa penuh di atas mereka\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 128, "text": "قَالَ مُوسَىٰ لِقَوۡمِهِ ٱسۡتَعِینُوا۟ بِٱللَّهِ وَٱصۡبِرُوۤا۟ۖ إِنَّ ٱلۡأَرۡضَ لِلَّهِ یُورِثُهَا مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۖ وَٱلۡعَـٰقِبَةُ لِلۡمُتَّقِینَ ۝١٢٨", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "قال موسى لقومه -من بني إسرائيل-: استعينوا بالله على فرعون وقومه، واصبروا على ما نالكم من فرعون من المكاره في أنفسكم وأبنائكم. إن الأرض كلها لله يورثها من يشاء من عباده، والعاقبة المحمودة لمن اتقى الله ففعل أوامره واجتنب نواهيه.", "isBasmala": false, "translation_en": "Moses said to his people, \"Seek help in God, and be patient. The earth belongs to God. He gives it in inheritance to whomever He wills of His servants, and the future belongs to the righteous.\"", "translation_id": "Musa berkata kepada kaumnya: \"Mohonlah pertolongan kepada Allah dan bersabarlah; sesungguhnya bumi (ini) kepunyaan Allah; dipusakakan-Nya kepada siapa yang dihendaki-Nya dari hamba-hamba-Nya. Dan kesudahan yang baik adalah bagi orang-orang yang bertakwa\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 129, "text": "قَالُوۤا۟ أُوذِینَا مِن قَبۡلِ أَن تَأۡتِیَنَا وَمِنۢ بَعۡدِ مَا جِئۡتَنَاۚ قَالَ عَسَىٰ رَبُّكُمۡ أَن یُهۡلِكَ عَدُوَّكُمۡ وَیَسۡتَخۡلِفَكُمۡ فِی ٱلۡأَرۡضِ فَیَنظُرَ كَیۡفَ تَعۡمَلُونَ ۝١٢٩", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "قال قوم موسى -من بني إسرائيل- لنبيهم موسى: ابتُلينا وأُوذينا بذبح أبنائنا واستحياء نسائنا على يد فرعون وقومه، من قبل أن تأتينا، ومن بعد ما جئتنا، قال موسى لهم: لعل ربكم أن يهلك عدوكم فرعون وقومه، ويستخلفكم في أرضهم بعد هلاكهم، فينظر كيف تعملون، هل تشكرون أو تكفرون؟", "isBasmala": false, "translation_en": "They said, \"We were persecuted before you came to us, and after you came to us.\" He said, \"Perhaps your Lord will destroy your enemy, and make you successors in the land; then He will see how you behave.\"", "translation_id": "Kaum Musa berkata: \"Kami telah ditindas (oleh Fir'aun) sebelum kamu datang kepada kami dan sesudah kamu datang. Musa menjawab: \"Mudah-mudahan Allah membinasakan musuhmu dan menjadikan kamu khalifah di bumi(Nya), maka Allah akan melihat bagaimana perbuatanmu.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 130, "text": "وَلَقَدۡ أَخَذۡنَاۤ ءَالَ فِرۡعَوۡنَ بِٱلسِّنِینَ وَنَقۡصࣲ مِّنَ ٱلثَّمَرَ ٰتِ لَعَلَّهُمۡ یَذَّكَّرُونَ ۝١٣٠", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "ولقد ابتلينا فرعون وقومه بالقحط والجدب، ونَقْص ثمارهم وغَلاتهم؛ ليتذكروا، وينزجروا عن ضلالاتهم، ويفزعوا إلى ربهم بالتوبة.", "isBasmala": false, "translation_en": "And We afflicted the people of Pharaoh with barren years, and with shortage of crops, that they may take heed.", "translation_id": "Dan sesungguhnya Kami telah menghukum (Fir'aun dan) kaumnya dengan (mendatangkan) musim kemarau yang panjang dan kekurangan buah-buahan, supaya mereka mengambil pelajaran.", "manzil": 2, "manzil_display": ""}], "166": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 131, "text": "فَإِذَا جَاۤءَتۡهُمُ ٱلۡحَسَنَةُ قَالُوا۟ لَنَا هَـٰذِهِۦۖ وَإِن تُصِبۡهُمۡ سَیِّئَةࣱ یَطَّیَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥۤۗ أَلَاۤ إِنَّمَا طَـٰۤىِٕرُهُمۡ عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ ۝١٣١", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "فإذا جاء فرعونَ وقومَه الخِصْبُ والرزقُ قالوا: هذا لنا بما نستحقه، وإن يُصِبْهم جدب وقحط يتشاءموا، ويقولوا: هذا بسبب موسى ومَن معه. ألا إنَّ ما يصيبهم من الجدب والقحط إنما هو بقضاء الله وقدره، وبسبب ذنوبهم وكفرهم، ولكن أكثر قوم فرعون لا يعلمون ذلك؛ لانغمارهم في الجهل والضلال.", "isBasmala": false, "translation_en": "When something good came their way, they said, \"This is ours.\" And when something bad happened to them, they ascribed the evil omen to Moses and those with him. In fact, their omen is with God, but most of them do not know.", "translation_id": "Kemudian apabila datang kepada mereka kemakmuran, mereka berkata: \"Itu adalah karena (usaha) kami\". Dan jika mereka ditimpa kesusahan, mereka lemparkan sebab kesialan itu kepada Musa dan orang-orang yang besertanya. Ketahuilah, sesungguhnya kesialan mereka itu adalah ketetapan dari Allah, akan tetapi kebanyakan mereka tidak mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 132, "text": "وَقَالُوا۟ مَهۡمَا تَأۡتِنَا بِهِۦ مِنۡ ءَایَةࣲ لِّتَسۡحَرَنَا بِهَا فَمَا نَحۡنُ لَكَ بِمُؤۡمِنِینَ ۝١٣٢", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "وقال قوم فرعون لموسى: أي آية تأتِنا بها، ودلالة وحجة أقمتها لتصرفنا عما نحن عليه من دين فرعون، فما نحن لك بمصدِّقين.", "isBasmala": false, "translation_en": "And they said, \"No matter what sign you bring us, to bewitch us with, we will not believe in you.\"", "translation_id": "Mereka berkata: \"Bagaimanapun kamu mendatangkan keterangan kepada kami untuk menyihir kami dengan keterangan itu, maka kami sekali-kali tidak akan beriman kepadamu\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 133, "text": "فَأَرۡسَلۡنَا عَلَیۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَایَـٰتࣲ مُّفَصَّلَـٰتࣲ فَٱسۡتَكۡبَرُوا۟ وَكَانُوا۟ قَوۡمࣰا مُّجۡرِمِینَ ۝١٣٣", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "فأرسلنا عليهم سيلا جارفًا أغرق الزروع والثمار، وأرسلنا الجراد، فأكل زروعهم وثمارهم وأبوابهم وسقوفهم وثيابهم، وأرسلنا القُمَّل الذي يفسد الثمار ويقضي على الحيوان والنبات، وأرسلنا الضفادع فملأت آنيتهم وأطعمتهم ومضاجعهم، وأرسلنا أيضًا الدم فصارت أنهارهم وآبارهم دمًا، ولم يجدوا ماء صالحًا للشرب، هذه آيات من آيات الله لا يقدر عليها غيره، مفرقات بعضها عن بعض، ومع كل هذا ترفَّع قوم فرعون، فاستكبروا عن الإيمان بالله، وكانوا قومًا يعملون بما ينهى الله عنه من المعاصي والفسق عتوًّا وتمردًا.", "isBasmala": false, "translation_en": "So We let loose upon them the flood, and the locusts, and the lice, and the frogs, and blood-all explicit signs-but they were too arrogant. They were a sinful people.", "translation_id": "Maka Kami kirimkan kepada mereka taufan, belalang, kutu, katak dan darah sebagai bukti yang jelas, tetapi mereka tetap menyombongkan diri dan mereka adalah kaum yang berdosa.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 134, "text": "وَلَمَّا وَقَعَ عَلَیۡهِمُ ٱلرِّجۡزُ قَالُوا۟ یَـٰمُوسَى ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَۖ لَىِٕن كَشَفۡتَ عَنَّا ٱلرِّجۡزَ لَنُؤۡمِنَنَّ لَكَ وَلَنُرۡسِلَنَّ مَعَكَ بَنِیۤ إِسۡرَ ٰۤءِیلَ ۝١٣٤", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "ولما نزل العذاب على فرعون وقومه فزعوا إلى موسى وقالوا: يا موسى ادع لنا ربك بما أوحى به إليك مِن رَفْع العذاب بالتوبة، لئن رفعت عنا العذاب الذي نحن فيه لنصدِّقنَّ بما جئت به، ونتبع ما دعوت إليه، ولنطلقنَّ معك بني إسرائيل، فلا نمنعهم من أن يذهبوا حيث شاؤوا.", "isBasmala": false, "translation_en": "Whenever a plague befell them, they would say, \"O Moses, pray to your Lord for us, according to the covenant He made with you. If you lift the plague from us, we will believe in you, and let the Children of Israel go with you.\"", "translation_id": "Dan ketika mereka ditimpa azab (yang telah diterangkan itu) merekapun berkata: \"Hai Musa, mohonkanlah untuk kami kepada Tuhamnu dengan (perantaraan) kenabian yang diketahui Allah ada pada sisimu. Sesungguhnya jika kamu dapat menghilangkan azab itu dan pada kami, pasti kami akan beriman kepadamu dan akan kami biarkan Bani Israil pergi bersamamu\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 135, "text": "فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلرِّجۡزَ إِلَىٰۤ أَجَلٍ هُم بَـٰلِغُوهُ إِذَا هُمۡ یَنكُثُونَ ۝١٣٥", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "فلما رفع الله عنهم العذاب الذى أنزله بهم إلى أجلٍ هم بالغوه لا محالة فيعذبون فيه، لا ينفعهم ما تقدَّم لهم من الإمهال وكَشْفِ العذاب إلى حلوله، إذا هم ينقضون عهودهم التي عاهدوا عليها ربهم وموسى، ويقيمون على كفرهم وضلالهم.", "isBasmala": false, "translation_en": "But when We lifted the plague from them, for a term they were to fulfill, they broke their promise.", "translation_id": "Maka setelah Kami hilangkan azab itu dari mereka hingga batas waktu yang mereka sampai kepadanya, tiba-tiba mereka mengingkarinya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 136, "text": "فَٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَـٰهُمۡ فِی ٱلۡیَمِّ بِأَنَّهُمۡ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَكَانُوا۟ عَنۡهَا غَـٰفِلِینَ ۝١٣٦", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "فانتقمنا منهم حين جاء الأجل المحدد لإهلاكهم، وذلك بإحلال نقمتنا عليهم، وهي إغراقهم في البحر؛ بسبب تكذيبهم بالمعجزات التي ظهرت على يد موسى، وكانوا عن هذه المعجزات غافلين، وتلك الغفلة هي سبب التكذيب.", "isBasmala": false, "translation_en": "So We took vengeance on them, and drowned them in the sea-because they rejected Our signs, and paid no heed to them.", "translation_id": "Kemudian Kami menghukum mereka, maka Kami tenggelamkan mereka di laut disebabkan mereka mendustakan ayat-ayat Kami dan mereka adalah orang-orang yang melalaikan ayat-ayat Kami itu.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 137, "text": "وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِینَ كَانُوا۟ یُسۡتَضۡعَفُونَ مَشَـٰرِقَ ٱلۡأَرۡضِ وَمَغَـٰرِبَهَا ٱلَّتِی بَـٰرَكۡنَا فِیهَاۖ وَتَمَّتۡ كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ عَلَىٰ بَنِیۤ إِسۡرَ ٰۤءِیلَ بِمَا صَبَرُوا۟ۖ وَدَمَّرۡنَا مَا كَانَ یَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُۥ وَمَا كَانُوا۟ یَعۡرِشُونَ ۝١٣٧", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "وأررثنا بني إسرائيل الذين كانوا يُستَذَلُّون للخدمة، مشارق الأرض ومغاربها (وهي بلاد \"الشام\") التي باركنا فيها، بإخراج الزروع والثمار والأنهار، وتمت كلمة ربك -أيها الرسول- الحسنى على بني إسرائيل بالتمكين لهم في الأرض؛ بسبب صبرهم على أذى فرعون وقومه، ودمَّرنا ما كان يصنع فرعون وقومه من العمارات والمزارع، وما كانوا يبنون من الأبنية والقصور وغير ذلك.", "isBasmala": false, "translation_en": "And We made the oppressed people inherit the eastern and western parts of the land, which We had blessed. Thus the fair promise of your Lord to the Children of Israel was fulfilled, because of their endurance. And We destroyed what Pharaoh and his people had built, and what they had harvested.", "translation_id": "Dan Kami pusakakan kepada kaum yang telah ditindas itu, negeri-negeri bahagian timur bumi dan bahagian baratnya yang telah Kami beri berkah padanya. Dan telah sempurnalah perkataan Tuhanmu yang baik (sebagai janji) untuk Bani Israil disebabkan kesabaran mereka. Dan Kami hancurkan apa yang telah dibuat Fir'aun dan kaumnya dan apa yang telah dibangun mereka.", "manzil": 2, "manzil_display": ""}], "167": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 138, "text": "وَجَـٰوَزۡنَا بِبَنِیۤ إِسۡرَ ٰۤءِیلَ ٱلۡبَحۡرَ فَأَتَوۡا۟ عَلَىٰ قَوۡمࣲ یَعۡكُفُونَ عَلَىٰۤ أَصۡنَامࣲ لَّهُمۡۚ قَالُوا۟ یَـٰمُوسَى ٱجۡعَل لَّنَاۤ إِلَـٰهࣰا كَمَا لَهُمۡ ءَالِهَةࣱۚ قَالَ إِنَّكُمۡ قَوۡمࣱ تَجۡهَلُونَ ۝١٣٨", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "وقطعنا ببني إسرائيل البحر، فمرُّوا على قوم يقيمون ويواظبون على عبادة أصنام لهم، قال بنو إسرائيل: اجعل لنا يا موسى صنمًا نعبده ونتخذه إلهًا، كما لهؤلاء القوم أصنام يعبدونها، قال موسى لهم: إنكم أيها القوم تجهلون عظمة الله، ولا تعلمون أن العبادة لا تنبغي إلا لله الواحد القهار.", "isBasmala": false, "translation_en": "And We delivered the Children of Israel across the sea. And when they came upon a people who were devoted to some statues of theirs, they said, \"O Moses, make for us a god, as they have gods.\" He said, \"You are truly an ignorant people.\"", "translation_id": "Dan Kami seberangkan Bani Israil ke seberang lautan itu, maka setelah mereka sampai kepada suatu kaum yang tetap menyembah berhala mereka, Bani lsrail berkata: \"Hai Musa. buatlah untuk kami sebuah tuhan (berhala) sebagaimana mereka mempunyai beberapa tuhan (berhala)\". Musa menjawab: \"Sesungguh-nya kamu ini adalah kaum yang tidak mengetahui (sifat-sifat Tuhan)\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 139, "text": "إِنَّ هَـٰۤؤُلَاۤءِ مُتَبَّرࣱ مَّا هُمۡ فِیهِ وَبَـٰطِلࣱ مَّا كَانُوا۟ یَعۡمَلُونَ ۝١٣٩", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "إن هؤلاء المقيمين على هذه الأصنام مُهْلَك ما هم فيه من الشرك، ومدمَّر وباطل ما كانوا يعملون من عبادتهم لتلك الأصنام، التي لا تدفع عنهم عذاب الله إذا نزل بهم.", "isBasmala": false, "translation_en": "\"What these people are concerned with is perdition, and their deeds are based on falsehoods.\"", "translation_id": "Sesungguhnya mereka itu akan dihancurkan kepercayaan yang dianutnya dan akan batal apa yang seIalu mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 140, "text": "قَالَ أَغَیۡرَ ٱللَّهِ أَبۡغِیكُمۡ إِلَـٰهࣰا وَهُوَ فَضَّلَكُمۡ عَلَى ٱلۡعَـٰلَمِینَ ۝١٤٠", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "قال موسى لقومه: أغير الله أطلب لكم معبودًا تعبدونه من دونه، والله هو الذي خلقكم، وفضَّلكم على عالمي زمانكم بكثرة الأنبياء فيكم، وإهلاك عدوكم وما خصَّكم به من الآيات؟", "isBasmala": false, "translation_en": "He said, \"Shall I seek for you a god other than God, when He has favored you over all other people?\"", "translation_id": "Musa menjawab: \"Patutkah aku mencari Tuhan untuk kamu yang selain dari pada Allah, padahal Dialah yang telah melebihkan kamu atas segala umat.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 141, "text": "وَإِذۡ أَنجَیۡنَـٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ یَسُومُونَكُمۡ سُوۤءَ ٱلۡعَذَابِ یُقَتِّلُونَ أَبۡنَاۤءَكُمۡ وَیَسۡتَحۡیُونَ نِسَاۤءَكُمۡۚ وَفِی ذَ ٰلِكُم بَلَاۤءࣱ مِّن رَّبِّكُمۡ عَظِیمࣱ ۝١٤١", "juz": 9, "hizb": "(*¼ ح 17*)", "tafsir": "واذكروا - يا بني إسرائيل - نِعَمنا عليكم إذ أنقذناكم من أَسْر فرعون وآله، وما كنتم فيه من الهوان والذلة من تذبيح أبنائكم واستبقاء نسائكم للخدمة، وفي حَمْلِكم على أقبح العذاب وأسوئه، ثم إنجائكم، اختبار من الله لكم ونعمة عظيمة.", "isBasmala": false, "translation_en": "Remember how We saved you from Pharaoh's people, who subjected you to the worst of sufferings-killing your sons and sparing your women. In that was a tremendous trial from your Lord.", "translation_id": "Dan (ingatlah hai Bani Israil), ketika Kami menyelamatkan kamu dari (Fir'aun) dan kaumnya, yang mengazab kamu dengan azab yang sangat jahat, yaitu mereka membunuh anak-anak lelakimu dan membiarkan hidup wanita-wanitamu. Dan pada yang demikian itu cobaan yang besar dari Tuhanmu\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 142, "text": "۞ وَوَ ٰعَدۡنَا مُوسَىٰ ثَلَـٰثِینَ لَیۡلَةࣰ وَأَتۡمَمۡنَـٰهَا بِعَشۡرࣲ فَتَمَّ مِیقَـٰتُ رَبِّهِۦۤ أَرۡبَعِینَ لَیۡلَةࣰۚ وَقَالَ مُوسَىٰ لِأَخِیهِ هَـٰرُونَ ٱخۡلُفۡنِی فِی قَوۡمِی وَأَصۡلِحۡ وَلَا تَتَّبِعۡ سَبِیلَ ٱلۡمُفۡسِدِینَ ۝١٤٢", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "وواعد الله سبحانه وتعالى موسى لمناجاة ربه ثلاثين ليلة، ثم زاده في الأجل بعد ذلك عشر ليال، فتمَّ ما وَقَّتَه الله لموسى لتكليمه أربعين ليلة. وقال موسى لأخيه هارون -حين أراد المضيَّ لمناجاة ربه-: كن خليفتي في قومي حتى أرجع، وأحمِلَهم على طاعة الله وعبادته، ولا تسلكْ طريق الذين يفسدون في الأرض.", "isBasmala": false, "translation_en": "And We appointed to Moses thirty nights, and completed them with ten; and thus the time appointed by his Lord was forty nights. And Moses said to his brother Aaron: \"Take my place among my people, and be upright, and do not follow the way of the mischief-makers.\"", "translation_id": "Dan telah Kami janjikan kepada Musa (memberikan Taurat) sesudah berlalu waktu tiga puluh malam, dan Kami sempurnakan jumlah malam itu dengan sepuluh (malam lagi), maka sempurnalah waktu yang telah ditentukan Tuhannya empat puluh malam. Dan berkata Musa kepada saudaranya yaitu Harun: \"Gantikanlah aku dalam (memimpin) kaumku, dan perbaikilah, dan janganlah kamu mengikuti jalan orang-orang yang membuat kerusakan\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 143, "text": "وَلَمَّا جَاۤءَ مُوسَىٰ لِمِیقَـٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِیۤ أَنظُرۡ إِلَیۡكَۚ قَالَ لَن تَرَىٰنِی وَلَـٰكِنِ ٱنظُرۡ إِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِیۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكࣰّا وَخَرَّ مُوسَىٰ صَعِقࣰاۚ فَلَمَّاۤ أَفَاقَ قَالَ سُبۡحَـٰنَكَ تُبۡتُ إِلَیۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِینَ ۝١٤٣", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "ولما جاء موسى في الوقت المحدد وهو تمام أربعين ليلة، وكلَّمه ربه بما كلَّمه من وحيه وأمره ونهيه، طمع في رؤية الله فطلب النظر إليه، قال الله له: لن تراني، أي لن تقدر على رؤيتي في الدنيا، ولكن انظر إلى الجبل، فإن استقر مكانه إذا تجلَّيتُ له فسوف تراني، فلما تجلَّى ربه للجبل جعله دكًّا مستويًا بالأرض، وسقط موسى مغشيًّا عليه، فلما أفاق من غشيته قال: تنزيهًا لك يا رب عما لا يليق بجلالك، إني تبت إليك من مسألتي إياك الرؤية في هذه الحياة الدنيا، وأنا أول المؤمنين بك من قومي.", "isBasmala": false, "translation_en": "And when Moses came to Our appointment, and his Lord spoke to him, he said, \"My Lord, allow me to look and see You.\" He said, \"You will not see Me, but look at the mountain; if it stays in its place, you will see Me.\" But when his Lord manifested Himself to the mountain, He turned it into dust, and Moses fell down unconscious. Then, when he recovered, he said, \"Glory be to you, I repent to you, and I am the first of the believers.\"", "translation_id": "Dan tatkala Musa datang untuk (munajat dengan Kami) pada waktu yang telah Kami tentukan dan Tuhan telah berfirman (langsung) kepadanya, berkatalah Musa: \"Ya Tuhanku, nampakkanlah (diri Engkau) kepadaku agar aku dapat melihat kepada Engkau\". Tuhan berfirman: \"Kamu sekali-kali tidak sanggup melihat-Ku, tapi lihatlah ke bukit itu, maka jika ia tetap di tempatnya (sebagai sediakala) niscaya kamu dapat melihat-Ku\". Tatkala Tuhannya menampakkan diri kepada gunung itu, dijadikannya gunung itu hancur luluh dan Musa pun jatuh pingsan. Maka setelah Musa sadar kembali, dia berkata: \"Maha Suci Engkau, aku bertaubat kepada Engkau dan aku orang yang pertama-tama beriman\".", "manzil": 2, "manzil_display": ""}], "168": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 144, "text": "قَالَ یَـٰمُوسَىٰۤ إِنِّی ٱصۡطَفَیۡتُكَ عَلَى ٱلنَّاسِ بِرِسَـٰلَـٰتِی وَبِكَلَـٰمِی فَخُذۡ مَاۤ ءَاتَیۡتُكَ وَكُن مِّنَ ٱلشَّـٰكِرِینَ ۝١٤٤", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "قال الله يا موسى: إني اخترتك على الناس برسالاتي إلى خلقي الذين أرسلتك إليهم وبكلامي إياك مِن غير وساطة، فخذ ما أعطيتك مِن أمري ونهيي، وتمسَّك به، واعمل به، وكن من الشاكرين لله تعالى على ما آتاك من رسالته، وخصَّك بكلامه.", "isBasmala": false, "translation_en": "He said, \"O Moses, I have chosen you over all people for My messages and for My Words. So take what I have given you, and be one of the thankful.\"", "translation_id": "Allah berfirman: \"Hai Musa, sesungguhnya Aku memilih (melebihkan) kamu dan manusia yang lain (di masamu) untuk membawa risalah-Ku dan untuk berbicara langsung dengan-Ku, sebab itu berpegang teguhlah kepada apa yang Aku berikan kepadamu dan hendaklah kamu termasuk orang-orang yang bersyukur\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 145, "text": "وَكَتَبۡنَا لَهُۥ فِی ٱلۡأَلۡوَاحِ مِن كُلِّ شَیۡءࣲ مَّوۡعِظَةࣰ وَتَفۡصِیلࣰا لِّكُلِّ شَیۡءࣲ فَخُذۡهَا بِقُوَّةࣲ وَأۡمُرۡ قَوۡمَكَ یَأۡخُذُوا۟ بِأَحۡسَنِهَاۚ سَأُو۟رِیكُمۡ دَارَ ٱلۡفَـٰسِقِینَ ۝١٤٥", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "وكتبنا لموسى في التوراة من كل ما يحتاج إليه في دينه من الأحكام، موعظة للازدجار والاعتبار وتفصيلا لتكاليف الحلال والحرام والأمر والنهي والقصص والعقائد والأخبار والمغيبات، قال الله له: فخذها بقوة، أي: خذ التوراة بجد واجتهاد، وأمر قومك يعملوا بما شرع الله فيها؛ فإن مَن أشرك منهم ومِن غيرهم فإني سأريه في الآخرة دار الفاسقين، وهي نار الله التي أعدَّها لأعدائه الخارجين عن طاعته.", "isBasmala": false, "translation_en": "And We inscribed for him in the Tablets all kinds of enlightenments, and decisive explanation of all things. \"Hold fast to them, and exhort your people to adopt the best of them. I will show you the fate of the sinners.\"", "translation_id": "Dan telah Kami tuliskan untuk Musa pada luh-luh (Taurat) segala sesuatu sebagai pelajaran dan penjelasan bagi segala sesuatu; maka (Kami berfirman): \"Berpeganglah kepadanya dengan teguh dan suruhlah kaummu berpegang kepada (perintah-perintahnya) dengan sebaik-baiknya, nanti Aku akan memperlihatkan kepadamu negeri orang-orang yang fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 146, "text": "سَأَصۡرِفُ عَنۡ ءَایَـٰتِیَ ٱلَّذِینَ یَتَكَبَّرُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَإِن یَرَوۡا۟ كُلَّ ءَایَةࣲ لَّا یُؤۡمِنُوا۟ بِهَا وَإِن یَرَوۡا۟ سَبِیلَ ٱلرُّشۡدِ لَا یَتَّخِذُوهُ سَبِیلࣰا وَإِن یَرَوۡا۟ سَبِیلَ ٱلۡغَیِّ یَتَّخِذُوهُ سَبِیلࣰاۚ ذَ ٰلِكَ بِأَنَّهُمۡ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَكَانُوا۟ عَنۡهَا غَـٰفِلِینَ ۝١٤٦", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "سأصرف عن فَهْم الحجج والأدلة الدالة على عظمتي وشريعتي وأحكامي قلوب المتكبرين عن طاعتي، والمتكبرين على الناس بغير الحق، فلا يتبعون نبيًا ولا يصغون إليه لتكبرهم، وإنْ يَرَ هؤلاء المتكبرون عن الإيمان كل آية لا يؤمنوا بها لإعراضهم ومحادَّتهم لله ورسوله، وإن يروا طريق الصلاح لا يتخذوه طريقًا، وإن يروا طريق الضلال، أي الكفر يتخذوه طريقًا ودينًا؛ وذلك بسبب تكذيبهم بآيات الله وغفلتهم عن النظر فيها والتفكر في دلالاتها.", "isBasmala": false, "translation_en": "I will turn away from My revelations those who behave proudly on earth without justification. Even if they see every sign, they will not believe in it; and if they see the path of rectitude, they will not adopt it for a path; and if they see the path of error, they will adopt it for a path. That is because they denied Our revelations, and paid no attention to them.", "translation_id": "Aku akan memalingkan orang-orang yang menyombongkan dirinya di muka bumi tanpa alasan yang benar dari tanda-tanda kekuasaan-Ku. Mereka jika melihat tiap-tiap ayat(Ku), mereka tidak beriman kepadanya. Dan jika mereka melihat jalan yang membawa kepada petunjuk, mereka tidak mau menempuhnya, tetapi jika mereka melihat jalan kesesatan, mereka terus memenempuhnya. Yang demikian itu adalah karena mereka mendustakan ayat-ayat Kami dan mereka selalu lalai dari padanya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 147, "text": "وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَلِقَاۤءِ ٱلۡـَٔاخِرَةِ حَبِطَتۡ أَعۡمَـٰلُهُمۡۚ هَلۡ یُجۡزَوۡنَ إِلَّا مَا كَانُوا۟ یَعۡمَلُونَ ۝١٤٧", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "والذين كذَّبوا بآيات الله وحججه وبلقاء الله في الآخرة حبطت أعمالهم؛ بسبب فَقْدِ شرطها، وهو الإيمان بالله والتصديق بجزائه، ما يجزون في الآخرة إلا جزاء ما كانوا يعملونه في الدنيا من الكفر والمعاصي، وهو الخلود في النار.", "isBasmala": false, "translation_en": "Those who deny Our revelations and the meeting of the Hereafter-their deeds will come to nothing. Will they be repaid except according to what they used to do?", "translation_id": "Dan orang-orang yang mendustakan ayat-ayat Kami dan mendustakan akan menemui akhirat, sia-sialah perbuatan mereka. Mereka tidak diberi balasan selain dari apa yang telah mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 148, "text": "وَٱتَّخَذَ قَوۡمُ مُوسَىٰ مِنۢ بَعۡدِهِۦ مِنۡ حُلِیِّهِمۡ عِجۡلࣰا جَسَدࣰا لَّهُۥ خُوَارٌۚ أَلَمۡ یَرَوۡا۟ أَنَّهُۥ لَا یُكَلِّمُهُمۡ وَلَا یَهۡدِیهِمۡ سَبِیلًاۘ ٱتَّخَذُوهُ وَكَانُوا۟ ظَـٰلِمِینَ ۝١٤٨", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "واتخذ قوم موسى من بعد ما فارقهم ماضيًا لمناجاة ربه معبودًا مِن ذهبهم عِجلا جسدًا بلا روح، له صوت، ألم يعلموا أنه لا يكلمهم، ولا يرشدهم إلى خير؟ أَقْدَمُوا على ما أقدموا عليه من هذا الأمر الشنيع، وكانوا ظالمين لأنفسهم واضعين الشيء في غير موضعه.", "isBasmala": false, "translation_en": "In his absence, the people of Moses adopted a calf made from their ornaments-a body which lowed. Did they not see that it could not speak to them, nor guide them in any way? They took it for worship. They were in the wrong.", "translation_id": "Dan kaum Musa, setelah kepergian Musa ke gunung Thur membuat dari perhiasan-perhiasan (emas) mereka anak lembu yang bertubuh dan bersuara. Apakah mereka tidak mengetahui bahwa anak lembu itu tidak dapat berbicara dengan mereka dan tidak dapat (pula) menunjukkan jalan kepada mereka? Mereka menjadikannya (sebagai sembahan) dan mereka adalah orang-orang yang zalim.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 149, "text": "وَلَمَّا سُقِطَ فِیۤ أَیۡدِیهِمۡ وَرَأَوۡا۟ أَنَّهُمۡ قَدۡ ضَلُّوا۟ قَالُوا۟ لَىِٕن لَّمۡ یَرۡحَمۡنَا رَبُّنَا وَیَغۡفِرۡ لَنَا لَنَكُونَنَّ مِنَ ٱلۡخَـٰسِرِینَ ۝١٤٩", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "ولما ندم الذين عبدوا العجل مِن دون الله عند رجوع موسى إليهم، ورأوا أنهم قد ضلُّوا عن قصد السبيل، وذهبوا عن دين الله، أخذوا في الإقرار بالعبودية والاستغفار، فقالوا: لئن لم يرحمنا ربنا بقَبول توبتنا، ويستر بها ذنوبنا، لنكونن من الهالكين الذين ذهبت أعمالهم.", "isBasmala": false, "translation_en": "Then, when they regretted, and realized that they had erred, they said, \"Unless our Lord extends His mercy to us, and forgives us, we will be among the losers.\"", "translation_id": "Dan setelah mereka sangat menyesali perbuatannya dan mengetahui bahwa mereka telah sesat, merekapun berkata: \"Sungguh jika Tuhan kami tidak memberi rahmat kepada kami dan tidak mengampuni kami, pastilah kami menjadi orang-orang yang merugi\".", "manzil": 2, "manzil_display": ""}], "169": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 150, "text": "وَلَمَّا رَجَعَ مُوسَىٰۤ إِلَىٰ قَوۡمِهِۦ غَضۡبَـٰنَ أَسِفࣰا قَالَ بِئۡسَمَا خَلَفۡتُمُونِی مِنۢ بَعۡدِیۤۖ أَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡۖ وَأَلۡقَى ٱلۡأَلۡوَاحَ وَأَخَذَ بِرَأۡسِ أَخِیهِ یَجُرُّهُۥۤ إِلَیۡهِۚ قَالَ ٱبۡنَ أُمَّ إِنَّ ٱلۡقَوۡمَ ٱسۡتَضۡعَفُونِی وَكَادُوا۟ یَقۡتُلُونَنِی فَلَا تُشۡمِتۡ بِیَ ٱلۡأَعۡدَاۤءَ وَلَا تَجۡعَلۡنِی مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝١٥٠", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "ولما رجع موسى إلى قومه مِن بني إسرائيل غضبان حزينًا؛ لأن الله قد أخبره أنه قد فُتِن قومه، وأن السامريَّ قد أضلَّهم، قال موسى: بئس الخلافة التي خلفتموني مِن بعدي، أعجلتم أَمْر ربكم؟ أي: أستعجلتم مجيئي إليكم وهو مقدَّر من الله تعالى؟ وألقى موسى ألواح التوراة غضبا على قومه الذين عبدوا العجل، وغضبًا على أخيه هارون، وأمسك برأس أخيه يجره إليه، قال هارون مستعطفًا: يا ابن أمي: إن القوم استذلوني وعدُّوني ضعيفًا وقاربوا أن يقتلوني، فلا تَسرَّ الأعداء بما تفعل بي، ولا تجعلني في غضبك مع القوم الذين خالفوا أمرك وعبدوا العجل.", "isBasmala": false, "translation_en": "And when Moses returned to his people, angry and disappointed, he said, \"What an awful thing you did in my absence. Did you forsake the commandments of your Lord so hastily?\" And he threw down the tablets; and he took hold of his brother's head, dragging him towards himself. He said, \"Son of my mother, the people have overpowered me, and were about to kill me; so do not allow the enemies to gloat over me, and do not count me among the unjust people.\"", "translation_id": "Dan tatkala Musa telah kembali kepada kaumnya dengan marah dan sedih hati berkatalah dia: \"Alangkah buruknya perbuatan yang kamu kerjakan sesudah kepergianku! Apakah kamu hendak mendahului janji Tuhanmu? Dan Musapun melemparkan luh-luh (Taurat) itu dan memegang (rambut) kepala saudaranya (Harun) sambil menariknya ke arahnya, Harun berkata: \"Hai anak ibuku, sesungguhnya kaum ini telah menganggapku lemah dan hampir-hampir mereka membunuhku, sebab itu janganlah kamu menjadikan musuh-musuh gembira melihatku, dan janganlah kamu masukkan aku ke dalam golongan orang-orang yang zalim\"", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 151, "text": "قَالَ رَبِّ ٱغۡفِرۡ لِی وَلِأَخِی وَأَدۡخِلۡنَا فِی رَحۡمَتِكَۖ وَأَنتَ أَرۡحَمُ ٱلرَّ ٰحِمِینَ ۝١٥١", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "قال موسى لما تبين له عذر أخيه، وعلم أنه لم يُفَرِّط فيما كان عليه من أمر الله: ربِّ اغفر لي غضبي، واغفر لأخي ما سبق بينه وبين بني إسرائيل، وأدخلنا في رحمتك الواسعة، فإنك أرحم بنا من كل راحم.", "isBasmala": false, "translation_en": "He said, \"My Lord, forgive me and my brother, and admit us into Your mercy; for you are the Most Merciful of the merciful.\"", "translation_id": "Musa berdoa: \"Ya Tuhanku, ampunilah aku dan saudaraku dan masukkanlah kami ke dalam rahmat Engkau, dan Engkau adalah Maha Penyayang di antara para penyayang\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 152, "text": "إِنَّ ٱلَّذِینَ ٱتَّخَذُوا۟ ٱلۡعِجۡلَ سَیَنَالُهُمۡ غَضَبࣱ مِّن رَّبِّهِمۡ وَذِلَّةࣱ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَكَذَ ٰلِكَ نَجۡزِی ٱلۡمُفۡتَرِینَ ۝١٥٢", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "إن الذين اتخذوا العجل إلهًا سينالهم غضب شديد مِن ربهم وهوان في الحياة الدنيا؛ بسبب كفرهم بربهم، وكما فعلنا بهؤلاء نفعل بالمفترين المبتدعين في دين الله، فكل صاحب بدعة ذليل.", "isBasmala": false, "translation_en": "Those who idolized the calf have incurred wrath from their Lord, and humiliation in this life. We thus requite the innovators.", "translation_id": "Sesungguhnya orang-orang yang menjadikan anak lembu (sebagai sembahannya), kelak akan menimpa mereka kemurkaan dari Tuhan mereka dan kehinaan dalam kehidupan di dunia. Demikianlah Kami memberi balasan kepada orang-orang yang membuat-buat kebohongan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 153, "text": "وَٱلَّذِینَ عَمِلُوا۟ ٱلسَّیِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعۡدِهَا وَءَامَنُوۤا۟ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِیمࣱ ۝١٥٣", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "والذين عملوا السيئات من الكفر والمعاصي، ثم رجعوا مِن بعد فعلها إلى الإيمان والعمل الصالح، إن ربك من بعد التوبة النصوح لغفور لأعمالهم غير فاضحهم بها، رحيم بهم وبكل مَن كان مثلهم من التائبين.", "isBasmala": false, "translation_en": "As for those who commit sins, and then repent afterwards and believe-your Lord, thereafter, is Forgiving and Merciful.", "translation_id": "Orang-orang yang mengerjakan kejahatan, kemudian bertaubat sesudah itu dan beriman; sesungguhnya Tuhan kamu sesudah taubat yang disertai dengan iman itu adalah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 154, "text": "وَلَمَّا سَكَتَ عَن مُّوسَى ٱلۡغَضَبُ أَخَذَ ٱلۡأَلۡوَاحَۖ وَفِی نُسۡخَتِهَا هُدࣰى وَرَحۡمَةࣱ لِّلَّذِینَ هُمۡ لِرَبِّهِمۡ یَرۡهَبُونَ ۝١٥٤", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "ولما سكن عن موسى غضبه أخذ الألواح بعد أن ألقاها على الأرض، وفيها بيان للحق ورحمة للذين يخافون الله، ويخشون عقابه.", "isBasmala": false, "translation_en": "When the anger abated in Moses, he took up the tablets. In their transcript is guidance and mercy for those in awe of their Lord.", "translation_id": "Sesudah amarah Musa menjadi reda, lalu diambilnya (kembali) luh-luh (Taurat) itu; dan dalam tulisannya terdapat petunjuk dan rahmat untuk orang-orang yang takut kepada Tuhannya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 155, "text": "وَٱخۡتَارَ مُوسَىٰ قَوۡمَهُۥ سَبۡعِینَ رَجُلࣰا لِّمِیقَـٰتِنَاۖ فَلَمَّاۤ أَخَذَتۡهُمُ ٱلرَّجۡفَةُ قَالَ رَبِّ لَوۡ شِئۡتَ أَهۡلَكۡتَهُم مِّن قَبۡلُ وَإِیَّـٰیَۖ أَتُهۡلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَاۤءُ مِنَّاۤۖ إِنۡ هِیَ إِلَّا فِتۡنَتُكَ تُضِلُّ بِهَا مَن تَشَاۤءُ وَتَهۡدِی مَن تَشَاۤءُۖ أَنتَ وَلِیُّنَا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَاۖ وَأَنتَ خَیۡرُ ٱلۡغَـٰفِرِینَ ۝١٥٥", "juz": 9, "hizb": "(*½ ح 17*)", "tafsir": "واختار موسى من قومه سبعين رجلا مِن خيارهم، وخرج بهم إلى طور \"سيناء\" للوقت والأجل الذي واعده الله أن يلقاه فيه بهم للتوبة مما كان من سفهاء بني إسرائيل من عبادة العجل، فلما أتوا ذلك المكان قالوا: لن نؤمن لك -يا موسى- حتى نرى الله جهرة فإنك قد كلَّمته فأرِنَاهُ، فأخذتهم الزلزلة الشديدة فماتوا، فقام موسى يتضرع إلى الله ويقول: رب ماذا أقول لبني إسرائيل إذا أتيتُهم، وقد أهلكتَ خيارهم؟ لو شئت أهلكتهم جميعًا من قبل هذا الحال وأنا معهم، فإن ذلك أخف عليَّ، أتهلكنا بما فعله سفهاء الأحلام منا؟ ما هذه الفعلة التي فعلها قومي من عبادتهم العجل إلا ابتلاءٌ واختبارٌ، تضلُّ بها مَن تشاء مِن خلقك، وتهدي بها من تشاء هدايته، أنت وليُّنا وناصرنا، فاغفر ذنوبنا، وارحمنا برحمتك، وأنت خير مَن صفح عن جُرْم، وستر عن ذنب.", "isBasmala": false, "translation_en": "And Moses chose from his people seventy men for Our appointment. When the tremor shook them, he said, \"My Lord, had You willed, You could have destroyed them before, and me too. Will you destroy us for what the fools among us have done? This is but Your test-with it You misguide whomever You will, and guide whomever You will. You are our Protector, so forgive us, and have mercy on us. You are the Best of Forgivers.\"", "translation_id": "Dan Musa memilih tujuh puluh orang dari kaumnya untuk (memohonkan taubat kepada Kami) pada waktu yang telah Kami tentukan. Maka ketika mereka digoncang gempa bumi, Musa berkata: \"Ya Tuhanku, kalau Engkau kehendaki, tentulah Engkau membinasakan mereka dan aku sebelum ini. Apakah Engkau membinasakan kami karena perbuatan orang-orang yang kurang akal di antara kami? Itu hanyalah cobaan dari Engkau, Engkau sesatkan dengan cobaan itu siapa yang Engkau kehendaki dan Engkau beri petunjuk kepada siapa yang Engkau kehendaki. Engkaulah Yang memimpin kami, maka ampunilah kami dan berilah kami rahmat dan Engkaulah Pemberi ampun yang sebaik-baiknya\".", "manzil": 2, "manzil_display": ""}], "170": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 156, "text": "۞ وَٱكۡتُبۡ لَنَا فِی هَـٰذِهِ ٱلدُّنۡیَا حَسَنَةࣰ وَفِی ٱلۡـَٔاخِرَةِ إِنَّا هُدۡنَاۤ إِلَیۡكَۚ قَالَ عَذَابِیۤ أُصِیبُ بِهِۦ مَنۡ أَشَاۤءُۖ وَرَحۡمَتِی وَسِعَتۡ كُلَّ شَیۡءࣲۚ فَسَأَكۡتُبُهَا لِلَّذِینَ یَتَّقُونَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلَّذِینَ هُم بِـَٔایَـٰتِنَا یُؤۡمِنُونَ ۝١٥٦", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "واجعلنا ممن كتبتَ له الصالحات من الأعمال في الدنيا وفي الآخرة، إنا رجعنا تائبين إليك، قال الله تعالى لموسى: عذابي أصيب به مَن أشاء مِن خلقي، كما أصبتُ هؤلاء الذين أصبتهم من قومك، ورحمتي وسعت خلقي كلَّهم، فسأكتبها للذين يخافون الله، ويخشون عقابه، فيؤدون فرائضه، ويجتنبون معاصيه، والذين هم بدلائل التوحيد وبراهينه يصدقون.", "isBasmala": false, "translation_en": "\"And inscribe for us goodness in this world, and in the Hereafter. We have turned to You.\" He said, \"My punishment-I inflict it upon whomever I will, but My mercy encompasses all things. I will specify it for those who act righteously and practice regular charity, and those who believe in Our signs.\"", "translation_id": "Dan tetapkanlah untuk kami kebajikan di dunia ini dan di akhirat; sesungguhnya kami kembali (bertaubat) kepada Engkau. Allah berfirman: \"Siksa-Ku akan Kutimpakan kepada siapa yang Aku kehendaki dan rahmat-Ku meliputi segala sesuatu. Maka akan Aku tetapkan rahmat-Ku untuk orang-orang yang bertakwa, yang menunaikan zakat dan orang-orang yang beriman kepada ayat-ayat Kami\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 157, "text": "ٱلَّذِینَ یَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِیَّ ٱلۡأُمِّیَّ ٱلَّذِی یَجِدُونَهُۥ مَكۡتُوبًا عِندَهُمۡ فِی ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِیلِ یَأۡمُرُهُم بِٱلۡمَعۡرُوفِ وَیَنۡهَىٰهُمۡ عَنِ ٱلۡمُنكَرِ وَیُحِلُّ لَهُمُ ٱلطَّیِّبَـٰتِ وَیُحَرِّمُ عَلَیۡهِمُ ٱلۡخَبَـٰۤىِٕثَ وَیَضَعُ عَنۡهُمۡ إِصۡرَهُمۡ وَٱلۡأَغۡلَـٰلَ ٱلَّتِی كَانَتۡ عَلَیۡهِمۡۚ فَٱلَّذِینَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِیۤ أُنزِلَ مَعَهُۥۤ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝١٥٧", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "هذه الرحمة سأكتبها للذين يخافون الله ويجتنبون معاصيه، ويتبعون الرسول النبي الأمي الذي لا يقرأ ولا يكتب، وهو محمد صلى الله عليه وسلم، الذي يجدون صفته وأمره مكتوبَيْن عندهم في التوراة والإنجيل، يأمرهم بالتوحيد والطاعة وكل ما عرف حُسْنه، وينهاهم عن الشرك والمعصية وكل ما عرف قُبْحه، ويُحِلُّ لهم الطيبات من المطاعم والمشارب والمناكح، ويُحرِّم عليهم الخبائث منها كلحم الخنزير، وما كانوا يستحلُّونه من المطاعم والمشارب التي حرَّمها الله، ويذهب عنهم ما كُلِّفوه من الأمور الشاقة كقطع موضع النجاسة من الجلد والثوب، وإحراق الغنائم، والقصاص حتمًا من القاتل عمدًا كان القتل أم خطأ، فالذين صدَّقوا بالنبي الأمي محمد صلى الله عليه وسلم وأقروا بنبوته، ووقروه وعظَّموه ونصروه، واتبعوا القرآن المنزل عليه، وعملوا بسنته، أولئك هم الفائزون بما وعد الله به عباده المؤمنين.", "isBasmala": false, "translation_en": "Those who follow the Messenger, the Unlettered Prophet, whom they find mentioned in the Torah and the Gospel in their possession. He directs them to righteousness, and deters them from evil, and allows for them all good things, and prohibits for them wickedness, and unloads the burdens and the shackles that are upon them. Those who believe in him, and respect him, and support him, and follow the light that came down with him-these are the successful.", "translation_id": "(Yaitu) orang-orang yang mengikut Rasul, Nabi yang ummi yang (namanya) mereka dapati tertulis di dalam Taurat dan Injil yang ada di sisi mereka, yang menyuruh mereka mengerjakan yang ma'ruf dan melarang mereka dari mengerjakan yang mungkar dan menghalalkan bagi mereka segala yang baik dan mengharamkan bagi mereka segala yang buruk dan membuang dari mereka beban-beban dan belenggu-belenggu yang ada pada mereka. Maka orang-orang yang beriman kepadanya. memuliakannya, menolongnya dan mengikuti cahaya yang terang yang diturunkan kepadanya (Al Quran), mereka itulah orang-orang yang beruntung.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 158, "text": "قُلۡ یَـٰۤأَیُّهَا ٱلنَّاسُ إِنِّی رَسُولُ ٱللَّهِ إِلَیۡكُمۡ جَمِیعًا ٱلَّذِی لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ لَاۤ إِلَـٰهَ إِلَّا هُوَ یُحۡیِۦ وَیُمِیتُۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِیِّ ٱلۡأُمِّیِّ ٱلَّذِی یُؤۡمِنُ بِٱللَّهِ وَكَلِمَـٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمۡ تَهۡتَدُونَ ۝١٥٨", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "قل -أيها الرسول- للناس كلهم: إني رسول الله إليكم جميعًا لا إلى بعضكم دون بعض، الذي له ملك السموات والأرض وما فيهما، لا ينبغي أن تكون الألوهية والعبادة إلا له جل ثناؤه، القادر على إيجاد الخلق وإفنائه وبعثه، فصدَّقوا بالله وأقرُّوا بوحدانيته، وصدَّقوا برسوله محمد صلى الله عليه وسلم النبي الأميِّ الذي يؤمن بالله وما أنزل إليه من ربه وما أنزل على النبيين من قبله، واتبعوا هذا الرسول، والتزموا العمل بما أمركم به من طاعة الله، رجاء أن توفقوا إلى الطريق المستقيم.", "isBasmala": false, "translation_en": "Say, \"O people, I am the Messenger of God to you all-He to whom belongs the kingdom of the heavens and the earth. There is no god but He. He gives life and causes death.\" So believe in God and His Messenger, the Unlettered Prophet, who believes in God and His words. And follow him, that you may be guided.", "translation_id": "Katakanlah: \"Hai manusia sesungguhnya aku adalah utusan Allah kepadamu semua, yaitu Allah Yang mempunyai kerajaan langit dan bumi; tidak ada Tuhan (yang berhak disembah) selain Dia, Yang menghidupkan dan mematikan, maka berimanlah kamu kepada Allah dan Rasul-Nya, Nabi yang ummi yang beriman kepada Allah dan kepada kalimat-kalimat-Nya (kitab-kitab-Nya) dan ikutilah dia, supaya kamu mendapat petunjuk\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 159, "text": "وَمِن قَوۡمِ مُوسَىٰۤ أُمَّةࣱ یَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ یَعۡدِلُونَ ۝١٥٩", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "ومِن بني إسرائيل من قوم موسى جماعة يستقيمون على الحق، يهدون الناس به، ويعدلون به في الحكم في قضاياهم.", "isBasmala": false, "translation_en": "Among the people of Moses is a community that guides by truth, and thereby does justice.", "translation_id": "Dan di antara kaum Musa itu terdapat suatu umat yang memberi petunjuk (kepada manusia) dengan hak dan dengan yang hak itulah mereka menjalankan keadilan.", "manzil": 2, "manzil_display": ""}], "171": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 160, "text": "وَقَطَّعۡنَـٰهُمُ ٱثۡنَتَیۡ عَشۡرَةَ أَسۡبَاطًا أُمَمࣰاۚ وَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ إِذِ ٱسۡتَسۡقَىٰهُ قَوۡمُهُۥۤ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡحَجَرَۖ فَٱنۢبَجَسَتۡ مِنۡهُ ٱثۡنَتَا عَشۡرَةَ عَیۡنࣰاۖ قَدۡ عَلِمَ كُلُّ أُنَاسࣲ مَّشۡرَبَهُمۡۚ وَظَلَّلۡنَا عَلَیۡهِمُ ٱلۡغَمَـٰمَ وَأَنزَلۡنَا عَلَیۡهِمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰۖ كُلُوا۟ مِن طَیِّبَـٰتِ مَا رَزَقۡنَـٰكُمۡۚ وَمَا ظَلَمُونَا وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ ۝١٦٠", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "وفرَّقنا قوم موسى مِن بني إسرائيل اثنتي عشرة قبيلة بعدد الأسباط -وهم أبناء يعقوب- كل قبيلة معروفة من جهة نقيبها. وأوحينا إلى موسى إذ طلب منه قومه السقيا حين عطشوا في التِّيْه: أن اضرب بعصاك الحجر، فضربه، فانفجرت منه اثنتا عشرة عينًا من الماء، قد علمت كل قبيلة من القبائل الاثنتي عشرة مشربهم، لا تدخل قبيلة على غيرها في شربها، وظلَّلنا عليهم السحاب، وأنزلنا عليهم المنَّ -وهو شيء يشبه الصَّمغ، طعمه كالعسل - والسلوى، وهو طائر يشبه السُّمَانَى، وقلنا لهم: كلوا من طيبات ما رزقناكم، فكرهوا ذلك وملُّوه من طول المداومة عليه، وقالوا: لن نصبر على طعام واحد، وطلبوا استبدال الذي هو أدنى بالذي هو خير. وما ظلمونا حين لم يشكروا لله، ولم يقوموا بما أوجب الله عليهم، ولكن كانوا أنفسهم يظلمون؛ إذ فوَّتوا عليها كل خير، وعرَّضوها للشر والنقمة.", "isBasmala": false, "translation_en": "We divided them into twelve tribal communities. And We inspired Moses, when his people asked him for something to drink: \"Strike the rock with your staff.\" Whereupon twelve springs gushed from it. Each group recognized its drinking-place. And We shaded them with clouds, and We sent down upon them manna and quails: \"Eat of the good things We have provided for you.\" They did not wrong Us, but they used to wrong their own selves.", "translation_id": "Dan mereka Kami bagi menjadi dua belas suku yang masing-masingnya berjumlah besar dan Kami wahyukan kepada Musa ketika kaumnya meminta air kepadanya: \"Pukullah batu itu dengan tongkatmu!\". Maka memancarlah dari padanya duabelas mata air. Sesungguhnya tiap-tiap suku mengetahui tempat minum masing-masing. Dan Kami naungkan awan di atas mereka dan Kami turunkan kepada mereka manna dan salwa. (Kami berfirman): \"Makanlah yang baik-baik dari apa yang telah Kami rezekikan kepadamu\". Mereka tidak menganiaya Kami, tapi merekalah yang selalu menganiaya dirinya sendiri.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 161, "text": "وَإِذۡ قِیلَ لَهُمُ ٱسۡكُنُوا۟ هَـٰذِهِ ٱلۡقَرۡیَةَ وَكُلُوا۟ مِنۡهَا حَیۡثُ شِئۡتُمۡ وَقُولُوا۟ حِطَّةࣱ وَٱدۡخُلُوا۟ ٱلۡبَابَ سُجَّدࣰا نَّغۡفِرۡ لَكُمۡ خَطِیۤـَٔـٰتِكُمۡۚ سَنَزِیدُ ٱلۡمُحۡسِنِینَ ۝١٦١", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "واذكر -أيها الرسول- عصيان بني إسرائيل لربهم سبحانه وتعالى ولنبيهم موسى عليه السلام، وتبديلهم القول الذي أمروا أن يقولوه حين قال الله لهم: اسكنوا قرية \"بيت المقدس\"، وكلوا من ثمارها وحبوبها ونباتها أين شئتم ومتى شئتم، وقولوا: حُطَّ عنا ذنوبنا، وادخلوا الباب خاضعين لله، نغفر لكم خطاياكم، فلا نؤاخذكم عليها، وسنزيد المحسنين مِن خَيْرَيِ الدنيا والآخرة.", "isBasmala": false, "translation_en": "And it was said to them, \"Settle this town, and eat therein whatever you wish, and speak modestly, and enter the gate in humility-We will forgive your sins, and will promote the righteous.\"", "translation_id": "Dan (ingatlah), ketika dikatakan kepada mereka (Bani Israil): \"Diamlah di negeri ini saja (Baitul Maqdis) dan makanlah dari (hasil bumi)nya di mana saja kamu kehendaki\". Dan katakanlah: \"Bebaskanlah kami dari dosa kami dan masukilah pintu gerbangnya sambil membungkuk, niscaya Kami ampuni kesalahan-kesalahanmu\". Kelak akan Kami tambah (pahala) kepada orang-orang yang berbuat baik.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 162, "text": "فَبَدَّلَ ٱلَّذِینَ ظَلَمُوا۟ مِنۡهُمۡ قَوۡلًا غَیۡرَ ٱلَّذِی قِیلَ لَهُمۡ فَأَرۡسَلۡنَا عَلَیۡهِمۡ رِجۡزࣰا مِّنَ ٱلسَّمَاۤءِ بِمَا كَانُوا۟ یَظۡلِمُونَ ۝١٦٢", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "فغيَّر الذين كفروا بالله منهم ما أمرهم الله به من القول، ودخلوا الباب يزحفون على أستاههم، وقالوا: حبة في شعرة، فأرسلنا عليهم عذابًا من السماء، أهلكناهم به؛ بسبب ظلمهم وعصيانهم.", "isBasmala": false, "translation_en": "But the wicked among them substituted other words for the words given to them; so We sent down upon them a plague from the sky, because of their wrongdoing.", "translation_id": "Maka orang-orang yang zalim di antara mereka itu mengganti (perkataan itu) dengan perkataan yang tidak dikatakan kepada mereka, maka Kami timpakan kepada mereka azab dari langit disebabkan kezaliman mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 163, "text": "وَسۡـَٔلۡهُمۡ عَنِ ٱلۡقَرۡیَةِ ٱلَّتِی كَانَتۡ حَاضِرَةَ ٱلۡبَحۡرِ إِذۡ یَعۡدُونَ فِی ٱلسَّبۡتِ إِذۡ تَأۡتِیهِمۡ حِیتَانُهُمۡ یَوۡمَ سَبۡتِهِمۡ شُرَّعࣰا وَیَوۡمَ لَا یَسۡبِتُونَ لَا تَأۡتِیهِمۡۚ كَذَ ٰلِكَ نَبۡلُوهُم بِمَا كَانُوا۟ یَفۡسُقُونَ ۝١٦٣", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "واسأل -أيها الرسول- هؤلاء اليهود عن خبر أهل القرية التي كانت بقرب البحر، إذ يعتدي أهلها في يوم السبت على حرمات الله، حيث أمرهم أن يعظموا يوم السبت ولا يصيدوا فيه سمكًا، فابتلاهم الله وامتحنهم؛ فكانت حيتانهم تأتيهم يوم السبت كثيرة طافية على وجه البحر، وإذا ذهب يوم السبت تذهب الحيتان في البحر، ولا يرون منها شيئًا، فكانوا يحتالون على حبسها في يوم السبت في حفائر، ويصطادونها بعده. وكما وصفنا لكم من الاختبار والابتلاء، لإظهار السمك على ظهر الماء في اليوم المحرم عليهم صيده فيه، وإخفائه عليهم في اليوم المحلل لهم فيه صيده، كذلك نختبرهم بسبب فسقهم عن طاعة الله وخروجهم عنها.", "isBasmala": false, "translation_en": "Ask them about the town by the sea, when they violated the Sabbath. When they observed the Sabbath, their fish would come to them abundantly. But when they violated the Sabbath, their fish would not come to them. Thus We tried them because they disobeyed.", "translation_id": "Dan tanyakanlah kepada Bani Israil tentang negeri yang terletak di dekat laut ketika mereka melanggar aturan pada hari Sabtu, di waktu datang kepada mereka ikan-ikan (yang berada di sekitar) mereka terapung-apung di permukaan air, dan di hari-hari yang bukan Sabtu, ikan-ikan itu tidak datang kepada mereka. Demikianlah Kami mencoba mereka disebabkan mereka berlaku fasik.", "manzil": 2, "manzil_display": ""}], "172": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 164, "text": "وَإِذۡ قَالَتۡ أُمَّةࣱ مِّنۡهُمۡ لِمَ تَعِظُونَ قَوۡمًا ٱللَّهُ مُهۡلِكُهُمۡ أَوۡ مُعَذِّبُهُمۡ عَذَابࣰا شَدِیدࣰاۖ قَالُوا۟ مَعۡذِرَةً إِلَىٰ رَبِّكُمۡ وَلَعَلَّهُمۡ یَتَّقُونَ ۝١٦٤", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "واذكر -أيها الرسول- إذ قالت جماعة منهم لجماعة أخرى كانت تعظ المعتدين في يوم السبت، وتنهاهم عن معصية الله فيه: لِمَ تعظون قومًا الله مهلكهم في الدنيا بمعصيتهم إياه أو معذبهم عذابا شديدًا في الآخرة؟ قال الذين كانوا ينهَوْنهم عن معصية الله: نَعِظهم وننهاهم لِنُعْذَر فيهم، ونؤدي فرض الله علينا في الأمر بالمعروف والنهي عن المنكر، ورجاء أن يتقوا الله، فيخافوه، ويتوبوا من معصيتهم ربهم وتعذِّيهم على ما حرَّم عليهم.", "isBasmala": false, "translation_en": "And when a group of them said, \"Why do you counsel a people whom God will annihilate, or punish with a severe punishment?\" They said, \"As an excuse to your Lord, and so that they may become righteous.\"", "translation_id": "Dan (ingatlah) ketika suatu umat di antara mereka berkata: \"Mengapa kamu menasehati kaum yang Allah akan membinasakan mereka atau mengazab mereka dengan azab yang amat keras?\" Mereka menjawab: \"Agar kami mempunyai alasan (pelepas tanggung jawab) kepada Tuhanmu, dan supaya mereka bertakwa.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 165, "text": "فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦۤ أَنجَیۡنَا ٱلَّذِینَ یَنۡهَوۡنَ عَنِ ٱلسُّوۤءِ وَأَخَذۡنَا ٱلَّذِینَ ظَلَمُوا۟ بِعَذَابِۭ بَـِٔیسِۭ بِمَا كَانُوا۟ یَفۡسُقُونَ ۝١٦٥", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "فلما تركت الطائفة التي اعتدت في يوم السبت ما ذُكِّرت به، واستمرت على غيِّها واعتدائها فيه، ولم تستجب لما وَعَظَتْها به الطائفة الواعظة، أنجى الله الذين ينهون عن معصيته، وأخذ الذين اعتدَوْا في يوم السبت بعذاب أليم شديد؛ بسبب مخالفتهم أمر الله وخروجهم عن طاعته.", "isBasmala": false, "translation_en": "Then, when they neglected what they were reminded of, We saved those who prohibited evil, and We seized those who did wrong with a terrible punishment, because of their sinfulness.", "translation_id": "Maka tatkala mereka melupakan apa yang diperingatkan kepada mereka, Kami selamatkan orang-orang yang melarang dari perbuatan jahat dan Kami timpakan kepada orang-orang yang zalim siksaan yang keras, disebabkan mereka selalu berbuat fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 166, "text": "فَلَمَّا عَتَوۡا۟ عَن مَّا نُهُوا۟ عَنۡهُ قُلۡنَا لَهُمۡ كُونُوا۟ قِرَدَةً خَـٰسِـِٔینَ ۝١٦٦", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "فلما تمردت تلك الطائفة، وتجاوزت ما نهاها الله عنه من عدم الصيد في يوم السبت، قال لهم الله: كونوا قردة خاسئين مبعدين من كل خير، فكانوا كذلك.", "isBasmala": false, "translation_en": "Then, when they rebelled against the commands to refrain, We said to them, \"Be despicable apes.\"", "translation_id": "Maka tatkala mereka bersikap sombong terhadap apa yang dilarang mereka mengerjakannya, Kami katakan kepadanya: \"Jadilah kamu kera yang hina.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 167, "text": "وَإِذۡ تَأَذَّنَ رَبُّكَ لَیَبۡعَثَنَّ عَلَیۡهِمۡ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ مَن یَسُومُهُمۡ سُوۤءَ ٱلۡعَذَابِۗ إِنَّ رَبَّكَ لَسَرِیعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورࣱ رَّحِیمࣱ ۝١٦٧", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "واذكر -أيها الرسول- إذ علم ذلك إعلامًا صريحًا ليبعثن على اليهود مَن يذيقهم سوء العذاب والإذلال إلى يوم القيامة. إن ربك -أيها الرسول- لسريع العقاب لِمَن استحقه بسبب كفره ومعصيته، وإنه لغفور عن ذنوب التائبين، رحيم بهم.", "isBasmala": false, "translation_en": "Your Lord has announced that, He would send against them, until the Day of Resurrection, those who would inflict terrible suffering upon them. Your Lord is swift in retribution, yet He is Forgiving and Merciful.", "translation_id": "Dan (ingatlah), ketika Tuhanmu memberitahukan, bahwa sesungguhnya Dia akan mengirim kepada mereka (orang-orang Yahudi) sampai hari kiamat orang-orang yang akan menimpakan kepada mereka azab yang seburuk-buruknya. Sesungguhnya Tuhanmu amat cepat siksa-Nya, dan sesungguhnya Dia adalah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 168, "text": "وَقَطَّعۡنَـٰهُمۡ فِی ٱلۡأَرۡضِ أُمَمࣰاۖ مِّنۡهُمُ ٱلصَّـٰلِحُونَ وَمِنۡهُمۡ دُونَ ذَ ٰلِكَۖ وَبَلَوۡنَـٰهُم بِٱلۡحَسَنَـٰتِ وَٱلسَّیِّـَٔاتِ لَعَلَّهُمۡ یَرۡجِعُونَ ۝١٦٨", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "وفرَّقنا بني إسرائيل في الأرض جماعات، منهم القائمون بحقوق الله وحقوق عباده، ومنهم المقصِّرون الظالمون لأنفسهم، واختبرنا هؤلاء بالرخاء في العيش والسَّعَة في الرزق، واختبرناهم أيضًا بالشدة في العيش والمصائب والرزايا؛ رجاء أن يرجعوا إلى طاعة ربهم ويتوبوا من معاصيه.", "isBasmala": false, "translation_en": "And We scattered them into communities on earth. Some of them righteous, and some of them short of that. And We tested them with fortunes and misfortunes, so that they may return.", "translation_id": "Dan Kami bagi-bagi mereka di dunia ini menjadi beberapa golongan; di antaranya ada orang-orang yang saleh dan di antaranya ada yang tidak demikian. Dan Kami coba mereka dengan (nikmat) yang baik-baik dan (bencana) yang buruk-buruk, agar mereka kembali (kepada kebenaran).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 169, "text": "فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفࣱ وَرِثُوا۟ ٱلۡكِتَـٰبَ یَأۡخُذُونَ عَرَضَ هَـٰذَا ٱلۡأَدۡنَىٰ وَیَقُولُونَ سَیُغۡفَرُ لَنَا وَإِن یَأۡتِهِمۡ عَرَضࣱ مِّثۡلُهُۥ یَأۡخُذُوهُۚ أَلَمۡ یُؤۡخَذۡ عَلَیۡهِم مِّیثَـٰقُ ٱلۡكِتَـٰبِ أَن لَّا یَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّ وَدَرَسُوا۟ مَا فِیهِۗ وَٱلدَّارُ ٱلۡـَٔاخِرَةُ خَیۡرࣱ لِّلَّذِینَ یَتَّقُونَۚ أَفَلَا تَعۡقِلُونَ ۝١٦٩", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "فجاء من بعد هؤلاء الذين وصفناهم بَدَلُ سوء أخذوا الكتاب من أسلافهم، فقرءوه وعلموه، وخالفوا حكمه، يأخذون ما يعرض لهم من متاع الدنيا من دنيء المكاسب كالرشوة وغيرها؛ وذلك لشدة حرصهم ونَهَمهم، ويقولون مع ذلك: إن الله سيغفر لنا ذنوبنا تمنيًا على الله الأباطيل، وإن يأت هؤلاء اليهودَ متاعٌ زائلٌ من أنواع الحرام يأخذوه ويستحلوه، مصرِّين على ذنوبهم وتناولهم الحرام، ألَمْ يؤخذ على هؤلاء العهود بإقامة التوراة والعمل بما فيها، وألا يقولوا على الله إلا الحق وألا يكذبوا عليه، وعلموا ما في الكتاب فضيعوه، وتركوا العمل به، وخالفوا عهد الله إليهم في ذلك؟ والدار الآخرة خير للذين يتقون الله، فيمتثلون أوامره، ويجتنبون نواهيه، أفلا يعقل هؤلاء الذين يأخذون دنيء المكاسب أن ما عند الله خير وأبقى للمتقين؟", "isBasmala": false, "translation_en": "They were succeeded by generations who inherited the Scripture and chose the materials of this world, saying, \"We will be forgiven.\" And should similar materials come their way, they would again seize them. Did they not make a covenant to uphold the Scripture, and to not say about God except the truth? Did they not study its contents? But the Home of the Hereafter is better for the cautious; will you not understand?", "translation_id": "Maka datanglah sesudah mereka generasi (yang jahat) yang mewarisi Taurat, yang mengambil harta benda dunia yang rendah ini, dan berkata: \"Kami akan diberi ampun\". Dan kelak jika datang kepada mereka harta benda dunia sebanyak itu (pula), niscaya mereka akan mengambilnya (juga). Bukankah perjanjian Taurat sudah diambil dari mereka, yaitu bahwa mereka tidak akan mengatakan terhadap Allah kecuali yang benar, padahal mereka telah mempelajari apa yang tersebut di dalamnya?. Dan kampung akhirat itu lebih bagi mereka yang bertakwa. Maka apakah kamu sekalian tidak mengerti?", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 170, "text": "وَٱلَّذِینَ یُمَسِّكُونَ بِٱلۡكِتَـٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِیعُ أَجۡرَ ٱلۡمُصۡلِحِینَ ۝١٧٠", "juz": 9, "hizb": "(*¾ ح 17*)", "tafsir": "والذين يتمسَّكون بالكتاب، ويعملون بما فيه من العقائد والأحكام، ويحافظون على الصلاة بحدودها، ولا يضيعون أوقاتها، فإن الله يثيبهم على أعمالهم الصالحة، ولا يضيعها.", "isBasmala": false, "translation_en": "Those who adhere to the Scripture, and practice prayer-We will not waste the reward of the reformers.", "translation_id": "Dan orang-orang yang berpegang teguh dengan Al Kitab (Taurat) serta mendirikan shalat, (akan diberi pahala) karena sesungguhnya Kami tidak menyia-nyiakan pahala orang-orang yang mengadakan perbaikan.", "manzil": 2, "manzil_display": ""}], "173": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 171, "text": "۞ وَإِذۡ نَتَقۡنَا ٱلۡجَبَلَ فَوۡقَهُمۡ كَأَنَّهُۥ ظُلَّةࣱ وَظَنُّوۤا۟ أَنَّهُۥ وَاقِعُۢ بِهِمۡ خُذُوا۟ مَاۤ ءَاتَیۡنَـٰكُم بِقُوَّةࣲ وَٱذۡكُرُوا۟ مَا فِیهِ لَعَلَّكُمۡ تَتَّقُونَ ۝١٧١", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "واذكر -أيها الرسول- إذ رفعنا الجبل فوق بني إسرائيل كأنه سحابة تظلهم، وأيقنوا أنه واقع بهم إن لم يقبلوا أحكام التوراة، وقلنا لهم: خذوا ما آتيناكم بقوة، أي اعملوا بما أعطيناكم باجتهاد منكم، واذكروا ما في كتابنا من العهود والمواثيق التي أخذناها عليكم بالعمل بما فيه؛ كي تتقوا ربكم فتنجوا من عقابه.", "isBasmala": false, "translation_en": "And when We suspended the mountain over them, as if it was an umbrella, and they thought it would fall on them: \"Hold fast to what We have given you, and remember what it contains, so that you may be saved.\"", "translation_id": "Dan (ingatlah), ketika Kami mengangkat bukit ke atas mereka seakan-akan bukit itu naungan awan dan mereka yakin bahwa bukit itu akan jatuh menimpa mereka. (Dan Kami katakan kepada mereka): \"Peganglah dengan teguh apa yang telah Kami berikan kepadamu, serta ingatlah selalu (amalkanlah) apa yang tersebut di dalamnya supaya kamu menjadi orang-orang yang bertakwa\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 172, "text": "وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِیۤ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّیَّتَهُمۡ وَأَشۡهَدَهُمۡ عَلَىٰۤ أَنفُسِهِمۡ أَلَسۡتُ بِرَبِّكُمۡۖ قَالُوا۟ بَلَىٰ شَهِدۡنَاۤۚ أَن تَقُولُوا۟ یَوۡمَ ٱلۡقِیَـٰمَةِ إِنَّا كُنَّا عَنۡ هَـٰذَا غَـٰفِلِینَ ۝١٧٢", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "واذكر -أيها النبي- إذ استخرج ربك أولاد آدم مِن أصلاب آبائهم، وقررهم بتوحيده بما أودعه في فطرهم من أنه ربهم وخالقهم ومليكهم، فأقروا له بذلك، خشية أن ينكروا يوم القيامة، فلا يقروا بشيء فيه، ويزعموا أن حجة الله ما قامت عليهم، ولا عندهم علم بها، بل كانوا عنها غافلين.", "isBasmala": false, "translation_en": "And when Your Lord summoned the descendants of Adam, and made them testify about themselves. \"Am I not your Lord?\" They said, \"Yes, we testify.\" Thus you cannot say on the Day of Resurrection, \"We were unaware of this.\"", "translation_id": "Dan (ingatlah), ketika Tuhanmu mengeluarkan keturunan anak-anak Adam dari sulbi mereka dan Allah mengambil kesaksian terhadap jiwa mereka (seraya berfirman): \"Bukankah Aku ini Tuhanmu?\" Mereka menjawab: \"Betul (Engkau Tuhan kami), kami menjadi saksi\". (Kami lakukan yang demikian itu) agar di hari kiamat kamu tidak mengatakan: \"Sesungguhnya kami (bani Adam) adalah orang-orang yang lengah terhadap ini (keesaan Tuhan)\",", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 173, "text": "أَوۡ تَقُولُوۤا۟ إِنَّمَاۤ أَشۡرَكَ ءَابَاۤؤُنَا مِن قَبۡلُ وَكُنَّا ذُرِّیَّةࣰ مِّنۢ بَعۡدِهِمۡۖ أَفَتُهۡلِكُنَا بِمَا فَعَلَ ٱلۡمُبۡطِلُونَ ۝١٧٣", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "أو لئلا تقولوا: إنما أشرك آباؤنا من قبلنا ونقضوا العهد، فاقتدينا بهم من بعدهم، أفتعذبنا بما فعل الذين أبطلوا أعمالهم بجعلهم مع الله شريكا في العبادة؟", "isBasmala": false, "translation_en": "Nor can you Say, \"Our ancestors practiced idolatry before; and we are their descendants who came after them; will you destroy us for what the falsifiers did?\"", "translation_id": "atau agar kamu tidak mengatakan: \"Sesungguhnya orang-orang tua kami telah mempersekutukan Tuhan sejak dahulu, sedang kami ini adalah anak-anak keturunan yang (datang) sesudah mereka. Maka apakah Engkau akan membinasakan kami karena perbuatan orang-orang yang sesat dahulu?\"", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 174, "text": "وَكَذَ ٰلِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ وَلَعَلَّهُمۡ یَرۡجِعُونَ ۝١٧٤", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "وكما فَصَّلْنا الآيات، وبيَّنَّا فيها ما فعلناه بالأمم السابقة، كذلك نفصِّل الآيات ونبيِّنها لقومك أيها الرسول؛ رجاء أن يرجعوا عن شركهم، وينيبوا إلى ربهم.", "isBasmala": false, "translation_en": "We thus elaborate the revelations, so that they may return.", "translation_id": "Dan demikianlah Kami menjelaskan ayat-ayat itu, agar mereka kembali (kepada kebenaran).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 175, "text": "وَٱتۡلُ عَلَیۡهِمۡ نَبَأَ ٱلَّذِیۤ ءَاتَیۡنَـٰهُ ءَایَـٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّیۡطَـٰنُ فَكَانَ مِنَ ٱلۡغَاوِینَ ۝١٧٥", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "واقصص -أيها الرسول- على أمتك خبر رجل من بني إسرائيل أعطيناه حججنا وأدلتنا، فتعلَّمها، ثم كفر بها، ونبذها وراء ظهره، فاستحوذ عليه الشيطان، فصار من الضالين الهالكين؛ بسبب مخالفته أمر ربه وطاعته الشيطان.", "isBasmala": false, "translation_en": "And relate to them the story of him to whom We delivered Our signs, but he detached himself from them, so Satan went after him, and he became one of the perverts.", "translation_id": "Dan bacakanlah kepada mereka berita orang yang telah Kami berikan kepadanya ayat-ayat Kami (pengetahuan tentang isi Al Kitab), kemudian dia melepaskan diri dari pada ayat-ayat itu, lalu dia diikuti oleh syaitan (sampai dia tergoda), maka jadilah dia termasuk orang-orang yang sesat.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 176, "text": "وَلَوۡ شِئۡنَا لَرَفَعۡنَـٰهُ بِهَا وَلَـٰكِنَّهُۥۤ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ فَمَثَلُهُۥ كَمَثَلِ ٱلۡكَلۡبِ إِن تَحۡمِلۡ عَلَیۡهِ یَلۡهَثۡ أَوۡ تَتۡرُكۡهُ یَلۡهَثۚ ذَّ ٰلِكَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۚ فَٱقۡصُصِ ٱلۡقَصَصَ لَعَلَّهُمۡ یَتَفَكَّرُونَ ۝١٧٦", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "ولو شئنا أن نرفع قدره بما آتيناه من الآيات لفعلنا، ولكنه رَكَنَ إلى الدنيا واتبع هواه، وآثر لَذَّاته وشهواته على الآخرة، وامتنع عن طاعة الله وخالف أمره. فَمَثَلُ هذا الرجل مثل الكلب، إن تطرده أو تتركه يُخْرج لسانه في الحالين لاهثًا، فكذلك الذي انسلخ من آيات الله يظل على كفره إن اجتهدْتَ في دعوتك له أو أهملته، هذا الوصف -أيها الرسول- وصف هؤلاء القوم الذين كانوا ضالين قبل أن تأتيهم بالهدى والرسالة، فاقصص -أيها الرسول- أخبار الأمم الماضية، ففي إخبارك بذلك أعظم معجزة، لعل قومك يتدبرون فيما جئتهم به فيؤمنوا لك.", "isBasmala": false, "translation_en": "Had We willed, We could have elevated him through them; but he clung to the ground, and followed his desires. His metaphor is that of a dog: if you chase it, it pants; and if you leave it alone, it pants. Such is the metaphor of the people who deny Our signs. So tell the tale, so that they may ponder.", "translation_id": "Dan kalau Kami menghendaki, sesungguhnya Kami tinggikan (derajat)nya dengan ayat-ayat itu, tetapi dia cenderung kepada dunia dan menurutkan hawa nafsunya yang rendah, maka perumpamaannya seperti anjing jika kamu menghalaunya diulurkannya lidahnya dan jika kamu membiarkannya dia mengulurkan lidahnya (juga). Demikian itulah perumpamaan orang-orang yang mendustakan ayat-ayat Kami. Maka ceritakanlah (kepada mereka) kisah-kisah itu agar mereka berfikir.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 177, "text": "سَاۤءَ مَثَلًا ٱلۡقَوۡمُ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا وَأَنفُسَهُمۡ كَانُوا۟ یَظۡلِمُونَ ۝١٧٧", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "قَبُحَ مثلا مثلُ القوم الذين كذَّبوا بحجج الله وأدلته، فجحدوها، وأنفسهم كانوا يظلمونها؛ بسبب تكذيبهم بهذه الحجج والأدلة.", "isBasmala": false, "translation_en": "Evil is the metaphor of the people who reject Our signs and wrong themselves.", "translation_id": "Amat buruklah perumpamaan orang-orang yang mendustakan ayat-ayat Kami dan kepada diri mereka sendirilah mereka berbuat zalim.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 178, "text": "مَن یَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِیۖ وَمَن یُضۡلِلۡ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ ۝١٧٨", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "من يوفقه الله للإيمان به وطاعته فهو الموفَّق، ومن يخذله فلم يوفقه فهو الخاسر الهالك، فالهداية والإضلال من الله وحده.", "isBasmala": false, "translation_en": "Whomever God guides is the guided one. And whomever He sends astray-these are the losers.", "translation_id": "Barangsiapa yang diberi petunjuk oleh Allah, maka dialah yang mendapat petunjuk; dan barangsiapa yang disesatkan Allah, maka merekalah orang-orang yang merugi.", "manzil": 2, "manzil_display": ""}], "174": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 179, "text": "وَلَقَدۡ ذَرَأۡنَا لِجَهَنَّمَ كَثِیرࣰا مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ لَهُمۡ قُلُوبࣱ لَّا یَفۡقَهُونَ بِهَا وَلَهُمۡ أَعۡیُنࣱ لَّا یُبۡصِرُونَ بِهَا وَلَهُمۡ ءَاذَانࣱ لَّا یَسۡمَعُونَ بِهَاۤۚ أُو۟لَـٰۤىِٕكَ كَٱلۡأَنۡعَـٰمِ بَلۡ هُمۡ أَضَلُّۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡغَـٰفِلُونَ ۝١٧٩", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "ولقد خلقنا للنار -التي يعذِّب الله فيها مَن يستحق العذاب في الآخرة - كثيرًا من الجن والإنس، لهم قلوب لا يعقلون بها، فلا يرجون ثوابًا ولا يخافون عقابًا، ولهم أعين لا ينظرون بها إلى آيات الله وأدلته، ولهم آذان لا يسمعون بها آيات كتاب الله فيتفكروا فيها، هؤلاء كالبهائم التي لا تَفْقَهُ ما يقال لها، ولا تفهم ما تبصره، ولا تعقل بقلوبها الخير والشر فتميز بينهما، بل هم أضل منها؛ لأن البهائم تبصر منافعها ومضارها وتتبع راعيها، وهم بخلاف ذلك، أولئك هم الغافلون عن الإيمان بالله وطاعته.", "isBasmala": false, "translation_en": "We have destined for Hell multitudes of jinn and humans. They have hearts with which they do not understand. They have eyes with which they do not see. They have ears with which they do not hear. These are like cattle. In fact, they are further astray. These are the heedless.", "translation_id": "Dan sesungguhnya Kami jadikan untuk (isi neraka Jahannam) kebanyakan dari jin dan manusia, mereka mempunyai hati, tetapi tidak dipergunakannya untuk memahami (ayat-ayat Allah) dan mereka mempunyai mata (tetapi) tidak dipergunakannya untuk melihat (tanda-tanda kekuasaan Allah), dan mereka mempunyai telinga (tetapi) tidak dipergunakannya untuk mendengar (ayat-ayat Allah). Mereka itu sebagai binatang ternak, bahkan mereka lebih sesat lagi. Mereka itulah orang-orang yang lalai.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 180, "text": "وَلِلَّهِ ٱلۡأَسۡمَاۤءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُوا۟ ٱلَّذِینَ یُلۡحِدُونَ فِیۤ أَسۡمَـٰۤىِٕهِۦۚ سَیُجۡزَوۡنَ مَا كَانُوا۟ یَعۡمَلُونَ ۝١٨٠", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "ولله سبحانه وتعالى الأسماء الحسنى، الدالة على كمال عظمته، وكل أسمائه حسن، فاطلبوا منه بأسمائه ما تريدون، واتركوا الذين يُغيِّرون في أسمائه بالزيادة أو النقصان أو التحريف، كأن يُسمَّى بها من لا يستحقها، كتسمية المشركين بها آلهتهم، أو أن يجعل لها معنى لم يُردْه الله ولا رسوله، فسوف يجزون جزاء أعمالهم السيئة التي كانوا يعملونها في الدنيا من الكفر بالله، والإلحاد في أسمائه وتكذيب رسوله.", "isBasmala": false, "translation_en": "To God belong the Most Beautiful Names, so call Him by them, and disregard those who blaspheme His names. They will be repaid for what they used to do.", "translation_id": "Hanya milik Allah asmaa-ul husna, maka bermohonlah kepada-Nya dengan menyebut asmaa-ul husna itu dan tinggalkanlah orang-orang yang menyimpang dari kebenaran dalam (menyebut) nama-nama-Nya. Nanti mereka akan mendapat balasan terhadap apa yang telah mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 181, "text": "وَمِمَّنۡ خَلَقۡنَاۤ أُمَّةࣱ یَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ یَعۡدِلُونَ ۝١٨١", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "ومن الذين خَلَقْنا جماعة فاضلة يهتدون بالحق ويَدْعون إليه، وبه يقضون وينصفون الناس، وهم أئمة الهدى ممن أنعم الله عليهم بالإيمان والعمل الصالح.", "isBasmala": false, "translation_en": "Among those We created is a community-they guide by truth, and do justice thereby.", "translation_id": "Dan di antara orang-orang yang Kami ciptakan ada umat yang memberi petunjuk dengan hak, dan dengan yang hak itu (pula) mereka menjalankan keadilan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 182, "text": "وَٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا سَنَسۡتَدۡرِجُهُم مِّنۡ حَیۡثُ لَا یَعۡلَمُونَ ۝١٨٢", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "والذين كذَّبوا بآياتنا، فجحدوها، ولم يتذكروا بها، سنفتح لهم أبواب الرزق ووجوه المعاش في الدنيا، استدراجًا لهم حتى يغتروا بما هم فيه ويعتقدوا أنهم على شيء، ثم نعاقبهم على غِرَّة من حيث لا يعلمون. وهذه عقوبة من الله على التكذيب بحجج الله وآياته.", "isBasmala": false, "translation_en": "As for those who reject Our messages, We will gradually lead them from where they do not know.", "translation_id": "Dan orang-orang yang mendustakan ayat-ayat Kami, nanti Kami akan menarik mereka dengan berangaur-angsur (ke arah kebinasaan), dengan cara yang tidak mereka ketahui.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 183, "text": "وَأُمۡلِی لَهُمۡۚ إِنَّ كَیۡدِی مَتِینٌ ۝١٨٣", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "وأمهل هؤلاء الذين كذبوا بآياتنا حتى يظنوا أنهم لا يعاقبون، فيزدادوا كفرًا وطغيانًا، وبذلك يتضاعف لهم العذاب. إن كيدي متين، أي: قوي شديد لا يُدْفع بقوة ولا بحيلة.", "isBasmala": false, "translation_en": "And I will encourage them. My plan is firm.", "translation_id": "Dan Aku memberi tangguh kepada mereka. Sesungguhnya rencana-Ku amat teguh.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 184, "text": "أَوَ لَمۡ یَتَفَكَّرُوا۟ۗ مَا بِصَاحِبِهِم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِیرࣱ مُّبِینٌ ۝١٨٤", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "أولم يتفكر هؤلاء الذين كذبوا بآياتنا فيتدبروا بعقولهم، ويعلموا أنه ليس بمحمد جنون؟ ما هو إلا نذير لهم من عقاب الله على كفرهم به إن لم يؤمنوا، ناصح مبين.", "isBasmala": false, "translation_en": "Do they not think? There is no madness in their friend. He is but a plain warner.", "translation_id": "Apakah (mereka lalai) dan tidak memikirkan bahwa teman mereka (Muhammad) tidak berpenyakit gila. Dia (Muhammad itu) tidak lain hanyalah seorang pemberi peringatan lagi pemberi penjelasan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 185, "text": "أَوَ لَمۡ یَنظُرُوا۟ فِی مَلَكُوتِ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا خَلَقَ ٱللَّهُ مِن شَیۡءࣲ وَأَنۡ عَسَىٰۤ أَن یَكُونَ قَدِ ٱقۡتَرَبَ أَجَلُهُمۡۖ فَبِأَیِّ حَدِیثِۭ بَعۡدَهُۥ یُؤۡمِنُونَ ۝١٨٥", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "أولم ينظر هؤلاء المكذبون بآيات الله في ملك الله العظيم وسلطانه القاهر في السموات والأرض، وما خلق الله -جلَّ ثناؤه- من شيء فيهما، فيتدبروا ذلك ويعتبروا به، وينظروا في آجالهم التي عست أن تكون قَرُبَتْ فيهلكوا على كفرهم، ويصيروا إلى عذاب الله وأليم عقابه؟ فبأي تخويف وتحذير بعد تحذير القرآن يصدقون ويعملون؟", "isBasmala": false, "translation_en": "Have they not observed the government of the heavens and the earth, and all the things that God created, and that their time may have drawn near? Which message, besides this, will they believe in?", "translation_id": "Dan apakah mereka tidak memperhatikan kerajaan langit dan bumi dan segala sesuatu yang diciptakan Allah, dan kemungkinan telah dekatnya kebinasaan mereka? Maka kepada berita manakah lagi mereka akan beriman sesudah Al Quran itu?", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 186, "text": "مَن یُضۡلِلِ ٱللَّهُ فَلَا هَادِیَ لَهُۥۚ وَیَذَرُهُمۡ فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ ۝١٨٦", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "مَن يضلله الله عن طريق الرشاد فلا هادي له، ويتركُهم في كفرهم يتحيرون ويترددون.", "isBasmala": false, "translation_en": "Whomever God misguides has no guide. And He leaves them blundering in their transgression.", "translation_id": "Barangsiapa yang Allah sesatkan, maka baginya tak ada orang yang akan memberi petunjuk. Dan Allah membiarkan mereka terombang-ambing dalam kesesatan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 187, "text": "یَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَیَّانَ مُرۡسَىٰهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ رَبِّیۖ لَا یُجَلِّیهَا لِوَقۡتِهَاۤ إِلَّا هُوَۚ ثَقُلَتۡ فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ لَا تَأۡتِیكُمۡ إِلَّا بَغۡتَةࣰۗ یَسۡـَٔلُونَكَ كَأَنَّكَ حَفِیٌّ عَنۡهَاۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝١٨٧", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "يسألك -أيها الرسول- كفار \"مكة\" عن الساعة متى قيامها؟ قل لهم: عِلْمُ قيامها عند الله لا يظهرها إلا هو، ثَقُلَ علمها، وخفي على أهل السموات والأرض، فلا يعلم وقت قيامها ملَك مقرَّب ولا نبي مرسل، لا تجيء الساعة إلا فجأة، يسألك هؤلاء القوم عنها كأنك حريص على العلم بها، مستقص بالسؤال عنها، قل لهم: إنما علمها عند الله الذي يعلم غيب السموات والأرض، ولكنَّ أكثر الناس لا يعلمون أن ذلك لا يعلمه إلا الله.", "isBasmala": false, "translation_en": "They ask you about the Hour, \"When will it come?\" Say, \"Knowledge of it rests with my Lord. None can reveal its coming except He. It weighs heavily on the heavens and the earth. It will not come upon you except suddenly.\" They ask you as if you are responsible for it. Say, \"Knowledge of it rests with God,\" but most people do not know.", "translation_id": "Mereka menanyakan kepadamu tentang kiamat: \"Bilakah terjadinya?\" Katakanlah: \"Sesungguhnya pengetahuan tentang kiamat itu adalah pada sisi Tuhanku; tidak seorangpun yang dapat menjelaskan waktu kedatangannya selain Dia. Kiamat itu amat berat (huru haranya bagi makhluk) yang di langit dan di bumi. Kiamat itu tidak akan datang kepadamu melainkan dengan tiba-tiba\". Mereka bertanya kepadamu seakan-akan kamu benar-benar mengetahuinya. Katakanlah: \"Sesungguhnya pengetahuan tentang bari kiamat itu adalah di sisi Allah, tetapi kebanyakan manusia tidak mengetahui\".", "manzil": 2, "manzil_display": ""}], "175": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 188, "text": "قُل لَّاۤ أَمۡلِكُ لِنَفۡسِی نَفۡعࣰا وَلَا ضَرًّا إِلَّا مَا شَاۤءَ ٱللَّهُۚ وَلَوۡ كُنتُ أَعۡلَمُ ٱلۡغَیۡبَ لَٱسۡتَكۡثَرۡتُ مِنَ ٱلۡخَیۡرِ وَمَا مَسَّنِیَ ٱلسُّوۤءُۚ إِنۡ أَنَا۠ إِلَّا نَذِیرࣱ وَبَشِیرࣱ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝١٨٨", "juz": 9, "hizb": "(* ح 18*)", "tafsir": "قل -أيها الرسول-: لا أقدرُ على جَلْبِ خير لنفسي ولا دفع شر يحل بها إلا ما شاء الله، ولو كنت أعلم الغيب لفعلت الأسباب التي أعلم أنها تكثِّر لي المصالح والمنافع، ولاتَّقيتُ ما يكون من الشر قبل أن يقع، ما أنا إلا رسول الله أرسلني إليكم، أخوِّف من عقابه، وأبشر بثوابه قومًا يصدقون بأني رسول الله، ويعملون بشرعه.", "isBasmala": false, "translation_en": "Say, \"I have no control over any benefit or harm to myself, except as God wills. Had I known the future, I would have acquired much good, and no harm would have touched me. I am only a warner, and a herald of good news to a people who believe.\"", "translation_id": "Katakanlah: \"Aku tidak berkuasa menarik kemanfaatan bagi diriku dan tidak (pula) menolak kemudharatan kecuali yang dikehendaki Allah. Dan sekiranya aku mengetahui yang ghaib, tentulah aku membuat kebajikan sebanyak-banyaknya dan aku tidak akan ditimpa kemudharatan. Aku tidak lain hanyalah pemberi peringatan, dan pembawa berita gembira bagi orang-orang yang beriman\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 189, "text": "۞ هُوَ ٱلَّذِی خَلَقَكُم مِّن نَّفۡسࣲ وَ ٰحِدَةࣲ وَجَعَلَ مِنۡهَا زَوۡجَهَا لِیَسۡكُنَ إِلَیۡهَاۖ فَلَمَّا تَغَشَّىٰهَا حَمَلَتۡ حَمۡلًا خَفِیفࣰا فَمَرَّتۡ بِهِۦۖ فَلَمَّاۤ أَثۡقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَىِٕنۡ ءَاتَیۡتَنَا صَـٰلِحࣰا لَّنَكُونَنَّ مِنَ ٱلشَّـٰكِرِینَ ۝١٨٩", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "هو الذي خلقكم -أيها الناس- من نفس واحدة، وهي آدم عليه السلام وخَلَق منها زوجها، وهي حواء؛ ليأنس بها ويطمئن، فلما جامعها -والمراد جنس الزوجين من ذرية آدم- حملت ماءً خفيفًا، فقامت به وقعدت وأتمت الحمل، فلما قَرُبت ولادتها وأثقلت دعا الزوجان ربهما: لئن أعطيتنا بشرًا سويًا صالحًا لنكونن ممن يشكرك على ما وهبت لنا من الولد الصالح.", "isBasmala": false, "translation_en": "It is He who created you from a single person, and made from it its mate, that he may find comfort with her. Then, when he has covered her, she conceives a light load, and she carries it around. But when she has grown heavy, they pray to God their Lord, \"if You give us a good child, we will be among the thankful.\"", "translation_id": "Dialah Yang menciptakan kamu dari diri yang satu dan dari padanya Dia menciptakan isterinya, agar dia merasa senang kepadanya. Maka setelah dicampurinya, isterinya itu mengandung kandungan yang ringan, dan teruslah dia merasa ringan (beberapa waktu). Kemudian tatkala dia merasa berat, keduanya (suami-isteri) bermohon kepada Allah, Tuhannya seraya berkata: \"Sesungguhnya jika Engkau memberi kami anak yang saleh, tentulah kami termasuk orang-orang yang bersyukur\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 190, "text": "فَلَمَّاۤ ءَاتَىٰهُمَا صَـٰلِحࣰا جَعَلَا لَهُۥ شُرَكَاۤءَ فِیمَاۤ ءَاتَىٰهُمَاۚ فَتَعَـٰلَى ٱللَّهُ عَمَّا یُشۡرِكُونَ ۝١٩٠", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "فلما رزق الله الزوجين ولدًا صالحًا، جعلا لله شركاء في ذلك الولد الذي انفرد الله بخلقه فعبَّداه لغير الله، فتعالى الله وتنزه عن كل شرك.", "isBasmala": false, "translation_en": "But when He has given them a good child, they attribute partners to Him in what He has given them. God is exalted above what they associate.", "translation_id": "Tatkala Allah memberi kepada keduanya seorang anak yang sempurna, maka keduanya menjadikan sekutu bagi Allah terhadap anak yang telah dianugerahkan-Nya kepada keduanya itu. Maka Maha Tinggi Allah dari apa yang mereka persekutukan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 191, "text": "أَیُشۡرِكُونَ مَا لَا یَخۡلُقُ شَیۡـࣰٔا وَهُمۡ یُخۡلَقُونَ ۝١٩١", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "أيشرك هؤلاء المشركون في عبادة الله مخلوقاته، وهي لا تقدر على خَلْق شيء، بل هي مخلوقة؟", "isBasmala": false, "translation_en": "Do they idolize those who create nothing, and are themselves created?", "translation_id": "Apakah mereka mempersekutukan (Allah dengan) berhada-berhala yang tak dapat menciptakan sesuatupun? Sedangkan berhala-berhala itu sendiri buatan orang.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 192, "text": "وَلَا یَسۡتَطِیعُونَ لَهُمۡ نَصۡرࣰا وَلَاۤ أَنفُسَهُمۡ یَنصُرُونَ ۝١٩٢", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "ولا تستطيع أن تنصر عابديها أو تدفع عن نفسها سوءًا، فإذا كانت لا تخلق شيئًا، بل هي مخلوقة، ولا تستطيع أن تدفع المكروه عمن يعبدها، ولا عن نفسها، فكيف تُتَّخذ مع الله آلهة؟ إنْ هذا إلا أظلم الظلم وأسفه السَّفَه.", "isBasmala": false, "translation_en": "And can neither help them, nor help their own selves?", "translation_id": "Dan berhala-berhala itu tidak mampu memberi pertolongan kepada penyembah-penyembahnya dan kepada dirinya sendiripun berhala-berha]a itu tidak dapat memberi pertolongan.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 193, "text": "وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا یَتَّبِعُوكُمۡۚ سَوَاۤءٌ عَلَیۡكُمۡ أَدَعَوۡتُمُوهُمۡ أَمۡ أَنتُمۡ صَـٰمِتُونَ ۝١٩٣", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "وإن تدعوا -أيها المشركون- هذه الأصنام التي عبدتموها من دون الله إلى الهدى، لا تسمع دعاءكم ولا تتبعكم؛ يستوي دعاؤكم لها وسكوتكم عنها؛ لأنها لا تسمع ولا تبصر ولا تَهدِي ولا تُهدى.", "isBasmala": false, "translation_en": "And if you invite them to guidance, they will not follow you. It is the same for you, whether you invite them, or remain silent.", "translation_id": "Dan jika kamu (hai orang-orang musyrik) menyerunya (berhala) untuk memberi petunjuk kepadamu, tidaklah berhala-berhala itu dapat memperkenankan seruanmu; sama saja (hasilnya) buat kamu menyeru mereka ataupun kamu herdiam diri.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 194, "text": "إِنَّ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمۡثَالُكُمۡۖ فَٱدۡعُوهُمۡ فَلۡیَسۡتَجِیبُوا۟ لَكُمۡ إِن كُنتُمۡ صَـٰدِقِینَ ۝١٩٤", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "إن الذين تعبدون من غير الله -أيها المشركون- هم مملوكون لربهم كما أنكم مملوكون لربكم، فإن كنتم كما تزعمون صادقين في أنها تستحق من العبادة شيئًا فادعوهم فليستجيبوا لكم، فإن استجابوا لكم وحصَّلوا مطلوبكم، وإلا تبين أنكم كاذبون مفترون على الله أعظم الفرية.", "isBasmala": false, "translation_en": "Those you call upon besides God are servants like you. So call upon them, and let them answer you, if you are truthful.", "translation_id": "Sesungguhnya berhala-berhala yang kamu seru selain Allah itu adalah makhluk (yang lemah) yang serupa juga dengan kamu. Maka serulah berhala-berhala itu lalu biarkanlah mereka mmperkenankan permintaanmu, jika kamu memang orang-orang yang benar.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 195, "text": "أَلَهُمۡ أَرۡجُلࣱ یَمۡشُونَ بِهَاۤۖ أَمۡ لَهُمۡ أَیۡدࣲ یَبۡطِشُونَ بِهَاۤۖ أَمۡ لَهُمۡ أَعۡیُنࣱ یُبۡصِرُونَ بِهَاۤۖ أَمۡ لَهُمۡ ءَاذَانࣱ یَسۡمَعُونَ بِهَاۗ قُلِ ٱدۡعُوا۟ شُرَكَاۤءَكُمۡ ثُمَّ كِیدُونِ فَلَا تُنظِرُونِ ۝١٩٥", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "ألهذه الآلهة والأصنام أرجل يسعَوْن بها معكم في حوائجكم؟ أم لهم أيدٍ يدفعون بها عنكم وينصرونكم على من يريد بكم شرًا ومكروهًا؟ أم لهم أعين ينظرون بها فيعرِّفونكم ما عاينوا وأبصروا مما يغيب عنكم فلا ترونه؟ أم لهم آذان يسمعون بها فيخبرونكم بما لم تسمعوه؟ فإذا كانت آلهتكم التي تعبدونها ليس فيها شيء من هذه الآلات، فما وجه عبادتكم إياها، وهي خالية من هذه الأشياء التي بها يتوصل إلى جلب النفع أو دفع الضر؟ قل -أيها الرسول- لهؤلاء المشركين من عبدة الأوثان: ادعوا آلهتكم الذين جعلتموهم لله شركاء في العبادة، ثم اجتمعوا على إيقاع السوء والمكروه بي، فلا تؤخروني وعجِّلوا بذلك، فإني لا أبالي بآلهتكم؛ لاعتمادي على حفظ الله وحده.", "isBasmala": false, "translation_en": "Do they have feet with which they walk? Or do they have hands with which they strike? Or do they have eyes with which they see? Or do they have ears with which they hear? Say, \"Call upon your partners, then plot against me, and do not wait.\"", "translation_id": "Apakah berhala-berhala mempunyai kaki yang dengan itu ia dapat berjalan, atau mempunyai tangan yang dengan itu ia dapat memegang dengan keras, atau mempunyai mata yang dengan itu ia dapat melihat, atau mempunyai telinga yang dengan itu ia dapat mendengar? Katakanlah: \"Panggillah berhala-berhalamu yang kamu jadikan sekutu Allah, kemudian lakukanlah tipu daya (untuk mencelakakan)-ku. tanpa memberi tangguh (kepada-ku)\".", "manzil": 2, "manzil_display": ""}], "176": [{"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 196, "text": "إِنَّ وَلِـِّۧیَ ٱللَّهُ ٱلَّذِی نَزَّلَ ٱلۡكِتَـٰبَۖ وَهُوَ یَتَوَلَّى ٱلصَّـٰلِحِینَ ۝١٩٦", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "إن وليِّيَ الله، الذي يتولى حفظي ونصري، هو الذي نزَّل عليَّ القرآن بالحق، وهو يتولى الصالحين مِن عباده، وينصرهم على أعدائهم ولا يخذلهم.", "isBasmala": false, "translation_en": "\"My Master is God, He Who sent down the Book, and He takes care of the righteous.\"", "translation_id": "Sesungguhnya pelindungku ialahlah Yang telah menurunkan Al Kitab (Al Quran) dan Dia melindungi orang-orang yang saleh.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 197, "text": "وَٱلَّذِینَ تَدۡعُونَ مِن دُونِهِۦ لَا یَسۡتَطِیعُونَ نَصۡرَكُمۡ وَلَاۤ أَنفُسَهُمۡ یَنصُرُونَ ۝١٩٧", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "والذين تدعون -أنتم أيها المشركون- مِن غير الله من الآلهة لا يستطيعون نصركم، ولا يقدرون على نصرة أنفسهم.", "isBasmala": false, "translation_en": "Those you call upon besides Him cannot help you, nor can they help themselves.", "translation_id": "Dan berhala-berhala yang kamu seru selain Allah tidaklah sanggup menolongmu, bahkan tidak dapat menolong dirinya sendiri.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 198, "text": "وَإِن تَدۡعُوهُمۡ إِلَى ٱلۡهُدَىٰ لَا یَسۡمَعُوا۟ۖ وَتَرَىٰهُمۡ یَنظُرُونَ إِلَیۡكَ وَهُمۡ لَا یُبۡصِرُونَ ۝١٩٨", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "وإن تدعوا -أيها المشركون- آلهتكم إلى الاستقامة والسداد لا يسمعوا دعاءكم، وترى -أيها الرسول- آلهة هؤلاء المشركين مِن عبدة الأوثان يقابلونك كالناظر إليك وهم لا يبصرون؛ لأنهم لا أبصار لهم ولا بصائر.", "isBasmala": false, "translation_en": "And if you call them to guidance, they will not hear. And you see them looking at you, yet they do not see.", "translation_id": "Dan jika kamu sekalian menyeru (berhala-berhala) untuk memberi petunjuk, niscaya berhala-herhala itu tidak dapat mendengarnya. Dan kamu melihat berhala-berhala itu memandang kepadamu padahal ia tidak melihat.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 199, "text": "خُذِ ٱلۡعَفۡوَ وَأۡمُرۡ بِٱلۡعُرۡفِ وَأَعۡرِضۡ عَنِ ٱلۡجَـٰهِلِینَ ۝١٩٩", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "اقْبَلْ -أيها النبي أنت وأمتك- الفضل من أخلاق الناس وأعمالهم، ولا تطلب منهم ما يشق عليهم حتى لا ينفروا، وأْمر بكل قول حسن وفِعْلٍ جميل، وأعرض عن منازعة السفهاء ومساواة الجهلة الأغبياء.", "isBasmala": false, "translation_en": "Be tolerant, and command decency, and avoid the ignorant.", "translation_id": "Jadilah engkau pemaaf dan suruhlah orang mengerjakan yang ma'ruf, serta berpalinglah dari pada orang-orang yang bodoh.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 200, "text": "وَإِمَّا یَنزَغَنَّكَ مِنَ ٱلشَّیۡطَـٰنِ نَزۡغࣱ فَٱسۡتَعِذۡ بِٱللَّهِۚ إِنَّهُۥ سَمِیعٌ عَلِیمٌ ۝٢٠٠", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "وإما يصيبنَّك -أيها النبي- من الشيطان غضب أو تُحِس منه بوسوسة وتثبيط عن الخير أو حث على الشرِّ، فالجأ إلى الله مستعيذًا به، إنه سميع لكل قول، عليم بكل فعل.", "isBasmala": false, "translation_en": "And when a suggestion from Satan assails you, take refuge with God. He is Hearing and Knowing.", "translation_id": "Dan jika kamu ditimpa sesuatu godaan syaitan maka berlindunglah kepada Allah", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 201, "text": "إِنَّ ٱلَّذِینَ ٱتَّقَوۡا۟ إِذَا مَسَّهُمۡ طَـٰۤىِٕفࣱ مِّنَ ٱلشَّیۡطَـٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبۡصِرُونَ ۝٢٠١", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "إن الذين اتقوا الله مِن خلقه، فخافوا عقابه بأداء فرائضه واجتناب نواهيه، إذا أصابهم عارض من وسوسة الشيطان تذكَّروا ما أوجب الله عليهم من طاعته، والتوبة إليه، فإذا هم منتهون عن معصية الله على بصيرة، آخذون بأمر الله، عاصون للشيطان.", "isBasmala": false, "translation_en": "Those who are righteous-when an impulse from Satan strikes them, they remind themselves, and immediately see clearly.", "translation_id": "Sesungguhnya orang-orang yang bertakwa bila mereka ditimpa was-was dari syaitan, mereka ingat kepada Allah, maka ketika itu juga mereka melihat kesalahan-kesalahannya.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 202, "text": "وَإِخۡوَ ٰنُهُمۡ یَمُدُّونَهُمۡ فِی ٱلۡغَیِّ ثُمَّ لَا یُقۡصِرُونَ ۝٢٠٢", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "وإخوان الشياطين، وهم الفجَّار من ضلال الإنس تمدهم الشياطين من الجن في الضلالة والغَواية، ولا تدَّخر شياطين الجن وُسْعًا في مدِّهم شياطين الإنس في الغيِّ، ولا تدَّخر شياطين الإنس وُسْعًا في عمل ما توحي به شياطين الجن.", "isBasmala": false, "translation_en": "But their brethren lead them relentlessly into error, and they never stop short.", "translation_id": "Dan teman-teman mereka (orang-orang kafir dan fasik) membantu syaitan-syaitan dalam menyesatkan dan mereka tidak henti-hentinya (menyesatkan).", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 203, "text": "وَإِذَا لَمۡ تَأۡتِهِم بِـَٔایَةࣲ قَالُوا۟ لَوۡلَا ٱجۡتَبَیۡتَهَاۚ قُلۡ إِنَّمَاۤ أَتَّبِعُ مَا یُوحَىٰۤ إِلَیَّ مِن رَّبِّیۚ هَـٰذَا بَصَاۤىِٕرُ مِن رَّبِّكُمۡ وَهُدࣰى وَرَحۡمَةࣱ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝٢٠٣", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "وإذا لم تجئ -أيها الرسول- هؤلاء المشركين بآية قالوا: هلا أحدَثْتها واختلقتها من عند نفسك، قل لهم -أيها الرسول-: إن هذا ليس لي، ولا يجوز لي فِعْله؛ لأن الله إنما أمرني باتباع ما يوحى إليَّ من عنده، وهو هذا القرآن الذي أتلوه عليكم حججًا وبراهين من ربكم، وبيانًا يهدي المؤمنين إلى الطريق المستقيم، ورحمة يرحم الله بها عباده المؤمنين.", "isBasmala": false, "translation_en": "If you do not produce a miracle for them, they say, \"Why don't you improvise one.\" Say, \"I only follow what is inspired to me from my Lord.\" These are insights from your Lord, and guidance, and mercy, for a people who believe.", "translation_id": "Dan apabila kamu tidak membawa suatu ayat Al Quran kepada mereka, mereka berkata: \"Mengapa tidak kamu buat sendiri ayat itu?\" Katakanlah: \"Sesungguhnya aku hanya mengikut apa yang diwahyukan dari Tuhanku kepadaku. Al Quran ini adalah bukti-bukti yang nyata dari Tuhanmu, petunjuk dan rahmat bagi orang-orang yang beriman\".", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 204, "text": "وَإِذَا قُرِئَ ٱلۡقُرۡءَانُ فَٱسۡتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمۡ تُرۡحَمُونَ ۝٢٠٤", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "وإذا قرئ القرآن فاستمعوا له أيها الناس وأنصتوا، لتعقلوه رجاء أن يرحمكم الله به.", "isBasmala": false, "translation_en": "When the Quran is recited, listen to it, and pay attention, so that you may experience mercy.", "translation_id": "Dan apabila dibacakan Al Quran, maka dengarkanlah baik-baik, dan perhatikanlah dengan tenang agar kamu mendapat rahmat.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 205, "text": "وَٱذۡكُر رَّبَّكَ فِی نَفۡسِكَ تَضَرُّعࣰا وَخِیفَةࣰ وَدُونَ ٱلۡجَهۡرِ مِنَ ٱلۡقَوۡلِ بِٱلۡغُدُوِّ وَٱلۡـَٔاصَالِ وَلَا تَكُن مِّنَ ٱلۡغَـٰفِلِینَ ۝٢٠٥", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "واذكر -أيها الرسول- ربك في نفسك تخشعًا وتواضعًا لله خائفًا وجل القلب منه، وادعه متوسطًا بين الجهر والمخافتة في أول النهار وآخره، ولا تكن من الذين يَغْفُلون عن ذكر الله، ويلهون عنه في سائر أوقاتهم.", "isBasmala": false, "translation_en": "And remember your Lord within yourself, humbly and fearfully, and quietly, in the morning and the evening, and do not be of the neglectful.", "translation_id": "Dan sebutlah (nama) Tuhanmu dalam hatimu dengan merendahkan diri dan rasa takut, dan dengan tidak mengeraskan suara, di waktu pagi dan petang, dan janganlah kamu termasuk orang-orang yang lalai.", "manzil": 2, "manzil_display": ""}, {"sura": 7, "sura_name": "الأعراف", "revelation": "Makkiyah", "aya": 206, "text": "إِنَّ ٱلَّذِینَ عِندَ رَبِّكَ لَا یَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَیُسَبِّحُونَهُۥ وَلَهُۥ یَ̅سۡ̅جُ̅دُ̅و̅نَ̅ ۝٢٠٦ ۩", "juz": 9, "hizb": "(*¼ ح 18*)", "tafsir": "إن الذين عند ربك من الملائكة لا يستكبرون عن عبادة الله، بل ينقادون لأوامره، ويسبحونه بالليل والنهار، وينزهونه عما لا يليق به، وله وحده لا شريك له يسجدون.", "isBasmala": false, "translation_en": "Those who are in the presence of your Lord are not too proud to worship Him. They recite His praises, and to Him they bow down.", "translation_id": "Sesungguhnya malaikat-malaikat yang ada di sisi Tuhanmu tidaklah merasa enggan menyembah Allah dan mereka mentasbihkan-Nya dan hanya kepada-Nya-lah mereka bersujud.", "manzil": 2, "manzil_display": ""}], "177": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 10, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 1, "text": "۞ یَسۡـَٔلُونَكَ عَنِ ٱلۡأَنفَالِۖ قُلِ ٱلۡأَنفَالُ لِلَّهِ وَٱلرَّسُولِۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَصۡلِحُوا۟ ذَاتَ بَیۡنِكُمۡۖ وَأَطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥۤ إِن كُنتُم مُّؤۡمِنِینَ ۝١", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "يسألك أصحابك -أيها النبي- عن الغنائم يوم \"بدر\" كيف تقسمها بينهم؟ قل لهم: إنَّ أمرها إلى الله ورسوله، فالرسول يتولى قسمتها بأمر ربه، فاتقوا عقاب الله ولا تُقَدموا على معصيته، واتركوا المنازعة والمخاصمة بسبب هذه الأموال، وأصلحوا الحال بينكم، والتزموا طاعة الله ورسوله إن كنتم مؤمنين؛ فإن الإيمان يدعو إلى طاعة الله ورسوله.", "isBasmala": false, "translation_en": "They ask you about the bounties. Say, \"The bounties are for God and the Messenger.\" So be mindful of God, and settle your differences, and obey God and His Messenger, if you are believers.", "translation_id": "Mereka menanyakan kepadamu tentang (pembagian) harta rampasan perang. Katakanlah: \"Harta rampasan perang kepunyaan Allah dan Rasul, oleh sebab itu bertakwalah kepada Allah dan perbaikilah perhubungan di antara sesamamu; dan taatlah kepada Allah dan Rasul-Nya jika kamu adalah orang-orang yang beriman\".", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 2, "text": "إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِینَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَإِذَا تُلِیَتۡ عَلَیۡهِمۡ ءَایَـٰتُهُۥ زَادَتۡهُمۡ إِیمَـٰنࣰا وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ ۝٢", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "إنما المؤمنون بالله حقًا هم الذين إذا ذُكِر الله فزعت قلوبهم، وإذا تليت عليهم آيات القرآن زادتهم إيمانًا مع إيمانهم، لتدبرهم لمعانيه وعلى الله تعالى يتوكلون، فلا يرجون غيره، ولا يرهبون سواه.", "isBasmala": false, "translation_en": "The believers are those whose hearts tremble when God is mentioned, and when His revelations are recited to them, they strengthen them in faith, and upon their Lord they rely.", "translation_id": "Sesungguhnya orang-orang yang beriman ialah mereka yang bila disebut nama Allah gemetarlah hati mereka, dan apabila dibacakan ayat-ayat-Nya bertambahlah iman mereka (karenanya), dan hanya kepada Tuhanlah mereka bertawakkal.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 3, "text": "ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ ۝٣", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "الذين يداومون على أداء الصلوات المفروضة في أوقاتها، ومما رزقناهم من الأموال ينفقون فيما أمرناهم به.", "isBasmala": false, "translation_en": "Those who perform the prayer; and from Our provisions to them, they spend.", "translation_id": "(yaitu) orang-orang yang mendirikan shalat dan yang menafkahkan sebagian dari rezeki yang Kami berikan kepada mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 4, "text": "أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقࣰّاۚ لَّهُمۡ دَرَجَـٰتٌ عِندَ رَبِّهِمۡ وَمَغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ ۝٤", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "هؤلاء الذين يفعلون هذه الأفعال هم المؤمنون حقًا ظاهرًا وباطنًا بما أنزل الله عليهم، لهم منازل عالية عند الله، وعفو عن ذنوبهم، ورزق كريم، وهو الجنة.", "isBasmala": false, "translation_en": "These are the true believers. They have high standing with their Lord, and forgiveness, and a generous provision.", "translation_id": "Itulah orang-orang yang beriman dengan sebenar-benarnya. Mereka akan memperoleh beberapa derajat ketinggian di sisi Tuhannya dan ampunan serta rezeki (nikmat) yang mulia.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 5, "text": "كَمَاۤ أَخۡرَجَكَ رَبُّكَ مِنۢ بَیۡتِكَ بِٱلۡحَقِّ وَإِنَّ فَرِیقࣰا مِّنَ ٱلۡمُؤۡمِنِینَ لَكَـٰرِهُونَ ۝٥", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "كما أنكم لما اختلفتم في المغانم فانتزعها الله منكم، وجعلها إلى قَسْمه وقَسْم رسوله صلى الله عليه وسلم، كذلك أمرك ربك -أيها النبي- بالخروج من \"المدينة\" للقاء عِيْر قريش، وذلك بالوحي الذي أتاك به جبريل مع كراهة فريق من المؤمنين للخروج.", "isBasmala": false, "translation_en": "Even as your Lord brought you out of your home with the truth, some believers were reluctant.", "translation_id": "Sebagaimana Tuhanmu menyuruhmu pergi dan rumahmu dengan kebenaran, padahal sesungguhnya sebagian dari orang-orang yang beriman itu tidak menyukainya,", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 6, "text": "یُجَـٰدِلُونَكَ فِی ٱلۡحَقِّ بَعۡدَ مَا تَبَیَّنَ كَأَنَّمَا یُسَاقُونَ إِلَى ٱلۡمَوۡتِ وَهُمۡ یَنظُرُونَ ۝٦", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "يجادلك -أيها النبي- فريق من المؤمنين في القتال مِن بعد ما تبيَّن لهم أن ذلك واقع، كأنهم يساقون إلى الموت، وهم ينظرون إليه عِيانًا.", "isBasmala": false, "translation_en": "Arguing with you about the truth after it was made clear, as if they were being driven to death as they looked on.", "translation_id": "mereka membantahmu tentang kebenaran sesudah nyata (bahwa mereka pasti menang), seolah-olah mereka dihalau kepada kematian, sedang mereka melihat (sebab-sebab kematian itu).", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 7, "text": "وَإِذۡ یَعِدُكُمُ ٱللَّهُ إِحۡدَى ٱلطَّاۤىِٕفَتَیۡنِ أَنَّهَا لَكُمۡ وَتَوَدُّونَ أَنَّ غَیۡرَ ذَاتِ ٱلشَّوۡكَةِ تَكُونُ لَكُمۡ وَیُرِیدُ ٱللَّهُ أَن یُحِقَّ ٱلۡحَقَّ بِكَلِمَـٰتِهِۦ وَیَقۡطَعَ دَابِرَ ٱلۡكَـٰفِرِینَ ۝٧", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "واذكروا -أيها المجادلون- وَعْدَ الله لكم بالظَّفْر بإحدى الطائفتين: العير وما تحمله مِن أرزاق، أو النفير، وهو قتال الأعداء والانتصار عليهم، وأنتم تحبون الظَّفْر بالعير دون القتال، ويريد الله أن يحق الإسلام، ويُعْليه بأمره إياكم بقتال الكفار، ويستأصل الكافرين بالهلاك.", "isBasmala": false, "translation_en": "God has promised you one of the two groups-that it would be yours-but you wanted the unarmed group to be yours. God intends to prove the truth with His words, and to uproot the disbelievers.", "translation_id": "Dan (ingatlah), ketika Allah menjanjikan kepadamu bahwa salah satu dari dua golongan (yang kamu hadapi) adalah untukmu, sedang kamu menginginkan bahwa yang tidak mempunyai kekekuatan senjatalah yang untukmu, dan Allah menghendaki untuk membenarkan yang benar dengan ayat-ayat-Nya dan memusnahkan orang-orang kafir,", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 8, "text": "لِیُحِقَّ ٱلۡحَقَّ وَیُبۡطِلَ ٱلۡبَـٰطِلَ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ ۝٨", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "ليعزَّ الله الإسلام وأهله، ويذهب الشرك وأهله، ولو كره المشركون ذلك.", "isBasmala": false, "translation_en": "In order to confirm the truth and nullify falsehood, even though the guilty dislike it.", "translation_id": "agar Allah menetapkan yang hak (Islam) dan membatalkan yang batil (syirik) walaupun orang-orang yang berdosa (musyrik) itu tidak menyukainya.", "manzil": 2, "manzil_display": ""}], "178": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 9, "text": "إِذۡ تَسۡتَغِیثُونَ رَبَّكُمۡ فَٱسۡتَجَابَ لَكُمۡ أَنِّی مُمِدُّكُم بِأَلۡفࣲ مِّنَ ٱلۡمَلَـٰۤىِٕكَةِ مُرۡدِفِینَ ۝٩", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "اذكروا نعمة الله عليكم يوم \"بدر\" إذ تطلبون النصر على عدوكم، فاستجاب الله لدعائكم قائلا إني ممدُّكم بألف من الملائكة من السماء، يتبع بعضهم بعضًا.", "isBasmala": false, "translation_en": "When you appealed to your Lord for help, He answered you, \"I am reinforcing you with one thousand angels in succession.\"", "translation_id": "(Ingatlah), ketika kamu memohon pertolongan kepada Tuhanmu, lalu diperkenankan-Nya bagimu: \"Sesungguhnya Aku akan mendatangkan bala bantuan kepada kamu dengan seribu malaikat yang datang berturut-turut\".", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 10, "text": "وَمَا جَعَلَهُ ٱللَّهُ إِلَّا بُشۡرَىٰ وَلِتَطۡمَىِٕنَّ بِهِۦ قُلُوبُكُمۡۚ وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِیزٌ حَكِیمٌ ۝١٠", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "وما جعل الله ذلك الإمداد إلا بشارة لكم بالنصر، ولتسكن به قلوبكم، وتوقنوا بنصر الله لكم، وما النصر إلا من عند الله، لا بشدة بأسكم وقواكم. إن الله عزيز في ملكه، حكيم في تدبيره وشرعه.", "isBasmala": false, "translation_en": "God only made it a message of hope, and to set your hearts at rest. Victory comes only from God. God is Mighty and Wise.", "translation_id": "Dan Allah tidak menjadikannya (mengirim bala bantuan itu), melainkan sebagai kabar gembira dan agar hatimu menjadi tenteram karenanya. Dan kemenangan itu hanyalah dari sisi Allah. Sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 11, "text": "إِذۡ یُغَشِّیكُمُ ٱلنُّعَاسَ أَمَنَةࣰ مِّنۡهُ وَیُنَزِّلُ عَلَیۡكُم مِّنَ ٱلسَّمَاۤءِ مَاۤءࣰ لِّیُطَهِّرَكُم بِهِۦ وَیُذۡهِبَ عَنكُمۡ رِجۡزَ ٱلشَّیۡطَـٰنِ وَلِیَرۡبِطَ عَلَىٰ قُلُوبِكُمۡ وَیُثَبِّتَ بِهِ ٱلۡأَقۡدَامَ ۝١١", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "إذ يُلْقي الله عليكم النعاس أمانًا منه لكم من خوف عدوكم أن يغلبكم، وينزل عليكم من السحاب ماء طهورًا، ليطهركم به من الأحداث الظاهرة، ويزيل عنكم في الباطن وساوس الشيطان وخواطره، وليشدَّ على قلوبكم بالصبر عند القتال، ويثبت به أقدام المؤمنين بتلبيد الأرض الرملية بالمطر حتى لا تنزلق فيها الأقدام.", "isBasmala": false, "translation_en": "He made drowsiness overcome you, as a security from Him. And He sent down upon you water from the sky, to cleanse you with it, and to rid you of Satan's pollution, and to fortify your hearts, and to strengthen your foothold.", "translation_id": "(Ingatlah), ketika Allah menjadikan kamu mengantuk sebagai suatu penenteraman daripada-Nya, dan Allah menurunkan kepadamu hujan dari langit untuk mensucikan kamu dengan hujan itu dan menghilangkan dari kamu gangguan-gangguan syaitan dan untuk menguatkan hatimu dan mesmperteguh dengannya telapak kaki(mu).", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 12, "text": "إِذۡ یُوحِی رَبُّكَ إِلَى ٱلۡمَلَـٰۤىِٕكَةِ أَنِّی مَعَكُمۡ فَثَبِّتُوا۟ ٱلَّذِینَ ءَامَنُوا۟ۚ سَأُلۡقِی فِی قُلُوبِ ٱلَّذِینَ كَفَرُوا۟ ٱلرُّعۡبَ فَٱضۡرِبُوا۟ فَوۡقَ ٱلۡأَعۡنَاقِ وَٱضۡرِبُوا۟ مِنۡهُمۡ كُلَّ بَنَانࣲ ۝١٢", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "إذ يوحي ربك -أيها النبي- إلى الملائكة الذين أمدَّ الله بهم المسلمين في غزوة \"بدر\" أني معكم أُعينكم وأنصركم، فقوُّوا عزائم الذين آمنوا، سألقي في قلوب الذين كفروا الخوف الشديد والذلة والصَّغَار، فاضربوا -أيها المؤمنون- رؤوس الكفار، واضربوا منهم كل طرف ومِفْصل.", "isBasmala": false, "translation_en": "Your Lord inspired the angels: \"I am with you, so support those who believe. I will cast terror into the hearts of those who disbelieve. So strike above the necks, and strike off every fingertip of theirs.\"", "translation_id": "(Ingatlah), ketika Tuhanmu mewahyukan kepada para malaikat: \"Sesungguhnya Aku bersama kamu, maka teguhkan (pendirian) orang-orang yang telah beriman\". Kelak akan Aku jatuhkan rasa ketakutan ke dalam hati orang-orang kafir, maka penggallah kepala mereka dan pancunglah tiap-tiap ujung jari mereka.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 13, "text": "ذَ ٰلِكَ بِأَنَّهُمۡ شَاۤقُّوا۟ ٱللَّهَ وَرَسُولَهُۥۚ وَمَن یُشَاقِقِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ ۝١٣", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "ذلك الذي حدث للكفار من ضَرْب رؤوسهم وأعناقهم وأطرافهم؛ بسبب مخالفتهم لأمر الله ورسوله، ومَن يخالف أمر الله ورسوله، فإن الله شديد العقاب له في الدنيا والآخرة.", "isBasmala": false, "translation_en": "That is because they opposed God and His Messenger. Whoever opposes God and His Messenger-God is severe in retribution.", "translation_id": "(Ketentuan) yang demikian itu adalah karena sesungguhnya mereka menentang Allah dan Rasul-Nya; dan barangsiapa menentang Allah dan Rasul-Nya, maka sesungguhnya Allah amat keras siksaan-Nya.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 14, "text": "ذَ ٰلِكُمۡ فَذُوقُوهُ وَأَنَّ لِلۡكَـٰفِرِینَ عَذَابَ ٱلنَّارِ ۝١٤", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "ذلكم العذاب الذي عجَّلته لكم -أيها الكافرون المخالفون لأوامر الله ورسوله في الدنيا- فذوقوه في الحياة الدنيا، ولكم في الآخرة عذاب النار.", "isBasmala": false, "translation_en": "\"Here it is; so taste it.\" For the disbelievers there is the suffering of the Fire.", "translation_id": "Itulah (hukum dunia yang ditimpakan atasmu), maka rasakanlah hukuman itu. Sesungguhnya bagi orang-orang yang kafir itu ada (lagi) azab neraka.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 15, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا لَقِیتُمُ ٱلَّذِینَ كَفَرُوا۟ زَحۡفࣰا فَلَا تُوَلُّوهُمُ ٱلۡأَدۡبَارَ ۝١٥", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه، إذا قابلتم الذين كفروا في القتال متقاربين منكم فلا تُوَلُّوهم ظهوركم، فتنهزموا عنهم، ولكن اثبتوا لهم، فإن الله معكم وناصركم عليهم.", "isBasmala": false, "translation_en": "O you who believe! When you meet those who disbelieve on the march, never turn your backs on them.", "translation_id": "Hai orang-orang yang beriman, apabila kamu bertemu dengan orang-orang yang kafir yang sedang menyerangmu, maka janganlah kamu membelakangi mereka (mundur).", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 16, "text": "وَمَن یُوَلِّهِمۡ یَوۡمَىِٕذࣲ دُبُرَهُۥۤ إِلَّا مُتَحَرِّفࣰا لِّقِتَالٍ أَوۡ مُتَحَیِّزًا إِلَىٰ فِئَةࣲ فَقَدۡ بَاۤءَ بِغَضَبࣲ مِّنَ ٱللَّهِ وَمَأۡوَىٰهُ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ ۝١٦", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "ومن يُوَلِّهم منكم ظهره وقت الزحف إلا منعطفًا لمكيدة الكفار أو منحازًا إلى جماعة المسلمين حاضري الحرب حيث كانوا، فقد استحق الغضب من الله، ومقامه جهنم، وبئس المصير والمنقلب.", "isBasmala": false, "translation_en": "Anyone who turns his back on them on that Day, except while maneuvering for battle, or to join another group, has incurred wrath from God, and his abode is Hell-what a miserable destination!", "translation_id": "Barangsiapa yang membelakangi mereka (mundur) di waktu itu, kecuali berbelok untuk (sisat) perang atau hendak menggabungkan diri dengan pasukan yang lain, maka sesungguhnya orang itu kembali dengan membawa kemurkaan dari Allah, dan tempatnya ialah neraka Jahannam. Dan amat buruklah tempat kembalinya.", "manzil": 2, "manzil_display": ""}], "179": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 17, "text": "فَلَمۡ تَقۡتُلُوهُمۡ وَلَـٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ وَمَا رَمَیۡتَ إِذۡ رَمَیۡتَ وَلَـٰكِنَّ ٱللَّهَ رَمَىٰ وَلِیُبۡلِیَ ٱلۡمُؤۡمِنِینَ مِنۡهُ بَلَاۤءً حَسَنًاۚ إِنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ ۝١٧", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "فلم تقتلوا -أيها المؤمنون- المشركين يوم \"بدر\"، ولكن الله قتلهم، حيث أعانكم على ذلك، وما رميت حين رميت -أيها النبي- ولكن الله رمى، حيث أوصل الرمية التي رميتها إلى وجوه المشركين؛ وليختبر المؤمنين بالله ورسوله ويوصلهم بالجهاد إلى أعلى الدرجات، ويعرِّفهم نعمته عليهم، فيشكروا له سبحانه على ذلك. إن الله سميع لدعائكم وأقوالكم ما أسررتم به وما أعلنتم، عليم بما فيه صلاح عباده.", "isBasmala": false, "translation_en": "It was not you who killed them, but it was God who killed them. And it was not you who launched when you launched, but it was God who launched. That He may bestow upon the believers an excellent reward. God is Hearing and Knowing.", "translation_id": "Maka (yang sebenarnya) bukan kamu yang membunuh mereka, akan tetapi Allahlah yang membunuh mereka, dan bukan kamu yang melempar ketika kamu melempar, tetapi Allah-lah yang melempar. (Allah berbuat demikian untuk membinasakan mereka) dan untuk memberi kemenangan kepada orang-orang mukmin, dengan kemenangan yang baik. Sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 18, "text": "ذَ ٰلِكُمۡ وَأَنَّ ٱللَّهَ مُوهِنُ كَیۡدِ ٱلۡكَـٰفِرِینَ ۝١٨", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "هذا الفعل مِن قتل المشركين ورميهم حين انهزموا، والبلاء الحسن بنصر المؤمنين على أعدائهم، هو من الله للمؤمنين، وأن الله -فيما يُسْتقبل- مُضعِف ومُبطِل مكر الكافرين حتى يَذِلُّوا وينقادوا للحق أو يهلكوا.", "isBasmala": false, "translation_en": "Such is the case. God will undermine the strategy of the disbelievers.", "translation_id": "Itulah (karunia Allah yang dilimpahkan kepadamu), dan sesungguhnya Allah melemahkan tipu daya orang-orang yang kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 19, "text": "إِن تَسۡتَفۡتِحُوا۟ فَقَدۡ جَاۤءَكُمُ ٱلۡفَتۡحُۖ وَإِن تَنتَهُوا۟ فَهُوَ خَیۡرࣱ لَّكُمۡۖ وَإِن تَعُودُوا۟ نَعُدۡ وَلَن تُغۡنِیَ عَنكُمۡ فِئَتُكُمۡ شَیۡـࣰٔا وَلَوۡ كَثُرَتۡ وَأَنَّ ٱللَّهَ مَعَ ٱلۡمُؤۡمِنِینَ ۝١٩", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "إن تطلبوا -أيها الكفار- من الله أن يوقع بأسه وعذابه على المعتدين الظالمين فقد أجاب الله طلبكم، حين أوقع بكم مِن عقابه ما كان نكالا لكم وعبرة للمتقين، فإن تنتهوا -أيها الكفار- عن الكفر بالله ورسوله وقتال نبيه محمد صلى الله عليه وسلم، فهو خير لكم في دنياكم وأخراكم، وإن تعودوا إلى الحرب وقتال محمد صلى الله عليه وسلم وقتال أتباعه المؤمنين نَعُدْ بهزيمتكم كما هُزمتم يوم \"بدر\"، ولن تغني عنكم جماعتكم شيئًا، كما لم تغن عنكم يوم \"بدر\" مع كثرة عددكم وعتادكم وقلة عدد المؤمنين وعدتهم، وأن الله مع المؤمنين بتأييده ونصره.", "isBasmala": false, "translation_en": "If you desire a verdict, the verdict has come to you. And if you desist, it would be best for you. And if you return, We will return; and your troops, however numerous, will not benefit you. God is with the believers.", "translation_id": "Jika kamu (orang-orang musyrikin) mencari keputusan, maka telah datang keputusan kepadamu; dan jika kamu berhenti; maka itulah yang lehih baik bagimu; dan jika kamu kembali, niscaya Kami kembali (pula); dan angkatan perangmu sekali-kali tidak akan dapat menolak dari kamu sesuatu bahayapun, biarpun dia banyak dan sesungguhnya Allah beserta orang-orang yang beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 20, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَوَلَّوۡا۟ عَنۡهُ وَأَنتُمۡ تَسۡمَعُونَ ۝٢٠", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله أطيعوا الله ورسوله فيما أمركم به ونهاكم عنه، ولا تتركوا طاعة الله وطاعة رسوله، وأنتم تسمعون ما يتلى عليكم في القرآن من الحجج والبراهين.", "isBasmala": false, "translation_en": "O you who believe! Obey God and His Messenger, and do not turn away from him when you hear.", "translation_id": "Hai orang-orang yang beriman, taatlah kepada Allah dan Rasul-Nya, dan janganlah kamu berpaling dari pada-Nya, sedang kamu mendengar (perintah-perintah-Nya),", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 21, "text": "وَلَا تَكُونُوا۟ كَٱلَّذِینَ قَالُوا۟ سَمِعۡنَا وَهُمۡ لَا یَسۡمَعُونَ ۝٢١", "juz": 9, "hizb": "(*½ ح 18*)", "tafsir": "ولا تكونوا أيها المؤمنون في مخالفة الله ورسوله محمد صلى الله عليه وسلم كالمشركين والمنافقين الذين إذا سمعوا كتاب الله يتلى عليهم قالوا: سمعنا بآذاننا، وهم في الحقيقة لا يتدبرون ما سمعوا، ولا يفكرون فيه.", "isBasmala": false, "translation_en": "And be not like those who say, \"We hear,\" when they do not hear.", "translation_id": "dan janganlah kamu menjadi seperti orang-orang (munafik) vang berkata \"Kami mendengarkan, padahal mereka tidak mendengarkan.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 22, "text": "۞ إِنَّ شَرَّ ٱلدَّوَاۤبِّ عِندَ ٱللَّهِ ٱلصُّمُّ ٱلۡبُكۡمُ ٱلَّذِینَ لَا یَعۡقِلُونَ ۝٢٢", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "إنَّ شر ما دبَّ على الأرض -مِنْ خَلْق الله- عند الله الصمُّ الذين انسدَّت آذانهم عن سماع الحق فلا يسمعون، البكم الذين خرست ألسنتهم عن النطق به فلا ينطقون، هؤلاء هم الذين لا يعقلون عن الله أمره ونهيه.", "isBasmala": false, "translation_en": "The worst of animals to God are the deaf and dumb-those who do not reason.", "translation_id": "Sesungguhnya binatang (makhluk) yang seburuk-buruknya pada sisi Allah ialah; orang-orang yang pekak dan tuli yang tidak mengerti apa-apapun.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 23, "text": "وَلَوۡ عَلِمَ ٱللَّهُ فِیهِمۡ خَیۡرࣰا لَّأَسۡمَعَهُمۡۖ وَلَوۡ أَسۡمَعَهُمۡ لَتَوَلَّوا۟ وَّهُم مُّعۡرِضُونَ ۝٢٣", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "ولو علم الله في هؤلاء خيرًا لأسمعهم مواعظ القرآن وعبره حتى يعقلوا عن الله عز وجل حججه وبراهينه، ولكنه علم أنه لا خير فيهم وأنهم لا يؤمنون، ولو أسمعهم -على الفرض والتقدير- لتولَّوا عن الإيمان قصدًا وعنادًا بعد فهمهم له، وهم معرضون عنه، لا التفات لهم إلى الحق بوجه من الوجوه.", "isBasmala": false, "translation_en": "Had God recognized any good in them, He would have made them hear; and had He made them hear, they would have turned away defiantly.", "translation_id": "Kalau sekiranya Allah mengetahui kebaikan ada pada mereka, tentulah Allah menjadikan mereka dapat mendengar. Dan jikalau Allah menjadikan mereka dapat mendengar, niscaya mereka pasti berpaling juga, sedang mereka memalingkan diri (dari apa yang mereka dengar itu).", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 24, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱسۡتَجِیبُوا۟ لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمۡ لِمَا یُحۡیِیكُمۡۖ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَحُولُ بَیۡنَ ٱلۡمَرۡءِ وَقَلۡبِهِۦ وَأَنَّهُۥۤ إِلَیۡهِ تُحۡشَرُونَ ۝٢٤", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "يا أيها الذين صدِّقوا بالله ربًا وبمحمد نبيًا ورسولا استجيبوا لله وللرسول بالطاعة إذا دعاكم لما يحييكم من الحق، ففي الاستجابة إصلاح حياتكم في الدنيا والآخرة، واعلموا -أيها المؤمنون- أن الله تعالى هو المتصرف في جميع الأشياء، والقادر على أن يحول بين الإنسان وما يشتهيه قلبه، فهو سبحانه الذي ينبغي أن يستجاب له إذا دعاكم؛ إذ بيده ملكوت كل شيء، واعلموا أنكم تُجمعون ليوم لا ريب فيه، فيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "O you who believe! Respond to God and to the Messenger when He calls you to what will revive you. And know that God stands between a man and his heart, and that to Him you will be gathered.", "translation_id": "Hai orang-orang yang beriman, penuhilah seruan Allah dan seruan Rasul apabila Rasul menyeru kamu kepada suatu yang memberi kehidupan kepada kamu, ketahuilah bahwa sesungguhnya Allah membatasi antara manusia dan hatinya dan sesungguhnya kepada-Nya-lah kamu akan dikumpulkan.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 25, "text": "وَٱتَّقُوا۟ فِتۡنَةࣰ لَّا تُصِیبَنَّ ٱلَّذِینَ ظَلَمُوا۟ مِنكُمۡ خَاۤصَّةࣰۖ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ ۝٢٥", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "واحذروا -أيها المؤمنون- اختبارًا ومحنة يُعَمُّ بها المسيء وغيره لا يُخَص بها أهل المعاصي ولا مَن باشر الذنب، بل تصيب الصالحين معهم إذا قدروا على إنكار الظلم ولم ينكروه، واعلموا أن الله شديد العقاب لمن خالف أمره ونهيه.", "isBasmala": false, "translation_en": "And beware of discord which does not afflict the wrongdoers among you exclusively; and know that God is severe in retribution.", "translation_id": "Dan peliharalah dirimu dari pada siksaan yang tidak khusus menimpa orang-orang yang zalim saja di antara kamu. Dan ketahuilah bahwa Allah amat keras siksaan-Nya.", "manzil": 2, "manzil_display": ""}], "180": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 26, "text": "وَٱذۡكُرُوۤا۟ إِذۡ أَنتُمۡ قَلِیلࣱ مُّسۡتَضۡعَفُونَ فِی ٱلۡأَرۡضِ تَخَافُونَ أَن یَتَخَطَّفَكُمُ ٱلنَّاسُ فَـَٔاوَىٰكُمۡ وَأَیَّدَكُم بِنَصۡرِهِۦ وَرَزَقَكُم مِّنَ ٱلطَّیِّبَـٰتِ لَعَلَّكُمۡ تَشۡكُرُونَ ۝٢٦", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "واذكروا أيها المؤمنون نِعَم الله عليكم إذ أنتم بـ\"مكة\" قليلو العدد مقهورون، تخافون أن يأخذكم الكفار بسرعة، فجعل لكم مأوى تأوون إليه وهو \"المدينة\"، وقوَّاكم بنصره عليهم يوم \"بدر\"، وأطعمكم من الطيبات -التي من جملتها الغنائم-؛ لكي تشكروا له على ما رزقكم وأنعم به عليكم.", "isBasmala": false, "translation_en": "And remember when you were few, oppressed in the land, fearing that people may capture you; but He sheltered you, and supported you with His victory, and provided you with good things-so that you may be thankful.", "translation_id": "Dan ingatlah (hai para muhajirin) ketika kamu masih berjumlah sedikit, lagi tertindas di muka bumi (Mekah), kamu takut orang-orang (Mekah) akan menculik kamu, maka Allah memberi kamu tempat menetap (Madinah) dan dijadikan-Nya kamu kuat dengan pertolongan-Nya dan diberi-Nya kamu rezeki dari yang baik-baik agar kamu bersyukur.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 27, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَخُونُوا۟ ٱللَّهَ وَٱلرَّسُولَ وَتَخُونُوۤا۟ أَمَـٰنَـٰتِكُمۡ وَأَنتُمۡ تَعۡلَمُونَ ۝٢٧", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تخونوا الله ورسوله بترك ما أوجبه الله عليكم وفِعْل ما نهاكم عنه، ولا تفرطوا فيما ائتمنكم الله عليه، وأنتم تعلمون أنه أمانة يجب الوفاء بها.", "isBasmala": false, "translation_en": "O you who believe! Do not betray God and the Messenger, nor betray your trusts, while you know.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu mengkhianati Allah dan Rasul (Muhammad) dan (juga) janganlah kamu mengkhianati amanat-amanat yang dipercayakan kepadamu, sedang kamu mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 28, "text": "وَٱعۡلَمُوۤا۟ أَنَّمَاۤ أَمۡوَ ٰلُكُمۡ وَأَوۡلَـٰدُكُمۡ فِتۡنَةࣱ وَأَنَّ ٱللَّهَ عِندَهُۥۤ أَجۡرٌ عَظِیمࣱ ۝٢٨", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "واعلموا -أيها المؤمنون- أن أموالكم التي استخلفكم الله فيها، وأولادكم الذين وهبهم الله لكم اختبار من الله وابتلاء لعباده؛ ليعلم أيشكرونه عليها ويطيعونه فيها، أو ينشغلون بها عنه؟ واعلموا أن الله عنده خير وثواب عظيم لمن اتقاه وأطاعه.", "isBasmala": false, "translation_en": "And know that your possessions and your children are a test, and that God possesses an immense reward.", "translation_id": "Dan ketahuilah, bahwa hartamu dan anak-anakmu itu hanyalah sebagai cobaan dan sesungguhnya di sisi Allah-lah pahala yang besar.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 29, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن تَتَّقُوا۟ ٱللَّهَ یَجۡعَل لَّكُمۡ فُرۡقَانࣰا وَیُكَفِّرۡ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَیَغۡفِرۡ لَكُمۡۗ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ ۝٢٩", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه إن تتقوا الله بفعل أوامره واجتناب نواهيه يجعل لكم فصلا بين الحق والباطل، ويَمحُ عنكم ما سلف من ذنوبكم ويسترها عليكم، فلا يؤاخذكم بها. والله ذو الفضل العظيم.", "isBasmala": false, "translation_en": "O you who believe! If you remain conscious of God, He will give you a criterion, and will remit from you your sins, and will forgive you. God is possessor of infinite grace.", "translation_id": "Hai orang-orang beriman, jika kamu bertakwa kepada Allah, Kami akan memberikan kepadamu Furqaan. Dan kami akan jauhkan dirimu dari kesalahan-kesalahanmu, dan mengampuni (dosa-dosa)mu. Dan Allah mempunyai karunia yang besar.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 30, "text": "وَإِذۡ یَمۡكُرُ بِكَ ٱلَّذِینَ كَفَرُوا۟ لِیُثۡبِتُوكَ أَوۡ یَقۡتُلُوكَ أَوۡ یُخۡرِجُوكَۚ وَیَمۡكُرُونَ وَیَمۡكُرُ ٱللَّهُۖ وَٱللَّهُ خَیۡرُ ٱلۡمَـٰكِرِینَ ۝٣٠", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "واذكر -أيها الرسول- حين يكيد لك مشركو قومك بـ\"مكَّة\"؛ ليحبسوك أو يقتلوك أو ينفوك من بلدك. ويكيدون لك، وردَّ الله مكرهم عليهم جزاء لهم، ويمكر الله، والله خير الماكرين.", "isBasmala": false, "translation_en": "When the disbelievers plotted against you, to imprison you, or kill you, or expel you. They planned, and God planned, but God is the Best of planners.", "translation_id": "Dan (ingatlah), ketika orang-orang kafir (Quraisy) memikirkan daya upaya terhadapmu untuk menangkap dan memenjarakanmu atau membunuhmu, atau mengusirmu. Mereka memikirkan tipu daya dan Allah menggagalkan tipu daya itu. Dan Allah sebaik-baik Pembalas tipu daya.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 31, "text": "وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا قَالُوا۟ قَدۡ سَمِعۡنَا لَوۡ نَشَاۤءُ لَقُلۡنَا مِثۡلَ هَـٰذَاۤ إِنۡ هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ۝٣١", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "وإذا تتلى على هؤلاء الذين كفروا بالله آيات القرآن العزيز قالوا جهلا منهم وعنادًا للحق: قد سمعنا هذا من قبل، لو نشاء لقلنا مثل هذا القرآن، ما هذا القرآن الذي تتلوه علينا -يا محمد- إلا أكاذيب الأولين.", "isBasmala": false, "translation_en": "And when Our revelations are recited to them, they say, \"We have heard. Had we wanted, we could have said the like of this; these are nothing but myths of the ancients.\"", "translation_id": "Dan apabila dibacakan kepada mereka ayat-ayat Kami, mereka berkata: \"Sesungguhnya kami telah mendengar (ayat-ayat yang seperti ini), kalau kami menhendaki niscaya kami dapat membacakan yang seperti ini, (Al Quran) ini tidak lain hanyalah dongeng-dongengan orang-orang purbakala\".", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 32, "text": "وَإِذۡ قَالُوا۟ ٱللَّهُمَّ إِن كَانَ هَـٰذَا هُوَ ٱلۡحَقَّ مِنۡ عِندِكَ فَأَمۡطِرۡ عَلَیۡنَا حِجَارَةࣰ مِّنَ ٱلسَّمَاۤءِ أَوِ ٱئۡتِنَا بِعَذَابٍ أَلِیمࣲ ۝٣٢", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "واذكر -أيها الرسول- قول المشركين من قومك داعين الله: إن كان ما جاء به محمد هو الحق مِن عندك فأمطر علينا حجارة من السماء، أو ائتنا بعذاب شديد موجع.", "isBasmala": false, "translation_en": "And they said, \"Our God, if this is the truth from You, then rain down on us stones from the sky, or visit us with a painful affliction.\"", "translation_id": "Dan (ingatlah), ketika mereka (orang-orang musyrik) berkata: \"Ya Allah, jika betul (Al Quran) ini, dialah yang benar dari sisi Engkau, maka hujanilah kami dengan batu dari langit, atau datangkanlah kepada kami azab yang pedih\".", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 33, "text": "وَمَا كَانَ ٱللَّهُ لِیُعَذِّبَهُمۡ وَأَنتَ فِیهِمۡۚ وَمَا كَانَ ٱللَّهُ مُعَذِّبَهُمۡ وَهُمۡ یَسۡتَغۡفِرُونَ ۝٣٣", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "وما كان الله سبحانه وتعالى ليعذِّب هؤلاء المشركين، وأنت -أيها الرسول- بين ظهرانَيْهم، وما كان الله معذِّبهم، وهم يستغفرون من ذنوبهم.", "isBasmala": false, "translation_en": "But God would not punish them while you are amongst them. And God would not punish them as long as they seek forgiveness.", "translation_id": "Dan Allah sekali-kali tidak akan mengazab mereka, sedang kamu berada di antara mereka. Dan tidaklah (pula) Allah akan mengazab mereka, sedang mereka meminta ampun", "manzil": 2, "manzil_display": ""}], "181": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 34, "text": "وَمَا لَهُمۡ أَلَّا یُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ یَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوۤا۟ أَوۡلِیَاۤءَهُۥۤۚ إِنۡ أَوۡلِیَاۤؤُهُۥۤ إِلَّا ٱلۡمُتَّقُونَ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ ۝٣٤", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "وكيف لا يستحقُّون عذاب الله، وهم يصدون أولياءه المؤمنين عن الطواف بالكعبة والصلاة في المسجد الحرام؟ وما كانوا أولياء الله، إنْ أولياء الله إلا الذين يتقونه بأداء فرائضه واجتناب معاصيه، ولكن أكثر الكفار لا يعلمون؛ فلذلك ادَّعوا لأنفسهم أمرًا، غيرهم أولى به.", "isBasmala": false, "translation_en": "Yet why should God not punish them, when they are turning others away from the Sacred Mosque, although they are not its custodians? Its rightful custodians are the pious; but most of them do not know.", "translation_id": "Kenapa Allah tidak mengazab mereka padahal mereka menghalangi orang untuk (mendatangi) Masjidilharam, dan mereka bukanlah orang-orang yang berhak menguasainya? Orang-orang yang berhak menguasai(nya) hanyalah orang-orang yang bertakwa. tetapi kebanyakan mereka tidak mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 35, "text": "وَمَا كَانَ صَلَاتُهُمۡ عِندَ ٱلۡبَیۡتِ إِلَّا مُكَاۤءࣰ وَتَصۡدِیَةࣰۚ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ۝٣٥", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "وما كان صلاتهم عند المسجد الحرام إلا صفيرًا وتصفيقًا. فذوقوا عذاب القتل والأسر يوم \"بدر\"؛ بسبب جحودكم وأفعالكم التي لا يُقْدم عليها إلا الكفرة، الجاحدون توحيد ربهم ورسالة نبيهم.", "isBasmala": false, "translation_en": "Their prayer at the House was nothing but whistling and clapping-so taste the punishment for your blasphemy.", "translation_id": "Sembahyang mereka di sekitar Baitullah itu, lain tidak hanyalah siulan dan tepukan tangan. Maka rasakanlah azab disebabkan kekafiranmu itu.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 36, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ یُنفِقُونَ أَمۡوَ ٰلَهُمۡ لِیَصُدُّوا۟ عَن سَبِیلِ ٱللَّهِۚ فَسَیُنفِقُونَهَا ثُمَّ تَكُونُ عَلَیۡهِمۡ حَسۡرَةࣰ ثُمَّ یُغۡلَبُونَۗ وَٱلَّذِینَ كَفَرُوۤا۟ إِلَىٰ جَهَنَّمَ یُحۡشَرُونَ ۝٣٦", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "إن الذين جحدوا وحدانية الله وعصوا رسوله ينفقون أموالهم فيعطونها أمثالهم من المشركين وأهل الضلال، ليصدوا عن سبيل الله ويمنعوا المؤمنين عن الإيمان بالله ورسوله، فينفقون أموالهم في ذلك، ثم تكون عاقبة نفقتهم تلك ندامة وحسرة عليهم؛ لأن أموالهم تذهب، ولا يظفرون بما يأمُلون مِن إطفاء نور الله والصد عن سبيله، ثم يهزمهم المؤمنون آخر الأمر. والذين كفروا إلى جهنم يحشرون فيعذبون فيها.", "isBasmala": false, "translation_en": "Those who disbelieve spend their wealth to repel from God's path. They will spend it, then it will become a source of sorrow for them, and then they will be defeated. Those who disbelieve will be herded into Hell.", "translation_id": "Sesungguhnya orang-orang yang kafir menafkahkan harta mereka untuk menghalangi (orang) dari jalan Allah. Mereka akan menafkahkan harta itu, kemudian menjadi sesalan bagi mereka, dan mereka akan dikalahkan. Dan ke dalam Jahannamlah orang-orang yang kafir itu dikumpulkan,", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 37, "text": "لِیَمِیزَ ٱللَّهُ ٱلۡخَبِیثَ مِنَ ٱلطَّیِّبِ وَیَجۡعَلَ ٱلۡخَبِیثَ بَعۡضَهُۥ عَلَىٰ بَعۡضࣲ فَیَرۡكُمَهُۥ جَمِیعࣰا فَیَجۡعَلَهُۥ فِی جَهَنَّمَۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ ۝٣٧", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "يحشر الله ويخزي هؤلاء الذين كفروا بربهم، وأنفقوا أموالهم لمنع الناس عن الإيمان بالله والصد عن سبيله؛ ليميز الله تعالى الخبيث من الطيب، ويجعل الله المال الحرام الذي أُنفق للصدِّ عن دين الله بعضه فوق بعض متراكمًا متراكبًا، فيجعله في نار جهنم، هؤلاء الكفار هم الخاسرون في الدنيا والآخرة.", "isBasmala": false, "translation_en": "That God may distinguish the bad from the good, and heap the bad on top of one another, and pile them together, and throw them in Hell. These are the losers.", "translation_id": "supaya Allah memisahkan (golongan) yang buruk dari yang baik dan menjadikan (golongan) yang buruk itu sebagiannya di atas sebagian yang lain, lalu kesemuanya ditumpukkan-Nya, dan dimasukkan-Nya ke dalam neraka Jahannam. Mereka itulah orang-orang yang merugi.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 38, "text": "قُل لِّلَّذِینَ كَفَرُوۤا۟ إِن یَنتَهُوا۟ یُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ وَإِن یَعُودُوا۟ فَقَدۡ مَضَتۡ سُنَّتُ ٱلۡأَوَّلِینَ ۝٣٨", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "قل -أيها الرسول- للذين جحدوا وحدانية الله مِن مشركي قومك: إن ينزجروا عن الكفر وعداوة النبي صلى الله عليه وسلم، ويرجعوا إلى الإيمان بالله وحده وعدم قتال الرسول والمؤمنين، يغفر الله لهم ما سبق من الذنوب، فالإسلام يجُبُّ ما قبله. وإن يَعُدْ هؤلاء المشركون لقتالك -أيها الرسول- بعد الوقعة التي أوقعتها بهم يوم \"بدر\" فقد سبقت طريقة الأولين، وهي أنهم إذا كذبوا واستمروا على عنادهم أننا نعاجلهم بالعذاب والعقوبة.", "isBasmala": false, "translation_en": "Say to those who disbelieve: if they desist, their past will be forgiven. But if they persist-the practice of the ancients has passed away.", "translation_id": "Katakanlah kepada orang-orang yang kafir itu: \"Jika mereka berhenti (dari kekafirannya), niscaya Allah akan mengampuni mereka tentang dosa-dosa mereka yang sudah lalu; dan jika mereka kembali lagi sesungguhnya akan berlaku (kepada mereka) sunnah (Allah tenhadap) orang-orang dahulu\".", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 39, "text": "وَقَـٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةࣱ وَیَكُونَ ٱلدِّینُ كُلُّهُۥ لِلَّهِۚ فَإِنِ ٱنتَهَوۡا۟ فَإِنَّ ٱللَّهَ بِمَا یَعۡمَلُونَ بَصِیرࣱ ۝٣٩", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "وقاتلوا -أيها المؤمنون- المشركين حتى لا يكون شِرْكٌ وصدٌّ عن سبيل الله؛ ولا يُعْبَدَ إلا الله وحده لا شريك له، فيرتفع البلاء عن عباد الله في الأرض، وحتى يكون الدين والطاعة والعبادة كلها لله خالصة دون غيره، فإن انزجروا عن فتنة المؤمنين وعن الشرك بالله وصاروا إلى الدين الحق معكم، فإن الله لا يخفى عليه ما يعملون مِن ترك الكفر والدخول في الإسلام.", "isBasmala": false, "translation_en": "Fight them until there is no more persecution, and religion becomes exclusively for God. But if they desist-God is Seeing of what they do.", "translation_id": "Dan perangilah mereka, supaya jangan ada fitnah dan supaya agama itu semata-mata untuk Allah. Jika mereka berhenti (dari kekafiran), maka sesungguhnya Allah Maha Melihat apa yang mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 40, "text": "وَإِن تَوَلَّوۡا۟ فَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ مَوۡلَىٰكُمۡۚ نِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِیرُ ۝٤٠", "juz": 9, "hizb": "(*¾ ح 18*)", "tafsir": "وإن أعرض هؤلاء المشركون عمَّا دعوتموهم إليه -أيها المؤمنون- من الإيمان بالله ورسوله وترك قتالكم، وأبَوْا إلا الإصرار على الكفر وقتالكم، فأيقِنوا أن الله معينكم وناصركم عليهم. نِعْمَ المعين والناصر لكم ولأوليائه على أعدائكم.", "isBasmala": false, "translation_en": "And if they turn away, know that God is your Protector. The Best Protector, and the Best Supporter.", "translation_id": "Dan jika mereka berpaling, maka ketahuilah bahwasanya Allah Pelindungmu. Dia adalah sebaik-baik Pelindung dan sebaik-baik Penolong.", "manzil": 2, "manzil_display": ""}], "182": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 41, "text": "۞ وَٱعۡلَمُوۤا۟ أَنَّمَا غَنِمۡتُم مِّن شَیۡءࣲ فَأَنَّ لِلَّهِ خُمُسَهُۥ وَلِلرَّسُولِ وَلِذِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَٱبۡنِ ٱلسَّبِیلِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ وَمَاۤ أَنزَلۡنَا عَلَىٰ عَبۡدِنَا یَوۡمَ ٱلۡفُرۡقَانِ یَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝٤١", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "واعلموا -أيها المؤمنون- أن ما ظَفِرتم به مِن عدوكم بالجهاد في سبيل الله فأربعة أخماسه للمقاتلين الذين حضروا المعركة، والخمس الباقي يجزَّأُ خمسة أقسام: الأول لله وللرسول، فيجعل في مصالح المسلمين العامة، والثاني لذوي قرابة رسول الله صلى الله عليه وسلم، وهم بنو هاشم وبنو المطلب، جُعِل لهم الخمس مكان الصدقة فإنها لا تحلُّ لهم، والثالث لليتامى، والرابع للمساكين، والخامس للمسافر الذي انقطعت به النفقة، إن كنتم مقرِّين بتوحيد الله مطيعين له، مؤمنين بما أنزل على عبده محمد صلى الله عليه وسلم من الآيات والمدد والنصر يوم فَرَق بين الحق والباطل بـ\"بدر\"، يوم التقى جَمْعُ المؤمنين وجَمْعُ المشركين. والله على كل شيء قدير لا يعجزه شيء.", "isBasmala": false, "translation_en": "And know that whatever spoils you gain, to God belongs its fifth, and to the Messenger, and the relatives, and the orphans, and the poor, and to the wayfarer, provided you believe in God and in what We revealed to Our servant on the Day of Distinction, the day when the two armies met. God is Capable of everything.", "translation_id": "Ketahuilah, sesungguhnya apa saja yang dapat kamu peroleh sebagai rampasan perang, maka sesungguhnya seperlima untuk Allah, Rasul, kerabat Rasul, anak-anak yatim, orang-orang miskin dan ibnussabil, jika kamu beriman kepada Allah dan kepada apa yang kami turunkan kepada hamba Kami (Muhammad) di hari Furqaan, yaitu di hari bertemunya dua pasukan. Dan Allah Maha Kuasa atas segala sesuatu.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 42, "text": "إِذۡ أَنتُم بِٱلۡعُدۡوَةِ ٱلدُّنۡیَا وَهُم بِٱلۡعُدۡوَةِ ٱلۡقُصۡوَىٰ وَٱلرَّكۡبُ أَسۡفَلَ مِنكُمۡۚ وَلَوۡ تَوَاعَدتُّمۡ لَٱخۡتَلَفۡتُمۡ فِی ٱلۡمِیعَـٰدِ وَلَـٰكِن لِّیَقۡضِیَ ٱللَّهُ أَمۡرࣰا كَانَ مَفۡعُولࣰا لِّیَهۡلِكَ مَنۡ هَلَكَ عَنۢ بَیِّنَةࣲ وَیَحۡیَىٰ مَنۡ حَیَّ عَنۢ بَیِّنَةࣲۗ وَإِنَّ ٱللَّهَ لَسَمِیعٌ عَلِیمٌ ۝٤٢", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "واذكروا حينما كنتم على جانب الوادي الأقرب إلى \"المدينة\"، وعدوكم نازل بجانب الوادي الأقصى، وعِير التجارة في مكان أسفل منكم إلى ساحل \"البحر الأحمر\"، ولو حاولتم أن تضعوا موعدًا لهذا اللقاء لاختلفتم، ولكنَّ الله جمعكم على غير ميعاد؛ ليقضي أمرًا كان مفعولا بنصر أوليائه، وخِذْلان أعدائه بالقتل والأسر؛ وذلك ليهلك من هلك منهم عن حجة لله ثبتت له فعاينها وقطعت عذره، وليحيا مَن حيَّ عن حجة لله قد ثبتت وظهرت له. وإن الله لسميع لأقوال الفريقين، لا يخفى عليه شيء، عليم بنيَّاتهم.", "isBasmala": false, "translation_en": "Recall when you were on the nearer bank, and they were on the further bank, and the caravan was below you. Had you planned for this meeting, you would have disagreed on the timing, but God was to carry out a predetermined matter, so that those who perish would perish by clear evidence, and those who survive would survive by clear evidence. God is Hearing and Knowing.", "translation_id": "(Yaitu di hari) ketika kamu berada di pinggir lembah yang dekat dan mereka berada di pinggir lembah yang jauh sedang kafilah itu berada di bawah kamu. Sekiranya kamu mengadakan persetujuan (untuk menentukan hari pertempuran), pastilah kamu tidak sependapat dalam menentukan hari pertempuran itu, akan tetapi (Allah mempertemukan dua pasukan itu) agar Dia melakukan suatu urusan yang mesti dilaksanakan, yaitu agar orang yang binasa itu binasanya dengan keterangan yang nyata dan agar orang yang hidup itu hidupnya dengan keterangan yang nyata (pula). Sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui,", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 43, "text": "إِذۡ یُرِیكَهُمُ ٱللَّهُ فِی مَنَامِكَ قَلِیلࣰاۖ وَلَوۡ أَرَىٰكَهُمۡ كَثِیرࣰا لَّفَشِلۡتُمۡ وَلَتَنَـٰزَعۡتُمۡ فِی ٱلۡأَمۡرِ وَلَـٰكِنَّ ٱللَّهَ سَلَّمَۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝٤٣", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "واذكر -أيها النبي- حينما أراك الله قلة عدد عدوك في منامك، فأخبرت المؤمنين بذلك، فقوِيت قلوبهم، واجترؤوا على حربهم، ولو أراك ربك كثرة عددهم لتردد أصحابك في ملاقاتهم، وجَبُنتم واختلفتم في أمر القتال، ولكن الله سلَّم من الفشل، ونجَّى من عاقبة ذلك. إنه عليم بخفايا القلوب وطبائع النفوس.", "isBasmala": false, "translation_en": "God made them appear in your dream as few. Had He made them appear as many, you would have lost heart, and disputed in the matter. But God saved the situation. He knows what the hearts contain.", "translation_id": "(yaitu) ketika Allah menampakkan mereka kepadamu di dalam mimpimu (berjumlah) sedikit. Dan sekiranya Allah memperlihatkan mereka kepada kamu (berjumlah) banyak tentu saja kamu menjadi gentar dan tentu saja kamu akan berbantah-bantahan dalam urusan itu, akan tetapi Allah telah menyelamatkan kamu. Sesungguhnya Allah Maha Mengetahui segala isi hati.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 44, "text": "وَإِذۡ یُرِیكُمُوهُمۡ إِذِ ٱلۡتَقَیۡتُمۡ فِیۤ أَعۡیُنِكُمۡ قَلِیلࣰا وَیُقَلِّلُكُمۡ فِیۤ أَعۡیُنِهِمۡ لِیَقۡضِیَ ٱللَّهُ أَمۡرࣰا كَانَ مَفۡعُولࣰاۗ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ۝٤٤", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "واذكر أيضًا حينما برز الأعداء إلى أرض المعركة فرأيتموهم قليلا فاجترأتم عليهم، وقلَّلكم في أعينهم، ليتركوا الاستعداد لحربكم؛ ليقضي الله أمرًا كان مفعولا فيتحقق وَعْدُ الله لكم بالنصر والغلبة، فكانت كلمة الله هي العليا وكلمة الذين كفروا السفلى. وإلى الله مصير الأمور كلها، فيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "When you met, He made them appear as few in your eyes, and made you appear fewer in their eyes, so that God may conclude a predetermined matter. To God all matters revert.", "translation_id": "Dan ketika Allah menampakkan mereka kepada kamu sekalian, ketika kamu berjumpa dengan mereka berjumlah sedikit pada penglihatan matamu dan kamu ditampakkan-Nya berjumlah sedikit pada penglihatan mata mereka, karena Allah hendak melakukan suatu urusan yang mesti dilaksanakan. Dan hanyalah kepada Allahlah dikembalikan segala urusan.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 45, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا لَقِیتُمۡ فِئَةࣰ فَٱثۡبُتُوا۟ وَٱذۡكُرُوا۟ ٱللَّهَ كَثِیرࣰا لَّعَلَّكُمۡ تُفۡلِحُونَ ۝٤٥", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا لقيتم جماعة من أهل الكفر قد استعدوا لقتالكم، فاثبتوا ولا تنهزموا عنهم، واذكروا الله كثيرًا داعين مبتهلين لإنزال النصر عليكم والظَّفَر بعدوكم؛ لكي تفوزوا.", "isBasmala": false, "translation_en": "O you who believe! When you meet a force, stand firm, and remember God much, so that you may prevail.", "translation_id": "Hai orang-orang yang beriman. apabila kamu memerangi pasukan (musuh), maka berteguh hatilah kamu dan sebutlah (nama) Allah sebanyak-banyaknya agar kamu beruntung.", "manzil": 2, "manzil_display": ""}], "183": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 46, "text": "وَأَطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَـٰزَعُوا۟ فَتَفۡشَلُوا۟ وَتَذۡهَبَ رِیحُكُمۡۖ وَٱصۡبِرُوۤا۟ۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّـٰبِرِینَ ۝٤٦", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "والتزموا طاعة الله وطاعة رسوله في كل أحوالكم، ولا تختلفوا فتتفرق كلمتكم وتختلف قلوبكم، فتضعفوا وتذهب قوتكم ونصركم، واصبروا عند لقاه العدو. إن الله مع الصابرين بالعون والنصر والتأييد، ولن يخذلهم.", "isBasmala": false, "translation_en": "And obey God and His Messenger, and do not dispute, lest you falter and lose your courage. And be steadfast. God is with the steadfast.", "translation_id": "Dan taatlah kepada Allah dan Rasul-Nya dan janganlah kamu berbantah-bantahan, yang menyebabkan kamu menjadi gentar dan hilang kekuatanmu dan bersabarlah. Sesungguhnya Allah beserta orang-orang yang sabar.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 47, "text": "وَلَا تَكُونُوا۟ كَٱلَّذِینَ خَرَجُوا۟ مِن دِیَـٰرِهِم بَطَرࣰا وَرِئَاۤءَ ٱلنَّاسِ وَیَصُدُّونَ عَن سَبِیلِ ٱللَّهِۚ وَٱللَّهُ بِمَا یَعۡمَلُونَ مُحِیطࣱ ۝٤٧", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "ولا تكونوا مثل المشركين الذين خرجوا من بلدهم كبرًا ورياءً؛ ليمنعوا الناس عن الدخول في دين الله. والله بما يعملون محيط لا يغيب عنه شيء.", "isBasmala": false, "translation_en": "And do not be like those who left their homes boastfully, showing off before the people, and barring others from the path of God. God comprehends what they do.", "translation_id": "Dan janganlah kamu menjadi seperti orang-orang yang keluar dari kampungnya dengan rasa angkuh dan dengan maksud riya' kepada manusia serta menghalangi (orang) dari jalan Allah. Dan (ilmu) Allah meliputi apa yang mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 48, "text": "وَإِذۡ زَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ أَعۡمَـٰلَهُمۡ وَقَالَ لَا غَالِبَ لَكُمُ ٱلۡیَوۡمَ مِنَ ٱلنَّاسِ وَإِنِّی جَارࣱ لَّكُمۡۖ فَلَمَّا تَرَاۤءَتِ ٱلۡفِئَتَانِ نَكَصَ عَلَىٰ عَقِبَیۡهِ وَقَالَ إِنِّی بَرِیۤءࣱ مِّنكُمۡ إِنِّیۤ أَرَىٰ مَا لَا تَرَوۡنَ إِنِّیۤ أَخَافُ ٱللَّهَۚ وَٱللَّهُ شَدِیدُ ٱلۡعِقَابِ ۝٤٨", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "واذكروا حين حسَّن الشيطان للمشركين ما جاؤوا له وما همُّوا به، وقال لهم: لن يغلبكم أحد اليوم، فإني ناصركم، فلما تقابل الفريقان: المشركون ومعهم الشيطان، والمسلمون ومعهم الملائكة، رجع الشيطان مُدْبرًا، وقال للمشركين: إني بريء منكم، إني أرى ما لا ترون من الملائكة الذين جاؤوا مددًا للمسلمين، إني أخاف الله، فخذلهم وتبرأ منهم. والله شديد العقاب لمن عصاه ولم يتب توبة نصوحًا.", "isBasmala": false, "translation_en": "Satan made their deeds appear good to them, and said, \"You cannot be defeated by any people today, and I am at your side.\" But when the two armies came in sight of one another, he turned on his heels, and said, \"I am innocent of you; I see what you do not see; I fear God; God is severe in punishment.\"", "translation_id": "Dan ketika syaitan menjadikan mereka memandang baik pekerjaan mereka dan mengatakan: \"Tidak ada seorang manusiapun yang dapat menang terhadapmu pada hari ini, dan sesungguhnya saya ini adalah pelindungmu\". Maka tatkala kedua pasukan itu telah dapat saling lihat melihat (berhadapan), syaitan itu balik ke belakang seraya berkata: \"Sesungguhnya saya berlepas diri daripada kamu, sesungguhnya saya dapat melihat apa yang kamu sekalian tidak dapat melihat; sesungguhnya saya takut kepada Allah\". Dan Allah sangat keras siksa-Nya.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 49, "text": "إِذۡ یَقُولُ ٱلۡمُنَـٰفِقُونَ وَٱلَّذِینَ فِی قُلُوبِهِم مَّرَضٌ غَرَّ هَـٰۤؤُلَاۤءِ دِینُهُمۡۗ وَمَن یَتَوَكَّلۡ عَلَى ٱللَّهِ فَإِنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ ۝٤٩", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "واذكروا حين يقول أهل الشرك والنفاق ومرضى القلوب، وهم يرون قلة المسلمين وكثرة عدوهم: غرَّ هؤلاء المسلمين دينُهم، فأوردهم هذه الموارد، ولم يدرك هؤلاء المنافقون أنه من يتوكل على الله ويثق بوعده فإن الله لن يخذله، فإن الله عزيز لا يعجزه شيء، حكيم في تدبيره وصنعه.", "isBasmala": false, "translation_en": "The hypocrites and those in whose hearts is sickness said, \"Their religion has deluded these people.\" But whoever puts his trust in God-God is Mighty and Wise.", "translation_id": "(Ingatlah), ketika orang-orang munafik dan orang-orang yang ada penyakit di dalam hatinya berkata: \"Mereka itu (orang-orang mukmin) ditipu oleh agamanya\". (Allah berfirman): \"Barangsiapa yang bertawakkal kepada Allah, maka sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana\".", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 50, "text": "وَلَوۡ تَرَىٰۤ إِذۡ یَتَوَفَّى ٱلَّذِینَ كَفَرُوا۟ ٱلۡمَلَـٰۤىِٕكَةُ یَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَـٰرَهُمۡ وَذُوقُوا۟ عَذَابَ ٱلۡحَرِیقِ ۝٥٠", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "ولو تعاين -أيها الرسول- حال قبض الملائكة أرواح الكفار وانتزاعها، وهم يضربون وجوههم في حال إقبالهم، ويضربون ظهورهم في حال فرارهم، ويقولون لهم: ذوقوا العذاب المحرق، لرأيت أمرًا عظيمًا، وهذا السياق وإن كان سببه وقعة \"بدر\"، ولكنه عام في حق كلِّ كافر.", "isBasmala": false, "translation_en": "If only you could see, as the angels take away those who disbelieve, striking their faces and their backs: \"Taste the agony of the Burning.\"", "translation_id": "Kalau kamu melihat ketika para malaikat mencabut jiwa orang-orang yang kafir seraya memukul muka dan belakang mereka (dan berkata): \"Rasakanlah olehmu siksa neraka yang membakar\", (tentulah kamu akan merasa ngeri).", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 51, "text": "ذَ ٰلِكَ بِمَا قَدَّمَتۡ أَیۡدِیكُمۡ وَأَنَّ ٱللَّهَ لَیۡسَ بِظَلَّـٰمࣲ لِّلۡعَبِیدِ ۝٥١", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "ذلك الجزاء الذي أصاب المشركين فبسبب أعمالهم السيئة في حياتهم الدنيا، ولا يظلم الله أحدًا من خَلْقه مثقال ذرة، بل هو الحَكَمُ العدل الذي لا يجور.", "isBasmala": false, "translation_en": "\"That is because of what your hands have committed, and because God is not unjust to the servants.\"", "translation_id": "Demikian itu disebabkan oleh perbuatan tanganmu sendiri. Sesungguhnya Allah sekali-kali tidak menganiaya hamba-Nya,", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 52, "text": "كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَفَرُوا۟ بِـَٔایَـٰتِ ٱللَّهِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡۚ إِنَّ ٱللَّهَ قَوِیࣱّ شَدِیدُ ٱلۡعِقَابِ ۝٥٢", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "إنَّ ما نزل بالمشركين يومئذ سُنَّة الله في عقاب الطغاة من الأمم السابقة من أمثال فرعون والسابقين له، عندما كذَّبوا رسل الله وجحدوا آياته، فإن الله أنزل بهم عقابه بسبب ذنوبهم. إن الله قوي لا يُقْهر، شديد العقاب لمن عصاه ولم يتب من ذنبه.", "isBasmala": false, "translation_en": "Like the behavior of the people of Pharaoh, and those before them. They rejected the signs of God, so God seized them for their sins. God is Powerful, Severe in punishment.", "translation_id": "(keadaan mereka) serupa dengan keadaan Fir'aun dan pengikut-pengikutnya serta orang-orang yang sebelumnya. Mereka mengingkari ayat-ayat Allah, maka Allah menyiksa mereka disebabkan dosa-dosanya. Sesungguhnya Allah Maha Kuat lagi amat keras siksaan-Nya.", "manzil": 2, "manzil_display": ""}], "184": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 53, "text": "ذَ ٰلِكَ بِأَنَّ ٱللَّهَ لَمۡ یَكُ مُغَیِّرࣰا نِّعۡمَةً أَنۡعَمَهَا عَلَىٰ قَوۡمٍ حَتَّىٰ یُغَیِّرُوا۟ مَا بِأَنفُسِهِمۡ وَأَنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ ۝٥٣", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "ذلك الجزاء السيِّئ بأن الله إذا أنعم على قوم نعمة لم يسلبها منهم حتى يغيِّروا حالهم الطيبة إلى حال سيئة، وأن الله سميع لأقوال خلقه، عليم بأحوالهم، فيجري عليهم ما اقتضاه علمه ومشيئته.", "isBasmala": false, "translation_en": "That is because God would never change a blessing He has bestowed on a people unless they change what is within themselves, and because God is Hearing and Knowing.", "translation_id": "(Siksaan) yang demikian itu adalah karena sesungguhnya Allah sekali-kali tidak akan meubah sesuatu nikmat yang telah dianugerahkan-Nya kepada suatu kaum, hingga kaum itu meubah apa-apa yang ada pada diri mereka sendiri, dan sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 54, "text": "كَدَأۡبِ ءَالِ فِرۡعَوۡنَ وَٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَذَّبُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ فَأَهۡلَكۡنَـٰهُم بِذُنُوبِهِمۡ وَأَغۡرَقۡنَاۤ ءَالَ فِرۡعَوۡنَۚ وَكُلࣱّ كَانُوا۟ ظَـٰلِمِینَ ۝٥٤", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "شأن هؤلاء الكافرين في ذلك كشأن آل فرعون الذين كذبوا موسى، وشأن الذين كذبوا رسلهم من الأمم السابقة فأهلكهم الله بسبب ذنوبهم، وأغرق آل فرعون في البحر، وكل منهم كان فاعلا ما لم يكن له فِعْلُه من تكذيبهم رسل الله وجحودهم آياته، وإشراكهم في العبادة غيره.", "isBasmala": false, "translation_en": "Such was the case with the people of Pharaoh, and those before them. They denied the signs of their Lord, so We annihilated them for their wrongs, and We drowned the people of Pharaoh-they were all evildoers.", "translation_id": "(keadaan mereka) serupa dengan keadaan Fir'aun dan pengikut-pengikutnya serta orang-orang yang sebelumnya. Mereka mendustakan ayat-ayat Tuhannya maka Kami membinasakan mereka disebabkan dosa-dosanya dan Kami tenggelamkan Fir'aun dan pengikut-pengikutnya; dan kesemuanya adalah orang-orang yang zalim.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 55, "text": "إِنَّ شَرَّ ٱلدَّوَاۤبِّ عِندَ ٱللَّهِ ٱلَّذِینَ كَفَرُوا۟ فَهُمۡ لَا یُؤۡمِنُونَ ۝٥٥", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "إن شر ما دبَّ على الأرض عند الله الكفار المصرُّون على الكفر، فهم لا يصدقون رسل الله، ولا يُقرون بوحدانيته، ولا يتبعون شرعه.", "isBasmala": false, "translation_en": "The worst of creatures in God's view are those who disbelieve. They have no faith.", "translation_id": "Sesungguhnya binatang (makhluk) yang paling buruk di sisi Allah ialah orang-orang yang kafir, karena mereka itu tidak beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 56, "text": "ٱلَّذِینَ عَـٰهَدتَّ مِنۡهُمۡ ثُمَّ یَنقُضُونَ عَهۡدَهُمۡ فِی كُلِّ مَرَّةࣲ وَهُمۡ لَا یَتَّقُونَ ۝٥٦", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "مِن أولئك الأشرار اليهود الذين دخلوا معك في المعاهدات بأن لا يحاربوك ولا يظاهروا عليك أحدًا، ثم ينقضون عهدهم المرة تلو المرة، وهم لا يخافون الله.", "isBasmala": false, "translation_en": "Those of them with whom you made a treaty, but they violate their agreement every time. They are not righteous.", "translation_id": "(Yaitu) orang-orang yang kamu telah mengambil perjanjian dari mereka, sesudah itu mereka mengkhianati janjinya pada setiap kalinya, dan mereka tidak takut (akibat-akibatnya).", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 57, "text": "فَإِمَّا تَثۡقَفَنَّهُمۡ فِی ٱلۡحَرۡبِ فَشَرِّدۡ بِهِم مَّنۡ خَلۡفَهُمۡ لَعَلَّهُمۡ یَذَّكَّرُونَ ۝٥٧", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "فإن واجهت هؤلاء الناقضين للعهود والمواثيق في المعركة، فأنزِلْ بهم من العذاب ما يُدْخل الرعب في قلوب الآخرين، ويشتت جموعهم؛ لعلهم يذّكرون، فلا يجترئون على مثل الذي أقدم عليه السابقون.", "isBasmala": false, "translation_en": "If you confront them in battle, make of them a fearsome example for those who follow them, that they may take heed.", "translation_id": "Jika kamu menemui mereka dalam peperangan, maka cerai beraikanlah orang-orang yang di belakang mereka dengan (menumpas) mereka, supaya mereka mengambil pelajaran.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 58, "text": "وَإِمَّا تَخَافَنَّ مِن قَوۡمٍ خِیَانَةࣰ فَٱنۢبِذۡ إِلَیۡهِمۡ عَلَىٰ سَوَاۤءٍۚ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡخَاۤىِٕنِینَ ۝٥٨", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "وإن خفت -أيها الرسول- من قومٍ خيانة ظهرت بوادرها فألق إليهم عهدهم، كي يكون الطرفان مستويين في العلم بأنه لا عهد بعد اليوم. إن الله لا يحب الخائنين في عهودهم الناقضين للعهد والميثاق.", "isBasmala": false, "translation_en": "If you fear treachery on the part of a people, break off with them in a like manner. God does not like the treacherous.", "translation_id": "Dan jika kamu khawatir akan (terjadinya) pengkhianatan dari suatu golongan, maka kembalikanlah perjanjian itu kepada mereka dengan cara yang jujur. Sesungguhnya Allah tidak menyukai orang-orang yang berkhianat.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 59, "text": "وَلَا یَحۡسَبَنَّ ٱلَّذِینَ كَفَرُوا۟ سَبَقُوۤا۟ۚ إِنَّهُمۡ لَا یُعۡجِزُونَ ۝٥٩", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "ولا يظنن الذين جحدوا آيات الله أنهم فاتوا ونجَوْا، وأن الله لا يقدر عليهم، إنهم لن يُفْلِتوا من عذاب الله.", "isBasmala": false, "translation_en": "Let not the disbelievers assume that they are ahead. They will not escape.", "translation_id": "Dan janganlah orang-orang yang kafir itu mengira, bahwa mereka akan dapat lolos (dari kekuasaan Allah). Sesungguhnya mereka tidak dapat melemahkan (Allah).", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 60, "text": "وَأَعِدُّوا۟ لَهُم مَّا ٱسۡتَطَعۡتُم مِّن قُوَّةࣲ وَمِن رِّبَاطِ ٱلۡخَیۡلِ تُرۡهِبُونَ بِهِۦ عَدُوَّ ٱللَّهِ وَعَدُوَّكُمۡ وَءَاخَرِینَ مِن دُونِهِمۡ لَا تَعۡلَمُونَهُمُ ٱللَّهُ یَعۡلَمُهُمۡۚ وَمَا تُنفِقُوا۟ مِن شَیۡءࣲ فِی سَبِیلِ ٱللَّهِ یُوَفَّ إِلَیۡكُمۡ وَأَنتُمۡ لَا تُظۡلَمُونَ ۝٦٠", "juz": 10, "hizb": "(* ح 19*)", "tafsir": "وأعدُّوا - يا معشر المسلمين - لمواجهة أعدائكم كل ما تقدرون عليه مِن عدد وعدة، لتُدْخلوا بذلك الرهبة في قلوب أعداء الله وأعدائكم المتربصين بكم، وتخيفوا آخرين لا تظهر لكم عداوتهم الآن، لكن الله يعلمهم ويعلم ما يضمرونه. وما تبذلوا من مال وغيره في سبيل الله قليلا أو كثيرًا يخلفه الله عليكم في الدنيا، ويدخر لكم ثوابه إلى يوم القيامة، وأنتم لا تُنْقصون من أجر ذلك شيئًا.", "isBasmala": false, "translation_en": "And prepare against them all the power you can muster, and all the cavalry you can mobilize, to terrify thereby God's enemies and your enemies, and others besides them whom you do not know, but God knows them. Whatever you spend in God's way will be repaid to you in full, and you will not be wronged.", "translation_id": "Dan siapkanlah untuk menghadapi mereka kekuatan apa saja yang kamu sanggupi dan dari kuda-kuda yang ditambat untuk berperang (yang dengan persiapan itu) kamu menggentarkan musuh Allah dan musuhmu dan orang orang selain mereka yang kamu tidak mengetahuinya; sedang Allah mengetahuinya. Apa saja yang kamu nafkahkan pada jalan Allah niscaya akan dibalasi dengan cukup kepadamu dan kamu tidak akan dianiaya (dirugikan).", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 61, "text": "۞ وَإِن جَنَحُوا۟ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا وَتَوَكَّلۡ عَلَى ٱللَّهِۚ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٦١", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "وإن مالوا إلى ترك الحرب ورغبوا في مسالمتكم فمِلْ إلى ذلك -أيها النبي- وفَوِّضْ أمرك إلى الله، وثق به. إنه هو السميع لأقوالهم، العليم بنيَّاتهم.", "isBasmala": false, "translation_en": "But if they incline towards peace, then incline towards it, and put your trust in God. He is the Hearer, the Knower.", "translation_id": "Dan jika mereka condong kepada perdamaian, maka condonglah kepadanya dan bertawakkallah kepada Allah. Sesungguhnya Dialah Yang Maha Mendengar lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}], "185": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 62, "text": "وَإِن یُرِیدُوۤا۟ أَن یَخۡدَعُوكَ فَإِنَّ حَسۡبَكَ ٱللَّهُۚ هُوَ ٱلَّذِیۤ أَیَّدَكَ بِنَصۡرِهِۦ وَبِٱلۡمُؤۡمِنِینَ ۝٦٢", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "وإن أراد الذين عاهدوك المكر بك فإن الله سيكفيك خداعهم؛ إنه هو الذي أنزل عليك نصره وقوَّاك بالمؤمنين من المهاجرين والأنصار، وجَمَع بين قلوبهم بعد التفرق، لو أنفقت مال الدنيا على جمع قلوبهم ما استطعت إلى ذلك سبيلا ولكن الله جمع بينها على الإيمان فأصبحوا إخوانًا متحابين، إنه عزيز في مُلْكه، حكيم في أمره وتدبيره.", "isBasmala": false, "translation_en": "If they intend to deceive you-God is sufficient for you. It is He who supported you with His aid, and with the believers.", "translation_id": "Dan jika mereka bermaksud menipumu, maka sesungguhnya cukuplah Allah (menjadi pelindungmu). Dialah yang memperkuatmu dengan pertolongan-Nya dan dengan para mukmin,", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 63, "text": "وَأَلَّفَ بَیۡنَ قُلُوبِهِمۡۚ لَوۡ أَنفَقۡتَ مَا فِی ٱلۡأَرۡضِ جَمِیعࣰا مَّاۤ أَلَّفۡتَ بَیۡنَ قُلُوبِهِمۡ وَلَـٰكِنَّ ٱللَّهَ أَلَّفَ بَیۡنَهُمۡۚ إِنَّهُۥ عَزِیزٌ حَكِیمࣱ ۝٦٣", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "وإن أراد الذين عاهدوك المكر بك فإن الله سيكفيك خداعهم؛ إنه هو الذي أنزل عليك نصره وقوَّاك بالمؤمنين من المهاجرين والأنصار، وجَمَع بين قلوبهم بعد التفرق، لو أنفقت مال الدنيا على جمع قلوبهم ما استطعت إلى ذلك سبيلا ولكن الله جمع بينها على الإيمان فأصبحوا إخوانًا متحابين، إنه عزيز في مُلْكه، حكيم في أمره وتدبيره.", "isBasmala": false, "translation_en": "And He united their hearts. Had you spent everything on earth, you would not have united their hearts, but God united them together. He is Mighty and Wise.", "translation_id": "dan Yang mempersatukan hati mereka (orang-orang yang beriman). Walaupun kamu membelanjakan semua (kekayaan) yang berada di bumi, niscaya kamu tidak dapat mempersatukan hati mereka, akan tetapi Allah telah mempersatukan hati mereka. Sesungguhnya Dia Maha Gagah lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 64, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ حَسۡبُكَ ٱللَّهُ وَمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِینَ ۝٦٤", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "يا أيها النبي إن الله كافيك، وكافي الذين معك من المؤمنين شرَّ أعدائكم.", "isBasmala": false, "translation_en": "O prophet! Count on God, and on the believers who have followed you.", "translation_id": "Hai Nabi, cukuplah Allah (menjadi Pelindung) bagimu dan bagi orang-orang mukmin yang mengikutimu.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 65, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ حَرِّضِ ٱلۡمُؤۡمِنِینَ عَلَى ٱلۡقِتَالِۚ إِن یَكُن مِّنكُمۡ عِشۡرُونَ صَـٰبِرُونَ یَغۡلِبُوا۟ مِا۟ئَتَیۡنِۚ وَإِن یَكُن مِّنكُم مِّا۟ئَةࣱ یَغۡلِبُوۤا۟ أَلۡفࣰا مِّنَ ٱلَّذِینَ كَفَرُوا۟ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَفۡقَهُونَ ۝٦٥", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "يا أيها النبي حُثَّ المؤمنين بك على القتال، إن يكن منكم عشرون صابرون عند لقاء العدو يغلبوا مائتين منهم، فإن يكن منكم مائة مجاهدة صابرة يغلبوا ألفًا من الكفار؛ لأنهم قوم لا عِلْم ولا فهم عندهم لما أعدَّ الله للمجاهدين في سبيله، فهم يقاتلون من أجل العلو في الأرض والفساد فيها.", "isBasmala": false, "translation_en": "O prophet! Rouse the believers to battle. If there are twenty steadfast among you, they will defeat two hundred; and if there are a hundred of you, they will defeat a thousand of those who disbelieve; because they are a people who do not understand.", "translation_id": "Hai Nabi, kobarkanlah semangat para mukmin untuk berperang. Jika ada dua puluh orang yang sabar diantaramu, niscaya mereka akan dapat mengalahkan dua ratus orang musuh. Dan jika ada seratus orang yang sabar diantaramu, niscaya mereka akan dapat mengalahkan seribu dari pada orang kafir, disebabkan orang-orang kafir itu kaum yang tidak mengerti.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 66, "text": "ٱلۡـَٔـٰنَ خَفَّفَ ٱللَّهُ عَنكُمۡ وَعَلِمَ أَنَّ فِیكُمۡ ضَعۡفࣰاۚ فَإِن یَكُن مِّنكُم مِّا۟ئَةࣱ صَابِرَةࣱ یَغۡلِبُوا۟ مِا۟ئَتَیۡنِۚ وَإِن یَكُن مِّنكُمۡ أَلۡفࣱ یَغۡلِبُوۤا۟ أَلۡفَیۡنِ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّـٰبِرِینَ ۝٦٦", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "الآن خفف الله عنكم أيها المؤمنون لما فيكم من الضعف، فإن يكن منكم مائة صابرة يغلبوا مائتين من الكافرين، وإن يكن منكم ألف يغلبوا ألفين منهم بإذن الله تعالى. والله مع الصابرين بتأييده ونصره.", "isBasmala": false, "translation_en": "God has now lightened your burden, knowing that there is weakness in you. If there are a hundred steadfast among you, they will defeat two hundred; and if there are a thousand of you, they will defeat two thousand by God's leave. God is with the steadfast.", "translation_id": "Sekarang Allah telah meringankan kepadamu dan dia telah mengetahui bahwa padamu ada kelemahan. Maka jika ada diantaramu seratus orang yang sabar, niscaya mereka akan dapat mengalahkan dua ratus orang kafir; dan jika diantaramu ada seribu orang (yang sabar), niscaya mereka akan dapat mengalahkan dua ribu orang, dengan seizin Allah. Dan Allah beserta orang-orang yang sabar.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 67, "text": "مَا كَانَ لِنَبِیٍّ أَن یَكُونَ لَهُۥۤ أَسۡرَىٰ حَتَّىٰ یُثۡخِنَ فِی ٱلۡأَرۡضِۚ تُرِیدُونَ عَرَضَ ٱلدُّنۡیَا وَٱللَّهُ یُرِیدُ ٱلۡـَٔاخِرَةَۗ وَٱللَّهُ عَزِیزٌ حَكِیمࣱ ۝٦٧", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "لا ينبغي لنبي أن يكون له أسرى مِن أعدائه حتى يبالغ في القتل؛ لإدخال الرعب في قلوبهم ويوطد دعائم الدين، تريدون -يا معشر المسلمين- بأخذكم الفداء من أسرى \"بدر\" متاع الدنيا، والله يريد إظهار دينه الذي به تدرك الآخرة. والله عزيز لا يُقْهر، حكيم في شرعه.", "isBasmala": false, "translation_en": "It is not for a prophet to take prisoners before he has subdued the land. You desire the materials of this world, but God desires the Hereafter. God is Strong and Wise.", "translation_id": "Tidak patut, bagi seorang Nabi mempunyai tawanan sebelum ia dapat melumpuhkan musuhnya di muka bumi. Kamu menghendaki harta benda duniawiyah sedangkan Allah menghendaki (pahala) akhirat (untukmu). Dan Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 68, "text": "لَّوۡلَا كِتَـٰبࣱ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِیمَاۤ أَخَذۡتُمۡ عَذَابٌ عَظِیمࣱ ۝٦٨", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "لولا كتاب من الله سبق به القضاء والقدر بإباحة الغنيمة وفداء الأسرى لهذه الأمة، لنالكم عذاب عظيم بسبب أخْذكم الغنيمة والفداء قبل أن ينزل بشأنهما تشريع.", "isBasmala": false, "translation_en": "Were it not for a predetermined decree from God, an awful punishment would have afflicted you for what you have taken.", "translation_id": "Kalau sekiranya tidak ada ketetapan yang telah terdahulu dari Allah, niscaya kamu ditimpa siksaan yang besar karena tebusan yang kamu ambil.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 69, "text": "فَكُلُوا۟ مِمَّا غَنِمۡتُمۡ حَلَـٰلࣰا طَیِّبࣰاۚ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝٦٩", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "فكلوا من الغنائم وفداء الأسرى فهو حلال طيب، وحافظوا على أحكام دين الله وتشريعاته. إن الله غفور لعباده، رحيم بهم.", "isBasmala": false, "translation_en": "So consume what you have gained, legitimate and wholesome; and remain conscious of God. God is Forgiving and Merciful.", "translation_id": "Maka makanlah dari sebagian rampasan perang yang telah kamu ambil itu, sebagai makanan yang halal lagi baik, dan bertakwalah kepada Allah; sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}], "186": [{"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 70, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ قُل لِّمَن فِیۤ أَیۡدِیكُم مِّنَ ٱلۡأَسۡرَىٰۤ إِن یَعۡلَمِ ٱللَّهُ فِی قُلُوبِكُمۡ خَیۡرࣰا یُؤۡتِكُمۡ خَیۡرࣰا مِّمَّاۤ أُخِذَ مِنكُمۡ وَیَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٧٠", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "يا أيها النبي قل لمن أسرتموهم في \"بدر\": لا تأسوا على الفداء الذي أخذ منكم، إن يعلم الله تعالى في قلوبكم خيرًا يؤتكم خيرًا مما أُخذ منكم من المال بأن يُيَسِّر لكم من فضله خيرًا كثيرًا -وقد أنجز الله وعده للعباس رضي الله عنه وغيره-، ويغفر لكم ذنوبكم. والله سبحانه غفور لذنوب عباده إذا تابوا، رحيم بهم.", "isBasmala": false, "translation_en": "O prophet! Say to those you hold prisoners, \"If God finds any good in your hearts, He will give you better than what was taken from you, and He will forgive you. God is Forgiving and Merciful.\"", "translation_id": "Hai Nabi, katakanlah kepada tawanan-tawanan yang ada di tanganmu: \"Jika Allah mengetahui ada kebaikan dalam hatimu, niscaya Dia akan memberikan kepadamu yang lebih baik dari apa yang telah diambil daripadamu dan Dia akan mengampuni kamu\". Dan Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 71, "text": "وَإِن یُرِیدُوا۟ خِیَانَتَكَ فَقَدۡ خَانُوا۟ ٱللَّهَ مِن قَبۡلُ فَأَمۡكَنَ مِنۡهُمۡۗ وَٱللَّهُ عَلِیمٌ حَكِیمٌ ۝٧١", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "وإن يرد الذين أَطْلَقْتَ سراحهم -أيها النبي- من الأسرى الغدر بك مرة أخرى فلا تَيْئسْ، فقد خانوا الله من قبل وحاربوك، فنصرك الله عليهم. والله عليم بما تنطوي عليه الصدور، حكيم في تدبير شؤون عباده.", "isBasmala": false, "translation_en": "But if they intend to betray you, they have already betrayed God, and He has overpowered them. God is Knowing and Wise.", "translation_id": "Akan tetapi jika mereka (tawanan-tawanan itu) bermaksud hendak berkhianat kepadamu, maka sesungguhnya mereka telah berkhianat kepada Allah sebelum ini, lalu Allah menjadikan(mu) berkuasa terhadap mereka. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 72, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ بِأَمۡوَ ٰلِهِمۡ وَأَنفُسِهِمۡ فِی سَبِیلِ ٱللَّهِ وَٱلَّذِینَ ءَاوَوا۟ وَّنَصَرُوۤا۟ أُو۟لَـٰۤىِٕكَ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضࣲۚ وَٱلَّذِینَ ءَامَنُوا۟ وَلَمۡ یُهَاجِرُوا۟ مَا لَكُم مِّن وَلَـٰیَتِهِم مِّن شَیۡءٍ حَتَّىٰ یُهَاجِرُوا۟ۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِی ٱلدِّینِ فَعَلَیۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۭ بَیۡنَكُمۡ وَبَیۡنَهُم مِّیثَـٰقࣱۗ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ ۝٧٢", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "إن الذين صدَّقوا الله، ورسوله وعملوا بشرعه، وهاجروا إلى دار الإسلام، أو بلد يتمكنون فيه من عبادة ربهم، وجاهدوا في سبيل الله بالمال والنفس، والذين أنزلوا المهاجرين في دورهم، وواسوهم بأموالهم، ونصروا دين الله، أولئك بعضهم نصراء بعض. أما الذين آمنوا ولم يهاجروا من دار الكفر فلستم مكلفين بحمايتهم ونصرتهم حتى يهاجروا، وإن وقع عليهم ظلم من الكفار فطلبوا نصرتكم فاستجيبوا لهم، إلا على قوم بينكم وبينهم عهد مؤكد لم ينقضوه. والله بصير بأعمالكم، بجزي كلا على قدر نيته وعمله.", "isBasmala": false, "translation_en": "Those who believed, and emigrated, and struggled in God's cause with their possessions and their persons, and those who provided shelter and support-these are allies of one another. As for those who believed, but did not emigrate, you owe them no protection, until they have emigrated. But if they ask you for help in religion, you must come to their aid, except against a people with whom you have a treaty. God is Seeing of what you do.", "translation_id": "Sesungguhnya orang-orang yang beriman dan berhijrah serta berjihad dengan harta dan jiwanya pada jalan Allah dan orang-orang yang memberikan tempat kediaman dan pertoIongan (kepada orang-orang muhajirin), mereka itu satu sama lain lindung-melindungi. Dan (terhadap) orang-orang yang beriman, tetapi belum berhijrah, maka tidak ada kewajiban sedikitpun atasmu melindungi mereka, sebelum mereka berhijrah. (Akan tetapi) jika mereka meminta pertolongan kepadamu dalam (urusan pembelaan) agama, maka kamu wajib memberikan pertolongan kecuali terhadap kaum yang telah ada perjanjian antara kamu dengan mereka. Dan Allah Maha Melihat apa yang kamu kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 73, "text": "وَٱلَّذِینَ كَفَرُوا۟ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضٍۚ إِلَّا تَفۡعَلُوهُ تَكُن فِتۡنَةࣱ فِی ٱلۡأَرۡضِ وَفَسَادࣱ كَبِیرࣱ ۝٧٣", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "والذين كفروا بعضهم نصراء بعض، وإن لم تكونوا -أيها المؤمنون- نصراء بعض تكن في الأرض فتنة للمؤمنين عن دين الله، وفساد عريض بالصد عن سبيل الله وتقوية دعائم الكفر.", "isBasmala": false, "translation_en": "As for those who disbelieve, they are allies of one another. Unless you do this, there will be turmoil in the land, and much corruption.", "translation_id": "Adapun orang-orang yang kafir, sebagian mereka menjadi pelindung bagi sebagian yang lain. Jika kamu (hai para muslimin) tidak melaksanakan apa yang telah diperintahkan Allah itu, niscaya akan terjadi kekacauan di muka bumi dan kerusakan yang besar.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 74, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِی سَبِیلِ ٱللَّهِ وَٱلَّذِینَ ءَاوَوا۟ وَّنَصَرُوۤا۟ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُؤۡمِنُونَ حَقࣰّاۚ لَّهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ ۝٧٤", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "والذين آمنوا بالله ورسوله، وتركوا ديارهم قاصدين دار الإسلام أو بلدًا يتمكنون فيه من عبادة ربهم، وجاهدوا لإعلاء كلمة الله، والذين نصروا إخوانهم المهاجرين وآووهم وواسوهم بالمال والتأييد، أولئك هم المؤمنون الصادقون حقًا، لهم مغفرة لذنوبهم، ورزق كريم واسع في جنات النعيم.", "isBasmala": false, "translation_en": "Those who believed, and emigrated, and struggled for God's cause, and those who gave shelter and support-these are the true believers. They will have forgiveness, and a bountiful provision.", "translation_id": "Dan orang-orang yang beriman dan berhijrah serta berjihad pada jalan Allah, dan orang-orang yang memberi tempat kediaman dan memberi pertolongan (kepada orang-orang muhajirin), mereka itulah orang-orang yang benar-benar beriman. Mereka memperoleh ampunan dan rezeki (nikmat) yang mulia.", "manzil": 2, "manzil_display": ""}, {"sura": 8, "sura_name": "الأنفال", "revelation": "Madaniyah", "aya": 75, "text": "وَٱلَّذِینَ ءَامَنُوا۟ مِنۢ بَعۡدُ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ مَعَكُمۡ فَأُو۟لَـٰۤىِٕكَ مِنكُمۡۚ وَأُو۟لُوا۟ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضࣲ فِی كِتَـٰبِ ٱللَّهِۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمُۢ ۝٧٥", "juz": 10, "hizb": "(*¼ ح 19*)", "tafsir": "والذين آمنوا مِن بعد هؤلاء المهاجرين والأنصار، وهاجروا وجاهدوا معكم في سبيل الله، فأولئك منكم -أيها المؤمنون- لهم ما لكم وعليهم ما عليكم، وأولو القرابة بعضهم أولى ببعض في التوارث في حكم الله من عامة المسلمين. إن الله بكل شيء عليم يعلم ما يصلح عباده مِن توريث بعضهم من بعض في القرابة والنسب دون التوارث بالحِلْف، وغير ذلك مما كان في أول الإسلام.", "isBasmala": false, "translation_en": "As for those who believed afterwards, and emigrated and struggled with you-these belong with you. But family members are nearer to one another in the Book of God. God is Cognizant of everything.", "translation_id": "Dan orang-orang yang beriman sesudah itu kemudian berhijrah serta berjihad bersamamu maka orang-orang itu termasuk golonganmu (juga). Orang-orang yang mempunyai hubungan kerabat itu sebagiannya lebih berhak terhadap sesamanya (daripada yang bukan kerabat) di dalam kitab Allah. Sesungguhnya Allah Maha Mengetahui segala sesuatu.", "manzil": 2, "manzil_display": ""}], "187": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 1, "text": "۞ بَرَاۤءَةࣱ مِّنَ ٱللَّهِ وَرَسُولِهِۦۤ إِلَى ٱلَّذِینَ عَـٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِینَ ۝١", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "هذه براءة من الله ورسوله، وإعلان بالتخلي عن العهود التي كانت بين المسلمين والمشركين.", "isBasmala": false, "translation_en": "A declaration of immunity from God and His Messenger to the polytheists with whom you had made a treaty.", "translation_id": "(Inilah pernyataan) pemutusan hubungan dari Allah dan Rasul-Nya (yang dihadapkan) kepada orang-orang musyrikin yang kamu (kaum muslimin) telah mengadakan perjanjian (dengan mereka).", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 2, "text": "فَسِیحُوا۟ فِی ٱلۡأَرۡضِ أَرۡبَعَةَ أَشۡهُرࣲ وَٱعۡلَمُوۤا۟ أَنَّكُمۡ غَیۡرُ مُعۡجِزِی ٱللَّهِ وَأَنَّ ٱللَّهَ مُخۡزِی ٱلۡكَـٰفِرِینَ ۝٢", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "فسيروا -أيها المشركون- في الأرض مدَّة أربعة أشهر، تذهبون حيث شئتم آمنين من المؤمنين، واعلموا أنكم لن تُفْلِتوا من العقوبة، وأن الله مذل الكافرين ومورثهم العار في الدنيا، والنار في الآخرة. وهذه الآية لذوي العهود المطلقة غير المؤقتة، أو من له عهد دون أربعة أشهر، فيكمَّل له أربعة أشهر، أو مَن كان له عهد فنقضه.", "isBasmala": false, "translation_en": "So travel the land for four months, and know that you cannot escape God, and that God will disgrace the disbelievers.", "translation_id": "Maka berjalanlah kamu (kaum musyrikin) di muka bumi selama empat bulan dan ketahuilah bahwa sesungguhnya kamu tidak akan dapat melemahkan Allah, dan sesungguhnya Allah menghinakan orang-orang kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 3, "text": "وَأَذَ ٰنࣱ مِّنَ ٱللَّهِ وَرَسُولِهِۦۤ إِلَى ٱلنَّاسِ یَوۡمَ ٱلۡحَجِّ ٱلۡأَكۡبَرِ أَنَّ ٱللَّهَ بَرِیۤءࣱ مِّنَ ٱلۡمُشۡرِكِینَ وَرَسُولُهُۥۚ فَإِن تُبۡتُمۡ فَهُوَ خَیۡرࣱ لَّكُمۡۖ وَإِن تَوَلَّیۡتُمۡ فَٱعۡلَمُوۤا۟ أَنَّكُمۡ غَیۡرُ مُعۡجِزِی ٱللَّهِۗ وَبَشِّرِ ٱلَّذِینَ كَفَرُوا۟ بِعَذَابٍ أَلِیمٍ ۝٣", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "وإعلام من الله ورسوله وإنذار إلى الناس يوم النحر أن الله بريء من المشركين، ورسوله بريء منهم كذلك. فإن رجعتم -أيها المشركون- إلى الحق وتركتم شرككم فهو خير لكم، وإن أعرضتم عن قَبول الحق وأبيتم الدخول في دين الله فاعلموا أنكم لن تُفْلِتوا من عذاب الله. وأنذر -أيها الرسول- هؤلاء المعرضين عن الإسلام عذاب الله الموجع.", "isBasmala": false, "translation_en": "And a proclamation from God and His Messenger to the people on the day of the Greater Pilgrimage, that God has disowned the polytheists, and so did His Messenger. If you repent, it will be better for you. But if you turn away, know that you cannot escape God. And announce to those who disbelieve a painful punishment.", "translation_id": "Dan (inilah) suatu permakluman daripada Allah dan Rasul-Nya kepada umat manusia pada hari haji akbar bahwa sesungguhnya Allah dan Rasul-Nya berlepas diri dari orang-orang musyrikin. Kemudian jika kamu (kaum musyrikin) bertobat, maka bertaubat itu lebih baik bagimu; dan jika kamu berpaling, maka ketahuilah bahwa sesungguhnya kamu tidak dapat melemahkan Allah. Dan beritakanlah kepada orang-orang kafir (bahwa mereka akan mendapat) siksa yang pedih.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 4, "text": "إِلَّا ٱلَّذِینَ عَـٰهَدتُّم مِّنَ ٱلۡمُشۡرِكِینَ ثُمَّ لَمۡ یَنقُصُوكُمۡ شَیۡـࣰٔا وَلَمۡ یُظَـٰهِرُوا۟ عَلَیۡكُمۡ أَحَدࣰا فَأَتِمُّوۤا۟ إِلَیۡهِمۡ عَهۡدَهُمۡ إِلَىٰ مُدَّتِهِمۡۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُتَّقِینَ ۝٤", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "ويُستثنى من الحكم السابق المشركون الذين دخلوا معكم في عهد محدد بمدة، ولم يخونوا العهد، ولم يعاونوا عليكم أحدا من الأعداء، فأكملوا لهم عهدهم إلى نهايته المحدودة. إن الله يحب المتقين الذين أدَّوا ما أمروا به، واتقوا الشرك والخيانة، وغير ذلك من المعاصي.", "isBasmala": false, "translation_en": "Except for those among the polytheists with whom you had made a treaty, and did not violate any of its terms, nor aided anyone against you. So fulfill the treaty with them to the end of its term. God loves the righteous.", "translation_id": "kecuali orang-orang musyrikin yang kamu telah mengadakan perjanjian (dengan mereka) dan mereka tidak mengurangi sesuatu pun (dari isi perjanjian)mu dan tidak (pula) mereka membantu seseorang yang memusuhi kamu, maka terhadap mereka itu penuhilah janjinya sampai batas waktunya. Sesungguhnya Allah menyukai orang-orang yang bertakwa.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 5, "text": "فَإِذَا ٱنسَلَخَ ٱلۡأَشۡهُرُ ٱلۡحُرُمُ فَٱقۡتُلُوا۟ ٱلۡمُشۡرِكِینَ حَیۡثُ وَجَدتُّمُوهُمۡ وَخُذُوهُمۡ وَٱحۡصُرُوهُمۡ وَٱقۡعُدُوا۟ لَهُمۡ كُلَّ مَرۡصَدࣲۚ فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَخَلُّوا۟ سَبِیلَهُمۡۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝٥", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "فإذا انقضت الأشهر الأربعة التي أمَّنتم فيها المشركين، فأعلنوا الحرب على أعداء الله حيث كانوا، واقصدوهم بالحصار في معاقلهم، وترصدوا لهم في طرقهم، فإن رجعوا عن كفرهم ودخلوا الإسلام والتزموا شرائعه من إقام الصلاة وإخراج الزكاة، فاتركوهم، فقد أصبحوا إخوانكم في الإسلام، إن الله غفور لمن تاب وأناب، رحيم بهم.", "isBasmala": false, "translation_en": "When the Sacred Months have passed, kill the polytheists wherever you find them. And capture them, and besiege them, and lie in wait for them at every ambush. But if they repent, and perform the prayers, and pay the alms, then let them go their way. God is Most Forgiving, Most Merciful.", "translation_id": "Apabila sudah habis bulan-bulan Haram itu, maka bunuhlah orang-orang musyrikin itu dimana saja kamu jumpai mereka, dan tangkaplah mereka. Kepunglah mereka dan intailah ditempat pengintaian. Jika mereka bertaubat dan mendirikan sholat dan menunaikan zakat, maka berilah kebebasan kepada mereka untuk berjalan. Sesungguhnya Allah Maha Pengampun lagi maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 6, "text": "وَإِنۡ أَحَدࣱ مِّنَ ٱلۡمُشۡرِكِینَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ یَسۡمَعَ كَلَـٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَ ٰلِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَعۡلَمُونَ ۝٦", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "وإذا طلب أحد من المشركين الذين استبيحت دماؤهم وأموالهم الدخول في جوارك -أيها الرسول- ورغب في الأمان، فأجبه إلى طلبه حتى يسمع القرآن الكريم ويطَّلع على هدايته، ثم أَعِدْه من حيث أتى آمنًا؛ وذلك لإقامة الحجة عليه؛ ذلك بسبب أن الكفار قوم جاهلون بحقائق الإسلام، فربما اختاروه إذا زال الجهل عنهم.", "isBasmala": false, "translation_en": "And if anyone of the polytheists asks you for protection, give him protection so that he may hear the Word of God; then escort him to his place of safety. That is because they are a people who do not know.", "translation_id": "Dan jika seorang diantara orang-orang musyrikin itu meminta perlindungan kepadamu, maka lindungilah ia supaya ia sempat mendengar firman Allah, kemudian antarkanlah ia ketempat yang aman baginya. Demikian itu disebabkan mereka kaum yang tidak mengetahui.", "manzil": 2, "manzil_display": ""}], "188": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 7, "text": "كَیۡفَ یَكُونُ لِلۡمُشۡرِكِینَ عَهۡدٌ عِندَ ٱللَّهِ وَعِندَ رَسُولِهِۦۤ إِلَّا ٱلَّذِینَ عَـٰهَدتُّمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِۖ فَمَا ٱسۡتَقَـٰمُوا۟ لَكُمۡ فَٱسۡتَقِیمُوا۟ لَهُمۡۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُتَّقِینَ ۝٧", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "لا ينبغي أن يكون للمشركين عهد عند الله وعند رسوله، إلا الذين عاهدتم عند المسجد الحرام في صلح (الحديبية) فما أقاموا على الوفاء بعهدكم فأقيموا لهم على مثل ذلك. إن الله يحب المتقين الموفِّين بعهودهم.", "isBasmala": false, "translation_en": "How can there be a treaty with the polytheists on the part of God and His Messenger, except for those with whom you made a treaty at the Sacred Mosque? As long as they are upright with you, be upright with them. God loves the pious.", "translation_id": "Bagaimana bisa ada perjanjian (aman) dari sisi Allah dan Rasul-Nya dengan orang-orang musyrikin, kecuali orang-orang yang kamu telah mengadakan perjanjian (dengan mereka) di dekat Masjidil haraam? maka selama mereka berlaku lurus terhadapmu, hendaklah kamu berlaku lurus (pula) terhadap mereka. Sesungguhnya Allah menyukai orang-orang yang bertakwa.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 8, "text": "كَیۡفَ وَإِن یَظۡهَرُوا۟ عَلَیۡكُمۡ لَا یَرۡقُبُوا۟ فِیكُمۡ إِلࣰّا وَلَا ذِمَّةࣰۚ یُرۡضُونَكُم بِأَفۡوَ ٰهِهِمۡ وَتَأۡبَىٰ قُلُوبُهُمۡ وَأَكۡثَرُهُمۡ فَـٰسِقُونَ ۝٨", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "إن شأن المشركين أن يلتزموا بالعهود ما دامت الغلبة لغيرهم، أما إذا شعروا بالقوة على المؤمنين فإنهم لا يراعون القرابة ولا العهد، فلا يغرنكم منهم ما يعاملونكم به وقت الخوف منكم، فإنهم يقولون لكم كلامًا بألسنتهم؛ لترضوا عنهم، ولكن قلوبهم تأبى ذلك، وأكثرهم متمردون على الإسلام ناقضون للعهد.", "isBasmala": false, "translation_en": "How? Whenever they overcome you, they respect neither kinship nor treaty with you. They satisfy you with lip service, but their hearts refuse, and most of them are immoral.", "translation_id": "Bagaimana bisa (ada perjanjian dari sisi Allah dan Rasul-Nya dengan orang-orang musyrikin), padahal jika mereka memperoleh kemenangan terhadap kamu, mereka tidak memelihara hubungan kekerabatan terhadap kamu dan tidak (pula mengindahkan) perjanjian. Mereka menyenangkan hatimu dengan mulutnya, sedang hatinya menolak. Dan kebanyakan mereka adalah orang-orang yang fasik (tidak menepati perjanjian).", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 9, "text": "ٱشۡتَرَوۡا۟ بِـَٔایَـٰتِ ٱللَّهِ ثَمَنࣰا قَلِیلࣰا فَصَدُّوا۟ عَن سَبِیلِهِۦۤۚ إِنَّهُمۡ سَاۤءَ مَا كَانُوا۟ یَعۡمَلُونَ ۝٩", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "استبدلوا بآيات الله عرض الدنيا التافه، فأعرضوا عن الحق ومنعوا الراغبين في الإسلام عن الدخول فيه، لقد قَبُح فعلهم، وساء صنيعهم.", "isBasmala": false, "translation_en": "They traded away God's revelations for a cheap price, so they barred others from His path. How evil is what they did.", "translation_id": "Mereka menukarkan ayat-ayat Allah dengan harga yang sedikit, lalu mereka menghalangi (manusia) dari jalan Allah. Sesungguhnya amat buruklah apa yang mereka kerjakan itu.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 10, "text": "لَا یَرۡقُبُونَ فِی مُؤۡمِنٍ إِلࣰّا وَلَا ذِمَّةࣰۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُعۡتَدُونَ ۝١٠", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "إن هؤلاء المشركين حرب على الإيمان وأهله، فلا يقيمون وزنًا لقرابة المؤمن ولا لعهده، وشأنهم العدوان والظلم.", "isBasmala": false, "translation_en": "Towards a believer they respect neither kinship nor treaty. These are the transgressors.", "translation_id": "Mereka tidak memelihara (hubungan) kerabat terhadap orang-orang mukmin dan tidak (pula mengindahkan) perjanjian. Dan mereka itulah orang-orang yang melampaui batas.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 11, "text": "فَإِن تَابُوا۟ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ فَإِخۡوَ ٰنُكُمۡ فِی ٱلدِّینِۗ وَنُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡلَمُونَ ۝١١", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "فإن أقلعوا عن عبادة غير الله، ونطقوا بكلمة التوحيد، والتزموا شرائع الإسلام من إقام الصلاة وإيتاء الزكاة، فإنهم إخوانكم في الإسلام. ونبين الآيات، ونوضحها لقوم ينتفعون بها.", "isBasmala": false, "translation_en": "But if they repent, and perform the prayers, and give the obligatory charity, then they are your brethren in faith. We detail the revelations for a people who know.", "translation_id": "Jika mereka bertaubat, mendirikan sholat dan menunaikan zakat, maka (mereka itu) adalah saudara-saudaramu seagama. Dan Kami menjelaskan ayat-ayat itu bagi kaum yang mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 12, "text": "وَإِن نَّكَثُوۤا۟ أَیۡمَـٰنَهُم مِّنۢ بَعۡدِ عَهۡدِهِمۡ وَطَعَنُوا۟ فِی دِینِكُمۡ فَقَـٰتِلُوۤا۟ أَىِٕمَّةَ ٱلۡكُفۡرِ إِنَّهُمۡ لَاۤ أَیۡمَـٰنَ لَهُمۡ لَعَلَّهُمۡ یَنتَهُونَ ۝١٢", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "وإنْ نَقَضَ هؤلاء المشركون العهود التي أبرمتموها معهم، وأظهروا الطعن في دين الإسلام، فقاتلوهم فإنهم رؤساء الضلال، لا عهد لهم ولا ذمة، حتى ينتهوا عن كفرهم وعداوتهم للإسلام.", "isBasmala": false, "translation_en": "But if they violate their oaths after their pledge, and attack your religion, then fight the leaders of disbelief-they have no faith-so that they may desist.", "translation_id": "Jika mereka merusak sumpah (janji)nya sesudah mereka berjanji, dan mereka mencerca agamamu, maka perangilah pemimpin-pemimpin orang-orang kafir itu, karena sesungguhnya mereka itu adalah orang-orang (yang tidak dapat dipegang) janjinya, agar supaya mereka berhenti.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 13, "text": "أَلَا تُقَـٰتِلُونَ قَوۡمࣰا نَّكَثُوۤا۟ أَیۡمَـٰنَهُمۡ وَهَمُّوا۟ بِإِخۡرَاجِ ٱلرَّسُولِ وَهُم بَدَءُوكُمۡ أَوَّلَ مَرَّةٍۚ أَتَخۡشَوۡنَهُمۡۚ فَٱللَّهُ أَحَقُّ أَن تَخۡشَوۡهُ إِن كُنتُم مُّؤۡمِنِینَ ۝١٣", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "لا تترددوا في قتال هؤلاء القوم الذين نقضوا عهودهم، وعملوا على إخراج الرسول من (مكة)، وهم الذين بدؤوا بإيذائكم أول الأمر، أتخافونهم أو تخافون ملاقاتهم في الحرب؟ فالله أحق أن تخافوه إن كنتم مؤمنين حقًا.", "isBasmala": false, "translation_en": "Will you not fight a people who violated their oaths, and planned to exile the Messenger, and initiated hostilities against you? Do you fear them? It is God you should fear, if you are believers.", "translation_id": "Mengapakah kamu tidak memerangi orang-orang yang merusak sumpah (janjinya), padahal mereka telah keras kemauannya untuk mengusir Rasul dan merekalah yang pertama mulai memerangi kamu? Mengapakah kamu takut kepada mereka padahal Allah-lah yang berhak untuk kamu takuti, jika kamu benar-benar orang yang beriman.", "manzil": 2, "manzil_display": ""}], "189": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 14, "text": "قَـٰتِلُوهُمۡ یُعَذِّبۡهُمُ ٱللَّهُ بِأَیۡدِیكُمۡ وَیُخۡزِهِمۡ وَیَنصُرۡكُمۡ عَلَیۡهِمۡ وَیَشۡفِ صُدُورَ قَوۡمࣲ مُّؤۡمِنِینَ ۝١٤", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "يا معشر المؤمنين قاتلوا أعداء الله يعذبهم عز وجل بأيديكم، ويذلهم بالهزيمة والخزي، وينصركم عليهم، ويُعْلِ كلمته، ويشف بهزيمتهم صدوركم التي طالما لحق بها الحزن والغم من كيد هؤلاء المشركين، ويُذْهِب عن قلوب المؤمنين الغيظ. ومن تاب من هؤلاء المعاندين فإن الله يتوب على من يشاء. والله عليم بصدق توبة التائب، حكيم في تدبيره وصنعه ووَضْع تشريعاته لعباده.", "isBasmala": false, "translation_en": "Fight them. God will punish them at your hands, and humiliate them, and help you against them, and heal the hearts of a believing people.", "translation_id": "Perangilah mereka, niscaya Allah akan menghancurkan mereka dengan (perantaraan) tangan-tanganmu dan Allah akan menghinakan mereka dan menolong kamu terhadap mereka, serta melegakan hati orang-orang yang beriman.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 15, "text": "وَیُذۡهِبۡ غَیۡظَ قُلُوبِهِمۡۗ وَیَتُوبُ ٱللَّهُ عَلَىٰ مَن یَشَاۤءُۗ وَٱللَّهُ عَلِیمٌ حَكِیمٌ ۝١٥", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "يا معشر المؤمنين قاتلوا أعداء الله يعذبهم عز وجل بأيديكم، ويذلهم بالهزيمة والخزي، وينصركم عليهم، ويُعْلِ كلمته، ويشف بهزيمتهم صدوركم التي طالما لحق بها الحزن والغم من كيد هؤلاء المشركين، ويُذْهِب عن قلوب المؤمنين الغيظ. ومن تاب من هؤلاء المعاندين فإن الله يتوب على من يشاء. والله عليم بصدق توبة التائب، حكيم في تدبيره وصنعه ووَضْع تشريعاته لعباده.", "isBasmala": false, "translation_en": "And He will remove the anger of their hearts. God redeems whomever He wills. God is Knowledgeable and Wise.", "translation_id": "dan menghilangkan panas hati orang-orang mukmin. Dan Allah menerima taubat orang yang dikehendaki-Nya. Allah maha Mengetahui lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 16, "text": "أَمۡ حَسِبۡتُمۡ أَن تُتۡرَكُوا۟ وَلَمَّا یَعۡلَمِ ٱللَّهُ ٱلَّذِینَ جَـٰهَدُوا۟ مِنكُمۡ وَلَمۡ یَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلۡمُؤۡمِنِینَ وَلِیجَةࣰۚ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ ۝١٦", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "مِن سنة الله الابتلاء، فلا تظنوا يا معشر المؤمنين أن يترككم الله دون اختبار؛ ليعلم الله علمًا ظاهرًا للخلق الذين أخلصوا في جهادهم، ولم يتخذوا غير الله ورسوله والمؤمنين بطانة وأولياء. والله خبير بجميع أعمالكم ومجازيكم بها.", "isBasmala": false, "translation_en": "Or do you think that you will be left alone, without God identifying which of you will strive, and take no supporters apart from God, His Messenger, and the believers? God is well Aware of what you do.", "translation_id": "Apakah kamu mengira bahwa kamu akan dibiarkan, sedang Allah belum mengetahui (dalam kenyataan) orang-orang yang berjihad di antara kamu dan tidak mengambil menjadi teman yang setia selain Allah, Rasul-Nya dan orang-orang yang beriman. Dan Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 17, "text": "مَا كَانَ لِلۡمُشۡرِكِینَ أَن یَعۡمُرُوا۟ مَسَـٰجِدَ ٱللَّهِ شَـٰهِدِینَ عَلَىٰۤ أَنفُسِهِم بِٱلۡكُفۡرِۚ أُو۟لَـٰۤىِٕكَ حَبِطَتۡ أَعۡمَـٰلُهُمۡ وَفِی ٱلنَّارِ هُمۡ خَـٰلِدُونَ ۝١٧", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "ليس من شأن المشركين إعمار بيوت الله، وهم يعلنون كفرهم بالله ويجعلون له شركاء. هؤلاء المشركون بطلت أعمالهم يوم القيامة، ومصيرهم الخلود في النار.", "isBasmala": false, "translation_en": "It is not for the polytheists to attend God's places of worship while professing their disbelief. These-their works are in vain, and in the Fire they will abide.", "translation_id": "Tidaklah pantas orang-orang musyrik itu memakmurkan mesjid-mesjid Allah, sedang mereka mengakui bahwa mereka sendiri kafir. Itulah orang-orang yang sia-sia pekerjaannya, dan mereka kekal di dalam neraka.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 18, "text": "إِنَّمَا یَعۡمُرُ مَسَـٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ یَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰۤ أُو۟لَـٰۤىِٕكَ أَن یَكُونُوا۟ مِنَ ٱلۡمُهۡتَدِینَ ۝١٨", "juz": 10, "hizb": "(*½ ح 19*)", "tafsir": "لا يعتني ببيوت الله ويعمرها إلا الذين يؤمنون بالله واليوم الآخر، ويقيمون الصلاة ويؤتون الزكاة، ولا يخافون في الله لومة لائم، هؤلاء العُمَّار هم المهتدون إلى الحق.", "isBasmala": false, "translation_en": "The only people to attend God's places of worship are those who believe in God and the Last Day, and pray regularly, and practice regular charity, and fear none but God. These are most likely to be guided.", "translation_id": "Hanya yang memakmurkan masjid-masjid Allah ialah orang-orang yang beriman kepada Allah dan Hari kemudian, serta tetap mendirikan shalat, menunaikan zakat dan tidak takut (kepada siapapun) selain kepada Allah, maka merekalah orang-orang yang diharapkan termasuk golongan orang-orang yang mendapat petunjuk.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 19, "text": "۞ أَجَعَلۡتُمۡ سِقَایَةَ ٱلۡحَاۤجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَجَـٰهَدَ فِی سَبِیلِ ٱللَّهِۚ لَا یَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝١٩", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "أجعلتم -أيها القوم- ما تقومون به من سقي الحجيج وعِمارة المسجد الحرام كإيمان من آمن بالله واليوم الآخر وجاهد في سبيل الله؟ لا تتساوى حال المؤمنين وحال الكافرين عند الله، لأن الله لا يقبل عملا بغير الإيمان. والله سبحانه لا يوفق لأعمال الخير القوم الظالمين لأنفسهم بالكفر.", "isBasmala": false, "translation_en": "Do you consider giving water to pilgrims and maintaining the Sacred Mosque the same as believing in God and the Last Day and striving in God's path? They are not equal in God's sight. God does not guide the unjust people.", "translation_id": "Apakah (orang-orang) yang memberi minuman orang-orang yang mengerjakan haji dan mengurus Masjidilharam kamu samakan dengan orang-orang yang beriman kepada Allah dan hari kemudian serta bejihad di jalan Allah? Mereka tidak sama di sisi Allah; dan Allah tidak memberi petunjuk kepada kaum yang zalim.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 20, "text": "ٱلَّذِینَ ءَامَنُوا۟ وَهَاجَرُوا۟ وَجَـٰهَدُوا۟ فِی سَبِیلِ ٱللَّهِ بِأَمۡوَ ٰلِهِمۡ وَأَنفُسِهِمۡ أَعۡظَمُ دَرَجَةً عِندَ ٱللَّهِۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَاۤىِٕزُونَ ۝٢٠", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "الذين آمنوا بالله وتركوا دار الكفر قاصدين دار الإسلام، وبذلوا أموالهم وأنفسهم في الجهاد لإعلاء كلمة الله، هؤلاء أعظم درجه عند الله، وأولئك هم الفائزون برضوانه.", "isBasmala": false, "translation_en": "Those who believe, and emigrate, and strive in God's path with their possessions and their persons, are of a higher rank with God. These are the winners.", "translation_id": "orang-orang yang beriman dan berhijrah serta berjihad di jalan Allah dengan harta, benda dan diri mereka, adalah lebih tinggi derajatnya di sisi Allah; dan itulah orang-orang yang mendapat kemenangan.", "manzil": 2, "manzil_display": ""}], "190": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 21, "text": "یُبَشِّرُهُمۡ رَبُّهُم بِرَحۡمَةࣲ مِّنۡهُ وَرِضۡوَ ٰنࣲ وَجَنَّـٰتࣲ لَّهُمۡ فِیهَا نَعِیمࣱ مُّقِیمٌ ۝٢١", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "إن هؤلاء المؤمنين المهاجرين لهم البشرى من ربهم بالرحمة الواسعة والرضوان الذي لا سخط بعده، ومصيرهم إلى جنات الخلد والنعيم الدائم.", "isBasmala": false, "translation_en": "Their Lord announces to them good news of mercy from Him, and acceptance, and gardens wherein they will have lasting bliss.", "translation_id": "Tuhan mereka menggembirakan mereka dengan memberikan rahmat dari pada-Nya, keridhaan dan surga, mereka memperoleh didalamnya kesenangan yang kekal,", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 22, "text": "خَـٰلِدِینَ فِیهَاۤ أَبَدًاۚ إِنَّ ٱللَّهَ عِندَهُۥۤ أَجۡرٌ عَظِیمࣱ ۝٢٢", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "ماكثين في تلك الجنان لا نهاية لإقامتهم وتنعمهم، وذلك ثواب ما قدَّموه من الطاعات والعمل الصالح في حياتهم الدنيا. إن الله تعالى عنده أجر عظيم لمن آمن وعمل صالحا بامتثال أوامره واجتناب نواهيه.", "isBasmala": false, "translation_en": "Abiding therein forever. With God is a great reward.", "translation_id": "mereka kekal di dalamnya selama-lamanya. Sesungguhnya di sisi Allah-lah pahala yang besar.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 23, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوۤا۟ ءَابَاۤءَكُمۡ وَإِخۡوَ ٰنَكُمۡ أَوۡلِیَاۤءَ إِنِ ٱسۡتَحَبُّوا۟ ٱلۡكُفۡرَ عَلَى ٱلۡإِیمَـٰنِۚ وَمَن یَتَوَلَّهُم مِّنكُمۡ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ ۝٢٣", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تتخذوا أقرباءكم -من الآباء والإخوان وغيرهم- أولياء، تفشون إليهم أسرار المسلمين، وتستشيرونهم في أموركم، ما داموا على الكفر معادين للإسلام. ومن يتخذهم أولياء ويُلْقِ إليهم المودة فقد عصى الله تعالى، وظلم نفسه ظلمًا عظيمًا.", "isBasmala": false, "translation_en": "O you who believe! Do not ally yourselves with your parents and your siblings if they prefer disbelief to belief. Whoever of you allies himself with them-these are the wrongdoers.", "translation_id": "Hai orang-orang beriman, janganlah kamu jadikan bapa-bapa dan saudara-saudaramu menjadi wali(mu), jika mereka lebih mengutamakan kekafiran atas keimanan dan siapa di antara kamu yang menjadikan mereka wali, maka mereka itulah orang-orang yang zalim.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 24, "text": "قُلۡ إِن كَانَ ءَابَاۤؤُكُمۡ وَأَبۡنَاۤؤُكُمۡ وَإِخۡوَ ٰنُكُمۡ وَأَزۡوَ ٰجُكُمۡ وَعَشِیرَتُكُمۡ وَأَمۡوَ ٰلٌ ٱقۡتَرَفۡتُمُوهَا وَتِجَـٰرَةࣱ تَخۡشَوۡنَ كَسَادَهَا وَمَسَـٰكِنُ تَرۡضَوۡنَهَاۤ أَحَبَّ إِلَیۡكُم مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَجِهَادࣲ فِی سَبِیلِهِۦ فَتَرَبَّصُوا۟ حَتَّىٰ یَأۡتِیَ ٱللَّهُ بِأَمۡرِهِۦۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ ۝٢٤", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "قل -يا أيها الرسول- للمؤمنين: إن فَضَّلتم الآباء والأبناء والإخوان والزوجات والقرابات والأموال التي جمعتموها والتجارة التي تخافون عدم رواجها والبيوت الفارهة التي أقمتم فيها، إن فَضَّلتم ذلك على حب الله ورسوله والجهاد في سبيله فانتظروا عقاب الله ونكاله بكم. والله لا يوفق الخارجين عن طاعته.", "isBasmala": false, "translation_en": "Say, \"If your parents, and your children, and your siblings, and your spouses, and your relatives, and the wealth you have acquired, and a business you worry about, and homes you love, are more dear to you than God, and His Messenger, and the struggle in His cause, then wait until God executes His judgment.\" God does not guide the sinful people.", "translation_id": "Katakanlah: \"jika bapa-bapa, anak-anak, saudara-saudara, isteri-isteri, kaum keluargamu, harta kekayaan yang kamu usahakan, perniagaan yang kamu khawatiri kerugiannya, dan tempat tinggal yang kamu sukai, adalah lebih kamu cintai dari Allah dan Rasul-Nya dan dari berjihad di jalan-Nya, maka tunggulah sampai Allah mendatangkan keputusan-Nya\". Dan Allah tidak memberi petunjuk kepada orang-orang yang fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 25, "text": "لَقَدۡ نَصَرَكُمُ ٱللَّهُ فِی مَوَاطِنَ كَثِیرَةࣲ وَیَوۡمَ حُنَیۡنٍ إِذۡ أَعۡجَبَتۡكُمۡ كَثۡرَتُكُمۡ فَلَمۡ تُغۡنِ عَنكُمۡ شَیۡـࣰٔا وَضَاقَتۡ عَلَیۡكُمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ ثُمَّ وَلَّیۡتُم مُّدۡبِرِینَ ۝٢٥", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "لقد أنزل الله نَصْرَه عليكم في مواقع كثيرة عندما أخذتم بالأسباب وتوكلتم على الله. ويوم غزوة (حنين) قلتم: لن نُغْلَبَ اليوم0 من قلة، فغرَّتكم الكثرة فلم تنفعكم، وظهر عليكم العدو فلم تجدوا ملجأً في الأرض الواسعة ففررتم منهزمين.", "isBasmala": false, "translation_en": "God has given you victory in numerous regions; but on the day of Hunayn, your great number impressed you, but it availed you nothing; and the land, as spacious as it was, narrowed for you; and you turned your backs in retreat.", "translation_id": "Sesungguhnya Allah telah menolong kamu (hai para mukminin) di medan peperangan yang banyak, dan (ingatlah) peperangan Hunain, yaitu diwaktu kamu menjadi congkak karena banyaknya jumlah(mu), maka jumlah yang banyak itu tidak memberi manfaat kepadamu sedikitpun, dan bumi yang luas itu telah terasa sempit olehmu, kemudian kamu lari kebelakang dengan bercerai-berai.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 26, "text": "ثُمَّ أَنزَلَ ٱللَّهُ سَكِینَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِینَ وَأَنزَلَ جُنُودࣰا لَّمۡ تَرَوۡهَا وَعَذَّبَ ٱلَّذِینَ كَفَرُوا۟ۚ وَذَ ٰلِكَ جَزَاۤءُ ٱلۡكَـٰفِرِینَ ۝٢٦", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "ثم أنزل الله الطمأنينة على رسوله وعلى المؤمنين فثبتوا، وأمدَّهم بجنود من الملائكة لم يروها، فنصرهم على عدوهم، وعذَّب الذين كفروا. وتلك عقوبة الله للصادِّين عن دينه، المكذِّبين لرسوله.", "isBasmala": false, "translation_en": "Then God sent down His serenity upon His Messenger, and upon the believers; and He sent down troops you did not see; and He punished those who disbelieved. Such is the recompense of the disbelievers.", "translation_id": "Kemudian Allah menurunkan ketenangan kepada Rasul-Nya dan kepada orang-orang yang beriman, dan Allah menurunkan bala tentara yang kamu tiada melihatnya, dan Allah menimpakan bencana kepada orang-orang yang kafir, dan demikianlah pembalasan kepada orang-orang yang kafir.", "manzil": 2, "manzil_display": ""}], "191": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 27, "text": "ثُمَّ یَتُوبُ ٱللَّهُ مِنۢ بَعۡدِ ذَ ٰلِكَ عَلَىٰ مَن یَشَاۤءُۗ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٢٧", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "ومن رجع عن كفره بعد ذلك ودخل الإسلام فإن الله يقبل توبة مَن يشاء منهم، فيغفر ذنبه. والله غفور رحيم.", "isBasmala": false, "translation_en": "Then, after that, God will relent towards whomever He wills. God is Forgiving and Merciful.", "translation_id": "Sesudah itu Allah menerima taubat dari orang-orang yang dikehendaki-Nya. Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 28, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسࣱ فَلَا یَقۡرَبُوا۟ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ بَعۡدَ عَامِهِمۡ هَـٰذَاۚ وَإِنۡ خِفۡتُمۡ عَیۡلَةࣰ فَسَوۡفَ یُغۡنِیكُمُ ٱللَّهُ مِن فَضۡلِهِۦۤ إِن شَاۤءَۚ إِنَّ ٱللَّهَ عَلِیمٌ حَكِیمࣱ ۝٢٨", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "يا معشر المؤمنين إنما المشركون رِجْس وخَبَث فلا تمكنوهم من الاقتراب من الحرم بعد هذا العام التاسع من الهجرة، وإن خفتم فقرًا لانقطاع تجارتهم عنكم، فإن الله سيعوضكم عنها، ويكفيكم من فضله إن شاء، إن الله عليم بحالكم، حكيم في تدبير شؤونكم.", "isBasmala": false, "translation_en": "O you who believe! The polytheists are polluted, so let them not approach the Sacred Mosque after this year of theirs. And if you fear poverty, God will enrich you from His grace, if He wills. God is Aware and Wise.", "translation_id": "Hai orang-orang yang beriman, Sesungguhnya orang-orang yang musyrik itu najis, maka janganlah mereka mendekati Masjidilharam sesudah tahun ini. Dan jika kamu khawatir menjadi miskin, maka Allah nanti akan memberimu kekayaan kepadamu dari karunia-Nya, jika Dia menghendaki. Sesungguhnya Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 29, "text": "قَـٰتِلُوا۟ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَلَا یُحَرِّمُونَ مَا حَرَّمَ ٱللَّهُ وَرَسُولُهُۥ وَلَا یَدِینُونَ دِینَ ٱلۡحَقِّ مِنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ حَتَّىٰ یُعۡطُوا۟ ٱلۡجِزۡیَةَ عَن یَدࣲ وَهُمۡ صَـٰغِرُونَ ۝٢٩", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "أيها المسلمون قاتلوا الكفار الذين لا يؤمنون بالله، ولا يؤمنون بالبعث والجزاء، ولا يجتنبون ما نهى الله عنه ورسوله، ولا يلتزمون أحكام شريعة الإسلام من اليهود والنصارى، حتى يدفعوا الجزية التي تفرضونها عليهم بأيديهم خاضعين أذلاء.", "isBasmala": false, "translation_en": "Fight those who do not believe in God, nor in the Last Day, nor forbid what God and His Messenger have forbidden, nor abide by the religion of truth-from among those who received the Scripture-until they pay the due tax, willingly or unwillingly.", "translation_id": "Perangilah orang-orang yang tidak beriman kepada Allah dan tidak (pula) kepada hari kemudian, dan mereka tidak mengharamkan apa yang diharamkan oleh Allah dan Rasul-Nya dan tidak beragama dengan agama yang benar (agama Allah), (yaitu orang-orang) yang diberikan Al-Kitab kepada mereka, sampai mereka membayar jizyah dengan patuh sedang mereka dalam keadaan tunduk.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 30, "text": "وَقَالَتِ ٱلۡیَهُودُ عُزَیۡرٌ ٱبۡنُ ٱللَّهِ وَقَالَتِ ٱلنَّصَـٰرَى ٱلۡمَسِیحُ ٱبۡنُ ٱللَّهِۖ ذَ ٰلِكَ قَوۡلُهُم بِأَفۡوَ ٰهِهِمۡۖ یُضَـٰهِـُٔونَ قَوۡلَ ٱلَّذِینَ كَفَرُوا۟ مِن قَبۡلُۚ قَـٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ یُؤۡفَكُونَ ۝٣٠", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "لقد أشرك اليهود بالله عندما زعموا أن عزيرًا ابن الله. وأشرك النصارى بالله عندما ادَّعوا أن المسيح ابن الله. وهذا القول اختلقوه من عند أنفسهم، وهم بذلك لا يشابهون قول المشركين من قبلهم. قَاتَلَ الله المشركين جميعًا كيف يعدلون عن الحق إلى الباطل؟", "isBasmala": false, "translation_en": "The Jews said, \"Ezra is the son of God,\" and the Christians said, \"The Messiah is the son of God.\" These are their statements, out of their mouths. They emulate the statements of those who blasphemed before. May God assail them! How deceived they are!", "translation_id": "Orang-orang Yahudi berkata: \"Uzair itu putera Allah\" dan orang-orang Nasrani berkata: \"Al Masih itu putera Allah\". Demikianlah itu ucapan mereka dengan mulut mereka, mereka meniru perkataan orang-orang kafir yang terdahulu. Dilaknati Allah mereka, bagaimana mereka sampai berpaling?", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 31, "text": "ٱتَّخَذُوۤا۟ أَحۡبَارَهُمۡ وَرُهۡبَـٰنَهُمۡ أَرۡبَابࣰا مِّن دُونِ ٱللَّهِ وَٱلۡمَسِیحَ ٱبۡنَ مَرۡیَمَ وَمَاۤ أُمِرُوۤا۟ إِلَّا لِیَعۡبُدُوۤا۟ إِلَـٰهࣰا وَ ٰحِدࣰاۖ لَّاۤ إِلَـٰهَ إِلَّا هُوَۚ سُبۡحَـٰنَهُۥ عَمَّا یُشۡرِكُونَ ۝٣١", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "اتخذ اليهودُ والنصارى العلماءَ والعُبَّادَ أربابًا يُشَرِّعون لهم الأحكام، فيلتزمون بها ويتركون شرائع الله، واتخذوا المسيح عيسى ابن مريم إلهًا فعبدوه، وقد أمرهم الله بعبادته وحده دون غيره، فهو الإله الحق لا إله إلا هو. تنزَّه وتقدَّس عما يفتريه أهل الشرك والضلال.", "isBasmala": false, "translation_en": "They have taken their rabbis and their priests as lords instead of God, as well as the Messiah son of Mary. Although they were commanded to worship none but The One God. There is no god except He. Glory be to Him; High above what they associate with Him.", "translation_id": "Mereka menjadikan orang-orang alimnya dan rahib-rahib mereka sebagai tuhan selain Allah dan (juga mereka mempertuhankan) Al Masih putera Maryam, padahal mereka hanya disuruh menyembah Tuhan yang Esa, tidak ada Tuhan (yang berhak disembah) selain Dia. Maha suci Allah dari apa yang mereka persekutukan.", "manzil": 2, "manzil_display": ""}], "192": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 32, "text": "یُرِیدُونَ أَن یُطۡفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفۡوَ ٰهِهِمۡ وَیَأۡبَى ٱللَّهُ إِلَّاۤ أَن یُتِمَّ نُورَهُۥ وَلَوۡ كَرِهَ ٱلۡكَـٰفِرُونَ ۝٣٢", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "يريد الكفار بتكذيبهم أن يبطلوا دين الإسلام، ويبطلوا حجج الله وبراهينه على توحيده الذي جاء به محمد صلى الله عليه وسلم، ويأبى الله إلا أن يتم دينه ويظهره، ويعلي كلمته، ولو كره ذلك الجاحدون.", "isBasmala": false, "translation_en": "They want to extinguish God's light with their mouths, but God refuses except to complete His light, even though the disbelievers dislike it.", "translation_id": "Mereka berkehendak memadamkan cahaya (agama) Allah dengan mulut (ucapan-ucapan) mereka, dan Allah tidak menghendaki selain menyempurnakan cahaya-Nya, walaupun orang-orang yang kafir tidak menyukai.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 33, "text": "هُوَ ٱلَّذِیۤ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِینِ ٱلۡحَقِّ لِیُظۡهِرَهُۥ عَلَى ٱلدِّینِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ ۝٣٣", "juz": 10, "hizb": "(*¾ ح 19*)", "tafsir": "هو الذي أرسل رسوله محمدًا صلى الله عليه وسلم بالقرآن ودين الإسلام؛ ليعليه على الأديان كلها، ولو كره المشركون دين الحق -الإسلام- وظهوره على الأديان.", "isBasmala": false, "translation_en": "It is He who sent His Messenger with the guidance and the religion of truth, in order to make it prevail over all religions, even though the idolaters dislike it.", "translation_id": "Dialah yang telah mengutus Rasul-Nya (dengan membawa) petunjuk (Al-Quran) dan agama yang benar untuk dimenangkan-Nya atas segala agama, walaupun orang-orang musyrikin tidak menyukai.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 34, "text": "۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ كَثِیرࣰا مِّنَ ٱلۡأَحۡبَارِ وَٱلرُّهۡبَانِ لَیَأۡكُلُونَ أَمۡوَ ٰلَ ٱلنَّاسِ بِٱلۡبَـٰطِلِ وَیَصُدُّونَ عَن سَبِیلِ ٱللَّهِۗ وَٱلَّذِینَ یَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا یُنفِقُونَهَا فِی سَبِیلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابٍ أَلِیمࣲ ۝٣٤", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه، إن كثيرًا من علماء أهل الكتاب وعُبَّادهم ليأخذون أموال الناس بغير حق كالرشوة وغيرها، ويمنعون الناس من الدخول في الإسلام، ويصدون عن سبيل الله. والذين يمسكون الأموال، ولا يؤدون زكاتها، ولا يُخْرجون منها الحقوق الواجبة، فبشِّرهم بعذاب موجع.", "isBasmala": false, "translation_en": "O you who believe! Many of the rabbis and priests consume people's wealth illicitly, and hinder from God's path. Those who hoard gold and silver, and do not spend them in God's cause, inform them of a painful punishment.", "translation_id": "Hai orang-orang yang beriman, sesungguhnya sebahagian besar dari orang-orang alim Yahudi dan rahib-rahib Nasrani benar-benar memakan harta orang dengan jalan batil dan mereka menghalang-halangi (manusia) dari jalan Allah. Dan orang-orang yang menyimpan emas dan perak dan tidak menafkahkannya pada jalan Allah, maka beritahukanlah kepada mereka, (bahwa mereka akan mendapat) siksa yang pedih,", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 35, "text": "یَوۡمَ یُحۡمَىٰ عَلَیۡهَا فِی نَارِ جَهَنَّمَ فَتُكۡوَىٰ بِهَا جِبَاهُهُمۡ وَجُنُوبُهُمۡ وَظُهُورُهُمۡۖ هَـٰذَا مَا كَنَزۡتُمۡ لِأَنفُسِكُمۡ فَذُوقُوا۟ مَا كُنتُمۡ تَكۡنِزُونَ ۝٣٥", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "يوم القيامة توضع قطع الذهب والفضة في النار، فإذا اشتدت حرارتها أُحرقت بها جباه أصحابها وجنوبهم وظهورهم. وقيل لهم توبيخًا: هذا مالكم الذي أمسكتموه ومنعتم منه حقوق الله، فذوقوا العذاب الموجع؛ بسبب كنزكم وإمساككم.", "isBasmala": false, "translation_en": "On the Day when they will be heated in the Fire of Hell, then their foreheads, and their sides, and their backs will be branded with them: \"This is what you hoarded for yourselves; so taste what you used to hoard.\"", "translation_id": "pada hari dipanaskan emas perak itu dalam neraka jahannam, lalu dibakar dengannya dahi mereka, lambung dan punggung mereka (lalu dikatakan) kepada mereka: \"Inilah harta bendamu yang kamu simpan untuk dirimu sendiri, maka rasakanlah sekarang (akibat dari) apa yang kamu simpan itu\".", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 36, "text": "إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرࣰا فِی كِتَـٰبِ ٱللَّهِ یَوۡمَ خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ مِنۡهَاۤ أَرۡبَعَةٌ حُرُمࣱۚ ذَ ٰلِكَ ٱلدِّینُ ٱلۡقَیِّمُۚ فَلَا تَظۡلِمُوا۟ فِیهِنَّ أَنفُسَكُمۡۚ وَقَـٰتِلُوا۟ ٱلۡمُشۡرِكِینَ كَاۤفَّةࣰ كَمَا یُقَـٰتِلُونَكُمۡ كَاۤفَّةࣰۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِینَ ۝٣٦", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "إنّ عدة الشهور في حكم الله وفيما كُتب في اللوح المحفوظ اثنا عشر شهرًا، يوم خلق السموات والأرض، منها أربعة حُرُم؛ حرَّم الله فيهنَّ القتال (هي: ذو القعدة وذو الحجة والمحرم ورجب) ذلك هو الدين المستقيم، فلا تظلموا فيهن أنفسكم؛ لزيادة تحريمها، وكون الظلم فيها أشد منه في غيرها، لا أنَّ الظلم في غيرها جائز. وقاتلوا المشركين جميعًا كما يقاتلونكم جميعًا، واعلموا أن الله مع أهل التقوى بتأييده ونصره.", "isBasmala": false, "translation_en": "The number of months, according to God, is twelve months-in the decree of God-since the Day He created the heavens and the earth, of which four are sacred. This is the correct religion. So do not wrong yourselves during them. And fight the polytheists collectively, as they fight you collectively, and know that God is with the righteous.", "translation_id": "Sesungguhnya bilangan bulan pada sisi Allah adalah dua belas bulan, dalam ketetapan Allah di waktu Dia menciptakan langit dan bumi, di antaranya empat bulan haram. Itulah (ketetapan) agama yang lurus, maka janganlah kamu menganiaya diri kamu dalam bulan yang empat itu, dan perangilah kaum musyrikin itu semuanya sebagaimana merekapun memerangi kamu semuanya, dan ketahuilah bahwasanya Allah beserta orang-orang yang bertakwa.", "manzil": 2, "manzil_display": ""}], "193": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 37, "text": "إِنَّمَا ٱلنَّسِیۤءُ زِیَادَةࣱ فِی ٱلۡكُفۡرِۖ یُضَلُّ بِهِ ٱلَّذِینَ كَفَرُوا۟ یُحِلُّونَهُۥ عَامࣰا وَیُحَرِّمُونَهُۥ عَامࣰا لِّیُوَاطِـُٔوا۟ عِدَّةَ مَا حَرَّمَ ٱللَّهُ فَیُحِلُّوا۟ مَا حَرَّمَ ٱللَّهُۚ زُیِّنَ لَهُمۡ سُوۤءُ أَعۡمَـٰلِهِمۡۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡكَـٰفِرِینَ ۝٣٧", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "إن الذي كانت تفعله العرب في الجاهلية من تحريم أربعة أشهر من السنة عددًا لا تحديدًا بأسماء الأشهر التي حرَّمها الله، فيؤخرون بعضها أو يقدِّمونه ويجعلون مكانه من أشهر الحل ما أرادوا حسب حاجتهم للقتال، إن ذلك زيادة في الكفر، يضل الشيطان به الذين كفروا، يحلون الذي أخروا تحريمه من الأشهر الأربعة عامًا، ويحرمونه عاما؛ ليوافقوا عدد الشهور الأربعة، فيحلوا ما حرَّم الله منها. زَيَّن لهم الشيطان الأعمال السيئة. والله لا يوفق القوم الكافرين إلى الحق والصواب.", "isBasmala": false, "translation_en": "Postponement is an increase in disbelief-by which those who disbelieve are led astray. They allow it one year, and forbid it another year, in order to conform to the number made sacred by God, thus permitting what God has forbidden. The evil of their deeds seems good to them. God does not guide the disbelieving people.", "translation_id": "Sesungguhnya mengundur-undurkan bulan haram itu adalah menambah kekafiran. Disesatkan orang-orang yang kafir dengan mengundur-undurkan itu, mereka menghalalkannya pada suatu tahun dan mengharamkannya pada tahun yang lain, agar mereka dapat mempersesuaikan dengan bilangan yang Allah mengharamkannya, maka mereka menghalalkan apa yang diharamkan Allah. (Syaitan) menjadikan mereka memandang perbuatan mereka yang buruk itu. Dan Allah tidak memberi petunjuk kepada orang-orang yang kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 38, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ مَا لَكُمۡ إِذَا قِیلَ لَكُمُ ٱنفِرُوا۟ فِی سَبِیلِ ٱللَّهِ ٱثَّاقَلۡتُمۡ إِلَى ٱلۡأَرۡضِۚ أَرَضِیتُم بِٱلۡحَیَوٰةِ ٱلدُّنۡیَا مِنَ ٱلۡـَٔاخِرَةِۚ فَمَا مَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا فِی ٱلۡـَٔاخِرَةِ إِلَّا قَلِیلٌ ۝٣٨", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، ما بالكم إذا قيل لكم: اخرجوا إلى الجهاد في سبيل الله لقتال أعدائكم تكاسلتم ولزمتم مساكنكم؟ هل آثرتم حظوظكم الدنيوية على نعيم الآخرة؟ فما تستمتعون به في الدنيا قليل زائل، أما نعيم الآخرة الذي أعده الله للمؤمنين المجاهدين فكثير دائم.", "isBasmala": false, "translation_en": "O you who believe! What is the matter with you, when it is said to you, \"Mobilize in the cause of God,\" you cling heavily to the earth? Do you prefer the present life to the Hereafter? The enjoyment of the present life, compared to the Hereafter, is only a little.", "translation_id": "Hai orang-orang yang beriman, apakah sebabnya bila dikatakan kepadamu: \"Berangkatlah (untuk berperang) pada jalan Allah\" kamu merasa berat dan ingin tinggal di tempatmu? Apakah kamu puas dengan kehidupan di dunia sebagai ganti kehidupan di akhirat? Padahal kenikmatan hidup di dunia ini (dibandingkan dengan kehidupan) diakhirat hanyalah sedikit.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 39, "text": "إِلَّا تَنفِرُوا۟ یُعَذِّبۡكُمۡ عَذَابًا أَلِیمࣰا وَیَسۡتَبۡدِلۡ قَوۡمًا غَیۡرَكُمۡ وَلَا تَضُرُّوهُ شَیۡـࣰٔاۗ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝٣٩", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "إن لا تنفروا أيها المؤمنون إلى قتال عدوكم ينزلِ الله عقوبته بكم، ويأت بقوم آخرين ينفرون إذ ا استُنْفروا، ويطيعون الله ورسوله، ولن تضروا الله شيئًا بتولِّيكم عن الجهاد، فهو الغني عنكم وأنتم الفقراء إليه. وما يريده الله يكون لا محالة. والله على كل شيء قدير من نصر دينه ونبيه دونكم.", "isBasmala": false, "translation_en": "Unless you mobilize, He will punish you most painfully, and will replace you with another people, and you will not harm Him at all. God has power over all things.", "translation_id": "Jika kamu tidak berangkat untuk berperang, niscaya Allah menyiksa kamu dengan siksa yang pedih dan digantinya (kamu) dengan kaum yang lain, dan kamu tidak akan dapat memberi kemudharatan kepada-Nya sedikitpun. Allah Maha Kuasa atas segala sesuatu.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 40, "text": "إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِینَ كَفَرُوا۟ ثَانِیَ ٱثۡنَیۡنِ إِذۡ هُمَا فِی ٱلۡغَارِ إِذۡ یَقُولُ لِصَـٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِینَتَهُۥ عَلَیۡهِ وَأَیَّدَهُۥ بِجُنُودࣲ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِینَ كَفَرُوا۟ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِیَ ٱلۡعُلۡیَاۗ وَٱللَّهُ عَزِیزٌ حَكِیمٌ ۝٤٠", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "يا معشر أصحاب رسول الله صلى الله عليه وسلم إن لا تنفروا معه أيها المؤمنون إذا استَنْفَركم، وإن لا تنصروه؛ فقد أيده الله ونصره يوم أخرجه الكفار من قريش من بلده (مكة)، وهو ثاني اثنين (هو وأبو بكر الصديق رضي الله عنه) وألجؤوهما إلى نقب في جبل ثور \"بمكة\"، فمكثا فيه ثلاث ليال، إذ يقول لصاحبه (أبي بكر) لما رأى منه الخوف عليه: لا تحزن إن الله معنا بنصره وتأييده، فأنزل الله الطمأنينة في قلب رسول الله صلى الله عليه وسلم، وأعانه بجنود لم يرها أحد من البشر وهم الملائكة، فأنجاه الله من عدوه وأذل الله أعداءه، وجعل كلمة الذين كفروا السفلى. وكلمةُ الله هي العليا،، ذلك بإعلاء شأن الإسلام. والله عزيز في ملكه، حكيم في تدبير شؤون عباده. وفي هذه الآية منقبة عظيمة لأبي بكر الصديق رضي الله عنه.", "isBasmala": false, "translation_en": "If you do not help him, God has already helped him, when those who disbelieved expelled him, and he was the second of two in the cave. He said to his friend, \"Do not worry, God is with us.\" And God made His tranquility descend upon him, and supported him with forces you did not see, and made the word of those who disbelieved the lowest, while the Word of God is the Highest. God is Mighty and Wise.", "translation_id": "Jikalau kamu tidak menolongnya (Muhammad) maka sesungguhnya Allah telah menolongnya (yaitu) ketika orang-orang kafir (musyrikin Mekah) mengeluarkannya (dari Mekah) sedang dia salah seorang dari dua orang ketika keduanya berada dalam gua, di waktu dia berkata kepada temannya: \"Janganlah kamu berduka cita, sesungguhnya Allah beserta kita\". Maka Allah menurunkan keterangan-Nya kepada (Muhammad) dan membantunya dengan tentara yang kamu tidak melihatnya, dan Al-Quran menjadikan orang-orang kafir itulah yang rendah. Dan kalimat Allah itulah yang tinggi. Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}], "194": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 41, "text": "ٱنفِرُوا۟ خِفَافࣰا وَثِقَالࣰا وَجَـٰهِدُوا۟ بِأَمۡوَ ٰلِكُمۡ وَأَنفُسِكُمۡ فِی سَبِیلِ ٱللَّهِۚ ذَ ٰلِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ۝٤١", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "اخرجوا -أيها المؤمنون- للجهاد في سبيل الله شبابًا وشيوخًا في العسر واليسر، على أي حال كنتم، وأنفقوا أموالكم في سبيل الله، وقاتلوا بأيديكم لإعلاء كلمة الله، ذلك الخروج والبذل خير لكم في حالكم ومآلكم فافعلوا ذلك وانفروا واستجيبوا لله ورسوله.", "isBasmala": false, "translation_en": "Mobilize, light or heavy, and strive with your possessions and your lives in the cause of God. That is better for you, if you only knew.", "translation_id": "Berangkatlah kamu baik dalam keadaan merasa ringan maupun berat, dan berjihadlah kamu dengan harta dan dirimu di jalan Allah. Yang demikian itu adalah lebih baik bagimu, jika kamu mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 42, "text": "لَوۡ كَانَ عَرَضࣰا قَرِیبࣰا وَسَفَرࣰا قَاصِدࣰا لَّٱتَّبَعُوكَ وَلَـٰكِنۢ بَعُدَتۡ عَلَیۡهِمُ ٱلشُّقَّةُۚ وَسَیَحۡلِفُونَ بِٱللَّهِ لَوِ ٱسۡتَطَعۡنَا لَخَرَجۡنَا مَعَكُمۡ یُهۡلِكُونَ أَنفُسَهُمۡ وَٱللَّهُ یَعۡلَمُ إِنَّهُمۡ لَكَـٰذِبُونَ ۝٤٢", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "وبَّخ الله جلَّ جلاله جماعة من المنافقين استأذنوا رسول الله صلى الله عليه وسلم في التخلف عن غزوة (تبوك) مبينًا أنه لو كان خروجهم إلى غنيمة قريبة سهلة المنال لاتبعوك، ولكن لما دعوا إلى قتال الروم في أطراف بلاد (الشام) في وقت الحر تخاذلوا، وتخلفوا، وسيعتذرون لتخلفهم عن الخروج حالفين بأنهم لا يستطيعون ذلك، يهلكون أنفسهم بالكذب والنفاق، والله يعلم إنهم لكاذبون فيما يبدون لك من الأعذار.", "isBasmala": false, "translation_en": "Had the gain been immediate, and the journey shorter, they would have followed you; but the distance seemed too long for them. Still they swear by God: \"Had we been able, we would have marched out with you.\" They damn their own souls, and God knows that they are lying.", "translation_id": "Kalau yang kamu serukan kepada mereka itu keuntungan yang mudah diperoleh dan perjalanan yang tidak seberapa jauh, pastilah mereka mengikutimu, tetapi tempat yang dituju itu amat jauh terasa oleh mereka. Mereka akan bersumpah dengan (nama) Allah: \"Jikalau kami sanggup tentulah kami berangkat bersama-samamu\". Mereka membinasakan diri mereka sendiri dan Allah mengetahui bahwa sesungguhnya mereka benar-benar orang-orang yang berdusta.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 43, "text": "عَفَا ٱللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمۡ حَتَّىٰ یَتَبَیَّنَ لَكَ ٱلَّذِینَ صَدَقُوا۟ وَتَعۡلَمَ ٱلۡكَـٰذِبِینَ ۝٤٣", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "عفا الله عنك -أيها النبي- عمَّا وقع منك مِن تَرْك الأولى والأكمل، وهو إذنك للمنافقين في القعود عن الجهاد، لأي سبب أَذِنْتَ لهؤلاء بالتخلف عن الغزوة، حتى يظهر لك الذين صدقوا في اعتذارهم وتعلم الكاذبين منهم في ذلك؟", "isBasmala": false, "translation_en": "May God pardon you! Why did you give them permission before it became clear to you who are the truthful ones, and who are the liars?", "translation_id": "Semoga Allah memaafkanmu. Mengapa kamu memberi izin kepada mereka (untuk tidak pergi berperang), sebelum jelas bagimu orang-orang yang benar (dalam keuzurannya) dan sebelum kamu ketahui orang-orang yang berdusta?", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 44, "text": "لَا یَسۡتَـٔۡذِنُكَ ٱلَّذِینَ یُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ أَن یُجَـٰهِدُوا۟ بِأَمۡوَ ٰلِهِمۡ وَأَنفُسِهِمۡۗ وَٱللَّهُ عَلِیمُۢ بِٱلۡمُتَّقِینَ ۝٤٤", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "ليس من شأن المؤمنين بالله ورسوله واليوم الآخر أن يستأذنوك -أيها النبي- في التخلف عن الجهاد في سبيل الله بالنفس والمال، وإنما هذا من شأن المنافقين. والله عليم بمن خافه فاتقاه بأداء فرائضه واجتناب نواهيه.", "isBasmala": false, "translation_en": "Those who believe in God and the Last Day do not ask you for exemption from striving with their possessions and their lives. God is fully aware of the righteous.", "translation_id": "Orang-orang yang beriman kepada Allah dan hari kemudian, tidak akan meminta izin kepadamu untuk tidak ikut berjihad dengan harta dan diri mereka. Dan Allah mengetahui orang-orang yang bertakwa.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 45, "text": "إِنَّمَا یَسۡتَـٔۡذِنُكَ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَٱرۡتَابَتۡ قُلُوبُهُمۡ فَهُمۡ فِی رَیۡبِهِمۡ یَتَرَدَّدُونَ ۝٤٥", "juz": 10, "hizb": "(* ح 20*)", "tafsir": "إنما يطلب الإذن للتخلف عن الجهاد الذين لا يصدِّقون بالله ولا باليوم الآخر، ولا يعملون صالحًا، وشكَّتْ قلوبهم في صحة ما جئت به -أيها النبي- من الإسلام وشرائعه، فهم في شكهم يتحيَّرون.", "isBasmala": false, "translation_en": "Only those who do not believe in God and the Last Day ask you for exemption. Their hearts are full of doubts, so they waver in their doubts.", "translation_id": "Sesungguhnya yang akan meminta izin kepadamu, hanyalah orang-orang yang tidak beriman kepada Allah dan hari kemudian, dan hati mereka ragu-ragu, karena itu mereka selalu bimbang dalam keraguannya.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 46, "text": "۞ وَلَوۡ أَرَادُوا۟ ٱلۡخُرُوجَ لَأَعَدُّوا۟ لَهُۥ عُدَّةࣰ وَلَـٰكِن كَرِهَ ٱللَّهُ ٱنۢبِعَاثَهُمۡ فَثَبَّطَهُمۡ وَقِیلَ ٱقۡعُدُوا۟ مَعَ ٱلۡقَـٰعِدِینَ ۝٤٦", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "ولو أراد المنافقون الخروج معك -أيها النبي- إلى الجهاد لتأهَّبوا له بالزاد والراحلة، ولكن الله كره خروجهم فثَقُلَ عليهم الخروج قضاء وقدرًا، وإن كان أمرهم به شرعا، وقيل لهم: تخلفوا مع القاعدين من المرضى والضعفاء والنساء والصبيان.", "isBasmala": false, "translation_en": "Had they wanted to mobilize, they would have made preparations for it; but God disliked their participation, so he held them back, and it was said, \"Stay behind with those who stay behind.\"", "translation_id": "Dan jika mereka mau berangkat, tentulah mereka menyiapkan persiapan untuk keberangkatan itu, tetapi Allah tidak menyukai keberangkatan mereka, maka Allah melemahkan keinginan mereka. dan dikatakan kepada mereka: \"Tinggallah kamu bersama orang-orang yang tinggal itu\".", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 47, "text": "لَوۡ خَرَجُوا۟ فِیكُم مَّا زَادُوكُمۡ إِلَّا خَبَالࣰا وَلَأَوۡضَعُوا۟ خِلَـٰلَكُمۡ یَبۡغُونَكُمُ ٱلۡفِتۡنَةَ وَفِیكُمۡ سَمَّـٰعُونَ لَهُمۡۗ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ ۝٤٧", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "لو خرج المنافقون معكم -أيها المؤمنون- للجهاد لنشروا الاضطراب في الصفوف والشر والفساد، ولأسرعوا السير بينكم بالنميمة والبغضاء، يبغون فتنتكم بتثبيطكم عن الجهاد في سبيل الله، وفيكم -أيها المؤمنون- عيون لهم يسمعون أخباركم، وينقلونها إليهم. والله عليم بهؤلاء المنافقين الظالمين، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "Had they mobilized with you, they would have added only to your difficulties, and they would have spread rumors in your midst, trying to sow discord among you. Some of you are avid listeners to them. God is Aware of the wrongdoers.", "translation_id": "Jika mereka berangkat bersama-sama kamu, niscaya mereka tidak menambah kamu selain dari kerusakan belaka, dan tentu mereka akan bergegas maju ke muka di celah-celah barisanmu, untuk mengadakan kekacauan di antara kamu; sedang di antara kamu ada orang-orang yang amat suka mendengarkan perkataan mereka. Dan Allah mengetahui orang-orang yang zalim.", "manzil": 2, "manzil_display": ""}], "195": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 48, "text": "لَقَدِ ٱبۡتَغَوُا۟ ٱلۡفِتۡنَةَ مِن قَبۡلُ وَقَلَّبُوا۟ لَكَ ٱلۡأُمُورَ حَتَّىٰ جَاۤءَ ٱلۡحَقُّ وَظَهَرَ أَمۡرُ ٱللَّهِ وَهُمۡ كَـٰرِهُونَ ۝٤٨", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "لقد ابتغى المنافقون فتنة المؤمنين عن دينهم وصدهم عن سبيل الله من قبل غزوة (تبوك)، وكشف أمرهم، وصرَّفوا لك -أيها النبي- الأمور في إبطال ما جئت به، كما فعلوا يوم (أحد) ويوم (الخندق)، ودبَّروا لك الكيد حتى جاء النصر من عند الله، وأعز جنده ونصر دينه، وهم كارهون له.", "isBasmala": false, "translation_en": "They tried to cause conflict before, and they hatched plots against you, until the truth prevailed, and the command of God became evident-in spite of their dislike.", "translation_id": "Sesungguhnya dari dahulupun mereka telah mencari-cari kekacauan dan mereka mengatur pelbagai macam tipu daya untuk (merusakkan)mu, hingga datanglah kebenaran (pertolongan Allah) dan menanglah agama Allah, padahal mereka tidak menyukainya.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 49, "text": "وَمِنۡهُم مَّن یَقُولُ ٱئۡذَن لِّی وَلَا تَفۡتِنِّیۤۚ أَلَا فِی ٱلۡفِتۡنَةِ سَقَطُوا۟ۗ وَإِنَّ جَهَنَّمَ لَمُحِیطَةُۢ بِٱلۡكَـٰفِرِینَ ۝٤٩", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "ومِن هؤلاء المنافقين من يطلب الإذن للقعود عن الجهاد ويقول: لا توقعْني في الابتلاء بما يعرض لي في حالة الخروج من فتنة النساء. لقد سقط هؤلاء المنافقون في فتنة النفاق الكبرى. فإن جهنم لمحيطة بالكافرين بالله واليوم الآخر، فلا يُفْلِت منهم أحد.", "isBasmala": false, "translation_en": "Among them is he who says, \"Excuse me, and do not trouble me.\" In fact, they sunk into trouble. In fact, Hell will engulf the disbelievers.", "translation_id": "Di antara mereka ada orang yang berkata: \"Berilah saya keizinan (tidak pergi berperang) dan janganlah kamu menjadikan saya terjerumus dalam fitnah\". Ketahuilah bahwa mereka telah terjerumus ke dalam fitnah. Dan sesungguhnya Jahannam itu benar-benar meliputi orang-orang yang kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 50, "text": "إِن تُصِبۡكَ حَسَنَةࣱ تَسُؤۡهُمۡۖ وَإِن تُصِبۡكَ مُصِیبَةࣱ یَقُولُوا۟ قَدۡ أَخَذۡنَاۤ أَمۡرَنَا مِن قَبۡلُ وَیَتَوَلَّوا۟ وَّهُمۡ فَرِحُونَ ۝٥٠", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "إن يصبك -أيها النبي- سرور وغنيمة يحزن المنافقون، وإن يلحق بك مكروه من هزيمة أو شدة يقولوا: نحن أصحاب رأي وتدبير قد احتطنا لأنفسنا بتخلفنا عن محمد، وينصرفوا وهم مسرورون بما صنعوا وبما أصابك من السوء.", "isBasmala": false, "translation_en": "If something good happens to you, it upsets them; and if a calamity befalls you, they say, \"We took our precautions in advance,\" and they depart, happy.", "translation_id": "Jika kamu mendapat suatu kebaikan, mereka menjadi tidak senang karenanya; dan jika kamu ditimpa oleh sesuatu bencana, mereka berkata: \"Sesungguhnya kami sebelumnya telah memperhatikan urusan kami (tidak pergi perang)\" dan mereka berpaling dengan rasa gembira.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 51, "text": "قُل لَّن یُصِیبَنَاۤ إِلَّا مَا كَتَبَ ٱللَّهُ لَنَا هُوَ مَوۡلَىٰنَاۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ۝٥١", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "قل -أيها النبي- لهؤلاء المتخاذلين زجرًا لهم وتوبيخًا: لن يصيبنا إلا ما قدَّره الله علينا وكتبه في اللوح المحفوظ، هو ناصرنا على أعدائنا، وعلى الله، وحده فليعتمد المؤمنون به.", "isBasmala": false, "translation_en": "Say, \"Nothing will happen to us except what God has ordained for us; He is our Protector.\" In God let the faithful put their trust.", "translation_id": "Katakanlah: \"Sekali-kali tidak akan menimpa kami melainkan apa yang telah ditetapkan Allah untuk kami. Dialah Pelindung kami, dan hanya kepada Allah orang-orang yang beriman harus bertawakal\".", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 52, "text": "قُلۡ هَلۡ تَرَبَّصُونَ بِنَاۤ إِلَّاۤ إِحۡدَى ٱلۡحُسۡنَیَیۡنِۖ وَنَحۡنُ نَتَرَبَّصُ بِكُمۡ أَن یُصِیبَكُمُ ٱللَّهُ بِعَذَابࣲ مِّنۡ عِندِهِۦۤ أَوۡ بِأَیۡدِینَاۖ فَتَرَبَّصُوۤا۟ إِنَّا مَعَكُم مُّتَرَبِّصُونَ ۝٥٢", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "قل لهم -أيها النبي-: هل تنتظرون بنا إلا شهادة أو ظفرًا بكم؟ ونحن ننتظر بكم أن يصيبكم الله بعقوبة مِن عنده عاجلة تهلككم أو بأيدينا فنقتلكم، فانتظروا إنا معكم منتظرون ما الله فاعل بكل فريق منا ومنكم.", "isBasmala": false, "translation_en": "Say, \"Are you expecting for us anything other than one of the two excellences? As for us: we are expecting that God will afflict you with a punishment from Himself, or at our hands. So wait, we are waiting with you.\"", "translation_id": "Katakanlah: \"tidak ada yang kamu tunggu-tunggu bagi kami, kecuali salah satu dari dua kebaikan. Dan Kami menunggu-nunggu bagi kamu bahwa Allah akan menimpakan kepadamu azab (yang besar) dari sisi-Nya. Sebab itu tunggulah, sesungguhnya kami menunggu-nunggu bersamamu\".", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 53, "text": "قُلۡ أَنفِقُوا۟ طَوۡعًا أَوۡ كَرۡهࣰا لَّن یُتَقَبَّلَ مِنكُمۡ إِنَّكُمۡ كُنتُمۡ قَوۡمࣰا فَـٰسِقِینَ ۝٥٣", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "قل -أيها النبي- للمنافقين: أنفقوا أموالكم كيف شئتم، وعلى أي حال شئتم طائعين أو كارهين، لن يقبل الله منكم نفقاتكم؛ لأنكم قوم خارجون عن دين الله وطاعته.", "isBasmala": false, "translation_en": "Say, \"Whether you spend willingly or unwillingly, it will not be accepted from you. You are evil people.\"", "translation_id": "Katakanlah: \"Nafkahkanlah hartamu, baik dengan sukarela ataupun dengan terpaksa, namun nafkah itu sekali-kali tidak akan diterima dari kamu. Sesungguhnya kamu adalah orang-orang yang fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 54, "text": "وَمَا مَنَعَهُمۡ أَن تُقۡبَلَ مِنۡهُمۡ نَفَقَـٰتُهُمۡ إِلَّاۤ أَنَّهُمۡ كَفَرُوا۟ بِٱللَّهِ وَبِرَسُولِهِۦ وَلَا یَأۡتُونَ ٱلصَّلَوٰةَ إِلَّا وَهُمۡ كُسَالَىٰ وَلَا یُنفِقُونَ إِلَّا وَهُمۡ كَـٰرِهُونَ ۝٥٤", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "وسبب عدم قَبول نفقاتهم أنهم أضمروا الكفر بالله عز وجل وتكذيب رسوله محمد صلى الله عليه وسلم، ولا يأتون الصلاة إلا وهم متثاقلون، ولا ينفقون الأموال إلا وهم كارهون، فهم لا يرجون ثواب هذه الفرائض، ولا يخشون على تركها عقابًا بسبب كفرهم.", "isBasmala": false, "translation_en": "What prevents the acceptance of their contributions is nothing but the fact that they disbelieved in God and His Messenger, and that they do not approach the prayer except lazily, and that they do not spend except grudgingly.", "translation_id": "Dan tidak ada yang menghalangi mereka untuk diterima dari mereka nafkah-nafkahnya melainkan karena mereka kafir kepada Allah dan Rasul-Nya dan mereka tidak mengerjakan sembahyang, melainkan dengan malas dan tidak (pula) menafkahkan (harta) mereka, melainkan dengan rasa enggan.", "manzil": 2, "manzil_display": ""}], "196": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 55, "text": "فَلَا تُعۡجِبۡكَ أَمۡوَ ٰلُهُمۡ وَلَاۤ أَوۡلَـٰدُهُمۡۚ إِنَّمَا یُرِیدُ ٱللَّهُ لِیُعَذِّبَهُم بِهَا فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَـٰفِرُونَ ۝٥٥", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "فلا تعجبك -أيها النبي- أموال هؤلاء المنافقين ولا أولادهم، إنما يريد الله أن يعذبهم بها في الحياة الدنيا بالتعب في تحصيلها وبالمصائب التي تقع فيها، حيث لا يحتسبون ذلك عند الله، وتخرج أنفسهم، فيموتوا على كفرهم بالله ورسوله.", "isBasmala": false, "translation_en": "Let neither their possessions nor their children impress you. God intends to torment them through them in this worldly life, and that their souls depart while they are disbelievers.", "translation_id": "Maka janganlah harta benda dan anak-anak mereka menarik hatimu. Sesungguhnya Allah menghendaki dengan (memberi) harta benda dan anak-anak itu untuk menyiksa mereka dalam kehidupan di dunia dan kelak akan melayang nyawa mereka, sedang mereka dalam keadaan kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 56, "text": "وَیَحۡلِفُونَ بِٱللَّهِ إِنَّهُمۡ لَمِنكُمۡ وَمَا هُم مِّنكُمۡ وَلَـٰكِنَّهُمۡ قَوۡمࣱ یَفۡرَقُونَ ۝٥٦", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "ويحلف هؤلاء المنافقون بالله لكم أيها المؤمنون كذبًا وباطلا إنهم لمنكم، وليسوا منكم، ولكنهم قوم يخافون فيحلفون تَقِيَّة لكم.", "isBasmala": false, "translation_en": "They swear by God that they are of you. But they are not of you. They are divisive people.", "translation_id": "Dan mereka (orang-orang munafik) bersumpah dengan (nama) Allah, bahwa sesungguhnya mereka termasuk golonganmu; padahal mereka bukanlah dari golonganmu, akan tetapi mereka adalah orang-orang yang sangat takut (kepadamu).", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 57, "text": "لَوۡ یَجِدُونَ مَلۡجَـًٔا أَوۡ مَغَـٰرَ ٰتٍ أَوۡ مُدَّخَلࣰا لَّوَلَّوۡا۟ إِلَیۡهِ وَهُمۡ یَجۡمَحُونَ ۝٥٧", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "لو يجد هؤلاء المنافقون مأمنًا وحصنًا يحفظهم، أو كهفًا في جبل يؤويهم، أو نفقًا في الأرض ينجيهم منكم، لانصرفوا إليه وهم يسرعون.", "isBasmala": false, "translation_en": "Were they to find a shelter, or a cave, or a hideout, they would go to it, rushing.", "translation_id": "Jikalau mereka memperoleh tempat perlindunganmu atau gua-gua atau lobang-lobang (dalam tanah) niscaya mereka pergi kepadanya dengan secepat-cepatnya.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 58, "text": "وَمِنۡهُم مَّن یَلۡمِزُكَ فِی ٱلصَّدَقَـٰتِ فَإِنۡ أُعۡطُوا۟ مِنۡهَا رَضُوا۟ وَإِن لَّمۡ یُعۡطَوۡا۟ مِنۡهَاۤ إِذَا هُمۡ یَسۡخَطُونَ ۝٥٨", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "ومن المنافقين مَن يعيبك في قسمة الصدقات، فإن نالهم نصيب منها رضوا وسكتوا، وإن لم يصبهم حظ منها سخطوا عليك وعابوك.", "isBasmala": false, "translation_en": "And among them are those who criticize you in regard to charities. If they are given some of it, they become pleased; but if they are not given any, they grow resentful.", "translation_id": "Dan di antara mereka ada orang yang mencelamu tentang (distribusi) zakat; jika mereka diberi sebahagian dari padanya, mereka bersenang hati, dan jika mereka tidak diberi sebahagian dari padanya, dengan serta merta mereka menjadi marah.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 59, "text": "وَلَوۡ أَنَّهُمۡ رَضُوا۟ مَاۤ ءَاتَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ وَقَالُوا۟ حَسۡبُنَا ٱللَّهُ سَیُؤۡتِینَا ٱللَّهُ مِن فَضۡلِهِۦ وَرَسُولُهُۥۤ إِنَّاۤ إِلَى ٱللَّهِ رَ ٰغِبُونَ ۝٥٩", "juz": 10, "hizb": "(*¼ ح 20*)", "tafsir": "ولو أن هؤلاء الذين يعيبونك في قسمة الصدقات رضوا بما قسم الله ورسوله لهم، وقالوا: حسبنا الله، سيؤتينا الله من فضله، ويعطينا رسوله مما آتاه الله، إنا نرغب أن يوسع الله علينا، فيغنينا عن الصدقة وعن صدقات الناس. لو فعلوا ذلك لكان خيرًا لهم وأجدى.", "isBasmala": false, "translation_en": "If only they were content with what God and His Messenger have given them, and said, \"God is sufficient for us; God will give us of His bounty, and so will His Messenger; to God we eagerly turn.\"", "translation_id": "Jikalau mereka sungguh-sungguh ridha dengan apa yang diberikan Allah dan Rasul-Nya kepada mereka, dan berkata: \"Cukuplah Allah bagi kami, Allah akan memberikan sebagian dari karunia-Nya dan demikian (pula) Rasul-Nya, sesungguhnya kami adalah orang-orang yang berharap kepada Allah,\" (tentulah yang demikian itu lebih baik bagi mereka).", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 60, "text": "۞ إِنَّمَا ٱلصَّدَقَـٰتُ لِلۡفُقَرَاۤءِ وَٱلۡمَسَـٰكِینِ وَٱلۡعَـٰمِلِینَ عَلَیۡهَا وَٱلۡمُؤَلَّفَةِ قُلُوبُهُمۡ وَفِی ٱلرِّقَابِ وَٱلۡغَـٰرِمِینَ وَفِی سَبِیلِ ٱللَّهِ وَٱبۡنِ ٱلسَّبِیلِۖ فَرِیضَةࣰ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ ۝٦٠", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "إنما تعطى الزكوات الواجبة للمحتاجين الذين لا يملكون شيئًا، وللمساكين الذين لا يملكون كفايتهم، وللسعاة الذين يجمعونها، وللذين تؤلِّفون قلوبهم بها ممن يُرْجَى إسلامه أو قوة إيمانه أو نفعه للمسلمين، أو تدفعون بها شرَّ أحد عن المسلمين، وتعطى في عتق رقاب الأرقاء والمكاتبين، وتعطى للغارمين لإصلاح ذات البين، ولمن أثقلَتْهم الديون في غير فساد ولا تبذير فأعسروا، وللغزاة في سبيل الله، وللمسافر الذي انقطعت به النفقة، هذه القسمة فريضة فرضها الله وقدَّرها. والله عليم بمصالح عباده، حكيم في تدبيره وشرعه.", "isBasmala": false, "translation_en": "Charities are for the poor, and the destitute, and those who administer them, and for reconciling hearts, and for freeing slaves, and for those in debt, and in the path of God, and for the traveler in need-an obligation from God. God is All-Knowing, Most Wise.", "translation_id": "Sesungguhnya zakat-zakat itu, hanyalah untuk orang-orang fakir, orang-orang miskin, pengurus-pengurus zakat, para mu'allaf yang dibujuk hatinya, untuk (memerdekakan) budak, orang-orang yang berhutang, untuk jalan Allah dan untuk mereka yuang sedang dalam perjalanan, sebagai suatu ketetapan yang diwajibkan Allah, dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 61, "text": "وَمِنۡهُمُ ٱلَّذِینَ یُؤۡذُونَ ٱلنَّبِیَّ وَیَقُولُونَ هُوَ أُذُنࣱۚ قُلۡ أُذُنُ خَیۡرࣲ لَّكُمۡ یُؤۡمِنُ بِٱللَّهِ وَیُؤۡمِنُ لِلۡمُؤۡمِنِینَ وَرَحۡمَةࣱ لِّلَّذِینَ ءَامَنُوا۟ مِنكُمۡۚ وَٱلَّذِینَ یُؤۡذُونَ رَسُولَ ٱللَّهِ لَهُمۡ عَذَابٌ أَلِیمࣱ ۝٦١", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "ومن المنافقين قوم يؤذون رسول الله صلى الله عليه وسلم بالكلام، ويقولون: إنه يستمع لكل ما يقال له فيصدقه، قل لهم -أيها النبي-: إن محمدًا هو أذن تستمع لكل خير، يؤمن بالله ويصدق المؤمنين فيما يخبرونه، وهو رحمة لمن اتبعه واهتدى بهداه. والذين يؤذون رسول الله محمدًا صلى الله عليه وسلم بأي نوع من أنواع الإيذاء، لهم عذاب مؤلم موجع.", "isBasmala": false, "translation_en": "And among them are those who insult the Prophet, and say, \"He is all ears.\" Say, \"He listens for your own good. He believes in God, and trusts the believers, and is mercy for those of you who believe.\" Those who insult the Messenger of God will have a painful penalty.", "translation_id": "Di antara mereka (orang-orang munafik) ada yang menyakiti Nabi dan mengatakan: \"Nabi mempercayai semua apa yang didengarnya\". Katakanlah: \"Ia mempercayai semua yang baik bagi kamu, ia beriman kepada Allah, mempercayai orang-orang mukmin, dan menjadi rahmat bagi orang-orang yang beriman di antara kamu\". Dan orang-orang yang menyakiti Rasulullah itu, bagi mereka azab yang pedih.", "manzil": 2, "manzil_display": ""}], "197": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 62, "text": "یَحۡلِفُونَ بِٱللَّهِ لَكُمۡ لِیُرۡضُوكُمۡ وَٱللَّهُ وَرَسُولُهُۥۤ أَحَقُّ أَن یُرۡضُوهُ إِن كَانُوا۟ مُؤۡمِنِینَ ۝٦٢", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "يحلف المنافقون الأيمان الكاذبة، ويقدمون الأعذار الملفقة؛ ليُرضُوا المؤمنين، والله ورسوله أحق وأولى أن يُرضُوهما بالإيمان بهما وطاعتهما، إن كانوا مؤمنين حقًا.", "isBasmala": false, "translation_en": "They swear to you by God to please you. But it is more proper for them to please God and His Messenger, if they are believers.", "translation_id": "Mereka bersumpah kepada kamu dengan (nama) Allah untuk mencari keridhaanmu, padahal Allah dan Rasul-Nya itulah yang lebih patut mereka cari keridhaannya jika mereka adalah orang-orang yang mukmin.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 63, "text": "أَلَمۡ یَعۡلَمُوۤا۟ أَنَّهُۥ مَن یُحَادِدِ ٱللَّهَ وَرَسُولَهُۥ فَأَنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدࣰا فِیهَاۚ ذَ ٰلِكَ ٱلۡخِزۡیُ ٱلۡعَظِیمُ ۝٦٣", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "ألم يعلم هؤلاء المنافقون أن مصير الذين يحاربون الله ورسوله نارُ جهنم لهم العذاب الدائم فيها؟ ذلك المصير هو الهوان والذل العظيم، ومن المحاربة أذِيَّة رسول الله صلى الله عليه وسلم بسبه والقدح فيه، عياذًا بالله من ذلك.", "isBasmala": false, "translation_en": "Do they not know that whoever opposes God and His Messenger, will have the Fire of Hell, abiding in it forever? That is the supreme disgrace.", "translation_id": "Tidaklah mereka (orang-orang munafik itu) mengetahui bahwasanya barangsiapa menentang Allah dan Rasul-Nya, maka sesungguhnya nerakan jahannamlah baginya, kekal mereka di dalamnya. Itu adalah kehinaan yang besar.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 64, "text": "یَحۡذَرُ ٱلۡمُنَـٰفِقُونَ أَن تُنَزَّلَ عَلَیۡهِمۡ سُورَةࣱ تُنَبِّئُهُم بِمَا فِی قُلُوبِهِمۡۚ قُلِ ٱسۡتَهۡزِءُوۤا۟ إِنَّ ٱللَّهَ مُخۡرِجࣱ مَّا تَحۡذَرُونَ ۝٦٤", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "يخاف المنافقون أن تنزل في شأنهم سورة تخبرهم بما يضمرونه في قلوبهم من الكفر، قل لهم -أيها النبي-: استمروا على ما أنتم عليه من الاستهزاء والسخرية، إن الله مخرج حقيقة ما تحذرون.", "isBasmala": false, "translation_en": "The hypocrites worry lest a chapter may be revealed about them, informing them of what is in their hearts. Say, \"Go on mocking; God will bring out what you fear.\"", "translation_id": "Orang-orang yang munafik itu takut akan diturunkan terhadap mereka sesuatu surat yang menerangkan apa yang tersembunyi dalam hati mereka. Katakanlah kepada mereka: \"Teruskanlah ejekan-ejekanmu (terhadap Allah dan rasul-Nya)\". Sesungguhnya Allah akan menyatakan apa yang kamu takuti itu.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 65, "text": "وَلَىِٕن سَأَلۡتَهُمۡ لَیَقُولُنَّ إِنَّمَا كُنَّا نَخُوضُ وَنَلۡعَبُۚ قُلۡ أَبِٱللَّهِ وَءَایَـٰتِهِۦ وَرَسُولِهِۦ كُنتُمۡ تَسۡتَهۡزِءُونَ ۝٦٥", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "ولئن سألتهم -أيها النبي- عما قالوا من القَدْح في حقك وحق أصحابك لَيَقولُنَّ: إنما كنا نتحدث بكلام لا قصد لنا به، قل لهم -أيها النبي-: أبالله عز وجل وآياته ورسوله كنتم تستهزئون؟", "isBasmala": false, "translation_en": "If you ask them, they will say, \"We were just joking and playing.\" Say, \"Were you making jokes about God, His revelations, and His Messenger?\"", "translation_id": "Dan jika kamu tanyakan kepada mereka (tentang apa yang mereka lakukan itu), tentulah mereka akan manjawab, \"Sesungguhnya kami hanyalah bersenda gurau dan bermain-main saja\". Katakanlah: \"Apakah dengan Allah, ayat-ayat-Nya dan Rasul-Nya kamu selalu berolok-olok?\"", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 66, "text": "لَا تَعۡتَذِرُوا۟ قَدۡ كَفَرۡتُم بَعۡدَ إِیمَـٰنِكُمۡۚ إِن نَّعۡفُ عَن طَاۤىِٕفَةࣲ مِّنكُمۡ نُعَذِّبۡ طَاۤىِٕفَةَۢ بِأَنَّهُمۡ كَانُوا۟ مُجۡرِمِینَ ۝٦٦", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "لا تعتذروا -معشر المنافقين- فلا جدوى مِن اعتذاركم، قد كفرتم بهذا المقال الذي استهزأتم به، إن نعف عن جماعة منكم طلبت العفو وأخلصت في توبتها، نعذب جماعة أخرى بسبب إجرامهم بهذه المقالة الفاجرة الخاطئة.", "isBasmala": false, "translation_en": "Do not apologize. You have disbelieved after your belief. If We pardon some of you, We will punish others, because they are guilty.", "translation_id": "Tidak usah kamu minta maaf, karena kamu kafir sesudah beriman. Jika Kami memaafkan segolongan kamu (lantaran mereka taubat), niscaya Kami akan mengazab golongan (yang lain) disebabkan mereka adalah orang-orang yang selalu berbuat dosa.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 67, "text": "ٱلۡمُنَـٰفِقُونَ وَٱلۡمُنَـٰفِقَـٰتُ بَعۡضُهُم مِّنۢ بَعۡضࣲۚ یَأۡمُرُونَ بِٱلۡمُنكَرِ وَیَنۡهَوۡنَ عَنِ ٱلۡمَعۡرُوفِ وَیَقۡبِضُونَ أَیۡدِیَهُمۡۚ نَسُوا۟ ٱللَّهَ فَنَسِیَهُمۡۚ إِنَّ ٱلۡمُنَـٰفِقِینَ هُمُ ٱلۡفَـٰسِقُونَ ۝٦٧", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "المنافقون والمنافقات صنف واحد في إعلانهم الإيمان واستبطانهم الكفر، يأمرون بالكفر بالله ومعصية رسوله وينهون عن الإيمان والطاعة، ويمسكون أيديهم عن النفقة في سبيل الله، نسوا الله فلا يذكرونه، فنسيهم من رحمته، فلم يوفقهم إلى خير. إن المنافقين هم الخارجون عن الإيمان بالله ورسوله.", "isBasmala": false, "translation_en": "The hypocrite men and hypocrite women are of one another. They advocate evil, and prohibit righteousness, and withhold their hands. They forgot God, so He forgot them. The hypocrites are the sinners.", "translation_id": "Orang-orang munafik laki-laki dan perempuan. sebagian dengan sebagian yang lain adalah sama, mereka menyuruh membuat yang munkar dan melarang berbuat yang ma'ruf dan mereka menggenggamkan tangannya. Mereka telah lupa kepada Allah, maka Allah melupakan mereka. Sesungguhnya orang-orang munafik itu adalah orang-orang yang fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 68, "text": "وَعَدَ ٱللَّهُ ٱلۡمُنَـٰفِقِینَ وَٱلۡمُنَـٰفِقَـٰتِ وَٱلۡكُفَّارَ نَارَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۚ هِیَ حَسۡبُهُمۡۚ وَلَعَنَهُمُ ٱللَّهُۖ وَلَهُمۡ عَذَابࣱ مُّقِیمࣱ ۝٦٨", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "وعد الله المنافقين والمنافقات والكفار بأن مصيرهم إلى نار جهنم خالدين فيها أبدًا، هي كافيتهم؛ عقابًا على كفرهم بالله، وطردهم الله مِن رحمته، ولهم عذاب دائم.", "isBasmala": false, "translation_en": "God has promised the hypocrite men and hypocrite women, and the disbelievers, the Fire of Hell, abiding therein forever. It is their due. And God has cursed them. They will have a lasting punishment.", "translation_id": "Allah mengancam orang-orang munafik laki-laki dan perempuan dan orang-orang kafir dengan neraka Jahannam, mereka kekal di dalamnya. Cukuplah neraka itu bagi mereka, dan Allah melaknati mereka, dan bagi mereka azab yang kekal.", "manzil": 2, "manzil_display": ""}], "198": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 69, "text": "كَٱلَّذِینَ مِن قَبۡلِكُمۡ كَانُوۤا۟ أَشَدَّ مِنكُمۡ قُوَّةࣰ وَأَكۡثَرَ أَمۡوَ ٰلࣰا وَأَوۡلَـٰدࣰا فَٱسۡتَمۡتَعُوا۟ بِخَلَـٰقِهِمۡ فَٱسۡتَمۡتَعۡتُم بِخَلَـٰقِكُمۡ كَمَا ٱسۡتَمۡتَعَ ٱلَّذِینَ مِن قَبۡلِكُم بِخَلَـٰقِهِمۡ وَخُضۡتُمۡ كَٱلَّذِی خَاضُوۤا۟ۚ أُو۟لَـٰۤىِٕكَ حَبِطَتۡ أَعۡمَـٰلُهُمۡ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ ۝٦٩", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "إن أفعالكم -معشر المنافقين- من الاستهزاء والكفر كأفعال الأمم السابقة التي كانت على جانب من القوة والمال والأولاد أشد منكم، فاطْمَأنوا إلى الحياة الدنيا، وتَمتَّعوا بما فيها من الحظوظ والملذات، فاستمعتم أيها المنافقون بنصيبكم من الشهوات الفانية كاستمتاع الذين من قبلكم بحظوظهم الفانية، وخضتم بالكذب على الله كخوض تلك الأمم قبلكم، أولئك الموصوفون بهذه الأخلاق هم الذين ذهبت حسناتهم في الدنيا والآخرة، وأولئك هم الخاسرون ببيعهم نعيم الآخرة بحظوظهم من الدنيا.", "isBasmala": false, "translation_en": "Like those before you. They were more powerful than you, and had more wealth and children. They enjoyed their share, and you enjoyed your share, as those before you enjoyed their share. And you indulged, as they indulged. It is they whose works will fail in this world and in the Hereafter. It is they who are the losers.", "translation_id": "(keadaan kamu hai orang-orang munafik dan musyrikin) adalah seperti keadaan orang-orang sebelum kamu, mereka lebih kuat daripada kamu, dan lebih banyak harta dan anak-anaknya dari kamu. Maka mereka telah menikmati bagian mereka, dan kamu telah menikmati bagian kamu sebagaimana orang-orang yang sebelummu menikmati bagiannya, dan kamu mempercakapkan (hal yang batil) sebagaimana mereka mempercakapkannya. Mereka itu amalannya menjadi sia-sia di dunia dan di akhirat; dan mereka itulah orang-orang yang merugi.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 70, "text": "أَلَمۡ یَأۡتِهِمۡ نَبَأُ ٱلَّذِینَ مِن قَبۡلِهِمۡ قَوۡمِ نُوحࣲ وَعَادࣲ وَثَمُودَ وَقَوۡمِ إِبۡرَ ٰهِیمَ وَأَصۡحَـٰبِ مَدۡیَنَ وَٱلۡمُؤۡتَفِكَـٰتِۚ أَتَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِۖ فَمَا كَانَ ٱللَّهُ لِیَظۡلِمَهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ ۝٧٠", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "ألم يأت هؤلاء المنافقين خبرُ الذين مضوا مِن قوم نوح وقبيلة عاد وقبيلة ثمود وقوم إبراهيم وأصحاب (مدين) وقوم لوط عندما جاءهم المرسلون بالوحي وبآيات الله فكذَّبوهم؟ فأنزل الله بهؤلاء جميعًا عذابه؛ انتقامًا منهم لسوء عملهم، فما كان الله ليظلمهم، ولكن كانوا هم الظالمين لأنفسهم بالتكذيب والمخالفة.", "isBasmala": false, "translation_en": "Have they not heard the stories of those before them? The people of Noah, and Aad, and Thamood; and the people of Abraham, and the inhabitants of Median, and the Overturned Cities? Their messengers came to them with the clear proofs. God never wronged them, but they used to wrong their own selves.", "translation_id": "Belumkah datang kepada mereka berita penting tentang orang-orang yang sebelum mereka, (yaitu) kaum Nuh, 'Aad, Tsamud, kaum Ibrahim, penduduk Madyan dan negeri-negeri yang telah musnah?. Telah datang kepada mereka rasul-rasul dengan membawa keterangan yang nyata, maka Allah tidaklah sekali-kali menganiaya mereka, akan tetapi merekalah yang menganiaya diri mereka sendiri.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 71, "text": "وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَـٰتُ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضࣲۚ یَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَیَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَیُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَیُطِیعُونَ ٱللَّهَ وَرَسُولَهُۥۤۚ أُو۟لَـٰۤىِٕكَ سَیَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ ۝٧١", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "والمؤمنون والمؤمنات بالله ورسوله بعضهم أنصار بعض، يأمرون الناس بالإيمان والعمل الصالح، وينهونهم عن الكفر والمعاصي، ويؤدون الصلاة، ويعطون الزكاة، ويطيعون الله ورسوله، وينتهون عما نُهوا عنه، أولئك سيرحمهم الله فينقذهم من عذابه ويدخلهم جنته. إن الله عزيز في ملكه، حكيم في تشريعاته وأحكامه.", "isBasmala": false, "translation_en": "The believing men and believing women are friends of one another. They advocate virtue, forbid evil, perform the prayers, practice charity, and obey God and His Messenger. These-God will have mercy on them. God is Noble and Wise.", "translation_id": "Dan orang-orang yang beriman, lelaki dan perempuan, sebahagian mereka (adalah) menjadi penolong bagi sebahagian yang lain. Mereka menyuruh (mengerjakan) yang ma'ruf, mencegah dari yang munkar, mendirikan shalat, menunaikan zakat dan mereka taat pada Allah dan Rasul-Nya. Mereka itu akan diberi rahmat oleh Allah; sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 72, "text": "وَعَدَ ٱللَّهُ ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا وَمَسَـٰكِنَ طَیِّبَةࣰ فِی جَنَّـٰتِ عَدۡنࣲۚ وَرِضۡوَ ٰنࣱ مِّنَ ٱللَّهِ أَكۡبَرُۚ ذَ ٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝٧٢", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "وعد الله المؤمنين والمؤمنات بالله ورسوله جنات تجري من تحتها الأنهار ماكثين فيها أبدًا، لا يزول عنهم نعيمها، ومساكن حسنة البناء طيبة القرار في جنات إقامة، ورضوان من الله أكبر وأعظم مما هم فيه من النعيم. ذلك الوعد بثواب الآخرة هو الفلاح العظيم.", "isBasmala": false, "translation_en": "God promises the believers, men and women, gardens beneath which rivers flow, abiding therein forever, and fine homes in the Gardens of Eden. But approval from God is even greater. That is the supreme achievement.", "translation_id": "Allah menjanjikan kepada orang-orang mukmin, lelaki dan perempuan, (akan mendapat) surga yang dibawahnya mengalir sungai-sungai, kekal mereka di dalamnya, dan (mendapat) tempat-tempat yang bagus di surga 'Adn. Dan keridhaan Allah adalah lebih besar; itu adalah keberuntungan yang besar.", "manzil": 2, "manzil_display": ""}], "199": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 73, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ جَـٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَـٰفِقِینَ وَٱغۡلُظۡ عَلَیۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ ۝٧٣", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "يا أيها النبي جاهد الكفار بالسيف والمنافقين باللسان والحجة، واشدد على كلا الفريقين، ومقرُّهم جهنم، وبئس المصير مصيرهم.", "isBasmala": false, "translation_en": "O Prophet! Strive against the disbelievers and the hypocrites, and be stern with them. Their abode is Hell-what a miserable destination!", "translation_id": "Hai Nabi, berjihadlah (melawan) orang-orang kafir dan orang-orang munafik itu, dan bersikap keraslah terhadap mereka. Tempat mereka ialah jahannam. Dan itu adalah tempat kembali yang seburuk-buruknya.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 74, "text": "یَحۡلِفُونَ بِٱللَّهِ مَا قَالُوا۟ وَلَقَدۡ قَالُوا۟ كَلِمَةَ ٱلۡكُفۡرِ وَكَفَرُوا۟ بَعۡدَ إِسۡلَـٰمِهِمۡ وَهَمُّوا۟ بِمَا لَمۡ یَنَالُوا۟ۚ وَمَا نَقَمُوۤا۟ إِلَّاۤ أَنۡ أَغۡنَىٰهُمُ ٱللَّهُ وَرَسُولُهُۥ مِن فَضۡلِهِۦۚ فَإِن یَتُوبُوا۟ یَكُ خَیۡرࣰا لَّهُمۡۖ وَإِن یَتَوَلَّوۡا۟ یُعَذِّبۡهُمُ ٱللَّهُ عَذَابًا أَلِیمࣰا فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۚ وَمَا لَهُمۡ فِی ٱلۡأَرۡضِ مِن وَلِیࣲّ وَلَا نَصِیرࣲ ۝٧٤", "juz": 10, "hizb": "(*½ ح 20*)", "tafsir": "يحلف المنافقون بالله أنهم ما قالوا شيئًا يسيء إلى الرسول وإلى المسلمين، إنهم لكاذبون؛ فلقد قالوا كلمة الكفر وارتدوا بها عن الإسلام وحاولوا الإضرار برسول الله محمد صلى الله عليه وسلم، فلم يمكنهم الله من ذلك، وما وجد المنافقون شيئًا يعيبونه، وينتقدونه، إلا أن الله -تعالى- تفضل عليهم، فأغناهم بما فتح على نبيه صلى الله عليه وسلم من الخير والبركة، فإن يرجع هؤلاء الكفار إلى الإيمان والتوبة فهو خير لهم، وإن يعرضوا، أو يستمروا على حالهم، يعذبهم الله العذاب الموجع في الدنيا على أيدي المؤمنين، وفي الآخرة بنار جهنم، وليس لهم منقذ ينقذهم ولا ناصر يدفع عنهم سوء العذاب.", "isBasmala": false, "translation_en": "They swear by God that they said nothing; but they did utter the word of blasphemy, and they renounced faith after their submission. And they plotted what they could not attain. They were resentful only because God and His Messenger have enriched them out of His grace. If they repent, it would be best for them; but if they turn away, God will afflict them with a painful punishment-in this life and in the Hereafter-and they will have on earth no protector and no savior.", "translation_id": "Mereka (orang-orang munafik itu) bersumpah dengan (nama) Allah, bahwa mereka tidak mengatakan (sesuatu yang menyakitimu). Sesungguhnya mereka telah mengucapkan perkataan kekafiran, dan telah menjadi kafir sesudah Islam dan mengingini apa yang mereka tidak dapat mencapainya, dan mereka tidak mencela (Allah dan Rasul-Nya), kecuali karena Allah dan Rasul-Nya telah melimpahkan karunia-Nya kepada mereka. Maka jika mereka bertaubat, itu adalah lebih baik bagi mereka, dan jika mereka berpaling, niscaya Allah akan mengazab mereka dengan azab yang pedih di dunia dan akhirat; dan mereka sekali-kali tidaklah mempunyai pelindung dan tidak (pula) penolong di muka bumi.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 75, "text": "۞ وَمِنۡهُم مَّنۡ عَـٰهَدَ ٱللَّهَ لَىِٕنۡ ءَاتَىٰنَا مِن فَضۡلِهِۦ لَنَصَّدَّقَنَّ وَلَنَكُونَنَّ مِنَ ٱلصَّـٰلِحِینَ ۝٧٥", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "ومن فقراء المنافقين مَن يقطع العهد على نفسه: لئن أعطاه الله المال ليصدَّقنَّ منه، وليعمَلنَّ ما يعمل الصالحون في أموالهم، وليسيرَنَّ في طريق الصلاح.", "isBasmala": false, "translation_en": "Among them are those who promised God: \"If He gives us of His bounty, we will donate and be among the upright.\"", "translation_id": "Dan diantara mereka ada orang yang telah berikrar kepada Allah: \"Sesungguhnya jika Allah memberikan sebahagian karunia-Nya kepada kami, pastilah kami akan bersedekah dan pastilah kami termasuk orang-orang yang saleh.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 76, "text": "فَلَمَّاۤ ءَاتَىٰهُم مِّن فَضۡلِهِۦ بَخِلُوا۟ بِهِۦ وَتَوَلَّوا۟ وَّهُم مُّعۡرِضُونَ ۝٧٦", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "فلما أعطاهم الله من فضله بخلوا بإعطاء الصدقة وبإنفاق المال في الخير، وتولَّوا وهم معرضون عن الإسلام.", "isBasmala": false, "translation_en": "But when He has given them of His bounty, they became stingy with it, and turned away in aversion.", "translation_id": "Maka setelah Allah memberikan kepada mereka sebahagian dari karunia-Nya, mereka kikir dengan karunia itu, dan berpaling, dan mereka memanglah orang-orang yang selalu membelakangi (kebenaran).", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 77, "text": "فَأَعۡقَبَهُمۡ نِفَاقࣰا فِی قُلُوبِهِمۡ إِلَىٰ یَوۡمِ یَلۡقَوۡنَهُۥ بِمَاۤ أَخۡلَفُوا۟ ٱللَّهَ مَا وَعَدُوهُ وَبِمَا كَانُوا۟ یَكۡذِبُونَ ۝٧٧", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "فكان جزاء صنيعهم وعاقبتهم أَنْ زادهم نفاقًا على نفاقهم، لا يستطيعون التخلص منه إلى يوم الحساب؛ وذلك بسبب إخلافهم الوعد الذي قطعوه على أنفسهم، وبسبب نفاقهم وكذبهم.", "isBasmala": false, "translation_en": "So He penalized them with hypocrisy in their hearts, until the Day they face Him-because they broke their promise to God, and because they used to lie.", "translation_id": "Maka Allah menimbulkan kemunafikan pada hati mereka sampai kepada waktu mereka menemui Allah, karena mereka telah memungkiri terhadap Allah apa yang telah mereka ikrarkan kepada-Nya dan juga karena mereka selalu berdusta.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 78, "text": "أَلَمۡ یَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَعۡلَمُ سِرَّهُمۡ وَنَجۡوَىٰهُمۡ وَأَنَّ ٱللَّهَ عَلَّـٰمُ ٱلۡغُیُوبِ ۝٧٨", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "ألم يعلم هؤلاء المنافقون أن الله يعلم ما يخفونه في أنفسهم وما يتحدثون به في مجالسهم من الكيد والمكر، وأن الله علام الغيوب؟ فسيجازيهم على أعمالهم التي أحصاها عليهم.", "isBasmala": false, "translation_en": "Do they not know that God knows their secrets and their conspiracies? And that God is the Knower of the unseen?", "translation_id": "Tidaklah mereka tahu bahwasanya Allah mengetahui rahasia dan bisikan mereka, dan bahwasanya Allah amat mengetahui segala yang ghaib.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 79, "text": "ٱلَّذِینَ یَلۡمِزُونَ ٱلۡمُطَّوِّعِینَ مِنَ ٱلۡمُؤۡمِنِینَ فِی ٱلصَّدَقَـٰتِ وَٱلَّذِینَ لَا یَجِدُونَ إِلَّا جُهۡدَهُمۡ فَیَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِیمٌ ۝٧٩", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "ومع بخل المنافقين لا يَسْلَم المتصدقون من أذاهم؛ فإذا تصدق الأغنياء بالمال الكثير عابوهم واتهموهم بالرياء، وإذا تصدق الفقراء بما في طاقتهم استهزؤوا بهم، وقالوا سخرية منهم: ماذا تجدي صدقتهم هذه؟ سخر الله من هؤلاء المنافقين، ولهم عذاب مؤلم موجع.", "isBasmala": false, "translation_en": "Those who criticize the believers who give charity voluntarily, and ridicule those who find nothing to give except their own efforts-God ridicules them. They will have a painful punishment.", "translation_id": "(Orang-orang munafik itu) yaitu orang-orang yang mencela orang-orang mukmin yang memberi sedekah dengan sukarela dan (mencela) orang-orang yang tidak memperoleh (untuk disedekahkan) selain sekedar kesanggupannya, maka orang-orang munafik itu menghina mereka. Allah akan membalas penghinaan mereka itu, dan untuk mereka azab yang pedih.", "manzil": 2, "manzil_display": ""}], "200": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 80, "text": "ٱسۡتَغۡفِرۡ لَهُمۡ أَوۡ لَا تَسۡتَغۡفِرۡ لَهُمۡ إِن تَسۡتَغۡفِرۡ لَهُمۡ سَبۡعِینَ مَرَّةࣰ فَلَن یَغۡفِرَ ٱللَّهُ لَهُمۡۚ ذَ ٰلِكَ بِأَنَّهُمۡ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ ۝٨٠", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "استغفر -أيها الرسول- للمنافقين أو لا تستغفر لهم، فلن يغفر الله لهم، مهما كثر استغفارك لهم وتكرر؛ لأنهم كفروا بالله ورسوله. والله سبحانه وتعالى لا يوفق للهدى الخارجين عن طاعته.", "isBasmala": false, "translation_en": "Whether you ask forgiveness for them, or do not ask forgiveness for them-even if you ask forgiveness for them seventy times, God will not forgive them. That is because they disbelieved in God and His Messenger. God does not guide the immoral people.", "translation_id": "Kamu memohonkan ampun bagi mereka atau tidak kamu mohonkan ampun bagi mereka (adalah sama saja). Kendatipun kamu memohonkan ampun bagi mereka tujuh puluh kali, namun Allah sekali-kali tidak akan memberi ampunan kepada mereka. Yang demikian itu adalah karena mereka kafir kepada Allah dan Rasul-Nya. Dan Allah tidak memberi petunjuk kepada kaum yang fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 81, "text": "فَرِحَ ٱلۡمُخَلَّفُونَ بِمَقۡعَدِهِمۡ خِلَـٰفَ رَسُولِ ٱللَّهِ وَكَرِهُوۤا۟ أَن یُجَـٰهِدُوا۟ بِأَمۡوَ ٰلِهِمۡ وَأَنفُسِهِمۡ فِی سَبِیلِ ٱللَّهِ وَقَالُوا۟ لَا تَنفِرُوا۟ فِی ٱلۡحَرِّۗ قُلۡ نَارُ جَهَنَّمَ أَشَدُّ حَرࣰّاۚ لَّوۡ كَانُوا۟ یَفۡقَهُونَ ۝٨١", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "فرح المخلفون الذين تخلفوا عن رسول الله صلى الله عليه وسلم بقعودهم في (المدينة) مخالفين لرسول الله صلى الله عليه وسلم، وكرهوا أن يجاهدوا معه بأموالهم وأنفسهم في سبيل الله، وقال بعضهم لبعض: لا تنفروا في الحرِّ، وكانت غزوة (تبوك) في وقت شدة الحرِّ. قل لهم -أيها الرسول-: نار جهنم أشد حرًا، لو كانوا يعلمون ذلك.", "isBasmala": false, "translation_en": "Those who stayed behind rejoiced at their staying behind the Messenger of God. And they hated to strive with their wealth and their lives in God's way. And they said, \"Do not venture out in the heat.\" Say, \"The Fire of Hell is much hotter, if they only understood.\"", "translation_id": "Orang-orang yang ditinggalkan (tidak ikut perang) itu, merasa gembira dengan tinggalnya mereka di belakang Rasulullah, dan mereka tidak suka berjihad dengan harta dan jiwa mereka pada jalan Allah dan mereka berkata: \"Janganlah kamu berangkat (pergi berperang) dalam panas terik ini\". Katakanlah: \"Api neraka jahannam itu lebih sangat panas(nya)\" jika mereka mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 82, "text": "فَلۡیَضۡحَكُوا۟ قَلِیلࣰا وَلۡیَبۡكُوا۟ كَثِیرࣰا جَزَاۤءَۢ بِمَا كَانُوا۟ یَكۡسِبُونَ ۝٨٢", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "فليضحك هؤلاء المنافقون الذين تخلفوا عن رسول الله في غزوة (تبوك) قليلا في حياتهم الدنيا الفانية، وليبكوا كثيرًا في نار جهنم؛ جزاءً بما كانوا يكسبون في الدنيا من النفاق والكفر.", "isBasmala": false, "translation_en": "Let them laugh a little, and weep much; in recompense for what they used to earn.", "translation_id": "Maka hendaklah mereka tertawa sedikit dan menangis banyak, sebagai pembalasan dari apa yang selalu mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 83, "text": "فَإِن رَّجَعَكَ ٱللَّهُ إِلَىٰ طَاۤىِٕفَةࣲ مِّنۡهُمۡ فَٱسۡتَـٔۡذَنُوكَ لِلۡخُرُوجِ فَقُل لَّن تَخۡرُجُوا۟ مَعِیَ أَبَدࣰا وَلَن تُقَـٰتِلُوا۟ مَعِیَ عَدُوًّاۖ إِنَّكُمۡ رَضِیتُم بِٱلۡقُعُودِ أَوَّلَ مَرَّةࣲ فَٱقۡعُدُوا۟ مَعَ ٱلۡخَـٰلِفِینَ ۝٨٣", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "فإنْ رَدَّك الله -أيها الرسول- مِن غزوتك إلى جماعة من المنافقين الثابتين على النفاق، فاستأذنوك للخروج معك إلى غزوة أخرى بعد غزوة (تبوك) فقل لهم: لن تخرجوا معي أبدًا في غزوة من الغزوات، ولن تقاتلوا معي عدوًا من الأعداء؛ إنكم رضيتم بالقعود أول مرة، فاقعدوا مع الذين تخلفوا عن الجهاد مع رسول الله صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "If God brings you back to a party of them, and they ask your permission to go out, say, \"You will not go out with me, ever, nor will you ever fight an enemy with me. You were content to sit back the first time, so sit back with those who stay behind.\"", "translation_id": "Maka jika Allah mengembalikanmu kepada suatu golongan dari mereka, kemudian mereka minta izin kepadamu untuk keluar (pergi berperang), maka Katakanlah: \"Kamu tidak boleh keluar bersamaku selama-lamanya dan tidak boleh memerangi musuh bersamaku. Sesungguhnya kamu telah rela tidak pergi berperang kali yang pertama. Karena itu duduklah bersama orang-orang yang tidak ikut berperang\".", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 84, "text": "وَلَا تُصَلِّ عَلَىٰۤ أَحَدࣲ مِّنۡهُم مَّاتَ أَبَدࣰا وَلَا تَقُمۡ عَلَىٰ قَبۡرِهِۦۤۖ إِنَّهُمۡ كَفَرُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَمَاتُوا۟ وَهُمۡ فَـٰسِقُونَ ۝٨٤", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "ولا تصلِّ -أيها الرسول- أبدًا على أحد مات من المنافقين، ولا تقم على قبره لتدعو له؛ لأنهم كفروا بالله تعالى وبرسوله صلى الله عليه وسلم وماتوا وهم فاسقون. وهذا حكم عام في كل من عُلِمَ نفاقه.", "isBasmala": false, "translation_en": "You are never to pray over anyone of them who dies, nor are you to stand at his graveside. They rejected God and His Messenger, and died while they were sinners.", "translation_id": "Dan janganlah kamu sekali-kali menyembahyangkan (jenazah) seorang yang mati di antara mereka, dan janganlah kamu berdiri (mendoakan) di kuburnya. Sesungguhnya mereka telah kafir kepada Allah dan Rasul-Nya dan mereka mati dalam keadaan fasik.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 85, "text": "وَلَا تُعۡجِبۡكَ أَمۡوَ ٰلُهُمۡ وَأَوۡلَـٰدُهُمۡۚ إِنَّمَا یُرِیدُ ٱللَّهُ أَن یُعَذِّبَهُم بِهَا فِی ٱلدُّنۡیَا وَتَزۡهَقَ أَنفُسُهُمۡ وَهُمۡ كَـٰفِرُونَ ۝٨٥", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "ولا تعجبك -أيها الرسول- أموال هؤلاء المنافقين وأولادهم، إنما يريد الله أن يعذبهم بها في الدنيا بمكابدتهم الشدائد في شأنها، وبموتهم على كفرهم بالله ورسوله.", "isBasmala": false, "translation_en": "Do not let their possessions and their children impress you. God desires to torment them through them in this world, and their souls expire while they are disbelievers.", "translation_id": "Dan janganlah harta benda dan anak-anak mereka menarik hatimu. Sesungguhnya Allah menghendaki akan mengazab mereka di dunia dengan harta dan anak-anak itu dan agar melayang nyawa mereka, dalam keadaan kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 86, "text": "وَإِذَاۤ أُنزِلَتۡ سُورَةٌ أَنۡ ءَامِنُوا۟ بِٱللَّهِ وَجَـٰهِدُوا۟ مَعَ رَسُولِهِ ٱسۡتَـٔۡذَنَكَ أُو۟لُوا۟ ٱلطَّوۡلِ مِنۡهُمۡ وَقَالُوا۟ ذَرۡنَا نَكُن مَّعَ ٱلۡقَـٰعِدِینَ ۝٨٦", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "وإذا أنزلت سورة على محمد صلى الله عليه ولم تأمر بالإيمان بالله والإخلاص له والجهاد مع رسول الله، طلب الإذن منك -أيها الرسول- أولو اليسار من المنافقين، وقالوا: اتركنا مع القاعدين العاجزين عن الخروج.", "isBasmala": false, "translation_en": "When a chapter is revealed, stating: \"Believe in God and strive with His Messenger,\" the prominent among them ask you for exemption. They say, \"Allow us to stay with those who stay behind.\"", "translation_id": "Dan apabila diturunkan suatu surat (yang memerintahkan kepada orang munafik itu): \"Berimanlah kamu kepada Allah dan berjihadlah beserta Rasul-Nya\", niscaya orang-orang yang sanggup di antara mereka meminta izin kepadamu (untuk tidak berjihad) dan mereka berkata: \"Biarkanlah kami berada bersama orang-orang yang duduk\".", "manzil": 2, "manzil_display": ""}], "201": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 87, "text": "رَضُوا۟ بِأَن یَكُونُوا۟ مَعَ ٱلۡخَوَالِفِ وَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَفۡقَهُونَ ۝٨٧", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "رضي هؤلاء المنافقون لأنفسهم بالعار، وهو أن يقعدوا في البيوت مع النساء والصبيان وأصحاب الأعذار، وختم الله على قلوبهم؛ بسبب نفاقهم وتخلفهم عن الجهاد والخروج مع رسول الله صلى الله عليه وسلم في سبيل الله، فهم لا يفقهون ما فيه صلاحهم ورشادهم.", "isBasmala": false, "translation_en": "They prefer to be with those who stay behind. Their hearts were sealed, so they do not understand.", "translation_id": "Mereka rela berada bersama orang-orang yang tidak berperang, dan hati mereka telah dikunci mati maka mereka tidak mengetahui (kebahagiaan beriman dan berjihad).", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 88, "text": "لَـٰكِنِ ٱلرَّسُولُ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ جَـٰهَدُوا۟ بِأَمۡوَ ٰلِهِمۡ وَأَنفُسِهِمۡۚ وَأُو۟لَـٰۤىِٕكَ لَهُمُ ٱلۡخَیۡرَ ٰتُۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝٨٨", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "إنْ تخلَّف هؤلاء المنافقون عن الغزو، فقد جاهد رسول الله صلى الله عليه وسلم والمؤمنون معه بأموالهم وأنفسهم، وأولئك لهم النصر والغنيمة في الدنيا، والجنة والكرامة في الآخرة، وأولئك هم الفائزون.", "isBasmala": false, "translation_en": "But the Messenger and those who believe with him struggle with their possessions and their lives. These have deserved the good things. These are the successful.", "translation_id": "Tetapi Rasul dan orang-orang yang beriman bersama dia, mereka berjihad dengan harta dan diri mereka. Dan mereka itulah orang-orang yang memperoleh kebaikan, dan mereka itulah orang-orang yang beruntung.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 89, "text": "أَعَدَّ ٱللَّهُ لَهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ ذَ ٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝٨٩", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "أعدَّ الله لهم يوم القيامة جنات تجري مِن تحت أشجارها الأنهار ماكثين فيها أبدًا. وذلك هو الفلاح العظيم.", "isBasmala": false, "translation_en": "God has prepared for them gardens beneath which rivers flow, wherein they will abide forever. That is the great victory.", "translation_id": "Allah telah menyediakan bagi mereka surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Itulah kemenangan yang besar.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 90, "text": "وَجَاۤءَ ٱلۡمُعَذِّرُونَ مِنَ ٱلۡأَعۡرَابِ لِیُؤۡذَنَ لَهُمۡ وَقَعَدَ ٱلَّذِینَ كَذَبُوا۟ ٱللَّهَ وَرَسُولَهُۥۚ سَیُصِیبُ ٱلَّذِینَ كَفَرُوا۟ مِنۡهُمۡ عَذَابٌ أَلِیمࣱ ۝٩٠", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "وجاء جماعة من أحياء العرب حول (المدينة) يعتذرون إلى رسول الله صلى الله عليه وسلم، ويبينون له ما هم فيه من الضعف وعدم القدرة على الخروج للغزو، وقعد قوم بغير عذر أظهروه جرأة على رسول الله صلى الله عليه وسلم. سيصيب الذين كفروا من هؤلاء عذاب أليم في الدنيا بالقتل وغيره، وفي الآخرة بالنار.", "isBasmala": false, "translation_en": "Some of the Desert-Arabs came to make excuses, asking to be granted exemption, while those who were untrue to God and His Messenger stayed behind. A painful punishment will afflict those among them who disbelieved.", "translation_id": "Dan datang (kepada Nabi) orang-orang yang mengemukakan 'uzur, yaitu orang-orang Arab Baswi agar diberi izin bagi mereka (untuk tidak berjihad), sedang orang-orang yang mendustakan Allah dan Rasul-Nya, duduk berdiam diri saja. Kelak orang-orang yang kafir di antara mereka itu akan ditimpa azab yang pedih.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 91, "text": "لَّیۡسَ عَلَى ٱلضُّعَفَاۤءِ وَلَا عَلَى ٱلۡمَرۡضَىٰ وَلَا عَلَى ٱلَّذِینَ لَا یَجِدُونَ مَا یُنفِقُونَ حَرَجٌ إِذَا نَصَحُوا۟ لِلَّهِ وَرَسُولِهِۦۚ مَا عَلَى ٱلۡمُحۡسِنِینَ مِن سَبِیلࣲۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٩١", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "ليس على أهل الأعذار مِن الضعفاء والمرضى والفقراء الذين لا يملكون من المال ما يتجهزون به للخروج إثم في القعود إذا أخلصوا لله ورسوله، وعملوا بشرعه، ما على مَن أحسن ممن منعه العذر عن الجهاد مع رسول الله صلى الله عليه وسلم، وهو ناصح لله ولرسوله من طريق يعاقب مِن قِبَلِه ويؤاخذ عليه. والله غفور للمحسنين، رحيم بهم.", "isBasmala": false, "translation_en": "There is no blame on the weak, nor on the sick, nor on those who have nothing to give, provided they are true to God and His Messenger. In no way can the righteous be blamed. God is Forgiving and Merciful.", "translation_id": "Tiada dosa (lantaran tidak pergi berjihad) atas orang-orang yang lemah, orang-orang yang sakit dan atas orang-orang yang tidak memperoleh apa yang akan mereka nafkahkan, apabila mereka berlaku ikhlas kepada Allah dan Rasul-Nya. Tidak ada jalan sedikitpun untuk menyalahkan orang-orang yang berbuat baik. Dan Allah Maha Pengampun lagi Maha Penyayang,", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 92, "text": "وَلَا عَلَى ٱلَّذِینَ إِذَا مَاۤ أَتَوۡكَ لِتَحۡمِلَهُمۡ قُلۡتَ لَاۤ أَجِدُ مَاۤ أَحۡمِلُكُمۡ عَلَیۡهِ تَوَلَّوا۟ وَّأَعۡیُنُهُمۡ تَفِیضُ مِنَ ٱلدَّمۡعِ حَزَنًا أَلَّا یَجِدُوا۟ مَا یُنفِقُونَ ۝٩٢", "juz": 10, "hizb": "(*¾ ح 20*)", "tafsir": "وكذلك لا إثم على الذين إذا ما جاؤوك يطلبون أن تعينهم بحملهم إلى الجهاد قلت لهم: لا أجد ما أحملكم عليه من الدوابِّ، فانصرفوا عنك، وقد فاضت أعينهم دَمعًا أسفًا على ما فاتهم من شرف الجهاد وثوابه؛ لأنهم لم يجدوا ما ينفقون، وما يحملهم لو خرجوا للجهاد في سبيل الله.", "isBasmala": false, "translation_en": "Nor on those who approach you, wishing to ride with you, and you said, \"I have nothing to carry you on.\" So they went away, with their eyes overflowing with tears, sorrowing for not finding the means to spend.", "translation_id": "dan tiada (pula) berdosa atas orang-orang yang apabila mereka datang kepadamu, supaya kamu memberi mereka kendaraan, lalu kamu berkata: \"Aku tidak memperoleh kendaraan untuk membawamu\". lalu mereka kembali, sedang mata mereka bercucuran air mata karena kesedihan, lantaran mereka tidak memperoleh apa yang akan mereka nafkahkan.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 93, "text": "۞ إِنَّمَا ٱلسَّبِیلُ عَلَى ٱلَّذِینَ یَسۡتَـٔۡذِنُونَكَ وَهُمۡ أَغۡنِیَاۤءُۚ رَضُوا۟ بِأَن یَكُونُوا۟ مَعَ ٱلۡخَوَالِفِ وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَعۡلَمُونَ ۝٩٣", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "إنما الإثم واللوم على الأغنياء الذين جاءوك -أيها الرسول- يطلبون الإذن بالتخلف، وهم المنافقون الأغنياء اختاروا لأنفسهم القعود مع النساء وأهل الأعذار، وختم الله على قلوبهم بالنفاق، فلا يدخلها إيمان، فهم لا يعلمون سوء عاقبتهم بتخلفهم عنك وتركهم الجهاد معك.", "isBasmala": false, "translation_en": "But blame is on those who ask you for exemption, although they are rich. They are content to be with those who stay behind. God has sealed their hearts, so they do not know.", "translation_id": "Sesungguhnya jalan (untuk menyalahkan) hanyalah terhadap orang-orang yang meminta izin kepadamu, padahal mereka itu orang-orang kaya. Mereka rela berada bersama orang-orang yang tidak ikut berperang dan Allah telah mengunci mati hati mereka, maka mereka tidak mengetahui (akibat perbuatan mereka).", "manzil": 2, "manzil_display": ""}], "202": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 94, "text": "یَعۡتَذِرُونَ إِلَیۡكُمۡ إِذَا رَجَعۡتُمۡ إِلَیۡهِمۡۚ قُل لَّا تَعۡتَذِرُوا۟ لَن نُّؤۡمِنَ لَكُمۡ قَدۡ نَبَّأَنَا ٱللَّهُ مِنۡ أَخۡبَارِكُمۡۚ وَسَیَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٩٤", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "يعتذر إليكم -أيها المؤمنون- هؤلاء المتخلفون عن جهاد المشركين بالأكاذيب عندما تعودون مِن جهادكم من غزوة (تبوك)، قل لهم -أيها الرسول-: لا تعتذروا لن نصدقكم فيما تقولون، قد نبأنا الله من أمركم ما حقق لدينا كذبكم، وسيرى الله عملكم ورسوله، إن كنتم تتوبون من نفاقكم، أو تقيمون عليه، وسيُظهر للناس أعمالكم في الدنيا، ثم ترجعون بعد مماتكم إلى الذي لا تخفى عليه بواطن أموركم وظواهرها، فيخبركم بأعمالكم كلها، ويجازيكم عليها.", "isBasmala": false, "translation_en": "They present excuses to you when you return to them. Say, \"Do not offer excuses; we do not trust you; God has informed us of you. And God will watch your actions, and so will the Messenger; then you will be returned to the Knower of the Invisible and the Visible, and He will inform you of what you used to do.\"", "translation_id": "Mereka (orang-orang munafik) mengemukakan 'uzurnya kepadamu, apabila kamu telah kembali kepada mereka (dari medan perang). Katakanlah: \"Janganlah kamu mengemukakan 'uzur; kami tidak percaya lagi kepadamu, (karena) sesungguhnya Allah telah memberitahukan kepada kami beritamu yang sebenarnya. Dan Allah serta Rasul-Nya akan melihat pekerjaanmu, kemudian kamu dikembalikan kepada Yang mengetahui yang ghaib dan yang nyata, lalu Dia memberitahukan kepadamu apa yang telah kamu kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 95, "text": "سَیَحۡلِفُونَ بِٱللَّهِ لَكُمۡ إِذَا ٱنقَلَبۡتُمۡ إِلَیۡهِمۡ لِتُعۡرِضُوا۟ عَنۡهُمۡۖ فَأَعۡرِضُوا۟ عَنۡهُمۡۖ إِنَّهُمۡ رِجۡسࣱۖ وَمَأۡوَىٰهُمۡ جَهَنَّمُ جَزَاۤءَۢ بِمَا كَانُوا۟ یَكۡسِبُونَ ۝٩٥", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "سيحلف لكم المنافقون بالله -كاذبين معتذرين- إذا رجعتم إليهم من الغزو؛ لتتركوهم دون مساءلة، فاجتنبوهم وأعرضوا عنهم احتقارًا لهم، إنهم خبثاء البواطن، ومكانهم الذي يأوون إليه في الآخرة نار جهنم؛ جزاء بما كانوا يكسبون من الآثام والخطايا.", "isBasmala": false, "translation_en": "They will swear to you by God, when you return to them, that you may leave them alone. So leave them alone. They are a disgrace, and their destiny is Hell; a reward for what they used to earn.", "translation_id": "Kelak mereka akan bersumpah kepadamu dengan nama Allah, apabila kamu kembali kepada mereka, supaya kamu berpaling dari mereka. Maka berpalinglah dari mereka; karena sesungguhnya mereka itu adalah najis dan tempat mereka jahannam; sebagai balasan atas apa yang telah mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 96, "text": "یَحۡلِفُونَ لَكُمۡ لِتَرۡضَوۡا۟ عَنۡهُمۡۖ فَإِن تَرۡضَوۡا۟ عَنۡهُمۡ فَإِنَّ ٱللَّهَ لَا یَرۡضَىٰ عَنِ ٱلۡقَوۡمِ ٱلۡفَـٰسِقِینَ ۝٩٦", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "يحلف لكم -أيها المؤمنون- هؤلاء المنافقون كذبًا؛ لتَرضَوا عنهم، فإن رضيتم عنهم -لأنكم لا تعلمون كذبهم- فإن الله لا يرضى عن هؤلاء وغيرهم ممن استمروا على الفسوق والخروج عن طاعة الله ورسوله.", "isBasmala": false, "translation_en": "They will swear to you that you may accept them. But even if you accept them, God does not accept the wicked people.", "translation_id": "Mereka akan bersumpah kepadamu, agar kamu ridha kepada mereka. Tetapi jika sekiranya kamu ridha kepada mereka, sesungguhnya Allah tidak ridha kepada orang-orang yang fasik itu.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 97, "text": "ٱلۡأَعۡرَابُ أَشَدُّ كُفۡرࣰا وَنِفَاقࣰا وَأَجۡدَرُ أَلَّا یَعۡلَمُوا۟ حُدُودَ مَاۤ أَنزَلَ ٱللَّهُ عَلَىٰ رَسُولِهِۦۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ ۝٩٧", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "الأعراب سكان البادية أشد كفرًا ونفاقًا من أهل الحاضرة، وذلك لجفائهم وقسوة قلوبهم وبُعدهم عن العلم والعلماء، ومجالس الوعظ والذكر، فهم لذلك أحق بأن لا يعلموا حدود الدين، وما أنزل الله من الشرائع والأحكام. والله عليم بحال هؤلاء جميعًا، حكيم في تدبيره لأمور عباده.", "isBasmala": false, "translation_en": "The Desert-Arabs are the most steeped in disbelief and hypocrisy, and the most likely to ignore the limits that God revealed to His Messenger. God is Knowing and Wise.", "translation_id": "Orang-orang Arab Badwi itu, lebih sangat kekafiran dan kemunafikannya, dan lebih wajar tidak mengetahui hukum-hukum yang diturunkan Allah kepada Rasul-Nya. Dan Allah Maha mengetahui lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 98, "text": "وَمِنَ ٱلۡأَعۡرَابِ مَن یَتَّخِذُ مَا یُنفِقُ مَغۡرَمࣰا وَیَتَرَبَّصُ بِكُمُ ٱلدَّوَاۤىِٕرَۚ عَلَیۡهِمۡ دَاۤىِٕرَةُ ٱلسَّوۡءِۗ وَٱللَّهُ سَمِیعٌ عَلِیمࣱ ۝٩٨", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "ومن الأعراب مَن يحتسب ما ينفق في سبيل الله غرامة وخسارة لا يرجو له ثوابًا، ولا يدفع عن نفسه عقابًا، وينتظر بكم الحوادث والآفات، ولكن السوء دائر عليهم لا بالمسلمين. والله سميع لما يقولون عليم بنياتهم الفاسدة.", "isBasmala": false, "translation_en": "And among the Desert-Arabs are those who consider their contribution to be a fine. And they wait for a reversal of your fortunes. Upon them will fall the cycle of misfortune. God is Hearing and Knowing.", "translation_id": "Di antara orang-orang Arab Badwi itu ada orang yang memandang apa yang dinafkahkannya (di jalan Allah), sebagi suatu kerugian, dan dia menanti-nanti marabahaya menimpamu, merekalah yang akan ditimpa marabahaya. Dan Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 99, "text": "وَمِنَ ٱلۡأَعۡرَابِ مَن یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَیَتَّخِذُ مَا یُنفِقُ قُرُبَـٰتٍ عِندَ ٱللَّهِ وَصَلَوَ ٰتِ ٱلرَّسُولِۚ أَلَاۤ إِنَّهَا قُرۡبَةࣱ لَّهُمۡۚ سَیُدۡخِلُهُمُ ٱللَّهُ فِی رَحۡمَتِهِۦۤۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝٩٩", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "ومن الأعراب مَن يؤمن بالله ويقرُّ بوحدانيته وبالبعث بعد الموت، والثواب والعقاب، ويحتسب ما ينفق من نفقة في جهاد المشركين قاصدًا بها رضا الله ومحبته، ويجعلها وسيلة إلى دعاء الرسول صلى الله عليه وسلم له، ألا إن هذه الأعمال تقربهم إلى الله تعالى، سيدخلهم الله في جنته. إن الله غفور لما فعلوا من السيئات، رحيم بهم.", "isBasmala": false, "translation_en": "Yet among the Desert-Arabs are those who believe in God and the Last Day, and consider their contribution to be a means towards God, and the prayers of the Messenger. Surely it will draw them closer, and God will admit them into His mercy. God is Forgiving and Compassionate.", "translation_id": "Di antara orang-orang Arab Badwi itu ada orang yang beriman kepada Allah dan hari kemudian, dan memandang apa yang dinafkahkannya (di jalan Allah) itu, sebagai jalan untuk mendekatkannya kepada Allah dan sebagai jalan untuk memperoleh doa Rasul. Ketahuilah, sesungguhnya nafkah itu adalah suatu jalan bagi mereka untuk mendekatkan diri (kepada Allah). Kelak Allah akan memasukan mereka kedalam rahmat (surga)Nya; Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}], "203": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 100, "text": "وَٱلسَّـٰبِقُونَ ٱلۡأَوَّلُونَ مِنَ ٱلۡمُهَـٰجِرِینَ وَٱلۡأَنصَارِ وَٱلَّذِینَ ٱتَّبَعُوهُم بِإِحۡسَـٰنࣲ رَّضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُ وَأَعَدَّ لَهُمۡ جَنَّـٰتࣲ تَجۡرِی تَحۡتَهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۚ ذَ ٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝١٠٠", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "والذين سبقوا الناس أولا إلى الإيمان بالله ورسوله من المهاجرين الذين هجروا قومهم وعشيرتهم وانتقلوا إلى دار الإسلام، والأنصار الذين نصروا رسول الله صلى الله عليه وسلم على أعدائه الكفار، والذين اتبعوهم بإحسان في الاعتقاد والأقوال والأعمال طلبًا لمرضاة الله سبحانه وتعالى، أولئك الذين رضي الله عنهم لطاعتهم الله ورسوله، ورضوا عنه لما أجزل لهم من الثواب على طاعتهم وإيمانهم، وأعدَّ لهم جنات تجري تحتها الأنهار خالدين فيها أبدًا، ذلك هو الفلاح العظيم. وفي هذه الآية تزكية للصحابة -رضي الله عنهم- وتعديل لهم، وثناء عليهم؛ ولهذا فإن توقيرهم من أصول الإيمان.", "isBasmala": false, "translation_en": "The Pioneers-The first of the Migrants and the Supporters, and those who followed them in righteousness. God is pleased with them, and they are pleased with Him. He has prepared for them Gardens beneath which rivers flow, where they will abide forever. That is the sublime triumph.", "translation_id": "Orang-orang yang terdahulu lagi yang pertama-tama (masuk Islam) dari golongan muhajirin dan anshar dan orang-orang yang mengikuti mereka dengan baik, Allah ridha kepada mereka dan merekapun ridha kepada Allah dan Allah menyediakan bagi mereka surga-surga yang mengalir sungai-sungai di dalamnya selama-lamanya. Mereka kekal di dalamnya. Itulah kemenangan yang besar.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 101, "text": "وَمِمَّنۡ حَوۡلَكُم مِّنَ ٱلۡأَعۡرَابِ مُنَـٰفِقُونَۖ وَمِنۡ أَهۡلِ ٱلۡمَدِینَةِ مَرَدُوا۟ عَلَى ٱلنِّفَاقِ لَا تَعۡلَمُهُمۡۖ نَحۡنُ نَعۡلَمُهُمۡۚ سَنُعَذِّبُهُم مَّرَّتَیۡنِ ثُمَّ یُرَدُّونَ إِلَىٰ عَذَابٍ عَظِیمࣲ ۝١٠١", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "ومن القوم الذين حول (المدينة) أعراب منافقون، ومن أهل (المدينة) منافقون أقاموا على النفاق، وازدادوا فيه طغيانًا، بحيث يخفى عليك -أيها الرسول- أمرهم، نحن نعلمهم، سنعذبهم مرتين: بالقتل والسبي والفضيحة في الدنيا، وبعذاب القبر بعد الموت، ثم يُرَدُّون يوم القيامة إلى عذاب عظيم في نار جهنم.", "isBasmala": false, "translation_en": "Among the Desert-Arabs around you there are some hypocrites, and among the inhabitants of Medina too. They have become adamant in hypocrisy. You do not know them, but We know them. We will punish them twice; then they will be returned to a severe torment.", "translation_id": "Di antara orang-orang Arab Badwi yang di sekelilingmu itu, ada orang-orang munafik; dan (juga) di antara penduduk Madinah. Mereka keterlaluan dalam kemunafikannya. Kamu (Muhammad) tidak mengetahui mereka, (tetapi) Kamilah yang mengetahui mereka. Nanti mereka akan Kami siksa dua kali kemudian mereka akan dikembalikan kepada azab yang besar.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 102, "text": "وَءَاخَرُونَ ٱعۡتَرَفُوا۟ بِذُنُوبِهِمۡ خَلَطُوا۟ عَمَلࣰا صَـٰلِحࣰا وَءَاخَرَ سَیِّئًا عَسَى ٱللَّهُ أَن یَتُوبَ عَلَیۡهِمۡۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ ۝١٠٢", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "وآخرون من أهل (المدينة) وممن حولها، اعترفوا بذنوبهم وندموا عليها وتابوا منها، خلطوا العمل الصالح -وهو التوبة والندم والاعتراف بالذنب وغير ذلك من الأعمال الصالحة- بآخر سيِّئ- وهو التخلف عن رسول الله صلى الله عليه وسلم وغيره من الأعمال السيئة -عسى الله أن يوفقهم للتوبة ويقبلها منهم. إن الله غفور لعباده، رحيم بهم.", "isBasmala": false, "translation_en": "Others have confessed their sins, having mixed good deeds with bad deeds. Perhaps God will redeem them. God is Forgiving and Merciful.", "translation_id": "Dan (ada pula) orang-orang lain yang mengakui dosa-dosa mereka, mereka mencampurbaurkan pekerjaan yang baik dengan pekerjaan lain yang buruk. Mudah-mudahan Allah menerima taubat mereka. Sesungguhnya Allah Maha Pengampun lagi maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 103, "text": "خُذۡ مِنۡ أَمۡوَ ٰلِهِمۡ صَدَقَةࣰ تُطَهِّرُهُمۡ وَتُزَكِّیهِم بِهَا وَصَلِّ عَلَیۡهِمۡۖ إِنَّ صَلَوٰتَكَ سَكَنࣱ لَّهُمۡۗ وَٱللَّهُ سَمِیعٌ عَلِیمٌ ۝١٠٣", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "خذ -أيها النبي- من أموال هؤلاء التائبين الذين خلطوا عملا صالحا وآخر سيئا صدقة تطهرهم مِن دنس ذنوبهم، وترفعهم عن منازل المنافقين إلى منازل المخلصين، وادع لهم بالمغفرة لذنوبهم واستغفر لهم منها، إن دعاءك واستغفارك رحمة وطمأنينة لهم. والله سميع لكل دعاء وقول، عليم بأحوال العباد ونياتهم، وسيجازي كلَّ عامل بعمله.", "isBasmala": false, "translation_en": "Receive contributions from their wealth, to purify them and sanctify them with it; and pray for them. Your prayer is comfort for them. God is Hearing and Knowing.", "translation_id": "Ambillah zakat dari sebagian harta mereka, dengan zakat itu kamu membersihkan dan mensucikan mereka dan mendoalah untuk mereka. Sesungguhnya doa kamu itu (menjadi) ketenteraman jiwa bagi mereka. Dan Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 104, "text": "أَلَمۡ یَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ هُوَ یَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَیَأۡخُذُ ٱلصَّدَقَـٰتِ وَأَنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِیمُ ۝١٠٤", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "ألم يعلم هؤلاء المتخلفون عن الجهاد وغيرهم أن الله وحده هو الذي يقبل توبة عباده، ويأخذ الصدقات ويثيب عليها، وأن الله هو التواب لعباده إذا رجعوا إلى طاعته، الرحيم بهم إذا أنابوا إلى رضاه؟", "isBasmala": false, "translation_en": "Do they not know that God accepts the repentance of His servants, and that He receives the contributions, and that God is the Acceptor of Repentance, the Merciful?", "translation_id": "Tidaklah mereka mengetahui, bahwasanya Allah menerima taubat dari hamba-hamba-Nya dan menerima zakat dan bahwasanya Allah Maha Penerima taubat lagi Maha Penyayang?", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 105, "text": "وَقُلِ ٱعۡمَلُوا۟ فَسَیَرَى ٱللَّهُ عَمَلَكُمۡ وَرَسُولُهُۥ وَٱلۡمُؤۡمِنُونَۖ وَسَتُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ۝١٠٥", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "وقل -أيها النبي- لهؤلاء المتخلِّفين عن الجهاد: اعملوا لله بما يرضيه من طاعته، وأداء فرائضه، واجتناب المعاصي، فسيرى الله عملكم ورسوله والمؤمنون، وسيتبين أمركم، وسترجعون يوم القيامة إلى مَن يعلم سركم وجهركم، فيخبركم بما كنتم تعملون. وفي هذا تهديد ووعيد لمن استمر على باطله وطغيانه.", "isBasmala": false, "translation_en": "Say, \"Work. God will see your work, and so will His Messenger, and the believers. Then you will be returned to the Knower of secrets and declarations, and He will inform you of what you used to do.\"", "translation_id": "Dan Katakanlah: \"Bekerjalah kamu, maka Allah dan Rasul-Nya serta orang-orang mukmin akan melihat pekerjaanmu itu, dan kamu akan dikembalikan kepada (Allah) Yang Mengetahui akan yang ghaib dan yang nyata, lalu diberitakan-Nya kepada kamu apa yang telah kamu kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 106, "text": "وَءَاخَرُونَ مُرۡجَوۡنَ لِأَمۡرِ ٱللَّهِ إِمَّا یُعَذِّبُهُمۡ وَإِمَّا یَتُوبُ عَلَیۡهِمۡۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ ۝١٠٦", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "ومن هؤلاء المتخلفين عنكم -أيها المؤمنون- في غزوة (تبوك) آخرون مؤخرون؛ ليقضي الله فيهم ما هو قاض. وهؤلاء هم الذين ندموا على ما فعلوا، وهم: مُرارة بن الربيع، وكعب بن مالك، وهلال بن أُميَّة، إما يعذبهم الله، وإما يعفو عنهم. والله عليم بمن يستحق العقوبة أو العفو، حكيم في كل أقواله وأفعاله.", "isBasmala": false, "translation_en": "Others are held in suspense, awaiting God's decree, as to whether He will punish them, or accept their repentance. God is Aware and Wise.", "translation_id": "Dan ada (pula) orang-orang lain yang ditangguhkan sampai ada keputusan Allah; adakalanya Allah akan mengazab mereka dan adakalanya Allah akan menerima taubat mereka. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}], "204": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 107, "text": "وَٱلَّذِینَ ٱتَّخَذُوا۟ مَسۡجِدࣰا ضِرَارࣰا وَكُفۡرࣰا وَتَفۡرِیقَۢا بَیۡنَ ٱلۡمُؤۡمِنِینَ وَإِرۡصَادࣰا لِّمَنۡ حَارَبَ ٱللَّهَ وَرَسُولَهُۥ مِن قَبۡلُۚ وَلَیَحۡلِفُنَّ إِنۡ أَرَدۡنَاۤ إِلَّا ٱلۡحُسۡنَىٰۖ وَٱللَّهُ یَشۡهَدُ إِنَّهُمۡ لَكَـٰذِبُونَ ۝١٠٧", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "والمنافقون الذين بنوا مسجدًا؛ مضارة للمؤمنين وكفرًا بالله وتفريقًا بين المؤمنين، ليصلي فيه بعضهم ويترك مسجد (قباء) الذي يصلي فيه المسلمون، فيختلف المسلمون ويتفرقوا بسبب ذلك، وانتظارا لمن حارب الله ورسوله من قبل -وهو أبو عامر الراهب الفاسق- ليكون مكانًا للكيد للمسلمين، وليحلفنَّ هؤلاء المنافقون أنهم ما أرادوا ببنائه إلا الخير والرفق بالمسلمين والتوسعة على الضعفاء العاجزين عن السير إلى مسجد (قباء)، والله يشهد إنهم لكاذبون فيما يحلفون عليه. وقد هُدِم المسجد وأُحرِق.", "isBasmala": false, "translation_en": "Then there are those who establish a mosque to cause harm, and disbelief, and disunity among the believers, and as an outpost for those who fight God and His Messenger. They will swear: \"Our intentions are nothing but good.\" But God bears witness that they are liars.", "translation_id": "Dan (di antara orang-orang munafik itu) ada orang-orang yang mendirikan masjid untuk menimbulkan kemudharatan (pada orang-orang mukmin), untuk kekafiran dan untuk memecah belah antara orang-orang mukmin serta menunggu kedatangan orang-orang yang telah memerangi Allah dan Rasul-Nya sejak dahulu. Mereka Sesungguhnya bersumpah: \"Kami tidak menghendaki selain kebaikan\". Dan Allah menjadi saksi bahwa sesungguhnya mereka itu adalah pendusta (dalam sumpahnya).", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 108, "text": "لَا تَقُمۡ فِیهِ أَبَدࣰاۚ لَّمَسۡجِدٌ أُسِّسَ عَلَى ٱلتَّقۡوَىٰ مِنۡ أَوَّلِ یَوۡمٍ أَحَقُّ أَن تَقُومَ فِیهِۚ فِیهِ رِجَالࣱ یُحِبُّونَ أَن یَتَطَهَّرُوا۟ۚ وَٱللَّهُ یُحِبُّ ٱلۡمُطَّهِّرِینَ ۝١٠٨", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "لا تقم -أيها النبي- للصلاة في ذلك المسجد أبدًا؛ فإن المسجد الذي أُسِّسَ على التقوى من أول يوم -وهو مسجد (قباء)- أولى أن تقوم فيه للصلاة، ففي هذا المسجد رجال يحبون أن يتطهروا بالماء من النجاسات والأقذار، كما يتطهرون بالتورع والاستغفار من الذنوب والمعاصي. والله يحب المتطهرين. وإذا كان مسجد (قباء) قد أُسِّسَ على التقوى من أول يوم، فمسجد رسول الله، صلى الله عليه وسلم، كذلك بطريق الأولى والأحرى.", "isBasmala": false, "translation_en": "Do not stand in it, ever. A mosque founded upon piety from the first day is worthier of your standing in it. In it are men who love to be purified. God loves those who purify themselves.", "translation_id": "Janganlah kamu bersembahyang dalam mesjid itu selama-lamanya. Sesungguhnya mesjid yang didirikan atas dasar takwa (mesjid Quba), sejak hari pertama adalah lebih patut kamu sholat di dalamnya. Di dalamnya mesjid itu ada orang-orang yang ingin membersihkan diri. Dan sesungguhnya Allah menyukai orang-orang yang bersih.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 109, "text": "أَفَمَنۡ أَسَّسَ بُنۡیَـٰنَهُۥ عَلَىٰ تَقۡوَىٰ مِنَ ٱللَّهِ وَرِضۡوَ ٰنٍ خَیۡرٌ أَم مَّنۡ أَسَّسَ بُنۡیَـٰنَهُۥ عَلَىٰ شَفَا جُرُفٍ هَارࣲ فَٱنۡهَارَ بِهِۦ فِی نَارِ جَهَنَّمَۗ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝١٠٩", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "لا يستوي مَن أسَّس بنيانه على تقوى الله وطاعته ومرضاته، ومن أسَّس بنيانه على طرف حفرة متداعية للسقوط، فبنى مسجدًا ضرارًا وكفرًا وتفريقًا بين المسلمين، فأدَّى به ذلك إلى السقوط في نار جهنم. والله لا يهدي القوم الظالمين المتجاوزين حدوده.", "isBasmala": false, "translation_en": "Is he who founds his structure upon piety and acceptance from God better, or he who founds his structure on the brink of a cliff that is about to tumble, so it tumbles with him into the Fire of Hell? God does not guide the unjust people.", "translation_id": "Maka apakah orang-orang yang mendirikan mesjidnya di atas dasar takwa kepada Allah dan keridhaan-(Nya) itu yang baik, ataukah orang-orang yang mendirikan bangunannya di tepi jurang yang runtuh, lalu bangunannya itu jatuh bersama-sama dengan dia ke dalam neraka Jahannam. Dan Allah tidak memberikan petunjuk kepada orang-orang yang zalim.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 110, "text": "لَا یَزَالُ بُنۡیَـٰنُهُمُ ٱلَّذِی بَنَوۡا۟ رِیبَةࣰ فِی قُلُوبِهِمۡ إِلَّاۤ أَن تَقَطَّعَ قُلُوبُهُمۡۗ وَٱللَّهُ عَلِیمٌ حَكِیمٌ ۝١١٠", "juz": 11, "hizb": "(* ح 21*)", "tafsir": "لا يزال بنيان المنافقين الذي بنوه مضارَّة لمسجد (قباء) شكًا ونفاقًا ماكثًا في قلوبهم، إلى أن تتقطع قلوبهم بقتلهم أو موتهم، أو بندمهم غاية الندم، وتوبتهم إلى ربهم، وخوفهم منه غاية الخوف. والله عليم بما عليه هؤلاء المنافقون من الشك وما قصدوا في بنائهم، حكيم في تدبير أمور خلقه.", "isBasmala": false, "translation_en": "The structure which they built will remain questionable in their hearts, until their hearts are stopped. God is Knowing and Wise.", "translation_id": "Bangunan-bangunan yang mereka dirikan itu senantiasa menjadi pangkal keraguan dalam hati mereka, kecuali bila hati mereka itu telah hancur. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 111, "text": "۞ إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِینَ أَنفُسَهُمۡ وَأَمۡوَ ٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ یُقَـٰتِلُونَ فِی سَبِیلِ ٱللَّهِ فَیَقۡتُلُونَ وَیُقۡتَلُونَۖ وَعۡدًا عَلَیۡهِ حَقࣰّا فِی ٱلتَّوۡرَىٰةِ وَٱلۡإِنجِیلِ وَٱلۡقُرۡءَانِۚ وَمَنۡ أَوۡفَىٰ بِعَهۡدِهِۦ مِنَ ٱللَّهِۚ فَٱسۡتَبۡشِرُوا۟ بِبَیۡعِكُمُ ٱلَّذِی بَایَعۡتُم بِهِۦۚ وَذَ ٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝١١١", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "إن الله اشترى من المؤمنين أنفسهم بأن لهم في مقابل ذلك الجنة، وما أعد الله فيها من النعيم لبذلهم نفوسهم وأموالهم في جهاد أعدائه لإعلاء كلمته وإظهار دينه، فيَقْتلون ويُقتَلون، وعدًا عليه حقًا في التوراة المنزلة على موسى عليه السلام، والإنجيل المنزل على عيسى عليه السلام، والقرآن المنزل على محمد صلى الله عليه وسلم. ولا أحد أوفى بعهده من الله لمن وفَّى بما عاهد الله عليه، فأظهِروا السرور-أيها المؤمنون- ببيعكم الذي بايعتم الله به، وبما وعدكم به من الجنة والرضوان، وذلك البيع هو الفلاح العظيم.", "isBasmala": false, "translation_en": "God has purchased from the believers their lives and their properties in exchange for Paradise. They fight in God's way, and they kill and get killed. It is a promise binding on Him in the Torah, and the Gospel, and the Quran. And who is more true to his promise than God? So rejoice in making such an exchange-that is the supreme triumph.", "translation_id": "Sesungguhnya Allah telah membeli dari orang-orang mukmin diri dan harta mereka dengan memberikan surga untuk mereka. Mereka berperang pada jalan Allah; lalu mereka membunuh atau terbunuh. (Itu telah menjadi) janji yang benar dari Allah di dalam Taurat, Injil dan Al Quran. Dan siapakah yang lebih menepati janjinya (selain) daripada Allah? Maka bergembiralah dengan jual beli yang telah kamu lakukan itu, dan itulah kemenangan yang besar.", "manzil": 2, "manzil_display": ""}], "205": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 112, "text": "ٱلتَّـٰۤىِٕبُونَ ٱلۡعَـٰبِدُونَ ٱلۡحَـٰمِدُونَ ٱلسَّـٰۤىِٕحُونَ ٱلرَّ ٰكِعُونَ ٱلسَّـٰجِدُونَ ٱلۡـَٔامِرُونَ بِٱلۡمَعۡرُوفِ وَٱلنَّاهُونَ عَنِ ٱلۡمُنكَرِ وَٱلۡحَـٰفِظُونَ لِحُدُودِ ٱللَّهِۗ وَبَشِّرِ ٱلۡمُؤۡمِنِینَ ۝١١٢", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "ومن صفات هؤلاء المؤمنين الذين لهم البشارة بدخول الجنة أنهم التائبون الراجعون عما كرهه الله إلى ما يحبه ويرضاه، الذين أخلصوا العبادة لله وحده وجدوا في طاعته، الذين يحمدون الله على كل ما امتحنهم به من خير أو شر، الصائمون، الراكعون في صلاتهم، الساجدون فيها، الذين يأمرون الناس بكل ما أمر الله ورسوله به، وينهونهم عن كل ما نهى الله عنه ورسوله، المؤدون فرائض الله المنتهون إلى أمره ونهيه، القائمون على طاعته، الواقفون عند حدوده. وبشِّر -أيها النبي- هؤلاء المؤمنين المتصفين بهذه الصفات برضوان الله وجنته.", "isBasmala": false, "translation_en": "Those who repent, those who worship, those who praise, those who journey, those who kneel, those who bow down, those who advocate righteousness and forbid evil, and those who keep God's limits-give good news to the believers.", "translation_id": "Mereka itu adalah orang-orang yang bertaubat, yang beribadat, yang memuji, yang melawat, yang ruku', yang sujud, yang menyuruh berbuat ma'ruf dan mencegah berbuat munkar dan yang memelihara hukum-hukum Allah. Dan gembirakanlah orang-orang mukmin itu.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 113, "text": "مَا كَانَ لِلنَّبِیِّ وَٱلَّذِینَ ءَامَنُوۤا۟ أَن یَسۡتَغۡفِرُوا۟ لِلۡمُشۡرِكِینَ وَلَوۡ كَانُوۤا۟ أُو۟لِی قُرۡبَىٰ مِنۢ بَعۡدِ مَا تَبَیَّنَ لَهُمۡ أَنَّهُمۡ أَصۡحَـٰبُ ٱلۡجَحِیمِ ۝١١٣", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "ما كان ينبغي للنبي محمد صلى الله عليه وسلم والذين آمنوا أن يدعوا بالمغفرة للمشركين، ولو كانوا ذوي قرابة لهم مِن بعد ما ماتوا على شركهم بالله وعبادة الأوثان، وتبين لهم أنهم أصحاب الجحيم لموتهم على الشرك، والله لا يغفر للمشركين، كما قال تعالى: {إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ (4:48)} وكما قال سبحانه: {إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ (5:72)}.", "isBasmala": false, "translation_en": "It is not for the Prophet and those who believe to ask forgiveness for the polytheists, even if they are near relatives, after it has become clear to them that they are people of Hellfire.", "translation_id": "Tiadalah sepatutnya bagi Nabi dan orang-orang yang beriman memintakan ampun (kepada Allah) bagi orang-orang musyrik, walaupun orang-orang musyrik itu adalah kaum kerabat(nya), sesudah jelas bagi mereka, bahwasanya orang-orang musyrik itu adalah penghuni neraka jahanam.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 114, "text": "وَمَا كَانَ ٱسۡتِغۡفَارُ إِبۡرَ ٰهِیمَ لِأَبِیهِ إِلَّا عَن مَّوۡعِدَةࣲ وَعَدَهَاۤ إِیَّاهُ فَلَمَّا تَبَیَّنَ لَهُۥۤ أَنَّهُۥ عَدُوࣱّ لِّلَّهِ تَبَرَّأَ مِنۡهُۚ إِنَّ إِبۡرَ ٰهِیمَ لَأَوَّ ٰهٌ حَلِیمࣱ ۝١١٤", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "وما كان استغفار إبراهيم عليه السلام لأبيه المشرك، إلا عن موعدة وعدها إياه، وهي قوله: {سَأَسْتَغْفِرُ لَكَ رَبِّي إِنَّهُ كَانَ بِي حَفِيًّا (19:47)}. فلما تبيَّن لإبراهيم أن أباه عدو لله ولم ينفع فيه الوعظ والتذكير، وأنه سيموت كافرًا، تركه وترك الاستغفار له، وتبرأ منه. إن إبراهيم عليه السلام عظيم التضرع لله، كثير الصفح عما يصدر مِن قومه من الزلات.", "isBasmala": false, "translation_en": "Abraham asked forgiveness for his father only because of a promise he had made to him. But when it became clear to him that he was an enemy of God, he disowned him. Abraham was kind and clement.", "translation_id": "Dan permintaan ampun dari Ibrahim (kepada Allah) untuk bapaknya tidak lain hanyalah karena suatu janji yang telah diikrarkannya kepada bapaknya itu. Maka, tatkala jelas bagi Ibrahim bahwa bapaknya itu adalah musuh Allah, maka Ibrahim berlepas diri dari padanya. Sesungguhnya Ibrahim adalah seorang yang sangat lembut hatinya lagi penyantun.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 115, "text": "وَمَا كَانَ ٱللَّهُ لِیُضِلَّ قَوۡمَۢا بَعۡدَ إِذۡ هَدَىٰهُمۡ حَتَّىٰ یُبَیِّنَ لَهُم مَّا یَتَّقُونَۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمٌ ۝١١٥", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "وما كان الله ليضلَّ قومًا بعد أن مَنَّ عليهم بالهداية والتوفيق حتى يبيِّن لهم ما يتقونه به، وما يحتاجون إليه في أصول الدين وفروعه. إن الله بكل شيء عليم، فقد علَّمكم ما لم تكونوا تعلمون، وبيَّن لكم ما به تنتفعون، وأقام الحجة عليكم بإبلاغكم رسالته.", "isBasmala": false, "translation_en": "God would never lead a people astray, after He had guided them, until He makes clear to them what they should guard against. God has knowledge of all things.", "translation_id": "Dan Allah sekali-kali tidak akan menyesatkan suatu kaum, sesudah Allah memberi petunjuk kepada mereka sehingga dijelaskan-Nya kepada mereka apa yang harus mereka jauhi. Sesungguhnya Allah Maha Mengetahui segala sesuatu.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 116, "text": "إِنَّ ٱللَّهَ لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ یُحۡیِۦ وَیُمِیتُۚ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرࣲ ۝١١٦", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "إن لله مالك السموات والأرض وما فيهن لا شريك له في الخلق والتدبير والعبادة والتشريع، يحيي مَن يشاء ويميت مَن يشاء، وما لكم مِن أحد غير الله يتولى أموركم، ولا نصير ينصركم على عدوكم.", "isBasmala": false, "translation_en": "To God belongs the dominion of the heavens and the earth. He gives life, and He causes death. And besides God, you have neither protector, nor supporter.", "translation_id": "Sesungguhnya kepunyaan Allah-lah kerajaan langit dan bumi. Dia menghidupkan dan mematikan. Dan sekali-kali tidak ada pelindung dan penolong bagimu selain Allah.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 117, "text": "لَّقَد تَّابَ ٱللَّهُ عَلَى ٱلنَّبِیِّ وَٱلۡمُهَـٰجِرِینَ وَٱلۡأَنصَارِ ٱلَّذِینَ ٱتَّبَعُوهُ فِی سَاعَةِ ٱلۡعُسۡرَةِ مِنۢ بَعۡدِ مَا كَادَ یَزِیغُ قُلُوبُ فَرِیقࣲ مِّنۡهُمۡ ثُمَّ تَابَ عَلَیۡهِمۡۚ إِنَّهُۥ بِهِمۡ رَءُوفࣱ رَّحِیمࣱ ۝١١٧", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "لقد وفَّق الله نبيه محمدا صلى الله عليه وسلم إلى الإنابة إليه وطاعته، وتاب الله على المهاجرين الذين هجروا ديارهم وعشيرتهم إلى دار الإسلام، وتاب على أنصار رسول الله صلى الله عليه وسلم الذين خرجوا معه لقتال الأعداء في غزوة (تبوك) في حرٍّ شديد، وضيق من الزاد والظَّهْر، لقد تاب الله عليهم من بعد ما كاد يَميل قلوب بعضهم عن الحق، فيميلون إلى الدَّعة والسكون، لكن الله ثبتهم وقوَّاهم وتاب عليهم، إنه بهم رؤوف رحيم. ومن رحمته بهم أنْ مَنَّ عليهم بالتوبة، وقَبِلَها منهم، وثبَّتهم عليها.", "isBasmala": false, "translation_en": "God has redeemed the Prophet, and the Emigrants, and the Supporters-those who followed him in the hour of difficulty-after the hearts of some of them almost swerved. Then He pardoned them. He is Kind towards them, Compassionate.", "translation_id": "Sesungguhnya Allah telah menerima taubat Nabi, orang-orang muhajirin dan orang-orang anshar yang mengikuti Nabi dalam masa kesulitan, setelah hati segolongan dari mereka hampir berpaling, kemudian Allah menerima taubat mereka itu. Sesungguhnya Allah Maha Pengasih lagi Maha Penyayang kepada mereka,", "manzil": 2, "manzil_display": ""}], "206": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 118, "text": "وَعَلَى ٱلثَّلَـٰثَةِ ٱلَّذِینَ خُلِّفُوا۟ حَتَّىٰۤ إِذَا ضَاقَتۡ عَلَیۡهِمُ ٱلۡأَرۡضُ بِمَا رَحُبَتۡ وَضَاقَتۡ عَلَیۡهِمۡ أَنفُسُهُمۡ وَظَنُّوۤا۟ أَن لَّا مَلۡجَأَ مِنَ ٱللَّهِ إِلَّاۤ إِلَیۡهِ ثُمَّ تَابَ عَلَیۡهِمۡ لِیَتُوبُوۤا۟ۚ إِنَّ ٱللَّهَ هُوَ ٱلتَّوَّابُ ٱلرَّحِیمُ ۝١١٨", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "وكذلك تاب الله على الثلاثة الذين خُلِّفوا من الأنصار -وهم كعب بن مالك وهلال بن أُميَّة ومُرَارة بن الربيع- تخلَّفوا عن رسول الله صلى الله عليه وسلم، وحزنوا حزنًا شديدًا، حتى إذا ضاقت عليهم الأرض بسَعَتها غمًّا وندمًا بسبب تخلفهم، وضاقت عليهم أنفسهم لِمَا أصابهم من الهم، وأيقنوا أن لا ملجأ من الله إلا إليه، وفَّقهم الله سبحانه وتعالى إلى الطاعة والرجوع إلى ما يرضيه سبحانه. إن الله هو التواب على عباده، الرحيم بهم.", "isBasmala": false, "translation_en": "Also towards the three who were left behind. Then, when the earth, as vast as it is, closed in on them, and their very souls closed in on them, and they realized that there was no refuge from God, except in Him, He redeemed them, so that they may repent. God is the Redeemer, the Merciful.", "translation_id": "dan terhadap tiga orang yang ditangguhkan (penerimaan taubat) mereka, hingga apabila bumi telah menjadi sempit bagi mereka, padahal bumi itu luas dan jiwa merekapun telah sempit (pula terasa) oleh mereka, serta mereka telah mengetahui bahwa tidak ada tempat lari dari (siksa) Allah, melainkan kepada-Nya saja. Kemudian Allah menerima taubat mereka agar mereka tetap dalam taubatnya. Sesungguhnya Allah-lah Yang maha Penerima taubat lagi Maha Penyayang.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 119, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَكُونُوا۟ مَعَ ٱلصَّـٰدِقِینَ ۝١١٩", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، امتثلوا أوامر الله واجتنبوا نواهيه في كل ما تفعلون وتتركون، وكونوا مع الصادقين في أَيمانهم وعهودهم، وفي كل شأن من شؤونهم.", "isBasmala": false, "translation_en": "O you who believe! Be conscious of God, and be with the sincere.", "translation_id": "Hai orang-orang yang beriman bertakwalah kepada Allah, dan hendaklah kamu bersama orang-orang yang benar.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 120, "text": "مَا كَانَ لِأَهۡلِ ٱلۡمَدِینَةِ وَمَنۡ حَوۡلَهُم مِّنَ ٱلۡأَعۡرَابِ أَن یَتَخَلَّفُوا۟ عَن رَّسُولِ ٱللَّهِ وَلَا یَرۡغَبُوا۟ بِأَنفُسِهِمۡ عَن نَّفۡسِهِۦۚ ذَ ٰلِكَ بِأَنَّهُمۡ لَا یُصِیبُهُمۡ ظَمَأࣱ وَلَا نَصَبࣱ وَلَا مَخۡمَصَةࣱ فِی سَبِیلِ ٱللَّهِ وَلَا یَطَـُٔونَ مَوۡطِئࣰا یَغِیظُ ٱلۡكُفَّارَ وَلَا یَنَالُونَ مِنۡ عَدُوࣲّ نَّیۡلًا إِلَّا كُتِبَ لَهُم بِهِۦ عَمَلࣱ صَـٰلِحٌۚ إِنَّ ٱللَّهَ لَا یُضِیعُ أَجۡرَ ٱلۡمُحۡسِنِینَ ۝١٢٠", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "ما كان ينبغي لأهل مدينة رسول الله صلى الله عليه وسلم ومَن حولهم من سكان البادية أن يتخلَّفوا في أهلهم ودورهم عن رسول الله صلى الله عليه وسلم، ولا يرضوا لأنفسهم بالراحة والرسول صلى الله عليه وسلم في تعب ومشقة؛ ذلك بأنهم لا يصيبهم في سفرهم وجهادهم عطش ولا تعب ولا مجاعة في سبيل الله، ولا يطؤون أرضًا يُغضِبُ الكفارَ وطؤهم إياها، ولا يصيبون مِن عدو الله وعدوهم قتلا أو هزيمةً إلا كُتِب لهم بذلك كله ثواب عمل صالح. إن الله لا يضيع أجر المحسنين.", "isBasmala": false, "translation_en": "It is not for the inhabitants of Medina and the Desert-Arabs around them to stay behind the Messenger of God, nor to prefer themselves to him. That is because they never suffer any thirst, nor fatigue, nor hunger in the cause of God, nor do they take one step that enrages the disbelievers, nor do they gain anything from an enemy, but it is recorded to their credit as a righteous deed. God does not waste the reward of the righteous.", "translation_id": "Tidaklah sepatutnya bagi penduduk Madinah dan orang-orang Arab Badwi yang berdiam di sekitar mereka, tidak turut menyertai Rasulullah (berperang) dan tidak patut (pula) bagi mereka lebih mencintai diri mereka daripada mencintai diri Rasul. Yang demikian itu ialah karena mereka tidak ditimpa kehausan, kepayahan dan kelaparan pada jalan Allah, dan tidak (pula) menginjak suatu tempat yang membangkitkan amarah orang-orang kafir, dan tidak menimpakan sesuatu bencana kepada musuh, melainkan dituliskanlah bagi mereka dengan yang demikian itu suatu amal saleh. Sesungguhnya Allah tidak menyia-nyiakan pahala orang-orang yang berbuat baik,", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 121, "text": "وَلَا یُنفِقُونَ نَفَقَةࣰ صَغِیرَةࣰ وَلَا كَبِیرَةࣰ وَلَا یَقۡطَعُونَ وَادِیًا إِلَّا كُتِبَ لَهُمۡ لِیَجۡزِیَهُمُ ٱللَّهُ أَحۡسَنَ مَا كَانُوا۟ یَعۡمَلُونَ ۝١٢١", "juz": 11, "hizb": "(*¼ ح 21*)", "tafsir": "ولا ينفقون نفقة صغيرة ولا كبيرة في سبيل الله، ولا يقطعون واديًا في سيرهم مع رسول الله صلى الله عليه وسلم في جهاده، إلا كُتِب لهم أجر عملهم؛ ليجزيهم الله أحسن ما يُجْزَون به على أعمالهم الصالحة.", "isBasmala": false, "translation_en": "Nor do they spend any expenditure, small or large, nor do they cross any valley, but it is recorded to their credit. That God may reward them in accordance with the best of their deeds.", "translation_id": "dan mereka tiada menafkahkan suatu nafkah yang kecil dan tidak (pula) yang besar dan tidak melintasi suatu lembah, melainkan dituliskan bagi mereka (amal saleh pula) karena Allah akan memberi balasan kepada mereka yang lebih baik dari apa yang telah mereka kerjakan.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 122, "text": "۞ وَمَا كَانَ ٱلۡمُؤۡمِنُونَ لِیَنفِرُوا۟ كَاۤفَّةࣰۚ فَلَوۡلَا نَفَرَ مِن كُلِّ فِرۡقَةࣲ مِّنۡهُمۡ طَاۤىِٕفَةࣱ لِّیَتَفَقَّهُوا۟ فِی ٱلدِّینِ وَلِیُنذِرُوا۟ قَوۡمَهُمۡ إِذَا رَجَعُوۤا۟ إِلَیۡهِمۡ لَعَلَّهُمۡ یَحۡذَرُونَ ۝١٢٢", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "وما كان ينبغي للمؤمنين أن يخرجوا جميعًا لقتال عدوِّهم، كما لا يستقيم لهم أن يقعدوا جميعًا، فهلا خرج من كل فرقة جماعة تحصل بهم الكفاية والمقصود؛ وذلك ليتفقه النافرون في دين الله وما أنزل على رسوله، وينذروا قومهم بما تعلموه عند رجوعهم إليهم، لعلهم يحذرون عذاب الله بامتثال أوامره واجتناب نواهيه.", "isBasmala": false, "translation_en": "It is not advisable for the believers to march out altogether. Of every division that marches out, let a group remain behind, to gain understanding of the religion, and to notify their people when they have returned to them, that they may beware.", "translation_id": "Tidak sepatutnya bagi mukminin itu pergi semuanya (ke medan perang). Mengapa tidak pergi dari tiap-tiap golongan di antara mereka beberapa orang untuk memperdalam pengetahuan mereka tentang agama dan untuk memberi peringatan kepada kaumnya apabila mereka telah kembali kepadanya, supaya mereka itu dapat menjaga dirinya.", "manzil": 2, "manzil_display": ""}], "207": [{"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 123, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ قَـٰتِلُوا۟ ٱلَّذِینَ یَلُونَكُم مِّنَ ٱلۡكُفَّارِ وَلۡیَجِدُوا۟ فِیكُمۡ غِلۡظَةࣰۚ وَٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِینَ ۝١٢٣", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، ابدؤوا بقتال الأقرب فالأقرب إلى دار الإسلام من الكفار، وليجد الكفار فيكم غِلْظة وشدة، واعلموا أن الله مع المتقين بتأييده ونصره.", "isBasmala": false, "translation_en": "O you who believe! Fight those of the disbelievers who attack you, and let them find severity in you, and know that God is with the righteous.", "translation_id": "Hai orang-orang yang beriman, perangilah orang-orang kafir yang di sekitar kamu itu, dan hendaklah mereka menemui kekerasan daripadamu, dan ketahuilah, bahwasanya Allah bersama orang-orang yang bertakwa.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 124, "text": "وَإِذَا مَاۤ أُنزِلَتۡ سُورَةࣱ فَمِنۡهُم مَّن یَقُولُ أَیُّكُمۡ زَادَتۡهُ هَـٰذِهِۦۤ إِیمَـٰنࣰاۚ فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ فَزَادَتۡهُمۡ إِیمَـٰنࣰا وَهُمۡ یَسۡتَبۡشِرُونَ ۝١٢٤", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "وإذا ما أنزل الله سورة من سور القرآن على رسوله، فمِن هؤلاء المنافقين من يقول: -إنكارًا واستهزاءً- أيُّكم زادته هذه السورة تصديقًا بالله وآياته؟ فأما الذين آمنوا بالله ورسوله فزادهم نزول السورة إيمانًا بالعلم بها وتدبرها واعتقادها والعمل بها، وهم يفرحون بما أعطاهم الله من الإيمان واليقين.", "isBasmala": false, "translation_en": "Whenever a chapter is revealed, some of them say, \"Which of you has this increased in faith?\" As for those who believe: it increases them in faith, and they rejoice.", "translation_id": "Dan apabila diturunkan suatu surat, maka di antara mereka (orang-orang munafik) ada yang berkata: \"Siapakah di antara kamu yang bertambah imannya dengan (turannya) surat ini?\" Adapun orang-orang yang beriman, maka surat ini menambah imannya, dan mereka merasa gembira.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 125, "text": "وَأَمَّا ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ فَزَادَتۡهُمۡ رِجۡسًا إِلَىٰ رِجۡسِهِمۡ وَمَاتُوا۟ وَهُمۡ كَـٰفِرُونَ ۝١٢٥", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "وأما الذين في قلوبهم نفاق وشك في دين الله، فإن نزول السورة يزيدهم نفاقًا وشكًا إلى ما هم عليه من قبلُ من النفاق والشك، وهلك هؤلاء وهم جاحدون بالله وآياته.", "isBasmala": false, "translation_en": "But as for those in whose hearts is sickness: it adds disgrace to their disgrace, and they die as unbelievers.", "translation_id": "Dan adapun orang-orang yang di dalam hati mereka ada penyakit, maka dengan surat itu bertambah kekafiran mereka, disamping kekafirannya (yang telah ada) dan mereka mati dalam keadaan kafir.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 126, "text": "أَوَ لَا یَرَوۡنَ أَنَّهُمۡ یُفۡتَنُونَ فِی كُلِّ عَامࣲ مَّرَّةً أَوۡ مَرَّتَیۡنِ ثُمَّ لَا یَتُوبُونَ وَلَا هُمۡ یَذَّكَّرُونَ ۝١٢٦", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "أولا يرى المنافقون أن الله يبتليهم بالقحط والشدة، وبإظهار ما يبطنون من النفاق مرة أو مرتين في كل عام؟ ثم هم مع ذلك لا يتوبون مِن كفرهم ونفاقهم، ولا هم يتعظون ولا يتذكرون بما يعاينون من آيات الله.", "isBasmala": false, "translation_en": "Do they not see that they are tested once or twice every year? Yet they do not repent, and they do not learn.", "translation_id": "Dan tidaklah mereka (orang-orang munafik) memperhatikan bahwa mereka diuji sekali atau dua kali setiap tahun, dan mereka tidak (juga) bertaubat dan tidak (pula) mengambil pelajaran?", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 127, "text": "وَإِذَا مَاۤ أُنزِلَتۡ سُورَةࣱ نَّظَرَ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ هَلۡ یَرَىٰكُم مِّنۡ أَحَدࣲ ثُمَّ ٱنصَرَفُوا۟ۚ صَرَفَ ٱللَّهُ قُلُوبَهُم بِأَنَّهُمۡ قَوۡمࣱ لَّا یَفۡقَهُونَ ۝١٢٧", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "وإذا ما أُنزلت سورة تغَامَزَ المنافقون بالعيون إنكارًا لنزولها وسخرية وغيظًا؛ لِمَا نزل فيها مِن ذِكْر عيوبهم وأفعالهم، ثم يقولون: هل يراكم من أحد إن قمتم من عند الرسول؟ فإن لم يرهم أحد قاموا وانصرفوا من عنده عليه الصلاة والسلام مخافة الفضيحة. صرف الله قلوبهم عن الإيمان؛ بسبب أنهم لا يفهمون ولا يتدبرون.", "isBasmala": false, "translation_en": "And whenever a chapter is revealed, they look at one another, \"Does anyone see you?\" Then they slip away. God has diverted their hearts, because they are a people who do not understand.", "translation_id": "Dan apabila diturunkan satu surat, sebagian mereka memandang kepada yang lain (sambil berkata): \"Adakah seorang dari (orang-orang muslimin) yang melihat kamu?\" Sesudah itu merekapun pergi. Allah telah memalingkan hati mereka disebabkan mereka adalah kaum yang tidak mengerti.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 128, "text": "لَقَدۡ جَاۤءَكُمۡ رَسُولࣱ مِّنۡ أَنفُسِكُمۡ عَزِیزٌ عَلَیۡهِ مَا عَنِتُّمۡ حَرِیصٌ عَلَیۡكُم بِٱلۡمُؤۡمِنِینَ رَءُوفࣱ رَّحِیمࣱ ۝١٢٨", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "لقد جاءكم أيها المؤمنون رسول من قومكم، يشق عليه ما تلقون من المكروه والعنت، حريص على إيمانكم وصلاح شأنكم، وهو بالمؤمنين كثير الرأفة والرحمة.", "isBasmala": false, "translation_en": "There has come to you a messenger from among yourselves, concerned over your suffering, anxious over you. Towards the believers, he is compassionate and merciful.", "translation_id": "Sungguh telah datang kepadamu seorang Rasul dari kaummu sendiri, berat terasa olehnya penderitaanmu, sangat menginginkan (keimanan dan keselamatan) bagimu, amat belas kasihan lagi penyayang terhadap orang-orang mukmin.", "manzil": 2, "manzil_display": ""}, {"sura": 9, "sura_name": "التوبة", "revelation": "Madaniyah", "aya": 129, "text": "فَإِن تَوَلَّوۡا۟ فَقُلۡ حَسۡبِیَ ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ عَلَیۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِیمِ ۝١٢٩", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "فإن أعرض المشركون والمنافقون عن الإيمان بك -أيها الرسول- فقل لهم: حسبي الله، يكفيني جميع ما أهمَّني، لا معبود بحق إلا هو، عليه اعتمدت، وإليه فَوَّضْتُ جميع أموري؛ فإنه ناصري ومعيني، وهو رب العرش العظيم، الذي هو أعظم المخلوقات.", "isBasmala": false, "translation_en": "If they turn away, say, \"God is enough for me; there is no god except He; in Him I have put my trust; He is the Lord of the Sublime Throne.\"", "translation_id": "Jika mereka berpaling (dari keimanan), maka katakanlah: \"Cukuplah Allah bagiku; tidak ada Tuhan selain Dia. Hanya kepada-Nya aku bertawakkal dan Dia adalah Tuhan yang memiliki 'Arsy yang agung\".", "manzil": 2, "manzil_display": ""}], "208": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 11, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 1, "text": "الۤرۚ تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡحَكِیمِ ۝١", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Ra. These are the Verses of the Wise Book.", "translation_id": "Alif laam raa. Inilah ayat-ayat Al Quran yang mengandung hikmah.", "manzil": 3, "manzil_display": "المنزل الثالث (م ي 3)"}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 2, "text": "أَكَانَ لِلنَّاسِ عَجَبًا أَنۡ أَوۡحَیۡنَاۤ إِلَىٰ رَجُلࣲ مِّنۡهُمۡ أَنۡ أَنذِرِ ٱلنَّاسَ وَبَشِّرِ ٱلَّذِینَ ءَامَنُوۤا۟ أَنَّ لَهُمۡ قَدَمَ صِدۡقٍ عِندَ رَبِّهِمۡۗ قَالَ ٱلۡكَـٰفِرُونَ إِنَّ هَـٰذَا لَسَـٰحِرࣱ مُّبِینٌ ۝٢", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "أكان أمرًا عجبًا للناس إنزالنا الوحي بالقرآن على رجل منهم ينذرهم عقاب الله، ويبشِّر الذين آمنوا بالله ورسله أن لهم أجرًا حسنًا بما قدَّموا من صالح الأعمال؟ فلما أتاهم رسول الله صلى الله عليه وسلم بوحي الله وتلاه عليهم، قال المنكرون: إنَّ محمدًا ساحر، وما جاء به سحر ظاهر البطلان.", "isBasmala": false, "translation_en": "Is it a wonder to the people that We inspired a man from among them: \"Warn mankind, and give good news to those who believe that they are on a sound footing with their Lord\"? The disbelievers said, \"This is a manifest sorcerer.\"", "translation_id": "Patutkah menjadi keheranan bagi manusia bahwa Kami mewahyukan kepada seorang laki-laki di antara mereka: \"Berilah peringatan kepada manusia dan gembirakanlah orang-orang beriman bahwa mereka mempunyai kedudukan yang tinggi di sisi Tuhan mereka\". Orang-orang kafir berkata: \"Sesungguhnya orang ini (Muhammad) benar-benar adalah tukang sihir yang nyata\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 3, "text": "إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ یُدَبِّرُ ٱلۡأَمۡرَۖ مَا مِن شَفِیعٍ إِلَّا مِنۢ بَعۡدِ إِذۡنِهِۦۚ ذَ ٰلِكُمُ ٱللَّهُ رَبُّكُمۡ فَٱعۡبُدُوهُۚ أَفَلَا تَذَكَّرُونَ ۝٣", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "إن ربكم الله الذي أوجد السموات والأرض في ستة أيام، ثم استوى -أي علا وارتفع- على العرش استواء يليق بجلاله وعظمته، يدبر أمور خلقه، لا يضادُّه في قضائه أحد، ولا يشفع عنده شافع يوم القيامة إلا من بعد أن يأذن له بالشفاعة، فاعبدوا الله ربكم المتصف بهذه الصفات، وأخلصوا له العبادة. أفلا تتعظون وتعتبرون بهذه الآيات والحجج؟", "isBasmala": false, "translation_en": "Your Lord is God, who created the heavens and the earth in six days, then settled over the Throne, governing all things. There is no intercessor except after His permission. Such is God, your Lord-so serve Him. Will you not reflect?", "translation_id": "Sesungguhnya Tuhan kamu ialah Allah Yang menciptakan langit dan bumi dalam enam masa, kemudian Dia bersemayam di atas 'Arsy untuk mengatur segala urusan. Tiada seorangpun yang akan memberi syafa'at kecuali sesudah ada izin-Nya. (Dzat) yang demikian itulah Allah, Tuhan kamu, maka sembahlah Dia. Maka apakah kamu tidak mengambil pelajaran?", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 4, "text": "إِلَیۡهِ مَرۡجِعُكُمۡ جَمِیعࣰاۖ وَعۡدَ ٱللَّهِ حَقًّاۚ إِنَّهُۥ یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ لِیَجۡزِیَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ بِٱلۡقِسۡطِۚ وَٱلَّذِینَ كَفَرُوا۟ لَهُمۡ شَرَابࣱ مِّنۡ حَمِیمࣲ وَعَذَابٌ أَلِیمُۢ بِمَا كَانُوا۟ یَكۡفُرُونَ ۝٤", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "إلى ربكم معادكم يوم القيامة جميعًا، وهذا وعد الله الحق، هو الذي يبدأ إيجاد الخلق ثم يعيده بعد الموت، فيوجده حيًا كهيئته الأولى، ليجزي مَن صَدَّق الله ورسوله، وعمل الأعمال الحسنة أحسن الجزاء بالعدل. والذين جحدوا وحدانية الله ورسالة رسوله لهم شراب من ماء شديد الحرارة يشوي الوجوه ويقطِّع الأمعاء، ولهم عذاب موجع بسبب كفرهم وضلالهم.", "isBasmala": false, "translation_en": "To Him is your return, altogether. The promise of God is true. He originates creation, and then He repeats it, to reward those who believe and do good deeds with equity. As for those who disbelieve, for them is a drink of boiling water, and agonizing torment, on account of their disbelief.", "translation_id": "Hanya kepada-Nya-lah kamu semuanya akan kembali; sebagai janji yang benar daripada Allah, sesungguhnya Allah menciptakan makhluk pada permulaannya kemudian mengulanginya (menghidupkannya) kembali (sesudah berbangkit), agar Dia memberi pembalasan kepada orang-orang yang beriman dan yang mengerjakan amal saleh dengan adil. Dan untuk orang-orang kafir disediakan minuman air yang panas dan azab yang pedih disebabkan kekafiran mereka.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 5, "text": "هُوَ ٱلَّذِی جَعَلَ ٱلشَّمۡسَ ضِیَاۤءࣰ وَٱلۡقَمَرَ نُورࣰا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُوا۟ عَدَدَ ٱلسِّنِینَ وَٱلۡحِسَابَۚ مَا خَلَقَ ٱللَّهُ ذَ ٰلِكَ إِلَّا بِٱلۡحَقِّۚ یُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡلَمُونَ ۝٥", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "الله هو الذي جعل الشمس ضياء، وجعل القمر نورًا، وقدَّر القمر منازل، فبالشمس تعرف الأيام، وبالقمر تعرف الشهور والأعوام، ما خلق الله تعالى الشمس والقمر إلا لحكمة عظيمة، ودلالة على كمال قدرة الله وعلمه، يبيِّن الحجج والأدلة لقوم يعلمون الحكمة في إبداع الخلق.", "isBasmala": false, "translation_en": "It is He who made the sun radiant, and the moon a light, and determined phases for it-that you may know the number of years and the calculation. God did not create all this except with truth. He details the revelations for a people who know.", "translation_id": "Dialah yang menjadikan matahari bersinar dan bulan bercahaya dan ditetapkan-Nya manzilah-manzilah (tempat-tempat) bagi perjalanan bulan itu, supaya kamu mengetahui bilangan tahun dan perhitungan (waktu). Allah tidak menciptakan yang demikian itu melainkan dengan hak. Dia menjelaskan tanda-tanda (kebesaran-Nya) kepada orang-orang yang mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 6, "text": "إِنَّ فِی ٱخۡتِلَـٰفِ ٱلَّیۡلِ وَٱلنَّهَارِ وَمَا خَلَقَ ٱللَّهُ فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَّقُونَ ۝٦", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "إن في تعاقب الليل والنهار وما خلق الله في السموات والأرض من عجائب الخلق وما فيهما من إبداع ونظام، لأدلة وحججًا واضحة لقوم يخشون عقاب الله وسخطه وعذابه.", "isBasmala": false, "translation_en": "In the alternation of night and day, and in what God created in the heavens and the earth, are signs for people who are aware.", "translation_id": "Sesungguhnya pada pertukaran malam dan siang itu dan pada apa yang diciptakan Allah di langit dan di bumi, benar-benar terdapat tanda-tanda (kekuasaan-Nya) bagi orang-orang yang bertakwa.", "manzil": 3, "manzil_display": ""}], "209": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 7, "text": "إِنَّ ٱلَّذِینَ لَا یَرۡجُونَ لِقَاۤءَنَا وَرَضُوا۟ بِٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَٱطۡمَأَنُّوا۟ بِهَا وَٱلَّذِینَ هُمۡ عَنۡ ءَایَـٰتِنَا غَـٰفِلُونَ ۝٧", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "إن الذين لا يطمعون في لقائنا في الآخرة للحساب، وما يتلوه من الجزاء على الأعمال لإنكارهم البعث، ورضوا بالحياة الدنيا عوضًا عن الآخرة، وركنوا إليها، والذين هم عن آياتنا الكونية والشرعية ساهون.", "isBasmala": false, "translation_en": "Those who do not hope to meet Us, and are content with the worldly life, and are at ease in it, and those who pay no heed to Our signs.", "translation_id": "Sesungguhnya orang-orang yang tidak mengharapkan (tidak percaya akan) pertemuan dengan Kami, dan merasa puas dengan kehidupan dunia serta merasa tenteram dengan kehidupan itu dan orang-orang yang melalaikan ayat-ayat Kami,", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 8, "text": "أُو۟لَـٰۤىِٕكَ مَأۡوَىٰهُمُ ٱلنَّارُ بِمَا كَانُوا۟ یَكۡسِبُونَ ۝٨", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "أولئك مقرُّهم نار جهنم في الآخرة؛ جزاء بما كانوا يكسبون في دنياهم من الآثام والخطايا.", "isBasmala": false, "translation_en": "These-their dwelling is the Fire-on account of what they used to do.", "translation_id": "mereka itu tempatnya ialah neraka, disebabkan apa yang selalu mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 9, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ یَهۡدِیهِمۡ رَبُّهُم بِإِیمَـٰنِهِمۡۖ تَجۡرِی مِن تَحۡتِهِمُ ٱلۡأَنۡهَـٰرُ فِی جَنَّـٰتِ ٱلنَّعِیمِ ۝٩", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "إن الذين آمنوا بالله ورسوله وعملوا الصالحات يدلهم ربهم إلى طريق الجنة ويوفقهم إلى العمل الموصل إليه؛ بسبب إيمانهم، ثم يثيبهم بدخول الجنة وإحلال رضوانه عليهم، تجري من تحتهم الأنهار في جنات النعيم.", "isBasmala": false, "translation_en": "As for those who believe and do good deeds, their Lord guides them in their faith. Rivers will flow beneath them in the Gardens of Bliss.", "translation_id": "Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal saleh, mereka diberi petunjuk oleh Tuhan mereka karena keimanannya, di bawah mereka mengalir sungai-sungai di dalam surga yang penuh kenikmatan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 10, "text": "دَعۡوَىٰهُمۡ فِیهَا سُبۡحَـٰنَكَ ٱللَّهُمَّ وَتَحِیَّتُهُمۡ فِیهَا سَلَـٰمࣱۚ وَءَاخِرُ دَعۡوَىٰهُمۡ أَنِ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٠", "juz": 11, "hizb": "(*½ ح 21*)", "tafsir": "دعاؤهم في الجنة التسبيح (سبحانك اللهم)، وتحية الله وملائكته لهم، وتحية بعضهم بعضًا في الجنة (سلام)، وآخر دعائهم قولهم: \"الحمد لله رب العالمين\" أي: الشكر والثناء لله خالق المخلوقات ومربِّيها بنعمه.", "isBasmala": false, "translation_en": "Their call therein is, \"Glory be to You, our God.\" And their greeting therein is, \"Peace.\" And the last of their call is, \"Praise be to God, Lord of the Worlds.\"", "translation_id": "Do'a mereka di dalamnya ialah: \"Subhanakallahumma\", dan salam penghormatan mereka ialah: \"Salam\". Dan penutup doa mereka ialah: \"Alhamdulilaahi Rabbil 'aalamin\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 11, "text": "۞ وَلَوۡ یُعَجِّلُ ٱللَّهُ لِلنَّاسِ ٱلشَّرَّ ٱسۡتِعۡجَالَهُم بِٱلۡخَیۡرِ لَقُضِیَ إِلَیۡهِمۡ أَجَلُهُمۡۖ فَنَذَرُ ٱلَّذِینَ لَا یَرۡجُونَ لِقَاۤءَنَا فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ ۝١١", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "ولو يعجِّل الله للناس إجابة دعائهم في الشر كاستعجاله لهم في الخير بالإجابة لهلكوا، فنترك الذين لا يخافون عقابنا، ولا يوقنون بالبعث والنشور في تمرُّدهم وعتوِّهم، يترددون حائرين.", "isBasmala": false, "translation_en": "If God were to accelerate the ill for the people, as they wish to accelerate the good, their term would have been fulfilled. But We leave those who do not expect Our encounter to blunder in their excesses.", "translation_id": "Dan kalau sekiranya Allah menyegerakan kejahatan bagi manusia seperti permintaan mereka untuk menyegerakan kebaikan, pastilah diakhiri umur mereka. Maka Kami biarkan orang-orang yang tidak mengharapkan pertemuan dengan Kami, bergelimangan di dalam kesesatan mereka.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 12, "text": "وَإِذَا مَسَّ ٱلۡإِنسَـٰنَ ٱلضُّرُّ دَعَانَا لِجَنۢبِهِۦۤ أَوۡ قَاعِدًا أَوۡ قَاۤىِٕمࣰا فَلَمَّا كَشَفۡنَا عَنۡهُ ضُرَّهُۥ مَرَّ كَأَن لَّمۡ یَدۡعُنَاۤ إِلَىٰ ضُرࣲّ مَّسَّهُۥۚ كَذَ ٰلِكَ زُیِّنَ لِلۡمُسۡرِفِینَ مَا كَانُوا۟ یَعۡمَلُونَ ۝١٢", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "وإذا أصاب الإنسانَ الشدةُ استغاث بنا في كشف ذلك عنه مضطجعًا لجنبه أو قاعدًا أو قائمًا، على حسب الحال التي يكون بها عند نزول ذلك الضرِّ به. فلما كشفنا عنه الشدة التي أصابته استمرَّ على طريقته الأولى قبل أن يصيبه الضر، ونسي ما كان فيه من الشدة والبلاء، وترك الشكر لربه الذي فرَّج عنه ما كان قد نزل به من البلاء، كما زُيِّن لهذا الإنسان استمراره على جحوده وعناده بعد كشف الله عنه ما كان فيه من الضر، زُيِّن للذين أسرفوا في الكذب على الله وعلى أنبيائه ما كانوا يعملون من معاصي الله والشرك به.", "isBasmala": false, "translation_en": "Whenever adversity touches the human being, he prays to Us-reclining on his side, or sitting, or standing. But when We have relieved his adversity from him, he goes away, as though he had never called on Us for trouble that had afflicted him. Thus the deeds of the transgressors appear good to them.", "translation_id": "Dan apabila manusia ditimpa bahaya dia berdoa kepada Kami dalam keadaan berbaring, duduk atau berdiri, tetapi setelah Kami hilangkan bahaya itu daripadanya, dia (kembali) melalui (jalannya yang sesat), seolah-olah dia tidak pernah berdoa kepada Kami untuk (menghilangkan) bahaya yang telah menimpanya. Begitulah orang-orang yang melampaui batas itu memandang baik apa yang selalu mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 13, "text": "وَلَقَدۡ أَهۡلَكۡنَا ٱلۡقُرُونَ مِن قَبۡلِكُمۡ لَمَّا ظَلَمُوا۟ وَجَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ وَمَا كَانُوا۟ لِیُؤۡمِنُوا۟ۚ كَذَ ٰلِكَ نَجۡزِی ٱلۡقَوۡمَ ٱلۡمُجۡرِمِینَ ۝١٣", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "ولقد أهلكنا الأمم التي كذَّبت رسل الله من قبلكم -أيها المشركون بربهم- لـمَّا أشركوا، وجاءتهم رسلهم من عند الله بالمعجزات الواضحات والحجج التي تبين صدق مَن جاء بها، فلم تكن هذه الأمم التي أهلكناها لتصدق رسلها وتنقاد لها، فاستحقوا الهلاك، ومثل ذلك الإهلاك نجزي كل مجرم متجاوز حدود الله.", "isBasmala": false, "translation_en": "We destroyed generations before you when they did wrong. Their messengers came to them with clear signs, but they would not believe. Thus We requite the sinful people.", "translation_id": "Dan sesungguhnya Kami telah membinasakan umat-umat sebelum kamu, ketika mereka berbuat kezaliman, padahal rasul-rasul mereka telah datang kepada mereka dengan membawa keterangan-keterangan yang nyata, tetapi mereka sekali-kali tidak hendak beriman. Demikianlah Kami memberi pembalasan kepada orang-orang yang berbuat dosa.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 14, "text": "ثُمَّ جَعَلۡنَـٰكُمۡ خَلَـٰۤىِٕفَ فِی ٱلۡأَرۡضِ مِنۢ بَعۡدِهِمۡ لِنَنظُرَ كَیۡفَ تَعۡمَلُونَ ۝١٤", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "ثم جعلناكم -أيها الناس- خَلَفًا في الأرض من بعد القرون الـمُهْلَكة، لننظر كيف تعملون: أخيرًا أم شرًا، فنجازيكم بذلك حسب عملكم.", "isBasmala": false, "translation_en": "Then We made you successors on earth after them, to see how you would behave.", "translation_id": "Kemudian Kami jadikan kamu pengganti-pengganti (mereka) di muka bumi sesudah mereka, supaya Kami memperhatikan bagaimana kamu berbuat.", "manzil": 3, "manzil_display": ""}], "210": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 15, "text": "وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَاتُنَا بَیِّنَـٰتࣲ قَالَ ٱلَّذِینَ لَا یَرۡجُونَ لِقَاۤءَنَا ٱئۡتِ بِقُرۡءَانٍ غَیۡرِ هَـٰذَاۤ أَوۡ بَدِّلۡهُۚ قُلۡ مَا یَكُونُ لِیۤ أَنۡ أُبَدِّلَهُۥ مِن تِلۡقَاۤىِٕ نَفۡسِیۤۖ إِنۡ أَتَّبِعُ إِلَّا مَا یُوحَىٰۤ إِلَیَّۖ إِنِّیۤ أَخَافُ إِنۡ عَصَیۡتُ رَبِّی عَذَابَ یَوۡمٍ عَظِیمࣲ ۝١٥", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "وإذا تتلى على المشركين آيات الله التي أنزلناها إليك -أيها الرسول- واضحات، قال الذين لا يخافون الحساب، ولا يرجون الثواب، ولا يؤمنون بيوم البعث والنشور: ائت بقرآن غير هذا، أو بدِّل هذا القرآن: بأن تجعل الحلال حرامًا، والحرام حلالا والوعد وعيدًا، والوعيد وعدًا، وأن تُسْقط ما فيه مِن عيب آلهتنا وتسفيه أحلامنا، قل لهم -أيها الرسول-: إن ذلك ليس إليَّ، وإنما أتبع في كل ما آمركم به وأنهاكم عنه ما ينزله عليَّ ربي ويأمرني به، إني أخشى من الله -إن خالفت أمره- عذاب يوم عظيم وهو يوم القيامة.", "isBasmala": false, "translation_en": "And when Our clear revelations are recited to them, those who do not hope to meet Us say, \"Bring a Quran other than this, or change it.\" Say, \"It is not for me to change it of my own accord. I only follow what is revealed to me. I fear, if I disobeyed my Lord, the torment of a terrible Day.\"", "translation_id": "Dan apabila dibacakan kepada mereka ayat-ayat Kami yang nyata, orang-orang yang tidak mengharapkan pertemuan dengan Kami berkata: \"Datangkanlah Al Quran yang lain dari ini atau gantilah dia\". Katakanlah: \"Tidaklah patut bagiku menggantinya dari pihak diriku sendiri. Aku tidak mengikut kecuali apa yang diwahyukan kepadaku. Sesungguhnya aku takut jika mendurhakai Tuhanku kepada siksa hari yang besar (kiamat)\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 16, "text": "قُل لَّوۡ شَاۤءَ ٱللَّهُ مَا تَلَوۡتُهُۥ عَلَیۡكُمۡ وَلَاۤ أَدۡرَىٰكُم بِهِۦۖ فَقَدۡ لَبِثۡتُ فِیكُمۡ عُمُرࣰا مِّن قَبۡلِهِۦۤۚ أَفَلَا تَعۡقِلُونَ ۝١٦", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "قل لهم -أيها الرسول-: لو شاء الله ما تلوت هذا القرآن عليكم، ولا أعلمكم الله به، فاعلموا أنه الحق من الله، فإنكم تعلمون أنني مكثت فيكم زمنًا طويلا من قبل أن يوحيه إليَّ ربي، ومن قبل أن أتلوه عليكم، أفلا تستعملون عقولكم بالتدبر والتفكر؟", "isBasmala": false, "translation_en": "Say, \"Had God willed, I would not have recited it to you, and He would not have made it known to you. I have lived among you for a lifetime before it. Do you not understand?\"", "translation_id": "Katakanlah: \"Jikalau Allah menghendaki, niscaya aku tidak membacakannya kepadamu dan Allah tidak (pula) memberitahukannya kepadamu\". Sesungguhnya aku telah tinggal bersamamu beberapa lama sebelumnya. Maka apakah kamu tidak memikirkannya?", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 17, "text": "فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔایَـٰتِهِۦۤۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلۡمُجۡرِمُونَ ۝١٧", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "لا أحد أشد ظلمًا ممن اختلق على الله الكذب أو كذَّب بآياته إنه لا ينجح مَن كذَّب أنبياء الله ورسله، ولا ينالون الفلاح.", "isBasmala": false, "translation_en": "Who does greater wrong than someone who fabricates lies about God, or denies His revelations? The guilty will never prosper.", "translation_id": "Maka siapakah yang lebih zalim daripada orang yang mengada-adakan kedustaan terhadap Allah atau mendustakan ayat-ayat-Nya? Sesungguhnya, tiadalah beruntung orang-orang yang berbuat dosa.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 18, "text": "وَیَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَضُرُّهُمۡ وَلَا یَنفَعُهُمۡ وَیَقُولُونَ هَـٰۤؤُلَاۤءِ شُفَعَـٰۤؤُنَا عِندَ ٱللَّهِۚ قُلۡ أَتُنَبِّـُٔونَ ٱللَّهَ بِمَا لَا یَعۡلَمُ فِی ٱلسَّمَـٰوَ ٰتِ وَلَا فِی ٱلۡأَرۡضِۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ ۝١٨", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "ويعبد هؤلاء المشركون من دون الله ما لا يضرهم شيئًا، ولا ينفعهم في الدنيا والآخرة، ويقولون: إنما نعبدهم ليشفعوا لنا عند الله، قل لهم -أيها الرسول-: أتخبرون الله تعالى بشيء لا يعلمه مِن أمر هؤلاء الشفعاء في السموات أو في الأرض؟ فإنه لو كان فيهما شفعاء يشفعون لكم عنده لكان أعلم بهم منكم، فالله تعالى منزَّه عما يفعله هؤلاء المشركون من إشراكهم في عبادته ما لا يضر ولا ينفع.", "isBasmala": false, "translation_en": "And they worship, besides God, what neither harms them nor benefits them. And they say, \"These are our intercessors with God.\" Say, \"Are you informing God about what He does not know in the heavens or on earth?\" Glorified be He, High above the associations they make.", "translation_id": "Dan mereka menyembah selain daripada Allah apa yang tidak dapat mendatangkan kemudharatan kepada mereka dan tidak (pula) kemanfaatan, dan mereka berkata: \"Mereka itu adalah pemberi syafa'at kepada kami di sisi Allah\". Katakanlah: \"Apakah kamu mengabarkan kepada Allah apa yang tidak diketahui-Nya baik di langit dan tidak (pula) dibumi?\" Maha Suci Allah dan Maha Tinggi dan apa yang mereka mempersekutukan (itu).", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 19, "text": "وَمَا كَانَ ٱلنَّاسُ إِلَّاۤ أُمَّةࣰ وَ ٰحِدَةࣰ فَٱخۡتَلَفُوا۟ۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَقُضِیَ بَیۡنَهُمۡ فِیمَا فِیهِ یَخۡتَلِفُونَ ۝١٩", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "كان الناس على دين واحد وهو الإسلام، ثم اختلفوا بعد ذلك، فكفر بعضهم، وثبت بعضهم على الحق. ولولا كلمة سبقت من الله بإمهال العاصين وعدم معاجلتهم بذنوبهم لقُضِيَ بينهم: بأن يُهْلك أهل الباطل منهم، وينجي أهل الحق.", "isBasmala": false, "translation_en": "Mankind was a single community; then they differed. Were it not for a prior decree from your Lord, the matters over which they had disputed would have been settled.", "translation_id": "Manusia dahulunya hanyalah satu umat, kemudian mereka berselisih. Kalau tidaklah karena suatu ketetapan yang telah ada dari Tuhanmu dahulu, pastilah telah diberi keputusan di antara mereka, tentang apa yang mereka perselisihkan itu.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 20, "text": "وَیَقُولُونَ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ ءَایَةࣱ مِّن رَّبِّهِۦۖ فَقُلۡ إِنَّمَا ٱلۡغَیۡبُ لِلَّهِ فَٱنتَظِرُوۤا۟ إِنِّی مَعَكُم مِّنَ ٱلۡمُنتَظِرِینَ ۝٢٠", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "ويقول هؤلاء الكفرة المعاندون: هلاَّ أُنزل على محمد علم ودليل، وآية حسية من ربه نعلم بها أنه على حق فيما يقول، فقل لهم -أيها الرسول-: لا يعلم الغيب أحد إلا الله، فإن شاء فعل وإن شاء لم يفعل، فانتظروا -أيها القوم- قضاء الله بيننا وبينكم بتعجيل عقوبته للمبطل منا، ونصرة صاحب الحق، إني منتظر ذلك.", "isBasmala": false, "translation_en": "And they say, \"If only a miracle was sent down to him from his Lord.\" Say, \"The realm of the unseen belongs to God; so wait, I am waiting with you.\"", "translation_id": "Dan mereka berkata: \"Mepada tidak diturunkan kepadanya (Muhammad) suatu keterangan (mukjizat) dari Tuhannya?\" Maka katakanlah: \"Sesungguhnya yang ghaib itu kepunyaan Allah, sebab itu tunggu (sajalah) olehmu, sesungguhnya aku bersama kamu termasuk orang-orang yang manunggu.", "manzil": 3, "manzil_display": ""}], "211": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 21, "text": "وَإِذَاۤ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةࣰ مِّنۢ بَعۡدِ ضَرَّاۤءَ مَسَّتۡهُمۡ إِذَا لَهُم مَّكۡرࣱ فِیۤ ءَایَاتِنَاۚ قُلِ ٱللَّهُ أَسۡرَعُ مَكۡرًاۚ إِنَّ رُسُلَنَا یَكۡتُبُونَ مَا تَمۡكُرُونَ ۝٢١", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "وإذا أذقنا المشركين يسرًا وفرجًا ورخاءً بعد عسر وشدة وكرب أصابهم، إذا هم يكذِّبون، ويستهزئون بآيات الله، قل -أيها الرسول- لهؤلاء المشركين المستهزئين: الله أسرع مكرًا واستدراجًا وعقوبة لكم. إن حَفَظَتَنا الذين نرسلهم إليكم يكتبون عليكم ما تمكرون في آياتنا، ثم نحاسبكم على ذلك.", "isBasmala": false, "translation_en": "When We make the people taste mercy after some adversity has touched them, they begin to scheme against Our revelations. Say, \"God is swifter in scheming.\" Our envoys are writing down what you scheme.", "translation_id": "Dan apabila Kami merasakan kepada manusia suatu rahmat, sesudah (datangnya) bahaya menimpa mereka, tiba-tiba mereka mempunyai tipu daya dalam (menentang) tanda-tanda kekuasaan Kami. Katakanlah: \"Allah lebih cepat pembalasannya (atas tipu daya itu)\". Sesungguhnya malaikat-malaikat Kami menuliskan tipu dayamu.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 22, "text": "هُوَ ٱلَّذِی یُسَیِّرُكُمۡ فِی ٱلۡبَرِّ وَٱلۡبَحۡرِۖ حَتَّىٰۤ إِذَا كُنتُمۡ فِی ٱلۡفُلۡكِ وَجَرَیۡنَ بِهِم بِرِیحࣲ طَیِّبَةࣲ وَفَرِحُوا۟ بِهَا جَاۤءَتۡهَا رِیحٌ عَاصِفࣱ وَجَاۤءَهُمُ ٱلۡمَوۡجُ مِن كُلِّ مَكَانࣲ وَظَنُّوۤا۟ أَنَّهُمۡ أُحِیطَ بِهِمۡ دَعَوُا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ لَىِٕنۡ أَنجَیۡتَنَا مِنۡ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِینَ ۝٢٢", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "هو الذي يسيِّركم -أيها الناس- في البر على الدواب وغيرها، وفي البحر في السُّفُن، حتى إذا كنتم فيها وجرت بريح طيبة، وفرح ركاب السفن بالريح الطيبة، جاءت هذه السفنَ ريحٌ شديدة، وجاء الركابَ الموجُ (وهو ما ارتفع من الماء) من كل مكان، وأيقنوا أن الهلاك قد أحاط بهم، أخلصوا الدعاء لله وحده، وتركوا ما كانوا يعبدون، وقالوا: لئن أنجيتنا من هذه الشدة التي نحن فيها لنكونن من الشاكرين لك على نِعَمك.", "isBasmala": false, "translation_en": "It is He who transports you across land and sea. Until, when you are on ships, sailing in a favorable wind, and rejoicing in it, a raging wind arrives. The waves surge over them from every side, and they realize that they are besieged. Thereupon they pray to God, professing sincere devotion to Him: \"If You save us from this, we will be among the appreciative.\"", "translation_id": "Dialah Tuhan yang menjadikan kamu dapat berjalan di daratan, (berlayar) di lautan. Sehingga apabila kamu berada di dalam bahtera, dan meluncurlah bahtera itu membawa orang-orang yang ada di dalamnya dengan tiupan angin yang baik, dan mereka bergembira karenanya, datanglah angin badai, dan (apabila) gelombang dari segenap penjuru menimpanya, dan mereka yakin bahwa mereka telah terkepung (bahaya), maka mereka berdoa kepada Allah dengan mengikhlaskan ketaatan kepada-Nya semata-mata. (Mereka berkata): \"Sesungguhnya jika Engkau menyelamatkan kami dari bahaya ini, pastilah kami akan termasuk orang-orang yang bersyukur\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 23, "text": "فَلَمَّاۤ أَنجَىٰهُمۡ إِذَا هُمۡ یَبۡغُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّۗ یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّمَا بَغۡیُكُمۡ عَلَىٰۤ أَنفُسِكُمۖ مَّتَـٰعَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ ثُمَّ إِلَیۡنَا مَرۡجِعُكُمۡ فَنُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٢٣", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "فلما أنجاهم الله من الشدائد والأهوال إذا هم يعملون في الأرض بالفساد وبالمعاصي. يا أيها الناس إنما وَبالُ بغيكم راجع على أنفسكم، لكم متاع في الحياة الدنيا الزائلة، ثم إلينا مصيركم ومرجعكم، فنخبركم بجميع أعمالكم، ونحاسبكم عليها.", "isBasmala": false, "translation_en": "But then, when He has saved them, they commit violations on earth, and oppose justice. O people! Your violations are against your own souls. It is the enjoyment of the present life. Then to Us is your return, and We will inform you of what you used to do.", "translation_id": "Maka tatkala Allah menyelamatkan mereka, tiba-tiba mereka membuat kezaliman di muka bumi tanpa (alasan) yang benar. Hai manusia, sesungguhnya (bencana) kezalimanmu akan menimpa dirimu sendiri; (hasil kezalimanmu) itu hanyalah kenikmatan hidup duniawi, kemudian kepada Kami-lah kembalimu, lalu Kami kabarkan kepadamu apa yang telah kamu kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 24, "text": "إِنَّمَا مَثَلُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا كَمَاۤءٍ أَنزَلۡنَـٰهُ مِنَ ٱلسَّمَاۤءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ مِمَّا یَأۡكُلُ ٱلنَّاسُ وَٱلۡأَنۡعَـٰمُ حَتَّىٰۤ إِذَاۤ أَخَذَتِ ٱلۡأَرۡضُ زُخۡرُفَهَا وَٱزَّیَّنَتۡ وَظَنَّ أَهۡلُهَاۤ أَنَّهُمۡ قَـٰدِرُونَ عَلَیۡهَاۤ أَتَىٰهَاۤ أَمۡرُنَا لَیۡلًا أَوۡ نَهَارࣰا فَجَعَلۡنَـٰهَا حَصِیدࣰا كَأَن لَّمۡ تَغۡنَ بِٱلۡأَمۡسِۚ كَذَ ٰلِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَتَفَكَّرُونَ ۝٢٤", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "إنما مثل الحياة الدنيا وما تتفاخرون به فيها من زينة وأموال، كمثل مطر أنزلناه من السماء إلى الأرض، فنبتت به أنواع من النبات مختلط بعضها ببعض مما يقتات به الناس من الثمار، وما تأكله الحيوانات من النبات، حتى إذا ظهر حُسْنُ هذه الأرض وبهاؤها، وظن أهل هذه الأرض أنهم قادرون على حصادها والانتفاع بها، جاءها أمرنا وقضاؤنا بهلاك ما عليها من النبات، والزينة إما ليلا وإما نهارًا، فجعلنا هذه النباتات والأشجار محصودة مقطوعة لا شيء فيها، كأن لم تكن تلك الزروع والنباتات قائمة قبل ذلك على وجه الأرض، فكذلك يأتي الفناء على ما تتباهَون به من دنياكم وزخارفها فيفنيها الله ويهلكها. وكما بيَّنا لكم -أيها الناس- مَثَلَ هذه الدنيا وعرَّفناكم بحقيقتها، نبيِّن حججنا وأدلتنا لقوم يتفكرون في آيات الله، ويتدبرون ما ينفعهم في الدنيا والآخرة.", "isBasmala": false, "translation_en": "The likeness of the present life is this: water that We send down from the sky is absorbed by the plants of the earth, from which the people and the animals eat. Until, when the earth puts on its fine appearance, and is beautified, and its inhabitants think that they have mastered it, Our command descends upon it by night or by day, and We turn it into stubble, as if it had not flourished the day before. We thus clarify the revelations for people who reflect.", "translation_id": "Sesungguhnya perumpamaan kehidupan duniawi itu, adalah seperti air (hujan) yang Kami turunkan dan langit, lalu tumbuhlah dengan suburnya karena air itu tanam-tanaman bumi, di antaranya ada yang dimakan manusia dan binatang ternak. Hingga apabila bumi itu telah sempurna keindahannya, dan memakai (pula) perhiasannya, dan pemilik-permliknya mengira bahwa mereka pasti menguasasinya, tiba-tiba datanglah kepadanya azab Kami di waktu malam atau siang, lalu Kami jadikan (tanam-tanamannya) laksana tanam-tanaman yang sudah disabit, seakan-akan belum pernah tumbuh kemarin. Demikianlah Kami menjelaskan tanda-tanda kekuasaan (Kami) kepada orang-orang berfikir.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 25, "text": "وَٱللَّهُ یَدۡعُوۤا۟ إِلَىٰ دَارِ ٱلسَّلَـٰمِ وَیَهۡدِی مَن یَشَاۤءُ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٢٥", "juz": 11, "hizb": "(*¾ ح 21*)", "tafsir": "والله يدعوكم إلى جناته التي أعدها لأوليائه، ويهدي مَن يشاء مِن خَلْقه، فيوفقه لإصابة الطريق المستقيم، وهو الإسلام.", "isBasmala": false, "translation_en": "God invites to the Home of Peace, and guides whomever He wills to a straight path.", "translation_id": "Allah menyeru (manusia) ke Darussalam (surga), dan menunjuki orang yang dikehendaki-Nya kepada jalan yang lurus (Islam).", "manzil": 3, "manzil_display": ""}], "212": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 26, "text": "۞ لِّلَّذِینَ أَحۡسَنُوا۟ ٱلۡحُسۡنَىٰ وَزِیَادَةࣱۖ وَلَا یَرۡهَقُ وُجُوهَهُمۡ قَتَرࣱ وَلَا ذِلَّةٌۚ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٢٦", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "للمؤمنين الذين أحسنوا عبادة الله فأطاعوه فيما أمر ونهى، الجنةُ، وزيادة عليها، وهي النظر إلى وجه الله تعالى في الجنة، والمغفرةُ والرضوان، ولا يغشى وجوههم غبار ولا ذلة، كما يلحق أهل النار. هؤلاء المتصفون بهذه الصفات هم أصحاب الجنة ماكثون فيها أبدًا.", "isBasmala": false, "translation_en": "For those who have done good is goodness, and more. Neither gloom nor shame will come over their faces. These are the inhabitants of Paradise, abiding therein forever.", "translation_id": "Bagi orang-orang yang berbuat baik, ada pahala yang terbaik (surga) dan tambahannya. Dan muka mereka tidak ditutupi debu hitam dan tidak (pula) kehinaan. Mereka itulah penghuni surga, mereka kekal di dalamnya.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 27, "text": "وَٱلَّذِینَ كَسَبُوا۟ ٱلسَّیِّـَٔاتِ جَزَاۤءُ سَیِّئَةِۭ بِمِثۡلِهَا وَتَرۡهَقُهُمۡ ذِلَّةࣱۖ مَّا لَهُم مِّنَ ٱللَّهِ مِنۡ عَاصِمࣲۖ كَأَنَّمَاۤ أُغۡشِیَتۡ وُجُوهُهُمۡ قِطَعࣰا مِّنَ ٱلَّیۡلِ مُظۡلِمًاۚ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٢٧", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "والذين عملوا السيئات في الدنيا فكفروا وعصَوا الله لهم جزاء أعمالهم السيئة التي عملوها بمثلها من عقاب الله في الآخرة، وتغشاهم ذلَّة وهوان، وليس لهم مِن عذاب الله مِن مانع يمنعهم إذا عاقبهم، كأنما أُلبست وجوههم طائفة من سواد الليل المظلم. هؤلاء هم أهل النار ماكثون فيها أبدًا.", "isBasmala": false, "translation_en": "As for those who have earned evil deeds: a reward of similar evil, and shame will cover them. They will have no defense against God-as if their faces are covered with dark patches of night. These are the inmates of the Fire, abiding therein forever.", "translation_id": "Dan orang-orang yang mengerjakan kejahatan (mendapat) balasan yang setimpal dan mereka ditutupi kehinaan. Tidak ada bagi mereka seorang pelindungpun dari (azab) Allah, seakan-akan muka mereka ditutupi dengan kepingan-kepingan malam yang gelap gelita. Mereka itulah penghuni neraka; mereka kekal di dalamnya.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 28, "text": "وَیَوۡمَ نَحۡشُرُهُمۡ جَمِیعࣰا ثُمَّ نَقُولُ لِلَّذِینَ أَشۡرَكُوا۟ مَكَانَكُمۡ أَنتُمۡ وَشُرَكَاۤؤُكُمۡۚ فَزَیَّلۡنَا بَیۡنَهُمۡۖ وَقَالَ شُرَكَاۤؤُهُم مَّا كُنتُمۡ إِیَّانَا تَعۡبُدُونَ ۝٢٨", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "واذكر -أيها الرسول- يوم نحشر الخلق جميعا للحساب والجزاء، ثم نقول للذين أشركوا بالله: الزموا مكانكم أنتم وشركاؤكم الذين كنتم تعبدونهم من دون الله حتى تنظروا ما يُفْعل بكم، فَفَرَّقْنا بين المشركين ومعبوديهم، وتبرَّأ مَن عُبِدُوا مِن دون الله ممن كانوا يعبدونهم، وقالوا للمشركين: ما كنتم إيانا تعبدون في الدنيا.", "isBasmala": false, "translation_en": "On the Day when We will gather them altogether, then say to those who ascribed partners, \"To your place, you and your partners.\" Then We will separate between them, and their partners will say, \"It was not us you were worshiping.\"", "translation_id": "(Ingatlah) suatu hari (ketika itu). Kami mengumpulkan mereka semuanya, kemudian Kami berkata kepada orang-orang yang mempersekutukan (Tuhan): \"Tetaplah kamu dan sekutu-sekutumu di tempatmu itu\". Lalu Kami pisahkan mereka dan berkatalah sekutu-sekutu mereka: \"Kamu sekali-kali tidak pernah menyembah kami.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 29, "text": "فَكَفَىٰ بِٱللَّهِ شَهِیدَۢا بَیۡنَنَا وَبَیۡنَكُمۡ إِن كُنَّا عَنۡ عِبَادَتِكُمۡ لَغَـٰفِلِینَ ۝٢٩", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "فكفى بالله شهيدًا بيننا وبينكم، إننا لم نكن نعلم ما كنتم تقولون وتفعلون، ولقد كنَّا عن عبادتكم إيانا غافلين، لا نشعر بها.", "isBasmala": false, "translation_en": "\"God is sufficient witness between us and you. We were unaware of your worshiping us.\"", "translation_id": "Dan cukuplah Allah menjadi saksi antara kami dengan kamu, bahwa kami tidak tahu-menahu tentang penyembahan kamu (kepada kami).", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 30, "text": "هُنَالِكَ تَبۡلُوا۟ كُلُّ نَفۡسࣲ مَّاۤ أَسۡلَفَتۡۚ وَرُدُّوۤا۟ إِلَى ٱللَّهِ مَوۡلَىٰهُمُ ٱلۡحَقِّۖ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ ۝٣٠", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "في ذلك الموقف للحساب تتفقد كل نفس أحوالها وأعمالها التي سلفت وتعاينها، وتجازى بحسبها: إن خيرًا فخير، وإن شرًا فشر، ورُدَّ الجميع إلى الله الحكم العدل، فأُدخِلَ أهل الجنةِ الجنةَ وأهل النار النار، وذهب عن المشركين ما كانوا يعبدون من دون الله افتراء عليه.", "isBasmala": false, "translation_en": "There, every soul will experience what it had done previously; and they will be returned to God, their True Master; and what they used to invent will fail them.", "translation_id": "Di tempat itu (padang Mahsyar), tiap-tiap diri merasakan pembalasan dari apa yang telah dikerjakannya dahulu dan mereka dikembalikan kepada Allah Pelindung mereka yang sebenarnya dan lenyaplah dari mereka apa yang mereka ada-adakan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 31, "text": "قُلۡ مَن یَرۡزُقُكُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ أَمَّن یَمۡلِكُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَمَن یُخۡرِجُ ٱلۡحَیَّ مِنَ ٱلۡمَیِّتِ وَیُخۡرِجُ ٱلۡمَیِّتَ مِنَ ٱلۡحَیِّ وَمَن یُدَبِّرُ ٱلۡأَمۡرَۚ فَسَیَقُولُونَ ٱللَّهُۚ فَقُلۡ أَفَلَا تَتَّقُونَ ۝٣١", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: مَن يرزقكم من السماء، بما يُنزله من المطر، ومن الأرض بما ينبته فيها من أنواع النبات والشجر تأكلون منه أنتم وأنعامكم؟ ومَن يملك ما تتمتعون به أنتم وغيركم من حواسِّ السمع والأبصار؟ ومن ذا الذي يملك الحياة والموت في الكون كلِّه، فيخرج الأحياء والأموات بعضها من بعض فيما تعرفون من المخلوقات، وفيما لا تعرفون؟ ومَن يدبِّر أمر السماء والأرض وما فيهن، وأمركم وأمر الخليقة جميعًا؟ فسوف يجيبونك بأن الذي يفعل ذلك كله هو الله، فقل لهم: أفلا تخافون عقاب الله إن عبدتم معه غيره؟", "isBasmala": false, "translation_en": "Say, \"Who provides for you from the heaven and the earth? And who controls the hearing and the sight? And who produces the living from the dead, and produces the dead from the living? And who governs the Order?\" They will say, \"God.\" Say, \"Will you not be careful?\"", "translation_id": "Katakanlah: \"Siapakah yang memberi rezeki kepadamu dari langit dan bumi, atau siapakah yang kuasa (menciptakan) pendengaran dan penglihatan, dan siapakah yang mengeluarkan yang hidup dari yang mati dan mengeluarkan yang mati dari yang hidup dan siapakah yang mengatur segala urusan?\" Maka mereka akan menjawab: \"Allah\". Maka katakanlah \"Mangapa kamu tidak bertakwa kepada-Nya)?\"", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 32, "text": "فَذَ ٰلِكُمُ ٱللَّهُ رَبُّكُمُ ٱلۡحَقُّۖ فَمَاذَا بَعۡدَ ٱلۡحَقِّ إِلَّا ٱلضَّلَـٰلُۖ فَأَنَّىٰ تُصۡرَفُونَ ۝٣٢", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "فذلكم الله ربكم هو الحق الذي لا ريب فيه، المستَحِق للعبادة وحده لا شريك له، فأي شيء سوى الحق إلا الضلال؟، فكيف تُصْرَفون عن عبادته إلى عبادة ما سواه؟", "isBasmala": false, "translation_en": "Such is God, your Lord-the True. What is there, beyond the truth, except falsehood? How are you turned away?", "translation_id": "Maka (Zat yang demikian) itulah Allah Tuhan kamu yang sebenarnya; maka tidak ada sesudah kebenaran itu, melainkan kesesatan. Maka bagaimanakah kamu dipalingkan (dari kebenaran)?", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 33, "text": "كَذَ ٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِینَ فَسَقُوۤا۟ أَنَّهُمۡ لَا یُؤۡمِنُونَ ۝٣٣", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "كما كفر هؤلاء المشركون واستمرُّوا على شركهم، حقت كلمة ربك وحكمه وقضاؤه على الذين خرجوا عن طاعة ربهم إلى معصيته وكفروا به أنَّهم لا يصدقون بوحدانية الله، ولا بنبوة نبيِّه محمد صلى الله عليه وسلم، ولا يعملون بهديه.", "isBasmala": false, "translation_en": "Thus your Lord's Word proved true against those who disobeyed, for they do not believe.", "translation_id": "Demikianlah telah tetap hukuman Tuhanmu terhadap orang-orang yang fasik, karena sesungguhnya mereka tidak beriman.", "manzil": 3, "manzil_display": ""}], "213": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 34, "text": "قُلۡ هَلۡ مِن شُرَكَاۤىِٕكُم مَّن یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥۚ قُلِ ٱللَّهُ یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥۖ فَأَنَّىٰ تُؤۡفَكُونَ ۝٣٤", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "قل لهم -أيها الرسول-: هل من آلهتكم ومعبوداتكم مَن يبدأ خَلْق أي شيء من غير أصل، ثم يفنيه بعد إنشائه، ثم يعيده كهيئته قبل أن يفنيه؟ فإنهم لا يقدرون على دعوى ذلك، قل -أيها الرسول-: الله تعالى وحده هو الذي ينشئ الخلق ثم يفنيه ثم يعيده، فكيف تنصرفون عن طريق الحق إلى الباطل، وهو عبادة غير الله؟", "isBasmala": false, "translation_en": "Say, \"Can any of your partners initiate creation, and then repeat it?\" Say, \"God initiates creation, and then repeats it. How are you so deluded?\"", "translation_id": "Katakanlah: \"Apakah di antara sekutu-sekutumu ada yang dapat memulai penciptaan makhluk, kemudian mengulanginya (menghidupkannya) kembali?\" katakanlah: \"Allah-lah yang memulai penciptaan makhluk, kemudian mengulanginya (menghidupkannya) kembali; maka bagaimanakah kamu dipalingkan (kepada menyembah yang selain Allah)?\"", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 35, "text": "قُلۡ هَلۡ مِن شُرَكَاۤىِٕكُم مَّن یَهۡدِیۤ إِلَى ٱلۡحَقِّۚ قُلِ ٱللَّهُ یَهۡدِی لِلۡحَقِّۗ أَفَمَن یَهۡدِیۤ إِلَى ٱلۡحَقِّ أَحَقُّ أَن یُتَّبَعَ أَمَّن لَّا یَهِدِّیۤ إِلَّاۤ أَن یُهۡدَىٰۖ فَمَا لَكُمۡ كَیۡفَ تَحۡكُمُونَ ۝٣٥", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: هل مِن شركائكم مَن يرشد إلى الطريق المستقيم؟ فإنهم لا يقدرون على ذلك، قل لهم: الله وحده يهدي الضال عن الهدى إلى الحق. أيهما أحق بالاتباع: مَن يهدي وحده للحق أم من لا يهتدي لعدم علمه ولضلاله، وهي شركاؤكم التي لا تَهدي ولا تَهتدي إلا أن تُهدَى؟ فما بالكم كيف سوَّيتم بين الله وخلقه؟ وهذا حكم باطل.", "isBasmala": false, "translation_en": "Say, \"Can any of your partners guide to the truth?\" Say, \"God guides to the truth. Is He who guides to the truth more worthy of being followed, or he who does not guide, unless he himself is guided? What is the matter with you? How do you judge?\"", "translation_id": "Katakanlah: \"Apakah di antara sekutu-sekuturmu ada yang menunjuki kepada kebenaran?\" Katakanlah \"Allah-lah yang menunjuki kepada kebenaran\". Maka apakah orang-orang yang menunjuki kepada kebenaran itu lebih berhak diikuti ataukah orang yang tidak dapat memberi petunjuk kecuali (bila) diberi petunjuk? Mengapa kamu (berbuat demikian)? Bagaimanakah kamu mengambil keputusan?", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 36, "text": "وَمَا یَتَّبِعُ أَكۡثَرُهُمۡ إِلَّا ظَنًّاۚ إِنَّ ٱلظَّنَّ لَا یُغۡنِی مِنَ ٱلۡحَقِّ شَیۡـًٔاۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِمَا یَفۡعَلُونَ ۝٣٦", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "وما يتبع أكثر هؤلاء المشركين في جعلهم الأصنام آلهة واعتقادهم بأنها تقرِّب إلى الله إلا تخرصًا وظنًا، وهو لا يغني من اليقين شيئًا. إن الله عليم بما يفعل هؤلاء المشركون من الكفر والتكذيب.", "isBasmala": false, "translation_en": "Most of them follow nothing but assumptions; and assumptions avail nothing against the truth. God is fully aware of what they do.", "translation_id": "Dan kebanyakan mereka tidak mengikuti kecuali persangkaan saja. Sesungguhnya persangkaan itu tidak sedikitpun berguna untuk mencapai kebenaran. Sesungguhnya Allah Maha Mengetahui apa yang mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 37, "text": "وَمَا كَانَ هَـٰذَا ٱلۡقُرۡءَانُ أَن یُفۡتَرَىٰ مِن دُونِ ٱللَّهِ وَلَـٰكِن تَصۡدِیقَ ٱلَّذِی بَیۡنَ یَدَیۡهِ وَتَفۡصِیلَ ٱلۡكِتَـٰبِ لَا رَیۡبَ فِیهِ مِن رَّبِّ ٱلۡعَـٰلَمِینَ ۝٣٧", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "وما كان يتهيَّأ لأحد أن يأتي بهذا القرآن مِن عند غير الله، لأنه لا يقدر على ذلك أحد من الخلق، ولكن الله أنزله مصدِّقا للكتب التي أنزلها على أنبيائه؛ لأن دين الله واحد، وفي هذا القرآن بيان وتفصيل لما شرعه الله لأمة محمد صلى الله عليه وسلم، لا شك في أن هذا القرآن موحىً من رب العالمين.", "isBasmala": false, "translation_en": "This Quran could not have been produced by anyone other than God. In fact, it is a confirmation of what preceded it, and an elaboration of the Book. There is no doubt about it-it is from the Lord of the Universe.", "translation_id": "Tidaklah mungkin Al Quran ini dibuat oleh selain Allah; akan tetapi (Al Quran itu) membenarkan kitab-kitab yang sebelumnya dan menjelaskan hukum-hukum yang telah ditetapkannya, tidak ada keraguan di dalamnya, (diturunkan) dari Tuhan semesta alam.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 38, "text": "أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُوا۟ بِسُورَةࣲ مِّثۡلِهِۦ وَٱدۡعُوا۟ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَـٰدِقِینَ ۝٣٨", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "بل أيقولون: إن هذا القرآن افتراه محمد من عند نفسه؟ فإنهم يعلمون أنه بشر مثلهم!! قل لهم -أيها الرسول-: فأتوا أنتم بسورة واحدة من جنس هذا القرآن في نظمه وهدايته، واستعينوا على ذلك بكل مَن قَدَرْتم عليه من دون الله من إنس وجن، إن كنتم صادقين في دعواكم.", "isBasmala": false, "translation_en": "Or do they say, \"He has forged it\"? Say, \"Then produce a single chapter like it, and call upon whomever you can, apart from God, if you are truthful.\"", "translation_id": "Atau (patutkah) mereka mengatakan \"Muhammad membuat-buatnya\". Katakanlah: \"(Kalau benar yang kamu katakan itu), maka cobalah datangkan sebuah surat seumpamanya dan panggillah siapa-siapa yang dapat kamu panggil (untuk membuatnya) selain Allah, jika kamu orang yang benar\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 39, "text": "بَلۡ كَذَّبُوا۟ بِمَا لَمۡ یُحِیطُوا۟ بِعِلۡمِهِۦ وَلَمَّا یَأۡتِهِمۡ تَأۡوِیلُهُۥۚ كَذَ ٰلِكَ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلظَّـٰلِمِینَ ۝٣٩", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "بل سارَعوا إلى التكذيب بالقرآن أول ما سمعوه، قبل أن يتدبروا آياته، وكفروا بما لم يحيطوا بعلمه من ذكر البعث والجزاء والجنة والنار وغير ذلك، ولم يأتهم بعدُ حقيقة ما وُعِدوا به في الكتاب. وكما كذَّب المشركون بوعيد الله كذَّبت الأمم التي خلت قبلهم، فانظر -أيها الرسول- كيف كانت عاقبة الظالمين؟ فقد أهلك الله بعضهم بالخسف، وبعضهم بالغرق، وبعضهم بغير ذلك.", "isBasmala": false, "translation_en": "In fact, they deny what is beyond the limits of their knowledge, and whose explanation has not yet reached them. Thus those before them refused to believe. So note the consequences for the wrongdoers.", "translation_id": "Bahkan yang sebenarnya, mereka mendustakan apa yang mereka belum mengetahuinya dengan sempurna padahal belum datang kepada mereka penjelasannya. Demikianlah orang-orang yang sebelum mereka telah mendustakan (rasul). Maka perhatikanlah bagaimana akibat orang-orang yang zalim itu.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 40, "text": "وَمِنۡهُم مَّن یُؤۡمِنُ بِهِۦ وَمِنۡهُم مَّن لَّا یُؤۡمِنُ بِهِۦۚ وَرَبُّكَ أَعۡلَمُ بِٱلۡمُفۡسِدِینَ ۝٤٠", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "ومِن قومك -أيها الرسول- مَن يصدِّق بالقرآن، ومنهم من لا يصدِّق به حتى يموت على ذلك ويبعث عليه، وربك أعلم بالمفسدين الذين لا يؤمنون به على وجه الظلم والعناد والفساد، فيجازيهم على فسادهم بأشد العذاب.", "isBasmala": false, "translation_en": "Among them are those who believe in it, and among them are those who do not believe in it. Your Lord is fully aware of the mischief-makers.", "translation_id": "Di antara mereka ada orang-orang yang beriman kepada Al Quran, dan di antaranya ada (pula) orang-orang yang tidak beriman kepadanya. Tuhanmu lebih mengetahui tentang orang-orang yang berbuat kerusakan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 41, "text": "وَإِن كَذَّبُوكَ فَقُل لِّی عَمَلِی وَلَكُمۡ عَمَلُكُمۡۖ أَنتُم بَرِیۤـُٔونَ مِمَّاۤ أَعۡمَلُ وَأَنَا۠ بَرِیۤءࣱ مِّمَّا تَعۡمَلُونَ ۝٤١", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "وإن كذَّبك -أيها الرسول- هؤلاء المشركون فقل لهم: لي ديني وعملي، ولكم دينكم وعملكم، فأنتم لا تؤاخَذون بعملي، وأنا لا أؤاخَذ بعملكم.", "isBasmala": false, "translation_en": "If they accuse you of lying, say, \"I have my deeds, and you have your deeds. You are quit of what I do, and I am quit of what you do.\"", "translation_id": "Jika mereka mendustakan kamu, maka katakanlah: \"Bagiku pekerjaanku dan bagimu pekerjaanmu. Kamu berlepas diri terhadap apa yang aku kerjakan dan akupun berlepas diri terhadap apa yang kamu kerjakan\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 42, "text": "وَمِنۡهُم مَّن یَسۡتَمِعُونَ إِلَیۡكَۚ أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ وَلَوۡ كَانُوا۟ لَا یَعۡقِلُونَ ۝٤٢", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "ومِنَ الكفار مَن يسمعون كلامك الحق، وتلاوتك القرآن، ولكنهم لا يهتدون. أفأنت تَقْدر على إسماع الصم؟ فكذلك لا تقدر على هداية هؤلاء إلا أن يشاء الله هدايتهم؛ لأنهم صمٌّ عن سماع الحق، لا يعقلونه.", "isBasmala": false, "translation_en": "And among them are those who listen to you. But can you make the deaf hear, even though they do not understand?", "translation_id": "Dan di antara mereka ada orang yang mendengarkanmu. Apakah kamu dapat menjadikan orang-orang tuli itu mendengar walaupun mereka tidak mengerti.", "manzil": 3, "manzil_display": ""}], "214": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 43, "text": "وَمِنۡهُم مَّن یَنظُرُ إِلَیۡكَۚ أَفَأَنتَ تَهۡدِی ٱلۡعُمۡیَ وَلَوۡ كَانُوا۟ لَا یُبۡصِرُونَ ۝٤٣", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "ومِنَ الكفار مَن ينظر إليك وإلى أدلة نبوتك الصادقة، ولكنه لا يبصر ما آتاك الله من نور الإيمان، أفأنت -أيها الرسول- تقدر على أن تخلق للعمي أبصارًا يهتدون بها؟ فكذلك لا تقدر على هدايتهم إذا كانوا فاقدي البصيرة، وإنما ذلك كلُّه لله وحده.", "isBasmala": false, "translation_en": "And among them are those who look at you. But can you guide the blind, even though they do not see?", "translation_id": "Dan di antara mereka ada orang yang melihat kepadamu, apakah dapat kamu memberi petunjuk kepada orang-orang yang buta, walaupun mereka tidak dapat memperhatikan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 44, "text": "إِنَّ ٱللَّهَ لَا یَظۡلِمُ ٱلنَّاسَ شَیۡـࣰٔا وَلَـٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ یَظۡلِمُونَ ۝٤٤", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "إن الله لا يظلم الناس شيئًا بزيادة في سيئاتهم أو نقص من حسناتهم، ولكن الناس هم الذين يظلمون أنفسهم بالكفر والمعصية ومخالفة أمر الله ونهيه.", "isBasmala": false, "translation_en": "God does not wrong the people in the least, but the people wrong their own selves.", "translation_id": "Sesungguhnya Allah tidak berbuat zalim kepada manusia sedikitpun, akan tetapi manusia itulah yang berbuat zalim kepada diri mereka sendiri.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 45, "text": "وَیَوۡمَ یَحۡشُرُهُمۡ كَأَن لَّمۡ یَلۡبَثُوۤا۟ إِلَّا سَاعَةࣰ مِّنَ ٱلنَّهَارِ یَتَعَارَفُونَ بَیۡنَهُمۡۚ قَدۡ خَسِرَ ٱلَّذِینَ كَذَّبُوا۟ بِلِقَاۤءِ ٱللَّهِ وَمَا كَانُوا۟ مُهۡتَدِینَ ۝٤٥", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "ويوم يَحشر الله هؤلاء المشركين يوم البعث والحساب، كأنهم قبل ذلك لم يمكثوا في الحياة الدنيا إلا قدر ساعة من النهار، يعرف بعضهم بعضًا كحالهم في الدنيا، ثم انقطعت تلك المعرفة وانقضت تلك الساعة. قد خسر الذين كفروا وكذَّبوا بلقاء الله وثوابه وعقابه، وما كانوا موفَّقين لإصابة الرشد فيما فعلوا.", "isBasmala": false, "translation_en": "On the Day when He rounds them up-as if they had tarried only one hour of a day-they will recognize one another. Those who denied the meeting with God will be the losers. They were not guided.", "translation_id": "Dan (ingatlah) akan hari (yang di waktu itu) Allah mengumpulkan mereka, (mereka merasa di hari itu) seakan-akan mereka tidak pernah berdiam (di dunia) hanya sesaat di siang hari, (di waktu itu) mereka saling berkenalan. Sesungguhnya rugilah orang-orang yang mendustakan pertemuan mereka dengan Allah dan mereka tidak mendapat petunjuk", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 46, "text": "وَإِمَّا نُرِیَنَّكَ بَعۡضَ ٱلَّذِی نَعِدُهُمۡ أَوۡ نَتَوَفَّیَنَّكَ فَإِلَیۡنَا مَرۡجِعُهُمۡ ثُمَّ ٱللَّهُ شَهِیدٌ عَلَىٰ مَا یَفۡعَلُونَ ۝٤٦", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "وإمَّا نرينَّك -أيها الرسول- في حياتك بعض الذي نَعِدُهم من العقاب في الدنيا، أو نتوفينك قبل أن نريك ذلك فيهم، فإلينا وحدنا يرجع أمرهم في الحالتين، ثم الله شهيد على أفعالهم التي كانوا يفعلونها في الدنيا، لا يخفى عليه شيء منها، فيجازيهم بها جزاءهم الذي يستحقونه.", "isBasmala": false, "translation_en": "Whether We show you some of what We promise them, or take you, to Us is their return. God is witness to everything they do.", "translation_id": "Dan jika Kami perlihatkan kepadamu sebahagian dari (siksa) yang Kami ancamkan kepada mereka, (tentulah kamu akan melihatnya) atau (jika) Kami wafatkan kamu (sebelum itu), maka kepada Kami jualah mereka kembali, dan Allah menjadi saksi atas apa yang mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 47, "text": "وَلِكُلِّ أُمَّةࣲ رَّسُولࣱۖ فَإِذَا جَاۤءَ رَسُولُهُمۡ قُضِیَ بَیۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا یُظۡلَمُونَ ۝٤٧", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "ولكل أمة خَلَتْ قبلكم -أيها الناس- رسول أرسلتُه إليهم، كما أرسلت محمدًا إليكم يدعو إلى دين الله وطاعته، فإذا جاء رسولهم في الآخرة قُضِيَ حينئذ بينهم بالعدل، وهم لا يُظلمون مِن جزاء أعمالهم شيئًا.", "isBasmala": false, "translation_en": "Every community has a messenger. When their messenger has come, judgment will be passed between them with fairness, and they will not be wronged.", "translation_id": "Tiap-tiap umat mempunyai rasul; maka apabila telah datang rasul mereka, diberikanlah keputusan antara mereka dengan adil dan mereka (sedikitpun) tidak dianiaya.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 48, "text": "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ ۝٤٨", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "ويقول المشركون من قومك -أيها الرسول-: متى قيام الساعة إن كنت أنت ومَن تبعك من الصادقين فيما تَعِدوننا به؟", "isBasmala": false, "translation_en": "And they say, \"When will this promise be fulfilled, if you are truthful?\"", "translation_id": "Mereka mengatakan: \"Bilakah (datangnya) ancaman itu, jika memang kamu orang-orang yang benar?\"", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 49, "text": "قُل لَّاۤ أَمۡلِكُ لِنَفۡسِی ضَرࣰّا وَلَا نَفۡعًا إِلَّا مَا شَاۤءَ ٱللَّهُۗ لِكُلِّ أُمَّةٍ أَجَلٌۚ إِذَا جَاۤءَ أَجَلُهُمۡ فَلَا یَسۡتَـٔۡخِرُونَ سَاعَةࣰ وَلَا یَسۡتَقۡدِمُونَ ۝٤٩", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "قل لهم -أيها الرسول-: لا أستطيع أن أدفع عن نفسي ضرًا، ولا أجلب لها نفعًا، إلا ما شاء الله أن يدفع عني مِن ضرٍّ أو يجلب لي من نفع. لكل قوم وقت لانقضاء مدتهم وأجلهم، إذا جاء وقت انقضاء أجلهم وفناء أعمارهم، فلا يستأخرون عنه ساعة فيُمْهلون، ولا يتقدم أجلهم عن الوقت المعلوم.", "isBasmala": false, "translation_en": "Say, \"I have no power to harm or benefit myself, except as God wills. To every nation is an appointed time. Then, when their time arrives, they can neither postpone it by one hour, nor advance it.", "translation_id": "Katakanlah: \"Aku tidak berkuasa mendatangkan kemudharatan dan tidak (pula) kemanfaatan kepada diriku, melainkan apa yang dikehendaki Allah\". Tiap-tiap umat mempunyai ajal. Apabila telah datang ajal mereka, maka mereka tidak dapat mengundurkannya barang sesaatpun dan tidak (pula) mendahulukan(nya).", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 50, "text": "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَتَىٰكُمۡ عَذَابُهُۥ بَیَـٰتًا أَوۡ نَهَارࣰا مَّاذَا یَسۡتَعۡجِلُ مِنۡهُ ٱلۡمُجۡرِمُونَ ۝٥٠", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن أتاكم عذاب الله ليلا أو نهارًا، فأي شيء تستعجلون أيها المجرمون بنزول العذاب؟", "isBasmala": false, "translation_en": "Say, \"Have you considered? If His punishment overtakes you by night or by day, what part of it will the guilty seek to hasten?\"", "translation_id": "Katakanlah: \"Terangkan kepadaku, jika datang kepada kamu sekalian sikaaan-Nya di waktu malam atau di siang hari, apakah orang-orang yang berdosa itu meminta disegerakan juga?\"", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 51, "text": "أَثُمَّ إِذَا مَا وَقَعَ ءَامَنتُم بِهِۦۤۚ ءَاۤلۡـَٔـٰنَ وَقَدۡ كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ ۝٥١", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "أبعدما وقع عذاب الله بكم -أيها المشركون- آمنتم في وقت لا ينفعكم فيه الإيمان؟ وقيل لكم حينئذ: آلآن تؤمنون به، وقد كنتم من قبل تستعجلون به؟", "isBasmala": false, "translation_en": "\"Then, when it falls, will you believe in it? Now? When before you tried to hasten it?\"", "translation_id": "Kemudian apakah setelah terjadinya (azab itu), kemudian itu kamu baru mempercayainya? Apakah sekarang (baru kamu mempercayai), padahal sebelumnya kamu selalu meminta supaya disegerakan?", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 52, "text": "ثُمَّ قِیلَ لِلَّذِینَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلۡخُلۡدِ هَلۡ تُجۡزَوۡنَ إِلَّا بِمَا كُنتُمۡ تَكۡسِبُونَ ۝٥٢", "juz": 11, "hizb": "(* ح 22*)", "tafsir": "ثم قيل للذين ظلموا أنفسهم بكفرهم بالله: تجرَّعوا عذاب الله الدائم لكم أبدًا، فهل تُعاقَبون إلا بما كنتم تعملون في حياتكم من معاصي الله؟", "isBasmala": false, "translation_en": "Then it will be said to those who did wrong, \"Taste the torment of eternity. Will you be rewarded except for what you used to do?\"", "translation_id": "Kemudian dikatakan kepada orang-orang yang zalim (musyrik) itu: \"Rasakanlah olehmu siksaan yang kekal; kamu tidak diberi balasan melainkan dengan apa yang telah kamu kerjakan\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 53, "text": "۞ وَیَسۡتَنۢبِـُٔونَكَ أَحَقٌّ هُوَۖ قُلۡ إِی وَرَبِّیۤ إِنَّهُۥ لَحَقࣱّۖ وَمَاۤ أَنتُم بِمُعۡجِزِینَ ۝٥٣", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "ويستخبرك هؤلاء المشركون من قومك -أيها الرسول- عن العذاب يوم القيامة، أحقٌّ هو؟ قل لهم -أيها الرسول-: نعم وربي إنه لحق لا شك فيه، وما أنتم بمعجزين الله أن يبعثكم ويجازيكم، فأنتم في قبضته وسلطانه.", "isBasmala": false, "translation_en": "And they inquire of you, \"Is it true?\" Say, \"Yes, by my Lord, it is true, and you cannot evade it.\"", "translation_id": "Dan mereka menanyakan kepadamu: \"Benarkah (azab yang dijanjikan) itu? Katakanlah: \"Ya, demi Tuhanku, sesungguhnya azab itu adalah benar dan kamu sekali-kali tidak bisa luput (daripadanya)\".", "manzil": 3, "manzil_display": ""}], "215": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 54, "text": "وَلَوۡ أَنَّ لِكُلِّ نَفۡسࣲ ظَلَمَتۡ مَا فِی ٱلۡأَرۡضِ لَٱفۡتَدَتۡ بِهِۦۗ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلۡعَذَابَۖ وَقُضِیَ بَیۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا یُظۡلَمُونَ ۝٥٤", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "ولو أن لكل نفس أشركت وكفرت بالله جميع ما في الأرض، وأمكنها أن تجعله فداء لها من ذلك العذاب لافتدت به، وأخفى الذين ظلموا حسرتهم حين أبصروا عذاب الله واقعا بهم جميعًا، وقضى الله عز وجل بينهم بالعدل، وهم لا يُظلَمون؛ لأن الله تعالى لا يعاقب أحدا إلا بذنبه.", "isBasmala": false, "translation_en": "Had every soul which had done wrong possessed everything on earth, it would offer it as a ransom. They will hide the remorse when they witness the suffering, and it will be judged between them equitably, and they will not be wronged.", "translation_id": "Dan kalau setiap diri yang zalim (muayrik) itu mempunyai segala apa yang ada di bumi ini, tentu dia menebus dirinya dengan itu, dan mereka membunyikan penyesalannya ketika mereka telah menyaksikan azab itu. Dan telah diberi keputusan di antara mereka dengan adil, sedang mereka tidak dianiaya.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 55, "text": "أَلَاۤ إِنَّ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۗ أَلَاۤ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ ۝٥٥", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "ألا إن كل ما في السموات وما في الأرض ملك لله تعالى، لا شيء من ذلك لأحد سواه. ألا إن لقاء الله تعالى وعذابه للمشركين كائن، ولكن أكثرهم لا يعلمون حقيقة ذلك.", "isBasmala": false, "translation_en": "Assuredly, to God belongs everything in the heavens and the earth. Assuredly, the promise of God is true. But most of them do not know.", "translation_id": "Ingatlah, sesungguhnya kepunyaan Allah apa yang ada di langit dan di bumi. Ingatlah, sesungguhnya janji Allah itu benar, tetapi kebanyakan mereka tidak mengetahui(nya).", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 56, "text": "هُوَ یُحۡیِۦ وَیُمِیتُ وَإِلَیۡهِ تُرۡجَعُونَ ۝٥٦", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "إن الله هو المحيي والمميت لا يتعذَّر عليه إحياء الناس بعد موتهم، كما لا تعجزه إماتتهم إذا أراد ذلك، وهم إليه راجعون بعد موتهم.", "isBasmala": false, "translation_en": "He gives life and causes death, and to Him you will be returned.", "translation_id": "Dialah yang menghidupkan dan mematikan dan hanya kepada-Nya-lah kamu dikembalikan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 57, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ قَدۡ جَاۤءَتۡكُم مَّوۡعِظَةࣱ مِّن رَّبِّكُمۡ وَشِفَاۤءࣱ لِّمَا فِی ٱلصُّدُورِ وَهُدࣰى وَرَحۡمَةࣱ لِّلۡمُؤۡمِنِینَ ۝٥٧", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "يا أيها الناس قد جاءتكم موعظة من ربكم تذكِّركم عقاب الله وتخوفكم وعيده، وهي القرآن وما اشتمل عليه من الآيات والعظات لإصلاح أخلاقكم وأعمالكم، وفيه دواء لما في القلوب من الجهل والشرك وسائر الأمراض، ورشد لمن اتبعه من الخلق فينجيه من الهلاك، جعله سبحانه وتعالى نعمة ورحمة للمؤمنين، وخصَّهم بذلك؛ لأنهم المنتفعون بالإيمان، وأما الكافرون فهو عليهم عَمَى.", "isBasmala": false, "translation_en": "O people! There has come to you advice from your Lord, and healing for what is in the hearts, and guidance and mercy for the believers.", "translation_id": "Hai manusia, sesungguhnya telah datang kepadamu pelajaran dari Tuhanmu dan penyembuh bagi penyakit-penyakit (yang berada) dalam dada dan petunjuk serta rahmat bagi orang-orang yang beriman.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 58, "text": "قُلۡ بِفَضۡلِ ٱللَّهِ وَبِرَحۡمَتِهِۦ فَبِذَ ٰلِكَ فَلۡیَفۡرَحُوا۟ هُوَ خَیۡرࣱ مِّمَّا یَجۡمَعُونَ ۝٥٨", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "قل -أيها الرسول- لجميع الناس: بفضل الله وبرحمته، وهو ما جاءهم من الله من الهدى ودين الحق وهو الإسلام، فبذلك فليفرحوا؛ فإن الإسلام الذي دعاهم الله إليه، والقرآن الذي أنزله على محمد صلى الله عليه وسلم، خير مما يجمعون من حطام الدنيا وما فيها من الزهرة الفانية الذاهبة.", "isBasmala": false, "translation_en": "Say, \"In God's grace and mercy let them rejoice. That is better than what they hoard.\"", "translation_id": "Katakanlah: \"Dengan kurnia Allah dan rahmat-Nya, hendaklah dengan itu mereka bergembira. Kurnia Allah dan rahmat-Nya itu adalah lebih baik dari apa yang mereka kumpulkan\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 59, "text": "قُلۡ أَرَءَیۡتُم مَّاۤ أَنزَلَ ٱللَّهُ لَكُم مِّن رِّزۡقࣲ فَجَعَلۡتُم مِّنۡهُ حَرَامࣰا وَحَلَـٰلࣰا قُلۡ ءَاۤللَّهُ أَذِنَ لَكُمۡۖ أَمۡ عَلَى ٱللَّهِ تَفۡتَرُونَ ۝٥٩", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "قل -أيها الرسول- لهؤلاء الجاحدين للوحي: أخبروني عن هذا الرزق الذي خلقه الله لكم من الحيوان والنبات والخيرات فحلَّلتم بعض ذلك لأنفسكم وحرَّمتم بعضه، قل لهم: آلله أذن لكم بذلك، أم تقولون على الله الباطل وتكذبون؟ وإنهم ليقولون على الله الباطل ويكذبون.", "isBasmala": false, "translation_en": "Say, \"Have you considered the sustenance God has sent down for you, some of which you made unlawful, and some lawful?\" Say, \"Did God give you permission, or do you fabricate lies and attribute them to God?\"", "translation_id": "Katakanlah: \"Terangkanlah kepadaku tentang rezeki yang diturunkan Allah kepadamu, lalu kamu jadikan sebagiannya haram dan (sebagiannya) halal\". Katakanlah: \"Apakah Allah telah memberikan izin kepadamu (tentang ini) atau kamu mengada-adakan saja terhadap Allah?\"", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 60, "text": "وَمَا ظَنُّ ٱلَّذِینَ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ یَوۡمَ ٱلۡقِیَـٰمَةِۗ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَشۡكُرُونَ ۝٦٠", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "وما ظنُّ هؤلاء الذين يتخرصون على الله الكذب يوم الحساب، فيضيفون إليه تحريم ما لم يحرمه عليهم من الأرزاق والأقوات، أن الله فاعل بهم يوم القيامة بكذبهم وفِرْيَتِهم عليه؟ أيحسبون أنه يصفح عنهم ويغفر لهم؟ إن الله لذو فضل على خلقه؛ بتركه معاجلة مَن افترى عليه الكذب بالعقوبة في الدنيا وإمهاله إياه، ولكن أكثر الناس لا يشكرون الله على تفضله عليهم بذلك.", "isBasmala": false, "translation_en": "What will they think-those who fabricate lies and attribute them to God-on the Day of Resurrection? God is bountiful towards the people, but most of them do not give thanks.", "translation_id": "Apakah dugaan orang-orang yang mengada-adakan kebohongan terhadap Allah pada hari kiamat? Sesungguhnya Allah benar-benar mempunyai karunia (yang dilimpahkan) atas manusia, tetapi kebanyakan mereka tidak mensyukuri(nya).", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 61, "text": "وَمَا تَكُونُ فِی شَأۡنࣲ وَمَا تَتۡلُوا۟ مِنۡهُ مِن قُرۡءَانࣲ وَلَا تَعۡمَلُونَ مِنۡ عَمَلٍ إِلَّا كُنَّا عَلَیۡكُمۡ شُهُودًا إِذۡ تُفِیضُونَ فِیهِۚ وَمَا یَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةࣲ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَاۤءِ وَلَاۤ أَصۡغَرَ مِن ذَ ٰلِكَ وَلَاۤ أَكۡبَرَ إِلَّا فِی كِتَـٰبࣲ مُّبِینٍ ۝٦١", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "وما تكون -أيها الرسول- في أمر مِن أمورك وما تتلو من كتاب الله من آيات، وما يعمل أحد من هذه الأمة عملا من خير أو شر إلا كنا عليكم شهودًا مُطَّلِعين عليه، إذ تأخذون في ذلك، وتعملونه، فنحفظه عليكم ونجزيكم به، وما يغيب عن علم ربك -أيها الرسول- من زنة نملة صغيرة في الأرض ولا في السماء، ولا أصغر الأشياء ولا أكبرها، إلا في كتاب عند الله واضح جلي، أحاط به علمه وجرى به قلمه.", "isBasmala": false, "translation_en": "You do not get into any situation, nor do you recite any Quran, nor do you do anything, but We are watching over you as you undertake it. Not even the weight of an atom, on earth or in the sky, escapes your Lord, nor is there anything smaller or larger, but is in a clear record.", "translation_id": "Kamu tidak berada dalam suatu keadaan dan tidak membaca suatu ayat dari Al Quran dan kamu tidak mengerjakan suatu pekerjaan, melainkan Kami menjadi saksi atasmu di waktu kamu melakukannya. Tidak luput dari pengetahuan Tuhanmu biarpun sebesar zarrah (atom) di bumi ataupun di langit. Tidak ada yang lebih kecil dan tidak (pula) yang lebih besar dari itu, melainkan (semua tercatat) dalam kitab yang nyata (Lauh Mahfuzh).", "manzil": 3, "manzil_display": ""}], "216": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 62, "text": "أَلَاۤ إِنَّ أَوۡلِیَاۤءَ ٱللَّهِ لَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝٦٢", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "ألا إن أولياء الله لا خوف عليهم في الآخرة من عقاب الله، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا.", "isBasmala": false, "translation_en": "Unquestionably, God's friends have nothing to fear, nor shall they grieve.", "translation_id": "Ingatlah, sesungguhnya wali-wali Allah itu, tidak ada kekhawatiran terhadap mereka dan tidak (pula) mereka bersedih hati.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 63, "text": "ٱلَّذِینَ ءَامَنُوا۟ وَكَانُوا۟ یَتَّقُونَ ۝٦٣", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "وصفات هؤلاء الأولياء، أنهم الذين صدَّقوا الله واتبعوا رسوله وما جاء به من عند الله، وكانوا يتقون الله بامتثال أوامره، واجتناب معاصيه.", "isBasmala": false, "translation_en": "Those who believe and are aware.", "translation_id": "(Yaitu) orang-orang yang beriman dan mereka selalu bertakwa.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 64, "text": "لَهُمُ ٱلۡبُشۡرَىٰ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَفِی ٱلۡـَٔاخِرَةِۚ لَا تَبۡدِیلَ لِكَلِمَـٰتِ ٱللَّهِۚ ذَ ٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝٦٤", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "لهؤلاء الأولياء البشارة من الله في الحياة الدنيا بما يسرُّهم، وفي الآخرة بالجنة، لا يخلف الله وعده ولا يغيِّره، ذلك هو الفوز العظيم؛ لأنه اشتمل على النجاة مِن كل محذور، والظَّفَر بكل مطلوب محبوب.", "isBasmala": false, "translation_en": "For them is good news in this life, and in the Hereafter. There is no alteration to the words of God. That is the supreme triumph.", "translation_id": "Bagi mereka berita gembira di dalam kehidupan di dunia dan (dalam kehidupan} di akhirat. Tidak ada perubahan bagi kalimat-kalimat (janji-janji) Allah. Yang demikian itu adalah kemenangan yang besar.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 65, "text": "وَلَا یَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِیعًاۚ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٦٥", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "ولا يحزنك -أيها الرسول- قول المشركين في ربهم وافتراؤهم عليه وإشراكهم معه الأوثان والأصنام؛ فإن الله تعالى هو المتفرد بالقوة الكاملة والقدرة التامة في الدنيا والآخرة، وهو السميع لأقوالهم، العليم بأفعالهم ونياتهم.", "isBasmala": false, "translation_en": "And let not their sayings dishearten you. All power is God's. He is the Hearer, the Knower.", "translation_id": "Janganlah kamu sedih oleh perkataan mereka. Sesungguhnya kekuasaan itu seluruhnya adalah kepunyaan Allah. Dialah Yang Maha Mendengar lagi Maha Mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 66, "text": "أَلَاۤ إِنَّ لِلَّهِ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَمَن فِی ٱلۡأَرۡضِۗ وَمَا یَتَّبِعُ ٱلَّذِینَ یَدۡعُونَ مِن دُونِ ٱللَّهِ شُرَكَاۤءَۚ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا یَخۡرُصُونَ ۝٦٦", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "ألا إن لله كل مَن في السموات ومن في الأرض من الملائكة، والإنس، والجن وغير ذلك. وأي شيء يتَّبع مَن يدعو غير الله من الشركاء؟ ما يتَّبعون إلا الشك، وإن هم إلا يكذبون فيما ينسبونه إلى الله.", "isBasmala": false, "translation_en": "Certainly, to God belongs everyone in the heavens and everyone on earth. Those who invoke other than God do not follow partners; they follow only assumptions, and they only guess.", "translation_id": "Ingatlah, sesungguhnya kepunyaan Allah semua yang ada di langit dan semua yang ada di bumi. Dan orang-orang yang menyeru sekutu-sekutu selain Allah, tidaklah mengikuti (suatu keyakinan). Mereka tidak mengikuti kecuali prasangka belaka, dan mereka hanyalah menduga-duga.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 67, "text": "هُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلَّیۡلَ لِتَسۡكُنُوا۟ فِیهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَسۡمَعُونَ ۝٦٧", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "هو الذي جعل لكم -أيها الناس- الليل لتسكنوا فيه وتهدؤوا من عناء الحركة في طلب المعاش، وجعل لكم النهار؛ لتبصروا فيه، ولتسعَوْا لطلب رزقكم. إن في اختلاف الليل والنهار وحال أهلهما فيهما لَدلالةً وحججًا على أن الله وحده هو المستحق للعبادة، لقوم يسمعون هذه الحجج، ويتفكرون فيها.", "isBasmala": false, "translation_en": "It is He who made the night for your rest, and the daylight for visibility. Surely in that are signs for people who listen.", "translation_id": "Dialah yang menjadikan malam bagi kamu supaya kamu beristirahat padanya dan (menjadikan) siang terang benderang (supaya kamu mencari karunia Allah). Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang mendengar.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 68, "text": "قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدࣰاۗ سُبۡحَـٰنَهُۥۖ هُوَ ٱلۡغَنِیُّۖ لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۚ إِنۡ عِندَكُم مِّن سُلۡطَـٰنِۭ بِهَـٰذَاۤۚ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝٦٨", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "قال المشركون: اتخذ الله ولدًا، كقولهم: الملائكة بنات الله، أو المسيح ابن الله. تقدَّس الله عن ذلك كله وتنزَّه، هو الغني عن كل ما سواه، له كل ما في السموات والأرض، فكيف يكون له ولد ممن خلق وكل شيء مملوك له؟ وليس لديكم دليل على ما تفترونه من الكذب، أتقولون على الله ما لا تعلمون حقيقته وصحته؟", "isBasmala": false, "translation_en": "And they said, \"God has taken a son.\" Be He glorified. He is the Self-Sufficient. His is everything in the heavens and everything on earth. Do you have any proof for this? Or are you saying about God what you do not know?", "translation_id": "Mereka (orang-orang Yahudi dan Nasrani) berkata: \"Allah mempuyai anak\". Maha Suci Allah; Dialah Yang Maha Kaya; kepunyaan-Nya apa yang ada di langit dan apa yang di bumi. Kamu tidak mempunyai hujjah tentang ini. Pantaskah kamu mengatakan terhadap Allah apa yang tidak kamu ketahui?", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 69, "text": "قُلۡ إِنَّ ٱلَّذِینَ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا یُفۡلِحُونَ ۝٦٩", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "قل: إن الذين يفترون على الله الكذب باتخاذ الولد وإضافة الشريك إليه، لا ينالون مطلوبهم في الدنيا ولا في الآخرة.", "isBasmala": false, "translation_en": "Say, \"Those who fabricate lies about God will not succeed.\"", "translation_id": "Katakanlah: \"Sesungguhnya orang-orang yang mengada-adakan kebohongan terhadap Allah tidak beruntung\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 70, "text": "مَتَـٰعࣱ فِی ٱلدُّنۡیَا ثُمَّ إِلَیۡنَا مَرۡجِعُهُمۡ ثُمَّ نُذِیقُهُمُ ٱلۡعَذَابَ ٱلشَّدِیدَ بِمَا كَانُوا۟ یَكۡفُرُونَ ۝٧٠", "juz": 11, "hizb": "(*¼ ح 22*)", "tafsir": "إنما يتمتعون في الدنيا بكفرهم وكذبهم متاعًا قصيرًا، ثم إذا انقضى أجلهم فإلينا مصيرهم، ثم نذيقهم عذاب جهنم بسبب كفرهم بالله وتكذيبهم رسل الله، وجحدهم آياته.", "isBasmala": false, "translation_en": "Some enjoyment in this world; then to Us is their return; then We will make them taste the severe punishment on account of their disbelief.", "translation_id": "(Bagi mereka) kesenangan (sementara) di dunia, kemudian kepada Kami-lah mereka kembali, kemudian Kami rasakan kepada mereka siksa yang berat, disebabkan kekafiran mereka.", "manzil": 3, "manzil_display": ""}], "217": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 71, "text": "۞ وَٱتۡلُ عَلَیۡهِمۡ نَبَأَ نُوحٍ إِذۡ قَالَ لِقَوۡمِهِۦ یَـٰقَوۡمِ إِن كَانَ كَبُرَ عَلَیۡكُم مَّقَامِی وَتَذۡكِیرِی بِـَٔایَـٰتِ ٱللَّهِ فَعَلَى ٱللَّهِ تَوَكَّلۡتُ فَأَجۡمِعُوۤا۟ أَمۡرَكُمۡ وَشُرَكَاۤءَكُمۡ ثُمَّ لَا یَكُنۡ أَمۡرُكُمۡ عَلَیۡكُمۡ غُمَّةࣰ ثُمَّ ٱقۡضُوۤا۟ إِلَیَّ وَلَا تُنظِرُونِ ۝٧١", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "واقصص -أيها الرسول- على كفار \"مكة\" خبر نوح -عليه السلام- مع قومه حين قال لهم: إن كان عَظُمَ عليكم مقامي فيكم وتذكيري إياكم بحجج الله وبراهينه فعلى الله اعتمادي وبه ثقتي، فأعدُّوا أمركم، وادعوا شركاءكم، ثم لا تجعلوا أمركم عليكم مستترًا بل ظاهرًا منكشفًا، ثم اقضوا عليَّ بالعقوبة والسوء الذي في إمكانكم، ولا تمهلوني ساعة من نهار.", "isBasmala": false, "translation_en": "And relate to them the story of Noah, when he said to his people, \"O my people, if my presence among you and my reminding you of God's signs is too much for you, then in God I have put my trust. So come to a decision, you and your partners, and do not let the matter perplex you; then carry out your decision on me, and do not hold back.\"", "translation_id": "Dan bacakanIah kepada mereka berita penting tentang Nuh di waktu dia berkata kepada kaumnya: \"Hai kaumku, jika terasa berat bagimu tinggal (bersamaku) dan peringatanku (kepadamu) dengan ayat-ayat Allah, maka kepada Allah-lah aku bertawakal, karena itu bulatkanlah keputusanmu dan (kumpulkanlah) sekutu-sekutumu (untuk membinasakanku). Kemudian janganlah keputusanmu itu dirahasiakan, lalu lakukanlah terhadap diriku, dan janganlah kamu memberi tangguh kepadaku.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 72, "text": "فَإِن تَوَلَّیۡتُمۡ فَمَا سَأَلۡتُكُم مِّنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَى ٱللَّهِۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِینَ ۝٧٢", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "فإن أعرضتم عن دعوتي فإنني لم أسألكم أجرًا؛ لأن ثوابي عند ربي وأجري عليه سبحانه، وحده لا شريك له، وأمرت أن أكون من المنقادين لحكمه.", "isBasmala": false, "translation_en": "\"But if you turn away, I have not asked you for any wage. My wage falls only on God, and I was commanded to be of those who submit.\"", "translation_id": "Jika kamu berpaling (dari peringatanku), aku tidak meminta upah sedikitpun dari padamu. Upahku tidak lain hanyalah dari Allah belaka, dan aku disuruh supaya aku termasuk golongan orang-orang yang berserah diri (kepada-Nya)\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 73, "text": "فَكَذَّبُوهُ فَنَجَّیۡنَـٰهُ وَمَن مَّعَهُۥ فِی ٱلۡفُلۡكِ وَجَعَلۡنَـٰهُمۡ خَلَـٰۤىِٕفَ وَأَغۡرَقۡنَا ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُنذَرِینَ ۝٧٣", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "فكذب نوحًا قومُه فيما أخبرهم به عن الله، فنجَّيناه هو ومن معه في السفينة، وجعلناهم يَخْلُفون المكذبين في الأرض، وأغرقنا الذين جحدوا حججنا، فتأمل -أيها الرسول- كيف كان عاقبة القوم الذين أنذرهم رسولهم عذاب الله وبأسه؟", "isBasmala": false, "translation_en": "But they denounced him, so We saved him and those with him in the Ark, and We made them successors, and We drowned those who rejected Our signs. So consider the fate of those who were warned.", "translation_id": "Lalu mereka mendustakan Nuh, maka Kami selamatkan dia dan orang-orang yang bersamanya di dalam bahtera, dan Kami jadikan mereka itu pemegang kekuasaan dan Kami tenggelamkan orang-orang yang mendustakan ayat-ayat Kami. Maka perhatikanlah bagaimana kesesudahan orang-orang yang diberi peringatan itu.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 74, "text": "ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِۦ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَاۤءُوهُم بِٱلۡبَیِّنَـٰتِ فَمَا كَانُوا۟ لِیُؤۡمِنُوا۟ بِمَا كَذَّبُوا۟ بِهِۦ مِن قَبۡلُۚ كَذَ ٰلِكَ نَطۡبَعُ عَلَىٰ قُلُوبِ ٱلۡمُعۡتَدِینَ ۝٧٤", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "ثم بعثنا من بعد نوح رسلا إلى أقوامهم (هودًا وصالحًا وإبراهيم ولوطًا وشعيبًا وغيرَهم) فجاء كل رسول قومه بالمعجزات الدالة على رسالته، وعلى صحة ما دعاهم إليه، فما كانوا ليصدِّقوا ويعملوا بما كذَّب به قوم نوح ومَن سبقهم من الأمم الخالية. وكما ختم الله على قلوب هؤلاء الأقوام فلم يؤمنوا، كذلك يختم على قلوب مَن شابههم ممن بعدهم من الذين تجاوزوا حدود الله، وخالفوا ما دعاهم إليه رسلهم من طاعته عقوبة لهم على معاصيهم.", "isBasmala": false, "translation_en": "Then, after him, We sent messengers to their people. They came to them with the clear proofs, but they would not believe in anything they had already rejected. Thus We set a seal on the hearts of the hostile.", "translation_id": "Kemudian sesudah Nuh, Kami utus beberapa rasul kepada kaum mereka (masing-masing), maka rasul-rasul itu datang kepada mereka dengan membawa keterangan-keterangan yang nyata, tetapi mereka tidak hendak beriman karena mereka dahulu telah (biasa) mendustakannya. Demikianlah Kami mengunci mati hati orang-orang yang melampaui batas.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 75, "text": "ثُمَّ بَعَثۡنَا مِنۢ بَعۡدِهِم مُّوسَىٰ وَهَـٰرُونَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ بِـَٔایَـٰتِنَا فَٱسۡتَكۡبَرُوا۟ وَكَانُوا۟ قَوۡمࣰا مُّجۡرِمِینَ ۝٧٥", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "ثم بعثنا مِن بعد أولئك الرسل موسى وهارون عليهما السلام إلى فرعون وأشراف قومه بالمعجزات الدالة على صدقهما، فاستكبروا عن قَبول الحق، وكانوا قومًا مشركين مجرمين مكذبين.", "isBasmala": false, "translation_en": "Then, after them, We sent Moses and Aaron with Our proofs to Pharaoh and his dignitaries. But they acted arrogantly. They were sinful people.", "translation_id": "Kemudian sesudah rasul-rasul itu, Kami utus Musa dan Harun kepada Fir'aun dan pemuka-pemuka kaumnya, dengan (membawa) tanda-tanda (mukjizat-mukjizat) Kami, maka mereka menyombongkan diri dan mereka adalah orang-orang yang berdosa.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 76, "text": "فَلَمَّا جَاۤءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوۤا۟ إِنَّ هَـٰذَا لَسِحۡرࣱ مُّبِینࣱ ۝٧٦", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "فلما أتى فرعونَ وقومَه الحقُّ الذي جاء به موسى قالوا: إن الذي جاء به موسى من الآيات إنما هو سحر ظاهر.", "isBasmala": false, "translation_en": "And when the truth came to them from Us, they said, \"This is clearly sorcery.\"", "translation_id": "Dan tatkala telah datang kepada mereka kebenaran dari sisi Kami, mereka berkata: \"Sesungguhnya ini adalah sihir yang nyata\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 77, "text": "قَالَ مُوسَىٰۤ أَتَقُولُونَ لِلۡحَقِّ لَمَّا جَاۤءَكُمۡۖ أَسِحۡرٌ هَـٰذَا وَلَا یُفۡلِحُ ٱلسَّـٰحِرُونَ ۝٧٧", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "قال لهم موسى متعجبًا مِن قولهم: أتقولون للحق لما جاءكم: إنه سحر مبين؟ انظروا وَصْفَ ما جاءكم وما اشتمل عليه تجدوه الحق. ولا يفلح الساحرون، ولا يفوزون في الدنيا ولا في الآخرة.", "isBasmala": false, "translation_en": "Moses said, \"Is this what you say of the truth when it has come to you? Is this sorcery? Sorcerers do not succeed.\"", "translation_id": "Musa berkata: \"Apakah kamu mengatakan terhadap kebenaran waktu ia datang kepadamu, sihirkah ini?\" padahal ahli-ahli sihir itu tidaklah mendapat kemenangan\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 78, "text": "قَالُوۤا۟ أَجِئۡتَنَا لِتَلۡفِتَنَا عَمَّا وَجَدۡنَا عَلَیۡهِ ءَابَاۤءَنَا وَتَكُونَ لَكُمَا ٱلۡكِبۡرِیَاۤءُ فِی ٱلۡأَرۡضِ وَمَا نَحۡنُ لَكُمَا بِمُؤۡمِنِینَ ۝٧٨", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "قال فرعون وملؤه لموسى: أجئتنا لتصرفنا عما وجدنا عليه آباءنا من عبادة غير الله، وتكون لكما أنت وهارون العظمة والسلطان في أرض \"مصر\"؟ وما نحن لكما بمقرِّين بأنكما رسولان أُرسلتما إلينا؛ لنعبد الله وحده لا شريك له.", "isBasmala": false, "translation_en": "They said, \"Did you come to us to divert us from what we found our ancestors following, and so that you become prominent in the land? We will never believe in you.\"", "translation_id": "Mereka berkata: \"Apakah kamu datang kepada kami untuk memalingkan kami dari apa yang kami dapati nenek moyang kami mengerjakannya, dan supaya kamu berdua mempunyai kekuasaan di muka bumi? Kami tidak akan mempercayai kamu berdua\".", "manzil": 3, "manzil_display": ""}], "218": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 79, "text": "وَقَالَ فِرۡعَوۡنُ ٱئۡتُونِی بِكُلِّ سَـٰحِرٍ عَلِیمࣲ ۝٧٩", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "وقال فرعون: جيئوني بكل ساحر متقن للسحر.", "isBasmala": false, "translation_en": "Pharaoh said, \"Bring me every experienced sorcerer.\"", "translation_id": "Fir'aun berkata (kepada pemuka kaumnya): \"Datangkanlah kepadaku semua ahli-ahli sihir yang pandai!\"", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 80, "text": "فَلَمَّا جَاۤءَ ٱلسَّحَرَةُ قَالَ لَهُم مُّوسَىٰۤ أَلۡقُوا۟ مَاۤ أَنتُم مُّلۡقُونَ ۝٨٠", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "فلما جاء السحرة فرعون قال لهم موسى: ألقوا على الأرض ما معكم من حبالكم وعصيِّكم.", "isBasmala": false, "translation_en": "And when the sorcerers came, Moses said to them, \"Throw whatever you have to throw.\"", "translation_id": "Maka tatkala ahli-ahli sihir itu datang, Musa berkata kepada mereka: \"Lemparkanlah apa yang hendak kamu lemparkan\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 81, "text": "فَلَمَّاۤ أَلۡقَوۡا۟ قَالَ مُوسَىٰ مَا جِئۡتُم بِهِ ٱلسِّحۡرُۖ إِنَّ ٱللَّهَ سَیُبۡطِلُهُۥۤ إِنَّ ٱللَّهَ لَا یُصۡلِحُ عَمَلَ ٱلۡمُفۡسِدِینَ ۝٨١", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "فلما ألقَوا حبالهم وعصيَّهم قال لهم موسى: إنَّ الذي جئتم به وألقيتموه هو السحر، إن الله سيُذْهب ما جئتم به وسيُبطله، إن الله لا يصلح عمل مَن سعى في أرض الله بما يكرهه، وأفسد فيها بمعصيته.", "isBasmala": false, "translation_en": "And when they threw, Moses said, \"What you produced is sorcery, and God will make it fail. God does not foster the efforts of the corrupt.\"", "translation_id": "Maka setelah mereka lemparkan, Musa berkata: \"Apa yang kamu lakukan itu, itulah yang sihir, sesungguhnya Allah akan menampakkan ketidak benarannya\" Sesungguhnya Allah tidak akan membiarkan terus berlangsungnya pekerjaan orang-yang membuat kerusakan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 82, "text": "وَیُحِقُّ ٱللَّهُ ٱلۡحَقَّ بِكَلِمَـٰتِهِۦ وَلَوۡ كَرِهَ ٱلۡمُجۡرِمُونَ ۝٨٢", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "ويثبِّت الله الحق الذي جئتكم به من عنده فيُعليه على باطلكم بكلماته وأمره، ولو كره المجرمون أصحاب المعاصي مِن آل فرعون.", "isBasmala": false, "translation_en": "\"And God upholds the truth with His words, even though the sinners detest it.\"", "translation_id": "Dan Allah akan mengokohkan yang benar dengan ketetapan-Nya, walaupun orang-orang yang berbuat dosa tidak menyukai(nya).", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 83, "text": "فَمَاۤ ءَامَنَ لِمُوسَىٰۤ إِلَّا ذُرِّیَّةࣱ مِّن قَوۡمِهِۦ عَلَىٰ خَوۡفࣲ مِّن فِرۡعَوۡنَ وَمَلَإِی۟هِمۡ أَن یَفۡتِنَهُمۡۚ وَإِنَّ فِرۡعَوۡنَ لَعَالࣲ فِی ٱلۡأَرۡضِ وَإِنَّهُۥ لَمِنَ ٱلۡمُسۡرِفِینَ ۝٨٣", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "فما آمن لموسى عليه السلام مع ما أتاهم به من الحجج والأدلة إلا ذرية من قومه من بني إسرائيل، وهم خائفون من فرعون وملئه أن يفتنوهم بالعذاب، فيصدُّوهم عن دينهم، وإن فرعون لَجبار مستكبر في الأرض، وإنه لمن المتجاوزين الحد في الكفر والفساد.", "isBasmala": false, "translation_en": "But none believed in Moses except some children of his people, for fear that Pharaoh and his chiefs would persecute them. Pharaoh was high and mighty in the land. He was a tyrant.", "translation_id": "Maka tidak ada yang beriman kepada Musa, melainkan pemuda-pemuda dari kaumnya (Musa) dalam keadaan takut bahwa Fir'aun dan pemuka-pemuka kaumnya akan menyiksa mereka. Sesungguhnya Fir'aun itu berbuat sewenang-wenang di muka bumi. Dan sesungguhnya dia termasuk orang-orang yang melampaui batas.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 84, "text": "وَقَالَ مُوسَىٰ یَـٰقَوۡمِ إِن كُنتُمۡ ءَامَنتُم بِٱللَّهِ فَعَلَیۡهِ تَوَكَّلُوۤا۟ إِن كُنتُم مُّسۡلِمِینَ ۝٨٤", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "وقال موسى: يا قومي إن صدقتم بالله -جلَّ وعلا- وامتثلتم شرعه فثقوا به، وسلِّموا لأمره، وعلى الله توكلوا إن كنتم مذعنين له بالطاعة.", "isBasmala": false, "translation_en": "Moses said, \"O my people, if you have believed in God, then put your trust in Him, if you have submitted.\"", "translation_id": "Berkata Musa: \"Hai kaumku, jika kamu beriman kepada Allah, maka bertawakkallah kepada-Nya saja, jika kamu benar-benar orang yang berserah diri\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 85, "text": "فَقَالُوا۟ عَلَى ٱللَّهِ تَوَكَّلۡنَا رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةࣰ لِّلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝٨٥", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "فقال قوم موسى له: على الله وحده لا شريك له اعتمدنا، وإليه فوَّضنا أمرنا، ربنا لا تنصرهم علينا فيكون ذلك فتنة لنا عن الدين، أو يُفتن الكفارُ بنصرهم، فيقولوا: لو كانوا على حق لما غُلبوا.", "isBasmala": false, "translation_en": "They said, \"In God we have put our trust. Our Lord, do not make us victims of the oppressive people.\"", "translation_id": "Lalu mereka berkata: \"Kepada Allahlah kami bertawakkal! Ya Tuhan kami; janganlah Engkau jadikan kami sasaran fitnah bagi kaum yang'zalim,", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 86, "text": "وَنَجِّنَا بِرَحۡمَتِكَ مِنَ ٱلۡقَوۡمِ ٱلۡكَـٰفِرِینَ ۝٨٦", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "ونجِّنا برحمتك من القوم الكافرين فرعون وملئه؛ لأنهم كانوا يأخذونهم بالأعمال الشاقة.", "isBasmala": false, "translation_en": "\"And deliver us, by Your mercy, from the disbelieving people.\"", "translation_id": "dan selamatkanlah kami dengan rahmat Engkau dari (tipu daya) orang-orang yang kafir\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 87, "text": "وَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰ وَأَخِیهِ أَن تَبَوَّءَا لِقَوۡمِكُمَا بِمِصۡرَ بُیُوتࣰا وَٱجۡعَلُوا۟ بُیُوتَكُمۡ قِبۡلَةࣰ وَأَقِیمُوا۟ ٱلصَّلَوٰةَۗ وَبَشِّرِ ٱلۡمُؤۡمِنِینَ ۝٨٧", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "وأوحينا إلى موسى وأخيه هارون أن اتخذا لقومكما بيوتًا في \"مصر\" تكون مساكن وملاجئ تعتصمون بها، واجعلوا بيوتكم أماكن تصلُّون فيها عند الخوف، وأدُّوا الصلاة المفروضة في أوقاتها. وبشِّر المؤمنين المطيعين لله بالنصر المؤزر، والثواب الجزيل منه سبحانه وتعالى.", "isBasmala": false, "translation_en": "And We inspired Moses and his brother, \"Settle your people in Egypt, and make your homes places of worship, and perform the prayer, and give good news to the believers.\"", "translation_id": "Dan Kami wahyukan kepada Musa dan saudaranya: \"Ambillah olehmu berdua beberapa buah rumah di Mesir untuk tempat tinggal bagi kaummu dan jadikanlah olehmu rumah-rumahmu itu tempat shalat dan dirikanlah olehmu sembahyang serta gembirakanlah orang-orang yang beriman\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 88, "text": "وَقَالَ مُوسَىٰ رَبَّنَاۤ إِنَّكَ ءَاتَیۡتَ فِرۡعَوۡنَ وَمَلَأَهُۥ زِینَةࣰ وَأَمۡوَ ٰلࣰا فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا رَبَّنَا لِیُضِلُّوا۟ عَن سَبِیلِكَۖ رَبَّنَا ٱطۡمِسۡ عَلَىٰۤ أَمۡوَ ٰلِهِمۡ وَٱشۡدُدۡ عَلَىٰ قُلُوبِهِمۡ فَلَا یُؤۡمِنُوا۟ حَتَّىٰ یَرَوُا۟ ٱلۡعَذَابَ ٱلۡأَلِیمَ ۝٨٨", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "وقال موسى: ربنا إنك أعطيت فرعون وأشراف قومه زينة من متاع الدنيا؛ فلم يشكروا لك، وإنما استعانوا بها على الإضلال عن سبيلك، ربنا اطمس على أموالهم، فلا ينتفعوا بها، واختم على قلوبهم حتى لا تنشرح للإيمان، فلا يؤمنوا حتى يروا العذاب الشديد الموجع.", "isBasmala": false, "translation_en": "Moses said, \"Our Lord, you have given Pharaoh and his chiefs splendor and wealth in the worldly life. Our Lord, for them to lead away from Your path. Our Lord, obliterate their wealth, and harden their hearts, they will not believe until they see the painful torment.\"", "translation_id": "Musa berkata: \"Ya Tuhan kami, sesungguhnya Engkau telah memberi kepada Fir'aun dan pemuka-pemuka kaumnya perhiasan dan harta kekayaan dalam kehidupan dunia, ya Tuhan Kami -- akibatnya mereka menyesatkan (manusia) dari jalan Engkau. Ya Tuhan kami, binasakanlah harta benda mereka, dan kunci matilah hati mereka, maka mereka tidak beriman hingga mereka melihat siksaan yang pedih\".", "manzil": 3, "manzil_display": ""}], "219": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 89, "text": "قَالَ قَدۡ أُجِیبَت دَّعۡوَتُكُمَا فَٱسۡتَقِیمَا وَلَا تَتَّبِعَاۤنِّ سَبِیلَ ٱلَّذِینَ لَا یَعۡلَمُونَ ۝٨٩", "juz": 11, "hizb": "(*½ ح 22*)", "tafsir": "قال الله تعالى لهما: قد أجيبت دعوتكما في فرعون وملئه وأموالهم -وكان موسى يدعو، وهارون يؤمِّن على دعائه، فمن هنا نسبت الدعوة إلى الاثنين- فاستقيما على دينكما، واستمرَّا على دعوتكما فرعون وقومه إلى توحيد الله وطاعته، ولا تسلكا طريق مَن لا يعلم حقيقة وعدي ووعيدي.", "isBasmala": false, "translation_en": "He said, \"Your prayer has been answered, so go straight, and do not follow the path of those who do not know.\"", "translation_id": "AlIah berfirman: \"Sesungguhnya telah diperkenankan permohonan kamu berdua, sebab itu tetaplah kamu berdua pada jalan yang lurus dan janganlah sekali-kali kamu mengikuti jalan orang-orang yang tidak mengetahui\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 90, "text": "۞ وَجَـٰوَزۡنَا بِبَنِیۤ إِسۡرَ ٰۤءِیلَ ٱلۡبَحۡرَ فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ وَجُنُودُهُۥ بَغۡیࣰا وَعَدۡوًاۖ حَتَّىٰۤ إِذَاۤ أَدۡرَكَهُ ٱلۡغَرَقُ قَالَ ءَامَنتُ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّا ٱلَّذِیۤ ءَامَنَتۡ بِهِۦ بَنُوۤا۟ إِسۡرَ ٰۤءِیلَ وَأَنَا۠ مِنَ ٱلۡمُسۡلِمِینَ ۝٩٠", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "وقطَعْنا ببني إسرائيل البحر حتى جاوزوه، فأتبعهم فرعون وجنوده ظلمًا وعدوانًا، فسلكوا البحر وراءهم، حتى إذا أحاط بفرعون الغرق قال: آمنتُ أنه لا إله إلا الذي آمنتْ به بنو إسرائيل، وأنا من الموحدين المستسلمين بالانقياد والطاعة.", "isBasmala": false, "translation_en": "And We delivered the Children of Israel across the sea. Pharaoh and his troops pursued them, defiantly and aggressively. Until, when he was about to drown, he said, \"I believe that there is no god except the One the Children of Israel believe in, and I am of those who submit.\"", "translation_id": "Dan Kami memungkinkan Bani Israil melintasi laut, lalu mereka diikuti oleh Fir'aun dan bala tentaranya, karena hendak menganiaya dan menindas (mereka); hingga bila Fir'aun itu telah hampir tenggelam berkatalah dia: \"Saya percaya bahwa tidak ada Tuhan melainkan Tuhan yang dipercayai oleh Bani Israil, dan saya termasuk orang-orang yang berserah diri (kepada Allah)\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 91, "text": "ءَاۤلۡـَٔـٰنَ وَقَدۡ عَصَیۡتَ قَبۡلُ وَكُنتَ مِنَ ٱلۡمُفۡسِدِینَ ۝٩١", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "آلآن يا فرعون، وقد نزل بك الموت تقرُّ لله بالعبودية، وقد عصيته قبل نزول عذابه بك، وكنت من المفسدين الصادين عن سبيله!! فلا تنفعك التوبة ساعة الاحتضار ومشاهدة الموت والعذاب.", "isBasmala": false, "translation_en": "Now? When you have rebelled before, and been of the mischief-makers?", "translation_id": "Apakah sekarang (baru kamu percaya), padahal sesungguhnya kamu telah durhaka sejak dahulu, dan kamu termasuk orang-orang yang berbuat kerusakan.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 92, "text": "فَٱلۡیَوۡمَ نُنَجِّیكَ بِبَدَنِكَ لِتَكُونَ لِمَنۡ خَلۡفَكَ ءَایَةࣰۚ وَإِنَّ كَثِیرࣰا مِّنَ ٱلنَّاسِ عَنۡ ءَایَـٰتِنَا لَغَـٰفِلُونَ ۝٩٢", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "فاليوم نجعلك على مرتفع من الأرض ببدنك، ينظر إليك من كذَّب بهلاكك؛ لتكون لمن بعدك من الناس عبرة يعتبرون بك. فإن كثيرًا من الناس عن حججنا وأدلتنا لَغافلون، لا يتفكرون فيها ولا يعتبرون.", "isBasmala": false, "translation_en": "Today We will preserve your body, so that you become a sign for those after you. But most people are heedless of Our signs.", "translation_id": "Maka pada hari ini Kami selamatkan badanmu supaya kamu dapat menjadi pelajaran bagi orang-orang yang datang sesudahmu dan sesungguhnya kebanyakan dari manusia lengah dari tanda-tanda kekuasaan Kami.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 93, "text": "وَلَقَدۡ بَوَّأۡنَا بَنِیۤ إِسۡرَ ٰۤءِیلَ مُبَوَّأَ صِدۡقࣲ وَرَزَقۡنَـٰهُم مِّنَ ٱلطَّیِّبَـٰتِ فَمَا ٱخۡتَلَفُوا۟ حَتَّىٰ جَاۤءَهُمُ ٱلۡعِلۡمُۚ إِنَّ رَبَّكَ یَقۡضِی بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ ۝٩٣", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "ولقد أنزلنا بني إسرائيل منزلا صالحًا مختارًا في بلاد \"الشام\" و\"مصر\"، ورزقناهم الرزق الحلال الطيب من خيرات الأرض المباركة، فما اختلفوا في أمر دينهم إلا مِن بعد ما جاءهم العلم الموجب لاجتماعهم وائتلافهم، ومن ذلك ما اشتملت عليه التوراة من الإخبار بنبوة محمد صلى الله عليه وسلم. إن ربك -أيها الرسول- يقضي بينهم يوم القيامة، ويَفْصِل فيما كانوا يختلفون فيه من أمرك، فيدخل المكذبين النار والمؤمنين الجنة.", "isBasmala": false, "translation_en": "And We settled the Children of Israel in a position of honor, and provided them with good things. They did not differ until knowledge came to them. Your Lord will judge between them on the Day of Resurrection regarding their differences.", "translation_id": "Dan sesungguhnya Kami telah menempatkan Bani Israil di ternpat kediaman yang bagus dan Kami beri mereka rezeki dari yang baik-baik. Maka mereka tidak berselisih, kecuali setelah datang kepada mereka pengetahuan (yang tersebut dalam Taurat). Sesungguhnya Tuhan kamu akan memutuskan antara mereka di hari kiamat tentang apa yang mereka perselisihkan itu.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 94, "text": "فَإِن كُنتَ فِی شَكࣲّ مِّمَّاۤ أَنزَلۡنَاۤ إِلَیۡكَ فَسۡـَٔلِ ٱلَّذِینَ یَقۡرَءُونَ ٱلۡكِتَـٰبَ مِن قَبۡلِكَۚ لَقَدۡ جَاۤءَكَ ٱلۡحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِینَ ۝٩٤", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "فإن كنت -أيها الرسول- في ريب من حقيقة ما أخبرناك به فاسأل الذين يقرؤون الكتاب من قبلك من أهل التوراة والإنجيل، فإن ذلك ثابت في كتبهم، لقد جاءك الحق اليقين من ربك بأنك رسول الله، وأن هؤلاء اليهود والنصارى يعلمون صحة ذلك، ويجدون صفتك في كتبهم، ولكنهم ينكرون ذلك مع علمهم به، فلا تكوننَّ من الشاكِّين في صحة ذلك وحقيقته.", "isBasmala": false, "translation_en": "If you are in doubt about what We revealed to you, ask those who read the Scripture before you. The truth has come to you from your Lord, so do not be of those who doubt.", "translation_id": "Maka jika kamu (Muhammad) berada dalam keragu-raguan tentang apa yang Kami turunkan kepadamu, maka tanyakanlah kepada orang-orang yang membaca kitab sebelum kamu. Sesungguhnya telah datang kebenaran kepadamu dari Tuhanmu, sebab itu janganlah sekali-kali kamu temasuk orang-orang yang ragu-ragu.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 95, "text": "وَلَا تَكُونَنَّ مِنَ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِ ٱللَّهِ فَتَكُونَ مِنَ ٱلۡخَـٰسِرِینَ ۝٩٥", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "ولا تكونن -أيها الرسول- من الذين كذَّبوا بحجج الله وأدلته فتكون من الخاسرين الذين سخِطَ الله عليهم ونالوا عقابه.", "isBasmala": false, "translation_en": "And do not be of those who deny God's revelations, lest you become one of the losers.", "translation_id": "Dan sekali-kali janganlah kamu termasuk orang-orang yang mendustakan ayat-ayat Allah yang menyebabkan kamu termasuk orang-orang yang rugi.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 96, "text": "إِنَّ ٱلَّذِینَ حَقَّتۡ عَلَیۡهِمۡ كَلِمَتُ رَبِّكَ لَا یُؤۡمِنُونَ ۝٩٦", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "إن الذين حقَّت عليهم كلمة ربك -أيها الرسول- بطردهم من رحمته وعذابه لهم، لا يؤمنون بحجج الله، ولا يقرُّون بوحدانيته، ولا يعملون بشرعه.", "isBasmala": false, "translation_en": "Those against whom your Lord's Word is justified will not believe.", "translation_id": "Sesungguhnya orang-orang yang telah pasti terhadap mereka kalimat Tuhanmu, tidaklah akan beriman,", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 97, "text": "وَلَوۡ جَاۤءَتۡهُمۡ كُلُّ ءَایَةٍ حَتَّىٰ یَرَوُا۟ ٱلۡعَذَابَ ٱلۡأَلِیمَ ۝٩٧", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "ولو جاءتهم كل موعظة وعبرة حتى يعاينوا العذاب الموجع، فحينئذ يؤمنون، ولا ينفعهم إيمانهم.", "isBasmala": false, "translation_en": "Even if every sign comes to them-until they see the painful punishment.", "translation_id": "meskipun datang kepada mereka segala macam keterangan, hingga mereka menyaksikan azab yang pedih.", "manzil": 3, "manzil_display": ""}], "220": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 98, "text": "فَلَوۡلَا كَانَتۡ قَرۡیَةٌ ءَامَنَتۡ فَنَفَعَهَاۤ إِیمَـٰنُهَاۤ إِلَّا قَوۡمَ یُونُسَ لَمَّاۤ ءَامَنُوا۟ كَشَفۡنَا عَنۡهُمۡ عَذَابَ ٱلۡخِزۡیِ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَمَتَّعۡنَـٰهُمۡ إِلَىٰ حِینࣲ ۝٩٨", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "لم ينفع الإيمان أهل قرية آمنوا عند معاينة العذاب إلا أهل قرية يونس بن مَتَّى، فإنهم لـمَّا أيقنوا أن العذاب نازل بهم تابوا إلى الله تعالى توبة نصوحا، فلمَّا تبيَّن منهم الصدق في توبتهم كشف الله عنهم عذاب الخزي بعد أن اقترب منهم، وتركهم في الدنيا يستمتعون إلى وقت إنهاء آجالهم.", "isBasmala": false, "translation_en": "If only there was one town that believed and benefited by its belief. Except for the people of Jonah. When they believed, We removed from them the suffering of disgrace in the worldly life, and We gave them comfort for a while.", "translation_id": "Dan mengapa tidak ada (penduduk) suatu kota yang beriman, lalu imannya itu bermanfaat kepadanya selain kaum Yunus? Tatkala mereka (kaum Yunus itu), beriman, Kami hilangkan dari mereka azab yang menghinakan dalam kehidupan dunia, dan Kami beri kesenangan kepada mereka sampai kepada waktu yang tertentu.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 99, "text": "وَلَوۡ شَاۤءَ رَبُّكَ لَـَٔامَنَ مَن فِی ٱلۡأَرۡضِ كُلُّهُمۡ جَمِیعًاۚ أَفَأَنتَ تُكۡرِهُ ٱلنَّاسَ حَتَّىٰ یَكُونُوا۟ مُؤۡمِنِینَ ۝٩٩", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "ولو شاء ربك -أيها الرسول- الإيمان لأهل الأرض كلهم لآمنوا جميعًا بما جئتهم به، ولكن له حكمة في ذلك؛ فإنه يهدي من يشاء ويضل من يشاء وَفْق حكمته، وليس في استطاعتك أن تُكْره الناس على الإيمان.", "isBasmala": false, "translation_en": "Had your Lord willed, everyone on earth would have believed. Will you compel people to become believers?", "translation_id": "Dan jikalau Tuhanmu menghendaki, tentulah beriman semua orang yang di muka bumi seluruhnya. Maka apakah kamu (hendak) memaksa manusia supaya mereka menjadi orang-orang yang beriman semuanya?", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 100, "text": "وَمَا كَانَ لِنَفۡسٍ أَن تُؤۡمِنَ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَیَجۡعَلُ ٱلرِّجۡسَ عَلَى ٱلَّذِینَ لَا یَعۡقِلُونَ ۝١٠٠", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "وما كان لنفس أن تؤمن بالله إلا بإذنه وتوفيقه، فلا تُجهد نفسك في ذلك، فإن أمرهم إلى الله. ويجعل الله العذاب والخزي على الذين لا يعقلون أمره ونهيه.", "isBasmala": false, "translation_en": "No soul can believe except by God's leave; and He lays disgrace upon those who refuse to understand.", "translation_id": "Dan tidak ada seorangpun akan beriman kecuali dengan izin Allah; dan Allah menimpakan kemurkaan kepada orang-orang yang tidak mempergunakan akalnya.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 101, "text": "قُلِ ٱنظُرُوا۟ مَاذَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَمَا تُغۡنِی ٱلۡـَٔایَـٰتُ وَٱلنُّذُرُ عَن قَوۡمࣲ لَّا یُؤۡمِنُونَ ۝١٠١", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "قل -أيها الرسول- لقومك: تفكروا واعتبروا بما في السموات والأرض من آيات الله البينات، ولكن الآيات والعبر والرسل المنذرة عباد الله عقابه، لا تنفع قومًا لا يؤمنون بشيء من ذلك؛ لإعراضهم وعنادهم.", "isBasmala": false, "translation_en": "Say, \"Look at what is in the heavens and the earth.\" But signs and warnings are of no avail for people who do not believe.", "translation_id": "Katakanlah: \"Perhatikanlah apa yaag ada di langit dan di bumi. Tidaklah bermanfaat tanda kekuasaan Allah dan rasul-rasul yang memberi peringatan bagi orang-orang yang tidak beriman\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 102, "text": "فَهَلۡ یَنتَظِرُونَ إِلَّا مِثۡلَ أَیَّامِ ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلِهِمۡۚ قُلۡ فَٱنتَظِرُوۤا۟ إِنِّی مَعَكُم مِّنَ ٱلۡمُنتَظِرِینَ ۝١٠٢", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "فهل ينتظر هؤلاء إلا يومًا يعاينون فيه عذاب الله مثل أيام أسلافهم المكذبين الذين مَضَوا قبلهم؟ قل لهم -أيها الرسول-: فانتظروا عقاب الله إني معكم من المنتظرين عقابكم.", "isBasmala": false, "translation_en": "Do they expect anything but the likes of the days of those who passed away before them? Say, \"Then wait, I will be waiting with you.\"", "translation_id": "Mereka tidak menunggu-nunggu kecuali (kejadian-kejadian) yang sama dengan kejadian-kejadian (yang menimpa) orang-orang yang telah terdahulu sebelum mereka. Katakanlah: \"Maka tunggulah, sesungguhnya akupun termasuk orang-orang yang menunggu bersama kamu\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 103, "text": "ثُمَّ نُنَجِّی رُسُلَنَا وَٱلَّذِینَ ءَامَنُوا۟ۚ كَذَ ٰلِكَ حَقًّا عَلَیۡنَا نُنجِ ٱلۡمُؤۡمِنِینَ ۝١٠٣", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "ثم ننجِّي رسلنا والذين آمنوا معهم، وكما نجينا أولئك ننجِّيك -أيها الرسول- ومن آمن بك تفضلا منَّا ورحمة.", "isBasmala": false, "translation_en": "Then We save Our messengers and those who believe. It is binding on Us to save the believers.", "translation_id": "Kemudian Kami selamatkan rasul-rasul Kami dan orang-orang yang beriman, demikianlah menjadi kewajiban atas Kami menyelamatkan orang-orang yang beriman.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 104, "text": "قُلۡ یَـٰۤأَیُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِی شَكࣲّ مِّن دِینِی فَلَاۤ أَعۡبُدُ ٱلَّذِینَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَلَـٰكِنۡ أَعۡبُدُ ٱللَّهَ ٱلَّذِی یَتَوَفَّىٰكُمۡۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ ۝١٠٤", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "قل -أيها الرسول- لهؤلاء الناس: إن كنتم في شك من صحة ديني الذي دعوتكم إليه، وهو الإسلام ومن ثباتي واستقامتي عليه، وترجون تحويلي عنه، فإني لا أعبد في حال من الأحوال أحدًا من الذين تعبدونهم مما اتخذتم من الأصنام والأوثان، ولكن أعبد الله وحده الذي يميتكم ويقبض أرواحكم، وأُمِرْت أن أكون من المصدِّقين به العاملين بشرعه.", "isBasmala": false, "translation_en": "Say, \"O people, if you are in doubt about my religion-I do not serve those you serve apart from God. But I serve God, the one who will terminate your lives. And I was commanded to be of the believers.\"", "translation_id": "Katakanlah: \"Hai manusia, jika kamu masih dalam keragu-raguan tentang agamaku, maka (ketahuilah) aku tidak menyembah yang kamu sembah selain Allah, tetapi aku menyembah Allah yang akan mematikan kamu dan aku telah diperintah supaya termasuk orang-orang yang beriman\",", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 105, "text": "وَأَنۡ أَقِمۡ وَجۡهَكَ لِلدِّینِ حَنِیفࣰا وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِینَ ۝١٠٥", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "وأن أقم -أيها الرسول- نفسك على دين الإسلام مستقيمًا عليه غير مائل عنه إلى يهودية ولا نصرانية ولا عبادة غيره، ولا تكونن ممن يشرك في عبادة ربه الآلهة والأنداد، فتكون من الهالكين. وهذا وإن كان خطابًا للرسول صلى الله عليه وسلَّم فإنه موجَّه لعموم الأمة.", "isBasmala": false, "translation_en": "And dedicate yourself to the true religion-a monotheist-and never be of the polytheists.", "translation_id": "dan (aku telah diperintah): \"Hadapkanlah mukamu kepada agama dengan tulus dan ikhlas dan janganlah kamu termasuk orang-orang yang musyrik.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 106, "text": "وَلَا تَدۡعُ مِن دُونِ ٱللَّهِ مَا لَا یَنفَعُكَ وَلَا یَضُرُّكَۖ فَإِن فَعَلۡتَ فَإِنَّكَ إِذࣰا مِّنَ ٱلظَّـٰلِمِینَ ۝١٠٦", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "ولا تَدْعُ -أيها الرسول- من دون الله شيئًا من الأوثان والأصنام؛ لأنها لا تنفع ولا تضرُّ، فإن فعَلْت ذلك ودعوتها من دون الله فإنك إذًا من المشركين بالله، الظالمين لأنفسهم بالشرك والمعصية. وهذا وإن كان خطابًا للرسول صلى الله عليه وسلَّم فإنه موجَّه لعموم الأمة.", "isBasmala": false, "translation_en": "And do not call, apart from God, on what neither benefits you nor harms you. If you do, you are then one of the wrongdoers.", "translation_id": "Dan janganlah kamu menyembah apa-apa yang tidak memberi manfaat dan tidak (pula) memberi mudharat kepadamu selain Allah; sebab jika kamu berbuat (yang demikian), itu, maka sesungguhnya kamu kalau begitu termasuk orang-orang yang zalim\".", "manzil": 3, "manzil_display": ""}], "221": [{"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 107, "text": "وَإِن یَمۡسَسۡكَ ٱللَّهُ بِضُرࣲّ فَلَا كَاشِفَ لَهُۥۤ إِلَّا هُوَۖ وَإِن یُرِدۡكَ بِخَیۡرࣲ فَلَا رَاۤدَّ لِفَضۡلِهِۦۚ یُصِیبُ بِهِۦ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۚ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ ۝١٠٧", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "وإن يصبك الله -أيها الرسول- بشدة أو بلاء فلا كاشف لذلك إلا هو جلَّ وعلا وإن يُرِدْك برخاء أو نعمة لا يمنعه عنك أحد، يصيب الله عز وجل بالسراء والضراء من يشاء من عباده، وهو الغفور لذنوب مَن تاب، الرحيم بمن آمن به وأطاعه.", "isBasmala": false, "translation_en": "If God afflicts you with harm, none can remove it except He. And if He wants good for you, none can repel His grace. He makes it reach whomever He wills of His servants. He is the Forgiver, the Merciful.", "translation_id": "Jika Allah menimpakan sesuatu kemudharatan kepadamu, maka tidak ada yang dapat menghilangkannya kecuali Dia. Dan jika Allah menghendaki kebaikan bagi kamu, maka tak ada yang dapat menolak kurnia-Nya. Dia memberikan kebaikan itu kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya dan Dialah Yang Maha Pengampun lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 108, "text": "قُلۡ یَـٰۤأَیُّهَا ٱلنَّاسُ قَدۡ جَاۤءَكُمُ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا یَهۡتَدِی لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا یَضِلُّ عَلَیۡهَاۖ وَمَاۤ أَنَا۠ عَلَیۡكُم بِوَكِیلࣲ ۝١٠٨", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "قل -أيها الرسول- لهؤلاء الناس: قد جاءكم رسول الله بالقرآن الذي فيه بيان هدايتكم، فمن اهتدى بهدي الله فإنما ثمرة عمله راجعة إليه، ومن انحرف عن الحق وأصرَّ على الضلال فإنما ضلاله وضرره على نفسه، وما أنا موكَّل بكم حتى تكونوا مؤمنين، إنما أنا رسول مبلِّغ أبلِّغكم ما أُرْسِلْت به.", "isBasmala": false, "translation_en": "Say, \"O people, the truth has come to you from your Lord. Whoever accepts guidance is guided for his own soul; and whoever strays only strays to its detriment. I am not a guardian over you.\"", "translation_id": "Katakanlah: \"Hai manusia, sesungguhnya teIah datang kepadamu kebenaran (Al Quran) dari Tuhanmu, sebab itu barangsiapa yang mendapat petunjuk maka sesungguhnya (petunjuk itu) untuk kebaikan dirinya sendiri. Dan barangsiapa yang sesat, maka sesungguhnya kesesatannya itu mencelakakan dirinya sendiri. Dan aku bukanlah seorang penjaga terhadap dirimu\".", "manzil": 3, "manzil_display": ""}, {"sura": 10, "sura_name": "يونس", "revelation": "Makkiyah", "aya": 109, "text": "وَٱتَّبِعۡ مَا یُوحَىٰۤ إِلَیۡكَ وَٱصۡبِرۡ حَتَّىٰ یَحۡكُمَ ٱللَّهُۚ وَهُوَ خَیۡرُ ٱلۡحَـٰكِمِینَ ۝١٠٩", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "واتبع -أيها الرسول- وحي الله الذي يوحيه إليك فاعمل به، واصبر على طاعة الله تعالى، وعن معصيته، وعلى أذى من آذاك في تبليغ رسالته، حتى يقضي الله فيهم وفيك أمره، وهو -عزَّ وجل- خير الحاكمين؛ فإن حكمه مشتمل على العدل التام.", "isBasmala": false, "translation_en": "And follow what is revealed to you, and be patient until God issues His judgment, for He is the Best of judges.", "translation_id": "Dan ikutilah apa yang diwahyukan kepadamu, dan bersabarlah hingga Allah memberi keputusan dan Dia adalah Hakim yang sebaik-baiknya.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 12, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 1, "text": "الۤرۚ كِتَـٰبٌ أُحۡكِمَتۡ ءَایَـٰتُهُۥ ثُمَّ فُصِّلَتۡ مِن لَّدُنۡ حَكِیمٍ خَبِیرٍ ۝١", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Ra. A Scripture whose Verses were perfected, then elaborated, from One who is Wise and Informed.", "translation_id": "Alif laam raa, (inilah) suatu kitab yang ayat-ayatnya disusun dengan rapi serta dijelaskan secara terperinci, yang diturunkan dari sisi (Allah) Yang Maha Bijaksana lagi Maha Tahu,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 2, "text": "أَلَّا تَعۡبُدُوۤا۟ إِلَّا ٱللَّهَۚ إِنَّنِی لَكُم مِّنۡهُ نَذِیرࣱ وَبَشِیرࣱ ۝٢", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "وإنزال القرآن وبيان أحكامه وتفصيلها وإحكامها؛ لأجل أن لا تعبدوا إلا الله وحده لا شريك له. إنني لكم -أيها الناس- من عند الله نذير ينذركم عقابه، وبشير يبشِّركم بثوابه.", "isBasmala": false, "translation_en": "That you shall worship none but God. \"I am a warner to you from Him, and a bearer of good news.\"", "translation_id": "agar kamu tidak menyembah selain Allah. Sesungguhnya aku (Muhammad) adalah pemberi peringatan dan pembawa khabar gembira kepadamu daripada-Nya,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 3, "text": "وَأَنِ ٱسۡتَغۡفِرُوا۟ رَبَّكُمۡ ثُمَّ تُوبُوۤا۟ إِلَیۡهِ یُمَتِّعۡكُم مَّتَـٰعًا حَسَنًا إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى وَیُؤۡتِ كُلَّ ذِی فَضۡلࣲ فَضۡلَهُۥۖ وَإِن تَوَلَّوۡا۟ فَإِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمࣲ كَبِیرٍ ۝٣", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "واسألوه أن يغفر لكم ذنوبكم، ثم ارجعوا إليه نادمين يمتعْكم في دنياكم متاعًا حسنًا بالحياة الطيبة فيها، إلى أن يحين أجلكم، ويُعطِ كل ذي فضل من علم وعمل جزاء فضله كاملا لا نقص فيه، وإن تعرضوا عمَّا أدعوكم إليه فإني أخشى عليكم عذاب يوم شديد، وهو يوم القيامة. وهذا تهديد شديد لمن تولَّى عن أوامر الله تعالى وكذَّب رسله.", "isBasmala": false, "translation_en": "\"And ask your Lord for forgiveness, and repent to Him. He will provide you with good sustenance until a stated term, and will bestow His grace on every possessor of virtue. But if you turn away, then I fear for you the punishment of a grievous Day.\"", "translation_id": "dan hendaklah kamu meminta ampun kepada Tuhanmu dan bertaubat kepada-Nya. (Jika kamu mengerjakan yang demikian), niscaya Dia akan memberi kenikmatan yang baik (terus menerus) kepadamu sampai kepada waktu yang telah ditentukan dan Dia akan memberikan kepada tiap-tiap orang yang mempunyai keutamaan (balasan) keutamaannya. Jika kamu berpaling, maka sesungguhnya aku takut kamu akan ditimpa siksa hari kiamat.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 4, "text": "إِلَى ٱللَّهِ مَرۡجِعُكُمۡۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝٤", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "إلى الله رجوعكم بعد موتكم جميعًا فاحذروا عقابه، وهو سبحانه قادر على بعثكم وحشركم وجزائكم.", "isBasmala": false, "translation_en": "\"To God is your return, and He is Capable of all things.\"", "translation_id": "Kepada Allah-lah kembalimu, dan Dia Maha Kuasa atas segala sesuatu.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 5, "text": "أَلَاۤ إِنَّهُمۡ یَثۡنُونَ صُدُورَهُمۡ لِیَسۡتَخۡفُوا۟ مِنۡهُۚ أَلَا حِینَ یَسۡتَغۡشُونَ ثِیَابَهُمۡ یَعۡلَمُ مَا یُسِرُّونَ وَمَا یُعۡلِنُونَۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝٥", "juz": 11, "hizb": "(*¾ ح 22*)", "tafsir": "إن هؤلاء المشركين يضمرون في صدورهم الكفر؛ ظنًا منهم أنه يخفى على الله ما تضمره نفوسهم، ألا يعلمون حين يغطُّون أجسادهم بثيابهم أن الله لا يخفى عليه سِرُّهم وعلانيتهم؟ إنه عليم بكل ما تُكِنُّه صدورهم من النيات والضمائر والسرائر.", "isBasmala": false, "translation_en": "They wrap their chests to hide from Him. But even as they cover themselves with their clothes, He knows what they conceal and what they reveal. He knows what lies within the hearts.", "translation_id": "Ingatlah, sesungguhnya (orang munafik itu) memalingkan dada mereka untuk menyembunyikan diri daripadanya (Muhammad). Ingatlah, di waktu mereka menyelimuti dirinya dengan kain, Allah mengetahui apa yang mereka sembunyikan dan apa yang mereka lahirkan, sesungguhnya Allah Maha Mengetahui segala isi hati.", "manzil": 3, "manzil_display": ""}], "222": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 6, "text": "۞ وَمَا مِن دَاۤبَّةࣲ فِی ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَیَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلࣱّ فِی كِتَـٰبࣲ مُّبِینࣲ ۝٦", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "لقد تكفَّل الله برزق جميع ما دبَّ على وجه الأرض، تفضلا منه، ويعلم مكان استقراره في حياته وبعد موته، ويعلم الموضع الذي يموت فيه، كل ذلك مكتوب في كتاب عند الله مبين عن جميع ذلك.", "isBasmala": false, "translation_en": "There is no moving creature on earth but its sustenance depends on God. And He knows where it lives and where it rests. Everything is in a Clear Book.", "translation_id": "Dan tidak ada suatu binatang melata pun di bumi melainkan Allah-lah yang memberi rezekinya, dan Dia mengetahui tempat berdiam binatang itu dan tempat penyimpanannya. Semuanya tertulis dalam Kitab yang nyata (Lauh mahfuzh).", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 7, "text": "وَهُوَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ فِی سِتَّةِ أَیَّامࣲ وَكَانَ عَرۡشُهُۥ عَلَى ٱلۡمَاۤءِ لِیَبۡلُوَكُمۡ أَیُّكُمۡ أَحۡسَنُ عَمَلࣰاۗ وَلَىِٕن قُلۡتَ إِنَّكُم مَّبۡعُوثُونَ مِنۢ بَعۡدِ ٱلۡمَوۡتِ لَیَقُولَنَّ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینࣱ ۝٧", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "وهو الذي خلق السماوات والأرض وما فيهن في ستة أيام، وكان عرشه على الماء قبل ذلك؛ ليختبركم أيكم أحسن له طاعةً وعملا وهو ما كان خالصًا لله موافقًا لما كان عليه رسول الله صلى الله عليه وسلم. ولئن قلت -أيها الرسول- لهؤلاء المشركين من قومك: إنكم مبعوثون أحياءً بعد موتكم، لسارعوا إلى التكذيب وقالوا: ما هذا القرآن الذي تتلوه علينا إلا سحر بيِّن.", "isBasmala": false, "translation_en": "It is He who created the heavens and the earth in six days-and His Throne was upon the waters-in order to test you-which of you is best in conduct. And if you were to say, \"You will be resurrected after death,\" those who disbelieve would say, \"This is nothing but plain witchcraft.\"", "translation_id": "Dan Dialah yang menciptakan langit dan bumi dalam enam masa, dan adalah singgasana-Nya (sebelum itu) di atas air, agar Dia menguji siapakah di antara kamu yang lebih baik amalnya, dan jika kamu berkata (kepada penduduk Mekah): \"Sesungguhnya kamu akan dibangkitkan sesudah mati\", niscaya orang-orang yang kafir itu akan berkata: \"Ini tidak lain hanyalah sihir yang nyata\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 8, "text": "وَلَىِٕنۡ أَخَّرۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِلَىٰۤ أُمَّةࣲ مَّعۡدُودَةࣲ لَّیَقُولُنَّ مَا یَحۡبِسُهُۥۤۗ أَلَا یَوۡمَ یَأۡتِیهِمۡ لَیۡسَ مَصۡرُوفًا عَنۡهُمۡ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٨", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "ولئن أخَّرنا عن هؤلاء المشركين العذاب إلى أجل معلوم فاستبطؤوه، ليقولُنَّ استهزاء وتكذيبًا: أي شيء يمنع هذا العذاب من الوقوع إن كان حقًا؟ ألا يوم يأتيهم ذلك العذاب لا يستطيع أن يصرفه عنهم صارف، ولا يدفعه دافع، وأحاط بهم من كل جانب عذاب ما كانوا يستهزئون به قبل وقوعه بهم.", "isBasmala": false, "translation_en": "And if We postponed their punishment until a stated time, they would say, \"What holds it back?\" On the Day when it reaches them, it will not be averted from them, and what they used to ridicule will besiege them.", "translation_id": "Dan sesungguhnya jika Kami undurkan azab dari mereka sampai kepada suatu waktu yang ditentukan. niscaya mereka akan berkata: \"Apakah yang menghalanginya?\" lngatlah, diwaktu azab itu datang kepada mereka tidaklah dapat dipalingkan dari mereka dan mereka diliputi oleh azab yang dahulunya mereka selalu memperolok-olokkannya.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 9, "text": "وَلَىِٕنۡ أَذَقۡنَا ٱلۡإِنسَـٰنَ مِنَّا رَحۡمَةࣰ ثُمَّ نَزَعۡنَـٰهَا مِنۡهُ إِنَّهُۥ لَیَـُٔوسࣱ كَفُورࣱ ۝٩", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "ولئن أعطينا الإنسان مِنَّا نعمة من صحة وأمن وغيرهما، ثم سلبناها منه، إنه لَشديد اليأس من رحمة الله، جَحود بالنعم التي أنعم الله بها عليه.", "isBasmala": false, "translation_en": "If We give the human being a taste of mercy from Us, and then withdraw it from him, he becomes despairing and ungrateful.", "translation_id": "Dan jika Kami rasakan kepada manusia suatu rahmat (nikmat) dari Kami, kemudian rahmat itu Kami cabut daripadanya, pastilah dia menjadi putus asa lagi tidak berterima kasih.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 10, "text": "وَلَىِٕنۡ أَذَقۡنَـٰهُ نَعۡمَاۤءَ بَعۡدَ ضَرَّاۤءَ مَسَّتۡهُ لَیَقُولَنَّ ذَهَبَ ٱلسَّیِّـَٔاتُ عَنِّیۤۚ إِنَّهُۥ لَفَرِحࣱ فَخُورٌ ۝١٠", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "ولئن بسطنا للإنسان في دنياه ووسَّعنا عليه في رزقه بعد ضيق من العيش، ليقولَنَّ عند ذلك: ذهب الضيق عني وزالت الشدائد، إنه لبَطِر بالنعم، مبالغ في الفخر والتعالي على الناس.", "isBasmala": false, "translation_en": "And if We give him a taste of prosperity, after some adversity has afflicted him, he will say, \"Troubles have gone away from me.\" He becomes excited and proud.", "translation_id": "Dan jika Kami rasakan kepadanya kebahagiaan sesudah bencana yang menimpanya, niscaya dia akan berkata: \"Telah hilang bencana-bencana itu daripadaku\"; sesungguhnya dia sangat gembira lagi bangga,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 11, "text": "إِلَّا ٱلَّذِینَ صَبَرُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰۤىِٕكَ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرࣱ ۝١١", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "لكن الذين صبروا على ما أصابهم من الضراء إيمانًا بالله واحتسابًا للأجر عنده، وعملوا الصالحات شكرا لله على نعمه، هؤلاء لهم مغفرة لذنوبهم وأجر كبير في الآخرة.", "isBasmala": false, "translation_en": "Except those who are patient and do good deeds-these will have forgiveness and a great reward.", "translation_id": "kecuali orang-orang yang sabar (terhadap bencana), dan mengerjakan amal-amal saleh; mereka itu beroleh ampunan dan pahala yang besar.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 12, "text": "فَلَعَلَّكَ تَارِكُۢ بَعۡضَ مَا یُوحَىٰۤ إِلَیۡكَ وَضَاۤىِٕقُۢ بِهِۦ صَدۡرُكَ أَن یَقُولُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ كَنزٌ أَوۡ جَاۤءَ مَعَهُۥ مَلَكٌۚ إِنَّمَاۤ أَنتَ نَذِیرࣱۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ وَكِیلٌ ۝١٢", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "فلعلك -أيها الرسول لعظم ما تراه منهم من الكفر والتكذيب- تارك بعض ما يوحى إليك مما أنزله الله عليك وأمرك بتبليغه، وضائق به صدرك؛ خشية أن يطلبوا منك بعض المطالب على وجه التعنت، كأن يقولوا: لولا أُنزل عليه مال كثير، أو جاء معه ملك يصدقه في رسالته، فبلغهم ما أوحيته إليك؛ فإنه ليس عليك إلا الإنذار بما أُوحي إليك. والله على كل شيء حفيظ يدَبِّر جميع شؤون خلقه.", "isBasmala": false, "translation_en": "Perhaps you wish to disregard some of what is revealed to you, and you may be stressed because of it, since they say, \"If only a treasure was sent down to him, or an angel came with him.\" You are only a warner, and God is Responsible for all things.", "translation_id": "Maka boleh jadi kamu hendak meninggalkan sebahagian dari apa yang diwahyukan kepadamu dan sempit karenanya dadamu, karena khawatir bahwa mereka akan mengatakan: \"Mengapa tidak diturunkan kepadanya perbendaharaan (kekayaan) atau datang bersama-sama dengan dia seorang malaikat?\" Sesungguhnya kamu hanyalah seorang pemberi peringatan dan Allah Pemelihara segala sesuatu.", "manzil": 3, "manzil_display": ""}], "223": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 13, "text": "أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُوا۟ بِعَشۡرِ سُوَرࣲ مِّثۡلِهِۦ مُفۡتَرَیَـٰتࣲ وَٱدۡعُوا۟ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَـٰدِقِینَ ۝١٣", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "بل أيقول هؤلاء المشركون من أهل \"مكة\": إن محمدًا قد افترى هذا القرآن؟ قل لهم: إن كان الأمر كما تزعمون فأتوا بعشر سور مثله مفتريات، وادعوا من استطعتم من جميع خلق الله ليساعدوكم على الإتيان بهذه السور العشر، إن كنتم صادقين في دعواكم.", "isBasmala": false, "translation_en": "Or do they say, \"He invented it?\" Say, \"Then produce ten chapters like it, invented, and call upon whomever you can, besides God, if you are truthful.\"", "translation_id": "Bahkan mereka mengatakan: \"Muhammad telah membuat-buat Al Quran itu\", Katakanlah: \"(Kalau demikian), maka datangkanlah sepuluh surat-surat yang dibuat-buat yang menyamainya, dan panggillah orang-orang yang kamu sanggup (memanggilnya) selain Allah, jika kamu memang orang-orang yang benar\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 14, "text": "فَإِلَّمۡ یَسۡتَجِیبُوا۟ لَكُمۡ فَٱعۡلَمُوۤا۟ أَنَّمَاۤ أُنزِلَ بِعِلۡمِ ٱللَّهِ وَأَن لَّاۤ إِلَـٰهَ إِلَّا هُوَۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ ۝١٤", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "فإن لم يستجب هؤلاء المشركون لكم -أيها الرسول ومَن آمن معك- لما تدعونهم إليه؛ لِعَجْز الجميع عن ذلك، فاعلموا أن هذا القرآن إنما أنزله الله على رسوله بعلمه وليس من قول البشر، واعلموا أن لا إله يُعبد بحق إلا الله، فهل أنتم -بعد قيام هذه الحجة عليكم- مسلمون منقادون لله ورسوله؟", "isBasmala": false, "translation_en": "But if they fail to answer you, know that it was revealed with God's knowledge, and that there is no god but He. Will you then submit?", "translation_id": "Jika mereka yang kamu seru itu tidak menerima seruanmu (ajakanmu) itu maka ketahuilah, sesungguhnya Al Quran itu diturunkan dengan ilmu Allah, dan bahwasanya tidak ada Tuhan selain Dia, maka maukah kamu berserah diri (kepada Allah)?", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 15, "text": "مَن كَانَ یُرِیدُ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا وَزِینَتَهَا نُوَفِّ إِلَیۡهِمۡ أَعۡمَـٰلَهُمۡ فِیهَا وَهُمۡ فِیهَا لَا یُبۡخَسُونَ ۝١٥", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "من كان يريد بعمله الحياة الدنيا ومُتَعها نعطهم ما قُسِم لهم من ثواب أعمالهم في الحياة الدنيا كاملا غير منقوص.", "isBasmala": false, "translation_en": "Whoever desires the worldly life and its glitter-We will fully recompense them for their deeds therein, and therein they will not be defrauded.", "translation_id": "Barangsiapa yang menghendaki kehidupan dunia dan perhiasannya, niscaya Kami berikan kepada mereka balasan pekerjaan mereka di dunia dengan sempurna dan mereka di dunia itu tidak akan dirugikan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 16, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَیۡسَ لَهُمۡ فِی ٱلۡـَٔاخِرَةِ إِلَّا ٱلنَّارُۖ وَحَبِطَ مَا صَنَعُوا۟ فِیهَا وَبَـٰطِلࣱ مَّا كَانُوا۟ یَعۡمَلُونَ ۝١٦", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "أولئك ليس لهم في الآخرة إلا نار جهنم يقاسون حرَّها، وذهب عنهم نَفْع ما عملوه، وكان عملهم باطلا لأنه لم يكن لوجه الله.", "isBasmala": false, "translation_en": "These-they will have nothing but the Fire in the Hereafter. Their deeds are in vain therein, and their works are null.", "translation_id": "Itulah orang-orang yang tidak memperoleh di akhirat, kecuali neraka dan lenyaplah di akhirat itu apa yang telah mereka usahakan di dunia dan sia-sialah apa yang telah mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 17, "text": "أَفَمَن كَانَ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّهِۦ وَیَتۡلُوهُ شَاهِدࣱ مِّنۡهُ وَمِن قَبۡلِهِۦ كِتَـٰبُ مُوسَىٰۤ إِمَامࣰا وَرَحۡمَةًۚ أُو۟لَـٰۤىِٕكَ یُؤۡمِنُونَ بِهِۦۚ وَمَن یَكۡفُرۡ بِهِۦ مِنَ ٱلۡأَحۡزَابِ فَٱلنَّارُ مَوۡعِدُهُۥۚ فَلَا تَكُ فِی مِرۡیَةࣲ مِّنۡهُۚ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یُؤۡمِنُونَ ۝١٧", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "أفمَن كان على حجة وبصيرة من ربه فيما يؤمن به، ويدعو إليه بالوحي الذي أنزل الله فيه هذه البينة، ويتلوها برهان آخر شاهد منه، وهو جبريل أو محمد عليهما السلام، ويؤيد ذلك برهان ثالث من قبل القرآن، وهو التوراة -الكتاب الذي أنزل على موسى إمامًا ورحمة لمن آمن به-، كمن كان همه الحياة الفانية بزينتها؟ أولئك يصدِّقون بهذا القرآن ويعملون بأحكامه، ومن يكفر بهذا القرآن من الذين تحزَّبوا على رسول الله صلى الله عليه وسلم فجزاؤه النار، يَرِدُها لا محالة، فلا تك -أيها الرسول- في شك من أمر القرآن وكونه من عند الله تعالى بعد ما شهدت بذلك الأدلة والحجج، واعلم أن هذا الدين هو الحق من ربك، ولكن أكثر الناس لا يصدِّقون ولا يعملون بما أُمروا به. وهذا توجيه عام لأمة محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Is he who possesses a clear proof from his Lord, recited by a witness from Him, and before it the Book of Moses, a guide and a mercy? These believe in it. But whoever defies it from among the various factions, the Fire is his promise. So have no doubt about it. It is the truth from your Lord, but most people do not believe.", "translation_id": "Apakah (orang-orang kafir itu sama dengan) orang-orang yang ada mempunyai bukti yang nyata (Al Quran) dari Tuhannya, dan diikuti pula oleh seorang saksi (Muhammad) dari Allah dan sebelum Al Quran itu telah ada Kitab Musa yang menjadi pedoman dan rahmat? Mereka itu beriman kepada Al Quran. Dan barangsiapa di antara mereka (orang-orang Quraisy) dan sekutu-sekutunya yang kafir kepada Al Quran, maka nerakalah tempat yang diancamkan baginya, karena itu janganlah kamu ragu-ragu terhadap Al Quran itu. Sesungguhnya (Al Quran) itu benar-benar dari Tuhanmu, tetapi kebanyakan manusia tidak beriman.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 18, "text": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًاۚ أُو۟لَـٰۤىِٕكَ یُعۡرَضُونَ عَلَىٰ رَبِّهِمۡ وَیَقُولُ ٱلۡأَشۡهَـٰدُ هَـٰۤؤُلَاۤءِ ٱلَّذِینَ كَذَبُوا۟ عَلَىٰ رَبِّهِمۡۚ أَلَا لَعۡنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِینَ ۝١٨", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "ولا أحد أظلم ممن اختلق على الله كذبًا، أولئك سيعرضون على ربهم يوم القيامة؛ ليحاسبهم على أعمالهم، ويقول الأشهاد من الملائكة والنبيين وغيرهم: هؤلاء الذين كذبوا على ربهم في الدنيا قد سخط الله عليهم، ولعنهم لعنة لا تنقطع؛ لأن ظلمهم صار وصفًا ملازمًا لهم.", "isBasmala": false, "translation_en": "Who does greater wrong than he who fabricates lies about God? These will be presented before their Lord, and the witnesses will say, \"These are they who lied about their Lord.\" Indeed, the curse of God is upon the wrongdoers.", "translation_id": "Dan siapakah yang lebih zalim daripada orang yang membuat-buat dusta terhadap Allah? Mereka itu akan dihadapkan kepada Tuhan mereka, dan para saksi akan berkata: \"Orang-orang inilah yang telah berdusta terhadap Tuhan mereka\". Ingatlah, kutukan Allah (ditimpakan) atas orang-orang yang zalim,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 19, "text": "ٱلَّذِینَ یَصُدُّونَ عَن سَبِیلِ ٱللَّهِ وَیَبۡغُونَهَا عِوَجࣰا وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ كَـٰفِرُونَ ۝١٩", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "هؤلاء الظالمون الذين يمنعون الناس عن سبيل الله الموصلة إلى عبادته، ويريدون أن تكون هذه السبيل عوجاء بموافقتها لأهوائهم، وهم كافرون بالآخرة لا يؤمنون ببعث ولا جزاء.", "isBasmala": false, "translation_en": "Those who hinder others from the path of God, and seek to make it crooked; and regarding the Hereafter, they are in denial.", "translation_id": "(yaitu) orang-orang yang menghalangi (manusia) dari jalan Allah dan menghendaki (supaya) jalan itu bengkok. Dan mereka itulah orang-orang yang tidak percaya akan adanya hari akhirat.", "manzil": 3, "manzil_display": ""}], "224": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 20, "text": "أُو۟لَـٰۤىِٕكَ لَمۡ یَكُونُوا۟ مُعۡجِزِینَ فِی ٱلۡأَرۡضِ وَمَا كَانَ لَهُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِیَاۤءَۘ یُضَـٰعَفُ لَهُمُ ٱلۡعَذَابُۚ مَا كَانُوا۟ یَسۡتَطِیعُونَ ٱلسَّمۡعَ وَمَا كَانُوا۟ یُبۡصِرُونَ ۝٢٠", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "أولئك الكافرون لم يكونوا ليفوتوا الله في الدنيا هربًا، وما كان لهم مِن أنصار يمنعونهم من عقابه. يضاعَفُ لهم العذاب في جهنم؛ لأنهم كانوا لا يستطيعون أن يسمعوا القرآن سماع منتفع، أو يبصروا آيات الله في هذا الكون إبصار مهتد؛ لاشتغالهم بالكفر الذي كانوا عليه مقيمين.", "isBasmala": false, "translation_en": "These will not escape on earth, and they have no protectors besides God. The punishment will be doubled for them. They have failed to hear, and they have failed to see.", "translation_id": "Orang-orang itu tidak mampu menghalang-halangi Allah untuk (mengazab mereka) di bumi ini, dan sekali-kali tidak adalah bagi mereka penolong selain Allah. Siksaan itu dilipat gandakan kepada mereka. Mereka selalu tidak dapat mendengar (kebenaran) dan mereka selalu tidak dapat melihat(nya).", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 21, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ ۝٢١", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "أولئك الذين خسروا أنفسهم بافترائهم على الله، وذهب عنهم ما كانوا يفترون من الآلهة التي يدَّعون أنها تشفع لهم.", "isBasmala": false, "translation_en": "Those are the ones who lost their souls, and what they had invented has strayed away from them.", "translation_id": "Mereka itulah orang-orang yang merugikan dirinya sendiri, dan lenyaplah dari mereka apa yang selalu mereka ada-adakan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 22, "text": "لَا جَرَمَ أَنَّهُمۡ فِی ٱلۡـَٔاخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ ۝٢٢", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "حقًا أنهم في الآخرة أخسر الناس صفقة؛ لأنهم استبدلوا الدركات بالدرجات، فكانوا في جهنم، وذلك هو الخسران المبين.", "isBasmala": false, "translation_en": "Without a doubt, in the Hereafter, they will be the biggest losers.", "translation_id": "Pasti mereka itu di akhirat menjadi orang-orang yang paling merugi.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 23, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَأَخۡبَتُوۤا۟ إِلَىٰ رَبِّهِمۡ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٢٣", "juz": 12, "hizb": "(* ح 23*)", "tafsir": "إن الذين صدَّقوا الله ورسوله وعملوا الأعمال الصالحة، وخضعوا لله في كل ما أُمروا به ونُهوا عنه، أولئك هم أهل الجنة، لا يموتون فيها، ولا يَخْرجون منها أبدًا.", "isBasmala": false, "translation_en": "As for those who believe and do good deeds, and humble themselves before their Lord-these are the inhabitants of Paradise, where they will abide forever.", "translation_id": "Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal saleh dan merendahkan diri kepada Tuhan mereka, mereka itu adalah penghuni-penghuni surga; mereka kekal di dalamnya.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 24, "text": "۞ مَثَلُ ٱلۡفَرِیقَیۡنِ كَٱلۡأَعۡمَىٰ وَٱلۡأَصَمِّ وَٱلۡبَصِیرِ وَٱلسَّمِیعِۚ هَلۡ یَسۡتَوِیَانِ مَثَلًاۚ أَفَلَا تَذَكَّرُونَ ۝٢٤", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "مثل فريقَي الكفر والإيمان كمثل الأعمى الذي لا يرى والأصم الذي لا يسمع والبصير والسميع: ففريق الكفر لا يبصر الحق فيتبعه، ولا يسمع داعي الله فيهتدي به، أما فريق الإيمان فقد أبصر حجج الله وسمع داعي الله فأجابه، هل يستوي هذان الفريقان؟ أفلا تعتبرون وتتفكرون؟", "isBasmala": false, "translation_en": "The parable of the two groups is that of the blind and the deaf, and the seeing and the hearing. Are they equal in comparison? Will you not reflect?", "translation_id": "Perbandingan kedua golongan itu (orang-orang kafir dan orang-orang mukmin), seperti orang buta dan tuli dengan orang yang dapat melihat dan dapat mendengar. Adakah kedua golongan itu sama keadaan dan sifatnya? Maka tidakkah kamu mengambil pelajaran (daripada perbandingan itu)?", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 25, "text": "وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦۤ إِنِّی لَكُمۡ نَذِیرࣱ مُّبِینٌ ۝٢٥", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "ولقد أرسلنا نوحًا إلى قومه فقال لهم: إني نذير لكم من عذاب الله، مبيِّن لكم ما أُرسلت به إليكم من أمر الله ونهيه.", "isBasmala": false, "translation_en": "We sent Noah to his people, \"I am to you a clear warner.\"", "translation_id": "Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, (dia berkata): \"Sesungguhnya aku adalah pemberi peringatan yang nyata bagi kamu,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 26, "text": "أَن لَّا تَعۡبُدُوۤا۟ إِلَّا ٱللَّهَۖ إِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمٍ أَلِیمࣲ ۝٢٦", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "آمركم ألا تعبدوا إلا الله، إني أخاف عليكم -إن لم تفردوا الله وحده بالعبادة- عذاب يوم موجع.", "isBasmala": false, "translation_en": "\"That you shall worship none but God. I fear for you the agony of a painful Day.\"", "translation_id": "agar kamu tidak menyembah selain Allah. Sesungguhnya aku takut kamu akan ditimpa azab (pada) hari yang sangat menyedihkan\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 27, "text": "فَقَالَ ٱلۡمَلَأُ ٱلَّذِینَ كَفَرُوا۟ مِن قَوۡمِهِۦ مَا نَرَىٰكَ إِلَّا بَشَرࣰا مِّثۡلَنَا وَمَا نَرَىٰكَ ٱتَّبَعَكَ إِلَّا ٱلَّذِینَ هُمۡ أَرَاذِلُنَا بَادِیَ ٱلرَّأۡیِ وَمَا نَرَىٰ لَكُمۡ عَلَیۡنَا مِن فَضۡلِۭ بَلۡ نَظُنُّكُمۡ كَـٰذِبِینَ ۝٢٧", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "فقال رؤساء الكفر من قومه: إنك لست بمَلَك ولكنك بشر، فكيف أُوحي إليك مِن دوننا؟ وما نراك اتبعك إلا الذين هم أسافلنا وإنما اتبعوك من غير تفكر ولا رويَّة، وما نرى لكم علينا من فضل في رزق ولا مال لـمَّا دخلتم في دينكم هذا، بل نعتقد أنكم كاذبون فيما تدَّعون.", "isBasmala": false, "translation_en": "The notables who disbelieved among his people said, \"We see in you nothing but a man like us, and we see that only the worst among us have followed you, those of immature judgment. And we see that you have no advantage over us. In fact, we think you are liars.\"", "translation_id": "Maka berkatalah pemimpin-pemimpin yang kafir dari kaumnya: \"Kami tidak melihat kamu, melainkan (sebagai) seorang manusia (biasa) seperti kami, dan kami tidak melihat orang-orang yang mengikuti kamu, melainkan orang-orang yang hina dina di antara kami yang lekas percaya saja, dan kami tidak melihat kamu memiliki sesuatu kelebihan apapun atas kami, bahkan kami yakin bahwa kamu adalah orang-orang yang dusta\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 28, "text": "قَالَ یَـٰقَوۡمِ أَرَءَیۡتُمۡ إِن كُنتُ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّی وَءَاتَىٰنِی رَحۡمَةࣰ مِّنۡ عِندِهِۦ فَعُمِّیَتۡ عَلَیۡكُمۡ أَنُلۡزِمُكُمُوهَا وَأَنتُمۡ لَهَا كَـٰرِهُونَ ۝٢٨", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "قال نوح: يا قومي أرأيتم إن كنتُ على حجة ظاهرة من ربي فيما جئتكم به تبيِّن لكم أنني على الحق من عنده، وآتاني رحمة من عنده، وهي النبوة والرسالة فأخفاها عليكم بسبب جهلكم وغروركم، فهل يصح أن نُلْزمكم إياها بالإكراه وأنتم جاحدون بها؟ لا نفعل ذلك، ولكن نَكِل أمركم إلى الله حتى يقضي في أمركم ما يشاء.", "isBasmala": false, "translation_en": "He said, \"O my people, Have you considered? If I stand on clear evidence from my Lord, and He has given me a mercy from Himself, but you were blind to it, can we compel you to accept it, even though you dislike it?\"", "translation_id": "Berkata Nuh: \"Hai kaumku, bagaimana pikiranmu, jika aku ada mempunyai bukti yang nyata dari Tuhanku, dan diberinya aku rahmat dari sisi-Nya, tetapi rahmat itu disamarkan bagimu. Apa akan kami paksakankah kamu menerimanya, padahal kamu tiada menyukainya?\"", "manzil": 3, "manzil_display": ""}], "225": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 29, "text": "وَیَـٰقَوۡمِ لَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مَالًاۖ إِنۡ أَجۡرِیَ إِلَّا عَلَى ٱللَّهِۚ وَمَاۤ أَنَا۠ بِطَارِدِ ٱلَّذِینَ ءَامَنُوۤا۟ۚ إِنَّهُم مُّلَـٰقُوا۟ رَبِّهِمۡ وَلَـٰكِنِّیۤ أَرَىٰكُمۡ قَوۡمࣰا تَجۡهَلُونَ ۝٢٩", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "قال نوح عليه السلام لقومه: يا قوم لا أسألكم على دعوتكم لتوحيد الله وإخلاص العبادة له مالاً تؤدونه إليَّ بعد إيمانكم، ولكن ثواب نصحي لكم على الله وحده، وليس من شأني أن أطرد المؤمنين، فإنهم ملاقو ربهم يوم القيامة، ولكني أراكم قومًا تجهلون؛ إذ تأمرونني بطرد أولياء الله وإبعادهم عني.", "isBasmala": false, "translation_en": "\"O my people! I ask of you no money for it. My reward lies only with God. And I am not about to dismiss those who believed; they will surely meet their Lord. And I see that you are ignorant people.\"", "translation_id": "Dan (dia berkata): \"Hai kaumku, aku tiada meminta harta benda kepada kamu (sebagai upah) bagi seruanku. Upahku hanyalah dari Allah dan aku sekali-kali tidak akan mengusir orang-orang yang telah beriman. Sesungguhnya mereka akan bertemu dengan Tuhannya, akan tetapi aku memandangmu suatu kaum yang tidak mengetahui\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 30, "text": "وَیَـٰقَوۡمِ مَن یَنصُرُنِی مِنَ ٱللَّهِ إِن طَرَدتُّهُمۡۚ أَفَلَا تَذَكَّرُونَ ۝٣٠", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "ويا قوم مَن يمنعني من الله إن عاقبني على طردي المؤمنين؟ أفلا تتدبرون الأمور فتعلموا ما هو الأنفع لكم والأصلح؟", "isBasmala": false, "translation_en": "\"O my people! Who will support me against God, if I dismiss them? Will you not give a thought?\"", "translation_id": "Dan (dia berkata): \"Hai kaumku, siapakah yang akan menolongku dari (azab) Allah jika aku mengusir mereka. Maka tidakkah kamu mengambil pelajaran?", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 31, "text": "وَلَاۤ أَقُولُ لَكُمۡ عِندِی خَزَاۤىِٕنُ ٱللَّهِ وَلَاۤ أَعۡلَمُ ٱلۡغَیۡبَ وَلَاۤ أَقُولُ إِنِّی مَلَكࣱ وَلَاۤ أَقُولُ لِلَّذِینَ تَزۡدَرِیۤ أَعۡیُنُكُمۡ لَن یُؤۡتِیَهُمُ ٱللَّهُ خَیۡرًاۖ ٱللَّهُ أَعۡلَمُ بِمَا فِیۤ أَنفُسِهِمۡ إِنِّیۤ إِذࣰا لَّمِنَ ٱلظَّـٰلِمِینَ ۝٣١", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "ولا أقول لكم: إني أملك التصرف في خزائن الله، ولا أعلم الغيب، ولست بمَلَك من الملائكة، ولا أقول لهؤلاء الذين تحتقرون من ضعفاء المؤمنين: لن يؤتيكم الله ثوابًا على أعمالكم، فالله وحده أعلم بما في صدورهم وقلوبهم، ولئن فعلتُ ذلك إني إذًا لمن الظالمين لأنفسهم ولغيرهم.", "isBasmala": false, "translation_en": "\"I do not say to you that I possess the treasures of God, nor do I know the future, nor do I say that I am an angel. Nor do I say of those who are despicable in your eyes that God will never give them any good. God is Aware of what lies in their souls. If I did, I would be one of the wrongdoers.\"", "translation_id": "Dan aku tidak mengatakan kepada kamu (bahwa): \"Aku mempunyai gudang-gudang rezeki dan kekayaan dari Allah, dan aku tiada mengetahui yang ghaib\", dan tidak (pula) aku mengatakan: \"Bahwa sesungguhnya aku adalah malaikat\", dan tidak juga aku mengatakan kepada orang-orang yang dipandang hina oleh penglihatanmu: \"Sekali-kali Allah tidak akan mendatangkan kebaikan kepada mereka\". Allah lebih mengetahui apa yang ada pada diri mereka; sesungguhnya aku, kalau begitu benar-benar termasuk orang-orang yang zalim.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 32, "text": "قَالُوا۟ یَـٰنُوحُ قَدۡ جَـٰدَلۡتَنَا فَأَكۡثَرۡتَ جِدَ ٰلَنَا فَأۡتِنَا بِمَا تَعِدُنَاۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ ۝٣٢", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "قالوا: يا نوح قد حاججتنا فأكثرت جدالنا، فأتنا بما تعدنا من العذاب إن كنت من الصادقين في دعواك.", "isBasmala": false, "translation_en": "They said, \"O Noah, you have argued with us, and argued a great deal. Now bring upon us what you threaten us with, if you are truthful.\"", "translation_id": "Mereka berkata \"Hai Nuh, sesungguhnya kamu telah berbantah dengan kami, dan kamu telah memperpanjang bantahanmu terhadap kami, maka datangkanlah kepada kami azab yang kamu ancamkan kepada kami, jika kamu termasuk orang-orang yang benar\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 33, "text": "قَالَ إِنَّمَا یَأۡتِیكُم بِهِ ٱللَّهُ إِن شَاۤءَ وَمَاۤ أَنتُم بِمُعۡجِزِینَ ۝٣٣", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "قال نوح لقومه: إن الله وحده هو الذي يأتيكم بالعذاب إذا شاء، ولستم بفائتيه إذا أراد أن يعذبكم؛ لأنه سبحانه لا يعجزه شيء في الأرض ولا في السماء.", "isBasmala": false, "translation_en": "He said, \"It is God who will bring it upon you, if He wills, and you will not be able to escape.\"", "translation_id": "Nuh menjawab: \"Hanyalah Allah yang akan mendatangkan azab itu kepadamu jika Dia menghendaki, dan kamu sekali-kali tidak dapat melepaskan diri.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 34, "text": "وَلَا یَنفَعُكُمۡ نُصۡحِیۤ إِنۡ أَرَدتُّ أَنۡ أَنصَحَ لَكُمۡ إِن كَانَ ٱللَّهُ یُرِیدُ أَن یُغۡوِیَكُمۡۚ هُوَ رَبُّكُمۡ وَإِلَیۡهِ تُرۡجَعُونَ ۝٣٤", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "ولا ينفعكم نصحي واجتهادي في دعوتكم للإيمان، إن كان الله يريد أن يضلَّكم ويهلككم، هو سبحانه مالككم، وإليه تُرجَعون في الآخرة للحساب والجزاء.", "isBasmala": false, "translation_en": "\"My advice will not benefit you, much as I may want to advise you, if God desires to confound you. He is your Lord, and to Him you will be returned.\"", "translation_id": "Dan tidaklah bermanfaat kepadamu nasehatku jika aku hendak memberi nasehat kepada kamu, sekiranya Allah hendak menyesatkan kamu, Dia adalah Tuhanmu, dan kepada-Nya-lah kamu dikembalikan\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 35, "text": "أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَیۡتُهُۥ فَعَلَیَّ إِجۡرَامِی وَأَنَا۠ بَرِیۤءࣱ مِّمَّا تُجۡرِمُونَ ۝٣٥", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "بل أيقول هؤلاء المشركون من قوم نوح: افترى نوح هذا القول؟ قل لهم: إن كنتُ قد افتريتُ ذلك على الله فعليَّ وحدي إثم ذلك، وإذا كنتُ صادقًا فأنتم المجرمون الآثمون، وأنا بريء مِن كفركم وتكذيبكم وإجرامكم.", "isBasmala": false, "translation_en": "Or do they say, \"He made it up?\" Say, \"If I made it up, upon me falls my crime, and I am innocent of the crimes you commit.\"", "translation_id": "Malahan kaum Nuh itu berkata: \"Dia cuma membuat-buat nasihatnya saja\". Katakanlah: \"Jika aku membuat-buat nasihat itu, maka hanya akulah yang memikul dosaku, dan aku berlepas diri dari dosa yang kamu perbuat\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 36, "text": "وَأُوحِیَ إِلَىٰ نُوحٍ أَنَّهُۥ لَن یُؤۡمِنَ مِن قَوۡمِكَ إِلَّا مَن قَدۡ ءَامَنَ فَلَا تَبۡتَىِٕسۡ بِمَا كَانُوا۟ یَفۡعَلُونَ ۝٣٦", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "وأوحى الله سبحانه وتعالى إلى نوح -عليه السلام- لـمَّا حق على قومه العذاب، أنه لن يؤمن بالله إلا مَن قد آمن مِن قبل، فلا تحزن يا نوح على ما كانوا يفعلون.", "isBasmala": false, "translation_en": "And it was revealed to Noah: \"None of your people will believe, except those who have already believed, so do not grieve over what they do.\"", "translation_id": "Dan diwahyukan kepada Nuh, bahwasanya sekali-kali tidak akan beriman di antara kaummu, kecuali orang yang telah beriman (saja), karena itu janganlah kamu bersedih hati tentang apa yang selalu mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 37, "text": "وَٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡیُنِنَا وَوَحۡیِنَا وَلَا تُخَـٰطِبۡنِی فِی ٱلَّذِینَ ظَلَمُوۤا۟ إِنَّهُم مُّغۡرَقُونَ ۝٣٧", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "واصنع السفينة بمرأى منَّا وبأمرنا لك ومعونتنا، وأنت في حفظنا وكلاءتنا، ولا تطلب مني إمهال هؤلاء الذين ظلموا أنفسهم من قومك بكفرهم، فإنهم مغرقون بالطوفان. وفي الآية إثبات صفة العين لله تعالى على ما يليق به سبحانه.", "isBasmala": false, "translation_en": "\"And build the Ark, under Our eyes, and with Our inspiration, and do not address Me regarding those who did wrong; they are to be drowned.\"", "translation_id": "Dan buatlah bahtera itu dengan pengawasan dan petunjuk wahyu Kami, dan janganlah kamu bicarakan dengan Aku tentang orang-orang yang zalim itu; sesungguhnya mereka itu akan ditenggelamkan.", "manzil": 3, "manzil_display": ""}], "226": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 38, "text": "وَیَصۡنَعُ ٱلۡفُلۡكَ وَكُلَّمَا مَرَّ عَلَیۡهِ مَلَأࣱ مِّن قَوۡمِهِۦ سَخِرُوا۟ مِنۡهُۚ قَالَ إِن تَسۡخَرُوا۟ مِنَّا فَإِنَّا نَسۡخَرُ مِنكُمۡ كَمَا تَسۡخَرُونَ ۝٣٨", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "ويصنع نوح السفينة، وكلَّما مر عليه جماعة من كبراء قومه سخروا منه، قال لهم نوح: إن تسخروا منا اليوم لجهلكم بصدق وعد الله، فإنا نسخر منكم غدًا عند الغرق كما تسخرون منا.", "isBasmala": false, "translation_en": "As he was building the ark, whenever some of his people passed by him, they ridiculed him. He said, \"If you ridicule us, we will ridicule you, just as you ridicule.\"", "translation_id": "Dan mulailah Nuh membuat bahtera. Dan setiap kali pemimpin kaumnya berjalan meliwati Nuh, mereka mengejeknya. Berkatalah Nuh: \"Jika kamu mengejek kami, maka sesungguhnya kami (pun) mengejekmu sebagaimana kamu sekalian mengejek (kami).", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 39, "text": "فَسَوۡفَ تَعۡلَمُونَ مَن یَأۡتِیهِ عَذَابࣱ یُخۡزِیهِ وَیَحِلُّ عَلَیۡهِ عَذَابࣱ مُّقِیمٌ ۝٣٩", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "فسوف تعلمون إذا جاء أمر الله بذلك: من الذي يأتيه في الدنيا عذاب الله الذي يُهينه، وينزل به في الآخرة عذاب دائم لا انقطاع له؟", "isBasmala": false, "translation_en": "\"You will surely know upon whom will come a torment that will abase him, and upon whom will fall a lasting torment.\"", "translation_id": "Kelak kamu akan mengetahui siapa yang akan ditimpa oleh azab yang menghinakannya dan yang akan ditimpa azab yang kekal\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 40, "text": "حَتَّىٰۤ إِذَا جَاۤءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ قُلۡنَا ٱحۡمِلۡ فِیهَا مِن كُلࣲّ زَوۡجَیۡنِ ٱثۡنَیۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَیۡهِ ٱلۡقَوۡلُ وَمَنۡ ءَامَنَۚ وَمَاۤ ءَامَنَ مَعَهُۥۤ إِلَّا قَلِیلࣱ ۝٤٠", "juz": 12, "hizb": "(*¼ ح 23*)", "tafsir": "حتى إذا جاء أمرنا بإهلاكهم كما وَعدْنا نوحًا بذلك، ونبع الماء بقوة من التنور -وهو المكان الذي يخبز فيه- علامة على مجيء العذاب، قلنا لنوح: احمل في السفينة من كل نوع من أنواع الحيوانات ذكرًا وأنثى، واحمل فيها أهل بيتك، إلا مَن سبق عليهم القول ممن لم يؤمن بالله كابنه وامرأته، واحمل فيها من آمن معك من قومك، وما آمن معه إلا قليل مع طول المدة والمقام فيهم.", "isBasmala": false, "translation_en": "Until, when Our command came, and the volcano erupted, We said, \"Board into it a pair of every kind, and your family-except those against whom the sentence has already been passed-and those who have believed.\" But those who believed with him were only a few.", "translation_id": "Hingga apabila perintah Kami datang dan dapur telah memancarkan air, Kami berfirman: \"Muatkanlah ke dalam bahtera itu dari masing-masing binatang sepasang (jantan dan betina), dan keluargamu kecuali orang yang telah terdahulu ketetapan terhadapnya dan (muatkan pula) orang-orang yang beriman\". Dan tidak beriman bersama dengan Nuh itu kecuali sedikit.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 41, "text": "۞ وَقَالَ ٱرۡكَبُوا۟ فِیهَا بِسۡمِ ٱللَّهِ مَجۡر۪ىٰهَا وَمُرۡسَىٰهَاۤۚ إِنَّ رَبِّی لَغَفُورࣱ رَّحِیمࣱ ۝٤١", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "وقال نوح لمن آمن معه: اركبوا في السفينة، باسم الله يكون جريها على وجه الماء، وباسم الله يكون منتهى سيرها ورُسوُّها. إن ربي لَغفور ذنوب من تاب وأناب إليه من عباده، رحيم بهم أن يعذبهم بعد التوبة.", "isBasmala": false, "translation_en": "He said, \"Embark in it. In the name of God shall be its sailing and its anchorage. My Lord is indeed Forgiving and Merciful.\"", "translation_id": "Dan Nuh berkata: \"Naiklah kamu sekalian ke dalamnya dengan menyebut nama Allah di waktu berlayar dan berlabuhnya\". Sesungguhnya Tuhanku benar-benar Maha Pengampun lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 42, "text": "وَهِیَ تَجۡرِی بِهِمۡ فِی مَوۡجࣲ كَٱلۡجِبَالِ وَنَادَىٰ نُوحٌ ٱبۡنَهُۥ وَكَانَ فِی مَعۡزِلࣲ یَـٰبُنَیَّ ٱرۡكَب مَّعَنَا وَلَا تَكُن مَّعَ ٱلۡكَـٰفِرِینَ ۝٤٢", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "وهي تجري بهم في موج يعلو ويرتفع حتى يصير كالجبال في علوها، ونادى نوح ابنه -وكان في مكانٍ عَزَل فيه نفسه عن المؤمنين- فقال له: يا بني اركب معنا في السفينة، ولا تكن مع الكافرين بالله فتغرق.", "isBasmala": false, "translation_en": "And so it sailed with them amidst waves like hills. And Noah called to his son, who had kept away, \"On my son! Embark with us, and do not be with the disbelievers.\"", "translation_id": "Dan bahtera itu berlayar membawa mereka dalam gelombang laksana gunung. Dan Nuh memanggil anaknya, sedang anak itu berada di tempat yang jauh terpencil: \"Hai anakku, naiklah (ke kapal) bersama kami dan janganlah kamu berada bersama orang-orang yang kafir\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 43, "text": "قَالَ سَـَٔاوِیۤ إِلَىٰ جَبَلࣲ یَعۡصِمُنِی مِنَ ٱلۡمَاۤءِۚ قَالَ لَا عَاصِمَ ٱلۡیَوۡمَ مِنۡ أَمۡرِ ٱللَّهِ إِلَّا مَن رَّحِمَۚ وَحَالَ بَیۡنَهُمَا ٱلۡمَوۡجُ فَكَانَ مِنَ ٱلۡمُغۡرَقِینَ ۝٤٣", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "قال ابن نوح: سألجأ إلى جبل أتحصَّن به من الماء، فيمنعني من الغرق، فأجابه نوح: لا مانع اليوم من أمر الله وقضائه الذي قد نزل بالخلق من الغرق والهلاك إلا مَن رحمه الله تعالى، فآمِنْ واركب في السفينة معنا، وحال الموج المرتفع بين نوح وابنه، فكان من المغرقين الهالكين.", "isBasmala": false, "translation_en": "He said, \"I will take refuge on a mountain-it will protect me from the water.\" He said, \"There is no protection from God's decree today, except for him on whom He has mercy.\" And the waves surged between them, and he was among the drowned.", "translation_id": "Anaknya menjawab: \"Aku akan mencari perlindungan ke gunung yang dapat memeliharaku dari air bah!\" Nuh berkata: \"Tidak ada yang melindungi hari ini dari azab Allah selain Allah (saja) Yang Maha Penyayang\". Dan gelombang menjadi penghalang antara keduanya; maka jadilah anak itu termasuk orang-orang yang ditenggelamkan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 44, "text": "وَقِیلَ یَـٰۤأَرۡضُ ٱبۡلَعِی مَاۤءَكِ وَیَـٰسَمَاۤءُ أَقۡلِعِی وَغِیضَ ٱلۡمَاۤءُ وَقُضِیَ ٱلۡأَمۡرُ وَٱسۡتَوَتۡ عَلَى ٱلۡجُودِیِّۖ وَقِیلَ بُعۡدࣰا لِّلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝٤٤", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "وقال الله للأرض -بعد هلاك قوم نوح -: يا أرض اشربي ماءك، ويا سماء أمسكي عن المطر، ونقص الماء ونضب، وقُضي أمر الله بهلاك قوم نوح، ورست السفينة على جبل الجوديِّ، وقيل: هلاكًا وبعدًا للقوم الظالمين الذين تجاوزوا حدود الله، ولم يؤمنوا به.", "isBasmala": false, "translation_en": "And it was said, \"O earth, swallow your waters,\" and \"O heaven, clear up.\" And the waters receded, and the event was concluded, and it settled on Judi, and it was proclaimed: \"Away with the wicked people.\"", "translation_id": "Dan difirmankan: \"Hai bumi telanlah airmu, dan hai langit (hujan) berhentilah,\" dan airpun disurutkan, perintahpun diselesaikan dan bahtera itupun berlabuh di atas bukit Judi, dan dikatakan: \"Binasalah orang-orang yang zalim\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 45, "text": "وَنَادَىٰ نُوحࣱ رَّبَّهُۥ فَقَالَ رَبِّ إِنَّ ٱبۡنِی مِنۡ أَهۡلِی وَإِنَّ وَعۡدَكَ ٱلۡحَقُّ وَأَنتَ أَحۡكَمُ ٱلۡحَـٰكِمِینَ ۝٤٥", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "ونادى نوح ربه فقال: رب إنك وعَدْتني أن تنجيني وأهلي من الغرق والهلاك، وإن ابني هذا من أهلي، وإن وعدك الحق الذي لا خُلْف فيه، وأنت أحكم الحاكمين وأعدلهم.", "isBasmala": false, "translation_en": "And Noah called to his Lord. He said, \"O My Lord, my son is of my family, and Your promise is true, and You are the Wisest of the wise.\"", "translation_id": "Dan Nuh berseru kepada Tuhannya sambil berkata: \"Ya Tuhanku, sesungguhnya anakku termasuk keluargaku, dan sesungguhnya janji Engkau itulah yang benar. Dan Engkau adalah Hakim yang seadil-adilnya\".", "manzil": 3, "manzil_display": ""}], "227": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 46, "text": "قَالَ یَـٰنُوحُ إِنَّهُۥ لَیۡسَ مِنۡ أَهۡلِكَۖ إِنَّهُۥ عَمَلٌ غَیۡرُ صَـٰلِحࣲۖ فَلَا تَسۡـَٔلۡنِ مَا لَیۡسَ لَكَ بِهِۦ عِلۡمٌۖ إِنِّیۤ أَعِظُكَ أَن تَكُونَ مِنَ ٱلۡجَـٰهِلِینَ ۝٤٦", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "قال الله: يا نوح إن ابنك الذي هلك ليس من أهلك الذين وعدتك أن أنجيهم؛ وذلك بسبب كفره، وعمله عملا غير صالح، وإني أنهاك أن تسألني أمرًا لا علم لك به، إني أعظك لئلا تكون من الجاهلين في مسألتك إياي عن ذلك.", "isBasmala": false, "translation_en": "He said, \"O Noah, he is not of your family. It is an unrighteous deed. So do not ask Me about something you know nothing about. I admonish you, lest you be one of the ignorant.\"", "translation_id": "Allah berfirman: \"Hai Nuh, sesungguhnya dia bukanlah termasuk keluargamu (yang dijanjikan akan diselamatkan), sesungguhnya (perbuatan)nya perbuatan yang tidak baik. Sebab itu janganlah kamu memohon kepada-Ku sesuatu yang kamu tidak mengetahui (hakekat)nya. Sesungguhnya Aku memperingatkan kepadamu supaya kamu jangan termasuk orang-orang yang tidak berpengetahuan\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 47, "text": "قَالَ رَبِّ إِنِّیۤ أَعُوذُ بِكَ أَنۡ أَسۡـَٔلَكَ مَا لَیۡسَ لِی بِهِۦ عِلۡمࣱۖ وَإِلَّا تَغۡفِرۡ لِی وَتَرۡحَمۡنِیۤ أَكُن مِّنَ ٱلۡخَـٰسِرِینَ ۝٤٧", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "قال نوح: يا رب إني أعتصم وأستجير بك أن أسألك ما ليس لي به علم، وإن لم تغفر لي ذنبي، وترحمني برحمتك، أكن من الذين غَبَنوا أنفسهم حظوظها وهلكوا.", "isBasmala": false, "translation_en": "He said, \"O My Lord, I seek refuge with You, from asking You about what I have no knowledge of. Unless You forgive me, and have mercy on me, I will be one of the losers.\"", "translation_id": "Nuh berkata: Ya Tuhanku, sesungguhnya aku berlindung kepada Engkau dari memohon kepada Engkau sesuatu yang aku tiada mengetahui (hakekat)nya. Dan sekiranya Engkau tidak memberi ampun kepadaku, dan (tidak) menaruh belas kasihan kepadaku, niscaya aku akan termasuk orang-orang yang merugi\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 48, "text": "قِیلَ یَـٰنُوحُ ٱهۡبِطۡ بِسَلَـٰمࣲ مِّنَّا وَبَرَكَـٰتٍ عَلَیۡكَ وَعَلَىٰۤ أُمَمࣲ مِّمَّن مَّعَكَۚ وَأُمَمࣱ سَنُمَتِّعُهُمۡ ثُمَّ یَمَسُّهُم مِّنَّا عَذَابٌ أَلِیمࣱ ۝٤٨", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "قال الله: يا نوح اهبط من السفينة إلى الأرض بأمن وسلامة منَّا وبركات عليك وعلى أمم ممن معك. وهناك أمم وجماعات من أهل الشقاء سنمتعهم في الحياة الدنيا، إلى أن يبلغوا آجالهم، ثم ينالهم منا العذاب الموجع يوم القيامة.", "isBasmala": false, "translation_en": "It was said, \"O Noah, disembark with peace from Us; and with blessings upon you, and upon communities from those with you. And other communities We will grant prosperity, and then a painful torment from Us will befall them.\"", "translation_id": "Difirmankan: \"Hai Nuh, turunlah dengan selamat sejahtera dan penuh keberkatan dari Kami atasmu dan atas umat-umat (yang mukmin) dari orang-orang yang bersamamu. Dan ada (pula) umat-umat yang Kami beri kesenangan pada mereka (dalam kehidupan dunia), kemudian mereka akan ditimpa azab yang pedih dari Kami\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 49, "text": "تِلۡكَ مِنۡ أَنۢبَاۤءِ ٱلۡغَیۡبِ نُوحِیهَاۤ إِلَیۡكَۖ مَا كُنتَ تَعۡلَمُهَاۤ أَنتَ وَلَا قَوۡمُكَ مِن قَبۡلِ هَـٰذَاۖ فَٱصۡبِرۡۖ إِنَّ ٱلۡعَـٰقِبَةَ لِلۡمُتَّقِینَ ۝٤٩", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "تلك القصة التي قصصناها عليك -أيها الرسول- عن نوح وقومه هي من أخبار الغيب السالفة، نوحيها إليك، ما كنت تعلمها أنت ولا قومك مِن قبل هذا البيان، فاصبر على تكذيب قومك وإيذائهم لك، كما صبر الأنبياء من قبل، إن العاقبة الطيبة في الدنيا والآخرة للمتقين الذين يخشون الله.", "isBasmala": false, "translation_en": "These are some stories from the past that we reveal to you. Neither you, nor your people knew them before this. So be patient. The future belongs to the pious.", "translation_id": "Itu adalah di antara berita-berita penting tentang yang ghaib yang Kami wahyukan kepadamu (Muhammad); tidak pernah kamu mengetahuinya dan tidak (pula) kaummu sebelum ini. Maka bersabarlah; sesungguhnya kesudahan yang baik adalah bagi orang-orang yang bertakwa.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 50, "text": "وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤۖ إِنۡ أَنتُمۡ إِلَّا مُفۡتَرُونَ ۝٥٠", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "وأرسلنا إلى عاد أخاهم هودًا، قال لهم: يا قوم اعبدوا الله وحده، ليس لكم من إله يستحق العبادة غيره جل وعلا، فأخلصوا له العبادة، فما أنتم إلا كاذبون في إشراككم بالله.", "isBasmala": false, "translation_en": "And to Aad, their brother Hud. He said, \"O my people, worship God, you have no other god besides Him. You do nothing but invent lies.\"", "translation_id": "Dan kepada kaum 'Ad (Kami utus) saudara mereka, Huud. Ia berkata: \"Hai kaumku, sembahlah Allah, sekali-kali tidak ada bagimu Tuhan selain Dia. Kamu hanyalah mengada-adakan saja.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 51, "text": "یَـٰقَوۡمِ لَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ أَجۡرًاۖ إِنۡ أَجۡرِیَ إِلَّا عَلَى ٱلَّذِی فَطَرَنِیۤۚ أَفَلَا تَعۡقِلُونَ ۝٥١", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "يا قوم لا أسألكم على ما أدعوكم إليه من إخلاص العبادة لله وترك عبادة الأوثان أجرًا، ما أجري على دعوتي لكم إلا على الله الذي خلقني، أفلا تعقلون فتميِّزوا بين الحق والباطل؟", "isBasmala": false, "translation_en": "\"O my people, I ask you no wage for it; my wage lies with Him who originated me. Do you not understand?\"", "translation_id": "Hai kaumku, aku tidak meminta upah kepadamu bagi seruanku ini. Upahku tidak lain hanyalah dari Allah yang telah menciptakanku. Maka tidakkah kamu memikirkan(nya)?\"", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 52, "text": "وَیَـٰقَوۡمِ ٱسۡتَغۡفِرُوا۟ رَبَّكُمۡ ثُمَّ تُوبُوۤا۟ إِلَیۡهِ یُرۡسِلِ ٱلسَّمَاۤءَ عَلَیۡكُم مِّدۡرَارࣰا وَیَزِدۡكُمۡ قُوَّةً إِلَىٰ قُوَّتِكُمۡ وَلَا تَتَوَلَّوۡا۟ مُجۡرِمِینَ ۝٥٢", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "ويا قوم اطلبوا مغفرة الله والإيمان به، ثم توبوا إليه من ذنوبكم، فإنكم إن فعلتم ذلك يرسل المطر عليكم متتابعًا كثيرًا، فتكثر خيراتكم، ويزدكم قوة إلى قوتكم بكثرة ذرياتكم وتتابع النِّعم عليكم، ولا تُعرضوا عما دعوتكم إليه مصرِّين على إجرامكم.", "isBasmala": false, "translation_en": "\"O my people, ask forgiveness from your Lord, and repent to Him. He will release the sky pouring down upon you, and will add strength to your strength. And do not turn away and be wicked.\"", "translation_id": "Dan (dia berkata): \"Hai kaumku, mohonlah ampun kepada Tuhanmu lalu bertobatlah kepada-Nya, niscaya Dia menurunkan hujan yang sangat deras atasmu, dan Dia akan menambahkan kekuatan kepada kekuatanmu, dan janganlah kamu berpaling dengan berbuat dosa\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 53, "text": "قَالُوا۟ یَـٰهُودُ مَا جِئۡتَنَا بِبَیِّنَةࣲ وَمَا نَحۡنُ بِتَارِكِیۤ ءَالِهَتِنَا عَن قَوۡلِكَ وَمَا نَحۡنُ لَكَ بِمُؤۡمِنِینَ ۝٥٣", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "قالوا: يا هود ما جئتنا بحجة واضحة على صحة ما تدعونا إليه، وما نحن بتاركي آلهتنا التي نعبدها من أجل قولك، وما نحن بمصدِّقين لك فيما تدَّعيه.", "isBasmala": false, "translation_en": "They said, \"O Hud, you did not bring us any evidence, and we are not about to abandon our gods at your word, and we are not believers in you.\"", "translation_id": "Kaum 'Ad berkata: \"Hai Huud, kamu tidak mendatangkan kepada kami suatu bukti yang nyata, dan kami sekali-kali tidak akan meninggalkan sembahan-sembahan kami karena perkataanmu, dan kami sekali-kali tidak akan mempercayai kamu.", "manzil": 3, "manzil_display": ""}], "228": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 54, "text": "إِن نَّقُولُ إِلَّا ٱعۡتَرَىٰكَ بَعۡضُ ءَالِهَتِنَا بِسُوۤءࣲۗ قَالَ إِنِّیۤ أُشۡهِدُ ٱللَّهَ وَٱشۡهَدُوۤا۟ أَنِّی بَرِیۤءࣱ مِّمَّا تُشۡرِكُونَ ۝٥٤", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "ما نقول إلا أن بعض آلهتنا أصابك بجنون بسبب نهيك عن عبادتها. قال لهم: إني أُشهد الله على ما أقول، وأُشهدكم على أنني بريء مما تشركون، مِن دون الله من الأنداد والأصنام، فانظروا واجتهدوا أنتم ومَن زعمتم من آلهتكم في إلحاق الضرر بي، ثم لا تؤخروا ذلك طرفة عين؛ ذلك أن هودًا واثق كل الوثوق أنه لا يصيبه منهم ولا من آلهتهم أذى.", "isBasmala": false, "translation_en": "\"We only say that some of our gods have possessed you with evil.\" He said, \"I call God to witness, and you to witness, that I am innocent of what you associate.", "translation_id": "Kami tidak mengatakan melainkan bahwa sebagian sembahan kami telah menimpakan penyakit gila atas dirimu\". Huud menjawab: \"Sesungguhnya aku bersaksi kepada Allah dan saksikanlah olehmu sekalian bahwa sesungguhnya aku berlepas diri dari apa yang kamu persekutukan,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 55, "text": "مِن دُونِهِۦۖ فَكِیدُونِی جَمِیعࣰا ثُمَّ لَا تُنظِرُونِ ۝٥٥", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "ما نقول إلا أن بعض آلهتنا أصابك بجنون بسبب نهيك عن عبادتها. قال لهم: إني أُشهد الله على ما أقول، وأُشهدكم على أنني بريء مما تشركون، مِن دون الله من الأنداد والأصنام، فانظروا واجتهدوا أنتم ومَن زعمتم من آلهتكم في إلحاق الضرر بي، ثم لا تؤخروا ذلك طرفة عين؛ ذلك أن هودًا واثق كل الوثوق أنه لا يصيبه منهم ولا من آلهتهم أذى.", "isBasmala": false, "translation_en": "Besides Him. So scheme against me, all of you, and do not hesitate.", "translation_id": "dari selain-Nya, sebab itu jalankanlah tipu dayamu semuanya terhadapku dan janganlah kamu memberi tangguh kepadaku.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 56, "text": "إِنِّی تَوَكَّلۡتُ عَلَى ٱللَّهِ رَبِّی وَرَبِّكُمۚ مَّا مِن دَاۤبَّةٍ إِلَّا هُوَ ءَاخِذُۢ بِنَاصِیَتِهَاۤۚ إِنَّ رَبِّی عَلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٥٦", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "إني توكلت على الله ربي وربكم مالك كل شيء والمتصرف فيه، فلا يصيبني شيء إلا بأمره، وهو القادر على كل شيء، فليس من شيء يدِبُّ على هذه الأرض إلا والله مالكه، وهو في سلطانه وتصرفه. إن ربي على صراط مستقيم، أي عدل في قضائه وشرعه وأمره. يجازي المحسن بإحسانه والمسيء بإساءته.", "isBasmala": false, "translation_en": "I have placed my trust in God, my Lord and your Lord. There is not a creature but He holds it by the forelock. My Lord is on a straight path.", "translation_id": "Sesungguhnya aku bertawakkal kepada Allah Tuhanku dan Tuhanmu. Tidak ada suatu binatang melatapun melainkan Dialah yang memegang ubun-ubunnya. Sesungguhnya Tuhanku di atas jalan yang lurus\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 57, "text": "فَإِن تَوَلَّوۡا۟ فَقَدۡ أَبۡلَغۡتُكُم مَّاۤ أُرۡسِلۡتُ بِهِۦۤ إِلَیۡكُمۡۚ وَیَسۡتَخۡلِفُ رَبِّی قَوۡمًا غَیۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَیۡـًٔاۚ إِنَّ رَبِّی عَلَىٰ كُلِّ شَیۡءٍ حَفِیظࣱ ۝٥٧", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "فإن تُعرضوا عما أدعوكم إليه من توحيد الله وإخلاص العبادة له فقد أبلغتكم رسالة ربي إليكم، وقامت عليكم الحجة، وحيث لم تؤمنوا بالله فسيهلككم ويأتي بقوم آخرين يخلفونكم في دياركم وأموالكم، ويخلصون لله العبادة، ولا تضرونه شيئًا، إن ربي على كل شيء حفيظ، فهو الذي يحفظني من أن تنالوني بسوء.", "isBasmala": false, "translation_en": "If you turn away, I have conveyed to you what I was sent to you with; and my Lord will replace you with another people, and you will not cause Him any harm. My Lord is Guardian over all things.\"", "translation_id": "Jika kamu berpaling, maka sesungguhnya aku telah menyampaikan kepadamu apa (amanat) yang aku diutus (untuk menyampaikan)nya kepadamu. Dan Tuhanku akan mengganti (kamu) dengan kaum yang lain (dari) kamu; dan kamu tidak dapat membuat mudharat kepada-Nya sedikitpun. Sesungguhnya Tuhanku adalah Maha Pemelihara segala sesuatu.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 58, "text": "وَلَمَّا جَاۤءَ أَمۡرُنَا نَجَّیۡنَا هُودࣰا وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَنَجَّیۡنَـٰهُم مِّنۡ عَذَابٍ غَلِیظࣲ ۝٥٨", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "ولما جاء أمرنا بعذاب قوم هود نجَّينا منه هودًا والمؤمنين بفضل منَّا عليهم ورحمة، ونجَّيناهم من عذاب شديد أحله الله بعادٍ فأصبحوا لا يُرى إلا مساكنُهم.", "isBasmala": false, "translation_en": "And when Our decree came, We saved Hud and those who believed with him, by a mercy from Us, and We delivered them from a harsh punishment.", "translation_id": "Dan tatkala datang azab Kami, Kami selamatkan Huud dan orang-orang yang beriman bersama dia dengan rahmat dari Kami; dan Kami selamatkan (pula) mereka (di akhirat) dari azab yang berat.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 59, "text": "وَتِلۡكَ عَادࣱۖ جَحَدُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ وَعَصَوۡا۟ رُسُلَهُۥ وَٱتَّبَعُوۤا۟ أَمۡرَ كُلِّ جَبَّارٍ عَنِیدࣲ ۝٥٩", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "وتلك عاد كفروا بآيات الله وعصَوا رسله، وأطاعوا أمر كل مستكبر على الله لا يقبل الحق ولا يُذْعن له.", "isBasmala": false, "translation_en": "That was Aad; they denied the signs of their Lord, and defied His messengers, and followed the lead of every stubborn tyrant.", "translation_id": "Dan itulah (kisah) kaum 'Ad yang mengingkari tanda-tanda kekuasaan Tuhan mereka, dan mendurhakai rasul-rasul Allah dan mereka menuruti perintah semua penguasa yang sewenang-wenang lagi menentang (kebenaran).", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 60, "text": "وَأُتۡبِعُوا۟ فِی هَـٰذِهِ ٱلدُّنۡیَا لَعۡنَةࣰ وَیَوۡمَ ٱلۡقِیَـٰمَةِۗ أَلَاۤ إِنَّ عَادࣰا كَفَرُوا۟ رَبَّهُمۡۗ أَلَا بُعۡدࣰا لِّعَادࣲ قَوۡمِ هُودࣲ ۝٦٠", "juz": 12, "hizb": "(*½ ح 23*)", "tafsir": "وأُتبعوا في هذه الدنيا لعنة من الله وسخطًا منه يوم القيامة. ألا إن عادًا جحدوا ربهم وكذَّبوا رسله. ألا بُعْدًا وهلاكًا لعاد قوم هود؛ بسبب شركهم وكفرهم نعمة ربهم.", "isBasmala": false, "translation_en": "And they were pursued by a curse in this world, and on the Day of Resurrection. Indeed, Aad blasphemed against their Lord-so away with Aad, the people of Hud.", "translation_id": "Dan mereka selalu diikuti dengan kutukan di dunia ini dan (begitu pula) di hari kiamat. Ingatlah, sesungguhnya kaum 'Ad itu kafir kepada Tuhan mereka. Ingatlah kebinasaanlah bagi kaum 'Ad (yaitu) kaum Huud itu.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 61, "text": "۞ وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَـٰلِحࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِیهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوۤا۟ إِلَیۡهِۚ إِنَّ رَبِّی قَرِیبࣱ مُّجِیبࣱ ۝٦١", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "وأرسلنا إلى ثمود أخاهم صالحًا، فقال لهم: يا قوم اعبدوا الله وحده ليس لكم من إله يستحق العبادة غيره جل وعلا، فأخلصوا له العبادة، هو الذي بدأ خَلْقكم من الأرض بخلق أبيكم آدم منها، وجعلكم عُمَّارا لها، فاسألوه أن يغفر لكم ذنوبكم، وارجعوا إليه بالتوبة النصوح. إن ربي قريب لمن أخلص له العبادة، ورغب إليه في التوبة، مجيب له إذا دعاه.", "isBasmala": false, "translation_en": "And to Thamood, their brother Saleh. He said, \"O my people, worship God, you have no god other than Him. He initiated you from the earth, and settled you in it. So seek His forgiveness, and repent to Him. My Lord is Near and Responsive.\"", "translation_id": "Dan kepada Tsamud (Kami utus) saudara mereka Shaleh. Shaleh berkata: \"Hai kaumku, sembahlah Allah, sekali-kali tidak ada bagimu Tuhan selain Dia. Dia telah menciptakan kamu dari bumi (tanah) dan menjadikan kamu pemakmurnya, karena itu mohonlah ampunan-Nya, kemudian bertobatlah kepada-Nya, Sesungguhnya Tuhanku amat dekat (rahmat-Nya) lagi memperkenankan (doa hamba-Nya)\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 62, "text": "قَالُوا۟ یَـٰصَـٰلِحُ قَدۡ كُنتَ فِینَا مَرۡجُوࣰّا قَبۡلَ هَـٰذَاۤۖ أَتَنۡهَىٰنَاۤ أَن نَّعۡبُدَ مَا یَعۡبُدُ ءَابَاۤؤُنَا وَإِنَّنَا لَفِی شَكࣲّ مِّمَّا تَدۡعُونَاۤ إِلَیۡهِ مُرِیبࣲ ۝٦٢", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "قالت ثمود لنبيِّهم صالح: لقد كنا نرجو أن تكون فينا سيدًا مطاعًا قبل هذا القول الذي قلته لنا، أتنهانا أن نعبد الآلهة التي كان يعبدها آباؤنا؟ وإننا لفي شكٍّ مريب مِن دعوتك لنا إلى عبادة الله وحده.", "isBasmala": false, "translation_en": "They said, \"O Saleh, we had hopes in you before this. Are you trying to prevent us from worshiping what our parents worship? We are in serious doubt regarding what you are calling us to.\"", "translation_id": "Kaum Tsamud berkata: \"Hai Shaleh, sesungguhnya kamu sebelum ini adalah seorang di antara kami yang kami harapkan, apakah kamu melarang kami untuk menyembah apa yang disembah oleh bapak-bapak kami? dan sesungguhnya kami betul-betul dalam keraguan yang menggelisahkan terhadap agama yang kamu serukan kepada kami\".", "manzil": 3, "manzil_display": ""}], "229": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 63, "text": "قَالَ یَـٰقَوۡمِ أَرَءَیۡتُمۡ إِن كُنتُ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّی وَءَاتَىٰنِی مِنۡهُ رَحۡمَةࣰ فَمَن یَنصُرُنِی مِنَ ٱللَّهِ إِنۡ عَصَیۡتُهُۥۖ فَمَا تَزِیدُونَنِی غَیۡرَ تَخۡسِیرࣲ ۝٦٣", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "قال صالح لقومه: يا قوم أخبروني إن كنت على برهان من الله وآتاني منه النبوة والحكمة، فمن الذي يدفع عني عقاب الله تعالى إن عصيته فلم أبلِّغ الرسالة وأنصحْ لكم؟ فما تزيدونني غير تضليل وإبعاد عن الخير.", "isBasmala": false, "translation_en": "He said, \"O my people, have you considered? If I stand upon clear evidence from my Lord, and He has given me mercy from Him, who would protect me from God, if I disobeyed Him? You add nothing for me except loss.\"", "translation_id": "Shaleh berkata: \"Hai kaumku, bagaimana pikiranmu jika aku mempunyai bukti yang nyata dari Tuhanku dan diberi-Nya aku rahmat (kenabian) dari-Nya, maka siapakah yang akan menolong aku dari (azab) Allah jika aku mendurhakai-Nya. Sebab itu kamu tidak menambah apapun kepadaku selain daripada kerugian.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 64, "text": "وَیَـٰقَوۡمِ هَـٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَایَةࣰۖ فَذَرُوهَا تَأۡكُلۡ فِیۤ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوۤءࣲ فَیَأۡخُذَكُمۡ عَذَابࣱ قَرِیبࣱ ۝٦٤", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "ويا قوم هذه ناقة الله جعلها لكم حجة وعلامة تدلُّ على صدقي فيما أدعوكم إليه، فاتركوها تأكل في أرض الله فليس عليكم رزقها، ولا تمسُّوها بعَقْر، فإنكم إن فعلتم ذلك يأخذكم من الله عذاب قريب من عَقْرها.", "isBasmala": false, "translation_en": "\"O my people, this is the she-camel of God, a sign for you. Let her graze on God's land, and do not harm her, lest an imminent punishment overtakes you.\"", "translation_id": "Hai kaumku, inilah unta betina dari Allah, sebagai mukjizat (yang menunjukkan kebenaran) untukmu, sebab itu biarkanlah dia makan di bumi Allah, dan janganlah kamu mengganggunya dengan gangguan apapun yang akan menyebabkan kamu ditimpa azab yang dekat\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 65, "text": "فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا۟ فِی دَارِكُمۡ ثَلَـٰثَةَ أَیَّامࣲۖ ذَ ٰلِكَ وَعۡدٌ غَیۡرُ مَكۡذُوبࣲ ۝٦٥", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "فكذَّبوه ونحروا الناقة، فقال لهم صالح: استمتعوا بحياتكم في بلدكم ثلاثة أيام، فإن العذاب نازل بكم بعدها، وذلك وَعْدٌ من الله غير مكذوب، لا بد من وقوعه.", "isBasmala": false, "translation_en": "But they hamstrung her, and so He said, \"Enjoy yourselves in your homes for three days. This is a prophecy that is infallible.\"", "translation_id": "Mereka membunuh unta itu, maka berkata Shaleh: \"Bersukarialah kamu sekalian di rumahmu selama tiga hari, itu adalah janji yang tidak dapat didustakan\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 66, "text": "فَلَمَّا جَاۤءَ أَمۡرُنَا نَجَّیۡنَا صَـٰلِحࣰا وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَمِنۡ خِزۡیِ یَوۡمِىِٕذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِیُّ ٱلۡعَزِیزُ ۝٦٦", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "فلما جاء أمرنا بهلاك ثمود نجينا صالحًا والذين آمنوا معه من الهلاك برحمة منا، ونجيناهم من هوان ذلك اليوم وذلَّته. إن ربك -أيها الرسول- هو القوي العزيز، ومِن قوته وعزته أن أهلك الأمم الطاغية، ونجَّى الرسل وأتباعهم.", "isBasmala": false, "translation_en": "Then, when Our command came, We saved Saleh and those who believed with him, by a mercy from Us, from the disgrace of that day. Your Lord is the Strong, the Mighty.", "translation_id": "Maka tatkala datang azab Kami, Kami selamatkan Shaleh beserta orang-orang yang beriman bersama dia dengan rahmat dari Kami dan dari kehinaan di hari itu. Sesungguhnya Tuhanmu Dia-Lah yang Maha Kuat lagi Maha Perkasa.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 67, "text": "وَأَخَذَ ٱلَّذِینَ ظَلَمُوا۟ ٱلصَّیۡحَةُ فَأَصۡبَحُوا۟ فِی دِیَـٰرِهِمۡ جَـٰثِمِینَ ۝٦٧", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "وأخذت الصيحة القوية ثمود الظالمين، فأصبحوا في ديارهم موتى هامدين ساقطين على وجوههم لا حِرَاك لهم.", "isBasmala": false, "translation_en": "And the Scream struck those who transgressed, and they became motionless bodies in their homes.", "translation_id": "Dan satu suara keras yang mengguntur menimpa orang-orang yang zalim itu, lalu mereka mati bergelimpangan di rumahnya,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 68, "text": "كَأَن لَّمۡ یَغۡنَوۡا۟ فِیهَاۤۗ أَلَاۤ إِنَّ ثَمُودَا۟ كَفَرُوا۟ رَبَّهُمۡۗ أَلَا بُعۡدࣰا لِّثَمُودَ ۝٦٨", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "كأنهم في سرعة زوالهم وفنائهم لم يعيشوا فيها. ألا إن ثمود جحدوا بآيات ربهم وحججه. ألا بُعْدًا لثمود وطردًا لهم من رحمة الله، فما أشقاهم وأذلَّهم!!", "isBasmala": false, "translation_en": "As if they had never prospered therein. Indeed, Thamood rejected their Lord, so away with Thamood.", "translation_id": "seolah-olah mereka belum pernah berdiam di tempat itu. Ingatlah, sesungguhnya kaum Tsamud mengingkari Tuhan mereka. Ingatlah, kebinasaanlah bagi kaum Tsamud.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 69, "text": "وَلَقَدۡ جَاۤءَتۡ رُسُلُنَاۤ إِبۡرَ ٰهِیمَ بِٱلۡبُشۡرَىٰ قَالُوا۟ سَلَـٰمࣰاۖ قَالَ سَلَـٰمࣱۖ فَمَا لَبِثَ أَن جَاۤءَ بِعِجۡلٍ حَنِیذࣲ ۝٦٩", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "ولقد جاءت الملائكة إبراهيم يبشرونه هو وزوجته بإسحاق، ويعقوبَ بعده، فقالوا: سلامًا، قال ردًّا على تحيتهم: سلام، فذهب سريعًا وجاءهم بعجل سمين مشويٍّ ليأكلوا منه.", "isBasmala": false, "translation_en": "Our messengers came to Abraham with good news. They said, \"Peace.\" He said, \"Peace.\" Soon after, he came with a roasted calf.", "translation_id": "Dan sesungguhnya utusan-utusan Kami (malaikat-malaikat) telah datang kepada lbrahim dengan membawa kabar gembira, mereka mengucapkan: \"Selamat\". Ibrahim menjawab: \"Selamatlah,\" maka tidak lama kemudian Ibrahim menyuguhkan daging anak sapi yang dipanggang.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 70, "text": "فَلَمَّا رَءَاۤ أَیۡدِیَهُمۡ لَا تَصِلُ إِلَیۡهِ نَكِرَهُمۡ وَأَوۡجَسَ مِنۡهُمۡ خِیفَةࣰۚ قَالُوا۟ لَا تَخَفۡ إِنَّاۤ أُرۡسِلۡنَاۤ إِلَىٰ قَوۡمِ لُوطࣲ ۝٧٠", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "فلما رأى إبراهيم أيديهم لا تَصِل إلى العجل الذي أتاهم به ولا يأكلون منه، أنكر ذلك منهم، وأحس في نفسه خيفة وأضمرها، قالت الملائكة -لما رأت ما بإبراهيم من الخوف-: لا تَخَفْ إنا ملائكة ربك أُرسلنا إلى قوم لوط لإهلاكهم.", "isBasmala": false, "translation_en": "But when he saw their hands not reaching towards it, he became suspicious of them, and conceived a fear of them. They said, \"Do not fear, we were sent to the people of Lot.\"", "translation_id": "Maka tatkala dilihatnya tangan mereka tidak menjamahnya, Ibrahim memandang aneh perbuatan mereka, dan merasa takut kepada mereka. Malaikat itu berkata: \"Jangan kamu takut, sesungguhnya kami adalah (malaikat-ma]aikat) yang diutus kepada kaum Luth\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 71, "text": "وَٱمۡرَأَتُهُۥ قَاۤىِٕمَةࣱ فَضَحِكَتۡ فَبَشَّرۡنَـٰهَا بِإِسۡحَـٰقَ وَمِن وَرَاۤءِ إِسۡحَـٰقَ یَعۡقُوبَ ۝٧١", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "وامرأة إبراهيم -سارة- كانت قائمة من وراء الستر تسمع الكلام، فضحكت تعجبًا مما سمعت، فبشرناها على ألسنة الملائكة بأنها ستلد مِن زوجها إبراهيم ولدًا يسمى إسحاق، وسيعيش ولدها، وسيكون لها بعد إسحاق حفيد منه، وهو يعقوب.", "isBasmala": false, "translation_en": "His wife was standing by, so she laughed. And We gave her good news of Isaac; and after Isaac, Jacob.", "translation_id": "Dan isterinya berdiri (dibalik tirai) lalu dia tersenyum, maka Kami sampaikan kepadanya berita gembira tentang (kelahiran) Ishak dan dari Ishak (akan lahir puteranya) Ya'qub.", "manzil": 3, "manzil_display": ""}], "230": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 72, "text": "قَالَتۡ یَـٰوَیۡلَتَىٰۤ ءَأَلِدُ وَأَنَا۠ عَجُوزࣱ وَهَـٰذَا بَعۡلِی شَیۡخًاۖ إِنَّ هَـٰذَا لَشَیۡءٌ عَجِیبࣱ ۝٧٢", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "قالت سارة لما بُشِّرت بإسحاق متعجبة: يا ويلتا كيف يكون لي ولد وأنا عجوز، وهذا زوجي في حال الشيخوخة والكبر؟ إن إنجاب الولد مِن مثلي ومثل زوجي مع كبر السن لَشيء عجيب.", "isBasmala": false, "translation_en": "She said, \"Alas for me. Shall I give birth, when I am an old woman, and this, my husband, is an old man? This is truly a strange thing.\"", "translation_id": "Isterinya berkata: \"Sungguh mengherankan, apakah aku akan melahirkan anak padahal aku adalah seorang perempuan tua, dan ini suamikupun dalam keadaan yang sudah tua pula?. Sesungguhnya ini benar-benar suatu yang sangat aneh\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 73, "text": "قَالُوۤا۟ أَتَعۡجَبِینَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَـٰتُهُۥ عَلَیۡكُمۡ أَهۡلَ ٱلۡبَیۡتِۚ إِنَّهُۥ حَمِیدࣱ مَّجِیدࣱ ۝٧٣", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "قالت الرسل لها: أتعجبين من أمر الله وقضائه؟ رحمة الله وبركاته عليكم معشر أهل بيت النبوة. إنه سبحانه وتعالى حميد الصفات والأفعال، ذو مَجْد وعظمة فيها.", "isBasmala": false, "translation_en": "They said, \"Do you marvel at the decree of God? The mercy and blessings of God are upon you, O people of the house. He is Praiseworthy and Glorious.\"", "translation_id": "Para malaikat itu berkata: \"Apakah kamu merasa heran tentang ketetapan Allah? (Itu adalah) rahmat Allah dan keberkatan-Nya, dicurahkan atas kamu, hai ahlulbait! Sesungguhnya Allah Maha Terpuji lagi Maha Pemurah\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 74, "text": "فَلَمَّا ذَهَبَ عَنۡ إِبۡرَ ٰهِیمَ ٱلرَّوۡعُ وَجَاۤءَتۡهُ ٱلۡبُشۡرَىٰ یُجَـٰدِلُنَا فِی قَوۡمِ لُوطٍ ۝٧٤", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "فلما ذهب عن إبراهيم الخوف الذي انتابه لعدم أكل الضيوف الطعام، وجاءته البشرى بإسحاق ويعقوب، ظلَّ يجادل رسلنا فيما أرسلناهم به من عقاب قوم لوط وإهلاكهم.", "isBasmala": false, "translation_en": "When Abraham's fear subsided, and the good news had reached him, he started pleading with Us concerning the people of Lot.", "translation_id": "Maka tatkala rasa takut hilang dari Ibrahim dan berita gembira telah datang kepadanya, diapun bersoal jawab dengan (malaikat-malaikat) Kami tentang kaum Luth.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 75, "text": "إِنَّ إِبۡرَ ٰهِیمَ لَحَلِیمٌ أَوَّ ٰهࣱ مُّنِیبࣱ ۝٧٥", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "إن إبراهيم كثير الحلم لا يحب المعاجلة بالعقاب، كثير التضرع إلى الله والدعاء له، تائب يرجع إلى الله في أموره كلها.", "isBasmala": false, "translation_en": "Abraham was gentle, kind, penitent.", "translation_id": "Sesungguhnya Ibrahim itu benar-benar seorang yang penyantun lagi penghiba dan suka kembali kepada Allah.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 76, "text": "یَـٰۤإِبۡرَ ٰهِیمُ أَعۡرِضۡ عَنۡ هَـٰذَاۤۖ إِنَّهُۥ قَدۡ جَاۤءَ أَمۡرُ رَبِّكَۖ وَإِنَّهُمۡ ءَاتِیهِمۡ عَذَابٌ غَیۡرُ مَرۡدُودࣲ ۝٧٦", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "قالت رسل الله: يا إبراهيم أعرض عن هذا الجدال في أمر قوم لوط والتماس الرحمة لهم؛ فإنه قد حق عليهم العذاب، وجاء أمر ربك الذي قدَّره عليهم بهلاكهم، وإنهم نازل بهم عذاب من الله غير مصروف عنهم ولا مدفوع.", "isBasmala": false, "translation_en": "\"O Abraham, refrain from this. The command of your Lord has come; they have incurred an irreversible punishment.\"", "translation_id": "Hai Ibrahim, tinggalkanlah soal jawab ini, sesungguhnya telah datang ketetapan Tuhanmu, dan sesungguhnya mereka itu akan didatangi azab yang tidak dapat ditolak.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 77, "text": "وَلَمَّا جَاۤءَتۡ رُسُلُنَا لُوطࣰا سِیۤءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعࣰا وَقَالَ هَـٰذَا یَوۡمٌ عَصِیبࣱ ۝٧٧", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "ولما جاءت ملائكتنا لوطًا ساءه مجيئهم واغتمَّ لذلك؛ وذلك لأنه لم يكن يعلم أنهم رسل الله، فخاف عليهم من قومه، وقال: هذا يوم بلاء وشدة.", "isBasmala": false, "translation_en": "And when Our envoys came to Lot, he was anxious for them, and concerned for them. He said, \"This is a dreadful day.\"", "translation_id": "Dan tatkala datang utusan-utusan Kami (para malaikat) itu kepada Luth, dia merasa susah dan merasa sempit dadanya karena kedatangan mereka, dan dia berkata: \"Ini adalah hari yang amat sulit\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 78, "text": "وَجَاۤءَهُۥ قَوۡمُهُۥ یُهۡرَعُونَ إِلَیۡهِ وَمِن قَبۡلُ كَانُوا۟ یَعۡمَلُونَ ٱلسَّیِّـَٔاتِۚ قَالَ یَـٰقَوۡمِ هَـٰۤؤُلَاۤءِ بَنَاتِی هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخۡزُونِ فِی ضَیۡفِیۤۖ أَلَیۡسَ مِنكُمۡ رَجُلࣱ رَّشِیدࣱ ۝٧٨", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "وجاء قومُ لوط يسرعون المشي إليه لطلب الفاحشة، وكانوا مِن قبل مجيئهم يأتون الرجال شهوة دون النساء، فقال لوط لقومه: هؤلاء بناتي تَزَوَّجوهن فهنَّ أطهر لكم مما تريدون، وسماهن بناته؛ لأن نبي الأمة بمنزلة الأب لهم، فاخشوا الله واحذروا عقابه، ولا تفضحوني بالاعتداء على ضيفي، أليس منكم رجل ذو رشد، ينهى من أراد ركوب الفاحشة، فيحول بينهم وبين ذلك؟", "isBasmala": false, "translation_en": "And his people came rushing towards him-they were in the habit of committing sins. He said, \"O my people, these are my daughters; they are purer for you. So fear God, and do not embarrass me before my guests. Is there not one reasonable man among you?\"", "translation_id": "Dan datanglah kepadanya kaumnya dengan bergegas-gegas. Dan sejak dahulu mereka selalu melakukan perbuatan-perbuatan yang keji. Luth berkata: \"Hai kaumku, inilah puteri-puteriku, mereka lebih suci bagimu, maka bertakwalah kepada Allah dan janganlah kamu mencemarkan (nama)ku terhadap tamuku ini. Tidak adakah di antaramu seorang yang berakal?\"", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 79, "text": "قَالُوا۟ لَقَدۡ عَلِمۡتَ مَا لَنَا فِی بَنَاتِكَ مِنۡ حَقࣲّ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِیدُ ۝٧٩", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "قال قوم لوط له: لقد علمتَ من قبلُ أنه ليس لنا في النساء من حاجة أو رغبة، وإنك لتعلم ما نريد، أي لا نريد إلا الرجال ولا رغبة لنا في نكاح النساء.", "isBasmala": false, "translation_en": "They said, \"You know well that we have no right to your daughters, and you know well what we want.\"", "translation_id": "Mereka menjawab: \"Sesungguhnya kamu telah tahu bahwa kami tidak mempunyai keinginan terhadap puteri-puterimu; dan sesungguhnya kamu tentu mengetahui apa yang sebenarnya kami kehendaki\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 80, "text": "قَالَ لَوۡ أَنَّ لِی بِكُمۡ قُوَّةً أَوۡ ءَاوِیۤ إِلَىٰ رُكۡنࣲ شَدِیدࣲ ۝٨٠", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "قال لهم حين أبوا إلا فعل الفاحشة: لو أن لي بكم قوة وأنصارًا معي، أو أركَن إلى عشيرة تمنعني منكم، لَحُلْتُ بينكم وبين ما تريدون.", "isBasmala": false, "translation_en": "He said, \"If only I had the strength to stop you, or could rely on some strong support.\"", "translation_id": "Luth berkata: \"Seandainya aku ada mempunyai kekuatan (untuk menolakmu) atau kalau aku dapat berlindung kepada keluarga yang kuat (tentu aku lakukan)\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 81, "text": "قَالُوا۟ یَـٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن یَصِلُوۤا۟ إِلَیۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعࣲ مِّنَ ٱلَّیۡلِ وَلَا یَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِیبُهَا مَاۤ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَیۡسَ ٱلصُّبۡحُ بِقَرِیبࣲ ۝٨١", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "قالت الملائكة: يا لوط إنَّا رسل ربك أَرْسَلَنا لإهلاك قومك، وإنهم لن يصلوا إليك، فاخرج من هذه القرية أنت وأهلك ببقية من الليل، ولا يلتفت منكم أحد وراءه؛ لئلا يرى العذاب فيصيبه، لكنَّ امرأتك التي خانتك بالكفر والنفاق سيصيبها ما أصاب قومك من الهلاك، إن موعد هلاكهم الصبح، وهو موعد قريب الحلول.", "isBasmala": false, "translation_en": "They said, \"O Lot, we are the envoys of your Lord; they will not reach you. So set out with your family during the cover of the night, and let none of you look back, except for your wife. She will be struck by what will strike them. Their appointed time is the morning. Is not the morning near?\"", "translation_id": "Para utusan (malaikat) berkata: \"Hai Luth, sesungguhnya kami adalah utusan-utusan Tuhanmu, sekali-kali mereka tidak akan dapat mengganggu kamu, sebab itu pergilah dengan membawa keluarga dan pengikut-pengikut kamu di akhir malam dan janganlah ada seorangpun di antara kamu yang tertinggal, kecuali isterimu. Sesungguhnya dia akan ditimpa azab yang menimpa mereka karena sesungguhnya saat jatuhnya azab kepada mereka ialah di waktu subuh; bukankah subuh itu sudah dekat?\".", "manzil": 3, "manzil_display": ""}], "231": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 82, "text": "فَلَمَّا جَاۤءَ أَمۡرُنَا جَعَلۡنَا عَـٰلِیَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَیۡهَا حِجَارَةࣰ مِّن سِجِّیلࣲ مَّنضُودࣲ ۝٨٢", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "فلما جاء أمرنا بنزول العذاب بهم جعلنا عالي قريتهم التي كانوا يعيشون فيها سافلها فقلبناها، وأمطرنا عليهم حجارة من طين متصلِّب متين، قد صُفَّ بعضها إلى بعض متتابعة، معلَّمة عند الله بعلامة معروفة لا تشاكِل حجارة الأرض، وما هذه الحجارة التي أمطرها الله على قوم لوط من كفار قريش ببعيد أن يُمْطَروا بمثلها. وفي هذا تهديد لكل عاص متمرِّد على الله.", "isBasmala": false, "translation_en": "And when Our command came about, We turned it upside down, and We rained down on it stones of baked clay.", "translation_id": "Maka tatkala datang azab Kami, Kami jadikan negeri kaum Luth itu yang di atas ke bawah (Kami balikkan), dan Kami hujani mereka dengan batu dari tanah yang terbakar dengan bertubi-tubi,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 83, "text": "مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِیَ مِنَ ٱلظَّـٰلِمِینَ بِبَعِیدࣲ ۝٨٣", "juz": 12, "hizb": "(*¾ ح 23*)", "tafsir": "فلما جاء أمرنا بنزول العذاب بهم جعلنا عالي قريتهم التي كانوا يعيشون فيها سافلها فقلبناها، وأمطرنا عليهم حجارة من طين متصلِّب متين، قد صُفَّ بعضها إلى بعض متتابعة، معلَّمة عند الله بعلامة معروفة لا تشاكِل حجارة الأرض، وما هذه الحجارة التي أمطرها الله على قوم لوط من كفار قريش ببعيد أن يُمْطَروا بمثلها. وفي هذا تهديد لكل عاص متمرِّد على الله.", "isBasmala": false, "translation_en": "Marked from your Lord, and never far from the wrongdoers.", "translation_id": "Yang diberi tanda oleh Tuhanmu, dan siksaan itu tiadalah jauh dari orang-orang yang zalim.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 84, "text": "۞ وَإِلَىٰ مَدۡیَنَ أَخَاهُمۡ شُعَیۡبࣰاۚ قَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۖ وَلَا تَنقُصُوا۟ ٱلۡمِكۡیَالَ وَٱلۡمِیزَانَۖ إِنِّیۤ أَرَىٰكُم بِخَیۡرࣲ وَإِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمࣲ مُّحِیطࣲ ۝٨٤", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "وأرسلنا إلى \"مدين\" أخاهم شعيبًا، فقال: يا قوم اعبدوا الله وحده، ليس لكم مِن إله يستحق العبادة غيره جل وعلا، فأخلصوا له العبادة، ولا تنقصوا الناس حقوقهم في مكاييلهم وموازينهم، إني أراكم في سَعَة عيش، وإني أخاف عليكم -بسبب إنقاص المكيال والميزان- عذاب يوم يحيط بكم.", "isBasmala": false, "translation_en": "And to Median, their brother Shuaib. He said, \"O my people, worship God; you have no god other than Him. And do not short measure or short weight. I see you in good circumstances, but I fear for you the agony of an encompassing Day.\"", "translation_id": "Dan kepada (penduduk) Mad-yan (Kami utus) saudara mereka, Syu'aib. Ia berkata: \"Hai kaumku, sembahlah Allah, sekali-kali tiada Tuhan bagimu selain Dia. Dan janganlah kamu kurangi takaran dan timbangan, sesungguhnya aku melihat kamu dalam keadaan yang baik (mampu) dan sesungguhnya aku khawatir terhadapmu akan azab hari yang membinasakan (kiamat)\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 85, "text": "وَیَـٰقَوۡمِ أَوۡفُوا۟ ٱلۡمِكۡیَالَ وَٱلۡمِیزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُوا۟ ٱلنَّاسَ أَشۡیَاۤءَهُمۡ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ ۝٨٥", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "ويا قوم أتمُّوا المكيال والميزان بالعدل، ولا تُنْقِصوا الناس حقهم في عموم أشيائهم، ولا تسيروا في الأرض تعملون فيها بمعاصي الله ونشر الفساد.", "isBasmala": false, "translation_en": "\"O my people! Give full measure and full weight, in all fairness, and do not cheat the people out of their rights, and do not spread corruption in the land.", "translation_id": "Dan Syu'aib berkata: \"Hai kaumku, cukupkanlah takaran dan timbangan dengan adil, dan janganlah kamu merugikan manusia terhadap hak-hak mereka dan janganlah kamu membuat kejahatan di muka bumi dengan membuat kerusakan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 86, "text": "بَقِیَّتُ ٱللَّهِ خَیۡرࣱ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِینَۚ وَمَاۤ أَنَا۠ عَلَیۡكُم بِحَفِیظࣲ ۝٨٦", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "إن ما يبقى لكم بعد إيفاء الكيل والميزان من الربح الحلال خير لكم ممَّا تأخذونه بالتطفيف ونحوه من الكسب الحرام، إن كنتم تؤمنون بالله حقا، فامتثلوا أمره، وما أنا عليكم برقيب أحصي عليكم أعمالكم.", "isBasmala": false, "translation_en": "What is left by God is best for you, if you are believers. And I am not a guardian over you.\"", "translation_id": "Sisa (keuntungan) dari Allah adalah lebih baik bagimu jika kamu orang-orang yang beriman. Dan aku bukanlah seorang penjaga atas dirimu\"", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 87, "text": "قَالُوا۟ یَـٰشُعَیۡبُ أَصَلَوٰتُكَ تَأۡمُرُكَ أَن نَّتۡرُكَ مَا یَعۡبُدُ ءَابَاۤؤُنَاۤ أَوۡ أَن نَّفۡعَلَ فِیۤ أَمۡوَ ٰلِنَا مَا نَشَـٰۤؤُا۟ۖ إِنَّكَ لَأَنتَ ٱلۡحَلِیمُ ٱلرَّشِیدُ ۝٨٧", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "قالوا: يا شعيب أهذه الصلاة التي تداوم عليها تأمرك بأن نترك ما يعبده آباؤنا من الأصنام والأوثان، أو أن نمتنع عن التصرف في كسب أموالنا بما نستطيع من احتيال ومكر؟ وقالوا -استهزاءً به-: إنك لأنت الحليم الرشيد.", "isBasmala": false, "translation_en": "They said, \"O Shuaib, does your prayer command you that we abandon what our ancestors worshiped, or doing with our wealth what we want? You are the one who is intelligent and wise.\"", "translation_id": "Mereka berkata: \"Hai Syu'aib, apakah sembahyangmu menyuruh kamu agar kami meninggalkan apa yang disembah oleh bapak-bapak kami atau melarang kami memperbuat apa yang kami kehendaki tentang harta kami. Sesungguhnya kamu adalah orang yang sangat penyantun lagi berakal\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 88, "text": "قَالَ یَـٰقَوۡمِ أَرَءَیۡتُمۡ إِن كُنتُ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّی وَرَزَقَنِی مِنۡهُ رِزۡقًا حَسَنࣰاۚ وَمَاۤ أُرِیدُ أَنۡ أُخَالِفَكُمۡ إِلَىٰ مَاۤ أَنۡهَىٰكُمۡ عَنۡهُۚ إِنۡ أُرِیدُ إِلَّا ٱلۡإِصۡلَـٰحَ مَا ٱسۡتَطَعۡتُۚ وَمَا تَوۡفِیقِیۤ إِلَّا بِٱللَّهِۚ عَلَیۡهِ تَوَكَّلۡتُ وَإِلَیۡهِ أُنِیبُ ۝٨٨", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "قال شعيب: يا قوم أرأيتم إن كنت على طريق واضح من ربي فيما أدعوكم إليه من إخلاص العبادة له، وفيما أنهاكم عنه من إفساد المال، ورزقني منه رزقًا واسعًا حلالا طيبًا؟ وما أريد أن أخالفكم فأرتكب أمرًا نهيتكم عنه، وما أريد فيما آمركم به وأنهاكم عنه إلا إصلاحكم قَدْر طاقتي واستطاعتي، وما توفيقي -في إصابة الحق ومحاولة إصلاحكم- إلا بالله، على الله وحده توكلت وإليه أرجع بالتوبة والإنابة.", "isBasmala": false, "translation_en": "He said, \"O my people, have you considered? What if I have clear evidence from my Lord, and He has given me good livelihood from Himself? I have no desire to do what I forbid you from doing. I desire nothing but reform, as far as I can. My success lies only with God. In Him I trust, and to Him I turn.\"", "translation_id": "Syu'aib berkata: \"Hai kaumku, bagaimana pikiranmu jika aku mempunyai bukti yang nyata dari Tuhanku dan dianugerahi-Nya aku dari pada-Nya rezeki yang baik (patutkah aku menyalahi perintah-Nya)? Dan aku tidak berkehendak menyalahi kamu (dengan mengerjakan) apa yang aku larang. Aku tidak bermaksud kecuali (mendatangkan) perbaikan selama aku masih berkesanggupan. Dan tidak ada taufik bagiku melainkan dengan (pertolongan) Allah. Hanya kepada Allah aku bertawakkal dan hanya kepada-Nya-lah aku kembali.", "manzil": 3, "manzil_display": ""}], "232": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 89, "text": "وَیَـٰقَوۡمِ لَا یَجۡرِمَنَّكُمۡ شِقَاقِیۤ أَن یُصِیبَكُم مِّثۡلُ مَاۤ أَصَابَ قَوۡمَ نُوحٍ أَوۡ قَوۡمَ هُودٍ أَوۡ قَوۡمَ صَـٰلِحࣲۚ وَمَا قَوۡمُ لُوطࣲ مِّنكُم بِبَعِیدࣲ ۝٨٩", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "ويا قوم لا تحملنَّكم عداوتي وبغضي وفراق الدين الذي أنا عليه على العناد والإصرار على ما أنتم عليه من الكفر بالله، فيصيبكم مثلُ ما أصاب قوم نوح أو قوم هود أو قوم صالح من الهلاك، وما قوم لوط وما حلَّ بهم من العذاب ببعيدين عنكم لا في الدار ولا في الزمان.", "isBasmala": false, "translation_en": "\"O my people, let not your hostility towards me cause you to suffer what was suffered by the people of Noah, or the people of Hud, or the people of Saleh. The people of Lot are not far away from you.\"", "translation_id": "Hai kaumku, janganlah hendaknya pertentangan antara aku (dengan kamu) menyebabkan kamu menjadi jahat hingga kamu ditimpa azab seperti yang menimpa kaum Nuh atau kaum Hud atau kaum Shaleh, sedang kaum Luth tidak (pula) jauh (tempatnya) dari kamu.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 90, "text": "وَٱسۡتَغۡفِرُوا۟ رَبَّكُمۡ ثُمَّ تُوبُوۤا۟ إِلَیۡهِۚ إِنَّ رَبِّی رَحِیمࣱ وَدُودࣱ ۝٩٠", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "واطلبوا من ربِّكم المغفرة لذنوبكم، ثم ارجعوا إلى طاعته واستمروا عليها. إن ربِّي رحيم كثير المودة والمحبة لمن تاب إليه وأناب، يرحمه ويقبل توبته. وفي الآية إثبات صفة الرحمة والمودة لله تعالى، كما يليق به سبحانه.", "isBasmala": false, "translation_en": "\"And ask your Lord for forgiveness, and repent to Him. My Lord is Merciful and Loving.\"", "translation_id": "Dan mohonlah ampun kepada Tuhanmu kemudian bertaubatlah kepada-Nya. Sesungguhnya Tuhanku Maha Penyayang lagi Maha Pengasih.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 91, "text": "قَالُوا۟ یَـٰشُعَیۡبُ مَا نَفۡقَهُ كَثِیرࣰا مِّمَّا تَقُولُ وَإِنَّا لَنَرَىٰكَ فِینَا ضَعِیفࣰاۖ وَلَوۡلَا رَهۡطُكَ لَرَجَمۡنَـٰكَۖ وَمَاۤ أَنتَ عَلَیۡنَا بِعَزِیزࣲ ۝٩١", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "قالوا: يا شعيب ما نفقه كثيرًا مما تقول، وإننا لَنراك فينا ضعيفًا لست من الكبراء ولا من الرؤساء، ولولا مراعاة عشيرتك لقتلناك رَجْما بالحجارة -وكان رهطه من أهل ملتهم-، وليس لك قَدْر واحترام في نفوسنا.", "isBasmala": false, "translation_en": "They said, \"O Shuaib, we do not understand much of what you say, and we see that you are weak among us. Were it not for your tribe, we would have stoned you. You are of no value to us.\"", "translation_id": "Mereka berkata: \"Hai Syu'aib, kami tidak banyak mengerti tentang apa yang kamu katakan itu dan sesungguhnya kami benar-benar melihat kamu seorang yang lemah di antara kami; kalau tidaklah karena keluargamu tentulah kami telah merajam kamu, sedang kamupun bukanlah seorang yang berwibawa di sisi kami\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 92, "text": "قَالَ یَـٰقَوۡمِ أَرَهۡطِیۤ أَعَزُّ عَلَیۡكُم مِّنَ ٱللَّهِ وَٱتَّخَذۡتُمُوهُ وَرَاۤءَكُمۡ ظِهۡرِیًّاۖ إِنَّ رَبِّی بِمَا تَعۡمَلُونَ مُحِیطࣱ ۝٩٢", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "قال: يا قوم أعشيرتي أعزُّ وأكرم عليكم من الله؟ ونبذتم أمر ربكم فجعلتموه خلف ظهوركم، لا تأتمرون به ولا تنتهون بنهيه، إن ربي بما تعملون محيط، لا يخفى عليه من أعمالكم مثقال ذرة، وسيجازيكم عليها عاجلا وآجلا.", "isBasmala": false, "translation_en": "He said, \"O my people, is my tribe more important to you than God? And you have turned your backs on Him? My Lord comprehends everything you do.\"", "translation_id": "Syu'aib menjawab: \"Hai kaumku, apakah keluargaku lebih terhormat menurut pandanganmu daripada Allah, sedang Allah kamu jadikan sesuatu yang terbuang di belakangmu?. Sesungguhnya (pengetahuan) Tuhanku meliputi apa yang kamu kerjakan\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 93, "text": "وَیَـٰقَوۡمِ ٱعۡمَلُوا۟ عَلَىٰ مَكَانَتِكُمۡ إِنِّی عَـٰمِلࣱۖ سَوۡفَ تَعۡلَمُونَ مَن یَأۡتِیهِ عَذَابࣱ یُخۡزِیهِ وَمَنۡ هُوَ كَـٰذِبࣱۖ وَٱرۡتَقِبُوۤا۟ إِنِّی مَعَكُمۡ رَقِیبࣱ ۝٩٣", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "ويا قوم اعملوا كل ما تستطيعون على طريقتكم وحالتكم، إني عامل مثابر على طريقتي وما وهبني ربي مِن دعوتكم إلى التوحيد، سوف تعلمون مَن منا يأتيه عذاب يذلُّه، ومَن منا كاذب في قوله، أنا أم أنتم؟ وانتظروا ما سيحل بكم إني معكم من المنتظرين. وهذا تهديد شديد لهم.", "isBasmala": false, "translation_en": "\"O my people, do as you may, and so will I. You will know to whom will come a punishment that will shame him, and who is a liar. So look out; I am on the lookout with you.\"", "translation_id": "Dan (dia berkata): \"Hai kaumku, berbuatlah menurut kemampuanmu, sesungguhnya akupun berbuat (pula). Kelak kamu akan mengetahui siapa yang akan ditimpa azab yang menghinakannya dan siapa yang berdusta. Dan tunggulah azab (Tuhan), sesungguhnya akupun menunggu bersama kamu\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 94, "text": "وَلَمَّا جَاۤءَ أَمۡرُنَا نَجَّیۡنَا شُعَیۡبࣰا وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ بِرَحۡمَةࣲ مِّنَّا وَأَخَذَتِ ٱلَّذِینَ ظَلَمُوا۟ ٱلصَّیۡحَةُ فَأَصۡبَحُوا۟ فِی دِیَـٰرِهِمۡ جَـٰثِمِینَ ۝٩٤", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "ولما جاء أمرنا بإهلاك قوم شعيب نجَّينا رسولنا شعيبًا والذين آمنوا معه برحمة منا، وأخذت الذين ظلموا الصيحة من السماء، فأهلكتهم، فأصبحوا في ديارهم باركين على رُكَبهم ميتين لا حِرَاك بهم.", "isBasmala": false, "translation_en": "And when Our command came, We saved Shuaib and those who believed with him, by mercy from Us, and the Blast struck the wrongdoers, and they became motionless bodies in their homes.", "translation_id": "Dan tatkala datang azab Kami, Kami selamatkan Syu'aib dan orang-orang yang beriman bersama-sama dengan dia dengan rahmat dari Kami, dan orang-orang yang zalim dibinasakan oleh satu suara yang mengguntur, lalu jadilah mereka mati bergelimpangan di rumahnya.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 95, "text": "كَأَن لَّمۡ یَغۡنَوۡا۟ فِیهَاۤۗ أَلَا بُعۡدࣰا لِّمَدۡیَنَ كَمَا بَعِدَتۡ ثَمُودُ ۝٩٥", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "كأن لم يقيموا في ديارهم وقتًا من الأوقات. ألا بُعدًا لـ \"مدين\" -إذ أهلكها الله وأخزاها- كما بَعِدت ثمود، فقد اشتركت هاتان القبيلتان في البعد والهلاك.", "isBasmala": false, "translation_en": "As though they never flourished therein. Away with Median, as was done away with Thamood.", "translation_id": "Seolah-olah mereka belum pernah berdiam di tempat itu. Ingatlah, kebinasaanlah bagi penduduk Mad-yan sebagaimana kaum Tsamud telah binasa.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 96, "text": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔایَـٰتِنَا وَسُلۡطَـٰنࣲ مُّبِینٍ ۝٩٦", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "ولقد أرسلنا موسى بأدلتنا على توحيدنا وحجة تبين لمن عاينها وتأملها -بقلب صحيح- أنها تدل على وحدانية الله، وكَذِبِ كلِّ من ادَّعى الربوبية دونه سبحانه وتعالى.", "isBasmala": false, "translation_en": "And We sent Moses with Our signs and a clear mandate.", "translation_id": "Dan sesungguhnya Kami telah mengutus Musa dengan tanda-tanda (kekuasaan) Kami dan mukjizat yang nyata,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 97, "text": "إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ فَٱتَّبَعُوۤا۟ أَمۡرَ فِرۡعَوۡنَۖ وَمَاۤ أَمۡرُ فِرۡعَوۡنَ بِرَشِیدࣲ ۝٩٧", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "أرسلنا موسى إلى فرعون وأكابر أتباعه وأشراف قومه، فكفر فرعون وأمر قومه أن يتبعوه، فأطاعوه، وخالفوا أمر موسى، وليس في أمر فرعون رشد ولا هدى، وإنما هو جهل وضلال وكفر وعناد.", "isBasmala": false, "translation_en": "To Pharaoh and his nobles, but they followed the command of Pharaoh, and the command of Pharaoh was not wise.", "translation_id": "kepada Fir'aun dan pemimpin-pemimpin kaumnya, tetapi mereka mengikut perintah Fir'aun, padahal perintah Fir'aun sekali-kali bukanlah (perintah) yang benar.", "manzil": 3, "manzil_display": ""}], "233": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 98, "text": "یَقۡدُمُ قَوۡمَهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ فَأَوۡرَدَهُمُ ٱلنَّارَۖ وَبِئۡسَ ٱلۡوِرۡدُ ٱلۡمَوۡرُودُ ۝٩٨", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "يَقْدُم فرعون قومه يوم القيامة حتى يدخلهم النار، وقبُح المدخل الذي يدخلونه.", "isBasmala": false, "translation_en": "He will precede his people on the Day of Resurrection, and will lead them into the Fire. Miserable is the place he placed them in.", "translation_id": "Ia berjalan di muka kaumnya di hari kiamat lalu memasukkan mereka ke dalam neraka. Neraka itu seburuk-buruk tempat yang didatangi.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 99, "text": "وَأُتۡبِعُوا۟ فِی هَـٰذِهِۦ لَعۡنَةࣰ وَیَوۡمَ ٱلۡقِیَـٰمَةِۚ بِئۡسَ ٱلرِّفۡدُ ٱلۡمَرۡفُودُ ۝٩٩", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "وأتبعهم الله في هذه الدنيا مع العذاب الذي عجَّله لهم فيها من الغرق في البحر لعنةً، ويوم القيامة كذلك لعنة أخرى بإدخالهم النار، وبئس ما اجتمع لهم وترادَف عليهم من عذاب الله، ولعنة الدنيا والآخرة.", "isBasmala": false, "translation_en": "They were followed by a curse in this, and on the Day of Resurrection. Miserable is the path they followed.", "translation_id": "Dan mereka selalu diikuti dengan kutukan di dunia ini dan (begitu pula) di hari kiamat. La'nat itu seburuk-buruk pemberian yang diberikan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 100, "text": "ذَ ٰلِكَ مِنۡ أَنۢبَاۤءِ ٱلۡقُرَىٰ نَقُصُّهُۥ عَلَیۡكَۖ مِنۡهَا قَاۤىِٕمࣱ وَحَصِیدࣱ ۝١٠٠", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "ذلك الذي ذكرناه لك -أيها الرسول- من أخبار القرى التي أهلكنا أهلها نخبرك به، ومن تلك القرى ما له آثار باقية، ومنها ما قد مُحِيَتْ آثاره، فلم يَبْق منه شيء.", "isBasmala": false, "translation_en": "These are of the reports of the towns-We relate them to you. Some are still standing, and some have withered away.", "translation_id": "Itu adalah sebahagian dan berita-berita negeri (yang telah dibinasakan) yang Kami ceritakan kepadamu (Muhammad); di antara negeri-negeri itu ada yang masih kedapatan bekas-bekasnya dan ada (pula) yang telah musnah.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 101, "text": "وَمَا ظَلَمۡنَـٰهُمۡ وَلَـٰكِن ظَلَمُوۤا۟ أَنفُسَهُمۡۖ فَمَاۤ أَغۡنَتۡ عَنۡهُمۡ ءَالِهَتُهُمُ ٱلَّتِی یَدۡعُونَ مِن دُونِ ٱللَّهِ مِن شَیۡءࣲ لَّمَّا جَاۤءَ أَمۡرُ رَبِّكَۖ وَمَا زَادُوهُمۡ غَیۡرَ تَتۡبِیبࣲ ۝١٠١", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "وما كان إهلاكهم بغير سبب وذنب يستحقونه، ولكن ظلموا أنفسهم بشركهم وإفسادهم في الأرض، فما نفعتهم آلهتهم التي كانوا يدعُونها ويطلبون منها أن تدفع عنهم الضر لـمَّا جاء أمر ربك بعذابهم، وما زادتهم آلهتهم غير تدمير وإهلاك وخسران.", "isBasmala": false, "translation_en": "We did not wrong them, but they wronged themselves. Their gods, whom they invoked besides God, availed them nothing when the command of your Lord arrived. In fact, they added only to their ruin.", "translation_id": "Dan Kami tidaklah menganiaya mereka tetapi merekalah yang menganiaya diri mereka sendiri, karena itu tiadalah bermanfaat sedikitpun kepada mereka sembahan-sembahan yang mereka seru selain Allah, di waktu azab Tuhanmu datang. Dan sembahan-sembahan itu tidaklah menambah kepada mereka kecuali kebinasaan belaka.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 102, "text": "وَكَذَ ٰلِكَ أَخۡذُ رَبِّكَ إِذَاۤ أَخَذَ ٱلۡقُرَىٰ وَهِیَ ظَـٰلِمَةٌۚ إِنَّ أَخۡذَهُۥۤ أَلِیمࣱ شَدِیدٌ ۝١٠٢", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "وكما أخذتُ أهل القرى الظالمة بالعذاب لمخالفتهم أمري وتكذيبهم برسلي، آخذ غيرهم مِن أهل القرى إذا ظلموا أنفسهم بكفرهم بالله ومعصيتهم له وتكذيبهم لرسله. إنَّ أَخْذه بالعقوبة لأليم موجع شديد.", "isBasmala": false, "translation_en": "Such is the grip of your Lord when He seizes the towns in the midst of their sins. His grip is most painful, most severe.", "translation_id": "Dan begitulah azab Tuhanmu, apabila Dia mengazab penduduk negeri-negeri yang berbuat zalim. Sesungguhnya azab-Nya itu adalah sangat pedih lagi keras.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 103, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّمَنۡ خَافَ عَذَابَ ٱلۡـَٔاخِرَةِۚ ذَ ٰلِكَ یَوۡمࣱ مَّجۡمُوعࣱ لَّهُ ٱلنَّاسُ وَذَ ٰلِكَ یَوۡمࣱ مَّشۡهُودࣱ ۝١٠٣", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "إن في أخذنا لأهل القرى السابقة الظالمة لعبرةً وعظة لمن خاف عقاب الله وعذابه في الآخرة، ذلك اليوم الذي يُجمع له الناس جميعًا للمحاسبة والجزاء، ويشهده الخلائق كلهم.", "isBasmala": false, "translation_en": "In that is a sign for whoever fears the punishment of the Hereafter. That is a Day for which humanity will be gathered together-that is a Day to be witnessed.", "translation_id": "Sesungguhnya pada yang demikian itu benar-benar terdapat pelajaran bagi orang-orang yang takut kepada azab akhirat. Hari kiamat itu adalah suatu hari yang semua manusia dikumpulkan untuk (menghadapi)nya, dan hari itu adalah suatu hari yang disaksikan (oleh segala makhluk).", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 104, "text": "وَمَا نُؤَخِّرُهُۥۤ إِلَّا لِأَجَلࣲ مَّعۡدُودࣲ ۝١٠٤", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "وما نؤخر يوم القيامة عنكم إلا لانتهاء مدة معدودة في علمنا، لا تزيد ولا تنقص عن تقديرنا لها بحكمتنا.", "isBasmala": false, "translation_en": "We only postpone it until a predetermined time.", "translation_id": "Dan Kami tiadalah mengundurkannya, melainkan sampai waktu yang tertentu.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 105, "text": "یَوۡمَ یَأۡتِ لَا تَكَلَّمُ نَفۡسٌ إِلَّا بِإِذۡنِهِۦۚ فَمِنۡهُمۡ شَقِیࣱّ وَسَعِیدࣱ ۝١٠٥", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "يوم يأتي يوم القيامة، لا تتكلم نفس إلا بإذن ربها، فمنهم شقي مستحق للعذاب، وسعيد متفضَّل عليه بالنعيم.", "isBasmala": false, "translation_en": "On the Day when it arrives, no soul will speak without His permission. Some will be miserable, and some will be happy.", "translation_id": "Di kala datang hari itu, tidak ada seorangun yang berbicara, melainkan dengan izin-Nya; maka di antara mereka ada yang celaka dan ada yang berbahagia.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 106, "text": "فَأَمَّا ٱلَّذِینَ شَقُوا۟ فَفِی ٱلنَّارِ لَهُمۡ فِیهَا زَفِیرࣱ وَشَهِیقٌ ۝١٠٦", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "فأما الذين شَقُوا في الدنيا لفساد عقيدتهم وسوء أعمالهم، فالنار مستقرهم، لهم فيها من شدة ما هم فيه من العذاب زفير وشهيق، وهما أشنع الأصوات وأقبحها، ماكثين في النار أبدًا ما دامت السموات والأرض، فلا ينقطع عذابهم ولا ينتهي، بل هو دائم مؤكَّد، إلا ما شاء ربك من إخراج عصاة الموحدين بعد مدَّة من مكثهم في النار. إن ربك -أيها الرسول- فعَّال لما يريد.", "isBasmala": false, "translation_en": "As for those who are miserable, they will be in the Fire. They will have therein sighing and wailing.", "translation_id": "Adapun orang-orang yang celaka, maka (tempatnya) di dalam neraka, di dalamnya mereka mengeluarkan dan menarik nafas (dengan merintih),", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 107, "text": "خَـٰلِدِینَ فِیهَا مَا دَامَتِ ٱلسَّمَـٰوَ ٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَاۤءَ رَبُّكَۚ إِنَّ رَبَّكَ فَعَّالࣱ لِّمَا یُرِیدُ ۝١٠٧", "juz": 12, "hizb": "(* ح 24*)", "tafsir": "فأما الذين شَقُوا في الدنيا لفساد عقيدتهم وسوء أعمالهم، فالنار مستقرهم، لهم فيها من شدة ما هم فيه من العذاب زفير وشهيق، وهما أشنع الأصوات وأقبحها، ماكثين في النار أبدًا ما دامت السموات والأرض، فلا ينقطع عذابهم ولا ينتهي، بل هو دائم مؤكَّد، إلا ما شاء ربك من إخراج عصاة الموحدين بعد مدَّة من مكثهم في النار. إن ربك -أيها الرسول- فعَّال لما يريد.", "isBasmala": false, "translation_en": "Remaining therein for as long as the heavens and the earth endure, except as your Lord wills. Your Lord is Doer of whatever He wills.", "translation_id": "mereka kekal di dalamnya selama ada langit dan bumi, kecuali jika Tuhanmu menghendaki (yang lain). Sesungguhnya Tuhanmu Maha Pelaksana terhadap apa yang Dia kehendaki.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 108, "text": "۞ وَأَمَّا ٱلَّذِینَ سُعِدُوا۟ فَفِی ٱلۡجَنَّةِ خَـٰلِدِینَ فِیهَا مَا دَامَتِ ٱلسَّمَـٰوَ ٰتُ وَٱلۡأَرۡضُ إِلَّا مَا شَاۤءَ رَبُّكَۖ عَطَاۤءً غَیۡرَ مَجۡذُوذࣲ ۝١٠٨", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "وأما الذين رزقهم الله السعادة فيدخلون الجنة خالدين فيها ما دامت السموات والأرض، إلا الفريق الذي شاء الله تأخيره، وهم عصاة الموحدين، فإنهم يبقون في النار فترة من الزمن، ثم يخرجون منها إلى الجنة بمشيئة الله ورحمته، ويعطي ربك هؤلاء السعداء في الجنة عطاء غير مقطوع عنهم.", "isBasmala": false, "translation_en": "And as for those who are happy, they will be in Paradise, remaining therein for as long as the heavens and the earth endure, except as your Lord wills-a reward without end.", "translation_id": "Adapun orang-orang yang berbahagia, maka tempatnya di dalam surga, mereka kekal di dalamnya selama ada langit dan bumi, kecuali jika Tuhanmu menghendaki (yang lain); sebagai karunia yang tiada putus-putusnya.", "manzil": 3, "manzil_display": ""}], "234": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 109, "text": "فَلَا تَكُ فِی مِرۡیَةࣲ مِّمَّا یَعۡبُدُ هَـٰۤؤُلَاۤءِۚ مَا یَعۡبُدُونَ إِلَّا كَمَا یَعۡبُدُ ءَابَاۤؤُهُم مِّن قَبۡلُۚ وَإِنَّا لَمُوَفُّوهُمۡ نَصِیبَهُمۡ غَیۡرَ مَنقُوصࣲ ۝١٠٩", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "فلا تكن -أيها الرسول- في شك من بطلان ما يعبد هؤلاء المشركون من قومك، ما يعبدون من الأوثان إلا مثل ما يعبد آباؤهم من قبل، وإنا لموفوهم ما وعدناهم تاما غير منقوص. وهذا توجيه لجميع الأمة، وإن كان لفظه موجهًا إلى الرسول صلى الله عليه وسلَّم.", "isBasmala": false, "translation_en": "So be not in doubt regarding what these people worship. They worship only as their ancestors worshiped before. We will pay them their due in full, without any reduction.", "translation_id": "Maka janganlah kamu berada dalam keragu-raguan tentang apa yang disembah oleh mereka. Mereka tidak menyembah melainkan sebagaimana nenek moyang mereka menyembah dahulu. Dan sesungguhnya Kami pasti akan menyempurnakan dengan secukup-cukupnya pembalasan (terhadap) mereka dengan tidak dikurangi sedikitpun.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 110, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ فَٱخۡتُلِفَ فِیهِۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَقُضِیَ بَیۡنَهُمۡۚ وَإِنَّهُمۡ لَفِی شَكࣲّ مِّنۡهُ مُرِیبࣲ ۝١١٠", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "ولقد آتينا موسى الكتاب وهو التوراة، فاختلف فيه قومه، فآمن به جماعة وكفر به آخرون كما فعل قومك بالقرآن. ولولا كلمة سبقت من ربك بأنه لا يعجل لخلقه العذاب، لحلَّ بهم في دنياهم قضاء الله بإهلاك المكذِّبين ونجاة المؤمنين. وإن الكفار من اليهود والمشركين -أيها الرسول- لفي شك -من هذا القرآن- مريب.", "isBasmala": false, "translation_en": "We gave Moses the Scripture, but it was disputed. Were it not for a prior word from your Lord, it would have been settled between them. They are in serious doubt concerning it.", "translation_id": "Dan sesungguhnya Kami telah memberikan Kitab (Taurat) kepada Musa, lalu diperselisihkan tentang Kitab itu. Dan seandainya tidak ada ketetapan yang telah terdahulu dari Tuhanmu, niscaya telah ditetapkan hukuman di antara mereka. Dan sesungguhnya mereka (orang-orang kafir Mekah) dalam keraguan yang menggelisahkan terhadap Al Quran.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 111, "text": "وَإِنَّ كُلࣰّا لَّمَّا لَیُوَفِّیَنَّهُمۡ رَبُّكَ أَعۡمَـٰلَهُمۡۚ إِنَّهُۥ بِمَا یَعۡمَلُونَ خَبِیرࣱ ۝١١١", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "وإن كل أولئك الأقوام المختلفين الذين ذكرنا لك -أيها الرسول- أخبارهم ليوفينهم ربك جزاء أعمالهم يوم القيامة، إن خيرًا فخير، وإن شرًا فشر، إن ربك بما يعمل هؤلاء المشركون خبير، لا يخفى عليه شيء من عملهم. وفي هذا تهديد ووعيد لهم.", "isBasmala": false, "translation_en": "Your Lord will repay each one of them in full for their deeds. He is Aware of everything they do.", "translation_id": "Dan sesungguhnya kepada masing-masing (mereka yang berselisih itu) pasti Tuhanmu akan menyempurnakan dengan cukup, (balasan) pekerjaan mereka. Sesungguhnya Dia Maha Mengetahui apa yang mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 112, "text": "فَٱسۡتَقِمۡ كَمَاۤ أُمِرۡتَ وَمَن تَابَ مَعَكَ وَلَا تَطۡغَوۡا۟ۚ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِیرࣱ ۝١١٢", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "فاستقم -أيها النبي- كما أمرك ربك أنت ومن تاب معك، ولا تتجاوزوا ما حدَّه الله لكم، إن ربَّكم بما تعملون من الأعمال كلها بصير، لا يخفى عليه شيء منها، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "So be upright, as you are commanded, along with those who repented with you, and do not transgress. He is Seeing of everything you do.", "translation_id": "Maka tetaplah kamu pada jalan yang benar, sebagaimana diperintahkan kepadamu dan (juga) orang yang telah taubat beserta kamu dan janganlah kamu melampaui batas. Sesungguhnya Dia Maha Melihat apa yang kamu kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 113, "text": "وَلَا تَرۡكَنُوۤا۟ إِلَى ٱلَّذِینَ ظَلَمُوا۟ فَتَمَسَّكُمُ ٱلنَّارُ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِنۡ أَوۡلِیَاۤءَ ثُمَّ لَا تُنصَرُونَ ۝١١٣", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "ولا تميلوا إلى هؤلاء الكفار الظلمة، فتصيبكم النار، وما لكم من دون الله من ناصر ينصركم، ويتولى أموركم.", "isBasmala": false, "translation_en": "And do not incline towards those who do wrong, or the Fire may touch you; and you will have no protectors besides God, and you will not be saved.", "translation_id": "Dan janganlah kamu cenderung kepada orang-orang yang zalim yang menyebabkan kamu disentuh api neraka, dan sekali-kali kamu tiada mempunyai seorang penolongpun selain daripada Allah, kemudian kamu tidak akan diberi pertolongan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 114, "text": "وَأَقِمِ ٱلصَّلَوٰةَ طَرَفَیِ ٱلنَّهَارِ وَزُلَفࣰا مِّنَ ٱلَّیۡلِۚ إِنَّ ٱلۡحَسَنَـٰتِ یُذۡهِبۡنَ ٱلسَّیِّـَٔاتِۚ ذَ ٰلِكَ ذِكۡرَىٰ لِلذَّ ٰكِرِینَ ۝١١٤", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "وأدِّ الصلاة -أيها النبي- على أتمِّ وجه طَرَفَي النهار في الصباح والمساء، وفي ساعات من الليل. إنَّ فِعْلَ الخيرات يكفِّر الذنوب السالفة ويمحو آثارها، والأمر بإقامة الصلاة وبيان أن الحسنات يذهبن السيئات، موعظة لمن اتعظ بها وتذكر.", "isBasmala": false, "translation_en": "Perform the prayer at the borders of the day, and during the approaches of the night. The good deeds take away the bad deeds. This is a reminder for those who remember.", "translation_id": "Dan dirikanlah sembahyang itu pada kedua tepi siang (pagi dan petang) dan pada bahagian permulaan daripada malam. Sesungguhnya perbuatan-perbuatan yang baik itu menghapuskan (dosa) perbuatan-perbuatan yang buruk. Itulah peringatan bagi orang-orang yang ingat.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 115, "text": "وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا یُضِیعُ أَجۡرَ ٱلۡمُحۡسِنِینَ ۝١١٥", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "واصبر -أيها النبي- على الصلاة، وعلى ما تَلْقى من الأذى من مشركي قومك؛ فإن الله لا يضيع ثواب المحسنين في أعمالهم.", "isBasmala": false, "translation_en": "And be patient. God will not waste the reward of the virtuous.", "translation_id": "Dan bersabarlah, karena sesungguhnya Allah tiada menyia-nyiakan pahala orang-orang yang berbuat kebaikan.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 116, "text": "فَلَوۡلَا كَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُو۟لُوا۟ بَقِیَّةࣲ یَنۡهَوۡنَ عَنِ ٱلۡفَسَادِ فِی ٱلۡأَرۡضِ إِلَّا قَلِیلࣰا مِّمَّنۡ أَنجَیۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ ٱلَّذِینَ ظَلَمُوا۟ مَاۤ أُتۡرِفُوا۟ فِیهِ وَكَانُوا۟ مُجۡرِمِینَ ۝١١٦", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "فهلاَّ وُجد من القرون الماضية بقايا من أهل الخير والصلاح، ينهون أهل الكفر عن كفرهم، وعن الفساد في الأرض، لم يوجد من أولئك الأقوام إلا قليل ممن آمن، فنجَّاهم الله بسبب ذلك مِن عذابه حين أخذ الظالمين. واتَّبع عامتهم من الذين ظلموا أنفسهم ما مُتِّعوا فيه من لذات الدنيا ونعيمها، وكانوا مجرمين ظالمين باتباعهم ما تنعموا فيه، فحقَّ عليهم العذاب.", "isBasmala": false, "translation_en": "If only there were, among the generations before you, people with wisdom, who spoke against corruption on earth-except for the few whom We saved. But the wrongdoers pursued the luxuries they were indulged in, and thus became guilty.", "translation_id": "Maka mengapa tidak ada dari umat-umat yang sebelum kamu orang-orang yang mempunyai keutamaan yang melarang daripada (mengerjakan) kerusakan di muka bumi, kecuali sebahagian kecil di antara orang-orang yang telah Kami selamatkan di antara mereka, dan orang-orang yang zalim hanya mementingkan kenikmatan yang mewah yang ada pada mereka, dan mereka adalah orang-orang yang berdosa.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 117, "text": "وَمَا كَانَ رَبُّكَ لِیُهۡلِكَ ٱلۡقُرَىٰ بِظُلۡمࣲ وَأَهۡلُهَا مُصۡلِحُونَ ۝١١٧", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "وما كان ربك -أيها الرسول- ليهلك قرية من القرى وأهلها مصلحون في الأرض، مجتنبون للفساد والظلم، وإنما يهلكهم بسبب ظلمهم وفسادهم.", "isBasmala": false, "translation_en": "Your Lord would never destroy the towns wrongfully, while their inhabitants are righteous.", "translation_id": "Dan Tuhanmu sekali-kali tidak akan membinasakan negeri-negeri secara zalim, sedang penduduknya orang-orang yang berbuat kebaikan.", "manzil": 3, "manzil_display": ""}], "235": [{"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 118, "text": "وَلَوۡ شَاۤءَ رَبُّكَ لَجَعَلَ ٱلنَّاسَ أُمَّةࣰ وَ ٰحِدَةࣰۖ وَلَا یَزَالُونَ مُخۡتَلِفِینَ ۝١١٨", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "ولو شاء ربك لجعل الناس كلهم جماعة واحدة على دين واحد وهو دين الإسلام، ولكنه سبحانه لم يشأ ذلك، فلا يزال الناس مختلفين في أديانهم؛ وذلك مقتضى حكمته.", "isBasmala": false, "translation_en": "Had your Lord willed, He could have made humanity one community, but they continue to differ.", "translation_id": "Jikalau Tuhanmu menghendaki, tentu Dia menjadikan manusia umat yang satu, tetapi mereka senantiasa berselisih pendapat,", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 119, "text": "إِلَّا مَن رَّحِمَ رَبُّكَۚ وَلِذَ ٰلِكَ خَلَقَهُمۡۗ وَتَمَّتۡ كَلِمَةُ رَبِّكَ لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِینَ ۝١١٩", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "إلا مَن رحم ربك فآمنوا به واتبعوا رسله، فإنهم لا يختلفون في توحيد الله وما جاءت به الرسل من عند الله، وقد اقتضت حكمته سبحانه وتعالى أنه خَلَقهم مختلفين: فريق شقيٌّ وفريق سعيد، وكل ميسر لما خُلِق له. وبهذا يتحقق وعد ربك في قضائه وقدره: أنه سبحانه سيملأ جهنم من الجن والإنس الذين اتبعوا إبليس وجنده ولم يهتدوا للإيمان.", "isBasmala": false, "translation_en": "Except those on whom your Lord has mercy-for that reason He created them. The Word of your Lord is final: \"I will fill Hell with jinn and humans, altogether.\"", "translation_id": "kecuali orang-orang yang diberi rahmat oleh Tuhanmu. Dan untuk itulah Allah menciptakan mereka. Kalimat Tuhanmu (keputusan-Nya) telah ditetapkan: sesungguhnya Aku akan memenuhi neraka Jahannam dengan jin dan manusia (yang durhaka) semuanya.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 120, "text": "وَكُلࣰّا نَّقُصُّ عَلَیۡكَ مِنۡ أَنۢبَاۤءِ ٱلرُّسُلِ مَا نُثَبِّتُ بِهِۦ فُؤَادَكَۚ وَجَاۤءَكَ فِی هَـٰذِهِ ٱلۡحَقُّ وَمَوۡعِظَةࣱ وَذِكۡرَىٰ لِلۡمُؤۡمِنِینَ ۝١٢٠", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "ونقصُّ عليك -أيها النبي- من أخبار الرسل الذين كانوا قبلك، كل ما تحتاج إليه مما يقوِّي قلبك للقيام بأعباء الرسالة، وقد جاءك في هذه السورة وما اشتملت عليه من أخبار، بيان الحق الذي أنت عليه، وجاءك فيها موعظة يرتدع بها الكافرون، وذكرى يتذكر بها المؤمنون بالله ورسله.", "isBasmala": false, "translation_en": "Everything We narrate to you of the history of the messengers is to strengthen your heart therewith. The truth has come to you in this, and a lesson, and a reminder for the believers.", "translation_id": "Dan semua kisah dari rasul-rasul Kami ceritakan kepadamu, ialah kisah-kisah yang dengannya Kami teguhkan hatimu; dan dalam surat ini telah datang kepadamu kebenaran serta pengajaran dan peringatan bagi orang-orang yang beriman.", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 121, "text": "وَقُل لِّلَّذِینَ لَا یُؤۡمِنُونَ ٱعۡمَلُوا۟ عَلَىٰ مَكَانَتِكُمۡ إِنَّا عَـٰمِلُونَ ۝١٢١", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "وقل -أيها الرسول- للكافرين الذين لا يقرُّون بوحدانية الله: اعملوا ما أنتم عاملون على حالتكم وطريقتكم في مقاومة الدعوة وإيذاء الرسول والمستجيبين له، فإنَّا عاملون على مكانتنا وطريقتنا من الثبات على ديننا وتنفيذ أمر الله. وانتظروا عاقبة أمرنا، فإنَّا منتظرون عاقبة أمركم. وفي هذا تهديد ووعيد لهم.", "isBasmala": false, "translation_en": "And say to those who do not believe, \"Act according to your ability; and so will we.\"", "translation_id": "Dan katakanlah kepada orang-orang yang tidak beriman: \"Berbuatlah menurut kemampuanmu; sesungguhnya Kami-pun berbuat (pula)\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 122, "text": "وَٱنتَظِرُوۤا۟ إِنَّا مُنتَظِرُونَ ۝١٢٢", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "وقل -أيها الرسول- للكافرين الذين لا يقرُّون بوحدانية الله: اعملوا ما أنتم عاملون على حالتكم وطريقتكم في مقاومة الدعوة وإيذاء الرسول والمستجيبين له، فإنَّا عاملون على مكانتنا وطريقتنا من الثبات على ديننا وتنفيذ أمر الله. وانتظروا عاقبة أمرنا، فإنَّا منتظرون عاقبة أمركم. وفي هذا تهديد ووعيد لهم.", "isBasmala": false, "translation_en": "\"And wait; we too are waiting.\"", "translation_id": "Dan tunggulah (akibat perbuatanmu); sesungguhnya kamipun menunggu (pula)\".", "manzil": 3, "manzil_display": ""}, {"sura": 11, "sura_name": "هود", "revelation": "Makkiyah", "aya": 123, "text": "وَلِلَّهِ غَیۡبُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَإِلَیۡهِ یُرۡجَعُ ٱلۡأَمۡرُ كُلُّهُۥ فَٱعۡبُدۡهُ وَتَوَكَّلۡ عَلَیۡهِۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ ۝١٢٣", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "ولله سبحانه وتعالى علم كل ما غاب في السموات والأرض، وإليه يُرْجَع الأمر كله يوم القيامة، فاعبده -أيها النبي- وفوِّض أمرك إليه، وما ربك بغافل عما تعملون من الخير والشر، وسيجازي كلاًّ بعمله.", "isBasmala": false, "translation_en": "To God belongs the future of the heavens and the earth, and to Him all authority goes back. So worship Him, and rely on Him. Your Lord is never unaware of what you do.", "translation_id": "Dan kepunyaan Allah-lah apa yang ghaib di langit dan di bumi dan kepada-Nya-lah dikembalikan urusan-urusan semuanya, maka sembahlah Dia, dan bertawakkallah kepada-Nya. Dan sekali-kali Tuhanmu tidak lalai dari apa yang kamu kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 13, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 1, "text": "الۤرۚ تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡمُبِینِ ۝١", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Ra. These are the Verses of the Clear Book.", "translation_id": "Alif, laam, raa. Ini adalah ayat-ayat Kitab (Al Quran) yang nyata (dari Allah).", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 2, "text": "إِنَّاۤ أَنزَلۡنَـٰهُ قُرۡءَ ٰنًا عَرَبِیࣰّا لَّعَلَّكُمۡ تَعۡقِلُونَ ۝٢", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "إنا أنزلنا هذا القرآن بلغة العرب، لعلكم -أيها العرب- تعقلون معانيه وتفهمونها، وتعملون بهديه.", "isBasmala": false, "translation_en": "We have revealed it an Arabic Quran, so that you may understand.", "translation_id": "Sesungguhnya Kami menurunkannya berupa Al Quran dengan berbahasa Arab, agar kamu memahaminya.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 3, "text": "نَحۡنُ نَقُصُّ عَلَیۡكَ أَحۡسَنَ ٱلۡقَصَصِ بِمَاۤ أَوۡحَیۡنَاۤ إِلَیۡكَ هَـٰذَا ٱلۡقُرۡءَانَ وَإِن كُنتَ مِن قَبۡلِهِۦ لَمِنَ ٱلۡغَـٰفِلِینَ ۝٣", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "نحن نقصُّ عليك -أيها الرسول- أحسن القصص بوحينا إليك هذا القرآن، وإن كنت قبل إنزاله عليك لمن الغافلين عن هذه الأخبار، لا تدري عنها شيئًا.", "isBasmala": false, "translation_en": "We narrate to you the most accurate history, by revealing to you this Quran. Although, prior to it, you were of the unaware.", "translation_id": "Kami menceritakan kepadamu kisah yang paling baik dengan mewahyukan Al Quran ini kepadamu, dan sesungguhnya kamu sebelum (Kami mewahyukan)nya adalah termasuk orang-orang yang belum mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 4, "text": "إِذۡ قَالَ یُوسُفُ لِأَبِیهِ یَـٰۤأَبَتِ إِنِّی رَأَیۡتُ أَحَدَ عَشَرَ كَوۡكَبࣰا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَیۡتُهُمۡ لِی سَـٰجِدِینَ ۝٤", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "اذكر -أيها الرسول- لقومك قول يوسف لأبيه: إني رأيت في المنام أحد عشر كوكبًا، والشمس والقمر رأيتهم لي ساجدين. فكانت هذه الرؤيا بشرى لِمَا وصل إليه يوسف عليه السلام من علوِّ المنزلة في الدنيا والآخرة.", "isBasmala": false, "translation_en": "When Joseph said to his father, \"O my father, I saw eleven planets, and the sun, and the moon; I saw them bowing down to me.\"", "translation_id": "(Ingatlah), ketika Yusuf berkata kepada ayahnya: \"Wahai ayahku, sesungguhnya aku bermimpi melihat sebelas bintang, matahari dan bulan; kulihat semuanya sujud kepadaku\".", "manzil": 3, "manzil_display": ""}], "236": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 5, "text": "قَالَ یَـٰبُنَیَّ لَا تَقۡصُصۡ رُءۡیَاكَ عَلَىٰۤ إِخۡوَتِكَ فَیَكِیدُوا۟ لَكَ كَیۡدًاۖ إِنَّ ٱلشَّیۡطَـٰنَ لِلۡإِنسَـٰنِ عَدُوࣱّ مُّبِینࣱ ۝٥", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "قال يعقوب لابنه يوسف: يا بني لا تذكر لإخوتك هذه الرؤيا فيحسدوك، ويعادوك، ويحتالوا في إهلاكك، إن الشيطان للإنسان عدو ظاهر العداوة.", "isBasmala": false, "translation_en": "He said, \"O my son, do not relate your vision to your brothers, lest they plot and scheme against you. Satan is man's sworn enemy.", "translation_id": "Ayahnya berkata: \"Hai anakku, janganlah kamu ceritakan mimpimu itu kepada saudara-saudaramu, maka mereka membuat makar (untuk membinasakan)mu. Sesungguhnya syaitan itu adalah musuh yang nyata bagi manusia\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 6, "text": "وَكَذَ ٰلِكَ یَجۡتَبِیكَ رَبُّكَ وَیُعَلِّمُكَ مِن تَأۡوِیلِ ٱلۡأَحَادِیثِ وَیُتِمُّ نِعۡمَتَهُۥ عَلَیۡكَ وَعَلَىٰۤ ءَالِ یَعۡقُوبَ كَمَاۤ أَتَمَّهَا عَلَىٰۤ أَبَوَیۡكَ مِن قَبۡلُ إِبۡرَ ٰهِیمَ وَإِسۡحَـٰقَۚ إِنَّ رَبَّكَ عَلِیمٌ حَكِیمࣱ ۝٦", "juz": 12, "hizb": "(*¼ ح 24*)", "tafsir": "وكما أراك ربك هذه الرؤيا فكذلك يصطفيك ويعلمك تفسير ما يراه الناس في منامهم من الرؤى مما تؤول إليه واقعًا، ويتم نعمته عليك وعلى آل يعقوب بالنبوة والرسالة، كما أتمها من قبل على أبويك إبراهيم وإسحاق بالنبوة والرسالة. إن ربك عليم بمن يصطفيه من عباده، حكيم في تدبير أمور خلقه.", "isBasmala": false, "translation_en": "And thus your Lord will choose you, and will teach you the interpretation of events, and will complete His blessing upon you and upon the family of Jacob, as He has completed it before upon your forefathers Abraham and Isaac. Your Lord is Knowing and Wise.", "translation_id": "Dan demikianlah Tuhanmu, memilih kamu (untuk menjadi Nabi) dan diajarkan-Nya kepadamu sebahagian dari ta'bir mimpi-mimpi dan disempurnakan-Nya nikmat-Nya kepadamu dan kepada keluarga Ya'qub, sebagaimana Dia telah menyempurnakan nikmat-Nya kepada dua orang bapakmu sebelum itu, (yaitu) Ibrahim dan Ishak. Sesungguhnya Tuhanmu Maha Mengetahui lagi Maha Bijaksana.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 7, "text": "۞ لَّقَدۡ كَانَ فِی یُوسُفَ وَإِخۡوَتِهِۦۤ ءَایَـٰتࣱ لِّلسَّاۤىِٕلِینَ ۝٧", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "لقد كان في قصة يوسف وإخوته عبر وأدلة تدل على قدرة الله وحكمته لمن يسأل عن أخبارهم، ويرغب في معرفتها.", "isBasmala": false, "translation_en": "In Joseph and his brothers are lessons for the seekers.", "translation_id": "Sesungguhnya ada beberapa tanda-tanda kekuasaan Allah pada (kisah) Yusuf dan saudara-saudaranya bagi orang-orang yang bertanya.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 8, "text": "إِذۡ قَالُوا۟ لَیُوسُفُ وَأَخُوهُ أَحَبُّ إِلَىٰۤ أَبِینَا مِنَّا وَنَحۡنُ عُصۡبَةٌ إِنَّ أَبَانَا لَفِی ضَلَـٰلࣲ مُّبِینٍ ۝٨", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "إذ قال إخوة يوسف من أبيه فيما بينهم: إن يوسف وأخاه الشقيق أحب إلى أبينا منا، يفضِّلهما علينا، ونحن جماعة ذوو عدد، إن أبانا لفي خطأ بيِّن حيث فضَّلهما علينا من غير موجب نراه.", "isBasmala": false, "translation_en": "When they said, \"Joseph and his brother are dearer to our father than we are, although we are a whole group. Our father is obviously in the wrong.", "translation_id": "(Yaitu) ketika mereka berkata: \"Sesungguhnya Yusuf dan saudara kandungnya (Bunyamin) lebih dicintai oleh ayah kita dari pada kita sendiri, padahal kita (ini) adalah satu golongan (yang kuat). Sesungguhnya ayah kita adalah dalam kekeliruan yang nyata.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 9, "text": "ٱقۡتُلُوا۟ یُوسُفَ أَوِ ٱطۡرَحُوهُ أَرۡضࣰا یَخۡلُ لَكُمۡ وَجۡهُ أَبِیكُمۡ وَتَكُونُوا۟ مِنۢ بَعۡدِهِۦ قَوۡمࣰا صَـٰلِحِینَ ۝٩", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "اقتلوا يوسف أو ألقوا به في أرض مجهولة بعيدة عن العُمران يخلُص لكم حب أبيكم وإقباله عليكم، ولا يلتفت عنكم إلى غيركم، وتكونوا مِنْ بعد قَتْل يوسف أو إبعاده تائبين إلى الله، مستغفرين له من بعد ذنبكم.", "isBasmala": false, "translation_en": "\"Kill Joseph, or throw him somewhere in the land, and your father's attention will be yours. Afterwards, you will be decent people.\"", "translation_id": "Bunuhlah Yusuf atau buanglah dia kesuatu daerah (yang tak dikenal) supaya perhatian ayahmu tertumpah kepadamu saja, dan sesudah itu hendaklah kamu menjadi orang-orang yang baik\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 10, "text": "قَالَ قَاۤىِٕلࣱ مِّنۡهُمۡ لَا تَقۡتُلُوا۟ یُوسُفَ وَأَلۡقُوهُ فِی غَیَـٰبَتِ ٱلۡجُبِّ یَلۡتَقِطۡهُ بَعۡضُ ٱلسَّیَّارَةِ إِن كُنتُمۡ فَـٰعِلِینَ ۝١٠", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "قال قائل من إخوة يوسف: لا تقتلوا يوسف وألقوه في جوف البئر يلتقطه بعض المارَّة من المسافرين فتستريحوا منه، ولا حاجة إلى قتله، إن كنتم عازمين على فعل ما تقولون.", "isBasmala": false, "translation_en": "One of them said, \"Do not kill Joseph, but throw him into the bottom of the well; some caravan may pick him up-if you must do something.\"", "translation_id": "Seorang diantara mereka berkata: \"Janganlah kamu bunuh Yusuf, tetapi masukkanlah dia ke dasar sumur supaya dia dipungut oleh beberapa orang musafir, jika kamu hendak berbuat\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 11, "text": "قَالُوا۟ یَـٰۤأَبَانَا مَالَكَ لَا تَأۡمَـ۫نَّا عَلَىٰ یُوسُفَ وَإِنَّا لَهُۥ لَنَـٰصِحُونَ ۝١١", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "قال إخوة يوسف -بعد اتفاقهم على إبعاده-: يا أبانا ما لك لا تجعلنا أمناء على يوسف مع أنه أخونا، ونحن نريد له الخير ونشفق عليه ونرعاه، ونخصه بخالص النصح؟", "isBasmala": false, "translation_en": "They said, \"Father, why do you not trust us with Joseph, although we care for him?\"", "translation_id": "Mereka berkata: \"Wahai ayah kami, apa sebabnya kamu tidak mempercayai kami terhadap Yusuf, padahal sesungguhnya kami adalah orang-orang yang mengingini kebaikan baginya.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 12, "text": "أَرۡسِلۡهُ مَعَنَا غَدࣰا یَرۡتَعۡ وَیَلۡعَبۡ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ ۝١٢", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "أرسله معنا غدًا عندما نخرج إلى مراعينا يَسْعَ وينشط ويفرح، ويلعب بالاستباق ونحوه من اللعب المباح، وإنا لحافظون له من كل ما تخاف عليه.", "isBasmala": false, "translation_en": "\"Send him with us tomorrow, that he may roam and play; we will take care of him.\"", "translation_id": "Biarkanlah dia pergi bersama kami besok pagi, agar dia (dapat) bersenang-senang dan (dapat) bermain-main, dan sesungguhnya kami pasti menjaganya\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 13, "text": "قَالَ إِنِّی لَیَحۡزُنُنِیۤ أَن تَذۡهَبُوا۟ بِهِۦ وَأَخَافُ أَن یَأۡكُلَهُ ٱلذِّئۡبُ وَأَنتُمۡ عَنۡهُ غَـٰفِلُونَ ۝١٣", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "قال يعقوب: إني لَيؤلم نفسي مفارقته لي إذا ذهبتم به إلى المراعي، وأخشى أن يأكله الذئب، وأنتم عنه غافلون منشغلون.", "isBasmala": false, "translation_en": "He said, \"It worries me that you would take him away. And I fear the wolf may eat him while you are careless of him.\"", "translation_id": "Berkata Ya'qub: \"Sesungguhnya kepergian kamu bersama Yusuf amat menyedihkanku dan aku khawatir kalau-kalau dia dimakan serigala, sedang kamu lengah dari padanya\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 14, "text": "قَالُوا۟ لَىِٕنۡ أَكَلَهُ ٱلذِّئۡبُ وَنَحۡنُ عُصۡبَةٌ إِنَّاۤ إِذࣰا لَّخَـٰسِرُونَ ۝١٤", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "قال إخوة يوسف لوالدهم: لئن أكله الذئب، ونحن جماعة قوية إنا إذًا لخاسرون، لا خير فينا، ولا نفع يُرْجَى منا.", "isBasmala": false, "translation_en": "They said, \"If the wolf ate him, and we are many, we would be good for nothing.\"", "translation_id": "Mereka berkata: \"Jika ia benar-benar dimakan serigala, sedang kami golongan (yang kuat), sesungguhnya kami kalau demikian adalah orang-orang yang merugi\".", "manzil": 3, "manzil_display": ""}], "237": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 15, "text": "فَلَمَّا ذَهَبُوا۟ بِهِۦ وَأَجۡمَعُوۤا۟ أَن یَجۡعَلُوهُ فِی غَیَـٰبَتِ ٱلۡجُبِّۚ وَأَوۡحَیۡنَاۤ إِلَیۡهِ لَتُنَبِّئَنَّهُم بِأَمۡرِهِمۡ هَـٰذَا وَهُمۡ لَا یَشۡعُرُونَ ۝١٥", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "فأرْسَلَهُ معهم. فلما ذهبوا به وأجمعوا على إلقائه في جوف البئر، وأوحينا إلى يوسف لتخبرنَّ إخوتك مستقبلا بفعلهم هذا الذي فعلوه بك، وهم لا يُحِسُّون بذلك الأمر ولا يشعرون به.", "isBasmala": false, "translation_en": "So they went away with him, and agreed to put him at the bottom of the well. And We inspired him, \"You will inform them of this deed of theirs when they are unaware.\"", "translation_id": "Maka tatkala mereka membawanya dan sepakat memasukkannya ke dasar sumur (lalu mereka masukkan dia), dan (di waktu dia sudah dalam sumur) Kami wahyukan kepada Yusuf: \"Sesungguhnya kamu akan menceritakan kepada mereka perbuatan mereka ini, sedang mereka tiada ingat lagi\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 16, "text": "وَجَاۤءُوۤ أَبَاهُمۡ عِشَاۤءࣰ یَبۡكُونَ ۝١٦", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "وجاء إخوة يوسف إلى أبيهم في وقت العِشاء من أول الليل، يبكون ويظهرون الأسف والجزع.", "isBasmala": false, "translation_en": "And they came to their father in the evening weeping.", "translation_id": "Kemudian mereka datang kepada ayah mereka di sore hari sambil menangis.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 17, "text": "قَالُوا۟ یَـٰۤأَبَانَاۤ إِنَّا ذَهَبۡنَا نَسۡتَبِقُ وَتَرَكۡنَا یُوسُفَ عِندَ مَتَـٰعِنَا فَأَكَلَهُ ٱلذِّئۡبُۖ وَمَاۤ أَنتَ بِمُؤۡمِنࣲ لَّنَا وَلَوۡ كُنَّا صَـٰدِقِینَ ۝١٧", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "قالوا: يا أبانا إنا ذهبنا نتسابق في الجَرْي والرمي بالسهام، وتركنا يوسف عند زادنا وثيابنا، فلم نقصِّر في حفظه، بل تركناه في مأمننا، وما فارقناه إلا وقتًا يسيرًا، فأكله الذئب، وما أنت بمصدِّق لنا ولو كنا موصوفين بالصدق؛ لشدة حبك ليوسف.", "isBasmala": false, "translation_en": "They said, \"O father, we went off racing one another, and left Joseph by our belongings; and the wolf ate him. But you will not believe us, even though we are being truthful.\"", "translation_id": "Mereka berkata: \"Wahai ayah kami, sesungguhnya kami pergi berlomba-lomba dan kami tinggalkan Yusuf di dekat barang-barang kami, lalu dia dimakan serigala; dan kamu sekali-kali tidak akan percaya kepada kami, sekalipun kami adalah orang-orang yang benar\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 18, "text": "وَجَاۤءُو عَلَىٰ قَمِیصِهِۦ بِدَمࣲ كَذِبࣲۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرࣰاۖ فَصَبۡرࣱ جَمِیلࣱۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١٨", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "وجاؤوا بقميصه ملطخًا بدم غير دم يوسف؛ ليشهد على صدقهم، فكان دليلا على كذبهم؛ لأن القميص لم يُمَزَّقْ. فقال لهم أبوهم يعقوب عليه السلام: ما الأمر كما تقولون، بل زيَّنت لكم أنفسكم الأمَّارة بالسوء أمرًا قبيحًا في يوسف، فرأيتموه حسنًا وفعلتموه، فصبري صبر جميل لا شكوى معه لأحد من الخلق، وأستعين بالله على احتمال ما تصفون من الكذب، لا على حولي وقوتي.", "isBasmala": false, "translation_en": "And they brought his shirt, with fake blood on it. He said, \"Your souls enticed you to do something. But patience is beautiful, and God is my Help against what you describe.\"", "translation_id": "Mereka datang membawa baju gamisnya (yang berlumuran) dengan darah palsu. Ya'qub berkata: \"Sebenarnya dirimu sendirilah yang memandang baik perbuatan (yang buruk) itu; maka kesabaran yang baik itulah (kesabaranku). Dan Allah sajalah yang dimohon pertolongan-Nya terhadap apa yang kamu ceritakan\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 19, "text": "وَجَاۤءَتۡ سَیَّارَةࣱ فَأَرۡسَلُوا۟ وَارِدَهُمۡ فَأَدۡلَىٰ دَلۡوَهُۥۖ قَالَ یَـٰبُشۡرَىٰ هَـٰذَا غُلَـٰمࣱۚ وَأَسَرُّوهُ بِضَـٰعَةࣰۚ وَٱللَّهُ عَلِیمُۢ بِمَا یَعۡمَلُونَ ۝١٩", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "وجاءت جماعة من المسافرين، فأرسلوا مَن يطلب لهم الماء، فلما أرسل دلوه في البئر تعلَّق بها يوسف، فقال واردهم: يا بشراي هذا غلام نفيس، وأخفى الواردُ وأصحابه يوسفَ من بقية المسافرين فلم يظهروه لهم، وقالوا: إن هذه بضاعة استبضعناها، والله عليم بما يعملونه بيوسف.", "isBasmala": false, "translation_en": "A caravan passed by, and they sent their water-carrier. He lowered his bucket, and said, \"Good news. Here is a boy.\" And they hid him as merchandise. But God was aware of what they did.", "translation_id": "Kemudian datanglah kelompok orang-orang musafir, lalu mereka menyuruh seorang pengambil air, maka dia menurunkan timbanya, dia berkata: \"Oh; kabar gembira, ini seorang anak muda!\" Kemudian mereka menyembunyikan dia sebagai barang dagangan. Dan Allah Maha Mengetahui apa yang mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 20, "text": "وَشَرَوۡهُ بِثَمَنِۭ بَخۡسࣲ دَرَ ٰهِمَ مَعۡدُودَةࣲ وَكَانُوا۟ فِیهِ مِنَ ٱلزَّ ٰهِدِینَ ۝٢٠", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "وباعه إخوته للواردين من المسافرين بثمن قليل من الدراهم، وكانوا زاهدين فيه راغبين في التخلص منه؛ وذلك أنهم لا يعلمون منزلته عند الله.", "isBasmala": false, "translation_en": "And they sold him for a cheap price-a few coins-they considered him to be of little value.", "translation_id": "Dan mereka menjual Yusuf dengan harga yang murah, yaitu beberapa dirham saja, dan mereka merasa tidak tertarik hatinya kepada Yusuf.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 21, "text": "وَقَالَ ٱلَّذِی ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦۤ أَكۡرِمِی مَثۡوَىٰهُ عَسَىٰۤ أَن یَنفَعَنَاۤ أَوۡ نَتَّخِذَهُۥ وَلَدࣰاۚ وَكَذَ ٰلِكَ مَكَّنَّا لِیُوسُفَ فِی ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِیلِ ٱلۡأَحَادِیثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰۤ أَمۡرِهِۦ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٢١", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "ولما ذهب المسافرون بيوسف إلى \"مصر\" اشتراه منهم عزيزها، وهو الوزير، وقال لامرأته: أحسني معاملته، واجعلي مقامه عندنا كريمًا، لعلنا نستفيد من خدمته، أو نقيمه عندنا مقام الولد، وكما أنجينا يوسف وجعلنا عزيز \"مصر\" يَعْطِف عليه، فكذلك مكنَّا له في أرض \"مصر\"، وجعلناه على خزائنها، ولنعلِّمه تفسير الرؤى فيعرف منها ما سيقع مستقبلا. والله غالب على أمره، فحكمه نافذ لا يبطله مبطل، ولكن أكثر الناس لا يعلمون أن الأمر كله بيد الله.", "isBasmala": false, "translation_en": "The Egyptian who bought him said to his wife, \"Take good care of him; he may be useful to us, or we may adopt him as a son.\" We thus established Joseph in the land, to teach him the interpretation of events. God has control over His affairs, but most people do not know.", "translation_id": "Dan orang Mesir yang membelinya berkata kepada isterinya: \"Berikanlah kepadanya tempat (dan layanan) yang baik, boleh jadi dia bermanfaat kepada kita atau kita pungut dia sebagai anak\". Dan demikian pulalah Kami memberikan kedudukan yang baik kepada Yusuf di muka bumi (Mesir), dan agar Kami ajarkan kepadanya ta'bir mimpi. Dan Allah berkuasa terhadap urusan-Nya, tetapi kebanyakan manusia tiada mengetahuinya.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 22, "text": "وَلَمَّا بَلَغَ أَشُدَّهُۥۤ ءَاتَیۡنَـٰهُ حُكۡمࣰا وَعِلۡمࣰاۚ وَكَذَ ٰلِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ ۝٢٢", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "ولما بلغ يوسف منتهى قوته في شبابه أعطيناه فهمًا وعلمًا، ومثل هذا الجزاء الذي جزينا به يوسف على إحسانه نجزي المحسنين على إحسانهم. وفي هذا تسلية للرسول صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "When he reached his maturity, We gave him wisdom and knowledge. We thus reward the righteous.", "translation_id": "Dan tatkala dia cukup dewasa Kami berikan kepadanya hikmah dan ilmu. Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.", "manzil": 3, "manzil_display": ""}], "238": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 23, "text": "وَرَ ٰوَدَتۡهُ ٱلَّتِی هُوَ فِی بَیۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَ ٰبَ وَقَالَتۡ هَیۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّیۤ أَحۡسَنَ مَثۡوَایَۖ إِنَّهُۥ لَا یُفۡلِحُ ٱلظَّـٰلِمُونَ ۝٢٣", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "ودعت امرأة العزيز -برفق ولين- يوسف الذي هو في بيتها إلى نفسها؛ لحبها الشديد له وحسن بهائه، وغلَّقت الأبواب عليها وعلى يوسف، وقالت: هلمَّ إليَّ، فقال: معاذ الله أعتصم به، وأستجير مِن الذي تدعينني إليه، من خيانة سيدي الذي أحسن منزلتي وأكرمني فلا أخونه في أهله، إنه لا يفلح مَن ظَلَم فَفَعل ما ليس له فعله.", "isBasmala": false, "translation_en": "She in whose house he was living tried to seduce him. She shut the doors, and said, \"I am yours.\" He said, \"God forbid! He is my Lord. He has given me a good home. Sinners never succeed.\"", "translation_id": "Dan wanita (Zulaikha) yang Yusuf tinggal di rumahnya menggoda Yusuf untuk menundukkan dirinya (kepadanya) dan dia menutup pintu-pintu, seraya berkata: \"Marilah ke sini\". Yusuf berkata: \"Aku berlindung kepada Allah, sungguh tuanku telah memperlakukan aku dengan baik\". Sesungguhnya orang-orang yang zalim tiada akan beruntung.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 24, "text": "وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَاۤ أَن رَّءَا بُرۡهَـٰنَ رَبِّهِۦۚ كَذَ ٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوۤءَ وَٱلۡفَحۡشَاۤءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِینَ ۝٢٤", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "ولقد مالت نفسها لفعل الفاحشة، وحدَّثت يوسفَ نفسُه حديث خطرات للاستجابة، لولا أن رأى آية من آيات ربه تزجره عمَّا حدثته به نفسه، وإنما أريناه ذلك؛ لندفع عنه السوء والفاحشة في جميع أموره، إنه من عبادنا المطهرين المصطفَين للرسالة الذين أخلصوا في عبادتهم لله وتوحيده.", "isBasmala": false, "translation_en": "She desired him, and he desired her, had he not seen the proof of his Lord. It was thus that We diverted evil and indecency away from him. He was one of Our loyal servants.", "translation_id": "Sesungguhnya wanita itu telah bermaksud (melakukan perbuatan itu) dengan Yusuf, dan Yusufpun bermaksud (melakukan pula) dengan wanita itu andaikata dia tidak melihat tanda (dari) Tuhannya. Demikianlah, agar Kami memalingkan dari padanya kemungkaran dan kekejian. Sesungguhnya Yusuf itu termasuk hamba-hamba Kami yang terpilih.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 25, "text": "وَٱسۡتَبَقَا ٱلۡبَابَ وَقَدَّتۡ قَمِیصَهُۥ مِن دُبُرࣲ وَأَلۡفَیَا سَیِّدَهَا لَدَا ٱلۡبَابِۚ قَالَتۡ مَا جَزَاۤءُ مَنۡ أَرَادَ بِأَهۡلِكَ سُوۤءًا إِلَّاۤ أَن یُسۡجَنَ أَوۡ عَذَابٌ أَلِیمࣱ ۝٢٥", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "وأسرع يوسف إلى الباب يريد الخروج، وأسرعت تحاول الإمساك به، وجذبت قميصه من خلفه؛ لتحول بينه وبين الخروج فشقَّته، ووجدا زوجها عند الباب فقالت: ما جزاء مَن أراد بامرأتك فاحشة إلا أن يسجن أو يعذب العذاب الموجع.", "isBasmala": false, "translation_en": "As they raced towards the door, she tore his shirt from behind. At the door, they ran into her husband. She said, \"What is the penalty for him who desired to dishonor your wife, except imprisonment or a painful punishment?\"", "translation_id": "Dan keduanya berlomba-lomba menuju pintu dan wanita itu menarik baju gamis Yusuf dari belakang hingga koyak dan kedua-duanya mendapati suami wanita itu di muka pintu. Wanita itu berkata: \"Apakah pembalasan terhadap orang yang bermaksud berbuat serong dengan isterimu, selain dipenjarakan atau (dihukum) dengan azab yang pedih?\"", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 26, "text": "قَالَ هِیَ رَ ٰوَدَتۡنِی عَن نَّفۡسِیۚ وَشَهِدَ شَاهِدࣱ مِّنۡ أَهۡلِهَاۤ إِن كَانَ قَمِیصُهُۥ قُدَّ مِن قُبُلࣲ فَصَدَقَتۡ وَهُوَ مِنَ ٱلۡكَـٰذِبِینَ ۝٢٦", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "قال يوسف: هي التي طلبت مني ذلك، فشهد صبي في المهد مِن أهلها فقال: إن كان قميصه شُقَّ من الأمام فصدقت في اتِّهامها له، وهو من الكاذبين.", "isBasmala": false, "translation_en": "He said, \"It was she who tried to seduce me.\" A witness from her household suggested: \"If his shirt is torn from the front: then she has told the truth, and he is the liar.", "translation_id": "Yusuf berkata: \"Dia menggodaku untuk menundukkan diriku (kepadanya)\", dan seorang saksi dari keluarga wanita itu memberikan kesaksiannya: \"Jika baju gamisnya koyak di muka, maka wanita itu benar dan Yusuf termasuk orang-orang yang dusta.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 27, "text": "وَإِن كَانَ قَمِیصُهُۥ قُدَّ مِن دُبُرࣲ فَكَذَبَتۡ وَهُوَ مِنَ ٱلصَّـٰدِقِینَ ۝٢٧", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "وإن كان قميصه شُقَّ من الخلف فكذبت في قولها، وهو من الصادقين.", "isBasmala": false, "translation_en": "But if his shirt is torn from the back: then she has lied, and he is the truthful.\"", "translation_id": "Dan jika baju gamisnya koyak di belakang, maka wanita itulah yang dusta, dan Yusuf termasuk orang-orang yang benar\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 28, "text": "فَلَمَّا رَءَا قَمِیصَهُۥ قُدَّ مِن دُبُرࣲ قَالَ إِنَّهُۥ مِن كَیۡدِكُنَّۖ إِنَّ كَیۡدَكُنَّ عَظِیمࣱ ۝٢٨", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "فلما رأى الزوج قميص يوسف شُقَّ من خلفه علم براءة يوسف، وقال لزوجته: إن هذا الكذب الذي اتهمتِ به هذا الشاب هو مِن جملة مكركن -أيتها النساء-، إنَّ مكركن عظيم.", "isBasmala": false, "translation_en": "And when he saw that his shirt was torn from the back, he said, \"This is a woman's scheme. Your scheming is serious indeed.\"", "translation_id": "Maka tatkala suami wanita itu melihat baju gamis Yusuf koyak di belakang berkatalah dia: \"Sesungguhnya (kejadian) itu adalah diantara tipu daya kamu, sesungguhnya tipu daya kamu adalah besar\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 29, "text": "یُوسُفُ أَعۡرِضۡ عَنۡ هَـٰذَاۚ وَٱسۡتَغۡفِرِی لِذَنۢبِكِۖ إِنَّكِ كُنتِ مِنَ ٱلۡخَاطِـِٔینَ ۝٢٩", "juz": 12, "hizb": "(*½ ح 24*)", "tafsir": "قال عزيز \"مصر\": يا يوسف اترك ذِكْر ما كان منها فلا تذكره لأحد، واطلبي -أيتها المرأة- المغفرة لذنبك؛ إنك كنتِ من الآثمين في مراودة يوسف عن نفسه، وفي افترائك عليه.", "isBasmala": false, "translation_en": "\"Joseph, turn away from this. And you, woman, ask forgiveness for your sin; you are indeed in the wrong.\"", "translation_id": "(Hai) Yusuf: \"Berpalinglah dari ini, dan (kamu hai isteriku) mohon ampunlah atas dosamu itu, karena kamu sesungguhnya termasuk orang-orang yang berbuat salah\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 30, "text": "۞ وَقَالَ نِسۡوَةࣱ فِی ٱلۡمَدِینَةِ ٱمۡرَأَتُ ٱلۡعَزِیزِ تُرَ ٰوِدُ فَتَىٰهَا عَن نَّفۡسِهِۦۖ قَدۡ شَغَفَهَا حُبًّاۖ إِنَّا لَنَرَىٰهَا فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٣٠", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "ووصل الخبر إلى نسوة في المدينة فتحدثن به، وقلن منكرات على امرأة العزيز: امرأة العزيز تحاول غلامها عن نفسه، وتدعوه إلى نفسها، وقد بلغ حبها له شَغَاف قلبها (وهو غلافه)، إنا لَنراها في هذا الفعل لفي ضلال واضح.", "isBasmala": false, "translation_en": "Some ladies in the city said, \"The governor's wife is trying to seduce her servant. She is deeply in love with him. We see she has gone astray.\"", "translation_id": "Dan wanita-wanita di kota berkata: \"Isteri Al Aziz menggoda bujangnya untuk menundukkan dirinya (kepadanya), sesungguhnya cintanya kepada bujangnya itu adalah sangat mendalam. Sesungguhnya kami memandangnya dalam kesesatan yang nyata\".", "manzil": 3, "manzil_display": ""}], "239": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 31, "text": "فَلَمَّا سَمِعَتۡ بِمَكۡرِهِنَّ أَرۡسَلَتۡ إِلَیۡهِنَّ وَأَعۡتَدَتۡ لَهُنَّ مُتَّكَـࣰٔا وَءَاتَتۡ كُلَّ وَ ٰحِدَةࣲ مِّنۡهُنَّ سِكِّینࣰا وَقَالَتِ ٱخۡرُجۡ عَلَیۡهِنَّۖ فَلَمَّا رَأَیۡنَهُۥۤ أَكۡبَرۡنَهُۥ وَقَطَّعۡنَ أَیۡدِیَهُنَّ وَقُلۡنَ حَـٰشَ لِلَّهِ مَا هَـٰذَا بَشَرًا إِنۡ هَـٰذَاۤ إِلَّا مَلَكࣱ كَرِیمࣱ ۝٣١", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "فلما سمعت امرأة العزيز بغِيْبتهن إياها واحتيالهن في ذمِّها، أرسلت إليهن تدعوهن لزيارتها، وهيَّأت لهن ما يتكئن عليه من الوسائد، وما يأكلنه من الطعام، وأعطت كل واحدة منهن سكينًا ليُقَطِّعن الطعام، ثم قالت ليوسف: اخرج عليهن، فلما رأينه أعظمنه وأجللنه، وأخَذَهن حسنه وجماله، فجرحن أيديهن وهن يُقَطِّعن الطعام من فرط الدهشة والذهول، وقلن متعجبات: معاذ الله، ما هذا من جنس البشر؛ لأن جماله غير معهود في البشر، ما هو إلا مَلَك كريم من الملائكة.", "isBasmala": false, "translation_en": "And when she heard of their gossip, she invited them, and prepared for them a banquet, and she gave each one of them a knife. She said, \"Come out before them.\" And when they saw him, they marveled at him, and cut their hands. They said, \"Good God, this is not a human, this must be a precious angel.\"", "translation_id": "Maka tatkala wanita itu (Zulaikha) mendengar cercaan mereka, diundangnyalah wanita-wanita itu dan disediakannya bagi mereka tempat duduk, dan diberikannya kepada masing-masing mereka sebuah pisau (untuk memotong jamuan), kemudian dia berkata (kepada Yusuf): \"Keluarlah (nampakkanlah dirimu) kepada mereka\". Maka tatkala wanita-wanita itu melihatnya, mereka kagum kepada (keelokan rupa)nya, dan mereka melukai (jari) tangannya dan berkata: \"Maha sempurna Allah, ini bukanlah manusia. Sesungguhnya ini tidak lain hanyalah malaikat yang mulia\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 32, "text": "قَالَتۡ فَذَ ٰلِكُنَّ ٱلَّذِی لُمۡتُنَّنِی فِیهِۖ وَلَقَدۡ رَ ٰوَدتُّهُۥ عَن نَّفۡسِهِۦ فَٱسۡتَعۡصَمَۖ وَلَىِٕن لَّمۡ یَفۡعَلۡ مَاۤ ءَامُرُهُۥ لَیُسۡجَنَنَّ وَلَیَكُونࣰا مِّنَ ٱلصَّـٰغِرِینَ ۝٣٢", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "قالت امرأة العزيز للنسوة اللاتي قطَّعن أيديهن: فهذا الذي أصابكن في رؤيتكن إياه ما أصابكن هو الفتى الذي لُمتُنَّني في الافتتان به، ولقد طلبته وحاولت إغراءه؛ ليستجيب لي فامتنع وأبى، ولئن لم يفعل ما آمره به مستقبلا لَيعاقَبَنَّ بدخول السجن، ولَيكونن من الأذلاء.", "isBasmala": false, "translation_en": "She said, \"Here he is, the one you blamed me for. I did try to seduce him, but he resisted. But if he does not do what I tell him to do, he will be imprisoned, and will be one of the despised.\"", "translation_id": "Wanita itu berkata: \"Itulah dia orang yang kamu cela aku karena (tertarik) kepadanya, dan sesungguhnya aku telah menggoda dia untuk menundukkan dirinya (kepadaku) akan tetapi dia menolak. Dan sesungguhnya jika dia tidak mentaati apa yang aku perintahkan kepadanya, niscaya dia akan dipenjarakan dan dia akan termasuk golongan orang-orang yang hina\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 33, "text": "قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَیَّ مِمَّا یَدۡعُونَنِیۤ إِلَیۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّی كَیۡدَهُنَّ أَصۡبُ إِلَیۡهِنَّ وَأَكُن مِّنَ ٱلۡجَـٰهِلِینَ ۝٣٣", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "قال يوسف مستعيذًا مِن شرهن ومكرهن: يا ربِّ السجنُ أحب إليَّ مما يدعونني إليه من عمل الفاحشة، وإن لم تدفع عني مكرهن أَمِلْ إليهن، وأكن من السفهاء الذين يرتكبون الإثم لجهلهم.", "isBasmala": false, "translation_en": "He said, \"My Lord, prison is more desirable to me than what they call me to. Unless You turn their scheming away from me, I may yield to them, and become one of the ignorant.\"", "translation_id": "Yusuf berkata: \"Wahai Tuhanku, penjara lebih aku sukai daripada memenuhi ajakan mereka kepadaku. Dan jika tidak Engkau hindarkan dari padaku tipu daya mereka, tentu aku akan cenderung untuk (memenuhi keinginan mereka) dan tentulah aku termasuk orang-orang yang bodoh\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 34, "text": "فَٱسۡتَجَابَ لَهُۥ رَبُّهُۥ فَصَرَفَ عَنۡهُ كَیۡدَهُنَّۚ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٣٤", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "فاستجاب الله ليوسف دعاءه فصرف عنه ما أرادت منه امرأة العزيز وصواحباتها من معصية الله. إن الله هو السميع لدعاء يوسف، ودعاء كل داع مِن خلقه، العليم بمطلبه وحاجته وما يصلحه، وبحاجة جميع خلقه وما يصلحهم.", "isBasmala": false, "translation_en": "Thereupon his Lord answered him, and diverted their scheming away from him. He is the Hearer, the Knower.", "translation_id": "Maka Tuhannya memperkenankan doa Yusuf dan Dia menghindarkan Yusuf dari tipu daya mereka. Sesungguhnya Dialah Yang Maha Mendengar lagi Maha Mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 35, "text": "ثُمَّ بَدَا لَهُم مِّنۢ بَعۡدِ مَا رَأَوُا۟ ٱلۡـَٔایَـٰتِ لَیَسۡجُنُنَّهُۥ حَتَّىٰ حِینࣲ ۝٣٥", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "ثم ظهر للعزيز وأصحابه -من بعد ما رأوا الأدلة على براءة يوسف وعفته- أن يسجنوه إلى زمن يطول أو يقصر؛ منعًا للفضيحة.", "isBasmala": false, "translation_en": "Then it occurred to them, after they had seen the signs, to imprison him for a while.", "translation_id": "Kemudian timbul pikiran pada mereka setelah melihat tanda-tanda (kebenaran Yusuf) bahwa mereka harus memenjarakannya sampai sesuatu waktu.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 36, "text": "وَدَخَلَ مَعَهُ ٱلسِّجۡنَ فَتَیَانِۖ قَالَ أَحَدُهُمَاۤ إِنِّیۤ أَرَىٰنِیۤ أَعۡصِرُ خَمۡرࣰاۖ وَقَالَ ٱلۡـَٔاخَرُ إِنِّیۤ أَرَىٰنِیۤ أَحۡمِلُ فَوۡقَ رَأۡسِی خُبۡزࣰا تَأۡكُلُ ٱلطَّیۡرُ مِنۡهُۖ نَبِّئۡنَا بِتَأۡوِیلِهِۦۤۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِینَ ۝٣٦", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "ودخل السجن مع يوسف فَتَيان، قال أحدهما: إني رأيت في المنام أني أعصر عنبًا ليصير خمرًا، وقال الآخر: إني رأيت أني أحمل فوق رأسي خبزًا تأكل الطير منه، أخبرنا -يا يوسف -بتفسير ما رأينا، إنا نراك من الذين يحسنون في عبادتهم لله، ومعاملتهم لخلقه.", "isBasmala": false, "translation_en": "Two youth entered the prison with him. One of them said, \"I see myself pressing wine.\" The other said, \"I see myself carrying bread on my head, from which the birds are eating. Tell us their interpretation-we see that you are one of the righteous.\"", "translation_id": "Dan bersama dengan dia masuk pula ke dalam penjara dua orang pemuda. Berkatalah salah seorang diantara keduanya: \"Sesungguhnya aku bermimpi, bahwa aku memeras anggur\". Dan yang lainnya berkata: \"Sesungguhnya aku bermimpi, bahwa aku membawa roti di atas kepalaku, sebahagiannya dimakan burung\". Berikanlah kepada kami ta'birnya; sesungguhnya kami memandang kamu termasuk orang-orang yang pandai (mena'birkan mimpi).", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 37, "text": "قَالَ لَا یَأۡتِیكُمَا طَعَامࣱ تُرۡزَقَانِهِۦۤ إِلَّا نَبَّأۡتُكُمَا بِتَأۡوِیلِهِۦ قَبۡلَ أَن یَأۡتِیَكُمَاۚ ذَ ٰلِكُمَا مِمَّا عَلَّمَنِی رَبِّیۤۚ إِنِّی تَرَكۡتُ مِلَّةَ قَوۡمࣲ لَّا یُؤۡمِنُونَ بِٱللَّهِ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ كَـٰفِرُونَ ۝٣٧", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "قال لهما يوسف: لا يأتيكما طعام ترزقانه في حال من الأحوال إلا أخبرتكما بتفسيره قبل أن يأتيكما، ذلكما التعبير الذي سأعبِّره لكما مما علَّمني ربي؛ إني آمنت به، وأخلصت له العبادة، وابتعدت عن دين قوم لا يؤمنون بالله، وهم بالبعث والحساب جاحدون.", "isBasmala": false, "translation_en": "He said, \"No food is served to you, but I have informed you about it before you have received it. That is some of what my Lord has taught me. I have forsaken the tradition of people who do not believe in God; and regarding the Hereafter, they are deniers.\"", "translation_id": "Yusuf berkata: \"Tidak disampaikan kepada kamu berdua makanan yang akan diberikan kepadamu melainkan aku telah dapat menerangkan jenis makanan itu, sebelum makanan itu sampai kepadamu. Yang demikian itu adalah sebagian dari apa yang diajarkan kepadaku oleh Tuhanku. Sesungguhnya aku telah meninggalkan agama orang-orang yang tidak beriman kepada Allah, sedang mereka ingkar kepada hari kemudian.", "manzil": 3, "manzil_display": ""}], "240": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 38, "text": "وَٱتَّبَعۡتُ مِلَّةَ ءَابَاۤءِیۤ إِبۡرَ ٰهِیمَ وَإِسۡحَـٰقَ وَیَعۡقُوبَۚ مَا كَانَ لَنَاۤ أَن نُّشۡرِكَ بِٱللَّهِ مِن شَیۡءࣲۚ ذَ ٰلِكَ مِن فَضۡلِ ٱللَّهِ عَلَیۡنَا وَعَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَشۡكُرُونَ ۝٣٨", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "واتبعت دين آبائي إبراهيم وإسحاق ويعقوب فعبدت الله وحده، ما كان لنا أن نجعل لله شريكًا في عبادته، ذلك التوحيد بإفراد الله بالعبادة، مما تفضل الله به علينا وعلى الناس، ولكن أكثر الناس لا يشكرون الله على نعمة التوحيد والإيمان.", "isBasmala": false, "translation_en": "\"And I have followed the faith of my forefathers, Abraham, and Isaac, and Jacob. It is not for us to associate anything with God. This is by virtue of God's grace upon us and upon the people, but most people do not give thanks.", "translation_id": "Dan aku pengikut agama bapak-bapakku yaitu Ibrahim, Ishak dan Ya'qub. Tiadalah patut bagi kami (para Nabi) mempersekutukan sesuatu apapun dengan Allah. Yang demikian itu adalah dari karunia Allah kepada kami dan kepada manusia (seluruhnya); tetapi kebanyakan manusia tidak mensyukuri (Nya).", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 39, "text": "یَـٰصَـٰحِبَیِ ٱلسِّجۡنِ ءَأَرۡبَابࣱ مُّتَفَرِّقُونَ خَیۡرٌ أَمِ ٱللَّهُ ٱلۡوَ ٰحِدُ ٱلۡقَهَّارُ ۝٣٩", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "وقال يوسف للفَتَيين اللذين معه في السجن: أعبادةُ آلهةٍ مخلوقة شتى خير أم عبادة الله الواحد القهار؟", "isBasmala": false, "translation_en": "\"O My fellow inmates, are diverse lords better, or God, the One, the Supreme?\"", "translation_id": "Hai kedua penghuni penjara, manakah yang baik, tuhan-tuhan yang bermacam-macam itu ataukah Allah Yang Maha Esa lagi Maha Perkasa?", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 40, "text": "مَا تَعۡبُدُونَ مِن دُونِهِۦۤ إِلَّاۤ أَسۡمَاۤءࣰ سَمَّیۡتُمُوهَاۤ أَنتُمۡ وَءَابَاۤؤُكُم مَّاۤ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَـٰنٍۚ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِ أَمَرَ أَلَّا تَعۡبُدُوۤا۟ إِلَّاۤ إِیَّاهُۚ ذَ ٰلِكَ ٱلدِّینُ ٱلۡقَیِّمُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٤٠", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "ما تعبدون من دون الله إلا أسماءً لا معاني وراءها، جعلتموها أنتم وآباؤكم أربابًا جهلا منكم وضلالا، ما أنزل الله من حجة أو برهان على صحتها، ما الحكم الحق إلا لله تعالى وحده، لا شريك له، أمر ألا تنقادوا ولا تخضعوا لغيره، وأن تعبدوه وحده، وهذا هو الدين القيم الذي لا عوج فيه، ولكن أكثر الناس يجهلون ذلك، فلا يعلمون حقيقته.", "isBasmala": false, "translation_en": "\"You do not worship, besides Him, except names you have named, you and your ancestors, for which God has sent down no authority. Judgment belongs to none but God. He has commanded that you worship none but Him. This is the right religion, but most people do not know.", "translation_id": "Kamu tidak menyembah yang selain Allah kecuali hanya (menyembah) nama-nama yang kamu dan nenek moyangmu membuat-buatnya. Allah tidak menurunkan suatu keteranganpun tentang nama-nama itu. Keputusan itu hanyalah kepunyaan Allah. Dia telah memerintahkan agar kamu tidak menyembah selain Dia. Itulah agama yang lurus, tetapi kebanyakan manusia tidak mengetahui\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 41, "text": "یَـٰصَـٰحِبَیِ ٱلسِّجۡنِ أَمَّاۤ أَحَدُكُمَا فَیَسۡقِی رَبَّهُۥ خَمۡرࣰاۖ وَأَمَّا ٱلۡـَٔاخَرُ فَیُصۡلَبُ فَتَأۡكُلُ ٱلطَّیۡرُ مِن رَّأۡسِهِۦۚ قُضِیَ ٱلۡأَمۡرُ ٱلَّذِی فِیهِ تَسۡتَفۡتِیَانِ ۝٤١", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "يا صاحبيَّ في السجن، إليكما تفسيرَ رؤياكما: أما الذي رأى أنه يعصر العنب في رؤياه فإنه يخرج من السجن ويكون ساقي الخمر للملك، وأما الآخر الذي رأى أنه يحمل على رأسه خبزًا فإنه يُصْلب ويُتْرك، وتأكل الطير من رأسه، قُضي الأمر الذي فيه تستفتيان وفُرغ منه.", "isBasmala": false, "translation_en": "\"O my fellow inmates! One of you will serve his master wine; while the other will be crucified, and the birds will eat from his head. Thus the matter you are inquiring about is settled.\"", "translation_id": "Hai kedua penghuni penjara: \"Adapun salah seorang diantara kamu berdua, akan memberi minuman tuannya dengan khamar; adapun yang seorang lagi maka ia akan disalib, lalu burung memakan sebagian dari kepalanya. Telah diputuskan perkara yang kamu berdua menanyakannya (kepadaku)\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 42, "text": "وَقَالَ لِلَّذِی ظَنَّ أَنَّهُۥ نَاجࣲ مِّنۡهُمَا ٱذۡكُرۡنِی عِندَ رَبِّكَ فَأَنسَىٰهُ ٱلشَّیۡطَـٰنُ ذِكۡرَ رَبِّهِۦ فَلَبِثَ فِی ٱلسِّجۡنِ بِضۡعَ سِنِینَ ۝٤٢", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "وقال يوسف للذي علم أنه ناجٍ من صاحبيه: اذكرني عند سيِّدك الملك وأخبره بأني مظلوم محبوس بلا ذنب، فأنسى الشيطان ذلك الرجل أن يذكر للملك حال يوسف، فمكث يوسف بعد ذلك في السجن عدة سنوات.", "isBasmala": false, "translation_en": "And he said to the one he thought would be released, \"Mention me to your master.\" But Satan caused him to forget mentioning him to his master, so he remained in prison for several years.", "translation_id": "Dan Yusuf berkata kepada orang yang diketahuinya akan selamat diantara mereka berdua: \"Terangkanlah keadaanku kepada tuanmu\". Maka syaitan menjadikan dia lupa menerangkan (keadaan Yusuf) kepada tuannya. Karena itu tetaplah dia (Yusuf) dalam penjara beberapa tahun lamanya.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 43, "text": "وَقَالَ ٱلۡمَلِكُ إِنِّیۤ أَرَىٰ سَبۡعَ بَقَرَ ٰتࣲ سِمَانࣲ یَأۡكُلُهُنَّ سَبۡعٌ عِجَافࣱ وَسَبۡعَ سُنۢبُلَـٰتٍ خُضۡرࣲ وَأُخَرَ یَابِسَـٰتࣲۖ یَـٰۤأَیُّهَا ٱلۡمَلَأُ أَفۡتُونِی فِی رُءۡیَـٰیَ إِن كُنتُمۡ لِلرُّءۡیَا تَعۡبُرُونَ ۝٤٣", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "وقال الملك: إني رأيت في منامي سبع بقرات سمان، يأكلهن سبع بقرات نحيلات من الهُزال، ورأيت سبع سنبلات خضر، وسبع سنبلات يابسات، يا أيها السادة والكبراء أخبروني عن هذه الرؤيا، إن كنتم للرؤيا تُفَسِّرون.", "isBasmala": false, "translation_en": "The king said, \"I see seven fat cows being eaten by seven lean ones, and seven green spikes, and others dried up. O elders, explain to me my vision, if you are able to interpret visions.\"", "translation_id": "Raja berkata (kepada orang-orang terkemuka dari kaumnya): \"Sesungguhnya aku bermimpi melihat tujuh ekor sapi betina yang gemuk-gemuk dimakan oleh tujuh ekor sapi betina yang kurus-kurus dan tujuh bulir (gandum) yang hijau dan tujuh bulir lainnya yang kering\". Hai orang-orang yang terkemuka: \"Terangkanlah kepadaku tentang ta'bir mimpiku itu jika kamu dapat mena'birkan mimpi\".", "manzil": 3, "manzil_display": ""}], "241": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 44, "text": "قَالُوۤا۟ أَضۡغَـٰثُ أَحۡلَـٰمࣲۖ وَمَا نَحۡنُ بِتَأۡوِیلِ ٱلۡأَحۡلَـٰمِ بِعَـٰلِمِینَ ۝٤٤", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "قالوا: رؤياك هذه أخلاط أحلام لا تأويل لها، وما نحن بتفسير الأحلام بعالمين.", "isBasmala": false, "translation_en": "They said, \"Jumbles of dreams, and we know nothing of the interpretation of dreams.\"", "translation_id": "Mereka menjawab: \"(Itu) adalah mimpi-mimpi yang kosong dan kami sekali-kali tidak tahu menta'birkan mimpi itu\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 45, "text": "وَقَالَ ٱلَّذِی نَجَا مِنۡهُمَا وَٱدَّكَرَ بَعۡدَ أُمَّةٍ أَنَا۠ أُنَبِّئُكُم بِتَأۡوِیلِهِۦ فَأَرۡسِلُونِ ۝٤٥", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "وقال الذي نجا من القتل من صاحبَي يوسف في السجن وتذكر بعد مدة ما نسي من أمر يوسف: أنا أخبركم بتأويل هذه الرؤيا، فابعثوني إلى يوسف لآتيكم بتفسيرها.", "isBasmala": false, "translation_en": "The one who was released said, having remembered after a time, \"I will inform you of its interpretation, so send me out.\"", "translation_id": "Dan berkatalah orang yang selamat diantara mereka berdua dan teringat (kepada Yusuf) sesudah beberapa waktu lamanya: \"Aku akan memberitakan kepadamu tentang (orang yang pandai) mena'birkan mimpi itu, maka utuslah aku (kepadanya)\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 46, "text": "یُوسُفُ أَیُّهَا ٱلصِّدِّیقُ أَفۡتِنَا فِی سَبۡعِ بَقَرَ ٰتࣲ سِمَانࣲ یَأۡكُلُهُنَّ سَبۡعٌ عِجَافࣱ وَسَبۡعِ سُنۢبُلَـٰتٍ خُضۡرࣲ وَأُخَرَ یَابِسَـٰتࣲ لَّعَلِّیۤ أَرۡجِعُ إِلَى ٱلنَّاسِ لَعَلَّهُمۡ یَعۡلَمُونَ ۝٤٦", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "وعندما وصل الرجل إلى يوسف قال له: يوسف أيها الصديق فسِّر لنا رؤيا مَن رأى سبع بقرات سمان يأكلهن سبع بقرات هزيلات، ورأى سبع سنبلات خضر وأخر يابسات؛ لعلي أرجع إلى الملك وأصحابه فأخبرهم؛ ليعلموا تأويل ما سألتك عنه، وليعلموا مكانتك وفضلك.", "isBasmala": false, "translation_en": "\"Joseph, O man of truth, inform us concerning seven fat cows being eaten by seven lean ones, and seven green spikes, and others dried up, so that I may return to the people, so that they may know.\"", "translation_id": "(Setelah pelayan itu berjumpa dengan Yusuf dia berseru): \"Yusuf, hai orang yang amat dipercaya, terangkanlah kepada kami tentang tujuh ekor sapi betina yang gemuk-gemuk yang dimakan oleh tujuh ekor sapi betina yang kurus-kurus dan tujuh bulir (gandum) yang hijau dan (tujuh) lainnya yang kering agar aku kembali kepada orang-orang itu, agar mereka mengetahuinya\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 47, "text": "قَالَ تَزۡرَعُونَ سَبۡعَ سِنِینَ دَأَبࣰا فَمَا حَصَدتُّمۡ فَذَرُوهُ فِی سُنۢبُلِهِۦۤ إِلَّا قَلِیلࣰا مِّمَّا تَأۡكُلُونَ ۝٤٧", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "قال يوسف لسائله عن رؤيا الملك: تفسير هذه الرؤيا أنكم تزرعون سبع سنين متتابعة جادِّين ليَكْثُر العطاء، فما حصدتم منه في كل مرة فادَّخِروه، واتركوه في سنبله؛ ليتمَّ حفظه من التسوُّس، وليكون أبقى، إلا قليلا مما تأكلونه من الحبوب.", "isBasmala": false, "translation_en": "He said, \"You will farm for seven consecutive years. But whatever you harvest, leave it in its spikes, except for the little that you eat.\"", "translation_id": "Yusuf berkata: \"Supaya kamu bertanam tujuh tahun (lamanya) sebagaimana biasa; maka apa yang kamu tuai hendaklah kamu biarkan dibulirnya kecuali sedikit untuk kamu makan.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 48, "text": "ثُمَّ یَأۡتِی مِنۢ بَعۡدِ ذَ ٰلِكَ سَبۡعࣱ شِدَادࣱ یَأۡكُلۡنَ مَا قَدَّمۡتُمۡ لَهُنَّ إِلَّا قَلِیلࣰا مِّمَّا تُحۡصِنُونَ ۝٤٨", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "ثم يأتي بعد هذه السنين الخِصْبة سبع سنين شديدة الجَدْب، يأكل أهلها كل ما ادَّخرتم لهن من قبل، إلا قليلا مما تحفظونه وتدَّخرونه ليكون بذورًا للزراعة.", "isBasmala": false, "translation_en": "Then after that will come seven difficult ones, which will consume what you have stored for them, except for the little that you have preserved.", "translation_id": "Kemudian sesudah itu akan datang tujuh tahun yang amat sulit, yang menghabiskan apa yang kamu simpan untuk menghadapinya (tahun sulit), kecuali sedikit dari (bibit gandum) yang kamu simpan.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 49, "text": "ثُمَّ یَأۡتِی مِنۢ بَعۡدِ ذَ ٰلِكَ عَامࣱ فِیهِ یُغَاثُ ٱلنَّاسُ وَفِیهِ یَعۡصِرُونَ ۝٤٩", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "ثم يأتي من بعد هذه السنين المجدبة عام يغاث فيه الناس بالمطر، فيرفع الله تعالى عنهم الشدة، ويعصرون فيه الثمار من كثرة الخِصْب والنماء.", "isBasmala": false, "translation_en": "Then after that will come a year that brings relief to the people, and during which they will press.", "translation_id": "Kemudian setelah itu akan datang tahun yang padanya manusia diberi hujan (dengan cukup) dan dimasa itu mereka memeras anggur\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 50, "text": "وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِی بِهِۦۖ فَلَمَّا جَاۤءَهُ ٱلرَّسُولُ قَالَ ٱرۡجِعۡ إِلَىٰ رَبِّكَ فَسۡـَٔلۡهُ مَا بَالُ ٱلنِّسۡوَةِ ٱلَّـٰتِی قَطَّعۡنَ أَیۡدِیَهُنَّۚ إِنَّ رَبِّی بِكَیۡدِهِنَّ عَلِیمࣱ ۝٥٠", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "وقال الملك لأعوانه: أخرجوا الرجل المعبِّر للرؤيا من السجن وأحضروه لي، فلما جاءه رسول الملك يدعوه قال يوسف للرسول: ارجع إلى سيدك الملك، واطلب منه أن يسأل النسوة اللاتي جرحن أيديهن عن حقيقة أمرهن وشأنهن معي؛ لتظهر الحقيقة للجميع، وتتضح براءتي، إن ربي عليم بصنيعهن وأفعالهن لا يخفى عليه شيء من ذلك.", "isBasmala": false, "translation_en": "The king said, \"Bring him to me.\" And when the envoy came to him, he said, \"Go back to your master, and ask him about the intentions of the women who cut their hands; my Lord is well aware of their schemes.\"", "translation_id": "Raja berkata: \"Bawalah dia kepadaku\". Maka tatkala utusan itu datang kepada Yusuf, berkatalah Yusuf: \"Kembalilah kepada tuanmu dan tanyakanlah kepadanya bagaimana halnya wanita-wanita yang telah melukai tangannya. Sesungguhnya Tuhanku, Maha Mengetahui tipu daya mereka\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 51, "text": "قَالَ مَا خَطۡبُكُنَّ إِذۡ رَ ٰوَدتُّنَّ یُوسُفَ عَن نَّفۡسِهِۦۚ قُلۡنَ حَـٰشَ لِلَّهِ مَا عَلِمۡنَا عَلَیۡهِ مِن سُوۤءࣲۚ قَالَتِ ٱمۡرَأَتُ ٱلۡعَزِیزِ ٱلۡـَٔـٰنَ حَصۡحَصَ ٱلۡحَقُّ أَنَا۠ رَ ٰوَدتُّهُۥ عَن نَّفۡسِهِۦ وَإِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِینَ ۝٥١", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "قال الملك للنسوة اللاتي جرحن أيديهن: ما شأنكن حين راودتنَّ يوسف عن نفسه يوم الضيافة؟ فهل رأيتن منه ما يريب؟ قلن: معاذ الله ما علمنا عليه أدنى شيء يَشينه، عند ذلك قالت امراة العزيز: الآن ظهر الحق بعد خفائه، فأنا التي حاولت فتنته بإغرائه فامتنع، وإنه لمن الصادقين في كل ما قاله.", "isBasmala": false, "translation_en": "He said, \"What was the matter with you, women, when you tried to seduce Joseph?\" They said, \"God forbid! We knew of no evil committed by him.\" The governor's wife then said, \"Now the truth is out. It was I who tried to seduce him, and he is telling the truth.\"", "translation_id": "Raja berkata (kepada wanita-wanita itu): \"Bagaimana keadaanmu ketika kamu menggoda Yusuf untuk menundukkan dirinya (kepadamu)?\" Mereka berkata: \"Maha Sempurna Allah, kami tiada mengetahui sesuatu keburukan dari padanya\". Berkata isteri Al Aziz: \"Sekarang jelaslah kebenaran itu, akulah yang menggodanya untuk menundukkan dirinya (kepadaku), dan sesungguhnya dia termasuk orang-orang yang benar\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 52, "text": "ذَ ٰلِكَ لِیَعۡلَمَ أَنِّی لَمۡ أَخُنۡهُ بِٱلۡغَیۡبِ وَأَنَّ ٱللَّهَ لَا یَهۡدِی كَیۡدَ ٱلۡخَاۤىِٕنِینَ ۝٥٢", "juz": 12, "hizb": "(*¾ ح 24*)", "tafsir": "ذلك القول الذي قلته في تنزيهه والإقرار على نفسي ليعلم زوجي أني لم أخنه بالكذب عليه، ولم تقع مني الفاحشة، وأنني راودته، واعترفت بذلك لإظهار براءتي وبراءته، وأن الله لا يوفق أهل الخيانة، ولا يرشدهم في خيانتهم.", "isBasmala": false, "translation_en": "\"This is that he may know that I did not betray him in secret, and that God does not guide the scheming of the betrayers.\"", "translation_id": "(Yusuf berkata): \"Yang demikian itu agar dia (Al Aziz) mengetahui bahwa sesungguhnya aku tidak berkhianat kepadanya di belakangnya, dan bahwasanya Allah tidak meridhai tipu daya orang-orang yang berkhianat.", "manzil": 3, "manzil_display": ""}], "242": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 53, "text": "۞ وَمَاۤ أُبَرِّئُ نَفۡسِیۤۚ إِنَّ ٱلنَّفۡسَ لَأَمَّارَةُۢ بِٱلسُّوۤءِ إِلَّا مَا رَحِمَ رَبِّیۤۚ إِنَّ رَبِّی غَفُورࣱ رَّحِیمࣱ ۝٥٣", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "قالت امرأة العزيز: وما أزكي نفسي ولا أبرئها، إن النفس لكثيرة الأمر لصاحبها بعمل المعاصي طلبا لملذاتها، إلا مَن عصمه الله. إن الله غفور لذنوب مَن تاب مِن عباده، رحيم بهم.", "isBasmala": false, "translation_en": "\"Yet I do not claim to be innocent. The soul commands evil, except those on whom my Lord has mercy. Truly my Lord is Forgiving and Merciful.\"", "translation_id": "Dan aku tidak membebaskan diriku (dari kesalahan), karena sesungguhnya nafsu itu selalu menyuruh kepada kejahatan, kecuali nafsu yang diberi rahmat oleh Tuhanku. Sesungguhnya Tuhanku Maha Pengampun lagi Maha Penyanyang.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 54, "text": "وَقَالَ ٱلۡمَلِكُ ٱئۡتُونِی بِهِۦۤ أَسۡتَخۡلِصۡهُ لِنَفۡسِیۖ فَلَمَّا كَلَّمَهُۥ قَالَ إِنَّكَ ٱلۡیَوۡمَ لَدَیۡنَا مَكِینٌ أَمِینࣱ ۝٥٤", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "وقال الملك الحاكم لـ \"مصر\" حين بلغته براءة يوسف: جيئوني به أجعله من خلصائي وأهل مشورتي، فلما جاء يوسف وكلَّمه الملك، وعرف براءته، وعظيم أمانته، وحسن خلقه، قال له: إنك اليوم عندنا عظيم المكانة، ومؤتمن على كل شيء.", "isBasmala": false, "translation_en": "The king said, \"Bring him to me, and I will reserve him for myself.\" And when he spoke to him, he said, \"This day you are with us established and secure.\"", "translation_id": "Dan raja berkata: \"Bawalah Yusuf kepadaku, agar aku memilih dia sebagai orang yang rapat kepadaku\". Maka tatkala raja telah bercakap-cakap dengan dia, dia berkata: \"Sesungguhnya kamu (mulai) hari ini menjadi seorang yang berkedudukan tinggi lagi dipercayai pada sisi kami\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 55, "text": "قَالَ ٱجۡعَلۡنِی عَلَىٰ خَزَاۤىِٕنِ ٱلۡأَرۡضِۖ إِنِّی حَفِیظٌ عَلِیمࣱ ۝٥٥", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "وأراد يوسف أن ينفع العباد، ويقيم العدل بينهم، فقال للملك: اجعلني واليًا على خزائن \"مصر\"، فإني خازن أمين، ذو علم وبصيرة بما أتولاه.", "isBasmala": false, "translation_en": "He said, \"Put me in charge of the storehouses of the land; I am honest and knowledgeable.\"", "translation_id": "Berkata Yusuf: \"Jadikanlah aku bendaharawan negara (Mesir); sesungguhnya aku adalah orang yang pandai menjaga, lagi berpengetahuan\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 56, "text": "وَكَذَ ٰلِكَ مَكَّنَّا لِیُوسُفَ فِی ٱلۡأَرۡضِ یَتَبَوَّأُ مِنۡهَا حَیۡثُ یَشَاۤءُۚ نُصِیبُ بِرَحۡمَتِنَا مَن نَّشَاۤءُۖ وَلَا نُضِیعُ أَجۡرَ ٱلۡمُحۡسِنِینَ ۝٥٦", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "وكما أنعم الله على يوسف بالخلاص من السجن مكَّن له في أرض \"مصر\" ينزل منها أي منزل شاءه. يصيب الله برحمته من يشاء من عباده المتقين، ولا يضيع أجر مَن أحسن شيئًا مِن العمل الصالح.", "isBasmala": false, "translation_en": "And thus We established Joseph in the land, to live therein wherever he wished. We touch with Our mercy whomever We will, and We never waste the reward of the righteous.", "translation_id": "Dan demikianlah Kami memberi kedudukan kepada Yusuf di negeri Mesir; (dia berkuasa penuh) pergi menuju kemana saja ia kehendaki di bumi Mesir itu. Kami melimpahkan rahmat Kami kepada siapa yang Kami kehendaki dan Kami tidak menyia-nyiakan pahala orang-orang yang berbuat baik.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 57, "text": "وَلَأَجۡرُ ٱلۡـَٔاخِرَةِ خَیۡرࣱ لِّلَّذِینَ ءَامَنُوا۟ وَكَانُوا۟ یَتَّقُونَ ۝٥٧", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "ولَثواب الآخرة عند الله أعظم من ثواب الدنيا لأهل الإيمان والتقوى الذين يخافون عقاب الله، ويطيعونه في أمره ونهيه.", "isBasmala": false, "translation_en": "But the reward of the Hereafter is better for those who believe and observed piety.", "translation_id": "Dan sesungguhnya pahala di akhirat itu lebih baik, bagi orang-orang yang beriman dan selalu bertakwa.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 58, "text": "وَجَاۤءَ إِخۡوَةُ یُوسُفَ فَدَخَلُوا۟ عَلَیۡهِ فَعَرَفَهُمۡ وَهُمۡ لَهُۥ مُنكِرُونَ ۝٥٨", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "وقدِمَ إخوة يوسف إلى \"مصر\" -بعد أن حلَّ بهم الجدب في أرضهم-؛ ليجلبوا منها الطعام، فدخلوا عليه فعرفهم، ولم يعرفوه لطول المدة وتغيُّر هيئته.", "isBasmala": false, "translation_en": "And Joseph's brothers came, and entered into his presence. He recognized them, but they did not recognize him.", "translation_id": "Dan saudara-saudara Yusuf datang (ke Mesir} lalu mereka masuk ke (tempat)nya. Maka Yusuf mengenal mereka, sedang mereka tidak kenal (lagi) kepadanya.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 59, "text": "وَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ قَالَ ٱئۡتُونِی بِأَخࣲ لَّكُم مِّنۡ أَبِیكُمۡۚ أَلَا تَرَوۡنَ أَنِّیۤ أُوفِی ٱلۡكَیۡلَ وَأَنَا۠ خَیۡرُ ٱلۡمُنزِلِینَ ۝٥٩", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "وقد أمر يوسف بإكرامهم وحسن ضيافتهم، ثم أعطاهم من الطعام ما طلبوا، وكانوا قد أخبروه أن لهم أخًا من أبيهم لم يُحضروه معهم -يريدون شقيقه- فقال: ائتوني بأخيكم من أبيكم، ألم تروا أني أوفيتُ لكم الكيل وأكرمتكم في الضيافة، وأنا خير المضيفين لكم؟", "isBasmala": false, "translation_en": "When he provided them with their provisions, he said, \"Bring me a brother of yours from your father. Do you not see that I fill up the measure, and I am the best of hosts?\"", "translation_id": "Dan tatkala Yusuf menyiapkan untuk mereka bahan makanannya, ia berkata: \"Bawalah kepadaku saudaramu yang seayah dengan kamu (Bunyamin), tidakkah kamu melihat bahwa aku menyempurnakan sukatan dan aku adalah sebaik-baik penerima tamu?", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 60, "text": "فَإِن لَّمۡ تَأۡتُونِی بِهِۦ فَلَا كَیۡلَ لَكُمۡ عِندِی وَلَا تَقۡرَبُونِ ۝٦٠", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "فإن لم تأتوني به فليس لكم عندي طعام أكيله لكم، ولا تأتوا إليَّ.", "isBasmala": false, "translation_en": "\"But if you do not bring him to me, you will have no measure from me, and you will not come near me.\"", "translation_id": "Jika kamu tidak membawanya kepadaku, maka kamu tidak akan mendapat sukatan lagi dari padaku dan jangan kamu mendekatiku\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 61, "text": "قَالُوا۟ سَنُرَ ٰوِدُ عَنۡهُ أَبَاهُ وَإِنَّا لَفَـٰعِلُونَ ۝٦١", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "قالوا: سنبذل جهدنا لإقناع أبيه أن يرسله معنا، ولن نقصِّر في ذلك.", "isBasmala": false, "translation_en": "They said, \"We will solicit him from his father. We will surely do.\"", "translation_id": "Mereka berkata: \"Kami akan membujuk ayahnya untuk membawanya (ke mari) dan sesungguhnya kami benar-benar akan melaksanakannya\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 62, "text": "وَقَالَ لِفِتۡیَـٰنِهِ ٱجۡعَلُوا۟ بِضَـٰعَتَهُمۡ فِی رِحَالِهِمۡ لَعَلَّهُمۡ یَعۡرِفُونَهَاۤ إِذَا ٱنقَلَبُوۤا۟ إِلَىٰۤ أَهۡلِهِمۡ لَعَلَّهُمۡ یَرۡجِعُونَ ۝٦٢", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "وقال يوسف لغلمانه: اجعلوا ثمن ما أخذوه في أمتعتهم سرًا؛ رجاء أن يعرفوه إذا رجعوا إلى أهلهم، ويقدِّروا إكرامنا لهم؛ ليرجعوا طمعًا في عطائنا.", "isBasmala": false, "translation_en": "He said to his servants, \"Put their goods in their saddlebags; perhaps they will recognize them when they return to their families, and maybe they will come back.\"", "translation_id": "Yusuf berkata kepada bujang-bujangnya: \"Masukkanlah barang-barang (penukar kepunyaan mereka) ke dalam karung-karung mereka, supaya mereka mengetahuinya apabila mereka telah kembali kepada keluarganya, mudah-mudahan mereka kembali lagi\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 63, "text": "فَلَمَّا رَجَعُوۤا۟ إِلَىٰۤ أَبِیهِمۡ قَالُوا۟ یَـٰۤأَبَانَا مُنِعَ مِنَّا ٱلۡكَیۡلُ فَأَرۡسِلۡ مَعَنَاۤ أَخَانَا نَكۡتَلۡ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ ۝٦٣", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "فلما رجعوا إلى أبيهم قصُّوا عليه ما كان من إكرام العزيز لهم، وقالوا: إنه لن يعطينا مستقبَلا إلا إذا كان معنا أخونا الذي أخبرناه به، فأرسلْه معنا نحضر الطعام وافيًا، ونتعهد لك بحفظه.", "isBasmala": false, "translation_en": "When they returned to their father, they said, \"O father, we were denied measure, but send our brother with us, and we will obtain measure. We will take care of him.\"", "translation_id": "Maka tatkala mereka telah kembali kepada ayah mereka (Ya'qub) mereka berkata: \"Wahai ayah kami, kami tidak akan mendapat sukatan (gandum) lagi, (jika tidak membawa saudara kami), sebab itu biarkanlah saudara kami pergi bersama-sama kami supaya kami mendapat sukatan, dan sesungguhnya kami benar benar akan menjaganya\".", "manzil": 3, "manzil_display": ""}], "243": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 64, "text": "قَالَ هَلۡ ءَامَنُكُمۡ عَلَیۡهِ إِلَّا كَمَاۤ أَمِنتُكُمۡ عَلَىٰۤ أَخِیهِ مِن قَبۡلُ فَٱللَّهُ خَیۡرٌ حَـٰفِظࣰاۖ وَهُوَ أَرۡحَمُ ٱلرَّ ٰحِمِینَ ۝٦٤", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "قال لهم أبوهم: كيف آمنكم على \"بنيامين\" وقد أمنتكم على أخيه يوسف من قبل، والتزمتم بحفظه فلم تفوا بذلك؟ فلا أثق بالتزامكم وحفظكم، ولكني أثق بحفظ الله، خير الحافظين وأرحم الراحمين، أرجو أن يرحمني فيحفظه ويرده عليَّ.", "isBasmala": false, "translation_en": "He said, \"Shall I trust you with him, as I trusted you with his brother before? God is the Best Guardian, and He is the Most Merciful of the merciful.\"", "translation_id": "Berkata Ya'qub: \"Bagaimana aku akan mempercayakannya (Bunyamin) kepadamu, kecuali seperti aku telah mempercayakan saudaranya (Yusuf) kepada kamu dahulu?\". Maka Allah adalah sebaik-baik Penjaga dan Dia adalah Maha Penyanyang diantara para penyanyang.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 65, "text": "وَلَمَّا فَتَحُوا۟ مَتَـٰعَهُمۡ وَجَدُوا۟ بِضَـٰعَتَهُمۡ رُدَّتۡ إِلَیۡهِمۡۖ قَالُوا۟ یَـٰۤأَبَانَا مَا نَبۡغِیۖ هَـٰذِهِۦ بِضَـٰعَتُنَا رُدَّتۡ إِلَیۡنَاۖ وَنَمِیرُ أَهۡلَنَا وَنَحۡفَظُ أَخَانَا وَنَزۡدَادُ كَیۡلَ بَعِیرࣲۖ ذَ ٰلِكَ كَیۡلࣱ یَسِیرࣱ ۝٦٥", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "ولما فتحوا أوعيتهم وجدوا ثمن بضاعتهم الذي دفعوه قد رُدَّ إليهم قالوا: يا أبانا ماذا نطلب أكثر من هذا؟ هذا ثمن بضاعتنا ردَّه العزيز إلينا، فكن مطمئنًا على أخينا، وأرسله معنا؛ لنجلب طعامًا وفيرًا لأهلنا، ونحفظ أخانا، ونزداد حِمْلَ بعير له؛ فإن العزيز يكيل لكل واحد حِمْلَ بعير، وذلك كيل يسير عليه.", "isBasmala": false, "translation_en": "And when they opened their baggage, they found that their goods were returned to them. They said, \"Father, what more do we want? Here are our goods, returned to us. We will provide for our family, and protect our brother, and have an additional camel-load. This is easy commerce.\"", "translation_id": "Tatkala mereka membuka barang-barangnya, mereka menemukan kembali barang-barang (penukaran) mereka, dikembalikan kepada mereka. Mereka berkata: \"Wahai ayah kami apa lagi yang kita inginkan. Ini barang-barang kita dikembalikan kepada kita, dan kami akan dapat memberi makan keluarga kami, dan kami akan dapat memelihara saudara kami, dan kami akan mendapat tambahan sukatan (gandum) seberat beban seekor unta. Itu adalah sukatan yang mudah (bagi raja Mesir)\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 66, "text": "قَالَ لَنۡ أُرۡسِلَهُۥ مَعَكُمۡ حَتَّىٰ تُؤۡتُونِ مَوۡثِقࣰا مِّنَ ٱللَّهِ لَتَأۡتُنَّنِی بِهِۦۤ إِلَّاۤ أَن یُحَاطَ بِكُمۡۖ فَلَمَّاۤ ءَاتَوۡهُ مَوۡثِقَهُمۡ قَالَ ٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِیلࣱ ۝٦٦", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "قال لهم يعقوب: لن أتركه يذهب معكم حتى تتعهدوا وتحلفوا لي بالله أن تردوه إليَّ، إلا أن تُغْلبوا عليه فلا تستطيعوا تخليصه، فلما أعطَوْه عهد الله على ما طلب، قال يعقوب: الله على ما نقول وكيل، أي تكفينا شهادته علينا وحفظه لنا.", "isBasmala": false, "translation_en": "He said, \"I will not send him with you, unless you give me a pledge before God that you will bring him back to me, unless you get trapped.\" And when they gave him their pledge, he said, \"God is witness to what we say.\"", "translation_id": "Ya'qub berkata: \"Aku sekali-kali tidak akan melepaskannya (pergi) bersama-sama kamu, sebelum kamu memberikan kepadaku janji yang teguh atas nama Allah, bahwa kamu pasti akan membawanya kepadaku kembali, kecuali jika kamu dikepung musuh\". Tatkala mereka memberikan janji mereka, maka Ya'qub berkata: \"Allah adalah saksi terhadap apa yang kita ucapkan (ini)\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 67, "text": "وَقَالَ یَـٰبَنِیَّ لَا تَدۡخُلُوا۟ مِنۢ بَابࣲ وَ ٰحِدࣲ وَٱدۡخُلُوا۟ مِنۡ أَبۡوَ ٰبࣲ مُّتَفَرِّقَةࣲۖ وَمَاۤ أُغۡنِی عَنكُم مِّنَ ٱللَّهِ مِن شَیۡءٍۖ إِنِ ٱلۡحُكۡمُ إِلَّا لِلَّهِۖ عَلَیۡهِ تَوَكَّلۡتُۖ وَعَلَیۡهِ فَلۡیَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ۝٦٧", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "وقال لهم أبوهم: يا أبنائي إذا دخلتم أرض \"مصر\" فلا تدخلوا مِن باب واحد، ولكن ادخلوها من أبواب متفرقة، حتى لا تصيبكم العين، وإني إذ أوصيكم بهذا لا أدفع عنكم شيئًا قضاه الله عليكم، فما الحكم إلا لله وحده، عليه اعتمدت ووثقت، وعليه وحده يعتمد المؤمنون.", "isBasmala": false, "translation_en": "And he said, \"O my sons, do not enter by one gate, but enter by different gates. I cannot avail you anything against God. The decision rests only with God. On Him I rely, and on Him let the reliant rely.\"", "translation_id": "Dan Ya'qub berkata: \"Hai anak-anakku janganlah kamu (bersama-sama) masuk dari satu pintu gerbang, dan masuklah dari pintu-pintu gerbang yang berlain-lain; namun demikian aku tiada dapat melepaskan kamu barang sedikitpun dari pada (takdir) Allah. Keputusan menetapkan (sesuatu) hanyalah hak Allah; kepada-Nya-lah aku bertawakkal dan hendaklah kepada-Nya saja orang-orang yang bertawakkal berserah diri\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 68, "text": "وَلَمَّا دَخَلُوا۟ مِنۡ حَیۡثُ أَمَرَهُمۡ أَبُوهُم مَّا كَانَ یُغۡنِی عَنۡهُم مِّنَ ٱللَّهِ مِن شَیۡءٍ إِلَّا حَاجَةࣰ فِی نَفۡسِ یَعۡقُوبَ قَضَىٰهَاۚ وَإِنَّهُۥ لَذُو عِلۡمࣲ لِّمَا عَلَّمۡنَـٰهُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٦٨", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "ولما دخلوا من أبواب متفرقة كما أمرهم أبوهم، ما كان ذلك ليدفع قضاء الله عنهم، ولكن كان شفقة في نفس يعقوب عليهم أن تصيبهم العين، وإن يعقوب لصاحب علمٍ عظيم بأمر دينه علَّمه الله له وحْيًا، ولكن أكثر الناس لا يعلمون عواقب الأمور ودقائق الأشياء، وما يعلمه يعقوب -عليه السلام- مِن أمر دينه.", "isBasmala": false, "translation_en": "And when they entered as their father had instructed them, it did not avail them anything against God; it was just a need in the soul of Jacob, which he carried out. He was a person of knowledge inasmuch as We had taught him, but most people do not know.", "translation_id": "Dan tatkala mereka masuk menurut yang diperintahkan ayah mereka, maka (cara yang mereka lakukan itu) tiadalah melepaskan mereka sedikitpun dari takdir Allah, akan tetapi itu hanya suatu keinginan pada diri Ya'qub yang telah ditetapkannya. Dan sesungguhnya dia mempunyai pengetahuan, karena Kami telah mengajarkan kepadanya. Akan tetapi kebanyakan manusia tiada mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 69, "text": "وَلَمَّا دَخَلُوا۟ عَلَىٰ یُوسُفَ ءَاوَىٰۤ إِلَیۡهِ أَخَاهُۖ قَالَ إِنِّیۤ أَنَا۠ أَخُوكَ فَلَا تَبۡتَىِٕسۡ بِمَا كَانُوا۟ یَعۡمَلُونَ ۝٦٩", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "ولما دخل إخوة يوسف عليه في منزل ضيافته ومعهم شقيقه، ضم يوسف إليه شقيقه، وقال له سرًا: إني أنا أخوك فلا تحزن، ولا تغتمَّ بما صنعوه بي فيما مضى. وأمره بكتمان ذلك عنهم.", "isBasmala": false, "translation_en": "And when they entered into the presence of Joseph, he embraced his brother, and said, \"I am your brother; do not be saddened by what they used to do.\"", "translation_id": "Dan tatkala mereka masuk ke (tempat) Yusuf. Yusuf membawa saudaranya (Bunyamin) ke tempatnya, Yusuf berkata: \"Sesungguhnya aku (ini) adalah saudaramu, maka janganlah kamu berdukacita terhadap apa yang telah mereka kerjakan\".", "manzil": 3, "manzil_display": ""}], "244": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 70, "text": "فَلَمَّا جَهَّزَهُم بِجَهَازِهِمۡ جَعَلَ ٱلسِّقَایَةَ فِی رَحۡلِ أَخِیهِ ثُمَّ أَذَّنَ مُؤَذِّنٌ أَیَّتُهَا ٱلۡعِیرُ إِنَّكُمۡ لَسَـٰرِقُونَ ۝٧٠", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "فلما جهزَّهم يوسف، وحمَّل إبلهم بالطعام، أمر عماله، فوضعوا الإناء الذي كان يكيل للناس به في متاع أخيه \"بنيامين\" من حيث لا يشعر أحد، ولما ركبوا ليسيروا نادى منادٍ قائلا يا أصحاب هذه العير المحمَّلة بالطعام، إنكم لسارقون.", "isBasmala": false, "translation_en": "Then, when he provided them with their provisions, he placed the drinking-cup in his brother's saddlebag. Then an announcer called out, \"O people of the caravan, you are thieves.\"", "translation_id": "Maka tatkala telah disiapkan untuk mereka bahan makanan mereka, Yusuf memasukkan piala (tempat minum) ke dalam karung saudaranya. Kemudian berteriaklah seseorang yang menyerukan: \"Hai kafilah, sesungguhnya kamu adalah orang-orang yang mencuri\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 71, "text": "قَالُوا۟ وَأَقۡبَلُوا۟ عَلَیۡهِم مَّاذَا تَفۡقِدُونَ ۝٧١", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "قال أولاد يعقوب مقبلين على المنادي: ما الذي تفقدونه؟", "isBasmala": false, "translation_en": "They said, as they came towards them, \"What are you missing?\"", "translation_id": "Mereka menjawab, sambil menghadap kepada penyeru-penyeru itu: \"Barang apakah yang hilang dari pada kamu?\"", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 72, "text": "قَالُوا۟ نَفۡقِدُ صُوَاعَ ٱلۡمَلِكِ وَلِمَن جَاۤءَ بِهِۦ حِمۡلُ بَعِیرࣲ وَأَنَا۠ بِهِۦ زَعِیمࣱ ۝٧٢", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "قال المنادي ومَن بحضرته: نفقد المكيال الذي يكيل الملك به، ومكافأة من يحضره مقدار حِمْل بعير من الطعام، وقال المنادي: وأنا بحِمْل البعير من الطعام ضامن وكفيل.", "isBasmala": false, "translation_en": "They said, \"We are missing the king's goblet. Whoever brings it will have a camel-load; and I personally guarantee it.\"", "translation_id": "Penyeru-penyeru itu berkata: \"Kami kehilangan piala raja, dan siapa yang dapat mengembalikannya akan memperoleh bahan makanan (seberat) beban unta, dan aku menjamin terhadapnya\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 73, "text": "قَالُوا۟ تَٱللَّهِ لَقَدۡ عَلِمۡتُم مَّا جِئۡنَا لِنُفۡسِدَ فِی ٱلۡأَرۡضِ وَمَا كُنَّا سَـٰرِقِینَ ۝٧٣", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "قال إخوة يوسف: والله لقد تحققتم مما شاهدتموه منا أننا ما جئنا أرض \"مصر\" من أجل الإفساد فيها، وليس من صفاتنا أن نكون سارقين.", "isBasmala": false, "translation_en": "They said, \"By God, you know we did not come to cause trouble in the land, and we are not thieves.\"", "translation_id": "Saudara-saudara Yusuf menjawab \"Demi Allah sesungguhnya kamu mengetahui bahwa kami datang bukan untuk membuat kerusakan di negeri (ini) dan kami bukanlah para pencuri\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 74, "text": "قَالُوا۟ فَمَا جَزَ ٰۤؤُهُۥۤ إِن كُنتُمۡ كَـٰذِبِینَ ۝٧٤", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "قال المكلَّفون بالبحث عن المكيال لإخوة يوسف: فما عقوبة السارق عندكم إن كنتم كاذبين في قولكم: لسنا بسارقين؟", "isBasmala": false, "translation_en": "They said, \"What shall be his punishment, if you are lying?\"", "translation_id": "Mereka berkata: \"Tetapi apa balasannya jikalau kamu betul-betul pendusta? \"", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 75, "text": "قَالُوا۟ جَزَ ٰۤؤُهُۥ مَن وُجِدَ فِی رَحۡلِهِۦ فَهُوَ جَزَ ٰۤؤُهُۥۚ كَذَ ٰلِكَ نَجۡزِی ٱلظَّـٰلِمِینَ ۝٧٥", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "قال إخوة يوسف: جزاء السارق مَن وُجِد المسروق في رحله فهو جزاؤه. أي يسلَّم بسرقته إلى مَن سرق منه حتى يكون عبدًا عنده، مثل هذا الجزاء -وهو الاسترقاق- نجزي الظالمين بالسرقة، وهذا ديننا وسنتنا في أهل السرقة.", "isBasmala": false, "translation_en": "They said, \"His punishment, if it is found in his bag: he will belong to you. Thus we penalize the guilty.\"", "translation_id": "Mereka menjawab: \"Balasannya, ialah pada siapa diketemukan (barang yang hilang) dalam karungnya, maka dia sendirilah balasannya (tebusannya)\". Demikianlah kami memberi pembalasan kepada orang-orang yang zalim.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 76, "text": "فَبَدَأَ بِأَوۡعِیَتِهِمۡ قَبۡلَ وِعَاۤءِ أَخِیهِ ثُمَّ ٱسۡتَخۡرَجَهَا مِن وِعَاۤءِ أَخِیهِۚ كَذَ ٰلِكَ كِدۡنَا لِیُوسُفَۖ مَا كَانَ لِیَأۡخُذَ أَخَاهُ فِی دِینِ ٱلۡمَلِكِ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُۚ نَرۡفَعُ دَرَجَـٰتࣲ مَّن نَّشَاۤءُۗ وَفَوۡقَ كُلِّ ذِی عِلۡمٍ عَلِیمࣱ ۝٧٦", "juz": 13, "hizb": "(* ح 25*)", "tafsir": "ورجعوا بإخوة يوسف إليه، فقام بنفسه يفتش أمتعتهم، فبدأ بأمتعتهم قبل متاع شقيقه؛ إحكامًا لما دبَّره لاستبقاء أخيه معه، ثم انتهى بوعاء أخيه، فاستخرج الإناء منه، كذلك يسَّرنا ليوسف هذا التدبير الذي توصَّل به لأخذ أخيه، وما كان له أن يأخذ أخاه في حكم مَلِك \"مصر\"؛ لأنه ليس من دينه أن يتملك السارق، إلا أن مشيئة الله اقتضت هذا التدبير والاحتكام إلى شريعة إخوة يوسف القاضية برِقِّ السارق. نرفع منازل مَن نشاء في الدنيا على غيره كما رفعنا منزلة يوسف. وفوق كل ذي علمٍ من هو أعلم منه، حتى ينتهي العلم إلى الله تعالى عالم الغيب والشهادة.", "isBasmala": false, "translation_en": "So he began with their bags, before his brother's bag. Then he pulled it out of his brother's bag. Thus We devised a plan for Joseph; he could not have detained his brother under the king's law, unless God so willed. We elevate by degrees whomever We will; and above every person of knowledge, there is one more learned.", "translation_id": "Maka mulailah Yusuf (memeriksa) karung-karung mereka sebelum (memeriksa) karung saudaranya sendiri, kemudian dia mengeluarkan piala raja itu dari karung saudaranya. Demikianlah Kami atur untuk (mencapai maksud) Yusuf. Tiadalah patut Yusuf menghukum saudaranya menurut undang-undang raja, kecuali Allah menghendaki-Nya. Kami tinggikan derajat orang yang Kami kehendaki; dan di atas tiap-tiap orang yang berpengetahuan itu ada lagi Yang Maha Mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 77, "text": "۞ قَالُوۤا۟ إِن یَسۡرِقۡ فَقَدۡ سَرَقَ أَخࣱ لَّهُۥ مِن قَبۡلُۚ فَأَسَرَّهَا یُوسُفُ فِی نَفۡسِهِۦ وَلَمۡ یُبۡدِهَا لَهُمۡۚ قَالَ أَنتُمۡ شَرࣱّ مَّكَانࣰاۖ وَٱللَّهُ أَعۡلَمُ بِمَا تَصِفُونَ ۝٧٧", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قال إخوة يوسف: إنْ سرق هذا فقد سرق أخ شقيق له من قبل (يقصدون يوسف عليه السلام) فأخفى يوسف في نفسه ما سمعه، وحدَّث نفسه قائلا أنتم أسوأ منزلة ممن ذكرتم، حيث دبَّرتم لي ما كان منكم، والله أعلم بما تصفون من الكذب والافتراء.", "isBasmala": false, "translation_en": "They said, \"If he has stolen, a brother of his has stolen before.\" But Joseph kept it to himself, and did not reveal it to them. He said, \"You are in a worse situation, and God is Aware of what you allege.\"", "translation_id": "Mereka berkata: \"Jika ia mencuri, maka sesungguhnya, telah pernah mencuri pula saudaranya sebelum itu\". Maka Yusuf menyembunyikan kejengkelan itu pada dirinya dan tidak menampakkannya kepada mereka. Dia berkata (dalam hatinya): \"Kamu lebih buruk kedudukanmu (sifat-sifatmu) dan Allah Maha Mengetahui apa yang kamu terangkan itu\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 78, "text": "قَالُوا۟ یَـٰۤأَیُّهَا ٱلۡعَزِیزُ إِنَّ لَهُۥۤ أَبࣰا شَیۡخࣰا كَبِیرࣰا فَخُذۡ أَحَدَنَا مَكَانَهُۥۤۖ إِنَّا نَرَىٰكَ مِنَ ٱلۡمُحۡسِنِینَ ۝٧٨", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قالوا مستعطفين ليوفوا بعهد أبيهم: يا أيها العزيز إن له والدًا كبيرًا في السن يحبه ولا يطيق بُعده، فخُذْ أحدنا بدلا من \"بنيامين\"، إنا نراك من المحسنين في معاملتك لنا ولغيرنا.", "isBasmala": false, "translation_en": "They said, \"O noble prince, he has a father, a very old man, so take one of us in his place. We see that you are a good person.\"", "translation_id": "Mereka berkata: \"Wahai Al Aziz, sesungguhnya ia mempunyai ayah yang sudah lanjut usianya, lantaran itu ambillah salah seorang diantara kami sebagai gantinya, sesungguhnya kami melihat kamu termasuk oranng-orang yang berbuat baik\".", "manzil": 3, "manzil_display": ""}], "245": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 79, "text": "قَالَ مَعَاذَ ٱللَّهِ أَن نَّأۡخُذَ إِلَّا مَن وَجَدۡنَا مَتَـٰعَنَا عِندَهُۥۤ إِنَّاۤ إِذࣰا لَّظَـٰلِمُونَ ۝٧٩", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قال يوسف: نعتصم بالله ونستجير به أن نأخذ أحدًا غير الذي وجدنا المكيال عنده -كما حكمتم أنتم-، فإننا إن فعلنا ما تطلبون نكون في عداد الظالمين.", "isBasmala": false, "translation_en": "He said, \"God forbid that we should arrest anyone except him in whose possession we found our property; for then we would be unjust.\"", "translation_id": "Berkata Yusuf: \"Aku mohon perlindungan kepada Allah daripada menahan seorang, kecuali orang yang kami ketemukan harta benda kami padanya, jika kami berbuat demikian, maka benar-benarlah kami orang-orang yang zalim\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 80, "text": "فَلَمَّا ٱسۡتَیۡـَٔسُوا۟ مِنۡهُ خَلَصُوا۟ نَجِیࣰّاۖ قَالَ كَبِیرُهُمۡ أَلَمۡ تَعۡلَمُوۤا۟ أَنَّ أَبَاكُمۡ قَدۡ أَخَذَ عَلَیۡكُم مَّوۡثِقࣰا مِّنَ ٱللَّهِ وَمِن قَبۡلُ مَا فَرَّطتُمۡ فِی یُوسُفَۖ فَلَنۡ أَبۡرَحَ ٱلۡأَرۡضَ حَتَّىٰ یَأۡذَنَ لِیۤ أَبِیۤ أَوۡ یَحۡكُمَ ٱللَّهُ لِیۖ وَهُوَ خَیۡرُ ٱلۡحَـٰكِمِینَ ۝٨٠", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "فلما يئسوا من إجابته إياهم لِمَا طلبوه انفردوا عن الناس، وأخذوا يتشاورون فيما بينهم، قال كبيرهم في السن: ألم تعلموا أن أباكم قد أخذ عليكم العهد المؤكد لتردُّنَّ أخاكم إلا أن تُغلبوا، ومن قبل هذا كان تقصيركم في يوسف وغدركم به؛ لذلك لن أفارق أرض \"مصر\" حتى يأذن لي أبي في مفارقتها، أو يقضي لي ربي بالخروج منها، وأتمكن مِن أَخْذِ أخي، والله خيرُ مَن حَكَمَ، وأعدل مَن فَصَلَ بين الناس.", "isBasmala": false, "translation_en": "And when they despaired of him, they conferred privately. Their eldest said, \"Don't you know that your father received a pledge from you before God, and in the past you failed with regard to Joseph? I will not leave this land until my father permits me, or God decides for me; for He is the Best of Deciders.\"", "translation_id": "Maka tatkala mereka berputus asa dari pada (putusan) Yusuf mereka menyendiri sambil berunding dengan berbisik-bisik. Berkatalah yang tertua diantara mereka: \"Tidakkah kamu ketahui bahwa sesungguhnya ayahmu telah mengambil janji dari kamu dengan nama Allah dan sebelum itu kamu telah menyia-nyiakan Yusuf. Sebab itu aku tidak akan meninggalkan negeri Mesir, sampai ayahku mengizinkan kepadaku (untuk kembali), atau Allah memberi keputusan terhadapku. Dan Dia adalah Hakim yang sebaik-baiknya\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 81, "text": "ٱرۡجِعُوۤا۟ إِلَىٰۤ أَبِیكُمۡ فَقُولُوا۟ یَـٰۤأَبَانَاۤ إِنَّ ٱبۡنَكَ سَرَقَ وَمَا شَهِدۡنَاۤ إِلَّا بِمَا عَلِمۡنَا وَمَا كُنَّا لِلۡغَیۡبِ حَـٰفِظِینَ ۝٨١", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "ارجعوا أنتم إلى أبيكم، وأخبروه بما جرى، وقولوا له: إن ابنك \"بنيامين\" قد سرق، وما شهدنا بذلك إلا بعد أن تَيَقَّنَّا، فقد رأينا المكيال في رحله، وما كان عندنا علم الغيب أنه سيسرق حين عاهدناك على ردِّه.", "isBasmala": false, "translation_en": "\"Go back to your father, and say, 'Our father, your son has stolen. We testify only to what we know, and we could not have prevented the unforeseen.'\"", "translation_id": "Kembalilah kepada ayahmu dan katakanlah: \"Wahai ayah kami! Sesungguhnya anakmu telah mencuri, dan kami hanya menyaksikan apa yang kami ketahui, dan sekali-kali kami tidak dapat menjaga (mengetahui) barang yang ghaib.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 82, "text": "وَسۡـَٔلِ ٱلۡقَرۡیَةَ ٱلَّتِی كُنَّا فِیهَا وَٱلۡعِیرَ ٱلَّتِیۤ أَقۡبَلۡنَا فِیهَاۖ وَإِنَّا لَصَـٰدِقُونَ ۝٨٢", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "واسأل -يا أبانا- أهل \"مصر\"، ومَن كان معنا في القافلة التي كنا فيها، وإننا صادقون فيما أخبرناك به.", "isBasmala": false, "translation_en": "\"Ask the town where we were, and the caravan in which we came. We are being truthful.\"", "translation_id": "Dan tanyalah (penduduk) negeri yang kami berada disitu, dan kafilah yang kami datang bersamanya, dan sesungguhnya kami adalah orang-orang yang benar\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 83, "text": "قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرࣰاۖ فَصَبۡرࣱ جَمِیلٌۖ عَسَى ٱللَّهُ أَن یَأۡتِیَنِی بِهِمۡ جَمِیعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ ۝٨٣", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "ولما رجعوا وأخبروا أباهم قال لهم: بل زَيَّنَت لكم أنفسكم الأمَّارة بالسوء مكيدة دبَّرتموها كما فعلتم مِن قبل مع يوسف، فصبري صبر جميل لا جزع فيه ولا شكوى معه، عسى الله أن يردَّ إليَّ أبنائي الثلاثة -وهم يوسف وشقيقه وأخوهم الكبير المتخلف من أجل أخيه- إنه هو العليم بحالي، الحكيم في تدبيره.", "isBasmala": false, "translation_en": "He said, \"Rather, your souls have contrived something for you. Patience is a virtue. Perhaps God will bring them all back to me. He is the Knowing, the Wise.\"", "translation_id": "Ya'qub berkata: \"Hanya dirimu sendirilah yang memandang baik perbuatan (yang buruk) itu. Maka kesabaran yang baik itulah (kesabaranku). Mudah-mudahan Allah mendatangkan mereka semuanya kepadaku; sesungguhnya Dialah Yang Maha Mengetahui lagi Maha Bijaksana\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 84, "text": "وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ یَـٰۤأَسَفَىٰ عَلَىٰ یُوسُفَ وَٱبۡیَضَّتۡ عَیۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِیمࣱ ۝٨٤", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "وأعرض يعقوب عنهم، وقد ضاق صدره بما قالوه، وقال: يا حسرتا على يوسف وابيضَّتْ عيناه، بذهاب سوادهما مِن شدة الحزن فهو ممتلئ القلب حزنًا، ولكنه شديد الكتمان له.", "isBasmala": false, "translation_en": "Then he turned away from them, and said, \"O my bitterness for Joseph.\" And his eyes turned white from sorrow, and he became depressed.", "translation_id": "Dan Ya'qub berpaling dari mereka (anak-anaknya) seraya berkata: \"Aduhai duka citaku terhadap Yusuf\", dan kedua matanya menjadi putih karena kesedihan dan dia adalah seorang yang menahan amarahnya (terhadap anak-anaknya).", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 85, "text": "قَالُوا۟ تَٱللَّهِ تَفۡتَؤُا۟ تَذۡكُرُ یُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَـٰلِكِینَ ۝٨٥", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قال بنوه: تالله ما تزال تتذكر يوسف، ويشتدُّ حزنك عليه حتى تُشْرِف على الهلاك أو تهلك فعلا فخفف عن نفسك.", "isBasmala": false, "translation_en": "They said, \"By God, you will not stop remembering Joseph, until you have ruined your health, or you have passed away.\"", "translation_id": "Mereka berkata: \"Demi Allah, senantiasa kamu mengingati Yusuf, sehingga kamu mengidapkan penyakit yang berat atau termasuk orang-orang yang binasa\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 86, "text": "قَالَ إِنَّمَاۤ أَشۡكُوا۟ بَثِّی وَحُزۡنِیۤ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝٨٦", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قال يعقوب مجيبًا لهم: لا أظهر همِّي وحزني إلا لله وحده، فهو كاشف الضرِّ والبلاء، وأعلم من رحمة الله وفرجه ما لا تعلمونه.", "isBasmala": false, "translation_en": "He said, \"I only complain of my grief and sorrow to God, and I know from God what you do not know.\"", "translation_id": "Ya'qub menjawab: \"Sesungguhnya hanyalah kepada Allah aku mengadukan kesusahan dan kesedihanku, dan aku mengetahui dari Allah apa yang kamu tiada mengetahuinya\".", "manzil": 3, "manzil_display": ""}], "246": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 87, "text": "یَـٰبَنِیَّ ٱذۡهَبُوا۟ فَتَحَسَّسُوا۟ مِن یُوسُفَ وَأَخِیهِ وَلَا تَا۟یۡـَٔسُوا۟ مِن رَّوۡحِ ٱللَّهِۖ إِنَّهُۥ لَا یَا۟یۡـَٔسُ مِن رَّوۡحِ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡكَـٰفِرُونَ ۝٨٧", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قال يعقوب: يا أبنائي عودوا إلى \"مصر\" فاستقصوا أخبار يوسف وأخيه، ولا تقطعوا رجاءكم من رحمة الله، إنه لا يقطع الرجاء من رحمة الله إلا الجاحدون لقدرته، الكافرون به.", "isBasmala": false, "translation_en": "\"O my sons, go and inquire about Joseph and his brother, and do not despair of God's comfort. None despairs of God's comfort except the disbelieving people.\"", "translation_id": "Hai anak-anakku, pergilah kamu, maka carilah berita tentang Yusuf dan saudaranya dan jangan kamu berputus asa dari rahmat Allah. Sesungguhnya tiada berputus asa dari rahmat Allah, melainkan kaum yang kafir\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 88, "text": "فَلَمَّا دَخَلُوا۟ عَلَیۡهِ قَالُوا۟ یَـٰۤأَیُّهَا ٱلۡعَزِیزُ مَسَّنَا وَأَهۡلَنَا ٱلضُّرُّ وَجِئۡنَا بِبِضَـٰعَةࣲ مُّزۡجَىٰةࣲ فَأَوۡفِ لَنَا ٱلۡكَیۡلَ وَتَصَدَّقۡ عَلَیۡنَاۤۖ إِنَّ ٱللَّهَ یَجۡزِی ٱلۡمُتَصَدِّقِینَ ۝٨٨", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "فذهبوا إلى \"مصر\"، فلما دخلوا على يوسف قالوا: يا أيها العزيز أصابنا وأهلنا القحط والجدب، وجئناك بثمن رديء قليل، فأعطنا به ما كنت تعطينا من قبل بالثمن الجيد، وتصدَّقْ علينا بقبض هذه الدراهم المزجاة وتجوَّز فيها، إن الله تعالى يثيب المتفضِّلين على أهل الحاجة بأموالهم.", "isBasmala": false, "translation_en": "Then, when they entered into his presence, they said, \"Mighty governor, adversity has befallen us, and our family. We have brought scant merchandise. But give us full measure, and be charitable towards us-God rewards the charitable.\"", "translation_id": "Maka ketika mereka masuk ke (tempat) Yusuf, mereka berkata: \"Hai Al Aziz, kami dan keluarga kami telah ditimpa kesengsaraan dan kami datang membawa barang-barang yang tak berharga, maka sempurnakanlah sukatan untuk kami, dan bersedekahlah kepada kami, sesungguhnya Allah memberi balasan kepada orang-orang yang bersedekah\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 89, "text": "قَالَ هَلۡ عَلِمۡتُم مَّا فَعَلۡتُم بِیُوسُفَ وَأَخِیهِ إِذۡ أَنتُمۡ جَـٰهِلُونَ ۝٨٩", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "فلما سمع مقالتهم رقَّ لهم، وعرَّفهم بنفسه وقال: هل تذكرون الذي فعلتموه بيوسف وأخيه من الأذى في حال جَهْلكم بعاقبة ما تفعلون؟", "isBasmala": false, "translation_en": "He said, \"Do you realize what you did with Joseph and his brother, in your ignorance?\"", "translation_id": "Yusuf berkata: \"Apakah kamu mengetahui (kejelekan) apa yang telah kamu lakukan terhadap Yusuf dan saudaranya ketika kamu tidak mengetahui (akibat) perbuatanmu itu?\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 90, "text": "قَالُوۤا۟ أَءِنَّكَ لَأَنتَ یُوسُفُۖ قَالَ أَنَا۠ یُوسُفُ وَهَـٰذَاۤ أَخِیۖ قَدۡ مَنَّ ٱللَّهُ عَلَیۡنَاۤۖ إِنَّهُۥ مَن یَتَّقِ وَیَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا یُضِیعُ أَجۡرَ ٱلۡمُحۡسِنِینَ ۝٩٠", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قالوا: أإنَّك لأنت يوسف؟ قال: نعم أنا يوسف، وهذا شقيقي، قد تفضَّل الله علينا، فجمع بيننا بعد الفرقة، إنه من يتق الله، ويصبر على المحن، فإن الله لا يذهب ثواب إحسانه، وإنما يجزيه أحسن الجزاء.", "isBasmala": false, "translation_en": "They said, \"Is that you, Joseph?\" He said, \"I am Joseph, and this is my brother. God has been gracious to us. He who practices piety and patience-God never fails to reward the righteous.\"", "translation_id": "Mereka berkata: \"Apakah kamu ini benar-benar Yusuf?\". Yusuf menjawab: \"Akulah Yusuf dan ini saudaraku. Sesungguhnya Allah telah melimpahkan karunia-Nya kepada kami\". Sesungguhnya barang siapa yang bertakwa dan bersabar, maka sesungguhnya Allah tidak menyia-nyiakan pahala orang-orang yang berbuat baik\"", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 91, "text": "قَالُوا۟ تَٱللَّهِ لَقَدۡ ءَاثَرَكَ ٱللَّهُ عَلَیۡنَا وَإِن كُنَّا لَخَـٰطِـِٔینَ ۝٩١", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قالوا: تالله لقد فَضَّلك الله علينا وأعزَّك بالعلم والحلم والفضل، وإن كنا لخاطئين بما فعلناه عمدًا بك وبأخيك.", "isBasmala": false, "translation_en": "They said, \"By God, God has preferred you over us. We were definitely in the wrong.\"", "translation_id": "Mereka berkata: \"Demi Allah, sesungguhnya Allah telah melebihkan kamu atas kami, dan sesungguhnya kami adalah orang-orang yang bersalah (berdosa)\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 92, "text": "قَالَ لَا تَثۡرِیبَ عَلَیۡكُمُ ٱلۡیَوۡمَۖ یَغۡفِرُ ٱللَّهُ لَكُمۡۖ وَهُوَ أَرۡحَمُ ٱلرَّ ٰحِمِینَ ۝٩٢", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قال لهم يوسف: لا تأنيب عليكم اليوم، يغفر الله لكم، وهو أرحم الراحمين لمن تاب من ذنبه وأناب إلى طاعته.", "isBasmala": false, "translation_en": "He said, \"There is no blame upon you today. God will forgive you. He is the Most Merciful of the merciful.\"", "translation_id": "Dia (Yusuf) berkata: \"Pada hari ini tak ada cercaan terhadap kamu, mudah-mudahan Allah mengampuni (kamu), dan Dia adalah Maha Penyayang diantara para penyayang\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 93, "text": "ٱذۡهَبُوا۟ بِقَمِیصِی هَـٰذَا فَأَلۡقُوهُ عَلَىٰ وَجۡهِ أَبِی یَأۡتِ بَصِیرࣰا وَأۡتُونِی بِأَهۡلِكُمۡ أَجۡمَعِینَ ۝٩٣", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "ولما سألهم عن أبيه أخبروه بذهاب بصره من البكاء عليه، فقال لهم: عودوا إلى أبيكم ومعكم قميصي هذا فاطرحوه على وجه أبي يَعُدْ إليه بصره، ثم أحضروا إليَّ جميع أهلكم.", "isBasmala": false, "translation_en": "\"Take this shirt of mine, and lay it over my father's face, and he will recover his sight. And bring your whole family to me.\"", "translation_id": "Pergilah kamu dengan membawa baju gamisku ini, lalu letakkanlah dia kewajah ayahku, nanti ia akan melihat kembali; dan bawalah keluargamu semuanya kepadaku\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 94, "text": "وَلَمَّا فَصَلَتِ ٱلۡعِیرُ قَالَ أَبُوهُمۡ إِنِّی لَأَجِدُ رِیحَ یُوسُفَۖ لَوۡلَاۤ أَن تُفَنِّدُونِ ۝٩٤", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "ولما خرجت القافلة من أرض \"مصر\"، ومعهم القميص قال يعقوب لمن حضره: إني لأجد ريح يوسف لولا أن تسفهوني وتسخروا مني، وتزعموا أن هذا الكلام صدر مني من غير شعور.", "isBasmala": false, "translation_en": "As the caravan set out, their father said, \"I sense the presence of Joseph, though you may think I am senile.\"", "translation_id": "Tatkala kafilah itu telah ke luar (dari negeri Mesir) berkata ayah mereka: \"Sesungguhnya aku mencium bau Yusuf, sekiranya kamu tidak menuduhku lemah akal (tentu kamu membenarkan aku)\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 95, "text": "قَالُوا۟ تَٱللَّهِ إِنَّكَ لَفِی ضَلَـٰلِكَ ٱلۡقَدِیمِ ۝٩٥", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قال الحاضرون عنده: تالله إنك لا تزال في خطئك القديم مِن حب يوسف، وأنك لا تنساه.", "isBasmala": false, "translation_en": "They said, \"By God, you are still in your old confusion.\"", "translation_id": "Keluarganya berkata: \"Demi Allah, sesungguhnya kamu masih dalam kekeliruanmu yang dahulu\".", "manzil": 3, "manzil_display": ""}], "247": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 96, "text": "فَلَمَّاۤ أَن جَاۤءَ ٱلۡبَشِیرُ أَلۡقَىٰهُ عَلَىٰ وَجۡهِهِۦ فَٱرۡتَدَّ بَصِیرࣰاۖ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّیۤ أَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ۝٩٦", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "فلما أن جاء من يُبشِّر يعقوب بأن يوسف حيٌّ، وطرح قميص يوسف على وجهه فعاد يعقوب مبصرًا، وعمَّه السرور فقال لمن عنده: ألـمْ أخبركم أني أعلم من الله ما لا تعلمونه من فضل الله ورحمته وكرمه؟", "isBasmala": false, "translation_en": "Then, when the bearer of good news arrived, he laid it over his face, and he regained his sight. He said, \"Did I not say to you that I know from God what you do not know?\"", "translation_id": "Tatkala telah tiba pembawa kabar gembira itu, maka diletakkannya baju gamis itu ke wajah Ya'qub, lalu kembalilah dia dapat melihat. Berkata Ya'qub: \"Tidakkah aku katakan kepadamu, bahwa aku mengetahui dari Allah apa yang kamu tidak mengetahuinya\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 97, "text": "قَالُوا۟ یَـٰۤأَبَانَا ٱسۡتَغۡفِرۡ لَنَا ذُنُوبَنَاۤ إِنَّا كُنَّا خَـٰطِـِٔینَ ۝٩٧", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قال بنوه: يا أبانا سل لنا ربك أن يعفو عنا ويستر علينا ذنوبنا، إنا كنا خاطئين فيما فعلناه بيوسف وشقيقه.", "isBasmala": false, "translation_en": "They said, \"Father, pray for the forgiveness of our sins; we were indeed at fault.\"", "translation_id": "Mereka berkata: \"Wahai ayah kami, mohonkanlah ampun bagi kami terhadap dosa-dosa kami, sesungguhnya kami adalah orang-orang yang bersalah (berdosa)\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 98, "text": "قَالَ سَوۡفَ أَسۡتَغۡفِرُ لَكُمۡ رَبِّیۤۖ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ ۝٩٨", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "قال يعقوب: سوف أسأل ربي أن يغفر لكم ذنوبكم، إنه هو الغفور لذنوب عباده التائبين، الرحيم بهم.", "isBasmala": false, "translation_en": "He said, \"I will ask my Lord to forgive you. He is the Forgiver, the Most Merciful.\"", "translation_id": "Ya'qub berkata: \"Aku akan memohonkan ampun bagimu kepada Tuhanku. Sesungguhnya Dialah Yang Maha Pengampun lagi Maha Penyayang\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 99, "text": "فَلَمَّا دَخَلُوا۟ عَلَىٰ یُوسُفَ ءَاوَىٰۤ إِلَیۡهِ أَبَوَیۡهِ وَقَالَ ٱدۡخُلُوا۟ مِصۡرَ إِن شَاۤءَ ٱللَّهُ ءَامِنِینَ ۝٩٩", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "وخرج يعقوب وأهله إلى \"مصر\" قاصدين يوسف، فلما وصلوا إليه ضمَّ يوسف إليه أبويه، وقال لهم: ادخلوا \"مصر\" بمشيئة الله، وأنتم آمنون من الجهد والقحط، ومن كل مكروه.", "isBasmala": false, "translation_en": "Then, when they entered into the presence of Joseph, he embraced his parents, and said, \"Enter Egypt, God willing, safe and secure.\"", "translation_id": "Maka tatkala mereka masuk ke (tempat) Yusuf: Yusuf merangkul ibu bapanya dan dia berkata: \"Masuklah kamu ke negeri Mesir, insya Allah dalam keadaan aman\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 100, "text": "وَرَفَعَ أَبَوَیۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّوا۟ لَهُۥ سُجَّدࣰاۖ وَقَالَ یَـٰۤأَبَتِ هَـٰذَا تَأۡوِیلُ رُءۡیَـٰیَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّی حَقࣰّاۖ وَقَدۡ أَحۡسَنَ بِیۤ إِذۡ أَخۡرَجَنِی مِنَ ٱلسِّجۡنِ وَجَاۤءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّیۡطَـٰنُ بَیۡنِی وَبَیۡنَ إِخۡوَتِیۤۚ إِنَّ رَبِّی لَطِیفࣱ لِّمَا یَشَاۤءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ ۝١٠٠", "juz": 13, "hizb": "(*¼ ح 25*)", "tafsir": "وأجْلَسَ أباه وأمه على سرير ملكه بجانبه؛ إكرامًا لهما، وحيَّاه أبواه وإخوته الأحد عشر بالسجود له تحية وتكريمًا، لا عبادة وخضوعًا، وكان ذلك جائزًا في شريعتهم، وقد حَرُم في شريعتنا؛ سدًا لذريعة الشرك بالله. وقال يوسف لأبيه: هذا السجود هو تفسير رؤياي التي قصصتها عليك من قبل في صغري، قد جعلها ربي صدقًا، وقد تفضَّل عليَّ حين أخرجني من السجن، وجاء بكم إليَّ من البادية، من بعد أن أفسد الشيطان رابطة الأخوة بيني وبين إخوتي. إن ربي لطيف التدبير لما يشاء، إنه هو العليم بمصالح عباده، الحكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "And he elevated his parents on the throne, and they fell prostrate before him. He said, \"Father, this is the fulfillment of my vision of long ago. My Lord has made it come true. He has blessed me, when he released me from prison, and brought you out of the wilderness, after the devil had sown conflict between me and my brothers. My Lord is Most Kind towards whomever He wills. He is the All-knowing, the Most Wise.\"", "translation_id": "Dan ia menaikkan kedua ibu-bapanya ke atas singgasana. Dan mereka (semuanya) merebahkan diri seraya sujud kepada Yusuf. Dan berkata Yusuf: \"Wahai ayahku inilah ta'bir mimpiku yang dahulu itu; sesungguhnya Tuhanku telah menjadikannya suatu kenyataan. Dan sesungguhnya Tuhanku telah berbuat baik kepadaku, ketika Dia membebaskan aku dari rumah penjara dan ketika membawa kamu dari dusun padang pasir, setelah syaitan merusakkan (hubungan) antaraku dan saudara-saudaraku. Sesungguhnya Tuhanku Maha Lembut terhadap apa yang Dia kehendaki. Sesungguhnya Dialah Yang Maha Mengetahui lagi Maha Bijaksana.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 101, "text": "۞ رَبِّ قَدۡ ءَاتَیۡتَنِی مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِی مِن تَأۡوِیلِ ٱلۡأَحَادِیثِۚ فَاطِرَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِیِّۦ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۖ تَوَفَّنِی مُسۡلِمࣰا وَأَلۡحِقۡنِی بِٱلصَّـٰلِحِینَ ۝١٠١", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "ثم دعا يوسف ربه قائلا ربِّ قد أعطيتني من ملك \"مصر\"، وعلَّمتني من تفسير الرؤى وغير ذلك من العلم، يا خالق السموات والأرض ومبدعهما، أنت متولي جميع شأني في الدنيا والآخرة، توفني إليك مسلمًا، وألحقني بعبادك الصالحين من الأنبياء الأبرار والأصفياء الأخيار.", "isBasmala": false, "translation_en": "\"My Lord, You have given me some authority, and taught me some interpretation of events. Initiator of the heavens and the earth; You are my Protector in this life and in the Hereafter. Receive my soul in submission, and unite me with the righteous.\"", "translation_id": "Ya Tuhanku, sesungguhnya Engkau telah menganugerahkan kepadaku sebahagian kerajaan dan telah mengajarkan kepadaku sebahagian ta'bir mimpi. (Ya Tuhan) Pencipta langit dan bumi. Engkaulah Pelindungku di dunia dan di akhirat, wafatkanlah aku dalam keadaan Islam dan gabungkanlah aku dengan orang-orang yang saleh.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 102, "text": "ذَ ٰلِكَ مِنۡ أَنۢبَاۤءِ ٱلۡغَیۡبِ نُوحِیهِ إِلَیۡكَۖ وَمَا كُنتَ لَدَیۡهِمۡ إِذۡ أَجۡمَعُوۤا۟ أَمۡرَهُمۡ وَهُمۡ یَمۡكُرُونَ ۝١٠٢", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "ذلك المذكور من قصة يوسف هو من أخبار الغيب نخبرك به -أيها الرسول- وحيًا، وما كنت حاضرًا مع إخوة يوسف حين دبَّروا له الإلقاء في البئر، واحتالوا عليه وعلى أبيه. وهذا يدل على صدقك، وأن الله يُوحِي إليك.", "isBasmala": false, "translation_en": "This is news from the past that We reveal to you. You were not present with them when they plotted and agreed on a plan.", "translation_id": "Demikian itu (adalah) diantara berita-berita yang ghaib yang Kami wahyukan kepadamu (Muhammad); padahal kamu tidak berada pada sisi mereka, ketika mereka memutuskan rencananya (untuk memasukkan Yusuf ke dalam sumur) dan mereka sedang mengatur tipu daya.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 103, "text": "وَمَاۤ أَكۡثَرُ ٱلنَّاسِ وَلَوۡ حَرَصۡتَ بِمُؤۡمِنِینَ ۝١٠٣", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "وما أكثرُ المشركين من قومك -أيها الرسول- بمصدِّقيك ولا متبعيك، ولو حَرَصْتَ على إيمانهم، فلا تحزن على ذلك.", "isBasmala": false, "translation_en": "But most people, for all your eagerness, are not believers.", "translation_id": "Dan sebahagian besar manusia tidak akan beriman -- walaupun kamu sangat menginginkannya.", "manzil": 3, "manzil_display": ""}], "248": [{"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 104, "text": "وَمَا تَسۡـَٔلُهُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۚ إِنۡ هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَـٰلَمِینَ ۝١٠٤", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "وما تطلب من قومك أجرة على إرشادهم للإيمان، إن الذي أُرسلتَ به من القرآن والهدى عظة للناس أجمعين يتذكرون به ويهتدون.", "isBasmala": false, "translation_en": "You ask them no wage for it. It is only a reminder for all mankind.", "translation_id": "Dan kamu sekali-kali tidak meminta upah kepada mereka (terhadap seruanmu ini), itu tidak lain hanyalah pengajaran bagi semesta alam.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 105, "text": "وَكَأَیِّن مِّنۡ ءَایَةࣲ فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ یَمُرُّونَ عَلَیۡهَا وَهُمۡ عَنۡهَا مُعۡرِضُونَ ۝١٠٥", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "وكثير من الدلائل الدالة على وحدانية الله وقدرته منتشرة في السموات والأرض، كالشمس والقمر والجبال والأشجار، يشاهدونها وهم عنها معرضون، لا يفكرون فيها ولا يعتبرون.", "isBasmala": false, "translation_en": "How many a sign in the heavens and the earth do they pass by, paying no attention to them?", "translation_id": "Dan banyak sekali tanda-tanda (kekuasaan Allah) di langit dan di bumi yang mereka melaluinya, sedang mereka berpaling dari padanya.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 106, "text": "وَمَا یُؤۡمِنُ أَكۡثَرُهُم بِٱللَّهِ إِلَّا وَهُم مُّشۡرِكُونَ ۝١٠٦", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "وما يُقِرُّ هؤلاء المعرضون عن آيات الله بأن الله خالقهم ورازقهم وخالق كل شيء ومستحق للعبادة وحده إلا وهم مشركون في عبادتهم الأوثان والأصنام. تعالى الله عن ذلك علوًّا كبيرا.", "isBasmala": false, "translation_en": "And most of them do not believe in God unless they associate others.", "translation_id": "Dan sebahagian besar dari mereka tidak beriman kepada Allah, melainkan dalam keadaan mempersekutukan Allah (dengan sembahan-sembahan lain).", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 107, "text": "أَفَأَمِنُوۤا۟ أَن تَأۡتِیَهُمۡ غَـٰشِیَةࣱ مِّنۡ عَذَابِ ٱللَّهِ أَوۡ تَأۡتِیَهُمُ ٱلسَّاعَةُ بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ ۝١٠٧", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "فهل عندهم ما يجعلهم آمنين أن ينزل بهم عذاب من الله يعُمُّهم، أو أن تأتيهم القيامة فجأة، وهم لا يشعرون ولا يُحِسُّون بذلك.", "isBasmala": false, "translation_en": "Do they feel secure that a covering of God's punishment will not come upon them, or that the Hour will not come upon them suddenly, while they are unaware?", "translation_id": "Apakah mereka merasa aman dari kedatangan siksa Allah yang meliputi mereka, atau kedatangan kiamat kepada mereka secara mendadak, sedang mereka tidak menyadarinya?", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 108, "text": "قُلۡ هَـٰذِهِۦ سَبِیلِیۤ أَدۡعُوۤا۟ إِلَى ٱللَّهِۚ عَلَىٰ بَصِیرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِیۖ وَسُبۡحَـٰنَ ٱللَّهِ وَمَاۤ أَنَا۠ مِنَ ٱلۡمُشۡرِكِینَ ۝١٠٨", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "قل لهم -أيها الرسول-: هذه طريقتي، أدعو إلى عبادة الله وحده، على حجة من الله ويقين، أنا ومن اقتدى بي، وأنزِّه الله سبحانه وتعالى عن الشركاء، ولستُ من المشركين مع الله غيره.", "isBasmala": false, "translation_en": "Say, \"This is my way; I invite to God, based on clear knowledge-I and whoever follows me. Glory be to God; and I am not of the polytheists.\"", "translation_id": "Katakanlah: \"Inilah jalan (agama)ku, aku dan orang-orang yang mengikutiku mengajak (kamu) kepada Allah dengan hujjah yang nyata, Maha Suci Allah, dan aku tiada termasuk orang-orang yang musyrik\".", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 109, "text": "وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالࣰا نُّوحِیۤ إِلَیۡهِم مِّنۡ أَهۡلِ ٱلۡقُرَىٰۤۗ أَفَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡۗ وَلَدَارُ ٱلۡـَٔاخِرَةِ خَیۡرࣱ لِّلَّذِینَ ٱتَّقَوۡا۟ۚ أَفَلَا تَعۡقِلُونَ ۝١٠٩", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "وما أرسلنا من قبلك -أيها الرسول- للناس إلا رجالا منهم ننزل عليهم وحينا، وهم من أهل الحاضرة، فهم أقدر على فهم الدعوة والرسالة، يصدقهم المهتدون للحق، ويكذبهم الضالون عنه، أفلم يمشوا في الأرض، فيعاينوا كيف كان مآل المكذبين السابقين وما حلَّ بهم من الهلاك؟ ولَثواب الدار الآخرة أفضل من الدنيا وما فيها للذين آمنوا وخافوا ربهم. أفلا تتفكرون فتعتبروا؟", "isBasmala": false, "translation_en": "We did not send before you except men, whom We inspired, from the people of the towns. Have they not roamed the earth and seen the consequences for those before them? The Home of the Hereafter is better for those who are righteous. Do you not understand?", "translation_id": "Kami tidak mengutus sebelum kamu, melainkan orang laki-laki yang Kami berikan wahyu kepadanya diantara penduduk negeri. Maka tidakkah mereka bepergian di muka bumi lalu melihat bagaimana kesudahan orang-orang sebelum mereka (yang mendustakan rasul) dan sesungguhnya kampung akhirat adalah lebih baik bagi orang-orang yang bertakwa. Maka tidakkah kamu memikirkannya?", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 110, "text": "حَتَّىٰۤ إِذَا ٱسۡتَیۡـَٔسَ ٱلرُّسُلُ وَظَنُّوۤا۟ أَنَّهُمۡ قَدۡ كُذِبُوا۟ جَاۤءَهُمۡ نَصۡرُنَا فَنُجِّیَ مَن نَّشَاۤءُۖ وَلَا یُرَدُّ بَأۡسُنَا عَنِ ٱلۡقَوۡمِ ٱلۡمُجۡرِمِینَ ۝١١٠", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "ولا تستعجل -أيها الرسول- النصر على مكذبيك، فإن الرسل قبلك ما كان يأتيهم النصر عاجلا لحكمة نعلمها، حتى إذا يئس الرسل من قومهم، وأيقنوا أن قومهم قد كذبوهم ولا أمل في إيمانهم، جاءهم نصرنا عند شدة الكرب، فننجي من نشاء من الرسل وأتباعهم، ولا يُرَدُّ عذابنا عمَّن أجرم وتجرَّأ على الله. وفي هذا تسلية للنبي صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Until, when the messengers have despaired, and thought that they were rejected, Our help came to them. We save whomever We will, and Our severity is not averted from the guilty people.", "translation_id": "Sehingga apabila para rasul tidak mempunyai harapan lagi (tentang keimanan mereka) dan telah meyakini bahwa mereka telah didustakan, datanglah kepada para rasul itu pertolongan Kami, lalu diselamatkan orang-orang yang Kami kehendaki. Dan tidak dapat ditolak siksa Kami dari pada orang-orang yang berdosa.", "manzil": 3, "manzil_display": ""}, {"sura": 12, "sura_name": "يوسف", "revelation": "Makkiyah", "aya": 111, "text": "لَقَدۡ كَانَ فِی قَصَصِهِمۡ عِبۡرَةࣱ لِّأُو۟لِی ٱلۡأَلۡبَـٰبِۗ مَا كَانَ حَدِیثࣰا یُفۡتَرَىٰ وَلَـٰكِن تَصۡدِیقَ ٱلَّذِی بَیۡنَ یَدَیۡهِ وَتَفۡصِیلَ كُلِّ شَیۡءࣲ وَهُدࣰى وَرَحۡمَةࣰ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝١١١", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "لقد كان في نبأ المرسلين الذي قصصناه عليك وما حلَّ بالمكذبين عظة لأهل العقول السليمة. ما كان هذا القرآن حديثًا مكذوبًا مختلَقًا، ولكن أنزلناه مصدقًا لما سبقه من الكتب السماوية، وبيانًا لكل ما يحتاج إليه العباد من تحليل وتحريم، ومحبوب ومكروه وغير ذلك، وإرشادًا من الضلال، ورحمة لأهل الإيمان تهتدي به قلوبهم، فيعملون بما فيه من الأوامر والنواهي.", "isBasmala": false, "translation_en": "In their stories is a lesson for those who possess intelligence. This is not a fabricated tale, but a confirmation of what came before it, and a detailed explanation of all things, and guidance, and mercy for people who believe.", "translation_id": "Sesungguhnya pada kisah-kisah mereka itu terdapat pengajaran bagi orang-orang yang mempunyai akal. Al Quran itu bukanlah cerita yang dibuat-buat, akan tetapi membenarkan (kitab-kitab) yang sebelumnya dan menjelaskan segala sesuatu, dan sebagai petunjuk dan rahmat bagi kaum yang beriman.", "manzil": 3, "manzil_display": ""}], "249": [{"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 13, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 1, "text": "الۤمۤرۚ تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِۗ وَٱلَّذِیۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ ٱلۡحَقُّ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یُؤۡمِنُونَ ۝١", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "(المر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Meem, Ra. These are the signs of the Scripture. What is revealed to you from your Lord is the truth, but most people do not believe.", "translation_id": "Alif laam miim raa. Ini adalah ayat-ayat Al Kitab (Al Quran). Dan Kitab yang diturunkan kepadamu daripada Tuhanmu itu adalah benar: akan tetapi kebanyakan manusia tidak beriman (kepadanya).", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 2, "text": "ٱللَّهُ ٱلَّذِی رَفَعَ ٱلسَّمَـٰوَ ٰتِ بِغَیۡرِ عَمَدࣲ تَرَوۡنَهَاۖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِی لِأَجَلࣲ مُّسَمࣰّىۚ یُدَبِّرُ ٱلۡأَمۡرَ یُفَصِّلُ ٱلۡـَٔایَـٰتِ لَعَلَّكُم بِلِقَاۤءِ رَبِّكُمۡ تُوقِنُونَ ۝٢", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "الله تعالى هو الذي رفع السموات السبع بقدرته من غير عمد كما ترونها، ثم استوى -أي علا وارتفع- على العرش استواء يليق بجلاله وعظمته، وذلَّل الشمس والقمر لمنافع العباد، كلٌّ منهما يدور في فلكه إلى يوم القيامة. يدبِّر سبحانه أمور الدنيا والآخرة، يوضح لكم الآيات الدالة على قدرته وأنه لا إله إلا هو؛ لتوقنوا بالله والمعاد إليه، فتصدقوا بوعده ووعيده وتُخْلصوا العبادة له وحده.", "isBasmala": false, "translation_en": "God is He who raised the heavens without pillars that you can see, and then settled on the Throne. And He regulated the sun and the moon, each running for a specified period. He manages all affairs, and He explains the signs, that you may be certain of the meeting with your Lord.", "translation_id": "Allah-lah Yang meninggikan langit tanpa tiang (sebagaimana) yang kamu lihat, kemudian Dia bersemayam di atas 'Arasy, dan menundukkan matahari dan bulan. Masing-masing beredar hingga waktu yang ditentukan. Allah mengatur urusan (makhluk-Nya), menjelaskan tanda-tanda (kebesaran-Nya), supaya kamu meyakini pertemuan(mu) dengan Tuhanmu.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 3, "text": "وَهُوَ ٱلَّذِی مَدَّ ٱلۡأَرۡضَ وَجَعَلَ فِیهَا رَوَ ٰسِیَ وَأَنۡهَـٰرࣰاۖ وَمِن كُلِّ ٱلثَّمَرَ ٰتِ جَعَلَ فِیهَا زَوۡجَیۡنِ ٱثۡنَیۡنِۖ یُغۡشِی ٱلَّیۡلَ ٱلنَّهَارَۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَفَكَّرُونَ ۝٣", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "وهو سبحانه الذي جعل الأرض متسعة ممتدة، وهيأها لمعاشكم، وجعل فيها جبالا تُثبِّتُها وأنهارًا لشربكم ومنافعكم، وجعل فيها من كل الثمرات صنفين اثنين، فكان منها الأبيض والأسود والحلو والحامض، وجعل الليل يغطي النهار بظلمته، إن في ذلك كله لَعظات لقوم يتفكرون فيها، فيتعظون.", "isBasmala": false, "translation_en": "And it is He who spread the earth, and placed in it mountains and rivers. And He placed in it two kinds of every fruit. He causes the night to overlap the day. In that are signs for people who reflect.", "translation_id": "Dan Dialah Tuhan yang membentangkan bumi dan menjadikan gunung-gunung dan sungai-sungai padanya. Dan menjadikan padanya semua buah-buahan berpasang-pasangan, Allah menutupkan malam kepada siang. Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kebesaran Allah) bagi kaum yang memikirkan.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 4, "text": "وَفِی ٱلۡأَرۡضِ قِطَعࣱ مُّتَجَـٰوِرَ ٰتࣱ وَجَنَّـٰتࣱ مِّنۡ أَعۡنَـٰبࣲ وَزَرۡعࣱ وَنَخِیلࣱ صِنۡوَانࣱ وَغَیۡرُ صِنۡوَانࣲ یُسۡقَىٰ بِمَاۤءࣲ وَ ٰحِدࣲ وَنُفَضِّلُ بَعۡضَهَا عَلَىٰ بَعۡضࣲ فِی ٱلۡأُكُلِۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَعۡقِلُونَ ۝٤", "juz": 13, "hizb": "(*½ ح 25*)", "tafsir": "وفي الأرض قطع يجاور بعضها بعضًا، منها ما هو طيِّب يُنبتُ ما ينفع الناس، ومنها سَبِخة مِلْحة لا تُنبت شيئًا، وفي الأرض الطيبة بساتين من أعناب، وجعل فيها زروعًا مختلفة ونخيلا مجتمعًا في منبت واحد، وغير مجتمع فيه، كل ذلك في تربة واحدة، ويشرب من ماء واحد، ولكنه يختلف في الثمار والحجم والطعم وغير ذلك، فهذا حلو وهذا حامض، وبعضها أفضل من بعض في الأكل، إن في ذلك لَعلامات لمن كان له قلب يعقل عن الله تعالى أمره ونهيه.", "isBasmala": false, "translation_en": "On earth are adjacent terrains, and gardens of vines, and crops, and date-palms, from the same root or from distinct roots, irrigated with the same water. We make some taste better than others. In that are proofs for people who reason.", "translation_id": "Dan di bumi ini terdapat bagian-bagian yang berdampingan, dan kebun-kebun anggur, tanaman-tanaman dan pohon korma yang bercabang dan yang tidak bercabang, disirami dengan air yang sama. Kami melebihkan sebahagian tanam-tanaman itu atas sebahagian yang lain tentang rasanya. Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kebesaran Allah) bagi kaum yang berfikir.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 5, "text": "۞ وَإِن تَعۡجَبۡ فَعَجَبࣱ قَوۡلُهُمۡ أَءِذَا كُنَّا تُرَ ٰبًا أَءِنَّا لَفِی خَلۡقࣲ جَدِیدٍۗ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡۖ وَأُو۟لَـٰۤىِٕكَ ٱلۡأَغۡلَـٰلُ فِیۤ أَعۡنَاقِهِمۡۖ وَأُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝٥", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "وإن تعجب -أيها الرسول- من عدم إيمانهم بعد هذه الأدلة فالعجب الأشدُّ من قول الكفار: أإذا متنا وكنا ترابا نُبعث من جديد؟ أولئك هم الجاحدون بربهم الذي أوجدهم من العدم، وأولئك تكون السلاسل من النار في أعناقهم يوم القيامة، وأولئك يدخلون النار، ولا يخرجون منها أبدًا.", "isBasmala": false, "translation_en": "Should you wonder-the real wonder is their saying: \"When we have become dust, will we be in a new creation?\" Those are they who defied their Lord. Those are they who will have yokes around their necks. Those are the inhabitants of the Fire, where they will remain forever.", "translation_id": "Dan jika (ada sesuatu) yang kamu herankan, maka yang patut mengherankan adalah ucapan mereka: \"Apabila kami telah menjadi tanah, apakah kami sesungguhnya akan (dikembalikan) menjadi makhluk yang baru?\" Orang-orang itulah yang kafir kepada Tuhannya; dan orang-orang itulah (yang dilekatkan) belenggu di lehernya; mereka itulah penghuni neraka, mereka kekal di dalamnya.", "manzil": 3, "manzil_display": ""}], "250": [{"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 6, "text": "وَیَسۡتَعۡجِلُونَكَ بِٱلسَّیِّئَةِ قَبۡلَ ٱلۡحَسَنَةِ وَقَدۡ خَلَتۡ مِن قَبۡلِهِمُ ٱلۡمَثُلَـٰتُۗ وَإِنَّ رَبَّكَ لَذُو مَغۡفِرَةࣲ لِّلنَّاسِ عَلَىٰ ظُلۡمِهِمۡۖ وَإِنَّ رَبَّكَ لَشَدِیدُ ٱلۡعِقَابِ ۝٦", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "ويستعجلك المكذِّبون بالعقوبة التي لم أعاجلهم بها قبل الإيمان الذي يرجى به الأمان والحسنات، وقد مضت عقوبات المكذبين مِن قبلهم، فكيف لا يعتبرون بهم؟ وإن ربك -أيها الرسول- لَذو مغفرة لذنوبِ مَن تاب مِن ذنوبه من الناس على ظلمهم، يفتح لهم باب المغفرة، ويدعوهم إليها، وهم يظلمون أنفسهم بعصيانهم ربهم، وإن ربك لشديد العقاب على مَن أصرَّ على الكفر والضلال ومعصية الله.", "isBasmala": false, "translation_en": "And they urge you to hasten evil before good, though examples have passed away before them. Your Lord is full of forgiveness towards the people for their wrongdoings, yet your Lord is severe in retribution.", "translation_id": "Mereka meminta kepadamu supaya disegerakan (datangnya) siksa, sebelum (mereka meminta) kebaikan, padahal telah terjadi bermacam-macam contoh siksa sebelum mereka. Sesungguhnya Tuhanmu benar-benar mempunyai ampunan (yang luas) bagi manusia sekalipun mereka zalim, dan sesungguhnya Tuhanmu benar-benar sangat keras siksanya.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 7, "text": "وَیَقُولُ ٱلَّذِینَ كَفَرُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ ءَایَةࣱ مِّن رَّبِّهِۦۤۗ إِنَّمَاۤ أَنتَ مُنذِرࣱۖ وَلِكُلِّ قَوۡمٍ هَادٍ ۝٧", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "ويقول كفار \"مكة\": هلا جاءته معجزة محسوسة كعصا موسى وناقة صالح، وليس ذلك بيدك -أيها الرسول- فما أنت إلا مبلِّغ لهم، ومخوِّف مِن بأس الله. ولكل أمة رسول يرشدهم إلى الله تعالى.", "isBasmala": false, "translation_en": "Those who disbelieve say, \"Why was a miracle not sent down to him from his Lord?\" You are only a warner, and to every community is a guide.", "translation_id": "Orang-orang yang kafir berkata: \"Mengapa tidak diturunkan kepadanya (Muhammad) suatu tanda (kebesaran) dari Tuhannya?\" Sesungguhnya kamu hanyalah seorang pemberi peringatan; dan bagi tiap-tiap kaum ada orang yang memberi petunjuk.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 8, "text": "ٱللَّهُ یَعۡلَمُ مَا تَحۡمِلُ كُلُّ أُنثَىٰ وَمَا تَغِیضُ ٱلۡأَرۡحَامُ وَمَا تَزۡدَادُۚ وَكُلُّ شَیۡءٍ عِندَهُۥ بِمِقۡدَارٍ ۝٨", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "الله تعالى يعلم ما تحمل كلُّ أنثى في بطنها، أذكر هو أم أنثى؟ وشقي هو أم سعيد؟ ويعلم ما تنقصه الأرحام، فيسقط أو يولد قبل تسعة أشهر، وما يزيد حمله عليها. وكل شيء مقدَّر عند الله بمقدار من النقصان أو الزيادة لا يتجاوزه.", "isBasmala": false, "translation_en": "God knows what every female bears, and every increase and decrease of the wombs. With Him, everything is by measure.", "translation_id": "Allah mengetahui apa yang dikandung oleh setiap perempuan, dan kandungan rahim yang kurang sempurna dan yang bertambah. Dan segala sesuatu pada sisi-Nya ada ukurannya.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 9, "text": "عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ ٱلۡكَبِیرُ ٱلۡمُتَعَالِ ۝٩", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "الله عالم بما خفي عن الأبصار، وبما هو مشاهَد، الكبير في ذاته وأسمائه وصفاته، المتعال على جميع خلقه بذاته وقدرته وقهره.", "isBasmala": false, "translation_en": "The Knower of the Invisible and the Visible; the Grand, the Supreme.", "translation_id": "Yang mengetahui semua yang ghaib dan yang nampak; Yang Maha Besar lagi Maha Tinggi.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 10, "text": "سَوَاۤءࣱ مِّنكُم مَّنۡ أَسَرَّ ٱلۡقَوۡلَ وَمَن جَهَرَ بِهِۦ وَمَنۡ هُوَ مُسۡتَخۡفِۭ بِٱلَّیۡلِ وَسَارِبُۢ بِٱلنَّهَارِ ۝١٠", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "يستوي في علمه تعالى مَن أخفى القول منكم ومَن جهر به، ويستوي عنده مَن استتر بأعماله في ظلمة الليل، ومن جهر بها في وضح النهار.", "isBasmala": false, "translation_en": "It is the same; whether one of you conceals his speech, or declares it; whether he goes into hiding by night, or goes out by day.", "translation_id": "Sama saja (bagi Tuhan), siapa diantaramu yang merahasiakan ucapannya, dan siapa yang berterus-terang dengan ucapan itu, dan siapa yang bersembunyi di malam hari dan yang berjalan (menampakkan diri) di siang hari.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 11, "text": "لَهُۥ مُعَقِّبَـٰتࣱ مِّنۢ بَیۡنِ یَدَیۡهِ وَمِنۡ خَلۡفِهِۦ یَحۡفَظُونَهُۥ مِنۡ أَمۡرِ ٱللَّهِۗ إِنَّ ٱللَّهَ لَا یُغَیِّرُ مَا بِقَوۡمٍ حَتَّىٰ یُغَیِّرُوا۟ مَا بِأَنفُسِهِمۡۗ وَإِذَاۤ أَرَادَ ٱللَّهُ بِقَوۡمࣲ سُوۤءࣰا فَلَا مَرَدَّ لَهُۥۚ وَمَا لَهُم مِّن دُونِهِۦ مِن وَالٍ ۝١١", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "لله تعالى ملائكة يتعاقبون على الإنسان من بين يديه ومن خلفه، يحفظونه بأمر الله ويحصون ما يصدر عنه من خير أو شر. إن الله سبحانه وتعالى لا يغيِّر نعمة أنعمها على قوم إلا إذا غيَّروا ما أمرهم به فعصوه. وإذا أراد الله بجماعةٍ بلاءً فلا مفرَّ منه، وليس لهم مِن دون الله مِن وال يتولى أمورهم، فيجلب لهم المحبوب، ويدفع عنهم المكروه.", "isBasmala": false, "translation_en": "He has a succession; before him and behind him, protecting him by God's command. God does not change the condition of a people until they change what is within themselves. And if God wills any hardship for a people, there is no turning it back;, and apart from Him they have no protector.", "translation_id": "Bagi manusia ada malaikat-malaikat yang selalu mengikutinya bergiliran, di muka dan di belakangnya, mereka menjaganya atas perintah Allah. Sesungguhnya Allah tidak merubah keadaan sesuatu kaum sehingga mereka merubah keadaan yang ada pada diri mereka sendiri. Dan apabila Allah menghendaki keburukan terhadap sesuatu kaum, maka tak ada yang dapat menolaknya; dan sekali-kali tak ada pelindung bagi mereka selain Dia.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 12, "text": "هُوَ ٱلَّذِی یُرِیكُمُ ٱلۡبَرۡقَ خَوۡفࣰا وَطَمَعࣰا وَیُنشِئُ ٱلسَّحَابَ ٱلثِّقَالَ ۝١٢", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "هو الذي يريكم من آياته البرق -وهو النور اللامع من خلال السحاب- فتخافون أن تنزل عليكم منه الصواعق المحرقة، وتطمعون أن ينزل معه المطر، وبقدرته سبحانه يوجد السحاب المحمَّل بالماء الكثير لمنافعكم.", "isBasmala": false, "translation_en": "It is He who shows you the lightening, causing fear and hope. And He produces the heavy clouds.", "translation_id": "Dialah Tuhan yang memperlihatkan kilat kepadamu untuk menimbulkan ketakutan dan harapan, dan Dia mengadakan awan mendung.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 13, "text": "وَیُسَبِّحُ ٱلرَّعۡدُ بِحَمۡدِهِۦ وَٱلۡمَلَـٰۤىِٕكَةُ مِنۡ خِیفَتِهِۦ وَیُرۡسِلُ ٱلصَّوَ ٰعِقَ فَیُصِیبُ بِهَا مَن یَشَاۤءُ وَهُمۡ یُجَـٰدِلُونَ فِی ٱللَّهِ وَهُوَ شَدِیدُ ٱلۡمِحَالِ ۝١٣", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "ويسبِّح الرعد بحمد الله تسبيحًا يدل على خضوعه لربه، وتنزِّه الملائكة ربها مِن خوفها من الله، ويرسل الله الصواعق المهلكة فيهلك بها مَن يشاء من خلقه، والكفار يجادلون في وحدانية الله وقدرته على البعث، وهو شديد الحول والقوة والبطش بمن عصاه.", "isBasmala": false, "translation_en": "The thunder praises His glory, and so do the angels, in awe of Him. And He sends the thunderbolts, striking with them whomever He wills. Yet they argue about God, while He is Tremendous in might.", "translation_id": "Dan guruh itu bertasbih dengan memuji Allah, (demikian pula) para malaikat karena takut kepada-Nya, dan Allah melepaskan halilintar, lalu menimpakannya kepada siapa yang Dia kehendaki, dan mereka berbantah-bantahan tentang Allah, dan Dialah Tuhan Yang Maha keras siksa-Nya.", "manzil": 3, "manzil_display": ""}], "251": [{"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 14, "text": "لَهُۥ دَعۡوَةُ ٱلۡحَقِّۚ وَٱلَّذِینَ یَدۡعُونَ مِن دُونِهِۦ لَا یَسۡتَجِیبُونَ لَهُم بِشَیۡءٍ إِلَّا كَبَـٰسِطِ كَفَّیۡهِ إِلَى ٱلۡمَاۤءِ لِیَبۡلُغَ فَاهُ وَمَا هُوَ بِبَـٰلِغِهِۦۚ وَمَا دُعَاۤءُ ٱلۡكَـٰفِرِینَ إِلَّا فِی ضَلَـٰلࣲ ۝١٤", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "لله سبحانه وتعالى وحده دعوة التوحيد (لا إله إلا الله)، فلا يُعبد ولا يُدعى إلا هو، والآلهة التي يعبدونها من دون الله لا تجيب دعاء مَن دعاها، وحالهم معها كحال عطشان يمد يده إلى الماء من بعيد؛ ليصل إلى فمه فلا يصل إليه، وما سؤال الكافرين لها إلا غاية في البعد عن الصواب لإشراكهم بالله غيره.", "isBasmala": false, "translation_en": "To Him belongs the call to truth. Those they call upon besides Him do not respond to them with anything-except as someone who stretches his hands towards water, so that it may reach his mouth, but it does not reach it. The prayers of the unbelievers are only in vain.", "translation_id": "Hanya bagi Allah-lah (hak mengabulkan) doa yang benar. Dan berhala-berhala yang mereka sembah selain Allah tidak dapat memperkenankan sesuatupun bagi mereka, melainkan seperti orang yang membukakan kedua telapak tangannya ke dalam air supaya sampai air ke mulutnya, padahal air itu tidak dapat sampai ke mulutnya. Dan doa (ibadat) orang-orang kafir itu, hanyalah sia-sia belaka.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 15, "text": "وَ̅لِ̅لَّ̅هِ̅ ̅یَ̅سۡ̅جُ̅دُ̅ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ طَوۡعࣰا وَكَرۡهࣰا وَظِلَـٰلُهُم بِٱلۡغُدُوِّ وَٱلۡـَٔاصَالِ ۝١٥ ۩", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "ولله وحده يسجد خاضعًا منقادًا كُلُّ مَن في السموات والأرض، فيسجد ويخضع له المؤمنون طوعًا واختيارًا، ويخضع له الكافرون رغمًا عنهم؛ لأنهم يستكبرون عن عبادته، وحالهم وفطرتهم تكذِّبهم في ذلك، وتنقاد لعظمته ظلال المخلوقات، فتتحرك بإرادته أول النهار وآخره.", "isBasmala": false, "translation_en": "To God prostrates everyone in the heavens and the earth, willingly or unwillingly, as do their shadows, in the morning and in the evening.", "translation_id": "Hanya kepada Allah-lah sujud (patuh) segala apa yang di langit dan di bumi, baik dengan kemauan sendiri ataupun terpaksa (dan sujud pula) bayang-bayangnya di waktu pagi dan petang hari.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 16, "text": "قُلۡ مَن رَّبُّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ قُلِ ٱللَّهُۚ قُلۡ أَفَٱتَّخَذۡتُم مِّن دُونِهِۦۤ أَوۡلِیَاۤءَ لَا یَمۡلِكُونَ لِأَنفُسِهِمۡ نَفۡعࣰا وَلَا ضَرࣰّاۚ قُلۡ هَلۡ یَسۡتَوِی ٱلۡأَعۡمَىٰ وَٱلۡبَصِیرُ أَمۡ هَلۡ تَسۡتَوِی ٱلظُّلُمَـٰتُ وَٱلنُّورُۗ أَمۡ جَعَلُوا۟ لِلَّهِ شُرَكَاۤءَ خَلَقُوا۟ كَخَلۡقِهِۦ فَتَشَـٰبَهَ ٱلۡخَلۡقُ عَلَیۡهِمۡۚ قُلِ ٱللَّهُ خَـٰلِقُ كُلِّ شَیۡءࣲ وَهُوَ ٱلۡوَ ٰحِدُ ٱلۡقَهَّـٰرُ ۝١٦", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "قل -أيها الرسول- للمشركين: مَن خالق السَّموات والأرض ومدبِّرهما؟ قل: الله هو الخالق المدبر لهما، وأنتم تقرون بذلك، ثم قل لهم ملزمًا بالحجة: أجعلتم غيره معبودين لكم، وهم لا يَقْدرون على نفع أنفسهم أو ضرها فضلا عن نفعكم أو ضركم، وتركتم عبادة مالكها؟ قل لهم -أيها الرسول-: هل يستوي عندكم الكافر -وهو كالأعمى- والمؤمن وهو كالبصير؟ أم هل يستوي عندكم الكفر -وهو كالظلمات- والإيمان -وهو كالنور؟ أم أن أولياءهم الذين جعلوهم شركاء لله يخلقون مثل خَلْقه، فتشابه عليهم خَلْق الشركاء بخلق الله، فاعتقدوا استحقاقهم للعبادة؟ قل لهم -أيها الرسول-: الله تعالى خالق كل كائن من العدم، وهو المستحق للعبادة وحده، وهو الواحد القهار الذي يستحق الألوهية والعبادة، لا الأصنام والأوثان التي لا تضرُّ ولا تنفع.", "isBasmala": false, "translation_en": "Say, \"Who is the Lord of the heavens and the earth?\" Say, \"God.\" Say, \"Have you taken besides Him protectors, who have no power to profit or harm even themselves?\" Say, \"Are the blind and the seeing equal? Or are darkness and light equal? Or have they assigned to God associates, who created the likes of His creation, so that the creations seemed to them alike? Say, \"God is the Creator of all things, and He is The One, the Irresistible.\"", "translation_id": "Katakanlah: \"Siapakah Tuhan langit dan bumi?\" Jawabnya: \"Allah\". Katakanlah: \"Maka patutkah kamu mengambil pelindung-pelindungmu dari selain Allah, padahal mereka tidak menguasai kemanfaatan dan tidak (pula) kemudharatan bagi diri mereka sendiri?\". Katakanlah: \"Adakah sama orang buta dan yang dapat melihat, atau samakah gelap gulita dan terang benderang; apakah mereka menjadikan beberapa sekutu bagi Allah yang dapat menciptakan seperti ciptaan-Nya sehingga kedua ciptaan itu serupa menurut pandangan mereka?\" Katakanlah: \"Allah adalah Pencipta segala sesuatu dan Dialah Tuhan Yang Maha Esa lagi Maha Perkasa\".", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 17, "text": "أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَسَالَتۡ أَوۡدِیَةُۢ بِقَدَرِهَا فَٱحۡتَمَلَ ٱلسَّیۡلُ زَبَدࣰا رَّابِیࣰاۖ وَمِمَّا یُوقِدُونَ عَلَیۡهِ فِی ٱلنَّارِ ٱبۡتِغَاۤءَ حِلۡیَةٍ أَوۡ مَتَـٰعࣲ زَبَدࣱ مِّثۡلُهُۥۚ كَذَ ٰلِكَ یَضۡرِبُ ٱللَّهُ ٱلۡحَقَّ وَٱلۡبَـٰطِلَۚ فَأَمَّا ٱلزَّبَدُ فَیَذۡهَبُ جُفَاۤءࣰۖ وَأَمَّا مَا یَنفَعُ ٱلنَّاسَ فَیَمۡكُثُ فِی ٱلۡأَرۡضِۚ كَذَ ٰلِكَ یَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ ۝١٧", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "ثم ضرب الله سبحانه مثلا للحق والباطل بماء أنزله من السماء، فجَرَت به أودية الأرض بقدر صغرها وكبرها، فحمل السيل غثاء طافيًا فوقه لا نفع فيه. وضرب مثلا آخر: هو المعادن يوقِدون عليها النار لصهرها طلبًا للزينة كما في الذهب والفضة، أو طلبًا لمنافع ينتفعون بها كما في النحاس، فيخرج منها خبثها مما لا فائدة فيه كالذي كان مع الماء، بمثل هذا يضرب الله المثل للحق والباطل: فالباطل كغثاء الماء يتلاشى أو يُرْمى إذ لا فائدة منه، والحق كالماء الصافي، والمعادن النقية تبقى في الأرض للانتفاع بها، كما بيَّن لكم هذه الأمثال، كذلك يضربها للناس؛ ليتضح الحق من الباطل والهدى من الضلال.", "isBasmala": false, "translation_en": "He sends down water from the sky, and riverbeds flow according to their capacity. The current carries swelling froth. And from what they heat in fire of ornaments or utensils comes a similar froth. Thus God exemplifies truth and falsehood. As for the froth, it is swept away, but what benefits the people remains in the ground. Thus God presents the analogies.", "translation_id": "Allah telah menurunkan air (hujan) dari langit, maka mengalirlah air di lembah-lembah menurut ukurannya, maka arus itu membawa buih yang mengambang. Dan dari apa (logam) yang mereka lebur dalam api untuk membuat perhiasan atau alat-alat, ada (pula) buihnya seperti buih arus itu. Demikianlah Allah membuat perumpamaan (bagi) yang benar dan yang bathil. Adapun buih itu, akan hilang sebagai sesuatu yang tak ada harganya; adapun yang memberi manfaat kepada manusia, maka ia tetap di bumi. Demikianlah Allah membuat perumpamaan-perumpamaan.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 18, "text": "لِلَّذِینَ ٱسۡتَجَابُوا۟ لِرَبِّهِمُ ٱلۡحُسۡنَىٰۚ وَٱلَّذِینَ لَمۡ یَسۡتَجِیبُوا۟ لَهُۥ لَوۡ أَنَّ لَهُم مَّا فِی ٱلۡأَرۡضِ جَمِیعࣰا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡا۟ بِهِۦۤۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ سُوۤءُ ٱلۡحِسَابِ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمِهَادُ ۝١٨", "juz": 13, "hizb": "(*¾ ح 25*)", "tafsir": "للمؤمنين الذين أطاعوا الله ورسوله الجنة، والذين لم يطيعوا وكفروا به لهم النار، ولو كانوا يملكون كل ما في الأرض وضِعْفه معه لبذلوه فداء لأنفسهم من عذاب الله يوم القيامة، ولن يُتَقبل منهم، أولئك يحاسَبون على كل ما أسلفوه من عمل سيِّئ، ومسكنهم ومقامهم جهنم تكون لهم فراشًا، وبئس الفراش الذي مهدوه لأنفسهم.", "isBasmala": false, "translation_en": "For those who respond to their Lord is the best. But as for those who do not respond to Him, even if they possessed everything on earth, and twice as much, they could not redeem themselves with it. Those will have the worst reckoning; and their home is Hell-a miserable destination.", "translation_id": "Bagi orang-orang yang memenuhi seruan Tuhannya, (disediakan) pembalasan yang baik. Dan orang-orang yang tidak memenuhi seruan Tuhan, sekiranya mereka mempunyai semua (kekayaan) yang ada di bumi dan (ditambah) sebanyak isi bumi itu lagi besertanya, niscaya mereka akan menebus dirinya dengan kekayaan itu. Orang-orang itu disediakan baginya hisab yang buruk dan tempat kediaman mereka ialah Jahanam dan itulah seburuk-buruk tempat kediaman.", "manzil": 3, "manzil_display": ""}], "252": [{"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 19, "text": "۞ أَفَمَن یَعۡلَمُ أَنَّمَاۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ ٱلۡحَقُّ كَمَنۡ هُوَ أَعۡمَىٰۤۚ إِنَّمَا یَتَذَكَّرُ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ ۝١٩", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "هل الذي يعلم أن ما جاءك -أيها الرسول- من عند الله هو الحق فيؤمن به، كالأعمى عن الحق الذي لم يؤمن؟ إنما يتعظ أصحاب العقول السليمة الذين يوفون بعهد الله الذي أمرهم به، ولا ينكثون العهد المؤكد الذي عاهدوا الله عليه.", "isBasmala": false, "translation_en": "Is he who knows that what was revealed to your from your Lord is the truth, like him who is blind? Only those who reason will remember.", "translation_id": "Adakah orang yang mengetahui bahwasanya apa yang diturunkan kepadamu dari Tuhanmu itu benar sama dengan orang yang buta? Hanyalah orang-orang yang berakal saja yang dapat mengambil pelajaran,", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 20, "text": "ٱلَّذِینَ یُوفُونَ بِعَهۡدِ ٱللَّهِ وَلَا یَنقُضُونَ ٱلۡمِیثَـٰقَ ۝٢٠", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "هل الذي يعلم أن ما جاءك -أيها الرسول- من عند الله هو الحق فيؤمن به، كالأعمى عن الحق الذي لم يؤمن؟ إنما يتعظ أصحاب العقول السليمة الذين يوفون بعهد الله الذي أمرهم به، ولا ينكثون العهد المؤكد الذي عاهدوا الله عليه.", "isBasmala": false, "translation_en": "Those who fulfill the promise to God, and do not violate the agreement.", "translation_id": "(yaitu) orang-orang yang memenuhi janji Allah dan tidak merusak perjanjian,", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 21, "text": "وَٱلَّذِینَ یَصِلُونَ مَاۤ أَمَرَ ٱللَّهُ بِهِۦۤ أَن یُوصَلَ وَیَخۡشَوۡنَ رَبَّهُمۡ وَیَخَافُونَ سُوۤءَ ٱلۡحِسَابِ ۝٢١", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "وهم الذين يَصِلون ما أمرهم الله بوصله كالأرحام والمحتاجين، ويراقبون ربهم، ويخشون أن يحاسبهم على كل ذنوبهم، ولا يغفر لهم منها شيئًا.", "isBasmala": false, "translation_en": "And those who join what God has commanded to be joined, and fear their Lord, and dread the dire reckoning.", "translation_id": "dan orang-orang yang menghubungkan apa-apa yang Allah perintahkan supaya dihubungkan, dan mereka takut kepada Tuhannya dan takut kepada hisab yang buruk.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 22, "text": "وَٱلَّذِینَ صَبَرُوا۟ ٱبۡتِغَاۤءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقۡنَـٰهُمۡ سِرࣰّا وَعَلَانِیَةࣰ وَیَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّیِّئَةَ أُو۟لَـٰۤىِٕكَ لَهُمۡ عُقۡبَى ٱلدَّارِ ۝٢٢", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "وهم الذين صبروا على الأذى وعلى الطاعة، وعن المعصية طلبًا لرضا ربهم، وأدَّوا الصلاة على أتمِّ وجوهها، وأدَّوا من أموالهم زكاتهم المفروضة، والنفقات المستحبة في الخفاء والعلن، ويدفعون بالحسنة السيئة فتمحوها، أولئك الموصوفون بهذه الصفات لهم العاقبة المحمودة في الآخرة.", "isBasmala": false, "translation_en": "And those who patiently seek the presence of their Lord, and pray regularly, and spend from Our provisions to them, secretly and openly, and repel evil with good. These will have the Ultimate Home.", "translation_id": "Dan orang-orang yang sabar karena mencari keridhaan Tuhannya, mendirikan shalat, dan menafkahkan sebagian rezeki yang Kami berikan kepada mereka, secara sembunyi atau terang-terangan serta menolak kejahatan dengan kebaikan; orang-orang itulah yang mendapat tempat kesudahan (yang baik),", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 23, "text": "جَنَّـٰتُ عَدۡنࣲ یَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَاۤىِٕهِمۡ وَأَزۡوَ ٰجِهِمۡ وَذُرِّیَّـٰتِهِمۡۖ وَٱلۡمَلَـٰۤىِٕكَةُ یَدۡخُلُونَ عَلَیۡهِم مِّن كُلِّ بَابࣲ ۝٢٣", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "تلك العاقبة هي جنات عدن يقيمون فيها لا يزولون عنها، ومعهم الصالحون من الآباء والزوجات والذريات من الذكور والإنات، وتدخل الملائكة عليهم من كل باب؛ لتهنئتهم بدخول الجنة.", "isBasmala": false, "translation_en": "Everlasting Gardens, which they will enter, along with the righteous among their parents, and their spouses, and their descendants. And the angels will enter upon them from every gate.", "translation_id": "(yaitu) surga 'Adn yang mereka masuk ke dalamnya bersama-sama dengan orang-orang yang saleh dari bapak-bapaknya, isteri-isterinya dan anak cucunya, sedang malaikat-malaikat masuk ke tempat-tempat mereka dari semua pintu;", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 24, "text": "سَلَـٰمٌ عَلَیۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ ۝٢٤", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "تقول الملائكة لهم: سَلِمْتم من كل سوء بسبب صبركم على طاعة الله، فنِعْمَ عاقبة الدار الجنة.", "isBasmala": false, "translation_en": "\"Peace be upon you, because you endured patiently. How excellent is the Final Home.\"", "translation_id": "(sambil mengucapkan): \"Salamun 'alaikum bima shabartum\". Maka alangkah baiknya tempat kesudahan itu.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 25, "text": "وَٱلَّذِینَ یَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِیثَـٰقِهِۦ وَیَقۡطَعُونَ مَاۤ أَمَرَ ٱللَّهُ بِهِۦۤ أَن یُوصَلَ وَیُفۡسِدُونَ فِی ٱلۡأَرۡضِ أُو۟لَـٰۤىِٕكَ لَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوۤءُ ٱلدَّارِ ۝٢٥", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "أما الأشقياء فقد وُصِفوا بضد صفات المؤمنين، فهم الذين لا يوفون بعهد الله بإفراده سبحانه بالعبادة بعد أن أكدوه على أنفسهم، وهم الذين يقطعون ما أمرهم الله بوصله مِن صلة الأرحام وغيرها، ويفسدون في الأرض بعمل المعاصي، أولئك الموصوفون بهذه الصفات القبيحة لهم الطرد من رحمة الله، ولهم ما يسوءهم من العذاب الشديد في الدار الآخرة.", "isBasmala": false, "translation_en": "As for those who violate the promise to God, after pledging to keep it, and sever what God has commanded to be joined, and spread corruption on earth-these, the curse will be upon them, and they will have the Worst Home.", "translation_id": "Orang-orang yang merusak janji Allah setelah diikrarkan dengan teguh dan memutuskan apa-apa yang Allah perintahkan supaya dihubungkan dan mengadakan kerusakan di bumi, orang-orang itulah yang memperoleh kutukan dan bagi mereka tempat kediaman yang buruk (Jahannam).", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 26, "text": "ٱللَّهُ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ وَفَرِحُوا۟ بِٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَا فِی ٱلۡـَٔاخِرَةِ إِلَّا مَتَـٰعࣱ ۝٢٦", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "الله وحده يوسِّع الرزق لمن يشاء من عباده، ويضيِّق على مَن يشاء منهم، وفرح الكفار بالسَّعة في الحياة الدنيا، وما هذه الحياة الدنيا بالنسبة للآخرة إلا شيء قليل يتمتع به، سُرعان ما يزول.", "isBasmala": false, "translation_en": "God dispenses the provisions to whomever He wills, and restricts. And they delight in the worldly life; yet the worldly life, compared to the Hereafter, is only enjoyment.", "translation_id": "Allah meluaskan rezeki dan menyempitkannya bagi siapa yang Dia kehendaki. Mereka bergembira dengan kehidupan di dunia, padahal kehidupan dunia itu (dibanding dengan) kehidupan akhirat, hanyalah kesenangan (yang sedikit).", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 27, "text": "وَیَقُولُ ٱلَّذِینَ كَفَرُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ ءَایَةࣱ مِّن رَّبِّهِۦۚ قُلۡ إِنَّ ٱللَّهَ یُضِلُّ مَن یَشَاۤءُ وَیَهۡدِیۤ إِلَیۡهِ مَنۡ أَنَابَ ۝٢٧", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "ويقول الكفار عنادًا: هلا أُنزل على محمد معجزة محسوسة كمعجزة موسى وعيسى. قل لهم: إن الله يضل مَن يشاء من المعاندين عن الهداية ولا تنفعه المعجزات، ويهدي إلى دينه الحق مَن رجع إليه وطلب رضوانه.", "isBasmala": false, "translation_en": "Those who disbelieve say, \"If only a miracle was sent down to him from his Lord.\" Say, \"God leads astray whomever He wills, and He guides to Himself whoever repents.\"", "translation_id": "Orang-orang kafir berkata: \"Mengapa tidak diturunkan kepadanya (Muhammad) tanda (mukjizat) dari Tuhannya?\" Katakanlah: \"Sesungguhnya Allah menyesatkan siapa yang Dia kehendaki dan menunjuki orang-orang yang bertaubat kepada-Nya\",", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 28, "text": "ٱلَّذِینَ ءَامَنُوا۟ وَتَطۡمَىِٕنُّ قُلُوبُهُم بِذِكۡرِ ٱللَّهِۗ أَلَا بِذِكۡرِ ٱللَّهِ تَطۡمَىِٕنُّ ٱلۡقُلُوبُ ۝٢٨", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "ويهدي الذين تسكن قلوبهم بتوحيد الله وذكره فتطمئن، ألا بطاعة الله وذكره وثوابه تسكن القلوب وتستأنس.", "isBasmala": false, "translation_en": "Those who believe, and whose hearts find comfort in the remembrance of God. Surely, it is in the remembrance of God that hearts find comfort.\"", "translation_id": "(yaitu) orang-orang yang beriman dan hati mereka manjadi tenteram dengan mengingat Allah. Ingatlah, hanya dengan mengingati Allah-lah hati menjadi tenteram.", "manzil": 3, "manzil_display": ""}], "253": [{"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 29, "text": "ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ طُوبَىٰ لَهُمۡ وَحُسۡنُ مَـَٔابࣲ ۝٢٩", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "الذين صدَّقوا بالله ورسوله، وعملوا الأعمال الصالحات لهم فرح وقرة عين، وحال طيبة، ومرجع حسن إلى جنة الله ورضوانه.", "isBasmala": false, "translation_en": "For those who believe and do righteous deeds-for them is happiness and a beautiful return.", "translation_id": "Orang-orang yang beriman dan beramal saleh, bagi mereka kebahagiaan dan tempat kembali yang baik.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 30, "text": "كَذَ ٰلِكَ أَرۡسَلۡنَـٰكَ فِیۤ أُمَّةࣲ قَدۡ خَلَتۡ مِن قَبۡلِهَاۤ أُمَمࣱ لِّتَتۡلُوَا۟ عَلَیۡهِمُ ٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ وَهُمۡ یَكۡفُرُونَ بِٱلرَّحۡمَـٰنِۚ قُلۡ هُوَ رَبِّی لَاۤ إِلَـٰهَ إِلَّا هُوَ عَلَیۡهِ تَوَكَّلۡتُ وَإِلَیۡهِ مَتَابِ ۝٣٠", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "كما أرسلنا المرسلين قبلك أرسلناك -أيها الرسول- في أمة قد مضت مِن قبلها أمم المرسلين؛ لتتلو على هذه الأمة القرآن المنزل عليك، وحال قومك الجحود بوحدانية الرحمن، قل لهم -أيها الرسول-: الرحمن الذي لم تتخذوه إلهًا واحدًا هو ربي وحده لا معبود بحق سواه، عليه اعتمدت ووثقت، وإليه مرجعي وإنابتي.", "isBasmala": false, "translation_en": "Thus We sent you among a community before which other communities have passed away, that you may recite to them what We revealed to you. Yet they deny the Benevolent One. Say, \"He is my Lord; there is no god but He; in Him I trust, and to Him is my repentance.\"", "translation_id": "Demikianlah, Kami telah mengutus kamu pada suatu umat yang sungguh telah berlalu beberapa umat sebelumnya, supaya kamu membacakan kepada mereka (Al Quran) yang Kami wahyukan kepadamu, padahal mereka kafir kepada Tuhan Yang Maha Pemurah. Katakanlah: \"Dialah Tuhanku tidak ada Tuhan selain Dia; hanya kepada-Nya aku bertawakkal dan hanya kepada-Nya aku bertaubat\".", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 31, "text": "وَلَوۡ أَنَّ قُرۡءَانࣰا سُیِّرَتۡ بِهِ ٱلۡجِبَالُ أَوۡ قُطِّعَتۡ بِهِ ٱلۡأَرۡضُ أَوۡ كُلِّمَ بِهِ ٱلۡمَوۡتَىٰۗ بَل لِّلَّهِ ٱلۡأَمۡرُ جَمِیعًاۗ أَفَلَمۡ یَا۟یۡـَٔسِ ٱلَّذِینَ ءَامَنُوۤا۟ أَن لَّوۡ یَشَاۤءُ ٱللَّهُ لَهَدَى ٱلنَّاسَ جَمِیعࣰاۗ وَلَا یَزَالُ ٱلَّذِینَ كَفَرُوا۟ تُصِیبُهُم بِمَا صَنَعُوا۟ قَارِعَةٌ أَوۡ تَحُلُّ قَرِیبࣰا مِّن دَارِهِمۡ حَتَّىٰ یَأۡتِیَ وَعۡدُ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا یُخۡلِفُ ٱلۡمِیعَادَ ۝٣١", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "يردُّ الله -تعالى- على الكافرين الذين طلبوا إنزال معجزات محسوسة على النبي صلى الله عليه وسلم فيقول لهم: ولو أن ثمة قرآنًا يقرأ، فتزول به الجبال عن أماكنها، أو تتشقق به الأرض أنهارًا، أو يحيا به الموتى وتُكَلَّم -كما طلبوا منك- لكان هذا القرآن هو المتصف بذلك دون غيره، ولما آمنوا به. بل لله وحده الأمر كله في المعجزات وغيرها. أفلم يعلم المؤمنون أن الله لو يشاء لآمن أهل الأرض كلهم من غير معجزة؟ ولا يزال الكفار تنزل بهم مصيبة بسبب كفرهم كالقتل والأسر في غزوات المسلمين، أو تنزل تلك المصيبة قريبًا من دارهم، حتى يأتي وعد الله بالنصر عليهم، إن الله لا يخلف الميعاد.", "isBasmala": false, "translation_en": "Even if there were a Quran, by which mountains could be set in motion, or by which the earth could be shattered, or by which the dead could be made to speak. In fact, every decision rests with God. Did the believers not give up and realize that had God willed, He would have guided all humanity? Disasters will continue to strike those who disbelieve, because of their deeds, or they fall near their homes, until God's promise comes true. God never breaks a promise.", "translation_id": "Dan sekiranya ada suatu bacaan (kitab suci) yang dengan bacaan itu gunung-gunung dapat digoncangkan atau bumi jadi terbelah atau oleh karenanya orang-orang yang sudah mati dapat berbicara, (tentulah Al Quran itulah dia). Sebenarnya segala urusan itu adalah kepunyaan Allah. Maka tidakkah orang-orang yang beriman itu mengetahui bahwa seandainya Allah menghendaki (semua manusia beriman), tentu Allah memberi petunjuk kepada manusia semuanya. Dan orang-orang yang kafir senantiasa ditimpa bencana disebabkan perbuatan mereka sendiri atau bencana itu terjadi dekat tempat kediaman mereka, sehingga datanglah janji Allah. Sesungguhnya Allah tidak menyalahi janji.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 32, "text": "وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلࣲ مِّن قَبۡلِكَ فَأَمۡلَیۡتُ لِلَّذِینَ كَفَرُوا۟ ثُمَّ أَخَذۡتُهُمۡۖ فَكَیۡفَ كَانَ عِقَابِ ۝٣٢", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "وإذا كانوا قد سخروا من دعوتك -أيها الرسول- فلقد سَخِرَتْ أمم من قبلك برسلهم، فلا تحزن فقد أمهلتُ الذين كفروا، ثم أخذتُهم بعقابي، وكان عقابًا شديدًا.", "isBasmala": false, "translation_en": "Messengers before you were ridiculed, but I granted the disbelievers respite, and then I seized them. What a punishment it was!", "translation_id": "Dan sesungguhnya telah diperolok-olokkan beberapa rasul sebelum kamu, maka Aku beri tangguh kepada orang-orang kafir itu kemudian Aku binasakan mereka. Alangkah hebatnya siksaan-Ku itu!", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 33, "text": "أَفَمَنۡ هُوَ قَاۤىِٕمٌ عَلَىٰ كُلِّ نَفۡسِۭ بِمَا كَسَبَتۡۗ وَجَعَلُوا۟ لِلَّهِ شُرَكَاۤءَ قُلۡ سَمُّوهُمۡۚ أَمۡ تُنَبِّـُٔونَهُۥ بِمَا لَا یَعۡلَمُ فِی ٱلۡأَرۡضِ أَم بِظَـٰهِرࣲ مِّنَ ٱلۡقَوۡلِۗ بَلۡ زُیِّنَ لِلَّذِینَ كَفَرُوا۟ مَكۡرُهُمۡ وَصُدُّوا۟ عَنِ ٱلسَّبِیلِۗ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادࣲ ۝٣٣", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "أفمن هو قائم على كل نفس يُحصي عليها ما تعمل، أحق أن يعبد، أم هذه المخلوقات العاجزة؟ وهم -من جهلهم- جعلوا لله شركاء مِن خَلْقه يعبدونهم، قل لهم -أيها الرسول-: اذكروا أسماءهم وصفاتهم، ولن يجدوا من صفاتهم ما يجعلهم أهلا للعبادة، أم تخبرون الله بشركاء في أرضه لا يعلمهم، أم تسمونهم شركاء بظاهر من اللفظ من غير أن يكون لهم حقيقة. بل حسَّن الشيطان للكفار قولهم الباطل وصدَّهم عن سبيل الله. ومَن لم يوفِّقه الله لهدايته فليس له أحد يهديه، ويوفقه إلى الحق والرشاد.", "isBasmala": false, "translation_en": "Is He who is watchful over the deeds of every soul? Yet they ascribe associates to God. Say, \"Name them! Or are you informing Him of something on earth He does not know, or is it a show of words?\" In fact, the scheming of those who disbelieve is made to appear good to them, and they are averted from the path. Whomever God misguides has no guide.", "translation_id": "Maka apakah Tuhan yang menjaga setiap diri terhadap apa yang diperbuatnya (sama dengan yang tidak demikian sifatnya)? Mereka menjadikan beberapa sekutu bagi Allah. Katakanlah: \"Sebutkanlah sifat-sifat mereka itu\". Atau apakah kamu hendak memberitakan kepada Allah apa yang tidak diketahui-Nya di bumi, atau kamu mengatakan (tentang hal itu) sekadar perkataan pada lahirnya saja. Sebenarnya orang-orang kafir itu dijadikan (oleh syaitan) memandang baik tipu daya mereka dan dihalanginya dari jalan (yang benar). Dan barangsiapa yang disesatkan Allah, maka baginya tak ada seorangpun yang akan memberi petunjuk.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 34, "text": "لَّهُمۡ عَذَابࣱ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَشَقُّۖ وَمَا لَهُم مِّنَ ٱللَّهِ مِن وَاقࣲ ۝٣٤", "juz": 13, "hizb": "(* ح 26*)", "tafsir": "لهؤلاء الكفار الصادين عن سبيل الله عذاب شاق في الحياة الدنيا بالقتل والأسر والخزي، ولَعذابهم في الآخرة أثقل وأشد، وليس لهم مانع يمنعهم من عذاب الله.", "isBasmala": false, "translation_en": "There is for them torment in the worldly life, but the torment of the Hereafter is harsher. And they have no defender against God.", "translation_id": "Bagi mereka azab dalam kehidupan dunia dan sesungguhnya azab akhirat adalah lebih keras dan tak ada bagi mereka seorang pelindungpun dari (azab) Allah.", "manzil": 3, "manzil_display": ""}], "254": [{"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 35, "text": "۞ مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِی وُعِدَ ٱلۡمُتَّقُونَۖ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ أُكُلُهَا دَاۤىِٕمࣱ وَظِلُّهَاۚ تِلۡكَ عُقۡبَى ٱلَّذِینَ ٱتَّقَوا۟ۚ وَّعُقۡبَى ٱلۡكَـٰفِرِینَ ٱلنَّارُ ۝٣٥", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "صفة الجنة التي وعد الله بها الذين يخشونه أنها تجري من تحت أشجارها وقصورها الأنهار، ثمرها لا ينقطع، وظلها لا يزول ولا ينقص، تلك المثوبة بالجنة عاقبة الذين خافوا الله، فاجتنبوا معاصيه وأدَّوا فرائضه، وعاقبة الكافرين بالله النار.", "isBasmala": false, "translation_en": "The likeness of the Garden promised to the righteous: rivers flowing beneath it; its food is perpetual, and so is its shade. Such is the sequel for those who guard against evil, but the sequel of the disbelievers is the Fire.", "translation_id": "Perumpamaan surga yang dijanjikan kepada orang-orang yang takwa ialah (seperti taman); mengalir sungai-sungai di dalamnya; buahnya tak henti-henti sedang naungannya (demikian pula). Itulah tempat kesudahan bagi orang-orang yang bertakwa, sedang tempat kesudahan bagi orang-orang kafir ialah neraka.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 36, "text": "وَٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یَفۡرَحُونَ بِمَاۤ أُنزِلَ إِلَیۡكَۖ وَمِنَ ٱلۡأَحۡزَابِ مَن یُنكِرُ بَعۡضَهُۥۚ قُلۡ إِنَّمَاۤ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ وَلَاۤ أُشۡرِكَ بِهِۦۤۚ إِلَیۡهِ أَدۡعُوا۟ وَإِلَیۡهِ مَـَٔابِ ۝٣٦", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "والذين أعطيناهم الكتاب من اليهود والنصارى مَن آمن منهم بك كعبد الله بن سلام والنجاشي، يستبشرون بالقرآن المنزل عليك لموافقته ما عندهم، ومن المتحزبين على الكفر ضدك، كالسَّيد والعاقب، أُسْقفَي \"نجران\"، وكعب بن الأشرف، مَن ينكر بعض المنزل عليك، قل لهم: إنما أمرني الله أن أعبده وحده، ولا أشرك به شيئًا، إلى عبادته أدعو الناس، وإليه مرجعي ومآبي.", "isBasmala": false, "translation_en": "Those to whom We gave the Scripture rejoice in what was revealed to you, while some factions reject parts of it. Say, \"I am commanded to worship God, and to never associate anything with Him. To Him I invite, and to Him is my return.\"", "translation_id": "Orang-orang yang telah Kami berikan kitab kepada mereka bergembira dengan kitab yang diturunkan kepadamu, dan di antara golongan-golongan (Yahudi dan Nasrani) yang bersekutu, ada yang mengingkari sebahagiannya. Katakanlah \"Sesungguhnya aku hanya diperintah untuk menyembah Allah dan tidak mempersekutukan sesuatupun dengan Dia. Hanya kepada-Nya aku seru (manusia) dan hanya kepada-Nya aku kembali\".", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 37, "text": "وَكَذَ ٰلِكَ أَنزَلۡنَـٰهُ حُكۡمًا عَرَبِیࣰّاۚ وَلَىِٕنِ ٱتَّبَعۡتَ أَهۡوَاۤءَهُم بَعۡدَ مَا جَاۤءَكَ مِنَ ٱلۡعِلۡمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِیࣲّ وَلَا وَاقࣲ ۝٣٧", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "وكما أنزلنا الكتب على الأنبياء بلسانهم أنزلنا إليك -أيها الرسول- القرآن بلغة العرب؛ لتحكم به، ولئن اتبعت أهواء المشركين في عبادة غير الله -بعد الحق الذي جاءك من الله- ليس لك ناصر ينصرك ويمنعك من عذابه.", "isBasmala": false, "translation_en": "Thus We revealed it an Arabic code of law. Were you to follow their desires, after the knowledge that has come to you, you would have neither ally nor defender against God.", "translation_id": "Dan demikianlah, Kami telah menurunkan Al Quran itu sebagai peraturan (yang benar) dalam bahasa Arab. Dan seandainya kamu mengikuti hawa nafsu mereka setelah datang pengetahuan kepadamu, maka sekali-kali tidak ada pelindung dan pemelihara bagimu terhadap (siksa) Allah.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 38, "text": "وَلَقَدۡ أَرۡسَلۡنَا رُسُلࣰا مِّن قَبۡلِكَ وَجَعَلۡنَا لَهُمۡ أَزۡوَ ٰجࣰا وَذُرِّیَّةࣰۚ وَمَا كَانَ لِرَسُولٍ أَن یَأۡتِیَ بِـَٔایَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ لِكُلِّ أَجَلࣲ كِتَابࣱ ۝٣٨", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "وإذا قالوا: ما لك -أيها الرسول- تتزوج النساء؟ فلقد بعثنا قبلك رسلا من البشر وجعلنا لهم أزواجًا وذرية، وإذا قالوا: لو كان رسولا لأتى بما طلبنا من المعجزات، فليس في وُسْع رسولٍ أن يأتي بمعجزةٍ أرادها قومه إلا بإذن الله. لكل أمر قضاه الله كتاب وأجل قد كتبه الله عنده، لا يتقدم ولا يتأخر.", "isBasmala": false, "translation_en": "We sent messengers before you, and We assigned for them wives and offspring. No messenger could bring a sign except with the permission of God. For every era is a scripture.", "translation_id": "Dan sesungguhnya Kami telah mengutus beberapa Rasul sebelum kamu dan Kami memberikan kepada mereka isteri-isteri dan keturunan. Dan tidak ada hak bagi seorang Rasul mendatangkan sesuatu ayat (mukjizat) melainkan dengan izin Allah. Bagi tiap-tiap masa ada Kitab (yang tertentu).", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 39, "text": "یَمۡحُوا۟ ٱللَّهُ مَا یَشَاۤءُ وَیُثۡبِتُۖ وَعِندَهُۥۤ أُمُّ ٱلۡكِتَـٰبِ ۝٣٩", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "يمحو الله ما يشاء من الأحكام وغيرها، ويُبْقي ما يشاء منها لحكمة يعلمها، وعنده أمُّ الكتاب، وهو اللوح المحفوظ.", "isBasmala": false, "translation_en": "God abolishes whatever He wills, and He affirms. With Him is the source of the Scripture.", "translation_id": "Allah menghapuskan apa yang Dia kehendaki dan menetapkan (apa yang Dia kehendaki), dan di sisi-Nya-lah terdapat Ummul-Kitab (Lauh mahfuzh).", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 40, "text": "وَإِن مَّا نُرِیَنَّكَ بَعۡضَ ٱلَّذِی نَعِدُهُمۡ أَوۡ نَتَوَفَّیَنَّكَ فَإِنَّمَا عَلَیۡكَ ٱلۡبَلَـٰغُ وَعَلَیۡنَا ٱلۡحِسَابُ ۝٤٠", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "وإن أريناك -أيها الرسول- بعض العقاب الذي توعَّدْنا به أعداءك من الخزي والنَّكال في الدنيا فذلك المعجَّل لهم، وإن توفيناك قبل أن ترى ذلك، فما عليك إلا تبليغ الدعوة، وعلينا الحساب والجزاء.", "isBasmala": false, "translation_en": "Whether We show you some of what We have promised them, or We cause you to die-your duty is to inform, and Ours is the reckoning.", "translation_id": "Dan jika Kami perlihatkan kepadamu sebahagian (siksa) yang Kami ancamkan kepada mereka atau Kami wafatkan kamu (hal itu tidak penting bagimu) karena sesungguhnya tugasmu hanya menyampaikan saja, sedang Kami-lah yang menghisab amalan mereka.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 41, "text": "أَوَ لَمۡ یَرَوۡا۟ أَنَّا نَأۡتِی ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۚ وَٱللَّهُ یَحۡكُمُ لَا مُعَقِّبَ لِحُكۡمِهِۦۚ وَهُوَ سَرِیعُ ٱلۡحِسَابِ ۝٤١", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "أولم يبصر هؤلاء الكفار أنا نأتي الأرض ننقصها من أطرافها، وذلك بفتح المسلمين بلاد المشركين وإلحاقها ببلاد المسلمين؟ والله سبحانه يحكم لا معقِّب لحكمه وقضائه، وهو سريع الحساب، فلا يستعجلوا بالعذاب؛ فإن كل آت قريب.", "isBasmala": false, "translation_en": "Do they not see how We deal with the earth, diminishing it at its edges? God judges; and nothing can hold back His judgment. And He is quick to settle accounts.", "translation_id": "Dan apakah mereka tidak melihat bahwa sesungguhnya Kami mendatangi daerah-daerah (orang-orang kafir), lalu Kami kurangi daerah-daerah itu (sedikit demi sedikit) dari tepi-tepinya? Dan Allah menetapkan hukum (menurut kehendak-Nya), tidak ada yang dapat menolak ketetapan-Nya; dan Dialah Yang Maha cepat hisab-Nya.", "manzil": 3, "manzil_display": ""}, {"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 42, "text": "وَقَدۡ مَكَرَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَلِلَّهِ ٱلۡمَكۡرُ جَمِیعࣰاۖ یَعۡلَمُ مَا تَكۡسِبُ كُلُّ نَفۡسࣲۗ وَسَیَعۡلَمُ ٱلۡكُفَّـٰرُ لِمَنۡ عُقۡبَى ٱلدَّارِ ۝٤٢", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "ولقد دبَّر الذين من قبلهم المكايد لرسلهم، كما فعل هؤلاء معك، فلله المكر جميعًا، فيبطل مكرهم، ويعيده عليهم بالخيبة والندم، يعلم سبحانه ما تكسب كل نفس من خير أو شر فتجازى عليه. وسيعلم الكفار -إذا قدموا على ربهم- لمن تكون العاقبة المحمودة بعد هذه الدنيا؟ إنها لأتباع الرسل. وفي هذا تهديد ووعيد للكافرين.", "isBasmala": false, "translation_en": "Those before them planned, but the entire plan is up to God. He knows what every soul earns. Those who disbelieve will know to whom the Ultimate Home is.", "translation_id": "Dan sungguh orang-orang kafir yang sebelum mereka (kafir Mekah) telah mengadakan tipu daya, tetapi semua tipu daya itu adalah dalam kekuasaan Allah. Dia mengetahui apa yang diusahakan oleh setiap diri, dan orang-orang kafir akan mengetahui untuk siapa tempat kesudahan (yang baik) itu.", "manzil": 3, "manzil_display": ""}], "255": [{"sura": 13, "sura_name": "الرعد", "revelation": "Madaniyah", "aya": 43, "text": "وَیَقُولُ ٱلَّذِینَ كَفَرُوا۟ لَسۡتَ مُرۡسَلࣰاۚ قُلۡ كَفَىٰ بِٱللَّهِ شَهِیدَۢا بَیۡنِی وَبَیۡنَكُمۡ وَمَنۡ عِندَهُۥ عِلۡمُ ٱلۡكِتَـٰبِ ۝٤٣", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "ويقول الذين كفروا لنبي الله: -يا محمد- ما أرسلك الله، قل لهم: كفى بالله شهيدًا بصدقي وكذبكم، وكَفَتْ شهادة مَن عنده علم الكتاب من اليهود والنصارى ممن آمن برسالتي، وما جئتُ به من عند الله، واتبع الحق فصرَّح بتلك الشهادة، ولم يكتمها.", "isBasmala": false, "translation_en": "Those who disbelieve say, \"You are not a messenger.\" Say, \"God is a sufficient witness between me and you, and whoever has knowledge of the Scripture.\"", "translation_id": "Berkatalah orang-orang kafir: \"Kamu bukan seorang yang dijadikan Rasul\". Katakanlah: \"Cukuplah Allah menjadi saksi antaraku dan kamu, dan antara orang yang mempunyai ilmu Al Kitab\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 13, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 1, "text": "الۤرۚ كِتَـٰبٌ أَنزَلۡنَـٰهُ إِلَیۡكَ لِتُخۡرِجَ ٱلنَّاسَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ بِإِذۡنِ رَبِّهِمۡ إِلَىٰ صِرَ ٰطِ ٱلۡعَزِیزِ ٱلۡحَمِیدِ ۝١", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Ra. A Scripture that We revealed to you, that you may bring humanity from darkness to light-with the permission of their Lord-to the path of the Almighty, the Praiseworthy.", "translation_id": "Alif, laam raa. (Ini adalah) Kitab yang Kami turunkan kepadamu supaya kamu mengeluarkan manusia dari gelap gulita kepada cahaya terang benderang dengan izin Tuhan mereka, (yaitu) menuju jalan Tuhan Yang Maha Perkasa lagi Maha Terpuji.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 2, "text": "ٱللَّهِ ٱلَّذِی لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۗ وَوَیۡلࣱ لِّلۡكَـٰفِرِینَ مِنۡ عَذَابࣲ شَدِیدٍ ۝٢", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "God-to whom belongs what is in the heavens and the earth. And woe to the disbelievers from a severe torment.", "translation_id": "Allah-lah yang memiliki segala apa yang di langit dan di bumi. Dan kecelakaanlah bagi orang-orang kafir karena siksaan yang sangat pedih,", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 3, "text": "ٱلَّذِینَ یَسۡتَحِبُّونَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا عَلَى ٱلۡـَٔاخِرَةِ وَیَصُدُّونَ عَن سَبِیلِ ٱللَّهِ وَیَبۡغُونَهَا عِوَجًاۚ أُو۟لَـٰۤىِٕكَ فِی ضَلَـٰلِۭ بَعِیدࣲ ۝٣", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "وهؤلاء الذين أعرضوا ولم يؤمنوا بالله ويتبعوا رسله هم الذين يختارون الحياة الدنيا الفانية، ويتركون الآخرة الباقية، ويمنعون الناس عن اتباع دين الله، ويريدونه طريقًا معوجًا ليوافق أهواءهم، أولئك الموصوفون بهذه الصفات في ضلال عن الحق بعيد عن كل أسباب الهداية.", "isBasmala": false, "translation_en": "Those who prefer the present life to the Hereafter, and repel from the path of God, and seek to make it crooked-these are far astray.", "translation_id": "(yaitu) orang-orang yang lebih menyukai kehidupan dunia dari pada kehidupan akhirat, dan menghalang-halangi (manusia) dari jalan Allah dan menginginkan agar jalan Allah itu bengkok. Mereka itu berada dalam kesesatan yang jauh.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 4, "text": "وَمَاۤ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِیُبَیِّنَ لَهُمۡۖ فَیُضِلُّ ٱللَّهُ مَن یَشَاۤءُ وَیَهۡدِی مَن یَشَاۤءُۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٤", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "وما أرسلنا مِن رسولٍ قبلك -أيها النبي- إلا بلُغة قومه؛ ليوضِّح لهم شريعة الله، فيضل الله من يشاء عن الهدى، ويهدي من يشاء إلى الحق، وهو العزيز في ملكه، الحكيم الذي يضع الأمور في مواضعها وَفْق الحكمة.", "isBasmala": false, "translation_en": "We never sent any messenger except in the language of his people, to make things clear for them. God leads astray whom He wills, and guides whom He wills. He is the Mighty, the Wise.", "translation_id": "Kami tidak mengutus seorang rasulpun, melainkan dengan bahasa kaumnya, supaya ia dapat memberi penjelasan dengan terang kepada mereka. Maka Allah menyesatkan siapa yang Dia kehendaki, dan memberi petunjuk kepada siapa yang Dia kehendaki. Dan Dialah Tuhan Yang Maha Kuasa lagi Maha Bijaksana.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 5, "text": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔایَـٰتِنَاۤ أَنۡ أَخۡرِجۡ قَوۡمَكَ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِ وَذَكِّرۡهُم بِأَیَّىٰمِ ٱللَّهِۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ ۝٥", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "ولقد أرسلنا موسى إلى بني إسرائيل وأيدناه بالمعجزات الدالة على صدقه، وأمرناه بأن يدعوهم إلى الإيمان؛ ليخرجهم من الضلال إلى الهدى، ويذكِّرهم بنعم الله ونقمه في أيامه، إن في هذا التذكير بها لَدلالات لكل صبَّار على طاعة الله، وعن محارمه، وعلى أقداره، شكور قائم بحقوق الله، يشكر الله على نعمه، وخصَّهم بذلك؛ لأنهم هم الذين يعتبرون بها، ولا يَغْفُلون عنها.", "isBasmala": false, "translation_en": "We sent Moses with Our signs: \"Bring your people out of darkness into light, and remind them of the Days of God.\" In that are signs for every patient and thankful person.\"", "translation_id": "Dan sesungguhnya Kami telah mengutus Musa dengan membawa ayat-ayat Kami, (dan Kami perintahkan kepadanya): \"Keluarkanlah kaummu dari gelap gulita kepada cahaya terang benderang dan ingatkanlah mereka kepada hari-hari Allah\". Sesunguhnya pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi setiap orang penyabar dan banyak bersyukur.", "manzil": 3, "manzil_display": ""}], "256": [{"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 6, "text": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِ ٱذۡكُرُوا۟ نِعۡمَةَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ أَنجَىٰكُم مِّنۡ ءَالِ فِرۡعَوۡنَ یَسُومُونَكُمۡ سُوۤءَ ٱلۡعَذَابِ وَیُذَبِّحُونَ أَبۡنَاۤءَكُمۡ وَیَسۡتَحۡیُونَ نِسَاۤءَكُمۡۚ وَفِی ذَ ٰلِكُم بَلَاۤءࣱ مِّن رَّبِّكُمۡ عَظِیمࣱ ۝٦", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "واذكر -أيها الرسول- لقومك قصة موسى حين قال لبني إسرائيل: اذكروا نعمة الله عليكم حين أنجاكم من فرعون وأتباعه يذيقونكم أشد العذاب، ويذبِّحون أبناءكم الذكور، حتى لا يأتي منهم من يستولي على مُلْك فرعون، ويبقون الإناث على قيد الحياة ذليلات، وفي ذلكم البلاء والإنجاء اختبار لكم من ربكم عظيم.", "isBasmala": false, "translation_en": "Moses said to his people, \"Remember God's blessings upon you, as He delivered you from the people of Pharaoh, who inflicted on you terrible suffering, slaughtering your sons while sparing your daughters. In that was a serious trial from your Lord.\"", "translation_id": "Dan (ingatlah), ketika Musa berkata kepada kaumnya: \"Ingatlah nikmat Allah atasmu ketika Dia menyelamatkan kamu dari (Fir'aun dan) pengikut-pengikutnya, mereka menyiksa kamu dengan siksa yang pedih, mereka menyembelih anak-anak laki-lakimu, membiarkan hidup anak-anak perempuanmu; dan pada yang demikian itu ada cobaan yang besar dari Tuhanmu\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 7, "text": "وَإِذۡ تَأَذَّنَ رَبُّكُمۡ لَىِٕن شَكَرۡتُمۡ لَأَزِیدَنَّكُمۡۖ وَلَىِٕن كَفَرۡتُمۡ إِنَّ عَذَابِی لَشَدِیدࣱ ۝٧", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "وقال لهم موسى: واذكروا حين أعلم ربكم إعلامًا مؤكَّدًا: لئن شكرتموه على نعمه ليزيدنكم من فضله، ولئن جحدتم نعمة الله ليعذبنَّكم عذابًا شديدًا.", "isBasmala": false, "translation_en": "And when your Lord proclaimed: \"If you give thanks, I will grant you increase; but if you are ungrateful, My punishment is severe.\"", "translation_id": "Dan (ingatlah juga), tatkala Tuhanmu memaklumkan; \"Sesungguhnya jika kamu bersyukur, pasti Kami akan menambah (nikmat) kepadamu, dan jika kamu mengingkari (nikmat-Ku), maka sesungguhnya azab-Ku sangat pedih\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 8, "text": "وَقَالَ مُوسَىٰۤ إِن تَكۡفُرُوۤا۟ أَنتُمۡ وَمَن فِی ٱلۡأَرۡضِ جَمِیعࣰا فَإِنَّ ٱللَّهَ لَغَنِیٌّ حَمِیدٌ ۝٨", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "وقال لهم: إن تكفروا بالله أنتم وجميع أهل الأرض فلن تضروا الله شيئًا؛ فإن الله لغني عن خلقه، مستحق للحمد والثناء، محمود في كل حال.", "isBasmala": false, "translation_en": "And Moses said, \"Even if you are ungrateful, together with everyone on earth-God is in no need, Worthy of Praise.\"", "translation_id": "Dan Musa berkata: \"Jika kamu dan orang-orang yang ada di muka bumi semuanya mengingkari (nikmat Allah) maka sesungguhnya Allah Maha Kaya lagi Maha Terpuji\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 9, "text": "أَلَمۡ یَأۡتِكُمۡ نَبَؤُا۟ ٱلَّذِینَ مِن قَبۡلِكُمۡ قَوۡمِ نُوحࣲ وَعَادࣲ وَثَمُودَ وَٱلَّذِینَ مِنۢ بَعۡدِهِمۡ لَا یَعۡلَمُهُمۡ إِلَّا ٱللَّهُۚ جَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَرَدُّوۤا۟ أَیۡدِیَهُمۡ فِیۤ أَفۡوَ ٰهِهِمۡ وَقَالُوۤا۟ إِنَّا كَفَرۡنَا بِمَاۤ أُرۡسِلۡتُم بِهِۦ وَإِنَّا لَفِی شَكࣲّ مِّمَّا تَدۡعُونَنَاۤ إِلَیۡهِ مُرِیبࣲ ۝٩", "juz": 13, "hizb": "(*¼ ح 26*)", "tafsir": "ألم يأتكم -يا أمَّة محمد- خبر الأمم التي سبقتكم، قوم نوح وقوم هود وقوم صالح، والأمم التي بعدهم، لا يحصي عددهم إلا الله، جاءتهم رسلهم بالبراهين الواضحات، فعضُّوا أيديهم غيظًا واستنكافًا عن قَبول الإيمان، وقالوا لرسلهم: إنا لا نصدِّق بما جئتمونا به، وإنا لفي شكٍّ مما تدعوننا إليه من الإيمان والتوحيد موجب للريبة.", "isBasmala": false, "translation_en": "Has not the story reached you, of those before you, the people of Noah, and Aad, and Thamood-and those after them? None knows them except God. Their messengers came to them with the clear proofs, but they tried to silence them, and said, \"We reject what you are sent with, and we are in serious doubt regarding what you are calling us to.\"", "translation_id": "Belumkah sampai kepadamu berita orang-orang sebelum kamu (yaitu) kaum Nuh, 'Ad, Tsamud dan orang-orang sesudah mereka. Tidak ada yang mengetahui mereka selain Allah. Telah datang rasul-rasul kepada mereka (membawa) bukti-bukti yang nyata lalu mereka menutupkan tangannya ke mulutnya (karena kebencian), dan berkata: \"Sesungguhnya kami mengingkari apa yang kamu disuruh menyampaikannya (kepada kami), dan sesungguhnya kami benar-benar dalam keragu-raguan yang menggelisahkan terhadap apa yang kamu ajak kami kepadanya\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 10, "text": "۞ قَالَتۡ رُسُلُهُمۡ أَفِی ٱللَّهِ شَكࣱّ فَاطِرِ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ یَدۡعُوكُمۡ لِیَغۡفِرَ لَكُم مِّن ذُنُوبِكُمۡ وَیُؤَخِّرَكُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّىۚ قَالُوۤا۟ إِنۡ أَنتُمۡ إِلَّا بَشَرࣱ مِّثۡلُنَا تُرِیدُونَ أَن تَصُدُّونَا عَمَّا كَانَ یَعۡبُدُ ءَابَاۤؤُنَا فَأۡتُونَا بِسُلۡطَـٰنࣲ مُّبِینࣲ ۝١٠", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "قالت لهم رسلهم: أفي الله وعبادته -وحده- ريب، وهو خالق السموات والأرض، ومنشئهما من العدم على غير مثال سابق، وهو يدعوكم إلى الإيمان؛ ليغفر لكم ذنوبكم، ويؤخر بقاءكم في الدنيا إلى أجل قدَّره، وهو نهاية آجالكم، فلا يعذبكم في الدنيا؟ فقالوا لرسلهم: ما نراكم إلا بشرًا صفاتكم كصفاتنا، لا فضل لكم علينا يؤهلكم أن تكونوا رسلا. تريدون أن تمنعونا من عبادة ما كان يعبده آباونا من الأصنام والأوثان، فأتونا بحجة ظاهرة تشهد على صحة ما تقولون.", "isBasmala": false, "translation_en": "Their messengers said, \"Is there any doubt about God, Maker of the heavens and the earth? He calls you to forgive you your sins, and to defer you until a stated term.\" They said, \"You are only humans like us; you want to turn us away from what our ancestors worshiped; so bring us a clear proof.\"", "translation_id": "Berkata rasul-rasul mereka: \"Apakah ada keragu-raguan terhadap Allah, Pencipta langit dan bumi? Dia menyeru kamu untuk memberi ampunan kepadamu dari dosa-dosamu dan menangguhkan (siksaan)mu sampai masa yang ditentukan?\" Mereka berkata: \"Kamu tidak lain hanyalah manusia seperti kami juga. Kamu menghendaki untuk menghalang-halangi (membelokkan) kami dari apa yang selalu disembah nenek moyang kami, karena itu datangkanlah kepada kami, bukti yang nyata\".", "manzil": 3, "manzil_display": ""}], "257": [{"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 11, "text": "قَالَتۡ لَهُمۡ رُسُلُهُمۡ إِن نَّحۡنُ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ وَلَـٰكِنَّ ٱللَّهَ یَمُنُّ عَلَىٰ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۖ وَمَا كَانَ لَنَاۤ أَن نَّأۡتِیَكُم بِسُلۡطَـٰنٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ۝١١", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "ولما سمع الرسل ما قاله أقوامهم قالوا لهم: حقًا ما نحن إلا بشر مثلكم كما قلتم، ولكن الله يتفضل بإنعامه على مَن يشاء من عباده فيصطفيهم لرسالته، وما طلبتم من البرهان المبين، فلا يمكن لنا ولا نستطيع أن نأتيكم به إلا بإذن الله وتوفيقه، وعلى الله وحده يعتمد المؤمنون في كل أمورهم.", "isBasmala": false, "translation_en": "Their messengers said to them, \"We are only humans like you, but God favors whomever He wills from among His servants. We cannot possibly show you any proof, except by leave of God. In God let the faithful put their trust.\"", "translation_id": "Rasul-rasul mereka berkata kepada mereka: \"Kami tidak lain hanyalah manusia seperti kamu, akan tetapi Allah memberi karunia kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya. Dan tidak patut bagi kami mendatangkan suatu bukti kepada kamu melainkan dengan izin Allah. Dan hanya kepada Allah sajalah hendaknya orang-orang mukmin bertawakkal.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 12, "text": "وَمَا لَنَاۤ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ عَلَىٰ مَاۤ ءَاذَیۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ ۝١٢", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "وكيف لا نعتمد على الله، وهو الذي أرشدنا إلى طريق النجاة من عذابه باتباع أحكام دينه؟ ولنصبرنَّ على إيذائكم لنا بالكلام السيئ وغيره، وعلى الله وحده يجب أن يعتمد المؤمنون في نصرهم، وهزيمة أعدائهم.", "isBasmala": false, "translation_en": "\"And why should we not trust in God, when He has guided us in our ways? We will persevere in the face of your persecution. And upon God the reliant should rely.\"", "translation_id": "Mengapa kami tidak akan bertawakkal kepada Allah padahal Dia telah menunjukkan jalan kepada kami, dan kami sungguh-sungguh akan bersabar terhadap gangguan-gangguan yang kamu lakukan kepada kami. Dan hanya kepada Allah saja orang-orang yang bertawakkal itu, berserah diri\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 13, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِرُسُلِهِمۡ لَنُخۡرِجَنَّكُم مِّنۡ أَرۡضِنَاۤ أَوۡ لَتَعُودُنَّ فِی مِلَّتِنَاۖ فَأَوۡحَىٰۤ إِلَیۡهِمۡ رَبُّهُمۡ لَنُهۡلِكَنَّ ٱلظَّـٰلِمِینَ ۝١٣", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "وضاقت صدور الكفار مما قاله الرسل فقالوا لهم: لنطردنكم من بلادنا حتى تعودوا إلى ديننا، فأوحى الله إلى رسله أنه سيهلك الجاحدين الذين كفروا به وبرسله.", "isBasmala": false, "translation_en": "Those who disbelieved said to their messengers, \"We will expel you from our land, unless you return to our religion.\" And their Lord inspired them: \"We will destroy the wrongdoers.\"", "translation_id": "Orang-orang kafir berkata kepada Rasul-rasul mereka: \"Kami sungguh-sungguh akan mengusir kamu dari negeri kami atau kamu kembali kepada agama kami\". Maka Tuhan mewahyukan kepada mereka: \"Kami pasti akan membinasakan orang-orang yang zalim itu,", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 14, "text": "وَلَنُسۡكِنَنَّكُمُ ٱلۡأَرۡضَ مِنۢ بَعۡدِهِمۡۚ ذَ ٰلِكَ لِمَنۡ خَافَ مَقَامِی وَخَافَ وَعِیدِ ۝١٤", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "ولنجعلن العاقبة الحسنة للرسل وأتباعهم بإسكانهم أرض الكافرين بعد إهلاكهم، ذلك الإهلاك للكفار، وإسكان المؤمنين أرضهم أمر مؤكد لمن خاف مقامه بين يديَّ يوم القيامة، وخشي وعيدي وعذابي.", "isBasmala": false, "translation_en": "\"And We will settle you in the land after them. That is for him who fears My Majesty, and fears My threats.\"", "translation_id": "dan Kami pasti akan menempatkan kamu di negeri-negeri itu sesudah mereka. Yang demikian itu (adalah untuk) orang-orang yang takut (akan menghadap) kehadirat-Ku dan yang takut kepada ancaman-Ku\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 15, "text": "وَٱسۡتَفۡتَحُوا۟ وَخَابَ كُلُّ جَبَّارٍ عَنِیدࣲ ۝١٥", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "ولجأ الرسل إلى ربهم وسألوه النصر على أعدائهم والحكم بينهم، فاستجاب لهم، وهلك كل متكبر لا يقبل الحق ولا يُذْعن له، ولا يقر بتوحيد الله وإخلاص العبادة له.", "isBasmala": false, "translation_en": "And they prayed for victory, and every stubborn tyrant came to disappointment.", "translation_id": "Dan mereka memohon kemenangan (atas musuh-musuh mereka) dan binasalah semua orang yang berlaku sewenang-wenang lagi keras kepala,", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 16, "text": "مِّن وَرَاۤىِٕهِۦ جَهَنَّمُ وَیُسۡقَىٰ مِن مَّاۤءࣲ صَدِیدࣲ ۝١٦", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "ومِن أمام هذا الكافر جهنم يَلْقى عذابها؛ ويُسقى فيها من القيح والدم الذي يَخْرج من أجسام أهل النار.", "isBasmala": false, "translation_en": "Beyond him lies Hell, and he will be given to drink putrid water.", "translation_id": "di hadapannya ada Jahannam dan dia akan diberi minuman dengan air nanah,", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 17, "text": "یَتَجَرَّعُهُۥ وَلَا یَكَادُ یُسِیغُهُۥ وَیَأۡتِیهِ ٱلۡمَوۡتُ مِن كُلِّ مَكَانࣲ وَمَا هُوَ بِمَیِّتࣲۖ وَمِن وَرَاۤىِٕهِۦ عَذَابٌ غَلِیظࣱ ۝١٧", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "يحاول المتكبر ابتلاع القيح والدم وغير ذلك مما يسيل من أهل النار مرة بعد مرة، فلا يستطيع أن يبتلعه؛ لقذارته وحرارته، ومرارته، ويأتيه العذاب الشديد من كل نوع ومن كل عضو من جسده، وما هو بميت فيستريح، وله من بعد هذا العذاب عذاب آخر مؤلم.", "isBasmala": false, "translation_en": "He will guzzle it, but he will not swallow it. Death will come at him from every direction, but he will not die. And beyond this is relentless suffering.", "translation_id": "diminumnnya air nanah itu dan hampir dia tidak bisa menelannya dan datanglah (bahaya) maut kepadanya dari segenap penjuru, tetapi dia tidak juga mati, dan dihadapannya masih ada azab yang berat.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 18, "text": "مَّثَلُ ٱلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡۖ أَعۡمَـٰلُهُمۡ كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّیحُ فِی یَوۡمٍ عَاصِفࣲۖ لَّا یَقۡدِرُونَ مِمَّا كَسَبُوا۟ عَلَىٰ شَیۡءࣲۚ ذَ ٰلِكَ هُوَ ٱلضَّلَـٰلُ ٱلۡبَعِیدُ ۝١٨", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "صفة أعمال الكفار في الدنيا كالبر وصلة الأرحام كصفة رماد اشتدت به الريح في يوم ذي ريح شديدة، فلم تترك له أثرًا، فكذلك أعمالهم لا يجدون منها ما ينفعهم عند الله، فقد أذهبها الكفر كما أذهبت الريح الرماد، ذلك السعي والعمل على غير أساس، هو الضلال البعيد عن الطريق المستقيم.", "isBasmala": false, "translation_en": "The likeness of those who disbelieve in their Lord: their works are like ashes, in a fierce wind, on a stormy day. They have no control over anything they have earned. That is the utmost misguidance.", "translation_id": "Orang-orang yang kafir kepada Tuhannya, amalan-amalan mereka adalah seperti abu yang ditiup angin dengan keras pada suatu hari yang berangin kencang. Mereka tidak dapat mengambil manfaat sedikitpun dari apa yang telah mereka usahakan (di dunia). Yang demikian itu adalah kesesatan yang jauh.", "manzil": 3, "manzil_display": ""}], "258": [{"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 19, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِن یَشَأۡ یُذۡهِبۡكُمۡ وَیَأۡتِ بِخَلۡقࣲ جَدِیدࣲ ۝١٩", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "ألم تعلم أيها المخاطب -والمراد عموم الناس- أن الله أوجد السموات والأرض على الوجه الصحيح الدال على حكمته، وأنه لم يخلقهما عبثًا، بل للاستدلال بهما على وحدانيته، وكمال قدرته، فيعبدوه وحده، ولا يشركوا به شيئًا؟ إن يشأ يذهبكم ويأت بقوم غيركم يطيعون الله.", "isBasmala": false, "translation_en": "Do you not see that God created the heavens and the earth with truth? If He wills, He can do away with you, and bring a new creation.", "translation_id": "Tidakkah kamu perhatikan, bahwa sesungguhnya Allah telah menciptakan langit dan bumi dengan hak? Jika Dia menghendaki, niscaya Dia membinasakan kamu dan mengganti(mu) dengan makhluk yang baru,", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 20, "text": "وَمَا ذَ ٰلِكَ عَلَى ٱللَّهِ بِعَزِیزࣲ ۝٢٠", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "وما إهلاككم والإتيان بغيركم بممتنع على الله، بل هو سهل يسير.", "isBasmala": false, "translation_en": "And that is not difficult for God.", "translation_id": "dan yang demikian itu sekali-kali tidak sukar bagi Allah.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 21, "text": "وَبَرَزُوا۟ لِلَّهِ جَمِیعࣰا فَقَالَ ٱلضُّعَفَـٰۤؤُا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوۤا۟ إِنَّا كُنَّا لَكُمۡ تَبَعࣰا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا مِنۡ عَذَابِ ٱللَّهِ مِن شَیۡءࣲۚ قَالُوا۟ لَوۡ هَدَىٰنَا ٱللَّهُ لَهَدَیۡنَـٰكُمۡۖ سَوَاۤءٌ عَلَیۡنَاۤ أَجَزِعۡنَاۤ أَمۡ صَبَرۡنَا مَا لَنَا مِن مَّحِیصࣲ ۝٢١", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "وخرجت الخلائق من قبورهم، وظهروا كلهم يوم القيامة لله الواحد القهار؛ ليحكم بينهم، فيقول الأتباع لقادتهم: إنَّا كنَّا لكم في الدنيا أتباعًا، نأتمر بأمركم، فهل أنتم -اليوم- دافعون عنا من عذاب الله شيئًا كما كنتم تَعِدوننا؟ فيقول الرؤساء: لو هدانا الله إلى الإيمان لأرشدناكم إليه، ولكنه لم يوفقنا، فضللنا وأضللناكم، يستوي علينا وعليكم الـجَزَع والصبر عليه، فليس لنا مهرب من العذاب ولا منجى.", "isBasmala": false, "translation_en": "They will emerge before God, altogether. The weak will say to those who were proud, \"We were your followers, can you protect us at all against God's punishment?\" They will say, \"Had God guided us, we would have guided you. It is the same for us; whether we mourn, or are patient; there is no asylum for us.\"", "translation_id": "Dan mereka semuanya (di padang Mahsyar) akan berkumpul menghadap ke hadirat Allah, lalu berkatalah orang-orang yang lemah kepada orang-orang yang sombong: \"Sesungguhnya kami dahulu adalah pengikut-pengikutmu, maka dapatkah kamu menghindarkan daripada kami azab Allah (walaupun) sedikit saja? Mereka menjawab: \"Seandainya Allah memberi petunjuk kepada kami, niscaya kami dapat memberi petunjuk kepadamu. Sama saja bagi kita, apakah kita mengeluh ataukah bersabar. Sekali-kali kita tidak mempunyai tempat untuk melarikan diri\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 22, "text": "وَقَالَ ٱلشَّیۡطَـٰنُ لَمَّا قُضِیَ ٱلۡأَمۡرُ إِنَّ ٱللَّهَ وَعَدَكُمۡ وَعۡدَ ٱلۡحَقِّ وَوَعَدتُّكُمۡ فَأَخۡلَفۡتُكُمۡۖ وَمَا كَانَ لِیَ عَلَیۡكُم مِّن سُلۡطَـٰنٍ إِلَّاۤ أَن دَعَوۡتُكُمۡ فَٱسۡتَجَبۡتُمۡ لِیۖ فَلَا تَلُومُونِی وَلُومُوۤا۟ أَنفُسَكُمۖ مَّاۤ أَنَا۠ بِمُصۡرِخِكُمۡ وَمَاۤ أَنتُم بِمُصۡرِخِیَّ إِنِّی كَفَرۡتُ بِمَاۤ أَشۡرَكۡتُمُونِ مِن قَبۡلُۗ إِنَّ ٱلظَّـٰلِمِینَ لَهُمۡ عَذَابٌ أَلِیمࣱ ۝٢٢", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "وقال الشيطان -بعد أن قضى الله الأمر وحاسب خَلْقه، ودخل أهلُ الجنة الجنةَ وأهلُ النارِ النارَ-: إن الله وعدكم وعدًا حقًا بالبعث والجزاء، ووعدتكم وعدًا باطلا أنه لا بَعْثَ ولا جزاء، فأخلفتكم وعدي، وما كان لي عليكم من قوة أقهركم بها على اتباعي، ولا كانت معي حجة، ولكن دعوتكم إلى الكفر والضلال فاتبعتموني، فلا تلوموني ولوموا أنفسكم، فالذنب ذنبكم، ما أنا بمغيثكم ولا أنتم بمغيثيَّ من عذاب الله، إني تبرَّأت مِن جَعْلِكم لي شريكًا مع الله في طاعته في الدنيا. إن الظالمين -في إعراضهم عن الحق واتباعهم الباطل- لهم عذاب مؤلم موجع.", "isBasmala": false, "translation_en": "And Satan will say, when the issue is settled, \"God has promised you the promise of truth, and I promised you, but I failed you. I had no authority over you, except that I called you, and you answered me. So do not blame me, but blame yourselves. I cannot come to your aid, nor can you come to my aid. I reject your associating with me in the past. The wrongdoers will have a torment most painful.\"", "translation_id": "Dan berkatalah syaitan tatkala perkara (hisab) telah diselesaikan: \"Sesungguhnya Allah telah menjanjikan kepadamu janji yang benar, dan akupun telah menjanjikan kepadamu tetapi aku menyalahinya. Sekali-kali tidak ada kekuasaan bagiku terhadapmu, melainkan (sekedar) aku menyeru kamu lalu kamu mematuhi seruanku, oleh sebab itu janganlah kamu mencerca aku akan tetapi cercalah dirimu sendiri. Aku sekali-kali tidak dapat menolongmu dan kamupun sekali-kali tidak dapat menolongku. Sesungguhnya aku tidak membenarkan perbuatanmu mempersekutukan aku (dengan Allah) sejak dahulu\". Sesungguhnya orang-orang yang zalim itu mendapat siksaan yang pedih.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 23, "text": "وَأُدۡخِلَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا بِإِذۡنِ رَبِّهِمۡۖ تَحِیَّتُهُمۡ فِیهَا سَلَـٰمٌ ۝٢٣", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "وأُدخل الذين صدَّقوا الله ورسوله وعملوا الصالحات جنات تجري من تحت أشجارها وقصورها الأنهار، لا يخرجون منها أبدًا -بإذن ربهم وحوله وقوته- يُحَيَّوْن فيها بسلام من الله وملائكته والمؤمنين.", "isBasmala": false, "translation_en": "But those who believed and did good deeds will be admitted into gardens beneath which rivers flow, to remain therein forever, by leave of their Lord. Their greeting therein will be: \"Peace.\"", "translation_id": "Dan dimasukkanlah orang-orang yang beriman dan beramal saleh ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya dengan seizin Tuhan mereka. Ucapan penghormatan mereka dalam surga itu ialah \"salaam\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 24, "text": "أَلَمۡ تَرَ كَیۡفَ ضَرَبَ ٱللَّهُ مَثَلࣰا كَلِمَةࣰ طَیِّبَةࣰ كَشَجَرَةࣲ طَیِّبَةٍ أَصۡلُهَا ثَابِتࣱ وَفَرۡعُهَا فِی ٱلسَّمَاۤءِ ۝٢٤", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "ألم تعلم -أيها الرسول- كيف ضرب الله مثلا لكلمة التوحيد (لا إله إلا الله) بشجرة عظيمة، وهي النخلة، أصلها متمكن في الأرض، وأعلاها مرتفع علوًّا نحو السماء؟", "isBasmala": false, "translation_en": "Do you not see how God presents a parable? A good word is like a good tree-its root is firm, and its branches are in the sky.", "translation_id": "Tidakkah kamu perhatikan bagaimana Allah telah membuat perumpamaan kalimat yang baik seperti pohon yang baik, akarnya teguh dan cabangnya (menjulang) ke langit,", "manzil": 3, "manzil_display": ""}], "259": [{"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 25, "text": "تُؤۡتِیۤ أُكُلَهَا كُلَّ حِینِۭ بِإِذۡنِ رَبِّهَاۗ وَیَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَالَ لِلنَّاسِ لَعَلَّهُمۡ یَتَذَكَّرُونَ ۝٢٥", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "تعطي ثمارها كل وقت بإذن ربها، وكذلك شجرة الإيمان أصلها ثابت في قلب المؤمن علمًا واعتقادًا، وفرعها من الأعمال الصالحة والأخلاق المرضية يُرفع إلى الله وينال ثوابه في كل وقت. ويضرب الله الأمثال للناس؛ ليتذكروا ويتعظوا، فيعتبروا.", "isBasmala": false, "translation_en": "It yields its fruits every season by the will of its Lord. God presents the parables to the people, so that they may reflect.", "translation_id": "pohon itu memberikan buahnya pada setiap musim dengan seizin Tuhannya. Allah membuat perumpamaan-perumpamaan itu untuk manusia supaya mereka selalu ingat.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 26, "text": "وَمَثَلُ كَلِمَةٍ خَبِیثَةࣲ كَشَجَرَةٍ خَبِیثَةٍ ٱجۡتُثَّتۡ مِن فَوۡقِ ٱلۡأَرۡضِ مَا لَهَا مِن قَرَارࣲ ۝٢٦", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "ومثل كلمة خبيثة -وهي كلمة الكفر- كشجرة خبيثة المأكل والمطعم، وهي شجرة الحنظل، اقتلعت من أعلى الأرض؛ لأن عروقها قريبة من سطح الأرض ما لها أصل ثابت، ولا فرع صاعد، وكذلك الكافر لا ثبات له ولا خير فيه، ولا يُرْفَع له عمل صالح إلى الله.", "isBasmala": false, "translation_en": "And the parable of a bad word is that of a bad tree-it is uprooted from the ground; it has no stability.", "translation_id": "Dan perumpamaan kalimat yang buruk seperti pohon yang buruk, yang telah dicabut dengan akar-akarnya dari permukaan bumi; tidak dapat tetap (tegak) sedikitpun.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 27, "text": "یُثَبِّتُ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ بِٱلۡقَوۡلِ ٱلثَّابِتِ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَفِی ٱلۡـَٔاخِرَةِۖ وَیُضِلُّ ٱللَّهُ ٱلظَّـٰلِمِینَۚ وَیَفۡعَلُ ٱللَّهُ مَا یَشَاۤءُ ۝٢٧", "juz": 13, "hizb": "(*½ ح 26*)", "tafsir": "يثبِّت الله الذين آمنوا بالقول الحق الراسخ، وهو شهادة أن لا إله إلا الله وأن محمدًا رسول الله، وما جاء به من الدين الحق يثبتهم الله به في الحياة الدنيا، وعند مماتهم بالخاتمة الحسنة، وفي القبر عند سؤال المَلَكين بهدايتهم إلى الجواب الصحيح، ويضل الله الظالمين عن الصواب في الدنيا والآخرة، ويفعل الله ما يشاء من توفيق أهل الإيمان وخِذْلان أهل الكفر والطغيان.", "isBasmala": false, "translation_en": "God gives firmness to those who believe, with the firm word, in this life, and in the Hereafter. And God leads the wicked astray. God does whatever He wills.", "translation_id": "Allah meneguhkan (iman) orang-orang yang beriman dengan ucapan yang teguh itu dalam kehidupan di dunia dan di akhirat; dan Allah menyesatkan orang-orang yang zalim dan memperbuat apa yang Dia kehendaki.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 28, "text": "۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ بَدَّلُوا۟ نِعۡمَتَ ٱللَّهِ كُفۡرࣰا وَأَحَلُّوا۟ قَوۡمَهُمۡ دَارَ ٱلۡبَوَارِ ۝٢٨", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "ألم تنظر أيها المخاطب -والمراد العموم- إلى حال المكذبين من كفار قريش الذين استبدلوا الكفر بالله بدلا عن شكره على نعمة الأمن بالحرم وبعثة النبي محمد صلى الله عليه وسلم فيهم؟ وقد أنـزلوا أتباعهم دار الهلاك حين تَسببوا بإخراجهم إلى \"بدر\" فقُتِلوا وصار مصيرهم دار البوار، وهي جهنم، يدخلونها ويقاسون حرها، وقَبُحَ المستقر مستقرهم.", "isBasmala": false, "translation_en": "Have you not seen those who exchanged the blessing of God with blasphemy, and landed their people into the house of perdition?", "translation_id": "Tidakkah kamu perhatikan orang-orang yang telah menukar nikmat Allah dengan kekafiran dan menjatuhkan kaumnya ke lembah kebinasaan?,", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 29, "text": "جَهَنَّمَ یَصۡلَوۡنَهَاۖ وَبِئۡسَ ٱلۡقَرَارُ ۝٢٩", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "ألم تنظر أيها المخاطب -والمراد العموم- إلى حال المكذبين من كفار قريش الذين استبدلوا الكفر بالله بدلا عن شكره على نعمة الأمن بالحرم وبعثة النبي محمد صلى الله عليه وسلم فيهم؟ وقد أنـزلوا أتباعهم دار الهلاك حين تَسببوا بإخراجهم إلى \"بدر\" فقُتِلوا وصار مصيرهم دار البوار، وهي جهنم، يدخلونها ويقاسون حرها، وقَبُحَ المستقر مستقرهم.", "isBasmala": false, "translation_en": "Hell-they will roast in it. What a miserable settlement.", "translation_id": "yaitu neraka jahannam; mereka masuk kedalamnya; dan itulah seburuk-buruk tempat kediaman.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 30, "text": "وَجَعَلُوا۟ لِلَّهِ أَندَادࣰا لِّیُضِلُّوا۟ عَن سَبِیلِهِۦۗ قُلۡ تَمَتَّعُوا۟ فَإِنَّ مَصِیرَكُمۡ إِلَى ٱلنَّارِ ۝٣٠", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "وجعل هؤلاء الكفار لله شركاء عبدوهم معه؛ ليُبْعدوا الناس عن دينه. قل لهم -أيها الرسول-: استمتعوا في الحياة الدنيا؛ فإنها سريعة الزوال، وإن مردَّكم ومرجعكم إلى عذاب جهنم.", "isBasmala": false, "translation_en": "And they set up rivals to God, in order to lead away from His path. Say, \"Enjoy yourselves; your destination is the Fire.\"", "translation_id": "Orang-orang kafir itu telah menjadikan sekutu-sekutu bagi Allah supaya mereka menyesatkan (manusia) dari jalan-Nya. Katakanlah: \"Bersenang-senanglah kamu, karena sesungguhnya tempat kembalimu ialah neraka\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 31, "text": "قُل لِّعِبَادِیَ ٱلَّذِینَ ءَامَنُوا۟ یُقِیمُوا۟ ٱلصَّلَوٰةَ وَیُنفِقُوا۟ مِمَّا رَزَقۡنَـٰهُمۡ سِرࣰّا وَعَلَانِیَةࣰ مِّن قَبۡلِ أَن یَأۡتِیَ یَوۡمࣱ لَّا بَیۡعࣱ فِیهِ وَلَا خِلَـٰلٌ ۝٣١", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "قل -أيها الرسول- لعبادي الذين آمنوا: يؤدوا الصلاة بحدودها، ويخرجوا بعض ما أعطيناهم من المال في وجوه الخير الواجبة والمستحبة مسرِّين ذلك ومعلنين، من قبل أن يأتي يوم القيامة الذي لا ينفع فيه فداء ولا صداقة.", "isBasmala": false, "translation_en": "Tell My servants who have believed to perform the prayers, and to give from what We have given them, secretly and publicly, before a Day comes in which there is neither trading nor friendship.", "translation_id": "Katakanlah kepada hamba-hamba-Ku yang telah beriman: \"Hendaklah mereka mendirikan shalat, menafkahkan sebahagian rezeki yang Kami berikan kepada mereka secara sembunyi ataupun terang-terangan sebelum datang hari (kiamat) yang pada bari itu tidak ada jual beli dan persahabatan.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 32, "text": "ٱللَّهُ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَ ٰتِ رِزۡقࣰا لَّكُمۡۖ وَسَخَّرَ لَكُمُ ٱلۡفُلۡكَ لِتَجۡرِیَ فِی ٱلۡبَحۡرِ بِأَمۡرِهِۦۖ وَسَخَّرَ لَكُمُ ٱلۡأَنۡهَـٰرَ ۝٣٢", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "الله تعالى الذي خلق السموات والأرض وأوجدهما من العدم، وأنزل المطر من السحاب فأحيا به الأرض بعد موتها، وأخرج لكم منها أرزاقكم، وذلَّل لكم السفن؛ لتسير في البحر بأمره لمنافعكم، وذلَّل لكم الأنهار لسقياكم وسقيا دوابكم وزروعكم وسائر منافعكم.", "isBasmala": false, "translation_en": "God is He Who created the heavens and the earth, and sends down water from the sky, and with it produces fruits for your sustenance. And He committed the ships to your service, sailing through the sea by His command, and He committed the rivers to your service.", "translation_id": "Allah-lah yang telah menciptakan langit dan bumi dan menurunkan air hujan dari langit, kemudian Dia mengeluarkan dengan air hujan itu berbagai buah-buahan menjadi rezeki untukmu; dan Dia telah menundukkan bahtera bagimu supaya bahtera itu, berlayar di lautan dengan kehendak-Nya, dan Dia telah menundukkan (pula) bagimu sungai-sungai.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 33, "text": "وَسَخَّرَ لَكُمُ ٱلشَّمۡسَ وَٱلۡقَمَرَ دَاۤىِٕبَیۡنِۖ وَسَخَّرَ لَكُمُ ٱلَّیۡلَ وَٱلنَّهَارَ ۝٣٣", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "وذلَّل الله لكم الشمس والقمر لا يَفْتُران عن حركتهما؛ لتتحقق المصالح بهما، وذلَّل لكم الليل؛ لتسكنوا فيه وتستريحوا، والنهار؛ لتبتغوا من فضله، وتدبِّروا معايشكم.", "isBasmala": false, "translation_en": "And He committed the sun and the moon to your service, both continuously pursuing their courses, and He committed the night and the day to your service.", "translation_id": "Dan Dia telah menundukkan (pula) bagimu matahari dan bulan yang terus menerus beredar (dalam orbitnya); dan telah menundukkan bagimu malam dan siang.", "manzil": 3, "manzil_display": ""}], "260": [{"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 34, "text": "وَءَاتَىٰكُم مِّن كُلِّ مَا سَأَلۡتُمُوهُۚ وَإِن تَعُدُّوا۟ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَاۤۗ إِنَّ ٱلۡإِنسَـٰنَ لَظَلُومࣱ كَفَّارࣱ ۝٣٤", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "وأعطاكم من كل ما طلبتموه، وإن تعدُّوا نِعَم الله عليكم لا تطيقوا عدها ولا إحصاءها ولا القيام بشكرها؛ لكثرتها وتنوُّعها. إن الإنسان لَكثير الظلم لنفسه، كثير الجحود لنعم ربه.", "isBasmala": false, "translation_en": "And He has given you something of all what you asked. And if you were to count God's blessings, you would not be able to enumerate them. The human being is unfair and ungrateful.", "translation_id": "Dan Dia telah memberikan kepadamu (keperluanmu) dan segala apa yang kamu mohonkan kepadanya. Dan jika kamu menghitung nikmat Allah, tidaklah dapat kamu menghinggakannya. Sesungguhnya manusia itu, sangat zalim dan sangat mengingkari (nikmat Allah).", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 35, "text": "وَإِذۡ قَالَ إِبۡرَ ٰهِیمُ رَبِّ ٱجۡعَلۡ هَـٰذَا ٱلۡبَلَدَ ءَامِنࣰا وَٱجۡنُبۡنِی وَبَنِیَّ أَن نَّعۡبُدَ ٱلۡأَصۡنَامَ ۝٣٥", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "واذكر -أيها الرسول- حين قال إبراهيم داعيًا ربه -بعد أن أسكن ابنه إسماعيل وأمه \"هاجَر\" وادي \"مكة\" -: رب اجعل \"مكة\" بلدَ أمنٍ يأمن كل مَن فيها، وأبعِدني وأبنائي عن عبادة الأصنام.", "isBasmala": false, "translation_en": "Recall that Abraham said, \"O my Lord, make this land peaceful, and keep me and my sons from worshiping idols.\"", "translation_id": "Dan (ingatlah), ketika Ibrahim berkata: \"Ya Tuhanku, jadikanlah negeri ini (Mekah), negeri yang aman, dan jauhkanlah aku beserta anak cucuku daripada menyembah berhala-berhala.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 36, "text": "رَبِّ إِنَّهُنَّ أَضۡلَلۡنَ كَثِیرࣰا مِّنَ ٱلنَّاسِۖ فَمَن تَبِعَنِی فَإِنَّهُۥ مِنِّیۖ وَمَنۡ عَصَانِی فَإِنَّكَ غَفُورࣱ رَّحِیمࣱ ۝٣٦", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "ربِّ إن الأصنام تسبَّبتْ في إبعاد كثير من الناس عن طريق الحق، فمن اقتدى بي في التوحيد فهو على ديني وسُنَّتي، ومَن خالفني فيما دون الشرك، فإنك غفور لذنوب المذنبين -بفضلك- رحيم بهم، تعفو عمن تشاء منهم.", "isBasmala": false, "translation_en": "\"My Lord, they have led many people astray. Whoever follows me belongs with me; and whoever disobeys me-You are Forgiving and Merciful.", "translation_id": "Ya Tuhanku, sesungguhnya berhala-berhala itu telah menyesatkan kebanyakan daripada manusia, maka barangsiapa yang mengikutiku, maka sesungguhnya orang itu termasuk golonganku, dan barangsiapa yang mendurhakai aku, maka sesungguhnya Engkau, Maha Pengampun lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 37, "text": "رَّبَّنَاۤ إِنِّیۤ أَسۡكَنتُ مِن ذُرِّیَّتِی بِوَادٍ غَیۡرِ ذِی زَرۡعٍ عِندَ بَیۡتِكَ ٱلۡمُحَرَّمِ رَبَّنَا لِیُقِیمُوا۟ ٱلصَّلَوٰةَ فَٱجۡعَلۡ أَفۡـِٔدَةࣰ مِّنَ ٱلنَّاسِ تَهۡوِیۤ إِلَیۡهِمۡ وَٱرۡزُقۡهُم مِّنَ ٱلثَّمَرَ ٰتِ لَعَلَّهُمۡ یَشۡكُرُونَ ۝٣٧", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "ربنا إني أسكنت من ذريتي بوادٍ ليس فيه زرع ولا ماء بجوار بيتك المحرم، ربنا إنني فعلت ذلك بأمرك؛ لكي يؤدوا الصلاة بحدودها، فاجعل قلوب بعض خلقك تَنزع إليهم وتحنُّ، وارزقهم في هذا المكان من أنواع الثمار؛ لكي يشكروا لك على عظيم نعمك. فاستجاب الله دعاءه.", "isBasmala": false, "translation_en": "\"Our Lord, I have settled some of my offspring in a valley of no vegetation, by Your Sacred House, our Lord, so that they may perform the prayers. So make the hearts of some people incline towards them, and provide them with fruits, that they may be thankful.\"", "translation_id": "Ya Tuhan kami, sesungguhnya aku telah menempatkan sebahagian keturunanku di lembah yang tidak mempunyai tanam-tanaman di dekat rumah Engkau (Baitullah) yang dihormati, ya Tuhan kami (yang demikian itu) agar mereka mendirikan shalat, maka jadikanlah hati sebagian manusia cenderung kepada mereka dan beri rezekilah mereka dari buah-buahan, mudah-mudahan mereka bersyukur.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 38, "text": "رَبَّنَاۤ إِنَّكَ تَعۡلَمُ مَا نُخۡفِی وَمَا نُعۡلِنُۗ وَمَا یَخۡفَىٰ عَلَى ٱللَّهِ مِن شَیۡءࣲ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَاۤءِ ۝٣٨", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "ربنا إنك تعلم كل ما نخفيه وما نظهره. وما يغيب عن علم الله شيء من الكائنات في الأرض ولا في السماء.", "isBasmala": false, "translation_en": "\"Our Lord, You know what we conceal and what we reveal. And nothing is hidden from God, on earth or in the heaven.\"", "translation_id": "Ya Tuhan kami, sesungguhnya Engkau mengetahui apa yang kami sembunyikan dan apa yang kami lahirkan; dan tidak ada sesuatupun yang tersembunyi bagi Allah, baik yang ada di bumi maupun yang ada di langit.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 39, "text": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی وَهَبَ لِی عَلَى ٱلۡكِبَرِ إِسۡمَـٰعِیلَ وَإِسۡحَـٰقَۚ إِنَّ رَبِّی لَسَمِیعُ ٱلدُّعَاۤءِ ۝٣٩", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "يُثْني إبراهيم على الله تعالى، فيقول: الحمد لله الذي رزقني على كِبَر سني ولديَّ إسماعيل وإسحاق بعد دعائي أن يهب لي من الصالحين، إن ربي لسميع الدعاء ممن دعاه، وقد دعوته ولم يخيِّب رجائي.", "isBasmala": false, "translation_en": "\"Praise be to God, Who has given me, in my old age, Ishmael and Isaac. My Lord is the Hearer of Prayers.\"", "translation_id": "Segala puji bagi Allah yang telah menganugerahkan kepadaku di hari tua(ku) Ismail dan Ishaq. Sesungguhnya Tuhanku, benar-benar Maha Mendengar (memperkenankan) doa.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 40, "text": "رَبِّ ٱجۡعَلۡنِی مُقِیمَ ٱلصَّلَوٰةِ وَمِن ذُرِّیَّتِیۚ رَبَّنَا وَتَقَبَّلۡ دُعَاۤءِ ۝٤٠", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "رب اجعلني مداومًا على أداء الصلاة على أتم وجوهها، واجعل من ذريتي مَن يحافظ عليها، ربنا واستجب دعائي وتقبَّل عبادتي.", "isBasmala": false, "translation_en": "\"My Lord, make me one who performs the prayer, and from my offspring. Our Lord, accept my supplication.\"", "translation_id": "Ya Tuhanku, jadikanlah aku dan anak cucuku orang-orang yang tetap mendirikan shalat, ya Tuhan kami, perkenankanlah doaku.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 41, "text": "رَبَّنَا ٱغۡفِرۡ لِی وَلِوَ ٰلِدَیَّ وَلِلۡمُؤۡمِنِینَ یَوۡمَ یَقُومُ ٱلۡحِسَابُ ۝٤١", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "ربنا اغفر لي ما وقع مني مما لا يسلم منه البشر واغفر لوالديَّ، (وهذا قبل أن يتبيَّن له أن والده عدو لله) واغفر للمؤمنين جميعًا يوم يقوم الناس للحساب والجزاء.", "isBasmala": false, "translation_en": "\"Our Lord, forgive me, and my parents, and the believers, on the Day the Reckoning takes place.\"", "translation_id": "Ya Tuhan kami, beri ampunlah aku dan kedua ibu bapaku dan sekalian orang-orang mukmin pada hari terjadinya hisab (hari kiamat)\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 42, "text": "وَلَا تَحۡسَبَنَّ ٱللَّهَ غَـٰفِلًا عَمَّا یَعۡمَلُ ٱلظَّـٰلِمُونَۚ إِنَّمَا یُؤَخِّرُهُمۡ لِیَوۡمࣲ تَشۡخَصُ فِیهِ ٱلۡأَبۡصَـٰرُ ۝٤٢", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "ولا تحسبن -أيها الرسول- أن الله غافل عما يعمله الظالمون: من التكذيب بك وبغيرك من الرسل، وإيذاء المؤمنين وغير ذلك من المعاصي، إنما يؤخِّرُ عقابهم ليوم شديد ترتفع فيه عيونهم ولا تَغْمَض؛ مِن هول ما تراه. وفي هذا تسلية لرسول الله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Do not ever think that God is unaware of what the wrongdoers do. He only defers them until a Day when the sights stare.", "translation_id": "Dan janganlah sekali-kali kamu (Muhammad) mengira, bahwa Allah lalai dari apa yang diperbuat oleh orang-orang yang zalim. Sesungguhnya Allah memberi tangguh kepada mereka sampai hari yang pada waktu itu mata (mereka) terbelalak,", "manzil": 3, "manzil_display": ""}], "261": [{"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 43, "text": "مُهۡطِعِینَ مُقۡنِعِی رُءُوسِهِمۡ لَا یَرۡتَدُّ إِلَیۡهِمۡ طَرۡفُهُمۡۖ وَأَفۡـِٔدَتُهُمۡ هَوَاۤءࣱ ۝٤٣", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "يوم يقوم الظالمون من قبورهم مسرعين لإجابة الداعي رافعي رؤوسهم لا يبصرون شيئًا لهول الموقف، وقلوبهم خالية ليس فيها شيء؛ لكثرة الخوف والوجل من هول ما ترى.", "isBasmala": false, "translation_en": "Their necks outstretched, their heads upraised, their gaze unblinking, their hearts void.", "translation_id": "mereka datang bergegas-gegas memenuhi panggilan dengan mangangkat kepalanya, sedang mata mereka tidak berkedip-kedip dan hati mereka kosong.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 44, "text": "وَأَنذِرِ ٱلنَّاسَ یَوۡمَ یَأۡتِیهِمُ ٱلۡعَذَابُ فَیَقُولُ ٱلَّذِینَ ظَلَمُوا۟ رَبَّنَاۤ أَخِّرۡنَاۤ إِلَىٰۤ أَجَلࣲ قَرِیبࣲ نُّجِبۡ دَعۡوَتَكَ وَنَتَّبِعِ ٱلرُّسُلَۗ أَوَ لَمۡ تَكُونُوۤا۟ أَقۡسَمۡتُم مِّن قَبۡلُ مَا لَكُم مِّن زَوَالࣲ ۝٤٤", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "وأنذر -أيها الرسول- الناس الذين أرسلتُكَ إليهم عذاب الله يوم القيامة، وعند ذلك يقول الذين ظلموا أنفسهم بالكفر: ربنا أَمْهِلْنا إلى وقت قريب نؤمن بك ونصدق رسلك. فيقال لهم توبيخًا: ألم تقسموا في حياتكم أنه لا زوال لكم عن الحياة الدنيا إلى الآخرة، فلم تصدِّقوا بهذا البعث؟", "isBasmala": false, "translation_en": "And warn mankind of the Day when the punishment will come upon them, and the wicked will say, \"Our Lord, defer us for a little while, and we will answer Your call and follow the messengers.\" Did you not swear before that there will be no passing away for you?", "translation_id": "Dan berikanlah peringatan kepada manusia terhadap hari (yang pada waktu itu) datang azab kepada mereka, maka berkatalah orang-orang yang zalim: \"Ya Tuhan kami, beri tangguhlah kami (kembalikanlah kami ke dunia) walaupun dalam waktu yang sedikit, niscaya kami akan mematuhi seruan Engkau dan akan mengikuti rasul-rasul\". (Kepada mereka dikatakan): \"Bukankah kamu telah bersumpah dahulu (di dunia) bahwa sekali-kali kamu tidak akan binasa?", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 45, "text": "وَسَكَنتُمۡ فِی مَسَـٰكِنِ ٱلَّذِینَ ظَلَمُوۤا۟ أَنفُسَهُمۡ وَتَبَیَّنَ لَكُمۡ كَیۡفَ فَعَلۡنَا بِهِمۡ وَضَرَبۡنَا لَكُمُ ٱلۡأَمۡثَالَ ۝٤٥", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "وحللتم في مساكن الكافرين السابقين الذين ظلموا أنفسهم كقوم هود وصالح، وعلمتم -بما رأيتم وأُخبرتم- ما أنزلناه بهم من الهلاك، وضربنا لكم الأمثال في القرآن، فلم تعتبروا؟", "isBasmala": false, "translation_en": "And you inhabited the homes of those who wronged themselves, and it became clear to you how We dealt with them, and We cited for you the examples.", "translation_id": "dan kamu telah berdiam di tempat-tempat kediaman orang-orang yang menganiaya diri mereka sendiri, dan telah nyata bagimu bagaimana Kami telah berbuat terhadap mereka dan telah Kami berikan kepadamu beberapa perumpamaan\".", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 46, "text": "وَقَدۡ مَكَرُوا۟ مَكۡرَهُمۡ وَعِندَ ٱللَّهِ مَكۡرُهُمۡ وَإِن كَانَ مَكۡرُهُمۡ لِتَزُولَ مِنۡهُ ٱلۡجِبَالُ ۝٤٦", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "وقد دبَّر المشركون الشرَّ للرسول صلى الله عليه وسلم بقتله، وعند الله مكرهم فهو محيط به، وقد عاد مكرهم عليهم، وما كان مكرهم لتزول منه الجبال ولا غيرها لضعفه ووَهَنه، ولم يضرُّوا الله شيئًا، وإنما ضرُّوا أنفسهم.", "isBasmala": false, "translation_en": "They planned their plans, but their plans are known to God, even if their plans can eliminate mountains.", "translation_id": "Dan sesungguhnya mereka telah membuat makar yang besar padahal di sisi Allah-lah (balasan) makar mereka itu. Dan sesungguhnya makar mereka itu (amat besar) sehingga gunung-gunung dapat lenyap karenanya.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 47, "text": "فَلَا تَحۡسَبَنَّ ٱللَّهَ مُخۡلِفَ وَعۡدِهِۦ رُسُلَهُۥۤۚ إِنَّ ٱللَّهَ عَزِیزࣱ ذُو ٱنتِقَامࣲ ۝٤٧", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "فلا تحسبن -أيها الرسول- أن الله يخلف رسله ما وعدهم به من النصر وإهلاك مكذبيهم. إن الله عزيز لا يمتنع عليه شيء، منتقم من أعدائه أشد انتقام. والخطاب وإن كان خاصًّا بالنبي صلى الله عليه وسلم، فهو موجَّه لعموم الأمة.", "isBasmala": false, "translation_en": "Do not ever think that God will break His promise to His messengers. God is Strong, Able to Avenge.", "translation_id": "Karena itu janganlah sekali-kali kamu mengira Allah akan menyalahi janji-Nya kepada rasul-raaul-Nya; sesungguhnya Allah Maha Perkasa, lagi mempunyai pembalasan.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 48, "text": "یَوۡمَ تُبَدَّلُ ٱلۡأَرۡضُ غَیۡرَ ٱلۡأَرۡضِ وَٱلسَّمَـٰوَ ٰتُۖ وَبَرَزُوا۟ لِلَّهِ ٱلۡوَ ٰحِدِ ٱلۡقَهَّارِ ۝٤٨", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "وانتقام الله تعالى مِن أعدائه في يوم القيامة يوم تُبَدَّل هذه الأرض بأرض أخرى بيضاء نقيَّة كالفضة، وكذلك تُبَدَّل السموات بغيرها، وتخرج الخلائق من قبورها أحياء ظاهرين للقاء الله الواحد القهار، المتفرد بعظمته وأسمائه وصفاته وأفعاله وقهره لكل شيء.", "isBasmala": false, "translation_en": "On the Day when the earth is changed into another earth, and the heavens, and they will emerge before God, the One, the Irresistible.", "translation_id": "(Yaitu) pada hari (ketika) bumi diganti dengan bumi yang lain dan (demikian pula) langit, dan meraka semuanya (di padang Mahsyar) berkumpul menghadap ke hadirat Allah yang Maha Esa lagi Maha Perkasa.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 49, "text": "وَتَرَى ٱلۡمُجۡرِمِینَ یَوۡمَىِٕذࣲ مُّقَرَّنِینَ فِی ٱلۡأَصۡفَادِ ۝٤٩", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "وتُبْصِرُ -أيها الرسول- المجرمين يوم القيامة مقيدين بالقيود، قد قُرِنت أيديهم وأرجلهم بالسلاسل، وهم في ذُلٍّ وهوان.", "isBasmala": false, "translation_en": "On that Day, you will see the sinners bound together in chains.", "translation_id": "Dan kamu akan melihat orang-orang yang berdosa pada hari itu diikat bersama-sama dengan belenggu.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 50, "text": "سَرَابِیلُهُم مِّن قَطِرَانࣲ وَتَغۡشَىٰ وُجُوهَهُمُ ٱلنَّارُ ۝٥٠", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "ثيابهم من القَطِران الشديد الاشتعال، وتلفح وجوههم النار فتحرقها.", "isBasmala": false, "translation_en": "Their garments made of tar, and the Fire covering their faces.", "translation_id": "Pakaian mereka adalah dari pelangkin (ter) dan muka mereka ditutup oleh api neraka,", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 51, "text": "لِیَجۡزِیَ ٱللَّهُ كُلَّ نَفۡسࣲ مَّا كَسَبَتۡۚ إِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ ۝٥١", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "فَعَل الله ذلك بهم؛ جزاء لهم بما كسبوا من الآثام في الدنيا، والله يجازي كل إنسان بما عمل مِن خير أو شر، إن الله سريع الحساب.", "isBasmala": false, "translation_en": "That God may repay each soul according to what it has earned. God is Quick in reckoning.", "translation_id": "agar Allah memberi pembalasan kepada tiap-tiap orang terhadap apa yang ia usahakan. Sesungguhnya Allah Maha cepat hisab-Nya.", "manzil": 3, "manzil_display": ""}, {"sura": 14, "sura_name": "إبراهيم", "revelation": "Makkiyah", "aya": 52, "text": "هَـٰذَا بَلَـٰغࣱ لِّلنَّاسِ وَلِیُنذَرُوا۟ بِهِۦ وَلِیَعۡلَمُوۤا۟ أَنَّمَا هُوَ إِلَـٰهࣱ وَ ٰحِدࣱ وَلِیَذَّكَّرَ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ ۝٥٢", "juz": 13, "hizb": "(*¾ ح 26*)", "tafsir": "هذا القرآن الذي أنزلناه إليك -أيها الرسول- بلاغ وإعلام للناس؛ لنصحهم وتخويفهم، ولكي يوقنوا أن الله هو الإله الواحد، فيعبدوه وحده لا شريك له، وليتعظ به أصحاب العقول السليمة.", "isBasmala": false, "translation_en": "This is a proclamation for mankind, that they may be warned thereby, and know that He is One God, and that people of understanding may remember.", "translation_id": "(Al Quran) ini adalah penjelasan yang sempurna bagi manusia, dan supaya mereka diberi peringatan dengan-Nya, dan supaya mereka mengetahui bahwasanya Dia adalah Tuhan Yang Maha Esa dan agar orang-orang yang berakal mengambil pelajaran.", "manzil": 3, "manzil_display": ""}], "262": [{"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 14, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 1, "text": "۞ الۤرۚ تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ وَقُرۡءَانࣲ مُّبِینࣲ ۝١", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "(الر) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Ra. These are the Verses of the Book; a Quran that makes things clear.", "translation_id": "Alif, laam, raa. (Surat) ini adalah (sebagian dari) ayat-ayat Al-Kitab (yang sempurna), yaitu (ayat-ayat) Al Quran yang memberi penjelasan.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 2, "text": "رُّبَمَا یَوَدُّ ٱلَّذِینَ كَفَرُوا۟ لَوۡ كَانُوا۟ مُسۡلِمِینَ ۝٢", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "سيتمنى الكفار حين يرون خروج عصاة المؤمنين من النار أن لو كانوا موحدين؛ ليخرجوا كما خرجوا.", "isBasmala": false, "translation_en": "Perhaps those who disbelieve would like to become Muslims.", "translation_id": "Orang-orang yang kafir itu seringkali (nanti di akhirat) menginginkan, kiranya mereka dahulu (di dunia) menjadi orang-orang muslim.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 3, "text": "ذَرۡهُمۡ یَأۡكُلُوا۟ وَیَتَمَتَّعُوا۟ وَیُلۡهِهِمُ ٱلۡأَمَلُۖ فَسَوۡفَ یَعۡلَمُونَ ۝٣", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "اترك -أيها الرسول- الكفار يأكلوا، ويستمتعوا بدنياهم، ويشغلهم الطمع فيها عن طاعة الله، فسوف يعلمون عاقبة أمرهم الخاسرة في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Leave them to eat, and enjoy, and be lulled by hope. They will find out.", "translation_id": "Biarkanlah mereka (di dunia ini) makan dan bersenang-senang dan dilalaikan oleh angan-angan (kosong), maka kelak mereka akan mengetahui (akibat perbuatan mereka).", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 4, "text": "وَمَاۤ أَهۡلَكۡنَا مِن قَرۡیَةٍ إِلَّا وَلَهَا كِتَابࣱ مَّعۡلُومࣱ ۝٤", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وإذا طلبوا نزول العذاب بهم تكذيبًا لك -أيها الرسول- فإنا لا نُهْلك قرية إلا ولإهلاكها أجل مقدَّر، لا نُهْلكهم حتى يبلغوه، مثل مَن سبقهم.", "isBasmala": false, "translation_en": "We have never destroyed a town unless it had a set time.", "translation_id": "Dan Kami tiada membinasakan sesuatu negeripun, melainkan ada baginya ketentuan masa yang telah ditetapkan.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 5, "text": "مَّا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا یَسۡتَـٔۡخِرُونَ ۝٥", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "لا تتجاوز أمة أجلها فتزيد عليه، ولا تتقدم عليه، فتنقص منه.", "isBasmala": false, "translation_en": "No nation can bring its time forward, nor can they delay it.", "translation_id": "Tidak ada suatu umatpun yang dapat mendahului ajalnya, dan tidak (pula) dapat mengundurkan(nya).", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 6, "text": "وَقَالُوا۟ یَـٰۤأَیُّهَا ٱلَّذِی نُزِّلَ عَلَیۡهِ ٱلذِّكۡرُ إِنَّكَ لَمَجۡنُونࣱ ۝٦", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وقال المكذبون لمحمد صلى الله عليه وسلم استهزاءً: يا أيها الذي نُزِّل عليه القرآن إنك لذاهب العقل، هلا تأتينا بالملائكة -إن كنت صادقًا-؛ لتشهد أن الله أرسلك.", "isBasmala": false, "translation_en": "And they said, \"O you who received the message, you are insane.\"", "translation_id": "Mereka berkata: \"Hai orang yang diturunkan Al Quran kepadanya, sesungguhnya kamu benar-benar orang yang gila.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 7, "text": "لَّوۡ مَا تَأۡتِینَا بِٱلۡمَلَـٰۤىِٕكَةِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ ۝٧", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وقال المكذبون لمحمد صلى الله عليه وسلم استهزاءً: يا أيها الذي نُزِّل عليه القرآن إنك لذاهب العقل، هلا تأتينا بالملائكة -إن كنت صادقًا-؛ لتشهد أن الله أرسلك.", "isBasmala": false, "translation_en": "Why do you not bring us the angels, if you are truthful?\"", "translation_id": "Mengapa kamu tidak mendatangkan malaikat kepada kami, jika kamu termasuk orang-orang yang benar?\"", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 8, "text": "مَا نُنَزِّلُ ٱلۡمَلَـٰۤىِٕكَةَ إِلَّا بِٱلۡحَقِّ وَمَا كَانُوۤا۟ إِذࣰا مُّنظَرِینَ ۝٨", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وردَّ الله عليهم: إننا لا ننزل الملائكة إلا بالعذاب الذي لا إمهال فيه لمن لم يؤمن، وما كانوا حين تنزل الملائكة بالعذاب بِمُمْهلين.", "isBasmala": false, "translation_en": "We do not send the angels down except with reason, and they will not be held back.", "translation_id": "Kami tidak menurunkan malaikat melainkan dengan benar (untuk membawa azab) dan tiadalah mereka ketika itu diberi tangguh.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 9, "text": "إِنَّا نَحۡنُ نَزَّلۡنَا ٱلذِّكۡرَ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ ۝٩", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "إنَّا نحن نزَّلنا القرآن على النبي محمد صلى الله عليه وسلم، وإنَّا نتعهد بحفظه مِن أن يُزاد فيه أو يُنْقَص منه، أو يضيع منه شيء.", "isBasmala": false, "translation_en": "Surely We revealed the Message, and We will surely preserve it.", "translation_id": "Sesungguhnya Kami-lah yang menurunkan Al Quran, dan sesungguhnya Kami benar-benar memeliharanya.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 10, "text": "وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ فِی شِیَعِ ٱلۡأَوَّلِینَ ۝١٠", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "ولقد أرسلنا من قبلك -أيها الرسول- رسلا في فِرَق الأولين، فما من رسولٍ جاءهم إلا كانوا منه يسخرون. وفي هذا تسلية للرسول صلى الله عليه وسلم. فكما فَعَل بك هؤلاء المشركون فكذلك فُعِلَ بمن قبلك من الرسل.", "isBasmala": false, "translation_en": "We sent others before you, to the former communities.", "translation_id": "Dan sesungguhnya Kami telah mengutus (beberapa rasul) sebelum kamu kepada umat-umat yang terdahulu.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 11, "text": "وَمَا یَأۡتِیهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝١١", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "ولقد أرسلنا من قبلك -أيها الرسول- رسلا في فِرَق الأولين، فما من رسولٍ جاءهم إلا كانوا منه يسخرون. وفي هذا تسلية للرسول صلى الله عليه وسلم. فكما فَعَل بك هؤلاء المشركون فكذلك فُعِلَ بمن قبلك من الرسل.", "isBasmala": false, "translation_en": "But no messenger came to them, but they ridiculed him.", "translation_id": "Dan tidak datang seorang rasulpun kepada mereka, melainkan mereka selalu memperolok-olokkannya.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 12, "text": "كَذَ ٰلِكَ نَسۡلُكُهُۥ فِی قُلُوبِ ٱلۡمُجۡرِمِینَ ۝١٢", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "كما أدخلنا الكفر في قلوب الأمم السابقة بالاستهزاء بالرسل وتكذيبهم، كذلك نفعل ذلك في قلوب مشركي قومك الذين أجرموا بالكفر بالله وتكذيب رسوله، لا يُصَدِّقون بالذكر الذي أُنزل إليك، وقد مضت سنَّة الأولين بإهلاك الكفار، وهؤلاء مِثْلهم، سَيُهْلك المستمرون منهم على الكفر والتكذيب.", "isBasmala": false, "translation_en": "Thus We slip it into the hearts of the guilty.", "translation_id": "Demikianlah, Kami mamasukkan (rasa ingkar dan memperolok-olokkan itu) kedalam hati orang-orang yang berdosa (orang-orang kafir),", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 13, "text": "لَا یُؤۡمِنُونَ بِهِۦ وَقَدۡ خَلَتۡ سُنَّةُ ٱلۡأَوَّلِینَ ۝١٣", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "كما أدخلنا الكفر في قلوب الأمم السابقة بالاستهزاء بالرسل وتكذيبهم، كذلك نفعل ذلك في قلوب مشركي قومك الذين أجرموا بالكفر بالله وتكذيب رسوله، لا يُصَدِّقون بالذكر الذي أُنزل إليك، وقد مضت سنَّة الأولين بإهلاك الكفار، وهؤلاء مِثْلهم، سَيُهْلك المستمرون منهم على الكفر والتكذيب.", "isBasmala": false, "translation_en": "They do not believe in it, though the ways of the ancients have passed away.", "translation_id": "mereka tidak beriman kepadanya (Al Quran) dan sesungguhnya telah berlalu sunnatullah terhadap orang-orang dahulu.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 14, "text": "وَلَوۡ فَتَحۡنَا عَلَیۡهِم بَابࣰا مِّنَ ٱلسَّمَاۤءِ فَظَلُّوا۟ فِیهِ یَعۡرُجُونَ ۝١٤", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "ولو فتحنا على كفار \"مكة\" بابًا من السماء فاستمروا صاعدين فيه حتى يشاهدوا ما في السماء من عجائب ملكوت الله، لما صدَّقوا، ولقالوا: سُحِرَتْ أبصارنا، حتى رأينا ما لم نرَ، وما نحن إلا مسحورون في عقولنا من محمد.", "isBasmala": false, "translation_en": "Even if We opened for them a gateway into the sky, and they began to ascend through it.", "translation_id": "Dan jika seandainya Kami membukakan kepada mereka salah satu dari (pintu-pintu) langit, lalu mereka terus menerus naik ke atasnya,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 15, "text": "لَقَالُوۤا۟ إِنَّمَا سُكِّرَتۡ أَبۡصَـٰرُنَا بَلۡ نَحۡنُ قَوۡمࣱ مَّسۡحُورُونَ ۝١٥", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "ولو فتحنا على كفار \"مكة\" بابًا من السماء فاستمروا صاعدين فيه حتى يشاهدوا ما في السماء من عجائب ملكوت الله، لما صدَّقوا، ولقالوا: سُحِرَتْ أبصارنا، حتى رأينا ما لم نرَ، وما نحن إلا مسحورون في عقولنا من محمد.", "isBasmala": false, "translation_en": "They would still say, \"Our eyes are hallucinating; in fact, we are people bewitched.\"", "translation_id": "tentulah mereka berkata: \"Sesungguhnya pandangan kamilah yang dikaburkan, bahkan kami adalah orang orang yang kena sihir\".", "manzil": 3, "manzil_display": ""}], "263": [{"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 16, "text": "وَلَقَدۡ جَعَلۡنَا فِی ٱلسَّمَاۤءِ بُرُوجࣰا وَزَیَّنَّـٰهَا لِلنَّـٰظِرِینَ ۝١٦", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "ومن أدلة قدرتنا: أنا جعلنا في السماء الدنيا منازل للكواكب تنزل فيها، ويستدل بذلك على الطرقات والأوقات والخِصْب والجَدْب، وزَيَّنَّا هذه السماء بالنجوم لمن ينظرون إليها، ويتأملون فيعتبرون.", "isBasmala": false, "translation_en": "We placed constellations in the sky, and made them beautiful to the beholders.", "translation_id": "Dan sesungguhnya Kami telah menciptakan gugusan bintang-bintang (di langit) dan Kami telah menghiasi langit itu bagi orang-orang yang memandang(nya),", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 17, "text": "وَحَفِظۡنَـٰهَا مِن كُلِّ شَیۡطَـٰنࣲ رَّجِیمٍ ۝١٧", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وحفظنا السماء من كل شيطان مرجوم مطرود من رحمة الله؛ كي لا يصل إليها.", "isBasmala": false, "translation_en": "And We guarded them from every outcast devil.", "translation_id": "dan Kami menjaganya dari tiap-tiap syaitan yang terkutuk,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 18, "text": "إِلَّا مَنِ ٱسۡتَرَقَ ٱلسَّمۡعَ فَأَتۡبَعَهُۥ شِهَابࣱ مُّبِینࣱ ۝١٨", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "إلا من اختلس السمع مِن كلام أهل الملأ الأعلى في بعض الأوقات، فأدركه ولحقه كوكب مضيء يحرقه. وقد يُلْقي الشيطان إلى وليه بعض ما استرقَه قبل أن يحرقه الشهاب.", "isBasmala": false, "translation_en": "Except one who steals a hearing, and is followed by a visible projectile.", "translation_id": "kecuali syaitan yang mencuri-curi (berita) yang dapat didengar (dari malaikat) lalu dia dikejar oleh semburan api yang terang.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 19, "text": "وَٱلۡأَرۡضَ مَدَدۡنَـٰهَا وَأَلۡقَیۡنَا فِیهَا رَوَ ٰسِیَ وَأَنۢبَتۡنَا فِیهَا مِن كُلِّ شَیۡءࣲ مَّوۡزُونࣲ ۝١٩", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "والأرض مددناها متسعة، وألقينا فيها جبالا تثبتها، وأنبتنا فيها من كل أنواع النبات ما هو مقدَّر معلوم مما يحتاج إليه العباد.", "isBasmala": false, "translation_en": "We spread the earth, and placed stabilizers in it, and in it We grew all things in proper measure.", "translation_id": "Dan Kami telah menghamparkan bumi dan menjadikan padanya gunung-gunung dan Kami tumbuhkan padanya segala sesuatu menurut ukuran.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 20, "text": "وَجَعَلۡنَا لَكُمۡ فِیهَا مَعَـٰیِشَ وَمَن لَّسۡتُمۡ لَهُۥ بِرَ ٰزِقِینَ ۝٢٠", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وجعلنا لكم فيها ما به تعيشون من الحَرْث، ومن الماشية، ومن أنواع المكاسب وغيرها، وخلقنا لكم من الذرية والخدم والدوابِّ ما تنتفعون به، وليس رزقهم عليكم، وإنما هو على الله رب العالمين تفضلا منه وتكرمًا.", "isBasmala": false, "translation_en": "And in it We created livelihoods for you, and for those for whom you are not the providers.", "translation_id": "Dan Kami telah menjadikan untukmu di bumi keperluan-keperluan hidup, dan (Kami menciptakan pula) makhluk-makhluk yang kamu sekali-kali bukan pemberi rezeki kepadanya.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 21, "text": "وَإِن مِّن شَیۡءٍ إِلَّا عِندَنَا خَزَاۤىِٕنُهُۥ وَمَا نُنَزِّلُهُۥۤ إِلَّا بِقَدَرࣲ مَّعۡلُومࣲ ۝٢١", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وما من شيء من منافع العباد إلا عندنا خزائنه من جميع الصنوف، وما ننزله إلا بمقدار محدد كما نشاء وكما نريد، فالخزائن بيد الله يعطي من يشاء ويمنع من يشاء، بحسب رحمته الواسعة، وحكمته البالغة.", "isBasmala": false, "translation_en": "There is not a thing but with Us are its stores, and We send it down only in precise measure.", "translation_id": "Dan tidak ada sesuatupun melainkan pada sisi Kami-lah khazanahnya; dan Kami tidak menurunkannya melainkan dengan ukuran yang tertentu.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 22, "text": "وَأَرۡسَلۡنَا ٱلرِّیَـٰحَ لَوَ ٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَسۡقَیۡنَـٰكُمُوهُ وَمَاۤ أَنتُمۡ لَهُۥ بِخَـٰزِنِینَ ۝٢٢", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وأرسلنا الرياح وسخرناها تُلَقِّح السحاب، وتحمل المطر والخير والنفع، فأنزلنا من السحاب ماء أعددناه لشرابكم وأرضكم ومواشيكم، وما أنتم بقادرين على خزنه وادِّخاره، ولكن نخزنه لكم رحمة بكم، وإحسانًا إليكم.", "isBasmala": false, "translation_en": "We send the fertilizing winds; and send down water from the sky, and give it to you to drink, and you are not the ones who store it.", "translation_id": "Dan Kami telah meniupkan angin untuk mengawinkan (tumbuh-tumbuhan) dan Kami turunkan hujan dari langit, lalu Kami beri minum kamu dengan air itu, dan sekali-kali bukanlah kamu yang menyimpannya.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 23, "text": "وَإِنَّا لَنَحۡنُ نُحۡیِۦ وَنُمِیتُ وَنَحۡنُ ٱلۡوَ ٰرِثُونَ ۝٢٣", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وإنَّا لنحن نحيي مَن كان ميتًا بخلقه من العدم، ونميت من كان حيًا بعد انقضاء أجله، ونحن الوارثون الأرض ومَن عليها.", "isBasmala": false, "translation_en": "It is We who give life and cause death, and We are the Inheritors.", "translation_id": "Dan sesungguhnya benar-benar Kami-lah yang menghidupkan dan mematikan dan Kami (pulalah) yang mewarisi.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 24, "text": "وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَقۡدِمِینَ مِنكُمۡ وَلَقَدۡ عَلِمۡنَا ٱلۡمُسۡتَـٔۡخِرِینَ ۝٢٤", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "ولقد علمنا مَن هلك منكم مِن لدن آدم، ومَن هو حيٌّ، ومَن سيأتي إلى يوم القيامة.", "isBasmala": false, "translation_en": "And We know those of you who go forward, and We know those who lag behind.", "translation_id": "Dan sesungguhnya Kami telah mengetahui orang-orang yang terdahulu daripada-mu dan sesungguhnya Kami mengetahui pula orang-orang yang terkemudian (daripadamu).", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 25, "text": "وَإِنَّ رَبَّكَ هُوَ یَحۡشُرُهُمۡۚ إِنَّهُۥ حَكِیمٌ عَلِیمࣱ ۝٢٥", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وإن ربك هو يحشرهم للحساب والجزاء، إنه حكيم في تدبيره، عليم لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "It is your Lord who will gather them together. He is the Wise, the Knowing.", "translation_id": "Sesungguhnya Tuhanmu, Dialah yang akan menghimpunkan mereka. Sesungguhnya Dia adalah Maha Bijaksana lagi Maha Mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 26, "text": "وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ مِن صَلۡصَـٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ ۝٢٦", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "ولقد خلقنا آدم مِن طين يابس إذا نُقِر عليه سُمع له صوت، وهذا الطين اليابس من طين أسود متغيِّر لونه وريحه؛ مِن طول مكثه.", "isBasmala": false, "translation_en": "We created the human being from clay, from molded mud.", "translation_id": "Dan sesungguhnya Kami telah menciptakan manusia (Adam) dari tanah liat kering (yang berasal) dari lumpur hitam yang diberi bentuk.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 27, "text": "وَٱلۡجَاۤنَّ خَلَقۡنَـٰهُ مِن قَبۡلُ مِن نَّارِ ٱلسَّمُومِ ۝٢٧", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وخلقنا أبا الجن، وهو إبليس مِن قَبْل خلق آدم من نار شديدة الحرارة لا دخان لها.", "isBasmala": false, "translation_en": "And the jinn We created before, from piercing fire.", "translation_id": "Dan Kami telah menciptakan jin sebelum (Adam) dari api yang sangat panas.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 28, "text": "وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰۤىِٕكَةِ إِنِّی خَـٰلِقُۢ بَشَرࣰا مِّن صَلۡصَـٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ ۝٢٨", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "واذكر -أيها النبي- حين قال ربك للملائكة: إني خالق إنسانًا من طين يابس، وهذا الطين اليابس من طين أسود متغيِّر اللون.", "isBasmala": false, "translation_en": "Your Lord said to the angels, \"I am creating a human being from clay, from molded mud.\"", "translation_id": "Dan (ingatlah), ketika Tuhanmu berfirman kepada para malaikat: \"Sesungguhnya Aku akan menciptakan seorang manusia dari tanah liat kering (yang berasal) dari lumpur hitam yang diberi bentuk,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 29, "text": "فَإِذَا سَوَّیۡتُهُۥ وَنَفَخۡتُ فِیهِ مِن رُّوحِی فَقَعُوا۟ لَهُۥ سَـٰجِدِینَ ۝٢٩", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "فإذا سوَّيته وأكملت صورته ونفخت فيه الروح، فخُرُّوا له ساجدين سجود تحية وتكريم، لا سجود عبادة.", "isBasmala": false, "translation_en": "\"When I have formed him, and breathed into him of My spirit, fall down prostrating before him.\"", "translation_id": "Maka apabila Aku telah menyempurnakan kejadiannya, dan telah meniup kan kedalamnya ruh (ciptaan)-Ku, maka tunduklah kamu kepadanya dengan bersujud.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 30, "text": "فَسَجَدَ ٱلۡمَلَـٰۤىِٕكَةُ كُلُّهُمۡ أَجۡمَعُونَ ۝٣٠", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "فسجد الملائكة كلهم أجمعون كما أمرهم ربهم لم يمتنع منهم أحد، لكن إبليس امتنع أن يسجد لآدم مع الملائكة الساجدين.", "isBasmala": false, "translation_en": "So the angels prostrated themselves, all together.", "translation_id": "Maka bersujudlah para malaikat itu semuanya bersama-sama,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 31, "text": "إِلَّاۤ إِبۡلِیسَ أَبَىٰۤ أَن یَكُونَ مَعَ ٱلسَّـٰجِدِینَ ۝٣١", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "فسجد الملائكة كلهم أجمعون كما أمرهم ربهم لم يمتنع منهم أحد، لكن إبليس امتنع أن يسجد لآدم مع الملائكة الساجدين.", "isBasmala": false, "translation_en": "Except for Satan. He refused to be among those who prostrated themselves.", "translation_id": "kecuali iblis. Ia enggan ikut besama-sama (malaikat) yang sujud itu.", "manzil": 3, "manzil_display": ""}], "264": [{"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 32, "text": "قَالَ یَـٰۤإِبۡلِیسُ مَا لَكَ أَلَّا تَكُونَ مَعَ ٱلسَّـٰجِدِینَ ۝٣٢", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال الله لإبليس: ما لك ألا تسجد مع الملائكة؟", "isBasmala": false, "translation_en": "He said, \"O Satan, what kept you from being among those who prostrated themselves?\"", "translation_id": "Allah berfirman: \"Hai iblis, apa sebabnya kamu tidak (ikut sujud) bersama-sama mereka yang sujud itu?\"", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 33, "text": "قَالَ لَمۡ أَكُن لِّأَسۡجُدَ لِبَشَرٍ خَلَقۡتَهُۥ مِن صَلۡصَـٰلࣲ مِّنۡ حَمَإࣲ مَّسۡنُونࣲ ۝٣٣", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال إبليس مظهرًا كبره وحسده: لا يليق بي أن أسجد لإنسان أَوجدْتَهُ من طين يابس كان طينًا أسود متغيرًا.", "isBasmala": false, "translation_en": "He said, \"I am not about to prostrate myself before a human being, whom You created from clay, from molded mud.\"", "translation_id": "Berkata Iblis: \"Aku sekali-kali tidak akan sujud kepada manusia yang Engkau telah menciptakannya dari tanah liat kering (yang berasal) dari lumpur hitam yang diberi bentuk\"", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 34, "text": "قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِیمࣱ ۝٣٤", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال الله تعالى له: فاخرج من الجنة، فإنك مطرود من كل خير، وإن عليك اللعنة والبعد من رحمتي إلى يوم يُبْعَث الناس للحساب والجزاء.", "isBasmala": false, "translation_en": "He said, \"Then get out of here, for you are an outcast\".", "translation_id": "Allah berfirman: \"Keluarlah dari surga, karena sesungguhnya kamu terkutuk,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 35, "text": "وَإِنَّ عَلَیۡكَ ٱللَّعۡنَةَ إِلَىٰ یَوۡمِ ٱلدِّینِ ۝٣٥", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال الله تعالى له: فاخرج من الجنة، فإنك مطرود من كل خير، وإن عليك اللعنة والبعد من رحمتي إلى يوم يُبْعَث الناس للحساب والجزاء.", "isBasmala": false, "translation_en": "\"And the curse will be upon you until the Day of Judgment.\"", "translation_id": "dan sesungguhnya kutukan itu tetap menimpamu sampai hari kiamat\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 36, "text": "قَالَ رَبِّ فَأَنظِرۡنِیۤ إِلَىٰ یَوۡمِ یُبۡعَثُونَ ۝٣٦", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال إبليس: رب أخِّرني في الدنيا إلى اليوم الذي تَبْعَث فيه عبادك، وهو يوم القيامة.", "isBasmala": false, "translation_en": "He said, \"My Lord, reprieve me until the Day they are resurrected.\"", "translation_id": "Berkata iblis: \"Ya Tuhanku, (kalau begitu) maka beri tangguhlah kepadaku sampai hari (manusia) dibangkitkan,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 37, "text": "قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِینَ ۝٣٧", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال الله له: فإنك ممن أخَّرْتُ هلاكهم إلى اليوم الذي يموت فيه كل الخلق بعد النفخة الأولى، لا إلى يوم البعث، وإنما أُجيبَ إلى ذلك استدراجًا له وإمهالا وفتنة للثقلين.", "isBasmala": false, "translation_en": "He said, \"You are of those reprieved.\"", "translation_id": "Allah berfirman: \"(Kalau begitu) maka sesungguhnya kamu termasuk orang-orang yang diberi tangguh,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 38, "text": "إِلَىٰ یَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ ۝٣٨", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال الله له: فإنك ممن أخَّرْتُ هلاكهم إلى اليوم الذي يموت فيه كل الخلق بعد النفخة الأولى، لا إلى يوم البعث، وإنما أُجيبَ إلى ذلك استدراجًا له وإمهالا وفتنة للثقلين.", "isBasmala": false, "translation_en": "\"Until the Day of the time appointed.\"", "translation_id": "sampai hari (suatu) waktu yang telah ditentukan,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 39, "text": "قَالَ رَبِّ بِمَاۤ أَغۡوَیۡتَنِی لَأُزَیِّنَنَّ لَهُمۡ فِی ٱلۡأَرۡضِ وَلَأُغۡوِیَنَّهُمۡ أَجۡمَعِینَ ۝٣٩", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال إبليس: ربِّ بسبب ما أغويتني وأضللتني لأحسِّنَنَّ لذرية آدم معاصيك في الأرض، ولأضلنهم أجمعين عن طريق الهدى، إلا عبادك الذين هديتهم فأخلصوا لك العبادة وحدك دون سائر خلقك.", "isBasmala": false, "translation_en": "He said, \"My Lord, since You have lured me away, I will glamorize for them on earth, and I will lure them all away.\"", "translation_id": "Iblis berkata: \"Ya Tuhanku, oleh sebab Engkau telah memutuskan bahwa aku sesat, pasti aku akan menjadikan mereka memandang baik (perbuatan maksiat) di muka bumi, dan pasti aku akan menyesatkan mereka semuanya,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 40, "text": "إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِینَ ۝٤٠", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال إبليس: ربِّ بسبب ما أغويتني وأضللتني لأحسِّنَنَّ لذرية آدم معاصيك في الأرض، ولأضلنهم أجمعين عن طريق الهدى، إلا عبادك الذين هديتهم فأخلصوا لك العبادة وحدك دون سائر خلقك.", "isBasmala": false, "translation_en": "\"Except for Your sincere servants among them.\"", "translation_id": "kecuali hamba-hamba Engkau yang mukhlis di antara mereka\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 41, "text": "قَالَ هَـٰذَا صِرَ ٰطٌ عَلَیَّ مُسۡتَقِیمٌ ۝٤١", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال الله: هذا طريق مستقيم معتدل موصل إليَّ وإلى دار كرامتي. إن عبادي الذين أخلصوا لي لا أجعل لك سلطانًا على قلوبهم تضلُّهم به عن الصراط المستقيم، لكن سلطانك على مَنِ اتبعك مِنَ الضالين المشركين الذين رضوا بولايتك وطاعتك بدلا من طاعتي.", "isBasmala": false, "translation_en": "He said, \"This is a right way with Me.\"", "translation_id": "Allah berfirman: \"Ini adalah jalan yang lurus, kewajiban Aku-lah (menjaganya).", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 42, "text": "إِنَّ عِبَادِی لَیۡسَ لَكَ عَلَیۡهِمۡ سُلۡطَـٰنٌ إِلَّا مَنِ ٱتَّبَعَكَ مِنَ ٱلۡغَاوِینَ ۝٤٢", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "قال الله: هذا طريق مستقيم معتدل موصل إليَّ وإلى دار كرامتي. إن عبادي الذين أخلصوا لي لا أجعل لك سلطانًا على قلوبهم تضلُّهم به عن الصراط المستقيم، لكن سلطانك على مَنِ اتبعك مِنَ الضالين المشركين الذين رضوا بولايتك وطاعتك بدلا من طاعتي.", "isBasmala": false, "translation_en": "\"Over My servants you have no authority, except for the sinners who follow you.\"", "translation_id": "Sesungguhnya hamba-hamba-Ku tidak ada kekuasaan bagimu terhadap mereka, kecuali orang-orang yang mengikut kamu, yaitu orang-orang yang sesat.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 43, "text": "وَإِنَّ جَهَنَّمَ لَمَوۡعِدُهُمۡ أَجۡمَعِینَ ۝٤٣", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وإن النار الشديدة لَموعدُ إبليس وأتباعه أجمعين، لها سبعة أبواب كل باب أسفل من الآخر، لكل بابٍ مِن أتباع إبليس قسم ونصيب بحسب أعمالهم.", "isBasmala": false, "translation_en": "And Hell is the meeting-place for them all.", "translation_id": "Dan sesungguhnya Jahannam itu benar-benar tempat yang telah diancamkan kepada mereka (pengikut-pengikut syaitan) semuanya.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 44, "text": "لَهَا سَبۡعَةُ أَبۡوَ ٰبࣲ لِّكُلِّ بَابࣲ مِّنۡهُمۡ جُزۡءࣱ مَّقۡسُومٌ ۝٤٤", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "وإن النار الشديدة لَموعدُ إبليس وأتباعه أجمعين، لها سبعة أبواب كل باب أسفل من الآخر، لكل بابٍ مِن أتباع إبليس قسم ونصيب بحسب أعمالهم.", "isBasmala": false, "translation_en": "\"It has seven doors; for each door is an assigned class.\"", "translation_id": "Jahannam itu mempunyai tujuh pintu. Tiap-tiap pintu (telah ditetapkan) untuk golongan yang tertentu dari mereka.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 45, "text": "إِنَّ ٱلۡمُتَّقِینَ فِی جَنَّـٰتࣲ وَعُیُونٍ ۝٤٥", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "إن الذين اتقوا الله بامتثال ما أمر واجتناب ما نهى في بساتين وأنهار جارية يقال لهم: ادخلوا هذه الجنات سالمين من كل سوء آمنين من كل عذاب. ونزعنا ما في قلوبهم من حقد وعداوة، يعيشون في الجنة إخوانًا متحابين، يجلسون على أسرَّة عظيمة، تتقابل وجوههم تواصلا وتحاببًا، لا يصيبهم فيها تعب ولا إعياء، وهم باقون فيها أبدًا.", "isBasmala": false, "translation_en": "But the righteous will be in gardens with springs.", "translation_id": "Sesungguhnya orang-orang yang bertakwa itu berada dalam surga (taman-taman) dan (di dekat) mata air-mata air (yang mengalir).", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 46, "text": "ٱدۡخُلُوهَا بِسَلَـٰمٍ ءَامِنِینَ ۝٤٦", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "إن الذين اتقوا الله بامتثال ما أمر واجتناب ما نهى في بساتين وأنهار جارية يقال لهم: ادخلوا هذه الجنات سالمين من كل سوء آمنين من كل عذاب. ونزعنا ما في قلوبهم من حقد وعداوة، يعيشون في الجنة إخوانًا متحابين، يجلسون على أسرَّة عظيمة، تتقابل وجوههم تواصلا وتحاببًا، لا يصيبهم فيها تعب ولا إعياء، وهم باقون فيها أبدًا.", "isBasmala": false, "translation_en": "\"Enter it in peace and security.\"", "translation_id": "(Dikatakan kepada mereka): \"Masuklah ke dalamnya dengan sejahtera lagi aman\"", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 47, "text": "وَنَزَعۡنَا مَا فِی صُدُورِهِم مِّنۡ غِلٍّ إِخۡوَ ٰنًا عَلَىٰ سُرُرࣲ مُّتَقَـٰبِلِینَ ۝٤٧", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "إن الذين اتقوا الله بامتثال ما أمر واجتناب ما نهى في بساتين وأنهار جارية يقال لهم: ادخلوا هذه الجنات سالمين من كل سوء آمنين من كل عذاب. ونزعنا ما في قلوبهم من حقد وعداوة، يعيشون في الجنة إخوانًا متحابين، يجلسون على أسرَّة عظيمة، تتقابل وجوههم تواصلا وتحاببًا، لا يصيبهم فيها تعب ولا إعياء، وهم باقون فيها أبدًا.", "isBasmala": false, "translation_en": "And We will remove all ill-feelings from their hearts-brothers and sisters, on couches facing one another.", "translation_id": "Dan Kami lenyapkan segala rasa dendam yang berada dalam hati mereka, sedang mereka merasa bersaudara duduk berhadap-hadapan di atas dipan-dipan.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 48, "text": "لَا یَمَسُّهُمۡ فِیهَا نَصَبࣱ وَمَا هُم مِّنۡهَا بِمُخۡرَجِینَ ۝٤٨", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "إن الذين اتقوا الله بامتثال ما أمر واجتناب ما نهى في بساتين وأنهار جارية يقال لهم: ادخلوا هذه الجنات سالمين من كل سوء آمنين من كل عذاب. ونزعنا ما في قلوبهم من حقد وعداوة، يعيشون في الجنة إخوانًا متحابين، يجلسون على أسرَّة عظيمة، تتقابل وجوههم تواصلا وتحاببًا، لا يصيبهم فيها تعب ولا إعياء، وهم باقون فيها أبدًا.", "isBasmala": false, "translation_en": "No fatigue will ever touch them therein, nor will they be asked to leave it.", "translation_id": "Mereka tidak merasa lelah di dalamnya dan mereka sekali-kali tidak akan dikeluarkan daripadanya.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 49, "text": "۞ نَبِّئۡ عِبَادِیۤ أَنِّیۤ أَنَا ٱلۡغَفُورُ ٱلرَّحِیمُ ۝٤٩", "juz": 14, "hizb": "(* ح 27*)", "tafsir": "أخبر -أيها الرسول- عبادي أني أنا الغفور للمؤمنين التائبين، الرحيم بهم، وأن عذابي هو العذاب المؤلم الموجع لغير التائبين. وأخبرهم -أيها الرسول- عن ضيوف إبراهيم من الملائكة الذين بشَّروه بالولد، وبهلاك قوم لوط.", "isBasmala": false, "translation_en": "Inform My servants that I am the Forgiver, the Merciful.", "translation_id": "Kabarkanlah kepada hamba-hamba-Ku, bahwa sesungguhnya Aku-lah Yang Maha Pengampun lagi Maha Penyayang,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 50, "text": "وَأَنَّ عَذَابِی هُوَ ٱلۡعَذَابُ ٱلۡأَلِیمُ ۝٥٠", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "أخبر -أيها الرسول- عبادي أني أنا الغفور للمؤمنين التائبين، الرحيم بهم، وأن عذابي هو العذاب المؤلم الموجع لغير التائبين. وأخبرهم -أيها الرسول- عن ضيوف إبراهيم من الملائكة الذين بشَّروه بالولد، وبهلاك قوم لوط.", "isBasmala": false, "translation_en": "And that My punishment is the painful punishment.", "translation_id": "dan bahwa sesungguhnya azab-Ku adalah azab yang sangat pedih.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 51, "text": "وَنَبِّئۡهُمۡ عَن ضَیۡفِ إِبۡرَ ٰهِیمَ ۝٥١", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "أخبر -أيها الرسول- عبادي أني أنا الغفور للمؤمنين التائبين، الرحيم بهم، وأن عذابي هو العذاب المؤلم الموجع لغير التائبين. وأخبرهم -أيها الرسول- عن ضيوف إبراهيم من الملائكة الذين بشَّروه بالولد، وبهلاك قوم لوط.", "isBasmala": false, "translation_en": "And inform them of the guests of Abraham.", "translation_id": "Dan kabarkanlah kepada mereka tentang tamu-tamu Ibrahim.", "manzil": 3, "manzil_display": ""}], "265": [{"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 52, "text": "إِذۡ دَخَلُوا۟ عَلَیۡهِ فَقَالُوا۟ سَلَـٰمࣰا قَالَ إِنَّا مِنكُمۡ وَجِلُونَ ۝٥٢", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "حين دخلوا عليه فقالوا: سلامًا؛ فرد عليهم السلام، ثم قدَّم لهم الطعام فلم يأكلوا، قال: إنا منكم فزعون.", "isBasmala": false, "translation_en": "When they entered upon him, and said, \"Peace.\" He said, \"We are wary of you.\"", "translation_id": "Ketika mereka masuk ke tempatnya, lalu mereka mengucapkan: \"Salaam\". Berkata Ibrahim: \"Sesungguhnya kami merasa takut kepadamu\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 53, "text": "قَالُوا۟ لَا تَوۡجَلۡ إِنَّا نُبَشِّرُكَ بِغُلَـٰمٍ عَلِیمࣲ ۝٥٣", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قالت الملائكة له: لا تفزع إنَّا جئنا نبشرك بولد كثير العلم بالدين، هو إسحاق.", "isBasmala": false, "translation_en": "They said, \"Do not fear; we bring you good news of a boy endowed with knowledge.\"", "translation_id": "Mereka berkata: \"Janganlah kamu merasa takut, sesungguhnya kami memberi kabar gembira kepadamu dengan (kelahiran seorang) anak laki-laki (yang akan menjadi) orang yang alim\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 54, "text": "قَالَ أَبَشَّرۡتُمُونِی عَلَىٰۤ أَن مَّسَّنِیَ ٱلۡكِبَرُ فَبِمَ تُبَشِّرُونَ ۝٥٤", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قال إبراهيم متعجبًا: أبشَّرتموني بالولد، وأنا كبير وزوجتي كذلك، فبأي أعجوبة تبشِّرونني؟", "isBasmala": false, "translation_en": "He said, \"Do you bring me good news, when old age has overtaken me? What good news do you bring?\"", "translation_id": "Berkata Ibrahim: \"Apakah kamu memberi kabar gembira kepadaku padahal usiaku telah lanjut, maka dengan cara bagaimanakah (terlaksananya) berita gembira yang kamu kabarkan ini?\"", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 55, "text": "قَالُوا۟ بَشَّرۡنَـٰكَ بِٱلۡحَقِّ فَلَا تَكُن مِّنَ ٱلۡقَـٰنِطِینَ ۝٥٥", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قالوا: بشَّرناك بالحق الذي أعلمَنا به الله، فلا تكن من اليائسين أن يولد لك.", "isBasmala": false, "translation_en": "They said, \"We bring you good news in truth, so do not despair.\"", "translation_id": "Mereka menjawab: \"Kami menyampaikan kabar gembira kepadamu dengan benar, maka janganlah kamu termasuk orang-orang yang berputus asa\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 56, "text": "قَالَ وَمَن یَقۡنَطُ مِن رَّحۡمَةِ رَبِّهِۦۤ إِلَّا ٱلضَّاۤلُّونَ ۝٥٦", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قال: لا ييئس من رحمة ربه إلا الخاطئون المنصرفون عن طريق الحق. قال: فما الأمر الخطير الذي جئتم من أجله -أيها المرسلون- من عند الله؟", "isBasmala": false, "translation_en": "He said, \"And who despairs of his Lord's mercy but the lost?\"", "translation_id": "Ibrahim berkata: \"Tidak ada orang yang berputus asa dari rahmat Tuhan-nya, kecuali orang-orang yang sesat\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 57, "text": "قَالَ فَمَا خَطۡبُكُمۡ أَیُّهَا ٱلۡمُرۡسَلُونَ ۝٥٧", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قال: لا ييئس من رحمة ربه إلا الخاطئون المنصرفون عن طريق الحق. قال: فما الأمر الخطير الذي جئتم من أجله -أيها المرسلون- من عند الله؟", "isBasmala": false, "translation_en": "He said, \"So what is your business, O envoys?\"", "translation_id": "Berkata (pula) Ibrahim: \"Apakah urusanmu yang penting (selain itu), hai para utusan?\"", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 58, "text": "قَالُوۤا۟ إِنَّاۤ أُرۡسِلۡنَاۤ إِلَىٰ قَوۡمࣲ مُّجۡرِمِینَ ۝٥٨", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قالوا: إن الله أرسلنا لإهلاك قوم لوط المشركين الضالين إلا لوطًا وأهله المؤمنين به، فلن نهلكهم وسننجيهم أجمعين، لكن زوجته الكافرة قضينا بأمر الله بإهلاكها مع الباقين في العذاب.", "isBasmala": false, "translation_en": "They said, \"We were sent to a sinful people.\"", "translation_id": "Mereka menjawab: \"Kami sesungguhnya diutus kepada kaum yang berdosa,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 59, "text": "إِلَّاۤ ءَالَ لُوطٍ إِنَّا لَمُنَجُّوهُمۡ أَجۡمَعِینَ ۝٥٩", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قالوا: إن الله أرسلنا لإهلاك قوم لوط المشركين الضالين إلا لوطًا وأهله المؤمنين به، فلن نهلكهم وسننجيهم أجمعين، لكن زوجته الكافرة قضينا بأمر الله بإهلاكها مع الباقين في العذاب.", "isBasmala": false, "translation_en": "\"Except for the family of Lot; we will save them all.\"", "translation_id": "kecuali Luth beserta pengikut-pengikutnya. Sesungguhnya Kami akan menyelamatkan mereka semuanya,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 60, "text": "إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَاۤ إِنَّهَا لَمِنَ ٱلۡغَـٰبِرِینَ ۝٦٠", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قالوا: إن الله أرسلنا لإهلاك قوم لوط المشركين الضالين إلا لوطًا وأهله المؤمنين به، فلن نهلكهم وسننجيهم أجمعين، لكن زوجته الكافرة قضينا بأمر الله بإهلاكها مع الباقين في العذاب.", "isBasmala": false, "translation_en": "\"Except for his wife.\" We have determined that she will be of those who lag behind.", "translation_id": "kecuali istrinya. Kami telah menentukan, bahwa sesungguhnya ia itu termasuk orang-orang yang tertinggal (bersama-sama dengan orang kafir lainnya)\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 61, "text": "فَلَمَّا جَاۤءَ ءَالَ لُوطٍ ٱلۡمُرۡسَلُونَ ۝٦١", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "فلما وصل الملائكة المرسلون إلى لوط، قال لهم: إنكم قوم غير معروفين لي.", "isBasmala": false, "translation_en": "And when the envoys came to the family of Lot.", "translation_id": "Maka tatkala para utusan itu datang kepada kaum Luth, beserta pengikut pengikutnya,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 62, "text": "قَالَ إِنَّكُمۡ قَوۡمࣱ مُّنكَرُونَ ۝٦٢", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "فلما وصل الملائكة المرسلون إلى لوط، قال لهم: إنكم قوم غير معروفين لي.", "isBasmala": false, "translation_en": "He said, \"You are a people unknown to me.\"", "translation_id": "ia berkata: \"Sesungguhnya kamu adalah orang-orang yang tidak dikenal\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 63, "text": "قَالُوا۟ بَلۡ جِئۡنَـٰكَ بِمَا كَانُوا۟ فِیهِ یَمۡتَرُونَ ۝٦٣", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قالوا: لا تَخَفْ، فإنَّا جئنا بالعذاب الذي كان يشك فيه قومك ولا يُصَدِّقون، وجئناك بالحق من عند الله، وإنا لصادقون، فاخرج مِن بينهم ومعك أهلك المؤمنون، بعد مرور جزء من الليل، وسر أنت وراءهم؛ لئلا يتخلف منهم أحد فيناله العذاب، واحذروا أن يلتفت منكم أحد، وأسرعوا إلى حيث أمركم الله؛ لتكونوا في مكان أمين.", "isBasmala": false, "translation_en": "They said, \"We bring you what they have doubts about.\"", "translation_id": "Para utusan menjawab: \"Sebenarnya kami ini datang kepadamu dengan membawa azab yang selalu mereka dustakan.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 64, "text": "وَأَتَیۡنَـٰكَ بِٱلۡحَقِّ وَإِنَّا لَصَـٰدِقُونَ ۝٦٤", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قالوا: لا تَخَفْ، فإنَّا جئنا بالعذاب الذي كان يشك فيه قومك ولا يُصَدِّقون، وجئناك بالحق من عند الله، وإنا لصادقون، فاخرج مِن بينهم ومعك أهلك المؤمنون، بعد مرور جزء من الليل، وسر أنت وراءهم؛ لئلا يتخلف منهم أحد فيناله العذاب، واحذروا أن يلتفت منكم أحد، وأسرعوا إلى حيث أمركم الله؛ لتكونوا في مكان أمين.", "isBasmala": false, "translation_en": "\"We bring you the truth, and we are truthful.\"", "translation_id": "Dan kami datang kepadamu membawa kebenaran dan sesungguhnya kami betul-betul orang-orang benar.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 65, "text": "فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعࣲ مِّنَ ٱلَّیۡلِ وَٱتَّبِعۡ أَدۡبَـٰرَهُمۡ وَلَا یَلۡتَفِتۡ مِنكُمۡ أَحَدࣱ وَٱمۡضُوا۟ حَیۡثُ تُؤۡمَرُونَ ۝٦٥", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قالوا: لا تَخَفْ، فإنَّا جئنا بالعذاب الذي كان يشك فيه قومك ولا يُصَدِّقون، وجئناك بالحق من عند الله، وإنا لصادقون، فاخرج مِن بينهم ومعك أهلك المؤمنون، بعد مرور جزء من الليل، وسر أنت وراءهم؛ لئلا يتخلف منهم أحد فيناله العذاب، واحذروا أن يلتفت منكم أحد، وأسرعوا إلى حيث أمركم الله؛ لتكونوا في مكان أمين.", "isBasmala": false, "translation_en": "\"Travel with your family at the dead of the night, and follow up behind them, and let none of you look back, and proceed as commanded.\"", "translation_id": "Maka pergilah kamu di akhir malam dengan membawa keluargamu, dan ikutlah mereka dari belakang dan janganlah seorangpun di antara kamu menoleh kebelakang dan teruskanlah perjalanan ke tempat yang di perintahkan kepadamu\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 66, "text": "وَقَضَیۡنَاۤ إِلَیۡهِ ذَ ٰلِكَ ٱلۡأَمۡرَ أَنَّ دَابِرَ هَـٰۤؤُلَاۤءِ مَقۡطُوعࣱ مُّصۡبِحِینَ ۝٦٦", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وأوحينا إلى لوط أن قومك مستأصَلون بالهلاك عن آخرهم عند طلوع الصبح.", "isBasmala": false, "translation_en": "And We informed him of Our decree: the last remnant of these will be uprooted by early morning.", "translation_id": "Dan telah Kami wahyukan kepadanya (Luth) perkara itu, yaitu bahwa mereka akan ditumpas habis di waktu subuh.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 67, "text": "وَجَاۤءَ أَهۡلُ ٱلۡمَدِینَةِ یَسۡتَبۡشِرُونَ ۝٦٧", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وجاء أهل مدينة لوط إلى لوط حين علموا بمن عنده من الضيوف، وهم فرحون يستبشرون بضيوفه؛ ليأخذوهم ويفعلوا بهم الفاحشة.", "isBasmala": false, "translation_en": "And the people of the town came joyfully.", "translation_id": "Dan datanglah penduduk kota itu (ke rumah Luth) dengan gembira (karena) kedatangan tamu-tamu itu.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 68, "text": "قَالَ إِنَّ هَـٰۤؤُلَاۤءِ ضَیۡفِی فَلَا تَفۡضَحُونِ ۝٦٨", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قال لهم لوط: إن هؤلاء ضيفي وهم في حمايتي فلا تفضحوني، وخافوا عقاب الله، ولا تتعرضوا لهم، فتوقعوني في الذل والهوان بإيذائكم لضيوفي.", "isBasmala": false, "translation_en": "He said, \"These are my guests, so do not embarrass me.\"", "translation_id": "Luth berkata: \"Sesungguhnya mereka adalah tamuku; maka janganlah kamu memberi malu (kepadaku),", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 69, "text": "وَٱتَّقُوا۟ ٱللَّهَ وَلَا تُخۡزُونِ ۝٦٩", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قال لهم لوط: إن هؤلاء ضيفي وهم في حمايتي فلا تفضحوني، وخافوا عقاب الله، ولا تتعرضوا لهم، فتوقعوني في الذل والهوان بإيذائكم لضيوفي.", "isBasmala": false, "translation_en": "\"And fear God, and do not disgrace me.\"", "translation_id": "dan bertakwalah kepada Allah dan janganlah kamu membuat aku terhina\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 70, "text": "قَالُوۤا۟ أَوَ لَمۡ نَنۡهَكَ عَنِ ٱلۡعَـٰلَمِینَ ۝٧٠", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قال قومه: أولم نَنْهَكَ أن تضيِّف أحدا من العالمين؛ لأنَّا نريد منهم الفاحشة؟", "isBasmala": false, "translation_en": "They said, \"Did we not forbid you from strangers?\"", "translation_id": "Mereka berkata: \"Dan bukankah kami telah melarangmu dari (melindungi) manusia?\"", "manzil": 3, "manzil_display": ""}], "266": [{"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 71, "text": "قَالَ هَـٰۤؤُلَاۤءِ بَنَاتِیۤ إِن كُنتُمۡ فَـٰعِلِینَ ۝٧١", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "قال لوط لهم: هؤلاء نساؤكم بناتي فتزوَّجوهن إن كنتم تريدون قضاء وطركم، وسماهن بناته؛ لأن نبي الأمة بمنزلة الأب لهم، ولا تفعلوا ما حرَّم الله عليكم من إتيان الرجال.", "isBasmala": false, "translation_en": "He said, \"These are my daughters, if you must.\"", "translation_id": "Luth berkata: \"Inilah puteri-puteriku (kawinlah dengan mereka), jika kamu hendak berbuat (secara yang halal)\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 72, "text": "لَعَمۡرُكَ إِنَّهُمۡ لَفِی سَكۡرَتِهِمۡ یَعۡمَهُونَ ۝٧٢", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "يقسم الخالق بمن يشاء وبما يشاء، أما المخلوق فلا يجوز له القسم إلا بالله، وقد أقسم الله تعالى بحياة محمد صلى الله عليه وسلم تشريفًا له. إن قوم لوط في غفلة شديدة يترددون ويتمادون، حتى حلَّتْ بهم صاعقة العذاب وقت شروق الشمس.", "isBasmala": false, "translation_en": "By your life, they were blundering in their drunkenness.", "translation_id": "(Allah berfirman): \"Demi umurmu (Muhammad), sesungguhnya mereka terombang-ambing di dalam kemabukan (kesesatan)\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 73, "text": "فَأَخَذَتۡهُمُ ٱلصَّیۡحَةُ مُشۡرِقِینَ ۝٧٣", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "يقسم الخالق بمن يشاء وبما يشاء، أما المخلوق فلا يجوز له القسم إلا بالله، وقد أقسم الله تعالى بحياة محمد صلى الله عليه وسلم تشريفًا له. إن قوم لوط في غفلة شديدة يترددون ويتمادون، حتى حلَّتْ بهم صاعقة العذاب وقت شروق الشمس.", "isBasmala": false, "translation_en": "So the Blast struck them at sunrise.", "translation_id": "Maka mereka dibinasakan oleh suara keras yang mengguntur, ketika matahari akan terbit.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 74, "text": "فَجَعَلۡنَا عَـٰلِیَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَیۡهِمۡ حِجَارَةࣰ مِّن سِجِّیلٍ ۝٧٤", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "فقلبنا قُراهم فجعلنا عاليها سافلها، وأمطرنا عليهم حجارة من طين متصلب متين.", "isBasmala": false, "translation_en": "And We turned it upside down, and rained down upon them stones of baked clay.", "translation_id": "Maka Kami jadikan bahagian atas kota itu terbalik ke bawah dan Kami hujani mereka dengan batu dari tanah yang keras.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 75, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّلۡمُتَوَسِّمِینَ ۝٧٥", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "إن فيما أصابهم لَعظاتٍ للناظرين المعتبرين، وإن قراهم لفي طريق ثابت يراها المسافرون المارُّون بها. إن في إهلاكنا لهم لَدلالةً بيِّنةً للمصدقين العاملين بشرع الله.", "isBasmala": false, "translation_en": "Surely in that are lessons for those who read signs.", "translation_id": "Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang memperhatikan tanda-tanda.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 76, "text": "وَإِنَّهَا لَبِسَبِیلࣲ مُّقِیمٍ ۝٧٦", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "إن فيما أصابهم لَعظاتٍ للناظرين المعتبرين، وإن قراهم لفي طريق ثابت يراها المسافرون المارُّون بها. إن في إهلاكنا لهم لَدلالةً بيِّنةً للمصدقين العاملين بشرع الله.", "isBasmala": false, "translation_en": "And it is on an existing road.", "translation_id": "Dan sesungguhnya kota itu benar-benar terletak di jalan yang masih tetap (dilalui manusia).", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 77, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّلۡمُؤۡمِنِینَ ۝٧٧", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "إن فيما أصابهم لَعظاتٍ للناظرين المعتبرين، وإن قراهم لفي طريق ثابت يراها المسافرون المارُّون بها. إن في إهلاكنا لهم لَدلالةً بيِّنةً للمصدقين العاملين بشرع الله.", "isBasmala": false, "translation_en": "Surely in that is a sign for the believers.", "translation_id": "Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang beriman.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 78, "text": "وَإِن كَانَ أَصۡحَـٰبُ ٱلۡأَیۡكَةِ لَظَـٰلِمِینَ ۝٧٨", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وقد كان أصحاب المدينة الملتفة الشجر -وهم قوم شعيب- ظالمين لأنفسهم لكفرهم بالله ورسولهم الكريم، فانتقمنا منهم بالرجفة وعذاب يوم الظلة، وإن مساكن قوم لوط وشعيب لفي طريق واضح يمرُّ بهما الناس في سفرهم فيعتبرون.", "isBasmala": false, "translation_en": "The people of the Woods were also wrongdoers.", "translation_id": "Dan sesungguhnya adalah penduduk Aikah itu benar-benar kaum yang zalim,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 79, "text": "فَٱنتَقَمۡنَا مِنۡهُمۡ وَإِنَّهُمَا لَبِإِمَامࣲ مُّبِینࣲ ۝٧٩", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وقد كان أصحاب المدينة الملتفة الشجر -وهم قوم شعيب- ظالمين لأنفسهم لكفرهم بالله ورسولهم الكريم، فانتقمنا منهم بالرجفة وعذاب يوم الظلة، وإن مساكن قوم لوط وشعيب لفي طريق واضح يمرُّ بهما الناس في سفرهم فيعتبرون.", "isBasmala": false, "translation_en": "So We took revenge upon them. Both are clearly documented.", "translation_id": "maka Kami membinasakan mereka. Dan sesungguhnya kedua kota itu benar-benar terletak di jalan umum yang terang.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 80, "text": "وَلَقَدۡ كَذَّبَ أَصۡحَـٰبُ ٱلۡحِجۡرِ ٱلۡمُرۡسَلِینَ ۝٨٠", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "ولقد كذَّب سكان \"وادي الحِجْر\" صالحًا عليه السلام، وهم ثمود فكانوا بذلك مكذبين لكل المرسلين؛ لأن من كذَّب نبيًا فقد كذَّب الأنبياء كلهم؛ لأنهم على دين واحد.", "isBasmala": false, "translation_en": "The people of the Rock also rejected the messengers.", "translation_id": "Dan sesungguhnya penduduk-penduduk kota Al Hijr telah mendustakan rasul-rasul,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 81, "text": "وَءَاتَیۡنَـٰهُمۡ ءَایَـٰتِنَا فَكَانُوا۟ عَنۡهَا مُعۡرِضِینَ ۝٨١", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وآتينا قوم صالح آياتنا الدالة على صحة ما جاءهم به صالح من الحق، ومن جملتها الناقة، فلم يعتبروا بها، وكانوا عنها مبتعدين معرضين.", "isBasmala": false, "translation_en": "We gave them Our revelations, but they turned away from them.", "translation_id": "dan Kami telah mendatangkan kepada mereka tanda-tanda (kekuasaan) Kami, tetapi mereka selalu berpaling daripadanya,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 82, "text": "وَكَانُوا۟ یَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُیُوتًا ءَامِنِینَ ۝٨٢", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وكانوا ينحتون الجبال، فيتخذون منها بيوتًا، وهم آمنون من أن تسقط عليهم أو تخرب.", "isBasmala": false, "translation_en": "They used to carve homes in the mountains, feeling secure.", "translation_id": "dan mereka memahat rumah-rumah dari gunung-gunung batu (yang didiami) dengan aman.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 83, "text": "فَأَخَذَتۡهُمُ ٱلصَّیۡحَةُ مُصۡبِحِینَ ۝٨٣", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "فأخذتهم صاعقة العذاب وقت الصباح مبكرين، فما دفع عنهم عذابَ الله الأموالُ والحصونُ في الجبال، ولا ما أُعطوه من قوة وجاه.", "isBasmala": false, "translation_en": "But the Blast struck them in the morning.", "translation_id": "Maka mereka dibinasakan oleh suara keras yang mengguntur di waktu pagi,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 84, "text": "فَمَاۤ أَغۡنَىٰ عَنۡهُم مَّا كَانُوا۟ یَكۡسِبُونَ ۝٨٤", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "فأخذتهم صاعقة العذاب وقت الصباح مبكرين، فما دفع عنهم عذابَ الله الأموالُ والحصونُ في الجبال، ولا ما أُعطوه من قوة وجاه.", "isBasmala": false, "translation_en": "All they had acquired was of no avail to them.", "translation_id": "maka tak dapat menolong mereka, apa yang telah mereka usahakan.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 85, "text": "وَمَا خَلَقۡنَا ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَاۤ إِلَّا بِٱلۡحَقِّۗ وَإِنَّ ٱلسَّاعَةَ لَـَٔاتِیَةࣱۖ فَٱصۡفَحِ ٱلصَّفۡحَ ٱلۡجَمِیلَ ۝٨٥", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وما خلَقْنا السموات والأرض وما بينهما إلا بالحق دالتين على كمال خالقهما واقتداره، وأنه الذي لا تنبغي العبادة إلا له وحده لا شريك له. وإن الساعة التي تقوم فيها القيامة لآتية لا محالة؛ لتوفَّى كل نفس بما عملت، فاعف -أيها الرسول- عن المشركين، واصفح عنهم وتجاوز عما يفعلونه.", "isBasmala": false, "translation_en": "We did not create the heavens and the earth, and what lies between them, except with truth. The Hour is coming, so forgive with gracious forgiveness.", "translation_id": "Dan tidaklah Kami ciptakan langit dan bumi dan apa yang ada di antara keduanya, melainkan dengan benar. Dan sesungguhnya saat (kiamat) itu pasti akan datang, maka maafkanlah (mereka) dengan cara yang baik.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 86, "text": "إِنَّ رَبَّكَ هُوَ ٱلۡخَلَّـٰقُ ٱلۡعَلِیمُ ۝٨٦", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "إنَّ ربك هو الخلاَّق لكل شيء، العليم به، فلا يعجزه شيء في الأرض ولا في السماء، ولا يخفى عليه.", "isBasmala": false, "translation_en": "Your Lord is the All-Knowing Creator.", "translation_id": "Sesungguhnya Tuhanmu, Dialah Yang Maha Pencipta lagi Maha Mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 87, "text": "وَلَقَدۡ ءَاتَیۡنَـٰكَ سَبۡعࣰا مِّنَ ٱلۡمَثَانِی وَٱلۡقُرۡءَانَ ٱلۡعَظِیمَ ۝٨٧", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "ولقد آتيناك -أيها النبي- فاتحة القرآن، وهي سبع آيات تكرر في كل صلاة، وآتيناك القرآن العظيم.", "isBasmala": false, "translation_en": "We have given you seven of the pairs, and the Grand Quran.", "translation_id": "Dan sesungguhnya Kami telah berikan kepadamu tujuh ayat yang dibaca berulang-ulang dan Al Quran yang agung.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 88, "text": "لَا تَمُدَّنَّ عَیۡنَیۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦۤ أَزۡوَ ٰجࣰا مِّنۡهُمۡ وَلَا تَحۡزَنۡ عَلَیۡهِمۡ وَٱخۡفِضۡ جَنَاحَكَ لِلۡمُؤۡمِنِینَ ۝٨٨", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "لا تنظر بعينيك وتتمنَّ ما مَتَّعْنا به أصنافًا من الكفار مِن مُتَع الدنيا، ولا تحزن على كفرهم، وتواضَعْ للمؤمنين بالله ورسوله.", "isBasmala": false, "translation_en": "Do not extend your eyes towards what We have bestowed on some couples of them to enjoy, and do not grieve over them, and lower your wing to the believers.", "translation_id": "Janganlah sekali-kali kamu menunjukkan pandanganmu kepada kenikmatan hidup yang telah Kami berikan kepada beberapa golongan di antara mereka (orang-orang kafir itu), dan janganlah kamu bersedih hati terhadap mereka dan berendah dirilah kamu terhadap orang-orang yang beriman.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 89, "text": "وَقُلۡ إِنِّیۤ أَنَا ٱلنَّذِیرُ ٱلۡمُبِینُ ۝٨٩", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وقل: إني أنا المنذر الموضِّح لما يهتدي به الناس إلى الإيمان بالله رب العالمين، ومنذركم أن يصيبكم العذاب، كما أنزله الله على الذين قسَّموا القرآن، فآمنوا ببعضه، وكفروا ببعضه الآخر من اليهود والنصارى وغيرهم.", "isBasmala": false, "translation_en": "And say, \"I am the clear warner.\"", "translation_id": "Dan katakanlah: \"Sesungguhnya aku adalah pemberi peringatan yang menjelaskan\".", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 90, "text": "كَمَاۤ أَنزَلۡنَا عَلَى ٱلۡمُقۡتَسِمِینَ ۝٩٠", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وقل: إني أنا المنذر الموضِّح لما يهتدي به الناس إلى الإيمان بالله رب العالمين، ومنذركم أن يصيبكم العذاب، كما أنزله الله على الذين قسَّموا القرآن، فآمنوا ببعضه، وكفروا ببعضه الآخر من اليهود والنصارى وغيرهم.", "isBasmala": false, "translation_en": "Just as We sent down to the separatists.", "translation_id": "Sebagaimana (Kami telah memberi peringatan), Kami telah menurunkan (azab) kepada orang-orang yang membagi-bagi (Kitab Allah),", "manzil": 3, "manzil_display": ""}], "267": [{"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 91, "text": "ٱلَّذِینَ جَعَلُوا۟ ٱلۡقُرۡءَانَ عِضِینَ ۝٩١", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "وهم الذين جعلوا القرآن أقسامًا وأجزاء، فمنهم من يقول: سحر، ومنهم من يقول كَهَانة، ومنهم من يقول غير ذلك، يصرِّفونه بحسب أهوائهم؛ ليصدوا الناس عن الهدى.", "isBasmala": false, "translation_en": "Those who made the Quran obsolete.", "translation_id": "(yaitu) orang-orang yang telah menjadikan Al Quran itu terbagi-bagi.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 92, "text": "فَوَرَبِّكَ لَنَسۡـَٔلَنَّهُمۡ أَجۡمَعِینَ ۝٩٢", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "فوربك لنحاسبنَّهم يوم القيامة ولنجزينهم أجمعين، عن تقسيمهم للقرآن بافتراءاتهم، وتحريفه وتبديله، وغير ذلك مما كانوا يعملونه من عبادة الأوثان، ومن المعاصي والآثام. وفي هذا ترهيب وزجر لهم من الإقامة على هذه الأفعال القبيحة.", "isBasmala": false, "translation_en": "By your Lord, we will question them all.", "translation_id": "Maka demi Tuhanmu, Kami pasti akan menanyai mereka semua,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 93, "text": "عَمَّا كَانُوا۟ یَعۡمَلُونَ ۝٩٣", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "فوربك لنحاسبنَّهم يوم القيامة ولنجزينهم أجمعين، عن تقسيمهم للقرآن بافتراءاتهم، وتحريفه وتبديله، وغير ذلك مما كانوا يعملونه من عبادة الأوثان، ومن المعاصي والآثام. وفي هذا ترهيب وزجر لهم من الإقامة على هذه الأفعال القبيحة.", "isBasmala": false, "translation_en": "About what they used to do.", "translation_id": "tentang apa yang telah mereka kerjakan dahulu.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 94, "text": "فَٱصۡدَعۡ بِمَا تُؤۡمَرُ وَأَعۡرِضۡ عَنِ ٱلۡمُشۡرِكِینَ ۝٩٤", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "فاجهر بدعوة الحق التي أمرك الله بها، ولا تبال بالمشركين، فقد برَّأك الله ممَّا يقولون.", "isBasmala": false, "translation_en": "So proclaim openly what you are commanded, and turn away from the polytheists.", "translation_id": "Maka sampaikanlah olehmu secara terang-terangan segala apa yang diperintahkan (kepadamu) dan berpalinglah dari orang-orang yang musyrik.", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 95, "text": "إِنَّا كَفَیۡنَـٰكَ ٱلۡمُسۡتَهۡزِءِینَ ۝٩٥", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "إنَّا كَفَيْناك المستهزئين الساخرين من زعماء قريش، الذين اتخذوا شريكًا مع الله من الأوثان وغيرها، فسوف يعلمون عاقبة عملهم في الدنيا والآخرة.", "isBasmala": false, "translation_en": "We are enough for you against the mockers.", "translation_id": "Sesungguhnya Kami memelihara kamu daripada (kejahatan) orang-orang yang memperolok-olokkan (kamu),", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 96, "text": "ٱلَّذِینَ یَجۡعَلُونَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَۚ فَسَوۡفَ یَعۡلَمُونَ ۝٩٦", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "إنَّا كَفَيْناك المستهزئين الساخرين من زعماء قريش، الذين اتخذوا شريكًا مع الله من الأوثان وغيرها، فسوف يعلمون عاقبة عملهم في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Those who set up another god with God. They will come to know.", "translation_id": "(Yaitu) orang-orang yang menganggap adanya tuhan yang lain di samping Allah; maka mereka kelak akan mengetahui (akibat-akibatnya).", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 97, "text": "وَلَقَدۡ نَعۡلَمُ أَنَّكَ یَضِیقُ صَدۡرُكَ بِمَا یَقُولُونَ ۝٩٧", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "ولقد نعلم بانقباض صدرك -أيها الرسول-؛ بسبب ما يقوله المشركون فيك وفي دعوتك.", "isBasmala": false, "translation_en": "We are aware that your heart is strained by what they say.", "translation_id": "Dan Kami sungguh-sungguh mengetahui, bahwa dadamu menjadi sempit disebabkan apa yang mereka ucapkan,", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 98, "text": "فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَكُن مِّنَ ٱلسَّـٰجِدِینَ ۝٩٨", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "فافزع إلى ربك عند ضيق صدرك، وسَبِّح بحمده شاكرًا له مثنيا عليه، وكن من المصلِّين لله العابدين له، فإن ذلك يكفيك ما أهمَّك.", "isBasmala": false, "translation_en": "So glorify the praise of your Lord, and be among those who bow down.", "translation_id": "maka bertasbihlah dengan memuji Tuhanmu dan jadilah kamu di antara orang-orang yang bersujud (shalat),", "manzil": 3, "manzil_display": ""}, {"sura": 15, "sura_name": "الحجر", "revelation": "Makkiyah", "aya": 99, "text": "وَٱعۡبُدۡ رَبَّكَ حَتَّىٰ یَأۡتِیَكَ ٱلۡیَقِینُ ۝٩٩", "juz": 14, "hizb": "(*¼ ح 27*)", "tafsir": "واستمِرَّ في عبادة ربك مدة حياتك حتى يأتيك اليقين، وهو الموت. وامتثل رسول الله صلى الله عليه وسلم أمر ربه، فلم يزل دائبًا في عبادة الله، حتى أتاه اليقين من ربه.", "isBasmala": false, "translation_en": "And worship your Lord in order to attain certainty.", "translation_id": "dan sembahlah Tuhanmu sampai datang kepadamu yang diyakini (ajal).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 14, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 1, "text": "۞ أَتَىٰۤ أَمۡرُ ٱللَّهِ فَلَا تَسۡتَعۡجِلُوهُۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ ۝١", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "قَرُب قيام الساعة وقضاء الله بعذابكم -أيها الكفار- فلا تستعجلوا العذاب استهزاء بوعيد الرسول لكم. تنزَّه الله سبحانه وتعالى عن الشرك والشركاء.", "isBasmala": false, "translation_en": "The command of God has come, so do not rush it. Glory be to Him; exalted above what they associate.", "translation_id": "Telah pasti datangnya ketetapan Allah maka janganlah kamu meminta agar disegerakan (datang)nya. Maha Suci Allah dan Maha Tinggi dari apa yang mereka persekutukan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 2, "text": "یُنَزِّلُ ٱلۡمَلَـٰۤىِٕكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۤ أَنۡ أَنذِرُوۤا۟ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّاۤ أَنَا۠ فَٱتَّقُونِ ۝٢", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "ينزِّل الله الملائكة بالوحي مِن أمره على مَن يشاء من عباده المرسلين: بأن خوِّفوا الناس من الشرك، وأنه لا معبود بحق إلا أنا، فاتقون بأداء فرائضي وإفرادي بالعبادة والإخلاص.", "isBasmala": false, "translation_en": "He sends down the angels with the Spirit by His command, upon whom He wills of His servants: \"Give warning that there is no god but Me, and fear Me.\"", "translation_id": "Dia menurunkan para malaikat dengan (membawa) wahyu dengan perintah-Nya kepada siapa yang Dia kehendaki di antara hamba-hamba-Nya, yaitu: \"Peringatkanlah olehmu sekalian, bahwasanya tidak ada Tuhan (yang hak) melainkan Aku, maka hendaklah kamu bertakwa kepada-Ku\".", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 3, "text": "خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ تَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ ۝٣", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "خلق الله السموات والأرض بالحق؛ ليستدِل بهما العباد على عظمة خالقهما، وأنه وحده المستحق للعبادة، تنزَّه -سبحانه- وتعاظم عن شركهم.", "isBasmala": false, "translation_en": "He created the heavens and the earth with justice. He is exalted above the associations they attribute.", "translation_id": "Dia menciptakan langit dan bumi dengan hak. Maha Tinggi Allah daripada apa yang mereka persekutukan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 4, "text": "خَلَقَ ٱلۡإِنسَـٰنَ مِن نُّطۡفَةࣲ فَإِذَا هُوَ خَصِیمࣱ مُّبِینࣱ ۝٤", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "خَلَق الإنسان من ماء مهين فإذا به يَقْوى ويغترُّ، فيصبح شديد الخصومة والجدال لربه في إنكار البعث، وغير ذلك، كقوله: \"مَن يُحْيِ الْعِظَامَ وَهِيَ رَمِيمٌ\"، ونسي الله الذي خلقه من العدم.", "isBasmala": false, "translation_en": "He created the human being from a drop of fluid, yet he becomes an open adversary.", "translation_id": "Dia telah menciptakan manusia dari mani, tiba-tiba ia menjadi pembantah yang nyata.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 5, "text": "وَٱلۡأَنۡعَـٰمَ خَلَقَهَاۖ لَكُمۡ فِیهَا دِفۡءࣱ وَمَنَـٰفِعُ وَمِنۡهَا تَأۡكُلُونَ ۝٥", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "والأنعامَ من الإبل والبقر والغنم خلقها الله لكم -أيها الناس- وجعل في أصوافها وأوبارها الدفء، ومنافع أُخر في ألبانها وجلودها وركوبها، ومنها ما تأكلون.", "isBasmala": false, "translation_en": "And the livestock-He created them for you. In them are warmth and benefits for you, and of them you eat.", "translation_id": "Dan Dia telah menciptakan binatang ternak untuk kamu; padanya ada (bulu) yang menghangatkan dan berbagai-bagai manfaat, dan sebahagiannya kamu makan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 6, "text": "وَلَكُمۡ فِیهَا جَمَالٌ حِینَ تُرِیحُونَ وَحِینَ تَسۡرَحُونَ ۝٦", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "ولكم فيها زينة تُدْخل السرور عليكم عندما تَرُدُّونها إلى منازلها في المساء، وعندما تُخْرجونها للمرعى في الصباح.", "isBasmala": false, "translation_en": "And there is beauty in them for you, when you bring them home, and when you drive them to pasture.", "translation_id": "Dan kamu memperoleh pandangan yang indah padanya, ketika kamu membawanya kembali ke kandang dan ketika kamu melepaskannya ke tempat penggembalaan.", "manzil": 3, "manzil_display": ""}], "268": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 7, "text": "وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَدࣲ لَّمۡ تَكُونُوا۟ بَـٰلِغِیهِ إِلَّا بِشِقِّ ٱلۡأَنفُسِۚ إِنَّ رَبَّكُمۡ لَرَءُوفࣱ رَّحِیمࣱ ۝٧", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وتحمل هذه الأنعام ما ثَقُل من أمتعتكم إلى بلد بعيد، لم تكونوا مستطيعين الوصول إليه إلا بجهد شديد من أنفسكم ومشقة عظيمة، إن ربكم لَرؤوف رحيم بكم، حيث سخَّر لكم ما تحتاجون إليه، فله الحمد وله الشكر.", "isBasmala": false, "translation_en": "And they carry your loads to territory you could not have reached without great hardship. Your Lord is Clement and Merciful.", "translation_id": "Dan ia memikul beban-bebanmu ke suatu negeri yang kamu tidak sanggup sampai kepadanya, melainkan dengan kesukaran-kesukaran (yang memayahkan) diri. Sesungguhnya Tuhanmu benar-benar Maha Pengasih lagi Maha Penyayang,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 8, "text": "وَٱلۡخَیۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِیرَ لِتَرۡكَبُوهَا وَزِینَةࣰۚ وَیَخۡلُقُ مَا لَا تَعۡلَمُونَ ۝٨", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وخلق لكم الخيل والبغال والحمير؛ لكي تركبوها، ولتكون جمَالا لكم ومنظرًا حسنًا؛ ويخلق لكم من وسائل الركوب وغيرها ما لا عِلْمَ لكم به؛ لتزدادوا إيمانًا به وشكرا له.", "isBasmala": false, "translation_en": "And the horses, and the mules, and the donkeys-for you to ride, and for luxury. And He creates what you do not know.", "translation_id": "dan (Dia telah menciptakan) kuda, bagal dan keledai, agar kamu menungganginya dan (menjadikannya) perhiasan. Dan Allah menciptakan apa yang kamu tidak mengetahuinya.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 9, "text": "وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِیلِ وَمِنۡهَا جَاۤىِٕرࣱۚ وَلَوۡ شَاۤءَ لَهَدَىٰكُمۡ أَجۡمَعِینَ ۝٩", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وعلى الله بيان الطريق المستقيم لِهدايتكم، وهو الإسلام، ومن الطرق ما هو مائل لا يُوصل إلى الهداية، وهو كل ما خالف الإسلام من الملل والنحل. ولو شاء الله هدايتكم لهداكم جميعًا للإيمان.", "isBasmala": false, "translation_en": "It is for God to point out the paths, but some of them are flawed. Had He willed, He could have guided you all.", "translation_id": "Dan hak bagi Allah (menerangkan) jalan yang lurus, dan di antara jalan-jalan ada yang bengkok. Dan jikalau Dia menghendaki, tentulah Dia memimpin kamu semuanya (kepada jalan yang benar).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 10, "text": "هُوَ ٱلَّذِیۤ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰۖ لَّكُم مِّنۡهُ شَرَابࣱ وَمِنۡهُ شَجَرࣱ فِیهِ تُسِیمُونَ ۝١٠", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "هو الذي أنزل لكم من السحاب مطرًا، فجعل لكم منه ماءً تشربونه، وأخرج لكم به شجرًا تَرْعَوْن فيه دوابّكم، ويعود عليكم دَرُّها ونفْعُها.", "isBasmala": false, "translation_en": "It is He Who sends down for you from the sky water. From it is drink, and with it grows vegetation for grazing.", "translation_id": "Dialah, Yang telah menurunkan air hujan dari langit untuk kamu, sebahagiannya menjadi minuman dan sebahagiannya (menyuburkan) tumbuh-tumbuhan, yang pada (tempat tumbuhnya) kamu menggembalakan ternakmu.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 11, "text": "یُنۢبِتُ لَكُم بِهِ ٱلزَّرۡعَ وَٱلزَّیۡتُونَ وَٱلنَّخِیلَ وَٱلۡأَعۡنَـٰبَ وَمِن كُلِّ ٱلثَّمَرَ ٰتِۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَتَفَكَّرُونَ ۝١١", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "يُخرج لكم من الأرض بهذا الماء الواحد الزروع المختلفة، ويُخرج به الزيتون والنخيل والأعناب، ويُخرج به كل أنواع الثمار والفواكه. إن في ذلك الإخراج لدلالةً واضحة لقوم يتأملون، فيعتبرون.", "isBasmala": false, "translation_en": "And He produces for you grains with it, and olives, and date-palms, and grapes, and all kinds of fruits. Surely in that is a sign for people who think.", "translation_id": "Dia menumbuhkan bagi kamu dengan air hujan itu tanam-tanaman; zaitun, korma, anggur dan segala macam buah-buahan. Sesungguhnya pada yang demikian itu benar-benar ada tanda (kekuasaan Allah) bagi kaum yang memikirkan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 12, "text": "وَسَخَّرَ لَكُمُ ٱلَّیۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ وَٱلنُّجُومُ مُسَخَّرَ ٰتُۢ بِأَمۡرِهِۦۤۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَعۡقِلُونَ ۝١٢", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وسخَّر لكم الليل لراحتكم، والنهار لمعاشكم، وسخَّر لكم الشمس ضياء، والقمر نورًا ولمعرفة السنين والحساب، وغير ذلك من المنافع، والنجوم في السماء مذللات لكم بأمر الله لمعرفة الأوقات، ونضج الثمار والزروع، والاهتداء بها في الظلمات. إن في ذلك التسخير لَدلائلَ واضحةً لقوم سيعقلون عن الله حججه وبراهينه.", "isBasmala": false, "translation_en": "And He regulated for you the night and the day; and the sun, and the moon, and the stars are disposed by His command. Surely in that are signs for people who ponder.", "translation_id": "Dan Dia menundukkan malam dan siang, matahari dan bulan untukmu. Dan bintang-bintang itu ditundukkan (untukmu) dengan perintah-Nya. Sesungguhnya pada yang demikian itu benar-benar ada tanda-tanda (kekuasaan Allah) bagi kaum yang memahami(nya),", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 13, "text": "وَمَا ذَرَأَ لَكُمۡ فِی ٱلۡأَرۡضِ مُخۡتَلِفًا أَلۡوَ ٰنُهُۥۤۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَذَّكَّرُونَ ۝١٣", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وسخَّر ما خلقه لكم في الأرض من الدوابِّ والثمار والمعادن، وغير ذلك مما تختلف ألوانه ومنافعه. إن في ذلك الخَلْق واختلاف الألوان والمنافع لَعبرةً لقوم يتعظون، ويعلمون أنَّ في تسخير هذه الأشياء علاماتٍ على وحدانية الله تعالى وإفراده بالعبادة.", "isBasmala": false, "translation_en": "And whatsoever He created for you on earth is of diverse colors. Surely in that is a sign for people who are mindful.", "translation_id": "dan Dia (menundukkan pula) apa yang Dia ciptakan untuk kamu di bumi ini dengan berlain-lainan macamnya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah) bagi kaum yang mengambil pelajaran.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 14, "text": "وَهُوَ ٱلَّذِی سَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُوا۟ مِنۡهُ لَحۡمࣰا طَرِیࣰّا وَتَسۡتَخۡرِجُوا۟ مِنۡهُ حِلۡیَةࣰ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِیهِ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ۝١٤", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وهو الذي سخَّر لكم البحر؛ لتأكلوا مما تصطادون من سمكه لحمًا طريًا، وتستخرجوا منه زينة تَلْبَسونها كاللؤلؤ والمرجان، وترى السفن العظيمة تشق وجه الماء تذهب وتجيء، وتركبونها؛ لتطلبوا رزق الله بالتجارة والربح فيها، ولعلكم تشكرون لله تعالى على عظيم إنعامه عليكم، فلا تعبدون غيره.", "isBasmala": false, "translation_en": "And it is He who made the sea to serve you, that you may eat from it tender meat, and extract from it ornaments that you wear. And you see the ships plowing through it, as you seek His bounties, so that you may give thanks.", "translation_id": "Dan Dialah, Allah yang menundukkan lautan (untukmu), agar kamu dapat memakan daripadanya daging yang segar (ikan), dan kamu mengeluarkan dari lautan itu perhiasan yang kamu pakai; dan kamu melihat bahtera berlayar padanya, dan supaya kamu mencari (keuntungan) dari karunia-Nya, dan supaya kamu bersyukur.", "manzil": 3, "manzil_display": ""}], "269": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 15, "text": "وَأَلۡقَىٰ فِی ٱلۡأَرۡضِ رَوَ ٰسِیَ أَن تَمِیدَ بِكُمۡ وَأَنۡهَـٰرࣰا وَسُبُلࣰا لَّعَلَّكُمۡ تَهۡتَدُونَ ۝١٥", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وأرسى في الأرض جبالا تثبتها حتى لا تميل بكم، وجعل فيها أنهارًا؛ لتشربوا منها، وجعل فيها طرقًا؛ لتهتدوا بها في الوصول إلى الأماكن التي تقصدونها.", "isBasmala": false, "translation_en": "And he cast mountains on the earth, lest it shifts with you; and rivers, and roads, so that you may be guided.", "translation_id": "Dan Dia menancapkan gunung-gunung di bumi supaya bumi itu tidak goncang bersama kamu, (dan Dia menciptakan) sungai-sungai dan jalan-jalan agar kamu mendapat petunjuk,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 16, "text": "وَعَلَـٰمَـٰتࣲۚ وَبِٱلنَّجۡمِ هُمۡ یَهۡتَدُونَ ۝١٦", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وجعل في الأرض معالم تستدلُّون بها على الطرق نهارًا، كما جعل النجوم للاهتداء بها ليلا.", "isBasmala": false, "translation_en": "And landmarks. And by the stars they guide themselves.", "translation_id": "dan (Dia ciptakan) tanda-tanda (penunjuk jalan). Dan dengan bintang-bintang itulah mereka mendapat petunjuk.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 17, "text": "أَفَمَن یَخۡلُقُ كَمَن لَّا یَخۡلُقُۚ أَفَلَا تَذَكَّرُونَ ۝١٧", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "أتجعلون الله الذي يخلق كل هذه الأشياء وغيرها في استحقاق العبادة كالآلهة المزعومة التي لا تخلق شيئًا؟ أفلا تتذكرون عظمة الله، فتفردوه بالعبادة؟", "isBasmala": false, "translation_en": "Is He who creates like him who does not create? Will you not take a lesson?", "translation_id": "Maka apakah (Allah) yang menciptakan itu sama dengan yang tidak dapat menciptakan (apa-apa)?. Maka mengapa kamu tidak mengambil pelajaran.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 18, "text": "وَإِن تَعُدُّوا۟ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَاۤۗ إِنَّ ٱللَّهَ لَغَفُورࣱ رَّحِیمࣱ ۝١٨", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وإن تحاولوا حَصْرَ نِعَم الله عليكم لا تَفُوا بحَصْرها؛ لكثرتها وتنوعها. إن الله لَغفور لكم رحيم بكم؛ إذ يتجاوز عن تقصيركم في أداء شكر النعم، ولا يقطعها عنكم لتفريطكم، ولا يعاجلكم بالعقوبة.", "isBasmala": false, "translation_en": "And if you tried to enumerate the favors of God, you will not be able to count them. God is Forgiving and Merciful.", "translation_id": "Dan jika kamu menghitung-hitung nikmat Allah, niscaya kamu tak dapat menentukan jumlahnya. Sesungguhnya Allah benar-benar Maha Pengampun lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 19, "text": "وَٱللَّهُ یَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَ ۝١٩", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "والله سبحانه يعلم كل أعمالكم، سواء ما تخفونه منها في نفوسكم وما تظهرونه لغيركم، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "And God knows what you hide and what you disclose.", "translation_id": "Dan Allah mengetahui apa yang kamu rahasiakan dan apa yang kamu lahirkan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 20, "text": "وَٱلَّذِینَ یَدۡعُونَ مِن دُونِ ٱللَّهِ لَا یَخۡلُقُونَ شَیۡـࣰٔا وَهُمۡ یُخۡلَقُونَ ۝٢٠", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "والآلهة التي يعبدها المشركون لا تخلق شيئًا وإن صَغُر، فهي مخلوقات صنعها الكفار بأيديهم، فكيف يعبدونها؟", "isBasmala": false, "translation_en": "Those they invoke besides God create nothing, but are themselves created.", "translation_id": "Dan berhala-berhala yang mereka seru selain Allah, tidak dapat membuat sesuatu apapun, sedang berhala-berhala itu (sendiri) dibuat orang.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 21, "text": "أَمۡوَ ٰتٌ غَیۡرُ أَحۡیَاۤءࣲۖ وَمَا یَشۡعُرُونَ أَیَّانَ یُبۡعَثُونَ ۝٢١", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "هم جميعًا جمادات لا حياة فيها ولا تشعر بالوقت الذي يبعث الله فيه عابديها، وهي معهم ليُلقى بهم جميعًا في النار يوم القيامة.", "isBasmala": false, "translation_en": "They are dead, not alive; and they do not know when they will be resurrected.", "translation_id": "(Berhala-berhala itu) benda mati tidak hidup, dan berhala-berhala tidak mengetahui bilakah penyembah-penyembahnya akan dibangkitkan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 22, "text": "إِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰحِدࣱۚ فَٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ قُلُوبُهُم مُّنكِرَةࣱ وَهُم مُّسۡتَكۡبِرُونَ ۝٢٢", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "إلهكم المستحق وحده للعبادة هو الله الإله الواحد، فالذين لا يؤمنون بالبعث قلوبهم جاحدة وحدانيته سبحانه؛ لعدم خوفهم من عقابه، فهم متكبرون عن قبول الحق، وعبادة الله وحده.", "isBasmala": false, "translation_en": "Your God is one God. As for those who do not believe in the Hereafter, their hearts are in denial, and they are arrogant.", "translation_id": "Tuhan kamu adalah Tuhan Yang Maha Esa. Maka orang-orang yang tidak beriman kepada akhirat, hati mereka mengingkari (keesaaan Allah), sedangkan mereka sendiri adalah orang-orang yang sombong.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 23, "text": "لَا جَرَمَ أَنَّ ٱللَّهَ یَعۡلَمُ مَا یُسِرُّونَ وَمَا یُعۡلِنُونَۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡمُسۡتَكۡبِرِینَ ۝٢٣", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "حقًا أنَّ الله يعلم ما يخفونه مِن عقائد وأقوال وأفعال، وما يظهرونه منها، وسيجازيهم على ذلك، إنه عز وجل لا يحب المستكبرين عن عبادته والانقياد له، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "Without a doubt, God knows what they conceal and what they reveal. He does not like the arrogant.", "translation_id": "Tidak diragukan lagi bahwa sesungguhnya Allah mengetahui apa yang mereka rahasiakan dan apa yang mereka lahirkan. Sesungguhnya Allah tidak menyukai orang-orang yang sombong.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 24, "text": "وَإِذَا قِیلَ لَهُم مَّاذَاۤ أَنزَلَ رَبُّكُمۡ قَالُوۤا۟ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ۝٢٤", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "وإذا سُئِل هؤلاء المشركون عمَّا نزل على النبي محمد صلى الله عليه وسلم قالوا كذبًا وزورًا: ما أتى إلا بقصص السابقين وأباطيلهم.", "isBasmala": false, "translation_en": "And when it is said to them, \"What has your Lord sent down?\" They say, \"Legends of the ancients.\"", "translation_id": "Dan apabila dikatakan kepada mereka \"Apakah yang telah diturunkan Tuhanmu?\" Mereka menjawab: \"Dongeng-dongengan orang-orang dahulu\",", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 25, "text": "لِیَحۡمِلُوۤا۟ أَوۡزَارَهُمۡ كَامِلَةࣰ یَوۡمَ ٱلۡقِیَـٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِینَ یُضِلُّونَهُم بِغَیۡرِ عِلۡمٍۗ أَلَا سَاۤءَ مَا یَزِرُونَ ۝٢٥", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "ستكون عاقبتهم أن يحملوا آثامهم كاملة يوم القيامة -لا يُغْفَر لهم منها شيء - ويَحْملوا من آثام الذين كذبوا عليهم؛ ليبعدوهم عن الإسلام من غير نقص من آثامهم. ألا قَبُحَ ما يحملونه من آثام.", "isBasmala": false, "translation_en": "So let them carry their loads complete on the Day of Resurrection, and some of the loads of those they misguided without knowledge. Evil is what they carry.", "translation_id": "(ucapan mereka) menyebabkan mereka memikul dosa-dosanya dengan sepenuh-penuhnya pada hari kiamat, dan sebahagian dosa-dosa orang yang mereka sesatkan yang tidak mengetahui sedikitpun (bahwa mereka disesatkan). Ingatlah, amat buruklah dosa yang mereka pikul itu.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 26, "text": "قَدۡ مَكَرَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَأَتَى ٱللَّهُ بُنۡیَـٰنَهُم مِّنَ ٱلۡقَوَاعِدِ فَخَرَّ عَلَیۡهِمُ ٱلسَّقۡفُ مِن فَوۡقِهِمۡ وَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَیۡثُ لَا یَشۡعُرُونَ ۝٢٦", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "قد دبَّر الكفار من قَبْل هؤلاء المشركين المكايد لرسلهم، وما جاءوا به من دعوة الحق، فأتى الله بنيانهم من أساسه وقاعدته، فسقط عليهم السقف مِن فوقهم، وأتاهم الهلاك مِن مأمنهم، من حيث لا يحتسبون ولا يتوقعون أنه يأتيهم منه.", "isBasmala": false, "translation_en": "Those before them also schemed, but God took their structures from the foundations, and the roof caved in on them. The punishment came at them from where they did not perceive.", "translation_id": "Sesungguhnya orang-orang yang sebelum mereka telah mengadakan makar, maka Allah menghancurkan rumah-rumah mereka dari fondasinya, lalu atap (rumah itu) jatuh menimpa mereka dari atas, dan datanglah azab itu kepada mereka dari tempat yang tidak mereka sadari.", "manzil": 3, "manzil_display": ""}], "270": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 27, "text": "ثُمَّ یَوۡمَ ٱلۡقِیَـٰمَةِ یُخۡزِیهِمۡ وَیَقُولُ أَیۡنَ شُرَكَاۤءِیَ ٱلَّذِینَ كُنتُمۡ تُشَـٰۤقُّونَ فِیهِمۡۚ قَالَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ إِنَّ ٱلۡخِزۡیَ ٱلۡیَوۡمَ وَٱلسُّوۤءَ عَلَى ٱلۡكَـٰفِرِینَ ۝٢٧", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "ثم يوم القيامة يفضحهم الله بالعذاب ويذلُّهم به، ويقول: أين شركائي من الآلهة التي عبدتموها من دوني؛ ليدفعوا عنكم العذاب، وقد كنتم تحاربون الأنبياء والمؤمنين وتعادونهم لأجلهم؟ قال العلماء الربانيون: إن الذل في هذا اليوم والعذاب على الكافرين بالله ورسله، الذين تقبض الملائكة أرواحهم في حال ظلمهم لأنفسهم بالكفر، فاستسْلَموا لأمر الله حين رأوا الموت، وأنكروا ما كانوا يعبدون من دون الله، وقالوا: ما كنا نعمل شيئًا من المعاصي، فيقال لهم: كَذَبْتم، قد كنتم تعملونها، إن الله عليم بأعمالكم كلها، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "Then, on the Day of Resurrection, He will disgrace them, and say, \"Where are My associates for whose sake you used to dispute?\" Those who were given knowledge will say, \"Today shame and misery are upon the disbelievers.\"", "translation_id": "Kemudian Allah menghinakan mereka di hari kiamat, dan berfirman: \"Di manakah sekutu-sekutu-Ku itu (yang karena membelanya) kamu selalu memusuhi mereka (nabi-nabi dan orang-orang mukmin)?\" Berkatalah orang-orang yang telah diberi ilmu: \"Sesungguhnya kehinaan dan azab hari ini ditimpakan atas orang-orang yang kafir\",", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 28, "text": "ٱلَّذِینَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰۤىِٕكَةُ ظَالِمِیۤ أَنفُسِهِمۡۖ فَأَلۡقَوُا۟ ٱلسَّلَمَ مَا كُنَّا نَعۡمَلُ مِن سُوۤءِۭۚ بَلَىٰۤۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٢٨", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "ثم يوم القيامة يفضحهم الله بالعذاب ويذلُّهم به، ويقول: أين شركائي من الآلهة التي عبدتموها من دوني؛ ليدفعوا عنكم العذاب، وقد كنتم تحاربون الأنبياء والمؤمنين وتعادونهم لأجلهم؟ قال العلماء الربانيون: إن الذل في هذا اليوم والعذاب على الكافرين بالله ورسله، الذين تقبض الملائكة أرواحهم في حال ظلمهم لأنفسهم بالكفر، فاستسْلَموا لأمر الله حين رأوا الموت، وأنكروا ما كانوا يعبدون من دون الله، وقالوا: ما كنا نعمل شيئًا من المعاصي، فيقال لهم: كَذَبْتم، قد كنتم تعملونها، إن الله عليم بأعمالكم كلها، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "Those wronging their souls while the angels are taking them away-they will propose peace: \"We did no wrong.\" Yes you did. God is aware of what you used to do.\"", "translation_id": "(yaitu) orang-orang yang dimatikan oleh para malaikat dalam keadaan berbuat zalim kepada diri mereka sendiri, lalu mereka menyerah diri (sambil berkata); \"Kami sekali-kali tidak ada mengerjakan sesuatu kejahatanpun\". (Malaikat menjawab): \"Ada, sesungguhnya Allah Maha Mengetahui apa yang telah kamu kerjakan\".", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 29, "text": "فَٱدۡخُلُوۤا۟ أَبۡوَ ٰبَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۖ فَلَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِینَ ۝٢٩", "juz": 14, "hizb": "(*½ ح 27*)", "tafsir": "فادخلوا أبواب جهنم، لا تخرجون منها أبدًا، فلبئست مقرًا للذين تكبَّروا عن الإيمان بالله وعن عبادته وحده وطاعته.", "isBasmala": false, "translation_en": "Enter the gates of Hell, to dwell therein forever. Miserable is the residence of the arrogant.", "translation_id": "Maka masukilah pintu-pintu neraka Jahannam, kamu kekal di dalamnya. Maka amat buruklah tempat orang-orang yang menyombongkan diri itu.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 30, "text": "۞ وَقِیلَ لِلَّذِینَ ٱتَّقَوۡا۟ مَاذَاۤ أَنزَلَ رَبُّكُمۡۚ قَالُوا۟ خَیۡرࣰاۗ لِّلَّذِینَ أَحۡسَنُوا۟ فِی هَـٰذِهِ ٱلدُّنۡیَا حَسَنَةࣱۚ وَلَدَارُ ٱلۡـَٔاخِرَةِ خَیۡرࣱۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِینَ ۝٣٠", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "وإذا قيل للمؤمنين الخائفين من الله: ما الذي أنزل الله على النبي محمد صلى الله عليه وسلم؟ قالوا: أنزل الله عليه الخير والهدى. للذين آمنوا بالله ورسوله في هذه الدنيا، ودَعَوْا عباد الله إلى الإيمان والعمل الصالح، مَكْرُمَة كبيرة من النصر لهم في الدنيا، وسَعَة الرزق، ولَدار الآخرة لهم خير وأعظم مما أُوتوه في الدنيا، ولَنِعْم دارُ المتقين الخائفين من الله الآخرةُ.", "isBasmala": false, "translation_en": "And it will be said to those who maintained piety, \"What has your Lord revealed?\" They will say, \"Goodness.\" To those who do good in this world is goodness, and the Home of the Hereafter is even better. How wonderful is the residence of the pious.", "translation_id": "Dan dikatakan kepada orang-orang yang bertakwa: \"Apakah yang telah diturunkan oleh Tuhanmu?\" Mereka menjawab: \"(Allah telah menurunkan) kebaikan\". Orang-orang yang berbuat baik di dunia ini mendapat (pembalasan) yang baik. Dan sesungguhnya kampung akhirat adalah lebih baik dan itulah sebaik-baik tempat bagi orang yang bertakwa,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 31, "text": "جَنَّـٰتُ عَدۡنࣲ یَدۡخُلُونَهَا تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ لَهُمۡ فِیهَا مَا یَشَاۤءُونَۚ كَذَ ٰلِكَ یَجۡزِی ٱللَّهُ ٱلۡمُتَّقِینَ ۝٣١", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "جنات إقامة لهم، يستقرون فيها، لا يخرجون منها أبدًا، تجري من تحت أشجارها وقصورها الأنهار، لهم فيها كل ما تشتهيه أنفسهم، بمثل هذا الجزاء الطيب يجزي الله أهل خشيته وتقواه الذين تقبض الملائكةُ أرواحَهم، وقلوبُهم طاهرة من الكفر، تقول الملائكة لهم: سلام عليكم، تحية خاصة لكم وسلامة من كل آفة، ادخلوا الجنة بما كنتم تعملون من الإيمان بالله والانقياد لأمره.", "isBasmala": false, "translation_en": "The Gardens of Perpetuity, which they will enter, beneath which rivers flow, where they will have whatever they desire. Thus God rewards the pious.", "translation_id": "(yaitu) surga 'Adn yang mereka masuk ke dalamnya, mengalir di bawahnya sungai-sungai, di dalam surga itu mereka mendapat segala apa yang mereka kehendaki. Demikianlah Allah memberi balasan kepada orang-orang yang bertakwa,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 32, "text": "ٱلَّذِینَ تَتَوَفَّىٰهُمُ ٱلۡمَلَـٰۤىِٕكَةُ طَیِّبِینَ یَقُولُونَ سَلَـٰمٌ عَلَیۡكُمُ ٱدۡخُلُوا۟ ٱلۡجَنَّةَ بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٣٢", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "جنات إقامة لهم، يستقرون فيها، لا يخرجون منها أبدًا، تجري من تحت أشجارها وقصورها الأنهار، لهم فيها كل ما تشتهيه أنفسهم، بمثل هذا الجزاء الطيب يجزي الله أهل خشيته وتقواه الذين تقبض الملائكةُ أرواحَهم، وقلوبُهم طاهرة من الكفر، تقول الملائكة لهم: سلام عليكم، تحية خاصة لكم وسلامة من كل آفة، ادخلوا الجنة بما كنتم تعملون من الإيمان بالله والانقياد لأمره.", "isBasmala": false, "translation_en": "Those who are in a wholesome state when the angels take them-will say, \"Peace be upon you; enter Paradise, for what you used to do.\"", "translation_id": "(yaitu) orang-orang yang diwafatkan dalam keadaan baik oleh para malaikat dengan mengatakan (kepada mereka): \"Salaamun'alaikum, masuklah kamu ke dalam surga itu disebabkan apa yang telah kamu kerjakan\".", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 33, "text": "هَلۡ یَنظُرُونَ إِلَّاۤ أَن تَأۡتِیَهُمُ ٱلۡمَلَـٰۤىِٕكَةُ أَوۡ یَأۡتِیَ أَمۡرُ رَبِّكَۚ كَذَ ٰلِكَ فَعَلَ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ ۝٣٣", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "ما ينتظر المشركون إلا أن تأتيهم الملائكة؛ لتقبض أرواحهم وهم على الكفر، أو يأتي أمر الله بعذاب عاجل يهلكهم، كما كذَّب هؤلاء كذَّب الكفار مِن قبلهم، فأهلكهم الله، وما ظلمهم الله بإهلاكهم، وإنزال العذاب بهم، ولكنهم هم الذين كانوا يظلمون أنفسهم بما جعلهم أهلا للعذاب.", "isBasmala": false, "translation_en": "Are they but waiting for the angels to come to them, or for the command of your Lord to arrive? Those before them did likewise. God did not wrong them, but they used to wrong their own souls.", "translation_id": "Tidak ada yang ditunggu-tunggu orang kafir selain dari datangnya para malaikat kepada mereka atau datangnya perintah Tuhanmu. Demikianlah yang telah diperbuat oleh orang-orang (kafir) sebelum mereka. Dan Allah tidak menganiaya mereka, akan tetapi merekalah yang selalu menganiaya diri mereka sendiri,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 34, "text": "فَأَصَابَهُمۡ سَیِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٣٤", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "فنزلت بهم عقوبة ذنوبهم التي عملوها، وأحاط بهم العذاب الذي كانوا يسخرون منه.", "isBasmala": false, "translation_en": "So the evils of their deeds assailed them, and what they used to ridicule engulfed them.", "translation_id": "Maka mereka ditimpa oleh (akibat) kejahatan perbuatan mereka dan mereka diliputi oleh azab yang selalu mereka perolok-olokan.", "manzil": 3, "manzil_display": ""}], "271": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 35, "text": "وَقَالَ ٱلَّذِینَ أَشۡرَكُوا۟ لَوۡ شَاۤءَ ٱللَّهُ مَا عَبَدۡنَا مِن دُونِهِۦ مِن شَیۡءࣲ نَّحۡنُ وَلَاۤ ءَابَاۤؤُنَا وَلَا حَرَّمۡنَا مِن دُونِهِۦ مِن شَیۡءࣲۚ كَذَ ٰلِكَ فَعَلَ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ فَهَلۡ عَلَى ٱلرُّسُلِ إِلَّا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ ۝٣٥", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "وقال المشركون: لو شاء الله أن نعبده وحده ما عبدنا أحدًا غيره، لا نحن ولا آباؤنا مِن قبلنا، ولا حَرَّمَنا شيئًا لم يحرمه، بمثل هذا الاحتجاج الباطل احتج الكفار السابقون، وهم كاذبون؛ فإن الله أمرهم ونهاهم ومكَّنهم من القيام بما كلَّفهم به، وجعل لهم قوة ومشيئة تصدر عنها أفعالهم، فاحتجاجهم بالقضاء والقدر من أبطل الباطل من بعد إنذار الرسل لهم، فليس على الرسل المنذِرين لهم إلا التبليغ الواضح لما كُلِّفوا به.", "isBasmala": false, "translation_en": "The idolaters say, \"Had God willed, we would not have worshiped anything besides Him, neither us, nor our ancestors, nor would we have prohibited anything besides His prohibitions.\" Those before them did likewise. Are the messengers responsible for anything but clear communication?", "translation_id": "Dan berkatalah orang-orang musyrik: \"Jika Allah menghendaki, niscaya kami tidak akan menyembah sesuatu apapun selain Dia, baik kami maupun bapak-bapak kami, dan tidak pula kami mengharamkan sesuatupun tanpa (izin)-Nya\". Demikianlah yang diperbuat orang-orang sebelum mereka; maka tidak ada kewajiban atas para rasul, selain dari menyampaikan (amanat Allah) dengan terang.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 36, "text": "وَلَقَدۡ بَعَثۡنَا فِی كُلِّ أُمَّةࣲ رَّسُولًا أَنِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱجۡتَنِبُوا۟ ٱلطَّـٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ حَقَّتۡ عَلَیۡهِ ٱلضَّلَـٰلَةُۚ فَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُكَذِّبِینَ ۝٣٦", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "ولقد بعثنا في كل أمة سبقَتْ رسولا آمرًا لهم بعبادة الله وطاعته وحده وتَرْكِ عبادة غيره من الشياطين والأوثان والأموات وغير ذلك مما يتخذ من دون الله وليًا، فكان منهم مَن هدى الله، فاتبع المرسلين، ومنهم المعاند الذي اتبع سبيل الغيِّ، فوجبت عليه الضلالة، فلم يوفقه الله. فامشوا في الأرض، وأبصروا بأعينكم كيف كان مآل هؤلاء المكذبين، وماذا حلَّ بهم مِن دمار؛ لتعتبروا؟", "isBasmala": false, "translation_en": "To every community We sent a messenger: \"Worship God, and avoid idolatry.\" Some of them God guided, while others deserved misguidance. So travel through the earth, and see what the fate of the deniers was.", "translation_id": "Dan sungguhnya Kami telah mengutus rasul pada tiap-tiap umat (untuk menyerukan): \"Sembahlah Allah (saja), dan jauhilah Thaghut itu\", maka di antara umat itu ada orang-orang yang diberi petunjuk oleh Allah dan ada pula di antaranya orang-orang yang telah pasti kesesatan baginya. Maka berjalanlah kamu dimuka bumi dan perhatikanlah bagaimana kesudahan orang-orang yang mendustakan (rasul-rasul).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 37, "text": "إِن تَحۡرِصۡ عَلَىٰ هُدَىٰهُمۡ فَإِنَّ ٱللَّهَ لَا یَهۡدِی مَن یُضِلُّۖ وَمَا لَهُم مِّن نَّـٰصِرِینَ ۝٣٧", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "إن تبذل -أيها الرسول- أقصى جهدك لهداية هؤلاء المشركين فاعلم أن الله لا يهدي مَن يضلُّ، وليس لهم من دون الله أحد ينصرهم، ويمنع عنهم عذابه.", "isBasmala": false, "translation_en": "Even though you may be concerned about their guidance, God does not guide those who misguide. And they will have no saviors.", "translation_id": "Jika kamu sangat mengharapkan agar mereka dapat petunjuk, maka sesungguhnya Allah tiada memberi petunjuk kepada orang yang disesatkan-Nya, dan sekali-kali mereka tiada mempunyai penolong.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 38, "text": "وَأَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ لَا یَبۡعَثُ ٱللَّهُ مَن یَمُوتُۚ بَلَىٰ وَعۡدًا عَلَیۡهِ حَقࣰّا وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٣٨", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "وحلف هؤلاء المشركون بالله أيمانًا مغلَّظة أن الله لا يبعث مَن يموت بعدما بَلِيَ وتفرَّق، بلى سيبعثهم الله حتمًا، وعدًا عليه حقًا، ولكن أكثر الناس لا يعلمون قدرة الله على البعث، فينكرونه.", "isBasmala": false, "translation_en": "And they swear by God with their most solemn oaths, \"God will not resurrect anyone who dies.\" Yes indeed, it is a promise binding on Him, but most people do not know.", "translation_id": "Mereka bersumpah dengan nama Allah dengan sumpahnya yang sungguh-sungguh: \"Allah tidak akan akan membangkitkan orang yang mati\". (Tidak demikian), bahkan (pasti Allah akan membangkitnya), sebagai suatu janji yang benar dari Allah, akan tetapi kebanyakan manusia tiada mengetahui,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 39, "text": "لِیُبَیِّنَ لَهُمُ ٱلَّذِی یَخۡتَلِفُونَ فِیهِ وَلِیَعۡلَمَ ٱلَّذِینَ كَفَرُوۤا۟ أَنَّهُمۡ كَانُوا۟ كَـٰذِبِینَ ۝٣٩", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "يبعث الله جميع العباد؛ ليبين لهم حقيقة البعث الذي اختلفوا فيه، ويعلم الكفار المنكرون له أنهم على باطل، وأنهم كاذبون حين حلفوا أنْ لا بعث.", "isBasmala": false, "translation_en": "To clarify for them what they differed about, and for the faithless to know that they were liars.", "translation_id": "agar Allah menjelaskan kepada mereka apa yang mereka perselisihkan itu, agar orang-orang kafir itu mengetahui bahwasanya mereka adalah orang-orang yang berdusta.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 40, "text": "إِنَّمَا قَوۡلُنَا لِشَیۡءٍ إِذَاۤ أَرَدۡنَـٰهُ أَن نَّقُولَ لَهُۥ كُن فَیَكُونُ ۝٤٠", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "إنَّ أمر البعث يسير علينا، فإنَّا إذا أردنا شيئًا فإنما نقول له: \"كن\"، فإذا هو كائن موجود.", "isBasmala": false, "translation_en": "When We intend for something to happen, We say to it, \"Be,\" and it becomes.", "translation_id": "Sesungguhnya perkataan Kami terhadap sesuatu apabila Kami menghendakinya, Kami hanya mengatakan kepadanya: \"kun (jadilah)\", maka jadilah ia.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 41, "text": "وَٱلَّذِینَ هَاجَرُوا۟ فِی ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُوا۟ لَنُبَوِّئَنَّهُمۡ فِی ٱلدُّنۡیَا حَسَنَةࣰۖ وَلَأَجۡرُ ٱلۡـَٔاخِرَةِ أَكۡبَرُۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ ۝٤١", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "والذين تركوا ديارهم مِن أجل الله، فهاجروا بعدما وقع عليهم الظلم، لنسكننهم في الدنيا دارًا حسنة، ولأجر الآخرة أكبر؛ لأن ثوابهم فيها الجنة. لو كان المتخلفون عن الهجرة يعلمون علم يقين ما عند الله من الأجر والثواب للمهاجرين في سبيله، ما تخلَّف منهم أحد عن ذلك.", "isBasmala": false, "translation_en": "Those who emigrate for God's sake after being persecuted, We will settle them in a good place in this world; but the reward of the Hereafter is greater, if they only knew.", "translation_id": "Dan orang-orang yang berhijrah karena Allah sesudah mereka dianiaya, pasti Kami akan memberikan tempat yang bagus kepada mereka di dunia. Dan sesungguhnya pahala di akhirat adalah lebih besar, kalau mereka mengetahui,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 42, "text": "ٱلَّذِینَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ ۝٤٢", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "هؤلاء المهاجرون في سبيل الله هم الذين صبروا على أوامر الله وعن نواهيه وعلى أقداره المؤلمة، وعلى ربهم وحده يعتمدون، فاستحقوا هذه المنزلة العظيمة.", "isBasmala": false, "translation_en": "Those who endure patiently, and in their Lord they put their trust.", "translation_id": "(yaitu) orang-orang yang sabar dan hanya kepada Tuhan saja mereka bertawakkal.", "manzil": 3, "manzil_display": ""}], "272": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 43, "text": "وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالࣰا نُّوحِیۤ إِلَیۡهِمۡۖ فَسۡـَٔلُوۤا۟ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ۝٤٣", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "وما أرسلنا في السابقين قبلك -أيها الرسول- إلا رسلا من الرجال لا من الملائكة، نوحي إليهم، وإن كنتم -يا مشركي قريش- لا تصدقون بذلك فاسألوا أهل الكتب السابقة، يخبروكم أن الأنبياء كانوا بشرًا، إن كنتم لا تعلمون أنهم بشر. والآية عامة في كل مسألة من مسائل الدين، إذا لم يكن عند الإنسان علم منها أن يسأل من يعلمها من العلماء الراسخين في العلم.", "isBasmala": false, "translation_en": "We did not send before you except men whom We inspired. So ask the people of knowledge, if you do not know.", "translation_id": "Dan Kami tidak mengutus sebelum kamu, kecuali orang-orang lelaki yang Kami beri wahyu kepada mereka; maka bertanyalah kepada orang yang mempunyai pengetahuan jika kamu tidak mengetahui,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 44, "text": "بِٱلۡبَیِّنَـٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَاۤ إِلَیۡكَ ٱلذِّكۡرَ لِتُبَیِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَیۡهِمۡ وَلَعَلَّهُمۡ یَتَفَكَّرُونَ ۝٤٤", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "وأَرْسَلْنا الرسل السابقين بالدلائل الواضحة وبالكتب السماوية، وأنزلنا إليك -أيها الرسول- القرآن؛ لتوضح للناس ما خفي مِن معانيه وأحكامه، ولكي يتدبروه ويهتدوا به.", "isBasmala": false, "translation_en": "With the clarifications and the scriptures. And We revealed to you the Reminder, that you may clarify to the people what was revealed to them, and that they may reflect.", "translation_id": "keterangan-keterangan (mukjizat) dan kitab-kitab. Dan Kami turunkan kepadamu Al Quran, agar kamu menerangkan pada umat manusia apa yang telah diturunkan kepada mereka dan supaya mereka memikirkan,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 45, "text": "أَفَأَمِنَ ٱلَّذِینَ مَكَرُوا۟ ٱلسَّیِّـَٔاتِ أَن یَخۡسِفَ ٱللَّهُ بِهِمُ ٱلۡأَرۡضَ أَوۡ یَأۡتِیَهُمُ ٱلۡعَذَابُ مِنۡ حَیۡثُ لَا یَشۡعُرُونَ ۝٤٥", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "أفأمن الكفار المدبِّرون للمكايد أن يخسف الله بهم الأرض كما فعل بقارون، أو يأتيهم العذاب من مكان لا يُحِسُّونه ولا يتوقعونه، أو يأخذهم العذاب، وهم يتقلبون في أسفارهم وتصرفهم؟ فما هم بسابقين الله ولا فائتيه ولا ناجين من عذابه؛ لأنه القوي الذي لا يعجزه شيء، أو يأخذهم الله بنقص من الأموال والأنفس والثمرات، أو في حال خوفهم من أخذه لهم، فإن ربكم لرؤوف بخلقه، رحيم بهم.", "isBasmala": false, "translation_en": "Do those who scheme evils feel secure that God will not cause the earth to cave in with them, or that the punishment will not come upon them from where they do not perceive?", "translation_id": "maka apakah orang-orang yang membuat makar yang jahat itu, merasa aman (dari bencana) ditenggelamkannya bumi oleh Allah bersama mereka, atau datangnya azab kepada mereka dari tempat yang tidak mereka sadari,", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 46, "text": "أَوۡ یَأۡخُذَهُمۡ فِی تَقَلُّبِهِمۡ فَمَا هُم بِمُعۡجِزِینَ ۝٤٦", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "أفأمن الكفار المدبِّرون للمكايد أن يخسف الله بهم الأرض كما فعل بقارون، أو يأتيهم العذاب من مكان لا يُحِسُّونه ولا يتوقعونه، أو يأخذهم العذاب، وهم يتقلبون في أسفارهم وتصرفهم؟ فما هم بسابقين الله ولا فائتيه ولا ناجين من عذابه؛ لأنه القوي الذي لا يعجزه شيء، أو يأخذهم الله بنقص من الأموال والأنفس والثمرات، أو في حال خوفهم من أخذه لهم، فإن ربكم لرؤوف بخلقه، رحيم بهم.", "isBasmala": false, "translation_en": "Or that He will not seize them during their activities? And they will not be able to prevent it.", "translation_id": "atau Allah mengazab mereka diwaktu mereka dalam perjalanan, maka sekali-kali mereka tidak dapat menolak (azab itu),", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 47, "text": "أَوۡ یَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفࣲ فَإِنَّ رَبَّكُمۡ لَرَءُوفࣱ رَّحِیمٌ ۝٤٧", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "أفأمن الكفار المدبِّرون للمكايد أن يخسف الله بهم الأرض كما فعل بقارون، أو يأتيهم العذاب من مكان لا يُحِسُّونه ولا يتوقعونه، أو يأخذهم العذاب، وهم يتقلبون في أسفارهم وتصرفهم؟ فما هم بسابقين الله ولا فائتيه ولا ناجين من عذابه؛ لأنه القوي الذي لا يعجزه شيء، أو يأخذهم الله بنقص من الأموال والأنفس والثمرات، أو في حال خوفهم من أخذه لهم، فإن ربكم لرؤوف بخلقه، رحيم بهم.", "isBasmala": false, "translation_en": "Or that He will not seize them while in dread? Your Lord is Gentle and Merciful.", "translation_id": "atau Allah mengazab mereka dengan berangsur-angsur (sampai binasa). Maka sesungguhnya Tuhanmu adalah Maha Pengasih lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 48, "text": "أَوَ لَمۡ یَرَوۡا۟ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَیۡءࣲ یَتَفَیَّؤُا۟ ظِلَـٰلُهُۥ عَنِ ٱلۡیَمِینِ وَٱلشَّمَاۤىِٕلِ سُجَّدࣰا لِّلَّهِ وَهُمۡ دَ ٰخِرُونَ ۝٤٨", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "أَعَمِيَ هؤلاء الكفار، فلم ينظروا إلى ما خلق الله من شيء له ظل، كالجبال والأشجار، تميل ظلالها تارة يمينًا وتارة شمالا تبعًا لحركة الشمس نهارًا والقمر ليلا كلها خاضعة لعظمة ربها وجلاله، وهي تحت تسخيره وتدبيره وقهره؟", "isBasmala": false, "translation_en": "Have they not observed what God has created? Their shadows revolve from the right and the left, bowing to God as they shrink away.", "translation_id": "Dan apakah mereka tidak memperhatikan segala sesuatu yang telah diciptakan Allah yang bayangannya berbolak-balik ke kanan dan ke kiri dalam keadaan sujud kepada Allah, sedang mereka berendah diri?", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 49, "text": "وَ̅لِ̅لَّ̅هِ̅ ̅یَ̅سۡ̅جُ̅دُ̅ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِ مِن دَاۤبَّةࣲ وَٱلۡمَلَـٰۤىِٕكَةُ وَهُمۡ لَا یَسۡتَكۡبِرُونَ ۝٤٩", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "ولله وحده يسجد كل ما في السموات وما في الأرض مِن دابة، والملائكة يسجدون لله، وهم لا يستكبرون عن عبادته. وخصَّهم بالذكر بعد العموم لفَضْلهم وشرفهم وكثرة عبادتهم.", "isBasmala": false, "translation_en": "To God bows down everything in the heavens and everything on earth-every living creature, and the angels, and without being proud.", "translation_id": "Dan kepada Allah sajalah bersujud segala apa yang berada di langit dan semua makhluk yang melata di bumi dan (juga) para ma]aikat, sedang mereka (malaikat) tidak menyombongkan diri.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 50, "text": "یَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَیَفۡعَلُونَ مَا یُؤۡمَرُونَ ۝٥٠ ۩", "juz": 14, "hizb": "(*¾ ح 27*)", "tafsir": "يخاف الملائكة ربهم الذي هو فوقهم بالذات والقهر وكمال الصفات، ويفعلون ما يُؤْمرون به من طاعة الله. وفي الآية: إثبات صفة العلو والفوقية لله على جميع خلقه، كما يليق بجلاله وكماله.", "isBasmala": false, "translation_en": "They fear their Lord above them, and they do what they are commanded.", "translation_id": "Mereka takut kepada Tuhan mereka yang di atas mereka dan melaksanakan apa yang diperintahkan (kepada mereka).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 51, "text": "۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوۤا۟ إِلَـٰهَیۡنِ ٱثۡنَیۡنِۖ إِنَّمَا هُوَ إِلَـٰهࣱ وَ ٰحِدࣱ فَإِیَّـٰیَ فَٱرۡهَبُونِ ۝٥١", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "وقال الله لعباده: لا تعبدوا إلهين اثنين، إنما معبودكم إله واحد، فخافوني دون سواي.", "isBasmala": false, "translation_en": "God has said: \"Do not take two gods; He is only One God; so fear only Me.\"", "translation_id": "Allah berfirman: \"Janganlah kamu menyembah dua tuhan; sesungguhnya Dialah Tuhan Yang Maha Esa, maka hendaklah kepada-Ku saja kamu takut\".", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 52, "text": "وَلَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَلَهُ ٱلدِّینُ وَاصِبًاۚ أَفَغَیۡرَ ٱللَّهِ تَتَّقُونَ ۝٥٢", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ولله كل ما في السموات والأرض خلقًا وملكًا وعبيدًا، وله وحده العبادة والطاعة والإخلاص دائمًا، أيليق بكم أن تخافوا غير الله وتعبدوه؟", "isBasmala": false, "translation_en": "To Him belongs everything in the heavens and the earth; and to Him obedience is due always. Do you, then, fear anyone other than God?", "translation_id": "Dan kepunyaan-Nya-lah segala apa yang ada di langit dan di bumi, dan untuk-Nya-lah ketaatan itu selama-lamanya. Maka mengapa kamu bertakwa kepada selain Allah?", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 53, "text": "وَمَا بِكُم مِّن نِّعۡمَةࣲ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَیۡهِ تَجۡـَٔرُونَ ۝٥٣", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "وما بكم مِن نعمةِ هدايةٍ، أو صحة جسم، وسَعَة رزقٍ وولد، وغير ذلك، فمِنَ الله وحده، فهو المُنْعِم بها عليكم، ثم إذا نزل بكم السقم والبلاء والقحط فإلى الله وحده تَضِجُّون بالدعاء.", "isBasmala": false, "translation_en": "Whatever blessing you have is from God. And when harm touches you, it is to Him that you groan.", "translation_id": "Dan apa saja nikmat yang ada pada kamu, maka dari Allah-lah (datangnya), dan bila kamu ditimpa oleh kemudharatan, maka hanya kepada-Nya-lah kamu meminta pertolongan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 54, "text": "ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمۡ إِذَا فَرِیقࣱ مِّنكُم بِرَبِّهِمۡ یُشۡرِكُونَ ۝٥٤", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ثم إذا كشف عنكم البلاء والسقم، إذا جماعة منكم بربهم المُنْعِم عليهم بالنجاة يتخذون معه الشركاء والأولياء.", "isBasmala": false, "translation_en": "But when He lifts the harm from you, some of you associate others with their Lord.", "translation_id": "Kemudian apabila Dia telah menghilangkan kemudharatan itu dari pada kamu, tiba-tiba sebahagian dari pada kamu mempersekutukan Tuhannya dengan (yang lain),", "manzil": 3, "manzil_display": ""}], "273": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 55, "text": "لِیَكۡفُرُوا۟ بِمَاۤ ءَاتَیۡنَـٰهُمۡۚ فَتَمَتَّعُوا۟ فَسَوۡفَ تَعۡلَمُونَ ۝٥٥", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ليجحدوا نعمنا عليهم، ومنها كَشْفُ البلاء عنهم، فاستمتعوا بدنياكم، ومصيرها إلى الزوال، فسوف تعلمون عاقبة كفركم وعصيانكم.", "isBasmala": false, "translation_en": "To show ingratitude for what We have given them. Enjoy yourselves. You will soon know.", "translation_id": "Biarlah mereka mengingkari nikmat yang telah Kami berikan kepada mereka; maka bersenang-senanglah kamu. Kelak kamu akan mengetahui (akibatnya).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 56, "text": "وَیَجۡعَلُونَ لِمَا لَا یَعۡلَمُونَ نَصِیبࣰا مِّمَّا رَزَقۡنَـٰهُمۡۗ تَٱللَّهِ لَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَفۡتَرُونَ ۝٥٦", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ومِن قبيح أعمالهم أنهم يجعلون للأصنام التي اتخذوها آلهة، وهي لا تعلم شيئًا ولا تنفع ولا تضر، جزءًا من أموالهم التي رزقهم الله بها تقربًا إليها. تالله لتسألُنَّ يوم القيامة عما كنتم تختلقونه من الكذب على الله.", "isBasmala": false, "translation_en": "And they allocate, to something they do not know, a share of what We have provided for them. By God, you will be questioned about what you have been inventing.", "translation_id": "Dan mereka sediakan untuk berhala-berhala yang mereka tiada mengetahui (kekuasaannya), satu bahagian dari rezeki yang telah Kami berikan kepada mereka. Demi Allah, sesungguhnya kamu akan ditanyai tentang apa yang telah kamu ada-adakan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 57, "text": "وَیَجۡعَلُونَ لِلَّهِ ٱلۡبَنَـٰتِ سُبۡحَـٰنَهُۥ وَلَهُم مَّا یَشۡتَهُونَ ۝٥٧", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ويجعل الكفار لله البنات، فيقولون: الملائكة بنات الله، تنزَّه الله عن قولهم، ويجعلون لأنفسهم ما يحبون من البنين.", "isBasmala": false, "translation_en": "And they attribute to God daughters-exalted is He-and for themselves what they desire.", "translation_id": "Dan mereka menetapkan bagi Allah anak-anak perempuan. Maha Suci Allah, sedang untuk mereka sendiri (mereka tetapkan) apa yang mereka sukai (yaitu anak-anak laki-laki).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 58, "text": "وَإِذَا بُشِّرَ أَحَدُهُم بِٱلۡأُنثَىٰ ظَلَّ وَجۡهُهُۥ مُسۡوَدࣰّا وَهُوَ كَظِیمࣱ ۝٥٨", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "وإذا جاء مَن يخبر أحدهم بولادة أنثى اسودَّ وجهه؛ كراهية لما سمع، وامتلأ غمًّا وحزنًا.", "isBasmala": false, "translation_en": "And when one of them is given news of a female infant, his face darkens, and he chokes with grief.", "translation_id": "Dan apabila seseorang dari mereka diberi kabar dengan (kelahiran) anak perempuan, hitamlah (merah padamlah) mukanya, dan dia sangat marah.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 59, "text": "یَتَوَ ٰرَىٰ مِنَ ٱلۡقَوۡمِ مِن سُوۤءِ مَا بُشِّرَ بِهِۦۤۚ أَیُمۡسِكُهُۥ عَلَىٰ هُونٍ أَمۡ یَدُسُّهُۥ فِی ٱلتُّرَابِۗ أَلَا سَاۤءَ مَا یَحۡكُمُونَ ۝٥٩", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "يستخفي مِن قومه كراهة أن يلقاهم متلبسًا بما ساءه من الحزن والعار؛ بسبب البنت التي وُلِدت له، ومتحيرًا في أمر هذه المولودة: أيبقيها حية على ذلٍّ وهوان، أم يدفنها حية في التراب؟ ألا بئس الحكم الذي حكموه مِن جَعْل البنات لله والذكور لهم.", "isBasmala": false, "translation_en": "He hides from the people because of the bad news given to him. Shall he keep it in humiliation, or bury it in the dust? Evil is the decision they make.", "translation_id": "Ia menyembunyikan dirinya dari orang banyak, disebabkan buruknya berita yang disampaikan kepadanya. Apakah dia akan memeliharanya dengan menanggung kehinaan ataukah akan menguburkannya ke dalam tanah (hidup-hidup)?. Ketahuilah, alangkah buruknya apa yang mereka tetapkan itu.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 60, "text": "لِلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ مَثَلُ ٱلسَّوۡءِۖ وَلِلَّهِ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٦٠", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "للذين لا يؤمنون بالآخرة ولا يعملون لها، الصفة القبيحة من العجز والحاجة والجهل والكفر، ولله الصفات العليا من الكمال والاستغناء عن خلقه، وهو العزيز في ملكه، الحكيم في تدبيره.", "isBasmala": false, "translation_en": "Those who do not believe in the Hereafter set a bad example, while God sets the Highest Example. He is the Mighty, the Wise.", "translation_id": "Orang-orang yang tidak beriman kepada kehidupan akhirat, mempunyai sifat yang buruk; dan Allah mempunyai sifat yang Maha Tinggi; dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 61, "text": "وَلَوۡ یُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَیۡهَا مِن دَاۤبَّةࣲ وَلَـٰكِن یُؤَخِّرُهُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّىۖ فَإِذَا جَاۤءَ أَجَلُهُمۡ لَا یَسۡتَـٔۡخِرُونَ سَاعَةࣰ وَلَا یَسۡتَقۡدِمُونَ ۝٦١", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ولو يؤاخذ الله الناس بكفرهم وافترائهم ما ترك على الأرض مَن يتحرَّك، ولكن يبقيهم إلى وقت محدد هو نهاية آجالهم، فإذا جاء أجلهم لا يتأخرون عنه وقتًا يسيرًا، ولا يتقدمون.", "isBasmala": false, "translation_en": "If God were to hold mankind for their injustices, He would not leave upon it a single creature, but He postpones them until an appointed time. Then, when their time arrives, they will not delay it by one hour, nor will they advance it.", "translation_id": "Jikalau Allah menghukum manusia karena kezalimannya, niscaya tidak akan ditinggalkan-Nya di muka bumi sesuatupun dari makhluk yang melata, tetapi Allah menangguhkan mereka sampai kepada waktu yang ditentukan. Maka apabila telah tiba waktunya (yang ditentukan) bagi mereka, tidaklah mereka dapat mengundurkannya barang sesaatpun dan tidak (pula) mendahulukannya.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 62, "text": "وَیَجۡعَلُونَ لِلَّهِ مَا یَكۡرَهُونَۚ وَتَصِفُ أَلۡسِنَتُهُمُ ٱلۡكَذِبَ أَنَّ لَهُمُ ٱلۡحُسۡنَىٰۚ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفۡرَطُونَ ۝٦٢", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ومن قبائحهم: أنهم يجعلون لله ما يكرهونه لأنفسهم من البنات، وتقول ألسنتهم كذبًا: إن لهم حسن العاقبة، حقًا أن لهم النار، وأنهم فيها مَتْروكون مَنْسيون.", "isBasmala": false, "translation_en": "And they attribute to God what they themselves dislike, while their tongues utter the lie that theirs is the goodness. Without a doubt, for them is the Fire, and they will be neglected.", "translation_id": "Dan mereka menetapkan bagi Allah apa yang mereka sendiri membencinya, dan lidah mereka mengucapkan kedustaan, yaitu bahwa sesungguhnya merekalah yang akan mendapat kebaikan. Tiadalah diragukan bahwa nerakalah bagi mereka, dan sesungguhnya mereka segera dimasukkan (ke dalamnya).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 63, "text": "تَٱللَّهِ لَقَدۡ أَرۡسَلۡنَاۤ إِلَىٰۤ أُمَمࣲ مِّن قَبۡلِكَ فَزَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ أَعۡمَـٰلَهُمۡ فَهُوَ وَلِیُّهُمُ ٱلۡیَوۡمَ وَلَهُمۡ عَذَابٌ أَلِیمࣱ ۝٦٣", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "تالله لقد أرسلنا رسلا إلى أمم مِن قبلك -أيها الرسول- فحسَّن لهم الشيطان ما عملوه من الكفر والتكذيب وعبادة غير الله، فهو متولٍّ إغواءهم في الدنيا، ولهم في الآخرة عذاب أليم موجع.", "isBasmala": false, "translation_en": "By God, We sent messengers to communities before you, but Satan made their deeds appear alluring to them. He is their master today, and they will have a painful punishment.", "translation_id": "Demi Allah, sesungguhnya Kami telah mengutus rasul-rasul Kami kepada umat-umat sebelum kamu, tetapi syaitan menjadikan umat-umat itu memandang baik perbuatan mereka (yang buruk), maka syaitan menjadi pemimpin mereka di hari itu dan bagi mereka azab yang sangat pedih.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 64, "text": "وَمَاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡكِتَـٰبَ إِلَّا لِتُبَیِّنَ لَهُمُ ٱلَّذِی ٱخۡتَلَفُوا۟ فِیهِ وَهُدࣰى وَرَحۡمَةࣰ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝٦٤", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "وما أنزلنا عليك القرآن -أيها الرسول- إلا لتوضح للناس ما اختلفوا فيه من الدين والأحكام؛ لتقوم الحجة عليهم ببيانك ورشدًا ورحمة لقوم يؤمنون.", "isBasmala": false, "translation_en": "We revealed to you the Scripture only to clarify for them what they differ about, and guidance and mercy for people who believe.", "translation_id": "Dan Kami tidak menurunkan kepadamu Al-Kitab (Al Quran) ini, melainkan agar kamu dapat menjelaskan kepada mereka apa yang mereka perselisihkan itu dan menjadi petunjuk dan rahmat bagi kaum yang beriman.", "manzil": 3, "manzil_display": ""}], "274": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 65, "text": "وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَحۡیَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۤۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَسۡمَعُونَ ۝٦٥", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "والله أنزل من السحاب مطرًا، فأخرج به النبات من الأرض بعد أن كانت قاحلة يابسة، إن في إنزال المطر وإنبات النبات لَدليلا على قدرة الله على البعث وعلى الوحدانية، لقوم يسمعون، ويتدبرون، ويطيعون الله، ويتقونه.", "isBasmala": false, "translation_en": "God sends down water from the sky, with which He revives the earth after its death. In this is a sign for people who listen.", "translation_id": "Dan Allah menurunkan dari langit air (hujan) dan dengan air itu dihidupkan-Nya bumi sesudah matinya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Tuhan) bagi orang-orang yang mendengarkan (pelajaran).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 66, "text": "وَإِنَّ لَكُمۡ فِی ٱلۡأَنۡعَـٰمِ لَعِبۡرَةࣰۖ نُّسۡقِیكُم مِّمَّا فِی بُطُونِهِۦ مِنۢ بَیۡنِ فَرۡثࣲ وَدَمࣲ لَّبَنًا خَالِصࣰا سَاۤىِٕغࣰا لِّلشَّـٰرِبِینَ ۝٦٦", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "وإن لكم -أيها الناس- في الأنعام -وهي الإبل والبقر والغنم- لَعظة، فقد شاهدتم أننا نسقيكم من ضروعها لبنًا خارجًا من بين فَرْث -وهو ما في الكَرِش- وبين دم خالصًا من كل الشوائب، لذيذًا لا يَغَصُّ به مَن شَرِبَه.", "isBasmala": false, "translation_en": "And there is a lesson for you in cattle: We give you a drink from their bellies, from between waste and blood, pure milk, refreshing to the drinkers.", "translation_id": "Dan sesungguhnya pada binatang ternak itu benar-benar terdapat pelajaran bagi kamu. Kami memberimu minum dari pada apa yang berada dalam perutnya (berupa) susu yang bersih antara tahi dan darah, yang mudah ditelan bagi orang-orang yang meminumnya.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 67, "text": "وَمِن ثَمَرَ ٰتِ ٱلنَّخِیلِ وَٱلۡأَعۡنَـٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرࣰا وَرِزۡقًا حَسَنًاۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَعۡقِلُونَ ۝٦٧", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ومِن نِعَمنا عليكم ما تأخذونه من ثمرات النخيل والأعناب، فتجعلونه خمرًا مُسْكِرًا -وهذا قبل تحريمها- وطعامًا طيبًا. إن فيما ذكر لَدليلا على قدرة الله لِقومٍ يعقلون البراهين فيعتبرون بها.", "isBasmala": false, "translation_en": "And from the fruits of date-palms and grapevines, you derive sugar and wholesome food. In this is a sign for people who understand.", "translation_id": "Dan dari buah korma dan anggur, kamu buat minimuman yang memabukkan dan rezeki yang baik. Sesunggguhnya pada yang demikian itu benar-benar terdapat tanda (kebesaran Allah) bagi orang yang memikirkan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 68, "text": "وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِی مِنَ ٱلۡجِبَالِ بُیُوتࣰا وَمِنَ ٱلشَّجَرِ وَمِمَّا یَعۡرِشُونَ ۝٦٨", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "وألْهَمَ ربك -أيها النبي- النحل بأن اجعلي لك بيوتًا في الجبال، وفي الشجر، وفيما يبني الناس من البيوت والسُّقُف.", "isBasmala": false, "translation_en": "And your Lord inspired the bee: \"Set up hives in the mountains, and in the trees, and in what they construct.\"", "translation_id": "Dan Tuhanmu mewahyukan kepada lebah: \"Buatlah sarang-sarang di bukit-bukit, di pohon-pohon kayu, dan di tempat-tempat yang dibikin manusia\",", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 69, "text": "ثُمَّ كُلِی مِن كُلِّ ٱلثَّمَرَ ٰتِ فَٱسۡلُكِی سُبُلَ رَبِّكِ ذُلُلࣰاۚ یَخۡرُجُ مِنۢ بُطُونِهَا شَرَابࣱ مُّخۡتَلِفٌ أَلۡوَ ٰنُهُۥ فِیهِ شِفَاۤءࣱ لِّلنَّاسِۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَتَفَكَّرُونَ ۝٦٩", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ثم كُلي مِن كل ثمرة تشتهينها، فاسلكي طرق ربك مذللة لك؛ لطلب الرزق في الجبال وخلال الشجر، وقد جعلها سهلة عليكِ، لا تضلي في العَوْد إليها وإن بَعُدَتْ. يخرج من بطون النحل عسل مختلف الألوان مِن بياض وصفرة وحمرة وغير ذلك، فيه شفاء للناس من الأمراض. إن فيما يصنعه النحل لَدلالة قوية على قدرة خالقها لقوم يتفكرون، فيعتبرون.", "isBasmala": false, "translation_en": "Then eat of all the fruits, and go along the pathways of your Lord, with precision. From their bellies emerges a fluid of diverse colors, containing healing for the people. Surely in this is a sign for people who reflect.", "translation_id": "kemudian makanlah dari tiap-tiap (macam) buah-buahan dan tempuhlah jalan Tuhanmu yang telah dimudahkan (bagimu). Dari perut lebah itu ke luar minuman (madu) yang bermacam-macam warnanya, di dalamnya terdapat obat yang menyembuhkan bagi manusia. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda (kebesaran Tuhan) bagi orang-orang yang memikirkan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 70, "text": "وَٱللَّهُ خَلَقَكُمۡ ثُمَّ یَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن یُرَدُّ إِلَىٰۤ أَرۡذَلِ ٱلۡعُمُرِ لِكَیۡ لَا یَعۡلَمَ بَعۡدَ عِلۡمࣲ شَیۡـًٔاۚ إِنَّ ٱللَّهَ عَلِیمࣱ قَدِیرࣱ ۝٧٠", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "والله سجانه وتعالى خلقكم ثم يميتكم في نهاية أعماركم، ومنكم مَن يصير إلى أردأ العمر وهو الهرم، كما كان في طفولته لا يعلم شيئًا مما كان يعلمه، إن الله عليم قدير، أحاط علمه وقدرته بكل شيء، فالله الذي ردَّ الإنسان إلى هذه الحالة قادر على أن يميته، ثم يبعثه.", "isBasmala": false, "translation_en": "God created you; then He takes you away. Some of you will be brought back to the worst age, so that he will no longer know anything, after having acquired knowledge. God is Omniscient and Omnipotent.", "translation_id": "Allah menciptakan kamu, kemudian mewafatkan kamu; dan di antara kamu ada yang dikembalikan kepada umur yang paling lemah (pikun), supaya dia tidak mengetahui lagi sesuatupun yang pernah diketahuinya. Sesungguhnya Allah Maha Mengetahui lagi Maha Kuasa.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 71, "text": "وَٱللَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضࣲ فِی ٱلرِّزۡقِۚ فَمَا ٱلَّذِینَ فُضِّلُوا۟ بِرَاۤدِّی رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ فَهُمۡ فِیهِ سَوَاۤءٌۚ أَفَبِنِعۡمَةِ ٱللَّهِ یَجۡحَدُونَ ۝٧١", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "والله فَضَّل بعضكم على بعض فيما أعطاكم في الدنيا من الرزق، فمنكم غني ومنكم فقير، ومنكم مالك ومنكم مملوك، فلا يعطي المالكون مملوكيهم مما أعطاهم الله ما يصيرون به شركاء لهم متساوين معهم في المال، فإذا لم يرضوا بذلك لأنفسهم، فلماذا رضوا أن يجعلوا لله شركاء من عبيده؟ إن هذا لَمن أعظم الظلم والجحود لِنعم الله عز وجل.", "isBasmala": false, "translation_en": "God has favored some of you over others in livelihood. Those who are favored would not give their properties to their servants, to the extent of making them partners in it. Will they then renounce God's blessings?", "translation_id": "Dan Allah melebihkan sebahagian kamu dari sebagian yang lain dalam hal rezeki, tetapi orang-orang yang dilebihkan (rezekinya itu) tidak mau memberikan rezeki mereka kepada budak-budak yang mereka miliki, agar mereka sama (merasakan) rezeki itu. Maka mengapa mereka mengingkari nikmat Allah?.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 72, "text": "وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَ ٰجࣰا وَجَعَلَ لَكُم مِّنۡ أَزۡوَ ٰجِكُم بَنِینَ وَحَفَدَةࣰ وَرَزَقَكُم مِّنَ ٱلطَّیِّبَـٰتِۚ أَفَبِٱلۡبَـٰطِلِ یُؤۡمِنُونَ وَبِنِعۡمَتِ ٱللَّهِ هُمۡ یَكۡفُرُونَ ۝٧٢", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "والله سبحانه جعل مِن جنسكم أزواجا؛ لتستريح نفوسكم معهن، وجعل لكم منهن الأبناء ومِن نسلهنَّ الأحفاد، ورزقكم من الأطعمة الطيبة من الثمار والحبوب واللحوم وغير ذلك. أفبالباطل من ألوهية شركائهم يؤمنون، وبنعم الله التي لا تحصى يجحدون، ولا يشكرون له بإفراده جل وعلا بالعبادة؟", "isBasmala": false, "translation_en": "God has given you mates from among yourselves; and has produced for you, from your mates, children and grandchildren; and has provided you with good things. Will they then believe in falsehood, and refuse God's favors?", "translation_id": "Allah menjadikan bagi kamu isteri-isteri dari jenis kamu sendiri dan menjadikan bagimu dari isteri-isteri kamu itu, anak-anak dan cucu-cucu, dan memberimu rezeki dari yang baik-baik. Maka mengapakah mereka beriman kepada yang bathil dan mengingkari nikmat Allah?\"", "manzil": 3, "manzil_display": ""}], "275": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 73, "text": "وَیَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَمۡلِكُ لَهُمۡ رِزۡقࣰا مِّنَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ شَیۡـࣰٔا وَلَا یَسۡتَطِیعُونَ ۝٧٣", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "ويعبد المشركون أصنامًا لا تملك أن تعطيهم شيئًا من الرزق من السماء كالمطر، ولا من الأرض كالزرع، فهم لا يملكون شيئًا، ولا يتأتى منهم أن يملكوه؛ لأنهم لا يقدرون.", "isBasmala": false, "translation_en": "And yet they serve besides God what possesses no provisions for them in the heavens, nor on earth, nor are they capable.", "translation_id": "Dan mereka menyembah selain Allah, sesuatu yang tidak dapat memberikan rezeki kepada mereka sedikitpun dari langit dan bumi, dan tidak berkuasa (sedikit juapun).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 74, "text": "فَلَا تَضۡرِبُوا۟ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ۝٧٤", "juz": 14, "hizb": "(* ح 28*)", "tafsir": "وإذا عَلِمتم أن الأصنام والأوثان لا تنفع، فلا تجعلوا -أيها الناس- لله أشباهًا مماثلين له مِن خَلْقه تشركونهم معه في العبادة. إن الله يعلم ما تفعلون، وأنتم غافلون لا تعلمون خطأكم وسوء عاقبتكم.", "isBasmala": false, "translation_en": "So do not cite the examples for God. God knows, and you do not know.", "translation_id": "Maka janganlah kamu mengadakan sekutu-sekutu bagi Allah. Sesungguhnya Allah mengetahui, sedang kamu tidak mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 75, "text": "۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدࣰا مَّمۡلُوكࣰا لَّا یَقۡدِرُ عَلَىٰ شَیۡءࣲ وَمَن رَّزَقۡنَـٰهُ مِنَّا رِزۡقًا حَسَنࣰا فَهُوَ یُنفِقُ مِنۡهُ سِرࣰّا وَجَهۡرًاۖ هَلۡ یَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ ۝٧٥", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "ضرب الله مثلا بيَّن فيه فساد عقيدة أهل الشرك: رجلا مملوكًا عاجزًا عن التصرف لا يملك شيئًا، ورجلا آخر حرًا، له مال حلال رزَقَه الله به، يملك التصرف فيه، ويعطي منه في الخفاء والعلن، فهل يقول عاقل بالتساوي بين الرجلين؟ فكذلك الله الخالق المالك المتصرف لا يستوي مع خلقه وعبيده، فكيف تُسَوُّون بينهما؟ الحمد لله وحده، فهو المستحق للحمد والثناء، بل أكثر المشركين لا يعلمون أن الحمد والنعمة لله، وأنه وحده المستحق للعبادة.", "isBasmala": false, "translation_en": "God cites the example of a bonded slave, who has no power over anything; and someone to whom We have given plentiful provision, from which he gives secretly and openly. Are they equal in comparison? All praise belongs to God, but most of them do not know.", "translation_id": "Allah membuat perumpamaan dengan seorang hamba sahaya yang dimiliki yang tidak dapat bertindak terhadap sesuatupun dan seorang yang Kami beri rezeki yang baik dari Kami, lalu dia menafkahkan sebagian dari rezeki itu secara sembunyi dan secara terang-terangan, adakah mereka itu sama? Segala puji hanya bagi Allah, tetapi kebanyakan mereka tiada mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 76, "text": "وَضَرَبَ ٱللَّهُ مَثَلࣰا رَّجُلَیۡنِ أَحَدُهُمَاۤ أَبۡكَمُ لَا یَقۡدِرُ عَلَىٰ شَیۡءࣲ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ أَیۡنَمَا یُوَجِّههُّ لَا یَأۡتِ بِخَیۡرٍ هَلۡ یَسۡتَوِی هُوَ وَمَن یَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٧٦", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "وضرب الله مثلا آخر لبطلان الشرك رجلين: أحدهما أخرس أصم لا يَفْهَم ولا يُفْهِم، لا يقدر على منفعة نفسه أو غيره، وهو عبء ثقيل على مَن يَلي أمره ويعوله، إذا أرسله لأمر يقضيه لا ينجح، ولا يعود عليه بخير، ورجل آخر سليم الحواس، ينفع نفسه وغيره، يأمر بالإنصاف، وهو على طريق واضح لا عوج فيه، فهل يستوي الرجلان في نظر العقلاء؟ فكيف تُسَوُّون بين الصنم الأبكم الأصمِّ وبين الله القادر المنعم بكل خير؟", "isBasmala": false, "translation_en": "And God cites the example of two men: one of them dumb, unable to do anything, and is a burden on his master; whichever way he directs him, he achieves nothing good. Is he equal to him who commands justice, and is on a straight path?", "translation_id": "Dan Allah membuat (pula) perumpamaan: dua orang lelaki yang seorang bisu, tidak dapat berbuat sesuatupun dan dia menjadi beban atas penanggungnya, ke mana saja dia disuruh oleh penanggungnya itu, dia tidak dapat mendatangkan suatu kebajikanpun. Samakah orang itu dengan orang yang menyuruh berbuat keadilan, dan dia berada pula di atas jalan yang lurus?", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 77, "text": "وَلِلَّهِ غَیۡبُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَمَاۤ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ ٱلۡبَصَرِ أَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٧٧", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "ولله سبحانه وتعالى عِلْمُ ما غاب في السموات والأرض، وما شأن القيامة في سرعة مجيئها إلا كنظرة سريعة بالبصر، بل هو أسرع من ذلك. إن الله على كل شيء قدير.", "isBasmala": false, "translation_en": "To God belongs the unseen of the heavens and the earth. The coming of the Hour is only as the twinkling of the eye, or even nearer. God has power over everything.", "translation_id": "Dan kepunyaan Allah-lah segala apa yang tersembunyi di langit dan di bumi. Tidak adalah kejadian kiamat itu, melainkan seperti sekejap mata atau lebih cepat (lagi). Sesungguhnya Allah Maha Kuasa atas segala sesuatu.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 78, "text": "وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَـٰتِكُمۡ لَا تَعۡلَمُونَ شَیۡـࣰٔا وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ ۝٧٨", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "والله سبحانه وتعالى أخرجكم مِن بطون أمهاتكم بعد مدة الحمل، لا تدركون شيئًا مما حولكم، وجعل لكم وسائل الإدراك من السمع والبصر والقلوب؛ لعلكم تشكرون لله تعالى على تلك النعم، وتفردونه عز وجل بالعبادة.", "isBasmala": false, "translation_en": "God brought you out of your mothers' wombs, not knowing anything; and He gave you the hearing, and the eyesight, and the brains; that you may give thanks.", "translation_id": "Dan Allah mengeluarkan kamu dari perut ibumu dalam keadaan tidak mengetahui sesuatupun, dan Dia memberi kamu pendengaran, penglihatan dan hati, agar kamu bersyukur.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 79, "text": "أَلَمۡ یَرَوۡا۟ إِلَى ٱلطَّیۡرِ مُسَخَّرَ ٰتࣲ فِی جَوِّ ٱلسَّمَاۤءِ مَا یُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝٧٩", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "ألم ينظر المشركون إلى الطير مذللات للطيران في الهواء بين السماء والأرض بأمر الله؟ ما يمسكهن عن الوقوع إلا هو سبحانه بما خَلَقه لها، وأقدرها عليه. إن في ذلك التذليل والإمساك لَدلالات لقوم يؤمنون بما يرونه من الأدلة على قدرة الله.", "isBasmala": false, "translation_en": "Have they not seen the birds, flying in the midst of the sky? None sustains them except God. In this are signs for people who believe.", "translation_id": "Tidakkah mereka memperhatikan burung-burung yang dimudahkan terbang diangkasa bebas. Tidak ada yang menahannya selain daripada Allah. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kebesaran Tuhan) bagi orang-orang yang beriman.", "manzil": 3, "manzil_display": ""}], "276": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 80, "text": "وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُیُوتِكُمۡ سَكَنࣰا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلۡأَنۡعَـٰمِ بُیُوتࣰا تَسۡتَخِفُّونَهَا یَوۡمَ ظَعۡنِكُمۡ وَیَوۡمَ إِقَامَتِكُمۡ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَاۤ أَثَـٰثࣰا وَمَتَـٰعًا إِلَىٰ حِینࣲ ۝٨٠", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "والله سبحانه جعل لكم من بيوتكم راحة واستقرارًا مع أهلكم، وأنتم مقيمون في الحضر، وجعل لكم في سفركم خيامًا وقبابًا من جلود الأنعام، يَخِفُّ عليكم حِمْلها وقت تَرْحالكم، ويخف عليكم نَصْبها وقت إقامتكم بعد التَّرْحال، وجعل لكم من أصواف الغنم، وأوبار الإبل، وأشعار المعز أثاثًا لكم من أكسية وألبسة وأغطية وفرش وزينة، تتمتعون بها إلى أجل مسمَّى ووقت معلوم.", "isBasmala": false, "translation_en": "And God has given you in your homes habitats for you, and has provided for you out of the hides of livestock portable homes for you, so you can use them when you travel, and when you camp; and from their wool, and fur, and hair, furnishings and comfort for a while.", "translation_id": "Dan Allah menjadikan bagimu rumah-rumahmu sebagai tempat tinggal dan Dia menjadikan bagi kamu rumah-rumah (kemah-kemah) dari kulit binatang ternak yang kamu merasa ringan (membawa)nya di waktu kamu berjalan dan waktu kamu bermukim dan (dijadikan-Nya pula) dari bulu domba, bulu unta dan bulu kambing, alat-alat rumah tangga dan perhiasan (yang kamu pakai) sampai waktu (tertentu).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 81, "text": "وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَـٰلࣰا وَجَعَلَ لَكُم مِّنَ ٱلۡجِبَالِ أَكۡنَـٰنࣰا وَجَعَلَ لَكُمۡ سَرَ ٰبِیلَ تَقِیكُمُ ٱلۡحَرَّ وَسَرَ ٰبِیلَ تَقِیكُم بَأۡسَكُمۡۚ كَذَ ٰلِكَ یُتِمُّ نِعۡمَتَهُۥ عَلَیۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ ۝٨١", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "والله جعل لكم ما تستظلُّون به من الأشجار وغيرها، وجعل لكم في الجبال من المغارات والكهوف أماكن تلجؤون إليها عند الحاجة، وجعل لكم ثيابًا من القطن والصوف وغيرهما، تحفظكم من الحر والبرد، وجعل لكم من الحديد ما يردُّ عنكم الطعن والأذى في حروبكم، كما أنعم الله عليكم بهذه النعم يتمُّ نعمته عليكم ببيان الدين الحق؛ لتستسلموا لأمر الله وحده، ولا تشركوا به شيئًا في عبادته.", "isBasmala": false, "translation_en": "And God has made for you shade out of what He has created, and has given you resorts in the mountains, and has given you garments to protect you from the heat, and garments to protect you from your violence. Thus He completes His blessings upon you, so that you may submit.", "translation_id": "Dan Allah menjadikan bagimu tempat bernaung dari apa yang telah Dia ciptakan, dan Dia jadikan bagimu tempat-tempat tinggal di gunung-gunung, dan Dia jadikan bagimu pakaian yang memeliharamu dari panas dan pakaian (baju besi) yang memelihara kamu dalam peperangan. Demikianlah Allah menyempurnakan nikmat-Nya atasmu agar kamu berserah diri (kepada-Nya).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 82, "text": "فَإِن تَوَلَّوۡا۟ فَإِنَّمَا عَلَیۡكَ ٱلۡبَلَـٰغُ ٱلۡمُبِینُ ۝٨٢", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "فإن أعرضوا عنك -أيها الرسول- بعدما رأوا من الآيات فلا تحزن، فما عليك إلا البلاغ الواضح لما أُرْسِلْتَ به، وأما الهداية فإلينا.", "isBasmala": false, "translation_en": "But if they turn away, your only duty is clear communication.", "translation_id": "Jika mereka tetap berpaling, maka sesungguhnya kewajiban yang dibebankan atasmu (Muhammad) hanyalah menyampaikan (amanat Allah) dengan terang.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 83, "text": "یَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ یُنكِرُونَهَا وَأَكۡثَرُهُمُ ٱلۡكَـٰفِرُونَ ۝٨٣", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "يعرف هؤلاء المشركون نعمة الله عليهم بإرسال محمد صلى الله عليه وسلم إليهم، ثم يجحدون نبوته، وأكثر قومه الجاحدون لنبوته، لا المقرون بها.", "isBasmala": false, "translation_en": "They recognize God's blessing, but then deny it, as most of them are ungrateful.", "translation_id": "Mereka mengetahui nikmat Allah, kemudian mereka mengingkarinya dan kebanyakan mereka adalah orang-orang yang kafir.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 84, "text": "وَیَوۡمَ نَبۡعَثُ مِن كُلِّ أُمَّةࣲ شَهِیدࣰا ثُمَّ لَا یُؤۡذَنُ لِلَّذِینَ كَفَرُوا۟ وَلَا هُمۡ یُسۡتَعۡتَبُونَ ۝٨٤", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "واذكر لهم -أيها الرسول- ما يكون يوم القيامة، حين نبعث من كل أمة رسولها شاهدًا على إيمان من آمن منها، وكُفْر مَن كَفَر، ثم لا يُؤذن للذين كفروا بالاعتذار عما وقع منهم، ولا يُطْلب منهم إرضاءُ ربهم بالتوبة والعمل الصالح، فقد مضى أوان ذلك.", "isBasmala": false, "translation_en": "On the Day when We raise up a witness from every community-those who disbelieved will not be permitted, nor will they be excused.", "translation_id": "Dan (ingatlah) akan hari (ketika) Kami bangkitkan dari tiap-tiap umat seorang saksi (rasul), kemudian tidak diizinkan kepada orang-orang yang kafir (untuk membela diri) dan tidak (pula) mereka dibolehkan meminta maaf.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 85, "text": "وَإِذَا رَءَا ٱلَّذِینَ ظَلَمُوا۟ ٱلۡعَذَابَ فَلَا یُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ یُنظَرُونَ ۝٨٥", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "وإذا شاهد الذين كفروا عذاب الله في الآخرة فلا يخفف عنهم منه شيء، ولا يُمْهلون، ولا يؤخر عذابهم.", "isBasmala": false, "translation_en": "When those who did wrong see the punishment, it will not be lightened for them, nor will they be reprieved.", "translation_id": "Dan apabila orang-orang zalim telah menyaksikan azab, maka tidaklah diringankan azab bagi mereka dan tidak puIa mereka diberi tangguh.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 86, "text": "وَإِذَا رَءَا ٱلَّذِینَ أَشۡرَكُوا۟ شُرَكَاۤءَهُمۡ قَالُوا۟ رَبَّنَا هَـٰۤؤُلَاۤءِ شُرَكَاۤؤُنَا ٱلَّذِینَ كُنَّا نَدۡعُوا۟ مِن دُونِكَۖ فَأَلۡقَوۡا۟ إِلَیۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَـٰذِبُونَ ۝٨٦", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "وإذا أبصر المشركون يوم القيامة آلهتهم التي عبدوها مع الله، قالوا: ربنا هؤلاء شركاؤنا الذين كنا نعبدهم مِن دونك، فنطقَتِ الآلهة بتكذيب مَن عبدوها، وقالت: إنكم -أيها المشركون- لَكاذبون، حين جعلتمونا شركاء لله وعبدتمونا معه، فلم نأمركم بذلك، ولا زعمنا أننا مستحقون للألوهية، فاللوم عليكم.", "isBasmala": false, "translation_en": "And when the idolaters see their associates, they will say, \"Our Lord, these are our associates whom we used to invoke besides You.\" They will strike back at them with the saying, \"Surely you are liars.\"", "translation_id": "Dan apabila orang-orang yang mempersekutukan (Allah) melihat sekutu-sekutu mereka, mereka berkata: \"Ya Tuhan kami mereka inilah sekutu-sekutu kami yang dahulu kami sembah selain dari Engkau\". Lalu sekutu-sekutu mereka mengatakan kepada mereka: \"Sesungguhnya kamu benar-benar orang-orang yang dusta\".", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 87, "text": "وَأَلۡقَوۡا۟ إِلَى ٱللَّهِ یَوۡمَىِٕذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ ۝٨٧", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "وأظهر المشركون الاستسلام والخضوع لله يوم القيامة، وغاب عنهم ما كانوا يختلقونه من الأكاذيب، وأن آلهتهم تشفع لهم.", "isBasmala": false, "translation_en": "On that Day they will offer their submission to God, and what they had invented will abandon them.", "translation_id": "Dan mereka menyatakan ketundukannya kepada Allah pada hari itu dan hilanglah dari mereka apa yang selalu mereka ada-adakan.", "manzil": 3, "manzil_display": ""}], "277": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 88, "text": "ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ زِدۡنَـٰهُمۡ عَذَابࣰا فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُوا۟ یُفۡسِدُونَ ۝٨٨", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "الذين جحدوا وحدانية الله ونبوتك -أيها الرسول- وكذَّبوك، ومنعوا غيرهم عن الإيمان بالله ورسوله، زدناهم عذابا على كفرهم وعذابًا على صدِّهم الناس عن اتباع الحق؛ وهذا بسبب تعمُّدهم الإفساد وإضلال العباد بالكفر والمعصية.", "isBasmala": false, "translation_en": "Those who disbelieve and obstruct from God's path-We will add punishment to their punishment, on account of the mischief they used to make.", "translation_id": "Orang-orang yang kafir dan menghalangi (manusia) dari jalan Allah, Kami tambahkan kepada mereka siksaan di atas siksaan disebabkan mereka selalu berbuat kerusakan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 89, "text": "وَیَوۡمَ نَبۡعَثُ فِی كُلِّ أُمَّةࣲ شَهِیدًا عَلَیۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِیدًا عَلَىٰ هَـٰۤؤُلَاۤءِۚ وَنَزَّلۡنَا عَلَیۡكَ ٱلۡكِتَـٰبَ تِبۡیَـٰنࣰا لِّكُلِّ شَیۡءࣲ وَهُدࣰى وَرَحۡمَةࣰ وَبُشۡرَىٰ لِلۡمُسۡلِمِینَ ۝٨٩", "juz": 14, "hizb": "(*¼ ح 28*)", "tafsir": "واذكر -أيها الرسول- حين نبعث يوم القيامة في كل أمة من الأمم شهيدًا عليهم، هو الرسول الذي بعثه الله إليهم من أنفسهم وبلسانهم، وجئنا بك -أيها الرسول- شهيدًا على أمتك، وقد نَزَّلْنا عليك القرآن توضيحًا لكل أمر يحتاج إلى بيان، كأحكام الحلال والحرام، والثواب والعقاب، وغير ذلك، وليكون هداية من الضلال، ورحمة لمن صدَّق وعمل به، وبشارة طيبة للمؤمنين بحسن مصيرهم.", "isBasmala": false, "translation_en": "On the Day when We raise in every community a witness against them, from among them, and bring you as a witness against these. We have revealed to you the Book, as an explanation of all things, and guidance, and mercy and good news for those who submit.", "translation_id": "(Dan ingatlah) akan hari (ketika) Kami bangkitkan pada tiap-tiap umat seorang saksi atas mereka dari mereka sendiri dan Kami datangkan kamu (Muhammad) menjadi saksi atas seluruh umat manusia. Dan Kami turunkan kepadamu Al Kitab (Al Quran) untuk menjelaskan segala sesuatu dan petunjuk serta rahmat dan kabar gembira bagi orang-orang yang berserah diri.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 90, "text": "۞ إِنَّ ٱللَّهَ یَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَـٰنِ وَإِیتَاۤىِٕ ذِی ٱلۡقُرۡبَىٰ وَیَنۡهَىٰ عَنِ ٱلۡفَحۡشَاۤءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡیِۚ یَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ ۝٩٠", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "إن الله سبحانه وتعالى يأمر عباده في هذا القرآن بالعدل والإنصاف في حقه بتوحيده وعدم الإشراك به، وفي حق عباده بإعطاء كل ذي حق حقه، ويأمر بالإحسان في حقه بعبادته وأداء فرائضه على الوجه المشروع، وإلى الخلق في الأقوال والأفعال، ويأمر بإعطاء ذوي القرابة ما به صلتهم وبرُّهم، وينهى عن كل ما قَبُحَ قولا أو عملا وعما ينكره الشرع ولا يرضاه من الكفر والمعاصي، وعن ظلم الناس والتعدي عليهم، والله -بهذا الأمر وهذا النهي- يَعِظكم ويذكِّركم العواقب؛ لكي تتذكروا أوامر الله وتنتفعوا بها.", "isBasmala": false, "translation_en": "God commands justice, and goodness, and generosity towards relatives. And He forbids immorality, and injustice, and oppression. He advises you, so that you may take heed.", "translation_id": "Sesungguhnya Allah menyuruh (kamu) berlaku adil dan berbuat kebajikan, memberi kepada kaum kerabat, dan Allah melarang dari perbuatan keji, kemungkaran dan permusuhan. Dia memberi pengajaran kepadamu agar kamu dapat mengambil pelajaran.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 91, "text": "وَأَوۡفُوا۟ بِعَهۡدِ ٱللَّهِ إِذَا عَـٰهَدتُّمۡ وَلَا تَنقُضُوا۟ ٱلۡأَیۡمَـٰنَ بَعۡدَ تَوۡكِیدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَیۡكُمۡ كَفِیلًاۚ إِنَّ ٱللَّهَ یَعۡلَمُ مَا تَفۡعَلُونَ ۝٩١", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "والتزموا الوفاء بكل عهد أوجبتموه على أنفسكم بينكم وبين الله -تعالى- أو بينكم وبين الناس فيما لا يخالف كتاب الله وسنة نبيه، ولا ترجعوا في الأيمان بعد أن أكَّدْتموها، وقد جعلتم الله عليكم كفيلا وضامنًا حين عاهدتموه. إن الله يعلم ما تفعلونه، وسيجزيكم عليه.", "isBasmala": false, "translation_en": "Fulfill God's covenant when you make a covenant, and do not break your oaths after ratifying them. You have made God your guarantor, and God knows what you do.", "translation_id": "Dan tepatilah perjanjian dengan Allah apabila kamu berjanji dan janganlah kamu membatalkan sumpah-sumpah(mu) itu, sesudah meneguhkannya, sedang kamu telah menjadikan Allah sebagai saksimu (terhadap sumpah-sumpahmu itu). Sesungguhnya Allah mengetahui apa yang kamu perbuat.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 92, "text": "وَلَا تَكُونُوا۟ كَٱلَّتِی نَقَضَتۡ غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَـٰثࣰا تَتَّخِذُونَ أَیۡمَـٰنَكُمۡ دَخَلَۢا بَیۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِیَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا یَبۡلُوكُمُ ٱللَّهُ بِهِۦۚ وَلَیُبَیِّنَنَّ لَكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ مَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ ۝٩٢", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "ولا ترجعوا في عهودكم، فيكون مَثَلكم مثل امرأة غزلت غَزْلا وأحكمته، ثم نقضته، تجعلون أيمانكم التي حلفتموها عند التعاهد خديعة لمن عاهدتموه، وتنقضون عهدكم إذا وجدتم جماعة أكثر مالا ومنفعة من الذين عاهدتموهم، إنما يختبركم الله بما أمركم به من الوفاء بالعهود وما نهاكم عنه مِن نقضها، وليبيِّن لكم يوم القيامة ما كنتم فيه تختلفون في الدنيا من الإيمان بالله ونبوة محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "And do not be like her who unravels her yarn, breaking it into pieces, after she has spun it strongly. Nor use your oaths as means of deception among you, because one community is more prosperous than another. God is testing you thereby. On the Day of Resurrection, He will make clear to you everything you had disputed about.", "translation_id": "Dan janganlah kamu seperti seorang perempuan yang menguraikan benangnya yang sudah dipintal dengan kuat, menjadi cerai berai kembali, kamu menjadikan sumpah (perjanjian)mu sebagai alat penipu di antaramu, disebabkan adanya satu golongan yang lebih banyak jumlahnya dari golongan yang lain. Sesungguhnya Allah hanya menguji kamu dengan hal itu. Dan sesungguhnya di hari kiamat akan dijelaskan-Nya kepadamu apa yang dahulu kamu perselisihkan itu.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 93, "text": "وَلَوۡ شَاۤءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةࣰ وَ ٰحِدَةࣰ وَلَـٰكِن یُضِلُّ مَن یَشَاۤءُ وَیَهۡدِی مَن یَشَاۤءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ ۝٩٣", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "ولو شاء الله لوفَّقكم كلكم، فجعلكم على ملة واحدة، وهي الإسلام والإيمان، وألزمكم به، ولكنه سبحانه يُضلُّ مَن يشاء ممن علم منه إيثار الضلال، فلا يهديه عدلا منه، ويهدي مَن يشاء مِمَّن علم منه إيثار الحق، فيوفقه فضلا منه، وليسألنَّكم الله جميعًا يوم القيامة عما كنتم تعملون في الدنيا فيما أمركم به، ونهاكم عنه، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "Had God willed, He would have made you one congregation, but He leaves astray whom He wills, and He guides whom He wills. And you will surely be questioned about what you used to do.", "translation_id": "Dan kalau Allah menghendaki, niscaya Dia menjadikan kamu satu umat (saja), tetapi Allah menyesatkan siapa yang dikehendaki-Nya dan memberi petunjuk kepada siapa yang dikehendaki-Nya. Dan sesungguhnya kamu akan ditanya tentang apa yang telah kamu kerjakan.", "manzil": 3, "manzil_display": ""}], "278": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 94, "text": "وَلَا تَتَّخِذُوۤا۟ أَیۡمَـٰنَكُمۡ دَخَلَۢا بَیۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا وَتَذُوقُوا۟ ٱلسُّوۤءَ بِمَا صَدَدتُّمۡ عَن سَبِیلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ عَظِیمࣱ ۝٩٤", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "ولا تجعلوا من الأيمان التي تحلفونها خديعة لمن حلفتم لهم، فتهلكوا بعد أن كنتم آمنين، كمن زلقت قدمه بعد ثبوتها، وتذوقوا ما يسوؤكم من العذاب في الدنيا؛ بما تسببتم فيه مِن مَنْع غيركم عن هذا الدين لما رأوه منكم من الغدر، ولكم في الآخرة عذاب عظيم.", "isBasmala": false, "translation_en": "And do not use your oaths to deceive one another, so that a foot may not slip after being firm, and you taste misery because you hindered from God's path, and incur a terrible torment.", "translation_id": "Dan janganlah kamu jadikan sumpah-sumpahmu sebagai alat penipu di antaramu, yang menyebabkan tergelincir kaki(mu) sesudah kokoh tegaknya, dan kamu rasakan kemelaratan (di dunia) karena kamu menghalangi (manusia) dari jalan Allah; dan bagimu azab yang besar.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 95, "text": "وَلَا تَشۡتَرُوا۟ بِعَهۡدِ ٱللَّهِ ثَمَنࣰا قَلِیلًاۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ۝٩٥", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "ولا تنقضوا عهد الله؛ لتستبدلوا مكانه عرضًا قليلا من متاع الدنيا، إن ما عند الله من الثواب على الوفاء أفضل لكم من هذا الثمن القليل، إن كنتم من أهل العلم، فتدبَّروا الفرق بين خيْرَي الدنيا والآخرة.", "isBasmala": false, "translation_en": "And do not exchange God's covenant for a small price. What is with God is better for you, if you only knew.", "translation_id": "Dan janganlah kamu tukar perjanjianmu dengan Allah dengan harga yang sedikit (murah), sesungguhnya apa yang ada di sisi Allah, itulah yang lebih baik bagimu jika kamu mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 96, "text": "مَا عِندَكُمۡ یَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقࣲۗ وَلَنَجۡزِیَنَّ ٱلَّذِینَ صَبَرُوۤا۟ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُوا۟ یَعۡمَلُونَ ۝٩٦", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "ما عندكم من حطام الدنيا يذهب، وما عند الله لكم من الرزق والثواب لا يزول. ولنُثِيبنَّ الذين تحمَّلوا مشاق التكاليف -ومنها الوفاء بالعهد- ثوابهم بأحسن أعمالهم، فنعطيهم على أدناها، كما نعطيهم على أعلاها تفضُّلا.", "isBasmala": false, "translation_en": "What you have runs out, but what is with God remains. We will reward those who are patient according to the best of their deeds.", "translation_id": "Apa yang di sisimu akan lenyap, dan apa yang ada di sisi Allah adalah kekal. Dan sesungguhnya Kami akan memberi balasan kepada orang-orang yang sabar dengan pahala yang lebih baik dari apa yang telah mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 97, "text": "مَنۡ عَمِلَ صَـٰلِحࣰا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ فَلَنُحۡیِیَنَّهُۥ حَیَوٰةࣰ طَیِّبَةࣰۖ وَلَنَجۡزِیَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُوا۟ یَعۡمَلُونَ ۝٩٧", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "مَن عمل عملا صالحًا ذكرًا كان أم أنثى، وهو مؤمن بالله ورسوله، فلنحيينه في الدنيا حياة سعيدة مطمئنة، ولو كان قليل المال، ولنجزينَّهم في الآخرة ثوابهم بأحسن ما عملوا في الدنيا.", "isBasmala": false, "translation_en": "Whoever works righteousness, whether male or female, while being a believer, We will grant him a good life-and We will reward them according to the best of what they used to do.", "translation_id": "Barangsiapa yang mengerjakan amal saleh, baik laki-laki maupun perempuan dalam keadaan beriman, maka sesungguhnya akan Kami berikan kepadanya kehidupan yang baik dan sesungguhnya akan Kami beri balasan kepada mereka dengan pahala yang lebih baik dari apa yang telah mereka kerjakan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 98, "text": "فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّیۡطَـٰنِ ٱلرَّجِیمِ ۝٩٨", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "فإذا أردت -أيها المؤمن- أن تقرأ شيئًا من القرآن فاستعذ بالله مِن شرِّ الشيطان المطرود من رحمة الله قائلا أعوذ بالله من الشيطان الرجيم.", "isBasmala": false, "translation_en": "When you read the Quran, seek refuge with God from Satan the outcast.", "translation_id": "Apabila kamu membaca Al Quran hendaklah kamu meminta perlindungan kepada Allah dari syaitan yang terkutuk.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 99, "text": "إِنَّهُۥ لَیۡسَ لَهُۥ سُلۡطَـٰنٌ عَلَى ٱلَّذِینَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ ۝٩٩", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "إن الشيطان ليس له تسلُّطٌ على المؤمنين بالله ورسوله، وعلى ربهم وحده يعتمدون. إنما تسلُّطه على الذين جعلوه مُعينًا لهم وأطاعوه، والذين هم -بسبب طاعته- مشركون بالله تعالى.", "isBasmala": false, "translation_en": "He has no authority over those who believe and trust in their Lord.", "translation_id": "Sesungguhnya syaitan itu tidak ada kekuasaannya atas orang-orang yang beriman dan bertawakkal kepada Tuhannya.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 100, "text": "إِنَّمَا سُلۡطَـٰنُهُۥ عَلَى ٱلَّذِینَ یَتَوَلَّوۡنَهُۥ وَٱلَّذِینَ هُم بِهِۦ مُشۡرِكُونَ ۝١٠٠", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "إن الشيطان ليس له تسلُّطٌ على المؤمنين بالله ورسوله، وعلى ربهم وحده يعتمدون. إنما تسلُّطه على الذين جعلوه مُعينًا لهم وأطاعوه، والذين هم -بسبب طاعته- مشركون بالله تعالى.", "isBasmala": false, "translation_en": "His authority is only over those who follow him, and those who associate others with Him.", "translation_id": "Sesungguhnya kekuasaannya (syaitan) hanyalah atas orang-orang yang mengambilnya jadi pemimpin dan atas orang-orang yang mempersekutukannya dengan Allah.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 101, "text": "وَإِذَا بَدَّلۡنَاۤ ءَایَةࣰ مَّكَانَ ءَایَةࣲ وَٱللَّهُ أَعۡلَمُ بِمَا یُنَزِّلُ قَالُوۤا۟ إِنَّمَاۤ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ ۝١٠١", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "وإذا بدَّلنا آية بآية أخرى، والله الخالق أعلم بمصلحة خَلْقه بما ينزله من الأحكام في الأوقات المختلفة، قال الكفار: إنما أنت -يا محمد- كاذب مختَلِق على الله ما لم يَقُلْه. ومحمد صلى الله عليه وسلم ليس كما يزعمون. بل أكثرهم لا عِلْم لهم بربهم ولا بشرعه وأحكامه.", "isBasmala": false, "translation_en": "When We substitute a verse in place of another verse-and God knows best what He reveals-they say, \"You are an impostor.\" But most of them do not know.", "translation_id": "Dan apabila Kami letakkan suatu ayat di tempat ayat yang lain sebagai penggantinya padahal Allah lebih mengetahui apa yang diturunkan-Nya, mereka berkata: \"Sesungguhnya kamu adalah orang yang mengada-adakan saja\". Bahkan kebanyakan mereka tiada mengetahui.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 102, "text": "قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ لِیُثَبِّتَ ٱلَّذِینَ ءَامَنُوا۟ وَهُدࣰى وَبُشۡرَىٰ لِلۡمُسۡلِمِینَ ۝١٠٢", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "قل لهم -أيها الرسول-: ليس القرآن مختلَقًا مِن عندي، بل نَزَّله جبريل مِن ربك بالصدق والعدل؛ تثبيتًا للمؤمنين، وهداية من الضلال، وبشارة طيبة لمن أسلموا وخضعوا لله رب العالمين.", "isBasmala": false, "translation_en": "Say, \"The Holy Spirit has brought it down from your Lord, truthfully, in order to stabilize those who believe, and as guidance and good news for those who submit.\"", "translation_id": "Katakanlah: \"Ruhul Qudus (Jibril) menurunkan Al Quran itu dari Tuhanmu dengan benar, untuk meneguhkan (hati) orang-orang yang telah beriman, dan menjadi petunjuk serta kabar gembira bagi orang-orang yang berserah diri (kepada Allah)\".", "manzil": 3, "manzil_display": ""}], "279": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 103, "text": "وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ یَقُولُونَ إِنَّمَا یُعَلِّمُهُۥ بَشَرࣱۗ لِّسَانُ ٱلَّذِی یُلۡحِدُونَ إِلَیۡهِ أَعۡجَمِیࣱّ وَهَـٰذَا لِسَانٌ عَرَبِیࣱّ مُّبِینٌ ۝١٠٣", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "ولقد نعلم أن المشركين يقولون: إن النبي يتلقى القرآن مِن بشر مِن بني آدم. كذبوا؛ فإن لسان الذي نسبوا إليه تعليم النبي صلى الله عليه وسلم أعجمي لا يُفصح، والقرآن عربي غاية في الوضوح والبيان.", "isBasmala": false, "translation_en": "We are well aware that they say, \"It is a human being who is teaching him.\" But the tongue of him they allude to is foreign, while this is a clear Arabic tongue.", "translation_id": "Dan sesungguhnya Kami mengetahui bahwa mereka berkata: \"Sesungguhnya Al Quran itu diajarkan oleh seorang manusia kepadanya (Muhammad)\". Padahal bahasa orang yang mereka tuduhkan (bahwa) Muhammad belajar kepadanya bahasa 'Ajam, sedang Al Quran adalah dalam bahasa Arab yang terang.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 104, "text": "إِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِـَٔایَـٰتِ ٱللَّهِ لَا یَهۡدِیهِمُ ٱللَّهُ وَلَهُمۡ عَذَابٌ أَلِیمٌ ۝١٠٤", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "إن الكفار الذين لا يصدقون بالقرآن لا يوفقهم الله لإصابة الحق، ولهم في الآخرة عذاب مؤلم موجع.", "isBasmala": false, "translation_en": "Those who do not believe in God's revelations-God will not guide them, and for them is a painful punishment.", "translation_id": "Sesungguhnya orang-orang yang tidak beriman kepada ayat-ayat Allah (Al Quran), Allah tidak akan memberi petunjuk kepada mereka dan bagi mereka azab yang pedih.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 105, "text": "إِنَّمَا یَفۡتَرِی ٱلۡكَذِبَ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِـَٔایَـٰتِ ٱللَّهِۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡكَـٰذِبُونَ ۝١٠٥", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "إنما يختلق الكذبَ مَن لا يؤمن بالله وآياته، وأولئك هم الكاذبون في قولهم ذلك. أما محمد صلى الله عليه وسلم المؤمن بربه الخاضع له فمحال أن يكذب على الله، ويقول عليه ما لم يقله.", "isBasmala": false, "translation_en": "It is those who do not believe in God's revelations who fabricate falsehood. These are the liars.", "translation_id": "Sesungguhnya yang mengada-adakan kebohongan, hanyalah orang-orang yang tidak beriman kepada ayat-ayat Allah, dan mereka itulah orang-orang pendusta.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 106, "text": "مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِیمَـٰنِهِۦۤ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَىِٕنُّۢ بِٱلۡإِیمَـٰنِ وَلَـٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرࣰا فَعَلَیۡهِمۡ غَضَبࣱ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِیمࣱ ۝١٠٦", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "إنما يفتري الكذب مَن نطق بكلمة الكفر وارتدَّ بعد إيمانه، فعليهم غضب من الله، إلا مَن أُرغم على النطق بالكفر، فنطق به خوفًا من الهلاك وقلبه ثابت على الإيمان، فلا لوم عليه، لكن من نطق بالكفر واطمأن قلبه إليه، فعليهم غضب شديد من الله، ولهم عذاب عظيم؛ وذلك بسبب إيثارهم الدنيا وزينتها، وتفضيلهم إياها على الآخرة وثوابها، وأن الله لا يهدي الكافرين، ولا يوفقهم للحق والصواب.", "isBasmala": false, "translation_en": "Whoever renounces faith in God after having believed-except for someone who is compelled, while his heart rests securely in faith-but whoever willingly opens up his heart to disbelief-upon them falls wrath from God, and for them is a tremendous torment.", "translation_id": "Barangsiapa yang kafir kepada Allah sesudah dia beriman (dia mendapat kemurkaan Allah), kecuali orang yang dipaksa kafir padahal hatinya tetap tenang dalam beriman (dia tidak berdosa), akan tetapi orang yang melapangkan dadanya untuk kekafiran, maka kemurkaan Allah menimpanya dan baginya azab yang besar.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 107, "text": "ذَ ٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّوا۟ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا عَلَى ٱلۡـَٔاخِرَةِ وَأَنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡكَـٰفِرِینَ ۝١٠٧", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "إنما يفتري الكذب مَن نطق بكلمة الكفر وارتدَّ بعد إيمانه، فعليهم غضب من الله، إلا مَن أُرغم على النطق بالكفر، فنطق به خوفًا من الهلاك وقلبه ثابت على الإيمان، فلا لوم عليه، لكن من نطق بالكفر واطمأن قلبه إليه، فعليهم غضب شديد من الله، ولهم عذاب عظيم؛ وذلك بسبب إيثارهم الدنيا وزينتها، وتفضيلهم إياها على الآخرة وثوابها، وأن الله لا يهدي الكافرين، ولا يوفقهم للحق والصواب.", "isBasmala": false, "translation_en": "That is because they have preferred the worldly life to the Hereafter, and because God does not guide the people who refuse.", "translation_id": "Yang demikian itu disebabkan karena sesungguhnya mereka mencintai kehidupan di dunia lebih dari akhirat, dan bahwasanya Allah tiada memberi petunjuk kepada kaum yang kafir.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 108, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَـٰرِهِمۡۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡغَـٰفِلُونَ ۝١٠٨", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "أولئك هم الذين ختم الله على قلوبهم بالكفر وإيثار الدنيا على الآخرة، فلا يصل إليها نور الهداية، وأصم سمعهم عن آيات الله فلا يسمعونها سماع تدبُّر، وأعمى أبصارهم، فلا يرون البراهين الدالة على ألوهية الله، وأولئك هم الغافلون عمَّا أعدَّ الله لهم من العذاب.", "isBasmala": false, "translation_en": "It is they whom God has sealed their hearts, and their hearing, and their sight. It is they who are the heedless.", "translation_id": "Mereka itulah orang-orang yang hati, pendengaran dan penglihatannya telah dikunci mati oleh Allah, dan mereka itulah orang-orang yang lalai.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 109, "text": "لَا جَرَمَ أَنَّهُمۡ فِی ٱلۡـَٔاخِرَةِ هُمُ ٱلۡخَـٰسِرُونَ ۝١٠٩", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "حقًا إنهم في الآخرة هم الخاسرون الهالكون، الذين صرفوا حياتهم إلى ما فيه عذابهم وهلاكهم.", "isBasmala": false, "translation_en": "There is no doubt that in the Hereafter they will be the losers.", "translation_id": "Pastilah bahwa mereka di akhirat nanti adalah orang-orang yang merugi.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 110, "text": "ثُمَّ إِنَّ رَبَّكَ لِلَّذِینَ هَاجَرُوا۟ مِنۢ بَعۡدِ مَا فُتِنُوا۟ ثُمَّ جَـٰهَدُوا۟ وَصَبَرُوۤا۟ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِیمࣱ ۝١١٠", "juz": 14, "hizb": "(*½ ح 28*)", "tafsir": "ثم إن ربك للمستضعفين في \"مكة\" الذين عذَّبهم المشركون، حتى وافقوهم على ما هم عليه ظاهرًا، ففتنوهم بالتلفظ بما يرضيهم، وقلوبهم مطمئنة بالإيمان، ولمَّا أمكنهم الخلاص هاجروا إلى \"المدينة\"، ثم جاهدوا في سبيل الله، وصبروا على مشاق التكاليف، إن ربك -من بعد توبتهم- لَغفور لهم، رحيم بهم.", "isBasmala": false, "translation_en": "But then your Lord-for those who emigrated after being persecuted, then struggled and persevered-your Lord thereafter is Forgiving and Merciful.", "translation_id": "Dan sesungguhnya Tuhanmu (pelindung) bagi orang-orang yang berhijrah sesudah menderita cobaan, kemudian mereka berjihad dan sabar; sesungguhnya Tuhanmu sesudah itu benar-benar Maha Pengampun lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}], "280": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 111, "text": "۞ یَوۡمَ تَأۡتِی كُلُّ نَفۡسࣲ تُجَـٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا عَمِلَتۡ وَهُمۡ لَا یُظۡلَمُونَ ۝١١١", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "وذكرهم -أيها الرسول- بيوم القيامة حين تأتي كل نفس تخاصم عن ذاتها، وتعتذر بكل المعاذير، ويوفي الله كل نفس جزاء ما عَمِلَتْه من غير ظلم لها، فلا يزيدهم في العقاب، ولا ينقصهم من الثواب.", "isBasmala": false, "translation_en": "On the Day when every soul will come pleading for itself, and every soul will be paid in full for what it has done, and they will not be wronged.", "translation_id": "(Ingatlah) suatu hari (ketika) tiap-tiap diri datang untuk membela dirinya sendiri dan bagi tiap-tiap diri disempurnakan (balasan) apa yang telah dikerjakannya, sedangkan mereka tidak dianiaya (dirugikan).", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 112, "text": "وَضَرَبَ ٱللَّهُ مَثَلࣰا قَرۡیَةࣰ كَانَتۡ ءَامِنَةࣰ مُّطۡمَىِٕنَّةࣰ یَأۡتِیهَا رِزۡقُهَا رَغَدࣰا مِّن كُلِّ مَكَانࣲ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَ ٰقَهَا ٱللَّهُ لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُوا۟ یَصۡنَعُونَ ۝١١٢", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "وضرب الله مثلا بلدة \"مكة\" كانت في أمان من الاعتداء، واطمئنان مِن ضيق العيش، يأتيها رزقها هنيئًا سهلا من كل جهة، فجحد أهلُها نِعَمَ الله عليهم، وأشركوا به، ولم يشكروا له، فعاقبهم الله بالجوع، والخوف من سرايا رسول الله صلى الله عليه وسلم وجيوشه، التي كانت تخيفهم؛ وذلك بسبب كفرهم وصنيعهم الباطل.", "isBasmala": false, "translation_en": "And God cites the example of a town that was secure and peaceful, with its livelihood coming to it abundantly from every direction. But then it turned unappreciative of God's blessings, so God made it taste the robe of hunger and fear, because of what they used to craft.", "translation_id": "Dan Allah telah membuat suatu perumpamaan (dengan) sebuah negeri yang dahulunya aman lagi tenteram, rezekinya datang kepadanya melimpah ruah dari segenap tempat, tetapi (penduduk)nya mengingkari nikmat-nikmat Allah; karena itu Allah merasakan kepada mereka pakaian kelaparan dan ketakutan, disebabkan apa yang selalu mereka perbuat.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 113, "text": "وَلَقَدۡ جَاۤءَهُمۡ رَسُولࣱ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ ظَـٰلِمُونَ ۝١١٣", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "ولقد أرسل الله إلى أهل \"مكة\" رسولا منهم، هو النبي محمد صلى الله عليه وسلم، يعرفون نسبه وصدقه وأمانته، فلم يقبلوا ما جاءهم به، ولم يصدقوه، فأخذهم العذاب من الشدائد والجوع والخوف، وقَتْل عظمائهم في \"بدر\" وهم ظالمون لأنفسهم بالشرك بالله، والصدِّ عن سبيله.", "isBasmala": false, "translation_en": "A messenger from among them had come to them, but they denounced him, so the punishment seized them in the midst of their wrongdoing.", "translation_id": "Dan sesungguhnya telah datang kepada mereka seorang rasul dari mereka sendiri, tetapi mereka mendustakannya; karena itu mereka dimusnahkan azab dan mereka adalah orang-orang yang zalim.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 114, "text": "فَكُلُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَـٰلࣰا طَیِّبࣰا وَٱشۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِیَّاهُ تَعۡبُدُونَ ۝١١٤", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "فكلوا -أيها المؤمنون- مما رزقكم الله، وجعله لكم حلالا مستطابًا، واشكروا نعمة الله عليكم بالاعتراف بها وصَرْفها في طاعة الله، إن كنتم حقًّا منقادين لأمره سامعين مطيعين له، تعبدونه وحده لا شريك له.", "isBasmala": false, "translation_en": "Eat of the lawful and good things God has provided for you, and be thankful for God's blessings, if it is Him that you serve.", "translation_id": "Maka makanlah yang halal lagi baik dari rezeki yang telah diberikan Allah kepadamu; dan syukurilah nikmat Allah, jika kamu hanya kepada-Nya saja menyembah.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 115, "text": "إِنَّمَا حَرَّمَ عَلَیۡكُمُ ٱلۡمَیۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِیرِ وَمَاۤ أُهِلَّ لِغَیۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَیۡرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝١١٥", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "إنما حرَّم الله عليكم الميتة من الحيوان، والدم المسفوح من الذبيح عند ذبحه، ولحم الخنزير، وما ذبح لغير الله، لكن مَن ألجأته ضرورة الخوف من الموت إلى أَكْلِ شيء مِن هذه المحرمات وهو غير ظالم، ولا متجاوزٍ حدَّ الضرورة، فإن الله غفور له، رحيم به، لا يعاقبه على ما فعل.", "isBasmala": false, "translation_en": "He has forbidden you carrion, and blood, and the flesh of swine, and anything consecrated to other than God. But if anyone is compelled by necessity, without being deliberate or malicious, then God is Forgiving and Merciful.", "translation_id": "Sesungguhnya Allah hanya mengharamkan atasmu (memakan) bangkai, darah, daging babi dan apa yang disembelih dengan menyebut nama selain Allah; tetapi barangsiapa yang terpaksa memakannya dengan tidak menganiaya dan tidak pula melampaui batas, maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 116, "text": "وَلَا تَقُولُوا۟ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَـٰذَا حَلَـٰلࣱ وَهَـٰذَا حَرَامࣱ لِّتَفۡتَرُوا۟ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِینَ یَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا یُفۡلِحُونَ ۝١١٦", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "ولا تقولوا -أيها المشركون- للكذب الذي تصفه ألسنتكم: هذا حلال لِما حرَّمه الله، وهذا حرام لِما أحَلَّه الله؛ لتختلقوا على الله الكذب بنسبة التحليل والتحريم إليه، إن الذين يختلقون على الله الكذب لا يفوزون بخير في الدنيا ولا في الآخرة.", "isBasmala": false, "translation_en": "And do not say of falsehood asserted by your tongues, \"This is lawful, and this is unlawful,\" in order to invent lies and attribute them to God. Those who invent lies and attribute them to God will not succeed.", "translation_id": "Dan janganlah kamu mengatakan terhadap apa yang disebut-sebut oleh lidahmu secara dusta \"ini halal dan ini haram\", untuk mengada-adakan kebohongan terhadap Allah. Sesungguhnya orang-orang yang mengada-adakan kebohongan terhadap Allah tiadalah beruntung.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 117, "text": "مَتَـٰعࣱ قَلِیلࣱ وَلَهُمۡ عَذَابٌ أَلِیمࣱ ۝١١٧", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "متاعهم في الدنيا متاع زائل ضئيل، ولهم في الآخرة عذاب موجع.", "isBasmala": false, "translation_en": "A brief enjoyment-then they will have a painful punishment.", "translation_id": "(Itu adalah) kesenangan yang sedikit, dan bagi mereka azab yang pedih.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 118, "text": "وَعَلَى ٱلَّذِینَ هَادُوا۟ حَرَّمۡنَا مَا قَصَصۡنَا عَلَیۡكَ مِن قَبۡلُۖ وَمَا ظَلَمۡنَـٰهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ ۝١١٨", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "وعلى اليهود حَرَّمنا ما أخبرناك به -أيها الرسول- مِن قبل، وهو كل ذي ظُفُر، وشحوم البقر والغنم، إلا ما حَمَلَتْه ظهورها أو أمعاؤها أو كان مختلطًا بعظم، وما ظلمناهم بتحريم ذلك عليهم، ولكن كانوا ظالمين لأنفسهم بالكفر والبغي، فاستحقوا التحريم عقوبة لهم.", "isBasmala": false, "translation_en": "For those who are Jews, We have prohibited what We related to you before. We did not wrong them, but they used to wrong their own selves.", "translation_id": "Dan terhadap orang-orang Yahudi, Kami haramkan apa yang telah Kami ceritakan dahulu kepadamu; dan Kami tiada menganiaya mereka, akan tetapi merekalah yang menganiaya diri mereka sendiri.", "manzil": 3, "manzil_display": ""}], "281": [{"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 119, "text": "ثُمَّ إِنَّ رَبَّكَ لِلَّذِینَ عَمِلُوا۟ ٱلسُّوۤءَ بِجَهَـٰلَةࣲ ثُمَّ تَابُوا۟ مِنۢ بَعۡدِ ذَ ٰلِكَ وَأَصۡلَحُوۤا۟ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِیمٌ ۝١١٩", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "ثم إن ربك للذين فعلوا المعاصي في حال جهلهم لعاقبتها وإيجابها لسخط الله -فكل عاص لله مخطئًا أو متعمدًا فهو جاهل بهذا الاعتبار وإن كان عالمًا بالتحريم-، ثم رجعوا إلى الله عمَّا كانوا عليه من الذنوب، وأصلحوا نفوسهم وأعمالهم، إن ربك -مِن بعد توبتهم وإصلاحهم- لَغفور لهم، رحيم بهم.", "isBasmala": false, "translation_en": "But towards those who do wrongs in ignorance, and then repent afterwards and reform, your Lord thereafter is Forgiving and Merciful.", "translation_id": "Kemudian, sesungguhnya Tuhanmu (mengampuni) bagi orang-orang yang mengerjakan kesalahan karena kebodohannya, kemudian mereka bertaubat sesudah itu dan memperbaiki (dirinya), sesungguhnya Tuhanmu sesudah itu benar-benar Maha Pengampun lagi Maha Penyayang.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 120, "text": "إِنَّ إِبۡرَ ٰهِیمَ كَانَ أُمَّةࣰ قَانِتࣰا لِّلَّهِ حَنِیفࣰا وَلَمۡ یَكُ مِنَ ٱلۡمُشۡرِكِینَ ۝١٢٠", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "إن إبراهيم كان إمامًا في الخير، وكان طائعا خاضعًا لله، لا يميل عن دين الإسلام موحِّدًا لله غير مشرك به، وكان شاكرًا لنعم الله عليه، اختاره الله لرسالته، وأرشده إلى الطريق المستقيم، وهو الإسلام، وآتيناه في الدنيا نعمة حسنة من الثناء عليه في الآخِرين والقدوة به، والولد الصالح، وإنه عند الله في الآخرة لمن الصالحين أصحاب المنازل العالية.", "isBasmala": false, "translation_en": "Abraham was an exemplary leader, devoted to God, a monotheist, and was not of the polytheists.", "translation_id": "Sesungguhnya Ibrahim adalah seorang imam yang dapat dijadikan teladan lagi patuh kepada Allah dan hanif. Dan sekali-kali bukanlah dia termasuk orang-orang yang mempersekutukan (Tuhan),", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 121, "text": "شَاكِرࣰا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝١٢١", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "إن إبراهيم كان إمامًا في الخير، وكان طائعا خاضعًا لله، لا يميل عن دين الإسلام موحِّدًا لله غير مشرك به، وكان شاكرًا لنعم الله عليه، اختاره الله لرسالته، وأرشده إلى الطريق المستقيم، وهو الإسلام، وآتيناه في الدنيا نعمة حسنة من الثناء عليه في الآخِرين والقدوة به، والولد الصالح، وإنه عند الله في الآخرة لمن الصالحين أصحاب المنازل العالية.", "isBasmala": false, "translation_en": "Thankful for His blessings. He chose him, and guided him to a straight path.", "translation_id": "(lagi) yang mensyukuri nikmat-nikmat Allah. Allah telah memilihnya dan menunjukinya kepada jalan yang lurus.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 122, "text": "وَءَاتَیۡنَـٰهُ فِی ٱلدُّنۡیَا حَسَنَةࣰۖ وَإِنَّهُۥ فِی ٱلۡـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِینَ ۝١٢٢", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "إن إبراهيم كان إمامًا في الخير، وكان طائعا خاضعًا لله، لا يميل عن دين الإسلام موحِّدًا لله غير مشرك به، وكان شاكرًا لنعم الله عليه، اختاره الله لرسالته، وأرشده إلى الطريق المستقيم، وهو الإسلام، وآتيناه في الدنيا نعمة حسنة من الثناء عليه في الآخِرين والقدوة به، والولد الصالح، وإنه عند الله في الآخرة لمن الصالحين أصحاب المنازل العالية.", "isBasmala": false, "translation_en": "And We gave him goodness in this world, and in the Hereafter he will be among the righteous.", "translation_id": "Dan Kami berikan kepadanya kebaikan di dunia. Dan sesungguhnya dia di akhirat benar-benar termasuk orang-orang yang saleh.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 123, "text": "ثُمَّ أَوۡحَیۡنَاۤ إِلَیۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَ ٰهِیمَ حَنِیفࣰاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِینَ ۝١٢٣", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "ثم أوحينا إليك -أيها الرسول- أن اتبع دين الإسلام كما اتبعه إبراهيم، وأن استقم عليه، ولا تَحِدْ عنه، فإن إبراهيم لم يكن من المشركين مع الله غيره.", "isBasmala": false, "translation_en": "Then We inspired you: \"Follow the religion of Abraham, the Monotheist. He was not an idol-worshiper.\"", "translation_id": "Kemudian Kami wahyukan kepadamu (Muhammad): \"Ikutilah agama Ibrahim seorang yang hanif\" dan bukanlah dia termasuk orang-orang yang mempersekutukan Tuhan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 124, "text": "إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِینَ ٱخۡتَلَفُوا۟ فِیهِۚ وَإِنَّ رَبَّكَ لَیَحۡكُمُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ ۝١٢٤", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "إنما جعل الله تعظيم يوم السبت بالتفرغ للعبادة فيه على اليهود الذين اختلفوا فيه على نبيهم، واختاروه بدل يوم الجمعة الذي أُمِروا بتعظيمه. فإن ربك -أيها الرسول- لَيحكم بين المختلفين يوم القيامة فيما اختلفوا فيه على نبيهم، ويجازي كلا بما يستحقه.", "isBasmala": false, "translation_en": "The Sabbath was decreed only for those who differed about it. Your Lord will judge between them on the Day of Resurrection regarding their differences.", "translation_id": "Sesungguhnya diwajibkan (menghormati) hari Sabtu atas orang-orang (Yahudi) yang berselisih padanya. Dan sesungguhnya Tuhanmu benar-benar akan memberi putusan di antara mereka di hari kiamat terhadap apa yang telah mereka perselisihkan itu.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 125, "text": "ٱدۡعُ إِلَىٰ سَبِیلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَـٰدِلۡهُم بِٱلَّتِی هِیَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِیلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ ۝١٢٥", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "ادعُ -أيها الرسول- أنت ومَنِ اتبعك إلى دين ربك وطريقه المستقيم، بالطريقة الحكيمة التي أوحاها الله إليك في الكتاب والسنة، وخاطِب الناس بالأسلوب المناسب لهم، وانصح لهم نصحًا حسنًا، يرغبهم في الخير، وينفرهم من الشر، وجادلهم بأحسن طرق المجادلة من الرفق واللين. فما عليك إلا البلاغ، وقد بلَّغْتَ، أما هدايتهم فعلى الله وحده، فهو أعلم بمن ضلَّ عن سبيله، وهو أعلم بالمهتدين.", "isBasmala": false, "translation_en": "Invite to the way of your Lord with wisdom and good advice, and debate with them in the most dignified manner. Your Lord is aware of those who stray from His path, and He is aware of those who are guided.", "translation_id": "Serulah (manusia) kepada jalan Tuhan-mu dengan hikmah dan pelajaran yang baik dan bantahlah mereka dengan cara yang baik. Sesungguhnya Tuhanmu Dialah yang lebih mengetahui tentang siapa yang tersesat dari jalan-Nya dan Dialah yang lebih mengetahui orang-orang yang mendapat petunjuk.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 126, "text": "وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُوا۟ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَىِٕن صَبَرۡتُمۡ لَهُوَ خَیۡرࣱ لِّلصَّـٰبِرِینَ ۝١٢٦", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "وإن أردتم -أيها المؤمنون- القصاص ممن اعتدوا عليكم، فلا تزيدوا عما فعلوه بكم، ولئن صبرتم لهو خير لكم في الدنيا بالنصر، وفي الآخرة بالأجر العظيم.", "isBasmala": false, "translation_en": "If you were to retaliate, retaliate to the same degree as the injury done to you. But if you resort to patience-it is better for the patient.", "translation_id": "Dan jika kamu memberikan balasan, maka balaslah dengan balasan yang sama dengan siksaan yang ditimpakan kepadamu. Akan tetapi jika kamu bersabar, sesungguhnya itulah yang lebih baik bagi orang-orang yang sabar.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 127, "text": "وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَیۡهِمۡ وَلَا تَكُ فِی ضَیۡقࣲ مِّمَّا یَمۡكُرُونَ ۝١٢٧", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "واصبر -أيها الرسول- على ما أصابك مِن أذى في الله حتى يأتيك الفرج، وما صبرك إلا بالله، فهو الذي يعينك عليه ويثبتك، ولا تحزن على مَن خالفك ولم يستجب لدعوتك، ولا تغتم مِن مكرهم وكيدهم؛ فإن ذلك عائد عليهم بالشر والوبال.", "isBasmala": false, "translation_en": "So be patient. Your patience is solely from God. And do not grieve over them, and do not be stressed by their schemes.", "translation_id": "Bersabarlah (hai Muhammad) dan tiadalah kesabaranmu itu melainkan dengan pertolongan Allah dan janganlah kamu bersedih hati terhadap (kekafiran) mereka dan janganlah kamu bersempit dada terhadap apa yang mereka tipu dayakan.", "manzil": 3, "manzil_display": ""}, {"sura": 16, "sura_name": "النحل", "revelation": "Makkiyah", "aya": 128, "text": "إِنَّ ٱللَّهَ مَعَ ٱلَّذِینَ ٱتَّقَوا۟ وَّٱلَّذِینَ هُم مُّحۡسِنُونَ ۝١٢٨", "juz": 14, "hizb": "(*¾ ح 28*)", "tafsir": "إن الله سبحانه وتعالى مع الذين اتقوه بامتثال ما أمر واجتناب ما نهى بالنصر والتأييد، ومع الذين يحسنون أداء فرائضه والقيام بحقوقه ولزوم طاعته، بعونه وتوفيقه ونصره.", "isBasmala": false, "translation_en": "God is with those who are righteous and those who are virtuous.", "translation_id": "Sesungguhnya Allah beserta orang-orang yang bertakwa dan orang-orang yang berbuat kebaikan.", "manzil": 3, "manzil_display": ""}], "282": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 15, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 1, "text": "۞ سُبۡحَـٰنَ ٱلَّذِیۤ أَسۡرَىٰ بِعَبۡدِهِۦ لَیۡلࣰا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِی بَـٰرَكۡنَا حَوۡلَهُۥ لِنُرِیَهُۥ مِنۡ ءَایَـٰتِنَاۤۚ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡبَصِیرُ ۝١", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "يمجِّد الله نفسه ويعظم شأنه، لقدرته على ما لا يقدر عليه أحد سواه، لا إله غيره، ولا رب سواه، فهو الذي أسرى بعبده محمد صلى الله عليه وسلم زمنًا من الليل بجسده وروحه، يقظة لا منامًا، من المسجد الحرام بـ \"مكة\" إلى المسجد الأقصى بـ \"بيت المقدس\" الذي بارك الله حوله في الزروع والثمار وغير ذلك، وجعله محلا لكثير من الأنبياء؛ ليشاهد عجائب قدرة الله وأدلة وحدانيته. إن الله سبحانه وتعالى هو السميع لجميع الأصوات، البصير بكل مُبْصَر، فيعطي كُلا ما يستحقه في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Glory to Him who journeyed His servant by night, from the Sacred Mosque, to the Farthest Mosque, whose precincts We have blessed, in order to show him of Our wonders. He is the Listener, the Beholder.", "translation_id": "Maha Suci Allah, yang telah memperjalankan hamba-Nya pada suatu malam dari Al Masjidil Haram ke Al Masjidil Aqsha yang telah Kami berkahi sekelilingnya agar Kami perlihatkan kepadanya sebagian dari tanda-tanda (kebesaran) Kami. Sesungguhnya Dia adalah Maha Mendengar lagi Maha Mengetahui.", "manzil": 4, "manzil_display": "المنزل الرابع (م ب 4)"}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 2, "text": "وَءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ وَجَعَلۡنَـٰهُ هُدࣰى لِّبَنِیۤ إِسۡرَ ٰۤءِیلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِی وَكِیلࣰا ۝٢", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "وكما كرَّم الله محمدًا صلى الله عليه وسلم بالإسراء، كَرَّم موسى عليه السلام بإعطائه التوراة، وجعلها بيانًا للحق وإرشادًا لبني إسرائيل، متضمنة نهيهم عن اتخاذ غير الله تعالى وليًا أو معبودًا يفوضون إليه أمورهم.", "isBasmala": false, "translation_en": "And We gave Moses the Scripture, and made it a guide for the Children of Israel: Take none for protector other than Me.", "translation_id": "Dan Kami berikan kepada Musa kitab (Taurat) dan Kami jadikan kitab Taurat itu petunjuk bagi Bani Israil (dengan firman): \"Janganlah kamu mengambil penolong selain Aku,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 3, "text": "ذُرِّیَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدࣰا شَكُورࣰا ۝٣", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "يا سلالة الذين أنجيناهم وحَمَلْناهم مع نوح في السفينة لا تشركوا بالله في عبادته، وكونوا شاكرين لنعمه، مقتدين بنوح عليه السلام؛ إنه كان عبدًا شكورًا لله بقلبه ولسانه وجوارحه.", "isBasmala": false, "translation_en": "The descendants of those We carried with Noah. He was an appreciative servant.", "translation_id": "(yaitu) anak cucu dari orang-orang yang Kami bawa bersama-sama Nuh. Sesungguhnya dia adalah hamba (Allah) yang banyak bersyukur.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 4, "text": "وَقَضَیۡنَاۤ إِلَىٰ بَنِیۤ إِسۡرَ ٰۤءِیلَ فِی ٱلۡكِتَـٰبِ لَتُفۡسِدُنَّ فِی ٱلۡأَرۡضِ مَرَّتَیۡنِ وَلَتَعۡلُنَّ عُلُوࣰّا كَبِیرࣰا ۝٤", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "وأخبرنا بني إسرائيل في التوراة التي أُنزلت عليهم بأنه لا بد أن يقع منهم إفساد مرتين في \"بيت المقدس\" وما والاه بالظلم، وقَتْل الأنبياء والتكبر والطغيان والعدوان.", "isBasmala": false, "translation_en": "And We conveyed to the Children of Israel in the Scripture: You will commit evil on earth twice, and you will rise to a great height.", "translation_id": "Dan telah Kami tetapkan terhadap Bani Israil dalam Kitab itu: \"Sesungguhnya kamu akan membuat kerusakan di muka bumi ini dua kali dan pasti kamu akan menyombongkan diri dengan kesombongan yang besar\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 5, "text": "فَإِذَا جَاۤءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَیۡكُمۡ عِبَادࣰا لَّنَاۤ أُو۟لِی بَأۡسࣲ شَدِیدࣲ فَجَاسُوا۟ خِلَـٰلَ ٱلدِّیَارِۚ وَكَانَ وَعۡدࣰا مَّفۡعُولࣰا ۝٥", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "فإذا وقع منهم الإفساد الأول سَلَّطْنا عليهم عبادًا لنا ذوي شجاعة وقوة شديدة، يغلبونهم ويقتلونهم ويشردونهم، فطافوا بين ديارهم مفسدين، وكان ذلك وعدًا لا بدَّ مِن وقوعه؛ لوجود سببه منهم.", "isBasmala": false, "translation_en": "When the first of the two promises came true, We sent against you servants of Ours, possessing great might, and they ransacked your homes. It was a promise fulfilled.", "translation_id": "Maka apabila datang saat hukuman bagi (kejahatan) pertama dari kedua (kejahatan) itu, Kami datangkan kepadamu hamba-hamba Kami yang mempunyai kekuatan yang besar, lalu mereka merajalela di kampung-kampung, dan itulah ketetapan yang pasti terlaksana.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 6, "text": "ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَیۡهِمۡ وَأَمۡدَدۡنَـٰكُم بِأَمۡوَ ٰلࣲ وَبَنِینَ وَجَعَلۡنَـٰكُمۡ أَكۡثَرَ نَفِیرًا ۝٦", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "ثم رَدَدْنا لكم -يا بني إسرائيل- الغلبة والظهور على أعدائكم الذين سُلِّطوا عليكم، وأكثرنا أرزاقكم وأولادكم، وقَوَّيناكم وجعلناكم أكثر عددًا من عدوكم؛ وذلك بسبب إحسانكم وخضوعكم لله.", "isBasmala": false, "translation_en": "Then We gave you back your turn against them, and supplied you with wealth and children, and made you more numerous.", "translation_id": "Kemudian Kami berikan kepadamu giliran untuk mengalahkan mereka kembali dan Kami membantumu dengan harta kekayaan dan anak-anak dan Kami jadikan kamu kelompok yang lebih besar.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 7, "text": "إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَاۤءَ وَعۡدُ ٱلۡـَٔاخِرَةِ لِیَسُـࣳۤـُٔوا۟ وُجُوهَكُمۡ وَلِیَدۡخُلُوا۟ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةࣲ وَلِیُتَبِّرُوا۟ مَا عَلَوۡا۟ تَتۡبِیرًا ۝٧", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "إن أحسنتم أفعالكم وأقوالكم فقد أحسنتم لأنفسكم؛ لأن ثواب ذلك عائد إليكم، وإن أسأتم فعقاب ذلك عائد عليكم، فإذا حان موعد الإفساد الثاني سَلَّطْنا عليكم أعداءكم مرة أخرى؛ ليذلوكم ويغلبوكم، فتظهر آثار الإهانة والمذلة على وجوهكم، وليدخلوا عليكم \"بيت المقدس\" فيخرِّبوه، كما خرَّبوه أول مرة، وليدمروا كل ما وقع تحت أيديهم تدميرًا كاملا.", "isBasmala": false, "translation_en": "If you work righteousness, you work righteousness for yourselves; and if you commit evil, you do so against yourselves. Then, when the second promise comes true, they will make your faces filled with sorrow, and enter the Temple as they entered it the first time, and utterly destroy all that falls into their power.", "translation_id": "Jika kamu berbuat baik (berarti) kamu berbuat baik bagi dirimu sendiri dan jika kamu berbuat jahat, maka (kejahatan) itu bagi dirimu sendiri, dan apabila datang saat hukuman bagi (kejahatan) yang kedua, (Kami datangkan orang-orang lain) untuk menyuramkan muka-muka kamu dan mereka masuk ke dalam mesjid, sebagaimana musuh-musuhmu memasukinya pada kali pertama dan untuk membinasakan sehabis-habisnya apa saja yang mereka kuasai.", "manzil": 4, "manzil_display": ""}], "283": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 8, "text": "عَسَىٰ رَبُّكُمۡ أَن یَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۘ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَـٰفِرِینَ حَصِیرًا ۝٨", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "عسى ربكم -يا بني إسرائيل- أن يرحمكم بعد انتقامه إن تبتم وأصلحتم، وإن عدتم إلى الإفساد والظلم عُدْنا إلى عقابكم ومذلَّتكم. وجعلنا جهنم لكم وللكافرين عامة سجنًا لا خروج منه أبدا. وفي هذه الآية وما قبلها، تحذير لهذه الأمة من العمل بالمعاصي؛ لئلا يصيبها مثل ما أصاب بني إسرائيل، فسنن الله واحدة لا تبدل ولا تغير.", "isBasmala": false, "translation_en": "Perhaps your Lord will have mercy on you. But if you revert, We will revert. We have made Hell a prison for the disbelievers.", "translation_id": "Mudah-mudahan Tuhanmu akan melimpahkan rahmat(Nya) kepadamu; dan sekiranya kamu kembali kepada (kedurhakaan) niscaya Kami kembali (mengazabmu) dan Kami jadikan neraka Jahannam penjara bagi orang-orang yang tidak beriman.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 9, "text": "إِنَّ هَـٰذَا ٱلۡقُرۡءَانَ یَهۡدِی لِلَّتِی هِیَ أَقۡوَمُ وَیُبَشِّرُ ٱلۡمُؤۡمِنِینَ ٱلَّذِینَ یَعۡمَلُونَ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمۡ أَجۡرࣰا كَبِیرࣰا ۝٩", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "إن هذا القرآن الذي أنزلناه على عبدنا محمد يرشد الناس إلى أحسن الطرق، وهي ملة الإسلام، ويبشر المؤمنين الذين يعملون بما أمرهم الله به، وينتهون عمَّا نهاهم عنه، بأن لهم ثوابًا عظيمًا، وأن الذين لا يصدقون بالدار الآخرة وما فيها من الجزاء أعددنا لهم عذابًا موجعًا في النار.", "isBasmala": false, "translation_en": "This Quran guides to what is most upright; and it gives good news to the believers who do good deeds, that they will have a great reward.", "translation_id": "Sesungguhnya Al Quran ini memberikan petunjuk kepada (jalan) yang lebih lurus dan memberi khabar gembira kepada orang-orang Mu'min yang mengerjakan amal saleh bahwa bagi mereka ada pahala yang besar,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 10, "text": "وَأَنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِیمࣰا ۝١٠", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "إن هذا القرآن الذي أنزلناه على عبدنا محمد يرشد الناس إلى أحسن الطرق، وهي ملة الإسلام، ويبشر المؤمنين الذين يعملون بما أمرهم الله به، وينتهون عمَّا نهاهم عنه، بأن لهم ثوابًا عظيمًا، وأن الذين لا يصدقون بالدار الآخرة وما فيها من الجزاء أعددنا لهم عذابًا موجعًا في النار.", "isBasmala": false, "translation_en": "And those who do not believe in the Hereafter-We have prepared for them a painful punishment.", "translation_id": "dan sesungguhnya orang-orang yang tidak beriman kepada kehidupan akhirat, Kami sediakan bagi mereka azab yang pedih.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 11, "text": "وَیَدۡعُ ٱلۡإِنسَـٰنُ بِٱلشَّرِّ دُعَاۤءَهُۥ بِٱلۡخَیۡرِۖ وَكَانَ ٱلۡإِنسَـٰنُ عَجُولࣰا ۝١١", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "ويدعو الإنسان أحيانًا على نفسه أو ولده أو ماله بالشر، وذلك عند الغضب، مثل ما يدعو بالخير، وهذا من جهل الإنسان وعجلته، ومن رحمة الله به أنه يستجيب له في دعائه بالخير دون الشر؛ لأنه يعلم منه عدم القصد إلى إرادة ذلك، وكان الإنسان بطبعه عجولا.", "isBasmala": false, "translation_en": "The human being prays for evil as he prays for good. The human being is very hasty.", "translation_id": "Dan manusia mendoa untuk kejahatan sebagaimana ia mendoa untuk kebaikan. Dan adalah manusia bersifat tergesa-gesa.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 12, "text": "وَجَعَلۡنَا ٱلَّیۡلَ وَٱلنَّهَارَ ءَایَتَیۡنِۖ فَمَحَوۡنَاۤ ءَایَةَ ٱلَّیۡلِ وَجَعَلۡنَاۤ ءَایَةَ ٱلنَّهَارِ مُبۡصِرَةࣰ لِّتَبۡتَغُوا۟ فَضۡلࣰا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُوا۟ عَدَدَ ٱلسِّنِینَ وَٱلۡحِسَابَۚ وَكُلَّ شَیۡءࣲ فَصَّلۡنَـٰهُ تَفۡصِیلࣰا ۝١٢", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "وجعلنا الليل والنهار علامتين دالَّتين على وحدانيتنا وقدرتنا، فمَحَوْنا علامة الليل -وهي القمر- وجعلنا علامة النهار -وهي الشمس- مضيئة؛ ليبصر الإنسان في ضوء النهار كيف يتصرف في شؤون معاشه، ويخلد في الليل إلى السكن والراحة، وليعلم الناس -من تعاقب الليل والنهار- عدد السنين وحساب الأشهر والأيام، فيرتبون عليها ما يشاؤون من مصالحهم. وكل شيء بيَّناه تبيينًا كافيًا.", "isBasmala": false, "translation_en": "We have made the night and the day two wonders. We erased the wonder of the night, and made the wonder of the day revealing, that you may seek bounty from your Lord, and know the number of years, and the calculation. We have explained all things in detail.", "translation_id": "Dan Kami jadikan malam dan siang sebagai dua tanda, lalu Kami hapuskan tanda malam dan Kami jadikan tanda siang itu terang, agar kamu mencari kurnia dari Tuhanmu, dan supaya kamu mengetahui bilangan tahun-tahun dan perhitungan. Dan segala sesuatu telah Kami terangkan dengan jelas.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 13, "text": "وَكُلَّ إِنسَـٰنٍ أَلۡزَمۡنَـٰهُ طَـٰۤىِٕرَهُۥ فِی عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ كِتَـٰبࣰا یَلۡقَىٰهُ مَنشُورًا ۝١٣", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "وكل إنسان يجعل الله ما عمله مِن خير أو شر ملازمًا له، فلا يحاسَب بعمل غيره، ولا يحاسَب غيره بعمله، ويخرج الله له يوم القيامة كتابًا قد سُجِّلت فيه أعماله يراه مفتوحًا.", "isBasmala": false, "translation_en": "For every person We have attached his fate to his neck. And on the Day of Resurrection, We will bring out for him a book which he will find spread open.", "translation_id": "Dan tiap-tiap manusia itu telah Kami tetapkan amal perbuatannya (sebagaimana tetapnya kalung) pada lehernya. Dan Kami keluarkan baginya pada hari kiamat sebuah kitab yang dijumpainya terbuka.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 14, "text": "ٱقۡرَأۡ كِتَـٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡیَوۡمَ عَلَیۡكَ حَسِیبࣰا ۝١٤", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "يقال له: اقرأ كتاب أعمالك، فيقرأ، وإن لم يكن يعرف القراءة في الدنيا، تكفيك نفسك اليوم محصية عليك عملك، فتعرف ما عليها من جزاء. وهذا من أعظم العدل والإنصاف أن يقال للعبد: حاسِبْ نفسك، كفى بها حسيبًا عليك.", "isBasmala": false, "translation_en": "\"Read your book; today there will be none but yourself to call you to account.\"", "translation_id": "\"Bacalah kitabmu, cukuplah dirimu sendiri pada waktu ini sebagai penghisab terhadapmu\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 15, "text": "مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا یَهۡتَدِی لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا یَضِلُّ عَلَیۡهَاۚ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِینَ حَتَّىٰ نَبۡعَثَ رَسُولࣰا ۝١٥", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "من اهتدى فاتبع طريق الحق فإنما يعود ثواب ذلك عليه وحده، ومن حاد واتبع طريق الباطل فإنما يعود عقاب ذلك عليه وحده، ولا تحمل نفس مذنبة إثم نفس مذنبة أخرى. ولا يعذب الله أحدًا إلا بعد إقامة الحجة عليه بإرسال الرسل وإنزال الكتب.", "isBasmala": false, "translation_en": "Whoever is guided-is guided for his own good. And whoever goes astray-goes astray to his detriment. No burdened soul carries the burdens of another, nor do We ever punish until We have sent a messenger.", "translation_id": "Barangsiapa yang berbuat sesuai dengan hidayah (Allah), maka sesungguhnya dia berbuat itu untuk (keselamatan) dirinya sendiri; dan barangsiapa yang sesat maka sesungguhnya dia tersesat bagi (kerugian) dirinya sendiri. Dan seorang yang berdosa tidak dapat memikul dosa orang lain, dan Kami tidak akan mengazab sebelum Kami mengutus seorang rasul.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 16, "text": "وَإِذَاۤ أَرَدۡنَاۤ أَن نُّهۡلِكَ قَرۡیَةً أَمَرۡنَا مُتۡرَفِیهَا فَفَسَقُوا۟ فِیهَا فَحَقَّ عَلَیۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَـٰهَا تَدۡمِیرࣰا ۝١٦", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "وإذا أردنا إهلاك أهل قرية لظلمهم أَمَرْنا مترفيهم بطاعة الله وتوحيده وتصديق رسله، وغيرهم تبع لهم، فعصَوا أمر ربهم وكذَّبوا رسله، فحقَّ عليهم القول بالعذاب الذي لا مردَّ له، فاستأصلناهم بالهلاك التام.", "isBasmala": false, "translation_en": "When We decide to destroy a town, We command its affluent ones, they transgress in it, so the word becomes justified against it, and We destroy it completely.", "translation_id": "Dan jika Kami hendak membinasakan suatu negeri, maka Kami perintahkan kepada orang-orang yang hidup mewah di negeri itu (supaya mentaati Allah) tetapi mereka melakukan kedurhakaan dalam negeri itu, maka sudah sepantasnya berlaku terhadapnya perkataan (ketentuan Kami), kemudian Kami hancurkan negeri itu sehancur-hancurnya.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 17, "text": "وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحࣲۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِیرَۢا بَصِیرࣰا ۝١٧", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "وكثيرا أهلكنا من الأمم المكذبة رسلها مِن بعد نبي الله نوح. وكفى بربك -أيها الرسول- أنه عالم بجميع أعمال عباده، لا تخفى عليه خافية.", "isBasmala": false, "translation_en": "How many generations have We destroyed after Noah? Your Lord is sufficient as Knower and Beholder of the sins of his servants.", "translation_id": "Dan berapa banyaknya kaum sesudah Nuh telah Kami binasakan. Dan cukuplah Tuhanmu Maha Mengetahui lagi Maha Melihat dosa hamba-hamba-Nya.", "manzil": 4, "manzil_display": ""}], "284": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 18, "text": "مَّن كَانَ یُرِیدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِیهَا مَا نَشَاۤءُ لِمَن نُّرِیدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ یَصۡلَىٰهَا مَذۡمُومࣰا مَّدۡحُورࣰا ۝١٨", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "من كان طلبه الدنيا العاجلة، وسعى لها وحدها، ولم يصدِّق بالآخرة، ولم يعمل لها، عجَّل الله له فيها ما يشاؤه اللّه ويريده مما كتبه له في اللوح المحفوظ، ثم يجعل الله له في الآخرة جهنم، يدخلها ملومًا مطرودًا من رحمته عز وجل؛ وذلك بسبب إرادته الدنيا وسعيه لها دون الآخرة.", "isBasmala": false, "translation_en": "Whoever desires the fleeting life, We expedite for him what We decide to give him, to whomever We desire. Then We consign him to Hell, where he will roast, condemned and defeated.", "translation_id": "Barangsiapa menghendaki kehidupan sekarang (duniawi), maka Kami segerakan baginya di dunia itu apa yang kami kehendaki bagi orang yang kami kehendaki dan Kami tentukan baginya neraka jahannam; ia akan memasukinya dalam keadaan tercela dan terusir.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 19, "text": "وَمَنۡ أَرَادَ ٱلۡـَٔاخِرَةَ وَسَعَىٰ لَهَا سَعۡیَهَا وَهُوَ مُؤۡمِنࣱ فَأُو۟لَـٰۤىِٕكَ كَانَ سَعۡیُهُم مَّشۡكُورࣰا ۝١٩", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "ومَن قصد بعمله الصالح ثواب الدار الآخرة الباقية، وسعى لها بطاعة الله تعالى، وهو مؤمن بالله وثوابه وعظيم جزائه، فأولئك كان عملهم مقبولا مُدَّخرًا لهم عند ربهم، وسيثابون عليه.", "isBasmala": false, "translation_en": "But whoever desires the Hereafter, and pursues it as it should be pursued, while he is a believer; these-their effort will be appreciated.", "translation_id": "Dan barangsiapa yang menghendaki kehidupan akhirat dan berusaha ke arah itu dengan sungguh-sungguh sedang ia adalah mukmin, maka mereka itu adalah orang-orang yang usahanya dibalasi dengan baik.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 20, "text": "كُلࣰّا نُّمِدُّ هَـٰۤؤُلَاۤءِ وَهَـٰۤؤُلَاۤءِ مِنۡ عَطَاۤءِ رَبِّكَۚ وَمَا كَانَ عَطَاۤءُ رَبِّكَ مَحۡظُورًا ۝٢٠", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "كل فريق من العاملين للدنيا الفانية، والعاملين للآخرة الباقية نزيده مِن رزقنا، فنرزق المؤمنين والكافرين في الدنيا؛ فإن الرزق مِن عطاء ربك تفضلا منه، وما كان عطاء ربك ممنوعا من أحد مؤمنًا كان أم كافرًا.", "isBasmala": false, "translation_en": "To all-these and those-We extend from the gifts of your Lord. The gifts of your Lord are not restricted.", "translation_id": "Kepada masing-masing golongan baik golongan ini maupun golongan itu Kami berikan bantuan dari kemurahan Tuhanmu. Dan kemurahan Tuhanmu tidak dapat dihalangi.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 21, "text": "ٱنظُرۡ كَیۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲۚ وَلَلۡـَٔاخِرَةُ أَكۡبَرُ دَرَجَـٰتࣲ وَأَكۡبَرُ تَفۡضِیلࣰا ۝٢١", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "تأمل -أيها الرسول- في كيفية تفضيل الله بعض الناس على بعض في الدنيا في الرزق والعمل، ولَلآخرة أكبرُ درجات للمؤمنين وأكبر تفضيلا.", "isBasmala": false, "translation_en": "See how We have favored some of them over others; yet the Hereafter is greater in ranks, and greater in favors.", "translation_id": "Perhatikanlah bagaimana Kami lebihkan sebagian dari mereka atas sebagian (yang lain). Dan pasti kehidupan akhirat lebih tinggi tingkatnya dan lebih besar keutamaannya.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 22, "text": "لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومࣰا مَّخۡذُولࣰا ۝٢٢", "juz": 15, "hizb": "(* ح 29*)", "tafsir": "لا تجعل -أيها الإنسان- مع الله شريكًا له في عبادته، فتبوء بالمذمة والخِذْلان.", "isBasmala": false, "translation_en": "Do not set up another god with God, lest you become condemned and damned.", "translation_id": "Janganlah kamu adakan tuhan yang lain di samping Allah, agar kamu tidak menjadi tercela dan tidak ditinggalkan (Allah).", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 23, "text": "۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوۤا۟ إِلَّاۤ إِیَّاهُ وَبِٱلۡوَ ٰلِدَیۡنِ إِحۡسَـٰنًاۚ إِمَّا یَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَاۤ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَاۤ أُفࣲّ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلࣰا كَرِیمࣰا ۝٢٣", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "وأَمَر ربك -أيها الإنسان- وألزم وأوجب أن يفرد سبحانه وتعالى وحده بالعبادة، وأمر بالإحسان إلى الأب والأم، وبخاصة حالةُ الشيخوخة، فلا تضجر ولا تستثقل شيئًا تراه من أحدهما أو منهما، ولا تسمعهما قولا سيئًا، حتى ولا التأفيف الذي هو أدنى مراتب القول السيئ، ولا يصدر منك إليهما فعل قبيح، ولكن ارفق بهما، وقل لهما -دائما- قولا لينًا لطيفًا.", "isBasmala": false, "translation_en": "Your Lord has commanded that you worship none but Him, and that you be good to your parents. If either of them or both of them reach old age with you, do not say to them a word of disrespect, nor scold them, but say to them kind words.", "translation_id": "Dan Tuhanmu telah memerintahkan supaya kamu jangan menyembah selain Dia dan hendaklah kamu berbuat baik pada ibu bapakmu dengan sebaik-baiknya. Jika salah seorang di antara keduanya atau kedua-duanya sampai berumur lanjut dalam pemeliharaanmu, maka sekali-kali janganlah kamu mengatakan kepada keduanya perkataan \"ah\" dan janganlah kamu membentak mereka dan ucapkanlah kepada mereka perkataan yang mulia.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 24, "text": "وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّیَانِی صَغِیرࣰا ۝٢٤", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "وكُنْ لأمك وأبيك ذليلا متواضعًا رحمة بهما، واطلب من ربك أن يرحمهما برحمته الواسعة أحياءً وأمواتًا، كما صبرا على تربيتك طفلا ضعيف الحول والقوة.", "isBasmala": false, "translation_en": "And lower to them the wing of humility, out of mercy, and say, \"My Lord, have mercy on them, as they raised me when I was a child.\"", "translation_id": "Dan rendahkanlah dirimu terhadap mereka berdua dengan penuh kesayangan dan ucapkanlah: \"Wahai Tuhanku, kasihilah mereka keduanya, sebagaimana mereka berdua telah mendidik aku waktu kecil\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 25, "text": "رَّبُّكُمۡ أَعۡلَمُ بِمَا فِی نُفُوسِكُمۡۚ إِن تَكُونُوا۟ صَـٰلِحِینَ فَإِنَّهُۥ كَانَ لِلۡأَوَّ ٰبِینَ غَفُورࣰا ۝٢٥", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "ربكم -أيها الناس- أعلم بما في ضمائركم من خير وشر. إن تكن إرادتكم ومقاصدكم مرضاة الله وما يقربكم إليه، فإنه كان -سبحانه- للراجعين إليه في جميع الأوقات غفورًا، فمَن عَلِمَ الله أنه ليس في قلبه إلا الإنابة إليه ومحبته، فإنه يعفو عنه، ويغفر له ما يعرض من صغائر الذنوب، مما هو من مقتضى الطبائع البشرية.", "isBasmala": false, "translation_en": "Your Lord knows best what is in your minds. If you are righteous-He is Forgiving to the obedient.", "translation_id": "Tuhanmu lebih mengetahui apa yang ada dalam hatimu; jika kamu orang-orang yang baik, maka sesungguhnya Dia Maha Pengampun bagi orang-orang yang bertaubat.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 26, "text": "وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِینَ وَٱبۡنَ ٱلسَّبِیلِ وَلَا تُبَذِّرۡ تَبۡذِیرًا ۝٢٦", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "وأحسِنْ إلى كل مَن له صلة قرابة بك، وأعطه حقه من الإحسان والبر، وأعط المسكين المحتاج والمسافر المنقطع عن أهله وماله، ولا تنفق مالك في غير طاعة الله، أو على وجه الإسراف والتبذير.", "isBasmala": false, "translation_en": "And give the relative his rights, and the poor, and the wayfarer, and do not squander wastefully.", "translation_id": "Dan berikanlah kepada keluarga-keluarga yang dekat akan haknya, kepada orang miskin dan orang yang dalam perjalanan dan janganlah kamu menghambur-hamburkan (hartamu) secara boros.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 27, "text": "إِنَّ ٱلۡمُبَذِّرِینَ كَانُوۤا۟ إِخۡوَ ٰنَ ٱلشَّیَـٰطِینِۖ وَكَانَ ٱلشَّیۡطَـٰنُ لِرَبِّهِۦ كَفُورࣰا ۝٢٧", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "إن المسرفين والمنفقين أموالهم في معاصي الله هم أشباه الشياطين في الشر والفساد والمعصية، وكان الشيطان كثير الكفران شديدَ الجحود لنعمة ربه.", "isBasmala": false, "translation_en": "The extravagant are brethren of the devils, and the devil is ever ungrateful to his Lord.", "translation_id": "Sesungguhnya pemboros-pemboros itu adalah saudara-saudara syaitan dan syaitan itu adalah sangat ingkar kepada Tuhannya.", "manzil": 4, "manzil_display": ""}], "285": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 28, "text": "وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَاۤءَ رَحۡمَةࣲ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلࣰا مَّیۡسُورࣰا ۝٢٨", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "وإن أعرضت عن إعطاء هؤلاء الذين أُمِرْت بإعطائهم؛ لعدم وجود ما تعطيهم منه طلبًا لرزق تنتظره من عند ربك، فقل لهم قولا ليِّنًا لطيفًا، كالدعاء لهم بالغنى وسعة الرزق، وعِدْهم بأن الله إذا أيسر من فضله رزقًا أنك تعطيهم منه.", "isBasmala": false, "translation_en": "But if you turn away from them, seeking mercy from your Lord which you hope for, then say to them words of comfort.", "translation_id": "Dan jika kamu berpaling dari mereka untuk memperoleh rahmat dari Tuhanmu yang kamu harapkan, maka katakanlah kepada mereka ucapan yang pantas.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 29, "text": "وَلَا تَجۡعَلۡ یَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومࣰا مَّحۡسُورًا ۝٢٩", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "ولا تمسك يدك عن الإنفاق في سبيل الخير، مضيِّقًا على نفسك وأهلك والمحتاجين، ولا تسرف في الإنفاق، فتعطي فوق طاقتك، فتقعد ملومًا يلومك الناس ويذمونك، نادمًا على تبذيرك وضياع مالك.", "isBasmala": false, "translation_en": "And do not keep your hand tied to your neck, nor spread it out fully, lest you end up liable and regretful.", "translation_id": "Dan janganlah kamu jadikan tanganmu terbelenggu pada lehermu dan janganlah kamu terlalu mengulurkannya karena itu kamu menjadi tercela dan menyesal.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 30, "text": "إِنَّ رَبَّكَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِیرَۢا بَصِیرࣰا ۝٣٠", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "إن ربك يوسِّع الرزق على بعض الناس، ويضيِّقه على بعضهم، وَفْق علمه وحكمته سبحانه وتعالى. إنه هو المطَّلِع على خفايا عباده، لا يغيب عن علمه شيء من أحوالهم.", "isBasmala": false, "translation_en": "Your Lord expands the provision for whomever He wills, and restricts it. He is fully Informed, Observant of His servants.", "translation_id": "Sesungguhnya Tuhanmu melapangkan rezeki kepada siapa yang Dia kehendaki dan menyempitkannya; sesungguhnya Dia Maha Mengetahui lagi Maha Melihat akan hamba-hamba-Nya.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 31, "text": "وَلَا تَقۡتُلُوۤا۟ أَوۡلَـٰدَكُمۡ خَشۡیَةَ إِمۡلَـٰقࣲۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِیَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـࣰٔا كَبِیرࣰا ۝٣١", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "وإذا علمتم أن الرزق بيد الله سبحانه فلا تقتلوا -أيها الناس- أولادكم خوفًا من الفقر؛ فإنه -سبحانه- هو الرزاق لعباده، يرزق الأبناء كما يرزق الآباء، إنَّ قَتْلَ الأولاد ذنب عظيم.", "isBasmala": false, "translation_en": "And do not kill your children for fear of poverty. We provide for them, and for you. Killing them is a grave sin.", "translation_id": "Dan janganlah kamu membunuh anak-anakmu karena takut kemiskinan. Kamilah yang akan memberi rezeki kepada mereka dan juga kepadamu. Sesungguhnya membunuh mereka adalah suatu dosa yang besar.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 32, "text": "وَلَا تَقۡرَبُوا۟ ٱلزِّنَىٰۤۖ إِنَّهُۥ كَانَ فَـٰحِشَةࣰ وَسَاۤءَ سَبِیلࣰا ۝٣٢", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "ولا تقربوا الزنى ودواعيه؛ كي لا تقعوا فيه، إنه كان فعلا بالغ القبح، وبئس الطريق طريقه.", "isBasmala": false, "translation_en": "And do not come near adultery. It is immoral, and an evil way.", "translation_id": "Dan janganlah kamu mendekati zina; sesungguhnya zina itu adalah suatu perbuatan yang keji. Dan suatu jalan yang buruk.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 33, "text": "وَلَا تَقۡتُلُوا۟ ٱلنَّفۡسَ ٱلَّتِی حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومࣰا فَقَدۡ جَعَلۡنَا لِوَلِیِّهِۦ سُلۡطَـٰنࣰا فَلَا یُسۡرِف فِّی ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورࣰا ۝٣٣", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "ولا تقتلوا النفس التي حرم الله قَتْلها إلا بالحق الشرعي كالقصاص أو رجم الزاني المحصن أو قتل المرتد. ومن قُتِل بغير حق شرعي فقد جعلنا لولي أمره مِن وارث أو حاكم حجة في طلب قَتْل قاتله أو الدية، ولا يصح لولي أمر المقتول أن يجاوز حدَّ الله في القصاص كأن يقتل بالواحد اثنين أو جماعة، أو يُمَثِّل بالقاتل، إن الله معين وليَّ المقتول على القاتل حتى يتمكن مِن قَتْله قصاصًا.", "isBasmala": false, "translation_en": "And do not kill the soul which God has made sacred, except in the course of justice. If someone is killed unjustly, We have given his next of kin certain authority. But he should not be excessive in killing, for he will be supported.", "translation_id": "Dan janganlah kamu membunuh jiwa yang diharamkan Allah (membunuhnya), melainkan dengan suatu (alasan) yang benar. Dan barangsiapa dibunuh secara zalim, maka sesungguhnya Kami telah memberi kekuasaan kepada ahli warisnya, tetapi janganlah ahli waris itu melampaui batas dalam membunuh. Sesungguhnya ia adalah orang yang mendapat pertolongan.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 34, "text": "وَلَا تَقۡرَبُوا۟ مَالَ ٱلۡیَتِیمِ إِلَّا بِٱلَّتِی هِیَ أَحۡسَنُ حَتَّىٰ یَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُوا۟ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولࣰا ۝٣٤", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "ولا تتصرَّفوا في أموال الأطفال الذين مات آباؤهم، وصاروا في كفالتكم، إلا بالطريقة التي هي أحسن لهم، وهي التثمير والتنمية، حتى يبلغ الطفل اليتيم سنَّ البلوغ، وحسن التصرف في المال، وأتموا الوفاء بكل عهد التزمتم به. إن العهد يسأل الله عنه صاحبه يوم القيامة، فيثيبه إذا أتمه ووفَّاه، ويعاقبه إذا خان فيه.", "isBasmala": false, "translation_en": "And do not go near the orphan's property, except with the best of intentions, until he has reached his maturity. And honor your pledge, because the pledge involves responsibility.", "translation_id": "Dan janganlah kamu mendekati harta anak yatim, kecuali dengan cara yang lebih baik (bermanfaat) sampai ia dewasa dan penuhilah janji; sesungguhnya janji itu pasti diminta pertanggungan jawabnya.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 35, "text": "وَأَوۡفُوا۟ ٱلۡكَیۡلَ إِذَا كِلۡتُمۡ وَزِنُوا۟ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِیمِۚ ذَ ٰلِكَ خَیۡرࣱ وَأَحۡسَنُ تَأۡوِیلࣰا ۝٣٥", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "وأتموا الكيل، ولا تنقصوه إذا كِلْتم لغيركم، وزِنوا بالميزان السوي، إن العدل في الكيل والوزن خير لكم في الدنيا، وأحسن عاقبة عند الله في الآخرة.", "isBasmala": false, "translation_en": "And give full measure when you measure, and weigh with accurate scales. That is fair, and the best determination.", "translation_id": "Dan sempurnakanlah takaran apabila kamu menakar, dan timbanglah dengan neraca yang benar. Itulah yang lebih utama (bagimu) dan lebih baik akibatnya.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 36, "text": "وَلَا تَقۡفُ مَا لَیۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُو۟لَـٰۤىِٕكَ كَانَ عَنۡهُ مَسۡـُٔولࣰا ۝٣٦", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "ولا تتبع -أيها الإنسان- ما لا تعلم، بل تأكَّد وتثبَّت. إن الإنسان مسؤول عما استعمَل فيه سمعه وبصره وفؤاده، فإذا استعمَلها في الخير نال الثواب، وإذا استعملها في الشر نال العقاب.", "isBasmala": false, "translation_en": "And do not occupy yourself with what you have no knowledge of. The hearing, and the sight, and the brains-all these will be questioned.", "translation_id": "Dan janganlah kamu mengikuti apa yang kamu tidak mempunyai pengetahuan tentangnya. Sesungguhnya pendengaran, penglihatan dan hati, semuanya itu akan diminta pertanggungan jawabnya.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 37, "text": "وَلَا تَمۡشِ فِی ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولࣰا ۝٣٧", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "ولا تمش في الأرض مختالا متكبرا؛ فإنك لن تَخْرِق الأرض بالمشي عليها، ولن تبلغ الجبال طولا خيلاء وتكبرًا.", "isBasmala": false, "translation_en": "And do not walk proudly on earth. You can neither pierce the earth, nor can you match the mountains in height.", "translation_id": "Dan janganlah kamu berjalan di muka bumi ini dengan sombong, karena sesungguhnya kamu sekali-kali tidak dapat menembus bumi dan sekali-kali kamu tidak akan sampai setinggi gunung.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 38, "text": "كُلُّ ذَ ٰلِكَ كَانَ سَیِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهࣰا ۝٣٨", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "جميع ما تقدَّم ذِكْرُه من أوامر ونواهٍ، يكره الله سيِّئَه، ولا يرضاه لعباده.", "isBasmala": false, "translation_en": "The evil of all these is disliked by your Lord.", "translation_id": "Semua itu kejahatannya amat dibenci di sisi Tuhanmu.", "manzil": 4, "manzil_display": ""}], "286": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 39, "text": "ذَ ٰلِكَ مِمَّاۤ أَوۡحَىٰۤ إِلَیۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتُلۡقَىٰ فِی جَهَنَّمَ مَلُومࣰا مَّدۡحُورًا ۝٣٩", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "ذلك الذي بيَّناه ووضَّحناه من هذه الأحكام الجليلة، من الأمر بمحاسن الأعمال، والنهي عن أراذل الأخلاق مما أوحيناه إليك أيها النبي. ولا تجعل -أيها الإنسان- مع الله تعالى شريكًا له في عبادته، فتُقْذف في نار جهنم تلومك نفسك والناس، وتكون مطرودًا مبعدًا من كل خير.", "isBasmala": false, "translation_en": "That is some of the wisdom your Lord has revealed to you. Do not set up with God another god, or else you will be thrown in Hell, rebuked and banished.", "translation_id": "Itulah sebagian hikmah yang diwahyukan Tuhanmu kepadamu. Dan janganlah kamu mengadakan tuhan yang lain di samping Allah, yang menyebabkan kamu dilemparkan ke dalam neraka dalam keadaan tercela lagi dijauhkan (dari rahmat Allah).", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 40, "text": "أَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِینَ وَٱتَّخَذَ مِنَ ٱلۡمَلَـٰۤىِٕكَةِ إِنَـٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِیمࣰا ۝٤٠", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "أفخصَّكم ربكم -أيها المشركون- بإعطائكم البنين، واتخذ لنفسه الملائكة بنات؟ إن قولكم هذا بالغ القبح والبشاعة، لا يليق بالله سبحانه وتعالى.", "isBasmala": false, "translation_en": "Has your Lord favored you with sons, while choosing for Himself daughters from among the angels? You are indeed saying a terrible thing.", "translation_id": "Maka apakah patut Tuhan memilihkan bagimu anak-anak laki-laki sedang Dia sendiri mengambil anak-anak perempuan di antara para malaikat? Sesungguhnya kamu benar-benar mengucapkan kata-kata yang besar (dosanya).", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 41, "text": "وَلَقَدۡ صَرَّفۡنَا فِی هَـٰذَا ٱلۡقُرۡءَانِ لِیَذَّكَّرُوا۟ وَمَا یَزِیدُهُمۡ إِلَّا نُفُورࣰا ۝٤١", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "ولقد وضَّحْنا ونوَّعْنا في هذا القرآن الأحكام والأمثال والمواعظ؛ ليتعظ الناس ويتدبروا ما ينفعهم فيأخذوه، وما يضرهم فيدَعوه، وما يزيد البيان والتوضيح الظالمين إلا تباعدًا عن الحق، وغفلة عن النظر والاعتبار.", "isBasmala": false, "translation_en": "We have explained in this Quran in various ways, that they may remember, but it only adds to their rebellion.", "translation_id": "Dan sesungguhnya dalam Al Quran ini Kami telah ulang-ulangi (peringatan-peringatan), agar mereka selalu ingat. Dan ulangan peringatan itu tidak lain hanyalah menambah mereka lari (dari kebenaran).", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 42, "text": "قُل لَّوۡ كَانَ مَعَهُۥۤ ءَالِهَةࣱ كَمَا یَقُولُونَ إِذࣰا لَّٱبۡتَغَوۡا۟ إِلَىٰ ذِی ٱلۡعَرۡشِ سَبِیلࣰا ۝٤٢", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "قل -أيها الرسول- للمشركين: لو أن مع الله آلهة أخرى، إذًا لطلبَتْ تلك الآلهة طريقًا إلى مغالبة الله ذي العرش العظيم.", "isBasmala": false, "translation_en": "Say, \"If there were other gods with Him, as they say, they would have sought a way to the Lord of the Throne.\"", "translation_id": "Katakanlah: \"Jikalau ada tuhan-tuhan di samping-Nya, sebagaimana yang mereka katakan, niscaya tuhan-tuhan itu mencari jalan kepada Tuhan yang mempunyai 'Arsy\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 43, "text": "سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یَقُولُونَ عُلُوࣰّا كَبِیرࣰا ۝٤٣", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "تنزَّه الله وتقدَّس عَمَّا يقوله المشركون وتعالى علوًا كبيرًا.", "isBasmala": false, "translation_en": "Be He glorified. He is exalted, far above what they say.", "translation_id": "Maha Suci dan Maha Tinggi Dia dari apa yang mereka katakan dengan ketinggian yang sebesar-besarnya.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 44, "text": "تُسَبِّحُ لَهُ ٱلسَّمَـٰوَ ٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِیهِنَّۚ وَإِن مِّن شَیۡءٍ إِلَّا یُسَبِّحُ بِحَمۡدِهِۦ وَلَـٰكِن لَّا تَفۡقَهُونَ تَسۡبِیحَهُمۡۚ إِنَّهُۥ كَانَ حَلِیمًا غَفُورࣰا ۝٤٤", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "تُسَبِّح له -سبحانه- السموات السبع والأرضون، ومَن فيهن مِن جميع المخلوقات، وكل شيء في هذا الوجود ينزه الله تعالى تنزيهًا مقرونًا بالثناء والحمد له سبحانه، ولكن لا تدركون -أيها الناس- ذلك. إنه سبحانه كان حليمًا بعباده لا يعاجل مَن عصاه بالعقوبة، غفورًا لهم.", "isBasmala": false, "translation_en": "Praising Him are the seven heavens, and the earth, and everyone in them. There is not a thing that does not glorify Him with praise, but you do not understand their praises. He is indeed Forbearing and Forgiving.", "translation_id": "Langit yang tujuh, bumi dan semua yang ada di dalamnya bertasbih kepada Allah. Dan tak ada suatupun melainkan bertasbih dengan memuji-Nya, tetapi kamu sekalian tidak mengerti tasbih mereka. Sesungguhnya Dia adalah Maha Penyantun lagi Maha Pengampun.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 45, "text": "وَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَیۡنَكَ وَبَیۡنَ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ حِجَابࣰا مَّسۡتُورࣰا ۝٤٥", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "وإذا قرأت القرآن فسمعه هؤلاء المشركون، جعلنا بينك وبين الذين لا يؤمنون بالآخرة حجابًا ساترًا يحجب عقولهم عن فَهْمِ القرآن؛ عقابًا لهم على كفرهم وإنكارهم.", "isBasmala": false, "translation_en": "When you read the Quran, We place between you and those who do not believe in the Hereafter an invisible barrier.", "translation_id": "Dan apabila kamu membaca Al Quran niscaya Kami adakan antara kamu dan orang-orang yang tidak beriman kepada kehidupan akhirat, suatu dinding yang tertutup,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 46, "text": "وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن یَفۡقَهُوهُ وَفِیۤ ءَاذَانِهِمۡ وَقۡرࣰاۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِی ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡا۟ عَلَىٰۤ أَدۡبَـٰرِهِمۡ نُفُورࣰا ۝٤٦", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "وجعلنا على قلوب المشركين أغطية؛ لئلا يفهموا القرآن، وجعلنا في آذانهم صممًا؛ لئلا يسمعوه، وإذا ذَكَرْتَ ربك في القرآن داعيًا لتوحيده ناهيًا عن الشرك به رجعوا على أعقابهم نافرين من قولك؛ استكبارًا واستعظامًا من أن يوحِّدوا الله تعالى في عبادته.", "isBasmala": false, "translation_en": "And We drape veils over their hearts, preventing them from understanding it, and heaviness in their ears. And when you mention your Lord alone in the Quran, they turn their backs in aversion.", "translation_id": "dan Kami adakan tutupan di atas hati mereka dan sumbatan di telinga mereka, agar mereka tidak dapat memahaminya. Dan apabila kamu menyebut Tuhanmu saja dalam Al Quran, niscaya mereka berpaling ke belakang karena bencinya,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 47, "text": "نَّحۡنُ أَعۡلَمُ بِمَا یَسۡتَمِعُونَ بِهِۦۤ إِذۡ یَسۡتَمِعُونَ إِلَیۡكَ وَإِذۡ هُمۡ نَجۡوَىٰۤ إِذۡ یَقُولُ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلࣰا مَّسۡحُورًا ۝٤٧", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "نحن أعلم بالذي يستمعه رؤساء قريش، إذ يستمعون إليك، ومقاصدهم سيئة، فليس استماعهم لأجل الاسترشاد وقَبول الحق، ونعلم تَناجيهم حين يقولون: ما تتبعون إلا رجلا أصابه السحر فاختلط عقله.", "isBasmala": false, "translation_en": "We know well what they listen to, when they listen to you, as they conspire, when the wrongdoers say, \"You only follow a man bewitched.\"", "translation_id": "Kami lebih mengetahui dalam keadaan bagaimana mereka mendengarkan sewaktu mereka mendengarkan kamu, dan sewaktu mereka berbisik-bisik (yaitu) ketika orang-orang zalim itu berkata: \"Kamu tidak lain hanyalah mengikuti seorang laki-laki yang kena sihir\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 48, "text": "ٱنظُرۡ كَیۡفَ ضَرَبُوا۟ لَكَ ٱلۡأَمۡثَالَ فَضَلُّوا۟ فَلَا یَسۡتَطِیعُونَ سَبِیلࣰا ۝٤٨", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "تفكر -أيها الرسول- متعجبًا من قولهم: إن محمدًا ساحر شاعر مجنون!! فجاروا وانحرفوا، ولم يهتدوا إلى طريق الحق والصواب.", "isBasmala": false, "translation_en": "Note what they compared you to. They are lost, and unable to find a way.", "translation_id": "Lihatlah bagaimana mereka membuat perumpamaan-perumpamaan terhadapmu; karena itu mereka menjadi sesat dan tidak dapat lagi menemukan jalan (yang benar).", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 49, "text": "وَقَالُوۤا۟ أَءِذَا كُنَّا عِظَـٰمࣰا وَرُفَـٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقࣰا جَدِیدࣰا ۝٤٩", "juz": 15, "hizb": "(*¼ ح 29*)", "tafsir": "وقال المشركون منكرين أن يُخْلَقوا خَلْقًا جديدًا بعد أن تبلى عظامهم، وتصير فُتاتًا: أئِنا لمبعوثون يوم القيامة بعثًا جديدًا؟", "isBasmala": false, "translation_en": "And they say, \"When we have become bones and fragments, shall we really be resurrected as a new creation?\"", "translation_id": "Dan mereka berkata: \"Apakah bila kami telah menjadi tulang belulang dan benda-benda yang hancur, apa benar-benarkah kami akan dibangkitkan kembali sebagai makhluk yang baru?\"", "manzil": 4, "manzil_display": ""}], "287": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 50, "text": "۞ قُلۡ كُونُوا۟ حِجَارَةً أَوۡ حَدِیدًا ۝٥٠", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "قل لهم -أيها الرسول- على جهة التعجيز: كونوا حجارة أو حديدًا في الشدة والقوة -إن قَدَرْتم على ذلك- فإن الله يُعيدكم كما بدأكم، وذلك هيِّن عليه يسير.", "isBasmala": false, "translation_en": "Say, \"Even if you become rocks or iron.", "translation_id": "Katakanlah: \"Jadilah kamu sekalian batu atau besi,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 51, "text": "أَوۡ خَلۡقࣰا مِّمَّا یَكۡبُرُ فِی صُدُورِكُمۡۚ فَسَیَقُولُونَ مَن یُعِیدُنَاۖ قُلِ ٱلَّذِی فَطَرَكُمۡ أَوَّلَ مَرَّةࣲۚ فَسَیُنۡغِضُونَ إِلَیۡكَ رُءُوسَهُمۡ وَیَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰۤ أَن یَكُونَ قَرِیبࣰا ۝٥١", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "أو كونوا خلقًا يَعْظُم ويُسْتَبْعَد في عقولكم قبوله للبعث، فالله تعالى قادر على إعادتكم وبعثكم، وحين تقوم عليهم الحجة في قدرة الله على البعث والإحياء فسيقولون -منكرين-: مَن يردُّنا إلى الحياة بعد الموت؟ قل لهم: يعيدكم ويرجعكم الله الذي أنشأكم من العدم أول مرة، وعند سماعهم هذا الرد فسيَهُزُّون رؤوسهم ساخرين متعجبين ويقولون -مستبعدين-: متى يقع هذا البعث؟ قل: هو قريب؛ فإن كل آتٍ قريب.", "isBasmala": false, "translation_en": "Or some substance, which, in your minds, is even harder.\" Then they will say, \"Who will restore us?\" Say, \"The One who originated you the first time.\" Then they will nod their heads at you, and say, \"When will it be?\" Say, \"Perhaps it will be soon.\"", "translation_id": "atau suatu makhluk dari makhluk yang tidak mungkin (hidup) menurut pikiranmu\". Maka mereka akan bertanya: \"Siapa yang akan menghidupkan kami kembali?\" Katakanlah: \"Yang telah menciptakan kamu pada kali yang pertama\". Lalu mereka akan menggeleng-gelengkan kepala mereka kepadamu dan berkata: \"Kapan itu (akan terjadi)?\" Katakanlah: \"Mudah-mudahan waktu berbangkit itu dekat\",", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 52, "text": "یَوۡمَ یَدۡعُوكُمۡ فَتَسۡتَجِیبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِیلࣰا ۝٥٢", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "يوم يناديكم خالقكم للخروج من قبوركم، فتستجيبون لأمر الله، وتنقادون له، وله الحمد على كل حال، وتظنون -لهول يوم القيامة- أنكم ما أقمتم في الدنيا إلا زمنًا قليلا؛ لطول لبثكم في الآخرة.", "isBasmala": false, "translation_en": "On the Day when He calls you, you will respond with His praise, and you will realize that you stayed only a little.", "translation_id": "yaitu pada hari Dia memanggil kamu, lalu kamu mematuhi-Nya sambil memuji-Nya dan kamu mengira, bahwa kamu tidak berdiam (di dalam kubur) kecuali sebentar saja.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 53, "text": "وَقُل لِّعِبَادِی یَقُولُوا۟ ٱلَّتِی هِیَ أَحۡسَنُۚ إِنَّ ٱلشَّیۡطَـٰنَ یَنزَغُ بَیۡنَهُمۡۚ إِنَّ ٱلشَّیۡطَـٰنَ كَانَ لِلۡإِنسَـٰنِ عَدُوࣰّا مُّبِینࣰا ۝٥٣", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "وقل لعبادي المؤمنين يقولوا في تخاطبهم وتحاورهم الكلام الحسن الطيب؛ فإنهم إن لم يفعلوا ذلك ألقى الشيطان بينهم العداوة والفساد والخصام. إن الشيطان كان للإنسان عدوًا ظاهر العداوة.", "isBasmala": false, "translation_en": "Tell My servants to say what is best. Satan sows discord among them. Satan is to man an open enemy.", "translation_id": "Dan katakanlah kepada hamha-hamba-Ku: \"Hendaklah mereka mengucapkan perkataan yang lebih baik (benar). Sesungguhnya syaitan itu menimbulkan perselisihan di antara mereka. Sesungguhnya syaitan itu adalah musuh yang nyata bagi manusia.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 54, "text": "رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن یَشَأۡ یَرۡحَمۡكُمۡ أَوۡ إِن یَشَأۡ یُعَذِّبۡكُمۡۚ وَمَاۤ أَرۡسَلۡنَـٰكَ عَلَیۡهِمۡ وَكِیلࣰا ۝٥٤", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "ربكم أعلم بكم -أيها الناس- إن يشأ يرحمكم، فيوفقكم للإيمان، أو إن يشأ يمتكم على الكفر، فيعذبكم، وما أرسلناك -أيها الرسول- عليهم وكيلا تدبِّر أمرهم وتجازيهم على أفعالهم، وإنما مهمتك تبليغ ما أُرْسلتَ به، وبيان الصراط المستقيم.", "isBasmala": false, "translation_en": "Your Lord knows you best. If He wills, He will have mercy on you; and if He wills, He will punish you. We did not send you as their advocate.", "translation_id": "Tuhanmu lebih mengetahui tentang kamu. Dia akan memberi rahmat kepadamu jika Dia menghendaki dan Dia akan mengazabmu, jika Dia menghendaki. Dan, Kami tidaklah mengutusmu untuk menjadi penjaga bagi mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 55, "text": "وَرَبُّكَ أَعۡلَمُ بِمَن فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِیِّـۧنَ عَلَىٰ بَعۡضࣲۖ وَءَاتَیۡنَا دَاوُۥدَ زَبُورࣰا ۝٥٥", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "وربك -أيها النبي- أعلم بمَن في السموات والأرض. ولقد فَضَّلْنا بعض النبيين على بعض بالفضائل وكثرة الأتباع وإنزال الكتب، وأعطينا داود الزبور.", "isBasmala": false, "translation_en": "Your Lord knows well everyone in the heavens and the earth. We have given some prophets advantage over others; and to David We gave the Psalms.", "translation_id": "Dan Tuhan-mu lebih mengetahui siapa yang (ada) di langit dan di bumi. Dan sesungguhnya telah Kami lebihkan sebagian nabi-nabi itu atas sebagian (yang lain), dan Kami berikan Zabur kepada Daud.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 56, "text": "قُلِ ٱدۡعُوا۟ ٱلَّذِینَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا یَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِیلًا ۝٥٦", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "قل -أيها الرسول- لمشركي قومك: إن هذه المعبودات التي تنادونها لكشف الضرِّ عنكم لا تملك ذلك، ولا تقدر على تحويله عنكم إلى غيركم، ولا تقدر على تحويله من حال إلى حال، فالقادر على ذلك هو الله وحده. وهذه الآية عامة في كل ما يُدْعى من دون الله، ميتًا كان أو غائبًا، من الأنبياء والصالحين وغيرهم، بلفظ الاستغاثة أو الدعاء أو غيرهما، فلا معبود بحق إلا الله.", "isBasmala": false, "translation_en": "Say, \"Call upon those you claim besides Him. They have no power to relieve your adversity, nor can they change it.\"", "translation_id": "Katakanlah: \"Panggillah mereka yang kamu anggap (tuhan) selain Allah, maka mereka tidak akan mempunyai kekuasaan untuk menghilangkan bahaya daripadamu dan tidak pula memindahkannya\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 57, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ یَدۡعُونَ یَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِیلَةَ أَیُّهُمۡ أَقۡرَبُ وَیَرۡجُونَ رَحۡمَتَهُۥ وَیَخَافُونَ عَذَابَهُۥۤۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورࣰا ۝٥٧", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "أولئك الذين يدعوهم المشركون من الأنبياء والصالحين والملائكة مع الله، يتنافسون في القرب من ربهم بما يقدرون عليه من الأعمال الصالحة، ويأمُلون رحمته ويخافون عذابه، إن عذاب ربك هو ما ينبغي أن يحذره العباد، ويخافوا منه.", "isBasmala": false, "translation_en": "Those they call upon are themselves seeking means of access to their Lord, vying to be nearer, and hoping for His mercy, and fearing His punishment. The punishment of your Lord is to be dreaded.", "translation_id": "Orang-orang yang mereka seru itu, mereka sendiri mencari jalan kepada Tuhan mereka siapa di antara mereka yang lebih dekat (kepada Allah) dan mengharapkan rahmat-Nya dan takut akan azab-Nya; sesungguhnya azab Tuhanmu adalah suatu yang (harus) ditakuti.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 58, "text": "وَإِن مِّن قَرۡیَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ یَوۡمِ ٱلۡقِیَـٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابࣰا شَدِیدࣰاۚ كَانَ ذَ ٰلِكَ فِی ٱلۡكِتَـٰبِ مَسۡطُورࣰا ۝٥٨", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "ويتوعَّد الله الكفار بأنه ما من قريةٍ كافرة مكذبة للرسل إلا وسينزل بها عقابه بالهلاك في الدنيا قبل يوم القيامة أو بالعذاب الشديد لأهلها، كتاب كتبه الله وقضاء أبرمه لا بد مِن وقوعه، وهو مسطور في اللوح المحفوظ.", "isBasmala": false, "translation_en": "There is no city but We will destroy before the Day of Resurrection, or punish it with a severe punishment. This is inscribed in the Book.", "translation_id": "Tak ada suatu negeripun (yang durhaka penduduknya), melainkan Kami membinasakannya sebelum hari kiamat atau Kami azab (penduduknya) dengan azab yang sangat keras. Yang demikian itu telah tertulis di dalam kitab (Lauh Mahfuzh).", "manzil": 4, "manzil_display": ""}], "288": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 59, "text": "وَمَا مَنَعَنَاۤ أَن نُّرۡسِلَ بِٱلۡـَٔایَـٰتِ إِلَّاۤ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ وَءَاتَیۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةࣰ فَظَلَمُوا۟ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡـَٔایَـٰتِ إِلَّا تَخۡوِیفࣰا ۝٥٩", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "وما منعَنا من إنزال المعجزات التي سألها المشركون إلا تكذيب مَن سبقهم من الأمم، فقد أجابهم الله إلى ما طلبوا فكذَّبوا وهلكوا. وأعطينا ثمود -وهم قوم صالح- معجزة واضحة وهي الناقة، فكفروا بها فأهلكناهم. وما إرسالنا الرسل بالآيات والعبر والمعجزات التي جعلناها على أيديهم إلا تخويف للعباد؛ ليعتبروا ويتذكروا.", "isBasmala": false, "translation_en": "Nothing prevents Us from sending miraculous signs, except that the ancients called them lies. We gave Thamood the she-camel, a visible sign, but they mistreated her. We do not send the signs except to instill reverence.", "translation_id": "Dan sekali-kali tidak ada yang menghalangi Kami untuk mengirimkan (kepadamu) tanda-tanda (kekuasan Kami), melainkan karena tanda-tanda itu telah didustakan oleh orang-orang dahulu. Dan telah Kami berikan kepada Tsamud unta betina itu (sebagai mukjizat) yang dapat dilihat, tetapi mereka menganiaya unta betina itu. Dan Kami tidak memberi tanda-tanda itu melainkan untuk menakuti.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 60, "text": "وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡیَا ٱلَّتِیۤ أَرَیۡنَـٰكَ إِلَّا فِتۡنَةࣰ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِی ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا یَزِیدُهُمۡ إِلَّا طُغۡیَـٰنࣰا كَبِیرࣰا ۝٦٠", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "واذكر -أيها الرسول- حين قلنا لك: إن ربك أحاط بالناس علمًا وقدرة. وما جعلنا الرؤيا التي أريناكها عِيانًا ليلة الإسراء والمعراج من عجائب المخلوقات إلا اختبارًا للناس؛ ليتميز كافرهم من مؤمنهم، وما جعلنا شجرة الزقوم الملعونة التي ذكرت في القرآن إلا ابتلاء للناس. ونخوِّف المشركين بأنواع العذاب والآيات، ولا يزيدهم التخويف إلا تماديًا في الكفر والضلال.", "isBasmala": false, "translation_en": "We said to you that your Lord encompasses humanity. We did not make the vision We showed you, except as a test for the people, and the tree cursed in the Quran. We frighten them, but that only increases their defiance.", "translation_id": "Dan (ingatlah), ketika Kami wahyukan kepadamu: \"Sesungguhnya (ilmu) Tuhanmu meliputi segala manusia\". Dan Kami tidak menjadikan mimpi yang telah Kami perlihatkan kepadamu, melainkan sebagai ujian bagi manusia dan (begitu pula) pohon kayu yang terkutuk dalam Al Quran. Dan Kami menakut-nakuti mereka, tetapi yang demikian itu hanyalah menambah besar kedurhakaan mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 61, "text": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَقۡتَ طِینࣰا ۝٦١", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "واذكر قولنا للملائكة: اسجدوا لآدم تحية وتكريمًا، فسجدوا جميعًا إلا إبليس، استكبر وامتنع عن السجود قائلا على سبيل الإنكار والاستكبار: أأسجد لهذا الضعيف، المخلوق من الطين؟", "isBasmala": false, "translation_en": "When We said to the angels, \"Bow down before Adam,\" they bowed down, except for Satan. He said, \"Shall I bow down before someone You created from mud?\"", "translation_id": "Dan (ingatlah), tatkala Kami berfirman kepada para malaikat: \"Sujudlah kamu semua kepada Adam\", lalu mereka sujud kecuali iblis. Dia berkata: \"Apakah aku akan sujud kepada orang yang Engkau ciptakan dari tanah?\"", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 62, "text": "قَالَ أَرَءَیۡتَكَ هَـٰذَا ٱلَّذِی كَرَّمۡتَ عَلَیَّ لَىِٕنۡ أَخَّرۡتَنِ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّیَّتَهُۥۤ إِلَّا قَلِیلࣰا ۝٦٢", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "وقال إبليس جراءة على الله وكفرًا به: أرأيت هذا المخلوق الذي ميزته عليَّ؟ لئن أبقيتني حيًا إلى يوم القيامة لأستولينَّ على ذريته بالإغواء والإفساد، إلا المخلصين منهم في الإيمان، وهم قليل.", "isBasmala": false, "translation_en": "He said, \"Do You see this one whom You have honored more than me? If You reprieve me until the Day of Resurrection, I will bring his descendants under my sway, except for a few.\"", "translation_id": "Dia (iblis) berkata: \"Terangkanlah kepadaku inikah orangnya yang Engkau muliakan atas diriku? Sesungguhnya jika Engkau memberi tangguh kepadaku sampai hari kiamat, niscaya benar-benar akan aku sesatkan keturunannya, kecuali sebahagian kecil\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 63, "text": "قَالَ ٱذۡهَبۡ فَمَن تَبِعَكَ مِنۡهُمۡ فَإِنَّ جَهَنَّمَ جَزَاۤؤُكُمۡ جَزَاۤءࣰ مَّوۡفُورࣰا ۝٦٣", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "قال الله تعالى مهددًا إبليس وأتباعه: اذهب فمَن تبعك مِن ذرية آدم، فأطاعك، فإن عقابك وعقابهم وافر في نار جهنم.", "isBasmala": false, "translation_en": "He said, \"Begone! Whoever of them follows you-Hell is your reward, an ample reward.\"", "translation_id": "Tuhan berfirman: \"Pergilah, barangsiapa di antara mereka yang mengikuti kamu, maka sesungguhnya neraka Jahannam adalah balasanmu semua, sebagai suatu pembalasan yang cukup.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 64, "text": "وَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَیۡهِم بِخَیۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ فِی ٱلۡأَمۡوَ ٰلِ وَٱلۡأَوۡلَـٰدِ وَعِدۡهُمۡۚ وَمَا یَعِدُهُمُ ٱلشَّیۡطَـٰنُ إِلَّا غُرُورًا ۝٦٤", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "واستَخْفِف كل مَن تستطيع استخفافه منهم بدعوتك إياه إلى معصيتي، واجمع عليهم كل ما تقدر عليه مِن جنودك من كل راكب وراجل، واجعل لنفسك شِرْكة في أموالهم بأن يكسبوها من الحرام، وشِرْكة في الأولاد بتزيين الزنى والمعاصي، ومخالفة أوامر الله حتى يكثر الفجور والفساد، وعِدْ أتباعك مِن ذرية آدم الوعود الكاذبة، فكل وعود الشيطان باطلة وغرور.", "isBasmala": false, "translation_en": "\"And entice whomever of them you can with your voice, and rally against them your cavalry and your infantry, and share with them in wealth and children, and make promises to them.\" But Satan promises them nothing but delusion.", "translation_id": "Dan hasunglah siapa yang kamu sanggupi di antara mereka dengan ajakanmu, dan kerahkanlah terhadap mereka pasukan berkuda dan pasukanmu yang berjalan kaki dan berserikatlah dengan mereka pada harta dan anak-anak dan beri janjilah mereka. Dan tidak ada yang dijanjikan oleh syaitan kepada mereka melainkan tipuan belaka.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 65, "text": "إِنَّ عِبَادِی لَیۡسَ لَكَ عَلَیۡهِمۡ سُلۡطَـٰنࣱۚ وَكَفَىٰ بِرَبِّكَ وَكِیلࣰا ۝٦٥", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "إن عبادي المؤمنين المخلصين الذين أطاعوني ليس لك قدرة على إغوائهم، وكفى بربك -أيها النبي- عاصمًا وحافظًا للمؤمنين مِن كيد الشيطان وغروره.", "isBasmala": false, "translation_en": "\"As for My devotees, you have no authority over them.\" Your Lord is an adequate Guardian.", "translation_id": "Sesungguhnya hamba-hamba-Ku, kamu tidak dapat berkuasa atas mereka. Dan cukuplah Tuhan-mu sebagai Penjaga\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 66, "text": "رَّبُّكُمُ ٱلَّذِی یُزۡجِی لَكُمُ ٱلۡفُلۡكَ فِی ٱلۡبَحۡرِ لِتَبۡتَغُوا۟ مِن فَضۡلِهِۦۤۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِیمࣰا ۝٦٦", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "ربكم -أيها الناس- هو الذي يُسَيِّر لكم السفن في البحر؛ لتطلبوا رزق الله في أسفاركم وتجاراتكم. إن الله سبحانه كان رحيمًا بعباده.", "isBasmala": false, "translation_en": "Your Lord is He who propels for you the ships at sea, that you may seek of His bounty. He is towards you Most Merciful.", "translation_id": "Tuhan-mu adalah yang melayarkan kapal-kapal di lautan untukmu, agar kamu mencari sebahagian dari karunia-Nya. Sesungguhnya Dia adalah Maha Penyayang terhadapmu.", "manzil": 4, "manzil_display": ""}], "289": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 67, "text": "وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِی ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّاۤ إِیَّاهُۖ فَلَمَّا نَجَّىٰكُمۡ إِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَـٰنُ كَفُورًا ۝٦٧", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "وإذا أصابتكم شدة في البحر حتى أشرفتم على الغرق والهلاك، غاب عن عقولكم الذين تعبدونهم من الآلهة، وتذكَّرتم الله القدير وحده؛ ليغيثكم وينقذكم، فأخلصتم له في طلب العون والإغاثة، فأغاثكم ونجَّاكم، فلمَّا نجاكم إلى البر أعرضتم عن الإيمان والإخلاص والعمل الصالح، وهذا من جهل الإنسان وكفره. وكان الإنسان جحودًا لنعم الله عزَّ وجل.", "isBasmala": false, "translation_en": "When harm afflicts you at sea, those you pray to vanish, except for Him. But when He saves you to land, you turn away. The human being is ever thankless.", "translation_id": "Dan apabila kamu ditimpa bahaya di lautan, niscaya hilanglah siapa yang kamu seru kecuali Dia, Maka tatkala Dia menyelamatkan kamu ke daratan, kamu berpaling. Dan manusia itu adalah selalu tidak berterima kasih.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 68, "text": "أَفَأَمِنتُمۡ أَن یَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ یُرۡسِلَ عَلَیۡكُمۡ حَاصِبࣰا ثُمَّ لَا تَجِدُوا۟ لَكُمۡ وَكِیلًا ۝٦٨", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "أغَفَلْتم -أيها الناس- عن عذاب الله، فأمنتم أن تنهار بكم الأرض خسفًا، أو يُمْطركم الله بحجارة من السماء فتقتلكم، ثم لا تجدوا أحدًا يحفظكم مِن عذابه؟", "isBasmala": false, "translation_en": "Are you confident that He will not cause a track of land to cave in beneath you, or unleash a tornado against you, and then you find no protector?", "translation_id": "Maka apakah kamu merasa aman (dari hukuman Tuhan) yang menjungkir balikkan sebagian daratan bersama kamu atau Dia meniupkan (angin keras yang membawa) batu-batu kecil? dan kamu tidak akan mendapat seorang pelindungpun bagi kamu,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 69, "text": "أَمۡ أَمِنتُمۡ أَن یُعِیدَكُمۡ فِیهِ تَارَةً أُخۡرَىٰ فَیُرۡسِلَ عَلَیۡكُمۡ قَاصِفࣰا مِّنَ ٱلرِّیحِ فَیُغۡرِقَكُم بِمَا كَفَرۡتُمۡ ثُمَّ لَا تَجِدُوا۟ لَكُمۡ عَلَیۡنَا بِهِۦ تَبِیعࣰا ۝٦٩", "juz": 15, "hizb": "(*½ ح 29*)", "tafsir": "أم أمنتم -أيها الناس- ربكم، وقد كفرتم به أن يعيدكم في البحر مرة أخرى، فيرسل عليكم ريحًا شديدة، تكسِّر كل ما أتت عليه، فيغرقكم بسبب كفركم، ثم لا تجدوا لكم علينا أي تبعة ومطالبة؛ فإن الله لم يظلمكم مثقال ذرة؟", "isBasmala": false, "translation_en": "Or are you confident that He will not return you to it once again, and unleash a hurricane against you, and drown you for your ingratitude? Then you will find no helper against Us.", "translation_id": "atau apakah kamu merasa aman dari dikembalikan-Nya kamu ke laut sekali lagi, lalu Dia meniupkan atas kamu angin taupan dan ditenggelamkan-Nya kamu disebabkan kekafiranmu. Dan kamu tidak akan mendapat seorang penolongpun dalam hal ini terhadap (siksaan) Kami.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 70, "text": "۞ وَلَقَدۡ كَرَّمۡنَا بَنِیۤ ءَادَمَ وَحَمَلۡنَـٰهُمۡ فِی ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَـٰهُم مِّنَ ٱلطَّیِّبَـٰتِ وَفَضَّلۡنَـٰهُمۡ عَلَىٰ كَثِیرࣲ مِّمَّنۡ خَلَقۡنَا تَفۡضِیلࣰا ۝٧٠", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ولقد كرَّمنا ذرية آدم بالعقل وإرسال الرسل، وسَخَّرنا لهم جميع ما في الكون، وسَخَّرنا لهم الدواب في البر والسفن في البحر لحملهم، ورزقناهم من طيبات المطاعم والمشارب، وفضَّلناهم على كثير من المخلوقات تفضيلا عظيمًا.", "isBasmala": false, "translation_en": "We have honored the Children of Adam, and carried them on land and sea, and provided them with good things, and greatly favored them over many of those We created.", "translation_id": "Dan sesungguhnya telah Kami muliakan anak-anak Adam, Kami angkut mereka di daratan dan di lautan, Kami beri mereka rezeki dari yang baik-baik dan Kami lebihkan mereka dengan kelebihan yang sempurna atas kebanyakan makhluk yang telah Kami ciptakan.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 71, "text": "یَوۡمَ نَدۡعُوا۟ كُلَّ أُنَاسِۭ بِإِمَـٰمِهِمۡۖ فَمَنۡ أُوتِیَ كِتَـٰبَهُۥ بِیَمِینِهِۦ فَأُو۟لَـٰۤىِٕكَ یَقۡرَءُونَ كِتَـٰبَهُمۡ وَلَا یُظۡلَمُونَ فَتِیلࣰا ۝٧١", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "اذكر -أيها الرسول- يوم البعث مبشرًا ومخوفًا، حين يدعو الله عز وجل كل جماعة من الناس مع إمامهم الذي كانوا يقتدون به في الدنيا، فمن كان منهم صالحًا، وأُعطي كتاب أعماله بيمينه، فهؤلاء يقرؤون كتاب حسناتهم فرحين مستبشرين، ولا يُنْقَصون من ثواب أعمالهم الصالحة شيئًا، وإن كان مقدارَ الخيط الذي يكون في شَقِّ النواة.", "isBasmala": false, "translation_en": "On the Day when We call every people with their leader. Whoever is given his record in his right hand-these will read their record, and they will not be wronged one bit.", "translation_id": "(Ingatlah) suatu hari (yang di hari itu) Kami panggil tiap umat dengan pemimpinnya; dan barangsiapa yang diberikan kitab amalannya di tangan kanannya maka mereka ini akan membaca kitabnya itu, dan mereka tidak dianiaya sedikitpun.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 72, "text": "وَمَن كَانَ فِی هَـٰذِهِۦۤ أَعۡمَىٰ فَهُوَ فِی ٱلۡـَٔاخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِیلࣰا ۝٧٢", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ومن كان في هذه الدنيا أعمى القلب عن دلائل قدرة الله فلم يؤمن بما جاء به الرسول محمد صلى الله عليه وسلم فهو في يوم القيامة أشدُّ عمى عن سلوك طريق الجنة، وأضل طريقًا عن الهداية والرشاد.", "isBasmala": false, "translation_en": "But whoever is blind in this, he will be blind in the Hereafter, and further astray from the way.", "translation_id": "Dan barangsiapa yang buta (hatinya) di dunia ini, niscaya di akhirat (nanti) ia akan lebih buta (pula) dan lebih tersesat dari jalan (yang benar).", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 73, "text": "وَإِن كَادُوا۟ لَیَفۡتِنُونَكَ عَنِ ٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ لِتَفۡتَرِیَ عَلَیۡنَا غَیۡرَهُۥۖ وَإِذࣰا لَّٱتَّخَذُوكَ خَلِیلࣰا ۝٧٣", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ولقد قارب المشركون أن يصرفوك -أيها الرسول- عن القرآن الذي أنزله الله إليك؛ لتختلق علينا غير ما أوحينا إليك، ولو فعلت ما أرادوه لاتخذوك حبيبًا خالصًا.", "isBasmala": false, "translation_en": "They almost lured you away from what We have revealed to you, so that you would invent something else in Our name. In that case, they would have taken you for a friend.", "translation_id": "Dan sesungguhnya mereka hampir memalingkan kamu dari apa yang telah Kami wahyukan kepadamu, agar kamu membuat yang lain secara bohong terhadap Kami; dan kalau sudah begitu tentulah mereka mengambil kamu jadi sahabat yang setia.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 74, "text": "وَلَوۡلَاۤ أَن ثَبَّتۡنَـٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَیۡهِمۡ شَیۡـࣰٔا قَلِیلًا ۝٧٤", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ولولا أن ثبَّتناك على الحق، وعصمناك عن موافقتهم، لَقاربْتَ أن تميل إليهم ميلا قليلا من كثرة المعالجة ورغبتك في هدايتهم.", "isBasmala": false, "translation_en": "Had We not given you stability, you might have inclined towards them a little.", "translation_id": "Dan kalau Kami tidak memperkuat (hati)mu, niscaya kamu hampir-hampir condong sedikit kepada mereka,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 75, "text": "إِذࣰا لَّأَذَقۡنَـٰكَ ضِعۡفَ ٱلۡحَیَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَیۡنَا نَصِیرࣰا ۝٧٥", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ولو رَكَنت -أيها الرسول- إلى هؤلاء المشركين ركونًا قليلا فيما سألوك، إذًا لأذقناك مِثْلَي عذاب الحياة في الدنيا ومثْلَي عذاب الممات في الآخرة؛ وذلك لكمال نعمة الله عليك وكمال معرفتك، ثم لا تجد أحدًا ينصرك ويدفع عنك عذابنا.", "isBasmala": false, "translation_en": "Then We would have made you taste double in life, and double at death; then you would have found for yourself no helper against Us.", "translation_id": "kalau terjadi demikian, benar-benarlah Kami akan rasakan kepadamu (siksaan) berlipat ganda di dunia ini dan begitu (pula siksaan) berlipat ganda sesudah mati, dan kamu tidak akan mendapat seorang penolongpun terhadap Kami.", "manzil": 4, "manzil_display": ""}], "290": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 76, "text": "وَإِن كَادُوا۟ لَیَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِیُخۡرِجُوكَ مِنۡهَاۖ وَإِذࣰا لَّا یَلۡبَثُونَ خِلَـٰفَكَ إِلَّا قَلِیلࣰا ۝٧٦", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ولقد قارب الكفار أن يخرجوك من \"مكة\" بإزعاجهم إيَّاك، ولو أخرجوك منها لم يمكثوا فيها بعدك إلا زمنًا قليلا حتى تحل بهم العقوبة العاجلة.", "isBasmala": false, "translation_en": "They almost provoked you, to expel you from the land. In that case, they would not have lasted after you, except briefly.", "translation_id": "Dan sesungguhnya benar-benar mereka hampir membuatmu gelisah di negeri (Mekah) untuk mengusirmu daripadanya dan kalau terjadi demikian, niscaya sepeninggalmu mereka tidak tinggal, melainkan sebentar saja.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 77, "text": "سُنَّةَ مَن قَدۡ أَرۡسَلۡنَا قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِیلًا ۝٧٧", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "تلك سنة الله تعالى في إهلاك الأمة التي تُخرج رسولها من بينها، ولن تجد -أيها الرسول- لسنتنا تغييرًا، فلا خلف في وعدنا.", "isBasmala": false, "translation_en": "The tradition of the messengers We sent before you-you will find no change in Our rules.", "translation_id": "(Kami menetapkan yang demikian) sebagai suatu ketetapan terhadap rasul-rasul Kami yang Kami utus sebelum kamu dan tidak akan kamu dapati perubahan bagi ketetapan Kami itu.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 78, "text": "أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّیۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودࣰا ۝٧٨", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "أقم الصلاة تامة من وقت زوال الشمس عند الظهيرة إلى وقت ظلمة الليل، ويدخل في هذا صلاة الظهر والعصر والمغرب والعشاء، وأقم صلاة الفجر، وأَطِلِ القراءة فيها؛ إن صلاة الفجر تحضرها ملائكة الليل وملائكة النهار.", "isBasmala": false, "translation_en": "Perform the prayer at the decline of the sun, until the darkness of the night; and the Quran at dawn. The Quran at dawn is witnessed.", "translation_id": "Dirikanlah shalat dari sesudah matahari tergelincir sampai gelap malam dan (dirikanlah pula shalat) subuh. Sesungguhnya shalat subuh itu disaksikan (oleh malaikat).", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 79, "text": "وَمِنَ ٱلَّیۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةࣰ لَّكَ عَسَىٰۤ أَن یَبۡعَثَكَ رَبُّكَ مَقَامࣰا مَّحۡمُودࣰا ۝٧٩", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "وقم -أيها النبي- من نومك بعض الليل، فاقرأ القرآن في صلاة الليل؛ لتكون صلاة الليل زيادة لك في علو القدر ورفع الدرجات، عسى أن يبعثك الله شافعًا للناس يوم القيامة؛ ليرحمهم الله مما يكونون فيه، وتقوم مقامًا يحمدك فيه الأولون والآخرون.", "isBasmala": false, "translation_en": "And keep vigil with it during parts of the night, as an extra prayer. Perhaps your Lord will raise you to a laudable position.", "translation_id": "Dan pada sebahagian malam hari bersembahyang tahajudlah kamu sebagai suatu ibadah tambahan bagimu; mudah-mudahan Tuhan-mu mengangkat kamu ke tempat yang terpuji.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 80, "text": "وَقُل رَّبِّ أَدۡخِلۡنِی مُدۡخَلَ صِدۡقࣲ وَأَخۡرِجۡنِی مُخۡرَجَ صِدۡقࣲ وَٱجۡعَل لِّی مِن لَّدُنكَ سُلۡطَـٰنࣰا نَّصِیرࣰا ۝٨٠", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "وقل: ربِّ أدخلني فيما هو خير لي مدخل صدق، وأخرجني مما هو شر لي مخرج صدق، واجعل لي مِن لدنك حجة ثابتة، تنصرني بها على جميع مَن خالفني.", "isBasmala": false, "translation_en": "And say, \"My Lord, lead me in through an entry of truth, and lead me out through an exit of truth, and grant me from You a supporting power.\"", "translation_id": "Dan katakanlah: \"Ya Tuhan-ku, masukkanlah aku secara masuk yang benar dan keluarkanlah (pula) aku secara keluar yang benar dan berikanlah kepadaku dari sisi Engkau kekuasaan yang menolong.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 81, "text": "وَقُلۡ جَاۤءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَـٰطِلُۚ إِنَّ ٱلۡبَـٰطِلَ كَانَ زَهُوقࣰا ۝٨١", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "وقل -أيها الرسول- للمشركين: جاء الإسلام وذهب الشرك، إن الباطل لا بقاء له ولا ثبات، والحق هو الثابت الباقي الذي لا يزول.", "isBasmala": false, "translation_en": "And say, \"The truth has come, and falsehood has withered away; for falsehood is bound to wither away.\"", "translation_id": "Dan katakanlah: \"Yang benar telah datang dan yang batil telah lenyap\". Sesungguhnya yang batil itu adalah sesuatu yang pasti lenyap.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 82, "text": "وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَاۤءࣱ وَرَحۡمَةࣱ لِّلۡمُؤۡمِنِینَ وَلَا یَزِیدُ ٱلظَّـٰلِمِینَ إِلَّا خَسَارࣰا ۝٨٢", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "وننزل من آيات القرآن العظيم ما يشفي القلوب مِنَ الأمراض، كالشك والنفاق والجهالة، وما يشفي الأبدان برُقْيتها به، وما يكون سببًا للفوز برحمة الله بما فيه من الإيمان، ولا يزيد هذا القرآن الكفار عند سماعه إلا كفرًا وضلالا؛ لتكذيبهم به وعدم إيمانهم.", "isBasmala": false, "translation_en": "We send down in the Quran healing and mercy for the believers, but it increases the wrongdoers only in loss.", "translation_id": "Dan Kami turunkan dari Al Quran suatu yang menjadi penawar dan rahmat bagi orang-orang yang beriman dan Al Quran itu tidaklah menambah kepada orang-orang yang zalim selain kerugian.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 83, "text": "وَإِذَاۤ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَـٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ یَـُٔوسࣰا ۝٨٣", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "وإذا أنعمنا على الإنسان من حيث هو بمال وعافية ونحوهما، تولَّى وتباعد عن طاعة ربه، وإذا أصابته شدة مِن فقر أو مرض كان قنوطًا؛ لأنه لا يثق بفضل الله تعالى، إلا من عصم الله في حالتي سرَّائه وضرَّائه.", "isBasmala": false, "translation_en": "When We bless the human being, he turns away and distances himself. But when adversity touches him, he is in despair.", "translation_id": "Dan apabila Kami berikan kesenangan kepada manusia niscaya berpalinglah dia; dan membelakang dengan sikap yang sombong; dan apabila dia ditimpa kesusahan niscaya dia berputus asa.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 84, "text": "قُلۡ كُلࣱّ یَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ سَبِیلࣰا ۝٨٤", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "قل -أيها الرسول- للناس: كل واحد منكم يعمل على ما يليق به من الأحوال، فربكم أعلم بمن هو أهدى طريقًا إلى الحق.", "isBasmala": false, "translation_en": "Say, \"Each does according to his disposition. Your Lord knows best who is better guided in the way.\"", "translation_id": "Katakanlah: \"Tiap-tiap orang berbuat menurut keadaannya masing-masing\". Maka Tuhanmu lebih mengetahui siapa yang lebih benar jalannya.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 85, "text": "وَیَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّی وَمَاۤ أُوتِیتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِیلࣰا ۝٨٥", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ويسألك الكفار عن حقيقة الروح تعنتًا، فأجبهم بأن حقيقة الروح وأحوالها من الأمور التي استأثر الله بعلمها، وما أُعطيتم أنتم وجميع الناس من العلم إلا شيئًا قليلا.", "isBasmala": false, "translation_en": "And they ask you about the Spirit. Say, \"The Spirit belongs to the domain of my Lord; and you were given only little knowledge.\"", "translation_id": "Dan mereka bertanya kepadamu tentang roh. Katakanlah: \"Roh itu termasuk urusan Tuhan-ku, dan tidaklah kamu diberi pengetahuan melainkan sedikit\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 86, "text": "وَلَىِٕن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَیۡنَا وَكِیلًا ۝٨٦", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ولئن شئنا مَحْوَ القرآن من قلبك لَقدَرْنا على ذلك، ثم لا تجد لنفسك ناصرًا يمنعنا من فعل ذلك، أو يرد عليك القرآن.", "isBasmala": false, "translation_en": "If We willed, We could take away what We revealed to you. Then you will find for yourself no protecting guardian against Us.", "translation_id": "Dan sesungguhnya jika Kami menghendaki, niscaya Kami lenyapkan apa yang telah Kami wahyukan kepadamu, dan dengan pelenyapan itu, kamu tidak akan mendapatkan seorang pembelapun terhadap Kami,", "manzil": 4, "manzil_display": ""}], "291": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 87, "text": "إِلَّا رَحۡمَةࣰ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَیۡكَ كَبِیرࣰا ۝٨٧", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "لكنَّ الله رحمك، فأثبت ذلك في قلبك، إن فضله كان عليك عظيمًا؛ فقد أعطاك هذا القرآن العظيم، والمقام المحمود، وغير ذلك مما لم يؤته أحدًا من العالمين.", "isBasmala": false, "translation_en": "Except through a mercy from your Lord. His favors upon you have been great.", "translation_id": "kecuali karena rahmat dari Tuhanmu. Sesungguhnya karunia-Nya atasmu adalah besar.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 88, "text": "قُل لَّىِٕنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰۤ أَن یَأۡتُوا۟ بِمِثۡلِ هَـٰذَا ٱلۡقُرۡءَانِ لَا یَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضࣲ ظَهِیرࣰا ۝٨٨", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "قل: لو اتفقت الإنس والجن على محاولة الإتيان بمثل هذا القرآن المعجز لا يستطيعون الإتيان به، ولو تعاونوا وتظاهروا على ذلك.", "isBasmala": false, "translation_en": "Say, \"If mankind and jinn came together to produce the like of this Quran, they could never produce the like of it, even if they backed up one another.\"", "translation_id": "Katakanlah: \"Sesungguhnya jika manusia dan jin berkumpul untuk membuat yang serupa Al Quran ini, niscaya mereka tidak akan dapat membuat yang serupa dengan dia, sekalipun sebagian mereka menjadi pembantu bagi sebagian yang lain\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 89, "text": "وَلَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِی هَـٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲ فَأَبَىٰۤ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورࣰا ۝٨٩", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ولقد بيَّنَّا ونَوَّعنا للناس في هذا القرآن من كل مثل ينبغي الاعتبار به؛ احتجاجًا بذلك عليهم؛ ليتبعوه ويعملوا به، فأبى أكثر الناس إلا جحودًا للحق وإنكارًا لحجج الله وأدلته.", "isBasmala": false, "translation_en": "We have displayed for mankind in this Quran every kind of similitude, but most people insist on denying the truth.", "translation_id": "Dan sesungguhnya Kami telah mengulang-ulang kepada manusia dalam Al Quran ini tiap-tiap macam perumpamaan, tapi kebanyakan manusia tidak menyukai kecuali mengingkari(nya).", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 90, "text": "وَقَالُوا۟ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ یَنۢبُوعًا ۝٩٠", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ولما أعجز القرآن المشركين وغلبهم أخذوا يطلبون معجزات وَفْق أهوائهم فقالوا: لن نصدقك -أيها الرسول- ونعمل بما تقول حتى تفجر لنا من أرض \"مكة\" عينًا جارية.", "isBasmala": false, "translation_en": "And they said, \"We will not believe in you unless you make a spring burst from the ground for us.", "translation_id": "Dan mereka berkata: \"Kami sekali-kali tidak percaya kepadamu hingga kamu memancarkan mata air dan bumi untuk kami,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 91, "text": "أَوۡ تَكُونَ لَكَ جَنَّةࣱ مِّن نَّخِیلࣲ وَعِنَبࣲ فَتُفَجِّرَ ٱلۡأَنۡهَـٰرَ خِلَـٰلَهَا تَفۡجِیرًا ۝٩١", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "أو تكون لك حديقة فيها أنواع النخيل والأعناب، وتجعل الأنهار تجري في وسطها بغزارة.", "isBasmala": false, "translation_en": "Or you have a garden of palms and vines; then cause rivers to gush pouring through them.", "translation_id": "atau kamu mempunyai sebuah kebun korma dan anggur, lalu kamu alirkan sungai-sungai di celah kebun yang deras alirannya,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 92, "text": "أَوۡ تُسۡقِطَ ٱلسَّمَاۤءَ كَمَا زَعَمۡتَ عَلَیۡنَا كِسَفًا أَوۡ تَأۡتِیَ بِٱللَّهِ وَٱلۡمَلَـٰۤىِٕكَةِ قَبِیلًا ۝٩٢", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "أو تسقط السماء علينا قطعًا كما زَعَمْتَ، أو تأتي لنا بالله وملائكته، فنشاهدهم مقابلة وعِيانًا.", "isBasmala": false, "translation_en": "Or make the sky fall on us in pieces, as you claim, or bring God and the angels before us.", "translation_id": "atau kamu jatuhkan langit berkeping-keping atas kami, sebagaimana kamu katakan atau kamu datangkan Allah dan malaikat-malaikat berhadapan muka dengan kami.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 93, "text": "أَوۡ یَكُونَ لَكَ بَیۡتࣱ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِی ٱلسَّمَاۤءِ وَلَن نُّؤۡمِنَ لِرُقِیِّكَ حَتَّىٰ تُنَزِّلَ عَلَیۡنَا كِتَـٰبࣰا نَّقۡرَؤُهُۥۗ قُلۡ سُبۡحَانَ رَبِّی هَلۡ كُنتُ إِلَّا بَشَرࣰا رَّسُولࣰا ۝٩٣", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "أو يكون لك بيت من ذهب، أو تصعد في درج إلى السماء، ولن نصدِّقك في صعودك حتى تعود، ومعك كتاب من الله منشور نقرأ فيه أنك رسول الله حقا. قل -أيها الرسول- متعجبًا مِن تعنُّت هؤلاء الكفار: سبحان ربي!! هل أنا إلا عبد من عباده مبلِّغ رسالته؟ فكيف أقدر على فعل ما تطلبون؟", "isBasmala": false, "translation_en": "Or you possess a house of gold. Or you ascend into the sky. Even then, we will not believe in your ascension, unless you bring down for us a book that we can read.\" Say, \"Glory be to my Lord. Am I anything but a human messenger?\"", "translation_id": "Atau kamu mempunyai sebuah rumah dari emas, atau kamu naik ke langit. Dan kami sekali-kali tidak akan mempercayai kenaikanmu itu hingga kamu turunkan atas kami sebuah kitab yang kami baca\". Katakanlah: \"Maha Suci Tuhanku, bukankah aku ini hanya seorang manusia yang menjadi rasul?\"", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 94, "text": "وَمَا مَنَعَ ٱلنَّاسَ أَن یُؤۡمِنُوۤا۟ إِذۡ جَاۤءَهُمُ ٱلۡهُدَىٰۤ إِلَّاۤ أَن قَالُوۤا۟ أَبَعَثَ ٱللَّهُ بَشَرࣰا رَّسُولࣰا ۝٩٤", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "وما منع الكفارَ من الإيمان بالله ورسوله وطاعتهما، حين جاءهم البيان الكافي من عند الله، إلا قولهم جهلا وإنكارًا: أبعث الله رسولا من جنس البشر؟", "isBasmala": false, "translation_en": "Nothing prevented the people from believing, when guidance has come to them, except that they said, \"Did God send a human messenger?\"", "translation_id": "Dan tidak ada sesuatu yang menghalangi manusia untuk beriman tatkala datang petunjuk kepadanya, kecuali perkataan mereka: \"Adakah Allah mengutus seorang manusia menjadi rasuI?\"", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 95, "text": "قُل لَّوۡ كَانَ فِی ٱلۡأَرۡضِ مَلَـٰۤىِٕكَةࣱ یَمۡشُونَ مُطۡمَىِٕنِّینَ لَنَزَّلۡنَا عَلَیۡهِم مِّنَ ٱلسَّمَاۤءِ مَلَكࣰا رَّسُولࣰا ۝٩٥", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "قل -أيها الرسول- ردًّا على المشركين إنكارهم أن يكون الرسول من البشر: لو كان في الأرض ملائكة يمشون عليها مطمئنين، لأرسلنا إليهم رسولا من جنسهم، ولكنَّ أهل الأرض بشر، فالرسول إليهم ينبغي أن يكون من جنسهم؛ ليمكنهم مخاطبته وفَهْم كلامه.", "isBasmala": false, "translation_en": "Say, \"If there were angels on earth, walking around in peace, We would have sent down to them from heaven an angel messenger.\"", "translation_id": "Katakanlah: \"Kalau seandainya ada malaikat-malaikat yang berjalan-jalan sebagai penghuni di bumi, niscaya Kami turunkan dari langit kepada mereka seorang malaikat menjadi rasul\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 96, "text": "قُلۡ كَفَىٰ بِٱللَّهِ شَهِیدَۢا بَیۡنِی وَبَیۡنَكُمۡۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِیرَۢا بَصِیرࣰا ۝٩٦", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "قل لهم: كفى بالله شهيدًا بيني وبينكم على صِدْقي وحقيقة نبوَّتي. إنه سبحانه خبير بأحوال عباده، بصير بأعمالهم، وسيجازيهم عليها.", "isBasmala": false, "translation_en": "Say, \"God is enough witness between you and me. He is fully aware of His servants, and He sees them well.\"", "translation_id": "Katakanlah: \"Cukuplah Allah menjadi saksi antara aku dan kamu sekalian. Sesungguhnya Dia adalah Maha Mengetahui lagi Maha Melihat akan hamba-hamba-Nya\".", "manzil": 4, "manzil_display": ""}], "292": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 97, "text": "وَمَن یَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن یُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِیَاۤءَ مِن دُونِهِۦۖ وَنَحۡشُرُهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡیࣰا وَبُكۡمࣰا وَصُمࣰّاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَـٰهُمۡ سَعِیرࣰا ۝٩٧", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "ومن يهده الله فهو المهتدي إلى الحق، ومن يضلله فيخذلْه ويَكِلْه إلى نفسه فلا هادي له من دون الله، وهؤلاء الضُّلال يبعثهم الله يوم القيامة، ويحشرهم على وجوههم، وهم لا يرون ولا ينطقون ولا يسمعون، مصيرهم إلى نار جهنم الملتهبة، كلما سكن لهيبها، وخمدت نارها، زدناهم نارًا ملتهبة متأججة.", "isBasmala": false, "translation_en": "Whomever God guides is the guided one. And whomever He leaves astray-for them you will find no protectors apart from Him. And We will gather them on the Day of Resurrection, on their faces, blind, dumb, and deaf. Their abode is Hell; whenever it abates, We intensify the blaze for them.", "translation_id": "Dan barangsiapa yang ditunjuki Allah, dialah yang mendapat petunjuk dan barangsiapa yang Dia sesatkan maka sekali-kali kamu tidak akan mendapat penolong-penolong bagi mereka selain dari Dia. Dan Kami akan mengumpulkan mereka pada hari kiamat (diseret) atas muka mereka dalam keadaan buta, bisu dan pekak. Tempat kediaman mereka adalah neraka jahannam. Tiap-tiap kali nyala api Jahannam itu akan padam, Kami tambah lagi bagi mereka nyalanya.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 98, "text": "ذَ ٰلِكَ جَزَاۤؤُهُم بِأَنَّهُمۡ كَفَرُوا۟ بِـَٔایَـٰتِنَا وَقَالُوۤا۟ أَءِذَا كُنَّا عِظَـٰمࣰا وَرُفَـٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقࣰا جَدِیدًا ۝٩٨", "juz": 15, "hizb": "(*¾ ح 29*)", "tafsir": "هذا الذي وُصِف من العذاب عقاب للمشركين؛ بسبب كفرهم بآيات الله وحججه، وتكذيبهم رسله الذين دَعَوْهم إلى عبادته، وقولهم استنكارًا - إذا أُمروا بالتصديق بالبعث -: أإذا متنا وصِرْنا عظامًا بالية وأجزاءً متفتتة نُبعث بعد ذلك خَلْقًا جديدًا؟", "isBasmala": false, "translation_en": "This is their repayment for having blasphemed against Our revelations, and having said, \"Shall we, when we have become bones and fragments, be resurrected as a new creation?\"", "translation_id": "Itulah balasan bagi mereka, karena sesungguhnya mereka kafir kepada ayat-ayat Kami dan (karena mereka) berkata: \"Apakah bila kami telah menjadi tulang belulang dan benda-benda yang hancur, apakah kami benar-benar akan dibangkitkan kembali sebagai makhluk baru?\"", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 99, "text": "۞ أَوَ لَمۡ یَرَوۡا۟ أَنَّ ٱللَّهَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰۤ أَن یَخۡلُقَ مِثۡلَهُمۡ وَجَعَلَ لَهُمۡ أَجَلࣰا لَّا رَیۡبَ فِیهِ فَأَبَى ٱلظَّـٰلِمُونَ إِلَّا كُفُورࣰا ۝٩٩", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "أَغَفَل هؤلاء المشركون، فلم يتبصروا ويعلموا أن الله الذي خلق السموات والأرض وما فيهن من المخلوقات على غير مثال سابق، قادر على أن يخلق أمثالهم بعد فنائهم؟ وقد جعل الله لهؤلاء المشركين وقتًا محددًا لموتهم وعذابهم، لا شك أنه آتيهم، ومع وضوح الحق ودلائله أبى الكافرون إلا جحودًا لدين الله عزَّ وجلَّ.", "isBasmala": false, "translation_en": "Do they not consider that God, Who created the heavens and the earth, is Able to create the likes of them? He has assigned for them a term, in which there is no doubt. But the wrongdoers persist in denying the truth.", "translation_id": "Dan apakah mereka tidak memperhatikan bahwasanya Allah yang menciptakan langit dan bumi adalah kuasa (pula) menciptakan yang serupa dengan mereka, dan telah menetapkan waktu yang tertentu bagi mereka yang tidak ada keraguan padanya? Maka orang-orang zalim itu tidak menghendaki kecuali kekafiran.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 100, "text": "قُل لَّوۡ أَنتُمۡ تَمۡلِكُونَ خَزَاۤىِٕنَ رَحۡمَةِ رَبِّیۤ إِذࣰا لَّأَمۡسَكۡتُمۡ خَشۡیَةَ ٱلۡإِنفَاقِۚ وَكَانَ ٱلۡإِنسَـٰنُ قَتُورࣰا ۝١٠٠", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: لو كنتم تملكون خزائن رحمة ربي التي لا تنفد ولا تبيد إذًا لبخلتم بها، فلم تعطوا منها غيركم خوفًا مِن نفادها فتصبحوا فقراء. ومن شأن الإنسان أنه بخيل بما في يده إلا مَن عصم الله بالإيمان.", "isBasmala": false, "translation_en": "Say, \"If you possessed the treasuries of my Lord's mercy, you would have withheld them for fear of spending.\" The human being has always been stingy.", "translation_id": "Katakanlah: \"Kalau seandainya kamu menguasai perbendaharaan-perbendaharaan rahmat Tuhanku, niscaya perbendaharaan itu kamu tahan, karena takut membelanjakannya\". Dan adalah manusia itu sangat kikir.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 101, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَىٰ تِسۡعَ ءَایَـٰتِۭ بَیِّنَـٰتࣲۖ فَسۡـَٔلۡ بَنِیۤ إِسۡرَ ٰۤءِیلَ إِذۡ جَاۤءَهُمۡ فَقَالَ لَهُۥ فِرۡعَوۡنُ إِنِّی لَأَظُنُّكَ یَـٰمُوسَىٰ مَسۡحُورࣰا ۝١٠١", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "ولقد آتينا موسى تسع معجزات واضحات شاهدات على صِدْق نبوته وهي: العصا واليد والسنون ونقص الثمرات والطوفان والجراد والقمل والضفادع والدم، فاسأل -أيها الرسول- اليهود سؤال تقرير حين جاء موسى أسلافهم بمعجزاته الواضحات، فقال فرعون لموسى: إني لأظنك -يا موسى- ساحرا، مخدوعًا مغلوبًا على عقلك بما تأتيه من غرائب الأفعال.", "isBasmala": false, "translation_en": "We gave Moses nine clear signs-ask the Children of Israel. When he went to them, Pharaoh said to him, \"I think that you, Moses, are bewitched.\"", "translation_id": "Dan sesungguhnya Kami telah memberikan kepada Musa sembilan buah mukjizat yang nyata, maka tanyakanlah kepada Bani Israil, tatkala Musa datang kepada mereka lalu Fir'aun berkata kepadanya: \"Sesungguhnya aku sangka kamu, hai Musa, seorang yang kena sihir\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 102, "text": "قَالَ لَقَدۡ عَلِمۡتَ مَاۤ أَنزَلَ هَـٰۤؤُلَاۤءِ إِلَّا رَبُّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ بَصَاۤىِٕرَ وَإِنِّی لَأَظُنُّكَ یَـٰفِرۡعَوۡنُ مَثۡبُورࣰا ۝١٠٢", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "فردَّ عليه موسى: لقد تيقَّنتَ -يا فرعون- أنه ما أنزل تلك المعجزات التسع الشاهدة على صدق نبوتي إلا رب السموات والأرض؛ لتكون دلالات يَستدِل بها أولو البصائر على وحدانية الله تعالى في ربوبيته وألوهيته، وإني لعلى يقين أنك -يا فرعون- هالك ملعون مغلوب.", "isBasmala": false, "translation_en": "He said, \"You know that none sent these down except the Lord of the heavens and the earth-eye openers; and I think that you, Pharaoh, are doomed.\"", "translation_id": "Musa menjawab: \"Sesungguhnya kamu telah mengetahui, bahwa tiada yang menurunkan mukjizat-mukjizat itu kecuali Tuhan Yang memelihara langit dan bumi sebagai bukti-bukti yang nyata; dan sesungguhnya aku mengira kamu, hai Fir'aun, seorang yang akan binasa\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 103, "text": "فَأَرَادَ أَن یَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَـٰهُ وَمَن مَّعَهُۥ جَمِیعࣰا ۝١٠٣", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "فأراد فرعون أن يزعج موسى ويخرجه مع بني إسرائيل مِن أرض \"مصر\"، فأغرقناه ومَن معه مِن جندٍ في البحر عقابًا لهم.", "isBasmala": false, "translation_en": "He resolved to scare them off the land, but We drowned him, and those with him, altogether.", "translation_id": "Kemudian (Fir'aun) hendak mengusir mereka (Musa dan pengikut-pengikutnya) dari bumi (Mesir) itu, maka Kami tenggelamkan dia (Fir'aun) serta orang-orang yang bersama-sama dia seluruhnya,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 104, "text": "وَقُلۡنَا مِنۢ بَعۡدِهِۦ لِبَنِیۤ إِسۡرَ ٰۤءِیلَ ٱسۡكُنُوا۟ ٱلۡأَرۡضَ فَإِذَا جَاۤءَ وَعۡدُ ٱلۡـَٔاخِرَةِ جِئۡنَا بِكُمۡ لَفِیفࣰا ۝١٠٤", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "وقلنا من بعد هلاك فرعون وجنده لبني إسرائيل: اسكنوا أرض \"الشام\"، فإذا جاء يوم القيامة جئنا بكم جميعًا مِن قبوركم إلى موقف الحساب.", "isBasmala": false, "translation_en": "After him, We said to the Children of Israel, \"Inhabit the land, and when the promise of the Hereafter arrives, We will bring you all together.\"", "translation_id": "dan Kami berfirman sesudah itu kepada Bani Israil: \"Diamlah di negeri ini, maka apabila datang masa berbangkit, niscaya Kami datangkan kamu dalam keadaan bercampur baur (dengan musuhmu)\".", "manzil": 4, "manzil_display": ""}], "293": [{"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 105, "text": "وَبِٱلۡحَقِّ أَنزَلۡنَـٰهُ وَبِٱلۡحَقِّ نَزَلَۗ وَمَاۤ أَرۡسَلۡنَـٰكَ إِلَّا مُبَشِّرࣰا وَنَذِیرࣰا ۝١٠٥", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "وبالحق أنزلنا هذا القرآن على محمد صلى الله عليه وسلم لأمْرِ العباد ونهيهم وثوابهم وعقابهم، وبالصدق والعدل والحفظ من التغيير والتبديل نزل. وما أرسلناك -أيها الرسول- إلا مبشرًا بالجنة لمن أطاع، ومخوفًا بالنار لمن عصى وكفر.", "isBasmala": false, "translation_en": "With the truth We sent it down, and with the truth it descended. We sent you only as a bearer of good news and a warner.", "translation_id": "Dan Kami turunkan (Al Quran) itu dengan sebenar-benarnya dan Al Quran itu telah turun dengan (membawa) kebenaran. Dan Kami tidak mengutus kamu, melainkan sebagai pembawa berita gembira dan pemberi peringatan.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 106, "text": "وَقُرۡءَانࣰا فَرَقۡنَـٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثࣲ وَنَزَّلۡنَـٰهُ تَنزِیلࣰا ۝١٠٦", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "وأنزلنا إليك -أيها الرسول- قرآنًا بيَّناه وأحكمناه وفَصَّلناه فارقًا بين الهدى والضلال والحق والباطل؛ لتقرأه على الناس في تؤدة وتمهُّل، ونَزَّلْناه مفرَّقًا، شيئًا بعد شيء، على حسب الحوادث ومقتضيات الأحوال.", "isBasmala": false, "translation_en": "A Quran which We unfolded gradually, that you may recite to the people over time. And We revealed it in stages.", "translation_id": "Dan Al Quran itu telah Kami turunkan dengan berangsur-angsur agar kamu membacakannya perlahan-lahan kepada manusia dan Kami menurunkannya bagian demi bagian.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 107, "text": "قُلۡ ءَامِنُوا۟ بِهِۦۤ أَوۡ لَا تُؤۡمِنُوۤا۟ۚ إِنَّ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ مِن قَبۡلِهِۦۤ إِذَا یُتۡلَىٰ عَلَیۡهِمۡ یَ̅خِ̅رُّ̅و̅نَ̅ ̅لِ̅لۡ̅أَ̅ذۡ̅قَ̅ا̅نِ̅ ̅سُ̅جَّ̅دࣰ̅ا̅ ۝١٠٧", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "قل -أيها الرسول- لهؤلاء المكذبين: آمِنوا بالقرآن أو لا تؤمنوا؛ فإن إيمانكم لا يزيده كمالا وتكذيبكم لا يُلْحِق به نقصًا. إن العلماء الذين أوتوا الكتب السابقة مِن قبل القرآن، وعرفوا حقيقة الوحي، إذا قرئ عليهم القرآن يخشعون، فيسجدون على وجوههم لله سبحانه وتعالى.", "isBasmala": false, "translation_en": "Say, \"Believe in it, or do not believe.\" Those who were given knowledge before it, when it is recited to them, they fall to their chins, prostrating.", "translation_id": "Katakanlah: \"Berimanlah kamu kepadanya atau tidak usah beriman (sama saja bagi Allah). Sesungguhnya orang-orang yang diberi pengetahuan sebelumnya apabila Al Quran dibacakan kepada mereka, mereka menyungkur atas muka mereka sambil bersujud,", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 108, "text": "وَیَقُولُونَ سُبۡحَـٰنَ رَبِّنَاۤ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولࣰا ۝١٠٨", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "ويقول هؤلاء الذين أوتوا العلم عند سماع القرآن: تنزيهًا لربنا وتبرئة له مما يصفه المشركون به، ما كان وعد الله تعالى من ثواب وعقاب إلا واقعًا حقًا.", "isBasmala": false, "translation_en": "And they say, \"Glory to our Lord. The promise of our Lord is fulfilled.\"", "translation_id": "dan mereka berkata: \"Maha Suci Tuhan kami, sesungguhnya janji Tuhan kami pasti dipenuhi\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 109, "text": "وَیَخِرُّونَ لِلۡأَذۡقَانِ یَبۡكُونَ وَیَزِیدُهُمۡ خُشُوعࣰا ۝١٠٩ ۩", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "ويقع هؤلاء ساجدين على وجوههم، يبكون تأثرًا بمواعظ القرآن، ويزيدهم سماع القرآن ومواعظه خضوعًا لأمر الله وعظيم قدرته.", "isBasmala": false, "translation_en": "And they fall to their chins, weeping, and it adds to their humility.", "translation_id": "Dan mereka menyungkur atas muka mereka sambil menangis dan mereka bertambah khusyu'.", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 110, "text": "قُلِ ٱدۡعُوا۟ ٱللَّهَ أَوِ ٱدۡعُوا۟ ٱلرَّحۡمَـٰنَۖ أَیࣰّا مَّا تَدۡعُوا۟ فَلَهُ ٱلۡأَسۡمَاۤءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَیۡنَ ذَ ٰلِكَ سَبِیلࣰا ۝١١٠", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "قل -أيها الرسول- لمشركي قومك الذين أنكروا عليك الدعاء بقولك: يا الله يا رحمن، ادعوا الله، أو ادعوا الرحمن، فبأي أسمائه دعوتموه فإنكم تدعون ربًا واحدًا؛ لأن أسماءه كلها حسنى. ولا تجهر بالقراءة في صلاتك، فيسمعك المشركون، ولا تُسِرَّ بها فلا يسمعك أصحابك، وكن وسطًا بين الجهر والهمس.", "isBasmala": false, "translation_en": "Say, \"Call Him God, or call Him the Most Merciful. Whichever name you use, to Him belong the Best Names.\" And be neither loud in your prayer, nor silent in it, but follow a course in between.", "translation_id": "Katakanlah: \"Serulah Allah atau serulah Ar-Rahman. Dengan nama yang mana saja kamu seru, Dia mempunyai al asmaaul husna (nama-nama yang terbaik) dan janganlah kamu mengeraskan suaramu dalam shalatmu dan janganlah pula merendahkannya dan carilah jalan tengah di antara kedua itu\".", "manzil": 4, "manzil_display": ""}, {"sura": 17, "sura_name": "الإسراء", "revelation": "Makkiyah", "aya": 111, "text": "وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی لَمۡ یَتَّخِذۡ وَلَدࣰا وَلَمۡ یَكُن لَّهُۥ شَرِیكࣱ فِی ٱلۡمُلۡكِ وَلَمۡ یَكُن لَّهُۥ وَلِیࣱّ مِّنَ ٱلذُّلِّۖ وَكَبِّرۡهُ تَكۡبِیرَۢا ۝١١١", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "وقل -أيها الرسول-: الحمد لله الذي له الكمال والثناء، الذي تنزَّه عن الولد والشريك في ألوهيته، ولا يكون له سبحانه وليٌّ مِن خلقه فهو الغني القوي، وهم الفقراء المحتاجون إليه، وعظِّمه تعظيمًا تامًا بالثناء عليه وعبادته وحده لا شريك له، وإخلاص الدين كله له.", "isBasmala": false, "translation_en": "And say, \"Praise be to God, who has not begotten a son, nor has He a partner in sovereignty, nor has He an ally out of weakness, and glorify Him constantly.\"", "translation_id": "Dan katakanlah: \"Segala puji bagi Allah Yang tidak mempunyai anak dan tidak mempunyai sekutu dalam kerajaan-Nya dan Dia bukan pula hina yang memerlukan penolong dan agungkanlah Dia dengan pengagungan yang sebesar-besarnya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 16, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 1, "text": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِیۤ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَـٰبَ وَلَمۡ یَجۡعَل لَّهُۥ عِوَجَاۜ ۝١", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "الثناء على الله بصفاته التي كلُّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، الذي تفضَّل فأنزل على عبده ورسوله محمد صلى الله عليه وسلم القرآن، ولم يجعل فيه شيئًا من الميل عن الحق.", "isBasmala": false, "translation_en": "Praise be to God, who revealed the Book to His servant, and allowed in it no distortion.", "translation_id": "Segala puji bagi Allah yang telah menurunkan kepada hamba-Nya Al Kitab (Al-Quran) dan Dia tidak mengadakan kebengkokan di dalamnya;", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 2, "text": "قَیِّمࣰا لِّیُنذِرَ بَأۡسࣰا شَدِیدࣰا مِّن لَّدُنۡهُ وَیُبَشِّرَ ٱلۡمُؤۡمِنِینَ ٱلَّذِینَ یَعۡمَلُونَ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنࣰا ۝٢", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "جعله الله كتابًا مستقيمًا، لا اختلاف فيه ولا تناقض؛ لينذر الكافرين من عذاب شديد من عنده، ويبشر المصدقين بالله ورسوله الذين يعملون الأعمال الصالحات، بأن لهم ثوابًا جزيلا هو الجنة، يقيمون في هذا النعيم لا يفارقونه أبدًا.", "isBasmala": false, "translation_en": "Valuable-to warn of severe punishment from Himself; and to deliver good news to the believers who do righteous deeds, that they will have an excellent reward.", "translation_id": "sebagai bimbingan yang lurus, untuk memperingatkan siksaan yang sangat pedih dari sisi Allah dan memberi berita gembira kepada orang-orang yang beriman, yang mengerjakan amal saleh, bahwa mereka akan mendapat pembalasan yang baik,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 3, "text": "مَّـٰكِثِینَ فِیهِ أَبَدࣰا ۝٣", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "جعله الله كتابًا مستقيمًا، لا اختلاف فيه ولا تناقض؛ لينذر الكافرين من عذاب شديد من عنده، ويبشر المصدقين بالله ورسوله الذين يعملون الأعمال الصالحات، بأن لهم ثوابًا جزيلا هو الجنة، يقيمون في هذا النعيم لا يفارقونه أبدًا.", "isBasmala": false, "translation_en": "In which they will abide forever.", "translation_id": "mereka kekal di dalamnya untuk selama-lamanya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 4, "text": "وَیُنذِرَ ٱلَّذِینَ قَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدࣰا ۝٤", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "وينذر به المشركين الذين قالوا: اتخذ الله ولدا.", "isBasmala": false, "translation_en": "And to warn those who say, \"God has begotten a son.\"", "translation_id": "Dan untuk memperingatkan kepada orang-orang yang berkata: \"Allah mengambil seorang anak\".", "manzil": 4, "manzil_display": ""}], "294": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 5, "text": "مَّا لَهُم بِهِۦ مِنۡ عِلۡمࣲ وَلَا لِـَٔابَاۤىِٕهِمۡۚ كَبُرَتۡ كَلِمَةࣰ تَخۡرُجُ مِنۡ أَفۡوَ ٰهِهِمۡۚ إِن یَقُولُونَ إِلَّا كَذِبࣰا ۝٥", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "ليس عند هؤلاء المشركين شيء من العلم على ما يَدَّعونه لله من اتخاذ الولد، كما لم يكن عند أسلافهم الذين قلَّدوهم، عَظُمت هذه المقالة الشنيعة التي تخرج من أفواههم، ما يقولون إلا قولا كاذبًا.", "isBasmala": false, "translation_en": "They have no knowledge of this, nor did their forefathers. Grave is the word that comes out of their mouths. They say nothing but a lie.", "translation_id": "Mereka sekali-kali tidak mempunyai pengetahuan tentang hal itu, begitu pula nenek moyang mereka. Alangkah buruknya kata-kata yang keluar dari mulut mereka; mereka tidak mengatakan (sesuatu) kecuali dusta.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 6, "text": "فَلَعَلَّكَ بَـٰخِعࣱ نَّفۡسَكَ عَلَىٰۤ ءَاثَـٰرِهِمۡ إِن لَّمۡ یُؤۡمِنُوا۟ بِهَـٰذَا ٱلۡحَدِیثِ أَسَفًا ۝٦", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "فلعلك -أيها الرسول- مُهْلِك نفسك غمًّا وحزنًا على أثر تولِّي قومك وإعراضهم عنك، إن لم يصدِّقوا بهذا القرآن ويعملوا به.", "isBasmala": false, "translation_en": "Perhaps you may destroy yourself with grief, chasing after them, if they do not believe in this information.", "translation_id": "Maka (apakah) barangkali kamu akan membunuh dirimu karena bersedih hati setelah mereka berpaling, sekiranya mereka tidak beriman kepada keterangan ini (Al-Quran).", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 7, "text": "إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِینَةࣰ لَّهَا لِنَبۡلُوَهُمۡ أَیُّهُمۡ أَحۡسَنُ عَمَلࣰا ۝٧", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "إنَّا جعلنا ما على وجه الأرض من المخلوقات جَمالا لها، ومنفعة لأهلها؛ لنختبرهم: أيُّهم أحسن عملا بطاعتنا، وأيهم أسوأ عملا بالمعاصي، ونجزي كلا بما يستحق.", "isBasmala": false, "translation_en": "We made what is upon the earth an ornament for it, to test them as to which of them is best in conduct.", "translation_id": "Sesungguhnya Kami telah menjadikan apa yang di bumi sebagai perhiasan baginya, agar Kami menguji mereka siapakah di antara mereka yang terbaik perbuatannya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 8, "text": "وَإِنَّا لَجَـٰعِلُونَ مَا عَلَیۡهَا صَعِیدࣰا جُرُزًا ۝٨", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "وإنَّا لجاعلون ما على الأرض من تلك الزينة عند انقضاء الدنيا ترابًا، لا نبات فيه.", "isBasmala": false, "translation_en": "And We will turn what is on it into barren waste.", "translation_id": "Dan sesungguhnya Kami benar-benar akan menjadikan (pula) apa yang di atasnya menjadi tanah rata lagi tandus.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 9, "text": "أَمۡ حَسِبۡتَ أَنَّ أَصۡحَـٰبَ ٱلۡكَهۡفِ وَٱلرَّقِیمِ كَانُوا۟ مِنۡ ءَایَـٰتِنَا عَجَبًا ۝٩", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "لا تظن -أيها الرسول- أن قصة أصحاب الكهف واللوح الذي كُتِبت فيه أسماؤهم من آياتنا عجيبة وغريبة؛ فإن خلق السموات والأرض وما فيهما أعجب من ذلك.", "isBasmala": false, "translation_en": "Did you know that the People of the Cave and the Inscription were of Our wondrous signs?", "translation_id": "Atau kamu mengira bahwa orang-orang yang mendiami gua dan (yang mempunyai) raqim itu, mereka termasuk tanda-tanda kekuasaan Kami yang mengherankan?", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 10, "text": "إِذۡ أَوَى ٱلۡفِتۡیَةُ إِلَى ٱلۡكَهۡفِ فَقَالُوا۟ رَبَّنَاۤ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةࣰ وَهَیِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدࣰا ۝١٠", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "اذكر -أيها الرسول- حين لجأ الشبَّان المؤمنون إلى الكهف؛ خشية من فتنة قومهم لهم، وإرغامهم على عبادة الأصنام، فقالوا: ربنا أعطنا مِن عندك رحمة، تثبتنا بها، وتحفظنا من الشر، ويسِّر لنا الطريق الصواب الذي يوصلنا إلى العمل الذي تحب، فنكون راشدين غير ضالين.", "isBasmala": false, "translation_en": "When the youths took shelter in the cave, they said, \"Our Lord, give us mercy from Yourself, and bless our affair with guidance.\"", "translation_id": "(Ingatlah) tatkala para pemuda itu mencari tempat berlindung ke dalam gua, lalu mereka berdoa: \"Wahai Tuhan kami, berikanlah rahmat kepada kami dari sisi-Mu dan sempurnakanlah bagi kami petunjuk yang lurus dalam urusan kami (ini)\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 11, "text": "فَضَرَبۡنَا عَلَىٰۤ ءَاذَانِهِمۡ فِی ٱلۡكَهۡفِ سِنِینَ عَدَدࣰا ۝١١", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "فألقينا عليهم النوم العميق، فبقوا في الكهف سنين كثيرة.", "isBasmala": false, "translation_en": "Then We sealed their ears in the cave for a number of years.", "translation_id": "Maka Kami tutup telinga mereka beberapa tahun dalam gua itu,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 12, "text": "ثُمَّ بَعَثۡنَـٰهُمۡ لِنَعۡلَمَ أَیُّ ٱلۡحِزۡبَیۡنِ أَحۡصَىٰ لِمَا لَبِثُوۤا۟ أَمَدࣰا ۝١٢", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "ثم أيقظناهم مِن نومهم؛ لنُظهر للناس ما علمناه في الأزل؛ فتتميَّز أي الطائفتين المتنازعتين في مدة لبثهم أضبط في الإحصاء، وهل لبثوا يومًا أو بعض يوم، أو مدة طويلة؟", "isBasmala": false, "translation_en": "Then We awakened them to know which of the two groups could better calculate the length of their stay.", "translation_id": "Kemudian Kami bangunkan mereka, agar Kami mengetahui manakah di antara kedua golongan itu] yang lebih tepat dalam menghitung berapa lama mereka tinggal (dalam gua itu).", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 13, "text": "نَّحۡنُ نَقُصُّ عَلَیۡكَ نَبَأَهُم بِٱلۡحَقِّۚ إِنَّهُمۡ فِتۡیَةٌ ءَامَنُوا۟ بِرَبِّهِمۡ وَزِدۡنَـٰهُمۡ هُدࣰى ۝١٣", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "نحن نقصُّ عليك -أيها الرسول- خبرهم بالصدق. إن أصحاب الكهف شُبَّان صدَّقوا ربهم وامتثلوا أمره، وزِدْناهم هدى وثباتًا على الحق.", "isBasmala": false, "translation_en": "We relate to you their story in truth. They were youths who believed in their Lord, and We increased them in guidance.", "translation_id": "Kami kisahkan kepadamu (Muhammad) cerita ini dengan benar. Sesungguhnya mereka adalah pemuda-pemuda yang beriman kepada Tuhan mereka, dan Kami tambah pula untuk mereka petunjuk.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 14, "text": "وَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ إِذۡ قَامُوا۟ فَقَالُوا۟ رَبُّنَا رَبُّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ لَن نَّدۡعُوَا۟ مِن دُونِهِۦۤ إِلَـٰهࣰاۖ لَّقَدۡ قُلۡنَاۤ إِذࣰا شَطَطًا ۝١٤", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "وقوَّينا قلوبهم بالإيمان، وشددنا عزيمتهم به، حين قاموا بين يدي الملك الكافر، وهو يلومهم على تَرْكِ عبادة الأصنام فقالوا له: ربنا الذي نعبده هو رب السموات والأرض، لن نعبد غيره من الآلهة، لو قلنا غير هذا لكُنَّا قد قلنا قولا جائرًا بعيدًا عن الحق.", "isBasmala": false, "translation_en": "And We strengthened their hearts, when they stood up and said, \"Our Lord is the Lord of the heavens and the earth; we will not call on any god besides Him, for then we would have spoken an outrage.\"", "translation_id": "Dan Kami meneguhkan hati mereka diwaktu mereka berdiri, lalu mereka pun berkata, \"Tuhan kami adalah Tuhan seluruh langit dan bumi; kami sekali-kali tidak menyeru Tuhan selain Dia, sesungguhnya kami kalau demikian telah mengucapkan perkataan yang amat jauh dari kebenaran\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 15, "text": "هَـٰۤؤُلَاۤءِ قَوۡمُنَا ٱتَّخَذُوا۟ مِن دُونِهِۦۤ ءَالِهَةࣰۖ لَّوۡلَا یَأۡتُونَ عَلَیۡهِم بِسُلۡطَـٰنِۭ بَیِّنࣲۖ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰا ۝١٥", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "ثم قال بعضهم لبعض: هؤلاء قومنا اتخذوا لهم آلهة غير الله، فهلا أتَوْا على عبادتهم لها بدليل واضح، فلا أحد أشد ظلمًا ممن اختلق على الله الكذب بنسبة الشريك إليه في عبادته.", "isBasmala": false, "translation_en": "\"These people, our people, have taken to themselves gods other than Him. Why do they not bring a clear proof concerning them? Who, then, does greater wrong than he who invents lies and attributes them to God?\"", "translation_id": "Kaum kami ini telah menjadikan selain Dia sebagai tuhan-tuhan (untuk disembah). Mengapa mereka tidak mengemukakan alasan yang terang (tentang kepercayaan mereka)? Siapakah yang lebih zalim daripada orang-orang yang mengada-adakan kebohongan terhadap Allah?", "manzil": 4, "manzil_display": ""}], "295": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 16, "text": "وَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا یَعۡبُدُونَ إِلَّا ٱللَّهَ فَأۡوُۥۤا۟ إِلَى ٱلۡكَهۡفِ یَنشُرۡ لَكُمۡ رَبُّكُم مِّن رَّحۡمَتِهِۦ وَیُهَیِّئۡ لَكُم مِّنۡ أَمۡرِكُم مِّرۡفَقࣰا ۝١٦", "juz": 15, "hizb": "(* ح 30*)", "tafsir": "وحين فارقتم قومكم بدينكم، وتركتم ما يعبدون من الآلهة إلا عبادة الله، فالجؤوا إلى الكهف في الجبل لعبادة ربكم وحده، يَبْسطْ لكم ربكم من رحمته ما يستركم به في الدارين، ويسهل لكم من أمركم ما تنتفعون به في حياتكم من أسباب العيش.", "isBasmala": false, "translation_en": "\"Now that you have withdrawn from them, and from what they worship besides God, take shelter in the cave. And your Lord will unfold His mercy for you, and will set your affair towards ease.\"", "translation_id": "Dan apabila kamu meninggalkan mereka dan apa yang mereka sembah selain Allah, maka carilah tempat berlindung ke dalam gua itu, niscaya Tuhanmu akan melimpahkan sebagian rahmat-Nya kepadamu dan menyediakan sesuatu yang berguna bagimu dalam urusan kamu.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 17, "text": "۞ وَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَ ٰوَرُ عَن كَهۡفِهِمۡ ذَاتَ ٱلۡیَمِینِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِی فَجۡوَةࣲ مِّنۡهُۚ ذَ ٰلِكَ مِنۡ ءَایَـٰتِ ٱللَّهِۗ مَن یَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن یُضۡلِلۡ فَلَن تَجِدَ لَهُۥ وَلِیࣰّا مُّرۡشِدࣰا ۝١٧", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "فلما فعلوا ذلك ألقى الله عليهم النوم وحَفِظهم. وترى -أيها المشاهد لهم- الشمس إذا طلعت من المشرق تميل عن مكانهم إلى جهة اليمين، وإذا غربت تتركهم إلى جهة اليسار، وهم في متسع من الكهف، فلا تؤذيهم حرارة الشمس ولا ينقطع عنهم الهواء، ذلك الذي فعلناه بهؤلاء الفتية من دلائل قدرة الله. من يوفقه الله للاهتداء بآياته فهو الموفَّق إلى الحق، ومن لم يوفقه لذلك فلن تجد له معينًا يرشده لإصابة الحق؛ لأن التوفيق والخِذْلان بيد الله وحده.", "isBasmala": false, "translation_en": "You would have seen the sun, when it rose, veering away from their cave towards the right, and when it sets, moving away from them to the left, as they lay in the midst of the cave. That was one of God's wonders. He whom God guides is truly guided; but he whom He misguides, for him you will find no directing friend.", "translation_id": "Dan kamu akan melihat matahari ketika terbit, condong dari gua mereka ke sebelah kanan, dan bila matahari terbenam menjauhi mereka ke sebelah kiri sedang mereka berada dalam tempat yang luas dalam gua itu. Itu adalah sebagian dari tanda-tanda (kebesaran) Allah. Barangsiapa yang diberi petunjuk oleh Allah, maka dialah yang mendapat petunjuk; dan barangsiapa yang disesatkan-Nya, maka kamu tidak akan mendapatkan seorang pemimpinpun yang dapat memberi petunjuk kepadanya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 18, "text": "وَتَحۡسَبُهُمۡ أَیۡقَاظࣰا وَهُمۡ رُقُودࣱۚ وَنُقَلِّبُهُمۡ ذَاتَ ٱلۡیَمِینِ وَذَاتَ ٱلشِّمَالِۖ وَكَلۡبُهُم بَـٰسِطࣱ ذِرَاعَیۡهِ بِٱلۡوَصِیدِۚ لَوِ ٱطَّلَعۡتَ عَلَیۡهِمۡ لَوَلَّیۡتَ مِنۡهُمۡ فِرَارࣰا وَلَمُلِئۡتَ مِنۡهُمۡ رُعۡبࣰا ۝١٨", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "وتظن -أيها الناظر- أهل الكهف أيقاظًا، وهم في الواقع نيام، ونتعهدهم بالرعاية، فنُقَلِّبهم حال نومهم مرة للجنب الأيمن ومرة للجنب الأيسر؛ لئلا تأكلهم الأرض، وكلبهم الذي صاحَبهم مادٌّ ذراعيه بفناء الكهف، لو عاينتهم لأدبرت عنهم هاربًا، ولَمُلِئَتْ نفسك منهم فزعًا.", "isBasmala": false, "translation_en": "You would think them awake, although they were asleep. And We turned them over to the right, and to the left, with their dog stretching its paws across the threshold. Had you looked at them, you would have turned away from them in flight, and been filled with fear of them.", "translation_id": "Dan kamu mengira mereka itu bangun, padahal mereka tidur; Dan kami balik-balikkan mereka ke kanan dan ke kiri, sedang anjing mereka mengunjurkan kedua lengannya di muka pintu gua. Dan jika kamu menyaksikan mereka tentulah kamu akan berpaling dari mereka dengan melarikan diri dan tentulah (hati) kamu akan dipenuhi oleh ketakutan terhadap mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 19, "text": "وَكَذَ ٰلِكَ بَعَثۡنَـٰهُمۡ لِیَتَسَاۤءَلُوا۟ بَیۡنَهُمۡۚ قَالَ قَاۤىِٕلࣱ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُوا۟ لَبِثۡنَا یَوۡمًا أَوۡ بَعۡضَ یَوۡمࣲۚ قَالُوا۟ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوۤا۟ أَحَدَكُم بِوَرِقِكُمۡ هَـٰذِهِۦۤ إِلَى ٱلۡمَدِینَةِ فَلۡیَنظُرۡ أَیُّهَاۤ أَزۡكَىٰ طَعَامࣰا فَلۡیَأۡتِكُم بِرِزۡقࣲ مِّنۡهُ وَلۡیَتَلَطَّفۡ وَلَا یُشۡعِرَنَّ بِكُمۡ أَحَدًا ۝١٩", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "وكما أنمناهم وحفظناهم هذه المدة الطويلة أيقظناهم مِن نومهم على هيئتهم دون تغيُّر؛ لكي يسأل بعضهم بعضًا: كم من الوقت مكثنا نائمين هنا؟ فقال بعضهم: مكثنا يوما أو بعض يوم، وقال آخرون التبس عليهم الأمر: فَوِّضوا عِلْم ذلك لله، فربكم أعلم بالوقت الذي مكثتموه، فأرسِلوا أحدكم بنقودكم الفضية هذه إلى مدينتنا فلينظر: أيَّ أهل المدينة أحلُّ وأطيب طعامًا؟ فليأتكم بقوت منه، وليتلطف في شرائه مع البائع حتى لا ننكشف، ويظهر أمرنا، ولا يُعْلِمَنَّ بكم أحدًا من الناس.", "isBasmala": false, "translation_en": "Even so, We awakened them, so that they may ask one another. A speaker among them said, \"How long have you stayed?\" They said, \"We have stayed a day, or part of a day.\" They said, \"Your Lord knows best how long you have stayed.\" \"Send one of you to the city, with this money of yours, and let him see which food is most suitable, and let him bring you some provision thereof. And let him be gentle, and let no one become aware of you.\"", "translation_id": "Dan demikianlah Kami bangunkan mereka agar mereka saling bertanya di antara mereka sendiri. Berkatalah salah seorang di antara mereka: Sudah berapa lamakah kamu berada (disini?)\". Mereka menjawab: \"Kita berada (disini) sehari atau setengah hari\". Berkata (yang lain lagi): \"Tuhan kamu lebih mengetahui berapa lamanya kamu berada (di sini). Maka suruhlah salah seorang di antara kamu untuk pergi ke kota dengan membawa uang perakmu ini, dan hendaklah dia lihat manakah makanan yang lebih baik, maka hendaklah ia membawa makanan itu untukmu, dan hendaklah ia berlaku lemah-lembut dan janganlah sekali-kali menceritakan halmu kepada seorangpun.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 20, "text": "إِنَّهُمۡ إِن یَظۡهَرُوا۟ عَلَیۡكُمۡ یَرۡجُمُوكُمۡ أَوۡ یُعِیدُوكُمۡ فِی مِلَّتِهِمۡ وَلَن تُفۡلِحُوۤا۟ إِذًا أَبَدࣰا ۝٢٠", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "إن قومكم إن يطَّلعوا عليكم يرجموكم بالحجارة، فيقتلوكم، أو يردوكم إلى دينهم، فتصيروا كفارًا، ولن تفوزوا بمطلبكم مِن دخول الجنة -إن فعلتم ذلك- أبدًا.", "isBasmala": false, "translation_en": "\"If they discover you, they will stone you, or force you back into their religion; then you will never be saved.\"", "translation_id": "Sesungguhnya jika mereka dapat mengetahui tempatmu, niscaya mereka akan melempar kamu dengan batu, atau memaksamu kembali kepada agama mereka, dan jika demikian niscaya kamu tidak akan beruntung selama lamanya\".", "manzil": 4, "manzil_display": ""}], "296": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 21, "text": "وَكَذَ ٰلِكَ أَعۡثَرۡنَا عَلَیۡهِمۡ لِیَعۡلَمُوۤا۟ أَنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَأَنَّ ٱلسَّاعَةَ لَا رَیۡبَ فِیهَاۤ إِذۡ یَتَنَـٰزَعُونَ بَیۡنَهُمۡ أَمۡرَهُمۡۖ فَقَالُوا۟ ٱبۡنُوا۟ عَلَیۡهِم بُنۡیَـٰنࣰاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِینَ غَلَبُوا۟ عَلَىٰۤ أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَیۡهِم مَّسۡجِدࣰا ۝٢١", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "وكما أنمناهم سنين كثيرة، وأيقظناهم بعدها، أطْلَعنا عليهم أهل ذلك الزمان، بعد أن كشف البائع نوع الدراهم التي جاء بها مبعوثهم؛ ليعلم الناس أنَّ وَعْدَ الله بالبعث حق، وأن القيامة آتية لا شك فيها، إذ يتنازع المطَّلِعون على أصحاب الكهف في أمر القيامة: فمِن مُثْبِتٍ لها ومِن مُنْكِر، فجعل الله إطْلاعهم على أصحاب الكهف حجة للمؤمنين على الكافرين. وبعد أن انكشف أمرهم، وماتوا قال فريق من المطَّلِعين عليهم: ابنوا على باب الكهف بناءً يحجبهم، واتركوهم وشأنهم، ربهم أعلم بحالهم، وقال أصحاب الكلمة والنفوذ فيهم: لنتخذنَّ على مكانهم مسجدًا للعبادة. وقد نهى رسول الله صلى الله عليه وسلم عن اتخاذ قبور الأنبياء والصالحين مساجد، ولعن مَن فَعَلَ ذلك في آخر وصاياه لأمته، كما أنه نهى عن البناء على القبور مطلقًا، وعن تجصيصها والكتابة عليها؛ لأن ذلك من الغلو الذي قد يؤدي إلى عبادة مَن فيها.", "isBasmala": false, "translation_en": "So it was, that We caused them to be discovered, that they would know that the promise of God is true, and that of the Hour there is no doubt. As they were disputing their case among themselves, they said, \"Build over them a building.\" Their Lord knows best about them. Those who prevailed over their case said, \"We will set up over them a place of worship.\"", "translation_id": "Dan demikian (pula) Kami mempertemukan (manusia) dengan mereka, agar manusia itu mengetahui, bahwa janji Allah itu benar, dan bahwa kedatangan hari kiamat tidak ada keraguan padanya. Ketika orang-orang itu berselisih tentang urusan mereka, orang-orang itu berkata: \"Dirikan sebuah bangunan di atas (gua) mereka, Tuhan mereka lebih mengetahui tentang mereka\". Orang-orang yang berkuasa atas urusan mereka berkata: \"Sesungguhnya kami akan mendirikan sebuah rumah peribadatan di atasnya\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 22, "text": "سَیَقُولُونَ ثَلَـٰثَةࣱ رَّابِعُهُمۡ كَلۡبُهُمۡ وَیَقُولُونَ خَمۡسَةࣱ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا بِٱلۡغَیۡبِۖ وَیَقُولُونَ سَبۡعَةࣱ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّیۤ أَعۡلَمُ بِعِدَّتِهِم مَّا یَعۡلَمُهُمۡ إِلَّا قَلِیلࣱۗ فَلَا تُمَارِ فِیهِمۡ إِلَّا مِرَاۤءࣰ ظَـٰهِرࣰا وَلَا تَسۡتَفۡتِ فِیهِم مِّنۡهُمۡ أَحَدࣰا ۝٢٢", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "سيقول بعض الخائضين في شأنهم من أهل الكتاب: هم ثلاثةٌ، رابعهم كلبهم، ويقول فريق آخر: هم خمسة، سادسهم كلبهم، وكلام الفريقين قول بالظن من غير دليل، وتقول جماعة ثالثة: هم سبعة، وثامنهم كلبهم، قل -أيها الرسول-: ربي هو الأعلم بعددهم، ما يعلم عددهم إلا قليل من خلقه. فلا تجادل أهل الكتاب في عددهم إلا جدالا ظاهرًا لا عمق فيه، بأن تَقُصَّ عليهم ما أخبرك به الوحي فحسب، ولا تسألهم عن عددهم وأحوالهم؛ فإنهم لا يعلمون ذلك.", "isBasmala": false, "translation_en": "They will say, \"Three, and their fourth being their dog.\" And they will say, \"Five, and their sixth being their dog,\" guessing at the unknown. And they will say, \"Seven, and their eighth being their dog.\" Say, \"My Lord knows best their number.\" None knows them except a few. So do not argue concerning them except with an obvious argument, and do not consult any of them about them.", "translation_id": "Nanti (ada orang yang akan) mengatakan (jumlah mereka) adalah tiga orang yang keempat adalah anjingnya, dan (yang lain) mengatakan: \"(jumlah mereka) adalah lima orang yang keenam adalah anjing nya\", sebagai terkaan terhadap barang yang gaib; dan (yang lain lagi) mengatakan: \"(jumlah mereka) tujuh orang, yang ke delapan adalah anjingnya\". Katakanlah: \"Tuhanku lebih mengetahui jumlah mereka; tidak ada orang yang mengetahui (bilangan) mereka kecuali sedikit\". Karena itu janganlah kamu (Muhammad) bertengkar tentang hal mereka, kecuali pertengkaran lahir saja dan jangan kamu menanyakan tentang mereka (pemuda-pemuda itu) kepada seorangpun di antara mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 23, "text": "وَلَا تَقُولَنَّ لِشَا۟یۡءٍ إِنِّی فَاعِلࣱ ذَ ٰلِكَ غَدًا ۝٢٣", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "ولا تقولنَّ لشيء تعزم على فعله: إني فاعل ذلك الشيء غدًا إلا أن تُعَلِّق قولك بالمشيئة، فتقول: إن شاء الله. واذكر ربك عند النسيان بقول: إن شاء الله، وكلما نسيت فاذكر الله؛ فإن ذِكْرَ الله يُذهِب النسيان، وقل: عسى أن يهديني ربي لأقرب الطرق الموصلة إلى الهدى والرشاد.", "isBasmala": false, "translation_en": "And never say about anything, \"I will do that tomorrow.\"", "translation_id": "Dan jangan sekali-kali kamu mengatakan tentang sesuatu: \"Sesungguhnya aku akan mengerjakan ini besok pagi,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 24, "text": "إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُۚ وَٱذۡكُر رَّبَّكَ إِذَا نَسِیتَ وَقُلۡ عَسَىٰۤ أَن یَهۡدِیَنِ رَبِّی لِأَقۡرَبَ مِنۡ هَـٰذَا رَشَدࣰا ۝٢٤", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "ولا تقولنَّ لشيء تعزم على فعله: إني فاعل ذلك الشيء غدًا إلا أن تُعَلِّق قولك بالمشيئة، فتقول: إن شاء الله. واذكر ربك عند النسيان بقول: إن شاء الله، وكلما نسيت فاذكر الله؛ فإن ذِكْرَ الله يُذهِب النسيان، وقل: عسى أن يهديني ربي لأقرب الطرق الموصلة إلى الهدى والرشاد.", "isBasmala": false, "translation_en": "Without saying, \"If God wills.\" And remember your Lord if you forget, and say, \"Perhaps my Lord will guide me to nearer than this in integrity.\"", "translation_id": "kecuali (dengan menyebut): \"Insya Allah\". Dan ingatlah kepada Tuhanmu jika kamu lupa dan katakanlah: \"Mudah-mudahan Tuhanku akan memberiku petunjuk kepada yang lebih dekat kebenarannya dari pada ini\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 25, "text": "وَلَبِثُوا۟ فِی كَهۡفِهِمۡ ثَلَـٰثَ مِا۟ئَةࣲ سِنِینَ وَٱزۡدَادُوا۟ تِسۡعࣰا ۝٢٥", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "ومكث الشُّبَّان نيامًا في كهفهم ثلاثمائة سنة وتسع سنين.", "isBasmala": false, "translation_en": "And they stayed in their cave for three hundred years, adding nine.", "translation_id": "Dan mereka tinggal dalam gua mereka tiga ratus tahun dan ditambah sembilan tahun (lagi).", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 26, "text": "قُلِ ٱللَّهُ أَعۡلَمُ بِمَا لَبِثُوا۟ۖ لَهُۥ غَیۡبُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِیࣲّ وَلَا یُشۡرِكُ فِی حُكۡمِهِۦۤ أَحَدࣰا ۝٢٦", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "وإذا سُئلت -أيها الرسول- عن مدة لبثهم في الكهف، وليس عندك علم في ذلك وتوقيف من الله، فلا تتقدم فيه بشيء، بل قل: الله أعلم بمدة لبثهم، له غيب السموات والأرض، أَبْصِرْ به وأسمع، أي: تعجب من كمال بصره وسمعه وإحاطته بكل شيء. ليس للخلق أحد غيره يتولى أمورهم، وليس له شريك في حكمه وقضائه وتشريعه، سبحانه وتعالى.", "isBasmala": false, "translation_en": "Say, \"God knows best how long they stayed.\" His is the mystery of the heavens and the earth. By Him you see and hear. They have no guardian apart from Him, and He shares His Sovereignty with no one.", "translation_id": "Katakanlah: \"Allah lebih mengetahui berapa lamanya mereka tinggal (di gua); kepunyaan-Nya-lah semua yang tersembunyi di langit dan di bumi. Alangkah terang penglihatan-Nya dan alangkah tajam pendengaran-Nya; tak ada seorang pelindungpun bagi mereka selain dari pada-Nya; dan Dia tidak mengambil seorangpun menjadi sekutu-Nya dalam menetapkan keputusan\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 27, "text": "وَٱتۡلُ مَاۤ أُوحِیَ إِلَیۡكَ مِن كِتَابِ رَبِّكَۖ لَا مُبَدِّلَ لِكَلِمَـٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلۡتَحَدࣰا ۝٢٧", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "واتل -أيها الرسول- ما أوحاه الله إليك من القرآن، فإنه الكتاب الذي لا مبدِّل لكلماته لصدقها وعدلها، ولن تجد من دون ربك ملجأً تلجأ إليه، ولا معاذًا تعوذ به.", "isBasmala": false, "translation_en": "And recite what was revealed to you from the Book of your Lord. There is no changing His words, and you will find no refuge except in Him.", "translation_id": "Dan bacakanlah apa yang diwahyukan kepadamu, yaitu kitab Tuhanmu (Al Quran). Tidak ada (seorangpun) yang dapat merubah kalimat-kalimat-Nya. Dan kamu tidak akan dapat menemukan tempat berlindung selain dari pada-Nya.", "manzil": 4, "manzil_display": ""}], "297": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 28, "text": "وَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِینَ یَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِیِّ یُرِیدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَیۡنَاكَ عَنۡهُمۡ تُرِیدُ زِینَةَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطࣰا ۝٢٨", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "واصبر نفسك -أيها النبي- مع أصحابك مِن فقراء المؤمنين الذين يعبدون ربهم وحده، ويدعونه في الصباح والمساء، يريدون بذلك وجهه، واجلس معهم وخالطهم، ولا تصرف نظرك عنهم إلى غيرهم من الكفار لإرادة التمتع بزينة الحياة الدنيا، ولا تُطِعْ من جعلنا قلبه غافلا عن ذكرنا، وآثَرَ هواه على طاعة مولاه، وصار أمره في جميع أعماله ضياعًا وهلاكًا.", "isBasmala": false, "translation_en": "And content yourself with those who pray to their Lord morning and evening, desiring His Presence. And do not turn your eyes away from them, desiring the glitter of this world. And do not obey him whose heart We have made heedless of Our remembrance-so he follows his own desires-and his priorities are confused.", "translation_id": "Dan bersabarlah kamu bersama-sama dengan orang-orang yang menyeru Tuhannya di pagi dan senja hari dengan mengharap keridhaan-Nya; dan janganlah kedua matamu berpaling dari mereka (karena) mengharapkan perhiasan dunia ini; dan janganlah kamu mengikuti orang yang hatinya telah Kami lalaikan dari mengingati Kami, serta menuruti hawa nafsunya dan adalah keadaannya itu melewati batas.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 29, "text": "وَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَاۤءَ فَلۡیُؤۡمِن وَمَن شَاۤءَ فَلۡیَكۡفُرۡۚ إِنَّاۤ أَعۡتَدۡنَا لِلظَّـٰلِمِینَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَاۚ وَإِن یَسۡتَغِیثُوا۟ یُغَاثُوا۟ بِمَاۤءࣲ كَٱلۡمُهۡلِ یَشۡوِی ٱلۡوُجُوهَۚ بِئۡسَ ٱلشَّرَابُ وَسَاۤءَتۡ مُرۡتَفَقًا ۝٢٩", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "وقل لهؤلاء الغافلين: ما جئتكم به هو الحق من ربكم، فمن أراد منكم أن يصدق ويعمل به، فليفعل فهو خير له، ومن أراد أن يجحد فليفعل، فما ظَلَم إلا نفسه. إنا أعتدنا للكافرين نارًا شديدة أحاط بهم سورها، وإن يستغث هؤلاء الكفار في النار بطلب الماء مِن شدة العطش، يُؤتَ لهم بماء كالزيت العَكِر شديد الحرارة يشوي وجوههم. قَبُح هذا الشراب الذي لا يروي ظمأهم بل يزيده، وقَبُحَتْ النار منزلا لهم ومقامًا. وفي هذا وعيد وتهديد شديد لمن أعرض عن الحق، فلم يؤمن برسالة محمد صلى الله عليه وسلم، ولم يعمل بمقتضاها.", "isBasmala": false, "translation_en": "And say, \"The truth is from your Lord. Whoever wills-let him believe. And whoever wills-let him disbelieve\". We have prepared for the unjust a Fire, whose curtains will hem them in. And when they cry for relief, they will be relieved with water like molten brass, which scalds the faces. What a miserable drink, and what a terrible place.", "translation_id": "Dan katakanlah: \"Kebenaran itu datangnya dari Tuhanmu; maka barangsiapa yang ingin (beriman) hendaklah ia beriman, dan barangsiapa yang ingin (kafir) biarlah ia kafir\". Sesungguhnya Kami telah sediakan bagi orang orang zalim itu neraka, yang gejolaknya mengepung mereka. Dan jika mereka meminta minum, niscaya mereka akan diberi minum dengan air seperti besi yang mendidih yang menghanguskan muka. Itulah minuman yang paling buruk dan tempat istirahat yang paling jelek.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 30, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ إِنَّا لَا نُضِیعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا ۝٣٠", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "إن الذين آمنوا بالله ورسوله وعملوا الأعمال الصالحات لهم أعظم المثوبة، إنا لا نضيع أجورهم، ولا ننقصها على ما أحسنوه من العمل.", "isBasmala": false, "translation_en": "As for those who believe and lead a righteous life-We will not waste the reward of those who work righteousness.", "translation_id": "Sesunggunya mereka yang beriman dan beramal saleh, tentulah Kami tidak akan menyia-nyiakan pahala orang-orang yang mengerjakan amalan(nya) dengan yang baik.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 31, "text": "أُو۟لَـٰۤىِٕكَ لَهُمۡ جَنَّـٰتُ عَدۡنࣲ تَجۡرِی مِن تَحۡتِهِمُ ٱلۡأَنۡهَـٰرُ یُحَلَّوۡنَ فِیهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَیَلۡبَسُونَ ثِیَابًا خُضۡرࣰا مِّن سُندُسࣲ وَإِسۡتَبۡرَقࣲ مُّتَّكِـِٔینَ فِیهَا عَلَى ٱلۡأَرَاۤىِٕكِۚ نِعۡمَ ٱلثَّوَابُ وَحَسُنَتۡ مُرۡتَفَقࣰا ۝٣١", "juz": 15, "hizb": "(*¼ ح 30*)", "tafsir": "أولئك الذين آمنوا لهم جنات يقيمون فيها دائمًا، تجري من تحت غرفهم ومنازلهم الأنهار العذبة، يُحَلَّون فيها بأساور الذهب، ويَلْبَسون ثيابًا ذات لون أخضر نسجت من رقيق الحرير وغليظه، يتكئون فيها على الأسِرَّة المزدانة بالستائر الجميلة، نِعْمَ الثواب ثوابهم، وحَسُنتِ الجنة منزلا ومكانًا لهم.", "isBasmala": false, "translation_en": "These will have the Gardens of Eden, beneath which rivers flow. Reclining on comfortable furnishings, they will be adorned with bracelets of gold, and will wear green garments of silk and brocade. What a wonderful reward, and what an excellent resting-place.", "translation_id": "Mereka itulah (orang-orang yang) bagi mereka surga 'Adn, mengalir sungai-sungai di bawahnya; dalam surga itu mereka dihiasi dengan gelang mas dan mereka memakai pakaian hijau dari sutera halus dan sutera tebal, sedang mereka duduk sambil bersandar di atas dipan-dipan yang indah. Itulah pahala yang sebaik-baiknya, dan tempat istirahat yang indah;", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 32, "text": "۞ وَٱضۡرِبۡ لَهُم مَّثَلࣰا رَّجُلَیۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَیۡنِ مِنۡ أَعۡنَـٰبࣲ وَحَفَفۡنَـٰهُمَا بِنَخۡلࣲ وَجَعَلۡنَا بَیۡنَهُمَا زَرۡعࣰا ۝٣٢", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "واضرب -أيها الرسول- لكفار قومك مثلا رجلين من الأمم السابقة: أحدهما مؤمن، والآخر كافر، وقد جعلنا للكافر حديقتين من أعناب، وأحطناهما بنخل كثير، وأنبتنا وسطهما زروعًا مختلفة نافعة.", "isBasmala": false, "translation_en": "And cite for them the parable of two men. To one of them We gave two gardens of vine, and We surrounded them with palms-trees, and We placed between them crops.", "translation_id": "Dan berikanlah kepada mereka sebuah perumpamaan dua orang laki-laki, Kami jadikan bagi seorang di antara keduanya (yang kafir) dua buah kebun anggur dan kami kelilingi kedua kebun itu dengan pohon-pohon korma dan di antara kedua kebun itu Kami buatkan ladang.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 33, "text": "كِلۡتَا ٱلۡجَنَّتَیۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡلِم مِّنۡهُ شَیۡـࣰٔاۚ وَفَجَّرۡنَا خِلَـٰلَهُمَا نَهَرࣰا ۝٣٣", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "وقد أثمرت كل واحدة من الحديقتين ثمرها، ولم تُنْقِص منه شيئًا، وشققنا بينهما نهرًا لسقيهما بسهولة ويسر.", "isBasmala": false, "translation_en": "Both gardens produced their harvest in full, and suffered no loss. And We made a river flow through them.", "translation_id": "Kedua buah kebun itu menghasilkan buahnya, dan kebun itu tiada kurang buahnya sedikitpun, dan Kami alirkan sungai di celah-celah kedua kebun itu,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 34, "text": "وَكَانَ لَهُۥ ثَمَرࣱ فَقَالَ لِصَـٰحِبِهِۦ وَهُوَ یُحَاوِرُهُۥۤ أَنَا۠ أَكۡثَرُ مِنكَ مَالࣰا وَأَعَزُّ نَفَرࣰا ۝٣٤", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "وكان لصاحب الحديقتين ثمر وأموال أخرى، فقال لصاحبه المؤمن، وهو يحاوره في الحديث، والغرور يملؤه: أنا أكثر منك مالا وأعز أنصارًا وأعوانًا.", "isBasmala": false, "translation_en": "And thus he had abundant fruits. He said to his friend, as he conversed with him, \"I am wealthier than you, and greater in manpower.\"", "translation_id": "dan dia mempunyai kekayaan besar, maka ia berkata kepada kawannya (yang mukmin) ketika bercakap-cakap dengan dia: \"Hartaku lebih banyak dari pada hartamu dan pengikut-pengikutku lebih kuat\"", "manzil": 4, "manzil_display": ""}], "298": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 35, "text": "وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمࣱ لِّنَفۡسِهِۦ قَالَ مَاۤ أَظُنُّ أَن تَبِیدَ هَـٰذِهِۦۤ أَبَدࣰا ۝٣٥", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "ودخل حديقته، وهو ظالم لنفسه بالكفر بالبعث، وشكه في قيام الساعة، فأعجبته ثمارها وقال: ما أعتقد أن تَهْلِك هذه الحديقة مدى الحياة، وما أعتقد أن القيامة واقعة، وإن فُرِضَ وقوعها -كما تزعم أيها المؤمن- ورُجعتُ إلى ربي لأجدنَّ عنده أفضل من هذه الحديقة مرجعًا ومردًا؛ لكرامتي ومنزلتي عنده.", "isBasmala": false, "translation_en": "And he entered his garden, wronging himself. He said, \"I do not think this will ever perish.\"", "translation_id": "Dan dia memasuki kebunnya sedang dia zalim terhadap dirinya sendiri; ia berkata: \"Aku kira kebun ini tidak akan binasa selama-lamanya,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 36, "text": "وَمَاۤ أَظُنُّ ٱلسَّاعَةَ قَاۤىِٕمَةࣰ وَلَىِٕن رُّدِدتُّ إِلَىٰ رَبِّی لَأَجِدَنَّ خَیۡرࣰا مِّنۡهَا مُنقَلَبࣰا ۝٣٦", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "ودخل حديقته، وهو ظالم لنفسه بالكفر بالبعث، وشكه في قيام الساعة، فأعجبته ثمارها وقال: ما أعتقد أن تَهْلِك هذه الحديقة مدى الحياة، وما أعتقد أن القيامة واقعة، وإن فُرِضَ وقوعها -كما تزعم أيها المؤمن- ورُجعتُ إلى ربي لأجدنَّ عنده أفضل من هذه الحديقة مرجعًا ومردًا؛ لكرامتي ومنزلتي عنده.", "isBasmala": false, "translation_en": "\"And I do not think the Hour is coming. And even if I am returned to my Lord, I will find something better than this in return.\"", "translation_id": "dan aku tidak mengira hari kiamat itu akan datang, dan jika sekiranya aku kembalikan kepada Tuhanku, pasti aku akan mendapat tempat kembali yang lebih baik dari pada kebun-kebun itu\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 37, "text": "قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ یُحَاوِرُهُۥۤ أَكَفَرۡتَ بِٱلَّذِی خَلَقَكَ مِن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ سَوَّىٰكَ رَجُلࣰا ۝٣٧", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "قال له صاحبه المؤمن، وهو يحاوره واعظًا له: كيف تكفر بالله الذي خلقك مِن تراب، ثم مِن نطفة الأبوين، ثم سَوَّاك بشرًا معتدل القامة والخَلْق؟ وفي هذه المحاورة دليل على أن القادر على ابتداء الخلق، قادر على إعادتهم.", "isBasmala": false, "translation_en": "His friend said to him, as he conversed with him, \"Are you being ungrateful to Him who created you from dust, then from a sperm-drop, then evolved you into a man?", "translation_id": "Kawannya (yang mukmin) berkata kepadanya -- sedang dia bercakap-cakap dengannya: \"Apakah kamu kafir kepada (Tuhan) yang menciptakan kamu dari tanah, kemudian dari setetes air mani, lalu Dia menjadikan kamu seorang laki-laki yang sempurna?", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 38, "text": "لَّـٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّی وَلَاۤ أُشۡرِكُ بِرَبِّیۤ أَحَدࣰا ۝٣٨", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "لكن أنا لا أقول بمقالتك الدالة على كفرك، وإنما أقول: المنعم المتفضل هو الله ربي وحده، ولا أشرك في عبادتي له أحدًا غيره.", "isBasmala": false, "translation_en": "But as for me, He is God, my Lord, and I never associate with my Lord anyone.", "translation_id": "Tetapi aku (percaya bahwa): Dialah Allah, Tuhanku, dan aku tidak mempersekutukan seorangpun dengan Tuhanku.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 39, "text": "وَلَوۡلَاۤ إِذۡ دَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَاۤءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالࣰا وَوَلَدࣰا ۝٣٩", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "وهلا حين دخَلْتَ حديقتك فأعجبتك حَمِدت الله، وقلت: هذا ما شاء الله لي، لا قوة لي على تحصيله إلا بالله. إن كنت تراني أقل منك مالا وأولادًا، فعسى ربي أن يعطيني أفضل من حديقتك، ويسلبك النعمة بكفرك، ويرسل على حديقتك عذابا من السماء، فتصبح أرضًا ملساء جرداء لا تثبت عليها قدم، ولا ينبت فيها نبات، أو يصير ماؤها الذي تُسقى منه غائرًا في الأرض، فلا تقدر على إخراجه.", "isBasmala": false, "translation_en": "When you entered your garden, why did you not say, \"As God wills; there is no power except through God\"? Although you see me inferior to you in wealth and children.", "translation_id": "Dan mengapa kamu tidak mengatakan waktu kamu memasuki kebunmu \"maasyaallaah, laa quwwata illaa billaah (sungguh atas kehendak Allah semua ini terwujud, tiada kekuatan kecuali dengan pertolongan Allah). Sekiranya kamu anggap aku lebih sedikit darimu dalam hal harta dan keturunan,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 40, "text": "فَعَسَىٰ رَبِّیۤ أَن یُؤۡتِیَنِ خَیۡرࣰا مِّن جَنَّتِكَ وَیُرۡسِلَ عَلَیۡهَا حُسۡبَانࣰا مِّنَ ٱلسَّمَاۤءِ فَتُصۡبِحَ صَعِیدࣰا زَلَقًا ۝٤٠", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "وهلا حين دخَلْتَ حديقتك فأعجبتك حَمِدت الله، وقلت: هذا ما شاء الله لي، لا قوة لي على تحصيله إلا بالله. إن كنت تراني أقل منك مالا وأولادًا، فعسى ربي أن يعطيني أفضل من حديقتك، ويسلبك النعمة بكفرك، ويرسل على حديقتك عذابا من السماء، فتصبح أرضًا ملساء جرداء لا تثبت عليها قدم، ولا ينبت فيها نبات، أو يصير ماؤها الذي تُسقى منه غائرًا في الأرض، فلا تقدر على إخراجه.", "isBasmala": false, "translation_en": "Perhaps my Lord will give me something better than your garden, and release upon it thunderbolts from the sky, so it becomes barren waste.", "translation_id": "maka mudah-mudahan Tuhanku, akan memberi kepadaku (kebun) yang lebih baik dari pada kebunmu (ini); dan mudah-mudahan Dia mengirimkan ketentuan (petir) dari langit kepada kebunmu; hingga (kebun itu) menjadi tanah yang licin;", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 41, "text": "أَوۡ یُصۡبِحَ مَاۤؤُهَا غَوۡرࣰا فَلَن تَسۡتَطِیعَ لَهُۥ طَلَبࣰا ۝٤١", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "وهلا حين دخَلْتَ حديقتك فأعجبتك حَمِدت الله، وقلت: هذا ما شاء الله لي، لا قوة لي على تحصيله إلا بالله. إن كنت تراني أقل منك مالا وأولادًا، فعسى ربي أن يعطيني أفضل من حديقتك، ويسلبك النعمة بكفرك، ويرسل على حديقتك عذابا من السماء، فتصبح أرضًا ملساء جرداء لا تثبت عليها قدم، ولا ينبت فيها نبات، أو يصير ماؤها الذي تُسقى منه غائرًا في الأرض، فلا تقدر على إخراجه.", "isBasmala": false, "translation_en": "Or its water will sink into the ground, and you will be unable to draw it.\"", "translation_id": "atau airnya menjadi surut ke dalam tanah, maka sekali-kali kamu tidak dapat menemukannya lagi\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 42, "text": "وَأُحِیطَ بِثَمَرِهِۦ فَأَصۡبَحَ یُقَلِّبُ كَفَّیۡهِ عَلَىٰ مَاۤ أَنفَقَ فِیهَا وَهِیَ خَاوِیَةٌ عَلَىٰ عُرُوشِهَا وَیَقُولُ یَـٰلَیۡتَنِی لَمۡ أُشۡرِكۡ بِرَبِّیۤ أَحَدࣰا ۝٤٢", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "وتحَقَّقَ ما قاله المؤمن، ووقع الدمار بالحديقة، فهلك كل ما فيها، فصار الكافر يُقَلِّب كفيه حسرةً وندامة على ما أنفق فيها، وهي خاوية قد سقط بعضها على بعض، ويقول: يا ليتني عرفت نِعَمَ الله وقدرته فلم أشرك به أحدًا. وهذا ندم منه حين لا ينفعه الندم.", "isBasmala": false, "translation_en": "And ruin closed in on his crops, and so he began wringing his hands over what he had invested in it, as it lays fallen upon its trellises. And he was saying, \"I wish I never associated anyone with my Lord.\"", "translation_id": "Dan harta kekayaannya dibinasakan; lalu ia membulak-balikkan kedua tangannya (tanda menyesal) terhadap apa yang ia telah belanjakan untuk itu, sedang pohon anggur itu roboh bersama para-paranya dan dia berkata: \"Aduhai kiranya dulu aku tidak mempersekutukan seorangpun dengan Tuhanku\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 43, "text": "وَلَمۡ تَكُن لَّهُۥ فِئَةࣱ یَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا ۝٤٣", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "ولم تكن له جماعة ممن افتخر بهم يمنعونه مِن عقاب الله النازل به، وما كان ممتنعًا بنفسه وقوته.", "isBasmala": false, "translation_en": "He had no faction to help him besides God, and he was helpless.", "translation_id": "Dan tidak ada bagi dia segolonganpun yang akan menolongnya selain Allah; dan sekali-kali ia tidak dapat membela dirinya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 44, "text": "هُنَالِكَ ٱلۡوَلَـٰیَةُ لِلَّهِ ٱلۡحَقِّۚ هُوَ خَیۡرࣱ ثَوَابࣰا وَخَیۡرٌ عُقۡبࣰا ۝٤٤", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "في مثل هذه الشدائد تكون الولاية والنصرة لله الحق، هو خير جزاءً، وخير عاقبة لمن تولاهم من عباده المؤمنين.", "isBasmala": false, "translation_en": "That is because authority belongs to God, the True. He is Best in rewarding, and Best in requiting.", "translation_id": "Di sana pertolongan itu hanya dari Allah Yang Hak. Dia adalah sebaik-baik Pemberi pahala dan sebaik-baik Pemberi balasan.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 45, "text": "وَٱضۡرِبۡ لَهُم مَّثَلَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا كَمَاۤءٍ أَنزَلۡنَـٰهُ مِنَ ٱلسَّمَاۤءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ فَأَصۡبَحَ هَشِیمࣰا تَذۡرُوهُ ٱلرِّیَـٰحُۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ مُّقۡتَدِرًا ۝٤٥", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "واضرب أيها الرسول للناس -وبخاصة ذوو الكِبْر منهم - صفة الدنيا التي اغترُّوا بها في بهجتها وسرعة زوالها، فهي كماء أنزله الله من السماء فخرج به النبات بإذنه، وصار مُخْضرًّا، وما هي إلا مدة يسيرة حتى صار هذا النبات يابسًا متكسرًا تنسفه الرياح إلى كل جهة. وكان الله على كل شيء مقتدرًا، أي: ذا قدرة عظيمة على كل شيء.", "isBasmala": false, "translation_en": "And cite for them the parable of the present life: it is like water that We send down from the sky; the plants of the earth absorb it; but then it becomes debris, scattered by the wind. God has absolute power over everything.", "translation_id": "Dan berilah perumpamaan kepada mereka (manusia), kehidupan dunia sebagai air hujan yang Kami turunkan dari langit, maka menjadi subur karenanya tumbuh-tumbuhan di muka bumi, kemudian tumbuh-tumbuhan itu menjadi kering yang diterbangkan oleh angin. Dan adalah Allah, Maha Kuasa atas segala sesuatu.", "manzil": 4, "manzil_display": ""}], "299": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 46, "text": "ٱلۡمَالُ وَٱلۡبَنُونَ زِینَةُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَٱلۡبَـٰقِیَـٰتُ ٱلصَّـٰلِحَـٰتُ خَیۡرٌ عِندَ رَبِّكَ ثَوَابࣰا وَخَیۡرٌ أَمَلࣰا ۝٤٦", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "الأموال والأولاد جَمال وقوة في هذه الدنيا الفانية، والأعمال الصالحة -وبخاصة التسبيحُ والتحميد والتكبير والتهليل- أفضل أجرًا عند ربك من المال والبنين، وهذه الأعمال الصالحة أفضل ما يرجو الإنسان من الثواب عند ربه، فينال بها في الآخرة ما كان يأمُله في الدنيا.", "isBasmala": false, "translation_en": "Wealth and children are the adornments of the present life. But the things that last, the virtuous deeds, are better with your Lord for reward, and better for hope.", "translation_id": "Harta dan anak-anak adalah perhiasan kehidupan dunia tetapi amalan-amalan yang kekal lagi saleh adalah lebih baik pahalanya di sisi Tuhanmu serta lebih baik untuk menjadi harapan.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 47, "text": "وَیَوۡمَ نُسَیِّرُ ٱلۡجِبَالَ وَتَرَى ٱلۡأَرۡضَ بَارِزَةࣰ وَحَشَرۡنَـٰهُمۡ فَلَمۡ نُغَادِرۡ مِنۡهُمۡ أَحَدࣰا ۝٤٧", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "واذكر لهم يوم نُزيل الجبال عن أماكنها، وتبصر الأرض ظاهرة، ليس عليها ما يسترها مما كان عليها من المخلوقات، وجمعنا الأولين والآخِرين لموقف الحساب، فلم نترك منهم أحدًا.", "isBasmala": false, "translation_en": "On the Day when We set the mountains in motion; and you see the earth emerging; and We gather them together, and leave none of them behind.", "translation_id": "Dan (ingatlah) akan hari (yang ketika itu) Kami perjalankan gunung-gunung dan kamu akan dapat melihat bumi itu datar dan Kami kumpulkan seluruh manusia, dan tidak kami tinggalkan seorangpun dari mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 48, "text": "وَعُرِضُوا۟ عَلَىٰ رَبِّكَ صَفࣰّا لَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَـٰكُمۡ أَوَّلَ مَرَّةِۭۚ بَلۡ زَعَمۡتُمۡ أَلَّن نَّجۡعَلَ لَكُم مَّوۡعِدࣰا ۝٤٨", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "وعُرِضوا جميعًا على ربك مصطَفِّين لا يُحجب منهم أحد، لقد بعثناكم، وجئتم إلينا فرادى لا مال معكم ولا ولد، كما خلقناكم أول مرة، بل ظننتم أن لن نجعل لكم موعدًا نبعثكم فيه، ونجازيكم على أعمالكم.", "isBasmala": false, "translation_en": "They will be presented before your Lord in a row. \"You have come to Us as We created you the first time. Although you claimed We would not set a meeting for you.\"", "translation_id": "Dan mereka akan dibawa ke hadapan Tuhanmu dengan berbaris. Sesungguhnya kamu datang kepada Kami, sebagaimana Kami menciptakan kamu pada kali yang pertama; bahkan kamu mengatakan bahwa Kami sekali-kali tidak akan menetapkan bagi kamu waktu (memenuhi) perjanjian.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 49, "text": "وَوُضِعَ ٱلۡكِتَـٰبُ فَتَرَى ٱلۡمُجۡرِمِینَ مُشۡفِقِینَ مِمَّا فِیهِ وَیَقُولُونَ یَـٰوَیۡلَتَنَا مَالِ هَـٰذَا ٱلۡكِتَـٰبِ لَا یُغَادِرُ صَغِیرَةࣰ وَلَا كَبِیرَةً إِلَّاۤ أَحۡصَىٰهَاۚ وَوَجَدُوا۟ مَا عَمِلُوا۟ حَاضِرࣰاۗ وَلَا یَظۡلِمُ رَبُّكَ أَحَدࣰا ۝٤٩", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "ووُضِع كتاب أعمال كل واحد في يمينه أو في شماله، فتبصر العصاة خائفين مما فيه بسبب ما قدموه من جرائمهم، ويقولون حين يعاينونه: يا هلاكنا! ما لهذا الكتاب لم يترك صغيرة مِن أفعالنا ولا كبيرة إلا أثبتها؟! ووجدوا كل ما عملوه في الدنيا حاضرًا مثبتًا. ولا يظلم ربك أحدًا مثقال ذرة، فلا يُنقَص طائع من ثوابه، ولا يُزاد عاص في عقابه.", "isBasmala": false, "translation_en": "And the book will be placed, and you will see the sinners fearful of its contents. And they will say, \"Woe to us! What is with this book that leaves nothing, small or big, but it has enumerated it?\" They will find everything they had done present. Your Lord does not wrong anyone.", "translation_id": "Dan diletakkanlah kitab, lalu kamu akan melihat orang-orang bersalah ketakutan terhadap apa yang (tertulis) di dalamnya, dan mereka berkata: \"Aduhai celaka kami, kitab apakah ini yang tidak meninggalkan yang kecil dan tidak (pula) yang besar, melainkan ia mencatat semuanya; dan mereka dapati apa yang telah mereka kerjakan ada (tertulis). Dan Tuhanmu tidak menganiaya seorang juapun\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 50, "text": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ كَانَ مِنَ ٱلۡجِنِّ فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦۤۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّیَّتَهُۥۤ أَوۡلِیَاۤءَ مِن دُونِی وَهُمۡ لَكُمۡ عَدُوُّۢۚ بِئۡسَ لِلظَّـٰلِمِینَ بَدَلࣰا ۝٥٠", "juz": 15, "hizb": "(*½ ح 30*)", "tafsir": "واذكر حين أمرنا الملائكة بالسجود لآدم، تحية له لا عبادة، وأمرنا إبليس بما أُمِروا به، فسجد الملائكة جميعًا، لكن إبليس الذي كان من الجن خرج عن طاعة ربه، ولم يسجد كِبرًا وحسدًا. أفتجعلونه -أيها الناس- وذريته أعوانًا لكم تطيعونهم وتتركون طاعتي، وهم ألد أعدائكم؟ قَبُحَتْ طاعة الظالمين للشيطان بدلا عن طاعة الرحمن.", "isBasmala": false, "translation_en": "We said to the angels, \"Bow down to Adam.\" So they bowed down, except for Satan. He was of the jinn, and he defied the command of his Lord. Will you take him and his offspring as lords instead of Me, when they are an enemy to you? Evil is the exchange for the wrongdoers.", "translation_id": "Dan (ingatlah) ketika Kami berfirman kepada para malaikat: \"Sujudlah kamu kepada Adam, maka sujudlah mereka kecuali Iblis. Dia adalah dari golongan jin, maka ia mendurhakai perintah Tuhannya. Patutkah kamu mengambil dia dan turanan-turunannya sebagai pemimpin selain daripada-Ku, sedang mereka adalah musuhmu? Amat buruklah iblis itu sebagai pengganti (dari Allah) bagi orang-orang yang zalim.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 51, "text": "۞ مَّاۤ أَشۡهَدتُّهُمۡ خَلۡقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَلَا خَلۡقَ أَنفُسِهِمۡ وَمَا كُنتُ مُتَّخِذَ ٱلۡمُضِلِّینَ عَضُدࣰا ۝٥١", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "ما أحضرتُ إبليس وذريته -الذين أطعتموهم- خَلْقَ السموات والأرض، فأستعين بهم على خلقهما، ولا أشهدتُ بعضهم على خَلْق بعض، بل تفردتُ بخلق جميع ذلك، بغير معين ولا ظهير، وما كنت متخذ المضلِّين من الشياطين وغيرهم أعوانًا. فكيف تصرفون إليهم حقي، وتتخذونهم أولياء من دوني، وأنا خالق كل شيء؟", "isBasmala": false, "translation_en": "I did not call them to witness the creation of the heavens and the earth, nor their own creation; and I do not take the misleaders for assistants.", "translation_id": "Aku tidak menghadirkan mereka (iblis dan anak cucunya) untuk menyaksikan penciptaan langit dan bumi dan tidak (pula) penciptaan diri mereka sendiri; dan tidaklah Aku mengambil orang-orang yang menyesatkan itu sebagai penolong.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 52, "text": "وَیَوۡمَ یَقُولُ نَادُوا۟ شُرَكَاۤءِیَ ٱلَّذِینَ زَعَمۡتُمۡ فَدَعَوۡهُمۡ فَلَمۡ یَسۡتَجِیبُوا۟ لَهُمۡ وَجَعَلۡنَا بَیۡنَهُم مَّوۡبِقࣰا ۝٥٢", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "واذكر لهم إذ يقول الله للمشركين يوم القيامة: نادوا شركائي الذين كنتم تزعمون أنهم شركاء لي في العبادة؛ لينصروكم اليوم مني، فاستغاثوا بهم فلم يغيثوهم، وجعلنا بين العابدين والمعبودين مهلكًا في جهنم يهلكون فيه جميعًا.", "isBasmala": false, "translation_en": "On the Day when He will say, \"Call on My partners whom you have claimed.\" They will call on them, but they will not answer them. And We will place between them a barrier.", "translation_id": "Dan (ingatlah) akan hari (yang ketika itu) Dia berfirman: \"Serulah olehmu sekalian sekutu-sekutu-Ku yang kamu katakan itu\". Mereka lalu memanggilnya tetapi sekutu-sekutu itu tidak membalas seruan mereka dan Kami adakan untuk mereka tempat kebinasaan (neraka).", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 53, "text": "وَرَءَا ٱلۡمُجۡرِمُونَ ٱلنَّارَ فَظَنُّوۤا۟ أَنَّهُم مُّوَاقِعُوهَا وَلَمۡ یَجِدُوا۟ عَنۡهَا مَصۡرِفࣰا ۝٥٣", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "وشاهد المجرمون النار، فأيقنوا أنهم واقعون فيها لا محالة، ولم يجدوا عنها معدلا للانصراف عنها إلى غيرها.", "isBasmala": false, "translation_en": "And the sinners will see the Fire, and will realize that they will tumble into it. They will find no deliverance from it.", "translation_id": "Dan orang-orang yang berdosa melihat neraka, maka mereka meyakini, bahwa mereka akan jatuh ke dalamnya dan mereka tidak menemukan tempat berpaling dari padanya.", "manzil": 4, "manzil_display": ""}], "300": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 54, "text": "وَلَقَدۡ صَرَّفۡنَا فِی هَـٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلࣲۚ وَكَانَ ٱلۡإِنسَـٰنُ أَكۡثَرَ شَیۡءࣲ جَدَلࣰا ۝٥٤", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "ولقد وضَّحنا ونوَّعنا في هذا القرآن للناس أنواعًا كثيرة من الأمثال؛ ليتعظوا بها ويؤمنوا. وكان الإنسان أكثر المخلوقات خصومة وجدلا.", "isBasmala": false, "translation_en": "We have elaborated in this Quran for the people every kind of example, but the human being is a most argumentative being.", "translation_id": "Dan sesungguhnya Kami telah mengulang-ulangi bagi manusia dalam Al Quran ini bermacam-macam perumpamaan. Dan manusia adalah makhluk yang paling banyak membantah.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 55, "text": "وَمَا مَنَعَ ٱلنَّاسَ أَن یُؤۡمِنُوۤا۟ إِذۡ جَاۤءَهُمُ ٱلۡهُدَىٰ وَیَسۡتَغۡفِرُوا۟ رَبَّهُمۡ إِلَّاۤ أَن تَأۡتِیَهُمۡ سُنَّةُ ٱلۡأَوَّلِینَ أَوۡ یَأۡتِیَهُمُ ٱلۡعَذَابُ قُبُلࣰا ۝٥٥", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "وما منع الناس من الإيمان -حين جاءهم الرسول محمد صلى الله عليه وسلم ومعه القرآن-، واستغفار ربهم طالبين عفوه عنهم، إلا تحدِّيهم للرسول، وطلبهم أن تصيبهم سنة الله في إهلاك السابقين عليهم، أو يصيبهم عذاب الله عِيانًا.", "isBasmala": false, "translation_en": "What prevented people from accepting faith, when guidance has come to them, and from seeking their Lord's forgiveness? Unless they are waiting for the precedent of the ancients to befall them, or to have the punishment come upon them face to face.", "translation_id": "Dam tidak ada sesuatupun yang menghalangi manusia dari beriman, ketika petunjuk telah datang kepada mereka, dan dari memohon ampun kepada Tuhannya, kecuali (keinginan menanti) datangnya hukum (Allah yang telah berlalu pada) umat-umat yang dahulu atau datangnya azab atas mereka dengan nyata.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 56, "text": "وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِینَ إِلَّا مُبَشِّرِینَ وَمُنذِرِینَۚ وَیُجَـٰدِلُ ٱلَّذِینَ كَفَرُوا۟ بِٱلۡبَـٰطِلِ لِیُدۡحِضُوا۟ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوۤا۟ ءَایَـٰتِی وَمَاۤ أُنذِرُوا۟ هُزُوࣰا ۝٥٦", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "وما نبعث الرسل إلى الناس إلا ليكونوا مبشرين بالجنة لأهل الإيمان والعمل الصالح، ومخوِّفين بالنار لأهل الكفر والعصيان، ومع وضوح الحق يخاصم الذين كفروا رسلهم بالباطل تعنتًا؛ ليزيلوا بباطلهم الحق الذي جاءهم به الرسول، واتخذوا كتابي وحججي وما خُوّفوا به من العذاب سخرية واستهزاء.", "isBasmala": false, "translation_en": "We send the messengers only as deliverers of good news and warners. Those who disbelieve argue with false argument, in order to defeat the truth thereby. They take My Verses, and the warnings, for a joke.", "translation_id": "Dan tidaklah Kami mengutus rasul-rasul hanyalah sebagai pembawa berita gembira dan sebagai pemberi peringatan; tetapi orang-orang yang kafir membantah dengan yang batil agar dengan demikian mereka dapat melenyap kan yang hak, dan mereka menganggap ayat-ayat kami dan peringatan-peringatan terhadap mereka sebagai olok-olokan.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 57, "text": "وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔایَـٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِیَ مَا قَدَّمَتۡ یَدَاهُۚ إِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن یَفۡقَهُوهُ وَفِیۤ ءَاذَانِهِمۡ وَقۡرࣰاۖ وَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن یَهۡتَدُوۤا۟ إِذًا أَبَدࣰا ۝٥٧", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "ولا أحد أشد ظلمًا ممن وُعِظ بآيات ربه الواضحة، فانصرف عنها إلى باطله، ونسي ما قدَّمته يداه من الأفعال القبيحة فلم يرجع عنها، إنَّا جعلنا على قلوبهم أغطية، فلم يفهموا القرآن، ولم يدركوا ما فيه من الخير، وجعلنا في آذانهم ما يشبه الصمم، فلم يسمعوه ولم ينتفعوا به، وإن تَدْعُهم إلى الإيمان فلن يستجيبوا لك، ولن يهتدوا إليه أبدًا.", "isBasmala": false, "translation_en": "Who does greater wrong than he, who, when reminded of his Lord's revelations, turns away from them, and forgets what his hands have put forward? We have placed coverings over their hearts, lest they understand it, and heaviness in their ears. And if you call them to guidance, they will not be guided, ever.", "translation_id": "Dan siapakah yang lebih zalim dari pada orang yang telah diperingatkan dengan ayat-ayat Tuhannya lalu dia berpaling dari padanya dan melupakan apa yang telah dikerjakan oleh kedua tangannya? Sesungguhnya Kami telah meletakkan tutupan di atas hati mereka, (sehingga mereka tidak) memahaminya, dan (Kami letakkan pula) sumbatan di telinga mereka; dan kendatipun kamu menyeru mereka kepada petunjuk, niscaya mereka tidak akan mendapat petunjuk selama-lamanya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 58, "text": "وَرَبُّكَ ٱلۡغَفُورُ ذُو ٱلرَّحۡمَةِۖ لَوۡ یُؤَاخِذُهُم بِمَا كَسَبُوا۟ لَعَجَّلَ لَهُمُ ٱلۡعَذَابَۚ بَل لَّهُم مَّوۡعِدࣱ لَّن یَجِدُوا۟ مِن دُونِهِۦ مَوۡىِٕلࣰا ۝٥٨", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "وربك الغفور لذنوب عباده إذا تابوا، ذو الرحمة بهم، لو يعاقب هؤلاء المعرضين عن آياته بما كسبوا من الذنوب والآثام لعجَّل لهم العذاب، ولكنه تعالى حليم لا يعجل بالعقوبة، بل لهم موعد يجازون فيه بأعمالهم، لا مندوحة لهم عنه ولا محيد.", "isBasmala": false, "translation_en": "Your Lord is the Forgiver, Possessor of Mercy. Were He to call them to account for what they have earned, He would have hastened the punishment for them. But they have an appointment from which they will find no escape.", "translation_id": "Dan Tuhanmulah yang Maha Pengampun, lagi mempunyai rahmat. Jika Dia mengazab mereka karena perbuatan mereka, tentu Dia akan menyegerakan azab bagi mereka. Tetapi bagi mereka ada waktu yang tertentu (untuk mendapat azab) yang mereka sekali-kali tidak akan menemukan tempat berlindung dari padanya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 59, "text": "وَتِلۡكَ ٱلۡقُرَىٰۤ أَهۡلَكۡنَـٰهُمۡ لَمَّا ظَلَمُوا۟ وَجَعَلۡنَا لِمَهۡلِكِهِم مَّوۡعِدࣰا ۝٥٩", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "وتلك القرى القريبة منكم -كقرى قوم هود وصالح ولوط وشعيب- أهلكناها حين ظلم أهلها بالكفر، وجعلنا لهلاكهم ميقاتًا وأجلا حين بلغوه جاءهم العذاب فأهلكهم الله به.", "isBasmala": false, "translation_en": "And these towns-We destroyed them when they committed injustices, and We set for their destruction an appointed time.", "translation_id": "Dan (penduduk) negeri telah Kami binasakan ketika mereka berbuat zalim, dan telah Kami tetapkan waktu tertentu bagi kebinasaan mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 60, "text": "وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَاۤ أَبۡرَحُ حَتَّىٰۤ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَیۡنِ أَوۡ أَمۡضِیَ حُقُبࣰا ۝٦٠", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "واذكر حين قال موسى لخادمه يوشع بن نون: لا أزال أتابع السير حتى أصل إلى ملتقى البحرين، أو أسير زمنًا طويلا حتى أصل إلى العبد الصالح؛ لأتعلم منه ما ليس عندي من العلم.", "isBasmala": false, "translation_en": "Recall when Moses said to his servant, \"I will not give up until I reach the junction of the two rivers, even if it takes me years.\"", "translation_id": "Dan (ingatlah) ketika Musa berkata kepada muridnya: \"Aku tidak akan berhenti (berjalan) sebelum sampai ke pertemuan dua buah lautan; atau aku akan berjalan sampai bertahun-tahun\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 61, "text": "فَلَمَّا بَلَغَا مَجۡمَعَ بَیۡنِهِمَا نَسِیَا حُوتَهُمَا فَٱتَّخَذَ سَبِیلَهُۥ فِی ٱلۡبَحۡرِ سَرَبࣰا ۝٦١", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "وجَدَّا في السَّيْر، فلما وصلا ملتقى البحرين جلسا عند صخرة، ونسيا حوتهما الذي أُمر موسى بأخذه معه قوتًا لهما، وحمله يوشع في مِكْتَل، فإذا الحوت يصبح حيًّا وينحدر في البحر، ويتخذ له فيه طريقًا مفتوحًا.", "isBasmala": false, "translation_en": "Then, when they reached the junction between them, they forgot about their fish. It found its way into the river, slipping away.", "translation_id": "Maka tatkala mereka sampai ke pertemuan dua buah laut itu, mereka lalai akan ikannya, lalu ikan itu melompat mengambil jalannya ke laut itu.", "manzil": 4, "manzil_display": ""}], "301": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 62, "text": "فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَاۤءَنَا لَقَدۡ لَقِینَا مِن سَفَرِنَا هَـٰذَا نَصَبࣰا ۝٦٢", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "فلما فارقا المكان الذي نسيا فيه الحوت وشعر موسى بالجوع، قال لخادمه: أحضر إلينا غداءنا، لقد لقينا من سفرنا هذا تعبًا.", "isBasmala": false, "translation_en": "When they went further, he said to his servant, \"Bring us our lunch; we were exposed in our travel to much fatigue.\"", "translation_id": "Maka tatkala mereka berjalan lebih jauh, berkatalah Musa kepada muridnya: \"Bawalah kemari makanan kita; sesungguhnya kita telah merasa letih karena perjalanan kita ini\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 63, "text": "قَالَ أَرَءَیۡتَ إِذۡ أَوَیۡنَاۤ إِلَى ٱلصَّخۡرَةِ فَإِنِّی نَسِیتُ ٱلۡحُوتَ وَمَاۤ أَنسَىٰنِیهُ إِلَّا ٱلشَّیۡطَـٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِیلَهُۥ فِی ٱلۡبَحۡرِ عَجَبࣰا ۝٦٣", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "قال له خادمه: أتذكر حين لجأنا إلى الصخرة التي استرحنا عندها؟ فإني نسيت أن أخبرك ما كان من الحوت، وما أنساني أن أذكر ذلك لك إلا الشيطان، فإن الحوت الميت دبَّتْ فيه الحياة، وقفز في البحر، واتخذ له فيه طريقًا، وكان أمره مما يُعْجَبُ منه.", "isBasmala": false, "translation_en": "He said, \"Do you remember when we rested by the rock? I forgot about the fish. It was only the devil who made me forget it. And so it found its way to the river, amazingly.\"", "translation_id": "Muridnya menjawab: \"Tahukah kamu tatkala kita mencari tempat berlindung di batu tadi, maka sesungguhnya aku lupa (menceritakan tentang) ikan itu dan tidak adalah yang melupakan aku untuk menceritakannya kecuali syaitan dan ikan itu mengambil jalannya ke laut dengan cara yang aneh sekali\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 64, "text": "قَالَ ذَ ٰلِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰۤ ءَاثَارِهِمَا قَصَصࣰا ۝٦٤", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "قال موسى: ما حصل هو ما كنا نطلبه، فإنه علامة لي على مكان العبد الصالح، فرجعا يقصان آثار مشيهما حتى انتهيا إلى الصخرة.", "isBasmala": false, "translation_en": "He said, \"This is what we were seeking.\" And so they turned back retracing their steps.", "translation_id": "Musa berkata: \"Itulah (tempat) yang kita cari\". Lalu keduanya kembali, mengikuti jejak mereka semula.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 65, "text": "فَوَجَدَا عَبۡدࣰا مِّنۡ عِبَادِنَاۤ ءَاتَیۡنَـٰهُ رَحۡمَةࣰ مِّنۡ عِندِنَا وَعَلَّمۡنَـٰهُ مِن لَّدُنَّا عِلۡمࣰا ۝٦٥", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "فوجدا هناك عبدًا صالحًا من عبادنا هو الخَضِر عليه السلام -وهو نبي من أنبياء الله توفاه الله-، آتيناه رحمة من عندنا، وعَلَّمْناه مِن لدنَّا علمًا عظيمًا.", "isBasmala": false, "translation_en": "Then they came upon a servant of Ours, whom We had blessed with mercy from Us, and had taught him knowledge from Our Own.", "translation_id": "Lalu mereka bertemu dengan seorang hamba di antara hamba-hamba Kami, yang telah Kami berikan kepadanya rahmat dari sisi Kami, dan yang telah Kami ajarkan kepadanya ilmu dari sisi Kami.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 66, "text": "قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰۤ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدࣰا ۝٦٦", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "فسلَّم عليه موسى، وقال له: أتأذن لي أن أتبعك؛ لتعلمني من العلم الذي علمك الله إياه ما أسترشد به وأنتفع؟", "isBasmala": false, "translation_en": "Moses said to him, \"May I follow you, so that you may teach me some of the guidance you were taught?\"", "translation_id": "Musa berkata kepada Khidhr: \"Bolehkah aku mengikutimu supaya kamu mengajarkan kepadaku ilmu yang benar di antara ilmu-ilmu yang telah diajarkan kepadamu?\"", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 67, "text": "قَالَ إِنَّكَ لَن تَسۡتَطِیعَ مَعِیَ صَبۡرࣰا ۝٦٧", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "قال له الخَضِر: إنك -يا موسى- لن تطيق أن تصبر على اتباعي وملازمتي.", "isBasmala": false, "translation_en": "He said, \"You will not be able to endure with me.", "translation_id": "Dia menjawab: \"Sesungguhnya kamu sekali-kali tidak akan sanggup sabar bersama aku.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 68, "text": "وَكَیۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرࣰا ۝٦٨", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "وكيف لك الصبر على ما سأفعله من أمور تخفى عليك مما علمنيه الله تعالى؟", "isBasmala": false, "translation_en": "And how will you endure what you have no knowledge of?\"", "translation_id": "Dan bagaimana kamu dapat sabar atas sesuatu, yang kamu belum mempunyai pengetahuan yang cukup tentang hal itu?\"", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 69, "text": "قَالَ سَتَجِدُنِیۤ إِن شَاۤءَ ٱللَّهُ صَابِرࣰا وَلَاۤ أَعۡصِی لَكَ أَمۡرࣰا ۝٦٩", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "قال له موسى: ستجدني إن شاء الله صابرًا على ما أراه منك، ولا أخالف لك أمرًا تأمرني به.", "isBasmala": false, "translation_en": "He said, \"You will find me, God willing, patient; and I will not disobey you in any order of yours.\"", "translation_id": "Musa berkata: \"Insya Allah kamu akan mendapati aku sebagai orang yang sabar, dan aku tidak akan menentangmu dalam sesuatu urusanpun\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 70, "text": "قَالَ فَإِنِ ٱتَّبَعۡتَنِی فَلَا تَسۡـَٔلۡنِی عَن شَیۡءٍ حَتَّىٰۤ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرࣰا ۝٧٠", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "فوافق الخَضِر وقال له: فإنْ صاحَبتني فلا تسألني عن شيء تنكره، حتى أبيِّن لك من أمره ما خفي عليك دون سؤال منك.", "isBasmala": false, "translation_en": "He said, \"If you follow me, do not ask me about anything, until I myself make mention of it to you.\"", "translation_id": "Dia berkata: \"Jika kamu mengikutiku, maka janganlah kamu menanyakan kepadaku tentang sesuatu apapun, sampai aku sendiri menerangkannya kepadamu\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 71, "text": "فَٱنطَلَقَا حَتَّىٰۤ إِذَا رَكِبَا فِی ٱلسَّفِینَةِ خَرَقَهَاۖ قَالَ أَخَرَقۡتَهَا لِتُغۡرِقَ أَهۡلَهَا لَقَدۡ جِئۡتَ شَیۡـًٔا إِمۡرࣰا ۝٧١", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "فانطلقا يمشيان على الساحل، فمرت بهما سفينة، فطلبا من أهلها أن يركبا معهم، فلما ركبا قَلَعَ الخَضِر لوحًا من السفينة فخرقها، فقال له موسى: أَخَرَقْتَ السفينة؛ لتُغرِق أهلَها، وقد حملونا بغير أجر؟ لقد فعلت أمرًا منكرًا.", "isBasmala": false, "translation_en": "So they set out. Until, when they had boarded the boat, he holed it. He said, \"Did you hole it, to drown its passengers? You have done something awful.\"", "translation_id": "Maka berjalanlah keduanya, hingga tatkala keduanya menaiki perahu lalu Khidhr melobanginya. Musa berkata: \"Mengapa kamu melobangi perahu itu akibatnya kamu menenggelamkan penumpangnya?\" Sesungguhnya kamu telah berbuat sesuatu kesalahan yang besar.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 72, "text": "قَالَ أَلَمۡ أَقُلۡ إِنَّكَ لَن تَسۡتَطِیعَ مَعِیَ صَبۡرࣰا ۝٧٢", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "قال له الخَضِر: لقد قلت لك من أول الأمر: إنك لن تستطيع الصبر على صحبتي.", "isBasmala": false, "translation_en": "He said, \"Did I not tell you that you will not be able to endure with me?\"", "translation_id": "Dia (Khidhr) berkata: \"Bukankah aku telah berkata: \"Sesungguhnya kamu sekali-kali tidak akan sabar bersama dengan aku\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 73, "text": "قَالَ لَا تُؤَاخِذۡنِی بِمَا نَسِیتُ وَلَا تُرۡهِقۡنِی مِنۡ أَمۡرِی عُسۡرࣰا ۝٧٣", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "قال موسى معتذرًا: لا تؤاخذني بنسياني شرطك عليَّ، ولا تكلفني مشقةً في تعلُّمي منك، وعاملني بيسر ورفق.", "isBasmala": false, "translation_en": "He said, \"Do not rebuke me for forgetting, and do not make my course difficult for me.\"", "translation_id": "Musa berkata: \"Janganlah kamu menghukum aku karena kelupaanku dan janganlah kamu membebani aku dengan sesuatu kesulitan dalam urusanku\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 74, "text": "فَٱنطَلَقَا حَتَّىٰۤ إِذَا لَقِیَا غُلَـٰمࣰا فَقَتَلَهُۥ قَالَ أَقَتَلۡتَ نَفۡسࣰا زَكِیَّةَۢ بِغَیۡرِ نَفۡسࣲ لَّقَدۡ جِئۡتَ شَیۡـࣰٔا نُّكۡرࣰا ۝٧٤", "juz": 15, "hizb": "(*¾ ح 30*)", "tafsir": "فقبل الخَضِر عذره، ثم خرجا من السفينة، فبينما هما يمشيان على الساحل إذ أبصرا غلامًا يلعب مع الغلمان، فقتله الخَضِر، فأنكر موسى عليه وقال: كيف قتلت نفسًا طاهرة لم تبلغ حدَّ التكليف، ولم تقتل نفسًا، حتى تستحق القتل بها؟ لقد فَعَلْتَ أمرًا منكرًا عظيمًا.", "isBasmala": false, "translation_en": "Then they set out. Until, when they encountered a boy, he killed him. He said, \"Did you kill a pure soul, who killed no one? You have done something terrible.\"", "translation_id": "Maka berjalanlah keduanya; hingga tatkala keduanya berjumpa dengan seorang anak, maka Khidhr membunuhnya. Musa berkata: \"Mengapa kamu membunuh jiwa yang bersih, bukan karena dia membunuh orang lain? Sesungguhnya kamu telah melakukan suatu yang mungkar\".", "manzil": 4, "manzil_display": ""}], "302": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 75, "text": "۞ قَالَ أَلَمۡ أَقُل لَّكَ إِنَّكَ لَن تَسۡتَطِیعَ مَعِیَ صَبۡرࣰا ۝٧٥", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "قال الخَضِر لموسى معاتبًا ومذكرًا: ألم أقل لك إنك لن تستطيع معي صبرًا على ما ترى من أفعالي مما لم تحط به خُبْرًا؟", "isBasmala": false, "translation_en": "He said, \"Did I not tell you that you will not be able to endure with me?\"", "translation_id": "Khidhr berkata: \"Bukankah sudah kukatakan kepadamu, bahwa sesungguhnya kamu tidak akan dapat sabar bersamaku?\"", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 76, "text": "قَالَ إِن سَأَلۡتُكَ عَن شَیۡءِۭ بَعۡدَهَا فَلَا تُصَـٰحِبۡنِیۖ قَدۡ بَلَغۡتَ مِن لَّدُنِّی عُذۡرࣰا ۝٧٦", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "قال موسى له: إن سألتك عن شيء بعد هذه المرة فاتركني ولا تصاحبني، قد بلغتَ العذر في شأني ولم تقصر؛ حيث أخبرتَني أني لن أستطيع معك صبرًا.", "isBasmala": false, "translation_en": "He said, \"If I ask you about anything after this, then do not keep company with me. You have received excuses from me.\"", "translation_id": "Musa berkata: \"Jika aku bertanya kepadamu tentang sesuatu sesudah (kali) ini, maka janganlah kamu memperbolehkan aku menyertaimu, sesungguhnya kamu sudah cukup memberikan uzur padaku\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 77, "text": "فَٱنطَلَقَا حَتَّىٰۤ إِذَاۤ أَتَیَاۤ أَهۡلَ قَرۡیَةٍ ٱسۡتَطۡعَمَاۤ أَهۡلَهَا فَأَبَوۡا۟ أَن یُضَیِّفُوهُمَا فَوَجَدَا فِیهَا جِدَارࣰا یُرِیدُ أَن یَنقَضَّ فَأَقَامَهُۥۖ قَالَ لَوۡ شِئۡتَ لَتَّخَذۡتَ عَلَیۡهِ أَجۡرࣰا ۝٧٧", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "فذهب موسى والخَضِر حتى أتيا أهل قرية، فطلبا منهم طعامًا على سبيل الضيافة، فامتنع أهل القرية عن ضيافتهما، فوجدا فيها حائطًا مائلا يوشك أن يسقط، فعدَّل الخَضِر مَيْلَه حتى صار مستويًا، قال له موسى: لو شئت لأخذت على هذا العمل أجرًا تصرفه في تحصيل طعامنا حيث لم يضيفونا.", "isBasmala": false, "translation_en": "So they set out. Until, when they reached the people of a town, they asked them for food, but they refused to offer them hospitality. There they found a wall about to collapse, and he repaired it. He said, \"If you wanted, you could have obtained a payment for it.\"", "translation_id": "Maka keduanya berjalan; hingga tatkala keduanya sampai kepada penduduk suatu negeri, mereka minta dijamu kepada penduduk negeri itu, tetapi penduduk negeri itu tidak mau menjamu mereka, kemudian keduanya mendapatkan dalam negeri itu dinding rumah yang hampir roboh, maka Khidhr menegakkan dinding itu. Musa berkata: \"Jikalau kamu mau, niscaya kamu mengambil upah untuk itu\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 78, "text": "قَالَ هَـٰذَا فِرَاقُ بَیۡنِی وَبَیۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِیلِ مَا لَمۡ تَسۡتَطِع عَّلَیۡهِ صَبۡرًا ۝٧٨", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "قال الخَضِر لموسى: هذا وقت الفراق بيني وبينك، سأخبرك بما أنكرت عليَّ من أفعالي التي فعلتها، والتي لم تستطع صبرًا على ترك السؤال عنها والإنكار عليَّ فيها.", "isBasmala": false, "translation_en": "He said, \"This is the parting between you and me. I will tell you the interpretation of what you were unable to endure.", "translation_id": "Khidhr berkata: \"Inilah perpisahan antara aku dengan kamu; kelak akan kuberitahukan kepadamu tujuan perbuatan-perbuatan yang kamu tidak dapat sabar terhadapnya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 79, "text": "أَمَّا ٱلسَّفِینَةُ فَكَانَتۡ لِمَسَـٰكِینَ یَعۡمَلُونَ فِی ٱلۡبَحۡرِ فَأَرَدتُّ أَنۡ أَعِیبَهَا وَكَانَ وَرَاۤءَهُم مَّلِكࣱ یَأۡخُذُ كُلَّ سَفِینَةٍ غَصۡبࣰا ۝٧٩", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "أما السفينة التي خرقتها فإنها كانت لأناس مساكين يعملون في البحر عليها سعيًا وراء الرزق، فأردت أن أعيبها بذلك الخرق؛ لأن أمامهم ملكًا يأخذ كل سفينة صالحة غصبًا من أصحابها.", "isBasmala": false, "translation_en": "As for the boat, it belonged to paupers working at sea. I wanted to damage it because there was a king coming after them seizing every boat by force.", "translation_id": "Adapun bahtera itu adalah kepunyaan orang-orang miskin yang bekerja di laut, dan aku bertujuan merusakkan bahtera itu, karena di hadapan mereka ada seorang raja yang merampas tiap-tiap bahtera.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 80, "text": "وَأَمَّا ٱلۡغُلَـٰمُ فَكَانَ أَبَوَاهُ مُؤۡمِنَیۡنِ فَخَشِینَاۤ أَن یُرۡهِقَهُمَا طُغۡیَـٰنࣰا وَكُفۡرࣰا ۝٨٠", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "وأما الغلام الذي قتلته فكان في علم الله كافرًا، وكان أبوه وأمه مؤمِنَيْن، فخشينا لو بقي الغلام حيًا لَحمل والديه على الكفر والطغيان؛ لأجل محبتهما إياه أو للحاجة إليه.", "isBasmala": false, "translation_en": "As for the boy, his parents were believers, and we feared he would overwhelm them with oppression and disbelief.", "translation_id": "Dan adapun anak muda itu, maka keduanya adalah orang-orang mukmin, dan kami khawatir bahwa dia akan mendorong kedua orang tuanya itu kepada kesesatan dan kekafiran.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 81, "text": "فَأَرَدۡنَاۤ أَن یُبۡدِلَهُمَا رَبُّهُمَا خَیۡرࣰا مِّنۡهُ زَكَوٰةࣰ وَأَقۡرَبَ رُحۡمࣰا ۝٨١", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "فأردنا أن يُبْدِل الله أبويه بمن هو خير منه صلاحًا ودينًا وبرًا بهما.", "isBasmala": false, "translation_en": "So we wanted their Lord to replace him with someone better in purity, and closer to mercy.", "translation_id": "Dan kami menghendaki, supaya Tuhan mereka mengganti bagi mereka dengan anak lain yang lebih baik kesuciannya dari anaknya itu dan lebih dalam kasih sayangnya (kepada ibu bapaknya).", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 82, "text": "وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَـٰمَیۡنِ یَتِیمَیۡنِ فِی ٱلۡمَدِینَةِ وَكَانَ تَحۡتَهُۥ كَنزࣱ لَّهُمَا وَكَانَ أَبُوهُمَا صَـٰلِحࣰا فَأَرَادَ رَبُّكَ أَن یَبۡلُغَاۤ أَشُدَّهُمَا وَیَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةࣰ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِیۚ ذَ ٰلِكَ تَأۡوِیلُ مَا لَمۡ تَسۡطِع عَّلَیۡهِ صَبۡرࣰا ۝٨٢", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "وأما الحائط الذي عدَّلتُ مَيْلَه حتى استوى فإنه كان لغلامين يتيمين في القرية التي فيها الجدار، وكان تحته كنز لهما من الذهب والفضة، وكان أبوهما رجلا صالحًا، فأراد ربك أن يكبَرا ويبلغا قوتهما، ويستخرجا كنزهما رحمة من ربك بهما، وما فعلتُ يا موسى جميع الذي رأيتَني فعلتُه عن أمري ومن تلقاء نفسي، وإنما فعلته عن أمر الله، ذلك الذي بَيَّنْتُ لك أسبابه هو عاقبة الأمور التي لم تستطع صبرًا على ترك السؤال عنها والإنكار عليَّ فيها.", "isBasmala": false, "translation_en": "And as for the wall, it belonged to two orphaned boys in the town. Beneath it was a treasure that belonged to them. Their father was a righteous man. Your Lord wanted them to reach their maturity, and then extract their treasure-as a mercy from your Lord. I did not do it of my own accord. This is the interpretation of what you were unable to endure.\"", "translation_id": "Adapun dinding rumah adalah kepunyaan dua orang anak yatim di kota itu, dan di bawahnya ada harta benda simpanan bagi mereka berdua, sedang ayahnya adalah seorang yang saleh, maka Tuhanmu menghendaki agar supaya mereka sampai kepada kedewasaannya dan mengeluarkan simpanannya itu, sebagai rahmat dari Tuhanmu; dan bukanlah aku melakukannya itu menurut kemauanku sendiri. Demikian itu adalah tujuan perbuatan-perbuatan yang kamu tidak dapat sabar terhadapnya\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 83, "text": "وَیَسۡـَٔلُونَكَ عَن ذِی ٱلۡقَرۡنَیۡنِۖ قُلۡ سَأَتۡلُوا۟ عَلَیۡكُم مِّنۡهُ ذِكۡرًا ۝٨٣", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "ويسألك -أيها الرسول- هؤلاء المشركون من قومك عن خبر ذي القرنين الملك الصالح، قل لهم: سأقصُّ عليكم منه ذِكْرًا تتذكرونه، وتعتبرون به.", "isBasmala": false, "translation_en": "And they ask you about Zul-Qarnain. Say, \"I will tell you something about him.\"", "translation_id": "Mereka akan bertanya kepadamu (Muhammad) tentang Dzulkarnain. Katakanlah: \"Aku akan bacakan kepadamu cerita tantangnya\".", "manzil": 4, "manzil_display": ""}], "303": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 84, "text": "إِنَّا مَكَّنَّا لَهُۥ فِی ٱلۡأَرۡضِ وَءَاتَیۡنَـٰهُ مِن كُلِّ شَیۡءࣲ سَبَبࣰا ۝٨٤", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "إنا مكَّنَّا له في الأرض، وآتيناه من كل شيء أسبابًا وطرقًا، يتوصل بها إلى ما يريد مِن فَتْح المدائن وقهر الأعداء وغير ذلك.", "isBasmala": false, "translation_en": "We established him on earth, and gave him all kinds of means.", "translation_id": "Sesungguhnya Kami telah memberi kekuasaan kepadanya di (muka) bumi, dan Kami telah memberikan kepadanya jalan (untuk mencapai) segala sesuatu,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 85, "text": "فَأَتۡبَعَ سَبَبًا ۝٨٥", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "فأخذ بتلك الأسباب والطرق بجد واجتهاد.", "isBasmala": false, "translation_en": "He pursued a certain course.", "translation_id": "maka diapun menempuh suatu jalan.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 86, "text": "حَتَّىٰۤ إِذَا بَلَغَ مَغۡرِبَ ٱلشَّمۡسِ وَجَدَهَا تَغۡرُبُ فِی عَیۡنٍ حَمِئَةࣲ وَوَجَدَ عِندَهَا قَوۡمࣰاۖ قُلۡنَا یَـٰذَا ٱلۡقَرۡنَیۡنِ إِمَّاۤ أَن تُعَذِّبَ وَإِمَّاۤ أَن تَتَّخِذَ فِیهِمۡ حُسۡنࣰا ۝٨٦", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "حتى إذا وصل ذو القرنين إلى مغرب الشمس وجدها في مرأى العين كأنها تغرب في عين حارة ذات طين أسود، ووجد عند مغربها قومًا. قلنا: يا ذا القرنين إما أن تعذبهم بالقتل أو غيره، إن لم يقروا بتوحيد الله، وإما أن تحسن إليهم، فتعلمهم الهدى وتبصرهم الرشاد.", "isBasmala": false, "translation_en": "Until, when he reached the setting of the sun, he found it setting in a murky spring, and found a people in its vicinity. We said, \"O Zul-Qarnain, you may either inflict a penalty, or else treat them kindly.\"", "translation_id": "Hingga apabila dia telah sampai ketempat terbenam matahari, dia melihat matahari terbenam di dalam laut yang berlumpur hitam, dan dia mendapati di situ segolongan umat. Kami berkata: \"Hai Dzulkarnain, kamu boleh menyiksa atau boleh berbuat kebaikan terhadap mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 87, "text": "قَالَ أَمَّا مَن ظَلَمَ فَسَوۡفَ نُعَذِّبُهُۥ ثُمَّ یُرَدُّ إِلَىٰ رَبِّهِۦ فَیُعَذِّبُهُۥ عَذَابࣰا نُّكۡرࣰا ۝٨٧", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "قال ذو القرنين: أمَّا مَن ظلم نفسه منهم فكفر بربه، فسوف نعذبه في الدنيا، ثم يرجع إلى ربه، فيعذبه عذابًا عظيمًا في نار جهنم.", "isBasmala": false, "translation_en": "He said, \"As for him who does wrong, we will penalize him, then he will be returned to his Lord, and He will punish him with an unheard-of torment.", "translation_id": "Berkata Dzulkarnain: \"Adapun orang yang aniaya, maka kami kelak akan mengazabnya, kemudian dia kembalikan kepada Tuhannya, lalu Tuhan mengazabnya dengan azab yang tidak ada taranya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 88, "text": "وَأَمَّا مَنۡ ءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَلَهُۥ جَزَاۤءً ٱلۡحُسۡنَىٰۖ وَسَنَقُولُ لَهُۥ مِنۡ أَمۡرِنَا یُسۡرࣰا ۝٨٨", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "وأما مَن آمن منهم بربه فصدَّق به ووحَّده وعمل بطاعته فله الجنة ثوابًا من الله، وسنحسن إليه، ونلين له في القول ونيسِّر له المعاملة.", "isBasmala": false, "translation_en": "\"But as for him who believes and acts righteously, he will have the finest reward, and We will speak to him of Our command with ease.\"", "translation_id": "Adapun orang-orang yang beriman dan beramal saleh, maka baginya pahala yang terbaik sebagai balasan, dan akan kami titahkan kepadanya (perintah) yang mudah dari perintah-perintah kami\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 89, "text": "ثُمَّ أَتۡبَعَ سَبَبًا ۝٨٩", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "ثم رجع ذو القرنين إلى المشرق متبعًا الأسباب التي أعطاه الله إياها.", "isBasmala": false, "translation_en": "Then he pursued a course.", "translation_id": "Kemudian dia menempuh jalan (yang lain).", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 90, "text": "حَتَّىٰۤ إِذَا بَلَغَ مَطۡلِعَ ٱلشَّمۡسِ وَجَدَهَا تَطۡلُعُ عَلَىٰ قَوۡمࣲ لَّمۡ نَجۡعَل لَّهُم مِّن دُونِهَا سِتۡرࣰا ۝٩٠", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "حتى إذا وصل إلى مطلع الشمس وجدها تطلع على قوم ليس لهم بناء يسترهم، ولا شجر يظلهم من الشمس.", "isBasmala": false, "translation_en": "Until, when he reached the rising of the sun, he found it rising on a people for whom We had provided no shelter from it.", "translation_id": "Hingga apabila dia telah sampai ke tempat terbit matahari (sebelah Timur) dia mendapati matahari itu menyinari segolongan umat yang Kami tidak menjadikan bagi mereka sesuatu yang melindunginya dari (cahaya) matahari itu,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 91, "text": "كَذَ ٰلِكَۖ وَقَدۡ أَحَطۡنَا بِمَا لَدَیۡهِ خُبۡرࣰا ۝٩١", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "كذلك وقد أحاط عِلْمُنا بما عنده من الخير والأسباب العظيمة، حيثما توجَّه وسار.", "isBasmala": false, "translation_en": "And so it was. We had full knowledge of what he had.", "translation_id": "demikianlah. dan sesungguhnya ilmu Kami meliputi segala apa yang ada padanya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 92, "text": "ثُمَّ أَتۡبَعَ سَبَبًا ۝٩٢", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "ثم سار ذو القرنين آخذًا بالطرق والأسباب التي منحناها إياه.", "isBasmala": false, "translation_en": "Then he pursued a course.", "translation_id": "Kemudian dia menempuh suatu jalan (yang lain lagi).", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 93, "text": "حَتَّىٰۤ إِذَا بَلَغَ بَیۡنَ ٱلسَّدَّیۡنِ وَجَدَ مِن دُونِهِمَا قَوۡمࣰا لَّا یَكَادُونَ یَفۡقَهُونَ قَوۡلࣰا ۝٩٣", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "حتى إذا وصل إلى ما بين الجبلين الحاجزين لما وراءهما، وجد من دونهما قومًا، لا يكادون يعرفون كلام غيرهم.", "isBasmala": false, "translation_en": "Until, when he reached the point separating the two barriers, he found beside them a people who could barely understand what is said.", "translation_id": "Hingga apabila dia telah sampai di antara dua buah gunung, dia mendapati di hadapan kedua bukit itu suatu kaum yang hampir tidak mengerti pembicaraan.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 94, "text": "قَالُوا۟ یَـٰذَا ٱلۡقَرۡنَیۡنِ إِنَّ یَأۡجُوجَ وَمَأۡجُوجَ مُفۡسِدُونَ فِی ٱلۡأَرۡضِ فَهَلۡ نَجۡعَلُ لَكَ خَرۡجًا عَلَىٰۤ أَن تَجۡعَلَ بَیۡنَنَا وَبَیۡنَهُمۡ سَدࣰّا ۝٩٤", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "قالوا يا ذا القرنين: إنَّ يأجوج ومأجوج -وهما أمَّتان عظيمتان من بني آدم- مفسدون في الأرض بإهلاك الحرث والنسل، فهل نجعل لك أجرًا، ونجمع لك مالا على أن تجعل بيننا وبينهم حاجزًا يحول بيننا وبينهم؟", "isBasmala": false, "translation_en": "They said, \"O Zul-Qarnain, the Gog and Magog are spreading chaos in the land. Can we pay you, to build between us and them a wall?\"", "translation_id": "Mereka berkata: \"Hai Dzulkarnain, sesungguhnya Ya'juj dan Ma'juj itu orang-orang yang membuat kerusakan di muka bumi, maka dapatkah kami memberikan sesuatu pembayaran kepadamu, supaya kamu membuat dinding antara kami dan mereka?\"", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 95, "text": "قَالَ مَا مَكَّنِّی فِیهِ رَبِّی خَیۡرࣱ فَأَعِینُونِی بِقُوَّةٍ أَجۡعَلۡ بَیۡنَكُمۡ وَبَیۡنَهُمۡ رَدۡمًا ۝٩٥", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "قال ذو القرنين: ما أعطانيه ربي من الملك والتمكين خير لي مِن مالكم، فأعينوني بقوة منكم أجعل بينكم وبينهم سدًا.", "isBasmala": false, "translation_en": "He said, \"What my Lord has empowered me with is better. But assist me with strength, and I will build between you and them a dam.\"", "translation_id": "Dzulkarnain berkata: \"Apa yang telah dikuasakan oleh Tuhanku kepadaku terhadapnya adalah lebih baik, maka tolonglah aku dengan kekuatan (manusia dan alat-alat), agar aku membuatkan dinding antara kamu dan mereka,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 96, "text": "ءَاتُونِی زُبَرَ ٱلۡحَدِیدِۖ حَتَّىٰۤ إِذَا سَاوَىٰ بَیۡنَ ٱلصَّدَفَیۡنِ قَالَ ٱنفُخُوا۟ۖ حَتَّىٰۤ إِذَا جَعَلَهُۥ نَارࣰا قَالَ ءَاتُونِیۤ أُفۡرِغۡ عَلَیۡهِ قِطۡرࣰا ۝٩٦", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "أعطوني قطع الحديد، حتى إذا جاؤوا به ووضعوه وحاذوا به جانبي الجبلين، قال للعمال: أجِّجوا النار، حتى إذا صار الحديد كله نارًا، قال: أعطوني نحاسًا أُفرغه عليه.", "isBasmala": false, "translation_en": "\"Bring me blocks of iron.\" So that, when he had leveled up between the two cliffs, he said, \"Blow.\" And having turned it into a fire, he said, \"Bring me tar to pour over it.\"", "translation_id": "berilah aku potongan-potongan besi\". Hingga apabila besi itu telah sama rata dengan kedua (puncak) gunung itu, berkatalah Dzulkarnain: \"Tiuplah (api itu)\". Hingga apabila besi itu sudah menjadi (merah seperti) api, diapun berkata: \"Berilah aku tembaga (yang mendidih) agar aku kutuangkan ke atas besi panas itu\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 97, "text": "فَمَا ٱسۡطَـٰعُوۤا۟ أَن یَظۡهَرُوهُ وَمَا ٱسۡتَطَـٰعُوا۟ لَهُۥ نَقۡبࣰا ۝٩٧", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "فما استطاعت يأجوج ومأجوج أن تصعد فوق السد؛ لارتفاعه وملاسته، وما استطاعوا أن ينقبوه من أسفله لبعد عرضه وقوته.", "isBasmala": false, "translation_en": "So they were unable to climb it, and they could not penetrate it.", "translation_id": "Maka mereka tidak bisa mendakinya dan mereka tidak bisa (pula) melobanginya.", "manzil": 4, "manzil_display": ""}], "304": [{"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 98, "text": "قَالَ هَـٰذَا رَحۡمَةࣱ مِّن رَّبِّیۖ فَإِذَا جَاۤءَ وَعۡدُ رَبِّی جَعَلَهُۥ دَكَّاۤءَۖ وَكَانَ وَعۡدُ رَبِّی حَقࣰّا ۝٩٨", "juz": 16, "hizb": "(* ح 31*)", "tafsir": "قال ذو القرنين: هذا الذي بنيته حاجزًا عن فساد يأجوج ومأجوج رحمة من ربي بالناس، فإذا جاء وعد ربي بخروج يأجوج ومأجوج جعله دكاء منهدمًا مستويًا بالأرض، وكان وعد ربي حقًّا.", "isBasmala": false, "translation_en": "He said, \"This is a mercy from my Lord. But when the promise of my Lord comes true, He will turn it into rubble, and the promise of my Lord is always true.\"", "translation_id": "Dzulkarnain berkata: \"Ini (dinding) adalah rahmat dari Tuhanku, maka apabila sudah datang janji Tuhanku, Dia akan menjadikannya hancur luluh; dan janji Tuhanku itu adalah benar\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 99, "text": "۞ وَتَرَكۡنَا بَعۡضَهُمۡ یَوۡمَىِٕذࣲ یَمُوجُ فِی بَعۡضࣲۖ وَنُفِخَ فِی ٱلصُّورِ فَجَمَعۡنَـٰهُمۡ جَمۡعࣰا ۝٩٩", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "وتركنا يأجوج ومأجوج -يوم يأتيهم وَعْدُنا- يموج بعضهم في بعض مختلطين؛ لكثرتهم، ونفخ في \"القرن\" للبعث، فجمعنا الخلق جميعًا للحساب والجزاء.", "isBasmala": false, "translation_en": "On that Day, We will leave them surging upon one another. And the Trumpet will be blown, and We will gather them together.", "translation_id": "Kami biarkan mereka di hari itu bercampur aduk antara satu dengan yang lain, kemudian ditiup lagi sangkakala, lalu Kami kumpulkan mereka itu semuanya,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 100, "text": "وَعَرَضۡنَا جَهَنَّمَ یَوۡمَىِٕذࣲ لِّلۡكَـٰفِرِینَ عَرۡضًا ۝١٠٠", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "وعرضنا جهنم للكافرين، وأبرزناها لهم لنريهم سوء عاقبتهم.", "isBasmala": false, "translation_en": "On that Day, We will present the disbelievers to Hell, all displayed.", "translation_id": "dan Kami nampakkan Jahannam pada hari itu kepada orang-orang kafir dengan jelas,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 101, "text": "ٱلَّذِینَ كَانَتۡ أَعۡیُنُهُمۡ فِی غِطَاۤءٍ عَن ذِكۡرِی وَكَانُوا۟ لَا یَسۡتَطِیعُونَ سَمۡعًا ۝١٠١", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "الذين كانت أعينهم في الدنيا في غطاء عن ذكري فلا تبصر آياتي، وكانوا لا يطيقون سماع حججي الموصلة إلى الإيمان بي وبرسولي.", "isBasmala": false, "translation_en": "Those whose eyes were screened to My message, and were unable to hear.", "translation_id": "yaitu orang-orang yang matanya dalam keadaan tertutup dari memperhatikan tanda-tanda kebesaran-Ku, dan adalah mereka tidak sanggup mendengar.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 102, "text": "أَفَحَسِبَ ٱلَّذِینَ كَفَرُوۤا۟ أَن یَتَّخِذُوا۟ عِبَادِی مِن دُونِیۤ أَوۡلِیَاۤءَۚ إِنَّاۤ أَعۡتَدۡنَا جَهَنَّمَ لِلۡكَـٰفِرِینَ نُزُلࣰا ۝١٠٢", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "أفظن الذين كفروا بي أن يتخذوا عبادي آلهة من غيري؛ ليكونوا أولياء لهم؟ إنا أعتدنا نار جهنم للكافرين منزلا.", "isBasmala": false, "translation_en": "Do those who disbelieve think that they can take My servants for masters instead of Me? We have prepared Hell for the hospitality of the faithless.", "translation_id": "maka apakah orang-orang kafir menyangka bahwa mereka (dapat) mengambil hamba-hamba-Ku menjadi penolong selain Aku? Sesungguhnya Kami telah menyediakan neraka Jahannam tempat tinggal bagi orang-orang kafir.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 103, "text": "قُلۡ هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِینَ أَعۡمَـٰلًا ۝١٠٣", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قل -أيها الرسول- للناس محذرًا: هل نُخبركم بأخسر الناس أعمالا؟", "isBasmala": false, "translation_en": "Say, \"Shall We inform you of the greatest losers in their works?\"", "translation_id": "Katakanlah: \"Apakah akan Kami beritahukan kepadamu tentang orang-orang yang paling merugi perbuatannya?\"", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 104, "text": "ٱلَّذِینَ ضَلَّ سَعۡیُهُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَهُمۡ یَحۡسَبُونَ أَنَّهُمۡ یُحۡسِنُونَ صُنۡعًا ۝١٠٤", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "إنهم الذين ضلَّ عملهم في الحياة الدنيا -وهم مشركو قومك وغيرهم ممن ضلَّ سواء السبيل، فلم يكن على هدى ولا صواب- وهم يظنون أنهم محسنون في أعمالهم.", "isBasmala": false, "translation_en": "\"Those whose efforts in this world are misguided, while they assume that they are doing well.\"", "translation_id": "Yaitu orang-orang yang telah sia-sia perbuatannya dalam kehidupan dunia ini, sedangkan mereka menyangka bahwa mereka berbuat sebaik-baiknya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 105, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ وَلِقَاۤىِٕهِۦ فَحَبِطَتۡ أَعۡمَـٰلُهُمۡ فَلَا نُقِیمُ لَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ وَزۡنࣰا ۝١٠٥", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "أولئك الأخسرون أعمالا هم الذين جحدوا بآيات ربهم وكذَّبوا بها، وأنكروا لقاءه يوم القيامة، فبطلت أعمالهم؛ بسبب كفرهم، فلا نقيم لهم يوم القيامة قدرًا.", "isBasmala": false, "translation_en": "It is they who rejected the communications of their Lord, and the encounter with Him. So their works are in vain. And on the Day of Resurrection, We will consider them of no weight.", "translation_id": "Mereka itu orang-orang yang telah kufur terhadap ayat-ayat Tuhan mereka dan (kufur terhadap) perjumpaan dengan Dia, maka hapuslah amalan-amalan mereka, dan Kami tidak mengadakan suatu penilaian bagi (amalan) mereka pada hari kiamat.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 106, "text": "ذَ ٰلِكَ جَزَاۤؤُهُمۡ جَهَنَّمُ بِمَا كَفَرُوا۟ وَٱتَّخَذُوۤا۟ ءَایَـٰتِی وَرُسُلِی هُزُوًا ۝١٠٦", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "ذلك المذكور مِن حبوط أعمالهم جزاؤهم نار جهنم؛ بسبب كفرهم بالله واتخاذهم آياته وحجج رسله استهزاءً وسخرية.", "isBasmala": false, "translation_en": "That is their requital-Hell-on account of their disbelief, and their taking My revelations and My messengers in mockery.", "translation_id": "Demikianlah balasan mereka itu neraka Jahannam, disebabkan kekafiran mereka dan disebabkan mereka menjadikan ayat-ayat-Ku dan rasul-rasul-Ku sebagai olok-olok.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 107, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ كَانَتۡ لَهُمۡ جَنَّـٰتُ ٱلۡفِرۡدَوۡسِ نُزُلًا ۝١٠٧", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "إن الذين آمنوا بي، وصدَّقوا رسلي، وعملوا الصالحات، لهم أعلى الجنة وأفضلها منزلا.", "isBasmala": false, "translation_en": "As for those who believe and do righteous deeds, they will have the Gardens of Paradise for hospitality.", "translation_id": "Sesungguhnya orang-orang yang beriman dan beramal saleh, bagi mereka adalah surga Firdaus menjadi tempat tinggal,", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 108, "text": "خَـٰلِدِینَ فِیهَا لَا یَبۡغُونَ عَنۡهَا حِوَلࣰا ۝١٠٨", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "خالدين فيها أبدًا، لا يريدون عنها تحوُّلا؛ لرغبتهم فيها وحبهم لها.", "isBasmala": false, "translation_en": "Abiding therein forever, without desiring any change therefrom.", "translation_id": "mereka kekal di dalamnya, mereka tidak ingin berpindah dari padanya.", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 109, "text": "قُل لَّوۡ كَانَ ٱلۡبَحۡرُ مِدَادࣰا لِّكَلِمَـٰتِ رَبِّی لَنَفِدَ ٱلۡبَحۡرُ قَبۡلَ أَن تَنفَدَ كَلِمَـٰتُ رَبِّی وَلَوۡ جِئۡنَا بِمِثۡلِهِۦ مَدَدࣰا ۝١٠٩", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قل -أيها الرسول-: لو كان ماء البحر حبرًا للأقلام التي يكتب بها كلام الله، لنفِد ماء البحر قبل أن تنفد كلمات الله، ولو جئنا بمثل البحر بحارًا أخرى مددًا له. وفي الآية إثبات صفة الكلام لله -تعالى- حقيقة كما يليق بجلاله وكماله.", "isBasmala": false, "translation_en": "Say, \"If the ocean were ink for the words of my Lord, the ocean would run out, before the words of my Lord run out,\" even if We were to bring the like of it in addition to it.", "translation_id": "Katakanlah: Sekiranya lautan menjadi tinta untuk (menulis) kalimat-kalimat Tuhanku, sungguh habislah lautan itu sebelum habis (ditulis) kalimat-kalimat Tuhanku, meskipun Kami datangkan tambahan sebanyak itu (pula)\".", "manzil": 4, "manzil_display": ""}, {"sura": 18, "sura_name": "الكهف", "revelation": "Makkiyah", "aya": 110, "text": "قُلۡ إِنَّمَاۤ أَنَا۠ بَشَرࣱ مِّثۡلُكُمۡ یُوحَىٰۤ إِلَیَّ أَنَّمَاۤ إِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰحِدࣱۖ فَمَن كَانَ یَرۡجُوا۟ لِقَاۤءَ رَبِّهِۦ فَلۡیَعۡمَلۡ عَمَلࣰا صَـٰلِحࣰا وَلَا یُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦۤ أَحَدَۢا ۝١١٠", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: إنما أنا بشر مثلكم يوحى إليَّ من ربي أنما إلهكم إله واحد، فمَن كان يخاف عذاب ربه ويرجو ثوابه يوم لقائه، فليعمل عملا صالحًا لربه موافقًا لشرعه، ولا يشرك في العبادة معه أحدًا غيره.", "isBasmala": false, "translation_en": "Say, \"I am only a human being like you, being inspired that your god is One God. Whoever hopes to meet his Lord, let him work righteousness, and never associate anyone with the service of his Lord.\"", "translation_id": "Katakanlah: Sesungguhnya aku ini manusia biasa seperti kamu, yang diwahyukan kepadaku: \"Bahwa sesungguhnya Tuhan kamu itu adalah Tuhan yang Esa\". Barangsiapa mengharap perjumpaan dengan Tuhannya, maka hendaklah ia mengerjakan amal yang saleh dan janganlah ia mempersekutukan seorangpun dalam beribadat kepada Tuhannya\".", "manzil": 4, "manzil_display": ""}], "305": [{"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 16, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 1, "text": "كۤهیعۤصۤ ۝١", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "(كهيعص) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Kaf, Ha, Ya, Ayn, Saad.", "translation_id": "Kaaf Haa Yaa 'Ain Shaad.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 2, "text": "ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِیَّاۤ ۝٢", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "هذا ذِكْر رحمة ربك عبده زكريا، سنقصه عليك، فإن في ذلك عبرة للمعتبرين.", "isBasmala": false, "translation_en": "A mention of the mercy of your Lord towards His servant Zechariah.", "translation_id": "(Yang dibacakan ini adalah) penjelasan tentang rahmat Tuhan kamu kepada hamba-Nya, Zakaria,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 3, "text": "إِذۡ نَادَىٰ رَبَّهُۥ نِدَاۤءً خَفِیࣰّا ۝٣", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "إذ دعا ربه سرًا؛ ليكون أكمل وأتم إخلاصًا لله، وأرجى للإجابة.", "isBasmala": false, "translation_en": "When he called on his Lord, a call in seclusion.", "translation_id": "yaitu tatkala ia berdoa kepada Tuhannya dengan suara yang lembut.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 4, "text": "قَالَ رَبِّ إِنِّی وَهَنَ ٱلۡعَظۡمُ مِنِّی وَٱشۡتَعَلَ ٱلرَّأۡسُ شَیۡبࣰا وَلَمۡ أَكُنۢ بِدُعَاۤىِٕكَ رَبِّ شَقِیࣰّا ۝٤", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قال: رب إني كَبِرْتُ، وضعف عظمي، وانتشر الشيب في رأسي، ولم أكن من قبل محرومًا من إجابة الدعاء.", "isBasmala": false, "translation_en": "He said, \"My Lord, my bones have become feeble, and my hair is aflame with gray, and never, Lord, have I been disappointed in my prayer to you.", "translation_id": "Ia berkata \"Ya Tuhanku, sesungguhnya tulangku telah lemah dan kepalaku telah ditumbuhi uban, dan aku belum pernah kecewa dalam berdoa kepada Engkau, ya Tuhanku.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 5, "text": "وَإِنِّی خِفۡتُ ٱلۡمَوَ ٰلِیَ مِن وَرَاۤءِی وَكَانَتِ ٱمۡرَأَتِی عَاقِرࣰا فَهَبۡ لِی مِن لَّدُنكَ وَلِیࣰّا ۝٥", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "وإني خفت أقاربي وعصبتي مِن بعد موتي أن لا يقوموا بدينك حق القيام، ولا يدعوا عبادك إليك، وكانت زوجتي عاقرًا لا تلد، فارزقني مِن عندك ولدًا وارثًا ومعينًا.", "isBasmala": false, "translation_en": "\"And I fear for my dependents after me, and my wife is barren. So grant me, from Yourself, an heir.", "translation_id": "Dan sesungguhnya aku khawatir terhadap mawaliku sepeninggalku, sedang isteriku adalah seorang yang mandul, maka anugerahilah aku dari sisi Engkau seorang putera,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 6, "text": "یَرِثُنِی وَیَرِثُ مِنۡ ءَالِ یَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِیࣰّا ۝٦", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "يرث نبوَّتي ونبوة آل يعقوب، واجعل هذا الولد مرضيًا منك ومن عبادك.", "isBasmala": false, "translation_en": "To inherit me, and inherit from the House of Jacob, and make him, my Lord, pleasing.\"", "translation_id": "yang akan mewarisi aku dan mewarisi sebahagian keluarga Ya'qub; dan jadikanlah ia, ya Tuhanku, seorang yang diridhai\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 7, "text": "یَـٰزَكَرِیَّاۤ إِنَّا نُبَشِّرُكَ بِغُلَـٰمٍ ٱسۡمُهُۥ یَحۡیَىٰ لَمۡ نَجۡعَل لَّهُۥ مِن قَبۡلُ سَمِیࣰّا ۝٧", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "يا زكريا إنَّا نبشرك بإجابة دعائك، قد وهبنا لك غلامًا اسمه يحيى، لم نُسَمِّ أحدًا قبله بهذا الاسم.", "isBasmala": false, "translation_en": "\"O Zechariah, We give you good news of a son, whose name is John, a name We have never given before.\"", "translation_id": "Hai Zakaria, sesungguhnya Kami memberi kabar gembira kepadamu akan (beroleh) seorang anak yang namanya Yahya, yang sebelumnya Kami belum pernah menciptakan orang yang serupa dengan dia.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 8, "text": "قَالَ رَبِّ أَنَّىٰ یَكُونُ لِی غُلَـٰمࣱ وَكَانَتِ ٱمۡرَأَتِی عَاقِرࣰا وَقَدۡ بَلَغۡتُ مِنَ ٱلۡكِبَرِ عِتِیࣰّا ۝٨", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قال زكريا متعجبًا: ربِّ كيف يكون لي غلام، وكانت امرأتي عاقرًا لا تلد، وأنا قد بلغت النهاية في الكبر ورقة العظم؟", "isBasmala": false, "translation_en": "He said, \"My Lord, how can I have a son, when my wife is barren, and I have become decrepit with old age?\"", "translation_id": "Zakaria berkata: \"Ya Tuhanku, bagaimana akan ada anak bagiku, padahal isteriku adalah seorang yang mandul dan aku (sendiri) sesungguhnya sudah mencapai umur yang sangat tua\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 9, "text": "قَالَ كَذَ ٰلِكَ قَالَ رَبُّكَ هُوَ عَلَیَّ هَیِّنࣱ وَقَدۡ خَلَقۡتُكَ مِن قَبۡلُ وَلَمۡ تَكُ شَیۡـࣰٔا ۝٩", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قال المَلَك مجيبًا زكريا عمَّا تعجَّب منه: هكذا الأمر كما تقول مِن كون امرأتك عاقرًا، وبلوغك من الكبر عتيًا، ولكنَّ ربك قال: خَلْقُ يحيى على هذه الكيفية أمر سهل هيِّن عليَّ، ثم ذكر الله سبحانه لزكريا ما هو أعجب مما سأل عنه فقال: وقد خلقتك أنت من قبل يحيى، ولم تكُ شيئًا مذكورًا ولا موجودًا.", "isBasmala": false, "translation_en": "He said, \"It will be so, your Lord says, 'it is easy for me, and I created you before, when you were nothing.'\"", "translation_id": "Tuhan berfirman: \"Demikianlah\". Tuhan berfirman: \"Hal itu adalah mudah bagi-Ku; dan sesunguhnya telah Aku ciptakan kamu sebelum itu, padahal kamu (di waktu itu) belum ada sama sekali\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 10, "text": "قَالَ رَبِّ ٱجۡعَل لِّیۤ ءَایَةࣰۖ قَالَ ءَایَتُكَ أَلَّا تُكَلِّمَ ٱلنَّاسَ ثَلَـٰثَ لَیَالࣲ سَوِیࣰّا ۝١٠", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قال زكريا زيادة في اطمئنانه: ربِّ اجعل لي علامة على تحقُّق ما بَشَّرَتْني به الملائكة، قال: علامتك أن لا تقدر على كلام الناس مدة ثلاث ليال وأيامها، وأنت صحيح معافى.", "isBasmala": false, "translation_en": "He said, \"My Lord, give me a sign.\" He said, \"Your sign is that you will not speak to the people for three nights straight.\"", "translation_id": "Zakaria berkata: \"Ya Tuhanku, berilah aku suatu tanda\". Tuhan berfirman: \"Tanda bagimu ialah bahwa kamu tidak dapat bercakap-cakap dengan manusia selama tiga malam, padahal kamu sehat\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 11, "text": "فَخَرَجَ عَلَىٰ قَوۡمِهِۦ مِنَ ٱلۡمِحۡرَابِ فَأَوۡحَىٰۤ إِلَیۡهِمۡ أَن سَبِّحُوا۟ بُكۡرَةࣰ وَعَشِیࣰّا ۝١١", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "فخرج زكريا على قومه مِن مصلاه، وهو المكان الذي بُشِّر فيه بالولد، فأشار إليهم: أن سَبِّحوا الله صباحًا ومساءً شكرًا له تعالى.", "isBasmala": false, "translation_en": "And he came out to his people, from the sanctuary, and signaled to them to praise morning and evening.", "translation_id": "Maka ia keluar dari mihrab menuju kaumnya, lalu ia memberi isyarat kepada mereka; hendaklah kamu bertasbih di waktu pagi dan petang.", "manzil": 4, "manzil_display": ""}], "306": [{"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 12, "text": "یَـٰیَحۡیَىٰ خُذِ ٱلۡكِتَـٰبَ بِقُوَّةࣲۖ وَءَاتَیۡنَـٰهُ ٱلۡحُكۡمَ صَبِیࣰّا ۝١٢", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "فلما ولد يحيى، وبلغ مبلغًا يفهم فيه الخطاب، أمره اللَّه أن يأخذ التوراة بجدٍّ واجتهاد بقوله: يا يحيى خذ التوراة بجد واجتهاد بحفظ ألفاظها، وفهم معانيها، والعمل بها، وأعطيناه الحكمة وحسن الفهم، وهو صغير السن.", "isBasmala": false, "translation_en": "\"O John, hold on to the Scripture firmly,\" and We gave him wisdom in his youth.", "translation_id": "Hai Yahya, ambillah Al Kitab (Taurat) itu dengan sungguh-sungguh. Dan kami berikan kepadanya hikmah selagi ia masih kanak-kanak,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 13, "text": "وَحَنَانࣰا مِّن لَّدُنَّا وَزَكَوٰةࣰۖ وَكَانَ تَقِیࣰّا ۝١٣", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "وآتيناه رحمة ومحبة من عندنا وطهارة من الذنوب، وكان خائفًا مطيعًا لله تعالى، مؤديًا فرائضه، مجتنبًا محارمه.", "isBasmala": false, "translation_en": "And tenderness from Us, and innocence. He was devout.", "translation_id": "dan rasa belas kasihan yang mendalam dari sisi Kami dan kesucian (dan dosa). Dan ia adalah seorang yang bertakwa,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 14, "text": "وَبَرَّۢا بِوَ ٰلِدَیۡهِ وَلَمۡ یَكُن جَبَّارًا عَصِیࣰّا ۝١٤", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "وكان بارًّا بوالديه مطيعًا لهما، ولم يكن متكبرًا عن طاعة ربه، ولا عن طاعة والديه، ولا عاصيًا لربه، ولا لوالديه.", "isBasmala": false, "translation_en": "And kind to his parents; and he was not a disobedient tyrant.", "translation_id": "dan seorang yang berbakti kepada kedua orang tuanya, dan bukanlah ia orang yang sombong lagi durhaka.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 15, "text": "وَسَلَـٰمٌ عَلَیۡهِ یَوۡمَ وُلِدَ وَیَوۡمَ یَمُوتُ وَیَوۡمَ یُبۡعَثُ حَیࣰّا ۝١٥", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "وسلام من الله على يحيى وأمان له يوم وُلِد، ويوم يموت، ويوم يُبعث مِن قبره حيًا.", "isBasmala": false, "translation_en": "And peace be upon him the day he was born, and the day he dies, and the Day he is raised alive.", "translation_id": "Kesejahteraan atas dirinya pada hari ia dilahirkan dan pada hari ia meninggal dan pada hari ia dibangkitkan hidup kembali.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 16, "text": "وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ مَرۡیَمَ إِذِ ٱنتَبَذَتۡ مِنۡ أَهۡلِهَا مَكَانࣰا شَرۡقِیࣰّا ۝١٦", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "واذكر - أيها الرسول - في هذا القرآن خبر مريم إذ تباعدت عن أهلها، فاتخذت لها مكانًا مما يلي الشرق عنهم.", "isBasmala": false, "translation_en": "And mention in the Scripture Mary, when she withdrew from her people to an eastern location.", "translation_id": "Dan ceritakanlah (kisah) Maryam di dalam Al Quran, yaitu ketika ia menjauhkan diri dari keluarganya ke suatu tempat di sebelah timur,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 17, "text": "فَٱتَّخَذَتۡ مِن دُونِهِمۡ حِجَابࣰا فَأَرۡسَلۡنَاۤ إِلَیۡهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرࣰا سَوِیࣰّا ۝١٧", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "فجعلت مِن دون أهلها سترًا يسترها عنهم وعن الناس، فأرسلنا إليها الملَك جبريل، فتمثَّل لها في صورة إنسان تام الخَلْق.", "isBasmala": false, "translation_en": "She screened herself away from them, and We sent to her Our spirit, and He appeared to her as an immaculate human.", "translation_id": "maka ia mengadakan tabir (yang melindunginya) dari mereka; lalu Kami mengutus roh Kami kepadanya, maka ia menjelma di hadapannya (dalam bentuk) manusia yang sempurna.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 18, "text": "قَالَتۡ إِنِّیۤ أَعُوذُ بِٱلرَّحۡمَـٰنِ مِنكَ إِن كُنتَ تَقِیࣰّا ۝١٨", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قالت مريم له: إني أستجير بالرحمن منك أن تنالني بسوء إن كنت ممن يتقي الله.", "isBasmala": false, "translation_en": "She said, \"I take refuge from you in the Most Merciful, should you be righteous.\"", "translation_id": "Maryam berkata: \"Sesungguhnya aku berlindung dari padamu kepada Tuhan Yang Maha pemurah, jika kamu seorang yang bertakwa\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 19, "text": "قَالَ إِنَّمَاۤ أَنَا۠ رَسُولُ رَبِّكِ لِأَهَبَ لَكِ غُلَـٰمࣰا زَكِیࣰّا ۝١٩", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قال لها المَلَك: إنما أنا رسول ربك بعثني إليك؛ لأهب لك غلامًا طاهرًا من الذنوب.", "isBasmala": false, "translation_en": "He said, \"I am only the messenger of your Lord, to give you the gift of a pure son.\"", "translation_id": "Ia (jibril) berkata: \"Sesungguhnya aku ini hanyalah seorang utusan Tuhanmu, untuk memberimu seorang anak laki-laki yang suci\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 20, "text": "قَالَتۡ أَنَّىٰ یَكُونُ لِی غُلَـٰمࣱ وَلَمۡ یَمۡسَسۡنِی بَشَرࣱ وَلَمۡ أَكُ بَغِیࣰّا ۝٢٠", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قالت مريم للمَلَك: كيف يكون لي غلام، ولم يمسسني بشر بنكاحٍ حلال، ولم أكُ زانية؟", "isBasmala": false, "translation_en": "She said, \"How can I have a son, when no man has touched me, and I was never unchaste?\"", "translation_id": "Maryam berkata: \"Bagaimana akan ada bagiku seorang anak laki-laki, sedang tidak pernah seorang manusiapun menyentuhku dan aku bukan (pula) seorang pezina!\"", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 21, "text": "قَالَ كَذَ ٰلِكِ قَالَ رَبُّكِ هُوَ عَلَیَّ هَیِّنࣱۖ وَلِنَجۡعَلَهُۥۤ ءَایَةࣰ لِّلنَّاسِ وَرَحۡمَةࣰ مِّنَّاۚ وَكَانَ أَمۡرࣰا مَّقۡضِیࣰّا ۝٢١", "juz": 16, "hizb": "(*¼ ح 31*)", "tafsir": "قال لها المَلَك: هكذا الأمر كما تصفين من أنه لم يمسسك بشر، ولم تكوني بَغِيًّا، ولكن ربك قال: الأمر عليَّ سهل؛ وليكون هذا الغلام علامة للناس تدل على قدرة الله تعالى، ورحمة منَّا به وبوالدته وبالناس، وكان وجود عيسى على هذه الحالة قضاء سابقًا مقدَّرًا، مسطورًا في اللوح المحفوظ، فلا بد مِن نفوذه.", "isBasmala": false, "translation_en": "He said, \"Thus said your Lord, `It is easy for Me, and We will make him a sign for humanity, and a mercy from Us. It is a matter already decided.'\"", "translation_id": "Jibril berkata: \"Demikianlah\". Tuhanmu berfirman: \"Hal itu adalah mudah bagi-Ku; dan agar dapat Kami menjadikannya suatu tanda bagi manusia dan sebagai rahmat dari Kami; dan hal itu adalah suatu perkara yang sudah diputuskan\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 22, "text": "۞ فَحَمَلَتۡهُ فَٱنتَبَذَتۡ بِهِۦ مَكَانࣰا قَصِیࣰّا ۝٢٢", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "فحملت مريم بالغلام بعد أن نفخ جبريل في جَيْب قميصها، فوصلت النفخة إلى رَحِمِها، فوقع الحمل بسبب ذلك، فتباعدت به إلى مكان بعيد عن الناس.", "isBasmala": false, "translation_en": "So she carried him, and secluded herself with him in a remote place.", "translation_id": "Maka Maryam mengandungnya, lalu ia menyisihkan diri dengan kandungannya itu ke tempat yang jauh.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 23, "text": "فَأَجَاۤءَهَا ٱلۡمَخَاضُ إِلَىٰ جِذۡعِ ٱلنَّخۡلَةِ قَالَتۡ یَـٰلَیۡتَنِی مِتُّ قَبۡلَ هَـٰذَا وَكُنتُ نَسۡیࣰا مَّنسِیࣰّا ۝٢٣", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "فألجأها طَلْقُ الحمل إلى جذع النخلة فقالت: يا ليتني متُّ قبل هذا اليوم، وكنت شيئًا لا يُعْرَف، ولا يُذْكَر، ولا يُدْرَى مَن أنا؟", "isBasmala": false, "translation_en": "The labor-pains came upon her, by the trunk of a palm-tree. She said, \"I wish I had died before this, and been completely forgotten.\"", "translation_id": "Maka rasa sakit akan melahirkan anak memaksa ia (bersandar) pada pangkal pohon kurma, dia berkata: \"Aduhai, alangkah baiknya aku mati sebelum ini, dan aku menjadi barang yang tidak berarti, lagi dilupakan\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 24, "text": "فَنَادَىٰهَا مِن تَحۡتِهَاۤ أَلَّا تَحۡزَنِی قَدۡ جَعَلَ رَبُّكِ تَحۡتَكِ سَرِیࣰّا ۝٢٤", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "فناداها جبريل أو عيسى: أن لا تَحزني، قد جعل ربك تحتك جَدْول ماء.", "isBasmala": false, "translation_en": "Whereupon he called her from beneath her: \"Do not worry; your Lord has placed a stream beneath you.", "translation_id": "Maka Jibril menyerunya dari tempat yang rendah: \"Janganlah kamu bersedih hati, sesungguhnya Tuhanmu telah menjadikan anak sungai di bawahmu.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 25, "text": "وَهُزِّیۤ إِلَیۡكِ بِجِذۡعِ ٱلنَّخۡلَةِ تُسَـٰقِطۡ عَلَیۡكِ رُطَبࣰا جَنِیࣰّا ۝٢٥", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "وحَرِّكي جذع النخلة تُسَاقِطْ عليك رطبًا غَضًّا جُنِيَ مِن ساعته.", "isBasmala": false, "translation_en": "And shake the trunk of the palm-tree towards you, and it will drop ripe dates by you.\"", "translation_id": "Dan goyanglah pangkal pohon kurma itu ke arahmu, niscaya pohon itu akan menggugurkan buah kurma yang masak kepadamu,", "manzil": 4, "manzil_display": ""}], "307": [{"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 26, "text": "فَكُلِی وَٱشۡرَبِی وَقَرِّی عَیۡنࣰاۖ فَإِمَّا تَرَیِنَّ مِنَ ٱلۡبَشَرِ أَحَدࣰا فَقُولِیۤ إِنِّی نَذَرۡتُ لِلرَّحۡمَـٰنِ صَوۡمࣰا فَلَنۡ أُكَلِّمَ ٱلۡیَوۡمَ إِنسِیࣰّا ۝٢٦", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "فكلي من الرطب، واشربي من الماء وطيـبي نفسًا بالمولود، فإن رأيت من الناس أحدًا فسألك عن أمرك فقولي له: إني أَوْجَبْتُ على نفسي لله سكوتًا، فلن أكلم اليوم أحدًا من الناس. والسكوت كان تعبدًا في شرعهم، دون شريعة محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "\"So eat, and drink, and be consoled. And if you see any human, say, 'I have vowed a fast to the Most Gracious, so I will not speak to any human today.'\"", "translation_id": "maka makan, minum dan bersenang hatilah kamu. Jika kamu melihat seorang manusia, maka katakanlah: \"Sesungguhnya aku telah bernazar berpuasa untuk Tuhan Yang Maha Pemurah, maka aku tidak akan berbicara dengan seorang manusiapun pada hari ini\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 27, "text": "فَأَتَتۡ بِهِۦ قَوۡمَهَا تَحۡمِلُهُۥۖ قَالُوا۟ یَـٰمَرۡیَمُ لَقَدۡ جِئۡتِ شَیۡـࣰٔا فَرِیࣰّا ۝٢٧", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "فأتت مريم قومها تحمل مولودها من المكان البعيد، فلما رأوها كذلك قالوا لها: يا مريم لقد جئت أمرًا عظيمًا مفترى.", "isBasmala": false, "translation_en": "Then she came to her people, carrying him. They said, \"O Mary, you have done something terrible.", "translation_id": "Maka Maryam membawa anak itu kepada kaumnya dengan menggendongnya. Kaumnya berkata: \"Hai Maryam, sesungguhnya kamu telah melakukan sesuatu yang amat mungkar.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 28, "text": "یَـٰۤأُخۡتَ هَـٰرُونَ مَا كَانَ أَبُوكِ ٱمۡرَأَ سَوۡءࣲ وَمَا كَانَتۡ أُمُّكِ بَغِیࣰّا ۝٢٨", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "يا أخت الرجل الصالح هارون ما كان أبوك رجل سوء يأتي الفواحش، وما كانت أمك امرأة سوء تأتي البِغاء.", "isBasmala": false, "translation_en": "O sister of Aaron, your father was not an evil man, and your mother was not a whore.\"", "translation_id": "Hai saudara perempuan Harun, ayahmu sekali-kali bukanlah seorang yang jahat dan ibumu sekali-kali bukanlah seorang pezina\",", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 29, "text": "فَأَشَارَتۡ إِلَیۡهِۖ قَالُوا۟ كَیۡفَ نُكَلِّمُ مَن كَانَ فِی ٱلۡمَهۡدِ صَبِیࣰّا ۝٢٩", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "فأشارت مريم إلى مولودها عيسى ليسألوه ويكلموه، فقالوا منكرين عليها: كيف نكلم مَن لا يزال في مهده طفلا رضيعًا؟", "isBasmala": false, "translation_en": "So she pointed to him. They said, \"How can we speak to an infant in the crib?\"", "translation_id": "maka Maryam menunjuk kepada anaknya. Mereka berkata: \"Bagaimana kami akan berbicara dengan anak kecil yang masih di dalam ayunan?\"", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 30, "text": "قَالَ إِنِّی عَبۡدُ ٱللَّهِ ءَاتَىٰنِیَ ٱلۡكِتَـٰبَ وَجَعَلَنِی نَبِیࣰّا ۝٣٠", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "قال عيسى وهو في مهده يرضع: إني عبد الله، قضى بإعطائي الكتاب، وهو الإنجيل، وجعلني نبيًا.", "isBasmala": false, "translation_en": "He said, \"I am the servant of God. He has given me the Scripture, and made me a prophet.", "translation_id": "Berkata Isa: \"Sesungguhnya aku ini hamba Allah, Dia memberiku Al Kitab (Injil) dan Dia menjadikan aku seorang nabi,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 31, "text": "وَجَعَلَنِی مُبَارَكًا أَیۡنَ مَا كُنتُ وَأَوۡصَـٰنِی بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَیࣰّا ۝٣١", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "وجعلني عظيم الخير والنفع حيثما وُجِدْتُ، وأوصاني بالمحافظة على الصلاة وإيتاء الزكاة ما بقيت حيًا.", "isBasmala": false, "translation_en": "And has made me blessed wherever I may be; and has enjoined on me prayer and charity, so long as I live.", "translation_id": "dan Dia menjadikan aku seorang yang diberkati di mana saja aku berada, dan Dia memerintahkan kepadaku (mendirikan) shalat dan (menunaikan) zakat selama aku hidup;", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 32, "text": "وَبَرَّۢا بِوَ ٰلِدَتِی وَلَمۡ یَجۡعَلۡنِی جَبَّارࣰا شَقِیࣰّا ۝٣٢", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "وجعلني بارًّا بوالدتي، ولم يجعلني متكبرًا ولا شقيًا، عاصيًا لربي.", "isBasmala": false, "translation_en": "And kind to my mother, and He did not make me a disobedient rebel.", "translation_id": "dan berbakti kepada ibuku, dan Dia tidak menjadikan aku seorang yang sombong lagi celaka.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 33, "text": "وَٱلسَّلَـٰمُ عَلَیَّ یَوۡمَ وُلِدتُّ وَیَوۡمَ أَمُوتُ وَیَوۡمَ أُبۡعَثُ حَیࣰّا ۝٣٣", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "والسلامة والأمان عليَّ من الله يوم وُلِدْتُ، ويوم أموت، ويوم أُبعث حيًا يوم القيامة.", "isBasmala": false, "translation_en": "So Peace is upon me the day I was born, and the day I die, and the Day I get resurrected alive.\"", "translation_id": "Dan kesejahteraan semoga dilimpahkan kepadaku, pada hari aku dilahirkan, pada hari aku meninggal dan pada hari aku dibangkitkan hidup kembali\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 34, "text": "ذَ ٰلِكَ عِیسَى ٱبۡنُ مَرۡیَمَۖ قَوۡلَ ٱلۡحَقِّ ٱلَّذِی فِیهِ یَمۡتَرُونَ ۝٣٤", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "ذلك الذي قصصنا عليك - أيها الرسول - صفتَه وخبرَه هو عيسى ابن مريم، مِن غير شك ولا مرية، بل هو قولُ الحق الذي شك فيه اليهود والنصارى.", "isBasmala": false, "translation_en": "That is Jesus son of Mary-the Word of truth about which they doubt.", "translation_id": "Itulah Isa putera Maryam, yang mengatakan perkataan yang benar, yang mereka berbantah-bantahan tentang kebenarannya.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 35, "text": "مَا كَانَ لِلَّهِ أَن یَتَّخِذَ مِن وَلَدࣲۖ سُبۡحَـٰنَهُۥۤۚ إِذَا قَضَىٰۤ أَمۡرࣰا فَإِنَّمَا یَقُولُ لَهُۥ كُن فَیَكُونُ ۝٣٥", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "ما كان لله تعالى ولا يليق به أن يتخذ مِن عباده وخَلْقه ولدًا، تنزَّه وتقدَّس عن ذلك، إذا قضى أمرًا من الأمور وأراده، صغيرًا أو كبيرًا، لم يمتنع عليه، وإنما يقول له: \"كن\"، فيكون كما شاءه وأراده.", "isBasmala": false, "translation_en": "It is not for God to have a child-glory be to Him. To have anything done, He says to it, \"Be,\" and it becomes.", "translation_id": "Tidak layak bagi Allah mempunyai anak, Maha Suci Dia. Apabila Dia telah menetapkan sesuatu, maka Dia hanya berkata kepadanya: \"Jadilah\", maka jadilah ia.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 36, "text": "وَإِنَّ ٱللَّهَ رَبِّی وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَـٰذَا صِرَ ٰطࣱ مُّسۡتَقِیمࣱ ۝٣٦", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "وقال عيسى لقومه: وإن الله الذي أدعوكم إليه هو وحده ربي وربكم فاعبدوه وحده لا شريك له، فأنا وأنتم سواء في العبودية والخضوع له، هذا هو الطريق الذي لا اعوجاج فيه.", "isBasmala": false, "translation_en": "\"God is my Lord and your Lord, so worship Him. That is a straight path.\"", "translation_id": "Sesungguhnya Allah adalah Tuhanku dan Tuhanmu, maka sembahIah Dia oleh kamu sekalian. Ini adalah jalan yang lurus.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 37, "text": "فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَیۡنِهِمۡۖ فَوَیۡلࣱ لِّلَّذِینَ كَفَرُوا۟ مِن مَّشۡهَدِ یَوۡمٍ عَظِیمٍ ۝٣٧", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "فاختلفت الفِرَق من أهل الكتاب فيما بينهم في أمر عيسى عليه السلام، فمنهم غال فيه وهم النصارى، فمنهم من قال: هو الله، ومنهم من قال: هو ابن الله، ومنهم من قال: ثالث ثلاثة - تعالى الله عما يقولون -، ومنهم جافٍ عنه وهم اليهود، قالوا: ساحر، وقالوا: ابن يوسف النجار، فهلاك للذين كفروا مِن شهود يوم عظيم الهول، وهو يوم القيامة.", "isBasmala": false, "translation_en": "But the various factions differed among themselves. So woe to those who disbelieve from the scene of a tremendous Day.", "translation_id": "Maka berselisihlah golongan-golongan (yang ada) di antara mereka. Maka kecelakaanlah bagi orang-orang kafir pada waktu menyaksikan hari yang besar.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 38, "text": "أَسۡمِعۡ بِهِمۡ وَأَبۡصِرۡ یَوۡمَ یَأۡتُونَنَاۖ لَـٰكِنِ ٱلظَّـٰلِمُونَ ٱلۡیَوۡمَ فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٣٨", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "ما أشدَّ سمعَهم وبصرهم يوم القيامة، يوم يَقْدُمون على الله، حين لا ينفعهم ذلك!! لكنِ الظالمون اليوم في هذه الدنيا في ذهابٍ بيِّنٍ عن الحق.", "isBasmala": false, "translation_en": "Listen to them and watch for them the Day they come to Us. But the wrongdoers today are completely lost.", "translation_id": "Alangkah terangnya pendengaran mereka dan alangkah tajamnya penglihatan mereka pada hari mereka datang kepada Kami. Tetapi orang-orang yang zalim pada hari ini (di dunia) berada dalam kesesatan yang nyata.", "manzil": 4, "manzil_display": ""}], "308": [{"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 39, "text": "وَأَنذِرۡهُمۡ یَوۡمَ ٱلۡحَسۡرَةِ إِذۡ قُضِیَ ٱلۡأَمۡرُ وَهُمۡ فِی غَفۡلَةࣲ وَهُمۡ لَا یُؤۡمِنُونَ ۝٣٩", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "وأنذر - أيها الرسول - الناس يوم الندامة حين يُقضى الأمر، ويُجَاءُ بالموت كأنَّه كبش أملح، فيُذْبَح، ويُفصل بين الخلق، فيصير أهل الإيمان إلى الجنة، وأهل الكفر إلى النار، وهم اليوم في هذه الدنيا في غفلة عمَّا أُنذروا به، فهم لا يصدقون، ولا يعملون العمل الصالح.", "isBasmala": false, "translation_en": "And warn them of the Day of Regret, when the matter will be concluded. Yet they are heedless, and they do not believe.", "translation_id": "Dan berilah mereka peringatan tentang hari penyesalan, (yaitu) ketika segala perkara telah diputus. Dan mereka dalam kelalaian dan mereka tidak (pula) beriman.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 40, "text": "إِنَّا نَحۡنُ نَرِثُ ٱلۡأَرۡضَ وَمَنۡ عَلَیۡهَا وَإِلَیۡنَا یُرۡجَعُونَ ۝٤٠", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "إنا نحن الوارثون للأرض ومَن عليها بفنائهم وبقائنا بعدهم وحُكْمنا فيهم، وإلينا مصيرهم وحسابهم، فنجازيهم على أعمالهم.", "isBasmala": false, "translation_en": "It is We who will inherit the earth and everyone on it, and to Us they will be returned.", "translation_id": "Sesungguhnya Kami mewarisi bumi dan semua orang-orang yang ada di atasnya, dan hanya kepada Kamilah mereka dikembalikan.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 41, "text": "وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ إِبۡرَ ٰهِیمَۚ إِنَّهُۥ كَانَ صِدِّیقࣰا نَّبِیًّا ۝٤١", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "واذكر - أيها الرسول - لقومك في هذا القرآن قصة إبراهيم - عليه السلام - إنه كان عظيم الصدق، ومِن أرفع أنبياء الله تعالى منزلة.", "isBasmala": false, "translation_en": "And mention in the Scripture Abraham. He was a man of truth, a prophet.", "translation_id": "Ceritakanlah (Hai Muhammad) kisah Ibrahim di dalam Al Kitab (Al Quran) ini. Sesungguhnya ia adalah seorang yang sangat membenarkan lagi seorang Nabi.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 42, "text": "إِذۡ قَالَ لِأَبِیهِ یَـٰۤأَبَتِ لِمَ تَعۡبُدُ مَا لَا یَسۡمَعُ وَلَا یُبۡصِرُ وَلَا یُغۡنِی عَنكَ شَیۡـࣰٔا ۝٤٢", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "إذ قال لأبيه آزر: يا أبت لأي شيء تعبد من الأصنام ما لا يسمع ولا يبصر، ولا يدفع عنك شيئًا من دون الله؟", "isBasmala": false, "translation_en": "He said to his father, \"O my father, why do you worship what can neither hear, nor see, nor benefit you in any way?", "translation_id": "Ingatlah ketika ia berkata kepada bapaknya; \"Wahai bapakku, mengapa kamu menyembah sesuatu yang tidak mendengar, tidak melihat dan tidak dapat menolong kamu sedikitpun?", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 43, "text": "یَـٰۤأَبَتِ إِنِّی قَدۡ جَاۤءَنِی مِنَ ٱلۡعِلۡمِ مَا لَمۡ یَأۡتِكَ فَٱتَّبِعۡنِیۤ أَهۡدِكَ صِرَ ٰطࣰا سَوِیࣰّا ۝٤٣", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "يا أبت، إن الله أعطاني من العلم ما لم يعطك، فاقبل مني، واتبعني إلى ما أدعوك إليه، أرشدك إلى الطريق السوي الذي لا تضلُّ فيه.", "isBasmala": false, "translation_en": "O my father, there has come to me knowledge that never came to you. So follow me, and I will guide you along a straight way.", "translation_id": "Wahai bapakku, sesungguhnya telah datang kepadaku sebahagian ilmu pengetahuan yang tidak datang kepadamu, maka ikutilah aku, niscaya aku akan menunjukkan kepadamu jalan yang lurus.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 44, "text": "یَـٰۤأَبَتِ لَا تَعۡبُدِ ٱلشَّیۡطَـٰنَۖ إِنَّ ٱلشَّیۡطَـٰنَ كَانَ لِلرَّحۡمَـٰنِ عَصِیࣰّا ۝٤٤", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "يا أبت، لا تطع الشيطان فتعبد هذه الأصنام؛ إن الشيطان كان للرحمن مخالفًا مستكبرًا عن طاعة الله.", "isBasmala": false, "translation_en": "O my father, do not worship the devil. The devil is disobedient to the Most Gracious.", "translation_id": "Wahai bapakku, janganlah kamu menyembah syaitan. Sesungguhnya syaitan itu durhaka kepada Tuhan Yang Maha Pemurah.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 45, "text": "یَـٰۤأَبَتِ إِنِّیۤ أَخَافُ أَن یَمَسَّكَ عَذَابࣱ مِّنَ ٱلرَّحۡمَـٰنِ فَتَكُونَ لِلشَّیۡطَـٰنِ وَلِیࣰّا ۝٤٥", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "يا أبت، إني أخاف أن تموت على كفرك، فيمَسَّك عذاب من الرحمن، فتكون للشيطان قرينًا في النار.", "isBasmala": false, "translation_en": "O my father, I fear that a punishment from the Most Gracious will afflict you, and you become an ally of the devil.\"", "translation_id": "Wahai bapakku, sesungguhnya aku khawatir bahwa kamu akan ditimpa azab dari Tuhan Yang Maha Pemurah, maka kamu menjadi kawan bagi syaitan\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 46, "text": "قَالَ أَرَاغِبٌ أَنتَ عَنۡ ءَالِهَتِی یَـٰۤإِبۡرَ ٰهِیمُۖ لَىِٕن لَّمۡ تَنتَهِ لَأَرۡجُمَنَّكَۖ وَٱهۡجُرۡنِی مَلِیࣰّا ۝٤٦", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "قال أبو إبراهيم لابنه: أمعرض أنت عن عبادة آلهتي يا إبراهيم؟ لئن لم تنته عن سَبِّها لأقتلنَّك رميًا بالحجارة، واذهب عني فلا تلقني، ولا تكلمني زمانًا طويلا من الدهر.", "isBasmala": false, "translation_en": "He said, \"Are you renouncing my gods, O Abraham? If you do not desist, I will stone you. So leave me alone for a while.\"", "translation_id": "Berkata bapaknya: \"Bencikah kamu kepada tuhan-tuhanku, hai Ibrahim? Jika kamu tidak berhenti, maka niscaya kamu akan kurajam, dan tinggalkanlah aku buat waktu yang lama\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 47, "text": "قَالَ سَلَـٰمٌ عَلَیۡكَۖ سَأَسۡتَغۡفِرُ لَكَ رَبِّیۤۖ إِنَّهُۥ كَانَ بِی حَفِیࣰّا ۝٤٧", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "قال إبراهيم لأبيه: سلام عليك مني فلا ينالك مني ما تكره، وسوف أدعو الله لك بالهداية والمغفرة. إن ربي كان رحيمًا رؤوفًا بحالي يجيبني إذا دعوته.", "isBasmala": false, "translation_en": "He said, \"Peace be upon you. I will ask my Lord to forgive you; He has been Kind to me.", "translation_id": "Berkata Ibrahim: \"Semoga keselamatan dilimpahkan kepadamu, aku akan memintakan ampun bagimu kepada Tuhanku. Sesungguhnya Dia sangat baik kepadaku.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 48, "text": "وَأَعۡتَزِلُكُمۡ وَمَا تَدۡعُونَ مِن دُونِ ٱللَّهِ وَأَدۡعُوا۟ رَبِّی عَسَىٰۤ أَلَّاۤ أَكُونَ بِدُعَاۤءِ رَبِّی شَقِیࣰّا ۝٤٨", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "وأفارقكم وآلهتكم التي تعبدونها من دون الله، وأدعو ربي مخلصًا، عسى أن لا أشقى بدعاء ربي، فلا يعطيني ما أسأله.", "isBasmala": false, "translation_en": "And I will withdraw from you, and from what you pray to instead of God. And I will pray to my Lord, and I hope I will not be disappointed in my prayer to my Lord.\"", "translation_id": "Dan aku akan menjauhkan diri darimu dan dari apa yang kamu seru selain Allah, dan aku akan berdoa kepada Tuhanku, mudah-mudahan aku tidak akan kecewa dengan berdoa kepada Tuhanku\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 49, "text": "فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا یَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥۤ إِسۡحَـٰقَ وَیَعۡقُوبَۖ وَكُلࣰّا جَعَلۡنَا نَبِیࣰّا ۝٤٩", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "فلما فارقهم وآلهتهم التي يعبدونها من دون الله رزقناه من الولد: إسحاق، ويعقوب بن إسحاق، وجعلناهما نبيَّين.", "isBasmala": false, "translation_en": "When he withdrew from them, and from what they worship besides God, We granted him Isaac and Jacob. And each We made a prophet.", "translation_id": "Maka ketika Ibrahim sudah menjauhkan diri dari mereka dan dari apa yang mereka sembah selain Allah, Kami anugerahkan kepadanya Ishak, dan Ya'qub. Dan masing-masingnya Kami angkat menjadi nabi.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 50, "text": "وَوَهَبۡنَا لَهُم مِّن رَّحۡمَتِنَا وَجَعَلۡنَا لَهُمۡ لِسَانَ صِدۡقٍ عَلِیࣰّا ۝٥٠", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "ووهبنا لهم جميعا من رحمتنا فضلا لا يحصى، وجعلنا لهم ذكرًا حسنًا، وثناءً جميلا باقيًا في الناس.", "isBasmala": false, "translation_en": "And We gave them freely of Our mercy, and gave them a noble reputation of truth.", "translation_id": "Dan Kami anugerahkan kepada mereka sebagian dari rahmat Kami dan Kami jadikan mereka buah tutur yang baik lagi tinggi.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 51, "text": "وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ مُوسَىٰۤۚ إِنَّهُۥ كَانَ مُخۡلَصࣰا وَكَانَ رَسُولࣰا نَّبِیࣰّا ۝٥١", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "واذكر - أيها الرسول - في القرآن قصة موسى - عليه السلام - إنه كان مصطفى مختارًا، وكان رسولا نبيًا مِن أولي العزم من الرسل.", "isBasmala": false, "translation_en": "And mention in the Scripture Moses. He was dedicated. He was a messenger and a prophet.", "translation_id": "Dan ceritakanlah (hai Muhammad kepada mereka), kisah Musa di dalam Al Kitab (Al Quran) ini. Sesungguhnya ia adalah seorang yang dipilih dan seorang rasul dan nabi.", "manzil": 4, "manzil_display": ""}], "309": [{"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 52, "text": "وَنَـٰدَیۡنَـٰهُ مِن جَانِبِ ٱلطُّورِ ٱلۡأَیۡمَنِ وَقَرَّبۡنَـٰهُ نَجِیࣰّا ۝٥٢", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "ونادينا موسى من ناحية جبل طور \"سيناء\" اليمنى من موسى، وقرَّبناه فشرَّفناه بمناجاتنا له. وفي هذا إثبات صفة الكلام لله - تعالى - كما يليق بجلاله وكماله.", "isBasmala": false, "translation_en": "And We called him from the right side of the Mount, and brought him near in communion.", "translation_id": "Dan Kami telah memanggilnya dari sebelah kanan gunung Thur dan Kami telah mendekatkannya kepada Kami di waktu dia munajat (kepada Kami).", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 53, "text": "وَوَهَبۡنَا لَهُۥ مِن رَّحۡمَتِنَاۤ أَخَاهُ هَـٰرُونَ نَبِیࣰّا ۝٥٣", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "ووهبنا لموسى من رحمتنا أخاه هارون نبيًا يؤيده ويؤازره.", "isBasmala": false, "translation_en": "And We granted him, out of Our mercy, his brother Aaron, a prophet.", "translation_id": "Dan Kami telah menganugerahkan kepadanya sebagian rahmat Kami, yaitu saudaranya, Harun menjadi seorang nabi.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 54, "text": "وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ إِسۡمَـٰعِیلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولࣰا نَّبِیࣰّا ۝٥٤", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "واذكر - أيها الرسول - في هذا القرآن خبر إسماعيل عليه السلام، إنه كان صادقًا في وعده فلم يَعِد شيئًا إلا وفَّى به، وكان رسولا نبيًا.", "isBasmala": false, "translation_en": "And mention in the Scripture Ishmael. He was true to his promise, and was a messenger, a prophet.", "translation_id": "Dan ceritakanlah (hai Muhammad kepada mereka) kisah Ismail (yang tersebut) di dalam Al Quran. Sesungguhnya ia adalah seorang yang benar janjinya, dan dia adalah seorang rasul dan nabi.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 55, "text": "وَكَانَ یَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِیࣰّا ۝٥٥", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "وكان يأمر أهله بإقام الصلاة وإيتاء الزكاة، وكان عند ربه عز وجل مرضيًا عنه.", "isBasmala": false, "translation_en": "And he used to enjoin on his people prayer and charity, and he was pleasing to his Lord.", "translation_id": "Dan ia menyuruh ahlinya untuk bersembahyang dan menunaikan zakat, dan ia adalah seorang yang diridhai di sisi Tuhannya.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 56, "text": "وَٱذۡكُرۡ فِی ٱلۡكِتَـٰبِ إِدۡرِیسَۚ إِنَّهُۥ كَانَ صِدِّیقࣰا نَّبِیࣰّا ۝٥٦", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "واذكر - أيها الرسول - في هذا القرآن خبر إدريس عليه السلام، إنه كان عظيم الصدق في قوله وعمله، نبيًا يوحى إليه.", "isBasmala": false, "translation_en": "And mention in the Scripture Enoch. He was a man of truth, a prophet.", "translation_id": "Dan ceritakanlah (hai Muhammad kepada mereka, kisah) Idris (yang tersebut) di dalam Al Quran. Sesungguhnya ia adalah seorang yang sangat membenarkan dan seorang nabi.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 57, "text": "وَرَفَعۡنَـٰهُ مَكَانًا عَلِیًّا ۝٥٧", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "ورفَعْنا ذِكْره في العالمين، ومنزلته بين المقربين، فكان عالي الذكر، عالي المنزلة.", "isBasmala": false, "translation_en": "And We raised him to a high position.", "translation_id": "Dan Kami telah mengangkatnya ke martabat yang tinggi.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 58, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ أَنۡعَمَ ٱللَّهُ عَلَیۡهِم مِّنَ ٱلنَّبِیِّـۧنَ مِن ذُرِّیَّةِ ءَادَمَ وَمِمَّنۡ حَمَلۡنَا مَعَ نُوحࣲ وَمِن ذُرِّیَّةِ إِبۡرَ ٰهِیمَ وَإِسۡرَ ٰۤءِیلَ وَمِمَّنۡ هَدَیۡنَا وَٱجۡتَبَیۡنَاۤۚ إِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُ ٱلرَّحۡمَـٰنِ خَ̅رُّ̅و̅ا۟̅ ̅سُ̅جَّ̅دࣰ̅ا̅ وَبُكِیࣰّا ۝٥٨ ۩", "juz": 16, "hizb": "(*½ ح 31*)", "tafsir": "هؤلاء الذين قصصتُ عليك خبرهم أيها الرسول، هم الذين أنعم الله عليهم بفضله وتوفيقه، فجعلهم أنبياء من ذرية آدم، ومِن ذرية مَن حملنا مع نوح في السفينة، ومن ذرية إبراهيم، ومن ذرية يعقوب، وممَّن هدينا للإيمان واصطفينا للرسالة والنبُوَّة، إذا تتلى عليهم آيات الرحمن المتضمنة لتوحيده وحججه خرُّوا ساجدين لله خضوعًا، واستكانة، وبكَوْا من خشيته سبحانه وتعالى.", "isBasmala": false, "translation_en": "These are some of the prophets God has blessed, from the descendants of Adam, and from those We carried with Noah, and from the descendants of Abraham and Israel, and from those We guided and selected. Whenever the revelations of the Most Gracious are recited to them, they would fall down, prostrating and weeping.", "translation_id": "Mereka itu adalah orang-orang yang telah diberi nikmat oleh Allah, yaitu para nabi dari keturunan Adam, dan dari orang-orang yang Kami angkat bersama Nuh, dan dari keturunan Ibrahim dan Israil, dan dari orang-orang yang telah Kami beri petunjuk dan telah Kami pilih. Apabila dibacakan ayat-ayat Allah Yang Maha Pemurah kepada mereka, maka mereka menyungkur dengan bersujud dan menangis.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 59, "text": "۞ فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٌ أَضَاعُوا۟ ٱلصَّلَوٰةَ وَٱتَّبَعُوا۟ ٱلشَّهَوَ ٰتِۖ فَسَوۡفَ یَلۡقَوۡنَ غَیًّا ۝٥٩", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "فأتى مِن بعد هؤلاء المنعَم عليهم أتباع سَوْء تركوا الصلاة كلها، أو فوتوا وقتها، أو تركوا أركانها وواجباتها، واتبعوا ما يوافق شهواتهم ويلائمها، فسوف يلقون شرًا وضلالا وخيبة في جهنم.", "isBasmala": false, "translation_en": "But they were succeeded by generations who lost the prayers and followed their appetites. They will meet perdition.", "translation_id": "Maka datanglah sesudah mereka, pengganti (yang jelek) yang menyia-nyiakan shalat dan memperturutkan hawa nafsunya, maka mereka kelak akan menemui kesesatan,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 60, "text": "إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَأُو۟لَـٰۤىِٕكَ یَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا یُظۡلَمُونَ شَیۡـࣰٔا ۝٦٠", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "لكن مَن تاب منهم مِن ذنبه وآمن بربه وعمل صالحًا تصديقًا لتوبته، فأولئك يقبل الله توبتهم، ويدخلون الجنة مع المؤمنين ولا يُنقَصون شيئًا من أعمالهم الصالحة.", "isBasmala": false, "translation_en": "Except for those who repent, and believe, and act righteously. These will enter Paradise, and will not be wronged in the least.", "translation_id": "kecuali orang yang bertaubat, beriman dan beramal saleh, maka mereka itu akan masuk surga dan tidak dianiaya (dirugikan) sedikitpun,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 61, "text": "جَنَّـٰتِ عَدۡنٍ ٱلَّتِی وَعَدَ ٱلرَّحۡمَـٰنُ عِبَادَهُۥ بِٱلۡغَیۡبِۚ إِنَّهُۥ كَانَ وَعۡدُهُۥ مَأۡتِیࣰّا ۝٦١", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "جنات خلد وإقامة دائمة، وهي التي وعد الرحمن بها عباده بالغيب فآمَنوا بها ولم يروها، إن وعد الله لعباده بهذه الجنة آتٍ لا محالة.", "isBasmala": false, "translation_en": "The Gardens of Eden, promised by the Most Merciful to His servants in the Unseen. His promise will certainly come true.", "translation_id": "yaitu surga 'Adn yang telah dijanjikan oleh Tuhan Yang Maha Pemurah kepada hamba-hamba-Nya, sekalipun (surga itu) tidak nampak. Sesungguhnya janji Allah itu pasti akan ditepati.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 62, "text": "لَّا یَسۡمَعُونَ فِیهَا لَغۡوًا إِلَّا سَلَـٰمࣰاۖ وَلَهُمۡ رِزۡقُهُمۡ فِیهَا بُكۡرَةࣰ وَعَشِیࣰّا ۝٦٢", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "لا يسمع أهل الجنة فيها كلامًا باطلا لكن يسمعون سلاما تحية لهم، ولهم رزقهم فيها من الطعام والشراب دائمًا، كلما شاؤوا بكرة وعشيًا.", "isBasmala": false, "translation_en": "They will hear no nonsense therein, but only peace. And they will have their provision therein, morning and evening.", "translation_id": "Mereka tidak mendengar perkataan yang tak berguna di dalam surga, kecuali ucapan salam. Bagi mereka rezekinya di surga itu tiap-tiap pagi dan petang.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 63, "text": "تِلۡكَ ٱلۡجَنَّةُ ٱلَّتِی نُورِثُ مِنۡ عِبَادِنَا مَن كَانَ تَقِیࣰّا ۝٦٣", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "تلك الجنة الموصوفة بتلك الصفات، هي التي نورثها ونعطيها عبادنا المتقين لنا، بامتثال أوامرنا واجتناب نواهينا.", "isBasmala": false, "translation_en": "Such is Paradise which We will give as inheritance to those of Our servants who are devout.", "translation_id": "Itulah surga yang akan Kami wariskan kepada hamba-hamba Kami yang selalu bertakwa.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 64, "text": "وَمَا نَتَنَزَّلُ إِلَّا بِأَمۡرِ رَبِّكَۖ لَهُۥ مَا بَیۡنَ أَیۡدِینَا وَمَا خَلۡفَنَا وَمَا بَیۡنَ ذَ ٰلِكَۚ وَمَا كَانَ رَبُّكَ نَسِیࣰّا ۝٦٤", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "وقل - يا جبريل - لمحمد: وما نتنزل - نحن الملائكة - من السماء إلى الأرض إلا بأمر ربك لنا، له ما بين أيدينا مما يستقبل من أمر الآخرة، وما خلفنا مما مضى من الدنيا، وما بين الدنيا والآخرة، فله الأمر كله في الزمان والمكان، وما كان ربك ناسيًا لشيء من الأشياء.", "isBasmala": false, "translation_en": "\"We do not descend except by the command of your Lord. His is what is before us, and what is behind us, and what is between them. Your Lord is never forgetful.\"", "translation_id": "Dan tidaklah kami (Jibril) turun, kecuali dengan perintah Tuhanmu. Kepunyaan-Nya-lah apa-apa yang ada di hadapan kita, apa-apa yang ada di belakang kita dan apa-apa yang ada di antara keduanya, dan tidaklah Tuhanmu lupa.", "manzil": 4, "manzil_display": ""}], "310": [{"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 65, "text": "رَّبُّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا فَٱعۡبُدۡهُ وَٱصۡطَبِرۡ لِعِبَـٰدَتِهِۦۚ هَلۡ تَعۡلَمُ لَهُۥ سَمِیࣰّا ۝٦٥", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "فهو الله رب السموات والأرض وما بينهما، ومالك ذلك كله وخالقه ومدبره، فاعبده وحده - أيها النبي - واصبر على طاعته أنت ومَن تبعك، ليس كمثله شيء في ذاته وأسمائه وصفاته وأفعاله.", "isBasmala": false, "translation_en": "Lord of the heavens and the earth and what is between them. So worship Him, and persevere in His service. Do you know of anyone equal to Him?", "translation_id": "Tuhan (yang menguasai) langit dan bumi dan apa-apa yang ada di antara keduanya, maka sembahlah Dia dan berteguh hatilah dalam beribadat kepada-Nya. Apakah kamu mengetahui ada seorang yang sama dengan Dia (yang patut disembah)?", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 66, "text": "وَیَقُولُ ٱلۡإِنسَـٰنُ أَءِذَا مَا مِتُّ لَسَوۡفَ أُخۡرَجُ حَیًّا ۝٦٦", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ويقول الإنسان الكافر منكرًا للبعث بعد الموت: أإذا ما مِتُّ وفَنِيتُ لسوف أُخرَج من قبري حيًا؟!", "isBasmala": false, "translation_en": "And the human being says, \"When I am dead, will I be brought back alive?\"", "translation_id": "Dan berkata manusia: \"Betulkah apabila aku telah mati, bahwa aku sungguh-sungguh akan dibangkitkan menjadi hidup kembali?\"", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 67, "text": "أَوَ لَا یَذۡكُرُ ٱلۡإِنسَـٰنُ أَنَّا خَلَقۡنَـٰهُ مِن قَبۡلُ وَلَمۡ یَكُ شَیۡـࣰٔا ۝٦٧", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "كيف نسي هذا الإنسان الكافر نفسه؟ أولا يَذْكُر أنا خلقناه أول مرة، ولم يكُ شيئًا موجودًا؟", "isBasmala": false, "translation_en": "Does the human being not remember that We created him before, when he was nothing?", "translation_id": "Dan tidakkah manusia itu memikirkan bahwa sesungguhnya Kami telah menciptakannya dahulu, sedang ia tidak ada sama sekali?", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 68, "text": "فَوَرَبِّكَ لَنَحۡشُرَنَّهُمۡ وَٱلشَّیَـٰطِینَ ثُمَّ لَنُحۡضِرَنَّهُمۡ حَوۡلَ جَهَنَّمَ جِثِیࣰّا ۝٦٨", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "فوربك - أيها الرسول - لنجمعن هؤلاء المنكرين للبعث يوم القيامة مع الشياطين، ثم لنأتين بهم أجمعين حول جهنم باركين على رُكَبهم؛ لشدة ما هم فيه من الهول، لا يقدرون على القيام.", "isBasmala": false, "translation_en": "By your Lord, We will round them up, and the devils, then We will bring them around Hell, on their knees.", "translation_id": "Demi Tuhanmu, sesungguhnya akan Kami bangkitkan mereka bersama syaitan, kemudian akan Kami datangkan mereka ke sekeliling Jahannam dengan berlutut.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 69, "text": "ثُمَّ لَنَنزِعَنَّ مِن كُلِّ شِیعَةٍ أَیُّهُمۡ أَشَدُّ عَلَى ٱلرَّحۡمَـٰنِ عِتِیࣰّا ۝٦٩", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ثم لنأخذنَّ مِن كل طائفة أشدَّهم تمردًا وعصيانًا لله، فنبدأ بعذابهم.", "isBasmala": false, "translation_en": "Then, out of every sect, We will snatch those most defiant to the Most Merciful.", "translation_id": "Kemudian pasti akan Kami tarik dari tiap-tiap golongan siapa di antara mereka yang sangat durhaka kepada Tuhan Yang Maha Pemurah.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 70, "text": "ثُمَّ لَنَحۡنُ أَعۡلَمُ بِٱلَّذِینَ هُمۡ أَوۡلَىٰ بِهَا صِلِیࣰّا ۝٧٠", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ثم لنحن أعلم بالذين هم أَوْلى بدخول النار ومقاساة حرها.", "isBasmala": false, "translation_en": "We are fully aware of those most deserving to scorch in it.", "translation_id": "Dan kemudian Kami sungguh lebih mengetahui orang-orang yang seharusnya dimasukkan ke dalam neraka.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 71, "text": "وَإِن مِّنكُمۡ إِلَّا وَارِدُهَاۚ كَانَ عَلَىٰ رَبِّكَ حَتۡمࣰا مَّقۡضِیࣰّا ۝٧١", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "وما منكم - أيها الناس - أحد إلا وارد النار بالمرور على الصراط المنصوب على متن جهنم، كل بحسب عمله، كان ذلك أمرًا محتومًا، قضى الله - سبحانه - وحكم أنه لا بد من وقوعه لا محالة.", "isBasmala": false, "translation_en": "There is not one of you but will go down to it. This has been an unavoidable decree of your Lord.", "translation_id": "Dan tidak ada seorangpun dari padamu, melainkan mendatangi neraka itu. Hal itu bagi Tuhanmu adalah suatu kemestian yang sudah ditetapkan.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 72, "text": "ثُمَّ نُنَجِّی ٱلَّذِینَ ٱتَّقَوا۟ وَّنَذَرُ ٱلظَّـٰلِمِینَ فِیهَا جِثِیࣰّا ۝٧٢", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ثم ننجي الذين اتقوا ربهم بطاعته والبعد عن معصيته، ونترك الظالمين لأنفسهم بالكفر بالله في النار باركين على رُكَبهم.", "isBasmala": false, "translation_en": "Then We will rescue those who were devout, and leave the wrongdoers in it, on their knees.", "translation_id": "Kemudian Kami akan menyelamatkan orang-orang yang bertakwa dan membiarkan orang-orang yang zalim di dalam neraka dalam keadaan berlutut.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 73, "text": "وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ قَالَ ٱلَّذِینَ كَفَرُوا۟ لِلَّذِینَ ءَامَنُوۤا۟ أَیُّ ٱلۡفَرِیقَیۡنِ خَیۡرࣱ مَّقَامࣰا وَأَحۡسَنُ نَدِیࣰّا ۝٧٣", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "وإذا تتلى على الناس آياتنا المنزلات الواضحات قال الكفار بالله للمؤمنين به: أيُّ الفريقين منَّا ومنكم أفضل منزلا وأحسن مجلسًا؟", "isBasmala": false, "translation_en": "When Our clear revelations are recited to them, those who disbelieve say to those who believe, \"Which of the two parties is better in position, and superior in influence?\"", "translation_id": "Dan apabila dibacakan kepada mereka ayat-ayat Kami yang terang (maksudnya), niscaya orang-orang yang kafir berkata kepada orang-orang yang beriman: \"Manakah di antara kedua golongan (kafir dan mukmin) yang lebih baik tempat tinggalnya dan lebih indah tempat pertemuan(nya)?\"", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 74, "text": "وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَحۡسَنُ أَثَـٰثࣰا وَرِءۡیࣰا ۝٧٤", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "وكثيرًا أهلكنا قبل كفار قومك - أيها الرسول - من الأمم كانوا أحسن متاعًا منهم وأجمل منظرًا.", "isBasmala": false, "translation_en": "How many a generation have We destroyed before them, who surpassed them in riches and splendor?", "translation_id": "Berapa banyak umat yang telah Kami binasakan sebelum mereka, sedang mereka adalah lebih bagus alat rumah tangganya dan lebih sedap di pandang mata.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 75, "text": "قُلۡ مَن كَانَ فِی ٱلضَّلَـٰلَةِ فَلۡیَمۡدُدۡ لَهُ ٱلرَّحۡمَـٰنُ مَدًّاۚ حَتَّىٰۤ إِذَا رَأَوۡا۟ مَا یُوعَدُونَ إِمَّا ٱلۡعَذَابَ وَإِمَّا ٱلسَّاعَةَ فَسَیَعۡلَمُونَ مَنۡ هُوَ شَرࣱّ مَّكَانࣰا وَأَضۡعَفُ جُندࣰا ۝٧٥", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "قل - أيها الرسول - لهم: من كان ضالا عن الحق غير متبع طريق الهدى، فالله يمهله ويملي له في ضلاله، حتى إذا رأى - يقينا - ما توعَّده الله به: إما العذاب العاجل في الدنيا، وإما قيام الساعة، فسيعلم - حينئذ - مَن هو شر مكانًا ومستقرًا، وأضعف قوة وجندًا.", "isBasmala": false, "translation_en": "Say, \"Whoever is in error, the Most Merciful will lead him on.\" Until, when they see what they were promised-either the punishment, or the Hour. Then they will know who was in worse position and weaker in forces.", "translation_id": "Katakanlah: \"Barang siapa yang berada di dalam kesesatan, maka biarlah Tuhan yang Maha Pemurah memperpanjang tempo baginya; sehingga apabila mereka telah melihat apa yang diancamkan kepadanya, baik siksa maupun kiamat, maka mereka akan mengetahui siapa yang lebih jelek kedudukannya dan lebih lemah penolong-penolongnya\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 76, "text": "وَیَزِیدُ ٱللَّهُ ٱلَّذِینَ ٱهۡتَدَوۡا۟ هُدࣰىۗ وَٱلۡبَـٰقِیَـٰتُ ٱلصَّـٰلِحَـٰتُ خَیۡرٌ عِندَ رَبِّكَ ثَوَابࣰا وَخَیۡرࣱ مَّرَدًّا ۝٧٦", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ويزيد الله عباده الذين اهتدوا لدينه هدى على هداهم بما يتجدد لهم من الإيمان بفرائض الله، والعمل بها. والأعمالُ الباقيات الصالحات خير ثوابًا عند الله في الآخرة، وخير مرجعًا وعاقبة.", "isBasmala": false, "translation_en": "God increases in guidance those who accept guidance. And the things that endure-the righteous deeds-have the best reward with your Lord, and the best outcome.", "translation_id": "Dan Allah akan menambah petunjuk kepada mereka yang telah mendapat petunjuk. Dan amal-amal saleh yang kekal itu lebih baik pahalanya di sisi Tuhanmu dan lebih baik kesudahannya.", "manzil": 4, "manzil_display": ""}], "311": [{"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 77, "text": "أَفَرَءَیۡتَ ٱلَّذِی كَفَرَ بِـَٔایَـٰتِنَا وَقَالَ لَأُوتَیَنَّ مَالࣰا وَوَلَدًا ۝٧٧", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "أعَلِمْت - أيها الرسول - وعجبت من هذا الكافر \"العاص بن وائل\" وأمثاله؟ إذ كفر بآيات الله وكذَّب بها وقال: لأعطينَّ في الآخرة أموالا وأولادًا.", "isBasmala": false, "translation_en": "Have you seen him who denied Our revelations, and said, \"I will be given wealth and children\"?", "translation_id": "Maka apakah kamu telah melihat orang yang kafir kepada ayat-ayat Kami dan ia mengatakan: \"Pasti aku akan diberi harta dan anak\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 78, "text": "أَطَّلَعَ ٱلۡغَیۡبَ أَمِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَـٰنِ عَهۡدࣰا ۝٧٨", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "أطَّلَع الغيب، فرأى أن له مالا وولدًا، أم له عند الله عهد بذلك؟", "isBasmala": false, "translation_en": "Did he look into the future, or did he receive a promise from the Most Merciful?", "translation_id": "Adakah ia melihat yang ghaib atau ia telah membuat perjanjian di sisi Tuhan Yang Maha Pemurah?,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 79, "text": "كَلَّاۚ سَنَكۡتُبُ مَا یَقُولُ وَنَمُدُّ لَهُۥ مِنَ ٱلۡعَذَابِ مَدࣰّا ۝٧٩", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ليس الأمر كما يزعم ذلك الكافر، فلا علم له ولا عهد عنده، سنكتب ما يقول مِن كذب وافتراء على الله، ونزيده في الآخرة من أنواع العقوبات، كما ازداد من الغيِّ والضلال.", "isBasmala": false, "translation_en": "No indeed! We will write what he says, and will keep extending the agony for him.", "translation_id": "sekali-kali tidak, Kami akan menulis apa yang ia katakan, dan benar-benar Kami akan memperpanjang azab untuknya,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 80, "text": "وَنَرِثُهُۥ مَا یَقُولُ وَیَأۡتِینَا فَرۡدࣰا ۝٨٠", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ونرثه مالَه وولده، ويأتينا يوم القيامة فردًا وحده، لا مال معه ولا ولد.", "isBasmala": false, "translation_en": "Then We will inherit from him what he speaks of, and he will come to Us alone.", "translation_id": "dan Kami akan mewarisi apa yang ia katakan itu, dan ia akan datang kepada Kami dengan seorang diri.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 81, "text": "وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةࣰ لِّیَكُونُوا۟ لَهُمۡ عِزࣰّا ۝٨١", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "واتخذ المشركون آلهة يعبدونها من دون الله؛ لتنصرهم، ويعتزوا بها.", "isBasmala": false, "translation_en": "And they took, besides God, other gods, to be for them a source of strength.", "translation_id": "Dan mereka telah mengambil sembahan-sembahan selain Allah, agar sembahan-sembahan itu menjadi pelindung bagi mereka,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 82, "text": "كَلَّاۚ سَیَكۡفُرُونَ بِعِبَادَتِهِمۡ وَیَكُونُونَ عَلَیۡهِمۡ ضِدًّا ۝٨٢", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ليس الأمر كما يزعمون، لن تكون لهم الآلهة عزًا، بل ستكفر هذه الآلهة في الآخرة بعبادتهم لها، وتكون عليهم أعوانًا في خصومتهم وتكذيبهم بخلاف ما ظنوه فيها.", "isBasmala": false, "translation_en": "By no means! They will reject their worship of them, and become opponents to them.", "translation_id": "sekali-kali tidak. Kelak mereka (sembahan-sembahan) itu akan mengingkari penyembahan (pengikut-pengikutnya) terhadapnya, dan mereka (sembahan-sembahan) itu akan menjadi musuh bagi mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 83, "text": "أَلَمۡ تَرَ أَنَّاۤ أَرۡسَلۡنَا ٱلشَّیَـٰطِینَ عَلَى ٱلۡكَـٰفِرِینَ تَؤُزُّهُمۡ أَزࣰّا ۝٨٣", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ألم تر - أيها الرسول - أنَّا سلَّطْنا الشياطين على الكافرين بالله ورسله؛ لتغويهم، وتدفعهم عن الطاعة إلى المعصية؟", "isBasmala": false, "translation_en": "Have you not considered how We dispatch the devils against the disbelievers, exciting them with incitement?", "translation_id": "Tidakkah kamu lihat, bahwasanya Kami telah mengirim syaitan-syaitan itu kepada orang-orang kafir untuk menghasung mereka berbuat maksiat dengan sungguh-sungguh?,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 84, "text": "فَلَا تَعۡجَلۡ عَلَیۡهِمۡۖ إِنَّمَا نَعُدُّ لَهُمۡ عَدࣰّا ۝٨٤", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "فلا تستعجل - أيها الرسول - بطلب العذاب على هؤلاء الكافرين، إنما نحصي أعمارهم وأعمالهم إحصاءً لا تفريط فيه ولا تأخير.", "isBasmala": false, "translation_en": "So do not hurry against them. We are counting for them a countdown.", "translation_id": "maka janganlah kamu tergesa-gesa memintakan siksa terhadap mereka, karena sesungguhnya Kami hanya menghitung datangnya (hari siksaan) untuk mereka dengan perhitungan yang teliti.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 85, "text": "یَوۡمَ نَحۡشُرُ ٱلۡمُتَّقِینَ إِلَى ٱلرَّحۡمَـٰنِ وَفۡدࣰا ۝٨٥", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "يوم نجمع المتقين إلى ربهم الرحيم بهم وفودًا مكرمين. ونسوق الكافرين بالله سوقًا شديدًا إلى النار مشاة عِطاشًا.", "isBasmala": false, "translation_en": "On the Day when We will gather the righteous to the Most Merciful, as guests.", "translation_id": "(Ingatlah) hari (ketika) Kami mengumpulkan orang-orang yang takwa kepada Tuhan Yang Maha Pemurah sebagai perutusan yang terhormat,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 86, "text": "وَنَسُوقُ ٱلۡمُجۡرِمِینَ إِلَىٰ جَهَنَّمَ وِرۡدࣰا ۝٨٦", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "يوم نجمع المتقين إلى ربهم الرحيم بهم وفودًا مكرمين. ونسوق الكافرين بالله سوقًا شديدًا إلى النار مشاة عِطاشًا.", "isBasmala": false, "translation_en": "And herd the sinners into hell, like animals to water.", "translation_id": "dan Kami akan menghalau orang-orang yang durhaka ke neraka Jahannam dalam keadaan dahaga.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 87, "text": "لَّا یَمۡلِكُونَ ٱلشَّفَـٰعَةَ إِلَّا مَنِ ٱتَّخَذَ عِندَ ٱلرَّحۡمَـٰنِ عَهۡدࣰا ۝٨٧", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "لا يملك هؤلاء الكفار الشفاعة لأحد، إنما يملكها مَنِ اتخذ عند الرحمن عهدًا بذلك، وهم المؤمنون بالله ورسله.", "isBasmala": false, "translation_en": "They will have no power of intercession, except for someone who has an agreement with the Most Merciful.", "translation_id": "Mereka tidak berhak mendapat syafa'at kecuali orang yang telah mengadakan perjanjian di sisi Tuhan Yang Maha Pemurah.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 88, "text": "وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحۡمَـٰنُ وَلَدࣰا ۝٨٨", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "وقال هؤلاء الكفار: اتخذ الرحمن ولدًا.", "isBasmala": false, "translation_en": "And they say, \"The Most Merciful has begotten a son.\"", "translation_id": "Dan mereka berkata: \"Tuhan Yang Maha Pemurah mengambil (mempunyai) anak\".", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 89, "text": "لَّقَدۡ جِئۡتُمۡ شَیۡـًٔا إِدࣰّا ۝٨٩", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "لقد جئتم - أيها القائلون - بهذه المقالة شيئا عظيمًا منكرًا.", "isBasmala": false, "translation_en": "You have come up with something monstrous.", "translation_id": "Sesungguhnya kamu telah mendatangkan sesuatu perkara yang sangat mungkar,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 90, "text": "تَكَادُ ٱلسَّمَـٰوَ ٰتُ یَتَفَطَّرۡنَ مِنۡهُ وَتَنشَقُّ ٱلۡأَرۡضُ وَتَخِرُّ ٱلۡجِبَالُ هَدًّا ۝٩٠", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "تكاد السموات يتشقَّقْنَ مِن فظاعة ذلكم القول، وتتصدع الأرض، وتسقط الجبال سقوطًا شديدًا غضبًا لله لِنِسْبَتِهم له الولد. تعالى الله عن ذلك علوًا كبيرًا.", "isBasmala": false, "translation_en": "At which the heavens almost rupture, and the earth splits, and the mountains fall and crumble.", "translation_id": "hampir-hampir langit pecah karena ucapan itu, dan bumi belah, dan gunung-gunung runtuh,", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 91, "text": "أَن دَعَوۡا۟ لِلرَّحۡمَـٰنِ وَلَدࣰا ۝٩١", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "تكاد السموات يتشقَّقْنَ مِن فظاعة ذلكم القول، وتتصدع الأرض، وتسقط الجبال سقوطًا شديدًا غضبًا لله لِنِسْبَتِهم له الولد. تعالى الله عن ذلك علوًا كبيرًا.", "isBasmala": false, "translation_en": "Because they attribute a son to the Most Merciful.", "translation_id": "karena mereka mendakwakan Allah Yang Maha Pemurah mempunyai anak.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 92, "text": "وَمَا یَنۢبَغِی لِلرَّحۡمَـٰنِ أَن یَتَّخِذَ وَلَدًا ۝٩٢", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "وما يصلح للرحمن، ولا يليق بعظمته، أن يتخذ ولدًا؛ لأن اتخاذ الولد يدل على النقص والحاجة، والله هو الغني الحميد المبرأ عن كل النقائص.", "isBasmala": false, "translation_en": "It is not fitting for the Most Merciful to have a son.", "translation_id": "Dan tidak layak bagi Tuhan Yang Maha Pemurah mengambil (mempunyai) anak.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 93, "text": "إِن كُلُّ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ إِلَّاۤ ءَاتِی ٱلرَّحۡمَـٰنِ عَبۡدࣰا ۝٩٣", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "ما كل مَن في السموات من الملائكة، ومَن في الأرض من الإنس والجن، إلا سيأتي ربه يوم القيامة عبدًا ذليلا خاضعًا مقرًا له بالعبودية.", "isBasmala": false, "translation_en": "There is none in the heavens and the earth but will come to the Most Merciful as a servant.", "translation_id": "Tidak ada seorangpun di langit dan di bumi, kecuali akan datang kepada Tuhan Yang Maha Pemurah selaku seorang hamba.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 94, "text": "لَّقَدۡ أَحۡصَىٰهُمۡ وَعَدَّهُمۡ عَدࣰّا ۝٩٤", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "لقد أحصى الله سبحانه وتعالى خَلْقَه كلهم، وعلم عددهم، فلا يخفى عليه أحد منهم.", "isBasmala": false, "translation_en": "He has enumerated them, and counted them one by one.", "translation_id": "Sesungguhnya Allah telah menentukan jumlah mereka dan menghitung mereka dengan hitungan yang teliti.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 95, "text": "وَكُلُّهُمۡ ءَاتِیهِ یَوۡمَ ٱلۡقِیَـٰمَةِ فَرۡدًا ۝٩٥", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "وسوف يأتي كل فرد من الخلق ربه يوم القيامة وحده، لا مال له ولا ولد معه.", "isBasmala": false, "translation_en": "And each one of them will come to Him on the Day of Resurrection alone.", "translation_id": "Dan tiap-tiap mereka akan datang kepada Allah pada hari kiamat dengan sendiri-sendiri.", "manzil": 4, "manzil_display": ""}], "312": [{"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 96, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَیَجۡعَلُ لَهُمُ ٱلرَّحۡمَـٰنُ وُدࣰّا ۝٩٦", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "إن الذين آمنوا بالله واتَّبَعوا رسله وعملوا الصالحات وَفْق شرعه، سيجعل لهم الرحمن محبة ومودة في قلوب عباده.", "isBasmala": false, "translation_en": "Those who believe and do righteous deeds, the Most Merciful will give them love.", "translation_id": "Sesungguhnya orang-orang yang beriman dan beramal saleh, kelak Allah Yang Maha Pemurah akan menanamkan dalam (hati) mereka rasa kasih sayang.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 97, "text": "فَإِنَّمَا یَسَّرۡنَـٰهُ بِلِسَانِكَ لِتُبَشِّرَ بِهِ ٱلۡمُتَّقِینَ وَتُنذِرَ بِهِۦ قَوۡمࣰا لُّدࣰّا ۝٩٧", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "فإنما يسَّرنا هذا القرآن بلسانك العربي أيها الرسول؛ لتبشر به المتقين من أتباعك، وتخوِّف به المكذبين شديدي الخصومة بالباطل.", "isBasmala": false, "translation_en": "We made it easy in your tongue, in order to deliver good news to the righteous, and to warn with it a hostile people.", "translation_id": "Maka sesungguhnya telah Kami mudahkan Al Quran itu dengan bahasamu, agar kamu dapat memberi kabar gembira dengan Al Quran itu kepada orang-orang yang bertakwa, dan agar kamu memberi peringatan dengannya kepada kaum yang membangkang.", "manzil": 4, "manzil_display": ""}, {"sura": 19, "sura_name": "مريم", "revelation": "Makkiyah", "aya": 98, "text": "وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هَلۡ تُحِسُّ مِنۡهُم مِّنۡ أَحَدٍ أَوۡ تَسۡمَعُ لَهُمۡ رِكۡزَۢا ۝٩٨", "juz": 16, "hizb": "(*¾ ح 31*)", "tafsir": "وكثيرًا أهلكنا - أيها الرسول - من الأمم السابقة قبل قومك، ما ترى منهم أحدًا وما تسمع لهم صوتًا، فكذلك الكفار من قومك، نهلكهم كما أهلكنا السابقين من قبلهم. وفي هذا تهديد ووعيد بإهلاك المكذبين المعاندين.", "isBasmala": false, "translation_en": "How many a generation have We destroyed before them? Can you feel a single one of them, or hear from them the slightest whisper?", "translation_id": "Dan berapa banyak telah Kami binasakan umat-umat sebelum mereka. Adakah kamu melihat seorangpun dari mereka atau kamu dengar suara mereka yang samar-samar?", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 16, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 1, "text": "۞ طه ۝١", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "(طه) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ta, Ha.", "translation_id": "Thaahaa.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 2, "text": "مَاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰۤ ۝٢", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "ما أنزلنا عليك - أيها الرسول - القرآن؛ لتشقى بما لا طاقة لك به من العمل.", "isBasmala": false, "translation_en": "We did not reveal the Quran to you to make you suffer.", "translation_id": "Kami tidak menurunkan Al Quran ini kepadamu agar kamu menjadi susah;", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 3, "text": "إِلَّا تَذۡكِرَةࣰ لِّمَن یَخۡشَىٰ ۝٣", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "لكن أنزلناه موعظة؛ ليتذكر به مَن يخاف عقاب الله، فيتقيه بأداء الفرائض واجتناب المحارم.", "isBasmala": false, "translation_en": "But only as a reminder for him who fears.", "translation_id": "tetapi sebagai peringatan bagi orang yang takut (kepada Allah),", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 4, "text": "تَنزِیلࣰا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَـٰوَ ٰتِ ٱلۡعُلَى ۝٤", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "هذا القرآن تنزيل من الله الذي خلق الأرض والسموات العلى.", "isBasmala": false, "translation_en": "A revelation from He who created the earth and the high heavens.", "translation_id": "yaitu diturunkan dari Allah yang menciptakan bumi dan langit yang tinggi.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 5, "text": "ٱلرَّحۡمَـٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ ۝٥", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "الرحمن على العرش استوى أي ارتفع وعلا استواء يليق بجلاله وعظمته.", "isBasmala": false, "translation_en": "The Most Merciful; on the Throne He settled.", "translation_id": "(Yaitu) Tuhan Yang Maha Pemurah. Yang bersemayam di atas 'Arsy.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 6, "text": "لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ ۝٦", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "له ما في السموات وما في الأرض وما بينهما وما تحت الأرض، خَلْقًا ومُلْكًا وتدبيرًا.", "isBasmala": false, "translation_en": "To Him belongs everything in the heavens and the earth, and everything between them, and everything beneath the soil.", "translation_id": "Kepunyaan-Nya-lah semua yang ada di langit, semua yang di bumi, semua yang di antara keduanya dan semua yang di bawah tanah.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 7, "text": "وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ یَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى ۝٧", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "وإن تجهر - أيها الرسول - بالقول، فتعلنه أو تخفه، فإن الله لا يخفى عليه شيء، يعلم السر وما هو أخفى من السر مما تحدِّث به نفسك.", "isBasmala": false, "translation_en": "If you speak aloud-He knows the secret, and the most hidden.", "translation_id": "Dan jika kamu mengeraskan ucapanmu, maka sesungguhnya Dia mengetahui rahasia dan yang lebih tersembunyi.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 8, "text": "ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَاۤءُ ٱلۡحُسۡنَىٰ ۝٨", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "الله الذي لا معبود بحق إلا هو، له وحده الأسماء الكاملة في الحسن.", "isBasmala": false, "translation_en": "God, there is no god but He, His are the Most Beautiful Names.", "translation_id": "Dialah Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia. Dia mempunyai al asmaaul husna (nama-nama yang baik),", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 9, "text": "وَهَلۡ أَتَىٰكَ حَدِیثُ مُوسَىٰۤ ۝٩", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "وهل أتاك - أيها الرسول - خبر موسى بن عمران عليه السلام؟", "isBasmala": false, "translation_en": "Has the story of Moses reached you?", "translation_id": "Apakah telah sampai kepadamu kisah Musa?", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 10, "text": "إِذۡ رَءَا نَارࣰا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوۤا۟ إِنِّیۤ ءَانَسۡتُ نَارࣰا لَّعَلِّیۤ ءَاتِیكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدࣰى ۝١٠", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "حين رأى في الليل نارًا موقدة فقال لأهله: انتظروا لقد أبصرت نارًا، لعلي أجيئكم منها بشعلة تستدفئون بها، وتوقدون بها نارًا أخرى، أو أجد عندها هاديًا يدلنا على الطريق.", "isBasmala": false, "translation_en": "When he saw a fire, he said to his family, \"Stay; I have noticed a fire; Perhaps I can bring you a torch therefrom, or find some guidance by the fire.\"", "translation_id": "Ketika ia melihat api, lalu berkatalah ia kepada keluarganya: \"Tinggallah kamu (di sini), sesungguhnya aku melihat api, mudah-mudahan aku dapat membawa sedikit daripadanya kepadamu atau aku akan mendapat petunjuk di tempat api itu\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 11, "text": "فَلَمَّاۤ أَتَىٰهَا نُودِیَ یَـٰمُوسَىٰۤ ۝١١", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "فلما أتى موسى تلك النار ناداه الله: يا موسى، إني أنا ربك فاخلع نعليك، إنك الآن بوادي \"طوى\" الذي باركته، وذلك استعدادًا لمناجاة ربه.", "isBasmala": false, "translation_en": "Then, when he reached it, he was called, \"O Moses.", "translation_id": "Maka ketika ia datang ke tempat api itu ia dipanggil: \"Hai Musa.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 12, "text": "إِنِّیۤ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَیۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوࣰى ۝١٢", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "فلما أتى موسى تلك النار ناداه الله: يا موسى، إني أنا ربك فاخلع نعليك، إنك الآن بوادي \"طوى\" الذي باركته، وذلك استعدادًا لمناجاة ربه.", "isBasmala": false, "translation_en": "I-I am your Lord. Take off your shoes. You are in the sacred valley of Tuwa.", "translation_id": "Sesungguhnya Aku inilah Tuhanmu, maka tanggalkanlah kedua terompahmu; sesungguhnya kamu berada dilembah yang suci, Thuwa.", "manzil": 4, "manzil_display": ""}], "313": [{"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 13, "text": "وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا یُوحَىٰۤ ۝١٣", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "وإني اخترتك يا موسى لرسالتي، فاستمع لما يوحى إليك مني.", "isBasmala": false, "translation_en": "I have chosen you, so listen to what is revealed.", "translation_id": "Dan Aku telah memilih kamu, maka dengarkanlah apa yang akan diwahyukan (kepadamu).", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 14, "text": "إِنَّنِیۤ أَنَا ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّاۤ أَنَا۠ فَٱعۡبُدۡنِی وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِیۤ ۝١٤", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "إنني أنا الله لا معبود بحق إلا أنا، لا شريك لي، فاعبدني وحدي، وأقم الصلاة لتذكرني فيها.", "isBasmala": false, "translation_en": "I-I am God. There is no God but I. So serve Me, and practice the prayer for My remembrance.", "translation_id": "Sesungguhnya Aku ini adalah Allah, tidak ada Tuhan (yang hak) selain Aku, maka sembahlah Aku dan dirikanlah shalat untuk mengingat Aku.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 15, "text": "إِنَّ ٱلسَّاعَةَ ءَاتِیَةٌ أَكَادُ أُخۡفِیهَا لِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا تَسۡعَىٰ ۝١٥", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "إن الساعة التي يُبعث فيها الناس آتية لا بد من وقوعها، أكاد أخفيها من نفسي، فكيف يعلمها أحد من المخلوقين؛ لكي تُجزى كل نفس بما عملت في الدنيا من خير أو شر.", "isBasmala": false, "translation_en": "The Hour is coming-but I keep it almost hidden-so that each soul will be paid for what it endeavors.", "translation_id": "Segungguhnya hari kiamat itu akan datang Aku merahasiakan (waktunya) agar supaya tiap-tiap diri itu dibalas dengan apa yang ia usahakan.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 16, "text": "فَلَا یَصُدَّنَّكَ عَنۡهَا مَن لَّا یُؤۡمِنُ بِهَا وَٱتَّبَعَ هَوَىٰهُ فَتَرۡدَىٰ ۝١٦", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "فلا يصرفنَّك - يا موسى - عن الإيمان بها والاستعداد لها مَن لا يصدق بوقوعها ولا يعمل لها، واتبع هوى نفسه، فكذَّب بها، فتهلك.", "isBasmala": false, "translation_en": "And do not let him who denies it and follows his desire turn you away from it, lest you fall.", "translation_id": "Maka sekali-kali janganlah kamu dipalingkan daripadanya oleh orang yang tidak beriman kepadanya dan oleh orang yang mengikuti hawa nafsunya, yang menyebabkan kamu jadi binasa\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 17, "text": "وَمَا تِلۡكَ بِیَمِینِكَ یَـٰمُوسَىٰ ۝١٧", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "وما هذه التي في يمينك يا موسى؟", "isBasmala": false, "translation_en": "And what is that in your right-hand, O Moses?\"", "translation_id": "Apakah itu yang di tangan kananmu, hai Musa?", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 18, "text": "قَالَ هِیَ عَصَایَ أَتَوَكَّؤُا۟ عَلَیۡهَا وَأَهُشُّ بِهَا عَلَىٰ غَنَمِی وَلِیَ فِیهَا مَـَٔارِبُ أُخۡرَىٰ ۝١٨", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: هي عصاي أعتمد عليها في المشي، وأهزُّ بها الشجر؛ لترعى غنمي ما يتساقط من ورقه، ولي فيها منافع أخرى.", "isBasmala": false, "translation_en": "He said, \"This is my staff. I lean on it, and herd my sheep with it, and I have other uses for it.\"", "translation_id": "Berkata Musa: \"Ini adalah tongkatku, aku bertelekan padanya, dan aku pukul (daun) dengannya untuk kambingku, dan bagiku ada lagi keperluan yang lain padanya\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 19, "text": "قَالَ أَلۡقِهَا یَـٰمُوسَىٰ ۝١٩", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال الله لموسى: ألق عصاك.", "isBasmala": false, "translation_en": "He said, \"Throw it, O Moses.\"", "translation_id": "Allah berfirman: \"Lemparkanlah ia, hai Musa!\"", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 20, "text": "فَأَلۡقَىٰهَا فَإِذَا هِیَ حَیَّةࣱ تَسۡعَىٰ ۝٢٠", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "فألقاها موسى على الأرض، فانقلبت بإذن الله حية تسعى، فرأى موسى أمرًا عظيمًا وولى هاربًا.", "isBasmala": false, "translation_en": "So he threw it-thereupon it became a moving serpent.", "translation_id": "Lalu dilemparkannyalah tongkat itu, maka tiba-tiba ia menjadi seekor ular yang merayap dengan cepat.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 21, "text": "قَالَ خُذۡهَا وَلَا تَخَفۡۖ سَنُعِیدُهَا سِیرَتَهَا ٱلۡأُولَىٰ ۝٢١", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال الله لموسى: خذ الحية، ولا تَخَفْ منها، سوف نعيدها عصًا كما كانت في حالتها الأولى. واضمم يدك إلى جنبك تحت العَضُد تخرج بيضاء كالثلج من غير برص؛ لتكون لك علامة أخرى.", "isBasmala": false, "translation_en": "He said, \"Take hold of it, and do not fear. We will restore it to its original condition.", "translation_id": "Allah berfirman: \"Peganglah ia dan jangan takut, Kami akan mengembalikannya kepada keadaannya semula,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 22, "text": "وَٱضۡمُمۡ یَدَكَ إِلَىٰ جَنَاحِكَ تَخۡرُجۡ بَیۡضَاۤءَ مِنۡ غَیۡرِ سُوۤءٍ ءَایَةً أُخۡرَىٰ ۝٢٢", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال الله لموسى: خذ الحية، ولا تَخَفْ منها، سوف نعيدها عصًا كما كانت في حالتها الأولى. واضمم يدك إلى جنبك تحت العَضُد تخرج بيضاء كالثلج من غير برص؛ لتكون لك علامة أخرى.", "isBasmala": false, "translation_en": "And press your hand to your side; it will come out white, without a blemish-another sign.", "translation_id": "dan kepitkanlah tanganmu ke ketiakmu, niscaya ia ke luar menjadi putih cemerlang tanpa cacad, sebagai mukjizat yang lain (pula),", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 23, "text": "لِنُرِیَكَ مِنۡ ءَایَـٰتِنَا ٱلۡكُبۡرَى ۝٢٣", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "فعلنا ذلك؛ لكي نريك - يا موسى - من أدلتنا الكبرى ما يدلُّ على قدرتنا، وعظيم سلطاننا، وصحة رسالتك.", "isBasmala": false, "translation_en": "That We may show you some of Our greatest signs.", "translation_id": "untuk Kami perlihatkan kepadamu sebahagian dari tanda-tanda kekuasaan Kami yang sangat besar,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 24, "text": "ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ۝٢٤", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "اذهب - يا موسى - إلى فرعون؛ إنه قد تجاوز قدره وتمرَّد على ربه، فادعه إلى توحيد الله وعبادته.", "isBasmala": false, "translation_en": "Go to Pharaoh; He has transgressed.\"", "translation_id": "Pergilah kepada Fir'aun; sesungguhnya ia telah melampaui batas\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 25, "text": "قَالَ رَبِّ ٱشۡرَحۡ لِی صَدۡرِی ۝٢٥", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "He said, \"My Lord, put my heart at peace for me.", "translation_id": "Berkata Musa: \"Ya Tuhanku, lapangkanlah untukku dadaku,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 26, "text": "وَیَسِّرۡ لِیۤ أَمۡرِی ۝٢٦", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "And ease my task for me.", "translation_id": "dan mudahkanlah untukku urusanku,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 27, "text": "وَٱحۡلُلۡ عُقۡدَةࣰ مِّن لِّسَانِی ۝٢٧", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "And untie the knot from my tongue.", "translation_id": "dan lepaskanlah kekakuan dari lidahku,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 28, "text": "یَفۡقَهُوا۟ قَوۡلِی ۝٢٨", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "So they can understand my speech.", "translation_id": "supaya mereka mengerti perkataanku,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 29, "text": "وَٱجۡعَل لِّی وَزِیرࣰا مِّنۡ أَهۡلِی ۝٢٩", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "And appoint an assistant for me, from my family.", "translation_id": "dan jadikanlah untukku seorang pembantu dari keluargaku,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 30, "text": "هَـٰرُونَ أَخِی ۝٣٠", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "Aaron, my brother.", "translation_id": "(yaitu) Harun, saudaraku,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 31, "text": "ٱشۡدُدۡ بِهِۦۤ أَزۡرِی ۝٣١", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "Strengthen me with him.", "translation_id": "teguhkanlah dengan dia kekuatanku,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 32, "text": "وَأَشۡرِكۡهُ فِیۤ أَمۡرِی ۝٣٢", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "And have him share in my mission.", "translation_id": "dan jadikankanlah dia sekutu dalam urusanku,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 33, "text": "كَیۡ نُسَبِّحَكَ كَثِیرࣰا ۝٣٣", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "That we may glorify You much.", "translation_id": "supaya kami banyak bertasbih kepada Engkau,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 34, "text": "وَنَذۡكُرَكَ كَثِیرًا ۝٣٤", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "And remember You much.", "translation_id": "dan banyak mengingat Engkau.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 35, "text": "إِنَّكَ كُنتَ بِنَا بَصِیرࣰا ۝٣٥", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى: رب وسِّع لي صدري، وسَهِّل لي أمري، وأطلق لساني بفصيح المنطق؛ ليفهموا كلامي. واجعل لي معينا من أهلي، هارون أخي. قَوِّني به وشدَّ به ظهري، وأشركه معي في النبوة وتبليغ الرسالة؛ كي ننزهك بالتسبيح كثيرًا، ونذكرك كثيرا فنحمدك. إنك كنت بنا بصيرًا، لا يخفى عليك شيء من أفعالنا.", "isBasmala": false, "translation_en": "You are always watching over us.\"", "translation_id": "Sesungguhnya Engkau adalah Maha Melihat (keadaan) kami\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 36, "text": "قَالَ قَدۡ أُوتِیتَ سُؤۡلَكَ یَـٰمُوسَىٰ ۝٣٦", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال الله: قد أعطيتك كل ما سألت يا موسى.", "isBasmala": false, "translation_en": "He said, \"You are granted your request, O Moses.", "translation_id": "Allah berfirman: \"Sesungguhnya telah diperkenankan permintaanmu, hai Musa\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 37, "text": "وَلَقَدۡ مَنَنَّا عَلَیۡكَ مَرَّةً أُخۡرَىٰۤ ۝٣٧", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "ولقد أنعمنا عليك - يا موسى - قبل هذه النعمة نعمة أخرى، حين كنت رضيعًا، فأنجيناك مِن بطش فرعون.", "isBasmala": false, "translation_en": "We had favored you another time.", "translation_id": "Dan sesungguhnya Kami telah memberi nikmat kepadamu pada kali yang lain,", "manzil": 4, "manzil_display": ""}], "314": [{"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 38, "text": "إِذۡ أَوۡحَیۡنَاۤ إِلَىٰۤ أُمِّكَ مَا یُوحَىٰۤ ۝٣٨", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "وذلك حين ألهمْنا أمَّك: أن ضعي ابنك موسى بعد ولادته في التابوت، ثم اطرحيه في النيل، فسوف يلقيه النيل على الساحل، فيأخذه فرعون عدوي وعدوه. وألقيت عليك محبة مني فصرت بذلك محبوبًا بين العباد، ولِتربى على عيني وفي حفظي. وفي الآية إثبات صفة العين لله - سبحانه وتعالى - كما يليق بجلاله وكماله.", "isBasmala": false, "translation_en": "When We inspired your mother with the inspiration.", "translation_id": "yaitu ketika Kami mengilhamkan kepada ibumu suatu yang diilhamkan,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 39, "text": "أَنِ ٱقۡذِفِیهِ فِی ٱلتَّابُوتِ فَٱقۡذِفِیهِ فِی ٱلۡیَمِّ فَلۡیُلۡقِهِ ٱلۡیَمُّ بِٱلسَّاحِلِ یَأۡخُذۡهُ عَدُوࣱّ لِّی وَعَدُوࣱّ لَّهُۥۚ وَأَلۡقَیۡتُ عَلَیۡكَ مَحَبَّةࣰ مِّنِّی وَلِتُصۡنَعَ عَلَىٰ عَیۡنِیۤ ۝٣٩", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "وذلك حين ألهمْنا أمَّك: أن ضعي ابنك موسى بعد ولادته في التابوت، ثم اطرحيه في النيل، فسوف يلقيه النيل على الساحل، فيأخذه فرعون عدوي وعدوه. وألقيت عليك محبة مني فصرت بذلك محبوبًا بين العباد، ولِتربى على عيني وفي حفظي. وفي الآية إثبات صفة العين لله - سبحانه وتعالى - كما يليق بجلاله وكماله.", "isBasmala": false, "translation_en": "`Put him in the chest; then cast him into the river. The river will wash him to shore, where an enemy of Mine and an enemy of his will pick him up. And I have bestowed upon you love from Me, so that you may be reared before My eye.", "translation_id": "Yaitu: \"Letakkanlah ia (Musa) didalam peti, kemudian lemparkanlah ia ke sungai (Nil), maka pasti sungai itu membawanya ke tepi, supaya diambil oleh (Fir'aun) musuh-Ku dan musuhnya. Dan Aku telah melimpahkan kepadamu kasih sayang yang datang dari-Ku; dan supaya kamu diasuh di bawah pengawasan-Ku,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 40, "text": "إِذۡ تَمۡشِیۤ أُخۡتُكَ فَتَقُولُ هَلۡ أَدُلُّكُمۡ عَلَىٰ مَن یَكۡفُلُهُۥۖ فَرَجَعۡنَـٰكَ إِلَىٰۤ أُمِّكَ كَیۡ تَقَرَّ عَیۡنُهَا وَلَا تَحۡزَنَۚ وَقَتَلۡتَ نَفۡسࣰا فَنَجَّیۡنَـٰكَ مِنَ ٱلۡغَمِّ وَفَتَنَّـٰكَ فُتُونࣰاۚ فَلَبِثۡتَ سِنِینَ فِیۤ أَهۡلِ مَدۡیَنَ ثُمَّ جِئۡتَ عَلَىٰ قَدَرࣲ یَـٰمُوسَىٰ ۝٤٠", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "ومننَّا عليك حين تمشي أختك تتبعك ثم تقول لمن أخذوك: هل أدلكم على من يكفُله، ويرضعه لكم؟ فرددناك إلى أمِّك بعد ما صرتَ في أيدي فرعون؛ كي تطيب نفسها بسلامتك من الغرق والقتل، ولا تحزن على فَقْدك، وقتلت الرجل القبطي خطأ فنجيناك من غَمِّ فِعْلك وخوف القتل، وابتليناك ابتلاء، فخرجت خائفًا إلى أهل \"مدين\"، فمكثت سنين فيهم، ثم جئت من \"مدين\" في الموعد الذي قدَّرناه لإرسالك مجيئًا موافقًا لقدر الله وإرادته، والأمر كله لله تبارك وتعالى.", "isBasmala": false, "translation_en": "When your sister walked along, and said, 'Shall I tell you about someone who will take care of him?' So We returned you to your mother, that she may be comforted, and not sorrow. And you killed a person, but We saved you from stress; and We tested you thoroughly. And you stayed years among the people of Median. Then you came back, as ordained, O Moses.", "translation_id": "(yaitu) ketika saudaramu yang perempuan berjalan, lalu ia berkata kepada (keluarga Fir'aun): \"Bolehkah saya menunjukkan kepadamu orang yang akan memeliharanya?\" Maka Kami mengembalikanmu kepada ibumu, agar senang hatinya dan tidak berduka cita. Dan kamu pernah membunuh seorang manusia, lalu Kami selamatkan kamu dari kesusahan dan Kami telah mencobamu dengan beberapa cobaan; maka kamu tinggal beberapa tahun diantara penduduk Madyan, kemudian kamu datang menurut waktu yang ditetapkan hai Musa,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 41, "text": "وَٱصۡطَنَعۡتُكَ لِنَفۡسِی ۝٤١", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "وأنعمتُ عليك - يا موسى - هذه النعم اجتباء مني لك، واختيارًا لرسالتي، والبلاغ عني، والقيام بأمري ونهيي.", "isBasmala": false, "translation_en": "And I made you for Myself.", "translation_id": "dan Aku telah memilihmu untuk diri-Ku.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 42, "text": "ٱذۡهَبۡ أَنتَ وَأَخُوكَ بِـَٔایَـٰتِی وَلَا تَنِیَا فِی ذِكۡرِی ۝٤٢", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "اذهب - يا موسى - أنت وأخوك هارون بآياتي الدالة على ألوهيتي وكمال قدرتي وصدق رسالتك، ولا تَضْعُفا عن مداومة ذكري. اذهبا معًا إلى فرعون؛ إنه قد جاوز الحد في الكفر والظلم، فقولا له قولا لطيفًا؛ لعله يتذكر أو يخاف ربه.", "isBasmala": false, "translation_en": "Go, you and your brother, with My signs, and do not neglect My remembrance.", "translation_id": "Pergilah kamu beserta saudaramu dengan membawa ayat-ayat-Ku, dan janganlah kamu berdua lalai dalam mengingat-Ku;", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 43, "text": "ٱذۡهَبَاۤ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ۝٤٣", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "اذهب - يا موسى - أنت وأخوك هارون بآياتي الدالة على ألوهيتي وكمال قدرتي وصدق رسالتك، ولا تَضْعُفا عن مداومة ذكري. اذهبا معًا إلى فرعون؛ إنه قد جاوز الحد في الكفر والظلم، فقولا له قولا لطيفًا؛ لعله يتذكر أو يخاف ربه.", "isBasmala": false, "translation_en": "Go to Pharaoh. He has tyrannized.", "translation_id": "Pergilah kamu berdua kepada Fir'aun, sesungguhnya dia telah melampaui batas;", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 44, "text": "فَقُولَا لَهُۥ قَوۡلࣰا لَّیِّنࣰا لَّعَلَّهُۥ یَتَذَكَّرُ أَوۡ یَخۡشَىٰ ۝٤٤", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "اذهب - يا موسى - أنت وأخوك هارون بآياتي الدالة على ألوهيتي وكمال قدرتي وصدق رسالتك، ولا تَضْعُفا عن مداومة ذكري. اذهبا معًا إلى فرعون؛ إنه قد جاوز الحد في الكفر والظلم، فقولا له قولا لطيفًا؛ لعله يتذكر أو يخاف ربه.", "isBasmala": false, "translation_en": "But speak to him nicely. Perhaps he will remember, or have some fear.\"", "translation_id": "maka berbicaralah kamu berdua kepadanya dengan kata-kata yang lemah lembut, mudah-mudahan ia ingat atau takut\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 45, "text": "قَالَا رَبَّنَاۤ إِنَّنَا نَخَافُ أَن یَفۡرُطَ عَلَیۡنَاۤ أَوۡ أَن یَطۡغَىٰ ۝٤٥", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى وهارون: ربنا إننا نخاف أن يعاجلنا بالعقوبة، أو أن يتمرد على الحق فلا يقبله.", "isBasmala": false, "translation_en": "They said, \"Lord, we fear he may persecute us, or become violent.\"", "translation_id": "Berkatalah mereka berdua: \"Ya Tuhan kami, sesungguhnya kami khawatir bahwa ia segera menyiksa kami atau akan bertambah melampaui batas\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 46, "text": "قَالَ لَا تَخَافَاۤۖ إِنَّنِی مَعَكُمَاۤ أَسۡمَعُ وَأَرَىٰ ۝٤٦", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال الله لموسى وهارون: لا تخافا من فرعون؛ فإنني معكما أسمع كلامكما وأرى أفعالكما، فاذهبا إليه وقولا له: إننا رسولان إليك من ربك أن أطلق بني إسرائيل، ولا تكلِّفهم ما لا يطيقون من الأعمال، قد أتيناك بدلالة معجزة من ربك تدل على صدقنا في دعوتنا، والسلامة من عذاب الله تعالى لمن اتبع هداه. إن ربك قد أوحى إلينا أن عذابه على مَن كذَّب وأعرض عن دعوته وشريعته.", "isBasmala": false, "translation_en": "He said, \"Do not fear, I am with you, I hear and I see.", "translation_id": "Allah berfirman: \"Janganlah kamu berdua khawatir, sesungguhnya Aku beserta kamu berdua, Aku mendengar dan melihat\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 47, "text": "فَأۡتِیَاهُ فَقُولَاۤ إِنَّا رَسُولَا رَبِّكَ فَأَرۡسِلۡ مَعَنَا بَنِیۤ إِسۡرَ ٰۤءِیلَ وَلَا تُعَذِّبۡهُمۡۖ قَدۡ جِئۡنَـٰكَ بِـَٔایَةࣲ مِّن رَّبِّكَۖ وَٱلسَّلَـٰمُ عَلَىٰ مَنِ ٱتَّبَعَ ٱلۡهُدَىٰۤ ۝٤٧", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال الله لموسى وهارون: لا تخافا من فرعون؛ فإنني معكما أسمع كلامكما وأرى أفعالكما، فاذهبا إليه وقولا له: إننا رسولان إليك من ربك أن أطلق بني إسرائيل، ولا تكلِّفهم ما لا يطيقون من الأعمال، قد أتيناك بدلالة معجزة من ربك تدل على صدقنا في دعوتنا، والسلامة من عذاب الله تعالى لمن اتبع هداه. إن ربك قد أوحى إلينا أن عذابه على مَن كذَّب وأعرض عن دعوته وشريعته.", "isBasmala": false, "translation_en": "Approach him and say, `We are the messengers of your Lord; so let the Children of Israel go with us, and do not torment them. We bring you a sign from your Lord, and peace be upon him who follows guidance.", "translation_id": "Maka datanglah kamu berdua kepadanya (Fir'aun) dan katakanlah: \"Sesungguhnya kami berdua adalah utusan Tuhanmu, maka lepaskanlah Bani Israil bersama kami dan janganlah kamu menyiksa mereka. Sesungguhnya kami telah datang kepadamu dengan membawa bukti (atas kerasulan kami) dari Tuhanmu. Dan keselamatan itu dilimpahkan kepada orang yang mengikuti petunjuk.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 48, "text": "إِنَّا قَدۡ أُوحِیَ إِلَیۡنَاۤ أَنَّ ٱلۡعَذَابَ عَلَىٰ مَن كَذَّبَ وَتَوَلَّىٰ ۝٤٨", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال الله لموسى وهارون: لا تخافا من فرعون؛ فإنني معكما أسمع كلامكما وأرى أفعالكما، فاذهبا إليه وقولا له: إننا رسولان إليك من ربك أن أطلق بني إسرائيل، ولا تكلِّفهم ما لا يطيقون من الأعمال، قد أتيناك بدلالة معجزة من ربك تدل على صدقنا في دعوتنا، والسلامة من عذاب الله تعالى لمن اتبع هداه. إن ربك قد أوحى إلينا أن عذابه على مَن كذَّب وأعرض عن دعوته وشريعته.", "isBasmala": false, "translation_en": "It was revealed to us that the punishment falls upon him who disbelieves and turns away.'\"", "translation_id": "Sesungguhnya telah diwahyukan kepada kami bahwa siksa itu (ditimpakan) atas orang-orang yang mendustakan dan berpaling.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 49, "text": "قَالَ فَمَن رَّبُّكُمَا یَـٰمُوسَىٰ ۝٤٩", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال فرعون لهما: فمَن ربكما يا موسى؟", "isBasmala": false, "translation_en": "He said, \"Who is your Lord, O Moses.\"", "translation_id": "Berkata Fir'aun: \"Maka siapakah Tuhanmu berdua, hai Musa?.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 50, "text": "قَالَ رَبُّنَا ٱلَّذِیۤ أَعۡطَىٰ كُلَّ شَیۡءٍ خَلۡقَهُۥ ثُمَّ هَدَىٰ ۝٥٠", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال له موسى: ربنا الذي أعطى كل شيء خَلْقَه اللائق به على حسن صنعه، ثم هدى كل مخلوق إلى الانتفاع بما خلقه الله له.", "isBasmala": false, "translation_en": "He said, \"Our Lord is He who gave everything its existence, then guided it.\"", "translation_id": "Musa berkata: \"Tuhan kami ialah (Tuhan) yang telah memberikan kepada tiap-tiap sesuatu bentuk kejadiannya, kemudian memberinya petunjuk.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 51, "text": "قَالَ فَمَا بَالُ ٱلۡقُرُونِ ٱلۡأُولَىٰ ۝٥١", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال فرعون لموسى: فما شأن الأمم السابقة؟ وما خبر القرون الماضية، فقد سبقونا إلى الإنكار والكفر؟", "isBasmala": false, "translation_en": "He said, \"What about the first generations?\"", "translation_id": "Berkata Fir'aun: \"Maka bagaimanakah keadaan umat-umat yang dahulu?\"", "manzil": 4, "manzil_display": ""}], "315": [{"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 52, "text": "قَالَ عِلۡمُهَا عِندَ رَبِّی فِی كِتَـٰبࣲۖ لَّا یَضِلُّ رَبِّی وَلَا یَنسَى ۝٥٢", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "قال موسى لفرعون: عِلْمُ تلك القرون فيما فَعَلَت من ذلك عند ربي في اللوح المحفوظ، ولا عِلْمَ لي به، لا يضل ربي في أفعاله وأحكامه، ولا ينسى شيئًا ممَّا علمه منها.", "isBasmala": false, "translation_en": "He said, \"Knowledge thereof is with my Lord, in a Book. My Lord never errs, nor does He forget.\"", "translation_id": "Musa menjawab: \"Pengetahuan tentang itu ada di sisi Tuhanku, di dalam sebuah kitab, Tuhan kami tidak akan salah dan tidak (pula) lupa;", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 53, "text": "ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدࣰا وَسَلَكَ لَكُمۡ فِیهَا سُبُلࣰا وَأَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجۡنَا بِهِۦۤ أَزۡوَ ٰجࣰا مِّن نَّبَاتࣲ شَتَّىٰ ۝٥٣", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "هو الذي جعل لكم الأرض ميسَّرة للانتفاع بها، وجعل لكم فيها طرقًا كثيرة، وأنزل من السماء مطرًا، فأخرج به أنواعًا مختلفة من النبات.", "isBasmala": false, "translation_en": "He who made the earth a habitat for you; and traced in it routes for you; and sent down water from the sky, with which We produce pairs of diverse plants.", "translation_id": "Yang telah menjadikan bagimu bumi sebagai hamparan dan Yang telah menjadikan bagimu di bumi itu jalan-ja]an, dan menurunkan dari langit air hujan. Maka Kami tumbuhkan dengan air hujan itu berjenis-jenis dari tumbuh-tumbuhan yang bermacam-macam.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 54, "text": "كُلُوا۟ وَٱرۡعَوۡا۟ أَنۡعَـٰمَكُمۡۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّأُو۟لِی ٱلنُّهَىٰ ۝٥٤", "juz": 16, "hizb": "(* ح 32*)", "tafsir": "كلوا - أيها الناس - من طيبات ما أنبتنا لكم، وارعوا حيواناتكم وبهائمكم. إن في كل ما ذُكر لَعلامات على قدرة الله، ودعوة لوحدانيته وإفراده بالعبادة، لذوي العقول السليمة.", "isBasmala": false, "translation_en": "Eat and pasture your livestock. In that are signs for those with understanding.", "translation_id": "Makanlah dan gembalakanlah binatang-binatangmu. Sesungguhnya pada yang demikian itu, terdapat tanda-tanda kekuasaan Allah bagi orang-orang yang berakal.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 55, "text": "۞ مِنۡهَا خَلَقۡنَـٰكُمۡ وَفِیهَا نُعِیدُكُمۡ وَمِنۡهَا نُخۡرِجُكُمۡ تَارَةً أُخۡرَىٰ ۝٥٥", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "من الأرض خَلَقْناكم - أيها الناس -، وفيها نعيدكم بعد الموت، ومنها نخرجكم أحياء مرة أخرى للحساب والجزاء.", "isBasmala": false, "translation_en": "From it We created you, and into it We will return you, and from it We will bring you out another time.", "translation_id": "Dari bumi (tanah) itulah Kami menjadikan kamu dan kepadanya Kami akan mengembalikan kamu dan daripadanya Kami akan mengeluarkan kamu pada kali yang lain,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 56, "text": "وَلَقَدۡ أَرَیۡنَـٰهُ ءَایَـٰتِنَا كُلَّهَا فَكَذَّبَ وَأَبَىٰ ۝٥٦", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "ولقد أرينا فرعون أدلتنا وحججنا جميعها، الدالة على ألوهيتنا وقدرتنا وصِدْقِ رسالة موسى فكذَّب بها، وامتنع عن قَبول الحق.", "isBasmala": false, "translation_en": "We showed him Our signs, all of them, but he denied and refused.", "translation_id": "Dan sesungguhnya Kami telah perlihatkan kepadanya (Fir'aun) tanda-tanda kekuasaan Kami semuanya maka ia mendustakan dan enggan (menerima kebenaran).", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 57, "text": "قَالَ أَجِئۡتَنَا لِتُخۡرِجَنَا مِنۡ أَرۡضِنَا بِسِحۡرِكَ یَـٰمُوسَىٰ ۝٥٧", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "قال فرعون: هل جئتنا - يا موسى - لتخرجنا من ديارنا بسحرك هذا؟", "isBasmala": false, "translation_en": "He said, \"Did you come to us to drive us out of our land with your magic, O Moses?", "translation_id": "Berkata Fir'aun: \"Adakah kamu datang kepada kami untuk mengusir kami dari negeri kami (ini) dengan sihirmu, hai Musa?", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 58, "text": "فَلَنَأۡتِیَنَّكَ بِسِحۡرࣲ مِّثۡلِهِۦ فَٱجۡعَلۡ بَیۡنَنَا وَبَیۡنَكَ مَوۡعِدࣰا لَّا نُخۡلِفُهُۥ نَحۡنُ وَلَاۤ أَنتَ مَكَانࣰا سُوࣰى ۝٥٨", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "فسوف نأتيك بسحر مثل سحرك، فاجعل بيننا وبينك موعدًا محددًا، لا نخلفه نحن ولا تخلفه أنت، في مكان مستوٍ معتدل بيننا وبينك.", "isBasmala": false, "translation_en": "We will produce for you magic like it; so make an appointment between us and you, which we will not miss-neither us, nor you-in a central place.\"", "translation_id": "Dan kamipun pasti akan mendatangkan (pula) kepadamu sihir semacam itu, maka buatlah suatu waktu untuk pertemuan antara kami dan kamu, yang kami tidak akan menyalahinya dan tidak (pula) kamu di suatu tempat yang pertengahan (letaknya).", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 59, "text": "قَالَ مَوۡعِدُكُمۡ یَوۡمُ ٱلزِّینَةِ وَأَن یُحۡشَرَ ٱلنَّاسُ ضُحࣰى ۝٥٩", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "قال موسى لفرعون: موعدكم للاجتماع يوم العيد، حين يتزيَّن الناس، ويجتمعون من كل فج وناحية وقت الضحى.", "isBasmala": false, "translation_en": "He said, \"Your appointment is the day of the festival, so let the people be gathered together at mid-morning.\"", "translation_id": "Berkata Musa: \"Waktu untuk pertemuan (kami dengan) kamu itu ialah di hari raya dan hendaklah dikumpulkan manusia pada waktu matahari sepenggalahan naik\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 60, "text": "فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَیۡدَهُۥ ثُمَّ أَتَىٰ ۝٦٠", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "فأدبر فرعون معرضًا عما أتاه به موسى من الحق، فجمع سحرته، ثم جاء بعد ذلك لموعد الاجتماع.", "isBasmala": false, "translation_en": "Pharaoh turned away, put together his plan, and then came back.", "translation_id": "Maka Fir'aun meninggalkan (tempat itu), lalu mengatur tipu dayanya, kemudian dia datang.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 61, "text": "قَالَ لَهُم مُّوسَىٰ وَیۡلَكُمۡ لَا تَفۡتَرُوا۟ عَلَى ٱللَّهِ كَذِبࣰا فَیُسۡحِتَكُم بِعَذَابࣲۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ ۝٦١", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "قال موسى لسحرة فرعون يعظهم: احذروا، لا تختلقوا على الله الكذب، فيستأصلكم بعذاب مِن عنده ويُبيدكم، وقد خسر من اختلق على الله كذبًا.", "isBasmala": false, "translation_en": "Moses said to them, \"Woe to you. Do not fabricate lies against God, or He will destroy you with a punishment. He who invents lies will fail.\"", "translation_id": "Berkata Musa kepada mereka: \"Celakalah kamu, janganlah kamu mengada-adakan kedustaan terhadap Allah, maka Dia membinasakan kamu dengan siksa\". Dan sesungguhnya telah merugi orang yang mengada-adakan kedustaan.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 62, "text": "فَتَنَـٰزَعُوۤا۟ أَمۡرَهُم بَیۡنَهُمۡ وَأَسَرُّوا۟ ٱلنَّجۡوَىٰ ۝٦٢", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "فتجاذب السحرة أمرهم بينهم وتحادثوا سرًا، قالوا: إن موسى وهارون ساحران يريدان أن يخرجاكم من بلادكم بسحرهما، ويذهبا بطريقة السحر العظيمة التي أنتم عليها، فأحكموا كيدكم، واعزموا عليه من غير اختلاف بينكم، ثم ائتوا صفًا واحدًا، وألقوا ما في أيديكم مرة واحدة؛ لتَبْهَروا الأبصار، وتغلبوا سحر موسى وأخيه، وقد ظفر بحاجته اليوم مَن علا على صاحبه، فغلبه وقهره.", "isBasmala": false, "translation_en": "They disagreed among themselves over their affair, and conferred secretly.", "translation_id": "Maka mereka berbantah-bantahan tentang urusan mereka di antara mereka dan mereka merahasiakan percakapan (mereka).", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 63, "text": "قَالُوۤا۟ إِنۡ هَـٰذَ ٰنِ لَسَـٰحِرَ ٰنِ یُرِیدَانِ أَن یُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَیَذۡهَبَا بِطَرِیقَتِكُمُ ٱلۡمُثۡلَىٰ ۝٦٣", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "فتجاذب السحرة أمرهم بينهم وتحادثوا سرًا، قالوا: إن موسى وهارون ساحران يريدان أن يخرجاكم من بلادكم بسحرهما، ويذهبا بطريقة السحر العظيمة التي أنتم عليها، فأحكموا كيدكم، واعزموا عليه من غير اختلاف بينكم، ثم ائتوا صفًا واحدًا، وألقوا ما في أيديكم مرة واحدة؛ لتَبْهَروا الأبصار، وتغلبوا سحر موسى وأخيه، وقد ظفر بحاجته اليوم مَن علا على صاحبه، فغلبه وقهره.", "isBasmala": false, "translation_en": "They said, \"These two are magicians who want to drive you out of your land with their magic, and to abolish your exemplary way of life.", "translation_id": "Mereka berkata: \"Sesungguhnya dua orang ini adalah benar-benar ahli sihir yang hendak mengusir kamu dari negeri kamu dengan sihirnya dan hendak melenyapkan kedudukan kamu yang utama.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 64, "text": "فَأَجۡمِعُوا۟ كَیۡدَكُمۡ ثُمَّ ٱئۡتُوا۟ صَفࣰّاۚ وَقَدۡ أَفۡلَحَ ٱلۡیَوۡمَ مَنِ ٱسۡتَعۡلَىٰ ۝٦٤", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "فتجاذب السحرة أمرهم بينهم وتحادثوا سرًا، قالوا: إن موسى وهارون ساحران يريدان أن يخرجاكم من بلادكم بسحرهما، ويذهبا بطريقة السحر العظيمة التي أنتم عليها، فأحكموا كيدكم، واعزموا عليه من غير اختلاف بينكم، ثم ائتوا صفًا واحدًا، وألقوا ما في أيديكم مرة واحدة؛ لتَبْهَروا الأبصار، وتغلبوا سحر موسى وأخيه، وقد ظفر بحاجته اليوم مَن علا على صاحبه، فغلبه وقهره.", "isBasmala": false, "translation_en": "So settle your plan, and come as one front. Today, whoever gains the upper hand will succeed.\"", "translation_id": "Maka himpunkanlah segala daya (sihir) kamu sekalian, kemudian datanglah dengan berbaris. dan sesungguhnya beruntunglah oran yang menang pada hari ini.", "manzil": 4, "manzil_display": ""}], "316": [{"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 65, "text": "قَالُوا۟ یَـٰمُوسَىٰۤ إِمَّاۤ أَن تُلۡقِیَ وَإِمَّاۤ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ ۝٦٥", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "قال السحرة: يا موسى إما أن تلقي عصاك أولا وإما أن نبدأ نحن فنلقي ما معنا.", "isBasmala": false, "translation_en": "They said, \"O Moses, either you throw, or we will be the first to throw.\"", "translation_id": "(Setelah mereka berkumpul) mereka berkata: \"Hai Musa (pilihlah), apakah kamu yang melemparkan (dahulu) atau kamikah orang yang mula-mula melemparkan?\"", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 66, "text": "قَالَ بَلۡ أَلۡقُوا۟ۖ فَإِذَا حِبَالُهُمۡ وَعِصِیُّهُمۡ یُخَیَّلُ إِلَیۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ ۝٦٦", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "قال لهم موسى: بل ألقُوا أنتم ما معكم أولا فألقَوا حبالهم وعصيَّهم، فتخيل موسى مِن قوة سحرهم أنها حيات تسعى، فشعر موسى في نفسه بالخوف.", "isBasmala": false, "translation_en": "He said, \"You throw.\" And suddenly, their ropes and sticks appeared to him, because of their magic, to be crawling swiftly.", "translation_id": "Berkata Musa: \"Silahkan kamu sekalian melemparkan\". Maka tiba-tiba tali-tali dan tongkat-tongkat mereka, terbayang kepada Musa seakan-akan ia merayap cepat, lantaran sihir mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 67, "text": "فَأَوۡجَسَ فِی نَفۡسِهِۦ خِیفَةࣰ مُّوسَىٰ ۝٦٧", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "قال لهم موسى: بل ألقُوا أنتم ما معكم أولا فألقَوا حبالهم وعصيَّهم، فتخيل موسى مِن قوة سحرهم أنها حيات تسعى، فشعر موسى في نفسه بالخوف.", "isBasmala": false, "translation_en": "So Moses felt apprehensive within himself.", "translation_id": "Maka Musa merasa takut dalam hatinya.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 68, "text": "قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ ۝٦٨", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "قال الله لموسى حينئذ: لا تَخَفْ من شيء، فإنك أنت الأعلى على هؤلاء السحرة وعلى فرعون وجنوده، وستغلبهم.", "isBasmala": false, "translation_en": "We said, \"Do not be afraid, you are the uppermost.", "translation_id": "Kami berkata: \"janganlah kamu takut, sesungguhnya kamulah yang paling unggul (menang).", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 69, "text": "وَأَلۡقِ مَا فِی یَمِینِكَ تَلۡقَفۡ مَا صَنَعُوۤا۟ۖ إِنَّمَا صَنَعُوا۟ كَیۡدُ سَـٰحِرࣲۖ وَلَا یُفۡلِحُ ٱلسَّاحِرُ حَیۡثُ أَتَىٰ ۝٦٩", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "وألق عصاك التي في يمينك تبتلع حبالهم وعصيهم، فما عملوه أمامك ما هو إلا مكر ساحرٍ وتخييل سِحْرٍ، ولا يظفر الساحر بسحره أين كان.", "isBasmala": false, "translation_en": "Now throw down what is in your right hand-it will swallow what they have crafted. What they have crafted is only a magician's trickery. But the magician will not succeed, no matter what he does.\"", "translation_id": "Dan lemparkanlah apa yang ada ditangan kananmu, niscaya ia akan menelan apa yang mereka perbuat. \"Sesungguhnya apa yang mereka perbuat itu adalah tipu daya tukang sihir (belaka). Dan tidak akan menang tukang sihir itu, dari mana saja ia datang\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 70, "text": "فَأُلۡقِیَ ٱلسَّحَرَةُ سُجَّدࣰا قَالُوۤا۟ ءَامَنَّا بِرَبِّ هَـٰرُونَ وَمُوسَىٰ ۝٧٠", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "فألقى موسى عصاه، فبلعت ما صنعوا، فظهر الحق وقامت الحجة عليهم. فألقى السحرة أنفسهم على الأرض ساجدين وقالوا: آمنا برب هارون وموسى، لو كان هذا سحرًا ما غُلِبْنا.", "isBasmala": false, "translation_en": "And the magicians fell down prostrate. They said, \"We have believed in the Lord of Aaron and Moses.\"", "translation_id": "Lalu tukang-tukang sihir itu tersungkur dengan bersujud, seraya berkata: \"Kami telah percaya kepada Tuhan Harun dan Musa\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 71, "text": "قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِیرُكُمُ ٱلَّذِی عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَیۡدِیَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَـٰفࣲ وَلَأُصَلِّبَنَّكُمۡ فِی جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَیُّنَاۤ أَشَدُّ عَذَابࣰا وَأَبۡقَىٰ ۝٧١", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "قال فرعون للسحرة: أصدَّقتم بموسى، واتبعتموه، وأقررتم له قبل أن آذن لكم بذلك؟ إن موسى لَعظيمكم الذي عَلَّمكم السحر؛ فلذلك تابعتموه، فلأقطعنَّ أيديكم وأرجلكم مخالفًا بينها، يدًا من جهة ورِجْلا من الجهة الأخرى، ولأصلبنَّكم - بربط أجسادكم - على جذوع النخل، ولتعلمنَّ أيها السحرة أينا: أنا أو رب موسى أشد عذابًا من الآخر، وأدوم له؟", "isBasmala": false, "translation_en": "He said, \"Did you believe in him before I have given you permission? He must be your chief, who has taught you magic. I will cut off your hands and your feet on alternate sides, and I will crucify you on the trunks of the palm-trees. Then you will know which of us is more severe in punishment, and more lasting.\"", "translation_id": "Berkata Fir'aun: \"Apakah kamu telah beriman kepadanya (Musa) sebelum aku memberi izin kepadamu sekalian. Sesungguhnya ia adalah pemimpinmu yang mengajarkan sihir kepadamu sekalian. Maka sesungguhnya aku akan memotong tangan dan kaki kamu sekalian dengan bersilang secara bertimbal balik, dan sesungguhnya aku akan menyalib kamu sekalian pada pangkal pohon kurma dan sesungguhnya kamu akan mengetahui siapa di antara kita yang lebih pedih dan lebih kekal siksanya\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 72, "text": "قَالُوا۟ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَاۤءَنَا مِنَ ٱلۡبَیِّنَـٰتِ وَٱلَّذِی فَطَرَنَاۖ فَٱقۡضِ مَاۤ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِی هَـٰذِهِ ٱلۡحَیَوٰةَ ٱلدُّنۡیَاۤ ۝٧٢", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "قال السحرة لفرعون: لن نفضلك، فنطيعك، ونتبع دينك، على ما جاءنا به موسى من البينات الدالة على صدقه ووجوب متابعته وطاعة ربه، ولن نُفَضِّل ربوبيتك المزعومة على ربوبية اللهِ الذي خلقنا، فافعل ما أنت فاعل بنا، إنما سلطانك في هذه الحياة الدنيا، وما تفعله بنا، ما هو إلا عذاب منتهٍ بانتهائها.", "isBasmala": false, "translation_en": "They said, \"We will not prefer you to the proofs that have come to us, and Him who created us. So issue whatever judgment you wish to issue. You can only rule in this lowly life.", "translation_id": "Mereka berkata: \"Kami sekali-kali tidak akan mengutamakan kamu daripada bukti-bukti yang nyata (mukjizat), yang telah datang kepada kami dan daripada Tuhan yang telah menciptakan kami; maka putuskanlah apa yang hendak kamu putuskan. Sesungguhnya kamu hanya akan dapat memutuskan pada kehidupan di dunia ini saja.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 73, "text": "إِنَّاۤ ءَامَنَّا بِرَبِّنَا لِیَغۡفِرَ لَنَا خَطَـٰیَـٰنَا وَمَاۤ أَكۡرَهۡتَنَا عَلَیۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَیۡرࣱ وَأَبۡقَىٰۤ ۝٧٣", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "إنَّا آمنا بربنا وصدَّقْنا رسوله وعملنا بما جاء به؛ ليعفو ربُّنا عن ذنوبنا، وما أكرهتنا عليه مِن عمل السحر في معارضة موسى. والله خير لنا منك - يا فرعون - جزاء لمن أطاعه، وأبقى عذابًا لمن عصاه وخالف أمره.", "isBasmala": false, "translation_en": "We have believed in our Lord, so that He may forgive us our sins, and the magic you have compelled us to practice. God is Better, and more Lasting.\"", "translation_id": "Sesungguhnya kami telah beriman kepada Tuhan kami, agar Dia mengampuni kesalahan-kesalahan kami dan sihir yang telah kamu paksakan kepada kami melakukannya. Dan Allah lebih baik (pahala-Nya) dan lebih kekal (azab-Nya)\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 74, "text": "إِنَّهُۥ مَن یَأۡتِ رَبَّهُۥ مُجۡرِمࣰا فَإِنَّ لَهُۥ جَهَنَّمَ لَا یَمُوتُ فِیهَا وَلَا یَحۡیَىٰ ۝٧٤", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "إنه من يأت ربه كافرًا به فإن له نار جهنم يُعَذَّب بها، لا يموت فيها فيستريح، ولا يحيا حياة يتلذذ بها.", "isBasmala": false, "translation_en": "Whoever comes to his Lord guilty, for him is Hell, where he neither dies nor lives.", "translation_id": "Sesungguhnya barangsiapa datang kepada Tuhannya dalam keadaan berdosa, maka sesungguhnya baginya neraka Jahannam. Ia tidak mati di dalamnya dan tidak (pula) hidup.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 75, "text": "وَمَن یَأۡتِهِۦ مُؤۡمِنࣰا قَدۡ عَمِلَ ٱلصَّـٰلِحَـٰتِ فَأُو۟لَـٰۤىِٕكَ لَهُمُ ٱلدَّرَجَـٰتُ ٱلۡعُلَىٰ ۝٧٥", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "ومن يأت ربه مؤمنًا به قد عمل الأعمال الصالحة فله المنازل العالية في جنات الإقامة الدائمة، تجري من تحت أشجارها الأنهار ماكثين فيها أبدًا، وذلك النعيم المقيم ثواب من الله لمن طهَّر نفسه من الدنس والخبث والشرك، وعبد الله وحده فأطاعه واجتنب معاصيه، ولقي ربه لا يشرك بعبادته أحدًا من خلقه.", "isBasmala": false, "translation_en": "But whoever comes to Him a believer, having worked righteousness-these will have the highest ranks.", "translation_id": "Dan barangsiapa datang kepada Tuhannya dalam keadaan beriman, lagi sungguh-sungguh telah beramal saleh, maka mereka itulah orang-orang yang memperoleh tempat-tempat yang tinggi (mulia),", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 76, "text": "جَنَّـٰتُ عَدۡنࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ وَذَ ٰلِكَ جَزَاۤءُ مَن تَزَكَّىٰ ۝٧٦", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "ومن يأت ربه مؤمنًا به قد عمل الأعمال الصالحة فله المنازل العالية في جنات الإقامة الدائمة، تجري من تحت أشجارها الأنهار ماكثين فيها أبدًا، وذلك النعيم المقيم ثواب من الله لمن طهَّر نفسه من الدنس والخبث والشرك، وعبد الله وحده فأطاعه واجتنب معاصيه، ولقي ربه لا يشرك بعبادته أحدًا من خلقه.", "isBasmala": false, "translation_en": "The Gardens of Perpetuity, beneath which rivers flow, dwelling therein forever. That is the reward for him who purifies himself.", "translation_id": "(yaitu) surga 'Adn yang mengalir sungai-sungai di bawahnya, mereka kekal di dalamnya. Dan itu adalah balasan bagi orang yang bersih (dari kekafiran dan kemaksiatan).", "manzil": 4, "manzil_display": ""}], "317": [{"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 77, "text": "وَلَقَدۡ أَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ أَنۡ أَسۡرِ بِعِبَادِی فَٱضۡرِبۡ لَهُمۡ طَرِیقࣰا فِی ٱلۡبَحۡرِ یَبَسࣰا لَّا تَخَـٰفُ دَرَكࣰا وَلَا تَخۡشَىٰ ۝٧٧", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "ولقد أوحينا إلى موسى: أن اخرُج ليلا بعبادي من بني إسرائيل من \"مصر\"، فاتِّخِذْ لهم في البحر طريقًا يابسًا، لا تخاف من فرعون وجنوده أن يلحقوكم فيدركوكم، ولا تخشى في البحر غرقًا.", "isBasmala": false, "translation_en": "And We inspired Moses: \"Travel by night with My servants, and strike for them a dry path across the sea, not fearing being overtaken, nor worrying.\"", "translation_id": "Dan sesungguhnya telah Kami wahyukan kepada Musa: \"Pergilah kamu dengan hamba-hamba-Ku (Bani Israil) di malam hari, maka buatlah untuk mereka jalan yang kering dilaut itu, kamu tak usah khawatir akan tersusul dan tidak usah takut (akan tenggelam)\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 78, "text": "فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِیَهُم مِّنَ ٱلۡیَمِّ مَا غَشِیَهُمۡ ۝٧٨", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "فأسرى موسى ببني إسرائيل، وعبر بهم طريقًا في البحر، فأتبعهم فرعون بجنوده، فغمرهم من الماء ما لا يعلم كنهه إلا الله، فغرقوا جميعًا ونجا موسى وقومه.", "isBasmala": false, "translation_en": "Pharaoh pursued them with his troops, but the sea overwhelmed them, and completely engulfed them.", "translation_id": "Maka Fir'aun dengan bala tentaranya mengejar mereka, lalu mereka ditutup oleh laut yang menenggelamkan mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 79, "text": "وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ ۝٧٩", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "وأضلَّ فرعون قومه بما زيَّنه لهم من الكفر والتكذيب، وما سلك بهم طريق الهداية.", "isBasmala": false, "translation_en": "Pharaoh misled his people, and did not guide them.", "translation_id": "Dan Fir'aun telah menyesatkan kaumnya dan tidak memberi petunjuk.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 80, "text": "یَـٰبَنِیۤ إِسۡرَ ٰۤءِیلَ قَدۡ أَنجَیۡنَـٰكُم مِّنۡ عَدُوِّكُمۡ وَوَ ٰعَدۡنَـٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَیۡمَنَ وَنَزَّلۡنَا عَلَیۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ ۝٨٠", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "يا بني إسرائيل اذكروا حين أنجيناكم مِن عدوكم فرعون، وجَعَلْنا موعدكم بجانب جبل الطور الأيمن لإنزال التوراة عليكم، ونزلنا عليكم في التيه ما تأكلونه، مما يشبه الصَّمغ طعمه كالعسل، والطير الذي يشبه السُّمَانَى.", "isBasmala": false, "translation_en": "O Children of Israel! We have delivered you from your enemy, and promised you by the right side of the Mount, and sent down to you manna and quails.", "translation_id": "Hai Bani Israil, sesungguhnya Kami telah menyelamatkan kamu sekalian dari musuhmu, dan Kami telah mengadakan perjanjian dengan kamu sekalian (untuk munajat) di sebelah kanan gunung itu dan Kami telah menurunkan kepada kamu sekalian manna dan salwa.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 81, "text": "كُلُوا۟ مِن طَیِّبَـٰتِ مَا رَزَقۡنَـٰكُمۡ وَلَا تَطۡغَوۡا۟ فِیهِ فَیَحِلَّ عَلَیۡكُمۡ غَضَبِیۖ وَمَن یَحۡلِلۡ عَلَیۡهِ غَضَبِی فَقَدۡ هَوَىٰ ۝٨١", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "كلوا من رزقنا الطيب، ولا تعتدوا فيه بأن يظلم بعضكم بعضًا، فينزل بكم غضبي، ومَن ينزل به غضبي فقد هلك وخسر.", "isBasmala": false, "translation_en": "Eat of the good things We have provided for you, but do not be excessive therein, lest My wrath descends upon you. He upon whom My wrath descends has fallen.", "translation_id": "Makanlah di antara rezeki yang baik yang telah Kami berikan kepadamu, dan janganlah melampaui batas padanya, yang menyebabkan kemurkaan-Ku menimpamu. Dan barangsiapa ditimpa oleh kemurkaan-Ku, maka sesungguhnya binasalah ia.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 82, "text": "وَإِنِّی لَغَفَّارࣱ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحࣰا ثُمَّ ٱهۡتَدَىٰ ۝٨٢", "juz": 16, "hizb": "(*¼ ح 32*)", "tafsir": "وإني لَغفار لمن تاب من ذنبه وكفره، وآمن بي وعمل الأعمال الصالحة، ثم اهتدى إلى الحق واستقام عليه.", "isBasmala": false, "translation_en": "And I am Forgiving towards him who repents, believes, acts righteously, and then remains guided.", "translation_id": "Dan sesungguhnya Aku Maha Pengampun bagi orang yang bertaubat, beriman, beramal saleh, kemudian tetap di jalan yang benar.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 83, "text": "۞ وَمَاۤ أَعۡجَلَكَ عَن قَوۡمِكَ یَـٰمُوسَىٰ ۝٨٣", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "وأيُّ شيء أعجلك عن قومك - يا موسى - فسبقتَهم إلى جانب الطور الأيمن، وخلَّفتَهم وراءك؟", "isBasmala": false, "translation_en": "\"And what made you rush ahead of your people, O Moses?\"", "translation_id": "Mengapa kamu datang lebih cepat daripada kaummu, hai Musa?", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 84, "text": "قَالَ هُمۡ أُو۟لَاۤءِ عَلَىٰۤ أَثَرِی وَعَجِلۡتُ إِلَیۡكَ رَبِّ لِتَرۡضَىٰ ۝٨٤", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "قال: إنهم خلفي سوف يلحقون بي، وسبقتُهم إليك - يا ربي - لتزداد عني رضا.", "isBasmala": false, "translation_en": "He said, \"They are following in my footsteps; and I hurried on to You, my Lord, that you may be pleased.\"", "translation_id": "Berkata, Musa: \"Itulah mereka sedang menyusuli aku dan aku bersegera kepada-Mu. Ya Tuhanku, agar supaya Engkau ridha (kepadaku)\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 85, "text": "قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِیُّ ۝٨٥", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "قال الله لموسى: فإنا قد ابتلينا قومك بعد فراقك إياهم بعبادة العجل، وإن السامري قد أضلهم.", "isBasmala": false, "translation_en": "He said, \"We have tested your people in your absence, and the Samarian misled them.\"", "translation_id": "Allah berfirman: \"Maka sesungguhnya Kami telah menguji kaummu sesudah kamu tinggalkan, dan mereka telah disesatkan oleh Samiri.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 86, "text": "فَرَجَعَ مُوسَىٰۤ إِلَىٰ قَوۡمِهِۦ غَضۡبَـٰنَ أَسِفࣰاۚ قَالَ یَـٰقَوۡمِ أَلَمۡ یَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَیۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن یَحِلَّ عَلَیۡكُمۡ غَضَبࣱ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِی ۝٨٦", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "فرجع موسى إلى قومه غضبان عليهم حزينًا، وقال لهم: يا قوم ألم يَعِدْكم ربكم وعدًا حسنًا بإنزال التوراة؟ أفطال عليكم العهد واستبطأتم الوعد، أم أردتم أن تفعلوا فعلا يحل عليكم بسببه غضب من ربكم، فأخلفتم موعدي وعبدتم العجل، وتركتم الالتزام بأوامري؟", "isBasmala": false, "translation_en": "So Moses returned to his people, angry and disappointed. He said, \"O my people, did your Lord not promise you a good promise? Was the time too long for you? Or did you want wrath from your Lord to descend upon you, so you broke your promise to me?\"", "translation_id": "Kemudian Musa kembali kepada kaumnya dengan marah dan bersedih hati. Berkata Musa: \"Hai kaumku, bukankah Tuhanmu telah menjanjikan kepadamu suatu janji yang baik? Maka apakah terasa lama masa yang berlalu itu bagimu atau kamu menghendaki agar kemurkaan dari Tuhanmu menimpamu, dan kamu melanggar perjanjianmu dengan aku?\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 87, "text": "قَالُوا۟ مَاۤ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَـٰكِنَّا حُمِّلۡنَاۤ أَوۡزَارࣰا مِّن زِینَةِ ٱلۡقَوۡمِ فَقَذَفۡنَـٰهَا فَكَذَ ٰلِكَ أَلۡقَى ٱلسَّامِرِیُّ ۝٨٧", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "قالوا: يا موسى ما أخلفنا موعدك باختيارنا، ولكنَّا حُمِّلنا أثقالا مِن حليِّ قوم فرعون، فألقيناها في حفرة فيها نار بأمر السامري، فكذلك ألقى السامري ما كان معه من تربة حافر فرس جبريل عليه السلام.", "isBasmala": false, "translation_en": "They said, \"We did not break our promise to you by our choice, but we were made to carry loads of the people's ornaments, and we cast them in. That was what the Samarian suggested.\"", "translation_id": "Mereka berkata: \"Kami sekali-kali tidak melanggar perjanjianmu dengan kemauan kami sendiri, tetapi kami disuruh membawa beban-beban dari perhiasan kaum itu, maka kami telah melemparkannya, dan demikian pula Samiri melemparkannya\",", "manzil": 4, "manzil_display": ""}], "318": [{"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 88, "text": "فَأَخۡرَجَ لَهُمۡ عِجۡلࣰا جَسَدࣰا لَّهُۥ خُوَارࣱ فَقَالُوا۟ هَـٰذَاۤ إِلَـٰهُكُمۡ وَإِلَـٰهُ مُوسَىٰ فَنَسِیَ ۝٨٨", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "فصنع السامري لبني إسرائيل من الذهب عجلا جسدًا يخور خوار البقر، فقال المفتونون به منهم للآخرين: هذا هو إلهكم وإله موسى، نسيه وغَفَل عنه.", "isBasmala": false, "translation_en": "So he produced for them a calf-a mere body which lowed. And they said, \"This is your god, and the god of Moses, but he has forgotten.\"", "translation_id": "kemudian Samiri mengeluarkan untuk mereka (dari lobang itu) anak lembu yang bertubuh dan bersuara, maka mereka berkata: \"Inilah Tuhanmu dan Tuhan Musa, tetapi Musa telah lupa\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 89, "text": "أَفَلَا یَرَوۡنَ أَلَّا یَرۡجِعُ إِلَیۡهِمۡ قَوۡلࣰا وَلَا یَمۡلِكُ لَهُمۡ ضَرࣰّا وَلَا نَفۡعࣰا ۝٨٩", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "أفلا يرى الذين عبدوا العجل أنه لا يكلمهم ابتداء، ولا يردُّ عليهم جوابًا، ولا يقدر على دفع ضرٍّ عنهم، ولا جلب نفع لهم؟", "isBasmala": false, "translation_en": "Did they not see that it cannot return a word to them, and has no power to harm them or benefit them?", "translation_id": "Maka apakah mereka tidak memperhatikan bahwa patung anak lembu itu tidak dapat memberi jawaban kepada mereka, dan tidak dapat memberi kemudharatan kepada mereka dan tidak (pula) kemanfaatan?", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 90, "text": "وَلَقَدۡ قَالَ لَهُمۡ هَـٰرُونُ مِن قَبۡلُ یَـٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَـٰنُ فَٱتَّبِعُونِی وَأَطِیعُوۤا۟ أَمۡرِی ۝٩٠", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "ولقد قال هارون لبني إسرائيل من قبل رجوع موسى إليهم: يا قوم إنما اختُبرتم بهذا العجل؛ ليظهر المؤمن منكم من الكافر، وإن ربكم الرحمن لا غيره فاتبعوني فيما أدعوكم إليه من عبادة الله، وأطيعوا أمري في اتباع شرعه.", "isBasmala": false, "translation_en": "Aaron had said to them before, \"O my people, you are being tested by this. And your Lord is the Merciful, so follow me, and obey my command.\"", "translation_id": "Dan sesungguhnya Harun telah berkata kepada mereka sebelumnya: \"Hai kaumku, sesungguhnya kamu hanya diberi cobaan dengan anak lembu. itu dan sesungguhnya Tuhanmu ialah (Tuhan) Yang Maha Pemurah, maka ikutilah aku dan taatilah perintahku\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 91, "text": "قَالُوا۟ لَن نَّبۡرَحَ عَلَیۡهِ عَـٰكِفِینَ حَتَّىٰ یَرۡجِعَ إِلَیۡنَا مُوسَىٰ ۝٩١", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "قال عُبَّاد العجل منهم: لن نزال مقيمين على عبادة العجل حتى يرجع إلينا موسى.", "isBasmala": false, "translation_en": "They said, \"We will not give up our devotion to it, until Moses returns to us.\"", "translation_id": "Mereka menjawab: \"Kami akan tetap menyembah patung anak lembu ini, hingga Musa kembali kepada kami\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 92, "text": "قَالَ یَـٰهَـٰرُونُ مَا مَنَعَكَ إِذۡ رَأَیۡتَهُمۡ ضَلُّوۤا۟ ۝٩٢", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "قال موسى لأخيه هارون: أيُّ شيء منعك حين رأيتهم ضلُّوا عن دينهم أن لا تتبعني، فتلحق بي وتتركهم؟ أفعصيت أمري فيما أمرتك به من خلافتي والإصلاح بعدي؟", "isBasmala": false, "translation_en": "He said, \"O Aaron, what prevented you, when you saw them going astray.", "translation_id": "Berkata Musa: \"Hai Harun, apa yang menghalangi kamu ketika kamu melihat mereka telah sesat,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 93, "text": "أَلَّا تَتَّبِعَنِۖ أَفَعَصَیۡتَ أَمۡرِی ۝٩٣", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "قال موسى لأخيه هارون: أيُّ شيء منعك حين رأيتهم ضلُّوا عن دينهم أن لا تتبعني، فتلحق بي وتتركهم؟ أفعصيت أمري فيما أمرتك به من خلافتي والإصلاح بعدي؟", "isBasmala": false, "translation_en": "From following me? Did you disobey my command?\"", "translation_id": "(sehingga) kamu tidak mengikuti aku? Maka apakah kamu telah (sengaja) mendurhakai perintahku?\"", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 94, "text": "قَالَ یَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡیَتِی وَلَا بِرَأۡسِیۤۖ إِنِّی خَشِیتُ أَن تَقُولَ فَرَّقۡتَ بَیۡنَ بَنِیۤ إِسۡرَ ٰۤءِیلَ وَلَمۡ تَرۡقُبۡ قَوۡلِی ۝٩٤", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "ثم أخذ موسى بلحية هارون ورأسه يجرُّه إليه، فقال له هارون: يا ابن أمي لا تمسك بلحيتي ولا بشعر رأسي، إني خفتُ - إن تركتهم ولحقت بك - أن تقول: فرَّقت بين بني إسرائيل، ولم تحفظ وصيتي بحسن رعايتهم.", "isBasmala": false, "translation_en": "He said, \"Son of my mother, do not seize me by my beard or my head. I feared you would say, `You have caused division among the Children of Israel, and did not regard my word.'\"", "translation_id": "Harun menjawab' \"Hai putera ibuku, janganlah kamu pegang janggutku dan jangan (pula) kepalaku; sesungguhnya aku khawatir bahwa kamu akan berkata (kepadaku): \"Kamu telah memecah antara Bani Israil dan kamu tidak memelihara amanatku\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 95, "text": "قَالَ فَمَا خَطۡبُكَ یَـٰسَـٰمِرِیُّ ۝٩٥", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "قال موسى للسامري: فما شأنك يا سامري؟ وما الذي دعاك إلى ما فعلته؟", "isBasmala": false, "translation_en": "He said, \"What do you have to say, O Samarian?\"", "translation_id": "Berkata Musa: \"Apakah yang mendorongmu (berbuat demikian) hai Samiri?\"", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 96, "text": "قَالَ بَصُرۡتُ بِمَا لَمۡ یَبۡصُرُوا۟ بِهِۦ فَقَبَضۡتُ قَبۡضَةࣰ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَ ٰلِكَ سَوَّلَتۡ لِی نَفۡسِی ۝٩٦", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "قال السامري: رأيت ما لم يروه - وهو جبريل عليه السلام - على فرس، وقت خروجهم من البحر وغرق فرعون وجنوده، فأخذتُ بكفي ترابا من أثر حافر فرس جبريل، فألقيته على الحليِّ الذي صنعت منه العجل، فكان عجلا جسدًا له خوار؛ بلاء وفتنة، وكذلك زيَّنت لي نفسي الأمَّارة بالسوء هذا الصنيع.", "isBasmala": false, "translation_en": "He said, \"I saw what they did not see, so I grasped a handful from the Messenger's traces, and I flung it away. Thus my soul prompted me.\"", "translation_id": "Samiri menjawab: \"Aku mengetahui sesuatu yang mereka tidak mengetahuinya, maka aku ambil segenggam dari jejak rasul lalu aku melemparkannya, dan demikianlah nafsuku membujukku\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 97, "text": "قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِی ٱلۡحَیَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدࣰا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰۤ إِلَـٰهِكَ ٱلَّذِی ظَلۡتَ عَلَیۡهِ عَاكِفࣰاۖ لَّنُحَرِّقَنَّهُۥ ثُمَّ لَنَنسِفَنَّهُۥ فِی ٱلۡیَمِّ نَسۡفًا ۝٩٧", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "قال موسى للسامري: فاذهب فإن لك في حياتك أن تعيش منبوذًا تقول لكل أحد: لا أَمَسُّ ولا أُمَسُّ، وإن لك موعدا لعذابك وعقابك، لن يُخْلفك الله إياه، وسوف تلقاه، وانظر إلى معبودك الذي أقمت على عبادته لنُحرقنَّه بالنار، ثم لنُذرينَّه في اليمِّ تذرية.", "isBasmala": false, "translation_en": "He said, \"Begone! Your lot in this life is to say, 'No contact.' And you have an appointment that you will not miss. Now look at your god that you remained devoted to-we will burn it up, and then blow it away into the sea, as powder.\"", "translation_id": "Berkata Musa: \"Pergilah kamu, maka sesungguhnya bagimu di dalam kehidupan di dunia ini (hanya dapat) mengatakan: \"Janganlah menyentuh (aku)\". Dan sesungguhnya bagimu hukuman (di akhirat) yang kamu sekali-kali tidak dapat menghindarinya, dan lihatlah tuhanmu itu yang kamu tetap menyembahnya. Sesungguhnya kami akan membakarnya, kemudian kami sungguh-sungguh akan menghamburkannya ke dalam laut (berupa abu yang berserakan).", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 98, "text": "إِنَّمَاۤ إِلَـٰهُكُمُ ٱللَّهُ ٱلَّذِی لَاۤ إِلَـٰهَ إِلَّا هُوَۚ وَسِعَ كُلَّ شَیۡءٍ عِلۡمࣰا ۝٩٨", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "إنما إلهكم - أيها الناس - هو الله الذي لا معبود بحق إلا هو، وسع علمه كل شيء.", "isBasmala": false, "translation_en": "Surely your god is God, the One besides whom there is no other god. He comprehends everything in knowledge.", "translation_id": "Sesungguhnya Tuhanmu hanyalah Allah, yang tidak ada Tuhan selain Dia. Pengetahuan-Nya meliputi segala sesuatu\".", "manzil": 4, "manzil_display": ""}], "319": [{"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 99, "text": "كَذَ ٰلِكَ نَقُصُّ عَلَیۡكَ مِنۡ أَنۢبَاۤءِ مَا قَدۡ سَبَقَۚ وَقَدۡ ءَاتَیۡنَـٰكَ مِن لَّدُنَّا ذِكۡرࣰا ۝٩٩", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "كما قصصنا عليك - أيها الرسول - أنباء موسى وفرعون وقومهما، نخبرك بأنباء السابقين لك. وقد آتيناك مِن عندنا هذا القرآن ذكرى لمن يتذكر.", "isBasmala": false, "translation_en": "Thus We narrate to you reports of times gone by; and We have given you a message from Our Presence.", "translation_id": "Demikianlah kami kisahkan kepadamu (Muhammad) sebagian kisah umat yang telah lalu, dan sesungguhnya telah Kami berikan kepadamu dari sisi Kami suatu peringatan (Al Quran).", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 100, "text": "مَّنۡ أَعۡرَضَ عَنۡهُ فَإِنَّهُۥ یَحۡمِلُ یَوۡمَ ٱلۡقِیَـٰمَةِ وِزۡرًا ۝١٠٠", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "من أعرض عن هذا القرآن، ولم يصدق به، ولم يعمل بما فيه، فإنه يأتي ربه يوم القيامة يحمل إثمًا عظيمًا.", "isBasmala": false, "translation_en": "Whoever turns away from it will carry on the Day of Resurrection a burden.", "translation_id": "Barangsiapa berpaling dari pada Al qur'an maka sesungguhnya ia akan memikul dosa yang besar di hari kiamat,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 101, "text": "خَـٰلِدِینَ فِیهِۖ وَسَاۤءَ لَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ حِمۡلࣰا ۝١٠١", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "خالدين في العذاب، وساءهم ذلك الحمل الثقيل من الآثام حيث أوردهم النار.", "isBasmala": false, "translation_en": "Abiding therein forever. And wretched is their burden on the Day of Resurrection.", "translation_id": "mereka kekal di dalam keadaan itu. Dan amat buruklah dosa itu sebagai beban bagi mereka di hari kiamat,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 102, "text": "یَوۡمَ یُنفَخُ فِی ٱلصُّورِۚ وَنَحۡشُرُ ٱلۡمُجۡرِمِینَ یَوۡمَىِٕذࣲ زُرۡقࣰا ۝١٠٢", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "يوم يَنفُخ الملَكُ في \"القرن\" لصيحة البعث، ونسوق الكافرين ذلكم اليوم وهم زرق، تغيَّرت ألوانهم وعيونهم؛ من شدة الأحداث والأهوال.", "isBasmala": false, "translation_en": "On the Day when the Trumpet is blown-We will gather the sinners on that Day, blue.", "translation_id": "(yaitu) di hari (yang di waktu itu) ditiup sangkakala dan Kami akan mengumpulkan pada hari itu orang-orang yang berdosa dengan muka yang biru muram;", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 103, "text": "یَتَخَـٰفَتُونَ بَیۡنَهُمۡ إِن لَّبِثۡتُمۡ إِلَّا عَشۡرࣰا ۝١٠٣", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "يتهامسون بينهم، يقول بعضهم لبعض: ما لبثتم في الحياة الدنيا إلا عشرة أيام.", "isBasmala": false, "translation_en": "Murmuring among themselves: \"You have lingered only for ten.\"", "translation_id": "mereka berbisik-bisik di antara mereka: \"Kamu tidak berdiam (di dunia) melainkan hanyalah sepuluh (hari)\"", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 104, "text": "نَّحۡنُ أَعۡلَمُ بِمَا یَقُولُونَ إِذۡ یَقُولُ أَمۡثَلُهُمۡ طَرِیقَةً إِن لَّبِثۡتُمۡ إِلَّا یَوۡمࣰا ۝١٠٤", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "نحن أعلم بما يقولون ويُسِرُّون حين يقول أعلمهم وأوفاهم عقلا ما لبثتم إلا يومًا واحدًا؛ لقِصَر مدة الدنيا في أنفسهم يوم القيامة.", "isBasmala": false, "translation_en": "We are fully aware of what they say, when the most exemplary of them in conduct will say, \"You have lingered only a day.\"", "translation_id": "Kami lebih mengetahui apa yang mereka katakan, ketika berkata orang yang paling lurus jalannya di antara mereka: \"Kamu tidak berdiam (di dunia), melainkan hanyalah sehari saja\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 105, "text": "وَیَسۡـَٔلُونَكَ عَنِ ٱلۡجِبَالِ فَقُلۡ یَنسِفُهَا رَبِّی نَسۡفࣰا ۝١٠٥", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "ويسألك - أيها الرسول - قومك عن مصير الجبال يوم القيامة، فقل لهم: يزيلها ربِّي عن أماكنها فيجعلها هباء منبثًا.", "isBasmala": false, "translation_en": "And they ask you about the mountains. Say, \"My Lord will crumble them utterly.\"", "translation_id": "Dan mereka bertanya kepadamu tentang gunung-gunung, maka katakanlah: \"Tuhanku akan menghancurkannya (di hari kiamat) sehancur-hancurnya,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 106, "text": "فَیَذَرُهَا قَاعࣰا صَفۡصَفࣰا ۝١٠٦", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "فيترك الأرض حينئذ منبسطة مستوية ملساء لا نبات فيها، لا يرى الناظر إليها مِن استوائها مَيْلا ولا ارتفاعًا ولا انخفاضًا.", "isBasmala": false, "translation_en": "And leave them desolate waste.", "translation_id": "maka Dia akan menjadikan (bekas) gunung-gunung itu datar sama sekali,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 107, "text": "لَّا تَرَىٰ فِیهَا عِوَجࣰا وَلَاۤ أَمۡتࣰا ۝١٠٧", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "فيترك الأرض حينئذ منبسطة مستوية ملساء لا نبات فيها، لا يرى الناظر إليها مِن استوائها مَيْلا ولا ارتفاعًا ولا انخفاضًا.", "isBasmala": false, "translation_en": "You will see in them neither crookedness, nor deviation.\"", "translation_id": "tidak ada sedikitpun kamu lihat padanya tempat yang rendah dan yang tinggi-tinggi.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 108, "text": "یَوۡمَىِٕذࣲ یَتَّبِعُونَ ٱلدَّاعِیَ لَا عِوَجَ لَهُۥۖ وَخَشَعَتِ ٱلۡأَصۡوَاتُ لِلرَّحۡمَـٰنِ فَلَا تَسۡمَعُ إِلَّا هَمۡسࣰا ۝١٠٨", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "في ذلك اليوم يتبع الناس صوت الداعي إلى موقف القيامة، لا محيد عن دعوة الداعي؛ لأنها حق وصدق لجميع الخلق، وسكنت الأصوات خضوعًا للرحمن، فلا تسمع منها إلا صوتًا خفيًا.", "isBasmala": false, "translation_en": "On that Day, they will follow the caller, without any deviation. Voices will be hushed before the Merciful, and you will hear nothing but murmur.", "translation_id": "Pada hari itu manusia mengikuti (menuju kepada suara) penyeru dengan tidak berbelok-belok; dan merendahlah semua suara kepada Tuhan Yang Maha Pemurah, maka kamu tidak mendengar kecuali bisikan saja.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 109, "text": "یَوۡمَىِٕذࣲ لَّا تَنفَعُ ٱلشَّفَـٰعَةُ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَـٰنُ وَرَضِیَ لَهُۥ قَوۡلࣰا ۝١٠٩", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "في ذلك اليوم لا تنفع الشفاعة أحدًا من الخلق، إلا إذا أذن الرحمن للشافع، ورضي عن المشفوع له، ولا يكون ذلك إلا للمؤمن المخلص.", "isBasmala": false, "translation_en": "On that Day, intercession will not avail, except for him permitted by the Merciful, and whose words He has approved.", "translation_id": "Pada hari itu tidak berguna syafa'at, kecuali (syafa'at) orang yang Allah Maha Pemurah telah memberi izin kepadanya, dan Dia telah meridhai perkataannya.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 110, "text": "یَعۡلَمُ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡ وَلَا یُحِیطُونَ بِهِۦ عِلۡمࣰا ۝١١٠", "juz": 16, "hizb": "(*½ ح 32*)", "tafsir": "يعلم الله ما بين أيدي الناس مِن أمر القيامة وما خلفهم من أمر الدنيا، ولا يحيط خلقه به علمًا سبحانه وتعالى.", "isBasmala": false, "translation_en": "He knows what is before them and what is behind them, and they cannot comprehend Him in their knowledge.", "translation_id": "Dia mengetahui apa yang ada di hadapan mereka dan apa yang ada di belakang mereka, sedang ilmu mereka tidak dapat meliputi ilmu-Nya.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 111, "text": "۞ وَعَنَتِ ٱلۡوُجُوهُ لِلۡحَیِّ ٱلۡقَیُّومِۖ وَقَدۡ خَابَ مَنۡ حَمَلَ ظُلۡمࣰا ۝١١١", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "وخضعت وجوه الخلائق، وذلَّت لخالقها، الذي له جميع معاني الحياة الكاملة كما يليق بجلاله الذي لا يموت، القائم على تدبير كلِّ شيء، المستغني عمَّن سواه. وقد خسر يوم القيامة مَن أشرك مع الله أحدًا من خلقه.", "isBasmala": false, "translation_en": "Faces will be humbled before the Living, the Eternal. Whoever carries injustice will despair.", "translation_id": "Dan tunduklah semua muka (dengan berendah diri) kepada Tuhan Yang Hidup Kekal lagi senantiasa mengurus (makhluk-Nya). Dan sesungguhnya telah merugilah orang yang melakukan kezaliman.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 112, "text": "وَمَن یَعۡمَلۡ مِنَ ٱلصَّـٰلِحَـٰتِ وَهُوَ مُؤۡمِنࣱ فَلَا یَخَافُ ظُلۡمࣰا وَلَا هَضۡمࣰا ۝١١٢", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "ومن يعمل صالحات الأعمال وهو مؤمن بربه، فلا يخاف ظلمًا بزيادة سيئاته، ولا هضمًا بنقص حسناته.", "isBasmala": false, "translation_en": "But whoever has done righteous deeds, while being a believer-will fear neither injustice, nor grievance.", "translation_id": "Dan barangsiapa mengerjakan amal-amal yang saleh dan ia dalam keadaan beriman, maka ia tidak khawatir akan perlakuan yang tidak adil (terhadapnya) dan tidak (pula) akan pengurangan haknya.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 113, "text": "وَكَذَ ٰلِكَ أَنزَلۡنَـٰهُ قُرۡءَانًا عَرَبِیࣰّا وَصَرَّفۡنَا فِیهِ مِنَ ٱلۡوَعِیدِ لَعَلَّهُمۡ یَتَّقُونَ أَوۡ یُحۡدِثُ لَهُمۡ ذِكۡرࣰا ۝١١٣", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "وكما رغَّبنا أهل الإيمان في صالحات الأعمال، وحذَّرنا أهل الكفر من المقام على معاصيهم وكفرهم بآياتنا، أنزلنا هذا القرآن باللسان العربي؛ ليفهموه، وفصَّلنا فيه أنواعًا من الوعيد؛ رجاء أن يتقوا ربهم، أو يُحدِث لهم هذا القرآن تذكرة، فيتعظوا، ويعتبروا.", "isBasmala": false, "translation_en": "Thus We have revealed it an Arabic Quran, and We have diversified the warnings in it, that perhaps they would become righteous, or it may produce a lesson for them.", "translation_id": "Dan demikianlah Kami menurunkan Al Quran dalam bahasa Arab, dan Kami telah menerangkan dengan berulang kali, di dalamnya sebahagian dari ancaman, agar mereka bertakwa atau (agar) Al Quran itu menimbulkan pengajaran bagi mereka.", "manzil": 4, "manzil_display": ""}], "320": [{"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 114, "text": "فَتَعَـٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن یُقۡضَىٰۤ إِلَیۡكَ وَحۡیُهُۥۖ وَقُل رَّبِّ زِدۡنِی عِلۡمࣰا ۝١١٤", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "فتنزَّه الله - سبحانه - وارتفع، وتقدَّس عن كل نقص، الملك الذي قهر سلطانه كل ملك وجبار، المتصرف بكل شيء، الذي هو حق، ووعده حق، ووعيده حق، وكل شيء منه حق. ولا تعجل - أيها الرسول - بمسابقة جبريل في تَلَقِّي القرآن قبل أن يَفْرَغ منه، وقل: ربِّ زدني علمًا إلى ما علمتني.", "isBasmala": false, "translation_en": "Exalted is God, the True King. Do not be hasty with the Quran before its inspiration to you is concluded, and say, \"My Lord, increase me in knowledge.\"", "translation_id": "Maka Maha Tinggi Allah Raja Yang sebenar-benarnya, dan janganlah kamu tergesa-gesa membaca Al qur'an sebelum disempurnakan mewahyukannya kepadamu, dan katakanlah: \"Ya Tuhanku, tambahkanlah kepadaku ilmu pengetahuan\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 115, "text": "وَلَقَدۡ عَهِدۡنَاۤ إِلَىٰۤ ءَادَمَ مِن قَبۡلُ فَنَسِیَ وَلَمۡ نَجِدۡ لَهُۥ عَزۡمࣰا ۝١١٥", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "ولقد وصينا آدم مِن قَبلِ أن يأكل من الشجرة، ألا يأكل منها، وقلنا له: إن إبليس عدو لك ولزوجك، فلا يخرجنكما من الجنة، فتشقى أنت وزوجك في الدنيا، فوسوس إليه الشيطان فأطاعه، ونسي آدم الوصية، ولم نجد له قوة في العزم يحفظ بها ما أُمر به.", "isBasmala": false, "translation_en": "And We covenanted with Adam before, but he forgot, and We found in him no resolve.", "translation_id": "Dan sesungguhnya telah Kami perintahkan kepada Adam dahulu, maka ia lupa (akan perintah itu), dan tidak Kami dapati padanya kemauan yang kuat.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 116, "text": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ أَبَىٰ ۝١١٦", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "واذكر - أيها الرسول - إذ قلنا للملائكة: اسجدوا لآدم سجود تحية وإكرام، فأطاعوا، وسجدوا، لكن إبليس امتنع من السجود.", "isBasmala": false, "translation_en": "And when We said to the angels, \"Bow down to Adam.\" They bowed down, except for Satan; he refused.", "translation_id": "Dan (ingatlah) ketika Kami berkata kepada malaikat: \"Sujudlah kamu kepada Adam\", maka mereka sujud kecuali iblis. Ia membangkang.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 117, "text": "فَقُلۡنَا یَـٰۤـَٔادَمُ إِنَّ هَـٰذَا عَدُوࣱّ لَّكَ وَلِزَوۡجِكَ فَلَا یُخۡرِجَنَّكُمَا مِنَ ٱلۡجَنَّةِ فَتَشۡقَىٰۤ ۝١١٧", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "فقلنا: يا آدم إن إبليس هذا عدو لك ولزوجتك، فاحذرا منه، ولا تطيعاه بمعصيتي، فيخرجكما من الجنة، فتشقى إذا أُخرجت منها.", "isBasmala": false, "translation_en": "We said, \"O Adam, this is an enemy to you and to your wife. So do not let him make you leave the Garden, for then you will suffer.", "translation_id": "Maka Kami berkata: \"Hai Adam, sesungguhnya ini (iblis) adalah musuh bagimu dan bagi isterimu, maka sekali-kali janganlah sampai ia mengeluarkan kamu berdua dari surga, yang menyebabkan kamu menjadi celaka.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 118, "text": "إِنَّ لَكَ أَلَّا تَجُوعَ فِیهَا وَلَا تَعۡرَىٰ ۝١١٨", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "إن لك - يا آدم - في هذه الجنة أن تأكل فلا تجوع، وأن تَلْبَس فلا تَعْرى.", "isBasmala": false, "translation_en": "In it you will never go hungry, nor be naked.", "translation_id": "Sesungguhnya kamu tidak akan kelaparan di dalamnya dan tidak akan telanjang,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 119, "text": "وَأَنَّكَ لَا تَظۡمَؤُا۟ فِیهَا وَلَا تَضۡحَىٰ ۝١١٩", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "وأن لك ألا تعطش في هذه الجنة ولا يصيبك حر الشمس.", "isBasmala": false, "translation_en": "Nor will you be thirsty in it, nor will you swelter.\"", "translation_id": "dan sesungguhnya kamu tidak akan merasa dahaga dan tidak (pula) akan ditimpa panas matahari di dalamnya\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 120, "text": "فَوَسۡوَسَ إِلَیۡهِ ٱلشَّیۡطَـٰنُ قَالَ یَـٰۤـَٔادَمُ هَلۡ أَدُلُّكَ عَلَىٰ شَجَرَةِ ٱلۡخُلۡدِ وَمُلۡكࣲ لَّا یَبۡلَىٰ ۝١٢٠", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "فوسوس الشيطان لآدم وقال له: هل أدلك على شجرة، إن أكلت منها خُلِّدتَ فلم تمت، وملكت مُلْكًا لا ينقضي ولا ينقطع؟", "isBasmala": false, "translation_en": "But Satan whispered to him. He said, \"O Adam, shall I show you the Tree of Immortality, and a kingdom that never decays?\"", "translation_id": "Kemudian syaitan membisikkan pikiran jahat kepadanya, dengan berkata: \"Hai Adam, maukah saya tunjukkan kepada kamu pohon khuldi dan kerajaan yang tidak akan binasa?\"", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 121, "text": "فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَ ٰتُهُمَا وَطَفِقَا یَخۡصِفَانِ عَلَیۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰۤ ءَادَمُ رَبَّهُۥ فَغَوَىٰ ۝١٢١", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "فأكل آدم وحواء من الشجرة التي نهاهما الله عنها، فانكشفت لهما عوراتهما، وكانت مستورةً عن أعينهما، فأخذا ينزعان من ورق أشجار الجنة ويلصقانه عليهما؛ ليسترا ما انكشف من عوراتهما، وخالف آدم أمر ربه، فغوى بالأكل من الشجرة التي نهاه الله عن الاقتراب منها.", "isBasmala": false, "translation_en": "And so they ate from it; whereupon their bodies became visible to them, and they started covering themselves with the leaves of the Garden. Thus Adam disobeyed his Lord, and fell.", "translation_id": "Maka keduanya memakan dari buah pohon itu, lalu nampaklah bagi keduanya aurat-auratnya dan mulailah keduanya menutupinya dengan daun-daun (yang ada di) surga, dan durhakalah Adam kepada Tuhan dan sesatlah ia.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 122, "text": "ثُمَّ ٱجۡتَبَـٰهُ رَبُّهُۥ فَتَابَ عَلَیۡهِ وَهَدَىٰ ۝١٢٢", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "ثم اصطفى الله آدم، وقرَّبه، وقَبِل توبته، وهداه رشده.", "isBasmala": false, "translation_en": "But then his Lord recalled him, and pardoned him, and guided him.", "translation_id": "Kemudian Tuhannya memilihnya maka Dia menerima taubatnya dan memberinya petunjuk.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 123, "text": "قَالَ ٱهۡبِطَا مِنۡهَا جَمِیعَۢاۖ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ فَإِمَّا یَأۡتِیَنَّكُم مِّنِّی هُدࣰى فَمَنِ ٱتَّبَعَ هُدَایَ فَلَا یَضِلُّ وَلَا یَشۡقَىٰ ۝١٢٣", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "قال الله تعالى لآدم وحواء: اهبطا من الجنة إلى الأرض جميعًا مع إبليس، فأنتما وهو أعداء، فإن يأتكم مني هدى وبيان فمن اتبع هداي وبياني وعمل بهما فإنه يرشد في الدنيا، ويهتدي، ولا يشقى في الآخرة بعقاب الله.", "isBasmala": false, "translation_en": "He said, \"Go down from it, altogether; some of you enemies of some others. But whenever guidance comes to you from Me, whoever follows My guidance, will not go astray, nor suffer.", "translation_id": "Allah berfirman: \"Turunlah kamu berdua dari surga bersama-sama, sebagian kamu menjadi musuh bagi sebagian yang lain. Maka jika datang kepadamu petunjuk daripada-Ku, lalu barangsiapa yang mengikut petunjuk-Ku, ia tidak akan sesat dan tidak akan celaka.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 124, "text": "وَمَنۡ أَعۡرَضَ عَن ذِكۡرِی فَإِنَّ لَهُۥ مَعِیشَةࣰ ضَنكࣰا وَنَحۡشُرُهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ أَعۡمَىٰ ۝١٢٤", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "ومن تولَّى عن ذكري الذي أذكِّره به فإن له في الحياة الأولى معيشة ضيِّقة شاقة -وإن ظهر أنه من أهل الفضل واليسار-، ويُضيَّق قبره عليه ويعذَّب فيه، ونحشره يوم القيامة أعمى عن الرؤية وعن الحجة.", "isBasmala": false, "translation_en": "But whoever turns away from My Reminder, for him is a confined life. And We will raise him on the Day of Resurrection blind.\"", "translation_id": "Dan barangsiapa berpaling dari peringatan-Ku, maka sesungguhnya baginya penghidupan yang sempit, dan Kami akan menghimpunkannya pada hari kiamat dalam keadaan buta\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 125, "text": "قَالَ رَبِّ لِمَ حَشَرۡتَنِیۤ أَعۡمَىٰ وَقَدۡ كُنتُ بَصِیرࣰا ۝١٢٥", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "قال المعرِض عن ذكر الله: ربِّ لِمَ حَشَرْتني أعمى، وقد كنت بصيرًا في الدنيا؟", "isBasmala": false, "translation_en": "He will say, \"My Lord, why did You raise me blind, though I was seeing?\"", "translation_id": "Berkatalah ia: \"Ya Tuhanku, mengapa Engkau menghimpunkan aku dalam keadaan buta, padahal aku dahulunya adalah seorang yang melihat?\"", "manzil": 4, "manzil_display": ""}], "321": [{"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 126, "text": "قَالَ كَذَ ٰلِكَ أَتَتۡكَ ءَایَـٰتُنَا فَنَسِیتَهَاۖ وَكَذَ ٰلِكَ ٱلۡیَوۡمَ تُنسَىٰ ۝١٢٦", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "قال الله تعالى له: حشرتك أعمى؛ لأنك أتتك آياتي البينات، فأعرضت عنها، ولم تؤمن بها، وكما تركتَها في الدنيا فكذلك اليوم تُترك في النار.", "isBasmala": false, "translation_en": "He will say, \"Just as Our revelations came to you, and you forgot them, today you will be forgotten.\"", "translation_id": "Allah berfirman: \"Demikianlah, telah datang kepadamu ayat-ayat Kami, maka kamu melupakannya, dan begitu (pula) pada hari ini kamupun dilupakan\".", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 127, "text": "وَكَذَ ٰلِكَ نَجۡزِی مَنۡ أَسۡرَفَ وَلَمۡ یُؤۡمِنۢ بِـَٔایَـٰتِ رَبِّهِۦۚ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَشَدُّ وَأَبۡقَىٰۤ ۝١٢٧", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "وهكذا نعاقب مَن أسرف على نفسه فعصى ربه، ولم يؤمن بآياته بعقوبات في الدنيا، ولَعذاب الآخرة المعدُّ لهم أشد ألمًا وأدوم وأثبت؛ لأنه لا ينقطع ولا ينقضي.", "isBasmala": false, "translation_en": "Thus We recompense him who transgresses and does not believe in the revelations of his Lord. The punishment of the Hereafter is more severe, and more lasting.", "translation_id": "Dan demikianlah Kami membalas orang yang melampaui batas dan tidak percaya kepada ayat-ayat Tuhannya. Dan sesungguhnya azab di akhirat itu lebih berat dan lebih kekal.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 128, "text": "أَفَلَمۡ یَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ یَمۡشُونَ فِی مَسَـٰكِنِهِمۡۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّأُو۟لِی ٱلنُّهَىٰ ۝١٢٨", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "أفلم يدل قومك - أيها الرسول - على طريق الرشاد كثرة مَن أهلكنا من الأمم المكذبة قبلهم وهم يمشون في ديارهم، ويرون آثار هلاكهم؟ إن في كثرة تلك الأمم وآثار عذابهم لَعبرًا وعظاتٍ لأهل العقول الواعية.", "isBasmala": false, "translation_en": "Is it not instructive to them, how many generations before them We destroyed, in whose settlements they walk? Surely in that are signs for people of understanding.", "translation_id": "Maka tidakkah menjadi petunjuk bagi mereka (kaum musyrikin) berapa banyaknya Kami membinasakan umat-umat sebelum mereka, padahal mereka berjalan (di bekas-bekas) tempat tinggal umat-umat itu? Sesungguhnya pada yang demikian itu terdapat tanda-tanda bagi orang yang berakal.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 129, "text": "وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَكَانَ لِزَامࣰا وَأَجَلࣱ مُّسَمࣰّى ۝١٢٩", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "ولولا كلمة سبقت من ربك وأجل مسمى عنده للازمهم الهلاك عاجلا، لأنهم يستحقونه؛ بسبب كفرهم.", "isBasmala": false, "translation_en": "Were it not for a word that issued from your Lord, the inevitable would have happened, but there is an appointed term.", "translation_id": "Dan sekiranya tidak ada suatu ketetapan dari Allah yang telah terdahulu atau tidak ada ajal yang telah ditentukan, pasti (azab itu) menimpa mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 130, "text": "فَٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ غُرُوبِهَاۖ وَمِنۡ ءَانَاۤىِٕ ٱلَّیۡلِ فَسَبِّحۡ وَأَطۡرَافَ ٱلنَّهَارِ لَعَلَّكَ تَرۡضَىٰ ۝١٣٠", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "فاصبر - أيها الرسول - على ما يقوله المكذبون بك من أوصاف وأباطيل، وسبِّح بحمد ربك في صلاة الفجر قبل طلوع الشمس، وصلاة العصر قبل غروبها، وصلاة العشاء في ساعات الليل، وصلاة الظهر والمغرب أطراف النهار؛ كي تثاب على هذه الأعمال بما تَرْضى به.", "isBasmala": false, "translation_en": "So bear patiently what they say, and celebrate the praises of your Lord before the rising of the sun, and before its setting. And during the hours of the night glorify Him, and at the borders of the day, that you may be satisfied.", "translation_id": "Maka sabarlah kamu atas apa yang mereka katakan, dan bertasbihlah dengan memuji Tuhanmu, sebelum terbit matahari dan sebelum terbenamnya dan bertasbih pulalah pada waktu-waktu di malam hari dan pada waktu-waktu di siang hari, supaya kamu merasa senang,", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 131, "text": "وَلَا تَمُدَّنَّ عَیۡنَیۡكَ إِلَىٰ مَا مَتَّعۡنَا بِهِۦۤ أَزۡوَ ٰجࣰا مِّنۡهُمۡ زَهۡرَةَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا لِنَفۡتِنَهُمۡ فِیهِۚ وَرِزۡقُ رَبِّكَ خَیۡرࣱ وَأَبۡقَىٰ ۝١٣١", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "ولا تنظر إلى ما مَتَّعْنا به هؤلاء المشركين وأمثالهم من أنواع المتع، فإنها زينة زائلة في هذه الحياة الدنيا، متعناهم بها؛ لنبتليهم بها، ورزق ربك وثوابه خير لك مما متعناهم به وأدوم؛ حيث لا انقطاع له ولا نفاد.", "isBasmala": false, "translation_en": "And do not extend your glance towards what We have given some classes of them to enjoy-the splendor of the life of this world-that We may test them thereby. Your Lord's provision is better, and more lasting.", "translation_id": "Dan janganlah kamu tujukan kedua matamu kepada apa yang telah Kami berikan kepada golongan-golongan dari mereka, sebagai bunga kehidupan dunia untuk Kami cobai mereka dengannya. Dan karunia Tuhan kamu adalah lebih baik dan lebih kekal.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 132, "text": "وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَیۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقࣰاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَـٰقِبَةُ لِلتَّقۡوَىٰ ۝١٣٢", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "وَأْمُرْ - أيها النبي - أهلك بالصلاة، واصطبر على أدائها، لا نسألك مالا، نحن نرزقك ونعطيك. والعاقبة الصالحة في الدنيا والآخرة لأهل التقوى.", "isBasmala": false, "translation_en": "And exhort your people to pray, and patiently adhere to it. We ask of you no sustenance, but it is We who sustain you. The good ending is that for righteousness.", "translation_id": "Dan perintahkanlah kepada keluargamu mendirikan shalat dan bersabarlah kamu dalam mengerjakannya. Kami tidak meminta rezeki kepadamu, Kamilah yang memberi rezeki kepadamu. Dan akibat (yang baik) itu adalah bagi orang yang bertakwa.", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 133, "text": "وَقَالُوا۟ لَوۡلَا یَأۡتِینَا بِـَٔایَةࣲ مِّن رَّبِّهِۦۤۚ أَوَ لَمۡ تَأۡتِهِم بَیِّنَةُ مَا فِی ٱلصُّحُفِ ٱلۡأُولَىٰ ۝١٣٣", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "وقال مكذبوك - أيها الرسول -: هلا تأتينا بعلامة من ربك تدلُّ على صدقك، أولم يأتهم هذا القرآن المصدق لما في الكتب السابقة من الحق؟", "isBasmala": false, "translation_en": "And they say, \"Why does he not bring us a miracle from his Lord?\" Were they not given enough miracles in the former scriptures?", "translation_id": "Dan mereka berkata: \"Mengapa ia tidak membawa bukti kepada kami dari Tuhannya?\" Dan apakah belum datang kepada mereka bukti yang nyata dari apa yang tersebut di dalam kitab-kitab yang dahulu?", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 134, "text": "وَلَوۡ أَنَّاۤ أَهۡلَكۡنَـٰهُم بِعَذَابࣲ مِّن قَبۡلِهِۦ لَقَالُوا۟ رَبَّنَا لَوۡلَاۤ أَرۡسَلۡتَ إِلَیۡنَا رَسُولࣰا فَنَتَّبِعَ ءَایَـٰتِكَ مِن قَبۡلِ أَن نَّذِلَّ وَنَخۡزَىٰ ۝١٣٤", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "ولو أنَّا أهلكنا هؤلاء المكذبين بعذاب من قبل أن نرسل إليهم رسولا وننزل عليهم كتابًا لقالوا: ربنا هلا أرسلت إلينا رسولا من عندك، فنصدقه، ونتبع آياتك وشرعك، مِن قبل أن نَذلَّ ونَخزى بعذابك.", "isBasmala": false, "translation_en": "Had We destroyed them with a punishment before him, they would have said, \"Our Lord, if only You had sent us a messenger, we would have followed Your revelations before we were humiliated and disgraced.\"", "translation_id": "Dan sekiranya Kami binasakan mereka dengan suatu azab sebelum Al Quran itu (diturunkan), tentulah mereka berkata: \"Ya Tuhan kami, mengapa tidak Engkau utus seorang rasul kepada kami, lalu kami mengikuti ayat-ayat Engkau sebelum kami menjadi hina dan rendah?\"", "manzil": 4, "manzil_display": ""}, {"sura": 20, "sura_name": "طه", "revelation": "Makkiyah", "aya": 135, "text": "قُلۡ كُلࣱّ مُّتَرَبِّصࣱ فَتَرَبَّصُوا۟ۖ فَسَتَعۡلَمُونَ مَنۡ أَصۡحَـٰبُ ٱلصِّرَ ٰطِ ٱلسَّوِیِّ وَمَنِ ٱهۡتَدَىٰ ۝١٣٥", "juz": 16, "hizb": "(*¾ ح 32*)", "tafsir": "قل - أيها الرسول - لهؤلاء المشركين بالله: كل منا ومنكم منتظر دوائر الزمان، ولمن يكون النصر والفلاح، فانتظروا، فستعلمون: مَن أهل الطريق المستقيم، ومَن المهتدي للحق منا ومنكم؟", "isBasmala": false, "translation_en": "Say, \"Everybody is waiting, so wait. You will know who the people of the straight path are, and who is rightly-guided.", "translation_id": "Katakanlah: \"Masing-masing (kita) menanti, maka nantikanlah oleh kamu sekalian! Maka kamu kelak akan mengetahui, siapa yang menempuh jalan yang lurus dan siapa yang telah mendapat petunjuk\".", "manzil": 4, "manzil_display": ""}], "322": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 17, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 1, "text": "۞ ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِی غَفۡلَةࣲ مُّعۡرِضُونَ ۝١", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "دنا وقت حساب الناس على ما قدَّموا من عمل، ومع ذلك فالكفار يعيشون لاهين عن هذه الحقيقة، معرضين عن هذا الإنذار.", "isBasmala": false, "translation_en": "Mankind's reckoning has drawn near, but they turn away heedlessly.", "translation_id": "Telah dekat kepada manusia hari menghisab segala amalan mereka, sedang mereka berada dalam kelalaian lagi berpaling (daripadanya).", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 2, "text": "مَا یَأۡتِیهِم مِّن ذِكۡرࣲ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ یَلۡعَبُونَ ۝٢", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "ما من شيء ينزل من القرآن يتلى عليهم مجدِّدًا لهم التذكير، إلا كان سماعهم له سماع لعب واستهزاء.", "isBasmala": false, "translation_en": "No fresh reminder comes to them from their Lord, but they listen to it playfully.", "translation_id": "Tidak datang kepada mereka suatu ayat Al Quran pun yang baru (di-turunkan) dari Tuhan mereka, melainkan mereka mendengarnya, sedang mereka bermain-main,", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 3, "text": "لَاهِیَةࣰ قُلُوبُهُمۡۗ وَأَسَرُّوا۟ ٱلنَّجۡوَى ٱلَّذِینَ ظَلَمُوا۟ هَلۡ هَـٰذَاۤ إِلَّا بَشَرࣱ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ ۝٣", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "قلوبهم غافلة عن القرآن الكريم، مشغولة بأباطيل الدنيا وشهواتها، لا يعقلون ما فيه. بل إن الظالمين من قريش اجتمعوا على أمر خَفِيٍّ: وهو إشاعة ما يصدُّون به الناس عن الإيمان بمحمد صلى الله عليه وسلم من أنه بشر مثلهم، لا يختلف عنهم في شيء، وأن ما جاء به من القرآن سحر، فكيف تجيئون إليه وتتبعونه، وأنتم تبصرون أنه بشر مثلكم؟", "isBasmala": false, "translation_en": "Their hearts distracted, the wrongdoers confer secretly, \"Is this anything but a mortal like you? Will you take to sorcery, with open-eyes?\"", "translation_id": "(lagi) hati mereka dalam keadaan lalai. Dan mereka yang zalim itu merahasiakan pembicaraan mereka: \"Orang ini tidak lain hanyalah seorang manusia (jua) seperti kamu, maka apakah kamu menerima sihir itu, padahal kamu menyaksikannya?\"", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 4, "text": "قَالَ رَبِّی یَعۡلَمُ ٱلۡقَوۡلَ فِی ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٤", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "رد النبي صلى الله عليه وسلم الأمرَ إلى ربه سبحانه وتعالى فقال: ربي يعلم القول في السماء والأرض، ويعلم ما أسررتموه من حديثكم، وهو السميع لأقوالكم، العليم بأحوالكم. وفي هذا تهديد لهم ووعيد.", "isBasmala": false, "translation_en": "He said, \"My Lord knows what is said in the heaven and the earth; and He is the Hearer, the Knower.\"", "translation_id": "Berkatalah Muhammad (kepada mereka): \"Tuhanku mengetahui semua perkataan di langit dan di bumi dan Dialah Yang Maha Mendengar lagi Maha Mengetahui\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 5, "text": "بَلۡ قَالُوۤا۟ أَضۡغَـٰثُ أَحۡلَـٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرࣱ فَلۡیَأۡتِنَا بِـَٔایَةࣲ كَمَاۤ أُرۡسِلَ ٱلۡأَوَّلُونَ ۝٥", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "بل جحد الكفار القرآن فمِن قائل: إنه أخلاط أحلام لا حقيقة لها، ومن قائل: إنه اختلاق وكذب وليس وحيًا، ومن قائل: إن محمدًا شاعر، وهذا الذي جاء به شعر، وإن أراد منا أن نصدِّقه فليجئنا بمعجزة محسوسة كناقة صالح، وآيات موسى وعيسى، وما جاء به الرسل من قبله.", "isBasmala": false, "translation_en": "And they said, \"A jumble of dreams,\" and, \"He made it up,\" and, \"He is a poet,\" \"let him bring us a sign, like those sent to the ancients.\"", "translation_id": "Bahkan mereka berkata (pula): \"(Al Quran itu adalah) mimpi-mimpi yang kalut, malah diada-adakannya, bahkan dia sendiri seorang penyair, maka hendaknya ia mendatangkan kepada kita suatu mukjizat, sebagai-mana rasul-rasul yang telah lalu di-utus\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 6, "text": "مَاۤ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡیَةٍ أَهۡلَكۡنَـٰهَاۤۖ أَفَهُمۡ یُؤۡمِنُونَ ۝٦", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "ما آمنت قبل كفار \"مكة\" من قرية طلب أهلها المعجزات مِن رسولهم وتحققت، بل كذَّبوا، فأهلكناهم، أفيؤمن كفار\"مكة\" إذا تحققت المعجزات التي طلبوها؟ كلا إنهم لا يؤمنون.", "isBasmala": false, "translation_en": "None of the towns We destroyed before them had believed. Will they, then, believe?", "translation_id": "Tidak ada (penduduk) suatu negeripun yang beriman yang Kami telah membinasakannya sebeIum mereka; maka apakah mereka akan beriman?", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 7, "text": "وَمَاۤ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالࣰا نُّوحِیۤ إِلَیۡهِمۡۖ فَسۡـَٔلُوۤا۟ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ ۝٧", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "وما أرسلنا قبلك - أيها الرسول - إلا رجالا من البشر نوحي إليهم، ولم نرسل ملائكة، فاسألوا - يا كفار \"مكة\" - أهل العلم بالكتب المنزلة السابقة، إن كنتم تجهلون ذلك.", "isBasmala": false, "translation_en": "We did not send before you except men, whom We inspired. Ask the people of knowledge, if you do not know.", "translation_id": "Kami tiada mengutus rasul rasul sebelum kamu (Muhammad), melainkan beberapa orang-laki-laki yang Kami beri wahyu kepada mereka, maka tanyakanlah olehmu kepada orang-orang yang berilmu, jika kamu tiada mengetahui.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 8, "text": "وَمَا جَعَلۡنَـٰهُمۡ جَسَدࣰا لَّا یَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَـٰلِدِینَ ۝٨", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "وما جعلنا أولئك المرسلين قبلك خارجين عن طباع البشر لا يحتاجون إلى طعام وشراب، وما كانوا خالدين لا يموتون.", "isBasmala": false, "translation_en": "We did not make them mere bodies that ate no food, nor were they immortal.", "translation_id": "Dan tidaklah Kami jadikan mereka tubuh-tubuh yang tiada memakan makanan, dan tidak (pula) mereka itu orang-orang yang kekal.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 9, "text": "ثُمَّ صَدَقۡنَـٰهُمُ ٱلۡوَعۡدَ فَأَنجَیۡنَـٰهُمۡ وَمَن نَّشَاۤءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِینَ ۝٩", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "ثم أنجزنا للأنبياء وأتباعم ما وعدناهم به من النصر والنجاة، وأهلَكْنا المسرفين على أنفسهم بكفرهم بربهم.", "isBasmala": false, "translation_en": "Then We fulfilled Our promise to them, and We saved them together with whomever We willed, and We destroyed the extravagant.", "translation_id": "Kemudian Kami tepati janji (yang telah Kami janjikan) kepada mereka. Maka Kami selamatkan mereka dan orang-orang yang Kami kehendaki dan Kami binasakan orang-orang yang melampaui batas.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 10, "text": "لَقَدۡ أَنزَلۡنَاۤ إِلَیۡكُمۡ كِتَـٰبࣰا فِیهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ ۝١٠", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "لقد أنزلنا إليكم هذا القرآن، فيه عزُّكم وشرفكم في الدنيا والآخرة إن تذكرتم به، أفلا تعقلون ما فَضَّلْتكم به على غيركم؟", "isBasmala": false, "translation_en": "We have sent down to you a Book, containing your message. Do you not understand?", "translation_id": "Sesungguhnya telah Kami turunkan kepada kamu sebuah kitab yang di dalamnya terdapat sebab-sebab kemuliaan bagimu. Maka apakah kamu tiada memahaminya?", "manzil": 4, "manzil_display": ""}], "323": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 11, "text": "وَكَمۡ قَصَمۡنَا مِن قَرۡیَةࣲ كَانَتۡ ظَالِمَةࣰ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِینَ ۝١١", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "وكثير من القرى كان أهلها ظالمين بكفرهم بما جاءتهم به رسلهم، فأهلكناهم بعذاب أبادهم جميعًا، وأوجدنا بعدهم قومًا آخرين سواهم.", "isBasmala": false, "translation_en": "How many a guilty town have We crushed, and established thereafter another people?", "translation_id": "Dan berapa banyaknya (penduduk) negeri yang zalim yang teIah Kami binasakan, dan Kami adakan sesudah mereka itu kaum yang lain (sebagai penggantinya).", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 12, "text": "فَلَمَّاۤ أَحَسُّوا۟ بَأۡسَنَاۤ إِذَا هُم مِّنۡهَا یَرۡكُضُونَ ۝١٢", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "فلما رأى هؤلاء الظالمون عذابنا الشديد نازلا بهم، وشاهدوا بوادره، إذا هم من قريتهم يسرعون هاربين.", "isBasmala": false, "translation_en": "Then, when they sensed Our might, they started running away from it.", "translation_id": "Maka tatkala mereka merasakan azab Kami, tiba-tiba mereka melarikan diri dari negerinya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 13, "text": "لَا تَرۡكُضُوا۟ وَٱرۡجِعُوۤا۟ إِلَىٰ مَاۤ أُتۡرِفۡتُمۡ فِیهِ وَمَسَـٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ ۝١٣", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "فنودوا في هذه الحال: لا تهربوا وارجعوا إلى لذاتكم وتنعُّمكم في دنياكم الملهية ومساكنكم المشيَّدة، لعلكم تُسألون من دنياكم شيئًا، وذلك على وجه السخرية والاستهزاء بهم.", "isBasmala": false, "translation_en": "Do not run, but come back to your luxuries, and to your homes, that you may be questioned.", "translation_id": "Janganlah kamu lari tergesa-gesa; kembalilah kamu kepada nikmat yang telah kamu rasakan dan kepada tempat-tempat kediamanmu (yang baik), supaya kamu ditanya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 14, "text": "قَالُوا۟ یَـٰوَیۡلَنَاۤ إِنَّا كُنَّا ظَـٰلِمِینَ ۝١٤", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "فلم يكن لهم من جواب إلا اعترافهم بجرمهم وقولهم: يا هلاكنا، فقد ظلمنا أنفسنا بكفرنا.", "isBasmala": false, "translation_en": "They said, \"Woe to us; we were unfair.\"", "translation_id": "Mereka berkata: \"Aduhai, celaka kami, sesungguhnya kami adalah orang-orang yang zaIim\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 15, "text": "فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَـٰهُمۡ حَصِیدًا خَـٰمِدِینَ ۝١٥", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "فما زالت تلك المقالة - وهي الدعاء على أنفسهم بالهلاك، والاعتراف بالظلم - دَعْوَتَهم يرددونها حتى جعلناهم كالزرع المحصود، خامدين لا حياة فيهم. فاحذروا - أيها المخاطبون - أن تستمروا على تكذيب محمد صلى الله عليه وسلم، فيحلُّ بكم ما حَلَّ بالأمم قبلكم.", "isBasmala": false, "translation_en": "This continued to be their cry, until We made them silent ashes.", "translation_id": "Maka tetaplah demikian keluhan mereka, sehingga Kami jadikan mereka sebagai tanaman yang telah dituai, yang tidak dapat hidup lagi.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 16, "text": "وَمَا خَلَقۡنَا ٱلسَّمَاۤءَ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا لَـٰعِبِینَ ۝١٦", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "وما خلقنا السماء والأرض وما بينهما عبثًا وباطلا بل لإقامة الحجة عليكم - أيها الناس - ولتعتبروا بذلك كله، فتعلموا أن الذي خلق ذلك لا يشبهه شيء، ولا تصلح العبادة إلا له.", "isBasmala": false, "translation_en": "We did not create the sky and the earth and what is between them for amusement.", "translation_id": "Dan tidaklah Kami ciptakan Iangit dan bumi dan segala yang ada di antara keduanya dengan bermain-main.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 17, "text": "لَوۡ أَرَدۡنَاۤ أَن نَّتَّخِذَ لَهۡوࣰا لَّٱتَّخَذۡنَـٰهُ مِن لَّدُنَّاۤ إِن كُنَّا فَـٰعِلِینَ ۝١٧", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "لو أردنا أن نتخذ لهوًا من الولد أو الصاحبة لاتخذناه من عندنا لا من عندكم، ما كنا فاعلين ذلك؛ لاستحالة أن يكون لنا ولد أو صاحبة.", "isBasmala": false, "translation_en": "If We wanted amusement, We could have found it within Us, were We to do so.", "translation_id": "Sekiranya Kami hendak membuat sesuatu permainan, (isteri dan anak), tentulah Kami membuatnya dari sisi Kami. Jika Kami menghendaki berbuat demikian, (tentulah Kami telah melakukannya).", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 18, "text": "بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَـٰطِلِ فَیَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقࣱۚ وَلَكُمُ ٱلۡوَیۡلُ مِمَّا تَصِفُونَ ۝١٨", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "بل نقذف بالحق ونبيِّنه، فيدحض الباطل، فإذا هو ذاهب مضمحل. ولكم العذاب في الآخرة - أيها المشركون - مِن وَصْفكم ربكم بغير صفته اللائقة به.", "isBasmala": false, "translation_en": "In fact, We hurl the truth against falsehood, and it crushes it, so it vanishes. Woe unto you, for what you describe.", "translation_id": "Sebenarya Kami melontarkan yang hak kepada yang batil lalu yang hak itu menghancurkannya, maka dengan serta merta yang batil itu lenyap. Dan kecelakaanlah bagimu disebabkan kamu mensifati (Allah dengan sifat-sifat yang tidak layak bagi-Nya).", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 19, "text": "وَلَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا یَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا یَسۡتَحۡسِرُونَ ۝١٩", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "ولله سبحانه كل مَن في السموات والأرض، والذين عنده من الملائكة لا يأنَفُون عن عبادته ولا يملُّونها. فكيف يجوز أن يشرك به ما هو عبده وخلقه؟", "isBasmala": false, "translation_en": "To Him belongs everyone in the heavens and the earth. Those near Him are not too proud to worship Him, nor do they waver.", "translation_id": "Dan kepunyaan-Nya-lah segala yang di langit dan di bumi. Dan malaikat-malaikat yang di sisi-Nya, mereka tiada mempunyai rasa angkuh untuk menyembah-Nya dan tiada (pula) merasa letih.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 20, "text": "یُسَبِّحُونَ ٱلَّیۡلَ وَٱلنَّهَارَ لَا یَفۡتُرُونَ ۝٢٠", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "يذكرون الله وينزِّهونه دائمًا، لا يضْعُفون ولا يسأمون.", "isBasmala": false, "translation_en": "They praise night and day, without ever tiring.", "translation_id": "Mereka selalu bertasbih malam dan siang tiada henti-hentinya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 21, "text": "أَمِ ٱتَّخَذُوۤا۟ ءَالِهَةࣰ مِّنَ ٱلۡأَرۡضِ هُمۡ یُنشِرُونَ ۝٢١", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "كيف يصح للمشركين أن يتخذوا آلهة عاجزة من الأرض لا تقدر على إحياء الموتى؟", "isBasmala": false, "translation_en": "Or have they taken to themselves gods from the earth who resurrect?", "translation_id": "Apakah mereka mengambil tuhan-tuhan dari bumi, yang dapat menghidupkan (orang-orang mati)?", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 22, "text": "لَوۡ كَانَ فِیهِمَاۤ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَـٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا یَصِفُونَ ۝٢٢", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "لو كان في السموات والأرض آلهة غير الله سبحانه وتعالى تدبر شؤونهما، لاختلَّ نظامهما، فتنزَّه الله رب العرش، وتقدَّس عَمَّا يصفه الجاحدون الكافرون، من الكذب والافتراء وكل نقص.", "isBasmala": false, "translation_en": "If there were in them gods other than God, they would have gone to ruin. So glory be to God, Lord of the Throne, beyond what they allege.", "translation_id": "Sekiranya ada di langit dan di bumi tuhan-tuhan selain Allah, tentulah keduanya itu telah rusak binasa. Maka Maha Suci Allah yang mempunyai 'Arsy daripada apa yang mereka sifatkan.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 23, "text": "لَا یُسۡـَٔلُ عَمَّا یَفۡعَلُ وَهُمۡ یُسۡـَٔلُونَ ۝٢٣", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "إن من دلائل تفرُّده سبحانه بالخلق والعبادة أنه لا يُسأل عن قضائه في خلقه، وجميع خلقه يُسألون عن أفعالهم.", "isBasmala": false, "translation_en": "He will not be questioned about what He does, but they will be questioned.", "translation_id": "Dia tidak ditanya tentang apa yang diperbuat-Nya dan merekalah yang akan ditanyai.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 24, "text": "أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦۤ ءَالِهَةࣰۖ قُلۡ هَاتُوا۟ بُرۡهَـٰنَكُمۡۖ هَـٰذَا ذِكۡرُ مَن مَّعِیَ وَذِكۡرُ مَن قَبۡلِیۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ ۝٢٤", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "هل اتخذ هؤلاء المشركون مِن غير الله آلهة تنفع وتضر وتحيي وتميت؟ قل - أيها الرسول - لهم: هاتوا ما لديكم من البرهان على ما اتخذتموه آلهة، فليس في القرآن الذي جئتُ به ولا في الكتب السابقة دليل على ما ذهبتم إليه، وما أشركوا إلا جهلا وتقليدًا، فهم معرضون عن الحق منكرون له.", "isBasmala": false, "translation_en": "Or have they taken, besides Him, other gods? Say, \"Bring your proof. This is a message for those with me, and a message of those before me.\" But most of them do not know the truth, so they turn away.", "translation_id": "Apakah mereka mengambil tuhan-tuhan selain-Nya? Katakanlah: \"Unjukkanlah hujjahmu! (Al Quran) ini adalah peringatan bagi orang-orang yang bersamaku, dan peringatan bagi orang-orang yang sebelumku\". Sebenarnya kebanyakan mereka tiada mengetahui yang hak, karena itu mereka berpaling.", "manzil": 4, "manzil_display": ""}], "324": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 25, "text": "وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِیۤ إِلَیۡهِ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّاۤ أَنَا۠ فَٱعۡبُدُونِ ۝٢٥", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "وما أرسلنا من قبلك - أيها الرسول - من رسول إلا نوحي إليه أنه لا معبود بحق إلا الله، فأخْلصوا العبادة له وحده.", "isBasmala": false, "translation_en": "We never sent a messenger before you without inspiring him that: \"There is no god but I, so worship Me.\"", "translation_id": "Dan Kami tidak mengutus seorang rasulpun sebelum kamu melainkan Kami wahyukan kepadanya: \"Bahwasanya tidak ada Tuhan (yang hak) melainkan Aku, maka sembahlah olehmu sekalian akan Aku\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 26, "text": "وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحۡمَـٰنُ وَلَدࣰاۗ سُبۡحَـٰنَهُۥۚ بَلۡ عِبَادࣱ مُّكۡرَمُونَ ۝٢٦", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "وقال المشركون: اتخذ الرحمن ولدًا بزعمهم أن الملائكة بنات الله. تنزَّه الله عن ذلك؛ فالملائكة عباد الله مقربون مخصصون بالفضائل، وهم في حسن طاعتهم لا يتكلمون إلا بما يأمرهم به ربهم، ولا يعملون عملا حتى يأذن لهم.", "isBasmala": false, "translation_en": "And they say, \"The Most Merciful has taken to himself a son.\" Be He glorified; they are but honored servants.", "translation_id": "Dan mereka berkata: \"Tuhan Yang Maha Pemurah telah mengambil (mempunyai) anak\", Maha Suci Allah. Sebenarnya (malaikat-malaikat itu), adalah hamba-hamba yang dimuliakan,", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 27, "text": "لَا یَسۡبِقُونَهُۥ بِٱلۡقَوۡلِ وَهُم بِأَمۡرِهِۦ یَعۡمَلُونَ ۝٢٧", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "وقال المشركون: اتخذ الرحمن ولدًا بزعمهم أن الملائكة بنات الله. تنزَّه الله عن ذلك؛ فالملائكة عباد الله مقربون مخصصون بالفضائل، وهم في حسن طاعتهم لا يتكلمون إلا بما يأمرهم به ربهم، ولا يعملون عملا حتى يأذن لهم.", "isBasmala": false, "translation_en": "They never speak before He has spoken, and they only act on His command.", "translation_id": "mereka itu tidak mendahului-Nya dengan perkataan dan mereka mengerjakan perintah-perintah-Nya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 28, "text": "یَعۡلَمُ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡ وَلَا یَشۡفَعُونَ إِلَّا لِمَنِ ٱرۡتَضَىٰ وَهُم مِّنۡ خَشۡیَتِهِۦ مُشۡفِقُونَ ۝٢٨", "juz": 17, "hizb": "(* ح 33*)", "tafsir": "وما من أعمال الملائكة عمل سابق أو لاحق إلا يعلمه الله سبحانه وتعالى، ويحصيه عليهم، ولا يتقدمون بالشفاعة إلا لمن ارتضى الله شفاعتهم له، وهم من خوف الله حذرون من مخالفة أمره ونهيه.", "isBasmala": false, "translation_en": "He knows what is before them, and what is behind them; and they do not intercede except for him whom He approves; and they tremble in awe of Him.", "translation_id": "Allah mengetahui segala sesuatu yang dihadapan mereka (malaikat) dan yang di belakang mereka, dan mereka tiada memberi syafa'at melainkan kepada orang yang diridhai Allah, dan mereka itu selalu berhati-hati karena takut kepada-Nya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 29, "text": "۞ وَمَن یَقُلۡ مِنۡهُمۡ إِنِّیۤ إِلَـٰهࣱ مِّن دُونِهِۦ فَذَ ٰلِكَ نَجۡزِیهِ جَهَنَّمَۚ كَذَ ٰلِكَ نَجۡزِی ٱلظَّـٰلِمِینَ ۝٢٩", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "ومن يدَّع من الملائكة أنه إله مع الله - على سبيل الفرض - فجزاؤه جهنم، مثل ذلك الجزاء نجزي كل ظالم مشرك.", "isBasmala": false, "translation_en": "And whoever of them says, \"I am a god besides Him,\" We will reward him with Hell. Thus We reward the wrongdoers.", "translation_id": "Dan barangsiapa di antara mereka, mengatakan: \"Sesungguhnya Aku adalah tuhan selain daripada Allah\", maka orang itu Kami beri balasan dengan Jahannam, demikian Kami memberikan pembalasan kepada orang-orang zalim.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 30, "text": "أَوَ لَمۡ یَرَ ٱلَّذِینَ كَفَرُوۤا۟ أَنَّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ كَانَتَا رَتۡقࣰا فَفَتَقۡنَـٰهُمَاۖ وَجَعَلۡنَا مِنَ ٱلۡمَاۤءِ كُلَّ شَیۡءٍ حَیٍّۚ أَفَلَا یُؤۡمِنُونَ ۝٣٠", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "أولم يعلم هؤلاء الذين كفروا أن السموات والأرض كانتا ملتصقتين لا فاصل بينهما، فلا مطر من السماء ولا نبات من الأرض، ففصلناهما بقدرتنا، وأنزلنا المطر من السماء، وأخرجنا النبات من الأرض، وجعلنا من الماء كل شيء حي، أفلا يؤمن هؤلاء الجاحدون فيصدقوا بما يشاهدونه، ويخصُّوا الله بالعبادة؟", "isBasmala": false, "translation_en": "Do the disbelievers not see that the heavens and the earth were one mass, and We tore them apart? And We made from water every living thing. Will they not believe?", "translation_id": "Dan apakah orang-orang yang kafir tidak mengetahui bahwasanya langit dan bumi itu keduanya dahulu adalah suatu yang padu, kemudian Kami pisahkan antara keduanya. Dan dari air Kami jadikan segala sesuatu yang hidup. Maka mengapakah mereka tiada juga beriman?", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 31, "text": "وَجَعَلۡنَا فِی ٱلۡأَرۡضِ رَوَ ٰسِیَ أَن تَمِیدَ بِهِمۡ وَجَعَلۡنَا فِیهَا فِجَاجࣰا سُبُلࣰا لَّعَلَّهُمۡ یَهۡتَدُونَ ۝٣١", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "وخلقنا في الأرض جبالا تثبتها حتى لا تضطرب، وجعلنا فيها طرقًا واسعة؛ رجاء اهتداء الخلق إلى معايشهم، وتوحيد خالقهم.", "isBasmala": false, "translation_en": "And We placed on earth stabilizers, lest it sways with them, and We placed therein signposts and passages, that they may be guided.", "translation_id": "Dan telah Kami jadikan di bumi ini gunung-gunung yang kokoh supaya bumi itu (tidak) goncang bersama mereka dan telah Kami jadikan (pula) di bumi itu jalan-jalan yang luas, agar mereka mendapat petunjuk.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 32, "text": "وَجَعَلۡنَا ٱلسَّمَاۤءَ سَقۡفࣰا مَّحۡفُوظࣰاۖ وَهُمۡ عَنۡ ءَایَـٰتِهَا مُعۡرِضُونَ ۝٣٢", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "وجعلنا السماء سقفًا للأرض لا يرفعها عماد، وهي محفوظة لا تسقط، ولا تخترقها الشياطين، والكفار عن الاعتبار بآيات السماء (الشمس والقمر والنجوم)، غافلون لاهون عن التفكير فيها.", "isBasmala": false, "translation_en": "And We made the sky a protected ceiling; yet they turn away from its wonders.", "translation_id": "Dan Kami menjadikan langit itu sebagai atap yang terpelihara, sedang mereka berpaling dari segala tanda-tanda (kekuasaan Allah) yang terdapat padanya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 33, "text": "وَهُوَ ٱلَّذِی خَلَقَ ٱلَّیۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ فِی فَلَكࣲ یَسۡبَحُونَ ۝٣٣", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "والله تعالى هو الذي خلق الليل؛ ليسكن الناس فيه، والنهار؛ ليطلبوا فيه المعايش، وخلق الشمس آية للنهار، والقمر آية للَّيل، ولكل منهما مدار يجري فيه وَيَسْبَح لا يحيد عنه.", "isBasmala": false, "translation_en": "It is He who created the night and the day, and the sun and the moon; each floating in an orbit.", "translation_id": "Dan Dialah yang telah menciptakan malam dan siang, matahari dan bulan. Masing-masing dari keduanya itu beredar di dalam garis edarnya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 34, "text": "وَمَا جَعَلۡنَا لِبَشَرࣲ مِّن قَبۡلِكَ ٱلۡخُلۡدَۖ أَفَإِی۟ن مِّتَّ فَهُمُ ٱلۡخَـٰلِدُونَ ۝٣٤", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "وما جعلنا لبشر من قبلك - أيها الرسول - دوام البقاء في الدنيا، أفإن مت فهم يُؤمِّلون الخلود بعدك؟ لا يكون هذا. وفي هذه الآية دليل على أن الخضر عليه السلام قد مات؛ لأنه بشر.", "isBasmala": false, "translation_en": "We did not grant immortality to any human being before you. Should you die, are they then the immortal?", "translation_id": "Kami tidak menjadikan hidup abadi bagi seorang manusiapun sebelum kamu (Muhammad); maka jikalau kamu mati, apakah mereka akan kekal?", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 35, "text": "كُلُّ نَفۡسࣲ ذَاۤىِٕقَةُ ٱلۡمَوۡتِۗ وَنَبۡلُوكُم بِٱلشَّرِّ وَٱلۡخَیۡرِ فِتۡنَةࣰۖ وَإِلَیۡنَا تُرۡجَعُونَ ۝٣٥", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "كل نفس ذائقة الموت لا محالة مهما عُمِّرت في الدنيا. وما وجودها في الحياة إلا ابتلاء بالتكاليف أمرًا ونهيًا، وبتقلب الأحوال خيرًا وشرًا، ثم المآل والمرجع بعد ذلك إلى الله - وحده - للحساب والجزاء.", "isBasmala": false, "translation_en": "Every soul will taste death. We burden you with adversity and prosperity-a test. And to Us you will be returned.", "translation_id": "Tiap-tiap yang berjiwa akan merasakan mati. Kami akan menguji kamu dengan keburukan dan kebaikan sebagai cobaan (yang sebenar-benarnya). Dan hanya kepada Kamilah kamu dikembalikan.", "manzil": 4, "manzil_display": ""}], "325": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 36, "text": "وَإِذَا رَءَاكَ ٱلَّذِینَ كَفَرُوۤا۟ إِن یَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَـٰذَا ٱلَّذِی یَذۡكُرُ ءَالِهَتَكُمۡ وَهُم بِذِكۡرِ ٱلرَّحۡمَـٰنِ هُمۡ كَـٰفِرُونَ ۝٣٦", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "وإذا رآك الكفار - أيها الرسول - أشاروا إليك ساخرين منك بقول بعضهم لبعض: أهذا الرجل الذي يسبُّ آلهتكم؟ وجحدوا بالرحمن ونعمه، وبما أنزله من القرآن والهدى.", "isBasmala": false, "translation_en": "When those who disbelieve see you, they treat you only with ridicule: \"Is this the one who mentions your gods?\" And they reject the mention of the Merciful.", "translation_id": "Dan apahila orang-orang kafir itu melihat kamu, mereka hanya membuat kamu menjadi olok-olok. (Mereka mengatakan): \"Apakah ini orang yang mencela tuhan-tuhan-mu?\", padahal mereka adaIah orang-orang yang ingkar mengingat Allah Yang Maha Pemurah.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 37, "text": "خُلِقَ ٱلۡإِنسَـٰنُ مِنۡ عَجَلࣲۚ سَأُو۟رِیكُمۡ ءَایَـٰتِی فَلَا تَسۡتَعۡجِلُونِ ۝٣٧", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "خُلق الإنسان عجولا يبادر الأشياء ويستعجل وقوعها. وقد استعجلت قريش العذاب واستبطأته، فأنذرهم الله بأنه سيريهم ما يستعجلونه من العذاب، فلا يسألوا الله تعجيله وسرعته.", "isBasmala": false, "translation_en": "The human being was created of haste. I will show you My signs, so do not seek to rush Me.", "translation_id": "Manusia telah dijadikan (bertabiat) tergesa-gesa. Kelak akan Aku perIihatkan kepadamu tanda-tanda azab-Ku. Maka janganlah kamu minta kepada-Ku mendatangkannya dengan segera.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 38, "text": "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ ۝٣٨", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "ويقول الكفار - مستعجلين العذاب مستهزئين -: متى حصول ما تَعِدُنا به يا محمد، إن كنت أنت ومَن اتبعك من الصادقين؟", "isBasmala": false, "translation_en": "And they say, \"When will this promise come true, if you are truthful?\"", "translation_id": "Mereka berkata: \"Kapankah janji itu akan datang, jika kamu sekaIian adalah orang-orang yang benar?\"", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 39, "text": "لَوۡ یَعۡلَمُ ٱلَّذِینَ كَفَرُوا۟ حِینَ لَا یَكُفُّونَ عَن وُجُوهِهِمُ ٱلنَّارَ وَلَا عَن ظُهُورِهِمۡ وَلَا هُمۡ یُنصَرُونَ ۝٣٩", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "لو يعلم هؤلاء الكفار ما يلاقونه عندما لا يستطيعون أن يدفعوا عن وجوههم وظهورهم النار، ولا يجدون لهم ناصرًا ينصرهم، لما أقاموا على كفرهم، ولما استعجلوا عذابهم.", "isBasmala": false, "translation_en": "If those who disbelieve only knew, when they cannot keep the fire off their faces and off their backs, and they will not be helped.", "translation_id": "Andaikata orang-orang kafir itu mengetahui, waktu (di mana) mereka itu tidak mampu mengelakkan api neraka dari muka mereka dan (tidak pula) dari punggung mereka, sedang mereka (tidak pula) mendapat pertolongan, (tentulah mereka tiada meminta disegerakan).", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 40, "text": "بَلۡ تَأۡتِیهِم بَغۡتَةࣰ فَتَبۡهَتُهُمۡ فَلَا یَسۡتَطِیعُونَ رَدَّهَا وَلَا هُمۡ یُنظَرُونَ ۝٤٠", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "ولسوف تأتيهم الساعة فجأة، فيتحيَّرون عند ذلك، ويخافون خوفًا عظيمًا، ولا يستطيعون دَفْعَ العذاب عن أنفسهم، ولا يُمْهلون لاستدراك توبة واعتذار.", "isBasmala": false, "translation_en": "In fact, it will come upon them suddenly, and bewilder them. They will not be able to repel it, and they will not be reprieved.", "translation_id": "Sebenarnya (azab) itu akan datang kepada mereka dengan sekonyong-konyong lalu membuat mereka menjadi panik, maka mereka tidak sanggup menolaknya dan tidak (pula) mereka diberi tangguh.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 41, "text": "وَلَقَدِ ٱسۡتُهۡزِئَ بِرُسُلࣲ مِّن قَبۡلِكَ فَحَاقَ بِٱلَّذِینَ سَخِرُوا۟ مِنۡهُم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٤١", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "ولقد استهزئ برسل مِن قبلك أيها الرسول، فحلَّ بالذين كانوا يستهزئون العذاب الذي كان مَثار سخريتهم واستهزائهم.", "isBasmala": false, "translation_en": "Messengers before you were also ridiculed, but those who jeered were surrounded by what they had ridiculed.", "translation_id": "Dan sungguh telah diperolok-olokkan beberapa orang rasul sebelum kamu maka turunlah kepada orang yang mencemoohkan rasul-rasul itu azab yang selalu mereka perolok-olokkan.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 42, "text": "قُلۡ مَن یَكۡلَؤُكُم بِٱلَّیۡلِ وَٱلنَّهَارِ مِنَ ٱلرَّحۡمَـٰنِۚ بَلۡ هُمۡ عَن ذِكۡرِ رَبِّهِم مُّعۡرِضُونَ ۝٤٢", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "قل - أيها الرسول - لهؤلاء المستعجلين بالعذاب: لا أحد يحفظكم ويحرسكم في ليلكم أو نهاركم، في نومكم أو يقظتكم، مِن بأس الرحمن إذا نزل بكم. بل هم عن القرآن ومواعظ ربهم لاهون غافلون.", "isBasmala": false, "translation_en": "Say, \"Who guards you against the Merciful by night and by day?\" But they turn away from the mention of their Lord.", "translation_id": "Katakanlah: \"Siapakah yang dapat memelihara kamu di waktu malam dan siang hari dari (azab Allah) Yang Maha Pemurah?\" Sebenarnya mereka adalah orang-orang yang berpaling dari mengingati Tuhan mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 43, "text": "أَمۡ لَهُمۡ ءَالِهَةࣱ تَمۡنَعُهُم مِّن دُونِنَاۚ لَا یَسۡتَطِیعُونَ نَصۡرَ أَنفُسِهِمۡ وَلَا هُم مِّنَّا یُصۡحَبُونَ ۝٤٣", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "أَلَهُمْ آلهة تمنعهم من عذابنا؟ إنَّ آلهتهم لا يستطيعون أن ينصروا أنفسهم، فكيف ينصرون عابديهم؟ وهم منا لا يُجارون.", "isBasmala": false, "translation_en": "Or do they have gods who can defend them against Us? They cannot help themselves, nor will they be protected from Us.", "translation_id": "Atau adakah mereka mempunyai tuhan-tuhan yang dapat memelihara mereka dari (azab) Kami. Tuhan-tuhan itu tidak sanggup menolong diri mereka sendiri dan tidak (pula) mereka dilindungi dari (azab) Kami itu?", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 44, "text": "بَلۡ مَتَّعۡنَا هَـٰۤؤُلَاۤءِ وَءَابَاۤءَهُمۡ حَتَّىٰ طَالَ عَلَیۡهِمُ ٱلۡعُمُرُۗ أَفَلَا یَرَوۡنَ أَنَّا نَأۡتِی ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۤۚ أَفَهُمُ ٱلۡغَـٰلِبُونَ ۝٤٤", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "لقد اغترَّ الكفار وآباؤهم بالإمهال لِمَا رأوه من الأموال والبنين وطول الأعمار، فأقاموا على كفرهم لا يَبْرحونه، وظنوا أنهم لا يُعذَّبون وقد غَفَلوا عن سُنَّة ماضية، فالله ينقص الأرض من جوانبها بما ينزله بالمشركين مِن بأس في كل ناحية ومِن هزيمة، أيكون بوسع كفار \"مكة\" الخروج عن قدرة الله، أو الامتناع من الموت؟", "isBasmala": false, "translation_en": "We have given these enjoyments, and their ancestors, until time grew long upon them. Do they not see how We gradually reduce the land from its extremities? Are they then the victors?", "translation_id": "Sebenarnya Kami telah memberi mereka dan bapak-bapak mereka kenikmatan (hidup di dunia) hingga panjanglah umur mereka. Maka apakah mereka tidak melihat bahwasanya Kami mendatangi negeri (orang kafir), lalu Kami kurangi luasnya dari segala penjurunya. Maka apakah mereka yang menang?", "manzil": 4, "manzil_display": ""}], "326": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 45, "text": "قُلۡ إِنَّمَاۤ أُنذِرُكُم بِٱلۡوَحۡیِۚ وَلَا یَسۡمَعُ ٱلصُّمُّ ٱلدُّعَاۤءَ إِذَا مَا یُنذَرُونَ ۝٤٥", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "قل - أيها الرسول - لمن أُرسلتَ إليهم: ما أُخوِّفكم من العذاب إلا بوحي من الله، وهو القرآن، ولكن الكفار لا يسمعون ما يُلقى إليهم سماع تدبر إذا أُنذِورا، فلا ينتفعون به.", "isBasmala": false, "translation_en": "Say, \"I am warning you through inspiration.\" But the deaf cannot hear the call when they are being warned.", "translation_id": "Katakanlah (hai Muhammad): \"Sesungguhnya aku hanya memberi peringatan kepada kamu sekalian dengan wahyu dan tiadalah orang-orang yang tuli mendengar seruan, apabila mereka diberi peringatan\"", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 46, "text": "وَلَىِٕن مَّسَّتۡهُمۡ نَفۡحَةࣱ مِّنۡ عَذَابِ رَبِّكَ لَیَقُولُنَّ یَـٰوَیۡلَنَاۤ إِنَّا كُنَّا ظَـٰلِمِینَ ۝٤٦", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "لو أصاب الكفارَ نصيب من عذاب الله لعلموا عاقبة تكذيبهم، وقابلوا ذلك بالدعاء على أنفسهم بالهلاك؛ بسبب ظلمهم لأنفسهم بعبادتهم غير الله.", "isBasmala": false, "translation_en": "And when a breath of your Lord's punishment touches them, they say, \"Woe to us, we were truly wicked.\"", "translation_id": "Dan sesungguhnya, jika mereka ditimpa sedikit saja dari azab Tuhan-mu, pastilah mereka berkata: \"Aduhai, celakalah kami, bahwasanya kami adalah orang yang menganiaya diri sendiri\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 47, "text": "وَنَضَعُ ٱلۡمَوَ ٰزِینَ ٱلۡقِسۡطَ لِیَوۡمِ ٱلۡقِیَـٰمَةِ فَلَا تُظۡلَمُ نَفۡسࣱ شَیۡـࣰٔاۖ وَإِن كَانَ مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلٍ أَتَیۡنَا بِهَاۗ وَكَفَىٰ بِنَا حَـٰسِبِینَ ۝٤٧", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "ويضع الله تعالى الميزان العادل للحساب في يوم القيامة، ولا يظلم هؤلاء ولا غيرهم شيئًا، وإن كان هذا العمل قدْرَ ذرة مِن خير أو شر اعتبرت في حساب صاحبها. وكفى بالله محصيًا أعمال عباده، ومجازيًا لهم عليها.", "isBasmala": false, "translation_en": "We will set up the scales of justice for the Day of Resurrection, so that no soul will suffer the least injustice. And even if it be the weight of a mustard-seed, We will bring it up. Sufficient are We as Reckoners.", "translation_id": "Kami akan memasang timbangan yang tepat pada hari kiamat, maka tiadalah dirugikan seseorang barang sedikitpun. Dan jika (amalan itu) hanya seberat biji sawipun pasti Kami mendatangkan (pahala)nya. Dan cukuplah Kami sebagai pembuat perhitungan.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 48, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَىٰ وَهَـٰرُونَ ٱلۡفُرۡقَانَ وَضِیَاۤءࣰ وَذِكۡرࣰا لِّلۡمُتَّقِینَ ۝٤٨", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "ولقد آتينا موسى وهارون حجة ونصرًا على عدوهما، وكتابًا - وهو التوراة - فَرَقْنا به بين الحق والباطل، ونورًا يهتدي به المتقون الذين يخافون عقاب ربهم، وهم من الساعة التي تقوم فيها القيامة خائفون وجلون.", "isBasmala": false, "translation_en": "We gave Moses and Aaron the Criterion, and illumination, and a reminder for the righteous.", "translation_id": "Dan sesungguhnya telah Kami berikan kepada Musa dan Harun Kitab Taurat dan penerangan serta pengajaran bagi orang-orang yang bertakwa.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 49, "text": "ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ وَهُم مِّنَ ٱلسَّاعَةِ مُشۡفِقُونَ ۝٤٩", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "ولقد آتينا موسى وهارون حجة ونصرًا على عدوهما، وكتابًا - وهو التوراة - فَرَقْنا به بين الحق والباطل، ونورًا يهتدي به المتقون الذين يخافون عقاب ربهم، وهم من الساعة التي تقوم فيها القيامة خائفون وجلون.", "isBasmala": false, "translation_en": "Those who fear their Lord in private, and are apprehensive of the Hour.", "translation_id": "(yaitu) orang-orang yang takut akan (azab) Tuhan mereka, sedang mereka tidak melihat-Nya, dan mereka merasa takut akan (tibanya) hari kiamat.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 50, "text": "وَهَـٰذَا ذِكۡرࣱ مُّبَارَكٌ أَنزَلۡنَـٰهُۚ أَفَأَنتُمۡ لَهُۥ مُنكِرُونَ ۝٥٠", "juz": 17, "hizb": "(*¼ ح 33*)", "tafsir": "وهذا القرآن الذي أنزله الله على رسوله محمد صلى الله عليه وسلم ذِكْرٌ لمن تذكَّر به، وعمل بأوامره واجتنب نواهيه، كثير الخير، عظيم النفع، أفتنكرونه وهو في غاية الجلاء والظهور؟", "isBasmala": false, "translation_en": "This too is a blessed message that We revealed. Are you going to deny it?", "translation_id": "Dan Al Quran ini adalah suatu kitab (peringatan) yang mempunyai berkah yang telah Kami turunkan. Maka mengapakah kamu mengingkarinya?", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 51, "text": "۞ وَلَقَدۡ ءَاتَیۡنَاۤ إِبۡرَ ٰهِیمَ رُشۡدَهُۥ مِن قَبۡلُ وَكُنَّا بِهِۦ عَـٰلِمِینَ ۝٥١", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "ولقد آتينا إبراهيم هداه، الذي دعا الناس إليه من قبل موسى وهارون، وكنَّا عالمين أنه أهل لذلك.", "isBasmala": false, "translation_en": "We gave Abraham his integrity formerly, and We knew him well.", "translation_id": "Dan sesungguhnya telah Kami anugerahkan kepada Ibrahim hidayah kebenaran sebelum (Musa dan Harun), dan adalah Kami mengetahui (keadaan)nya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 52, "text": "إِذۡ قَالَ لِأَبِیهِ وَقَوۡمِهِۦ مَا هَـٰذِهِ ٱلتَّمَاثِیلُ ٱلَّتِیۤ أَنتُمۡ لَهَا عَـٰكِفُونَ ۝٥٢", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "حين قال لأبيه وقومه: ما هذه الأصنام التي صنعتموها، ثم أقمتم على عبادتها ملازمين لها؟", "isBasmala": false, "translation_en": "When he said to his father and his people, \"What are these statues to which you are devoted?\"", "translation_id": "(Ingatlah), ketika Ibrahim berkata kepada bapaknya dan kaumnya: \"Patung-patung apakah ini yang kamu tekun beribadat kepadanya?\"", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 53, "text": "قَالُوا۟ وَجَدۡنَاۤ ءَابَاۤءَنَا لَهَا عَـٰبِدِینَ ۝٥٣", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "قالوا: وجدنا آباءنا عابدين لها، ونحن نعبدها اقتداء بهم.", "isBasmala": false, "translation_en": "They said, \"We found our parents worshiping them.\"", "translation_id": "Mereka menjawab: \"Kami mendapati bapak-bapak kami menyembahnya\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 54, "text": "قَالَ لَقَدۡ كُنتُمۡ أَنتُمۡ وَءَابَاۤؤُكُمۡ فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٥٤", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "قال لهم إبراهيم: لقد كنتم أنتم وآباؤكم في عبادتكم لهذه الأصنام في بُعْد واضح بيِّن عن الحق.", "isBasmala": false, "translation_en": "He said, \"You and your parents are in evident error.\"", "translation_id": "Ibrahim berkata: \"Sesungguhnya kamu dan bapak-bapakmu berada dalam kesesatan yang nyata\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 55, "text": "قَالُوۤا۟ أَجِئۡتَنَا بِٱلۡحَقِّ أَمۡ أَنتَ مِنَ ٱللَّـٰعِبِینَ ۝٥٥", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "قالوا: أهذا القول الذي جئتنا به حق وَجِدٌّ، أم كلامك لنا كلام لاعبٍ مستهزئ لا يدري ما يقول؟", "isBasmala": false, "translation_en": "They said, \"Are you telling us the truth, or are you just playing?\"", "translation_id": "Mereka menjawab: \"Apakah kamu datang kepada kami dengan sungguh-sungguh ataukah kamu termasuk orang-orang yang bermain-main?\"", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 56, "text": "قَالَ بَل رَّبُّكُمۡ رَبُّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ ٱلَّذِی فَطَرَهُنَّ وَأَنَا۠ عَلَىٰ ذَ ٰلِكُم مِّنَ ٱلشَّـٰهِدِینَ ۝٥٦", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "قال لهم إبراهيم عليه الصلاة والسلام: بل ربكم الذي أدعوكم إلى عبادته هو رب السموات والأرض الذي خلقهنَّ، وأنا من الشاهدين على ذلك.", "isBasmala": false, "translation_en": "He said, \"Your Lord is the Lord of the heavens and the earth, the One who created them, and I bear witness to that.", "translation_id": "Ibrahim berkata: \"Sebenarnya Tuhan kamu ialah Tuhan langit dan bumi yang telah menciptakannya: dan aku termasuk orang-orang yang dapat memberikan bukti atas yang demikian itu\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 57, "text": "وَتَٱللَّهِ لَأَكِیدَنَّ أَصۡنَـٰمَكُم بَعۡدَ أَن تُوَلُّوا۟ مُدۡبِرِینَ ۝٥٧", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وتالله لأمكرنَّ بأصنامكم وأكسِّرها بعد أن تتولَّوا عنها ذاهبين.", "isBasmala": false, "translation_en": "\"By God, I will have a plan for your statues after you have gone away.\"", "translation_id": "Demi Allah, sesungguhnya aku akan melakukan tipu daya terhadap berhala-berhalamu sesudah kamu pergi meninggalkannya.", "manzil": 4, "manzil_display": ""}], "327": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 58, "text": "فَجَعَلَهُمۡ جُذَ ٰذًا إِلَّا كَبِیرࣰا لَّهُمۡ لَعَلَّهُمۡ إِلَیۡهِ یَرۡجِعُونَ ۝٥٨", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "فحطم إبراهيم الأصنام وجعلها قطعًا صغيرة، وترك كبيرها؛ كي يرجع القوم إليه ويسألوه، فيتبين عجزهم وضلالهم، وتقوم الحجة عليهم.", "isBasmala": false, "translation_en": "So he reduced them into pieces, except for their biggest, that they may return to it.", "translation_id": "Maka Ibrahim membuat berhala-berhala itu hancur berpotong-potong, kecuali yang terbesar (induk) dari patung-patung yang lain; agar mereka kembali (untuk bertanya) kepadanya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 59, "text": "قَالُوا۟ مَن فَعَلَ هَـٰذَا بِـَٔالِهَتِنَاۤ إِنَّهُۥ لَمِنَ ٱلظَّـٰلِمِینَ ۝٥٩", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "ورجع القوم، ورأوا أصنامهم محطمة مهانة، فسأل بعضهم بعضًا: مَن فعل هذا بآلهتنا؟ إنه لظالم في اجترائه على الآلهة المستحقة للتعظيم والتوقير.", "isBasmala": false, "translation_en": "They said, \"Who did this to our gods? He is certainly one of the wrongdoers.\"", "translation_id": "Mereka berkata: \"Siapakah yang melakukan perbuatan ini terhadap tuhan-tuhan kami, sesungguhnya dia termasuk orang-orang yang zalim\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 60, "text": "قَالُوا۟ سَمِعۡنَا فَتࣰى یَذۡكُرُهُمۡ یُقَالُ لَهُۥۤ إِبۡرَ ٰهِیمُ ۝٦٠", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "قال مَن سمع إبراهيم يحلف بأنه سيكيد أصنامهم: سمعنا فتى يقال له إبراهيم، يذكر الأصنام بسوء.", "isBasmala": false, "translation_en": "They said, \"We heard a youth mentioning them. He is called Abraham.\"", "translation_id": "Mereka berkata: \"Kami dengar ada seorang pemuda yang mencela berhala-berhala ini yang bernama Ibrahim\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 61, "text": "قَالُوا۟ فَأۡتُوا۟ بِهِۦ عَلَىٰۤ أَعۡیُنِ ٱلنَّاسِ لَعَلَّهُمۡ یَشۡهَدُونَ ۝٦١", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "قال رؤساؤهم: فَأْتوا بإبراهيم على مرأى من الناس؛ كي يشهدوا على اعترافه بما قال؛ ليكون ذلك حجة عليه.", "isBasmala": false, "translation_en": "They said, \"Bring him before the eyes of the people, so that they may witness.\"", "translation_id": "Mereka berkata: \"(Kalau demikian) bawalah dia dengan cara yang dapat dilihat orang banyak, agar mereka menyaksikan\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 62, "text": "قَالُوۤا۟ ءَأَنتَ فَعَلۡتَ هَـٰذَا بِـَٔالِهَتِنَا یَـٰۤإِبۡرَ ٰهِیمُ ۝٦٢", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وجيء بإبراهيم وسألوه منكرين: أأنت الذي كسَّرْتَ آلهتنا؟ يعنون أصنامهم.", "isBasmala": false, "translation_en": "They said, \"Are you the one who did this to our gods, O Abraham?\"", "translation_id": "Mereka bertanya: \"Apakah kamu, yang melakukan perbuatan ini terhadap tuhan-tuhan kami, hai Ibrahim?\"", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 63, "text": "قَالَ بَلۡ فَعَلَهُۥ كَبِیرُهُمۡ هَـٰذَا فَسۡـَٔلُوهُمۡ إِن كَانُوا۟ یَنطِقُونَ ۝٦٣", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وتمَّ لإبراهيم ما أراد من إظهار سفههم على مرأى منهم. فقال محتجًا عليهم معرِّضًا بغباوتهم: بل الذي كسَّرها هذا الصنم الكبير، فاسألوا آلهتكم المزعومة عن ذلك، إن كانت تتكلم أو تُحير جوابًا.", "isBasmala": false, "translation_en": "He said, \"But it was this biggest of them that did it. Ask them, if they can speak.\"", "translation_id": "Ibrahim menjawab: \"Sebenarnya patung yang besar itulah yang melakukannya, maka tanyakanlah kepada berhala itu, jika mereka dapat berbicara\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 64, "text": "فَرَجَعُوۤا۟ إِلَىٰۤ أَنفُسِهِمۡ فَقَالُوۤا۟ إِنَّكُمۡ أَنتُمُ ٱلظَّـٰلِمُونَ ۝٦٤", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "فأُسقِط في أيديهم، وبدا لهم ضلالهم؛ كيف يعبدونها، وهي عاجزة عن أن تدفع عن نفسها شيئًا أو أن تجيب سائلها؟ وأقرُّوا على أنفسهم بالظلم والشرك.", "isBasmala": false, "translation_en": "Then they turned to one another, and said, \"You yourselves are the wrongdoers.\"", "translation_id": "Maka mereka telah kembali kepada kesadaran dan lalu berkata: \"Sesungguhnya kamu sekalian adalah orang-orang yang menganiaya (diri sendiri)\",", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 65, "text": "ثُمَّ نُكِسُوا۟ عَلَىٰ رُءُوسِهِمۡ لَقَدۡ عَلِمۡتَ مَا هَـٰۤؤُلَاۤءِ یَنطِقُونَ ۝٦٥", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وسُرعان ما عاد إليهم عنادهم بعد إفحامهم، فانقلبوا إلى الباطل، واحتجُّوا على إبراهيم بما هو حجة له عليهم، فقالوا: كيف نسألها، وقد علمتَ أنها لا تنطق؟", "isBasmala": false, "translation_en": "But they reverted to their old ideas: \"You certainly know that these do not speak.\"", "translation_id": "kemudian kepala mereka jadi tertunduk (lalu berkata): \"Sesungguhnya kamu (hai Ibrahim) telah mengetahui bahwa berhala-berhala itu tidak dapat berbicara\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 66, "text": "قَالَ أَفَتَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَنفَعُكُمۡ شَیۡـࣰٔا وَلَا یَضُرُّكُمۡ ۝٦٦", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "قال إبراهيم محقِّرًا لشأن الأصنام: كيف تعبدون أصنامًا لا تنفع إذا عُبدت، ولا تضرُّ إذا تُركت؟ قبحًا لكم ولآلهتكم التي تعبدونها من دون الله تعالى، أفلا تعقلون فتدركون سوء ما أنتم عليه؟", "isBasmala": false, "translation_en": "He said, \"Do you worship, instead of God, what can neither benefit you in anything, nor harm you?", "translation_id": "Ibrahim berkata: Maka mengapakah kamu menyembah selain Allah sesuatu yang tidak dapat memberi manfaat sedikitpun dan tidak (pula) memberi mudharat kepada kamu?\"", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 67, "text": "أُفࣲّ لَّكُمۡ وَلِمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِۚ أَفَلَا تَعۡقِلُونَ ۝٦٧", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "قال إبراهيم محقِّرًا لشأن الأصنام: كيف تعبدون أصنامًا لا تنفع إذا عُبدت، ولا تضرُّ إذا تُركت؟ قبحًا لكم ولآلهتكم التي تعبدونها من دون الله تعالى، أفلا تعقلون فتدركون سوء ما أنتم عليه؟", "isBasmala": false, "translation_en": "Fie on you, and on what you worship instead of God. Do you not understand?\"", "translation_id": "Ah (celakalah) kamu dan apa yang kamu sembah selain Allah. Maka apakah kamu tidak memahami?", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 68, "text": "قَالُوا۟ حَرِّقُوهُ وَٱنصُرُوۤا۟ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَـٰعِلِینَ ۝٦٨", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "لما بطلت حجتهم وظهر الحق عدلوا إلى استعمال سلطانهم، وقالوا: حَرِّقوا إبراهيم بالنار؛ غضبًا لآلهتكم إن كنتم ناصرين لها. فأشْعَلوا نارًا عظيمة وألقوه فيها، فانتصر الله لرسوله وقال للنار: كوني بردًا وسلامًا على إبراهيم، فلم يَنَلْه فيها أذى، ولم يصبه مكروه.", "isBasmala": false, "translation_en": "They said, \"Burn him and support your gods, if you are going to act.\"", "translation_id": "Mereka berkata: \"Bakarlah dia dan bantulah tuhan-tuhan kamu, jika kamu benar-benar hendak bertindak\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 69, "text": "قُلۡنَا یَـٰنَارُ كُونِی بَرۡدࣰا وَسَلَـٰمًا عَلَىٰۤ إِبۡرَ ٰهِیمَ ۝٦٩", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "لما بطلت حجتهم وظهر الحق عدلوا إلى استعمال سلطانهم، وقالوا: حَرِّقوا إبراهيم بالنار؛ غضبًا لآلهتكم إن كنتم ناصرين لها. فأشْعَلوا نارًا عظيمة وألقوه فيها، فانتصر الله لرسوله وقال للنار: كوني بردًا وسلامًا على إبراهيم، فلم يَنَلْه فيها أذى، ولم يصبه مكروه.", "isBasmala": false, "translation_en": "We said, \"O fire, be coolness and safety upon Abraham.\"", "translation_id": "Kami berfirman: \"Hai api menjadi dinginlah, dan menjadi keselamatanlah bagi Ibrahim\",", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 70, "text": "وَأَرَادُوا۟ بِهِۦ كَیۡدࣰا فَجَعَلۡنَـٰهُمُ ٱلۡأَخۡسَرِینَ ۝٧٠", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وأراد القوم بإبراهيم الهلاك فأبطل الله كيدهم، وجعلهم المغلوبين الأسفلين.", "isBasmala": false, "translation_en": "They planned to harm him, but We made them the worst losers.", "translation_id": "mereka hendak berbuat makar terhadap Ibrahim, maka Kami menjadikan mereka itu orang-orang yang paling merugi.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 71, "text": "وَنَجَّیۡنَـٰهُ وَلُوطًا إِلَى ٱلۡأَرۡضِ ٱلَّتِی بَـٰرَكۡنَا فِیهَا لِلۡعَـٰلَمِینَ ۝٧١", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "ونجينا إبراهيم ولوطًا الذي آمن به من \"العراق\"، وأخرجناهما إلى أرض \"الشام\" التي باركنا فيها بكثرة الخيرات، وفيها أكثر الأنبياء عليهم الصلاة والسلام.", "isBasmala": false, "translation_en": "And We delivered him, and Lot, to the land that We blessed for all people.", "translation_id": "Dan Kami seIamatkan Ibrahim dan Luth ke sebuah negeri yang Kami telah memberkahinya untuk sekalian manusia.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 72, "text": "وَوَهَبۡنَا لَهُۥۤ إِسۡحَـٰقَ وَیَعۡقُوبَ نَافِلَةࣰۖ وَكُلࣰّا جَعَلۡنَا صَـٰلِحِینَ ۝٧٢", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وأنعم الله على إبراهيم، فوهب له ابنه إسحاق حين دعاه، ووهب له من إسحاق يعقوب زيادة على ذلك، وكلٌّ من إبراهيم وإسحاق ويعقوب جعله الله صالحًا مطيعًا له.", "isBasmala": false, "translation_en": "And We granted him Isaac and Jacob as a gift; and each We made righteous.", "translation_id": "Dan Kami telah memberikan kepada-nya (Ibrahim) lshak dan Ya'qub, sebagai suatu anugerah (daripada Kami). Dan masing-masingnya Kami jadikan orang-orang yang saleh", "manzil": 4, "manzil_display": ""}], "328": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 73, "text": "وَجَعَلۡنَـٰهُمۡ أَىِٕمَّةࣰ یَهۡدُونَ بِأَمۡرِنَا وَأَوۡحَیۡنَاۤ إِلَیۡهِمۡ فِعۡلَ ٱلۡخَیۡرَ ٰتِ وَإِقَامَ ٱلصَّلَوٰةِ وَإِیتَاۤءَ ٱلزَّكَوٰةِۖ وَكَانُوا۟ لَنَا عَـٰبِدِینَ ۝٧٣", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وجعلنا إبراهيم وإسحاق ويعقوب قدوة للناس يدعونهم إلى عبادته وطاعته بإذنه تعالى، وأوحينا إليهم فِعْلَ الخيرات من العمل بشرائع الأنبياء، وإقام الصلاة على وجهها، وإيتاء الزكاة، فامتثلوا لذلك، وكانوا منقادين مطيعين لله وحده دون سواه.", "isBasmala": false, "translation_en": "And We made them leaders, guiding by Our command; and We inspired them to do good works, and to observe the prayer, and to give out charity. They were devoted servants to Us.", "translation_id": "Kami telah menjadikan mereka itu sebagai pemimpin-pemimpin yang memberi petunjuk dengan perintah Kami dan telah Kami wahyukan kepada, mereka mengerjakan kebajikan, mendirikan sembahyang, menunaikan zakat, dan hanya kepada Kamilah mereka selalu menyembah,", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 74, "text": "وَلُوطًا ءَاتَیۡنَـٰهُ حُكۡمࣰا وَعِلۡمࣰا وَنَجَّیۡنَـٰهُ مِنَ ٱلۡقَرۡیَةِ ٱلَّتِی كَانَت تَّعۡمَلُ ٱلۡخَبَـٰۤىِٕثَۚ إِنَّهُمۡ كَانُوا۟ قَوۡمَ سَوۡءࣲ فَـٰسِقِینَ ۝٧٤", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وآتينا لوطًا النبوة وفصل القضاء بين الخصوم وعلمًا بأمر الله ودينه، ونجيناه من قريته \"سدوم\" التي كان يعمل أهلها الخبائث. إنهم كانوا بسبب الخبائث والمنكرات التي يأتونها أهل سوء وقُبْح، خارجين عن طاعة الله.", "isBasmala": false, "translation_en": "And Lot-We gave him judgment and knowledge, and We delivered him from the town that practiced the abominations. They were wicked and perverted people.", "translation_id": "dan kepada Luth, Kami telah berikan hikmah dan ilmu, dan telah Kami selamatkan dia dari (azab yang telah menimpa penduduk) kota yang mengerjakan perbuatan keji. Sesungguhnya mereka adalah kaum yang jahat lagi fasik,", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 75, "text": "وَأَدۡخَلۡنَـٰهُ فِی رَحۡمَتِنَاۤۖ إِنَّهُۥ مِنَ ٱلصَّـٰلِحِینَ ۝٧٥", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وأتمَّ الله عليه النعمة فأدخله في رحمته بإنجائه ممَّا حلَّ بقومه؛ لأنه كان من الذين يعملون بطاعة الله.", "isBasmala": false, "translation_en": "And We admitted him into Our mercy; for He was one of the righteous.", "translation_id": "dan Kami masukkan dia ke dalam rahmat Kami; karena sesungguhnya dia termasuk orang-orang yang saleh.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 76, "text": "وَنُوحًا إِذۡ نَادَىٰ مِن قَبۡلُ فَٱسۡتَجَبۡنَا لَهُۥ فَنَجَّیۡنَـٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِیمِ ۝٧٦", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "واذكر - أيها الرسول - نوحا حين نادى ربه مِن قبلك ومِن قبل إبراهيم ولوط، فاستجبنا له دعاءه، فنجيناه وأهله المؤمنين به من الغم الشديد.", "isBasmala": false, "translation_en": "And Noah, when he called before. So We answered him, and delivered him and his family from the great disaster.", "translation_id": "Dan (ingatlah kisah) Nuh, sebelum itu ketika dia berdoa, dan Kami memperkenankan doanya, lalu Kami selamatkan dia beserta keluarganya dari bencana yang besar.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 77, "text": "وَنَصَرۡنَـٰهُ مِنَ ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَاۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمَ سَوۡءࣲ فَأَغۡرَقۡنَـٰهُمۡ أَجۡمَعِینَ ۝٧٧", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "ونصرناه مِن كيد القوم الذين كذَّبوا بآياتنا الدالة على صدقه، إنهم كانوا أهل قُبْح، فأغرقناهم بالطوفان أجمعين.", "isBasmala": false, "translation_en": "And We supported him against the people who rejected Our signs. They were an evil people, so We drowned them all.", "translation_id": "Dan Kami telah menolongnya dari kaum yang telah mendustakan ayat-ayat Kami. Sesungguhnya mereka adalah kaum yang jahat, maka Kami tenggelamkan mereka semuanya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 78, "text": "وَدَاوُۥدَ وَسُلَیۡمَـٰنَ إِذۡ یَحۡكُمَانِ فِی ٱلۡحَرۡثِ إِذۡ نَفَشَتۡ فِیهِ غَنَمُ ٱلۡقَوۡمِ وَكُنَّا لِحُكۡمِهِمۡ شَـٰهِدِینَ ۝٧٨", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "واذكر - أيها الرسول - نبي الله داود وابنه سليمان، إذ يحكمان في قضية عرَضَها خصمان، عَدَت غنم أحدهما على زرع الآخر، وانتشرت فيه ليلا فأتلفت الزرع، فحكم داود بأن تكون الغنم لصاحب الزرع ملْكًا بما أتلفته، فقيمتهما سواء، وكنَّا لحكمهم شاهدين لم يَغِبْ عنا.", "isBasmala": false, "translation_en": "And David and Solomon, when they gave judgment in the case of the field, when some people's sheep wandered therein by night; and We were witnesses to their judgment.", "translation_id": "Dan (ingatlah kisah) Daud dan Sulaiman, di waktu keduanya memberikan keputusan mengenai tanaman, karena tanaman itu dirusak oleh kambing-kambing kepunyaan kaumnya. Dan adalah Kami menyaksikan keputusan yang diberikan oleh mereka itu,", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 79, "text": "فَفَهَّمۡنَـٰهَا سُلَیۡمَـٰنَۚ وَكُلًّا ءَاتَیۡنَا حُكۡمࣰا وَعِلۡمࣰاۚ وَسَخَّرۡنَا مَعَ دَاوُۥدَ ٱلۡجِبَالَ یُسَبِّحۡنَ وَٱلطَّیۡرَۚ وَكُنَّا فَـٰعِلِینَ ۝٧٩", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "فَفَهَّمنا سليمان مراعاة مصلحة الطرفين مع العدل، فحكم على صاحب الغنم بإصلاح الزرع التالف في فترة يستفيد فيها صاحب الزرع بمنافع الغنم من لبن وصوف ونحوهما، ثم تعود الغنم إلى صاحبها والزرع إلى صاحبه؛ لمساواة قيمة ما تلف من الزرع لمنفعة الغنم، وكلا من داود وسليمان أعطيناه حكمًا وعلمًا، ومننَّا على داود بتطويع الجبال تسبِّح معه إذا سبَّح، وكذلك الطير تسبِّح، وكنا فاعلين ذلك.", "isBasmala": false, "translation_en": "And so We made Solomon understand it, and to each We gave wisdom and knowledge. And We subjected the mountains along with David to sing Our praises, and the birds as well-surely We did.", "translation_id": "maka Kami telah memberikan pengertian kepada Sulaiman tentang hukum (yang lebih tepat); dan kepada masing-masing mereka telah Kami berikan hikmah dan ilmu dan telah Kami tundukkan gunung-gunung dan burung-burung, semua bertasbih bersama Daud. Dan kamilah yang melakukannya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 80, "text": "وَعَلَّمۡنَـٰهُ صَنۡعَةَ لَبُوسࣲ لَّكُمۡ لِتُحۡصِنَكُم مِّنۢ بَأۡسِكُمۡۖ فَهَلۡ أَنتُمۡ شَـٰكِرُونَ ۝٨٠", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "واختصَّ الله داود عليه السلام بأن علَّمه صناعة الدروع يعملها حِلَقًا متشابكة، تسهِّل حركة الجسم؛ لتحمي المحاربين مِن وَقْع السلاح فيهم، فهل أنتم شاكرون نعمة الله عليكم حيث أجراها على يد عبده داود؟", "isBasmala": false, "translation_en": "And We taught him the making of shields for you, to protect you from your violence. Are you, then, appreciative?", "translation_id": "Dan telah Kami ajarkan kepada Daud membuat baju besi untuk kamu, guna memelihara kamu dalam peperanganmu; Maka hendaklah kamu bersyukur (kepada Allah).", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 81, "text": "وَلِسُلَیۡمَـٰنَ ٱلرِّیحَ عَاصِفَةࣰ تَجۡرِی بِأَمۡرِهِۦۤ إِلَى ٱلۡأَرۡضِ ٱلَّتِی بَـٰرَكۡنَا فِیهَاۚ وَكُنَّا بِكُلِّ شَیۡءٍ عَـٰلِمِینَ ۝٨١", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وسخَّرنا لسليمان الريح شديدة الهبوب تحمله ومَن معه، تجري بأمره إلى أرض \"بيت المقدس\" بـ \"الشام\" التي باركنا فيها بالخيرات الكثيرة، وقد أحاط علمنا بجميع الأشياء.", "isBasmala": false, "translation_en": "And to Solomon the stormy wind, blowing at His command towards the land that We have blessed. We are aware of everything.", "translation_id": "Dan (telah Kami tundukkan) untuk Sulaiman angin yang sangat kencang tiupannya yang berhembus dengan perintahnya ke negeri yang kami telah memberkatinya. Dan adalah Kami Maha Mengetahui segala sesuatu.", "manzil": 4, "manzil_display": ""}], "329": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 82, "text": "وَمِنَ ٱلشَّیَـٰطِینِ مَن یَغُوصُونَ لَهُۥ وَیَعۡمَلُونَ عَمَلࣰا دُونَ ذَ ٰلِكَۖ وَكُنَّا لَهُمۡ حَـٰفِظِینَ ۝٨٢", "juz": 17, "hizb": "(*½ ح 33*)", "tafsir": "وسخَّرنا لسليمان من الشياطين شياطين يستخدمهم فيما يَعْجِز عنه غيرهم، فكانوا يغوصون في البحر يستخرجون له اللآلئ والجواهر، وكانوا يعملون كذلك في صناعة ما يريده منهم، لا يقدرون على الامتناع مما يريده منهم، حفظهم الله له بقوته وعزه سبحانه وتعالى.", "isBasmala": false, "translation_en": "And of the devils were some that dived for him, and performed other, lesser tasks. But We kept them restrained.", "translation_id": "Dan Kami telah tundukkan (pula kepada Sulaiman) segolongan syaitan-syaitan yang menyelam (ke dalam laut) untuknya dan mengerjakan pekerjaan selain daripada itu, dan adalah Kami memelihara mereka itu,", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 83, "text": "۞ وَأَیُّوبَ إِذۡ نَادَىٰ رَبَّهُۥۤ أَنِّی مَسَّنِیَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّ ٰحِمِینَ ۝٨٣", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "واذكر - أيها الرسول - عبدنا أيوب، إذ ابتليناه بضر وسقم عظيم في جسده، وفقد أهله وماله وولده، فصبر واحتسب، ونادى ربه عز وجل أني قد أصابني الضر، وأنت أرحم الراحمين، فاكشفه عني.", "isBasmala": false, "translation_en": "And Job, when he cried out to his Lord: \"Great harm has afflicted me, and you are the Most Merciful of the merciful.\"", "translation_id": "dan (ingatlah kisah) Ayub, ketika ia menyeru Tuhannya: \"(Ya Tuhanku), sesungguhnya aku telah ditimpa penyakit dan Engkau adalah Tuhan Yang Maha Penyayang di antara semua penyayang\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 84, "text": "فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرࣲّۖ وَءَاتَیۡنَـٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةࣰ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَـٰبِدِینَ ۝٨٤", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "فاستجبنا له دعاءه، ورفعنا عنه البلاء، ورددنا عليه ما فقده من أهل وولد ومال مضاعفًا، فَعَلْنا به ذلك رحمة منَّا، وليكون قدوة لكل صابر على البلاء، راجٍ رحمة ربه، عابد له.", "isBasmala": false, "translation_en": "So We answered him, lifted his suffering, and restored his family to him, and their like with them-a mercy from Us, and a reminder for the worshipers.", "translation_id": "Maka Kamipun memperkenankan seruannya itu, lalu Kami lenyapkan penyakit yang ada padanya dan Kami kembalikan keluarganya kepadanya, dan Kami lipat gandakan bilangan mereka, sebagai suatu rahmat dari sisi Kami dan untuk menjadi peringatan bagi semua yang menyembah Allah.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 85, "text": "وَإِسۡمَـٰعِیلَ وَإِدۡرِیسَ وَذَا ٱلۡكِفۡلِۖ كُلࣱّ مِّنَ ٱلصَّـٰبِرِینَ ۝٨٥", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "واذكر إسماعيل وإدريس وذا الكفل، كل هؤلاء من الصابرين على طاعة الله سبحانه وتعالى، وعن معاصيه، وعلى أقداره، فاستحقوا الذكر بالثناء الجميل.", "isBasmala": false, "translation_en": "And Ishmael, and Enoch, and Ezekiel; each was one of the steadfast.", "translation_id": "Dan (ingatlah kisah) Ismail, Idris dan Dzulkifli. Semua mereka termasuk orang-orang yang sabar.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 86, "text": "وَأَدۡخَلۡنَـٰهُمۡ فِی رَحۡمَتِنَاۤۖ إِنَّهُم مِّنَ ٱلصَّـٰلِحِینَ ۝٨٦", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "وأدخلناهم في رحمتنا، إنهم ممن صلح باطنه وظاهره، فأطاع الله وعمل بما أمره به.", "isBasmala": false, "translation_en": "And We admitted them into Our mercy. They were among the righteous.", "translation_id": "Kami telah memasukkan mereka kedalam rahmat Kami. Sesungguhnya mereka termasuk orang-orang yang saleh.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 87, "text": "وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَـٰضِبࣰا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَیۡهِ فَنَادَىٰ فِی ٱلظُّلُمَـٰتِ أَن لَّاۤ إِلَـٰهَ إِلَّاۤ أَنتَ سُبۡحَـٰنَكَ إِنِّی كُنتُ مِنَ ٱلظَّـٰلِمِینَ ۝٨٧", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "واذكر قصة صاحب الحوت، وهو يونس بن مَتَّى عليه السلام، أرسله الله إلى قومه فدعاهم فلم يؤمنوا، فتوعَّدهم بالعذاب فلم ينيبوا، ولم يصبر عليهم كما أمره الله، وخرج مِن بينهم غاضبًا عليهم، ضائقًا صدره بعصيانهم، وظن أن الله لن يضيِّق عليه ويؤاخذه بهذه المخالفة، فابتلاه الله بشدة الضيق والحبس، والتقمه الحوت في البحر، فنادى ربه في ظلمات الليل والبحر وبطن الحوت تائبًا معترفًا بظلمه؛ لتركه الصبر على قومه، قائلا: لا إله إلا أنت سبحانك، إني كنت من الظالمين.", "isBasmala": false, "translation_en": "And Jonah, when he stormed out in fury, thinking We had no power over him. But then He cried out in the darkness, \"There is no god but You! Glory to You! I was one of the wrongdoers!\"", "translation_id": "Dan (ingatlah kisah) Dzun Nun (Yunus), ketika ia pergi dalam keadaan marah, lalu ia menyangka bahwa Kami tidak akan mempersempitnya (menyulitkannya), maka ia menyeru dalam keadaan yang sangat gelap: \"Bahwa tidak ada Tuhan selain Engkau. Maha Suci Engkau, sesungguhnya aku adalah termasuk orang-orang yang zalim\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 88, "text": "فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّیۡنَـٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَ ٰلِكَ نُۨجِی ٱلۡمُؤۡمِنِینَ ۝٨٨", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "فاستجبنا له دعاءه، وخلَّصناه مِن غَم هذه الشدة، وكذلك ننجي المصدِّقين العاملين بشرعنا.", "isBasmala": false, "translation_en": "So We answered him, and saved him from the affliction. Thus We save the faithful.", "translation_id": "Maka Kami telah memperkenankan doanya dan menyelamatkannya dari pada kedukaan. Dan demikianlah Kami selamatkan orang-orang yang beriman.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 89, "text": "وَزَكَرِیَّاۤ إِذۡ نَادَىٰ رَبَّهُۥ رَبِّ لَا تَذَرۡنِی فَرۡدࣰا وَأَنتَ خَیۡرُ ٱلۡوَ ٰرِثِینَ ۝٨٩", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "واذكر - أيها الرسول - قصة عبد الله زكريا حين دعا ربه أن يرزقه الذرية لما كَبِرت سنُّه قائلا رب لا تتركني وحيدًا لا عقب لي، هب لي وارثًا يقوم بأمر الدين في الناس من بعدي، وأنت خير الباقين وخير مَن خلفني بخير.", "isBasmala": false, "translation_en": "And Zechariah, when he called out to his Lord, \"My Lord, do not leave me alone, even though you are the Best of heirs.\"", "translation_id": "Dan (ingatlah kisah) Zakaria, tatkala ia menyeru Tuhannya: \"Ya Tuhanku janganlah Engkau membiarkan aku hidup seorang diri dan Engkaulah Waris Yang Paling Baik.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 90, "text": "فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ یَحۡیَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥۤۚ إِنَّهُمۡ كَانُوا۟ یُسَـٰرِعُونَ فِی ٱلۡخَیۡرَ ٰتِ وَیَدۡعُونَنَا رَغَبࣰا وَرَهَبࣰاۖ وَكَانُوا۟ لَنَا خَـٰشِعِینَ ۝٩٠", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "فاستجبنا له دعاءه ووهبنا له على الكبر ابنه يحيى، وجعلنا زوجته صالحة في أخلاقها وصالحة للحمل والولادة بعد أن كانت عاقرًا، إنهم كانوا يبادرون إلى كل خير، ويدعوننا راغبين فيما عندنا، خائفين من عقوبتنا، وكانوا لنا خاضعين متواضعين.", "isBasmala": false, "translation_en": "So We answered him, and gave him John. And We cured his wife for him. They used to vie in doing righteous deeds, and used to call on Us in love and awe, and they used to humble themselves to Us.", "translation_id": "Maka Kami memperkenankan doanya, dan Kami anugerahkan kepada nya Yahya dan Kami jadikan isterinya dapat mengandung. Sesungguhnya mereka adalah orang-orang yang selalu bersegera dalam (mengerjakan) perbuatan-perbuatan yang baik dan mereka berdoa kepada Kami dengan harap dan cemas. Dan mereka adalah orang-orang yang khusyu' kepada Kami.", "manzil": 4, "manzil_display": ""}], "330": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 91, "text": "وَٱلَّتِیۤ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِیهَا مِن رُّوحِنَا وَجَعَلۡنَـٰهَا وَٱبۡنَهَاۤ ءَایَةࣰ لِّلۡعَـٰلَمِینَ ۝٩١", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "واذكر - أيها الرسول - قصة مريم ابنة عمران التي حفظت فرجها من الحرام، ولم تأتِ فاحشة في حياتها، فأرسل الله إليها جبريل عليه السلام، فنفخ في جيب قميصها، فوصلت النفخة إلى رحمها، فخلق الله بذلك النفخ المسيح عيسى عليه السلام، فحملت به من غير زوج، فكانت هي وابنها بذلك علامة على قدرة الله، وعبرة للخلق إلى قيام الساعة.", "isBasmala": false, "translation_en": "And she who guarded her virginity. We breathed into her of Our spirit, and made her and her son a sign to the world.", "translation_id": "Dan (ingatlah kisah) Maryam yang telah memelihara kehormatannya, lalu Kami tiupkan ke dalam (tubuh)nya ruh dari Kami dan Kami jadikan dia dan anaknya tanda (kekuasaan Allah) yang besar bagi semesta alam.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 92, "text": "إِنَّ هَـٰذِهِۦۤ أُمَّتُكُمۡ أُمَّةࣰ وَ ٰحِدَةࣰ وَأَنَا۠ رَبُّكُمۡ فَٱعۡبُدُونِ ۝٩٢", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "هؤلاء الأنبياء جميعًا دينهم واحد، الإسلام، وهو الاستسلام لله بالطاعة وإفراده بالعبادة، والله سبحانه وتعالى رب الخلق فاعبدوه - أيها الناس - وحده لا شريك له.", "isBasmala": false, "translation_en": "This community of yours is one community, and I am your Lord, so worship Me.", "translation_id": "Sesungguhnya (agama Tauhid) ini adalah agama kamu semua; agama yang satu dan Aku adalah Tuhanmu, maka sembahlah Aku.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 93, "text": "وَتَقَطَّعُوۤا۟ أَمۡرَهُم بَیۡنَهُمۡۖ كُلٌّ إِلَیۡنَا رَ ٰجِعُونَ ۝٩٣", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "لكن الناس اختلفوا على رسلهم، وتفرَّق كثير من أتباعهم في الدين شيعًا وأحزابًا، فعبدوا المخلوقين والأهواء، وكلهم راجعون إلينا ومحاسبون على ما فعلوا.", "isBasmala": false, "translation_en": "But they splintered themselves into factions. They will all return to Us.", "translation_id": "Dan mereka telah memotong-motong urusan (agama) mereka di antara mereka. Kepada Kamilah masing-masing golongan itu akan kembali.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 94, "text": "فَمَن یَعۡمَلۡ مِنَ ٱلصَّـٰلِحَـٰتِ وَهُوَ مُؤۡمِنࣱ فَلَا كُفۡرَانَ لِسَعۡیِهِۦ وَإِنَّا لَهُۥ كَـٰتِبُونَ ۝٩٤", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "فمن التزم الإيمان بالله ورسله، وعمل ما يستطيع من صالح الأعمال طاعةً لله وعبادة له فلا يضيع الله عمله ولا يبطله، بل يضاعفه كله أضعافًا كثيرة، وسيجد ما عمله في كتابه يوم يُبْعث بعد موته.", "isBasmala": false, "translation_en": "Whoever does righteous deeds, and is a believer, his effort will not be denied. We are writing it down for him.", "translation_id": "Maka barang siapa yang mengerjakan amal saleh, sedang ia beriman, maka tidak ada pengingkaran terhadap amalannya itu dan sesungguhnya Kami menuliskan amalannya itu untuknya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 95, "text": "وَحَرَ ٰمٌ عَلَىٰ قَرۡیَةٍ أَهۡلَكۡنَـٰهَاۤ أَنَّهُمۡ لَا یَرۡجِعُونَ ۝٩٥", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "وممتنع على أهل القرى التي أهلكناها بسبب كفرهم وظلمهم، رجوعهم إلى الدنيا قبل يوم القيامة؛ ليستدركوا ما فرطوا فيه.", "isBasmala": false, "translation_en": "There is a ban on the town that We had destroyed-that they will not return.", "translation_id": "Sungguh tidak mungkin atas (penduduk) suatu negeri yang telah Kami binasakan, bahwa mereka tidak akan kembali (kepada Kami).", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 96, "text": "حَتَّىٰۤ إِذَا فُتِحَتۡ یَأۡجُوجُ وَمَأۡجُوجُ وَهُم مِّن كُلِّ حَدَبࣲ یَنسِلُونَ ۝٩٦", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "فإذا فُتِح سد يأجوج ومأجوج، وانطلقوا من مرتفعات الأرض وانتشروا في جنباتها مسرعين، دنا يوم القيامة وبدَتْ أهواله فإذا أبصار الكفار مِن شدة الفزع مفتوحة لا تكاد تَطْرِف، يدعون على أنفسهم بالويل في حسرة: يا ويلنا قد كنا لاهين غافلين عن هذا اليوم وعن الإعداد له، وكنا بذلك ظالمين.", "isBasmala": false, "translation_en": "Until, when Gog and Magog are let loose, and they swarm down from every mound.", "translation_id": "Hingga apabila dibukakan (tembok) Ya'juj dan Ma'juj, dan mereka turun dengan cepat dari seluruh tempat yang tinggi.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 97, "text": "وَٱقۡتَرَبَ ٱلۡوَعۡدُ ٱلۡحَقُّ فَإِذَا هِیَ شَـٰخِصَةٌ أَبۡصَـٰرُ ٱلَّذِینَ كَفَرُوا۟ یَـٰوَیۡلَنَا قَدۡ كُنَّا فِی غَفۡلَةࣲ مِّنۡ هَـٰذَا بَلۡ كُنَّا ظَـٰلِمِینَ ۝٩٧", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "فإذا فُتِح سد يأجوج ومأجوج، وانطلقوا من مرتفعات الأرض وانتشروا في جنباتها مسرعين، دنا يوم القيامة وبدَتْ أهواله فإذا أبصار الكفار مِن شدة الفزع مفتوحة لا تكاد تَطْرِف، يدعون على أنفسهم بالويل في حسرة: يا ويلنا قد كنا لاهين غافلين عن هذا اليوم وعن الإعداد له، وكنا بذلك ظالمين.", "isBasmala": false, "translation_en": "The promise of truth has drawn near. The eyes of those who disbelieved will stare in horror: \"Woe to us. We were oblivious to this. In fact, we were wrongdoers.\"", "translation_id": "Dan telah dekatlah kedatangan janji yang benar (hari berbangkit), maka tiba-tiba terbelalaklah mata orang-orang yang kafir. (Mereka berkata): \"Aduhai, celakalah kami, sesungguhnya kami adalah dalam kelalaian tentang ini, bahkan kami adalah orang-orang yang zalim\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 98, "text": "إِنَّكُمۡ وَمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ حَصَبُ جَهَنَّمَ أَنتُمۡ لَهَا وَ ٰرِدُونَ ۝٩٨", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "إنكم - أيها الكفار - وما كنتم تعبدون من دون الله من الأصنام ومَن رضي بعبادتكم إياه من الجن والإنس، وقود جهنم وحطبها، أنتم وهم فيها داخلون.", "isBasmala": false, "translation_en": "You and what you worship besides God are fuel for Hell. You will descend into it.", "translation_id": "Sesungguhnya kamu dan apa yang kamu sembah selain Allah, adalah umpan Jahannam, kamu pasti masuk ke dalamnya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 99, "text": "لَوۡ كَانَ هَـٰۤؤُلَاۤءِ ءَالِهَةࣰ مَّا وَرَدُوهَاۖ وَكُلࣱّ فِیهَا خَـٰلِدُونَ ۝٩٩", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "لو كان هؤلاء الذين عبدتموهم من دون الله تعالى آلهة تستحق العبادة ما دخلوا نار جهنم معكم أيها المشركون، إنَّ كلا من العابدين والمعبودين خالدون في نار جهنم.", "isBasmala": false, "translation_en": "Had these been gods, they would not have descended into it. All will abide in it.", "translation_id": "Andaikata berhala-berhala itu Tuhan, tentulah mereka tidak masuk neraka. Dan semuanya akan kekal di dalamnya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 100, "text": "لَهُمۡ فِیهَا زَفِیرࣱ وَهُمۡ فِیهَا لَا یَسۡمَعُونَ ۝١٠٠", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "لهؤلاء المعذبين في النار آلام ينبئ عنها زفيرهم الذي تتردد فيه أنفاسهم، وهم في النار لا يسمعون؛ من هول عذابهم.", "isBasmala": false, "translation_en": "In it they will wail. In it they will not hear.", "translation_id": "Mereka merintih di dalam api dan mereka di dalamnya tidak bisa mendengar.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 101, "text": "إِنَّ ٱلَّذِینَ سَبَقَتۡ لَهُم مِّنَّا ٱلۡحُسۡنَىٰۤ أُو۟لَـٰۤىِٕكَ عَنۡهَا مُبۡعَدُونَ ۝١٠١", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "إن الذين سبقت لهم منا سابقة السعادة الحسنة في علمنا بكونهم من أهل الجنة، أولئك عن النار مبعدون، فلا يدخلونها ولا يكونون قريبًا منها.", "isBasmala": false, "translation_en": "As for those who deserved goodness from Us-these will be kept away from it.", "translation_id": "Bahwasanya orang-orang yang telah ada untuk mereka ketetapan yang baik dari Kami, mereka itu dijauhkan dari neraka,", "manzil": 4, "manzil_display": ""}], "331": [{"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 102, "text": "لَا یَسۡمَعُونَ حَسِیسَهَاۖ وَهُمۡ فِی مَا ٱشۡتَهَتۡ أَنفُسُهُمۡ خَـٰلِدُونَ ۝١٠٢", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "لا يسمعون صوت لهيبها واحتراق الأجساد فيها فقد سكنوا منازلهم في الجنة، وأصبحوا فيما تشتهيه نفوسهم من نعيمها ولذاتها مقيمين إقامةً دائمة.", "isBasmala": false, "translation_en": "They will not hear its hissing, and they will forever abide in what their hearts desire.", "translation_id": "mereka tidak mendengar sedikitpun suara api neraka, dan mereka kekal dalam menikmati apa yang diingini oleh mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 103, "text": "لَا یَحۡزُنُهُمُ ٱلۡفَزَعُ ٱلۡأَكۡبَرُ وَتَتَلَقَّىٰهُمُ ٱلۡمَلَـٰۤىِٕكَةُ هَـٰذَا یَوۡمُكُمُ ٱلَّذِی كُنتُمۡ تُوعَدُونَ ۝١٠٣", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "لا يخيفهم الهول العظيم يوم القيامة، بل تبشرهم الملائكة: هذا يومكم الذي وُعِدتُم فيه الكرامة من الله وجزيل الثواب. يوم نطوي السماء كما تُطْوى الصحيفة على ما كُتب فيها، ونبعث فيه الخلق على هيئة خَلْقنا لهم أول مرة كما ولدتهم أمهاتهم، ذلك وعد الله الذي لا يتخلَّف، وَعَدْنا بذلك وعدًا حقًا علينا، إنا كنا فاعلين دائمًا ما نَعِدُ به.", "isBasmala": false, "translation_en": "The Supreme Fear will not worry them, and the angels will receive them: \"This is your Day which you were promised.\"", "translation_id": "Mereka tidak disusahkan oleh kedahsyatan yang besar (pada hari kiamat), dan mereka disambut oleh para malaikat. (Malaikat berkata): \"Inilah harimu yang telah dijanjikan kepadamu\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 104, "text": "یَوۡمَ نَطۡوِی ٱلسَّمَاۤءَ كَطَیِّ ٱلسِّجِلِّ لِلۡكُتُبِۚ كَمَا بَدَأۡنَاۤ أَوَّلَ خَلۡقࣲ نُّعِیدُهُۥۚ وَعۡدًا عَلَیۡنَاۤۚ إِنَّا كُنَّا فَـٰعِلِینَ ۝١٠٤", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "لا يخيفهم الهول العظيم يوم القيامة، بل تبشرهم الملائكة: هذا يومكم الذي وُعِدتُم فيه الكرامة من الله وجزيل الثواب. يوم نطوي السماء كما تُطْوى الصحيفة على ما كُتب فيها، ونبعث فيه الخلق على هيئة خَلْقنا لهم أول مرة كما ولدتهم أمهاتهم، ذلك وعد الله الذي لا يتخلَّف، وَعَدْنا بذلك وعدًا حقًا علينا، إنا كنا فاعلين دائمًا ما نَعِدُ به.", "isBasmala": false, "translation_en": "On the Day when We fold the heaven, like the folding of a book. Just as We began the first creation, We will repeat it-a promise binding on Us. We will act.", "translation_id": "(Yaitu) pada hari Kami gulung langit sebagai menggulung lembaran-lembaran kertas. Sebagaimana Kami telah memulai panciptaan pertama begitulah Kami akan mengulanginya. Itulah suatu janji yang pasti Kami tepati; sesungguhnya Kamilah yang akan melaksanakannya.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 105, "text": "وَلَقَدۡ كَتَبۡنَا فِی ٱلزَّبُورِ مِنۢ بَعۡدِ ٱلذِّكۡرِ أَنَّ ٱلۡأَرۡضَ یَرِثُهَا عِبَادِیَ ٱلصَّـٰلِحُونَ ۝١٠٥", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "ولقد كتبنا في الكتب المنزلة من بعد ما كُتِب في اللوح المحفوظ: أن الأرض يرثها عباد الله الصالحون الذين قاموا بما أُمروا به، واجتنبوا ما نُهوا عنه، وهم أمة محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "We have written in the Psalms, after the Reminder, that the earth will be inherited by My righteous servants.", "translation_id": "Dan sungguh telah Kami tulis didalam Zabur sesudah (Kami tulis dalam) Lauh Mahfuzh, bahwasanya bumi ini dipusakai hamba-hamba-Ku yang saleh.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 106, "text": "إِنَّ فِی هَـٰذَا لَبَلَـٰغࣰا لِّقَوۡمٍ عَـٰبِدِینَ ۝١٠٦", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "إن في هذا المتلوِّ من الموعظة لَعبرة كافية لقوم عابدين الله بما شرعه لهم ورضيه منهم.", "isBasmala": false, "translation_en": "Indeed, in this is a message for people who worship.", "translation_id": "Sesungguhnya (apa yang disebutkan) dalam (surat) ini, benar-benar menjadi peringatan bagi kaum yang menyembah (Allah).", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 107, "text": "وَمَاۤ أَرۡسَلۡنَـٰكَ إِلَّا رَحۡمَةࣰ لِّلۡعَـٰلَمِینَ ۝١٠٧", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "وما أرسلناك - أيها الرسول - إلا رحمة لجميع الناس، فمن آمن بك سَعِد ونجا، ومن لم يؤمن خاب وخسر.", "isBasmala": false, "translation_en": "We did not send you except as mercy to mankind.", "translation_id": "Dan tiadalah Kami mengutus kamu, melainkan untuk (menjadi) rahmat bagi semesta alam.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 108, "text": "قُلۡ إِنَّمَا یُوحَىٰۤ إِلَیَّ أَنَّمَاۤ إِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰحِدࣱۖ فَهَلۡ أَنتُم مُّسۡلِمُونَ ۝١٠٨", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "قل: إن الذي أُوحي إليَّ وبُعِثت به: أن إلهكم الذي يستحق العبادة وحده هو الله، فأسلموا له، وانقادوا لعبادته.", "isBasmala": false, "translation_en": "Say, \"It is revealed to me that your God is One God. Are you going to submit?\"", "translation_id": "Katakanlah: \"Sesungguhnya yang diwahyukan kepadaku adalah: \"Bahwasanya Tuhanmu adalah Tuhan Yang Esa. maka hendaklah kamu berserah diri (kepada-Nya)\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 109, "text": "فَإِن تَوَلَّوۡا۟ فَقُلۡ ءَاذَنتُكُمۡ عَلَىٰ سَوَاۤءࣲۖ وَإِنۡ أَدۡرِیۤ أَقَرِیبٌ أَم بَعِیدࣱ مَّا تُوعَدُونَ ۝١٠٩", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "فإن أعرض هؤلاء عن الإسلام فقل لهم: أبلغكم جميعًا ما أوحاه الله تعالى إليَّ، فأنا وأنتم مستوون في العلم لمَّا أنذرتكم وحذرتكم، ولستُ أعلم - بعد ذلك - متى يحل بكم ما وُعِدْتُم به من العذاب؟", "isBasmala": false, "translation_en": "But if they turn away, say, \"I have informed you sufficiently. Although I do not know whether what you are promised is near or far.\"", "translation_id": "Jika mereka berpaling, maka katakanlah: \"Aku telah menyampaikan kepada kamu sekalian (ajaran) yang sama (antara kita) dan aku tidak mengetahui apakah yang diancamkan kepadamu itu sudah dekat atau masih jauh?\".", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 110, "text": "إِنَّهُۥ یَعۡلَمُ ٱلۡجَهۡرَ مِنَ ٱلۡقَوۡلِ وَیَعۡلَمُ مَا تَكۡتُمُونَ ۝١١٠", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "إن الله يعلم ما تجهرون به من أقوالكم، وما تكتمونه في سرائركم، وسيحاسبكم عليه.", "isBasmala": false, "translation_en": "He knows what is said openly, and He knows what you conceal.", "translation_id": "Sesungguhnya Dia mengetahui perkataan (yang kamu ucapkan) dengan terang-terangan dan Dia mengetahui apa yang kamu rahasiakan.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 111, "text": "وَإِنۡ أَدۡرِی لَعَلَّهُۥ فِتۡنَةࣱ لَّكُمۡ وَمَتَـٰعٌ إِلَىٰ حِینࣲ ۝١١١", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "ولست أدري لعل تأخير العذاب الذي استعجلتموه استدراج لكم وابتلاء، وأن تتمتعوا في الدنيا إلى حين؛ لتزدادوا كفرًا، ثم يكون أعظم لعقوبتكم.", "isBasmala": false, "translation_en": "\"And I do not know whether it is perhaps a trial for you, and an enjoyment for a while.\"", "translation_id": "Dan aku tiada mengetahui, boleh jadi hal itu cobaan bagi kamu dan kesenangan sampai kepada suatu waktu.", "manzil": 4, "manzil_display": ""}, {"sura": 21, "sura_name": "الأنبياء", "revelation": "Makkiyah", "aya": 112, "text": "قَـٰلَ رَبِّ ٱحۡكُم بِٱلۡحَقِّۗ وَرَبُّنَا ٱلرَّحۡمَـٰنُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ ۝١١٢", "juz": 17, "hizb": "(*¾ ح 33*)", "tafsir": "قال النبي صلى الله عليه وسلم: ربِّ افصل بيننا وبين قومنا المكذبين بالقضاء الحق. ونسأل ربنا الرحمن، ونستعين به على ما تَصِفونه - أيها الكفار - من الشرك والتكذيب والافتراء عليه، وما تتوعدونا به من الظهور والغلبة.", "isBasmala": false, "translation_en": "He said, \"My Lord, judge with justice.\" And, \"Our Lord is the Gracious, Whose help is sought against what you allege.\"", "translation_id": "(Muhammad) berkata: \"Ya Tuhanku, berilah keputusan dengan adil. Dan Tuhan kami ialah Tuhan Yang Maha Pemurah lagi Yang dimohonkan pertolongan-Nya terhadap apa yang kamu katakan\".", "manzil": 4, "manzil_display": ""}], "332": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 17, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 1, "text": "۞ یَـٰۤأَیُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمۡۚ إِنَّ زَلۡزَلَةَ ٱلسَّاعَةِ شَیۡءٌ عَظِیمࣱ ۝١", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "يا أيها الناس احذروا عقاب الله بامتثال أوامره واجتناب نواهيه، إن ما يحدث عند قيام الساعة من أهوال وحركة شديدة للأرض، تتصدع منها كل جوانبها، شيء عظيم، لا يُقْدر قدره ولا يُبْلغ كنهه، ولا يعلم كيفيَّته إلا رب العالمين.", "isBasmala": false, "translation_en": "O people, be conscious of your Lord. The quaking of the Hour is a tremendous thing.", "translation_id": "Hai manusia, bertakwalah kepada Tuhanmu; sesungguhnya kegoncangan hari kiamat itu adalah suatu kejadian yang sangat besar (dahsyat).", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 2, "text": "یَوۡمَ تَرَوۡنَهَا تَذۡهَلُ كُلُّ مُرۡضِعَةٍ عَمَّاۤ أَرۡضَعَتۡ وَتَضَعُ كُلُّ ذَاتِ حَمۡلٍ حَمۡلَهَا وَتَرَى ٱلنَّاسَ سُكَـٰرَىٰ وَمَا هُم بِسُكَـٰرَىٰ وَلَـٰكِنَّ عَذَابَ ٱللَّهِ شَدِیدࣱ ۝٢", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "يوم ترون قيام الساعة تنسى الوالدةُ رضيعَها الذي ألقمته ثديها؛ لِمَا نزل بها من الكرب، وتُسْقط الحامل حملها من الرعب، وتغيب عقول للناس، فهم كالسكارى من شدة الهول والفزع، وليسوا بسكارى من الخمر، ولكن شدة العذاب أفقدتهم عقولهم وإدراكهم.", "isBasmala": false, "translation_en": "On the Day when you will see it: every nursing mother will discard her infant, and every pregnant woman will abort her load, and you will see the people drunk, even though they are not drunk-but the punishment of God is severe.", "translation_id": "(Ingatlah) pada hari (ketika) kamu melihat kegoncangan itu, lalailah semua wanita yang menyusui anaknya dari anak yang disusuinya dan gugurlah kandungan segala wanita yang hamil, dan kamu lihat manusia dalam keadaan mabuk, padahal sebenarnya mereka tidak mabuk, akan tetapi azab Allah itu sangat kerasnya.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 3, "text": "وَمِنَ ٱلنَّاسِ مَن یُجَـٰدِلُ فِی ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَیَتَّبِعُ كُلَّ شَیۡطَـٰنࣲ مَّرِیدࣲ ۝٣", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "وبعض رؤوس الكفر من الناس يخاصمون ويشككون في قدرة الله على البعث؛ جهلا منهم بحقيقة هذه القدرة، واتباعًا لأئمة الضلال من كل شيطان متمرد على الله ورسله.", "isBasmala": false, "translation_en": "Among the people is he who argues about God without knowledge, and follows every defiant devil.", "translation_id": "Di antara manusia ada orang yang membantah tentang Allah tanpa ilmu pengetahuan dan mengikuti setiap syaitan yang jahat,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 4, "text": "كُتِبَ عَلَیۡهِ أَنَّهُۥ مَن تَوَلَّاهُ فَأَنَّهُۥ یُضِلُّهُۥ وَیَهۡدِیهِ إِلَىٰ عَذَابِ ٱلسَّعِیرِ ۝٤", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "قضى الله وقدَّر على هذا الشيطان أنه يُضِل كل من اتبعه، ولا يهديه إلى الحق، بل يسوقه إلى عذاب جهنم الموقدة جزاء اتباعه إياه.", "isBasmala": false, "translation_en": "It was decreed for him, that whoever follows him-he will misguide him, and lead him to the torment of the Blaze.", "translation_id": "yang telah ditetapkan terhadap syaitan itu, bahwa barangsiapa yang berkawan dengan dia, tentu dia akan menyesatkannya, dan membawanya ke azab neraka.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 5, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ إِن كُنتُمۡ فِی رَیۡبࣲ مِّنَ ٱلۡبَعۡثِ فَإِنَّا خَلَقۡنَـٰكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ مِنۡ عَلَقَةࣲ ثُمَّ مِن مُّضۡغَةࣲ مُّخَلَّقَةࣲ وَغَیۡرِ مُخَلَّقَةࣲ لِّنُبَیِّنَ لَكُمۡۚ وَنُقِرُّ فِی ٱلۡأَرۡحَامِ مَا نَشَاۤءُ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى ثُمَّ نُخۡرِجُكُمۡ طِفۡلࣰا ثُمَّ لِتَبۡلُغُوۤا۟ أَشُدَّكُمۡۖ وَمِنكُم مَّن یُتَوَفَّىٰ وَمِنكُم مَّن یُرَدُّ إِلَىٰۤ أَرۡذَلِ ٱلۡعُمُرِ لِكَیۡلَا یَعۡلَمَ مِنۢ بَعۡدِ عِلۡمࣲ شَیۡـࣰٔاۚ وَتَرَى ٱلۡأَرۡضَ هَامِدَةࣰ فَإِذَاۤ أَنزَلۡنَا عَلَیۡهَا ٱلۡمَاۤءَ ٱهۡتَزَّتۡ وَرَبَتۡ وَأَنۢبَتَتۡ مِن كُلِّ زَوۡجِۭ بَهِیجࣲ ۝٥", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "يا أيها الناس إن كنتم في شك من أن الله يُحيي الموتى فإنَّا خلقنا أباكم آدم من تراب، ثم تناسلت ذريته من نطفة، هي المنيُّ يقذفه الرجل في رحم المرأة، فيتحول بقدرة الله إلى علقة، وهي الدم الأحمر الغليظ، ثم إلى مضغة، وهي قطعة لحم صغيرة قَدْر ما يُمْضَغ، فتكون تارة مخلَّقة، أي تامة الخلق تنتهي إلى خروح الجنين حيًا، وغير تامة الخلق تارة أخرى، فتسقط لغير تمام؛ لنبيِّن لكم تمام قدرتنا بتصريف أطوار الخلق، ونبقي في الأرحام ما نشاء، وهو المخلَّق إلى وقت ولادته، وتكتمل الأطوار بولادة الأجنَّة أطفالا صغارًا تكبَرُ حتى تبلغ الأشد، وهو وقت الشباب والقوة واكتمال العقل، وبعض الأطفال قد يموت قبل ذلك، وبعضهم يكبَرُ حتى يبلغ سن الهرم وضَعْف العقل؛ فلا يعلم هذا المعمَّر شيئًا مما كان يعلمه قبل ذلك. وترى الأرض يابسةً ميتة لا نبات فيها، فإذا أنزلنا عليها الماء تحركت بالنبات تتفتح عنه، وارتفعت وزادت لارتوائها، وأنبتت من كل نوع من أنواع النبات الحسن الذي يَسُرُّ الناظرين.", "isBasmala": false, "translation_en": "O people! If you are in doubt about the Resurrection-We created you from dust, then from a small drop, then from a clinging clot, then from a lump of flesh, partly developed and partly undeveloped. In order to clarify things for you. And We settle in the wombs whatever We will for a designated term, and then We bring you out as infants, until you reach your full strength. And some of you will pass away, and some of you will be returned to the vilest age, so that he may not know, after having known. And you see the earth still; but when We send down water on it, it vibrates, and swells, and grows all kinds of lovely pairs.", "translation_id": "Hai manusia, jika kamu dalam keraguan tentang kebangkitan (dari kubur), maka (ketahuilah) sesungguhnya Kami telah menjadikan kamu dari tanah, kemudian dari setetes mani, kemudian dari segumpal darah, kemudian dari segumpal daging yang sempurna kejadiannya dan yang tidak sempurna, agar Kami jelaskan kepada kamu dan Kami tetapkan dalam rahim, apa yang Kami kehendaki sampai waktu yang sudah ditentukan, kemudian Kami keluarkan kamu sebagai bayi, kemudian (dengan berangsur-angsur) kamu sampailah kepada kedewasaan, dan di antara kamu ada yang diwafatkan dan (adapula) di antara kamu yang dipanjangkan umurnya sampai pikun, supaya dia tidak mengetahui lagi sesuatupun yang dahulunya telah diketahuinya. Dan kamu lihat bumi ini kering, kemudian apabila telah Kami turunkan air di atasnya, hiduplah bumi itu dan suburlah dan menumbuhkan berbagai macam tumbuh-tumbuhan yang indah.", "manzil": 4, "manzil_display": ""}], "333": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 6, "text": "ذَ ٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ یُحۡیِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٦", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "ذلك المذكور مما تقدَّم من آيات قدرة الله تعالى، فيه دلالة قاطعة على أن الله سبحانه وتعالى هو الرب المعبود بحق، الذي لا تنبغي العبادة إلا له، وهو يُحيي الموتى، وهو قادر على كل شيء.", "isBasmala": false, "translation_en": "That is because God is the truth, and because He gives life to the dead, and because He is Capable of everything.", "translation_id": "Yang demikian itu, karena sesungguhnya Allah, Dialah yang haq dan sesungguhnya Dialah yang menghidupkan segala yang mati dan sesungguhnya Allah Maha Kuasa atas segala sesuatu,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 7, "text": "وَأَنَّ ٱلسَّاعَةَ ءَاتِیَةࣱ لَّا رَیۡبَ فِیهَا وَأَنَّ ٱللَّهَ یَبۡعَثُ مَن فِی ٱلۡقُبُورِ ۝٧", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "وأن ساعة البعث آتية، لا شك في ذلك، وأن الله يبعث الموتى مِن قبورهم لحسابهم وجزائهم.", "isBasmala": false, "translation_en": "And because the Hour is coming-there is no doubt about it-and because God will resurrect those in the graves.", "translation_id": "dan sesungguhnya hari kiamat itu pastilah datang, tak ada keraguan padanya; dan bahwasanya Allah membangkitkan semua orang di dalam kubur.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 8, "text": "وَمِنَ ٱلنَّاسِ مَن یُجَـٰدِلُ فِی ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَلَا هُدࣰى وَلَا كِتَـٰبࣲ مُّنِیرࣲ ۝٨", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "ومن الكفار مَن يجادل بالباطل في الله وتوحيده واختياره رسوله صلى الله عليه وسلم وإنزاله القرآن، وذلك الجدال بغير علم، ولا بيان، ولا كتاب من الله فيه برهان وحجة واضحة، لاويًا عنقه في تكبر، معرضًا عن الحق؛ ليصد غيره عن الدخول في دين الله، فسوف يلقى خزيًا في الدنيا باندحاره وافتضاح أمره، ونحرقه يوم القيامة بالنار.", "isBasmala": false, "translation_en": "And among the people is he who argues about God without knowledge, or guidance, or an enlightening scripture.", "translation_id": "Dan di antara manusia ada orang-orang yang membantah tentang Allah tanpa ilmu pengetahuan, tanpa petunjuk dan tanpa kitab (wahyu) yang bercahaya,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 9, "text": "ثَانِیَ عِطۡفِهِۦ لِیُضِلَّ عَن سَبِیلِ ٱللَّهِۖ لَهُۥ فِی ٱلدُّنۡیَا خِزۡیࣱۖ وَنُذِیقُهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ عَذَابَ ٱلۡحَرِیقِ ۝٩", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "ومن الكفار مَن يجادل بالباطل في الله وتوحيده واختياره رسوله صلى الله عليه وسلم وإنزاله القرآن، وذلك الجدال بغير علم، ولا بيان، ولا كتاب من الله فيه برهان وحجة واضحة، لاويًا عنقه في تكبر، معرضًا عن الحق؛ ليصد غيره عن الدخول في دين الله، فسوف يلقى خزيًا في الدنيا باندحاره وافتضاح أمره، ونحرقه يوم القيامة بالنار.", "isBasmala": false, "translation_en": "Turning aside in contempt, to lead away from the path of God. He will have humiliation in this world, and on the Day of Resurrection We will make him taste the agony of burning.", "translation_id": "dengan memalingkan lambungnya untuk menyesatkan manusia dari jalan Allah. Ia mendapat kehinaan di dunia dan dihari kiamat Kami merasakan kepadanya azab neraka yang membakar.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 10, "text": "ذَ ٰلِكَ بِمَا قَدَّمَتۡ یَدَاكَ وَأَنَّ ٱللَّهَ لَیۡسَ بِظَلَّـٰمࣲ لِّلۡعَبِیدِ ۝١٠", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "ويقال له: ذلك العذاب بسبب ما فَعَلْتَ من المعاصي واكتسبت من الآثام، والله لا يعذب أحدًا بغير ذنب.", "isBasmala": false, "translation_en": "That is for what your hands have advanced, and because God is not unjust to the servants.", "translation_id": "(Akan dikatakan kepadanya): \"Yang demikian itu, adalah disebabkan perbuatan yang dikerjakan oleh kedua tangan kamu dahulu dan sesungguhnya Allah sekali-kali bukanlah penganiaya hamba-hamba-Nya\".", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 11, "text": "وَمِنَ ٱلنَّاسِ مَن یَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفࣲۖ فَإِنۡ أَصَابَهُۥ خَیۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةَۚ ذَ ٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِینُ ۝١١", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "ومن الناس مَن يدخل في الإسلام على ضعف وشكٍّ، فيعبد الله على تردده، كالذي يقف على طرف جبل أو حائط لا يتماسك في وقفته، ويربط إيمانه بدنياه، فإن عاش في صحة وسَعَة استمر على عبادته، وإن حصل له ابتلاء بمكروه وشدة عزا شؤم ذلك إلى دينه، فرجع عنه كمن ينقلب على وجهه بعد استقامة، فهو بذلك قد خسر الدنيا؛ إذ لا يغيِّر كفرُه ما قُدِّر له في دنياه، وخسر الآخرة بدخوله النار، وذلك خسران بيِّن واضح. يعبد ذلك الخاسر من دون الله ما لا يضره إن تركه، ولا ينفعه إذا عبده، ذلك هو الضلال البعيد عن الحق. يدعو مَن ضررُه المحقق أقرب من نفعه، قبح ذلك المعبود نصيرًا، وقبح عشيرًا.", "isBasmala": false, "translation_en": "And among the people is he who worships God on edge. When something good comes his way, he is content with it. But when an ordeal strikes him, he makes a turnaround. He loses this world and the next. That is the obvious loss.", "translation_id": "Dan di antara manusia ada orang yang menyembah Allah dengan berada di tepi; maka jika ia memperoleh kebajikan, tetaplah ia dalam keadaan itu, dan jika ia ditimpa oleh suatu bencana, berbaliklah ia ke belakang. Rugilah ia di dunia dan di akhirat. Yang demikian itu adalah kerugian yang nyata.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 12, "text": "یَدۡعُوا۟ مِن دُونِ ٱللَّهِ مَا لَا یَضُرُّهُۥ وَمَا لَا یَنفَعُهُۥۚ ذَ ٰلِكَ هُوَ ٱلضَّلَـٰلُ ٱلۡبَعِیدُ ۝١٢", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "ومن الناس مَن يدخل في الإسلام على ضعف وشكٍّ، فيعبد الله على تردده، كالذي يقف على طرف جبل أو حائط لا يتماسك في وقفته، ويربط إيمانه بدنياه، فإن عاش في صحة وسَعَة استمر على عبادته، وإن حصل له ابتلاء بمكروه وشدة عزا شؤم ذلك إلى دينه، فرجع عنه كمن ينقلب على وجهه بعد استقامة، فهو بذلك قد خسر الدنيا؛ إذ لا يغيِّر كفرُه ما قُدِّر له في دنياه، وخسر الآخرة بدخوله النار، وذلك خسران بيِّن واضح. يعبد ذلك الخاسر من دون الله ما لا يضره إن تركه، ولا ينفعه إذا عبده، ذلك هو الضلال البعيد عن الحق. يدعو مَن ضررُه المحقق أقرب من نفعه، قبح ذلك المعبود نصيرًا، وقبح عشيرًا.", "isBasmala": false, "translation_en": "He invokes, instead of God, what can neither harm him nor benefit him. That is the far straying.", "translation_id": "Ia menyeru selain Allah, sesuatu yang tidak dapat memberi mudharat dan tidak (pula) memberi manfaat kepadanya. Yang demikian itu adalah kesesatan yang jauh.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 13, "text": "یَدۡعُوا۟ لَمَن ضَرُّهُۥۤ أَقۡرَبُ مِن نَّفۡعِهِۦۚ لَبِئۡسَ ٱلۡمَوۡلَىٰ وَلَبِئۡسَ ٱلۡعَشِیرُ ۝١٣", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "ومن الناس مَن يدخل في الإسلام على ضعف وشكٍّ، فيعبد الله على تردده، كالذي يقف على طرف جبل أو حائط لا يتماسك في وقفته، ويربط إيمانه بدنياه، فإن عاش في صحة وسَعَة استمر على عبادته، وإن حصل له ابتلاء بمكروه وشدة عزا شؤم ذلك إلى دينه، فرجع عنه كمن ينقلب على وجهه بعد استقامة، فهو بذلك قد خسر الدنيا؛ إذ لا يغيِّر كفرُه ما قُدِّر له في دنياه، وخسر الآخرة بدخوله النار، وذلك خسران بيِّن واضح. يعبد ذلك الخاسر من دون الله ما لا يضره إن تركه، ولا ينفعه إذا عبده، ذلك هو الضلال البعيد عن الحق. يدعو مَن ضررُه المحقق أقرب من نفعه، قبح ذلك المعبود نصيرًا، وقبح عشيرًا.", "isBasmala": false, "translation_en": "He invokes one whose harm is closer than his benefit. What a miserable master. What a miserable companion.", "translation_id": "Ia menyeru sesuatu yang sebenarnya mudharatnya lebih dekat dari manfaatnya. Sesungguhnya yang diserunya itu adalah sejahat-jahat kawan.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 14, "text": "إِنَّ ٱللَّهَ یُدۡخِلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۚ إِنَّ ٱللَّهَ یَفۡعَلُ مَا یُرِیدُ ۝١٤", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "إن الله يدخل الذين آمنوا بالله ورسوله، وثبتوا على ذلك، وعملوا الصالحات، جنات تجري من تحت أشجارها الأنهار، إن الله يفعل ما يريد من ثواب أهل طاعته تفضلا وعقاب أهل معصيته عدلا.", "isBasmala": false, "translation_en": "God will admit those who believe and do righteous deeds into Gardens beneath which rivers flow. God does whatever He wills.", "translation_id": "Sesungguhnya Allah memasukkan orang-orang yang beriman dan mengerjakan amal yang saleh ke dalam surga-surga yang di bawahnya mengalir sungai-sungai. Sesungguhnya Allah berbuat apa yang Dia kehendaki.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 15, "text": "مَن كَانَ یَظُنُّ أَن لَّن یَنصُرَهُ ٱللَّهُ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ فَلۡیَمۡدُدۡ بِسَبَبٍ إِلَى ٱلسَّمَاۤءِ ثُمَّ لۡیَقۡطَعۡ فَلۡیَنظُرۡ هَلۡ یُذۡهِبَنَّ كَیۡدُهُۥ مَا یَغِیظُ ۝١٥", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "من كان يعتقد أن الله تعالى لن يؤيد رسوله محمدًا بالنصر في الدنيا بإظهار دينه، وفي الآخرة بإعلاء درجته، وعذابِ مَن كذَّبه، فلْيَمدُدْ حبلا إلى سقف بيته وليخنق به نفسه، ثم ليقطع ذلك الحبل، ثم لينظر: هل يُذْهِبنَّ ذلك ما يجد في نفسه من الغيظ؟ فإن الله تعالى ناصرٌ نبيه محمدًا صلى الله عليه وسلم لا محالة.", "isBasmala": false, "translation_en": "Whoever thinks that God will not help him in this life and in the Hereafter-let him turn to heaven, then sever, and see if his cunning eliminates what enrages him.", "translation_id": "Barangsiapa yang menyangka bahwa Allah sekali-kali tiada menolongnya (Muhammad) di dunia dan akhirat, maka hendaklah ia merentangkan tali ke langit, kemudian hendaklah ia melaluinya, kemudian hendaklah ia pikirkan apakah tipu dayanya itu dapat melenyapkan apa yang menyakitkan hatinya.", "manzil": 4, "manzil_display": ""}], "334": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 16, "text": "وَكَذَ ٰلِكَ أَنزَلۡنَـٰهُ ءَایَـٰتِۭ بَیِّنَـٰتࣲ وَأَنَّ ٱللَّهَ یَهۡدِی مَن یُرِیدُ ۝١٦", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "وكما أقام الله الحجة من دلائل قدرته على الكافرين بالبعث أنزل القرآن، آياته واضحة في لفظها ومعناها، يهدي بها الله مَن أراد هدايته؛ لأنه لا هادي سواه.", "isBasmala": false, "translation_en": "Thus We revealed it as clarifying signs, and God guides whomever He wills.", "translation_id": "Dan demikianlah Kami telah menurunkan Al Quran yang merupakan ayat-ayat yang nyata, dan bahwasanya Allah memberikan petunjuk kepada siapa yang Dia kehendaki.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 17, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَٱلَّذِینَ هَادُوا۟ وَٱلصَّـٰبِـِٔینَ وَٱلنَّصَـٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِینَ أَشۡرَكُوۤا۟ إِنَّ ٱللَّهَ یَفۡصِلُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ ۝١٧", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "إن الذين آمنوا بالله ورسوله محمدٍ صلى الله عليه وسلم واليهود والصابئين وهم: (قوم باقون على فطرتهم ولا دين مقرر لهم يتبعونه) والنصارى والمجوس (وهم عبدة النار) والذين أشركوا وهم: عبدة الأوثان، إنَّ الله يفصل بينهم جميعًا يوم القيامة فيدخل المؤمنين الجنة، ويدخل الكافرين النار، إن الله على كل شيء شهيد، شهد أعمال العباد كلَّها، وأحصاها وحفظها، وسيجازي كلا بما يستحق جزاء وفاقًا للأعمال التي عملوها.", "isBasmala": false, "translation_en": "Those who believe, and those who are Jewish, and the Sabeans, and the Christians, and the Zoroastrians, and the Polytheists-God will judge between them on the Day of Resurrection. God is witness to all things.", "translation_id": "Sesungguhnya orang-orang yang beriman, orang-orang Yahudi, orang-orang Shaabi-iin orang-orang Nasrani, orang-orang Majusi dan orang-orang musyrik, Allah akan memberi keputusan di antara mereka pada hari kiamat. Sesungguhnya Allah menyaksikan segala sesuatu.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 18, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ یَ̅سۡ̅جُ̅دُ̅ ̅لَ̅هُ̅ۥ̅ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَمَن فِی ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَاۤبُّ وَكَثِیرࣱ مِّنَ ٱلنَّاسِۖ وَكَثِیرٌ حَقَّ عَلَیۡهِ ٱلۡعَذَابُۗ وَمَن یُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ یَفۡعَلُ مَا یَشَاۤءُ ۝١٨ ۩", "juz": 17, "hizb": "(* ح 34*)", "tafsir": "ألم تعلم- أيها النبي- أن الله سبحانه يسجد له خاضعًا منقادًا مَن في السموات من الملائكة ومَن في الأرض من المخلوقات والشمس والقمر والنجوم والجبال والشجر والدواب؟ ولله يسجد طاعة واختيارًا كثير من الناس، وهم المؤمنون، وكثير من الناس حق عليه العذاب فهو مهين، وأيُّ إنسان يهنه الله فليس له أحد يكرمه. إن الله يفعل في خلقه ما يشاء وَفْقَ حكمته.", "isBasmala": false, "translation_en": "Do you not realize that to God prostrates everyone in the heavens and everyone on earth, and the sun, and the moon, and the stars, and the mountains, and the trees, and the animals, and many of the people? But many are justly deserving of punishment. Whomever God shames, there is none to honor him. God does whatever He wills.", "translation_id": "Apakah kamu tiada mengetahui, bahwa kepada Allah bersujud apa yang ada di langit, di bumi, matahari, bulan, bintang, gunung, pohon-pohonan, binatang-binatang yang melata dan sebagian besar daripada manusia? Dan banyak di antara manusia yang telah ditetapkan azab atasnya. Dan barangsiapa yang dihinakan Allah maka tidak seorangpun yang memuliakannya. Sesungguhnya Allah berbuat apa yang Dia kehendaki.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 19, "text": "۞ هَـٰذَانِ خَصۡمَانِ ٱخۡتَصَمُوا۟ فِی رَبِّهِمۡۖ فَٱلَّذِینَ كَفَرُوا۟ قُطِّعَتۡ لَهُمۡ ثِیَابࣱ مِّن نَّارࣲ یُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِیمُ ۝١٩", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "هذان فريقان اختلفوا في ربهم: أهل الإيمان وأهل الكفر، كل يدَّعي أنه محقٌّ، فالذين كفروا يحيط بهم العذاب في هيئة ثياب جُعلت لهم من نار يَلْبَسونها، فتشوي أجسادهم، ويُصبُّ على رؤوسهم الماء المتناهي في حره، ويَنزِل إلى أجوافهم فيذيب ما فيها، حتى ينفُذ إلى جلودهم فيشويها فتسقط، وتضربهم الملائكة على رؤوسهم بمطارق من حديد. كلما حاولوا الخروج من النار -لشدة غمِّهم وكربهم- أعيدوا للعذاب فيها، وقيل لهم: ذوقوا عذاب النار المحرق.", "isBasmala": false, "translation_en": "Here are two adversaries feuding regarding their Lord. As for those who disbelieve, garments of fire will be tailored for them, and scalding water will be poured over their heads.", "translation_id": "Inilah dua golongan (golongan mukmin dan golongan kafir) yang bertengkar, mereka saling bertengkar mengenai Tuhan mereka. Maka orang kafir akan dibuatkan untuk mereka pakaian-pakaian dari api neraka. Disiramkan air yang sedang mendidih ke atas kepala mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 20, "text": "یُصۡهَرُ بِهِۦ مَا فِی بُطُونِهِمۡ وَٱلۡجُلُودُ ۝٢٠", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "هذان فريقان اختلفوا في ربهم: أهل الإيمان وأهل الكفر، كل يدَّعي أنه محقٌّ، فالذين كفروا يحيط بهم العذاب في هيئة ثياب جُعلت لهم من نار يَلْبَسونها، فتشوي أجسادهم، ويُصبُّ على رؤوسهم الماء المتناهي في حره، ويَنزِل إلى أجوافهم فيذيب ما فيها، حتى ينفُذ إلى جلودهم فيشويها فتسقط، وتضربهم الملائكة على رؤوسهم بمطارق من حديد. كلما حاولوا الخروج من النار -لشدة غمِّهم وكربهم- أعيدوا للعذاب فيها، وقيل لهم: ذوقوا عذاب النار المحرق.", "isBasmala": false, "translation_en": "Melting their insides and their skins.", "translation_id": "Dengan air itu dihancur luluhkan segala apa yang ada dalam perut mereka dan juga kulit (mereka).", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 21, "text": "وَلَهُم مَّقَـٰمِعُ مِنۡ حَدِیدࣲ ۝٢١", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "هذان فريقان اختلفوا في ربهم: أهل الإيمان وأهل الكفر، كل يدَّعي أنه محقٌّ، فالذين كفروا يحيط بهم العذاب في هيئة ثياب جُعلت لهم من نار يَلْبَسونها، فتشوي أجسادهم، ويُصبُّ على رؤوسهم الماء المتناهي في حره، ويَنزِل إلى أجوافهم فيذيب ما فيها، حتى ينفُذ إلى جلودهم فيشويها فتسقط، وتضربهم الملائكة على رؤوسهم بمطارق من حديد. كلما حاولوا الخروج من النار -لشدة غمِّهم وكربهم- أعيدوا للعذاب فيها، وقيل لهم: ذوقوا عذاب النار المحرق.", "isBasmala": false, "translation_en": "And they will have maces of iron.", "translation_id": "Dan untuk mereka cambuk-cambuk dari besi.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 22, "text": "كُلَّمَاۤ أَرَادُوۤا۟ أَن یَخۡرُجُوا۟ مِنۡهَا مِنۡ غَمٍّ أُعِیدُوا۟ فِیهَا وَذُوقُوا۟ عَذَابَ ٱلۡحَرِیقِ ۝٢٢", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "هذان فريقان اختلفوا في ربهم: أهل الإيمان وأهل الكفر، كل يدَّعي أنه محقٌّ، فالذين كفروا يحيط بهم العذاب في هيئة ثياب جُعلت لهم من نار يَلْبَسونها، فتشوي أجسادهم، ويُصبُّ على رؤوسهم الماء المتناهي في حره، ويَنزِل إلى أجوافهم فيذيب ما فيها، حتى ينفُذ إلى جلودهم فيشويها فتسقط، وتضربهم الملائكة على رؤوسهم بمطارق من حديد. كلما حاولوا الخروج من النار -لشدة غمِّهم وكربهم- أعيدوا للعذاب فيها، وقيل لهم: ذوقوا عذاب النار المحرق.", "isBasmala": false, "translation_en": "Whenever they try to escape the gloom, they will be driven back to it: \"Taste the suffering of burning.\"", "translation_id": "Setiap kali mereka hendak ke luar dari neraka lantaran kesengsaraan mereka, niscaya mereka dikembalikan ke dalamnya. (Kepada mereka dikatakan), \"Rasailah azab yang membakar ini\".", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 23, "text": "إِنَّ ٱللَّهَ یُدۡخِلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ یُحَلَّوۡنَ فِیهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَلُؤۡلُؤࣰاۖ وَلِبَاسُهُمۡ فِیهَا حَرِیرࣱ ۝٢٣", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "إن الله تعالى يدخل أهل الإيمان والعمل الصالح جنات نعيمها دائم، تجري مِن تحت أشجارها الأنهار، يُزَيَّنون فيها بأساور الذهب وباللؤلؤ، ولباسهم المعتاد في الجنة الحرير رجالا ونساءً.", "isBasmala": false, "translation_en": "But God will admit those who believe and do good deeds into Gardens beneath which rivers flow. They will be decorated therein with bracelets of gold and pearls, and their garments therein will be of silk.", "translation_id": "Sesungguhnya Allah memasukkan orang-orang beriman dan mengerjakan amal yang saleh ke dalam surga-surga yang di bawahnya mengalir sungai-sungai. Di surga itu mereka diberi perhiasan dengan gelang-gelang dari emas dan mutiara, dan pakaian mereka adalah sutera.", "manzil": 4, "manzil_display": ""}], "335": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 24, "text": "وَهُدُوۤا۟ إِلَى ٱلطَّیِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوۤا۟ إِلَىٰ صِرَ ٰطِ ٱلۡحَمِیدِ ۝٢٤", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "لقد هداهم الله في الدنيا إلى طيب القول: من كلمة التوحيد وحَمْد الله والثناء عليه، وفي الآخرة إلى حمده على حسن العاقبة، كما هداهم من قبل إلى طريق الإسلام المحمود الموصل إلى الجنة.", "isBasmala": false, "translation_en": "They were guided to purity of speech. They were guided to the path of the Most Praised.", "translation_id": "Dan mereka diberi petunjuk kepada ucapan-ucapan yang baik dan ditunjuki (pula) kepada jalan (Allah) yang terpuji.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 25, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَیَصُدُّونَ عَن سَبِیلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِی جَعَلۡنَـٰهُ لِلنَّاسِ سَوَاۤءً ٱلۡعَـٰكِفُ فِیهِ وَٱلۡبَادِۚ وَمَن یُرِدۡ فِیهِ بِإِلۡحَادِۭ بِظُلۡمࣲ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِیمࣲ ۝٢٥", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "إن الذين كفروا بالله، وكذبوا بما جاءهم به محمد صلى الله عليه وسلم، ويمنعون غيرهم من الدخول في دين الله، ويصدون رسول الله صلى الله عليه وسلم والمؤمنين في عام \"الحديبية\" عن المسجد الحرام، الذي جعلناه لجميع المؤمنين، سواء المقيم فيه والقادم إليه، لهم عذاب أليم موجع، ومن يرد في المسجد الحرام الميْلَ عن الحق ظلمًا فيَعْصِ الله فيه، نُذِقْه مِن عذاب أليم موجع.", "isBasmala": false, "translation_en": "As for those who disbelieve and repel from God's path and from the Sacred Mosque-which We have designated for all mankind equally, whether residing therein or passing through-and seek to commit sacrilege therein-We will make him taste of a painful punishment.", "translation_id": "Sesungguhnya orang-orang yang kafir dan menghalangi manusia dari jalan Allah dan Masjidilharam yang telah Kami jadikan untuk semua manusia, baik yang bermukim di situ maupun di padang pasir dan siapa yang bermaksud di dalamnya melakukan kejahatan secara zalim, niscaya akan Kami rasakan kepadanya sebahagian siksa yang pedih.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 26, "text": "وَإِذۡ بَوَّأۡنَا لِإِبۡرَ ٰهِیمَ مَكَانَ ٱلۡبَیۡتِ أَن لَّا تُشۡرِكۡ بِی شَیۡـࣰٔا وَطَهِّرۡ بَیۡتِیَ لِلطَّاۤىِٕفِینَ وَٱلۡقَاۤىِٕمِینَ وَٱلرُّكَّعِ ٱلسُّجُودِ ۝٢٦", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "واذكر- أيها النبي- إذ بَيَّنا لإبراهيم - عليه السلام- مكان البيت، وهيَّأناه له وقد كان غير معروف، وأمرناه ببنائه على تقوى من الله وتوحيده وتطهيره من الكفر والبدع والنجاسات؛ ليكون رحابًا للطائفين به، والقائمين المصلين عنده.", "isBasmala": false, "translation_en": "We showed Abraham the location of the House: \"Do not associate anything with Me; and purify My House for those who circle around, and those who stand to pray, and those who kneel and prostrate.\"", "translation_id": "Dan (ingatlah), ketika Kami memberikan tempat kepada Ibrahim di tempat Baitullah (dengan mengatakan): \"Janganlah kamu memperserikatkan sesuatupun dengan Aku dan sucikanlah rumah-Ku ini bagi orang-orang yang thawaf, dan orang-orang yang beribadat dan orang-orang yang ruku' dan sujud.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 27, "text": "وَأَذِّن فِی ٱلنَّاسِ بِٱلۡحَجِّ یَأۡتُوكَ رِجَالࣰا وَعَلَىٰ كُلِّ ضَامِرࣲ یَأۡتِینَ مِن كُلِّ فَجٍّ عَمِیقࣲ ۝٢٧", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "وأعلِمْ- يا إبراهيم- الناس بوجوب الحج عليهم يأتوك على مختلف أحوالهم مشاةً وركبانًا على كل ضامر من الإبل، وهو: (الخفيف اللحم من السَّيْر والأعمال لا من الهُزال)، يأتين من كل طريق بعيد؛ ليحضروا منافع لهم من: مغفرة ذنوبهم، وثواب أداء نسكهم وطاعتهم، وتكَسُّبِهم في تجاراتهم، وغير ذلك؛ وليذكروا اسم الله على ذَبْح ما يتقربون به من الإبل والبقر والغنم في أيام معيَّنة هي: عاشر ذي الحجة وثلاثة أيام بعده؛ شكرًا لله على نعمه، وهم مأمورون أن يأكلوا مِن هذه الذبائح استحبابًا، ويُطعموا منها الفقير الذي اشتد فقره.", "isBasmala": false, "translation_en": "And announce the pilgrimage to humanity. They will come to you on foot, and on every transport. They will come from every distant point.", "translation_id": "Dan berserulah kepada manusia untuk mengerjakan haji, niscaya mereka akan datang kepadamu dengan berjalan kaki, dan mengendarai unta yang kurus yang datang dari segenap penjuru yang jauh,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 28, "text": "لِّیَشۡهَدُوا۟ مَنَـٰفِعَ لَهُمۡ وَیَذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ فِیۤ أَیَّامࣲ مَّعۡلُومَـٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِیمَةِ ٱلۡأَنۡعَـٰمِۖ فَكُلُوا۟ مِنۡهَا وَأَطۡعِمُوا۟ ٱلۡبَاۤىِٕسَ ٱلۡفَقِیرَ ۝٢٨", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "وأعلِمْ- يا إبراهيم- الناس بوجوب الحج عليهم يأتوك على مختلف أحوالهم مشاةً وركبانًا على كل ضامر من الإبل، وهو: (الخفيف اللحم من السَّيْر والأعمال لا من الهُزال)، يأتين من كل طريق بعيد؛ ليحضروا منافع لهم من: مغفرة ذنوبهم، وثواب أداء نسكهم وطاعتهم، وتكَسُّبِهم في تجاراتهم، وغير ذلك؛ وليذكروا اسم الله على ذَبْح ما يتقربون به من الإبل والبقر والغنم في أيام معيَّنة هي: عاشر ذي الحجة وثلاثة أيام بعده؛ شكرًا لله على نعمه، وهم مأمورون أن يأكلوا مِن هذه الذبائح استحبابًا، ويُطعموا منها الفقير الذي اشتد فقره.", "isBasmala": false, "translation_en": "That they may witness the benefits for themselves, and celebrate the name of God during the appointed days, for providing them with the animal livestock. So eat from it, and feed the unfortunate poor.", "translation_id": "supaya mereka menyaksikan berbagai manfaat bagi mereka dan supaya mereka menyebut nama Allah pada hari yang telah ditentukan atas rezeki yang Allah telah berikan kepada mereka berupa binatang ternak. Maka makanlah sebahagian daripadanya dan (sebahagian lagi) berikanlah untuk dimakan orang-orang yang sengsara dan fakir.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 29, "text": "ثُمَّ لۡیَقۡضُوا۟ تَفَثَهُمۡ وَلۡیُوفُوا۟ نُذُورَهُمۡ وَلۡیَطَّوَّفُوا۟ بِٱلۡبَیۡتِ ٱلۡعَتِیقِ ۝٢٩", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "ثم ليكمل الحجاج ما بقي عليهم من النُّسُك، بإحلالهم وخروجهم من إحرامهم، وذلك بإزالة ما تراكم مِن وسخ في أبدانهم، وقص أظفارهم، وحلق شعرهم، وليوفوا بما أوجبوه على أنفسهم من الحج والعمرة والهدايا، وليطوفوا بالبيت العتيق القديم، الذي أعتقه الله مِن تسلُّط الجبارين عليه، وهو الكعبة.", "isBasmala": false, "translation_en": "Then let them perform their acts of cleansing, and fulfill their vows, and circle around the Ancient House.", "translation_id": "Kemudian, hendaklah mereka menghilangkan kotoran yang ada pada badan mereka dan hendaklah mereka menyempurnakan nazar-nazar mereka dan hendaklah mereka melakukan melakukan thawaf sekeliling rumah yang tua itu (Baitullah).", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 30, "text": "ذَ ٰلِكَۖ وَمَن یُعَظِّمۡ حُرُمَـٰتِ ٱللَّهِ فَهُوَ خَیۡرࣱ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَـٰمُ إِلَّا مَا یُتۡلَىٰ عَلَیۡكُمۡۖ فَٱجۡتَنِبُوا۟ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَـٰنِ وَٱجۡتَنِبُوا۟ قَوۡلَ ٱلزُّورِ ۝٣٠", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "ذلك الذي أمر الله به مِن قضاء التفث والوفاء بالنذور والطواف بالبيت، هو ما أوجبه الله عليكم فعظِّموه، ومن يعظم حرمات الله، ومنها مناسكه بأدائها كاملة خالصة لله، فهو خير له في الدنيا والآخرة. وأحلَّ الله لكم أَكْلَ الأنعام إلا ما حرَّمه فيما يتلى عليكم في القرآن من الميتة وغيرها فاجتنبوه، وفي ذلك إبطال ما كانت العرب تحرِّمه من بعض الأنعام، وابتعِدوا عن القذارة التي هي الأوثان، وعن الكذب الذي هو الافتراء على الله.", "isBasmala": false, "translation_en": "All that. Whoever venerates the sanctities of God-it is good for him with his Lord. All livestock are permitted to you, except what is recited to you. So stay away from the abomination of idols, and stay away from perjury.", "translation_id": "Demikianlah (perintah Allah). Dan barangsiapa mengagungkan apa-apa yang terhormat di sisi Allah maka itu adalah lebih baik baginya di sisi Tuhannya. Dan telah dihalalkan bagi kamu semua binatang ternak, terkecuali yang diterangkan kepadamu keharamannya, maka jauhilah olehmu berhala-berhala yang najis itu dan jauhilah perkataan-perkataan dusta.", "manzil": 4, "manzil_display": ""}], "336": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 31, "text": "حُنَفَاۤءَ لِلَّهِ غَیۡرَ مُشۡرِكِینَ بِهِۦۚ وَمَن یُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَاۤءِ فَتَخۡطَفُهُ ٱلطَّیۡرُ أَوۡ تَهۡوِی بِهِ ٱلرِّیحُ فِی مَكَانࣲ سَحِیقࣲ ۝٣١", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "مستقيمين لله على إخلاص العمل له، مقبلين عليه بعبادته وحده وإفراده بالطاعة، معرضين عما سواه بنبذ الشرك، فإنَّه من يشرك بالله شيئًا، فمثله- في بُعْده عن الهدى، وفي هلاكه وسقوطه من رفيع الإيمان بل حضيض الكفر، وتخطُّف الشياطين له من كل جانب- كمثل مَن سقط من السماء: فإما أن تخطفه الطير فتقطع أعضاءه، وإما أن تأخذه عاصفة شديدة من الريح، فتقذفه في مكان بعيد.", "isBasmala": false, "translation_en": "Being true to God, without associating anything with Him. Whoever associates anything with God-it is as though he has fallen from the sky, and is snatched by the birds, or is swept away by the wind to a distant abyss.", "translation_id": "dengan ikhlas kepada Allah, tidak mempersekutukan sesuatu dengan Dia. Barangsiapa mempersekutukan sesuatu dengan Allah, maka adalah ia seolah-olah jatuh dari langit lalu disambar oleh burung, atau diterbangkan angin ke tempat yang jauh.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 32, "text": "ذَ ٰلِكَۖ وَمَن یُعَظِّمۡ شَعَـٰۤىِٕرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ ۝٣٢", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "ذلك ما أمر الله به مِن توحيده وإخلاص العبادة له. ومن يمتثل أمر الله ويُعَظِّم معالم الدين، ومنها أعمال الحج وأماكنه، والذبائح التي تُذْبَح فيه، وذلك باستحسانها واستسمانها، فهذا التعظيم مِن أفعال أصحاب القلوب المتصفة بتقوى الله وخشيته.", "isBasmala": false, "translation_en": "So it is. Whoever venerates the sacraments of God-it is from the piety of the hearts.", "translation_id": "Demikianlah (perintah Allah). Dan barangsiapa mengagungkan syi'ar-syi'ar Allah, maka sesungguhnya itu timbul dari ketakwaan hati.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 33, "text": "لَكُمۡ فِیهَا مَنَـٰفِعُ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى ثُمَّ مَحِلُّهَاۤ إِلَى ٱلۡبَیۡتِ ٱلۡعَتِیقِ ۝٣٣", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "لكم في هذه الهدايا منافع تنتفعون بها من الصوف واللبن والركوب، وغير ذلك مما لا يضرها إلى وقت ذبحها عند البيت العتيق، وهو الحرم كله.", "isBasmala": false, "translation_en": "In them are benefits for you until a certain time. Then their place is by the Ancient House.", "translation_id": "Bagi kamu pada binatang-binatang hadyu itu ada beberapa manfaat, sampai kepada waktu yang ditentukan, kemudian tempat wajib (serta akhir masa) menyembelihnya ialah setelah sampai ke Baitul Atiq (Baitullah).", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 34, "text": "وَلِكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكࣰا لِّیَذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِیمَةِ ٱلۡأَنۡعَـٰمِۗ فَإِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰحِدࣱ فَلَهُۥۤ أَسۡلِمُوا۟ۗ وَبَشِّرِ ٱلۡمُخۡبِتِینَ ۝٣٤", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "ولكل جماعة مؤمنة سلفت، جعلنا لها مناسك مِنَ الذبح وإراقة الدماء؛ وذلك ليذكروا اسم الله تعالى عند ذبح ما رزقهم مِن هذه الأنعام ويشكروا له. فإلهكم -أيها الناس- إله واحد هو الله فانقادوا لأمره وأمر رسوله. وبشِّر - أيها النبي- المتواضعين الخاضعين لربهم بخيرَي الدنيا والآخرة.", "isBasmala": false, "translation_en": "We have appointed a rite for every nation, that they may commemorate God's name over the livestock He has provided for them. Your God is One God, so to Him submit, and announce good news to the humble.", "translation_id": "Dan bagi tiap-tiap umat telah Kami syariatkan penyembelihan (kurban), supaya mereka menyebut nama Allah terhadap binatang ternak yang telah direzekikan Allah kepada mereka, maka Tuhanmu ialah Tuhan Yang Maha Esa, karena itu berserah dirilah kamu kepada-Nya. Dan berilah kabar gembira kepada orang-orang yang tunduk patuh (kepada Allah),", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 35, "text": "ٱلَّذِینَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّـٰبِرِینَ عَلَىٰ مَاۤ أَصَابَهُمۡ وَٱلۡمُقِیمِی ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ ۝٣٥", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "هؤلاء المتواضعون الخاشعون مِن صفاتهم أنهم إذا ذُكِر الله وحده خافوا عقابه، وحَذِروا مخالفته، وإذا أصابهم بأس وشدة صبروا على ذلك مؤملين الثواب من الله عز وجل، وأدَّوْا الصلاة تامة، وهم مع ذلك ينفقون مما رزقهم الله في الواجب عليهم مِن زكاة ونفقة عيال، ومَن وَجَبَتْ عليهم نفقته، وفي سبيل الله، والنفقات المستحبة.", "isBasmala": false, "translation_en": "Those whose hearts tremble when God is mentioned, and those who endure what has befallen them, and those who perform the prayer and spend from what We have provided for them.", "translation_id": "(yaitu) orang-orang yang apabila disebut nama Allah gemetarlah hati mereka, orang-orang yang sabar terhadap apa yang menimpa mereka, orang-orang yang mendirikan sembahyang dan orang-orang yang menafkahkan sebagian dari apa yang telah Kami rezekikan kepada mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 36, "text": "وَٱلۡبُدۡنَ جَعَلۡنَـٰهَا لَكُم مِّن شَعَـٰۤىِٕرِ ٱللَّهِ لَكُمۡ فِیهَا خَیۡرࣱۖ فَٱذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ عَلَیۡهَا صَوَاۤفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُوا۟ مِنۡهَا وَأَطۡعِمُوا۟ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَ ٰلِكَ سَخَّرۡنَـٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ ۝٣٦", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "وجعلنا لكم نَحْرَ البُدْن من شعائر الدين وأعلامه؛ لتتقربوا بها إلى الله، لكم فيها- أيها المتقربون -خير في منافعها من الأكل والصدقة والثواب والأجر، فقولوا عند ذبحها: بسم الله. وتُنْحَر الإبل واقفة قد صُفَّتْ ثلاث من قوائمها وقُيِّدت الرابعة، فإذا سقطت على الأرض جنوبها فقد حلَّ أكلها، فليأكل منها مقربوها تعبدًا ويُطْعِمُوا منها القانع -وهو الفقير الذي لم يسأل تعففًا- والمعترَّ الذي يسأل لحاجته، هكذا سخَّر الله البُدْن لكم، لعلكم تشكرون الله على تسخيرها لكم.", "isBasmala": false, "translation_en": "We have made the animal offerings emblems of God for you. In them is goodness for you. So pronounce God's name upon them as they line up. Then, when they have fallen on their sides, eat of them and feed the contented and the beggar. Thus We have subjected them to you, that you may be thankful.", "translation_id": "Dan telah Kami jadikan untuk kamu unta-unta itu sebahagian dari syi'ar Allah, kamu memperoleh kebaikan yang banyak padanya, maka sebutlah olehmu nama Allah ketika kamu menyembelihnya dalam keadaan berdiri (dan telah terikat). Kemudian apabila telah roboh (mati), maka makanlah sebahagiannya dan beri makanlah orang yang rela dengan apa yang ada padanya (yang tidak meminta-minta) dan orang yang meminta. Demikianlah Kami telah menundukkan untua-unta itu kepada kamu, mudah-mudahan kamu bersyukur.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 37, "text": "لَن یَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَاۤؤُهَا وَلَـٰكِن یَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَ ٰلِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِینَ ۝٣٧", "juz": 17, "hizb": "(*¼ ح 34*)", "tafsir": "لن ينال اللهَ مِن لحوم هذه الذبائح ولا من دمائها شيء، ولكن يناله الإخلاص فيها، وأن يكون القصد بها وجه الله وحده، كذلك ذللها لكم -أيها المتقربون-؛ لتعظموا الله، وتشكروا له على ما هداكم من الحق، فإنه أهلٌ لذلك. وبشِّر- أيها النبي- المحسنين بعبادة الله وحده والمحسنين إلى خلقه بكل خير وفلاح.", "isBasmala": false, "translation_en": "Neither their flesh, nor their blood, ever reaches God. What reaches Him is the righteousness from you. Thus He subdued them to you, that you may glorify God for guiding you. And give good news to the charitable.", "translation_id": "Daging-daging unta dan darahnya itu sekali-kali tidak dapat mencapai (keridhaan) Allah, tetapi ketakwaan dari kamulah yang dapat mencapainya. Demikianlah Allah telah menundukkannya untuk kamu supaya kamu mengagungkan Allah terhadap hidayah-Nya kepada kamu. Dan berilah kabar gembira kepada orang-orang yang berbuat baik.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 38, "text": "۞ إِنَّ ٱللَّهَ یُدَ ٰفِعُ عَنِ ٱلَّذِینَ ءَامَنُوۤا۟ۗ إِنَّ ٱللَّهَ لَا یُحِبُّ كُلَّ خَوَّانࣲ كَفُورٍ ۝٣٨", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "إن الله تعالى يدفع عن المؤمنين عدوان الكفار، وكيد الأشرار؛ لأنه عز وجل لا يحب كل خوَّان لأمانة ربه، جحود لنعمته.", "isBasmala": false, "translation_en": "God defends those who believe. God does not love any ungrateful traitor.", "translation_id": "Sesungguhnya Allah membela orang-orang yang telah beriman. Sesungguhnya Allah tidak menyukai tiap-tiap orang yang berkhianat lagi mengingkari nikmat.", "manzil": 4, "manzil_display": ""}], "337": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 39, "text": "أُذِنَ لِلَّذِینَ یُقَـٰتَلُونَ بِأَنَّهُمۡ ظُلِمُوا۟ۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِیرٌ ۝٣٩", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "(كان المسلمون في أول أمرهم ممنوعين من قتال الكفار، مأمورين بالصبر على أذاهم، فلما بلغ أذى المشركين مداه وخرج النبي صلى الله عليه وسلم من \"مكة\" مهاجرًا إلى \"المدينة\"، وأصبح للإسلام قوة) أَذِنَ الله للمسلمين في القتال؛ بسبب ما وقع عليهم من الظلم والعدوان، وإن الله تعالى قادر على نصرهم وإذلال عدوِّهم.", "isBasmala": false, "translation_en": "Permission is given to those who are fought against, and God is Able to give them victory.", "translation_id": "Telah diizinkan (berperang) bagi orang-orang yang diperangi, karena sesungguhnya mereka telah dianiaya. Dan sesungguhnya Allah, benar-benar Maha Kuasa menolong mereka itu,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 40, "text": "ٱلَّذِینَ أُخۡرِجُوا۟ مِن دِیَـٰرِهِم بِغَیۡرِ حَقٍّ إِلَّاۤ أَن یَقُولُوا۟ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّهُدِّمَتۡ صَوَ ٰمِعُ وَبِیَعࣱ وَصَلَوَ ٰتࣱ وَمَسَـٰجِدُ یُذۡكَرُ فِیهَا ٱسۡمُ ٱللَّهِ كَثِیرࣰاۗ وَلَیَنصُرَنَّ ٱللَّهُ مَن یَنصُرُهُۥۤۚ إِنَّ ٱللَّهَ لَقَوِیٌّ عَزِیزٌ ۝٤٠", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "الذين أُلجئوا إلى الخروج من ديارهم، لا لشيء فعلوه إلا لأنهم أسلموا وقالوا: ربنا الله وحده. ولولا ما شرعه الله من دَفْع الظلم والباطل بالقتال لَهُزِم الحقُّ في كل أمة ولخربت الأرض، وهُدِّمت فيها أماكن العبادة من صوامع الرهبان، وكنائس النصارى، ومعابد اليهود، ومساجد المسلمين التي يصلُّون فيها، ويذكرون اسم الله فيها كثيرًا. ومن اجتهد في نصرة دين الله، فإن الله ناصره على عدوه. إن الله لَقوي لا يغالَب، عزيز لا يرام، قد قهر الخلائق وأخذ بنواصيهم.", "isBasmala": false, "translation_en": "Those who were unjustly evicted from their homes, merely for saying, \"Our Lord is God.\" Were it not that God repels people by means of others: monasteries, churches, synagogues, and mosques-where the name of God is mentioned much-would have been demolished. God supports whoever supports Him. God is Strong and Mighty.", "translation_id": "(yaitu) orang-orang yang telah diusir dari kampung halaman mereka tanpa alasan yang benar, kecuali karena mereka berkata: \"Tuhan kami hanyalah Allah\". Dan sekiranya Allah tiada menolak (keganasan) sebagian manusia dengan sebagian yang lain, tentulah telah dirobohkan biara-biara Nasrani, gereja-gereja, rumah-rumah ibadat orang Yahudi dan masjid-masjid, yang di dalamnya banyak disebut nama Allah. Sesungguhnya Allah pasti menolong orang yang menolong (agama)-Nya. Sesungguhnya Allah benar-benar Maha Kuat lagi Maha Perkasa,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 41, "text": "ٱلَّذِینَ إِن مَّكَّنَّـٰهُمۡ فِی ٱلۡأَرۡضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلۡمَعۡرُوفِ وَنَهَوۡا۟ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَـٰقِبَةُ ٱلۡأُمُورِ ۝٤١", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "الذين وعدناهم بنصرنا هم الذين إنْ مكَّنَّاهم في الأرض، واستخلفناهم فيها بإظهارهم على عدوهم، أقاموا الصلاة بأدائها في أوقاتها بحدودها، وأخرجوا زكاة أموالهم إلى أهلها، وأمروا بكل ما أمر الله به مِن حقوقه وحقوق عباده، ونَهَوْا عن كل ما نهى الله عنه ورسوله. ولله وحده مصير الأمور كلها، والعاقبة للتقوى.", "isBasmala": false, "translation_en": "Those who, when We empower them in the land, observe the prayer, and give regular charity, and command what is right, and forbid what is wrong. To God belongs the outcome of events.", "translation_id": "(yaitu) orang-orang yang jika Kami teguhkan kedudukan mereka di muka bumi niscaya mereka mendirikan sembahyang, menunaikan zakat, menyuruh berbuat ma'ruf dan mencegah dari perbuatan yang mungkar; dan kepada Allah-lah kembali segala urusan.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 42, "text": "وَإِن یُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَثَمُودُ ۝٤٢", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "وإن يكذبك قومك- أيها الرسول- فقد سبقهم في تكذيب رسلهم قوم نوح، وعاد، وثمود، وقوم إبراهيم، وقوم لوط، وأصحاب \"مدين\" الذين كذبوا شعيبًا، وكذَّب فرعون وقومه موسى، فلم أعاجل هذه الأمم بالعقوبة، بل أمهلتها، ثم أخذتُ كلا منهم بالعذاب، فكيف كان إنكاري عليهم كفرهم وتكذيبهم، وتبديل ما كان بهم مِن نعمة بالعذاب والهلاك؟", "isBasmala": false, "translation_en": "If they deny you-before them the people of Noah, and Aad, and Thamood also denied.", "translation_id": "Dan jika mereka (orang-orang musyrik) mendustakan kamu, maka sesungguhnya telah mendustakan juga sebelum mereka kaum Nuh, 'Aad dan Tsamud,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 43, "text": "وَقَوۡمُ إِبۡرَ ٰهِیمَ وَقَوۡمُ لُوطࣲ ۝٤٣", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "وإن يكذبك قومك- أيها الرسول- فقد سبقهم في تكذيب رسلهم قوم نوح، وعاد، وثمود، وقوم إبراهيم، وقوم لوط، وأصحاب \"مدين\" الذين كذبوا شعيبًا، وكذَّب فرعون وقومه موسى، فلم أعاجل هذه الأمم بالعقوبة، بل أمهلتها، ثم أخذتُ كلا منهم بالعذاب، فكيف كان إنكاري عليهم كفرهم وتكذيبهم، وتبديل ما كان بهم مِن نعمة بالعذاب والهلاك؟", "isBasmala": false, "translation_en": "And the people of Abraham, and the people of Lot.", "translation_id": "dan kaum Ibrahim dan kaum Luth,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 44, "text": "وَأَصۡحَـٰبُ مَدۡیَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَیۡتُ لِلۡكَـٰفِرِینَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَیۡفَ كَانَ نَكِیرِ ۝٤٤", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "وإن يكذبك قومك- أيها الرسول- فقد سبقهم في تكذيب رسلهم قوم نوح، وعاد، وثمود، وقوم إبراهيم، وقوم لوط، وأصحاب \"مدين\" الذين كذبوا شعيبًا، وكذَّب فرعون وقومه موسى، فلم أعاجل هذه الأمم بالعقوبة، بل أمهلتها، ثم أخذتُ كلا منهم بالعذاب، فكيف كان إنكاري عليهم كفرهم وتكذيبهم، وتبديل ما كان بهم مِن نعمة بالعذاب والهلاك؟", "isBasmala": false, "translation_en": "And the inhabitants of Median. And Moses was denied. Then I reprieved those who disbelieved, but then I seized them. So how was My rejection?", "translation_id": "dan penduduk Madyan, dan telah didustakan Musa, lalu Aku tangguhkan (azab-Ku) untuk orang-orang kafir, kemudian Aku azab mereka, maka (lihatlah) bagaimana besarnya kebencian-Ku (kepada mereka itu).", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 45, "text": "فَكَأَیِّن مِّن قَرۡیَةٍ أَهۡلَكۡنَـٰهَا وَهِیَ ظَالِمَةࣱ فَهِیَ خَاوِیَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرࣲ مُّعَطَّلَةࣲ وَقَصۡرࣲ مَّشِیدٍ ۝٤٥", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "فكثيرًا من القرى الظالمة بكفرها أهلكنا أهلها، فديارهم مهدَّمة خَلَتْ مِن سكانها، وآبارها لا يُستقى منها، وقصورها العالية المزخرفة لم تدفع عن أهلها سوء العذاب.", "isBasmala": false, "translation_en": "How many a town have We destroyed while it was doing wrong? They lie in ruins; with stilled wells, and lofty mansions.", "translation_id": "Berapalah banyaknya kota yang Kami telah membinasakannya, yang penduduknya dalam keadaan zalim, maka (tembok-tembok) kota itu roboh menutupi atap-atapnya dan (berapa banyak pula) sumur yang telah ditinggalkan dan istana yang tinggi,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 46, "text": "أَفَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبࣱ یَعۡقِلُونَ بِهَاۤ أَوۡ ءَاذَانࣱ یَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَـٰرُ وَلَـٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِی فِی ٱلصُّدُورِ ۝٤٦", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "أفلم يَسِر المكذبون من قريش في الأرض ليشاهدوا آثار المهلكين، فيتفكروا بعقولهم، فيعتبروا، ويسمعوا أخبارهم سماع تدبُّر فيتعظوا؟ فإن العمى ليس عمى البصر، وإنما العمى المُهْلِك هو عمى البصيرة عن إدراك الحق والاعتبار.", "isBasmala": false, "translation_en": "Have they not journeyed in the land, and had minds to reason with, or ears to listen with? It is not the eyes that go blind, but it is the hearts, within the chests, that go blind.", "translation_id": "maka apakah mereka tidak berjalan di muka bumi, lalu mereka mempunyai hati yang dengan itu mereka dapat memahami atau mempunyai telinga yang dengan itu mereka dapat mendengar? Karena sesungguhnya bukanlah mata itu yang buta, tetapi yang buta, ialah hati yang di dalam dada.", "manzil": 4, "manzil_display": ""}], "338": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 47, "text": "وَیَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن یُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ یَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةࣲ مِّمَّا تَعُدُّونَ ۝٤٧", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "ويستعجلك- أيها الرسول- كفار قريش -لشدة جهلهم- بالعذاب الذي أنذرتهم به لـمَّا أصروا على الكفر، ولن يخلف الله ما وعدهم به من العذاب فلا بدَّ من وقوعه، وقد عجَّل لهم في الدينا ذلك في يوم \"بدر\". وإن يومًا من الأيام عند الله - وهو يوم القيامة- كألف سنة مما تَعُدُّون من سني الدنيا.", "isBasmala": false, "translation_en": "And they ask you to hasten the punishment. But God never breaks His promise. A day with your Lord is like a thousand years of your count.", "translation_id": "Dan mereka meminta kepadamu agar azab itu disegerakan, padahal Allah sekali-kali tidak akan menyalahi janji-Nya. Sesungguhnya sehari disisi Tuhanmu adalah seperti seribu tahun menurut perhitunganmu.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 48, "text": "وَكَأَیِّن مِّن قَرۡیَةٍ أَمۡلَیۡتُ لَهَا وَهِیَ ظَالِمَةࣱ ثُمَّ أَخَذۡتُهَا وَإِلَیَّ ٱلۡمَصِیرُ ۝٤٨", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "وكثير من القرى كانت ظالمة بإصرار أهلها على الكفر، فأمهلتهم ولم أعاجلهم بالعقوبة فاغتروا، ثم أخَذْتُهم بعذابي في الدنيا، وإليَّ مرجعهم بعد هلاكهم، فأعذبهم بما يستحقون.", "isBasmala": false, "translation_en": "How many a town have I reprieved, although it was unjust? Then I seized it. To Me is the destination.", "translation_id": "Dan berapalah banyaknya kota yang Aku tangguhkan (azab-Ku) kepadanya, yang penduduknya berbuat zalim, kemudian Aku azab mereka, dan hanya kepada-Kulah kembalinya (segala sesuatu).", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 49, "text": "قُلۡ یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّمَاۤ أَنَا۠ لَكُمۡ نَذِیرࣱ مُّبِینࣱ ۝٤٩", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "قل - أيها الرسول -: يا أيها الناس ما أنا إلا منذر لكم مبلِّغ عن الله رسالته. فالذين آمنوا بالله ورسوله، واستقر ذلك في قلوبهم، وعملوا الأعمال الصالحة، لهم عند الله عفو عن ذنوبهم ومغفرة يستر بها ما صدر عنهم من معصية، ورزق حسن لا ينقطع وهو الجنة. والذين اجتهدوا في الكيد لإبطال آيات القرآن بالتكذيب مشاقين مغالبين، أولئك هم أهل النار الموقدة، يدخلونها ويبقون فيها أبدًا.", "isBasmala": false, "translation_en": "Say, \"O people, I am only a plain warner to you.\"", "translation_id": "Katakanlah: \"Hai manusia, sesungguhnya aku adalah seorang pemberi peringatan yang nyata kepada kamu\".", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 50, "text": "فَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ ۝٥٠", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "قل - أيها الرسول -: يا أيها الناس ما أنا إلا منذر لكم مبلِّغ عن الله رسالته. فالذين آمنوا بالله ورسوله، واستقر ذلك في قلوبهم، وعملوا الأعمال الصالحة، لهم عند الله عفو عن ذنوبهم ومغفرة يستر بها ما صدر عنهم من معصية، ورزق حسن لا ينقطع وهو الجنة. والذين اجتهدوا في الكيد لإبطال آيات القرآن بالتكذيب مشاقين مغالبين، أولئك هم أهل النار الموقدة، يدخلونها ويبقون فيها أبدًا.", "isBasmala": false, "translation_en": "Those who believe and work righteousness-for them is forgiveness and a generous provision.", "translation_id": "Maka orang-orang yang beriman dan beramal saleh, bagi mereka ampunan dan rezeki yang mulia.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 51, "text": "وَٱلَّذِینَ سَعَوۡا۟ فِیۤ ءَایَـٰتِنَا مُعَـٰجِزِینَ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ ۝٥١", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "قل - أيها الرسول -: يا أيها الناس ما أنا إلا منذر لكم مبلِّغ عن الله رسالته. فالذين آمنوا بالله ورسوله، واستقر ذلك في قلوبهم، وعملوا الأعمال الصالحة، لهم عند الله عفو عن ذنوبهم ومغفرة يستر بها ما صدر عنهم من معصية، ورزق حسن لا ينقطع وهو الجنة. والذين اجتهدوا في الكيد لإبطال آيات القرآن بالتكذيب مشاقين مغالبين، أولئك هم أهل النار الموقدة، يدخلونها ويبقون فيها أبدًا.", "isBasmala": false, "translation_en": "But those who strive against Our revelations-these are the inmates of Hell.", "translation_id": "Dan orang-orang yang berusaha dengan maksud menentang ayat-ayat Kami dengan melemahkan (kemauan untuk beriman); mereka itu adalah penghuni-penghuni neraka.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 52, "text": "وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولࣲ وَلَا نَبِیٍّ إِلَّاۤ إِذَا تَمَنَّىٰۤ أَلۡقَى ٱلشَّیۡطَـٰنُ فِیۤ أُمۡنِیَّتِهِۦ فَیَنسَخُ ٱللَّهُ مَا یُلۡقِی ٱلشَّیۡطَـٰنُ ثُمَّ یُحۡكِمُ ٱللَّهُ ءَایَـٰتِهِۦۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ ۝٥٢", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "وما أرسلنا من قبلك- أيها الرسول - من رسول ولا نبي إلا إذا قرأ كتاب الله ألقى الشيطان في قراءته الوساوس والشبهات؛ ليصدَّ الناس عن اتباع ما يقرؤه ويتلوه، لكن الله يبطل كيد الشيطان، فيزيل وساوسه، ويثبت آياته الواضحات. والله عليم بما كان ويكون، لا تخفى عليه خافية، حكيم في تقديره وأمره.", "isBasmala": false, "translation_en": "We never sent a messenger before you, or a prophet, but when he had a desire Satan interfered in his wishes. But God nullifies what Satan interjects, and God affirms His revelations. God is Omniscient and Wise.", "translation_id": "Dan Kami tidak mengutus sebelum kamu seorang rasulpun dan tidak (pula) seorang nabi, melainkan apabila ia mempunyai sesuatu keinginan, syaitanpun memasukkan godaan-godaan terhadap keinginan itu, Allah menghilangkan apa yang dimasukkan oleh syaitan itu, dan Allah menguatkan ayat-ayat-Nya. Dan Allah Maha Mengetahui lagi Maha Bijaksana,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 53, "text": "لِّیَجۡعَلَ مَا یُلۡقِی ٱلشَّیۡطَـٰنُ فِتۡنَةࣰ لِّلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ وَٱلۡقَاسِیَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِینَ لَفِی شِقَاقِۭ بَعِیدࣲ ۝٥٣", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "وما كان هذا الفعل مِنَ الشيطان إلا ليجعله الله اختبارًا للذين في قلوبهم شك ونفاق، ولقساة القلوب من المشركين الذين لا يؤثِّرُ فيهم زجر. وإن الظالمين مِن هؤلاء وأولئك في عداوة شديدة لله ورسوله وخلافٍ للحق بعيد عن الصواب.", "isBasmala": false, "translation_en": "In order to make Satan's suggestions a trial for those whose hearts are diseased, and those whose hearts are hardened. The wrongdoers are in profound discord.", "translation_id": "agar Dia menjadikan apa yang dimasukkan oleh syaitan itu, sebagai cobaan bagi orang-orang yang di dalam hatinya ada penyakit dan yang kasar hatinya. Dan sesungguhnya orang-orang yang zalim itu, benar-benar dalam permusuhan yang sangat,", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 54, "text": "وَلِیَعۡلَمَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَیُؤۡمِنُوا۟ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِینَ ءَامَنُوۤا۟ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٥٤", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "وليعلم أهل العلم الذين يفرقون بعلمهم بين الحق والباطل أن القرآن الكريم هو الحق النازل من عند الله عليك أيها الرسول، لا شبهة فيه، ولا سبيل للشيطان إليه، فيزداد به إيمانهم، وتخضع له قلوبهم. وإن الله لهادي الذين آمنوا به وبرسوله إلى طريق الحق الواضح، وهو الإسلام ينقذهم به من الضلال.", "isBasmala": false, "translation_en": "And so that those endowed with knowledge may know that it is the truth from your Lord, and so believe in it, and their hearts soften to it. God guides those who believe to a straight path.", "translation_id": "dan agar orang-orang yang telah diberi ilmu, meyakini bahwasanya Al Quran itulah yang hak dari Tuhan-mu lalu mereka beriman dan tunduk hati mereka kepadanya dan sesungguhnya Allah adalah Pemberi Petunjuk bagi orang-orang yang beriman kepada jalan yang lurus.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 55, "text": "وَلَا یَزَالُ ٱلَّذِینَ كَفَرُوا۟ فِی مِرۡیَةࣲ مِّنۡهُ حَتَّىٰ تَأۡتِیَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ یَأۡتِیَهُمۡ عَذَابُ یَوۡمٍ عَقِیمٍ ۝٥٥", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "ولا يزال الكافرون المكذبون في شك مما جئتهم به من القرآن إلى أن تأتيهم الساعة فجأة، وهم على تكذيبهم، أو يأتيهم عذاب يوم لا خير فيه، وهو يوم القيامة.", "isBasmala": false, "translation_en": "Those who disbelieve will continue to be hesitant about it, until the Hour comes upon them suddenly, or there comes to them the torment of a desolate Day.", "translation_id": "Dan senantiasalah orang-orang kafir itu berada dalam keragu-raguan terhadap Al Quran, hingga datang kepada mereka saat (kematiannya) dengan tiba-tiba atau datang kepada mereka azab hari kiamat.", "manzil": 4, "manzil_display": ""}], "339": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 56, "text": "ٱلۡمُلۡكُ یَوۡمَىِٕذࣲ لِّلَّهِ یَحۡكُمُ بَیۡنَهُمۡۚ فَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فِی جَنَّـٰتِ ٱلنَّعِیمِ ۝٥٦", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "المُلك والسلطان في هذا اليوم لله وحده، وهو سبحانه يقضي بين المؤمنين والكافرين. فالذين آمنوا بالله ورسوله وعملوا الأعمال الصالحة، لهم النعيم الدائم في الجنات. والذين جحدوا وحدانية الله وكذبوا رسوله وأنكروا آيات القرآن، فأولئك لهم عذاب يخزيهم ويهينهم في جهنم.", "isBasmala": false, "translation_en": "Sovereignty on that Day belongs to God; He will judge between them. Those who believe and do good deeds will be in the Gardens of Bliss.", "translation_id": "Kekuasaan di hari itu ada pada Allah, Dia memberi keputusan di antara mereka. Maka orang-orang yang beriman dan beramal saleh adalah di dalam surga yang penuh kenikmatan.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 57, "text": "وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَا فَأُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مُّهِینࣱ ۝٥٧", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "المُلك والسلطان في هذا اليوم لله وحده، وهو سبحانه يقضي بين المؤمنين والكافرين. فالذين آمنوا بالله ورسوله وعملوا الأعمال الصالحة، لهم النعيم الدائم في الجنات. والذين جحدوا وحدانية الله وكذبوا رسوله وأنكروا آيات القرآن، فأولئك لهم عذاب يخزيهم ويهينهم في جهنم.", "isBasmala": false, "translation_en": "But those who disbelieve and reject Our revelations-these will have a humiliating punishment.", "translation_id": "Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, maka bagi mereka azab yang menghinakan.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 58, "text": "وَٱلَّذِینَ هَاجَرُوا۟ فِی سَبِیلِ ٱللَّهِ ثُمَّ قُتِلُوۤا۟ أَوۡ مَاتُوا۟ لَیَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنࣰاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَیۡرُ ٱلرَّ ٰزِقِینَ ۝٥٨", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "والذين خرجوا من ديارهم طلبًا لرضا الله، ونصرة لدينه، من قُتل منهم وهو يجاهد الكفار، ومن مات منهم مِن غير قتال، لَيرزقَنَّهم الله الجنة ونعيمها الذي لا ينقطع ولا يزول، وإن الله سبحانه وتعالى لهو خير الرازقين.", "isBasmala": false, "translation_en": "Those who emigrate in God's cause, then get killed, or die, God will provide them with fine provisions. God is the Best of Providers.", "translation_id": "Dan orang-orang yang berhijrah di jalan Allah, kemudian mereka di bunuh atau mati, benar-benar Allah akan memberikan kepada mereka rezeki yang baik (surga). Dan sesungguhnya Allah adalah sebaik-baik pemberi rezeki.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 59, "text": "لَیُدۡخِلَنَّهُم مُّدۡخَلࣰا یَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِیمٌ حَلِیمࣱ ۝٥٩", "juz": 17, "hizb": "(*½ ح 34*)", "tafsir": "ليُدخلنَّهم الله المُدْخل الذي يحبونه وهو الجنة. وإن الله لَعليم بمن يخرج في سبيله، ومن يخرج طلبًا للدنيا، حليم عمن عصاه، فلا يعاجلهم بالعقوبة.", "isBasmala": false, "translation_en": "He will admit them an admittance that will please them. God is Knowing and Clement.", "translation_id": "Sesungguhnya Allah akan memasukkan mereka ke dalam suatu tempat (surga) yang mereka menyukainya. Dan sesungguhnya Allah Maha mengetahui lagi Maha Penyantun.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 60, "text": "۞ ذَ ٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِیَ عَلَیۡهِ لَیَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورࣱ ۝٦٠", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "ذلك الأمر الذي قصصنا عليك من إدخال المهاجرين الجنة، ومن اعتُدِي عليه وظُلم فقد أُذِن له أن يقابل الجاني بمثل فعلته، ولا حرج عليه، فإذا عاد الجاني إلى إيذائه وبغى، فإن الله ينصر المظلوم المعتدى عليه؛ إذ لا يجوز أن يُعْتَدى عليه بسبب انتصافه لنفسه. إن الله لعفوٌ غفور، يعفو عن المذنبين فلا يعاجلهم بالعقوبة، ويغفر ذنوبهم.", "isBasmala": false, "translation_en": "That is so! Whoever retaliates similarly to the affliction he was made to suffer, and then he is wronged again, God will definitely assist him. God is Pardoning and Forgiving.", "translation_id": "Demikianlah, dan barangsiapa membalas seimbang dengan penganiayaan yang pernah ia derita kemudian ia dianiaya (lagi), pasti Allah akan menolongnya. Sesungguhnya Allah benar-benar Maha Pemaaf lagi Maha Pengampun.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 61, "text": "ذَ ٰلِكَ بِأَنَّ ٱللَّهَ یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِ وَأَنَّ ٱللَّهَ سَمِیعُۢ بَصِیرࣱ ۝٦١", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "ذلك الذي شرع لكم تلك الأحكام العادلة هو الحق، وهو القادر على ما يشاء، ومِن قدرته أنه يدخل ما ينقص من ساعات الليل في ساعات النهار، ويدخل ما انتقص من ساعات النهار في ساعات الليل، وأن الله سميع لكل صوت، بصير بكل فعل، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "That is because God merges the night into the day, and He merges the day into the night, and because God is Hearing and Seeing.", "translation_id": "Yang demikian itu, adalah karena sesungguhnya Allah (kuasa) memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam dan bahwasanya Allah Maha Mendengar lagi Maha Melihat.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 62, "text": "ذَ ٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا یَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَـٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِیُّ ٱلۡكَبِیرُ ۝٦٢", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "ذلك بأن الله هو الإله الحق الذي لا تنبغي العبادة إلا له، وأن ما يعبده المشركون من دونه من الأصنام والأنداد هو الباطل الذي لا ينفع ولا يضرُّ، وأن الله هو العليُّ على خلقه ذاتًا وقدرًا وقهرًا، المتعالي عن الأشباه والأنداد، الكبير في ذاته وأسمائه فهو أكبر من كلِّ شيء.", "isBasmala": false, "translation_en": "That is because God is the Reality, and what they invoke besides Him is vanity, and because God is the Sublime, the Grand.", "translation_id": "(Kuasa Allah) yang demikian itu, adalah karena sesungguhnya Allah, Dialah (Tuhan) Yang Haq dan sesungguhnya apa saja yang mereka seru selain dari Allah, itulah yang batil, dan sesungguhnya Allah, Dialah Yang Maha Tinggi lagi Maha Besar.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 63, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَتُصۡبِحُ ٱلۡأَرۡضُ مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِیفٌ خَبِیرࣱ ۝٦٣", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "ألم ترَ- أيها النبي- أن الله أنزل من السماء مطرًا، فتصبح الأرض مخضرة بما ينبت فيها من النبات؟ إن الله لطيف بعباده باستخراج النبات من الأرض بذلك الماء، خبير بمصالحهم.", "isBasmala": false, "translation_en": "Do you not see that God sends down water from the sky, and the land becomes green? God is Kind and Aware.", "translation_id": "Apakah kamu tiada melihat, bahwasanya Allah menurunkan air dari langit, lalu jadilah bumi itu hijau? Sesungguhnya Allah Maha Halus lagi Maha Mengetahui.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 64, "text": "لَّهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ ۝٦٤", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "لله سبحانه وتعالى ما في السموات والأرض خلقًا وملكًا وعبودية، كلٌّ محتاج إلى تدبيره وإفضاله. إن الله لهو الغني الذي لا يحتاج إلى شيء، المحمود في كل حال.", "isBasmala": false, "translation_en": "To Him belongs everything in the heavens and everything on earth. God is the Rich, the Praised.", "translation_id": "Kepunyaan Allah-lah segala yang ada di langit dan segala yang ada di bumi. Dan sesungguhnya Allah benar-benar Maha Kaya lagi Maha Terpuji.", "manzil": 4, "manzil_display": ""}], "340": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 65, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِی ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِی فِی ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَیُمۡسِكُ ٱلسَّمَاۤءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦۤۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفࣱ رَّحِیمࣱ ۝٦٥", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "ألم تر أن الله تعالى ذلَّل لكم ما في الأرض من الدواب والبهائم والزروع والثمار والجماد لركوبكم وطعامكم وكل منافعكم، كما ذلَّل لكم السفن تجري في البحر بقدرته وأمره فتحملكم مع أمتعتكم إلى حيث تشاؤون من البلاد والأماكن، وهو الذي يمسك السماء فيحفظها؛ حتى لا تقع على الأرض فيهلك مَن عليها إلا بإذنه سبحانه بذلك؟ إن الله بالناس لرؤوف رحيم فيما سخر لهم من هذه الأشياء وغيرها؛ تفضلا منه عليهم.", "isBasmala": false, "translation_en": "Do you not see that God made everything on earth subservient to you? How the ships sail at sea by His command? That He holds up the sky lest it falls on earth-except by His permission? God is Gracious towards the people, Most Merciful.", "translation_id": "Apakah kamu tiada melihat bahwasanya Allah menundukkan bagimu apa yang ada di bumi dan bahtera yang berlayar di lautan dengan perintah-Nya. Dan Dia menahan (benda-benda) langit jatuh ke bumi, melainkan dengan izin-Nya? Sesungguhnya Allah benar-benar Maha Pengasih lagi Maha Penyayang kepada Manusia.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 66, "text": "وَهُوَ ٱلَّذِیۤ أَحۡیَاكُمۡ ثُمَّ یُمِیتُكُمۡ ثُمَّ یُحۡیِیكُمۡۗ إِنَّ ٱلۡإِنسَـٰنَ لَكَفُورࣱ ۝٦٦", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "وهو الله تعالى الذي أحياكم بأن أوجدكم من العدم، ثم يميتكم عند انقضاء أعماركم، ثم يحييكم بالبعث لمحاسبتكم على أعمالكم. إن الإنسان لَجحود لما ظهر من الآيات الدالة على قدرة الله ووحدانيته.", "isBasmala": false, "translation_en": "And it is He who gives you life, then makes you die, then revives you. The human being is unappreciative.", "translation_id": "Dan Dialah Allah yang telah menghidupkan kamu, kemudian mematikan kamu, kemudian menghidupkan kamu (lagi), sesungguhnya manusia itu, benar-benar sangat mengingkari nikmat.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 67, "text": "لِّكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا یُنَـٰزِعُنَّكَ فِی ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدࣰى مُّسۡتَقِیمࣲ ۝٦٧", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "لكل أمة من الأمم الماضية جعلنا شريعة وعبادة أمرناهم بها، فهم عاملون بها، فلا ينازعنك- أيها الرسول- مشركو قريش في شريعتك، وما أمرك الله به في المناسك وأنواع العبادات كلها، وادع إلى توحيد ربك وإخلاص العبادة له واتباع أمره، إنك لعلى دين قويم، لا اعوجاج فيه.", "isBasmala": false, "translation_en": "For every congregation We have appointed acts of devotion, which they observe. So do not let them dispute with you in this matter. And invite to your Lord; you are upon a straight guidance.", "translation_id": "Bagi tiap-tiap umat telah Kami tetapkan syari'at tertentu yang mereka lakukan, maka janganlah sekali-kali mereka membantah kamu dalam urusan (syari'at) ini dan serulah kepada (agama) Tuhanmu. Sesungguhnya kamu benar-benar berada pada jalan yang lurus.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 68, "text": "وَإِن جَـٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ ۝٦٨", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "وإن أصرُّوا على مجادلتك بالباطل فيما تدعوهم إليه فلا تجادلهم، بل قل لهم: الله أعلم بما تعملونه من الكفر والتكذيب، فهم معاندون مكابرون.", "isBasmala": false, "translation_en": "But if they dispute with you, say, \"God is fully aware of what you do.\"", "translation_id": "Dan jika mereka membantah kamu, maka katakanlah: \"Allah lebih mengetahui tentang apa yang kamu kerjakan\".", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 69, "text": "ٱللَّهُ یَحۡكُمُ بَیۡنَكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ ۝٦٩", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "الله تعالى يحكم بين المسلمين والكافرين يوم القيامة في أمر اختلافهم في الدين. وفي هذه الآية أدب حسن في الرد على مَن جادل تعنتًا واستكبارًا.", "isBasmala": false, "translation_en": "God will judge between you on the Day of Resurrection regarding what you disagree about.", "translation_id": "Allah akan mengadili di antara kamu pada hari kiamat tentang apa yang kamu dahulu selalu berselisih padanya.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 70, "text": "أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِی ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۚ إِنَّ ذَ ٰلِكَ فِی كِتَـٰبٍۚ إِنَّ ذَ ٰلِكَ عَلَى ٱللَّهِ یَسِیرࣱ ۝٧٠", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "ألم تعلم- أيها النبي- أن الله يعلم ما في السماء والأرض علماً كاملا قد أثبته في اللوح المحفوظ؟ إن ذلك العلم أمر سهل على الله، الذي لا يعجزه شيء.", "isBasmala": false, "translation_en": "Do you not know that God knows everything in the heavens and the earth? This is in a book. That is easy for God.", "translation_id": "Apakah kamu tidak mengetahui bahwa sesungguhnya Allah mengetahui apa saja yang ada di langit dan di bumi?; bahwasanya yang demikian itu terdapat dalam sebuah kitab (Lauh Mahfuzh). Sesungguhnya yang demikian itu amat mudah bagi Allah.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 71, "text": "وَیَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ یُنَزِّلۡ بِهِۦ سُلۡطَـٰنࣰا وَمَا لَیۡسَ لَهُم بِهِۦ عِلۡمࣱۗ وَمَا لِلظَّـٰلِمِینَ مِن نَّصِیرࣲ ۝٧١", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "ويصر كفار قريش على الشرك بالله مع ظهور بطلان ما هم عليه، فهم يعبدون آلهة، لم يَنْزِل في كتاب مِن كتب الله برهان بأنها تصلح للعبادة، ولا علم لهم فيما اختلقوه، وافتروه على الله، وإنما هو أمر اتبعوا فيه آباءَهم بلا دليل. فإذا جاء وقت الحساب في الآخرة فليس للمشركين ناصر ينصرهم، أو يدفع عنهم العذاب.", "isBasmala": false, "translation_en": "Yet they worship, besides God, things for which He sent down no warrant, and what they have no knowledge of. There is no savior for the transgressors.", "translation_id": "Dan mereka menyembah selain Allah, apa yang Allah tidak menurunkan keterangan tentang itu, dan apa yang mereka sendiri tiada mempunyai pengetahuan terhadapnya. Dan bagi orang-orang yang zalim sekali-kali tidak ada seorang penolongpun.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 72, "text": "وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ تَعۡرِفُ فِی وُجُوهِ ٱلَّذِینَ كَفَرُوا۟ ٱلۡمُنكَرَۖ یَكَادُونَ یَسۡطُونَ بِٱلَّذِینَ یَتۡلُونَ عَلَیۡهِمۡ ءَایَـٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرࣲّ مِّن ذَ ٰلِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِینَ كَفَرُوا۟ۖ وَبِئۡسَ ٱلۡمَصِیرُ ۝٧٢", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "وإذا تتلى آيات القرآن الواضحة على هؤلاء المشركين ترى الكراهة ظاهرة على وجوههم، يكادون يبطشون بالمؤمنين الذين يدعونهم إلى الله تعالى، ويتلون عليهم آياته. قل لهم -أيها الرسول-: أفلا أخبركم بما هو أشد كراهة إليكم من سماع الحق ورؤية الداعين إليه؟ النار أعدَّها الله للكافرين في الآخرة، وبئس المكان الذي يصيرون إليه.", "isBasmala": false, "translation_en": "And when Our Clear Verses are recited to them, you will recognize disgust on the faces of those who disbelieve. They nearly assault those who recite to them Our Verses. Say, \"Shall I inform you of something worse than that? The Fire! God has promised it to those who disbelieve. And what a wretched outcome!\"", "translation_id": "Dan apabila dibacakan di hadapan mereka ayat-ayat Kami yang terang, niscaya kamu melihat tanda-tanda keingkaran pada muka orang-orang yang kafir itu. Hampir-hampir mereka menyerang orang-orang yang membacakan ayat-ayat Kami di hadapan mereka. Katakanlah: \"Apakah akan aku kabarkan kepadamu yang lebih buruk daripada itu, yaitu neraka?\" Allah telah mengancamkannya kepada orang-orang yang kafir. Dan neraka itu adalah seburuk-buruknya tempat kembali.", "manzil": 4, "manzil_display": ""}], "341": [{"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 73, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ ضُرِبَ مَثَلࣱ فَٱسۡتَمِعُوا۟ لَهُۥۤۚ إِنَّ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن یَخۡلُقُوا۟ ذُبَابࣰا وَلَوِ ٱجۡتَمَعُوا۟ لَهُۥۖ وَإِن یَسۡلُبۡهُمُ ٱلذُّبَابُ شَیۡـࣰٔا لَّا یَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ ۝٧٣", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "يا أيها الناس ضُرِب مثل فاستمعوا له وتدبروه: إن الأصنام والأنداد التي تعبدونها من دون الله لن تقدر مجتمعة على خَلْق ذبابة واحدة، فكيف بخلق ما هو أكبر؟ ولا تقدر أن تستخلص ما يسلبه الذباب منها، فهل بعد ذلك مِن عَجْز؟ فهما ضعيفان معًا: ضَعُفَ الطالب الذي هو المعبود من دون الله أن يستنقذ ما أخذه الذباب منه، وضَعُفَ المطلوب الذي هو الذباب، فكيف تُتَّخذ هذه الأصنام والأنداد آلهة، وهي بهذا الهوان؟", "isBasmala": false, "translation_en": "O people! A parable is presented, so listen to it: Those you invoke besides God will never create a fly, even if they banded together for that purpose. And if the fly steals anything from them, they cannot recover it from it. Weak are the pursuer and the pursued.", "translation_id": "Hai manusia, telah dibuat perumpamaan, maka dengarkanlah olehmu perumpamaan itu. Sesungguhnya segala yang kamu seru selain Allah sekali-kali tidak dapat menciptakan seekor lalatpun, walaupun mereka bersatu menciptakannya. Dan jika lalat itu merampas sesuatu dari mereka, tiadalah mereka dapat merebutnya kembali dari lalat itu. Amat lemahlah yang menyembah dan amat lemah (pulalah) yang disembah.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 74, "text": "مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدۡرِهِۦۤۚ إِنَّ ٱللَّهَ لَقَوِیٌّ عَزِیزٌ ۝٧٤", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "هؤلاء المشركون لم يعظِّموا الله حق تعظيمه، إذ جعلوا له شركاء، وهو القوي الذي خلق كل شيء، العزيز الذي لا يغالَب.", "isBasmala": false, "translation_en": "They do not value God as He should be valued. God is Strong and Powerful.", "translation_id": "Mereka tidak mengenal Allah dengan sebenar-benarnya. Sesungguhnya Allah benar-benar Maha Kuat lagi Maha Perkasa.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 75, "text": "ٱللَّهُ یَصۡطَفِی مِنَ ٱلۡمَلَـٰۤىِٕكَةِ رُسُلࣰا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِیعُۢ بَصِیرࣱ ۝٧٥", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "الله سبحانه وتعالى يختار من الملائكة رسلا إلى أنبيائه، ويختار من الناس رسلا لتبليغ رسالاته إلى الخلق، إن الله سميع لأقوال عباده، بصير بجميع الأشياء، وبمن يختاره للرسالة مِن خلقه. وهو سبحانه يعلم ما بين أيدي ملائكته ورسله من قبل أن يخلقهم، ويعلم ما هو كائن بعد فنائهم. وإلى الله وحده ترجع الأمور.", "isBasmala": false, "translation_en": "God chooses messengers from among the angels, and from among the people. God is Hearing and Seeing.", "translation_id": "Allah memilih utusan-utusan-(Nya) dari malaikat dan dari manusia; sesungguhnya Allah Maha Mendengar lagi Maha Melihat.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 76, "text": "یَعۡلَمُ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ۝٧٦", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "الله سبحانه وتعالى يختار من الملائكة رسلا إلى أنبيائه، ويختار من الناس رسلا لتبليغ رسالاته إلى الخلق، إن الله سميع لأقوال عباده، بصير بجميع الأشياء، وبمن يختاره للرسالة مِن خلقه. وهو سبحانه يعلم ما بين أيدي ملائكته ورسله من قبل أن يخلقهم، ويعلم ما هو كائن بعد فنائهم. وإلى الله وحده ترجع الأمور.", "isBasmala": false, "translation_en": "He knows what is before them, and what is behind them. To God all matters are referred.", "translation_id": "Allah mengetahui apa yang di hadapan mereka dan apa yang di belakang mereka. Dan hanya kepada Allah dikembalikan semua urusan.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 77, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱرۡكَعُوا۟ وَ̅ٱ̅سۡ̅جُ̅دُ̅و̅ا۟̅ وَٱعۡبُدُوا۟ رَبَّكُمۡ وَٱفۡعَلُوا۟ ٱلۡخَیۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ ۝٧٧ ۩", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "يا أيها الذين آمنوا بالله ورسوله محمد صلى الله عليه وسلم اركعوا واسجدوا في صلاتكم، واعبدوا ربكم وحده لا شريك له، وافعلوا الخير؛ لتفلحوا، وجاهدوا أنفسكم، وقوموا قيامًا تامًّا بأمر الله، وادعوا الخلق إلى سبيله، وجاهدوا بأموالكم وألسنتكم وأنفسكم، مخلصين فيه النية لله عز وجل، مسلمين له قلوبكم وجوارحكم، هو اصطفاكم لحمل هذا الدين، وقد منَّ عليكم بأن جعل شريعتكم سمحة، ليس فيها تضييق ولا تشديد في تكاليفها وأحكامها، كما كان في بعض الأمم قبلكم، هذه الملة السمحة هي ملة أبيكم إبراهيم، وقد سَمَّاكم الله المسلمين مِن قبلُ في الكتب المنزلة السابقة، وفي هذا القرآن، وقد اختصَّكم بهذا الاختيار؛ ليكون خاتم الرسل محمد صلى الله عليه وسلم شاهدًا عليكم بأنه بلَّغكم رسالة ربه، وتكونوا شهداء على الأمم أن رسلهم قد بلَّغتهم بما أخبركم الله به في كتابه، فعليكم أن تعرفوا لهذه النعمة قدرها، فتشكروها، وتحافظوا على معالم دين الله بأداء الصلاة بأركانها وشروطها، وإخراج الزكاة المفروضة، وأن تلجؤوا إلى الله سبحانه وتعالى، وتتوكلوا عليه، فهو نِعْمَ المولى لمن تولاه، ونعم النصير لمن استنصره.", "isBasmala": false, "translation_en": "O you who believe! Kneel, and prostrate, and worship your Lord, and do good deeds, so that you may succeed.", "translation_id": "Hai orang-orang yang beriman, ruku'lah kamu, sujudlah kamu, sembahlah Tuhanmu dan perbuatlah kebajikan, supaya kamu mendapat kemenangan.", "manzil": 4, "manzil_display": ""}, {"sura": 22, "sura_name": "الحج", "revelation": "Madaniyah", "aya": 78, "text": "وَجَـٰهِدُوا۟ فِی ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَیۡكُمۡ فِی ٱلدِّینِ مِنۡ حَرَجࣲۚ مِّلَّةَ أَبِیكُمۡ إِبۡرَ ٰهِیمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِینَ مِن قَبۡلُ وَفِی هَـٰذَا لِیَكُونَ ٱلرَّسُولُ شَهِیدًا عَلَیۡكُمۡ وَتَكُونُوا۟ شُهَدَاۤءَ عَلَى ٱلنَّاسِۚ فَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعۡتَصِمُوا۟ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِیرُ ۝٧٨", "juz": 17, "hizb": "(*¾ ح 34*)", "tafsir": "يا أيها الذين آمنوا بالله ورسوله محمد صلى الله عليه وسلم اركعوا واسجدوا في صلاتكم، واعبدوا ربكم وحده لا شريك له، وافعلوا الخير؛ لتفلحوا، وجاهدوا أنفسكم، وقوموا قيامًا تامًّا بأمر الله، وادعوا الخلق إلى سبيله، وجاهدوا بأموالكم وألسنتكم وأنفسكم، مخلصين فيه النية لله عز وجل، مسلمين له قلوبكم وجوارحكم، هو اصطفاكم لحمل هذا الدين، وقد منَّ عليكم بأن جعل شريعتكم سمحة، ليس فيها تضييق ولا تشديد في تكاليفها وأحكامها، كما كان في بعض الأمم قبلكم، هذه الملة السمحة هي ملة أبيكم إبراهيم، وقد سَمَّاكم الله المسلمين مِن قبلُ في الكتب المنزلة السابقة، وفي هذا القرآن، وقد اختصَّكم بهذا الاختيار؛ ليكون خاتم الرسل محمد صلى الله عليه وسلم شاهدًا عليكم بأنه بلَّغكم رسالة ربه، وتكونوا شهداء على الأمم أن رسلهم قد بلَّغتهم بما أخبركم الله به في كتابه، فعليكم أن تعرفوا لهذه النعمة قدرها، فتشكروها، وتحافظوا على معالم دين الله بأداء الصلاة بأركانها وشروطها، وإخراج الزكاة المفروضة، وأن تلجؤوا إلى الله سبحانه وتعالى، وتتوكلوا عليه، فهو نِعْمَ المولى لمن تولاه، ونعم النصير لمن استنصره.", "isBasmala": false, "translation_en": "And strive for God, with the striving due to Him. He has chosen you, and has not burdened you in religion-the faith of your father Abraham. It is he who named you Muslims before, and in this. So that the Messenger may be a witness over you, and you may be witnesses over the people. So pray regularly, and give regular charity, and cleave to God. He is your Protector. What an excellent Protector, and what an excellent Helper.", "translation_id": "Dan berjihadlah kamu pada jalan Allah dengan jihad yang sebenar-benarnya. Dia telah memilih kamu dan Dia sekali-kali tidak menjadikan untuk kamu dalam agama suatu kesempitan. (Ikutilah) agama orang tuamu Ibrahim. Dia (Allah) telah menamai kamu sekalian orang-orang muslim dari dahulu, dan (begitu pula) dalam (Al Quran) ini, supaya Rasul itu menjadi saksi atas dirimu dan supaya kamu semua menjadi saksi atas segenap manusia, maka dirikanlah sembahyang, tunaikanlah zakat dan berpeganglah kamu pada tali Allah. Dia adalah Pelindungmu, maka Dialah sebaik-baik Pelindung dan sebaik-baik Penolong.", "manzil": 4, "manzil_display": ""}], "342": [{"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 18, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 1, "text": "۞ قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ ۝١", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "قد فاز المصدِّقون بالله وبرسوله العاملون بشرعه.", "isBasmala": false, "translation_en": "Successful are the believers.", "translation_id": "Sesungguhnya beruntunglah orang-orang yang beriman,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 2, "text": "ٱلَّذِینَ هُمۡ فِی صَلَاتِهِمۡ خَـٰشِعُونَ ۝٢", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "الذين من صفاتهم أنهم في صلاتهم خاشعون، تَفْرُغُ لها قلوبهم، وتسكن جوارحهم.", "isBasmala": false, "translation_en": "Those who are humble in their prayers.", "translation_id": "(yaitu) orang-orang yang khusyu' dalam sembahyangnya,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 3, "text": "وَٱلَّذِینَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ ۝٣", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "والذين هم تاركون لكل ما لا خير فيه من الأقوال والأفعال.", "isBasmala": false, "translation_en": "Those who avoid nonsense.", "translation_id": "dan orang-orang yang menjauhkan diri dari (perbuatan dan perkataan) yang tiada berguna,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 4, "text": "وَٱلَّذِینَ هُمۡ لِلزَّكَوٰةِ فَـٰعِلُونَ ۝٤", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "والذين هم مُطَهِّرون لنفوسهم وأموالهم بأداء زكاة أموالهم على اختلاف أجناسها.", "isBasmala": false, "translation_en": "Those who work for charity.", "translation_id": "dan orang-orang yang menunaikan zakat,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 5, "text": "وَٱلَّذِینَ هُمۡ لِفُرُوجِهِمۡ حَـٰفِظُونَ ۝٥", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "والذين هم لفروجهم حافظون مما حرَّم الله من الزنى واللواط وكل الفواحش.", "isBasmala": false, "translation_en": "Those who safeguard their chastity.", "translation_id": "dan orang-orang yang menjaga kemaluannya,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 6, "text": "إِلَّا عَلَىٰۤ أَزۡوَ ٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ فَإِنَّهُمۡ غَیۡرُ مَلُومِینَ ۝٦", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "إلا على زوجاتهم أو ما ملكت أيمانهم من الإماء، فلا لوم عليهم ولا حرج في جماعهن والاستمتاع بهن؛ لأن الله تعالى أحلَّهن.", "isBasmala": false, "translation_en": "Except from their spouses, or their dependents-for then they are free from blame.", "translation_id": "kecuali terhadap isteri-isteri mereka atau budak yang mereka miliki; maka sesungguhnya mereka dalam hal ini tiada tercela.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 7, "text": "فَمَنِ ٱبۡتَغَىٰ وَرَاۤءَ ذَ ٰلِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡعَادُونَ ۝٧", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "فمن طلب التمتع بغير زوجته أو أمَتِه فهو من المجاوزين الحلال إلى الحرام، وقد عرَّض نفسه لعقاب الله وسخطه.", "isBasmala": false, "translation_en": "But whoever seeks anything beyond that-these are the transgressors.", "translation_id": "Barangsiapa mencari yang di balik itu maka mereka itulah orang-orang yang melampaui batas.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 8, "text": "وَٱلَّذِینَ هُمۡ لِأَمَـٰنَـٰتِهِمۡ وَعَهۡدِهِمۡ رَ ٰعُونَ ۝٨", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "والذين هم حافظون لكل ما اؤتمنوا عليه، موفُّون بكل عهودهم.", "isBasmala": false, "translation_en": "Those who are faithful to their trusts and pledges.", "translation_id": "Dan orang-orang yang memelihara amanat-amanat (yang dipikulnya) dan janjinya.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 9, "text": "وَٱلَّذِینَ هُمۡ عَلَىٰ صَلَوَ ٰتِهِمۡ یُحَافِظُونَ ۝٩", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "والذين هم يداومون على أداء صلاتهم في أوقاتها على هيئتها المشروعة، الواردة عن النبي صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Those who safeguard their prayers.", "translation_id": "dan orang-orang yang memelihara sembahyangnya.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 10, "text": "أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡوَ ٰرِثُونَ ۝١٠", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "هؤلاء المؤمنون هم الوارثون الجنة.", "isBasmala": false, "translation_en": "These are the inheritors.", "translation_id": "Mereka itulah orang-orang yang akan mewarisi,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 11, "text": "ٱلَّذِینَ یَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِیهَا خَـٰلِدُونَ ۝١١", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "الذين يرثون أعلى منازل الجنة وأوسطها، هم فيها خالدون، لا ينقطع نعيمهم ولا يزول.", "isBasmala": false, "translation_en": "Who will inherit Paradise, wherein they will dwell forever.", "translation_id": "(yakni) yang akan mewarisi surga Firdaus. Mereka kekal di dalamnya.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 12, "text": "وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ مِن سُلَـٰلَةࣲ مِّن طِینࣲ ۝١٢", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "ولقد خلقنا آدم من طين مأخوذ من جميع الأرض.", "isBasmala": false, "translation_en": "We created man from an extract of clay.", "translation_id": "Dan sesungguhnya Kami telah menciptakan manusia dari suatu saripati (berasal) dari tanah.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 13, "text": "ثُمَّ جَعَلۡنَـٰهُ نُطۡفَةࣰ فِی قَرَارࣲ مَّكِینࣲ ۝١٣", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "ثم خلقنا بنيه متناسلين مِن نطفة: هي مني الرجال تخرج من أصلابهم، فتستقر متمكنة في أرحام النساء.", "isBasmala": false, "translation_en": "Then We made him a seed, in a secure repository.", "translation_id": "Kemudian Kami jadikan saripati itu air mani (yang disimpan) dalam tempat yang kokoh (rahim).", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 14, "text": "ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةࣰ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةࣰ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَـٰمࣰا فَكَسَوۡنَا ٱلۡعِظَـٰمَ لَحۡمࣰا ثُمَّ أَنشَأۡنَـٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَـٰلِقِینَ ۝١٤", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "ثم خلقنا النطفة علقة أي: دمًا أحمر، فخلقنا العلقة بعد أربعين يومًا مضغة أي: قطعة لحم قَدْر ما يُمْضغ، فخلقنا المضغة اللينة عظامًا، فكسونا العظام لحمًا، ثم أنشأناه خلقًا آخر بنفخ الروح فيه، فتبارك الله، الذي أحسن كل شيء خلقه.", "isBasmala": false, "translation_en": "Then We developed the seed into a clot. Then We developed the clot into a lump. Then We developed the lump into bones. Then We clothed the bones with flesh. Then We produced it into another creature. Most Blessed is God, the Best of Creators.", "translation_id": "Kemudian air mani itu Kami jadikan segumpal darah, lalu segumpal darah itu Kami jadikan segumpal daging, dan segumpal daging itu Kami jadikan tulang belulang, lalu tulang belulang itu Kami bungkus dengan daging. Kemudian Kami jadikan dia makhluk yang (berbentuk) lain. Maka Maha sucilah Allah, Pencipta Yang Paling Baik.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 15, "text": "ثُمَّ إِنَّكُم بَعۡدَ ذَ ٰلِكَ لَمَیِّتُونَ ۝١٥", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "ثم إنكم أيها البشر بعد أطوار الحياة وانقضاء الأعمار لَميتون.", "isBasmala": false, "translation_en": "Then, after that, you will die.", "translation_id": "Kemudian, sesudah itu, sesungguhnya kamu sekalian benar-benar akan mati.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 16, "text": "ثُمَّ إِنَّكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ تُبۡعَثُونَ ۝١٦", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "ثم إنكم بعد الموت وانقضاء الدنيا تُبْعثون يوم القيامة أحياء من قبوركم للحساب والجزاء.", "isBasmala": false, "translation_en": "Then, on the Day of Resurrection, you will be resurrected.", "translation_id": "Kemudian, sesungguhnya kamu sekalian akan dibangkitkan (dari kuburmu) di hari kiamat.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 17, "text": "وَلَقَدۡ خَلَقۡنَا فَوۡقَكُمۡ سَبۡعَ طَرَاۤىِٕقَ وَمَا كُنَّا عَنِ ٱلۡخَلۡقِ غَـٰفِلِینَ ۝١٧", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "ولقد خلقنا فوقكم سبع سموات بعضها فوق بعض، وما كنا عن الخلق غافلين، فلا نُغْفِلُ مخلوقًا، ولا ننساه.", "isBasmala": false, "translation_en": "We created above you seven pathways, and We are never heedless of the creation.", "translation_id": "Dan sesungguhnya Kami telah menciptakan di atas kamu tujuh buah jalan (tujuh buah langit); dan Kami tidaklah lengah terhadap ciptaan (Kami).", "manzil": 4, "manzil_display": ""}], "343": [{"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 18, "text": "وَأَنزَلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءَۢ بِقَدَرࣲ فَأَسۡكَنَّـٰهُ فِی ٱلۡأَرۡضِۖ وَإِنَّا عَلَىٰ ذَهَابِۭ بِهِۦ لَقَـٰدِرُونَ ۝١٨", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "وأنزلنا من السماء ماء بقدر حاجة الخلائق، وجعلنا الأرض مستقرًا لهذا الماء، وإنا على ذَهاب بالماء المستقر لَقادرون. وفي هذا تهديد ووعيد للظالمين.", "isBasmala": false, "translation_en": "And We sent down water from the sky in proper quantity, and settled it in the ground, and We are Able to take it away.", "translation_id": "Dan Kami turunkan air dari langit menurut suatu ukuran; lalu Kami jadikan air itu menetap di bumi, dan sesungguhnya Kami benar-benar berkuasa menghilangkannya.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 19, "text": "فَأَنشَأۡنَا لَكُم بِهِۦ جَنَّـٰتࣲ مِّن نَّخِیلࣲ وَأَعۡنَـٰبࣲ لَّكُمۡ فِیهَا فَوَ ٰكِهُ كَثِیرَةࣱ وَمِنۡهَا تَأۡكُلُونَ ۝١٩", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "فأنشأنا بهذا الماء لكم بساتين النخيل والأعناب، لكم فيها فواكه كثيرة الأنواع والأشكال، ومنها تأكلون.", "isBasmala": false, "translation_en": "With it We produce for you gardens of palms and vines, yielding abundant fruit for you to eat.", "translation_id": "Lalu dengan air itu, Kami tumbuhkan untuk kamu kebun-kebun kurma dan anggur; di dalam kebun-kebun itu kamu peroleh buah-buahan yang banyak dan sebahagian dari buah-buahan itu kamu makan,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 20, "text": "وَشَجَرَةࣰ تَخۡرُجُ مِن طُورِ سَیۡنَاۤءَ تَنۢبُتُ بِٱلدُّهۡنِ وَصِبۡغࣲ لِّلۡـَٔاكِلِینَ ۝٢٠", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "وأنشأنا لكم به شجرة الزيتون التي تخرج حول جبل طور \"سيناء\"، يعصر منها الزيت، فيدَّهن ويؤتدم به.", "isBasmala": false, "translation_en": "And a tree springing out of Mount Sinai, producing oil, and seasoning for those who eat.", "translation_id": "dan pohon kayu keluar dari Thursina (pohon zaitun), yang menghasilkan minyak, dan pemakan makanan bagi orang-orang yang makan.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 21, "text": "وَإِنَّ لَكُمۡ فِی ٱلۡأَنۡعَـٰمِ لَعِبۡرَةࣰۖ نُّسۡقِیكُم مِّمَّا فِی بُطُونِهَا وَلَكُمۡ فِیهَا مَنَـٰفِعُ كَثِیرَةࣱ وَمِنۡهَا تَأۡكُلُونَ ۝٢١", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "وإن لكم- أيها الناس- في الإبل والبقر والغنم لَعبرة تعتبرون بخلقها، نسقيكم مما في بطونها من اللبن، ولكم فيها منافع أخرى كثيرة كالصوف والجلود، ونحوهما، ومنها تأكلون.", "isBasmala": false, "translation_en": "And there is a lesson for you in livestock: We give you to drink from what is in their bellies, and you have many benefits in them, and from them you eat.", "translation_id": "Dan sesungguhnya pada binatang-binatang ternak, benar-benar terdapat pelajaran yang penting bagi kamu, Kami memberi minum kamu dari air susu yang ada dalam perutnya, dan (juga) pada binatang-binatang ternak itu terdapat faedah yang banyak untuk kamu, dan sebagian daripadanya kamu makan,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 22, "text": "وَعَلَیۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ ۝٢٢", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "وعلى الإبل والسفن في البر والبحر تُحْمَلون.", "isBasmala": false, "translation_en": "And on them, and on the ships, you are transported.", "translation_id": "dan di atas punggung binatang-binatang ternak itu dan (juga) di atas perahu-perahu kamu diangkut.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 23, "text": "وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤۚ أَفَلَا تَتَّقُونَ ۝٢٣", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "ولقد أرسلنا نوحًا إلى قومه، بدعوة التوحيد فقال لهم: اعبدوا الله وحده، ليس لكم من إله يستحق العبادة غيره جل وعلا، فأخلصوا له العبادة، أفلا تخشون عذابه؟", "isBasmala": false, "translation_en": "We sent Noah to his people. He said, \"O my people, worship God, you have no deity other than Him. Will you not take heed?\"", "translation_id": "Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, lalu ia berkata: \"Hai kaumku, sembahlah oleh kamu Allah, (karena) sekali-kali tidak ada Tuhan bagimu selain Dia. Maka mengapa kamu tidak bertakwa (kepada-Nya)?\"", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 24, "text": "فَقَالَ ٱلۡمَلَؤُا۟ ٱلَّذِینَ كَفَرُوا۟ مِن قَوۡمِهِۦ مَا هَـٰذَاۤ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ یُرِیدُ أَن یَتَفَضَّلَ عَلَیۡكُمۡ وَلَوۡ شَاۤءَ ٱللَّهُ لَأَنزَلَ مَلَـٰۤىِٕكَةࣰ مَّا سَمِعۡنَا بِهَـٰذَا فِیۤ ءَابَاۤىِٕنَا ٱلۡأَوَّلِینَ ۝٢٤", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "فكذَّبه أشراف قومه، وقالوا لعامتهم: إنه إنسان مثلكم لا يتميَّز عنكم بشيء، ولا يريد بقوله إلا رئاسة وفضلا عليكم، ولو شاء الله أن يرسل إلينا رسولا لأرسله من الملائكة، ما سمعنا بمثل هذا فيمَن سبقنا من آباء وأجداد. وما نوح إلا رجل به مَسٌّ من الجنون، فانتظروا حتى يُفيق، فيترك دعوته، أو يموت، فتستريحوا منه.", "isBasmala": false, "translation_en": "But the notables of his people, who disbelieved, said, \"This is nothing but a human like you, who wants to gain superiority over you. Had God willed, He would have sent down angels. We never heard of this from our forefathers of old.", "translation_id": "Maka pemuka-pemuka orang yang kafir di antara kaumnya menjawab: \"Orang ini tidak lain hanyalah manusia seperti kamu, yang bermaksud hendak menjadi seorang yang lebih tinggi dari kamu. Dan kalau Allah menghendaki, tentu Dia mengutus beberapa orang malaikat. Belum pernah kami mendengar (seruan yang seperti) ini pada masa nenek moyang kami yang dahulu.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 25, "text": "إِنۡ هُوَ إِلَّا رَجُلُۢ بِهِۦ جِنَّةࣱ فَتَرَبَّصُوا۟ بِهِۦ حَتَّىٰ حِینࣲ ۝٢٥", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "فكذَّبه أشراف قومه، وقالوا لعامتهم: إنه إنسان مثلكم لا يتميَّز عنكم بشيء، ولا يريد بقوله إلا رئاسة وفضلا عليكم، ولو شاء الله أن يرسل إلينا رسولا لأرسله من الملائكة، ما سمعنا بمثل هذا فيمَن سبقنا من آباء وأجداد. وما نوح إلا رجل به مَسٌّ من الجنون، فانتظروا حتى يُفيق، فيترك دعوته، أو يموت، فتستريحوا منه.", "isBasmala": false, "translation_en": "He is nothing but a man possessed. Just ignore him for a while.\"", "translation_id": "la tidak lain hanyalah seorang laki-laki yang berpenyakit gila, maka tunggulah (sabarlah) terhadapnya sampai suatu waktu\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 26, "text": "قَالَ رَبِّ ٱنصُرۡنِی بِمَا كَذَّبُونِ ۝٢٦", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "قال نوح: رب انصرني على قومي؛ بسبب تكذيبهم إياي فيما بلَّغتهم من رسالتك.", "isBasmala": false, "translation_en": "He said, \"My Lord, help me, for they have rejected me.\"", "translation_id": "Nuh berdoa: \"Ya Tuhanku, tolonglah aku, karena mereka mendustakan aku\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 27, "text": "فَأَوۡحَیۡنَاۤ إِلَیۡهِ أَنِ ٱصۡنَعِ ٱلۡفُلۡكَ بِأَعۡیُنِنَا وَوَحۡیِنَا فَإِذَا جَاۤءَ أَمۡرُنَا وَفَارَ ٱلتَّنُّورُ فَٱسۡلُكۡ فِیهَا مِن كُلࣲّ زَوۡجَیۡنِ ٱثۡنَیۡنِ وَأَهۡلَكَ إِلَّا مَن سَبَقَ عَلَیۡهِ ٱلۡقَوۡلُ مِنۡهُمۡۖ وَلَا تُخَـٰطِبۡنِی فِی ٱلَّذِینَ ظَلَمُوۤا۟ إِنَّهُم مُّغۡرَقُونَ ۝٢٧", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "فأوحينا إليه أن اصنع السفينة بمرأى منا وبأمرنا لك ومعونتنا، وأنت في حفظنا وكلاءتنا، فإذا جاء أمرنا بعذاب قومك بالغرق، وبدأ الطوفان، فنبع الماء بقوة من التنور -وهو المكان الذي يخبز فيه- علامة على مجيء العذاب، فأدخِلْ في السفينة من كل الأحياء ذكرًا وأنثى؛ ليبقى النسل، وأدخل أهلك إلا مَنِ استحق العذاب لكفره كزوجتك وابنك، ولا تسألني نجاة قومك الظالمين، فإنهم مغرقون لا محالة. وفي هذه الآية إثبات صفة العين لله سبحانه بما يليق به تعالى دون تشبيه ولا تكييف.", "isBasmala": false, "translation_en": "So We inspired him: \"Build the Ark under Our observation and by Our inspiration. And when Our decree comes to pass, and the oven boils over, load into it two pairs of every kind, together with your family, except those of them against whom the word has already been pronounced. And do not speak to me concerning those who did wrong; for they are to be drowned.\"", "translation_id": "Lalu Kami wahyukan kepadanya: \"Buatlah bahtera di bawah penilikan dan petunjuk Kami, maka apabila perintah Kami telah datang dan tanur telah memancarkan air, maka masukkanlah ke dalam bahtera itu sepasang dari tiap-tiap (jenis), dan (juga) keluargamu, kecuali orang yang telah lebih dahulu ditetapkan (akan ditimpa azab) di antara mereka. Dan janganlah kamu bicarakan dengan Aku tentang orang-orang yang zalim, karena sesungguhnya mereka itu akan ditenggelamkan.", "manzil": 4, "manzil_display": ""}], "344": [{"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 28, "text": "فَإِذَا ٱسۡتَوَیۡتَ أَنتَ وَمَن مَّعَكَ عَلَى ٱلۡفُلۡكِ فَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی نَجَّىٰنَا مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝٢٨", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "فإذا علوت السفينة مستقرًا عليها أنت ومن معك آمنين من الغرق، فقل: الحمد لله الذي نجَّانا من القوم الكافرين.", "isBasmala": false, "translation_en": "Then, when you and those with you are settled in the Ark, say, \"Praise be to God, who has saved us from the wrongdoing people.\"", "translation_id": "Apabila kamu dan orang-orang yang bersamamu telah berada di atas bahtera itu, maka ucapkanlah: \"Segala puji bagi Allah yang telah menyelamatkan kami dari orang-orang yang zalim\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 29, "text": "وَقُل رَّبِّ أَنزِلۡنِی مُنزَلࣰا مُّبَارَكࣰا وَأَنتَ خَیۡرُ ٱلۡمُنزِلِینَ ۝٢٩", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "وقل: رب يسِّر لي النزول المبارك الآمن، وأنت خير المنزلين. وفي هذا تعليم من الله عز وجل لعباده إذا نزلوا أن يقولوا هذا.", "isBasmala": false, "translation_en": "And say, \"My Lord, land me with a blessed landing, as you are the best of transporters.\"", "translation_id": "Dan berdoalah: Ya Tuhanku, tempatkanlah aku pada tempat yang diberkati, dan Engkau adalah sebaik-baik Yang memberi tempat\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 30, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ وَإِن كُنَّا لَمُبۡتَلِینَ ۝٣٠", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "إن في إنجاء المؤمنين وإهلاك الكافرين لَدلالات واضحات على صدق رسل الله فيما جاؤوا به من الله، وإن كنا لمختبرين الأمم بإرسال الرسل إليهم قبل وقوع العقوبة بهم.", "isBasmala": false, "translation_en": "Surely in that are signs. We are always testing.", "translation_id": "Sesungguhnya pada (kejadian) itu benar-benar terdapat beberapa tanda (kebesaran Allah), dan sesungguhnya Kami menimpakan azab (kepada kaum Nuh itu).", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 31, "text": "ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قَرۡنًا ءَاخَرِینَ ۝٣١", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "ثم أنشأنا من بعد قوم نوح جيلا آخر هم قوم عاد.", "isBasmala": false, "translation_en": "Then, after them, We established another generation.", "translation_id": "Kemudian, Kami jadikan sesudah mereka umat yang lain.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 32, "text": "فَأَرۡسَلۡنَا فِیهِمۡ رَسُولࣰا مِّنۡهُمۡ أَنِ ٱعۡبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنۡ إِلَـٰهٍ غَیۡرُهُۥۤۚ أَفَلَا تَتَّقُونَ ۝٣٢", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "فأرسلنا فيهم رسولا منهم هو هود عليه السلام، فقال لهم: اعبدوا الله وحده ليس لكم معبود بحق غيره، أفلا تخافون عقابه إذا عبدتم غيره؟", "isBasmala": false, "translation_en": "And We sent among them a messenger from themselves: \"Serve God. You have no god other than Him. Will you not be cautious?\"", "translation_id": "Lalu Kami utus kepada mereka, seorang rasul dari kalangan mereka sendiri (yang berkata): \"Sembahlah Allah oleh kamu sekalian, sekali-kali tidak ada Tuhan selain daripada-Nya. Maka mengapa kamu tidak bertakwa (kepada-Nya).", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 33, "text": "وَقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِ ٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِلِقَاۤءِ ٱلۡـَٔاخِرَةِ وَأَتۡرَفۡنَـٰهُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا مَا هَـٰذَاۤ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ یَأۡكُلُ مِمَّا تَأۡكُلُونَ مِنۡهُ وَیَشۡرَبُ مِمَّا تَشۡرَبُونَ ۝٣٣", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "وقال الأشراف والوجهاء من قومه الذين كفروا بالله، وأنكروا الحياة الآخرة، وأطغاهم ما أُنعم به عليهم في الدنيا من ترف العيش: ما هذا الذي يدعوكم إلى توحيد الله تعالى إلا بشر مثلكم يأكل من جنس طعامكم، ويشرب من جنس شرابكم.", "isBasmala": false, "translation_en": "But the dignitaries of his people, those who disbelieved and denied the meeting of the Hereafter, and We had indulged them in the present life, said, \"This is nothing but a human like you; he eats what you eat, and he drinks what you drink.", "translation_id": "Dan berkatalah pemuka-pemuka yang kafir di antara kaumnya dan yang mendustakan akan menemui hari akhirat (kelak) dan yang telah Kami mewahkan mereka dalam kehidupan di dunia: \"(Orang) ini tidak lain hanyalah manusia seperti kamu, dia makan dari apa yang kamu makan, dan meminum dari apa yang kamu minum.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 34, "text": "وَلَىِٕنۡ أَطَعۡتُم بَشَرࣰا مِّثۡلَكُمۡ إِنَّكُمۡ إِذࣰا لَّخَـٰسِرُونَ ۝٣٤", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "ولئن اتبعتم فردًا مثلكم إنكم إذًا لخاسرون بترككم آلهتكم واتباعكم إياه.", "isBasmala": false, "translation_en": "If you obey a human being like yourselves, then you will be losers.", "translation_id": "Dan sesungguhnya jika kamu sekalian mentaati manusia yang seperti kamu, niscaya bila demikian, kamu benar-benar (menjadi) orang-orang yang merugi.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 35, "text": "أَیَعِدُكُمۡ أَنَّكُمۡ إِذَا مِتُّمۡ وَكُنتُمۡ تُرَابࣰا وَعِظَـٰمًا أَنَّكُم مُّخۡرَجُونَ ۝٣٥", "juz": 18, "hizb": "(* ح 35*)", "tafsir": "كيف تُصَدِّقون ما يَعِدُكم به من أنكم إذا متُّم، وصرتم ترابًا وعظامًا مفتتة، تُخْرَجون من قبوركم أحياء؟", "isBasmala": false, "translation_en": "Does he promise you that when you have died and become dust and bones, you will be brought out?", "translation_id": "Apakah ia menjanjikan kepada kamu sekalian, bahwa bila kamu telah mati dan telah menjadi tanah dan tulang belulang, kamu sesungguhnya akan dikeluarkan (dari kuburmu)?", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 36, "text": "۞ هَیۡهَاتَ هَیۡهَاتَ لِمَا تُوعَدُونَ ۝٣٦", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "بعيد حقًا ما توعدون به أيها القوم من أنكم بعد موتكم تُخْرَجون أحياء من قبوركم.", "isBasmala": false, "translation_en": "Farfetched, farfetched is what you are promised.", "translation_id": "jauh, jauh sekali (dari kebenaran) apa yang diancamkan kepada kamu itu,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 37, "text": "إِنۡ هِیَ إِلَّا حَیَاتُنَا ٱلدُّنۡیَا نَمُوتُ وَنَحۡیَا وَمَا نَحۡنُ بِمَبۡعُوثِینَ ۝٣٧", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ما حياتنا إلا في هذه الدنيا، يموت الآباء منا ويحيا الأبناء، وما نحن بمخرجين أحياء مرة أخرى.", "isBasmala": false, "translation_en": "There is nothing but our life in this world. We die, and we live, and we are not resurrected.", "translation_id": "kehidupan itu tidak lain hanyalah kehidupan kita di dunia ini, kita mati dan kita hidup dan sekali-kali tidak akan dibangkitkan lagi,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 38, "text": "إِنۡ هُوَ إِلَّا رَجُلٌ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰا وَمَا نَحۡنُ لَهُۥ بِمُؤۡمِنِینَ ۝٣٨", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "وما هذا الداعي لكم إلى الإيمان إلا رجل اختلق على الله كذبًا، ولسنا بمصدقين ما قاله لنا.", "isBasmala": false, "translation_en": "He is nothing but a man, making up lies about God. We have no faith in him.\"", "translation_id": "Ia tidak lain hanyalah seorang yang mengada-adakan kebohongan terhadap Allah, dan kami sekali-kali tidak akan beriman kepadanya\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 39, "text": "قَالَ رَبِّ ٱنصُرۡنِی بِمَا كَذَّبُونِ ۝٣٩", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "فدعا رسولهم ربه قائلا رب انصرني عليهم بسبب تكذيبهم لي.", "isBasmala": false, "translation_en": "He said, \"My Lord, help me, for they have rejected me.\"", "translation_id": "Rasul itu berdoa: \"Ya Tuhanku, tolonglah aku karena mereka mendustakanku\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 40, "text": "قَالَ عَمَّا قَلِیلࣲ لَّیُصۡبِحُنَّ نَـٰدِمِینَ ۝٤٠", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "وقال الله مجيبًا لدعوته: عمَّا قليل ليصبحُنَّ نادمين، أي: بعد زمن قريب سيصير هؤلاء المكذبون نادمين.", "isBasmala": false, "translation_en": "He said, \"Soon they will be filled with regret.\"", "translation_id": "Allah berfirman: \"Dalam sedikit waktu lagi pasti mereka akan menjadi orang-orang yang menyesal\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 41, "text": "فَأَخَذَتۡهُمُ ٱلصَّیۡحَةُ بِٱلۡحَقِّ فَجَعَلۡنَـٰهُمۡ غُثَاۤءࣰۚ فَبُعۡدࣰا لِّلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝٤١", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ولم يلبثوا أن جاءتهم صيحة شديدة مع ريح، أهلكهم الله بها، فماتوا جميعًا، وأصبحوا كغثاء السيل الذي يطفو على الماء، فهلاكًا لهؤلاء الظالمين وبُعْدًا لهم من رحمة الله، فليحذر السامعون أن يكذبوا رسولهم، فيحل بهم ما حل بسابقيهم.", "isBasmala": false, "translation_en": "Then the Blast struck them, justifiably, and We turned them into scum. So away with the wicked people.", "translation_id": "Maka dimusnahkanlah mereka oleh suara yang mengguntur dengan hak dan Kami jadikan mereka (sebagai) sampah banjir maka kebinasaanlah bagi orang-orang yang zalim itu.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 42, "text": "ثُمَّ أَنشَأۡنَا مِنۢ بَعۡدِهِمۡ قُرُونًا ءَاخَرِینَ ۝٤٢", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ثم أنشأنا من بعد هؤلاء المكذبين أممًا وخلائق آخرين كأقوام: لوط وشعيب وأيوب ويونس صلوات الله وسلامه عليهم أجمعين.", "isBasmala": false, "translation_en": "Then, after them, We raised other generations.", "translation_id": "Kemudian Kami ciptakan sesudah mereka umat-umat yang lain.", "manzil": 4, "manzil_display": ""}], "345": [{"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 43, "text": "مَا تَسۡبِقُ مِنۡ أُمَّةٍ أَجَلَهَا وَمَا یَسۡتَـٔۡخِرُونَ ۝٤٣", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ما تتقدم أي أمة من هذه الأمم المكذبة الوقت المحدد لهلاكها، ولا تتأخر عنه.", "isBasmala": false, "translation_en": "No nation can advance its time, nor can they postpone it.", "translation_id": "Tidak (dapat) sesuatu umatpun mendahului ajalnya, dan tidak (dapat pula) mereka terlambat (dari ajalnya itu).", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 44, "text": "ثُمَّ أَرۡسَلۡنَا رُسُلَنَا تَتۡرَاۖ كُلَّ مَا جَاۤءَ أُمَّةࣰ رَّسُولُهَا كَذَّبُوهُۖ فَأَتۡبَعۡنَا بَعۡضَهُم بَعۡضࣰا وَجَعَلۡنَـٰهُمۡ أَحَادِیثَۚ فَبُعۡدࣰا لِّقَوۡمࣲ لَّا یُؤۡمِنُونَ ۝٤٤", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ثم أرسلنا رسلنا إلى تلك الأمم يتبع بعضهم بعضًا، كلما دعا رسول أمته كذبوه، فأتبعنا بعضهم بعضًا بالهلاك والدمار، ولم يَبْقَ إلا أخبار هلاكهم، وجعلناها أحاديث لمن بعدهم، يتخذونها عبرة، فهلاكًا وسُحْقًا لقوم لا يصدقون الرسل ولا يطيعونهم.", "isBasmala": false, "translation_en": "Then We sent Our messengers in succession. Every time a messenger came to his community, they called him a liar. So We made them follow one another, and made them history. So away with a people who do not believe.", "translation_id": "Kemudian Kami utus (kepada umat-umat itu) rasul-rasul Kami berturut-turut. Tiap-tiap seorang rasul datang kepada umatnya, umat itu mendustakannya, maka Kami perikutkan sebagian mereka dengan sebagian yang lain. Dan Kami jadikan mereka buah tutur (manusia), maka kebinasaanlah bagi orang-orang yang tidak beriman.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 45, "text": "ثُمَّ أَرۡسَلۡنَا مُوسَىٰ وَأَخَاهُ هَـٰرُونَ بِـَٔایَـٰتِنَا وَسُلۡطَـٰنࣲ مُّبِینٍ ۝٤٥", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ثم أرسلنا موسى وأخاه هارون بآياتنا التسع وهي: العصا واليد والجراد والقُمَّل والضفادع والدم والطوفان والسنون ونقص من الثمرات، حجةً بيِّنة تقهر القلوب فتنقاد لها قلوب المؤمنين، وتقوم الحجة على المعاندين، أرسلناهما إلى فرعون حاكم \"مصر\" وأشراف قومه، فاستكبروا عن الإيمان بموسى وأخيه، وكانوا قومًا متطاولين على الناس قاهرين لهم بالظلم.", "isBasmala": false, "translation_en": "Then We sent Moses and his brother Aaron, with Our signs and a clear authority.", "translation_id": "Kemudian Kami utus Musa dan saudaranya Harun dengan membawa tanda-tanda (Kebesaran) Kami, dan bukti yang nyata,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 46, "text": "إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ فَٱسۡتَكۡبَرُوا۟ وَكَانُوا۟ قَوۡمًا عَالِینَ ۝٤٦", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ثم أرسلنا موسى وأخاه هارون بآياتنا التسع وهي: العصا واليد والجراد والقُمَّل والضفادع والدم والطوفان والسنون ونقص من الثمرات، حجةً بيِّنة تقهر القلوب فتنقاد لها قلوب المؤمنين، وتقوم الحجة على المعاندين، أرسلناهما إلى فرعون حاكم \"مصر\" وأشراف قومه، فاستكبروا عن الإيمان بموسى وأخيه، وكانوا قومًا متطاولين على الناس قاهرين لهم بالظلم.", "isBasmala": false, "translation_en": "To Pharaoh and his nobles, but they turned arrogant. They were oppressive people.", "translation_id": "kepada Fir'aun dan pembesar-pembesar kaumnya, maka mereka ini takbur dan mereka adalah orang-orang yang sombong.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 47, "text": "فَقَالُوۤا۟ أَنُؤۡمِنُ لِبَشَرَیۡنِ مِثۡلِنَا وَقَوۡمُهُمَا لَنَا عَـٰبِدُونَ ۝٤٧", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "فقالوا: أنصدِّق فَرْدَيْن مثلنا، وقومهما من بني إسرائيل تحت إمرتنا مطيعون متذللون لنا؟", "isBasmala": false, "translation_en": "They said, \"Are we to believe in two mortals like us, and their people are our slaves?\"", "translation_id": "Dan mereka berkata: \"Apakah (patut) kita percaya kepada dua orang manusia seperti kita (juga), padahal kaum mereka (Bani Israil) adalah orang-orang yang menghambakan diri kepada kita?\"", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 48, "text": "فَكَذَّبُوهُمَا فَكَانُوا۟ مِنَ ٱلۡمُهۡلَكِینَ ۝٤٨", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "فكذبوهما فيما جاءا به، فكانوا من المهلكين بالغرق في البحر.", "isBasmala": false, "translation_en": "So they called them liars, and thus were among those destroyed.", "translation_id": "Maka (tetaplah) mereka mendustakan keduanya, sebab itu mereka adalah termasuk orang-orang yang dibinasakan.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 49, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ لَعَلَّهُمۡ یَهۡتَدُونَ ۝٤٩", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ولقد آتينا موسى التوراة؛ ليهتدي بها قومه إلى الحق.", "isBasmala": false, "translation_en": "And We gave Moses the Scripture, that they may be guided.", "translation_id": "Dan sesungguhnya telah Kami berikan Al Kitab (Taurat) kepada Musa, agar mereka (Bani Israil) mendapat petunjuk.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 50, "text": "وَجَعَلۡنَا ٱبۡنَ مَرۡیَمَ وَأُمَّهُۥۤ ءَایَةࣰ وَءَاوَیۡنَـٰهُمَاۤ إِلَىٰ رَبۡوَةࣲ ذَاتِ قَرَارࣲ وَمَعِینࣲ ۝٥٠", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "وجعلنا عيسى بن مريم وأمه علامة دالة على قدرتنا؛ إذ خلقناه من غير أب، وجعلنا لهما مأوى في مكان مرتفع من الأرض، مستوٍ للاستقرار عليه، فيه خصوبة وماء جار ظاهر للعيون.", "isBasmala": false, "translation_en": "And We made Mary's son and his mother a sign, and We sheltered them on high ground with security and flowing springs.", "translation_id": "Dan telah Kami jadikan (Isa) putera Maryam beserta ibunya suatu bukti yang nyata bagi (kekuasaan Kami), dan Kami melindungi mereka di suatu tanah tinggi yang datar yang banyak terdapat padang-padang rumput dan sumber-sumber air bersih yang mengalir.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 51, "text": "یَـٰۤأَیُّهَا ٱلرُّسُلُ كُلُوا۟ مِنَ ٱلطَّیِّبَـٰتِ وَٱعۡمَلُوا۟ صَـٰلِحًاۖ إِنِّی بِمَا تَعۡمَلُونَ عَلِیمࣱ ۝٥١", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "يا أيها الرسل كلوا من طيب الرزق الحلال، واعملوا الأعمال الصالحة، إني بما تعملون عليم، لا يخفى عليَّ شيء من أعمالكم. والخطاب في الآية عام للرسل- عليهم السلام- وأتباعهم، وفي الآية دليل على أن أكل الحلال عون على العمل الصالح، وأن عاقبة الحرام وخيمة، ومنها رد الدعاء.", "isBasmala": false, "translation_en": "O messengers, eat of the good things, and act with integrity. I am aware of what you do.", "translation_id": "Hai rasul-rasul, makanlah dari makanan yang baik-baik, dan kerjakanlah amal yang saleh. Sesungguhnya Aku Maha Mengetahui apa yang kamu kerjakan.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 52, "text": "وَإِنَّ هَـٰذِهِۦۤ أُمَّتُكُمۡ أُمَّةࣰ وَ ٰحِدَةࣰ وَأَنَا۠ رَبُّكُمۡ فَٱتَّقُونِ ۝٥٢", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "وإنَّ دينكم- يا معشر الأنبياء- دين واحد وهو الإسلام، وأنا ربكم فاتقوني بامتثال أوامري واجتناب زواجري.", "isBasmala": false, "translation_en": "This nation of yours is one nation, and I am your Lord, so fear Me.", "translation_id": "Sesungguhnya (agama tauhid) ini, adalah agama kamu semua, agama yang satu, dan Aku adalah Tuhanmu, maka bertakwalah kepada-Ku.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 53, "text": "فَتَقَطَّعُوۤا۟ أَمۡرَهُم بَیۡنَهُمۡ زُبُرࣰاۖ كُلُّ حِزۡبِۭ بِمَا لَدَیۡهِمۡ فَرِحُونَ ۝٥٣", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "فتفرَّق الأتباع في الدين إلى أحزاب وشيع، جعلوا دينهم أديانًا بعدما أُمروا بالاجتماع، كل حزب معجب برأيه زاعم أنه على الحق وغيره على الباطل. وفي هذا تحذير من التحزب والتفرق في الدين.", "isBasmala": false, "translation_en": "But they tore themselves into sects; each party happy with what they have.", "translation_id": "Kemudian mereka (pengikut-pengikut rasul itu) menjadikan agama mereka terpecah belah menjadi beberapa pecahan. Tiap-tiap golongan merasa bangga dengan apa yang ada pada sisi mereka (masing-masing).", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 54, "text": "فَذَرۡهُمۡ فِی غَمۡرَتِهِمۡ حَتَّىٰ حِینٍ ۝٥٤", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "فاتركهم - أيها الرسول - في ضلالتهم وجهلهم بالحق إلى أن ينزل العذاب بهم.", "isBasmala": false, "translation_en": "So leave them in their bewilderment until a time.", "translation_id": "Maka biarkanlah mereka dalam kesesatannya sampai suatu waktu.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 55, "text": "أَیَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالࣲ وَبَنِینَ ۝٥٥", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "أيظن هؤلاء الكفار أن ما نمدُّهم به من أموال وأولاد في الدنيا هو تعجيلُ خيرٍ لهم يستحقونه؟ إنما نعجل لهم الخير فتنة لهم واستدراجًا، ولكنهم لا يُحِسُّون بذلك.", "isBasmala": false, "translation_en": "Do they assume that, in furnishing them with wealth and children.", "translation_id": "Apakah mereka mengira bahwa harta dan anak-anak yang Kami berikan kepada mereka itu (berarti bahwa),", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 56, "text": "نُسَارِعُ لَهُمۡ فِی ٱلۡخَیۡرَ ٰتِۚ بَل لَّا یَشۡعُرُونَ ۝٥٦", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "أيظن هؤلاء الكفار أن ما نمدُّهم به من أموال وأولاد في الدنيا هو تعجيلُ خيرٍ لهم يستحقونه؟ إنما نعجل لهم الخير فتنة لهم واستدراجًا، ولكنهم لا يُحِسُّون بذلك.", "isBasmala": false, "translation_en": "We race to give them the good things? In fact, they have no idea.", "translation_id": "Kami bersegera memberikan kebaikan-kebaikan kepada mereka? Tidak, sebenarnya mereka tidak sadar.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 57, "text": "إِنَّ ٱلَّذِینَ هُم مِّنۡ خَشۡیَةِ رَبِّهِم مُّشۡفِقُونَ ۝٥٧", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "إنَّ الذين هم من خشية ربهم مشفقون وَجِلون مما خوَّفهم الله تعالى به.", "isBasmala": false, "translation_en": "Those who, from awe of their Lord, are fearful.", "translation_id": "Sesungguhnya orang-orang yang berhati-hati karena takut akan (azab) Tuhan mereka,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 58, "text": "وَٱلَّذِینَ هُم بِـَٔایَـٰتِ رَبِّهِمۡ یُؤۡمِنُونَ ۝٥٨", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "والذين هم يصدِّقون بآيات الله في القرآن، ويعملون بها.", "isBasmala": false, "translation_en": "And those who believe in their Lord's Verses.", "translation_id": "Dan orang-orang yang beriman dengan ayat-ayat Tuhan mereka,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 59, "text": "وَٱلَّذِینَ هُم بِرَبِّهِمۡ لَا یُشۡرِكُونَ ۝٥٩", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "والذين هم يخلصون العبادة لله وحده، ولا يشركون به غيره.", "isBasmala": false, "translation_en": "And those who associate no partners with their Lord.", "translation_id": "Dan orang-orang yang tidak mempersekutukan dengan Tuhan mereka (sesuatu apapun),", "manzil": 4, "manzil_display": ""}], "346": [{"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 60, "text": "وَٱلَّذِینَ یُؤۡتُونَ مَاۤ ءَاتَوا۟ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَ ٰجِعُونَ ۝٦٠", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "والذين يجتهدون في أعمال الخير والبر، وقلوبهم خائفة ألا تُقبل أعمالهم، وألا تنجيهم من عذاب ربهم إذا رجعوا إليه للحساب.", "isBasmala": false, "translation_en": "And those who give what they give, while their hearts quake, knowing that to their Lord they will return.", "translation_id": "Dan orang-orang yang memberikan apa yang telah mereka berikan, dengan hati yang takut, (karena mereka tahu bahwa) sesungguhnya mereka akan kembali kepada Tuhan mereka,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 61, "text": "أُو۟لَـٰۤىِٕكَ یُسَـٰرِعُونَ فِی ٱلۡخَیۡرَ ٰتِ وَهُمۡ لَهَا سَـٰبِقُونَ ۝٦١", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "أولئك المجتهدون في الطاعة، دأبهم المسارعة إلى كل عمل صالح، وهم إلى الخيرات سابقون.", "isBasmala": false, "translation_en": "It is they who race towards goodness. It is they who will reach it first.", "translation_id": "mereka itu bersegera untuk mendapat kebaikan-kebaikan, dan merekalah orang-orang yang segera memperolehnya.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 62, "text": "وَلَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۚ وَلَدَیۡنَا كِتَـٰبࣱ یَنطِقُ بِٱلۡحَقِّ وَهُمۡ لَا یُظۡلَمُونَ ۝٦٢", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ولا نكلف عبدًا من عبادنا إلا بما يسعه العمل به، وأعمالهم مسطورة عندنا في كتاب إحصاء الأعمال الذي ترفعه الملائكة ينطق بالحق عليهم، ولا يُظْلم أحد منهم.", "isBasmala": false, "translation_en": "We never burden any soul beyond its capacity. And with Us is a record that tells the truth, and they will not be wronged.", "translation_id": "Kami tiada membebani seseorang melainkan menurut kesanggupannya, dan pada sisi Kami ada suatu kitab yang membicarakan kebenaran, dan mereka tidak dianiaya.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 63, "text": "بَلۡ قُلُوبُهُمۡ فِی غَمۡرَةࣲ مِّنۡ هَـٰذَا وَلَهُمۡ أَعۡمَـٰلࣱ مِّن دُونِ ذَ ٰلِكَ هُمۡ لَهَا عَـٰمِلُونَ ۝٦٣", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "لكن قلوب الكفار في ضلال غامر عن هذا القرآن وما فيه، ولهم مع شركهم أعمال سيئة، يُمْهلهم الله ليعملوها، فينالوا غضب الله وعقابه.", "isBasmala": false, "translation_en": "But their hearts are puzzled because of this; and they have deeds that do not conform to this, which they continue to perpetrate.", "translation_id": "Tetapi hati orang-orang kafir itu dalam kesesatan dari (memahami kenyataan) ini, dan mereka banyak mengerjakan perbuatan-perbuatan (buruk) selain daripada itu, mereka tetap mengerjakannya.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 64, "text": "حَتَّىٰۤ إِذَاۤ أَخَذۡنَا مُتۡرَفِیهِم بِٱلۡعَذَابِ إِذَا هُمۡ یَجۡـَٔرُونَ ۝٦٤", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "حتى إذا أخذنا المترفين وأهل البطر منهم بعذابنا، إذا هم يرفعون أصواتهم يتضرعون مستغيثين.", "isBasmala": false, "translation_en": "Until, when We seize the decadent among them with torment, they begin to groan.", "translation_id": "Hingga apabila Kami timpakan azab, kepada orang-orang yang hidup mewah di antara mereka, dengan serta merta mereka memekik minta tolong.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 65, "text": "لَا تَجۡـَٔرُوا۟ ٱلۡیَوۡمَۖ إِنَّكُم مِّنَّا لَا تُنصَرُونَ ۝٦٥", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "فيقال لهم: لا تصرخوا، ولا تستغيثوا اليوم، إنكم لا تستطيعون نصر أنفسكم، ولا ينصركم أحد من عذاب الله.", "isBasmala": false, "translation_en": "Do not groan today. You will receive no help from Us.", "translation_id": "Janganlah kamu memekik minta tolong pada hari ini. Sesungguhnya kamu tiada akan mendapat pertolongan dari Kami.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 66, "text": "قَدۡ كَانَتۡ ءَایَـٰتِی تُتۡلَىٰ عَلَیۡكُمۡ فَكُنتُمۡ عَلَىٰۤ أَعۡقَـٰبِكُمۡ تَنكِصُونَ ۝٦٦", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "قد كانت آيات القرآن تُقرأ عليكم؛ لتؤمنوا بها، فكنتم تنفرون من سماعها والتصديق بها، والعمل بها كما يفعل الناكص على عقبيه برجوعه إلى الوراء.", "isBasmala": false, "translation_en": "My Verses were recited to you, but you turned back on your heels.", "translation_id": "Sesungguhnya ayat-ayat-Ku (Al Quran) selalu dibacakan kepada kamu sekalian, maka kamu selalu berpaling ke belakang,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 67, "text": "مُسۡتَكۡبِرِینَ بِهِۦ سَـٰمِرࣰا تَهۡجُرُونَ ۝٦٧", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "تفعلون ذلك مستكبرين على الناس بغير الحق بسبب بيت الله الحرام، تقولون: نحن أهله لا نُغْلَب فيه، وتتسامرون حوله بالسيِّئ من القول.", "isBasmala": false, "translation_en": "Arrogant towards it-talked nonsense about it-disregarded it.", "translation_id": "dengan menyombongkan diri terhadap Al Quran itu dan mengucapkan perkataan-perkataan keji terhadapnya di waktu kamu bercakap-cakap di malam hari.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 68, "text": "أَفَلَمۡ یَدَّبَّرُوا۟ ٱلۡقَوۡلَ أَمۡ جَاۤءَهُم مَّا لَمۡ یَأۡتِ ءَابَاۤءَهُمُ ٱلۡأَوَّلِینَ ۝٦٨", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "أفلم يتفكروا في القرآن فيعرفوا صدقه، أم منعهم من الإيمان أنه جاءهم رسول وكتاب لم يأت أباءهم الأولين مثله، فأنكروه وأعرضوا عنه؟", "isBasmala": false, "translation_en": "Have they not pondered the Word? Or has there come to them what came not to their forefathers of old?", "translation_id": "Maka apakah mereka tidak memperhatikan perkataan (Kami), atau apakah telah datang kepada mereka apa yang tidak pernah datang kepada nenek moyang mereka dahulu?", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 69, "text": "أَمۡ لَمۡ یَعۡرِفُوا۟ رَسُولَهُمۡ فَهُمۡ لَهُۥ مُنكِرُونَ ۝٦٩", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "أم منعهم من اتباع الحق أن رسولهم محمدًا صلى الله عليه وسلم غير معروف عندهم، فهم منكرون له؟", "isBasmala": false, "translation_en": "Or is it that they did not recognize their messenger, so they are denying him?", "translation_id": "Ataukah mereka tidak mengenal rasul mereka, karena itu mereka memungkirinya?", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 70, "text": "أَمۡ یَقُولُونَ بِهِۦ جِنَّةُۢۚ بَلۡ جَاۤءَهُم بِٱلۡحَقِّ وَأَكۡثَرُهُمۡ لِلۡحَقِّ كَـٰرِهُونَ ۝٧٠", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "بل أحسبوه مجنونًا؟ لقد كذَبوا؛ فإنما جاءهم بالقرآن والتوحيد والدين الحق، وأكثرهم كارهون للحق حسدًا وبغيًا.", "isBasmala": false, "translation_en": "Or do they say, \"He is possessed?\" In fact, he brought them the truth, but most of them hate the truth.", "translation_id": "Atau (apakah patut) mereka berkata: \"Padanya (Muhammad) ada penyakit gila\". Sebenarnya dia telah membawa kebenaran kepada mereka, dan kebanyakan mereka benci kepada kebenaran itu.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 71, "text": "وَلَوِ ٱتَّبَعَ ٱلۡحَقُّ أَهۡوَاۤءَهُمۡ لَفَسَدَتِ ٱلسَّمَـٰوَ ٰتُ وَٱلۡأَرۡضُ وَمَن فِیهِنَّۚ بَلۡ أَتَیۡنَـٰهُم بِذِكۡرِهِمۡ فَهُمۡ عَن ذِكۡرِهِم مُّعۡرِضُونَ ۝٧١", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "ولو شرع الله لهم ما يوافق أهواءهم لفسدت السموات والأرض ومَن فيهن، بل أتيناهم بما فيه عزهم وشرفهم، وهو القرآن، فهم عنه معرضون.", "isBasmala": false, "translation_en": "If the truth conformed to their desires, the heavens, the earth, and everyone in them would have gone to ruin. In fact, We have given them their message, but they keep avoiding their message.", "translation_id": "Andaikata kebenaran itu menuruti hawa nafsu mereka, pasti binasalah langit dan bumi ini, dan semua yang ada di dalamnya. Sebenarnya Kami telah mendatangkan kepada mereka kebanggaan (Al Quran) mereka tetapi mereka berpaling dari kebanggaan itu.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 72, "text": "أَمۡ تَسۡـَٔلُهُمۡ خَرۡجࣰا فَخَرَاجُ رَبِّكَ خَیۡرࣱۖ وَهُوَ خَیۡرُ ٱلرَّ ٰزِقِینَ ۝٧٢", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "بل أَمَنعهم من الإيمان أنك - أيها الرسول - تسألهم أجرًا على دعوتك لهم فبخلوا؟ لم تفعل ذلك، فإن ما عند الله من الثواب والعطاء خير، وهو خير الرازقين، فلا يَقدر أحد أن يَرزق مثل رزقه سبحانه وتعالى.", "isBasmala": false, "translation_en": "Or are you asking them for a payment? The revenue from your Lord is better, and He is the Best of providers.", "translation_id": "Atau kamu meminta upah kepada mereka?\", maka upah dari Tuhanmu adalah lebih baik, dan Dia adalah Pemberi rezeki Yang Paling Baik.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 73, "text": "وَإِنَّكَ لَتَدۡعُوهُمۡ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٧٣", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "وإنك - أيها الرسول - لتدعو قومك وغيرهم إلى دينٍ قويم، وهو دين الإسلام.", "isBasmala": false, "translation_en": "You are inviting them to a straight path.", "translation_id": "Dan sesungguhnya kamu benar-benar menyeru mereka kepada jalan yang lurus.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 74, "text": "وَإِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ عَنِ ٱلصِّرَ ٰطِ لَنَـٰكِبُونَ ۝٧٤", "juz": 18, "hizb": "(*¼ ح 35*)", "tafsir": "وإن الذين لا يُصَدِّقون بالبعث والحساب، ولا يعملون لهما، عن طريق الدين القويم لمائلون إلى غيره.", "isBasmala": false, "translation_en": "But those who do not believe in the Hereafter are swerving from the path.", "translation_id": "Dan sesungguhnya orang-orang yang tidak beriman kepada negeri akhirat benar-benar menyimpang dari jalan (yang lurus).", "manzil": 4, "manzil_display": ""}], "347": [{"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 75, "text": "۞ وَلَوۡ رَحِمۡنَـٰهُمۡ وَكَشَفۡنَا مَا بِهِم مِّن ضُرࣲّ لَّلَجُّوا۟ فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ ۝٧٥", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "ولو رحمناهم وكشفنا عنهم ما بهم مِن قحط وجوع لَتمادوا في الكفر والعناد، يتحيَّرون ويتخبطون.", "isBasmala": false, "translation_en": "Even if We had mercy on them, and relieved their problems, they would still blindly persist in their defiance.", "translation_id": "Andaikata mereka Kami belas kasihani, dan Kami lenyapkan kemudharatan yang mereka alami, benar-benar mereka akan terus menerus terombang-ambing dalam keterlaluan mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 76, "text": "وَلَقَدۡ أَخَذۡنَـٰهُم بِٱلۡعَذَابِ فَمَا ٱسۡتَكَانُوا۟ لِرَبِّهِمۡ وَمَا یَتَضَرَّعُونَ ۝٧٦", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "ولقد ابتليناهم بصنوف المصائب فما خضعوا لربهم، وما دعوه خاشعين عند نزولها.", "isBasmala": false, "translation_en": "We have already gripped them with suffering, but they did not surrender to their Lord, nor did they humble themselves.", "translation_id": "Dan sesungguhnya Kami telah pernah menimpakan azab kepada mereka, maka mereka tidak tunduk kepada Tuhan mereka, dan (juga) tidak memohon (kepada-Nya) dengan merendahkan diri.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 77, "text": "حَتَّىٰۤ إِذَا فَتَحۡنَا عَلَیۡهِم بَابࣰا ذَا عَذَابࣲ شَدِیدٍ إِذَا هُمۡ فِیهِ مُبۡلِسُونَ ۝٧٧", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "حتى إذا فتحنا عليهم بابًا من العذاب الشديد في الآخرة، إذا هم فيه آيسون من كل خير، متحيرون لا يدرون ما يصنعون.", "isBasmala": false, "translation_en": "Until, when We have opened before them a gate of intense agony, at once they will despair.", "translation_id": "Hingga apabila Kami bukakan untuk mereka suatu pintu tempat azab yang amat sangat (di waktu itulah) tiba-tiba mereka menjadi putus asa.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 78, "text": "وَهُوَ ٱلَّذِیۤ أَنشَأَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ ۝٧٨", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "وهو الذي أنشأ لكم السمع لإدراك المسموعات، والأبصار لإدراك المرئيات، والأفئدة لتفقهوا بها، ومع ذلك فشكركم لهذه النعم المتوالية عليكم قليل لا يُذْكَر.", "isBasmala": false, "translation_en": "It is He who produced for you the hearing, and the eyesight, and the feelings. But little gratitude you show.", "translation_id": "Dan Dialah yang telah menciptakan bagi kamu sekalian, pendengaran, penglihatan dan hati. Amat sedikitlah kamu bersyukur.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 79, "text": "وَهُوَ ٱلَّذِی ذَرَأَكُمۡ فِی ٱلۡأَرۡضِ وَإِلَیۡهِ تُحۡشَرُونَ ۝٧٩", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "وهو الذي خلق جميع الناس في الأرض، وإليه تُحشرون بعد موتكم، فيجازيكم بما عملتم من خير أو شر.", "isBasmala": false, "translation_en": "And it is He who multiplied you on earth, and to Him you will be gathered.", "translation_id": "Dan Dialah yang menciptakan serta mengembang biakkan kamu di bumi ini dan kepada-Nya-lah kamu akan dihimpunkan.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 80, "text": "وَهُوَ ٱلَّذِی یُحۡیِۦ وَیُمِیتُ وَلَهُ ٱخۡتِلَـٰفُ ٱلَّیۡلِ وَٱلنَّهَارِۚ أَفَلَا تَعۡقِلُونَ ۝٨٠", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "وهو وحده الذي يحيي من العدم، ويميت بعد الحياة، وله تعاقب الليل والنهار وتفاوتهما، أفلا تعقلون قدرته ووحدانيته؟", "isBasmala": false, "translation_en": "And it is He who gives life and brings death, and to Him is the alternation of night and day. Do you not understand?", "translation_id": "Dan Dialah yang menghidupkan dan mematikan, dan Dialah yang (mengatur) pertukaran malam dan siang. Maka apakah kamu tidak memahaminya?", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 81, "text": "بَلۡ قَالُوا۟ مِثۡلَ مَا قَالَ ٱلۡأَوَّلُونَ ۝٨١", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "لكن الكفار لم يصدقوا بالبعث، بل ردَّدوا مقولة أسلافهم المنكرين.", "isBasmala": false, "translation_en": "But they say the like of what the ancients said.", "translation_id": "Sebenarnya mereka mengucapkan perkataan yang serupa dengan perkataan yang diucapkan oleh orang-orang dahulu kala.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 82, "text": "قَالُوۤا۟ أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰا وَعِظَـٰمًا أَءِنَّا لَمَبۡعُوثُونَ ۝٨٢", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "قالوا: أإذا متنا وتحللت أجسامنا وعظامنا في تراب الأرض نحيا مرة أُخرى؟ هذا لا يكون ولا يُتصور.", "isBasmala": false, "translation_en": "They say, \"After we have died, and become dust and bones, will we be resurrected?", "translation_id": "Mereka berkata: \"Apakah betul, apabila kami telah mati dan kami telah menjadi tanah dan tulang belulang, apakah sesungguhnya kami benar-benar akan dibangkitkan?", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 83, "text": "لَقَدۡ وُعِدۡنَا نَحۡنُ وَءَابَاۤؤُنَا هَـٰذَا مِن قَبۡلُ إِنۡ هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ۝٨٣", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "لقد قيل هذا الكلام لآبائنا من قبل، كما تقوله لنا يا محمد، فلم نره حقيقة، ما هذا إلا أباطيل الأولين.", "isBasmala": false, "translation_en": "We were promised this before-we and our ancestors-these are nothing but legends of the ancients.\"", "translation_id": "Sesungguhnya kami dan bapak-bapak kami telah diberi ancaman (dengan) ini dahulu, ini tidak lain hanyalah dongengan orang-orang dahulu kala!\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 84, "text": "قُل لِّمَنِ ٱلۡأَرۡضُ وَمَن فِیهَاۤ إِن كُنتُمۡ تَعۡلَمُونَ ۝٨٤", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "قل لهم: لمن هذه الأرض ومَن فيها إن كان لديكم علم؟", "isBasmala": false, "translation_en": "Say, \"To whom does the earth belong, and everyone in it, if you happen to know?\"", "translation_id": "Katakanlah: \"Kepunyaan siapakah bumi ini, dan semua yang ada padanya, jika kamu mengetahui?\"", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 85, "text": "سَیَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَذَكَّرُونَ ۝٨٥", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "سيعترفون حتمًا بأنها لله، هو خالقها ومالكها، قل لهم: ألا يكون لكم في ذلك تذكُّر بأنه قادر على البعث والنشور؟", "isBasmala": false, "translation_en": "They will say, \"To God.\" Say, \"Will you not reflect?\"", "translation_id": "Mereka akan menjawab: \"Kepunyaan Allah\". Katakanlah: \"Maka apakah kamu tidak ingat?\"", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 86, "text": "قُلۡ مَن رَّبُّ ٱلسَّمَـٰوَ ٰتِ ٱلسَّبۡعِ وَرَبُّ ٱلۡعَرۡشِ ٱلۡعَظِیمِ ۝٨٦", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "قل مَن رب السموات السبع ورب العرش العظيم، الذي هو أعظم المخلوقات وأعلاها؟", "isBasmala": false, "translation_en": "Say, \"Who is the Lord of the seven heavens, and Lord of the Splendid Throne?\"", "translation_id": "Katakanlah: \"Siapakah Yang Empunya langit yang tujuh dan Yang Empunya 'Arsy yang besar?\"", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 87, "text": "سَیَقُولُونَ لِلَّهِۚ قُلۡ أَفَلَا تَتَّقُونَ ۝٨٧", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "سيقولون حتمًا: هو الله، فقل لهم: أفلا تخافون عذابه إذا عبدتم غيره؟", "isBasmala": false, "translation_en": "They will say, \"To God.\" Say, \"Will you not become righteous?\"", "translation_id": "Mereka akan menjawab: \"Kepunyaan Allah\". Katakanlah: \"Maka apakah kamu tidak bertakwa?\"", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 88, "text": "قُلۡ مَنۢ بِیَدِهِۦ مَلَكُوتُ كُلِّ شَیۡءࣲ وَهُوَ یُجِیرُ وَلَا یُجَارُ عَلَیۡهِ إِن كُنتُمۡ تَعۡلَمُونَ ۝٨٨", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "قل: مَن مالك كل شيء ومَن بيده خزائن كل شيء، ومَن يجير مَنِ استجار به، ولا يقدر أحد أن يُجير ويحمي مَن أراد الله إهلاكه، ولا يدفع الشر الذي قدَّره الله، إن كنتم تعلمون ذلك؟", "isBasmala": false, "translation_en": "Say, \"In whose hand is the dominion of all things, and He protects and cannot be protected from, if you happen to know?\"", "translation_id": "Katakanlah: \"Siapakah yang di tangan-Nya berada kekuasaan atas segala sesuatu sedang Dia melindungi, tetapi tidak ada yang dapat dilindungi dari (azab)-Nya, jika kamu mengetahui?\"", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 89, "text": "سَیَقُولُونَ لِلَّهِۚ قُلۡ فَأَنَّىٰ تُسۡحَرُونَ ۝٨٩", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "سيجيبون: بأن ذلك كلَّه لله، قل لهم: كيف تذهب عقولكم وتُخْدَعون وتُصْرفون عن توحيد الله وطاعته، وتصديق أمر البعث والنشور؟", "isBasmala": false, "translation_en": "They will say, \"To God.\" Say, \"Then are you bewitched?\"", "translation_id": "Mereka akan menjawab: \"Kepunyaan Allah\". Katakanlah: \"(Kalau demikian), maka dari jalan manakah kamu ditipu?\"", "manzil": 4, "manzil_display": ""}], "348": [{"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 90, "text": "بَلۡ أَتَیۡنَـٰهُم بِٱلۡحَقِّ وَإِنَّهُمۡ لَكَـٰذِبُونَ ۝٩٠", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "بل أتينا هؤلاء المنكرين بالحق فيما أرسلنا به محمدًا صلى الله عليه وسلم، وإنهم لَكاذبون في شركهم وإنكارهم البعث.", "isBasmala": false, "translation_en": "In fact, We have given them the truth, and they are liars.", "translation_id": "Sebenarnya Kami telah membawa kebenaran kepada mereka, dan sesungguhnya mereka benar-benar orang-orang yang berdusta.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 91, "text": "مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدࣲ وَمَا كَانَ مَعَهُۥ مِنۡ إِلَـٰهٍۚ إِذࣰا لَّذَهَبَ كُلُّ إِلَـٰهِۭ بِمَا خَلَقَ وَلَعَلَا بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲۚ سُبۡحَـٰنَ ٱللَّهِ عَمَّا یَصِفُونَ ۝٩١", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "لم يجعل الله لنفسه ولدًا، ولم يكن معه من معبود آخر؛ لأنه لو كان ثمة أكثر مِن معبود لانفرد كل معبود بمخلوقاته، ولكان بينهم مغالبة كشأن ملوك الدنيا، فيختلُّ نظام الكون، تنزَّه الله سبحانه وتعالى وتقدَّس عن وصفهم له بأن له شريكًا أو ولدًا.", "isBasmala": false, "translation_en": "God has never begotten a son, nor is there any god besides Him. Otherwise, each god would have taken away what it has created, and some of them would have gained supremacy over others. Glory be to God, far beyond what they describe.", "translation_id": "Allah sekali-kali tidak mempunyai anak, dan sekali-kali tidak ada tuhan (yang lain) beserta-Nya, kalau ada tuhan beserta-Nya, masing-masing tuhan itu akan membawa makhluk yang diciptakannya, dan sebagian dari tuhan-tuhan itu akan mengalahkan sebagian yang lain. Maha Suci Allah dari apa yang mereka sifatkan itu,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 92, "text": "عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ ۝٩٢", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "هو وحده يعلم ما غاب عن خلقه وما شاهدوه، فتنزَّه الله تعالى عن الشريك الذي يزعمون.", "isBasmala": false, "translation_en": "The Knower of the hidden and the manifest. He is exalted, far above what they associate.", "translation_id": "Yang mengetahui semua yang ghaib dan semua yang nampak, maka Maha Tinggilah Dia dari apa yang mereka persekutukan.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 93, "text": "قُل رَّبِّ إِمَّا تُرِیَنِّی مَا یُوعَدُونَ ۝٩٣", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "قل - أيها الرسول -: ربِّ إما ترينِّي في هؤلاء المشركين ما تَعِدُهم مِن عذابك فلا تهلكني بما تهلكهم به، ونجني من عذابك وسخطك، فلا تجعلني في القوم المشركين الظالمين، ولكن اجعلني ممن رضيتَ عنهم.", "isBasmala": false, "translation_en": "Say, \"My Lord, if You would show me what they are promised.", "translation_id": "Katakanlah: \"Ya Tuhanku, jika Engkau sungguh-sungguh hendak memperlihatkan kepadaku azab yang diancamkan kepada mereka,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 94, "text": "رَبِّ فَلَا تَجۡعَلۡنِی فِی ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝٩٤", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "قل - أيها الرسول -: ربِّ إما ترينِّي في هؤلاء المشركين ما تَعِدُهم مِن عذابك فلا تهلكني بما تهلكهم به، ونجني من عذابك وسخطك، فلا تجعلني في القوم المشركين الظالمين، ولكن اجعلني ممن رضيتَ عنهم.", "isBasmala": false, "translation_en": "My Lord, do not place me among the wicked people.\"", "translation_id": "ya Tuhanku, maka janganlah Engkau jadikan aku berada di antara orang-orang yang zalim\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 95, "text": "وَإِنَّا عَلَىٰۤ أَن نُّرِیَكَ مَا نَعِدُهُمۡ لَقَـٰدِرُونَ ۝٩٥", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "وإننا لَقادرون على أن نريك ما نَعِدُهم من العذاب.", "isBasmala": false, "translation_en": "We are surely Able to show you what We promise them.", "translation_id": "Dan sesungguhnya Kami benar-benar kuasa untuk memperlihatkan kepadamu apa yang Kami ancamkan kepada mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 96, "text": "ٱدۡفَعۡ بِٱلَّتِی هِیَ أَحۡسَنُ ٱلسَّیِّئَةَۚ نَحۡنُ أَعۡلَمُ بِمَا یَصِفُونَ ۝٩٦", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "إذا أساء إليك أعداؤك - أيها الرسول - بالقول أو الفعل فلا تقابلهم بالإساءة، ولكن ادفع إساءتهم بالإحسان منك إليهم، نحن أعلم بما يصفه هؤلاء المشركون من الشرك والتكذيب، وسنجازيهم عليه أسوأ الجزاء.", "isBasmala": false, "translation_en": "Repel evil by what is better. We are aware of what they describe.", "translation_id": "Tolaklah perbuatan buruk mereka dengan yang lebih baik. Kami lebih mengetahui apa yang mereka sifatkan.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 97, "text": "وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَ ٰتِ ٱلشَّیَـٰطِینِ ۝٩٧", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "وقل - أيها النبي -: رب أستجير بك من إغواء الشياطين ووسوستها، المغرية على الباطل والفساد والصد عن الحق، وأستجير بك- يا رب- مِن حضورهم في شيء من أموري.", "isBasmala": false, "translation_en": "And say, \"My Lord, I seek refuge with You from the urgings of the devils.", "translation_id": "Dan katakanlah: \"Ya Tuhanku aku berlindung kepada Engkau dari bisikan-bisikan syaitan.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 98, "text": "وَأَعُوذُ بِكَ رَبِّ أَن یَحۡضُرُونِ ۝٩٨", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "وقل - أيها النبي -: رب أستجير بك من إغواء الشياطين ووسوستها، المغرية على الباطل والفساد والصد عن الحق، وأستجير بك- يا رب- مِن حضورهم في شيء من أموري.", "isBasmala": false, "translation_en": "And I seek refuge with You, my Lord, lest they become present.\"", "translation_id": "Dan aku berlindung (pula) kepada Engkau ya Tuhanku, dari kedatangan mereka kepadaku\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 99, "text": "حَتَّىٰۤ إِذَا جَاۤءَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ رَبِّ ٱرۡجِعُونِ ۝٩٩", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "يخبر الله تعالى عن حال المحتضر من الكافرين أو المفرطين في أمره تعالى، حتى إذا أشرف على الموت، وشاهد ما أُعِدَّ له من العذاب قال: رب ردُّوني إلى الدنيا.", "isBasmala": false, "translation_en": "Until, when death comes to one of them, he says, \"My Lord, send me back.", "translation_id": "(Demikianlah keadaan orang-orang kafir itu), hingga apabila datang kematian kepada seseorang dari mereka, dia berkata: \"Ya Tuhanku kembalikanlah aku (ke dunia),", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 100, "text": "لَعَلِّیۤ أَعۡمَلُ صَـٰلِحࣰا فِیمَا تَرَكۡتُۚ كَلَّاۤۚ إِنَّهَا كَلِمَةٌ هُوَ قَاۤىِٕلُهَاۖ وَمِن وَرَاۤىِٕهِم بَرۡزَخٌ إِلَىٰ یَوۡمِ یُبۡعَثُونَ ۝١٠٠", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "لعلي أستدرك ما ضيَّعْتُ من الإيمان والطاعة. ليس له ذلك، فلا يجاب إلى ما طلب ولا يُمْهَل. فإنما هي كلمة هو قائلها قولا لا ينفعه، وهو فيه غير صادق، فلو رُدَّ إلى الدنيا لعاد إلى ما نُهي عنه، وسيبقى المتوفَّون في الحاجز والبَرْزخ الذي بين الدنيا والآخرة إلى يوم البعث والنشور.", "isBasmala": false, "translation_en": "That I may do right in what I have neglected.\" By no means! It is just a word that he utters. And behind them is a barrier, until the Day they are resurrected.", "translation_id": "agar aku berbuat amal yang saleh terhadap yang telah aku tinggalkan. Sekali-kali tidak. Sesungguhnya itu adalah perkataan yang diucapkannya saja. Dan di hadapan mereka ada dinding sampal hari mereka dibangkitkan.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 101, "text": "فَإِذَا نُفِخَ فِی ٱلصُّورِ فَلَاۤ أَنسَابَ بَیۡنَهُمۡ یَوۡمَىِٕذࣲ وَلَا یَتَسَاۤءَلُونَ ۝١٠١", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "فإذا كان يوم القيامة، ونفخ المَلَك المكلَّف في \"القرن\"، وبُعِثَ الناس من قبورهم، فلا تَفاخُرَ بالأنساب حينئذ كما كانوا يفتخرون بها في الدنيا، ولا يسأل أحد أحدًا.", "isBasmala": false, "translation_en": "When the Horn is blown, no relations between them will exist on that Day, and they will not ask after one another.", "translation_id": "Apabila sangkakala ditiup maka tidaklah ada lagi pertalian nasab di antara mereka pada hari itu, dan tidak ada pula mereka saling bertanya.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 102, "text": "فَمَن ثَقُلَتۡ مَوَ ٰزِینُهُۥ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝١٠٢", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "فمن كثرت حسناته وثَقُلَتْ بها موازين أعماله عند الحساب، فأولئك هم الفائزون بالجنة.", "isBasmala": false, "translation_en": "Those whose scales are heavy-those are the successful.", "translation_id": "Barangsiapa yang berat timbangan (kebaikan)nya, maka mereka itulah orang-orang yang dapat keberuntungan.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 103, "text": "وَمَنۡ خَفَّتۡ مَوَ ٰزِینُهُۥ فَأُو۟لَـٰۤىِٕكَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ فِی جَهَنَّمَ خَـٰلِدُونَ ۝١٠٣", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "ومن قَلَّتْ حسناته في الميزان، ورجحت سيئاته، وأعظمها الشرك، فأولئك هم الذين خابوا وخسروا أنفسهم، في نار جهنم خالدون.", "isBasmala": false, "translation_en": "But those whose scales are light-those are they who have lost their souls; in Hell they will dwell forever.", "translation_id": "Dan barangsiapa yang ringan timbangannya, maka mereka itulah orang-orang yang merugikan dirinya sendiri, mereka kekal di dalam neraka Jahannam.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 104, "text": "تَلۡفَحُ وُجُوهَهُمُ ٱلنَّارُ وَهُمۡ فِیهَا كَـٰلِحُونَ ۝١٠٤", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "تَحْرقُ النار وجوههم، وهم فيها عابسون تَقَلَّصَتْ شفاههم، وبرزت أسنانهم.", "isBasmala": false, "translation_en": "The Fire lashes their faces, and therein they grimace.", "translation_id": "Muka mereka dibakar api neraka, dan mereka di dalam neraka itu dalam keadaan cacat.", "manzil": 4, "manzil_display": ""}], "349": [{"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 105, "text": "أَلَمۡ تَكُنۡ ءَایَـٰتِی تُتۡلَىٰ عَلَیۡكُمۡ فَكُنتُم بِهَا تُكَذِّبُونَ ۝١٠٥", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "يقال لهم: ألم تكن آيات القرآن تتلى عليكم في الدنيا، فكنتم بها تكذبون؟", "isBasmala": false, "translation_en": "\"Were not My revelations recited to you, and you kept on rejecting them?\"", "translation_id": "Bukankah ayat-ayat-Ku telah dibacakan kepadamu sekalian, tetapi kamu selalu mendustakannya?", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 106, "text": "قَالُوا۟ رَبَّنَا غَلَبَتۡ عَلَیۡنَا شِقۡوَتُنَا وَكُنَّا قَوۡمࣰا ضَاۤلِّینَ ۝١٠٦", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "لما بلَّغتهم رسلهم وأنذرتهم قالوا يوم القيامة: ربنا غلبت علينا لذاتنا وأهواؤنا المقدَّرة علينا في سابق علمك، وكنا في فعلنا ضالين عن الهدى.", "isBasmala": false, "translation_en": "They will say, \"Our Lord, our wretchedness prevailed over us, and we were a people astray.", "translation_id": "Mereka berkata: \"Ya Tuhan kami, kami telah dikuasai oleh kejahatan kami, dan adalah kami orang-orang yang sesat.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 107, "text": "رَبَّنَاۤ أَخۡرِجۡنَا مِنۡهَا فَإِنۡ عُدۡنَا فَإِنَّا ظَـٰلِمُونَ ۝١٠٧", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "ربنا أخرجنا من النار، وأعدنا إلى الدنيا، فإن رجعنا إلى الضلال فإنا ظالمون نستحق العقوبة.", "isBasmala": false, "translation_en": "Our Lord! Bring us out of this. If we ever returned, we would truly be evil.\"", "translation_id": "Ya Tuhan kami, keluarkanlah kami daripadanya (dan kembalikanlah kami ke dunia), maka jika kami kembali (juga kepada kekafiran), sesungguhnya kami adalah orang-orang yang zalim\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 108, "text": "قَالَ ٱخۡسَـُٔوا۟ فِیهَا وَلَا تُكَلِّمُونِ ۝١٠٨", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "قال الله عز وجل لهم: امكثوا في النار أذلاء ولا تخاطبوني. فانقطع عند ذلك دعاؤهم ورجاؤهم.", "isBasmala": false, "translation_en": "He will say, \"Be despised therein, and do not speak to Me.", "translation_id": "Allah berfirman: \"Tinggallah dengan hina di dalamnya, dan janganlah kamu berbicara dengan Aku.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 109, "text": "إِنَّهُۥ كَانَ فَرِیقࣱ مِّنۡ عِبَادِی یَقُولُونَ رَبَّنَاۤ ءَامَنَّا فَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَا وَأَنتَ خَیۡرُ ٱلرَّ ٰحِمِینَ ۝١٠٩", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "إنه كان فريق من عبادي- وهم المؤمنون- يَدْعون: ربنا آمنا فاستر ذنوبنا، وارحمنا، وأنت خير الراحمين.", "isBasmala": false, "translation_en": "There was a group of My servants who would say, `Our Lord, we have believed, so forgive us, and have mercy on us; You are the Best of the merciful.'", "translation_id": "Sesungguhnya, ada segolongan dari hamba-hamba-Ku berdoa (di dunia): \"Ya Tuhan kami, kami telah beriman, maka ampunilah kami dan berilah kami rahmat dan Engkau adalah Pemberi rahmat Yang Paling Baik.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 110, "text": "فَٱتَّخَذۡتُمُوهُمۡ سِخۡرِیًّا حَتَّىٰۤ أَنسَوۡكُمۡ ذِكۡرِی وَكُنتُم مِّنۡهُمۡ تَضۡحَكُونَ ۝١١٠", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "فاشتغلتم بالاستهزاء بهم حتى نسيتم ذكر الله، فبقيتم على تكذيبكم، وقد كنتم تضحكون منهم سخرية واستهزاء.", "isBasmala": false, "translation_en": "But you made then a target of ridicule, until they made you forget My remembrance; and you used to laugh at them.", "translation_id": "Lalu kamu menjadikan mereka buah ejekan, sehingga (kesibukan) kamu mengejek mereka, menjadikan kamu lupa mengingat Aku, dan adalah kamu selalu mentertawakan mereka,", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 111, "text": "إِنِّی جَزَیۡتُهُمُ ٱلۡیَوۡمَ بِمَا صَبَرُوۤا۟ أَنَّهُمۡ هُمُ ٱلۡفَاۤىِٕزُونَ ۝١١١", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "إني جزيت هذا الفريق من عبادي المؤمنين الفوز بالجنة؛ بسبب صبرهم على الأذى وطاعة الله.", "isBasmala": false, "translation_en": "Today, I have rewarded them for their endurance. They are the ones who are the triumphant.\"", "translation_id": "Sesungguhnya Aku memberi balasan kepada mereka di hari ini, karena kesabaran mereka; sesungguhnya mereka itulah orang-orang yang menang\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 112, "text": "قَـٰلَ كَمۡ لَبِثۡتُمۡ فِی ٱلۡأَرۡضِ عَدَدَ سِنِینَ ۝١١٢", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "ويُسْألُ الأشقياء في النار: كم بقيتم في الدنيا من السنين؟ وكم ضيَّعتم فيها من طاعة الله؟", "isBasmala": false, "translation_en": "He will say, \"How many years did you remain on earth?\"", "translation_id": "Allah bertanya: \"Berapa tahunkah lamanya kamu tinggal di bumi?\"", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 113, "text": "قَالُوا۟ لَبِثۡنَا یَوۡمًا أَوۡ بَعۡضَ یَوۡمࣲ فَسۡـَٔلِ ٱلۡعَاۤدِّینَ ۝١١٣", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "قالوا لِهول الموقف وشدة العذاب: بقينا فيها يومًا أو بعض يوم، فاسأل الحُسَّاب الذين يعدُّون الشهور والأيام.", "isBasmala": false, "translation_en": "They will say, \"We remained a day, or part of a day; but ask those who keep count.\"", "translation_id": "Mereka menjawab: \"Kami tinggal (di bumi) sehari atau setengah hari, maka tanyakanlah kepada orang-orang yang menghitung\".", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 114, "text": "قَـٰلَ إِن لَّبِثۡتُمۡ إِلَّا قَلِیلࣰاۖ لَّوۡ أَنَّكُمۡ كُنتُمۡ تَعۡلَمُونَ ۝١١٤", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "قال لهم: ما لبثتم إلا وقتًا قليلا لو صبرتم فيه على طاعة الله لفزتم بالجنة، لو كان عندكم علم بذلك؛ وذلك لأن مدة مكثهم في الدنيا قليلة جدا بالنسبة إلى طول مدتهم خالدين في النار.", "isBasmala": false, "translation_en": "He will say, \"You remained only for a little while, if you only knew.", "translation_id": "Allah berfirman: \"Kamu tidak tinggal (di bumi) melainkan sebentar saja, kalau kamu sesungguhnya mengetahui\"", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 115, "text": "أَفَحَسِبۡتُمۡ أَنَّمَا خَلَقۡنَـٰكُمۡ عَبَثࣰا وَأَنَّكُمۡ إِلَیۡنَا لَا تُرۡجَعُونَ ۝١١٥", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "أفحسبتم- أيها الخلق- أنما خلقناكم مهملين، لا أمر ولا نهي ولا ثواب ولا عقاب، وأنكم إلينا لا ترجعون في الآخرة للحساب والجزاء؟", "isBasmala": false, "translation_en": "Did you think that We created you in vain, and that to Us you will not be returned?\"", "translation_id": "Maka apakah kamu mengira, bahwa sesungguhnya Kami menciptakan kamu secara main-main (saja), dan bahwa kamu tidak akan dikembalikan kepada Kami?", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 116, "text": "فَتَعَـٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۖ لَاۤ إِلَـٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡكَرِیمِ ۝١١٦", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "فتعالى الله الملك المتصرف في كل شيء، الذي هو حق، ووعده حق، ووعيده حق، وكل شيء منه حق، وتَقَدَّس عن أن يخلق شيئًا عبثًا أو سفهًا، لا إله غيره ربُّ العرشِ الكريمِ، الذي هو أعظم المخلوقات.", "isBasmala": false, "translation_en": "So Exalted is God, the Ruler, the Real. There is no god except He, the Lord of the Noble Throne.", "translation_id": "Maka Maha Tinggi Allah, Raja Yang Sebenarnya; tidak ada Tuhan selain Dia, Tuhan (Yang mempunyai) 'Arsy yang mulia.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 117, "text": "وَمَن یَدۡعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ لَا بُرۡهَـٰنَ لَهُۥ بِهِۦ فَإِنَّمَا حِسَابُهُۥ عِندَ رَبِّهِۦۤۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلۡكَـٰفِرُونَ ۝١١٧", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "ومن يعبد مع الله الواحد إلهًا آخر، لا حجة له على استحقاقه العبادة، فإنما جزاؤه على عمله السيِّئ عند ربه في الآخرة. إنه لا فلاح ولا نجاة للكافرين يوم القيامة.", "isBasmala": false, "translation_en": "Whoever invokes another god besides God-he has no proof thereof-his reckoning rests with his Lord. The disbelievers will not succeed.", "translation_id": "Dan barangsiapa menyembah tuhan yang lain di samping Allah, padahal tidak ada suatu dalilpun baginya tentang itu, maka sesungguhnya perhitungannya di sisi Tuhannya. Sesungguhnya orang-orang yang kafir itu tiada beruntung.", "manzil": 4, "manzil_display": ""}, {"sura": 23, "sura_name": "المؤمنون", "revelation": "Makkiyah", "aya": 118, "text": "وَقُل رَّبِّ ٱغۡفِرۡ وَٱرۡحَمۡ وَأَنتَ خَیۡرُ ٱلرَّ ٰحِمِینَ ۝١١٨", "juz": 18, "hizb": "(*½ ح 35*)", "tafsir": "وقل- أيها النبي-: ربِّ تجاوَزْ عن الذنوب وارحم؛ وأنت خير من رحم ذا ذنب، فقبل توبته ولم يعاقبه على ذنبه.", "isBasmala": false, "translation_en": "And say, \"My Lord, forgive and have mercy, for You are the Best of the merciful.\"", "translation_id": "Dan katakanlah: \"Ya Tuhanku berilah ampun dan berilah rahmat, dan Engkau adalah Pemberi rahmat Yang Paling baik\".", "manzil": 4, "manzil_display": ""}], "350": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 18, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 1, "text": "۞ سُورَةٌ أَنزَلۡنَـٰهَا وَفَرَضۡنَـٰهَا وَأَنزَلۡنَا فِیهَاۤ ءَایَـٰتِۭ بَیِّنَـٰتࣲ لَّعَلَّكُمۡ تَذَكَّرُونَ ۝١", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "هذه سورة عظيمة من القرآن أنزلناها، وأوجبنا العمل بأحكامها، وأنزلنا فيها دلالات واضحات؛ لتتذكروا- أيها المؤمنون- بهذه الآيات البينات، وتعملوا بها.", "isBasmala": false, "translation_en": "A chapter that We have revealed, and made obligatory, and revealed in it clear Verses, that you may take heed.", "translation_id": "(Ini adalah) satu surat yang Kami turunkan dan Kami wajibkan (menjalankan hukum-hukum yang ada di dalam)nya, dan Kami turunkan di dalamnya ayat ayat yang jelas, agar kamu selalu mengingatinya.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 2, "text": "ٱلزَّانِیَةُ وَٱلزَّانِی فَٱجۡلِدُوا۟ كُلَّ وَ ٰحِدࣲ مِّنۡهُمَا مِا۟ئَةَ جَلۡدَةࣲۖ وَلَا تَأۡخُذۡكُم بِهِمَا رَأۡفَةࣱ فِی دِینِ ٱللَّهِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۖ وَلۡیَشۡهَدۡ عَذَابَهُمَا طَاۤىِٕفَةࣱ مِّنَ ٱلۡمُؤۡمِنِینَ ۝٢", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "الزانية والزاني اللذان لم يسبق لهما الزواج، عقوبةُ كل منهما مائة جلدة بالسوط، وثبت في السنة مع هذا الجلد التغريب لمدة عام. ولا تحملكم الرأفة بهما على ترك العقوبة أو تخفيفها، إن كنتم مصدقين بالله واليوم الآخر عاملين بأحكام الإسلام، وليحضر العقوبةَ عدد من المؤمنين؛ تشنيعًا وزجرًا وعظة واعتبارًا.", "isBasmala": false, "translation_en": "The adulteress and the adulterer-whip each one of them a hundred lashes, and let no pity towards them overcome you regarding God's Law, if you believe in God and the Last Day. And let a group of believers witness their punishment.", "translation_id": "Perempuan yang berzina dan laki-laki yang berzina, maka deralah tiap-tiap seorang dari keduanya seratus dali dera, dan janganlah belas kasihan kepada keduanya mencegah kamu untuk (menjalankan) agama Allah, jika kamu beriman kepada Allah, dan hari akhirat, dan hendaklah (pelaksanaan) hukuman mereka disaksikan oleh sekumpulan orang-orang yang beriman.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 3, "text": "ٱلزَّانِی لَا یَنكِحُ إِلَّا زَانِیَةً أَوۡ مُشۡرِكَةࣰ وَٱلزَّانِیَةُ لَا یَنكِحُهَاۤ إِلَّا زَانٍ أَوۡ مُشۡرِكࣱۚ وَحُرِّمَ ذَ ٰلِكَ عَلَى ٱلۡمُؤۡمِنِینَ ۝٣", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "الزاني لا يرضى إلا بنكاح زانية أو مشركة لا تُقِرُّ بحرمة الزنى، والزانية لا ترضى إلا بنكاح زان أو مشرك لا يُقِرُّ بحرمة الزنى، أما العفيفون والعفيفات فإنهم لا يرضون بذلك، وحُرِّم ذلك النكاح على المؤمنين. وهذا دليل صريح على تحريم نكاح الزانية حتى تتوب، وكذلك تحريم إنكاح الزاني حتى يتوب.", "isBasmala": false, "translation_en": "The adulterer shall marry none but an adulteress or an idolatress; and the adulteress shall marry none but an adulterer or an idolater. That has been prohibited for the believers.", "translation_id": "Laki-laki yang berzina tidak mengawini melainkan perempuan yang berzina, atau perempuan yang musyrik; dan perempuan yang berzina tidak dikawini melainkan oleh laki-laki yang berzina atau laki-laki musyrik, dan yang demikian itu diharamkan atas oran-orang yang mukmin.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 4, "text": "وَٱلَّذِینَ یَرۡمُونَ ٱلۡمُحۡصَنَـٰتِ ثُمَّ لَمۡ یَأۡتُوا۟ بِأَرۡبَعَةِ شُهَدَاۤءَ فَٱجۡلِدُوهُمۡ ثَمَـٰنِینَ جَلۡدَةࣰ وَلَا تَقۡبَلُوا۟ لَهُمۡ شَهَـٰدَةً أَبَدࣰاۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ ۝٤", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "والذين يتهمون بالفاحشة أنفسًا عفيفة من النساء والرجال مِن دون أن يشهد معهم أربعة شهود عدول، فاجلدوهم بالسوط ثمانين جلدة، ولا تقبلوا لهم شهادة أبدًا، وأولئك هم الخارجون عن طاعة الله.", "isBasmala": false, "translation_en": "Those who accuse chaste women, then cannot bring four witnesses, whip them eighty lashes, and do not ever accept their testimony. For these are the immoral.", "translation_id": "Dan orang-orang yang menuduh wanita-wanita yang baik-baik (berbuat zina) dan mereka tidak mendatangkan empat orang saksi, maka deralah mereka (yang menuduh itu) delapan puluh kali dera, dan janganlah kamu terima kesaksian mereka buat selama-lamanya. Dan mereka itulah orang-orang yang fasik.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 5, "text": "إِلَّا ٱلَّذِینَ تَابُوا۟ مِنۢ بَعۡدِ ذَ ٰلِكَ وَأَصۡلَحُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝٥", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "لكن مَن تاب ونَدم ورجع عن اتهامه وأصلح عمله، فإن الله يغفر ذنبه ويرحمه، ويقبل توبته.", "isBasmala": false, "translation_en": "Except for those who repent afterwards, and reform; for God is Forgiving and Merciful.", "translation_id": "kecuali orang-orang yang bertaubat sesudah itu dan memperbaiki (dirinya), maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 6, "text": "وَٱلَّذِینَ یَرۡمُونَ أَزۡوَ ٰجَهُمۡ وَلَمۡ یَكُن لَّهُمۡ شُهَدَاۤءُ إِلَّاۤ أَنفُسُهُمۡ فَشَهَـٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَـٰدَ ٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّـٰدِقِینَ ۝٦", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "والذين يرمون زوجاتهم بالزنى، ولم يكن لهم شهداء على اتهامهم لهنَّ إلا أنفسهم، فعلى الواحد منهم أن يشهد أمام القاضي أربع مرات بقوله: أشهد بالله أني صادق فيما رميتها به من الزنى، ويزيد في الشهادة الخامسة الدعوة على نفسه باستحقاقه لعنة الله إن كان كاذبًا في قوله.", "isBasmala": false, "translation_en": "As for those who accuse their own spouses, but have no witnesses except themselves, the testimony of one of them is equivalent to four testimonies, if he swears by God that he is truthful.", "translation_id": "Dan orang-orang yang menuduh isterinya (berzina), padahal mereka tidak ada mempunyai saksi-saksi selain diri mereka sendiri, maka persaksian orang itu ialah empat kali bersumpah dengan nama Allah, sesungguhnya dia adalah termasuk orang-orang yang benar.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 7, "text": "وَٱلۡخَـٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَیۡهِ إِن كَانَ مِنَ ٱلۡكَـٰذِبِینَ ۝٧", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "والذين يرمون زوجاتهم بالزنى، ولم يكن لهم شهداء على اتهامهم لهنَّ إلا أنفسهم، فعلى الواحد منهم أن يشهد أمام القاضي أربع مرات بقوله: أشهد بالله أني صادق فيما رميتها به من الزنى، ويزيد في الشهادة الخامسة الدعوة على نفسه باستحقاقه لعنة الله إن كان كاذبًا في قوله.", "isBasmala": false, "translation_en": "And the fifth time, that God's curse be upon him, if he is a liar.", "translation_id": "Dan (sumpah) yang kelima: bahwa laknat Allah atasnya, jika dia termasuk orang-orang yang berdusta.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 8, "text": "وَیَدۡرَؤُا۟ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَـٰدَ ٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَـٰذِبِینَ ۝٨", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "وبشهادته تستوجب الزوجة عقوبة الزنى، وهي الرجم حتى الموت، ولا يدفع عنها هذه العقوبة إلا أن تشهد في مقابل شهادته أربع شهادات بالله إنه لكاذب في اتهامه لها بالزنى، وتزيد في الشهادة الخامسة الدعوة على نفسها باستحقاقها غضب الله، إن كان زوجها صادقًا فى اتهامه لها، وفي هذه الحال يفرق بينهما.", "isBasmala": false, "translation_en": "But punishment shall be averted from her, if she swears four times by God, that he is a liar.", "translation_id": "Istrinya itu dihindarkan dari hukuman oleh sumpahnya empat kali atas nama Allah sesungguhnya suaminya itu benar-benar termasuk orang-orang yang dusta.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 9, "text": "وَٱلۡخَـٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَیۡهَاۤ إِن كَانَ مِنَ ٱلصَّـٰدِقِینَ ۝٩", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "وبشهادته تستوجب الزوجة عقوبة الزنى، وهي الرجم حتى الموت، ولا يدفع عنها هذه العقوبة إلا أن تشهد في مقابل شهادته أربع شهادات بالله إنه لكاذب في اتهامه لها بالزنى، وتزيد في الشهادة الخامسة الدعوة على نفسها باستحقاقها غضب الله، إن كان زوجها صادقًا فى اتهامه لها، وفي هذه الحال يفرق بينهما.", "isBasmala": false, "translation_en": "And the fifth time, that God's wrath be upon her, if he is truthful.", "translation_id": "dan (sumpah) yang kelima: bahwa laknat Allah atasnya jika suaminya itu termasuk orang-orang yang benar.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 10, "text": "وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ تَوَّابٌ حَكِیمٌ ۝١٠", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "ولولا تفضُّل الله عليكم ورحمته- أيها المؤمنون- بهذا التشريع للأزواج والزوجات، لأحلَّ بالكاذب من المتلاعنين ما دعا به على نفسه، وأن الله تواب لمن تاب مِن عباده، حكيم في شرعه وتدبيره.", "isBasmala": false, "translation_en": "Were it not for God's grace upon you, and His mercy, and that God is Conciliatory and Wise.", "translation_id": "Dan andaikata tidak ada kurnia Allah dan rahmat-Nya atas dirimu dan (andaikata) Allah bukan Penerima Taubat lagi Maha Bijaksana, (niscaya kamu akan mengalami kesulitan-kesulitan).", "manzil": 4, "manzil_display": ""}], "351": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 11, "text": "إِنَّ ٱلَّذِینَ جَاۤءُو بِٱلۡإِفۡكِ عُصۡبَةࣱ مِّنكُمۡۚ لَا تَحۡسَبُوهُ شَرࣰّا لَّكُمۖ بَلۡ هُوَ خَیۡرࣱ لَّكُمۡۚ لِكُلِّ ٱمۡرِىࣲٕ مِّنۡهُم مَّا ٱكۡتَسَبَ مِنَ ٱلۡإِثۡمِۚ وَٱلَّذِی تَوَلَّىٰ كِبۡرَهُۥ مِنۡهُمۡ لَهُۥ عَذَابٌ عَظِیمࣱ ۝١١", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "إن الذين جاؤوا بأشنع الكذب، وهو اتهام أم المؤمنين عائشة رضي الله عنها بالفاحشة، جماعة منتسبون إليكم - معشر المسلمين- لا تحسبوا قولهم شرًّا لكم، بل هو خير لكم، لما تضمن ذلك مِن تبرئة أم المؤمنين ونزاهتها والتنويه بذكرها، ورفع الدرجات، وتكفير السيئات، وتمحيص المؤمنين. لكل فرد تكلم بالإفك جزاء فعله من الذنب، والذي تحمَّل معظمه، وهو عبد الله بن أُبيِّ ابن سلول كبير المنافقين- لعنه الله- له عذاب عظيم في الآخرة، وهو الخلود في الدرك الأسفل من النار.", "isBasmala": false, "translation_en": "Those who perpetrated the slander are a band of you. Do not consider it bad for you, but it is good for you. Each person among them bears his share in the sin. As for him who played the major role-for him is a terrible punishment.", "translation_id": "Sesungguhnya orang-orang yang membawa berita bohong itu adalah dari golongan kamu juga. Janganlah kamu kira bahwa berita bohong itu buruk bagi kamu bahkan ia adalah baik bagi kamu. Tiap-tiap seseorang dari mereka mendapat balasan dari dosa yang dikerjakannya. Dan siapa di antara mereka yang mengambil bahagian yang terbesar dalam penyiaran berita bohong itu baginya azab yang besar.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 12, "text": "لَّوۡلَاۤ إِذۡ سَمِعۡتُمُوهُ ظَنَّ ٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَـٰتُ بِأَنفُسِهِمۡ خَیۡرࣰا وَقَالُوا۟ هَـٰذَاۤ إِفۡكࣱ مُّبِینࣱ ۝١٢", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "هلا ظن المؤمنون والمؤمنات بعضهم ببعض خيرًا عند سماعهم ذلك الإفك، وهو السلامة مما رموا به، وقالوا: هذا كذب ظاهر على عائشة رضي الله عنها.", "isBasmala": false, "translation_en": "Why, when you heard about it, the believing men and women did not think well of one another, and say, \"This is an obvious lie\"?", "translation_id": "Mengapa di waktu kamu mendengar berita bohon itu orang-orang mukminin dan mukminat tidak bersangka baik terhadap diri mereka sendiri, dan (mengapa tidak) berkata: \"Ini adalah suatu berita bohong yang nyata\".", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 13, "text": "لَّوۡلَا جَاۤءُو عَلَیۡهِ بِأَرۡبَعَةِ شُهَدَاۤءَۚ فَإِذۡ لَمۡ یَأۡتُوا۟ بِٱلشُّهَدَاۤءِ فَأُو۟لَـٰۤىِٕكَ عِندَ ٱللَّهِ هُمُ ٱلۡكَـٰذِبُونَ ۝١٣", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "هلا أتى القاذفون بأربعة شهود عدول على قولهم، فحين لم يفعلوا ذلك فأولئك هم الكاذبون عند الله.", "isBasmala": false, "translation_en": "Why did they not bring four witnesses to testify to it? If they fail to bring the witnesses, then in God's sight, they are liars.", "translation_id": "Mengapa mereka (yang menuduh itu) tidak mendatangkan empat orang saksi atas berita bohong itu? Olah karena mereka tidak mendatangkan saksi-saksi maka mereka itulah pada sisi Allah orang-orang yang dusta.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 14, "text": "وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ لَمَسَّكُمۡ فِی مَاۤ أَفَضۡتُمۡ فِیهِ عَذَابٌ عَظِیمٌ ۝١٤", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "ولولا فَضْلُ الله عليكم ورحمته لكم بحيث شملكم إحسانه في دينكم ودنياكم فلم يعجِّل عقوبتكم، وتاب على مَن تاب منكم، لأصابكم بسبب ما خضتم فيه عذاب عظيم.", "isBasmala": false, "translation_en": "Were it not for God's favor upon you, and His mercy, in this world and the Hereafter, you would have suffered a great punishment for what you have ventured into.", "translation_id": "Sekiranya tidak ada kurnia Allah dan rahmat-Nya kepada kamu semua di dunia dan di akhirat, niscaya kamu ditimpa azab yang besar, karena pembicaraan kamu tentang berita bohong itu.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 15, "text": "إِذۡ تَلَقَّوۡنَهُۥ بِأَلۡسِنَتِكُمۡ وَتَقُولُونَ بِأَفۡوَاهِكُم مَّا لَیۡسَ لَكُم بِهِۦ عِلۡمࣱ وَتَحۡسَبُونَهُۥ هَیِّنࣰا وَهُوَ عِندَ ٱللَّهِ عَظِیمࣱ ۝١٥", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "حين تتلقفون الإفك وتتناقلونه بأفواهكم، وهو قول باطل، وليس عندكم به علم، وهما محظوران: التكلم بالباطل، والقول بلا علم، وتظنون ذلك شيئًا هيِّنًا، وهو عند الله عظيم. وفي هذا زجر بليغ عن التهاون في إشاعة الباطل.", "isBasmala": false, "translation_en": "When you rumored it with your tongues, and spoke with your mouths what you had no knowledge of, and you considered it trivial; but according to God, it is serious.", "translation_id": "(Ingatlah) di waktu kamu menerima berita bohong itu dari mulut ke mulut dan kamu katakan dengan mulutmu apa yang tidak kamu ketahui sedikit juga, dan kamu menganggapnya suatu yang ringan saja. Padahal dia pada sisi Allah adalah besar.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 16, "text": "وَلَوۡلَاۤ إِذۡ سَمِعۡتُمُوهُ قُلۡتُم مَّا یَكُونُ لَنَاۤ أَن نَّتَكَلَّمَ بِهَـٰذَا سُبۡحَـٰنَكَ هَـٰذَا بُهۡتَـٰنٌ عَظِیمࣱ ۝١٦", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "وهلا قلتم عند سماعكم إياه: ما يَحِلُّ لنا الكلام بهذا الكذب، تنزيهًا لك - يارب - مِن قول ذلك على زوجة رسولك محمد صلى الله عليه وسلم، فهو كذب عظيم في الوزر واستحقاق الذنب.", "isBasmala": false, "translation_en": "When you heard it, you should have said, \"It is not for us to repeat this. By Your glory, this is a serious slander.\"", "translation_id": "Dan mengapa kamu tidak berkata, diwaktu mendengar berita bohong itu: \"Sekali-kali tidaklah pantas bagi kita memperkatakan ini, Maha Suci Engkau (Ya Tuhan kami), ini adalah dusta yang besar\".", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 17, "text": "یَعِظُكُمُ ٱللَّهُ أَن تَعُودُوا۟ لِمِثۡلِهِۦۤ أَبَدًا إِن كُنتُم مُّؤۡمِنِینَ ۝١٧", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "يذكِّركم الله وينهاكم أن تعودوا أبدًا لمثل هذا الفعل من الاتهام الكاذب، إن كنتم مؤمنين به.", "isBasmala": false, "translation_en": "God cautions you never to return to the like of it, if you are believers.", "translation_id": "Allah memperingatkan kamu agar (jangan) kembali memperbuat yang seperti itu selama-lamanya, jika kamu orang-orang yang beriman.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 18, "text": "وَیُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِۚ وَٱللَّهُ عَلِیمٌ حَكِیمٌ ۝١٨", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "ويبين الله لكم الآيات المشتملة على الأحكام الشرعية والمواعظ، والله عليم بأفعالكم، حكيم في شرعه وتدبيره.", "isBasmala": false, "translation_en": "God explains the Verses to you. God is Knowing and Wise.", "translation_id": "dan Allah menerangkan ayat-ayat-Nya kepada kamu. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 19, "text": "إِنَّ ٱلَّذِینَ یُحِبُّونَ أَن تَشِیعَ ٱلۡفَـٰحِشَةُ فِی ٱلَّذِینَ ءَامَنُوا۟ لَهُمۡ عَذَابٌ أَلِیمࣱ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِۚ وَٱللَّهُ یَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ ۝١٩", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "إن الذين يحبون شيوع الفاحشة في المسلمين من قَذْف بالزنى أو أي قول سيِّئ لهم عذاب أليم في الدنيا بإقامة الحد عليهم، وغيره من البلايا الدنيوية، ولهم في الآخرة عذاب النار إن لم يتوبوا، والله- وحده- يعلم كذبهم، ويعلم مصالح عباده، وعواقب الأمور، وأنتم لا تعلمون ذلك.", "isBasmala": false, "translation_en": "Those who love to see immorality spread among the believers-for them is a painful punishment, in this life and in the Hereafter. God knows, and you do not know.", "translation_id": "Sesungguhnya orang-orang yang ingin agar (berita) perbuatan yang amat keji itu tersiar di kalangan orang-orang yang beriman, bagi mereka azab yang pedih di dunia dan di akhirat. Dan Allah mengetahui, sedang, kamu tidak mengetahui.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 20, "text": "وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ وَأَنَّ ٱللَّهَ رَءُوفࣱ رَّحِیمࣱ ۝٢٠", "juz": 18, "hizb": "(*¾ ح 35*)", "tafsir": "ولولا فَضْلُ الله على مَن وقع في حديث الإفك ورحمته بهم، وأن الله يرحم عباده المؤمنين رحمة واسعة في عاجلهم وآجلهم، لما بيَّن هذه الأحكام والمواعظ، ولَعاجل مَن خالف أمره بالعقوبة.", "isBasmala": false, "translation_en": "Were it not for God's grace upon you, and His mercy, and that God is Clement and Merciful.", "translation_id": "Dan sekiranya tidaklah karena kurnia Allah dan rahmat-Nya kepada kamu semua, dan Allah Maha Penyantun dan Maha Penyayang, (niscaya kamu akan ditimpa azab yang besar).", "manzil": 4, "manzil_display": ""}], "352": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 21, "text": "۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّبِعُوا۟ خُطُوَ ٰتِ ٱلشَّیۡطَـٰنِۚ وَمَن یَتَّبِعۡ خُطُوَ ٰتِ ٱلشَّیۡطَـٰنِ فَإِنَّهُۥ یَأۡمُرُ بِٱلۡفَحۡشَاۤءِ وَٱلۡمُنكَرِۚ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَیۡكُمۡ وَرَحۡمَتُهُۥ مَا زَكَىٰ مِنكُم مِّنۡ أَحَدٍ أَبَدࣰا وَلَـٰكِنَّ ٱللَّهَ یُزَكِّی مَن یَشَاۤءُۗ وَٱللَّهُ سَمِیعٌ عَلِیمࣱ ۝٢١", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تسلكوا طرق الشيطان، ومَن يسلك طرق الشيطان فإنه يأمره بقبيح الأفعال ومنكراتها، ولولا فَضْلُ الله على المؤمنين ورحمته بهم ما طَهُرَ منهم أحد أبدًا مِن دنس ذنبه، ولكن الله- بفضله- يطهر من يشاء. والله سميع لأقوالكم، عليم بنياتكم وأفعالكم.", "isBasmala": false, "translation_en": "O you who believe! Do not follow Satan's footsteps. Whoever follows Satan's footsteps-he advocates obscenity and immorality. Were it not for God's grace towards you, and His mercy, not one of you would have been pure, ever. But God purifies whomever He wills. God is All-Hearing, All-Knowing.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu mengikuti langkah-langkah syaitan. Barangsiapa yang mengikuti langkah-langkah syaitan, maka sesungguhnya syaitan itu menyuruh mengerjakan perbuatan yang keji dan yang mungkar. Sekiranya tidaklah karena kurnia Allah dan rahmat-Nya kepada kamu sekalian, niscaya tidak seorangpun dari kamu bersih (dari perbuatan-perbuatan keji dan mungkar itu) selama-lamanya, tetapi Allah membersihkan siapa yang dikehendaki-Nya. Dan Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 22, "text": "وَلَا یَأۡتَلِ أُو۟لُوا۟ ٱلۡفَضۡلِ مِنكُمۡ وَٱلسَّعَةِ أَن یُؤۡتُوۤا۟ أُو۟لِی ٱلۡقُرۡبَىٰ وَٱلۡمَسَـٰكِینَ وَٱلۡمُهَـٰجِرِینَ فِی سَبِیلِ ٱللَّهِۖ وَلۡیَعۡفُوا۟ وَلۡیَصۡفَحُوۤا۟ۗ أَلَا تُحِبُّونَ أَن یَغۡفِرَ ٱللَّهُ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمٌ ۝٢٢", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "ولا يحلف أهل الفضل في الدين والسَّعَة في المال على ترك صلة أقربائهم الفقراء والمحتاجين والمهاجرين، ومنعهم النفقة؛ بسبب ذنب فعلوه، ولْيتجاوزوا عن إساءتهم، ولا يعاقبوهم. ألا تحبون أن يتجاوز الله عنكم؟ فتجاوزوا عنهم. والله غفور لعباده، رحيم بهم. وفي هذا الحثُّ على العفو والصفح، ولو قوبل بالإساءة.", "isBasmala": false, "translation_en": "Those of you who have affluence and means should not refuse to give to the relatives, and the needy, and the emigrants for the sake of God. And let them pardon, and let them overlook. Do you not love for God to pardon you? God is All-Forgiving, Most Merciful.", "translation_id": "Dan janganlah orang-orang yang mempunyai kelebihan dan kelapangan di antara kamu bersumpah bahwa mereka (tidak) akan memberi (bantuan) kepada kaum kerabat(nya), orang-orang yang miskin dan orang-orang yang berhijrah pada jalan Allah, dan hendaklah mereka memaafkan dan berlapang dada. Apakah kamu tidak ingin bahwa Allah mengampunimu? Dan Allah adalah Maha Pengampun lagi Maha Penyayang,", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 23, "text": "إِنَّ ٱلَّذِینَ یَرۡمُونَ ٱلۡمُحۡصَنَـٰتِ ٱلۡغَـٰفِلَـٰتِ ٱلۡمُؤۡمِنَـٰتِ لُعِنُوا۟ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَلَهُمۡ عَذَابٌ عَظِیمࣱ ۝٢٣", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "إن الذين يقذفون بالزنى العفيفات الغافلات المؤمنات اللاتي لم يخطر ذلك بقلوبهن، مطرودون من رحمة الله في الدنيا والآخرة، ولهم عذاب عظيم في نار جهنم. وفي هذه الآية دليل على كفر من سبَّ، أو اتهم زوجة من زوجات النبي صلى الله عليه وسلم بسوء.", "isBasmala": false, "translation_en": "Those who slander honorable, innocent, believing women are cursed in this life and in the Hereafter. They will have a terrible punishment.", "translation_id": "Sesungguhnya orang-orang yang menuduh wanita yang baik-baik, yang lengah lagi beriman (berbuat zina), mereka kena laknat di dunia dan akhirat, dan bagi mereka azab yang besar,", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 24, "text": "یَوۡمَ تَشۡهَدُ عَلَیۡهِمۡ أَلۡسِنَتُهُمۡ وَأَیۡدِیهِمۡ وَأَرۡجُلُهُم بِمَا كَانُوا۟ یَعۡمَلُونَ ۝٢٤", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "ذلك العذاب يوم القيامة يوم تشهد عليهم ألسنتهم بما نطقت، وتتكلم أيديهم وأرجلهم بما عملت.", "isBasmala": false, "translation_en": "On the Day when their tongues, and their hands, and their feet will testify against them regarding what they used to do.", "translation_id": "pada hari (ketika), lidah, tangan dan kaki mereka menjadi saksi atas mereka terhadap apa yang dahulu mereka kerjakan.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 25, "text": "یَوۡمَىِٕذࣲ یُوَفِّیهِمُ ٱللَّهُ دِینَهُمُ ٱلۡحَقَّ وَیَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِینُ ۝٢٥", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "في هذا اليوم يوفيهم الله جزاءهم كاملا على أعمالهم بالعدل، ويعلمون في ذلك الموقف العظيم أن الله هو الحق المبين الذي هو حق، ووعده حق، ووعيده حق، وكل شيء منه حق، الذي لا يظلم أحدًا مثقال ذرة.", "isBasmala": false, "translation_en": "On that Day, God will pay them their account in full, and they will know that God is the Evident Reality.", "translation_id": "Di hari itu, Allah akan memberi mereka balasan yag setimpal menurut semestinya, dan tahulah mereka bahwa Allah-lah yang Benar, lagi Yang menjelaskan (segala sesutatu menurut hakikat yang sebenarnya).", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 26, "text": "ٱلۡخَبِیثَـٰتُ لِلۡخَبِیثِینَ وَٱلۡخَبِیثُونَ لِلۡخَبِیثَـٰتِۖ وَٱلطَّیِّبَـٰتُ لِلطَّیِّبِینَ وَٱلطَّیِّبُونَ لِلطَّیِّبَـٰتِۚ أُو۟لَـٰۤىِٕكَ مُبَرَّءُونَ مِمَّا یَقُولُونَۖ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ ۝٢٦", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "كل خبيث من الرجال والنساء والأقوال والأفعال مناسب للخبيث وموافق له، وكل طيِّب من الرجال والنساء والأقوال والأفعال مناسب للطيب وموافق له، والطيبون والطيبات مبرؤون مما يرميهم به الخبيثون من السوء، لهم من الله مغفرة تستغرق الذنوب، ورزق كريم في الجنة.", "isBasmala": false, "translation_en": "Bad women are for bad men, and bad men are for bad women, and good women are for good men, and good men are for good women. Those are acquitted of what they say. There is forgiveness for them, and a generous provision.", "translation_id": "Wanita-wanita yang keji adalah untuk laki-laki yang keji, dan laki-laki yang keji adalah buat wanita-wanita yang keji (pula), dan wanita-wanita yang baik adalah untuk laki-laki yang baik dan laki-laki yang baik adalah untuk wanita-wanita yang baik (pula). Mereka (yang dituduh) itu bersih dari apa yang dituduhkan oleh mereka (yang menuduh itu). Bagi mereka ampunan dan rezeki yang mulia (surga).", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 27, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَدۡخُلُوا۟ بُیُوتًا غَیۡرَ بُیُوتِكُمۡ حَتَّىٰ تَسۡتَأۡنِسُوا۟ وَتُسَلِّمُوا۟ عَلَىٰۤ أَهۡلِهَاۚ ذَ ٰلِكُمۡ خَیۡرࣱ لَّكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ ۝٢٧", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تدخلوا بيوتًا غير بيوتكم حتى تستأذنوا أهلها في الدخول وتسلموا عليهم وصيغة ذلك من السنة: السلام عليكم أأدخل؟ ذلكم الاستئذان خير لكم؛ لعلكم تتذكرون- بفعلكم له- أوامر الله، فتطيعوه.", "isBasmala": false, "translation_en": "O you who believe! Do not enter homes other than your own, until you have asked permission and greeted their occupants. That is better for you, that you may be aware.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu memasuki rumah yang bukan rumahmu sebelum meminta izin dan memberi salam kepada penghuninya. Yang demikian itu lebih baik bagimu, agar kamu (selalu) ingat.", "manzil": 4, "manzil_display": ""}], "353": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 28, "text": "فَإِن لَّمۡ تَجِدُوا۟ فِیهَاۤ أَحَدࣰا فَلَا تَدۡخُلُوهَا حَتَّىٰ یُؤۡذَنَ لَكُمۡۖ وَإِن قِیلَ لَكُمُ ٱرۡجِعُوا۟ فَٱرۡجِعُوا۟ۖ هُوَ أَزۡكَىٰ لَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ عَلِیمࣱ ۝٢٨", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "فإن لم تجدوا في بيوت الآخرين أحدًا فلا تدخلوها حتى يوجد مَن يأذن لكم، فإن لم يأذن، بل قال لكم: ارجعوا فارجعوا، ولا تُلحُّوا، فإن الرجوع عندئذ أطهر لكم؛ لأن للإنسان أحوالا يكره اطلاع أحد عليها. والله بما تعملون عليم، فيجازي كل عامل بعمله.", "isBasmala": false, "translation_en": "And if you find no one in them, do not enter them until you are given permission. And if it is said to you, \"Turn back,\" then turn back. That is more proper for you. God is aware of what you do.", "translation_id": "Jika kamu tidak menemui seorangpun didalamnya, maka janganlah kamu masuk sebelum kamu mendapat izin. Dan jika dikatakan kepadamu: \"Kembali (saja)lah, maka hendaklah kamu kembali. Itu bersih bagimu dan Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 29, "text": "لَّیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَن تَدۡخُلُوا۟ بُیُوتًا غَیۡرَ مَسۡكُونَةࣲ فِیهَا مَتَـٰعࣱ لَّكُمۡۚ وَٱللَّهُ یَعۡلَمُ مَا تُبۡدُونَ وَمَا تَكۡتُمُونَ ۝٢٩", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "لكن لا حرج عليكم أن تدخلوا بغير استئذان بيوتًا ليست مخصصة لسكنى أناس بذاتهم، بل ليتمتع بها مَن يحتاج إليها كالبيوت المُعَدَّة صدقة لابن السبيل في طرق المسافرين وغيرها من المرافق، ففيها منافع وحاجة لمن يدخلها، وفي الاستئذان مشقة. والله يعلم أحوالكم الظاهرة والخفية.", "isBasmala": false, "translation_en": "There is no blame on you for entering uninhabited houses, in which are belongings of yours. God knows what you reveal and what you conceal.", "translation_id": "Tidak ada dosa atasmu memasuki rumah yang tidak disediakan untuk didiami, yang di dalamnya ada keperluanmu, dan Allah mengetahui apa yang kamu nyatakan dan apa yang kamu sembunyikan.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 30, "text": "قُل لِّلۡمُؤۡمِنِینَ یَغُضُّوا۟ مِنۡ أَبۡصَـٰرِهِمۡ وَیَحۡفَظُوا۟ فُرُوجَهُمۡۚ ذَ ٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِیرُۢ بِمَا یَصۡنَعُونَ ۝٣٠", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "قل - أيها النبي - للمؤمنين يَغُضُّوا مِن أبصارهم عمَّا لا يحلُّ لهم من النساء والعورات، ويحفظوا فروجهم عمَّا حَرَّم الله من الزنى واللواط، وكشف العورات، ونحو ذلك، ذلك أطهر لهم. إن الله خبير بما يصنعون فيما يأمرهم به وينهاهم عنه.", "isBasmala": false, "translation_en": "Tell the believing men to restrain their looks, and to guard their privates. That is purer for them. God is cognizant of what they do.", "translation_id": "Katakanlah kepada orang laki-laki yang beriman: \"Hendaklah mereka menahan pandanganya, dan memelihara kemaluannya; yang demikian itu adalah lebih suci bagi mereka, sesungguhnya Allah Maha Mengetahui apa yang mereka perbuat\".", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 31, "text": "وَقُل لِّلۡمُؤۡمِنَـٰتِ یَغۡضُضۡنَ مِنۡ أَبۡصَـٰرِهِنَّ وَیَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا یُبۡدِینَ زِینَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡیَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُیُوبِهِنَّۖ وَلَا یُبۡدِینَ زِینَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَاۤىِٕهِنَّ أَوۡ ءَابَاۤءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَاۤىِٕهِنَّ أَوۡ أَبۡنَاۤءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَ ٰنِهِنَّ أَوۡ بَنِیۤ إِخۡوَ ٰنِهِنَّ أَوۡ بَنِیۤ أَخَوَ ٰتِهِنَّ أَوۡ نِسَاۤىِٕهِنَّ أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُهُنَّ أَوِ ٱلتَّـٰبِعِینَ غَیۡرِ أُو۟لِی ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِینَ لَمۡ یَظۡهَرُوا۟ عَلَىٰ عَوۡرَ ٰتِ ٱلنِّسَاۤءِۖ وَلَا یَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِیُعۡلَمَ مَا یُخۡفِینَ مِن زِینَتِهِنَّۚ وَتُوبُوۤا۟ إِلَى ٱللَّهِ جَمِیعًا أَیُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ ۝٣١", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "وقل للمؤمنات يغضضن من أبصارهن عمَّا لا يحلُّ لهن من العورات، ويحفظن فروجهن عمَّا حَرَّم الله، ولا يُظهرن زينتهن للرجال، بل يجتهدن في إخفائها إلا الثياب الظاهرة التي جرت العادة بلُبْسها، إذا لم يكن في ذلك ما يدعو إلى الفتنة بها، وليلقين بأغطية رؤوسهن على فتحات صدورهن مغطيات وجوههن؛ ليكمل سترهن، ولا يُظْهِرْنَ الزينة الخفية إلا لأزواجهن؛ إذ يرون منهن ما لا يرى غيرهم. وبعضها، كالوجه، والعنق، واليدين، والساعدين يباح رؤيته لآبائهن أو آباء أزواجهن أو أبنائهن أو أبناء أزواجهن أو إخوانهن أو أبناء إخوانهن أو أبناء أخواتهن أو نسائهن المسلمات دون الكافرات، أو ما ملكن مِنَ العبيد، أو التابعين من الرجال الذين لا غرض ولا حاجة لهم في النساء، مثل البُلْه الذين يتبعون غيرهم للطعام والشراب فحسب، أو الأطفال الصغار الذين ليس لهم علم بأمور عورات النساء، ولم توجد فيهم الشهوة بعد، ولا يضرب النساء عند سَيْرهن بأرجلهن ليُسْمِعْن صوت ما خفي من زينتهن كالخلخال ونحوه، وارجعوا- أيها المؤمنون- إلى طاعة الله فيما أمركم به من هذه الصفات الجميلة والأخلاق الحميدة، واتركوا ما كان عليه أهل الجاهلية من الأخلاق والصفات الرذيلة؛ رجاء أن تفوزوا بخيري الدنيا والآخرة.", "isBasmala": false, "translation_en": "And tell the believing women to restrain their looks, and to guard their privates, and not display their beauty except what is apparent thereof, and to draw their coverings over their breasts, and not expose their beauty except to their husbands, their fathers, their husbands' fathers, their sons, their husbands' sons, their brothers, their brothers' sons, their sisters' sons, their women, what their right hands possess, their male attendants who have no sexual desires, or children who are not yet aware of the nakedness of women. And they should not strike their feet to draw attention to their hidden beauty. And repent to God, all of you believers, so that you may succeed.", "translation_id": "Katakanlah kepada wanita yang beriman: \"Hendaklah mereka menahan pandangannya, dan kemaluannya, dan janganlah mereka menampakkan perhiasannya, kecuali yang (biasa) nampak dari padanya. Dan hendaklah mereka menutupkan kain kudung kedadanya, dan janganlah menampakkan perhiasannya kecuali kepada suami mereka, atau ayah mereka, atau ayah suami mereka, atau putera-putera mereka, atau putera-putera suami mereka, atau saudara-saudara laki-laki mereka, atau putera-putera saudara lelaki mereka, atau putera-putera saudara perempuan mereka, atau wanita-wanita islam, atau budak-budak yang mereka miliki, atau pelayan-pelayan laki-laki yang tidak mempunyai keinginan (terhadap wanita) atau anak-anak yang belum mengerti tentang aurat wanita. Dan janganlah mereka memukulkan kakinyua agar diketahui perhiasan yang mereka sembunyikan. Dan bertaubatlah kamu sekalian kepada Allah, hai orang-orang yang beriman supaya kamu beruntung.", "manzil": 4, "manzil_display": ""}], "354": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 32, "text": "وَأَنكِحُوا۟ ٱلۡأَیَـٰمَىٰ مِنكُمۡ وَٱلصَّـٰلِحِینَ مِنۡ عِبَادِكُمۡ وَإِمَاۤىِٕكُمۡۚ إِن یَكُونُوا۟ فُقَرَاۤءَ یُغۡنِهِمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱللَّهُ وَ ٰسِعٌ عَلِیمࣱ ۝٣٢", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "وزوِّجوا- أيها المؤمنون- مَن لا زوج له من الأحرار والحرائر والصالحين مِن عبيدكم وجواريكم، إن يكن الراغب في الزواج للعفة فقيرًا يغنه الله من واسع رزقه. والله واسع كثير الخير عظيم الفضل، عليم بأحوال عباده.", "isBasmala": false, "translation_en": "And wed the singles among you, and those who are fit among your servants and maids. If they are poor, God will enrich them from His bounty. God is All-Encompassing, All-Knowing.", "translation_id": "Dan kawinkanlah orang-orang yang sedirian diantara kamu, dan orang-orang yang layak (berkawin) dari hamba-hamba sahayamu yang lelaki dan hamba-hamba sahayamu yang perempuan. Jika mereka miskin Allah akan memampukan mereka dengan kurnia-Nya. Dan Allah Maha luas (pemberian-Nya) lagi Maha Mengetahui.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 33, "text": "وَلۡیَسۡتَعۡفِفِ ٱلَّذِینَ لَا یَجِدُونَ نِكَاحًا حَتَّىٰ یُغۡنِیَهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَٱلَّذِینَ یَبۡتَغُونَ ٱلۡكِتَـٰبَ مِمَّا مَلَكَتۡ أَیۡمَـٰنُكُمۡ فَكَاتِبُوهُمۡ إِنۡ عَلِمۡتُمۡ فِیهِمۡ خَیۡرࣰاۖ وَءَاتُوهُم مِّن مَّالِ ٱللَّهِ ٱلَّذِیۤ ءَاتَىٰكُمۡۚ وَلَا تُكۡرِهُوا۟ فَتَیَـٰتِكُمۡ عَلَى ٱلۡبِغَاۤءِ إِنۡ أَرَدۡنَ تَحَصُّنࣰا لِّتَبۡتَغُوا۟ عَرَضَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَمَن یُكۡرِههُّنَّ فَإِنَّ ٱللَّهَ مِنۢ بَعۡدِ إِكۡرَ ٰهِهِنَّ غَفُورࣱ رَّحِیمࣱ ۝٣٣", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "والذين لا يستطيعون الزواج لفقرهم أو غيره فليطلبوا العفة عمَّا حَرَّمَ الله حتى يغنيهم الله من فضله، وييسر لهم الزواج. والذين يريدون أن يتحرروا من العبيد والإماء بمكاتبة أسيادهم على بعض المال يؤدونه إليهم، فعلى مالكيهم أن يكاتبوهم على ذلك إن علموا فيهم خيرًا: مِن رشد وقدرة على الكسب وصلاح في الدين، وعليهم أن يعطوهم شيئًا من المال أو أن يحطوا عنهم مما كُوتبوا عليه. ولا يجوز لكم إكراه جواريكم على الزنى طلبًا للمال، وكيف يقع منكم ذلك وهن يُرِدْن العفة وأنتم تأبونها؟ وفي هذا غاية التشنيع لفعلهم القبيح. ومن يكرههنَّ على الزنى فإن الله تعالى من بعد إكراههن غفور لهن رحيم بهن، والإثم على مَن أكْرههن.", "isBasmala": false, "translation_en": "And let those who do not find the means to marry abstain, until God enriches them from His bounty. If any of your servants wish to be freed, grant them their wish, if you recognize some good in them. And give them of God's wealth which he has given you. And do not compel your girls to prostitution, seeking the materials of this life, if they desire to remain chaste. Should anyone compel them-after their compulsion, God is Forgiving and Merciful.", "translation_id": "Dan orang-orang yang tidak mampu kawin hendaklah menjaga kesucian (diri)nya, sehingga Allah memampukan mereka dengan karunia-Nya. Dan budak-budak yang kamu miliki yang memginginkan perjanjian, hendaklah kamu buat perjanjian dengan mereka, jika kamu mengetahui ada kebaikan pada mereka, dan berikanlah kepada mereka sebahagian dari harta Allah yang dikaruniakan-Nya kepadamu. Dan janganlah kamu paksa budak-budak wanitamu untuk melakukan pelacuran, sedang mereka sendiri mengingini kesucian, karena kamu hendak mencari keuntungan duniawi. Dan barangsiapa yang memaksa mereka, maka sesungguhnya Allah adalah Maha Pengampun lagi Maha Penyayang (kepada mereka) sesudah mereka dipaksa itu.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 34, "text": "وَلَقَدۡ أَنزَلۡنَاۤ إِلَیۡكُمۡ ءَایَـٰتࣲ مُّبَیِّنَـٰتࣲ وَمَثَلࣰا مِّنَ ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلِكُمۡ وَمَوۡعِظَةࣰ لِّلۡمُتَّقِینَ ۝٣٤", "juz": 18, "hizb": "(* ح 36*)", "tafsir": "ولقد أنزلنا إليكم- أيها الناس- آيات القرآن دلالات واضحات على الحق، ومثلا من أخبار الأمم السابقة المؤمنين منهم والكافرين، وما جرى لهم وعليهم ما يكون مثلا وعبرة لكم، وموعظة يتعظ بها من يتقي الله ويَحْذَرُ عذابه.", "isBasmala": false, "translation_en": "We have sent down to you clarifying revelations, and examples of those who passed on before you, and advice for the righteous.", "translation_id": "Dan sesungguhnya Kami telah menurunkan kepada kamu ayat-ayat yang memberi penerangan, dan contoh-contoh dari orang-orang yang terdahulu sebelum kamu dan pelajaran bagi orang-orang yang bertakwa.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 35, "text": "۞ ٱللَّهُ نُورُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةࣲ فِیهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِی زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبࣱ دُرِّیࣱّ یُوقَدُ مِن شَجَرَةࣲ مُّبَـٰرَكَةࣲ زَیۡتُونَةࣲ لَّا شَرۡقِیَّةࣲ وَلَا غَرۡبِیَّةࣲ یَكَادُ زَیۡتُهَا یُضِیۤءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارࣱۚ نُّورٌ عَلَىٰ نُورࣲۚ یَهۡدِی ٱللَّهُ لِنُورِهِۦ مَن یَشَاۤءُۚ وَیَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَـٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ ۝٣٥", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "الله نور السموات والأرض يدبر الأمر فيهما ويهدي أهلهما، فهو- سبحانه- نور، وحجابه نور، به استنارت السموات والأرض وما فيهما، وكتاب الله وهدايته نور منه سبحانه، فلولا نوره تعالى لتراكمت الظلمات بعضها فوق بعض. مثل نوره الذي يهدي إليه، وهو الإيمان والقرآن في قلب المؤمن كمشكاة، وهي الكُوَّة في الحائط غير النافذة، فيها مصباح، حيث تجمع الكوَّة نور المصباح فلا يتفرق، وذلك المصباح في زجاجة، كأنها -لصفائها- كوكب مضيء كالدُّر، يوقَد المصباح من زيت شجرة مباركة، وهي شجرة الزيتون، لا شرقية فقط، فلا تصيبها الشمس آخر النهار، ولا غربية فقط فلا تصيبها الشمس أول النهار، بل هي متوسطة في مكان من الأرض لا إلى الشرق ولا إلى الغرب، يكاد زيتها -لصفائه- يضيء من نفسه قبل أن تمسه النار، فإذا مَسَّتْه النار أضاء إضاءة بليغة، نور على نور، فهو نور من إشراق الزيت على نور من إشعال النار، فذلك مثل الهدى يضيء في قلب المؤمن. والله يهدي ويوفق لاتباع القرآن مَن يشاء، ويضرب الأمثال للناس؛ ليعقلوا عنه أمثاله وحكمه. والله بكل شيء عليم، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "God is the Light of the heavens and the earth. The allegory of His light is that of a pillar on which is a lamp. The lamp is within a glass. The glass is like a brilliant planet, fueled by a blessed tree, an olive tree, neither eastern nor western. Its oil would almost illuminate, even if no fire has touched it. Light upon Light. God guides to His light whomever He wills. God thus cites the parables for the people. God is cognizant of everything.", "translation_id": "Allah (Pemberi) cahaya (kepada) langit dan bumi. Perumpamaan cahaya Allah, adalah seperti sebuah lubang yang tak tembus, yang di dalamnya ada pelita besar. Pelita itu di dalam kaca (dan) kaca itu seakan-akan bintang (yang bercahaya) seperti mutiara, yang dinyalakan dengan minyak dari pohon yang berkahnya, (yaitu) pohon zaitun yang tumbuh tidak di sebelah timur (sesuatu) dan tidak pula di sebelah barat(nya), yang minyaknya (saja) hampir-hampir menerangi, walaupun tidak disentuh api. Cahaya di atas cahaya (berlapis-lapis), Allah membimbing kepada cahaya-Nya siapa yang dia kehendaki, dan Allah memperbuat perumpamaan-perumpamaan bagi manusia, dan Allah Maha Mengetahui segala sesuatu.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 36, "text": "فِی بُیُوتٍ أَذِنَ ٱللَّهُ أَن تُرۡفَعَ وَیُذۡكَرَ فِیهَا ٱسۡمُهُۥ یُسَبِّحُ لَهُۥ فِیهَا بِٱلۡغُدُوِّ وَٱلۡـَٔاصَالِ ۝٣٦", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "هذا النور المضيء في مساجد أَمَرَ الله أن يُرْفع شأنها وبناؤها، ويُذْكر فيها اسمه بتلاوة كتابه والتسبيح والتهليل، وغير ذلك من أنواع الذكر، يُصلِّي فيها لله في الصباح والمساء.", "isBasmala": false, "translation_en": "In houses which God has permitted to be raised, and His name is celebrated therein. He is glorified therein, morning and evening.", "translation_id": "Bertasbih kepada Allah di masjid-masjid yang telah diperintahkan untuk dimuliakan dan disebut nama-Nya di dalamnya, pada waktu pagi dan waktu petang,", "manzil": 4, "manzil_display": ""}], "355": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 37, "text": "رِجَالࣱ لَّا تُلۡهِیهِمۡ تِجَـٰرَةࣱ وَلَا بَیۡعٌ عَن ذِكۡرِ ٱللَّهِ وَإِقَامِ ٱلصَّلَوٰةِ وَإِیتَاۤءِ ٱلزَّكَوٰةِ یَخَافُونَ یَوۡمࣰا تَتَقَلَّبُ فِیهِ ٱلۡقُلُوبُ وَٱلۡأَبۡصَـٰرُ ۝٣٧", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "رجال لا تشغلهم تجارة ولا بيع عن ذِكْرِ الله، وإقام الصلاة، وإيتاء الزكاة لمستحقيها، يخافون يوم القيامة الذي تتقلب فيه القلوب بين الرجاء في النجاة والخوف من الهلاك، وتتقلب فيه الأبصار تنظر إلى أي مصير تكون؟", "isBasmala": false, "translation_en": "By men who neither trading nor commerce distracts them from God's remembrance, and from performing the prayers, and from giving alms. They fear a Day when hearts and sights are overturned.", "translation_id": "laki-laki yang tidak dilalaikan oleh perniagaan dan tidak (pula) oleh jual beli dari mengingati Allah, dan (dari) mendirikan sembahyang, dan (dari) membayarkan zakat. Mereka takut kepada suatu hari yang (di hari itu) hati dan penglihatan menjadi goncang.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 38, "text": "لِیَجۡزِیَهُمُ ٱللَّهُ أَحۡسَنَ مَا عَمِلُوا۟ وَیَزِیدَهُم مِّن فَضۡلِهِۦۗ وَٱللَّهُ یَرۡزُقُ مَن یَشَاۤءُ بِغَیۡرِ حِسَابࣲ ۝٣٨", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "ليعطيهم الله ثواب أحسن أعمالهم، ويزيدهم من فضله بمضاعفة حسناتهم. والله يرزق مَن يشاء بغير حساب، بل يعطيه مِنَ الأجر ما لا يبلغه عمله، وبلا عدٍّ ولا كيل.", "isBasmala": false, "translation_en": "God will reward them according to the best of what they did, and He will increase them from His bounty. God provides for whomever He wills without reckoning.", "translation_id": "(Meraka mengerjakan yang demikian itu) supaya Allah memberikan balasan kepada mereka (dengan balasan) yang lebih baik dari apa yang telah mereka kerjakan, dan supaya Allah menambah karunia-Nya kepada mereka. Dan Allah memberi rezeki kepada siapa yang dikehendaki-Nya tanpa batas.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 39, "text": "وَٱلَّذِینَ كَفَرُوۤا۟ أَعۡمَـٰلُهُمۡ كَسَرَابِۭ بِقِیعَةࣲ یَحۡسَبُهُ ٱلظَّمۡـَٔانُ مَاۤءً حَتَّىٰۤ إِذَا جَاۤءَهُۥ لَمۡ یَجِدۡهُ شَیۡـࣰٔا وَوَجَدَ ٱللَّهَ عِندَهُۥ فَوَفَّىٰهُ حِسَابَهُۥۗ وَٱللَّهُ سَرِیعُ ٱلۡحِسَابِ ۝٣٩", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "والذين كفروا بربهم وكذَّبوا رسله، أعمالهم التي ظنوها نافعة لهم في الآخرة، كصلة الأرحام وفك الأسرى وغيرها، كسراب، وهو ما يشاهَد كالماء على الأرض المستوية في الظهيرة، يظنه العطشان ماء، فإذا أتاه لم يجده ماء. فالكافر يظن أن أعماله تنفعه، فإذا كان يوم القيامة لم يجد لها ثوابًا، ووجد الله سبحانه وتعالى له بالمرصاد فوفَّاه جزاء عمله كاملا. والله سريع الحساب، فلا يستبطئ الجاهلون ذلك الوعد، فإنه لا بدَّ مِن إتيانه.", "isBasmala": false, "translation_en": "As for those who disbelieve, their works are like a mirage in a desert. The thirsty assumes it is to be water. Until, when he has reached it, he finds it to be nothing, but there he finds God, Who settles his account in full. God is swift in reckoning.", "translation_id": "Dan orang-orang kafir amal-amal mereka adalah laksana fatamorgana di tanah yang datar, yang disangka air oleh orang-orang yang dahaga, tetapi bila didatanginya air itu dia tidak mendapatinya sesuatu apapun. Dan didapatinya (ketetapan) Allah disisinya, lalu Allah memberikan kepadanya perhitungan amal-amal dengan cukup dan Allah adalah sangat cepat perhitungan-Nya.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 40, "text": "أَوۡ كَظُلُمَـٰتࣲ فِی بَحۡرࣲ لُّجِّیࣲّ یَغۡشَىٰهُ مَوۡجࣱ مِّن فَوۡقِهِۦ مَوۡجࣱ مِّن فَوۡقِهِۦ سَحَابࣱۚ ظُلُمَـٰتُۢ بَعۡضُهَا فَوۡقَ بَعۡضٍ إِذَاۤ أَخۡرَجَ یَدَهُۥ لَمۡ یَكَدۡ یَرَىٰهَاۗ وَمَن لَّمۡ یَجۡعَلِ ٱللَّهُ لَهُۥ نُورࣰا فَمَا لَهُۥ مِن نُّورٍ ۝٤٠", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "أو تكون أعمالهم مثل ظلمات في بحر عميق يعلوه موج، من فوق الموج موج آخر، ومِن فوقه سحاب كثيف، ظلمات شديدة بعضها فوق بعض، إذا أخرج الناظر يده لم يقارب رؤيتها من شدة الظلمات، فالكفار تراكمت عليهم ظلمات الشرك والضلال وفساد الأعمال. ومن لم يجعل الله له نورًا من كتابه وسنة نبيه يهتدي به فما له مِن هاد.", "isBasmala": false, "translation_en": "Or like utter darkness in a vast ocean, covered by waves, above which are waves, above which is fog. Darkness upon darkness. If he brings out his hand, he will hardly see it. He to whom God has not granted a light has no light.", "translation_id": "Atau seperti gelap gulita di lautan yang dalam, yang diliputi oleh ombak, yang di atasnya ombak (pula), di atasnya (lagi) awan; gelap gulita yang tindih-bertindih, apabila dia mengeluarkan tangannya, tiadalah dia dapat melihatnya, (dan) barangsiapa yang tiada diberi cahaya (petunjuk) oleh Allah tiadalah dia mempunyai cahaya sedikitpun.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 41, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ یُسَبِّحُ لَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَٱلطَّیۡرُ صَـٰۤفَّـٰتࣲۖ كُلࣱّ قَدۡ عَلِمَ صَلَاتَهُۥ وَتَسۡبِیحَهُۥۗ وَٱللَّهُ عَلِیمُۢ بِمَا یَفۡعَلُونَ ۝٤١", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "ألم تعلم - أيها النبي - أن الله يُسَبِّح له مَن في السموات والأرض من المخلوقات، والطير صافات أجنحتها في السماء تسبح ربها؟ كل مخلوق قد أرشده الله كيف يصلي له ويسبحه. وهو سبحانه عليم، مُطَّلِع على ما يفعله كل عابد ومسبِّح، لا يخفى عليه منها شيء، وسيجازيهم بذلك.", "isBasmala": false, "translation_en": "Do you not realize that God is glorified by whatever is in the heavens and the earth, and even by the birds in formation? Each knows its prayer and its manner of praise. God knows well what they do.", "translation_id": "Tidaklah kamu tahu bahwasanya Allah: kepada-Nya bertasbih apa yang di langit dan di bumi dan (juga) burung dengan mengembangkan sayapnya. Masing-masing telah mengetahui (cara) sembahyang dan tasbihnya, dan Allah Maha Mengetahui apa yang mereka kerjakan.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 42, "text": "وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ وَإِلَى ٱللَّهِ ٱلۡمَصِیرُ ۝٤٢", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "ولله وحده ملك السموات والأرض، له السلطان فيهما، وإليه المرجع يوم القيامة.", "isBasmala": false, "translation_en": "To God belongs the dominion of the heavens and the earth, and to God is the ultimate return.", "translation_id": "Dan kepunyaan Allah-lah kerajaan langit dan bumi dan kepada Allah-lah kembali (semua makhluk).", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 43, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ یُزۡجِی سَحَابࣰا ثُمَّ یُؤَلِّفُ بَیۡنَهُۥ ثُمَّ یَجۡعَلُهُۥ رُكَامࣰا فَتَرَى ٱلۡوَدۡقَ یَخۡرُجُ مِنۡ خِلَـٰلِهِۦ وَیُنَزِّلُ مِنَ ٱلسَّمَاۤءِ مِن جِبَالࣲ فِیهَا مِنۢ بَرَدࣲ فَیُصِیبُ بِهِۦ مَن یَشَاۤءُ وَیَصۡرِفُهُۥ عَن مَّن یَشَاۤءُۖ یَكَادُ سَنَا بَرۡقِهِۦ یَذۡهَبُ بِٱلۡأَبۡصَـٰرِ ۝٤٣", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "ألم تشاهد أن الله سبحانه وتعالى يسوق السحاب إلى حيث يشاء، ثم يجمعه بعد تفرقه، ثم يجعله متراكمًا، فينزل مِن بينه المطر؟ وينزل من السحاب الذي يشبه الجبال في عظمته بَرَدًا، فيصيب به مَن يشاء من عباده ويصرفه عمَّن يشاء منهم بحسب حكمته وتقديره، يكاد ضوء ذلك البرق في السحاب مِن شدته يذهب بأبصار الناظرين إليه.", "isBasmala": false, "translation_en": "Have you not seen how God propels the clouds, then brings them together, then piles them into a heap, and you see rain drops emerging from its midst? How He brings down loads of hail from the sky, striking with it whomever He wills, and diverting it from whomever He wills? The flash of its lightening almost snatches the sight away.", "translation_id": "Tidaklah kamu melihat bahwa Allah mengarak awan, kemudian mengumpulkan antara (bagian-bagian)nya, kemudian menjadikannya bertindih-tindih, maka kelihatanlah olehmu hujan keluar dari celah-celahnya dan Allah (juga) menurunkan (butiran-butiran) es dari langit, (yaitu) dari (gumpalan-gumpalan awan seperti) gunung-gunung, maka ditimpakan-Nya (butiran-butiran) es itu kepada siapa yang dikehendaki-Nya dan dipalingkan-Nya dari siapa yang dikehendaki-Nya. Kilauan kilat awan itu hampir-hampir menghilangkan penglihatan.", "manzil": 4, "manzil_display": ""}], "356": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 44, "text": "یُقَلِّبُ ٱللَّهُ ٱلَّیۡلَ وَٱلنَّهَارَۚ إِنَّ فِی ذَ ٰلِكَ لَعِبۡرَةࣰ لِّأُو۟لِی ٱلۡأَبۡصَـٰرِ ۝٤٤", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "ومن دلائل قدرة الله سبحانه وتعالى أنه يقلب الليل والنهار بمجيء أحدهما بعد الآخر، واختلافهما طولا وقِصَرًا، إن في ذلك لَدلالة يعتبر بها كل مَن له بصيرة.", "isBasmala": false, "translation_en": "God alternates the night and the day. In that is a lesson for those who have insight.", "translation_id": "Allah mempergantikan malam dan siang. Sesungguhnya pada yang demikian itu terdapat pelajaran yang besar bagi orang-orang yang mempunyai penglihatan.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 45, "text": "وَٱللَّهُ خَلَقَ كُلَّ دَاۤبَّةࣲ مِّن مَّاۤءࣲۖ فَمِنۡهُم مَّن یَمۡشِی عَلَىٰ بَطۡنِهِۦ وَمِنۡهُم مَّن یَمۡشِی عَلَىٰ رِجۡلَیۡنِ وَمِنۡهُم مَّن یَمۡشِی عَلَىٰۤ أَرۡبَعࣲۚ یَخۡلُقُ ٱللَّهُ مَا یَشَاۤءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٤٥", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "والله تعالى خلق كل ما يدِب على الأرض مِن ماء، فالماء أصل خلقه، فمن هذه الدواب: مَن يمشي زحفًا على بطنه كالحيَّات ونحوها، ومنهم مَن يمشي على رجلين كالإنسان، ومنهم من يمشي على أربع كالبهائم ونحوها. والله سبحانه وتعالى يخلق ما يشاء، وهو قادر على كل شيء.", "isBasmala": false, "translation_en": "God created every living creature from water. Some of them crawl on their bellies, and some walk on two feet, and others walk on four. God creates whatever He wills. God is Capable of everything.", "translation_id": "Dan Allah telah menciptakan semua jenis hewan dari air, maka sebagian dari hewan itu ada yang berjalan di atas perutnya dan sebagian berjalan dengan dua kaki sedang sebagian (yang lain) berjalan dengan empat kaki. Allah menciptakan apa yang dikehendaki-Nya, sesungguhnya Allah Maha Kuasa atas segala sesuatu.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 46, "text": "لَّقَدۡ أَنزَلۡنَاۤ ءَایَـٰتࣲ مُّبَیِّنَـٰتࣲۚ وَٱللَّهُ یَهۡدِی مَن یَشَاۤءُ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٤٦", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "لقد أنزلنا في القرآن علامات واضحات مرشدات إلى الحق. والله يهدي ويوفق مَن يشاء مِن عباده إلى الطريق المستقيم، وهو الإسلام.", "isBasmala": false, "translation_en": "We sent down enlightening revelations, and God guides whomever He wills to a straight path.", "translation_id": "Sesungguhnya Kami telah menurunkan ayat-ayat yang menjelaskan. Dan Allah memimpin siapa yang dikehendaki-Nya kepada jalan yang lurus.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 47, "text": "وَیَقُولُونَ ءَامَنَّا بِٱللَّهِ وَبِٱلرَّسُولِ وَأَطَعۡنَا ثُمَّ یَتَوَلَّىٰ فَرِیقࣱ مِّنۡهُم مِّنۢ بَعۡدِ ذَ ٰلِكَۚ وَمَاۤ أُو۟لَـٰۤىِٕكَ بِٱلۡمُؤۡمِنِینَ ۝٤٧", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "ويقول المنافقون: صَدَّقنا بالله وبما جاء به الرسول، وأطعنا أمرهما، ثم تُعْرِضُ طوائف منهم من بعد ذلك فلا تقبل حكم الرسول، وما أولئك بالمؤمنين.", "isBasmala": false, "translation_en": "And they say, \"We have believed in God and the Messenger, and we obey,\" but some of them turn away afterwards. These are not believers.", "translation_id": "Dan mereka berkata: \"Kami telah beriman kepada Allah dan rasul, dan kami mentaati (keduanya)\". Kemudian sebagian dari mereka berpaling sesudah itu, sekali-kali mereka itu bukanlah orang-orang yang beriman.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 48, "text": "وَإِذَا دُعُوۤا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِیَحۡكُمَ بَیۡنَهُمۡ إِذَا فَرِیقࣱ مِّنۡهُم مُّعۡرِضُونَ ۝٤٨", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "وإذا دُعوا في خصوماتهم إلى ما في كتاب الله وإلى رسوله؛ ليَحكُم بينهم، إذا فريق منهم معرض لا يقبل حكم الله وحكم رسوله، مع أنه الحق الذي لا شك فيه.", "isBasmala": false, "translation_en": "And when they are called to God and His Messenger, in order to judge between them, some of them refuse.", "translation_id": "Dan apabila mereka dipanggil kepada Allah dan rasul-Nya, agar rasul menghukum (mengadili) di antara mereka, tiba-tiba sebagian dari mereka menolak untuk datang.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 49, "text": "وَإِن یَكُن لَّهُمُ ٱلۡحَقُّ یَأۡتُوۤا۟ إِلَیۡهِ مُذۡعِنِینَ ۝٤٩", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "وإن يكن الحق في جانبهم فإنهم يأتون إلى النبي عليه الصلاة والسلام طائعين منقادين لحكمه؛ لعلمهم أنه يقضي بالحق.", "isBasmala": false, "translation_en": "But if justice is on their side, they accept it willingly.", "translation_id": "Tetapi jika keputusan itu untuk (kemaslahatan) mereka, mereka datang kepada rasul dengan patuh.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 50, "text": "أَفِی قُلُوبِهِم مَّرَضٌ أَمِ ٱرۡتَابُوۤا۟ أَمۡ یَخَافُونَ أَن یَحِیفَ ٱللَّهُ عَلَیۡهِمۡ وَرَسُولُهُۥۚ بَلۡ أُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ ۝٥٠", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "أسَبَبُ الإعراض ما في قلوبهم من مرض النفاق، أم شكُّوا في نبوة محمد صلى الله عليه وسلم، أم السبب خوفهم أن يكون حكم الله ورسوله جائرًا؟ كلا إنهم لا يخافون جورًا، بل السبب أنهم هم الظالمون الفجرة.", "isBasmala": false, "translation_en": "Is there sickness in their hearts? Or are they suspicious? Or do they fear that God may do them injustice? Or His Messenger? In fact, they themselves are the unjust.", "translation_id": "Apakah (ketidak datangan mereka itu karena) dalam hati mereka ada penyakit, atau (karena) mereka ragu-ragu ataukah (karena) takut kalau-kalau Allah dan rasul-Nya berlaku zalim kepada mereka? Sebenarnya, mereka itulah orang-orang yang zalim.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 51, "text": "إِنَّمَا كَانَ قَوۡلَ ٱلۡمُؤۡمِنِینَ إِذَا دُعُوۤا۟ إِلَى ٱللَّهِ وَرَسُولِهِۦ لِیَحۡكُمَ بَیۡنَهُمۡ أَن یَقُولُوا۟ سَمِعۡنَا وَأَطَعۡنَاۚ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝٥١", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "أما المؤمنون حقا فدأبهم إذا دعوا إلى التحاكم في خصوماتهم إلى كتاب الله وحكم رسوله، أن يقبلوا الحكم ويقولوا: سمعنا ما قيل لنا وأطعنا مَن دعانا إلى ذلك، وأولئك هم المفلحون الفائزون بمطلوبهم في جنات النعيم.", "isBasmala": false, "translation_en": "The response of the believers, when they are called to God and His Messenger in order to judge between them, is to say, \"We hear and we obey.\" These are the successful.", "translation_id": "Sesungguhnya jawaban oran-orang mukmin, bila mereka dipanggil kepada Allah dan rasul-Nya agar rasul menghukum (mengadili) di antara mereka ialah ucapan. \"Kami mendengar, dan kami patuh\". Dan mereka itulah orang-orang yang beruntung.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 52, "text": "وَمَن یُطِعِ ٱللَّهَ وَرَسُولَهُۥ وَیَخۡشَ ٱللَّهَ وَیَتَّقۡهِ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَاۤىِٕزُونَ ۝٥٢", "juz": 18, "hizb": "(*¼ ح 36*)", "tafsir": "ومن يطع الله ورسوله في الأمر والنهي، ويَخَفْ عواقب العصيان، ويحْذَر عذاب الله، فهؤلاء هم الفائزون بالنعيم في الجنة.", "isBasmala": false, "translation_en": "Whoever obeys God and His Messenger, and fears God, and is conscious of Him-these are the winners.", "translation_id": "Dan barang siapa yang taat kepada Allah dan rasul-Nya dan takut kepada Allah dan bertakwa kepada-Nya, maka mereka adalah orang-orang yang mendapat kemenangan.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 53, "text": "۞ وَأَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ لَىِٕنۡ أَمَرۡتَهُمۡ لَیَخۡرُجُنَّۖ قُل لَّا تُقۡسِمُوا۟ۖ طَاعَةࣱ مَّعۡرُوفَةٌۚ إِنَّ ٱللَّهَ خَبِیرُۢ بِمَا تَعۡمَلُونَ ۝٥٣", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "وأقسم المنافقون بالله تعالى غاية اجتهادهم في الأيمان المغلَّظة: لئن أمرتنا - أيها الرسول - بالخروج للجهاد معك لنخرجن، قل لهم: لا تحلفوا كذبًا، فطاعتكم معروفة بأنها باللسان فحسب، إن الله خبير بما تعملونه، وسيجازيكم عليه.", "isBasmala": false, "translation_en": "And they swear by God with their solemn oaths, that if you commanded them, they would mobilize. Say, \"Do not swear. Obedience will be recognized. God is experienced with what you do.\"", "translation_id": "Dan mereka bersumpah dengan nama Allah sekuat-kuat sumpah, jika kamu suruh mereka berperang, pastilah mereka akan pergi. Katakanlah: \"Janganlah kamu bersumpah, (karena ketaatan yang diminta ialah) ketaatan yang sudah dikenal. Sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 4, "manzil_display": ""}], "357": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 54, "text": "قُلۡ أَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَۖ فَإِن تَوَلَّوۡا۟ فَإِنَّمَا عَلَیۡهِ مَا حُمِّلَ وَعَلَیۡكُم مَّا حُمِّلۡتُمۡۖ وَإِن تُطِیعُوهُ تَهۡتَدُوا۟ۚ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ ۝٥٤", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "قل - أيها الرسول - للناس: أطيعوا الله وأطيعوا الرسول، فإن أعرضوا فإنما على الرسول فِعْلُ ما أُمر به من تبليغ الرسالة، وعلى الجميع فِعْلُ ما كُلِّفوه من الامتثال، وإن تطيعوه ترشدوا إلى الحق، وليس على الرسول إلا أن يبلغ رسالة ربه بلاغًا بينًا.", "isBasmala": false, "translation_en": "Say, \"Obey God and obey the Messenger.\" But if they turn away, then he is responsible for his obligations, and you are responsible for your obligations. And if you obey him, you will be guided. It is only incumbent on the Messenger to deliver the Clarifying Message.", "translation_id": "Katakanlah: \"Taat kepada Allah dan taatlah kepada rasul; dan jika kamu berpaling maka sesungguhnya kewajiban rasul itu adalah apa yang dibebankan kepadanya, dan kewajiban kamu sekalian adalah semata-mata apa yang dibebankan kepadamu. Dan jika kamu taat kepadanya, niscaya kamu mendapat petunjuk. Dan tidak lain kewajiban rasul itu melainkan menyampaikan (amanat Allah) dengan terang\".", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 55, "text": "وَعَدَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ مِنكُمۡ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَیَسۡتَخۡلِفَنَّهُمۡ فِی ٱلۡأَرۡضِ كَمَا ٱسۡتَخۡلَفَ ٱلَّذِینَ مِن قَبۡلِهِمۡ وَلَیُمَكِّنَنَّ لَهُمۡ دِینَهُمُ ٱلَّذِی ٱرۡتَضَىٰ لَهُمۡ وَلَیُبَدِّلَنَّهُم مِّنۢ بَعۡدِ خَوۡفِهِمۡ أَمۡنࣰاۚ یَعۡبُدُونَنِی لَا یُشۡرِكُونَ بِی شَیۡـࣰٔاۚ وَمَن كَفَرَ بَعۡدَ ذَ ٰلِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ ۝٥٥", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "وعد الله بالنصر الذين آمنوا منكم وعملوا الأعمال الصالحة، بأن يورثهم أرض المشركين، ويجعلهم خلفاء فيها، مثلما فعل مع أسلافهم من المؤمنين بالله ورسله، وأن يجعل دينهم الذي ارتضاه لهم- وهو الإسلام- دينًا عزيزًا مكينًا، وأن يبدل حالهم من الخوف إلى الأمن، إذا عبدوا الله وحده، واستقاموا على طاعته، ولم يشركوا معه شيئًا، ومن كفر بعد ذلك الاستخلاف والأمن والتمكين والسلطنة التامة، وجحد نِعَم الله، فأولئك هم الخارجون عن طاعة الله.", "isBasmala": false, "translation_en": "God has promised those of you who believe and do righteous deeds, that He will make them successors on earth, as He made those before them successors, and He will establish for them their religion-which He has approved for them-and He will substitute security in place of their fear. They worship Me, never associating anything with Me. But whoever disbelieves after that-these are the sinners.", "translation_id": "Dan Allah telah berjanji kepada orang-orang yang beriman di antara kamu dan mengerjakan amal-amal yang saleh bahwa Dia sungguh-sungguh akan menjadikan mereka berkuasa dimuka bumi, sebagaimana Dia telah menjadikan orang-orang sebelum mereka berkuasa, dan sungguh Dia akan meneguhkan bagi mereka agama yang telah diridhai-Nya untuk mereka, dan Dia benar-benar akan menukar (keadaan) mereka, sesudah mereka dalam ketakutan menjadi aman sentausa. Mereka tetap menyembahku-Ku dengan tiada mempersekutukan sesuatu apapun dengan Aku. Dan barangsiapa yang (tetap) kafir sesudah (janji) itu, maka mereka itulah orang-orang yang fasik.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 56, "text": "وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِیعُوا۟ ٱلرَّسُولَ لَعَلَّكُمۡ تُرۡحَمُونَ ۝٥٦", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "وأقيموا الصلاة تامة، وآتوا الزكاة لمستحقيها، وأطيعوا الرسول صلى الله عليه وسلم؛ رجاء أن يرحمكم الله.", "isBasmala": false, "translation_en": "Pray regularly, and give regular charity, and obey the Messenger, so that you may receive mercy.", "translation_id": "Dan dirikanlah sembahyang, tunaikanlah zakat, dan taatlah kepada rasul, supaya kamu diberi rahmat.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 57, "text": "لَا تَحۡسَبَنَّ ٱلَّذِینَ كَفَرُوا۟ مُعۡجِزِینَ فِی ٱلۡأَرۡضِۚ وَمَأۡوَىٰهُمُ ٱلنَّارُۖ وَلَبِئۡسَ ٱلۡمَصِیرُ ۝٥٧", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "لا تظننَّ الذين كفروا معجزين الله في الأرض، بل هو قادر على إهلاكهم، ومرجعهم في الآخرة إلى النار، وقبُح هذا المرجع والمصير. وهو توجيه عام للأمّة، وإن كان الخطاب فيه للرسول صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Never think that those who disbelieve can escape on earth. Their place is the Fire; a miserable destination.", "translation_id": "Janganlah kamu kira bahwa orang-orang yang kafir itu dapat melemahkan (Allah dari mengazab mereka) di bumi ini, sedang tempat tinggal mereka (di akhirat) adalah neraka. Dan sungguh amat jeleklah tempat kembali itu.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 58, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لِیَسۡتَـٔۡذِنكُمُ ٱلَّذِینَ مَلَكَتۡ أَیۡمَـٰنُكُمۡ وَٱلَّذِینَ لَمۡ یَبۡلُغُوا۟ ٱلۡحُلُمَ مِنكُمۡ ثَلَـٰثَ مَرَّ ٰتࣲۚ مِّن قَبۡلِ صَلَوٰةِ ٱلۡفَجۡرِ وَحِینَ تَضَعُونَ ثِیَابَكُم مِّنَ ٱلظَّهِیرَةِ وَمِنۢ بَعۡدِ صَلَوٰةِ ٱلۡعِشَاۤءِۚ ثَلَـٰثُ عَوۡرَ ٰتࣲ لَّكُمۡۚ لَیۡسَ عَلَیۡكُمۡ وَلَا عَلَیۡهِمۡ جُنَاحُۢ بَعۡدَهُنَّۚ طَوَّ ٰفُونَ عَلَیۡكُم بَعۡضُكُمۡ عَلَىٰ بَعۡضࣲۚ كَذَ ٰلِكَ یُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ ۝٥٨", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه مُروا عبيدكم وإماءكم، والأطفال الأحرار دون سن الاحتلام أن يستأذنوا عند الدخول عليكم في أوقات عوراتكم الثلاثة: من قبل صلاة الفجر؛ لأنه وقت الخروج من ثياب النوم ولبس ثياب اليقظة، ووقت خلع الثياب للقيلولة في الظهيرة، ومن بعد صلاة العشاء؛ لأنه وقت للنوم، وهذه الأوقات الثلاثة عورات لكم، يقل فيها التستر، أما فيما سواها فلا حرج إذا دخلوا بغير إذن؛ لحاجتهم في الدخول عليكم، طوافون عليكم للخدمة، وكما بيَّن الله لكم أحكام الاستئذان يبيِّن لكم آياته وأحكامه وحججه وشرائع دينه. والله عليم بما يصلح خلقه، حكيم في تدبيره أمورهم.", "isBasmala": false, "translation_en": "O you who believe! Permission must be requested by your servants and those of you who have not reached puberty. On three occasions: before the Dawn Prayer, and at noon when you change your clothes, and after the Evening Prayer. These are three occasions of privacy for you. At other times, it is not wrong for you or them to intermingle with one another. God thus clarifies the revelations for you. God is Knowledgeable and Wise.", "translation_id": "Hai orang-orang yang beriman, hendaklah budak-budak (lelaki dan wanita) yang kamu miliki, dan orang-orang yang belum balig di antara kamu, meminta izin kepada kamu tiga kali (dalam satu hari) yaitu: sebelum sembahyang subuh, ketika kamu menanggalkan pakaian (luar)mu di tengah hari dan sesudah sembahyang Isya'. (Itulah) tiga aurat bagi kamu. Tidak ada dosa atasmu dan tidak (pula) atas mereka selain dari (tiga waktu) itu. Mereka melayani kamu, sebahagian kamu (ada keperluan) kepada sebahagian (yang lain). Demikianlah Allah menjelaskan ayat-ayat bagi kamu. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 4, "manzil_display": ""}], "358": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 59, "text": "وَإِذَا بَلَغَ ٱلۡأَطۡفَـٰلُ مِنكُمُ ٱلۡحُلُمَ فَلۡیَسۡتَـٔۡذِنُوا۟ كَمَا ٱسۡتَـٔۡذَنَ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَذَ ٰلِكَ یُبَیِّنُ ٱللَّهُ لَكُمۡ ءَایَـٰتِهِۦۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ ۝٥٩", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "وإذا بلغ الأطفال منكم سن الاحتلام والتكليف بالأحكام الشرعية، فعليهم أن يستأذنوا إذا أرادوا الدخول في كل الأوقات كما يستأذن الكبار، وكما يبيِّن الله آداب الاستئذان يبيِّن الله تعالى لكم آياته. والله عليم بما يصلح عباده، حكيم في تشريعه.", "isBasmala": false, "translation_en": "When the children among you reach puberty, they must ask permission, as those before them asked permission. God thus clarifies His revelations for you. God is Knowledgeable and Wise.", "translation_id": "Dan apabila anak-anakmu telah sampai umur balig, maka hendaklah mereka meminta izin, seperti orang-orang yang sebelum mereka meminta izin. Demikianlah Allah menjelaskan ayat-ayat-Nya. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 60, "text": "وَٱلۡقَوَ ٰعِدُ مِنَ ٱلنِّسَاۤءِ ٱلَّـٰتِی لَا یَرۡجُونَ نِكَاحࣰا فَلَیۡسَ عَلَیۡهِنَّ جُنَاحٌ أَن یَضَعۡنَ ثِیَابَهُنَّ غَیۡرَ مُتَبَرِّجَـٰتِۭ بِزِینَةࣲۖ وَأَن یَسۡتَعۡفِفۡنَ خَیۡرࣱ لَّهُنَّۗ وَٱللَّهُ سَمِیعٌ عَلِیمࣱ ۝٦٠", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "والعجائز من النساء اللاتي قعدن عن الاستمتاع والشهوة لكبرهن، فلا يطمعن في الرجال للزواج، ولا يطمع فيهن الرجال كذلك، فهؤلاء لا حرج عليهن أن يضعن بعض ثيابهن كالرداء الذي يكون فوق الثياب غير مظهرات ولا متعرضات للزينة، ولُبْسهن هذه الثياب - سترًا وتعففًا- أحسن لهن. والله سميع لأقوالكم، عليم بنياتكم وأعمالكم.", "isBasmala": false, "translation_en": "Women past the age of childbearing, who have no desire for marriage, commit no wrong by taking off their outer clothing, provided they do not flaunt their finery. But to maintain modesty is better for them. God is Hearing and Knowing.", "translation_id": "Dan perempuan-perempuan tua yang telah terhenti (dari haid dan mengandung) yang tiada ingin kawin (lagi), tiadalah atas mereka dosa menanggalkan pakaian mereka dengan tidak (bermaksud) menampakkan perhiasan, dan berlaku sopan adalah lebih baik bagi mereka. Dan Allah Maha Mendengar lagi Maha Bijaksana.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 61, "text": "لَّیۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجࣱ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجࣱ وَلَا عَلَى ٱلۡمَرِیضِ حَرَجࣱ وَلَا عَلَىٰۤ أَنفُسِكُمۡ أَن تَأۡكُلُوا۟ مِنۢ بُیُوتِكُمۡ أَوۡ بُیُوتِ ءَابَاۤىِٕكُمۡ أَوۡ بُیُوتِ أُمَّهَـٰتِكُمۡ أَوۡ بُیُوتِ إِخۡوَ ٰنِكُمۡ أَوۡ بُیُوتِ أَخَوَ ٰتِكُمۡ أَوۡ بُیُوتِ أَعۡمَـٰمِكُمۡ أَوۡ بُیُوتِ عَمَّـٰتِكُمۡ أَوۡ بُیُوتِ أَخۡوَ ٰلِكُمۡ أَوۡ بُیُوتِ خَـٰلَـٰتِكُمۡ أَوۡ مَا مَلَكۡتُم مَّفَاتِحَهُۥۤ أَوۡ صَدِیقِكُمۡۚ لَیۡسَ عَلَیۡكُمۡ جُنَاحٌ أَن تَأۡكُلُوا۟ جَمِیعًا أَوۡ أَشۡتَاتࣰاۚ فَإِذَا دَخَلۡتُم بُیُوتࣰا فَسَلِّمُوا۟ عَلَىٰۤ أَنفُسِكُمۡ تَحِیَّةࣰ مِّنۡ عِندِ ٱللَّهِ مُبَـٰرَكَةࣰ طَیِّبَةࣰۚ كَذَ ٰلِكَ یُبَیِّنُ ٱللَّهُ لَكُمُ ٱلۡـَٔایَـٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ ۝٦١", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "ليس على أصحاب الأعذار من العُمْيان وذوي العرج والمرضى إثم في ترك الأمور الواجبة التي لا يقدرون على القيام بها، كالجهاد ونحوه، مما يتوقف على بصر الأعمى أو سلامة الأعرج أو صحة المريض، وليس على أنفسكم- أيها المؤمنون- حرج في أن تأكلوا من بيوت أولادكم، أو من بيوت آبائكم، أو أمهاتكم، أو إخوانكم، أو أخواتكم، أو أعمامكم، أو عماتكم، أو أخوالكم، أو خالاتكم، أو من البيوت التي وُكِّلْتم بحفظها في غيبة أصحابها بإذنهم، أو من بيوت الأصدقاء، ولا حرج عليكم أن تأكلوا مجتمعين أو متفرقين، فإذا دخلتم بيوتًا مسكونة أو غير مسكونة فليسلِّم بعضكم على بعض بتحية الإسلام، وهي: السلام عليكم ورحمة الله وبركاته، أو السلام علينا وعلى عباد الله الصالحين، إذا لم يوجد أحد، وهذه التحية شرعها الله، وهي مباركة تُنْمِي المودة والمحبة، طيبة محبوبة للسامع، وبمثل هذا التبيين يبيِّن الله لكم معالم دينه وآياته؛ لتعقلوها، وتعملوا بها.", "isBasmala": false, "translation_en": "There is no blame on the blind, nor any blame on the lame, nor any blame on the sick, nor on yourselves for eating at your homes, or your fathers' homes, or your mothers' homes, or your brothers' homes, or your sisters' homes, or the homes of your paternal uncles, or the homes of your paternal aunts, or the homes of your maternal uncles, or the homes of your maternal aunts, or those whose keys you own, or the homes of your friends. You commit no wrong by eating together or separately. But when you enter any home, greet one another with a greeting from God, blessed and good. God thus explains the revelations for you, so that you may understand.", "translation_id": "Tidak ada halangan bagi orang buta, tidak (pula) bagi orang pincang, tidak (pula) bagi orang sakit, dan tidak (pula) bagi dirimu sendiri, makan (bersama-sama mereka) dirumah kamu sendiri atau dirumah bapak-bapakmu, dirumah ibu-ibumu, dirumah saudara-saudaramu yang laki-laki, di rumah saudaramu yang perempuan, dirumah saudara bapakmu yang laki-laki, dirumah saudara bapakmu yang perempuan, dirumah saudara ibumu yang laki-laki, dirumah saudara ibumu yang perempuan, dirumah yang kamu miliki kuncinya atau dirumah kawan-kawanmu. Tidak ada halangan bagi kamu makan bersama-sama mereka atau sendirian. Maka apabila kamu memasuki (suatu rumah dari) rumah-rumah (ini) hendaklah kamu memberi salam kepada (penghuninya yang berarti memberi salam) kepada dirimu sendiri, salam yang ditetapkan dari sisi Allah, yang diberi berkat lagi baik. Demikianlah Allah menjelaskan ayat-ayatnya(Nya) bagimu, agar kamu memahaminya.", "manzil": 4, "manzil_display": ""}], "359": [{"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 62, "text": "إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَإِذَا كَانُوا۟ مَعَهُۥ عَلَىٰۤ أَمۡرࣲ جَامِعࣲ لَّمۡ یَذۡهَبُوا۟ حَتَّىٰ یَسۡتَـٔۡذِنُوهُۚ إِنَّ ٱلَّذِینَ یَسۡتَـٔۡذِنُونَكَ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ یُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦۚ فَإِذَا ٱسۡتَـٔۡذَنُوكَ لِبَعۡضِ شَأۡنِهِمۡ فَأۡذَن لِّمَن شِئۡتَ مِنۡهُمۡ وَٱسۡتَغۡفِرۡ لَهُمُ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝٦٢", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "إنما المؤمنون حقًا هم الذين صدَّقوا الله ورسوله، وعملوا بشرعه، وإذا كانوا مع النبي صلى الله عليه وسلم على أمر جمعهم له في مصلحة المسلمين، لم ينصرف أحد منهم حتى يستأذنه، إن الذين يستأذنونك - أيها النبي - هم الذين يؤمنون بالله ورسوله حقًا، فإذا استأذنوك لبعض حاجتهم فَأْذَن لمن شئت ممن طلب الإذن في الانصراف لعذر، واطلب لهم المغفرة من الله. إن الله غفور لذنوب عباده التائبين، رحيم بهم.", "isBasmala": false, "translation_en": "The believers are those who believe in God and His Messenger, and when they are with him for a matter of common interest, they do not leave until they have asked him for permission. Those who ask your permission are those who believe in God and His Messenger. So when they ask your permission to attend to some affair of theirs, give permission to any of them you wish, and ask God's forgiveness for them. God is Forgiving and Merciful.", "translation_id": "Sesungguhnya yang sebenar-benar orang mukmin ialah orang-orang yang beriman kepada Allah dan Rasul-Nya, dan apabila mereka berada bersama-sama Rasulullah dalam sesuatu urusan yang memerlukan pertemuan, mereka tidak meninggalkan (Rasulullah) sebelum meminta izin kepadanya. Sesungguhnya orang-orang yang meminta izin kepadamu (Muhammad) mereka itulah orang-orang yang beriman kepada Allah dan rasul-Nya, maka apabila mereka meminta izin kepadamu karena sesuatu keperluan, berilah izin kepada siapa yang kamu kehendaki di antara mereka, dan mohonkanlah ampunan untuk mereka kepada Allah. Sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 63, "text": "لَّا تَجۡعَلُوا۟ دُعَاۤءَ ٱلرَّسُولِ بَیۡنَكُمۡ كَدُعَاۤءِ بَعۡضِكُم بَعۡضࣰاۚ قَدۡ یَعۡلَمُ ٱللَّهُ ٱلَّذِینَ یَتَسَلَّلُونَ مِنكُمۡ لِوَاذࣰاۚ فَلۡیَحۡذَرِ ٱلَّذِینَ یُخَالِفُونَ عَنۡ أَمۡرِهِۦۤ أَن تُصِیبَهُمۡ فِتۡنَةٌ أَوۡ یُصِیبَهُمۡ عَذَابٌ أَلِیمٌ ۝٦٣", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "لا تقولوا -أيها المؤمنون- عند ندائكم رسول الله: يا محمد، ولا يا محمد بن عبد الله، كما يقول ذلك بعضكم لبعض، ولكن شرِّفوه، وقولوا: يا نبي الله، يا رسول الله. قد يعلم الله المنافقين الذين يخرجون من مجلس النبي صلى الله عليه وسلم خفية بغير إذنه، يلوذ بعضهم ببعض، فليَحْذَر الذين يخالفون أمر رسول الله أن تنزل بهم محنة وشر، أو يصيبهم عذاب مؤلم موجع في الآخرة.", "isBasmala": false, "translation_en": "Do not address the Messenger in the same manner you address one another. God knows those of you who slip away using flimsy excuses. So let those who oppose his orders beware, lest an ordeal strikes them, or a painful punishment befalls them.", "translation_id": "Janganlah kamu jadikan panggilan Rasul diantara kamu seperti panggilan sebahagian kamu kepada sebahagian (yang lain). Sesungguhnya Allah telah mengetahui orang-orang yang berangsur-angsur pergi di antara kamu dengan berlindung (kepada kawannya), maka hendaklah orang-orang yang menyalahi perintah Rasul takut akan ditimpa cobaan atau ditimpa azab yang pedih.", "manzil": 4, "manzil_display": ""}, {"sura": 24, "sura_name": "النور", "revelation": "Madaniyah", "aya": 64, "text": "أَلَاۤ إِنَّ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ قَدۡ یَعۡلَمُ مَاۤ أَنتُمۡ عَلَیۡهِ وَیَوۡمَ یُرۡجَعُونَ إِلَیۡهِ فَیُنَبِّئُهُم بِمَا عَمِلُوا۟ۗ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمُۢ ۝٦٤", "juz": 18, "hizb": "(*½ ح 36*)", "tafsir": "ألا إن لله ما في السموات والأرض خلقًا وملكًا وعبادة، قد أحاط علمه بجميع ما أنتم عليه، ويوم يرجع العباد إليه في الآخرة، يخبرهم بعملهم، ويجازيهم عليه، والله بكل شيء عليم، لا تخفى عليه أعمالهم وأحوالهم.", "isBasmala": false, "translation_en": "Surely, to God belongs everything in the heavens and the earth. He knows what you are about. And on the Day they are returned to Him, He will inform them of what they did. God has full knowledge of all things.", "translation_id": "Ketahuilah sesungguhnya kepunyaan Allahlah apa yang di langit dan di bumi. Sesungguhnya Dia mengetahui keadaan yang kamu berada di dalamnya (sekarang). Dan (mengetahui pula) hati (manusia) dikembalikan kepada-Nya, lalu diterangkan-Nya kepada mereka apa yang telah mereka kerjakan. Dan Allah Maha mengehui segala sesuatu.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 19, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 1, "text": "۞ تَبَارَكَ ٱلَّذِی نَزَّلَ ٱلۡفُرۡقَانَ عَلَىٰ عَبۡدِهِۦ لِیَكُونَ لِلۡعَـٰلَمِینَ نَذِیرًا ۝١", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "عَظُمَتْ بركات الله، وكثرت خيراته، وكملت أوصافه سبحانه وتعالى الذي نزَّل القرآن الفارق بين الحق والباطل على عبده محمد صلى الله عليه وسلم؛ ليكون رسولا للإنس والجن، مخوِّفًا لهم من عذاب الله.", "isBasmala": false, "translation_en": "Blessed is He who sent down the Criterion upon His servant, to be a warning to humanity.", "translation_id": "Maha suci Allah yang telah menurunkan Al Furqaan (Al Quran) kepada hamba-Nya, agar dia menjadi pemberi peringatan kepada seluruh alam,", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 2, "text": "ٱلَّذِی لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَلَمۡ یَتَّخِذۡ وَلَدࣰا وَلَمۡ یَكُن لَّهُۥ شَرِیكࣱ فِی ٱلۡمُلۡكِ وَخَلَقَ كُلَّ شَیۡءࣲ فَقَدَّرَهُۥ تَقۡدِیرࣰا ۝٢", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "الذي له ملك السموات والأرض، ولم يتخذ ولدًا، ولم يكن له شريك في ملكه، وهو الذي خلق كل شيء، فسوَّاه على ما يناسبه من الخلق وَفْق ما تقتضيه حكمته دون نقص أو خلل.", "isBasmala": false, "translation_en": "He to whom belongs the kingdom of the heavens and the earth, who took to Himself no son, who never had a partner in His kingship; who created everything and determined its measure.", "translation_id": "yang kepunyaan-Nya-lah kerajaan langit dan bumi, dan Dia tidak mempunyai anak, dan tidak ada sekutu bagi-Nya dalam kekuasaan(Nya), dan dia telah menciptakan segala sesuatu, dan Dia menetapkan ukuran-ukurannya dengan serapi-rapinya.", "manzil": 4, "manzil_display": ""}], "360": [{"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 3, "text": "وَٱتَّخَذُوا۟ مِن دُونِهِۦۤ ءَالِهَةࣰ لَّا یَخۡلُقُونَ شَیۡـࣰٔا وَهُمۡ یُخۡلَقُونَ وَلَا یَمۡلِكُونَ لِأَنفُسِهِمۡ ضَرࣰّا وَلَا نَفۡعࣰا وَلَا یَمۡلِكُونَ مَوۡتࣰا وَلَا حَیَوٰةࣰ وَلَا نُشُورࣰا ۝٣", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "واتخذ مشركو العرب معبودات من دون الله لا تستطيع خَلْق شيء، والله خلقها وخلقهم، ولا تملك لنفسها دَفْعَ ضر أو جلب نفع، ولا تستطيع إماتة حي أو إحياء ميت، أو بعث أحد من الأموات حيًا من قبره.", "isBasmala": false, "translation_en": "And yet, instead of Him, they produce for themselves gods that create nothing, but are themselves created; that have no power to harm or benefit themselves; and no power over life, death, or resurrection.", "translation_id": "Kemudian mereka mengambil tuhan-tuhan selain daripada-Nya (untuk disembah), yang tuhan-tuhan itu tidak menciptakan apapun, bahkan mereka sendiri diciptakan dan tidak kuasa untuk (menolak) sesuatu kemudharatan dari dirinya dan tidak (pula untuk mengambil) suatu kemanfaatanpun dan (juga) tidak kuasa mematikan, menghidupkan dan tidak (pula) membangkitkan.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 4, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّاۤ إِفۡكٌ ٱفۡتَرَىٰهُ وَأَعَانَهُۥ عَلَیۡهِ قَوۡمٌ ءَاخَرُونَۖ فَقَدۡ جَاۤءُو ظُلۡمࣰا وَزُورࣰا ۝٤", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "وقال الكافرون بالله: ما هذا القرآن إلا كذب وبهتان اختلقه محمد، وأعانه على ذلك أناس آخرون، فقد ارتكبوا ظلمًا فظيعًا، وأتوا زورًا شنيعًا؛ فالقرآن ليس مما يمكن لبشر أن يختلقه.", "isBasmala": false, "translation_en": "Those who disbelieve say, \"This is nothing but a lie that he made up, and others have helped him at it.\" They have committed an injustice and a perjury.", "translation_id": "Dan orang-orang kafir berkata: \"Al Quran ini tidak lain hanyalah kebohongan yang diada-adakan oleh Muhammad dan dia dibantu oleh kaum yang lain\"; maka sesungguhnya mereka telah berbuat suatu kezaliman dan dusta yang besar.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 5, "text": "وَقَالُوۤا۟ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ٱكۡتَتَبَهَا فَهِیَ تُمۡلَىٰ عَلَیۡهِ بُكۡرَةࣰ وَأَصِیلࣰا ۝٥", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "وقالوا عن القرآن: هو أحاديث الأولين المسطرة في كتبهم، استنسخها محمد، فهي تُقْرَأ عليه صباحًا ومساء.", "isBasmala": false, "translation_en": "And they say, \"Tales of the ancients; he wrote them down; they are dictated to him morning and evening.\"", "translation_id": "Dan mereka berkata: \"Dongengan-dongengan orang-orang dahulu, dimintanya supaya dituliskan, maka dibacakanlah dongengan itu kepadanya setiap pagi dan petang\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 6, "text": "قُلۡ أَنزَلَهُ ٱلَّذِی یَعۡلَمُ ٱلسِّرَّ فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ غَفُورࣰا رَّحِیمࣰا ۝٦", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "قل - أيها الرسول - لهؤلاء الكفار: إن الذي أنزل القرآن هو الله الذي أحاط علمه بما في السموات والأرض، إنه كان غفورًا لمن تاب من الذنوب والمعاصي، رحيمًا بهم حيث لم يعاجلهم بالعقوبة.", "isBasmala": false, "translation_en": "Say, \"It was revealed by He who knows the Secret in the heavens and the earth. He is always Forgiving and Merciful.\"", "translation_id": "Katakanlah: \"Al Quran itu diturunkan oleh (Allah) yang mengetahui rahasia di langit dan di bumi. Sesungguhnya Dia adalah Maha Pengampun lagi Maha Penyayang\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 7, "text": "وَقَالُوا۟ مَالِ هَـٰذَا ٱلرَّسُولِ یَأۡكُلُ ٱلطَّعَامَ وَیَمۡشِی فِی ٱلۡأَسۡوَاقِ لَوۡلَاۤ أُنزِلَ إِلَیۡهِ مَلَكࣱ فَیَكُونَ مَعَهُۥ نَذِیرًا ۝٧", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "وقال المشركون: ما لهذا الذي يزعم أنه رسول الله (يعنون محمدًا صلى الله عليه وسلم) يأكل الطعام مثلنا، ويمشي في الأسواق لطلب الرزق؟ فهلا أرسل الله معه مَلَكًا يشهد على صدقه، أو يهبط عليه من السماء كنز من مال، أو تكون له حديقة عظيمة يأكل من ثمرها، وقال هؤلاء الظالمون المكذبون: ما تتبعون أيها المؤمنون إلا رجلا به سحر غلب على عقله.", "isBasmala": false, "translation_en": "And they say, \"What sort of messenger is this, who eats food, and walks in the marketplaces? If only an angel was sent down with him, to be alongside him a warner.\"", "translation_id": "Dan mereka berkata: \"Mengapa rasul itu memakan makanan dan berjalan di pasar-pasar? Mengapa tidak diturunkan kepadanya seorang malaikat agar malaikat itu memberikan peringatan bersama-sama dengan dia?,", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 8, "text": "أَوۡ یُلۡقَىٰۤ إِلَیۡهِ كَنزٌ أَوۡ تَكُونُ لَهُۥ جَنَّةࣱ یَأۡكُلُ مِنۡهَاۚ وَقَالَ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلࣰا مَّسۡحُورًا ۝٨", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "وقال المشركون: ما لهذا الذي يزعم أنه رسول الله (يعنون محمدًا صلى الله عليه وسلم) يأكل الطعام مثلنا، ويمشي في الأسواق لطلب الرزق؟ فهلا أرسل الله معه مَلَكًا يشهد على صدقه، أو يهبط عليه من السماء كنز من مال، أو تكون له حديقة عظيمة يأكل من ثمرها، وقال هؤلاء الظالمون المكذبون: ما تتبعون أيها المؤمنون إلا رجلا به سحر غلب على عقله.", "isBasmala": false, "translation_en": "Or, \"If only a treasure was dropped on him.\" Or, \"If only he had a garden from which he eats.\" The evildoers also say, \"You are following but a man under spell.\"", "translation_id": "atau (mengapa tidak) diturunkan kepadanya perbendaharaan, atau (mengapa tidak) ada kebun baginya, yang dia dapat makan dari (hasil)nya?\" Dan orang-orang yang zalim itu berkata: \"Kamu sekalian tidak lain hanyalah mengikuti seorang lelaki yang kena sihir\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 9, "text": "ٱنظُرۡ كَیۡفَ ضَرَبُوا۟ لَكَ ٱلۡأَمۡثَـٰلَ فَضَلُّوا۟ فَلَا یَسۡتَطِیعُونَ سَبِیلࣰا ۝٩", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "انظر - أيها الرسول - كيف قال المكذبون في حقك تلك الأقوال العجيبة التي تشبه -لغرابتها- الأمثال؛ ليتوصلوا إلى تكذيبك؟ فبَعُدوا بذلك عن الحق، فلا يجدون سبيلا إليه؛ ليصححوا ما قالوه فيك من الكذب والافتراء.", "isBasmala": false, "translation_en": "Look how they invent examples for you. They have gone astray, and cannot find a way.", "translation_id": "Perhatikanlah, bagaimana mereka membuat perbandingan-perbandingan tentang kamu, lalu sesatlah mereka, mereka tidak sanggup (mendapatkan) jalan (untuk menentang kerasulanmu).", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 10, "text": "تَبَارَكَ ٱلَّذِیۤ إِن شَاۤءَ جَعَلَ لَكَ خَیۡرࣰا مِّن ذَ ٰلِكَ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ وَیَجۡعَل لَّكَ قُصُورَۢا ۝١٠", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "عَظُمَتْ بركات الله، وكَثُرَتْ خيراته، الذي إن شاء جعل لك - أيها الرسول - خيرًا مما تمنَّوه لك، فجعل لك في الدنيا حدائق كثيرة تتخللها الأنهار، وجعل لك فيها قصورًا عظيمة.", "isBasmala": false, "translation_en": "Blessed is He who, if He wills, can provide you with better than that-gardens beneath which rivers flow-and He will give you palaces.", "translation_id": "Maha Suci (Allah) yang jika Dia menghendaki, niscaya dijadikan-Nya bagimu yang lebih baik dari yang demikian, (yaitu) surga-surga yang mengalir sungai-sungai di bawahnya, dan dijadikan-Nya (pula) untukmu istana-istana.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 11, "text": "بَلۡ كَذَّبُوا۟ بِٱلسَّاعَةِۖ وَأَعۡتَدۡنَا لِمَن كَذَّبَ بِٱلسَّاعَةِ سَعِیرًا ۝١١", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "وما كذبوك؛ لأنك تأكل الطعام، وتمشي في الأسواق، بل كذَّبوا بيوم القيامة وما فيه من جزاء، وأعتدنا لمن كذب بالساعة نارًا حارة تُسَعَّر بهم.", "isBasmala": false, "translation_en": "In fact, they have denied the Hour, and We have prepared for those who deny the Hour a Blaze.", "translation_id": "Bahkan mereka mendustakan hari kiamat. Dan kami menyediakan neraka yang menyala-nyala bagi siapa yang mendustakan hari kiamat.", "manzil": 4, "manzil_display": ""}], "361": [{"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 12, "text": "إِذَا رَأَتۡهُم مِّن مَّكَانِۭ بَعِیدࣲ سَمِعُوا۟ لَهَا تَغَیُّظࣰا وَزَفِیرࣰا ۝١٢", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "إذا رأت النار هؤلاء المكذبين يوم القيامة من مكان بعيد، سمعوا صوت غليانها وزفيرها، من شدة تغيظها منهم.", "isBasmala": false, "translation_en": "When it sees them from a distant place, they will hear it raging and roaring.", "translation_id": "Apabila neraka itu melihat mereka dari tempat yang jauh, mereka mendengar kegeramannya dan suara nyalanya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 13, "text": "وَإِذَاۤ أُلۡقُوا۟ مِنۡهَا مَكَانࣰا ضَیِّقࣰا مُّقَرَّنِینَ دَعَوۡا۟ هُنَالِكَ ثُبُورࣰا ۝١٣", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "وإذا أُلقوا في مكان شديد الضيق من جهنم- وقد قُرِنت أيديهم بالسلاسل إلى أعناقهم- دَعَوْا على أنفسهم بالهلاك للخلاص منها.", "isBasmala": false, "translation_en": "And when they are thrown into it, into a tight place, shackled, they will plead there for death.", "translation_id": "Dan apabila mereka dilemparkan ke tempat yang sempit di neraka itu dengan dibelenggu, mereka di sana mengharapkan kebinasaan.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 14, "text": "لَّا تَدۡعُوا۟ ٱلۡیَوۡمَ ثُبُورࣰا وَ ٰحِدࣰا وَٱدۡعُوا۟ ثُبُورࣰا كَثِیرࣰا ۝١٤", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "فيقال لهم تيئيسًا، لا تَدْعوا اليوم بالهلاك مرة واحدة، بل مرات كثيرة، فلن يزيدكم ذلك إلا غمًّا، فلا خلاص لكم.", "isBasmala": false, "translation_en": "\"Do not plead for one death today, but plead for a great many deaths.\"", "translation_id": "(Akan dikatakan kepada mereka): \"Jangan kamu sekalian mengharapkan satu kebinasaan, melainkan harapkanlah kebinasaan yang banyak\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 15, "text": "قُلۡ أَذَ ٰلِكَ خَیۡرٌ أَمۡ جَنَّةُ ٱلۡخُلۡدِ ٱلَّتِی وُعِدَ ٱلۡمُتَّقُونَۚ كَانَتۡ لَهُمۡ جَزَاۤءࣰ وَمَصِیرࣰا ۝١٥", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "قل لهم - أيها الرسول -: أهذه النار التي وُصِفتْ لكم خيرٌ أم جنة النعيم الدائم التي وُعِد بها الخائفون من عذاب ربهم، كانت لهم ثوابًا على عملهم، ومآلا يرجعون إليه في الآخرة؟", "isBasmala": false, "translation_en": "Say, \"Is this better, or the Garden of Eternity promised to the righteous? It is for them a reward and a destination.", "translation_id": "Katakanlah: \"Apa (azab) yang demikian itukah yang baik, atau surga yang kekal yang telah dijanjikan kepada orang-orang yang bertakwa?\" Dia menjadi balasan dan tempat kembali bagi mereka?\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 16, "text": "لَّهُمۡ فِیهَا مَا یَشَاۤءُونَ خَـٰلِدِینَۚ كَانَ عَلَىٰ رَبِّكَ وَعۡدࣰا مَّسۡـُٔولࣰا ۝١٦", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "لهؤلاء المطيعين في الجنة ما يشتهون من ملاذِّ النعيم، متاعهم فيه دائم، كان دخولهم إياها على ربك - أيها الرسول - وعدًا مسؤولا يسأله عباد الله المتقون، والله لا يخلف وعده.", "isBasmala": false, "translation_en": "They will have therein whatever they desire, forever. That is upon your Lord a binding promise.", "translation_id": "Bagi mereka di dalam surga itu apa yang mereka kehendaki, sedang mereka kekal (di dalamnya). (Hal itu) adalah janji dari Tuhanmu yang patut dimohonkan (kepada-Nya).", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 17, "text": "وَیَوۡمَ یَحۡشُرُهُمۡ وَمَا یَعۡبُدُونَ مِن دُونِ ٱللَّهِ فَیَقُولُ ءَأَنتُمۡ أَضۡلَلۡتُمۡ عِبَادِی هَـٰۤؤُلَاۤءِ أَمۡ هُمۡ ضَلُّوا۟ ٱلسَّبِیلَ ۝١٧", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "ويوم القيامة يحشر الله المشركين وما كانوا يعبدونه من دونه، فيقول لهؤلاء المعبودين: أأنتم أضللتم عبادي هؤلاء عن طريق الحق، وأمرتموهم بعبادتكم، أم هم ضلوا السبيل، فعبدوكم مِن تلقاء أنفسهم؟", "isBasmala": false, "translation_en": "On the Day when He gathers them, and what they worshiped besides God, He will say, \"Was it you who misled these servants of Mine, or was it they who lost the way?\"", "translation_id": "Dan (ingatlah) suatu hari (ketika) Allah menghimpunkan mereka beserta apa yang mereka sembah selain Allah, lalu Allah berkata (kepada yang disembah); \"Apakah kamu yang menyesatkan hamba-hamba-Ku itu, atau mereka sendirikah yang sesat dari jalan (yang benar)?\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 18, "text": "قَالُوا۟ سُبۡحَـٰنَكَ مَا كَانَ یَنۢبَغِی لَنَاۤ أَن نَّتَّخِذَ مِن دُونِكَ مِنۡ أَوۡلِیَاۤءَ وَلَـٰكِن مَّتَّعۡتَهُمۡ وَءَابَاۤءَهُمۡ حَتَّىٰ نَسُوا۟ ٱلذِّكۡرَ وَكَانُوا۟ قَوۡمَۢا بُورࣰا ۝١٨", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "قال المعبودون من دون الله: تنزيهًا لك- يا ربنا- عَمَّا فعل هؤلاء، فما يصحُّ أن نَتَّخِذ سواك أولياء نواليهم، ولكن متعتَ هؤلاء المشركين وآباءهم بالمال والعافية في الدنيا، حتى نسوا ذكرك فأشركوا بك، وكانوا قومًا هلكى غلب عليهم الشقاء والخِذْلان.", "isBasmala": false, "translation_en": "They will say, \"Glory be to You. It was not for us to take any lords besides You. But you gave them enjoyments, and their ancestors, until they forgot the Message, and became ruined people.\"", "translation_id": "Mereka (yang disembah itu) menjawab: \"Maha Suci Engkau, tidaklah patut bagi kami mengambil selain engkau (untuk jadi) pelindung, akan tetapi Engkau telah memberi mereka dan bapak-bapak mereka kenikmatan hidup, sampai mereka lupa mengingati (Engkau); dan mereka adalah kaum yang binasa\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 19, "text": "فَقَدۡ كَذَّبُوكُم بِمَا تَقُولُونَ فَمَا تَسۡتَطِیعُونَ صَرۡفࣰا وَلَا نَصۡرࣰاۚ وَمَن یَظۡلِم مِّنكُمۡ نُذِقۡهُ عَذَابࣰا كَبِیرࣰا ۝١٩", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "فيقال للمشركين: لقد كذَّبكم هؤلاء الذين عبدتموهم في ادِّعائكم عليهم، فها أنتم أولاء لا تستطيعون دَفْعًا للعذاب عن أنفسكم، ولا نصرًا لها، ومَن يشرك بالله فيظلم نفسه ويعبد غير الله، ويمت على ذلك، يعذبه الله عذابًا شديدًا.", "isBasmala": false, "translation_en": "They have denied you because of what you say; so you can neither avert, nor help. Whoever among you commits injustice, We will make him taste a grievous punishment.", "translation_id": "maka sesungguhnya mereka (yang disembah itu) telah mendustakan kamu tentang apa yang kamu katakan maka kamu tidak akan dapat menolak (azab) dan tidak (pula) menolong (dirimu), dan barang siapa di antara kamu yang berbuat zalim, niscaya Kami rasakan kepadanya azab yang besar.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 20, "text": "وَمَاۤ أَرۡسَلۡنَا قَبۡلَكَ مِنَ ٱلۡمُرۡسَلِینَ إِلَّاۤ إِنَّهُمۡ لَیَأۡكُلُونَ ٱلطَّعَامَ وَیَمۡشُونَ فِی ٱلۡأَسۡوَاقِۗ وَجَعَلۡنَا بَعۡضَكُمۡ لِبَعۡضࣲ فِتۡنَةً أَتَصۡبِرُونَۗ وَكَانَ رَبُّكَ بَصِیرࣰا ۝٢٠", "juz": 18, "hizb": "(*¾ ح 36*)", "tafsir": "وما أرسلنا قبلك - أيها الرسول - أحدًا مِن رسلنا إلا كانوا بشرًا، يأكلون الطعام، ويمشون في الأسواق. وجعلنا بعضكم- أيها الناس- لبعض ابتلاء واختبارًا بالهدى والضلال، والغنى والفقر، والصحة والمرض، هل تصبرون، فتقوموا بما أوجبه الله عليكم، وتشكروا له، فيثيبكم مولاكم، أو لا تصبرون فتستحقوا العقوبة؟ وكان ربك - أيها الرسول - بصيرًا بمن يجزع أو يصبر، وبمن يكفر أو يشكر.", "isBasmala": false, "translation_en": "We never sent any messengers before you, but they ate food and walked in the marketplaces. And We made some of you tempters for one another-will you be patient? Your Lord is always Observing.", "translation_id": "Dan Kami tidak mengutus rasul-rasul sebelummu, melainkan mereka sungguh memakan makanan dan berjalan di pasar-pasar. Dan kami jadikan sebahagian kamu cobaan bagi sebahagian yang lain. Maukah kamu bersabar?; dan adalah Tuhanmu maha Melihat.", "manzil": 4, "manzil_display": ""}], "362": [{"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 21, "text": "۞ وَقَالَ ٱلَّذِینَ لَا یَرۡجُونَ لِقَاۤءَنَا لَوۡلَاۤ أُنزِلَ عَلَیۡنَا ٱلۡمَلَـٰۤىِٕكَةُ أَوۡ نَرَىٰ رَبَّنَاۗ لَقَدِ ٱسۡتَكۡبَرُوا۟ فِیۤ أَنفُسِهِمۡ وَعَتَوۡ عُتُوࣰّا كَبِیرࣰا ۝٢١", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وقال الذين لا يؤمِّلون لقاء ربهم بعد موتهم لإنكارهم له: هلا أُنزل علينا الملائكة، فتُخْبِرنا بأن محمدًا صادق، أو نرى ربنا عِيانًا، فيخبرنا بصدقه في رسالته. لقد أُعجِبوا بأنفسهم واستعلَوْا حيث اجترؤوا على هذا القول، وتجاوزوا الحدَّ في طغيانهم وكفرهم.", "isBasmala": false, "translation_en": "Those who do not expect to meet Us say, \"If only the angels were sent down to us, or we could see our Lord.\" They have grown arrogant within themselves, and have become excessively defiant.", "translation_id": "Berkatalah orang-orang yang tidak menanti-nanti pertemuan(nya) dengan Kami: \"Mengapakah tidak diturunkan kepada kita malaikat atau (mengapa) kita (tidak) melihat Tuhan kita?\" Sesungguhnya mereka memandang besar tentang diri mereka dan mereka benar-benar telah melampaui batas(dalam melakukan) kezaliman\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 22, "text": "یَوۡمَ یَرَوۡنَ ٱلۡمَلَـٰۤىِٕكَةَ لَا بُشۡرَىٰ یَوۡمَىِٕذࣲ لِّلۡمُجۡرِمِینَ وَیَقُولُونَ حِجۡرࣰا مَّحۡجُورࣰا ۝٢٢", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "يوم يرون الملائكة عند الاحتضار، وفي القبر، ويوم القيامة، على غير الصورة التي اقترحوها لا لتبشرهم بالجنة، ولكن لتقول لهم: جعل الله الجنة مكانًا محرمًا عليكم.", "isBasmala": false, "translation_en": "On the Day when they see the angels-there will be no good news for sinners on that Day; and they will say, \"A protective refuge.\"", "translation_id": "Pada hari mereka melihat malaikat dihari itu tidak ada kabar gembira bagi orang-orang yang berdosa mereka berkata: \"Hijraan mahjuuraa.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 23, "text": "وَقَدِمۡنَاۤ إِلَىٰ مَا عَمِلُوا۟ مِنۡ عَمَلࣲ فَجَعَلۡنَـٰهُ هَبَاۤءࣰ مَّنثُورًا ۝٢٣", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وقَدِمْنا إلى ما عملوه مِن مظاهر الخير والبر، فجعلناه باطلا مضمحلا لا ينفعهم كالهباء المنثور، وهو ما يُرى في ضوء الشمس من خفيف الغبار؛ وذلك أن العمل لا ينفع في الآخرة إلا إذا توفر في صاحبه: الإيمان بالله، والإخلاص له، والمتابعة لرسوله محمد، صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "We will proceed to the works they did, and will turn them into scattered dust.", "translation_id": "Dan kami hadapi segala amal yang mereka kerjakan, lalu kami jadikan amal itu (bagaikan) debu yang berterbangan.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 24, "text": "أَصۡحَـٰبُ ٱلۡجَنَّةِ یَوۡمَىِٕذٍ خَیۡرࣱ مُّسۡتَقَرࣰّا وَأَحۡسَنُ مَقِیلࣰا ۝٢٤", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "أصحاب الجنة يوم القيامة خير مستقرًا من أهل النار وأحسن منازل في الجنة، فراحتهم تامة، ونعيمهم لا يشوبه كدر.", "isBasmala": false, "translation_en": "The companions of Paradise on that Day will be better lodged, and more fairly accommodated.", "translation_id": "Penghuni-penghuni surga pada hari itu palig baik tempat tinggalnya dan paling indah tempat istirahatnya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 25, "text": "وَیَوۡمَ تَشَقَّقُ ٱلسَّمَاۤءُ بِٱلۡغَمَـٰمِ وَنُزِّلَ ٱلۡمَلَـٰۤىِٕكَةُ تَنزِیلًا ۝٢٥", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "واذكر - أيها الرسول - ذلك اليوم الذي تتشقق فيه السماء، ويظهر من فتحاتها السحاب الأبيض الرقيق، وينزل الله ملائكة السموات يومئذ، فيحيطون بالخلائق في المحشر، ويأتي الله تبارك وتعالى لفصل القضاء بين العباد، إتيانًا يليق بجلاله.", "isBasmala": false, "translation_en": "The Day when the sky is cleft with clouds, and the angels are sent down in streams.", "translation_id": "Dan (ingatlah) hari (ketika) langit pecah belah mengeluarkan kabut putih dan diturunkanlah malaikat bergelombang-gelombang.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 26, "text": "ٱلۡمُلۡكُ یَوۡمَىِٕذٍ ٱلۡحَقُّ لِلرَّحۡمَـٰنِۚ وَكَانَ یَوۡمًا عَلَى ٱلۡكَـٰفِرِینَ عَسِیرࣰا ۝٢٦", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "المُلْك الحق في هذا اليوم للرحمن وحده دون مَن سواه، وكان هذا اليوم صعبًا شديدًا على الكافرين، لما ينالهم من العقاب والعذاب الأليم.", "isBasmala": false, "translation_en": "On that Day, true sovereignty will belong to the Merciful, and it will be a difficult Day for the disbelievers.", "translation_id": "Kerajaan yang hak pada hari itu adalah kepunyaan Tuhan Yang Maha Pemurah. Dan adalah (hari itu), satu hari penuh kesukaran bagi orang-orang kafir.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 27, "text": "وَیَوۡمَ یَعَضُّ ٱلظَّالِمُ عَلَىٰ یَدَیۡهِ یَقُولُ یَـٰلَیۡتَنِی ٱتَّخَذۡتُ مَعَ ٱلرَّسُولِ سَبِیلࣰا ۝٢٧", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "واذكر - أيها الرسول - يوم يَعَضُّ الظالم لنفسه على يديه ندمًا وتحسرًا قائلا يا ليتني صاحبت رسول الله محمدًا صلى الله عليه وسلم واتبعته في اتخاذ الإسلام طريقًا إلى الجنة، ويتحسَّر قائلا يا ليتني لم أتخذ الكافر فلانًا صديقًا أتبعه وأوده. لقد أضلَّني هذا الصديق عن القرآن بعد إذ جاءني. وكان الشيطان الرجيم خذولا للإنسان دائمًا. وفي هذه الآيات التحذير من مصاحبة قرين السوء؛ فإنه قد يكون سببًا لإدخال قرينه النار.", "isBasmala": false, "translation_en": "On that Day, the wrongdoer will bite his hands, and say, \"If only I had followed the way with the Messenger.", "translation_id": "Dan (ingatlah) hari (ketika itu) orang yang zalim menggigit dua tangannya, seraya berkata: \"Aduhai kiranya (dulu) aku mengambil jalan bersama-sama Rasul\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 28, "text": "یَـٰوَیۡلَتَىٰ لَیۡتَنِی لَمۡ أَتَّخِذۡ فُلَانًا خَلِیلࣰا ۝٢٨", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "واذكر - أيها الرسول - يوم يَعَضُّ الظالم لنفسه على يديه ندمًا وتحسرًا قائلا يا ليتني صاحبت رسول الله محمدًا صلى الله عليه وسلم واتبعته في اتخاذ الإسلام طريقًا إلى الجنة، ويتحسَّر قائلا يا ليتني لم أتخذ الكافر فلانًا صديقًا أتبعه وأوده. لقد أضلَّني هذا الصديق عن القرآن بعد إذ جاءني. وكان الشيطان الرجيم خذولا للإنسان دائمًا. وفي هذه الآيات التحذير من مصاحبة قرين السوء؛ فإنه قد يكون سببًا لإدخال قرينه النار.", "isBasmala": false, "translation_en": "Oh, woe to me; I wish I never took so-and-so for a friend.", "translation_id": "Kecelakaan besarlah bagiku; kiranya aku (dulu) tidak menjadikan sifulan itu teman akrab(ku).", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 29, "text": "لَّقَدۡ أَضَلَّنِی عَنِ ٱلذِّكۡرِ بَعۡدَ إِذۡ جَاۤءَنِیۗ وَكَانَ ٱلشَّیۡطَـٰنُ لِلۡإِنسَـٰنِ خَذُولࣰا ۝٢٩", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "واذكر - أيها الرسول - يوم يَعَضُّ الظالم لنفسه على يديه ندمًا وتحسرًا قائلا يا ليتني صاحبت رسول الله محمدًا صلى الله عليه وسلم واتبعته في اتخاذ الإسلام طريقًا إلى الجنة، ويتحسَّر قائلا يا ليتني لم أتخذ الكافر فلانًا صديقًا أتبعه وأوده. لقد أضلَّني هذا الصديق عن القرآن بعد إذ جاءني. وكان الشيطان الرجيم خذولا للإنسان دائمًا. وفي هذه الآيات التحذير من مصاحبة قرين السوء؛ فإنه قد يكون سببًا لإدخال قرينه النار.", "isBasmala": false, "translation_en": "He led me away from the Message after it had come to me; for Satan has always been a betrayer of man.\"", "translation_id": "Sesungguhnya dia telah menyesatkan aku dari Al Quran ketika Al Quran itu telah datang kepadaku. Dan adalah syaitan itu tidak mau menolong manusia.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 30, "text": "وَقَالَ ٱلرَّسُولُ یَـٰرَبِّ إِنَّ قَوۡمِی ٱتَّخَذُوا۟ هَـٰذَا ٱلۡقُرۡءَانَ مَهۡجُورࣰا ۝٣٠", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وقال الرسول شاكيًا ما صنع قومه: يا ربِّ إن قومي تركوا هذا القرآن وهجروه، متمادين في إعراضهم عنه وتَرْكِ تدبُّره والعمل به وتبليغه. وفي الآية تخويف عظيم لمن هجر القرآن فلم يعمل به.", "isBasmala": false, "translation_en": "And the Messenger will say, \"My Lord, my people have abandoned this Quran.\"", "translation_id": "Berkatalah Rasul: \"Ya Tuhanku, sesungguhnya kaumku menjadikan Al Quran itu sesuatu yang tidak diacuhkan\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 31, "text": "وَكَذَ ٰلِكَ جَعَلۡنَا لِكُلِّ نَبِیٍّ عَدُوࣰّا مِّنَ ٱلۡمُجۡرِمِینَۗ وَكَفَىٰ بِرَبِّكَ هَادِیࣰا وَنَصِیرࣰا ۝٣١", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وكما جعلنا لك - أيها الرسول - أعداء من مجرمي قومك، جعلنا لكل نبيٍّ من الأنبياء عدوًا من مجرمي قومه، فاصبر كما صبروا. وكفى بربك هاديًا ومرشدًا ومعينًا يعينك على أعدائك. وفي هذا تسلية لنبيه محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Likewise, to every prophet We assign enemies from among the wicked. But your Lord suffices as a Guide and Savior.", "translation_id": "Dan seperti itulah, telah Kami adakan bagi tiap-tiap nabi, musuh dari orang-orang yang berdosa. Dan cukuplah Tuhanmu menjadi Pemberi petunjuk dan Penolong.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 32, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَوۡلَا نُزِّلَ عَلَیۡهِ ٱلۡقُرۡءَانُ جُمۡلَةࣰ وَ ٰحِدَةࣰۚ كَذَ ٰلِكَ لِنُثَبِّتَ بِهِۦ فُؤَادَكَۖ وَرَتَّلۡنَـٰهُ تَرۡتِیلࣰا ۝٣٢", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وقال الذين كفروا: هلا أنزل القرآن على محمد جملة واحدة كالتوراة والإنجيل والزبور! قال الله سبحانه وتعالى: كذلك أنزلناه مفرقًا؛ لنقوِّي به قلبك وتزداد به طمأنينة، فتعيه وتحمله، وبيَّنَّاه في تثبت ومُهْلَة.", "isBasmala": false, "translation_en": "Those who disbelieve say, \"Why was the Quran not revealed to him at once?\" Thus in order to strengthen your heart thereby, and We revealed it in stages.", "translation_id": "Berkatalah orang-orang yang kafir: \"Mengapa Al Quran itu tidak diturunkan kepadanya sekali turun saja?\"; demikianlah supaya Kami perkuat hatimu dengannya dan Kami membacanya secara tartil (teratur dan benar).", "manzil": 4, "manzil_display": ""}], "363": [{"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 33, "text": "وَلَا یَأۡتُونَكَ بِمَثَلٍ إِلَّا جِئۡنَـٰكَ بِٱلۡحَقِّ وَأَحۡسَنَ تَفۡسِیرًا ۝٣٣", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "ولا يأتيك - أيها الرسول - المشركون بحجة أو شبهة إلا جئناك بالجواب الحق وبأحسن بيان له.", "isBasmala": false, "translation_en": "Whatever argument they come to you with, We provide you with the truth, and a better exposition.", "translation_id": "Tidaklah orang-orang kafir itu datang kepadamu (membawa) sesuatu yang ganjil, melainkan Kami datangkan kepadamu suatu yang benar dan yang paling baik penjelasannya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 34, "text": "ٱلَّذِینَ یُحۡشَرُونَ عَلَىٰ وُجُوهِهِمۡ إِلَىٰ جَهَنَّمَ أُو۟لَـٰۤىِٕكَ شَرࣱّ مَّكَانࣰا وَأَضَلُّ سَبِیلࣰا ۝٣٤", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "أولئك الكفار هم الذين يُسحبون على وجوههم إلى جهنم، وأولئك هم شر الناس منزلة، وأبعدهم طريقًا عن الحق.", "isBasmala": false, "translation_en": "Those who are herded into Hell on their faces-those are in a worse position, and further astray from the way.", "translation_id": "Orang-orang yang dihimpunkan ke neraka Jahannam dengan diseret atas muka-muka mereka, mereka itulah orang yang paling buruk tempatnya dan paling sesat jalannya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 35, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ وَجَعَلۡنَا مَعَهُۥۤ أَخَاهُ هَـٰرُونَ وَزِیرࣰا ۝٣٥", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "ولقد آتينا موسى التوراة، وجعلنا معه أخاه هارون معينًا له، فقلنا لهما: اذهبا إلى فرعون وقومه الذين كذَّبوا بدلائل ربوبيتنا وألوهيتنا، فذهبا إليهم، فدَعَواهم إلى الإيمان بالله وطاعته وعدم الإشراك به، فكذَّبوهما، فأهلكناهم إهلاكًا عظيمًا.", "isBasmala": false, "translation_en": "We gave Moses the Scripture, and appointed his brother Aaron as his assistant.", "translation_id": "Dan sesungguhnya kami telah memberikan Al Kitab (Taurat) kepada Musa dan Kami telah menjadikan Harun saudaranya, menyertai dia sebagai wazir (pembantu).", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 36, "text": "فَقُلۡنَا ٱذۡهَبَاۤ إِلَى ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِنَا فَدَمَّرۡنَـٰهُمۡ تَدۡمِیرࣰا ۝٣٦", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "ولقد آتينا موسى التوراة، وجعلنا معه أخاه هارون معينًا له، فقلنا لهما: اذهبا إلى فرعون وقومه الذين كذَّبوا بدلائل ربوبيتنا وألوهيتنا، فذهبا إليهم، فدَعَواهم إلى الإيمان بالله وطاعته وعدم الإشراك به، فكذَّبوهما، فأهلكناهم إهلاكًا عظيمًا.", "isBasmala": false, "translation_en": "We said, \"Go to the people who rejected Our signs,\" and We destroyed them completely.", "translation_id": "Kemudian Kami berfirman kepada keduanya: \"Pergilah kamu berdua kepada kaum yang mendustakan ayat-ayat Kami\". Maka Kami membinasakan mereka sehancur-hancurnya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 37, "text": "وَقَوۡمَ نُوحࣲ لَّمَّا كَذَّبُوا۟ ٱلرُّسُلَ أَغۡرَقۡنَـٰهُمۡ وَجَعَلۡنَـٰهُمۡ لِلنَّاسِ ءَایَةࣰۖ وَأَعۡتَدۡنَا لِلظَّـٰلِمِینَ عَذَابًا أَلِیمࣰا ۝٣٧", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وأغرقنا قوم نوح بالطوفان حين كذَّبوه. ومن كذب رسولا فقد كذب الرسل جميعًا. وجعلنا إغراقهم للناس عبرة، وجعلنا لهم ولمن سلك سبيلهم في التكذيب يوم القيامة عذابًا موجعًا.", "isBasmala": false, "translation_en": "And the people of Noah: when they rejected the messengers, We drowned them, and made them a lesson for mankind. We have prepared for the wrongdoers a painful retribution.", "translation_id": "Dan (telah Kami binasakan) kaum Nuh tatkala mereka mendustakan rasul-rasul. Kami tenggelamkan mereka dan kami jadikan (cerita) mereka itu pelajaran bagi manusia. Dan Kami telah menyediakan bagi orang-orang zalim azab yang pedih;", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 38, "text": "وَعَادࣰا وَثَمُودَا۟ وَأَصۡحَـٰبَ ٱلرَّسِّ وَقُرُونَۢا بَیۡنَ ذَ ٰلِكَ كَثِیرࣰا ۝٣٨", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وأهلكنا عادًا قوم هود، وثمود قوم صالح، وأصحاب البئر وأممًا كثيرة بين قوم نوح وعاد وثمود وأصحاب الرسِّ، لا يعلمهم إلا الله.", "isBasmala": false, "translation_en": "And Aad, and Thamood, and the inhabitants of Arras, and many generations in between.", "translation_id": "dan (Kami binasakan) kaum 'Aad dan Tsamud dan penduduk Rass dan banyak (lagi) generasi-generasi di antara kaum-kaum tersebut.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 39, "text": "وَكُلࣰّا ضَرَبۡنَا لَهُ ٱلۡأَمۡثَـٰلَۖ وَكُلࣰّا تَبَّرۡنَا تَتۡبِیرࣰا ۝٣٩", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وكل الأمم بيَّنَّا لهم الحجج، ووضَّحنا لهم الأدلة، وأزحنا الأعذار عنهم، ومع ذلك لم يؤمنوا، فأهلكناهم بالعذاب إهلاكًا.", "isBasmala": false, "translation_en": "To each We presented the parables; and each We devastated utterly.", "translation_id": "Dan Kami jadikan bagi masing-masing mereka perumpamaan dan masing-masing mereka itu benar benar telah Kami binasakan dengan sehancur-hancurnya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 40, "text": "وَلَقَدۡ أَتَوۡا۟ عَلَى ٱلۡقَرۡیَةِ ٱلَّتِیۤ أُمۡطِرَتۡ مَطَرَ ٱلسَّوۡءِۚ أَفَلَمۡ یَكُونُوا۟ یَرَوۡنَهَاۚ بَلۡ كَانُوا۟ لَا یَرۡجُونَ نُشُورࣰا ۝٤٠", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "ولقد كان مشركو \"مكة\" يمرون في أسفارهم على قرية قوم لوط، وهي قرية \"سدوم\" التي أُهلِكت بالحجارة من السماء، فلم يعتبروا بها، بل كانوا لا يرجون معادًا يوم القيامة يجازون فيه.", "isBasmala": false, "translation_en": "And they came upon the city that was drenched by the terrible rain. Did they not see it? But they do not expect resurrection.", "translation_id": "Dan sesungguhnya mereka (kaum musyrik Mekah) telah melalui sebuah negeri (Sadum) yang (dulu) dihujani dengan hujan yang sejelek-jeleknya (hujan batu). Maka apakah mereka tidak menyaksikan runtuhan itu; bahkan adalah mereka itu tidak mengharapkan akan kebangkitan.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 41, "text": "وَإِذَا رَأَوۡكَ إِن یَتَّخِذُونَكَ إِلَّا هُزُوًا أَهَـٰذَا ٱلَّذِی بَعَثَ ٱللَّهُ رَسُولًا ۝٤١", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وإذا رآك هؤلاء المكذبون - أيها الرسول - استهزؤوا بك قائلين: أهذا الذي يزعم أن الله بعثه رسولا إلينا؟ إنه قارب أن يصرفنا عن عبادة أصنامنا بقوة حجته وبيانه، لولا أن ثَبَتْنا على عبادتها، وسوف يعلمون حين يرون ما يستحقون من العذاب: مَن أضل دينًا أهم أم محمد؟", "isBasmala": false, "translation_en": "And when they see you, they take you for nothing but mockery: \"Is this the one God sent as a messenger?\"", "translation_id": "Dan apabila mereka melihat kamu (Muhammad), mereka hanyalah menjadikan kamu sebagai ejekan (dengan mengatakan): \"Inikah orangnya yang di utus Allah sebagai Rasul?.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 42, "text": "إِن كَادَ لَیُضِلُّنَا عَنۡ ءَالِهَتِنَا لَوۡلَاۤ أَن صَبَرۡنَا عَلَیۡهَاۚ وَسَوۡفَ یَعۡلَمُونَ حِینَ یَرَوۡنَ ٱلۡعَذَابَ مَنۡ أَضَلُّ سَبِیلًا ۝٤٢", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وإذا رآك هؤلاء المكذبون - أيها الرسول - استهزؤوا بك قائلين: أهذا الذي يزعم أن الله بعثه رسولا إلينا؟ إنه قارب أن يصرفنا عن عبادة أصنامنا بقوة حجته وبيانه، لولا أن ثَبَتْنا على عبادتها، وسوف يعلمون حين يرون ما يستحقون من العذاب: مَن أضل دينًا أهم أم محمد؟", "isBasmala": false, "translation_en": "\"He nearly led us away from our gods, had we not patiently adhered to them.\" But they will know, when they witness the torment, who is further away from the way.", "translation_id": "Sesungguhnya hampirlah ia menyesatkan kita dari sembahan-sembahan kita, seandainya kita tidak sabar(menyembah)nya\" dan mereka kelak akan mengetahui di saat mereka melihat azab, siapa yang paling sesat jalannya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 43, "text": "أَرَءَیۡتَ مَنِ ٱتَّخَذَ إِلَـٰهَهُۥ هَوَىٰهُ أَفَأَنتَ تَكُونُ عَلَیۡهِ وَكِیلًا ۝٤٣", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "انظر - أيها الرسول - متعجبًا إلى مَن أطاع هواه كطاعة الله، أفأنت تكون عليه حفيظًا حتى تردَّه إلى الإيمان؟", "isBasmala": false, "translation_en": "Have you seen him who chose his desire as his god? Would you be an agent for him?", "translation_id": "Terangkanlah kepadaku tentang orang yang menjadikan hawa nafsunya sebagai tuhannya. Maka apakah kamu dapat menjadi pemelihara atasnya?,", "manzil": 4, "manzil_display": ""}], "364": [{"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 44, "text": "أَمۡ تَحۡسَبُ أَنَّ أَكۡثَرَهُمۡ یَسۡمَعُونَ أَوۡ یَعۡقِلُونَۚ إِنۡ هُمۡ إِلَّا كَٱلۡأَنۡعَـٰمِ بَلۡ هُمۡ أَضَلُّ سَبِیلًا ۝٤٤", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "أم تظن أن أكثرهم يسمعون آيات الله سماع تدبر، أو يفهمون ما فيها؟ ما هم إلا كالبهائم في عدم الانتفاع بما يسمعونه، بل هم أضل طريقًا منها.", "isBasmala": false, "translation_en": "Or do you assume that most of them hear or understand? They are just like cattle, but even more errant in their way.", "translation_id": "atau apakah kamu mengira bahwa kebanyakan mereka itu mendengar atau memahami. Mereka itu tidak lain, hanyalah seperti binatang ternak, bahkan mereka lebih sesat jalannya (dari binatang ternak itu).", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 45, "text": "أَلَمۡ تَرَ إِلَىٰ رَبِّكَ كَیۡفَ مَدَّ ٱلظِّلَّ وَلَوۡ شَاۤءَ لَجَعَلَهُۥ سَاكِنࣰا ثُمَّ جَعَلۡنَا ٱلشَّمۡسَ عَلَیۡهِ دَلِیلࣰا ۝٤٥", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "ألم تر كيف مدَّ الله الظل من طلوع الفجر إلى طلوع الشمس؟ ولو شاء لجعله ثابتًا مستقرًا لا تزيله الشمس، ثم جعلنا الشمس علامة يُستَدَلُّ بأحوالها على أحواله، ثم تَقَلَّصَ الظل يسيرًا يسيرًا، فكلما ازداد ارتفاع الشمس ازداد نقصانه. وذلك من الأدلة على قدرة الله وعظمته، وأنه وحده المستحق للعبادة دون سواه.", "isBasmala": false, "translation_en": "Do you not see how your Lord extends the shadow? Had He willed, He could have made it still. And We made the sun a pointer to it.", "translation_id": "Apakah kamu tidak memperhatikan (penciptaan) Tuhanmu, bagaimana Dia memanjangkan (dan memendekkan) bayang-bayang dan kalau Dia menghendaki niscaya Dia menjadikan tetap bayang-bayang itu, kemudian Kami jadikan matahari sebagai petunjuk atas bayang-bayang itu,", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 46, "text": "ثُمَّ قَبَضۡنَـٰهُ إِلَیۡنَا قَبۡضࣰا یَسِیرࣰا ۝٤٦", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "ألم تر كيف مدَّ الله الظل من طلوع الفجر إلى طلوع الشمس؟ ولو شاء لجعله ثابتًا مستقرًا لا تزيله الشمس، ثم جعلنا الشمس علامة يُستَدَلُّ بأحوالها على أحواله، ثم تَقَلَّصَ الظل يسيرًا يسيرًا، فكلما ازداد ارتفاع الشمس ازداد نقصانه. وذلك من الأدلة على قدرة الله وعظمته، وأنه وحده المستحق للعبادة دون سواه.", "isBasmala": false, "translation_en": "Then We withdraw it towards Us gradually.", "translation_id": "kemudian Kami menarik bayang-bayang itu kepada kami dengan tarikan yang perlahan-lahan.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 47, "text": "وَهُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلَّیۡلَ لِبَاسࣰا وَٱلنَّوۡمَ سُبَاتࣰا وَجَعَلَ ٱلنَّهَارَ نُشُورࣰا ۝٤٧", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "والله تعالى هو الذي جعل لكم الليل ساترًا لكم بظلامه كما يستركم اللباس، وجعل النوم راحة لأبدانكم، وجعل لكم النهار؛ لتنتشروا في الأرض، وتطلبوا معايشكم.", "isBasmala": false, "translation_en": "And it is He who made the night a covering for you, and sleep for rest; and He made the day a revival.", "translation_id": "Dialah yang menjadikan untukmu malam (sebagai) pakaian, dan tidur untuk istirahat, dan Dia menjadikan siang untuk bangun berusaha.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 48, "text": "وَهُوَ ٱلَّذِیۤ أَرۡسَلَ ٱلرِّیَـٰحَ بُشۡرَۢا بَیۡنَ یَدَیۡ رَحۡمَتِهِۦۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ طَهُورࣰا ۝٤٨", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وهو الذي أرسل الرياح التي تحمل السحاب، تبشر الناس بالمطر رحمة منه، وأنزلنا من السماء ماء يُتَطَهَّر به؛ لنخرج به النبات في مكان لا نبات فيه، فيحيا البلد الجدب بعد موات، ونُسْقي ذلك الماء مِن خَلْقِنا كثيرًا من الأنعام والناس.", "isBasmala": false, "translation_en": "And it is He who sends the winds, bringing advance news of His mercy; and We send down from the sky pure water.", "translation_id": "Dialah yang meniupkan angin (sebagai) pembawa kabar gembira dekat sebelum kedatangan rahmat-nya (hujan); dan Kami turunkan dari langit air yang amat bersih,", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 49, "text": "لِّنُحۡـِۧیَ بِهِۦ بَلۡدَةࣰ مَّیۡتࣰا وَنُسۡقِیَهُۥ مِمَّا خَلَقۡنَاۤ أَنۡعَـٰمࣰا وَأَنَاسِیَّ كَثِیرࣰا ۝٤٩", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "وهو الذي أرسل الرياح التي تحمل السحاب، تبشر الناس بالمطر رحمة منه، وأنزلنا من السماء ماء يُتَطَهَّر به؛ لنخرج به النبات في مكان لا نبات فيه، فيحيا البلد الجدب بعد موات، ونُسْقي ذلك الماء مِن خَلْقِنا كثيرًا من الأنعام والناس.", "isBasmala": false, "translation_en": "To revive dead lands thereby, and to provide drink for the multitude of animals and humans We created.", "translation_id": "agar Kami menghidupkan dengan air itu negeri (tanah) yang mati, dan agar Kami memberi minum dengan air itu sebagian besar dari makhluk Kami, binatang-binatang ternak dan manusia yang banyak.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 50, "text": "وَلَقَدۡ صَرَّفۡنَـٰهُ بَیۡنَهُمۡ لِیَذَّكَّرُوا۟ فَأَبَىٰۤ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورࣰا ۝٥٠", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "ولقد أنزلنا المطر على أرض دون أخرى؛ ليذكر الذين أنزلنا عليهم المطر نعمة الله عليهم، فيشكروا له، وليذكر الذين مُنعوا منه، فيسارعوا بالتوبة إلى الله - جل وعلا- ليرحمهم ويسقيهم، فأبى أكثر الناس إلا جحودًا لنعمنا عليهم، كقولهم: مطرنا بنَوْء كذا وكذا.", "isBasmala": false, "translation_en": "We have circulated it among them, that they may reflect, but most people persist in thanklessness.", "translation_id": "Dan sesungguhnya Kami telah mempergilirkan hujan itu diantara manusia supaya mereka mengambil pelajaran (dari padanya); maka kebanyakan manusia itu tidak mau kecuali mengingkari (nikmat).", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 51, "text": "وَلَوۡ شِئۡنَا لَبَعَثۡنَا فِی كُلِّ قَرۡیَةࣲ نَّذِیرࣰا ۝٥١", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "ولو شئنا لبعثنا في كل قرية نذيرًا، يدعوهم إلى الله عز وجل، وينذرهم عذابه، ولكنا جعلناك - أيها الرسول - مبعوثًا إلى جميع أهل الأرض، وأمرناك أن تبلغهم هذا القرآن، فلا تطع الكافرين في ترك شيء مما أرسلتَ به، بل ابذل جهدك في تبليغ الرسالة، وجاهد الكافرين بهذا القرآن جهادًا كبيرًا، لا يخالطه فتور.", "isBasmala": false, "translation_en": "Had We willed, We could have sent to every town a warner.", "translation_id": "Dan andaikata Kami menghendaki benar-benarlah Kami utus pada tiap-tiap negeri seorang yang memberi peringatan (rasul).", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 52, "text": "فَلَا تُطِعِ ٱلۡكَـٰفِرِینَ وَجَـٰهِدۡهُم بِهِۦ جِهَادࣰا كَبِیرࣰا ۝٥٢", "juz": 19, "hizb": "(* ح 37*)", "tafsir": "ولو شئنا لبعثنا في كل قرية نذيرًا، يدعوهم إلى الله عز وجل، وينذرهم عذابه، ولكنا جعلناك - أيها الرسول - مبعوثًا إلى جميع أهل الأرض، وأمرناك أن تبلغهم هذا القرآن، فلا تطع الكافرين في ترك شيء مما أرسلتَ به، بل ابذل جهدك في تبليغ الرسالة، وجاهد الكافرين بهذا القرآن جهادًا كبيرًا، لا يخالطه فتور.", "isBasmala": false, "translation_en": "So do not obey the disbelievers, but strive against them with it, a mighty struggle.", "translation_id": "Maka janganlah kamu mengikuti orang-orang kafir, dan berjihadlah terhadap mereka dengan Al Quran dengan jihad yang besar.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 53, "text": "۞ وَهُوَ ٱلَّذِی مَرَجَ ٱلۡبَحۡرَیۡنِ هَـٰذَا عَذۡبࣱ فُرَاتࣱ وَهَـٰذَا مِلۡحٌ أُجَاجࣱ وَجَعَلَ بَیۡنَهُمَا بَرۡزَخࣰا وَحِجۡرࣰا مَّحۡجُورࣰا ۝٥٣", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والله هو الذي خلط البحرين: العذب السائغ الشراب، والملح الشديد الملوحة، وجعل بينهما حاجزًا يمنع كل واحدٍ منهما من إفساد الآخر، ومانعًا مِن أن يصل أحدهما إلى الآخر.", "isBasmala": false, "translation_en": "And it is He who merged the two seas; this one fresh and sweet, and that one salty and bitter; and He placed between them a barrier, and an impassable boundary.", "translation_id": "Dan Dialah yang membiarkan dua laut yang mengalir (berdampingan); yang ini tawar lagi segar dan yang lain asin lagi pahit; dan Dia jadikan antara keduanya dinding dan batas yang menghalangi.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 54, "text": "وَهُوَ ٱلَّذِی خَلَقَ مِنَ ٱلۡمَاۤءِ بَشَرࣰا فَجَعَلَهُۥ نَسَبࣰا وَصِهۡرࣰاۗ وَكَانَ رَبُّكَ قَدِیرࣰا ۝٥٤", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "وهو الذي خلق مِن منيِّ الرجل والمرأة ذرية ذكورًا وإناثًا، فنشأ من هذا قرابة النسب وقرابة المصاهرة. وكان ربك قديرًا على خلق ما يشاء.", "isBasmala": false, "translation_en": "And it is He who, from fluid, created the human being. Then He made relationships through marriage and mating. Your Lord is Omnipotent.", "translation_id": "Dan Dia (pula) yang menciptakan manusia dari air lalu dia jadikan manusia itu (punya) keturunan dan mushaharah dan adalah Tuhanmu Maha Kuasa.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 55, "text": "وَیَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا یَنفَعُهُمۡ وَلَا یَضُرُّهُمۡۗ وَكَانَ ٱلۡكَافِرُ عَلَىٰ رَبِّهِۦ ظَهِیرࣰا ۝٥٥", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "ومع كل هذه الدلائل على قدرة الله وإنعامه على خلقه يَعبدُ الكفار مِن دون الله ما لا ينفعهم إن عبدوه، ولا يضرهم إن تركوا عبادته، وكان الكافر عونًا للشيطان على ربه بالشرك في عبادة الله، مُظَاهِرًا له على معصيته.", "isBasmala": false, "translation_en": "And yet, instead of God, they serve what neither profits them nor harms them. The disbeliever has always turned his back on his Lord.", "translation_id": "Dan mereka menyembah selain Allah apa yang tidak memberi manfaat kepada mereka dan tidak (pula) memberi mudharat kepada mereka. Adalah orang-orang kafir itu penolong (syaitan untuk berbuat durhaka) terhadap Tuhannya.", "manzil": 4, "manzil_display": ""}], "365": [{"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 56, "text": "وَمَاۤ أَرۡسَلۡنَـٰكَ إِلَّا مُبَشِّرࣰا وَنَذِیرࣰا ۝٥٦", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "وما أرسلناك - أيها الرسول - إلا مبشرًا للمؤمنين بالجنة ومنذرًا للكافرين بالنار.", "isBasmala": false, "translation_en": "We sent you only as a herald of good news and a warner.", "translation_id": "Dan tidaklah Kami mengutus kamu melainkan hanya sebagai pembawa kabar gembira dan pemberi peringatan.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 57, "text": "قُلۡ مَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍ إِلَّا مَن شَاۤءَ أَن یَتَّخِذَ إِلَىٰ رَبِّهِۦ سَبِیلࣰا ۝٥٧", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "قل لهم: لا أطلب منكم على تبليغ الرسالة أيَّ أجر، لكنْ من أراد أن يهتدي ويسلك سبيل الحق إلى ربه وينفق في مرضاته، فلست أُجبركم عليه، وإنما هو خير لأنفسكم.", "isBasmala": false, "translation_en": "Say, \"I ask of you no payment for this-only that whoever wills may take a path to his Lord.\"", "translation_id": "Katakanlah: \"Aku tidak meminta upah sedikitpun kepada kamu dalam menyampaikan risalah itu, melainkan (mengharapkan kepatuhan) orang-orang yang mau mengambil jalan kepada Tuhan nya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 58, "text": "وَتَوَكَّلۡ عَلَى ٱلۡحَیِّ ٱلَّذِی لَا یَمُوتُ وَسَبِّحۡ بِحَمۡدِهِۦۚ وَكَفَىٰ بِهِۦ بِذُنُوبِ عِبَادِهِۦ خَبِیرًا ۝٥٨", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "وتوكل على الله الذي له جميع معاني الحياة الكاملة كما يليق بجلاله الذي لا يموت، ونزِّهه عن صفات النقصان. وكفى بالله خبيرًا بذنوب خلقه، لا يخفى عليه شيء منها، وسيحاسبهم عليها ويجازيهم بها.", "isBasmala": false, "translation_en": "And put your trust in the Living, the One who never dies; and celebrate His praise. He suffices as the All-Informed Knower of the faults of His creatures.", "translation_id": "Dan bertawakkallah kepada Allah yang hidup (kekal) Yang tidak mati, dan bertasbihlah dengan memuji-Nya. Dan cukuplah Dia Maha Mengetahui dosa-dosa hamba-hamba-Nya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 59, "text": "ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ ٱلرَّحۡمَـٰنُ فَسۡـَٔلۡ بِهِۦ خَبِیرࣰا ۝٥٩", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "الذي خلق السموات والأرض وما بينهما في ستة أيام، ثم استوى على العرش- أي علا وارتفع- استواءً يليق بجلاله، هو الرحمن، فاسأل - أيها النبي - به خبيرًا، يعني بذلك سبحانه نفسه الكريمة، فهو الذي يعلم صفاته وعظمته وجلاله. ولا أحد من البشر أعلم بالله ولا أخبر به من عبده ورسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "He who created the heavens and the earth and everything between them in six days, then settled on the Throne. The Most Merciful. Ask about Him a well-informed.", "translation_id": "Yang menciptakan langit dan bumi dan apa yang ada antara keduanya dalam enam masa, kemudian dia bersemayam di atas 'Arsy, (Dialah) Yang Maha Pemurah, maka tanyakanlah (tentang Allah) kepada yang lebih mengetahui (Muhammad) tentang Dia.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 60, "text": "وَإِذَا قِیلَ لَهُمُ ٱ̅سۡ̅جُ̅دُ̅و̅ا۟̅ لِلرَّحۡمَـٰنِ قَالُوا۟ وَمَا ٱلرَّحۡمَـٰنُ أَنَسۡجُدُ لِمَا تَأۡمُرُنَا وَزَادَهُمۡ نُفُورࣰا ۝٦٠ ۩", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "وإذا قيل للكافرين: اسجدوا للرحمن واعبدوه قالوا: ما نعرف الرحمن، أنسجد لما تأمرنا بالسجود له طاعة لأمرك؟ وزادهم دعاؤهم إلى السجود للرحمن بُعْداً عن الإيمان ونفورًا منه.", "isBasmala": false, "translation_en": "And when it is said to them, \"Bow down to the Merciful,\" they say, \"And what is the Merciful? Are we to bow down to whatever you command us?\" And it increases their aversion.", "translation_id": "Dan apabila dikatakan kepada mereka: \"Sujudlah kamu sekalian kepada yang Maha Penyayang\", mereka menjawab: \"Siapakah yang Maha Penyayang itu? Apakah kami akan sujud kepada Tuhan Yang kamu perintahkan kami(bersujud kepada-Nya)?\", dan (perintah sujud itu) menambah mereka jauh (dari iman).", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 61, "text": "تَبَارَكَ ٱلَّذِی جَعَلَ فِی ٱلسَّمَاۤءِ بُرُوجࣰا وَجَعَلَ فِیهَا سِرَ ٰجࣰا وَقَمَرࣰا مُّنِیرࣰا ۝٦١", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "عَظُمَتْ بركات الرحمن وكثر خيره، الذي جعل في السماء النجوم الكبار بمنازلها، وجعل فيها شمسًا تضيء وقمرًا ينير.", "isBasmala": false, "translation_en": "Blessed is He who placed constellations in the sky, and placed in it a lamp, and an illuminating moon.", "translation_id": "Maha Suci Allah yang menjadikan di langit gugusan-gugusan bintang dan Dia menjadikan juga padanya matahari dan bulan yang bercahaya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 62, "text": "وَهُوَ ٱلَّذِی جَعَلَ ٱلَّیۡلَ وَٱلنَّهَارَ خِلۡفَةࣰ لِّمَنۡ أَرَادَ أَن یَذَّكَّرَ أَوۡ أَرَادَ شُكُورࣰا ۝٦٢", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "وهو الذي جعل الليل والنهار متعاقبَيْن يَخْلُف أحدهما الآخر لمن أراد أن يعتبر بما في ذلك إيمانًا بالمدبِّر الخالق، أو أراد أن يشكر لله تعالى على نعمه وآلائه.", "isBasmala": false, "translation_en": "And it is He who made the night and the day alternate-for whoever desires to reflect, or desires to show gratitude.", "translation_id": "Dan Dia (pula) yang menjadikan malam dan siang silih berganti bagi orang yang ingin mengambil pelajaran atau orang yang ingin bersyukur.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 63, "text": "وَعِبَادُ ٱلرَّحۡمَـٰنِ ٱلَّذِینَ یَمۡشُونَ عَلَى ٱلۡأَرۡضِ هَوۡنࣰا وَإِذَا خَاطَبَهُمُ ٱلۡجَـٰهِلُونَ قَالُوا۟ سَلَـٰمࣰا ۝٦٣", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "وعباد الرحمن الصالحون يمشون على الأرض بسكينة متواضعين، وإذا خاطبهم الجهلة السفهاء بالأذى أجابوهم بالمعروف من القول، وخاطبوهم خطابًا يَسْلَمون فيه من الإثم، ومن مقابلة الجاهل بجهله.", "isBasmala": false, "translation_en": "The servants of the Merciful are those who walk the earth in humility, and when the ignorant address them, they say, \"Peace.\"", "translation_id": "Dan hamba-hamba Tuhan yang Maha Penyayang itu (ialah) orang-orang yang berjalan di atas bumi dengan rendah hati dan apabila orang-orang jahil menyapa mereka, mereka mengucapkan kata-kata (yang mengandung) keselamatan.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 64, "text": "وَٱلَّذِینَ یَبِیتُونَ لِرَبِّهِمۡ سُجَّدࣰا وَقِیَـٰمࣰا ۝٦٤", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين يكثرون من صلاة الليل مخلصين فيها لربهم، متذللين له بالسجود والقيام.", "isBasmala": false, "translation_en": "And those who pass the night prostrating themselves to their Lord and standing up.", "translation_id": "Dan orang yang melalui malam hari dengan bersujud dan berdiri untuk Tuhan mereka.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 65, "text": "وَٱلَّذِینَ یَقُولُونَ رَبَّنَا ٱصۡرِفۡ عَنَّا عَذَابَ جَهَنَّمَۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا ۝٦٥", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين هم مع اجتهادهم في العبادة يخافون الله فيدعونه أن ينجيهم من عذاب جهنم، إن عذابها يلازم صاحبه. إن جهنم شر قرار وإقامة.", "isBasmala": false, "translation_en": "And those who say, ''Our Lord, avert from us the suffering of Hell, for its suffering is continuous.", "translation_id": "Dan orang-orang yang berkata: \"Ya Tuhan kami, jauhkan azab jahannam dari kami, sesungguhnya azabnya itu adalah kebinasaan yang kekal\".", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 66, "text": "إِنَّهَا سَاۤءَتۡ مُسۡتَقَرࣰّا وَمُقَامࣰا ۝٦٦", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين هم مع اجتهادهم في العبادة يخافون الله فيدعونه أن ينجيهم من عذاب جهنم، إن عذابها يلازم صاحبه. إن جهنم شر قرار وإقامة.", "isBasmala": false, "translation_en": "It is indeed a miserable residence and destination.\"", "translation_id": "Sesungguhnya jahannam itu seburuk-buruk tempat menetap dan tempat kediaman.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 67, "text": "وَٱلَّذِینَ إِذَاۤ أَنفَقُوا۟ لَمۡ یُسۡرِفُوا۟ وَلَمۡ یَقۡتُرُوا۟ وَكَانَ بَیۡنَ ذَ ٰلِكَ قَوَامࣰا ۝٦٧", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين إذا أنفقوا من أموالهم لم يتجاوزوا الحد في العطاء، ولم يضيِّقوا في النفقة، وكان إنفاقهم وسطًا بين التبذير والتضييق.", "isBasmala": false, "translation_en": "And those who, when they spend, are neither wasteful nor stingy, but choose a middle course between that.", "translation_id": "Dan orang-orang yang apabila membelanjakan (harta), mereka tidak berlebihan, dan tidak (pula) kikir, dan adalah (pembelanjaan itu) di tengah-tengah antara yang demikian.", "manzil": 4, "manzil_display": ""}], "366": [{"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 68, "text": "وَٱلَّذِینَ لَا یَدۡعُونَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ وَلَا یَقۡتُلُونَ ٱلنَّفۡسَ ٱلَّتِی حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّ وَلَا یَزۡنُونَۚ وَمَن یَفۡعَلۡ ذَ ٰلِكَ یَلۡقَ أَثَامࣰا ۝٦٨", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين يوحدون الله، ولا يدعون ولا يعبدون إلهًا غيره، ولا يقتلون النفس التي حرَّم الله قتلها إلا بما يحق قتلها به: من كفر بعد إيمان، أو زنى بعد زواج، أو قتل نفس عدوانًا، ولا يزنون، بل يحفظون فروجهم، إلا على أزواجهم أو ما ملكت أيمانهم، ومن يفعل شيئًا من هذه الكبائر يَلْقَ في الآخرة عقابًا. يُضاعَفْ له العذاب يوم القيامة، ويَخْلُدْ فيه ذليلا حقيرًا. (والوعيد بالخلود لمن فعلها كلَّها، أو لمن أشرك بالله). لكن مَن تاب مِن هذه الذنوب توبة نصوحًا وآمن إيمانًا جازمًا مقرونًا بالعمل الصالح، فأولئك يمحو الله عنهم سيئاتهم ويجعل مكانها حسنات؛ بسبب توبتهم وندمهم. وكان الله غفورًا لمن تاب، رحيمًا بعباده حيث دعاهم إلى التوبة بعد مبارزته بأكبر المعاصي. ومن تاب عمَّا ارتكب من الذنوب، وعمل عملا صالحا فإنه بذلك يرجع إلى الله رجوعًا صحيحًا، فيقبل الله توبته ويكفر ذنوبه.", "isBasmala": false, "translation_en": "And those who do not implore besides God any other god, and do not kill the soul which God has made sacred-except in the pursuit of justice-and do not commit adultery. Whoever does that will face penalties.", "translation_id": "Dan orang-orang yang tidak menyembah tuhan yang lain beserta Allah dan tidak membunuh jiwa yang diharamkan Allah (membunuhnya) kecuali dengan (alasan) yang benar, dan tidak berzina, barang siapa yang melakukan yang demikian itu, niscaya dia mendapat (pembalasan) dosa(nya),", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 69, "text": "یُضَـٰعَفۡ لَهُ ٱلۡعَذَابُ یَوۡمَ ٱلۡقِیَـٰمَةِ وَیَخۡلُدۡ فِیهِۦ مُهَانًا ۝٦٩", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين يوحدون الله، ولا يدعون ولا يعبدون إلهًا غيره، ولا يقتلون النفس التي حرَّم الله قتلها إلا بما يحق قتلها به: من كفر بعد إيمان، أو زنى بعد زواج، أو قتل نفس عدوانًا، ولا يزنون، بل يحفظون فروجهم، إلا على أزواجهم أو ما ملكت أيمانهم، ومن يفعل شيئًا من هذه الكبائر يَلْقَ في الآخرة عقابًا. يُضاعَفْ له العذاب يوم القيامة، ويَخْلُدْ فيه ذليلا حقيرًا. (والوعيد بالخلود لمن فعلها كلَّها، أو لمن أشرك بالله). لكن مَن تاب مِن هذه الذنوب توبة نصوحًا وآمن إيمانًا جازمًا مقرونًا بالعمل الصالح، فأولئك يمحو الله عنهم سيئاتهم ويجعل مكانها حسنات؛ بسبب توبتهم وندمهم. وكان الله غفورًا لمن تاب، رحيمًا بعباده حيث دعاهم إلى التوبة بعد مبارزته بأكبر المعاصي. ومن تاب عمَّا ارتكب من الذنوب، وعمل عملا صالحا فإنه بذلك يرجع إلى الله رجوعًا صحيحًا، فيقبل الله توبته ويكفر ذنوبه.", "isBasmala": false, "translation_en": "The punishment will be doubled for him on the Day of Resurrection, and he will dwell therein in humiliation forever.", "translation_id": "(yakni) akan dilipat gandakan azab untuknya pada hari kiamat dan dia akan kekal dalam azab itu, dalam keadaan terhina,", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 70, "text": "إِلَّا مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلࣰا صَـٰلِحࣰا فَأُو۟لَـٰۤىِٕكَ یُبَدِّلُ ٱللَّهُ سَیِّـَٔاتِهِمۡ حَسَنَـٰتࣲۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا ۝٧٠", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين يوحدون الله، ولا يدعون ولا يعبدون إلهًا غيره، ولا يقتلون النفس التي حرَّم الله قتلها إلا بما يحق قتلها به: من كفر بعد إيمان، أو زنى بعد زواج، أو قتل نفس عدوانًا، ولا يزنون، بل يحفظون فروجهم، إلا على أزواجهم أو ما ملكت أيمانهم، ومن يفعل شيئًا من هذه الكبائر يَلْقَ في الآخرة عقابًا. يُضاعَفْ له العذاب يوم القيامة، ويَخْلُدْ فيه ذليلا حقيرًا. (والوعيد بالخلود لمن فعلها كلَّها، أو لمن أشرك بالله). لكن مَن تاب مِن هذه الذنوب توبة نصوحًا وآمن إيمانًا جازمًا مقرونًا بالعمل الصالح، فأولئك يمحو الله عنهم سيئاتهم ويجعل مكانها حسنات؛ بسبب توبتهم وندمهم. وكان الله غفورًا لمن تاب، رحيمًا بعباده حيث دعاهم إلى التوبة بعد مبارزته بأكبر المعاصي. ومن تاب عمَّا ارتكب من الذنوب، وعمل عملا صالحا فإنه بذلك يرجع إلى الله رجوعًا صحيحًا، فيقبل الله توبته ويكفر ذنوبه.", "isBasmala": false, "translation_en": "Except for those who repent, and believe, and do good deeds. These-God will replace their bad deeds with good deeds. God is ever Forgiving and Merciful.", "translation_id": "kecuali orang-orang yang bertaubat, beriman dan mengerjakan amal saleh; maka itu kejahatan mereka diganti Allah dengan kebajikan. Dan adalah Allah maha Pengampun lagi Maha Penyayang.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 71, "text": "وَمَن تَابَ وَعَمِلَ صَـٰلِحࣰا فَإِنَّهُۥ یَتُوبُ إِلَى ٱللَّهِ مَتَابࣰا ۝٧١", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين يوحدون الله، ولا يدعون ولا يعبدون إلهًا غيره، ولا يقتلون النفس التي حرَّم الله قتلها إلا بما يحق قتلها به: من كفر بعد إيمان، أو زنى بعد زواج، أو قتل نفس عدوانًا، ولا يزنون، بل يحفظون فروجهم، إلا على أزواجهم أو ما ملكت أيمانهم، ومن يفعل شيئًا من هذه الكبائر يَلْقَ في الآخرة عقابًا. يُضاعَفْ له العذاب يوم القيامة، ويَخْلُدْ فيه ذليلا حقيرًا. (والوعيد بالخلود لمن فعلها كلَّها، أو لمن أشرك بالله). لكن مَن تاب مِن هذه الذنوب توبة نصوحًا وآمن إيمانًا جازمًا مقرونًا بالعمل الصالح، فأولئك يمحو الله عنهم سيئاتهم ويجعل مكانها حسنات؛ بسبب توبتهم وندمهم. وكان الله غفورًا لمن تاب، رحيمًا بعباده حيث دعاهم إلى التوبة بعد مبارزته بأكبر المعاصي. ومن تاب عمَّا ارتكب من الذنوب، وعمل عملا صالحا فإنه بذلك يرجع إلى الله رجوعًا صحيحًا، فيقبل الله توبته ويكفر ذنوبه.", "isBasmala": false, "translation_en": "Whoever repents and acts righteously-has inclined towards God with repentance.", "translation_id": "Dan orang-orang yang bertaubat dan mengerjakan amal saleh, maka sesungguhnya dia bertaubat kepada Allah dengan taubat yang sebenar-benarnya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 72, "text": "وَٱلَّذِینَ لَا یَشۡهَدُونَ ٱلزُّورَ وَإِذَا مَرُّوا۟ بِٱللَّغۡوِ مَرُّوا۟ كِرَامࣰا ۝٧٢", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين لا يشهدون بالكذب ولا يحضرون مجالسه، وإذا مروا بأهل الباطل واللغو من غير قصد مرُّوا معرضين منكرين يتنزهون عنه، ولا يرضونه لغيرهم.", "isBasmala": false, "translation_en": "And those who do not bear false witness; and when they come across indecencies, they pass by with dignity.", "translation_id": "Dan orang-orang yang tidak memberikan persaksian palsu, dan apabila mereka bertemu dengan (orang-orang) yang mengerjakan perbuatan-perbuatan yang tidak berfaedah, mereka lalui (saja) dengan menjaga kehormatan dirinya.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 73, "text": "وَٱلَّذِینَ إِذَا ذُكِّرُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ لَمۡ یَخِرُّوا۟ عَلَیۡهَا صُمࣰّا وَعُمۡیَانࣰا ۝٧٣", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين إذا وُعِظُوا بآيات القرآن ودلائل وحدانية الله لم يتغافلوا عنها، كأنهم صمٌّ لم يسمعوها، وعُمْيٌ لم يبصروها، بل وَعَتْها قلوبهم، وتفتَّحت لها بصائرهم، فخرُّوا لله ساجدين مطيعين.", "isBasmala": false, "translation_en": "And those who, when reminded of the revelations of their Lord, do not fall before them deaf and blind.", "translation_id": "Dan orang-orang yang apabila diberi peringatan dengan ayat-ayat Tuhan mereka, mereka tidaklah menghadapinya sebagai orang-orang yang tuli dan buta.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 74, "text": "وَٱلَّذِینَ یَقُولُونَ رَبَّنَا هَبۡ لَنَا مِنۡ أَزۡوَ ٰجِنَا وَذُرِّیَّـٰتِنَا قُرَّةَ أَعۡیُنࣲ وَٱجۡعَلۡنَا لِلۡمُتَّقِینَ إِمَامًا ۝٧٤", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "والذين يسألون الله تعالى قائلين: ربنا هب لنا مِن أزواجنا وذريَّاتنا ما تَقَرُّ به أعيننا، وفيه أنسنا وسرورنا، واجعلنا قدوة يُقتدى بنا في الخير.", "isBasmala": false, "translation_en": "And those who say, \"Our Lord, grant us delight in our spouses and our children, and make us a good example for the righteous.\"", "translation_id": "Dan orang orang yang berkata: \"Ya Tuhan kami, anugrahkanlah kepada kami isteri-isteri kami dan keturunan kami sebagai penyenang hati (kami), dan jadikanlah kami imam bagi orang-orang yang bertakwa.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 75, "text": "أُو۟لَـٰۤىِٕكَ یُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُوا۟ وَیُلَقَّوۡنَ فِیهَا تَحِیَّةࣰ وَسَلَـٰمًا ۝٧٥", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "أولئك الذين اتصفوا بالصفات السابقة من عباد الرحمن، يثابون أعلى منازل الجنة؛ برحمة الله وبسبب صبرهم على الطاعات، وسَيُلَقَّوْن في الجنة التحية والتسليم من الملائكة، والحياة الطيبة والسلامة مِنَ الآفات، خالدين فيها أبدًا مِن غير موت، حَسُنَتْ مستقرًا يَقِرُّون فيه ومقامًا يقيمون به، لا يبغون عنها تحولا.", "isBasmala": false, "translation_en": "Those will be awarded the Chamber for their patience, and will be greeted therein with greetings and peace.", "translation_id": "Mereka itulah orang yang dibalasi dengan martabat yang tinggi (dalam surga) karena kesabaran mereka dan mereka disambut dengan penghormatan dan ucapan selamat di dalamnya,", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 76, "text": "خَـٰلِدِینَ فِیهَاۚ حَسُنَتۡ مُسۡتَقَرࣰّا وَمُقَامࣰا ۝٧٦", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "أولئك الذين اتصفوا بالصفات السابقة من عباد الرحمن، يثابون أعلى منازل الجنة؛ برحمة الله وبسبب صبرهم على الطاعات، وسَيُلَقَّوْن في الجنة التحية والتسليم من الملائكة، والحياة الطيبة والسلامة مِنَ الآفات، خالدين فيها أبدًا مِن غير موت، حَسُنَتْ مستقرًا يَقِرُّون فيه ومقامًا يقيمون به، لا يبغون عنها تحولا.", "isBasmala": false, "translation_en": "Abiding therein forever-it is an excellent residence and destination.", "translation_id": "mereka kekal di dalamnya. Surga itu sebaik-baik tempat menetap dan tempat kediaman.", "manzil": 4, "manzil_display": ""}, {"sura": 25, "sura_name": "الفرقان", "revelation": "Makkiyah", "aya": 77, "text": "قُلۡ مَا یَعۡبَؤُا۟ بِكُمۡ رَبِّی لَوۡلَا دُعَاۤؤُكُمۡۖ فَقَدۡ كَذَّبۡتُمۡ فَسَوۡفَ یَكُونُ لِزَامَۢا ۝٧٧", "juz": 19, "hizb": "(*¼ ح 37*)", "tafsir": "أخبر الله تعالى أنه لا يبالي ولا يعبأ بالناس، لولا دعاؤهم إياه دعاء العبادة ودعاء المسألة، فقد كَذَّبتم-أيها الكافرون- فسوف يكون تكذيبكم مُفْضِيًا لعذاب يلزمكم لزوم الغريم لغريمه، ويهلككم في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Say, \"What are you to my Lord without your prayers? You have denied the truth, and the inevitable will happen.\"", "translation_id": "Katakanlah (kepada orang-orang musyrik): \"Tuhanku tidak mengindahkan kamu, melainkan kalau ada ibadatmu. (Tetapi bagaimana kamu beribadat kepada-Nya), padahal kamu sungguh telah mendustakan-Nya? karena itu kelak (azab) pasti (menimpamu)\".", "manzil": 4, "manzil_display": ""}], "367": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 19, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 1, "text": "۞ طسۤمۤ ۝١", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "(طسم) سبق الكلام على الحروف المقطعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ta, Seen, Meem.", "translation_id": "Thaa Siim Miim", "manzil": 5, "manzil_display": "المنزل الخامس (م ش 5)"}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 2, "text": "تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡمُبِینِ ۝٢", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "هذه آيات القرآن الموضِّح لكل شيء الفاصل بين الهدى والضلال.", "isBasmala": false, "translation_en": "These are the Verses of the Clarifying Book.", "translation_id": "Inilah ayat-ayat Al Quran yang menerangkan.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 3, "text": "لَعَلَّكَ بَـٰخِعࣱ نَّفۡسَكَ أَلَّا یَكُونُوا۟ مُؤۡمِنِینَ ۝٣", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "لعلك - أيها الرسول - من شدة حرصك على هدايتهم مُهْلِك نفسك؛ لأنهم لم يصدِّقوا بك ولم يعملوا بهديك، فلا تفعل ذلك.", "isBasmala": false, "translation_en": "Perhaps you will destroy yourself with grief, because they do not become believers.", "translation_id": "Boleh jadi kamu (Muhammad) akan membinasakan dirimu, karena mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 4, "text": "إِن نَّشَأۡ نُنَزِّلۡ عَلَیۡهِم مِّنَ ٱلسَّمَاۤءِ ءَایَةࣰ فَظَلَّتۡ أَعۡنَـٰقُهُمۡ لَهَا خَـٰضِعِینَ ۝٤", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "إن نشأ ننزل على المكذبين من قومك من السماء معجزة مخوِّفة لهم تلجئهم إلى الإيمان، فتصير أعناقهم خاضعة ذليلة، ولكننا لم نشأ ذلك؛ فإن الإيمان النافع هو الإيمان بالغيب اختيارًا.", "isBasmala": false, "translation_en": "If We will, We can send down upon them a sign from heaven, at which their necks will stay bent in humility.", "translation_id": "Jika kami kehendaki niscaya Kami menurunkan kepada mereka mukjizat dari langit, maka senantiasa kuduk-kuduk mereka tunduk kepadanya.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 5, "text": "وَمَا یَأۡتِیهِم مِّن ذِكۡرࣲ مِّنَ ٱلرَّحۡمَـٰنِ مُحۡدَثٍ إِلَّا كَانُوا۟ عَنۡهُ مُعۡرِضِینَ ۝٥", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "وما يجيء هؤلاء المشركين المكذبين مِن ذِكْرٍ من الرحمن مُحْدَث إنزاله، شيئًا بعد شيء، يأمرهم وينهاهم، ويذكرهم بالدين الحق إلا أعرضوا عنه، ولم يقبلوه.", "isBasmala": false, "translation_en": "No fresh reminder comes to them from the Most Merciful, but they turn their backs at it.", "translation_id": "Dan sekali-kali tidak datang kepada mereka suatu peringatan baru dari Tuhan Yang Maha Pemurah, melainkan mereka selalu berpaling daripadanya.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 6, "text": "فَقَدۡ كَذَّبُوا۟ فَسَیَأۡتِیهِمۡ أَنۢبَـٰۤؤُا۟ مَا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٦", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فقد كذَّبوا بالقرآن واستهزؤوا به، فسيأتيهم أخبار الأمر الذي كانوا يستهزئون به ويسخرون منه، وسيحلُّ بهم العذاب جزاء تمردهم على ربهم.", "isBasmala": false, "translation_en": "They have denied the truth, but soon will come to them the news of what they ridiculed.", "translation_id": "Sungguh mereka telah mendustakan (Al Quran), maka kelak akan datang kepada mereka (kenyataan dari) berita-berita yang selalu mereka perolok-olokkan.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 7, "text": "أَوَ لَمۡ یَرَوۡا۟ إِلَى ٱلۡأَرۡضِ كَمۡ أَنۢبَتۡنَا فِیهَا مِن كُلِّ زَوۡجࣲ كَرِیمٍ ۝٧", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "أكذبوا ولم ينظروا إلى الأرض التي أنبتنا فيها من كل نوع حسن نافع من النبات، لا يقدر على إنباته إلا رب العالمين؟ إن في إخراج النبات من الأرض لَدلالة واضحة على كمال قدرة الله، وما كان أكثر القوم مؤمنين. وإن ربك لهو العزيز على كل مخلوق، الرحيم الذي وسعت رحمته كل شيء.", "isBasmala": false, "translation_en": "Have they not seen the earth, and how many beautiful pairs We produced therein?", "translation_id": "Dan apakah mereka tidak memperhatikan bumi, berapakah banyaknya Kami tumbuhkan di bumi itu pelbagai macam tumbuh-tumbuhan yang baik?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 8, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ ۝٨", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "أكذبوا ولم ينظروا إلى الأرض التي أنبتنا فيها من كل نوع حسن نافع من النبات، لا يقدر على إنباته إلا رب العالمين؟ إن في إخراج النبات من الأرض لَدلالة واضحة على كمال قدرة الله، وما كان أكثر القوم مؤمنين. وإن ربك لهو العزيز على كل مخلوق، الرحيم الذي وسعت رحمته كل شيء.", "isBasmala": false, "translation_en": "Surely in this is a sign, but most of them are not believers.", "translation_id": "Sesungguhnya pada yang demikian itu benar-benar terdapat suatu tanda kekuasaan Allah. Dan kebanyakan mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 9, "text": "وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝٩", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "أكذبوا ولم ينظروا إلى الأرض التي أنبتنا فيها من كل نوع حسن نافع من النبات، لا يقدر على إنباته إلا رب العالمين؟ إن في إخراج النبات من الأرض لَدلالة واضحة على كمال قدرة الله، وما كان أكثر القوم مؤمنين. وإن ربك لهو العزيز على كل مخلوق، الرحيم الذي وسعت رحمته كل شيء.", "isBasmala": false, "translation_en": "Most surely, your Lord is the Almighty, the Merciful.", "translation_id": "Dan sesungguhnya Tuhanmu benar-benar Dialah Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 10, "text": "وَإِذۡ نَادَىٰ رَبُّكَ مُوسَىٰۤ أَنِ ٱئۡتِ ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝١٠", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "واذكر - أيها الرسول - لقومك إذ نادى ربك موسى: أن ائت القوم الظالمين، قوم فرعون، وقل لهم: ألا يخافون عقاب الله تعالى، ويتركون ما هم عليه من الكفر والضلال؟", "isBasmala": false, "translation_en": "Your Lord called to Moses, \"Go to the tyrannical people.", "translation_id": "Dan (ingatlah) ketika Tuhanmu menyeru Musa (dengan firman-Nya): \"Datangilah kaum yang zalim itu,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 11, "text": "قَوۡمَ فِرۡعَوۡنَۚ أَلَا یَتَّقُونَ ۝١١", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "واذكر - أيها الرسول - لقومك إذ نادى ربك موسى: أن ائت القوم الظالمين، قوم فرعون، وقل لهم: ألا يخافون عقاب الله تعالى، ويتركون ما هم عليه من الكفر والضلال؟", "isBasmala": false, "translation_en": "The people of Pharaoh. Will they not fear?\"", "translation_id": "(yaitu) kaum Fir'aun. Mengapa mereka tidak bertakwa?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 12, "text": "قَالَ رَبِّ إِنِّیۤ أَخَافُ أَن یُكَذِّبُونِ ۝١٢", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى: رب إني أخاف أن يكذبوني في الرسالة، ويملأ صدري الغمُّ لتكذيبهم إياي، ولا ينطلق لساني بالدعوة فأرسِلْ جبريل بالوحي إلى أخي هارون؛ ليعاونني. ولهم علي ذنب في قتل رجل منهم، وهو القبطي، فأخاف أن يقتلوني به.", "isBasmala": false, "translation_en": "He said, \"My Lord, I fear they will reject me.", "translation_id": "Berkata Musa: \"Ya Tuhanku, sesungguhnya aku takut bahwa mereka akan mendustakan aku.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 13, "text": "وَیَضِیقُ صَدۡرِی وَلَا یَنطَلِقُ لِسَانِی فَأَرۡسِلۡ إِلَىٰ هَـٰرُونَ ۝١٣", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى: رب إني أخاف أن يكذبوني في الرسالة، ويملأ صدري الغمُّ لتكذيبهم إياي، ولا ينطلق لساني بالدعوة فأرسِلْ جبريل بالوحي إلى أخي هارون؛ ليعاونني. ولهم علي ذنب في قتل رجل منهم، وهو القبطي، فأخاف أن يقتلوني به.", "isBasmala": false, "translation_en": "And I become stressed, and my tongue is not fluent, so send Aaron too.", "translation_id": "Dan (karenanya) sempitlah dadaku dan tidak lancar lidahku maka utuslah (Jibril) kepada Harun.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 14, "text": "وَلَهُمۡ عَلَیَّ ذَنۢبࣱ فَأَخَافُ أَن یَقۡتُلُونِ ۝١٤", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى: رب إني أخاف أن يكذبوني في الرسالة، ويملأ صدري الغمُّ لتكذيبهم إياي، ولا ينطلق لساني بالدعوة فأرسِلْ جبريل بالوحي إلى أخي هارون؛ ليعاونني. ولهم علي ذنب في قتل رجل منهم، وهو القبطي، فأخاف أن يقتلوني به.", "isBasmala": false, "translation_en": "And they have a charge against me, so I fear they will kill me.\"", "translation_id": "Dan aku berdosa terhadap mereka, maka aku takut mereka akan membunuhku\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 15, "text": "قَالَ كَلَّاۖ فَٱذۡهَبَا بِـَٔایَـٰتِنَاۤۖ إِنَّا مَعَكُم مُّسۡتَمِعُونَ ۝١٥", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال الله لموسى: كلا لن يقتلوك، وقد أجبت طلبك في هارون، فاذهبا بالمعجزات الدالة على صدقكما، إنا معكم بالعلم والحفظ والنصرة مستمعون. فأتِيَا فرعون فقولا له: إنا مرسَلان إليك وإلى قومك من رب العالمين: أن اترك بني إسرائيل؛ ليذهبوا معنا.", "isBasmala": false, "translation_en": "He said, \"No. Go, both of you, with Our proofs. We will be with you, listening.", "translation_id": "Allah berfirman: \"Jangan takut (mereka tidak akan dapat membunuhmu), maka pergilah kamu berdua dengan membawa ayat-ayat Kami (mukjizat-mukjizat); sesungguhnya Kami bersamamu mendengarkan (apa-apa yang mereka katakan),", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 16, "text": "فَأۡتِیَا فِرۡعَوۡنَ فَقُولَاۤ إِنَّا رَسُولُ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٦", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال الله لموسى: كلا لن يقتلوك، وقد أجبت طلبك في هارون، فاذهبا بالمعجزات الدالة على صدقكما، إنا معكم بالعلم والحفظ والنصرة مستمعون. فأتِيَا فرعون فقولا له: إنا مرسَلان إليك وإلى قومك من رب العالمين: أن اترك بني إسرائيل؛ ليذهبوا معنا.", "isBasmala": false, "translation_en": "Go to Pharaoh, and say, 'We are the Messengers of the Lord of the Worlds.", "translation_id": "Maka datanglah kamu berdua kepada Fir'aun dan katakanlah olehmu: \"Sesungguhnya Kami adalah Rasul Tuhan semesta alam,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 17, "text": "أَنۡ أَرۡسِلۡ مَعَنَا بَنِیۤ إِسۡرَ ٰۤءِیلَ ۝١٧", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال الله لموسى: كلا لن يقتلوك، وقد أجبت طلبك في هارون، فاذهبا بالمعجزات الدالة على صدقكما، إنا معكم بالعلم والحفظ والنصرة مستمعون. فأتِيَا فرعون فقولا له: إنا مرسَلان إليك وإلى قومك من رب العالمين: أن اترك بني إسرائيل؛ ليذهبوا معنا.", "isBasmala": false, "translation_en": "Let the Children of Israel go with us.'\"", "translation_id": "lepaskanlah Bani Israil (pergi) beserta kami\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 18, "text": "قَالَ أَلَمۡ نُرَبِّكَ فِینَا وَلِیدࣰا وَلَبِثۡتَ فِینَا مِنۡ عُمُرِكَ سِنِینَ ۝١٨", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون لموسى ممتنًا عليه: ألم نُرَبِّك في منازلنا صغيرًا، ومكثت في رعايتنا سنين من عُمُرك وارتكبت جنايةً بقتلك رجلا من قومي حين ضربته ودفعته، وأنت من الجاحدين نعمتي المنكرين ربوبيتي؟", "isBasmala": false, "translation_en": "He said, \"Did we not raise you among us as a child, and you stayed among us for many of your years?", "translation_id": "Fir'aun menjawab: \"Bukankah kami telah mengasuhmu di antara (keluarga) kami, waktu kamu masih kanak-kanak dan kamu tinggal bersama kami beberapa tahun dari umurmu.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 19, "text": "وَفَعَلۡتَ فَعۡلَتَكَ ٱلَّتِی فَعَلۡتَ وَأَنتَ مِنَ ٱلۡكَـٰفِرِینَ ۝١٩", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون لموسى ممتنًا عليه: ألم نُرَبِّك في منازلنا صغيرًا، ومكثت في رعايتنا سنين من عُمُرك وارتكبت جنايةً بقتلك رجلا من قومي حين ضربته ودفعته، وأنت من الجاحدين نعمتي المنكرين ربوبيتي؟", "isBasmala": false, "translation_en": "And you committed that deed you committed, and you were ungrateful.\"", "translation_id": "dan kamu telah berbuat suatu perbuatan yang telah kamu lakukan itu dan kamu termasuk golongan orang-orang yang tidak membalas guna.", "manzil": 5, "manzil_display": ""}], "368": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 20, "text": "قَالَ فَعَلۡتُهَاۤ إِذࣰا وَأَنَا۠ مِنَ ٱلضَّاۤلِّینَ ۝٢٠", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى مجيبًا لفرعون: فعلتُ ما ذكرتَ قبل أن يوحي الله إلي، ويبعثني رسولا فخرجت من بينكم فارًّا إلى \"مدين\"، لـمَّا خفت أن تقتلوني بما فعلتُ من غير عَمْد، فوهب لي ربي تفضلا منه النبوة والعلم، وجعلني من المرسلين. وتلك التربية في بيتك تَعُدُّها نعمة منك عليَّ، وقد جعلت بني إسرائيل عبيدًا تذبح أبناءهم وتستحيي نساءهم؟", "isBasmala": false, "translation_en": "He said, \"I did it then, when I was of those astray.", "translation_id": "Berkata Musa: \"Aku telah melakukannya, sedang aku di waktu itu termasuk orang-orang yang khilaf.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 21, "text": "فَفَرَرۡتُ مِنكُمۡ لَمَّا خِفۡتُكُمۡ فَوَهَبَ لِی رَبِّی حُكۡمࣰا وَجَعَلَنِی مِنَ ٱلۡمُرۡسَلِینَ ۝٢١", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى مجيبًا لفرعون: فعلتُ ما ذكرتَ قبل أن يوحي الله إلي، ويبعثني رسولا فخرجت من بينكم فارًّا إلى \"مدين\"، لـمَّا خفت أن تقتلوني بما فعلتُ من غير عَمْد، فوهب لي ربي تفضلا منه النبوة والعلم، وجعلني من المرسلين. وتلك التربية في بيتك تَعُدُّها نعمة منك عليَّ، وقد جعلت بني إسرائيل عبيدًا تذبح أبناءهم وتستحيي نساءهم؟", "isBasmala": false, "translation_en": "And I fled from you when I feared you; but my Lord gave me wisdom, and made me one of the messengers.", "translation_id": "Lalu aku lari meninggalkan kamu ketika aku takut kepadamu, kemudian Tuhanku memberikan kepadaku ilmu serta Dia menjadikanku salah seorang di antara rasul-rasul.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 22, "text": "وَتِلۡكَ نِعۡمَةࣱ تَمُنُّهَا عَلَیَّ أَنۡ عَبَّدتَّ بَنِیۤ إِسۡرَ ٰۤءِیلَ ۝٢٢", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى مجيبًا لفرعون: فعلتُ ما ذكرتَ قبل أن يوحي الله إلي، ويبعثني رسولا فخرجت من بينكم فارًّا إلى \"مدين\"، لـمَّا خفت أن تقتلوني بما فعلتُ من غير عَمْد، فوهب لي ربي تفضلا منه النبوة والعلم، وجعلني من المرسلين. وتلك التربية في بيتك تَعُدُّها نعمة منك عليَّ، وقد جعلت بني إسرائيل عبيدًا تذبح أبناءهم وتستحيي نساءهم؟", "isBasmala": false, "translation_en": "Is that the favor you taunt me with, although you have enslaved the Children of Israel?\"", "translation_id": "Budi yang kamu limpahkan kepadaku itu adalah (disebabkan) kamu telah memperbudak Bani Israil\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 23, "text": "قَالَ فِرۡعَوۡنُ وَمَا رَبُّ ٱلۡعَـٰلَمِینَ ۝٢٣", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون لموسى: وما رب العالمين الذي تدَّعي أنك رسوله؟", "isBasmala": false, "translation_en": "Pharaoh said, \"And what is the Lord of the Worlds?\"", "translation_id": "Fir'aun bertanya: \"Siapa Tuhan semesta alam itu?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 24, "text": "قَالَ رَبُّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۤۖ إِن كُنتُم مُّوقِنِینَ ۝٢٤", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى: هو مالك ومدبر السموات والأرض وما بينهما، إن كنتم موقنين بذلك، فآمِنوا.", "isBasmala": false, "translation_en": "He said, \"The Lord of the heavens and the earth, and everything between them, if you are aware.\"", "translation_id": "Musa menjawab: \"Tuhan Pencipta langit dan bumi dan apa-apa yang di antara keduanya (Itulah Tuhanmu), jika kamu sekalian (orang-orang) mempercayai-Nya\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 25, "text": "قَالَ لِمَنۡ حَوۡلَهُۥۤ أَلَا تَسۡتَمِعُونَ ۝٢٥", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون لمن حوله مِن أشراف قومه: ألا تسمعون مقالة موسى العجيبة بوجود رب سواي؟", "isBasmala": false, "translation_en": "He said to those around him, \"Do you not hear?\"", "translation_id": "Berkata Fir'aun kepada orang-orang sekelilingnya: \"Apakah kamu tidak mendengarkan?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 26, "text": "قَالَ رَبُّكُمۡ وَرَبُّ ءَابَاۤىِٕكُمُ ٱلۡأَوَّلِینَ ۝٢٦", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى: الرب الذي أدعوكم إليه هو الذي خلقكم وخلق آباءكم الأولين، فكيف تعبدون مَن هو مخلوق مثلكم، وله آباء قد فنوا كآبائكم؟", "isBasmala": false, "translation_en": "He said, \"Your Lord and the Lord of your ancestors of old.\"", "translation_id": "Musa berkata (pula): \"Tuhan kamu dan Tuhan nenek-nenek moyang kamu yang dahulu\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 27, "text": "قَالَ إِنَّ رَسُولَكُمُ ٱلَّذِیۤ أُرۡسِلَ إِلَیۡكُمۡ لَمَجۡنُونࣱ ۝٢٧", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون لخاصته يستثير غضبهم؛ لتكذيب موسى إياه: إن رسولكم الذي أرسل إليكم لمجنون، يتكلم كلامًا لا يُعْقَل!", "isBasmala": false, "translation_en": "He said, \"This messenger of yours, who is sent to you, is crazy.\"", "translation_id": "Fir'aun berkata: \"Sesungguhnya Rasulmu yang diutus kepada kamu sekalian benar-benar orang gila\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 28, "text": "قَالَ رَبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَمَا بَیۡنَهُمَاۤۖ إِن كُنتُمۡ تَعۡقِلُونَ ۝٢٨", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى: رب المشرق والمغرب وما بينهما وما يكون فيهما من نور وظلمة، وهذا يستوجب الإيمان به وحده إن كنتم من أهل العقل والتدبر!", "isBasmala": false, "translation_en": "He said, \"Lord of the East and the West, and everything between them, if you understand.\"", "translation_id": "Musa berkata: \"Tuhan yang menguasai timur dan barat dan apa yang ada di antara keduanya: (Itulah Tuhanmu) jika kamu mempergunakan akal\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 29, "text": "قَالَ لَىِٕنِ ٱتَّخَذۡتَ إِلَـٰهًا غَیۡرِی لَأَجۡعَلَنَّكَ مِنَ ٱلۡمَسۡجُونِینَ ۝٢٩", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون لموسى مهددًا له: لئن اتخذت إلهًا غيري لأسجننك مع مَن سجنت.", "isBasmala": false, "translation_en": "He said, \"If you accept any god other than me, I will make you a prisoner.\"", "translation_id": "Fir'aun berkata: \"Sungguh jika kamu menyembah Tuhan selain aku, benar-benar aku akan menjadikan kamu salah seorang yang dipenjarakan\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 30, "text": "قَالَ أَوَ لَوۡ جِئۡتُكَ بِشَیۡءࣲ مُّبِینࣲ ۝٣٠", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى: أتجعلني من المسجونين، ولو جئتك ببرهان قاطع يتبين منه صدقي؟", "isBasmala": false, "translation_en": "He said, \"What if I bring you something convincing?\"", "translation_id": "Musa berkata: \"Dan apakah (kamu akan melakukan itu) kendatipun aku tunjukkan kepadamu sesuatu (keterangan) yang nyata?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 31, "text": "قَالَ فَأۡتِ بِهِۦۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ ۝٣١", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون: فأت به إن كنت من الصادقين في دعواك.", "isBasmala": false, "translation_en": "He said, \"Bring it, if you are being truthful.\"", "translation_id": "Fir'aun berkata: \"Datangkanlah sesuatu (keterangan) yang nyata itu, jika kamu adalah termasuk orang-orang yang benar\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 32, "text": "فَأَلۡقَىٰ عَصَاهُ فَإِذَا هِیَ ثُعۡبَانࣱ مُّبِینࣱ ۝٣٢", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فألقى موسى عصاه فتحولت ثعبانًا حقيقيًا، ليس تمويهًا كما يفعل السحرة، وأخرج يده مِن جيبه فإذا هي بيضاء كالثلج من غير برص، تَبْهَر الناظرين.", "isBasmala": false, "translation_en": "So he cast his staff; and it was a serpent, plain to see.", "translation_id": "Maka Musa melemparkan tongkatnya, lalu tiba-tiba tongkat itu (menjadi) ular yang nyata.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 33, "text": "وَنَزَعَ یَدَهُۥ فَإِذَا هِیَ بَیۡضَاۤءُ لِلنَّـٰظِرِینَ ۝٣٣", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فألقى موسى عصاه فتحولت ثعبانًا حقيقيًا، ليس تمويهًا كما يفعل السحرة، وأخرج يده مِن جيبه فإذا هي بيضاء كالثلج من غير برص، تَبْهَر الناظرين.", "isBasmala": false, "translation_en": "And he pulled his hand; and it was white, for all to see.", "translation_id": "Dan ia menarik tangannya (dari dalam bajunya), maka tiba-tiba tangan itu jadi putih (bersinar) bagi orang-orang yang melihatnya.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 34, "text": "قَالَ لِلۡمَلَإِ حَوۡلَهُۥۤ إِنَّ هَـٰذَا لَسَـٰحِرٌ عَلِیمࣱ ۝٣٤", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون لأشراف قومه خشية أن يؤمنوا: إن موسى لَساحر ماهر، يريد أن يخرجكم بسحره من أرضكم، فأي شيء تشيرون به في شأنه أتبع رأيكم فيه؟", "isBasmala": false, "translation_en": "He said to the dignitaries around him, \"This is a skilled magician.", "translation_id": "Fir'aun berkata kepada pembesar-pembesar yang berada sekelilingnya: Sesungguhnya Musa ini benar-benar seorang ahli sihir yang pandai,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 35, "text": "یُرِیدُ أَن یُخۡرِجَكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِۦ فَمَاذَا تَأۡمُرُونَ ۝٣٥", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون لأشراف قومه خشية أن يؤمنوا: إن موسى لَساحر ماهر، يريد أن يخرجكم بسحره من أرضكم، فأي شيء تشيرون به في شأنه أتبع رأيكم فيه؟", "isBasmala": false, "translation_en": "He intends to drive you out of your land with his magic, so what do you recommend?\"", "translation_id": "ia hendak mengusir kamu dari negerimu sendiri dengan sihirnya; maka karena itu apakah yang kamu anjurkan?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 36, "text": "قَالُوۤا۟ أَرۡجِهۡ وَأَخَاهُ وَٱبۡعَثۡ فِی ٱلۡمَدَاۤىِٕنِ حَـٰشِرِینَ ۝٣٦", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال له قومه: أخِّر أمر موسى وهارون، وأرسِلْ في المدائن جندًا جامعين للسحرة، يأتوك بكلِّ مَن أجاد السحر، وتفوَّق في معرفته.", "isBasmala": false, "translation_en": "They said, \"Delay him and his brother, and send recruiters to the cities.", "translation_id": "Mereka menjawab: \"Tundalah (urusan) dia dan saudaranya dan kirimkanlah ke seluruh negeri orang-orang yang akan mengumpulkan (ahli sihir),", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 37, "text": "یَأۡتُوكَ بِكُلِّ سَحَّارٍ عَلِیمࣲ ۝٣٧", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال له قومه: أخِّر أمر موسى وهارون، وأرسِلْ في المدائن جندًا جامعين للسحرة، يأتوك بكلِّ مَن أجاد السحر، وتفوَّق في معرفته.", "isBasmala": false, "translation_en": "To bring you every experienced magician.\"", "translation_id": "niscaya mereka akan mendatangkan semua ahli sihir yang pandai kepadamu\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 38, "text": "فَجُمِعَ ٱلسَّحَرَةُ لِمِیقَـٰتِ یَوۡمࣲ مَّعۡلُومࣲ ۝٣٨", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فَجُمع السحرة، وحُدِّد لهم وقت معلوم، هو وقت الضحى من يوم الزينة الذي يتفرغون فيه من أشغالهم، ويجتمعون ويتزيَّنون؛ وذلك للاجتماع بموسى. وحُثَّ الناس على الاجتماع؛ أملا في أن تكون الغلبة للسحرة.", "isBasmala": false, "translation_en": "So the magicians were gathered for the appointment on a specified day.", "translation_id": "Lalu dikumpulkan ahli-ahli sihir pada waktu yang ditetapkan di hari yang maklum,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 39, "text": "وَقِیلَ لِلنَّاسِ هَلۡ أَنتُم مُّجۡتَمِعُونَ ۝٣٩", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فَجُمع السحرة، وحُدِّد لهم وقت معلوم، هو وقت الضحى من يوم الزينة الذي يتفرغون فيه من أشغالهم، ويجتمعون ويتزيَّنون؛ وذلك للاجتماع بموسى. وحُثَّ الناس على الاجتماع؛ أملا في أن تكون الغلبة للسحرة.", "isBasmala": false, "translation_en": "And it was said to the people, \"Are you all gathered?", "translation_id": "dan dikatakan kepada orang banyak: \"Berkumpullah kamu sekalian.", "manzil": 5, "manzil_display": ""}], "369": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 40, "text": "لَعَلَّنَا نَتَّبِعُ ٱلسَّحَرَةَ إِن كَانُوا۟ هُمُ ٱلۡغَـٰلِبِینَ ۝٤٠", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "إننا نطمع أن تكون الغلبة للسحرة، فنثبت على ديننا.", "isBasmala": false, "translation_en": "That we may follow the magicians, if they are the winners.\"", "translation_id": "semoga kita mengikuti ahli-ahli sihir jika mereka adalah orang-orang yang menang\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 41, "text": "فَلَمَّا جَاۤءَ ٱلسَّحَرَةُ قَالُوا۟ لِفِرۡعَوۡنَ أَىِٕنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَـٰلِبِینَ ۝٤١", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فلما جاء السحرة فرعون قالوا له: أإن لنا لأجرًا مِن مال أو جاه، إنْ كنا نحن الغالبين لموسى؟", "isBasmala": false, "translation_en": "When the magicians arrived, they said to Pharaoh, \"Is there a reward for us, if we are the winners?\"", "translation_id": "Maka tatkala ahli-ahli sihir datang, merekapun bertanya kepada Fir'aun: \"Apakah kami sungguh-sungguh mendapat upah yang besar jika kami adalah orang-orang yang menang?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 42, "text": "قَالَ نَعَمۡ وَإِنَّكُمۡ إِذࣰا لَّمِنَ ٱلۡمُقَرَّبِینَ ۝٤٢", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون: نعم لكم عندي ما طلبتم مِن أجر، وإنكم حينئذ لمن المقربين لديَّ.", "isBasmala": false, "translation_en": "He said, \"Yes, and you will be among those favored.\"", "translation_id": "Fir'aun menjawab: \"Ya, kalau demikian, sesungguhnya kamu sekalian benar-benar akan menjadi orang yang didekatkan (kepadaku)\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 43, "text": "قَالَ لَهُم مُّوسَىٰۤ أَلۡقُوا۟ مَاۤ أَنتُم مُّلۡقُونَ ۝٤٣", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال موسى للسحرة مريدًا إبطال سحرهم وإظهار أن ما جاء به ليس سحرًا: ألقوا ما تريدون إلقاءه من السحر.", "isBasmala": false, "translation_en": "Moses said to them, \"Present what you intend to present.\"", "translation_id": "Berkatalah Musa kepada mereka: \"Lemparkanlah apa yang hendak kamu lemparkan\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 44, "text": "فَأَلۡقَوۡا۟ حِبَالَهُمۡ وَعِصِیَّهُمۡ وَقَالُوا۟ بِعِزَّةِ فِرۡعَوۡنَ إِنَّا لَنَحۡنُ ٱلۡغَـٰلِبُونَ ۝٤٤", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فألقَوا حبالهم وعصيَّهم، وخُيِّل للناس أنها حيَّات تسعى، وأقسموا بعزة فرعون قائلين: إننا لنحن الغالبون.", "isBasmala": false, "translation_en": "So they threw their ropes and their sticks, and said, \"By the majesty of Pharaoh, we will be the winners.\"", "translation_id": "Lalu mereka melemparkan tali temali dan tongkat-tongkat mereka dan berkata: \"Demi kekuasaan Fir'aun, sesungguhnya kami benar-benar akan menang\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 45, "text": "فَأَلۡقَىٰ مُوسَىٰ عَصَاهُ فَإِذَا هِیَ تَلۡقَفُ مَا یَأۡفِكُونَ ۝٤٥", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فألقى موسى عصاه، فإذا هي حية عظيمة، تبتلع ما صدر منهم من إفك وتزوير.", "isBasmala": false, "translation_en": "Then Moses threw his staff, and behold, it began swallowing their trickery.", "translation_id": "Kemudian Musa menjatuhkan tongkatnya maka tiba-tiba ia menelan benda-benda palsu yang mereka ada-adakan itu.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 46, "text": "فَأُلۡقِیَ ٱلسَّحَرَةُ سَـٰجِدِینَ ۝٤٦", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فلما شاهدوا ذلك، وعلموا أنه ليس من تمويه السحرة، آمنوا بالله وسجدوا له، وقالوا: آمنَّا برب العالمين رب موسى وهارون.", "isBasmala": false, "translation_en": "And the magicians fell down prostrating.", "translation_id": "Maka tersungkurlah ahli-ahli sihir sambil bersujud (kepada Allah),", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 47, "text": "قَالُوۤا۟ ءَامَنَّا بِرَبِّ ٱلۡعَـٰلَمِینَ ۝٤٧", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فلما شاهدوا ذلك، وعلموا أنه ليس من تمويه السحرة، آمنوا بالله وسجدوا له، وقالوا: آمنَّا برب العالمين رب موسى وهارون.", "isBasmala": false, "translation_en": "They said, \"We have believed in the Lord of the Worlds.", "translation_id": "mereka berkata: \"Kami beriman kepada Tuhan semesta alam,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 48, "text": "رَبِّ مُوسَىٰ وَهَـٰرُونَ ۝٤٨", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "فلما شاهدوا ذلك، وعلموا أنه ليس من تمويه السحرة، آمنوا بالله وسجدوا له، وقالوا: آمنَّا برب العالمين رب موسى وهارون.", "isBasmala": false, "translation_en": "The Lord of Moses and Aaron.\"", "translation_id": "(yaitu) Tuhan Musa dan Harun\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 49, "text": "قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِیرُكُمُ ٱلَّذِی عَلَّمَكُمُ ٱلسِّحۡرَ فَلَسَوۡفَ تَعۡلَمُونَۚ لَأُقَطِّعَنَّ أَیۡدِیَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَـٰفࣲ وَلَأُصَلِّبَنَّكُمۡ أَجۡمَعِینَ ۝٤٩", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال فرعون للسحرة مستنكرًا: آمنتم لموسى بغير إذن مني، وقال موهمًا أنَّ فِعْل موسى سحر: إنه لكبيركم الذي علَّمكم السحر، فلسوف تعلمون ما ينزل بكم من عقاب: لأقطعنَّ أيديكم وأرجلكم من خلاف: بقطع اليد اليمنى والرجل اليسرى أو عكس ذلك، ولأصلبنَّكم أجمعين.", "isBasmala": false, "translation_en": "He said, \"Did you believe in Him before I have given you permission? He must be your chief, who taught you magic. You will soon know. I will cut off your hands and feet on opposite sides, and I will crucify you all.\"", "translation_id": "Fir'aun berkata: \"Apakah kamu sekalian beriman kepada Musa sebelum aku memberi izin kepadamu? Sesungguhnya dia benar-benar pemimpinmu yang mengajarkan sihir kepadamu maka kamu nanti pasti benar-benar akan mengetahui (akibat perbuatanmu); sesungguhnya aku akan memotong tanganmu dan kakimu dengan bersilangan dan aku akan menyalibmu semuanya\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 50, "text": "قَالُوا۟ لَا ضَیۡرَۖ إِنَّاۤ إِلَىٰ رَبِّنَا مُنقَلِبُونَ ۝٥٠", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال السحرة لفرعون: لا ضرر علينا فيما يلحقنا من عقاب الدنيا، إنا راجعون إلى ربنا فيعطينا النعيم المقيم. إنا نرجو أن يغفر لنا ربنا خطايانا من الشرك وغيره؛ لكوننا أول المؤمنين في قومك.", "isBasmala": false, "translation_en": "They said, \"No problem. To our Lord we will return.", "translation_id": "Mereka berkata: \"Tidak ada kemudharatan (bagi kami); sesungguhnya kami akan kembali kepada Tuhan kami,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 51, "text": "إِنَّا نَطۡمَعُ أَن یَغۡفِرَ لَنَا رَبُّنَا خَطَـٰیَـٰنَاۤ أَن كُنَّاۤ أَوَّلَ ٱلۡمُؤۡمِنِینَ ۝٥١", "juz": 19, "hizb": "(*½ ح 37*)", "tafsir": "قال السحرة لفرعون: لا ضرر علينا فيما يلحقنا من عقاب الدنيا، إنا راجعون إلى ربنا فيعطينا النعيم المقيم. إنا نرجو أن يغفر لنا ربنا خطايانا من الشرك وغيره؛ لكوننا أول المؤمنين في قومك.", "isBasmala": false, "translation_en": "We are eager for our Lord to forgive us our sins, since we are the first of the believers.\"", "translation_id": "sesungguhnya kami amat menginginkan bahwa Tuhan kami akan mengampuni kesalahan kami, karena kami adalah orang-orang yang pertama-tama beriman\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 52, "text": "۞ وَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ أَنۡ أَسۡرِ بِعِبَادِیۤ إِنَّكُم مُّتَّبَعُونَ ۝٥٢", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وأوحى الله إلى موسى عليه السلام: أَنْ سِرْ ليلا بمن آمن من بني إسرائيل؛ لأن فرعون وجنوده متبعوكم حتى لا يدركوكم قبل وصولكم إلى البحر.", "isBasmala": false, "translation_en": "And We inspired Moses: \"Travel with My servants by night. You will be followed.\"", "translation_id": "Dan Kami wahyukan (perintahkan) kepada Musa: \"Pergilah di malam hari dengan membawa hamba-hamba-Ku (Bani Israil), karena sesungguhnya kamu sekalian akan disusuli\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 53, "text": "فَأَرۡسَلَ فِرۡعَوۡنُ فِی ٱلۡمَدَاۤىِٕنِ حَـٰشِرِینَ ۝٥٣", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فأرسل فرعون جنده- حين بلغه مسير بني إسرائيل- يجمعون جيشه من مدائن مملكته.", "isBasmala": false, "translation_en": "Pharaoh sent heralds to the cities.", "translation_id": "Kemudian Fir'aun mengirimkan orang yang mengumpulkan (tentaranya) ke kota-kota.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 54, "text": "إِنَّ هَـٰۤؤُلَاۤءِ لَشِرۡذِمَةࣱ قَلِیلُونَ ۝٥٤", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال فرعون: إن بني إسرائيل الذين فرُّوا مع موسى لَطائفة حقيرة قليلة العدد، وإنهم لمالئون صدورنا غيظًا؛ حيث خالفوا ديننا، وخرجوا بغير إذننا، وإنا لجميع متيقظون مستعدون لهم.", "isBasmala": false, "translation_en": "\"These are a small gang.", "translation_id": "(Fir'aun berkata): \"Sesungguhnya mereka (Bani Israil) benar-benar golongan kecil,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 55, "text": "وَإِنَّهُمۡ لَنَا لَغَاۤىِٕظُونَ ۝٥٥", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال فرعون: إن بني إسرائيل الذين فرُّوا مع موسى لَطائفة حقيرة قليلة العدد، وإنهم لمالئون صدورنا غيظًا؛ حيث خالفوا ديننا، وخرجوا بغير إذننا، وإنا لجميع متيقظون مستعدون لهم.", "isBasmala": false, "translation_en": "And they are enraging us.", "translation_id": "dan sesungguhnya mereka membuat hal-hal yang menimbulkan amarah kita,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 56, "text": "وَإِنَّا لَجَمِیعٌ حَـٰذِرُونَ ۝٥٦", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال فرعون: إن بني إسرائيل الذين فرُّوا مع موسى لَطائفة حقيرة قليلة العدد، وإنهم لمالئون صدورنا غيظًا؛ حيث خالفوا ديننا، وخرجوا بغير إذننا، وإنا لجميع متيقظون مستعدون لهم.", "isBasmala": false, "translation_en": "But we are a vigilant multitude.\"", "translation_id": "dan sesungguhnya kita benar-benar golongan yang selalu berjaga-jaga\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 57, "text": "فَأَخۡرَجۡنَـٰهُم مِّن جَنَّـٰتࣲ وَعُیُونࣲ ۝٥٧", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فأخرج الله فرعون وقومه من أرض \"مصر\" ذات البساتين وعيون الماء وخزائن المال والمنازل الحسان. وكما أخرجناهم، جعلنا هذه الديار من بعدهم لبني إسرائيل.", "isBasmala": false, "translation_en": "So We drove them out of gardens and springs.", "translation_id": "Maka Kami keluarkan Fir'aun dan kaumnya dari taman-taman dan mata air,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 58, "text": "وَكُنُوزࣲ وَمَقَامࣲ كَرِیمࣲ ۝٥٨", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فأخرج الله فرعون وقومه من أرض \"مصر\" ذات البساتين وعيون الماء وخزائن المال والمنازل الحسان. وكما أخرجناهم، جعلنا هذه الديار من بعدهم لبني إسرائيل.", "isBasmala": false, "translation_en": "And treasures and noble dwellings.", "translation_id": "dan (dari) perbendaharaan dan kedudukan yang mulia,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 59, "text": "كَذَ ٰلِكَۖ وَأَوۡرَثۡنَـٰهَا بَنِیۤ إِسۡرَ ٰۤءِیلَ ۝٥٩", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فأخرج الله فرعون وقومه من أرض \"مصر\" ذات البساتين وعيون الماء وخزائن المال والمنازل الحسان. وكما أخرجناهم، جعلنا هذه الديار من بعدهم لبني إسرائيل.", "isBasmala": false, "translation_en": "So it was. And We made the Children of Israel inherit them.", "translation_id": "demikianlah halnya dan Kami anugerahkan semuanya (itu) kepada Bani Israil.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 60, "text": "فَأَتۡبَعُوهُم مُّشۡرِقِینَ ۝٦٠", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فلحق فرعون وجنده موسى ومَن معه وقت شروق الشمس.", "isBasmala": false, "translation_en": "And they pursued them at sunrise.", "translation_id": "Maka Fir'aun dan bala tentaranya dapat menyusuli mereka di waktu matahari terbit.", "manzil": 5, "manzil_display": ""}], "370": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 61, "text": "فَلَمَّا تَرَ ٰۤءَا ٱلۡجَمۡعَانِ قَالَ أَصۡحَـٰبُ مُوسَىٰۤ إِنَّا لَمُدۡرَكُونَ ۝٦١", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فلما رأى كل واحد من الفريقين الآخر قال أصحاب موسى: إنَّ جَمْعَ فرعون مُدْرِكنا ومهلكنا.", "isBasmala": false, "translation_en": "When the two groups sighted each other, the followers of Moses said, \"We are being overtaken.\"", "translation_id": "Maka setelah kedua golongan itu saling melihat, berkatalah pengikut-pengikut Musa: \"Sesungguhnya kita benar-benar akan tersusul\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 62, "text": "قَالَ كَلَّاۤۖ إِنَّ مَعِیَ رَبِّی سَیَهۡدِینِ ۝٦٢", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال موسى لهم: كلا ليس الأمر كما ذكرتم فلن تُدْرَكوا؛ إن معي ربي بالنصر، سيهديني لما فيه نجاتي ونجاتكم.", "isBasmala": false, "translation_en": "He said, \"No; my Lord is with me, He will guide me.\"", "translation_id": "Musa menjawab: \"Sekali-kali tidak akan tersusul; sesungguhnya Tuhanku besertaku, kelak Dia akan memberi petunjuk kepadaku\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 63, "text": "فَأَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ أَنِ ٱضۡرِب بِّعَصَاكَ ٱلۡبَحۡرَۖ فَٱنفَلَقَ فَكَانَ كُلُّ فِرۡقࣲ كَٱلطَّوۡدِ ٱلۡعَظِیمِ ۝٦٣", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فأوحينا إلى موسى أن اضرب بعصاك البحر، فضرب، فانفلق البحر إلى اثني عشر طريقًا بعدد قبائل بني إسرائيل، فكانت كل قطعة انفصلت من البحر كالجبل العظيم.", "isBasmala": false, "translation_en": "We inspired Moses: \"Strike the sea with your staff.\" Whereupon it parted, and each part was like a huge hill.", "translation_id": "Lalu Kami wahyukan kepada Musa: \"Pukullah lautan itu dengan tongkatmu\". Maka terbelahlah lautan itu dan tiap-tiap belahan adalah seperti gunung yang besar.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 64, "text": "وَأَزۡلَفۡنَا ثَمَّ ٱلۡـَٔاخَرِینَ ۝٦٤", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وقرَّبْنا هناك فرعون وقومه حتى دخلوا البحر، وأنجينا موسى ومَن معه أجمعين. فاستمر البحر على انفلاقه حتى عبروا إلى البر، ثم أغرقنا فرعون ومن معه بإطباق البحر عليهم بعد أن دخلوا فيه متبعين موسى وقومه.", "isBasmala": false, "translation_en": "And there We brought the others near.", "translation_id": "Dan di sanalah Kami dekatkan golongan yang lain.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 65, "text": "وَأَنجَیۡنَا مُوسَىٰ وَمَن مَّعَهُۥۤ أَجۡمَعِینَ ۝٦٥", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وقرَّبْنا هناك فرعون وقومه حتى دخلوا البحر، وأنجينا موسى ومَن معه أجمعين. فاستمر البحر على انفلاقه حتى عبروا إلى البر، ثم أغرقنا فرعون ومن معه بإطباق البحر عليهم بعد أن دخلوا فيه متبعين موسى وقومه.", "isBasmala": false, "translation_en": "And We saved Moses and those with him, all together.", "translation_id": "Dan Kami selamatkan Musa dan orang-orang yang besertanya semuanya.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 66, "text": "ثُمَّ أَغۡرَقۡنَا ٱلۡـَٔاخَرِینَ ۝٦٦", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وقرَّبْنا هناك فرعون وقومه حتى دخلوا البحر، وأنجينا موسى ومَن معه أجمعين. فاستمر البحر على انفلاقه حتى عبروا إلى البر، ثم أغرقنا فرعون ومن معه بإطباق البحر عليهم بعد أن دخلوا فيه متبعين موسى وقومه.", "isBasmala": false, "translation_en": "Then We drowned the others.", "translation_id": "Dan Kami tenggelamkan golongan yang lain itu.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 67, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ ۝٦٧", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "إن في ذلك الذي حدث لَعبرة عجيبة دالة على قدرة الله، وما صار أكثر أتباع فرعون مؤمنين مع هذه العلامة الباهرة.", "isBasmala": false, "translation_en": "In that there is a sign, but most of them are not believers.", "translation_id": "Sesungguhnya pada yang demikian itu benar-benar merupakan suatu tanda yang besar (mukjizat) dan tetapi adalah kebanyakan mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 68, "text": "وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝٦٨", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وإن ربك لهو العزيز الرحيم، بعزته أهلك الكافرين المكذبين، وبرحمته نجَّى موسى ومَن معه أجمعين.", "isBasmala": false, "translation_en": "Surely, your Lord is the Almighty, the Merciful.", "translation_id": "Dan sesungguhnya Tuhanmu benar-benar Dialah Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 69, "text": "وَٱتۡلُ عَلَیۡهِمۡ نَبَأَ إِبۡرَ ٰهِیمَ ۝٦٩", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "واقصص على الكافرين - أيها الرسول - خبر إبراهيم حين قال لأبيه وقومه: أي شيء تعبدونه؟", "isBasmala": false, "translation_en": "And relate to them the story of Abraham.", "translation_id": "Dan bacakanlah kepada mereka kisah Ibrahim.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 70, "text": "إِذۡ قَالَ لِأَبِیهِ وَقَوۡمِهِۦ مَا تَعۡبُدُونَ ۝٧٠", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "واقصص على الكافرين - أيها الرسول - خبر إبراهيم حين قال لأبيه وقومه: أي شيء تعبدونه؟", "isBasmala": false, "translation_en": "When he said to his father and his people, \"What do you worship?\"", "translation_id": "Ketika ia berkata kepada bapaknya dan kaumnya: \"Apakah yang kamu sembah?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 71, "text": "قَالُوا۟ نَعۡبُدُ أَصۡنَامࣰا فَنَظَلُّ لَهَا عَـٰكِفِینَ ۝٧١", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قالوا: نعبد أصنامًا، فنَعْكُف على عبادتها.", "isBasmala": false, "translation_en": "They said, \"We worship idols, and we remain devoted to them.\"", "translation_id": "Mereka menjawab: \"Kami menyembah berhala-berhala dan kami senantiasa tekun menyembahnya\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 72, "text": "قَالَ هَلۡ یَسۡمَعُونَكُمۡ إِذۡ تَدۡعُونَ ۝٧٢", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم منبهًا على فساد مذهبهم: هل يسمعون دعاءكم إذ تدعونهم، أو يقدِّمون لكم نفعًا إذا عبدتموهم، أو يصيبونكم بضر إذا تركتم عبادتهم؟", "isBasmala": false, "translation_en": "He said, \"Do they hear you when you pray?", "translation_id": "Berkata Ibrahim: \"Apakah berhala-berhala itu mendengar (doa)mu sewaktu kamu berdoa (kepadanya)?,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 73, "text": "أَوۡ یَنفَعُونَكُمۡ أَوۡ یَضُرُّونَ ۝٧٣", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم منبهًا على فساد مذهبهم: هل يسمعون دعاءكم إذ تدعونهم، أو يقدِّمون لكم نفعًا إذا عبدتموهم، أو يصيبونكم بضر إذا تركتم عبادتهم؟", "isBasmala": false, "translation_en": "Or do they benefit you, or harm you?\"", "translation_id": "atau (dapatkah) mereka memberi manfaat kepadamu atau memberi mudharat?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 74, "text": "قَالُوا۟ بَلۡ وَجَدۡنَاۤ ءَابَاۤءَنَا كَذَ ٰلِكَ یَفۡعَلُونَ ۝٧٤", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قالوا: لا يكون منهم شيء من ذلك، ولكننا وجدنا آباءنا يعبدونهم، فقلَّدناهم فيما كانوا يفعلون.", "isBasmala": false, "translation_en": "They said, \"But we found our ancestors doing so.\"", "translation_id": "Mereka menjawab: \"(Bukan karena itu) sebenarnya kami mendapati nenek moyang kami berbuat demikian\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 75, "text": "قَالَ أَفَرَءَیۡتُم مَّا كُنتُمۡ تَعۡبُدُونَ ۝٧٥", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم: أفأبصرتم بتدبر ما كنتم تعبدون من الأصنام التي لا تسمع ولا تنفع ولا تضر، أنتم وآباؤكم الأقدمون من قبلكم؟ فإن ما تعبدونهم من دون الله أعداء لي، لكن رب العالمين ومالك أمرهم هو وحده الذي أعبده. هو الذي خلقني في أحسن صورة فهو يرشدني إلى مصالح الدنيا والآخرة، وهو الذي ينعم عليَّ بالطعام والشراب، وإذا أصابني مرض فهو الذي يَشْفيني ويعافيني منه، وهو الذي يميتني في الدينا بقبض روحي، ثم يحييني يوم القيامة، لا يقدر على ذلك أحد سواه، والذي أطمع أن يتجاوز عن ذنبي يوم الجزاء.", "isBasmala": false, "translation_en": "He said, \"Have you considered what you worship.", "translation_id": "Ibrahim berkata: \"Maka apakah kamu telah memperhatikan apa yang selalu kamu sembah,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 76, "text": "أَنتُمۡ وَءَابَاۤؤُكُمُ ٱلۡأَقۡدَمُونَ ۝٧٦", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم: أفأبصرتم بتدبر ما كنتم تعبدون من الأصنام التي لا تسمع ولا تنفع ولا تضر، أنتم وآباؤكم الأقدمون من قبلكم؟ فإن ما تعبدونهم من دون الله أعداء لي، لكن رب العالمين ومالك أمرهم هو وحده الذي أعبده. هو الذي خلقني في أحسن صورة فهو يرشدني إلى مصالح الدنيا والآخرة، وهو الذي ينعم عليَّ بالطعام والشراب، وإذا أصابني مرض فهو الذي يَشْفيني ويعافيني منه، وهو الذي يميتني في الدينا بقبض روحي، ثم يحييني يوم القيامة، لا يقدر على ذلك أحد سواه، والذي أطمع أن يتجاوز عن ذنبي يوم الجزاء.", "isBasmala": false, "translation_en": "You and your ancient ancestors?", "translation_id": "kamu dan nenek moyang kamu yang dahulu?,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 77, "text": "فَإِنَّهُمۡ عَدُوࣱّ لِّیۤ إِلَّا رَبَّ ٱلۡعَـٰلَمِینَ ۝٧٧", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم: أفأبصرتم بتدبر ما كنتم تعبدون من الأصنام التي لا تسمع ولا تنفع ولا تضر، أنتم وآباؤكم الأقدمون من قبلكم؟ فإن ما تعبدونهم من دون الله أعداء لي، لكن رب العالمين ومالك أمرهم هو وحده الذي أعبده. هو الذي خلقني في أحسن صورة فهو يرشدني إلى مصالح الدنيا والآخرة، وهو الذي ينعم عليَّ بالطعام والشراب، وإذا أصابني مرض فهو الذي يَشْفيني ويعافيني منه، وهو الذي يميتني في الدينا بقبض روحي، ثم يحييني يوم القيامة، لا يقدر على ذلك أحد سواه، والذي أطمع أن يتجاوز عن ذنبي يوم الجزاء.", "isBasmala": false, "translation_en": "They are enemies to me, but not so the Lord of the Worlds.", "translation_id": "karena sesungguhnya apa yang kamu sembah itu adalah musuhku, kecuali Tuhan Semesta Alam,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 78, "text": "ٱلَّذِی خَلَقَنِی فَهُوَ یَهۡدِینِ ۝٧٨", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم: أفأبصرتم بتدبر ما كنتم تعبدون من الأصنام التي لا تسمع ولا تنفع ولا تضر، أنتم وآباؤكم الأقدمون من قبلكم؟ فإن ما تعبدونهم من دون الله أعداء لي، لكن رب العالمين ومالك أمرهم هو وحده الذي أعبده. هو الذي خلقني في أحسن صورة فهو يرشدني إلى مصالح الدنيا والآخرة، وهو الذي ينعم عليَّ بالطعام والشراب، وإذا أصابني مرض فهو الذي يَشْفيني ويعافيني منه، وهو الذي يميتني في الدينا بقبض روحي، ثم يحييني يوم القيامة، لا يقدر على ذلك أحد سواه، والذي أطمع أن يتجاوز عن ذنبي يوم الجزاء.", "isBasmala": false, "translation_en": "He who created me, and guides me.", "translation_id": "(yaitu Tuhan) Yang telah menciptakan aku, maka Dialah yang menunjuki aku,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 79, "text": "وَٱلَّذِی هُوَ یُطۡعِمُنِی وَیَسۡقِینِ ۝٧٩", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم: أفأبصرتم بتدبر ما كنتم تعبدون من الأصنام التي لا تسمع ولا تنفع ولا تضر، أنتم وآباؤكم الأقدمون من قبلكم؟ فإن ما تعبدونهم من دون الله أعداء لي، لكن رب العالمين ومالك أمرهم هو وحده الذي أعبده. هو الذي خلقني في أحسن صورة فهو يرشدني إلى مصالح الدنيا والآخرة، وهو الذي ينعم عليَّ بالطعام والشراب، وإذا أصابني مرض فهو الذي يَشْفيني ويعافيني منه، وهو الذي يميتني في الدينا بقبض روحي، ثم يحييني يوم القيامة، لا يقدر على ذلك أحد سواه، والذي أطمع أن يتجاوز عن ذنبي يوم الجزاء.", "isBasmala": false, "translation_en": "He who feeds me, and waters me.", "translation_id": "dan Tuhanku, Yang Dia memberi makan dan minum kepadaku,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 80, "text": "وَإِذَا مَرِضۡتُ فَهُوَ یَشۡفِینِ ۝٨٠", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم: أفأبصرتم بتدبر ما كنتم تعبدون من الأصنام التي لا تسمع ولا تنفع ولا تضر، أنتم وآباؤكم الأقدمون من قبلكم؟ فإن ما تعبدونهم من دون الله أعداء لي، لكن رب العالمين ومالك أمرهم هو وحده الذي أعبده. هو الذي خلقني في أحسن صورة فهو يرشدني إلى مصالح الدنيا والآخرة، وهو الذي ينعم عليَّ بالطعام والشراب، وإذا أصابني مرض فهو الذي يَشْفيني ويعافيني منه، وهو الذي يميتني في الدينا بقبض روحي، ثم يحييني يوم القيامة، لا يقدر على ذلك أحد سواه، والذي أطمع أن يتجاوز عن ذنبي يوم الجزاء.", "isBasmala": false, "translation_en": "And when I get sick, He heals me.", "translation_id": "dan apabila aku sakit, Dialah Yang menyembuhkan aku,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 81, "text": "وَٱلَّذِی یُمِیتُنِی ثُمَّ یُحۡیِینِ ۝٨١", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم: أفأبصرتم بتدبر ما كنتم تعبدون من الأصنام التي لا تسمع ولا تنفع ولا تضر، أنتم وآباؤكم الأقدمون من قبلكم؟ فإن ما تعبدونهم من دون الله أعداء لي، لكن رب العالمين ومالك أمرهم هو وحده الذي أعبده. هو الذي خلقني في أحسن صورة فهو يرشدني إلى مصالح الدنيا والآخرة، وهو الذي ينعم عليَّ بالطعام والشراب، وإذا أصابني مرض فهو الذي يَشْفيني ويعافيني منه، وهو الذي يميتني في الدينا بقبض روحي، ثم يحييني يوم القيامة، لا يقدر على ذلك أحد سواه، والذي أطمع أن يتجاوز عن ذنبي يوم الجزاء.", "isBasmala": false, "translation_en": "He who makes me die, and then revives me.", "translation_id": "dan Yang akan mematikan aku, kemudian akan menghidupkan aku (kembali),", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 82, "text": "وَٱلَّذِیۤ أَطۡمَعُ أَن یَغۡفِرَ لِی خَطِیۤـَٔتِی یَوۡمَ ٱلدِّینِ ۝٨٢", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم: أفأبصرتم بتدبر ما كنتم تعبدون من الأصنام التي لا تسمع ولا تنفع ولا تضر، أنتم وآباؤكم الأقدمون من قبلكم؟ فإن ما تعبدونهم من دون الله أعداء لي، لكن رب العالمين ومالك أمرهم هو وحده الذي أعبده. هو الذي خلقني في أحسن صورة فهو يرشدني إلى مصالح الدنيا والآخرة، وهو الذي ينعم عليَّ بالطعام والشراب، وإذا أصابني مرض فهو الذي يَشْفيني ويعافيني منه، وهو الذي يميتني في الدينا بقبض روحي، ثم يحييني يوم القيامة، لا يقدر على ذلك أحد سواه، والذي أطمع أن يتجاوز عن ذنبي يوم الجزاء.", "isBasmala": false, "translation_en": "He who, I hope, will forgive my sins on the Day of the Reckoning.\"", "translation_id": "dan Yang amat kuinginkan akan mengampuni kesalahanku pada hari kiamat\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 83, "text": "رَبِّ هَبۡ لِی حُكۡمࣰا وَأَلۡحِقۡنِی بِٱلصَّـٰلِحِینَ ۝٨٣", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قال إبراهيم داعيًا ربه: ربِّ امنحني العلم والفهم، وألحقني بالصالحين، واجمع بيني وبينهم في الجنة.", "isBasmala": false, "translation_en": "\"My Lord! Grant me wisdom, and include me with the righteous.", "translation_id": "(Ibrahim berdoa): \"Ya Tuhanku, berikanlah kepadaku hikmah dan masukkanlah aku ke dalam golongan orang-orang yang saleh,", "manzil": 5, "manzil_display": ""}], "371": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 84, "text": "وَٱجۡعَل لِّی لِسَانَ صِدۡقࣲ فِی ٱلۡـَٔاخِرِینَ ۝٨٤", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "واجعل لي ثناء حسنًا وذكرًا جميلا في الذين يأتون بعدي إلى يوم القيامة.", "isBasmala": false, "translation_en": "And give me a reputation of truth among the others.", "translation_id": "dan jadikanlah aku buah tutur yang baik bagi orang-orang (yang datang) kemudian,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 85, "text": "وَٱجۡعَلۡنِی مِن وَرَثَةِ جَنَّةِ ٱلنَّعِیمِ ۝٨٥", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "واجعلني من عبادك الذين تورثهم نعيم الجنة.", "isBasmala": false, "translation_en": "And make me of the inheritors of the Garden of Bliss.", "translation_id": "dan jadikanlah aku termasuk orang-orang yang mempusakai surga yang penuh kenikmatan,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 86, "text": "وَٱغۡفِرۡ لِأَبِیۤ إِنَّهُۥ كَانَ مِنَ ٱلضَّاۤلِّینَ ۝٨٦", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وهذا دعاء من إبراهيم عليه السلام أن ينقذ الله أباه من الضلال إلى الهدى، فيغفر له ويتجاوز عنه، كما وعد إبراهيم أباه بالدعاء له، فلما تبيَّن له أنه مستمر في الكفر والشرك إلى أن يموت تبرَّأ منه.", "isBasmala": false, "translation_en": "And forgive my father-he was one of the misguided.", "translation_id": "dan ampunilah bapakku, karena sesungguhnya ia adalah termasuk golongan orang-orang yang sesat,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 87, "text": "وَلَا تُخۡزِنِی یَوۡمَ یُبۡعَثُونَ ۝٨٧", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "ولا تُلْحق بي الذل، يوم يخرج الناس من القبور للحساب والجزاء، يوم لا ينفع المال والبنون أحدًا من العباد، إلا مَن أتى الله بقلب سليم من الكفر والنفاق والرذيلة.", "isBasmala": false, "translation_en": "And do not disgrace me on the Day they are resurrected.", "translation_id": "dan janganlah Engkau hinakan aku pada hari mereka dibangkitkan,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 88, "text": "یَوۡمَ لَا یَنفَعُ مَالࣱ وَلَا بَنُونَ ۝٨٨", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "ولا تُلْحق بي الذل، يوم يخرج الناس من القبور للحساب والجزاء، يوم لا ينفع المال والبنون أحدًا من العباد، إلا مَن أتى الله بقلب سليم من الكفر والنفاق والرذيلة.", "isBasmala": false, "translation_en": "The Day when neither wealth nor children will help.", "translation_id": "(yaitu) di hari harta dan anak-anak laki-laki tidak berguna,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 89, "text": "إِلَّا مَنۡ أَتَى ٱللَّهَ بِقَلۡبࣲ سَلِیمࣲ ۝٨٩", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "ولا تُلْحق بي الذل، يوم يخرج الناس من القبور للحساب والجزاء، يوم لا ينفع المال والبنون أحدًا من العباد، إلا مَن أتى الله بقلب سليم من الكفر والنفاق والرذيلة.", "isBasmala": false, "translation_en": "Except for him who comes to God with a sound heart.\"", "translation_id": "kecuali orang-orang yang menghadap Allah dengan hati yang bersih,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 90, "text": "وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِینَ ۝٩٠", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وقُرِّبت الجنة للذين اجتنبوا الكفر والمعاصي، وأقبلوا على الله بالطاعة.", "isBasmala": false, "translation_en": "And Paradise will be brought near for the righteous.", "translation_id": "dan (di hari itu) didekatkanlah surga kepada orang-orang yang bertakwa,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 91, "text": "وَبُرِّزَتِ ٱلۡجَحِیمُ لِلۡغَاوِینَ ۝٩١", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وأُظهرت النار للكافرين الذين ضَلُّوا عن الهدى، وتجرَّؤوا على محارم الله وكذَّبوا رسله.", "isBasmala": false, "translation_en": "And the Blaze will be displayed to the deviators.", "translation_id": "dan diperlihatkan dengan jelas neraka Jahim kepada orang-orang yang sesat\",", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 92, "text": "وَقِیلَ لَهُمۡ أَیۡنَ مَا كُنتُمۡ تَعۡبُدُونَ ۝٩٢", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وقيل لهم توبيخًا: أين آلهتكم التي كنتم تعبدونها مِن دون الله، وتزعمون أنها تشفع لكم اليوم؟ هل ينصرونكم، فيدفعون العذاب عنكم، أو ينتصرون بدفع العذاب عن أنفسهم؟ لا شيء من ذلك.", "isBasmala": false, "translation_en": "And it will be said to them, \"Where are those you used to worship?\"", "translation_id": "dan dikatakan kepada mereka: \"Dimanakah berhala-berhala yang dahulu kamu selalu menyembah(nya)", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 93, "text": "مِن دُونِ ٱللَّهِ هَلۡ یَنصُرُونَكُمۡ أَوۡ یَنتَصِرُونَ ۝٩٣", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "وقيل لهم توبيخًا: أين آلهتكم التي كنتم تعبدونها مِن دون الله، وتزعمون أنها تشفع لكم اليوم؟ هل ينصرونكم، فيدفعون العذاب عنكم، أو ينتصرون بدفع العذاب عن أنفسهم؟ لا شيء من ذلك.", "isBasmala": false, "translation_en": "Besides God? Can they help you, or help themselves?\"", "translation_id": "selain dari Allah? Dapatkah mereka menolong kamu atau menolong diri mereka sendiri?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 94, "text": "فَكُبۡكِبُوا۟ فِیهَا هُمۡ وَٱلۡغَاوُۥنَ ۝٩٤", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فجُمِعوا وألقُوا في جهنم، هم والذين أضلوهم وأعوان إبليس الذين زيَّنوا لهم الشر، لم يُفْلِت منهم أحد.", "isBasmala": false, "translation_en": "Then they will be toppled into it, together with the seducers.", "translation_id": "Maka mereka (sembahan-sembahan itu) dijungkirkan ke dalam neraka bersama-sama orang-orang yang sesat,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 95, "text": "وَجُنُودُ إِبۡلِیسَ أَجۡمَعُونَ ۝٩٥", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فجُمِعوا وألقُوا في جهنم، هم والذين أضلوهم وأعوان إبليس الذين زيَّنوا لهم الشر، لم يُفْلِت منهم أحد.", "isBasmala": false, "translation_en": "And the soldiers of Satan, all of them.", "translation_id": "dan bala tentara iblis semuanya.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 96, "text": "قَالُوا۟ وَهُمۡ فِیهَا یَخۡتَصِمُونَ ۝٩٦", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قالوا معترفين بخطئهم، وهم يتنازعون في جهنم مع مَن أضلوهم، تالله إننا كنا في الدنيا في ضلال واضح لا خفاء فيه؛ إذ نسويكم برب العالمين المستحق للعبادة وحده. وما أوقعنا في هذا المصير السيِّئ إلا المجرمون الذين دعونا إلى عبادة غير الله فاتبعناهم.", "isBasmala": false, "translation_en": "They will say, as they feud in it.", "translation_id": "Mereka berkata sedang mereka bertengkar di dalam neraka:", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 97, "text": "تَٱللَّهِ إِن كُنَّا لَفِی ضَلَـٰلࣲ مُّبِینٍ ۝٩٧", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قالوا معترفين بخطئهم، وهم يتنازعون في جهنم مع مَن أضلوهم، تالله إننا كنا في الدنيا في ضلال واضح لا خفاء فيه؛ إذ نسويكم برب العالمين المستحق للعبادة وحده. وما أوقعنا في هذا المصير السيِّئ إلا المجرمون الذين دعونا إلى عبادة غير الله فاتبعناهم.", "isBasmala": false, "translation_en": "\"By God, We were in evident error.", "translation_id": "\"demi Allah: sungguh kita dahulu (di dunia) dalam kesesatan yang nyata,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 98, "text": "إِذۡ نُسَوِّیكُم بِرَبِّ ٱلۡعَـٰلَمِینَ ۝٩٨", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قالوا معترفين بخطئهم، وهم يتنازعون في جهنم مع مَن أضلوهم، تالله إننا كنا في الدنيا في ضلال واضح لا خفاء فيه؛ إذ نسويكم برب العالمين المستحق للعبادة وحده. وما أوقعنا في هذا المصير السيِّئ إلا المجرمون الذين دعونا إلى عبادة غير الله فاتبعناهم.", "isBasmala": false, "translation_en": "For equating you with the Lord of the Worlds.", "translation_id": "karena kita mempersamakan kamu dengan Tuhan semesta alam\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 99, "text": "وَمَاۤ أَضَلَّنَاۤ إِلَّا ٱلۡمُجۡرِمُونَ ۝٩٩", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "قالوا معترفين بخطئهم، وهم يتنازعون في جهنم مع مَن أضلوهم، تالله إننا كنا في الدنيا في ضلال واضح لا خفاء فيه؛ إذ نسويكم برب العالمين المستحق للعبادة وحده. وما أوقعنا في هذا المصير السيِّئ إلا المجرمون الذين دعونا إلى عبادة غير الله فاتبعناهم.", "isBasmala": false, "translation_en": "No one misled us except the sinners.", "translation_id": "Dan tiadalah yang menyesatkan kami kecuali orang-orang yang berdosa.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 100, "text": "فَمَا لَنَا مِن شَـٰفِعِینَ ۝١٠٠", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فلا أحدَ يشفع لنا، ويخلِّصنا من العذاب، ولا مَن يَصْدُق في مودتنا ويشفق علينا.", "isBasmala": false, "translation_en": "Now we have no intercessors.", "translation_id": "Maka kami tidak mempunyai pemberi syafa'at seorangpun,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 101, "text": "وَلَا صَدِیقٍ حَمِیمࣲ ۝١٠١", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فلا أحدَ يشفع لنا، ويخلِّصنا من العذاب، ولا مَن يَصْدُق في مودتنا ويشفق علينا.", "isBasmala": false, "translation_en": "And no sincere friend.", "translation_id": "dan tidak pula mempunyai teman yang akrab,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 102, "text": "فَلَوۡ أَنَّ لَنَا كَرَّةࣰ فَنَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ ۝١٠٢", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "فليت لنا رجعة إلى الدنيا، فنصير من جملة المؤمنين الناجين.", "isBasmala": false, "translation_en": "If only we could have another chance, we would be among the faithful.\"", "translation_id": "maka sekiranya kita dapat kembali sekali lagi (ke dunia) niscaya kami menjadi orang-orang yang beriman\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 103, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ ۝١٠٣", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "إن في نبأ إبراهيم السابق لَعبرة لِمن يعتبر، وما صار أكثر الذين سمعوا هذا النبأ مؤمنين. وإن ربك لهو العزيز القادر على الانتقام من المكذبين، الرحيم بعباده المؤمنين.", "isBasmala": false, "translation_en": "Surely in this is a sign, but most of them are not believers.", "translation_id": "Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 104, "text": "وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝١٠٤", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "إن في نبأ إبراهيم السابق لَعبرة لِمن يعتبر، وما صار أكثر الذين سمعوا هذا النبأ مؤمنين. وإن ربك لهو العزيز القادر على الانتقام من المكذبين، الرحيم بعباده المؤمنين.", "isBasmala": false, "translation_en": "Your Lord is the Almighty, the Merciful.", "translation_id": "Dan sesungguhnya Tuhanmu benar-benar Dialah Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 105, "text": "كَذَّبَتۡ قَوۡمُ نُوحٍ ٱلۡمُرۡسَلِینَ ۝١٠٥", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "كَذَّبت قوم نوح رسالة نبيهم، فكانوا بهذا مكذبين لجميع الرسل؛ لأن كل رسول يأمر بتصديق جميع الرسل. إذ قال لهم أخوهم نوح: ألا تخشون الله بترك عبادة غيره؟ إني لكم رسول أمين فيما أبلغكم، فاجعلوا الإيمان وقاية لكم من عذاب الله وأطيعوني فيما آمركم به من عبادته وحده. وما أطلب منكم أجرًا على تبليغ الرسالة، ما أجري إلا على رب العالمين، المتصرف في خلقه، فاحذروا عقابه، وأطيعوني بامتثال أوامره، واجتناب نواهيه.", "isBasmala": false, "translation_en": "The people of Noah disbelieved the messengers.", "translation_id": "Kaum Nuh telah mendustakan para rasul.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 106, "text": "إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ نُوحٌ أَلَا تَتَّقُونَ ۝١٠٦", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "كَذَّبت قوم نوح رسالة نبيهم، فكانوا بهذا مكذبين لجميع الرسل؛ لأن كل رسول يأمر بتصديق جميع الرسل. إذ قال لهم أخوهم نوح: ألا تخشون الله بترك عبادة غيره؟ إني لكم رسول أمين فيما أبلغكم، فاجعلوا الإيمان وقاية لكم من عذاب الله وأطيعوني فيما آمركم به من عبادته وحده. وما أطلب منكم أجرًا على تبليغ الرسالة، ما أجري إلا على رب العالمين، المتصرف في خلقه، فاحذروا عقابه، وأطيعوني بامتثال أوامره، واجتناب نواهيه.", "isBasmala": false, "translation_en": "Their brother Noah said to them, \"Do you not fear?", "translation_id": "Ketika saudara mereka (Nuh) berkata kepada mereka: \"Mengapa kamu tidak bertakwa?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 107, "text": "إِنِّی لَكُمۡ رَسُولٌ أَمِینࣱ ۝١٠٧", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "كَذَّبت قوم نوح رسالة نبيهم، فكانوا بهذا مكذبين لجميع الرسل؛ لأن كل رسول يأمر بتصديق جميع الرسل. إذ قال لهم أخوهم نوح: ألا تخشون الله بترك عبادة غيره؟ إني لكم رسول أمين فيما أبلغكم، فاجعلوا الإيمان وقاية لكم من عذاب الله وأطيعوني فيما آمركم به من عبادته وحده. وما أطلب منكم أجرًا على تبليغ الرسالة، ما أجري إلا على رب العالمين، المتصرف في خلقه، فاحذروا عقابه، وأطيعوني بامتثال أوامره، واجتناب نواهيه.", "isBasmala": false, "translation_en": "I am to you a faithful messenger.", "translation_id": "Sesungguhnya aku adalah seorang rasul kepercayaan (yang diutus) kepadamu,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 108, "text": "فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝١٠٨", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "كَذَّبت قوم نوح رسالة نبيهم، فكانوا بهذا مكذبين لجميع الرسل؛ لأن كل رسول يأمر بتصديق جميع الرسل. إذ قال لهم أخوهم نوح: ألا تخشون الله بترك عبادة غيره؟ إني لكم رسول أمين فيما أبلغكم، فاجعلوا الإيمان وقاية لكم من عذاب الله وأطيعوني فيما آمركم به من عبادته وحده. وما أطلب منكم أجرًا على تبليغ الرسالة، ما أجري إلا على رب العالمين، المتصرف في خلقه، فاحذروا عقابه، وأطيعوني بامتثال أوامره، واجتناب نواهيه.", "isBasmala": false, "translation_en": "So fear God, and obey me.", "translation_id": "maka bertakwalah kepada Allah dan taatlah kepadaku.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 109, "text": "وَمَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٠٩", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "كَذَّبت قوم نوح رسالة نبيهم، فكانوا بهذا مكذبين لجميع الرسل؛ لأن كل رسول يأمر بتصديق جميع الرسل. إذ قال لهم أخوهم نوح: ألا تخشون الله بترك عبادة غيره؟ إني لكم رسول أمين فيما أبلغكم، فاجعلوا الإيمان وقاية لكم من عذاب الله وأطيعوني فيما آمركم به من عبادته وحده. وما أطلب منكم أجرًا على تبليغ الرسالة، ما أجري إلا على رب العالمين، المتصرف في خلقه، فاحذروا عقابه، وأطيعوني بامتثال أوامره، واجتناب نواهيه.", "isBasmala": false, "translation_en": "I ask of you no payment for this. My payment is only from the Lord of the Worlds.", "translation_id": "Dan aku sekali-kali tidak minta upah kepadamu atas ajakan-ajakan itu; upahku tidak lain hanyalah dari Tuhan semesta alam.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 110, "text": "فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝١١٠", "juz": 19, "hizb": "(*¾ ح 37*)", "tafsir": "كَذَّبت قوم نوح رسالة نبيهم، فكانوا بهذا مكذبين لجميع الرسل؛ لأن كل رسول يأمر بتصديق جميع الرسل. إذ قال لهم أخوهم نوح: ألا تخشون الله بترك عبادة غيره؟ إني لكم رسول أمين فيما أبلغكم، فاجعلوا الإيمان وقاية لكم من عذاب الله وأطيعوني فيما آمركم به من عبادته وحده. وما أطلب منكم أجرًا على تبليغ الرسالة، ما أجري إلا على رب العالمين، المتصرف في خلقه، فاحذروا عقابه، وأطيعوني بامتثال أوامره، واجتناب نواهيه.", "isBasmala": false, "translation_en": "So fear God, and obey me.\"", "translation_id": "Maka bertakwalah kepada Allah dan taatlah kepadaku\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 111, "text": "۞ قَالُوۤا۟ أَنُؤۡمِنُ لَكَ وَٱتَّبَعَكَ ٱلۡأَرۡذَلُونَ ۝١١١", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "قال له قومه: كيف نصدِّقك ونتبعك، والذين اتبعوك أراذل الناس وأسافلهم؟", "isBasmala": false, "translation_en": "They said, \"Shall we believe in you, when it is the lowliest who follow you?\"", "translation_id": "Mereka berkata: \"Apakah kami akan beriman kepadamu, padahal yang mengikuti kamu ialah orang-orang yang hina?\".", "manzil": 5, "manzil_display": ""}], "372": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 112, "text": "قَالَ وَمَا عِلۡمِی بِمَا كَانُوا۟ یَعۡمَلُونَ ۝١١٢", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فأجابهم نوح عليه السلام بقوله: لست مكلفًا بمعرفة أعمالهم، إنما كُلفت أن أدعوهم إلى الإيمان. والاعتبار بالإيمان لا بالحسب والنسب والحِرف والصنائع.", "isBasmala": false, "translation_en": "He said, \"What do I know about what they do?", "translation_id": "Nuh menjawab: \"Bagaimana aku mengetahui apa yang telah mereka kerjakan?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 113, "text": "إِنۡ حِسَابُهُمۡ إِلَّا عَلَىٰ رَبِّیۖ لَوۡ تَشۡعُرُونَ ۝١١٣", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "ما حسابهم للجزاء على أعمالهم وبواطنهم إلا على ربي المطَّلِع على السرائر. لو كنتم تشعرون بذلك لما قلتم هذا الكلام.", "isBasmala": false, "translation_en": "Their account rests only with my Lord, if you have sense.", "translation_id": "Perhitungan (amal perbuatan) mereka tidak lain hanyalah kepada Tuhanku, kalau kamu menyadari.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 114, "text": "وَمَاۤ أَنَا۠ بِطَارِدِ ٱلۡمُؤۡمِنِینَ ۝١١٤", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "وما أنا بطارد الذين يؤمنون بدعوتي، مهما تكن حالهم؛ تلبية لرغبتكم كي تؤمنوا بي. ما أنا إلا نذير بيِّن الإنذار.", "isBasmala": false, "translation_en": "And I am not about to drive away the believers.", "translation_id": "Dan aku sekali-kali tidak akan mengusir orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 115, "text": "إِنۡ أَنَا۠ إِلَّا نَذِیرࣱ مُّبِینࣱ ۝١١٥", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "وما أنا بطارد الذين يؤمنون بدعوتي، مهما تكن حالهم؛ تلبية لرغبتكم كي تؤمنوا بي. ما أنا إلا نذير بيِّن الإنذار.", "isBasmala": false, "translation_en": "I am only a clear warner.\"", "translation_id": "Aku (ini) tidak lain melainkan pemberi peringatan yang menjelaskan\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 116, "text": "قَالُوا۟ لَىِٕن لَّمۡ تَنتَهِ یَـٰنُوحُ لَتَكُونَنَّ مِنَ ٱلۡمَرۡجُومِینَ ۝١١٦", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "عدل قوم نوح عن المحاورة إلى التهديد، فقالوا له: لئن لم ترجع- يا نوح- عن دعوتك لتكوننَّ مِنَ المقتولين رميًا بالحجارة.", "isBasmala": false, "translation_en": "They said, \"If you do not refrain, O Noah, you will be stoned.\"", "translation_id": "Mereka berkata: \"Sungguh jika kamu tidak (mau) berhenti hai Nuh, niscaya benar-benar kamu akan termasuk orang-orang yang dirajam\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 117, "text": "قَالَ رَبِّ إِنَّ قَوۡمِی كَذَّبُونِ ۝١١٧", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فلما سمع نوح قولهم هذا دعا ربه بقوله: رب إن قومي أصروا على تكذيـبي، فاحكم بيني وبينهم حكمًا تُهلك به مَن جحد توحيدك وكذَّب رسولك، ونجني ومَن معي من المؤمنين مما تعذب به الكافرين.", "isBasmala": false, "translation_en": "He said, \"My Lord, my people have denied me.", "translation_id": "Nuh berkata: \"Ya Tuhanku, sesungguhnya kaumku telah mendustakan aku;", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 118, "text": "فَٱفۡتَحۡ بَیۡنِی وَبَیۡنَهُمۡ فَتۡحࣰا وَنَجِّنِی وَمَن مَّعِیَ مِنَ ٱلۡمُؤۡمِنِینَ ۝١١٨", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فلما سمع نوح قولهم هذا دعا ربه بقوله: رب إن قومي أصروا على تكذيـبي، فاحكم بيني وبينهم حكمًا تُهلك به مَن جحد توحيدك وكذَّب رسولك، ونجني ومَن معي من المؤمنين مما تعذب به الكافرين.", "isBasmala": false, "translation_en": "So judge between me and them decisively, and deliver me and the believers who are with me.", "translation_id": "maka itu adakanlah suatu keputusan antaraku dan antara mereka, dan selamatkanlah aku dan orang-orang yang mukmin besertaku\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 119, "text": "فَأَنجَیۡنَـٰهُ وَمَن مَّعَهُۥ فِی ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ۝١١٩", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فأنجيناه ومَن معه في السفينة المملوءة بصنوف المخلوقات التي حملها معه.", "isBasmala": false, "translation_en": "So We delivered him and those with him in the laden Ark.", "translation_id": "Maka Kami selamatkan Nuh dan orang-orang yang besertanya di dalam kapal yang penuh muatan.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 120, "text": "ثُمَّ أَغۡرَقۡنَا بَعۡدُ ٱلۡبَاقِینَ ۝١٢٠", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "ثم أغرقنا بعد إنجاء نوح ومن معه الباقين، الذين لم يؤمنوا مِن قومه وردُّوا عليه النصيحة.", "isBasmala": false, "translation_en": "Then We drowned the rest.", "translation_id": "Kemudian sesudah itu Kami tenggelamkan orang-orang yang tinggal.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 121, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ ۝١٢١", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إن في نبأ نوح وما كان من إنجاء المؤمنين وإهلاك المكذبين لَعلامة وعبرةً عظيمة لمن بعدهم، وما كان أكثر الذين سمعوا هذه القصة مؤمنين بالله وبرسوله وشرعه.", "isBasmala": false, "translation_en": "In that is a sign, but most of them are not believers.", "translation_id": "Sesungguhnya pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 122, "text": "وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝١٢٢", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "وإن ربك لهو العزيز في انتقامه ممن كفر به وخالف أمره، الرحيم بعباده المؤمنين.", "isBasmala": false, "translation_en": "Your Lord is the Almighty, the Merciful.", "translation_id": "Dan sesungguhnya Tuhanmu Dialah Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 123, "text": "كَذَّبَتۡ عَادٌ ٱلۡمُرۡسَلِینَ ۝١٢٣", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "كذَّبت قبيلة عاد رسولهم هودًا- عليه السلام- فكانوا بهذا مكذِّبين لجميع الرسل؛ لاتحاد دعوتهم في أصولها وغايتها.", "isBasmala": false, "translation_en": "Aad disbelieved the messengers.", "translation_id": "Kaum 'Aad telah mendustakan para rasul.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 124, "text": "إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ هُودٌ أَلَا تَتَّقُونَ ۝١٢٤", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم هود: ألا تخشون الله فتخلصوا له العبادة؟ إني مرسَل إليكم لهدايتكم وإرشادكم، حفيظ على رسالة الله، أبلِّغها لكم كما أمرني ربي، فخافوا عقاب الله وأطيعوني فيما جئتكم به من عند الله. وما أطلب منكم على إرشادكم إلى التوحيد أيَّ نوع من أنواع الأجر، ما أجري إلا على رب العالمين.", "isBasmala": false, "translation_en": "When their brother Hud said to them, \"Do you not fear?", "translation_id": "Ketika saudara mereka Hud berkata kepada mereka: \"Mengapa kamu tidak bertakwa?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 125, "text": "إِنِّی لَكُمۡ رَسُولٌ أَمِینࣱ ۝١٢٥", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم هود: ألا تخشون الله فتخلصوا له العبادة؟ إني مرسَل إليكم لهدايتكم وإرشادكم، حفيظ على رسالة الله، أبلِّغها لكم كما أمرني ربي، فخافوا عقاب الله وأطيعوني فيما جئتكم به من عند الله. وما أطلب منكم على إرشادكم إلى التوحيد أيَّ نوع من أنواع الأجر، ما أجري إلا على رب العالمين.", "isBasmala": false, "translation_en": "I am to you a faithful messenger.", "translation_id": "Sesungguhnya aku adalah seorang rasul kepercayaan (yang diutus) kepadamu,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 126, "text": "فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝١٢٦", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم هود: ألا تخشون الله فتخلصوا له العبادة؟ إني مرسَل إليكم لهدايتكم وإرشادكم، حفيظ على رسالة الله، أبلِّغها لكم كما أمرني ربي، فخافوا عقاب الله وأطيعوني فيما جئتكم به من عند الله. وما أطلب منكم على إرشادكم إلى التوحيد أيَّ نوع من أنواع الأجر، ما أجري إلا على رب العالمين.", "isBasmala": false, "translation_en": "So fear God, and obey me.", "translation_id": "maka bertakwalah kepada Allah dan taatlah kepadaku.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 127, "text": "وَمَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٢٧", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم هود: ألا تخشون الله فتخلصوا له العبادة؟ إني مرسَل إليكم لهدايتكم وإرشادكم، حفيظ على رسالة الله، أبلِّغها لكم كما أمرني ربي، فخافوا عقاب الله وأطيعوني فيما جئتكم به من عند الله. وما أطلب منكم على إرشادكم إلى التوحيد أيَّ نوع من أنواع الأجر، ما أجري إلا على رب العالمين.", "isBasmala": false, "translation_en": "I ask of you no payment for this. My payment is only from the Lord of the Worlds.", "translation_id": "Dan sekali-kali aku tidak minta upah kepadamu atas ajakan itu; upahku tidak lain hanyalah dari Tuhan semesta alam.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 128, "text": "أَتَبۡنُونَ بِكُلِّ رِیعٍ ءَایَةࣰ تَعۡبَثُونَ ۝١٢٨", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "أتبنون بكل مكان مرتفع بناء عاليًا تشرفون منه فتسخرون مِنَ المارة؟ وذلك عبث وإسراف لا يعود عليكم بفائدة في الدين أو الدنيا، وتتخذون قصورًا منيعة وحصونًا مشيَّدة، كأنكم تخلدون في الدنيا ولا تموتون، وإذا بطشتم بأحد من الخلق قتلا أو ضربًا، فعلتم ذلك قاهرين ظالمين.", "isBasmala": false, "translation_en": "Do you build a monument on every height for vanity's sake?", "translation_id": "Apakah kamu mendirikan pada tiap-tiap tanah tinggi bangunan untuk bermain-main,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 129, "text": "وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمۡ تَخۡلُدُونَ ۝١٢٩", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "أتبنون بكل مكان مرتفع بناء عاليًا تشرفون منه فتسخرون مِنَ المارة؟ وذلك عبث وإسراف لا يعود عليكم بفائدة في الدين أو الدنيا، وتتخذون قصورًا منيعة وحصونًا مشيَّدة، كأنكم تخلدون في الدنيا ولا تموتون، وإذا بطشتم بأحد من الخلق قتلا أو ضربًا، فعلتم ذلك قاهرين ظالمين.", "isBasmala": false, "translation_en": "And you set up fortresses, hoping to live forever?", "translation_id": "dan kamu membuat benteng-benteng dengan maksud supaya kamu kekal (di dunia)?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 130, "text": "وَإِذَا بَطَشۡتُم بَطَشۡتُمۡ جَبَّارِینَ ۝١٣٠", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "أتبنون بكل مكان مرتفع بناء عاليًا تشرفون منه فتسخرون مِنَ المارة؟ وذلك عبث وإسراف لا يعود عليكم بفائدة في الدين أو الدنيا، وتتخذون قصورًا منيعة وحصونًا مشيَّدة، كأنكم تخلدون في الدنيا ولا تموتون، وإذا بطشتم بأحد من الخلق قتلا أو ضربًا، فعلتم ذلك قاهرين ظالمين.", "isBasmala": false, "translation_en": "And when you strike, you strike mercilessly?", "translation_id": "Dan apabila kamu menyiksa, maka kamu menyiksa sebagai orang-orang kejam dan bengis.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 131, "text": "فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝١٣١", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فخافوا الله، وامتثلوا ما أدعوكم إليه فإنه أنفع لكم، واخشوا الله الذي أعطاكم من أنواع النعم ما لا خفاء فيه عليكم، أعطاكم الأنعام: من الإبل والبقر والغنم، وأعطاكم الأولاد، وأعطاكم البساتين المثمرة، وفجَّر لكم الماء من العيون الجارية.", "isBasmala": false, "translation_en": "So fear God, and obey me.", "translation_id": "Maka bertakwalah kepada Allah dan taatlah kepadaku.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 132, "text": "وَٱتَّقُوا۟ ٱلَّذِیۤ أَمَدَّكُم بِمَا تَعۡلَمُونَ ۝١٣٢", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فخافوا الله، وامتثلوا ما أدعوكم إليه فإنه أنفع لكم، واخشوا الله الذي أعطاكم من أنواع النعم ما لا خفاء فيه عليكم، أعطاكم الأنعام: من الإبل والبقر والغنم، وأعطاكم الأولاد، وأعطاكم البساتين المثمرة، وفجَّر لكم الماء من العيون الجارية.", "isBasmala": false, "translation_en": "And reverence Him, who supplied you with everything you know.", "translation_id": "Dan bertakwalah kepada Allah yang telah menganugerahkan kepadamu apa yang kamu ketahui.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 133, "text": "أَمَدَّكُم بِأَنۡعَـٰمࣲ وَبَنِینَ ۝١٣٣", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فخافوا الله، وامتثلوا ما أدعوكم إليه فإنه أنفع لكم، واخشوا الله الذي أعطاكم من أنواع النعم ما لا خفاء فيه عليكم، أعطاكم الأنعام: من الإبل والبقر والغنم، وأعطاكم الأولاد، وأعطاكم البساتين المثمرة، وفجَّر لكم الماء من العيون الجارية.", "isBasmala": false, "translation_en": "He supplied you with livestock and children.", "translation_id": "Dia telah menganugerahkan kepadamu binatang-binatang ternak, dan anak-anak,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 134, "text": "وَجَنَّـٰتࣲ وَعُیُونٍ ۝١٣٤", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فخافوا الله، وامتثلوا ما أدعوكم إليه فإنه أنفع لكم، واخشوا الله الذي أعطاكم من أنواع النعم ما لا خفاء فيه عليكم، أعطاكم الأنعام: من الإبل والبقر والغنم، وأعطاكم الأولاد، وأعطاكم البساتين المثمرة، وفجَّر لكم الماء من العيون الجارية.", "isBasmala": false, "translation_en": "And gardens and springs.", "translation_id": "dan kebun-kebun dan mata air,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 135, "text": "إِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمٍ عَظِیمࣲ ۝١٣٥", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "قال هود- عليه السَّلام- محذرًا لهم: إني أخاف إن أصررتم على ما أنتم عليه من التكذيب والظلم وكُفْر النِّعم، أن ينزل الله بكم عذابًا في يوم تعظم شدته من هول عذابه.", "isBasmala": false, "translation_en": "I fear for you the punishment of an awesome Day.\"", "translation_id": "sesungguhnya aku takut kamu akan ditimpa azab hari yang besar\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 136, "text": "قَالُوا۟ سَوَاۤءٌ عَلَیۡنَاۤ أَوَعَظۡتَ أَمۡ لَمۡ تَكُن مِّنَ ٱلۡوَ ٰعِظِینَ ۝١٣٦", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "قالوا له: يستوي عندنا تذكيرك وتخويفك لنا وتركه، فلن نؤمن لك.", "isBasmala": false, "translation_en": "They said, \"It is the same for us, whether you lecture us, or do not lecture.", "translation_id": "Mereka menjawab: \"Adalah sama saja bagi kami, apakah kamu memberi nasehat atau tidak memberi nasehat,", "manzil": 5, "manzil_display": ""}], "373": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 137, "text": "إِنۡ هَـٰذَاۤ إِلَّا خُلُقُ ٱلۡأَوَّلِینَ ۝١٣٧", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "وقالوا: ما هذا الذي نحن عليه إلا دين الأولين وعاداتهم، وما نحن بمعذبين على ما نفعل مما حَذَّرْتنا منه من العذاب.", "isBasmala": false, "translation_en": "This is nothing but morals of the ancients.", "translation_id": "(agama kami) ini tidak lain hanyalah adat kebiasaan orang dahulu.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 138, "text": "وَمَا نَحۡنُ بِمُعَذَّبِینَ ۝١٣٨", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "وقالوا: ما هذا الذي نحن عليه إلا دين الأولين وعاداتهم، وما نحن بمعذبين على ما نفعل مما حَذَّرْتنا منه من العذاب.", "isBasmala": false, "translation_en": "And we will not be punished.\"", "translation_id": "dan kami sekali-kali tidak akan di \"azab\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 139, "text": "فَكَذَّبُوهُ فَأَهۡلَكۡنَـٰهُمۡۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ ۝١٣٩", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فاستمَرُّوا على تكذيبه، فأهلكهم الله بريح باردة شديدة. إن في ذلك الإهلاك لَعبرة لمن بعدهم، وما كان أكثر الذين سمعوا قصتهم مؤمنين بك. وإن ربك لهو العزيز الغالب على ما يريده من إهلاك المكذبين، الرحيم بالمؤمنين.", "isBasmala": false, "translation_en": "So they denied him, and We destroyed them. Surely in this is a sign, but most of them are not believers.", "translation_id": "Maka mereka mendustakan Hud, lalu Kami binasakan mereka. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 140, "text": "وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝١٤٠", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فاستمَرُّوا على تكذيبه، فأهلكهم الله بريح باردة شديدة. إن في ذلك الإهلاك لَعبرة لمن بعدهم، وما كان أكثر الذين سمعوا قصتهم مؤمنين بك. وإن ربك لهو العزيز الغالب على ما يريده من إهلاك المكذبين، الرحيم بالمؤمنين.", "isBasmala": false, "translation_en": "Your Lord is the Almighty, the Merciful.", "translation_id": "Dan sesungguhnya Tuhanmu, Dialah Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 141, "text": "كَذَّبَتۡ ثَمُودُ ٱلۡمُرۡسَلِینَ ۝١٤١", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "كذَّبت قبيلة ثمود أخاهم صالحًا في رسالته ودعوته إلى توحيد الله، فكانوا بهذا مكذِّبين لجميع الرسل؛ لأنهم جميعًا يدعون إلى توحيد الله.", "isBasmala": false, "translation_en": "Thamood disbelieved the messengers.", "translation_id": "Kaum Tsamud telah mendustakan rasul-rasul.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 142, "text": "إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ صَـٰلِحٌ أَلَا تَتَّقُونَ ۝١٤٢", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم صالح: ألا تخشون عقاب الله، فتُفرِدونه بالعبادة؟ إني مرسَل من الله إليكم، حفيظ على هذه الرسالة كما تلقيتها عن الله، فاحذروا عقابه تعالى، وامتثلوا ما دعوتكم إليه. وما أطلب منكم على نصحي وإرشادي لكم أي جزاء، ما جزائي إلا على رب العالمين.", "isBasmala": false, "translation_en": "When their brother Saleh said to them, \"Do you not fear?", "translation_id": "Ketika saudara mereka, Shaleh, berkata kepada mereka: \"Mengapa kamu tidak bertakwa?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 143, "text": "إِنِّی لَكُمۡ رَسُولٌ أَمِینࣱ ۝١٤٣", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم صالح: ألا تخشون عقاب الله، فتُفرِدونه بالعبادة؟ إني مرسَل من الله إليكم، حفيظ على هذه الرسالة كما تلقيتها عن الله، فاحذروا عقابه تعالى، وامتثلوا ما دعوتكم إليه. وما أطلب منكم على نصحي وإرشادي لكم أي جزاء، ما جزائي إلا على رب العالمين.", "isBasmala": false, "translation_en": "I am to you a faithful messenger.", "translation_id": "Sesungguhnya aku adalah seorang rasul kepercayaan (yang diutus) kepadamu,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 144, "text": "فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝١٤٤", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم صالح: ألا تخشون عقاب الله، فتُفرِدونه بالعبادة؟ إني مرسَل من الله إليكم، حفيظ على هذه الرسالة كما تلقيتها عن الله، فاحذروا عقابه تعالى، وامتثلوا ما دعوتكم إليه. وما أطلب منكم على نصحي وإرشادي لكم أي جزاء، ما جزائي إلا على رب العالمين.", "isBasmala": false, "translation_en": "So fear God, and obey me.", "translation_id": "maka bertakwalah kepada Allah dan taatlah kepadaku.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 145, "text": "وَمَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٤٥", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم صالح: ألا تخشون عقاب الله، فتُفرِدونه بالعبادة؟ إني مرسَل من الله إليكم، حفيظ على هذه الرسالة كما تلقيتها عن الله، فاحذروا عقابه تعالى، وامتثلوا ما دعوتكم إليه. وما أطلب منكم على نصحي وإرشادي لكم أي جزاء، ما جزائي إلا على رب العالمين.", "isBasmala": false, "translation_en": "I ask of you no payment for it. My payment is only from the Lord of the Worlds.", "translation_id": "Dan aku sekali-kali tidak minta upah kepadamu atas ajakan itu, upahku tidak lain hanyalah dari Tuhan semesta alam.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 146, "text": "أَتُتۡرَكُونَ فِی مَا هَـٰهُنَاۤ ءَامِنِینَ ۝١٤٦", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "أيترككم ربكم فيما أنتم فيه من النعيم مستقرين في هذه الدنيا آمنين من العذاب والزوال والموت؟ في حدائق مثمرة وعيون جارية وزروع كثيرة ونخل ثمرها يانع لين نضيج، وتنحتون من الجبال بيوتًا ماهرين بنحتها، أَشِرين بَطِرين.", "isBasmala": false, "translation_en": "Will you be left secure in what is here?", "translation_id": "Adakah kamu akan dibiarkan tinggal disini (di negeri kamu ini) dengan aman,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 147, "text": "فِی جَنَّـٰتࣲ وَعُیُونࣲ ۝١٤٧", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "أيترككم ربكم فيما أنتم فيه من النعيم مستقرين في هذه الدنيا آمنين من العذاب والزوال والموت؟ في حدائق مثمرة وعيون جارية وزروع كثيرة ونخل ثمرها يانع لين نضيج، وتنحتون من الجبال بيوتًا ماهرين بنحتها، أَشِرين بَطِرين.", "isBasmala": false, "translation_en": "In gardens and springs?", "translation_id": "di dalam kebun-kebun serta mata air,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 148, "text": "وَزُرُوعࣲ وَنَخۡلࣲ طَلۡعُهَا هَضِیمࣱ ۝١٤٨", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "أيترككم ربكم فيما أنتم فيه من النعيم مستقرين في هذه الدنيا آمنين من العذاب والزوال والموت؟ في حدائق مثمرة وعيون جارية وزروع كثيرة ونخل ثمرها يانع لين نضيج، وتنحتون من الجبال بيوتًا ماهرين بنحتها، أَشِرين بَطِرين.", "isBasmala": false, "translation_en": "And fields, and palm-trees whose fruits are delicious?", "translation_id": "dan tanam-tanaman dan pohon-pohon korma yang mayangnya lembut.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 149, "text": "وَتَنۡحِتُونَ مِنَ ٱلۡجِبَالِ بُیُوتࣰا فَـٰرِهِینَ ۝١٤٩", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "أيترككم ربكم فيما أنتم فيه من النعيم مستقرين في هذه الدنيا آمنين من العذاب والزوال والموت؟ في حدائق مثمرة وعيون جارية وزروع كثيرة ونخل ثمرها يانع لين نضيج، وتنحتون من الجبال بيوتًا ماهرين بنحتها، أَشِرين بَطِرين.", "isBasmala": false, "translation_en": "And you skillfully carve houses in the mountains?", "translation_id": "Dan kamu pahat sebagian dari gunung-gunung untuk dijadikan rumah-rumah dengan rajin;", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 150, "text": "فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝١٥٠", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فخافوا عقوبة الله، واقبلوا نصحي، ولا تنقادوا لأمر المسرفين على أنفسهم المتمادين في معصية الله الذين دأبوا على الإفساد في الأرض إفسادًا لا إصلاح فيه.", "isBasmala": false, "translation_en": "So fear God, and obey me.", "translation_id": "maka bertakwalah kepada Allah dan taatlah kepadaku;", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 151, "text": "وَلَا تُطِیعُوۤا۟ أَمۡرَ ٱلۡمُسۡرِفِینَ ۝١٥١", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فخافوا عقوبة الله، واقبلوا نصحي، ولا تنقادوا لأمر المسرفين على أنفسهم المتمادين في معصية الله الذين دأبوا على الإفساد في الأرض إفسادًا لا إصلاح فيه.", "isBasmala": false, "translation_en": "And do not obey the command of the extravagant.", "translation_id": "dan janganlah kamu mentaati perintah orang-orang yang melewati batas,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 152, "text": "ٱلَّذِینَ یُفۡسِدُونَ فِی ٱلۡأَرۡضِ وَلَا یُصۡلِحُونَ ۝١٥٢", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فخافوا عقوبة الله، واقبلوا نصحي، ولا تنقادوا لأمر المسرفين على أنفسهم المتمادين في معصية الله الذين دأبوا على الإفساد في الأرض إفسادًا لا إصلاح فيه.", "isBasmala": false, "translation_en": "Who spread turmoil on earth, and do not reform.\"", "translation_id": "yang membuat kerusakan di muka bumi dan tidak mengadakan perbaikan\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 153, "text": "قَالُوۤا۟ إِنَّمَاۤ أَنتَ مِنَ ٱلۡمُسَحَّرِینَ ۝١٥٣", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "قالت ثمود لنبيها صالح: ما أنت إلا من الذين سُحروا سِحْرًا كثيرًا، حتى غلب السحر على عقلك. ما أنت إلا فرد مماثل لنا في البشرية من بني آدم، فكيف تتميز علينا بالرسالة؟ فأت بحجة واضحة تدل على ثبوت رسالتك، إن كنت صادقًا في دعواك أن الله أرسلك إلينا.", "isBasmala": false, "translation_en": "They said, \"You are surely one of the bewitched.", "translation_id": "Mereka berkata: \"Sesungguhnya kamu adalah salah seorang dari orang-orang yang kena sihir;", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 154, "text": "مَاۤ أَنتَ إِلَّا بَشَرࣱ مِّثۡلُنَا فَأۡتِ بِـَٔایَةٍ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ ۝١٥٤", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "قالت ثمود لنبيها صالح: ما أنت إلا من الذين سُحروا سِحْرًا كثيرًا، حتى غلب السحر على عقلك. ما أنت إلا فرد مماثل لنا في البشرية من بني آدم، فكيف تتميز علينا بالرسالة؟ فأت بحجة واضحة تدل على ثبوت رسالتك، إن كنت صادقًا في دعواك أن الله أرسلك إلينا.", "isBasmala": false, "translation_en": "You are nothing but a man like us. So bring us a sign, if you are truthful.", "translation_id": "Kamu tidak lain melainkan seorang manusia seperti kami; maka datangkanlah sesuatu mukjizat, jika kamu memang termasuk orang-orang yang benar\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 155, "text": "قَالَ هَـٰذِهِۦ نَاقَةࣱ لَّهَا شِرۡبࣱ وَلَكُمۡ شِرۡبُ یَوۡمࣲ مَّعۡلُومࣲ ۝١٥٥", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "قال لهم صالح- وقد أتاهم بناقة أخرجها الله له من الصخرة-: هذه ناقة الله لها نصيب من الماء في يوم معلوم، ولكم نصيب منه في يوم آخر. ليس لكم أن تشربوا في اليوم الذي هو نصيبها، ولا هي تشرب في اليوم الذي هو نصيبكم، ولا تنالوها بشيء مما يسوءها كضَرْبٍ أو قتل أو نحو ذلك، فيهلككم الله بعذابِ يومٍ تعظم شدته؛ بسبب ما يقع فيه من الهول والشدة.", "isBasmala": false, "translation_en": "He said, \"This is a she-camel; she has her turn of drinking, and you have your turn of drinking-on a specified day.", "translation_id": "Shaleh menjawab: \"Ini seekor unta betina, ia mempunyai giliran untuk mendapatkan air, dan kamu mempunyai giliran pula untuk mendapatkan air di hari yang tertentu.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 156, "text": "وَلَا تَمَسُّوهَا بِسُوۤءࣲ فَیَأۡخُذَكُمۡ عَذَابُ یَوۡمٍ عَظِیمࣲ ۝١٥٦", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "قال لهم صالح- وقد أتاهم بناقة أخرجها الله له من الصخرة-: هذه ناقة الله لها نصيب من الماء في يوم معلوم، ولكم نصيب منه في يوم آخر. ليس لكم أن تشربوا في اليوم الذي هو نصيبها، ولا هي تشرب في اليوم الذي هو نصيبكم، ولا تنالوها بشيء مما يسوءها كضَرْبٍ أو قتل أو نحو ذلك، فيهلككم الله بعذابِ يومٍ تعظم شدته؛ بسبب ما يقع فيه من الهول والشدة.", "isBasmala": false, "translation_en": "And do not touch her with harm, lest the punishment of a great day seizes you.\"", "translation_id": "Dan janganlah kamu sentuh unta betina itu dengan sesuatu kejahatan, yang menyebabkan kamu akan ditimpa oleh azab hari yang besar\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 157, "text": "فَعَقَرُوهَا فَأَصۡبَحُوا۟ نَـٰدِمِینَ ۝١٥٧", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فنحروا الناقة، فأصبحوا متحسرين على ما فعلوا لَمَّا أيقنوا بالعذاب، فلم ينفعهم ندمهم.", "isBasmala": false, "translation_en": "But they slaughtered her, and became full of remorse.", "translation_id": "Kemudian mereka membunuhnya, lalu mereka menjadi menyesal,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 158, "text": "فَأَخَذَهُمُ ٱلۡعَذَابُۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ ۝١٥٨", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فنزل بهم عذاب الله الذي توعدهم به صالح عليه السلام، فأهلكهم. إن في إهلاك ثمود لَعبرة لمن اعتبر بهذا المصير، وما كان أكثرهم مؤمنين.", "isBasmala": false, "translation_en": "So the punishment overtook them. Surely in this is a sign, but most of them are not believers.", "translation_id": "maka mereka ditimpa azab. Sesungguhnya pada yang demikian itu benar-benar terdapat bukti yang nyata. Dan adalah kebanyakan mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 159, "text": "وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝١٥٩", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "وإن ربك لهو العزيز القاهر المنتقم من أعدائه المكذبين، الرحيم بمن آمن من خلقه.", "isBasmala": false, "translation_en": "Your Lord is the Almighty, the Merciful.", "translation_id": "Dan sesungguhnya Tuhanmu benar-benar Dialah Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}], "374": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 160, "text": "كَذَّبَتۡ قَوۡمُ لُوطٍ ٱلۡمُرۡسَلِینَ ۝١٦٠", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "كَذَّبت قوم لوط برسالته، فكانوا بهذا مكذبين لسائر رسل الله؛ لأن ما جاؤوا به من التوحيد وأصول الشرائع واحد.", "isBasmala": false, "translation_en": "The people of Lot disbelieved the messengers.", "translation_id": "Kaum Luth telah mendustakan rasul-rasul,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 161, "text": "إِذۡ قَالَ لَهُمۡ أَخُوهُمۡ لُوطٌ أَلَا تَتَّقُونَ ۝١٦١", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم لوط: ألا تخشون عذاب الله؟ إني رسول من ربكم، أمين على تبليغ رسالته إليكم، فاحذروا عقاب الله على تكذيبكم رسوله، واتبعوني فيما دعوتكم إليه، وما أسألكم على دعوتي لهدايتكم أيَّ أجر، ما أجري إلا على رب العالمين.", "isBasmala": false, "translation_en": "When their brother Lot said to them, \"Do you not fear?", "translation_id": "ketika saudara mereka, Luth, berkata kepada mereka: mengapa kamu tidak bertakwa?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 162, "text": "إِنِّی لَكُمۡ رَسُولٌ أَمِینࣱ ۝١٦٢", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم لوط: ألا تخشون عذاب الله؟ إني رسول من ربكم، أمين على تبليغ رسالته إليكم، فاحذروا عقاب الله على تكذيبكم رسوله، واتبعوني فيما دعوتكم إليه، وما أسألكم على دعوتي لهدايتكم أيَّ أجر، ما أجري إلا على رب العالمين.", "isBasmala": false, "translation_en": "I am to you a faithful messenger.", "translation_id": "Sesungguhnya aku adalah seorang rasul kepercayaan (yang diutus) kepadamu,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 163, "text": "فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝١٦٣", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم لوط: ألا تخشون عذاب الله؟ إني رسول من ربكم، أمين على تبليغ رسالته إليكم، فاحذروا عقاب الله على تكذيبكم رسوله، واتبعوني فيما دعوتكم إليه، وما أسألكم على دعوتي لهدايتكم أيَّ أجر، ما أجري إلا على رب العالمين.", "isBasmala": false, "translation_en": "So fear God, and obey me.", "translation_id": "maka bertakwalah kepada Allah dan taatlah kepadaku.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 164, "text": "وَمَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٦٤", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إذ قال لهم أخوهم لوط: ألا تخشون عذاب الله؟ إني رسول من ربكم، أمين على تبليغ رسالته إليكم، فاحذروا عقاب الله على تكذيبكم رسوله، واتبعوني فيما دعوتكم إليه، وما أسألكم على دعوتي لهدايتكم أيَّ أجر، ما أجري إلا على رب العالمين.", "isBasmala": false, "translation_en": "I ask of you no payment for it. My payment is only from the Lord of the Worlds.", "translation_id": "Dan aku sekali-kali tidak minta upah kepadamu atas ajakan itu; upahku tidak lain hanyalah dari Tuhan semeta alam.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 165, "text": "أَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَـٰلَمِینَ ۝١٦٥", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "أتنكحون الذكور مِن بني آدم، وتتركون ما خلق الله لاستمتاعكم وتناسلكم مِن أزواجكم؟ بل أنتم قوم - بهذه المعصية- متجاوزون ما أباحه الله لكم من الحلال إلى الحرام.", "isBasmala": false, "translation_en": "Do you approach the males of the world?", "translation_id": "Mengapa kamu mendatangi jenis lelaki di antara manusia,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 166, "text": "وَتَذَرُونَ مَا خَلَقَ لَكُمۡ رَبُّكُم مِّنۡ أَزۡوَ ٰجِكُمۚ بَلۡ أَنتُمۡ قَوۡمٌ عَادُونَ ۝١٦٦", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "أتنكحون الذكور مِن بني آدم، وتتركون ما خلق الله لاستمتاعكم وتناسلكم مِن أزواجكم؟ بل أنتم قوم - بهذه المعصية- متجاوزون ما أباحه الله لكم من الحلال إلى الحرام.", "isBasmala": false, "translation_en": "And forsake the wives your Lord created for you? Indeed, you are intrusive people.\"", "translation_id": "dan kamu tinggalkan isteri-isteri yang dijadikan oleh Tuhanmu untukmu, bahkan kamu adalah orang-orang yang melampaui batas\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 167, "text": "قَالُوا۟ لَىِٕن لَّمۡ تَنتَهِ یَـٰلُوطُ لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِینَ ۝١٦٧", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "قال قوم لوط: لئن لم تترك يا لوط نَهْيَنا عن إتيان الذكور وتقبيح فعله، لتكونن من المطرودين من بلادنا.", "isBasmala": false, "translation_en": "They said, \"Unless you refrain, O Lot, you will be expelled.\"", "translation_id": "Mereka menjawab: \"Hai Luth, sesungguhnya jika kamu tidak berhenti, benar-benar kamu termasuk orang-orang yang diusir\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 168, "text": "قَالَ إِنِّی لِعَمَلِكُم مِّنَ ٱلۡقَالِینَ ۝١٦٨", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "قال لوط لهم: إني لِعملكم الذي تعملونه من إتيان الذكور، لَمن المبغضين له بغضًا شديدًا.", "isBasmala": false, "translation_en": "He said, \"I certainly deplore your conduct.\"", "translation_id": "Luth berkata: \"Sesungguhnya aku sangat benci kepada perbuatanmu\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 169, "text": "رَبِّ نَجِّنِی وَأَهۡلِی مِمَّا یَعۡمَلُونَ ۝١٦٩", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "ثم دعا لوط ربه حينما يئس من استجابتهم له قائلا ربِّ أنقذني وأنقذ أهلي مما يعمله قومي مِن هذه المعصية القبيحة، ومِن عقوبتك التي ستصيبهم.", "isBasmala": false, "translation_en": "\"My Lord, save me and my family from what they do.\"", "translation_id": "(Luth berdoa): \"Ya Tuhanku selamatkanlah aku beserta keluargaku dari (akibat) perbuatan yang mereka kerjakan\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 170, "text": "فَنَجَّیۡنَـٰهُ وَأَهۡلَهُۥۤ أَجۡمَعِینَ ۝١٧٠", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فنجيناه وأهل بيته والمستجيبين لدعوته أجمعين إلا عجوزًا من أهله، وهي امرأته، لم تشاركهم في الإيمان، فكانت من الباقين في العذاب والهلاك.", "isBasmala": false, "translation_en": "So We saved him and his family, altogether.", "translation_id": "Lalu Kami selamatkan ia beserta keluarganya semua,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 171, "text": "إِلَّا عَجُوزࣰا فِی ٱلۡغَـٰبِرِینَ ۝١٧١", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "فنجيناه وأهل بيته والمستجيبين لدعوته أجمعين إلا عجوزًا من أهله، وهي امرأته، لم تشاركهم في الإيمان، فكانت من الباقين في العذاب والهلاك.", "isBasmala": false, "translation_en": "Except for an old woman among those who tarried.", "translation_id": "kecuali seorang perempuan tua (isterinya), yang termasuk dalam golongan yang tinggal.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 172, "text": "ثُمَّ دَمَّرۡنَا ٱلۡـَٔاخَرِینَ ۝١٧٢", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "ثم أهلكنا مَن عداهم من الكفرة أشدَّ إهلاك، وأنزلنا عليهم حجارة من السماء كالمطر أهلكتهم، فقَبُحَ مطرُ من أنذرهم رسلهم ولم يستجيبوا لهم؛ فقد أُنزل بهم أشدُّ أنواع الهلاك والتدمير.", "isBasmala": false, "translation_en": "Then We destroyed the others.", "translation_id": "Kemudian Kami binasakan yang lain.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 173, "text": "وَأَمۡطَرۡنَا عَلَیۡهِم مَّطَرࣰاۖ فَسَاۤءَ مَطَرُ ٱلۡمُنذَرِینَ ۝١٧٣", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "ثم أهلكنا مَن عداهم من الكفرة أشدَّ إهلاك، وأنزلنا عليهم حجارة من السماء كالمطر أهلكتهم، فقَبُحَ مطرُ من أنذرهم رسلهم ولم يستجيبوا لهم؛ فقد أُنزل بهم أشدُّ أنواع الهلاك والتدمير.", "isBasmala": false, "translation_en": "And We rained down on them a rain. Dreadful is the rain of those forewarned.", "translation_id": "Dan Kami hujani mereka dengan hujan (batu) maka amat jeleklah hujan yang menimpa orang-orang yang telah diberi peringatan itu.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 174, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ ۝١٧٤", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "إن في ذلك العقاب الذي نزل بقوم لوط لَعبرة وموعظة، يتعظ بها المكذبون. وما كان أكثرهم مؤمنين.", "isBasmala": false, "translation_en": "Surely in this is a sign, but most of them are not believers.", "translation_id": "Sesunguhnya pada yang demikian itu benar-benar terdapat bukti-bukti yang nyata. Dan adalah kebanyakan mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 175, "text": "وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝١٧٥", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "وإن ربك لهو العزيز الغالب الذي يقهر المكذبين، الرحيم بعباده المؤمنين.", "isBasmala": false, "translation_en": "Your Lord is the Almighty, the Merciful.", "translation_id": "Dan sesungguhnya Tuhanmu, benar-benar Dialah Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 176, "text": "كَذَّبَ أَصۡحَـٰبُ لۡـَٔیۡكَةِ ٱلۡمُرۡسَلِینَ ۝١٧٦", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "كذَّب أصحاب الأرض ذات الشجر الملتف رسولهم شعيبًا في رسالته، فكانوا بهذا مكذِّبين لجميع الرسالات. إذ قال لهم شعيب: ألا تخشون عقاب الله على شرككم ومعاصيكم؟ إني مرسَل إليكم مِنَ الله لهدايتكم، حفيظ على ما أوحى الله به إليَّ من الرسالة، فخافوا عقاب الله، واتبعوا ما دعوتكم إليه مِن هداية الله؛ لترشدوا، وما أطلب منكم على دعائي لكم إلى الإيمان بالله أيَّ جزاء، ما جزائي إلا على رب العالمين.", "isBasmala": false, "translation_en": "The People of the Woods disbelieved the messengers.", "translation_id": "Penduduk Aikah telah mendustakan rasul-rasul;", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 177, "text": "إِذۡ قَالَ لَهُمۡ شُعَیۡبٌ أَلَا تَتَّقُونَ ۝١٧٧", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "كذَّب أصحاب الأرض ذات الشجر الملتف رسولهم شعيبًا في رسالته، فكانوا بهذا مكذِّبين لجميع الرسالات. إذ قال لهم شعيب: ألا تخشون عقاب الله على شرككم ومعاصيكم؟ إني مرسَل إليكم مِنَ الله لهدايتكم، حفيظ على ما أوحى الله به إليَّ من الرسالة، فخافوا عقاب الله، واتبعوا ما دعوتكم إليه مِن هداية الله؛ لترشدوا، وما أطلب منكم على دعائي لكم إلى الإيمان بالله أيَّ جزاء، ما جزائي إلا على رب العالمين.", "isBasmala": false, "translation_en": "When Shuaib said to them, \"Do you not fear?", "translation_id": "ketika Syu'aib berkata kepada mereka: \"Mengapa kamu tidak bertakwa?,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 178, "text": "إِنِّی لَكُمۡ رَسُولٌ أَمِینࣱ ۝١٧٨", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "كذَّب أصحاب الأرض ذات الشجر الملتف رسولهم شعيبًا في رسالته، فكانوا بهذا مكذِّبين لجميع الرسالات. إذ قال لهم شعيب: ألا تخشون عقاب الله على شرككم ومعاصيكم؟ إني مرسَل إليكم مِنَ الله لهدايتكم، حفيظ على ما أوحى الله به إليَّ من الرسالة، فخافوا عقاب الله، واتبعوا ما دعوتكم إليه مِن هداية الله؛ لترشدوا، وما أطلب منكم على دعائي لكم إلى الإيمان بالله أيَّ جزاء، ما جزائي إلا على رب العالمين.", "isBasmala": false, "translation_en": "I am to you a trustworthy messenger.", "translation_id": "Sesungguhnya aku adalah seorang rasul kepercayaan (yang diutus) kepadamu.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 179, "text": "فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝١٧٩", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "كذَّب أصحاب الأرض ذات الشجر الملتف رسولهم شعيبًا في رسالته، فكانوا بهذا مكذِّبين لجميع الرسالات. إذ قال لهم شعيب: ألا تخشون عقاب الله على شرككم ومعاصيكم؟ إني مرسَل إليكم مِنَ الله لهدايتكم، حفيظ على ما أوحى الله به إليَّ من الرسالة، فخافوا عقاب الله، واتبعوا ما دعوتكم إليه مِن هداية الله؛ لترشدوا، وما أطلب منكم على دعائي لكم إلى الإيمان بالله أيَّ جزاء، ما جزائي إلا على رب العالمين.", "isBasmala": false, "translation_en": "So fear God, and obey me.", "translation_id": "maka bertakwalah kepada Allah dan taatlah kepadaku;", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 180, "text": "وَمَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرٍۖ إِنۡ أَجۡرِیَ إِلَّا عَلَىٰ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٨٠", "juz": 19, "hizb": "(* ح 38*)", "tafsir": "كذَّب أصحاب الأرض ذات الشجر الملتف رسولهم شعيبًا في رسالته، فكانوا بهذا مكذِّبين لجميع الرسالات. إذ قال لهم شعيب: ألا تخشون عقاب الله على شرككم ومعاصيكم؟ إني مرسَل إليكم مِنَ الله لهدايتكم، حفيظ على ما أوحى الله به إليَّ من الرسالة، فخافوا عقاب الله، واتبعوا ما دعوتكم إليه مِن هداية الله؛ لترشدوا، وما أطلب منكم على دعائي لكم إلى الإيمان بالله أيَّ جزاء، ما جزائي إلا على رب العالمين.", "isBasmala": false, "translation_en": "I ask of you no payment for it. My payment is only from the Lord of the Worlds.", "translation_id": "dan aku sekali-kali tidak minta upah kepadamu atas ajakan itu; upahku tidak lain hanyalah dari Tuhan semesta alam.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 181, "text": "۞ أَوۡفُوا۟ ٱلۡكَیۡلَ وَلَا تَكُونُوا۟ مِنَ ٱلۡمُخۡسِرِینَ ۝١٨١", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "قال لهم شعيب- وقد كانوا يُنْقِصون الكيل والميزان-: أتمُّوا الكيل للناس وافيًا لهم، ولا تكونوا ممن يُنْقِصون الناس حقوقهم، وَزِنوا بالميزان العدل المستقيم، ولا تنقصوا الناس شيئًا مِن حقوقهم في كيل أو وزن أو غير ذلك، ولا تكثروا في الأرض الفساد، بالشرك والقتل والنهب وتخويف الناس وارتكاب المعاصي.", "isBasmala": false, "translation_en": "Give full measure, and do not cheat.", "translation_id": "Sempurnakanlah takaran dan janganlah kamu termasuk orang-orang yang merugikan;", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 182, "text": "وَزِنُوا۟ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِیمِ ۝١٨٢", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "قال لهم شعيب- وقد كانوا يُنْقِصون الكيل والميزان-: أتمُّوا الكيل للناس وافيًا لهم، ولا تكونوا ممن يُنْقِصون الناس حقوقهم، وَزِنوا بالميزان العدل المستقيم، ولا تنقصوا الناس شيئًا مِن حقوقهم في كيل أو وزن أو غير ذلك، ولا تكثروا في الأرض الفساد، بالشرك والقتل والنهب وتخويف الناس وارتكاب المعاصي.", "isBasmala": false, "translation_en": "And weigh with accurate scales.", "translation_id": "dan timbanglah dengan timbangan yang lurus.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 183, "text": "وَلَا تَبۡخَسُوا۟ ٱلنَّاسَ أَشۡیَاۤءَهُمۡ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ ۝١٨٣", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "قال لهم شعيب- وقد كانوا يُنْقِصون الكيل والميزان-: أتمُّوا الكيل للناس وافيًا لهم، ولا تكونوا ممن يُنْقِصون الناس حقوقهم، وَزِنوا بالميزان العدل المستقيم، ولا تنقصوا الناس شيئًا مِن حقوقهم في كيل أو وزن أو غير ذلك، ولا تكثروا في الأرض الفساد، بالشرك والقتل والنهب وتخويف الناس وارتكاب المعاصي.", "isBasmala": false, "translation_en": "And do not defraud people of their belongings, and do not work corruption in the land.", "translation_id": "Dan janganlah kamu merugikan manusia pada hak-haknya dan janganlah kamu merajalela di muka bumi dengan membuat kerusakan;", "manzil": 5, "manzil_display": ""}], "375": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 184, "text": "وَٱتَّقُوا۟ ٱلَّذِی خَلَقَكُمۡ وَٱلۡجِبِلَّةَ ٱلۡأَوَّلِینَ ۝١٨٤", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "واحذروا عقوبة الله الذي خلقكم وخلق الأمم المتقدمة عليكم.", "isBasmala": false, "translation_en": "And fear Him who created you and the masses of old.\"", "translation_id": "dan bertakwalah kepada Allah yang telah menciptakan kamu dan umat-umat yang dahulu\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 185, "text": "قَالُوۤا۟ إِنَّمَاۤ أَنتَ مِنَ ٱلۡمُسَحَّرِینَ ۝١٨٥", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "قالوا: إنما أنت- يا شعيب- مِنَ الذين أصابهم السحر إصابة شديدة، فذهب بعقولهم، وما أنت إلا واحد مثلنا في البشرية، فكيف تختص دوننا بالرسالة؟ وإن أكبر ظننا أنك من الكاذبين فيما تدَّعيه من الرسالة. فإن كنت صادقًا في دعوى النبوة، فادع الله أن يسقط علينا قطع عذاب من السماء تستأصلنا.", "isBasmala": false, "translation_en": "They said, \"You are one of those bewitched.", "translation_id": "Mereka berkata: \"Sesungguhnya kamu adalah salah seorang dari orang-orang yang kena sihir,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 186, "text": "وَمَاۤ أَنتَ إِلَّا بَشَرࣱ مِّثۡلُنَا وَإِن نَّظُنُّكَ لَمِنَ ٱلۡكَـٰذِبِینَ ۝١٨٦", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "قالوا: إنما أنت- يا شعيب- مِنَ الذين أصابهم السحر إصابة شديدة، فذهب بعقولهم، وما أنت إلا واحد مثلنا في البشرية، فكيف تختص دوننا بالرسالة؟ وإن أكبر ظننا أنك من الكاذبين فيما تدَّعيه من الرسالة. فإن كنت صادقًا في دعوى النبوة، فادع الله أن يسقط علينا قطع عذاب من السماء تستأصلنا.", "isBasmala": false, "translation_en": "And you are nothing but a man like us; and we think that you are a liar.", "translation_id": "dan kamu tidak lain melainkan seorang manusia seperti kami, dan sesungguhnya kami yakin bahwa kamu benar-benar termasuk orang-orang yang berdusta.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 187, "text": "فَأَسۡقِطۡ عَلَیۡنَا كِسَفࣰا مِّنَ ٱلسَّمَاۤءِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ ۝١٨٧", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "قالوا: إنما أنت- يا شعيب- مِنَ الذين أصابهم السحر إصابة شديدة، فذهب بعقولهم، وما أنت إلا واحد مثلنا في البشرية، فكيف تختص دوننا بالرسالة؟ وإن أكبر ظننا أنك من الكاذبين فيما تدَّعيه من الرسالة. فإن كنت صادقًا في دعوى النبوة، فادع الله أن يسقط علينا قطع عذاب من السماء تستأصلنا.", "isBasmala": false, "translation_en": "So bring down on us pieces from the sky, if you are truthful.\"", "translation_id": "Maka jatuhkanlah atas kami gumpalan dari langit, jika kamu termasuk orang-orang yang benar.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 188, "text": "قَالَ رَبِّیۤ أَعۡلَمُ بِمَا تَعۡمَلُونَ ۝١٨٨", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "قال لهم شعيب: ربي أعلم بما تعملونه مِنَ الشرك والمعاصي، وبما تستوجبونه من العقاب.", "isBasmala": false, "translation_en": "He said, \"My Lord is Well Aware of what you do.\"", "translation_id": "Syu'aib berkata: \"Tuhanku lebih mengetahui apa yang kamu kerjakan\".", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 189, "text": "فَكَذَّبُوهُ فَأَخَذَهُمۡ عَذَابُ یَوۡمِ ٱلظُّلَّةِۚ إِنَّهُۥ كَانَ عَذَابَ یَوۡمٍ عَظِیمٍ ۝١٨٩", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "فاستمَرُّوا على تكذيبه، فأصابهم الحر الشديد، وصاروا يبحثون عن ملاذ يستظلون به، فأظلتهم سحابة، وجدوا لها بردًا ونسيمًا، فلما اجتمعوا تحتها، التهبت عليهم نارًا فأحرقتهم، فكان هلاكهم جميعًا في يوم شديد الهول.", "isBasmala": false, "translation_en": "But they denied him. So the punishment of the day of gloom gripped them. It was the punishment of a great day.", "translation_id": "Kemudian mereka mendustakan Syu'aib, lalu mereka ditimpa azab pada hari mereka dinaungi awan. Sesungguhnya azab itu adalah azab hari yang besar.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 190, "text": "إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰۖ وَمَا كَانَ أَكۡثَرُهُم مُّؤۡمِنِینَ ۝١٩٠", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "إن في ذلك العقاب الذي نزل بهم، لَدلالة واضحة على قدرة الله في مؤاخذة المكذبين، وعبرة لمن يعتبر، وما كان أكثرهم مؤمنين متعظين بذلك.", "isBasmala": false, "translation_en": "Surely in this is a sign, but most of them are not believers.", "translation_id": "Sesungguhnya pada yang demikian itu benar-benar terdapat tanda (kekuasaan Allah), tetapi kebanyakan mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 191, "text": "وَإِنَّ رَبَّكَ لَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝١٩١", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وإن ربك - أيها الرسول - لهو العزيز في نقمته ممن انتقم منه من أعدائه، الرحيم بعباده الموحدين.", "isBasmala": false, "translation_en": "Your Lord is the Almighty, the Merciful.", "translation_id": "Dan sesungguhnya Tuhanmu benar-benar Dialah Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 192, "text": "وَإِنَّهُۥ لَتَنزِیلُ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٩٢", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وإن هذا القرآن الذي ذُكِرَتْ فيه هذه القصص الصادقة، لَمنزَّل مِن خالق الخلق، ومالك الأمر كله، نزل به جبريل الأمين، فتلاه عليك - أيها الرسول - حتى وعيته بقلبك حفظًا وفهمًا؛ لتكون مِن رسل الله الذين يخوِّفون قومهم عقاب الله، فتنذر بهذا التنزيل الإنس والجن أجمعين. نزل به جبريل عليك بلغة عربية واضحة المعنى، ظاهرة الدلالة، فيما يحتاجون إليه في إصلاح شؤون دينهم ودنياهم.", "isBasmala": false, "translation_en": "It is a revelation from the Lord of the Worlds.", "translation_id": "Dan sesungguhnya Al Quran ini benar-benar diturunkan oleh Tuhan semesta alam,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 193, "text": "نَزَلَ بِهِ ٱلرُّوحُ ٱلۡأَمِینُ ۝١٩٣", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وإن هذا القرآن الذي ذُكِرَتْ فيه هذه القصص الصادقة، لَمنزَّل مِن خالق الخلق، ومالك الأمر كله، نزل به جبريل الأمين، فتلاه عليك - أيها الرسول - حتى وعيته بقلبك حفظًا وفهمًا؛ لتكون مِن رسل الله الذين يخوِّفون قومهم عقاب الله، فتنذر بهذا التنزيل الإنس والجن أجمعين. نزل به جبريل عليك بلغة عربية واضحة المعنى، ظاهرة الدلالة، فيما يحتاجون إليه في إصلاح شؤون دينهم ودنياهم.", "isBasmala": false, "translation_en": "The Honest Spirit came down with it.", "translation_id": "dia dibawa turun oleh Ar-Ruh Al-Amin (Jibril),", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 194, "text": "عَلَىٰ قَلۡبِكَ لِتَكُونَ مِنَ ٱلۡمُنذِرِینَ ۝١٩٤", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وإن هذا القرآن الذي ذُكِرَتْ فيه هذه القصص الصادقة، لَمنزَّل مِن خالق الخلق، ومالك الأمر كله، نزل به جبريل الأمين، فتلاه عليك - أيها الرسول - حتى وعيته بقلبك حفظًا وفهمًا؛ لتكون مِن رسل الله الذين يخوِّفون قومهم عقاب الله، فتنذر بهذا التنزيل الإنس والجن أجمعين. نزل به جبريل عليك بلغة عربية واضحة المعنى، ظاهرة الدلالة، فيما يحتاجون إليه في إصلاح شؤون دينهم ودنياهم.", "isBasmala": false, "translation_en": "Upon your heart, that you may be one of the warners.", "translation_id": "ke dalam hatimu (Muhammad) agar kamu menjadi salah seorang di antara orang-orang yang memberi peringatan,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 195, "text": "بِلِسَانٍ عَرَبِیࣲّ مُّبِینࣲ ۝١٩٥", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وإن هذا القرآن الذي ذُكِرَتْ فيه هذه القصص الصادقة، لَمنزَّل مِن خالق الخلق، ومالك الأمر كله، نزل به جبريل الأمين، فتلاه عليك - أيها الرسول - حتى وعيته بقلبك حفظًا وفهمًا؛ لتكون مِن رسل الله الذين يخوِّفون قومهم عقاب الله، فتنذر بهذا التنزيل الإنس والجن أجمعين. نزل به جبريل عليك بلغة عربية واضحة المعنى، ظاهرة الدلالة، فيما يحتاجون إليه في إصلاح شؤون دينهم ودنياهم.", "isBasmala": false, "translation_en": "In a clear Arabic tongue.", "translation_id": "dengan bahasa Arab yang jelas.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 196, "text": "وَإِنَّهُۥ لَفِی زُبُرِ ٱلۡأَوَّلِینَ ۝١٩٦", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وإنَّ ذِكْرَ هذا القرآن لَمثبتٌ في كتب الأنبياء السابقين، قد بَشَّرَتْ به وصَدَّقَتْه.", "isBasmala": false, "translation_en": "And it is in the scriptures of the ancients.", "translation_id": "Dan sesungguhnya Al Quran itu benar-benar (tersebut) dalam Kitab-kitab orang yang dahulu.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 197, "text": "أَوَ لَمۡ یَكُن لَّهُمۡ ءَایَةً أَن یَعۡلَمَهُۥ عُلَمَـٰۤؤُا۟ بَنِیۤ إِسۡرَ ٰۤءِیلَ ۝١٩٧", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "أولم يَكْفِ هؤلاء- في الدلالة على أنك رسول الله، وأن القرآن حق- عِلْمُ علماء بني إسرائيل صحة ذلك، ومَن آمن منهم كعبد الله بن سلام؟", "isBasmala": false, "translation_en": "Is it not a sign for them that the scholars of the Children of Israel recognized it?", "translation_id": "Dan apakah tidak cukup menjadi bukti bagi mereka, bahwa para ulama Bani Israil mengetahuinya?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 198, "text": "وَلَوۡ نَزَّلۡنَـٰهُ عَلَىٰ بَعۡضِ ٱلۡأَعۡجَمِینَ ۝١٩٨", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "ولو نَزَّلنا القرآن على بعض الذين لا يتكلمون بالعربية، فقرأه على كفار قريش قراءة عربية صحيحة، لكفروا به أيضًا، وانتحلوا لجحودهم عذرًا. كذلك أدخلنا في قلوب المجرمين جحود القرآن، وصار متمكنًا فيها؛ وذلك بسبب ظلمهم وإجرامهم، فلا سبيل إلى أن يتغيروا عمَّا هم عليه من إنكار القرآن، حتى يعاينوا العذاب الشديد الذي وُعِدوا به.", "isBasmala": false, "translation_en": "Had We revealed it to one of the foreigners.", "translation_id": "Dan kalau Al Quran itu Kami turunkan kepada salah seorang dari golongan bukan Arab,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 199, "text": "فَقَرَأَهُۥ عَلَیۡهِم مَّا كَانُوا۟ بِهِۦ مُؤۡمِنِینَ ۝١٩٩", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "ولو نَزَّلنا القرآن على بعض الذين لا يتكلمون بالعربية، فقرأه على كفار قريش قراءة عربية صحيحة، لكفروا به أيضًا، وانتحلوا لجحودهم عذرًا. كذلك أدخلنا في قلوب المجرمين جحود القرآن، وصار متمكنًا فيها؛ وذلك بسبب ظلمهم وإجرامهم، فلا سبيل إلى أن يتغيروا عمَّا هم عليه من إنكار القرآن، حتى يعاينوا العذاب الشديد الذي وُعِدوا به.", "isBasmala": false, "translation_en": "And he had recited it to them, they still would not have believed in it.", "translation_id": "lalu ia membacakannya kepada mereka (orang-orang kafir); niscaya mereka tidak akan beriman kepadanya.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 200, "text": "كَذَ ٰلِكَ سَلَكۡنَـٰهُ فِی قُلُوبِ ٱلۡمُجۡرِمِینَ ۝٢٠٠", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "ولو نَزَّلنا القرآن على بعض الذين لا يتكلمون بالعربية، فقرأه على كفار قريش قراءة عربية صحيحة، لكفروا به أيضًا، وانتحلوا لجحودهم عذرًا. كذلك أدخلنا في قلوب المجرمين جحود القرآن، وصار متمكنًا فيها؛ وذلك بسبب ظلمهم وإجرامهم، فلا سبيل إلى أن يتغيروا عمَّا هم عليه من إنكار القرآن، حتى يعاينوا العذاب الشديد الذي وُعِدوا به.", "isBasmala": false, "translation_en": "Thus We make it pass through the hearts of the guilty.", "translation_id": "Demikianlah Kami masukkan Al Quran ke dalam hati orang-orang yang durhaka.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 201, "text": "لَا یُؤۡمِنُونَ بِهِۦ حَتَّىٰ یَرَوُا۟ ٱلۡعَذَابَ ٱلۡأَلِیمَ ۝٢٠١", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "ولو نَزَّلنا القرآن على بعض الذين لا يتكلمون بالعربية، فقرأه على كفار قريش قراءة عربية صحيحة، لكفروا به أيضًا، وانتحلوا لجحودهم عذرًا. كذلك أدخلنا في قلوب المجرمين جحود القرآن، وصار متمكنًا فيها؛ وذلك بسبب ظلمهم وإجرامهم، فلا سبيل إلى أن يتغيروا عمَّا هم عليه من إنكار القرآن، حتى يعاينوا العذاب الشديد الذي وُعِدوا به.", "isBasmala": false, "translation_en": "They will not believe in it until they witness the painful punishment.", "translation_id": "Mereka tidak beriman kepadanya, hingga mereka melihat azab yang pedih,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 202, "text": "فَیَأۡتِیَهُم بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ ۝٢٠٢", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "فينزل بهم العذاب فجأة، وهم لا يعلمون قبل ذلك بمجيئه، فيقولون عند مفاجأتهم به تحسُّرًا على ما فاتهم من الإيمان: هل نحن مُمْهَلون مُؤخَّرون؛ لنتوب إلى الله مِن شركنا، ونستدرك ما فاتنا؟", "isBasmala": false, "translation_en": "It will come to them suddenly, while they are unaware.", "translation_id": "maka datanglah azab kepada mereka dengan mendadak, sedang mereka tidak menyadarinya,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 203, "text": "فَیَقُولُوا۟ هَلۡ نَحۡنُ مُنظَرُونَ ۝٢٠٣", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "فينزل بهم العذاب فجأة، وهم لا يعلمون قبل ذلك بمجيئه، فيقولون عند مفاجأتهم به تحسُّرًا على ما فاتهم من الإيمان: هل نحن مُمْهَلون مُؤخَّرون؛ لنتوب إلى الله مِن شركنا، ونستدرك ما فاتنا؟", "isBasmala": false, "translation_en": "Then they will say, \"Are we given any respite?\"", "translation_id": "lalu mereka berkata: \"Apakah kami dapat diberi tangguh?\"", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 204, "text": "أَفَبِعَذَابِنَا یَسۡتَعۡجِلُونَ ۝٢٠٤", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "أَغَرَّ هؤلاء إمهالي، فيستعجلون نزول العذاب عليهم من السماء؟", "isBasmala": false, "translation_en": "Do they seek to hasten Our punishment?", "translation_id": "Maka apakah mereka meminta supaya disegerakan azab Kami?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 205, "text": "أَفَرَءَیۡتَ إِن مَّتَّعۡنَـٰهُمۡ سِنِینَ ۝٢٠٥", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "أفعلمت - أيها الرسول - إن مَتَّعناهم بالحياة سنين طويلة بتأخير آجالهم، ثم نزل بهم العذاب الموعود؟", "isBasmala": false, "translation_en": "Have you considered: if We let them enjoy themselves for some years.", "translation_id": "Maka bagaimana pendapatmu jika Kami berikan kepada mereka kenikmatan hidup bertahun-tahun,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 206, "text": "ثُمَّ جَاۤءَهُم مَّا كَانُوا۟ یُوعَدُونَ ۝٢٠٦", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "أفعلمت - أيها الرسول - إن مَتَّعناهم بالحياة سنين طويلة بتأخير آجالهم، ثم نزل بهم العذاب الموعود؟", "isBasmala": false, "translation_en": "Then there comes to them what they were promised.", "translation_id": "Kemudian datang kepada mereka azab yang telah diancamkan kepada mereka,", "manzil": 5, "manzil_display": ""}], "376": [{"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 207, "text": "مَاۤ أَغۡنَىٰ عَنۡهُم مَّا كَانُوا۟ یُمَتَّعُونَ ۝٢٠٧", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "ما أغنى عنهم تمتعهم بطول العمر، وطيب العيش، إذا لم يتوبوا من شركهم؟ فعذاب الله واقع بهم عاجلا أم آجلا.", "isBasmala": false, "translation_en": "Of what avail to them will be their past enjoyments?", "translation_id": "niscaya tidak berguna bagi mereka apa yang mereka selalu menikmatinya.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 208, "text": "وَمَاۤ أَهۡلَكۡنَا مِن قَرۡیَةٍ إِلَّا لَهَا مُنذِرُونَ ۝٢٠٨", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وما أهلكنا مِن قرية من القرى في الأمم جميعًا، إلا بعد أن نرسل إليهم رسلا ينذرونهم، تذكرة لهم وتنبيهًا على ما فيه نجاتهم، وما كنا ظالمين فنعذب أمة قبل أن نرسل إليها رسولا.", "isBasmala": false, "translation_en": "Never did We destroy a town, but it had warners.", "translation_id": "Dan Kami tidak membinasakan sesuatu negeripun, melainkan sesudah ada baginya orang-orang yang memberi peringatan;", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 209, "text": "ذِكۡرَىٰ وَمَا كُنَّا ظَـٰلِمِینَ ۝٢٠٩", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وما أهلكنا مِن قرية من القرى في الأمم جميعًا، إلا بعد أن نرسل إليهم رسلا ينذرونهم، تذكرة لهم وتنبيهًا على ما فيه نجاتهم، وما كنا ظالمين فنعذب أمة قبل أن نرسل إليها رسولا.", "isBasmala": false, "translation_en": "As a reminder-We are never unjust.", "translation_id": "untuk menjadi peringatan. Dan Kami sekali-kali tidak berlaku zalim.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 210, "text": "وَمَا تَنَزَّلَتۡ بِهِ ٱلشَّیَـٰطِینُ ۝٢١٠", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وما تَنَزَّلَتْ بالقرآن على محمد الشياطين- كما يزعم الكفرة- ولا يصح منهم ذلك، وما يستطيعونه؛ لأنهم عن استماع القرآن من السماء محجوبون مرجومون بالشهب.", "isBasmala": false, "translation_en": "It was not the devils that revealed it.", "translation_id": "Dan Al Quran itu bukanlah dibawa turun oleh syaitan-syaitan.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 211, "text": "وَمَا یَنۢبَغِی لَهُمۡ وَمَا یَسۡتَطِیعُونَ ۝٢١١", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وما تَنَزَّلَتْ بالقرآن على محمد الشياطين- كما يزعم الكفرة- ولا يصح منهم ذلك، وما يستطيعونه؛ لأنهم عن استماع القرآن من السماء محجوبون مرجومون بالشهب.", "isBasmala": false, "translation_en": "It is not in their interests, nor in their power.", "translation_id": "Dan tidaklah patut mereka membawa turun Al Quran itu, dan merekapun tidak akan kuasa.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 212, "text": "إِنَّهُمۡ عَنِ ٱلسَّمۡعِ لَمَعۡزُولُونَ ۝٢١٢", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وما تَنَزَّلَتْ بالقرآن على محمد الشياطين- كما يزعم الكفرة- ولا يصح منهم ذلك، وما يستطيعونه؛ لأنهم عن استماع القرآن من السماء محجوبون مرجومون بالشهب.", "isBasmala": false, "translation_en": "They are barred from hearing.", "translation_id": "Sesungguhnya mereka benar-benar dijauhkan daripada mendengar Al Quran itu.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 213, "text": "فَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتَكُونَ مِنَ ٱلۡمُعَذَّبِینَ ۝٢١٣", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "فلا تعبد مع الله معبودًا غيره، فينزل بك من العذاب ما نزل بهؤلاء الذين عبدوا مع الله غيره.", "isBasmala": false, "translation_en": "So do not pray to another god with God, else you will be of those tormented.", "translation_id": "Maka janganlah kamu menyeru (menyembah) tuhan yang lain di samping Allah, yang menyebabkan kamu termasuk orang-orang yang diazab.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 214, "text": "وَأَنذِرۡ عَشِیرَتَكَ ٱلۡأَقۡرَبِینَ ۝٢١٤", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وحذِّر - أيها الرسول - الأقرب فالأقرب مِن قومك، مِن عذابنا، أن ينزل بهم.", "isBasmala": false, "translation_en": "And warn your close relatives.", "translation_id": "Dan berilah peringatan kepada kerabat-kerabatmu yang terdekat,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 215, "text": "وَٱخۡفِضۡ جَنَاحَكَ لِمَنِ ٱتَّبَعَكَ مِنَ ٱلۡمُؤۡمِنِینَ ۝٢١٥", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وأَلِنْ جانبك وكلامك تواضعًا ورحمة لمن ظهر لك منه إجابة دعوتك.", "isBasmala": false, "translation_en": "And lower your wing to those of the believers who follow you.", "translation_id": "dan rendahkanlah dirimu terhadap orang-orang yang mengikutimu, yaitu orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 216, "text": "فَإِنۡ عَصَوۡكَ فَقُلۡ إِنِّی بَرِیۤءࣱ مِّمَّا تَعۡمَلُونَ ۝٢١٦", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "فإن خالفوا أمرك ولم يتبعوك، فتبرَّأ من أعمالهم، وما هم عليه من الشرك والضلال.", "isBasmala": false, "translation_en": "And if they disobey you, say, \"I am innocent of what you do.\"", "translation_id": "Jika mereka mendurhakaimu maka katakanlah: \"Sesungguhnya aku tidak bertanggung jawab terhadap apa yang kamu kerjakan\";", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 217, "text": "وَتَوَكَّلۡ عَلَى ٱلۡعَزِیزِ ٱلرَّحِیمِ ۝٢١٧", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وفَوِّضْ أمرك إلى الله العزيز الذي لا يغالَب ولا يُقْهَر، الرحيم الذي لا يخذل أولياءه، وهو الذي يراك حين تقوم للصلاة وحدك في جوف الليل، ويرى تقلُّبك مع الساجدين في صلاتهم معك قائمًا وراكعًا وساجدًا وجالسًا، إنه- سبحانه- هو السميع لتلاوتك وذكرك، العليم بنيتك وعملك.", "isBasmala": false, "translation_en": "And put your trust in the Almighty, the Merciful.", "translation_id": "Dan bertawakkallah kepada (Allah) Yang Maha Perkasa lagi Maha Penyayang,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 218, "text": "ٱلَّذِی یَرَىٰكَ حِینَ تَقُومُ ۝٢١٨", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وفَوِّضْ أمرك إلى الله العزيز الذي لا يغالَب ولا يُقْهَر، الرحيم الذي لا يخذل أولياءه، وهو الذي يراك حين تقوم للصلاة وحدك في جوف الليل، ويرى تقلُّبك مع الساجدين في صلاتهم معك قائمًا وراكعًا وساجدًا وجالسًا، إنه- سبحانه- هو السميع لتلاوتك وذكرك، العليم بنيتك وعملك.", "isBasmala": false, "translation_en": "He Who sees you when you rise.", "translation_id": "Yang melihat kamu ketika kamu berdiri (untuk sembahyang),", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 219, "text": "وَتَقَلُّبَكَ فِی ٱلسَّـٰجِدِینَ ۝٢١٩", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وفَوِّضْ أمرك إلى الله العزيز الذي لا يغالَب ولا يُقْهَر، الرحيم الذي لا يخذل أولياءه، وهو الذي يراك حين تقوم للصلاة وحدك في جوف الليل، ويرى تقلُّبك مع الساجدين في صلاتهم معك قائمًا وراكعًا وساجدًا وجالسًا، إنه- سبحانه- هو السميع لتلاوتك وذكرك، العليم بنيتك وعملك.", "isBasmala": false, "translation_en": "And your devotions amidst the worshipers.", "translation_id": "dan (melihat pula) perubahan gerak badanmu di antara orang-orang yang sujud.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 220, "text": "إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٢٢٠", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "وفَوِّضْ أمرك إلى الله العزيز الذي لا يغالَب ولا يُقْهَر، الرحيم الذي لا يخذل أولياءه، وهو الذي يراك حين تقوم للصلاة وحدك في جوف الليل، ويرى تقلُّبك مع الساجدين في صلاتهم معك قائمًا وراكعًا وساجدًا وجالسًا، إنه- سبحانه- هو السميع لتلاوتك وذكرك، العليم بنيتك وعملك.", "isBasmala": false, "translation_en": "He is indeed the Hearer, the Aware.", "translation_id": "Sesungguhnya Dia adalah Yang Maha Mendengar lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 221, "text": "هَلۡ أُنَبِّئُكُمۡ عَلَىٰ مَن تَنَزَّلُ ٱلشَّیَـٰطِینُ ۝٢٢١", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "هل أخبركم- أيها الناس- على مَن تنـزَّل الشياطين؟ تتنزل على كل كذَّاب كثير الآثام من الكهنة، يَسْتَرِقُ الشياطين السمع، يتخطفونه من الملأ الأعلى، فيلقونه إلى الكهان، ومَن جرى مجراهم مِنَ الفسقة، وأكثر هؤلاء كاذبون، يَصْدُق أحدهم في كلمة، فيزيد فيها أكثر مِن مائة كذبة.", "isBasmala": false, "translation_en": "Shall I inform you upon whom the devils descend?", "translation_id": "Apakah akan Aku beritakan kepadamu, kepada siapa syaitan-syaitan itu turun?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 222, "text": "تَنَزَّلُ عَلَىٰ كُلِّ أَفَّاكٍ أَثِیمࣲ ۝٢٢٢", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "هل أخبركم- أيها الناس- على مَن تنـزَّل الشياطين؟ تتنزل على كل كذَّاب كثير الآثام من الكهنة، يَسْتَرِقُ الشياطين السمع، يتخطفونه من الملأ الأعلى، فيلقونه إلى الكهان، ومَن جرى مجراهم مِنَ الفسقة، وأكثر هؤلاء كاذبون، يَصْدُق أحدهم في كلمة، فيزيد فيها أكثر مِن مائة كذبة.", "isBasmala": false, "translation_en": "They descend upon every sinful liar.", "translation_id": "Mereka turun kepada tiap-tiap pendusta lagi yang banyak dosa,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 223, "text": "یُلۡقُونَ ٱلسَّمۡعَ وَأَكۡثَرُهُمۡ كَـٰذِبُونَ ۝٢٢٣", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "هل أخبركم- أيها الناس- على مَن تنـزَّل الشياطين؟ تتنزل على كل كذَّاب كثير الآثام من الكهنة، يَسْتَرِقُ الشياطين السمع، يتخطفونه من الملأ الأعلى، فيلقونه إلى الكهان، ومَن جرى مجراهم مِنَ الفسقة، وأكثر هؤلاء كاذبون، يَصْدُق أحدهم في كلمة، فيزيد فيها أكثر مِن مائة كذبة.", "isBasmala": false, "translation_en": "They give ear, and most of them are liars.", "translation_id": "mereka menghadapkan pendengaran (kepada syaitan) itu, dan kebanyakan mereka adalah orang-orang pendusta.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 224, "text": "وَٱلشُّعَرَاۤءُ یَتَّبِعُهُمُ ٱلۡغَاوُۥنَ ۝٢٢٤", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "والشعراء يقوم شعرهم على الباطل والكذب، ويجاريهم الضالون الزائغون مِن أمثالهم. ألم تر - أيها النبي - أنهم يذهبون كالهائم على وجهه، يخوضون في كل فن مِن فنون الكذب والزور وتمزيق الأعراض والطعن في الأنساب وتجريح النساء العفائف، وأنهم يقولون ما لا يفعلون، يبالغون في مدح أهل الباطل، وينتقصون أهل الحق؟", "isBasmala": false, "translation_en": "And as for the poets-the deviators follow them.", "translation_id": "Dan penyair-penyair itu diikuti oleh orang-orang yang sesat.", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 225, "text": "أَلَمۡ تَرَ أَنَّهُمۡ فِی كُلِّ وَادࣲ یَهِیمُونَ ۝٢٢٥", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "والشعراء يقوم شعرهم على الباطل والكذب، ويجاريهم الضالون الزائغون مِن أمثالهم. ألم تر - أيها النبي - أنهم يذهبون كالهائم على وجهه، يخوضون في كل فن مِن فنون الكذب والزور وتمزيق الأعراض والطعن في الأنساب وتجريح النساء العفائف، وأنهم يقولون ما لا يفعلون، يبالغون في مدح أهل الباطل، وينتقصون أهل الحق؟", "isBasmala": false, "translation_en": "Do you not see how they ramble in every style?", "translation_id": "Tidakkah kamu melihat bahwasanya mereka mengembara di tiap-tiap lembah,", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 226, "text": "وَأَنَّهُمۡ یَقُولُونَ مَا لَا یَفۡعَلُونَ ۝٢٢٦", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "والشعراء يقوم شعرهم على الباطل والكذب، ويجاريهم الضالون الزائغون مِن أمثالهم. ألم تر - أيها النبي - أنهم يذهبون كالهائم على وجهه، يخوضون في كل فن مِن فنون الكذب والزور وتمزيق الأعراض والطعن في الأنساب وتجريح النساء العفائف، وأنهم يقولون ما لا يفعلون، يبالغون في مدح أهل الباطل، وينتقصون أهل الحق؟", "isBasmala": false, "translation_en": "And how they say what they do not do?", "translation_id": "dan bahwasanya mereka suka mengatakan apa yang mereka sendiri tidak mengerjakan(nya)?", "manzil": 5, "manzil_display": ""}, {"sura": 26, "sura_name": "الشعراء", "revelation": "Makkiyah", "aya": 227, "text": "إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَذَكَرُوا۟ ٱللَّهَ كَثِیرࣰا وَٱنتَصَرُوا۟ مِنۢ بَعۡدِ مَا ظُلِمُوا۟ۗ وَسَیَعۡلَمُ ٱلَّذِینَ ظَلَمُوۤا۟ أَیَّ مُنقَلَبࣲ یَنقَلِبُونَ ۝٢٢٧", "juz": 19, "hizb": "(*¼ ح 38*)", "tafsir": "استثنى الله من الشعراءِ الشعراءَ الذين اهتدَوْا بالإيمان وعملوا الصالحات، وأكثروا مِن ذِكْر الله فقالوا الشعر في توحيد الله - سبحانه- والثناء عليه جلَّ ذكره، والدفاع عن رسوله محمد صلى الله عليه وسلم، وتكلموا بالحكمة والموعظة والآداب الحسنة، وانتصروا للإسلام، يهجون مَن يهجوه أو يهجو رسوله، ردًّا على الشعراء الكافرين. وسيعلم الذين ظلموا أنفسهم بالشرك والمعاصي، وظلموا غيرهم بغمط حقوقهم، أو الاعتداء عليهم، أو بالتُّهم الباطلة، أي مرجع من مراجع الشر والهلاك يرجعون إليه؟ إنَّه منقلب سوء، نسأل الله السلامة والعافية.", "isBasmala": false, "translation_en": "Except for those who believe, and do good deeds, and remember God frequently, and defend themselves after they are wronged. As for those who do wrong, they will know by what overturning they will be overturned.", "translation_id": "kecuali orang-orang (penyair-penyair) yang beriman dan beramal saleh dan banyak menyebut Allah dan mendapat kemenangan sesudah menderita kezaliman. Dan orang-orang yang zalim itu kelak akan mengetahui ke tempat mana mereka akan kembali.", "manzil": 5, "manzil_display": ""}], "377": [{"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 20, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 1, "text": "۞ طسۤۚ تِلۡكَ ءَایَـٰتُ ٱلۡقُرۡءَانِ وَكِتَابࣲ مُّبِینٍ ۝١", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "(طس) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ta, Seen. These are the Signs of the Quran-a book that makes things clear.", "translation_id": "Thaa Siin (Surat) ini adalah ayat-ayat Al Quran, dan (ayat-ayat) Kitab yang menjelaskan,", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 2, "text": "هُدࣰى وَبُشۡرَىٰ لِلۡمُؤۡمِنِینَ ۝٢", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "وهي آيات ترشد إلى طريق الفوز في الدنيا والآخرة، وتبشر بحسن الثواب للمؤمنين الذين صَدَّقوا بها، واهتدَوْا بهديها، الذين يقيمون الصلوات الخمس كاملة الأركان، مستوفية الشروط، ويؤدون الزكاة المفروضة لمستحقيها، وهم يوقنون بالحياة الآخرة، وما فيها مِن ثواب وعقاب.", "isBasmala": false, "translation_en": "Guidance and good news for the believers.", "translation_id": "untuk menjadi petunjuk dan berita gembira untuk orang-orang yang beriman,", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 3, "text": "ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ یُوقِنُونَ ۝٣", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "وهي آيات ترشد إلى طريق الفوز في الدنيا والآخرة، وتبشر بحسن الثواب للمؤمنين الذين صَدَّقوا بها، واهتدَوْا بهديها، الذين يقيمون الصلوات الخمس كاملة الأركان، مستوفية الشروط، ويؤدون الزكاة المفروضة لمستحقيها، وهم يوقنون بالحياة الآخرة، وما فيها مِن ثواب وعقاب.", "isBasmala": false, "translation_en": "Those who observe the prayers, and give charity regularly, and are certain of the Hereafter.", "translation_id": "(yaitu) orang-orang yang mendirikan sembahyang dan menunaikan zakat dan mereka yakin akan adanya negeri akhirat.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 4, "text": "إِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ زَیَّنَّا لَهُمۡ أَعۡمَـٰلَهُمۡ فَهُمۡ یَعۡمَهُونَ ۝٤", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "إن الذين لا يُصَدِّقون بالدار الآخرة، ولا يعملون لها حسَّنَّا لهم أعمالهم السيئة، فرأوها حسنة، فهم يترددون فيها متحيِّرين. أولئك الذين لهم العذاب السيِّئ في الدنيا قتلا وأَسْرًا وذُلا وهزيمةً، وهم في الآخرة أشد الناس خسرانًا.", "isBasmala": false, "translation_en": "As for those who do not believe in the Hereafter: We made their deeds appear good to them, so they wander aimlessly.", "translation_id": "Sesungguhnya orang-orang yang tidak beriman kepada negeri akhirat, Kami jadikan mereka memandang indah perbuatan-perbuatan mereka, maka mereka bergelimang (dalam kesesatan).", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 5, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَهُمۡ سُوۤءُ ٱلۡعَذَابِ وَهُمۡ فِی ٱلۡـَٔاخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ ۝٥", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "إن الذين لا يُصَدِّقون بالدار الآخرة، ولا يعملون لها حسَّنَّا لهم أعمالهم السيئة، فرأوها حسنة، فهم يترددون فيها متحيِّرين. أولئك الذين لهم العذاب السيِّئ في الدنيا قتلا وأَسْرًا وذُلا وهزيمةً، وهم في الآخرة أشد الناس خسرانًا.", "isBasmala": false, "translation_en": "It is they who will receive the grievous punishment-and in the Hereafter they will be the greatest losers.", "translation_id": "Mereka itulah orang-orang yang mendapat (di dunia) azab yang buruk dan mereka di akhirat adalah orang-orang yang paling merugi.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 6, "text": "وَإِنَّكَ لَتُلَقَّى ٱلۡقُرۡءَانَ مِن لَّدُنۡ حَكِیمٍ عَلِیمٍ ۝٦", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "وإنك -أيها الرسول- لتتلقى القرآن من عند الله، الحكيم في خلقه وتدبيره الذي أحاط بكل شيء علمًا.", "isBasmala": false, "translation_en": "You are receiving the Quran from an All-Wise, All-Knowing.", "translation_id": "Dan sesungguhnya kamu benar-benar diberi Al Quran dari sisi (Allah) Yang Maha Bijaksana lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 7, "text": "إِذۡ قَالَ مُوسَىٰ لِأَهۡلِهِۦۤ إِنِّیۤ ءَانَسۡتُ نَارࣰا سَـَٔاتِیكُم مِّنۡهَا بِخَبَرٍ أَوۡ ءَاتِیكُم بِشِهَابࣲ قَبَسࣲ لَّعَلَّكُمۡ تَصۡطَلُونَ ۝٧", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "اذكر قصة موسى حين قال لأهله في مسيره من \"مدين\" إلى \"مصر\": إني أبصَرْتُ نارًا سآتيكم منها بخبر يدلنا على الطريق، أو آتيكم بشعلة نار؛ كي تستدفئوا بها من البرد.", "isBasmala": false, "translation_en": "When Moses said to his family, \"I have glimpsed a fire. I will bring you some news from it; or bring you a firebrand, that you may warm yourselves.\"", "translation_id": "(Ingatlah) ketika Musa berkata kepada keluarganya: \"Sesungguhnya aku melihat api. Aku kelak akan membawa kepadamu khabar daripadanya, atau aku membawa kepadamu suluh api supaya kamu dapat berdiang\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 8, "text": "فَلَمَّا جَاۤءَهَا نُودِیَ أَنۢ بُورِكَ مَن فِی ٱلنَّارِ وَمَنۡ حَوۡلَهَا وَسُبۡحَـٰنَ ٱللَّهِ رَبِّ ٱلۡعَـٰلَمِینَ ۝٨", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "فلما جاء موسى النارَ ناداه الله وأخبره أن هذا مكانٌ قدَّسه الله وباركه فجعله موضعًا لتكليم موسى وإرساله، وأن الله بارك مَن في النار ومَن حولها مِنَ الملائكة، وتنزيهًا لله رب الخلائق عما لا يليق به. يا موسى إنه أنا الله المستحق للعبادة وحدي، العزيز الغالب في انتقامي من أعدائي، الحكيم في تدبير خلقي. وألق عصاك فألقاها فصارت حية، فلما رآها تتحرك في خفة تَحَرُّكَ الحية السريعة ولَّى هاربًا ولم يرجع إليها، فطمأنه الله بقوله: يا موسى لا تَخَفْ، إني لا يخاف لديَّ من أرسلتهم برسالتي، لكن مَن تجاوز الحدَّ بذنب، ثم تاب فبدَّل حُسْن التوبة بعد قبح الذنب، فإني غفور له رحيم به، فلا ييئس أحدٌ من رحمة الله ومغفرته. وأدخل يدك في جيبك تخرج بيضاء كالثلج من غير بَرَص في جملة تسع معجزات، وهي مع اليد: العصا، والسنون، ونقص الثمرات، والطوفان، والجراد، والقُمَّل، والضفادع، والدم؛ لتأييدك في رسالتك إلى فرعون وقومه، إنهم كانوا قومًا خارجين عن أمر الله كافرين به.", "isBasmala": false, "translation_en": "Then, when he reached it, he was called: \"Blessed is He who is within the fire, and He who is around it, and glorified be God, Lord of the Worlds.", "translation_id": "Maka tatkala dia tiba di (tempat) api itu, diserulah dia: \"Bahwa telah diberkati orang-orang yang berada di dekat api itu, dan orang-orang yang berada di sekitarnya. Dan Maha Suci Allah, Tuhan semesta alam\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 9, "text": "یَـٰمُوسَىٰۤ إِنَّهُۥۤ أَنَا ٱللَّهُ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٩", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "فلما جاء موسى النارَ ناداه الله وأخبره أن هذا مكانٌ قدَّسه الله وباركه فجعله موضعًا لتكليم موسى وإرساله، وأن الله بارك مَن في النار ومَن حولها مِنَ الملائكة، وتنزيهًا لله رب الخلائق عما لا يليق به. يا موسى إنه أنا الله المستحق للعبادة وحدي، العزيز الغالب في انتقامي من أعدائي، الحكيم في تدبير خلقي. وألق عصاك فألقاها فصارت حية، فلما رآها تتحرك في خفة تَحَرُّكَ الحية السريعة ولَّى هاربًا ولم يرجع إليها، فطمأنه الله بقوله: يا موسى لا تَخَفْ، إني لا يخاف لديَّ من أرسلتهم برسالتي، لكن مَن تجاوز الحدَّ بذنب، ثم تاب فبدَّل حُسْن التوبة بعد قبح الذنب، فإني غفور له رحيم به، فلا ييئس أحدٌ من رحمة الله ومغفرته. وأدخل يدك في جيبك تخرج بيضاء كالثلج من غير بَرَص في جملة تسع معجزات، وهي مع اليد: العصا، والسنون، ونقص الثمرات، والطوفان، والجراد، والقُمَّل، والضفادع، والدم؛ لتأييدك في رسالتك إلى فرعون وقومه، إنهم كانوا قومًا خارجين عن أمر الله كافرين به.", "isBasmala": false, "translation_en": "O Moses, it is I, God, the Almighty, the Wise.", "translation_id": "(Allah berfirman): \"Hai Musa, sesungguhnya, Akulah Allah, Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 10, "text": "وَأَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَاۤنࣱّ وَلَّىٰ مُدۡبِرࣰا وَلَمۡ یُعَقِّبۡۚ یَـٰمُوسَىٰ لَا تَخَفۡ إِنِّی لَا یَخَافُ لَدَیَّ ٱلۡمُرۡسَلُونَ ۝١٠", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "فلما جاء موسى النارَ ناداه الله وأخبره أن هذا مكانٌ قدَّسه الله وباركه فجعله موضعًا لتكليم موسى وإرساله، وأن الله بارك مَن في النار ومَن حولها مِنَ الملائكة، وتنزيهًا لله رب الخلائق عما لا يليق به. يا موسى إنه أنا الله المستحق للعبادة وحدي، العزيز الغالب في انتقامي من أعدائي، الحكيم في تدبير خلقي. وألق عصاك فألقاها فصارت حية، فلما رآها تتحرك في خفة تَحَرُّكَ الحية السريعة ولَّى هاربًا ولم يرجع إليها، فطمأنه الله بقوله: يا موسى لا تَخَفْ، إني لا يخاف لديَّ من أرسلتهم برسالتي، لكن مَن تجاوز الحدَّ بذنب، ثم تاب فبدَّل حُسْن التوبة بعد قبح الذنب، فإني غفور له رحيم به، فلا ييئس أحدٌ من رحمة الله ومغفرته. وأدخل يدك في جيبك تخرج بيضاء كالثلج من غير بَرَص في جملة تسع معجزات، وهي مع اليد: العصا، والسنون، ونقص الثمرات، والطوفان، والجراد، والقُمَّل، والضفادع، والدم؛ لتأييدك في رسالتك إلى فرعون وقومه، إنهم كانوا قومًا خارجين عن أمر الله كافرين به.", "isBasmala": false, "translation_en": "Throw down your staff.\" But when he saw it quivering, as though it were a demon, he turned around not looking back. \"O Moses, do not fear; the messengers do not fear in My presence.", "translation_id": "dan lemparkanlah tongkatmu\". Maka tatkala (tongkat itu menjadi ular dan) Musa melihatnya bergerak-gerak seperti dia seekor ular yang gesit, larilah ia berbalik ke belakang tanpa menoleh. \"Hai Musa, janganlah kamu takut. Sesungguhnya orang yang dijadikan rasul, tidak takut di hadapan-Ku.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 11, "text": "إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسۡنَۢا بَعۡدَ سُوۤءࣲ فَإِنِّی غَفُورࣱ رَّحِیمࣱ ۝١١", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "فلما جاء موسى النارَ ناداه الله وأخبره أن هذا مكانٌ قدَّسه الله وباركه فجعله موضعًا لتكليم موسى وإرساله، وأن الله بارك مَن في النار ومَن حولها مِنَ الملائكة، وتنزيهًا لله رب الخلائق عما لا يليق به. يا موسى إنه أنا الله المستحق للعبادة وحدي، العزيز الغالب في انتقامي من أعدائي، الحكيم في تدبير خلقي. وألق عصاك فألقاها فصارت حية، فلما رآها تتحرك في خفة تَحَرُّكَ الحية السريعة ولَّى هاربًا ولم يرجع إليها، فطمأنه الله بقوله: يا موسى لا تَخَفْ، إني لا يخاف لديَّ من أرسلتهم برسالتي، لكن مَن تجاوز الحدَّ بذنب، ثم تاب فبدَّل حُسْن التوبة بعد قبح الذنب، فإني غفور له رحيم به، فلا ييئس أحدٌ من رحمة الله ومغفرته. وأدخل يدك في جيبك تخرج بيضاء كالثلج من غير بَرَص في جملة تسع معجزات، وهي مع اليد: العصا، والسنون، ونقص الثمرات، والطوفان، والجراد، والقُمَّل، والضفادع، والدم؛ لتأييدك في رسالتك إلى فرعون وقومه، إنهم كانوا قومًا خارجين عن أمر الله كافرين به.", "isBasmala": false, "translation_en": "But whoever has done wrong, and then substituted goodness in place of evil. I am Forgiving and Merciful.", "translation_id": "tetapi orang yang berlaku zalim, kemudian ditukarnya kezalimannya dengan kebaikan (Allah akan mengampuninya); maka seaungguhnya Aku Maha Pangampun lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 12, "text": "وَأَدۡخِلۡ یَدَكَ فِی جَیۡبِكَ تَخۡرُجۡ بَیۡضَاۤءَ مِنۡ غَیۡرِ سُوۤءࣲۖ فِی تِسۡعِ ءَایَـٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ ۝١٢", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "فلما جاء موسى النارَ ناداه الله وأخبره أن هذا مكانٌ قدَّسه الله وباركه فجعله موضعًا لتكليم موسى وإرساله، وأن الله بارك مَن في النار ومَن حولها مِنَ الملائكة، وتنزيهًا لله رب الخلائق عما لا يليق به. يا موسى إنه أنا الله المستحق للعبادة وحدي، العزيز الغالب في انتقامي من أعدائي، الحكيم في تدبير خلقي. وألق عصاك فألقاها فصارت حية، فلما رآها تتحرك في خفة تَحَرُّكَ الحية السريعة ولَّى هاربًا ولم يرجع إليها، فطمأنه الله بقوله: يا موسى لا تَخَفْ، إني لا يخاف لديَّ من أرسلتهم برسالتي، لكن مَن تجاوز الحدَّ بذنب، ثم تاب فبدَّل حُسْن التوبة بعد قبح الذنب، فإني غفور له رحيم به، فلا ييئس أحدٌ من رحمة الله ومغفرته. وأدخل يدك في جيبك تخرج بيضاء كالثلج من غير بَرَص في جملة تسع معجزات، وهي مع اليد: العصا، والسنون، ونقص الثمرات، والطوفان، والجراد، والقُمَّل، والضفادع، والدم؛ لتأييدك في رسالتك إلى فرعون وقومه، إنهم كانوا قومًا خارجين عن أمر الله كافرين به.", "isBasmala": false, "translation_en": "Put your hand inside your pocket, and it will come out white, without blemish-among nine miracles to Pharaoh and his people, for they are immoral people.\"", "translation_id": "Dan masukkanlah tanganmu ke leher bajumu, niscaya ia akan ke luar putih (bersinar) bukan karena penyakit. (Kedua mukjizat ini) termasuk sembilan buah mukjizat (yang akan dikemukakan) kepada Fir'aun dan kaumnya. Sesungguhnya mereka adalah kaum yang fasik\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 13, "text": "فَلَمَّا جَاۤءَتۡهُمۡ ءَایَـٰتُنَا مُبۡصِرَةࣰ قَالُوا۟ هَـٰذَا سِحۡرࣱ مُّبِینࣱ ۝١٣", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "فلما جاءتهم هذه المعجزات ظاهرة بيِّنة يبصر بها مَن نظر إليها حقيقةَ ما دلت عليه، قالوا: هذا سحرٌ واضحٌ بيِّن.", "isBasmala": false, "translation_en": "Yet when Our enlightening signs came to them, they said, \"This is obvious witchcraft.\"", "translation_id": "Maka tatkala mukjizat-mukjizat Kami yang jelas itu sampai kepada mereka, berkatalah mereka: \"Ini adalah sihir yang nyata\".", "manzil": 5, "manzil_display": ""}], "378": [{"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 14, "text": "وَجَحَدُوا۟ بِهَا وَٱسۡتَیۡقَنَتۡهَاۤ أَنفُسُهُمۡ ظُلۡمࣰا وَعُلُوࣰّاۚ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُفۡسِدِینَ ۝١٤", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "وكذَّبوا بالمعجزات التسع الواضحة الدلالة على صدق موسى في نبوته وصدق دعوته، وأنكروا بألسنتهم أن تكون من عند الله، وقد استيقنوها في قلوبهم اعتداءً على الحق وتكبرًا على الاعتراف به، فانظر -أيها الرسول- كيف كان مصير الذين كفروا بآيات الله وأفسدوا في الأرض، إذ أغرقهم الله في البحر؟ وفي ذلك عبرة لمن يعتبر.", "isBasmala": false, "translation_en": "And they rejected them, although their souls were certain of them, out of wickedness and pride. So see how the outcome was for the mischief-makers.", "translation_id": "Dan mereka mengingkarinya karena kezaliman dan kesombongan (mereka) padahal hati mereka meyakini (kebenaran)nya. Maka perhatikanlah betapa kesudahan orang-orang yang berbuat kebinasaan.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 15, "text": "وَلَقَدۡ ءَاتَیۡنَا دَاوُۥدَ وَسُلَیۡمَـٰنَ عِلۡمࣰاۖ وَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی فَضَّلَنَا عَلَىٰ كَثِیرࣲ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِینَ ۝١٥", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "ولقد آتينا داود وسليمان علمًا فعملا به، وقالا الحمد لله الذي فضَّلنا بهذا على كثير من عباده المؤمنين. وفي الآية دليل على شرف العلم، وارتفاع أهله.", "isBasmala": false, "translation_en": "And We gave David and Solomon knowledge. They said, \"Praise God, who has favored us over many of His believing servants.\"", "translation_id": "Dan sesungguhnya Kami telah memberi ilmu kepada Daud dan Sulaiman; dan keduanya mengucapkan: \"Segala puji bagi Allah yang melebihkan kami dari kebanyakan hamba-hambanya yang beriman\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 16, "text": "وَوَرِثَ سُلَیۡمَـٰنُ دَاوُۥدَۖ وَقَالَ یَـٰۤأَیُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّیۡرِ وَأُوتِینَا مِن كُلِّ شَیۡءٍۖ إِنَّ هَـٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِینُ ۝١٦", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "وورث سليمان أباه داود في النبوة والعلم والملك، وقال سليمان لقومه: يا أيها الناس عُلِّمنا وفُهِّمنا كلام الطير، وأُعطينا مِن كل شيء تدعو إليه الحاجة، إن هذا الذي أعطانا الله تعالى إياه لهو الفضل الواضح الذي يُمَيِّزنا على مَن سوانا.", "isBasmala": false, "translation_en": "And Solomon succeeded David. He said, \"O people, we were taught the language of birds, and we were given from everything. This is indeed a real blessing.\"", "translation_id": "Dan Sulaiman telah mewarisi Daud, dan dia berkata: \"Hai Manusia, kami telah diberi pengertian tentang suara burung dan kami diberi segala sesuatu. Sesungguhnya (semua) ini benar-benar suatu kurnia yang nyata\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 17, "text": "وَحُشِرَ لِسُلَیۡمَـٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّیۡرِ فَهُمۡ یُوزَعُونَ ۝١٧", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "وجُمِع لسليمان جنوده من الجن والإنس والطير في مسيرة لهم، فهم على كثرتهم لم يكونوا مهمَلين، بل كان على كل جنس من يَرُدُّ أولهم على آخرهم؛ كي يقفوا جميعًا منتظمين.", "isBasmala": false, "translation_en": "To the service of Solomon were mobilized his troops of sprites, and men, and birds-all held in strict order.", "translation_id": "Dan dihimpunkan untuk Sulaiman tentaranya dari jin, manusia dan burung lalu mereka itu diatur dengan tertib (dalam barisan).", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 18, "text": "حَتَّىٰۤ إِذَاۤ أَتَوۡا۟ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةࣱ یَـٰۤأَیُّهَا ٱلنَّمۡلُ ٱدۡخُلُوا۟ مَسَـٰكِنَكُمۡ لَا یَحۡطِمَنَّكُمۡ سُلَیۡمَـٰنُ وَجُنُودُهُۥ وَهُمۡ لَا یَشۡعُرُونَ ۝١٨", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "حتى إذا بلغوا وادي النمل قالت نملة: يا أيها النمل ادخلوا مساكنكم لا يهلكنَّكم سليمان وجنوده، وهم لا يعلمون بذلك. فتبسم ضاحكًا من قول هذه النملة لفهمها واهتدائها إلى تحذير النمل، واستشعر نعمة الله عليه، فتوجَّه إليه داعيًا: ربِّ ألْهِمْني، ووفقني، أن أشكر نعمتك التي أنعمت عليَّ وعلى والديَّ، وأن أعمل عملا صالحًا ترضاه مني، وأدخلني برحمتك في نعيم جنتك مع عبادك الصالحين الذين ارتضيت أعمالهم.", "isBasmala": false, "translation_en": "Until, when they came upon the Valley of Ants, an ant said, \"O ants! Go into your nests, lest Solomon and his troops crush you without noticing.\"", "translation_id": "Hingga apabila mereka sampai di lembah semut berkatalah seekor semut: Hai semut-semut, masuklah ke dalam sarang-sarangmu, agar kamu tidak diinjak oleh Sulaiman dan tentaranya, sedangkan mereka tidak menyadari\";", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 19, "text": "فَتَبَسَّمَ ضَاحِكࣰا مِّن قَوۡلِهَا وَقَالَ رَبِّ أَوۡزِعۡنِیۤ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِیۤ أَنۡعَمۡتَ عَلَیَّ وَعَلَىٰ وَ ٰلِدَیَّ وَأَنۡ أَعۡمَلَ صَـٰلِحࣰا تَرۡضَىٰهُ وَأَدۡخِلۡنِی بِرَحۡمَتِكَ فِی عِبَادِكَ ٱلصَّـٰلِحِینَ ۝١٩", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "حتى إذا بلغوا وادي النمل قالت نملة: يا أيها النمل ادخلوا مساكنكم لا يهلكنَّكم سليمان وجنوده، وهم لا يعلمون بذلك. فتبسم ضاحكًا من قول هذه النملة لفهمها واهتدائها إلى تحذير النمل، واستشعر نعمة الله عليه، فتوجَّه إليه داعيًا: ربِّ ألْهِمْني، ووفقني، أن أشكر نعمتك التي أنعمت عليَّ وعلى والديَّ، وأن أعمل عملا صالحًا ترضاه مني، وأدخلني برحمتك في نعيم جنتك مع عبادك الصالحين الذين ارتضيت أعمالهم.", "isBasmala": false, "translation_en": "He smiled and laughed at her words, and said, \"My Lord, direct me to be thankful for the blessings you have bestowed upon me and upon my parents, and to do good works that please You. And admit me, by Your grace, into the company of Your virtuous servants.\"", "translation_id": "maka dia tersenyum dengan tertawa karena (mendengar) perkataan semut itu. Dan dia berdoa: \"Ya Tuhanku berilah aku ilham untuk tetap mensyukuri nikmat Mu yang telah Engkau anugerahkan kepadaku dan kepada dua orang ibu bapakku dan untuk mengerjakan amal saleh yang Engkau ridhai; dan masukkanlah aku dengan rahmat-Mu ke dalam golongan hamba-hamba-Mu yang saleh\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 20, "text": "وَتَفَقَّدَ ٱلطَّیۡرَ فَقَالَ مَا لِیَ لَاۤ أَرَى ٱلۡهُدۡهُدَ أَمۡ كَانَ مِنَ ٱلۡغَاۤىِٕبِینَ ۝٢٠", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "وتفقد سليمان حال الطير المسخرة له وحال ما غاب منها، وكان عنده هدهد متميز معروف فلم يجده، فقال: ما لي لا أرى الهدهد الذي أعهده؟ أسَتَره ساتر عني، أم أنه كان من الغائبين عني، فلم أره لغيبته؟ فلما ظهر أنه غائب قال: لأعذبنَّ هذا الهدهد عذابًا شديدًا لغيابه تأديبًا له، أو لأذبحنَّه عقوبة على ما فعل حيث أخلَّ بما سُخِّر له، أو ليأتينِّي بحجة ظاهرة، فيها عذر لغيبته.", "isBasmala": false, "translation_en": "Then he inspected the birds, and said, \"Why do I not see the hoopoe? Or is he among the absentees?", "translation_id": "Dan dia memeriksa burung-burung lalu berkata: \"Mengapa aku tidak melihat hud-hud, apakah dia termasuk yang tidak hadir.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 21, "text": "لَأُعَذِّبَنَّهُۥ عَذَابࣰا شَدِیدًا أَوۡ لَأَا۟ذۡبَحَنَّهُۥۤ أَوۡ لَیَأۡتِیَنِّی بِسُلۡطَـٰنࣲ مُّبِینࣲ ۝٢١", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "وتفقد سليمان حال الطير المسخرة له وحال ما غاب منها، وكان عنده هدهد متميز معروف فلم يجده، فقال: ما لي لا أرى الهدهد الذي أعهده؟ أسَتَره ساتر عني، أم أنه كان من الغائبين عني، فلم أره لغيبته؟ فلما ظهر أنه غائب قال: لأعذبنَّ هذا الهدهد عذابًا شديدًا لغيابه تأديبًا له، أو لأذبحنَّه عقوبة على ما فعل حيث أخلَّ بما سُخِّر له، أو ليأتينِّي بحجة ظاهرة، فيها عذر لغيبته.", "isBasmala": false, "translation_en": "I will punish him most severely, or slay him, unless he gives me a valid excuse.\"", "translation_id": "Sungguh aku benar-benar akan mengazabnya dengan azab yang keras atau benar-benar menyembelihnya kecuali jika benar-benar dia datang kepadaku dengan alasan yang terang\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 22, "text": "فَمَكَثَ غَیۡرَ بَعِیدࣲ فَقَالَ أَحَطتُ بِمَا لَمۡ تُحِطۡ بِهِۦ وَجِئۡتُكَ مِن سَبَإِۭ بِنَبَإࣲ یَقِینٍ ۝٢٢", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "فمكث الهدهد زمنًا غير بعيد ثم حضر فعاتبه سليمان على مغيبه وتخلُّفه، فقال له الهدهد: علمت ما لم تعلمه من الأمر على وجه الإحاطة، وجئتك من مدينة \"سبأ\" بـ \"اليمن\" بخبر خطير الشأن، وأنا على يقين منه.", "isBasmala": false, "translation_en": "But he did not stay for long. He said, \"I have learnt something you did not know. I have come to you from Sheba, with reliable information.", "translation_id": "Maka tidak lama kemudian (datanglah hud-hud), lalu ia berkata: \"Aku telah mengetahui sesuatu yang kamu belum mengetahuinya; dan kubawa kepadamu dari negeri Saba suatu berita penting yang diyakini.", "manzil": 5, "manzil_display": ""}], "379": [{"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 23, "text": "إِنِّی وَجَدتُّ ٱمۡرَأَةࣰ تَمۡلِكُهُمۡ وَأُوتِیَتۡ مِن كُلِّ شَیۡءࣲ وَلَهَا عَرۡشٌ عَظِیمࣱ ۝٢٣", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "إني وجدت امرأةً تحكم أهل \"سبأ\"، وأوتيت من كل شيء من أسباب الدنيا، ولها سرير عظيم القدر، تجلس عليه لإدارة ملكها.", "isBasmala": false, "translation_en": "I found a woman ruling over them, and she was given of everything, and she has a magnificent throne.", "translation_id": "Sesungguhnya aku menjumpai seorang wanita yang memerintah mereka, dan dia dianugerahi segala sesuatu serta mempunyai singgasana yang besar.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 24, "text": "وَجَدتُّهَا وَقَوۡمَهَا یَسۡجُدُونَ لِلشَّمۡسِ مِن دُونِ ٱللَّهِ وَزَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ أَعۡمَـٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِیلِ فَهُمۡ لَا یَهۡتَدُونَ ۝٢٤", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "وجدتُها هي وقومها يعبدون الشمس معرضين عن عبادة الله، وحسَّن لهم الشيطان أعمالهم السيئة التي كانوا يعملونها، فصرفهم عن الإيمان بالله وتوحيده، فهم لا يهتدون إلى الله وتوحيده وعبادته وحده.", "isBasmala": false, "translation_en": "I found her and her people worshiping the sun, instead of God. Satan made their conduct appear good to them, and diverted them from the path, so they are not guided.", "translation_id": "Aku mendapati dia dan kaumnya menyembah matahari, selain Allah; dan syaitan telah menjadikan mereka memandang indah perbuatan-perbuatan mereka lalu menghalangi mereka dari jalan (Allah), sehingga mereka tidak dapat petunjuk,", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 25, "text": "أَ̅لَّ̅ا̅ ̅یَ̅سۡ̅جُ̅دُ̅و̅ا۟̅ ̅لِ̅لَّ̅هِ̅ ٱلَّذِی یُخۡرِجُ ٱلۡخَبۡءَ فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَیَعۡلَمُ مَا تُخۡفُونَ وَمَا تُعۡلِنُونَ ۝٢٥", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "حسَّن لهم الشيطان ذلك؛ لئلا يسجدوا لله الذي يُخرج المخبوء المستور في السموات والأرض من المطر والنبات وغير ذلك، ويعلم ما تُسرُّون وما تظهرون. الله الذي لا معبود يستحق العبادة سواه، رب العرش العظيم.", "isBasmala": false, "translation_en": "If only they would worship God, who brings to light the mysteries of the heavens and the earth, and knows what you conceal and what you reveal.", "translation_id": "agar mereka tidak menyembah Allah Yang mengeluarkan apa yang terpendam di langit dan di bumi dan Yang mengetahui apa yang kamu sembunyikan dan apa yang kamu nyatakan.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 26, "text": "ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِیمِ ۝٢٦ ۩", "juz": 19, "hizb": "(*½ ح 38*)", "tafsir": "حسَّن لهم الشيطان ذلك؛ لئلا يسجدوا لله الذي يُخرج المخبوء المستور في السموات والأرض من المطر والنبات وغير ذلك، ويعلم ما تُسرُّون وما تظهرون. الله الذي لا معبود يستحق العبادة سواه، رب العرش العظيم.", "isBasmala": false, "translation_en": "God-There is no god but He, the Lord of the Sublime Throne.\"", "translation_id": "Allah, tiada Tuhan Yang disembah kecuali Dia, Tuhan Yang mempunyai 'Arsy yang besar\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 27, "text": "۞ قَالَ سَنَنظُرُ أَصَدَقۡتَ أَمۡ كُنتَ مِنَ ٱلۡكَـٰذِبِینَ ۝٢٧", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قال سليمان للهدهد: سنتأمل فيما جئتنا به من الخبر أصدقت في ذلك أم كنت من الكاذبين فيه؟ اذهب بكتابي هذا إلى أهل \"سبأ\" فأعطهم إياه، ثم تنحَّ عنهم قريبًا منهم بحيث تسمع كلامهم، فتأمل ما يتردد بينهم من الكلام.", "isBasmala": false, "translation_en": "He said, \"We will see, whether you have spoken the truth, or whether you are a liar.", "translation_id": "Berkata Sulaiman: \"Akan kami lihat, apa kamu benar, ataukah kamu termasuk orang-orang yang berdusta.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 28, "text": "ٱذۡهَب بِّكِتَـٰبِی هَـٰذَا فَأَلۡقِهۡ إِلَیۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا یَرۡجِعُونَ ۝٢٨", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قال سليمان للهدهد: سنتأمل فيما جئتنا به من الخبر أصدقت في ذلك أم كنت من الكاذبين فيه؟ اذهب بكتابي هذا إلى أهل \"سبأ\" فأعطهم إياه، ثم تنحَّ عنهم قريبًا منهم بحيث تسمع كلامهم، فتأمل ما يتردد بينهم من الكلام.", "isBasmala": false, "translation_en": "Go with this letter of mine, and deliver it to them; then withdraw from them, and see how they respond.\"", "translation_id": "Pergilah dengan (membawa) suratku ini, lalu jatuhkan kepada mereka, kemudian berpalinglah dari mereka, lalu perhatikanlah apa yang mereka bicarakan\"", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 29, "text": "قَالَتۡ یَـٰۤأَیُّهَا ٱلۡمَلَؤُا۟ إِنِّیۤ أُلۡقِیَ إِلَیَّ كِتَـٰبࣱ كَرِیمٌ ۝٢٩", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "ذهب الهدهد وألقى الكتاب إلى الملكة فقرأته، فجمعت أشراف قومها، وسمعها تقول لهم: إني وصل إليَّ كتاب جليل المقدار من شخص عظيم الشأن.", "isBasmala": false, "translation_en": "She said, \"O Counselors, a gracious letter was delivered to me.", "translation_id": "Berkata ia (Balqis): \"Hai pembesar-pembesar, sesungguhnya telah dijatuhkan kepadaku sebuah surat yang mulia.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 30, "text": "إِنَّهُۥ مِن سُلَیۡمَـٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ۝٣٠", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "ثم بيَّنت ما فيه فقالت: إنه من سليمان، وإنه مفتتح بـ \"بسم الله الرحمن الرحيم\" ألا تتكبروا ولا تتعاظموا عما دعوتكم إليه، وأقْبِلوا إليَّ منقادين لله بالوحدانية والطاعة مسلمين له.", "isBasmala": false, "translation_en": "It is from Solomon, and it is, 'In the Name of God, the Gracious, the Merciful.", "translation_id": "Sesungguhnya surat itu, dari SuIaiman dan sesungguhnya (isi)nya: \"Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 31, "text": "أَلَّا تَعۡلُوا۟ عَلَیَّ وَأۡتُونِی مُسۡلِمِینَ ۝٣١", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "ثم بيَّنت ما فيه فقالت: إنه من سليمان، وإنه مفتتح بـ \"بسم الله الرحمن الرحيم\" ألا تتكبروا ولا تتعاظموا عما دعوتكم إليه، وأقْبِلوا إليَّ منقادين لله بالوحدانية والطاعة مسلمين له.", "isBasmala": false, "translation_en": "Do not defy me, and come to me submissively.'\"", "translation_id": "Bahwa janganlah kamu sekalian berlaku sombong terhadapku dan datanglah kepadaku sebagai orang-orang yang berserah diri\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 32, "text": "قَالَتۡ یَـٰۤأَیُّهَا ٱلۡمَلَؤُا۟ أَفۡتُونِی فِیۤ أَمۡرِی مَا كُنتُ قَاطِعَةً أَمۡرًا حَتَّىٰ تَشۡهَدُونِ ۝٣٢", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قالت: يا أيها الأشراف أشيروا عليَّ في هذا الأمر، ما كنت لأفصل في أمر إلا بمحضركم ومشورتكم.", "isBasmala": false, "translation_en": "She said, \"O counselors, advise me in this matter of mine. I never make a decision unless you are present.\"", "translation_id": "Berkata dia (Balqis): \"Hai para pembesar berilah aku pertimbangan dalam urusanku (ini) aku tidak pernah memutuskan sesuatu persoalan sebelum kamu berada dalam majelis(ku)\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 33, "text": "قَالُوا۟ نَحۡنُ أُو۟لُوا۟ قُوَّةࣲ وَأُو۟لُوا۟ بَأۡسࣲ شَدِیدࣲ وَٱلۡأَمۡرُ إِلَیۡكِ فَٱنظُرِی مَاذَا تَأۡمُرِینَ ۝٣٣", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قالوا مجيبين لها: نحن أصحاب قوة في العدد والعُدَّة وأصحاب النجدة والشجاعة في شدة الحرب، والأمر موكول إليكِ، وأنتِ صاحبة الرأي، فتأملي ماذا تأمريننا به؟ فنحن سامعون لأمرك مطيعون لك.", "isBasmala": false, "translation_en": "They said, \"We are a people of might and great courage, but the decision is yours, so consider what you wish to command.\"", "translation_id": "Mereka menjawab: \"Kita adalah orang-orang yang memiliki kekuatan dan (juga) memiliki keberanian yang sangat (dalam peperangan), dan keputusan berada ditanganmu: maka pertimbangkanlah apa yang akan kamu perintahkan\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 34, "text": "قَالَتۡ إِنَّ ٱلۡمُلُوكَ إِذَا دَخَلُوا۟ قَرۡیَةً أَفۡسَدُوهَا وَجَعَلُوۤا۟ أَعِزَّةَ أَهۡلِهَاۤ أَذِلَّةࣰۚ وَكَذَ ٰلِكَ یَفۡعَلُونَ ۝٣٤", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قالت محذرةً لهم من مواجهة سليمان بالعداوة، ومبيِّنة لهم سوء مغبَّة القتال: إن الملوك إذا دخلوا بجيوشهم قريةً عنوةً وقهرًا خرَّبوها وصيَّروا أعزَّة أهلها أذلة، وقتلوا وأسروا، وهذه عادتهم المستمرة الثابتة لحمل الناس على أن يهابوهم. وإني مرسلة إلى سليمان وقومه بهديَّة مشتملة على نفائس الأموال أصانعه بها، ومنتظرة ما يرجع به الرسل.", "isBasmala": false, "translation_en": "She said, \"When kings enter a city, they devastate it, and subjugate its dignified people. Thus they always do.", "translation_id": "Dia berkata: \"Sesungguhnya raja-raja apabila memasuki suatu negeri, niscaya mereka membinasakannya, dan menjadikan penduduknya yang mulia jadi hina; dan demikian pulalah yang akan mereka perbuat.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 35, "text": "وَإِنِّی مُرۡسِلَةٌ إِلَیۡهِم بِهَدِیَّةࣲ فَنَاظِرَةُۢ بِمَ یَرۡجِعُ ٱلۡمُرۡسَلُونَ ۝٣٥", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قالت محذرةً لهم من مواجهة سليمان بالعداوة، ومبيِّنة لهم سوء مغبَّة القتال: إن الملوك إذا دخلوا بجيوشهم قريةً عنوةً وقهرًا خرَّبوها وصيَّروا أعزَّة أهلها أذلة، وقتلوا وأسروا، وهذه عادتهم المستمرة الثابتة لحمل الناس على أن يهابوهم. وإني مرسلة إلى سليمان وقومه بهديَّة مشتملة على نفائس الأموال أصانعه بها، ومنتظرة ما يرجع به الرسل.", "isBasmala": false, "translation_en": "I am sending them a gift, and will see what the envoys bring back.\"", "translation_id": "Dan sesungguhnya aku akan mengirim utusan kepada mereka dengan (membawa) hadiah, dan (aku akan) menunggu apa yang akan dibawa kembali oleh utusan-utusan itu\".", "manzil": 5, "manzil_display": ""}], "380": [{"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 36, "text": "فَلَمَّا جَاۤءَ سُلَیۡمَـٰنَ قَالَ أَتُمِدُّونَنِ بِمَالࣲ فَمَاۤ ءَاتَىٰنِۦَ ٱللَّهُ خَیۡرࣱ مِّمَّاۤ ءَاتَىٰكُمۚ بَلۡ أَنتُم بِهَدِیَّتِكُمۡ تَفۡرَحُونَ ۝٣٦", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "فلمَّا جاء رسول الملكة بالهديَّة إلى سليمان، قال مستنكرًا ذلك متحدثًا بأَنْعُمِ الله عليه: أتمدونني بمالٍ تَرْضيةً لي؟ فما أعطاني الله من النبوة والملك والأموال الكثيرة خير وأفضل مما أعطاكم، بل أنتم الذين تفرحون بالهدية التي تُهدى إليكم؛ لأنكم أهل مفاخرة بالدنيا ومكاثرة بها.", "isBasmala": false, "translation_en": "When he came to Solomon, he said, \"Are you supplying me with money? What God has given me is better than what He has given you. It is you who delight in your gift.", "translation_id": "Maka tatkala utusan itu sampai kepada Sulaiman, Sulaiman berkata: \"Apakah (patut) kamu menolong aku dengan harta? maka apa yang diberikan Allah kepadaku lebih baik daripada apa yang diberikan-Nya kepadamu; tetapi kamu merasa bangga dengan hadiahmu.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 37, "text": "ٱرۡجِعۡ إِلَیۡهِمۡ فَلَنَأۡتِیَنَّهُم بِجُنُودࣲ لَّا قِبَلَ لَهُم بِهَا وَلَنُخۡرِجَنَّهُم مِّنۡهَاۤ أَذِلَّةࣰ وَهُمۡ صَـٰغِرُونَ ۝٣٧", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "وقال سليمان عليه السلام لرسول أهل \"سبأ\": ارجع إليهم، فوالله لنأتينَّهم بجنود لا طاقة لهم بمقاومتها ومقابلتها، ولنخرجنَّهم مِن أرضهم أذلة وهم صاغرون مهانون، إن لم ينقادوا لدين الله وحده، ويتركوا عبادة من سواه.", "isBasmala": false, "translation_en": "Go back to them. We will come upon them with troops they cannot resist; and we will expel them from there, disgraced and humiliated.\"", "translation_id": "Kembalilah kepada mereka sungguh kami akan mendatangi mereka dengan balatentara yang mereka tidak kuasa melawannya, dan pasti kami akan mengusir mereka dari negeri itu (Saba) dengan terhina dan mereka menjadi (tawanan-tawanan) yang hina dina\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 38, "text": "قَالَ یَـٰۤأَیُّهَا ٱلۡمَلَؤُا۟ أَیُّكُمۡ یَأۡتِینِی بِعَرۡشِهَا قَبۡلَ أَن یَأۡتُونِی مُسۡلِمِینَ ۝٣٨", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قال سليمان مخاطبًا من سَخَّرهم الله له من الجن والإنس: أيُّكم يأتيني بسرير ملكها العظيم قبل أن يأتوني منقادين طائعين؟", "isBasmala": false, "translation_en": "He said, \"O notables, which one of you will bring me her throne before they come to me in submission?\"", "translation_id": "Berkata Sulaiman: \"Hai pembesar-pembesar, siapakah di antara kamu sekalian yang sanggup membawa singgasananya kepadaku sebelum mereka datang kepadaku sebagai orang-orang yang berserah diri\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 39, "text": "قَالَ عِفۡرِیتࣱ مِّنَ ٱلۡجِنِّ أَنَا۠ ءَاتِیكَ بِهِۦ قَبۡلَ أَن تَقُومَ مِن مَّقَامِكَۖ وَإِنِّی عَلَیۡهِ لَقَوِیٌّ أَمِینࣱ ۝٣٩", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قال مارد قويٌّ شديد من الجن: أنا آتيك به قبل أن تقوم من مجلسك هذا، وإني لقويٌّ على حَمْله، أمين على ما فيه، آتي به كما هو لا أُنقِص منه شيئًا ولا أبدله.", "isBasmala": false, "translation_en": "An imp of the sprites said, \"I will bring it to you before you rise from your seat. I am strong and reliable enough to do it.\"", "translation_id": "Berkata 'Ifrit (yang cerdik) dari golongan jin: \"Aku akan datang kepadamu dengan membawa singgsana itu kepadamu sebelum kamu berdiri dari tempat dudukmu; sesungguhnya aku benar-benar kuat untuk membawanya lagi dapat dipercaya\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 40, "text": "قَالَ ٱلَّذِی عِندَهُۥ عِلۡمࣱ مِّنَ ٱلۡكِتَـٰبِ أَنَا۠ ءَاتِیكَ بِهِۦ قَبۡلَ أَن یَرۡتَدَّ إِلَیۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَـٰذَا مِن فَضۡلِ رَبِّی لِیَبۡلُوَنِیۤ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا یَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّی غَنِیࣱّ كَرِیمࣱ ۝٤٠", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قال الذي عنده علم من الكتاب: أنا آتيك بهذا العرش قبل ارتداد أجفانك إذا تحرَّكَتْ للنظر في شيء. فأذن له سليمان فدعا الله، فأتى بالعرش. فلما رآه سليمان حاضرًا لديه ثابتًا عنده قال: هذا مِن فضل ربي الذي خلقني وخلق الكون كله؛ ليختبرني: أأشكر بذلك اعترافًا بنعمته تعالى عليَّ أم أكفر بترك الشكر؟ ومن شكر لله على نعمه فإنَّ نَفْعَ ذلك يرجع إليه، ومن جحد النعمة وترك الشكر فإن ربي غني عن شكره، كريم يعم بخيره في الدنيا الشاكر والكافر، ثم يحاسبهم ويجازيهم في الآخرة.", "isBasmala": false, "translation_en": "He who had knowledge from the Book said, \"I will bring it to you before your glance returns to you.\" And when he saw it settled before him, he said, \"This is from the grace of my Lord, to test me, whether I am grateful or ungrateful. He who is grateful, his gratitude is to his own credit; but he who is ungrateful-my Lord is Independent and Generous.\"", "translation_id": "Berkatalah seorang yang mempunyai ilmu dari Al Kitab: \"Aku akan membawa singgasana itu kepadamu sebelum matamu berkedip\". Maka tatkala Sulaiman melihat singgasana itu terletak di hadapannya, iapun berkata: \"Ini termasuk kurnia Tuhanku untuk mencoba aku apakah aku bersyukur atau mengingkari (akan nikmat-Nya). Dan barangsiapa yang bersyukur maka sesungguhnya dia bersyukur untuk (kebaikan) dirinya sendiri dan barangsiapa yang ingkar, maka sesungguhnya Tuhanku Maha Kaya lagi Maha Mulia\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 41, "text": "قَالَ نَكِّرُوا۟ لَهَا عَرۡشَهَا نَنظُرۡ أَتَهۡتَدِیۤ أَمۡ تَكُونُ مِنَ ٱلَّذِینَ لَا یَهۡتَدُونَ ۝٤١", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قال سليمان لمن عنده: غيِّروا سرير ملكها الذي تجلس عليه إلى حال تنكره إذا رأته؛ لنرى أتهتدي إلى معرفته أم تكون من الذين لا يهتدون؟", "isBasmala": false, "translation_en": "He said, \"Disguise her throne for her, and we shall see whether she will be guided, or remains one of the misguided.\"", "translation_id": "Dia berkata: \"Rubahlah baginya singgasananya; maka kita akan melihat apakah dia mengenal ataukah dia termasuk orang-orang yang tidak mengenal(nya)\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 42, "text": "فَلَمَّا جَاۤءَتۡ قِیلَ أَهَـٰكَذَا عَرۡشُكِۖ قَالَتۡ كَأَنَّهُۥ هُوَۚ وَأُوتِینَا ٱلۡعِلۡمَ مِن قَبۡلِهَا وَكُنَّا مُسۡلِمِینَ ۝٤٢", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "فلما جاءت ملكة \"سبأ\" إلى سليمان في مجلسه قيل لها: أهكذا عرشك؟ قالت: إنه يشبهه. فظهر لسليمان أنها أصابت في جوابها، وقد علمت قدرة الله وصحة نبوة سليمان عليه السلام، فقال: وأوتينا العلم بالله وبقدرته مِن قبلها، وكنا منقادين لأمر الله متبعين لدين الاسلام.", "isBasmala": false, "translation_en": "When she arrived, it was said, \"Is your throne like this?\" She said, \"As if this is it.\" \"We were given knowledge before her, and we were submissive.\"", "translation_id": "Dan ketika Balqis datang, ditanyakanlah kepadanya: \"Serupa inikah singgasanamu?\" Dia menjawab: \"Seakan-akan singgasana ini singgasanaku, kami telah diberi pengetahuan sebelumnya dan kami adalah orang-orang yang berserah diri\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 43, "text": "وَصَدَّهَا مَا كَانَت تَّعۡبُدُ مِن دُونِ ٱللَّهِۖ إِنَّهَا كَانَتۡ مِن قَوۡمࣲ كَـٰفِرِینَ ۝٤٣", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "ومَنَعَها عن عبادة الله وحده ما كانت تعبده مِن دون الله تعالى، إنها كانت كافرة ونشأت بين قوم كافرين، واستمرت على دينهم، وإلا فلها من الذكاء والفطنة ما تعرف به الحق من الباطل، ولكن العقائد الباطلة تُذهب بصيرة القلب.", "isBasmala": false, "translation_en": "But she was prevented by what she worshiped besides God; she belonged to a disbelieving people.", "translation_id": "Dan apa yang disembahnya selama ini selain Allah, mencegahnya (untuk melahirkan keislamannya), karena sesungguhnya dia dahulunya termasuk orang-orang yang kafir.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 44, "text": "قِیلَ لَهَا ٱدۡخُلِی ٱلصَّرۡحَۖ فَلَمَّا رَأَتۡهُ حَسِبَتۡهُ لُجَّةࣰ وَكَشَفَتۡ عَن سَاقَیۡهَاۚ قَالَ إِنَّهُۥ صَرۡحࣱ مُّمَرَّدࣱ مِّن قَوَارِیرَۗ قَالَتۡ رَبِّ إِنِّی ظَلَمۡتُ نَفۡسِی وَأَسۡلَمۡتُ مَعَ سُلَیۡمَـٰنَ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ ۝٤٤", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قيل لها: ادخلي القصر، وكان صحنه مِن زجاج تحته ماء، فلما رأته ظنته ماء تتردد أمواجه، وكشفت عن ساقيها لتخوض الماء، فقال لها سليمان: إنه صحن أملس من زجاج صاف والماء تحته. فأدركت عظمة ملك سليمان، وقالت: رب إني ظلمت نفسي بما كنت عليه من الشرك، وانقدتُ متابعة لسليمان داخلة في دين رب العالمين أجمعين.", "isBasmala": false, "translation_en": "It was said to her, \"Go inside the palace.\" And when she saw it, she thought it was a deep pond, and she bared her legs. He said, \"It is a palace paved with glass.\" She said, \"My Lord, I have done wrong to myself, and I have submitted with Solomon, to God, Lord of the Worlds.\"", "translation_id": "Dikatakan kepadanya: \"Masuklah ke dalam istana\". Maka tatkala dia melihat lantai istana itu, dikiranya kolam air yang besar, dan disingkapkannya kedua betisnya. Berkatalah Sulaiman: \"Sesungguhnya ia adalah istana licin terbuat dari kaca\". Berkatalah Balqis: \"Ya Tuhanku, sesungguhnya aku telah berbuat zalim terhadap diriku dan aku berserah diri bersama Sulaiman kepada Allah, Tuhan semesta alam\".", "manzil": 5, "manzil_display": ""}], "381": [{"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 45, "text": "وَلَقَدۡ أَرۡسَلۡنَاۤ إِلَىٰ ثَمُودَ أَخَاهُمۡ صَـٰلِحًا أَنِ ٱعۡبُدُوا۟ ٱللَّهَ فَإِذَا هُمۡ فَرِیقَانِ یَخۡتَصِمُونَ ۝٤٥", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "ولقد أرسلنا إلى ثمود أخاهم صالحًا: أن وحِّدوا الله، ولا تجعلوا معه إلهًا آخر، فلما أتاهم صالحٌ داعيًا إلى توحيد الله وعبادته وحده صار قومه فريقين: أحدهما مؤمن به، والآخر كافر بدعوته، وكل منهم يزعم أن الحق معه.", "isBasmala": false, "translation_en": "And We sent to Thamood their brother Saleh: \"Worship God.\" But they became two disputing factions.", "translation_id": "Dan sesungguhnya Kami telah mengutus kepada (kaum) Tsamud saudara mereka Shaleh (yang berseru): \"Sembahlah Allah\". Tetapi tiba-tiba mereka (jadi) dua golongan yang bermusuhan.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 46, "text": "قَالَ یَـٰقَوۡمِ لِمَ تَسۡتَعۡجِلُونَ بِٱلسَّیِّئَةِ قَبۡلَ ٱلۡحَسَنَةِۖ لَوۡلَا تَسۡتَغۡفِرُونَ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ ۝٤٦", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قال صالح للفريق الكافر: لِمَ تبادرون الكفر وعمل السيئات الذي يجلب لكم العذاب، وتؤخرون الإيمان وفِعْل الحسنات الذي يجلب لكم الثواب؟ هلا تطلبون المغفرة من الله ابتداء، وتتوبون إليه؛ رجاء أن ترحموا.", "isBasmala": false, "translation_en": "He said, \"O my people, why are you quick to do evil rather than good? If only you would seek God's forgiveness, so that you may be shown mercy.\"", "translation_id": "Dia berkata: \"Hai kaumku mengapa kamu minta disegerakan keburukan sebelum (kamu minta) kebaikan? Hendaklah kamu meminta ampun kepada Allah, agar kamu mendapat rahmat\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 47, "text": "قَالُوا۟ ٱطَّیَّرۡنَا بِكَ وَبِمَن مَّعَكَۚ قَالَ طَـٰۤىِٕرُكُمۡ عِندَ ٱللَّهِۖ بَلۡ أَنتُمۡ قَوۡمࣱ تُفۡتَنُونَ ۝٤٧", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قال قوم صالح له: تَشاءَمْنا بك وبمن معك ممن دخل في دينك، قال لهم صالح: ما أصابكم الله مِن خير أو شر فهو مقدِّره عليكم ومجازيكم به، بل أنتم قوم تُخْتَبرون بالسراء والضراء والخير والشر.", "isBasmala": false, "translation_en": "They said, \"We consider you an ill omen, and those with you.\" He said, \"Your omen is with God. In fact, you are a people being tested.\"", "translation_id": "Mereka menjawab: \"Kami mendapat nasib yang malang, disebabkan kamu dan orang-orang yang besertamu\". Shaleh berkata: \"Nasibmu ada pada sisi Allah, (bukan kami yang menjadi sebab), tetapi kamu kaum yang diuji\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 48, "text": "وَكَانَ فِی ٱلۡمَدِینَةِ تِسۡعَةُ رَهۡطࣲ یُفۡسِدُونَ فِی ٱلۡأَرۡضِ وَلَا یُصۡلِحُونَ ۝٤٨", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "وكان في مدينة صالح -وهي \"الحِجْر\" الواقعة في شمال غرب جزيرة العرب- تسعة رجال، شأنهم الإفساد في الأرض، الذي لا يخالطه شيء من الصلاح.", "isBasmala": false, "translation_en": "In the city was a gang of nine who made mischief in the land and did no good.", "translation_id": "Dan adalah di kota itu sembilan orang laki-laki yang membuat kerusakan di muka bumi, dan mereka tidak berbuat kebaikan.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 49, "text": "قَالُوا۟ تَقَاسَمُوا۟ بِٱللَّهِ لَنُبَیِّتَنَّهُۥ وَأَهۡلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِیِّهِۦ مَا شَهِدۡنَا مَهۡلِكَ أَهۡلِهِۦ وَإِنَّا لَصَـٰدِقُونَ ۝٤٩", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "قال هؤلاء التسعة بعضهم لبعض: تقاسموا بالله بأن يحلف كل واحد للآخرين: لنأتينَّ صالحًا بغتة في الليل فنقتله ونقتل أهله، ثم لنقولَنَّ لوليِّ الدم مِن قرابته: ما حضرنا قتلهم، وإنا لصادقون فيما قلناه.", "isBasmala": false, "translation_en": "They said, \"Swear by God to one another that we will attack him and his family by night, and then tell his guardian, 'We did not witness the murder of his family, and we are being truthful.'\"", "translation_id": "Mereka berkata: \"Bersumpahlah kamu dengan nama Allah, bahwa kita sungguh-sungguh akan menyerangnya dengan tiba-tiba beserta keluarganya di malam hari, kemudian kita katakan kepada warisnya (bahwa) kita tidak menyaksikan kematian keluarganya itu, dan sesungguhnya kita adalah orang-orang yang benar\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 50, "text": "وَمَكَرُوا۟ مَكۡرࣰا وَمَكَرۡنَا مَكۡرࣰا وَهُمۡ لَا یَشۡعُرُونَ ۝٥٠", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "ودبَّروا هذه الحيلة لإهلاك صالح وأهله مكرًا منهم، فنصرنا نبينا صالحًا عليه السلام، وأخذناهم بالعقوبة على غِرَّة، وهم لا يتوقعون كيدنا لهم جزاءً على كيدهم.", "isBasmala": false, "translation_en": "They planned a plan, and We planned a plan, but they did not notice.", "translation_id": "Dan merekapun merencanakan makar dengan sungguh-sungguh dan Kami merencanakan makar (pula), sedang mereka tidak menyadari.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 51, "text": "فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ مَكۡرِهِمۡ أَنَّا دَمَّرۡنَـٰهُمۡ وَقَوۡمَهُمۡ أَجۡمَعِینَ ۝٥١", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "فانظر -أيها الرسول- نظرة اعتبار إلى عاقبة غَدْر هؤلاء الرهط بنبيهم صالح؟ أنا أهلكناهم وقومهم أجمعين.", "isBasmala": false, "translation_en": "So note the outcome of their planning; We destroyed them and their people, altogether.", "translation_id": "Maka perhatikanlah betapa sesungguhnya akibat makar mereka itu, bahwasanya Kami membinasakan mereka dan kaum mereka semuanya.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 52, "text": "فَتِلۡكَ بُیُوتُهُمۡ خَاوِیَةَۢ بِمَا ظَلَمُوۤا۟ۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّقَوۡمࣲ یَعۡلَمُونَ ۝٥٢", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "فتلك مساكنهم خالية ليس فيها منهم أحد، أهلكهم الله؛ بسبب ظلمهم لأنفسهم بالشرك، وتكذيب نبيهم. إن في ذلك التدمير والإهلاك لَعظة لقوم يعلمون ما فعلناه بهم، وهذه سنتنا فيمن يكذب المرسلين.", "isBasmala": false, "translation_en": "Here are their homes, in ruins, on account of their iniquities. Surely in this is a sign for people who know.", "translation_id": "Maka itulah rumah-rumah mereka dalam keadaan runtuh disebabkan kezaliman mereka. Sesungguhnya pada yang demikian itu (terdapat) pelajaran bagi kaum yang mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 53, "text": "وَأَنجَیۡنَا ٱلَّذِینَ ءَامَنُوا۟ وَكَانُوا۟ یَتَّقُونَ ۝٥٣", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "وأنجينا مما حلَّ بثمود من الهلاك صالحًا والمؤمنين به، الذين كانوا يتقون بإيمانهم عذاب الله.", "isBasmala": false, "translation_en": "And We saved those who believed and were pious.", "translation_id": "Dan telah Kami selamatkan orang-orang yang beriman dan mereka itu selalu bertakwa.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 54, "text": "وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦۤ أَتَأۡتُونَ ٱلۡفَـٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ ۝٥٤", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "واذكر لوطًا إذ قال لقومه: أتأتون الفعلة المتناهية في القبح، وأنتم تعلمون قبحها؟ أإنكم لتأتون الرجال في أدبارهم للشهوة عوضًا عن النساء؟ بل أنتم قوم تجهلون حقَّ الله عليكم، فخالفتم بذلك أمره، وعَصَيْتُم رسوله بفعلتكم القبيحة التي لم يسبقكم بها أحد من العالمين.", "isBasmala": false, "translation_en": "And Lot, when he said to his people, \"Do you commit lewdness with open eyes?", "translation_id": "Dan (ingatlah kisah) Luth, ketika dia berkata kepada kaumnya: \"Mengapa kamu mengerjakan perbuatan fahisyah itu sedang kamu memperlihatkan(nya)?\"", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 55, "text": "أَىِٕنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةࣰ مِّن دُونِ ٱلنِّسَاۤءِۚ بَلۡ أَنتُمۡ قَوۡمࣱ تَجۡهَلُونَ ۝٥٥", "juz": 19, "hizb": "(*¾ ح 38*)", "tafsir": "واذكر لوطًا إذ قال لقومه: أتأتون الفعلة المتناهية في القبح، وأنتم تعلمون قبحها؟ أإنكم لتأتون الرجال في أدبارهم للشهوة عوضًا عن النساء؟ بل أنتم قوم تجهلون حقَّ الله عليكم، فخالفتم بذلك أمره، وعَصَيْتُم رسوله بفعلتكم القبيحة التي لم يسبقكم بها أحد من العالمين.", "isBasmala": false, "translation_en": "Do you lust after men instead of women? You are truly ignorant people.\"", "translation_id": "\"Mengapa kamu mendatangi laki-laki untuk (memenuhi) nafsu(mu), bukan (mendatangi) wanita? Sebenarnya kamu adalah kaum yang tidak mengetahui (akibat perbuatanmu)\".", "manzil": 5, "manzil_display": ""}], "382": [{"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 56, "text": "۞ فَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوۤا۟ أَخۡرِجُوۤا۟ ءَالَ لُوطࣲ مِّن قَرۡیَتِكُمۡۖ إِنَّهُمۡ أُنَاسࣱ یَتَطَهَّرُونَ ۝٥٦", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "فما كان لقوم لوط جواب له إلا قول بعضهم لبعض: أَخْرجوا آل لوط من قريتكم، إنهم أناس يتنزهون عن إتيان الذكران. قالوا لهم ذلك استهزاءً بهم.", "isBasmala": false, "translation_en": "But the only response of his people was to say, \"Expel the family of Lot from your town. They are purist people.\"", "translation_id": "Maka tidak lain jawaban kaumnya melainkan mengatakan: \"Usirlah Luth beserta keluarganya dari negerimu; karena sesungguhnya mereka itu orang-orang yang (mendakwakan dirinya) bersih\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 57, "text": "فَأَنجَیۡنَـٰهُ وَأَهۡلَهُۥۤ إِلَّا ٱمۡرَأَتَهُۥ قَدَّرۡنَـٰهَا مِنَ ٱلۡغَـٰبِرِینَ ۝٥٧", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "فأنجينا لوطًا وأهله من العذاب الذي سيقع بقوم لوط، إلا امرأته قدَّرناها من الباقين في العذاب حتى تهلك مع الهالكين؛ لأنها كانت عونًا لقومها على أفعالهم القبيحة راضية بها.", "isBasmala": false, "translation_en": "So We saved him and his family, except for his wife, whom We destined to be among the laggards.", "translation_id": "Maka Kami selamatkan dia beserta keluarganya, kecuali isterinya. Kami telah mentakdirkan dia termasuk orang-orang yang tertinggal (dibinasakan).", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 58, "text": "وَأَمۡطَرۡنَا عَلَیۡهِم مَّطَرࣰاۖ فَسَاۤءَ مَطَرُ ٱلۡمُنذَرِینَ ۝٥٨", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "وأمطرنا عليهم من السماء حجارة مِن طين مهلكة، فقَبُحَ مطر المنذَرين، الذين قامت عليهم الحجة.", "isBasmala": false, "translation_en": "And We rained upon them a rain. Miserable was the rain of those forewarned.", "translation_id": "Dan Kami turunkan hujan atas mereka (hujan batu), maka amat buruklah hujan yang ditimpakan atas orang-orang yang diberi peringatan itu.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 59, "text": "قُلِ ٱلۡحَمۡدُ لِلَّهِ وَسَلَـٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِینَ ٱصۡطَفَىٰۤۗ ءَاۤللَّهُ خَیۡرٌ أَمَّا یُشۡرِكُونَ ۝٥٩", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "قل -أيها الرسول-: الثناء والشكر لله، وسلام منه، وأَمَنَةٌ على عباده الذين تخيرهم لرسالته، ثم اسأل مشركي قومك هل الله الذي يملك النفع والضر خير أو الذي يشركون من دونه، ممن لا يملك لنفسه ولا لغيره نفعًا ولا ضرًا؟", "isBasmala": false, "translation_en": "Say, \"Praise God, and peace be upon His servants whom He has selected. Is God better, or what they associate?\"", "translation_id": "Katakanlah: \"Segala puji bagi Allah dan kesejahteraan atas hamba-hamba-Nya yang dipilih-Nya. Apakah Allah yang lebih baik, ataukah apa yang mereka persekutukan dengan Dia?\"", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 60, "text": "أَمَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَنۢبَتۡنَا بِهِۦ حَدَاۤىِٕقَ ذَاتَ بَهۡجَةࣲ مَّا كَانَ لَكُمۡ أَن تُنۢبِتُوا۟ شَجَرَهَاۤۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ بَلۡ هُمۡ قَوۡمࣱ یَعۡدِلُونَ ۝٦٠", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "واسألهم مَن خلق السموات والأرض، وأنزل لكم من السماء ماء، فأنبت به حدائق ذات منظر حسن؟ ما كان لكم أن تنبتوا شجرها، لولا أن الله أنزل عليكم الماء من السماء. إن عبادته سبحانه هي الحق، وعبادة ما سواه هي الباطل. أمعبود مع الله فعل هذه الأفعال حتى يُعبد معه ويُشرك به؟ بل هؤلاء المشركون قوم ينحرفون عن طريق الحق والإيمان، فيسوون بالله غيره في العبادة والتعظيم.", "isBasmala": false, "translation_en": "Or, who created the heavens and the earth, and rains down water from the sky for you? With it We produce gardens full of beauty, whose trees you could not have produced. Is there another god with God? But they are a people who equate.", "translation_id": "Atau siapakah yang telah menciptakan langit dan bumi dan yang menurunkan air untukmu dari langit, lalu Kami tumbuhkan dengan air itu kebun-kebun yang berpemandangan indah, yang kamu sekali-kali tidak mampu menumbuhkan pohon-pohonnya? Apakah disamping Allah ada tuhan (yang lain)? Bahkan (sebenarnya) mereka adalah orang-orang yang menyimpang (dari kebenaran).", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 61, "text": "أَمَّن جَعَلَ ٱلۡأَرۡضَ قَرَارࣰا وَجَعَلَ خِلَـٰلَهَاۤ أَنۡهَـٰرࣰا وَجَعَلَ لَهَا رَوَ ٰسِیَ وَجَعَلَ بَیۡنَ ٱلۡبَحۡرَیۡنِ حَاجِزًاۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ ۝٦١", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "أعبادة ما تشركون بربكم خير أم الذي جعل لكم الأرض مستقرًا وجعل وسطها أنهارًا، وجعل لها الجبال ثوابت، وجعل بين البحرين العذب والملح حاجزًا حتى لا يُفسد أحدهما الآخر؟ أمعبود مع الله فَعَلَ ذلك حتى تشركوه معه في عبادتكم؟ بل أكثر هؤلاء المشركين لا يعلمون قَدْر عظمة الله، فهم يشركون به تقليدًا وظلمًا.", "isBasmala": false, "translation_en": "Or, who made the earth habitable, and made rivers flow through it, and set mountains on it, and placed a partition between the two seas? Is there another god with God? But most of them do not know.", "translation_id": "Atau siapakah yang telah menjadikan bumi sebagai tempat berdiam, dan yang menjadikan sungai-sungai di celah-celahnya, dan yang menjadikan gunung-gunung untuk (mengkokohkan)nya dan menjadikan suatu pemisah antara dua laut? Apakah disamping Allah ada tuhan (yang lain)? Bahkan (sebenarnya) kebanyakan dari mereka tidak mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 62, "text": "أَمَّن یُجِیبُ ٱلۡمُضۡطَرَّ إِذَا دَعَاهُ وَیَكۡشِفُ ٱلسُّوۤءَ وَیَجۡعَلُكُمۡ خُلَفَاۤءَ ٱلۡأَرۡضِۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ قَلِیلࣰا مَّا تَذَكَّرُونَ ۝٦٢", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "أعبادة ما تشركون بالله خير أم الذي يجيب المكروب إذا دعاه، ويكشف السوء النازل به، ويجعلكم خلفاء لمن سبقكم في الأرض؟ أمعبود مع الله ينعم عليكم هذه النعم؟ قليلا ما تذكرون وتعتبرون، فلذلك أشركتم بالله غيره في عبادته.", "isBasmala": false, "translation_en": "Or, who answers the one in need when he prays to Him, and relieves adversity, and makes you successors on earth? Is there another god with God? How hardly you pay attention.", "translation_id": "Atau siapakah yang memperkenankan (doa) orang yang dalam kesulitan apabila ia berdoa kepada-Nya, dan yang menghilangkan kesusahan dan yang menjadikan kamu (manusia) sebagai khalifah di bumi? Apakah disamping Allah ada tuhan (yang lain)? Amat sedikitlah kamu mengingati(Nya).", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 63, "text": "أَمَّن یَهۡدِیكُمۡ فِی ظُلُمَـٰتِ ٱلۡبَرِّ وَٱلۡبَحۡرِ وَمَن یُرۡسِلُ ٱلرِّیَـٰحَ بُشۡرَۢا بَیۡنَ یَدَیۡ رَحۡمَتِهِۦۤۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ تَعَـٰلَى ٱللَّهُ عَمَّا یُشۡرِكُونَ ۝٦٣", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "أعبادة ما تشركون بالله خير أم الذي يرشدكم في ظلمات البر والبحر إذا ضللتم فأظلمت عليكم السبل، والذي يرسل الرياح مبشرات بما يرحم به عباده مِن غيث يحيي موات الأرض؟ أمعبود مع الله يفعل بكم شيئًا من ذلك فتدعونه من دونه؟ تنزَّه الله وتقدَّس عما يشركون به غيره.", "isBasmala": false, "translation_en": "Or, who guides you through the darkness of land and sea, and who sends the winds as heralds of His mercy? Is there another god with God? Most exalted is God, above what they associate.", "translation_id": "Atau siapakah yang memimpin kamu dalam kegelapan di dataran dan lautan dan siapa (pula)kah yang mendatangkan angin sebagai kabar gembira sebelum (kedatangan) rahmat-Nya? Apakah disamping Allah ada tuhan (yang lain)? Maha Tinggi Allah terhadap apa yang mereka persekutukan (dengan-Nya).", "manzil": 5, "manzil_display": ""}], "383": [{"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 64, "text": "أَمَّن یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ وَمَن یَرۡزُقُكُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۗ أَءِلَـٰهࣱ مَّعَ ٱللَّهِۚ قُلۡ هَاتُوا۟ بُرۡهَـٰنَكُمۡ إِن كُنتُمۡ صَـٰدِقِینَ ۝٦٤", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "واسألهم من الذي ينشئ الخلق ثم يفنيه إذا شاء، ثم يعيده، ومَن الذي يرزقكم من السماء بإنزال المطر، ومن الأرض بإنبات الزرع وغيره؟ أمعبود سوى الله يفعل ذلك؟ قل: هاتوا حجتكم إن كنتم صادقين في زعمكم أن لله تعالى شريكًا في ملكه وعبادته.", "isBasmala": false, "translation_en": "Or, who originates the creation and then repeats it, and who gives you livelihood from the sky and the earth? Is there another god with God? Say, \"Produce your evidence, if you are truthful.\"", "translation_id": "Atau siapakah yang menciptakan (manusia dari permulaannya), kemudian mengulanginya (lagi), dan siapa (pula) yang memberikan rezeki kepadamu dari langit dan bumi? Apakah disamping Allah ada tuhan (yang lain)?. Katakanlah: \"Unjukkanlah bukti kebenaranmu, jika kamu memang orang-orang yang benar\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 65, "text": "قُل لَّا یَعۡلَمُ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ ٱلۡغَیۡبَ إِلَّا ٱللَّهُۚ وَمَا یَشۡعُرُونَ أَیَّانَ یُبۡعَثُونَ ۝٦٥", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "قل -أيها الرسول- لهم: لا يعلم أحد في السموات ولا في الأرض ما استأثر الله بعلمه من المغيَّبات، ولا يدرون متى هم مبعوثون مِن قبورهم عند قيام الساعة؟ بل تكامل علمهم في الآخرة، فأيقنوا بالدار الآخرة، وما فيها مِن أهوال حين عاينوها، وقد كانوا في الدنيا في شك منها، بل عميت عنها بصائرهم.", "isBasmala": false, "translation_en": "Say, \"No one in the heavens or on earth knows the future except God; and they do not perceive when they will be resurrected.\"", "translation_id": "Katakanlah: \"Tidak ada seorangpun di langit dan di bumi yang mengetahui perkara yang ghaib, kecuali Allah\", dan mereka tidak mengetahui bila mereka akan dibangkitkan.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 66, "text": "بَلِ ٱدَّ ٰرَكَ عِلۡمُهُمۡ فِی ٱلۡـَٔاخِرَةِۚ بَلۡ هُمۡ فِی شَكࣲّ مِّنۡهَاۖ بَلۡ هُم مِّنۡهَا عَمُونَ ۝٦٦", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "قل -أيها الرسول- لهم: لا يعلم أحد في السموات ولا في الأرض ما استأثر الله بعلمه من المغيَّبات، ولا يدرون متى هم مبعوثون مِن قبورهم عند قيام الساعة؟ بل تكامل علمهم في الآخرة، فأيقنوا بالدار الآخرة، وما فيها مِن أهوال حين عاينوها، وقد كانوا في الدنيا في شك منها، بل عميت عنها بصائرهم.", "isBasmala": false, "translation_en": "In fact, their knowledge of the Hereafter is confused. In fact, they are in doubt about it. In fact, they are blind to it.", "translation_id": "Sebenarnya pengetahuan mereka tentang akhirat tidak sampai (kesana) malahan mereka ragu-ragu tentang akhirat itu, lebih-lebih lagi mereka buta daripadanya.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 67, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوۤا۟ أَءِذَا كُنَّا تُرَ ٰبࣰا وَءَابَاۤؤُنَاۤ أَىِٕنَّا لَمُخۡرَجُونَ ۝٦٧", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "وقال الذين جحدوا وحدانية الله: أنحن وآباؤنا مبعوثون أحياء كهيئتنا من بعد مماتنا بعد أن صرنا ترابًا؟", "isBasmala": false, "translation_en": "Those who disbelieve say, \"When we have become dust, and our ancestors, shall we be brought out?", "translation_id": "Berkatalah orang-orang yang kafir: \"Apakah setelah kita menjadi tanah dan (begitu pula) bapak-bapak kita; apakah sesungguhnya kita akan dikeluarkan (dari kubur)?", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 68, "text": "لَقَدۡ وُعِدۡنَا هَـٰذَا نَحۡنُ وَءَابَاۤؤُنَا مِن قَبۡلُ إِنۡ هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ۝٦٨", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "لقد وُعدنا هذا البعث نحن وآباؤنا مِن قبل، فلم نر لذلك حقيقة ولم نؤمن به، ما هذا الوعد إلا مما سطَّره الأولون من الأكاذيب في كتبهم وافتروه.", "isBasmala": false, "translation_en": "We were promised that before, we and our ancestors-these are nothing but legends of the ancients.\"", "translation_id": "Sesungguhnya kami telah diberi ancaman dengan ini dan (juga) bapak-bapak kami dahulu; ini tidak lain hanyalah dongengan-dongengan orang dahulu kala\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 69, "text": "قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُجۡرِمِینَ ۝٦٩", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "قل -أيها الرسول- لهؤلاء المكذبين: سيروا في الأرض، فانظروا إلى ديار مَن كان قبلكم من المجرمين، كيف كان عاقبة المكذبين للرسل؟ أهلكهم الله بتكذيبهم، والله فاعل بكم مثلهم إن لم تؤمنوا.", "isBasmala": false, "translation_en": "Say, travel through the earth, and observe the fate of the guilty.\"", "translation_id": "Katakanlah: \"Berjalanlah kamu (di muka) bumi, lalu perhatikanlah bagaimana akibat orang-orang yang berdosa.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 70, "text": "وَلَا تَحۡزَنۡ عَلَیۡهِمۡ وَلَا تَكُن فِی ضَیۡقࣲ مِّمَّا یَمۡكُرُونَ ۝٧٠", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "ولا تحزن على إعراض المشركين عنك وتكذيبهم لك، ولا يَضِقْ صدرك مِن مكرهم بك، فإن الله ناصرك عليهم.", "isBasmala": false, "translation_en": "But do not grieve over them, and do not be troubled by what they plot.", "translation_id": "Dan janganlah kamu berduka cita terhadap mereka, dan janganlah (dadamu) merasa sempit terhadap apa yang mereka tipudayakan\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 71, "text": "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ ۝٧١", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "ويقول مشركو قومك -أيها الرسول-: متى يكون هذا الوعد بالعذاب الذي تَعِدُنا به أنت وأتباعك إن كنتم صادقين فيما تعدوننا به؟", "isBasmala": false, "translation_en": "And they say, \"When is this promise, if you are truthful?\"", "translation_id": "Dan mereka (orang-orang kafir) berkata: \"Bilakah datangnya azab itu, jika memang kamu orang-orang yang benar\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 72, "text": "قُلۡ عَسَىٰۤ أَن یَكُونَ رَدِفَ لَكُم بَعۡضُ ٱلَّذِی تَسۡتَعۡجِلُونَ ۝٧٢", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "قل لهم -أيها الرسول-: عسى أن يكون قد اقترب لكم بعض الذي تستعجلون من عذاب الله.", "isBasmala": false, "translation_en": "Say, \"Perhaps some of what you are impatient for has drawn near.\"", "translation_id": "Katakanlah: \"Mungkin telah hampir datang kepadamu sebagian dari (azab) yang kamu minta (supaya) disegerakan itu.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 73, "text": "وَإِنَّ رَبَّكَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَشۡكُرُونَ ۝٧٣", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "وإنَّ ربك لذو فضل على الناس؛ بتركه معاجلتهم بالعقوبة على معصيتهم إياه وكفرهم به، ولكن أكثرهم لا يشكرون له على ذلك، فيؤمنوا به ويخلصوا له العبادة.", "isBasmala": false, "translation_en": "Your Lord is gracious towards humanity, but most of them are not thankful.", "translation_id": "Dan sesungguhnya Tuhanmu benar-benar mempunyai kurnia yang besar (yang diberikan-Nya) kepada manusia, tetapi kebanyakan mereka tidak mensyukuri(nya).", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 74, "text": "وَإِنَّ رَبَّكَ لَیَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا یُعۡلِنُونَ ۝٧٤", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "وإن ربك لَيعلم ما تخفيه صدور خلقه وما يظهرونه.", "isBasmala": false, "translation_en": "And your Lord knows what their hearts conceal, and what they reveal.", "translation_id": "Dan sesungguhnya Tuhanmu, benar-benar mengetahui apa yang disembunyikan hati mereka dan apa yang mereka nyatakan.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 75, "text": "وَمَا مِنۡ غَاۤىِٕبَةࣲ فِی ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ إِلَّا فِی كِتَـٰبࣲ مُّبِینٍ ۝٧٥", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "وما مِن شيء غائب عن أبصار الخلق في السماء والأرض إلا في كتاب واضح عند الله. قد أحاط ذلك الكتاب بجميع ما كان وما يكون.", "isBasmala": false, "translation_en": "There is no mystery in the heaven and the earth, but it is in a Clear Book.", "translation_id": "Tiada sesuatupun yang ghaib di langit dan di bumi, melainkan (terdapat) dalam kitab yang nyata (Lauhul Mahfuzh).", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 76, "text": "إِنَّ هَـٰذَا ٱلۡقُرۡءَانَ یَقُصُّ عَلَىٰ بَنِیۤ إِسۡرَ ٰۤءِیلَ أَكۡثَرَ ٱلَّذِی هُمۡ فِیهِ یَخۡتَلِفُونَ ۝٧٦", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "إن هذا القرآن يقصُّ على بني إسرائيل الحق في أكثر الأشياء التي اختلفوا فيها.", "isBasmala": false, "translation_en": "This Quran relates to the Children of Israel most of what they differ about.", "translation_id": "Sesungguhnya Al Quran ini menjelaskan kepada Bani lsrail sebahagian besar dari (perkara-perkara) yang mereka berselisih tentangnya.", "manzil": 5, "manzil_display": ""}], "384": [{"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 77, "text": "وَإِنَّهُۥ لَهُدࣰى وَرَحۡمَةࣱ لِّلۡمُؤۡمِنِینَ ۝٧٧", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "وإن هذا القرآن لهداية من الضلال ورحمة من العذاب، لمن صدَّق به واهتدى بهداه.", "isBasmala": false, "translation_en": "And it is guidance and mercy for the believers.", "translation_id": "Dan sesungguhnya Al Quran itu benar-benar menjadi petunjuk dan rahmat bagi orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 78, "text": "إِنَّ رَبَّكَ یَقۡضِی بَیۡنَهُم بِحُكۡمِهِۦۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡعَلِیمُ ۝٧٨", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "إن ربك يقضي بين المختلفين من بني إسرائيل وغيرهم بحكمه فيهم، فينتقم من المبطل، ويجازي المحسن. وهو العزيز الغالب، فلا يُرَدُّ قضاؤه، العليم، فلا يلتبس عليه حق بباطل.", "isBasmala": false, "translation_en": "Your Lord will judge between them by His wisdom. He is the Almighty, the All-Knowing.", "translation_id": "Sesungguhnya Tuhanmu akan menyelesaikan perkara antara mereka dengan keputusan-Nya, dan Dia Maha Perkasa lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 79, "text": "فَتَوَكَّلۡ عَلَى ٱللَّهِۖ إِنَّكَ عَلَى ٱلۡحَقِّ ٱلۡمُبِینِ ۝٧٩", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "فاعتمد -أيها الرسول- في كل أمورك على الله، وثق به؛ فإنه كافيك، إنك على الحق الواضح الذي لا شك فيه.", "isBasmala": false, "translation_en": "So rely on God. You are upon the clear truth.", "translation_id": "Sebab itu bertakwalah kepada Allah, sesungguhnya kamu berada di atas kebenaran yang nyata.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 80, "text": "إِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَاۤءَ إِذَا وَلَّوۡا۟ مُدۡبِرِینَ ۝٨٠", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "إنك -أيها الرسول- لا تقدر أن تُسمع الحق مَن طبع الله على قلبه فأماته، ولا تُسمع دعوتك مَن أصمَّ الله سمعه عن سماع الحق عند إدبارهم معرضين عنك، فإن الأصم لا يسمع الدعاء إذا كان مقبلا، فكيف إذا كان معرضًا عنه موليًا مدبرًا؟", "isBasmala": false, "translation_en": "You cannot make the dead hear, nor can you make the deaf hear the call if they turn their backs and flee.", "translation_id": "Sesungguhnya kamu tidak dapat menjadikan orang-orang yang mati mendengar dan (tidak pula) menjadikan orang-orang yang tuli mendengar panggilan, apabila mereka telah berpaling membelakang.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 81, "text": "وَمَاۤ أَنتَ بِهَـٰدِی ٱلۡعُمۡیِ عَن ضَلَـٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن یُؤۡمِنُ بِـَٔایَـٰتِنَا فَهُم مُّسۡلِمُونَ ۝٨١", "juz": 20, "hizb": "(* ح 39*)", "tafsir": "وما أنت -أيها الرسول- بهادٍ عن الضلالة مَن أعماه الله عن الهدى والرشاد، ولا يمكنك أن تُسمع إلا مَن يصدِّق بآياتنا، فهم مسلمون مطيعون، مستجيبون لما دعوتهم إليه.", "isBasmala": false, "translation_en": "Nor can you guide the blind out of their straying. You can make no one listen, except those who believe in Our verses; for they are Muslims.", "translation_id": "Dan kamu sekali-kali tidak dapat memimpin (memalingkan) orang-orang buta dari kesesatan mereka. Kamu tidak dapat menjadikan (seorangpun) mendengar, kecuali orang-orang yang beriman kepada ayat-ayat Kami, lalu mereka berserah diri.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 82, "text": "۞ وَإِذَا وَقَعَ ٱلۡقَوۡلُ عَلَیۡهِمۡ أَخۡرَجۡنَا لَهُمۡ دَاۤبَّةࣰ مِّنَ ٱلۡأَرۡضِ تُكَلِّمُهُمۡ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔایَـٰتِنَا لَا یُوقِنُونَ ۝٨٢", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "وإذا وجب العذاب عليهم؛ لتماديهم في المعاصي والطغيان، وإعراضهم عن شرع الله وحكمه، حتى صاروا من شرار خلقه، أخرجنا لهم من الأرض في آخر الزمان علامة من علامات الساعة الكبرى، وهي \"الدابة\"، تحدثهم أن الناس المنكرين للبعث كانوا بالقرآن ومحمد صلى الله عليه وسلم ودينه لا يصدقون ولا يعملون.", "isBasmala": false, "translation_en": "And when the Word has fallen on them, We will bring out for them from the earth a creature which will say to them that the people are uncertain of Our revelations.", "translation_id": "Dan apabila perkataan telah jatuh atas mereka, Kami keluarkan sejenis binatang melata dari bumi yang akan mengatakan kepada mereka, bahwa sesungguhnya manusia dahulu tidak yakin kepada ayat-ayat Kami.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 83, "text": "وَیَوۡمَ نَحۡشُرُ مِن كُلِّ أُمَّةࣲ فَوۡجࣰا مِّمَّن یُكَذِّبُ بِـَٔایَـٰتِنَا فَهُمۡ یُوزَعُونَ ۝٨٣", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "ويوم نجمع يوم الحشر من كل أمة جماعة، ممن يكذب بأدلتنا وحججنا، يُحْبَس أولهم على آخرهم؛ ليجتمعوا كلهم، ثم يساقون إلى الحساب.", "isBasmala": false, "translation_en": "On the Day when We gather from every community a group of those who rejected Our revelations; and they will be restrained.", "translation_id": "Dan (ingatlah) hari (ketika) Kami kumpulkan dari tiap-tiap umat segolongan orang-orang yang mendustakan ayat-ayat Kami, lalu mereka dibagi-bagi (dalam kelompok-kelompok).", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 84, "text": "حَتَّىٰۤ إِذَا جَاۤءُو قَالَ أَكَذَّبۡتُم بِـَٔایَـٰتِی وَلَمۡ تُحِیطُوا۟ بِهَا عِلۡمًا أَمَّاذَا كُنتُمۡ تَعۡمَلُونَ ۝٨٤", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "حتى إذا جاء من كل أمة فوج ممن يكذب بآياتنا فاجتمعوا قال الله: أكذَّبْتم بآياتي التي أنزلتها على رسلي، وبالآيات التي أقمتها دلالة على توحيدي واستحقاقي وحدي للعبادة ولم تحيطوا علمًا ببطلانها، حتى تُعرضوا عنها وتُكَذِّبوا بها، أم أي شيء كنتم تعملون؟ وحقت عليهم كلمة العذاب بسبب ظلمهم وتكذيبهم، فهم لا ينطقون بحجة يدفعون بها عن أنفسهم ما حلَّ بهم من سوء العذاب.", "isBasmala": false, "translation_en": "Until, when they arrive, He will say, \"Did you reject My revelations without comprehending them? Or what is it you were doing?\"", "translation_id": "Hingga apabila mereka datang, Allah berfirman: \"Apakah kamu telah mendustakan ayat-ayat-Ku, padahal ilmu kamu tidak meliputinya, atau apakah yang telah kamu kerjakan?\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 85, "text": "وَوَقَعَ ٱلۡقَوۡلُ عَلَیۡهِم بِمَا ظَلَمُوا۟ فَهُمۡ لَا یَنطِقُونَ ۝٨٥", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "حتى إذا جاء من كل أمة فوج ممن يكذب بآياتنا فاجتمعوا قال الله: أكذَّبْتم بآياتي التي أنزلتها على رسلي، وبالآيات التي أقمتها دلالة على توحيدي واستحقاقي وحدي للعبادة ولم تحيطوا علمًا ببطلانها، حتى تُعرضوا عنها وتُكَذِّبوا بها، أم أي شيء كنتم تعملون؟ وحقت عليهم كلمة العذاب بسبب ظلمهم وتكذيبهم، فهم لا ينطقون بحجة يدفعون بها عن أنفسهم ما حلَّ بهم من سوء العذاب.", "isBasmala": false, "translation_en": "The Word will come down upon them for their wrongdoing, and they will not speak.", "translation_id": "Dan jatuhlah perkataan (azab) atas mereka disebabkan kezaliman mereka, maka mereka tidak dapat berkata (apa-apa).", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 86, "text": "أَلَمۡ یَرَوۡا۟ أَنَّا جَعَلۡنَا ٱلَّیۡلَ لِیَسۡكُنُوا۟ فِیهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝٨٦", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "ألم ير هؤلاء المكذبون بآياتنا أنا جعلنا الليل يستقرُّون فيه وينامون، والنهار يبصرون فيه للسعي في معاشهم؟ إن في تصريفهما لَدلالة لقوم يؤمنون بكمال قدرة الله ووحدانيَّته وعظيم نعمه.", "isBasmala": false, "translation_en": "Do they not see that We made the night for them to rest therein, and the day for visibility? Surely in that are signs for people who believe.", "translation_id": "Apakah mereka tidak memperhatikan, bahwa sesungguhnya Kami telah menjadikan malam supaya mereka beristirahat padanya dan siang yang menerangi? Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 87, "text": "وَیَوۡمَ یُنفَخُ فِی ٱلصُّورِ فَفَزِعَ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَمَن فِی ٱلۡأَرۡضِ إِلَّا مَن شَاۤءَ ٱللَّهُۚ وَكُلٌّ أَتَوۡهُ دَ ٰخِرِینَ ۝٨٧", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "واذكر -أيها الرسول- يوم يَنفخ الملَك في \"القرن\" ففزع مَن في السموات ومَن في الأرض فزعًا شديدًا مِن هول النفخة، إلا مَنِ استثناه الله ممن أكرمه وحفظه من الفزع، وكل المخلوقات يأتون إلى ربهم صاغرين مطيعين.", "isBasmala": false, "translation_en": "On the Day when the Trumpet is blown, everyone in the heavens and the earth will be horrified, except whomever God wills; and everyone will come before Him in humility.", "translation_id": "Dan (ingatlah) hari (ketika) ditiup sangkakala, maka terkejutlah segala yang di langit dan segala yang di bumi, kecuali siapa yang dikehendaki Allah. Dan semua mereka datang menghadap-Nya dengan merendahkan diri.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 88, "text": "وَتَرَى ٱلۡجِبَالَ تَحۡسَبُهَا جَامِدَةࣰ وَهِیَ تَمُرُّ مَرَّ ٱلسَّحَابِۚ صُنۡعَ ٱللَّهِ ٱلَّذِیۤ أَتۡقَنَ كُلَّ شَیۡءٍۚ إِنَّهُۥ خَبِیرُۢ بِمَا تَفۡعَلُونَ ۝٨٨", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "وترى الجبال تظنها واقفة مستقرة، وهي تسير سيرًا حثيثًا كسير السحاب الذي تسيِّره الرياح، وهذا مِن صنع الله الذي أحسن كل شيء خلقه وأتقنه. إن الله خبير بما يفعل عباده من خير وشر، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "And you see the mountains, and imagine them fixed, yet they pass, as the passing of the clouds-the making of God, who has perfected everything. He is fully Informed of what you do.", "translation_id": "Dan kamu lihat gunung-gunung itu, kamu sangka dia tetap di tempatnya, padahal ia berjalan sebagai jalannya awan. (Begitulah) perbuatan Allah yang membuat dengan kokoh tiap-tiap sesuatu; sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 5, "manzil_display": ""}], "385": [{"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 89, "text": "مَن جَاۤءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَیۡرࣱ مِّنۡهَا وَهُم مِّن فَزَعࣲ یَوۡمَىِٕذٍ ءَامِنُونَ ۝٨٩", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "من جاء بتوحيد الله والإيمان به وعبادته وحده، والأعمال الصالحة يوم القيامة، فله عند الله من الأجر العظيم ما هو خير منها وأفضل، وهو الجنة، وهم يوم الفزع الأكبر آمنون.", "isBasmala": false, "translation_en": "Whoever brings a virtue will receive better than it-and they will be safe from the horrors of that Day.", "translation_id": "Barangsiapa yang membawa kebaikan, maka ia memperoleh (balasan) yang lebih baik dari padanya, sedang mereka itu adalah orang-orang yang aman tenteram dari pada kejutan yang dahsyat pada hari itu.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 90, "text": "وَمَن جَاۤءَ بِٱلسَّیِّئَةِ فَكُبَّتۡ وُجُوهُهُمۡ فِی ٱلنَّارِ هَلۡ تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ ۝٩٠", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "ومن جاء بالشرك والأعمال السيئة المنكرة، فجزاؤهم أن يكبَّهم الله على وجوههم في النار يوم القيامة، ويقال لهم توبيخًا: هل تجزون إلا ما كنتم تعملون في الدنيا؟", "isBasmala": false, "translation_en": "But whoever brings evil-their faces will be tumbled into the Fire. Will you be rewarded except for what you used to do?", "translation_id": "Dan barang siapa yang membawa kejahatan, maka disungkurkanlah muka mereka ke dalam neraka. Tiadalah kamu dibalasi, melainkan (setimpal) dengan apa yang dahulu kamu kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 91, "text": "إِنَّمَاۤ أُمِرۡتُ أَنۡ أَعۡبُدَ رَبَّ هَـٰذِهِ ٱلۡبَلۡدَةِ ٱلَّذِی حَرَّمَهَا وَلَهُۥ كُلُّ شَیۡءࣲۖ وَأُمِرۡتُ أَنۡ أَكُونَ مِنَ ٱلۡمُسۡلِمِینَ ۝٩١", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "قل -أيها الرسول- للناس: إنما أُمرت أن أعبد رب هذه البلدة، وهي \"مكة\"، الذي حَرَّمها على خلقه أن يسفكوا فيها دمًا حرامًا، أو يظلموا فيها أحدًا، أو يصيدوا صيدها، أو يقطعوا شجرها، وله سبحانه كل شيء، وأُمرت أن أعبده وحده دون مَن سواه، وأُمرت أن أكون من المنقادين لأمره، المبادرين لطاعته، وأن أتلو القرآن على الناس، فمن اهتدى بما فيه واتبع ما جئت به، فإنما خير ذلك وجزاؤه لنفسه، ومن ضلَّ عن الحق فقل -أيها الرسول-: إنما أنا نذير لكم من عذاب الله وعقابه إن لم تؤمنوا، فأنا واحد من الرسل الذين أنذروا قومهم، وليس بيدي من الهداية شيء.", "isBasmala": false, "translation_en": "\"I was commanded to worship the Lord of this town, who has sanctified it, and to Whom everything belongs; and I was commanded to be of those who submit.", "translation_id": "Aku hanya diperintahkan untuk menyembah Tuhan negeri ini (Mekah) Yang telah menjadikannya suci dan kepunyaan-Nya-lah segala sesuatu, dan aku diperintahkan supaya aku termasuk orang-orang yang berserah diri.", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 92, "text": "وَأَنۡ أَتۡلُوَا۟ ٱلۡقُرۡءَانَۖ فَمَنِ ٱهۡتَدَىٰ فَإِنَّمَا یَهۡتَدِی لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَقُلۡ إِنَّمَاۤ أَنَا۠ مِنَ ٱلۡمُنذِرِینَ ۝٩٢", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "قل -أيها الرسول- للناس: إنما أُمرت أن أعبد رب هذه البلدة، وهي \"مكة\"، الذي حَرَّمها على خلقه أن يسفكوا فيها دمًا حرامًا، أو يظلموا فيها أحدًا، أو يصيدوا صيدها، أو يقطعوا شجرها، وله سبحانه كل شيء، وأُمرت أن أعبده وحده دون مَن سواه، وأُمرت أن أكون من المنقادين لأمره، المبادرين لطاعته، وأن أتلو القرآن على الناس، فمن اهتدى بما فيه واتبع ما جئت به، فإنما خير ذلك وجزاؤه لنفسه، ومن ضلَّ عن الحق فقل -أيها الرسول-: إنما أنا نذير لكم من عذاب الله وعقابه إن لم تؤمنوا، فأنا واحد من الرسل الذين أنذروا قومهم، وليس بيدي من الهداية شيء.", "isBasmala": false, "translation_en": "And to recite the Quran.\" Whoever is guided-is guided to his own advantage. And whoever goes astray, then say, \"I am one of the warners.\"", "translation_id": "Dan supaya aku membacakan Al Quran (kepada manusia). Maka barangsiapa yang mendapat petunjuk maka sesungguhnya ia hanyalah mendapat petunjuk untuk (kebaikan) dirinya, dan barangsiapa yang sesat maka katakanlah: \"Sesungguhnya aku (ini) tidak lain hanyalah salah seorang pemberi peringatan\".", "manzil": 5, "manzil_display": ""}, {"sura": 27, "sura_name": "النمل", "revelation": "Makkiyah", "aya": 93, "text": "وَقُلِ ٱلۡحَمۡدُ لِلَّهِ سَیُرِیكُمۡ ءَایَـٰتِهِۦ فَتَعۡرِفُونَهَاۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا تَعۡمَلُونَ ۝٩٣", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "وقل -أيها الرسول-: الثناء الجميل لله، سيريكم آياته في أنفسكم وفي السماء والأرض، فتعرفونها معرفة تدلكم على الحق، وتبيِّن لكم الباطل، وما ربك بغافل عما تعملون، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "And say, \"Praise belongs to God; He will show you His signs, and you will recognize them. Your Lord is not heedless of what you do.\"", "translation_id": "Dan katakanlah: \"Segala puji bagi Allah, Dia akan memperlihatkan kepadamu tanda-tanda kebesaran-Nya, maka kamu akan mengetahuinya. Dan Tuhanmu tiada lalai dari apa yang kamu kerjakan\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 20, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 1, "text": "طسۤمۤ ۝١", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "(طسم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ta, Seen, Meem.", "translation_id": "Thaa Siin Miim", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 2, "text": "تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡمُبِینِ ۝٢", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "هذه آيات القرآن الذي أنزلته إليك -أيها الرسول-، مبينًا لكل ما يحتاج إليه العباد في دنياهم وأخراهم.", "isBasmala": false, "translation_en": "These are the Verses of the Clear Book.", "translation_id": "Ini adalah ayat-ayat Kitab (Al Quran) yang nyata (dari Allah).", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 3, "text": "نَتۡلُوا۟ عَلَیۡكَ مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمࣲ یُؤۡمِنُونَ ۝٣", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "نقصُّ عليك من خبر موسى وفرعون بالصدق لقوم يؤمنون بهذا القرآن، ويصدِّقون بأنه من عند الله، ويعملون بهديه.", "isBasmala": false, "translation_en": "We narrate to you from the history of Moses and Pharaoh-in truth-for people who believe.", "translation_id": "Kami membacakan kepadamu sebagian dari kisah Musa dan Fir'aun dengan benar untuk orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 4, "text": "إِنَّ فِرۡعَوۡنَ عَلَا فِی ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِیَعࣰا یَسۡتَضۡعِفُ طَاۤىِٕفَةࣰ مِّنۡهُمۡ یُذَبِّحُ أَبۡنَاۤءَهُمۡ وَیَسۡتَحۡیِۦ نِسَاۤءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِینَ ۝٤", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "إن فرعون تكبر وطغى في الأرض، وجعل أهلها طوائف متفرقة، يستضعف طائفة منهم، وهم بنو إسرائيل، يذبِّح أبناءهم، ويستعبد نساءهم، إنه كان من المفسدين في الأرض.", "isBasmala": false, "translation_en": "Pharaoh exalted himself in the land, and divided its people into factions. He persecuted a group of them, slaughtering their sons, while sparing their daughters. He was truly a corrupter.", "translation_id": "Sesungguhnya Fir'aun telah berbuat sewenang-wenang di muka bumi dan menjadikan penduduknya berpecah belah, dengan menindas segolongan dari mereka, menyembelih anak laki-laki mereka dan membiarkan hidup anak-anak perempuan mereka. Sesungguhnya Fir'aun termasuk orang-orang yang berbuat kerusakan.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 5, "text": "وَنُرِیدُ أَن نَّمُنَّ عَلَى ٱلَّذِینَ ٱسۡتُضۡعِفُوا۟ فِی ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَىِٕمَّةࣰ وَنَجۡعَلَهُمُ ٱلۡوَ ٰرِثِینَ ۝٥", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "ونريد أن نتفضل على الذين استضعفهم فرعون في الأرض، ونجعلهم قادةً في الخير ودعاةً إليه، ونجعلهم يرثون الأرض بعد هلاك فرعون وقومه.", "isBasmala": false, "translation_en": "But We desired to favor those who were oppressed in the land, and to make them leaders, and to make them the inheritors.", "translation_id": "Dan Kami hendak memberi karunia kepada orang-orang yang tertindas di bumi (Mesir) itu dan hendak menjadikan mereka pemimpin dan menjadikan mereka orang-orang yang mewarisi (bumi),", "manzil": 5, "manzil_display": ""}], "386": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 6, "text": "وَنُمَكِّنَ لَهُمۡ فِی ٱلۡأَرۡضِ وَنُرِیَ فِرۡعَوۡنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُوا۟ یَحۡذَرُونَ ۝٦", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "ونمكن لهم في الأرض، ونجعل فرعون وهامان وجنودهما يرون من هذه الطائفة المستضعفة ما كانوا يخافونه مِن هلاكهم وذهاب ملكهم، وإخراجهم من ديارهم على يد مولود من بني إسرائيل.", "isBasmala": false, "translation_en": "And to establish them in the land; and to show Pharaoh, Hamaan, and their troops, the very thing they feared.", "translation_id": "dan akan Kami teguhkan kedudukan mereka di muka bumi dan akan Kami perlihatkan kepada Fir'aun dan Haman beserta tentaranya apa yang selalu mereka khawatirkan dari mereka itu.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 7, "text": "وَأَوۡحَیۡنَاۤ إِلَىٰۤ أُمِّ مُوسَىٰۤ أَنۡ أَرۡضِعِیهِۖ فَإِذَا خِفۡتِ عَلَیۡهِ فَأَلۡقِیهِ فِی ٱلۡیَمِّ وَلَا تَخَافِی وَلَا تَحۡزَنِیۤۖ إِنَّا رَاۤدُّوهُ إِلَیۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِینَ ۝٧", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "وألْهمنا أم موسى حين ولدته وخشيت عليه أن يذبحه فرعون كما يذبح أبناء بني إسرائيل: أن أرضعيه مطمئنة، فإذا خشيت أن يُعرف أمره فضعيه في صندوق وألقيه في النيل، دون خوف من فرعون وقومه أن يقتلوه، ودون حزن على فراقه، إنا رادُّو ولدك إليك وباعثوه رسولا. فوضعته في صندوق وألقته في النيل، فعثر عليه أعوان فرعون وأخذوه، فكانت عاقبةُ ذلك أن جعله الله لهم عدوًّا وحزنًا، فكان إهلاكُهم على يده. إن فرعون وهامان وأعوانهما كانوا آثمين مشركين.", "isBasmala": false, "translation_en": "We inspired the mother of Moses: \"Nurse him; then, when you fear for him, cast him into the river, and do not fear, nor grieve; We will return him to you, and make him one of the messengers.\"", "translation_id": "Dan kami ilhamkan kepada ibu Musa; \"Susuilah dia, dan apabila kamu khawatir terhadapnya maka jatuhkanlah dia ke sungai (Nil). Dan janganlah kamu khawatir dan janganlah (pula) bersedih hati, karena sesungguhnya Kami akan mengembalikannya kepadamu, dan menjadikannya (salah seorang) dari para rasul.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 8, "text": "فَٱلۡتَقَطَهُۥۤ ءَالُ فِرۡعَوۡنَ لِیَكُونَ لَهُمۡ عَدُوࣰّا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا كَانُوا۟ خَـٰطِـِٔینَ ۝٨", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "وألْهمنا أم موسى حين ولدته وخشيت عليه أن يذبحه فرعون كما يذبح أبناء بني إسرائيل: أن أرضعيه مطمئنة، فإذا خشيت أن يُعرف أمره فضعيه في صندوق وألقيه في النيل، دون خوف من فرعون وقومه أن يقتلوه، ودون حزن على فراقه، إنا رادُّو ولدك إليك وباعثوه رسولا. فوضعته في صندوق وألقته في النيل، فعثر عليه أعوان فرعون وأخذوه، فكانت عاقبةُ ذلك أن جعله الله لهم عدوًّا وحزنًا، فكان إهلاكُهم على يده. إن فرعون وهامان وأعوانهما كانوا آثمين مشركين.", "isBasmala": false, "translation_en": "Pharaoh's household picked him up, to be an opponent and a sorrow for them. Pharaoh, Hamaan, and their troops were sinners.", "translation_id": "Maka dipungutlah ia oleh keluarga Fir'aun yang akibatnya dia menjadi musuh dan kesedihan bagi mereka. Sesungguhnya Fir'aun dan Haman beserta tentaranya adalah orang-orang yang bersalah.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 9, "text": "وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَیۡنࣲ لِّی وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰۤ أَن یَنفَعَنَاۤ أَوۡ نَتَّخِذَهُۥ وَلَدࣰا وَهُمۡ لَا یَشۡعُرُونَ ۝٩", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "وقالت امرأة فرعون لفرعون: هذا الطفل سيكون مصدر سرور لي ولك، لا تقتلوه؛ فقد نصيب منه خيرًا أو نتخذه ولدا، وفرعون وآله لا يدركون أن هلاكهم على يديه.", "isBasmala": false, "translation_en": "Pharaoh's wife said, \"An eye's delight for me and for you. Do not kill him; perhaps he will be useful to us, or we may adopt him as a son.\" But they did not foresee.", "translation_id": "Dan berkatalah isteri Fir'aun: \"(Ia) adalah penyejuk mata hati bagiku dan bagimu. Janganlah kamu membunuhnya, mudah-mudahan ia bermanfaat kepada kita atau kita ambil ia menjadi anak\", sedang mereka tiada menyadari.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 10, "text": "وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَـٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِی بِهِۦ لَوۡلَاۤ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ ۝١٠", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "وأصبح فؤاد أم موسى خاليًا من كل شيء في الدنيا إلا من همِّ موسى وذكره، وقاربت أن تُظهِر أنه ابنها لولا أن ثبتناها، فصبرت ولم تُبْدِ به؛ لتكون من المؤمنين بوعد الله الموقنين به.", "isBasmala": false, "translation_en": "The heart of Moses' mother became vacant. She was about to disclose him, had We not steadied her heart, that she may remain a believer.", "translation_id": "Dan menjadi kosonglah hati ibu Musa. Sesungguhnya hampir saja ia menyatakan rahasia tentang Musa, seandainya tidak Kami teguhkan hatinya, supaya ia termasuk orang-orang yang percaya (kepada janji Allah).", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 11, "text": "وَقَالَتۡ لِأُخۡتِهِۦ قُصِّیهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبࣲ وَهُمۡ لَا یَشۡعُرُونَ ۝١١", "juz": 20, "hizb": "(*¼ ح 39*)", "tafsir": "وقالت أم موسى لأخته حين ألقته في اليم: اتَّبِعي أثر موسى كيف يُصْنَع به؟ فتتبعت أثره فأبصرته عن بُعْد، وقوم فرعون لا يعرفون أنها أخته، وأنها تتبع خبره.", "isBasmala": false, "translation_en": "She said to his sister, \"Trail him.\" So she watched him from afar, and they were unaware.", "translation_id": "Dan berkatalah ibu Musa kepada saudara Musa yang perempuan: \"Ikutilah dia\" Maka kelihatanlah olehnya Musa dari jauh, sedang mereka tidak mengetahuinya,", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 12, "text": "۞ وَحَرَّمۡنَا عَلَیۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَىٰۤ أَهۡلِ بَیۡتࣲ یَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَـٰصِحُونَ ۝١٢", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "وحرمنا على موسى المراضع أن يرتضع منهن مِن قبل أن نردَّه إلى أمه، فقالت أخته: هل أدلكم على أهل بيت يحسنون تربيته وإرضاعه، وهم مشفقون عليه؟ فأجابوها إلى ذلك.", "isBasmala": false, "translation_en": "We forbade him breastfeeding at first. So she said, \"Shall I tell you about a family that can raise him for you, and will look after him?\"", "translation_id": "dan Kami cegah Musa dari menyusu kepada perempuan-perempuan yang mau menyusui(nya) sebelum itu; maka berkatalah saudara Musa: \"Maukah kamu aku tunjukkan kepadamu ahlul bait yang akan memeliharanya untukmu dan mereka dapat berlaku baik kepadanya?\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 13, "text": "فَرَدَدۡنَـٰهُ إِلَىٰۤ أُمِّهِۦ كَیۡ تَقَرَّ عَیۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ ۝١٣", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "فرددنا موسى إلى أمه؛ كي تقرَّ عينها به، ووفينا إليها بالوعد؛ إذ رجع إليها سليمًا مِن قتل فرعون، ولا تحزنَ على فراقه، ولتعلم أن وعد الله حق فيما وعدها مِن ردِّه إليها وجعله من المرسلين. إن الله لا يخلف وعده، ولكن أكثر المشركين لا يعلمون أن وعد الله حق.", "isBasmala": false, "translation_en": "Thus We returned him to his mother, that she may be comforted, and not grieve, and know that God's promise is true. But most of them do not know.", "translation_id": "Maka kami kembalikan Musa kepada ibunya, supaya senang hatinya dan tidak berduka cita dan supaya ia mengetahui bahwa janji Allah itu adalah benar, tetapi kebanyakan manusia tidak mengetahuinya.", "manzil": 5, "manzil_display": ""}], "387": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 14, "text": "وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰۤ ءَاتَیۡنَـٰهُ حُكۡمࣰا وَعِلۡمࣰاۚ وَكَذَ ٰلِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ ۝١٤", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "ولما بلغ موسى أشد قوته وتكامل عقله، آتيناه حكمًا وعلمًا يعرف بهما الأحكام الشرعية، وكما جزينا موسى على طاعته وإحسانه نجزي مَن أحسن مِن عبادنا.", "isBasmala": false, "translation_en": "And when he reached his maturity, and became established, We gave him wisdom and knowledge. Thus do We reward the virtuous.", "translation_id": "Dan setelah Musa cukup umur dan sempurna akalnya, Kami berikan kepadanya hikmah (kenabian) dan pengetahuan. Dan demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 15, "text": "وَدَخَلَ ٱلۡمَدِینَةَ عَلَىٰ حِینِ غَفۡلَةࣲ مِّنۡ أَهۡلِهَا فَوَجَدَ فِیهَا رَجُلَیۡنِ یَقۡتَتِلَانِ هَـٰذَا مِن شِیعَتِهِۦ وَهَـٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَـٰثَهُ ٱلَّذِی مِن شِیعَتِهِۦ عَلَى ٱلَّذِی مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَیۡهِۖ قَالَ هَـٰذَا مِنۡ عَمَلِ ٱلشَّیۡطَـٰنِۖ إِنَّهُۥ عَدُوࣱّ مُّضِلࣱّ مُّبِینࣱ ۝١٥", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "ودخل موسى المدينة مستخفيًا وقت غفلة أهلها، فوجد فيها رجلين يقتتلان: أحدهما من قوم موسى من بني إسرائيل، والآخر من قوم فرعون، فطلب الذي من قوم موسى النصر على الذي من عدوه، فضربه موسى بجُمْع كفِّه فمات، قال موسى حين قتله: هذا من نزغ الشيطان، بأن هيَّج غضبي، حتى ضربت هذا فهلك، إن الشيطان عدو لابن آدم، مضل عن سبيل الرشاد، ظاهر العداوة. وهذا العمل من موسى عليه السلام كان قبل النبوة.", "isBasmala": false, "translation_en": "Once he entered the city, unnoticed by its people. He found in it two men fighting-one of his own sect, and one from his enemies. The one of his sect solicited his assistance against the one from his enemies; so Moses punched him, and put an end to him. He said, \"This is of Satan's doing; he is an enemy that openly misleads.\"", "translation_id": "Dan Musa masuk ke kota (Memphis) ketika penduduknya sedang lengah, maka didapatinya di dalam kota itu dua orang laki-laki yang berkelahi; yang seorang dari golongannya (Bani Israil) dan seorang (lagi) dari musuhnya (kaum Fir'aun). Maka orang yang dari golongannya meminta pertolongan kepadanya, untuk mengalahkan orang yang dari musuhnya lalu Musa meninjunya, dan matilah musuhnya itu. Musa berkata: \"Ini adalah perbuatan syaitan sesungguhnya syaitan itu adalah musuh yang menyesatkan lagi nyata (permusuhannya).", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 16, "text": "قَالَ رَبِّ إِنِّی ظَلَمۡتُ نَفۡسِی فَٱغۡفِرۡ لِی فَغَفَرَ لَهُۥۤۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ ۝١٦", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "قال موسى: رب إني ظلمت نفسي بقتل النفس التي لم تأمرني بقتلها فاغفر لي ذلك الذنب، فغفر الله له. إن الله غفور لذنوب عباده، رحيم بهم.", "isBasmala": false, "translation_en": "He said, \"My Lord, I have wronged myself, so forgive me.\" So He forgave him. He is the Forgiver, the Merciful.", "translation_id": "Musa mendoa: \"Ya Tuhanku, sesungguhnya aku telah menganiaya diriku sendiri karena itu ampunilah aku\". Maka Allah mengampuninya, sesungguhnya Allah Dialah Yang Maha Pengampun lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 17, "text": "قَالَ رَبِّ بِمَاۤ أَنۡعَمۡتَ عَلَیَّ فَلَنۡ أَكُونَ ظَهِیرࣰا لِّلۡمُجۡرِمِینَ ۝١٧", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "قال موسى: ربِّ بما أنعمت عليَّ بالتوبة والمغفرة والنعم الكثيرة، فلن أكون معينًا لأحد على معصيته وإجرامه.", "isBasmala": false, "translation_en": "He said, \"My Lord, in as much as you have favored me, I will never be a supporter of the criminals.\"", "translation_id": "Musa berkata: \"Ya Tuhanku, demi nikmat yang telah Engkau anugerahkan kepadaku, aku sekali-kali tiada akan menjadi penolong bagi orang-orang yang berdosa\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 18, "text": "فَأَصۡبَحَ فِی ٱلۡمَدِینَةِ خَاۤىِٕفࣰا یَتَرَقَّبُ فَإِذَا ٱلَّذِی ٱسۡتَنصَرَهُۥ بِٱلۡأَمۡسِ یَسۡتَصۡرِخُهُۥۚ قَالَ لَهُۥ مُوسَىٰۤ إِنَّكَ لَغَوِیࣱّ مُّبِینࣱ ۝١٨", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "فأصبح موسى في مدينة فرعون خائفًا يترقب الأخبار مما يتحدث به الناس في أمره وأمر قتيله، فرأى صاحبه بالأمس يقاتل قبطيًا آخر، ويطلب منه النصر، قال له موسى: إنك لكثير الغَواية ظاهر الضلال.", "isBasmala": false, "translation_en": "The next morning, he went about in the city, fearful and vigilant, when the man who had sought his assistance the day before was shouting out to him. Moses said to him, \"You are clearly a troublemaker.\"", "translation_id": "Karena itu, jadilah Musa di kota itu merasa takut menunggu-nunggu dengan khawatir (akibat perbuatannya), maka tiba-tiba orang yang meminta pertolongan kemarin berteriak meminta pertolongan kepadanya. Musa berkata kepadanya: \"Sesungguhnya kamu benar-benar orang sesat yang nyata (kesesatannya)\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 19, "text": "فَلَمَّاۤ أَنۡ أَرَادَ أَن یَبۡطِشَ بِٱلَّذِی هُوَ عَدُوࣱّ لَّهُمَا قَالَ یَـٰمُوسَىٰۤ أَتُرِیدُ أَن تَقۡتُلَنِی كَمَا قَتَلۡتَ نَفۡسَۢا بِٱلۡأَمۡسِۖ إِن تُرِیدُ إِلَّاۤ أَن تَكُونَ جَبَّارࣰا فِی ٱلۡأَرۡضِ وَمَا تُرِیدُ أَن تَكُونَ مِنَ ٱلۡمُصۡلِحِینَ ۝١٩", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "فلما أن أراد موسى أن يبطش بالقبطي، قال: أتريد أن تقتلني كما قتلت نفسًا بالأمس؟ ما تريد إلا أن تكون طاغية في الأرض، وما تريد أن تكون من الذين يصلحون بين الناس.", "isBasmala": false, "translation_en": "As he was about to strike the one who was their enemy, he said, \"O Moses, do you intend to kill me, as you killed someone yesterday? You only want to be a bully in the land, and do not want to be a peacemaker.\"", "translation_id": "Maka tatkala Musa hendak memegang dengan keras orang yang menjadi musuh keduanya, musuhnya berkata: \"Hai Musa, apakah kamu bermaksud hendak membunuhku, sebagaimana kamu kemarin telah membunuh seorang manusia? Kamu tidak bermaksud melainkan hendak menjadi orang yang berbuat sewenang-wenang di negeri (ini), dan tiadalah kamu hendak menjadi salah seorang dari orang-orang yang mengadakan perdamaian\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 20, "text": "وَجَاۤءَ رَجُلࣱ مِّنۡ أَقۡصَا ٱلۡمَدِینَةِ یَسۡعَىٰ قَالَ یَـٰمُوسَىٰۤ إِنَّ ٱلۡمَلَأَ یَأۡتَمِرُونَ بِكَ لِیَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّی لَكَ مِنَ ٱلنَّـٰصِحِینَ ۝٢٠", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "وجاء رجل من آخر المدينة يسعى، قال يا موسى: إن أشراف قوم فرعون يتآمرون بقتلك، ويتشاورون، فاخرج من هذه المدينة، إني لك من الناصحين المشفقين عليك.", "isBasmala": false, "translation_en": "And a man came from the farthest part of the city running. He said, \"O Moses, the authorities are considering killing you, so leave; I am giving you good advice.\"", "translation_id": "Dan datanglah seorang laki-laki dari ujung kota bergegas-gegas seraya berkata: \"Hai Musa, sesungguhnya pembesar negeri sedang berunding tentang kamu untuk membunuhmu, sebab itu keluarlah (dari kota ini) sesungguhnya aku termasuk orang-orang yang memberi nasehat kepadamu\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 21, "text": "فَخَرَجَ مِنۡهَا خَاۤىِٕفࣰا یَتَرَقَّبُۖ قَالَ رَبِّ نَجِّنِی مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝٢١", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "فخرج موسى من مدينة فرعون خائفًا ينتظر الطلب أن يدركه فيأخذه، فدعا الله أن ينقذه من القوم الظالمين.", "isBasmala": false, "translation_en": "So he left, fearful and vigilant. He said, \"My Lord, deliver me from the wrongdoing people.\"", "translation_id": "Maka keluarlah Musa dari kota itu dengan rasa takut menunggu-nunggu dengan khawatir, dia berdoa: \"Ya Tuhanku, selamatkanlah aku dari orang-orang yang zalim itu\".", "manzil": 5, "manzil_display": ""}], "388": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 22, "text": "وَلَمَّا تَوَجَّهَ تِلۡقَاۤءَ مَدۡیَنَ قَالَ عَسَىٰ رَبِّیۤ أَن یَهۡدِیَنِی سَوَاۤءَ ٱلسَّبِیلِ ۝٢٢", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "ولما قصد موسى بلاد \"مدين\" وخرج من سلطان فرعون قال: عسى ربي أن يرشدني خير طريق إلى \"مدين\".", "isBasmala": false, "translation_en": "As he headed towards Median, he said, \"Perhaps my Lord will guide me to the right way.\"", "translation_id": "Dan tatkala ia menghadap kejurusan negeri Mad-yan ia berdoa (lagi): \"Mudah-mudahan Tuhanku memimpinku ke jalan yang benar\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 23, "text": "وَلَمَّا وَرَدَ مَاۤءَ مَدۡیَنَ وَجَدَ عَلَیۡهِ أُمَّةࣰ مِّنَ ٱلنَّاسِ یَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَیۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِی حَتَّىٰ یُصۡدِرَ ٱلرِّعَاۤءُۖ وَأَبُونَا شَیۡخࣱ كَبِیرࣱ ۝٢٣", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "ولما وصل ماء \"مدين\" وجد عليه جماعة من الناس يسقون مواشيهم، ووجد من دون تلك الجماعة امرأتين منفردتين عن الناس، تحبسان غنمهما عن الماء؛ لعجزهما وضعفهما عن مزاحمة الرجال، وتنتظران حتى تَصْدُر عنه مواشي الناس، ثم تسقيان ماشيتهما، فلما رآهما موسى -عليه السلام- رقَّ لهما، ثم قال: ما شأنكما؟ قالتا: لا نستطيع مزاحمة الرجال، ولا نسقي حتى يسقي الناس، وأبونا شيخ كبير، لا يستطيع أن يسقي ماشيته؛ لضعفه وكبره.", "isBasmala": false, "translation_en": "And when he arrived at the waters of Median, he found there a crowd of people drawing water, and he noticed two women waiting on the side. He said, \"What is the matter with you?\" They said, \"We cannot draw water until the shepherds depart, and our father is a very old man.\"", "translation_id": "Dan tatkala ia sampai di sumber air negeri Mad-yan ia menjumpai di sana sekumpulan orang yang sedang meminumkan (ternaknya), dan ia menjumpai di belakang orang banyak itu, dua orang wanita yang sedang menghambat (ternaknya). Musa berkata: \"Apakah maksudmu (dengan berbuat at begitu)?\" Kedua wanita itu menjawab: \"Kami tidak dapat meminumkan (ternak kami), sebelum pengembala-pengembala itu memulangkan (ternaknya), sedang bapak kami adalah orang tua yang telah lanjut umurnya\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 24, "text": "فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰۤ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّی لِمَاۤ أَنزَلۡتَ إِلَیَّ مِنۡ خَیۡرࣲ فَقِیرࣱ ۝٢٤", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "فسقى موسى للمرأتين ماشيتهما، ثم تولى إلى ظل شجرة فاستظلَّ بها وقال: رب إني مفتقر إلى ما تسوقه إليَّ مِن أي خير كان، كالطعام. وكان قد اشتد به الجوع.", "isBasmala": false, "translation_en": "So he drew water for them, and then withdrew to the shade, and said, \"My Lord, I am in dire need of whatever good you might send down to me.\"", "translation_id": "Maka Musa memberi minum ternak itu untuk (menolong) keduanya, kemudian dia kembali ke tempat yang teduh lalu berdoa: \"Ya Tuhanku sesungguhnya aku sangat memerlukan sesuatu kebaikan yang Engkau turunkan kepadaku\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 25, "text": "فَجَاۤءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِی عَلَى ٱسۡتِحۡیَاۤءࣲ قَالَتۡ إِنَّ أَبِی یَدۡعُوكَ لِیَجۡزِیَكَ أَجۡرَ مَا سَقَیۡتَ لَنَاۚ فَلَمَّا جَاۤءَهُۥ وَقَصَّ عَلَیۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝٢٥", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "فجاءت إحدى المرأتين اللتين سقى لهما تسير إليه في حياء، قالت: إن أبي يدعوك ليعطيك أجر ما سقيت لنا، فمضى موسى معها إلى أبيها، فلما جاء أباها وقصَّ عليه قصصه مع فرعون وقومه، قال له أبوها: لا تَخَفْ نجوت من القوم الظالمين، وهم فرعون وقومه؛ إذ لا سلطان لهم بأرضنا.", "isBasmala": false, "translation_en": "Then, one of the two women approached him, walking bashfully. She said, \"My father is calling you, to reward you for drawing water for us.\" And when he came to him, and told him the story, he said, \"Do not fear, you have escaped from the wrongdoing people.\"", "translation_id": "Kemudian datanglah kepada Musa salah seorang dari kedua wanita itu berjalan kemalu-maluan, ia berkata: \"Sesungguhnya bapakku memanggil kamu agar ia memberikan balasan terhadap (kebaikan)mu memberi minum (ternak) kami\". Maka tatkala Musa mendatangi bapaknya (Syu'aib) dan menceritakan kepadanya cerita (mengenai dirinya), Syu'aib berkata: \"Janganlah kamu takut. Kamu telah selamat dari orang-orang yang zalim itu\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 26, "text": "قَالَتۡ إِحۡدَىٰهُمَا یَـٰۤأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَیۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِیُّ ٱلۡأَمِینُ ۝٢٦", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "قالت إحدى المرأتين لأبيها: يا أبت استأجره ليرعى لك ماشيتك؛ إنَّ خير من تستأجره للرعي القوي على حفظ ماشيتك، الأمين الذي لا تخاف خيانته فيما تأمنه عليه.", "isBasmala": false, "translation_en": "One of the two women said, \"Father, hire him; the best employee for you is the strong and trustworthy.\"", "translation_id": "Salah seorang dari kedua wanita itu berkata: \"Ya bapakku ambillah ia sebagai orang yang bekerja (pada kita), karena sesungguhnya orang yang paling baik yang kamu ambil untuk bekerja (pada kita) ialah orang yang kuat lagi dapat dipercaya\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 27, "text": "قَالَ إِنِّیۤ أُرِیدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَیَّ هَـٰتَیۡنِ عَلَىٰۤ أَن تَأۡجُرَنِی ثَمَـٰنِیَ حِجَجࣲۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرࣰا فَمِنۡ عِندِكَۖ وَمَاۤ أُرِیدُ أَنۡ أَشُقَّ عَلَیۡكَۚ سَتَجِدُنِیۤ إِن شَاۤءَ ٱللَّهُ مِنَ ٱلصَّـٰلِحِینَ ۝٢٧", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "قال الشيخ لموسى: إني أريد أن أزوِّجك إحدى ابنتيَّ هاتين، على أن تكون أجيرًا لي في رعي ماشيتي ثماني سنين مقابل ذلك، فإن أكملت عشر سنين فإحسان من عندك، وما أريد أن أشق عليك بجعلها عشرا، ستجدني إن شاء الله من الصالحين في حسن الصحبة والوفاء بما قلتُ.", "isBasmala": false, "translation_en": "He said, \"I want to marry you to one of these two daughters of mine, provided you work for me for eight years. But if you complete ten, that is up to you. I do not intend to impose any hardship on you. You will find me, God willing, one of the righteous.\"", "translation_id": "Berkatalah dia (Syu'aib): \"Sesungguhnya aku bermaksud menikahkan kamu dengan salah seorang dari kedua anakku ini, atas dasar bahwa kamu bekerja denganku delapan tahun dan jika kamu cukupkan sepuluh tahun maka itu adalah (suatu kebaikan) dari kamu, maka aku tidak hendak memberati kamu. Dan kamu Insya Allah akan mendapatiku termasuk orang-orang yang baik\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 28, "text": "قَالَ ذَ ٰلِكَ بَیۡنِی وَبَیۡنَكَۖ أَیَّمَا ٱلۡأَجَلَیۡنِ قَضَیۡتُ فَلَا عُدۡوَ ٰنَ عَلَیَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِیلࣱ ۝٢٨", "juz": 20, "hizb": "(*½ ح 39*)", "tafsir": "قال موسى: ذلك الذي قلته قائم بيني وبينك، أي المدتين أَقْضِها في العمل أكن قد وفيتك، فلا أُطالَب بزيادة عليها، والله على ما نقول وكيل حافظ يراقبنا، ويعلم ما تعاقدنا عليه.", "isBasmala": false, "translation_en": "He said, \"Let this be an agreement between you and me. Whichever of the two terms I fulfill, there shall be no reprisal against me; and God is witness over what we say.\"", "translation_id": "Dia (Musa) berkata: \"Itulah (perjanjian) antara aku dan kamu. Mana saja dari kedua waktu yang ditentukan itu aku sempurnakan, maka tidak ada tuntutan tambahan atas diriku (lagi). Dan Allah adalah saksi atas apa yang kita ucapkan\".", "manzil": 5, "manzil_display": ""}], "389": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 29, "text": "۞ فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦۤ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارࣰاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوۤا۟ إِنِّیۤ ءَانَسۡتُ نَارࣰا لَّعَلِّیۤ ءَاتِیكُم مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةࣲ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ ۝٢٩", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "فلما وفى نبي الله موسى -عليه السلام- صاحبه المدة عشر سنين، وهي أكمل المدتين، وسار بأهله إلى \"مصر\" أبصر من جانب الطور نارًا، قال موسى لأهله: تمهلوا وانتظروا إني أبصرت نارًا؛ لعلي آتيكم منها بنبأ، أو آتيكم بشعلة من النار لعلكم تستدفئون بها.", "isBasmala": false, "translation_en": "When Moses had completed the term, and departed with his family, he noticed a fire by the side of the Mount. He said to his family, \"Stay here, I have glimpsed a fire. Perhaps I can bring you some information from there, or an ember from the fire, that you may warm yourselves.\"", "translation_id": "Maka tatkala Musa telah menyelesaikan waktu yang ditentukan dan dia berangkat dengan keluarganya, dilihatnyalah api di lereng gunung ia berkata kepada keluarganya: \"Tunggulah (di sini), sesungguhnya aku melihat api, mudah-mudahan aku dapat membawa suatu berita kepadamu dari (tempat) api itu atau (membawa) sesuluh api, agar kamu dapat menghangatkan badan\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 30, "text": "فَلَمَّاۤ أَتَىٰهَا نُودِیَ مِن شَـٰطِىِٕ ٱلۡوَادِ ٱلۡأَیۡمَنِ فِی ٱلۡبُقۡعَةِ ٱلۡمُبَـٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن یَـٰمُوسَىٰۤ إِنِّیۤ أَنَا ٱللَّهُ رَبُّ ٱلۡعَـٰلَمِینَ ۝٣٠", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "فلما أتى موسى النار ناداه الله من جانب الوادي الأيمن لموسى في البقعة المباركة من جانب الشجرة: أن يا موسى إني أنا الله رب العالين، وأن ألق عصاك، فألقاها موسى، فصارت حية تسعى، فلما رآها موسى تضطرب كأنها جانٌّ من الحيات ولَّى هاربًا منها، ولم يلتفت من الخوف، فناداه ربه: يا موسى أقبل إليَّ ولا تَخَفْ؛ إنك من الآمنين من كل مكروه.", "isBasmala": false, "translation_en": "When he reached it, he was called from the right side of the valley, at the Blessed Spot, from the bush: \"O Moses, it is I, God, the Lord of the Worlds.", "translation_id": "Maka tatkala Musa sampai ke (tempat) api itu, diserulah dia dari (arah) pinggir lembah yang sebelah kanan(nya) pada tempat yang diberkahi, dari sebatang pohon kayu, yaitu: \"Ya Musa, sesungguhnya aku adalah Allah, Tuhan semesta alam.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 31, "text": "وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَاۤنࣱّ وَلَّىٰ مُدۡبِرࣰا وَلَمۡ یُعَقِّبۡۚ یَـٰمُوسَىٰۤ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡـَٔامِنِینَ ۝٣١", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "فلما أتى موسى النار ناداه الله من جانب الوادي الأيمن لموسى في البقعة المباركة من جانب الشجرة: أن يا موسى إني أنا الله رب العالين، وأن ألق عصاك، فألقاها موسى، فصارت حية تسعى، فلما رآها موسى تضطرب كأنها جانٌّ من الحيات ولَّى هاربًا منها، ولم يلتفت من الخوف، فناداه ربه: يا موسى أقبل إليَّ ولا تَخَفْ؛ إنك من الآمنين من كل مكروه.", "isBasmala": false, "translation_en": "Throw down your staff.\" And when he saw it wiggling, as if it were possessed, he turned his back to flee, and did not look back. \"O Moses, come forward, and do not fear, you are perfectly safe.", "translation_id": "dan lemparkanlah tongkatmu. Maka tatkala (tongkat itu menjadi ular dan) Musa melihatnya bergerak-gerak seolah-olah dia seekor ular yang gesit, larilah ia berbalik ke belakang tanpa menoleh. (Kemudian Musa diseru): \"Hai Musa datanglah kepada-Ku dan janganlah kamu takut. Sesungguhnya kamu termasuk orang-orang yang aman.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 32, "text": "ٱسۡلُكۡ یَدَكَ فِی جَیۡبِكَ تَخۡرُجۡ بَیۡضَاۤءَ مِنۡ غَیۡرِ سُوۤءࣲ وَٱضۡمُمۡ إِلَیۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ فَذَ ٰنِكَ بُرۡهَـٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ ۝٣٢", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "أدخل يدك في فتحة قميصك وأخرجها تخرج بيضاء كالثلج مِن غير مرض ولا برص، واضمم إليك يدك لتأمن من الخوف، فهاتان اللتان أريتُكَهما يا موسى: مِن تحوُّل العصا حية، وجَعْلِ يدك بيضاء تلمع من غير مرض ولا برص، آيتان من ربك إلى فرعون وأشراف قومه. إن فرعون وملأه كانوا قومًا كافرين.", "isBasmala": false, "translation_en": "Put your hand inside your pocket, and it will come out white, without blemish. And press your arm to your side, against fear. These are two proofs from your Lord, to Pharaoh and his dignitaries. They are truly sinful people.\"", "translation_id": "Masukkanlah tanganmu ke leher bajumu, niscaya ia keluar putih tidak bercacat bukan karena penyakit, dan dekapkanlah kedua tanganmu (ke dada)mu bila ketakutan, maka yang demikian itu adalah dua mukjizat dari Tuhanmu (yang akan kamu hadapkan kepada Fir'aun dan pembesar-pembesarnya). Sesungguhnya mereka adalah orang-orang yang fasik\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 33, "text": "قَالَ رَبِّ إِنِّی قَتَلۡتُ مِنۡهُمۡ نَفۡسࣰا فَأَخَافُ أَن یَقۡتُلُونِ ۝٣٣", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "قال موسى: ربِّ إني قتلت من قوم فرعون نفسًا فأخاف أن يقتلوني، وأخي هارون هو أفصح مني نطقًا، فأرسله معي عونًا يصدقني، ويبين لهم عني ما أخاطبهم به، إني أخاف أن يكذبوني في قولي لهم: إني أُرسلت إليهم.", "isBasmala": false, "translation_en": "He said, \"My Lord, I have killed one of them, and I fear they will kill me.", "translation_id": "Musa berkata: \"Ya Tuhanku sesungguhnya aku, telah membunuh seorang manusia dari golongan mereka, maka aku takut mereka akan membunuhku.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 34, "text": "وَأَخِی هَـٰرُونُ هُوَ أَفۡصَحُ مِنِّی لِسَانࣰا فَأَرۡسِلۡهُ مَعِیَ رِدۡءࣰا یُصَدِّقُنِیۤۖ إِنِّیۤ أَخَافُ أَن یُكَذِّبُونِ ۝٣٤", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "قال موسى: ربِّ إني قتلت من قوم فرعون نفسًا فأخاف أن يقتلوني، وأخي هارون هو أفصح مني نطقًا، فأرسله معي عونًا يصدقني، ويبين لهم عني ما أخاطبهم به، إني أخاف أن يكذبوني في قولي لهم: إني أُرسلت إليهم.", "isBasmala": false, "translation_en": "And my brother Aaron, he is more eloquent than me, so send him with me, to help me, and to confirm my words, for I fear they will reject me.\"", "translation_id": "Dan saudaraku Harun dia lebih fasih lidahnya daripadaku, maka utuslah dia bersamaku sebagai pembantuku untuk membenarkan (perkataan)ku; sesungguhnya aku khawatir mereka akan mendustakanku\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 35, "text": "قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِیكَ وَنَجۡعَلُ لَكُمَا سُلۡطَـٰنࣰا فَلَا یَصِلُونَ إِلَیۡكُمَا بِـَٔایَـٰتِنَاۤۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَـٰلِبُونَ ۝٣٥", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "قال الله لموسى: سنقوِّيك بأخيك، ونجعل لكما حجة على فرعون وقومه فلا يصلون إليكما بسوء. أنتما -يا موسى وهارون- ومَن آمن بكما المنتصرون على فرعون وقومه؛ بسبب آياتنا وما دلَّتْ عليه من الحق.", "isBasmala": false, "translation_en": "He said, \"We will strengthen your arm with your brother, and We will give you authority, so they will not touch you. By virtue of Our signs, you and those who follow you will be the triumphant.\"", "translation_id": "Allah berfirman: \"Kami akan membantumu dengan saudaramu, dan Kami berikan kepadamu berdua kekuasaan yang besar, maka mereka tidak dapat mencapaimu; (berangkatlah kamu berdua) dengan membawa mukjizat Kami, kamu berdua dan orang yang mengikuti kamulah yang akan menang.", "manzil": 5, "manzil_display": ""}], "390": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 36, "text": "فَلَمَّا جَاۤءَهُم مُّوسَىٰ بِـَٔایَـٰتِنَا بَیِّنَـٰتࣲ قَالُوا۟ مَا هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّفۡتَرࣰى وَمَا سَمِعۡنَا بِهَـٰذَا فِیۤ ءَابَاۤىِٕنَا ٱلۡأَوَّلِینَ ۝٣٦", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "فلما جاء موسى فرعون وملأه بأدلتنا وحججنا شاهدة بحقيقة ما جاء به موسى مِن عند ربه، قالوا لموسى: ما هذا الذي جئتنا به إلا سحر افتريته كذبًا وباطلا وما سمعنا بهذا الذي تدعونا إليه في أسلافنا الذين مضوا قبلنا.", "isBasmala": false, "translation_en": "But when Moses came to them with Our signs, clear and manifest, they said, \"This is nothing but fabricated magic, and We never heard of this from our ancestors of old.\"", "translation_id": "Maka tatkala Musa datang kepada mereka dengan (membawa) mukjizat-mukjizat Kami yang nyata, mereka berkata: \"Ini tidak lain hanyalah sihir yang dibuat-buat dan kami belum pernah mendengar (seruan yang seperti) ini pada nenek moyang kami dahulu\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 37, "text": "وَقَالَ مُوسَىٰ رَبِّیۤ أَعۡلَمُ بِمَن جَاۤءَ بِٱلۡهُدَىٰ مِنۡ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلظَّـٰلِمُونَ ۝٣٧", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "وقال موسى لفرعون: ربي أعلم بالمحقِّ منَّا الذي جاء بالرشاد من عنده، ومَن الذي له العقبى المحمودة في الدار الآخرة، إنه لا يظفر الظالمون بمطلوبهم.", "isBasmala": false, "translation_en": "Moses said, \"My Lord is well aware of him who brings guidance from Him, and him who will have the sequel of the abode. The wrongdoers will not succeed.\"", "translation_id": "Musa menjawab: \"Tuhanku lebih mengetahui orang yang (patut) membawa petunjuk dari sisi-Nya dan siapa yang akan mendapat kesudahan (yang baik) di negeri akhirat. Sesungguhnya tidaklah akan mendapat kemenangan orang-orang yang zalim\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 38, "text": "وَقَالَ فِرۡعَوۡنُ یَـٰۤأَیُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَـٰهٍ غَیۡرِی فَأَوۡقِدۡ لِی یَـٰهَـٰمَـٰنُ عَلَى ٱلطِّینِ فَٱجۡعَل لِّی صَرۡحࣰا لَّعَلِّیۤ أَطَّلِعُ إِلَىٰۤ إِلَـٰهِ مُوسَىٰ وَإِنِّی لَأَظُنُّهُۥ مِنَ ٱلۡكَـٰذِبِینَ ۝٣٨", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "وقال فرعون لأشراف قومه: يا أيها الملأ ما علمت لكم من إله غيري يستحق العبادة، فأشْعِل لي -يا هامان- على الطين نارًا، حتى يشتد، وابْنِ لي بناء عاليًا؛ لعلي أنظر إلى معبود موسى الذي يعبده ويدعو إلى عبادته، وإني لأظنه فيما يقول من الكاذبين.", "isBasmala": false, "translation_en": "Pharaoh said, \"O nobles, I know of no god for you other than me. So fire-up the bricks for me O Hamaan, and build me a tower, that I may ascend to the God of Moses, though I think he is a liar.\"", "translation_id": "Dan berkata Fir'aun: \"Hai pembesar kaumku, aku tidak mengetahui tuhan bagimu selain aku. Maka bakarlah hai Haman untukku tanah liat kemudian buatkanlah untukku bangunan yang tinggi supaya aku dapat naik melihat Tuhan Musa, dan sesungguhnya aku benar-benar yakin bahwa dia termasuk orang-orang pendusta\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 39, "text": "وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَظَنُّوۤا۟ أَنَّهُمۡ إِلَیۡنَا لَا یُرۡجَعُونَ ۝٣٩", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "واستعلى فرعون وجنوده في أرض \"مصر\" بغير الحق عن تصديق موسى واتِّباعه على ما دعاهم إليه، وحسبوا أنهم بعد مماتهم لا يبعثون.", "isBasmala": false, "translation_en": "He and his troops acted arrogantly in the land, with no justification. They thought they would not be returned to Us.", "translation_id": "dan berlaku angkuhlah Fir'aun dan bala tentaranya di bumi (Mesir) tanpa alasan yang benar dan mereka menyangka bahwa mereka tidak akan dikembalikan kepada Kami.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 40, "text": "فَأَخَذۡنَـٰهُ وَجُنُودَهُۥ فَنَبَذۡنَـٰهُمۡ فِی ٱلۡیَمِّۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلظَّـٰلِمِینَ ۝٤٠", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "فأخذنا فرعون وجنوده، فألقيناهم جميعًا في البحر وأغرقناهم، فانظر -أيها الرسول- كيف كان نهاية هؤلاء الذين ظلموا أنفسهم، فكفروا بربهم؟", "isBasmala": false, "translation_en": "So We seized him, and his troops, and We threw them into the sea. Observe, therefore, what was the end of the oppressors.", "translation_id": "Maka Kami hukumlah Fir'aun dan bala tentaranya, lalu Kami lemparkan mereka ke dalam laut. Maka lihatlah bagaimana akibat orang-orang yang zalim.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 41, "text": "وَجَعَلۡنَـٰهُمۡ أَىِٕمَّةࣰ یَدۡعُونَ إِلَى ٱلنَّارِۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ لَا یُنصَرُونَ ۝٤١", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "وجعلنا فرعون وقومه قادة إلى النار، يَقتدي بهم أهل الكفر والفسق، ويوم القيامة لا ينصرون؛ وذلك بسبب كفرهم وتكذيبهم رسول ربهم وإصرارهم على ذلك.", "isBasmala": false, "translation_en": "And We made them leaders calling to the Fire. And on Resurrection Day, they will not be saved.", "translation_id": "Dan Kami jadikan mereka pemimpin-pemimpin yang menyeru (manusia) ke neraka dan pada hari kiamat mereka tidak akan ditolong.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 42, "text": "وَأَتۡبَعۡنَـٰهُمۡ فِی هَـٰذِهِ ٱلدُّنۡیَا لَعۡنَةࣰۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ هُم مِّنَ ٱلۡمَقۡبُوحِینَ ۝٤٢", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "وأتبعنا فرعون وقومه في هذه الدنيا خزيًا وغضبًا منا عليهم، ويوم القيامة هم من المستقذرة أفعالهم، المبعدين عن رحمة الله.", "isBasmala": false, "translation_en": "And We pursued them in this world with a curse. And on Resurrection Day, they will be among the despised.", "translation_id": "Dan Kami ikutkanlah laknat kepada mereka di dunia ini; dan pada hari kiamat mereka termasuk orang-orang yang dijauhkan (dari rahmat Allah).", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 43, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ مِنۢ بَعۡدِ مَاۤ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَاۤىِٕرَ لِلنَّاسِ وَهُدࣰى وَرَحۡمَةࣰ لَّعَلَّهُمۡ یَتَذَكَّرُونَ ۝٤٣", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "ولقد آتينا موسى التوراة من بعد ما أهلكنا الأمم التي كانت من قبله -كقوم نوح وعاد وثمود وقوم لوط وأصحاب \"مدين\"- فيها بصائر لبني إسرائيل، يبصرون بها ما ينفعهم وما يضرهم، وفيها رحمة لمن عمل بها منهم؛ لعلهم يتذكرون نِعَم الله عليهم، فيشكروه عليها، ولا يكفروه.", "isBasmala": false, "translation_en": "We gave Moses the Scripture after We had annihilated the previous generations; as an illumination for mankind, and guidance, and mercy, so that they may remember.", "translation_id": "Dan sesungguhnya telah Kami berikan kepada Musa Al-Kitab (Taurat) sesudah Kami binasakan generasi-generasi yang terdahulu, untuk menjadi pelita bagi manusia dan petunjuk dan rahmat, agar mereka ingat.", "manzil": 5, "manzil_display": ""}], "391": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 44, "text": "وَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِیِّ إِذۡ قَضَیۡنَاۤ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ مِنَ ٱلشَّـٰهِدِینَ ۝٤٤", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "وما كنت -أيها الرسول- بجانب الجبل الغربي من موسى إذ كلَّفناه أَمْرنا ونَهْينا، وما كنت من الشاهدين لذلك، حتى يقال: إنه وصل إليك من هذا الطريق.", "isBasmala": false, "translation_en": "You were not on the Western Side when We decreed the command to Moses, nor were you among the witnesses.", "translation_id": "Dan tidaklah kamu (Muhammad) berada di sisi yang sebelah barat ketika Kami menyampaikan perintah kepada Musa, dan tiada pula kamu termasuk orang-orang yang menyaksikan.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 45, "text": "وَلَـٰكِنَّاۤ أَنشَأۡنَا قُرُونࣰا فَتَطَاوَلَ عَلَیۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِیࣰا فِیۤ أَهۡلِ مَدۡیَنَ تَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِنَا وَلَـٰكِنَّا كُنَّا مُرۡسِلِینَ ۝٤٥", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "ولكنا خلقنا أممًا من بعد موسى، فمكثوا زمنًا طويلا فنسوا عهد الله، وتركوا أمره، وما كنت مقيمًا في أهل \"مدين\" تقرأ عليهم كتابنا، فتعرف قصتهم وتخبر بها، ولكن ذلك الخبر الذي جئت به عن موسى وحي، وشاهد على رسالتك.", "isBasmala": false, "translation_en": "But We established many generations, and time took its toll on them. Nor were you among the people of Median, reciting Our revelations to them. But We kept sending messengers.", "translation_id": "Tetapi Kami telah mengadakan beberapa generasi, dan berlalulah atas mereka masa yang panjang, dan tiadalah kamu tinggal bersama-sama penduduk Mad-yan dengan membacakan ayat-ayat Kami kepada mereka, tetapi Kami telah mengutus rasul-rasul.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 46, "text": "وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذۡ نَادَیۡنَا وَلَـٰكِن رَّحۡمَةࣰ مِّن رَّبِّكَ لِتُنذِرَ قَوۡمࣰا مَّاۤ أَتَىٰهُم مِّن نَّذِیرࣲ مِّن قَبۡلِكَ لَعَلَّهُمۡ یَتَذَكَّرُونَ ۝٤٦", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "وما كنت -أيها الرسول- بجانب جبل الطور حين نادينا موسى، ولم تشهد شيئًا من ذلك فتعلمه، ولكنا أرسلناك رحمة من ربك؛ لتنذر قومًا لم يأتهم مِن قبلك من نذير؛ لعلهم يتذكرون الخير الذي جئتَ به فيفعلوه، والشرَّ الذي نَهيتَ عنه فيجتنبوه.", "isBasmala": false, "translation_en": "Nor were you by the side of the Mount when We proclaimed. Rather, it was a mercy from your Lord, that you may warn people who received no warner before you, so that they may take heed.", "translation_id": "Dan tiadalah kamu berada di dekat gunung Thur ketika Kami menyeru (Musa), tetapi (Kami beritahukan itu kepadamu) sebagai rahmat dari Tuhanmu, supaya kamu memberi peringatan kepada kaum (Quraisy) yang sekali-kali belum datang kepada mereka pemberi peringatan sebelum kamu agar mereka ingat.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 47, "text": "وَلَوۡلَاۤ أَن تُصِیبَهُم مُّصِیبَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ فَیَقُولُوا۟ رَبَّنَا لَوۡلَاۤ أَرۡسَلۡتَ إِلَیۡنَا رَسُولࣰا فَنَتَّبِعَ ءَایَـٰتِكَ وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ ۝٤٧", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "ولولا أن ينزل بهؤلاء الكفار عذاب بسبب كفرهم بربهم، فيقولوا: ربنا هلا أرسلت إلينا رسولا من قبل، فنتبع آياتك المنزلة في كتابك، ونكون من المؤمنين بك.", "isBasmala": false, "translation_en": "Otherwise, if a calamity befell them as a result of what their hands have perpetrated, they would say, \"Our Lord, if only You had sent us a messenger, we would have followed Your revelations, and been among the believers.\"", "translation_id": "Dan agar mereka tidak mengatakan ketika azab menimpa mereka disebabkan apa yang mereka kerjakan: \"Ya Tuhan kami, mengapa Engkau tidak mengutus seorang rasul kepada kami, lalu kami mengikuti ayat-ayat Engkau dan jadilah kami termasuk orang-orang mukmin\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 48, "text": "فَلَمَّا جَاۤءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوا۟ لَوۡلَاۤ أُوتِیَ مِثۡلَ مَاۤ أُوتِیَ مُوسَىٰۤۚ أَوَ لَمۡ یَكۡفُرُوا۟ بِمَاۤ أُوتِیَ مُوسَىٰ مِن قَبۡلُۖ قَالُوا۟ سِحۡرَانِ تَظَـٰهَرَا وَقَالُوۤا۟ إِنَّا بِكُلࣲّ كَـٰفِرُونَ ۝٤٨", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "فلما جاء محمد هؤلاء القوم نذيرًا لهم، قالوا: هلا أوتي هذا الذي أُرسل إلينا مثل ما أوتي موسى من معجزات حسية، وكتابٍ نزل جملة واحدة! قل -أيها الرسول- لهم: أولم يكفر اليهود بما أوتي موسى من قبل؟ قالوا: في التوراة والقرآن سحران تعاونا في سحرهما، وقالوا: نحن بكل منهما كافرون.", "isBasmala": false, "translation_en": "But when the truth came to them from Us, they said, \"If only he was given the like of what was given to Moses.\" Did they not disbelieve in what was given to Moses in the past? They said, \"Two works of magic backing one another.\" And they said, \"We are disbelieving in both.\"", "translation_id": "Maka tatkala datang kepada mereka kebenaran dari sisi Kami, mereka berkata: \"Mengapakah tidak diberikan kepadanya (Muhammad) seperti yang telah diberikan kepada Musa dahulu?\". Dan bukankah mereka itu telah ingkar (juga) kepada apa yang telah diberikan kepada Musa dahulu?; mereka dahulu telah berkata: \"Musa dan Harun adalah dua ahli sihir yang bantu membantu\". Dan mereka (juga) berkata: \"Sesungguhnya kami tidak mempercayai masing-masing mereka itu\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 49, "text": "قُلۡ فَأۡتُوا۟ بِكِتَـٰبࣲ مِّنۡ عِندِ ٱللَّهِ هُوَ أَهۡدَىٰ مِنۡهُمَاۤ أَتَّبِعۡهُ إِن كُنتُمۡ صَـٰدِقِینَ ۝٤٩", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "قل -أيها الرسول- لهؤلاء: فأتوا بكتاب من عند الله هو أقوم من التوراة والقرآن أتبعه، إن كنتم صادقين في زعمكم.", "isBasmala": false, "translation_en": "Say, \"Then bring a scripture from God, more conductive to guidance than both, and I will follow it, if you are truthful.\"", "translation_id": "Katakanlah: \"Datangkanlah olehmu sebuah kitab dari sisi Allah yang kitab itu lebih (dapat) memberi petunjuk daripada keduanya (Taurat dan Al Quran) niscaya aku mengikutinya, jika kamu sungguh orang-orang yang benar\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 50, "text": "فَإِن لَّمۡ یَسۡتَجِیبُوا۟ لَكَ فَٱعۡلَمۡ أَنَّمَا یَتَّبِعُونَ أَهۡوَاۤءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَیۡرِ هُدࣰى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝٥٠", "juz": 20, "hizb": "(*¾ ح 39*)", "tafsir": "فإن لم يستجيبوا لك بالإتيان بالكتاب، ولم تبق لهم حجة، فاعلم أنما يتبعون أهواءهم، ولا أحد أكثر ضلالا ممن اتبع هواه بغير هدى من الله. إن الله لا يوفِّق لإصابة الحق القوم الظالمين الذين خالفوا أمر الله، وتجاوزوا حدوده.", "isBasmala": false, "translation_en": "But if they fail to respond to you, know that they follow their fancies. And who is more lost than him who follows his fancy without guidance from God? God does not guide the unjust people.", "translation_id": "Maka jika mereka tidak menjawab (tantanganmu) ketahuilah bahwa sesungguhnya mereka hanyalah mengikuti hawa nafsu mereka (belaka). Dan siapakah yang lebih sesat daripada orang yang mengikuti hawa nafsunya dengan tidak mendapat petunjuk dari Allah sedikitpun. Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang zalim.", "manzil": 5, "manzil_display": ""}], "392": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 51, "text": "۞ وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ یَتَذَكَّرُونَ ۝٥١", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "ولقد فصَّلنا وبيَّنا القرآن رحمة بقومك أيها الرسول؛ لعلهم يتذكرون، فيتعظوا به.", "isBasmala": false, "translation_en": "We have delivered the Word to them, that they may remember.", "translation_id": "Dan sesungguhnya telah Kami turunkan berturut-turut perkataan ini (Al Quran) kepada mereka agar mereka mendapat pelajaran.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 52, "text": "ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ مِن قَبۡلِهِۦ هُم بِهِۦ یُؤۡمِنُونَ ۝٥٢", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "الذين آتيناهم الكتاب من قبل القرآن -وهم اليهود والنصارى الذين لم يبدِّلوا- يؤمنون بالقرآن وبمحمد عليه الصلاة والسلام.", "isBasmala": false, "translation_en": "Those to whom We gave the Scripture before it believe in it.", "translation_id": "Orang-orang yang telah Kami datangkan kepada mereka Al Kitab sebelum Al Quran, mereka beriman (pula) dengan Al Quran itu.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 53, "text": "وَإِذَا یُتۡلَىٰ عَلَیۡهِمۡ قَالُوۤا۟ ءَامَنَّا بِهِۦۤ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّنَاۤ إِنَّا كُنَّا مِن قَبۡلِهِۦ مُسۡلِمِینَ ۝٥٣", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "وإذا يتلى هذا القرآن على الذين آتيناهم الكتاب، قالوا: صدَّقنا به، وعملنا بما فيه، إنه الحق من عند ربنا، إنا كنا من قبل نزوله مسلمين موحدين، فدين الله واحد، وهو الإسلام.", "isBasmala": false, "translation_en": "When it is recited to them, they say, \"We have believed in it; it is the truth from our Lord; we were Muslims prior to it.\"", "translation_id": "Dan apabila dibacakan (Al Quran itu) kepada mereka, mereka berkata: \"Kami beriman kepadanya; sesungguhnya; Al Quran itu adalah suatu kebenaran dari Tuhan kami, sesungguhnya kami sebelumnya adalah orang-orang yang membenarkan(nya).", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 54, "text": "أُو۟لَـٰۤىِٕكَ یُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَیۡنِ بِمَا صَبَرُوا۟ وَیَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّیِّئَةَ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ ۝٥٤", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "هؤلاء الذين تقدَّمَتْ صفتُهم يُؤتَوْن ثواب عملهم مرتين: على الإيمان بكتابهم، وعلى إيمانهم بالقرآن بما صبروا، ومن أوصافهم أنهم يدفعون السيئة بالحسنة، ومما رزقناهم ينفقون في سبيل الخير والبر. وإذا سمع هؤلاء القوم الباطل من القول لم يُصْغوا إليه، وقالوا: لنا أعمالنا لا نحيد عنها، ولكم أعمالكم ووزرها عليكم، فنحن لا نشغل أنفسنا بالرد عليكم، ولا تسمعون منَّا إلا الخير، ولا نخاطبهم بمقتضى جهلكم؛ لأننا لا نريد طريق الجاهلين ولا نحبها. وهذا من خير ما يقوله الدعاة إلى الله.", "isBasmala": false, "translation_en": "These will be given their reward twice, because they persevered; and they counter evil with good; and from Our provisions to them, they give.", "translation_id": "Mereka itu diberi pahala dua kali disebabkan kesabaran mereka, dan mereka menolak kejahatan dengan kebaikan, dan sebagian dari apa yang telah Kami rezekikan kepada mereka, mereka nafkahkan.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 55, "text": "وَإِذَا سَمِعُوا۟ ٱللَّغۡوَ أَعۡرَضُوا۟ عَنۡهُ وَقَالُوا۟ لَنَاۤ أَعۡمَـٰلُنَا وَلَكُمۡ أَعۡمَـٰلُكُمۡ سَلَـٰمٌ عَلَیۡكُمۡ لَا نَبۡتَغِی ٱلۡجَـٰهِلِینَ ۝٥٥", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "هؤلاء الذين تقدَّمَتْ صفتُهم يُؤتَوْن ثواب عملهم مرتين: على الإيمان بكتابهم، وعلى إيمانهم بالقرآن بما صبروا، ومن أوصافهم أنهم يدفعون السيئة بالحسنة، ومما رزقناهم ينفقون في سبيل الخير والبر. وإذا سمع هؤلاء القوم الباطل من القول لم يُصْغوا إليه، وقالوا: لنا أعمالنا لا نحيد عنها، ولكم أعمالكم ووزرها عليكم، فنحن لا نشغل أنفسنا بالرد عليكم، ولا تسمعون منَّا إلا الخير، ولا نخاطبهم بمقتضى جهلكم؛ لأننا لا نريد طريق الجاهلين ولا نحبها. وهذا من خير ما يقوله الدعاة إلى الله.", "isBasmala": false, "translation_en": "And when they hear vain talk, they avoid it, and say, \"We have our deeds, and you have your deeds; peace be upon you; we do not desire the ignorant.\"", "translation_id": "Dan apabila mereka mendengar perkataan yang tidak bermanfaat, mereka berpaling daripadanya dan mereka berkata: \"Bagi kami amal-amal kami dan bagimu amal-amalmu, kesejahteraan atas dirimu, kami tidak ingin bergaul dengan orang-orang jahil\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 56, "text": "إِنَّكَ لَا تَهۡدِی مَنۡ أَحۡبَبۡتَ وَلَـٰكِنَّ ٱللَّهَ یَهۡدِی مَن یَشَاۤءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ ۝٥٦", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "إنك -أيها الرسول- لا تهدي هداية توفيق مَن أحببت هدايته، ولكن ذلك بيد الله يهدي مَن يشاء أن يهديه للإيمان، ويوفقه إليه، وهو أعلم بمن يصلح للهداية فيهديه.", "isBasmala": false, "translation_en": "You cannot guide whom you love, but God guides whom He wills, and He knows best those who are guided.", "translation_id": "Sesungguhnya kamu tidak akan dapat memberi petunjuk kepada orang yang kamu kasihi, tetapi Allah memberi petunjuk kepada orang yang dikehendaki-Nya, dan Allah lebih mengetahui orang-orang yang mau menerima petunjuk.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 57, "text": "وَقَالُوۤا۟ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَاۤۚ أَوَ لَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنࣰا یُجۡبَىٰۤ إِلَیۡهِ ثَمَرَ ٰتُ كُلِّ شَیۡءࣲ رِّزۡقࣰا مِّن لَّدُنَّا وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ ۝٥٧", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "وقال كفار \"مكة\": إن نتبع الحق الذي جئتنا به، ونتبرأ من الأولياء والآلهة، نُتَخَطَّفْ من أرضنا بالقتل والأسر ونهب الأموال، أولم نجعلهم متمكنين في بلد آمن، حرَّمنا على الناس سفك الدماء فيه، يُجلب إليه ثمرات كل شيء رزقًا مِن لدنا؟ ولكن أكثر هؤلاء المشركين لا يعلمون قَدْر هذه النعم عليهم، فيشكروا مَن أنعم عليهم بها ويطيعوه.", "isBasmala": false, "translation_en": "And they say, \"If we follow the guidance with you, we will be snatched from our land.\" Did We not establish for them a Safe Sanctuary, to which are brought all kinds of fruits, as provision from Ourselves? But most of them do not know.", "translation_id": "Dan mereka berkata: \"Jika kami mengikuti petunjuk bersama kamu, niscaya kami akan diusir dari negeri kami\". Dan apakah Kami tidak meneguhkan kedudukan mereka dalam daerah haram (tanah suci) yang aman, yang didatangkan ke tempat itu buah-buahan dari segala macam (tumbuh-tumbuhan) untuk menjadi rezeki (bagimu) dari sisi Kami?. Tetapi kebanyakan mereka tidak mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 58, "text": "وَكَمۡ أَهۡلَكۡنَا مِن قَرۡیَةِۭ بَطِرَتۡ مَعِیشَتَهَاۖ فَتِلۡكَ مَسَـٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ إِلَّا قَلِیلࣰاۖ وَكُنَّا نَحۡنُ ٱلۡوَ ٰرِثِینَ ۝٥٨", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "وكثير من أهل القرى أهلكناهم حين أَلْهَتهم معيشتهم عن الإيمان بالرسل، فكفروا وطغَوْا، فتلك مساكنهم لم تُسكن من بعدهم إلا قليلا منها، وكنا نحن الوارثين للعباد نميتهم، ثم يرجعون إلينا، فنجازيهم بأعمالهم.", "isBasmala": false, "translation_en": "And how many a city did We destroy for turning unappreciative of its livelihood? Here are their homes, uninhabited after them, except for a few. And We became the Inheritors.", "translation_id": "Dan berapa banyaknya (penduduk) negeri yang telah Kami binasakan, yang sudah bersenang-senang dalam kehidupannya; maka itulah tempat kediaman mereka yang tiada di diami (lagi) sesudah mereka, kecuali sebahagian kecil. Dan Kami adalah Pewaris(nya).", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 59, "text": "وَمَا كَانَ رَبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ یَبۡعَثَ فِیۤ أُمِّهَا رَسُولࣰا یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِنَاۚ وَمَا كُنَّا مُهۡلِكِی ٱلۡقُرَىٰۤ إِلَّا وَأَهۡلُهَا ظَـٰلِمُونَ ۝٥٩", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "وما كان ربك -أيها الرسول- مهلك القرى التي حول \"مكة\" في زمانك حتى يبعث في أمها -وهي \"مكة\"- رسولا يتلو عليهم آياتنا، وما كنا مهلكي القرى إلا وأهلها ظالمون لأنفسهم بكفرهم بالله ومعصيته، فهم بذلك مستحقون للعقوبة والنكال.", "isBasmala": false, "translation_en": "Your Lord never destroys cities without first sending a messenger in their midst, reciting to them Our revelations. And We never destroy the cities, unless their people are wrongdoers.", "translation_id": "Dan tidak adalah Tuhanmu membinasakan kota-kota, sebelum Dia mengutus di ibukota itu seorang rasul yang membacakan ayat-ayat Kami kepada mereka; dan tidak pernah (pula) Kami membinasakan kota-kota; kecuali penduduknya dalam keadaan melakukan kezaliman.", "manzil": 5, "manzil_display": ""}], "393": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 60, "text": "وَمَاۤ أُوتِیتُم مِّن شَیۡءࣲ فَمَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَزِینَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَیۡرࣱ وَأَبۡقَىٰۤۚ أَفَلَا تَعۡقِلُونَ ۝٦٠", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "وما أُعطيتم -أيها الناس- من شيء من الأموال والأولاد، فإنما هو متاع تتمتعون به في هذه الحياة الدنيا، وزينة يُتزيَّن بها، وما عند الله لأهل طاعته وولايته خير وأبقى؛ لأنه دائم لا نفاد له، أفلا تكون لكم عقول -أيها القوم- تتدبرون بها، فتعرفون الخير من الشر؟", "isBasmala": false, "translation_en": "Whatever thing you are given is but the material of this world, and its glitter. But what is with God is better, and longer lasting. Do you not comprehend?", "translation_id": "Dan apa saja yang diberikan kepada kamu, maka itu adalah kenikmatan hidup duniawi dan perhiasannya; sedang apa yang di sisi Allah adalah lebih baik dan lebih kekal. Maka apakah kamu tidak memahaminya?", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 61, "text": "أَفَمَن وَعَدۡنَـٰهُ وَعۡدًا حَسَنࣰا فَهُوَ لَـٰقِیهِ كَمَن مَّتَّعۡنَـٰهُ مَتَـٰعَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا ثُمَّ هُوَ یَوۡمَ ٱلۡقِیَـٰمَةِ مِنَ ٱلۡمُحۡضَرِینَ ۝٦١", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "أفمَن وعدناه مِن خَلْقنا على طاعته إيانا الجنة، فهو ملاقٍ ما وُعِدَ، وصائر إليه، كمن متعناه في الحياة الدنيا متاعها، فتمتع به، وآثر لذة عاجلة على آجلة، ثم هو يوم القيامة من المحضرين للحساب والجزاء؟ لا يستوي الفريقان، فليختر العاقل لنفسه ما هو أولى بالاختيار، وهو طاعة الله وابتغاء مرضاته.", "isBasmala": false, "translation_en": "Can someone to whom We have made a fine promise-which he will attain-be equal to someone to whom We have given enjoyments in this world, but who will be, on Resurrection Day, among the arraigned?", "translation_id": "Maka apakah orang yang Kami janjikan kepadanya suatu janji yang baik (surga) lalu ia memperolehnya, sama dengan orang yang Kami berikan kepadanya kenikmatan hidup duniawi; kemudian dia pada hari kiamat termasuk orang-orang yang diseret (ke dalam neraka)?", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 62, "text": "وَیَوۡمَ یُنَادِیهِمۡ فَیَقُولُ أَیۡنَ شُرَكَاۤءِیَ ٱلَّذِینَ كُنتُمۡ تَزۡعُمُونَ ۝٦٢", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "ويوم ينادي الله عز وجل الذين أشركوا به الأولياء والأوثان في الدنيا، فيقول لهم: أين شركائي الذين كنتم تزعمون أنهم لي شركاء؟", "isBasmala": false, "translation_en": "On the Day when He will call to them, and say, \"Where are My associates whom you used to claim?\"", "translation_id": "Dan (ingatlah) hari (di waktu) Allah menyeru mereka, seraya berkata: \"Di manakah sekutu-sekutu-Ku yang dahulu kamu katakan?\"", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 63, "text": "قَالَ ٱلَّذِینَ حَقَّ عَلَیۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَـٰۤؤُلَاۤءِ ٱلَّذِینَ أَغۡوَیۡنَاۤ أَغۡوَیۡنَـٰهُمۡ كَمَا غَوَیۡنَاۖ تَبَرَّأۡنَاۤ إِلَیۡكَۖ مَا كَانُوۤا۟ إِیَّانَا یَعۡبُدُونَ ۝٦٣", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "قال الذين حقَّ عليهم العذاب، وهم دعاة الكفر: ربنا هؤلاء الذين أضللنا، أضللناهم كما ضللنا، تبرأنا إليك مِن ولايتهم ونصرتهم، ما كانوا إيانا يعبدون، وإنما كانوا يعبدون الشياطين.", "isBasmala": false, "translation_en": "Those against whom the sentence is justified will say, \"Our Lord, these are they whom we misled. We misled them, as we were misled. We beg Your forgiveness; it was not us they used to worship.\"", "translation_id": "Berkatalah orang-orang yang telah tetap hukuman atas mereka; \"Ya Tuhan kami, mereka inilah orang-orang yang kami sesatkan itu; kami telah menyesatkan mereka sebagaimana kami (sendiri) sesat, kami menyatakan berlepas diri (dari mereka) kepada Engkau, mereka sekali-kali tidak menyembah kami\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 64, "text": "وَقِیلَ ٱدۡعُوا۟ شُرَكَاۤءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ یَسۡتَجِیبُوا۟ لَهُمۡ وَرَأَوُا۟ ٱلۡعَذَابَۚ لَوۡ أَنَّهُمۡ كَانُوا۟ یَهۡتَدُونَ ۝٦٤", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "وقيل للمشركين بالله يوم القيامة: ادعوا شركاءكم الذين كنتم تعبدونهم من دون الله، فدعوهم فلم يستجيبوا لهم، وعاينوا العذاب، لو أنهم كانوا في الدنيا مهتدين للحق لما عُذِّبوا.", "isBasmala": false, "translation_en": "And it will be said, \"Call on your partners.\" And they will call on them, but they will not respond to them. And they will see the suffering. If only they were guided.", "translation_id": "Dikatakan (kepada mereka) \"Serulah olehmu sekutu-sekutu kamu\", lalu mereka menyerunya, maka sekutu-sekutu itu tidak memperkenankan (seruan) mereka, dan mereka melihat azab. (Mereka ketika itu berkeinginan) kiranya mereka dahulu menerima petunjuk.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 65, "text": "وَیَوۡمَ یُنَادِیهِمۡ فَیَقُولُ مَاذَاۤ أَجَبۡتُمُ ٱلۡمُرۡسَلِینَ ۝٦٥", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "ويوم ينادي الله هؤلاء المشركين، فيقول: بأيِّ شيء أجبتم المرسلين فيما أرسلناهم به إليكم؟", "isBasmala": false, "translation_en": "On the Day when He will call to them, and say, \"What did you answer the Messengers?\"", "translation_id": "Dan (ingatlah) hari (di waktu) Allah menyeru mereka, seraya berkata: \"Apakah jawabanmu kepada para rasul?\"", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 66, "text": "فَعَمِیَتۡ عَلَیۡهِمُ ٱلۡأَنۢبَاۤءُ یَوۡمَىِٕذࣲ فَهُمۡ لَا یَتَسَاۤءَلُونَ ۝٦٦", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "فخفيت عليهم الحجج، فلم يَدْروا ما يحتجون به، فهم لا يسأل بعضهم بعضًا عما يحتجون به سؤال انتفاع.", "isBasmala": false, "translation_en": "They will be blinded by the facts on that Day, and they will not question each other.", "translation_id": "Maka gelaplah bagi mereka segala macam alasan pada hari itu, karena itu mereka tidak saling tanya menanya.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 67, "text": "فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَعَسَىٰۤ أَن یَكُونَ مِنَ ٱلۡمُفۡلِحِینَ ۝٦٧", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "فأما من تاب من المشركين، وأخلص لله العبادة، وعمل بما أمره الله به ورسوله، فهو من الفائزين في الدارين.", "isBasmala": false, "translation_en": "But he who repents, and believes, and does righteous deeds, may well be among the winners.", "translation_id": "Adapun orang yang bertaubat dan beriman, serta mengerjakan amal yang saleh, semoga dia termasuk orang-orang yang beruntung.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 68, "text": "وَرَبُّكَ یَخۡلُقُ مَا یَشَاۤءُ وَیَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِیَرَةُۚ سُبۡحَـٰنَ ٱللَّهِ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ ۝٦٨", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "وربك يخلق ما يشاء أن يخلقه، ويصطفي لولايته مَن يشاء من خلقه، وليس لأحد من الأمر والاختيار شيء، وإنما ذلك لله وحده سبحانه، تعالى وتنزَّه عن شركهم.", "isBasmala": false, "translation_en": "Your Lord creates whatever He wills, and He chooses. The choice is not theirs. Glory be to God, and exalted be He above the associations they make.", "translation_id": "Dan Tuhanmu menciptakan apa yang Dia kehendaki dan memilihnya. Sekali-kali tidak ada pilihan bagi mereka. Maha Suci Allah dan Maha Tinggi dari apa yang mereka persekutukan (dengan Dia).", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 69, "text": "وَرَبُّكَ یَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا یُعۡلِنُونَ ۝٦٩", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "وربك يعلم ما تُخفي صدور خلقه وما يظهرونه.", "isBasmala": false, "translation_en": "And your Lord knows what their hearts conceal, and what they reveal.", "translation_id": "Dan Tuhanmu mengetahui apa yang disembunyikan (dalam) dada mereka dan apa yang mereka nyatakan.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 70, "text": "وَهُوَ ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ لَهُ ٱلۡحَمۡدُ فِی ٱلۡأُولَىٰ وَٱلۡـَٔاخِرَةِۖ وَلَهُ ٱلۡحُكۡمُ وَإِلَیۡهِ تُرۡجَعُونَ ۝٧٠", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "وهو الله الذي لا معبود بحق سواه، له الثناء الجميل والشكر في الدنيا والآخرة، وله الحكم بين خلقه، وإليه تُرَدُّون بعد مماتكم للحساب والجزاء.", "isBasmala": false, "translation_en": "And He is God. There is no god but He. To Him belongs all praise in this life, and in the next. And His is the decision, and to Him you will be returned.", "translation_id": "Dan Dialah Allah, tidak ada Tuhan (yang berhak disembah) melainkan Dia, bagi-Nya-lah segala puji di dunia dan di akhirat, dan bagi-Nya-lah segala penentuan dan hanya kepada-Nya-lah kamu dikembalikan.", "manzil": 5, "manzil_display": ""}], "394": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 71, "text": "قُلۡ أَرَءَیۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَیۡكُمُ ٱلَّیۡلَ سَرۡمَدًا إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ مَنۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِ یَأۡتِیكُم بِضِیَاۤءٍۚ أَفَلَا تَسۡمَعُونَ ۝٧١", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "قل -أيها الرسول-: أخبروني -أيها الناس- إن جعل الله عليكم الليل دائمًا إلى يوم القيامة، مَن إله غير الله يأتيكم بضياء تستضيئون به؟ أفلا تسمعون سماع فهم وقَبول؟", "isBasmala": false, "translation_en": "Say, \"Have you considered? Had God made the night perpetual over you until the Day of Resurrection, which god other than God will bring you illumination? Do you not hear?\"", "translation_id": "Katakanlah: \"Terangkanlah kepadaku, jika Allah menjadikan untukmu malam itu terus menerus sampai hari kiamat, siapakah Tuhan selain Allah yang akan mendatangkan sinar terang kepadamu? Maka apakah kamu tidak mendengar?\"", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 72, "text": "قُلۡ أَرَءَیۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَیۡكُمُ ٱلنَّهَارَ سَرۡمَدًا إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ مَنۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِ یَأۡتِیكُم بِلَیۡلࣲ تَسۡكُنُونَ فِیهِۚ أَفَلَا تُبۡصِرُونَ ۝٧٢", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "قل لهم: أخبروني إن جعل الله عليكم النهار دائمًا إلى يوم القيامة، مَن إله غير الله يأتيكم بليل تستقرون وتهدؤون فيه؟ أفلا ترون بأبصاركم اختلاف الليل والنهار؟", "isBasmala": false, "translation_en": "Say, \"Have you considered? Had God made the day perpetual over you until the Day of Resurrection, which god other than God will bring you night to rest in? Do you not see?\"", "translation_id": "Katakanlah: \"Terangkanlah kepadaku, jika Allah menjadikan untukmu siang itu terus menerus sampai hari kiamat, siapakah Tuhan selain Allah yang akan mendatangkan malam kepadamu yang kamu beristirahat padanya? Maka apakah kamu tidak memperhatikan?\"", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 73, "text": "وَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّیۡلَ وَٱلنَّهَارَ لِتَسۡكُنُوا۟ فِیهِ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ۝٧٣", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "ومن رحمته بكم -أيها الناس- أن جعل لكم الليل والنهار فخالف بينهما، فجعل هذا الليل ظلامًا؛ لتستقروا فيه وترتاح أبدانكم، وجعل لكم النهار ضياءً؛ لتطلبوا فيه معايشكم، ولتشكروا له على إنعامه عليكم بذلك.", "isBasmala": false, "translation_en": "It is out of His mercy that He made for you the night and the day, that you may rest in it, and seek some of His bounty; and that you may give thanks.", "translation_id": "Dan karena rahmat-Nya, Dia jadikan untukmu malam dan siang, supaya kamu beristirahat pada malam itu dan supaya kamu mencari sebahagian dari karunia-Nya (pada siang hari) dan agar kamu bersyukur kepada-Nya.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 74, "text": "وَیَوۡمَ یُنَادِیهِمۡ فَیَقُولُ أَیۡنَ شُرَكَاۤءِیَ ٱلَّذِینَ كُنتُمۡ تَزۡعُمُونَ ۝٧٤", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "ويوم ينادي الله هؤلاء المشركين، فيقول لهم: أين شركائي الذين كنتم تزعمون في الدنيا أنهم شركائي؟", "isBasmala": false, "translation_en": "On the Day when He will call to them, and say, \"Where are My associates whom you used to claim?\"", "translation_id": "Dan (ingatlah) hari (di waktu) Allah menyeru mereka, seraya berkata: \"Di manakah sekutu-sekutu-Ku yang dahulu kamu katakan?\"", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 75, "text": "وَنَزَعۡنَا مِن كُلِّ أُمَّةࣲ شَهِیدࣰا فَقُلۡنَا هَاتُوا۟ بُرۡهَـٰنَكُمۡ فَعَلِمُوۤا۟ أَنَّ ٱلۡحَقَّ لِلَّهِ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ ۝٧٥", "juz": 20, "hizb": "(* ح 40*)", "tafsir": "ونزعنا من كل أمة من الأمم المكذبة شهيدا -وهو نبيُّهم-، يشهد على ما جرى في الدنيا من شركهم وتكذيبهم لرسلهم، فقلنا لتلك الأمم التي كذبت رسلها وما جاءت به من عند الله: هاتوا حجتكم على ما أشركتم مع الله، فعلموا حينئذ أن الحجة البالغة لله عليهم، وأن الحق لله، وذهب عنهم ما كانوا يفترون على ربهم، فلم ينفعهم ذلك، بل ضرَّهم وأوردهم نار جهنم.", "isBasmala": false, "translation_en": "And We will draw out from every community a witness, and say, \"Produce your evidence.\" Then they will realize that the truth is God's, and those they used to invent have forsaken them.", "translation_id": "Dan Kami datangkan dari tiap-tiap umat seorang saksi, lalu Kami berkata \"Tunjukkanlah bukti kebenaranmu\", maka tahulah mereka bahwasanya yang hak itu kepunyaan Allah dan lenyaplah dari mereka apa yang dahulunya mereka ada-adakan.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 76, "text": "۞ إِنَّ قَـٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَیۡهِمۡۖ وَءَاتَیۡنَـٰهُ مِنَ ٱلۡكُنُوزِ مَاۤ إِنَّ مَفَاتِحَهُۥ لَتَنُوۤأُ بِٱلۡعُصۡبَةِ أُو۟لِی ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡفَرِحِینَ ۝٧٦", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "إن قارون كان من قوم موسى -عليه الصلاة والسلام- فتجاوز حدَّه في الكِبْر والتجبر عليهم، وآتينا قارون من كنوز الأموال شيئًا عظيمًا، حتى إنَّ مفاتحه لَيثقل حملها على العدد الكثير من الأقوياء، إذ قال له قومه: لا تبطر فرحًا بما أنت فيه من المال، إن الله لا يحب مِن خلقه البَطِرين الذين لا يشكرون لله تعالى ما أعطاهم.", "isBasmala": false, "translation_en": "Quaroon belonged to the clan of Moses, but he oppressed them. We had given him treasures, the keys of which would weigh down a group of strong men. His people said to him, \"Do not exult; God does not love the exultant.", "translation_id": "Sesungguhnya Karun adalah termasuk kaum Musa, maka ia berlaku aniaya terhadap mereka, dan Kami telah menganugerahkan kepadanya perbendaharaan harta yang kunci-kuncinya sungguh berat dipikul oleh sejumlah orang yang kuat-kuat. (Ingatlah) ketika kaumnya berkata kepadanya: \"Janganlah kamu terlalu bangga; sesungguhnya Allah tidak menyukai orang-orang yang terlalu membanggakan diri\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 77, "text": "وَٱبۡتَغِ فِیمَاۤ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡـَٔاخِرَةَۖ وَلَا تَنسَ نَصِیبَكَ مِنَ ٱلدُّنۡیَاۖ وَأَحۡسِن كَمَاۤ أَحۡسَنَ ٱللَّهُ إِلَیۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِی ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡمُفۡسِدِینَ ۝٧٧", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "والتمس فيما أتاك الله من الأموال ثواب الدار الآخرة، بالعمل فيها بطاعة الله في الدنيا، ولا تترك حظك من الدنيا، بأن تتمتع فيها بالحلال دون إسراف، وأحسن إلى الناس بالصدقة، كما أحسن الله إليك بهذه الأموال الكثيرة، ولا تلتمس ما حرَّم الله عليك من البغي على قومك، إن الله لا يحب المفسدين.", "isBasmala": false, "translation_en": "But seek, with what God has given you, the Home of the Hereafter, and do not neglect your share of this world. And be charitable, as God has been charitable to you. And do not seek corruption in the land. God does not like the seekers of corruption.\"", "translation_id": "Dan carilah pada apa yang telah dianugerahkan Allah kepadamu (kebahagiaan) negeri akhirat, dan janganlah kamu melupakan bahagianmu dari (kenikmatan) duniawi dan berbuat baiklah (kepada orang lain) sebagaimana Allah telah berbuat baik, kepadamu, dan janganlah kamu berbuat kerusakan di (muka) bumi. Sesungguhnya Allah tidak menyukai orang-orang yang berbuat kerusakan.", "manzil": 5, "manzil_display": ""}], "395": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 78, "text": "قَالَ إِنَّمَاۤ أُوتِیتُهُۥ عَلَىٰ عِلۡمٍ عِندِیۤۚ أَوَ لَمۡ یَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةࣰ وَأَكۡثَرُ جَمۡعࣰاۚ وَلَا یُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ ۝٧٨", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "قال قارون لقومه الذين وعظوه: إنما أُعطيتُ هذه الكنوز بما عندي من العلم والقدرة، أولم يعلم قارون أن الله قد أهلك مِن قبله من الأمم مَن هو أشد منه بطشًا، وأكثر جمعًا للأموال؟ ولا يُسأل عن ذنوبهم المجرمون؛ لعلم الله تعالى بها، إنما يُسْألون سؤال توبيخ وتقرير، ويعاقبهم الله على ما علمه منهم.", "isBasmala": false, "translation_en": "He said, \"I was given all this on account of knowledge I possess.\" Did he not know that God destroyed many generations before him, who were stronger than he, and possessed greater riches? But the guilty will not be asked about their sins.", "translation_id": "Karun berkata: \"Sesungguhnya aku hanya diberi harta itu, karena ilmu yang ada padaku\". Dan apakah ia tidak mengetahui, bahwasanya Allah sungguh telah membinasakan umat-umat sebelumnya yang lebih kuat daripadanya, dan lebih banyak mengumpulkan harta? Dan tidaklah perlu ditanya kepada orang-orang yang berdosa itu, tentang dosa-dosa mereka.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 79, "text": "فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِی زِینَتِهِۦۖ قَالَ ٱلَّذِینَ یُرِیدُونَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا یَـٰلَیۡتَ لَنَا مِثۡلَ مَاۤ أُوتِیَ قَـٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِیمࣲ ۝٧٩", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "فخرج قارون على قومه في زينته، مريدًا بذلك إظهار عظمته وكثرة أمواله، وحين رآه الذين يريدون زينة الحياة الدنيا قالوا: يا ليت لنا مثل ما أُعطي قارون من المال والزينة والجاه، إن قارون لذو نصيب عظيم من الدنيا.", "isBasmala": false, "translation_en": "And he went out before his people in his splendor. Those who desired the worldly life said, \"If only we possessed the likes of what Quaroon was given. He is indeed very fortunate.\"", "translation_id": "Maka keluarlah Karun kepada kaumnya dalam kemegahannya. Berkatalah orang-orang yang menghendaki kehidupan dunia: \"Moga-moga kiranya kita mempunyai seperti apa yang telah diberikan kepada Karun; sesungguhnya ia benar-benar mempunyai keberuntungan yang besar\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 80, "text": "وَقَالَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ وَیۡلَكُمۡ ثَوَابُ ٱللَّهِ خَیۡرࣱ لِّمَنۡ ءَامَنَ وَعَمِلَ صَـٰلِحࣰاۚ وَلَا یُلَقَّىٰهَاۤ إِلَّا ٱلصَّـٰبِرُونَ ۝٨٠", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "وقال الذين أوتوا العلم بالله وشرعه وعرفوا حقائق الأمور للذين قالوا: يا ليت لنا مثل ما أوتي قارون: ويلكم اتقوا الله وأطيعوه، ثوابُ الله لمن آمن به وبرسله، وعمل الأعمال الصالحة، خيرٌ مما أوتي قارون، ولا يَتَقَبَّل هذه النصيحة ويوفَّق إليها ويعمل بها إلا مَن يجاهد نفسه، ويصبر على طاعة ربه، ويجتنب معاصيه.", "isBasmala": false, "translation_en": "But those who were given knowledge said, \"Woe to you! The reward of God is better for those who believe and do righteous deeds.\" Yet none attains it except the steadfast.", "translation_id": "Berkatalah orang-orang yang dianugerahi ilmu: \"Kecelakaan yang besarlah bagimu, pahala Allah adalah lebih baik bagi orang-orang yang beriman dan beramal saleh, dan tidak diperoleh pahala itu, kecuali oleh orang-orang yang sabar\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 81, "text": "فَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةࣲ یَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِینَ ۝٨١", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "فخسفنا بقارون وبداره الأرض، فما كان له من جند ينصرونه من دون الله، وما كان ممتنعًا من الله إذا أحلَّ به نقمته.", "isBasmala": false, "translation_en": "So We caused the earth to cave in on him and his mansion. He had no company to save him from God, and he could not defend himself.", "translation_id": "Maka Kami benamkanlah Karun beserta rumahnya ke dalam bumi. Maka tidak ada baginya suatu golonganpun yang menolongnya terhadap azab Allah. Dan tiadalah ia termasuk orang-orang (yang dapat) membela (dirinya).", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 82, "text": "وَأَصۡبَحَ ٱلَّذِینَ تَمَنَّوۡا۟ مَكَانَهُۥ بِٱلۡأَمۡسِ یَقُولُونَ وَیۡكَأَنَّ ٱللَّهَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ مِنۡ عِبَادِهِۦ وَیَقۡدِرُۖ لَوۡلَاۤ أَن مَّنَّ ٱللَّهُ عَلَیۡنَا لَخَسَفَ بِنَاۖ وَیۡكَأَنَّهُۥ لَا یُفۡلِحُ ٱلۡكَـٰفِرُونَ ۝٨٢", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "وصار الذين تمنوا حاله بالأمس يقولون متوجعين ومعتبرين وخائفين من وقوع العذاب بهم: إن الله يوسِّع الرزق لمن يشاء من عباده، ويضيِّق على مَن يشاء منهم، لولا أن الله منَّ علينا فلم يعاقبنا على ما قلنا لَخسف بنا كما فعل بقارون، ألم تعلم أنه لا يفلح الكافرون، لا في الدنيا ولا في الآخرة؟", "isBasmala": false, "translation_en": "Those who had wished they were in his position the day before were saying, \"Indeed, it is God who spreads the bounty to whomever He wills of His servants, and restricts it. Had God not been gracious to us, He would have caved in on us. No wonder the ungrateful never prosper.\"", "translation_id": "Dan jadilah orang-orang yang kemarin mencita-citakan kedudukan Karun itu, berkata: \"Aduhai, benarlah Allah melapangkan rezeki bagi siapa yang Dia kehendaki dari hamba-hambanya dan menyempitkannya; kalau Allah tidak melimpahkan karunia-Nya atas kita benar-benar Dia telah membenamkan kita (pula). Aduhai benarlah, tidak beruntung orang-orang yang mengingkari (nikmat Allah)\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 83, "text": "تِلۡكَ ٱلدَّارُ ٱلۡـَٔاخِرَةُ نَجۡعَلُهَا لِلَّذِینَ لَا یُرِیدُونَ عُلُوࣰّا فِی ٱلۡأَرۡضِ وَلَا فَسَادࣰاۚ وَٱلۡعَـٰقِبَةُ لِلۡمُتَّقِینَ ۝٨٣", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "تلك الدار الآخرة نجعل نعيمها للذين لا يريدون تكبرًا عن الحق في الأرض ولا فسادًا فيها. والعاقبة المحمودة -وهي الجنة- لمن اتقى عذاب الله وعمل الطاعات، وترك المحرمات.", "isBasmala": false, "translation_en": "That Home of the Hereafter-We assign it for those who seek no superiority on earth, nor corruption. And the outcome is for the cautious.", "translation_id": "Negeri akhirat itu, Kami jadikan untuk orang-orang yang tidak ingin menyombongkan diri dan berbuat kerusakan di (muka) bumi. Dan kesudahan (yang baik) itu adalah bagi orang-orang yang bertakwa.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 84, "text": "مَن جَاۤءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَیۡرࣱ مِّنۡهَاۖ وَمَن جَاۤءَ بِٱلسَّیِّئَةِ فَلَا یُجۡزَى ٱلَّذِینَ عَمِلُوا۟ ٱلسَّیِّـَٔاتِ إِلَّا مَا كَانُوا۟ یَعۡمَلُونَ ۝٨٤", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "من جاء يوم القيامة بإخلاص التوحيد لله وبالأعمال الصالحة وَفْق ما شرع الله، فله أجر عظيم خير من ذلك، وذلك الخير هو الجنة والنعيم الدائم، ومن جاء بالأعمال السيئة، فلا يُجْزى الذين عملوا السيئات على أعمالهم إلا بما كانوا يعملون.", "isBasmala": false, "translation_en": "Whoever brings a virtue will receive better than it. But whoever brings evil-the evildoers will be rewarded only according to what they used to do.", "translation_id": "Barangsiapa yang datang dengan (membawa) kebaikan, maka baginya (pahala) yang lebih baik daripada kebaikannya itu; dan barangsiapa yang datang dengan (membawa) kejahatan, maka tidaklah diberi pembalasan kepada orang-orang yang telah mengerjakan kejahatan itu, melainkan (seimbang) dengan apa yang dahulu mereka kerjakan.", "manzil": 5, "manzil_display": ""}], "396": [{"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 85, "text": "إِنَّ ٱلَّذِی فَرَضَ عَلَیۡكَ ٱلۡقُرۡءَانَ لَرَاۤدُّكَ إِلَىٰ مَعَادࣲۚ قُل رَّبِّیۤ أَعۡلَمُ مَن جَاۤءَ بِٱلۡهُدَىٰ وَمَنۡ هُوَ فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٨٥", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "إن الذي أنزل عليك -أيها الرسول- القرآن، وفرض عليك تبليغه والتمسُّك به، لمرجعك إلى الموضع الذي خرجت منه، وهو \"مكة\"، قل -أيها الرسول- لهؤلاء المشركين: ربي أعلم مَن جاء بالهدى، ومن هو في ذهابٍ واضحٍ عن الحق.", "isBasmala": false, "translation_en": "He Who ordained the Quran for you will return you Home. Say, \"My Lord knows best who comes with guidance, and who is in manifest error.\"", "translation_id": "Sesungguhnya yang mewajibkan atasmu (melaksanakan hukum-hukum) Al Quran, benar-benar akan mengembalikan kamu ke tempat kembali. Katakanlah: \"Tuhanku mengetahui orang yang membawa petunjuk dan orang yang dalam kesesatan yang nyata\".", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 86, "text": "وَمَا كُنتَ تَرۡجُوۤا۟ أَن یُلۡقَىٰۤ إِلَیۡكَ ٱلۡكِتَـٰبُ إِلَّا رَحۡمَةࣰ مِّن رَّبِّكَۖ فَلَا تَكُونَنَّ ظَهِیرࣰا لِّلۡكَـٰفِرِینَ ۝٨٦", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "وما كنت -أيها الرسول- تؤمِّل نزول القرآن عليك، لكن الله سبحانه وتعالى رحمك فأنزله عليك، فاشكر لله تعالى على نِعَمه، ولا تكوننَّ عونًا لأهل الشرك والضلال.", "isBasmala": false, "translation_en": "You did not expect the Scripture to be transmitted to you, except as mercy from your Lord. Therefore, do not be a supporter of the disbelievers.", "translation_id": "Dan kamu tidak pernah mengharap agar Al Quran diturunkan kepadamu, tetapi ia (diturunkan) karena suatu rahmat yang besar dari Tuhanmu, sebab itu janganlah sekali-kali kamu menjadi penolong bagi orang-orang kafir.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 87, "text": "وَلَا یَصُدُّنَّكَ عَنۡ ءَایَـٰتِ ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَیۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِینَ ۝٨٧", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "ولا يصرفَنَّك هؤلاء المشركون عن تبليغ آيات ربك وحججه، بعد أن أنزلها إليك، وبلِّغ رسالة ربك، ولا تكونن من المشركين في شيء.", "isBasmala": false, "translation_en": "And do not let them divert you from God's revelations after they have been revealed to you. And pray to your Lord, and never be of the polytheists.", "translation_id": "Dan janganlah sekali-kali mereka dapat menghalangimu dari (menyampaikan) ayat-ayat Allah, sesudah ayat-ayat itu diturunkan kepadamu, dan serulah mereka kepada (jalan) Tuhanmu, dan janganlah sekali-sekali kamu termasuk orang-orang yang mempersekutukan Tuhan.", "manzil": 5, "manzil_display": ""}, {"sura": 28, "sura_name": "القصص", "revelation": "Makkiyah", "aya": 88, "text": "وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَۘ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ كُلُّ شَیۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ لَهُ ٱلۡحُكۡمُ وَإِلَیۡهِ تُرۡجَعُونَ ۝٨٨", "juz": 20, "hizb": "(*¼ ح 40*)", "tafsir": "ولا تعبد مع الله معبودًا أخر؛ فلا معبود بحق إلا الله، كل شيء هالك وفانٍ إلا وجهه، له الحكم، وإليه ترجعون من بعد موتكم للحساب والجزاء. وفي هذه الآية إثبات صفة الوجه لله تعالى كما يليق بكماله وعظمة جلاله.", "isBasmala": false, "translation_en": "And do not invoke with God any other god. There is no god but He. All things perish, except His presence. His is the judgment, and to Him you will be returned.", "translation_id": "Janganlah kamu sembah di samping (menyembah) Allah, tuhan apapun yang lain. Tidak ada Tuhan (yang berhak disembah) melainkan Dia. Tiap-tiap sesuatu pasti binasa, kecuali Allah. Bagi-Nya-lah segala penentuan, dan hanya kepada-Nya-lah kamu dikembalikan.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 21, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 1, "text": "۞ الۤمۤ ۝١", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "الم: سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Meem.", "translation_id": "Alif laam miim", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 2, "text": "أَحَسِبَ ٱلنَّاسُ أَن یُتۡرَكُوۤا۟ أَن یَقُولُوۤا۟ ءَامَنَّا وَهُمۡ لَا یُفۡتَنُونَ ۝٢", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "أظَنَّ الناس إذ قالوا: آمنا، أن الله يتركهم بلا ابتلاء ولا اختبار؟", "isBasmala": false, "translation_en": "Have the people supposed that they will be left alone to say, \"We believe,\" without being put to the test?", "translation_id": "Apakah manusia itu mengira bahwa mereka dibiarkan (saja) mengatakan: \"Kami telah beriman\", sedang mereka tidak diuji lagi?", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 3, "text": "وَلَقَدۡ فَتَنَّا ٱلَّذِینَ مِن قَبۡلِهِمۡۖ فَلَیَعۡلَمَنَّ ٱللَّهُ ٱلَّذِینَ صَدَقُوا۟ وَلَیَعۡلَمَنَّ ٱلۡكَـٰذِبِینَ ۝٣", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "ولقد فتنَّا الذين من قبلهم من الأمم واختبرناهم، ممن أرسلنا إليهم رسلنا، فليعلمنَّ الله علمًا ظاهرًا للخلق صدق الصادقين في إيمانهم، وكذب الكاذبين؛ ليميز كلَّ فريق من الآخر.", "isBasmala": false, "translation_en": "We have tested those before them. God will surely know the truthful, and He will surely know the liars.", "translation_id": "Dan sesungguhnya kami telah menguji orang-orang yang sebelum mereka, maka sesungguhnya Allah mengetahui orang-orang yang benar dan sesungguhnya Dia mengetahui orang-orang yang dusta.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 4, "text": "أَمۡ حَسِبَ ٱلَّذِینَ یَعۡمَلُونَ ٱلسَّیِّـَٔاتِ أَن یَسۡبِقُونَاۚ سَاۤءَ مَا یَحۡكُمُونَ ۝٤", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "بل أظنَّ الذين يعملون المعاصي مِن شرك وغيره أن يعجزونا، فيفوتونا بأنفسهم فلا نقدر عليهم؟ بئس حكمهم الذي يحكمون به.", "isBasmala": false, "translation_en": "Or do those who commit sins think they can fool Us? Terrible is their opinion!", "translation_id": "Ataukah orang-orang yang mengerjakan kejahatan itu mengira bahwa mereka akan luput (dari azab) Kami? Amatlah buruk apa yang mereka tetapkan itu.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 5, "text": "مَن كَانَ یَرۡجُوا۟ لِقَاۤءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَـَٔاتࣲۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٥", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "من كان يرجو لقاء الله، ويطمع في ثوابه، فإن أجل الله الذي أجَّله لبعث خلقه للجزاء والعقاب لآتٍ قريبًا، وهو السميع للأقوال، العليم بالأفعال.", "isBasmala": false, "translation_en": "Whoever looks forward to the meeting with God-the appointed time of God is coming. He is the All-Hearing, the All-Knowing.", "translation_id": "Barangsiapa yang mengharap pertemuan dengan Allah, maka sesungguhnya waktu (yang dijanjikan) Allah itu, pasti datang. Dan Dialah Yang Maha mendengar lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 6, "text": "وَمَن جَـٰهَدَ فَإِنَّمَا یُجَـٰهِدُ لِنَفۡسِهِۦۤۚ إِنَّ ٱللَّهَ لَغَنِیٌّ عَنِ ٱلۡعَـٰلَمِینَ ۝٦", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "ومن جاهد في سبيل إعلاء كلمة الله تعالى، وجاهد نفسه بحملها على الطاعة، فإنما يجاهد لنفسه؛ لأنه يفعل ذلك ابتغاء الثواب على جهاده. إن الله لغني عن أعمال جميع خلقه، له الملك والخلق والأمر.", "isBasmala": false, "translation_en": "Whoever strives, strives only for himself. God is Independent of the beings.", "translation_id": "Dan barangsiapa yang berjihad, maka sesungguhnya jihadnya itu adalah untuk dirinya sendiri. Sesungguhnya Allah benar-benar Maha Kaya (tidak memerlukan sesuatu) dari semesta alam.", "manzil": 5, "manzil_display": ""}], "397": [{"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 7, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَیِّـَٔاتِهِمۡ وَلَنَجۡزِیَنَّهُمۡ أَحۡسَنَ ٱلَّذِی كَانُوا۟ یَعۡمَلُونَ ۝٧", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "والذين صدَّقوا الله ورسوله، وعملوا الصالحات لنمحونَّ عنهم خطيئاتهم، ولنثيبنَّهم على أعمالهم الصالحة أحسن ما كانوا يعملون.", "isBasmala": false, "translation_en": "Those who believe and do righteous deeds-We will remit their sins, and We will reward them according to the best of what they used to do.", "translation_id": "Dan orang-orang yang beriman dan beramal saleh, benar-benar akan Kami hapuskan dari mereka dosa-dosa mereka dan benar-benar akan Kami beri mereka balasan yang lebih baik dari apa yang mereka kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 8, "text": "وَوَصَّیۡنَا ٱلۡإِنسَـٰنَ بِوَ ٰلِدَیۡهِ حُسۡنࣰاۖ وَإِن جَـٰهَدَاكَ لِتُشۡرِكَ بِی مَا لَیۡسَ لَكَ بِهِۦ عِلۡمࣱ فَلَا تُطِعۡهُمَاۤۚ إِلَیَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٨", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "ووصينا الإنسان بوالديه أن يبرهما، ويحسن إليهما بالقول والعمل، وإن جاهداك -أيها الإنسان- على أن تشرك معي في عبادتي، فلا تمتثل أمرهما. ويلحق بطلب الإشراك بالله، سائر المعاصي، فلا طاعة لمخلوق كائنًا من كان في معصية الله سبحانه، كما ثبت ذلك عن رسول الله صلى الله عليه وسلم. إليَّ مصيركم يوم القيامة، فأخبركم بما كنتم تعملون في الدنيا من صالح الأعمال وسيئها، وأجازيكم عليها.", "isBasmala": false, "translation_en": "We have advised the human being to be good to his parents. But if they urge you to associate with Me something you have no knowledge of, do not obey them. To Me is your return; and I will inform you of what you used to do.", "translation_id": "Dan Kami wajibkan manusia (berbuat) kebaikan kepada dua orang ibu-bapaknya. Dan jika keduanya memaksamu untuk mempersekutukan Aku dengan sesuatu yang tidak ada pengetahuanmu tentang itu, maka janganlah kamu mengikuti keduanya. Hanya kepada-Ku-lah kembalimu, lalu Aku kabarkan kepadamu apa yang telah kamu kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 9, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُدۡخِلَنَّهُمۡ فِی ٱلصَّـٰلِحِینَ ۝٩", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "والذين صدَّقوا الله ورسوله وعملوا الصالحات من الأعمال، لندخلنهم الجنة في جملة عباد الله الصالحين.", "isBasmala": false, "translation_en": "Those who believe and do good works-We will admit them into the company of the righteous.", "translation_id": "Dan orang-orang yang beriman dan mengerjakan amal saleh benar-benar akan Kami masukkan mereka ke dalam (golongan) orang-orang yang saleh.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 10, "text": "وَمِنَ ٱلنَّاسِ مَن یَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَاۤ أُوذِیَ فِی ٱللَّهِ جَعَلَ فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ وَلَىِٕن جَاۤءَ نَصۡرࣱ مِّن رَّبِّكَ لَیَقُولُنَّ إِنَّا كُنَّا مَعَكُمۡۚ أَوَ لَیۡسَ ٱللَّهُ بِأَعۡلَمَ بِمَا فِی صُدُورِ ٱلۡعَـٰلَمِینَ ۝١٠", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "ومن الناس من يقول: آمنا بالله، فإذا آذاه المشركون جزع من عذابهم وأذاهم، كما يجزع من عذاب الله ولا يصبر على الأذيَّة منه، فارتدَّ عن إيمانه، ولئن جاء نصر من ربك -أيها الرسول- لأهل الإيمان به ليقولَنَّ هؤلاء المرتدون عن إيمانهم: إنَّا كنا معكم -أيها المؤمنون- ننصركم على أعدائكم، أوليس الله بأعلم من كل أحد بما في صدور جميع خلقه؟", "isBasmala": false, "translation_en": "Among the people is he who says, \"We have believed in God.\" Yet when he is harmed on God's account, he equates the people's persecution with God's retribution. And if help comes from your Lord, he says, \"We were actually with you.\" Is not God aware of what is inside the hearts of the people?", "translation_id": "Dan di antara manusia ada orang yang berkata: \"Kami beriman kepada Allah\", maka apabila ia disakiti (karena ia beriman) kepada Allah, ia menganggap fitnah manusia itu sebagai azab Allah. Dan sungguh jika datang pertolongan dari Tuhanmu, mereka pasti akan berkata: \"Sesungguhnya kami adalah besertamu\". Bukankah Allah lebih mengetahui apa yang ada dalam dada semua manusia?", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 11, "text": "وَلَیَعۡلَمَنَّ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَلَیَعۡلَمَنَّ ٱلۡمُنَـٰفِقِینَ ۝١١", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "وليعلمنَّ الله علمًا ظاهرًا للخلق الذين صدَّقوا الله ورسوله وعملوا بشرعه، وليعلمنَّ المنافقين؛ ليميز كل فريق من الآخر.", "isBasmala": false, "translation_en": "God certainly knows those who believe, and He certainly knows the hypocrites.", "translation_id": "Dan sesungguhnya Allah benar-benar mengetahui orang-orang yang beriman: dan sesungguhnya Dia mengetahui orang-orang yang munafik.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 12, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِلَّذِینَ ءَامَنُوا۟ ٱتَّبِعُوا۟ سَبِیلَنَا وَلۡنَحۡمِلۡ خَطَـٰیَـٰكُمۡ وَمَا هُم بِحَـٰمِلِینَ مِنۡ خَطَـٰیَـٰهُم مِّن شَیۡءٍۖ إِنَّهُمۡ لَكَـٰذِبُونَ ۝١٢", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "وقال الذين جحدوا وحدانية الله من قريش، ولم يؤمنوا بوعيد الله ووعده، للذين صدَّقوا الله منهم وعملوا بشرعه: اتركوا دين محمد، واتبعوا ديننا، فإنا نتحمل آثام خطاياكم، وليسوا بحاملين من آثامهم من شيء، إنهم لكاذبون فيما قالوا.", "isBasmala": false, "translation_en": "Those who disbelieve say to those who believe, \"Follow our way, and we will carry your sins.\" In no way can they carry any of their sins. They are liars.", "translation_id": "Dan berkatalah orang-orang kafir kepada orang-orang yang beriman: \"Ikutilah jalan kami, dan nanti kami akan memikul dosa-dosamu\", dan mereka (sendiri) sedikitpun tidak (sanggup), memikul dosa-dosa mereka. Sesungguhnya mereka adalah benar-benar orang pendusta.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 13, "text": "وَلَیَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالࣰا مَّعَ أَثۡقَالِهِمۡۖ وَلَیُسۡـَٔلُنَّ یَوۡمَ ٱلۡقِیَـٰمَةِ عَمَّا كَانُوا۟ یَفۡتَرُونَ ۝١٣", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "وليحملَنَّ هؤلاء المشركون أوزار أنفسهم وآثامها، وأوزار مَن أضلوا وصدُّوا عن سبيل الله مع أوزارهم، دون أن ينقص من أوزار تابعيهم شيء، وليُسألُنَّ يوم القيامة عما كانوا يختلقونه من الأكاذيب.", "isBasmala": false, "translation_en": "They will carry their own loads, and other loads with their own. And they will be questioned on the Day of Resurrection concerning what they used to fabricate.", "translation_id": "Dan sesungguhnya mereka akan memikul beban (dosa) mereka, dan beban-beban (dosa yang lain) di samping beban-beban mereka sendiri, dan sesungguhnya mereka akan ditanya pada hari kiamat tentang apa yang selalu mereka ada-adakan.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 14, "text": "وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِیهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِینَ عَامࣰا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَـٰلِمُونَ ۝١٤", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "ولقد أرسلنا نوحًا إلى قومه فمكث فيهم ألف سنة إلا خمسين عامًا، يدعوهم إلى التوحيد وينهاهم عن الشرك، فلم يستجيبوا له، فأهلكهم الله بالطوفان، وهم ظالمون لأنفسهم بكفرهم وطغيانهم.", "isBasmala": false, "translation_en": "We sent Noah to his people, and He stayed among them for a thousand years minus fifty years. Then the Deluge swept them; for they were wrongdoers.", "translation_id": "Dan sesungguhnya Kami telah mengutus Nuh kepada kaumnya, maka ia tinggal di antara mereka seribu tahun kurang lima puluh tahun. Maka mereka ditimpa banjir besar, dan mereka adalah orang-orang yang zalim.", "manzil": 5, "manzil_display": ""}], "398": [{"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 15, "text": "فَأَنجَیۡنَـٰهُ وَأَصۡحَـٰبَ ٱلسَّفِینَةِ وَجَعَلۡنَـٰهَاۤ ءَایَةࣰ لِّلۡعَـٰلَمِینَ ۝١٥", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "فأنجينا نوحًا ومَن تبعه ممن كان معه في السفينة، وجعلنا ذلك عبرة وعظة للعالمين.", "isBasmala": false, "translation_en": "But We saved him, together with the company of the Ark, and We made it a sign for all peoples.", "translation_id": "Maka Kami selamatkan Nuh dan penumpang-penumpang bahtera itu dan Kami jadikan peristiwa itu pelajaran bagi semua umat manusia.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 16, "text": "وَإِبۡرَ ٰهِیمَ إِذۡ قَالَ لِقَوۡمِهِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُۖ ذَ ٰلِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ۝١٦", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "واذكر -أيها الرسول- إبراهيم عليه السلام حين دعا قومه: أن أخلصوا العبادة لله وحده، واتقوا سخطه بأداء فرائضه واجتناب معاصيه، ذلكم خير لكم، إن كنتم تعلمون ما هو خير لكم مما هو شر لكم.", "isBasmala": false, "translation_en": "And Abraham, when he said to his people, \"Worship God, and fear Him. That is better for you, if you only knew.", "translation_id": "Dan (ingatlah) Ibrahim, ketika ia berkata kepada kaumnya: \"Sembahlah olehmu Allah dan bertakwalah kepada-Nya. Yang demikian itu adalah lebih baik bagimu, jika kamu mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 17, "text": "إِنَّمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ أَوۡثَـٰنࣰا وَتَخۡلُقُونَ إِفۡكًاۚ إِنَّ ٱلَّذِینَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ لَا یَمۡلِكُونَ لَكُمۡ رِزۡقࣰا فَٱبۡتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزۡقَ وَٱعۡبُدُوهُ وَٱشۡكُرُوا۟ لَهُۥۤۖ إِلَیۡهِ تُرۡجَعُونَ ۝١٧", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "ما تعبدون -أيها القوم- مِن دون الله إلا أصنامًا، وتفترون كذبًا بتسميتكم إياها آلهة، إنَّ أوثانكم التي تعبدونها من دون الله لا تقدر أن ترزقكم شيئًا، فالتمسوا عند الله الرزق لا من عند أوثانكم، وأخلصوا له العبادة والشكر على رزقه إياكم، إلى الله تُردُّون من بعد مماتكم، فيجازيكم على ما عملتم.", "isBasmala": false, "translation_en": "You worship idols besides God, and you fabricate falsehoods. Those you worship, instead of God, cannot provide you with livelihood. So seek your livelihood from God, and worship Him, and thank Him. To Him you will be returned.\"", "translation_id": "Sesungguhnya apa yang kamu sembah selain Allah itu adalah berhala, dan kamu membuat dusta. Sesungguhnya yang kamu sembah selain Allah itu tidak mampu memberikan rezeki kepadamu; maka mintalah rezeki itu di sisi Allah, dan sembahlah Dia dan bersyukurlah kepada-Nya. Hanya kepada-Nya-lah kamu akan dikembalikan.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 18, "text": "وَإِن تُكَذِّبُوا۟ فَقَدۡ كَذَّبَ أُمَمࣱ مِّن قَبۡلِكُمۡۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ ۝١٨", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "وإن تكذِّبوا - أيها الناس- رسولنا محمدًا صلى الله عليه وسلم فيما دعاكم إليه من عبادة الله وحده، فقد كذبت جماعات من قبلكم رسلها فيما دعتهم إليه من الحق، فحل بهم سخط الله، وما على الرَّسول محمد إلا أن يبلغكم عن الله رسالته البلاغ الواضح، وقد فَعَل.", "isBasmala": false, "translation_en": "If you disbelieve, communities before you have also disbelieved. The Messenger is only responsible for clear transmission.", "translation_id": "Dan jika kamu (orang kafir) mendustakan, maka umat yang sebelum kamu juga telah mendustakan. Dan kewajiban rasul itu, tidak lain hanyalah menyampaikan (agama Allah) dengan seterang-terangnya\".", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 19, "text": "أَوَ لَمۡ یَرَوۡا۟ كَیۡفَ یُبۡدِئُ ٱللَّهُ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥۤۚ إِنَّ ذَ ٰلِكَ عَلَى ٱللَّهِ یَسِیرࣱ ۝١٩", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "أولم يعلم هؤلاء كيف ينشئ الله الخلق من العدم، ثم يعيده من بعد فنائه، كما بدأه أول مرة خلقًا جديدًا، لا يتعذر عليه ذلك؟ إن ذلك على الله يسير، كما كان يسيرًا عليه إنشاؤه.", "isBasmala": false, "translation_en": "Have they not seen how God originates the creation, and then reproduces it? This is easy for God.", "translation_id": "Dan apakah mereka tidak memperhatikan bagaimana Allah menciptakan (manusia) dari permulaannya, kemudian mengulanginya (kembali). Sesungguhnya yang demikian itu adalah mudah bagi Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 20, "text": "قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ یُنشِئُ ٱلنَّشۡأَةَ ٱلۡـَٔاخِرَةَۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٢٠", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "قل -أيها الرسول- لمنكري البعث بعد الممات: سيروا في الأرض، فانظروا كيف أنشأ الله الخلق، ولم يتعذر عليه إنشاؤه مبتدَأً؟ فكذلك لا يتعذر عليه إعادة إنشائه النشأة الآخرة. إن الله على كل شيء قدير، لا يعجزه شيء أراده.", "isBasmala": false, "translation_en": "Say, \"Roam the earth, and observe how He originated the creation.\" Then God will bring about the next existence. God has power over all things.\"", "translation_id": "Katakanlah: \"Berjalanlah di (muka) bumi, maka perhatikanlah bagaimana Allah menciptakan (manusia) dari permulaannya, kemudian Allah menjadikannya sekali lagi. Sesungguhnya Allah Maha Kuasa atas segala sesuatu.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 21, "text": "یُعَذِّبُ مَن یَشَاۤءُ وَیَرۡحَمُ مَن یَشَاۤءُۖ وَإِلَیۡهِ تُقۡلَبُونَ ۝٢١", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "يعذب مَن يشاء مِن خلقه على ما أسلف مِن جرمه في أيام حياته، ويرحم مَن يشاء منهم ممن تاب وآمن وعمل صالحًا، وإليه ترجعون، فيجازيكم بما عملتم.", "isBasmala": false, "translation_en": "He punishes whom He wills, and He grants mercy to whom He wills, and to Him you will be restored.", "translation_id": "Allah mengazab siapa yang dikehendaki-Nya, dan memberi rahmat kepada siapa yang dikehendaki-Nya, dan hanya kepada-Nya-lah kamu akan dikembalikan.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 22, "text": "وَمَاۤ أَنتُم بِمُعۡجِزِینَ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَاۤءِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرࣲ ۝٢٢", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "وما أنتم -أيها الناس- بمعجزي الله في الأرض ولا في السماء إن عصيتموه، وما كان لكم من دون الله مِن وليٍّ يلي أموركم، ولا نصير ينصركم من الله إن أراد بكم سوءًا.", "isBasmala": false, "translation_en": "You cannot escape, on earth or in the heaven; and you have no protector and no savior besides God.", "translation_id": "Dan kamu sekali-kali tidak dapat melepaskan diri (dari azab Allah) di bumi dan tidak (pula) di langit dan sekali-kali tiadalah bagimu pelindung dan penolong selain Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 23, "text": "وَٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ ٱللَّهِ وَلِقَاۤىِٕهِۦۤ أُو۟لَـٰۤىِٕكَ یَىِٕسُوا۟ مِن رَّحۡمَتِی وَأُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابٌ أَلِیمࣱ ۝٢٣", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "والذين جحدوا حُجج الله وأنكروا أدلته، ولقاءه يوم القيامة، أولئك ليس لهم مطمع في رحمتي لَمَّا عاينوا ما أُعِدَّ لهم من العذاب، وأولئك لهم عذاب مؤلم موجع.", "isBasmala": false, "translation_en": "Those who disbelieved in God's signs and His encounter-these have despaired of My mercy. For them is a painful torment.", "translation_id": "Dan orang-orang yang kafir terhadap ayat-ayat Allah dan pertemuan dengan Dia, mereka putus asa dari rahmat-Ku, dan mereka itu mendapat azab yang pedih.", "manzil": 5, "manzil_display": ""}], "399": [{"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 24, "text": "فَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوا۟ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝٢٤", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "فلم يكن جواب قوم إبراهيم له إلا أن قال بعضهم لبعض: اقتلوه أو حرِّقوه بالنار، فألقوه فيها، فأنجاه الله منها، وجعلها عليه بردًا وسلامًا، إن في إنجائنا لإبراهيم من النار لأدلة وحججًا لقوم يصدِّقون الله ويعملون بشرعه.", "isBasmala": false, "translation_en": "But the only response from his people was their saying, \"Kill him, or burn him.\" But God saved him from the fire. Surely in that are signs for people who believe.", "translation_id": "Maka tidak adalah jawaban kaum Ibrahim, selain mengatakan: \"Bunuhlah atau bakarlah dia\", lalu Allah menyelamatkannya dari api. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda kebesaran Allah bagi orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 25, "text": "وَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَـٰنࣰا مَّوَدَّةَ بَیۡنِكُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ ثُمَّ یَوۡمَ ٱلۡقِیَـٰمَةِ یَكۡفُرُ بَعۡضُكُم بِبَعۡضࣲ وَیَلۡعَنُ بَعۡضُكُم بَعۡضࣰا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِینَ ۝٢٥", "juz": 20, "hizb": "(*½ ح 40*)", "tafsir": "وقال إبراهيم لقومه: يا قوم إنما عبدتم من دون الله آلهة باطلة، اتخذتموها مودة بينكم في الحياة الدنيا، تتحابون على عبادتها، وتتوادون على خدمتها، ثم يوم القيامة، يتبرأ بعضكم من بعض، ويلعن بعضكم بعضًا، ومصيركم جميعًا النار، وليس لكم ناصر يمنعكم من دخولها.", "isBasmala": false, "translation_en": "And he said, \"You have chosen idols instead of God, out of affection for one another in the worldly life. But then, on the Day of Resurrection, you will disown one another, and curse one another. Your destiny is Hell, and you will have no saviors.\"", "translation_id": "Dan berkata Ibrahim: \"Sesungguhnya berhala-berhala yang kamu sembah selain Allah adalah untuk menciptakan perasaan kasih sayang di antara kamu dalam kehidupan dunia ini kemudian di hari kiamat sebahagian kamu mengingkari sebahagian (yang lain) dan sebahagian kamu melaknati sebahagian (yang lain); dan tempat kembalimu ialah neraka, dan sekali-kali tak ada bagimu para penolongpun.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 26, "text": "۞ فَـَٔامَنَ لَهُۥ لُوطࣱۘ وَقَالَ إِنِّی مُهَاجِرٌ إِلَىٰ رَبِّیۤۖ إِنَّهُۥ هُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٢٦", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "فصدَّق لوطٌ إبراهيمَ وتبع ملته. وقال إبراهيم: إني تارك دار قومي إلى الأرض المباركة وهي \"الشام\"، إن الله هو العزيز الذي لا يُغَالَب، الحكيم في تدبيره.", "isBasmala": false, "translation_en": "Then Lot believed in him, and said, \"I am emigrating to my Lord. He is the Noble, the Wise.\"", "translation_id": "Maka Luth membenarkan (kenabian)nya. Dan berkatalah Ibrahim: \"Sesungguhnya aku akan berpindah ke (tempat yang diperintahkan) Tuhanku (kepadaku); sesungguhnya Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 27, "text": "وَوَهَبۡنَا لَهُۥۤ إِسۡحَـٰقَ وَیَعۡقُوبَ وَجَعَلۡنَا فِی ذُرِّیَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَـٰبَ وَءَاتَیۡنَـٰهُ أَجۡرَهُۥ فِی ٱلدُّنۡیَاۖ وَإِنَّهُۥ فِی ٱلۡـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِینَ ۝٢٧", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "ووهبنا له إسحاق ولدًا، ويعقوب من بعده وَلَدَ وَلَدٍ، وجعلنا في ذريته الأنبياء والكتب، وأعطيناه ثواب بلائه فينا، في الدنيا الذكر الحسن والولد الصالح، وإنه في الآخرة لمن الصالحين.", "isBasmala": false, "translation_en": "And We granted him Isaac and Jacob, and conferred on his descendants the Prophethood and the Book, and gave him his reward in this life; and in the Hereafter he will be among the upright.", "translation_id": "Dan Kami anugrahkan kepda Ibrahim, Ishak dan Ya'qub, dan Kami jadikan kenabian dan Al Kitab pada keturunannya, dan Kami berikan kepadanya balasannya di dunia; dan sesungguhnya dia di akhirat, benar-benar termasuk orang-orang yang saleh.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 28, "text": "وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦۤ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَـٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدࣲ مِّنَ ٱلۡعَـٰلَمِینَ ۝٢٨", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "واذكر -أيها الرسول- لوطًا حين قال لقومه: إنكم لتأتون الفعلة القبيحة، ما تَقَدَّمكم بفعلها أحد من العالمين، أإنكم لتأتون الرجال في أدبارهم، وتقطعون على المسافرين طرقهم بفعلكم الخبيث، وتأتون في مجالسكم الأعمال المنكرة كالسخرية من الناس، وحذف المارة، وإيذائهم بما لا يليق من الأقوال والأفعال؟ وفي هذا إعلام بأنه لا يجوز أن يجتمع الناس على المنكر مما نهى الله ورسوله عنه. فلم يكن جواب قوم لوط له إلا أن قالوا: جئنا بعذاب الله إن كنت من الصادقين فيما تقول، والمنجزين لما تَعِد.", "isBasmala": false, "translation_en": "And Lot, when he said to his people, \"You are committing an obscenity not perpetrated before you by anyone in the whole world.", "translation_id": "Dan (ingatlah) ketika Luth berkata pepada kaumnya: \"Sesungguhnya kamu benar-benar mengerjakan perbuatan yang amat keji yang belum pernah dikerjakan oleh seorangpun dari umat-umat sebelum kamu\".", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 29, "text": "أَىِٕنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ وَتَقۡطَعُونَ ٱلسَّبِیلَ وَتَأۡتُونَ فِی نَادِیكُمُ ٱلۡمُنكَرَۖ فَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوا۟ ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ ۝٢٩", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "واذكر -أيها الرسول- لوطًا حين قال لقومه: إنكم لتأتون الفعلة القبيحة، ما تَقَدَّمكم بفعلها أحد من العالمين، أإنكم لتأتون الرجال في أدبارهم، وتقطعون على المسافرين طرقهم بفعلكم الخبيث، وتأتون في مجالسكم الأعمال المنكرة كالسخرية من الناس، وحذف المارة، وإيذائهم بما لا يليق من الأقوال والأفعال؟ وفي هذا إعلام بأنه لا يجوز أن يجتمع الناس على المنكر مما نهى الله ورسوله عنه. فلم يكن جواب قوم لوط له إلا أن قالوا: جئنا بعذاب الله إن كنت من الصادقين فيما تقول، والمنجزين لما تَعِد.", "isBasmala": false, "translation_en": "You approach men, and cut off the way, and commit lewdness in your gatherings.\" But the only response from his people was to say, \"Bring upon us God's punishment, if you are truthful.\"", "translation_id": "Apakah sesungguhnya kamu patut mendatangi laki-laki, menyamun dan mengerjakan kemungkaran di tempat-tempat pertemuanmu? Maka jawaban kaumnya tidak lain hanya mengatakan: \"Datangkanlah kepada kami azab Allah, jika kamu termasuk orang-orang yang benar\".", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 30, "text": "قَالَ رَبِّ ٱنصُرۡنِی عَلَى ٱلۡقَوۡمِ ٱلۡمُفۡسِدِینَ ۝٣٠", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "قال: رب انصرني على القوم المفسدين بإنزال العذاب عليهم؛ حيث ابتدعوا الفاحشة وأصرُّوا عليها، فاستجاب الله دعاءه.", "isBasmala": false, "translation_en": "He said, \"My Lord, help me against the people of corruption.\"", "translation_id": "Luth berdoa: \"Ya Tuhanku, tolonglah aku (dengan menimpakan azab) atas kaum yang berbuat kerusakan itu\".", "manzil": 5, "manzil_display": ""}], "400": [{"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 31, "text": "وَلَمَّا جَاۤءَتۡ رُسُلُنَاۤ إِبۡرَ ٰهِیمَ بِٱلۡبُشۡرَىٰ قَالُوۤا۟ إِنَّا مُهۡلِكُوۤا۟ أَهۡلِ هَـٰذِهِ ٱلۡقَرۡیَةِۖ إِنَّ أَهۡلَهَا كَانُوا۟ ظَـٰلِمِینَ ۝٣١", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "ولما جاءت الملائكة إبراهيم بالخبر السارِّ من الله بإسحاق، ومن وراء إسحاق ولده يعقوب، قالت الملائكة لإبراهيم: إنا مهلكو أهل قرية قوم لوط، وهي \"سدوم\"؛ إنَّ أهلها كانوا ظالمي أنفسهم بمعصيتهم لله.", "isBasmala": false, "translation_en": "And when Our envoys brought Abraham the good news, they said, \"We are going to destroy the people of this town; its people are wrongdoers.\"", "translation_id": "Dan tatkala utusan Kami (para malaikat) datang kepada Ibrahim membawa kabar gembira, mereka mengatakan: \"Sesungguhnya kami akan menghancurkan penduduk negeri (Sodom) ini; sesungguhnya penduduknya adalah orang-orang yang zalim\".", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 32, "text": "قَالَ إِنَّ فِیهَا لُوطࣰاۚ قَالُوا۟ نَحۡنُ أَعۡلَمُ بِمَن فِیهَاۖ لَنُنَجِّیَنَّهُۥ وَأَهۡلَهُۥۤ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَـٰبِرِینَ ۝٣٢", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "قال إبراهيم للملائكة: إنَّ فيها لوطًا وليس من الظالمين، فقالت الملائكة له: نحن أعلم بمن فيها، لننجِّينَّه وأهله من الهلاك الذي سينزل بأهل قريته إلا امرأته كانت من الباقين الهالكين.", "isBasmala": false, "translation_en": "He said, \"Yet Lot is in it.\" They said, \"We are well aware of who is in it. We will save him, and his family, except for his wife, who will remain behind.\"", "translation_id": "Berkata Ibrahim: \"Sesungguhnya di kota itu ada Luth\". Para malaikat berkata: \"Kami lebih mengetahui siapa yang ada di kota itu. Kami sungguh-sungguh akan menyelamatkan dia dan pengikut-pengikutnya kecuali isterinya. Dia adalah termasuk orang-orang yang tertinggal (dibinasakan).", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 33, "text": "وَلَمَّاۤ أَن جَاۤءَتۡ رُسُلُنَا لُوطࣰا سِیۤءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعࣰاۖ وَقَالُوا۟ لَا تَخَفۡ وَلَا تَحۡزَنۡ إِنَّا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا ٱمۡرَأَتَكَ كَانَتۡ مِنَ ٱلۡغَـٰبِرِینَ ۝٣٣", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "ولما جاءت الملائكة لوطًا ساءه ذلك؛ لأنه ظنهم ضيوفًا من البشر، وحزن بسبب وجودهم؛ لعلمه خبث فعل قومه، وقالوا له: لا تَخَفْ علينا لن يصل إلينا قومك، ولا تحزن مما أخبرناك مِن أنا مهلكوهم، إنَّا منجُّوك من العذاب النازل بقومك ومنجُّو أهلك معك إلا أمرأتك، فإنها هالكة فيمن يهلك مِن قومها.", "isBasmala": false, "translation_en": "Then, when Our envoys came to Lot, they were mistreated, and he was troubled and distressed on their account. They said, \"Do not fear, nor grieve. We will save you and your family, except for your wife, who will remain behind.\"", "translation_id": "Dan tatkala datang utusan-utusan Kami (para malaikat) itu kepada Luth, dia merasa susah karena (kedatangan) mereka, dan (merasa) tidak punya kekuatan untuk melindungi mereka dan mereka berkata: \"Janganlah kamu takut dan jangan (pula) susah. Sesungguhnya kami akan menyelamatkan kamu dan pengikut-pengikutmu, kecuali isterimu, dia adalah termasuk orang-orang yang tertinggal (dibinasakan)\".", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 34, "text": "إِنَّا مُنزِلُونَ عَلَىٰۤ أَهۡلِ هَـٰذِهِ ٱلۡقَرۡیَةِ رِجۡزࣰا مِّنَ ٱلسَّمَاۤءِ بِمَا كَانُوا۟ یَفۡسُقُونَ ۝٣٤", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "إنا منزلون على أهل هذه القرية عذابًا من السماء؛ بسبب معصيتهم لله وارتكابهم الفاحشة.", "isBasmala": false, "translation_en": "\"We will bring down upon the people of this town a scourge from heaven, because of their wickedness.\"", "translation_id": "Sesungguhnya Kami akan menurunkan azab dari langit atas penduduk kota ini karena mereka berbuat fasik.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 35, "text": "وَلَقَد تَّرَكۡنَا مِنۡهَاۤ ءَایَةَۢ بَیِّنَةࣰ لِّقَوۡمࣲ یَعۡقِلُونَ ۝٣٥", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "ولقد أبقينا مِن ديار قوم لوط آثارًا بينة لقوم يعقلون العبر، فينتفعون بها.", "isBasmala": false, "translation_en": "And We left behind a clear trace of it, for people who understand.", "translation_id": "Dan sesungguhnya Kami tinggalkan daripadanya satu tanda yang nyata bagi orang-orang yang berakal.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 36, "text": "وَإِلَىٰ مَدۡیَنَ أَخَاهُمۡ شُعَیۡبࣰا فَقَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱرۡجُوا۟ ٱلۡیَوۡمَ ٱلۡـَٔاخِرَ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ ۝٣٦", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "وأرسلنا إلى \"مدين\" أخاهم شعيبًا، فقال لهم: يا قوم اعبدوا الله وحده، وأخلصوا له العبادة، ما لكم من إله غيره، وارجوا بعبادتكم جزاء اليوم الآخر، ولا تكثروا في الأرض الفساد والمعاصي، ولا تقيموا عليها، ولكن توبوا إلى الله منها وأنيبوا.", "isBasmala": false, "translation_en": "And to Median, their brother Shuaib. He said, \"O my people, worship God and anticipate the Last Day, and do not spread corruption in the land.\"", "translation_id": "Dan (Kami telah mengutus) kepada penduduk Mad-yan, saudara mereka Syu'aib, maka ia berkata: \"Hai kaumku, sembahlah olehmu Allah, harapkanlah (pahala) hari akhir, dan jangan kamu berkeliaran di muka bumi berbuat kerusakan\".", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 37, "text": "فَكَذَّبُوهُ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُوا۟ فِی دَارِهِمۡ جَـٰثِمِینَ ۝٣٧", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "فكذَّب أهل \"مدين\" شعيبًا فيما جاءهم به عن الله من الرسالة، فأخذتهم الزلزلة الشديدة، فأصبحوا في دارهم صَرْعى هالكين.", "isBasmala": false, "translation_en": "But they rejected him, so the tremor overtook them, and they were left motionless in their homes.", "translation_id": "Maka mereka mendustakan Syu'aib, lalu mereka ditimpa gempa yang dahsyat, dan jadilah mereka mayat-mayat yang bergelimpangan di tempat-tempat tinggal mereka.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 38, "text": "وَعَادࣰا وَثَمُودَا۟ وَقَد تَّبَیَّنَ لَكُم مِّن مَّسَـٰكِنِهِمۡۖ وَزَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ أَعۡمَـٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِیلِ وَكَانُوا۟ مُسۡتَبۡصِرِینَ ۝٣٨", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "وأهلكنا عادًا وثمود، وقد تبين لكم من مساكنهم خَرابُها وخلاؤها منهم، وحلول نقمتنا بهم جميعًا، وحسَّن لهم الشيطان أعمالهم القبيحة، فصدَّهم عن سبيل الله وعن طريق الإيمان به وبرسله، وكانوا مستبصرين في كفرهم وضلالهم، معجبين به، يحسبون أنهم على هدى وصواب، بينما هم في الضلال غارقون.", "isBasmala": false, "translation_en": "And Aad and Thamood. It has become clear to you from their dwellings. Satan embellished for them their deeds, barring them from the path, even though they could see.", "translation_id": "Dan (juga) kaum 'Aad dan Tsamud, dan sungguh telah nyata bagi kamu (kehancuran mereka) dari (puing-puing) tempat tinggal mereka. Dan syaitan menjadikan mereka memandang baik perbuatan-perbuatan mereka, lalu ia menghalangi mereka dari jalan (Allah), sedangkan mereka adalah orang-orang berpandangan tajam,", "manzil": 5, "manzil_display": ""}], "401": [{"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 39, "text": "وَقَـٰرُونَ وَفِرۡعَوۡنَ وَهَـٰمَـٰنَۖ وَلَقَدۡ جَاۤءَهُم مُّوسَىٰ بِٱلۡبَیِّنَـٰتِ فَٱسۡتَكۡبَرُوا۟ فِی ٱلۡأَرۡضِ وَمَا كَانُوا۟ سَـٰبِقِینَ ۝٣٩", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "وأهلكنا قارون وفرعون وهامان، ولقد جاءهم جميعًا موسى بالأدلة الواضحة، فتعاظموا في الأرض، واستكبروا فيها، ولم يكونوا ليفوتوننا، بل كنا مقتدرين عليهم.", "isBasmala": false, "translation_en": "And Quaroon, and Pharaoh, and Hamaan-Moses went to them with clear arguments, but they acted arrogantly in the land. And they could not get ahead.", "translation_id": "dan (juga) Karun, Fir'aun dan Haman. Dan sesungguhnya telah datang kepada mereka Musa dengan (membawa bukti-bukti) keterangan-keterangan yang nyata. Akan tetapi mereka berlaku sombong di (muka) bumi, dan tiadalah mereka orang-orang yang luput (dari kehancuran itu).", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 40, "text": "فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَیۡهِ حَاصِبࣰا وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّیۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِیَظۡلِمَهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ ۝٤٠", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "فأخذنا كلا من هؤلاء المذكورين بعذابنا بسبب ذنبه: فمنهم الذين أرسلنا عليهم حجارة من طين منضود، وهم قوم لوط، ومنهم مَن أخذته الصيحة، وهم قوم صالح وقوم شعيب، ومنهم مَن خسفنا به الأرض كقارون، ومنهم مَن أغرقنا، وهم قومُ نوح وفرعونُ وقومُه، ولم يكن الله ليهلك هؤلاء بذنوب غيرهم، فيظلمهم بإهلاكه إياهم بغير استحقاق، ولكنهم كانوا أنفسهم يظلمون بتنعمهم في نِعَم ربهم وعبادتهم غيره.", "isBasmala": false, "translation_en": "Each We seized by his sin. Against some We sent a sandstorm. Some were struck by the Blast. Some We caused the ground to cave in beneath them. And some We drowned. It was not God who wronged them, but it was they who wronged their own selves.", "translation_id": "Maka masing-masing (mereka itu) Kami siksa disebabkan dosanya, maka di antara mereka ada yang Kami timpakan kepadanya hujan batu kerikil dan di antara mereka ada yang ditimpa suara keras yang mengguntur, dan di antara mereka ada yang Kami benamkan ke dalam bumi, dan di antara mereka ada yang Kami tenggelamkan, dan Allah sekali-kali tidak hendak menganiaya mereka, akan tetapi merekalah yang menganiaya diri mereka sendiri.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 41, "text": "مَثَلُ ٱلَّذِینَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوۡلِیَاۤءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَیۡتࣰاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُیُوتِ لَبَیۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ ۝٤١", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "مثل الذين جعلوا الأوثان من دون الله أولياء يرجون نصرها، كمثل العنكبوت التي عملت بيتًا لنفسها ليحفظها، فلم يُغن عنها شيئًا عند حاجتها إليه، فكذلك هؤلاء المشركون لم يُغْن عنهم أولياؤهم الذين اتخذوهم من دون الله شيئًا، وإن أضعف البيوت لَبيت العنكبوت، لو كانوا يعلمون ذلك ما اتخذوهم أولياء، فهم لا ينفعونهم ولا يضرونهم.", "isBasmala": false, "translation_en": "The likeness of those who take to themselves protectors other than God is that of the spider. It builds a house. But the most fragile of houses is the spider's house. If they only knew.", "translation_id": "Perumpamaan orang-orang yang mengambil pelindung-pelindung selain Allah adalah seperti laba-laba yang membuat rumah. Dan sesungguhnya rumah yang paling lemah adalah rumah laba-laba kalau mereka mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 42, "text": "إِنَّ ٱللَّهَ یَعۡلَمُ مَا یَدۡعُونَ مِن دُونِهِۦ مِن شَیۡءࣲۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٤٢", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "إن الله يعلم ما يشركون به من الأنداد، وأنها ليست بشيء في الحقيقة، بل هي مجرد أسماء سَمَّوها، لا تنفع ولا تضر. وهو العزيز في انتقامه ممن كفر به، الحكيم في تدبيره وصنعه.", "isBasmala": false, "translation_en": "God knows what they invoke besides Him. He is the Almighty, the Wise.", "translation_id": "Sesungguhnya Allah mengetahui apa saja yang mereka seru selain Allah. Dan Dia Maha Perkasa lagi Maha Bijaksana.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 43, "text": "وَتِلۡكَ ٱلۡأَمۡثَـٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا یَعۡقِلُهَاۤ إِلَّا ٱلۡعَـٰلِمُونَ ۝٤٣", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "وهذه الأمثال نضربها للناس؛ لينتفعوا بها ويتعلموا منها، وما يعقلها إلا العالمون بالله وآياته وشرعه.", "isBasmala": false, "translation_en": "These examples-We put them forward to the people; but none grasps them except the learned.", "translation_id": "Dan perumpamaan-perumpamaan ini Kami buat untuk manusia; dan tiada yang memahaminya kecuali orang-orang yang berilmu.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 44, "text": "خَلَقَ ٱللَّهُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّلۡمُؤۡمِنِینَ ۝٤٤", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "خلق الله السموات والأرض بالعدل والقسط، إن في خلقه ذلك لدلالة عظيمة على قدرته، وتفرده بالإلهية، وخَصَّ المؤمنين؛ لأنهم الذين ينتفعون بذلك.", "isBasmala": false, "translation_en": "God created the heavens and the earth with truth. Surely in that is a sign for the believers.", "translation_id": "Allah menciptakan langit dan bumi dengan hak. Sesungguhnya pada yang demikian itu terdapat tanda-tanda kekuasaan Allah bagi orang-orang mukmin.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 45, "text": "ٱتۡلُ مَاۤ أُوحِیَ إِلَیۡكَ مِنَ ٱلۡكِتَـٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَاۤءِ وَٱلۡمُنكَرِۗ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ وَٱللَّهُ یَعۡلَمُ مَا تَصۡنَعُونَ ۝٤٥", "juz": 20, "hizb": "(*¾ ح 40*)", "tafsir": "اتل ما أُنزل إليك من هذا القرآن، واعمل به، وأدِّ الصلاة بحدودها، إن المحافظة على الصلاة تنهى صاحبها عن الوقوع في المعاصي والمنكرات؛ وذلك لأن المقيم لها، المتمم لأركانها وشروطها، يستنير قلبه، ويزداد إيمانه، وتقوى رغبته في الخير، وتقل أو تنعدم رغبته في الشر، ولَذكر الله في الصلاة وغيرها أعظم وأكبر وأفضل من كل شيء. والله يعلم ما تصنعون مِن خيرٍ وشر، فيجازيكم على ذلك أكمل الجزاء وأوفاه.", "isBasmala": false, "translation_en": "Recite what is revealed to you of the Scripture, and perform the prayer. The prayer prevents indecencies and evils. And the remembrance of God is greater. And God knows what you do.", "translation_id": "Bacalah apa yang telah diwahyukan kepadamu, yaitu Al Kitab (Al Quran) dan dirikanlah shalat. Sesungguhnya shalat itu mencegah dari (perbuatan-perbuatan) keji dan mungkar. Dan sesungguhnya mengingat Allah (shalat) adalah lebih besar (keutamaannya dari ibadat-ibadat yang lain). Dan Allah mengetahui apa yang kamu kerjakan.", "manzil": 5, "manzil_display": ""}], "402": [{"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 46, "text": "۞ وَلَا تُجَـٰدِلُوۤا۟ أَهۡلَ ٱلۡكِتَـٰبِ إِلَّا بِٱلَّتِی هِیَ أَحۡسَنُ إِلَّا ٱلَّذِینَ ظَلَمُوا۟ مِنۡهُمۡۖ وَقُولُوۤا۟ ءَامَنَّا بِٱلَّذِیۤ أُنزِلَ إِلَیۡنَا وَأُنزِلَ إِلَیۡكُمۡ وَإِلَـٰهُنَا وَإِلَـٰهُكُمۡ وَ ٰحِدࣱ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ۝٤٦", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "ولا تجادلوا -أيها المؤمنون- اليهودَ والنصارى إلا بالأسلوب الحسن، والقول الجميل، والدعوة إلى الحق بأيسر طريق موصل لذلك، إلا الذين حادوا عن وجه الحق وعاندوا وكابروا وأعلنوا الحرب عليكم فجالدوهم بالسيف حتى يؤمنوا، أو يعطوا الجزية عن يدٍ وهم صاغرون، وقولوا: آمنا بالقرآن الذي أُنزل إلينا، وآمنا بالتوراة والإنجيل اللذَيْن أُنزلا إليكم، وإلهنا وإلهكم واحد لا شريك له في ألوهيته، ولا في ربوبيته، ولا في أسمائه وصفاته، ونحن له خاضعون متذللون بالطاعة فيما أمرنا به، ونهانا عنه.", "isBasmala": false, "translation_en": "And do not argue with the People of the Scripture except in the best manner possible, except those who do wrong among them. And say, \"We believe in what was revealed to us, and in what was revealed to you; and our God and your God is One; and to Him we are submissive.\"", "translation_id": "Dan janganlah kamu berdebat denganAhli Kitab, melainkan dengan cara yang paling baik, kecuali dengan orang-orang zalim di antara mereka, dan katakanlah: \"Kami telah beriman kepada (kitab-kitab) yang diturunkan kepada kami dan yang diturunkan kepadamu; Tuhan kami dan Tuhanmu adalah satu; dan kami hanya kepada-Nya berserah diri\".", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 47, "text": "وَكَذَ ٰلِكَ أَنزَلۡنَاۤ إِلَیۡكَ ٱلۡكِتَـٰبَۚ فَٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَـٰۤؤُلَاۤءِ مَن یُؤۡمِنُ بِهِۦۚ وَمَا یَجۡحَدُ بِـَٔایَـٰتِنَاۤ إِلَّا ٱلۡكَـٰفِرُونَ ۝٤٧", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "وكما أنزلنا -أيها الرسول- الكتب على مَن قبلك من الرسل، أنزلنا إليك هذا الكتاب المصدق للكتب السابقة، فالذين آتيناهم الكتاب من بني إسرائيل فعرفوه حق معرفته يؤمنون بالقرآن، ومِن هؤلاء العرب من قريش وغيرهم مَن يؤمن به، ولا ينكر القرآن أو يتشكك في دلائله وبراهينه البينة إلا الكافرون الذين دَأْبُهم الجحود والعناد.", "isBasmala": false, "translation_en": "Likewise, We revealed to you the Scripture. Those to whom We gave the Scripture believe in it, and some of these believe in it. None renounce Our communications except the disbelievers.", "translation_id": "Dan demikian (pulalah) Kami turunkan kepadamu Al Kitab (Al Quran). Maka orang-orang yang telah kami berikan kepada mereka Al Kitab (Taurat) mereka beriman kepadanya (Al Quran); dan di antara mereka (orang-orang kafir Mekah) ada yang beriman kepadanya. Dan tiadalah yang mengingkari ayat-ayat kami selain orang-orang kafir.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 48, "text": "وَمَا كُنتَ تَتۡلُوا۟ مِن قَبۡلِهِۦ مِن كِتَـٰبࣲ وَلَا تَخُطُّهُۥ بِیَمِینِكَۖ إِذࣰا لَّٱرۡتَابَ ٱلۡمُبۡطِلُونَ ۝٤٨", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "من معجزاتك البينة -أيها الرسول- أنك لم تقرأ كتابًا ولم تكتب حروفًا بيمينك قبل نزول القرآن عليك، وهم يعرفون ذلك، ولو كنت قارئًا أو كاتبًا من قبل أن يوحى إليك لشك في ذلك المبطلون، وقالوا: تعلَّمه من الكتب السابقة أو استنسخه منها.", "isBasmala": false, "translation_en": "You did not read any scripture before this, nor did you write it down with your right hand; otherwise the falsifiers would have doubted.", "translation_id": "Dan kamu tidak pernah membaca sebelumnya (Al Quran) sesuatu Kitabpun dan kamu tidak (pernah) menulis suatu Kitab dengan tangan kananmu; andaikata (kamu pernah membaca dan menulis), benar-benar ragulah orang yang mengingkari(mu).", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 49, "text": "بَلۡ هُوَ ءَایَـٰتُۢ بَیِّنَـٰتࣱ فِی صُدُورِ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَۚ وَمَا یَجۡحَدُ بِـَٔایَـٰتِنَاۤ إِلَّا ٱلظَّـٰلِمُونَ ۝٤٩", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "بل القرآن آيات بينات واضحة في الدلالة على الحق يحفظه العلماء، وما يكذِّب بآياتنا ويردها إلا الظالمون المعاندون الذين يعلمون الحق ويحيدون عنه.", "isBasmala": false, "translation_en": "In fact, it is clear signs in the hearts of those given knowledge. No one renounce Our signs except the unjust.", "translation_id": "Sebenarnya, Al Quran itu adalah ayat-ayat yang nyata di dalam dada orang-orang yang diberi ilmu. Dan tidak ada yang mengingkari ayat-ayat Kami kecuali orang-orang yang zalim.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 50, "text": "وَقَالُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ ءَایَـٰتࣱ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡـَٔایَـٰتُ عِندَ ٱللَّهِ وَإِنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینٌ ۝٥٠", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "وقال المشركون: هلا أُنزل على محمد دلائل وحجج من ربه نشاهدها كناقة صالح، وعصا موسى! قل لهم: إن أمر هذه الآيات لله، إن شاء أنزلها، وإن شاء منعها، وإنما أنا لكم نذير أحذركم شدة بأسه وعقابه، مبيِّن طريق الحق من الباطل.", "isBasmala": false, "translation_en": "And they said, \"If only a miracle from his Lord was sent down to him.\" Say, \"Miracles are only with God, and I am only a clear warner.\"", "translation_id": "Dan orang-orang kafir Mekah berkata: \"Mengapa tidak diturunkan kepadanya mukjizat-mukjizat dari Tuhannya?\" Katakanlah: \"Sesungguhnya mukjizat-mukjizat itu terserah kepada Allah. Dan sesungguhnya aku hanya seorang pemberi peringatan yang nyata\".", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 51, "text": "أَوَ لَمۡ یَكۡفِهِمۡ أَنَّاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡكِتَـٰبَ یُتۡلَىٰ عَلَیۡهِمۡۚ إِنَّ فِی ذَ ٰلِكَ لَرَحۡمَةࣰ وَذِكۡرَىٰ لِقَوۡمࣲ یُؤۡمِنُونَ ۝٥١", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "أولم يكف هؤلاء المشركين في علمهم بصدقك -أيها الرسول- أنَّا أنزلنا عليك القرآن يتلى عليهم؟ إن في هذا القرآن لَرحمة للمؤمنين في الدنيا والآخرة، وذكرى يتذكرون بما فيه من عبرة وعظة.", "isBasmala": false, "translation_en": "Does it not suffice them that We revealed to you the Scripture, which is recited to them? In that is mercy and a reminder for people who believe.", "translation_id": "Dan apakah tidak cukup bagi mereka bahwasanya Kami telah menurunkan kepadamu Al Kitab (Al Quran) sedang dia dibacakan kepada mereka? Sesungguhnya dalam (Al Quran) itu terdapat rahmat yang besar dan pelajaran bagi orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 52, "text": "قُلۡ كَفَىٰ بِٱللَّهِ بَیۡنِی وَبَیۡنَكُمۡ شَهِیدࣰاۖ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِینَ ءَامَنُوا۟ بِٱلۡبَـٰطِلِ وَكَفَرُوا۟ بِٱللَّهِ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ ۝٥٢", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "قل: كفى بالله بيني وبينكم شاهدًا على صدقي أني رسوله، وعلى تكذيبكم لي وردكم الحق الذي جئتُ به من عند الله، يعلم ما في السموات والأرض، فلا يخفى عليه شيء فيهما. والذين آمنوا بالباطل وكفروا بالله -مع هذه الدلائل الواضحة- أولئك هم الخاسرون في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Say, \"God suffices as witness between you and me. He knows everything in the heavens and the Earth. Those who believe in vanity and reject God-it is they who are the losers.\"", "translation_id": "Katakanlah: \"Cukuplah Allah menjadi saksi antaraku dan antaramu. Dia mengetahui apa yang di langit dan di bumi. Dan orang-orang yang percaya kepada yang batil dan ingkar kepada Allah, mereka itulah orang-orang yang merugi.", "manzil": 5, "manzil_display": ""}], "403": [{"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 53, "text": "وَیَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَوۡلَاۤ أَجَلࣱ مُّسَمࣰّى لَّجَاۤءَهُمُ ٱلۡعَذَابُۚ وَلَیَأۡتِیَنَّهُم بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ ۝٥٣", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "ويستعجلك -أيها الرسول- هؤلاء المشركون من قومك بالعذاب استهزاء، ولولا أن الله جعل لعذابهم في الدنيا وقتًا لا يتقدم ولا يتأخر، لجاءهم العذاب حين طلبوه، وليأتينهم فجأة، وهم لا يشعرون به ولا يُحِسُّون.", "isBasmala": false, "translation_en": "And they urge you to hasten the punishment. Were it not for a specified time, the punishment would have come to them. But it will come upon them suddenly, while they are unaware.", "translation_id": "Dan mereka meminta kepadamu supaya segera diturunkan azab. Kalau tidaklah karena waktu yang telah ditetapkan, benar-benar telah datang azab kepada mereka, dan azab itu benar-benar akan datang kepada mereka dengan tiba-tiba, sedang mereka tidak menyadarinya.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 54, "text": "یَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِیطَةُۢ بِٱلۡكَـٰفِرِینَ ۝٥٤", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "يستعجلونك بالعذاب في الدنيا، وهو آتيهم لا محالة إمَّا في الدنيا وإما في الآخرة، وإن عذاب جهنم في الآخرة لمحيط بهم، لا مفرَّ لهم منه.", "isBasmala": false, "translation_en": "They urge you to hasten the punishment. But Hell will engulf the disbelievers.", "translation_id": "Mereka meminta kepadamu supaya segera diturunkan azab. Dan sesungguhnya Jahannam benar-benar meliputi orang-orang yang kafir,", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 55, "text": "یَوۡمَ یَغۡشَىٰهُمُ ٱلۡعَذَابُ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ وَیَقُولُ ذُوقُوا۟ مَا كُنتُمۡ تَعۡمَلُونَ ۝٥٥", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "يوم القيامة يغشى الكافرين عذاب جهنم من فوق رؤوسهم، ومِن تحت أقدامهم، فالنار تغشاهم من سائر جهاتهم، ويقول الله لهم حينئذ: ذوقوا جزاء ما كنتم تعملونه في الدنيا: من الإشراك بالله، وارتكاب الجرائم والآثام.", "isBasmala": false, "translation_en": "On the Day when the punishment will envelop them, from above them, and from beneath their feet, He will say, \"Taste what you used to do!\"", "translation_id": "pada hari mereka ditutup oleh azab dari atas mereka dan dari bawah kaki mereka dan Allah berkata (kepada mereka): \"Rasailah (pembalasan dari) apa yang telah kamu kerjakan\".", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 56, "text": "یَـٰعِبَادِیَ ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ أَرۡضِی وَ ٰسِعَةࣱ فَإِیَّـٰیَ فَٱعۡبُدُونِ ۝٥٦", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "يا عبادي الذين آمنوا إن كنتم في ضيق من إظهار الإيمان وعبادة الله وحده، فهاجِروا إلى أرض الله الواسعة، وأخلصوا العبادة لي وحدي.", "isBasmala": false, "translation_en": "O My servants who have believed: My earth is vast, so worship Me alone.", "translation_id": "Hai hamba-hamba-Ku yang beriman, sesungguhnya bumi-Ku luas, maka sembahlah Aku saja.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 57, "text": "كُلُّ نَفۡسࣲ ذَاۤىِٕقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَیۡنَا تُرۡجَعُونَ ۝٥٧", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "كل نفس حية ذائقة الموت، ثم إلينا ترجعون للحساب والجزاء.", "isBasmala": false, "translation_en": "Every soul will taste death. Then to Us you will be returned.", "translation_id": "Tiap-tiap yang berjiwa akan merasakan mati. Kemudian hanyalah kepada Kami kamu dikembalikan.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 58, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفࣰا تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَـٰمِلِینَ ۝٥٨", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "والذين صدَّقوا بالله ورسوله وعملوا ما أُمروا به من الصالحات لننزلنَّهم من الجنة غرفًا عالية تجري من تحتها الأنهار، ماكثين فيها أبدًا، نِعْمَ جزاء العاملين بطاعة الله هذه الغرف في جنات النعيم.", "isBasmala": false, "translation_en": "Those who believe and work righteousness-We will settle them in Paradise, in mansions under which rivers flow, dwelling therein forever. Excellent is the compensation for the workers.", "translation_id": "Dan orang-orang yang beriman dan mengerjakan amal-amal yang saleh, sesungguhnya akan Kami tempatkan mereka pada tempat-tempat yang tinggi di dalam surga, yang mengalir sungai-sungai di bawahnya, mereka kekal di dalamnya. Itulah sebaik-baik pembalasan bagi orang-orang yang beramal,", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 59, "text": "ٱلَّذِینَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ ۝٥٩", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "إن تلك الجنات المذكورة للمؤمنين الذين صبروا على عبادة الله، وتمسكوا بدينهم، وعلى الله يعتمدون في أرزاقهم وجهاد أعدائهم.", "isBasmala": false, "translation_en": "Those who endure patiently, and in their Lord they trust.", "translation_id": "(yaitu) yang bersabar dan bertawakkal kepada Tuhannya.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 60, "text": "وَكَأَیِّن مِّن دَاۤبَّةࣲ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ یَرۡزُقُهَا وَإِیَّاكُمۡۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٦٠", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "وكم من دابة لا تدَّخر غذاءها لغد، كما يفعل ابن آدم، فالله سبحانه وتعالى يرزقها كما يرزقكم، وهو السميع لأقوالكم، العليم بأفعالكم وخطرات قلوبكم.", "isBasmala": false, "translation_en": "How many a creature there is that does not carry its provision? God provides for them, and for you. He is the Hearer, the Knowledgeable.", "translation_id": "Dan berapa banyak binatang yang tidak (dapat) membawa (mengurus) rezekinya sendiri. Allah-lah yang memberi rezeki kepadanya dan kepadamu dan Dia Maha Mendengar lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 61, "text": "وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَ لَیَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ یُؤۡفَكُونَ ۝٦١", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "ولئن سألت -أيها الرسول- المشركين: من الذي خلق السموات والأرض على هذا النظام البديع، وذلَّل الشمس والقمر؟ ليقولُنَّ: خلقهن الله وحده، فكيف يصرفون عن الإيمان بالله خالق كل شيء ومدبره، ويعبدون معه غيره؟ فاعجب من إفكهم وكذبهم!!", "isBasmala": false, "translation_en": "And if you asked them, \"Who created the heavens and the earth and regulated the sun and the moon?\" They would say, \"God.\" Why then do they deviate?", "translation_id": "Dan sesungguhnya jika kamu tanyakan kepada mereka: \"Siapakah yang menjadikan langit dan bumi dan menundukkan matahari dan bulan?\" Tentu mereka akan menjawab: \"Allah\", maka betapakah mereka (dapat) dipalingkan (dari jalan yang benar).", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 62, "text": "ٱللَّهُ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ مِنۡ عِبَادِهِۦ وَیَقۡدِرُ لَهُۥۤۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمࣱ ۝٦٢", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "الله سبحانه وتعالى يوسع الرزق لمن يشاء من خلقه، ويضيق على آخرين منهم؛ لعلمه بما يصلح عباده، إن الله بكل شيء من أحوالكم وأموركم عليم، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "God expands the provision for whomever He wills of His servants, and restricts it. God is Cognizant of all things.", "translation_id": "Allah melapangkan rezeki bagi siapa yang dikehendaki-Nya di antara hamba-hamba-Nya dan Dia (pula) yang menyempitkan baginya. Sesungguhnya Allah Maha Mengetahui segala sesuatu.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 63, "text": "وَلَىِٕن سَأَلۡتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَحۡیَا بِهِ ٱلۡأَرۡضَ مِنۢ بَعۡدِ مَوۡتِهَا لَیَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡقِلُونَ ۝٦٣", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "ولئن سألت -أيها الرسول- المشركين: مَنِ الذي نزَّل من السحاب ماء فأنبت به الأرض من بعد جفافها؟ ليقولُنَّ لك معترفين: الله وحده هو الذي نزَّل ذلك، قل: الحمد لله الذي أظهر حجتك عليهم، بل أكثرهم لا يعقلون ما ينفعهم ولا ما يضرهم، ولو عَقَلوا ما أشركوا مع الله غيره.", "isBasmala": false, "translation_en": "And if you asked them, \"Who sends water down from the sky, with which He revives the earth after it had died?\" They would say, \"God.\" Say, \"Praise be to God.\" But most of them do not understand.", "translation_id": "Dan sesungguhnya jika kamu menanyakan kepada mereka: \"Siapakah yang menurunkan air dari langit lalu menghidupkan dengan air itu bumi sesudah matinya?\" Tentu mereka akan menjawab: \"Allah\", Katakanlah: \"Segala puji bagi Allah\", tetapi kebanyakan mereka tidak memahami(nya).", "manzil": 5, "manzil_display": ""}], "404": [{"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 64, "text": "وَمَا هَـٰذِهِ ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا لَهۡوࣱ وَلَعِبࣱۚ وَإِنَّ ٱلدَّارَ ٱلۡـَٔاخِرَةَ لَهِیَ ٱلۡحَیَوَانُۘ لَوۡ كَانُوا۟ یَعۡلَمُونَ ۝٦٤", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "وما هذه الحياة الدنيا إلا لهو ولعب، تلهو بها القلوب وتلعب بها الأبدان؛ بسبب ما فيها من الزينة والشهوات، ثم تزول سريعًا، وإن الدار الآخرة لهي الحياة الحقيقية الدائمة التي لا موت فيها، لو كان الناس يعلمون ذلك لما آثروا دار الفناء على دار البقاء.", "isBasmala": false, "translation_en": "The life of this world is nothing but diversion and play, and the Home of the Hereafter is the Life, if they only knew.", "translation_id": "Dan tiadalah kehidupan dunia ini melainkan senda gurau dan main-main. Dan sesungguhnya akhirat itulah yang sebenarnya kehidupan, kalau mereka mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 65, "text": "فَإِذَا رَكِبُوا۟ فِی ٱلۡفُلۡكِ دَعَوُا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ یُشۡرِكُونَ ۝٦٥", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "فإذا ركب الكفار السفن في البحر، وخافوا الغرق، وحَّدوا الله، وأخلصوا له في الدعاء حال شدتهم، فلما نجَّاهم إلى البر، وزالت عنهم الشدة، عادوا إلى شركهم، إنهم بهذا يتناقضون، يوحِّدون الله ساعة الشدة، ويشركون به ساعة الرخاء. وشِرْكهم بعد نعمتنا عليهم بالنجاة من البحر؛ ليكونَ عاقبته الكفر بما أنعمنا عليهم في أنفسهم وأموالهم، وليكملوا تمتعهم في هذه الدنيا، فسوف يعلمون فساد عملهم، وما أعدَّه الله لهم من عذاب أليم يوم القيامة. وفي ذلك تهديد ووعيد لهم.", "isBasmala": false, "translation_en": "When they embark on a vessel, they pray to God, devoting their faith to Him; but once He has delivered them safely to land, they attribute partners to Him.", "translation_id": "Maka apabila mereka naik kapal mereka mendoa kepada Allah dengan memurnikan ketaatan kepada-Nya; maka tatkala Allah menyelamatkan mereka sampai ke darat, tiba-tiba mereka (kembali) mempersekutukan (Allah)", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 66, "text": "لِیَكۡفُرُوا۟ بِمَاۤ ءَاتَیۡنَـٰهُمۡ وَلِیَتَمَتَّعُوا۟ۚ فَسَوۡفَ یَعۡلَمُونَ ۝٦٦", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "فإذا ركب الكفار السفن في البحر، وخافوا الغرق، وحَّدوا الله، وأخلصوا له في الدعاء حال شدتهم، فلما نجَّاهم إلى البر، وزالت عنهم الشدة، عادوا إلى شركهم، إنهم بهذا يتناقضون، يوحِّدون الله ساعة الشدة، ويشركون به ساعة الرخاء. وشِرْكهم بعد نعمتنا عليهم بالنجاة من البحر؛ ليكونَ عاقبته الكفر بما أنعمنا عليهم في أنفسهم وأموالهم، وليكملوا تمتعهم في هذه الدنيا، فسوف يعلمون فساد عملهم، وما أعدَّه الله لهم من عذاب أليم يوم القيامة. وفي ذلك تهديد ووعيد لهم.", "isBasmala": false, "translation_en": "To be ungrateful for what We have given them, and to enjoy themselves. They will surely come to know.", "translation_id": "agar mereka mengingkari nikmat yang telah Kami berikan kepada mereka dan agar mereka (hidup) bersenang-senang (dalam kekafiran). Kelak mereka akan mengetahui (akibat perbuatannya).", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 67, "text": "أَوَ لَمۡ یَرَوۡا۟ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنࣰا وَیُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَـٰطِلِ یُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ یَكۡفُرُونَ ۝٦٧", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "أولم يشاهد كفار \"مكة\" أن الله جعل \"مكة\" لهم حَرَمًا آمنًا يأمن فيه أهله على أنفسهم وأموالهم، والناسُ مِن حولهم خارج الحرم، يُتَخَطَّفون غير آمنين؟ أفبالشرك يؤمنون، وبنعمة الله التي خصَّهم بها يكفرون، فلا يعبدونه وحده دون سواه؟", "isBasmala": false, "translation_en": "Do they not see that We established a Secure Sanctuary, while all around them the people are being carried away? Do they believe in falsehood, and reject the blessings of God?", "translation_id": "Dan apakah mereka tidak memperhatikan, bahwa sesungguhnya Kami telah menjadikan (negeri mereka) tanah suci yang aman, sedang manusia sekitarnya rampok-merampok. Maka mengapa (sesudah nyata kebenaran) mereka masih percaya kepada yang bathil dan ingkar kepada nikmat Allah?", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 68, "text": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِٱلۡحَقِّ لَمَّا جَاۤءَهُۥۤۚ أَلَیۡسَ فِی جَهَنَّمَ مَثۡوࣰى لِّلۡكَـٰفِرِینَ ۝٦٨", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "لا أحد أشد ظلمًا ممن كذَب على الله، فنسب ما هو عليه من الضلال والباطل إلى الله، أو كذَّب بالحق الذي بعث الله به رسوله محمدًا صلى الله عليه وسلم، إن في النار لمسكنًا لمن كفر بالله، وجحد توحيده وكذَّب رسوله محمدًا صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "And who does greater wrong than he who fabricates lies and attributes them to God, or calls the truth a lie when it has come to him? Is there not in Hell a dwelling for the blasphemers?", "translation_id": "Dan siapakah yang lebih zalim daripada orang-orang yang mengada-adakan kedustaan terhadap Allah atau mendustakan yang hak tatkala yang hak itu datang kepadanya? Bukankah dalam neraka Jahannam itu ada tempat bagi orang-orang yang kafir?", "manzil": 5, "manzil_display": ""}, {"sura": 29, "sura_name": "العنكبوت", "revelation": "Makkiyah", "aya": 69, "text": "وَٱلَّذِینَ جَـٰهَدُوا۟ فِینَا لَنَهۡدِیَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِینَ ۝٦٩", "juz": 21, "hizb": "(* ح 41*)", "tafsir": "والمؤمنون الذين جاهدوا أعداء الله، والنفس، والشيطان، وصبروا على الفتن والأذى في سبيل الله، سيهديهم الله سبل الخير، ويثبتهم على الصراط المستقيم، ومَن هذه صفته فهو محسن إلى نفسه وإلى غيره. وإن الله سبحانه وتعالى لمع مَن أحسن مِن خَلْقِه بالنصرة والتأييد والحفظ والهداية.", "isBasmala": false, "translation_en": "As for those who strive for Us-We will guide them in Our ways. God is with the doers of good.", "translation_id": "Dan orang-orang yang berjihad untuk (mencari keridhaan) Kami, benar-benar akan Kami tunjukkan kepada mereka jalan-jalan Kami. Dan sesungguhnya Allah benar-benar beserta orang-orang yang berbuat baik.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 21, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 1, "text": "۞ الۤمۤ ۝١", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "(الم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Meem.", "translation_id": "Alif Laam Miim", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 2, "text": "غُلِبَتِ ٱلرُّومُ ۝٢", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "غَلَبت فارسُ الرومَ في أدنى أرض \"الشام\" إلى \"فارس\"، وسوف يَغْلِب الرومُ الفرسَ في مدة من الزمن، لا تزيد على عشر سنوات ولا تنقص عن ثلاث. لله سبحانه وتعالى الأمر كله قبل انتصار الروم وبعده، ويوم ينتصر الروم على الفرس يفرح المؤمنون بنصر الله للروم على الفرس. والله سبحانه وتعالى ينصر من يشاء، ويخذل من يشاء، وهو العزيز الذي لا يغالَب، الرحيم بمن شاء من خلقه. وقد تحقق ذلك فغَلَبَت الرومُ الفرسَ بعد سبع سنين، وفرح المسلمون بذلك؛ لكون الروم أهل كتاب وإن حرَّفوه.", "isBasmala": false, "translation_en": "The Romans have been defeated.", "translation_id": "Telah dikalahkan bangsa Rumawi,", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 3, "text": "فِیۤ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَیَغۡلِبُونَ ۝٣", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "غَلَبت فارسُ الرومَ في أدنى أرض \"الشام\" إلى \"فارس\"، وسوف يَغْلِب الرومُ الفرسَ في مدة من الزمن، لا تزيد على عشر سنوات ولا تنقص عن ثلاث. لله سبحانه وتعالى الأمر كله قبل انتصار الروم وبعده، ويوم ينتصر الروم على الفرس يفرح المؤمنون بنصر الله للروم على الفرس. والله سبحانه وتعالى ينصر من يشاء، ويخذل من يشاء، وهو العزيز الذي لا يغالَب، الرحيم بمن شاء من خلقه. وقد تحقق ذلك فغَلَبَت الرومُ الفرسَ بعد سبع سنين، وفرح المسلمون بذلك؛ لكون الروم أهل كتاب وإن حرَّفوه.", "isBasmala": false, "translation_en": "In a nearby territory. But following their defeat, they will be victorious.", "translation_id": "di negeri yang terdekat dan mereka sesudah dikalahkan itu akan menang", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 4, "text": "فِی بِضۡعِ سِنِینَۗ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ وَیَوۡمَىِٕذࣲ یَفۡرَحُ ٱلۡمُؤۡمِنُونَ ۝٤", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "غَلَبت فارسُ الرومَ في أدنى أرض \"الشام\" إلى \"فارس\"، وسوف يَغْلِب الرومُ الفرسَ في مدة من الزمن، لا تزيد على عشر سنوات ولا تنقص عن ثلاث. لله سبحانه وتعالى الأمر كله قبل انتصار الروم وبعده، ويوم ينتصر الروم على الفرس يفرح المؤمنون بنصر الله للروم على الفرس. والله سبحانه وتعالى ينصر من يشاء، ويخذل من يشاء، وهو العزيز الذي لا يغالَب، الرحيم بمن شاء من خلقه. وقد تحقق ذلك فغَلَبَت الرومُ الفرسَ بعد سبع سنين، وفرح المسلمون بذلك؛ لكون الروم أهل كتاب وإن حرَّفوه.", "isBasmala": false, "translation_en": "In a few years. The matter is up to God, in the past, and in the future. On that day, the believers will rejoice.", "translation_id": "dalam beberapa tahun lagi. Bagi Allah-lah urusan sebelum dan sesudah (mereka menang). Dan di hari (kemenangan bangsa Rumawi) itu bergembiralah orang-orang yang beriman,", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 5, "text": "بِنَصۡرِ ٱللَّهِۚ یَنصُرُ مَن یَشَاۤءُۖ وَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝٥", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "غَلَبت فارسُ الرومَ في أدنى أرض \"الشام\" إلى \"فارس\"، وسوف يَغْلِب الرومُ الفرسَ في مدة من الزمن، لا تزيد على عشر سنوات ولا تنقص عن ثلاث. لله سبحانه وتعالى الأمر كله قبل انتصار الروم وبعده، ويوم ينتصر الروم على الفرس يفرح المؤمنون بنصر الله للروم على الفرس. والله سبحانه وتعالى ينصر من يشاء، ويخذل من يشاء، وهو العزيز الذي لا يغالَب، الرحيم بمن شاء من خلقه. وقد تحقق ذلك فغَلَبَت الرومُ الفرسَ بعد سبع سنين، وفرح المسلمون بذلك؛ لكون الروم أهل كتاب وإن حرَّفوه.", "isBasmala": false, "translation_en": "In God's support. He supports whomever He wills. He is the Almighty, the Merciful.", "translation_id": "Karena pertolongan Allah. Dia menolong siapa yang dikehendaki-Nya. Dan Dialah Maha Perkasa lagi Penyayang.", "manzil": 5, "manzil_display": ""}], "405": [{"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 6, "text": "وَعۡدَ ٱللَّهِۖ لَا یُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٦", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "وعد الله المؤمنين وعدًا جازمًا لا يتخلف، بنصر الروم النصارى على الفرس الوثنيين، ولكن أكثر كفار \"مكة\" لا يعلمون أن ما وعد الله به حق، وإنما يعلمون ظواهر الدنيا وزخرفها، وهم عن أمور الآخرة وما ينفعهم فيها غافلون، لا يفكرون فيها.", "isBasmala": false, "translation_en": "The promise of God-God never breaks His promise, but most people do not know.", "translation_id": "(Sebagai) janji yang sebenarnya dari Allah. Allah tidak akan menyalahi janji-Nya, tetapi kebanyakan manusia tidak mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 7, "text": "یَعۡلَمُونَ ظَـٰهِرࣰا مِّنَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَهُمۡ عَنِ ٱلۡـَٔاخِرَةِ هُمۡ غَـٰفِلُونَ ۝٧", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "وعد الله المؤمنين وعدًا جازمًا لا يتخلف، بنصر الروم النصارى على الفرس الوثنيين، ولكن أكثر كفار \"مكة\" لا يعلمون أن ما وعد الله به حق، وإنما يعلمون ظواهر الدنيا وزخرفها، وهم عن أمور الآخرة وما ينفعهم فيها غافلون، لا يفكرون فيها.", "isBasmala": false, "translation_en": "They know an outer aspect of the worldly life, but they are heedless of the Hereafter.", "translation_id": "Mereka hanya mengetahui yang lahir (saja) dari kehidupan dunia; sedang mereka tentang (kehidupan) akhirat adalah lalai.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 8, "text": "أَوَ لَمۡ یَتَفَكَّرُوا۟ فِیۤ أَنفُسِهِمۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَاۤ إِلَّا بِٱلۡحَقِّ وَأَجَلࣲ مُّسَمࣰّىۗ وَإِنَّ كَثِیرࣰا مِّنَ ٱلنَّاسِ بِلِقَاۤىِٕ رَبِّهِمۡ لَكَـٰفِرُونَ ۝٨", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "أولم يتفكر هؤلاء المكذِّبون برسل الله ولقائه في خلق الله إياهم، وأنه خلقهم، ولم يكونوا شيئًا. ما خلق الله السموات والأرض وما بينهما إلا لإقامة العدل والثواب والعقاب، والدلالة على توحيده وقدرته، وأجل مسمى تنتهي إليه وهو يوم القيامة؟ وإن كثيرًا من الناس بلقاء ربهم لجاحدون منكرون؛ جهلا منهم بأن معادهم إلى الله بعد فنائهم، وغفلةً منهم عن الآخرة.", "isBasmala": false, "translation_en": "Do they not reflect within themselves? God did not create the heavens and the earth, and what is between them, except with reason, and for a specific duration. But most people, regarding meeting their Lord, are disbelievers.", "translation_id": "Dan mengapa mereka tidak memikirkan tentang (kejadian) diri mereka? Allah tidak menjadikan langit dan bumi dan apa yang ada diantara keduanya melainkan dengan (tujuan) yang benar dan waktu yang ditentukan. Dan sesungguhnya kebanyakan di antara manusia benar-benar ingkar akan pertemuan dengan Tuhannya.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 9, "text": "أَوَ لَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَانُوۤا۟ أَشَدَّ مِنۡهُمۡ قُوَّةࣰ وَأَثَارُوا۟ ٱلۡأَرۡضَ وَعَمَرُوهَاۤ أَكۡثَرَ مِمَّا عَمَرُوهَا وَجَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِۖ فَمَا كَانَ ٱللَّهُ لِیَظۡلِمَهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ ۝٩", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "أولم يَسِرْ هؤلاء المكذبون بالله الغافلون عن الآخرة في الأرض سَيْرَ تأمل واعتبار، فيشاهدوا كيف كان جزاء الأمم الذين كذَّبوا برسل الله كعاد وثمود؟ وقد كانوا أقوى منهم أجسامًا، وأقدر على التمتع بالحياة حيث حرثوا الأرض وزرعوها، وبنَوْا القصور وسكنوها، فعَمَروا دنياهم أكثر مما عَمَر أهل \"مكة\" دنياهم، فلم تنفعهم عِمارتهم ولا طول مدتهم، وجاءتهم رسلهم بالحجج الظاهرة والبراهين الساطعة، فكذَّبوهم فأهلكهم الله، ولم يظلمهم الله بذلك الإهلاك، وإنما ظلموا أنفسهم بالشرك والعصيان.", "isBasmala": false, "translation_en": "Have they not travelled the earth and seen how those before them ended up? They were more powerful than them, and they cultivated the land and developed it more than they developed it, and their messengers came to them with clear signs. God would never wrong them, but they used to wrong themselves.", "translation_id": "Dan apakah mereka tidak mengadakan perjalanan di muka bumi dan memperhatikan bagaimana akibat (yang diderita) oleh orang-orang sebelum mereka? orang-orang itu adalah lebihkuat dari mereka (sendiri) dan telah mengolah bumi (tanah) serta memakmurkannya lebih banyak dari apa yang telah mereka makmurkan. Dan telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti yang nyata. Maka Allah sekali-kali tidak berlaku zalim kepada mereka, akan tetapi merekalah yang berlaku zalim kepada diri sendiri.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 10, "text": "ثُمَّ كَانَ عَـٰقِبَةَ ٱلَّذِینَ أَسَـٰۤـُٔوا۟ ٱلسُّوۤأَىٰۤ أَن كَذَّبُوا۟ بِـَٔایَـٰتِ ٱللَّهِ وَكَانُوا۟ بِهَا یَسۡتَهۡزِءُونَ ۝١٠", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ثم كانت عاقبة أهل السوء من الطغاة والكفرة أسوأ العواقب وأقبحها؛ لتكذيبهم بالله وسخريتهم بآياته التي أنزلها على رسله.", "isBasmala": false, "translation_en": "Then, evil was the end of those who committed evil. That is because they rejected God's revelations, and used to ridicule them.", "translation_id": "Kemudian, akibat orang-orang yang mengerjakan kejahatan adalah (azab) yang lebih buruk, karena mereka mendustakan ayat-ayat Allah dan mereka selalu memperolok-oloknya.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 11, "text": "ٱللَّهُ یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ ثُمَّ إِلَیۡهِ تُرۡجَعُونَ ۝١١", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "الله وحده هو المتفرد بإنشاء المخلوقات كلها، وهو القادر وحده على إعادتها مرة أخرى، ثم إليه يرجع جميع الخلق، فيجازي المحسن بإحسانه والمسيء بإساءته.", "isBasmala": false, "translation_en": "God originates creation, and then repeats it. Then to Him you will be returned.", "translation_id": "Allah menciptakan (manusia) dari permulaan, kemudian mengembalikan (menghidupkan)nya kembali; kemudian kepada-Nya-lah kamu dikembalikan", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 12, "text": "وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یُبۡلِسُ ٱلۡمُجۡرِمُونَ ۝١٢", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ويوم تقوم الساعة ييئس المجرمون من النجاة من العذاب، وتصيبهم الحَيْرة فتنقطع حجتهم.", "isBasmala": false, "translation_en": "On the Day when the Hour takes place, the guilty will despair.", "translation_id": "Dan pada hari terjadinya kiamat, orang-orang yang berdosa terdiam berputus asa.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 13, "text": "وَلَمۡ یَكُن لَّهُم مِّن شُرَكَاۤىِٕهِمۡ شُفَعَـٰۤؤُا۟ وَكَانُوا۟ بِشُرَكَاۤىِٕهِمۡ كَـٰفِرِینَ ۝١٣", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ولم يكن للمشركين في ذلك اليوم من آلهتهم التي كانوا يعبدونها من دون الله شفعاء، بل إنها تتبرأ منهم، ويتبرؤون منها. فالشفاعة لله وحده، ولا تُطلَب من غيره.", "isBasmala": false, "translation_en": "They will have no intercessors from among their idols, and they will disown their partners.", "translation_id": "Dan sekali-kali tidak ada pemberi syafa'at bagi mereka dari berhala-berhala mereka dan adalah mereka mengingkari berhala mereka itu.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 14, "text": "وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یَوۡمَىِٕذࣲ یَتَفَرَّقُونَ ۝١٤", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ويوم تقوم الساعة يفترق أهل الإيمان به وأهل الكفر، فأما المؤمنون بالله ورسوله، العاملون الصالحات فهم في الجنة، يكرَّمون ويسرُّون وينعَّمون.", "isBasmala": false, "translation_en": "On the Day when the Hour takes place-on that Day they will separate.", "translation_id": "Dan pada hari terjadinya kiamat, di hari itu mereka (manusia) bergolong-golongan.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 15, "text": "فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَهُمۡ فِی رَوۡضَةࣲ یُحۡبَرُونَ ۝١٥", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ويوم تقوم الساعة يفترق أهل الإيمان به وأهل الكفر، فأما المؤمنون بالله ورسوله، العاملون الصالحات فهم في الجنة، يكرَّمون ويسرُّون وينعَّمون.", "isBasmala": false, "translation_en": "As for those who believed and did good deeds-they will be delighted in meadows.", "translation_id": "Adapun orang-orang yang beriman dan mengerjakan amal saleh, maka mereka di dalam taman (surga) bergembira.", "manzil": 5, "manzil_display": ""}], "406": [{"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 16, "text": "وَأَمَّا ٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَا وَلِقَاۤىِٕ ٱلۡـَٔاخِرَةِ فَأُو۟لَـٰۤىِٕكَ فِی ٱلۡعَذَابِ مُحۡضَرُونَ ۝١٦", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "وأما الذين كفروا بالله وكذَّبوا بما جاءت به الرسل وأنكروا البعث بعد الموت، فأولئك في العذاب مقيمون؛ جزاء ما كذَّبوا به في الدنيا.", "isBasmala": false, "translation_en": "But as for those who disbelieved, and rejected Our signs and the encounter of the Hereafter-those will be hauled into the torment.", "translation_id": "Adapun orang-orang yang kafir dan mendustakan ayat-ayat Kami (Al Quran) serta (mendustakan) menemui hari akhirat, maka mereka tetap berada di dalam siksaan (neraka).", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 17, "text": "فَسُبۡحَـٰنَ ٱللَّهِ حِینَ تُمۡسُونَ وَحِینَ تُصۡبِحُونَ ۝١٧", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "فيا أيها المؤمنون سبِّحوا الله ونزِّهوه عن الشريك والصاحبة والولد، وَصِفوه بصفات الكمال بألسنتكم، وحقِّقوا ذلك بجوارحكم كلها حين تمسون، وحين تصبحون، ووقت العشي، ووقت الظهيرة. وله -سبحانه- الحمد والثناء في السموات والأرض وفي الليل والنهار.", "isBasmala": false, "translation_en": "So glorify God when you retire at night, and when you rise in the morning.", "translation_id": "Maka bertasbihlah kepada Allah di waktu kamu berada di petang hari dan waktu kamu berada di waktu subuh,", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 18, "text": "وَلَهُ ٱلۡحَمۡدُ فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَعَشِیࣰّا وَحِینَ تُظۡهِرُونَ ۝١٨", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "فيا أيها المؤمنون سبِّحوا الله ونزِّهوه عن الشريك والصاحبة والولد، وَصِفوه بصفات الكمال بألسنتكم، وحقِّقوا ذلك بجوارحكم كلها حين تمسون، وحين تصبحون، ووقت العشي، ووقت الظهيرة. وله -سبحانه- الحمد والثناء في السموات والأرض وفي الليل والنهار.", "isBasmala": false, "translation_en": "His is the praise in the heavens and on earth, and in the evening, and when you reach midday.", "translation_id": "dan bagi-Nya-lah segala puji di langit dan di bumi dan di waktu kamu berada pada petang hari dan di waktu kamu berada di waktu Zuhur.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 19, "text": "یُخۡرِجُ ٱلۡحَیَّ مِنَ ٱلۡمَیِّتِ وَیُخۡرِجُ ٱلۡمَیِّتَ مِنَ ٱلۡحَیِّ وَیُحۡیِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ وَكَذَ ٰلِكَ تُخۡرَجُونَ ۝١٩", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "يخرج الله الحي من الميت كالإنسان من النطفة والطير من البيضة، ويخرج الميت من الحي، كالنطفة من الإنسان والبيضة من الطير. ويحيي الأرض بالنبات بعد يُبْسها وجفافها، ومثل هذا الإحياء تخرجون -أيها الناس- من قبوركم أحياء للحساب والجزاء.", "isBasmala": false, "translation_en": "He brings the living out of the dead, and He brings the dead out of the living, and He revives the land after it had died. Likewise you will be resurrected.", "translation_id": "Dia mengeluarkan yang hidup dari yang mati dan mengeluarkan yang mati dari yang hidup dan menghidupkan bumi sesudah matinya. Dan seperti itulah kamu akan dikeluarkan (dari kubur).", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 20, "text": "وَمِنۡ ءَایَـٰتِهِۦۤ أَنۡ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ إِذَاۤ أَنتُم بَشَرࣱ تَنتَشِرُونَ ۝٢٠", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ومن آيات الله الدالة على عظمته وكمال قدرته أن خلق أباكم آدم من تراب، ثم أنتم بشر تتناسلون منتشرين في الأرض، تبتغون من فضل الله.", "isBasmala": false, "translation_en": "And of His signs is that He created you from dust; and behold, you become humans spreading out.", "translation_id": "Dan di antara tanda-tanda kekuasaan-Nya ialah Dia menciptakan kamu dari tanah, kemudian tiba-tiba kamu (menjadi) manusia yang berkembang biak.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 21, "text": "وَمِنۡ ءَایَـٰتِهِۦۤ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَ ٰجࣰا لِّتَسۡكُنُوۤا۟ إِلَیۡهَا وَجَعَلَ بَیۡنَكُم مَّوَدَّةࣰ وَرَحۡمَةًۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَفَكَّرُونَ ۝٢١", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ومن آياته الدالة على عظمته وكمال قدرته أن خلق لأجلكم من جنسكم -أيها الرجال- أزواجًا؛ لتطمئن نفوسكم إليها وتسكن، وجعل بين المرأة وزوجها محبة وشفقة، إن في خلق الله ذلك لآيات دالة على قدرة الله ووحدانيته لقوم يتفكرون، ويتدبرون.", "isBasmala": false, "translation_en": "And of His signs is that He created for you mates from among yourselves, so that you may find tranquility in them; and He planted love and compassion between you. In this are signs for people who reflect.", "translation_id": "Dan di antara tanda-tanda kekuasaan-Nya ialah Dia menciptakan untukmu isteri-isteri dari jenismu sendiri, supaya kamu cenderung dan merasa tenteram kepadanya, dan dijadikan-Nya diantaramu rasa kasih dan sayang. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda bagi kaum yang berfikir.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 22, "text": "وَمِنۡ ءَایَـٰتِهِۦ خَلۡقُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَـٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَ ٰنِكُمۡۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّلۡعَـٰلِمِینَ ۝٢٢", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ومن دلائل القدرة الربانية: خَلْقُ السموات وارتفاعها بغير عمد، وخَلْقُ الأرض مع اتساعها وامتدادها، واختلافُ لغاتكم وتباينُ ألوانكم، إن في هذا لَعبرة لكل ذي علم وبصيرة.", "isBasmala": false, "translation_en": "And of His signs is the creation of the heavens and the earth, and the diversity of your languages and colors. In this are signs for those who know.", "translation_id": "Dan di antara tanda-tanda kekuasaan-Nya ialah menciptakan langit dan bumi dan berlain-lainan bahasamu dan warna kulitmu. Sesungguhnya pada yang demikan itu benar-benar terdapat tanda-tanda bagi orang-orang yang mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 23, "text": "وَمِنۡ ءَایَـٰتِهِۦ مَنَامُكُم بِٱلَّیۡلِ وَٱلنَّهَارِ وَٱبۡتِغَاۤؤُكُم مِّن فَضۡلِهِۦۤۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَسۡمَعُونَ ۝٢٣", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ومن دلائل هذه القدرة أن جعل الله النوم راحة لكم في الليل أو النهار؛ إذ في النوم حصول الراحة وذهاب التعب، وجعل لكم النهار تنتشرون فيه لطلب الرزق، إن في ذلك لدلائل على كمال قدرة الله ونفوذ مشيئته لقوم يسمعون المواعظ سماع تأمل وتفكر واعتبار.", "isBasmala": false, "translation_en": "And of His signs are your sleep by night and day, and your pursuit of His bounty. In this are signs for people who listen.", "translation_id": "Dan di antara tanda-tanda kekuasaan-Nya ialah tidurmu di waktu malam dan siang hari dan usahamu mencari sebagian dari karunia-Nya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda bagi kaum yang mendengarkan.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 24, "text": "وَمِنۡ ءَایَـٰتِهِۦ یُرِیكُمُ ٱلۡبَرۡقَ خَوۡفࣰا وَطَمَعࣰا وَیُنَزِّلُ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَیُحۡیِۦ بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۤۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَعۡقِلُونَ ۝٢٤", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ومن دلائل قدرته سبحانه أن يريكم البرق، فتخافون من الصواعق، وتطمعون في الغيث، وينزل من السحاب مطرًا فيحيي به الأرض بعد جدبها وجفافها، إن في هذا لدليلا على كمال قدرة الله وعظيم حكمته وإحسانه لكل مَن لديه عقل يهتدي به.", "isBasmala": false, "translation_en": "And of His signs is that He shows you the lightning, causing fear and hope. And He brings down water from the sky, and with it He revives the earth after it was dead. In this are signs for people who understand.", "translation_id": "Dan di antara tanda-tanda kekuasaan-Nya, Dia memperlihatkan kepadamu kilat untuk (menimbulkan) ketakutan dan harapan, dan Dia menurunkan hujan dari langit, lalu menghidupkan bumi dengan air itu sesudah matinya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda bagi kaum yang mempergunakan akalnya.", "manzil": 5, "manzil_display": ""}], "407": [{"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 25, "text": "وَمِنۡ ءَایَـٰتِهِۦۤ أَن تَقُومَ ٱلسَّمَاۤءُ وَٱلۡأَرۡضُ بِأَمۡرِهِۦۚ ثُمَّ إِذَا دَعَاكُمۡ دَعۡوَةࣰ مِّنَ ٱلۡأَرۡضِ إِذَاۤ أَنتُمۡ تَخۡرُجُونَ ۝٢٥", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ومن آياته الدالة على قدرته قيام السماء والأرض واستقرارهما وثباتهما بأمره، فلم تتزلزلا ولم تسقط السماء على الأرض، ثم إذا دعاكم الله إلى البعث يوم القيامة، إذا أنتم تخرجون من القبور مسرعين.", "isBasmala": false, "translation_en": "And of His signs is that the heaven and the earth stand at His disposal. And then, when He calls you out of the earth, you will emerge at once.", "translation_id": "Dan di antara tanda-tanda kekuasaan-Nya ialah berdirinya langit dan bumi dengan iradat-Nya. Kemudian apabila Dia memanggil kamu sekali panggil dari bumi, seketika itu (juga) kamu keluar (dari kubur).", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 26, "text": "وَلَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ كُلࣱّ لَّهُۥ قَـٰنِتُونَ ۝٢٦", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ولله وحده كل مَن في السموات والأرض من الملائكة والإنس والجن والحيوان والنبات والجماد، كل هؤلاء منقادون لأمره خاضعون لكماله.", "isBasmala": false, "translation_en": "To Him belongs everyone in the heavens and the earth. All are submissive to Him.", "translation_id": "Dan kepunyaan-Nya-lah siapa saja yang ada di langit dan di bumi. Semuanya hanya kepada-Nya tunduk.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 27, "text": "وَهُوَ ٱلَّذِی یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ وَهُوَ أَهۡوَنُ عَلَیۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٢٧", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "والله وحده الذي يبدأ الخلق من العدم ثم يعيده حيًا بعد الموت، وإعادة الخلق حيًا بعد الموت أهون على الله من ابتداء خلقهم، وكلاهما عليه هيِّن. وله سبحانه الوصف الأعلى في كل ما يوصف به، ليس كمثله شيء، وهو السميع البصير. وهو العزيز الذي لا يغالَب، الحكيم في أقواله وأفعاله، وتدبير أمور خلقه.", "isBasmala": false, "translation_en": "It is He who initiates creation, and then repeats it, something easy for Him. His is the highest attribute, in the heavens and the earth. He is the Almighty, the Wise.", "translation_id": "Dan Dialah yang menciptakan (manusia) dari permulaan, kemudian mengembalikan (menghidupkan)nya kembali, dan menghidupkan kembali itu adalah lebih mudah bagi-Nya. Dan bagi-Nya-lah sifat yang Maha Tinggi di langit dan di bumi; dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 28, "text": "ضَرَبَ لَكُم مَّثَلࣰا مِّنۡ أَنفُسِكُمۡۖ هَل لَّكُم مِّن مَّا مَلَكَتۡ أَیۡمَـٰنُكُم مِّن شُرَكَاۤءَ فِی مَا رَزَقۡنَـٰكُمۡ فَأَنتُمۡ فِیهِ سَوَاۤءࣱ تَخَافُونَهُمۡ كَخِیفَتِكُمۡ أَنفُسَكُمۡۚ كَذَ ٰلِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡقِلُونَ ۝٢٨", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "ضرب الله مثلا لكم -أيها المشركون -من أنفسكم: هل لكم من عبيدكم وإمائكم مَن يشارككم في رزقكم، وترون أنكم وإياهم متساوون فيه، تخافونهم كما تخافون الأحرار الشركاء في مقاسمة أموالكم؟ إنكم لن ترضوا بذلك، فكيف ترضون بذلك في جنب الله بأن تجعلوا له شريكًا من خلقه؟ وبمثل هذا البيان نبيِّن البراهين والحجج لأصحاب العقول السليمة الذين ينتفعون بها.", "isBasmala": false, "translation_en": "He illustrates an example for you, from your own selves: do you make your servants full partners in the wealth We have given you? Do you revere them as you revere one another? We thus explain the revelations for a people who understand.", "translation_id": "Dia membuat perumpamaan untuk kamu dari dirimu sendiri. Apakah ada diantara hamba-sahaya yang dimiliki oleh tangan kananmu, sekutu bagimu dalam (memiliki) rezeki yang telah Kami berikan kepadamu; maka kamu sama dengan mereka dalam (hak mempergunakan) rezeki itu, kamu takut kepada mereka sebagaimana kamu takut kepada dirimu sendiri? Demikianlah Kami jelaskan ayat-ayat bagi kaum yang berakal.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 29, "text": "بَلِ ٱتَّبَعَ ٱلَّذِینَ ظَلَمُوۤا۟ أَهۡوَاۤءَهُم بِغَیۡرِ عِلۡمࣲۖ فَمَن یَهۡدِی مَنۡ أَضَلَّ ٱللَّهُۖ وَمَا لَهُم مِّن نَّـٰصِرِینَ ۝٢٩", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "بل اتبع المشركون أهواءهم بتقليد آبائهم بغير علم، فشاركوهم في الجهل والضلالة، ولا أحد يقدر على هداية مَن أضلَّه الله بسبب تماديه في الكفر والعناد، وليس لهؤلاء مِن أنصار يُخَلِّصونهم من عذاب الله.", "isBasmala": false, "translation_en": "Yet the wrongdoers follow their desires without knowledge. But who can guide whom God leaves astray? They will have no helpers.", "translation_id": "Tetapi orang-orang yang zalim, mengikuti hawa nafsunya tanpa ilmu pengetahuan; maka siapakah yang akan menunjuki orang yang telah disesatkan Allah? Dan tiadalah bagi mereka seorang penolongpun.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 30, "text": "فَأَقِمۡ وَجۡهَكَ لِلدِّینِ حَنِیفࣰاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِی فَطَرَ ٱلنَّاسَ عَلَیۡهَاۚ لَا تَبۡدِیلَ لِخَلۡقِ ٱللَّهِۚ ذَ ٰلِكَ ٱلدِّینُ ٱلۡقَیِّمُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٣٠", "juz": 21, "hizb": "(*¼ ح 41*)", "tafsir": "فأقم -أيها الرسول أنت ومن اتبعك- وجهك، واستمر على الدين الذي شرعه الله لك، وهو الإسلام الذي فطر الله الناس عليه، فبقاؤكم عليه، وتمسككم به، تمسك بفطرة الله من الإيمان بالله وحده، لا تبديل لخلق الله ودينه، فهو الطريق المستقيم الموصل إلى رضا الله رب العالمين وجنته، ولكن أكثر الناس لا يعلمون أن الذي أمرتك به -أيها الرسول- هو الدين الحق دون سواه.", "isBasmala": false, "translation_en": "So devote yourself to the religion of monotheism-the natural instinct God has instilled in mankind. There is no altering God's creation. This is the true religion, but most people do not know.", "translation_id": "Maka hadapkanlah wajahmu dengan lurus kepada agama Allah; (tetaplah atas) fitrah Allah yang telah menciptakan manusia menurut fitrah itu. Tidak ada peubahan pada fitrah Allah. (Itulah) agama yang lurus; tetapi kebanyakan manusia tidak mengetahui,", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 31, "text": "۞ مُنِیبِینَ إِلَیۡهِ وَٱتَّقُوهُ وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلۡمُشۡرِكِینَ ۝٣١", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "وكونوا راجعين إلى الله بالتوبة وإخلاص العمل له، واتقوه بفعل الأوامر واجتناب النواهي، وأقيموا الصلاة تامة بأركانها وواجباتها وشروطها، ولا تكونوا من المشركين مع الله غيره في العبادة.", "isBasmala": false, "translation_en": "Turning towards Him-and be conscious of Him, and perform the prayer, and do not be of the idolaters.", "translation_id": "dengan kembali bertaubat kepada-Nya dan bertakwalah kepada-Nya serta dirikanlah shalat dan janganlah kamu termasuk orang-orang yang mempersekutukan Allah,", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 32, "text": "مِنَ ٱلَّذِینَ فَرَّقُوا۟ دِینَهُمۡ وَكَانُوا۟ شِیَعࣰاۖ كُلُّ حِزۡبِۭ بِمَا لَدَیۡهِمۡ فَرِحُونَ ۝٣٢", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "ولا تكونوا من المشركين وأهل الأهواء والبدع الذين بدَّلوا دينهم، وغيَّروه، فأخذوا بعضه، وتركوا بعضه؛ تبعًا لأهوائهم، فصاروا فرقًا وأحزابًا، يتشيعون لرؤسائهم وأحزابهم وآرائهم، يعين بعضهم بعضًا على الباطل، كل حزب بما لديهم فرحون مسرورون، يحكمون لأنفسهم بأنهم على الحق وغيرهم على الباطل.", "isBasmala": false, "translation_en": "Of those who divided their religion, and became sects; each faction pleased with what they have.", "translation_id": "yaitu orang-orang yang memecah-belah agama mereka dan mereka menjadi beberapa golongan. Tiap-tiap golongan merasa bangga dengan apa yang ada pada golongan mereka.", "manzil": 5, "manzil_display": ""}], "408": [{"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 33, "text": "وَإِذَا مَسَّ ٱلنَّاسَ ضُرࣱّ دَعَوۡا۟ رَبَّهُم مُّنِیبِینَ إِلَیۡهِ ثُمَّ إِذَاۤ أَذَاقَهُم مِّنۡهُ رَحۡمَةً إِذَا فَرِیقࣱ مِّنۡهُم بِرَبِّهِمۡ یُشۡرِكُونَ ۝٣٣", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "وإذا أصاب الناسَ شدة وبلاء دعَوا ربهم مخلصين له أن يكشف عنهم الضر، فإذا رحمهم وكشف عنهم ضرهم إذا فريق منهم يعودون إلى الشرك مرة أخرى، فيعبدون مع الله غيره.", "isBasmala": false, "translation_en": "When affliction touches the people, they call on their Lord, turning to Him in repentance. But then, when He gives them a taste of His mercy, some of them attribute partners to their Lord.", "translation_id": "Dan apabila manusia disentuh oleh suatu bahaya, mereka menyeru Tuhannya dengan kembali bertaubat kepada-Nya, kemudian apabila Tuhan merasakan kepada mereka barang sedikit rahmat daripada-Nya, tiba-tiba sebagian dari mereka mempersekutukan Tuhannya,", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 34, "text": "لِیَكۡفُرُوا۟ بِمَاۤ ءَاتَیۡنَـٰهُمۡۚ فَتَمَتَّعُوا۟ فَسَوۡفَ تَعۡلَمُونَ ۝٣٤", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "ليكفروا بما آتيناهم ومننَّا به عليهم من كشف الضر، وزوال الشدة عنهم، فتمتعوا -أيها المشركون- بالرخاء والسَّعَة في هذه الدنيا، فسوف تعلمون ما تلقونه من العذاب والعقاب.", "isBasmala": false, "translation_en": "To show ingratitude for what We have given them. Indulge yourselves-you will surely know.", "translation_id": "sehingga mereka mengingkari akan rahmat yang telah Kami berikan kepada mereka. Maka bersenang-senanglah kamu sekalian, kelak kamu akan mengetahui (akibat perbuatanmu).", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 35, "text": "أَمۡ أَنزَلۡنَا عَلَیۡهِمۡ سُلۡطَـٰنࣰا فَهُوَ یَتَكَلَّمُ بِمَا كَانُوا۟ بِهِۦ یُشۡرِكُونَ ۝٣٥", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "أم أنزلنا على هؤلاء المشركين برهانًا ساطعًا وكتابًا قاطعًا، ينطق بصحة شركهم وكفرهم بالله وآياته.", "isBasmala": false, "translation_en": "Have We sent down to them any authority, which speaks in support of their idols?", "translation_id": "Atau pernahkah Kami menurunkan kepada mereka keterangan, lalu keterangan itu menunjukkan (kebenaran) apa yang mereka selalu mempersekutukan dengan Tuhan?", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 36, "text": "وَإِذَاۤ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةࣰ فَرِحُوا۟ بِهَاۖ وَإِن تُصِبۡهُمۡ سَیِّئَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ إِذَا هُمۡ یَقۡنَطُونَ ۝٣٦", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "وإذا أذقنا الناس منا نعمة مِن صحة وعافية ورخاء، فرحوا بذلك فرح بطرٍ وأَشَرٍ، لا فرح شكر، وإن يصبهم مرض وفقر وخوف وضيق بسبب ذنوبهم ومعاصيهم، إذا هم يَيْئَسون من زوال ذلك، وهذا طبيعة أكثر الناس في الرخاء والشدة.", "isBasmala": false, "translation_en": "When We give people a taste of mercy, they rejoice in it. But when adversity befalls them, because of what their hands have perpetrated, they begin to despair.", "translation_id": "Dan apabila Kami rasakan sesuatu rahmat kepada manusia, niscaya mereka gembira dengan rahmat itu. Dan apabila mereka ditimpa suatu musibah (bahaya) disebabkan kesalahan yang telah dikerjakan oleh tangan mereka sendiri, tiba-tiba mereka itu berputus asa.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 37, "text": "أَوَ لَمۡ یَرَوۡا۟ أَنَّ ٱللَّهَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝٣٧", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "أولم يعلموا أن الله يوسع الرزق لمن يشاء امتحانًا، هل يشكر أو يكفر؟ ويضيِّقه على من يشاء اختبارًا، هل يصبر أو يجزع؟ إن في ذلك التوسيع والتضييق لآيات لقوم يؤمنون بالله ويعرفون حكمة الله ورحمته.", "isBasmala": false, "translation_en": "Do they not see that God expands the provision for whomever He wills, or restricts it? Surely in this are signs for people who believe.", "translation_id": "Dan apakah mereka tidak memperhatikan bahwa Sesungguhnya Allah melapangkan rezeki bagi siapa yang dikehendaki-Nya dan Dia (pula) yang menyempitkan (rezeki itu). Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah) bagi kaum yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 38, "text": "فَـَٔاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِینَ وَٱبۡنَ ٱلسَّبِیلِۚ ذَ ٰلِكَ خَیۡرࣱ لِّلَّذِینَ یُرِیدُونَ وَجۡهَ ٱللَّهِۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝٣٨", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "فأعط -أيها المؤمن- قريبك حقه من الصلة والصدقة وسائر أعمال البر، وأعط الفقير والمحتاج الذي انقطع به السبيل من الزكاة والصدقة، ذلك الإعطاء خير للذين يريدون بعملهم وجه الله، والذين يعملون هذه الأعمال وغيرها من أعمال الخير، أولئك هم الفائزون بثواب الله الناجون مِن عقابه.", "isBasmala": false, "translation_en": "So give the relative his rights, and the destitute, and the wayfarer. That is best for those who seek God's presence. Those are the prosperous.", "translation_id": "Maka berikanlah kepada kerabat yang terdekat akan haknya, demikian (pula) kepada fakir miskin dan orang-orang yang dalam perjalanan. Itulah yang lebih baik bagi orang-orang yang mencari keridhaan Allah; dan mereka itulah orang-orang beruntung.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 39, "text": "وَمَاۤ ءَاتَیۡتُم مِّن رِّبࣰا لِّیَرۡبُوَا۟ فِیۤ أَمۡوَ ٰلِ ٱلنَّاسِ فَلَا یَرۡبُوا۟ عِندَ ٱللَّهِۖ وَمَاۤ ءَاتَیۡتُم مِّن زَكَوٰةࣲ تُرِیدُونَ وَجۡهَ ٱللَّهِ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُضۡعِفُونَ ۝٣٩", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "وما أعطيتم قرضًا من المال بقصد الربا، وطلب زيادة ذلك القرض؛ ليزيد وينمو في أموال الناس، فلا يزيد عند الله، بل يمحقه ويبطله. وما أعطيتم من زكاة وصدقة للمستحقين ابتغاء مرضاة الله وطلبًا لثوابه، فهذا هو الذي يقبله الله ويضاعفه لكم أضعافًا كثيرة.", "isBasmala": false, "translation_en": "The usury you practice, seeking thereby to multiply people's wealth, will not multiply with God. But what you give in charity, desiring God's approval-these are the multipliers.", "translation_id": "Dan sesuatu riba (tambahan) yang kamu berikan agar dia bertambah pada harta manusia, maka riba itu tidak menambah pada sisi Allah. Dan apa yang kamu berikan berupa zakat yang kamu maksudkan untuk mencapai keridhaan Allah, maka (yang berbuat demikian) itulah orang-orang yang melipat gandakan (pahalanya).", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 40, "text": "ٱللَّهُ ٱلَّذِی خَلَقَكُمۡ ثُمَّ رَزَقَكُمۡ ثُمَّ یُمِیتُكُمۡ ثُمَّ یُحۡیِیكُمۡۖ هَلۡ مِن شُرَكَاۤىِٕكُم مَّن یَفۡعَلُ مِن ذَ ٰلِكُم مِّن شَیۡءࣲۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ ۝٤٠", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "الله وحده هو الذي خلقكم -أيها الناس- ثم رزقكم في هذه الحياة، ثم يميتكم بانتهاء آجالكم، ثم يبعثكم من القبور أحياء للحساب والجزاء، هل من شركائكم مَن يفعل من ذلكم من شيء؟ تنزَّه الله وتقدَّس عن شرك هؤلاء المشركين به.", "isBasmala": false, "translation_en": "God is He who created you, then provides for you, then makes you die, then brings you back to life. Can any of your idols do any of that? Glorified is He, and Exalted above what they associate.", "translation_id": "Allah-lah yang menciptakan kamu, kemudian memberimu rezeki, kemudian mematikanmu, kemudian menghidupkanmu (kembali). Adakah di antara yang kamu sekutukan dengan Allah itu yang dapat berbuat sesuatu dari yang demikian itu? Maha Sucilah Dia dan Maha Tinggi dari apa yang mereka persekutukan.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 41, "text": "ظَهَرَ ٱلۡفَسَادُ فِی ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَیۡدِی ٱلنَّاسِ لِیُذِیقَهُم بَعۡضَ ٱلَّذِی عَمِلُوا۟ لَعَلَّهُمۡ یَرۡجِعُونَ ۝٤١", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "ظهر الفساد في البر والبحر، كالجدب وقلة الأمطار وكثرة الأمراض والأوبئة؛ وذلك بسبب المعاصي التي يقترفها البشر؛ ليصيبهم بعقوبة بعض أعمالهم التي عملوها في الدنيا؛ كي يتوبوا إلى الله -سبحانه- ويرجعوا عن المعاصي، فتصلح أحوالهم، وتستقيم أمورهم.", "isBasmala": false, "translation_en": "Corruption has appeared on land and sea, because of what people's hands have earned, in order to make them taste some of what they have done, so that they might return.", "translation_id": "Telah nampak kerusakan di darat dan di laut disebabkan karena perbuatan tangan manusi, supay Allah merasakan kepada mereka sebahagian dari (akibat) perbuatan mereka, agar mereka kembali (ke jalan yang benar).", "manzil": 5, "manzil_display": ""}], "409": [{"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 42, "text": "قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِینَ ۝٤٢", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "قل -أيها الرسول- للمكذبين بما جئت به: سيروا في أنحاء الأرض سير اعتبار وتأمل، فانظروا كيف كان عاقبة الأمم السابقة المكذبة كقوم نوح، وعاد وثمود، تجدوا عاقبتهم شر العواقب ومآلهم شر مآل؟ فقد كان أكثرهم مشركين بالله.", "isBasmala": false, "translation_en": "Say, \"Roam the earth, and observe the fate of those who came before. Most of them were idolaters.\"", "translation_id": "Katakanlah: \"Adakanlah perjalanan di muka bumi dan perhatikanlah bagaimana kesudahan orang-orang yang terdahulu. Kebanyakan dari mereka itu adalah orang-orang yang mempersekutukan (Allah)\".", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 43, "text": "فَأَقِمۡ وَجۡهَكَ لِلدِّینِ ٱلۡقَیِّمِ مِن قَبۡلِ أَن یَأۡتِیَ یَوۡمࣱ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۖ یَوۡمَىِٕذࣲ یَصَّدَّعُونَ ۝٤٣", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "فوجِّه وجهك -أيها الرسول- نحو الدين المستقيم، وهو الإسلام، منفذًا أوامره مجتنبًا نواهيه، واستمسك به من قبل مجيء يوم القيامة، فإذا جاء ذلك اليوم الذي لا يقدر أحد على ردِّه تفرقت الخلائق أشتاتًا متفاوتين؛ ليُروا أعمالهم.", "isBasmala": false, "translation_en": "So devote yourself to the upright religion, before there comes from God a Day that cannot be averted. On that Day, they will be shocked.", "translation_id": "Oleh karena itu, hadapkanlah wajahmu kepada agama yang lurus (Islam) sebelum datang dari Allah suatu hari yang tidak dapat ditolak (kedatangannya): pada hari itu mereka terpisah-pisah.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 44, "text": "مَن كَفَرَ فَعَلَیۡهِ كُفۡرُهُۥۖ وَمَنۡ عَمِلَ صَـٰلِحࣰا فَلِأَنفُسِهِمۡ یَمۡهَدُونَ ۝٤٤", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "من كفر فعليه عقوبة كفره، وهي خلوده في النار، ومن آمن وعمل صالحًا فلأنفسهم يهيئون منازل الجنة؛ بسبب تمسكهم بطاعة ربهم.", "isBasmala": false, "translation_en": "Whoever disbelieves, upon him falls his disbelief. And whoever acts righteously-they are preparing for themselves.", "translation_id": "Barangsiapa yang kafir maka dia sendirilah yang menanggung (akibat) kekafirannya itu; dan barangsiapa yang beramal saleh maka untuk diri mereka sendirilah mereka menyiapkan (tempat yang menyenangkan),", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 45, "text": "لِیَجۡزِیَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِن فَضۡلِهِۦۤۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡكَـٰفِرِینَ ۝٤٥", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "ليجزي الله الذين آمنوا بالله ورسوله وعملوا الصالحات من فضله وإحسانه. إنه لا يحب الكافرين لسخطه وغضبه عليهم.", "isBasmala": false, "translation_en": "So that He may reward those who have believed and done the righteous deeds out of His bounty. Indeed, He does not love the ungrateful.", "translation_id": "agar Allah memberi pahala kepada orang-orang yang beriman dan beramal saleh dari karunia-Nya. Sesungguhnya Dia tidak menyukai orang-orang yang ingkar.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 46, "text": "وَمِنۡ ءَایَـٰتِهِۦۤ أَن یُرۡسِلَ ٱلرِّیَاحَ مُبَشِّرَ ٰتࣲ وَلِیُذِیقَكُم مِّن رَّحۡمَتِهِۦ وَلِتَجۡرِیَ ٱلۡفُلۡكُ بِأَمۡرِهِۦ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ۝٤٦", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "ومن آيات الله الدالة على أنه الإله الحق وحده لا شريك له وعلى عظيم قدرته إرسال الرياح أمام المطر مبشرات بإثارتها للسحاب، فتستبشر بذلك النفوس؛ وليذيقكم من رحمته بإنزاله المطر الذي تحيا به البلاد والعباد، ولتجري السفن في البحر بأمر الله ومشيئته، ولتبتغوا من فضله بالتجارة وغيرها؛ فعل الله ذلك من أجل أن تشكروا له نعمه وتعبدوه وحده.", "isBasmala": false, "translation_en": "And of His signs is that He sends the winds bearing good news, to give you a taste of His mercy, and so that the ships may sail by His command, and so that you may seek of His bounty, and so that you may give thanks.", "translation_id": "Dan di antara tanda-tanda kekuasan-Nya adalah bahwa Dia mengirimkan angin sebagai pembawa berita gembira dan untuk merasakan kepadamu sebagian dari rahmat-Nya dan supaya kapal dapat berlayar dengan perintah-Nya dan (juga) supaya kamu dapat mencari karunia-Nya; mudah-mudahn kamu bersyukur.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 47, "text": "وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَاۤءُوهُم بِٱلۡبَیِّنَـٰتِ فَٱنتَقَمۡنَا مِنَ ٱلَّذِینَ أَجۡرَمُوا۟ۖ وَكَانَ حَقًّا عَلَیۡنَا نَصۡرُ ٱلۡمُؤۡمِنِینَ ۝٤٧", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "ولقد أرسلنا مِن قبلك -أيها الرسول- رسلا إلى قومهم مبشرين ومنذرين يدعونهم إلى التوحيد، ويحذرونهم من الشرك، فجاؤوهم بالمعجزات والبراهين الساطعة، فكفر أكثرهم بربهم، فانتقمنا من الذين اكتسبوا السيئات منهم، فأهلكناهم، ونصرنا المؤمنين أتباع الرسل، وكذلك نفعل بالمكذبين بك إن استمروا على تكذيبك، ولم يؤمنوا.", "isBasmala": false, "translation_en": "Before you, We sent messengers to their people. They came to them with clear proofs. Then We took revenge on those who sinned. It is incumbent on Us to help the believers.", "translation_id": "Dan Sesungguhnya Kami telah mengutus sebelum kamu beberapa orang rasul kepada kaumnya, mereka datang kepadanya dengan membawa keterangan-keterangan (yang cukup), lalu Kami melakukan pembalasan terhadap orang-orang yang berdosa. Dan Kami selalu berkewajiban menolong orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 48, "text": "ٱللَّهُ ٱلَّذِی یُرۡسِلُ ٱلرِّیَـٰحَ فَتُثِیرُ سَحَابࣰا فَیَبۡسُطُهُۥ فِی ٱلسَّمَاۤءِ كَیۡفَ یَشَاۤءُ وَیَجۡعَلُهُۥ كِسَفࣰا فَتَرَى ٱلۡوَدۡقَ یَخۡرُجُ مِنۡ خِلَـٰلِهِۦۖ فَإِذَاۤ أَصَابَ بِهِۦ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۤ إِذَا هُمۡ یَسۡتَبۡشِرُونَ ۝٤٨", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "الله -سبحانه- هو الذي يرسل الرياح فتثير سحابًا مثقلا بالماء، فينشره الله في السماء كيف يشاء، ويجعله قطعًا متفرقة، فترى المطر يخرج من بين السحاب، فإذا ساقه الله إلى عباده إذا هم يستبشرون ويفرحون بأن الله صرف ذلك إليهم.", "isBasmala": false, "translation_en": "God is He who sends the winds. They stir up clouds. Then He spreads them in the sky as He wills. And He breaks them apart. Then you see rain drops issuing from their midst. Then, when He makes it fall upon whom He wills of His servants, behold, they rejoice.", "translation_id": "Allah, Dialah yang mengirim angin, lalu angin itu menggerakkan awan dan Allah membentangkannya di langit menurut yang dikehendaki-Nya, dan menjadikannya bergumpal-gumpal; lalu kamu lihat hujan keluar dari celah-celahnya, maka apabila hujan itu turun mengenai hamba-hamba-Nya yang dikehendaki-Nya, tiba-tiba mereka menjadi gembira.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 49, "text": "وَإِن كَانُوا۟ مِن قَبۡلِ أَن یُنَزَّلَ عَلَیۡهِم مِّن قَبۡلِهِۦ لَمُبۡلِسِینَ ۝٤٩", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "وإنْ كانوا من قبل نزول المطر لفي يأس وقنوط؛ بسبب احتباسه عنهم.", "isBasmala": false, "translation_en": "Although they were before this-before it was sent down upon them-in despair.", "translation_id": "Dan Sesungguhnya sebelum hujan diturunkan kepada mereka, mereka benar-benar telah berputus asa.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 50, "text": "فَٱنظُرۡ إِلَىٰۤ ءَاثَـٰرِ رَحۡمَتِ ٱللَّهِ كَیۡفَ یُحۡیِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۤۚ إِنَّ ذَ ٰلِكَ لَمُحۡیِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٥٠", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "فانظر -أيها المشاهد- نظر تأمل وتدبر إلى آثار المطر في النبات والزروع والشجر، كيف يحيي به الله الأرض بعد موتها، فينبتها ويعشبها؟ إن الذي قَدَر على إحياء هذه الأرض لمحيي الموتى، وهو على كل شيء قدير لا يعجزه شيء.", "isBasmala": false, "translation_en": "So observe the effects of God's mercy-how He revives the earth after it was dead. Indeed, He is the Reviver of the dead. He is Capable of everything.", "translation_id": "Maka perhatikanlah bekas-bekas rahmat Allah, bagaimana Allah menghidupkan bumi yang sudah mati. Sesungguhnya (Tuhan yang berkuasa seperti) demikian benar-benar (berkuasa) menghidupkan orang-orang yang telah mati. Dan Dia Maha Kuasa atas segala sesuatu.", "manzil": 5, "manzil_display": ""}], "410": [{"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 51, "text": "وَلَىِٕنۡ أَرۡسَلۡنَا رِیحࣰا فَرَأَوۡهُ مُصۡفَرࣰّا لَّظَلُّوا۟ مِنۢ بَعۡدِهِۦ یَكۡفُرُونَ ۝٥١", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "ولئن أرسلنا على زروعهم ونباتهم ريحًا مفسدة، فرأوا نباتهم قد فسد بتلك الريح، فصار من بعد خضرته مصفرًا، لمكثوا من بعد رؤيتهم له يكفرون بالله ويجحدون نعمه.", "isBasmala": false, "translation_en": "But if We send a wind, and they see it turning things yellow, they would continue thereafter to disbelieve.", "translation_id": "Dan sungguh, jika Kami mengirimkan angin (kepada tumbuh-tumbuhan) lalu mereka melihat (tumbuh-tumbuhan itu) menjadi kuning (kering), benar-benar tetaplah mereka sesudah itu menjadi orang yang ingkar.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 52, "text": "فَإِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَاۤءَ إِذَا وَلَّوۡا۟ مُدۡبِرِینَ ۝٥٢", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "فإنك -أيها الرسول- لا تسمع من مات قلبه، أو سدَّ أذنه عن سماع الحق، فلا تجزع ولا تحزن على عدم إيمان هؤلاء المشركين بك، فإنهم كالصم والموتى لا يسمعون، ولا يشعرون ولو كانوا حاضرين، فكيف إذا كانوا غائبين عنك مدبرين؟", "isBasmala": false, "translation_en": "You cannot make the dead hear, nor can you make the deaf hear the call when they turn away.", "translation_id": "Maka Sesungguhnya kamu tidak akan sanggup menjadikan orang-orang yang mati itu dapat mendengar, dan menjadikan orang-orang yang tuli dapat mendengar seruan, apabila mereka itu berpaling membelakang.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 53, "text": "وَمَاۤ أَنتَ بِهَـٰدِ ٱلۡعُمۡیِ عَن ضَلَـٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن یُؤۡمِنُ بِـَٔایَـٰتِنَا فَهُم مُّسۡلِمُونَ ۝٥٣", "juz": 21, "hizb": "(*½ ح 41*)", "tafsir": "وما أنت -أيها الرسول- بمرشد مَن أعماه الله عن طريق الهدى، ما تُسمع سماع انتفاع إلا مَن يؤمن بآياتنا، فهم خاضعون ممتثلون لأمر الله.", "isBasmala": false, "translation_en": "Nor can you guide the blind out of their error. You can make hear only those who believe in Our signs, and so have submitted.", "translation_id": "Dan kamu sekali-kali tidak akan dapat memberi petunjuk kepada orang-orang yang buta (mata hatinya) dari kesesatannya. Dan kamu tidak dapat memperdengarkan (petunjuk Tuhan) melainkan kepada orang-orang yang beriman dengan ayat-ayat Kami, mereka itulah orang-orang yang berserah diri (kepada Kami).", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 54, "text": "۞ ٱللَّهُ ٱلَّذِی خَلَقَكُم مِّن ضَعۡفࣲ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفࣲ قُوَّةࣰ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةࣲ ضَعۡفࣰا وَشَیۡبَةࣰۚ یَخۡلُقُ مَا یَشَاۤءُۚ وَهُوَ ٱلۡعَلِیمُ ٱلۡقَدِیرُ ۝٥٤", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "الله تعالى هو الذي خلقكم من ماء ضعيف مهين، وهو النطفة، ثم جعل من بعد ضعف الطفولة قوة الرجولة، ثم جعل من بعد هذه القوة ضعف الكبر والهرم، يخلق الله ما يشاء من الضعف والقوة، وهو العليم بخلقه، القادر على كل شيء.", "isBasmala": false, "translation_en": "God is He Who created you weak, then after weakness gave you strength, then after strength gave you weakness and gray hair. He creates whatever He wills. He is the Omniscient, the Omnipotent.", "translation_id": "Allah, Dialah yang menciptakan kamu dari keadaan lemah, kemudian Dia menjadikan (kamu) sesudah keadaan lemah itu menjadi kuat, kemudian Dia menjadikan (kamu) sesudah kuat itu lemah (kembali) dan beruban. Dia menciptakan apa yang dikehendaki-Nya dan Dialah Yang Maha Mengetahui lagi Maha Kuasa.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 55, "text": "وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُوا۟ غَیۡرَ سَاعَةࣲۚ كَذَ ٰلِكَ كَانُوا۟ یُؤۡفَكُونَ ۝٥٥", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "ويوم تجيء القيامة ويبعث الله الخلق من قبورهم يقسم المشركون ما مكثوا في الدنيا غير فترة قصيرة من الزمن، كذبوا في قسمهم، كما كانوا يكذبون في الدنيا، وينكرون الحق الذي جاءت به الرسل.", "isBasmala": false, "translation_en": "On the Day when the Hour takes place, the sinners will swear they had stayed but an hour. Thus they were deluded.", "translation_id": "Dan pada hari terjadinya kiamat, bersumpahlah orang-orang yang berdosa; \"mereka tidak berdiam (dalam kubur) melainkan sesaat (saja)\". Seperti demikianlah mereka selalu dipalingkan (dari kebenaran).", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 56, "text": "وَقَالَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ وَٱلۡإِیمَـٰنَ لَقَدۡ لَبِثۡتُمۡ فِی كِتَـٰبِ ٱللَّهِ إِلَىٰ یَوۡمِ ٱلۡبَعۡثِۖ فَهَـٰذَا یَوۡمُ ٱلۡبَعۡثِ وَلَـٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ ۝٥٦", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "وقال الذين أوتوا العلم والإيمان بالله من الملائكة والأنبياء والمؤمنين: لقد مكثتم فيما كتب الله مما سبق في علمه من يوم خُلقتم إلى أن بُعثتم، فهذا يوم البعث، ولكنكم كنتم لا تعلمون، فأنكرتموه في الدنيا، وكذَّبتم به.", "isBasmala": false, "translation_en": "But those endowed with knowledge and faith will say, \"You remained in God's Book until the Day of Resurrection. This is the Day of Resurrection, but you did not know.\"", "translation_id": "Dan berkata orang-orang yang diberi ilmu pengetahuan dan keimanan (kepada orang-orang yang kafir): \"Sesungguhnya kamu telah berdiam (dalam kubur) menurut ketetapan Allah, sampai hari berbangkit; maka inilah hari berbangkit itu akan tetapi kamu selalu tidak meyakini(nya)\".", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 57, "text": "فَیَوۡمَىِٕذࣲ لَّا یَنفَعُ ٱلَّذِینَ ظَلَمُوا۟ مَعۡذِرَتُهُمۡ وَلَا هُمۡ یُسۡتَعۡتَبُونَ ۝٥٧", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "فيوم القيامة لا ينفع الظالمين ما يقدمونه من أعذار، ولا يُطلب منهم إرضاء الله تعالى بالتوبة والطاعة، بل يُعاقبون بسيئاتهم ومعاصيهم.", "isBasmala": false, "translation_en": "On that Day, the sinners' excuses will not benefit them, nor will they be excused.", "translation_id": "Maka pada hari itu tidak bermanfaat (lagi) bagi orang-orang yang zalim permintaan uzur mereka, dan tidak pula mereka diberi kesempatan bertaubat lagi.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 58, "text": "وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِی هَـٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲۚ وَلَىِٕن جِئۡتَهُم بِـَٔایَةࣲ لَّیَقُولَنَّ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ أَنتُمۡ إِلَّا مُبۡطِلُونَ ۝٥٨", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "ولقد بينَّا للناس في هذا القرآن مِن كل مثل من أجل إقامة الحجة عليهم وإثبات وحدانية الله جل وعلا، ولئن جئتهم -أيها الرسول- بأي حجة تدل على صدقك ليقولَنَّ الذين كفروا بك: ما أنتم -أيها الرسول وأتباعك- إلا مبطلون فيما تجيئوننا به من الأمور.", "isBasmala": false, "translation_en": "We have cited in this Quran for the people every sort of parable. But even if you bring them a miracle, those who disbelieve will say, \"You are nothing but fakers.\"", "translation_id": "Dan Sesungguhnya telah Kami buat dalam Al Quran ini segala macam perumpamaan untuk manusia. Dan Sesungguhnya jika kamu membawa kepada mereka suatu ayat, pastilah orang-orang yang kafir itu akan berkata: \"Kamu tidak lain hanyalah orang-orang yang membuat kepalsuan belaka\".", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 59, "text": "كَذَ ٰلِكَ یَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِینَ لَا یَعۡلَمُونَ ۝٥٩", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "ومثل ذلك الختم يختم الله على قلوب الذين لا يعلمون حقيقة ما تأتيهم به -أيها الرسول- من عند الله من هذه العبر والآيات البينات.", "isBasmala": false, "translation_en": "God thus seals the hearts of those who do not know.", "translation_id": "Demikianlah Allah mengunci mati hati orang-orang yang tidak (mau) memahami.", "manzil": 5, "manzil_display": ""}, {"sura": 30, "sura_name": "الروم", "revelation": "Makkiyah", "aya": 60, "text": "فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ وَلَا یَسۡتَخِفَّنَّكَ ٱلَّذِینَ لَا یُوقِنُونَ ۝٦٠", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "فاصبر -أيها الرسول- على ما ينالك مِن أذى قومك وتكذيبهم لك، إن ما وعدك الله به من نصر وتمكين وثواب حق لا شك فيه، ولا يستفزَّنَّك عن دينك الذين لا يوقنون بالميعاد، ولا يصدِّقون بالبعث والجزاء.", "isBasmala": false, "translation_en": "So be patient. The promise of God is true. And do not let those who lack certainty belittle you.", "translation_id": "Dan bersabarlah kamu, sesungguhnya janji Allah adalah benar dan sekali-kali janganlah orang-orang yang tidak meyakini (kebenaran ayat-ayat Allah) itu menggelisahkan kamu.", "manzil": 5, "manzil_display": ""}], "411": [{"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 21, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 1, "text": "الۤمۤ ۝١", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "(الم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Meem.", "translation_id": "Alif Laam Miim", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 2, "text": "تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡحَكِیمِ ۝٢", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "هذه الآيات آيات القرآن ذي الحكمة البالغة.", "isBasmala": false, "translation_en": "These are the Verses of the Wise Book.", "translation_id": "Inilah ayat-ayat Al Quran yang mengandung hikmat,", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 3, "text": "هُدࣰى وَرَحۡمَةࣰ لِّلۡمُحۡسِنِینَ ۝٣", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "هذه الآيات هدى ورحمة للذين أحسنوا العمل بما أنزل الله في القرآن، وما أمرهم به رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "A guide and a mercy for the righteous.", "translation_id": "menjadi petunjuk dan rahmat bagi orang-orang yang berbuat kebaikan,", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 4, "text": "ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ یُوقِنُونَ ۝٤", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "الذين يؤدون الصلاة كاملة في أوقاتها ويؤتون الزكاة المفروضة عليهم لمستحقيها، وهم بالبعث والجزاء في الدار الآخرة يوقنون.", "isBasmala": false, "translation_en": "Those who observe the prayer, and pay the obligatory charity, and are certain of the Hereafter.", "translation_id": "(yaitu) orang-orang yang mendirikan shalat, menunaikan zakat dan mereka yakin akan adanya negeri akhirat.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 5, "text": "أُو۟لَـٰۤىِٕكَ عَلَىٰ هُدࣰى مِّن رَّبِّهِمۡۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝٥", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "أولئك المتصفون بالصفات السابقة على بيان مِن ربهم ونور، وأولئك هم الفائزون في الدنيا والآخرة.", "isBasmala": false, "translation_en": "These are upon guidance from their Lord. These are the successful.", "translation_id": "Mereka itulah orang-orang yang tetap mendapat petunjuk dari Tuhannya dan mereka itulah orang-orang yang beruntung.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 6, "text": "وَمِنَ ٱلنَّاسِ مَن یَشۡتَرِی لَهۡوَ ٱلۡحَدِیثِ لِیُضِلَّ عَن سَبِیلِ ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَیَتَّخِذَهَا هُزُوًاۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مُّهِینࣱ ۝٦", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "ومن الناس مَن يشتري لَهْو الحديث - وهو كل ما يُلهي عن طاعة الله ويصد عن مرضاته- ليضلَّ الناس عن طريق الهدى إلى طريق الهوى، ويتخذ آيات الله سخرية، أولئك لهم عذاب يهينهم ويخزيهم.", "isBasmala": false, "translation_en": "Among the people is he who trades in distracting tales; intending, without knowledge, to lead away from God's way, and to make a mockery of it. These will have a humiliating punishment.", "translation_id": "Dan di antara manusia (ada) orang yang mempergunakan perkataan yang tidak berguna untuk menyesatkan (manusia) dari jalan Allah tanpa pengetahuan dan menjadikan jalan Allah itu olok-olokan. Mereka itu akan memperoleh azab yang menghinakan.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 7, "text": "وَإِذَا تُتۡلَىٰ عَلَیۡهِ ءَایَـٰتُنَا وَلَّىٰ مُسۡتَكۡبِرࣰا كَأَن لَّمۡ یَسۡمَعۡهَا كَأَنَّ فِیۤ أُذُنَیۡهِ وَقۡرࣰاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِیمٍ ۝٧", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "وإذا تتلى عليه آيات القرآن أعرض عن طاعة الله، وتكبَّر غير معتبر، كأنه لم يسمع شيئًا، كأَنَّ في أذنيه صممًا، ومَن هذه حاله فبشِّره -أيها الرسول- بعذاب مؤلم موجع في النار يوم القيامة.", "isBasmala": false, "translation_en": "And when Our Verses are recited to him, he turns away in pride, as though he did not hear them, as though there is deafness in his ears. So inform him of a painful punishment.", "translation_id": "Dan apabila dibacakan kepadanya ayat-ayat Kami dia berpaling dengan menyombongkan diri seolah-olah dia belum mendengarnya, seakan-akan ada sumbat di kedua telinganya; maka beri kabar gembiralah dia dengan azab yang pedih.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 8, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمۡ جَنَّـٰتُ ٱلنَّعِیمِ ۝٨", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "إن الذين آمنوا بالله ورسوله وعملوا الصالحات التي أُمروا بها، أولئك لهم نعيم مقيم في الجنات.", "isBasmala": false, "translation_en": "As for those who believe and do good deeds-for them are the Gardens of Bliss.", "translation_id": "Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal saleh, bagi mereka surga-surga yang penuh kenikmatan,", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 9, "text": "خَـٰلِدِینَ فِیهَاۖ وَعۡدَ ٱللَّهِ حَقࣰّاۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٩", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "وحياتهم في تلك الجنات حياة أبديةٌ لا تنقطع ولا تزول، وعدهم الله بذلك وعدًا حقًا. وهو سبحانه لا يُخلف وعده، وهو العزيز في أمره، الحكيم في تدبيره.", "isBasmala": false, "translation_en": "Dwelling therein forever. The promise of God is true. He is the Mighty, the Wise.", "translation_id": "Kekal mereka di dalamnya; sebagai janji Allah yang benar. Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 10, "text": "خَلَقَ ٱلسَّمَـٰوَ ٰتِ بِغَیۡرِ عَمَدࣲ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِی ٱلۡأَرۡضِ رَوَ ٰسِیَ أَن تَمِیدَ بِكُمۡ وَبَثَّ فِیهَا مِن كُلِّ دَاۤبَّةࣲۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَنۢبَتۡنَا فِیهَا مِن كُلِّ زَوۡجࣲ كَرِیمٍ ۝١٠", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "خلق الله السموات، ورفعها بغير عمد كما تشاهدونها، وألقى في الأرض جبالا ثابتة؛ لئلا تضطرب وتتحرك فتفسد حياتكم، ونشر في الأرض مختلف أنواع الدواب، وأنزلنا من السحاب مطرًا، فأنبتنا به من الأرض من كل زوج بهيج نافع حسن المنظر.", "isBasmala": false, "translation_en": "He created the heavens without pillars that you can see, and placed stabilizers on earth lest it shifts with you, and scattered throughout it all kinds of creatures. And from the sky We sent down water, and caused to grow therein of every noble pair.", "translation_id": "Dia menciptakan langit tanpa tiang yang kamu melihatnya dan Dia meletakkan gunung-gunung (di permukaan) bumi supaya bumi itu tidak menggoyangkan kamu; dan memperkembang biakkan padanya segala macam jenis binatang. Dan Kami turunkan air hujan dari langit, lalu Kami tumbuhkan padanya segala macam tumbuh-tumbuhan yang baik.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 11, "text": "هَـٰذَا خَلۡقُ ٱللَّهِ فَأَرُونِی مَاذَا خَلَقَ ٱلَّذِینَ مِن دُونِهِۦۚ بَلِ ٱلظَّـٰلِمُونَ فِی ضَلَـٰلࣲ مُّبِینࣲ ۝١١", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "وكل ما تشاهدونه هو خلق الله، فأروني- أيها المشركون-: ماذا خلقت آلهتكم التي تعبدونها من دون الله؟ بل المشركون في ذهاب بيِّن عن الحق والاستقامة.", "isBasmala": false, "translation_en": "Such is God's creation. Now show me what those besides Him have created. In fact, the wicked are in obvious error.", "translation_id": "Inilah ciptaan Allah, maka perlihatkanlah olehmu kepadaku apa yang telah diciptakan oleh sembahan-sembahan(mu) selain Allah. Sebenarnya orang-orang yang zalim itu berada di dalam kesesatan yang nyata.", "manzil": 5, "manzil_display": ""}], "412": [{"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 12, "text": "وَلَقَدۡ ءَاتَیۡنَا لُقۡمَـٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن یَشۡكُرۡ فَإِنَّمَا یَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِیٌّ حَمِیدࣱ ۝١٢", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "ولقد أعطينا عبدًا صالحًا من عبادنا (وهو لقمان) الحكمة، وهي الفقه في الدين وسلامة العقل والإصابة في القول، وقلنا له: اشكر لله نِعَمَه عليك، ومَن يشكر لربه فإنما يعود نَفْع ذلك عليه، ومن جحد نِعَمَه فإن الله غني عن شكره، غير محتاج إليه، له الحمد والثناء على كل حال.", "isBasmala": false, "translation_en": "We endowed Luqman with wisdom: \"Give thanks to God.\" Whoever is appreciative-is appreciative for the benefit of his own soul. And whoever is unappreciative-God is Sufficient and Praiseworthy.", "translation_id": "Dan sesungguhnya telah Kami berikan hikmat kepada Luqman, yaitu: \"Bersyukurlah kepada Allah. Dan barangsiapa yang bersyukur (kepada Allah), maka sesungguhnya ia bersyukur untuk dirinya sendiri; dan barangsiapa yang tidak bersyukur, maka sesungguhnya Allah Maha Kaya lagi Maha Terpuji\".", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 13, "text": "وَإِذۡ قَالَ لُقۡمَـٰنُ لِٱبۡنِهِۦ وَهُوَ یَعِظُهُۥ یَـٰبُنَیَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِیمࣱ ۝١٣", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "واذكر -أيها الرسول- نصيحة لقمان لابنه حين قال له واعظًا: يا بنيَّ لا تشرك بالله فتظلم نفسك؛ إن الشرك لأعظم الكبائر وأبشعها.", "isBasmala": false, "translation_en": "When Luqman said to his son, as he advised him, \"O my son, do not associate anything with God, for idolatry is a terrible wrong.\"", "translation_id": "Dan (ingatlah) ketika Luqman berkata kepada anaknya, di waktu ia memberi pelajaran kepadanya: \"Hai anakku, janganlah kamu mempersekutukan Allah, sesungguhnya mempersekutukan (Allah) adalah benar-benar kezaliman yang besar\".", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 14, "text": "وَوَصَّیۡنَا ٱلۡإِنسَـٰنَ بِوَ ٰلِدَیۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنࣲ وَفِصَـٰلُهُۥ فِی عَامَیۡنِ أَنِ ٱشۡكُرۡ لِی وَلِوَ ٰلِدَیۡكَ إِلَیَّ ٱلۡمَصِیرُ ۝١٤", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "وأَمَرْنا الإنسان ببرِّ والديه والإحسان إليهما، حَمَلَتْه أمه ضعفًا على ضعف، وحمله وفِطامه عن الرضاعة في مدة عامين، وقلنا له: اشكر لله، ثم اشكر لوالديك، إليَّ المرجع فأُجازي كُلا بما يستحق.", "isBasmala": false, "translation_en": "We have entrusted the human being with the care of his parents. His mother carried him through hardship upon hardship, weaning him in two years. So give thanks to Me, and to your parents. To Me is the destination.", "translation_id": "Dan Kami perintahkan kepada manusia (berbuat baik) kepada dua orang ibu-bapaknya; ibunya telah mengandungnya dalam keadaan lemah yang bertambah-tambah, dan menyapihnya dalam dua tahun. Bersyukurlah kepada-Ku dan kepada dua orang ibu bapakmu, hanya kepada-Kulah kembalimu.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 15, "text": "وَإِن جَـٰهَدَاكَ عَلَىٰۤ أَن تُشۡرِكَ بِی مَا لَیۡسَ لَكَ بِهِۦ عِلۡمࣱ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِی ٱلدُّنۡیَا مَعۡرُوفࣰاۖ وَٱتَّبِعۡ سَبِیلَ مَنۡ أَنَابَ إِلَیَّۚ ثُمَّ إِلَیَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ۝١٥", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "وإن جاهدك- أيها الولد المؤمن- والداك على أن تشرك بي غيري في عبادتك إياي مما ليس لك به عِلم، أو أمراك بمعصية مِن معاصي الله فلا تطعهما؛ لأنه لا طاعة لمخلوق في معصية الخالق، وصاحبهما في الدنيا بالمعروف فيما لا إثم فيه، واسلك- أيها الابن المؤمن- طريق مَن تاب من ذنبه، ورجع إليَّ وآمن برسولي محمد صلى الله عليه وسلم، ثم إليَّ مرجعكم، فأخبركم بما كنتم تعملونه في الدنيا، وأجازي كلَّ عامل بعمله.", "isBasmala": false, "translation_en": "But if they strive to have you associate with Me something of which you have no knowledge, do not obey them. But keep them company in this life, in kindness, and follow the path of him who turns to Me. Then to Me is your return; and I will inform you of what you used to do.", "translation_id": "Dan jika keduanya memaksamu untuk mempersekutukan dengan Aku sesuatu yang tidak ada pengetahuanmu tentang itu, maka janganlah kamu mengikuti keduanya, dan pergaulilah keduanya di dunia dengan baik, dan ikutilah jalan orang yang kembali kepada-Ku, kemudian hanya kepada-Kulah kembalimu, maka Kuberitakan kepadamu apa yang telah kamu kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 16, "text": "یَـٰبُنَیَّ إِنَّهَاۤ إِن تَكُ مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلࣲ فَتَكُن فِی صَخۡرَةٍ أَوۡ فِی ٱلسَّمَـٰوَ ٰتِ أَوۡ فِی ٱلۡأَرۡضِ یَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِیفٌ خَبِیرࣱ ۝١٦", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "يا بنيَّ اعلم أن السيئة أو الحسنة إن كانت قَدْر حبة خردل- وهي المتناهية في الصغر- في باطن جبل، أو في أي مكان في السموات أو في الأرض، فإن الله يأتي بها يوم القيامة، ويحاسِب عليها. إن الله لطيف بعباده خبير بأعمالهم.", "isBasmala": false, "translation_en": "\"O my son, even if it were the weight of a mustard-seed, in a rock, or in the heavens, or on earth, God will bring it to light. God is Kind and Expert.", "translation_id": "(Luqman berkata): \"Hai anakku, sesungguhnya jika ada (sesuatu perbuatan) seberat biji sawi, dan berada dalam batu atau di langit atau di dalam bumi, niscaya Allah akan mendatangkannya (membalasinya). Sesungguhnya Allah Maha Halus lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 17, "text": "یَـٰبُنَیَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَاۤ أَصَابَكَۖ إِنَّ ذَ ٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ ۝١٧", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "يا بنيَّ أقم الصلاة تامة بأركانها وشروطها وواجباتها، وأْمر بالمعروف، وانْه عن المنكر بلطفٍ ولينٍ وحكمة بحسب جهدك، وتحمَّل ما يصيبك من الأذى مقابل أمرك بالمعروف ونهيك عن المنكر، واعلم أن هذه الوصايا مما أمر الله به من الأمور التي ينبغي الحرص عليها.", "isBasmala": false, "translation_en": "O my son, observe the prayer, advocate righteousness, forbid evil, and be patient over what has befallen you. These are of the most honorable traits.", "translation_id": "Hai anakku, dirikanlah shalat dan suruhlah (manusia) mengerjakan yang baik dan cegahlah (mereka) dari perbuatan yang mungkar dan bersabarlah terhadap apa yang menimpa kamu. Sesungguhnya yang demikian itu termasuk hal-hal yang diwajibkan (oleh Allah).", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 18, "text": "وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِی ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا یُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورࣲ ۝١٨", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "ولا تُمِلْ وجهك عن الناس إذا كلَّمتهم أو كلموك؛ احتقارًا منك لهم واستكبارًا عليهم، ولا تمش في الأرض بين الناس مختالا متبخترًا، إن الله لا يحب كل متكبر متباه في نفسه وهيئته وقوله.", "isBasmala": false, "translation_en": "And do not treat people with arrogance, nor walk proudly on earth. God does not love the arrogant showoffs.", "translation_id": "Dan janganlah kamu memalingkan mukamu dari manusia (karena sombong) dan janganlah kamu berjalan di muka bumi dengan angkuh. Sesungguhnya Allah tidak menyukai orang-orang yang sombong lagi membanggakan diri.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 19, "text": "وَٱقۡصِدۡ فِی مَشۡیِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَ ٰتِ لَصَوۡتُ ٱلۡحَمِیرِ ۝١٩", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "وتواضع في مشيك، واخفض من صوتك فلا ترفعه، إن أقبح الأصوات وأبغضها لصوت الحمير المعروفة ببلادتها وأصواتها المرتفعة.", "isBasmala": false, "translation_en": "And moderate your stride, and lower your voice. The most repulsive of voices is the donkey's voice.\"", "translation_id": "Dan sederhanalah kamu dalam berjalan dan lunakkanlah suaramu. Sesungguhnya seburuk-buruk suara ialah suara keledai.", "manzil": 5, "manzil_display": ""}], "413": [{"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 20, "text": "أَلَمۡ تَرَوۡا۟ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَیۡكُمۡ نِعَمَهُۥ ظَـٰهِرَةࣰ وَبَاطِنَةࣰۗ وَمِنَ ٱلنَّاسِ مَن یُجَـٰدِلُ فِی ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَلَا هُدࣰى وَلَا كِتَـٰبࣲ مُّنِیرࣲ ۝٢٠", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "ألم تروا- أيها الناس- أن الله ذلَّل لكم ما في السموات من الشمس والقمر والسحاب وغير ذلك، وما في الأرض من الدوابِّ والشجر والماء، وغير ذلك مما لا يحصى، وعمَّكم بنعمه الظاهرة على الأبدان والجوارح، والباطنة في العقول والقلوب، وما ادَّخره لكم مما لا تعلمونه؟ ومن الناس مَن يجادل في توحيد الله وإخلاص العبادة له بغير حجة ولا بيان، ولا كتاب مبين يبيِّن حقيقة دعواه.", "isBasmala": false, "translation_en": "Do you not see how God placed at your service everything in the heavens and the earth? How He showered you with His blessings, both outward and inward? Yet among the people is he who argues about God without knowledge, without guidance, and without an enlightening Scripture.", "translation_id": "Tidakkah kamu perhatikan sesungguhnya Allah telah menundukkan untuk (kepentingan)mu apa yang di langit dan apa yang di bumi dan menyempurnakan untukmu nikmat-Nya lahir dan batin. Dan di antara manusia ada yang membantah tentang (keesaan) Allah tanpa ilmu pengetahuan atau petunjuk dan tanpa Kitab yang memberi penerangan.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 21, "text": "وَإِذَا قِیلَ لَهُمُ ٱتَّبِعُوا۟ مَاۤ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَیۡهِ ءَابَاۤءَنَاۤۚ أَوَ لَوۡ كَانَ ٱلشَّیۡطَـٰنُ یَدۡعُوهُمۡ إِلَىٰ عَذَابِ ٱلسَّعِیرِ ۝٢١", "juz": 21, "hizb": "(*¾ ح 41*)", "tafsir": "وإذا قيل لهؤلاء المجادلين في توحيد الله وإفراده بالعبادة: اتبعوا ما أنزل الله على نبيه محمد صلى الله عليه وسلم قالوا: بل نتبع ما كان عليه آباؤنا من الشرك وعبادة الأصنام، أيفعلون ذلك، ولو كان الشيطان يدعوهم؛ بتزيينه لهم سوء أعمالهم، وكفرهم بالله إلى عذاب النار المستعرة؟", "isBasmala": false, "translation_en": "And when it is said to them, \"Follow what God has revealed,\" they say, \"Rather, we follow what we found our parents devoted to.\" Even if Satan is calling them to the suffering of the Blaze?", "translation_id": "Dan apabila dikatakan kepada mereka: \"Ikutilah apa yang diturunkan Allah\". Mereka menjawab: \"(Tidak), tapi kami (hanya) mengikuti apa yang kami dapati bapak-bapak kami mengerjakannya\". Dan apakah mereka (akan mengikuti bapak-bapak mereka) walaupun syaitan itu menyeru mereka ke dalam siksa api yang menyala-nyala (neraka)?", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 22, "text": "۞ وَمَن یُسۡلِمۡ وَجۡهَهُۥۤ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنࣱ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَـٰقِبَةُ ٱلۡأُمُورِ ۝٢٢", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ومن يُخْلص عبادته لله وقصده إلى ربه تعالى، وهو محسن في أقواله، متقن لأعماله، فقد أخذ بأوثق سبب موصل إلى رضوان الله وجنته. وإلى الله وحده تصير كل الأمور، فيجازي المحسن على إحسانه، والمسيء على إساءته.", "isBasmala": false, "translation_en": "Whoever submits himself wholly to God, and is a doer of good, has grasped the most trustworthy handle. With God rests the outcome of all events.", "translation_id": "Dan barangsiapa yang menyerahkan dirinya kepada Allah, sedang dia orang yang berbuat kebaikan, maka sesungguhnya ia telah berpegang kepada buhul tali yang kokoh. Dan hanya kepada Allah-lah kesudahan segala urusan.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 23, "text": "وَمَن كَفَرَ فَلَا یَحۡزُنكَ كُفۡرُهُۥۤۚ إِلَیۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوۤا۟ۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝٢٣", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ومن كفر فلا تأسَ عليه -أيها الرسول- ولا تحزن؛ لأنك أدَّيت ما عليك من الدعوة والبلاغ، إلينا مرجعهم ومصيرهم يوم القيامة، فنخبرهم بأعمالهم الخبيثة التي عملوها في الدنيا، ثم نجازيهم عليها، إن الله عليم بما تُكِنُّه صدورهم من الكفر بالله وإيثار طاعة الشيطان.", "isBasmala": false, "translation_en": "Whoever disbelieves-let not his disbelief sadden you. To Us is their return. Then We will inform them of what they did. God knows what lies within the hearts.", "translation_id": "Dan barangsiapa kafir maka kekafirannya itu janganlah menyedihkanmu. Hanya kepada Kami-lah mereka kembali, lalu Kami beritakan kepada mereka apa yang telah mereka kerjakan. Sesungguhnya Allah Maha Mengetahui segala isi hati.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 24, "text": "نُمَتِّعُهُمۡ قَلِیلࣰا ثُمَّ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَلِیظࣲ ۝٢٤", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "نمتعهم في هذه الدنيا الفانية مدة قليلة، ثم يوم القيامة نُلجئهم ونسوقهم إلى عذاب فظيع، وهو عذاب جهنم.", "isBasmala": false, "translation_en": "We give them a little comfort; then We compel them to a harsh torment.", "translation_id": "Kami biarkan mereka bersenang-senang sebentar, kemudian Kami paksa mereka (masuk) ke dalam siksa yang keras.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 25, "text": "وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ لَیَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ ۝٢٥", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ولئن سألت -أيها الرسول- هؤلاء المشركين بالله: مَن خلق السموات والأرض؟ ليقولُنَّ الله، فإذا قالوا ذلك فقل لهم: الحمد لله الذي أظهر الاستدلال عليكم من أنفسكم، بل أكثر هؤلاء المشركين لا ينظرون ولا يتدبرون مَن الذي له الحمد والشكر، فلذلك أشركوا معه غيره.", "isBasmala": false, "translation_en": "And if you ask them, \"Who created the heavens and the earth?\" They will say, \"God.\" Say, \"Praise be to God.\" But most of them do not know.", "translation_id": "Dan sesungguhnya jika kamu tanyakan kepada mereka: \"Siapakah yang menciptakan langit dan bumi?\" Tentu mereka akan menjawab: \"Allah\". Katakanlah: \"Segala puji bagi Allah\"; tetapi kebanyakan mereka tidak mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 26, "text": "لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ ۝٢٦", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "لله- سبحانه- كل ما في السموات والأرض ملكًا وعبيدًا وإيجادًا وتقديرًا، فلا يستحق العبادة أحد غيره. إن الله هو الغني عن خلقه، له الحمد والثناء على كل حال.", "isBasmala": false, "translation_en": "To God belongs everything in the heavens and the earth. God is the Rich, the Praised.", "translation_id": "Kepunyaan Allah-lah apa yang di langit dan yang di bumi. Sesungguhnya Allah Dialah Yang Maha Kaya lagi Maha Terpuji.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 27, "text": "وَلَوۡ أَنَّمَا فِی ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَـٰمࣱ وَٱلۡبَحۡرُ یَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرࣲ مَّا نَفِدَتۡ كَلِمَـٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ ۝٢٧", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ولو أن أشجار الأرض كلها بُريت أقلامًا والبحر مداد لها، ويُمَد بسبعة أبحر أخرى، وكُتِب بتلك الأقلام وذلك المداد كلمات الله، لتكسرت تلك الأقلام، ولنفِد ذلك المداد، ولم تنفد كلمات الله التامة التي لا يحيط بها أحد. إن الله عزيز في انتقامه ممن أشرك به، حكيم في تدبير خلقه. وفي الآية إثبات صفة الكلام لله- تعالى- حقيقة كما يليق بجلاله وكماله سبحانه.", "isBasmala": false, "translation_en": "If all the trees on earth were pens, filled by the ocean, with seven more oceans besides, the Words of God would not run out. God is Majestic and Wise.", "translation_id": "Dan seandainya pohon-pohon di bumi menjadi pena dan laut (menjadi tinta), ditambahkan kepadanya tujuh laut (lagi) sesudah (kering)nya, niscaya tidak akan habis-habisnya (dituliskan) kalimat Allah. Sesungguhnya Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 28, "text": "مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسࣲ وَ ٰحِدَةٍۚ إِنَّ ٱللَّهَ سَمِیعُۢ بَصِیرٌ ۝٢٨", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ما خَلْقُكم- أيها الناس- ولا بَعْثُكم يوم القيامة في السهولة واليسر إلا كخَلْق نفس واحدة وبَعْثها، إن الله سميع لأقوالكم، بصير بأعمالكم، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "Your creation and your resurrection are only as a single soul. God is Hearing and Seeing.", "translation_id": "Tidaklah Allah menciptakan dan membangkitkan kamu (dari dalam kubur) itu melainkan hanyalah seperti (menciptakan dan membangkitkan) satu jiwa saja. Sesungguhnya Allah Maha Mendengar lagi Maha Melihat.", "manzil": 5, "manzil_display": ""}], "414": [{"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 29, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِیۤ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِیرࣱ ۝٢٩", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ألم تر أن الله يأخذ من ساعات الليل، فيطول النهار، ويقصر الليل، ويأخذ من ساعات النهار، فيطول الليل، ويقصر النهار، وذلَّل لكم الشمس والقمر، يجري كل منهما في مداره إلى أجل معلوم محدد، وأن الله مُطَّلع على كل أعمال الخلق مِن خير أو شر، لا يخفى عليه منها شيء؟", "isBasmala": false, "translation_en": "Have you not seen how God merges the night into the day, and merges the day into the night? That He subjected the sun and the moon, each running for a stated term? And that God is Cognizant of everything you do?", "translation_id": "Tidakkah kamu memperhatikan, bahwa sesungguhnya Allah memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam dan Dia tundukkan matahari dan bulan masing-masing berjalan sampai kepada waktu yang ditentukan, dan sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 30, "text": "ذَ ٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا یَدۡعُونَ مِن دُونِهِ ٱلۡبَـٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِیُّ ٱلۡكَبِیرُ ۝٣٠", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ذلك كله من عظيم قدرتي؛ لتعلموا وتقروا أن الله هو الحق في ذاته وصفاته، وأفعاله، وأن ما يدعون من دونه الباطل، وأن الله هو العلي بذاته وقَدْره وقهره فوق جميع مخلوقاته، الكبير على كل شيء، وكل ما عداه خاضع له، فهو وحده المستحق أن يُعبد دون مَن سواه.", "isBasmala": false, "translation_en": "That is because God is the Reality, and what they worship besides Him is falsehood, and because God is the Exalted, the Supreme.", "translation_id": "Demikianlah, karena sesungguhnya Allah, Dialah yang hak dan sesungguhnya apa saja yang mereka seru selain dari Allah itulah yang batil; dan sesungguhnya Allah Dialah Yang Maha Tinggi lagi Maha Besar.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 31, "text": "أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِی فِی ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِیُرِیَكُم مِّنۡ ءَایَـٰتِهِۦۤۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ ۝٣١", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ألم تر- أيها المشاهد- أن السفن تجري في البحر بأمر الله نعمة منه على خلقه؛ ليريكم من عبره وحججه عليكم ما تعتبرون به؟ إن في جرْي السفن في البحر لَدلالات لكل صبَّار عن محارم الله، شكور لنعمه.", "isBasmala": false, "translation_en": "Have you not seen how the ships sail through the sea, by the grace of God, to show you of His wonders? In that are signs for every persevering, thankful person.", "translation_id": "Tidakkah kamu memperhatikan bahwa sesungguhnya kapal itu berlayar di laut dengan nikmat Allah, supaya diperlihatkan-Nya kepadamu sebahagian dari tanda-tanda (kekuasaan)-Nya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda bagi semua orang yang sangat sabar lagi banyak bersyukur.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 32, "text": "وَإِذَا غَشِیَهُم مَّوۡجࣱ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدࣱۚ وَمَا یَجۡحَدُ بِـَٔایَـٰتِنَاۤ إِلَّا كُلُّ خَتَّارࣲ كَفُورࣲ ۝٣٢", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "وإذا ركب المشركون السفن وعَلَتْهم الأمواج مِن حولهم كالسحب والجبال، أصابهم الخوف والذعر من الغرق ففزعوا إلى الله، وأخلصوا دعاءهم له، فلما نجاهم إلى البر فمنهم متوسط لم يقم بشكر الله على وجه الكمال، ومنهم كافر بنعمة الله جاحد لها، وما يكفر بآياتنا وحججنا الدالة على كمال قدرتنا ووحدانيتنا إلا كل غدَّار ناقض للعهد، جحود لنعم الله عليه.", "isBasmala": false, "translation_en": "When waves, like canopies, cover them, they call upon God, devoting their religion to Him. But when He has delivered them to dry land, some of them waver. No one renounces Our revelations except the treacherous blasphemer.", "translation_id": "Dan apabila mereka dilamun ombak yang besar seperti gunung, mereka menyeru Allah dengan memurnikan ketaatan kepada-Nya maka tatkala Allah menyelamatkan mereka sampai di daratan, lalu sebagian mereka tetap menempuh jalan yang lurus. Dan tidak ada yang mengingkari ayat-ayat Kami selain orang-orang yang tidak setia lagi ingkar.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 33, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمۡ وَٱخۡشَوۡا۟ یَوۡمࣰا لَّا یَجۡزِی وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَیۡـًٔاۚ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَلَا یَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ۝٣٣", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "يا أيها الناس اتقوا ربكم، وأطيعوه بامتثال أوامره واجتناب نواهيه، واحذروا يوم القيامة الذي لا يغني فيه والد عن ولده ولا مولود عن أبيه شيئًا، إن وعد الله حق لا ريب فيه، فلا تنخدعوا بالحياة الدنيا وزخرفها فتنسيكم الأخرى، ولا يخدعنكم بالله خادع من شياطين الجن والإنس.", "isBasmala": false, "translation_en": "O people! Be conscious of your Lord, and dread a Day when no parent can avail his child, nor can a child avail his parent, in anything. The promise of God is true. Therefore, do not let this life deceive you, nor let illusions deceive you regarding God.", "translation_id": "Hai manusia, bertakwalah kepada Tuhanmu dan takutilah suatu hari yang (pada hari itu) seorang bapak tidak dapat menolong anaknya dan seorang anak tidak dapat (pula) menolong bapaknya sedikitpun. Sesungguhnya janji Allah adalah benar, maka janganlah sekali-kali kehidupan dunia memperdayakan kamu, dan jangan (pula) penipu (syaitan) memperdayakan kamu dalam (mentaati) Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 31, "sura_name": "لقمان", "revelation": "Makkiyah", "aya": 34, "text": "إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَیُنَزِّلُ ٱلۡغَیۡثَ وَیَعۡلَمُ مَا فِی ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِی نَفۡسࣱ مَّاذَا تَكۡسِبُ غَدࣰاۖ وَمَا تَدۡرِی نَفۡسُۢ بِأَیِّ أَرۡضࣲ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِیمٌ خَبِیرُۢ ۝٣٤", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "إن الله- وحده لا غيره- يعلم متى تقوم الساعة؟ وهو الذي ينزل المطر من السحاب، لا يقدر على ذلك أحد غيره، ويعلم ما في أرحام الإناث، ويعلم ما تكسبه كل نفس في غدها، وما تعلم نفس بأيِّ أرض تموت. بل الله تعالى هو المختص بعلم ذلك جميعه. إن الله عليم خبير محيط بالظواهر والبواطن، لا يخفى عليه شيء منها.", "isBasmala": false, "translation_en": "With God rests the knowledge of the Hour. He sends down the rain, and He knows what the wombs contain. No soul knows what it will reap tomorrow, and no soul knows in what land it will die. God is All-Knowing, Well-Informed.", "translation_id": "Sesungguhnya Allah, hanya pada sisi-Nya sajalah pengetahuan tentang Hari Kiamat; dan Dialah Yang menurunkan hujan, dan mengetahui apa yang ada dalam rahim. Dan tiada seorangpun yang dapat mengetahui (dengan pasti) apa yang akan diusahakannya besok. Dan tiada seorangpun yang dapat mengetahui di bumi mana dia akan mati. Sesungguhnya Allah Maha Mengetahui lagi Maha Mengenal.", "manzil": 5, "manzil_display": ""}], "415": [{"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 21, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 1, "text": "الۤمۤ ۝١", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "(الم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Alif, Lam, Meem.", "translation_id": "Alif Laam Miim", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 2, "text": "تَنزِیلُ ٱلۡكِتَـٰبِ لَا رَیۡبَ فِیهِ مِن رَّبِّ ٱلۡعَـٰلَمِینَ ۝٢", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "هذا القرآن الذي جاء به محمد صلى الله عليه وسلم لا شك أنه منزل من عند الله، رب الخلائق أجمعين.", "isBasmala": false, "translation_en": "The revelation of the Book, without a doubt, is from the Lord of the Universe.", "translation_id": "Turunnya Al-Quran yang tidak ada keraguan di dalamnya, (adalah) dari Tuhan semesta alam.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 3, "text": "أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمࣰا مَّاۤ أَتَىٰهُم مِّن نَّذِیرࣲ مِّن قَبۡلِكَ لَعَلَّهُمۡ یَهۡتَدُونَ ۝٣", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "بل أيقول المشركون: اختلق محمد صلى الله عليه وسلم القرآن؟ كذَبوا، بل هو الحق الثابت المنزل عليك -أيها الرسول- من ربك؛ لتنذر به أناسًا لم يأتهم نذير من قبلك، لعلهم يهتدون، فيعرفوا الحق ويؤمنوا به ويؤثروه، ويؤمنوا بك.", "isBasmala": false, "translation_en": "Yet they say, \"He made it up.\" In fact, it is the Truth from your Lord, to warn a people who received no warner before you, that they may be guided.", "translation_id": "Tetapi mengapa mereka (orang kafir) mengatakan: \"Dia Muhammad mengada-adakannya\". Sebenarnya Al-Quran itu adalah kebenaran dari Rabbmu, agar kamu memberi peringatan kepada kaum yang belum datang kepada mereka orang yang memberi peringatan sebelum kamu; mudah-mudahan mereka mendapat petunjuk.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 4, "text": "ٱللَّهُ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِیࣲّ وَلَا شَفِیعٍۚ أَفَلَا تَتَذَكَّرُونَ ۝٤", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "الله الذي خلق السموات والأرض وما بينهما في ستة أيام لحكمة يعلمها، وهو قادر أن يخلقها بكلمة \"كن\" فتكون، ثم استوى سبحانه وتعالى -أي علا وارتفع- على عرشه استواء يليق بجلاله، لا يكيَّف، ولا يشبَّه باستواء المخلوقين. ليس لكم -أيها الناس- من وليٍّ يلي أموركم، أو شفيع يشفع لكم عند الله؛ لتنجوا من عذابه، أفلا تتعظون وتتفكرون -أيها الناس-، فتُفردوا الله بالألوهية وتُخلصوا له العبادة؟", "isBasmala": false, "translation_en": "God is He who created the heavens and the earth and everything between them in six days, and then established Himself on the Throne. Apart from Him, you have no master and no intercessor. Will you not reflect?", "translation_id": "Allah lah yang menciptakan langit dan bumi dan apa yang ada di antara keduanya dalam enam masa, kemudian Dia bersemayam di atas 'Arsy. Tidak ada bagi kamu selain dari pada-Nya seorang penolongpun dan tidak (pula) seorang pemberi syafa'at. Maka apakah kamu tidak memperhatikan?", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 5, "text": "یُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَاۤءِ إِلَى ٱلۡأَرۡضِ ثُمَّ یَعۡرُجُ إِلَیۡهِ فِی یَوۡمࣲ كَانَ مِقۡدَارُهُۥۤ أَلۡفَ سَنَةࣲ مِّمَّا تَعُدُّونَ ۝٥", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "يدبر الله تعالى أَمْر المخلوقات من السماء إلى الأرض، ثم يصعد ذلك الأمر والتدبير إلى الله في يوم مقداره ألف سنة من أيام الدنيا التي تعدُّونها.", "isBasmala": false, "translation_en": "He regulates all affairs, from the heavens, to the earth. Then it ascends to Him on a Day the length of which is a thousand years by your count.", "translation_id": "Dia mengatur urusan dari langit ke bumi, kemudian (urusan) itu naik kepada-Nya dalam satu hari yang kadarnya adalah seribu tahun menurut perhitunganmu", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 6, "text": "ذَ ٰلِكَ عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝٦", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ذلك الخالق المدبِّر لشؤون العالمين، عالم بكل ما يغيب عن الأبصار، مما تُكِنُّه الصدور وتخفيه النفوس، وعالم بما شاهدته الأبصار، وهو القويُّ الظاهر الذي لا يغالَب، الرحيم بعباده المؤمنين.", "isBasmala": false, "translation_en": "That is the Knower of the Invisible and the Visible, the Powerful, the Merciful.", "translation_id": "Yang demikian itu ialah Tuhan Yang mengetahui yang ghaib dan yang nyata, Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 7, "text": "ٱلَّذِیۤ أَحۡسَنَ كُلَّ شَیۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَـٰنِ مِن طِینࣲ ۝٧", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "الله الذي أحكم خلق كل شيء، وبدأ خَلْقَ الإنسان، وهو آدم عليه السلام من طين.", "isBasmala": false, "translation_en": "He who perfected everything He created, and originated the creation of man from clay.", "translation_id": "Yang membuat segala sesuatu yang Dia ciptakan sebaik-baiknya dan Yang memulai penciptaan manusia dari tanah.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 8, "text": "ثُمَّ جَعَلَ نَسۡلَهُۥ مِن سُلَـٰلَةࣲ مِّن مَّاۤءࣲ مَّهِینࣲ ۝٨", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ثم جعل ذرية آدم متناسلة من نطفة ضعيفة رقيقة مهينة.", "isBasmala": false, "translation_en": "Then made his reproduction from an extract of an insignificant fluid.", "translation_id": "Kemudian Dia menjadikan keturunannya dari saripati air yang hina.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 9, "text": "ثُمَّ سَوَّىٰهُ وَنَفَخَ فِیهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ ۝٩", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "ثم أتم خلق الإنسان وأبدعه، وأحسن خلقته، ونفخ فيه مِن روحه بإرسال الملك له؛ لينفخ فيه الروح، وجعل لكم -أيها الناس- نعمة السمع والأبصار يُميَّز بها بين الأصوات والألوان والذوات والأشخاص، ونعمة العقل يُميَّز بها بين الخير والشر والنافع والضار. قليلا ما تشكرون ربكم على ما أنعم به عليكم.", "isBasmala": false, "translation_en": "Then He proportioned him, and breathed into him of His Spirit. Then He gave you the hearing, and the eyesight, and the brains-but rarely do you give thanks.", "translation_id": "Kemudian Dia menyempurnakan dan meniupkan ke dalamnya roh (ciptaan)-Nya dan Dia menjadikan bagi kamu pendengaran, penglihatan dan hati; (tetapi) kamu sedikit sekali bersyukur.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 10, "text": "وَقَالُوۤا۟ أَءِذَا ضَلَلۡنَا فِی ٱلۡأَرۡضِ أَءِنَّا لَفِی خَلۡقࣲ جَدِیدِۭۚ بَلۡ هُم بِلِقَاۤءِ رَبِّهِمۡ كَـٰفِرُونَ ۝١٠", "juz": 21, "hizb": "(* ح 42*)", "tafsir": "وقال المشركون بالله المكذبون بالبعث: أإذا صارت لحومنا وعظامنا ترابًا في الأرض أنُبعَث خلقًا جديدًا؟ يستبعدون ذلك غير طالبين الوصول إلى الحق، وإنما هو منهم ظلم وعناد؛ لأنهم بلقاء ربهم -يوم القيامة- كافرون.", "isBasmala": false, "translation_en": "And they say, \"When we are lost into the earth, shall we be in a new creation?\" In fact, they deny the meeting with their Lord.", "translation_id": "Dan mereka berkata: \"Apakah bila kami telah lenyap (hancur) dalam tanah, kami benar-benar akan berada dalam ciptaan yang baru?\" Bahkan mereka ingkar akan menemui Tuhannya.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 11, "text": "۞ قُلۡ یَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِی وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ ۝١١", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: يتوفاكم ملك الموت الذي وُكِّل بكم، فيقبض أرواحكم إذا انتهت آجالكم، ولن تتأخروا لحظة واحدة، ثم تُردُّون إلى ربكم، فيجازيكم على جميع أعمالكم: إن خيرًا فخير وإن شرًا فشر.", "isBasmala": false, "translation_en": "Say, \"The angel of death put in charge of you will reclaim you. Then to your Lord you will be returned.\"", "translation_id": "Katakanlah: \"Malaikat maut yang diserahi untuk (mencabut nyawa)mu akan mematikanmu, kemudian hanya kepada Tuhanmulah kamu akan dikembalikan\".", "manzil": 5, "manzil_display": ""}], "416": [{"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 12, "text": "وَلَوۡ تَرَىٰۤ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُوا۟ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَاۤ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَـٰلِحًا إِنَّا مُوقِنُونَ ۝١٢", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "ولو ترى -أيها المخاطب- إذ المجرمون الذين أنكروا البعث قد خفضوا رؤوسهم عند ربهم من الخزي والعار قائلين: ربنا أبصرنا قبائحنا، وسمعنا منك تصديق ما كانت رسلك تأمرنا به في الدنيا، وقد تُبْنا إليك، فارجعنا إلى الدنيا لنعمل فيها بطاعتك، إنا قد أيقنَّا الآن ما كنا به في الدنيا مكذبين من وحدانيتك، وأنك تبعث من في القبور. ولو رأيت -أيها الخاطب- ذلك كله، لرأيت أمرًا عظيمًا، وخطبًا جسيمًا.", "isBasmala": false, "translation_en": "If only you could see the guilty, bowing their heads before their Lord: \"Our Lord, we have seen and we have heard, so send us back, and we will act righteously; we are now convinced.\"", "translation_id": "Dan, jika sekiranya kamu melihat mereka ketika orang-orang yang berdosa itu menundukkan kepalanya di hadapan Tuhannya, (mereka berkata): \"Ya Tuhan kami, kami telah melihat dan mendengar, maka kembalikanlah kami (ke dunia), kami akan mengerjakan amal saleh, sesungguhnya kami adalah orang-orang yang yakin\".", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 13, "text": "وَلَوۡ شِئۡنَا لَـَٔاتَیۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَـٰكِنۡ حَقَّ ٱلۡقَوۡلُ مِنِّی لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِینَ ۝١٣", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "ولو شئنا لآتينا هؤلاء المشركين بالله رشدهم وتوفيقهم للإيمان، ولكن حق القول مني ووجب لأملأنَّ جهنم من أهل الكفر والمعاصي، من الجِنَّة والناس أجمعين؛ وذلك لاختيارهم الضلالة على الهدى.", "isBasmala": false, "translation_en": "Had We willed, We could have given every soul its guidance, but the declaration from Me will come true: \"I will fill Hell with jinn and humans, altogether.\"", "translation_id": "Dan kalau Kami menghendaki niscaya Kami akan berikan kepada tiap-tiap jiwa petunjuk, akan tetapi telah tetaplah perkataan dari pada-Ku: \"Sesungguhnya akan Aku penuhi neraka jahannam itu dengan jin dan manusia bersama-sama\".", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 14, "text": "فَذُوقُوا۟ بِمَا نَسِیتُمۡ لِقَاۤءَ یَوۡمِكُمۡ هَـٰذَاۤ إِنَّا نَسِینَـٰكُمۡۖ وَذُوقُوا۟ عَذَابَ ٱلۡخُلۡدِ بِمَا كُنتُمۡ تَعۡمَلُونَ ۝١٤", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "يقال لهؤلاء المشركين -عند دخولهم النار-: فذوقوا العذاب؛ بسبب غفلتكم عن الآخرة وانغماسكم في لذائذ الدنيا، إنا تركناكم اليوم في العذاب، وذوقوا عذاب جهنم الذي لا ينقطع؛ بما كنتم تعملون في الدنيا من الكفر بالله ومعاصيه.", "isBasmala": false, "translation_en": "So taste, because you forgot the meeting of this Day of yours; We have forgotten you; so taste the eternal torment for what you used to do.", "translation_id": "Maka rasailah olehmu (siksa ini) disebabkan kamu melupakan akan pertemuan dengan harimu ini. Sesungguhnya Kami telah melupakan kamu (pula) dan rasakanlah siksa yang kekal, disebabkan apa yang selalu kamu kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 15, "text": "إِنَّمَا یُؤۡمِنُ بِـَٔایَـٰتِنَا ٱلَّذِینَ إِذَا ذُكِّرُوا۟ بِهَا خَ̅رُّ̅و̅ا۟̅ ̅سُ̅جَّ̅دࣰ̅ا̅ وَسَبَّحُوا۟ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا یَسۡتَكۡبِرُونَ ۝١٥ ۩", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "إنما يصدق بآيات القرآن ويعمل بها الذين إذا وُعِظوا بها أو تُليت عليهم سجدوا لربهم خاشعين مطيعين، وسبَّحوا الله في سجودهم بحمده، وهم لا يستكبرون عن السجود والتسبيح له، وعبادته وحده لا شريك له.", "isBasmala": false, "translation_en": "They believe in Our communications, those who, when reminded of them, fall down prostrate, and glorify their Lord with praise, and are not proud.", "translation_id": "Sesungguhnya orang yang benar-benar percaya kepada ayat-ayat Kami adalah mereka yang apabila diperingatkan dengan ayat-ayat itu mereka segera bersujud seraya bertasbih dan memuji Rabbnya, dan lagi pula mereka tidaklah sombong.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 16, "text": "تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ یَدۡعُونَ رَبَّهُمۡ خَوۡفࣰا وَطَمَعࣰا وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ ۝١٦", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "ترتفع جنوب هؤلاء الذين يؤمنون بآيات الله عن فراش النوم، يتهجدون لربهم في صلاة الليل، يدعون ربهم خوفًا من العذاب وطمعًا في الثواب، ومما رزقناهم ينفقون في طاعة الله وفي سبيله.", "isBasmala": false, "translation_en": "Their sides shun their beds, as they pray to their Lord, out of reverence and hope; and from Our provisions to them, they give.", "translation_id": "Lambung mereka jauh dari tempat tidurnya dan mereka selalu berdoa kepada Rabbnya dengan penuh rasa takut dan harap, serta mereka menafkahkan apa apa rezeki yang Kami berikan.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 17, "text": "فَلَا تَعۡلَمُ نَفۡسࣱ مَّاۤ أُخۡفِیَ لَهُم مِّن قُرَّةِ أَعۡیُنࣲ جَزَاۤءَۢ بِمَا كَانُوا۟ یَعۡمَلُونَ ۝١٧", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "فلا تعلم نفس ما ادَّخر الله لهؤلاء المؤمنين مما تَقَرُّ به العين، وينشرح له الصدر؛ جزاء لهم على أعمالهم الصالحة.", "isBasmala": false, "translation_en": "No soul knows what eye's delight awaits them-a reward for what they used to do.", "translation_id": "Tak seorangpun mengetahui berbagai nikmat yang menanti, yang indah dipandang sebagai balasan bagi mereka, atas apa yang mereka kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 18, "text": "أَفَمَن كَانَ مُؤۡمِنࣰا كَمَن كَانَ فَاسِقࣰاۚ لَّا یَسۡتَوُۥنَ ۝١٨", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "أفمن كان مطيعًا لله ورسوله مصدقًا بوعده ووعيده، مثل من كفر بالله ورسله وكذب باليوم الآخر؟ لا يستوون عند الله.", "isBasmala": false, "translation_en": "Is someone who is faithful like someone who is a sinner? They are not equal.", "translation_id": "Apakah orang-orang beriman itu sama dengan orang-orang yang fasik? Mereka tidak sama.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 19, "text": "أَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمۡ جَنَّـٰتُ ٱلۡمَأۡوَىٰ نُزُلَۢا بِمَا كَانُوا۟ یَعۡمَلُونَ ۝١٩", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "أما الذين آمنوا بالله وعملوا بما أُمِروا به فجزاؤهم جنات يأوون إليها، ويقيمون في نعيمها ضيافة لهم؛ جزاءً لهم بما كانوا يعملون في الدنيا بطاعته.", "isBasmala": false, "translation_en": "As for those who believe and do righteous deeds, for them are the Gardens of Shelter-hospitality for what they used to do.", "translation_id": "Adapun orang-orang yang beriman dan mengerjakan amal saleh, maka bagi mereka jannah tempat kediaman, sebagai pahala terhadap apa yang mereka kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 20, "text": "وَأَمَّا ٱلَّذِینَ فَسَقُوا۟ فَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَاۤ أَرَادُوۤا۟ أَن یَخۡرُجُوا۟ مِنۡهَاۤ أُعِیدُوا۟ فِیهَا وَقِیلَ لَهُمۡ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّذِی كُنتُم بِهِۦ تُكَذِّبُونَ ۝٢٠", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "وأما الذين خرجوا عن طاعة الله وعملوا بمعاصيه فمستقرهم جهنم، كلما أرادوا أن يخرجوا منها أعيدوا فيها، وقيل لهم -توبيخا وتقريعا-: ذوقوا عذاب النار الذي كنتم به تكذبون في الدنيا.", "isBasmala": false, "translation_en": "But as for those who transgressed, their shelter is the Fire. Every time they try to get out of it, they will be brought back into it, and it will be said to them, \"Taste the suffering of the Fire which you used to deny.\"", "translation_id": "Dan adapun orang-orang yang fasik (kafir) maka tempat mereka adalah jahannam. Setiap kali mereka hendak keluar daripadanya, mereka dikembalikan ke dalamnya dan dikatakan kepada mereka: \"Rasakanlah siksa neraka yang dahulu kamu mendustakannya\".", "manzil": 5, "manzil_display": ""}], "417": [{"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 21, "text": "وَلَنُذِیقَنَّهُم مِّنَ ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ دُونَ ٱلۡعَذَابِ ٱلۡأَكۡبَرِ لَعَلَّهُمۡ یَرۡجِعُونَ ۝٢١", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "ولنذيقن هؤلاء الفاسقين المكذبين من العذاب الأدنى من البلاء والمحن والمصائب في الدنيا قبل العذاب الأكبر يوم القيامة، حيث يُعذَّبون في نار جهنم؛ لعلهم يرجعون ويتوبون من ذنوبهم.", "isBasmala": false, "translation_en": "We will make them taste the lesser torment, prior to the greater torment, so that they may return.", "translation_id": "Dan Sesungguhnya Kami merasakan kepada mereka sebahagian azab yang dekat (di dunia) sebelum azab yang lebih besar (di akhirat), mudah-mudahan mereka kembali (ke jalan yang benar).", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 22, "text": "وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔایَـٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَاۤۚ إِنَّا مِنَ ٱلۡمُجۡرِمِینَ مُنتَقِمُونَ ۝٢٢", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "ولا أحد أشد ظلمًا لنفسه ممن وعظ بدلائل الله، ثم أعرض عن ذلك كله، فلم يتعظ بمواعظه، ولكنه استكبر عنها، إنا من المجرمين الذين أعرضوا عن آيات الله وحججه، ولم ينتفعوا بها، منتقمون.", "isBasmala": false, "translation_en": "Who is more wrong than he, who, when reminded of his Lord's revelations, turns away from them? We will certainly wreak vengeance upon the criminals.", "translation_id": "Dan siapakah yang lebih zalim daripada orang yang telah diperingatkan dengan ayat-ayat Tuhannya, kemudian ia berpaling daripadanya? Sesungguhnya Kami akan memberikan pembalasan kepada orang-orang yang berdosa.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 23, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ فَلَا تَكُن فِی مِرۡیَةࣲ مِّن لِّقَاۤىِٕهِۦۖ وَجَعَلۡنَـٰهُ هُدࣰى لِّبَنِیۤ إِسۡرَ ٰۤءِیلَ ۝٢٣", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "ولقد آتينا موسى التوراة كما آتيناك -أيها الرسول- القرآن، فلا تكن في شك من لقاء موسى ليلة الإسراء والمعراج، وجعلنا التوراة هداية لبني إسرائيل، تدعوهم إلى الحق وإلى طريق مستقيم.", "isBasmala": false, "translation_en": "We gave Moses the Book; so do not be in doubt regarding His encounter; and We made it a guidance for the Children of Israel.", "translation_id": "Dan Sesungguhnya Kami telah berikan kepada Musa Al-Kitab (Taurat), maka janganlah kamu (Muhammad) ragu menerima (Al-Quran itu) dan Kami jadikan Al-Kitab (Taurat) itu petunjuk bagi Bani Israil.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 24, "text": "وَجَعَلۡنَا مِنۡهُمۡ أَىِٕمَّةࣰ یَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُوا۟ۖ وَكَانُوا۟ بِـَٔایَـٰتِنَا یُوقِنُونَ ۝٢٤", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "وجعلنا من بني إسرائيل هداة ودعاة إلى الخير، يأتمُّ بهم الناس، ويدعونهم إلى التوحيد وعبادة الله وحده وطاعته، وإنما نالوا هذه الدرجة العالية حين صبروا على أوامر الله، وترك زواجره، والدعوة إليه، وتحمُّل الأذى في سبيله، وكانوا بآيات الله وحججه يوقنون.", "isBasmala": false, "translation_en": "And We appointed leaders from among them, guiding by Our command, as long as they persevered and were certain of Our communications.", "translation_id": "Dan Kami jadikan di antara mereka itu pemimpin-pemimpin yang memberi petunjuk dengan perintah Kami ketika mereka sabar. Dan adalah mereka meyakini ayat-ayat Kami.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 25, "text": "إِنَّ رَبَّكَ هُوَ یَفۡصِلُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ ۝٢٥", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "إن ربك -أيها الرسول- يقضي بين المؤمنين والكافرين من بني إسرائيل وغيرهم يوم القيامة بالعدل فيما اختلفوا فيه من أمور الدين، ويجازي كل إنسان بعمله بإدخال أهلِ الجنةِ الجنةَ وأهلِ النارِ النارَ.", "isBasmala": false, "translation_en": "Your Lord will judge between them on the Day of Resurrection regarding everything they had disputed.", "translation_id": "Sesungguhnya Tuhanmu Dialah yang memberikan keputusan di antara mereka pada hari kiamat tentang apa yang selalu mereka perselisihkan padanya.", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 26, "text": "أَوَ لَمۡ یَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ یَمۡشُونَ فِی مَسَـٰكِنِهِمۡۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتٍۚ أَفَلَا یَسۡمَعُونَ ۝٢٦", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "أولم يتبين لهؤلاء المكذبين للرسول: كم أهلكنا من قبلهم من الأمم السابقة يمشون في مساكنهم، فيشاهدونها عِيانًا كقوم هود وصالح ولوط؟ إن في ذلك لآيات وعظات يُستدَلُّ بها على صدق الرسل التي جاءتهم، وبطلان ما هم عليه من الشرك، أفلا يسمع هؤلاء المكذبون بالرسل مواعظ الله وحججه، فينتفعون بها؟", "isBasmala": false, "translation_en": "Is it not a lesson for them, how many generations We have destroyed before them, in whose habitations they walk? Surely in that are signs. Do they not hear?", "translation_id": "Dan apakah tidak menjadi petunjuk bagi mereka, berapa banyak umat sebelum mereka yang telah Kami binasakan sedangkan mereka sendiri berjalan di tempat-tempat kediaman mereka itu. Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kekuasaan Allah). Maka apakah mereka tidak mendengarkan?", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 27, "text": "أَوَ لَمۡ یَرَوۡا۟ أَنَّا نَسُوقُ ٱلۡمَاۤءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ بِهِۦ زَرۡعࣰا تَأۡكُلُ مِنۡهُ أَنۡعَـٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا یُبۡصِرُونَ ۝٢٧", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "أولم ير المكذبون بالبعث بعد الموت أننا نسوق الماء إلى الأرض اليابسة الغليظة التي لا نبات فيها، فنخرج به زرعًا مختلفًا ألوانه تأكل منه أنعامهم، وتتغذى به أبدانهم فيعيشون به؟ أفلا يرون هذه النعم بأعينهم، فيعلموا أن الله الذي فعل ذلك قادر على إحياء الأموات ونَشْرهم من قبورهم؟", "isBasmala": false, "translation_en": "Do they not see how We conduct the water to a dry land, and with it We produce vegetation, from which their livestock eat, and themselves? Do they not see?", "translation_id": "Dan apakah mereka tidak memperhatikan, bahwasanya Kami menghalau (awan yang mengandung) air ke bumi yang tandus, lalu Kami tumbuhkan dengan air hujan itu tanaman yang daripadanya makan hewan ternak mereka dan mereka sendiri. Maka apakah mereka tidak memperhatikan?", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 28, "text": "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡفَتۡحُ إِن كُنتُمۡ صَـٰدِقِینَ ۝٢٨", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "يستعجل هؤلاء المشركون بالله العذاب، فيقولون: متى هذا الحكم الذي يقضي بيننا وبينكم بتعذيبنا على زعمكم إن كنتم صادقين في دعواكم؟", "isBasmala": false, "translation_en": "And they say, \"When is this victory, if you are truthful?\"", "translation_id": "Dan mereka bertanya: \"Bilakah kemenangan itu (datang) jika kamu memang orang-orang yang benar?\"", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 29, "text": "قُلۡ یَوۡمَ ٱلۡفَتۡحِ لَا یَنفَعُ ٱلَّذِینَ كَفَرُوۤا۟ إِیمَـٰنُهُمۡ وَلَا هُمۡ یُنظَرُونَ ۝٢٩", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "قل لهم -أيها الرسول-: يوم القضاء الذي يقع فيه عقابكم، وتعاينون فيه الموت لا ينفع الكفار إيمانهم، ولا هم يؤخرون للتوبة والمراجعة.", "isBasmala": false, "translation_en": "Say, \"On the day of victory, the faith of those who disbelieved will be of no avail to them, and they will not be granted respite.\"", "translation_id": "Katakanlah: \"Pada hari kemenangan itu tidak berguna bagi orang-orang kafir, iman mereka dan tidak pula mereka diberi tangguh\".", "manzil": 5, "manzil_display": ""}, {"sura": 32, "sura_name": "السجدة", "revelation": "Makkiyah", "aya": 30, "text": "فَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ ۝٣٠", "juz": 21, "hizb": "(*¼ ح 42*)", "tafsir": "فأعرض -أيها الرسول- عن هؤلاء المشركين، ولا تبال بتكذيبهم، وانتظر ما الله صانع بهم، إنهم منتظرون ومتربصون بكم دوائر السوء، فسيخزيهم الله ويذلهم، وينصرك عليهم. وقد فعل فله الحمد والمنة.", "isBasmala": false, "translation_en": "So turn away from them, and wait. They too are waiting.", "translation_id": "Maka berpalinglah kamu dari mereka dan tunggulah, sesungguhnya mereka (juga) menunggu.", "manzil": 5, "manzil_display": ""}], "418": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 22, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 1, "text": "۞ یَـٰۤأَیُّهَا ٱلنَّبِیُّ ٱتَّقِ ٱللَّهَ وَلَا تُطِعِ ٱلۡكَـٰفِرِینَ وَٱلۡمُنَـٰفِقِینَۚ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا ۝١", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "يا أيها النبي دُم على تقوى الله بالعمل بأوامره واجتناب محارمه، وليقتد بك المؤمنون؛ لأنهم أحوج إلى ذلك منك، ولا تطع الكافرين وأهل النفاق. إن الله كان عليمًا بكل شيء، حكيمًا في خلقه وأمره وتدبيره.", "isBasmala": false, "translation_en": "O Prophet! Fear God, and do not obey the unbelievers and the hypocrites. God is Knowledgeable and Wise.", "translation_id": "Hai Nabi, bertakwalah kepada Allah dan janganlah kamu menuruti (keinginan) orang-orang kafir dan orang-orang munafik. Sesungguhnya Allah adalah Maha Mengetahui lagi Maha Bijaksana,", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 2, "text": "وَٱتَّبِعۡ مَا یُوحَىٰۤ إِلَیۡكَ مِن رَّبِّكَۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِیرࣰا ۝٢", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "واتبع ما يوحى إليك من ربك من القرآن والسنة، إن الله مطَّلِع على كل ما تعملون ومجازيكم به، لا يخفى عليه شيء من ذلك.", "isBasmala": false, "translation_en": "And follow what is revealed to you from your Lord. God is fully aware of what you do.", "translation_id": "dan ikutilah apa yang diwahyukan Tuhan kepadamu. Sesungguhnya Allah adalah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 3, "text": "وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلࣰا ۝٣", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "واعتمد على ربك، وفَوِّضْ جميع أمورك إليه، وحسبك به حافظًا لمن توكل عليه وأناب إليه.", "isBasmala": false, "translation_en": "And put your trust in God. God is enough as a trustee.", "translation_id": "dan bertawakkallah kepada Allah. Dan cukuplah Allah sebagai Pemelihara.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 4, "text": "مَّا جَعَلَ ٱللَّهُ لِرَجُلࣲ مِّن قَلۡبَیۡنِ فِی جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَ ٰجَكُمُ ٱلَّـٰۤـِٔی تُظَـٰهِرُونَ مِنۡهُنَّ أُمَّهَـٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِیَاۤءَكُمۡ أَبۡنَاۤءَكُمۡۚ ذَ ٰلِكُمۡ قَوۡلُكُم بِأَفۡوَ ٰهِكُمۡۖ وَٱللَّهُ یَقُولُ ٱلۡحَقَّ وَهُوَ یَهۡدِی ٱلسَّبِیلَ ۝٤", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "ما جعل الله لأحد من البشر من قلبين في صدره، وما جعل زوجاتكم اللاتي تظاهرون منهن (في الحرمة) كحرمة أمهاتكم (والظهار أن يقول الرجل لامرأته: أنت عليَّ كظهر أمي، وقد كان هذا طلاقًا في الجاهلية، فبيَّن الله أن الزوجة لا تصير أُمًّا بحال) وما جعل الله الأولاد المتَبَنَّيْنَ أبناء في الشرع، بل إن الظهار والتبني لا حقيقة لهما في التحريم الأبدي، فلا تكون الزوجة المظاهَر منها كالأم في الحرمة، ولا يثبت النسب بالتبني من قول الشخص للدَّعِيِّ: هذا ابني، فهو كلام بالفم لا حقيقة له، ولا يُعتَدُّ به، والله سبحانه يقول الحق ويبيِّن لعباده سبيله، ويرشدهم إلى طريق الرشاد.", "isBasmala": false, "translation_en": "God did not place two hearts inside any man's body. Nor did He make your wives whom you equate with your mothers, your actual mothers. Nor did He make your adopted sons, your actual sons. These are your words coming out of your mouths. God speaks the truth, and guides to the path.", "translation_id": "Allah sekali-kali tidak menjadikan bagi seseorang dua buah hati dalam rongganya; dan Dia tidak menjadikan istri-istrimu yang kamu zhihar itu sebagai ibumu, dan Dia tidak menjadikan anak-anak angkatmu sebagai anak kandungmu (sendiri). Yang demikian itu hanyalah perkataanmu di mulutmu saja. Dan Allah mengatakan yang sebenarnya dan Dia menunjukkan jalan (yang benar).", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 5, "text": "ٱدۡعُوهُمۡ لِـَٔابَاۤىِٕهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوۤا۟ ءَابَاۤءَهُمۡ فَإِخۡوَ ٰنُكُمۡ فِی ٱلدِّینِ وَمَوَ ٰلِیكُمۡۚ وَلَیۡسَ عَلَیۡكُمۡ جُنَاحࣱ فِیمَاۤ أَخۡطَأۡتُم بِهِۦ وَلَـٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمًا ۝٥", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "انسبوا أدعياءكم لآبائهم، هو أعدل وأقوم عند الله، فإن لم تعلموا آباءهم الحقيقيين فادعوهم إذًا بأخوَّة الدين التي تجمعكم بهم، فإنهم إخوانكم في الدين ومواليكم فيه، وليس عليكم إثم فيما وقعتم فيه من خطأ لم تتعمدوه، وإنما يؤاخذكم الله إذا تعمدتم ذلك. وكان الله غفورًا لمن أخطأ، رحيمًا لمن تاب من ذنبه.", "isBasmala": false, "translation_en": "Call them after their fathers; that is more equitable with God. But if you do not know their fathers, then your brethren in faith and your friends. There is no blame on you if you err therein, barring what your hearts premeditates. God is Forgiving and Merciful.", "translation_id": "Panggilah mereka (anak-anak angkat itu) dengan (memakai) nama bapak-bapak mereka; itulah yang lebih adil pada sisi Allah, dan jika kamu tidak mengetahui bapak-bapak mereka, maka (panggilah mereka sebagai) saudara-saudaramu seagama dan maula-maulamu. Dan tidak ada dosa atasmu terhadap apa yang kamu khilaf padanya, tetapi (yang ada dosanya) apa yang disengaja oleh hatimu. Dan adalah Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 6, "text": "ٱلنَّبِیُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِینَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَ ٰجُهُۥۤ أُمَّهَـٰتُهُمۡۗ وَأُو۟لُوا۟ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضࣲ فِی كِتَـٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِینَ وَٱلۡمُهَـٰجِرِینَ إِلَّاۤ أَن تَفۡعَلُوۤا۟ إِلَىٰۤ أَوۡلِیَاۤىِٕكُم مَّعۡرُوفࣰاۚ كَانَ ذَ ٰلِكَ فِی ٱلۡكِتَـٰبِ مَسۡطُورࣰا ۝٦", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "النبي محمد صلى الله عليه وسلم أولى بالمؤمنين، وأقرب لهم من أنفسهم في أمور الدين والدنيا، وحرمة أزواج النبي صلى الله عليه وسلم على أُمَّته كحرمة أمهاتهم، فلا يجوز نكاح زوجات الرسول صلى الله عليه وسلم من بعده. وذوو القرابة من المسلمين بعضهم أحق بميراث بعض في حكم الله وشرعه من الإرث بالإيمان والهجرة (وكان المسلمون في أول الإسلام يتوارثون بالهجرة والإيمان دون الرحم، ثم نُسخ ذلك بآية المواريث) إلا أن تفعلوا -أيها المسلمون- إلى غير الورثة معروفًا بالنصر والبر والصلة والإحسان والوصية، كان هذا الحكم المذكور مقدَّرًا مكتوبًا في اللوح المحفوظ، فيجب عليكم العمل به. وفي الآية وجوب كون النبي صلى الله عليه وسلم أحبَّ إلى العبد من نفسه، ووجوب كمال الانقياد له، وفيها وجوب احترام أمهات المؤمنين، زوجاته صلى الله عليه وسلم، وأن من سبَّهن فقد باء بالخسران.", "isBasmala": false, "translation_en": "The Prophet is more caring of the believers than they are of themselves, and his wives are mothers to them. And blood-relatives are closer to one another in God's Book than the believers or the emigrants, though you should do good to your friends. That is inscribed in the Book.", "translation_id": "Nabi itu (hendaknya) lebih utama bagi orang-orang mukmin dari diri mereka sendiri dan isteri-isterinya adalah ibu-ibu mereka. Dan orang-orang yang mempunyai hubungan darah satu sama lain lebih berhak (waris-mewarisi) di dalam Kitab Allah daripada orang-orang mukmim dan orang-orang Muhajirin, kecuali kalau kamu berbuat baik kepada saudara-saudaramu (seagama). Adalah yang demikian itu telah tertulis di dalam Kitab (Allah).", "manzil": 5, "manzil_display": ""}], "419": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 7, "text": "وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِیِّـۧنَ مِیثَـٰقَهُمۡ وَمِنكَ وَمِن نُّوحࣲ وَإِبۡرَ ٰهِیمَ وَمُوسَىٰ وَعِیسَى ٱبۡنِ مَرۡیَمَۖ وَأَخَذۡنَا مِنۡهُم مِّیثَـٰقًا غَلِیظࣰا ۝٧", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "واذكر -أيها النبي- حين أخذنا من النبيين العهد المؤكد بتبليغ الرسالة، وأخذنا الميثاق منك ومن نوح وإبراهيم وموسى وعيسى ابن مريم (وهم أولو العزم من الرسل على المشهور)، وأخذنا منهم عهدًا مؤكدًا بتبليغ الرسالة وأداء الأمانة، وأن يُصَدِّق بعضهم بعضًا.", "isBasmala": false, "translation_en": "Recall that We received a pledge from the prophets, and from you, and from Noah, and Abraham, and Moses, and Jesus son of Mary. We received from them a solemn pledge.", "translation_id": "Dan (ingatlah) ketika Kami mengambil perjanjian dari nabi-nabi dan dari kamu (sendiri) dari Nuh, Ibrahim, Musa dan Isa putra Maryam, dan Kami telah mengambil dari mereka perjanjian yang teguh.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 8, "text": "لِّیَسۡـَٔلَ ٱلصَّـٰدِقِینَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَـٰفِرِینَ عَذَابًا أَلِیمࣰا ۝٨", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "(أخذ الله ذلك العهد من أولئك الرسل) ليسأل المرسلين عمَّا أجابتهم به أممهم، فيجزي الله المؤمنين الجنة، وأعد للكافرين يوم القيامة عذابًا شديدًا في جهنم.", "isBasmala": false, "translation_en": "That He may ask the sincere about their sincerity. He has prepared for the disbelievers a painful punishment.", "translation_id": "agar Dia menanyakan kepada orang-orang yang benar tentang kebenaran mereka dan Dia menyediakan bagi orang-orang kafir siksa yang pedih.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 9, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱذۡكُرُوا۟ نِعۡمَةَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ جَاۤءَتۡكُمۡ جُنُودࣱ فَأَرۡسَلۡنَا عَلَیۡهِمۡ رِیحࣰا وَجُنُودࣰا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرًا ۝٩", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "يا معشر المؤمنين اذكروا نعمة الله تعالى التي أنعمها عليكم في \"المدينة\" أيام غزوة الأحزاب -وهي غزوة الخندق-، حين اجتمع عليكم المشركون من خارج \"المدينة\"، واليهود والمنافقون من \"المدينة\" وما حولها، فأحاطوا بكم، فأرسلنا على الأحزاب ريحًا شديدة اقتلعت خيامهم ورمت قدورهم، وأرسلنا ملائكة من السماء لم تروها، فوقع الرعب في قلوبهم. وكان الله بما تعملون بصيرًا، لا يخفى عليه من ذلك شيء.", "isBasmala": false, "translation_en": "O you who believe! Remember God's blessings upon you, when forces came against you, and We sent against them a wind, and forces you did not see. God is Observant of what you do.", "translation_id": "Hai orang-orang yang beriman, ingatlah akan nikmat Allah (yang telah dikurniakan) kepadamu ketika datang kepadamu tentara-tentara, lalu Kami kirimkan kepada mereka angin topan dan tentara yang tidak dapat kamu melihatnya. Dan adalah Allah Maha Melihat akan apa yang kamu kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 10, "text": "إِذۡ جَاۤءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَـٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠ ۝١٠", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "اذكروا إذ جاؤوكم مِن فوقكم من أعلى الوادي من جهة المشرق، ومن أسفل منكم من بطن الوادي من جهة المغرب، وإذ شخصت الأبصار من شدة الحَيْرة والدهشة، وبلغت القلوب الحناجر من شدة الرعب، وغلب اليأس المنافقين، وكثرت الأقاويل، وتظنون بالله الظنون السيئة أنه لا ينصر دينه، ولا يعلي كلمته.", "isBasmala": false, "translation_en": "When they came upon you, from above you, and from beneath you; and the eyes became dazed, and the hearts reached the throats, and you harbored doubts about God.", "translation_id": "(Yaitu) ketika mereka datang kepadamu dari atas dan dari bawahmu, dan ketika tidak tetap lagi penglihatan(mu) dan hatimu naik menyesak sampai ke tenggorokan dan kamu menyangka terhadap Allah dengan bermacam-macam purbasangka.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 11, "text": "هُنَالِكَ ٱبۡتُلِیَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُوا۟ زِلۡزَالࣰا شَدِیدࣰا ۝١١", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "في ذلك الموقف العصيب اختُبر إيمان المؤمنين ومُحِّص القوم، وعُرف المؤمن من المنافق، واضطربوا اضطرابًا شديدًا بالخوف والقلق؛ ليتبين إيمانهم ويزيد يقينهم.", "isBasmala": false, "translation_en": "There and then the believers were tested, and were shaken most severely.", "translation_id": "Disitulah diuji orang-orang mukmin dan digoncangkan (hatinya) dengan goncangan yang sangat.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 12, "text": "وَإِذۡ یَقُولُ ٱلۡمُنَـٰفِقُونَ وَٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥۤ إِلَّا غُرُورࣰا ۝١٢", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "وإذ يقول المنافقون والذين في قلوبهم شك، وهم ضعفاء الإيمان: ما وعدنا الله ورسوله من النصر والتمكين إلا باطلا من القول وغرورًا، فلا تصدقوه.", "isBasmala": false, "translation_en": "When the hypocrites and those in whose hearts is sickness said, \"God and His Messenger promised us nothing but illusion.\"", "translation_id": "Dan (ingatlah) ketika orang-orang munafik dan orang-orang yang berpenyakit dalam hatinya berkata: \"Allah dan Rasul-Nya tidak menjanjikan kepada kami melainkan tipu daya\".", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 13, "text": "وَإِذۡ قَالَت طَّاۤىِٕفَةࣱ مِّنۡهُمۡ یَـٰۤأَهۡلَ یَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُوا۟ۚ وَیَسۡتَـٔۡذِنُ فَرِیقࣱ مِّنۡهُمُ ٱلنَّبِیَّ یَقُولُونَ إِنَّ بُیُوتَنَا عَوۡرَةࣱ وَمَا هِیَ بِعَوۡرَةٍۖ إِن یُرِیدُونَ إِلَّا فِرَارࣰا ۝١٣", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "واذكر -أيها النبي- قول طائفة من المنافقين منادين المؤمنين من أهل \"المدينة\": يا أهل \"يثرب\"(وهو الاسم القديم \"للمدينة\") لا إقامة لكم في معركة خاسرة، فارجعوا إلى منازلكم داخل \"المدينة\"، ويستأذن فريق آخر من المنافقين الرسول صلى الله عليه وسلم بالعودة إلى منازلهم بحجة أنها غير محصنة، فيخشون عليها، والحق أنها ليست كذلك، وما قصدوا بذلك إلا الفرار من القتال.", "isBasmala": false, "translation_en": "And when a group of them said, \"O people of Yathrib, you cannot make a stand, so retreat.\" And a faction of them asked the Prophet to excuse them, saying, \"Our homes are exposed,\" although they were not exposed. They only wanted to flee.", "translation_id": "Dan (ingatlah) ketika segolongan di antara mreka berkata: \"Hai penduduk Yatsrib (Madinah), tidak ada tempat bagimu, maka kembalilah kamu\". Dan sebahagian dari mereka minta izin kepada Nabi (untuk kembali pulang) dengan berkata: \"Sesungguhnya rumah-rumah kami terbuka (tidak ada penjaga)\". Dan rumah-rumah itu sekali-kali tidak terbuka, mereka tidak lain hanya hendak lari.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 14, "text": "وَلَوۡ دُخِلَتۡ عَلَیۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُىِٕلُوا۟ ٱلۡفِتۡنَةَ لَـَٔاتَوۡهَا وَمَا تَلَبَّثُوا۟ بِهَاۤ إِلَّا یَسِیرࣰا ۝١٤", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "ولو دخل جيش الأحزاب \"المدينة\" من جوانبها، ثم سئل هؤلاء المنافقون الشرك بالله والرجوع عن الإسلام، لأجابوا إلى ذلك مبادرين، وما تأخروا عن الشرك إلا يسيرًا.", "isBasmala": false, "translation_en": "Had it been invaded from its sides, and they were asked to dissent, they would have done so with little hesitation.", "translation_id": "Kalau (Yatsrib) diserang dari segala penjuru, kemudian diminta kepada mereka supaya murtad, niscaya mereka mengerjakannya; dan mereka tiada akan bertangguh untuk murtad itu melainkan dalam waktu yang singkat.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 15, "text": "وَلَقَدۡ كَانُوا۟ عَـٰهَدُوا۟ ٱللَّهَ مِن قَبۡلُ لَا یُوَلُّونَ ٱلۡأَدۡبَـٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولࣰا ۝١٥", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "ولقد كان هؤلاء المنافقون عاهدوا الله على يد رسوله من قبل غزوة الخندق، لا يفرُّون إن شهدوا الحرب، ولا يتأخرون إذا دعوا إلى الجهاد، ولكنهم خانوا عهدهم، وسيحاسبهم الله على ذلك، ويسألهم عن ذلك العهد، وكان عهد الله مسؤولا عنه، محاسَبًا عليه.", "isBasmala": false, "translation_en": "Although they had made a pledged to God, in the past, that they will not turn their backs. A pledge to God is a responsibility.", "translation_id": "Dan sesungguhnya mereka sebelum itu telah berjanji kepada Allah: \"Mereka tidak akan berbalik ke belakang (mundur)\". Dan adalah perjanjian dengan Allah akan diminta pertanggungan jawabnya.", "manzil": 5, "manzil_display": ""}], "420": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 16, "text": "قُل لَّن یَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذࣰا لَّا تُمَتَّعُونَ إِلَّا قَلِیلࣰا ۝١٦", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "قل -أيها النبي- لهؤلاء المنافقين: لن ينفعكم الفرار من المعركة خوفًا من الموت أو القتل؛ فإن ذلك لا يؤخر آجالكم، وإن فررتم فلن تتمتعوا في هذه الدنيا إلا بقدر أعماركم المحدودة، وهو زمن يسير جدًا بالنسبة إلى الآخرة.", "isBasmala": false, "translation_en": "Say, \"Flight will not benefit you, if you flee from death or killing, even then you will be given only brief enjoyment.\"", "translation_id": "Katakanlah: \"Lari itu sekali-kali tidaklah berguna bagimu, jika kamu melarikan diri dari kematian atau pembunuhan, dan jika (kamu terhindar dari kematian) kamu tidak juga akan mengecap kesenangan kecuali sebentar saja\".", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 17, "text": "قُلۡ مَن ذَا ٱلَّذِی یَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ أَرَادَ بِكُمۡ سُوۤءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةࣰۚ وَلَا یَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِیࣰّا وَلَا نَصِیرࣰا ۝١٧", "juz": 21, "hizb": "(*½ ح 42*)", "tafsir": "قل -أيها النبي- لهم: مَن ذا الذي يمنعكم من الله، أو يجيركم مِن عذابه، إن أراد بكم سوءًا، أو أراد بكم رحمة، فإنه المعطي المانع الضارُّ النافع؟ ولا يجد هؤلاء المنافقون لهم من دون الله وليًّا يواليهم، ولا نصيرًا ينصرهم.", "isBasmala": false, "translation_en": "Say, \"Who is it who will shield you from God, if He intends adversity for you, or intends mercy for you?\" Besides God, they will find for themselves neither friend nor helper.", "translation_id": "Katakanlah: \"Siapakah yang dapat melindungi kamu dari (takdir) Allah jika Dia menghendaki bencana atasmu atau menghendaki rahmat untuk dirimu?\" Dan orang-orang munafik itu tidak memperoleh bagi mereka pelindung dan penolong selain Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 18, "text": "۞ قَدۡ یَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِینَ مِنكُمۡ وَٱلۡقَاۤىِٕلِینَ لِإِخۡوَ ٰنِهِمۡ هَلُمَّ إِلَیۡنَاۖ وَلَا یَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِیلًا ۝١٨", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "إن الله يعلم المثبطين عن الجهاد في سبيل الله، والقائلين لإخوانهم: تعالوا وانضموا إلينا، واتركوا محمدًا، فلا تشهدوا معه قتالا؛ فإنا نخاف عليكم الهلاك بهلاكه، وهم مع تخذيلهم هذا لا يأتون القتال إلا نادرًا؛ رياء وسمعة وخوف الفضيحة.", "isBasmala": false, "translation_en": "God already knows the hinderers among you, and those who say to their brethren, \"Come and join us.\" Rarely do they mobilize for battle.", "translation_id": "Sesungguhnya Allah mengetahui orang-orang yang menghalang-halangi di antara kamu dan orang-orang yang berkata kepada saudara-saudaranya: \"Marilah kepada kami\". Dan mereka tidak mendatangi peperangan melainkan sebentar.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 19, "text": "أَشِحَّةً عَلَیۡكُمۡۖ فَإِذَا جَاۤءَ ٱلۡخَوۡفُ رَأَیۡتَهُمۡ یَنظُرُونَ إِلَیۡكَ تَدُورُ أَعۡیُنُهُمۡ كَٱلَّذِی یُغۡشَىٰ عَلَیۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم بِأَلۡسِنَةٍ حِدَادٍۙ أَشِحَّةً عَلَى ٱلۡخَیۡرِۚ أُو۟لَـٰۤىِٕكَ لَمۡ یُؤۡمِنُوا۟ فَأَحۡبَطَ ٱللَّهُ أَعۡمَـٰلَهُمۡۚ وَكَانَ ذَ ٰلِكَ عَلَى ٱللَّهِ یَسِیرࣰا ۝١٩", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "بُخَلاء عليكم -أيها المؤمنون- بالمال والنفس والجهد والمودة لما في نفوسهم من العداوة والحقد؛ حبًا في الحياة وكراهة للموت، فإذا حضر القتال خافوا الهلاك ورأيتهم ينظرون إليك، تدور أعينهم لذهاب عقولهم؛ خوفًا من القتل وفرارًا منه كدوران عين مَن حضره الموت، فإذا انتهت الحرب وذهب الرعب رموكم بألسنة حداد مؤذية، وتراهم عند قسمة الغنائم بخلاء وحسدة، أولئك لم يؤمنوا بقلوبهم، فأذهب الله ثواب أعمالهم، وكان ذلك على الله يسيرًا.", "isBasmala": false, "translation_en": "Being stingy towards you. And when fear approaches, you see them staring at you-their eyes rolling-like someone fainting at death. Then, when panic is over, they whip you with sharp tongues. They resent you any good. These have never believed, so God has nullified their works; a matter easy for God.", "translation_id": "Mereka bakhil terhadapmu, apabila datang ketakutan (bahaya), kamu lihat mereka itu memandang kepadamu dengan mata yang terbalik-balik seperti orang yang pingsan karena akan mati, dan apabila ketakutan telah hilang, mereka mencaci kamu dengan lidah yang tajam, sedang mereka bakhil untuk berbuat kebaikan. Mereka itu tidak beriman, maka Allah menghapuskan (pahala) amalnya. Dan yang demikian itu adalah mudah bagi Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 20, "text": "یَحۡسَبُونَ ٱلۡأَحۡزَابَ لَمۡ یَذۡهَبُوا۟ۖ وَإِن یَأۡتِ ٱلۡأَحۡزَابُ یَوَدُّوا۟ لَوۡ أَنَّهُم بَادُونَ فِی ٱلۡأَعۡرَابِ یَسۡـَٔلُونَ عَنۡ أَنۢبَاۤىِٕكُمۡۖ وَلَوۡ كَانُوا۟ فِیكُم مَّا قَـٰتَلُوۤا۟ إِلَّا قَلِیلࣰا ۝٢٠", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "يظن المنافقون أن الأحزاب الذين هزمهم الله تعالى شر هزيمة لم يذهبوا؛ ذلك من شدة الخوف والجبن، ولو عاد الأحزاب إلى \"المدينة\" لتمنَّى أولئك المنافقون أنهم كانوا غائبين عن \"المدينة\" بين أعراب البادية، يستخبرون عن أخباركم ويسألون عن أنبائكم، ولو كانوا فيكم ما قاتلوا معكم إلا قليلا لكثرة جبنهم وذلتهم وضعف يقينهم.", "isBasmala": false, "translation_en": "They assumed that the confederates had not withdrawn. But were the confederates to advance, they would wish they were in the desert with the Bedouins, inquiring about your news. And if they were among you, they would have done little fighting.", "translation_id": "Mereka mengira (bahwa) golongan-golongan yang bersekutu itu belum pergi; dan jika golongan-golongan yang bersekutu itu datang kembali, niscaya mereka ingin berada di dusun-dusun bersama-sama orang Arab Badwi, sambil menanya-nanyakan tentang berita-beritamu. Dan sekiranya mereka berada bersama kamu, mereka tidak akan berperang, melainkan sebentar saja.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 21, "text": "لَّقَدۡ كَانَ لَكُمۡ فِی رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةࣱ لِّمَن كَانَ یَرۡجُوا۟ ٱللَّهَ وَٱلۡیَوۡمَ ٱلۡـَٔاخِرَ وَذَكَرَ ٱللَّهَ كَثِیرࣰا ۝٢١", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "لقد كان لكم -أيها المؤمنون- في أقوال رسول الله صلى الله عليه وسلم وأفعاله وأحواله قدوة حسنة تتأسون بها، فالزموا سنته، فإنما يسلكها ويتأسى بها مَن كان يرجو الله واليوم الآخر، وأكثرَ مِن ذكر الله واستغفاره، وشكره في كل حال.", "isBasmala": false, "translation_en": "You have an excellent example in the Messenger of God; for anyone who seeks God and the Last Day, and remembers God frequently.", "translation_id": "Sesungguhnya telah ada pada (diri) Rasulullah itu suri teladan yang baik bagimu (yaitu) bagi orang yang mengharap (rahmat) Allah dan (kedatangan) hari kiamat dan dia banyak menyebut Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 22, "text": "وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُوا۟ هَـٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّاۤ إِیمَـٰنࣰا وَتَسۡلِیمࣰا ۝٢٢", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "ولمَّا شاهد المؤمنون الأحزاب الذين تحزَّبوا حول \"المدينة\" وأحاطوا بها، تذكروا أن موعد النصر قد قرب، فقالوا: هذا ما وعدنا الله ورسوله، من الابتلاء والمحنة والنصر، فأنجز الله وعده، وصدق رسوله فيما بشَّر به، وما زادهم النظر إلى الأحزاب إلا إيمانًا بالله وتسليمًا لقضائه وانقيادًا لأمره.", "isBasmala": false, "translation_en": "And when the believers saw the confederates, they said, \"This is what God and His messenger have promised us; and God and His messenger have told the truth.\" And it only increased them in faith and submission.", "translation_id": "Dan tatkala orang-orang mukmin melihat golongan-golongan yang bersekutu itu, mereka berkata: \"Inilah yang dijanjikan Allah dan Rasul-Nya kepada kita\". Dan benarlah Allah dan Rasul-Nya. Dan yang demikian itu tidaklah menambah kepada mereka kecuali iman dan ketundukan.", "manzil": 5, "manzil_display": ""}], "421": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 23, "text": "مِّنَ ٱلۡمُؤۡمِنِینَ رِجَالࣱ صَدَقُوا۟ مَا عَـٰهَدُوا۟ ٱللَّهَ عَلَیۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن یَنتَظِرُۖ وَمَا بَدَّلُوا۟ تَبۡدِیلࣰا ۝٢٣", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "من المؤمنين رجال أوفوا بعهودهم مع الله تعالى، وصبروا على البأساء والضراء وحين البأس: فمنهم من وَفَّى بنذره، فاستشهد في سبيل الله، أو مات على الصدق والوفاء، ومنهم مَن ينتظر إحدى الحسنيين: النصر أو الشهادة، وما غيَّروا عهد الله، ولا نقضوه ولا بدَّلوه، كما غيَّر المنافقون.", "isBasmala": false, "translation_en": "Of the believers are men who are true to what they pledged to God. Some of them have fulfilled their vows; and some are still waiting, and never wavering.", "translation_id": "Di antara orang-orang mukmin itu ada orang-orang yang menepati apa yang telah mereka janjikan kepada Allah; maka di antara mereka ada yang gugur. Dan di antara mereka ada (pula) yang menunggu-nunggu dan mereka tidak merubah (janjinya),", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 24, "text": "لِّیَجۡزِیَ ٱللَّهُ ٱلصَّـٰدِقِینَ بِصِدۡقِهِمۡ وَیُعَذِّبَ ٱلۡمُنَـٰفِقِینَ إِن شَاۤءَ أَوۡ یَتُوبَ عَلَیۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِیمࣰا ۝٢٤", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "ليثيب الله أهل الصدق بسبب صدقهم وبلائهم وهم المؤمنون، ويعذب المنافقين إن شاء تعذيبهم، بأن لا يوفقهم للتوبة النصوح قبل الموت، فيموتوا على الكفر، فيستوجبوا النار، أو يتوب عليهم بأن يوفقهم للتوبة والإنابة، إن الله كان غفورًا لذنوب المسرفين على أنفسهم إذا تابوا، رحيمًا بهم؛ حيث وفقهم للتوبة النصوح.", "isBasmala": false, "translation_en": "That God may reward the truthful for their truthfulness; and punish the hypocrites, if He wills, or pardon them. God is Forgiving and Merciful.", "translation_id": "supaya Allah memberikan balasan kepada orang-orang yang benar itu karena kebenarannya, dan menyiksa orang munafik jika dikehendaki-Nya, atau menerima taubat mereka. Sesungguhnya Allah adalah Maha Pengampun lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 25, "text": "وَرَدَّ ٱللَّهُ ٱلَّذِینَ كَفَرُوا۟ بِغَیۡظِهِمۡ لَمۡ یَنَالُوا۟ خَیۡرࣰاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِینَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِیًّا عَزِیزࣰا ۝٢٥", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "وردَّ الله أحزاب الكفر عن \"المدينة\" خائبين خاسرين مغتاظين، لم ينالوا خيرًا في الدنيا ولا في الآخرة، وكفى الله المؤمنين القتال بما أيدهم به من الأسباب. وكان الله قويًا لا يُغالَب ولا يُقْهَر، عزيزًا في ملكه وسلطانه.", "isBasmala": false, "translation_en": "God repelled the disbelievers in their rage; they gained no advantage. God thus spared the believers combat. God is Strong and Mighty.", "translation_id": "Dan Allah menghalau orang-orang yang kafir itu yang keadaan mereka penuh kejengkelan, (lagi) mereka tidak memperoleh keuntungan apapun. Dan Allah menghindarkan orang-orang mukmin dari peperangan. Dan adalah Allah Maha Kuat lagi Maha Perkasa.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 26, "text": "وَأَنزَلَ ٱلَّذِینَ ظَـٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ مِن صَیَاصِیهِمۡ وَقَذَفَ فِی قُلُوبِهِمُ ٱلرُّعۡبَ فَرِیقࣰا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِیقࣰا ۝٢٦", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "وأنزل الله يهود بني قريظة من حصونهم؛ لإعانتهم الأحزاب في قتال المسلمين، وألقى في قلوبهم الخوف فهُزموا، تقتلون منهم فريقًا، وتأسرون فريقًا آخر.", "isBasmala": false, "translation_en": "And He brought down from their strongholds those of the People of the Book who backed them, and He threw terror into their hearts. Some of them you killed, and others you took captive.", "translation_id": "Dan Dia menurunkan orang-orang Ahli Kitab (Bani Quraizhah) yang membantu golongan-golongan yang bersekutu dari benteng-benteng mereka, dan Dia memesukkan rasa takut ke dalam hati mereka. Sebahagian mereka kamu bunuh dan sebahagian yang lain kamu tawan.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 27, "text": "وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِیَـٰرَهُمۡ وَأَمۡوَ ٰلَهُمۡ وَأَرۡضࣰا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣰا ۝٢٧", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "وملَّككم الله -أيها المؤمنون- أرضهم ومساكنهم وأموالهم المنقولة كالحليِّ والسلاح والمواشي، وغير المنقولة كالمزارع والبيوت والحصون المنيعة، وأورثكم أرضًا لم تتمكنوا مِن وطئها من قبل؛ لمنعتها وعزتها عند أهلها. وكان الله على كل شيء قديرًا، لا يعجزه شيء.", "isBasmala": false, "translation_en": "And He made you inherit their land, and their homes, and their possessions, and a region you have never stepped on. God has power over all things.", "translation_id": "Dan Dia mewariskan kepada kamu tanah-tanah, rumah-rumah dan harta benda mereka, dan (begitu pula) tanah yang belum kamu injak. Dan adalah Allah Maha Kuasa terhadap segala sesuatu.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 28, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ قُل لِّأَزۡوَ ٰجِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا وَزِینَتَهَا فَتَعَالَیۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحࣰا جَمِیلࣰا ۝٢٨", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "يا أيها النبي قل لأزواجك اللاتي اجتمعن عليك، يطلبن منك زيادة النفقة: إن كنتنَّ تردن الحياة الدنيا وزينتها فأقبِلْنَ أمتعكنَّ شيئًا مما عندي من الدنيا، وأفارقكنَّ دون ضرر أو إيذاء.", "isBasmala": false, "translation_en": "O Prophet! Say to your wives, \"If you desire the life of this world and its finery, then let me compensate you, and release you kindly.", "translation_id": "Hai Nabi, katakanlah kepada isteri-isterimu: \"Jika kamu sekalian mengingini kehidupan dunia dan perhiasannya, maka marilah supaya kuberikan kepadamu mut'ah dan aku ceraikan kamu dengan cara yang baik.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 29, "text": "وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡـَٔاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَـٰتِ مِنكُنَّ أَجۡرًا عَظِیمࣰا ۝٢٩", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "وإن كنتن تردْنَ رضا الله ورضا رسوله وما أعدَّ الله لكُنَّ في الدار الآخرة، فاصبرْنَ على ما أنتُنَّ عليه، وأطعن الله ورسوله، فإن الله أعد للمحسنات منكنَّ ثوابًا عظيمًا. (وقد اخترن الله ورسوله، وما أعدَّ الله لهن في الدار الآخرة).", "isBasmala": false, "translation_en": "But if you desire God, His Messenger, and the Home of the Hereafter, then God has prepared for the righteous among you a magnificent compensation.\"", "translation_id": "Dan jika kamu sekalian menghendaki (keridhaan) Allah dan Rasulnya-Nya serta (kesenangan) di negeri akhirat, maka sesungguhnya Allah menyediakan bagi siapa yang berbuat baik diantaramu pahala yang besar.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 30, "text": "یَـٰنِسَاۤءَ ٱلنَّبِیِّ مَن یَأۡتِ مِنكُنَّ بِفَـٰحِشَةࣲ مُّبَیِّنَةࣲ یُضَـٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَیۡنِۚ وَكَانَ ذَ ٰلِكَ عَلَى ٱللَّهِ یَسِیرࣰا ۝٣٠", "juz": 21, "hizb": "(*¾ ح 42*)", "tafsir": "يا نساء النبي مَن يأت منكن بمعصية ظاهرة يُضاعَف لها العذاب مرتين. فلما كانت مكانتهن رفيعة ناسب أن يجعل الله الذنب الواقع منهن عقوبته مغلظة؛ صيانة لجنابهن وجناب رسول الله صلى الله عليه وسلم. وكان ذلك العقاب على الله يسيرًا.", "isBasmala": false, "translation_en": "O wives of the Prophet! Whoever of you commits a proven indecency, the punishment for her will be doubled. And that would be easy for God.", "translation_id": "Hai isteri-isteri Nabi, siapa-siapa di antaramu yang mengerjakan perbuatan keji yang nyata, niscaya akan di lipat gandakan siksaan kepada mereka dua kali lipat. Dan adalah yang demikian itu mudah bagi Allah.", "manzil": 5, "manzil_display": ""}], "422": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 31, "text": "۞ وَمَن یَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَـٰلِحࣰا نُّؤۡتِهَاۤ أَجۡرَهَا مَرَّتَیۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقࣰا كَرِیمࣰا ۝٣١", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "ومن تطع منكن الله ورسوله، وتعمل بما أمر الله به، نُعْطها ثواب عملها مثلَي ثواب عمل غيرها من سائر النساء، وأعددنا لها رزقًا كريمًا، وهو الجنة.", "isBasmala": false, "translation_en": "But whoever of you remains obedient to God and His Messenger, and acts righteously, We will give her a double reward; and We have prepared for her a generous provision.", "translation_id": "Dan barang siapa diantara kamu sekalian (isteri-isteri nabi) tetap taat kepada Allah dan Rasul-Nya dan mengerjakan amal yang saleh, niscata Kami memberikan kepadanya pahala dua kali lipat dan Kami sediakan baginya rezeki yang mulia.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 32, "text": "یَـٰنِسَاۤءَ ٱلنَّبِیِّ لَسۡتُنَّ كَأَحَدࣲ مِّنَ ٱلنِّسَاۤءِۛ إِنِ ٱتَّقَیۡتُنَّۛ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَیَطۡمَعَ ٱلَّذِی فِی قَلۡبِهِۦ مَرَضࣱ وَقُلۡنَ قَوۡلࣰا مَّعۡرُوفࣰا ۝٣٢", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "يا نساء النبيِّ -محمد- لستنَّ في الفضل والمنزلة كغيركنَّ من النساء، إن عملتن بطاعة الله وابتعدتن عن معاصيه، فلا تتحدثن مع الأجانب بصوت لَيِّن يُطمع الذي في قلبه فجور ومرض في الشهوة الحرام، وهذا أدب واجب على كل امرأة تؤمن بالله واليوم الآخر، وقُلن قولا بعيدًا عن الريبة، لا تنكره الشريعة.", "isBasmala": false, "translation_en": "O wives of the Prophet! You are not like any other women, if you observe piety. So do not speak too softly, lest the sick at heart lusts after you, but speak in an appropriate manner.", "translation_id": "Hai isteri-isteri Nabi, kamu sekalian tidaklah seperti wanita yang lain, jika kamu bertakwa. Maka janganlah kamu tunduk dalam berbicara sehingga berkeinginanlah orang yang ada penyakit dalam hatinya dan ucapkanlah perkataan yang baik,", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 33, "text": "وَقَرۡنَ فِی بُیُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَـٰهِلِیَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ ٱلصَّلَوٰةَ وَءَاتِینَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥۤۚ إِنَّمَا یُرِیدُ ٱللَّهُ لِیُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَیۡتِ وَیُطَهِّرَكُمۡ تَطۡهِیرࣰا ۝٣٣", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "والْزَمْنَ بيوتكن، ولا تخرجن منها إلا لحاجة، ولا تُظهرن محاسنكن، كما كان يفعل نساء الجاهلية الأولى في الأزمنة السابقة على الإسلام، وهو خطاب للنساء المؤمنات في كل عصر. وأدِّين - يا نساء النبي- الصلاة كاملة في أوقاتها، وأعطين الزكاة كما شرع الله، وأطعن الله ورسوله في أمرهما ونهيهما، إنما أوصاكن الله بهذا؛ ليزكيكنَّ، ويبعد عنكنَّ الأذى والسوء والشر يا أهل بيت النبي -ومنهم زوجاته وذريته عليه الصلاة والسلام-، ويطهِّر نفوسكم غاية الطهارة.", "isBasmala": false, "translation_en": "And settle in your homes; and do not display yourselves, as in the former days of ignorance. And perform the prayer, and give regular charity, and obey God and His Messenger. God desires to remove all impurity from you, O People of the Household, and to purify you thoroughly.", "translation_id": "dan hendaklah kamu tetap di rumahmu dan janganlah kamu berhias dan bertingkah laku seperti orang-orang Jahiliyah yang dahulu dan dirikanlah shalat, tunaikanlah zakat dan taatilah Allah dan Rasul-Nya. Sesungguhnya Allah bermaksud hendak menghilangkan dosa dari kamu, hai ahlul bait dan membersihkan kamu sebersih-bersihnya.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 34, "text": "وَٱذۡكُرۡنَ مَا یُتۡلَىٰ فِی بُیُوتِكُنَّ مِنۡ ءَایَـٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِیفًا خَبِیرًا ۝٣٤", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "واذكرن ما يتلى في بيوتكن من القرآن وحديث الرسول صلى الله عليه وسلم، واعملن به، واقدُرْنه حقَّ قَدْره، فهو من نِعَم الله عليكن، إن الله كان لطيفًا بكنَّ؛ إذ جعلكنَّ في البيوت التي تتلى فيها آيات الله والسنة، خبيرًا بكنَّ إذ اختاركنَّ لرسوله أزواجًا.", "isBasmala": false, "translation_en": "And remember what is recited in your homes of God's revelations and wisdom. God is Kind and Informed.", "translation_id": "Dan ingatlah apa yang dibacakan di rumahmu dari ayat-ayat Allah dan hikmah (sunnah nabimu). Sesungguhnya Allah adalah Maha Lembut lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 35, "text": "إِنَّ ٱلۡمُسۡلِمِینَ وَٱلۡمُسۡلِمَـٰتِ وَٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ وَٱلۡقَـٰنِتِینَ وَٱلۡقَـٰنِتَـٰتِ وَٱلصَّـٰدِقِینَ وَٱلصَّـٰدِقَـٰتِ وَٱلصَّـٰبِرِینَ وَٱلصَّـٰبِرَ ٰتِ وَٱلۡخَـٰشِعِینَ وَٱلۡخَـٰشِعَـٰتِ وَٱلۡمُتَصَدِّقِینَ وَٱلۡمُتَصَدِّقَـٰتِ وَٱلصَّـٰۤىِٕمِینَ وَٱلصَّـٰۤىِٕمَـٰتِ وَٱلۡحَـٰفِظِینَ فُرُوجَهُمۡ وَٱلۡحَـٰفِظَـٰتِ وَٱلذَّ ٰكِرِینَ ٱللَّهَ كَثِیرࣰا وَٱلذَّ ٰكِرَ ٰتِۙ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةࣰ وَأَجۡرًا عَظِیمࣰا ۝٣٥", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "إن المنقادين لأوامر الله والمنقادات، والمصَدِّقين والمصدِّقات والمطيعين لله ورسوله والمطيعات، والصادقين في أقوالهم والصادقات، والصابرين عن الشهوات وعلى الطاعات وعلى المكاره والصابرات، والخائفين من الله والخائفات، والمتصدقين بالفرض والنَّفْل والمتصدقات، والصائمين في الفرض والنَّفْل والصائمات، والحافظين فروجهم عن الزنى ومقدماته، وعن كشف العورات والحافظات، والذاكرين الله كثيرًا بقلوبهم وألسنتهم والذاكرات، أعدَّ الله لهؤلاء مغفرة لذنوبهم وثوابًا عظيمًا، وهو الجنة.", "isBasmala": false, "translation_en": "Muslim men and Muslim women, believing men and believing women, obedient men and obedient women, truthful men and truthful women, patient men and patient women, humble men and humble women, charitable men and charitable women, fasting men and fasting women, men who guard their chastity and women who guard, men who remember God frequently and women who remember-God has prepared for them a pardon, and an immense reward.", "translation_id": "Sesungguhnya laki-laki dan perempuan yang muslim, laki-laki dan perempuan yang mukmin, laki-laki dan perempuan yang tetap dalam ketaatannya, laki-laki dan perempuan yang benar, laki-laki dan perempuan yang sabar, laki-laki dan perempuan yang khusyu', laki-laki dan perempuan yang bersedekah, laki-laki dan perempuan yang berpuasa, laki-laki dan perempuan yang memelihara kehormatannya, laki-laki dan perempuan yang banyak menyebut (nama) Allah, Allah telah menyediakan untuk mereka ampunan dan pahala yang besar.", "manzil": 5, "manzil_display": ""}], "423": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 36, "text": "وَمَا كَانَ لِمُؤۡمِنࣲ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥۤ أَمۡرًا أَن یَكُونَ لَهُمُ ٱلۡخِیَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن یَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَـٰلࣰا مُّبِینࣰا ۝٣٦", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "ولا ينبغي لمؤمن ولا مؤمنة إذا حكم الله ورسوله فيهم حُكمًا أن يخالفوه، بأن يختاروا غير الذي قضى فيهم. ومن يعص الله ورسوله فقد بَعُدَ عن طريق الصواب بُعْدًا ظاهرًا.", "isBasmala": false, "translation_en": "It is not for any believer, man or woman, when God and His Messenger have decided a matter, to have liberty of choice in their decision. Whoever disobeys God and His Messenger has gone far astray.", "translation_id": "Dan tidaklah patut bagi laki-laki yang mukmin dan tidak (pula) bagi perempuan yang mukmin, apabila Allah dan Rasul-Nya telah menetapkan suatu ketetapan, akan ada bagi mereka pilihan (yang lain) tentang urusan mereka. Dan barangsiapa mendurhakai Allah dan Rasul-Nya maka sungguhlah dia telah sesat, sesat yang nyata.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 37, "text": "وَإِذۡ تَقُولُ لِلَّذِیۤ أَنۡعَمَ ٱللَّهُ عَلَیۡهِ وَأَنۡعَمۡتَ عَلَیۡهِ أَمۡسِكۡ عَلَیۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِی فِی نَفۡسِكَ مَا ٱللَّهُ مُبۡدِیهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَیۡدࣱ مِّنۡهَا وَطَرࣰا زَوَّجۡنَـٰكَهَا لِكَیۡ لَا یَكُونَ عَلَى ٱلۡمُؤۡمِنِینَ حَرَجࣱ فِیۤ أَزۡوَ ٰجِ أَدۡعِیَاۤىِٕهِمۡ إِذَا قَضَوۡا۟ مِنۡهُنَّ وَطَرࣰاۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولࣰا ۝٣٧", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "وإذ تقول -أيها النبي- للذي أنعم الله عليه بالإسلام -وهو زيد بن حارثة الذي أعتقه وتبنَّاه النبيُّ صلى الله عليه وسلم- وأنعمت عليه بالعتق: أَبْقِ زوجك زينب بنت جحش ولا تطلقها، واتق الله يا زيد، وتخفي -يا محمد- في نفسك ما أوحى الله به إليك من طلاق زيد لزوجه وزواجك منها، والله تعالى مظهر ما أخفيت، وتخاف المنافقين أن يقولوا: تزوج محمد مطلقة متبناه، والله تعالى أحق أن تخافه، فلما قضى زيد منها حاجته، وطلقها، وانقضت عدتها، زوجناكها؛ لتكون أسوة في إبطال عادة تحريم الزواج بزوجة المتبنى بعد طلاقها، ولا يكون على المؤمنين إثم وذنب في أن يتزوجوا من زوجات من كانوا يتبنَّوْنهم بعد طلاقهن إذا قضوا منهن حاجتهم. وكان أمر الله مفعولا لا عائق له ولا مانع. وكانت عادة التبني في الجاهلية، ثم أُبطلت بقوله تعالى: {ادْعُوهُمْ لآبَائِهِمْ (33:5)}.", "isBasmala": false, "translation_en": "When you said to him whom God had blessed, and you had favored, \"Keep your wife to yourself, and fear God.\" But you hid within yourself what God was to reveal. And you feared the people, but it was God you were supposed to fear. Then, when Zaid ended his relationship with her, We gave her to you in marriage, that there may be no restriction for believers regarding the wives of their adopted sons, when their relationship has ended. The command of God was fulfilled.", "translation_id": "Dan (ingatlah), ketika kamu berkata kepada orang yang Allah telah melimpahkan nikmat kepadanya dan kamu (juga) telah memberi nikmat kepadanya: \"Tahanlah terus isterimu dan bertakwalah kepada Allah\", sedang kamu menyembunyikan di dalam hatimu apa yang Allah akan menyatakannya, dan kamu takut kepada manusia, sedang Allah-lah yang lebih berhak untuk kamu takuti. Maka tatkala Zaid telah mengakhiri keperluan terhadap istrinya (menceraikannya), Kami kawinkan kamu dengan dia supaya tidak ada keberatan bagi orang mukmin untuk (mengawini) isteri-isteri anak-anak angkat mereka, apabila anak-anak angkat itu telah menyelesaikan keperluannya daripada isterinya. Dan adalah ketetapan Allah itu pasti terjadi.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 38, "text": "مَّا كَانَ عَلَى ٱلنَّبِیِّ مِنۡ حَرَجࣲ فِیمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِی ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرࣰا مَّقۡدُورًا ۝٣٨", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "ما كان على النبيِّ محمد صلى الله عليه وسلم من ذنب فيما أحلَّ الله له من زواج امرأة مَن تبنَّاه بعد طلاقها، كما أباحه للأنبياء قبله، سنة الله في الذين خَلَوا من قبل، وكان أمر الله قدرًا مقدورًا لا بد من وقوعه.", "isBasmala": false, "translation_en": "There is no blame on the Prophet regarding what God has ordained for him. Such is the pattern of God among those who passed before. The command of God is an absolute decree.", "translation_id": "Tidak ada suatu keberatanpun atas Nabi tentang apa yang telah ditetapkan Allah baginya. (Allah telah menetapkan yang demikian) sebagai sunnah-Nya pada nabi-nabi yang telah berlalu dahulu. Dan adalah ketetapan Allah itu suatu ketetapan yang pasti berlaku,", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 39, "text": "ٱلَّذِینَ یُبَلِّغُونَ رِسَـٰلَـٰتِ ٱللَّهِ وَیَخۡشَوۡنَهُۥ وَلَا یَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ بِٱللَّهِ حَسِیبࣰا ۝٣٩", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "ثم ذكر سبحانه الأنبياء الماضين وأثنى عليهم بأنهم: الذين يُبَلِّغون رسالاتِ الله إلى الناس، ويخافون الله وحده، ولا يخافون أحدًا سواه. وكفى بالله محاسبًا عباده على جميع أعمالهم ومراقبًا لها.", "isBasmala": false, "translation_en": "Those who deliver the messages of God, and fear Him, and never fear anyone except God. God is sufficient as a reckoner.", "translation_id": "(yaitu) orang-orang yang menyapaikan risalah-risalah Allah, mereka takut kepada-Nya dan mereka tiada merasa takut kepada seorang(pun) selain kepada Allah. Dan cukuplah Allah sebagai Pembuat Perhitungan.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 40, "text": "مَّا كَانَ مُحَمَّدٌ أَبَاۤ أَحَدࣲ مِّن رِّجَالِكُمۡ وَلَـٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِیِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣰا ۝٤٠", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "ما كان محمد أبًا لأحد من رجالكم، ولكنه رسول الله وخاتم النبيين، فلا نبوة بعده إلى يوم القيامة. وكان الله بكل شيء من أعمالكم عليمًا، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "Muhammad is not the father of any of your men; but he is the Messenger of God, and the seal of the prophets. God is Cognizant of everything.", "translation_id": "Muhammad itu sekali-kali bukanlah bapak dari seorang laki-laki di antara kamu, tetapi dia adalah Rasulullah dan penutup nabi-nabi. Dan adalah Allah Maha Mengetahui segala sesuatu.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 41, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱذۡكُرُوا۟ ٱللَّهَ ذِكۡرࣰا كَثِیرࣰا ۝٤١", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه، اذكروا الله بقلوبكم وألسنتكم وجوارحكم ذِكْرًا كثيرًا، واشغلوا أوقاتكم بذكر الله تعالى عند الصباح والمساء، وأدبار الصلوات المفروضات، وعند العوارض والأسباب، فإن ذلك عبادة مشروعة، تدعو إلى محبة الله، وكف اللسان عن الآثام، وتعين على كل خير.", "isBasmala": false, "translation_en": "O you who believe, remember God with frequent remembrance.", "translation_id": "Hai orang-orang yang beriman, berzdikirlah (dengan menyebut nama) Allah, zikir yang sebanyak-banyaknya.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 42, "text": "وَسَبِّحُوهُ بُكۡرَةࣰ وَأَصِیلًا ۝٤٢", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "يا أيها الذين صَدَّقوا الله ورسوله وعملوا بشرعه، اذكروا الله بقلوبكم وألسنتكم وجوارحكم ذِكْرًا كثيرًا، واشغلوا أوقاتكم بذكر الله تعالى عند الصباح والمساء، وأدبار الصلوات المفروضات، وعند العوارض والأسباب، فإن ذلك عبادة مشروعة، تدعو إلى محبة الله، وكف اللسان عن الآثام، وتعين على كل خير.", "isBasmala": false, "translation_en": "And glorify Him morning and evening.", "translation_id": "Dan bertasbihlah kepada-Nya diwaktu pagi dan petang.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 43, "text": "هُوَ ٱلَّذِی یُصَلِّی عَلَیۡكُمۡ وَمَلَـٰۤىِٕكَتُهُۥ لِیُخۡرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِینَ رَحِیمࣰا ۝٤٣", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "هو الذي يرحمكم ويثني عليكم وتدعو لكم ملائكته؛ ليخرجكم من ظلمات الجهل والضلال إلى نور الإسلام، وكان بالمؤمنين رحيمًا في الدنيا والآخرة، لا يعذبهم ما داموا مطيعين مخلصين له.", "isBasmala": false, "translation_en": "It is He who reaches out to you, and His angels, to bring you out of darkness into the light. And He is Ever-Merciful towards the believers.", "translation_id": "Dialah yang memberi rahmat kepadamu dan malaikat-Nya (memohonkan ampunan untukmu), supaya Dia mengeluarkan kamu dari kegelapan kepada cahaya (yang terang). Dan adalah Dia Maha Penyayang kepada orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}], "424": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 44, "text": "تَحِیَّتُهُمۡ یَوۡمَ یَلۡقَوۡنَهُۥ سَلَـٰمࣱۚ وَأَعَدَّ لَهُمۡ أَجۡرࣰا كَرِیمࣰا ۝٤٤", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "تحية هؤلاء المؤمنين من الله في الجنة يوم يلقونه سلام، وأمان لهم من عذاب الله، وقد أعدَّ لهم ثوابًا حسنًا، وهو الجنة.", "isBasmala": false, "translation_en": "Their greeting on the Day they meet Him is, \"Peace,\" and He has prepared for them a generous reward.", "translation_id": "Salam penghormatan kepada mereka (orang-orang mukmin itu) pada hari mereka menemui-Nya ialah: Salam; dan Dia menyediakan pahala yang mulia bagi mereka.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 45, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِنَّاۤ أَرۡسَلۡنَـٰكَ شَـٰهِدࣰا وَمُبَشِّرࣰا وَنَذِیرࣰا ۝٤٥", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "يا أيها النبي إنَّا أرسلناك شاهدًا على أمتك بإبلاغهم الرسالة، ومبشرًا المؤمنين منهم بالرحمة والجنة، ونذيرًا للعصاة والمكذبين من النار، وداعيًا إلى توحيد الله وعبادته وحده بأمره إياك، وسراجًا منيرًا لمن استنار بك، فأمْرك ظاهر فيما جئتَ به من الحق كالشمس في إشراقها وإضاءتها، لا يجحدها إلا معاند.", "isBasmala": false, "translation_en": "O prophet! We have sent you as a witness, and a bearer of good news, and a warner.", "translation_id": "Hai Nabi, sesungguhnya Kami mengutusmu untuk jadi saksi, dan pembawa kabar gemgira dan pemberi peringatan,", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 46, "text": "وَدَاعِیًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجࣰا مُّنِیرࣰا ۝٤٦", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "يا أيها النبي إنَّا أرسلناك شاهدًا على أمتك بإبلاغهم الرسالة، ومبشرًا المؤمنين منهم بالرحمة والجنة، ونذيرًا للعصاة والمكذبين من النار، وداعيًا إلى توحيد الله وعبادته وحده بأمره إياك، وسراجًا منيرًا لمن استنار بك، فأمْرك ظاهر فيما جئتَ به من الحق كالشمس في إشراقها وإضاءتها، لا يجحدها إلا معاند.", "isBasmala": false, "translation_en": "And a caller towards God by His leave, and an illuminating beacon.", "translation_id": "dan untuk jadi penyeru kepada Agama Allah dengan izin-Nya dan untuk jadi cahaya yang menerangi.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 47, "text": "وَبَشِّرِ ٱلۡمُؤۡمِنِینَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلࣰا كَبِیرࣰا ۝٤٧", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "وبَشِّر -أيها النبي- أهل الإيمان بأن لهم من الله ثوابًا عظيمًا، وهو روضات الجنات.", "isBasmala": false, "translation_en": "And give the believers the good news that for them is a great reward.", "translation_id": "Dan sampaikanlah berita gembira kepada orang-orang mukmin bahwa sesungguhnya bagi mereka karunia yang besar dari Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 48, "text": "وَلَا تُطِعِ ٱلۡكَـٰفِرِینَ وَٱلۡمُنَـٰفِقِینَ وَدَعۡ أَذَىٰهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلࣰا ۝٤٨", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "ولا تطع -أيها الرسول- قول كافر أو منافق واترك أذاهم، ولا يمنعك ذلك من تبليغ الرسالة، وثق بالله في كل أمورك واعتمد عليه؛ فإنه يكفيك ما أهمَّك من كل أمور الدنيا والآخرة.", "isBasmala": false, "translation_en": "And do not obey the blasphemers and the hypocrites, and ignore their insults, and rely on God. God is a sufficient protector.", "translation_id": "Dan janganlah kamu menuruti orang-orang yang kafir dan orang-orang munafik itu, janganlah kamu hiraukan gangguan mereka dan bertawakkallah kepada Allah. Dan cukuplah Allah sebagai Pelindung.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 49, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَـٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَیۡهِنَّ مِنۡ عِدَّةࣲ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحࣰا جَمِیلࣰا ۝٤٩", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا عقدتم على النساء ولم تدخلوا بهن ثم طلقتموهن مِن قبل أن تجامعوهن، فما لكم عليهن مِن عدَّة تحصونها عليهن، فأعطوهن من أموالكم متعة يتمتعن بها بحسب الوسع جبرًا لخواطرهن، وخلُّوا سبيلهن مع الستر الجميل، دون أذى أو ضرر.", "isBasmala": false, "translation_en": "O you who believe! When you marry believing women, but then divorce them before you have touched them, there is no waiting period for you to observe in respect to them; but compensate them, and release them in a graceful manner.", "translation_id": "Hai orang-orang yang beriman, apabila kamu menikahi perempuan-perempuan yang beriman, kemudian kamu ceraikan mereka sebelum kamu mencampurinya maka sekali-sekali tidak wajib atas mereka 'iddah bagimu yang kamu minta menyempurnakannya. Maka berilah mereka mut'ah dan lepaskanlah mereka itu dengan cara yang sebaik-baiknya.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 50, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِنَّاۤ أَحۡلَلۡنَا لَكَ أَزۡوَ ٰجَكَ ٱلَّـٰتِیۤ ءَاتَیۡتَ أُجُورَهُنَّ وَمَا مَلَكَتۡ یَمِینُكَ مِمَّاۤ أَفَاۤءَ ٱللَّهُ عَلَیۡكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّـٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَـٰلَـٰتِكَ ٱلَّـٰتِی هَاجَرۡنَ مَعَكَ وَٱمۡرَأَةࣰ مُّؤۡمِنَةً إِن وَهَبَتۡ نَفۡسَهَا لِلنَّبِیِّ إِنۡ أَرَادَ ٱلنَّبِیُّ أَن یَسۡتَنكِحَهَا خَالِصَةࣰ لَّكَ مِن دُونِ ٱلۡمُؤۡمِنِینَۗ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا عَلَیۡهِمۡ فِیۤ أَزۡوَ ٰجِهِمۡ وَمَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ لِكَیۡلَا یَكُونَ عَلَیۡكَ حَرَجࣱۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا ۝٥٠", "juz": 22, "hizb": "(* ح 43*)", "tafsir": "يا أيها النبي إنَّا أبَحْنا لك أزواجك اللاتي أعطيتهن مهورهن، وأبَحْنا لك ما مَلَكَتْ يمينك من الإماء، مما أنعم الله به عليك، وأبحنا لك الزواج من بنات عمك وبنات عماتك وبنات خالك وبنات خالاتك اللاتي هاجرن معك، وأبحنا لك امرأة مؤمنة مَنَحَتْ نفسها لك من غير مهر، إن كنت تريد الزواج منها خالصة لك، وليس لغيرك أن يتزوج امرأة بالهِبَة. قد علمنا ما أوجبنا على المؤمنين في أزواجهم وإمائهم بألا يتزوجوا إلا أربع نسوة، وما شاؤوا من الإماء، واشتراط الوليِّ والمهر والشهود عليهم، ولكنا رخصنا لك في ذلك، ووسَّعْنا عليك ما لم يُوسَّع على غيرك؛ لئلا يضيق صدرك في نكاح مَن نكحت مِن هؤلاء الأصناف. وكان الله غفورًا لذنوب عباده المؤمنين، رحيمًا بالتوسعة عليهم.", "isBasmala": false, "translation_en": "O Prophet! We have permitted to you your wives to whom you have given their dowries, and those you already have, as granted to you by God, and the daughters of your paternal uncle, and the daughters of your paternal aunts, and the daughters of your maternal uncle, and the daughters of your maternal aunts who emigrated with you, and a believing woman who has offered herself to the Prophet, if the Prophet desires to marry her, exclusively for you, and not for the believers. We know what We have ordained for them regarding their wives and those their right-hands possess. This is to spare you any difficulty. God is Forgiving and Merciful.", "translation_id": "Hai Nabi, sesungguhnya Kami telah menghalalkan bagimu isteri-isterimu yang telah kamu berikan mas kawinnya dan hamba sahaya yang kamu miliki yang termasuk apa yang kamu peroleh dalam peperangan yang dikaruniakan Allah untukmu, dan (demikian pula) anak-anak perempuan dari saudara laki-laki bapakmu, anak-anak perempuan dari saudara perempuan bapakmu, anak-anak perempuan dari saudara laki-laki ibumu dan anak-anak perempuan dari saudara perempuan ibumu yang turut hijrah bersama kamu dan perempuan mukmin yang menyerahkan dirinya kepada Nabi kalau Nabi mau mengawininya, sebagai pengkhususan bagimu, bukan untuk semua orang mukmin. Sesungguhnya Kami telah mengetahui apa yang Kami wajibkan kepada mereka tentang isteri-isteri mereka dan hamba sahaya yang mereka miliki supaya tidak menjadi kesempitan bagimu. Dan adalah Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}], "425": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 51, "text": "۞ تُرۡجِی مَن تَشَاۤءُ مِنۡهُنَّ وَتُـٔۡوِیۤ إِلَیۡكَ مَن تَشَاۤءُۖ وَمَنِ ٱبۡتَغَیۡتَ مِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَیۡكَۚ ذَ ٰلِكَ أَدۡنَىٰۤ أَن تَقَرَّ أَعۡیُنُهُنَّ وَلَا یَحۡزَنَّ وَیَرۡضَیۡنَ بِمَاۤ ءَاتَیۡتَهُنَّ كُلُّهُنَّۚ وَٱللَّهُ یَعۡلَمُ مَا فِی قُلُوبِكُمۡۚ وَكَانَ ٱللَّهُ عَلِیمًا حَلِیمࣰا ۝٥١", "juz": 22, "hizb": "(*¼ ح 43*)", "tafsir": "تؤخر مَن تشاء مِن نسائك في القَسْم في المبيت، وتضم إليك مَن تشاء منهن، ومَن طَلَبْتَ ممن أخَّرت قَسْمها، فلا إثم عليك في هذا، ذلك التخيير أقرب إلى أن يفرحن ولا يحزنَّ، ويرضين كلهن بما قسمت لهنَّ، والله يعلم ما في قلوب الرجال مِن مَيْلها إلى بعض النساء دون بعض. وكان الله عليمًا بما في القلوب، حليمًا لا يعجل بالعقوبة على من عصاه.", "isBasmala": false, "translation_en": "You may defer any of them you wish, and receive any of them you wish. Should you desire any of those you had deferred, there is no blame on you. This is more proper, so that they will be comforted, and not be grieved, and be content with what you have given each one of them. God knows what is within your hearts. God is Omniscient and Clement.", "translation_id": "Kamu boleh menangguhkan menggauli siapa yang kamu kehendaki di antara mereka (isteri-isterimu) dan (boleh pula) menggauli siapa yang kamu kehendaki. Dan siapa-siapa yang kamu ingini untuk menggaulinya kembali dari perempuan yang telah kamu cerai, maka tidak ada dosa bagimu. Yang demikian itu adalah lebih dekat untuk ketenangan hati mereka, dan mereka tidak merasa sedih, dan semuanya rela dengan apa yang telah kamu berikan kepada mereka. Dan Allah mengetahui apa yang (tersimpan) dalam hatimu. Dan adalah Allah Maha Mengetahui lagi Maha Penyantun.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 52, "text": "لَّا یَحِلُّ لَكَ ٱلنِّسَاۤءُ مِنۢ بَعۡدُ وَلَاۤ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَ ٰجࣲ وَلَوۡ أَعۡجَبَكَ حُسۡنُهُنَّ إِلَّا مَا مَلَكَتۡ یَمِینُكَۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ رَّقِیبࣰا ۝٥٢", "juz": 22, "hizb": "(*¼ ح 43*)", "tafsir": "لا يباح لك النساء من بعد نسائك اللاتي فى عصمتك، واللاتي أبحناهنَّ لك (وهنَّ المذكورات في الآية السابقة رقم [50] من هذه السورة)، ومن كانت في عصمتك من النساء المذكورات لا يحل لك أن تطلِّقها مستقبَلا وتأتي بغيرها بدلا منها، ولو أعجبك جمالها، وأما الزيادة على زوجاتك من غير تطليق إحداهن فلا حرج عليك، وأما ما ملكت يمينك من الإماء، فحلال لك منهن من شئت. وكان الله على كل شيء رقيبًا، لا يغيب عنه علم شيء.", "isBasmala": false, "translation_en": "Beyond that, no other women are permissible for you, nor can you exchange them for other wives, even if you admire their beauty, except those you already have. God is Watchful over all things.", "translation_id": "Tidak halal bagimu mengawini perempuan-perempuan sesudah itu dan tidak boleh (pula) mengganti mereka dengan isteri-isteri (yang lain), meskipun kecantikannya menarik hatimu kecuali perempuan-perempuan (hamba sahaya) yang kamu miliki. Dan adalah Allah Maha Mengawasi segala sesuatu.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 53, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَدۡخُلُوا۟ بُیُوتَ ٱلنَّبِیِّ إِلَّاۤ أَن یُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَیۡرَ نَـٰظِرِینَ إِنَىٰهُ وَلَـٰكِنۡ إِذَا دُعِیتُمۡ فَٱدۡخُلُوا۟ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُوا۟ وَلَا مُسۡتَـٔۡنِسِینَ لِحَدِیثٍۚ إِنَّ ذَ ٰلِكُمۡ كَانَ یُؤۡذِی ٱلنَّبِیَّ فَیَسۡتَحۡیِۦ مِنكُمۡۖ وَٱللَّهُ لَا یَسۡتَحۡیِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَـٰعࣰا فَسۡـَٔلُوهُنَّ مِن وَرَاۤءِ حِجَابࣲۚ ذَ ٰلِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُوا۟ رَسُولَ ٱللَّهِ وَلَاۤ أَن تَنكِحُوۤا۟ أَزۡوَ ٰجَهُۥ مِنۢ بَعۡدِهِۦۤ أَبَدًاۚ إِنَّ ذَ ٰلِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِیمًا ۝٥٣", "juz": 22, "hizb": "(*¼ ح 43*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تدخلوا بيوت النبي إلا بإذنه لتناول طعام غير منتظرين نضجه، ولكن إذا دعيتم فادخلوا، فإذا أكلتم فانصرفوا غير مستأنسين لحديث بينكم؛ فإن انتظاركم واستئناسكم يؤذي النبي، فيستحيي من إخراجكم من البيوت مع أن ذلك حق له، والله لا يستحيي من بيان الحق وإظهاره. وإذا سألتم نساء رسول الله صلى الله عليه وسلم حاجة من أواني البيت ونحوها فاسألوهن من وراء ستر؛ ذلكم أطهر لقلوبكم وقلوبهن من الخواطر التي تعرض للرجال في أمر النساء، وللنساء في أمر الرجال؛ فالرؤية سبب الفتنة، وما ينبغي لكم أن تؤذوا رسول الله، ولا أن تتزوجوا أزواجه من بعد موته أبدًا؛ لأنهن أمهاتكم، ولا يحلُّ للرجل أن يتزوج أمَّه، إنَّ أذاكم رسول الله صلى الله عليه وسلم ونكاحكم أزواجه من بعده إثم عظيم عند الله. (وقد امتثلت هذه الأمة هذا الأمر، واجتنبت ما نهى الله عنه منه).", "isBasmala": false, "translation_en": "O you who believe! Do not enter the homes of the Prophet, unless you are given permission to come for a meal; and do not wait for its preparation. And when you are invited, go in. And when you have eaten, disperse, without lingering for conversation. This irritates the Prophet, and he shies away from you, but God does not shy away from the truth. And when you ask his wives for something, ask them from behind a screen; that is purer for your hearts and their hearts. You must never offend the Messenger of God, nor must you ever marry his wives after him, for that would be an enormity with God.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu memasuki rumah-rumah Nabi kecuali bila kamu diizinkan untuk makan dengan tidak menunggu-nunggu waktu masak (makanannya), tetapi jika kamu diundang maka masuklah dan bila kamu selesai makan, keluarlah kamu tanpa asyik memperpanjang percakapan. Sesungguhnya yang demikian itu akan mengganggu Nabi lalu Nabi malu kepadamu (untuk menyuruh kamu keluar), dan Allah tidak malu (menerangkan) yang benar. Apabila kamu meminta sesuatu (keperluan) kepada mereka (isteri-isteri Nabi), maka mintalah dari belakang tabir. Cara yang demikian itu lebih suci bagi hatimu dan hati mereka. Dan tidak boleh kamu menyakiti (hati) Rasulullah dan tidak (pula) mengawini isteri-isterinya selama-lamanya sesudah ia wafat. Sesungguhnya perbuatan itu adalah amat besar (dosanya) di sisi Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 54, "text": "إِن تُبۡدُوا۟ شَیۡـًٔا أَوۡ تُخۡفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَیۡءٍ عَلِیمࣰا ۝٥٤", "juz": 22, "hizb": "(*¼ ح 43*)", "tafsir": "إن تُظْهِروا شيئًا على ألسنتكم -أيها الناس- مما يؤذي رسول الله مما نهاكم الله عنه، أو تخفوه في نفوسكم، فإن الله تعالى يعلم ما في قلوبكم وما أظهرتموه، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "Whether you declare a thing, or hide it, God is Aware of all things.", "translation_id": "Jika kamu melahirkan sesuatu atau menyembunyikannya, maka sesungguhnya Allah adalah Maha Mengetahui segala sesuatu.", "manzil": 5, "manzil_display": ""}], "426": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 55, "text": "لَّا جُنَاحَ عَلَیۡهِنَّ فِیۤ ءَابَاۤىِٕهِنَّ وَلَاۤ أَبۡنَاۤىِٕهِنَّ وَلَاۤ إِخۡوَ ٰنِهِنَّ وَلَاۤ أَبۡنَاۤءِ إِخۡوَ ٰنِهِنَّ وَلَاۤ أَبۡنَاۤءِ أَخَوَ ٰتِهِنَّ وَلَا نِسَاۤىِٕهِنَّ وَلَا مَا مَلَكَتۡ أَیۡمَـٰنُهُنَّۗ وَٱتَّقِینَ ٱللَّهَۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدًا ۝٥٥", "juz": 22, "hizb": "(*¼ ح 43*)", "tafsir": "لا إثم على النساء في عدم الاحتجاب من آبائهن وأبنائهن وإخوانهن وأبناء إخوانهن وأبناء أخواتهن والنساء المؤمنات والعبيد المملوكين لهن؛ لشدة الحاجة إليهم في الخدمة. وخفن الله -أيتها النساء- أن تتعدَّيْن ما حَدَّ لكنَّ، فتبدين من زينتكن ما ليس لكُنَّ أن تبدينه، أو تتركن الحجاب أمام مَن يجب عليكن الاحتجاب منه. إن الله كان على كل شيء شهيدًا، يشهد أعمال العباد ظاهرها وباطنها، وسيجزيهم عليها.", "isBasmala": false, "translation_en": "There is no blame on them concerning their fathers, or their sons, or their brothers, or their brothers' sons, or their sisters' sons, or their women, or their female servants. But they should remain conscious of God. God is Witness over all things.", "translation_id": "Tidak ada dosa atas isteri-isteri Nabi (untuk berjumpa tanpa tabir) dengan bapak-bapak mereka, anak-anak laki-laki mereka, saudara laki-laki mereka, anak laki-laki dari saudara laki-laki mereka, anak laki-laki dari saudara mereka yang perempuan yang beriman dan hamba sahaya yang mereka miliki, dan bertakwalah kamu (hai isteri-isteri Nabi) kepada Allah. Sesungguhnya Allah Maha Menyaksikan segala sesuatu.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 56, "text": "إِنَّ ٱللَّهَ وَمَلَـٰۤىِٕكَتَهُۥ یُصَلُّونَ عَلَى ٱلنَّبِیِّۚ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ صَلُّوا۟ عَلَیۡهِ وَسَلِّمُوا۟ تَسۡلِیمًا ۝٥٦", "juz": 22, "hizb": "(*¼ ح 43*)", "tafsir": "إن الله تعالى يثني على النبي صلى الله عليه وسلم عند الملائكة المقربين، وملائكته يثنون على النبي ويدعون له، يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، صلُّوا على رسول لله، وسلِّموا تسليمًا، تحية وتعظيمًا له. وصفة الصلاة على النبي صلى الله عليه وسلم ثبتت في السنة على أنواع، منها: \"اللهم صلِّ على محمد وعلى آل محمد، كما صليت على آل إبراهيم، إنك حميد مجيد، اللهم بارك على محمد وعلى آل محمد، كما باركت على آل إبراهيم، إنك حميد مجيد\".", "isBasmala": false, "translation_en": "God and His angels give blessings to the Prophet. O you who believe, call for blessings on him, and greet him with a prayer of peace.", "translation_id": "Sesungguhnya Allah dan malaikat-malaikat-Nya bershalawat untuk Nabi. Hai orang-orang yang beriman, bershalawatlah kamu untuk Nabi dan ucapkanlah salam penghormatan kepadanya.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 57, "text": "إِنَّ ٱلَّذِینَ یُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابࣰا مُّهِینࣰا ۝٥٧", "juz": 22, "hizb": "(*¼ ح 43*)", "tafsir": "إن الذين يؤذون الله بالشرك أو غيره من المعاصي، ويؤذون رسول الله بالأقوال أو الأفعال، أبعدهم الله وطردهم مِن كل خير في الدنيا والآخرة، وأعدَّ لهم في الآخرة عذابًا يذلهم ويهينهم.", "isBasmala": false, "translation_en": "Those who insult God and His Messenger, God has cursed them in this life and in the Hereafter, and has prepared for them a demeaning punishment.", "translation_id": "Sesungguhnya orang-orang yang menyakiti Allah dan Rasul-Nya. Allah akan melaknatinya di dunia dan di akhirat, dan menyediakan baginya siksa yang menghinakan.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 58, "text": "وَٱلَّذِینَ یُؤۡذُونَ ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ بِغَیۡرِ مَا ٱكۡتَسَبُوا۟ فَقَدِ ٱحۡتَمَلُوا۟ بُهۡتَـٰنࣰا وَإِثۡمࣰا مُّبِینࣰا ۝٥٨", "juz": 22, "hizb": "(*¼ ح 43*)", "tafsir": "والذين يؤذون المؤمنين والمؤمنات بقول أو فعل من غير ذنب عملوه، فقد ارتكبوا أفحش الكذب والزور، وأتوا ذنبًا ظاهر القبح يستحقون به العذاب في الآخرة.", "isBasmala": false, "translation_en": "Those who harm believing men and believing women, for acts they did not commit, bear the burden of perjury and a flagrant sin.", "translation_id": "Dan orang-orang yang menyakiti orang-orang yang mukmin dan mukminat tanpa kesalahan yang mereka perbuat, maka sesungguhnya mereka telah memikul kebohongan dan dosa yang nyata.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 59, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ قُل لِّأَزۡوَ ٰجِكَ وَبَنَاتِكَ وَنِسَاۤءِ ٱلۡمُؤۡمِنِینَ یُدۡنِینَ عَلَیۡهِنَّ مِن جَلَـٰبِیبِهِنَّۚ ذَ ٰلِكَ أَدۡنَىٰۤ أَن یُعۡرَفۡنَ فَلَا یُؤۡذَیۡنَۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا ۝٥٩", "juz": 22, "hizb": "(*¼ ح 43*)", "tafsir": "يا أيها النبي قل لأزواجك وبناتك ونساء المؤمنين يرخين على رؤوسهن ووجوههن من أرديتهن وملاحفهن؛ لستر وجوههن وصدورهن ورؤوسهن؛ ذلك أقرب أن يميَّزن بالستر والصيانة، فلا يُتعَرَّض لهن بمكروه أو أذى. وكان الله غفورًا رحيمًا حيث غفر لكم ما سلف، ورحمكم بما أوضح لكم من الحلال والحرام.", "isBasmala": false, "translation_en": "O Prophet! Tell your wives, and your daughters, and the women of the believers, to lengthen their garments. That is more proper, so they will be recognized and not harassed. God is Forgiving and Merciful.", "translation_id": "Hai Nabi, katakanlah kepada isteri-isterimu, anak-anak perempuanmu dan isteri-isteri orang mukmin: \"Hendaklah mereka mengulurkan jilbabnya ke seluruh tubuh mereka\". Yang demikian itu supaya mereka lebih mudah untuk dikenal, karena itu mereka tidak di ganggu. Dan Allah adalah Maha Pengampun lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 60, "text": "۞ لَّىِٕن لَّمۡ یَنتَهِ ٱلۡمُنَـٰفِقُونَ وَٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ وَٱلۡمُرۡجِفُونَ فِی ٱلۡمَدِینَةِ لَنُغۡرِیَنَّكَ بِهِمۡ ثُمَّ لَا یُجَاوِرُونَكَ فِیهَاۤ إِلَّا قَلِیلࣰا ۝٦٠", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "لئن لم يكفَّ الذين يضمرون الكفر ويظهرون الإيمان والذين في قلوبهم شك وريبة، والذين ينشرون الأخبار الكاذبة في مدينة الرسول صلى الله عليه وسلم عن قبائحهم وشرورهم، لنسلِّطنَّك عليهم، ثم لا يسكنون معك فيها إلا زمنًا قليلا. مطرودين من رحمة الله، في أي مكان وُجِدوا فيه أُسِروا وقُتِّلوا تقتيلا ما داموا مقيمين على النفاق ونشر الأخبار الكاذبة بين المسلمين بغرض الفتنة والفساد.", "isBasmala": false, "translation_en": "If the hypocrites, and those with sickness in their hearts, and the rumormongers in the City, do not desist, We will incite you against them; then they will not be your neighbors there except for a short while.", "translation_id": "Sesungguhnya jika tidak berhenti orang-orang munafik, orang-orang yang berpenyakit dalam hatinya dan orang-orang yang menyebarkan kabar bohong di Madinah (dari menyakitimu), niscaya Kami perintahkan kamu (untuk memerangi) mereka, kemudian mereka tidak menjadi tetanggamu (di Madinah) melainkan dalam waktu yang sebentar,", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 61, "text": "مَّلۡعُونِینَۖ أَیۡنَمَا ثُقِفُوۤا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقۡتِیلࣰا ۝٦١", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "لئن لم يكفَّ الذين يضمرون الكفر ويظهرون الإيمان والذين في قلوبهم شك وريبة، والذين ينشرون الأخبار الكاذبة في مدينة الرسول صلى الله عليه وسلم عن قبائحهم وشرورهم، لنسلِّطنَّك عليهم، ثم لا يسكنون معك فيها إلا زمنًا قليلا. مطرودين من رحمة الله، في أي مكان وُجِدوا فيه أُسِروا وقُتِّلوا تقتيلا ما داموا مقيمين على النفاق ونشر الأخبار الكاذبة بين المسلمين بغرض الفتنة والفساد.", "isBasmala": false, "translation_en": "They are cursed; wherever they are found, they should be captured and killed outright.", "translation_id": "dalam keadaan terlaknat. Di mana saja mereka dijumpai, mereka ditangkap dan dibunuh dengan sehebat-hebatnya.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 62, "text": "سُنَّةَ ٱللَّهِ فِی ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِیلࣰا ۝٦٢", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "سنة الله وطريقته في منافقي الأمم السابقة أن يؤسَروا ويُقَتَّلوا أينما كانوا، ولن تجد -أيها النبي- لطريقة الله تحويلا ولا تغييرًا.", "isBasmala": false, "translation_en": "Such has been God's precedent with those who passed away before. You will find no change in God's system.", "translation_id": "Sebagai sunnah Allah yang berlaku atas orang-orang yang telah terdahulu sebelum(mu), dan kamu sekali-kali tiada akan mendapati peubahan pada sunnah Allah.", "manzil": 5, "manzil_display": ""}], "427": [{"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 63, "text": "یَسۡـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِۚ وَمَا یُدۡرِیكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِیبًا ۝٦٣", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "يسألك الناس -أيها الرسول- عن وقت القيامة استبعادًا وتكذيبًا، قل لهم: إنما علم الساعة عند الله، وما يدريك -أيها الرسول- لعل زمانها قريب؟", "isBasmala": false, "translation_en": "The people ask you about the Hour. Say, \"The knowledge thereof rests with God. But what do you know? Perhaps the hour is near.\"", "translation_id": "Manusia bertanya kepadamu tentang hari berbangkit. Katakanlah: \"Sesungguhnya pengetahuan tentang hari berbangkit itu hanya di sisi Allah\". Dan tahukah kamu (hai Muhammad), boleh jadi hari berbangkit itu sudah dekat waktunya.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 64, "text": "إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَـٰفِرِینَ وَأَعَدَّ لَهُمۡ سَعِیرًا ۝٦٤", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "إن الله طرد الكافرين من رحمته في الدنيا والآخرة، وأعدَّ لهم في الآخرة نارًا موقدة شديدة الحرارة، ماكثين فيها أبدًا، لا يجدون وليًّا يتولاهم ويدافع عنهم، ولا نصيرًا ينصرهم، فيخرجهم من النار. يوم تُقَلَّب وجوه الكافرين في النار يقولون نادمين متحيِّرين: يا ليتنا أطعنا الله وأطعنا رسوله في الدنيا، فكنا من أهل الجنة.", "isBasmala": false, "translation_en": "God has cursed the disbelievers, and has prepared for them a Blaze.", "translation_id": "Sesungguhnya Allah melaknati orang-orang kafir dan menyediakan bagi mereka api yang menyala-nyala (neraka),", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 65, "text": "خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ لَّا یَجِدُونَ وَلِیࣰّا وَلَا نَصِیرࣰا ۝٦٥", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "إن الله طرد الكافرين من رحمته في الدنيا والآخرة، وأعدَّ لهم في الآخرة نارًا موقدة شديدة الحرارة، ماكثين فيها أبدًا، لا يجدون وليًّا يتولاهم ويدافع عنهم، ولا نصيرًا ينصرهم، فيخرجهم من النار. يوم تُقَلَّب وجوه الكافرين في النار يقولون نادمين متحيِّرين: يا ليتنا أطعنا الله وأطعنا رسوله في الدنيا، فكنا من أهل الجنة.", "isBasmala": false, "translation_en": "Dwelling therein forever, not finding a protector or a savior.", "translation_id": "mereka kekal di dalamnya selama-lamanya; mereka tidak memperoleh seorang pelindungpun dan tidak (pula) seorang penolong.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 66, "text": "یَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِی ٱلنَّارِ یَقُولُونَ یَـٰلَیۡتَنَاۤ أَطَعۡنَا ٱللَّهَ وَأَطَعۡنَا ٱلرَّسُولَا۠ ۝٦٦", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "إن الله طرد الكافرين من رحمته في الدنيا والآخرة، وأعدَّ لهم في الآخرة نارًا موقدة شديدة الحرارة، ماكثين فيها أبدًا، لا يجدون وليًّا يتولاهم ويدافع عنهم، ولا نصيرًا ينصرهم، فيخرجهم من النار. يوم تُقَلَّب وجوه الكافرين في النار يقولون نادمين متحيِّرين: يا ليتنا أطعنا الله وأطعنا رسوله في الدنيا، فكنا من أهل الجنة.", "isBasmala": false, "translation_en": "The Day when their faces are flipped into the Fire, they will say, \"If only we had obeyed God and obeyed the Messenger.\"", "translation_id": "Pada hari ketika muka mereka dibolak-balikan dalam neraka, mereka berkata: \"Alangkah baiknya, andaikata kami taat kepada Allah dan taat (pula) kepada Rasul\".", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 67, "text": "وَقَالُوا۟ رَبَّنَاۤ إِنَّاۤ أَطَعۡنَا سَادَتَنَا وَكُبَرَاۤءَنَا فَأَضَلُّونَا ٱلسَّبِیلَا۠ ۝٦٧", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "وقال الكافرون يوم القيامة: ربنا إنا أطَعْنا أئمتنا في الضلال وكبراءنا في الشرك، فأزالونا عن طريق الهُدى والإيمان. ربنا عذِّبهم من العذاب مثلَيْ عذابنا الذي تعذبنا به، واطردهم من رحمتك طردًا شديدًا. وفي هذا دليل على أن طاعة غير الله في مخالفة أمره وأمر رسوله، موجبة لسخط الله وعقابه، وأن التابع والمتبوع في العذاب مشتركون، فليحذر المسلم ذلك.", "isBasmala": false, "translation_en": "And they will say, \"Lord, we have obeyed our superiors and our dignitaries, but they led us away from the way.", "translation_id": "Dan mereka berkata: \"Ya Tuhan kami, sesungguhnya kami telah mentaati pemimpin-pemimpin dan pembesar-pembesar kami, lalu mereka menyesatkan kami dari jalan (yang benar).", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 68, "text": "رَبَّنَاۤ ءَاتِهِمۡ ضِعۡفَیۡنِ مِنَ ٱلۡعَذَابِ وَٱلۡعَنۡهُمۡ لَعۡنࣰا كَبِیرࣰا ۝٦٨", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "وقال الكافرون يوم القيامة: ربنا إنا أطَعْنا أئمتنا في الضلال وكبراءنا في الشرك، فأزالونا عن طريق الهُدى والإيمان. ربنا عذِّبهم من العذاب مثلَيْ عذابنا الذي تعذبنا به، واطردهم من رحمتك طردًا شديدًا. وفي هذا دليل على أن طاعة غير الله في مخالفة أمره وأمر رسوله، موجبة لسخط الله وعقابه، وأن التابع والمتبوع في العذاب مشتركون، فليحذر المسلم ذلك.", "isBasmala": false, "translation_en": "Lord, give them double the punishment, and curse them with a great curse.\"", "translation_id": "Ya Tuhan kami, timpakanlah kepada mereka azab dua kali lipat dan kutuklah mereka dengan kutukan yang besar\".", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 69, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِینَ ءَاذَوۡا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ۚ وَكَانَ عِندَ ٱللَّهِ وَجِیهࣰا ۝٦٩", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه لا تؤذوا رسول الله بقول أو فعل، ولا تكونوا أمثال الذين آذوا نبيَّ الله موسى، فبرَّأه الله مما قالوا فيه من الكذب والزور، وكان عند الله عظيم القدر والجاه.", "isBasmala": false, "translation_en": "O you who believe! Do not be like those who abused Moses; but God cleared him of what they said. He was distinguished with God.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu menjadi seperti orang-orang yang menyakiti Musa; maka Allah membersihkannya dari tuduhan-tuduhan yang mereka katakan. Dan adalah dia seorang yang mempunyai kedudukan terhormat di sisi Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 70, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوۡلࣰا سَدِیدࣰاۙ ۝٧٠", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، اعملوا بطاعته، واجتنبوا معصيته؛ لئلا تستحقوا بذلك العقاب، وقولوا في جميع أحوالكم وشؤونكم قولا مستقيمًا موافقًا للصواب خاليًا من الكذب والباطل.", "isBasmala": false, "translation_en": "O you who believe! Be conscious of God, and speak in a straightforward manner.", "translation_id": "Hai orang-orang yang beriman, bertakwalah kamu kepada Allah dan katakanlah perkataan yang benar,", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 71, "text": "یُصۡلِحۡ لَكُمۡ أَعۡمَـٰلَكُمۡ وَیَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن یُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِیمًا ۝٧١", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "إذا اتقيتم الله وقلتم قولا سديدًا أصلح الله لكم أعمالكم، وغفر ذنوبكم. ومن يطع الله ورسوله فيما أمر ونهى فقد فاز بالكرامة العظمى في الدنيا والآخرة.", "isBasmala": false, "translation_en": "He will rectify your conduct for you, and will forgive you your sins. Whoever obeys God and His Messenger has won a great victory.", "translation_id": "niscaya Allah memperbaiki bagimu amalan-amalanmu dan mengampuni bagimu dosa-dosamu. Dan barangsiapa mentaati Allah dan Rasul-Nya, maka sesungguhnya ia telah mendapat kemenangan yang besar.", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 72, "text": "إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَیۡنَ أَن یَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَـٰنُۖ إِنَّهُۥ كَانَ ظَلُومࣰا جَهُولࣰا ۝٧٢", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "إنا عرضنا الأمانة -التي ائتمن الله عليها المكلَّفين من امتثال الأوامر واجتناب النواهي- على السموات والأرض والجبال، فأبين أن يحملنها، وخفن أن لا يقمن بأدائها، وحملها الإنسان والتزم بها على ضعفه، إنه كان شديد الظلم والجهل لنفسه.", "isBasmala": false, "translation_en": "We offered the Trust to the heavens, and the earth, and the mountains; but they refused to bear it, and were apprehensive of it; but the human being accepted it. He was unfair and ignorant.", "translation_id": "Sesungguhnya Kami telah mengemukakan amanat kepada langit, bumi dan gunung-gunung, maka semuanya enggan untuk memikul amanat itu dan mereka khawatir akan mengkhianatinya, dan dipikullah amanat itu oleh manusia. Sesungguhnya manusia itu amat zalim dan amat bodoh,", "manzil": 5, "manzil_display": ""}, {"sura": 33, "sura_name": "الأحزاب", "revelation": "Madaniyah", "aya": 73, "text": "لِّیُعَذِّبَ ٱللَّهُ ٱلۡمُنَـٰفِقِینَ وَٱلۡمُنَـٰفِقَـٰتِ وَٱلۡمُشۡرِكِینَ وَٱلۡمُشۡرِكَـٰتِ وَیَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمَۢا ۝٧٣", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "(وحمل الإنسان الأمانة) ليعذب الله المنافقين الذين يُظهرون الإسلام ويُخفون الكفر، والمنافقات، والمشركين في عبادة الله غيره، والمشركات، ويتوب الله على المؤمنين والمؤمنات بستر ذنوبهم وترك عقابهم. وكان الله غفورًا للتائبين من عباده، رحيمًا بهم.", "isBasmala": false, "translation_en": "God will punish the hypocrites, men and women, and the idolaters, men and women. And God will redeem the believers, men and women. God is Ever-Forgiving, Most Merciful.", "translation_id": "sehingga Allah mengazab orang-orang munafik laki-laki dan perempuan dan orang-orang musyrikin laki-laki dan perempuan; dan sehingga Allah menerima taubat orang-orang mukmin laki-laki dan perempuan. Dan adalah Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}], "428": [{"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 22, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 1, "text": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِ وَلَهُ ٱلۡحَمۡدُ فِی ٱلۡـَٔاخِرَةِۚ وَهُوَ ٱلۡحَكِیمُ ٱلۡخَبِیرُ ۝١", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "الثناء على الله بصفاته التي كلُّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، الذي له ملك ما في السموات وما في الأرض، وله الثناء التام في الآخرة، وهو الحكيم في فعله، الخبير بشؤون خلقه.", "isBasmala": false, "translation_en": "Praise be to God, to Whom belongs everything in the heavens and the earth; and praise be to Him in the Hereafter. He is the Wise, the Expert.", "translation_id": "Segala puji bagi Allah yang memiliki apa yang di langit dan apa yang di bumi dan bagi-Nya (pula) segala puji di akhirat. Dan Dialah Yang Maha Bijaksana lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 2, "text": "یَعۡلَمُ مَا یَلِجُ فِی ٱلۡأَرۡضِ وَمَا یَخۡرُجُ مِنۡهَا وَمَا یَنزِلُ مِنَ ٱلسَّمَاۤءِ وَمَا یَعۡرُجُ فِیهَاۚ وَهُوَ ٱلرَّحِیمُ ٱلۡغَفُورُ ۝٢", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "يعلم كل ما يدخل في الأرض من قطرات الماء، وما يخرج منها من النبات والمعادن والمياه، وما ينزل من السماء من الأمطار والملائكة والكتب، وما يصعد إليها من الملائكة وأفعال الخلق. وهو الرحيم بعباده فلا يعاجل عصاتهم بالعقوبة، الغفور لذنوب التائبين إليه المتوكلين عليه.", "isBasmala": false, "translation_en": "He knows what penetrates into the earth, and what comes out of it, and what descends from the sky, and what ascends to it. He is the Merciful, the Forgiving.", "translation_id": "Dia mengetahui apa yang masuk ke dalam bumi, apa yang ke luar daripadanya, apa yang turun dari langit dan apa yang naik kepadanya. Dan Dialah Yang Maha Penyayang lagi Maha Pengampun.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 3, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَا تَأۡتِینَا ٱلسَّاعَةُۖ قُلۡ بَلَىٰ وَرَبِّی لَتَأۡتِیَنَّكُمۡ عَـٰلِمِ ٱلۡغَیۡبِۖ لَا یَعۡزُبُ عَنۡهُ مِثۡقَالُ ذَرَّةࣲ فِی ٱلسَّمَـٰوَ ٰتِ وَلَا فِی ٱلۡأَرۡضِ وَلَاۤ أَصۡغَرُ مِن ذَ ٰلِكَ وَلَاۤ أَكۡبَرُ إِلَّا فِی كِتَـٰبࣲ مُّبِینࣲ ۝٣", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "وقال الكافرون المنكرون للبعث: لا تأتينا القيامة، قل لهم -أيها الرسول-: بلى وربي لتأتينَّكم، ولكن لا يعلم وقت مجيئها أحد سوى الله علام الغيوب، الذي لا يغيب عنه وزن نملة صغيرة في السموات والأرض، ولا أصغر من ذلك ولا أكبر إلا هو مسطور في كتاب واضح، وهو اللوح المحفوظ؛ ليثيب الذين صدَّقوا بالله، واتَّبَعوا رسوله، وعملوا الصالحات. أولئك لهم مغفرة لذنوبهم ورزق كريم، وهو الجنة.", "isBasmala": false, "translation_en": "Those who disbelieve say, \"The Hour will not come upon us.\" Say, \"Yes indeed, by my Lord, it will come upon you. He is the Knower of the unseen.\" Not an atom's weight in the heavens and the earth, or anything smaller or larger, escapes His knowledge. All are in a Clear Record.", "translation_id": "Dan orang-orang yang kafir berkata: \"Hari berbangkit itu tidak akan datang kepada kami\". Katakanlah: \"Pasti datang, demi Tuhanku Yang Mengetahui yang ghaib, sesungguhnya kiamat itu pasti akan datang kepadamu. Tidak ada tersembunyi daripada-Nya sebesar zarrahpun yang ada di langit dan yang ada di bumi dan tidak ada (pula) yang lebih kecil dari itu dan yang lebih besar, melainkan tersebut dalam Kitab yang nyata (Lauh Mahfuzh)\",", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 4, "text": "لِّیَجۡزِیَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِۚ أُو۟لَـٰۤىِٕكَ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ ۝٤", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "وقال الكافرون المنكرون للبعث: لا تأتينا القيامة، قل لهم -أيها الرسول-: بلى وربي لتأتينَّكم، ولكن لا يعلم وقت مجيئها أحد سوى الله علام الغيوب، الذي لا يغيب عنه وزن نملة صغيرة في السموات والأرض، ولا أصغر من ذلك ولا أكبر إلا هو مسطور في كتاب واضح، وهو اللوح المحفوظ؛ ليثيب الذين صدَّقوا بالله، واتَّبَعوا رسوله، وعملوا الصالحات. أولئك لهم مغفرة لذنوبهم ورزق كريم، وهو الجنة.", "isBasmala": false, "translation_en": "That He may recompense those who believe and do good works. Those will have forgiveness, and a generous provision.", "translation_id": "supaya Allah memberi balasan kepada orang-orang yang beriman dan mengerjakan amal yang saleh. Mereka itu adalah orang-orang yang baginya ampunan dan rezeki yang mulia.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 5, "text": "وَٱلَّذِینَ سَعَوۡ فِیۤ ءَایَـٰتِنَا مُعَـٰجِزِینَ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مِّن رِّجۡزٍ أَلِیمࣱ ۝٥", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "والذين سعوا في الصدِّ عن سبيل الله وتكذيب رسله وإبطال آياتنا مشاقين الله مغالبين أمره، أولئك لهم أسوأ العذاب وأشده ألمًا.", "isBasmala": false, "translation_en": "As for those who strive against Our revelations, seeking to undermine them-for them is a punishment of a painful plague.", "translation_id": "Dan orang-orang yang berusaha untuk (menentang) ayat-ayat Kami dengan anggapan mereka dapat melemahkan (menggagalkan azab Kami), mereka itu memperoleh azab, yaitu (jenis) azab yang pedih.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 6, "text": "وَیَرَى ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ ٱلَّذِیۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ وَیَهۡدِیۤ إِلَىٰ صِرَ ٰطِ ٱلۡعَزِیزِ ٱلۡحَمِیدِ ۝٦", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "ويعلم الذين أُعطوا العلم أن القرآن الذي أُنزل إليك من ربك هو الحق، ويرشد إلى طريق الله، العزيز الذي لا يغالَب ولا يمانع، بل قهر كل شيء وغلبه، المحمود في أقواله وأفعاله وشرعه.", "isBasmala": false, "translation_en": "Those who received knowledge know that what is revealed to you from your Lord is the truth; and it guides to the path of the Majestic, the Praiseworthy.", "translation_id": "Dan orang-orang yang diberi ilmu (Ahli Kitab) berpendapat bahwa wahyu yang diturunkan kepadamu dari Tuhanmu itulah yang benar dan menunjuki (manusia) kepada jalan Tuhan Yang Maha Perkasa lagi Maha Terpuji.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 7, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوا۟ هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلࣲ یُنَبِّئُكُمۡ إِذَا مُزِّقۡتُمۡ كُلَّ مُمَزَّقٍ إِنَّكُمۡ لَفِی خَلۡقࣲ جَدِیدٍ ۝٧", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "وقال الذين كفروا بعضهم لبعض استهزاء: هل ندلكم على رجل (يريدون محمدًا صلى الله عليه وسلم) يخبركم أنكم إذا متم وتفرقت أجسامكم كل تفرُّق، إنكم ستُحيون وتُبعثون من قبوركم؟ قالوا ذلك مِن فرط إنكارهم.", "isBasmala": false, "translation_en": "Those who disbelieved said, \"Shall we point out to you a man, who will tell you that, once torn into shreds, you will be in a new creation?", "translation_id": "Dan orang-orang kafir berkata (kepada teman-temannya). \"Maukah kamu kami tunjukkan kepadamu seorang laki-laki yang memberitakan kepadamu bahwa apabila badanmu telah hancur sehancur-hancurnya, sesungguhnya kamu benar-benar (akan dibangkitkan kembali) dalam ciptaan yang baru?", "manzil": 5, "manzil_display": ""}], "429": [{"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 8, "text": "أَفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةُۢۗ بَلِ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ فِی ٱلۡعَذَابِ وَٱلضَّلَـٰلِ ٱلۡبَعِیدِ ۝٨", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "هذا الرجل أختلق على الله كذبًا أم به جنون، فهو يتكلم بما لا يدري؟ ليس الأمر كما قال الكفار، بل محمد أصدق الصادقين. والذين لا يصدقون بالبعث ولا يعملون من أجله في العذاب الدائم في الآخرة، والضلال البعيد عن الصواب في الدنيا.", "isBasmala": false, "translation_en": "Did he invent a lie about God, or is there madness in him?\" Indeed, those who do not believe in the Hereafter are in torment, and far astray.", "translation_id": "Apakah dia mengada-adakan kebohongan terhadap Allah ataukah ada padanya penyakit gila?\" (Tidak), tetapi orang-orang yang tidak beriman kepada negeri akhirat berada dalam siksaan dan kesesatan yang jauh.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 9, "text": "أَفَلَمۡ یَرَوۡا۟ إِلَىٰ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَیۡهِمۡ كِسَفࣰا مِّنَ ٱلسَّمَاۤءِۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَةࣰ لِّكُلِّ عَبۡدࣲ مُّنِیبࣲ ۝٩", "juz": 22, "hizb": "(*½ ح 43*)", "tafsir": "أفلم ير هؤلاء الكفار الذين لا يؤمنون بالآخرة عظيم قدرة الله فيما بين أيديهم وما خلفهم من السماء والأرض مما يبهر العقول، وأنهما قد أحاطتا بهم؟ إن نشأ نخسف بهم الأرض، كما فعلنا بقارون، أو ننزل عليهم قطعًا من العذاب، كما فعلنا بقوم شعيب، فقد أمطرت السماء عليهم نارًا فأحرقتهم. إن في ذلك الذي ذكرنا من قدرتنا لَدلالة ظاهرة لكل عبد راجع إلى ربه بالتوبة، ومقر له بتوحيده، ومخلص له في العبادة.", "isBasmala": false, "translation_en": "Do they not reflect upon what lies before them and behind them, of the heaven and the earth? If We will, We can make the earth cave in beneath them, or make pieces of the sky fall down on them. In that is a sign for every devout servant.", "translation_id": "Maka apakah mereka tidak melihat langit dan bumi yang ada di hadapan dan di belakang mereka? Jika Kami menghendaki, niscaya Kami benamkan mereka di bumi atau Kami jatuhkan kepada mereka gumpalan dari langit. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda (kekuasaan Tuhan) bagi setiap hamba yang kembali (kepada-Nya).", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 10, "text": "۞ وَلَقَدۡ ءَاتَیۡنَا دَاوُۥدَ مِنَّا فَضۡلࣰاۖ یَـٰجِبَالُ أَوِّبِی مَعَهُۥ وَٱلطَّیۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِیدَ ۝١٠", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "ولقد آتينا داود نبوة، وكتابًا وعلمًا، وقلنا للجبال والطير: سبِّحي معه، وألنَّا له الحديد، فكان كالعجين يتصرف فيه كيف يشاء.", "isBasmala": false, "translation_en": "We bestowed upon David favor from Us: \"O mountains, and birds: echo with him.\" And We softened iron for him.", "translation_id": "Dan sesungguhnya telah Kami berikan kepada Daud kurnia dari Kami. (Kami berfirman): \"Hai gunung-gunung dan burung-burung, bertasbihlah berulang-ulang bersama Daud\", dan Kami telah melunakkan besi untuknya,", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 11, "text": "أَنِ ٱعۡمَلۡ سَـٰبِغَـٰتࣲ وَقَدِّرۡ فِی ٱلسَّرۡدِۖ وَٱعۡمَلُوا۟ صَـٰلِحًاۖ إِنِّی بِمَا تَعۡمَلُونَ بَصِیرࣱ ۝١١", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "أن اعمل دروعًا تامات واسعات وقدِّر المسامير في حِلَق الدروع، فلا تعمل الحلقة صغيرة فتَضْعُف، فلا تقوى الدروع على الدفاع، ولا تجعلها كبيرة فتثقُل على لابسها، واعمل يا داود أنت وأهلك بطاعة الله، إني بما تعملون بصير لا يخفى عليَّ شيء منها.", "isBasmala": false, "translation_en": "\"Make coats of armor, and measure the links well; and work righteousness. I am Observant of everything you do.\"", "translation_id": "(yaitu) buatlah baju besi yang besar-besar dan ukurlah anyamannya; dan kerjakanlah amalan yang saleh. Sesungguhnya Aku melihat apa yang kamu kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 12, "text": "وَلِسُلَیۡمَـٰنَ ٱلرِّیحَ غُدُوُّهَا شَهۡرࣱ وَرَوَاحُهَا شَهۡرࣱۖ وَأَسَلۡنَا لَهُۥ عَیۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن یَعۡمَلُ بَیۡنَ یَدَیۡهِ بِإِذۡنِ رَبِّهِۦۖ وَمَن یَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِیرِ ۝١٢", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "وسخَّرنا لسليمان الريح تجري من أول النهار إلى انتصافه مسيرة شهر، ومن منتصف النهار إلى الليل مسيرة شهر بالسير المعتاد، وأسلنا له النحاس كما يسيل الماء، يعمل به ما يشاء، وسخَّرنا له من الجن من يعمل بين يديه بإذن ربه، ومن يعدل منهم عن أمرنا الذي أمرناه به من طاعة سليمان نذقه من عذاب النار المستعرة.", "isBasmala": false, "translation_en": "And for Solomon the wind-its outward journey was one month, and its return journey was one month. And We made a spring of tar flow for him. And there were sprites that worked under him, by the leave of his Lord. But whoever of them swerved from Our command, We make him taste of the punishment of the Inferno.", "translation_id": "Dan Kami (tundukkan) angin bagi Sulaiman, yang perjalanannya di waktu pagi sama dengan perjalanan sebulan dan perjalanannya di waktu sore sama dengan perjalanan sebulan (pula) dan Kami alirkan cairan tembaga baginya. Dan sebahagian dari jin ada yang bekerja di hadapannya (di bawah kekuasaannya) dengan izin Tuhannya. Dan siapa yang menyimpang di antara mereka dari perintah Kami, Kami rasakan kepadanya azab neraka yang apinya menyala-nyala.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 13, "text": "یَعۡمَلُونَ لَهُۥ مَا یَشَاۤءُ مِن مَّحَـٰرِیبَ وَتَمَـٰثِیلَ وَجِفَانࣲ كَٱلۡجَوَابِ وَقُدُورࣲ رَّاسِیَـٰتٍۚ ٱعۡمَلُوۤا۟ ءَالَ دَاوُۥدَ شُكۡرࣰاۚ وَقَلِیلࣱ مِّنۡ عِبَادِیَ ٱلشَّكُورُ ۝١٣", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "يعمل الجن لسليمان ما يشاء من مساجد للعبادة، وصور من نحاس وزجاج، وقِصَاع كبيرة كالأحواض التي يجتمع فيها الماء، وقدور ثابتات لا تتحرك من أماكنها لعظمهن، وقلنا يا آل داود: اعملوا شكرًا لله على ما أعطاكم، وذلك بطاعته وامتثال أمره، وقليل من عبادي من يشكر الله كثيرًا، وكان داود وآله من القليل.", "isBasmala": false, "translation_en": "They made for him whatever he wished: sanctuaries, statues, bowls like pools, and heavy cauldrons. \"O House of David, work with appreciation,\" but a few of My servants are appreciative.", "translation_id": "Para jin itu membuat untuk Sulaiman apa yang dikehendakinya dari gedung-gedung yang tinggi dan patung-patung dan piring-piring yang (besarnya) seperti kolam dan periuk yang tetap (berada di atas tungku). Bekerjalah hai keluarga Daud untuk bersyukur (kepada Allah). Dan sedikit sekali dari hamba-hamba-Ku yang berterima kasih.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 14, "text": "فَلَمَّا قَضَیۡنَا عَلَیۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦۤ إِلَّا دَاۤبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَیَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُوا۟ یَعۡلَمُونَ ٱلۡغَیۡبَ مَا لَبِثُوا۟ فِی ٱلۡعَذَابِ ٱلۡمُهِینِ ۝١٤", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "فلما قضينا على سليمان بالموت ما دلَّ الجن على موته إلا الأرَضَةُ تأكل عصاه التي كان متكئًا عليها، فوقع سليمان على الأرض، عند ذلك علمت الجن أنهم لو كانوا يعلمون الغيب ما أقاموا في العذاب المذلِّ والعمل الشاق لسليمان؛ ظنا منهم أنه من الأحياء. وفي الآية إبطال لاعتقاد بعض الناس أن الجن يعلمون الغيب؛ إذ لو كانوا يعلمون الغيب لعلموا وفاة سليمان عليه السلام، ولما أقاموا في العذاب المهين.", "isBasmala": false, "translation_en": "Then, when We decreed death for him, nothing indicated his death to them except an earthworm eating at his staff. Then, when he fell down, it became clear to the sprites that, had they known the unseen, they would not have remained in the demeaning torment.", "translation_id": "Maka tatkala Kami telah menetapkan kematian Sulaiman, tidak ada yang menunjukkan kepada mereka kematiannya itu kecuali rayap yang memakan tongkatnya. Maka tatkala ia telah tersungkur, tahulah jin itu bahwa kalau sekiranya mereka mengetahui yang ghaib tentulah mereka tidak akan tetap dalam siksa yang menghinakan.", "manzil": 5, "manzil_display": ""}], "430": [{"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 15, "text": "لَقَدۡ كَانَ لِسَبَإࣲ فِی مَسۡكَنِهِمۡ ءَایَةࣱۖ جَنَّتَانِ عَن یَمِینࣲ وَشِمَالࣲۖ كُلُوا۟ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُوا۟ لَهُۥۚ بَلۡدَةࣱ طَیِّبَةࣱ وَرَبٌّ غَفُورࣱ ۝١٥", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "لقد كان لقبيلة سبأ بـ \"اليمن\" في مسكنهم دلالة على قدرتنا: بستانان عن يمين وشمال، كلوا من رزق ربكم، واشكروا له نعمه عليكم؛ فإن بلدتكم كريمة التربة حسنة الهواء، وربكم غفور لكم.", "isBasmala": false, "translation_en": "In Sheba's homeland there used to be a wonder: two gardens, on the right, and on the left. \"Eat of your Lord's provision, and give thanks to Him.\" A good land, and a forgiving Lord.", "translation_id": "Sesungguhnya bagi kaum Saba' ada tanda (kekuasaan Tuhan) di tempat kediaman mereka yaitu dua buah kebun di sebelah kanan dan di sebelah kiri. (kepada mereka dikatakan): \"Makanlah olehmu dari rezeki yang (dianugerahkan) Tuhanmu dan bersyukurlah kamu kepada-Nya. (Negerimu) adalah negeri yang baik dan (Tuhanmu) adalah Tuhan Yang Maha Pengampun\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 16, "text": "فَأَعۡرَضُوا۟ فَأَرۡسَلۡنَا عَلَیۡهِمۡ سَیۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَـٰهُم بِجَنَّتَیۡهِمۡ جَنَّتَیۡنِ ذَوَاتَیۡ أُكُلٍ خَمۡطࣲ وَأَثۡلࣲ وَشَیۡءࣲ مِّن سِدۡرࣲ قَلِیلࣲ ۝١٦", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "فأعرضوا عن أمر الله وشكره وكذبوا الرسل، فأرسلنا عليهم السيل الجارف الشديد الذي خرَّب السد وأغرق البساتين، وبدَّلناهم بجنتيهم المثمرتين جنتين ذواتَيْ أكل خمط، وهو الثمر المر الكريه الطعم، وأثْل وهو شجر شبيه بالطَّرْفاء لا ثمر له، وقليل من شجر النَّبْق كثير الشوك. ذلك التبديل من خير إلى شر بسبب كفرهم، وعدم شكرهم نِعَمَ الله، وما نعاقب بهذا العقاب الشديد إلا الجَحود المبالغ في الكفر، يجازى بفعله مثلا بمثل.", "isBasmala": false, "translation_en": "But they turned away, so We unleashed against them the flood of the dam; and We substituted their two gardens with two gardens of bitter fruits, thorny shrubs, and meager harvest.", "translation_id": "Tetapi mereka berpaling, maka Kami datangkan kepada mereka banjir yang besar dan Kami ganti kedua kebun mereka dengan dua kebun yang ditumbuhi (pohon-pohon) yang berbuah pahit, pohon Atsl dan sedikit dari pohon Sidr.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 17, "text": "ذَ ٰلِكَ جَزَیۡنَـٰهُم بِمَا كَفَرُوا۟ۖ وَهَلۡ نُجَـٰزِیۤ إِلَّا ٱلۡكَفُورَ ۝١٧", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "فأعرضوا عن أمر الله وشكره وكذبوا الرسل، فأرسلنا عليهم السيل الجارف الشديد الذي خرَّب السد وأغرق البساتين، وبدَّلناهم بجنتيهم المثمرتين جنتين ذواتَيْ أكل خمط، وهو الثمر المر الكريه الطعم، وأثْل وهو شجر شبيه بالطَّرْفاء لا ثمر له، وقليل من شجر النَّبْق كثير الشوك. ذلك التبديل من خير إلى شر بسبب كفرهم، وعدم شكرهم نِعَمَ الله، وما نعاقب بهذا العقاب الشديد إلا الجَحود المبالغ في الكفر، يجازى بفعله مثلا بمثل.", "isBasmala": false, "translation_en": "We thus penalized them for their ingratitude. Would We penalize any but the ungrateful?", "translation_id": "Demikianlah Kami memberi balasan kepada mereka karena kekafiran mereka. Dan Kami tidak menjatuhkan azab (yang demikian itu), melainkan hanya kepada orang-orang yang sangat kafir.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 18, "text": "وَجَعَلۡنَا بَیۡنَهُمۡ وَبَیۡنَ ٱلۡقُرَى ٱلَّتِی بَـٰرَكۡنَا فِیهَا قُرࣰى ظَـٰهِرَةࣰ وَقَدَّرۡنَا فِیهَا ٱلسَّیۡرَۖ سِیرُوا۟ فِیهَا لَیَالِیَ وَأَیَّامًا ءَامِنِینَ ۝١٨", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "وجعلنا بين أهل \"سبأ\" -وهم \"باليمن\"- والقرى التي باركنا فيها -وهي \"الشام\"- مُدنًا متصلة يُرى بعضها من بعض، وجعلنا السير فيها سيرًا مقدَّرًا من منزل إلى منزل لا مشقة فيه، وقلنا لهم: سيروا في تلك القرى في أيِّ وقت شئتم من ليل أو نهار، آمنين لا تخافون عدوًّا، ولا جوعًا ولا عطشًا.", "isBasmala": false, "translation_en": "Between them and the towns We had blessed, We placed prominent towns, and We made the travel between them easy. \"Travel between them by night and day, in safety.\"", "translation_id": "Dan Kami jadikan antara mereka dan antara negeri-negeri yang Kami limpahkan berkat kepadanya, beberapa negeri yang berdekatan dan Kami tetapkan antara negeri-negeri itu (jarak-jarak) perjalanan. Berjalanlah kamu di kota-kota itu pada malam hari dan siang hari dengan dengan aman.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 19, "text": "فَقَالُوا۟ رَبَّنَا بَـٰعِدۡ بَیۡنَ أَسۡفَارِنَا وَظَلَمُوۤا۟ أَنفُسَهُمۡ فَجَعَلۡنَـٰهُمۡ أَحَادِیثَ وَمَزَّقۡنَـٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ ۝١٩", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "فبطغيانهم ملُّوا الراحة والأمن ورغد العيش، وقالوا: ربنا اجعل قُرانا متباعدة؛ ليبعد سفرنا بينها، فلا نجد قرى عامرة في طريقنا، وظلموا أنفسهم بكفرهم فأهلكناهم، وجعلناهم عبرًا وأحاديث لمن يأتي بعدهم، وفَرَّقناهم كل تفريق وخربت بلادهم، إن فيما حل \"بسبأ\" لَعبرة لكل صبَّار على المكاره والشدائد، شكور لنعم الله تعالى.", "isBasmala": false, "translation_en": "But they said, \"Our Lord, lengthen the distances of our journeys.\" They wronged themselves; so We made them history, and We scattered them in every direction. In this are lessons for every steadfast and appreciative person.", "translation_id": "Maka mereka berkata: \"Ya Tuhan kami jauhkanlah jarak perjalanan kami\", dan mereka menganiaya diri mereka sendiri; maka Kami jadikan mereka buah mulut dan Kami hancurkan mereka sehancur-hancurnya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda kekuasaan Allah bagi setiap orang yang sabar lagi bersyukur.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 20, "text": "وَلَقَدۡ صَدَّقَ عَلَیۡهِمۡ إِبۡلِیسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِیقࣰا مِّنَ ٱلۡمُؤۡمِنِینَ ۝٢٠", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "ولقد ظن إبليس ظنًا غير يقين أنه سيضل بني آدم، وأنهم سيطيعونه في معصية الله، فصدَّق ظنه عليهم، فأطاعوه وعصوا ربهم إلا فريقًا من المؤمنين بالله، فإنهم ثبتوا على طاعة الله.", "isBasmala": false, "translation_en": "Satan was correct in his assessment of them. They followed him, except for a group of believers.", "translation_id": "Dan sesungguhnya iblis telah dapat membuktikan kebenaran sangkaannya terhadap mereka lalu mereka mengikutinya, kecuali sebahagian orang-orang yang beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 21, "text": "وَمَا كَانَ لَهُۥ عَلَیۡهِم مِّن سُلۡطَـٰنٍ إِلَّا لِنَعۡلَمَ مَن یُؤۡمِنُ بِٱلۡـَٔاخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِی شَكࣲّۗ وَرَبُّكَ عَلَىٰ كُلِّ شَیۡءٍ حَفِیظࣱ ۝٢١", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "وما كان لإبليس على هؤلاء الكفار مِن قهر على الكفر، ولكن حكمة الله اقتضت تسويله لبني آدم؛ ليظهر ما علمه سبحانه في الأزل؛ لنميز مَن يصدِّق بالبعث والثواب والعقاب ممن هو في شك من ذلك. وربك على كل شيء حفيظ، يحفظه ويجازي عليه.", "isBasmala": false, "translation_en": "He had no authority over them; except that We willed to distinguish him who believes in the Hereafter, from him who is doubtful about it. Your Lord is Guardian over all things.", "translation_id": "Dan tidak adalah kekuasaan iblis terhadap mereka, melainkan hanyalah agar Kami dapat membedakan siapa yang beriman kepada adanya kehidupan akhirat dari siapa yang ragu-ragu tentang itu. Dan Tuhanmu Maha Memelihara segala sesuatu.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 22, "text": "قُلِ ٱدۡعُوا۟ ٱلَّذِینَ زَعَمۡتُم مِّن دُونِ ٱللَّهِ لَا یَمۡلِكُونَ مِثۡقَالَ ذَرَّةࣲ فِی ٱلسَّمَـٰوَ ٰتِ وَلَا فِی ٱلۡأَرۡضِ وَمَا لَهُمۡ فِیهِمَا مِن شِرۡكࣲ وَمَا لَهُۥ مِنۡهُم مِّن ظَهِیرࣲ ۝٢٢", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "قل -أيها الرسول- للمشركين: ادعوا الذين زعمتموهم شركاء لله فعبدتموهم من دونه من الأصنام والملائكة والبشر، واقصدوهم في حوائجكم، فإنهم لن يجيبوكم، فهم لا يملكون وزن نملة صغيرة في السموات ولا في الأرض، وليس لهم شِرْكة فيهما، وليس لله من هؤلاء المشركين معين على خلق شيء، بل الله -سبحانه وتعالى- هو المتفرد بالإيجاد، فهو الذي يُعْبَدُ وحده، ولا يستحق العبادة أحد سواه.", "isBasmala": false, "translation_en": "Say, \"Call upon those whom you claim besides God. They possess not an atom's weight in the heavens or the earth, and they possess no share of either, and He has no backers from among them.\"", "translation_id": "Katakanlah: \"Serulah mereka yang kamu anggap (sebagai tuhan) selain Allah, mereka tidak memiliki (kekuasaan) seberat zarrahpun di langit dan di bumi, dan mereka tidak mempunyai suatu sahampun dalam (penciptaan) langit dan bumi dan sekali-kali tidak ada di antara mereka yang menjadi pembantu bagi-Nya.", "manzil": 5, "manzil_display": ""}], "431": [{"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 23, "text": "وَلَا تَنفَعُ ٱلشَّفَـٰعَةُ عِندَهُۥۤ إِلَّا لِمَنۡ أَذِنَ لَهُۥۚ حَتَّىٰۤ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُوا۟ مَاذَا قَالَ رَبُّكُمۡۖ قَالُوا۟ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِیُّ ٱلۡكَبِیرُ ۝٢٣", "juz": 22, "hizb": "(*¾ ح 43*)", "tafsir": "ولا تنفع شفاعة الشافع عند الله تعالى إلا لمن أذن له. ومن عظمته وجلاله عز وجل أنه إذا تكلم سبحانه بالوحي فسمع أهل السماوات كلامه أُرعدوا من الهيبة، حتى يلحقهم مثل الغشي، فإذا زال الفزع عن قلوبهم سأل بعضهم بعضًا: ماذا قال ربكم؟ قالت الملائكة: قال الحق، وهو العليُّ بذاته وقهره وعلوِّ قدْره، الكبير على كل شيء.", "isBasmala": false, "translation_en": "Intercession with Him is of no value, except for someone He has permitted. Until, when fear has subsided from their hearts, they will say, \"What did your Lord say?\" They will say, \"The truth, and He is the High, the Great.\"", "translation_id": "Dan tiadalah berguna syafa'at di sisi Allah melainkan bagi orang yang telah diizinkan-Nya memperoleh syafa'at itu, sehingga apabila telah dihilangkan ketakutan dari hati mereka, mereka berkata \"Apakah yang telah difirmankan oleh Tuhan-mu?\" Mereka menjawab: (Perkataan) yang benar\", dan Dialah Yang Maha Tinggi lagi Maha Besar.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 24, "text": "۞ قُلۡ مَن یَرۡزُقُكُم مِّنَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ قُلِ ٱللَّهُۖ وَإِنَّاۤ أَوۡ إِیَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٢٤", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "قل -أيها الرسول- للمشركين: مَن يرزقكم من السماوات بالمطر، ومن الأرض بالنبات والمعادن وغير ذلك؟ فإنهم لا بدَّ أن يُقِرُّوا بأنه الله، وإن لم يُقِرُّوا بذلك فقل لهم: الله هو الرزاق، وإنَّ أحد الفريقين منا ومنكم لعلى هدى متمكن منه، أو في ضلال بيِّن منغمس فيه.", "isBasmala": false, "translation_en": "Say, \"Who provides for you from the heavens and the earth?\" Say, \"God. And Either you, or we, are rightly guided, or in evident error.\"", "translation_id": "Katakanlah: \"Siapakan yang memberi rezeki kepadamu dari langit dan dari bumi?\" Katakanlah: \"Allah\", dan sesungguhnya kami atau kamu (orang-orang musyrik), pasti berada dalam kebenaran atau dalam kesesatan yang nyata.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 25, "text": "قُل لَّا تُسۡـَٔلُونَ عَمَّاۤ أَجۡرَمۡنَا وَلَا نُسۡـَٔلُ عَمَّا تَعۡمَلُونَ ۝٢٥", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "قل: لا تُسألون عن ذنوبنا، ولا نُسأل عن أعمالكم؛ لأننا بريئون منكم ومِن كفركم.", "isBasmala": false, "translation_en": "Say, \"You will not be asked about our misdeeds, nor will we be asked about what you do.\"", "translation_id": "Katakanlah: \"Kamu tidak akan ditanya (bertanggung jawab) tentang dosa yang kami perbuat dan kami tidak akan ditanya (pula) tentang apa yang kamu perbuat\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 26, "text": "قُلۡ یَجۡمَعُ بَیۡنَنَا رَبُّنَا ثُمَّ یَفۡتَحُ بَیۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِیمُ ۝٢٦", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "قل: ربنا يجمع بيننا وبينكم يوم القيامة، ثم يقضي بيننا بالعدل، وهو الفتَّاح الحاكم بين خلقه، العليم بما ينبغي أن يُقْضى به، وبأحوال خلقه، لا تخفى عليه خافية.", "isBasmala": false, "translation_en": "Say, \"Our Lord will bring us together; then He will judge between us equitably. He is the All-Knowing Judge.\"", "translation_id": "Katakanlah: \"Tuhan kita akan mengumpulkan kita semua, kemudian Dia memberi keputusan antara kita dengan benar. Dan Dialah Maha Pemberi keputusan lagi Maha Mengetahui\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 27, "text": "قُلۡ أَرُونِیَ ٱلَّذِینَ أَلۡحَقۡتُم بِهِۦ شُرَكَاۤءَۖ كَلَّاۚ بَلۡ هُوَ ٱللَّهُ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٢٧", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "قل: أروني بالحجة والدليل الذين ألحقتموهم بالله وجعلتموهم شركاء له في العبادة، هل خلقوا شيئًا؟ ليس الأمر كما وصفوا، بل هو المعبود بحق الذي لا شريك له، العزيز في انتقامه ممن أشرك به، الحكيم في أقواله وأفعاله وتدبير أمور خلقه.", "isBasmala": false, "translation_en": "Say, \"Show me those you have attached to Him as associates. No indeed! But He is God, the Powerful, the Wise.\"", "translation_id": "Katakanlah: \"Perlihatkanlah kepadaku sembah-sembahan yang kamu hubungkan dengan Dia sebagai sekutu-sekutu-Nya, sekali-kali tidak mungkin! Sebenarnya Dialah Allah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 28, "text": "وَمَاۤ أَرۡسَلۡنَـٰكَ إِلَّا كَاۤفَّةࣰ لِّلنَّاسِ بَشِیرࣰا وَنَذِیرࣰا وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٢٨", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "وما أرسلناك -أيها الرسول- إلا للناس أجمعين مبشرًا بثواب الله، ومنذرًا عقابه، ولكن أكثر الناس لا يعلمون الحق، فهم معرضون عنه.", "isBasmala": false, "translation_en": "We sent you only universally to all people, a herald and warner, but most people do not know.", "translation_id": "Dan Kami tidak mengutus kamu, melainkan kepada umat manusia seluruhnya sebagai pembawa berita gembira dan sebagai pemberi peringatan, tetapi kebanyakan manusia tiada mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 29, "text": "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ ۝٢٩", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "ويقول هؤلاء المشركون مستهزئين: متى هذا الوعد الذي تَعِدوننا أن يجمعنا الله فيه، ثم يقضي بيننا، إن كنتم صادقين فيما تعدوننا به؟", "isBasmala": false, "translation_en": "And they say, \"When is this promise due, if you are truthful?\"", "translation_id": "Dan mereka berkata: \"Kapankah (datangnya) janji ini, jika kamu adalah orang-orang yang benar?\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 30, "text": "قُل لَّكُم مِّیعَادُ یَوۡمࣲ لَّا تَسۡتَـٔۡخِرُونَ عَنۡهُ سَاعَةࣰ وَلَا تَسۡتَقۡدِمُونَ ۝٣٠", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "قل لهم -أيها الرسول-: لكم ميعاد هو آتيكم لا محالة، وهو ميعاد يوم القيامة، لا تستأخرون عنه ساعة للتوبة، ولا تستقدمون ساعةً قبله للعذاب. فاحذروا ذلك اليوم، وأَعِدُّوا له عدته.", "isBasmala": false, "translation_en": "Say, \"You are promised a Day, which you cannot postpone by one hour, nor bring forward.\"", "translation_id": "Katakanlah: \"Bagimu ada hari yang telah dijanjikan (hari kiamat) yang tiada dapat kamu minta mundur daripadanya barang sesaatpun dan tidak (pula) kamu dapat meminta supaya diajukan\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 31, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَن نُّؤۡمِنَ بِهَـٰذَا ٱلۡقُرۡءَانِ وَلَا بِٱلَّذِی بَیۡنَ یَدَیۡهِۗ وَلَوۡ تَرَىٰۤ إِذِ ٱلظَّـٰلِمُونَ مَوۡقُوفُونَ عِندَ رَبِّهِمۡ یَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ یَقُولُ ٱلَّذِینَ ٱسۡتُضۡعِفُوا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوا۟ لَوۡلَاۤ أَنتُمۡ لَكُنَّا مُؤۡمِنِینَ ۝٣١", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "وقال الذين كفروا: لن نصدِّق بهذا القرآن ولا بالذي تَقَدَّمَه من التوراة والإنجيل والزبور، فقد كذَّبوا بجميع كتب الله. ولو ترى -أيها الرسول- إذ الظالمون محبوسون عند ربهم للحساب، يتراجعون الكلام فيما بينهم، كل يُلْقي بالعتاب على الآخر، لرأيت شيئًا فظيعا، يقول المستضعفون للذين استكبروا -وهم القادة والرؤساء الضالون المضلون-: لولا أنتم أضللتمونا عن الهدى لكنا مؤمنين بالله ورسوله.", "isBasmala": false, "translation_en": "Those who disbelieve say, \"We will never believe in this Quran, nor in what came before it.\" If you could only see the wrongdoers, captive before their Lord, throwing back allegations at one another. Those who were oppressed will say to those who were arrogant, \"Were it not for you, we would have been believers.\"", "translation_id": "Dan orang-orang kafir berkata: \"Kami sekali-kali tidak akan beriman kepada Al Quran ini dan tidak (pula) kepada kitab yang sebelumnya\". Dan (alangkah hebatnya) kalau kamu lihat ketika orang-orang yang zalim itu dihadapkan kepada Tuhannya, sebahagian dari mereka menghadap kan perkataan kepada sebagian yang lain; orang-orang yang dianggap lemah berkata kepada orang-orang yang menyombongkan diri: \"Kalau tidaklah karena kamu tentulah kami menjadi orang-orang yang beriman\".", "manzil": 5, "manzil_display": ""}], "432": [{"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 32, "text": "قَالَ ٱلَّذِینَ ٱسۡتَكۡبَرُوا۟ لِلَّذِینَ ٱسۡتُضۡعِفُوۤا۟ أَنَحۡنُ صَدَدۡنَـٰكُمۡ عَنِ ٱلۡهُدَىٰ بَعۡدَ إِذۡ جَاۤءَكُمۖ بَلۡ كُنتُم مُّجۡرِمِینَ ۝٣٢", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "قال الرؤساء للذين استُضعِفوا: أنحن منعناكم من الهدى بعد إذ جاءكم؟ بل كنتم مجرمين إذ دخلتم في الكفر بإرادتكم مختارين.", "isBasmala": false, "translation_en": "Those who were arrogant will say to those who were oppressed, \"Was it us who turned you away from guidance when it came to you? No indeed, you yourselves were sinful.\"", "translation_id": "Orang-orang yang menyombongkan diri berkata kepada orang-orang yang dianggap lemah: \"Kamikah yang telah menghalangi kamu dari petunjuk sesudah petunjuk itu datang kepadamu? (Tidak), sebenarnya kamu sendirilah orang-orang yang berdosa\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 33, "text": "وَقَالَ ٱلَّذِینَ ٱسۡتُضۡعِفُوا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوا۟ بَلۡ مَكۡرُ ٱلَّیۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَاۤ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥۤ أَندَادࣰاۚ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلۡعَذَابَۚ وَجَعَلۡنَا ٱلۡأَغۡلَـٰلَ فِیۤ أَعۡنَاقِ ٱلَّذِینَ كَفَرُوا۟ۖ هَلۡ یُجۡزَوۡنَ إِلَّا مَا كَانُوا۟ یَعۡمَلُونَ ۝٣٣", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "وقال المستضعفون لرؤسائهم في الضلال: بل تدبيركم الشر لنا في الليل والنهار هو الذي أوقعنا في التهلكة، فكنتم تطلبون منا أن نكفر بالله، ونجعل له شركاء في العبادة، وأسرَّ كُلٌّ من الفريقين الحسرة حين رأوا العذاب الذي أُعدَّ لهم، وجعلنا الأغلال في أعناق الذين كفروا، لا يعاقَبون بهذا العقاب إلا بسبب كفرهم بالله وعملهم السيئات في الدنيا. وفي الآية تحذير شديد من متابعة دعاة الضلال وأئمة الطغيان.", "isBasmala": false, "translation_en": "And those who were oppressed will say to those who were arrogant, \"It was your scheming by night and day; as you instructed us to reject God, and to set up rivals to Him.\" They will hide their remorse when they see the retribution. We will put yokes around the necks of those who disbelieved. Will they be repaid for anything other than what they used to do?", "translation_id": "Dan orang-orang yang dianggap lemah berkata kepada orang-orang yang menyombongkan diri: \"(Tidak) sebenarnya tipu daya(mu) di waktu malam dan siang (yang menghalangi kami), ketika kamu menyeru kami supaya kami kafir kepada Allah dan menjadikan sekutu-sekutu bagi-Nya\". Kedua belah pihak menyatakan penyesalan tatkala mereka melihat azab. Dan kami pasang belenggu di leher orang-orang yang kafir. Mereka tidak dibalas melainkan dengan apa yang telah mereka kerjakan.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 34, "text": "وَمَاۤ أَرۡسَلۡنَا فِی قَرۡیَةࣲ مِّن نَّذِیرٍ إِلَّا قَالَ مُتۡرَفُوهَاۤ إِنَّا بِمَاۤ أُرۡسِلۡتُم بِهِۦ كَـٰفِرُونَ ۝٣٤", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "وما أرسلنا في قرية من رسول يدعو الى توحيد الله وإفراده بالعبادة، إلا قال المنغمسون في اللذات والشهوات من أهلها: إنَّا بالذي جئتم به -أيها الرسل- جاحدون.", "isBasmala": false, "translation_en": "We sent no warner to any town, without its affluent saying, \"We reject what you are sent with.\"", "translation_id": "Dan Kami tidak mengutus kepada suatu negeri seorang pemberi peringatanpun, melainkan orang-orang yang hidup mewah di negeri itu berkata: \"Sesungguhnya kami mengingkari apa yang kamu diutus untuk menyampaikannya\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 35, "text": "وَقَالُوا۟ نَحۡنُ أَكۡثَرُ أَمۡوَ ٰلࣰا وَأَوۡلَـٰدࣰا وَمَا نَحۡنُ بِمُعَذَّبِینَ ۝٣٥", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "وقالوا: نحن أكثر منكم أموالا وأولادًا، والله لم يعطنا هذه النعم إلا لرضاه عنا، وما نحن بمعذَّبين في الدنيا ولا في الآخرة.", "isBasmala": false, "translation_en": "And they say, \"We have more wealth and more children, and we will not be punished.\"", "translation_id": "Dan mereka berkata: \"Kami lebih banyak mempunyai harta dan anak-anak (daripada kamu) dan kami sekali-kali tidak akan diazab.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 36, "text": "قُلۡ إِنَّ رَبِّی یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٣٦", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "قل لهم -أيها الرسول-: إن ربي يوسِّع الرزق في الدنيا لمن يشاء مِن عباده، ويضيِّق على مَن يشاء، لا لمحبة ولا لبغض، ولكن يفعل ذلك اختبارًا، ولكن أكثر الناس لا يعلمون أن ذلك اختبار لعباده؛ لأنهم لا يتأملون.", "isBasmala": false, "translation_en": "Say, \"My Lord spreads out His bounty to whomever He wills, or restricts it; but most people do not know.\"", "translation_id": "Katakanlah: \"Sesungguhnya Tuhanku melapangkan rezeki bagi siapa yang dikehendaki-Nya dan menyempitkan (bagi siapa yang dikehendaki-Nya). akan tetapi kebanyakan manusia tidak mengetahui\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 37, "text": "وَمَاۤ أَمۡوَ ٰلُكُمۡ وَلَاۤ أَوۡلَـٰدُكُم بِٱلَّتِی تُقَرِّبُكُمۡ عِندَنَا زُلۡفَىٰۤ إِلَّا مَنۡ ءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَأُو۟لَـٰۤىِٕكَ لَهُمۡ جَزَاۤءُ ٱلضِّعۡفِ بِمَا عَمِلُوا۟ وَهُمۡ فِی ٱلۡغُرُفَـٰتِ ءَامِنُونَ ۝٣٧", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "وليست أموالكم ولا أولادكم بالتي تقربكم عندنا قربى، وترفع درجاتكم، لكن مَن آمن بالله وعمل صالحًا فهؤلاء لهم ثواب الضعف من الحسنات، فالحسنة بعشر أمثالها إلى ما يشاء الله من الزيادة، وهم في أعالي الجنة آمنون من العذاب والموت والأحزان.", "isBasmala": false, "translation_en": "It is neither your wealth nor your children that bring you closer to Us, but it is he who believes and does good deeds. These will have a double reward for what they did; and they will reside in the Chambers, in peace and security.", "translation_id": "Dan sekali-kali bukanlah harta dan bukan (pula) anak-anak kamu yang mendekatkan kamu kepada Kami sedikitpun; tetapi orang-orang yang beriman dan mengerjakan amal-amal (saleh, mereka itulah yang memperoleh balasan yang berlipat ganda disebabkan apa yang telah mereka kerjakan; dan mereka aman sentosa di tempat-tempat yang tinggi (dalam surga).", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 38, "text": "وَٱلَّذِینَ یَسۡعَوۡنَ فِیۤ ءَایَـٰتِنَا مُعَـٰجِزِینَ أُو۟لَـٰۤىِٕكَ فِی ٱلۡعَذَابِ مُحۡضَرُونَ ۝٣٨", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "والذين يسعون في إبطال حججنا، ويصدون عن سبيل الله مشاقين مغالبين، هؤلاء في عذاب جهنم يوم القيامة، تحضرهم الزبانية، فلا يخرجون منها.", "isBasmala": false, "translation_en": "But those who work against Our revelations, seeking to undermine them-those will be summoned to the punishment.", "translation_id": "Dan orang-orang yang berusaha (menentang) ayat-ayat Kami dengan anggapan untuk dapat melemahkan (menggagalkan azab Kami), mereka itu dimasukkan ke dalam azab.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 39, "text": "قُلۡ إِنَّ رَبِّی یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ مِنۡ عِبَادِهِۦ وَیَقۡدِرُ لَهُۥۚ وَمَاۤ أَنفَقۡتُم مِّن شَیۡءࣲ فَهُوَ یُخۡلِفُهُۥۖ وَهُوَ خَیۡرُ ٱلرَّ ٰزِقِینَ ۝٣٩", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "قل -أيها الرسول- لهؤلاء المغترين بالأموال والأولاد: إن ربي يوسِّع الرزق على مَن يشاء من عباده، ويضيِّقه على مَن يشاء؛ لحكمة يعلمها، ومهما أَعْطَيتم من شيء فيما أمركم به فهو يعوضه لكم في الدنيا بالبدل، وفي الآخرة بالثواب، وهو -سبحانه- خير الرازقين، فاطلبوا الرزق منه وحده، واسعَوا في الأسباب التي أمركم بها.", "isBasmala": false, "translation_en": "Say, \"My Lord extends the provision to whomever He wills of His servants, or withholds it. Anything you spend, He will replace it. He is the Best of providers.\"", "translation_id": "Katakanlah: \"Sesungguhnya Tuhanku melapangkan rezeki bagi siapa yang dikehendaki-Nya di antara hamba-hamba-Nya dan menyempitkan bagi (siapa yang dikehendaki-Nya)\". Dan barang apa saja yang kamu nafkahkan, maka Allah akan menggantinya dan Dialah Pemberi rezeki yang sebaik-baiknya.", "manzil": 5, "manzil_display": ""}], "433": [{"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 40, "text": "وَیَوۡمَ یَحۡشُرُهُمۡ جَمِیعࣰا ثُمَّ یَقُولُ لِلۡمَلَـٰۤىِٕكَةِ أَهَـٰۤؤُلَاۤءِ إِیَّاكُمۡ كَانُوا۟ یَعۡبُدُونَ ۝٤٠", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "واذكر -أيها الرسول- يوم يحشر الله المشركين والمعبودين من دونه من الملائكة، ثم يقول للملائكة على وجه التوبيخ لمن عبدهم: أهؤلاء إياكم كانوا يعبدون مِن دوننا؟", "isBasmala": false, "translation_en": "On the Day when He gathers them all together, then say to the angels, \"Was it you these used to worship?\"", "translation_id": "Dan (ingatlah) hari (yang di waktu itu) Allah mengumpulkan mereka semuanya kemudian Allah berfirman kepada malaikat: \"Apakah mereka ini dahulu menyembah kamu?\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 41, "text": "قَالُوا۟ سُبۡحَـٰنَكَ أَنتَ وَلِیُّنَا مِن دُونِهِمۖ بَلۡ كَانُوا۟ یَعۡبُدُونَ ٱلۡجِنَّۖ أَكۡثَرُهُم بِهِم مُّؤۡمِنُونَ ۝٤١", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "قالت الملائكة: ننزهك يا ألله عن أن يكون لك شريك في العبادة، أنت وليُّنا الذي نطيعه ونعبده وحده، بل كان هؤلاء يعبدون الشياطين، أكثرهم بهم مصدقون ومطيعون.", "isBasmala": false, "translation_en": "They will say, \"Be You glorified; You are our Master, not them. In fact, they used to worship the jinn, and most of them had faith in them.\"", "translation_id": "Malaikat-malaikat itu menjawab: \"Maha Suci Engkau. Engkaulah pelindung kami, bukan mereka; bahkan mereka telah menyembah jin; kebanyakan mereka beriman kepada jin itu\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 42, "text": "فَٱلۡیَوۡمَ لَا یَمۡلِكُ بَعۡضُكُمۡ لِبَعۡضࣲ نَّفۡعࣰا وَلَا ضَرࣰّا وَنَقُولُ لِلَّذِینَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِی كُنتُم بِهَا تُكَذِّبُونَ ۝٤٢", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "ففي يوم الحشر لا يملك المعبودون للعابدين نفعًا ولا ضرًّا، ونقول للذين ظلموا أنفسهم بالشرك والمعاصي: ذوقوا عذاب النار التي كنتم بها تكذبون.", "isBasmala": false, "translation_en": "\"Today, none of you has the power to profit or harm the other.\" And We will say to those who did wrong, \"Taste the agony of the Fire which you used to deny.\"", "translation_id": "Maka pada hari ini sebahagian kamu tidak berkuasa (untuk memberikan) kemanfaatan dan tidak pula kemudharatan kepada sebahagian yang lain. Dan Kami katakan kepada orang-orang yang zalim: \"Rasakanlah olehmu azab neraka yang dahulunya kamu dustakan itu\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 43, "text": "وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ قَالُوا۟ مَا هَـٰذَاۤ إِلَّا رَجُلࣱ یُرِیدُ أَن یَصُدَّكُمۡ عَمَّا كَانَ یَعۡبُدُ ءَابَاۤؤُكُمۡ وَقَالُوا۟ مَا هَـٰذَاۤ إِلَّاۤ إِفۡكࣱ مُّفۡتَرࣰىۚ وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِلۡحَقِّ لَمَّا جَاۤءَهُمۡ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینࣱ ۝٤٣", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "وإذا تتلى على كفار \"مكة\" آيات الله واضحات قالوا: ما محمد إلا رجل يرغب أن يمنعكم عن عبادة الآلهة التي كان يعبدها آباؤكم، وقالوا: ما هذا القرآن الذي تتلوه علينا -يا محمد- إلا كذب مختلق، جئتَ به من عند نفسك، وليس مِن عند الله، وقال الكفار عن القرآن لما جاءهم: ما هذا إلا سحر واضح.", "isBasmala": false, "translation_en": "And when Our enlightening Verses are recited to them, they say, \"This is nothing but a man who wants to divert you from what your ancestors used to worship.\" And they say, \"This is nothing but a fabricated lie.\" And when the Truth comes to them, the blasphemers say of the Truth, \"This is nothing but plain magic.\"", "translation_id": "Dan apabila dibacakan kepada mereka ayat-ayat Kami yang terang, mereka berkata: \"Orang ini tiada lain hanyalah seorang laki-laki yang ingin menghalangi kamu dari apa yang disembah oleh bapak-bapakmu\", dan mereka berkata: \"(Al Quran) ini tidak lain hanyalah kebohongan yang diada-adakan saja\". Dan orang-orang kafir berkata terhadap kebenaran tatkala kebenaran itu datang kepada mereka: \"Ini tidak lain hanyalah sihir yang nyata\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 44, "text": "وَمَاۤ ءَاتَیۡنَـٰهُم مِّن كُتُبࣲ یَدۡرُسُونَهَاۖ وَمَاۤ أَرۡسَلۡنَاۤ إِلَیۡهِمۡ قَبۡلَكَ مِن نَّذِیرࣲ ۝٤٤", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "وما أنزلنا على الكفار مِن كُتُب يقرؤونها قبل القرآن فتدلهم على ما يزعمون من أن ما جاءهم به محمد سحر، وما أرسلنا إليهم قبلك -أيها الرسول- من رسول ينذرهم بأسنا.", "isBasmala": false, "translation_en": "But We gave them no book to study, and We did not send them any warner before you.", "translation_id": "Dan Kami tidak pernah memberikan kepada mereka kitab-kitab yang mereka baca dan sekali-kali tidak pernah (pula) mengutus kepada mereka sebelum kamu seorang pemberi peringatanpun.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 45, "text": "وَكَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ وَمَا بَلَغُوا۟ مِعۡشَارَ مَاۤ ءَاتَیۡنَـٰهُمۡ فَكَذَّبُوا۟ رُسُلِیۖ فَكَیۡفَ كَانَ نَكِیرِ ۝٤٥", "juz": 22, "hizb": "(* ح 44*)", "tafsir": "وكذَّب الذين من قبلهم كعاد وثمود رسلنا، وما بلغ أهل \"مكة\" عُشرَ ما آتينا الأمم السابقة من القوة، وكثرة المال، وطول العمر وغير ذلك من النعم، فكذبوا رسلي فيما جاؤوهم به فأهلكناهم، فانظر -أيها الرسول- كيف كان إنكاري عليهم وعقوبتي إياهم؟", "isBasmala": false, "translation_en": "Those before them also denied the Truth, yet they have not attained one-tenth of what We had given them. They rejected My messengers, so how was My disapproval?", "translation_id": "Dan orang-orang yang sebelum mereka telah mendustakan sedang orang-orang kafir Mekah itu belum sampai menerima sepersepuluh dari apa yang telah Kami berikan kepada orang-orang dahulu itu lalu mereka mendustakan rasul-rasul-Ku. Maka alangkah hebatnya akibat kemurkaan-Ku.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 46, "text": "۞ قُلۡ إِنَّمَاۤ أَعِظُكُم بِوَ ٰحِدَةٍۖ أَن تَقُومُوا۟ لِلَّهِ مَثۡنَىٰ وَفُرَ ٰدَىٰ ثُمَّ تَتَفَكَّرُوا۟ۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِیرࣱ لَّكُم بَیۡنَ یَدَیۡ عَذَابࣲ شَدِیدࣲ ۝٤٦", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "قل -أيها الرسول- لهؤلاء المكذبين المعاندين: إنما أنصح لكم بخصلة واحدة أن تنهضوا في طاعة الله اثنين اثنين وواحدًا واحدًا، ثم تتفكروا في حال صاحبكم رسول الله صلى الله عليه وسلم وفيما نسب إليه، فما به من جنون، وما هو إلا مخوِّف لكم، ونذير من عذاب جهنم قبل أن تقاسوا حرها.", "isBasmala": false, "translation_en": "Say, \"I offer you a single advice: devote yourselves to God, in pairs, or individually; and reflect. There is no madness in your friend. He is just a warner to you, before the advent of a severe punishment.\"", "translation_id": "Katakanlah: \"Sesungguhnya aku hendak memperingatkan kepadamu suatu hal saja, yaitu supaya kamu menghadap Allah (dengan ikhlas) berdua-dua atau sendiri-sendiri; kemudian kamu fikirkan (tentang Muhammad) tidak ada penyakit gila sedikitpun pada kawanmu itu. Dia tidak lain hanyalah pemberi peringatan bagi kamu sebelum (menghadapi) azab yang keras.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 47, "text": "قُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرࣲ فَهُوَ لَكُمۡۖ إِنۡ أَجۡرِیَ إِلَّا عَلَى ٱللَّهِۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدࣱ ۝٤٧", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "قل -أيها الرسول- للكفار: ما سألتكم على الخير الذي جئتكم به من أجر فهو لكم، ما أجري الذي أنتظره إلا على الله المطَّلِع على أعمالي وأعمالكم، لا يخفى عليه شيء فهو يجازي الجميع، كلٌّ بما يستحقه.", "isBasmala": false, "translation_en": "Say, \"Whatever compensation I have asked of you, is yours. My compensation comes only from God, and He is Witness over all things.\"", "translation_id": "Katakanlah: \"Upah apapun yang aku minta kepadamu, maka itu untuk kamu. Upahku hanyalah dari Allah, dan Dia Maha Mengetahui segala sesuatu\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 48, "text": "قُلۡ إِنَّ رَبِّی یَقۡذِفُ بِٱلۡحَقِّ عَلَّـٰمُ ٱلۡغُیُوبِ ۝٤٨", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "قل -أيها الرسول- لمن أنكر التوحيد ورسالة الإسلام: إن ربي يقذف الباطل بحجج من الحق، فيفضحه ويهلكه، والله علام الغيوب، لا يخفى عليه شيء في الأرض ولا في السماء.", "isBasmala": false, "translation_en": "Say, \"My Lord projects the truth. He is the Knower of the Unseen.\"", "translation_id": "Katakanlah: \"Sesungguhnya Tuhanku mewahyukan kebenaran. Dia Maha Mengetahui segala yang ghaib\".", "manzil": 5, "manzil_display": ""}], "434": [{"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 49, "text": "قُلۡ جَاۤءَ ٱلۡحَقُّ وَمَا یُبۡدِئُ ٱلۡبَـٰطِلُ وَمَا یُعِیدُ ۝٤٩", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "قل -أيها الرسول-: جاء الحق والشرع العظيم من الله، وذهب الباطل واضمحلَّ سلطانه، فلم يبق للباطل شيء يبدؤه ويعيده.", "isBasmala": false, "translation_en": "Say, \"The Truth has come; while falsehood can neither originate, nor regenerate.\"", "translation_id": "Katakanlah: \"Kebenaran telah datang dan yang batil itu tidak akan memulai dan tidak (pula) akan mengulangi\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 50, "text": "قُلۡ إِن ضَلَلۡتُ فَإِنَّمَاۤ أَضِلُّ عَلَىٰ نَفۡسِیۖ وَإِنِ ٱهۡتَدَیۡتُ فَبِمَا یُوحِیۤ إِلَیَّ رَبِّیۤۚ إِنَّهُۥ سَمِیعࣱ قَرِیبࣱ ۝٥٠", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "قل: إن مِلْت عن الحق فإثم ضلالي على نفسي، وإن استقمت عليه فبوحي الله الذي يوحيه إليَّ، إن ربي سميع لما أقول لكم، قريب ممن دعاه وسأله.", "isBasmala": false, "translation_en": "Say, \"If I err, I err only to my own loss; but if I am guided, it is by what my Lord inspires me. He is Hearing and Near.\"", "translation_id": "Katakanlah: \"Jika aku sesat maka sesungguhnya aku sesat atas kemudharatan diriku sendiri; dan jika aku mendapat petunjuk maka itu adalah disebabkan apa yang diwahyukan Tuhanku kepadaku. Sesungguhnya Dia Maha Mendengar lagi Maha Dekat\".", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 51, "text": "وَلَوۡ تَرَىٰۤ إِذۡ فَزِعُوا۟ فَلَا فَوۡتَ وَأُخِذُوا۟ مِن مَّكَانࣲ قَرِیبࣲ ۝٥١", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "ولو ترى -أيها الرسول- إذ فَزِعَ الكفار حين معاينتهم عذاب الله، لرأيت أمرًا عظيمًا، فلا نجاة لهم ولا مهرب، وأُخذوا إلى النار من موضع قريب التناول.", "isBasmala": false, "translation_en": "If you could only see when they are terrified, and there is no escape, and they are seized from a nearby place.", "translation_id": "Dan (alangkah hebatnya) jikalau kamu melihat ketika mereka (orang-orang kafir) terperanjat ketakutan (pada hari kiamat); maka mereka tidak dapat melepaskan diri dan mereka ditangkap dari tempat yang dekat (untuk dibawa ke neraka),", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 52, "text": "وَقَالُوۤا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانِۭ بَعِیدࣲ ۝٥٢", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "وقال الكفار -عندما رأوا العذاب في الآخرة-: آمنا بالله وكتبه ورسله، وكيف لهم تناول الإيمان في الآخرة ووصولهم له من مكان بعيد؟ قد حيل بينهم وبينه، فمكانه الدنيا، وقد كفروا فيها.", "isBasmala": false, "translation_en": "And they say, \"We have believed in it.\" But how can they attain it from a distant place?", "translation_id": "dan (di waktu itu) mereka berkata: \"Kami beriman kepada Allah\", bagaimanakah mereka dapat mencapai (keimanan) dari tempat yang jauh itu.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 53, "text": "وَقَدۡ كَفَرُوا۟ بِهِۦ مِن قَبۡلُۖ وَیَقۡذِفُونَ بِٱلۡغَیۡبِ مِن مَّكَانِۭ بَعِیدࣲ ۝٥٣", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "وقد كفروا بالحق في الدنيا، وكذبوا الرسل، ويرمون بالظن من جهة بعيدة عن إصابة الحق، ليس لهم فيها مستند لظنهم الباطل، فلا سبيل لإصابتهم الحق، كما لا سبيل للرامي إلى إصابة الغرض من مكان بعيد.", "isBasmala": false, "translation_en": "They have rejected it in the past, and made allegations from a far-off place.", "translation_id": "Dan sesungguhnya mereka telah mengingkari Allah sebelum itu; dan mereka menduga-duga tentang yang ghaib dari tempat yang jauh.", "manzil": 5, "manzil_display": ""}, {"sura": 34, "sura_name": "سبأ", "revelation": "Makkiyah", "aya": 54, "text": "وَحِیلَ بَیۡنَهُمۡ وَبَیۡنَ مَا یَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡیَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُوا۟ فِی شَكࣲّ مُّرِیبِۭ ۝٥٤", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "وحيل بين الكفار وما يشتهون من التوبة والعودة إلى الدنيا ليؤمنوا، كما فعل الله بأمثالهم من كفرة الأمم السابقة، إنهم كانوا في الدنيا في شَكٍّ من أمر الرسل والبعث والحساب، مُحْدِث للريبة والقلق، فلذلك لم يؤمنوا.", "isBasmala": false, "translation_en": "A barrier will be placed between them and what they desire, as was done formerly with their counterparts. They were in disturbing doubt.", "translation_id": "Dan dihalangi antara mereka dengan apa yang mereka ingini sebagaimana yang dilakukan terhadap orang-orang yang serupa dengan mereka pada masa dahulu. Sesungguhnya mereka dahulu (di dunia) dalam keraguan yang mendalam.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 22, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 1, "text": "ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَـٰۤىِٕكَةِ رُسُلًا أُو۟لِیۤ أَجۡنِحَةࣲ مَّثۡنَىٰ وَثُلَـٰثَ وَرُبَـٰعَۚ یَزِیدُ فِی ٱلۡخَلۡقِ مَا یَشَاۤءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝١", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "الثناء على الله بصفاته التي كلُّها أوصاف كمال، وبنعمه الظاهرة والباطنة، الدينية والدنيوية، خالق السماوات والأرض ومبدعهما، جاعل الملائكة رسلا إلى مَن يشاء من عباده، وفيما شاء من أمره ونهيه، ومِن عظيم قدرة الله أن جعل الملائكة أصحاب أجنحة مثنى وثلاث ورباع تطير بها؛ لتبليغ ما أمر الله به، يزيد الله في خلقه ما يشاء. إن الله على كل شيء قدير، لا يستعصي عليه شيء.", "isBasmala": false, "translation_en": "Praise be to God, Originator of the heavens and the earth, Maker of the angels messengers with wings-double, triple, and quadruple. He adds to creation as He wills. God is Able to do all things.", "translation_id": "Segala puji bagi Allah Pencipta langit dan bumi, Yang menjadikan malaikat sebagai utusan-utusan (untuk mengurus berbagai macam urusan) yang mempunyai sayap, masing-masing (ada yang) dua, tiga dan empat. Allah menambahkan pada ciptaan-Nya apa yang dikehendaki-Nya. Sesungguhnya Allah Maha Kuasa atas segala sesuatu.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 2, "text": "مَّا یَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةࣲ فَلَا مُمۡسِكَ لَهَاۖ وَمَا یُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٢", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "ما يفتح الله للناس من رزق ومطر وصحة وعلم وغير ذلك من النعم، فلا أحد يقدر أن يمسك هذه الرحمة، وما يمسك منها فلا أحد يستطيع أن يرسلها بعده سبحانه وتعالى. وهو العزيز القاهر لكل شيء، الحكيم الذي يرسل الرحمة ويمسكها وَفْق حكمته.", "isBasmala": false, "translation_en": "Whatever mercy God unfolds for the people, none can withhold it. And if He withholds it, none can release it thereafter. He is the Exalted in Power, Full of Wisdom.", "translation_id": "Apa saja yang Allah anugerahkan kepada manusia berupa rahmat, maka tidak ada seorangpun yang dapat menahannya; dan apa saja yang ditahan oleh Allah maka tidak seorangpun yang sanggup melepaskannya sesudah itu. Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 3, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ ٱذۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ عَلَیۡكُمۡۚ هَلۡ مِنۡ خَـٰلِقٍ غَیۡرُ ٱللَّهِ یَرۡزُقُكُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۚ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ ۝٣", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "يا أيها الناس اذكروا نعمة الله عليكم بقلوبكم وألسنتكم وجوارحكم، فلا خالق لكم غير الله يرزقكم من السماء بالمطر، ومن الأرض بالماء والمعادن وغير ذلك. لا إله إلا هو وحده لا شريك له، فكيف تُصْرَفون عن توحيده وعبادته؟", "isBasmala": false, "translation_en": "O people! Remember God's blessings upon you. Is there a creator other than God who provides for you from the heaven and the earth? There is no god but He. So how are you misled?", "translation_id": "Hai manusia, ingatlah akan nikmat Allah kepadamu. Adakah pencipta selain Allah yang dapat memberikan rezeki kepada kamu dari langit dan bumi? Tidak ada Tuhan selain Dia; maka mengapakah kamu berpaling (dari ketauhidan)?", "manzil": 5, "manzil_display": ""}], "435": [{"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 4, "text": "وَإِن یُكَذِّبُوكَ فَقَدۡ كُذِّبَتۡ رُسُلࣱ مِّن قَبۡلِكَۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ۝٤", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "وإن يكذبك قومك -أيها الرسول- فقد كُذِّب رسل مِن قبلك، وإلى الله تصير الأمور في الآخرة، فيجازي كلا بما يستحق. وفي هذا تسلية للرسول صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "If they reject you, messengers before you were also rejected. To God all matters are returned.", "translation_id": "Dan jika mereka mendustakan kamu (sesudah kamu beri peringatan) maka sungguh telah didustakan pula rasul-rasul sebelum kamu. Dan hanya kepada Allahlah dikembalikan segala urusan.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 5, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَلَا یَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ ۝٥", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "يا أيها الناس إن وعد الله بالبعث والثواب والعقاب حق ثابت، فلا تخدعنَّكم الحياة الدنيا بشهواتها ومطالبها، ولا يخدعنَّكم بالله الشيطان. إن الشيطان لبني آدم عدو، فاتخذوه عدوًّا ولا تطيعوه، إنما يدعو أتباعه إلى الضلال؛ ليكونوا من أصحاب النار الموقدة.", "isBasmala": false, "translation_en": "O people! The promise of God is true; so let not the lowly life seduce you, and let not the Tempter tempt you away from God.", "translation_id": "Hai manusia, sesungguhnya janji Allah adalah benar, maka sekali-kali janganlah kehidupan dunia memperdayakan kamu dan sekali-kali janganlah syaitan yang pandai menipu, memperdayakan kamu tentang Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 6, "text": "إِنَّ ٱلشَّیۡطَـٰنَ لَكُمۡ عَدُوࣱّ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا یَدۡعُوا۟ حِزۡبَهُۥ لِیَكُونُوا۟ مِنۡ أَصۡحَـٰبِ ٱلسَّعِیرِ ۝٦", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "يا أيها الناس إن وعد الله بالبعث والثواب والعقاب حق ثابت، فلا تخدعنَّكم الحياة الدنيا بشهواتها ومطالبها، ولا يخدعنَّكم بالله الشيطان. إن الشيطان لبني آدم عدو، فاتخذوه عدوًّا ولا تطيعوه، إنما يدعو أتباعه إلى الضلال؛ ليكونوا من أصحاب النار الموقدة.", "isBasmala": false, "translation_en": "Satan is an enemy to you, so treat him as an enemy. He only invites his gang to be among the inmates of the Inferno.", "translation_id": "Sesungguhnya syaitan itu adalah musuh bagimu, maka anggaplah ia musuh(mu), karena sesungguhnya syaitan-syaitan itu hanya mengajak golongannya supaya mereka menjadi penghuni neraka yang menyala-nyala", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 7, "text": "ٱلَّذِینَ كَفَرُوا۟ لَهُمۡ عَذَابࣱ شَدِیدࣱۖ وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرٌ ۝٧", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "الذين جحدوا أن الله هو وحده الإله الحق وجحدوا ما جاءت به رسله لهم عذاب شديد في الآخرة، والذين صدَّقوا الله ورسوله وعملوا الصالحات لهم عفو من ربهم وتجاوز عن ذنوبهم بعد سترها عليهم، ولهم أجر كبير، وهو الجنة.", "isBasmala": false, "translation_en": "Those who disbelieve will suffer a harsh punishment, but those who believe and do righteous deeds will have forgiveness and a great reward.", "translation_id": "Orang-orang yang kafir bagi mereka azab yang keras. Dan orang-orang yang beriman dan mengerjakan amal saleh bagi mereka ampunan dan pahala yang besar.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 8, "text": "أَفَمَن زُیِّنَ لَهُۥ سُوۤءُ عَمَلِهِۦ فَرَءَاهُ حَسَنࣰاۖ فَإِنَّ ٱللَّهَ یُضِلُّ مَن یَشَاۤءُ وَیَهۡدِی مَن یَشَاۤءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَیۡهِمۡ حَسَرَ ٰتٍۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِمَا یَصۡنَعُونَ ۝٨", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "أفمن حسَّن له الشيطان أعماله السيئة من معاصي الله والكفر وعبادة ما دونه من الآلهة والأوثان فرآه حسنًا جميلا كمَن هداه الله تعالى، فرأى الحسن حسنًا والسيئ سيئًا؟ فإن الله يضل من يشاء من عباده، ويهدي من يشاء، فلا تُهْلك نفسك حزنًا على كفر هؤلاء الضالين، إن الله عليم بقبائحهم وسيجازيهم عليها أسوأ الجزاء.", "isBasmala": false, "translation_en": "What of him whose evil deed was made attractive to him, and so he regards it as good? God leads astray whomever He wills, and He guides whomever He wills. Therefore, do not waste yourself sorrowing over them. God knows exactly what they do.", "translation_id": "Maka apakah orang yang dijadikan (syaitan) menganggap baik pekerjaannya yang buruk lalu dia meyakini pekerjaan itu baik, (sama dengan orang yang tidak ditipu oleh syaitan)? Maka sesungguhnya Allah menyesatkan siapa yang dikehendaki-Nya dan menunjuki siapa yang dikehendaki-Nya; maka janganlah dirimu binasa karena kesedihan terhadap mereka. Sesungguhnya Allah Maha Mengetahui apa yang mereka perbuat.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 9, "text": "وَٱللَّهُ ٱلَّذِیۤ أَرۡسَلَ ٱلرِّیَـٰحَ فَتُثِیرُ سَحَابࣰا فَسُقۡنَـٰهُ إِلَىٰ بَلَدࣲ مَّیِّتࣲ فَأَحۡیَیۡنَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ كَذَ ٰلِكَ ٱلنُّشُورُ ۝٩", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "واللهُ هو الذي أرسل الرياح فتحرك سحابًا، فسقناه إلى بلد جدب، فينزل الماء فأحيينا به الأرض بعد يُبْسها فتخضر بالنبات، مثل ذلك الإحياء يحيي الله الموتى يوم القيامة.", "isBasmala": false, "translation_en": "God is He who sends the winds, which agitate clouds, which We drive to a dead land, and thereby revive the ground after it had died. Likewise is the Resurrection.", "translation_id": "Dan Allah, Dialah Yang mengirimkan angin; lalu angin itu menggerakkan awan, maka Kami halau awan itu kesuatu negeri yang mati lalu Kami hidupkan bumi setelah matinya dengan hujan itu. Demikianlah kebangkitan itu.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 10, "text": "مَن كَانَ یُرِیدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِیعًاۚ إِلَیۡهِ یَصۡعَدُ ٱلۡكَلِمُ ٱلطَّیِّبُ وَٱلۡعَمَلُ ٱلصَّـٰلِحُ یَرۡفَعُهُۥۚ وَٱلَّذِینَ یَمۡكُرُونَ ٱلسَّیِّـَٔاتِ لَهُمۡ عَذَابࣱ شَدِیدࣱۖ وَمَكۡرُ أُو۟لَـٰۤىِٕكَ هُوَ یَبُورُ ۝١٠", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "من كان يطلب عزة في الدنيا أو الآخرة فليطلبها من الله، ولا تُنال إلا بطاعته، فلله العزة جميعًا، فمن اعتز بالمخلوق أذلَّه الله، ومن اعتز بالخالق أعزه الله، إليه سبحانه يصعد ذكره والعمل الصالح يرفعه. والذين يكتسبون السيئات لهم عذاب شديد، ومكر أولئك يَهْلك ويَفْسُد، ولا يفيدهم شيئًا.", "isBasmala": false, "translation_en": "Whoever desires honor-all honor belongs to God. To Him ascends speech that is pure, and He elevates righteous conduct. As for those who plot evil, a terrible punishment awaits them, and the planning of these will fail.", "translation_id": "Barangsiapa yang menghendaki kemuliaan, maka bagi Allah-lah kemuliaan itu semuanya. Kepada-Nya-lah naik perkataan-perkataan yang baik dan amal yang saleh dinaikkan-Nya. Dan orang-orang yang merencanakan kejahatan bagi mereka azab yang keras. Dan rencana jahat mereka akan hancur.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 11, "text": "وَٱللَّهُ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ جَعَلَكُمۡ أَزۡوَ ٰجࣰاۚ وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَمَا یُعَمَّرُ مِن مُّعَمَّرࣲ وَلَا یُنقَصُ مِنۡ عُمُرِهِۦۤ إِلَّا فِی كِتَـٰبٍۚ إِنَّ ذَ ٰلِكَ عَلَى ٱللَّهِ یَسِیرࣱ ۝١١", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "واللهُ خلق أباكم آدم من تراب، ثم جعل نسله من سلالة من ماء مهين، ثم جعلكم رجالا ونساءً. وما تحمل من أنثى ولا تضع إلا بعلمه، وما يعمَّر من مُعَمَّر، فيطول عمره، ولا يُنْقَص من عمره إلا في كتاب عنده، وهو اللوح المحفوظ، قبل أن تحمل به أمُّه وقبل أن تضعه. قد أحصى الله ذلك كله، وعلمه قبل أن يخلقه، لا يُزاد فيما كتب له ولا يُنْقَص. إن خَلْقكم وعِلْم أحوالكم وكتابتها في اللوح المحفوظ سهل يسير على الله.", "isBasmala": false, "translation_en": "God created you from dust, then from a small drop; then He made you pairs. No female conceives, or delivers, except with His knowledge. No living thing advances in years, or its life is shortened, except it be in a Record. That is surely easy for God.", "translation_id": "Dan Allah menciptakan kamu dari tanah kemudian dari air mani, kemudian Dia menjadikan kamu berpasangan (laki-laki dan perempuan). Dan tidak ada seorang perempuanpun mengandung dan tidak (pula) melahirkan melainkan dengan sepengetahuan-Nya. Dan sekali-kali tidak dipanjangkan umur seorang yang berumur panjang dan tidak pula dikurangi umurnya, melainkan (sudah ditetapkan) dalam Kitab (Lauh Mahfuzh). Sesungguhnya yang demikian itu bagi Allah adalah mudah.", "manzil": 5, "manzil_display": ""}], "436": [{"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 12, "text": "وَمَا یَسۡتَوِی ٱلۡبَحۡرَانِ هَـٰذَا عَذۡبࣱ فُرَاتࣱ سَاۤىِٕغࣱ شَرَابُهُۥ وَهَـٰذَا مِلۡحٌ أُجَاجࣱۖ وَمِن كُلࣲّ تَأۡكُلُونَ لَحۡمࣰا طَرِیࣰّا وَتَسۡتَخۡرِجُونَ حِلۡیَةࣰ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ فِیهِ مَوَاخِرَ لِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ۝١٢", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "وما يستوي البحران: هذا عذب شديد العذوبة، سَهْلٌ مروره في الحلق يزيل العطش، وهذا ملح شديد الملوحة، ومن كل من البحرين تأكلون سمكًا طريًّا شهيَّ الطَّعم، وتستخرجون زينة هي اللؤلؤ والمَرْجان تَلْبَسونها، وترى السفن فيه شاقات المياه؛ لتبتغوا من فضله من التجارة وغيرها. وفي هذا دلالة على قدرة الله ووحدانيته؛ ولعلكم تشكرون لله على هذه النعم التي أنعم بها عليكم.", "isBasmala": false, "translation_en": "The two seas are not the same. One is fresh, sweet, good to drink, while the other is salty and bitter. Yet from each you eat tender meat, and extract jewelry which you wear. And you see the ships plowing through them, so that you may seek of His bounty, so that you may give thanks.", "translation_id": "Dan tiada sama (antara) dua laut; yang ini tawar, segar, sedap diminum dan yang lain asin lagi pahit. Dan dari masing-masing laut itu kamu dapat memakan daging yang segar dan kamu dapat mengeluarkan perhiasan yang dapat kamu memakainya, dan pada masing-masingnya kamu lihat kapal-kapal berlayar membelah laut supaya kamu dapat mencari karunia-Nya dan supaya kamu bersyukur.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 13, "text": "یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِی لِأَجَلࣲ مُّسَمࣰّىۚ ذَ ٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۚ وَٱلَّذِینَ تَدۡعُونَ مِن دُونِهِۦ مَا یَمۡلِكُونَ مِن قِطۡمِیرٍ ۝١٣", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "واللهُ يدخل من ساعات الليل في النهار، فيزيد النهار بقَدْر ما نقص من الليل، ويُدخل من ساعات النهار في الليل، فيزيد الليل بقَدْر ما نقص من النهار، وذلل الشمس والقمر، يجريان لوقت معلوم، ذلكم الذي فعل هذا هو الله ربكم له الملك كله، والذين تعبدون من دون الله ما يملكون مِن قطمير، وهي القشرة الرقيقة البيضاء تكون على النَّواة.", "isBasmala": false, "translation_en": "He merges the night into the day, and He merges the day into the night; and He regulates the sun and the moon, each running for a stated term. Such is God, your Lord; His is the sovereignty. As for those you call upon besides Him, they do not possess a speck.", "translation_id": "Dia memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam dan menundukkan matahari dan bulan, masing-masing berjalan menurut waktu yang ditentukan. Yang (berbuat) demikian itulah Allah Tuhanmu, kepunyaan-Nya-lah kerajaan. Dan orang-orang yang kamu seru (sembah) selain Allah tiada mempunyai apa-apa walaupun setipis kulit ari.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 14, "text": "إِن تَدۡعُوهُمۡ لَا یَسۡمَعُوا۟ دُعَاۤءَكُمۡ وَلَوۡ سَمِعُوا۟ مَا ٱسۡتَجَابُوا۟ لَكُمۡۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ یَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا یُنَبِّئُكَ مِثۡلُ خَبِیرࣲ ۝١٤", "juz": 22, "hizb": "(*¼ ح 44*)", "tafsir": "إن تدعوا -أيها الناس- هذه المعبودات من دون الله لا يسمعوا دعاءكم، ولو سمعوا على سبيل الفرض ما أجابوكم، ويوم القيامة يتبرؤون منكم، ولا أحد يخبرك -أيها الرسول- أصدق من الله العليم الخبير.", "isBasmala": false, "translation_en": "If you pray to them, they cannot hear your prayer. And even if they heard, they would not answer you. And on the Day of Resurrection, they will reject your partnership. None informs you like an Expert.", "translation_id": "Jika kamu menyeru mereka, mereka tiada mendengar seruanmu; dan kalau mereka mendengar, mereka tidak dapat memperkenankan permintaanmu. Dan dihari kiamat mereka akan mengingkari kemusyirikanmu dan tidak ada yang dapat memberi keterangan kepadamu sebagai yang diberikan oleh Yang Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 15, "text": "۞ یَـٰۤأَیُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَاۤءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ ۝١٥", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "يا أيها الناس أنتم المحتاجون إلى الله في كل شيء، لا تستغنون عنه طرفة عين، وهو سبحانه الغنيُّ عن الناس وعن كل شيء من مخلوقاته، الحميد في ذاته وأسمائه وصفاته، المحمود على نعمه؛ فإن كل نعمة بالناس فمنه، فله الحمد والشكر على كلِّ حال.", "isBasmala": false, "translation_en": "O people! It is you who are the poor, in need of God; while God is the Rich, the Praiseworthy.", "translation_id": "Hai manusia, kamulah yang berkehendak kepada Allah; dan Allah Dialah Yang Maha Kaya (tidak memerlukan sesuatu) lagi Maha Terpuji.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 16, "text": "إِن یَشَأۡ یُذۡهِبۡكُمۡ وَیَأۡتِ بِخَلۡقࣲ جَدِیدࣲ ۝١٦", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "إن يشأ الله يهلكُّم أيها الناس، ويأت بقوم آخرين يطيعونه ويعبدونه وحده.", "isBasmala": false, "translation_en": "If He wills, He can do away with you, and produce a new creation.", "translation_id": "Jika Dia menghendaki, niscaya Dia memusnahkan kamu dan mendatangkan makhluk yang baru (untuk menggantikan kamu).", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 17, "text": "وَمَا ذَ ٰلِكَ عَلَى ٱللَّهِ بِعَزِیزࣲ ۝١٧", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وما إهلاككم والإتيان بخلق سواكم على الله بممتنع، بل ذلك على الله سهل يسير.", "isBasmala": false, "translation_en": "And that would not be difficult for God.", "translation_id": "Dan yang demikian itu sekali-kali tidak sulit bagi Allah.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 18, "text": "وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ وَإِن تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا یُحۡمَلۡ مِنۡهُ شَیۡءࣱ وَلَوۡ كَانَ ذَا قُرۡبَىٰۤۗ إِنَّمَا تُنذِرُ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَۚ وَمَن تَزَكَّىٰ فَإِنَّمَا یَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِیرُ ۝١٨", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "ولا تحمل نفس مذنبة ذنب نفس أخرى، وإن تَسْأل نفسٌ مثقَلَة بالخطايا مَن يحمل عنها من ذنوبها لم تجد من يَحمل عنها شيئًا، ولو كان الذي سألتْه ذا قرابة منها من أب أو أخ ونحوهما. إنما تحذِّر -أيها الرسول- الذين يخافون عذاب ربهم بالغيب، وأدَّوا الصلاة حق أدائها. ومن تطهر من الشرك وغيره من المعاصي فإنما يتطهر لنفسه. وإلى الله سبحانه مآل الخلائق ومصيرهم، فيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "No burdened soul can carry the burden of another. Even if one weighted down calls for help with its burden, nothing can be lifted from it, even if they were related. You are to warn those who fear their Lord inwardly, and perform the prayer. He who purifies himself purifies himself for his own good. To God is the ultimate return.", "translation_id": "Dan orang yang berdosa tidak akan memikul dosa orang lain. Dan jika seseorang yang berat dosanya memanggil (orang lain) untuk memikul dosanya itu tiadalah akan dipikulkan untuknya sedikitpun meskipun (yang dipanggilnya itu) kaum kerabatnya. Sesungguhnya yang dapat kamu beri peringatan hanya orang-orang yang takut kepada azab Tuhannya (sekalipun) mereka tidak melihat-Nya dan mereka mendirikan sembahyang. Dan barangsiapa yang mensucikan dirinya, sesungguhnya ia mensucikan diri untuk kebaikan dirinya sendiri. Dan kepada Allahlah kembali(mu).", "manzil": 5, "manzil_display": ""}], "437": [{"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 19, "text": "وَمَا یَسۡتَوِی ٱلۡأَعۡمَىٰ وَٱلۡبَصِیرُ ۝١٩", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وما يستوي الأعمى عن دين الله، والبصير الذي أبصر طريق الحق واتبعه، وما تستوي ظلمات الكفر ونور الإيمان، ولا الظل ولا الريح الحارة، وما يستوي أحياء القلوب بالإيمان، وأموات القلوب بالكفر. إن الله يسمع مَن يشاء سماع فَهْم وقَبول، وما أنت -أيها الرسول- بمسمع مَن في القبور، فكما لا تُسمع الموتى في قبورهم فكذلك لا تُسمع هؤلاء الكفار لموت قلوبهم، إن أنت إلا نذير لهم غضب الله وعقابه. إنا أرسلناك بالحق، وهو الإيمان بالله وشرائع الدين، مبشرًا بالجنة مَن صدَّقك وعمل بهديك، ومحذرًا مَن كذَّبك وعصاك النار. وما من أمة من الأمم إلا جاءها نذير يحذرها عاقبة كفرها وضلالها.", "isBasmala": false, "translation_en": "Not equal are the blind and the seeing.", "translation_id": "Dan tidaklah sama orang yang buta dengan orang yang melihat.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 20, "text": "وَلَا ٱلظُّلُمَـٰتُ وَلَا ٱلنُّورُ ۝٢٠", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وما يستوي الأعمى عن دين الله، والبصير الذي أبصر طريق الحق واتبعه، وما تستوي ظلمات الكفر ونور الإيمان، ولا الظل ولا الريح الحارة، وما يستوي أحياء القلوب بالإيمان، وأموات القلوب بالكفر. إن الله يسمع مَن يشاء سماع فَهْم وقَبول، وما أنت -أيها الرسول- بمسمع مَن في القبور، فكما لا تُسمع الموتى في قبورهم فكذلك لا تُسمع هؤلاء الكفار لموت قلوبهم، إن أنت إلا نذير لهم غضب الله وعقابه. إنا أرسلناك بالحق، وهو الإيمان بالله وشرائع الدين، مبشرًا بالجنة مَن صدَّقك وعمل بهديك، ومحذرًا مَن كذَّبك وعصاك النار. وما من أمة من الأمم إلا جاءها نذير يحذرها عاقبة كفرها وضلالها.", "isBasmala": false, "translation_en": "Nor are the darkness and the light.", "translation_id": "dan tidak (pula) sama gelap gulita dengan cahaya,", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 21, "text": "وَلَا ٱلظِّلُّ وَلَا ٱلۡحَرُورُ ۝٢١", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وما يستوي الأعمى عن دين الله، والبصير الذي أبصر طريق الحق واتبعه، وما تستوي ظلمات الكفر ونور الإيمان، ولا الظل ولا الريح الحارة، وما يستوي أحياء القلوب بالإيمان، وأموات القلوب بالكفر. إن الله يسمع مَن يشاء سماع فَهْم وقَبول، وما أنت -أيها الرسول- بمسمع مَن في القبور، فكما لا تُسمع الموتى في قبورهم فكذلك لا تُسمع هؤلاء الكفار لموت قلوبهم، إن أنت إلا نذير لهم غضب الله وعقابه. إنا أرسلناك بالحق، وهو الإيمان بالله وشرائع الدين، مبشرًا بالجنة مَن صدَّقك وعمل بهديك، ومحذرًا مَن كذَّبك وعصاك النار. وما من أمة من الأمم إلا جاءها نذير يحذرها عاقبة كفرها وضلالها.", "isBasmala": false, "translation_en": "Nor are the shade and the torrid heat.", "translation_id": "dan tidak (pula) sama yang teduh dengan yang panas,", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 22, "text": "وَمَا یَسۡتَوِی ٱلۡأَحۡیَاۤءُ وَلَا ٱلۡأَمۡوَ ٰتُۚ إِنَّ ٱللَّهَ یُسۡمِعُ مَن یَشَاۤءُۖ وَمَاۤ أَنتَ بِمُسۡمِعࣲ مَّن فِی ٱلۡقُبُورِ ۝٢٢", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وما يستوي الأعمى عن دين الله، والبصير الذي أبصر طريق الحق واتبعه، وما تستوي ظلمات الكفر ونور الإيمان، ولا الظل ولا الريح الحارة، وما يستوي أحياء القلوب بالإيمان، وأموات القلوب بالكفر. إن الله يسمع مَن يشاء سماع فَهْم وقَبول، وما أنت -أيها الرسول- بمسمع مَن في القبور، فكما لا تُسمع الموتى في قبورهم فكذلك لا تُسمع هؤلاء الكفار لموت قلوبهم، إن أنت إلا نذير لهم غضب الله وعقابه. إنا أرسلناك بالحق، وهو الإيمان بالله وشرائع الدين، مبشرًا بالجنة مَن صدَّقك وعمل بهديك، ومحذرًا مَن كذَّبك وعصاك النار. وما من أمة من الأمم إلا جاءها نذير يحذرها عاقبة كفرها وضلالها.", "isBasmala": false, "translation_en": "Nor are equal the living and the dead. God causes whomever He wills to hear, but you cannot make those in the graves hear.", "translation_id": "dan tidak (pula) sama orang-orang yang hidup dan orang-orang yang mati. Sesungguhnya Allah memberi pendengaran kepada siapa yang dikehendaki-Nya dan kamu sekali-kali tiada sanggup menjadikan orang yang didalam kubur dapat mendengar.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 23, "text": "إِنۡ أَنتَ إِلَّا نَذِیرٌ ۝٢٣", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وما يستوي الأعمى عن دين الله، والبصير الذي أبصر طريق الحق واتبعه، وما تستوي ظلمات الكفر ونور الإيمان، ولا الظل ولا الريح الحارة، وما يستوي أحياء القلوب بالإيمان، وأموات القلوب بالكفر. إن الله يسمع مَن يشاء سماع فَهْم وقَبول، وما أنت -أيها الرسول- بمسمع مَن في القبور، فكما لا تُسمع الموتى في قبورهم فكذلك لا تُسمع هؤلاء الكفار لموت قلوبهم، إن أنت إلا نذير لهم غضب الله وعقابه. إنا أرسلناك بالحق، وهو الإيمان بالله وشرائع الدين، مبشرًا بالجنة مَن صدَّقك وعمل بهديك، ومحذرًا مَن كذَّبك وعصاك النار. وما من أمة من الأمم إلا جاءها نذير يحذرها عاقبة كفرها وضلالها.", "isBasmala": false, "translation_en": "You are only a warner.", "translation_id": "Kamu tidak lain hanyalah seorang pemberi peringatan.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 24, "text": "إِنَّاۤ أَرۡسَلۡنَـٰكَ بِٱلۡحَقِّ بَشِیرࣰا وَنَذِیرࣰاۚ وَإِن مِّنۡ أُمَّةٍ إِلَّا خَلَا فِیهَا نَذِیرࣱ ۝٢٤", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وما يستوي الأعمى عن دين الله، والبصير الذي أبصر طريق الحق واتبعه، وما تستوي ظلمات الكفر ونور الإيمان، ولا الظل ولا الريح الحارة، وما يستوي أحياء القلوب بالإيمان، وأموات القلوب بالكفر. إن الله يسمع مَن يشاء سماع فَهْم وقَبول، وما أنت -أيها الرسول- بمسمع مَن في القبور، فكما لا تُسمع الموتى في قبورهم فكذلك لا تُسمع هؤلاء الكفار لموت قلوبهم، إن أنت إلا نذير لهم غضب الله وعقابه. إنا أرسلناك بالحق، وهو الإيمان بالله وشرائع الدين، مبشرًا بالجنة مَن صدَّقك وعمل بهديك، ومحذرًا مَن كذَّبك وعصاك النار. وما من أمة من الأمم إلا جاءها نذير يحذرها عاقبة كفرها وضلالها.", "isBasmala": false, "translation_en": "We sent you with the truth; a bearer of good news, and a warner. There is no community but a warner has passed through it.", "translation_id": "Sesungguhnya Kami mengutus kamu dengan membawa kebenaran sebagai pembawa berita gembira dan sebagai pemberi peringatan. Dan tidak ada suatu umatpun melainkan telah ada padanya seorang pemberi peringatan.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 25, "text": "وَإِن یُكَذِّبُوكَ فَقَدۡ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ جَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ وَبِٱلزُّبُرِ وَبِٱلۡكِتَـٰبِ ٱلۡمُنِیرِ ۝٢٥", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وإن يكذبك هؤلاء المشركون فقد كذَّب الذين مِن قبلهم رسلهم الذين جاؤوهم بالمعجزات الواضحات الدالة على نبوتهم، وجاؤوهم بالكتب المجموع فيها كثير من الأحكام، وبالكتاب المنير الموضح لطريق الخير والشر.", "isBasmala": false, "translation_en": "If they disbelieve you, those before them also disbelieved. Their messengers came to them with the clear proofs, with the Psalms, and with the Enlightening Scripture.", "translation_id": "Dan jika mereka mendustakan kamu, maka sesungguhnya orang-orang yang sebelum mereka telah mendustakan (rasul-rasulnya); kepada mereka telah datang rasul-rasulnya dengan membawa mukjizat yang nyata, zubur, dan kitab yang memberi penjelasan yang sempurna.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 26, "text": "ثُمَّ أَخَذۡتُ ٱلَّذِینَ كَفَرُوا۟ۖ فَكَیۡفَ كَانَ نَكِیرِ ۝٢٦", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "ثم أخَذْت الذين كفروا بأنواع العذاب، فانظر كيف كان إنكاري لعملهم وحلول عقوبتي بهم؟", "isBasmala": false, "translation_en": "Then I seized those who disbelieved-so how was My rejection?", "translation_id": "Kemudian Aku azab orang-orang yang kafir; maka (lihatlah) bagaimana (hebatnya) akibat kemurkaan-Ku.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 27, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَ ٰتࣲ مُّخۡتَلِفًا أَلۡوَ ٰنُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِیضࣱ وَحُمۡرࣱ مُّخۡتَلِفٌ أَلۡوَ ٰنُهَا وَغَرَابِیبُ سُودࣱ ۝٢٧", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "ألم تر أن الله أنزل من السماء ماء، فسقينا به أشجارًا في الأرض، فأخرجنا من تلك الأشجار ثمرات مختلفًا ألوانها، منها الأحمر ومنها الأسود والأصفر وغير ذلك؟ وخَلَقْنا من الجبال طرائق بيضًا وحمرًا مختلفًا ألوانها، وخلقنا من الجبال جبالا شديدة السواد.", "isBasmala": false, "translation_en": "Have you not seen that God sends down water from the sky? With it We produce fruits of various colors. And in the mountains are streaks of white and red-varying in their hue-and pitch-black.", "translation_id": "Tidakkah kamu melihat bahwasanya Allah menurunkan hujan dari langit lalu Kami hasilkan dengan hujan itu buah-buahan yang beraneka macam jenisnya. Dan di antara gunung-gunung itu ada garis-garis putih dan merah yang beraneka macam warnanya dan ada (pula) yang hitam pekat.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 28, "text": "وَمِنَ ٱلنَّاسِ وَٱلدَّوَاۤبِّ وَٱلۡأَنۡعَـٰمِ مُخۡتَلِفٌ أَلۡوَ ٰنُهُۥ كَذَ ٰلِكَۗ إِنَّمَا یَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَـٰۤؤُا۟ۗ إِنَّ ٱللَّهَ عَزِیزٌ غَفُورٌ ۝٢٨", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وخلقنا من الناس والدواب والإبل والبقر والغنم ما هو مختلف ألوانه كذلك، فمن ذلك الأحمر والأبيض والأسود وغير ذلك كاختلاف ألوان الثمار والجبال. إنما يخشى اللهَ ويتقي عقابه بطاعته واجتناب معصيته العلماءُ به سبحانه، وبصفاته، وبشرعه، وقدرته على كل شيء، ومنها اختلاف هذه المخلوقات مع اتحاد سببها، ويتدبرون ما فيها من عظات وعبر. إن الله عزيز قويٌّ لا يغالَب، غفور يثيب أهل الطاعة، ويعفو عنهم.", "isBasmala": false, "translation_en": "Likewise, human beings, animals, and livestock come in various colors. From among His servants, the learned fear God. God is Almighty, Oft-Forgiving.", "translation_id": "Dan demikian (pula) di antara manusia, binatang-binatang melata dan binatang-binatang ternak ada yang bermacam-macam warnanya (dan jenisnya). Sesungguhnya yang takut kepada Allah di antara hamba-hamba-Nya, hanyalah ulama. Sesungguhnya Allah Maha Perkasa lagi Maha Pengampun.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 29, "text": "إِنَّ ٱلَّذِینَ یَتۡلُونَ كِتَـٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقۡنَـٰهُمۡ سِرࣰّا وَعَلَانِیَةࣰ یَرۡجُونَ تِجَـٰرَةࣰ لَّن تَبُورَ ۝٢٩", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "إن الذين يقرؤون القرآن، ويعملون به، وداوموا على الصلاة في أوقاتها، وأنفقوا مما رزقناهم من أنواع النفقات الواجبة والمستحبة سرًّا وجهرًا، هؤلاء يرجون بذلك تجارة لن تكسد ولن تهلك، ألا وهي رضا ربهم، والفوز بجزيل ثوابه؛ ليوفيهم الله تعالى ثواب أعمالهم كاملا غير منقوص، ويضاعف لهم الحسنات من فضله، إن الله غفور لسيئاتهم، شكور لحسناتهم، يثيبهم عليها الجزيل من الثواب.", "isBasmala": false, "translation_en": "Those who recite the Book of God, and perform the prayer, and spend of what We have provided for them, secretly and publicly, expect a trade that will not fail.", "translation_id": "Sesungguhnya orang-orang yang selalu membaca kitab Allah dan mendirikan shalat dan menafkahkan sebahagian dari rezeki yang Kami anugerahkan kepada mereka dengan diam-diam dan terang-terangan, mereka itu mengharapkan perniagaan yang tidak akan merugi,", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 30, "text": "لِیُوَفِّیَهُمۡ أُجُورَهُمۡ وَیَزِیدَهُم مِّن فَضۡلِهِۦۤۚ إِنَّهُۥ غَفُورࣱ شَكُورࣱ ۝٣٠", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "إن الذين يقرؤون القرآن، ويعملون به، وداوموا على الصلاة في أوقاتها، وأنفقوا مما رزقناهم من أنواع النفقات الواجبة والمستحبة سرًّا وجهرًا، هؤلاء يرجون بذلك تجارة لن تكسد ولن تهلك، ألا وهي رضا ربهم، والفوز بجزيل ثوابه؛ ليوفيهم الله تعالى ثواب أعمالهم كاملا غير منقوص، ويضاعف لهم الحسنات من فضله، إن الله غفور لسيئاتهم، شكور لحسناتهم، يثيبهم عليها الجزيل من الثواب.", "isBasmala": false, "translation_en": "He will pay them their dues in full, and will increase them from His bounty. He is Forgiving and Appreciative.", "translation_id": "agar Allah menyempurnakan kepada mereka pahala mereka dan menambah kepada mereka dari karunia-Nya. Sesungguhnya Allah Maha Pengampun lagi Maha Mensyukuri.", "manzil": 5, "manzil_display": ""}], "438": [{"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 31, "text": "وَٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ مِنَ ٱلۡكِتَـٰبِ هُوَ ٱلۡحَقُّ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِیرُۢ بَصِیرࣱ ۝٣١", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "والذي أنزلناه إليك -أيها الرسول- من القرآن هو الحق المصدِّق للكتب التي أنزلها الله على رسله قبلك. إن الله لخبير بشؤون عباده، بصير بأعمالهم، وسيجازيهم عليها.", "isBasmala": false, "translation_en": "What We inspired in you, of the Book, is the truth, confirming what preceded it. God is Well-Informed of His servants, All-Seeing.", "translation_id": "Dan apa yang telah Kami wahyukan kepadamu yaitu Al Kitab (Al Quran) itulah yang benar, dengan membenarkan kitab-kitab yang sebelumnya. Sesungguhnya Allah benar-benar Maha Mengetahui lagi Maha Melihat (keadaan) hamba-hamba-Nya.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 32, "text": "ثُمَّ أَوۡرَثۡنَا ٱلۡكِتَـٰبَ ٱلَّذِینَ ٱصۡطَفَیۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمࣱ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدࣱ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَیۡرَ ٰتِ بِإِذۡنِ ٱللَّهِۚ ذَ ٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِیرُ ۝٣٢", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "ثم أعطينا -بعد هلاك الأمم- القرآن مَن اخترناهم من أمة محمد صلى الله عليه وسلم: فمنهم ظالم لنفسه بفعل بعض المعاصي، ومنهم مقتصد، وهو المؤدي للواجبات المجتنب للمحرمات، ومنهم سابق بالخيرات بإذن الله، أي مسارع مجتهد في الأعمال الصالحة، فَرْضِها ونفلها، ذلك الإعطاء للكتاب واصطفاء هذه الأمة هو الفضل الكبير.", "isBasmala": false, "translation_en": "Then We passed the Book to those of Our servants whom We chose. Some of them wrong their souls, and some follow a middle course, and some are in the foremost in good deeds by God's leave; that is the greatest blessing.", "translation_id": "Kemudian Kitab itu Kami wariskan kepada orang-orang yang Kami pilih di antara hamba-hamba Kami, lalu di antara mereka ada yang menganiaya diri mereka sendiri dan di antara mereka ada yang pertengahan dan diantara mereka ada (pula) yang lebih dahulu berbuat kebaikan dengan izin Allah. Yang demikian itu adalah karunia yang amat besar.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 33, "text": "جَنَّـٰتُ عَدۡنࣲ یَدۡخُلُونَهَا یُحَلَّوۡنَ فِیهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَلُؤۡلُؤࣰاۖ وَلِبَاسُهُمۡ فِیهَا حَرِیرࣱ ۝٣٣", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "جنات إقامة دائمة للذين أورثهم الله كتابه يُحلَّون فيها الأساور من الذهب واللؤلؤ، ولباسهم المعتاد في الجنة حرير أي: ثياب رقيقة. وقالوا حين دخلوا الجنة: الحمد لله الذي أذهب عنا كل حَزَن، إن ربنا لغفور؛ حيث غفر لنا الزلات، شكور؛ حيث قبل منا الحسنات وضاعفها. وهو الذي أنزلَنا دار الجنة من فضله، لا يمسنا فيها تعب ولا إعياء.", "isBasmala": false, "translation_en": "The Gardens of Eden, which they will enter. They will be adorned therein with gold bracelets and pearls, and their garments therein will be of silk.", "translation_id": "(Bagi mereka) surga 'Adn mereka masuk ke dalamnya, di dalamnya mereka diberi perhiasan dengan gelang-gelang dari emas, dan dengan mutiara, dan pakaian mereka didalamnya adalah sutera.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 34, "text": "وَقَالُوا۟ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِیۤ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورࣱ شَكُورٌ ۝٣٤", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "جنات إقامة دائمة للذين أورثهم الله كتابه يُحلَّون فيها الأساور من الذهب واللؤلؤ، ولباسهم المعتاد في الجنة حرير أي: ثياب رقيقة. وقالوا حين دخلوا الجنة: الحمد لله الذي أذهب عنا كل حَزَن، إن ربنا لغفور؛ حيث غفر لنا الزلات، شكور؛ حيث قبل منا الحسنات وضاعفها. وهو الذي أنزلَنا دار الجنة من فضله، لا يمسنا فيها تعب ولا إعياء.", "isBasmala": false, "translation_en": "And they will say, \"Praise God, who has lifted all sorrow from us. Our Lord is Most Forgiving, Most Appreciative.", "translation_id": "Dan mereka berkata: \"Segala puji bagi Allah yang telah menghilangkan duka cita dari kami. Sesungguhnya Tuhan kami benar-benar Maha Pengampum lagi Maha Mensyukuri.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 35, "text": "ٱلَّذِیۤ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا یَمَسُّنَا فِیهَا نَصَبࣱ وَلَا یَمَسُّنَا فِیهَا لُغُوبࣱ ۝٣٥", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "جنات إقامة دائمة للذين أورثهم الله كتابه يُحلَّون فيها الأساور من الذهب واللؤلؤ، ولباسهم المعتاد في الجنة حرير أي: ثياب رقيقة. وقالوا حين دخلوا الجنة: الحمد لله الذي أذهب عنا كل حَزَن، إن ربنا لغفور؛ حيث غفر لنا الزلات، شكور؛ حيث قبل منا الحسنات وضاعفها. وهو الذي أنزلَنا دار الجنة من فضله، لا يمسنا فيها تعب ولا إعياء.", "isBasmala": false, "translation_en": "He Who settled us in the Home of Permanence, by His grace, where boredom will not touch us, and fatigue will not afflict us.\"", "translation_id": "Yang menempatkan kami dalam tempat yang kekal (surga) dari karunia-Nya; didalamnya kami tiada merasa lelah dan tiada pula merasa lesu\".", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 36, "text": "وَٱلَّذِینَ كَفَرُوا۟ لَهُمۡ نَارُ جَهَنَّمَ لَا یُقۡضَىٰ عَلَیۡهِمۡ فَیَمُوتُوا۟ وَلَا یُخَفَّفُ عَنۡهُم مِّنۡ عَذَابِهَاۚ كَذَ ٰلِكَ نَجۡزِی كُلَّ كَفُورࣲ ۝٣٦", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "والذين كفروا بالله ورسوله لهم نار جهنم الموقدة، لا يُقْضى عليهم بالموت، فيموتوا ويستريحوا، ولا يُخَفَّف عنهم مِن عذابها، ومثل ذلك الجزاء يجزي الله كلَّ متمادٍ في الكفر مُصِرٍّ عليه.", "isBasmala": false, "translation_en": "As for those who disbelieve, for them is the Fire of Hell, wherein they will never be finished off and die, nor will its punishment be lightened for them. Thus We will repay every ingrate.", "translation_id": "Dan orang-orang kafir bagi mereka neraka Jahannam. Mereka tidak dibinasakan sehingga mereka mati dan tidak (pula) diringankan dari mereka azabnya. Demikianlah Kami membalas setiap orang yang sangat kafir.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 37, "text": "وَهُمۡ یَصۡطَرِخُونَ فِیهَا رَبَّنَاۤ أَخۡرِجۡنَا نَعۡمَلۡ صَـٰلِحًا غَیۡرَ ٱلَّذِی كُنَّا نَعۡمَلُۚ أَوَ لَمۡ نُعَمِّرۡكُم مَّا یَتَذَكَّرُ فِیهِ مَن تَذَكَّرَ وَجَاۤءَكُمُ ٱلنَّذِیرُۖ فَذُوقُوا۟ فَمَا لِلظَّـٰلِمِینَ مِن نَّصِیرٍ ۝٣٧", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "وهؤلاء الكفار يَصْرُخون من شدة العذاب في نار جهنم مستغيثين: ربنا أخرجنا من نار جهنم، وردَّنا إلى الدنيا نعمل صالحًا غير الذي كنا نعمله في حياتنا الدنيا، فنؤمن بدل الكفر، فيقول لهم: أولم نُمْهلكم في الحياة قَدْرًا وافيًا من العُمُر، يتعظ فيه من اتعظ، وجاءكم النبي صلى الله عليه وسلم، ومع ذلك لم تتذكروا ولم تتعظوا؟ فذوقوا عذاب جهنم، فليس للكافرين من ناصر ينصرهم من عذاب الله.", "isBasmala": false, "translation_en": "And they will scream therein, \"Our Lord, let us out, and we will act righteously, differently from the way we used to act.\" Did We not give you a life long enough, in which anyone who wanted to understand would have understood? And the warner did come to you. So taste. The evildoers will have no helper.", "translation_id": "Dan mereka berteriak di dalam neraka itu: \"Ya Tuhan kami, keluarkanlah kami niscaya kami akan mengerjakan amal yang saleh berlainan dengan yang telah kami kerjakan\". Dan apakah Kami tidak memanjangkan umurmu dalam masa yang cukup untuk berfikir bagi orang yang mau berfikir, dan (apakah tidak) datang kepada kamu pemberi peringatan? maka rasakanlah (azab Kami) dan tidak ada bagi orang-orang yang zalim seorang penolongpun.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 38, "text": "إِنَّ ٱللَّهَ عَـٰلِمُ غَیۡبِ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝٣٨", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "إن الله مطَّلع على كل غائب في السماوات والأرض، وإنه عليم بخفايا الصدور، فاتقوه أن يطَّلع عليكم، وأنتم تُضْمِرون الشك أو الشرك في وحدانيته، أو في نبوة محمد صلى الله عليه وسلم، أو أن تَعْصوه بما دون ذلك.", "isBasmala": false, "translation_en": "God is the Knower of the future of the heavens and the earth. He knows what the hearts contain.", "translation_id": "Sesungguhnya Allah mengetahui yang tersembunyi di langit dan di bumi. Sesungguhnya Dia Maha Mengetahui segala isi hati.", "manzil": 5, "manzil_display": ""}], "439": [{"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 39, "text": "هُوَ ٱلَّذِی جَعَلَكُمۡ خَلَـٰۤىِٕفَ فِی ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَیۡهِ كُفۡرُهُۥۖ وَلَا یَزِیدُ ٱلۡكَـٰفِرِینَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتࣰاۖ وَلَا یَزِیدُ ٱلۡكَـٰفِرِینَ كُفۡرُهُمۡ إِلَّا خَسَارࣰا ۝٣٩", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "الله هو الذي جعلكم -أيها الناس- يَخْلُف بعضكم بعضًا في الأرض، فمن جحد وحدانية الله منكم فعلى نفسه ضرره وكفره ولا يزيد الكافرين كفرهم عند ربهم إلا بغضًا وغضبًا، ولا يزيدهم كفرهم بالله إلا ضلالا وهلاكًا.", "isBasmala": false, "translation_en": "It is He who made you successors on earth. Whoever disbelieves, his disbelief will recoil upon him. The disbelief of the disbelievers adds only to their Lord's disfavor of them. The disbelief of the disbelievers adds only to their perdition.", "translation_id": "Dialah yang menjadikan kamu khalifah-khalifah di muka bumi. Barangsiapa yang kafir, maka (akibat) kekafirannya menimpa dirinya sendiri. Dan kekafiran orang-orang yang kafir itu tidak lain hanyalah akan menambah kemurkaan pada sisi Tuhannya dan kekafiran orang-orang yang kafir itu tidak lain hanyalah akan menambah kerugian mereka belaka.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 40, "text": "قُلۡ أَرَءَیۡتُمۡ شُرَكَاۤءَكُمُ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِی مَاذَا خَلَقُوا۟ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكࣱ فِی ٱلسَّمَـٰوَ ٰتِ أَمۡ ءَاتَیۡنَـٰهُمۡ كِتَـٰبࣰا فَهُمۡ عَلَىٰ بَیِّنَتࣲ مِّنۡهُۚ بَلۡ إِن یَعِدُ ٱلظَّـٰلِمُونَ بَعۡضُهُم بَعۡضًا إِلَّا غُرُورًا ۝٤٠", "juz": 22, "hizb": "(*½ ح 44*)", "tafsir": "قل -أيها الرسول- للمشركين: أخبروني أيَّ شيء خَلَق شركاؤكم من الأرض، أم أن لشركائكم الذين تعبدونهم من دون الله شركًا مع الله في خلق السماوات، أم أعطيناهم كتابًا فهم على حجة منه؟ بل ما يَعِدُ الكافرون بعضهم بعضًا إلا غرورًا وخداعًا.", "isBasmala": false, "translation_en": "Say, \"Have you considered those partners of yours that you worship instead of God? Show me what they have created on earth. Or do they have any share in the heavens?\" Or have We given them a book whose clear teachings they follow? In fact, the wrongdoers promise one another nothing but delusions.", "translation_id": "Katakanlah: \"Terangkanlah kepada-Ku tentang sekutu-sekutumu yang kamu seru selain Allah. Perlihatkanlah kepada-Ku (bahagian) manakah dari bumi ini yang telah mereka ciptakan ataukah mereka mempunyai saham dalam (penciptaan) langit atau adakah Kami memberi kepada mereka sebuah Kitab sehingga mereka mendapat keterangan-keterangan yang jelas daripadanya? Sebenarnya orang-orang yang zalim itu sebahagian dari mereka tidak menjanjikan kepada sebahagian yang lain, melainkan tipuan belaka\".", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 41, "text": "۞ إِنَّ ٱللَّهَ یُمۡسِكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ أَن تَزُولَاۚ وَلَىِٕن زَالَتَاۤ إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَدࣲ مِّنۢ بَعۡدِهِۦۤۚ إِنَّهُۥ كَانَ حَلِیمًا غَفُورࣰا ۝٤١", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "إن الله يمسك السماوات والأرض أن تزولا عن مكانهما، ولئن زالت السماوات والأرض عن مكانهما ما يمسكهما من أحد من بعده. إن الله كان حليمًا في تأخير العقوبة عن الكافرين والعصاة، غفورًا لمن تاب من ذنبه ورجع إليه.", "isBasmala": false, "translation_en": "God holds the heavens and the earth, lest they fall apart. And were they to fall apart, there is none to hold them together except He. He is Most Clement, Most Forgiving.", "translation_id": "Sesungguhnya Allah menahan langit dan bumi supaya jangan lenyap; dan sungguh jika keduanya akan lenyap tidak ada seorangpun yang dapat menahan keduanya selain Allah. Sesungguhnya Dia adalah Maha Penyantun lagi Maha Pengampun.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 42, "text": "وَأَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ لَىِٕن جَاۤءَهُمۡ نَذِیرࣱ لَّیَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَاۤءَهُمۡ نَذِیرࣱ مَّا زَادَهُمۡ إِلَّا نُفُورًا ۝٤٢", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "وأقسم كفار قريش بالله أشد الأَيْمان: لئن جاءهم رسول من عند الله يخوِّفهم عقاب الله ليكونُنَّ أكثر استقامة واتباعًا للحق من اليهود والنصارى وغيرهم، فلما جاءهم محمد صلى الله عليه وسلم ما زادهم ذلك إلا بُعْدًا عن الحق ونفورًا منه.", "isBasmala": false, "translation_en": "And they swore by God with their solemn oaths, that if a warner came to them, they would be more guided than any other people. Yet when a warner came to them, it only increased them in aversion.", "translation_id": "Dan mereka bersumpah dengan nama Allah dengan sekuat-kuat sumpah; sesungguhnya jika datang kepada mereka seorang pemberi peringatan, niscaya mereka akan lebih mendapat petunjuk dari salah satu umat-umat (yang lain). Tatkala datang kepada mereka pemberi peringatan, maka kedatangannya itu tidak menambah kepada mereka, kecuali jauhnya mereka dari (kebenaran),", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 43, "text": "ٱسۡتِكۡبَارࣰا فِی ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّیِّىِٕۚ وَلَا یَحِیقُ ٱلۡمَكۡرُ ٱلسَّیِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ یَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِینَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِیلࣰاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِیلًا ۝٤٣", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "ليس إقسامهم لقَصْد حسن وطلبًا للحق، وإنما هو استكبار في الأرض على الخلق، يريدون به المكر السيِّئ والخداع والباطل، ولا يحيق المكر السيِّئ إلا بأهله، فهل ينتظر المستكبرون الماكرون إلا العذاب الذي نزل بأمثالهم الذين سبقوهم، فلن تجد لطريقة الله تبديلا ولا تحويلا فلا يستطيع أحد أن يُبَدِّل، ولا أن يُحَوِّل العذاب عن نفسه أو غيره.", "isBasmala": false, "translation_en": "Priding themselves on earth, and scheming evil. But evil scheming overwhelms none but its authors. Do they expect anything but the precedent of the ancients? You will not find any change in God's practice, and you will not find any substitute to God's practice.", "translation_id": "karena kesombongan (mereka) di muka bumi dan karena rencana (mereka) yang jahat. Rencana yang jahat itu tidak akan menimpa selain orang yang merencanakannya sendiri. Tiadalah yang mereka nanti-nantikan melainkan (berlakunya) sunnah (Allah yang telah berlaku) kepada orang-orang yang terdahulu. Maka sekali-kali kamu tidak akan mendapat penggantian bagi sunnah Allah, dan sekali-kali tidak (pula) akan menemui penyimpangan bagi sunnah Allah itu.", "manzil": 5, "manzil_display": ""}, {"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 44, "text": "أَوَ لَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡ وَكَانُوۤا۟ أَشَدَّ مِنۡهُمۡ قُوَّةࣰۚ وَمَا كَانَ ٱللَّهُ لِیُعۡجِزَهُۥ مِن شَیۡءࣲ فِی ٱلسَّمَـٰوَ ٰتِ وَلَا فِی ٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ عَلِیمࣰا قَدِیرࣰا ۝٤٤", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "أولم يَسِرْ كفار \"مكة\" في الأرض، فينظروا كيف كان عاقبة الذين من قبلهم كعاد وثمود وأمثالهم، وما حلَّ بهم من الدمار، وبديارهم من الخراب، حين كذبوا الرسل، وكان أولئك الكفرة أشد قوة وبطشًا من كفار \"مكة\"؟ وما كان الله تعالى ليعجزه ويفوته من شيء في السماوات ولا في الأرض، إنه كان عليمًا بأفعالهم، قديرًا على إهلاكهم.", "isBasmala": false, "translation_en": "Have they not journeyed in the land and observed the fate of those who preceded them? They were superior to them in strength. But nothing can defeat God in the heavens or on Earth. He is indeed Omniscient and Omnipotent.", "translation_id": "Dan apakah mereka tidak berjalan di muka bumi, lalu melihat bagaimana kesudahan orang-orang yang sebelum mereka, sedangkan orang-orang itu adalah lebih besar kekuatannya dari mereka? Dan tiada sesuatupun yang dapat melemahkan Allah baik di langit maupun di bumi. Sesungguhnya Allah Maha Mengetahui lagi Maha Kuasa.", "manzil": 5, "manzil_display": ""}], "440": [{"sura": 35, "sura_name": "فاطر", "revelation": "Makkiyah", "aya": 45, "text": "وَلَوۡ یُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَاۤبَّةࣲ وَلَـٰكِن یُؤَخِّرُهُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّىۖ فَإِذَا جَاۤءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِیرَۢا ۝٤٥", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "ولو يعاقب الله الناس بما عملوا من الذنوب والمعاصي ما ترك على ظهر الأرض من دابة تَدِبُّ عليها، ولكن يُمْهلهم ويؤخر عقابهم إلى وقت معلوم عنده، فإذا جاء وقت عقابهم فإن الله كان بعباده بصيرًا، لا يخفى عليه أحد منهم، ولا يعزب عنه علم شيء من أمورهم، وسيجازيهم بما عملوا من خير أو شر.", "isBasmala": false, "translation_en": "If God were to punish the people for what they have earned, He would not leave a single living creature on its surface. But He defers them until a stated time. Then, when their time has arrived-God is Observant of His creatures.", "translation_id": "Dan kalau sekiranya Allah menyiksa manusia disebabkan usahanya, niscaya Dia tidak akan meninggalkan di atas permukaan bumi suatu mahluk yang melatapun akan tetapi Allah menangguhkan (penyiksaan) mereka, sampai waktu yang tertentu; maka apabila datang ajal mereka, maka sesungguhnya Allah adalah Maha Melihat (keadaan) hamba-hamba-Nya.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 23, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 1, "text": "یسۤ ۝١", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "(يس) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ya, Seen.", "translation_id": "Yaa siin", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 2, "text": "وَٱلۡقُرۡءَانِ ٱلۡحَكِیمِ ۝٢", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "يقسم الله تعالى بالقرآن المحكم بما فيه من الأحكام والحكم والحجج، إنك -أيها الرسول- لمن المرسلين بوحي الله إلى عباده، على طريق مستقيم معتدل، وهو الإسلام.", "isBasmala": false, "translation_en": "By the Wise Quran.", "translation_id": "Demi Al Quran yang penuh hikmah,", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 3, "text": "إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِینَ ۝٣", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "يقسم الله تعالى بالقرآن المحكم بما فيه من الأحكام والحكم والحجج، إنك -أيها الرسول- لمن المرسلين بوحي الله إلى عباده، على طريق مستقيم معتدل، وهو الإسلام.", "isBasmala": false, "translation_en": "You are one of the messengers.", "translation_id": "Sesungguhnya kamu salah seorang dari rasul-rasul,", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 4, "text": "عَلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٤", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "يقسم الله تعالى بالقرآن المحكم بما فيه من الأحكام والحكم والحجج، إنك -أيها الرسول- لمن المرسلين بوحي الله إلى عباده، على طريق مستقيم معتدل، وهو الإسلام.", "isBasmala": false, "translation_en": "On a straight path.", "translation_id": "(yang berada) diatas jalan yang lurus,", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 5, "text": "تَنزِیلَ ٱلۡعَزِیزِ ٱلرَّحِیمِ ۝٥", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "هذا القرآن تنزيل العزيز في انتقامه من أهل الكفر والمعاصي، الرحيم بمن تاب من عباده وعمل صالحًا.", "isBasmala": false, "translation_en": "The revelation of the Almighty, the Merciful.", "translation_id": "(sebagai wahyu) yang diturunkan oleh Yang Maha Perkasa lagi Maha Penyayang,", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 6, "text": "لِتُنذِرَ قَوۡمࣰا مَّاۤ أُنذِرَ ءَابَاۤؤُهُمۡ فَهُمۡ غَـٰفِلُونَ ۝٦", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "أنزلناه عليك -أيها الرسول- لتحذر به قومًا لم يُنْذَرْ آباؤهم من قبلك، وهم العرب، فهؤلاء القوم ساهون عن الإيمان والاستقامة على العمل الصالح. وكل أمة ينقطع عنها الإنذار تقع في الغفلة، وفي هذا دليل على وجوب الدعوة والتذكير على العلماء بالله وشرعه؛ لإيقاظ المسلمين من غفلتهم.", "isBasmala": false, "translation_en": "To warn a people whose ancestors were not warned, and so they are unaware.", "translation_id": "Agar kamu memberi peringatan kepada kaum yang bapak-bapak mereka belum pernah diberi peringatan, karena itu mereka lalai.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 7, "text": "لَقَدۡ حَقَّ ٱلۡقَوۡلُ عَلَىٰۤ أَكۡثَرِهِمۡ فَهُمۡ لَا یُؤۡمِنُونَ ۝٧", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "لقد وجب العذاب على أكثر هؤلاء الكافرين، بعد أن عُرِض عليهم الحق فرفضوه، فهم لا يصدقون بالله ولا برسوله، ولا يعملون بشرعه.", "isBasmala": false, "translation_en": "The Word was realized against most of them, for they do not believe.", "translation_id": "Sesungguhnya telah pasti berlaku perkataan (ketentuan Allah) terhadap kebanyakan mereka, kerena mereka tidak beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 8, "text": "إِنَّا جَعَلۡنَا فِیۤ أَعۡنَـٰقِهِمۡ أَغۡلَـٰلࣰا فَهِیَ إِلَى ٱلۡأَذۡقَانِ فَهُم مُّقۡمَحُونَ ۝٨", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "إنا جعلنا هؤلاء الكفار الذين عُرض عليهم الحق فردُّوه، وأصرُّوا على الكفر وعدم الإيمان، كمن جُعِل في أعناقهم أغلال، فجمعت أيديهم مع أعناقهم تحت أذقانهم، فاضطروا إلى رفع رؤوسهم إلى السماء، فهم مغلولون عن كل خير، لا يبصرون الحق ولا يهتدون إليه.", "isBasmala": false, "translation_en": "We placed shackles around their necks, up to their chins, so they are stiff-necked.", "translation_id": "Sesungguhnya Kami telah memasang belenggu dileher mereka, lalu tangan mereka (diangkat) ke dagu, maka karena itu mereka tertengadah.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 9, "text": "وَجَعَلۡنَا مِنۢ بَیۡنِ أَیۡدِیهِمۡ سَدࣰّا وَمِنۡ خَلۡفِهِمۡ سَدࣰّا فَأَغۡشَیۡنَـٰهُمۡ فَهُمۡ لَا یُبۡصِرُونَ ۝٩", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "وجعلنا من أمام الكافرين سدًّا ومن ورائهم سدًّا، فهم بمنزلة من سُدَّ طريقه من بين يديه ومن خلفه، فأعمينا أبصارهم؛ بسبب كفرهم واستكبارهم، فهم لا يبصرون رشدًا، ولا يهتدون. وكل من قابل دعوة الإسلام بالإعراض والعناد، فهو حقيق بهذا العقاب.", "isBasmala": false, "translation_en": "And We placed a barrier in front of them, and a barrier behind them, and We have enshrouded them, so they cannot see.", "translation_id": "Dan Kami adakan di hadapan mereka dinding dan di belakang mereka dinding (pula), dan Kami tutup (mata) mereka sehingga mereka tidak dapat melihat.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 10, "text": "وَسَوَاۤءٌ عَلَیۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا یُؤۡمِنُونَ ۝١٠", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "يستوي عند هؤلاء الكفار المعاندين تحذيرك لهم -أيها الرسول- وعدم تحذيرك، فهم لا يصدِّقون ولا يعملون.", "isBasmala": false, "translation_en": "It is the same for them, whether you warn them, or do not warn them-they will not believe.", "translation_id": "Sama saja bagi mereka apakah kamu memberi peringatan kepada mereka ataukah kamu tidak memberi peringatan kepada mereka, mereka tidak akan beriman.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 11, "text": "إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِیَ ٱلرَّحۡمَـٰنَ بِٱلۡغَیۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةࣲ وَأَجۡرࣲ كَرِیمٍ ۝١١", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "إنما ينفع تحذيرك مَن آمن بالقرآن، واتبع ما فيه من أحكام الله، وخاف الرحمن، حيث لا يراه أحد إلا الله، فبشِّره بمغفرة من الله لذنوبه، وثواب منه في الآخرة على أعماله الصالحة، وهو دخوله الجنة.", "isBasmala": false, "translation_en": "You warn only him who follows the Message, and fears the Most Gracious inwardly. So give him good news of forgiveness, and a generous reward.", "translation_id": "Sesungguhnya kamu hanya memberi peringatan kepada orang-orang yang mau mengikuti peringatan dan yang takut kepada Tuhan Yang Maha Pemurah walaupun dia tidak melihatnya. Maka berilah mereka kabar gembira dengan ampunan dan pahala yang mulia.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 12, "text": "إِنَّا نَحۡنُ نُحۡیِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُوا۟ وَءَاثَـٰرَهُمۡۚ وَكُلَّ شَیۡءٍ أَحۡصَیۡنَـٰهُ فِیۤ إِمَامࣲ مُّبِینࣲ ۝١٢", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "إنا نحن نحيي الأموات جميعًا ببعثهم يوم القيامة، ونكتب ما عملوا من الخير والشر، وآثارهم التي كانوا سببًا فيها في حياتهم وبعد مماتهم من خير، كالولد الصالح، والعلم النافع، والصدقة الجارية، ومن شر، كالشرك والعصيان، وكلَّ شيء أحصيناه في كتاب واضح هو أمُّ الكتب، وإليه مرجعها، وهو اللوح المحفوظ. فعلى العاقل محاسبة نفسه؛ ليكون قدوة في الخير في حياته وبعد مماته.", "isBasmala": false, "translation_en": "It is We who revive the dead; and We write down what they have forwarded, and their traces. We have tallied all things in a Clear Record.", "translation_id": "Sesungguhnya Kami menghidupkan orang-orang mati dan Kami menuliskan apa yang telah mereka kerjakan dan bekas-bekas yang mereka tinggalkan. Dan segala sesuatu Kami kumpulkan dalam Kitab Induk yang nyata (Lauh Mahfuzh).", "manzil": 5, "manzil_display": ""}], "441": [{"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 13, "text": "وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَـٰبَ ٱلۡقَرۡیَةِ إِذۡ جَاۤءَهَا ٱلۡمُرۡسَلُونَ ۝١٣", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "واضرب -أيها الرسول- لمشركي قومك الرادِّين لدعوتك مثلا يعتبرون به، وهو قصة أهل القرية، حين ذهب إليهم المرسلون، إذ أرسلنا إليهم رسولين لدعوتهم إلى الإيمان بالله وترك عبادة غيره، فكذَّب أهل القرية الرسولين، فعزَّزناهما وقويناهما برسول ثالث، فقال الثلاثة لأهل القرية: إنا إليكم -أيها القوم- مرسلون.", "isBasmala": false, "translation_en": "And cite for them the parable of the landlords of the town-when the messengers came to it.", "translation_id": "Dan buatlah bagi mereka suatu perumpamaan, yaitu penduduk suatu negeri ketika utusan-utusan datang kepada mereka.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 14, "text": "إِذۡ أَرۡسَلۡنَاۤ إِلَیۡهِمُ ٱثۡنَیۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثࣲ فَقَالُوۤا۟ إِنَّاۤ إِلَیۡكُم مُّرۡسَلُونَ ۝١٤", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "واضرب -أيها الرسول- لمشركي قومك الرادِّين لدعوتك مثلا يعتبرون به، وهو قصة أهل القرية، حين ذهب إليهم المرسلون، إذ أرسلنا إليهم رسولين لدعوتهم إلى الإيمان بالله وترك عبادة غيره، فكذَّب أهل القرية الرسولين، فعزَّزناهما وقويناهما برسول ثالث، فقال الثلاثة لأهل القرية: إنا إليكم -أيها القوم- مرسلون.", "isBasmala": false, "translation_en": "We sent them two messengers, but they denied them both, so We reinforced them with a third. They said, \"We are messengers to you.\"", "translation_id": "(yaitu) ketika Kami mengutus kepada mereka dua orang utusan, lalu mereka mendustakan keduanya; kemudian Kami kuatkan dengan (utusan) yang ketiga, maka ketiga utusan itu berkata: \"Sesungguhnya kami adalah orang-orang di utus kepadamu\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 15, "text": "قَالُوا۟ مَاۤ أَنتُمۡ إِلَّا بَشَرࣱ مِّثۡلُنَا وَمَاۤ أَنزَلَ ٱلرَّحۡمَـٰنُ مِن شَیۡءٍ إِنۡ أَنتُمۡ إِلَّا تَكۡذِبُونَ ۝١٥", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "قال أهل القرية للمرسلين: ما أنتم إلا أناس مثلنا، وما أنزل الرحمن شيئًا من الوحي، وما أنتم -أيها الرسل- إلا تكذبون.", "isBasmala": false, "translation_en": "They said, \"You are nothing but humans like us, and the Gracious did not send down anything; you are only lying.\"", "translation_id": "Mereka menjawab: \"Kamu tidak lain hanyalah manusia seperti kami dan Allah Yang Maha Pemurah tidak menurunkan sesuatupun, kamu tidak lain hanyalah pendusta belaka\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 16, "text": "قَالُوا۟ رَبُّنَا یَعۡلَمُ إِنَّاۤ إِلَیۡكُمۡ لَمُرۡسَلُونَ ۝١٦", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "قال المرسلون مؤكدين: ربُّنا الذي أرسلنا يعلم إنا إليكم لمرسلون، وما علينا إلا تبليغ الرسالة بوضوح، ولا نملك هدايتكم، فالهداية بيد الله وحده.", "isBasmala": false, "translation_en": "They said, \"Our Lord knows that we are messengers to you.", "translation_id": "Mereka berkata: \"Tuhan kami mengetahui bahwa sesungguhnya kami adalah orang yang diutus kepada kamu\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 17, "text": "وَمَا عَلَیۡنَاۤ إِلَّا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ ۝١٧", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "قال المرسلون مؤكدين: ربُّنا الذي أرسلنا يعلم إنا إليكم لمرسلون، وما علينا إلا تبليغ الرسالة بوضوح، ولا نملك هدايتكم، فالهداية بيد الله وحده.", "isBasmala": false, "translation_en": "And our only duty is clear communication.\"", "translation_id": "Dan kewajiban kami tidak lain hanyalah menyampaikan (perintah Allah) dengan jelas\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 18, "text": "قَالُوۤا۟ إِنَّا تَطَیَّرۡنَا بِكُمۡۖ لَىِٕن لَّمۡ تَنتَهُوا۟ لَنَرۡجُمَنَّكُمۡ وَلَیَمَسَّنَّكُم مِّنَّا عَذَابٌ أَلِیمࣱ ۝١٨", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "قال أهل القرية: إنا تَشَاءَمْنا بكم، لئن لم تكُفُّوا عن دعوتكم لنا لنقتلنكم رميًا بالحجارة، وليصيبنكم منَّا عذاب أليم موجع.", "isBasmala": false, "translation_en": "They said, \"We see an evil omen in you; if you do not give up, we will stone you, and a painful punishment from us will befall you.\"", "translation_id": "Mereka menjawab: \"Sesungguhnya kami bernasib malang karena kamu, sesungguhnya jika kamu tidak berhenti (menyeru kami), niscaya kami akan merajam kamu dan kamu pasti akan mendapat siksa yang pedih dari kami\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 19, "text": "قَالُوا۟ طَـٰۤىِٕرُكُم مَّعَكُمۡ أَىِٕن ذُكِّرۡتُمۚ بَلۡ أَنتُمۡ قَوۡمࣱ مُّسۡرِفُونَ ۝١٩", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "قال المرسلون: شؤمكم وأعمالكم من الشرك والشر معكم ومردودة عليكم، أإن وُعظتم بما فيه خيركم تشاءمتم وتوعدتمونا بالرجم والتعذيب؟ بل أنتم قوم عادتكم الإسراف في العصيان والتكذيب.", "isBasmala": false, "translation_en": "They said, \"Your evil omen is upon you. Is it because you were reminded? But you are an extravagant people.\"", "translation_id": "Utusan-utusan itu berkata: \"Kemalangan kamu adalah karena kamu sendiri. Apakah jika kamu diberi peringatan (kamu bernasib malang)? Sebenarnya kamu adalah kaum yang melampui batas\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 20, "text": "وَجَاۤءَ مِنۡ أَقۡصَا ٱلۡمَدِینَةِ رَجُلࣱ یَسۡعَىٰ قَالَ یَـٰقَوۡمِ ٱتَّبِعُوا۟ ٱلۡمُرۡسَلِینَ ۝٢٠", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "وجاء من مكان بعيد في المدينة رجل مسرع (وذلك حين علم أن أهل القرية هَمُّوا بقتل الرسل أو تعذيبهم)، قال: يا قوم اتبعوا المرسلين إليكم من الله، اتبعوا الذين لا يطلبون منكم أموالا على إبلاغ الرسالة، وهم مهتدون فيما يدعونكم إليه من عبادة الله وحده. وفي هذا بيان فضل مَن سعى إلى الأمر بالمعروف والنهي عن المنكر.", "isBasmala": false, "translation_en": "Then a man came running from the remotest part of the city. He said, \"O my people, follow the messengers.", "translation_id": "Dan datanglah dari ujung kota, seorang laki-laki dengan bergegas-gegas ia berkata: \"Hai kaumku, ikutilah utusan-utusan itu\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 21, "text": "ٱتَّبِعُوا۟ مَن لَّا یَسۡـَٔلُكُمۡ أَجۡرࣰا وَهُم مُّهۡتَدُونَ ۝٢١", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "وجاء من مكان بعيد في المدينة رجل مسرع (وذلك حين علم أن أهل القرية هَمُّوا بقتل الرسل أو تعذيبهم)، قال: يا قوم اتبعوا المرسلين إليكم من الله، اتبعوا الذين لا يطلبون منكم أموالا على إبلاغ الرسالة، وهم مهتدون فيما يدعونكم إليه من عبادة الله وحده. وفي هذا بيان فضل مَن سعى إلى الأمر بالمعروف والنهي عن المنكر.", "isBasmala": false, "translation_en": "Follow those who ask you of no wage, and are themselves guided.", "translation_id": "Ikutilah orang yang tiada minta balasan kepadamu; dan mereka adalah orang-orang yang mendapat petunjuk.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 22, "text": "وَمَا لِیَ لَاۤ أَعۡبُدُ ٱلَّذِی فَطَرَنِی وَإِلَیۡهِ تُرۡجَعُونَ ۝٢٢", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "وأيُّ شيء يمنعني مِن أن أعبد الله الذي خلقني، وإليه تصيرون جميعًا؟", "isBasmala": false, "translation_en": "\"And why should I not worship Him Who created me, and to Whom you will be returned?", "translation_id": "Mengapa aku tidak menyembah (Tuhan) yang telah menciptakanku dan yang hanya kepada-Nya-lah kamu (semua) akan dikembalikan?", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 23, "text": "ءَأَتَّخِذُ مِن دُونِهِۦۤ ءَالِهَةً إِن یُرِدۡنِ ٱلرَّحۡمَـٰنُ بِضُرࣲّ لَّا تُغۡنِ عَنِّی شَفَـٰعَتُهُمۡ شَیۡـࣰٔا وَلَا یُنقِذُونِ ۝٢٣", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "أأعبد من دون الله آلهة أخرى لا تملك من الأمر شيئًا، إن يردني الرحمن بسوء فهذه الآلهة لا تملك دفع ذلك ولا منعه، ولا تستطيع إنقاذي مما أنا فيه؟ إني إن فعلت ذلك لفي خطأ واضح ظاهر. إني آمنت بربكم فاستمعوا إلى ما قُلْته لكم، وأطيعوني بالإيمان. فلما قال ذلك وثب إليه قومه وقتلوه، فأدخله الله الجنة.", "isBasmala": false, "translation_en": "Shall I take other gods instead of Him? If the Merciful desires harm for me, their intercession will not avail me at all, nor will they save me.", "translation_id": "Mengapa aku akan menyembah tuhan-tuhan selain-Nya jika (Allah) Yang Maha Pemurah menghendaki kemudharatan terhadapku, niscaya syafa'at mereka tidak memberi manfaat sedikitpun bagi diriku dan mereka tidak (pula) dapat menyelamatkanku?", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 24, "text": "إِنِّیۤ إِذࣰا لَّفِی ضَلَـٰلࣲ مُّبِینٍ ۝٢٤", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "أأعبد من دون الله آلهة أخرى لا تملك من الأمر شيئًا، إن يردني الرحمن بسوء فهذه الآلهة لا تملك دفع ذلك ولا منعه، ولا تستطيع إنقاذي مما أنا فيه؟ إني إن فعلت ذلك لفي خطأ واضح ظاهر. إني آمنت بربكم فاستمعوا إلى ما قُلْته لكم، وأطيعوني بالإيمان. فلما قال ذلك وثب إليه قومه وقتلوه، فأدخله الله الجنة.", "isBasmala": false, "translation_en": "In that case, I would be completely lost.", "translation_id": "Sesungguhnya aku kalau begitu pasti berada dalam kesesatan yang nyata.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 25, "text": "إِنِّیۤ ءَامَنتُ بِرَبِّكُمۡ فَٱسۡمَعُونِ ۝٢٥", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "أأعبد من دون الله آلهة أخرى لا تملك من الأمر شيئًا، إن يردني الرحمن بسوء فهذه الآلهة لا تملك دفع ذلك ولا منعه، ولا تستطيع إنقاذي مما أنا فيه؟ إني إن فعلت ذلك لفي خطأ واضح ظاهر. إني آمنت بربكم فاستمعوا إلى ما قُلْته لكم، وأطيعوني بالإيمان. فلما قال ذلك وثب إليه قومه وقتلوه، فأدخله الله الجنة.", "isBasmala": false, "translation_en": "I have believed in your Lord, so listen to me.\"", "translation_id": "Sesungguhnya aku telah beriman kepada Tuhanmu; maka dengarkanlah (pengakuan keimanan)ku.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 26, "text": "قِیلَ ٱدۡخُلِ ٱلۡجَنَّةَۖ قَالَ یَـٰلَیۡتَ قَوۡمِی یَعۡلَمُونَ ۝٢٦", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "قيل له بعد قتله: ادخل الجنة، إكرامًا له.", "isBasmala": false, "translation_en": "It was said, \"Enter Paradise.\" He said, \"If only my people knew.", "translation_id": "Dikatakan (kepadanya): \"Masuklah ke surga\". Ia berkata: \"Alangkah baiknya sekiranya kamumku mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 27, "text": "بِمَا غَفَرَ لِی رَبِّی وَجَعَلَنِی مِنَ ٱلۡمُكۡرَمِینَ ۝٢٧", "juz": 22, "hizb": "(*¾ ح 44*)", "tafsir": "قال وهو في النعيم والكرامة: يا ليت قومي يعلمون بغفران ربي لي وإكرامه إياي؛ بسبب إيماني بالله وصبري على طاعته، واتباع رسله حتى قُتِلت، فيؤمنوا بالله فيدخلوا الجنة مثلي.", "isBasmala": false, "translation_en": "How my Lord has forgiven me, and made me one of the honored.\"", "translation_id": "Apa yang menyebabkan Tuhanku memberi ampun kepadaku dan menjadikan aku termasuk orang-orang yang dimuliakan\".", "manzil": 5, "manzil_display": ""}], "442": [{"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 28, "text": "۞ وَمَاۤ أَنزَلۡنَا عَلَىٰ قَوۡمِهِۦ مِنۢ بَعۡدِهِۦ مِن جُندࣲ مِّنَ ٱلسَّمَاۤءِ وَمَا كُنَّا مُنزِلِینَ ۝٢٨", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وما احتاج الأمر إلى إنزال جند من السماء لعذابهم بعد قتلهم الرجل الناصح لهم وتكذيبهم رسلهم، فهم أضعف من ذلك وأهون، وما كنا منزلين الملائكة على الأمم إذا أهلكناهم، بل نبعث عليهم عذابًا يدمرهم.", "isBasmala": false, "translation_en": "After him, We sent down no hosts from heaven to his people; nor would We ever send any down.", "translation_id": "Dan kami tidak menurunkan kepada kaumnya sesudah dia (meninggal) suatu pasukanpun dari langit dan tidak layak Kami menurunkannya.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 29, "text": "إِن كَانَتۡ إِلَّا صَیۡحَةࣰ وَ ٰحِدَةࣰ فَإِذَا هُمۡ خَـٰمِدُونَ ۝٢٩", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ما كان هلاكهم إلا بصيحة واحدة، فإذا هم ميتون لم تَبْقَ منهم باقية.", "isBasmala": false, "translation_en": "It was just one Cry, and they were stilled.", "translation_id": "Tidak ada siksaan atas mereka melainkan satu teriakan suara saja; maka tiba-tiba mereka semuanya mati.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 30, "text": "یَـٰحَسۡرَةً عَلَى ٱلۡعِبَادِۚ مَا یَأۡتِیهِم مِّن رَّسُولٍ إِلَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٣٠", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "يا حسرة العباد وندامتهم يوم القيامة إذا عاينوا العذاب، ما يأتيهم من رسول من الله تعالى إلا كانوا به يستهزئون ويسخرون.", "isBasmala": false, "translation_en": "Alas for the servants. No messenger ever came to them, but they ridiculed him.", "translation_id": "Alangkah besarnya penyesalan terhadap hamba-hamba itu, tiada datang seorang rasulpun kepada mereka melainkan mereka selalu memperolok-olokkannya.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 31, "text": "أَلَمۡ یَرَوۡا۟ كَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّنَ ٱلۡقُرُونِ أَنَّهُمۡ إِلَیۡهِمۡ لَا یَرۡجِعُونَ ۝٣١", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ألم ير هؤلاء المستهزئون ويعتبروا بمن قبلهم من القرون التي أهلكناها أنهم لا يرجعون إلى هذه الدينا؟", "isBasmala": false, "translation_en": "Have they not considered how many generations We destroyed before them; and that unto them they will not return?", "translation_id": "Tidakkah mereka mengetahui berapa banyaknya umat-umat sebelum mereka yang telah Kami binasakan, bahwasanya orang-orang (yang telah Kami binasakan) itu tiada kembali kepada mereka.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 32, "text": "وَإِن كُلࣱّ لَّمَّا جَمِیعࣱ لَّدَیۡنَا مُحۡضَرُونَ ۝٣٢", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وما كل هذه القرون التي أهلكناها وغيرهم، إلا محضرون جميعًا عندنا يوم القيامة للحساب والجزاء.", "isBasmala": false, "translation_en": "All of them, every single one of them, will be arraigned before Us.", "translation_id": "Dan setiap mereka semuanya akan dikumpulkan lagi kepada Kami.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 33, "text": "وَءَایَةࣱ لَّهُمُ ٱلۡأَرۡضُ ٱلۡمَیۡتَةُ أَحۡیَیۡنَـٰهَا وَأَخۡرَجۡنَا مِنۡهَا حَبࣰّا فَمِنۡهُ یَأۡكُلُونَ ۝٣٣", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ودلالة لهؤلاء المشركين على قدرة الله على البعث والنشور: هذه الأرض الميتة التي لا نبات فيها، أحييناها بإنزال الماء، وأخرجنا منها أنواع النبات مما يأكل الناس والأنعام، ومن أحيا الأرض بالنبات أحيا الخلق بعد الممات.", "isBasmala": false, "translation_en": "And there is a sign for them in the dead land: We give it life, and produce from it grains from which they eat.", "translation_id": "Dan suatu tanda (kekuasaan Allah yang besar) bagi mereka adalah bumi yang mati. Kami hidupkan bumi itu dan Kami keluarkan dari padanya biji-bijian, maka daripadanya mereka makan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 34, "text": "وَجَعَلۡنَا فِیهَا جَنَّـٰتࣲ مِّن نَّخِیلࣲ وَأَعۡنَـٰبࣲ وَفَجَّرۡنَا فِیهَا مِنَ ٱلۡعُیُونِ ۝٣٤", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وجعلنا في هذه الأرض بساتين من نخيل وأعناب، وفجَّرنا فيها من عيون المياه ما يسقيها.", "isBasmala": false, "translation_en": "And We place in it gardens of palm-trees and vines, and cause springs to gush out of it.", "translation_id": "Dan Kami jadikan padanya kebun-kebun kurma dan anggur dan Kami pancarkan padanya beberapa mata air,", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 35, "text": "لِیَأۡكُلُوا۟ مِن ثَمَرِهِۦ وَمَا عَمِلَتۡهُ أَیۡدِیهِمۡۚ أَفَلَا یَشۡكُرُونَ ۝٣٥", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "كل ذلك؛ ليأكل العباد من ثمره، وما ذلك إلا من رحمة الله بهم لا بسعيهم ولا بكدِّهم، ولا بحولهم وبقوتهم، أفلا يشكرون الله على ما أنعم به عليهم من هذه النعم التي لا تعدُّ ولا تحصى؟", "isBasmala": false, "translation_en": "That they may eat from its fruits, although their hands did not make it. Will they not be appreciative?", "translation_id": "supaya mereka dapat makan dari buahnya, dan dari apa yang diusahakan oleh tangan mereka. Maka mengapakah mereka tidak bersyukur?", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 36, "text": "سُبۡحَـٰنَ ٱلَّذِی خَلَقَ ٱلۡأَزۡوَ ٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا یَعۡلَمُونَ ۝٣٦", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "تنزَّه الله العظيم الذي خلق الأصناف جميعها من أنواع نبات الأرض، ومن أنفسهم ذكورًا وإناثًا، ومما لا يعلمون من مخلوقات الله الأخرى. قد انفرد سبحانه بالخلق، فلا ينبغي أن يُشْرَك به غيره.", "isBasmala": false, "translation_en": "Glory be to Him who created all the pairs; of what the earth produces, and of their own selves, and of what they do not know.", "translation_id": "Maha Suci Tuhan yang telah menciptakan pasangan-pasangan semuanya, baik dari apa yang ditumbuhkan oleh bumi dan dari diri mereka maupun dari apa yang tidak mereka ketahui.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 37, "text": "وَءَایَةࣱ لَّهُمُ ٱلَّیۡلُ نَسۡلَخُ مِنۡهُ ٱلنَّهَارَ فَإِذَا هُم مُّظۡلِمُونَ ۝٣٧", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وعلامة لهم دالة على توحيد الله وكمال قدرته: هذا الليل ننزع منه النهار، فإذا الناس مظلمون.", "isBasmala": false, "translation_en": "Another sign for them is the night: We strip the day out of it-and they are in darkness.", "translation_id": "Dan suatu tanda (kekuasaan Allah yang besar) bagi mereka adalah malam; Kami tanggalkan siang dari malam itu, maka dengan serta merta mereka berada dalam kegelapan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 38, "text": "وَٱلشَّمۡسُ تَجۡرِی لِمُسۡتَقَرࣲّ لَّهَاۚ ذَ ٰلِكَ تَقۡدِیرُ ٱلۡعَزِیزِ ٱلۡعَلِیمِ ۝٣٨", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وآية لهم الشمس تجري لمستقر لها، قدَّره الله لها لا تتعداه ولا تقصر عنه، ذلك تقدير العزيز الذي لا يغالَب، العليم الذي لا يغيب عن علمه شيء.", "isBasmala": false, "translation_en": "And the sun runs towards its destination. Such is the design of the Almighty, the All-Knowing.", "translation_id": "dan matahari berjalan ditempat peredarannya. Demikianlah ketetapan Yang Maha Perkasa lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 39, "text": "وَٱلۡقَمَرَ قَدَّرۡنَـٰهُ مَنَازِلَ حَتَّىٰ عَادَ كَٱلۡعُرۡجُونِ ٱلۡقَدِیمِ ۝٣٩", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "والقمرَ آية في خلقه، قدَّرناه منازل كل ليلة، يبدأ هلالا ضئيلا حتى يكمل قمرًا مستديرًا، ثم يرجع ضئيلا مثل عِذْق النخلة المتقوس في الرقة والانحناء والصفرة؛ لقدمه ويُبْسه.", "isBasmala": false, "translation_en": "And the moon: We have disposed it in phases, until it returns like the old twig.", "translation_id": "Dan telah Kami tetapkan bagi bulan manzilah-manzilah, sehingga (setelah dia sampai ke manzilah yang terakhir) kembalilah dia sebagai bentuk tandan yang tua.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 40, "text": "لَا ٱلشَّمۡسُ یَنۢبَغِی لَهَاۤ أَن تُدۡرِكَ ٱلۡقَمَرَ وَلَا ٱلَّیۡلُ سَابِقُ ٱلنَّهَارِۚ وَكُلࣱّ فِی فَلَكࣲ یَسۡبَحُونَ ۝٤٠", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "لكل من الشمس والقمر والليل والنهار وقت قدَّره الله له لا يتعدَّاه، فلا يمكن للشمس أن تلحق القمر فتمحو نوره، أو تغير مجراه، ولا يمكن للَّيل أن يسبق النهار، فيدخل عليه قبل انقضاء وقته، وكل من الشمس والقمر والكواكب في فلك يَجْرون.", "isBasmala": false, "translation_en": "The sun is not to overtake the moon, nor is the night to outpace the day. Each floats in an orbit.", "translation_id": "Tidaklah mungkin bagi matahari mendapatkan bulan dan malampun tidak dapat mendahului siang. Dan masing-masing beredar pada garis edarnya.", "manzil": 5, "manzil_display": ""}], "443": [{"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 41, "text": "وَءَایَةࣱ لَّهُمۡ أَنَّا حَمَلۡنَا ذُرِّیَّتَهُمۡ فِی ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ۝٤١", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ودليل لهم وبرهان على أن الله وحده المستحق للعبادة، المنعم بالنعم، أنَّا حملنا مَن نجا مِن ولد آدم في سفينة نوح المملوءة بأجناس المخلوقات؛ لاستمرار الحياة بعد الطوفان.", "isBasmala": false, "translation_en": "Another sign for them is that We carried their offspring in the laden Ark.", "translation_id": "Dan suatu tanda (kebesaran Allah yang besar) bagi mereka adalah bahwa Kami angkut keturunan mereka dalam bahtera yang penuh muatan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 42, "text": "وَخَلَقۡنَا لَهُم مِّن مِّثۡلِهِۦ مَا یَرۡكَبُونَ ۝٤٢", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وخلقنا لهؤلاء المشركين وغيرهم مثل سفينة نوح من السفن وغيرها من المراكب التي يركبونها وتبلِّغهم أوطانهم.", "isBasmala": false, "translation_en": "And We created for them the like of it, in which they ride.", "translation_id": "dan Kami ciptakan untuk mereka yang akan mereka kendarai seperti bahtera itu.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 43, "text": "وَإِن نَّشَأۡ نُغۡرِقۡهُمۡ فَلَا صَرِیخَ لَهُمۡ وَلَا هُمۡ یُنقَذُونَ ۝٤٣", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وإن نشأ نغرقهم، فلا يجدون مغيثًا لهم مِن غرقهم، ولا هم يخلصون من الغرق.", "isBasmala": false, "translation_en": "If We will, We can drown them-with no screaming to be heard from them, nor will they be saved.", "translation_id": "Dan jika Kami menghendaki niscaya Kami tenggelamkan mereka, maka tiadalah bagi mereka penolong dan tidak pula mereka diselamatkan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 44, "text": "إِلَّا رَحۡمَةࣰ مِّنَّا وَمَتَـٰعًا إِلَىٰ حِینࣲ ۝٤٤", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "إلا أن نرحمهم فننجيهم ونمتعهم إلى أجل؛ لعلهم يرجعون ويستدركون ما فرَّطوا فيه.", "isBasmala": false, "translation_en": "Except by a mercy from Us, and enjoyment for a while.", "translation_id": "Tetapi (Kami selamatkan mereka) karena rahmat yang besar dari Kami dan untuk memberikan kesenangan hidup sampai kepada suatu ketika.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 45, "text": "وَإِذَا قِیلَ لَهُمُ ٱتَّقُوا۟ مَا بَیۡنَ أَیۡدِیكُمۡ وَمَا خَلۡفَكُمۡ لَعَلَّكُمۡ تُرۡحَمُونَ ۝٤٥", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وإذا قيل للمشركين: احذروا أمر الآخرة وأهوالها وأحوال الدنيا وعقابها؛ رجاء رحمة الله لكم، أعرضوا، ولم يجيبوا إلى ذلك.", "isBasmala": false, "translation_en": "Yet when it is said to them, \"Beware of what lies before you, and what lies behind you, that you may receive mercy.\"", "translation_id": "Dan apabila dikatakan kepada mereka: \"Takutlah kamu akan siksa yang dihadapanmu dan siksa yang akan datang supaya kamu mendapat rahmat\", (niscaya mereka berpaling).", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 46, "text": "وَمَا تَأۡتِیهِم مِّنۡ ءَایَةࣲ مِّنۡ ءَایَـٰتِ رَبِّهِمۡ إِلَّا كَانُوا۟ عَنۡهَا مُعۡرِضِینَ ۝٤٦", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وما تجيء هؤلاء المشركين من علامة واضحة من عند ربهم؛ لتهديهم للحق، وتبيِّن لهم صدق الرسول، إلا أعرضوا عنها، ولم ينتفعوا بها.", "isBasmala": false, "translation_en": "Yet never came to them a sign of their Lord's signs, but they turned away from it.", "translation_id": "Dan sekali-kali tiada datang kepada mereka suatu tanda dari tanda tanda kekuasaan Tuhan mereka, melainkan mereka selalu berpaling daripadanya.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 47, "text": "وَإِذَا قِیلَ لَهُمۡ أَنفِقُوا۟ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالَ ٱلَّذِینَ كَفَرُوا۟ لِلَّذِینَ ءَامَنُوۤا۟ أَنُطۡعِمُ مَن لَّوۡ یَشَاۤءُ ٱللَّهُ أَطۡعَمَهُۥۤ إِنۡ أَنتُمۡ إِلَّا فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٤٧", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "وإذا قيل للكافرين: أنفقوا من الرزق الذي مَنَّ به الله عليكم، قالوا للمؤمنين مُحْتجِّين: أنطعم من لو شاء الله أطعمه؟ ما أنتم -أيها المؤمنون- إلا في بُعْدٍ واضح عن الحق، إذ تأمروننا بذلك.", "isBasmala": false, "translation_en": "And when it is said to them, \"Spend of what God has provided for you,\" those who disbelieve say to those who believe, \"Shall we feed someone whom God could feed, if He so willed? You must be deeply misguided.\"", "translation_id": "Dan apabila dikatakakan kepada mereka: \"Nafkahkanlah sebahagian dari reski yang diberikan Allah kepadamu\", maka orang-orang yang kafir itu berkata kepada orang-orang yang beriman: \"Apakah kami akan memberi makan kepada orang-orang yang jika Allah menghendaki tentulah Dia akan memberinya makan, tiadalah kamu melainkan dalam kesesatan yang nyata\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 48, "text": "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ ۝٤٨", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ويقول هؤلاء الكفار على وجه التكذيب والاستعجال: متى يكون البعث إن كنتم صادقين فيما تقولونه عنه؟", "isBasmala": false, "translation_en": "And they say, \"When will this promise be, if you are truthful?\"", "translation_id": "Dan mereka berkata: \"Bilakah (terjadinya) janji ini (hari berbangkit) jika kamu adalah orang-orang yang benar?\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 49, "text": "مَا یَنظُرُونَ إِلَّا صَیۡحَةࣰ وَ ٰحِدَةࣰ تَأۡخُذُهُمۡ وَهُمۡ یَخِصِّمُونَ ۝٤٩", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ما ينتظر هؤلاء المشركون الذين يستعجلون بوعيد الله إياهم إلا نفخة الفَزَع عند قيام الساعة، تأخذهم فجأة، وهم يختصمون في شؤون حياتهم.", "isBasmala": false, "translation_en": "All they can expect is a single blast, which will seize them while they feud.", "translation_id": "Mereka tidak menunggu melainkan satu teriakan saja yang akan membinasakan mereka ketika mereka sedang bertengkar.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 50, "text": "فَلَا یَسۡتَطِیعُونَ تَوۡصِیَةࣰ وَلَاۤ إِلَىٰۤ أَهۡلِهِمۡ یَرۡجِعُونَ ۝٥٠", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "فلا يستطيع هؤلاء المشركون عند النفخ في \"القرن\" أن يوصوا أحدًا بشيء، ولا يستطيعون الرجوع إلى أهلهم، بل يموتون في أسواقهم ومواضعهم.", "isBasmala": false, "translation_en": "They will not be able to make a will, nor will they return to their families.", "translation_id": "lalu mereka tidak kuasa membuat suatu wasiatpun dan tidak (pula) dapat kembali kepada keluarganya.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 51, "text": "وَنُفِخَ فِی ٱلصُّورِ فَإِذَا هُم مِّنَ ٱلۡأَجۡدَاثِ إِلَىٰ رَبِّهِمۡ یَنسِلُونَ ۝٥١", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ونُفِخ في \"القرن\" النفخةُ الثانية، فتُرَدُّ أرواحهم إلى أجسادهم، فإذا هم من قبورهم يخرجون إلى ربهم سراعًا.", "isBasmala": false, "translation_en": "The Trumpet will be blown, then behold, they will rush from the tombs to their Lord.", "translation_id": "Dan ditiuplah sangkalala, maka tiba-tiba mereka keluar dengan segera dari kuburnya (menuju) kepada Tuhan mereka.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 52, "text": "قَالُوا۟ یَـٰوَیۡلَنَا مَنۢ بَعَثَنَا مِن مَّرۡقَدِنَاۜۗ هَـٰذَا مَا وَعَدَ ٱلرَّحۡمَـٰنُ وَصَدَقَ ٱلۡمُرۡسَلُونَ ۝٥٢", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "قال المكذبون بالبعث نادمين: يا هلاكنا مَن أخرجنا مِن قبورنا؟ فيجابون ويقال لهم: هذا ما وعد به الرحمن، وأخبر عنه المرسلون الصادقون.", "isBasmala": false, "translation_en": "They will say, \"Woe to us! Who resurrected us from our resting-place?\" This is what the Most Gracious had promised, and the messengers have spoken the truth.\"", "translation_id": "Mereka berkata: \"Aduhai celakalah kami! Siapakah yang membangkitkan kami dari tempat-tidur kami (kubur)?\". Inilah yang dijanjikan (Tuhan) Yang Maha Pemurah dan benarlah Rasul-rasul(Nya).", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 53, "text": "إِن كَانَتۡ إِلَّا صَیۡحَةࣰ وَ ٰحِدَةࣰ فَإِذَا هُمۡ جَمِیعࣱ لَّدَیۡنَا مُحۡضَرُونَ ۝٥٣", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ما كان البعث من القبور إلا نتيجة نفخة واحدة في \"القرن\"، فإذا جميع الخلق لدينا ماثلون للحساب والجزاء.", "isBasmala": false, "translation_en": "It will be but a single scream; and behold, they will all be brought before Us.", "translation_id": "Tidak adalah teriakan itu selain sekali teriakan saja, maka tiba-tiba mereka semua dikumpulkan kepada Kami.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 54, "text": "فَٱلۡیَوۡمَ لَا تُظۡلَمُ نَفۡسࣱ شَیۡـࣰٔا وَلَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ ۝٥٤", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "في ذلك اليوم يتم الحساب بالعدل، فلا تُظْلم نفس شيئًا بنقص حسناتها أو زيادة سيئاتها، ولا تُجْزون إلا بما كنتم تعملونه في الدنيا.", "isBasmala": false, "translation_en": "On that Day, no soul will be wronged in the least, and you will be recompensed only for what you used to do.", "translation_id": "Maka pada hari itu seseorang tidak akan dirugikan sedikitpun dan kamu tidak dibalasi, kecuali dengan apa yang telah kamu kerjakan.", "manzil": 5, "manzil_display": ""}], "444": [{"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 55, "text": "إِنَّ أَصۡحَـٰبَ ٱلۡجَنَّةِ ٱلۡیَوۡمَ فِی شُغُلࣲ فَـٰكِهُونَ ۝٥٥", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "إن أهل الجنة في ذلك اليوم مشغولون عن غيرهم بأنواع النعيم التي يتفكهون بها.", "isBasmala": false, "translation_en": "The inhabitants of Paradise, on that Day, will be happily busy.", "translation_id": "Sesungguhnya penghuni surga pada hari itu bersenang-senang dalam kesibukan (mereka).", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 56, "text": "هُمۡ وَأَزۡوَ ٰجُهُمۡ فِی ظِلَـٰلٍ عَلَى ٱلۡأَرَاۤىِٕكِ مُتَّكِـُٔونَ ۝٥٦", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "هم وأزواجهم متنعمون بالجلوس على الأسرَّة المزيَّنة، تحت الظلال الوارفة.", "isBasmala": false, "translation_en": "They and their spouses, in shades, reclining on couches.", "translation_id": "Mereka dan isteri-isteri mereka berada dalam tempat yang teduh, bertelekan di atas dipan-dipan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 57, "text": "لَهُمۡ فِیهَا فَـٰكِهَةࣱ وَلَهُم مَّا یَدَّعُونَ ۝٥٧", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "لهم في الجنة أنواع الفواكه اللذيذة، ولهم كل ما يطلبون من أنواع النعيم.", "isBasmala": false, "translation_en": "They will have therein fruits. They will have whatever they call for.", "translation_id": "Di surga itu mereka memperoleh buah-buahan dan memperoleh apa yang mereka minta.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 58, "text": "سَلَـٰمࣱ قَوۡلࣰا مِّن رَّبࣲّ رَّحِیمࣲ ۝٥٨", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ولهم نعيم آخر أكبر حين يكلمهم ربهم، الرحيم بهم بالسلام عليهم. وعند ذلك تحصل لهم السلامة التامة من جميع الوجوه.", "isBasmala": false, "translation_en": "Peace-a saying from a Most Merciful Lord.", "translation_id": "(Kepada mereka dikatakan): \"Salam\", sebagai ucapan selamat dari Tuhan Yang Maha Penyayang.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 59, "text": "وَٱمۡتَـٰزُوا۟ ٱلۡیَوۡمَ أَیُّهَا ٱلۡمُجۡرِمُونَ ۝٥٩", "juz": 23, "hizb": "(* ح 45*)", "tafsir": "ويقال للكفار في ذلك اليوم: تميَّزوا عن المؤمنين، وانفصلوا عنهم.", "isBasmala": false, "translation_en": "But step aside today, you criminals.", "translation_id": "Dan (dikatakan kepada orang-orang kafir): \"Berpisahlah kamu (dari orang-orang mukmin) pada hari ini, hai orang-orang yang berbuat jahat.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 60, "text": "۞ أَلَمۡ أَعۡهَدۡ إِلَیۡكُمۡ یَـٰبَنِیۤ ءَادَمَ أَن لَّا تَعۡبُدُوا۟ ٱلشَّیۡطَـٰنَۖ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینࣱ ۝٦٠", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "ويقول الله لهم توبيخًا وتذكيرًا: ألم أوصكم على ألسنة رسلي أن لا تعبدوا الشيطان ولا تطيعوه؟ إنه لكم عدو ظاهر العداوة.", "isBasmala": false, "translation_en": "Did I not covenant with you, O Children of Adam, that you shall not serve the devil? That he is your sworn enemy?", "translation_id": "Bukankah Aku telah memerintahkan kepadamu hai Bani Adam supaya kamu tidak menyembah syaitan? Sesungguhnya syaitan itu adalah musuh yang nyata bagi kamu\",", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 61, "text": "وَأَنِ ٱعۡبُدُونِیۚ هَـٰذَا صِرَ ٰطࣱ مُّسۡتَقِیمࣱ ۝٦١", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وأمرتكم بعبادتي وحدي، فعبادتي وطاعتي ومعصية الشيطان هي الدين القويم الموصل لمرضاتي وجنَّاتي.", "isBasmala": false, "translation_en": "And that you shall serve Me? This is a straight path.", "translation_id": "dan hendaklah kamu menyembah-Ku. Inilah jalan yang lurus.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 62, "text": "وَلَقَدۡ أَضَلَّ مِنكُمۡ جِبِلࣰّا كَثِیرًاۖ أَفَلَمۡ تَكُونُوا۟ تَعۡقِلُونَ ۝٦٢", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "ولقد أضلَّ الشيطان عن الحق منكم خلقًا كثيرًا، أفما كان لكم عقل -أيها المشركون- ينهاكم عن اتباعه؟", "isBasmala": false, "translation_en": "He has misled a great multitude of you. Did you not understand?", "translation_id": "Sesungguhnya syaitan itu telah menyesatkan sebahagian besar diantaramu, Maka apakah kamu tidak memikirkan?.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 63, "text": "هَـٰذِهِۦ جَهَنَّمُ ٱلَّتِی كُنتُمۡ تُوعَدُونَ ۝٦٣", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "هذه جهنم التي كنتم توعدون بها في الدنيا على كفركم بالله وتكذيبكم رسله.", "isBasmala": false, "translation_en": "This is Hellfire, which you were promised.", "translation_id": "Inilah Jahannam yang dahulu kamu diancam (dengannya).", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 64, "text": "ٱصۡلَوۡهَا ٱلۡیَوۡمَ بِمَا كُنتُمۡ تَكۡفُرُونَ ۝٦٤", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "ادخلوها اليوم وقاسوا حرَّها؛ بسبب كفركم.", "isBasmala": false, "translation_en": "Roast in it today, because you persistently disbelieved.", "translation_id": "Masuklah ke dalamnya pada hari ini disebabkan kamu dahulu mengingkarinya.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 65, "text": "ٱلۡیَوۡمَ نَخۡتِمُ عَلَىٰۤ أَفۡوَ ٰهِهِمۡ وَتُكَلِّمُنَاۤ أَیۡدِیهِمۡ وَتَشۡهَدُ أَرۡجُلُهُم بِمَا كَانُوا۟ یَكۡسِبُونَ ۝٦٥", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "اليوم نطبع على أفواه المشركين فلا ينطقون، وتُكلِّمنا أيديهم بما بطشت به، وتشهد أرجلهم بما سعت إليه في الدنيا، وكسبت من الآثام.", "isBasmala": false, "translation_en": "On this Day, We will seal their mouths, and their hands will speak to Us, and their feet will testify to everything they had done.", "translation_id": "Pada hari ini Kami tutup mulut mereka; dan berkatalah kepada Kami tangan mereka dan memberi kesaksianlah kaki mereka terhadap apa yang dahulu mereka usahakan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 66, "text": "وَلَوۡ نَشَاۤءُ لَطَمَسۡنَا عَلَىٰۤ أَعۡیُنِهِمۡ فَٱسۡتَبَقُوا۟ ٱلصِّرَ ٰطَ فَأَنَّىٰ یُبۡصِرُونَ ۝٦٦", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "ولو نشاء لطمسنا على أعينهم بأن نُذْهب أبصارهم، كما ختمنا على أفواههم، فبادَروا إلى الصراط ليجوزوه، فكيف يتحقق لهم ذلك وقد طُمِست أبصارهم؟", "isBasmala": false, "translation_en": "If We will, We can blind their eyes as they rush towards the path-but how will they see?", "translation_id": "Dan jikalau Kami menghendaki pastilah Kami hapuskan penglihatan mata mereka; lalu mereka berlomba-lomba (mencari) jalan, Maka betapakah mereka dapat melihat(nya).", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 67, "text": "وَلَوۡ نَشَاۤءُ لَمَسَخۡنَـٰهُمۡ عَلَىٰ مَكَانَتِهِمۡ فَمَا ٱسۡتَطَـٰعُوا۟ مُضِیࣰّا وَلَا یَرۡجِعُونَ ۝٦٧", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "ولو شئنا لَغَيَّرنا خلقهم وأقعدناهم في أماكنهم، فلا يستطيعون أن يَمْضوا أمامهم، ولا يرجعوا وراءهم.", "isBasmala": false, "translation_en": "And if We will, We can cripple them in their place; so they can neither move forward, nor go back.", "translation_id": "Dan jikalau Kami menghendaki pastilah Kami ubah mereka di tempat mereka berada; maka mereka tidak sanggup berjalan lagi dan tidak (pula) sanggup kembali.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 68, "text": "وَمَن نُّعَمِّرۡهُ نُنَكِّسۡهُ فِی ٱلۡخَلۡقِۚ أَفَلَا یَعۡقِلُونَ ۝٦٨", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "ومن نُطِلْ عمره حتى يهرم نُعِدْه إلى الحالة التي ابتدأ منها حالة ضعف العقل وضعف الجسد، أفلا يعقلون أنَّ مَن فعل مثل هذا بهم قادر على بعثهم؟", "isBasmala": false, "translation_en": "Whomever We grant old age, We reverse his development. Do they not understand?", "translation_id": "Dan barangsiapa yang Kami panjangkan umurnya niscaya Kami kembalikan dia kepada kejadian(nya). Maka apakah mereka tidak memikirkan?", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 69, "text": "وَمَا عَلَّمۡنَـٰهُ ٱلشِّعۡرَ وَمَا یَنۢبَغِی لَهُۥۤۚ إِنۡ هُوَ إِلَّا ذِكۡرࣱ وَقُرۡءَانࣱ مُّبِینࣱ ۝٦٩", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وما علَّمنا رسولنا محمدًا الشعر، وما ينبغي له أن يكون شاعرًا، ما هذا الذي جاء به إلا ذكر يتذكر به أولو الألباب، وقرآن بيِّن الدلالة على الحق والباطل، واضحة أحكامه وحِكَمه ومواعظه؛ لينذر مَن كان حيَّ القلب مستنير البصيرة، ويحق العذاب على الكافرين بالله؛ لأنهم قامت عليهم بالقرآن حجة الله البالغة.", "isBasmala": false, "translation_en": "We did not teach him poetry, nor is it proper for him. It is only a reminder, and a Clear Quran.", "translation_id": "Dan Kami tidak mengajarkan syair kepadanya (Muhammad) dan bersyair itu tidaklah layak baginya. Al Quran itu tidak lain hanyalah pelajaran dan kitab yang memberi penerangan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 70, "text": "لِّیُنذِرَ مَن كَانَ حَیࣰّا وَیَحِقَّ ٱلۡقَوۡلُ عَلَى ٱلۡكَـٰفِرِینَ ۝٧٠", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وما علَّمنا رسولنا محمدًا الشعر، وما ينبغي له أن يكون شاعرًا، ما هذا الذي جاء به إلا ذكر يتذكر به أولو الألباب، وقرآن بيِّن الدلالة على الحق والباطل، واضحة أحكامه وحِكَمه ومواعظه؛ لينذر مَن كان حيَّ القلب مستنير البصيرة، ويحق العذاب على الكافرين بالله؛ لأنهم قامت عليهم بالقرآن حجة الله البالغة.", "isBasmala": false, "translation_en": "That he may warn whoever is alive, and prove the Word against the faithless.", "translation_id": "supaya dia (Muhammad) memberi peringatan kepada orang-orang yang hidup (hatinya) dan supaya pastilah (ketetapan azab) terhadap orang-orang kafir.", "manzil": 5, "manzil_display": ""}], "445": [{"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 71, "text": "أَوَ لَمۡ یَرَوۡا۟ أَنَّا خَلَقۡنَا لَهُم مِّمَّا عَمِلَتۡ أَیۡدِینَاۤ أَنۡعَـٰمࣰا فَهُمۡ لَهَا مَـٰلِكُونَ ۝٧١", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "أولم ير الخلق أنا خلقنا لأجلهم أنعامًا ذللناها لهم، فهم مالكون أمرها؟", "isBasmala": false, "translation_en": "Have they not seen that We created for them, of Our Handiwork, livestock that they own?", "translation_id": "Dan apakah mereka tidak melihat bahwa sesungguhnya Kami telah menciptakan binatang ternak untuk mereka yaitu sebahagian dari apa yang telah Kami ciptakan dengan kekuasaan Kami sendiri, lalu mereka menguasainya?", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 72, "text": "وَذَلَّلۡنَـٰهَا لَهُمۡ فَمِنۡهَا رَكُوبُهُمۡ وَمِنۡهَا یَأۡكُلُونَ ۝٧٢", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وسخَّرناها لهم، فمنها ما يركبون في الأسفار، ويحملون عليها الأثقال، ومنها ما يأكلون.", "isBasmala": false, "translation_en": "And We subdued them for them. Some they ride, and some they eat.", "translation_id": "Dan Kami tundukkan binatang-binatang itu untuk mereka; maka sebahagiannya menjadi tunggangan mereka dan sebahagiannya mereka makan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 73, "text": "وَلَهُمۡ فِیهَا مَنَـٰفِعُ وَمَشَارِبُۚ أَفَلَا یَشۡكُرُونَ ۝٧٣", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "ولهم فيها منافع أخرى ينتفعون بها، كالانتفاع بأصوافها وأوبارها وأشعارها أثاثًا ولباسًا، وغير ذلك، ويشربون ألبانها، أفلا يشكرون الله الذي أنعم عليهم بهذه النعم، ويخلصون له العبادة؟", "isBasmala": false, "translation_en": "And they have in them other benefits, and drinks. Will they not give thanks?", "translation_id": "Dan mereka memperoleh padanya manfaat-manfaat dan minuman. Maka mengapakah mereka tidak bersyukur?", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 74, "text": "وَٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ ءَالِهَةࣰ لَّعَلَّهُمۡ یُنصَرُونَ ۝٧٤", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "واتخذ المشركون من دون الله آلهة يعبدونها؛ طمعًا في نصرها لهم وإنقاذهم من عذاب الله.", "isBasmala": false, "translation_en": "Yet they have taken to themselves gods other than God, that perhaps they may be helped.", "translation_id": "Mereka mengambil sembahan-sembahan selain Allah, agar mereka mendapat pertolongan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 75, "text": "لَا یَسۡتَطِیعُونَ نَصۡرَهُمۡ وَهُمۡ لَهُمۡ جُندࣱ مُّحۡضَرُونَ ۝٧٥", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "لا تستطيع تلك الآلهة نصر عابديها ولا أنفسهم ينصرون، والمشركون وآلهتهم جميعًا محضرون في العذاب، متبرئ بعضهم من بعض.", "isBasmala": false, "translation_en": "They cannot help them, although they are arrayed as troops for them.", "translation_id": "Berhala-berhala itu tiada dapat menolong mereka; padahal berhala-berhala itu menjadi tentara yang disiapkan untuk menjaga mereka.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 76, "text": "فَلَا یَحۡزُنكَ قَوۡلُهُمۡۘ إِنَّا نَعۡلَمُ مَا یُسِرُّونَ وَمَا یُعۡلِنُونَ ۝٧٦", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "فلا يَحْزُنك -أيها الرسول- كفرهم بالله وتكذيبهم لك واستهزاؤهم بك؛ إنا نعلم ما يخفون، وما يظهرون، وسنجازيهم على ذلك.", "isBasmala": false, "translation_en": "So let their words not sadden you. We know what they conceal, and what they reveal.", "translation_id": "Maka janganlah ucapan mereka menyedihkan kamu. Sesungguhnya Kami mengetahui apa yang mereka rahasiakan dan apa yang mereka nyatakan.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 77, "text": "أَوَ لَمۡ یَرَ ٱلۡإِنسَـٰنُ أَنَّا خَلَقۡنَـٰهُ مِن نُّطۡفَةࣲ فَإِذَا هُوَ خَصِیمࣱ مُّبِینࣱ ۝٧٧", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "أولم ير الإنسان المنكر للبعث ابتداء خلقه فيستدل به على معاده، أنا خلقناه من نطفة مرَّت بأطوار حتى كَبِر، فإذا هو كثير الخصام واضح الجدال؟", "isBasmala": false, "translation_en": "Does the human being not consider that We created him from a seed? Yet he becomes a fierce adversary.", "translation_id": "Dan apakah manusia tidak memperhatikan bahwa Kami menciptakannya dari setitik air (mani), maka tiba-tiba ia menjadi penantang yang nyata!", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 78, "text": "وَضَرَبَ لَنَا مَثَلࣰا وَنَسِیَ خَلۡقَهُۥۖ قَالَ مَن یُحۡیِ ٱلۡعِظَـٰمَ وَهِیَ رَمِیمࣱ ۝٧٨", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وضرب لنا المنكر للبعث مثلا لا ينبغي ضربه، وهو قياس قدرة الخالق بقدرة المخلوق، ونسي ابتداء خلقه، قال: مَن يحيي العظام البالية المتفتتة؟", "isBasmala": false, "translation_en": "And he produces arguments against Us, and he forgets his own creation. He says, \"Who will revive the bones when they have decayed?\"", "translation_id": "Dan ia membuat perumpamaan bagi Kami; dan dia lupa kepada kejadiannya; ia berkata: \"Siapakah yang dapat menghidupkan tulang belulang, yang telah hancur luluh?\"", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 79, "text": "قُلۡ یُحۡیِیهَا ٱلَّذِیۤ أَنشَأَهَاۤ أَوَّلَ مَرَّةࣲۖ وَهُوَ بِكُلِّ خَلۡقٍ عَلِیمٌ ۝٧٩", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "قل له: يحييها الذي خلقها أول مرة، وهو بجميع خلقه عليم، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "Say, \"He who initiated them in the first instance will revive them. He has knowledge of every creation.\"", "translation_id": "Katakanlah: \"Ia akan dihidupkan oleh Tuhan yang menciptakannya kali yang pertama. Dan Dia Maha Mengetahui tentang segala makhluk.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 80, "text": "ٱلَّذِی جَعَلَ لَكُم مِّنَ ٱلشَّجَرِ ٱلۡأَخۡضَرِ نَارࣰا فَإِذَاۤ أَنتُم مِّنۡهُ تُوقِدُونَ ۝٨٠", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "الذي أخرج لكم من الشجر الأخضر الرطب نارًا محرقة، فإذا أنتم من الشجر توقدون النار، فهو القادر على إخراج الضد من الضد. وفي ذلك دليل على وحدانية الله وكمال قدرته، ومن ذلك إخراج الموتى من قبورهم أحياء.", "isBasmala": false, "translation_en": "He who produced fuel for you from the green trees, with which you kindle a fire.", "translation_id": "yaitu Tuhan yang menjadikan untukmu api dari kayu yang hijau, maka tiba-tiba kamu nyalakan (api) dari kayu itu\".", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 81, "text": "أَوَ لَیۡسَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ بِقَـٰدِرٍ عَلَىٰۤ أَن یَخۡلُقَ مِثۡلَهُمۚ بَلَىٰ وَهُوَ ٱلۡخَلَّـٰقُ ٱلۡعَلِیمُ ۝٨١", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "أوليس الذي خلق السموات والأرض وما فيهما بقادر على أن يخلق مثلهم، فيعيدهم كما بدأهم؟ بلى، إنه قادر على ذلك، وهو الخلاق لجميع المخلوقات، العليم بكل ما خلق ويَخْلُقُ، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "Is not He who created the heavens and the earth able to create the like of them? Certainly. He is the Supreme All-Knowing Creator.", "translation_id": "Dan tidaklah Tuhan yang menciptakan langit dan bumi itu berkuasa menciptakan yang serupa dengan itu? Benar, Dia berkuasa. Dan Dialah Maha Pencipta lagi Maha Mengetahui.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 82, "text": "إِنَّمَاۤ أَمۡرُهُۥۤ إِذَاۤ أَرَادَ شَیۡـًٔا أَن یَقُولَ لَهُۥ كُن فَیَكُونُ ۝٨٢", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "إنما أمره سبحانه وتعالى إذا أراد شيئًا أن يقول له: \"كن\" فيكون، ومن ذلك الإماتة والإحياء، والبعث والنشور.", "isBasmala": false, "translation_en": "His command, when He wills a thing, is to say to it, \"Be,\" and it comes to be.", "translation_id": "Sesungguhnya keadaan-Nya apabila Dia menghendaki sesuatu hanyalah berkata kepadanya: \"Jadilah!\" maka terjadilah ia.", "manzil": 5, "manzil_display": ""}, {"sura": 36, "sura_name": "يس", "revelation": "Makkiyah", "aya": 83, "text": "فَسُبۡحَـٰنَ ٱلَّذِی بِیَدِهِۦ مَلَكُوتُ كُلِّ شَیۡءࣲ وَإِلَیۡهِ تُرۡجَعُونَ ۝٨٣", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "فتنزه الله تعالى وتقدس عن العجز والشرك، فهو المالك لكل شيء، المتصرف في شؤون خلقه بلا منازع أو ممانع، وقد ظهرت دلائل قدرته، وتمام نعمته، وإليه تُرجعون للحساب والجزاء.", "isBasmala": false, "translation_en": "So glory be to Him in whose hand is the dominion of everything, and to Him you will be returned.", "translation_id": "Maka Maha Suci (Allah) yang di tangan-Nya kekuasaaan atas segala sesuatu dan kepada-Nya-lah kamu dikembalikan.", "manzil": 5, "manzil_display": ""}], "446": [{"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 23, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلصَّـٰۤفَّـٰتِ صَفࣰّا ۝١", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "أقسم الله تعالى بالملائكة تصف في عبادتها صفوفًا متراصة، وبالملائكة تزجر السحاب وتسوقه بأمر الله، وبالملائكة تتلو ذكر الله وكلامه تعالى. إن معبودكم -أيها الناس- لواحد لا شريك له، فأخلصوا له العبادة والطاعة. ويقسم الله بما شاء مِن خلقه، أما المخلوق فلا يجوز له القسم إلا بالله، فالحلف بغير الله شرك.", "isBasmala": false, "translation_en": "By the aligners aligning.", "translation_id": "Demi (rombongan) yang ber shaf-shaf dengan sebenar-benarnya],", "manzil": 6, "manzil_display": "المنزل السادس (م ص 6)"}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 2, "text": "فَٱلزَّ ٰجِرَ ٰتِ زَجۡرࣰا ۝٢", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "أقسم الله تعالى بالملائكة تصف في عبادتها صفوفًا متراصة، وبالملائكة تزجر السحاب وتسوقه بأمر الله، وبالملائكة تتلو ذكر الله وكلامه تعالى. إن معبودكم -أيها الناس- لواحد لا شريك له، فأخلصوا له العبادة والطاعة. ويقسم الله بما شاء مِن خلقه، أما المخلوق فلا يجوز له القسم إلا بالله، فالحلف بغير الله شرك.", "isBasmala": false, "translation_en": "And the drivers driving.", "translation_id": "dan demi (rombongan) yang melarang dengan sebenar-benarnya (dari perbuatan-perbuatan maksiat),", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 3, "text": "فَٱلتَّـٰلِیَـٰتِ ذِكۡرًا ۝٣", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "أقسم الله تعالى بالملائكة تصف في عبادتها صفوفًا متراصة، وبالملائكة تزجر السحاب وتسوقه بأمر الله، وبالملائكة تتلو ذكر الله وكلامه تعالى. إن معبودكم -أيها الناس- لواحد لا شريك له، فأخلصوا له العبادة والطاعة. ويقسم الله بما شاء مِن خلقه، أما المخلوق فلا يجوز له القسم إلا بالله، فالحلف بغير الله شرك.", "isBasmala": false, "translation_en": "And the reciters of the Reminder.", "translation_id": "dan demi (rombongan) yang membacakan pelajaran,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 4, "text": "إِنَّ إِلَـٰهَكُمۡ لَوَ ٰحِدࣱ ۝٤", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "أقسم الله تعالى بالملائكة تصف في عبادتها صفوفًا متراصة، وبالملائكة تزجر السحاب وتسوقه بأمر الله، وبالملائكة تتلو ذكر الله وكلامه تعالى. إن معبودكم -أيها الناس- لواحد لا شريك له، فأخلصوا له العبادة والطاعة. ويقسم الله بما شاء مِن خلقه، أما المخلوق فلا يجوز له القسم إلا بالله، فالحلف بغير الله شرك.", "isBasmala": false, "translation_en": "Your God is indeed One.", "translation_id": "Sesungguhnya Tuhanmu benar-benar Esa.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 5, "text": "رَّبُّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا وَرَبُّ ٱلۡمَشَـٰرِقِ ۝٥", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "هو خالق السموات والأرض وما بينهما، ومدبِّر الشمس في مطالعها ومغاربها.", "isBasmala": false, "translation_en": "Lord of the heavens and the earth, and everything between them; and Lord of the Easts.", "translation_id": "Tuhan langit dan bumi dan apa yang berada di antara keduanya dan Tuhan tempat-tempat terbit matahari.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 6, "text": "إِنَّا زَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِزِینَةٍ ٱلۡكَوَاكِبِ ۝٦", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "إنَّا زينَّا السماء الدنيا بزينة هي النجوم.", "isBasmala": false, "translation_en": "We have adorned the lower heaven with the beauty of the planets.", "translation_id": "Sesungguhnya Kami telah menghias langit yang terdekat dengan hiasan, yaitu bintang-bintang,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 7, "text": "وَحِفۡظࣰا مِّن كُلِّ شَیۡطَـٰنࣲ مَّارِدࣲ ۝٧", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وحفظنا السماء بالنجوم مِن كل شيطان متمرِّد عاتٍ رجيم.", "isBasmala": false, "translation_en": "And guarded it against every defiant devil.", "translation_id": "dan telah memeliharanya (sebenar-benarnya) dari setiap syaitan yang sangat durhaka,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 8, "text": "لَّا یَسَّمَّعُونَ إِلَى ٱلۡمَلَإِ ٱلۡأَعۡلَىٰ وَیُقۡذَفُونَ مِن كُلِّ جَانِبࣲ ۝٨", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "لا تستطيع الشياطين أن تصل إلى الملأ الأعلى، وهي السموات ومَن فيها مِن الملائكة، فتستمع إليهم إذا تكلموا بما يوحيه الله تعالى مِن شرعه وقدره، ويُرْجَمون بالشهب من كل جهة؛ طردًا لهم عن الاستماع، ولهم في الدار الآخرة عذاب دائم موجع.", "isBasmala": false, "translation_en": "They cannot eavesdrop on the Supernal Elite, for they get bombarded from every side.", "translation_id": "syaitan syaitan itu tidak dapat mendengar-dengarkan (pembicaraan) para malaikat dan mereka dilempari dari segala penjuru.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 9, "text": "دُحُورࣰاۖ وَلَهُمۡ عَذَابࣱ وَاصِبٌ ۝٩", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "لا تستطيع الشياطين أن تصل إلى الملأ الأعلى، وهي السموات ومَن فيها مِن الملائكة، فتستمع إليهم إذا تكلموا بما يوحيه الله تعالى مِن شرعه وقدره، ويُرْجَمون بالشهب من كل جهة؛ طردًا لهم عن الاستماع، ولهم في الدار الآخرة عذاب دائم موجع.", "isBasmala": false, "translation_en": "Repelled-they will have a lingering torment.", "translation_id": "Untuk mengusir mereka dan bagi mereka siksaan yang kekal,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 10, "text": "إِلَّا مَنۡ خَطِفَ ٱلۡخَطۡفَةَ فَأَتۡبَعَهُۥ شِهَابࣱ ثَاقِبࣱ ۝١٠", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "إلا مَنِ اختطف من الشياطين الخطفة، وهي الكلمة يسمعها من السماء بسرعة، فيلقيها إلى الذي تحته، ويلقيها الآخر إلى الذي تحته، فربما أدركه الشهاب المضيء قبل أن يلقيها، وربما ألقاها بقَدَر الله تعالى قبل أن يأتيه الشهاب، فيحرقه فيذهب بها الآخر إلى الكهنة، فيكذبون معها مائة كذبة.", "isBasmala": false, "translation_en": "Except for him who snatches a fragment-he gets pursued by a piercing projectile.", "translation_id": "akan tetapi barangsiapa (di antara mereka) yang mencuri-curi (pembicaraan); maka ia dikejar oleh suluh api yang cemerlang.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 11, "text": "فَٱسۡتَفۡتِهِمۡ أَهُمۡ أَشَدُّ خَلۡقًا أَم مَّنۡ خَلَقۡنَاۤۚ إِنَّا خَلَقۡنَـٰهُم مِّن طِینࣲ لَّازِبِۭ ۝١١", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "فاسأل -أيها الرسول- منكري البعث أَهُم أشد خلقًا أم من خلقنا من هذه المخلوقات؟ إنا خلقنا أباهم آدم من طين لزج، يلتصق بعضه ببعض.", "isBasmala": false, "translation_en": "Inquire of them, \"Are they more difficult to create, or the others We created?\" We created them from sticky clay.", "translation_id": "Maka tanyakanlah kepada mereka (musyrik Mekah): \"Apakah mereka yang lebih kukuh kejadiannya ataukah apa yang telah Kami ciptakan itu?\" Sesungguhnya Kami telah menciptakan mereka dari tanah liat.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 12, "text": "بَلۡ عَجِبۡتَ وَیَسۡخَرُونَ ۝١٢", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "بل عجبتَ -أيها الرسول- من تكذيبهم وإنكارهم البعث، وأعجب من إنكارهم وأبلغ أنهم يستهزئون بك، ويسخرون من قولك.", "isBasmala": false, "translation_en": "But you wonder, and they ridicule.", "translation_id": "Bahkan kamu menjadi heran (terhadap keingkaran mereka) dan mereka menghinakan kamu.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 13, "text": "وَإِذَا ذُكِّرُوا۟ لَا یَذۡكُرُونَ ۝١٣", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وإذا ذكِّروا بما نسوه أو غَفَلوا عنه لا ينتفعون بهذا الذكر ولا يتدبَّرون.", "isBasmala": false, "translation_en": "And when reminded, they pay no attention.", "translation_id": "Dan apabila mereka diberi pelajaran mereka tiada mengingatnya.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 14, "text": "وَإِذَا رَأَوۡا۟ ءَایَةࣰ یَسۡتَسۡخِرُونَ ۝١٤", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وإذا رأوا معجزة دالَّة على نبوَّتك يسخرون منها ويعجبون.", "isBasmala": false, "translation_en": "And when they see a sign, they ridicule.", "translation_id": "Dan apabila mereka melihat sesuatu tanda kebesaran Allah, mereka sangat menghinakan.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 15, "text": "وَقَالُوۤا۟ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینٌ ۝١٥", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وقالوا: ما هذا الذي جئت به إلا سحر ظاهر بيِّن. أإذا متنا وصِرْنا ترابًا وعظامًا بالية أإنا لمبعوثون من قبورنا أحياء، أو يُبعث آباؤنا الذين مضوا من قبلنا؟", "isBasmala": false, "translation_en": "And they say, \"This is nothing but plain magic.", "translation_id": "Dan mereka berkata \"Ini tiada lain hanyalah sihir yang nyata.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 16, "text": "أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰا وَعِظَـٰمًا أَءِنَّا لَمَبۡعُوثُونَ ۝١٦", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وقالوا: ما هذا الذي جئت به إلا سحر ظاهر بيِّن. أإذا متنا وصِرْنا ترابًا وعظامًا بالية أإنا لمبعوثون من قبورنا أحياء، أو يُبعث آباؤنا الذين مضوا من قبلنا؟", "isBasmala": false, "translation_en": "When we have died and become dust and bones, shall we be resurrected?", "translation_id": "Apakah apabila kami telah mati dan telah menjadi tanah serta menjadi tulang belulang, apakah benar-benar kami akan dibangkitkan (kembali)?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 17, "text": "أَوَ ءَابَاۤؤُنَا ٱلۡأَوَّلُونَ ۝١٧", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وقالوا: ما هذا الذي جئت به إلا سحر ظاهر بيِّن. أإذا متنا وصِرْنا ترابًا وعظامًا بالية أإنا لمبعوثون من قبورنا أحياء، أو يُبعث آباؤنا الذين مضوا من قبلنا؟", "isBasmala": false, "translation_en": "And our ancestors of old?\"", "translation_id": "Dan apakah bapak-bapak kami yang telah terdahulu (akan dibangkitkan pula)\"?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 18, "text": "قُلۡ نَعَمۡ وَأَنتُمۡ دَ ٰخِرُونَ ۝١٨", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "قل لهم -أيها الرسول-: نعم سوف تُبعثون، وأنتم أذلاء صاغرون.", "isBasmala": false, "translation_en": "Say, \"Yes indeed, and you will be totally subdued.\"", "translation_id": "Katakanlah: \"Ya, dan kamu akan terhina\"", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 19, "text": "فَإِنَّمَا هِیَ زَجۡرَةࣱ وَ ٰحِدَةࣱ فَإِذَا هُمۡ یَنظُرُونَ ۝١٩", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "فإنما هي نفخة واحدة، فإذا هم قائمون من قبورهم ينظرون أهوال يوم القيامة.", "isBasmala": false, "translation_en": "It will be a single nudge, and they will be staring.", "translation_id": "Maka sesungguhnya kebangkitan itu hanya dengan satu teriakan saja; maka tiba-tiba mereka meIihatnya.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 20, "text": "وَقَالُوا۟ یَـٰوَیۡلَنَا هَـٰذَا یَوۡمُ ٱلدِّینِ ۝٢٠", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "وقالوا: يا هلاكنا هذا يوم الحساب والجزاء.", "isBasmala": false, "translation_en": "They will say, \"Woe to us. This is the Day of Judgment.\"", "translation_id": "Dan mereka berkata: \"Aduhai celakalah kita!\" Inilah hari pembalasan.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 21, "text": "هَـٰذَا یَوۡمُ ٱلۡفَصۡلِ ٱلَّذِی كُنتُم بِهِۦ تُكَذِّبُونَ ۝٢١", "juz": 23, "hizb": "(*¼ ح 45*)", "tafsir": "فيقال لهم: هذا يوم القضاء بين الخلق بالعدل الذي كنتم تكذبون به في الدنيا وتنكرونه.", "isBasmala": false, "translation_en": "\"This is the Day of Separation which you used to deny.", "translation_id": "Inilah hari keputusan yang kamu selalu mendustakannya.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 22, "text": "۞ ٱحۡشُرُوا۟ ٱلَّذِینَ ظَلَمُوا۟ وَأَزۡوَ ٰجَهُمۡ وَمَا كَانُوا۟ یَعۡبُدُونَ ۝٢٢", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ويقال للملائكة: اجمَعُوا الذين كفروا بالله ونظراءهم وآلهتهم التي كانوا يعبدونها من دون الله، فسوقوهم سوقًا عنيفًا إلى جهنم.", "isBasmala": false, "translation_en": "Gather those who did wrong, and their mates, and what they used to worship.", "translation_id": "(kepada malaikat diperintahkan): \"Kumpulkanlah orang-orang yang zalim beserta teman sejawat mereka dan sembahan-sembahan yang selalu mereka sembah,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 23, "text": "مِن دُونِ ٱللَّهِ فَٱهۡدُوهُمۡ إِلَىٰ صِرَ ٰطِ ٱلۡجَحِیمِ ۝٢٣", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ويقال للملائكة: اجمَعُوا الذين كفروا بالله ونظراءهم وآلهتهم التي كانوا يعبدونها من دون الله، فسوقوهم سوقًا عنيفًا إلى جهنم.", "isBasmala": false, "translation_en": "Besides God, and lead them to the way to Hell.", "translation_id": "selain Allah; maka tunjukkanlah kepada mereka jalan ke neraka.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 24, "text": "وَقِفُوهُمۡۖ إِنَّهُم مَّسۡـُٔولُونَ ۝٢٤", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "واحبسوهم قبل أن يصلوا إلى جهنم؛ إنهم مسؤولون عن أعمالهم وأقوالهم التي صدرت عنهم في الدنيا، مساءلة إنكار عليهم وتبكيت لهم.", "isBasmala": false, "translation_en": "And stop them. They are to be questioned.\"", "translation_id": "Dan tahanlah mereka (di tempat perhentian) karena sesungguhnya mereka akan ditanya:", "manzil": 6, "manzil_display": ""}], "447": [{"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 25, "text": "مَا لَكُمۡ لَا تَنَاصَرُونَ ۝٢٥", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ويقال لهم توبيخًا: ما لكم لا ينصر بعضكم بعضًا؟", "isBasmala": false, "translation_en": "What is the matter with you? Why do you not help one another?", "translation_id": "\"Kenapa kamu tidak tolong menolong?\"", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 26, "text": "بَلۡ هُمُ ٱلۡیَوۡمَ مُسۡتَسۡلِمُونَ ۝٢٦", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "بل هم اليوم منقادون لأمر الله، لا يخالفونه ولا يحيدون عنه، غير منتصرين لأنفسهم.", "isBasmala": false, "translation_en": "In fact, on that Day, they will be submissive.", "translation_id": "Bahkan mereka pada hari itu menyerah diri.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 27, "text": "وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲ یَتَسَاۤءَلُونَ ۝٢٧", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "وأقبل بعض الكفار على بعض يتلاومون ويتخاصمون.", "isBasmala": false, "translation_en": "They will come to one another, questioning one another.", "translation_id": "Sebahagian dan mereka menghadap kepada sebahagian yang lain berbantah-bantahan.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 28, "text": "قَالُوۤا۟ إِنَّكُمۡ كُنتُمۡ تَأۡتُونَنَا عَنِ ٱلۡیَمِینِ ۝٢٨", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "قال الأتباع للمتبوعين: إنكم كنتم تأتوننا من قِبَل الدين والحق، فتهوِّنون علينا أمر الشريعة، وتُنَفِّروننا عنها، وتزينون لنا الضلال.", "isBasmala": false, "translation_en": "They will say, \"You used to come at us from the right.\"", "translation_id": "Pengikut-pengikut mereka berkata (kepada pemimpin-pemimpin mereka): \"Sesungguhnya kamulah yang datang kepada kami dan kanan.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 29, "text": "قَالُوا۟ بَل لَّمۡ تَكُونُوا۟ مُؤۡمِنِینَ ۝٢٩", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "قال المتبوعون للتابعين: ما الأمر كما تزعمون، بل كانت قلوبكم منكرة للإيمان، قابلة للكفر والعصيان.", "isBasmala": false, "translation_en": "They will say, \"You yourselves were not believers.", "translation_id": "Pemimpin-pemimpin mereka menjawab: \"Sebenarnya kamulah yang tidak beriman\".", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 30, "text": "وَمَا كَانَ لَنَا عَلَیۡكُم مِّن سُلۡطَـٰنِۭۖ بَلۡ كُنتُمۡ قَوۡمࣰا طَـٰغِینَ ۝٣٠", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "وما كان لنا عليكم من حجة أو قوَّة، فنصدكم بها عن الإيمان، بل كنتم -أيها المشركون- قومًا طاغين متجاوزين للحق.", "isBasmala": false, "translation_en": "We had no authority over you. You yourselves were rebellious people.", "translation_id": "Dan sekali-kali kami tidak berkuasa terhadapmu, bahkan kamulah kaum yang melampaui batas.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 31, "text": "فَحَقَّ عَلَیۡنَا قَوۡلُ رَبِّنَاۤۖ إِنَّا لَذَاۤىِٕقُونَ ۝٣١", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "فلزِمَنا جميعًا وعيد ربنا، إنا لذائقو العذاب، نحن وأنتم، بما قدمنا من ذنوبنا ومعاصينا في الدنيا.", "isBasmala": false, "translation_en": "The Word of our Lord has been realized against us. We are tasting it.", "translation_id": "Maka pastilah putusan (azab) Tuhan kita menimpa atas kita; sesungguhnya kita akan merasakan (azab itu).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 32, "text": "فَأَغۡوَیۡنَـٰكُمۡ إِنَّا كُنَّا غَـٰوِینَ ۝٣٢", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "فأضللناكم عن سبيل الله والإيمان به، إنا كنا ضالين من قبلكم، فهلكنا؛ بسبب كفرنا، وأهلكناكم معنا.", "isBasmala": false, "translation_en": "We seduced you. We were seducers.\"", "translation_id": "Maka kami telah menyesatkan kamu, sesungguhnya kami adalah orang-orang yang sesat.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 33, "text": "فَإِنَّهُمۡ یَوۡمَىِٕذࣲ فِی ٱلۡعَذَابِ مُشۡتَرِكُونَ ۝٣٣", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "فإن الأتباع والمتبوعين مشتركون يوم القيامة في العذاب، كما اشتركوا في الدنيا في معصية الله.", "isBasmala": false, "translation_en": "On that Day, they will share in the punishment.", "translation_id": "Maka sesungguhnya mereka pada hari itu bersama-sama dalam azab.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 34, "text": "إِنَّا كَذَ ٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِینَ ۝٣٤", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنا هكذا نفعل بالذين اختاروا معاصي الله في الدنيا على طاعته، فنذيقهم العذاب الأليم.", "isBasmala": false, "translation_en": "Thus We deal with the sinners.", "translation_id": "Sesungguhnya demikianlah Kami berbuat terhadap orang-orang yang berbuat jahat.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 35, "text": "إِنَّهُمۡ كَانُوۤا۟ إِذَا قِیلَ لَهُمۡ لَاۤ إِلَـٰهَ إِلَّا ٱللَّهُ یَسۡتَكۡبِرُونَ ۝٣٥", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إن أولئك المشركين كانوا في الدنيا إذا قيل لهم: لا إله إلا الله، ودعوا إليها، وأُمروا بترك ما ينافيها، يستكبرون عنها وعلى من جاء بها.", "isBasmala": false, "translation_en": "When it was said to them, \"There is no god except God,\" they grew arrogant.", "translation_id": "Sesungguhnya mereka dahulu apabila dikatakan kepada mereka: \"Laa ilaaha illallah\" (Tiada Tuhan yang berhak disembah melainkan Allah) mereka menyombongkan diri,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 36, "text": "وَیَقُولُونَ أَىِٕنَّا لَتَارِكُوۤا۟ ءَالِهَتِنَا لِشَاعِرࣲ مَّجۡنُونِۭ ۝٣٦", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ويقولون: أنترك عبادة آلهتنا لقول رجل شاعر مجنون؟ يعنون رسول الله صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "And said, \"Are we to abandon our gods for a mad poet?\"", "translation_id": "dan mereka berkata: \"Apakah sesungguhnya kami harus meninggalkan sembahan-sembahan kami karena seorang penyair gila?\"", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 37, "text": "بَلۡ جَاۤءَ بِٱلۡحَقِّ وَصَدَّقَ ٱلۡمُرۡسَلِینَ ۝٣٧", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "كذَبوا، ما محمد كما وصفوه به، بل جاء بالقرآن والتوحيد، وصدَّق المرسلين فيما أخبروا به عنه من شرع الله وتوحيده.", "isBasmala": false, "translation_en": "In fact, he came with the truth, and he confirmed the messengers.", "translation_id": "Sebenarnya dia (Muhammad) telah datang membawa kebenaran dan membenarkan rasul-rasul (sebelumnya).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 38, "text": "إِنَّكُمۡ لَذَاۤىِٕقُوا۟ ٱلۡعَذَابِ ٱلۡأَلِیمِ ۝٣٨", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنكم -أيها المشركون- بقولكم وكفركم وتكذيبكم لذائقو العذاب الأليم الموجع.", "isBasmala": false, "translation_en": "Most assuredly, you will taste the painful punishment.", "translation_id": "Sesungguhnya kamu pasti akan merasakan azab yang pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 39, "text": "وَمَا تُجۡزَوۡنَ إِلَّا مَا كُنتُمۡ تَعۡمَلُونَ ۝٣٩", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "وما تجزون في الآخرة إلا بما كنتم تعملونه في الدنيا من المعاصي.", "isBasmala": false, "translation_en": "And you will be repaid only for what you used to do.", "translation_id": "Dan kamu tidak diberi pembalasan melainkan terhadap kejahatan yang telah kamu kerjakan,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 40, "text": "إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِینَ ۝٤٠", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إلا عباد الله تعالى الذين أخلصوا له في عبادته، فأخلصهم واختصهم برحمته؛ فإنهم ناجون من العذاب الأليم.", "isBasmala": false, "translation_en": "Except for God's sincere servants.", "translation_id": "tetapi hamba-hamba Allah yang dibersihkan (dari dosa).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 41, "text": "أُو۟لَـٰۤىِٕكَ لَهُمۡ رِزۡقࣱ مَّعۡلُومࣱ ۝٤١", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "أولئك المخلصون لهم في الجنة رزق معلوم لا ينقطع.", "isBasmala": false, "translation_en": "For them is a known provision.", "translation_id": "Mereka itu memperoleh rezeki yang tertentu,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 42, "text": "فَوَ ٰكِهُ وَهُم مُّكۡرَمُونَ ۝٤٢", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ذلك الرزق فواكه متنوعة، وهم مكرمون بكرامة الله لهم في جنات النعيم الدائم.", "isBasmala": false, "translation_en": "Fruits; and they will be honored.", "translation_id": "yaitu buah-buahan. Dan mereka adalah orang-orang yang dimuliakan,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 43, "text": "فِی جَنَّـٰتِ ٱلنَّعِیمِ ۝٤٣", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ذلك الرزق فواكه متنوعة، وهم مكرمون بكرامة الله لهم في جنات النعيم الدائم.", "isBasmala": false, "translation_en": "In the Gardens of Bliss.", "translation_id": "di dalam surga-surga yang penuh nikmat.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 44, "text": "عَلَىٰ سُرُرࣲ مُّتَقَـٰبِلِینَ ۝٤٤", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ومن كرامتهم عند ربهم وإكرام بعضهم بعضًا أنهم على سرر متقابلين فيما بينهم.", "isBasmala": false, "translation_en": "On furnishings, facing one another.", "translation_id": "di atas takhta-takhta kebesaran berhadap-hadapan.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 45, "text": "یُطَافُ عَلَیۡهِم بِكَأۡسࣲ مِّن مَّعِینِۭ ۝٤٥", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "يدار عليهم في مجالسهم بكؤوس خمر من أنهار جارية، لا يخافون انقطاعها، بيضاء في لونها، لذيذة في شربها، ليس فيها أذى للجسم ولا للعقل.", "isBasmala": false, "translation_en": "They will be offered a cup of pure drink.", "translation_id": "Diedarkan kepada mereka gelas yang berisi khamar dari sungai yang mengalir.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 46, "text": "بَیۡضَاۤءَ لَذَّةࣲ لِّلشَّـٰرِبِینَ ۝٤٦", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "يدار عليهم في مجالسهم بكؤوس خمر من أنهار جارية، لا يخافون انقطاعها، بيضاء في لونها، لذيذة في شربها، ليس فيها أذى للجسم ولا للعقل.", "isBasmala": false, "translation_en": "White; a delight to those who drink.", "translation_id": "(Warnanya) putih bersih, sedap rasanya bagi orang-orang yang minum.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 47, "text": "لَا فِیهَا غَوۡلࣱ وَلَا هُمۡ عَنۡهَا یُنزَفُونَ ۝٤٧", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "يدار عليهم في مجالسهم بكؤوس خمر من أنهار جارية، لا يخافون انقطاعها، بيضاء في لونها، لذيذة في شربها، ليس فيها أذى للجسم ولا للعقل.", "isBasmala": false, "translation_en": "Never polluted, and never intoxicating.", "translation_id": "Tidak ada dalam khamar itu alkohol dan mereka tiada mabuk karenanya.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 48, "text": "وَعِندَهُمۡ قَـٰصِرَ ٰتُ ٱلطَّرۡفِ عِینࣱ ۝٤٨", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "وعندهم في مجالسهم نساء عفيفات، لا ينظرن إلى غير أزواجهن حسان الأعين، كأنهن بَيْض مصون لم تمسه الأيدي.", "isBasmala": false, "translation_en": "With them will be bashful women with lovely eyes.", "translation_id": "Di sisi mereka ada bidadari-bidadari yang tidak liar pandangannya dan jelita matanya,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 49, "text": "كَأَنَّهُنَّ بَیۡضࣱ مَّكۡنُونࣱ ۝٤٩", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "وعندهم في مجالسهم نساء عفيفات، لا ينظرن إلى غير أزواجهن حسان الأعين، كأنهن بَيْض مصون لم تمسه الأيدي.", "isBasmala": false, "translation_en": "As if they were closely guarded pearls.", "translation_id": "seakan-akan mereka adalah telur (burung unta) yang tersimpan dengan baik.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 50, "text": "فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲ یَتَسَاۤءَلُونَ ۝٥٠", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "فأقبل بعضهم على بعض يتساءلون عن أحوالهم في الدنيا وما كانوا يعانون فيها، وما أنعم الله به عليهم في الجنة، وهذا من تمام الأنس.", "isBasmala": false, "translation_en": "Then they will approach one another, questioning.", "translation_id": "Lalu sebahagian mereka menghadap kepada sebahagian yang lain sambil bercakap-cakap.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 51, "text": "قَالَ قَاۤىِٕلࣱ مِّنۡهُمۡ إِنِّی كَانَ لِی قَرِینࣱ ۝٥١", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "قال قائل من أهل الجنة: لقد كان لي في الدنيا صاحب ملازم لي.", "isBasmala": false, "translation_en": "One of them will say, \"I used to have a friend.", "translation_id": "Berkatalah salah seorang di antara mereka: \"Sesungguhnya aku dahulu (di dunia) mempunyai seorang teman,", "manzil": 6, "manzil_display": ""}], "448": [{"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 52, "text": "یَقُولُ أَءِنَّكَ لَمِنَ ٱلۡمُصَدِّقِینَ ۝٥٢", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "يقول: كيف تصدِّق بالبعث الذي هو في غاية الاستغراب؟ أإذا متنا وتمزقنا وصرنا ترابًا وعظامًا، نُبعث ونُحاسب ونُجازى بأعمالنا؟", "isBasmala": false, "translation_en": "Who used to say, \"Are you of those who believe?", "translation_id": "yang berkata: \"Apakah kamu sungguh-sungguh termasuk orang-orang yang membenarkan (hari berbangkit)?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 53, "text": "أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰا وَعِظَـٰمًا أَءِنَّا لَمَدِینُونَ ۝٥٣", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "يقول: كيف تصدِّق بالبعث الذي هو في غاية الاستغراب؟ أإذا متنا وتمزقنا وصرنا ترابًا وعظامًا، نُبعث ونُحاسب ونُجازى بأعمالنا؟", "isBasmala": false, "translation_en": "That after we die and become dust and bones, we will be called to account?\"", "translation_id": "Apakah bila kita telah mati dan kita telah menjadi tanah dan tulang belulang, apakah sesungguhnya kita benar-benar (akan dibangkitkan) untuk diberi pembalasan?\"", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 54, "text": "قَالَ هَلۡ أَنتُم مُّطَّلِعُونَ ۝٥٤", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "قال هذا المؤمن الذي أُدخل الجنة لأصحابه: هل أنتم مُطَّلعون لنرى مصير ذلك القرين؟ فاطلع فرأى قرينه في وسط النار.", "isBasmala": false, "translation_en": "He will say, \"Will you have a look?\"", "translation_id": "Berkata pulalah ia: \"Maukah kamu meninjau (temanku itu)?\"", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 55, "text": "فَٱطَّلَعَ فَرَءَاهُ فِی سَوَاۤءِ ٱلۡجَحِیمِ ۝٥٥", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "قال هذا المؤمن الذي أُدخل الجنة لأصحابه: هل أنتم مُطَّلعون لنرى مصير ذلك القرين؟ فاطلع فرأى قرينه في وسط النار.", "isBasmala": false, "translation_en": "He will look, and will see him in the pit of Hell.", "translation_id": "Maka ia meninjaunya, lalu dia melihat temannya itu di tengah-tengah neraka menyala-nyala.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 56, "text": "قَالَ تَٱللَّهِ إِن كِدتَّ لَتُرۡدِینِ ۝٥٦", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "قال المؤمن لقرينه المنكر للبعث: لقد قاربت أن تهلكني بصدك إياي عن الإيمان لو أطعتك. ولولا فضل ربي بهدايتي إلى الإيمان وتثبيتي عليه، لكنت من المحضرين في العذاب معك.", "isBasmala": false, "translation_en": "He will say, \"By God, you almost ruined me.", "translation_id": "Ia berkata (pula): \"Demi Allah, sesungguhnya kamu benar-benar hampir mencelakakanku,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 57, "text": "وَلَوۡلَا نِعۡمَةُ رَبِّی لَكُنتُ مِنَ ٱلۡمُحۡضَرِینَ ۝٥٧", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "قال المؤمن لقرينه المنكر للبعث: لقد قاربت أن تهلكني بصدك إياي عن الإيمان لو أطعتك. ولولا فضل ربي بهدايتي إلى الإيمان وتثبيتي عليه، لكنت من المحضرين في العذاب معك.", "isBasmala": false, "translation_en": "Were it not for the grace of my Lord, I would have been among the arraigned.\"", "translation_id": "jikalau tidaklah karena nikmat Tuhanku pastilah aku termasuk orang-orang yang diseret (ke neraka).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 58, "text": "أَفَمَا نَحۡنُ بِمَیِّتِینَ ۝٥٨", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "أحقًا أننا مخلَّدون منعَّمون، فما نحن بميتين إلا موتتنا الأولى في الدنيا، وما نحن بمعذَّبين بعد دخولنا الجنة؟ إنَّ ما نحن فيه من نعيم لهُوَ الظَّفَر العظيم.", "isBasmala": false, "translation_en": "\"We will not die.", "translation_id": "Maka apakah kita tidak akan mati?,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 59, "text": "إِلَّا مَوۡتَتَنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُعَذَّبِینَ ۝٥٩", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "أحقًا أننا مخلَّدون منعَّمون، فما نحن بميتين إلا موتتنا الأولى في الدنيا، وما نحن بمعذَّبين بعد دخولنا الجنة؟ إنَّ ما نحن فيه من نعيم لهُوَ الظَّفَر العظيم.", "isBasmala": false, "translation_en": "Except for our first death, and we will not be punished.\"", "translation_id": "melainkan hanya kematian kita yang pertama saja (di dunia), dan kita tidak akan disiksa (di akhirat ini)?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 60, "text": "إِنَّ هَـٰذَا لَهُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝٦٠", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "أحقًا أننا مخلَّدون منعَّمون، فما نحن بميتين إلا موتتنا الأولى في الدنيا، وما نحن بمعذَّبين بعد دخولنا الجنة؟ إنَّ ما نحن فيه من نعيم لهُوَ الظَّفَر العظيم.", "isBasmala": false, "translation_en": "This is the supreme triumph.", "translation_id": "Sesungguhnya ini benar-benar kemenangan yang besar.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 61, "text": "لِمِثۡلِ هَـٰذَا فَلۡیَعۡمَلِ ٱلۡعَـٰمِلُونَ ۝٦١", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "لمثل هذا النعيم الكامل، والخلود الدائم، والفوز العظيم، فليعمل العاملون في الدنيا؛ ليصيروا إليه في الآخرة.", "isBasmala": false, "translation_en": "For the like of this let the workers work.", "translation_id": "Untuk kemenangan serupa ini hendaklah berusaha orang-orang yang bekerja\"", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 62, "text": "أَذَ ٰلِكَ خَیۡرࣱ نُّزُلًا أَمۡ شَجَرَةُ ٱلزَّقُّومِ ۝٦٢", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "أذلك الذي سبق وصفه مِن نعيم الجنة خير ضيافة وعطاء من الله، أم شجرة الزقوم الخبيثة الملعونة، طعام أهل النار؟", "isBasmala": false, "translation_en": "Is this a better hospitality, or the Tree of Bitterness?", "translation_id": "(Makanan surga) itukah hidangan yang lebih baik ataukah pohon zaqqum.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 63, "text": "إِنَّا جَعَلۡنَـٰهَا فِتۡنَةࣰ لِّلظَّـٰلِمِینَ ۝٦٣", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنا جعلناها فتنة افتتن بها الظالمون لأنفسهم بالكفر والمعاصي، وقالوا مستنكرين: إن صاحبكم ينبئكم أن في النار شجرة، والنار تأكل الشجر.", "isBasmala": false, "translation_en": "We made it an ordeal for the unjust.", "translation_id": "Sesungguhnya Kami menjadikan pohon zaqqum itu sebagai siksaan bagi orang-orang yang zalim.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 64, "text": "إِنَّهَا شَجَرَةࣱ تَخۡرُجُ فِیۤ أَصۡلِ ٱلۡجَحِیمِ ۝٦٤", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنها شجرة تنبت في قعر جهنم، ثمرها قبيح المنظر كأنه رؤوس الشياطين، فإذا كانت كذلك فلا تَسْألْ بعد هذا عن طعمها، فإن المشركين لآكلون من تلك الشجرة فمالئون منها بطونهم. ثم إنهم بعد الأكل منها لشاربون شرابًا خليطًا قبيحًا حارًّا، ثم إن مردَّهم بعد هذا العذاب إلى عذاب النار.", "isBasmala": false, "translation_en": "It is a tree that grows from the bottom of Hell.", "translation_id": "Sesungguhnya dia adalah sebatang pohon yang ke luar dan dasar neraka yang menyala.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 65, "text": "طَلۡعُهَا كَأَنَّهُۥ رُءُوسُ ٱلشَّیَـٰطِینِ ۝٦٥", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنها شجرة تنبت في قعر جهنم، ثمرها قبيح المنظر كأنه رؤوس الشياطين، فإذا كانت كذلك فلا تَسْألْ بعد هذا عن طعمها، فإن المشركين لآكلون من تلك الشجرة فمالئون منها بطونهم. ثم إنهم بعد الأكل منها لشاربون شرابًا خليطًا قبيحًا حارًّا، ثم إن مردَّهم بعد هذا العذاب إلى عذاب النار.", "isBasmala": false, "translation_en": "Its fruits are like the devils' heads.", "translation_id": "mayangnya seperti kepala syaitan-syaitan.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 66, "text": "فَإِنَّهُمۡ لَـَٔاكِلُونَ مِنۡهَا فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ ۝٦٦", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنها شجرة تنبت في قعر جهنم، ثمرها قبيح المنظر كأنه رؤوس الشياطين، فإذا كانت كذلك فلا تَسْألْ بعد هذا عن طعمها، فإن المشركين لآكلون من تلك الشجرة فمالئون منها بطونهم. ثم إنهم بعد الأكل منها لشاربون شرابًا خليطًا قبيحًا حارًّا، ثم إن مردَّهم بعد هذا العذاب إلى عذاب النار.", "isBasmala": false, "translation_en": "They will eat from it, and fill their bellies with it.", "translation_id": "Maka sesungguhnya mereka benar-benar memakan sebagian dari buah pohon itu, maka mereka memenuhi perutnya dengan buah zaqqum itu.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 67, "text": "ثُمَّ إِنَّ لَهُمۡ عَلَیۡهَا لَشَوۡبࣰا مِّنۡ حَمِیمࣲ ۝٦٧", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنها شجرة تنبت في قعر جهنم، ثمرها قبيح المنظر كأنه رؤوس الشياطين، فإذا كانت كذلك فلا تَسْألْ بعد هذا عن طعمها، فإن المشركين لآكلون من تلك الشجرة فمالئون منها بطونهم. ثم إنهم بعد الأكل منها لشاربون شرابًا خليطًا قبيحًا حارًّا، ثم إن مردَّهم بعد هذا العذاب إلى عذاب النار.", "isBasmala": false, "translation_en": "Then, on top of it, they will have a brew of boiling liquid.", "translation_id": "Kemudian sesudah makan buah pohon zaqqum itu pasti mereka mendapat minuman yang bercampur dengan air yang sangat panas.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 68, "text": "ثُمَّ إِنَّ مَرۡجِعَهُمۡ لَإِلَى ٱلۡجَحِیمِ ۝٦٨", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنها شجرة تنبت في قعر جهنم، ثمرها قبيح المنظر كأنه رؤوس الشياطين، فإذا كانت كذلك فلا تَسْألْ بعد هذا عن طعمها، فإن المشركين لآكلون من تلك الشجرة فمالئون منها بطونهم. ثم إنهم بعد الأكل منها لشاربون شرابًا خليطًا قبيحًا حارًّا، ثم إن مردَّهم بعد هذا العذاب إلى عذاب النار.", "isBasmala": false, "translation_en": "Then their return will be to the Blaze.", "translation_id": "Kemudian sesungguhnya tempat kembali mereka benar-benar ke neraka Jahim.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 69, "text": "إِنَّهُمۡ أَلۡفَوۡا۟ ءَابَاۤءَهُمۡ ضَاۤلِّینَ ۝٦٩", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنهم وجدوا آباءهم على الشرك والضلال، فسارعوا إلى متابعتهم على ذلك.", "isBasmala": false, "translation_en": "They had found their parents astray.", "translation_id": "Karena sesungguhnya mereka mendapati bapak-bapak mereka dalam Keadaaan sesat.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 70, "text": "فَهُمۡ عَلَىٰۤ ءَاثَـٰرِهِمۡ یُهۡرَعُونَ ۝٧٠", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إنهم وجدوا آباءهم على الشرك والضلال، فسارعوا إلى متابعتهم على ذلك.", "isBasmala": false, "translation_en": "And rushed along in their footsteps.", "translation_id": "Lalu mereka sangat tergesa-gesa mengikuti jejak orang-orang tua mereka itu.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 71, "text": "وَلَقَدۡ ضَلَّ قَبۡلَهُمۡ أَكۡثَرُ ٱلۡأَوَّلِینَ ۝٧١", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ولقد ضلَّ عن الحق قبل قومك -أيها الرسول- أكثر الأمم السابقة.", "isBasmala": false, "translation_en": "And most of the ancients before them went astray.", "translation_id": "Dan sesungguhnya telah sesat sebelum mereka (Quraisy) sebagian besar dari orang-orang yang dahulu,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 72, "text": "وَلَقَدۡ أَرۡسَلۡنَا فِیهِم مُّنذِرِینَ ۝٧٢", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ولقد أرسلنا في تلك الأمم مرسلين أنذروهم بالعذاب فكفروا.", "isBasmala": false, "translation_en": "Even though We sent messengers to warn them.", "translation_id": "dan sesungguhnya telah Kami utus pemberi-pemberi peringatan (rasul-rasul) di kalangan mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 73, "text": "فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُنذَرِینَ ۝٧٣", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "فتأمَّل كيف كانت نهاية تلك الأمم التي أنذرت، فكفرت؟ فقد عُذِّبت، وصارت للناس عبرة.", "isBasmala": false, "translation_en": "So observe the end of those who were warned.", "translation_id": "Maka perhatikanlah bagaimana kesudahan orang-orang yang diberi peringatan itu.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 74, "text": "إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِینَ ۝٧٤", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إلا عباد الله الذين أخلصهم الله، وخصَّهم برحمته لإخلاصهم له.", "isBasmala": false, "translation_en": "Except for the sincere servants of God.", "translation_id": "Tetapi hamba-hamba Allah yang bersihkan (dari dosa tidak akan diazab).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 75, "text": "وَلَقَدۡ نَادَىٰنَا نُوحࣱ فَلَنِعۡمَ ٱلۡمُجِیبُونَ ۝٧٥", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ولقد نادانا نبينا نوح؛ لننصره على قومه، فلنعم المجيبون له نحن.", "isBasmala": false, "translation_en": "And Noah called out to Us, and We are the Best of responders.", "translation_id": "Sesungguhnya Nuh telah menyeru Kami: maka sesungguhnya sebaik-baik yang memperkenankan (adalah Kami).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 76, "text": "وَنَجَّیۡنَـٰهُ وَأَهۡلَهُۥ مِنَ ٱلۡكَرۡبِ ٱلۡعَظِیمِ ۝٧٦", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ونجيناه وأهله والمؤمنين معه مِن أذى المشركين، ومن الغرق بالطوفان العظيم.", "isBasmala": false, "translation_en": "And We saved him and his family from the great calamity.", "translation_id": "Dan Kami telah menyelamatkannya dan pengikutnya dari bencana yang besar.", "manzil": 6, "manzil_display": ""}], "449": [{"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 77, "text": "وَجَعَلۡنَا ذُرِّیَّتَهُۥ هُمُ ٱلۡبَاقِینَ ۝٧٧", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "وجعلنا ذرية نوح هم الباقين بعد غرق قومه.", "isBasmala": false, "translation_en": "And We made his descendants the survivors.", "translation_id": "Dan Kami jadikan anak cucunya orang-orang yang melanjutkan keturunan.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 78, "text": "وَتَرَكۡنَا عَلَیۡهِ فِی ٱلۡـَٔاخِرِینَ ۝٧٨", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "وأبقينا له ذِكْرًا جميلا وثناءً حسنًا فيمن جاء بعده من الناس يذكرونه به.", "isBasmala": false, "translation_en": "And We left mention of him among those who succeeded.", "translation_id": "Dan Kami abadikan untuk Nuh itu (pujian yang baik) di kalangan orang-orang yang datang kemudian;", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 79, "text": "سَلَـٰمٌ عَلَىٰ نُوحࣲ فِی ٱلۡعَـٰلَمِینَ ۝٧٩", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "أمان لنوح وسلامة له من أن يُذْكر بسوء في الآخِرين، بل تُثني عليه الأجيال من بعده.", "isBasmala": false, "translation_en": "Peace be upon Noah among all people.", "translation_id": "\"Kesejahteraan dilimpahkan atas Nuh di seluruh alam\".", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 80, "text": "إِنَّا كَذَ ٰلِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ ۝٨٠", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "مثل جزاء نوح نجزي كلَّ مَن أحسن من العباد في طاعة الله.", "isBasmala": false, "translation_en": "We thus reward the righteous.", "translation_id": "Sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 81, "text": "إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِینَ ۝٨١", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "إن نوحًا من عبادنا المصدقين المخلصين العاملين بأوامر الله.", "isBasmala": false, "translation_en": "He was one of Our believing servants.", "translation_id": "Sesungguhnya dia termasuk di antara hamba-hamba Kami yang beriman.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 82, "text": "ثُمَّ أَغۡرَقۡنَا ٱلۡـَٔاخَرِینَ ۝٨٢", "juz": 23, "hizb": "(*½ ح 45*)", "tafsir": "ثم أغرقنا الآخرين المكذبين من قومه بالطوفان، فلم تبق منهم عين تَطْرِف.", "isBasmala": false, "translation_en": "Then We drowned the others.", "translation_id": "Kemudian Kami tenggelamkan orang-orang yang lain.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 83, "text": "۞ وَإِنَّ مِن شِیعَتِهِۦ لَإِبۡرَ ٰهِیمَ ۝٨٣", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإنَّ من أشياع نوح على منهاجه وملَّته نبيَّ الله إبراهيم، حين جاء ربه بقلب بريء من كل اعتقاد باطل وخُلُق ذميم، حين قال لأبيه وقومه منكرًا عليهم: ما الذي تعبدونه من دون الله؟ أتريدون آلهة مختلَقَة تعبدونها، وتتركون عبادة الله المستحق للعبادة وحده؟ فما ظنكم برب العالمين أنه فاعل بكم إذا أشركتم به وعبدتم معه غيره؟", "isBasmala": false, "translation_en": "Of his kind was Abraham.", "translation_id": "Dan sesungguhnya Ibrahim benar-benar termasuk golongannya (Nuh).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 84, "text": "إِذۡ جَاۤءَ رَبَّهُۥ بِقَلۡبࣲ سَلِیمٍ ۝٨٤", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإنَّ من أشياع نوح على منهاجه وملَّته نبيَّ الله إبراهيم، حين جاء ربه بقلب بريء من كل اعتقاد باطل وخُلُق ذميم، حين قال لأبيه وقومه منكرًا عليهم: ما الذي تعبدونه من دون الله؟ أتريدون آلهة مختلَقَة تعبدونها، وتتركون عبادة الله المستحق للعبادة وحده؟ فما ظنكم برب العالمين أنه فاعل بكم إذا أشركتم به وعبدتم معه غيره؟", "isBasmala": false, "translation_en": "When he came to his Lord with a sound heart.", "translation_id": "(lngatlah) ketika ia datang kepada Tuhannya dengan hati yang suci:", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 85, "text": "إِذۡ قَالَ لِأَبِیهِ وَقَوۡمِهِۦ مَاذَا تَعۡبُدُونَ ۝٨٥", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإنَّ من أشياع نوح على منهاجه وملَّته نبيَّ الله إبراهيم، حين جاء ربه بقلب بريء من كل اعتقاد باطل وخُلُق ذميم، حين قال لأبيه وقومه منكرًا عليهم: ما الذي تعبدونه من دون الله؟ أتريدون آلهة مختلَقَة تعبدونها، وتتركون عبادة الله المستحق للعبادة وحده؟ فما ظنكم برب العالمين أنه فاعل بكم إذا أشركتم به وعبدتم معه غيره؟", "isBasmala": false, "translation_en": "He said to his father and his people, \"What are you worshiping?", "translation_id": "(Ingatlah) ketika ia berkata kepada bapaknya dan kaumnya: \"Apakah yang kamu sembah itu?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 86, "text": "أَىِٕفۡكًا ءَالِهَةࣰ دُونَ ٱللَّهِ تُرِیدُونَ ۝٨٦", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإنَّ من أشياع نوح على منهاجه وملَّته نبيَّ الله إبراهيم، حين جاء ربه بقلب بريء من كل اعتقاد باطل وخُلُق ذميم، حين قال لأبيه وقومه منكرًا عليهم: ما الذي تعبدونه من دون الله؟ أتريدون آلهة مختلَقَة تعبدونها، وتتركون عبادة الله المستحق للعبادة وحده؟ فما ظنكم برب العالمين أنه فاعل بكم إذا أشركتم به وعبدتم معه غيره؟", "isBasmala": false, "translation_en": "Is it falsified gods, instead of God, that you want?", "translation_id": "Apakah kamu menghendaki sembahan-sembahan selain Allah dengan jalan berbohong?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 87, "text": "فَمَا ظَنُّكُم بِرَبِّ ٱلۡعَـٰلَمِینَ ۝٨٧", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإنَّ من أشياع نوح على منهاجه وملَّته نبيَّ الله إبراهيم، حين جاء ربه بقلب بريء من كل اعتقاد باطل وخُلُق ذميم، حين قال لأبيه وقومه منكرًا عليهم: ما الذي تعبدونه من دون الله؟ أتريدون آلهة مختلَقَة تعبدونها، وتتركون عبادة الله المستحق للعبادة وحده؟ فما ظنكم برب العالمين أنه فاعل بكم إذا أشركتم به وعبدتم معه غيره؟", "isBasmala": false, "translation_en": "So what is your opinion about the Lord of the Worlds?\"", "translation_id": "Maka apakah anggapanmu terhadap Tuhan semesta alam?\"", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 88, "text": "فَنَظَرَ نَظۡرَةࣰ فِی ٱلنُّجُومِ ۝٨٨", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فنظر إبراهيم نظرة في النجوم متفكرًا فيما يعتذر به عن الخروج معهم إلى أعيادهم، فقال لهم: إني مريض. وهذا تعريض منه. فتركوه وراء ظهورهم.", "isBasmala": false, "translation_en": "Then he took a glance at the stars.", "translation_id": "Lalu ia memandang sekali pandang ke bintang-bintang.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 89, "text": "فَقَالَ إِنِّی سَقِیمࣱ ۝٨٩", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فنظر إبراهيم نظرة في النجوم متفكرًا فيما يعتذر به عن الخروج معهم إلى أعيادهم، فقال لهم: إني مريض. وهذا تعريض منه. فتركوه وراء ظهورهم.", "isBasmala": false, "translation_en": "And said, \"I am sick.\"", "translation_id": "Kemudian ia berkata: \"Sesungguhnya aku sakit\".", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 90, "text": "فَتَوَلَّوۡا۟ عَنۡهُ مُدۡبِرِینَ ۝٩٠", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فنظر إبراهيم نظرة في النجوم متفكرًا فيما يعتذر به عن الخروج معهم إلى أعيادهم، فقال لهم: إني مريض. وهذا تعريض منه. فتركوه وراء ظهورهم.", "isBasmala": false, "translation_en": "But they turned their backs on him, and went away.", "translation_id": "Lalu mereka berpaling daripadanya dengan membelakang.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 91, "text": "فَرَاغَ إِلَىٰۤ ءَالِهَتِهِمۡ فَقَالَ أَلَا تَأۡكُلُونَ ۝٩١", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فمال مسرعًا إلى أصنام قومه فقال مستهزئًا بها: ألا تاكلون هذا الطعام الذي يقدمه لكم سدنتكم؟ ما لكم لا تنطقون ولا تجيبون مَن يسألكم؟", "isBasmala": false, "translation_en": "Then he turned to their gods, and said, \"will you not eat?", "translation_id": "Kemudian ia pergi dengan diam-diam kepada berhala-berhala mereka; lalu ia berkata: \"Apakah kamu tidak makan?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 92, "text": "مَا لَكُمۡ لَا تَنطِقُونَ ۝٩٢", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فمال مسرعًا إلى أصنام قومه فقال مستهزئًا بها: ألا تاكلون هذا الطعام الذي يقدمه لكم سدنتكم؟ ما لكم لا تنطقون ولا تجيبون مَن يسألكم؟", "isBasmala": false, "translation_en": "What is it with you, that you do not speak?\"", "translation_id": "Kenapa kamu tidak menjawab?\"", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 93, "text": "فَرَاغَ عَلَیۡهِمۡ ضَرۡبَۢا بِٱلۡیَمِینِ ۝٩٣", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فأقبل على آلهتهم يضربها ويكسِّرها بيده اليمني؛ ليثبت لقومه خطأ عبادتهم لها.", "isBasmala": false, "translation_en": "Then he turned on them, striking with his right hand.", "translation_id": "Lalu dihadapinya berhala-berhala itu sambil memukulnya dengan tangan kanannya (dengan kuat).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 94, "text": "فَأَقۡبَلُوۤا۟ إِلَیۡهِ یَزِفُّونَ ۝٩٤", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فأقبلوا إليه يَعْدُون مسرعين غاضبين.", "isBasmala": false, "translation_en": "And they came running towards him.", "translation_id": "Kemudian kaumnya datang kepadanya dengan bergegas.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 95, "text": "قَالَ أَتَعۡبُدُونَ مَا تَنۡحِتُونَ ۝٩٥", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فلقيهم إبراهيم بثبات قائلا كيف تعبدون أصنامًا تنحتونها أنتم، وتصنعونها بأيديكم، وتتركون عبادة ربكم الذي خلقكم، وخلق عملكم؟", "isBasmala": false, "translation_en": "He said, \"Do you worship what you carve?", "translation_id": "Ibrahim berkata: \"Apakah kamu menyembah patung-patung yang kamu pahat itu?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 96, "text": "وَٱللَّهُ خَلَقَكُمۡ وَمَا تَعۡمَلُونَ ۝٩٦", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فلقيهم إبراهيم بثبات قائلا كيف تعبدون أصنامًا تنحتونها أنتم، وتصنعونها بأيديكم، وتتركون عبادة ربكم الذي خلقكم، وخلق عملكم؟", "isBasmala": false, "translation_en": "When God created you, and what you manufacture?\"", "translation_id": "Padahal Allah-lah yang menciptakan kamu dan apa yang kamu perbuat itu\".", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 97, "text": "قَالُوا۟ ٱبۡنُوا۟ لَهُۥ بُنۡیَـٰنࣰا فَأَلۡقُوهُ فِی ٱلۡجَحِیمِ ۝٩٧", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "(فلما قامت عليهم الحجة لجؤوا إلى القوة) وقالوا: ابنوا له بنيانًا واملؤوه حطبًا، ثم ألقوه فيه.", "isBasmala": false, "translation_en": "They said, \"Build a pyre for him, and throw him into the furnace.\"", "translation_id": "Mereka berkata: \"Dirikanlah suatu bangunan untuk (membakar) Ibrahim; lalu lemparkanlah dia ke dalam api yang menyala-nyala itu\".", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 98, "text": "فَأَرَادُوا۟ بِهِۦ كَیۡدࣰا فَجَعَلۡنَـٰهُمُ ٱلۡأَسۡفَلِینَ ۝٩٨", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فأراد قوم إبراهيم به كيدًا لإهلاكه، فجعلناهم المقهورين المغلوبين، وردَّ الله كيدهم في نحورهم، وجعل النار على إبراهيم بردًا وسلامًا.", "isBasmala": false, "translation_en": "They wished him ill, but We made them the losers.", "translation_id": "Mereka hendak melakukan tipu muslihat kepadanya, maka Kami jadikan mereka orang-orang yang hina.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 99, "text": "وَقَالَ إِنِّی ذَاهِبٌ إِلَىٰ رَبِّی سَیَهۡدِینِ ۝٩٩", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وقال إبراهيم: إني مهاجر إلى ربي من بلد قومي إلى حيث أتمكن من عبادة ربي؛ فإنه سيدلني على الخير في ديني ودنياي. رب أعطني ولدًا صالحًا.", "isBasmala": false, "translation_en": "He said, \"I am going towards my Lord, and He will guide me.\"", "translation_id": "Dan Ibrahim berkata: \"Sesungguhnya aku pergi menghadap kepada Tuhanku, dan Dia akan memberi petunjuk kepadaku.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 100, "text": "رَبِّ هَبۡ لِی مِنَ ٱلصَّـٰلِحِینَ ۝١٠٠", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وقال إبراهيم: إني مهاجر إلى ربي من بلد قومي إلى حيث أتمكن من عبادة ربي؛ فإنه سيدلني على الخير في ديني ودنياي. رب أعطني ولدًا صالحًا.", "isBasmala": false, "translation_en": "\"My Lord, give me one of the righteous.\"", "translation_id": "Ya Tuhanku, anugrahkanlah kepadaku (seorang anak) yang termasuk orang-orang yang saleh.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 101, "text": "فَبَشَّرۡنَـٰهُ بِغُلَـٰمٍ حَلِیمࣲ ۝١٠١", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فأجبنا له دعوته، وبشَّرناه بغلام حليم، أي: يكون حليمًا في كبره، وهو إسماعيل.", "isBasmala": false, "translation_en": "So We gave him good news of a clement boy.", "translation_id": "Maka Kami beri dia khabar gembira dengan seorang anak yang amat sabar.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 102, "text": "فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡیَ قَالَ یَـٰبُنَیَّ إِنِّیۤ أَرَىٰ فِی ٱلۡمَنَامِ أَنِّیۤ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ یَـٰۤأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِیۤ إِن شَاۤءَ ٱللَّهُ مِنَ ٱلصَّـٰبِرِینَ ۝١٠٢", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فلما كَبِر إسماعيل ومشى مع أبيه قال له أبوه: إني أرى في المنام أني أذبحك، فما رأيك؟ (ورؤيا الأنبياء حق) فقال إسماعيل مُرْضيًا ربه، بارًّا بوالده، معينًا له على طاعة الله: أمض ما أمرك الله به مِن ذبحي، ستجدني -إن شاء الله- صابرًا طائعًا محتسبًا.", "isBasmala": false, "translation_en": "Then, when he was old enough to accompany him, he said, \"O My son, I see in a dream that I am sacrificing you; see what you think.\" He said, \"O my Father, do as you are commanded; you will find me, God willing, one of the steadfast.\"", "translation_id": "Maka tatkala anak itu sampai (pada umur sanggup) berusaha bersama-sama Ibrahim, Ibrahim berkata: \"Hai anakku sesungguhnya aku melihat dalam mimpi bahwa aku menyembelihmu. Maka fikirkanlah apa pendapatmu!\" Ia menjawab: \"Hai bapakku, kerjakanlah apa yang diperintahkan kepadamu; insya Allah kamu akan mendapatiku termasuk orang-orang yang sabar\".", "manzil": 6, "manzil_display": ""}], "450": [{"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 103, "text": "فَلَمَّاۤ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِینِ ۝١٠٣", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فلما استسلما لأمر الله وانقادا له، وألقى إبراهيم ابنه على جبينه -وهو جانب الجبهة- على الأرض؛ ليذبحه.", "isBasmala": false, "translation_en": "Then, when they had submitted, and he put his forehead down.", "translation_id": "Tatkala keduanya telah berserah diri dan Ibrahim membaringkan anaknya atas pelipis(nya), (nyatalah kesabaran keduanya).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 104, "text": "وَنَـٰدَیۡنَـٰهُ أَن یَـٰۤإِبۡرَ ٰهِیمُ ۝١٠٤", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "ونادينا إبراهيم في تلك الحالة العصيبة: أن يا إبراهيم، قد فعلتَ ما أُمرت به وصَدَّقْتَ رؤياك، إنا كما جزيناك على تصديقك نجزي الذين أحسنوا مثلك، فنخلِّصهم من الشدائد في الدنيا والآخرة.", "isBasmala": false, "translation_en": "We called out to him, \"O Abraham!", "translation_id": "Dan Kami panggillah dia: \"Hai Ibrahim,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 105, "text": "قَدۡ صَدَّقۡتَ ٱلرُّءۡیَاۤۚ إِنَّا كَذَ ٰلِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ ۝١٠٥", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "ونادينا إبراهيم في تلك الحالة العصيبة: أن يا إبراهيم، قد فعلتَ ما أُمرت به وصَدَّقْتَ رؤياك، إنا كما جزيناك على تصديقك نجزي الذين أحسنوا مثلك، فنخلِّصهم من الشدائد في الدنيا والآخرة.", "isBasmala": false, "translation_en": "You have fulfilled the vision.\" Thus We reward the doers of good.", "translation_id": "sesungguhnya kamu telah membenarkan mimpi itu sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 106, "text": "إِنَّ هَـٰذَا لَهُوَ ٱلۡبَلَـٰۤؤُا۟ ٱلۡمُبِینُ ۝١٠٦", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "إن الأمر بذبح ابنك هو الابتلاء الشاق الذي أبان عن صدق إيمانك.", "isBasmala": false, "translation_en": "This was certainly an evident test.", "translation_id": "Sesungguhnya ini benar-benar suatu ujian yang nyata.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 107, "text": "وَفَدَیۡنَـٰهُ بِذِبۡحٍ عَظِیمࣲ ۝١٠٧", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "واستنقذنا إسماعيل، فجعلنا بديلا عنه كبشًا عظيمًا.", "isBasmala": false, "translation_en": "And We redeemed him with a great sacrifice.", "translation_id": "Dan Kami tebus anak itu dengan seekor sembelihan yang besar.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 108, "text": "وَتَرَكۡنَا عَلَیۡهِ فِی ٱلۡـَٔاخِرِینَ ۝١٠٨", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وأبقينا لإبراهيم ثناءً حسنًا في الأمم بعده.", "isBasmala": false, "translation_en": "And We left with him for later generations.", "translation_id": "Kami abadikan untuk Ibrahim itu (pujian yang baik) di kalangan orang-orang yang datang kemudian,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 109, "text": "سَلَـٰمٌ عَلَىٰۤ إِبۡرَ ٰهِیمَ ۝١٠٩", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "تحيةٌ لإبراهيم من عند الله، ودعاءٌ له بالسلامة من كل آفة.", "isBasmala": false, "translation_en": "Peace be upon Abraham.", "translation_id": "(yaitu)\"Kesejahteraan dilimpahkan atas Ibrahim\".", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 110, "text": "كَذَ ٰلِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ ۝١١٠", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "كما جزينا إبراهيم على طاعته لنا وامتثاله أمرنا، نجزي المحسنين من عبادنا.", "isBasmala": false, "translation_en": "Thus We reward the doers of good.", "translation_id": "Demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 111, "text": "إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِینَ ۝١١١", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "إنه من عبادنا المؤمنين الذين أعطَوا العبودية حقها.", "isBasmala": false, "translation_en": "He was one of Our believing servants.", "translation_id": "Sesungguhnya ia termasuk hamba-hamba Kami yang beriman.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 112, "text": "وَبَشَّرۡنَـٰهُ بِإِسۡحَـٰقَ نَبِیࣰّا مِّنَ ٱلصَّـٰلِحِینَ ۝١١٢", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وبشَّرنا إبراهيم بولده إسحاق نبيًّا من الصالحين؛ جزاء له على صبره ورضاه بأمر ربه، وطاعته له.", "isBasmala": false, "translation_en": "And We gave him good news of Isaac, a prophet, one of the righteous.", "translation_id": "Dan Kami beri dia kabar gembira dengan (kelahiran) Ishaq seorang nabi yang termasuk orang-orang yang saleh.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 113, "text": "وَبَـٰرَكۡنَا عَلَیۡهِ وَعَلَىٰۤ إِسۡحَـٰقَۚ وَمِن ذُرِّیَّتِهِمَا مُحۡسِنࣱ وَظَالِمࣱ لِّنَفۡسِهِۦ مُبِینࣱ ۝١١٣", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وأنزلنا عليهما البركة. ومِن ذريتهما من هو مطيع لربه، محسن لنفسه، ومَن هو ظالم لها ظلمًا بيِّنًا بكفره ومعصيته.", "isBasmala": false, "translation_en": "And We blessed him, and Isaac. But among their descendants are some who are righteous, and some who are clearly unjust to themselves.", "translation_id": "Kami limpahkan keberkatan atasnya dan atas Ishaq. Dan diantara anak cucunya ada yang berbuat baik dan ada (pula) yang Zalim terhadap dirinya sendiri dengan nyata.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 114, "text": "وَلَقَدۡ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَـٰرُونَ ۝١١٤", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "ولقد مننَّا على موسى وهارون بالنبوة والرسالة، ونجيناهما وقومهما من الغرق، وما كانوا فيه من عبودية ومَذلَّة.", "isBasmala": false, "translation_en": "And We blessed Moses and Aaron.", "translation_id": "Dan sesungguhnya Kami telah melimpahkan nikmat atas Musa dan Harun.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 115, "text": "وَنَجَّیۡنَـٰهُمَا وَقَوۡمَهُمَا مِنَ ٱلۡكَرۡبِ ٱلۡعَظِیمِ ۝١١٥", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "ولقد مننَّا على موسى وهارون بالنبوة والرسالة، ونجيناهما وقومهما من الغرق، وما كانوا فيه من عبودية ومَذلَّة.", "isBasmala": false, "translation_en": "And We delivered them and their people from the terrible disaster.", "translation_id": "Dan Kami selamatkan keduanya dan kaumnya dari bencana yang besar.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 116, "text": "وَنَصَرۡنَـٰهُمۡ فَكَانُوا۟ هُمُ ٱلۡغَـٰلِبِینَ ۝١١٦", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "ونصرناهم، فكانت لهم العزة والنصرة والغلبة على فرعون وآله.", "isBasmala": false, "translation_en": "And We supported them, and so they were the victors.", "translation_id": "Dan Kami tolong mereka, maka jadilah mereka orang-orang yang menang.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 117, "text": "وَءَاتَیۡنَـٰهُمَا ٱلۡكِتَـٰبَ ٱلۡمُسۡتَبِینَ ۝١١٧", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وآتيناهما التوراة البينة، وهديناهما الطريق المستقيم الذي لا اعوجاج فيه، وهو الإسلام دين الله الذي ابتعث به أنبياءه، وأبقينا لهما ثناءً حسنًا وذكرًا جميلا فيمن بعدهما.", "isBasmala": false, "translation_en": "And We gave them the Clarifying Scripture.", "translation_id": "Dan Kami berikan kepada keduanya kitab yang sangat jelas.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 118, "text": "وَهَدَیۡنَـٰهُمَا ٱلصِّرَ ٰطَ ٱلۡمُسۡتَقِیمَ ۝١١٨", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وآتيناهما التوراة البينة، وهديناهما الطريق المستقيم الذي لا اعوجاج فيه، وهو الإسلام دين الله الذي ابتعث به أنبياءه، وأبقينا لهما ثناءً حسنًا وذكرًا جميلا فيمن بعدهما.", "isBasmala": false, "translation_en": "And We guided them upon the straight path.", "translation_id": "Dan Kami tunjuki keduanya ke jalan yang lurus.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 119, "text": "وَتَرَكۡنَا عَلَیۡهِمَا فِی ٱلۡـَٔاخِرِینَ ۝١١٩", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وآتيناهما التوراة البينة، وهديناهما الطريق المستقيم الذي لا اعوجاج فيه، وهو الإسلام دين الله الذي ابتعث به أنبياءه، وأبقينا لهما ثناءً حسنًا وذكرًا جميلا فيمن بعدهما.", "isBasmala": false, "translation_en": "And We left with them for later generations.", "translation_id": "Dan Kami abadikan untuk keduanya (pujian yang baik) dikalangan orang-orang yang datang kemudian;", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 120, "text": "سَلَـٰمٌ عَلَىٰ مُوسَىٰ وَهَـٰرُونَ ۝١٢٠", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "تحيةٌ لموسى وهارون من عند الله، وثناءٌ ودعاءٌ لهما بالسلامة من كل آفة، كما جزيناهما الجزاء الحسن نجزي المحسنين من عبادنا المخلصين لنا بالصدق والإيمان والعمل. إنهما من عبادنا الراسخين في الإيمان.", "isBasmala": false, "translation_en": "Peace be upon Moses and Aaron.", "translation_id": "(yaitu): \"Kesejahteraan dilimpahkan atas Musa dan Harun\".", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 121, "text": "إِنَّا كَذَ ٰلِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ ۝١٢١", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "تحيةٌ لموسى وهارون من عند الله، وثناءٌ ودعاءٌ لهما بالسلامة من كل آفة، كما جزيناهما الجزاء الحسن نجزي المحسنين من عبادنا المخلصين لنا بالصدق والإيمان والعمل. إنهما من عبادنا الراسخين في الإيمان.", "isBasmala": false, "translation_en": "Thus We reward the righteous.", "translation_id": "Sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 122, "text": "إِنَّهُمَا مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِینَ ۝١٢٢", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "تحيةٌ لموسى وهارون من عند الله، وثناءٌ ودعاءٌ لهما بالسلامة من كل آفة، كما جزيناهما الجزاء الحسن نجزي المحسنين من عبادنا المخلصين لنا بالصدق والإيمان والعمل. إنهما من عبادنا الراسخين في الإيمان.", "isBasmala": false, "translation_en": "They were of Our believing servants.", "translation_id": "Sesungguhnya keduanya termasuk hamba-hamba Kami yang beriman.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 123, "text": "وَإِنَّ إِلۡیَاسَ لَمِنَ ٱلۡمُرۡسَلِینَ ۝١٢٣", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإن عبدنا إلياس لمن الذين أكرمناهم بالنبوة والرسالة، إذ قال لقومه من بني إسرائيل: اتقوا الله وحده وخافوه، ولا تشركوا معه غيره، كيف تعبدون صنمًا، وتتركون عبادة الله أحسن الخالقين، وهو ربكم الذي خلقكم، وخلق آباءكم الماضين قبلكم؟", "isBasmala": false, "translation_en": "Also Elijah was one of the messengers.", "translation_id": "Dan sesungguhnya Ilyas benar-benar termasuk salah seorang rasul-rasul.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 124, "text": "إِذۡ قَالَ لِقَوۡمِهِۦۤ أَلَا تَتَّقُونَ ۝١٢٤", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإن عبدنا إلياس لمن الذين أكرمناهم بالنبوة والرسالة، إذ قال لقومه من بني إسرائيل: اتقوا الله وحده وخافوه، ولا تشركوا معه غيره، كيف تعبدون صنمًا، وتتركون عبادة الله أحسن الخالقين، وهو ربكم الذي خلقكم، وخلق آباءكم الماضين قبلكم؟", "isBasmala": false, "translation_en": "He said to his people, \"Do you not fear?", "translation_id": "(ingatlah) ketika ia berkata kepada kaumnya: \"Mengapa kamu tidak bertakwa?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 125, "text": "أَتَدۡعُونَ بَعۡلࣰا وَتَذَرُونَ أَحۡسَنَ ٱلۡخَـٰلِقِینَ ۝١٢٥", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإن عبدنا إلياس لمن الذين أكرمناهم بالنبوة والرسالة، إذ قال لقومه من بني إسرائيل: اتقوا الله وحده وخافوه، ولا تشركوا معه غيره، كيف تعبدون صنمًا، وتتركون عبادة الله أحسن الخالقين، وهو ربكم الذي خلقكم، وخلق آباءكم الماضين قبلكم؟", "isBasmala": false, "translation_en": "Do you call on Baal, and forsake the Best of creators?", "translation_id": "Patutkah kamu menyembah Ba'l dan kamu tinggalkan sebaik-baik Pencipta,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 126, "text": "ٱللَّهَ رَبَّكُمۡ وَرَبَّ ءَابَاۤىِٕكُمُ ٱلۡأَوَّلِینَ ۝١٢٦", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإن عبدنا إلياس لمن الذين أكرمناهم بالنبوة والرسالة، إذ قال لقومه من بني إسرائيل: اتقوا الله وحده وخافوه، ولا تشركوا معه غيره، كيف تعبدون صنمًا، وتتركون عبادة الله أحسن الخالقين، وهو ربكم الذي خلقكم، وخلق آباءكم الماضين قبلكم؟", "isBasmala": false, "translation_en": "God is your Lord, and the Lord of your ancestors.\"", "translation_id": "(yaitu) Allah Tuhanmu dan Tuhan bapak-bapakmu yang terdahulu?\"", "manzil": 6, "manzil_display": ""}], "451": [{"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 127, "text": "فَكَذَّبُوهُ فَإِنَّهُمۡ لَمُحۡضَرُونَ ۝١٢٧", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فكذب قوم إلياس نبيهم، فليجمعنهم الله يوم القيامة للحساب والعقاب، إلا عباد الله الذين أخلصوا دينهم لله، فإنهم ناجون من عذابه.", "isBasmala": false, "translation_en": "But they called him a liar, and thus they will be brought forward.", "translation_id": "Maka mereka mendustakannya, karena itu mereka akan diseret (ke neraka),", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 128, "text": "إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِینَ ۝١٢٨", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فكذب قوم إلياس نبيهم، فليجمعنهم الله يوم القيامة للحساب والعقاب، إلا عباد الله الذين أخلصوا دينهم لله، فإنهم ناجون من عذابه.", "isBasmala": false, "translation_en": "Except for God's sincere servants.", "translation_id": "kecuali hamba-hamba Allah yang dibersihkan (dari dosa).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 129, "text": "وَتَرَكۡنَا عَلَیۡهِ فِی ٱلۡـَٔاخِرِینَ ۝١٢٩", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وجعلنا لإلياس ثناءً جميلا في الأمم بعده. تحية من الله، وثناءٌ على إلياس. وكما جزينا إلياس الجزاء الحسن على طاعته، نجزي المحسنين من عبادنا المؤمنين. إنه من عباد الله المؤمنين المخلصين له العاملين بأوامره.", "isBasmala": false, "translation_en": "And We left with him for later generations.", "translation_id": "Dan Kami abadikan untuk Ilyas (pujian yang baik) di kalangan orang-orang yang datang kemudian.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 130, "text": "سَلَـٰمٌ عَلَىٰۤ إِلۡ یَاسِینَ ۝١٣٠", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وجعلنا لإلياس ثناءً جميلا في الأمم بعده. تحية من الله، وثناءٌ على إلياس. وكما جزينا إلياس الجزاء الحسن على طاعته، نجزي المحسنين من عبادنا المؤمنين. إنه من عباد الله المؤمنين المخلصين له العاملين بأوامره.", "isBasmala": false, "translation_en": "Peace be upon the House of Elijah.", "translation_id": "(yaitu): \"Kesejahteraan dilimpahkan atas Ilyas?\"", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 131, "text": "إِنَّا كَذَ ٰلِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ ۝١٣١", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وجعلنا لإلياس ثناءً جميلا في الأمم بعده. تحية من الله، وثناءٌ على إلياس. وكما جزينا إلياس الجزاء الحسن على طاعته، نجزي المحسنين من عبادنا المؤمنين. إنه من عباد الله المؤمنين المخلصين له العاملين بأوامره.", "isBasmala": false, "translation_en": "Thus We reward the virtuous.", "translation_id": "Sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 132, "text": "إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُؤۡمِنِینَ ۝١٣٢", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وجعلنا لإلياس ثناءً جميلا في الأمم بعده. تحية من الله، وثناءٌ على إلياس. وكما جزينا إلياس الجزاء الحسن على طاعته، نجزي المحسنين من عبادنا المؤمنين. إنه من عباد الله المؤمنين المخلصين له العاملين بأوامره.", "isBasmala": false, "translation_en": "He was one of Our believing servants.", "translation_id": "Sesungguhnya dia termasuk hamba-hamba Kami yang beriman.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 133, "text": "وَإِنَّ لُوطࣰا لَّمِنَ ٱلۡمُرۡسَلِینَ ۝١٣٣", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإن عبدنا لوطًا اصطفيناه، فجعلناه من المرسلين، إذ نجيناه وأهله أجمعين من العذاب، إلا عجوزًا هَرِمة، هي زوجته، هلكت مع الذين هلكوا من قومها لكفرها.", "isBasmala": false, "translation_en": "And Lot was one of the messengers.", "translation_id": "Sesungguhnya Luth benar-benar salah seorang rasul.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 134, "text": "إِذۡ نَجَّیۡنَـٰهُ وَأَهۡلَهُۥۤ أَجۡمَعِینَ ۝١٣٤", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإن عبدنا لوطًا اصطفيناه، فجعلناه من المرسلين، إذ نجيناه وأهله أجمعين من العذاب، إلا عجوزًا هَرِمة، هي زوجته، هلكت مع الذين هلكوا من قومها لكفرها.", "isBasmala": false, "translation_en": "We saved him and his family, all of them.", "translation_id": "(Ingatlah) ketika Kami selamatkan dia dan keluarganya (pengikut-pengikutnya) semua,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 135, "text": "إِلَّا عَجُوزࣰا فِی ٱلۡغَـٰبِرِینَ ۝١٣٥", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإن عبدنا لوطًا اصطفيناه، فجعلناه من المرسلين، إذ نجيناه وأهله أجمعين من العذاب، إلا عجوزًا هَرِمة، هي زوجته، هلكت مع الذين هلكوا من قومها لكفرها.", "isBasmala": false, "translation_en": "Except for an old woman who lagged behind.", "translation_id": "kecuali seorang perempuan tua (isterinya yang berada) bersama-sama orang yang tinggal.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 136, "text": "ثُمَّ دَمَّرۡنَا ٱلۡـَٔاخَرِینَ ۝١٣٦", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "ثم أهلكنا الباقين المكذبين من قومه.", "isBasmala": false, "translation_en": "Then We annihilated the others.", "translation_id": "Kemudian Kami binasakan orang-orang yang lain.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 137, "text": "وَإِنَّكُمۡ لَتَمُرُّونَ عَلَیۡهِم مُّصۡبِحِینَ ۝١٣٧", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإنكم -يا أهل \"مكة\"- لتمرون في أسفاركم على منازل قوم لوط وآثارهم وقت الصباح، وتمرون عليها ليلا. أفلا تعقلون، فتخافوا أن يصيبكم مثل ما أصابهم؟", "isBasmala": false, "translation_en": "You pass by them in the morning.", "translation_id": "Dan sesungguhnya kamu (hai penduduk Mekah) benar-benar akan melalui (bekas-bekas) mereka di waktu pagi,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 138, "text": "وَبِٱلَّیۡلِۚ أَفَلَا تَعۡقِلُونَ ۝١٣٨", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإنكم -يا أهل \"مكة\"- لتمرون في أسفاركم على منازل قوم لوط وآثارهم وقت الصباح، وتمرون عليها ليلا. أفلا تعقلون، فتخافوا أن يصيبكم مثل ما أصابهم؟", "isBasmala": false, "translation_en": "And at night. Do you not understand?", "translation_id": "dan di waktu malam. Maka apakah kamu tidak memikirkan?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 139, "text": "وَإِنَّ یُونُسَ لَمِنَ ٱلۡمُرۡسَلِینَ ۝١٣٩", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإن عبدنا يونس اصطفيناه وجعلناه من المرسلين، إذ هرب من بلده غاضبًا على قومه، وركب سفينة مملوءة ركابًا وأمتعة.", "isBasmala": false, "translation_en": "And Jonah was one of the messengers.", "translation_id": "Sesungguhnya Yunus benar-benar salah seorang rasul,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 140, "text": "إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ ۝١٤٠", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وإن عبدنا يونس اصطفيناه وجعلناه من المرسلين، إذ هرب من بلده غاضبًا على قومه، وركب سفينة مملوءة ركابًا وأمتعة.", "isBasmala": false, "translation_en": "When he fled to the laden boat.", "translation_id": "(ingatlah) ketika ia lari, ke kapal yang penuh muatan,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 141, "text": "فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِینَ ۝١٤١", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "وأحاطت بها الأمواج العظيمة، فاقترع ركاب السفينة لتخفيف الحمولة خوف الغرق، فكان يونس من المغلوبين.", "isBasmala": false, "translation_en": "He gambled and lost.", "translation_id": "kemudian ia ikut berundi lalu dia termasuk orang-orang yang kalah dalam undian.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 142, "text": "فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِیمࣱ ۝١٤٢", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فأُلقي في البحر، فابتلعه الحوت، ويونس عليه السلام آتٍ بما يُلام عليه.", "isBasmala": false, "translation_en": "Then the fish swallowed him, and he was to blame.", "translation_id": "Maka ia ditelan oleh ikan besar dalam keadaan tercela.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 143, "text": "فَلَوۡلَاۤ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِینَ ۝١٤٣", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فلولا ما تقدَّم له من كثرة العبادة والعمل الصالح قبل وقوعه في بطن الحوت، وتسبيحه، وهو في بطن الحوت بقوله: {لا إِلَهَ إِلا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ (21:87)}، لمكث في بطن الحوت، وصار له قبرًا إلى يوم القيامة.", "isBasmala": false, "translation_en": "Had he not been one of those who praised.", "translation_id": "Maka kalau sekiranya dia tidak termasuk orang-orang yang banyak mengingat Allah,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 144, "text": "لَلَبِثَ فِی بَطۡنِهِۦۤ إِلَىٰ یَوۡمِ یُبۡعَثُونَ ۝١٤٤", "juz": 23, "hizb": "(*¾ ح 45*)", "tafsir": "فلولا ما تقدَّم له من كثرة العبادة والعمل الصالح قبل وقوعه في بطن الحوت، وتسبيحه، وهو في بطن الحوت بقوله: {لا إِلَهَ إِلا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ (21:87)}، لمكث في بطن الحوت، وصار له قبرًا إلى يوم القيامة.", "isBasmala": false, "translation_en": "He would have stayed in its belly until the Day they are raised.", "translation_id": "niscaya ia akan tetap tinggal di perut ikan itu sampai hari berbangkit.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 145, "text": "۞ فَنَبَذۡنَـٰهُ بِٱلۡعَرَاۤءِ وَهُوَ سَقِیمࣱ ۝١٤٥", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "فطرحناه من بطن الحوت، وألقيناه في أرض خالية عارية من الشجر والبناء، وهو ضعيف البدن.", "isBasmala": false, "translation_en": "Then We threw him into the wilderness, and he was sick.", "translation_id": "Kemudian Kami lemparkan dia ke daerah yang tandus, sedang ia dalam keadaan sakit.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 146, "text": "وَأَنۢبَتۡنَا عَلَیۡهِ شَجَرَةࣰ مِّن یَقۡطِینࣲ ۝١٤٦", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وأنبتنا عليه شجرة من القَرْع تظلُّه، وينتفع بها.", "isBasmala": false, "translation_en": "And We made a gourd tree grow over him.", "translation_id": "Dan Kami tumbuhkan untuk dia sebatang pohon dari jenis labu.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 147, "text": "وَأَرۡسَلۡنَـٰهُ إِلَىٰ مِا۟ئَةِ أَلۡفٍ أَوۡ یَزِیدُونَ ۝١٤٧", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وأرسلناه إلى مائة ألف من قومه بل يزيدون، فصدَّقوا وعملوا بما جاء به، فمتعناهم بحياتهم إلى وقت بلوغ آجالهم.", "isBasmala": false, "translation_en": "Then We sent him to a hundred thousand, or more.", "translation_id": "Dan Kami utus dia kepada seratus ribu orang atau lebih.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 148, "text": "فَـَٔامَنُوا۟ فَمَتَّعۡنَـٰهُمۡ إِلَىٰ حِینࣲ ۝١٤٨", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وأرسلناه إلى مائة ألف من قومه بل يزيدون، فصدَّقوا وعملوا بما جاء به، فمتعناهم بحياتهم إلى وقت بلوغ آجالهم.", "isBasmala": false, "translation_en": "And they believed, so We gave them enjoyment for a while.", "translation_id": "Lalu mereka beriman, karena itu Kami anugerahkan kenikmatan hidup kepada mereka hingga waktu yang tertentu.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 149, "text": "فَٱسۡتَفۡتِهِمۡ أَلِرَبِّكَ ٱلۡبَنَاتُ وَلَهُمُ ٱلۡبَنُونَ ۝١٤٩", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "فاسأل -أيها الرسول- قومك: كيف جعلوا لله البنات اللاتي يكرهونهنَّ، ولأنفسهم البنين الذين يريدونهم؟", "isBasmala": false, "translation_en": "Ask them, \"Are the daughters for your Lord, while for them the sons?\"", "translation_id": "Tanyakanlah (ya Muhammad) kepada mereka (orang-orang kafir Mekah): \"Apakah untuk Tuhanmu anak-anak perempuan dan untuk mereka anak laki-laki,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 150, "text": "أَمۡ خَلَقۡنَا ٱلۡمَلَـٰۤىِٕكَةَ إِنَـٰثࣰا وَهُمۡ شَـٰهِدُونَ ۝١٥٠", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "واسألهم أخَلَقْنا الملائكة إناثًا، وهم حاضرون؟", "isBasmala": false, "translation_en": "Or did We create the angels females, as they witnessed?\"", "translation_id": "atau apakah Kami menciptakan malaikat-malaikat berupa perempuan dan mereka menyaksikan(nya)?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 151, "text": "أَلَاۤ إِنَّهُم مِّنۡ إِفۡكِهِمۡ لَیَقُولُونَ ۝١٥١", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وإنَّ مِن كذبهم قولهم: ولَد الله، وإنهم لكاذبون؛ لأنهم يقولون ما لا يعلمون.", "isBasmala": false, "translation_en": "No indeed! It is one of their lies when they say.", "translation_id": "Ketahuilah bahwa sesungguhnya mereka dengan kebohongannya benar-benar mengatakan:", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 152, "text": "وَلَدَ ٱللَّهُ وَإِنَّهُمۡ لَكَـٰذِبُونَ ۝١٥٢", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وإنَّ مِن كذبهم قولهم: ولَد الله، وإنهم لكاذبون؛ لأنهم يقولون ما لا يعلمون.", "isBasmala": false, "translation_en": "\"God has begotten.\" They are indeed lying.", "translation_id": "\"Allah beranak\". Dan sesungguhnya mereka benar-benar orang yang berdusta.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 153, "text": "أَصۡطَفَى ٱلۡبَنَاتِ عَلَى ٱلۡبَنِینَ ۝١٥٣", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "لأي شيء يختار الله البنات دون البنين؟", "isBasmala": false, "translation_en": "So He preferred girls over boys?", "translation_id": "Apakah Tuhan memilih (mengutamakan) anak-anak perempuan daripada anak laki-laki?", "manzil": 6, "manzil_display": ""}], "452": [{"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 154, "text": "مَا لَكُمۡ كَیۡفَ تَحۡكُمُونَ ۝١٥٤", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "بئس الحكم ما تحكمونه -أيها القوم- أن يكون لله البنات ولكم البنون، وأنتم لا ترضون البنات لأنفسكم.", "isBasmala": false, "translation_en": "What is the matter with you? How do you judge?", "translation_id": "Apakah yang terjadi padamu? Bagaimana (caranya) kamu menetapkan?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 155, "text": "أَفَلَا تَذَكَّرُونَ ۝١٥٥", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "أفلا تذكرون أنه لا يجوز ولا ينبغي أن يكون له ولد؟ تعالى الله عن ذلك علوًّا كبيرًا.", "isBasmala": false, "translation_en": "Will you not reflect?", "translation_id": "Maka apakah kamu tidak memikirkan?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 156, "text": "أَمۡ لَكُمۡ سُلۡطَـٰنࣱ مُّبِینࣱ ۝١٥٦", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "بل ألكم حجة بيِّنة على قولكم وافترائكم؟", "isBasmala": false, "translation_en": "Or do you have some clear proof?", "translation_id": "Atau apakah kamu mempunyai bukti yang nyata?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 157, "text": "فَأۡتُوا۟ بِكِتَـٰبِكُمۡ إِن كُنتُمۡ صَـٰدِقِینَ ۝١٥٧", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "إن كانت لكم حجة في كتاب من عند الله فأتوا بها، إن كنتم صادقين في قولكم؟", "isBasmala": false, "translation_en": "Then bring your book, if you are telling the truth.", "translation_id": "Maka bawalah kitabmu jika kamu memang orang-orang yang benar.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 158, "text": "وَجَعَلُوا۟ بَیۡنَهُۥ وَبَیۡنَ ٱلۡجِنَّةِ نَسَبࣰاۚ وَلَقَدۡ عَلِمَتِ ٱلۡجِنَّةُ إِنَّهُمۡ لَمُحۡضَرُونَ ۝١٥٨", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وجعل المشركون بين الله والملائكة قرابة ونسبًا، ولقد علمت الملائكة أن المشركين محضرون للعذاب يوم القيامة.", "isBasmala": false, "translation_en": "And they invented a relationship between Him and the jinn. But the jinn know that they will be arraigned.", "translation_id": "Dan mereka adakan (hubungan) nasab antara Allah dan antara jin. Dan sesungguhnya jin mengetahui bahwa mereka benar-benar akan diseret (ke neraka),", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 159, "text": "سُبۡحَـٰنَ ٱللَّهِ عَمَّا یَصِفُونَ ۝١٥٩", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "تنزَّه الله عن كل ما لا يليق به ممَّا يصفه به الكافرون.", "isBasmala": false, "translation_en": "God be glorified, far above what they allege.", "translation_id": "Maha Suci Allah dari apa yang mereka sifatkan,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 160, "text": "إِلَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِینَ ۝١٦٠", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "لكن عباد الله المخلصين له في عبادته لا يصفونه إلا بما يليق بجلاله سبحانه.", "isBasmala": false, "translation_en": "Except for God's sincere servants.", "translation_id": "Kecuali hamba-hamba Allah yang dibersihkan dari (dosa).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 161, "text": "فَإِنَّكُمۡ وَمَا تَعۡبُدُونَ ۝١٦١", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "فإنكم -أيها المشركون بالله- وما تعبدون من دون الله من آلهة، ما أنتم بمضلِّين أحدًا إلا مَن قدَّر الله عز وجل عليه أن يَصْلَى الجحيم؛ لكفره وظلمه.", "isBasmala": false, "translation_en": "Surely, you and what you serve.", "translation_id": "Maka sesungguhnya kamu dan apa-apa yang kamu sembah itu,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 162, "text": "مَاۤ أَنتُمۡ عَلَیۡهِ بِفَـٰتِنِینَ ۝١٦٢", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "فإنكم -أيها المشركون بالله- وما تعبدون من دون الله من آلهة، ما أنتم بمضلِّين أحدًا إلا مَن قدَّر الله عز وجل عليه أن يَصْلَى الجحيم؛ لكفره وظلمه.", "isBasmala": false, "translation_en": "Cannot seduce away from Him.", "translation_id": "Sekali-kali tidak dapat menyesatkan (seseorang) terhadap Allah,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 163, "text": "إِلَّا مَنۡ هُوَ صَالِ ٱلۡجَحِیمِ ۝١٦٣", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "فإنكم -أيها المشركون بالله- وما تعبدون من دون الله من آلهة، ما أنتم بمضلِّين أحدًا إلا مَن قدَّر الله عز وجل عليه أن يَصْلَى الجحيم؛ لكفره وظلمه.", "isBasmala": false, "translation_en": "Except for he who will be roasting in Hell.", "translation_id": "kecuali orang-orang yang akan masuk neraka yang menyala.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 164, "text": "وَمَا مِنَّاۤ إِلَّا لَهُۥ مَقَامࣱ مَّعۡلُومࣱ ۝١٦٤", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "قالت الملائكة: وما منا أحدٌ إلا له مقام في السماء معلوم، وإنا لنحن الواقفون صفوفًا في عبادة الله وطاعته، وإنا لنحن المنزِّهون الله عن كل ما لا يليق به.", "isBasmala": false, "translation_en": "\"There is not one of us but has an assigned position.", "translation_id": "Tiada seorangpun di antara kami (malaikat) melainkan mempunyai kedudukan yang tertentu,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 165, "text": "وَإِنَّا لَنَحۡنُ ٱلصَّاۤفُّونَ ۝١٦٥", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "قالت الملائكة: وما منا أحدٌ إلا له مقام في السماء معلوم، وإنا لنحن الواقفون صفوفًا في عبادة الله وطاعته، وإنا لنحن المنزِّهون الله عن كل ما لا يليق به.", "isBasmala": false, "translation_en": "And we are the arrangers.", "translation_id": "dan sesungguhnya kami benar-benar bershaf-shaf (dalam menunaikan perintah Allah).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 166, "text": "وَإِنَّا لَنَحۡنُ ٱلۡمُسَبِّحُونَ ۝١٦٦", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "قالت الملائكة: وما منا أحدٌ إلا له مقام في السماء معلوم، وإنا لنحن الواقفون صفوفًا في عبادة الله وطاعته، وإنا لنحن المنزِّهون الله عن كل ما لا يليق به.", "isBasmala": false, "translation_en": "And we are the glorifiers.\"", "translation_id": "Dan sesungguhnya kami benar-benar bertasbih (kepada Allah).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 167, "text": "وَإِن كَانُوا۟ لَیَقُولُونَ ۝١٦٧", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وإن كفار \"مكة\" ليقولون قبل بعثتك -أيها الرسول-: لو جاءنا من الكتب والأنبياء ما جاء الأولين قبلنا، لكنا عباد الله الصادقين في الإيمان، المخلَصين في العبادة.", "isBasmala": false, "translation_en": "Even though they used to say.", "translation_id": "Sesungguhnya mereka benar-benar akan berkata:", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 168, "text": "لَوۡ أَنَّ عِندَنَا ذِكۡرࣰا مِّنَ ٱلۡأَوَّلِینَ ۝١٦٨", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وإن كفار \"مكة\" ليقولون قبل بعثتك -أيها الرسول-: لو جاءنا من الكتب والأنبياء ما جاء الأولين قبلنا، لكنا عباد الله الصادقين في الإيمان، المخلَصين في العبادة.", "isBasmala": false, "translation_en": "\"Had we received advice from the ancients.", "translation_id": "\"Kalau sekiranya di sksi kami ada sebuah kitab dari (kitab-kitab yang diturunkan) kepada orang-orang dahulu,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 169, "text": "لَكُنَّا عِبَادَ ٱللَّهِ ٱلۡمُخۡلَصِینَ ۝١٦٩", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وإن كفار \"مكة\" ليقولون قبل بعثتك -أيها الرسول-: لو جاءنا من الكتب والأنبياء ما جاء الأولين قبلنا، لكنا عباد الله الصادقين في الإيمان، المخلَصين في العبادة.", "isBasmala": false, "translation_en": "We would have been God's faithful servants.\"", "translation_id": "benar-benar kami akan jadi hamba Allah yang dibersihkan (dari dosa)\".", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 170, "text": "فَكَفَرُوا۟ بِهِۦۖ فَسَوۡفَ یَعۡلَمُونَ ۝١٧٠", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "فلما جاءهم ذكر الأولين، وعلم الآخرين، وأكمل الكتب، وأفضل الرسل، وهو محمد صلى الله عليه وسلم، كفروا به، فسوف يعلمون ما لهم من العذاب في الآخرة.", "isBasmala": false, "translation_en": "But they rejected it, so they will find out.", "translation_id": "Tetapi mereka mengingkarinya (Al Quran); maka kelak mereka akan mengetahui (akibat keingkarannya itu).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 171, "text": "وَلَقَدۡ سَبَقَتۡ كَلِمَتُنَا لِعِبَادِنَا ٱلۡمُرۡسَلِینَ ۝١٧١", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "ولقد سبقت كلمتنا -التي لا مردَّ لها- لعبادنا المرسلين، أن لهم النصرة على أعدائهم بالحجة والقوة، وأن جندنا المجاهدين في سبيلنا لهم الغالبون لأعدائهم في كل مقام باعتبار العاقبة والمآل.", "isBasmala": false, "translation_en": "Our Word has already gone out to our servant messengers.", "translation_id": "Dan sesungguhnya telah tetap janji Kami kepada hamba-hamba Kami yang menjadi rasul,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 172, "text": "إِنَّهُمۡ لَهُمُ ٱلۡمَنصُورُونَ ۝١٧٢", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "ولقد سبقت كلمتنا -التي لا مردَّ لها- لعبادنا المرسلين، أن لهم النصرة على أعدائهم بالحجة والقوة، وأن جندنا المجاهدين في سبيلنا لهم الغالبون لأعدائهم في كل مقام باعتبار العاقبة والمآل.", "isBasmala": false, "translation_en": "It is they who will be supported.", "translation_id": "(yaitu) sesungguhnya mereka itulah yang pasti mendapat pertolongan.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 173, "text": "وَإِنَّ جُندَنَا لَهُمُ ٱلۡغَـٰلِبُونَ ۝١٧٣", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "ولقد سبقت كلمتنا -التي لا مردَّ لها- لعبادنا المرسلين، أن لهم النصرة على أعدائهم بالحجة والقوة، وأن جندنا المجاهدين في سبيلنا لهم الغالبون لأعدائهم في كل مقام باعتبار العاقبة والمآل.", "isBasmala": false, "translation_en": "And Our troops will be the victors.", "translation_id": "Dan sesungguhnya tentara Kami itulah yang pasti menang,", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 174, "text": "فَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِینࣲ ۝١٧٤", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "فأعرض -أيها الرسول- عَمَّن عاند، ولم يقبل الحق حتى تنقضي المدة التي أمهلهم فيها، ويأتي أمر الله بعذابهم، وأنظرهم وارتقب ماذا يحل بهم من العذاب بمخالفتك؟ فسوف يرون ما يحل بهم من عذاب الله.", "isBasmala": false, "translation_en": "So disregard them for a while.", "translation_id": "Maka berpalinglah kamu (Muhammad) dari mereka sampai suatu ketika.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 175, "text": "وَأَبۡصِرۡهُمۡ فَسَوۡفَ یُبۡصِرُونَ ۝١٧٥", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "فأعرض -أيها الرسول- عَمَّن عاند، ولم يقبل الحق حتى تنقضي المدة التي أمهلهم فيها، ويأتي أمر الله بعذابهم، وأنظرهم وارتقب ماذا يحل بهم من العذاب بمخالفتك؟ فسوف يرون ما يحل بهم من عذاب الله.", "isBasmala": false, "translation_en": "And watch them-they will soon see.", "translation_id": "Dan lihatlah mereka, maka kelak mereka akan melihat (azab itu).", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 176, "text": "أَفَبِعَذَابِنَا یَسۡتَعۡجِلُونَ ۝١٧٦", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "أفبنزول عذابنا بهم يستعجلونك أيها الرسول؟ فإذا نزل عذابنا بهم، فبئس الصباح صباحهم.", "isBasmala": false, "translation_en": "Are they seeking to hasten Our punishment?", "translation_id": "Maka apakah mereka meminta supaya siksa Kami disegerakan?", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 177, "text": "فَإِذَا نَزَلَ بِسَاحَتِهِمۡ فَسَاۤءَ صَبَاحُ ٱلۡمُنذَرِینَ ۝١٧٧", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "أفبنزول عذابنا بهم يستعجلونك أيها الرسول؟ فإذا نزل عذابنا بهم، فبئس الصباح صباحهم.", "isBasmala": false, "translation_en": "When it descends into their yard, miserable will be the morning of those forewarned.", "translation_id": "Maka apabila siksaan itu turun dihalaman mereka, maka amat buruklah pagi hari yang dialami oleh orang-orang yang diperingatkan itu.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 178, "text": "وَتَوَلَّ عَنۡهُمۡ حَتَّىٰ حِینࣲ ۝١٧٨", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وأعرض عنهم حتى يأذن الله بعذابهم، وأنظرهم فسوف يرون ما يحل بهم من العذاب والنكال.", "isBasmala": false, "translation_en": "So avoid them for a while.", "translation_id": "Dan berpalinglah kamu dari mereka hingga suatu ketika.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 179, "text": "وَأَبۡصِرۡ فَسَوۡفَ یُبۡصِرُونَ ۝١٧٩", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وأعرض عنهم حتى يأذن الله بعذابهم، وأنظرهم فسوف يرون ما يحل بهم من العذاب والنكال.", "isBasmala": false, "translation_en": "And watch-they will soon see.", "translation_id": "Dan lihatlah, maka kelak mereka juga akan melihat.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 180, "text": "سُبۡحَـٰنَ رَبِّكَ رَبِّ ٱلۡعِزَّةِ عَمَّا یَصِفُونَ ۝١٨٠", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "تنزَّه الله وتعالى رب العزة عما يصفه هؤلاء المفترون عليه.", "isBasmala": false, "translation_en": "Exalted be your Lord, the Lord of Glory, beyond their allegations.", "translation_id": "Maha Suci Tuhanmu Yang mempunyai keperkasaan dari apa yang mereka katakan.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 181, "text": "وَسَلَـٰمٌ عَلَى ٱلۡمُرۡسَلِینَ ۝١٨١", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وتحية الله الدائمة وثناؤه وأمانه لجميع المرسلين.", "isBasmala": false, "translation_en": "And peace be upon the messengers.", "translation_id": "Dan kesejahteraan dilimpahkan atas para rasul.", "manzil": 6, "manzil_display": ""}, {"sura": 37, "sura_name": "الصافات", "revelation": "Makkiyah", "aya": 182, "text": "وَٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ ۝١٨٢", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "والحمد لله رب العالمين في الأولى والآخرة، فهو المستحق لذلك وحده لا شريك له.", "isBasmala": false, "translation_en": "And praise be to God, the Lord of the Worlds.", "translation_id": "Dan segala puji bagi Allah Tuhan seru sekalian alam.", "manzil": 6, "manzil_display": ""}], "453": [{"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 23, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 1, "text": "صۤۚ وَٱلۡقُرۡءَانِ ذِی ٱلذِّكۡرِ ۝١", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "(ص) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Saad. By the renowned Quran.", "translation_id": "Shaad, demi Al Quran yang mempunyai keagungan.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 2, "text": "بَلِ ٱلَّذِینَ كَفَرُوا۟ فِی عِزَّةࣲ وَشِقَاقࣲ ۝٢", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "(ص) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Those who disbelieve are steeped in arrogance and defiance.", "translation_id": "Sebenarnya orang-orang kafir itu (berada) dalam kesombongan dan permusuhan yang sengit.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 3, "text": "كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنࣲ فَنَادَوا۟ وَّلَاتَ حِینَ مَنَاصࣲ ۝٣", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "كثيرًا من الأمم أهلكناها قبل هؤلاء المشركين، فاستغاثوا حين جاءهم العذاب ونادوا بالتوبة، وليس الوقت وقت قَبول توبة، ولا وقت فرار وخلاص مما أصابهم.", "isBasmala": false, "translation_en": "How many generations have We destroyed before them? They cried out when it was too late to escape.", "translation_id": "Betapa banyaknya umat sebelum mereka yang telah Kami binasakan, lalu mereka meminta tolong padahal (waktu itu) bukanlah saat untuk lari melepaskan diri.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 4, "text": "وَعَجِبُوۤا۟ أَن جَاۤءَهُم مُّنذِرࣱ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَـٰفِرُونَ هَـٰذَا سَـٰحِرࣱ كَذَّابٌ ۝٤", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وعجِب هؤلاء الكفار مِن بعث الله إليهم بشرا منهم؛ ليدعوهم إلى الله ويخوَّفهم عذابه، وقالوا: إنه ليس رسولا بل هو كاذب في قوله، ساحر لقومه، كيف يصيِّر الآلهة الكثيرة إلهًا واحدًا؟ إنَّ هذا الذي جاء به ودعا إليه لَشيء عجيب.", "isBasmala": false, "translation_en": "And they marveled that a warner has come to them from among them. The disbelievers said, \"This is a lying magician.\"", "translation_id": "Dan mereka heran karena mereka kedatangan seorang pemberi peringatan (rasul) dari kalangan mereka; dan orang-orang kafir berkata: \"Ini adalah seorang ahli sihir yang banyak berdusta\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 5, "text": "أَجَعَلَ ٱلۡـَٔالِهَةَ إِلَـٰهࣰا وَ ٰحِدًاۖ إِنَّ هَـٰذَا لَشَیۡءٌ عُجَابࣱ ۝٥", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وعجِب هؤلاء الكفار مِن بعث الله إليهم بشرا منهم؛ ليدعوهم إلى الله ويخوَّفهم عذابه، وقالوا: إنه ليس رسولا بل هو كاذب في قوله، ساحر لقومه، كيف يصيِّر الآلهة الكثيرة إلهًا واحدًا؟ إنَّ هذا الذي جاء به ودعا إليه لَشيء عجيب.", "isBasmala": false, "translation_en": "\"Did he turn all the gods into one God? This is something strange.\"", "translation_id": "Mengapa ia menjadikan tuhan-tuhan itu Tuhan Yang Satu saja? Sesungguhnya ini benar-benar suatu hal yang sangat mengherankan.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 6, "text": "وَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ ٱمۡشُوا۟ وَٱصۡبِرُوا۟ عَلَىٰۤ ءَالِهَتِكُمۡۖ إِنَّ هَـٰذَا لَشَیۡءࣱ یُرَادُ ۝٦", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وانطلق رؤساء القوم وكبراؤهم يحرِّضون قومهم على الاستمرار على الشرك والصبر على تعدد الآلهة، ويقولون إن ما جاء به هذا الرسول شيء مدبَّر يقصد منه الرئاسة والسيادة، ما سمعنا بما يدعو إليه في دين آبائنا من قريش، ولا في النصرانية، ما هذا إلا كذب وافتراء.", "isBasmala": false, "translation_en": "The notables among them announced: \"Go on, and hold fast to your gods. This is something planned.", "translation_id": "Dan pergilah pemimpin-pemimpin mereka (seraya berkata): \"Pergilah kamu dan tetaplah (menyembah) tuhan-tuhanmu, sesungguhnya ini benar-benar suatu hal yang dikehendaki.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 7, "text": "مَا سَمِعۡنَا بِهَـٰذَا فِی ٱلۡمِلَّةِ ٱلۡـَٔاخِرَةِ إِنۡ هَـٰذَاۤ إِلَّا ٱخۡتِلَـٰقٌ ۝٧", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وانطلق رؤساء القوم وكبراؤهم يحرِّضون قومهم على الاستمرار على الشرك والصبر على تعدد الآلهة، ويقولون إن ما جاء به هذا الرسول شيء مدبَّر يقصد منه الرئاسة والسيادة، ما سمعنا بما يدعو إليه في دين آبائنا من قريش، ولا في النصرانية، ما هذا إلا كذب وافتراء.", "isBasmala": false, "translation_en": "We never heard of this in the former faith. This is nothing but a fabrication.", "translation_id": "Kami tidak pernah mendengar hal ini dalam agama yang terakhir; ini (mengesakan Allah), tidak lain hanyalah (dusta) yang diada-adakan,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 8, "text": "أَءُنزِلَ عَلَیۡهِ ٱلذِّكۡرُ مِنۢ بَیۡنِنَاۚ بَلۡ هُمۡ فِی شَكࣲّ مِّن ذِكۡرِیۚ بَل لَّمَّا یَذُوقُوا۟ عَذَابِ ۝٨", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "أخُص محمد بنزول القرآن عليه من دوننا؟ بل هم في ريب من وحيي إليك -أيها الرسول- وإرسالي لك، بل قالوا ذلك؛ لأنهم لم يذوقوا عذاب الله، فلو ذاقوا عذابه لما تجرؤوا على ما قالوا.", "isBasmala": false, "translation_en": "Was the message sent down to him, out of all of us?\" In fact, they are doubtful of My warning. In fact, they have not yet tasted My punishment.", "translation_id": "mengapa Al Quran itu diturunkan kepadanya di antara kita?\" Sebenarnya mereka ragu-ragu terhadap Al Quran-Ku, dan sebenarnya mereka belum merasakan azab-Ku.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 9, "text": "أَمۡ عِندَهُمۡ خَزَاۤىِٕنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِیزِ ٱلۡوَهَّابِ ۝٩", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "أم هم يملكون خزائن فضل ربك العزيز في سلطانه، الوهاب ما يشاء من رزقه وفضله لمن يشاء من خلقه؟", "isBasmala": false, "translation_en": "Or do they possess the treasuries of the mercy of your Lord-the Majestic, the Giver?", "translation_id": "Atau apakah mereka itu mempunyai perbendaharaan rahmat Tuhanmu Yang Maha Perkasa lagi Maha Pemberi?", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 10, "text": "أَمۡ لَهُم مُّلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۖ فَلۡیَرۡتَقُوا۟ فِی ٱلۡأَسۡبَـٰبِ ۝١٠", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "أم لهؤلاء المشركين مُلْك السموات والأرض وما بينهما، فيُعْطوا ويَمْنعوا؟ فليأخذوا بالأسباب الموصلة لهم إلى السماء، حتى يحكموا بما يريدون من عطاء ومنع.", "isBasmala": false, "translation_en": "Or do they possess the sovereignty of the heavens and the earth and what is between them? Then let them ascend the ropes.", "translation_id": "Atau apakah bagi mereka kerajaan langit dan bumi dan yang ada di antara keduanya? (Jika ada), maka hendaklah mereka menaiki tangga-tangga (ke langit).", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 11, "text": "جُندࣱ مَّا هُنَالِكَ مَهۡزُومࣱ مِّنَ ٱلۡأَحۡزَابِ ۝١١", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "هؤلاء الجند المكذِّبون جند مهزومون، كما هُزم غيرهم من الأحزاب قبلهم، كذَّبت قبلهم قوم نوح وعاد وفرعون صاحب القوة العظيمة، وثمود وقوم لوط وأصحاب الأشجار والبساتين وهم قوم شعيب. أولئك الأمم الذين تحزَّبوا على الكفر والتكذيب واجتمعوا عليه. إنْ كلٌّ مِن هؤلاء إلا كذَّب الرسل، فاستحقوا عذاب الله، وحلَّ بهم عقابه.", "isBasmala": false, "translation_en": "An army of confederates with be defeated there.", "translation_id": "Suatu tentara yang besar yang berada disana dari golongan-golongan yang berserikat, pasti akan dikalahkan.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 12, "text": "كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ ۝١٢", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "هؤلاء الجند المكذِّبون جند مهزومون، كما هُزم غيرهم من الأحزاب قبلهم، كذَّبت قبلهم قوم نوح وعاد وفرعون صاحب القوة العظيمة، وثمود وقوم لوط وأصحاب الأشجار والبساتين وهم قوم شعيب. أولئك الأمم الذين تحزَّبوا على الكفر والتكذيب واجتمعوا عليه. إنْ كلٌّ مِن هؤلاء إلا كذَّب الرسل، فاستحقوا عذاب الله، وحلَّ بهم عقابه.", "isBasmala": false, "translation_en": "Before them the people of Noah denied the truth; as did Aad, and Pharaoh of the Stakes.", "translation_id": "Telah mendustakan (rasul-rasul pula) sebelum mereka itu kaum Nuh, 'Aad, Fir'aun yang mempunyai tentara yang banyak,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 13, "text": "وَثَمُودُ وَقَوۡمُ لُوطࣲ وَأَصۡحَـٰبُ لۡـَٔیۡكَةِۚ أُو۟لَـٰۤىِٕكَ ٱلۡأَحۡزَابُ ۝١٣", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "هؤلاء الجند المكذِّبون جند مهزومون، كما هُزم غيرهم من الأحزاب قبلهم، كذَّبت قبلهم قوم نوح وعاد وفرعون صاحب القوة العظيمة، وثمود وقوم لوط وأصحاب الأشجار والبساتين وهم قوم شعيب. أولئك الأمم الذين تحزَّبوا على الكفر والتكذيب واجتمعوا عليه. إنْ كلٌّ مِن هؤلاء إلا كذَّب الرسل، فاستحقوا عذاب الله، وحلَّ بهم عقابه.", "isBasmala": false, "translation_en": "And Thamood, and the people of Lot, and the dwellers of the Woods-these were the confederates.", "translation_id": "dan Tsamud, kaum Luth dan penduduk Aikah. Mereka itulah golongan-golongan yang bersekutu (menentang rasul-rasul).", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 14, "text": "إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ ۝١٤", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "هؤلاء الجند المكذِّبون جند مهزومون، كما هُزم غيرهم من الأحزاب قبلهم، كذَّبت قبلهم قوم نوح وعاد وفرعون صاحب القوة العظيمة، وثمود وقوم لوط وأصحاب الأشجار والبساتين وهم قوم شعيب. أولئك الأمم الذين تحزَّبوا على الكفر والتكذيب واجتمعوا عليه. إنْ كلٌّ مِن هؤلاء إلا كذَّب الرسل، فاستحقوا عذاب الله، وحلَّ بهم عقابه.", "isBasmala": false, "translation_en": "None of them but denied the messengers, so My retribution was deserved.", "translation_id": "Semua mereka itu tidak lain hanyalah mendustakan rasul-rasul, maka pastilah (bagi mereka) azab-Ku.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 15, "text": "وَمَا یَنظُرُ هَـٰۤؤُلَاۤءِ إِلَّا صَیۡحَةࣰ وَ ٰحِدَةࣰ مَّا لَهَا مِن فَوَاقࣲ ۝١٥", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وما ينتظر هؤلاء المشركون لحلول العذاب عليهم إن بقوا على شركهم، إلا نفخة واحدة ما لها من رجوع.", "isBasmala": false, "translation_en": "These can expect only a single scream, from which there is no recovery.", "translation_id": "Tidaklah yang mereka tunggu melainkan hanya satu teriakan saja yang tidak ada baginya saat berselang.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 16, "text": "وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبۡلَ یَوۡمِ ٱلۡحِسَابِ ۝١٦", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وقالوا: ربنا عجِّل لنا نصيبنا من العذاب في الدينا قبل يوم القيامة، وكان هذا استهزاءً منهم.", "isBasmala": false, "translation_en": "And they say, \"Our Lord, hasten Your writ upon us, before the Day of Account.\"", "translation_id": "Dan mereka berkata: \"Ya Tuhan kami cepatkanlah untuk kami azab yang diperuntukkan bagi kami sebelum hari berhisab\".", "manzil": 6, "manzil_display": ""}], "454": [{"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 17, "text": "ٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَیۡدِۖ إِنَّهُۥۤ أَوَّابٌ ۝١٧", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "اصبر -أيها الرسول- على ما يقولونه مما تكره، واذكر عبدنا داود صاحب القوة على أعداء الله والصبر على طاعته، إنه توَّاب كثير الرجوع إلى ما يرضي الله. (وفي هذا تسلية للرسول صلى الله عليه وسلم).", "isBasmala": false, "translation_en": "Be patient in the face of what they say, and mention Our servant David, the resourceful. He was obedient.", "translation_id": "Bersabarlah atas segala apa yang mereka katakan; dan ingatlah hamba Kami Daud yang mempunyai kekuatan; sesungguhnya dia amat taat (kepada Tuhan).", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 18, "text": "إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ یُسَبِّحۡنَ بِٱلۡعَشِیِّ وَٱلۡإِشۡرَاقِ ۝١٨", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "إنا سخَّرنا الجبال مع داود يسبِّحن بتسبيحه أول النهار وآخره، وسخرنا الطير معه مجموعة تسبِّح، وتطيع تبعًا له.", "isBasmala": false, "translation_en": "We committed the mountains to glorify with him, in the evening and at daybreak.", "translation_id": "Sesungguhnya Kami menundukkan gunung-gunung untuk bertasbih bersama dia (Daud) di waktu petang dan pagi,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 19, "text": "وَٱلطَّیۡرَ مَحۡشُورَةࣰۖ كُلࣱّ لَّهُۥۤ أَوَّابࣱ ۝١٩", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "إنا سخَّرنا الجبال مع داود يسبِّحن بتسبيحه أول النهار وآخره، وسخرنا الطير معه مجموعة تسبِّح، وتطيع تبعًا له.", "isBasmala": false, "translation_en": "And the birds, gathered together. All obedient to him.", "translation_id": "dan (Kami tundukkan pula) burung-burung dalam keadaan terkumpul. Masing-masingnya amat taat kepada Allah.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 20, "text": "وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَیۡنَـٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ ۝٢٠", "juz": 23, "hizb": "(* ح 46*)", "tafsir": "وقوَّينا له ملكه بالهيبة والقوة والنصر، وآتيناه النبوة، والفصل في الكلام والحكم.", "isBasmala": false, "translation_en": "And We strengthened his kingdom, and gave him wisdom and decisive speech.", "translation_id": "Dan Kami kuatkan kerajaannya dan Kami berikan kepadanya hikmahdan kebijaksanaan dalam menyelesaikan perselisihan.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 21, "text": "۞ وَهَلۡ أَتَىٰكَ نَبَؤُا۟ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُوا۟ ٱلۡمِحۡرَابَ ۝٢١", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "وهل جاءك -أيها الرسول- خبر المتخاصِمَين اللذَين تسوَّرا على داود في مكان عبادته، فارتاع من دخولهما عليه؟ قالوا له: لا تَخَفْ، فنحن خصمان ظلم أحدنا الآخر، فاقض بيننا بالعدل، ولا تَجُرْ علينا في الحكم، وأرشِدنا إلى سواء السبيل.", "isBasmala": false, "translation_en": "Has the story of the two disputants reached you? When they scaled the sanctuary?", "translation_id": "Dan adakah sampai kepadamu berita orang-orang yang berperkara ketika mereka memanjat pagar?", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 22, "text": "إِذۡ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنۡهُمۡۖ قَالُوا۟ لَا تَخَفۡۖ خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡضࣲ فَٱحۡكُم بَیۡنَنَا بِٱلۡحَقِّ وَلَا تُشۡطِطۡ وَٱهۡدِنَاۤ إِلَىٰ سَوَاۤءِ ٱلصِّرَ ٰطِ ۝٢٢", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "وهل جاءك -أيها الرسول- خبر المتخاصِمَين اللذَين تسوَّرا على داود في مكان عبادته، فارتاع من دخولهما عليه؟ قالوا له: لا تَخَفْ، فنحن خصمان ظلم أحدنا الآخر، فاقض بيننا بالعدل، ولا تَجُرْ علينا في الحكم، وأرشِدنا إلى سواء السبيل.", "isBasmala": false, "translation_en": "When they entered upon David, and he was startled by them. They said, \"Do not fear. Two disputants; one of us has wronged the other; so judge between us fairly, and do not be biased, and guide us to the straight way.\"", "translation_id": "Ketika mereka masuk (menemui) Daud lalu ia terkejut karena kedatangan) mereka. Mereka berkata: \"Janganlah kamu merasa takut; (kami) adalah dua orang yang berperkara yang salah seorang dari kami berbuat zalim kepada yang lain; maka berilah keputusan antara kami dengan adil dan janganlah kamu menyimpang dari kebenaran dan tunjukilah kami ke jalan yang lurus.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 23, "text": "إِنَّ هَـٰذَاۤ أَخِی لَهُۥ تِسۡعࣱ وَتِسۡعُونَ نَعۡجَةࣰ وَلِیَ نَعۡجَةࣱ وَ ٰحِدَةࣱ فَقَالَ أَكۡفِلۡنِیهَا وَعَزَّنِی فِی ٱلۡخِطَابِ ۝٢٣", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "قال أحدهما: إن هذا أخي له تسع وتسعون من النعاج، وليس عندي إلا نعجة واحدة، فطمع فيها، وقال: أعطنيها، وغلبني بحجته.", "isBasmala": false, "translation_en": "\"This brother of mine has ninety nine ewes, and I have one ewe, and he said, 'Entrust it to me,' and he pressured me with words.\"", "translation_id": "Sesungguhnya saudaraku ini mempunyai sembilan puluh sembilan ekor kambing betina dan aku mempunyai seekor saja. Maka dia berkata: \"Serahkanlah kambingmu itu kepadaku dan dia mengalahkan aku dalam perdebatan\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 24, "text": "قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِیرࣰا مِّنَ ٱلۡخُلَطَاۤءِ لَیَبۡغِی بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَقَلِیلࣱ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّـٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَ̅خَ̅رَّ̅ ̅رَ̅ا̅كِ̅عࣰ̅ا̅ وَأَنَابَ ۝٢٤ ۩", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "قال داود: لقد ظلمك أخوك بسؤاله ضم نعجتك إلى نعاجه، وإن كثيرًا من الشركاء ليعتدي بعضهم على بعض، ويظلمه بأخذ حقه وعدم إنصافه مِن نفسه إلا المؤمنين الصالحين، فلا يبغي بعضهم على بعض، وهم قليل. وأيقن داود أننا فتنَّاه بهذه الخصومة، فاستغفر ربه، وسجد تقربًا لله، ورجع إليه وتاب.", "isBasmala": false, "translation_en": "He said, \"He has done you wrong by asking your ewe in addition to his ewes. Many partners take advantage of one another, except those who believe and do good deeds, but these are so few.\" David realized that We were testing him, so he sought forgiveness from his Lord, and fell down to his knees, and repented.", "translation_id": "Daud berkata: \"Sesungguhnya dia telah berbuat zalim kepadamu dengan meminta kambingmu itu untuk ditambahkan kepada kambingnya. Dan sesungguhnya kebanyakan dari orang-orang yang berserikat itu sebahagian mereka berbuat zalim kepada sebahagian yang lain, kecuali orang-orang yang beriman dan mengerjakan amal yang saleh; dan amat sedikitlah mereka ini\". Dan Daud mengetahui bahwa Kami mengujinya; maka ia meminta ampun kepada Tuhannya lalu menyungkur sujud dan bertaubat.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 25, "text": "فَغَفَرۡنَا لَهُۥ ذَ ٰلِكَۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابࣲ ۝٢٥", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "فغفرنا له ذلك، وجعلناه من المقرَّبين عندنا، وأعددنا له حسن المصير في الآخرة.", "isBasmala": false, "translation_en": "So We forgave him that. And for him is nearness to Us, and a good place of return.", "translation_id": "Maka Kami ampuni baginya kesalahannya itu. Dan sesungguhnya dia mempunyai kedudukan dekat pada sisi Kami dan tempat kembali yang baik.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 26, "text": "یَـٰدَاوُۥدُ إِنَّا جَعَلۡنَـٰكَ خَلِیفَةࣰ فِی ٱلۡأَرۡضِ فَٱحۡكُم بَیۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَیُضِلَّكَ عَن سَبِیلِ ٱللَّهِۚ إِنَّ ٱلَّذِینَ یَضِلُّونَ عَن سَبِیلِ ٱللَّهِ لَهُمۡ عَذَابࣱ شَدِیدُۢ بِمَا نَسُوا۟ یَوۡمَ ٱلۡحِسَابِ ۝٢٦", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "يا داود إنا استخلفناك في الأرض وملَّكناك فيها، فاحكم بين الناس بالعدل والإنصاف، ولا تتبع الهوى في الأحكام، فيُضلك ذلك عن دين الله وشرعه، إن الذين يَضِلُّون عن سبيل الله لهم عذاب أليم في النار؛ بغفلتهم عن يوم الجزاء والحساب. وفي هذا توصية لولاة الأمر أن يحكموا بالحق المنزل من الله، تبارك وتعالى، ولا يعدلوا عنه، فيضلوا عن سبيله.", "isBasmala": false, "translation_en": "\"O David, We made you a ruler in the land, so judge between the people with justice, and do not follow desire, lest it diverts you from God's path. Those who stray from God's path will have a painful punishment, for having ignored the Day of Account.\"", "translation_id": "Hai Daud, sesungguhnya Kami menjadikan kamu khalifah (penguasa) di muka bumi, maka berilah keputusan (perkara) di antara manusia dengan adil dan janganlah kamu mengikuti hawa nafsu, karena ia akan menyesatkan kamu dari jalan Allah. Sesungguhnya orang-orang yang sesat darin jalan Allah akan mendapat azab yang berat, karena mereka melupakan hari perhitungan.", "manzil": 6, "manzil_display": ""}], "455": [{"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 27, "text": "وَمَا خَلَقۡنَا ٱلسَّمَاۤءَ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا بَـٰطِلࣰاۚ ذَ ٰلِكَ ظَنُّ ٱلَّذِینَ كَفَرُوا۟ۚ فَوَیۡلࣱ لِّلَّذِینَ كَفَرُوا۟ مِنَ ٱلنَّارِ ۝٢٧", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "وما خلقنا السماء والأرض وما بينهما عبثًا ولهوًا، ذلك ظنُّ الذين كفروا، فويل لهم من النار يوم القيامة؛ لظنهم الباطل، وكفرهم بالله.", "isBasmala": false, "translation_en": "We did not create the heaven and the earth and everything between them in vain. That is the assumption of those who disbelieve-so woe to those who disbelieve because of the Fire.", "translation_id": "Dan Kami tidak menciptakan langit dan bumi dan apa yang ada antara keduanya tanpa hikmah. Yang demikian itu adalah anggapan orang-orang kafir, maka celakalah orang-orang kafir itu karena mereka akan masuk neraka.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 28, "text": "أَمۡ نَجۡعَلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ كَٱلۡمُفۡسِدِینَ فِی ٱلۡأَرۡضِ أَمۡ نَجۡعَلُ ٱلۡمُتَّقِینَ كَٱلۡفُجَّارِ ۝٢٨", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "أنجعل الذين آمنوا وعملوا الصالحات كالمفسدين في الأرض، أم نجعل أهل التقوى المؤمنين كأصحاب الفجور الكافرين؟ هذه التسوية غير لائقة بحكمة الله وحُكْمه، فلا يستوون عند الله، بل يثيب الله المؤمنين الأتقياء، ويعاقب المفسدين الأشقياء.", "isBasmala": false, "translation_en": "Or are We to treat those who believe and do righteous deeds like those who make trouble on earth? Or are We to treat the pious like the shameless?", "translation_id": "Patutkah Kami menganggap orang-orang yang beriman dan mengerjakan amal yang saleh sama dengan orang-orang yang berbuat kerusakan di muka bumi? Patutkah (pula) Kami menganggap orang-orang yang bertakwa sama dengan orang-orang yang berbuat maksiat?", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 29, "text": "كِتَـٰبٌ أَنزَلۡنَـٰهُ إِلَیۡكَ مُبَـٰرَكࣱ لِّیَدَّبَّرُوۤا۟ ءَایَـٰتِهِۦ وَلِیَتَذَكَّرَ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ ۝٢٩", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "هذا الموحى به إليك -أيها الرسول- كتاب أنزلناه إليك مبارك؛ ليتفكروا في آياته، ويعملوا بهداياته ودلالاته، وليتذكر أصحاب العقول السليمة ما كلفهم الله به.", "isBasmala": false, "translation_en": "A blessed Book that We sent down to you, that they may ponder its Verses, and for those with intelligence to take heed.", "translation_id": "Ini adalah sebuah kitab yang Kami turunkan kepadamu penuh dengan berkah supaya mereka memperhatikan ayat-ayatnya dan supaya mendapat pelajaran orang-orang yang mempunyai fikiran.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 30, "text": "وَوَهَبۡنَا لِدَاوُۥدَ سُلَیۡمَـٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥۤ أَوَّابٌ ۝٣٠", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "ووهبنا لداود ابنه سليمان، فأنعمنا به عليه، وأقررنا به عينه، نِعْم العبد سليمان، إنه كان كثير الرجوع إلى الله والإنابة إليه.", "isBasmala": false, "translation_en": "And We granted David, Solomon, an excellent servant. He was penitent.", "translation_id": "Dan Kami karuniakan kepada Daud, Sulaiman, dia adalah sebaik-baik hamba. Sesungguhnya dia amat taat (kepada Tuhannya),", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 31, "text": "إِذۡ عُرِضَ عَلَیۡهِ بِٱلۡعَشِیِّ ٱلصَّـٰفِنَـٰتُ ٱلۡجِیَادُ ۝٣١", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "اذكر حين عُرِضت عليه عصرًا الخيول الأصيلة السريعة، تقف على ثلاث قوائم وترفع الرابعة؛ لنجابتها وخفتها، فما زالت تُعرض عليه حتى غابت الشمس.", "isBasmala": false, "translation_en": "When the beautiful horses were paraded before him in the evening.", "translation_id": "(ingatlah) ketika dipertunjukkan kepadanya kuda-kuda yang tenang di waktu berhenti dan cepat waktu berlari pada waktu sore,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 32, "text": "فَقَالَ إِنِّیۤ أَحۡبَبۡتُ حُبَّ ٱلۡخَیۡرِ عَن ذِكۡرِ رَبِّی حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ ۝٣٢", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "فقال: إنني آثرت حب المال عن ذكر ربي حتى غابت الشمس عن عينيه، رُدُّوا عليَّ الخيل التي عُرضت من قبل، فشرع يمسح سوقها وأعناقها.", "isBasmala": false, "translation_en": "He said, \"I have preferred the love of niceties to the remembrance of my Lord-until it disappeared behind the veil.", "translation_id": "maka ia berkata: \"Sesungguhnya aku menyukai kesenangan terhadap barang yang baik (kuda) sehingga aku lalai mengingat Tuhanku sampai kuda itu hilang dari pandangan\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 33, "text": "رُدُّوهَا عَلَیَّۖ فَطَفِقَ مَسۡحَۢا بِٱلسُّوقِ وَٱلۡأَعۡنَاقِ ۝٣٣", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "فقال: إنني آثرت حب المال عن ذكر ربي حتى غابت الشمس عن عينيه، رُدُّوا عليَّ الخيل التي عُرضت من قبل، فشرع يمسح سوقها وأعناقها.", "isBasmala": false, "translation_en": "Bring them back to me.\" And he began caressing their legs and necks.", "translation_id": "\"Bawalah kuda-kuda itu kembali kepadaku\". Lalu ia potong kaki dan leher kuda itu.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 34, "text": "وَلَقَدۡ فَتَنَّا سُلَیۡمَـٰنَ وَأَلۡقَیۡنَا عَلَىٰ كُرۡسِیِّهِۦ جَسَدࣰا ثُمَّ أَنَابَ ۝٣٤", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "ولقد ابتلينا سليمان وألقينا على كرسيه شق وَلَد، وُلِد له حين أقسم ليطوفنَّ على نسائه، وكلهن تأتي بفارس يجاهد في سبيل الله، ولم يقل: إن شاء الله، فطاف عليهن جميعًا، فلم تحمل منهن إلا امرأة واحدة جاءت بشق ولد، ثم رجع سليمان إلى ربه وتاب، قال: رب اغفر لي ذنبي، وأعطني ملكًا عظيمًا خاصًا لا يكون مثله لأحد من البشر بعدي، إنك- سبحانك- كثير الجود والعطاء. فاستجبنا له، وذللنا الريح تجري بأمره طيِّعة مع قوتها وشدتها حيث أراد.", "isBasmala": false, "translation_en": "We tested Solomon, and placed a body on his throne; then he repented.", "translation_id": "Dan sesungguhnya Kami telah menguji Sulaiman dan Kami jadikan (dia) tergeletak di atas kursinya sebagai tubuh (yang lemah karena sakit), kemudian ia bertaubat.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 35, "text": "قَالَ رَبِّ ٱغۡفِرۡ لِی وَهَبۡ لِی مُلۡكࣰا لَّا یَنۢبَغِی لِأَحَدࣲ مِّنۢ بَعۡدِیۤۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ ۝٣٥", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "ولقد ابتلينا سليمان وألقينا على كرسيه شق وَلَد، وُلِد له حين أقسم ليطوفنَّ على نسائه، وكلهن تأتي بفارس يجاهد في سبيل الله، ولم يقل: إن شاء الله، فطاف عليهن جميعًا، فلم تحمل منهن إلا امرأة واحدة جاءت بشق ولد، ثم رجع سليمان إلى ربه وتاب، قال: رب اغفر لي ذنبي، وأعطني ملكًا عظيمًا خاصًا لا يكون مثله لأحد من البشر بعدي، إنك- سبحانك- كثير الجود والعطاء. فاستجبنا له، وذللنا الريح تجري بأمره طيِّعة مع قوتها وشدتها حيث أراد.", "isBasmala": false, "translation_en": "He said, \"My Lord, forgive me, and grant me a kingdom never to be attained by anyone after me. You are the Giver.\"", "translation_id": "Ia berkata: \"Ya Tuhanku, ampunilah aku dan anugerahkanlah kepadaku kerajaan yang tidak dimiliki oleh seorang juapun sesudahku, sesungguhnya Engkaulah Yang Maha Pemberi\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 36, "text": "فَسَخَّرۡنَا لَهُ ٱلرِّیحَ تَجۡرِی بِأَمۡرِهِۦ رُخَاۤءً حَیۡثُ أَصَابَ ۝٣٦", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "ولقد ابتلينا سليمان وألقينا على كرسيه شق وَلَد، وُلِد له حين أقسم ليطوفنَّ على نسائه، وكلهن تأتي بفارس يجاهد في سبيل الله، ولم يقل: إن شاء الله، فطاف عليهن جميعًا، فلم تحمل منهن إلا امرأة واحدة جاءت بشق ولد، ثم رجع سليمان إلى ربه وتاب، قال: رب اغفر لي ذنبي، وأعطني ملكًا عظيمًا خاصًا لا يكون مثله لأحد من البشر بعدي، إنك- سبحانك- كثير الجود والعطاء. فاستجبنا له، وذللنا الريح تجري بأمره طيِّعة مع قوتها وشدتها حيث أراد.", "isBasmala": false, "translation_en": "So We placed the wind at his service, blowing gently by his command, wherever he directed.", "translation_id": "Kemudian Kami tundukkan kepadanya angin yang berhembus dengan baik menurut ke mana saja yang dikehendakinya,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 37, "text": "وَٱلشَّیَـٰطِینَ كُلَّ بَنَّاۤءࣲ وَغَوَّاصࣲ ۝٣٧", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "وسخَّرنا له الشياطين يستعملهم في أعماله: فمنهم البناؤون والغوَّاصون في البحار، وآخرون، وهم مردة الشياطين، موثوقون في الأغلال. هذا المُلْك العظيم والتسخير الخاص عطاؤنا لك يا سليمان، فأعط مَن شئت وامنع مَن شئت، لا حساب عليك.", "isBasmala": false, "translation_en": "And the demons-every builder and diver.", "translation_id": "dan (Kami tundukkan pula kepadanya) syaitan-syaitan semuanya ahli bangunan dan penyelam,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 38, "text": "وَءَاخَرِینَ مُقَرَّنِینَ فِی ٱلۡأَصۡفَادِ ۝٣٨", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "وسخَّرنا له الشياطين يستعملهم في أعماله: فمنهم البناؤون والغوَّاصون في البحار، وآخرون، وهم مردة الشياطين، موثوقون في الأغلال. هذا المُلْك العظيم والتسخير الخاص عطاؤنا لك يا سليمان، فأعط مَن شئت وامنع مَن شئت، لا حساب عليك.", "isBasmala": false, "translation_en": "And others fettered in chains.", "translation_id": "dan syaitan yang lain yang terikat dalam belenggu.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 39, "text": "هَـٰذَا عَطَاۤؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَیۡرِ حِسَابࣲ ۝٣٩", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "وسخَّرنا له الشياطين يستعملهم في أعماله: فمنهم البناؤون والغوَّاصون في البحار، وآخرون، وهم مردة الشياطين، موثوقون في الأغلال. هذا المُلْك العظيم والتسخير الخاص عطاؤنا لك يا سليمان، فأعط مَن شئت وامنع مَن شئت، لا حساب عليك.", "isBasmala": false, "translation_en": "\"This is Our gift; so give generously, or withhold; without account.\"", "translation_id": "Inilah anugerah Kami; maka berikanlah (kepada orang lain) atau tahanlah (untuk dirimu sendiri) dengan tiada pertanggungan jawab.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 40, "text": "وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابࣲ ۝٤٠", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "وإن لسليمان عندنا في الدار الآخرة لَقربةً وحسن مرجع.", "isBasmala": false, "translation_en": "For him is nearness to Us, and a beautiful resort.", "translation_id": "Dan sesungguhnya dia mempunyai kedudukan yang dekat pada sisi Kami dan tempat kembali yang baik.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 41, "text": "وَٱذۡكُرۡ عَبۡدَنَاۤ أَیُّوبَ إِذۡ نَادَىٰ رَبَّهُۥۤ أَنِّی مَسَّنِیَ ٱلشَّیۡطَـٰنُ بِنُصۡبࣲ وَعَذَابٍ ۝٤١", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "واذكر -أيها الرسول- عبدنا أيوب، حين دعا ربه أن الشيطان تسبب لي بتعب ومشقة، وألم في جسدي ومالي وأهلي.", "isBasmala": false, "translation_en": "And mention Our servant Job, when he called out to his Lord, \"Satan has afflicted me with hardship and pain.\"", "translation_id": "Dan ingatlah akan hamba Kami Ayyub ketika ia menyeru Tuhan-nya: \"Sesungguhnya aku diganggu syaitan dengan kepayahan dan siksaan\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 42, "text": "ٱرۡكُضۡ بِرِجۡلِكَۖ هَـٰذَا مُغۡتَسَلُۢ بَارِدࣱ وَشَرَابࣱ ۝٤٢", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "فقلنا له: اضرب برجلك الأرض ينبع لك منها ماء بارد، فاشرب منه، واغتسِلْ فيذهب عنك الضر والأذى.", "isBasmala": false, "translation_en": "\"Stamp with your foot-here is cool water to wash with, and to drink.\"", "translation_id": "(Allah berfirman): \"Hantamkanlah kakimu; inilah air yang sejuk untuk mandi dan untuk minum\".", "manzil": 6, "manzil_display": ""}], "456": [{"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 43, "text": "وَوَهَبۡنَا لَهُۥۤ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةࣰ مِّنَّا وَذِكۡرَىٰ لِأُو۟لِی ٱلۡأَلۡبَـٰبِ ۝٤٣", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "فكشفنا عنه ضره وأكرمناه ووهبنا له أهله من زوجة وولد، وزدناه مثلهم بنين وحفدة، كل ذلك رحمة منَّا به وإكرامًا له على صبره، وعبرة وذكرى لأصحاب العقول السليمة؛ ليعلموا أن عاقبة الصبر الفرج وكشف الضر.", "isBasmala": false, "translation_en": "And We restored his family for him, and their like with them; as a mercy from Us, and a lesson for those who possess insight.", "translation_id": "Dan Kami anugerahi dia (dengan mengumpulkan kembali) keluarganya dan (Kami tambahkan) kepada mereka sebanyak mereka pula sebagai rahmat dari Kami dan pelajaran bagi orang-orang yang mempunyai fikiran.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 44, "text": "وَخُذۡ بِیَدِكَ ضِغۡثࣰا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَـٰهُ صَابِرࣰاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥۤ أَوَّابࣱ ۝٤٤", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "وقلنا له: خذ بيدك حُزمة شماريخ، فاضرب بها زوجك إبرارًا بيمينك، فلا تحنث؛ إذ أقسم ليضربنَّها مائة جلدة إذا شفاه الله، لـمَّا غضب عليها من أمر يسير أثناء مرضه، وكانت امرأة صالحة، فرحمها الله ورحمه بهذه الفتوى. إنا وجدنا أيوب صابرًا على البلاء، نِعم العبد هو، إنه رجَّاع إلى طاعة الله.", "isBasmala": false, "translation_en": "\"Take with your hand a bundle, and strike with it, and do not break your oath.\" We found him patient. What an excellent servant! He was obedient.", "translation_id": "Dan ambillah dengan tanganmu seikat (rumput), maka pukullah dengan itu dan janganlah kamu melanggar sumpah. Sesungguhnya Kami dapati dia (Ayyub) seorang yang sabar. Dialah sebaik-baik hamba. Sesungguhnya dia amat taat (kepada Tuhan-nya).", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 45, "text": "وَٱذۡكُرۡ عِبَـٰدَنَاۤ إِبۡرَ ٰهِیمَ وَإِسۡحَـٰقَ وَیَعۡقُوبَ أُو۟لِی ٱلۡأَیۡدِی وَٱلۡأَبۡصَـٰرِ ۝٤٥", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "واذكر -أيها الرسول- عبادنا وأنبياءنا: إبراهيم وإسحاق ويعقوب؛ فإنهم أصحاب قوة في طاعة الله، وبصيرة في دينه.", "isBasmala": false, "translation_en": "And mention Our servants Abraham, Isaac, and Jacob-endowed with ability and vision.", "translation_id": "Dan ingatlah hamba-hamba Kami: Ibrahim, Ishaq dan Ya'qub yang mempunyai perbuatan-perbuatan yang besar dan ilmu-ilmu yang tinggi.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 46, "text": "إِنَّاۤ أَخۡلَصۡنَـٰهُم بِخَالِصَةࣲ ذِكۡرَى ٱلدَّارِ ۝٤٦", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "إنا خصصناهم بخاصة عظيمة، حيث جعلنا ذكرى الدار الآخرة في قلوبهم، فعملوا لها بطاعتنا، ودعوا الناس إليها، وذكَّروهم بها. وإنهم عندنا لمن الذين اخترناهم لطاعتنا، واصطفيناهم لرسالتنا.", "isBasmala": false, "translation_en": "We distinguished them with a distinct quality: the remembrance of the Home.", "translation_id": "Sesungguhnya Kami telah mensucikan mereka dengan (menganugerahkan kepada mereka) akhlak yang tinggi yaitu selalu mengingatkan (manusia) kepada negeri akhirat.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 47, "text": "وَإِنَّهُمۡ عِندَنَا لَمِنَ ٱلۡمُصۡطَفَیۡنَ ٱلۡأَخۡیَارِ ۝٤٧", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "إنا خصصناهم بخاصة عظيمة، حيث جعلنا ذكرى الدار الآخرة في قلوبهم، فعملوا لها بطاعتنا، ودعوا الناس إليها، وذكَّروهم بها. وإنهم عندنا لمن الذين اخترناهم لطاعتنا، واصطفيناهم لرسالتنا.", "isBasmala": false, "translation_en": "To Us they are among the chosen, the outstanding.", "translation_id": "Dan sesungguhnya mereka pada sisi Kami benar-benar termasuk orang-orang pilihan yang paling baik.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 48, "text": "وَٱذۡكُرۡ إِسۡمَـٰعِیلَ وَٱلۡیَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلࣱّ مِّنَ ٱلۡأَخۡیَارِ ۝٤٨", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "واذكر -أيها الرسول- عبادنا: إسماعيل، واليسع، وذا الكفل، بأحسن الذكر؛ إن كلا منهم من الأخيار الذين اختارهم الله من الخلق، واختار لهم أكمل الأحوال والصفات.", "isBasmala": false, "translation_en": "And mention Ishmael, Elisha, and Ezekiel; all are among the outstanding.", "translation_id": "Dan ingatlah akan Ismail, Ilyasa' dan Zulkifli. Semuanya termasuk orang-orang yang paling baik.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 49, "text": "هَـٰذَا ذِكۡرࣱۚ وَإِنَّ لِلۡمُتَّقِینَ لَحُسۡنَ مَـَٔابࣲ ۝٤٩", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "هذا القرآن ذِكْر وشرف لك -أيها الرسول- ولقومك. وإن لأهل تقوى الله وطاعته لَحسنَ مصير عندنا في جنات إقامة، مفتَّحة لهم أبوابها، متكئين فيها على الأرائك المزيَّنات، يطلبون ما يشتهون من أنواع الفواكه الكثيرة والشراب، من كل ما تشتهيه نفوسهم، وتلذه أعينهم.", "isBasmala": false, "translation_en": "This is a reminder. The devout will have a good place of return.", "translation_id": "Ini adalah kehormatan (bagi mereka). Dan sesungguhnya bagi orang-orang yang bertakwa benar-benar (disediakan) tempat kembali yang baik,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 50, "text": "جَنَّـٰتِ عَدۡنࣲ مُّفَتَّحَةࣰ لَّهُمُ ٱلۡأَبۡوَ ٰبُ ۝٥٠", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "هذا القرآن ذِكْر وشرف لك -أيها الرسول- ولقومك. وإن لأهل تقوى الله وطاعته لَحسنَ مصير عندنا في جنات إقامة، مفتَّحة لهم أبوابها، متكئين فيها على الأرائك المزيَّنات، يطلبون ما يشتهون من أنواع الفواكه الكثيرة والشراب، من كل ما تشتهيه نفوسهم، وتلذه أعينهم.", "isBasmala": false, "translation_en": "The Gardens of Eden, with their doors wide-open for them.", "translation_id": "(yaitu) surga 'Adn yang pintu-pintunya terbuka bagi mereka,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 51, "text": "مُتَّكِـِٔینَ فِیهَا یَدۡعُونَ فِیهَا بِفَـٰكِهَةࣲ كَثِیرَةࣲ وَشَرَابࣲ ۝٥١", "juz": 23, "hizb": "(*¼ ح 46*)", "tafsir": "هذا القرآن ذِكْر وشرف لك -أيها الرسول- ولقومك. وإن لأهل تقوى الله وطاعته لَحسنَ مصير عندنا في جنات إقامة، مفتَّحة لهم أبوابها، متكئين فيها على الأرائك المزيَّنات، يطلبون ما يشتهون من أنواع الفواكه الكثيرة والشراب، من كل ما تشتهيه نفوسهم، وتلذه أعينهم.", "isBasmala": false, "translation_en": "Relaxing therein, and calling for abundant fruit and beverage.", "translation_id": "di dalamnya mereka bertelekan (diatas dipan-dipan) sambil meminta buah-buahan yang banyak dan minuman di surga itu.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 52, "text": "۞ وَعِندَهُمۡ قَـٰصِرَ ٰتُ ٱلطَّرۡفِ أَتۡرَابٌ ۝٥٢", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "وعندهم نساء قاصرات أبصارهن على أزواجهن متساويات في السن.", "isBasmala": false, "translation_en": "With them will be attendants with modest gaze, of same age.", "translation_id": "Dan pada sisi mereka (ada bidadari-bidadari) yang tidak liar pandangannya dan sebaya umurnya.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 53, "text": "هَـٰذَا مَا تُوعَدُونَ لِیَوۡمِ ٱلۡحِسَابِ ۝٥٣", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "هذا النعيم هو ما توعدون به- أيها المتقون- يوم القيامة، إنه لَرزقنا لكم، ليس له فناء ولا انقطاع.", "isBasmala": false, "translation_en": "This is what you are promised for the Day of Account.", "translation_id": "Inilah apa yang dijanjikan kepadamu pada hari berhisab.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 54, "text": "إِنَّ هَـٰذَا لَرِزۡقُنَا مَا لَهُۥ مِن نَّفَادٍ ۝٥٤", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "هذا النعيم هو ما توعدون به- أيها المتقون- يوم القيامة، إنه لَرزقنا لكم، ليس له فناء ولا انقطاع.", "isBasmala": false, "translation_en": "Such is Our bounty, inexhaustible.", "translation_id": "Sesungguhnya ini adalah benar-benar rezeki dari Kami yang tiada habis-habisnya.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 55, "text": "هَـٰذَاۚ وَإِنَّ لِلطَّـٰغِینَ لَشَرَّ مَـَٔابࣲ ۝٥٥", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "هذا الذي سبق وصفه للمتقين. وأما المتجاوزون الحدَّ في الكفر والمعاصي، فلهم شر مرجع ومصير، وهو النار يُعذَّبون فيها، تغمرهم من جميع جوانبهم، فبئس الفراش فراشهم.", "isBasmala": false, "translation_en": "All This. But the transgressors will have a miserable return.", "translation_id": "Beginilah (keadaan mereka). Dan sesungguhnya bagi orang-orang yang durhaka benar-benar (disediakan) tempat kembali yang buruk,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 56, "text": "جَهَنَّمَ یَصۡلَوۡنَهَا فَبِئۡسَ ٱلۡمِهَادُ ۝٥٦", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "هذا الذي سبق وصفه للمتقين. وأما المتجاوزون الحدَّ في الكفر والمعاصي، فلهم شر مرجع ومصير، وهو النار يُعذَّبون فيها، تغمرهم من جميع جوانبهم، فبئس الفراش فراشهم.", "isBasmala": false, "translation_en": "Hell; in which they will roast; what a miserable abode!", "translation_id": "(yaitu) neraka Jahannam, yang mereka masuk ke dalamnya; maka amat buruklah Jahannam itu sebagai tempat tinggal.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 57, "text": "هَـٰذَا فَلۡیَذُوقُوهُ حَمِیمࣱ وَغَسَّاقࣱ ۝٥٧", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "هذا العذاب ماء شديد الحرارة، وصديد سائل من أجساد أهل النار فليشربوه، ولهم عذاب آخر من هذا القبيل أصناف وألوان.", "isBasmala": false, "translation_en": "All this. Let them taste it-boiling and bitter cold.", "translation_id": "Inilah (azab neraka), biarlah mereka merasakannya, (minuman mereka) air yang sangat panas dan air yang sangat dingin.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 58, "text": "وَءَاخَرُ مِن شَكۡلِهِۦۤ أَزۡوَ ٰجٌ ۝٥٨", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "هذا العذاب ماء شديد الحرارة، وصديد سائل من أجساد أهل النار فليشربوه، ولهم عذاب آخر من هذا القبيل أصناف وألوان.", "isBasmala": false, "translation_en": "And similar torments of diverse kinds.", "translation_id": "Dan azab yang lain yang serupa itu berbagai macam.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 59, "text": "هَـٰذَا فَوۡجࣱ مُّقۡتَحِمࣱ مَّعَكُمۡ لَا مَرۡحَبَۢا بِهِمۡۚ إِنَّهُمۡ صَالُوا۟ ٱلنَّارِ ۝٥٩", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "وعند توارد الطاغين على النار يَشْتم بعضهم بعضًا، ويقول بعضهم لبعض: هذه جماعة من أهل النار داخلة معكم، فيجيبون: لا مرحبًا بهم، ولا اتسعت منازلهم في النار، إنهم مقاسون حرَّ النار كما قاسيناها.", "isBasmala": false, "translation_en": "\"This is a crowd rushing headlong with you.\" There is no welcome for them. They will be scorched by the Fire.", "translation_id": "(Dikatakan kepada mereka): \"Ini adalah suatu rombongan (pengikut-pengikutmu) yang masuk berdesak-desak bersama kamu (ke neraka)\". (Berkata pemimpin-pemimpin mereka yang durhaka): \"Tiadalah ucapan selamat datang kepada mereka karena sesungguhnya mereka akan masuk neraka\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 60, "text": "قَالُوا۟ بَلۡ أَنتُمۡ لَا مَرۡحَبَۢا بِكُمۡۖ أَنتُمۡ قَدَّمۡتُمُوهُ لَنَاۖ فَبِئۡسَ ٱلۡقَرَارُ ۝٦٠", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال فوج الأتباع للطاغين: بل أنتم لا مرحبًا بكم؛ لأنكم قدَّمتم لنا سكنى النار لإضلالكم لنا في الدنيا، فبئس دار الاستقرار جهنم.", "isBasmala": false, "translation_en": "They will say, \"But it is you! There is no welcome for you! It is you who brought it upon us! What a miserable end!\"", "translation_id": "Pengikut-pengikut mereka menjawab: \"Sebenarnya kamulah. Tiada ucapan selamat datang bagimu, karena kamulah yang menjerumuskan kami ke dalam azab, maka amat buruklah Jahannam itu sebagai tempat menetap\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 61, "text": "قَالُوا۟ رَبَّنَا مَن قَدَّمَ لَنَا هَـٰذَا فَزِدۡهُ عَذَابࣰا ضِعۡفࣰا فِی ٱلنَّارِ ۝٦١", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال فوج الأتباع: ربنا مَن أضلَّنا في الدنيا عن الهدى فضاعِف عذابه في النار.", "isBasmala": false, "translation_en": "They will say, \"Our Lord, whoever brought this upon us, give him double torment in the Fire.\"", "translation_id": "Mereka berkata (lagi): \"Ya Tuhan kami; barang siapa yang menjerumuskan kami ke dalam azab ini maka tambahkanlah azab kepadanya dengan berlipat ganda di dalam neraka\".", "manzil": 6, "manzil_display": ""}], "457": [{"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 62, "text": "وَقَالُوا۟ مَا لَنَا لَا نَرَىٰ رِجَالࣰا كُنَّا نَعُدُّهُم مِّنَ ٱلۡأَشۡرَارِ ۝٦٢", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "وقال الطاغون: ما بالنا لا نرى معنا في النار رجالا كنا نعدهم في الدنيا من الأشرار الأشقياء؟ هل تحقيرنا لهم واستهزاؤنا بهم خطأ، أو أنهم معنا في النار، لكن لم تقع عليهم الأبصار؟", "isBasmala": false, "translation_en": "And they will say, \"What is it with us that we do not see men we used to count among the wicked?", "translation_id": "Dan (orang-orang durhaka) berkata: \"Mengapa kami tidak melihat orang-orang yang dahulu (di dunia) kami anggap sebagai orang-orang yang jahat (hina).", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 63, "text": "أَتَّخَذۡنَـٰهُمۡ سِخۡرِیًّا أَمۡ زَاغَتۡ عَنۡهُمُ ٱلۡأَبۡصَـٰرُ ۝٦٣", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "وقال الطاغون: ما بالنا لا نرى معنا في النار رجالا كنا نعدهم في الدنيا من الأشرار الأشقياء؟ هل تحقيرنا لهم واستهزاؤنا بهم خطأ، أو أنهم معنا في النار، لكن لم تقع عليهم الأبصار؟", "isBasmala": false, "translation_en": "Did we take them for mockery, or have our eyes swerved from them?", "translation_id": "Apakah kami dahulu menjadikan mereka olok-olokan, ataukah karena mata kami tidak melihat mereka?\"", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 64, "text": "إِنَّ ذَ ٰلِكَ لَحَقࣱّ تَخَاصُمُ أَهۡلِ ٱلنَّارِ ۝٦٤", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "إن ذلك من جدال أهل النار وخصامهم حق واقع لا مرية فيه.", "isBasmala": false, "translation_en": "This is certainly true-the feuding of the people of the Fire.", "translation_id": "Sesungguhnya yang demikian itu pasti terjadi, (yaitu) pertengkaran penghuni neraka.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 65, "text": "قُلۡ إِنَّمَاۤ أَنَا۠ مُنذِرࣱۖ وَمَا مِنۡ إِلَـٰهٍ إِلَّا ٱللَّهُ ٱلۡوَ ٰحِدُ ٱلۡقَهَّارُ ۝٦٥", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قل -أيها الرسول- لقومك: إنما أنا منذر لكم من عذاب الله أن يحل بكم؛ بسبب كفركم به، ليس هناك إله مستحق للعبادة إلا الله وحده، فهو المتفردُ بعظمته وأسمائه وصفاته وأفعاله، القهَّارُ الذي قهر كل شيء وغلبه.", "isBasmala": false, "translation_en": "Say, \"I am only a warner, and there is no god except God-the One, the Conqueror.", "translation_id": "Katakanlah (ya Muhammad): \"Sesungguhnya aku hanya seorang pemberi peringatan, dan sekali-kali tidak ada Tuhan selain Allah Yang Maha Esa dan Maha Mengalahkan.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 66, "text": "رَبُّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا ٱلۡعَزِیزُ ٱلۡغَفَّـٰرُ ۝٦٦", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "مالك السموات والأرض وما بينهما العزيز في انتقامه، الغفار لذنوب مَن تاب وأناب إلى مرضاته.", "isBasmala": false, "translation_en": "The Lord of the heavens and the earth, and everything between them; the Mighty, the Forgiver.\"", "translation_id": "Tuhan langit dan bumi dan apa yang ada di antara keduanya Yang Maha Perkasa lagi Maha Pengampun.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 67, "text": "قُلۡ هُوَ نَبَؤٌا۟ عَظِیمٌ ۝٦٧", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قل -أيها الرسول- لقومك: إن هذا القرآن خبر عظيم النفع. أنتم عنه غافلون منصرفون، لا تعملون به.", "isBasmala": false, "translation_en": "Say, \"It is a message of great importance.", "translation_id": "Katakanlah: \"Berita itu adalah berita yang besar,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 68, "text": "أَنتُمۡ عَنۡهُ مُعۡرِضُونَ ۝٦٨", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قل -أيها الرسول- لقومك: إن هذا القرآن خبر عظيم النفع. أنتم عنه غافلون منصرفون، لا تعملون به.", "isBasmala": false, "translation_en": "From which you are turning away.", "translation_id": "yang kamu berpaling daripadanya.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 69, "text": "مَا كَانَ لِیَ مِنۡ عِلۡمِۭ بِٱلۡمَلَإِ ٱلۡأَعۡلَىٰۤ إِذۡ یَخۡتَصِمُونَ ۝٦٩", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "ليس لي علم باختصام ملائكة السماء في شأن خلق آدم، لولا تعليم الله إياي، وإيحاؤه إليَّ.", "isBasmala": false, "translation_en": "I have no knowledge of the Highest Assembly as they dispute.", "translation_id": "Aku tiada mempunyai pengetahuan sedikitpun tentang al mala'ul a'la (malaikat) itu ketika mereka berbantah-bantahan.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 70, "text": "إِن یُوحَىٰۤ إِلَیَّ إِلَّاۤ أَنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینٌ ۝٧٠", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "ما يوحي الله إليَّ مِن عِلْم ما لا علم لي به إلا لأني نذير لكم من عذابه، مبيِّن لكم شرعه.", "isBasmala": false, "translation_en": "It is only revealed to me that I am a clear warner.\"", "translation_id": "Tidak diwahyukan kepadaku, melainkan bahwa sesungguhnya aku hanyalah seorang pemberi peringatan yang nyata\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 71, "text": "إِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰۤىِٕكَةِ إِنِّی خَـٰلِقُۢ بَشَرࣰا مِّن طِینࣲ ۝٧١", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "اذكر لهم -أيها الرسول-: حين قال ربك للملائكة: إني خالق بشرًا من طين. فإذا سوَّيت جسده وخلقه ونفخت فيه الروح، فدبت فيه الحياة، فاسجدوا له سجود تحية وإكرام، لا سجود عبادة وتعظيم؛ فالعبادة لا تكون إلا لله وحده. وقد حرَّم الله في شريعة الإسلام السجود للتحية.", "isBasmala": false, "translation_en": "Your Lord said to the angels, \"I am creating a human being from clay.", "translation_id": "(Ingatlah) ketika Tuhanmu berfirman kepada malaikat: \"Sesungguhnya Aku akan menciptakan manusia dari tanah\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 72, "text": "فَإِذَا سَوَّیۡتُهُۥ وَنَفَخۡتُ فِیهِ مِن رُّوحِی فَقَعُوا۟ لَهُۥ سَـٰجِدِینَ ۝٧٢", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "اذكر لهم -أيها الرسول-: حين قال ربك للملائكة: إني خالق بشرًا من طين. فإذا سوَّيت جسده وخلقه ونفخت فيه الروح، فدبت فيه الحياة، فاسجدوا له سجود تحية وإكرام، لا سجود عبادة وتعظيم؛ فالعبادة لا تكون إلا لله وحده. وقد حرَّم الله في شريعة الإسلام السجود للتحية.", "isBasmala": false, "translation_en": "When I have formed him, and breathed into him of My spirit, fall prostrate before him.", "translation_id": "Maka apabila telah Kusempurnakan kejadiannya dan Kutiupkan kepadanya roh (ciptaan)Ku; maka hendaklah kamu tersungkur dengan bersujud kepadanya\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 73, "text": "فَسَجَدَ ٱلۡمَلَـٰۤىِٕكَةُ كُلُّهُمۡ أَجۡمَعُونَ ۝٧٣", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "فسجد الملائكة كلهم أجمعون طاعة وامتثالا غير إبليس؛ فإنه لم يسجد أنَفَةً وتكبرًا، وكان من الكافرين في علم الله تعالى.", "isBasmala": false, "translation_en": "So the angels fell prostrate, all of them.", "translation_id": "Lalu seluruh malaikat-malaikat itu bersujud semuanya,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 74, "text": "إِلَّاۤ إِبۡلِیسَ ٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَـٰفِرِینَ ۝٧٤", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "فسجد الملائكة كلهم أجمعون طاعة وامتثالا غير إبليس؛ فإنه لم يسجد أنَفَةً وتكبرًا، وكان من الكافرين في علم الله تعالى.", "isBasmala": false, "translation_en": "Except for Satan. He was too proud, and one of the faithless.", "translation_id": "kecuali iblis; dia menyombongkan diri dan adalah dia termasuk orang-orang yang kafir.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 75, "text": "قَالَ یَـٰۤإِبۡلِیسُ مَا مَنَعَكَ أَن تَسۡجُدَ لِمَا خَلَقۡتُ بِیَدَیَّۖ أَسۡتَكۡبَرۡتَ أَمۡ كُنتَ مِنَ ٱلۡعَالِینَ ۝٧٥", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال الله لإبليس: ما الذي منعك من السجود لمن أكرمتُه فخلقتُه بيديَّ؟ أستكبرت على آدم، أم كنت من المتكبرين على ربك؟ وفي الآية إثبات صفة اليدين لله تبارك وتعالى، على الوجه اللائق به سبحانه.", "isBasmala": false, "translation_en": "He said, \"O Satan, what prevented you from prostrating before what I created with My Own hands? Are you too proud, or were you one of the exalted?\"", "translation_id": "Allah berfirman: \"Hai iblis, apakah yang menghalangi kamu sujud kepada yang telah Ku-ciptakan dengan kedua tangan-Ku. Apakah kamu menyombongkan diri ataukah kamu (merasa) termasuk orang-orang yang (lebih) tinggi?\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 76, "text": "قَالَ أَنَا۠ خَیۡرࣱ مِّنۡهُ خَلَقۡتَنِی مِن نَّارࣲ وَخَلَقۡتَهُۥ مِن طِینࣲ ۝٧٦", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال إبليس معارضًا لربه: لم أسجد له؛ لأنني أفضل منه، حيث خلقتني من نارٍ، وخلقته من طين. (والنار خير من الطين).", "isBasmala": false, "translation_en": "He said, \"I am better than he; You created me from fire, and You created him from clay.\"", "translation_id": "Iblis berkata: \"Aku lebih baik daripadanya, karena Engkau ciptakan aku dari api, sedangkan dia Engkau ciptakan dari tanah\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 77, "text": "قَالَ فَٱخۡرُجۡ مِنۡهَا فَإِنَّكَ رَجِیمࣱ ۝٧٧", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال الله له: فاخرج من الجنة فإنك مرجوم بالقول، مدحور ملعون، وإن عليك طردي وإبعادي إلى يوم القيامة.", "isBasmala": false, "translation_en": "He said, \"Then get out of here! You are an outcast!", "translation_id": "Allah berfirman: \"Maka keluarlah kamu dari surga; sesungguhnya kamu adalah orang yang terkutuk,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 78, "text": "وَإِنَّ عَلَیۡكَ لَعۡنَتِیۤ إِلَىٰ یَوۡمِ ٱلدِّینِ ۝٧٨", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال الله له: فاخرج من الجنة فإنك مرجوم بالقول، مدحور ملعون، وإن عليك طردي وإبعادي إلى يوم القيامة.", "isBasmala": false, "translation_en": "And My curse will be upon you until the Day of Judgment.\"", "translation_id": "Sesungguhnya kutukan-Ku tetap atasmu sampai hari pembalasan\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 79, "text": "قَالَ رَبِّ فَأَنظِرۡنِیۤ إِلَىٰ یَوۡمِ یُبۡعَثُونَ ۝٧٩", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال إبليس: ربِّ فأخِّر أجلي، ولا تهلكني إلى حين تَبعث الخلق من قبورهم.", "isBasmala": false, "translation_en": "He said, \"Lord, defer me until the Day they are resurrected.\"", "translation_id": "Iblis berkata: \"Ya Tuhanku, beri tangguhlah aku sampai hari mereka dibangkitkan\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 80, "text": "قَالَ فَإِنَّكَ مِنَ ٱلۡمُنظَرِینَ ۝٨٠", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال الله له: فإنك من المؤخَّرين إلى يوم الوقت المعلوم، وهو يوم النفخة الأولى عندما تموت الخلائق.", "isBasmala": false, "translation_en": "He said, \"You are one of those deferred.", "translation_id": "Allah berfirman: \"Sesungguhnya kamu termasuk orang-orang yang diberi tangguh,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 81, "text": "إِلَىٰ یَوۡمِ ٱلۡوَقۡتِ ٱلۡمَعۡلُومِ ۝٨١", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال الله له: فإنك من المؤخَّرين إلى يوم الوقت المعلوم، وهو يوم النفخة الأولى عندما تموت الخلائق.", "isBasmala": false, "translation_en": "Until the Day of the Time Appointed.\"", "translation_id": "sampai kepada hari yang telah ditentukan waktunya (hari Kiamat)\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 82, "text": "قَالَ فَبِعِزَّتِكَ لَأُغۡوِیَنَّهُمۡ أَجۡمَعِینَ ۝٨٢", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال إبليس: فبعزتك- يا رب- وعظمتك لأضلنَّ بني آدم أجمعين، إلا مَن أخلصتَه منهم لعبادتك، وعصمتَه من إضلالي، فلم تجعل لي عليهم سبيلا.", "isBasmala": false, "translation_en": "He said, \"By Your majesty, I will seduce them all.", "translation_id": "Iblis menjawab: \"Demi kekuasaan Engkau aku akan menyesatkan mereka semuanya,", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 83, "text": "إِلَّا عِبَادَكَ مِنۡهُمُ ٱلۡمُخۡلَصِینَ ۝٨٣", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال إبليس: فبعزتك- يا رب- وعظمتك لأضلنَّ بني آدم أجمعين، إلا مَن أخلصتَه منهم لعبادتك، وعصمتَه من إضلالي، فلم تجعل لي عليهم سبيلا.", "isBasmala": false, "translation_en": "Except for your loyal servants among them.\"", "translation_id": "kecuali hamba-hamba-Mu yang mukhlis di antara mereka.", "manzil": 6, "manzil_display": ""}], "458": [{"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 84, "text": "قَالَ فَٱلۡحَقُّ وَٱلۡحَقَّ أَقُولُ ۝٨٤", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال الله: فالحقُّ مني، ولا أقول إلا الحق، لأملان جهنم منك ومن ذريتك وممن تبعك من بني آدم أجمعين.", "isBasmala": false, "translation_en": "He said, \"The truth is, and I say the truth.", "translation_id": "Allah berfirman: \"Maka yang benar (adalah sumpah-Ku) dan hanya kebenaran itulah yang Ku-katakan\".", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 85, "text": "لَأَمۡلَأَنَّ جَهَنَّمَ مِنكَ وَمِمَّن تَبِعَكَ مِنۡهُمۡ أَجۡمَعِینَ ۝٨٥", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قال الله: فالحقُّ مني، ولا أقول إلا الحق، لأملان جهنم منك ومن ذريتك وممن تبعك من بني آدم أجمعين.", "isBasmala": false, "translation_en": "I will fill Hell with you, and with every one of them who follows you.\"", "translation_id": "Sesungguhnya Aku pasti akan memenuhi neraka Jahannam dengan jenis kamu dan dengan orang-orang yang mengikuti kamu di antara mereka kesemuanya.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 86, "text": "قُلۡ مَاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ مِنۡ أَجۡرࣲ وَمَاۤ أَنَا۠ مِنَ ٱلۡمُتَكَلِّفِینَ ۝٨٦", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين من قومك: لا أطلب منكم أجرًا أو جزاءً على دعوتكم وهدايتكم، ولا أدَّعي أمرًا ليس لي، بل أتبع ما يوحى إليَّ، ولا أتكلف تخرُّصًا وافتراءً.", "isBasmala": false, "translation_en": "Say, \"I ask of you no wage for this, and I am not a pretender.", "translation_id": "Katakanlah (hai Muhammad): \"Aku tidak meminta upah sedikitpun padamu atas dakwahku dan bukanlah aku termasuk orang-orang yang mengada-adakan.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 87, "text": "إِنۡ هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَـٰلَمِینَ ۝٨٧", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "ما هذا القرآن إلا تذكير للعالمين من الجن والإنس، يتذكرون به ما ينفعهم من مصالح دينهم ودنياهم.", "isBasmala": false, "translation_en": "It is but a reminder to mankind.", "translation_id": "Al Quran ini tidak lain hanyalah peringatan bagi semesta alam.", "manzil": 6, "manzil_display": ""}, {"sura": 38, "sura_name": "ص", "revelation": "Makkiyah", "aya": 88, "text": "وَلَتَعۡلَمُنَّ نَبَأَهُۥ بَعۡدَ حِینِۭ ۝٨٨", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "ولتعلمن- أيها المشركون- خبر هذا القرآن وصدقه، حين يَغْلب الإسلام، ويدخل الناس فيه أفواجًا، وكذلك حين يقع عليكم العذاب، وتنقطع عنكم الأسباب.", "isBasmala": false, "translation_en": "And you will know its message after a while.\"", "translation_id": "Dan sesungguhnya kamu akan mengetahui (kebenaran) berita Al Quran setelah beberapa waktu lagi.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 24, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 1, "text": "تَنزِیلُ ٱلۡكِتَـٰبِ مِنَ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ ۝١", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "تنزيل القرآن إنما هو من الله العزيز في قدرته وانتقامه، الحكيم في تدبيره وأحكامه.", "isBasmala": false, "translation_en": "The revelation of the Book is from God, the Mighty and Wise.", "translation_id": "Kitab (Al Quran ini) diturunkan oleh Allah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 2, "text": "إِنَّاۤ أَنزَلۡنَاۤ إِلَیۡكَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ فَٱعۡبُدِ ٱللَّهَ مُخۡلِصࣰا لَّهُ ٱلدِّینَ ۝٢", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "إنا أنزلنا إليك -أيها الرسول- القرآن يأمر بالحق والعدل، فاعبد الله وحده، وأخلص له جميع دينك.", "isBasmala": false, "translation_en": "We sent down to you the Book with the truth, so serve God, devoting your religion to Him.", "translation_id": "Sesunguhnya Kami menurunkan kepadamu Kitab (Al Quran) dengan (membawa) kebenaran. Maka sembahlah Allah dengan memurnikan ketaatan kepada-Nya.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 3, "text": "أَلَا لِلَّهِ ٱلدِّینُ ٱلۡخَالِصُۚ وَٱلَّذِینَ ٱتَّخَذُوا۟ مِن دُونِهِۦۤ أَوۡلِیَاۤءَ مَا نَعۡبُدُهُمۡ إِلَّا لِیُقَرِّبُونَاۤ إِلَى ٱللَّهِ زُلۡفَىٰۤ إِنَّ ٱللَّهَ یَحۡكُمُ بَیۡنَهُمۡ فِی مَا هُمۡ فِیهِ یَخۡتَلِفُونَۗ إِنَّ ٱللَّهَ لَا یَهۡدِی مَنۡ هُوَ كَـٰذِبࣱ كَفَّارࣱ ۝٣", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "ألا لله وحده الطاعة التامة السالمة من الشرك، والذين أشركوا مع الله غيره واتخذوا من دونه أولياء، قالوا: ما نعبد تلك الآلهة مع الله إلا لتشفع لنا عند الله، وتقربنا عنده منزلة، فكفروا بذلك؛ لأن العبادة والشفاعة لله وحده، إن الله يفصل بين المؤمنين المخلصين والمشركين مع الله غيره يوم القيامة فيما يختلفون فيه من عبادتهم، فيجازي كلا بما يستحق. إن الله لا يوفق للهداية إلى الصراط المستقيم من هو مفترٍ على الله، كَفَّار بآياته وحججه.", "isBasmala": false, "translation_en": "Is not to God that sincere faith is due? As for those who take guardians besides Him, \"We only worship them that they may bring us nearer to God.\" God will judge between them regarding their differences. God does not guide the lying blasphemer.", "translation_id": "Ingatlah, hanya kepunyaan Allah-lah agama yang bersih (dari syirik). Dan orang-orang yang mengambil pelindung selain Allah (berkata): \"Kami tidak menyembah mereka melainkan supaya mereka mendekatkan kami kepada Allah dengan sedekat-dekatnya\". Sesungguhnya Allah akan memutuskan di antara mereka tentang apa yang mereka berselisih padanya. Sesungguhnya Allah tidak menunjuki orang-orang yang pendusta dan sangat ingkar.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 4, "text": "لَّوۡ أَرَادَ ٱللَّهُ أَن یَتَّخِذَ وَلَدࣰا لَّٱصۡطَفَىٰ مِمَّا یَخۡلُقُ مَا یَشَاۤءُۚ سُبۡحَـٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَ ٰحِدُ ٱلۡقَهَّارُ ۝٤", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "لو أراد الله أن يتخذ ولدًا لاختار من مخلوقاته ما يشاء، تنزَّه الله وتقدَّس عن أن يكون له ولد، فإنه الواحد الأحد، الفرد الصمد، القهَّار الذي قهر خلقه بقدرته، فكل شيء له متذلل خاضع.", "isBasmala": false, "translation_en": "If God wanted to have a son, He could have selected from His creation at will. Glory be to Him. He is God, the One, the Prevailing.", "translation_id": "Kalau sekiranya Allah hendak mengambil anak, tentu Dia akan memilih apa yang dikehendaki-Nya di antara ciptaan-ciptaan yang telah diciptakan-Nya. Maha Suci Allah. Dialah Allah Yang Maha Esa lagi Maha Mengalahkan.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 5, "text": "خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۖ یُكَوِّرُ ٱلَّیۡلَ عَلَى ٱلنَّهَارِ وَیُكَوِّرُ ٱلنَّهَارَ عَلَى ٱلَّیۡلِۖ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِی لِأَجَلࣲ مُّسَمًّىۗ أَلَا هُوَ ٱلۡعَزِیزُ ٱلۡغَفَّـٰرُ ۝٥", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "خلق الله السموات والأرض وما فيهما بالحق، يجيء بالليل ويذهب بالنهار، ويجيء بالنهار ويذهب بالليل، وذلَّل الشمس والقمر بانتظام لمنافع العباد، كل منهما يجري في مداره إلى حين قيام الساعة. ألا إن الله الذي فعل هذه الأفعال، وأنعم على خلقه بهذه النعم هو العزيز على خلقه، الغفار لذنوب عباده التائبين.", "isBasmala": false, "translation_en": "He created the heavens and the earth with reason. He wraps the night around the day, and He wraps the day around the night. And He regulates the sun and the moon, each running along a specific course. He is indeed the Almighty, the Forgiver.", "translation_id": "Dia menciptakan langit dan bumi dengan (tujuan) yang benar; Dia menutupkan malam atas siang dan menutupkan siang atas malam dan menundukkan matahari dan bulan, masing-masing berjalan menurut waktu yang ditentukan. Ingatlah Dialah Yang Maha Perkasa lagi Maha Pengampun.", "manzil": 6, "manzil_display": ""}], "459": [{"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 6, "text": "خَلَقَكُم مِّن نَّفۡسࣲ وَ ٰحِدَةࣲ ثُمَّ جَعَلَ مِنۡهَا زَوۡجَهَا وَأَنزَلَ لَكُم مِّنَ ٱلۡأَنۡعَـٰمِ ثَمَـٰنِیَةَ أَزۡوَ ٰجࣲۚ یَخۡلُقُكُمۡ فِی بُطُونِ أُمَّهَـٰتِكُمۡ خَلۡقࣰا مِّنۢ بَعۡدِ خَلۡقࣲ فِی ظُلُمَـٰتࣲ ثَلَـٰثࣲۚ ذَ ٰلِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۖ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُصۡرَفُونَ ۝٦", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "خلقكم ربكم- أيها الناس- من آدم، وخلق منه زوجه، وخلق لكم من الأنعام ثمانية أنواع ذكر‌ًا وأنثى من الإبل والبقر والضأن والمعز، يخلقكم في بطون أمهاتكم طورًا بعد طور من الخلق في ظلمات البطن، والرحم، والمَشِيمَة، ذلكم الله الذي خلق هذه الأشياء، ربكم المتفرد بالملك المتوحد بالألوهية المستحق للعبادة وحده، فكيف تعدلون عن عبادته إلى عبادة غيره مِن خلقه؟", "isBasmala": false, "translation_en": "He created you from one person, then made from it its mate, and brought down livestock for you-eight kinds in pairs. He creates you in the wombs of your mothers, in successive formations, in a triple darkness. Such is God, your Lord. His is the kingdom. There is no god but He. So what made you deviate?", "translation_id": "Dia menciptakan kamu dari seorang diri kemudian Dia jadikan daripadanya isterinya dan Dia menurunkan untuk kamu delapan ekor yang berpasangan dari binatang ternak. Dia menjadikan kamu dalam perut ibumu kejadian demi kejadian dalam tiga kegelapan. Yang (berbuat) demikian itu adalah Allah, Tuhan kamu, Tuhan Yang mempunyai kerajaan. Tidak ada Tuhan selain Dia; maka bagaimana kamu dapat dipalingkan?", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 7, "text": "إِن تَكۡفُرُوا۟ فَإِنَّ ٱللَّهَ غَنِیٌّ عَنكُمۡۖ وَلَا یَرۡضَىٰ لِعِبَادِهِ ٱلۡكُفۡرَۖ وَإِن تَشۡكُرُوا۟ یَرۡضَهُ لَكُمۡۗ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝٧", "juz": 23, "hizb": "(*½ ح 46*)", "tafsir": "إن تكفروا- أيها الناس- بربكم ولم تؤمنوا به، ولم تتبعوا رسله، فإنه غنيٌّ عنكم، ليس بحاجة إليكم، وأنتم الفقراء إليه، ولا يرضى لعباده الكفر، ولا يأمرهم به، وإنما يرضى لهم شكر نعمه عليهم. ولا تحمل نفس إثم نفس أخرى، ثم إلى ربكم مصيركم، فيخبركم بعملكم، ويحاسبكم عليه. إنه عليم بأسرار النفوس وما تخفي الصدور.", "isBasmala": false, "translation_en": "If you disbelieve, God is Independent of you, yet He does not approve ingratitude on the part of His servants. And if you are thankful, He will approve that in you. No bearer of burden can bear the burden of another. Then to your Lord is your return; and He will inform you of what you used to do. He is aware of what the hearts contain.", "translation_id": "Jika kamu kafir maka sesungguhnya Allah tidak memerlukan (iman)mu dan Dia tidak meridhai kekafiran bagi hamba-Nya; dan jika kamu bersyukur, niscaya Dia meridhai bagimu kesyukuranmu itu; dan seorang yang berdosa tidak akan memikul dosa orang lain. Kemudian kepada Tuhanmulah kembalimu lalu Dia memberitakan kepadamu apa yang telah kamu kerjakan. Sesungguhnya Dia Maha Mengetahui apa yang tersimpan dalam (dada)mu.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 8, "text": "۞ وَإِذَا مَسَّ ٱلۡإِنسَـٰنَ ضُرࣱّ دَعَا رَبَّهُۥ مُنِیبًا إِلَیۡهِ ثُمَّ إِذَا خَوَّلَهُۥ نِعۡمَةࣰ مِّنۡهُ نَسِیَ مَا كَانَ یَدۡعُوۤا۟ إِلَیۡهِ مِن قَبۡلُ وَجَعَلَ لِلَّهِ أَندَادࣰا لِّیُضِلَّ عَن سَبِیلِهِۦۚ قُلۡ تَمَتَّعۡ بِكُفۡرِكَ قَلِیلًا إِنَّكَ مِنۡ أَصۡحَـٰبِ ٱلنَّارِ ۝٨", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "وإذا أصاب الإنسانَ بلاءٌ وشدة ومرض تَذكَّر ربه، فاستغاث به ودعاه، ثم إذا أجابه وكشف عنه ضرَّه، ومنحه نِعَمه، نسي دعاءه لربه عند حاجته إليه، وأشرك معه غيره؛ ليُضل غيره عن الإيمان بالله وطاعته، قل له -أيها الرسول- متوعدًا: تمتع بكفرك قليلا حتى موتك وانتهاء أجلك، إنك من أهل النار المخلَّدين فيها.", "isBasmala": false, "translation_en": "When some adversity touches the human being, he prays to his Lord, repenting to Him. But then, when He confers on him a grace of His, he forgets what he was praying for before, and he attributes rivals to God, in order to lead astray from His way. Say, \"Enjoy your disbelief for a little while; you will be among the inmates of the Fire.\"", "translation_id": "Dan apabila manusia itu ditimpa kemudharatan, dia memohon (pertolongan) kepada Tuhannya dengan kembali kepada-Nya; kemudian apabila Tuhan memberikan nikmat-Nya kepadanya lupalah dia akan kemudharatan yang pernah dia berdoa (kepada Allah) untuk (menghilangkannya) sebelum itu, dan dia mengada-adakan sekutu-sekutu bagi Allah untuk menyesatkan (manusia) dari jalan-Nya. Katakanlah: \"Bersenang-senanglah dengan kekafiranmu itu sementara waktu; sesungguhnya kamu termasuk penghuni neraka\".", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 9, "text": "أَمَّنۡ هُوَ قَـٰنِتٌ ءَانَاۤءَ ٱلَّیۡلِ سَاجِدࣰا وَقَاۤىِٕمࣰا یَحۡذَرُ ٱلۡـَٔاخِرَةَ وَیَرۡجُوا۟ رَحۡمَةَ رَبِّهِۦۗ قُلۡ هَلۡ یَسۡتَوِی ٱلَّذِینَ یَعۡلَمُونَ وَٱلَّذِینَ لَا یَعۡلَمُونَۗ إِنَّمَا یَتَذَكَّرُ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ ۝٩", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "أهذا الكافر المتمتع بكفره خير، أم من هو عابد لربه طائع له، يقضي ساعات الليل في القيام والسجود لله، يخاف عذاب الآخرة، ويأمُل رحمة ربه؟ قل -أيها الرسول-: هل يستوي الذين يعلمون ربهم ودينهم الحق والذين لا يعلمون شيئًا من ذلك؟ لا يستوون. إنما يتذكر ويعرف الفرق أصحاب العقول السليمة.", "isBasmala": false, "translation_en": "Is he who worships devoutly during the watches of the night, prostrating himself and standing up, mindful of the Hereafter, and placing his hope in the mercy of his Lord? Say, \"Are those who know and those who do not know equal?\" Only those possessed of reason will remember.", "translation_id": "(Apakah kamu hai orang musyrik yang lebih beruntung) ataukah orang yang beribadat di waktu-waktu malam dengan sujud dan berdiri, sedang ia takut kepada (azab) akhirat dan mengharapkan rahmat Tuhannya? Katakanlah: \"Adakah sama orang-orang yang mengetahui dengan orang-orang yang tidak mengetahui?\" Sesungguhnya orang yang berakallah yang dapat menerima pelajaran.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 10, "text": "قُلۡ یَـٰعِبَادِ ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ رَبَّكُمۡۚ لِلَّذِینَ أَحۡسَنُوا۟ فِی هَـٰذِهِ ٱلدُّنۡیَا حَسَنَةࣱۗ وَأَرۡضُ ٱللَّهِ وَ ٰسِعَةٌۗ إِنَّمَا یُوَفَّى ٱلصَّـٰبِرُونَ أَجۡرَهُم بِغَیۡرِ حِسَابࣲ ۝١٠", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "قل -أيها النبي- لعبادي المؤمنين بالله ورسوله: اتقوا ربكم بطاعته واجتناب معصيته. للذين أحسنوا في هذه الدينا بعبادة ربهم وطاعته حسنة في الآخرة، وهي الجنة، وحسنة في الدنيا من صحة ورزق ونصر وغير ذلك. وأرض الله واسعة، فهاجِروا فيها إلى حيث تعبدون ربكم، وتتمكنون من إقامة دينكم. إنما يُعطَى الصابرون ثوابهم في الآخرة بغير حدّ ولا عدّ ولا مقدار، وهذا تعظيم لجزاء الصابرين وثوابهم.", "isBasmala": false, "translation_en": "Say, \"O My devotees who have believed, keep your duty to your Lord. For those who do good in this world, is goodness. And God's earth is vast. The steadfast will be paid their wages in full, without reckoning.\"", "translation_id": "Katakanlah: \"Hai hamba-hamba-Ku yang beriman. bertakwalah kepada Tuhanmu\". Orang-orang yang berbuat baik di dunia ini memperoleh kebaikan. Dan bumi Allah itu adalah luas. Sesungguhnya hanya orang-orang yang bersabarlah Yang dicukupkan pahala mereka tanpa batas.", "manzil": 6, "manzil_display": ""}], "460": [{"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 11, "text": "قُلۡ إِنِّیۤ أُمِرۡتُ أَنۡ أَعۡبُدَ ٱللَّهَ مُخۡلِصࣰا لَّهُ ٱلدِّینَ ۝١١", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "قل -أيها الرسول- للناس: إن الله أمرني ومن تبعني بإخلاص العبادة له وحده دون سواه، وأمرني بأن أكون أول من أسلم من أمتي، فخضع له بالتوحيد، وأخلص له العبادة، وبرئ مِن كل ما دونه من الآلهة.", "isBasmala": false, "translation_en": "Say, \"I was commanded to serve God, devoting my religion exclusively to Him.", "translation_id": "Katakanlah: \"Sesungguhnya aku diperintahkan supaya menyembah Allah dengan memurnikan ketaatan kepada-Nya dalam (menjalankan) agama.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 12, "text": "وَأُمِرۡتُ لِأَنۡ أَكُونَ أَوَّلَ ٱلۡمُسۡلِمِینَ ۝١٢", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "قل -أيها الرسول- للناس: إن الله أمرني ومن تبعني بإخلاص العبادة له وحده دون سواه، وأمرني بأن أكون أول من أسلم من أمتي، فخضع له بالتوحيد، وأخلص له العبادة، وبرئ مِن كل ما دونه من الآلهة.", "isBasmala": false, "translation_en": "And I was commanded to be the first of those who submit.\"", "translation_id": "Dan aku diperintahkan supaya menjadi orang yang pertama-tama berserah diri\".", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 13, "text": "قُلۡ إِنِّیۤ أَخَافُ إِنۡ عَصَیۡتُ رَبِّی عَذَابَ یَوۡمٍ عَظِیمࣲ ۝١٣", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "قل -أيها الرسول- للناس: إني أخاف إن عصيت ربي فيما أمرني به من عبادته والإخلاص في طاعته عذاب يوم القيامة، ذلك اليوم الذي يعظم هوله.", "isBasmala": false, "translation_en": "Say, \"I fear, if I disobeyed my Lord, the punishment of a horrendous Day.\"", "translation_id": "Katakanlah: \"Sesungguhnya aku takut akan siksaan hari yang besar jika aku durhaka kepada Tuhanku\".", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 14, "text": "قُلِ ٱللَّهَ أَعۡبُدُ مُخۡلِصࣰا لَّهُۥ دِینِی ۝١٤", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "قل -أيها الرسول-: إني أعبد الله وحده لا شريك له مخلصًا له عبادتي وطاعتي، فاعبدوا أنتم- أيها المشركون- ما شئتم من دون الله من الأوثان والأصنام وغير ذلك من مخلوقاته، فلا يضرني ذلك شيئًا. وهذا تهديد ووعيد لمن عبد غير الله، وأشرك معه غيره. قل -أيها الرسول-: إن الخاسرين- حقًا- هم الذين خسروا أنفسهم وأهليهم يوم القيامة، وذلك بإغوائهم في الدنيا وإضلالهم عن الإيمان. ألا إن خسران هؤلاء المشركين أنفسهم وأهليهم يوم القيامة هو الخسران البيِّن الواضح.", "isBasmala": false, "translation_en": "Say, \"It is God I worship, sincere in my faith in Him.\"", "translation_id": "Katakanlah: \"Hanya Allah saja Yang aku sembah dengan memurnikan ketaatan kepada-Nya dalam (menjalankan) agamaku\".", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 15, "text": "فَٱعۡبُدُوا۟ مَا شِئۡتُم مِّن دُونِهِۦۗ قُلۡ إِنَّ ٱلۡخَـٰسِرِینَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ وَأَهۡلِیهِمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۗ أَلَا ذَ ٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِینُ ۝١٥", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "قل -أيها الرسول-: إني أعبد الله وحده لا شريك له مخلصًا له عبادتي وطاعتي، فاعبدوا أنتم- أيها المشركون- ما شئتم من دون الله من الأوثان والأصنام وغير ذلك من مخلوقاته، فلا يضرني ذلك شيئًا. وهذا تهديد ووعيد لمن عبد غير الله، وأشرك معه غيره. قل -أيها الرسول-: إن الخاسرين- حقًا- هم الذين خسروا أنفسهم وأهليهم يوم القيامة، وذلك بإغوائهم في الدنيا وإضلالهم عن الإيمان. ألا إن خسران هؤلاء المشركين أنفسهم وأهليهم يوم القيامة هو الخسران البيِّن الواضح.", "isBasmala": false, "translation_en": "\"But you can worship whatever you wish besides Him.\" Say, \"The losers are those who lose their souls and their people on the Day of Resurrection.\" That is indeed the obvious loss.", "translation_id": "Maka sembahlah olehmu (hai orang-orang musyrik) apa yang kamu kehendaki selain Dia. Katakanlah: \"Sesungguhnya orang-orang yang rugi ialah orang-orang yang merugikan diri mereka sendiri dan keluarganya pada hari kiamat\". Ingatlah yang demikian itu adalah kerugian yang nyata.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 16, "text": "لَهُم مِّن فَوۡقِهِمۡ ظُلَلࣱ مِّنَ ٱلنَّارِ وَمِن تَحۡتِهِمۡ ظُلَلࣱۚ ذَ ٰلِكَ یُخَوِّفُ ٱللَّهُ بِهِۦ عِبَادَهُۥۚ یَـٰعِبَادِ فَٱتَّقُونِ ۝١٦", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "أولئك الخاسرون لهم يوم القيامة في جهنم مِن فوقهم قطع عذاب من النار كهيئة الظُّلل المبنية، ومن تحتهم كذلك. ذلك العذاب الموصوف يخوِّف الله به عباده؛ ليحْذَروه. يا عباد فاتقوني بامتثال أوامري واجتناب معاصيَّ.", "isBasmala": false, "translation_en": "They will have layers of Fire above them, and layers beneath them. That is how God strikes fear into His servants-\"O My servants! Beware of Me!\"", "translation_id": "Bagi mereka lapisan-lapisan dari api di atas mereka dan di bawah merekapun lapisan-lapisan (dari api). Demikianlah Allah mempertakuti hamba-hamba-Nya dengan azab itu. Maka bertakwalah kepada-Ku hai hamba-hamba-Ku.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 17, "text": "وَٱلَّذِینَ ٱجۡتَنَبُوا۟ ٱلطَّـٰغُوتَ أَن یَعۡبُدُوهَا وَأَنَابُوۤا۟ إِلَى ٱللَّهِ لَهُمُ ٱلۡبُشۡرَىٰۚ فَبَشِّرۡ عِبَادِ ۝١٧", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "والذين اجتنبوا طاعة الشيطان وعبادة غير الله، وتابوا إلى الله بعبادته وإخلاص الدين له، لهم البشرى في الحياة الدنيا بالثناء الحسن والتوفيق من الله، وفي الآخرة رضوان الله والنعيم الدائم في الجنة. فبشِّر -أيها النبي- عبادي الذين يستمعون القول فيتبعون أرشده. وأحسن الكلام وأرشده كلام الله ثم كلام رسوله. أولئك هم الذين وفقهم الله للرشاد والسداد، وهداهم لأحسن الأخلاق والأعمال، وأولئك هم أصحاب العقول السليمة.", "isBasmala": false, "translation_en": "As for those who avoid the worship of idols, and devote themselves to God-theirs is the good news. So give good news to My servants.", "translation_id": "Dan orang-orang yang menjauhi thaghut (yaitu) tidak menyembahnya dan kembali kepada Allah, bagi mereka berita gembira; sebab itu sampaikanlah berita itu kepada hamba-hamba-Ku,", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 18, "text": "ٱلَّذِینَ یَسۡتَمِعُونَ ٱلۡقَوۡلَ فَیَتَّبِعُونَ أَحۡسَنَهُۥۤۚ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ هَدَىٰهُمُ ٱللَّهُۖ وَأُو۟لَـٰۤىِٕكَ هُمۡ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ ۝١٨", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "والذين اجتنبوا طاعة الشيطان وعبادة غير الله، وتابوا إلى الله بعبادته وإخلاص الدين له، لهم البشرى في الحياة الدنيا بالثناء الحسن والتوفيق من الله، وفي الآخرة رضوان الله والنعيم الدائم في الجنة. فبشِّر -أيها النبي- عبادي الذين يستمعون القول فيتبعون أرشده. وأحسن الكلام وأرشده كلام الله ثم كلام رسوله. أولئك هم الذين وفقهم الله للرشاد والسداد، وهداهم لأحسن الأخلاق والأعمال، وأولئك هم أصحاب العقول السليمة.", "isBasmala": false, "translation_en": "Those who listen to the Word, and follow the best of it. These are they whom God has guided. These are they who possess intellect.", "translation_id": "yang mendengarkan perkataan lalu mengikuti apa yang paling baik di antaranya. Mereka itulah orang-orang yang telah diberi Allah petunjuk dan mereka itulah orang-orang yang mempunyai akal.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 19, "text": "أَفَمَنۡ حَقَّ عَلَیۡهِ كَلِمَةُ ٱلۡعَذَابِ أَفَأَنتَ تُنقِذُ مَن فِی ٱلنَّارِ ۝١٩", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "أفمن وجبت عليه كلمة العذاب؛ باستمراره على غيِّه وعناده، فإنه لا حيلة لك -أيها الرسول- في هدايته، أفتقدر أن تنقذ مَن في النار؟ لست بقادر على ذلك.", "isBasmala": false, "translation_en": "What about someone who has deserved the sentence of punishment? Is it you who can save those in the Fire?", "translation_id": "Apakah (kamu hendak merubah nasib) orang-orang yang telah pasti ketentuan azab atasnya? Apakah kamu akan menyelamatkan orang yang berada dalam api neraka?", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 20, "text": "لَـٰكِنِ ٱلَّذِینَ ٱتَّقَوۡا۟ رَبَّهُمۡ لَهُمۡ غُرَفࣱ مِّن فَوۡقِهَا غُرَفࣱ مَّبۡنِیَّةࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ وَعۡدَ ٱللَّهِ لَا یُخۡلِفُ ٱللَّهُ ٱلۡمِیعَادَ ۝٢٠", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "لكن الذين اتقوا ربهم- بطاعته وإخلاص عبادته- لهم في الجنة غرف مبنية بعضها فوق بعض، تجري مِن تحت أشجارها الأنهار، وعدها الله عباده المتقين وعدًا متحققًا، لا يخلف الله الميعاد.", "isBasmala": false, "translation_en": "But those who fear their Lord will have mansions upon mansions, built high, with streams flowing beneath them. The promise of God; and God never breaks a promise.", "translation_id": "Tetapi orang-orang yang bertakwa kepada Tuhannya mereka mendapat tempat-tempat yang tinggi, di atasnya dibangun pula tempat-tempat yang tinggi yang di bawahnya mengalir sungai-sungai. Allah telah berjanji dengan sebenar-benarnya. Allah tidak akan memungkiri janji-Nya.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 21, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَسَلَكَهُۥ یَنَـٰبِیعَ فِی ٱلۡأَرۡضِ ثُمَّ یُخۡرِجُ بِهِۦ زَرۡعࣰا مُّخۡتَلِفًا أَلۡوَ ٰنُهُۥ ثُمَّ یَهِیجُ فَتَرَىٰهُ مُصۡفَرࣰّا ثُمَّ یَجۡعَلُهُۥ حُطَـٰمًاۚ إِنَّ فِی ذَ ٰلِكَ لَذِكۡرَىٰ لِأُو۟لِی ٱلۡأَلۡبَـٰبِ ۝٢١", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "ألم تر -أيها الرسول- أن الله أنزل من السحاب مطرًا فأدخله في الأرض، وجعله عيونًا نابعة ومياهًا جارية، ثم يُخْرج بهذا الماء زرعًا مختلفًا ألوانه وأنواعه، ثم ييبس بعد خضرته ونضارته، فتراه مصفرًا لونه، ثم يجعله حطامًا متكسِّرًا متفتتًا؟ إن في فِعْل الله ذلك لَذكرى وموعظة لأصحاب العقول السليمة.", "isBasmala": false, "translation_en": "Have you not considered how God sends down water from the sky, then He makes it flow into underground wells, then He produces with it plants of various colors, then they wither and you see them yellowing, then He turns them into debris? Surely in this is a reminder for those with understanding.", "translation_id": "Apakah kamu tidak memperhatikan, bahwa sesungguhnya Allah menurunkan air dari langit, maka diaturnya menjadi sumber-sumber air di bumi kemudian ditumbuhkan-Nya dengan air itu tanam-tanaman yang bermacam-macam warnanya, lalu menjadi kering lalu kamu melihatnya kekuning-kuningan, kemudian dijadikan-Nya hancur berderai-derai. Sesungguhnya pada yang demikian itu benar-benar terdapat pelajaran bagi orang-orang yang mempunyai akal.", "manzil": 6, "manzil_display": ""}], "461": [{"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 22, "text": "أَفَمَن شَرَحَ ٱللَّهُ صَدۡرَهُۥ لِلۡإِسۡلَـٰمِ فَهُوَ عَلَىٰ نُورࣲ مِّن رَّبِّهِۦۚ فَوَیۡلࣱ لِّلۡقَـٰسِیَةِ قُلُوبُهُم مِّن ذِكۡرِ ٱللَّهِۚ أُو۟لَـٰۤىِٕكَ فِی ضَلَـٰلࣲ مُّبِینٍ ۝٢٢", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "أفمن وسَّع الله صدره، فسعد بقبول الإسلام والانقياد له والإيمان به، فهو على بصيرة من أمره وهدى من ربه، كمن ليس كذلك؟ لا يستوون. فويل وهلاك للذين قَسَتْ قلوبهم، وأعرضت عن ذكر الله، أولئك في ضلال بيِّن عن الحق.", "isBasmala": false, "translation_en": "What about someone whose heart God has opened to Islam, so that he follows a light from His Lord? Woe to those whose hearts are hardened against the mention of God. Those are in manifest error.", "translation_id": "Maka apakah orang-orang yang dibukakan Allah hatinya untuk (menerima) agama Islam lalu ia mendapat cahaya dari Tuhannya (sama dengan orang yang membatu hatinya)? Maka kecelakaan yang besarlah bagi mereka yang telah membatu hatinya untuk mengingat Allah. Mereka itu dalam kesesatan yang nyata.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 23, "text": "ٱللَّهُ نَزَّلَ أَحۡسَنَ ٱلۡحَدِیثِ كِتَـٰبࣰا مُّتَشَـٰبِهࣰا مَّثَانِیَ تَقۡشَعِرُّ مِنۡهُ جُلُودُ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُمۡ ثُمَّ تَلِینُ جُلُودُهُمۡ وَقُلُوبُهُمۡ إِلَىٰ ذِكۡرِ ٱللَّهِۚ ذَ ٰلِكَ هُدَى ٱللَّهِ یَهۡدِی بِهِۦ مَن یَشَاۤءُۚ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٍ ۝٢٣", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "الله تعالى هو الذي نزل أحسن الحديث، وهو القرآن العظيم، متشابهًا في حسنه وإحكامه وعدم اختلافه، تثنى فيه القصص والأحكام، والحجج والبينات، تقشعر من سماعه، وتضطرب جلود الذين يخافون ربهم؛ تأثرًا بما فيه مِن ترهيب ووعيد، ثم تلين جلودهم وقلوبهم؛ استبشارًا بما فيه من وعد وترغيب، ذلك التأثر بالقرآن هداية من الله لعباده. والله يهدي بالقرآن من يشاء مِن عباده. ومن يضلله الله عن الإيمان بهذا القرآن؛ لكفره وعناده، فما له مِن هاد يهديه ويوفقه.", "isBasmala": false, "translation_en": "God has sent down the best of narrations: a Scripture consistent and paired. The skins of those who reverence their Lord shiver from it, then their skins and their hearts soften up to the remembrance of God. Such is God's guidance; He guides with it whomever He wills. But whomever God leaves astray, for him there is no guide.", "translation_id": "Allah telah menurunkan perkataan yang paling baik (yaitu) Al Quran yang serupa (mutu ayat-ayatnya) lagi berulang-ulang, gemetar karenanya kulit orang-orang yang takut kepada Tuhannya, kemudian menjadi tenang kulit dan hati mereka di waktu mengingat Allah. Itulah petunjuk Allah, dengan kitab itu Dia menunjuki siapa yang dikehendaki-Nya. Dan barangsiapa yang disesatkan Allah, niscaya tak ada baginya seorang pemimpinpun.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 24, "text": "أَفَمَن یَتَّقِی بِوَجۡهِهِۦ سُوۤءَ ٱلۡعَذَابِ یَوۡمَ ٱلۡقِیَـٰمَةِۚ وَقِیلَ لِلظَّـٰلِمِینَ ذُوقُوا۟ مَا كُنتُمۡ تَكۡسِبُونَ ۝٢٤", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "أفمن يُلْقى في النار مغلولا- فلا يتهيأ له أن يتقي النار إلا بوجهه؛ لكفره وضلاله- خير أم من ينعم في الجنة؛ لأن الله هداه؟ وقيل يومئذ للظالمين: ذوقوا وبال ما كنتم في الدنيا تكسبون من معاصي الله.", "isBasmala": false, "translation_en": "What about someone who covers his face against the terrible misery of the Day of Resurrection? To the evildoers it will be said, \"Taste what you used to earn.\"", "translation_id": "Maka apakah orang-orang yang menoleh dengan mukanya menghindari azab yang buruk pada hari kiamat (sama dengan orang mukmin yang tidak kena azab)? Dan dikatakan kepada orang-orang yang zalim: \"Rasakanlah olehmu balasan apa yang telah kamu kerjakan\".", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 25, "text": "كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَیۡثُ لَا یَشۡعُرُونَ ۝٢٥", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "كذَّب الذين مِن قبل قومك -أيها الرسول- رسلهم، فجاءهم العذاب من حيث لا يشعرون بمجيئه، فأذاق الله الأمم المكذبة العذاب والهوان في الدنيا، وأعد لهم عذابًا أشد وأشق في الآخرة، لو كان هؤلاء المشركون يعلمون أن ما حلَّ بهم؛ بسبب كفرهم وتكذيبهم لاتَّعظوا.", "isBasmala": false, "translation_en": "Those before them also denied the truth, so the penalty came upon them from where they did not perceive.", "translation_id": "Orang-orang yang sebelum mereka telah mendustakan (rasul-rasul), maka datanglah kepada mereka azab dari arah yang tidak mereka sangka.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 26, "text": "فَأَذَاقَهُمُ ٱللَّهُ ٱلۡخِزۡیَ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَكۡبَرُۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ ۝٢٦", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "كذَّب الذين مِن قبل قومك -أيها الرسول- رسلهم، فجاءهم العذاب من حيث لا يشعرون بمجيئه، فأذاق الله الأمم المكذبة العذاب والهوان في الدنيا، وأعد لهم عذابًا أشد وأشق في الآخرة، لو كان هؤلاء المشركون يعلمون أن ما حلَّ بهم؛ بسبب كفرهم وتكذيبهم لاتَّعظوا.", "isBasmala": false, "translation_en": "God made them taste disgrace in the present life, but the punishment of the Hereafter is worse, if they only knew.", "translation_id": "Maka Allah merasakan kepada mereka kehinaan pada kehidupan dunia. Dan sesungguhnya azab pada hari akhirat lebih besar kalau mereka mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 27, "text": "وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِی هَـٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲ لَّعَلَّهُمۡ یَتَذَكَّرُونَ ۝٢٧", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "ولقد ضربنا لهؤلاء المشركين بالله في هذا القرآن من كل مثل من أمثال القرون الخالية تخويفًا وتحذيرًا؛ ليتذكروا فينزجروا عما هم عليه مقيمون من الكفر بالله. وجعلنا هذا القرآن عربيًا واضح الألفاظ سهل المعاني، لا لَبْس فيه ولا انحراف؛ لعلهم يتقون الله بامتثال أوامره واجتناب نواهيه.", "isBasmala": false, "translation_en": "We have cited in this Quran for mankind every ideal, that they may take heed.", "translation_id": "Sesungguhnya telah Kami buatkan bagi manusia dalam Al Quran ini setiap macam perumpamaan supaya mereka dapat pelajaran.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 28, "text": "قُرۡءَانًا عَرَبِیًّا غَیۡرَ ذِی عِوَجࣲ لَّعَلَّهُمۡ یَتَّقُونَ ۝٢٨", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "ولقد ضربنا لهؤلاء المشركين بالله في هذا القرآن من كل مثل من أمثال القرون الخالية تخويفًا وتحذيرًا؛ ليتذكروا فينزجروا عما هم عليه مقيمون من الكفر بالله. وجعلنا هذا القرآن عربيًا واضح الألفاظ سهل المعاني، لا لَبْس فيه ولا انحراف؛ لعلهم يتقون الله بامتثال أوامره واجتناب نواهيه.", "isBasmala": false, "translation_en": "An Arabic Quran, without any defect, so they may become righteous.", "translation_id": "(Ialah) Al Quran dalam bahasa Arab yang tidak ada kebengkokan (di dalamnya) supaya mereka bertakwa.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 29, "text": "ضَرَبَ ٱللَّهُ مَثَلࣰا رَّجُلࣰا فِیهِ شُرَكَاۤءُ مُتَشَـٰكِسُونَ وَرَجُلࣰا سَلَمࣰا لِّرَجُلٍ هَلۡ یَسۡتَوِیَانِ مَثَلًاۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ ۝٢٩", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "ضرب الله مثلا عبدًا مملوكًا لشركاء متنازعين، فهو حيران في إرضائهم، وعبدًا خالصًا لمالك واحد يعرف مراده وما يرضيه، هل يستويان مثلا؟ لا يستويان، كذلك المشرك هو في حَيْرة وشك، والمؤمن في راحة واطمئنان. فالثناء الكامل التام لله وحده، بل المشركون لا يعلمون الحق فيتبعونه.", "isBasmala": false, "translation_en": "God cites the example of a man shared by partners at odds, and a man belonging exclusively to one man. Are they equal in status? Praise be to God, but most of them do not know.", "translation_id": "Allah membuat perumpamaan (yaitu) seorang laki-laki (budak) yang dimiliki oleh beberapa orang yang berserikat yang dalam perselisihan dan seorang budak yang menjadi milik penuh dari seorang laki-laki (saja); Adakah kedua budak itu sama halnya? Segala puji bagi Allah tetapi kebanyakan mereka tidak mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 30, "text": "إِنَّكَ مَیِّتࣱ وَإِنَّهُم مَّیِّتُونَ ۝٣٠", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "إنك -أيها الرسول- ميت وإنهم ميتون، ثم إنكم جميعًا- أيها الناس- يوم القيامة عند ربكم تتنازعون، فيحكم بينكم بالعدل والإنصاف.", "isBasmala": false, "translation_en": "You will die, and they will die.", "translation_id": "Sesungguhnya kamu akan mati dan sesungguhnya mereka akan mati (pula).", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 31, "text": "ثُمَّ إِنَّكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ عِندَ رَبِّكُمۡ تَخۡتَصِمُونَ ۝٣١", "juz": 23, "hizb": "(*¾ ح 46*)", "tafsir": "إنك -أيها الرسول- ميت وإنهم ميتون، ثم إنكم جميعًا- أيها الناس- يوم القيامة عند ربكم تتنازعون، فيحكم بينكم بالعدل والإنصاف.", "isBasmala": false, "translation_en": "Then, on the Day of Resurrection, you will be quarrelling before your Lord.", "translation_id": "Kemudian sesungguhnya kamu pada hari kiamat akan berbantah-bantah di hadapan Tuhanmu.", "manzil": 6, "manzil_display": ""}], "462": [{"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 32, "text": "۞ فَمَنۡ أَظۡلَمُ مِمَّن كَذَبَ عَلَى ٱللَّهِ وَكَذَّبَ بِٱلصِّدۡقِ إِذۡ جَاۤءَهُۥۤۚ أَلَیۡسَ فِی جَهَنَّمَ مَثۡوࣰى لِّلۡكَـٰفِرِینَ ۝٣٢", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "لا أحد أظلم ممن افترى على الله الكذب: بأن نسب إليه ما لا يليق به كالشريك والولد، أو قال: أوحي إليَّ، ولم يوحَ إليه شيء، ولا أحد أظلم ممن كذَّب بالحق الذي نزل على محمد صلى الله عليه وسلم. أليس في النار مأوى ومسكن لمن كفر بالله، ولم يصدق محمدًا صلى الله عليه وسلم ولم يعمل بما جاء به؟ بَلَى.", "isBasmala": false, "translation_en": "Who is more evil than he who lies about God, and denies the truth when it has come to him? Is there not in Hell room for the ungrateful?", "translation_id": "Maka siapakah yang lebih zalim daripada orang yang membuat-buat dusta terhadap Allah dan mendustakan kebenaran ketika datang kepadanya? Bukankah di neraka Jahannam tersedia tempat tinggal bagi orang-orang yang kafir?", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 33, "text": "وَٱلَّذِی جَاۤءَ بِٱلصِّدۡقِ وَصَدَّقَ بِهِۦۤ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُتَّقُونَ ۝٣٣", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "والذي جاء بالصدق في قوله وعمله من الأنبياء وأتباعهم، وصدَّق به إيمانًا وعملا أولئك هم الذين جمعوا خصال التقوى، وفي مقدمة هؤلاء خاتم الأنبياء والمرسلين محمد صلى الله عليه وسلم والمؤمنون به، العاملون بشريعته من الصحابة، رضي الله عنهم، فمَن بعدهم إلى يوم الدين.", "isBasmala": false, "translation_en": "But he who promotes the truth, and testifies to it-these are the righteous.", "translation_id": "Dan orang yang membawa kebenaran (Muhammad) dan membenarkannya, mereka itulah orang-orang yang bertakwa.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 34, "text": "لَهُم مَّا یَشَاۤءُونَ عِندَ رَبِّهِمۡۚ ذَ ٰلِكَ جَزَاۤءُ ٱلۡمُحۡسِنِینَ ۝٣٤", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "لهم ما يشاؤون عند ربهم من أصناف اللذات المشتهيات؛ ذلك جزاء مَن أطاع ربه حق الطاعة، وعبده حق العبادة.", "isBasmala": false, "translation_en": "They will have whatever they please with their Lord. Such is the reward for the virtuous.", "translation_id": "Mereka memperoleh apa yang mereka kehendaki pada sisi Tuhan mereka. Demikianlah balasan orang-orang yang berbuat baik,", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 35, "text": "لِیُكَفِّرَ ٱللَّهُ عَنۡهُمۡ أَسۡوَأَ ٱلَّذِی عَمِلُوا۟ وَیَجۡزِیَهُمۡ أَجۡرَهُم بِأَحۡسَنِ ٱلَّذِی كَانُوا۟ یَعۡمَلُونَ ۝٣٥", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "ليكفِّر الله عنهم أسوأ الذي عملوا في الدنيا من الأعمال؛ بسبب ما كان منهم مِن توبة وإنابة مما اجترحوا من السيئات فيها، ويثيبهم الله على طاعتهم في الدنيا بأحسن ما كانوا يعملون، وهو الجنة.", "isBasmala": false, "translation_en": "God will acquit them of the worst of their deeds, and will reward them according to the best of what they used to do.", "translation_id": "agar Allah akan menutupi (mengampuni) bagi mereka perbuatan yang paling buruk yang mereka kerjakan dan membalas mereka dengan upah yang lebih baik dari apa yang telah mereka kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 36, "text": "أَلَیۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَیُخَوِّفُونَكَ بِٱلَّذِینَ مِن دُونِهِۦۚ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادࣲ ۝٣٦", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "أليس الله بكاف عبده محمدًا وعيد المشركين وكيدهم من أن ينالوه بسوء؟ بلى إنه سيكفيه في أمر دينه ودنياه، ويدفع عنه مَن أراده بسوء، ويخوِّفونك -أيها الرسول- بآلهتهم التي زعموا أنها ستؤذيك. ومن يخذله الله فيضله عن طريق الحق، فما له مِن هاد يهديه إليه.", "isBasmala": false, "translation_en": "Is God not enough for His servant? And they frighten you with those besides Him. Whomever God sends astray, for him there is no guide.", "translation_id": "Bukankah Allah cukup untuk melindungi hamba-hamba-Nya. Dan mereka mempertakuti kamu dengan (sembahan-sembahan) yang selain Allah? Dan siapa yang disesatkan Allah maka tidak seorangpun pemberi petunjuk baginya.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 37, "text": "وَمَن یَهۡدِ ٱللَّهُ فَمَا لَهُۥ مِن مُّضِلٍّۗ أَلَیۡسَ ٱللَّهُ بِعَزِیزࣲ ذِی ٱنتِقَامࣲ ۝٣٧", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "ومن يوفقه الله للإيمان به والعمل بكتابه واتباع رسوله فما له مِن مضل عن الحق الذي هو عليه. أليس الله بعزيز في انتقامه مِن كفرة خلقه، وممن عصاه؟", "isBasmala": false, "translation_en": "And whomever God guides, for him there is no misleader. Is God not Powerful and Vengeful?", "translation_id": "Dan barangsiapa yang diberi petunjuk oleh Allah, maka tidak seorangpun yang dapat menyesatkannya. Bukankah Allah Maha Perkasa lagi mempunyai (kekuasaan untuk) mengazab?", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 38, "text": "وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ لَیَقُولُنَّ ٱللَّهُۚ قُلۡ أَفَرَءَیۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ إِنۡ أَرَادَنِیَ ٱللَّهُ بِضُرٍّ هَلۡ هُنَّ كَـٰشِفَـٰتُ ضُرِّهِۦۤ أَوۡ أَرَادَنِی بِرَحۡمَةٍ هَلۡ هُنَّ مُمۡسِكَـٰتُ رَحۡمَتِهِۦۚ قُلۡ حَسۡبِیَ ٱللَّهُۖ عَلَیۡهِ یَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ ۝٣٨", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "ولئن سألت -أيها الرسول- هؤلاء المشركين الذين يعبدون غير الله: مَن خلق هذه السموات والأرض؟ ليقولُنَّ: خلقهنَّ الله، فهم يُقِرُّون بالخالق. قل لهم: هل تستطيع هذه الآلهة التي تشركونها مع الله أن تُبْعِدَ عني أذى قدَّره الله عليَّ، أو تزيلَ مكروهًا لَحِق بي؟ وهل تستطيع أن تمنع نفعَا يسَّره الله لي، أو تحبس رحمة الله عني؟ إنهم سيقولون: لا تستطيع ذلك. قل لهم: حسبي الله وكافِيَّ، عليه يعتمد المعتمدون في جلب مصالحهم ودفع مضارهم، فالذي بيده وحده الكفاية هو حسبي، وسيكفيني كل ما أهمني.", "isBasmala": false, "translation_en": "And if you asked them, \"Who created the heavens and the earth?\" they would say, \"God.\" Say, \"Have you seen those you pray to instead of God? If God willed any harm for me, can they lift His harm? And if He willed a blessing for me, can they hold back His mercy?\" Say, \"God suffices for me. On Him the reliant rely.\"", "translation_id": "Dan sungguh jika kamu bertanya kepada mereka: \"Siapakah yang menciptakan langit dan bumi?\", niscaya mereka menjawab: \"Allah\". Katakanlah: \"Maka terangkanlah kepadaku tentang apa yang kamu seru selain Allah, jika Allah hendak mendatangkan kemudharatan kepadaku, apakah berhala-berhalamu itu dapat menghilangkan kemudharatan itu, atau jika Allah hendak memberi rahmat kepadaku, apakah mereka dapat menahan rahmat-Nya?. Katakanlah: \"Cukuplah Allah bagiku\". Kepada-Nya-lah bertawakkal orang-orang yang berserah diri.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 39, "text": "قُلۡ یَـٰقَوۡمِ ٱعۡمَلُوا۟ عَلَىٰ مَكَانَتِكُمۡ إِنِّی عَـٰمِلࣱۖ فَسَوۡفَ تَعۡلَمُونَ ۝٣٩", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "قل -أيها الرسول- لقومك المعاندين: اعملوا على حالتكم التي رضيتموها لأنفسكم، حيث عبدتم مَن لا يستحق العبادة، وليس له من الأمر شيء، إني عامل على ما أُمرت به من التوجه لله وحده في أقوالي وأفعالي، فسوف تعلمون من يأتيه عذاب يهينه في الحياة الدنيا، ويحل عليه في الآخرة عذاب دائم؟ لا يحول عنه ولا يزول.", "isBasmala": false, "translation_en": "Say: \"O my people, work according to your ability; and so will I. Then you will know.", "translation_id": "Katakanlah: \"Hai kaumku, bekerjalah sesuai dengan keadaanmu, sesungguhnya aku akan bekerja (pula), maka kelak kamu akan mengetahui,", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 40, "text": "مَن یَأۡتِیهِ عَذَابࣱ یُخۡزِیهِ وَیَحِلُّ عَلَیۡهِ عَذَابࣱ مُّقِیمٌ ۝٤٠", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "قل -أيها الرسول- لقومك المعاندين: اعملوا على حالتكم التي رضيتموها لأنفسكم، حيث عبدتم مَن لا يستحق العبادة، وليس له من الأمر شيء، إني عامل على ما أُمرت به من التوجه لله وحده في أقوالي وأفعالي، فسوف تعلمون من يأتيه عذاب يهينه في الحياة الدنيا، ويحل عليه في الآخرة عذاب دائم؟ لا يحول عنه ولا يزول.", "isBasmala": false, "translation_en": "Who will receive a humiliating punishment, and on whom will fall a lasting torment.\"", "translation_id": "siapa yang akan mendapat siksa yang menghinakannya dan lagi ditimpa oleh azab yang kekal\".", "manzil": 6, "manzil_display": ""}], "463": [{"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 41, "text": "إِنَّاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡكِتَـٰبَ لِلنَّاسِ بِٱلۡحَقِّۖ فَمَنِ ٱهۡتَدَىٰ فَلِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا یَضِلُّ عَلَیۡهَاۖ وَمَاۤ أَنتَ عَلَیۡهِم بِوَكِیلٍ ۝٤١", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "إنا أنزلنا عليك -أيها الرسول- القرآن بالحق هداية للعالمين، إلى طريق الرشاد، فمن اهتدى بنوره، وعمل بما فيه، واستقام على منهجه، فنفعُ ذلك يعود على نفسه، ومَن ضلَّ بعد ما تبين له الهدى، فإنما يعود ضرره على نفسه، ولن يضرَّ الله شيئا، وما أنت -أيها الرسول- عليهم بوكيل تحفظ أعمالهم، وتحاسبهم عليها، وتجبرهم على ما تشاء، ما عليك إلا البلاغ.", "isBasmala": false, "translation_en": "We sent down upon you the Book for mankind in truth. He who follows guidance does so for the good of his soul. And he who strays in error does so to its detriment. You are not their overseer.", "translation_id": "Sesungguhnya Kami menurunkan kepadamu Al Kitab (Al Quran) untuk manusia dengan membawa kebenaran; siapa yang mendapat petunjuk maka (petunjuk itu) untuk dirinya sendiri, dan siapa yang sesat maka sesungguhnya dia semata-mata sesat buat (kerugian) dirinya sendiri, dan kamu sekali-kali bukanlah orang yang bertanggung jawab terhadap mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 42, "text": "ٱللَّهُ یَتَوَفَّى ٱلۡأَنفُسَ حِینَ مَوۡتِهَا وَٱلَّتِی لَمۡ تَمُتۡ فِی مَنَامِهَاۖ فَیُمۡسِكُ ٱلَّتِی قَضَىٰ عَلَیۡهَا ٱلۡمَوۡتَ وَیُرۡسِلُ ٱلۡأُخۡرَىٰۤ إِلَىٰۤ أَجَلࣲ مُّسَمًّىۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَفَكَّرُونَ ۝٤٢", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "الله- سبحانه وتعالى- هو الذي يقبض الأنفس حين موتها، وهذه الوفاة الكبرى، وفاة الموت بانقضاء الأجل، ويقبض التي لم تمت في منامها، وهي الموتة الصغرى، فيحبس من هاتين النفسين النفس التي قضى عليها الموت، وهي نفس مَن مات، ويرسل النفس الأخرى إلى استكمال أجلها ورزقها، وذلك بإعادتها إلى جسم صاحبها، إن في قبض الله نفس الميت والنائم وإرساله نفس النائم، وحبسه نفس الميت لَدلائل واضحة على قدرة الله لمن تفكر وتدبر.", "isBasmala": false, "translation_en": "God takes the souls at the time of their death, and those that have not died during their sleep. He retains those for which He has decreed death, and He releases the others until a predetermined time. In that are signs for people who reflect.", "translation_id": "Allah memegang jiwa (orang) ketika matinya dan (memegang) jiwa (orang) yang belum mati di waktu tidurnya; maka Dia tahanlah jiwa (orang) yang telah Dia tetapkan kematiannya dan Dia melepaskan jiwa yang lain sampai waktu yang ditetapkan. Sesungguhnya pada yang demikian itu terdapat tanda-tanda kekuasaan Allah bagi kaum yang berfikir.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 43, "text": "أَمِ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ شُفَعَاۤءَۚ قُلۡ أَوَ لَوۡ كَانُوا۟ لَا یَمۡلِكُونَ شَیۡـࣰٔا وَلَا یَعۡقِلُونَ ۝٤٣", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "أم اتخذ هؤلاء المشركون بالله من دونه آلهتهم التي يعبدونها شفعاء، تشفع لهم عند الله في حاجاتهم؟ قل -أيها الرسول- لهم: أتتخذونها شفعاء كما تزعمون، ولو كانت الآلهة لا تملك شيئا، ولا تعقل عبادتكم لها؟", "isBasmala": false, "translation_en": "Or have they chosen intercessors other than God? Say, \"Even though they have no power over anything, and are devoid of reason?\"", "translation_id": "Bahkan mereka mengambil pemberi syafa'at selain Allah. Katakanlah: \"Dan apakah (kamu mengambilnya juga) meskipun mereka tidak memiliki sesuatupun dan tidak berakal?\"", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 44, "text": "قُل لِّلَّهِ ٱلشَّفَـٰعَةُ جَمِیعࣰاۖ لَّهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ ثُمَّ إِلَیۡهِ تُرۡجَعُونَ ۝٤٤", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: لله الشفاعة جميعًا، له ملك السموات والأرض وما فيهما، فالأمر كله لله وحده، ولا يشفع أحد عنده إلا بإذنه، فهو الذي يملك السموات والأرض ويتصرف فيهما، فالواجب أن تُطلب الشفاعة ممن يملكها، وأن تُخلص له العبادة، ولا تُطلب من هذه الآلهة التي لا تضر ولا تنفع، ثم إليه تُرجَعون بعد مماتكم للحساب والجزاء.", "isBasmala": false, "translation_en": "Say, \"All intercession is up to God. To Him belongs the kingdom of the heavens and the earth. Then to Him you will be returned.\"", "translation_id": "Katakanlah: \"Hanya kepunyaan Allah syafa'at itu semuanya. Kepunyaan-Nya kerajaan langit dan bumi. Kemudian kepada-Nya-lah kamu dikembalikan\"", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 45, "text": "وَإِذَا ذُكِرَ ٱللَّهُ وَحۡدَهُ ٱشۡمَأَزَّتۡ قُلُوبُ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِۖ وَإِذَا ذُكِرَ ٱلَّذِینَ مِن دُونِهِۦۤ إِذَا هُمۡ یَسۡتَبۡشِرُونَ ۝٤٥", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "وإذا ذُكِر الله وحده نفرت قلوب الذين لا يؤمنون بالمعاد والبعث بعد الممات، وإذا ذُكِر الذين مِن دونه من الأصنام والأوثان والأولياء إذا هم يفرحون؛ لكون الشرك موافقًا لأهوائهم.", "isBasmala": false, "translation_en": "When God alone is mentioned, the hearts of those who do not believe in the Hereafter shrink with resentment. But when those other than Him are mentioned, they become filled with joy.", "translation_id": "Dan apabila hanya nama Allah saja disebut, kesallah hati orang-orang yang tidak beriman kepada kehidupan akhirat; dan apabila nama sembahan-sembahan selain Allah yang disebut, tiba-tiba mereka bergirang hati.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 46, "text": "قُلِ ٱللَّهُمَّ فَاطِرَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ عَـٰلِمَ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ أَنتَ تَحۡكُمُ بَیۡنَ عِبَادِكَ فِی مَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ ۝٤٦", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "قل: اللهم يا خالق السموات والأرض ومبدعهما على غير مثال سبق، عالم السر والعلانية، أنت تفصل بين عبادك يوم القيامة فيما كانوا فيه يختلفون من القول فيك، وفي عظمتك وسلطانك والإيمان بك وبرسولك، اهدني لما اختُلِف فيه من الحق بإذنك، إنك تهدي مَن تشاء إلى صراط مستقيم. وكان هذا مِن دعائه صلى الله عليه وسلم، وهو تعليم للعباد بالالتجاء إلى الله تعالى، ودعائه بأسمائه الحسنى وصفاته العلى.", "isBasmala": false, "translation_en": "Say, \"Our God, Initiator of the heavens and the earth, Knower of all secrets and declarations. You will judge between your servants regarding what they had differed about.\"", "translation_id": "Katakanlah: \"Wahai Allah, Pencipta langit dan bumi, Yang mengetahui barang ghaib dan yang nyata, Engkaulah Yang memutuskan antara hamba-hamba-Mu tentang apa yang selalu mereka memperselisihkannya\".", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 47, "text": "وَلَوۡ أَنَّ لِلَّذِینَ ظَلَمُوا۟ مَا فِی ٱلۡأَرۡضِ جَمِیعࣰا وَمِثۡلَهُۥ مَعَهُۥ لَٱفۡتَدَوۡا۟ بِهِۦ مِن سُوۤءِ ٱلۡعَذَابِ یَوۡمَ ٱلۡقِیَـٰمَةِۚ وَبَدَا لَهُم مِّنَ ٱللَّهِ مَا لَمۡ یَكُونُوا۟ یَحۡتَسِبُونَ ۝٤٧", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "ولو أن لهؤلاء المشركين بالله ما في الأرض جميعا مِن مال وذخائر، ومثله معه مضاعفًا، لَبذلوه يوم القيامة؛ ليفتدوا به من سوء العذاب، ولو بذلوا وافتدوا به ما قُبِل منهم، ولا أغنى عنهم من عذاب الله شيئًا، وظهر لهم يومئذٍ من أمر الله وعذابه ما لم يكونوا يحتسبون في الدنيا أنه نازل بهم.", "isBasmala": false, "translation_en": "If those who did wrong owned everything on earth, and the like of it with it, they would redeem themselves with it from the terrible suffering on the Day of Resurrection. But there will appear to them from God what they never anticipated.", "translation_id": "Dan sekiranya orang-orang yang zalim mempunyai apa yang ada di bumi semuanya dan (ada pula) sebanyak itu besertanya, niscaya mereka akan menebus dirinya dengan itu dari siksa yang buruk pada hari kiamat. Dan jelaslah bagi mereka azab dari Allah yang belum pernah mereka perkirakan.", "manzil": 6, "manzil_display": ""}], "464": [{"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 48, "text": "وَبَدَا لَهُمۡ سَیِّـَٔاتُ مَا كَسَبُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٤٨", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "وظهر لهؤلاء المكذبين يوم الحساب جزاء سيئاتهم التي اقترفوها، حيث نسبوا إلى الله ما لا يليق به، وارتكبوا المعاصي في حياتهم، وأحاط بهم من كل جانب عذاب أليم؛ عقابًا لهم على استهزائهم بالإنذار بالعذاب الذي كان الرسول يَعِدُهم به، ولا يأبهون له.", "isBasmala": false, "translation_en": "There will appear to them the evils of their deeds, and they will be surrounded by what they used to ridicule.", "translation_id": "Dan (jelaslah) bagi mereka akibat buruk dari apa yang telah mereka perbuat dan mereka diliputi oleh pembalasan yang mereka dahulu selalu memperolok-olokkannya.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 49, "text": "فَإِذَا مَسَّ ٱلۡإِنسَـٰنَ ضُرࣱّ دَعَانَا ثُمَّ إِذَا خَوَّلۡنَـٰهُ نِعۡمَةࣰ مِّنَّا قَالَ إِنَّمَاۤ أُوتِیتُهُۥ عَلَىٰ عِلۡمِۭۚ بَلۡ هِیَ فِتۡنَةࣱ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ ۝٤٩", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "فإذا أصاب الإنسان شدة وضُرٌّ، طلب من ربه أن يُفرِّج عنه، فإذا كشفنا عنه ما أصابه وأعطيناه نعمة منا عاد بربه كافرًا، ولفضله منكرًا، وقال: إن الذي أوتيتُه إنما هو على علم من الله أني له أهل ومستحق، بل ذلك فتنة يبتلي الله بها عباده؛ لينظر مَن يشكره ممن يكفره، ولكن أكثرهم- لجهلهم وسوء ظنهم وقولهم- لا يعلمون؛ فلذلك يعدُّون الفتنة منحة.", "isBasmala": false, "translation_en": "When adversity touches the human being, he calls on Us. But then, when We favor him with a blessing from Us, he says, \"I have attained this by virtue of my knowledge.\" However, it is a test, but most of them do not know.", "translation_id": "Maka apabila manusia ditimpa bahaya ia menyeru Kami, kemudian apabila Kami berikan kepadanya nikmat dari Kami ia berkata: \"Sesungguhnya aku diberi nikmat itu hanyalah karena kepintaranku\". Sebenarnya itu adalah ujian, tetapi kebanyakan mereka itu tidak mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 50, "text": "قَدۡ قَالَهَا ٱلَّذِینَ مِن قَبۡلِهِمۡ فَمَاۤ أَغۡنَىٰ عَنۡهُم مَّا كَانُوا۟ یَكۡسِبُونَ ۝٥٠", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "قد قال مقالتهم هذه مَن قبلهم من الأمم الخالية المكذبة، فما أغنى عنهم حين جاءهم العذاب ما كانوا يكسبونه من الأموال والأولاد.", "isBasmala": false, "translation_en": "Those before them said it, but what they had earned did not avail them.", "translation_id": "Sungguh orang-orang yang sebelum mereka (juga) telah mengatakan itu pula, maka tiadalah berguna bagi mereka apa yang dahulu mereka usahakan.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 51, "text": "فَأَصَابَهُمۡ سَیِّـَٔاتُ مَا كَسَبُوا۟ۚ وَٱلَّذِینَ ظَلَمُوا۟ مِنۡ هَـٰۤؤُلَاۤءِ سَیُصِیبُهُمۡ سَیِّـَٔاتُ مَا كَسَبُوا۟ وَمَا هُم بِمُعۡجِزِینَ ۝٥١", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "فأصاب الذين قالوا هذه المقالة من الأمم الخالية وبال سيئات ما كسبوا من الأعمال، فعوجلوا بالخزي في الحياة الدنيا، والذين ظلموا أنفسهم من قومك -أيها الرسول-، وقالوا هذه المقالة، سيصيبهم أيضًا وبال سيئات ما كسبوا، كما أصاب الذين من قبلهم، وما هم بفائتين الله ولا سابقيه.", "isBasmala": false, "translation_en": "The evils of their deeds caught up with them. And the wrongdoers among these will also be afflicted by the evils of what they earned, and they cannot prevent it.", "translation_id": "Maka mereka ditimpa oleh akibat buruk dari apa yang mereka usahakan. Dan orang-orang yang zalim di antara mereka akan ditimpa akibat buruk dari usahanya dan mereka tidak dapat melepaskan diri.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 52, "text": "أَوَ لَمۡ یَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ ۝٥٢", "juz": 24, "hizb": "(* ح 47*)", "tafsir": "أولم يعلم هؤلاء أن رزق الله للإنسان لا يدل على حسن حال صاحبه، فإن الله لبالغ حكمته يوسِّع الرزق لمن يشاء مِن عباده، صالحًا كان أو طالحًا، ويضيِّقه على مَن يشاء منهم؟ إن في ذلك التوسيع والتضييق في الرزق لَدلالات واضحات لقوم يُصدِّقون أمر الله ويعملون به.", "isBasmala": false, "translation_en": "Do they not know that God extends the provision to whomever He wills, and constricts it? In that are signs for people who believe.", "translation_id": "Dan tidakkah mereka mengetahui bahwa Allah melapangkan rezeki dan menyempitkannya bagi siapa yang dikehendaki-Nya? Sesungguhnya pada yang demikian itu terdapat tanda-tanda kekuasaan Allah bagi kaum yang beriman.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 53, "text": "۞ قُلۡ یَـٰعِبَادِیَ ٱلَّذِینَ أَسۡرَفُوا۟ عَلَىٰۤ أَنفُسِهِمۡ لَا تَقۡنَطُوا۟ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ یَغۡفِرُ ٱلذُّنُوبَ جَمِیعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ ۝٥٣", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "قل -أيها الرسول- لعبادي الذين تمادَوا في المعاصي، وأسرفوا على أنفسهم بإتيان ما تدعوهم إليه نفوسهم من الذنوب: لا تَيْئسوا من رحمة الله؛ لكثرة ذنوبكم، إن الله يغفر الذنوب جميعًا لمن تاب منها ورجع عنها مهما كانت، إنه هو الغفور لذنوب التائبين من عباده، الرحيم بهم.", "isBasmala": false, "translation_en": "Say, \"O My servants who have transgressed against themselves: do not despair of God's mercy, for God forgives all sins. He is indeed the Forgiver, the Clement.\"", "translation_id": "Katakanlah: \"Hai hamba-hamba-Ku yang malampaui batas terhadap diri mereka sendiri, janganlah kamu berputus asa dari rahmat Allah. Sesungguhnya Allah mengampuni dosa-dosa semuanya. Sesungguhnya Dialah Yang Maha Pengampun lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 54, "text": "وَأَنِیبُوۤا۟ إِلَىٰ رَبِّكُمۡ وَأَسۡلِمُوا۟ لَهُۥ مِن قَبۡلِ أَن یَأۡتِیَكُمُ ٱلۡعَذَابُ ثُمَّ لَا تُنصَرُونَ ۝٥٤", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "وارجعوا إلى ربكم- أيها الناس- بالطاعة والتوبة، واخضعوا له من قبل أن يقع بكم عقابه، ثم لا ينصركم أحد من دون الله.", "isBasmala": false, "translation_en": "And turn to your Lord, and submit to Him, before the retribution comes upon you. Then you will not be helped.", "translation_id": "Dan kembalilah kamu kepada Tuhanmu, dan berserah dirilah kepada-Nya sebelum datang azab kepadamu kemudian kamu tidak dapat ditolong (lagi).", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 55, "text": "وَٱتَّبِعُوۤا۟ أَحۡسَنَ مَاۤ أُنزِلَ إِلَیۡكُم مِّن رَّبِّكُم مِّن قَبۡلِ أَن یَأۡتِیَكُمُ ٱلۡعَذَابُ بَغۡتَةࣰ وَأَنتُمۡ لَا تَشۡعُرُونَ ۝٥٥", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "واتبعوا أحسن ما أُنزل إليكم من ربكم، وهو القرآن العظيم، وكله حسن، فامتثلوا أوامره، واجتنبوا نواهية من قبل أن يأتيكم العذاب فجأة، وأنتم لا تعلمون به.", "isBasmala": false, "translation_en": "And follow the best of what was revealed to you from your Lord, before the punishment comes upon you suddenly, while you are unaware.", "translation_id": "Dan ikutilah sebaik-baik apa yang telah diturunkan kepadamu dari Tuhanmu sebelum datang azab kepadamu dengan tiba-tiba, sedang kamu tidak menyadarinya,", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 56, "text": "أَن تَقُولَ نَفۡسࣱ یَـٰحَسۡرَتَىٰ عَلَىٰ مَا فَرَّطتُ فِی جَنۢبِ ٱللَّهِ وَإِن كُنتُ لَمِنَ ٱلسَّـٰخِرِینَ ۝٥٦", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "وأطيعوا ربكم وتوبوا إليه حتى لا تندم نفس وتقول: يا حسرتى على ما ضيَّعت في الدنيا من العمل بما أمر الله به، وقصَّرت في طاعته وحقه، وإن كنت في الدنيا لمن المستهزئين بأمر الله وكتابه ورسوله والمؤمنين به.", "isBasmala": false, "translation_en": "So that a soul may not say, \"How sorry I am, for having neglected my duty to God, and for having been of the scoffers.\"", "translation_id": "supaya jangan ada orang yang mengatakan: \"Amat besar penyesalanku atas kelalaianku dalam (menunaikan kewajiban) terhadap Allah, sedang aku sesungguhnya termasuk orang-orang yang memperolok-olokkan (agama Allah),", "manzil": 6, "manzil_display": ""}], "465": [{"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 57, "text": "أَوۡ تَقُولَ لَوۡ أَنَّ ٱللَّهَ هَدَىٰنِی لَكُنتُ مِنَ ٱلۡمُتَّقِینَ ۝٥٧", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "أو تقول: لو أن الله أرشدني إلى دينه لكنت من المتقين الشرك والمعاصي.", "isBasmala": false, "translation_en": "Or say, \"Had God guided me; I would have been of the pious.\"", "translation_id": "atau supaya jangan ada yang berkata: 'Kalau sekiranya Allah memberi petunjuk kepadaku tentulah aku termasuk orang-orang yang bertakwa'.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 58, "text": "أَوۡ تَقُولَ حِینَ تَرَى ٱلۡعَذَابَ لَوۡ أَنَّ لِی كَرَّةࣰ فَأَكُونَ مِنَ ٱلۡمُحۡسِنِینَ ۝٥٨", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "أو تقول حين ترى عقاب الله قد أحاط بها يوم الحساب: ليت لي رجعة إلى الحياة الدنيا، فأكون فيها من الذين أحسنوا بطاعة ربهم، والعمل بما أمَرَتْهم به الرسل.", "isBasmala": false, "translation_en": "Or say, when it sees the penalty, \"If only I had another chance, I would be of the virtuous.\"", "translation_id": "Atau supaya jangan ada yang berkata ketika ia melihat azab 'Kalau sekiranya aku dapat kemnbali (ke dunia), niscaya aku akan termasuk orang-orang berbuat baik'.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 59, "text": "بَلَىٰ قَدۡ جَاۤءَتۡكَ ءَایَـٰتِی فَكَذَّبۡتَ بِهَا وَٱسۡتَكۡبَرۡتَ وَكُنتَ مِنَ ٱلۡكَـٰفِرِینَ ۝٥٩", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "ما القول كما تقول، قد جاءتك آياتي الواضحة الدالة على الحق، فكذَّبت بها، واستكبرت عن قَبولها واتباعها، وكنت من الكافرين بالله ورسله.", "isBasmala": false, "translation_en": "Yes indeed! My Verses did come to you, but you called them lies, turned arrogant, and were of the faithless.", "translation_id": "(Bukan demikian) sebenarya telah datang keterangan-keterangan-Ku kepadamu lalu kamu mendustakannya dan kamu menyombongkan diri dan adalah kamu termasuk orang-orang yang kafir\".", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 60, "text": "وَیَوۡمَ ٱلۡقِیَـٰمَةِ تَرَى ٱلَّذِینَ كَذَبُوا۟ عَلَى ٱللَّهِ وُجُوهُهُم مُّسۡوَدَّةٌۚ أَلَیۡسَ فِی جَهَنَّمَ مَثۡوࣰى لِّلۡمُتَكَبِّرِینَ ۝٦٠", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "ويوم القيامة ترى هؤلاء المكذبين الذين وصفوا ربهم بما لا يليق به، ونسبوا إليه الشريك والولد وجوههم مسودة. أليس في جهنم مأوى ومسكن لمن تكبر على الله، فامتنع من توحيده وطاعته؟ بلى.", "isBasmala": false, "translation_en": "On the Day of Resurrection, you will see those who told lies about God with their faces blackened. Is there not a place in Hell for the arrogant?", "translation_id": "Dan pada hari kiamat kamu akan melihat orang-orang yang berbuat dusta terhadap Allah, mukanya menjadi hitam. Bukankah dalam neraka Jahannam itu ada tempat bagi orang-orang yang menyombongkan diri?", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 61, "text": "وَیُنَجِّی ٱللَّهُ ٱلَّذِینَ ٱتَّقَوۡا۟ بِمَفَازَتِهِمۡ لَا یَمَسُّهُمُ ٱلسُّوۤءُ وَلَا هُمۡ یَحۡزَنُونَ ۝٦١", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "وينجي الله من جهنم وعذابها الذين اتقوا ربهم بأداء فرائضه واجتناب نواهيه بفوزهم وتحقق أمنيتهم، وهي الظَّفَر بالجنة، لا يمسهم من عذاب جهنم شيء، ولا هم يحزنون على ما فاتهم من حظوظ الدنيا.", "isBasmala": false, "translation_en": "And God will save those who maintained righteousness to their place of salvation. No harm will touch them, nor will they grieve.", "translation_id": "Dan Allah menyelamatkan orang-orang yang bertakwa karena kemenangan mereka, mereka tiada disentuh oleh azab (neraka dan tidak pula) mereka berduka cita.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 62, "text": "ٱللَّهُ خَـٰلِقُ كُلِّ شَیۡءࣲۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ وَكِیلࣱ ۝٦٢", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "الله تعالى هو خالق الأشياء كلها، وربها ومليكها والمتصرف فيها، وهو على كل شيء حفيظ يدَبِّر جميع شؤون خلقه.", "isBasmala": false, "translation_en": "God is the Creator of all things, and He is in Charge of all things.", "translation_id": "Allah menciptakan segala sesuatu dan Dia memelihara segala sesuatu.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 63, "text": "لَّهُۥ مَقَالِیدُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۗ وَٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ ٱللَّهِ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ ۝٦٣", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "لله مفاتيح خزائن السموات والأرض، يعطي منها خَلْقَه كيف يشاء. والذين جحدوا بآيات القرآن وما فيها من الدلائل الواضحة، أولئك هم الخاسرون في الدنيا بخِذْلانهم عن الإيمان، وفي الآخرة بخلودهم في النار.", "isBasmala": false, "translation_en": "To Him belong the reins of the heavens and the earth. But those who blaspheme against the revelations of God-it is they who are the losers.", "translation_id": "Kepunyaan-Nya-lah kunci-kunci (perbendaharaan) langit dan bumi. Dan orang-orang yang kafir terhadap ayat-ayat Allah, mereka itulah orang-orang yang merugi.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 64, "text": "قُلۡ أَفَغَیۡرَ ٱللَّهِ تَأۡمُرُوۤنِّیۤ أَعۡبُدُ أَیُّهَا ٱلۡجَـٰهِلُونَ ۝٦٤", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "قل -أيها الرسول- لمشركي قومك: أفغير الله أيها الجاهلون بالله تأمرونِّي أن أعبد، ولا تصلح العبادة لشيء سواه؟", "isBasmala": false, "translation_en": "Say, \"Is it other than God you instruct me to worship, you ignorant ones?\"", "translation_id": "Katakanlah: \"Maka apakah kamu menyuruh aku menyembah selain Allah, hai orang-orang yang tidak berpengetahuan?\"", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 65, "text": "وَلَقَدۡ أُوحِیَ إِلَیۡكَ وَإِلَى ٱلَّذِینَ مِن قَبۡلِكَ لَىِٕنۡ أَشۡرَكۡتَ لَیَحۡبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ ٱلۡخَـٰسِرِینَ ۝٦٥", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "ولقد أوحي إليك -أيها الرسول- وإلى من قبلك من الرسل: لئن أشركت بالله غيره ليبطلنَّ عملك، ولتكوننَّ من الهالكين الخاسرين دينك وآخرتك؛ لأنه لا يُقبل مع الشرك عمل صالح.", "isBasmala": false, "translation_en": "It was revealed to you, and to those before you, that if you idolize, your works will be in vain, and you will be of the losers.", "translation_id": "Dan sesungguhnya telah diwahyukan kepadamu dan kepada (nabi-nabi) yang sebelummu. \"Jika kamu mempersekutukan (Tuhan), niscaya akan hapuslah amalmu dan tentulah kamu termasuk orang-orang yang merugi.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 66, "text": "بَلِ ٱللَّهَ فَٱعۡبُدۡ وَكُن مِّنَ ٱلشَّـٰكِرِینَ ۝٦٦", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "بل الله فاعبد -أيها النبي- مخلصًا له العبادة وحده لا شريك له، وكن من الشاكرين لله نعمه.", "isBasmala": false, "translation_en": "Rather, worship God, and be of the appreciative.", "translation_id": "Karena itu, maka hendaklah Allah saja kamu sembah dan hendaklah kamu termasuk orang-orang yang bersyukur\".", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 67, "text": "وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدۡرِهِۦ وَٱلۡأَرۡضُ جَمِیعࣰا قَبۡضَتُهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ وَٱلسَّمَـٰوَ ٰتُ مَطۡوِیَّـٰتُۢ بِیَمِینِهِۦۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ ۝٦٧", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "وما عظَّم هؤلاء المشركون اللهَ حق تعظيمه؛ إذ عبدوا معه غيره مما لا ينفع ولا يضر، فسوَّوا المخلوق مع عجزه بالخالق العظيم، الذي من عظيم قدرته أن جميع الأرض في قبضته يوم القيامة، والسموات مطويات بيمينه، تنزه وتعاظم سبحانه وتعالى عما يشرك به هؤلاء المشركون، وفي الآية دليل على إثبات القبضة، واليمين، والطيِّ، لله كما يليق بجلاله وعظمته، من غير تكييف ولا تشبيه.", "isBasmala": false, "translation_en": "They have not esteemed God as He ought to be esteemed. The entire earth will be in His grip on the Day of Resurrection, and the heavens will be folded in His righ. Immaculate is He, and Transcendent He is beyond the associations they make.", "translation_id": "Dan mereka tidak mengagungkan Allah dengan pengagungan yang semestinya padahal bumi seluruhnya dalam genggaman-Nya pada hari kiamat dan langit digulung dengan tangan kanan-Nya. Maha Suci Tuhan dan Maha Tinggi Dia dari apa yang mereka persekutukan.", "manzil": 6, "manzil_display": ""}], "466": [{"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 68, "text": "وَنُفِخَ فِی ٱلصُّورِ فَصَعِقَ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَمَن فِی ٱلۡأَرۡضِ إِلَّا مَن شَاۤءَ ٱللَّهُۖ ثُمَّ نُفِخَ فِیهِ أُخۡرَىٰ فَإِذَا هُمۡ قِیَامࣱ یَنظُرُونَ ۝٦٨", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "ونُفِخ في \"القرن\" فمات كلُّ مَن في السموات والأرض، إلا مَن شاء الله عدم موته، ثم نفخ المَلَك فيه نفخة ثانية مؤذنًا بإحياء جميع الخلائق للحساب أمام ربهم، فإذا هم قيام من قبورهم ينظرون ماذا يفعل الله بهم؟", "isBasmala": false, "translation_en": "And the Trumpet will be sounded, whereupon everyone in the heavens and the earth will be stunned, except whomever God wills. Then it will be sounded another time, whereupon they will rise up, looking on.", "translation_id": "Dan ditiuplah sangkakala, maka matilah siapa yang di langit dan di bumi kecuali siapa yang dikehendaki Allah. Kemudian ditiup sangkakala itu sekali lagi maka tiba-tiba mereka berdiri menunggu (putusannya masing-masing).", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 69, "text": "وَأَشۡرَقَتِ ٱلۡأَرۡضُ بِنُورِ رَبِّهَا وَوُضِعَ ٱلۡكِتَـٰبُ وَجِا۟یۤءَ بِٱلنَّبِیِّـۧنَ وَٱلشُّهَدَاۤءِ وَقُضِیَ بَیۡنَهُم بِٱلۡحَقِّ وَهُمۡ لَا یُظۡلَمُونَ ۝٦٩", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "وأضاءت الأرض يوم القيامة إذا تجلى الحق جل وعلا للخلائق لفصل القضاء، ونشرت الملائكة صحيفة كل فرد، وجيء بالنبيين والشهود على الأمم؛ ليسأل الله النبيين عن التبليغ وعما أجابتهم به أممهم، كما تأتي أمة محمد صلى الله عليه وسلم؛ لتشهد بتبليغ الرسل السابقين لأممهم إذا أنكرت هذا التبليغ، فتقوم الحجة على الأمم، وقضى ربُّ العالمين بين العباد بالعدل التام، وهم لا يُظلمون شيئًا بنقص ثواب أو زيادة عقاب.", "isBasmala": false, "translation_en": "And the earth will shine with the Light of its Lord; and the Book will be put in place; and the prophets and the witnesses will be brought in; and Judgment will be passed among them equitably, and they will not be wronged.", "translation_id": "Dan terang benderanglah bumi (padang mahsyar) dengan cahaya (keadilan) Tuhannya; dan diberikanlah buku (perhitungan perbuatan masing-masing) dan didatangkanlah para nabi dan saksi-saksi dan diberi keputusan di antara mereka dengan adil, sedang mereka tidak dirugikan.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 70, "text": "وَوُفِّیَتۡ كُلُّ نَفۡسࣲ مَّا عَمِلَتۡ وَهُوَ أَعۡلَمُ بِمَا یَفۡعَلُونَ ۝٧٠", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "ووفَّى الله كلَّ نفس جزاء عملها من خير وشر، وهو سبحانه وتعالى أعلم بما يفعلون في الدنيا من طاعة أو معصية.", "isBasmala": false, "translation_en": "And every soul will be fully compensated for what it had done. He is well aware of what they do.", "translation_id": "Dan disempurnakan bagi tiap-tiap jiwa (balasan) apa yang telah dikerjakannya dan Dia lebih mengetahui apa yang mereka kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 71, "text": "وَسِیقَ ٱلَّذِینَ كَفَرُوۤا۟ إِلَىٰ جَهَنَّمَ زُمَرًاۖ حَتَّىٰۤ إِذَا جَاۤءُوهَا فُتِحَتۡ أَبۡوَ ٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَاۤ أَلَمۡ یَأۡتِكُمۡ رُسُلࣱ مِّنكُمۡ یَتۡلُونَ عَلَیۡكُمۡ ءَایَـٰتِ رَبِّكُمۡ وَیُنذِرُونَكُمۡ لِقَاۤءَ یَوۡمِكُمۡ هَـٰذَاۚ قَالُوا۟ بَلَىٰ وَلَـٰكِنۡ حَقَّتۡ كَلِمَةُ ٱلۡعَذَابِ عَلَى ٱلۡكَـٰفِرِینَ ۝٧١", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "وسيق الذين كفروا بالله ورسله إلى جهنم جماعات، حتى إذا جاؤوها فتح الخزنة الموكَّلون بها أبوابها السبعة، وزجروهم قائلين: كيف تعصون الله وتجحدون أنه الإله الحق وحده؟ ألم يرسل إليكم رسلا منكم يتلون عليكم آيات ربكم، ويحذِّرونكم أهوال هذا اليوم؟ قالوا مقرين بذنبهم: بلى قد جاءت رسل ربنا بالحق، وحذَّرونا هذا اليوم، ولكن وجبت كلمة الله أن عذابه لأهل الكفر به.", "isBasmala": false, "translation_en": "Those who disbelieved will be driven to Hell in throngs. Until, when they have reached it, and its gates are opened, its keepers will say to them, \"Did not messengers from among you come to you, reciting to you the revelations of your Lord, and warning you of the meeting of this Day of yours?\" They will say, \"Yes, but the verdict of punishment is justified against the disbelievers.\"", "translation_id": "Orang-orang kafir dibawa ke neraka Jahannam berombong-rombongan. Sehingga apabila mereka sampai ke neraka itu dibukakanlah pintu-pintunya dan berkatalah kepada mereka penjaga-penjaganya: \"Apakah belum pernah datang kepadamu rasul-rasul di antaramu yang membacakan kepadamu ayat-ayat Tuhanmu dan memperingatkan kepadamu akan pertemuan dengan hari ini?\" Mereka menjawab: \"Benar (telah datang)\". Tetapi telah pasti berlaku ketetapan azab terhadap orang-orang yang kafir.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 72, "text": "قِیلَ ٱدۡخُلُوۤا۟ أَبۡوَ ٰبَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِینَ ۝٧٢", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "قيل للجاحدين أن الله هو الإله الحق إهانة لهم وإذلالا: ادخلوا أبواب جهنم ماكثين فيها أبدًا، فقَبُح مصير المتعالين على الإيمان بالله والعمل بشرعه.", "isBasmala": false, "translation_en": "It will be said, \"Enter the gates of Hell, to abide therein eternally.\" How wretched is the destination of the arrogant.", "translation_id": "Dikatakan (kepada mereka): \"Masukilah pintu-pintu neraka Jahannam itu, sedang kamu kekal di dalamnya\" Maka neraka Jahannam itulah seburuk-buruk tempat bagi orang-orang yang menyombongkan diri.", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 73, "text": "وَسِیقَ ٱلَّذِینَ ٱتَّقَوۡا۟ رَبَّهُمۡ إِلَى ٱلۡجَنَّةِ زُمَرًاۖ حَتَّىٰۤ إِذَا جَاۤءُوهَا وَفُتِحَتۡ أَبۡوَ ٰبُهَا وَقَالَ لَهُمۡ خَزَنَتُهَا سَلَـٰمٌ عَلَیۡكُمۡ طِبۡتُمۡ فَٱدۡخُلُوهَا خَـٰلِدِینَ ۝٧٣", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "وسيق الذين اتقوا ربهم بتوحيده والعمل بطاعته إلى الجنة جماعات، حتى إذا جاؤوها وشُفع لهم بدخولها، فتحت أبوابها، فترحِّب بهم الملائكة الموكَّلون بالجنة، ويُحَيُّونهم بالبِشر والسرور؛ لطهارتهم من آثار المعاصي قائلين لهم: سلام عليكم من كل آفة، طابت أحوالكم، فادخلوا الجنة خالدين فيها.", "isBasmala": false, "translation_en": "And those who feared their Lord will be led to Paradise in throngs. Until, when they have reached it, and its gates are opened, its keepers will say to them, \"Peace be upon you, you have been good, so enter it, to abide therein eternally.\"", "translation_id": "Dan orang-orang yang bertakwa kepada Tuhan dibawa ke dalam surga berombong-rombongan (pula). Sehingga apabila mereka sampai ke surga itu sedang pintu-pintunya telah terbuka dan berkatalah kepada mereka penjaga-penjaganya: \"Kesejahteraan (dilimpahkan) atasmu. Berbahagialah kamu! maka masukilah surga ini, sedang kamu kekal di dalamnya\".", "manzil": 6, "manzil_display": ""}, {"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 74, "text": "وَقَالُوا۟ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی صَدَقَنَا وَعۡدَهُۥ وَأَوۡرَثَنَا ٱلۡأَرۡضَ نَتَبَوَّأُ مِنَ ٱلۡجَنَّةِ حَیۡثُ نَشَاۤءُۖ فَنِعۡمَ أَجۡرُ ٱلۡعَـٰمِلِینَ ۝٧٤", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "وقال المؤمنون: الحمد لله الذي صدَقنا وعده الذي وعدَنا إياه على ألسنة رسله، وأورثَنا أرض الجنة نَنْزِل منها في أيِّ مكان شئنا، فنِعم ثواب المحسنين الذين اجتهدوا في طاعة ربهم.", "isBasmala": false, "translation_en": "And they will say, \"Praise be to God, who has fulfilled His promise to us, and made us inherit the land, enjoying Paradise as we please.\" How excellent is the reward of the workers.", "translation_id": "Dan mereka mengucapkan: \"Segala puji bagi Allah yang telah memenuhi janji-Nya kepada kami dan telah (memberi) kepada kami tempat ini sedang kami (diperkenankan) menempati tempat dalam surga di mana saja yang kami kehendaki; maka surga itulah sebaik-baik balasan bagi orang-orang yang beramal\".", "manzil": 6, "manzil_display": ""}], "467": [{"sura": 39, "sura_name": "الزمر", "revelation": "Makkiyah", "aya": 75, "text": "وَتَرَى ٱلۡمَلَـٰۤىِٕكَةَ حَاۤفِّینَ مِنۡ حَوۡلِ ٱلۡعَرۡشِ یُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡۚ وَقُضِیَ بَیۡنَهُم بِٱلۡحَقِّۚ وَقِیلَ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ ۝٧٥", "juz": 24, "hizb": "(*¼ ح 47*)", "tafsir": "وترى-أيها النبي- الملائكة محيطين بعرش الرحمن، ينزهون ربهم عن كل ما لا يليق به، وقضى الله سبحانه وتعالى بين الخلائق بالحق والعدل، فأسكن أهل الإيمان الجنة، وأهل الكفر النار، وقيل: الحمد لله رب العالمين على ما قضى به بين أهل الجنة وأهل النار، حَمْدَ فضل وإحسان، وحَمْدَ عدل وحكمة.", "isBasmala": false, "translation_en": "And you will see the angels hovering around the Throne, glorifying their Lord with praise. And it will be judged between them equitably, and it will be said, \"Praise be to God, Lord of the Worlds.\"", "translation_id": "Dan kamu (Muhammad) akan melihat malaikat-mmlaikat berlingkar di sekeliling 'Arsy bertasbih sambil memuji Tuhannya; dan diberi putusan di antara hamba-hamba Allah dengan adil dan diucapkan: \"Segala puji bagi Allah, Tuhan semesta alam\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 24, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 1, "text": "۞ حمۤ ۝١", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "(حم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ha, Meem.", "translation_id": "Haa Miim.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 2, "text": "تَنزِیلُ ٱلۡكِتَـٰبِ مِنَ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡعَلِیمِ ۝٢", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "تنزيل القرآن على النبي محمد صلى الله عليه وسلم من عند الله- عزَّ وجل- العزيز الذي قهر بعزته كل مخلوق، العليم بكل شيء.", "isBasmala": false, "translation_en": "The sending down of the Scripture is from God the Almighty, the Omniscient.", "translation_id": "Diturunkan Kitab ini (Al Quran) dari Allah Yang Maha Perkasa lagi Maha Mengetahui,", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 3, "text": "غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِیدِ ٱلۡعِقَابِ ذِی ٱلطَّوۡلِۖ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ إِلَیۡهِ ٱلۡمَصِیرُ ۝٣", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "غافر الذنب للمذنبين، وقابل التوب من التائبين، شديد العقاب على مَن تجرَّأَ على الذنوب، ولم يتب منها، وهو سبحانه وتعالى صاحب الإنعام والتفضُّل على عباده الطائعين، لا معبود تصلح العبادة له سواه، إليه مصير جميع الخلائق يوم الحساب، فيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "Forgiver of sins, Accepter of repentance, Severe in punishment, Bountiful in bounty. There is no god but He. To Him is the ultimate return.", "translation_id": "Yang Mengampuni dosa dan Menerima taubat lagi keras hukuman-Nya. Yang mempunyai karunia. Tiada Tuhan (yang berhak disembah) selain Dia. Hanya kepada-Nya-lah kembali (semua makhluk).", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 4, "text": "مَا یُجَـٰدِلُ فِیۤ ءَایَـٰتِ ٱللَّهِ إِلَّا ٱلَّذِینَ كَفَرُوا۟ فَلَا یَغۡرُرۡكَ تَقَلُّبُهُمۡ فِی ٱلۡبِلَـٰدِ ۝٤", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "ما يخاصم في آيات القرآن وأدلته على وحدانية الله، ويقابلها بالباطل إلا الجاحدون الذين جحدوا أنه الإله الحق المستحق للعبادة وحده، فلا يغررك -أيها الرسول- ترددهم في البلاد بأنواع التجارات والمكاسب، ونعيم الدنيا وزهرتها.", "isBasmala": false, "translation_en": "None argues against God's revelations except those who disbelieve. So do not be impressed by their activities in the land.", "translation_id": "Tidak ada yang memperdebatkan tentang ayat-ayat Allah, kecuali orang-orang yang kafir. Karena itu janganlah pulang balik mereka dengan bebas dari suatu kota ke kota yang lain memperdayakan kamu.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 5, "text": "كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَٱلۡأَحۡزَابُ مِنۢ بَعۡدِهِمۡۖ وَهَمَّتۡ كُلُّ أُمَّةِۭ بِرَسُولِهِمۡ لِیَأۡخُذُوهُۖ وَجَـٰدَلُوا۟ بِٱلۡبَـٰطِلِ لِیُدۡحِضُوا۟ بِهِ ٱلۡحَقَّ فَأَخَذۡتُهُمۡۖ فَكَیۡفَ كَانَ عِقَابِ ۝٥", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "كذَّبت قبل هؤلاء الكفار قومُ نوح ومَن تلاهم من الأمم التي أعلنت حربها على الرسل كعاد وثمود، حيث عزموا على إيذائهم وتجمَّعوا عليهم بالتعذيب أو القتل، وهمَّت كل أمة من هذه الأمم المكذبة برسولهم ليقتلوه، وخاصموا بالباطل؛ ليبطلوا بجدالهم الحق فعاقَبْتُهم، فكيف كان عقابي إياهم عبرة للخلق، وعظة لمن يأتي بعدهم؟", "isBasmala": false, "translation_en": "Before them the people of Noah rejected the truth, as did the confederates after them. Every community plotted against their messenger, to capture him. And they argued with falsehood, to defeat with it the truth. But I seized them. What a punishment it was!", "translation_id": "Sebelum mereka, kaum Nuh dan golongan-golongan yang bersekutu sesudah mereka telah mendustakan (rasul) dan tiap-tiap umat telah merencanakan makar terhadap rasul mereka untuk menawannya dan mereka membantah dengan (alasan) yang batil untuk melenyapkan kebenaran dengan yang batil itu; karena itu Aku azab mereka. Maka betapa (pedihnya) azab-Ku?", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 6, "text": "وَكَذَ ٰلِكَ حَقَّتۡ كَلِمَتُ رَبِّكَ عَلَى ٱلَّذِینَ كَفَرُوۤا۟ أَنَّهُمۡ أَصۡحَـٰبُ ٱلنَّارِ ۝٦", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "وكما حق العقاب على الأمم السابقة التي كذَّبت رسلها، حق على الذين كفروا أنهم أصحاب النار.", "isBasmala": false, "translation_en": "Thus the sentence of your Lord became realized against those who disbelieve, that they are to be inmates of the Fire.", "translation_id": "Dan demikianlah telah pasti berlaku ketetapan azab Tuhanmu terhadap orang-orang kafir, karena sesungguhnya mereka adalah penghuni neraka.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 7, "text": "ٱلَّذِینَ یَحۡمِلُونَ ٱلۡعَرۡشَ وَمَنۡ حَوۡلَهُۥ یُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَیُؤۡمِنُونَ بِهِۦ وَیَسۡتَغۡفِرُونَ لِلَّذِینَ ءَامَنُوا۟ۖ رَبَّنَا وَسِعۡتَ كُلَّ شَیۡءࣲ رَّحۡمَةࣰ وَعِلۡمࣰا فَٱغۡفِرۡ لِلَّذِینَ تَابُوا۟ وَٱتَّبَعُوا۟ سَبِیلَكَ وَقِهِمۡ عَذَابَ ٱلۡجَحِیمِ ۝٧", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "الذين يحملون عرش الرحمن من الملائكة ومَن حول العرش ممن يحف به منهم، ينزِّهون الله عن كل نقص، ويحمَدونه بما هو أهل له، ويؤمنون به حق الإيمان، ويطلبون منه أن يعفو عن المؤمنين، قائلين: ربنا وسعت كل شيء رحمة وعلمًا، فاغفر للذين تابوا من الشرك والمعاصي، وسلكوا الطريق الذي أمرتهم أن يسلكوه وهو الإسلام، وجَنِّبْهم عذاب النار وأهوالها.", "isBasmala": false, "translation_en": "Those who carry the Throne, and those around it, glorify their Lord with praise, and believe in Him, and ask for forgiveness for those who believe: \"Our Lord, You have encompassed everything in mercy and knowledge; so forgive those who repent and follow Your path, and protect them from the agony of the Blaze.", "translation_id": "(Malaikat-malaikat) yang memikul 'Arsy dan malaikat yang berada di sekelilingnya bertasbih memuji Tuhannya dan mereka beriman kepada-Nya serta memintakan ampun bagi orang-orang yang beriman (seraya mengucapkan): \"Ya Tuhan kami, rahmat dan ilmu Engkau meliputi segala sesuatu, maka berilah ampunan kepada orang-orang yang bertaubat dan mengikuti jalan Engkau dan peliharalah mereka dari siksaan neraka yang menyala-nyala,", "manzil": 6, "manzil_display": ""}], "468": [{"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 8, "text": "رَبَّنَا وَأَدۡخِلۡهُمۡ جَنَّـٰتِ عَدۡنٍ ٱلَّتِی وَعَدتَّهُمۡ وَمَن صَلَحَ مِنۡ ءَابَاۤىِٕهِمۡ وَأَزۡوَ ٰجِهِمۡ وَذُرِّیَّـٰتِهِمۡۚ إِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٨", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "ربنا وأدخل المؤمنين جنات عدن التي وعدتهم، ومَن صلح بالإيمان والعمل الصالح من آبائهم وأزواجهم وأولادهم. إنك أنت العزيز القاهر لكل شيء، الحكيم في تدبيره وصنعه.", "isBasmala": false, "translation_en": "And admit them, Our Lord, into the Gardens of Eternity, which You have promised them, and the righteous among their parents, and their spouses, and their offspring. You are indeed the Almighty, the Most Wise.", "translation_id": "ya Tuhan kami, dan masukkanlah mereka ke dalam surga 'Adn yang telah Engkau janjikan kepada mereka dan orang-orang yang saleh di antara bapak-bapak mereka, dan isteri-isteri mereka, dan keturunan mereka semua. Sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana,", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 9, "text": "وَقِهِمُ ٱلسَّیِّـَٔاتِۚ وَمَن تَقِ ٱلسَّیِّـَٔاتِ یَوۡمَىِٕذࣲ فَقَدۡ رَحِمۡتَهُۥۚ وَذَ ٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝٩", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "واصرف عنهم سوء عاقبة سيئاتهم، فلا تؤاخذهم بها، ومن تصْرِف عنه السيئات يوم الحساب فقد رحمته، وأنعمت عليه بالنجاة من عذابك، وذلك هو الظَّفَر العظيم الذي لا فوز مثله.", "isBasmala": false, "translation_en": "And shield them from the evil deeds. Whomever You shield from the evil deeds, on that Day, You have had mercy on him. That is the supreme achievement.\"", "translation_id": "dan peliharalah mereka dari (balasan) kejahatan. Dan orang-orang yang Engkau pelihara dari (pembalasan) kejahatan pada hari itu maka sesungguhnya telah Engkau anugerahkan rahmat kepadanya dan itulah kemenangan yang besar\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 10, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ یُنَادَوۡنَ لَمَقۡتُ ٱللَّهِ أَكۡبَرُ مِن مَّقۡتِكُمۡ أَنفُسَكُمۡ إِذۡ تُدۡعَوۡنَ إِلَى ٱلۡإِیمَـٰنِ فَتَكۡفُرُونَ ۝١٠", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "إن الذين جحدوا أن الله هو الإله الحق وصرفوا العبادة لغيره عندما يعاينون أهوال النار بأنفسهم، يَمْقُتون أنفسهم أشد المقت، وعند ذلك يناديهم خزنة جهنم: لَمقت الله لكم في الدنيا- حين طلب منكم الإيمان به واتباع رسله، فأبيتم- أكبر من بغضكم لأنفسكم الآن، بعد أن أدركتم أنكم تستحقون سخط الله وعذابه.", "isBasmala": false, "translation_en": "Those who disbelieved will be addressed, \"The loathing of God is greater than your loathing of yourselves-for you were invited to the faith, but you refused.\"", "translation_id": "Sesungguhnya orang-orang yang kafir diserukan kepada mereka (pada hari kiamat): \"Sesungguhnya kebencian Allah (kepadamu) lebih besar daripada kebencianmu kepada dirimu sendiri karena kamu diseru untuk beriman lalu kamu kafir\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 11, "text": "قَالُوا۟ رَبَّنَاۤ أَمَتَّنَا ٱثۡنَتَیۡنِ وَأَحۡیَیۡتَنَا ٱثۡنَتَیۡنِ فَٱعۡتَرَفۡنَا بِذُنُوبِنَا فَهَلۡ إِلَىٰ خُرُوجࣲ مِّن سَبِیلࣲ ۝١١", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "قال الكافرون: ربنا أمتَّنا مرتين: حين كنا في بطون أمهاتنا نُطَفًا قبل نفخ الروح، وحين انقضى أجلُنا في الحياة الدنيا، وأحييتنا مرتين: في دار الدنيا، يوم وُلِدْنا، ويوم بُعِثنا من قبورنا، فنحن الآن نُقِرُّ بأخطائنا السابقة، فهل لنا من طريق نخرج به من النار، وتعيدنا به إلى الدنيا؛ لنعمل بطاعتك؟ ولكن هيهات أن ينفعهم هذا الاعتراف.", "isBasmala": false, "translation_en": "They will say, \"Our Lord, you made us die twice, and twice you gave us life. Now we acknowledge our sins. Is there any way out?\"", "translation_id": "Mereka menjawab: \"Ya Tuhan kami Engkau telah mematikan kami dua kali dan telah menghidupkan kami dua kali (pula), lalu kami mengakui dosa-dosa kami. Maka adakah sesuatu jalan (bagi kami) untuk keluar (dari neraka)?\"", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 12, "text": "ذَ ٰلِكُم بِأَنَّهُۥۤ إِذَا دُعِیَ ٱللَّهُ وَحۡدَهُۥ كَفَرۡتُمۡ وَإِن یُشۡرَكۡ بِهِۦ تُؤۡمِنُوا۟ۚ فَٱلۡحُكۡمُ لِلَّهِ ٱلۡعَلِیِّ ٱلۡكَبِیرِ ۝١٢", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "ذلكم العذاب الذي لكم- أيها الكافرون- بسبب أنكم كنتم إذا دُعيتم لتوحيد الله وإخلاص العمل له كفرتم به، وإن يُجْعل لله شريك تُصَدِّقوا به وتتبعوه. فالله سبحانه وتعالى هو الحاكم في خلقه، العادل الذي لا يجور، يهدي من يشاء ويضل من يشاء، ويرحم مَن يشاء ويعذب مَن يشاء، لا إله إلا هو الذي له علو الذات والقَدْر والقهر، وله الكبرياء والعظمة.", "isBasmala": false, "translation_en": "That is because when God alone was called upon, you disbelieved; but when others were associated with Him, you believed. Judgment rests with God the Sublime, the Majestic.", "translation_id": "Yang demikian itu adalah karena kamu kafir apabila Allah saja disembah. Dan kamu percaya apabila Allah dipersekutukan. Maka putusan (sekarang ini) adalah pada Allah Yang Maha Tinggi lagi Maha Besar.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 13, "text": "هُوَ ٱلَّذِی یُرِیكُمۡ ءَایَـٰتِهِۦ وَیُنَزِّلُ لَكُم مِّنَ ٱلسَّمَاۤءِ رِزۡقࣰاۚ وَمَا یَتَذَكَّرُ إِلَّا مَن یُنِیبُ ۝١٣", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "هو الذي يُظْهِر لكم- أيها الناس- قدرته بما تشاهدونه من الآيات العظيمة الدالة على كمال خالقها ومبدعها، ويُنَزِّل لكم من السماء مطرًا تُرزَقون به، وما يتذكر بهذه الآيات إلا مَن يرجع إلى طاعة الله، ويخلص له العبادة.", "isBasmala": false, "translation_en": "It is He who shows you His wonders, and sends down sustenance from the sky for you. But none pays heed except the repentant.", "translation_id": "Dialah yang memperlihatkan kepadamu tanda-tanda (kekuasaan)-Nya dan menurunkan untukmu rezeki dari langit. Dan tiadalah mendapat pelajaran kecuali orang-orang yang kembali (kepada Allah).", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 14, "text": "فَٱدۡعُوا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ وَلَوۡ كَرِهَ ٱلۡكَـٰفِرُونَ ۝١٤", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "فأخلصوا- أيها المؤمنون- لله وحده العبادة والدعاء، وخالفوا المشركين في مسلكهم، ولو أغضبهم ذلك، فلا تبالوا بهم.", "isBasmala": false, "translation_en": "So call upon God, with sincere devotion to Him, even though the disbelievers resent it.", "translation_id": "Maka sembahlah Allah dengan memurnikan ibadat kepada-Nya, meskipun orang-orang kafir tidak menyukai(nya).", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 15, "text": "رَفِیعُ ٱلدَّرَجَـٰتِ ذُو ٱلۡعَرۡشِ یُلۡقِی ٱلرُّوحَ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦ لِیُنذِرَ یَوۡمَ ٱلتَّلَاقِ ۝١٥", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "إن الله هو العليُّ الأعلى الذي ارتفعت درجاته ارتفاعًا باين به مخلوقاته، وارتفع به قَدْره، وهو صاحب العرش العظيم، ومن رحمته بعباده أن يرسل إليهم رسلا يلقي إليهم الوحي الذي يحيون به، فيكونون على بصيرة من أمرهم؛ لتخوِّف الرسل عباد الله، وتنذرهم يوم القيامة الذي يلتقي فيه الأولون والآخرون.", "isBasmala": false, "translation_en": "Exalted in rank, Owner of the Throne. He conveys the Spirit, by His command, upon whomever He wills of His servants, to warn of the Day of Encounter.", "translation_id": "(Dialah) Yang Maha Tinggi derajat-Nya, Yang mempunyai 'Arsy, Yang mengutus Jibril dengan (membawa) perintah-Nya kepada siapa yang dikehendaki-Nya di antara hamba-hamba-Nya, supaya dia memperingatkan (manusia) tentang hari pertemuan (hari kiamat).", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 16, "text": "یَوۡمَ هُم بَـٰرِزُونَۖ لَا یَخۡفَىٰ عَلَى ٱللَّهِ مِنۡهُمۡ شَیۡءࣱۚ لِّمَنِ ٱلۡمُلۡكُ ٱلۡیَوۡمَۖ لِلَّهِ ٱلۡوَ ٰحِدِ ٱلۡقَهَّارِ ۝١٦", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "يوم القيامة تظهر الخلائق أمام ربهم، لا يخفى على الله منهم ولا مِن أعمالهم التي عملوها في الدنيا شيء، يقول الله سبحانه: لمن الملك والتصرف في هذا اليوم؟ فيجيب نفسه: لله المتفرد بأسمائه وصفاته وأفعاله، القهَّار الذي قهر جميع الخلائق بقدرته وعزته.", "isBasmala": false, "translation_en": "The Day when they will emerge, nothing about them will be concealed from God. \"To whom does the sovereignty belong today?\" \"To God, the One, the Irresistible.\"", "translation_id": "(Yaitu) hari (ketika) mereka keluar (dari kubur); tiada suatupun dari keadaan mereka yang tersembunyi bagi Allah. (Lalu Allah berfirman): \"Kepunyaan siapakah kerajaan pada hari ini?\" Kepunyaan Allah Yang Maha Esa lagi Maha Mengalahkan.", "manzil": 6, "manzil_display": ""}], "469": [{"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 17, "text": "ٱلۡیَوۡمَ تُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡۚ لَا ظُلۡمَ ٱلۡیَوۡمَۚ إِنَّ ٱللَّهَ سَرِیعُ ٱلۡحِسَابِ ۝١٧", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "اليوم تثاب كل نفس بما كسبت في الدنيا من خير وشر، لا ظلم لأحد اليوم بزيادة في سيئاته أو نقص من حسناته. إن الله سبحانه وتعالى سريع الحساب، فلا تستبطئوا ذلك اليوم؛ فإنه قريب.", "isBasmala": false, "translation_en": "On that Day, every soul will be recompensed for what it had earned. There will be no injustice on that Day. God is quick to settle accounts.", "translation_id": "Pada hari ini tiap-tiap jiwa diberi balasan dengan apa yang diusahakannya. Tidak ada yang dirugikan pada hari ini. Sesungguhnya Allah amat cepat hisabnya.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 18, "text": "وَأَنذِرۡهُمۡ یَوۡمَ ٱلۡـَٔازِفَةِ إِذِ ٱلۡقُلُوبُ لَدَى ٱلۡحَنَاجِرِ كَـٰظِمِینَۚ مَا لِلظَّـٰلِمِینَ مِنۡ حَمِیمࣲ وَلَا شَفِیعࣲ یُطَاعُ ۝١٨", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "وحذِّر -أيها الرسول- الناس من يوم القيامة القريب، وإن استبعدوه، إذ قلوب العباد مِن مخافة عقاب الله قد ارتفعت من صدورهم، فتعلقت بحلوقهم، وهم ممتلئون غمًّا وحزنًا. ما للظالمين من قريب ولا صاحب، ولا شفيع يشفع لهم عند ربهم، فيستجاب له.", "isBasmala": false, "translation_en": "And warn them of the Day of Imminence, when the hearts are at the throats, choking them. The evildoers will have no intimate friend, and no intercessor to be obeyed.", "translation_id": "Berilah mereka peringatan dengan hari yang dekat (hari kiamat yaitu) ketika hati (menyesak) sampai di kerongkongan dengan menahan kesedihan. Orang-orang yang zalim tidak mempunyai teman setia seorangpun dan tidak (pula) mempunyai seorang pemberi syafa'at yang diterima syafa'atnya.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 19, "text": "یَعۡلَمُ خَاۤىِٕنَةَ ٱلۡأَعۡیُنِ وَمَا تُخۡفِی ٱلصُّدُورُ ۝١٩", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "يعلم الله سبحانه ما تختلسه العيون من نظرات، وما يضمره الإنسان في نفسه من خير أو شر.", "isBasmala": false, "translation_en": "He knows the deceptions of the eyes, and what the hearts conceal.", "translation_id": "Dia mengetahui (pandangan) mata yang khianat dan apa yang disembunyikan oleh hati.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 20, "text": "وَٱللَّهُ یَقۡضِی بِٱلۡحَقِّۖ وَٱلَّذِینَ یَدۡعُونَ مِن دُونِهِۦ لَا یَقۡضُونَ بِشَیۡءٍۗ إِنَّ ٱللَّهَ هُوَ ٱلسَّمِیعُ ٱلۡبَصِیرُ ۝٢٠", "juz": 24, "hizb": "(*½ ح 47*)", "tafsir": "والله سبحانه يقضي بين الناس بالعدل فيما يستحقونه، والذين يُعبدون من دون الله من الآلهة لا يقضون بشيء؛ لعجزهم عن ذلك. إن الله هو السميع لما تنطق به ألسنتكم، البصير بأفعالكم وأعمالكم، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "God judges with justice, while those whom they invoke besides Him cannot judge with anything. It is God who is the Hearing, the Seeing.", "translation_id": "Dan Allah menghukum dengan keadilan. Dan sembahan-sembahan yang mereka sembah selain Allah tiada dapat menghukum dengan sesuatu apapun. Sesungguhnya Allah Dialah Yang Maha Mendengar lagi Maha Melihat.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 21, "text": "۞ أَوَ لَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ كَانُوا۟ مِن قَبۡلِهِمۡۚ كَانُوا۟ هُمۡ أَشَدَّ مِنۡهُمۡ قُوَّةࣰ وَءَاثَارࣰا فِی ٱلۡأَرۡضِ فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡ وَمَا كَانَ لَهُم مِّنَ ٱللَّهِ مِن وَاقࣲ ۝٢١", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "أولم يَسِرْ هؤلاء المكذبون برسالتك -أيها الرسول- في الأرض، فينظروا كيف كان خاتمة الأمم السابقة قبلهم؟ كانوا أشد منهم بطشًا، وأبقى في الأرض آثارًا، فلم تنفعهم شدة قواهم وعِظَم أجسامهم، فأخذهم الله بعقوبته؛ بسبب كفرهم واكتسابهم الآثام، وما كان لهم من عذاب الله من واق يقيهم منه، فيدفعه عنهم.", "isBasmala": false, "translation_en": "Have they not travelled through the earth, and seen the consequences for those before them? They were stronger than them, and they left more impact on earth. But God seized them for their sins, and they had no defender against God.", "translation_id": "Dan apakah mereka tidak mengadakan perjalanan di muka bumi, lalu memperhatikan betapa kesudahan orang-orang yang sebelum mereka. Mereka itu adalah lebih hebat kekuatannya daripada mereka dan (lebih banyak) bekas-bekas mereka di muka bumi, maka Allah mengazab mereka disebabkan dosa-dosa mereka. Dan mereka tidak mempunyai seorang pelindung dari azab Allah.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 22, "text": "ذَ ٰلِكَ بِأَنَّهُمۡ كَانَت تَّأۡتِیهِمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَكَفَرُوا۟ فَأَخَذَهُمُ ٱللَّهُۚ إِنَّهُۥ قَوِیࣱّ شَدِیدُ ٱلۡعِقَابِ ۝٢٢", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "ذلك العذاب الذي حلَّ بالمكذبين السابقين، كان بسبب موقفهم من رسل الله الذين جاؤوا بالدلائل القاطعة على صدق دعواهم، فكفروا بهم، وكذَّبوهم، فأخذهم الله بعقابه، إنه سبحانه قوي لا يغلبه أحد، شديد العقاب لمن كفر به وعصاه.", "isBasmala": false, "translation_en": "That is because their messengers used to come to them with clear proofs, but they disbelieved, so God seized them. He is Strong, Severe in retribution.", "translation_id": "Yang demiklan itu adalah karena telah datang kepada mereka rasul-rasul mereka dengan membawa bukti-bukti yang nyata lalu mereka kafir; maka Allah mengazab mereka. Sesungguhnya Dia Maha Kuat lagi Maha Keras hukuman-Nya.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 23, "text": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔایَـٰتِنَا وَسُلۡطَـٰنࣲ مُّبِینٍ ۝٢٣", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "ولقد أرسلنا موسى بآياتنا العظيمة الدالة على حقيقة ما أُرسل به، وحجة واضحة بيِّنة على صدقه في دعوته، وبطلان ما كان عليه مَن أُرسل إليهم.", "isBasmala": false, "translation_en": "We sent Moses with Our signs, and a clear authority.", "translation_id": "Dan sesungguhnya telah Kami utus Musa dengan membawa ayat-ayat Kami dan keterangan yang nyata,", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 24, "text": "إِلَىٰ فِرۡعَوۡنَ وَهَـٰمَـٰنَ وَقَـٰرُونَ فَقَالُوا۟ سَـٰحِرࣱ كَذَّابࣱ ۝٢٤", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "إلى فرعون ملك \"مصر\"، وهامان وزيره، وقارون صاحب الأموال والكنوز، فأنكروا رسالته واستكبروا، وقالوا عنه: إنه ساحر كذاب، فكيف يزعم أنه أُرسِل للناس رسولا؟", "isBasmala": false, "translation_en": "To Pharaoh, Hamaan, and Quaroon. But they said, \"A lying sorcerer.\"", "translation_id": "kepada Fir'aun, Haman dan Qarun; maka mereka berkata: \"(Ia) adalah seorang ahli sihir yang pendusta\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 25, "text": "فَلَمَّا جَاۤءَهُم بِٱلۡحَقِّ مِنۡ عِندِنَا قَالُوا۟ ٱقۡتُلُوۤا۟ أَبۡنَاۤءَ ٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥ وَٱسۡتَحۡیُوا۟ نِسَاۤءَهُمۡۚ وَمَا كَیۡدُ ٱلۡكَـٰفِرِینَ إِلَّا فِی ضَلَـٰلࣲ ۝٢٥", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "فلما جاء موسى فرعون وهامان وقارون بالمعجزات الظاهرة مِن عندنا، لم يكتفوا بمعارضتها وإنكارها، بل قالوا: اقتلوا أبناء الذين آمنوا معه، واستبقوا نساءهم للخدمة والاسترقاق. وما تدبير أهل الكفر إلا في ذَهاب وهلاك.", "isBasmala": false, "translation_en": "Then, when he came to them with the truth from Us, they said, \"Kill the sons of those who have believed with him, and spare their daughters.\" But the scheming of the unbelievers can only go astray.", "translation_id": "Maka tatkala Musa datang kepada mereka membawa kebenaran dari sisi Kami mereka berkata: \"Bunuhlah anak-anak orang-orang yang beriman bersama dengan dia dan biarkanlah hidup wanita-wanita mereka\". Dan tipu daya orang-orang kafir itu tak lain hanyalah sia-sia (belaka).", "manzil": 6, "manzil_display": ""}], "470": [{"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 26, "text": "وَقَالَ فِرۡعَوۡنُ ذَرُونِیۤ أَقۡتُلۡ مُوسَىٰ وَلۡیَدۡعُ رَبَّهُۥۤۖ إِنِّیۤ أَخَافُ أَن یُبَدِّلَ دِینَكُمۡ أَوۡ أَن یُظۡهِرَ فِی ٱلۡأَرۡضِ ٱلۡفَسَادَ ۝٢٦", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "وقال فرعون لأشراف قومه: اتركوني أقتل موسى، وليدع ربه الذي يزعم أنه أرسله إلينا، فيمنعه منا، إني أخاف أن يُبَدِّل دينكم الذي أنتم عليه، أو أن يُظْهِر في أرض \"مصر\" الفساد.", "isBasmala": false, "translation_en": "Pharaoh said, \"Leave me to kill Moses, and let him appeal to his Lord. I fear he may change your religion, or spread disorder in the land.\"", "translation_id": "Dan berkata Fir'aun (kepada pembesar-pembesarnya): \"Biarkanlah aku membunuh Musa dan hendaklah ia memohon kepada Tuhannya, karena sesungguhnya aku khawatir dia akan menukar agamamu atau menimbulkan kerusakan di muka bumi\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 27, "text": "وَقَالَ مُوسَىٰۤ إِنِّی عُذۡتُ بِرَبِّی وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرࣲ لَّا یُؤۡمِنُ بِیَوۡمِ ٱلۡحِسَابِ ۝٢٧", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "وقال موسى لفرعون وملئه: إني استجرت بربي وربكم- أيها القوم- من كل مستكبر عن توحيد الله وطاعته، لا يؤمن بيوم يحاسب الله فيه خلقه.", "isBasmala": false, "translation_en": "Moses said, \"I have sought the protection of my Lord and your Lord, from every tyrant who does not believe in the Day of Account.\"", "translation_id": "Dan Musa berkata: \"Sesungguhnya aku berlindung kepada Tuhanku dan Tuhanmu dari setiap orang yang menyombongkan diri yang tidak beriman kepada hari berhisab\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 28, "text": "وَقَالَ رَجُلࣱ مُّؤۡمِنࣱ مِّنۡ ءَالِ فِرۡعَوۡنَ یَكۡتُمُ إِیمَـٰنَهُۥۤ أَتَقۡتُلُونَ رَجُلًا أَن یَقُولَ رَبِّیَ ٱللَّهُ وَقَدۡ جَاۤءَكُم بِٱلۡبَیِّنَـٰتِ مِن رَّبِّكُمۡۖ وَإِن یَكُ كَـٰذِبࣰا فَعَلَیۡهِ كَذِبُهُۥۖ وَإِن یَكُ صَادِقࣰا یُصِبۡكُم بَعۡضُ ٱلَّذِی یَعِدُكُمۡۖ إِنَّ ٱللَّهَ لَا یَهۡدِی مَنۡ هُوَ مُسۡرِفࣱ كَذَّابࣱ ۝٢٨", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "وقال رجل مؤمن بالله من آل فرعون، يكتم إيمانه منكرًا على قومه: كيف تستحلون قَتْلَ رجل لا جرم له عندكم إلا أن يقول ربي الله، وقد جاءكم بالبراهين القاطعة مِن ربكم على صِدْق ما يقول؟ فإن يك موسى كاذبًا فإنَّ وبالَ كذبه عائد عليه وحده، وإن يك صادقًا لحقكم بعض الذي يتوعَّدكم به، إن الله لا يوفق للحق مَن هو متجاوز للحد، بترك الحق والإقبال على الباطل، كذَّاب بنسبته ما أسرف فيه إلى الله.", "isBasmala": false, "translation_en": "A believing man from Pharaoh's family, who had concealed his faith, said, \"Are you going to kill a man for saying, `My Lord is God,' and he has brought you clear proofs from your Lord? If he is a liar, his lying will rebound upon him; but if he is truthful, then some of what he promises you will befall you. God does not guide the extravagant imposter.", "translation_id": "Dan seorang laki-laki yang beriman di antara pengikut-pengikut Fir'aun yang menyembunyikan imannya berkata: \"Apakah kamu akan membunuh seorang laki-laki karena dia menyatakan: \"Tuhanku ialah Allah padahal dia telah datang kepadamu dengan membawa keterangan-keterangan dari Tuhanmu. Dan jika ia seorang pendusta maka dialah yang menanggung (dosa) dustanya itu; dan jika ia seorang yang benar niscaya sebagian (bencana) yang diancamkannya kepadamu akan menimpamu\". Sesungguhnya Allah tidak menunjuki orang-orang yang melampaui batas lagi pendusta.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 29, "text": "یَـٰقَوۡمِ لَكُمُ ٱلۡمُلۡكُ ٱلۡیَوۡمَ ظَـٰهِرِینَ فِی ٱلۡأَرۡضِ فَمَن یَنصُرُنَا مِنۢ بَأۡسِ ٱللَّهِ إِن جَاۤءَنَاۚ قَالَ فِرۡعَوۡنُ مَاۤ أُرِیكُمۡ إِلَّا مَاۤ أَرَىٰ وَمَاۤ أَهۡدِیكُمۡ إِلَّا سَبِیلَ ٱلرَّشَادِ ۝٢٩", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "يا قوم لكم السلطان اليوم ظاهرين في أرض \"مصر \" على رعيتكم من بني إسرائيل وغيرهم، فمَن يدفع عنا عذاب الله إن حلَّ بنا؟ قال فرعون لقومه مجيبًا: ما أريكم- أيها الناس- من الرأي والنصيحة إلا ما أرى لنفسي ولكم صلاحًا وصوابًا، وما أدعوكم إلا إلى طريق الحق والصواب.", "isBasmala": false, "translation_en": "O my people! Yours is the dominion today, supreme in the land; but who will help us against God's might, should it fall upon us?\" Pharaoh said, \"I do not show you except what I see, and I do not guide you except to the path of prudence.\"", "translation_id": "(Musa berkata): \"Hai kaumku, untukmulah kerajaan pada hari ini dengan berkuasa di muka bumi. Siapakah yang akan menolong kita dari azab Allah jika azab itu menimpa kita!\" Fir'aun berkata: \"Aku tidak mengemukakan kepadamu, melainkan apa yang aku pandang baik; dan aku tiada menunjukkan kepadamu selain jalan yang benar\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 30, "text": "وَقَالَ ٱلَّذِیۤ ءَامَنَ یَـٰقَوۡمِ إِنِّیۤ أَخَافُ عَلَیۡكُم مِّثۡلَ یَوۡمِ ٱلۡأَحۡزَابِ ۝٣٠", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "وقال الرجل المؤمن من آل فرعون لفرعون وملئه واعظًا ومحذرًا: إني أخاف عليكم إن قتلتم موسى، مثل يوم الأحزاب الذين تحزَّبوا على أنبيائهم.", "isBasmala": false, "translation_en": "The one who had believed said, \"O my people, I fear for you the like of the day of the confederates.", "translation_id": "Dan orang yang beriman itu berkata: \"Hai kaumku, sesungguhnya aku khawatir kamu akan ditimpa (bencana) seperti peristiwa kehancuran golongan yang bersekutu.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 31, "text": "مِثۡلَ دَأۡبِ قَوۡمِ نُوحࣲ وَعَادࣲ وَثَمُودَ وَٱلَّذِینَ مِنۢ بَعۡدِهِمۡۚ وَمَا ٱللَّهُ یُرِیدُ ظُلۡمࣰا لِّلۡعِبَادِ ۝٣١", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "مثلَ عادة قوم نوح وعاد وثمود ومَن جاء بعدهم في الكفر والتكذيب، أهلكهم الله بسبب ذلك. وما الله سبحانه يريد ظلمًا للعباد، فيعذبهم بغير ذنب أذنبوه. تعالى الله عن الظلم والنقص علوًا كبيرًا.", "isBasmala": false, "translation_en": "Like the fate of the people of Noah, and Aad, and Thamood, and those after them. God wants no injustice for the servants.", "translation_id": "(Yakni) seperti keadaan kaum Nuh, 'Aad, Tsamud dan orang-orang yang datang sesudah mereka. Dan Allah tidak menghendaki berbuat kezaliman terhadap hamba-hamba-Nya.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 32, "text": "وَیَـٰقَوۡمِ إِنِّیۤ أَخَافُ عَلَیۡكُمۡ یَوۡمَ ٱلتَّنَادِ ۝٣٢", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "ويا قوم إني أخاف عليكم عقاب يوم القيامة، يوم ينادي فيه بعض الناس بعضًا؛ من هول الموقف ذلك اليوم.", "isBasmala": false, "translation_en": "O my people, I fear for you the Day of Calling Out.", "translation_id": "Hai kaumku, sesungguhnya aku khawatir terhadapmu akan siksaan hari panggil-memanggil.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 33, "text": "یَوۡمَ تُوَلُّونَ مُدۡبِرِینَ مَا لَكُم مِّنَ ٱللَّهِ مِنۡ عَاصِمࣲۗ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادࣲ ۝٣٣", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "يوم تولون ذاهبين هاربين، ما لكم من الله من مانع يمنعكم وناصر ينصركم. ومَن يخذله الله ولم يوفقه إلى رشده، فما له من هاد يهديه إلى الحق والصواب.", "isBasmala": false, "translation_en": "The Day when you will turn and flee, having no defender against God. Whomever God misguides has no guide.\"", "translation_id": "(yaitu) hari (ketika) kamu (lari) berpaling ke belakang, tidak ada bagimu seorangpun yang menyelamatkan kamu dari (azab) Allah, dan siapa yang disesatkan Allah, niscaya tidak ada baginya seorangpun yang akan memberi petunjuk.", "manzil": 6, "manzil_display": ""}], "471": [{"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 34, "text": "وَلَقَدۡ جَاۤءَكُمۡ یُوسُفُ مِن قَبۡلُ بِٱلۡبَیِّنَـٰتِ فَمَا زِلۡتُمۡ فِی شَكࣲّ مِّمَّا جَاۤءَكُم بِهِۦۖ حَتَّىٰۤ إِذَا هَلَكَ قُلۡتُمۡ لَن یَبۡعَثَ ٱللَّهُ مِنۢ بَعۡدِهِۦ رَسُولࣰاۚ كَذَ ٰلِكَ یُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفࣱ مُّرۡتَابٌ ۝٣٤", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "ولقد أرسل الله إليكم النبيَّ الكريم يوسف بن يعقوب عليهما السلام من قبل موسى، بالدلائل الواضحة على صدقه، وأمركم بعبادة الله وحده لا شريك له، فما زلتم مرتابين مما جاءكم به في حياته، حتى إذا مات ازداد شككم وشرككم، وقلتم: إن الله لن يرسل من بعده رسولا، مثل ذلك الضلال يُضِلُّ الله كل متجاوز للحق، شاكٍّ في وحدانية الله تعالى، فلا يوفقه إلى الهدى والرشاد.", "isBasmala": false, "translation_en": "Joseph had come to you with clear revelations, but you continued to doubt what he came to you with. Until, when he perished, you said, \"God will never send a messenger after him.\" Thus God leads astray the outrageous skeptic.", "translation_id": "Dan sesungguhnya telah datang Yusuf kepadamu dengan membawa keterangan-keterangan, tetapi kamu senantiasa dalam keraguan tentang apa yang dibawanya kepadamu, hingga ketika dia meninggal, kamu berkata: \"Allah tidak akan mengirim seorang (rasulpun) sesudahnya. Demikianlah Allah menyesatkan orang-orang yang melampaui batas dan ragu-ragu.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 35, "text": "ٱلَّذِینَ یُجَـٰدِلُونَ فِیۤ ءَایَـٰتِ ٱللَّهِ بِغَیۡرِ سُلۡطَـٰنٍ أَتَىٰهُمۡۖ كَبُرَ مَقۡتًا عِندَ ٱللَّهِ وَعِندَ ٱلَّذِینَ ءَامَنُوا۟ۚ كَذَ ٰلِكَ یَطۡبَعُ ٱللَّهُ عَلَىٰ كُلِّ قَلۡبِ مُتَكَبِّرࣲ جَبَّارࣲ ۝٣٥", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "الذين يخاصمون في آيات الله وحججه لدفعها من غير أن يكون لديهم حجة مقبولة، كَبُر ذلك الجدال مقتًا عند الله وعند الذين آمنوا، كما خَتَم بالضلال وحَجَبَ عن الهدى قلوب هؤلاء المخاصمين، يختم الله على قلب كل مستكبر عن توحيد الله وطاعته، جبار بكثرة ظلمه وعدوانه.", "isBasmala": false, "translation_en": "Those who argue against God's revelations, without any proof having come to them-a heinous sin in the sight of God, and of those who believe. Thus God seals the heart of every proud bully.", "translation_id": "(Yaitu) orang-orang yang memperdebatkan ayat-ayat Allah tanpa alasan yang sampai kepada mereka. Amat besar kemurkaan (bagi mereka) di sisi Allah dan di sisi orang-orang yang beriman. Demikianlah Allah mengunci mati hati orang yang sombong dan sewenang-wenang.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 36, "text": "وَقَالَ فِرۡعَوۡنُ یَـٰهَـٰمَـٰنُ ٱبۡنِ لِی صَرۡحࣰا لَّعَلِّیۤ أَبۡلُغُ ٱلۡأَسۡبَـٰبَ ۝٣٦", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "وقال فرعون مكذِّبًا لموسى في دعوته إلى الإقرار برب العالمين والتسليم له: يا هامان ابْنِ لي بنًاء عظيمًا؛ لعلي أبلغ أبواب السماوات وما يوصلني إليها، فأنظر إلى إله موسى بنفسي، وإني لأظن موسى كاذبًا في دعواه أن لنا ربًا، وأنه فوق السماوات، وهكذا زُيَّن لفرعون عمله السيِّئ فرآه حسنًا، وصُدَّ عن سبيل الحق؛ بسبب الباطل الذي زُيِّن له، وما احتيال فرعون وتدبيره لإيهام الناس أنه محق، وموسى مبطل إلا في خسار وبوار، لا يفيده إلا الشقاء في الدنيا والآخرة.", "isBasmala": false, "translation_en": "And Pharaoh said, \"O Hamaan, build me a tower, that I may reach the pathways.", "translation_id": "Dan berkatalah Fir'aun: \"Hai Haman, buatkanlah bagiku sebuah bangunan yang tinggi supaya aku sampai ke pintu-pintu,", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 37, "text": "أَسۡبَـٰبَ ٱلسَّمَـٰوَ ٰتِ فَأَطَّلِعَ إِلَىٰۤ إِلَـٰهِ مُوسَىٰ وَإِنِّی لَأَظُنُّهُۥ كَـٰذِبࣰاۚ وَكَذَ ٰلِكَ زُیِّنَ لِفِرۡعَوۡنَ سُوۤءُ عَمَلِهِۦ وَصُدَّ عَنِ ٱلسَّبِیلِۚ وَمَا كَیۡدُ فِرۡعَوۡنَ إِلَّا فِی تَبَابࣲ ۝٣٧", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "وقال فرعون مكذِّبًا لموسى في دعوته إلى الإقرار برب العالمين والتسليم له: يا هامان ابْنِ لي بنًاء عظيمًا؛ لعلي أبلغ أبواب السماوات وما يوصلني إليها، فأنظر إلى إله موسى بنفسي، وإني لأظن موسى كاذبًا في دعواه أن لنا ربًا، وأنه فوق السماوات، وهكذا زُيَّن لفرعون عمله السيِّئ فرآه حسنًا، وصُدَّ عن سبيل الحق؛ بسبب الباطل الذي زُيِّن له، وما احتيال فرعون وتدبيره لإيهام الناس أنه محق، وموسى مبطل إلا في خسار وبوار، لا يفيده إلا الشقاء في الدنيا والآخرة.", "isBasmala": false, "translation_en": "The pathways of the heavens, so that I may glance at the God of Moses; though I think he is lying.\" Thus Pharaoh's evil deeds were made to appear good to him, and he was averted from the path. Pharaoh's guile was only in defeat.", "translation_id": "(yaitu) pintu-pintu langit, supaya aku dapat melihat Tuhan Musa dan sesungguhnya aku memandangnya seorang pendusta\". Demikianlah dijadikan Fir'aun memandang baik perbuatan yang buruk itu, dan dia dihalangi dari jalan (yang benar); dan tipu daya Fir'aun itu tidak lain hanyalah membawa kerugian.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 38, "text": "وَقَالَ ٱلَّذِیۤ ءَامَنَ یَـٰقَوۡمِ ٱتَّبِعُونِ أَهۡدِكُمۡ سَبِیلَ ٱلرَّشَادِ ۝٣٨", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "وقال الذي آمن معيدًا نصيحته لقومه: يا قوم اتبعون أهدكم طريق الرشد والصواب.", "isBasmala": false, "translation_en": "The one who had believed said, \"O my people, follow me, and I will guide you to the path of rectitude.\"", "translation_id": "Orang yang beriman itu berkata: \"Hai kaumku, ikutilah aku, aku akan menunjukkan kepadamu jalan yang benar.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 39, "text": "یَـٰقَوۡمِ إِنَّمَا هَـٰذِهِ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا مَتَـٰعࣱ وَإِنَّ ٱلۡـَٔاخِرَةَ هِیَ دَارُ ٱلۡقَرَارِ ۝٣٩", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "يا قوم إن هذه الحياة الدنيا حياة يتنعَّم الناس فيها قليلا ثم تنقطع وتزول، فينبغي ألا تَرْكَنوا إليها، وإن الدار الآخرة بما فيها من النعيم المقيم هي محل الإقامة التي تستقرون فيها، فينبغي لكم أن تؤثروها، وتعملوا لها العمل الصالح الذي يُسعِدكم فيها.", "isBasmala": false, "translation_en": "\"O my people, the life of this world is nothing but fleeting enjoyment, but the Hereafter is the Home of Permanence.", "translation_id": "Hai kaumku, sesungguhnya kehidupan dunia ini hanyalah kesenangan (sementara) dan sesungguhnya akhirat itulah negeri yang kekal.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 40, "text": "مَنۡ عَمِلَ سَیِّئَةࣰ فَلَا یُجۡزَىٰۤ إِلَّا مِثۡلَهَاۖ وَمَنۡ عَمِلَ صَـٰلِحࣰا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ فَأُو۟لَـٰۤىِٕكَ یَدۡخُلُونَ ٱلۡجَنَّةَ یُرۡزَقُونَ فِیهَا بِغَیۡرِ حِسَابࣲ ۝٤٠", "juz": 24, "hizb": "(*¾ ح 47*)", "tafsir": "من عصى الله في حياته وانحرف عن طريق الهدى، فلا يُجْزى في الآخرة إلا عقابًا يساوي معصيته، ومَن أطاع الله وعمل صالحًا بامتثال أوامره واجتناب نواهيه، ذكرًا كان أو أنثى، وهو مؤمن بالله موحد له، فأولئك يدخلون الجنة، يرزقهم الله فيها من ثمارها ونعيمها ولذاتها بغير حساب.", "isBasmala": false, "translation_en": "Whoever commits a sin will be repaid only with its like. But whoever works righteousness, whether male or female, and is a believer-these will enter Paradise, where they will be provided for without account.", "translation_id": "Barangsiapa mengerjakan perbuatan jahat, maka dia tidak akan dibalasi melainkan sebanding dengan kejahatan itu. Dan barangsiapa mengerjakan amal yang saleh baik laki-laki maupun perempuan sedang ia dalam keadaan beriman, maka mereka akan masuk surga, mereka diberi rezeki di dalamnya tanpa hisab.", "manzil": 6, "manzil_display": ""}], "472": [{"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 41, "text": "۞ وَیَـٰقَوۡمِ مَا لِیۤ أَدۡعُوكُمۡ إِلَى ٱلنَّجَوٰةِ وَتَدۡعُونَنِیۤ إِلَى ٱلنَّارِ ۝٤١", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "ويا قوم كيف أدعوكم إلى الإيمان بالله واتباع رسوله موسى، وهي دعوة تنتهي بكم إلى الجنة والبعد عن أهوال النار، وأنتم تدعونني إلى عمل يؤدي إلى عذاب الله وعقوبته في النار؟", "isBasmala": false, "translation_en": "O my people, how is it that I call you to salvation, and you call me to the Fire?", "translation_id": "Hai kaumku, bagaimanakah kamu, aku menyeru kamu kepada keselamatan, tetapi kamu menyeru aku ke neraka?", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 42, "text": "تَدۡعُونَنِی لِأَكۡفُرَ بِٱللَّهِ وَأُشۡرِكَ بِهِۦ مَا لَیۡسَ لِی بِهِۦ عِلۡمࣱ وَأَنَا۠ أَدۡعُوكُمۡ إِلَى ٱلۡعَزِیزِ ٱلۡغَفَّـٰرِ ۝٤٢", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "تدعونني لأكفر بالله، وأشرك به ما ليس لي به علم أنه يستحق العبادة من دونه- وهذا من أكبر الذنوب وأقبحها- وأنا أدعوكم إلى الطريق الموصل إلى الله العزيز في انتقامه، الغفار لمن تاب إليه بعد معصيته.", "isBasmala": false, "translation_en": "You call me to reject God, and to associate with Him what I have no knowledge of, while I call you to the Mighty Forgiver.", "translation_id": "(Kenapa) kamu menyeruku supaya kafir kepada Allah dan mempersekutukan-Nya dengan apa yang tidak kuketahui padahal aku menyeru kamu (beriman) kepada Yang Maha Perkasa lagi Maha Pengampun?", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 43, "text": "لَا جَرَمَ أَنَّمَا تَدۡعُونَنِیۤ إِلَیۡهِ لَیۡسَ لَهُۥ دَعۡوَةࣱ فِی ٱلدُّنۡیَا وَلَا فِی ٱلۡـَٔاخِرَةِ وَأَنَّ مَرَدَّنَاۤ إِلَى ٱللَّهِ وَأَنَّ ٱلۡمُسۡرِفِینَ هُمۡ أَصۡحَـٰبُ ٱلنَّارِ ۝٤٣", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "حقًا أن ما تدعونني إلى الاعتقاد به لا يستحق الدعوة إليه، ولا يُلجأ إليه في الدنيا ولا في الآخرة لعجزه ونقصه، واعلموا أن مصير الخلائق كلها إلى الله سبحانه، وهو يجازي كل عامل بعمله، وأن الذين تعدَّوا حدوده بالمعاصي وسفك الدماء والكفر هم أهل النار.", "isBasmala": false, "translation_en": "Without a doubt, what you call me to has no say in this world, or in the Hereafter; and our turning back is to God; and the transgressors are the inmates of the Fire.", "translation_id": "Sudah pasti bahwa apa yang kamu seru supaya aku (beriman) kepadanya tidak dapat memperkenankan seruan apapun baik di dunia maupun di akhirat. Dan sesungguhnya kita kembali kepada Allah dan sesungguhnya orang-orang yang melampaui batas, mereka itulah penghuni neraka.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 44, "text": "فَسَتَذۡكُرُونَ مَاۤ أَقُولُ لَكُمۡۚ وَأُفَوِّضُ أَمۡرِیۤ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِیرُۢ بِٱلۡعِبَادِ ۝٤٤", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "فلما نصحهم ولم يطيعوه قال لهم: فستذكرون أني نصحت لكم وذكَّرتكم، وسوف تندمون حيث لا ينفع الندم، وألجأ إلى الله، وأعتصم به، وأتوكل عليه. إن الله سبحانه وتعالى بصير بأحوال العباد، وما يستحقونه من جزاء، لا يخفى عليه شيء منها.", "isBasmala": false, "translation_en": "You will remember what I am telling you, so I commit my case to God. God is Observant of the servants.\"", "translation_id": "Kelak kamu akan ingat kepada apa yang kukatakan kepada kamu. Dan aku menyerahkan urusanku kepada Allah. Sesungguhnya Allah Maha Melihat akan hamba-hamba-Nya\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 45, "text": "فَوَقَىٰهُ ٱللَّهُ سَیِّـَٔاتِ مَا مَكَرُوا۟ۖ وَحَاقَ بِـَٔالِ فِرۡعَوۡنَ سُوۤءُ ٱلۡعَذَابِ ۝٤٥", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "فوقى الله سبحانه ذلك الرجل المؤمن الموفَّق عقوبات مكر فرعون وآله، وحلَّ بهم سوء العذاب حيث أغرقهم الله عن آخرهم.", "isBasmala": false, "translation_en": "So God protected him from the evils of their scheming, while a terrible torment besieged Pharaoh's clan.", "translation_id": "Maka Allah memeliharanya dari kejahatan tipu daya mereka, dan Fir'aun beserta kaumnya dikepung oleh azab yang amat buruk.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 46, "text": "ٱلنَّارُ یُعۡرَضُونَ عَلَیۡهَا غُدُوࣰّا وَعَشِیࣰّاۚ وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ أَدۡخِلُوۤا۟ ءَالَ فِرۡعَوۡنَ أَشَدَّ ٱلۡعَذَابِ ۝٤٦", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "لقد أصابهم الغرق أولا وهلكوا، ثم يُعذَّبون في قبورهم حيث النار، يُعرضون عليها صباحًا ومساء إلى وقت الحساب، ويوم تقوم الساعة يقال: أدخلوا آل فرعون النار؛ جزاء ما اقترفوه من أعمال السوء. وهذه الآية أصل في إثبات عذاب القبر.", "isBasmala": false, "translation_en": "The Fire. They will be exposed to it morning and evening. And on the Day the Hour takes place: \"Admit the clan of Pharaoh to the most intense agony.\"", "translation_id": "Kepada mereka dinampakkan neraka pada pagi dan petang, dan pada hari terjadinya Kiamat. (Dikatakan kepada malaikat): \"Masukkanlah Fir'aun dan kaumnya ke dalam azab yang sangat keras\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 47, "text": "وَإِذۡ یَتَحَاۤجُّونَ فِی ٱلنَّارِ فَیَقُولُ ٱلضُّعَفَـٰۤؤُا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوۤا۟ إِنَّا كُنَّا لَكُمۡ تَبَعࣰا فَهَلۡ أَنتُم مُّغۡنُونَ عَنَّا نَصِیبࣰا مِّنَ ٱلنَّارِ ۝٤٧", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "وإذ يتخاصم أهل النار، ويعاتب بعضهم بعضًا، فيحتجُّ الأتباع المقلدون على رؤسائهم المستكبرين الذين أضلُّوهم، وزيَّنوا لهم طريق الشقاء، قائلين لهم: هل أنتم مغنون عنا نصيبًا من النار بتحملكم قسطًا من عذابنا؟", "isBasmala": false, "translation_en": "As they quarrel in the Fire, the weak will say to those who were arrogant, \"We were followers of yours; will you then spare us a portion of the Fire?\"", "translation_id": "Dan (ingatlah), ketika mereka berbantah-bantah dalam neraka, maka orang-orang yang lemah berkata kepada orang-orang yang menyombongkan diri: \"Sesungguhnya kami adalah pengikut-pengikutmu, maka dapatkah kamu menghindarkan dari kami sebahagian azab api neraka?\"", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 48, "text": "قَالَ ٱلَّذِینَ ٱسۡتَكۡبَرُوۤا۟ إِنَّا كُلࣱّ فِیهَاۤ إِنَّ ٱللَّهَ قَدۡ حَكَمَ بَیۡنَ ٱلۡعِبَادِ ۝٤٨", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "قال الرؤساء المستكبرون مبيِّنين عجزهم: لا نتحمل عنكم شيئًا من عذاب النار، وكلُّنا فيها، لا خلاصَ لنا منها، إن الله قد قسم بيننا العذاب بقَدْر ما يستحق كلٌّ منا بقضائه العادل.", "isBasmala": false, "translation_en": "Those who were arrogant will say, \"We are all in it; God has judged between the servants.\"", "translation_id": "Orang-orang yang menyombongkan diri menjawab: \"Sesungguhnya kita semua sama-sama dalam neraka karena sesungguhnya Allah telah menetapkan keputusan antara hamba-hamba-(Nya)\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 49, "text": "وَقَالَ ٱلَّذِینَ فِی ٱلنَّارِ لِخَزَنَةِ جَهَنَّمَ ٱدۡعُوا۟ رَبَّكُمۡ یُخَفِّفۡ عَنَّا یَوۡمࣰا مِّنَ ٱلۡعَذَابِ ۝٤٩", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "وقال الذين في النار من المستكبرين والضعفاء لخزنة جهنم: ادعوا ربكم يُخَفِّفْ عنا يومًا واحدًا من العذاب؛ كي تحصل لنا بعض الراحة.", "isBasmala": false, "translation_en": "And those in the Fire will say to the keepers of Hell, \"Call to your Lord to lessen our suffering for one day.\"", "translation_id": "Dan orang-orang yang berada dalam neraka berkata kepada penjaga-penjaga neraka Jahannam: \"Mohonkanlah kepada Tuhanmu supaya Dia meringankan azab dari kami barang sehari\".", "manzil": 6, "manzil_display": ""}], "473": [{"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 50, "text": "قَالُوۤا۟ أَوَ لَمۡ تَكُ تَأۡتِیكُمۡ رُسُلُكُم بِٱلۡبَیِّنَـٰتِۖ قَالُوا۟ بَلَىٰۚ قَالُوا۟ فَٱدۡعُوا۟ۗ وَمَا دُعَـٰۤؤُا۟ ٱلۡكَـٰفِرِینَ إِلَّا فِی ضَلَـٰلٍ ۝٥٠", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "قال خزنة جهنم لهم توبيخًا: هذا الدعاء لا ينفعكم في شيء، أولم تأتكم رسلكم بالحجج الواضحة من الله فكذبتموهم؟ فاعترف الجاحدون بذلك وقالوا: بلى. فتبرأ خزنة جهنم منهم وقالوا: نحن لا ندعو لكم، ولا نشفع فيكم، فادعوا أنتم، ولكن هذا الدعاء لا يغني شيئًا؛ لأنكم كافرون. وما دعاء الكافرين إلا في ضياع لا يُقبل، ولا يُستجاب.", "isBasmala": false, "translation_en": "They will say, \"Did not your messengers come to you with clear signs?\" They will say, \"Yes.\" They will say, \"Then pray, but the prayers of the disbelievers will always be in vain.\"", "translation_id": "Penjaga Jahannam berkata: \"Dan apakah belum datang kepada kamu rasul-rasulmu dengan membawa keterangan-keterangan?\" Mereka menjawab: \"Benar, sudah datang\". Penjaga-penjaga Jahannam berkata: \"Berdoalah kamu\". Dan doa orang-orang kafir itu hanyalah sia-sia belaka.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 51, "text": "إِنَّا لَنَنصُرُ رُسُلَنَا وَٱلَّذِینَ ءَامَنُوا۟ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَیَوۡمَ یَقُومُ ٱلۡأَشۡهَـٰدُ ۝٥١", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "إنَّا لننصر رسلنا ومَن تبعهم من المؤمنين، ونؤيدهم على مَن آذاهم في حياتهم الدنيا، ويوم القيامة، يوم تشهد فيه الملائكة والأنبياء والمؤمنون على الأمم التي كذَّبت رسلها، فتشهد بأن الرسل قد بلَّغوا رسالات ربهم، وأن الأمم كذَّبتهم.", "isBasmala": false, "translation_en": "Most surely We will support Our messengers and those who believe, in this life, and on the Day the witnesses arise.", "translation_id": "Sesungguhnya Kami menolong rasul-rasul Kami dan orang-orang yang beriman dalam kehidupan dunia dan pada hari berdirinya saksi-saksi (hari kiamat),", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 52, "text": "یَوۡمَ لَا یَنفَعُ ٱلظَّـٰلِمِینَ مَعۡذِرَتُهُمۡۖ وَلَهُمُ ٱللَّعۡنَةُ وَلَهُمۡ سُوۤءُ ٱلدَّارِ ۝٥٢", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "يوم الحساب لا ينتفع الكافرون الذين تعدَّوا حدود الله بما يقدِّمونه من عذر لتكذيبهم رسل الله، ولهم الطرد من رحمة الله، ولهم الدار السيئة في الآخرة، وهي النار.", "isBasmala": false, "translation_en": "The Day when their excuses will not profit the wrongdoers, and the curse will be upon them, and they will have the Home of Misery.", "translation_id": "(yaitu) hari yang tidak berguna bagi orang-orang zalim permintaan maafnya dan bagi merekalah laknat dan bagi merekalah tempat tinggal yang buruk.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 53, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡهُدَىٰ وَأَوۡرَثۡنَا بَنِیۤ إِسۡرَ ٰۤءِیلَ ٱلۡكِتَـٰبَ ۝٥٣", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "ولقد آتينا موسى ما يهدي إلى الحق من التوراة والمعجزات، وجعلنا بني إسرائيل يتوارثون التوراة خلفًا عن سلف، هادية إلى سبيل الرشاد، وموعظة لأصحاب العقول السليمة.", "isBasmala": false, "translation_en": "We gave Moses guidance, and made the Children of Israel inherit the Scripture.", "translation_id": "Dan sesungguhnya telah Kami berikan petunjuk kepada Musa; dan Kami wariskan Taurat kepada Bani Israil,", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 54, "text": "هُدࣰى وَذِكۡرَىٰ لِأُو۟لِی ٱلۡأَلۡبَـٰبِ ۝٥٤", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "ولقد آتينا موسى ما يهدي إلى الحق من التوراة والمعجزات، وجعلنا بني إسرائيل يتوارثون التوراة خلفًا عن سلف، هادية إلى سبيل الرشاد، وموعظة لأصحاب العقول السليمة.", "isBasmala": false, "translation_en": "A guide and a reminder for those endowed with reason.", "translation_id": "untuk menjadi petunjuk dan peringatan bagi orang-orang yang berfikir.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 55, "text": "فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِٱلۡعَشِیِّ وَٱلۡإِبۡكَـٰرِ ۝٥٥", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "فاصبر -أيها الرسول- على أذى المشركين، فقد وعدناك بإعلاء كلمتك، ووعْدُنا حق لا يتخلف، واستغفر لذنبك، ودُمْ على تنزيه ربك عمَّا لا يليق به، في آخر النهار وأوله.", "isBasmala": false, "translation_en": "So be patient. The promise of God is true. And ask forgiveness for your sin, and proclaim the praise of your Lord evening and morning.", "translation_id": "Maka bersabarlah kamu, karena sesungguhnya janji Allah itu benar, dan mohonlah ampunan untuk dosamu dan bertasbihlah seraya memuji Tuhanmu pada waktu petang dan pagi.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 56, "text": "إِنَّ ٱلَّذِینَ یُجَـٰدِلُونَ فِیۤ ءَایَـٰتِ ٱللَّهِ بِغَیۡرِ سُلۡطَـٰنٍ أَتَىٰهُمۡ إِن فِی صُدُورِهِمۡ إِلَّا كِبۡرࣱ مَّا هُم بِبَـٰلِغِیهِۚ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡبَصِیرُ ۝٥٦", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "إن الذين يدفعون الحق بالباطل، ويردُّون الحجج الصحيحة بالشُّبَه الفاسدة بلا برهان ولا حجة من الله، ليس في صدور هؤلاء إلا تكبر عن الحق؛ حسدًا منهم على الفضل الذي آتاه الله نبيه، وكرامة النبوة التي أكرمه بها، وهو أمر ليسوا بمدركيه ولا نائليه، فاعتصم بالله من شرهم؛ إنه هو السميع لأقوالهم، البصير بأفعالهم، وسيجازيهم عليها.", "isBasmala": false, "translation_en": "Those who dispute regarding God's revelations without any authority having come to them-there is nothing in their hearts but the feeling of greatness, which they will never attain. So seek refuge in God; for He is the All-Hearing, the All-Seeing.", "translation_id": "Sesungguhhnya orang-orang yang memperdebatkan tentang ayat-ayat Allah tanpa alasan yang sampai kepada mereka tidak ada dalam dada mereka melainkan hanyalah (keinginan akan) kebesaran yang mereka sekali-kali tiada akan mencapainya, maka mintalah perlindungan kepada Allah. Sesungguhnya Dia Maha Mendengar lagi Maha Melihat.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 57, "text": "لَخَلۡقُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ أَكۡبَرُ مِنۡ خَلۡقِ ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٥٧", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "لَخَلْق الله السموات والأرض أكبر من خَلْق الناس وإعادتهم بعد موتهم، ولكن أكثر الناس لا يعلمون أن خلق جميع ذلك هيِّن على الله.", "isBasmala": false, "translation_en": "Certainly the creation of the heavens and the earth is greater than the creation of humanity, but most people do not know.", "translation_id": "Sesungguhnya penciptaan langit dan bumi lebih besar daripada penciptaan manusia akan tetapi kebanyakan manusia tidak mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 58, "text": "وَمَا یَسۡتَوِی ٱلۡأَعۡمَىٰ وَٱلۡبَصِیرُ وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَلَا ٱلۡمُسِیۤءُۚ قَلِیلࣰا مَّا تَتَذَكَّرُونَ ۝٥٨", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "وما يستوي الأعمى والبصير، وكذلك لا يستوي المؤمنون الذين يُقِرُّون بأن الله هو الإله الحق لا شريك له، ويستجيبون لرسله ويعملون بشرعه، والجاحدون الذين ينكرون أن الله هو الإله الحق، ويكذبون رسله ولا يعملون بشرعه. قليلا ما تتذكرون -أيها الناس- حجج الله، فتعتبرون، وتتعظون بها.", "isBasmala": false, "translation_en": "Not equal are the blind and the seeing. Nor are those who believe and work righteousness equal to the sinners. How little you reflect.", "translation_id": "Dan tidaklah sama orang yang buta dengan orang yang melihat, dan tidaklah (pula sama) orang-orang yang beriman serta mengerjakan amal saleh dengan orang-orang yang durhaka. Sedikit sekali kamu mengambil pelajaran.", "manzil": 6, "manzil_display": ""}], "474": [{"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 59, "text": "إِنَّ ٱلسَّاعَةَ لَـَٔاتِیَةࣱ لَّا رَیۡبَ فِیهَا وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یُؤۡمِنُونَ ۝٥٩", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "إن الساعة لآتية لا شك فيها، فأيقنوا بمجيئها، كما أخبرتْ بذلك الرسل، ولكن أكثر الناس لا يُصَدِّقون بمجيئها، ولا يعملون لها.", "isBasmala": false, "translation_en": "Indeed, the Hour is coming; there is no doubt about it; but most people do not believe.", "translation_id": "Sesungguhnya hari kiamat pasti akan datang, tidak ada keraguan tentangnya, akan tetapi kebanyakan manusia tiada beriman.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 60, "text": "وَقَالَ رَبُّكُمُ ٱدۡعُونِیۤ أَسۡتَجِبۡ لَكُمۡۚ إِنَّ ٱلَّذِینَ یَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِی سَیَدۡخُلُونَ جَهَنَّمَ دَاخِرِینَ ۝٦٠", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "وقال ربكم- أيها العباد-: ادعوني وحدي وخصُّوني بالعبادة أستجب لكم، إن الذين يتكبرون عن إفرادي بالعبودية والألوهية، سيدخلون جهنم صاغرين حقيرين.", "isBasmala": false, "translation_en": "Your Lord has said, \"Pray to Me, and I will respond to you. But those who are too proud to worship Me will enter Hell forcibly.\"", "translation_id": "Dan Tuhanmu berfirman: \"Berdoalah kepada-Ku, niscaya akan Kuperkenankan bagimu. Sesungguhnya orang-orang yang menyombongkan diri dari menyembah-Ku akan masuk neraka Jahannam dalam keadaan hina dina\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 61, "text": "ٱللَّهُ ٱلَّذِی جَعَلَ لَكُمُ ٱلَّیۡلَ لِتَسۡكُنُوا۟ فِیهِ وَٱلنَّهَارَ مُبۡصِرًاۚ إِنَّ ٱللَّهَ لَذُو فَضۡلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَشۡكُرُونَ ۝٦١", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "الله وحده هو الذي جعل لكم الليل؛ لتسكنوا فيه، وتحققوا راحتكم، والنهار مضيئًا؛ لتُصَرِّفوا فيه أمور معاشكم. إن الله لذو فضل عظيم على الناس، ولكن أكثرهم لا يشكرون له بالطاعة وإخلاص العبادة.", "isBasmala": false, "translation_en": "It is God Who made the night for you, that you may rest therein; and the day allowing sight. God is gracious towards the people, but most people do not give thanks.", "translation_id": "Allah-lah yang menjadikan malam untuk kamu supaya kamu beristirahat padanya; dan menjadikan siang terang benderang. Sesungguhnya Allah benar-benar mempunyal karunia yang dilimpahkan atas manusia, akan tetapi kebanyakan manusia tidak bersyukur.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 62, "text": "ذَ ٰلِكُمُ ٱللَّهُ رَبُّكُمۡ خَـٰلِقُ كُلِّ شَیۡءࣲ لَّاۤ إِلَـٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ ۝٦٢", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "الذي أنعم عليكم بهذه النعم إنما هو ربكم خالق الأشياء كلها، لا إله يستحق العبادة غيره، فكيف تعدلون عن الإيمان به، وتعبدون غيره من الأوثان، بعد أن تبينت لكم دلائله؟", "isBasmala": false, "translation_en": "Such is God, your Lord, Creator of all things. There is no god except Him; so how could you turn away?", "translation_id": "Yang demikian itu adalah Allah, Tuhanmu, Pencipta segala sesuatu, tiada Tuhan (yang berhak disembah) melainkan Dia; maka bagaimanakah kamu dapat dipalingkan?", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 63, "text": "كَذَ ٰلِكَ یُؤۡفَكُ ٱلَّذِینَ كَانُوا۟ بِـَٔایَـٰتِ ٱللَّهِ یَجۡحَدُونَ ۝٦٣", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "كما كذَّبتم بالحق -يا كفار قريش- وأعرضتم عنه إلى الباطل، يُصرف عن الحق والإيمان به الذين كانوا بحجج الله وأدلته يجحدون.", "isBasmala": false, "translation_en": "Thus are turned away those who dispute the signs of God.", "translation_id": "Seperti demikianlah dipalingkan orang-orang yang selalu mengingkari ayat-ayat Allah.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 64, "text": "ٱللَّهُ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ قَرَارࣰا وَٱلسَّمَاۤءَ بِنَاۤءࣰ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡ وَرَزَقَكُم مِّنَ ٱلطَّیِّبَـٰتِۚ ذَ ٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ فَتَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَـٰلَمِینَ ۝٦٤", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "الله الذي جعل لكم الأرض؛ لتستقروا فيها، ويسَّر لكم الإقامة عليها، وجعل السماء سقفًا للأرض، وبثَّ فيها من العلامات الهادية، وخلقكم في أكمل هيئة وأحسن تقويم، وأنعم عليكم بحلال الرزق ولذيذ المطاعم والمشارب، ذلكم الذي أنعم عليكم بهذه النعم هو ربكم، فتكاثر خيره وفضله وبركته، وتنزَّه عمَّا لا يليق به، وهو ربُّ الخلائق أجمعين.", "isBasmala": false, "translation_en": "It is God who made the earth a habitat for you, and the sky a structure. And He designed you, and designed you well; and He provided you with the good things. Such is God, your Lord; so Blessed is God, Lord of the Worlds.", "translation_id": "Allah-lah yang menjadikan bumi bagi kamu tempat menetap dan langit sebagai atap, dan membentuk kamu lalu membaguskan rupamu serta memberi kamu rezeki dengan sebahagian yang baik-baik. Yang demikian itu adalah Allah Tuhanmu, Maha Agung Allah, Tuhan semesta alam.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 65, "text": "هُوَ ٱلۡحَیُّ لَاۤ إِلَـٰهَ إِلَّا هُوَ فَٱدۡعُوهُ مُخۡلِصِینَ لَهُ ٱلدِّینَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ ۝٦٥", "juz": 24, "hizb": "(* ح 48*)", "tafsir": "هو الله سبحانه الحي الذي له الحياة الكاملة التامة لا إله غيره، فاسألوه واصرفوا عبادتكم له وحده، مخلصين له دينكم وطاعتكم. فالحمد لله والثناء الكامل له رب الخلائق أجمعين.", "isBasmala": false, "translation_en": "He is the Living One. There is no god except He. So pray to Him, devoting your religion to Him. Praise be to God, the Lord of the Worlds.", "translation_id": "Dialah Yang hidup kekal, tiada Tuhan (yang berhak disembah) melainkan Dia; maka sembahlah Dia dengan memurnikan ibadat kepada-Nya. Segala puji bagi Allah Tuhan semesta alam.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 66, "text": "۞ قُلۡ إِنِّی نُهِیتُ أَنۡ أَعۡبُدَ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَمَّا جَاۤءَنِیَ ٱلۡبَیِّنَـٰتُ مِن رَّبِّی وَأُمِرۡتُ أَنۡ أُسۡلِمَ لِرَبِّ ٱلۡعَـٰلَمِینَ ۝٦٦", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "قل -أيها الرسول- لمشركي قومك: إني نُهيت أن أعبد الذين تدعون من دون الله، لـمَّا جاءني الآيات الواضحات من عند ربي، وأمرني أن أخضع وأنقاد بالطاعة التامة له، سبحانه رب العالمين.", "isBasmala": false, "translation_en": "Say, \"I was prohibited from worshiping those you invoke besides God, now that clear revelations have come to me from my Lord; and I was commanded to submit to the Lord of the Worlds.\"", "translation_id": "Katakanlah (ya Muhammad): \"Sesungguhnya aku dilarang menyembah sembahan yang kamu sembah selain Allah setelah datang kepadaku keterangan-keterangan dari Tuhanku; dan aku diperintahkan supaya tunduk patuh kepada Tuhan semesta alam.", "manzil": 6, "manzil_display": ""}], "475": [{"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 67, "text": "هُوَ ٱلَّذِی خَلَقَكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ مِنۡ عَلَقَةࣲ ثُمَّ یُخۡرِجُكُمۡ طِفۡلࣰا ثُمَّ لِتَبۡلُغُوۤا۟ أَشُدَّكُمۡ ثُمَّ لِتَكُونُوا۟ شُیُوخࣰاۚ وَمِنكُم مَّن یُتَوَفَّىٰ مِن قَبۡلُۖ وَلِتَبۡلُغُوۤا۟ أَجَلࣰا مُّسَمࣰّى وَلَعَلَّكُمۡ تَعۡقِلُونَ ۝٦٧", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "هو الله الذي خلق أباكم آدم من تراب، ثم أوجدكم من المنيِّ بقدرته، وبعد ذلك تنتقلون إلى طور الدم الغليظ الأحمر، ثم تجري عليكم أطوار متعددة في الأرحام، إلى أن تولدوا أطفالا صغارًا، ثم تقوى بِنْيَتُكم إلى أن تصيروا شيوخًا، ومنكم من يموت قبل ذلك، ولتبلغوا بهذه الأطوار المقدَّرة أجلا مسمى تنتهي عنده أعماركم، ولعلكم تعقلون حجج الله عليكم بذلك، وتتدبرون آياته، فتعرفون أنه لا إله غيره يفعل ذلك، وأنه الذي لا تنبغي العبادة إلا له.", "isBasmala": false, "translation_en": "It is He who created you from dust, then from a seed, then from an embryo, then He brings you out as an infant, then He lets you reach your maturity, then you become elderly-although some of you die sooner-so that you may reach a predetermined age, so that you may understand.", "translation_id": "Dialah yang menciptakan kamu dari tanah kemudian dari setetes mani, sesudah itu dari segumpal darah, kemudian dilahirkannya kamu sebagai seorang anak, kemudian (kamu dibiarkan hidup) supaya kamu sampai kepada masa (dewasa), kemudian (dibiarkan kamu hidup lagi) sampai tua, di antara kamu ada yang diwafatkan sebelum itu. (Kami perbuat demikian) supaya kamu sampai kepada ajal yang ditentukan dan supaya kamu memahami(nya).", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 68, "text": "هُوَ ٱلَّذِی یُحۡیِۦ وَیُمِیتُۖ فَإِذَا قَضَىٰۤ أَمۡرࣰا فَإِنَّمَا یَقُولُ لَهُۥ كُن فَیَكُونُ ۝٦٨", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "هو سبحانه المتفرد بالإحياء والإماتة، فإذا قضى أمرًا فإنما يقول له: \"كن\"، فيكون، لا رادَّ لقضائه.", "isBasmala": false, "translation_en": "It is He who gives life and death; and when He decides on a thing, He just says to it, \"Be,\" and it comes to be.", "translation_id": "Dialah yang menghidupkan dan mematikan, maka apabila Dia menetapkan sesuatu urusan, Dia hanya bekata kepadanya: \"Jadilah\", maka jadilah ia.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 69, "text": "أَلَمۡ تَرَ إِلَى ٱلَّذِینَ یُجَـٰدِلُونَ فِیۤ ءَایَـٰتِ ٱللَّهِ أَنَّىٰ یُصۡرَفُونَ ۝٦٩", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "ألا تعجب -أيها الرسول- من هؤلاء المكذِّبين بآيات الله يخاصمون فيها، وهي واضحة الدلالة على توحيد الله وقدرته، كيف يعدلون عنها مع صحتها؟ وإلى أيِّ شيء يذهبون بعد البيان التام؟", "isBasmala": false, "translation_en": "Have you not observed those who dispute regarding God's revelations, how they have deviated?", "translation_id": "Apakah kamu tidak melihat kepada orang-orang yang membantah ayat-ayat Allah? Bagaimanakah mereka dapat dipalingkan?", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 70, "text": "ٱلَّذِینَ كَذَّبُوا۟ بِٱلۡكِتَـٰبِ وَبِمَاۤ أَرۡسَلۡنَا بِهِۦ رُسُلَنَاۖ فَسَوۡفَ یَعۡلَمُونَ ۝٧٠", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "هؤلاء المشركون الذين كذَّبوا بالقرآن والكتب السماوية التي أنزلها الله على رسله لهداية الناس، فسوف يعلم هؤلاء المكذبون عاقبة تكذيبهم حين تُجعل الأغلال في أعناقهم، والسلاسل في أرجلهم، وتسحبهم زبانية العذاب في الماء الحار الذي اشتدَّ غليانه وحرُّه، ثم في نار جهنم يوقد بهم.", "isBasmala": false, "translation_en": "Those who call the Book a lie, and what We sent Our messengers with-they will surely know.", "translation_id": "(Yaitu) orang-orang yang mendustakan Al Kitab (Al Quran) dan wahyu yang dibawa oleh rasul-rasul Kami yang telah Kami utus. Kelak mereka akan mengetahui,", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 71, "text": "إِذِ ٱلۡأَغۡلَـٰلُ فِیۤ أَعۡنَـٰقِهِمۡ وَٱلسَّلَـٰسِلُ یُسۡحَبُونَ ۝٧١", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "هؤلاء المشركون الذين كذَّبوا بالقرآن والكتب السماوية التي أنزلها الله على رسله لهداية الناس، فسوف يعلم هؤلاء المكذبون عاقبة تكذيبهم حين تُجعل الأغلال في أعناقهم، والسلاسل في أرجلهم، وتسحبهم زبانية العذاب في الماء الحار الذي اشتدَّ غليانه وحرُّه، ثم في نار جهنم يوقد بهم.", "isBasmala": false, "translation_en": "When the yokes are around their necks, and they will be dragged by the chains.", "translation_id": "ketika belenggu dan rantai dipasang di leher mereka, seraya mereka diseret,", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 72, "text": "فِی ٱلۡحَمِیمِ ثُمَّ فِی ٱلنَّارِ یُسۡجَرُونَ ۝٧٢", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "هؤلاء المشركون الذين كذَّبوا بالقرآن والكتب السماوية التي أنزلها الله على رسله لهداية الناس، فسوف يعلم هؤلاء المكذبون عاقبة تكذيبهم حين تُجعل الأغلال في أعناقهم، والسلاسل في أرجلهم، وتسحبهم زبانية العذاب في الماء الحار الذي اشتدَّ غليانه وحرُّه، ثم في نار جهنم يوقد بهم.", "isBasmala": false, "translation_en": "Into the boiling water, then in the Fire they will be consumed.", "translation_id": "ke dalam air yang sangat panas, kemudian mereka dibakar dalam api,", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 73, "text": "ثُمَّ قِیلَ لَهُمۡ أَیۡنَ مَا كُنتُمۡ تُشۡرِكُونَ ۝٧٣", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "ثم قيل لهم توبيخًا، وهم في هذه الحال التعيسة: أين الآلهة التي كنتم تعبدونها من دون الله؟ هل ينصرونكم اليوم؟ فادعوهم؛ لينقذوكم من هذا البلاء الذي حلَّ بكم إن استطاعوا، قال المكذبون: غابوا عن عيوننا، فلم ينفعونا بشيء، ويعترفون بأنهم كانوا في جهالة من أمرهم، وأن عبادتهم لهم كانت باطلة لا تساوي شيئًا، كما أضل الله هؤلاء الذين ضلَّ عنهم في جهنم ما كانوا يعبدون في الدنيا من دون الله، يضل الله الكافرين به.", "isBasmala": false, "translation_en": "Then it will be said to them, \"Where are those you used to deify?", "translation_id": "kemudian dikatakan kepada mereka: \"Manakah berhala-berhala yang selalu kamu persekutukan,", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 74, "text": "مِن دُونِ ٱللَّهِۖ قَالُوا۟ ضَلُّوا۟ عَنَّا بَل لَّمۡ نَكُن نَّدۡعُوا۟ مِن قَبۡلُ شَیۡـࣰٔاۚ كَذَ ٰلِكَ یُضِلُّ ٱللَّهُ ٱلۡكَـٰفِرِینَ ۝٧٤", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "ثم قيل لهم توبيخًا، وهم في هذه الحال التعيسة: أين الآلهة التي كنتم تعبدونها من دون الله؟ هل ينصرونكم اليوم؟ فادعوهم؛ لينقذوكم من هذا البلاء الذي حلَّ بكم إن استطاعوا، قال المكذبون: غابوا عن عيوننا، فلم ينفعونا بشيء، ويعترفون بأنهم كانوا في جهالة من أمرهم، وأن عبادتهم لهم كانت باطلة لا تساوي شيئًا، كما أضل الله هؤلاء الذين ضلَّ عنهم في جهنم ما كانوا يعبدون في الدنيا من دون الله، يضل الله الكافرين به.", "isBasmala": false, "translation_en": "Instead of God?\" They will say, \"They have abandoned us. In fact, we were praying to nothing before.\" Thus God sends the disbelievers astray.", "translation_id": "(yang kamu sembah) selain Allah?\" Mereka menjawab: \"Mereka telah hilang lenyap dari kami, bahkan kami dahulu tiada pernah menyembah sesuatu\". Seperti demikianlah Allah menyesatkan orang-orang kafir.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 75, "text": "ذَ ٰلِكُم بِمَا كُنتُمۡ تَفۡرَحُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَمۡرَحُونَ ۝٧٥", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "ذلكم العذاب الذي أصابكم إنما هو بسبب ما كنتم عليه في حياتكم الدنيا من غفلة، حيث كنتم تفرحون بما تقترفونه من المعاصي والآثام، وبما أنتم عليه من الأشَر والبَطَر والبغي على عباد الله.", "isBasmala": false, "translation_en": "That is because you used to rejoice on earth in other than the truth, and because you used to behave with vanity.", "translation_id": "Yang demikian itu disebabkan karena kamu bersuka ria di muka bumi dengan tidak benar dan karena kamu selalu bersuka ria (dalam kemaksiatan).", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 76, "text": "ٱدۡخُلُوۤا۟ أَبۡوَ ٰبَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۖ فَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِینَ ۝٧٦", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "ادخلوا أبواب جهنم عقوبة لكم على كفركم بالله ومعصيتكم له خالدين فيها، فبئست جهنم نزلا للمتكبرين في الدنيا على الله.", "isBasmala": false, "translation_en": "Enter the gates of Hell, to remain therein forever. What a terrible dwelling for the arrogant.", "translation_id": "(Dikatakan kepada mereka): \"Masuklah kamu ke pintu-pintu neraka Jahannam, sedang kamu kekal di dalamnya. Maka itulah seburuk-buruk tempat bagi orang-orang yang sombong\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 77, "text": "فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۚ فَإِمَّا نُرِیَنَّكَ بَعۡضَ ٱلَّذِی نَعِدُهُمۡ أَوۡ نَتَوَفَّیَنَّكَ فَإِلَیۡنَا یُرۡجَعُونَ ۝٧٧", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "فاصبر أيها الرسول، وامض في طريق الدعوة، إن وعد الله حق، وسيُنْجِز لك ما وعدك، فإما نرينَّك في حياتك بعض الذي نعد هؤلاء المشركين من العذاب، أو نتوفينَّك قبل أن يحلَّ ذلك بهم، فإلينا مصيرهم يوم القيامة، وسنذيقهم العذاب الشديد بما كانوا يكفرون.", "isBasmala": false, "translation_en": "So be patient. The promise of God is true. Whether We show you some of what We have promised them, or take you to Us, to Us they will be returned.", "translation_id": "Maka bersabarlah kamu, sesungguhnya janji Allah adalah benar; maka meskipun Kami perlihatkan kepadamu sebagian siksa yang Kami ancamkan kepada mereka ataupun Kami wafatkan kamu (sebelum ajal menimpa mereka), namun kepada Kami sajalah mereka dikembalikan.", "manzil": 6, "manzil_display": ""}], "476": [{"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 78, "text": "وَلَقَدۡ أَرۡسَلۡنَا رُسُلࣰا مِّن قَبۡلِكَ مِنۡهُم مَّن قَصَصۡنَا عَلَیۡكَ وَمِنۡهُم مَّن لَّمۡ نَقۡصُصۡ عَلَیۡكَۗ وَمَا كَانَ لِرَسُولٍ أَن یَأۡتِیَ بِـَٔایَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ فَإِذَا جَاۤءَ أَمۡرُ ٱللَّهِ قُضِیَ بِٱلۡحَقِّ وَخَسِرَ هُنَالِكَ ٱلۡمُبۡطِلُونَ ۝٧٨", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "ولقد أرسلنا مِن قبلك -أيها الرسول- رسلا كثيرين إلى قومهم يدعونهم، ويصبرون على أذاهم: منهم مَن قصصنا عليك خبرهم، ومنهم مَن لم نقصص عليك، وكلهم مأمورون بتبليغ وحي الله إليهم. وما كان لأحد منهم أن يأتي بآية من الآيات الحسية أو العقلية إلا بإذن الله ومشيئته، فإذا جاء أمر الله بعذاب المكذبين قُضِي بالعدل بين الرسل ومكذبيهم، وخسر هنالك المبطلون؛ لافترائهم على الله الكذب، وعبادتهم غيره.", "isBasmala": false, "translation_en": "We sent messengers before you. Some of them We told you about, and some We did not tell you about. No messenger can bring a miracle except by leave of God. Then, when the command of God is issued, fair judgment will be passed, and there and then the seekers of vanity will lose.", "translation_id": "Dan sesungguhnya telah Kami utus beberapa orang rasul sebelum kamu, di antara mereka ada yang Kami ceritakan kepadamu dan di antara mereka ada (pula) yang tidak Kami ceritakan kepadamu. Tidak dapat bagi seorang rasul membawa suatu mukjizat, melainkan dengan seizin Allah; maka apabila telah datang perintah Allah, diputuskan (semua perkara) dengan adil. Dan ketika itu rugilah orang-orang yang berpegang kepada yang batil.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 79, "text": "ٱللَّهُ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَنۡعَـٰمَ لِتَرۡكَبُوا۟ مِنۡهَا وَمِنۡهَا تَأۡكُلُونَ ۝٧٩", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "الله سبحانه هو الذي جعل لكم الأنعام؛ لتنتفعوا بها: من منافع الركوب والأكل وغيرها من أنواع المنافع، ولتبلغوا بالحمولة على بعضها حاجةً في صدوركم من الوصول إلى الأقطار البعيدة، وعلى هذه الأنعام تُحْمَلون في البرية، وعلى الفلك في البحر تُحْمَلون كذلك.", "isBasmala": false, "translation_en": "God is He who created the domestic animals for you-some for you to ride, and some you eat.", "translation_id": "Allahlah yang menjadikan binatang ternak untuk kamu, sebagiannya untuk kamu kendarai dan sebagiannya untuk kamu makan.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 80, "text": "وَلَكُمۡ فِیهَا مَنَـٰفِعُ وَلِتَبۡلُغُوا۟ عَلَیۡهَا حَاجَةࣰ فِی صُدُورِكُمۡ وَعَلَیۡهَا وَعَلَى ٱلۡفُلۡكِ تُحۡمَلُونَ ۝٨٠", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "الله سبحانه هو الذي جعل لكم الأنعام؛ لتنتفعوا بها: من منافع الركوب والأكل وغيرها من أنواع المنافع، ولتبلغوا بالحمولة على بعضها حاجةً في صدوركم من الوصول إلى الأقطار البعيدة، وعلى هذه الأنعام تُحْمَلون في البرية، وعلى الفلك في البحر تُحْمَلون كذلك.", "isBasmala": false, "translation_en": "And in them you have other benefits as well, and through them you satisfy your needs. And on them, and on the ships, you are transported.", "translation_id": "Dan (ada lagi) manfaat-manfaat yang lain pada binatang ternak itu untuk kamu dan supaya kamu mencapai suatu keperluan yang tersimpan dalam hati dengan mengendarainya. Dan kamu dapat diangkut dengan mengendarai binatang-binatang itu dan dengan mengendarai bahtera.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 81, "text": "وَیُرِیكُمۡ ءَایَـٰتِهِۦ فَأَیَّ ءَایَـٰتِ ٱللَّهِ تُنكِرُونَ ۝٨١", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "ويريكم الله تعالى دلائله الكثيرة الواضحة الدالة على قدرته وتدبيره في خلقه، فأي آية من آياته تنكرونها، ولا تعترفون بها؟", "isBasmala": false, "translation_en": "And He shows you His signs. So which of God's signs will you deny?", "translation_id": "Dan Dia memperlihatkan kepada kamu tanda-tanda (kekuasaan-Nya); maka tanda-tanda (kekuasaan) Allah yang manakah yang kamu ingkari?", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 82, "text": "أَفَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَانُوۤا۟ أَكۡثَرَ مِنۡهُمۡ وَأَشَدَّ قُوَّةࣰ وَءَاثَارࣰا فِی ٱلۡأَرۡضِ فَمَاۤ أَغۡنَىٰ عَنۡهُم مَّا كَانُوا۟ یَكۡسِبُونَ ۝٨٢", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "أفلم يَسِرْ هؤلاء المكذبون في الأرض ويتفكروا في مصارع الأمم المكذبة من قبلهم، كيف كانت عاقبتهم؟ وكانت هذه الأمم السابقة أكثر منهم عددًا وعدة وآثارًا في الأرض من الأبنية والمصانع والغراس وغير ذلك، فما أغنى عنهم ما كانوا يكسبونه حين حلَّ بهم بأس الله.", "isBasmala": false, "translation_en": "Have they not journeyed through the land, and seen the outcome for those before them? They were more numerous than they, and had greater power and influence in the land. But what they had achieved availed them nothing.", "translation_id": "Maka apakah mereka tiada mengadakan perjalanan di muka bumi lalu memperhatikan betapa kesudahan orang-orang yang sebelum mereka. Adalah orang-orang yang sebelum mereka itu lebih hebat kekuatannya dan (lebih banyak) bekas-bekas mereka di muka bumi, maka apa yang mereka usahakan itu tidak dapat menolong mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 83, "text": "فَلَمَّا جَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَرِحُوا۟ بِمَا عِندَهُم مِّنَ ٱلۡعِلۡمِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٨٣", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "فلما جاءت هؤلاء الأمم المكذبة رسلُها بالدلائل الواضحات، فرحوا جهلا منهم بما عندهم من العلم المناقض لما جاءت به الرسل، وحلَّ بهم من العذاب ما كانوا يستعجلون به رسلَهم على سبيل السخرية والاستهزاء. وفي الآية دليل على أن كل علم يناقض الإسلام، أو يقدح فيه، أو يشكك في صحته، فإنه مذموم ممقوت، ومعتقده ليس من أتباع محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "When their messengers came to them with clear proofs, they rejoiced in the knowledge they had, and the very things they used to ridicule besieged them.", "translation_id": "Maka tatkala datang kepada mereka rasul-rasul (yang diutus kepada) mereka dengan membawa ketarangan-keterangan, mereka merasa senang dengan pengetahuan yang ada pada mereka dan mereka dikepung oleh azab Allah yang selalu mereka perolok-olokkan itu.", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 84, "text": "فَلَمَّا رَأَوۡا۟ بَأۡسَنَا قَالُوۤا۟ ءَامَنَّا بِٱللَّهِ وَحۡدَهُۥ وَكَفَرۡنَا بِمَا كُنَّا بِهِۦ مُشۡرِكِینَ ۝٨٤", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "فلما رأوا عذابنا أقرُّوا حين لا ينفع الإقرار، وقالوا: آمنا بالله وحده، وكفرنا بما كنا به مشركين في عبادة الله.", "isBasmala": false, "translation_en": "Then, when they witnessed Our might, they said, \"We believe in God alone, and we reject what we used to associate with Him.\"", "translation_id": "Maka tatkala mereka melihat azab Kami, mereka berkata: \"Kami beriman hanya kepada Allah saja, dan kami kafir kepada sembahan-sembahan yang telah kami persekutukan dengan Allah\".", "manzil": 6, "manzil_display": ""}, {"sura": 40, "sura_name": "غافر", "revelation": "Makkiyah", "aya": 85, "text": "فَلَمۡ یَكُ یَنفَعُهُمۡ إِیمَـٰنُهُمۡ لَمَّا رَأَوۡا۟ بَأۡسَنَاۖ سُنَّتَ ٱللَّهِ ٱلَّتِی قَدۡ خَلَتۡ فِی عِبَادِهِۦۖ وَخَسِرَ هُنَالِكَ ٱلۡكَـٰفِرُونَ ۝٨٥", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "فلم يك ينفعهم إيمانهم هذا حين رأوا عذابنا؛ وذلك لأنه إيمان قد اضطروا إليه، لا إيمان اختيار ورغبة، سنة الله وطريقته التي سنَّها في الأمم كلها أن لا ينفعها الإيمان إذا رأوا العذاب، وهلك عند مجيء بأس الله الكافرون بربهم، الجاحدون توحيده وطاعته.", "isBasmala": false, "translation_en": "But their faith could not help them once they witnessed Our might. This has been God's way of dealing with His servants. And there and then the disbelievers lost.", "translation_id": "Maka iman mereka tiada berguna bagi mereka tatkala mereka telah melihat siksa Kami. Itulah sunnah Allah yang telah berlaku terhadap hamba-hamba-Nya. Dan di waktu itu binasalah orang-orang kafir.", "manzil": 6, "manzil_display": ""}], "477": [{"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 25, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 1, "text": "حمۤ ۝١", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "(حم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ha, Meem.", "translation_id": "Haa Miim.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 2, "text": "تَنزِیلࣱ مِّنَ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ۝٢", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "هذا القرآن الكريم تنزيل من الرحمن الرحيم، نزَّله على نبيه محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "A revelation from the Most Gracious, the Most Merciful.", "translation_id": "Diturunkan dari Tuhan Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 3, "text": "كِتَـٰبࣱ فُصِّلَتۡ ءَایَـٰتُهُۥ قُرۡءَانًا عَرَبِیࣰّا لِّقَوۡمࣲ یَعۡلَمُونَ ۝٣", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "كتاب بُيِّنت آياته تمام البيان، وَوُضِّحت معانيه وأحكامه، قرآنًا عربيًا ميسَّرًا فهمه لقوم يعلمون اللسان العربي.", "isBasmala": false, "translation_en": "A Scripture whose Verses are detailed, a Quran in Arabic for people who know.", "translation_id": "Kitab yang dijelaskan ayat-ayatnya, yakni bacaan dalam bahasa Arab, untuk kaum yang mengetahui,", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 4, "text": "بَشِیرࣰا وَنَذِیرࣰا فَأَعۡرَضَ أَكۡثَرُهُمۡ فَهُمۡ لَا یَسۡمَعُونَ ۝٤", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "بشيرًا بالثواب العاجل والآجل لمن آمن به وعمل بمقتضاه، ونذيرًا بالعقاب العاجل والآجل لمن كفر به، فأعرض عنه أكثر الناس، فهم لا يسمعون له سماع قَبول وإجابة.", "isBasmala": false, "translation_en": "Bringing good news, and giving warnings. But most of them turn away, so they do not listen.", "translation_id": "yang membawa berita gembira dan yang membawa peringatan, tetapi kebanyakan mereka berpaling, tidak mau mendengarkan.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 5, "text": "وَقَالُوا۟ قُلُوبُنَا فِیۤ أَكِنَّةࣲ مِّمَّا تَدۡعُونَاۤ إِلَیۡهِ وَفِیۤ ءَاذَانِنَا وَقۡرࣱ وَمِنۢ بَیۡنِنَا وَبَیۡنِكَ حِجَابࣱ فَٱعۡمَلۡ إِنَّنَا عَـٰمِلُونَ ۝٥", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "وقال هؤلاء المعرضون الكافرون للنبي محمد صلى الله عليه وسلم: قلوبنا في أغطية مانعة لنا من فهم ما تدعونا إليه، وفي آذاننا صمم فلا نسمع، ومن بيننا وبينك- يا محمد- ساتر يحجبنا عن إجابة دعوتك، فاعمل على وَفْق دينك، كما أننا عاملون على وَفْق ديننا.", "isBasmala": false, "translation_en": "And they say, \"Our hearts are screened from what you call us to, and in our ears is deafness, and between us and you is a barrier. So do what you want, and so will we.\"", "translation_id": "Mereka berkata: \"Hati kami berada dalam tutupan (yang menutupi) apa yang kamu seru kami kepadanya dan telinga kami ada sumbatan dan antara kami dan kamu ada dinding, maka bekerjalah kamu; sesungguhnya kami bekerja (pula)\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 6, "text": "قُلۡ إِنَّمَاۤ أَنَا۠ بَشَرࣱ مِّثۡلُكُمۡ یُوحَىٰۤ إِلَیَّ أَنَّمَاۤ إِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰحِدࣱ فَٱسۡتَقِیمُوۤا۟ إِلَیۡهِ وَٱسۡتَغۡفِرُوهُۗ وَوَیۡلࣱ لِّلۡمُشۡرِكِینَ ۝٦", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "قل لهم -أيها الرسول-: إنما أنا بشر مثلكم يوحي الله إليَّ أنما إلهكم الذي يستحق العبادة، إله واحد لا شريك له، فاسلكوا الطريق الموصل إليه، واطلبوا مغفرته. وعذاب للمشركين الذين عبدوا من دون الله أوثانًا لا تنفع ولا تضر، والذين لم يطهروا أنفسهم بتوحيد ربهم، والإخلاص له، ولم يصلُّوا ولم يزكَّوا، فلا إخلاص منهم للخالق ولا نفع فيهم للخلق، وهم لا يؤمنون بالبعث، ولا بالجنة والنار، ولا ينفقون في طاعة الله.", "isBasmala": false, "translation_en": "Say, \"I am only a human like you; it is inspired in me that your God is One God. So be upright towards Him, and seek forgiveness from Him.\" And woe to the idolaters.", "translation_id": "Katakanlah: \"Bahwasanya aku hanyalah seorang manusia seperti kamu, diwahyukan kepadaku bahwasanya Tuhan kamu adalah Tuhan yang Maha Esa, maka tetaplah pada jalan yang lurus menuju kepada-Nya dan mohonlah ampun kepada-Nya. Dan kecelakaan besarlah bagi orang-orang yang mempersekutukan-Nya,", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 7, "text": "ٱلَّذِینَ لَا یُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ كَـٰفِرُونَ ۝٧", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "قل لهم -أيها الرسول-: إنما أنا بشر مثلكم يوحي الله إليَّ أنما إلهكم الذي يستحق العبادة، إله واحد لا شريك له، فاسلكوا الطريق الموصل إليه، واطلبوا مغفرته. وعذاب للمشركين الذين عبدوا من دون الله أوثانًا لا تنفع ولا تضر، والذين لم يطهروا أنفسهم بتوحيد ربهم، والإخلاص له، ولم يصلُّوا ولم يزكَّوا، فلا إخلاص منهم للخالق ولا نفع فيهم للخلق، وهم لا يؤمنون بالبعث، ولا بالجنة والنار، ولا ينفقون في طاعة الله.", "isBasmala": false, "translation_en": "Those who do not pay the alms; and regarding the Hereafter, they are disbelievers.", "translation_id": "(yaitu) orang-orang yang tidak menunaikan zakat dan mereka kafir akan adanya (kehidupan) akhirat.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 8, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمۡ أَجۡرٌ غَیۡرُ مَمۡنُونࣲ ۝٨", "juz": 24, "hizb": "(*¼ ح 48*)", "tafsir": "إن الذين آمنوا بالله ورسوله وكتابه وعملوا الأعمال الصالحة مخلصين لله فيها، لهم ثواب عظيم غير مقطوع ولا ممنوع.", "isBasmala": false, "translation_en": "As for those who believe and do righteous deeds-for them is a reward uninterrupted.", "translation_id": "Sesungguhnya orang-orang yang beriman dan beramal saleh, mereka mendapat pahala yang tiada putus-putusnya\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 9, "text": "۞ قُلۡ أَىِٕنَّكُمۡ لَتَكۡفُرُونَ بِٱلَّذِی خَلَقَ ٱلۡأَرۡضَ فِی یَوۡمَیۡنِ وَتَجۡعَلُونَ لَهُۥۤ أَندَادࣰاۚ ذَ ٰلِكَ رَبُّ ٱلۡعَـٰلَمِینَ ۝٩", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين موبخًا لهم ومتعجبًا من فعلهم: أإنكم لتكفرون بالله الذي خلق الأرض في يومين اثنين، وتجعلون له نظراء وشركاء تعبدونهم معه؟ ذلك الخالق هو رب العالمين كلهم.", "isBasmala": false, "translation_en": "Say, \"Do you reject the One who created the earth in two days? And you attribute equals to Him? That is the Lord of the Universe.\"", "translation_id": "Katakanlah: \"Sesungguhnya patutkah kamu kafir kepada Yang menciptakan bumi dalam dua masa dan kamu adakan sekutu-sekutu bagi-Nya? (Yang bersifat) demikian itu adalah Rabb semesta alam\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 10, "text": "وَجَعَلَ فِیهَا رَوَ ٰسِیَ مِن فَوۡقِهَا وَبَـٰرَكَ فِیهَا وَقَدَّرَ فِیهَاۤ أَقۡوَ ٰتَهَا فِیۤ أَرۡبَعَةِ أَیَّامࣲ سَوَاۤءࣰ لِّلسَّاۤىِٕلِینَ ۝١٠", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "وجعل سبحانه في الأرض جبالا ثوابت من فوقها، وبارك فيها فجعلها دائمة الخير لأهلها، وقدَّر فيها أرزاق أهلها من الغذاء، وما يصلحهم من المعاش في تمام أربعة أيام: يومان خلق فيهما الأرض، ويومان جعل فيها رواسي وقدر فيها أقواتها، سواء للسائلين أي: لمن أراد السؤال عن ذلك؛ ليعلمه.", "isBasmala": false, "translation_en": "He placed stabilizers over it; and blessed it; and planned its provisions in four days, equally to the seekers.", "translation_id": "Dan dia menciptakan di bumi itu gunung-gunung yang kokoh di atasnya. Dia memberkahinya dan Dia menentukan padanya kadar makanan-makanan (penghuni)nya dalam empat masa. (Penjelasan itu sebagai jawaban) bagi orang-orang yang bertanya.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 11, "text": "ثُمَّ ٱسۡتَوَىٰۤ إِلَى ٱلسَّمَاۤءِ وَهِیَ دُخَانࣱ فَقَالَ لَهَا وَلِلۡأَرۡضِ ٱئۡتِیَا طَوۡعًا أَوۡ كَرۡهࣰا قَالَتَاۤ أَتَیۡنَا طَاۤىِٕعِینَ ۝١١", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "ثم استوى سبحانه وتعالى، أي قصد إلى السماء وكانت دخانًا من قبلُ، فقال للسماء وللأرض: انقادا لأمري مختارتين أو مجبرتين. قالتا: أتينا مذعنين لك، ليس لنا إرادة تخالف إرادتك.", "isBasmala": false, "translation_en": "Then He turned to the sky, and it was smoke, and said to it and to the earth, \"Come, willingly or unwillingly.\" They said, \"We come willingly.\"", "translation_id": "Kemudian Dia menuju kepada penciptaan langit dan langit itu masih merupakan asap, lalu Dia berkata kepadanya dan kepada bumi: \"Datanglah kamu keduanya menurut perintah-Ku dengan suka hati atau terpaksa\". Keduanya menjawab: \"Kami datang dengan suka hati\".", "manzil": 6, "manzil_display": ""}], "478": [{"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 12, "text": "فَقَضَىٰهُنَّ سَبۡعَ سَمَـٰوَاتࣲ فِی یَوۡمَیۡنِ وَأَوۡحَىٰ فِی كُلِّ سَمَاۤءٍ أَمۡرَهَاۚ وَزَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِمَصَـٰبِیحَ وَحِفۡظࣰاۚ ذَ ٰلِكَ تَقۡدِیرُ ٱلۡعَزِیزِ ٱلۡعَلِیمِ ۝١٢", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "فقضى الله خلق السماوات السبع وتسويتهن في يومين، فتم بذلك خلق السماوات والأرض في ستة أيام، لحكمة يعلمها الله، مع قدرته سبحانه على خلقهما في لحظة واحدة، وأوحى في كل سماء ما أراده وما أمر به فيها، وزيَّنا السماء الدنيا بالنجوم المضيئة، وحفظًا لها من الشياطين الذين يسترقون السمع، ذلك الخلق البديع تقدير العزيز في ملكه، العليم الذي أحاط علمه بكل شيء.", "isBasmala": false, "translation_en": "So He completed them as seven universes in two days, and He assigned to each universe its laws. And We decorated the lower universe with lamps, and for protection. That is the design of the Almighty, the All-Knowing.", "translation_id": "Maka Dia menjadikannya tujuh langit dalam dua masa. Dia mewahyukan pada tiap-tiap langit urusannya. Dan Kami hiasi langit yang dekat dengan bintang-bintang yang cemerlang dan Kami memeliharanya dengan sebaik-baiknya. Demikianlah ketentuan Yang Maha Perkasa lagi Maha Mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 13, "text": "فَإِنۡ أَعۡرَضُوا۟ فَقُلۡ أَنذَرۡتُكُمۡ صَـٰعِقَةࣰ مِّثۡلَ صَـٰعِقَةِ عَادࣲ وَثَمُودَ ۝١٣", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "فإن أعرض هؤلاء المكذبون بعدما بُيَّن لهم من أوصاف القرآن الحميدة، ومن صفات الله العظيم، فقل لهم: قد أنذرتكم عذابًا يستأصلكم مثل عذاب عاد وثمود حين كفروا بربهم وعصوا رسله.", "isBasmala": false, "translation_en": "But if they turn away, say, \"I have warned you of a thunderbolt, like the thunderbolt of Aad and Thamood.\"", "translation_id": "Jika mereka berpaling maka katakanlah: \"Aku telah memperingatkan kamu dengan petir, seperti petir yang menimpa kaum 'Aad dan Tsamud\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 14, "text": "إِذۡ جَاۤءَتۡهُمُ ٱلرُّسُلُ مِنۢ بَیۡنِ أَیۡدِیهِمۡ وَمِنۡ خَلۡفِهِمۡ أَلَّا تَعۡبُدُوۤا۟ إِلَّا ٱللَّهَۖ قَالُوا۟ لَوۡ شَاۤءَ رَبُّنَا لَأَنزَلَ مَلَـٰۤىِٕكَةࣰ فَإِنَّا بِمَاۤ أُرۡسِلۡتُم بِهِۦ كَـٰفِرُونَ ۝١٤", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "حين جاءت الرسل عادًا وثمود، يتبع بعضهم بعضًا متوالين، يأمرونهم بعبادة الله وحده لا شريك له، قالوا لرسلهم: لو شاء ربنا أن نوحده ولا نعبد من دونه شيئًا غيره، لأنزل إلينا ملائكة من السماء رسلا بما تدعوننا إليه، ولم يرسلكم وأنتم بشر مثلنا، فإنا بما أرسلكم الله به إلينا من الإيمان بالله وحده جاحدون.", "isBasmala": false, "translation_en": "Their messengers came to them, from before them and from behind them, saying, \"Do not worship anyone but God.\" They said, \"Had our Lord willed, He would have sent down angels; Therefore, we reject what you are sent with.\"", "translation_id": "Ketika para rasul datang kepada mereka dari depan dan belakang mereka (dengan menyerukan): \"Janganlah kamu menyembah selain Allah\". Mereka menjawab: \"Kalau Tuhan kami menghendaki tentu Dia akan menurunkan malaikat-malaikat-Nya, maka sesungguhnya kami kafir kepada wahyu yang kamu diutus membawanya\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 15, "text": "فَأَمَّا عَادࣱ فَٱسۡتَكۡبَرُوا۟ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَقَالُوا۟ مَنۡ أَشَدُّ مِنَّا قُوَّةًۖ أَوَ لَمۡ یَرَوۡا۟ أَنَّ ٱللَّهَ ٱلَّذِی خَلَقَهُمۡ هُوَ أَشَدُّ مِنۡهُمۡ قُوَّةࣰۖ وَكَانُوا۟ بِـَٔایَـٰتِنَا یَجۡحَدُونَ ۝١٥", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "فأما عاد قوم هود فقد استعلَوا في الأرض على العباد بغير حق، وقالوا في غرور: مَن أشد منا قوة؟ أولم يروا أن الله تعالى الذي خلقهم هو أشدُّ منهم قوة وبطشًا؟ وكانوا بأدلتنا وحججنا يجحدون.", "isBasmala": false, "translation_en": "As for Aad, they turned arrogant on earth, and opposed justice, and said, \"Who is more powerful than us?\" Have they not considered that God, who created them, is more powerful than they? And they went on denying Our revelations.", "translation_id": "Adapun kaum 'Aad maka mereka menyombongkan diri di muka bumi tanpa alasan yang benar dan berkata: \"Siapakah yang lebih besar kekuatannya dari kami?\" Dan apakah mereka itu tidak memperhatikan bahwa Allah Yang menciptakan mereka adalah lebih besar kekuatan-Nya daripada mereka? Dan adalah mereka mengingkari tanda-tanda (kekuatan) Kami.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 16, "text": "فَأَرۡسَلۡنَا عَلَیۡهِمۡ رِیحࣰا صَرۡصَرࣰا فِیۤ أَیَّامࣲ نَّحِسَاتࣲ لِّنُذِیقَهُمۡ عَذَابَ ٱلۡخِزۡیِ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَخۡزَىٰۖ وَهُمۡ لَا یُنصَرُونَ ۝١٦", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "فأرسلنا عليهم ريحًا شديدة البرودة عالية الصوت في أيام مشؤومات عليهم؛ لنذيقهم عذاب الذل والهوان في الحياة الدنيا، ولَعذاب الآخرة أشد ذلا وهوانًا، وهم لا يُنْصَرون بمنع العذاب عنهم.", "isBasmala": false, "translation_en": "So We unleashed upon them a screaming wind, for a few miserable days, to make them taste the punishment of shame in this life; but the punishment of the Hereafter is more shameful; and they will not be saved.", "translation_id": "Maka Kami meniupkan angin yang amat gemuruh kepada mereka dalam beberapa hari yang sial, karena Kami hendak merasakan kepada mereka itu siksaan yang menghinakan dalam kehidupan dunia. Dan Sesungguhnya siksa akhirat lebih menghinakan sedang mereka tidak diberi pertolongan.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 17, "text": "وَأَمَّا ثَمُودُ فَهَدَیۡنَـٰهُمۡ فَٱسۡتَحَبُّوا۟ ٱلۡعَمَىٰ عَلَى ٱلۡهُدَىٰ فَأَخَذَتۡهُمۡ صَـٰعِقَةُ ٱلۡعَذَابِ ٱلۡهُونِ بِمَا كَانُوا۟ یَكۡسِبُونَ ۝١٧", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "وأما ثمود قوم صالح فقد بينَّا لهم سبيل الحق وطريق الرشد، فاختاروا العمى على الهدى، فأهلكتهم صاعقة العذاب المهين؛ بسبب ما كانوا يقترفون من الآثام بكفرهم بالله وتكذيبهم رسله.", "isBasmala": false, "translation_en": "And as for Thamood, We guided them, but they preferred blindness over guidance. So the thunderbolt of the humiliating punishment seized them, because of what they used to earn.", "translation_id": "Dan adapun kaum Tsamud, maka mereka telah Kami beri petunjuk tetapi mereka lebih menyukai buta (kesesatan) daripada petunjuk, maka mereka disambar petir azab yang menghinakan disebabkan apa yang telah mereka kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 18, "text": "وَنَجَّیۡنَا ٱلَّذِینَ ءَامَنُوا۟ وَكَانُوا۟ یَتَّقُونَ ۝١٨", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "ونجَّينا الذين آمنوا من العذاب الذي أخذ عادًا وثمود، وكان هؤلاء الناجون يخافون الله ويتقونه.", "isBasmala": false, "translation_en": "And We saved those who believed and were righteous.", "translation_id": "Dan Kami selamatkan orang-orang yang beriman dan mereka adalah orang-orang yang bertakwa.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 19, "text": "وَیَوۡمَ یُحۡشَرُ أَعۡدَاۤءُ ٱللَّهِ إِلَى ٱلنَّارِ فَهُمۡ یُوزَعُونَ ۝١٩", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "ويوم يُحشر أعداء الله إلى نار جهنم، تَرُدُّ زبانية العذاب أولَهم على آخرهم، حتى إذا ما جاؤوا النار، وأنكروا جرائمهم شهد عليهم سمعهم وأبصارهم وجلودهم بما كانوا يعملون في الدنيا من الذنوب والآثام.", "isBasmala": false, "translation_en": "The Day when God's enemies are herded into the Fire, forcibly.", "translation_id": "Dan (ingatlah) hari (ketika) musuh-musuh Allah di giring ke dalam neraka, lalu mereka dikumpulkan semuanya.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 20, "text": "حَتَّىٰۤ إِذَا مَا جَاۤءُوهَا شَهِدَ عَلَیۡهِمۡ سَمۡعُهُمۡ وَأَبۡصَـٰرُهُمۡ وَجُلُودُهُم بِمَا كَانُوا۟ یَعۡمَلُونَ ۝٢٠", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "ويوم يُحشر أعداء الله إلى نار جهنم، تَرُدُّ زبانية العذاب أولَهم على آخرهم، حتى إذا ما جاؤوا النار، وأنكروا جرائمهم شهد عليهم سمعهم وأبصارهم وجلودهم بما كانوا يعملون في الدنيا من الذنوب والآثام.", "isBasmala": false, "translation_en": "Until, when they have reached it, their hearing, and their sight, and their skins will testify against them regarding what they used to do.", "translation_id": "Sehingga apabila mereka sampai ke neraka, pendengaran, penglihatan dan kulit mereka menjadi saksi terhadap mereka tentang apa yang telah mereka kerjakan.", "manzil": 6, "manzil_display": ""}], "479": [{"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 21, "text": "وَقَالُوا۟ لِجُلُودِهِمۡ لِمَ شَهِدتُّمۡ عَلَیۡنَاۖ قَالُوۤا۟ أَنطَقَنَا ٱللَّهُ ٱلَّذِیۤ أَنطَقَ كُلَّ شَیۡءࣲۚ وَهُوَ خَلَقَكُمۡ أَوَّلَ مَرَّةࣲ وَإِلَیۡهِ تُرۡجَعُونَ ۝٢١", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "وقال هؤلاء الذين يُحْشرون إلى النار من أعداء الله لجلودهم معاتبين: لِمَ شهدتم علينا؟ فأجابتهم جلودهم: أنطقنا الله الذي أنطق كل شيء، وهو الذي خلقكم أول مرة ولم تكونوا شيئًا، وإليه مصيركم بعد الموت للحساب والجزاء.", "isBasmala": false, "translation_en": "And they will say to their skins, \"Why did you testify against us?\" They will say, \"God, Who made all things speak, made us speak. It is He who created you the first time, and to Him you are returned.\"", "translation_id": "Dan mereka berkata kepada kulit mereka: \"Mengapa kamu menjadi saksi terhadap kami?\" Kulit mereka menjawab: \"Allah yang menjadikan segala sesuatu pandai berkata telah menjadikan kami pandai (pula) berkata, dan Dialah yang menciptakan kamu pada kali pertama dan hanya kepada-Nya lah kamu dikembalikan\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 22, "text": "وَمَا كُنتُمۡ تَسۡتَتِرُونَ أَن یَشۡهَدَ عَلَیۡكُمۡ سَمۡعُكُمۡ وَلَاۤ أَبۡصَـٰرُكُمۡ وَلَا جُلُودُكُمۡ وَلَـٰكِن ظَنَنتُمۡ أَنَّ ٱللَّهَ لَا یَعۡلَمُ كَثِیرࣰا مِّمَّا تَعۡمَلُونَ ۝٢٢", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "وما كنتم تَسْتَخْفون عند ارتكابكم المعاصي؛ خوفًا من أن يشهد عليكم سمعكم ولا أبصاركم ولا جلودكم يوم القيامة، ولكن ظننتم بارتكابكم المعاصي أن الله لا يعلم كثيرًا من أعمالكم التي تعصون الله بها. وذلكم ظنكم السيِّئ الذي ظننتموه بربكم أهلككم، فأوردكم النار، فأصبحتم اليوم من الخاسرين الذين خسروا أنفسهم وأهليهم.", "isBasmala": false, "translation_en": "You were unable to hide yourselves from your hearing, and your sight, and your skins, to prevent them from testifying against you, and you imagined that God was unaware of much of what you do.", "translation_id": "Kamu sekali-sekali tidak dapat bersembunyi dari kesaksian pendengaran, penglihatan dan kulitmu kepadamu bahkan kamu mengira bahwa Allah tidak mengetahui kebanyakan dari apa yang kamu kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 23, "text": "وَذَ ٰلِكُمۡ ظَنُّكُمُ ٱلَّذِی ظَنَنتُم بِرَبِّكُمۡ أَرۡدَىٰكُمۡ فَأَصۡبَحۡتُم مِّنَ ٱلۡخَـٰسِرِینَ ۝٢٣", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "وما كنتم تَسْتَخْفون عند ارتكابكم المعاصي؛ خوفًا من أن يشهد عليكم سمعكم ولا أبصاركم ولا جلودكم يوم القيامة، ولكن ظننتم بارتكابكم المعاصي أن الله لا يعلم كثيرًا من أعمالكم التي تعصون الله بها. وذلكم ظنكم السيِّئ الذي ظننتموه بربكم أهلككم، فأوردكم النار، فأصبحتم اليوم من الخاسرين الذين خسروا أنفسهم وأهليهم.", "isBasmala": false, "translation_en": "It is that thought of yours about your Lord that led you to ruin-so you became of the losers.", "translation_id": "Dan yang demikian itu adalah prasangkamu yang telah kamu sangka kepada Tuhanmu, Dia telah membinasakan kamu, maka jadilah kamu termasuk orang-orang yang merugi.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 24, "text": "فَإِن یَصۡبِرُوا۟ فَٱلنَّارُ مَثۡوࣰى لَّهُمۡۖ وَإِن یَسۡتَعۡتِبُوا۟ فَمَا هُم مِّنَ ٱلۡمُعۡتَبِینَ ۝٢٤", "juz": 24, "hizb": "(*½ ح 48*)", "tafsir": "فإن يصبروا على العذاب فالنار مأواهم، وإن يسألوا الرجوع إلى الدنيا؛ ليستأنفوا العمل الصالح لا يُجابوا إلى ذلك، ولا تُقبل لهم أعذار.", "isBasmala": false, "translation_en": "If they endure patiently, the Fire will be their residence; and if they make up excuses, they will not be pardoned.", "translation_id": "Jika mereka bersabar (menderita azab) maka nerakalah tempat diam mereka dan jika mereka mengemukakan alasan-alasan, maka tidaklah mereka termasuk orang-orang yang diterima alasannya.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 25, "text": "۞ وَقَیَّضۡنَا لَهُمۡ قُرَنَاۤءَ فَزَیَّنُوا۟ لَهُم مَّا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡ وَحَقَّ عَلَیۡهِمُ ٱلۡقَوۡلُ فِیۤ أُمَمࣲ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُوا۟ خَـٰسِرِینَ ۝٢٥", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "وهيأنا لهؤلاء الظالمين الجاحدين قرناء فاسدين من شياطين الإنس والجن، فزينوا لهم قبائح أعمالهم في الدنيا، ودعَوهم إلى لذاتها وشهواتها المحرمة، وزَيَّنوا لهم ما خَلْفهم من أمور الآخرة، فأنسوهم ذِكرها، ودعَوهم إلى التكذيب بالمعاد، وبذلك استحقوا دخول النار في جملة أمم سابقة من كفرة الجن والإنس، إنهم كانوا خاسرين أعمالهم في الدنيا وأنفسهم وأهليهم يوم القيامة.", "isBasmala": false, "translation_en": "We had assigned companions for them, who glamorized to them what was in front of them, and what was behind them. And the Word proved true against them in communities of jinn and humans that have passed away before them. They were losers.", "translation_id": "Dan Kami tetapkan bagi mereka teman-teman yang menjadikan mereka memandang bagus apa yang ada di hadapan dan di belakang mereka dan tetaplah atas mereka keputusan azab pada umat-umat yang terdahulu sebelum mereka dari jinn dan manusia, sesungguhnya mereka adalah orang-orang yang merugi.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 26, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَا تَسۡمَعُوا۟ لِهَـٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡا۟ فِیهِ لَعَلَّكُمۡ تَغۡلِبُونَ ۝٢٦", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "وقال الكافرون بعضهم لبعض متواصين فيما بينهم: لا تسمعوا لهذا القرآن، ولا تطيعوه، ولا تنقادوا لأوامره، وارفعوا أصواتكم بالصياح والصفير والتخليط على محمد إذا قرأ القرآن؛ لعلكم تغلبونه، فيترك القراءة، وننتصر عليه.", "isBasmala": false, "translation_en": "Those who disbelieve say, \"Do not listen to this Quran, and talk over it, so that you may prevail.\"", "translation_id": "Dan orang-orang yang kafir berkata: \"Janganlah kamu mendengar dengan sungguh-sungguh akan Al Quran ini dan buatlah hiruk-pikuk terhadapnya, supaya kamu dapat mengalahkan mereka\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 27, "text": "فَلَنُذِیقَنَّ ٱلَّذِینَ كَفَرُوا۟ عَذَابࣰا شَدِیدࣰا وَلَنَجۡزِیَنَّهُمۡ أَسۡوَأَ ٱلَّذِی كَانُوا۟ یَعۡمَلُونَ ۝٢٧", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "فلنذيقن الذين قالوا هذا القول عذابًا شديدًا في الدنيا والآخرة، ولنجزينهم أسوأ ما كانوا يعملون من السيئات.", "isBasmala": false, "translation_en": "We will make those who disbelieve taste an intense agony, and We will recompense them according to the worst of what they used to do.", "translation_id": "Maka sesungguhnya Kami akan merasakan azab yang keras kepada orang-orang kafir dan Kami akan memberi balasan kepada mereka dengan seburuk-buruk pembalasan bagi apa yang telah mereka kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 28, "text": "ذَ ٰلِكَ جَزَاۤءُ أَعۡدَاۤءِ ٱللَّهِ ٱلنَّارُۖ لَهُمۡ فِیهَا دَارُ ٱلۡخُلۡدِ جَزَاۤءَۢ بِمَا كَانُوا۟ بِـَٔایَـٰتِنَا یَجۡحَدُونَ ۝٢٨", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "هذا الجزاء الذي يُجزى به هؤلاء الذين كفروا جزاء أعداء الله النار، لهم فيها دار الخلود الدائم؛ جزاء بما كانوا بحججنا وأدلتنا يجحدون في الدنيا. والآية دالة على عظم جريمة من صرف الناس عن القرآن العظيم، وصدهم عن تدبره وهدايته بأيِّ وسيلة كانت.", "isBasmala": false, "translation_en": "Such is the recompense of God's enemies-the Fire-where they will have their permanent home, in recompense for having disregarded Our revelations.", "translation_id": "Demikianlah balasan terhadap musuh-musuh Allah, (yaitu) neraka; mereka mendapat tempat tinggal yang kekal di dalamnya sebagai balasan atas keingkaran mereka terhadap ayat-ayat Kami.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 29, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوا۟ رَبَّنَاۤ أَرِنَا ٱلَّذَیۡنِ أَضَلَّانَا مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ نَجۡعَلۡهُمَا تَحۡتَ أَقۡدَامِنَا لِیَكُونَا مِنَ ٱلۡأَسۡفَلِینَ ۝٢٩", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "وقال الذين كفروا بالله ورسوله، وهم في النار: ربنا أرنا اللذَين أضلانا من خلقك من الجن والإنس نجعلهما تحت أقدامنا؛ ليكونا في الدرك الأسفل من النار.", "isBasmala": false, "translation_en": "Those who disbelieved will say, \"Our Lord, show us those who led us astray-among jinn and humans-and we will trample them under our feet, so they become among of the lowest.\"", "translation_id": "Dan orang-orang kafir berkata: \"Ya Rabb kami perlihatkanlah kepada kami dua jenis orang yang telah menyesatkan kami (yaitu) sebagian dari jinn dan manusia agar kami letakkan keduanya di bawah telapak kaki kami supaya kedua jenis itu menjadi orang-orang yang hina\".", "manzil": 6, "manzil_display": ""}], "480": [{"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 30, "text": "إِنَّ ٱلَّذِینَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَـٰمُوا۟ تَتَنَزَّلُ عَلَیۡهِمُ ٱلۡمَلَـٰۤىِٕكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحۡزَنُوا۟ وَأَبۡشِرُوا۟ بِٱلۡجَنَّةِ ٱلَّتِی كُنتُمۡ تُوعَدُونَ ۝٣٠", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "إن الذين قالوا ربنا الله تعالى وحده لا شريك له، ثم استقاموا على شريعته، تتنزل عليهم الملائكة عند الموت قائلين لهم: لا تخافوا من الموت وما بعده، ولا تحزنوا على ما تخلفونه وراءكم من أمور الدنيا، وأبشروا بالجنة التي كنتم توعدون بها.", "isBasmala": false, "translation_en": "Surely, those who say: \"Our Lord is God,\" and then go straight, the angels will descend upon them: \"Do not fear, and do not grieve, but rejoice in the news of the Garden which you were promised.", "translation_id": "Sesungguhnya orang-orang yang mengatakan: \"Tuhan kami ialah Allah\" kemudian mereka meneguhkan pendirian mereka, maka malaikat akan turun kepada mereka dengan mengatakan: \"Janganlah kamu takut dan janganlah merasa sedih; dan gembirakanlah mereka dengan jannah yang telah dijanjikan Allah kepadamu\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 31, "text": "نَحۡنُ أَوۡلِیَاۤؤُكُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَفِی ٱلۡـَٔاخِرَةِۖ وَلَكُمۡ فِیهَا مَا تَشۡتَهِیۤ أَنفُسُكُمۡ وَلَكُمۡ فِیهَا مَا تَدَّعُونَ ۝٣١", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "وتقول لهم الملائكة: نحن أنصاركم في الحياة الدنيا، نسددكم ونحفظكم بأمر الله، وكذلك نكون معكم في الآخرة، ولكم في الجنة كل ما تشتهيه أنفسكم مما تختارونه، وتَقَرُّ به أعينكم، ومهما طلبتم من شيء وجدتموه بين أيديكم ضيافة وإنعامًا لكم مِن غفور لذنوبكم، رحيم بكم.", "isBasmala": false, "translation_en": "We are your allies in this life and in the Hereafter, wherein you will have whatever your souls desire, and you will have therein whatever you call for.", "translation_id": "Kamilah pelindung-pelindungmu dalam kehidupan dunia dan akhirat; di dalamnya kamu memperoleh apa yang kamu inginkan dan memperoleh (pula) di dalamnya apa yang kamu minta.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 32, "text": "نُزُلࣰا مِّنۡ غَفُورࣲ رَّحِیمࣲ ۝٣٢", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "وتقول لهم الملائكة: نحن أنصاركم في الحياة الدنيا، نسددكم ونحفظكم بأمر الله، وكذلك نكون معكم في الآخرة، ولكم في الجنة كل ما تشتهيه أنفسكم مما تختارونه، وتَقَرُّ به أعينكم، ومهما طلبتم من شيء وجدتموه بين أيديكم ضيافة وإنعامًا لكم مِن غفور لذنوبكم، رحيم بكم.", "isBasmala": false, "translation_en": "As Hospitality from an All-Forgiving, Merciful One.\"", "translation_id": "Sebagai hidangan (bagimu) dari Tuhan Yang Maha Pengampun lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 33, "text": "وَمَنۡ أَحۡسَنُ قَوۡلࣰا مِّمَّن دَعَاۤ إِلَى ٱللَّهِ وَعَمِلَ صَـٰلِحࣰا وَقَالَ إِنَّنِی مِنَ ٱلۡمُسۡلِمِینَ ۝٣٣", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "لا أحد أحسن قولا ممن دعا إلى توحيد الله وعبادته وحده وعمل صالحًا وقال: إنني من المسلمين المنقادين لأمر الله وشرعه. وفي الآية حث على الدعوة إلى الله سبحانه، وبيان فضل العلماء الداعين إليه على بصيرة، وَفْق ما جاء عن رسول الله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "And who is better in speech than someone who calls to God, and acts with integrity, and says, \"I am of those who submit\"?", "translation_id": "Siapakah yang lebih baik perkataannya daripada orang yang menyeru kepada Allah, mengerjakan amal yang saleh, dan berkata: \"Sesungguhnya aku termasuk orang-orang yang menyerah diri?\"", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 34, "text": "وَلَا تَسۡتَوِی ٱلۡحَسَنَةُ وَلَا ٱلسَّیِّئَةُۚ ٱدۡفَعۡ بِٱلَّتِی هِیَ أَحۡسَنُ فَإِذَا ٱلَّذِی بَیۡنَكَ وَبَیۡنَهُۥ عَدَ ٰوَةࣱ كَأَنَّهُۥ وَلِیٌّ حَمِیمࣱ ۝٣٤", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "ولا تستوي حسنة الذين آمنوا بالله، واستقاموا على شرعه، وأحسنوا إلى خلقه، وسيئة الذين كفروا به وخالفوا أمره، وأساؤوا إلى خلقه. ادفع بعفوك وحلمك وإحسانك مَن أساء إليك، وقابل إساءته لك بالإحسان إليه، فبذلك يصير المسيء إليك الذي بينك وبينه عداوة كأنه قريب لك شفيق عليك. وما يُوفَّق لهذه الخصلة الحميدة إلا الذين صبروا أنفسهم على ما تكره، وأجبروها على ما يحبه الله، وما يُوفَّق لها إلا ذو نصيب وافر من السعادة في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Good and evil are not equal. Repel evil with good, and the person who was your enemy becomes like an intimate friend.", "translation_id": "Dan tidaklah sama kebaikan dan kejahatan. Tolaklah (kejahatan itu) dengan cara yang lebih baik, maka tiba-tiba orang yang antaramu dan antara dia ada permusuhan seolah-olah telah menjadi teman yang sangat setia.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 35, "text": "وَمَا یُلَقَّىٰهَاۤ إِلَّا ٱلَّذِینَ صَبَرُوا۟ وَمَا یُلَقَّىٰهَاۤ إِلَّا ذُو حَظٍّ عَظِیمࣲ ۝٣٥", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "ولا تستوي حسنة الذين آمنوا بالله، واستقاموا على شرعه، وأحسنوا إلى خلقه، وسيئة الذين كفروا به وخالفوا أمره، وأساؤوا إلى خلقه. ادفع بعفوك وحلمك وإحسانك مَن أساء إليك، وقابل إساءته لك بالإحسان إليه، فبذلك يصير المسيء إليك الذي بينك وبينه عداوة كأنه قريب لك شفيق عليك. وما يُوفَّق لهذه الخصلة الحميدة إلا الذين صبروا أنفسهم على ما تكره، وأجبروها على ما يحبه الله، وما يُوفَّق لها إلا ذو نصيب وافر من السعادة في الدنيا والآخرة.", "isBasmala": false, "translation_en": "But none will attain it except those who persevere, and none will attain it except the very fortunate.", "translation_id": "Sifat-sifat yang baik itu tidak dianugerahkan melainkan kepada orang-orang yang sabar dan tidak dianugerahkan melainkan kepada orang-orang yang mempunyai keuntungan yang besar.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 36, "text": "وَإِمَّا یَنزَغَنَّكَ مِنَ ٱلشَّیۡطَـٰنِ نَزۡغࣱ فَٱسۡتَعِذۡ بِٱللَّهِۖ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٣٦", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "وإما يلقينَّ الشيطان في نفسك وسوسة من حديث النفس لحملك على مجازاة المسيء بالإساءة، فاستجر بالله واعتصم به، إن الله هو السميع لاستعاذتك به، العليم بأمور خلقه جميعها.", "isBasmala": false, "translation_en": "When a temptation from the Devil provokes you, seek refuge in God; He is the Hearer, the Knower.", "translation_id": "Dan jika syetan mengganggumu dengan suatu gangguan, maka mohonlah perlindungan kepada Allah. Sesungguhnya Dialah yang Maha Mendengar lagi Maha Mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 37, "text": "وَمِنۡ ءَایَـٰتِهِ ٱلَّیۡلُ وَٱلنَّهَارُ وَٱلشَّمۡسُ وَٱلۡقَمَرُۚ لَا تَسۡجُدُوا۟ لِلشَّمۡسِ وَلَا لِلۡقَمَرِ وَ̅ٱ̅سۡ̅جُ̅دُ̅و̅ا۟̅ ̅لِ̅لَّ̅هِ̅ ٱلَّذِی خَلَقَهُنَّ إِن كُنتُمۡ إِیَّاهُ تَعۡبُدُونَ ۝٣٧", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "ومِن حجج الله على خلقه، ودلائله على وحدانيته وكمال قدرته اختلاف الليل والنهار، وتعاقبهما، واختلاف الشمس والقمر وتعاقبهما، كل ذلك تحت تسخيره وقهره. لا تسجدوا للشمس ولا للقمر- فإنهما مدَبَّران مخلوقان- واسجدوا لله الذي خلقهن، إن كنتم حقًّا منقادين لأمره سامعين مطيعين له، تعبدونه وحده لا شريك له.", "isBasmala": false, "translation_en": "And of His signs are the night and the day, and the sun and the moon. Do not bow down to the sun, nor to the moon, but bow down to God, Who created them both, if it is Him that you serve.", "translation_id": "Dan di antara tanda-tanda kekuasaan-Nya ialah malam, siang, matahari dan bulan. Janganlah sembah matahari maupun bulan, tapi sembahlah Allah Yang menciptakannya, Jika Ialah yang kamu hendak sembah.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 38, "text": "فَإِنِ ٱسۡتَكۡبَرُوا۟ فَٱلَّذِینَ عِندَ رَبِّكَ یُسَبِّحُونَ لَهُۥ بِٱلَّیۡلِ وَٱلنَّهَارِ وَهُمۡ لَا یَسۡـَٔمُونَ ۝٣٨ ۩", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "فإن استكبر هؤلاء المشركون عن السجود لله، فإن الملائكة الذين عند ربك لا يستكبرون عن ذلك، بل يسبحون له، وينزِّهونه عن كل نقص بالليل والنهار، وهم لا يَفْتُرون عن ذلك، ولا يملون.", "isBasmala": false, "translation_en": "But if they are too proud-those in the presence of your Lord praise Him night and day, and without ever tiring.", "translation_id": "Jika mereka menyombongkan diri, maka mereka (malaikat) yang di sisi Tuhanmu bertasbih kepada-Nya di malam dan siang hari, sedang mereka tidak jemu-jemu.", "manzil": 6, "manzil_display": ""}], "481": [{"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 39, "text": "وَمِنۡ ءَایَـٰتِهِۦۤ أَنَّكَ تَرَى ٱلۡأَرۡضَ خَـٰشِعَةࣰ فَإِذَاۤ أَنزَلۡنَا عَلَیۡهَا ٱلۡمَاۤءَ ٱهۡتَزَّتۡ وَرَبَتۡۚ إِنَّ ٱلَّذِیۤ أَحۡیَاهَا لَمُحۡیِ ٱلۡمَوۡتَىٰۤۚ إِنَّهُۥ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝٣٩", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "ومن علامات وحدانية الله وقدرته: أنك ترى الأرض يابسة لا نبات فيها، فإذا أنزلنا عليها المطر دبَّت فيها الحياة، وتحركت بالنبات، وانتفخت وعلت، إن الذي أحيا هذه الأرض بعد همودها، قادر على إحياء الخلق بعد موتهم، إنه على كل شيء قدير، فكما لا تعجز قدرته عن إحياء الأرض بعد موتها، فكذلك لا تعجز عن إحياء الموتى.", "isBasmala": false, "translation_en": "And of His signs is that you see the land still. But when We send down water upon it, it stirs and grows. Surely, He Who revived it will revive the dead. He is Able to do all things.", "translation_id": "Dan di antara tanda-tanda-Nya (Ialah) bahwa kau lihat bumi kering dan gersang, maka apabila Kami turunkan air di atasnya, niscaya ia bergerak dan subur. Sesungguhnya Tuhan Yang menghidupkannya, Pastilah dapat menghidupkan yang mati. Sesungguhnya Dia Maha Kuasa atas segala sesuatu.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 40, "text": "إِنَّ ٱلَّذِینَ یُلۡحِدُونَ فِیۤ ءَایَـٰتِنَا لَا یَخۡفَوۡنَ عَلَیۡنَاۤۗ أَفَمَن یُلۡقَىٰ فِی ٱلنَّارِ خَیۡرٌ أَم مَّن یَأۡتِیۤ ءَامِنࣰا یَوۡمَ ٱلۡقِیَـٰمَةِۚ ٱعۡمَلُوا۟ مَا شِئۡتُمۡ إِنَّهُۥ بِمَا تَعۡمَلُونَ بَصِیرٌ ۝٤٠", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "إن الذين يميلون عن الحق، فيكفرون بالقرآن ويحرفونه، لا يَخْفَون علينا، بل نحن مُطَّلعون عليهم. أفهذا الملحد في آيات الله الذي يُلقى في النار خير، أم الذي يأتي يوم القيامة آمنًا من عذاب الله، مستحقًا لثوابه؛ لإيمانه به وتصديقه بآياته؟ اعملوا- أيها الملحدون- ما شئتم، فإن الله تعالى بأعمالكم بصير، لا يخفى عليه شيء منها، وسيجازيكم على ذلك. وفي هذا وعيد وتهديد لهم.", "isBasmala": false, "translation_en": "Those who despise Our revelations are not hidden from Us. Is he who is hurled into the Fire better? Or he who arrives safely on the Day of Resurrection? Do as you please; He is Seeing of everything you do.", "translation_id": "Sesungguhnya orang-orang yang mengingkari ayat-ayat Kami, mereka tidak tersembunyi dari Kami. Maka apakah orang-orang yang dilemparkan ke dalam neraka lebih baik, ataukah orang-orang yang datang dengan aman sentosa pada hari Kiamat? Perbuatlah apa yang kamu kehendaki; Sesungguhnya Dia Maha Melihat apa yang kamu kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 41, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ بِٱلذِّكۡرِ لَمَّا جَاۤءَهُمۡۖ وَإِنَّهُۥ لَكِتَـٰبٌ عَزِیزࣱ ۝٤١", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "إن الذين جحدوا بهذا القرآن وكذَّبوا به حين جاءهم هالكون ومعذَّبون، وإن هذا القرآن لكتاب عزيز بإعزاز الله إياه وحفظه له من كل تغيير أو تبديل، لا يأتيه الباطل من أي ناحية من نواحيه ولا يبطله شيء، فهو محفوظ من أن يُنقص منه، أو يزاد فيه، تنزيل من حكيم بتدبير أمور عباده، محمود على ما له من صفات الكمال.", "isBasmala": false, "translation_en": "Those who reject the Reminder when it has come to them-it is an invincible Book.", "translation_id": "Sesungguhnya orang-orang yang mengingkari Al Quran ketika Al Quran itu datang kepada mereka, (mereka itu pasti akan celaka), dan sesungguhnya Al Quran itu adalah kitab yang mulia.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 42, "text": "لَّا یَأۡتِیهِ ٱلۡبَـٰطِلُ مِنۢ بَیۡنِ یَدَیۡهِ وَلَا مِنۡ خَلۡفِهِۦۖ تَنزِیلࣱ مِّنۡ حَكِیمٍ حَمِیدࣲ ۝٤٢", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "إن الذين جحدوا بهذا القرآن وكذَّبوا به حين جاءهم هالكون ومعذَّبون، وإن هذا القرآن لكتاب عزيز بإعزاز الله إياه وحفظه له من كل تغيير أو تبديل، لا يأتيه الباطل من أي ناحية من نواحيه ولا يبطله شيء، فهو محفوظ من أن يُنقص منه، أو يزاد فيه، تنزيل من حكيم بتدبير أمور عباده، محمود على ما له من صفات الكمال.", "isBasmala": false, "translation_en": "Falsehood cannot approach it, from before it or behind it. It is a revelation from One Wise and Praiseworthy.", "translation_id": "Yang tidak datang kepadanya (Al Quran) kebatilan baik dari depan maupun dari belakangnya, yang diturunkan dari Rabb Yang Maha Bijaksana lagi Maha Terpuji.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 43, "text": "مَّا یُقَالُ لَكَ إِلَّا مَا قَدۡ قِیلَ لِلرُّسُلِ مِن قَبۡلِكَۚ إِنَّ رَبَّكَ لَذُو مَغۡفِرَةࣲ وَذُو عِقَابٍ أَلِیمࣲ ۝٤٣", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "ما يقول لك هؤلاء المشركون -أيها الرسول- إلا ما قد قاله مَن قبلهم مِنَ الأمم لرسلهم، فاصبر على ما ينالك في سبيل الدعوة إلى الله. إن ربك لذو مغفرة لذنوب التائبين، وذو عقاب لمن أصرَّ على كفره وتكذيبه.", "isBasmala": false, "translation_en": "Nothing is said to you but was said to the Messengers before you: your Lord is Possessor of Forgiveness, and Possessor of Painful Repayment.", "translation_id": "Tidaklah ada yang dikatakan (oleh orang-orang kafir) kepadamu itu selain apa yang sesungguhnya telah dikatakan kepada rasul-rasul sebelum kamu. Sesungguhnya Rabb-mu benar-benar mempunyai ampunan dan hukuman yang pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 44, "text": "وَلَوۡ جَعَلۡنَـٰهُ قُرۡءَانًا أَعۡجَمِیࣰّا لَّقَالُوا۟ لَوۡلَا فُصِّلَتۡ ءَایَـٰتُهُۥۤۖ ءَا۬عۡجَمِیࣱّ وَعَرَبِیࣱّۗ قُلۡ هُوَ لِلَّذِینَ ءَامَنُوا۟ هُدࣰى وَشِفَاۤءࣱۚ وَٱلَّذِینَ لَا یُؤۡمِنُونَ فِیۤ ءَاذَانِهِمۡ وَقۡرࣱ وَهُوَ عَلَیۡهِمۡ عَمًىۚ أُو۟لَـٰۤىِٕكَ یُنَادَوۡنَ مِن مَّكَانِۭ بَعِیدࣲ ۝٤٤", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "ولو جعلنا هذا القرآن الذي أنزلناه عليك -أيها الرسول- أعجميًا، لقال المشركون: هلا بُيِّنتْ آياته، فنفقهه ونعلمه، أأعجمي هذا القرآن، ولسان الذي أنزل عليه عربي؟ هذا لا يكون. قل لهم -أيها الرسول-: هذا القرآن للذين آمنوا بالله ورسوله هدى من الضلالة، وشفاء لما في الصدور من الشكوك والأمراض، والذين لا يؤمنون بالقرآن في آذانهم صمم من سماعه وتدبره، وهو على قلوبهم عَمًى، فلا يهتدون به، أولئك المشركون كمن يُنادى، وهو في مكان بعيد لا يسمع داعيًا، ولا يجيب مناديًا.", "isBasmala": false, "translation_en": "Had We made it a Quran in a foreign language, they would have said, \"If only its verses were made clear.\" Non-Arabic and an Arab? Say, \"For those who believe, it is guidance and healing. But as for those who do not believe: there is heaviness in their ears, and it is blindness for them. These are being called from a distant place.\"", "translation_id": "Dan jikalau Kami jadikan Al Quran itu suatu bacaan dalam bahasa selain Arab, tentulah mereka mengatakan: \"Mengapa tidak dijelaskan ayat-ayatnya?\" Apakah (patut Al Quran) dalam bahasa asing sedang (rasul adalah orang) Arab? Katakanlah: \"Al Quran itu adalah petunjuk dan penawar bagi orang-orang mukmin. Dan orang-orang yang tidak beriman pada telinga mereka ada sumbatan, sedang Al Quran itu suatu kegelapan bagi mereka. Mereka itu adalah (seperti) yang dipanggil dari tempat yang jauh\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 45, "text": "وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ فَٱخۡتُلِفَ فِیهِۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ لَقُضِیَ بَیۡنَهُمۡۚ وَإِنَّهُمۡ لَفِی شَكࣲّ مِّنۡهُ مُرِیبࣲ ۝٤٥", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "ولقد آتينا موسى التوراة كما آتيناك -أيها الرسول- القرآن فاختلف فيها قومه: فمنهم مَن آمن، ومنهم مَن كذَّب. ولولا كلمة سبقت من ربك بتأجيل العذاب عن قومك لفُصِل بينهم بإهلاك الكافرين في الحال، وإن المشركين لفي شك من القرآن شديد الريبة.", "isBasmala": false, "translation_en": "We gave Moses the Book, but disputes arose concerning it. Were it not for a prior decree from your Lord, judgment would have been pronounced between them. But they are in perplexing doubt concerning it.", "translation_id": "Dan sesungguhnya telah Kami berikan kepada Musa Taurat lalu diperselisihkan tentang Taurat itu. Kalau tidak ada keputusan yang telah terdahulu dari Rabb-mu, tentulah orang-orang kafir itu sudah dibinasakan. Dan Sesungguhnya mereka terhadap Al Quran benar-benar dalam keragu-raguan yang membingungkan.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 46, "text": "مَّنۡ عَمِلَ صَـٰلِحࣰا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَاۤءَ فَعَلَیۡهَاۗ وَمَا رَبُّكَ بِظَلَّـٰمࣲ لِّلۡعَبِیدِ ۝٤٦", "juz": 24, "hizb": "(*¾ ح 48*)", "tafsir": "من عمل صالحًا فأطاع الله ورسوله فلنفسه ثواب عمله، ومن أساء فعصى الله ورسوله فعلى نفسه وزر عمله. وما ربك بظلام للعبيد، بنقص حسنة أو زيادة سيِّئة.", "isBasmala": false, "translation_en": "Whoever acts righteously does so for himself; and whoever works evil does so against himself. Your Lord is not unjust to the servants.", "translation_id": "Barangsiapa yang mengerjakan amal yang saleh maka (pahalanya) untuk dirinya sendiri dan barangsiapa mengerjakan perbuatan jahat, maka (dosanya) untuk dirinya sendiri; dan sekali-kali tidaklah Rabb-mu menganiaya hamba-hamba-Nya.", "manzil": 6, "manzil_display": ""}], "482": [{"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 47, "text": "۞ إِلَیۡهِ یُرَدُّ عِلۡمُ ٱلسَّاعَةِۚ وَمَا تَخۡرُجُ مِن ثَمَرَ ٰتࣲ مِّنۡ أَكۡمَامِهَا وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَیَوۡمَ یُنَادِیهِمۡ أَیۡنَ شُرَكَاۤءِی قَالُوۤا۟ ءَاذَنَّـٰكَ مَامِنَّا مِن شَهِیدࣲ ۝٤٧", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "إلى الله تعالى وحده لا شريك له يُرْجَع علم الساعة، فإنه لا يعلم أحد متى قيامها غيره، وما تخرج من ثمرات من أوعيتها، وما تحمل مِن أنثى ولا تضع حَمْلها إلا بعلم من الله، لا يخفى عليه شيء من ذلك. ويوم ينادي الله تعالى المشركين يوم القيامة توبيخًا لهم وإظهارًا لكذبهم: أين شركائي الذين كنتم تشركونهم في عبادتي؟ قالوا: أعلمناك الآن ما منا من أحد يشهد اليوم أن معك شريكًا.", "isBasmala": false, "translation_en": "To Him is referred the knowledge of the Hour. No fruit emerges from its sheath, and no female conceives or delivers, except with His knowledge. And on the Day when He calls out to them, \"Where are My associates?\" They will say, \"We admit to you, none of us is a witness.\"", "translation_id": "Kepada-Nya-lah dikembalikan pengetahuan tentang hari Kiamat. Dan tidak ada buah-buahan keluar dari kelopaknya dan tidak seorang perempuanpun mengandung dan tidak (pula) melahirkan, melainkan dengan sepengetahuan-Nya. Pada hari Tuhan memanggil mereka: \"Dimanakah sekutu-sekutu-Ku itu?\", mereka menjawab: \"Kami nyatakan kepada Engkau bahwa tidak ada seorangpun di antara kami yang memberi kesaksian (bahwa Engkau punya sekutu)\".", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 48, "text": "وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَدۡعُونَ مِن قَبۡلُۖ وَظَنُّوا۟ مَا لَهُم مِّن مَّحِیصࣲ ۝٤٨", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "وذهب عن هؤلاء المشركين شركاؤهم الذين كانوا يعبدونهم من دون الله، فلم ينفعوهم، وأيقنوا أن لا ملجأ لهم من عذاب الله، ولا محيد عنه.", "isBasmala": false, "translation_en": "What they used to pray to before will forsake them, and they will realize that they have no escape.", "translation_id": "Dan hilang lenyaplah dari mereka apa yang selalu mereka sembah dahulu, dan mereka yakin bahwa tidak ada bagi mereka satu jalan keluarpun.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 49, "text": "لَّا یَسۡـَٔمُ ٱلۡإِنسَـٰنُ مِن دُعَاۤءِ ٱلۡخَیۡرِ وَإِن مَّسَّهُ ٱلشَّرُّ فَیَـُٔوسࣱ قَنُوطࣱ ۝٤٩", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "لا يملُّ الإنسان من دعاء ربه طالبًا الخير الدنيوي، وإن أصابه فقر وشدة فهو يؤوس من رحمة الله، قنوط بسوء الظن بربه.", "isBasmala": false, "translation_en": "The human being never tires of praying for good things; but when adversity afflicts him, he despairs and loses hope.", "translation_id": "Manusia tidak jemu memohon kebaikan, dan jika mereka ditimpa malapetaka dia menjadi putus asa lagi putus harapan.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 50, "text": "وَلَىِٕنۡ أَذَقۡنَـٰهُ رَحۡمَةࣰ مِّنَّا مِنۢ بَعۡدِ ضَرَّاۤءَ مَسَّتۡهُ لَیَقُولَنَّ هَـٰذَا لِی وَمَاۤ أَظُنُّ ٱلسَّاعَةَ قَاۤىِٕمَةࣰ وَلَىِٕن رُّجِعۡتُ إِلَىٰ رَبِّیۤ إِنَّ لِی عِندَهُۥ لَلۡحُسۡنَىٰۚ فَلَنُنَبِّئَنَّ ٱلَّذِینَ كَفَرُوا۟ بِمَا عَمِلُوا۟ وَلَنُذِیقَنَّهُم مِّنۡ عَذَابٍ غَلِیظࣲ ۝٥٠", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "ولئن أذقنا الإنسان نعمة منا من بعد شدة وبلاء لم يشكر الله تعالى، بل يطغى ويقول: أتاني هذا؛ لأني مستحق له، وما أعتقد أن الساعة آتية، وذلك إنكار منه للبعث، وعلى تقدير إتيان الساعة وأني سأرجع إلى ربي، فإن لي عنده الجنة، فلنخبرن الذين كفروا يوم القيامة بما عملوا من سيئات، ولنذيقنهم من العذاب الشديد.", "isBasmala": false, "translation_en": "And when We let him taste a mercy from Us, after the adversity that had afflicted him, he will say, \"This is mine, and I do not think that the Hour is coming; and even if I am returned to my Lord, I will have the very best with Him.\" We will inform those who disbelieve of what they did, and We will make them taste an awful punishment.", "translation_id": "Dan jika Kami merasakan kepadanya sesuatu rahmat dari Kami sesudah dia ditimpa kesusahan, pastilah dia berkata: \"Ini adalah hakku, dan aku tidak yakin bahwa hari Kiamat itu akan datang. Dan jika aku dikembalikan kepada Tuhanku maka sesungguhnya aku akan memperoleh kebaikan pada sisi-Nya\". Maka Kami benar-benar akan memberitakan kepada orang-orang kafir apa yang telah mereka kerjakan dan akan Kami rasakan kepada mereka azab yang keras.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 51, "text": "وَإِذَاۤ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَـٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ فَذُو دُعَاۤءٍ عَرِیضࣲ ۝٥١", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "وإذا أنعمنا على الإنسان بصحة أو رزق أو غيرهما أعرض وترفَّع عن الانقياد إلى الحق، فإن أصابه ضر فهو ذو دعاء كثير بأن يكشف الله ضرَّه، فهو يعرف ربه في الشدة، ولا يعرفه في الرخاء.", "isBasmala": false, "translation_en": "When We provide comfort for the human being, he withdraws and distances himself; but when adversity befalls him, he starts lengthy prayers.", "translation_id": "Dan apabila Kami memberikan nikmat kepada manusia, ia berpaling dan menjauhkan diri; tetapi apabila ia ditimpa malapetaka, maka ia banyak berdoa.", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 52, "text": "قُلۡ أَرَءَیۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ ثُمَّ كَفَرۡتُم بِهِۦ مَنۡ أَضَلُّ مِمَّنۡ هُوَ فِی شِقَاقِۭ بَعِیدࣲ ۝٥٢", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "قل -أيها الرسول- لهؤلاء المكذبين: أخبروني إن كان هذا القرآن من عند الله ثم جحدتم وكذَّبتم به، لا أحد أضل منكم؛ لأنكم في خلاف بعيد عن الحق بكفركم بالقرآن وتكذيبكم به.", "isBasmala": false, "translation_en": "Say, \"Have you considered? If it is from God and you reject it-who is further astray than he who is cutoff and alienated?\"", "translation_id": "Katakanlah: \"Bagaimana pendapatmu jika (Al Quran) itu datang dari sisi Allah, kemudian kamu mengingkarinya. Siapakah yang lebih sesat daripada orang yang selalu berada dalam penyimpangan yang jauh?\"", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 53, "text": "سَنُرِیهِمۡ ءَایَـٰتِنَا فِی ٱلۡـَٔافَاقِ وَفِیۤ أَنفُسِهِمۡ حَتَّىٰ یَتَبَیَّنَ لَهُمۡ أَنَّهُ ٱلۡحَقُّۗ أَوَ لَمۡ یَكۡفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ ۝٥٣", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "سَنُري هؤلاء المكذبين آياتنا من الفتوحات وظهور الإسلام على الأقاليم وسائر الأديان، وفي أقطار السماوات والأرض، وما يحدثه الله فيهما من الحوادث العظيمة، وفي أنفسهم وما اشتملت عليه من بديع آيات الله وعجائب صنعه، حتى يتبين لهم من تلك الآيات بيان لا يقبل الشك أن القرآن الكريم هو الحق الموحَى به من رب العالمين. أولم يكفهم دليلا على أن القرآن حق، ومَن جاء به صادق، شهادة الله تعالى؟ فإنه قد شهد له بالتصديق، وهو على كل شيء شهيد، ولا شيء أكبر شهادة من شهادته سبحانه وتعالى.", "isBasmala": false, "translation_en": "We will show them Our proofs on the horizons, and in their very souls, until it becomes clear to them that it is the truth. Is it not sufficient that your Lord is witness over everything?", "translation_id": "Kami akan memperlihatkan kepada mereka tanda-tanda (kekuasaan) Kami di segala wilayah bumi dan pada diri mereka sendiri, hingga jelas bagi mereka bahwa Al Quran itu adalah benar. Tiadakah cukup bahwa sesungguhnya Tuhanmu menjadi saksi atas segala sesuatu?", "manzil": 6, "manzil_display": ""}, {"sura": 41, "sura_name": "فصلت", "revelation": "Makkiyah", "aya": 54, "text": "أَلَاۤ إِنَّهُمۡ فِی مِرۡیَةࣲ مِّن لِّقَاۤءِ رَبِّهِمۡۗ أَلَاۤ إِنَّهُۥ بِكُلِّ شَیۡءࣲ مُّحِیطُۢ ۝٥٤", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "ألا إن هؤلاء الكافرين في شك عظيم من البعث بعد الممات. ألا إن الله- جلَّ وعلا- بكل شيء محيط علمًا وقدرة وعزةً، لا يخفى عليه شيء في الأرض ولا في السماء.", "isBasmala": false, "translation_en": "Surely they are in doubt about the encounter with their Lord. Surely He comprehends everything.", "translation_id": "Ingatlah bahwa sesungguhnya mereka adalah dalam keraguan tentang pertemuan dengan Tuhan mereka. Ingatlah bahwa sesungguhnya Dia Maha Meliputi segala sesuatu.", "manzil": 6, "manzil_display": ""}], "483": [{"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 25, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 1, "text": "حمۤ ۝١", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "(حم * عسق) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ha, Meem.", "translation_id": "Haa Miim.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 2, "text": "عۤسۤقۤ ۝٢", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "(حم * عسق) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ayn, Seen, Qaf.", "translation_id": "'Ain Siin Qaaf.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 3, "text": "كَذَ ٰلِكَ یُوحِیۤ إِلَیۡكَ وَإِلَى ٱلَّذِینَ مِن قَبۡلِكَ ٱللَّهُ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٣", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "كما أنزل الله إليك -أيها النبي- هذا القرآن أنزل الكتب والصحف على الأنبياء من قبلك، وهو العزيز في انتقامه، الحكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "Thus He inspires you, and those before you-God the Almighty, the Wise.", "translation_id": "Demikianlah Allah Yang Maha Perkasa lagi Maha Bijaksana, mewahyukan kepada kamu dan kepada orang-orang sebelum kamu.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 4, "text": "لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَلِیُّ ٱلۡعَظِیمُ ۝٤", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "لله وحده ما في السماوات وما في الأرض، وهو العليُّ بذاته وقدره وقهره، العظيم الذي له العظمة والكبرياء.", "isBasmala": false, "translation_en": "To him belongs everything in the heavens and everything on earth. He is the Sublime, the Magnificent.", "translation_id": "Kepunyaan-Nya-lah apa yang ada di langit dan apa yang ada di bumi. Dan Dialah yang Maha Tinggi lagi Maha Besar.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 5, "text": "تَكَادُ ٱلسَّمَـٰوَ ٰتُ یَتَفَطَّرۡنَ مِن فَوۡقِهِنَّۚ وَٱلۡمَلَـٰۤىِٕكَةُ یُسَبِّحُونَ بِحَمۡدِ رَبِّهِمۡ وَیَسۡتَغۡفِرُونَ لِمَن فِی ٱلۡأَرۡضِۗ أَلَاۤ إِنَّ ٱللَّهَ هُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ ۝٥", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "تكاد السماوات يتشقَّقْنَ، كل واحدة فوق التي تليها؛ من عظمة الرحمن وجلاله تبارك وتعالى، والملائكة يسبحون بحمد ربهم، وينزهونه عما لا يليق به، ويسألون ربهم المغفرة لذنوب مَن في الأرض مِن أهل الإيمان به. ألا إن الله هو الغفور لذنوب مؤمني عباده، الرحيم بهم.", "isBasmala": false, "translation_en": "The heavens above them almost burst apart, while the angels glorify the praises of their Lord, and ask forgiveness for those on earth. God is indeed the Forgiver, the Merciful.", "translation_id": "Hampir saja langit itu pecah dari sebelah atas (karena kebesaran Tuhan) dan malaikat-malaikat bertasbih serta memuji Tuhan-nya dan memohonkan ampun bagi orang-orang yang ada di bumi. Ingatlah, bahwa sesungguhnya Allah Dialah Yang Maha Pengampun lagi Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 6, "text": "وَٱلَّذِینَ ٱتَّخَذُوا۟ مِن دُونِهِۦۤ أَوۡلِیَاۤءَ ٱللَّهُ حَفِیظٌ عَلَیۡهِمۡ وَمَاۤ أَنتَ عَلَیۡهِم بِوَكِیلࣲ ۝٦", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "والذين اتخذوا غير الله آلهة مِن دونه يتولَّونها، ويعبدونها، الله تعالى يحفظ عليهم أفعالهم؛ ليجازيهم بها يوم القيامة، وما أنت -أيها الرسول- بالوكيل عليهم بحفظ أعمالهم، إنما أنت منذر، فعليك البلاغ وعلينا الحساب.", "isBasmala": false, "translation_en": "As for those who take masters other than Him: God is in charge of them, and you are not responsible for them.", "translation_id": "Dan orang-orang yang mengambil pelindung-pelindung selain Allah, Allah mengawasi (perbuatan) mereka; dan kamu (ya Muhammad) bukanlah orang yang diserahi mengawasi mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 7, "text": "وَكَذَ ٰلِكَ أَوۡحَیۡنَاۤ إِلَیۡكَ قُرۡءَانًا عَرَبِیࣰّا لِّتُنذِرَ أُمَّ ٱلۡقُرَىٰ وَمَنۡ حَوۡلَهَا وَتُنذِرَ یَوۡمَ ٱلۡجَمۡعِ لَا رَیۡبَ فِیهِۚ فَرِیقࣱ فِی ٱلۡجَنَّةِ وَفَرِیقࣱ فِی ٱلسَّعِیرِ ۝٧", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "وكما أوحينا إلى الأنبياء قبلك أوحَيْنا إليك قرآنا عربيًّا؛ لتنذر أهل \"مكة\" ومَن حولها مِن سائر الناس، وتنذر عذاب يوم الجمع، وهو يوم القيامة، لا شك في مجيئه. الناس فيه فريقان: فريق في الجنة، وهم الذين آمنوا بالله واتبعوا ما جاءهم به رسوله محمد صلى الله عليه وسلم، ومنهم فريق في النار المستعرة، وهم الذين كفروا بالله، وخالفوا ما جاءهم به رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Thus We inspired you with an Arabic Quran, that you may warn the Central City and whoever is around it, and to warn of the Day of Assembly, of which there is no doubt; a group in the Garden, and a group in the Furnace.", "translation_id": "Demikianlah Kami wahyukan kepadamu Al Quran dalam bahasa Arab, supaya kamu memberi peringatan kepada ummul Qura (penduduk Mekah) dan penduduk (negeri-negeri) sekelilingnya serta memberi peringatan (pula) tentang hari berkumpul (kiamat) yang tidak ada keraguan padanya. Segolongan masuk surga, dan segolongan masuk Jahannam.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 8, "text": "وَلَوۡ شَاۤءَ ٱللَّهُ لَجَعَلَهُمۡ أُمَّةࣰ وَ ٰحِدَةࣰ وَلَـٰكِن یُدۡخِلُ مَن یَشَاۤءُ فِی رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمُونَ مَا لَهُم مِّن وَلِیࣲّ وَلَا نَصِیرٍ ۝٨", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "ولو شاء الله أن يجمع خَلْقَه على الهدى ويجعلهم على ملة واحدة مهتدية لفعل، ولكنه أراد أن يُدخل في رحمته مَن يشاء مِن خواص خلقه. والظالمون أنفسهم بالشرك ما لهم من وليٍّ يتولى أمورهم يوم القيامة، ولا نصير ينصرهم من عقاب الله تعالى.", "isBasmala": false, "translation_en": "Had God willed, He could have made them one community, but He admits into His mercy whomever He wills. As for the wrongdoers, they will have no protector and no savior.", "translation_id": "Dan kalau Allah menghendaki niscaya Allah menjadikan mereka satu umat (saja), tetapi Dia memasukkan orang-orang yang dikehendaki-Nya ke dalam rahmat-Nya. Dan orang-orang yang zalim tidak ada bagi mereka seorang pelindungpun dan tidak pula seorang penolong.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 9, "text": "أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦۤ أَوۡلِیَاۤءَۖ فَٱللَّهُ هُوَ ٱلۡوَلِیُّ وَهُوَ یُحۡیِ ٱلۡمَوۡتَىٰ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٩", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "بل اتخذ هؤلاء المشركون أولياء من دون الله يتولونهم، فالله وحده هو الوليُّ يتولاه عَبْدُه بالعبادة والطاعة، ويتولَّى عباده المؤمنين بإخراجهم من الظلمات إلى النور وإعانتهم في جميع أمورهم، وهو يحيي الموتى عند البعث، وهو على كل شيء قدير، لا يعجزه شيء.", "isBasmala": false, "translation_en": "Or have they adopted protectors besides him? But God is the Protector, and He gives life to the dead, and He has power over all things.", "translation_id": "Atau patutkah mereka mengambil pelindung-pelindung selain Allah? Maka Allah, Dialah pelindung (yang sebenarnya) dan Dia menghidupkan orang-orang yang mati, dan Dia adalah Maha Kuasa atas segala sesuatu.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 10, "text": "وَمَا ٱخۡتَلَفۡتُمۡ فِیهِ مِن شَیۡءࣲ فَحُكۡمُهُۥۤ إِلَى ٱللَّهِۚ ذَ ٰلِكُمُ ٱللَّهُ رَبِّی عَلَیۡهِ تَوَكَّلۡتُ وَإِلَیۡهِ أُنِیبُ ۝١٠", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "وما اختلفتم فيه- أيها الناس- من شيء من أمور دينكم، فالحكم فيه مردُّه إلى الله في كتابه وسنة رسوله صلى الله عليه وسلم. ذلكم الله ربي وربكم، عليه وحده توكلت في أموري، وإليه أرجع في جميع شؤوني.", "isBasmala": false, "translation_en": "Whatever matter you differ about, its judgment rests with God. \"Such is God, my Lord, in Whom I trust, and unto Him I repent.\"", "translation_id": "Tentang sesuatu apapun kamu berselisih, maka putusannya (terserah) kepada Allah. (Yang mempunyai sifat-sifat demikian) itulah Allah Tuhanku. Kepada-Nya lah aku bertawakkal dan kepada-Nya-lah aku kembali.", "manzil": 6, "manzil_display": ""}], "484": [{"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 11, "text": "فَاطِرُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَ ٰجࣰا وَمِنَ ٱلۡأَنۡعَـٰمِ أَزۡوَ ٰجࣰا یَذۡرَؤُكُمۡ فِیهِۚ لَیۡسَ كَمِثۡلِهِۦ شَیۡءࣱۖ وَهُوَ ٱلسَّمِیعُ ٱلۡبَصِیرُ ۝١١", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "الله سبحانه وتعالى هو خالق السماوات والأرض ومبدعهما بقدرته ومشيئته وحكمته، جعل لكم من أنفسكم أزواجًا؛ لتسكنوا إليها، وجعل لكم من الأنعام أزواجًا ذكورًا وإناثًا، يكثركم بسببه بالتوالد، ليس يشبهه تعالى ولا يماثله شيء من مخلوقاته، لا في ذاته ولا في أسمائه ولا في صفاته ولا في أفعاله؛ لأن أسماءه كلَّها حسنى، وصفاتِه صفات كمال وعظمة، وأفعالَه تعالى أوجد بها المخلوقات العظيمة من غير مشارك، وهو السميع البصير، لا يخفى عليه مِن أعمال خلقه وأقوالهم شيء، وسيجازيهم على ذلك.", "isBasmala": false, "translation_en": "Originator of the heavens and the earth. He made for you mates from among yourselves, and pairs of animals, by means of which He multiplies you. There is nothing like Him. He is the Hearing, the Seeing.", "translation_id": "(Dia) Pencipta langit dan bumi. Dia menjadikan bagi kamu dari jenis kamu sendiri pasangan-pasangan dan dari jenis binatang ternak pasangan-pasangan (pula), dijadikan-Nya kamu berkembang biak dengan jalan itu. Tidak ada sesuatupun yang serupa dengan Dia, dan Dialah yang Maha Mendengar dan Melihat.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 12, "text": "لَهُۥ مَقَالِیدُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّهُۥ بِكُلِّ شَیۡءٍ عَلِیمࣱ ۝١٢", "juz": 25, "hizb": "(* ح 49*)", "tafsir": "له سبحانه وتعالى ملك السماوات والأرض، وبيده مفاتيح الرحمة والأرزاق، يوسِّع رزقه على مَن يشاء مِن عباده ويضيِّقه على مَن يشاء، إنه تبارك وتعالى بكل شيء عليم، لا يخفى عليه شيء من أمور خلقه.", "isBasmala": false, "translation_en": "To Him belongs absolute control of the heavens and the earth. He spreads the bounties to whomever He wills, or reduces it. He is aware of all things.", "translation_id": "Kepunyaan-Nya-lah perbendaharaan langit dan bumi; Dia melapangkan rezeki bagi siapa yang dikehendaki-Nya dan menyempitkan(nya). Sesungguhnya Dia Maha Mengetahui segala sesuatu.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 13, "text": "۞ شَرَعَ لَكُم مِّنَ ٱلدِّینِ مَا وَصَّىٰ بِهِۦ نُوحࣰا وَٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ وَمَا وَصَّیۡنَا بِهِۦۤ إِبۡرَ ٰهِیمَ وَمُوسَىٰ وَعِیسَىٰۤۖ أَنۡ أَقِیمُوا۟ ٱلدِّینَ وَلَا تَتَفَرَّقُوا۟ فِیهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِینَ مَا تَدۡعُوهُمۡ إِلَیۡهِۚ ٱللَّهُ یَجۡتَبِیۤ إِلَیۡهِ مَن یَشَاۤءُ وَیَهۡدِیۤ إِلَیۡهِ مَن یُنِیبُ ۝١٣", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "شرع الله لكم- أيها الناس- من الدِّين الذي أوحيناه إليك -أيها الرسول، وهو الإسلام- ما وصَّى به نوحًا أن يعمله ويبلغه، وما وصينا به إبراهيم وموسى وعيسى (هؤلاء الخمسة هم أولو العزم من الرسل على المشهور) أن أقيموا الدين بالتوحيد وطاعة الله وعبادته دون مَن سواه، ولا تختلفوا في الدين الذي أمرتكم به، عَظُمَ على المشركين ما تدعوهم إليه من توحيد الله وإخلاص العبادة له، الله يصطفي للتوحيد مَن يشاء مِن خلقه، ويوفِّق للعمل بطاعته مَن يرجع إليه.", "isBasmala": false, "translation_en": "He prescribed for you the same religion He enjoined upon Noah, and what We inspired to you, and what We enjoined upon Abraham, and Moses, and Jesus: \"You shall uphold the religion, and be not divided therein.\" As for the idolaters, what you call them to is outrageous to them. God chooses to Himself whom He wills, and He guides to Himself whoever repents.", "translation_id": "Dia telah mensyari'atkan bagi kamu tentang agama apa yang telah diwasiatkan-Nya kepada Nuh dan apa yang telah Kami wahyukan kepadamu dan apa yang telah Kami wasiatkan kepada Ibrahim, Musa dan Isa yaitu: Tegakkanlah agama dan janganlah kamu berpecah belah tentangnya. Amat berat bagi orang-orang musyrik agama yang kamu seru mereka kepadanya. Allah menarik kepada agama itu orang yang dikehendaki-Nya dan memberi petunjuk kepada (agama)-Nya orang yang kembali (kepada-Nya).", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 14, "text": "وَمَا تَفَرَّقُوۤا۟ إِلَّا مِنۢ بَعۡدِ مَا جَاۤءَهُمُ ٱلۡعِلۡمُ بَغۡیَۢا بَیۡنَهُمۡۚ وَلَوۡلَا كَلِمَةࣱ سَبَقَتۡ مِن رَّبِّكَ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى لَّقُضِیَ بَیۡنَهُمۡۚ وَإِنَّ ٱلَّذِینَ أُورِثُوا۟ ٱلۡكِتَـٰبَ مِنۢ بَعۡدِهِمۡ لَفِی شَكࣲّ مِّنۡهُ مُرِیبࣲ ۝١٤", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "وما تفرَّق المشركون بالله في أديانهم فصاروا شيعًا وأحزابًا إلا مِن بعد ما جاءهم العلم وقامت الحجة عليهم، وما حملهم على ذلك إلا البغي والعناد، ولولا كلمة سبقت من ربك -أيها الرسول- بتأخير العذاب عنهم إلى أجل مسمى وهو يوم القيامة، لقضي بينهم بتعجيل عذاب الكافرين منهم. وإن الذين أورثوا التوراة والإنجيل من بعد هؤلاء المختلفين في الحق لفي شك من الدين والإيمان موقعٍ في الريبة والاختلاف المذموم.", "isBasmala": false, "translation_en": "They became divided only after knowledge came to them, out of resentment among themselves. Were it not for a predetermined decision from your Lord, judgment would have been pronounced between them. Indeed, those who were made to inherit the Book after them are in grave doubt about it.", "translation_id": "Dan mereka (ahli kitab) tidak berpecah belah, kecuali setelah datang pada mereka ilmu pengetahuan, karena kedengkian di antara mereka. Kalau tidaklah karena sesuatu ketetapan yang telah ada dari Tuhanmu dahulunya (untuk menangguhkan azab) sampai kepada waktu yang ditentukan, pastilah mereka telah dibinasakan. Dan sesungguhnya orang-orang yang diwariskan kepada mereka Al-Kitab (Taurat dan Injil) sesudah mereka, benar-benar berada dalam keraguan yang menggoncangkan tentang kitab itu.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 15, "text": "فَلِذَ ٰلِكَ فَٱدۡعُۖ وَٱسۡتَقِمۡ كَمَاۤ أُمِرۡتَۖ وَلَا تَتَّبِعۡ أَهۡوَاۤءَهُمۡۖ وَقُلۡ ءَامَنتُ بِمَاۤ أَنزَلَ ٱللَّهُ مِن كِتَـٰبࣲۖ وَأُمِرۡتُ لِأَعۡدِلَ بَیۡنَكُمُۖ ٱللَّهُ رَبُّنَا وَرَبُّكُمۡۖ لَنَاۤ أَعۡمَـٰلُنَا وَلَكُمۡ أَعۡمَـٰلُكُمۡۖ لَا حُجَّةَ بَیۡنَنَا وَبَیۡنَكُمُۖ ٱللَّهُ یَجۡمَعُ بَیۡنَنَاۖ وَإِلَیۡهِ ٱلۡمَصِیرُ ۝١٥", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "فإلى ذلك الدين القيِّم الذي شرعه الله للأنبياء ووصَّاهم به، فادع -أيها الرسول- عباد الله، واستقم كما أمرك الله، ولا تتبع أهواء الذين شكُّوا في الحق وانحرفوا عن الدين، وقل: صدَّقت بجميع الكتب المنزلة من السماء على الأنبياء، وأمرني ربي أن أعدل بينكم في الحكم، الله ربنا وربكم، لنا ثواب أعمالنا الصالحة، ولكم جزاء أعمالكم السيئة، لا خصومة ولا جدال بيننا وبينكم بعدما تبين الحق، الله يجمع بيننا وبينكم يوم القيامة، فيقضي بيننا بالحق فيما اختلفنا فيه، وإليه المرجع والمآب، فيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "To this go on inviting, and be upright as you were commanded, and do not follow their inclinations, and say, \"I believe in whatever Book God has sent down, and I was commanded to judge between you equitably. God is our Lord and your Lord. We have our deeds, and you have your deeds. Let there be no quarrel between us and you. God will bring us together, and to Him is the ultimate return.\"", "translation_id": "Maka karena itu serulah (mereka kepada agama ini) dan tetaplah sebagai mana diperintahkan kepadamu dan janganlah mengikuti hawa nafsu mereka dan katakanlah: \"Aku beriman kepada semua Kitab yang diturunkan Allah dan aku diperintahkan supaya berlaku adil diantara kamu. Allah-lah Tuhan kami dan Tuhan kamu. Bagi kami amal-amal kami dan bagi kamu amal-amal kamu. Tidak ada pertengkaran antara kami dan kamu, Allah mengumpulkan antara kita dan kepada-Nya-lah kembali (kita)\".", "manzil": 6, "manzil_display": ""}], "485": [{"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 16, "text": "وَٱلَّذِینَ یُحَاۤجُّونَ فِی ٱللَّهِ مِنۢ بَعۡدِ مَا ٱسۡتُجِیبَ لَهُۥ حُجَّتُهُمۡ دَاحِضَةٌ عِندَ رَبِّهِمۡ وَعَلَیۡهِمۡ غَضَبࣱ وَلَهُمۡ عَذَابࣱ شَدِیدٌ ۝١٦", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "والذين يجادلون في دين الله الذي أرسلتُ به محمدًا صلى الله عليه وسلم، مِن بعد ما استجاب الناس له وأسلموا، حجتهم ومجادلتهم باطلة ذاهبة عند ربهم، وعليهم من الله غضب في الدنيا، ولهم في الآخرة عذاب شديد، وهو النار.", "isBasmala": false, "translation_en": "As for those who dispute about God after having answered His call, their argument is invalid with their Lord; and upon them falls wrath; and a grievous torment awaits them.", "translation_id": "Dan orang-orang yang membantah (agama) Allah sesudah agama itu diterima maka bantahan mereka itu sia-sia saja, di sisi Tuhan mereka. Mereka mendapat kemurkaan (Allah) dan bagi mereka azab yang sangat keras.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 17, "text": "ٱللَّهُ ٱلَّذِیۤ أَنزَلَ ٱلۡكِتَـٰبَ بِٱلۡحَقِّ وَٱلۡمِیزَانَۗ وَمَا یُدۡرِیكَ لَعَلَّ ٱلسَّاعَةَ قَرِیبࣱ ۝١٧", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "الله الذي أنزل القرآن وسائر الكتب المنزلة بالصدق، وأنزل الميزان وهو العدل؛ ليحكم بين الناس بالإنصاف. وأي شيء يدريك ويُعْلمك لعل الساعة التي تقوم فيها القيامة قريب؟", "isBasmala": false, "translation_en": "It is God who revealed the Book with the truth, and the Balance. And what will make you realize that perhaps the Hour is near?", "translation_id": "Allah-lah yang menurunkan kitab dengan (membawa) kebenaran dan (menurunkan) neraca (keadilan). Dan tahukah kamu, boleh jadi hari kiamat itu (sudah) dekat?", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 18, "text": "یَسۡتَعۡجِلُ بِهَا ٱلَّذِینَ لَا یُؤۡمِنُونَ بِهَاۖ وَٱلَّذِینَ ءَامَنُوا۟ مُشۡفِقُونَ مِنۡهَا وَیَعۡلَمُونَ أَنَّهَا ٱلۡحَقُّۗ أَلَاۤ إِنَّ ٱلَّذِینَ یُمَارُونَ فِی ٱلسَّاعَةِ لَفِی ضَلَـٰلِۭ بَعِیدٍ ۝١٨", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "يستعجل بمجيء الساعة الذين لا يؤمنون بها؛ تهكمًا واستهزاءً، والذين آمنوا بها خائفون من قيامها، ويعلمون أنها الحق الذي لا شك فيه. ألا إن الذين يخاصمون في قيام الساعة لفي ضلال بعيد عن الحق.", "isBasmala": false, "translation_en": "Those who do not believe in it seek to hasten it; but those who believe are apprehensive of it, and they know it to be the truth. Absolutely, those who question the Hour are in distant error.", "translation_id": "Orang-orang yang tidak beriman kepada hari kiamat meminta supaya hari itu segera didatangkan dan orang-orang yang beriman merasa takut kepadanya dan mereka yakin bahwa kiamat itu adalah benar (akan terjadi). Ketahuilah bahwa sesungguhnya orang-orang yang membantah tentang terjadinya kiamat itu benar-benar dalam kesesatan yang jauh.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 19, "text": "ٱللَّهُ لَطِیفُۢ بِعِبَادِهِۦ یَرۡزُقُ مَن یَشَاۤءُۖ وَهُوَ ٱلۡقَوِیُّ ٱلۡعَزِیزُ ۝١٩", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "الله لطيف بعباده، يوسِّع الرزق على مَن يشاء، ويضيِّقه على مَن يشاء وَفْق حكمته سبحانه، وهو القوي الذي له القوة كلها، العزيز في انتقامه من أهل معاصيه.", "isBasmala": false, "translation_en": "God is kind towards His worshipers. He provides for whomever He wills. He is the Powerful, the Honorable.", "translation_id": "Allah Maha lembut terhadap hamba-hamba-Nya; Dia memberi rezeki kepada yang di kehendaki-Nya dan Dialah Yang Maha Kuat lagi Maha Perkasa.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 20, "text": "مَن كَانَ یُرِیدُ حَرۡثَ ٱلۡـَٔاخِرَةِ نَزِدۡ لَهُۥ فِی حَرۡثِهِۦۖ وَمَن كَانَ یُرِیدُ حَرۡثَ ٱلدُّنۡیَا نُؤۡتِهِۦ مِنۡهَا وَمَا لَهُۥ فِی ٱلۡـَٔاخِرَةِ مِن نَّصِیبٍ ۝٢٠", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "من كان يريد بعمله ثواب الآخرة فأدى حقوق الله وأنفق في الدعوة إلى الدين، نزد له في عمله الحسن، فنضاعف له ثواب الحسنة إلى عشر أمثالها إلى ما شاء الله من الزيادة، ومن كان يريد بعمله الدنيا وحدها، نؤته منها ما قسمناه له، وليس له في الآخرة شيء من الثواب.", "isBasmala": false, "translation_en": "Whoever desires the harvest of the Hereafter, We increase for him his harvest; and whoever desires the harvest of this world, We give him thereof, and he has no share of the Hereafter.", "translation_id": "Barang siapa yang menghendaki keuntungan di akhirat akan Kami tambah keuntungan itu baginya dan barang siapa yang menghendaki keuntungan di dunia Kami berikan kepadanya sebagian dari keuntungan dunia dan tidak ada baginya suatu bahagianpun di akhirat.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 21, "text": "أَمۡ لَهُمۡ شُرَكَـٰۤؤُا۟ شَرَعُوا۟ لَهُم مِّنَ ٱلدِّینِ مَا لَمۡ یَأۡذَنۢ بِهِ ٱللَّهُۚ وَلَوۡلَا كَلِمَةُ ٱلۡفَصۡلِ لَقُضِیَ بَیۡنَهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِینَ لَهُمۡ عَذَابٌ أَلِیمࣱ ۝٢١", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "بل ألهؤلاء المشركين بالله شركاء في شركهم وضلالتهم، ابتدعوا لهم من الدين والشرك ما لم يأذن به الله؟ ولولا قضاء الله وقدره بإمهالهم، وأن لا يعجل لهم العذاب في الدنيا، لقضي بينهم بتعجيل العذاب لهم. وإن الكافرين بالله لهم يوم القيامة عذاب مؤلم موجع.", "isBasmala": false, "translation_en": "Or is it that they have partners who litigate for them religious laws never authorized by God? Were it not for the conclusive decision, it would have been settled between them. The wicked will have a painful punishment.", "translation_id": "Apakah mereka mempunyai sembahan-sembahan selain Allah yang mensyariatkan untuk mereka agama yang tidak diizinkan Allah? Sekiranya tak ada ketetapan yang menentukan (dari Allah) tentulah mereka telah dibinasakan. Dan sesungguhnya orang-orang yang zalim itu akan memperoleh azab yang amat pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 22, "text": "تَرَى ٱلظَّـٰلِمِینَ مُشۡفِقِینَ مِمَّا كَسَبُوا۟ وَهُوَ وَاقِعُۢ بِهِمۡۗ وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فِی رَوۡضَاتِ ٱلۡجَنَّاتِۖ لَهُم مَّا یَشَاۤءُونَ عِندَ رَبِّهِمۡۚ ذَ ٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِیرُ ۝٢٢", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "ترى -أيها الرسول- الكافرين يوم القيامة خائفين من عقاب الله على ما كسبوا في الدنيا من أعمال خبيثة، والعذاب نازل بهم، وهم ذائقوه لا محالة، والذين آمنوا بالله وأطاعوه في بساتين الجنات وقصورها ونعيم الآخرة، لهم ما تشتهيه أنفسهم عند ربهم، ذلك الذي أعطاه الله لهم من الفضل والكرامة هو الفضل الذي لا يوصف، ولا تهتدي إليه العقول.", "isBasmala": false, "translation_en": "You will see the unjust terrified of what they have earned, and it will befall them. As for those who believe and do good deeds, they will be in the Meadows of the Gardens; they will have whatever they please in the presence of their Lord; that is the supreme blessing.", "translation_id": "Kamu lihat orang-orang yang zalim sangat ketakutan karena kejahatan-kejahatan yang telah mereka kerjakan, sedang siksaan menimpa mereka. Dan orang-orang yang beriman serta mengerjakan amal saleh (berada) di dalam taman-taman surga, mereka memperoleh apa yang mereka kehendaki di sisi Tuhan mereka. Yang demikian itu adalah karunia yang besar.", "manzil": 6, "manzil_display": ""}], "486": [{"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 23, "text": "ذَ ٰلِكَ ٱلَّذِی یُبَشِّرُ ٱللَّهُ عِبَادَهُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِۗ قُل لَّاۤ أَسۡـَٔلُكُمۡ عَلَیۡهِ أَجۡرًا إِلَّا ٱلۡمَوَدَّةَ فِی ٱلۡقُرۡبَىٰۗ وَمَن یَقۡتَرِفۡ حَسَنَةࣰ نَّزِدۡ لَهُۥ فِیهَا حُسۡنًاۚ إِنَّ ٱللَّهَ غَفُورࣱ شَكُورٌ ۝٢٣", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "ذلك الذي أخبرتكم به- أيها الناس- من النعيم والكرامة في الآخرة هو البشرى التي يبشر الله بها عباده الذين آمنوا به في الدنيا وأطاعوه. قل -أيها الرسول- للذين يشكون في الساعة من مشركي قومك: لا أسألكم على ما أدعوكم إليه من الحق الذي جئتكم به عوضًا من أموالكم، إلا أن تَوَدُّوني في قرابتي منكم، وتَصِلوا الرحم التي بيني وبينكم. ومن يكتسب حسنة نضاعفها له بعشر فصاعدًا. إن الله غفور لذنوب عباده، شكور لحسناتهم وطاعتهم إياه.", "isBasmala": false, "translation_en": "That is the good news God gives to His servants who believe and do good deeds. Say, \"I ask of you no wage for it, except affection among the near of kin.\" Whoever does a good deed, We will increase its goodness for him. God is Forgiving and Appreciative.", "translation_id": "Itulah (karunia) yang (dengan itu) Allah menggembirakan hamba-hamba-Nya yang beriman dan mengerjakan amal yang saleh. Katakanlah: \"Aku tidak meminta kepadamu sesuatu upahpun atas seruanku kecuali kasih sayang dalam kekeluargaan\". Dan siapa yang mengerjakan kebaikan akan Kami tambahkan baginya kebaikan pada kebaikannya itu. Sesungguhnya Allah Maha Pengampun lagi Maha Mensyukuri.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 24, "text": "أَمۡ یَقُولُونَ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبࣰاۖ فَإِن یَشَإِ ٱللَّهُ یَخۡتِمۡ عَلَىٰ قَلۡبِكَۗ وَیَمۡحُ ٱللَّهُ ٱلۡبَـٰطِلَ وَیُحِقُّ ٱلۡحَقَّ بِكَلِمَـٰتِهِۦۤۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝٢٤", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "بل أيقول هؤلاء المشركون: اختلق محمد الكذب على الله، فجاء بالذي يتلوه علينا اختلاقًا من عند نفسه؟ فإن يشأ الله يطبع على قلبك -أيها الرسول- لو فعلت ذلك. ويُذْهِبُ الله الباطل فيمحقه، ويحق الحق بكلماته التي لا تتبدل ولا تتغيَّر، وبوعده الصادق الذي لا يتخلف. إن الله عليم بما في قلوب العباد، لا يخفى عليه شيء منه.", "isBasmala": false, "translation_en": "Or do they say, \"He forged a lie about God.\" If God so willed, He could have sealed your heart. But God obliterates the false, and confirm the true by His Words. He knows what is in the hearts.", "translation_id": "Bahkan mereka mengatakan: \"Dia (Muhammad) telah mengada-adakan dusta terhadap Allah\". Maka jika Allah menghendaki niscaya Dia mengunci mati hatimu; dan Allah menghapuskan yang batil dan membenarkan yang hak dengan kalimat-kalimat-Nya (Al Quran). Sesungguhnya Dia Maha Mengetahui segala isi hati.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 25, "text": "وَهُوَ ٱلَّذِی یَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ وَیَعۡفُوا۟ عَنِ ٱلسَّیِّـَٔاتِ وَیَعۡلَمُ مَا تَفۡعَلُونَ ۝٢٥", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "والله سبحانه وتعالى هو الذي يقبل التوبة عن عباده إذا رجعوا إلى توحيد الله وطاعته، ويعفو عن السيئات، ويعلم ما تصنعون من خير وشر، لا يخفى عليه شيء من ذلك، وهو مجازيكم به.", "isBasmala": false, "translation_en": "It is He who accepts the repentance of His worshipers, and remits the sins, and knows what you do.", "translation_id": "Dan Dialah yang menerima taubat dari hamba-hamba-Nya dan memaafkan kesalahan-kesalahan dan mengetahui apa yang kamu kerjakan,", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 26, "text": "وَیَسۡتَجِیبُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَیَزِیدُهُم مِّن فَضۡلِهِۦۚ وَٱلۡكَـٰفِرُونَ لَهُمۡ عَذَابࣱ شَدِیدࣱ ۝٢٦", "juz": 25, "hizb": "(*¼ ح 49*)", "tafsir": "ويستجيب الذين آمنوا بالله ورسوله لربهم لِمَا دعاهم إليه وينقادون له، ويزيدهم من فضله توفيقًا ومضاعفة في الأجر والثواب. والكافرون بالله ورسوله لهم يوم القيامة عذاب شديد موجع مؤلم.", "isBasmala": false, "translation_en": "And He answers those who believe and do good deeds, and He increases them of His grace. But the disbelievers will suffer a terrible punishment.", "translation_id": "dan Dia memperkenankan (doa) orang-orang yang beriman serta mengerjakan amal yang saleh dan menambah (pahala) kepada mereka dari karunia-Nya. Dan orang-orang yang kafir bagi mereka azab yang sangat keras.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 27, "text": "۞ وَلَوۡ بَسَطَ ٱللَّهُ ٱلرِّزۡقَ لِعِبَادِهِۦ لَبَغَوۡا۟ فِی ٱلۡأَرۡضِ وَلَـٰكِن یُنَزِّلُ بِقَدَرࣲ مَّا یَشَاۤءُۚ إِنَّهُۥ بِعِبَادِهِۦ خَبِیرُۢ بَصِیرࣱ ۝٢٧", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "ولو بسط الله الرزق لعباده فوسَّعه عليهم، لبغوا في الأرض أشَرًا وبطرًا، ولطغى بعضهم على بعض، ولكن الله ينزل أرزاقهم بقدر ما يشاء لكفايتهم. إنه بعباده خبير بما يصلحهم، بصير بتدبيرهم وتصريف أحوالهم.", "isBasmala": false, "translation_en": "If God were to increase the provision to His servants, they would transgress on earth; but He sends down in precise measure whatever He wills. Surely, regarding His servants, He is Expert and Observant.", "translation_id": "Dan jikalau Allah melapangkan rezeki kepada hamba-hamba-Nya tentulah mereka akan melampaui batas di muka bumi, tetapi Allah menurunkan apa yang dikehendaki-Nya dengan ukuran. Sesungguhnya Dia Maha Mengetahui (keadaan) hamba-hamba-Nya lagi Maha Melihat.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 28, "text": "وَهُوَ ٱلَّذِی یُنَزِّلُ ٱلۡغَیۡثَ مِنۢ بَعۡدِ مَا قَنَطُوا۟ وَیَنشُرُ رَحۡمَتَهُۥۚ وَهُوَ ٱلۡوَلِیُّ ٱلۡحَمِیدُ ۝٢٨", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "والله وحده هو الذي ينزل المطر من السماء، فيغيثهم به من بعد ما يئسوا من نزوله، وينشر رحمته في خلقه، فيعمهم بالغيث، وهو الوليُّ الذي يتولى عباده بإحسانه وفضله، الحميد في ولايته وتدبيره.", "isBasmala": false, "translation_en": "It is He who brings down the rain after they have despaired, and unfolds His mercy. He is the Guardian, the Praised.", "translation_id": "Dan Dialah Yang menurunkan hujan sesudah mereka berputus asa dan menyebarkan rahmat-Nya. Dan Dialah Yang Maha Pelindung lagi Maha Terpuji.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 29, "text": "وَمِنۡ ءَایَـٰتِهِۦ خَلۡقُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَثَّ فِیهِمَا مِن دَاۤبَّةࣲۚ وَهُوَ عَلَىٰ جَمۡعِهِمۡ إِذَا یَشَاۤءُ قَدِیرࣱ ۝٢٩", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "ومن آياته الدالة على عظمته وقدرته وسلطانه، خَلْقُ السموات والأرض على غير مثال سابق، وما نشر فيهما من أصناف الدواب، وهو على جَمْع الخلق بعد موتهم لموقف القيامة إذا يشاء قدير، لا يتعذر عليه شيء.", "isBasmala": false, "translation_en": "And of His signs are the creation of the heavens and the earth, and the creatures He has spread throughout them; and He is Able to gather them at will.", "translation_id": "Di antara (ayat-ayat) tanda-tanda-Nya ialah menciptakan langit dan bumi dan makhluk-makhluk yang melata Yang Dia sebarkan pada keduanya. Dan Dia Maha Kuasa mengumpulkan semuanya apabila dikehendaki-Nya.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 30, "text": "وَمَاۤ أَصَـٰبَكُم مِّن مُّصِیبَةࣲ فَبِمَا كَسَبَتۡ أَیۡدِیكُمۡ وَیَعۡفُوا۟ عَن كَثِیرࣲ ۝٣٠", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "وما أصابكم- أيها الناس- من مصيبة في دينكم ودنياكم فبما كسبتم من الذنوب والآثام، ويعفو لكم ربكم عن كثير من السيئات، فلا يؤاخذكم بها.", "isBasmala": false, "translation_en": "Whatever misfortune befalls you, it is because of what your hands have earned; and yet He pardons much.", "translation_id": "Dan apa saja musibah yang menimpa kamu maka adalah disebabkan oleh perbuatan tanganmu sendiri, dan Allah memaafkan sebagian besar (dari kesalahan-kesalahanmu).", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 31, "text": "وَمَاۤ أَنتُم بِمُعۡجِزِینَ فِی ٱلۡأَرۡضِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرࣲ ۝٣١", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "وما أنتم- أيها الناس- بمعجزين قدرة الله عليكم، ولا فائتيه، وما لكم من دون الله مِن وليٍّ يتولى أموركم، فيوصل لكم المنافع، ولا نصير يدفع عنكم المضارَّ.", "isBasmala": false, "translation_en": "You are not the ones to interfere on earth; and besides God, you have no ally, and no helper.", "translation_id": "Dan kamu tidak dapat melepaskan diri (dari azab Allah) di muka bumi, dan kamu tidak memperoleh seorang pelindung dan tidak pula penolong selain Allah.", "manzil": 6, "manzil_display": ""}], "487": [{"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 32, "text": "وَمِنۡ ءَایَـٰتِهِ ٱلۡجَوَارِ فِی ٱلۡبَحۡرِ كَٱلۡأَعۡلَـٰمِ ۝٣٢", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "ومن آياته الدالة على قدرته الباهرة وسلطانه القاهر السفن العظيمة كالجبال تجري في البحر. إن يشأ الله الذي أجرى هذه السفن في البحر يُسكن الريح، فتَبْقَ السفن سواكن على ظهر البحر لا تجري، إن في جَرْي هذه السفن ووقوفها في البحر بقدرة الله لَعظات وحججًا بيِّنة على قدرة الله لكل صبار على طاعة الله، شكور لنعمه وأفضاله.", "isBasmala": false, "translation_en": "And of His signs are the ships sailing the sea like flags.", "translation_id": "Dan di antara tanda-tanda kekuasaan-Nya ialah kapal-kapal di tengah (yang berlayar) di laut seperti gunung-gunung.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 33, "text": "إِن یَشَأۡ یُسۡكِنِ ٱلرِّیحَ فَیَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦۤۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورٍ ۝٣٣", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "ومن آياته الدالة على قدرته الباهرة وسلطانه القاهر السفن العظيمة كالجبال تجري في البحر. إن يشأ الله الذي أجرى هذه السفن في البحر يُسكن الريح، فتَبْقَ السفن سواكن على ظهر البحر لا تجري، إن في جَرْي هذه السفن ووقوفها في البحر بقدرة الله لَعظات وحججًا بيِّنة على قدرة الله لكل صبار على طاعة الله، شكور لنعمه وأفضاله.", "isBasmala": false, "translation_en": "If He willed, He could have stilled the winds, leaving them motionless on its surface. Surely in that are signs for every disciplined, grateful person.", "translation_id": "Jika Dia menghendaki, Dia akan menenangkan angin, maka jadilah kapal-kapal itu terhenti di permukaan laut. Sesungguhnya pada yang demikian itu terdapat tanda-tanda (kekuasaannya) bagi setiap orang yang banyak bersabar dan banyak bersyukur,", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 34, "text": "أَوۡ یُوبِقۡهُنَّ بِمَا كَسَبُوا۟ وَیَعۡفُ عَن كَثِیرࣲ ۝٣٤", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "أو يهلكِ السفن بالغرق بسبب ذنوب أهلها، ويعفُ عن كثير من الذنوب فلا يعاقب عليها.", "isBasmala": false, "translation_en": "Or He could wreck them, because of what they have earned. And yet He pardons much.", "translation_id": "atau kapal-kapal itu dibinasakan-Nya karena perbuatan mereka atau Dia memberi maaf sebagian besar (dari mereka).", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 35, "text": "وَیَعۡلَمَ ٱلَّذِینَ یُجَـٰدِلُونَ فِیۤ ءَایَـٰتِنَا مَا لَهُم مِّن مَّحِیصࣲ ۝٣٥", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "ويَعْلَم الذين يجادلون بالباطل في آياتنا الدالة على توحيدنا، ما لهم من محيد ولا ملجأ من عقاب الله، إذا عاقبهم على ذنوبهم وكفرهم به.", "isBasmala": false, "translation_en": "Those who dispute Our signs know that there is no asylum for them.", "translation_id": "Dan supaya orang-orang yang membantah ayat-ayat (kekuasaan) Kami mengetahui bahwa mereka sekali-kali tidak akan memperoleh jalan ke luar (dari siksaan).", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 36, "text": "فَمَاۤ أُوتِیتُم مِّن شَیۡءࣲ فَمَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَمَا عِندَ ٱللَّهِ خَیۡرࣱ وَأَبۡقَىٰ لِلَّذِینَ ءَامَنُوا۟ وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ ۝٣٦", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "فما أوتيتم- أيها الناس- من شيء من المال أو البنين وغير ذلك فهو متاع لكم في الحياة الدنيا، سُرعان ما يزول، وما عند الله تعالى من نعيم الجنة المقيم خير وأبقى للذين آمنوا بالله ورسله، وعلى ربهم يتوكلون.", "isBasmala": false, "translation_en": "Whatever thing you are given is only the provision of this life. But what God possesses is better and more lasting for those who believe and rely on their Lord.", "translation_id": "Maka sesuatu yang diberikan kepadamu, itu adalah kenikmatan hidup di dunia; dan yang ada pada sisi Allah lebih baik dan lebih kekal bagi orang-orang yang beriman, dan hanya kepada Tuhan mereka, mereka bertawakkal.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 37, "text": "وَٱلَّذِینَ یَجۡتَنِبُونَ كَبَـٰۤىِٕرَ ٱلۡإِثۡمِ وَٱلۡفَوَ ٰحِشَ وَإِذَا مَا غَضِبُوا۟ هُمۡ یَغۡفِرُونَ ۝٣٧", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "والذين يجتنبون كبائر ما نهى الله عنه، وما فَحُش وقَبُح من أنواع المعاصي، وإذا ما غضبوا على مَن أساء إليهم هم يغفرون الإساءة، ويصفحون عن عقوبة المسيء؛ طلبًا لثواب الله تعالى وعفوه، وهذا من محاسن الأخلاق.", "isBasmala": false, "translation_en": "And those who avoid major sins and indecencies; and if they become angry, they forgive.", "translation_id": "Dan (bagi) orang-orang yang menjauhi dosa-dosa besar dan perbuatan-perbuatan keji, dan apabila mereka marah mereka memberi maaf.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 38, "text": "وَٱلَّذِینَ ٱسۡتَجَابُوا۟ لِرَبِّهِمۡ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَمۡرُهُمۡ شُورَىٰ بَیۡنَهُمۡ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ ۝٣٨", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "والذين استجابوا لربهم حين دعاهم إلى توحيده وطاعته، وأقاموا الصلاة المفروضة بحدودها في أوقاتها، وإذا أرادوا أمرًا تشاوروا فيه، ومما أعطيناهم من الأموال يتصدقون في سبيل الله، ويؤدون ما فرض الله عليهم من الحقوق لأهلها من زكاة ونفقة وغير ذلك من وجوه الإنفاق.", "isBasmala": false, "translation_en": "And those who respond to their Lord, and pray regularly, and conduct their affairs by mutual consultation, and give of what We have provided them.", "translation_id": "Dan (bagi) orang-orang yang menerima (mematuhi) seruan Tuhannya dan mendirikan shalat, sedang urusan mereka (diputuskan) dengan musyawarat antara mereka; dan mereka menafkahkan sebagian dari rezeki yang Kami berikan kepada mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 39, "text": "وَٱلَّذِینَ إِذَاۤ أَصَابَهُمُ ٱلۡبَغۡیُ هُمۡ یَنتَصِرُونَ ۝٣٩", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "والذين إذا أصابهم الظلم هم ينتصرون ممن بغى عليهم مِن غير أن يعتدوا، وإن صبروا ففي عاقبة صبرهم خير كثير.", "isBasmala": false, "translation_en": "And those who, when wronged, defend themselves.", "translation_id": "Dan ( bagi) orang-orang yang apabila mereka diperlakukan dengan zalim mereka membela diri.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 40, "text": "وَجَزَ ٰۤؤُا۟ سَیِّئَةࣲ سَیِّئَةࣱ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا یُحِبُّ ٱلظَّـٰلِمِینَ ۝٤٠", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "وجزاء سيئة المسيء عقوبته بسيئة مثلها من غير زيادة، فمن عفا عن المسيء، وترك عقابه، وأصلح الودَّ بينه وبين المعفو عنه ابتغاء وجه الله، فأَجْرُ عفوه ذلك على الله. إن الله لا يحب الظالمين الذين يبدؤون بالعدوان على الناس، ويسيئون إليهم.", "isBasmala": false, "translation_en": "The repayment of a bad action is one equivalent to it. But whoever pardons and makes reconciliation, his reward lies with God. He does not love the unjust.", "translation_id": "Dan balasan suatu kejahatan adalah kejahatan yang serupa, maka barang siapa memaafkan dan berbuat baik maka pahalanya atas (tanggungan) Allah. Sesungguhnya Dia tidak menyukai orang-orang yang zalim.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 41, "text": "وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُو۟لَـٰۤىِٕكَ مَا عَلَیۡهِم مِّن سَبِیلٍ ۝٤١", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "ولمن انتصر ممن ظلمه من بعد ظلمه له فأولئك ما عليهم من مؤاخذة.", "isBasmala": false, "translation_en": "As for those who retaliate after being wronged, there is no blame on them.", "translation_id": "Dan sesungguhnya orang-orang yang membela diri sesudah teraniaya, tidak ada satu dosapun terhadap mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 42, "text": "إِنَّمَا ٱلسَّبِیلُ عَلَى ٱلَّذِینَ یَظۡلِمُونَ ٱلنَّاسَ وَیَبۡغُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابٌ أَلِیمࣱ ۝٤٢", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "إنما المؤاخذة على الذين يتعدَّون على الناس ظلمًا وعدوانًا، ويتجاوزون الحدَّ الذي أباحه لهم ربهم إلى ما لم يأذن لهم فيه، فيفسدون في الأرض بغير الحق، أولئك لهم يوم القيامة عذاب مؤلم موجع.", "isBasmala": false, "translation_en": "Blame lies on those who wrong people, and commit aggression in the land without right. These will have a painful punishment.", "translation_id": "Sesungguhnya dosa itu atas orang-orang yang berbuat zalim kepada manusia dan melampaui batas di muka bumi tanpa hak. Mereka itu mendapat azab yang pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 43, "text": "وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَ ٰلِكَ لَمِنۡ عَزۡمِ ٱلۡأُمُورِ ۝٤٣", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "ولمن صبر على الأذى، وقابل الإساءة بالعفو والصفح والسَّتر، إن ذلك من عزائم الأمور المشكورة والأفعال الحميدة التي أمر الله بها، ورتَّب لها ثوابًا جريلا وثناءً حميدًا.", "isBasmala": false, "translation_en": "But whoever endures patiently and forgives-that is a sign of real resolve.", "translation_id": "Tetapi orang yang bersabar dan memaafkan, sesungguhnya (perbuatan) yang demikian itu termasuk hal-hal yang diutamakan.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 44, "text": "وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن وَلِیࣲّ مِّنۢ بَعۡدِهِۦۗ وَتَرَى ٱلظَّـٰلِمِینَ لَمَّا رَأَوُا۟ ٱلۡعَذَابَ یَقُولُونَ هَلۡ إِلَىٰ مَرَدࣲّ مِّن سَبِیلࣲ ۝٤٤", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "ومن يضلله الله عن الرشاد بسبب ظلمه فليس له من ناصر يهديه سبيل الرشاد. وترى -أيها الرسول- الكافرين بالله يوم القيامة - حين رأوا العذاب- يقولون لربهم: هل لنا من سبيل إلى الرجوع إلى الدنيا؛ لنعمل بطاعتك؟ فلا يجابون إلى ذلك.", "isBasmala": false, "translation_en": "Whoever God leaves astray has no protector apart from Him. And you will see the transgressors, when they see the torment, saying, \"Is there a way of going back?\"", "translation_id": "Dan siapa yang disesatkan Allah maka tidak ada baginya seorang pemimpinpun sesudah itu. Dan kamu akan melihat orang-orang yang zalim ketika mereka melihat azab berkata: \"Adakah kiranya jalan untuk kembali (ke dunia)?\"", "manzil": 6, "manzil_display": ""}], "488": [{"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 45, "text": "وَتَرَىٰهُمۡ یُعۡرَضُونَ عَلَیۡهَا خَـٰشِعِینَ مِنَ ٱلذُّلِّ یَنظُرُونَ مِن طَرۡفٍ خَفِیࣲّۗ وَقَالَ ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ ٱلۡخَـٰسِرِینَ ٱلَّذِینَ خَسِرُوۤا۟ أَنفُسَهُمۡ وَأَهۡلِیهِمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۗ أَلَاۤ إِنَّ ٱلظَّـٰلِمِینَ فِی عَذَابࣲ مُّقِیمࣲ ۝٤٥", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "وترى -أيها الرسول- هؤلاء الظالمين يُعْرَضون على النار خاضعين متذللين ينظرون إلى النار مِن طرْف ذليل ضعيف من الخوف والهوان. وقال الذين آمنوا بالله ورسوله في الجنة، لما عاينوا ما حلَّ بالكفار من خسران: إن الخاسرين حقًا هم الذين خسروا أنفسهم وأهليهم يوم القيامة بدخول النار. ألا إن الظالمين- يوم القيامة- في عذاب دائم، لا ينقطع عنهم، ولا يزول.", "isBasmala": false, "translation_en": "And you will see them exposed to it, cowering from disgrace, looking with concealed eyes. Those who believed will say, \"The losers are those who lost themselves and their families on the Day of Resurrection.\" Indeed, the evildoers are in a lasting torment.", "translation_id": "Dan kamu akan melihat mereka dihadapkan ke neraka dalam keadaan tunduk karena (merasa) hina, mereka melihat dengan pandangan yang lesu. Dan orang-orang yang beriman berkata: \"Sesungguhnya orang-orang yang merugi ialah orang-orang yang kehilangan diri mereka sendiri dan (kehilangan) keluarga mereka pada hari kiamat. Ingatlah, sesungguhnya orang-orang yang zalim itu berada dalam azab yang kekal.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 46, "text": "وَمَا كَانَ لَهُم مِّنۡ أَوۡلِیَاۤءَ یَنصُرُونَهُم مِّن دُونِ ٱللَّهِۗ وَمَن یُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِن سَبِیلٍ ۝٤٦", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "وما كان لهؤلاء الكافرين حين يعذبهم الله يوم القيامة من أعوان ونصراء ينصرونهم من عذاب الله. ومن يضلله الله بسبب كفره وظلمه، فما له من طريق يصل به إلى الحق في الدنيا، وإلى الجنة في الآخرة؛ لأنه قد سدَّت عليه طرق النجاة، فالهداية والإضلال بيده سبحانه وتعالى دون سواه.", "isBasmala": false, "translation_en": "They will have no allies to support them against God. Whomever God leaves astray has no way out.", "translation_id": "Dan mereka sekali-kali tidak mempunyai pelindung-pelindung yang dapat menolong mereka selain Allah. Dan siapa yang disesatkan Allah maka tidaklah ada baginya satu jalanpun (untuk mendapat petunjuk).", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 47, "text": "ٱسۡتَجِیبُوا۟ لِرَبِّكُم مِّن قَبۡلِ أَن یَأۡتِیَ یَوۡمࣱ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۚ مَا لَكُم مِّن مَّلۡجَإࣲ یَوۡمَىِٕذࣲ وَمَا لَكُم مِّن نَّكِیرࣲ ۝٤٧", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "استجيبوا لربكم- أيها الكافرون- بالإيمان والطاعة من قبل أن يأتي يوم القيامة، الذي لا يمكن رده، ما لكم من ملجأ يومئذ ينجيكم من العذاب، ولا مكان يستركم، وتتنكرون فيه. وفي الآية دليل على ذم التسويف، وفيها الأمر بالمبادرة إلى كل عمل صالح يعرض للعبد، فإن للتأخير آفات وموانع.", "isBasmala": false, "translation_en": "Respond to your Lord before there comes from God a Day that cannot be turned back. You will have no refuge on that Day, and no possibility of denial.", "translation_id": "Patuhilah seruan Tuhanmu sebelum datang dari Allah suatu hari yang tidak dapat ditolak kedatangannya. Kamu tidak memperoleh tempat berlindung pada hari itu dan tidak (pula) dapat mengingkari (dosa-dosamu).", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 48, "text": "فَإِنۡ أَعۡرَضُوا۟ فَمَاۤ أَرۡسَلۡنَـٰكَ عَلَیۡهِمۡ حَفِیظًاۖ إِنۡ عَلَیۡكَ إِلَّا ٱلۡبَلَـٰغُۗ وَإِنَّاۤ إِذَاۤ أَذَقۡنَا ٱلۡإِنسَـٰنَ مِنَّا رَحۡمَةࣰ فَرِحَ بِهَاۖ وَإِن تُصِبۡهُمۡ سَیِّئَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ فَإِنَّ ٱلۡإِنسَـٰنَ كَفُورࣱ ۝٤٨", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "فإن أعرض هؤلاء المشركون -أيها الرسول- عن الإيمان بالله فما أرسلناك عليهم حافظًا لأعمالهم حتى تحاسبهم عليها، ما عليك إلا البلاغ. وإنَّا إذا أعطينا الإنسان منا رحمة مِن غنى وسَعَة في المال وغير ذلك، فَرِح وسُرَّ، وإن تصبهم مصيبة مِن فقر ومرض وغير ذلك بسبب ما قدمته أيديهم من معاصي الله، فإن الإنسان جحود يعدِّد المصائب، وينسى النعم.", "isBasmala": false, "translation_en": "But if they turn away-We did not send you as a guardian over them. Your only duty is communication. Whenever We let man taste mercy from Us, he rejoices in it; but when misfortune befalls them, as a consequence of what their hands have perpetrated, man turns blasphemous.", "translation_id": "Jika mereka berpaling maka Kami tidak mengutus kamu sebagai pengawas bagi mereka. Kewajibanmu tidak lain hanyalah menyampaikan (risalah). Sesungguhnya apabila Kami merasakan kepada manusia sesuatu rahmat dari Kami dia bergembira ria karena rahmat itu. Dan jika mereka ditimpa kesusahan disebabkan perbuatan tangan mereka sendiri (niscaya mereka ingkar) karena sesungguhnya manusia itu amat ingkar (kepada nikmat).", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 49, "text": "لِّلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ یَخۡلُقُ مَا یَشَاۤءُۚ یَهَبُ لِمَن یَشَاۤءُ إِنَـٰثࣰا وَیَهَبُ لِمَن یَشَاۤءُ ٱلذُّكُورَ ۝٤٩", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "لله سبحانه وتعالى ملك السموات والأرض وما فيهما، يخلق ما يشاء من الخلق، يهب لمن يشاء من عباده إناثًا لا ذكور معهن، ويهب لمن يشاء الذكور لا إناث معهم، ويعطي سبحانه وتعالى لمن يشاء من الناس الذكر والأنثى، ويجعل مَن يشاء عقيمًا لا يولد له، إنه عليم بما يَخْلُق، قدير على خَلْق ما يشاء، لا يعجزه شيء أراد خلقه.", "isBasmala": false, "translation_en": "To God belongs the dominion of the heavens and the earth. He creates whatever He wills. He grants daughters to whomever He wills, and He grants sons to whomever He wills.", "translation_id": "Kepunyaan Allah-lah kerajaan langit dan bumi, Dia menciptakan apa yang Dia kehendaki. Dia memberikan anak-anak perempuan kepada siapa yang Dia kehendaki dan memberikan anak-anak lelaki kepada siapa yang Dia kehendaki,", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 50, "text": "أَوۡ یُزَوِّجُهُمۡ ذُكۡرَانࣰا وَإِنَـٰثࣰاۖ وَیَجۡعَلُ مَن یَشَاۤءُ عَقِیمًاۚ إِنَّهُۥ عَلِیمࣱ قَدِیرࣱ ۝٥٠", "juz": 25, "hizb": "(*½ ح 49*)", "tafsir": "لله سبحانه وتعالى ملك السموات والأرض وما فيهما، يخلق ما يشاء من الخلق، يهب لمن يشاء من عباده إناثًا لا ذكور معهن، ويهب لمن يشاء الذكور لا إناث معهم، ويعطي سبحانه وتعالى لمن يشاء من الناس الذكر والأنثى، ويجعل مَن يشاء عقيمًا لا يولد له، إنه عليم بما يَخْلُق، قدير على خَلْق ما يشاء، لا يعجزه شيء أراد خلقه.", "isBasmala": false, "translation_en": "Or He combines them together, males and females; and He renders whomever He wills sterile. He is Knowledgeable and Capable.", "translation_id": "atau Dia menganugerahkan kedua jenis laki-laki dan perempuan (kepada siapa) yang dikehendaki-Nya, dan Dia menjadikan mandul siapa yang Dia kehendaki. Sesungguhnya Dia Maha Mengetahui lagi Maha Kuasa.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 51, "text": "۞ وَمَا كَانَ لِبَشَرٍ أَن یُكَلِّمَهُ ٱللَّهُ إِلَّا وَحۡیًا أَوۡ مِن وَرَاۤىِٕ حِجَابٍ أَوۡ یُرۡسِلَ رَسُولࣰا فَیُوحِیَ بِإِذۡنِهِۦ مَا یَشَاۤءُۚ إِنَّهُۥ عَلِیٌّ حَكِیمࣱ ۝٥١", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "وما ينبغي لبشر من بني آدم أن يكلمه الله إلا وحيًا يوحيه الله إليه، أو يكلمه من وراء حجاب، كما كلَّم سبحانه موسى عليه السلام، أو يرسل رسولا كما ينزل جبريل عليه السلام إلى المرسل إليه، فيوحي بإذن ربه لا بمجرد هواه ما يشاء الله إيحاءه، إنه تعالى عليٌّ بذاته وأسمائه وصفاته وأفعاله، قد قهر كل شيء ودانت له المخلوقات، حكيم في تدبير أمور خلقه. وفي الآية إثبات صفة الكلام لله تعالى على الوجه اللائق بجلاله وعظيم سلطانه.", "isBasmala": false, "translation_en": "It is not for any human that God should speak to him, except by inspiration, or from behind a veil, or by sending a messenger to reveal by His permission whatever He wills. He is All-High, All-Wise.", "translation_id": "Dan tidak mungkin bagi seorang manusiapun bahwa Allah berkata-kata dengan dia kecuali dengan perantaraan wahyu atau dibelakang tabir atau dengan mengutus seorang utusan (malaikat) lalu diwahyukan kepadanya dengan seizin-Nya apa yang Dia kehendaki. Sesungguhnya Dia Maha Tinggi lagi Maha Bijaksana.", "manzil": 6, "manzil_display": ""}], "489": [{"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 52, "text": "وَكَذَ ٰلِكَ أَوۡحَیۡنَاۤ إِلَیۡكَ رُوحࣰا مِّنۡ أَمۡرِنَاۚ مَا كُنتَ تَدۡرِی مَا ٱلۡكِتَـٰبُ وَلَا ٱلۡإِیمَـٰنُ وَلَـٰكِن جَعَلۡنَـٰهُ نُورࣰا نَّهۡدِی بِهِۦ مَن نَّشَاۤءُ مِنۡ عِبَادِنَاۚ وَإِنَّكَ لَتَهۡدِیۤ إِلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٥٢", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "وكما أوحينا إلى الأنبياء من قبلك -أيها النبي- أوحينا إليك قرآنًا من عندنا، ما كنت تدري قبله ما الكتب السابقة ولا الإيمان ولا الشرائع الإلهية؟ ولكن جعلنا القرآن ضياء للناس نهدي به مَن نشاء مِن عبادنا إلى الصراط المستقيم. وإنك -أيها الرسول- لَتَدُلُّ وَتُرْشِدُ بإذن الله إلى صراط مستقيم- وهو الإسلام- صراط الله الذي له ملك جميع ما في السموات وما في الأرض، لا شريك له في ذلك. ألا إلى الله- أيها الناس- ترجع جميع أموركم من الخير والشر، فيجازي كلا بعمله: إن خيرًا فخير، وإن شرًا فشر.", "isBasmala": false, "translation_en": "We thus inspired you spiritually, by Our command. You did not know what the Scripture is, nor what faith is, but We made it a light, with which We guide whomever We will of Our servants. You surely guide to a straight path.", "translation_id": "Dan demikianlah Kami wahyukan kepadamu wahyu (Al Quran) dengan perintah Kami. Sebelumnya kamu tidaklah mengetahui apakah Al Kitab (Al Quran) dan tidak pula mengetahui apakah iman itu, tetapi Kami menjadikan Al Quran itu cahaya, yang Kami tunjuki dengan dia siapa yang kami kehendaki di antara hamba-hamba Kami. Dan sesungguhnya kamu benar-benar memberi petunjuk kepada jalan yang lurus.", "manzil": 6, "manzil_display": ""}, {"sura": 42, "sura_name": "الشورى", "revelation": "Makkiyah", "aya": 53, "text": "صِرَ ٰطِ ٱللَّهِ ٱلَّذِی لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۗ أَلَاۤ إِلَى ٱللَّهِ تَصِیرُ ٱلۡأُمُورُ ۝٥٣", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "وكما أوحينا إلى الأنبياء من قبلك -أيها النبي- أوحينا إليك قرآنًا من عندنا، ما كنت تدري قبله ما الكتب السابقة ولا الإيمان ولا الشرائع الإلهية؟ ولكن جعلنا القرآن ضياء للناس نهدي به مَن نشاء مِن عبادنا إلى الصراط المستقيم. وإنك -أيها الرسول- لَتَدُلُّ وَتُرْشِدُ بإذن الله إلى صراط مستقيم- وهو الإسلام- صراط الله الذي له ملك جميع ما في السموات وما في الأرض، لا شريك له في ذلك. ألا إلى الله- أيها الناس- ترجع جميع أموركم من الخير والشر، فيجازي كلا بعمله: إن خيرًا فخير، وإن شرًا فشر.", "isBasmala": false, "translation_en": "The path of God, to whom belongs everything in the heavens and everything on earth. Indeed, to God all matters revert.", "translation_id": "(Yaitu) jalan Allah yang kepunyaan-Nya segala apa yang ada di langit dan apa yang ada di bumi. Ingatlah, bahwa kepada Allah-lah kembali semua urusan.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 25, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 1, "text": "حمۤ ۝١", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "(حم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ha, Meem.", "translation_id": "Haa Miim.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 2, "text": "وَٱلۡكِتَـٰبِ ٱلۡمُبِینِ ۝٢", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "أقسم الله تعالى بالقرآن الواضح لفظًا ومعنى.", "isBasmala": false, "translation_en": "By the Book that makes things clear.", "translation_id": "Demi Kitab (Al Quran) yang menerangkan.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 3, "text": "إِنَّا جَعَلۡنَـٰهُ قُرۡءَ ٰنًا عَرَبِیࣰّا لَّعَلَّكُمۡ تَعۡقِلُونَ ۝٣", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "إنَّا أنزلنا القرآن على محمد صلى الله عليه وسلم بلسان العرب؛ لعلكم تفهمون، وتتدبرون معانيه وحججه. وإنه في اللوح المحفوظ لدينا لعليٌّ في قَدْره وشرفه، محكم لا اختلاف فيه ولا تناقض.", "isBasmala": false, "translation_en": "We made it an Arabic Quran, so that you may understand.", "translation_id": "Sesungguhnya Kami menjadikan Al Quran dalam bahasa Arab supaya kamu memahami(nya).", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 4, "text": "وَإِنَّهُۥ فِیۤ أُمِّ ٱلۡكِتَـٰبِ لَدَیۡنَا لَعَلِیٌّ حَكِیمٌ ۝٤", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "إنَّا أنزلنا القرآن على محمد صلى الله عليه وسلم بلسان العرب؛ لعلكم تفهمون، وتتدبرون معانيه وحججه. وإنه في اللوح المحفوظ لدينا لعليٌّ في قَدْره وشرفه، محكم لا اختلاف فيه ولا تناقض.", "isBasmala": false, "translation_en": "And it is with Us, in the Source Book, sublime and wise.", "translation_id": "Dan sesungguhnya Al Quran itu dalam induk Al Kitab (Lauh Mahfuzh) di sisi Kami, adalah benar-benar tinggi (nilainya) dan amat banyak mengandung hikmah.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 5, "text": "أَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمࣰا مُّسۡرِفِینَ ۝٥", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "أفنُعْرِض عنكم، ونترك إنزال القرآن إليكم لأجل إعراضكم وعدم انقيادكم، وإسرافكم في عدم الإيمان به؟", "isBasmala": false, "translation_en": "Shall We hold back the Reminder from you, since you are a transgressing people?", "translation_id": "Maka apakah Kami akan berhenti menurunkan Al Quran kepadamu, karena kamu adalah kaum yang melampaui batas?", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 6, "text": "وَكَمۡ أَرۡسَلۡنَا مِن نَّبِیࣲّ فِی ٱلۡأَوَّلِینَ ۝٦", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "كثيرًا من الأنبياء أرسلنا في القرون الأولى التي مضت قبل قومك أيها النبي. وما يأتيهم من نبي إلا كانوا به يستهزئون كاستهزاء قومك بك، فأهلكنا مَن كذَّبوا رسلنا، وكانوا أشد قوة وبأسًا من قومك يا محمد، ومضت عقوبة الأولين بأن أهلِكوا؛ بسبب كفرهم وطغيانهم واستهزائهم بأنبيائهم. وفي هذا تسلية للنبي صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "How many a prophet did We send to the ancients?", "translation_id": "Berapa banyaknya nabi-nabi yang telah Kami utus kepada umat-umat yang terdahulu.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 7, "text": "وَمَا یَأۡتِیهِم مِّن نَّبِیٍّ إِلَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٧", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "كثيرًا من الأنبياء أرسلنا في القرون الأولى التي مضت قبل قومك أيها النبي. وما يأتيهم من نبي إلا كانوا به يستهزئون كاستهزاء قومك بك، فأهلكنا مَن كذَّبوا رسلنا، وكانوا أشد قوة وبأسًا من قومك يا محمد، ومضت عقوبة الأولين بأن أهلِكوا؛ بسبب كفرهم وطغيانهم واستهزائهم بأنبيائهم. وفي هذا تسلية للنبي صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "No messenger came to them, but they ridiculed him.", "translation_id": "Dan tiada seorang nabipun datang kepada mereka melainkan mereka selalu memperolok-olokkannya.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 8, "text": "فَأَهۡلَكۡنَاۤ أَشَدَّ مِنۡهُم بَطۡشࣰا وَمَضَىٰ مَثَلُ ٱلۡأَوَّلِینَ ۝٨", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "كثيرًا من الأنبياء أرسلنا في القرون الأولى التي مضت قبل قومك أيها النبي. وما يأتيهم من نبي إلا كانوا به يستهزئون كاستهزاء قومك بك، فأهلكنا مَن كذَّبوا رسلنا، وكانوا أشد قوة وبأسًا من قومك يا محمد، ومضت عقوبة الأولين بأن أهلِكوا؛ بسبب كفرهم وطغيانهم واستهزائهم بأنبيائهم. وفي هذا تسلية للنبي صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "We destroyed people more powerful than they, and so the example of the ancients has passed away.", "translation_id": "Maka telah Kami binasakan orang-orang yang lebih besar kekuatannya dari mereka itu (musyrikin Mekah) dan telah terdahulu (tersebut dalam Al Quran) perumpamaan umat-umat masa dahulu.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 9, "text": "وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ لَیَقُولُنَّ خَلَقَهُنَّ ٱلۡعَزِیزُ ٱلۡعَلِیمُ ۝٩", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "ولئن سألت -أيها الرسول- هؤلاء المشركين من قومك مَن خلق السموات والأرض؟ ليقولُنَّ: خلقهنَّ العزيز في سلطانه، العليم بهن وما فيهن من الأشياء، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "And if you asked them, \"Who created the heavens and the earth?\" They would say, \"The Mighty, the Knower created them.\"", "translation_id": "Dan sungguh jika kamu tanyakan kepada mereka: \"Siapakah yang menciptakan langit dan bumi?\", niscaya mereka akan menjawab: \"Semuanya diciptakan oleh Yang Maha Perkasa lagi Maha Mengetahui\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 10, "text": "ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدࣰا وَجَعَلَ لَكُمۡ فِیهَا سُبُلࣰا لَّعَلَّكُمۡ تَهۡتَدُونَ ۝١٠", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "الذي جعل لكم الأرض فراشًا وبساطًا، وسهَّل لكم فيها طرقًا لمعاشكم ومتاجركم؛ لكي تهتدوا بتلك السبل إلى مصالحكم الدينية والدنيوية.", "isBasmala": false, "translation_en": "He who made the earth a habitat for you, and traced pathways for you on it, that you may be guided.", "translation_id": "Yang menjadikan bumi untuk kamu sebagai tempat menetap dan Dia membuat jalan-jalan di atas bumi untuk kamu supaya kamu mendapat petunjuk.", "manzil": 6, "manzil_display": ""}], "490": [{"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 11, "text": "وَٱلَّذِی نَزَّلَ مِنَ ٱلسَّمَاۤءِ مَاۤءَۢ بِقَدَرࣲ فَأَنشَرۡنَا بِهِۦ بَلۡدَةࣰ مَّیۡتࣰاۚ كَذَ ٰلِكَ تُخۡرَجُونَ ۝١١", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "والذي نزل من السماء مطرًا بقدر، ليس طوفانًا مغرقًا ولا قاصرًا عن الحاجة؛ حتى يكون معاشًا لكم ولأنعامكم، فأحيينا بالماء بلدة مُقْفِرَة من النبات، كما أخرجنا بهذا الماء الذي نزلناه من السماء من هذه البلدة الميتة النبات والزرع، تُخْرَجون- أيها الناس- من قبوركم بعد فنائكم.", "isBasmala": false, "translation_en": "He who sends down water from the sky in due proportion; and so We revive thereby a dead land. Thus you will be brought out.", "translation_id": "Dan Yang menurunkan air dari langit menurut kadar (yang diperlukan) lalu Kami hidupkan dengan air itu negeri yang mati, seperti itulah kamu akan dikeluarkan (dari dalam kubur).", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 12, "text": "وَٱلَّذِی خَلَقَ ٱلۡأَزۡوَ ٰجَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَـٰمِ مَا تَرۡكَبُونَ ۝١٢", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "والذي خلق الأصناف كلها من حيوان ونبات، وجعل لكم من السفن ما تركبون في البحر، ومن البهائم كالإبل والخيل والبغال والحمير ما تركبون في البر.", "isBasmala": false, "translation_en": "He Who created all the pairs; and provided you with ships, and animals on which you ride.", "translation_id": "Dan Yang menciptakan semua yang berpasang-pasangan dan menjadikan untukmu kapal dan binatang ternak yang kamu tunggangi.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 13, "text": "لِتَسۡتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُوا۟ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَیۡتُمۡ عَلَیۡهِ وَتَقُولُوا۟ سُبۡحَـٰنَ ٱلَّذِی سَخَّرَ لَنَا هَـٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِینَ ۝١٣", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "لكي تستووا على ظهور ما تركبون، ثم تذكروا نعمة ربكم إذا ركبتم عليه، وتقولوا: الحمد لله الذي سخر لنا هذا، وما كنا له مطيقين، ولتقولوا أيضًا: وإنا إلى ربنا بعد مماتنا لصائرون إليه راجعون. وفي هذا بيان أن الله المنعم على عباده بشتَّى النعم، هو المستحق للعبادة في كل حال.", "isBasmala": false, "translation_en": "That you may mount their backs, and remember the favor of your Lord as you sit firmly upon them, and say, \"Glory be to Him Who placed these at our service; surely we could not have done it by ourselves.", "translation_id": "Supaya kamu duduk di atas punggungnya kemudian kamu ingat nikmat Tuhanmu apabila kamu telah duduk di atasnya; dan supaya kamu mengucapkan: \"Maha Suci Tuhan yang telah menundukkan semua ini bagi kami padahal kami sebelumnya tidak mampu menguasainya,", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 14, "text": "وَإِنَّاۤ إِلَىٰ رَبِّنَا لَمُنقَلِبُونَ ۝١٤", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "لكي تستووا على ظهور ما تركبون، ثم تذكروا نعمة ربكم إذا ركبتم عليه، وتقولوا: الحمد لله الذي سخر لنا هذا، وما كنا له مطيقين، ولتقولوا أيضًا: وإنا إلى ربنا بعد مماتنا لصائرون إليه راجعون. وفي هذا بيان أن الله المنعم على عباده بشتَّى النعم، هو المستحق للعبادة في كل حال.", "isBasmala": false, "translation_en": "And surely, to our Lord we will return.\"", "translation_id": "dan sesungguhnya kami akan kembali kepada Tuhan kami\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 15, "text": "وَجَعَلُوا۟ لَهُۥ مِنۡ عِبَادِهِۦ جُزۡءًاۚ إِنَّ ٱلۡإِنسَـٰنَ لَكَفُورࣱ مُّبِینٌ ۝١٥", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "وجعل هؤلاء المشركون لله مِن خلقه نصيًبا، وذلك قولهم للملائكة: بنات الله. إن الإنسان لجحود لنعم ربه التي أنعم بها عليه، مظهر لجحوده وكفره يعدِّد المصائب، وينسى النعم.", "isBasmala": false, "translation_en": "Yet they turn one of His servants into a part of Him. Man is clearly ungrateful.", "translation_id": "Dan mereka menjadikan sebahagian dari hamba-hamba-Nya sebagai bahagian daripada-Nya. Sesungguhnya manusia itu benar-benar pengingkar yang nyata (terhadap rahmat Allah).", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 16, "text": "أَمِ ٱتَّخَذَ مِمَّا یَخۡلُقُ بَنَاتࣲ وَأَصۡفَىٰكُم بِٱلۡبَنِینَ ۝١٦", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "بل أتزعمون- أيها الجاهلون- أن ربكم اتخذ مما يخلق بنات وأنتم لا ترضون ذلك لأنفسكم، وخصَّكم بالبنين فجعلهم لكم؟ وفي هذا توبيخ لهم.", "isBasmala": false, "translation_en": "Or has He chosen for Himself daughters from what He creates, and favored you with sons?", "translation_id": "Patutkah Dia mengambil anak perempuan dari yang diciptakan-Nya dan Dia mengkhususkan buat kamu anak laki-laki.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 17, "text": "وَإِذَا بُشِّرَ أَحَدُهُم بِمَا ضَرَبَ لِلرَّحۡمَـٰنِ مَثَلࣰا ظَلَّ وَجۡهُهُۥ مُسۡوَدࣰّا وَهُوَ كَظِیمٌ ۝١٧", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "وإذا بُشِّر أحدهم بالأنثى التي نسبها للرحمن حين زعم أن الملائكة بنات الله صار وجهه مُسْوَدَّا من سوء البشارة بالأنثى، وهو حزين مملوء من الهم والكرب. (فكيف يرضون لله ما لا يرضونه لأنفسهم؟ تعالى الله وتقدَّس عما يقول الكافرون علوًا كبيرًا).", "isBasmala": false, "translation_en": "Yet when one of them is given news of what he attributes to the Most Gracious, his face darkens, and he suppresses grief.", "translation_id": "Padahal apabila salah seorang di antara mereka diberi kabar gembira dengan apa yang dijadikan sebagai misal bagi Allah Yang Maha Pemurah; jadilah mukanya hitam pekat sedang dia amat menahan sedih.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 18, "text": "أَوَ مَن یُنَشَّؤُا۟ فِی ٱلۡحِلۡیَةِ وَهُوَ فِی ٱلۡخِصَامِ غَیۡرُ مُبِینࣲ ۝١٨", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "أتجترئون وتنسبون إلى الله تعالى مَن يُرَبَّى في الزينة، وهو في الجدال غير مبين لحجته؛ لأنوثته؟", "isBasmala": false, "translation_en": "\"Someone brought up to be beautiful, and unable to help in a fight?\"", "translation_id": "Dan apakah patut (menjadi anak Allah) orang yang dibesarkan dalam keadaan berperhiasan sedang dia tidak dapat memberi alasan yang terang dalam pertengkaran.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 19, "text": "وَجَعَلُوا۟ ٱلۡمَلَـٰۤىِٕكَةَ ٱلَّذِینَ هُمۡ عِبَـٰدُ ٱلرَّحۡمَـٰنِ إِنَـٰثًاۚ أَشَهِدُوا۟ خَلۡقَهُمۡۚ سَتُكۡتَبُ شَهَـٰدَتُهُمۡ وَیُسۡـَٔلُونَ ۝١٩", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "وجعل هؤلاء المشركون بالله الملائكة الذين هم عباد الرحمن إناثًا، أحَضَروا حالة خَلْقهم حتى يحكموا بأنهم إناث؟ ستُكتب شهادتهم، ويُسألون عنها في الآخرة.", "isBasmala": false, "translation_en": "And they appoint the angels, who are servants to the Most Gracious, as females. Have they witnessed their creation? Their claim will be recorded, and they will be questioned.", "translation_id": "Dan mereka menjadikan malaikat-malaikat yang mereka itu adalah hamba-hamba Allah Yang Maha Pemurah sebagai orang-orang perempuan. Apakah mereka menyaksikan penciptaan malaika-malaikat itu? Kelak akan dituliskan persaksian mereka dan mereka akan dimintai pertanggung-jawaban.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 20, "text": "وَقَالُوا۟ لَوۡ شَاۤءَ ٱلرَّحۡمَـٰنُ مَا عَبَدۡنَـٰهُمۗ مَّا لَهُم بِذَ ٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا یَخۡرُصُونَ ۝٢٠", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "وقال هؤلاء المشركون من قريش: لو شاء الرحمن ما عبدنا أحدًا من دونه، وهذه حجة باطلة، فقد أقام الله الحجة على العباد بإرسال الرسل وإنزال الكتب، فاحتجاجهم بالقضاء والقَدَر مِن أبطل الباطل مِن بعد إنذار الرسل لهم. ما لهم بحقيقة ما يقولون مِن ذلك مِن علم، وإنما يقولونه تخرُّصًا وكذبًا؛ لأنه لا خبر عندهم من الله بذلك ولا برهان.", "isBasmala": false, "translation_en": "And they say, \"Had the Most Gracious willed, we would not have worshiped them.\" But they have no knowledge of that; they are merely guessing.", "translation_id": "Dan mereka berkata: \"Jikalau Allah Yang Maha Pemurah menghendaki tentulah kami tidak menyembah mereka (malaikat)\". Mereka tidak mempunyai pengetahuan sedikitpun tentang itu, mereka tidak lain hanyalah menduga-duga belaka.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 21, "text": "أَمۡ ءَاتَیۡنَـٰهُمۡ كِتَـٰبࣰا مِّن قَبۡلِهِۦ فَهُم بِهِۦ مُسۡتَمۡسِكُونَ ۝٢١", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "أَحَضَروا خَلْق الملائكة، أم أعطيناهم كتابًا من قبل القرآن الذي أنزلناه، فهم به مستمسكون يعملون بما فيه، ويحتجون به عليك أيها الرسول؟", "isBasmala": false, "translation_en": "Or have We given them a book prior to this one, to which they adhere?", "translation_id": "Atau adakah Kami memberikan sebuah kitab kepada mereka sebelum Al Quran, lalu mereka berpegang dengan kitab itu?", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 22, "text": "بَلۡ قَالُوۤا۟ إِنَّا وَجَدۡنَاۤ ءَابَاۤءَنَا عَلَىٰۤ أُمَّةࣲ وَإِنَّا عَلَىٰۤ ءَاثَـٰرِهِم مُّهۡتَدُونَ ۝٢٢", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "بل قالوا: إنا وجدنا آباءنا على طريقة ومذهب ودين، وإنا على آثار آبائنا فيما كانوا عليه متبعون لهم، ومقتدون بهم.", "isBasmala": false, "translation_en": "But they say, \"We found our parents on a course, and we are guided in their footsteps.\"", "translation_id": "Bahkan mereka berkata: \"Sesungguhnya kami mendapati bapak-bapak kami menganut suatu agama, dan sesungguhnya kami orang-orang yang mendapat petunjuk dengan (mengikuti) jejak mereka\".", "manzil": 6, "manzil_display": ""}], "491": [{"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 23, "text": "وَكَذَ ٰلِكَ مَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ فِی قَرۡیَةࣲ مِّن نَّذِیرٍ إِلَّا قَالَ مُتۡرَفُوهَاۤ إِنَّا وَجَدۡنَاۤ ءَابَاۤءَنَا عَلَىٰۤ أُمَّةࣲ وَإِنَّا عَلَىٰۤ ءَاثَـٰرِهِم مُّقۡتَدُونَ ۝٢٣", "juz": 25, "hizb": "(*¾ ح 49*)", "tafsir": "وكذلك ما أرسلنا من قبلك -أيها الرسول- في قرية مِن نذير ينذرهم عقابنا على كفرهم بنا، فأنذروهم وحذَّروهم سخَطنا وحلول عقوبتنا، إلا قال الذين أبطرتهم النعمة من الرؤساء والكبراء: إنَّا وجدنا آباءنا على ملة ودين، وإنا على منهاجهم وطريقتهم مقتدون.", "isBasmala": false, "translation_en": "Likewise, We sent no warner before you to any town, but the wealthy among them said, \"We found our parents on a course, and we are following in their footsteps.\"", "translation_id": "Dan demikianlah, Kami tidak mengutus sebelum kamu seorang pemberi peringatanpun dalam suatu negeri, melainkan orang-orang yang hidup mewah di negeri itu berkata: \"Sesungguhnya kami mendapati bapak-bapak kami menganut suatu agama dan sesungguhnya kami adalah pengikut jejak-jejak mereka\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 24, "text": "۞ قَـٰلَ أَوَ لَوۡ جِئۡتُكُم بِأَهۡدَىٰ مِمَّا وَجَدتُّمۡ عَلَیۡهِ ءَابَاۤءَكُمۡۖ قَالُوۤا۟ إِنَّا بِمَاۤ أُرۡسِلۡتُم بِهِۦ كَـٰفِرُونَ ۝٢٤", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "قال محمد صلى الله عليه وسلم ومَن سبقه من الرسل لمن عارضه بهذه الشبهة الباطلة: أتتبعون آباءكم، ولو جئتكم مِن عند ربكم بأهدى إلى طريق الحق وأدلَّ على سبيل الرشاد مما وجدتم عليه آباءكم من الدين والملة؟ قالوا في عناد: إنا بما أرسلتم به جاحدون كافرون.", "isBasmala": false, "translation_en": "He would say, \"Even if I bring you better guidance than what you found your parents following?\" They would say, \"We reject what you are sent with.\"", "translation_id": "(Rasul itu) berkata: \"Apakah (kamu akan mengikutinya juga) sekalipun aku membawa untukmu (agama) yang lebih (nyata) memberi petunjuk daripada apa yang kamu dapati bapak-bapakmu menganutnya?\" Mereka menjawab: \"Sesungguhnya kami mengingkari agama yang kamu diutus untuk menyampaikannya\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 25, "text": "فَٱنتَقَمۡنَا مِنۡهُمۡۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُكَذِّبِینَ ۝٢٥", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "فانتقمنا من هذه الأمم المكذبة رسلها بإحلالنا العقوبة بهم خَسْفًا وغرقًا وغير ذلك، فانظر -أيها الرسول- كيف كان عاقبة أمرهم إذ كذبوا بآيات الله ورسله؟ وليحْذَر قومك أن يستمروا على تكذيبهم، فيصيبهم مثل ما أصابهم.", "isBasmala": false, "translation_en": "So We wreaked vengeance upon them. Behold, then, what was the fate of those who deny.", "translation_id": "Maka Kami binasakan mereka maka perhatikanlah bagaimana kesudahan orang-orang yang mendustakan itu.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 26, "text": "وَإِذۡ قَالَ إِبۡرَ ٰهِیمُ لِأَبِیهِ وَقَوۡمِهِۦۤ إِنَّنِی بَرَاۤءࣱ مِّمَّا تَعۡبُدُونَ ۝٢٦", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "واذكر -أيها الرسول- إذ قال إبراهيم لأبيه وقومه الذين كانوا يعبدون ما يعبده قومك: إنني براء مما تعبدون من دون الله.", "isBasmala": false, "translation_en": "When Abraham said to his father and his people, \"I am innocent of what you worship.", "translation_id": "Dan ingatlah ketika Ibrahim berkata kepada bapaknya dan kaumnya: \"Sesungguhnya aku tidak bertanggung jawab terhadap apa yang kamu sembah,", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 27, "text": "إِلَّا ٱلَّذِی فَطَرَنِی فَإِنَّهُۥ سَیَهۡدِینِ ۝٢٧", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "إلا الذي خلقني، فإنه سيوفقني لاتباع سبيل الرشاد.", "isBasmala": false, "translation_en": "Except for He who created me, for He will guide me.\"", "translation_id": "tetapi (aku menyembah) Tuhan Yang menjadikanku; karena sesungguhnya Dia akan memberi hidayah kepadaku\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 28, "text": "وَجَعَلَهَا كَلِمَةَۢ بَاقِیَةࣰ فِی عَقِبِهِۦ لَعَلَّهُمۡ یَرۡجِعُونَ ۝٢٨", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "وجعل إبراهيم عليه السلام كلمة التوحيد (لا إله إلا الله) باقية في مَن بعده؛ لعلهم يرجعون إلى طاعة ربهم وتوحيده، ويتوبون من كفرهم وذنوبهم.", "isBasmala": false, "translation_en": "And he made it an enduring word in his progeny, so that they may return.", "translation_id": "Dan (lbrahim a. s.) menjadikan kalimat tauhid itu kalimat yang kekal pada keturunannya supaya mereka kembali kepada kalimat tauhid itu.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 29, "text": "بَلۡ مَتَّعۡتُ هَـٰۤؤُلَاۤءِ وَءَابَاۤءَهُمۡ حَتَّىٰ جَاۤءَهُمُ ٱلۡحَقُّ وَرَسُولࣱ مُّبِینࣱ ۝٢٩", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "بل متعتُ -أيها الرسول- هؤلاء المشركين من قومك وآباءهم مِن قبلهم بالحياة، فلم أعاجلهم بالعقوبة على كفرهم، حتى جاءهم القرآن ورسول يبيِّن لهم ما يحتاجون إليه من أمور دينهم.", "isBasmala": false, "translation_en": "I gave these and their forefathers some enjoyment, until the truth and a manifest messenger came to them.", "translation_id": "Tetapi Aku telah memberikan kenikmatan hidup kepada mereka dan bapak-bapak mereka sehingga datanglah kepada mereka kebenaran (Al Quran) dan seorang rasul yang memberi penjelasan.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 30, "text": "وَلَمَّا جَاۤءَهُمُ ٱلۡحَقُّ قَالُوا۟ هَـٰذَا سِحۡرࣱ وَإِنَّا بِهِۦ كَـٰفِرُونَ ۝٣٠", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "ولما جاءهم القرآن من عند الله قالوا: هذا الذي جاءنا به هذا الرسول سحرٌ يسحرنا به، وليس بوحي مِن عند الله، وإنا به مكذِّبون.", "isBasmala": false, "translation_en": "But when the truth came to them, they said, \"This is sorcery, and we refuse to believe in it.\"", "translation_id": "Dan tatkala kebenaran (Al Quran) itu datang kepada mereka, mereka berkata: \"Ini adalah sihir dan sesungguhnya kami adalah orang-orang yang mengingkarinya\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 31, "text": "وَقَالُوا۟ لَوۡلَا نُزِّلَ هَـٰذَا ٱلۡقُرۡءَانُ عَلَىٰ رَجُلࣲ مِّنَ ٱلۡقَرۡیَتَیۡنِ عَظِیمٍ ۝٣١", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "وقال هؤلاء المشركون مِن قريش: إنْ كان هذا القرآن مِن عند الله حقًا، فهلا نُزِّل على رجل عظيم من إحدى هاتين القريتين \"مكة\" أو \"الطائف\".", "isBasmala": false, "translation_en": "They also said, \"If only this Quran was sent down to a man of importance from the two cities.\"", "translation_id": "Dan mereka berkata: \"Mengapa Al Quran ini tidak diturunkan kepada seorang besar dari salah satu dua negeri (Mekah dan Thaif) ini?\"", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 32, "text": "أَهُمۡ یَقۡسِمُونَ رَحۡمَتَ رَبِّكَۚ نَحۡنُ قَسَمۡنَا بَیۡنَهُم مَّعِیشَتَهُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَرَفَعۡنَا بَعۡضَهُمۡ فَوۡقَ بَعۡضࣲ دَرَجَـٰتࣲ لِّیَتَّخِذَ بَعۡضُهُم بَعۡضࣰا سُخۡرِیࣰّاۗ وَرَحۡمَتُ رَبِّكَ خَیۡرࣱ مِّمَّا یَجۡمَعُونَ ۝٣٢", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "أهم يقسمون النبوة فيضعونها حيث شاؤوا؟ نحن قسمنا بينهم معيشتهم في حياتهم الدنيا من الأرزاق والأقوات، ورفعنا بعضهم فوق بعض درجات: هذا غنيٌّ وهذا فقير، وهذا قويٌّ وهذا ضعيف؛ ليكون بعضهم مُسَخَّرًا لبعض في المعاش. ورحمة ربك -أيها الرسول- بإدخالهم الجنة خير مما يجمعون من حطام الدنيا الفاني.", "isBasmala": false, "translation_en": "Is it they who allocate the mercy of your Lord? It is We who have allocated their livelihood in this life, and We elevated some of them in rank above others, that some of them would take others in service. But your Lord's mercy is better than what they amass.", "translation_id": "Apakah mereka yang membagi-bagi rahmat Tuhanmu? Kami telah menentukan antara mereka penghidupan mereka dalam kehidupan dunia, dan kami telah meninggikan sebahagian mereka atas sebagian yang lain beberapa derajat, agar sebagian mereka dapat mempergunakan sebagian yang lain. Dan rahmat Tuhanmu lebih baik dari apa yang mereka kumpulkan.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 33, "text": "وَلَوۡلَاۤ أَن یَكُونَ ٱلنَّاسُ أُمَّةࣰ وَ ٰحِدَةࣰ لَّجَعَلۡنَا لِمَن یَكۡفُرُ بِٱلرَّحۡمَـٰنِ لِبُیُوتِهِمۡ سُقُفࣰا مِّن فِضَّةࣲ وَمَعَارِجَ عَلَیۡهَا یَظۡهَرُونَ ۝٣٣", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "ولولا أن يكون الناس جماعة واحدة على الكفر، لجعلنا لمن يكفر بالرحمن لبيوتهم سُقُفا من فضة وسلالم عليها يصعدون.", "isBasmala": false, "translation_en": "Were it not that humanity would become a single community, We would have provided those who disbelieve in the Most Gracious with roofs of silver to their houses, and stairways by which they ascend.", "translation_id": "Dan sekiranya bukan karena hendak menghindari manusia menjadi umat yang satu (dalam kekafiran), tentulah kami buatkan bagi orang-orang yang kafir kepada Tuhan Yang Maha Pemurah loteng-loteng perak bagi rumah mereka dan (juga) tangga-tangga (perak) yang mereka menaikinya.", "manzil": 6, "manzil_display": ""}], "492": [{"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 34, "text": "وَلِبُیُوتِهِمۡ أَبۡوَ ٰبࣰا وَسُرُرًا عَلَیۡهَا یَتَّكِـُٔونَ ۝٣٤", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "وجعلنا لبيوتهم أبوابًا من فضة، وجعلنا لهم سررًا عليها يتكئون، وجعلنا لهم ذهبًا، وما كل ذلك إلا متاع الحياة الدنيا، وهو متاع قليل زائل، ونعيم الآخرة مدَّخر عند ربك للمتقين ليس لغيرهم.", "isBasmala": false, "translation_en": "And doors to their houses, and furnishings on which they recline.", "translation_id": "Dan (Kami buatkan pula) pintu-pintu (perak) bagi rumah-rumah mereka dan (begitu pula) dipan-dipan yang mereka bertelekan atasnya.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 35, "text": "وَزُخۡرُفࣰاۚ وَإِن كُلُّ ذَ ٰلِكَ لَمَّا مَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۚ وَٱلۡـَٔاخِرَةُ عِندَ رَبِّكَ لِلۡمُتَّقِینَ ۝٣٥", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "وجعلنا لبيوتهم أبوابًا من فضة، وجعلنا لهم سررًا عليها يتكئون، وجعلنا لهم ذهبًا، وما كل ذلك إلا متاع الحياة الدنيا، وهو متاع قليل زائل، ونعيم الآخرة مدَّخر عند ربك للمتقين ليس لغيرهم.", "isBasmala": false, "translation_en": "And decorations. Yet all that is nothing but the stuff of this life. Yet the Hereafter, with your Lord, is for the righteous.", "translation_id": "Dan (Kami buatkan pula) perhiasan-perhiasan (dari emas untuk mereka). Dan semuanya itu tidak lain hanyalah kesenangan kehidupan dunia, dan kehidupan akhirat itu di sisi Tuhanmu adalah bagi orang-orang yang bertakwa.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 36, "text": "وَمَن یَعۡشُ عَن ذِكۡرِ ٱلرَّحۡمَـٰنِ نُقَیِّضۡ لَهُۥ شَیۡطَـٰنࣰا فَهُوَ لَهُۥ قَرِینࣱ ۝٣٦", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "ومن يُعْرِض عن ذكر الرحمن، وهو القرآن، فلم يَخَفْ عقابه، ولم يهتد بهدايته، نجعل له شيطانًا في الدنيا يغويه؛ جزاء له على إعراضه عن ذكر الله، فهو له ملازم ومصاحب يمنعه الحلال، ويبعثه على الحرام.", "isBasmala": false, "translation_en": "Whoever shuns the remembrance of the Most Gracious, We assign for him a devil, to be his companion.", "translation_id": "Barangsiapa yang berpaling dari pengajaran Tuhan Yang Maha Pemurah (Al Quran), kami adakan baginya syaitan (yang menyesatkan) maka syaitan itulah yang menjadi teman yang selalu menyertainya.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 37, "text": "وَإِنَّهُمۡ لَیَصُدُّونَهُمۡ عَنِ ٱلسَّبِیلِ وَیَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ۝٣٧", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "وإن الشياطين ليصدون عن سبيل الحق هؤلاء الذين يعرضون عن ذكر الله، فيزيِّنون لهم الضلالة، ويكرِّهون لهم الإيمان بالله والعمل بطاعته، ويظن هؤلاء المعرضون بتحسين الشياطين لهم ما هم عليه من الضلال أنهم على الحق والهدى.", "isBasmala": false, "translation_en": "They hinder them from the path, though they think they are guided.", "translation_id": "Dan sesungguhnya syaitan-syaitan itu benar-benar menghalangi mereka dari jalan yang benar dan mereka menyangka bahwa mereka mendapat petunjuk.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 38, "text": "حَتَّىٰۤ إِذَا جَاۤءَنَا قَالَ یَـٰلَیۡتَ بَیۡنِی وَبَیۡنَكَ بُعۡدَ ٱلۡمَشۡرِقَیۡنِ فَبِئۡسَ ٱلۡقَرِینُ ۝٣٨", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "حتى إذا جاءنا الذي أعرض عن ذكر الرحمن وقرينُه من الشياطين للحساب والجزاء، قال المعرض عن ذكر الله لقرينه: وددت أن بيني وبينك بُعْدَ ما بين المشرق والمغرب، فبئس القرين لي حيث أغويتني.", "isBasmala": false, "translation_en": "Until, when He comes to Us, he will say, \"If only there were between me and you the distance of the two Easts.\" What an evil companion!", "translation_id": "Sehingga apabila orang-orang yang berpaling itu datang kepada kami (di hari kiamat) dia berkata: \"Aduhai, semoga (jarak) antaraku dan kamu seperti jarak antara masyrik dan maghrib, maka syaitan itu adalah sejahat-jahat teman (yang menyertai manusia)\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 39, "text": "وَلَن یَنفَعَكُمُ ٱلۡیَوۡمَ إِذ ظَّلَمۡتُمۡ أَنَّكُمۡ فِی ٱلۡعَذَابِ مُشۡتَرِكُونَ ۝٣٩", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "ولن ينفعكم اليوم- أيها المعرضون- عن ذكر الله إذ أشركتم في الدنيا أنكم في العذاب مشتركون أنتم وقرناؤكم، فلكل واحد نصيبه الأوفر من العذاب، كما اشتركتم في الكفر.", "isBasmala": false, "translation_en": "It will not benefit you on that Day, since you did wrong. You are partners in the suffering.", "translation_id": "(Harapanmu itu) sekali-kali tidak akan memberi manfaat kepadamu di hari itu karena kamu telah menganiaya (dirimu sendiri). Sesungguhnya kamu bersekutu dalam azab itu.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 40, "text": "أَفَأَنتَ تُسۡمِعُ ٱلصُّمَّ أَوۡ تَهۡدِی ٱلۡعُمۡیَ وَمَن كَانَ فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٤٠", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "أفأنت -أيها الرسول- تُسمع مَن أصمَّه الله عن سماع الحق، أو تهدي إلى طريق الهدى مَن أعمى قلبه عن إبصاره، أو تهدي مَن كان في ضلال عن الحق بيِّن واضح؟ ليس ذلك إليك، إنما عليك البلاغ، وليس عليك هداهم، ولكن الله يهدي مَن يشاء، ويضلُّ مَن يشاء.", "isBasmala": false, "translation_en": "Can you make the deaf hear, or guide the blind, and him who is in evident error?", "translation_id": "Maka apakah kamu dapat menjadikan orang yang pekak bisa mendengar atau (dapatkah) kamu memberi petunjuk kepada orang yang buta (hatinya) dan kepada orang yang tetap dalam kesesatan yang nyata?", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 41, "text": "فَإِمَّا نَذۡهَبَنَّ بِكَ فَإِنَّا مِنۡهُم مُّنتَقِمُونَ ۝٤١", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "فإن توفيناك -أيها الرسول- قبل نصرك على المكذبين من قومك، فإنَّا منهم منتقمون في الآخرة، أو نرينك الذي وعدناهم من العذاب النازل بهم كيوم \"بدر\"، فإنا عليهم مقتدرون نُظهِرك عليهم، ونخزيهم بيدك وأيدي المؤمنين بك.", "isBasmala": false, "translation_en": "Even if We take you away, We will wreak vengeance upon them.", "translation_id": "Sungguh, jika Kami mewafatkan kamu (sebelum kamu mencapai kemenangan) maka sesungguhnya Kami akan menyiksa mereka (di akhirat).", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 42, "text": "أَوۡ نُرِیَنَّكَ ٱلَّذِی وَعَدۡنَـٰهُمۡ فَإِنَّا عَلَیۡهِم مُّقۡتَدِرُونَ ۝٤٢", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "فإن توفيناك -أيها الرسول- قبل نصرك على المكذبين من قومك، فإنَّا منهم منتقمون في الآخرة، أو نرينك الذي وعدناهم من العذاب النازل بهم كيوم \"بدر\"، فإنا عليهم مقتدرون نُظهِرك عليهم، ونخزيهم بيدك وأيدي المؤمنين بك.", "isBasmala": false, "translation_en": "Or show you what We have promised them; for We have absolute power over them.", "translation_id": "Atau Kami memperlihatkan kepadamu (azab) yang telah Kami ancamkan kepada mereka. Maka sesungguhnya Kami berkuasa atas mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 43, "text": "فَٱسۡتَمۡسِكۡ بِٱلَّذِیۤ أُوحِیَ إِلَیۡكَۖ إِنَّكَ عَلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٤٣", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "فاستمسك -أيها الرسول- بما يأمرك به الله في هذا القرآن الذي أوحاه إليك؛ إنك على صراط مستقيم، وذلك هو دين الله الذي أمر به، وهو الإسلام. وفي هذا تثبيت للرسول صلى الله عليه وسلم، وثناء عليه.", "isBasmala": false, "translation_en": "So adhere to what is revealed to you. You are upon a straight path.", "translation_id": "Maka berpegang teguhlah kamu kepada agama yang telah diwahyukan kepadamu. Sesungguhnya kamu berada di atas jalan yang lurus.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 44, "text": "وَإِنَّهُۥ لَذِكۡرࣱ لَّكَ وَلِقَوۡمِكَۖ وَسَوۡفَ تُسۡـَٔلُونَ ۝٤٤", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "وإن هذا القرآن لَشرف لك ولقومك من قريش؛ حيث أُنزل بلغتهم، فهم أفهم الناس له، فينبغي أن يكونوا أقوم الناس به، وأعملهم بمقتضاه، وسوف تُسألون أنت ومَن معك عن الشكر لله عليه والعمل به.", "isBasmala": false, "translation_en": "It is a message for you, and for your people; and you will be questioned.", "translation_id": "Dan sesungguhnya Al Quran itu benar-benar adalah suatu kemuliaan besar bagimu dan bagi kaummu dan kelak kamu akan diminta pertanggungan jawab.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 45, "text": "وَسۡـَٔلۡ مَنۡ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رُّسُلِنَاۤ أَجَعَلۡنَا مِن دُونِ ٱلرَّحۡمَـٰنِ ءَالِهَةࣰ یُعۡبَدُونَ ۝٤٥", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "واسأل -أيها الرسول- أتباع مَن أرسلنا مِن قبلك من رسلنا وحملة شرائعهم: أجاءت رسلهم بعبادة غير الله؟ فإنهم يخبرونك أن ذلك لم يقع؛ فإن جميع الرسل دَعَوْا إلى ما دعوتَ الناس إليه من عبادة الله وحده، لا شريك له، ونهَوْا عن عبادة ما سوى الله.", "isBasmala": false, "translation_en": "Ask those of Our messengers We sent before you: \"Did We appoint gods besides the Most Gracious to be worshiped?\"", "translation_id": "Dan tanyakanlah kepada rasul-rasul Kami yang telah Kami utus sebelum kamu: \"Adakah Kami menentukan tuhan-tuhan untuk disembah selain Allah Yang Maha Pemurah?\"", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 46, "text": "وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔایَـٰتِنَاۤ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦ فَقَالَ إِنِّی رَسُولُ رَبِّ ٱلۡعَـٰلَمِینَ ۝٤٦", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "ولقد أرسلنا موسى بحججنا إلى فرعون وأشراف قومه، كما أرسلناك -أيها الرسول- إلى هؤلاء المشركين من قومك، فقال لهم موسى: إني رسول رب العالمين، فلما جاءهم بالبينات الواضحات الدالة على صدقه في دعوته، إذا فرعون وملؤه مما جاءهم به موسى من الآيات والعبر يضحكون.", "isBasmala": false, "translation_en": "We sent Moses with Our revelations to Pharaoh and his dignitaries. He said, \"I am the Messenger of the Lord of the Worlds.\"", "translation_id": "Dan sesunguhnya Kami telah mengutus Musa dengan membawa mukjizat-mukjizat Kami kepada Fir'aun dan pemuka-pemuka kaumnya. Maka Musa berkata: \"Sesungguhnya aku adalah utusan dari Tuhan seru sekalian alam\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 47, "text": "فَلَمَّا جَاۤءَهُم بِـَٔایَـٰتِنَاۤ إِذَا هُم مِّنۡهَا یَضۡحَكُونَ ۝٤٧", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "ولقد أرسلنا موسى بحججنا إلى فرعون وأشراف قومه، كما أرسلناك -أيها الرسول- إلى هؤلاء المشركين من قومك، فقال لهم موسى: إني رسول رب العالمين، فلما جاءهم بالبينات الواضحات الدالة على صدقه في دعوته، إذا فرعون وملؤه مما جاءهم به موسى من الآيات والعبر يضحكون.", "isBasmala": false, "translation_en": "But when he showed them Our signs, they started laughing at them.", "translation_id": "Maka tatkala dia datang kepada mereka dengan membawa mukjizat-mukjizat Kami dengan serta merta mereka mentertawakannya.", "manzil": 6, "manzil_display": ""}], "493": [{"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 48, "text": "وَمَا نُرِیهِم مِّنۡ ءَایَةٍ إِلَّا هِیَ أَكۡبَرُ مِنۡ أُخۡتِهَاۖ وَأَخَذۡنَـٰهُم بِٱلۡعَذَابِ لَعَلَّهُمۡ یَرۡجِعُونَ ۝٤٨", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "وما نُري فرعون وملأه من حجة إلا هي أعظم من التي قبلها، وأدل على صحة ما يدعوهم موسى عليه، وأخذناهم بصنوف العذاب كالجراد والقُمَّل والضفادع والطوفان، وغير ذلك؛ لعلهم يرجعون عن كفرهم بالله إلى توحيده وطاعته.", "isBasmala": false, "translation_en": "Each sign We showed them was more marvelous than its counterpart. And We afflicted them with the plagues, so that they may repent.", "translation_id": "Dan tidaklah Kami perlihatkan kepada mereka sesuatu mukjizat kecuali mukjizat itu lebih besar dari mukjizat-mukjizat yang sebelumnya. Dan Kami timpakan kepada mereka azab supaya mereka kembali (ke jalan yang benar).", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 49, "text": "وَقَالُوا۟ یَـٰۤأَیُّهَ ٱلسَّاحِرُ ٱدۡعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ إِنَّنَا لَمُهۡتَدُونَ ۝٤٩", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "وقال فرعون وملؤه لموسى: يا أيها العالم (وكان الساحر فيهم عظيمًا يُوَقِّرونه ولم يكن السحر صفة ذم) ادع لنا ربك بعهده الذي عهد إليك وما خصَّك به من الفضائل أن يكشف عنا العذاب، فإن كشف عنا العذاب فإننا لمهتدون مؤمنون بما جئتنا به.", "isBasmala": false, "translation_en": "They said, \"O sorcerer, pray to your Lord for us, according to His pledge to you, and then we will be guided.\"", "translation_id": "Dan mereka berkata: \"Hai ahli sihir, berdoalah kepada Tuhanmu untuk (melepaskan) kami sesuai dengan apa yang telah dijanjikan-Nya kepadamu; sesungguhnya kami (jika doamu dikabulkan) benar-benar akan menjadi orang yang mendapat petunjuk.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 50, "text": "فَلَمَّا كَشَفۡنَا عَنۡهُمُ ٱلۡعَذَابَ إِذَا هُمۡ یَنكُثُونَ ۝٥٠", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "فلما دعا موسى برفع العذاب عنهم، ورفعناه عنهم إذا هم يغدرون، ويصرُّون على ضلالهم.", "isBasmala": false, "translation_en": "But when We lifted the torment from them, they immediately broke their promise.", "translation_id": "Maka tatkala Kami hilangkan azab itu dari mereka, dengan serta merta mereka memungkiri (janjinya).", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 51, "text": "وَنَادَىٰ فِرۡعَوۡنُ فِی قَوۡمِهِۦ قَالَ یَـٰقَوۡمِ أَلَیۡسَ لِی مُلۡكُ مِصۡرَ وَهَـٰذِهِ ٱلۡأَنۡهَـٰرُ تَجۡرِی مِن تَحۡتِیۤۚ أَفَلَا تُبۡصِرُونَ ۝٥١", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "ونادى فرعون في عظماء قومه متبجحًا مفتخرًا بمُلْك \"مصر\": أليس لي مُلْك \"مصر\" وهذه الأنهار تجري مِن تحتي؟ أفلا تبصرون عظمتي وقوتي، وضعف موسى وفقره؟", "isBasmala": false, "translation_en": "Pharaoh proclaimed among his people, saying, \"O my people, do I not own the Kingdom of Egypt, and these rivers flow beneath me? Do you not see?", "translation_id": "Dan Fir'aun berseru kepada kaumnya (seraya) berkata: \"Hai kaumku, bukankah kerajaan Mesir ini kepunyaanku dan (bukankah) sungai-sungai ini mengalir di bawahku; maka apakah kamu tidak melihat(nya)?", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 52, "text": "أَمۡ أَنَا۠ خَیۡرࣱ مِّنۡ هَـٰذَا ٱلَّذِی هُوَ مَهِینࣱ وَلَا یَكَادُ یُبِینُ ۝٥٢", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "بل أنا خير من هذا الذي لا عزَّ معه، فهو يمتهن نفسه في حاجاته لضعفه وحقارته، ولا يكاد يُبين الكلام لعِيِّ لسانه، وقد حمل فرعونَ على هذا القول الكفرُ والعنادُ والصدُّ عن سبيل الله.", "isBasmala": false, "translation_en": "Am I not better than this miserable wretch, who can barely express himself?", "translation_id": "Bukankah aku lebih baik dari orang yang hina ini dan yang hampir tidak dapat menjelaskan (perkataannya)?", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 53, "text": "فَلَوۡلَاۤ أُلۡقِیَ عَلَیۡهِ أَسۡوِرَةࣱ مِّن ذَهَبٍ أَوۡ جَاۤءَ مَعَهُ ٱلۡمَلَـٰۤىِٕكَةُ مُقۡتَرِنِینَ ۝٥٣", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "فهلا أُلقِي على موسى- إن كان صادقًا أنه رسول رب العالمين- أسْوِرَة من ذهب، أو جاء معه الملائكة قد اقترن بعضهم ببعض، فتتابعوا يشهدون له بأنه رسول الله إلينا.", "isBasmala": false, "translation_en": "Why are bracelets of gold not dropped on him, or they angels came with him in procession?\"", "translation_id": "Mengapa tidak dipakaikan kepadanya gelang dari emas atau malaikat datang bersama-sama dia untuk mengiringkannya?\"", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 54, "text": "فَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُۚ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ ۝٥٤", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "فاسْتَخَفَّ فرعون عقول قومه فدعاهم إلى الضلالة، فأطاعوه وكذبوا موسى، إنهم كانوا قومًا خارجين عن طاعة الله وصراطه المستقيم.", "isBasmala": false, "translation_en": "Thus he fooled his people, and they obeyed him. They were wicked people.", "translation_id": "Maka Fir'aun mempengaruhi kaumnya (dengan perkataan itu) lalu mereka patuh kepadanya. Karena sesungguhnya mereka adalah kaum yang fasik.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 55, "text": "فَلَمَّاۤ ءَاسَفُونَا ٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَـٰهُمۡ أَجۡمَعِینَ ۝٥٥", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "فلما أغضبونا- بعصياننا، وتكذيب موسى وما جاء به من الآيات- انتقمنا منهم بعاجل العذاب الذي عَجَّلناه لهم، فأغرقناهم أجمعين في البحر.", "isBasmala": false, "translation_en": "And when they provoked Our wrath, We took retribution from them, and We drowned them all.", "translation_id": "Maka tatkala mereka membuat Kami murka, Kami menghukum mereka lalu kami tenggelamkan mereka semuanya (di laut),", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 56, "text": "فَجَعَلۡنَـٰهُمۡ سَلَفࣰا وَمَثَلࣰا لِّلۡـَٔاخِرِینَ ۝٥٦", "juz": 25, "hizb": "(* ح 50*)", "tafsir": "فجعلنا هؤلاء الذين أغرقناهم في البحر سلفًا لمن يعمل مثل عملهم ممن يأتي بعدهم في استحقاق العذاب، وعبرة وعظة للآخرين.", "isBasmala": false, "translation_en": "Thus We made them a precedent and an example for the others.", "translation_id": "dan Kami jadikan mereka sebagai pelajaran dan contoh bagi orang-orang yang kemudian.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 57, "text": "۞ وَلَمَّا ضُرِبَ ٱبۡنُ مَرۡیَمَ مَثَلًا إِذَا قَوۡمُكَ مِنۡهُ یَصِدُّونَ ۝٥٧", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "ولما ضرب المشركون عيسى ابن مريم مثلا حين خاصموا محمدا صلى الله عليه وسلم، وحاجُّوه بعبادة النصارى إياه، إذا قومك من ذلك ولأجله يرتفع لهم جَلَبة وضجيج فرحًا وسرورًا، وذلك عندما نزل قوله تعالى {إِنَّكُمْ وَمَا تَعْبُدُونَ مِنْ دُونِ اللَّهِ حَصَبُ جَهَنَّمَ أَنْتُمْ لَهَا وَارِدُونَ (21:98)}، وقال المشركون: رضينا أن تكون آلهتنا بمنزلة عيسى، فأنزل الله قوله: {إِنَّ الَّذِينَ سَبَقَتْ لَهُمْ مِنَّا الْحُسْنَى أُولَئِكَ عَنْهَا مُبْعَدُونَ (21:101)}، فالذي يُلْقى في النار من آلهة المشركين من رضي بعبادتهم إياه.", "isBasmala": false, "translation_en": "And when the son of Mary was cited as an example, your people opposed.", "translation_id": "Dan tatkala putra Maryam (Isa) dijadikan perumpamnaan tiba-tiba kaummu (Quraisy) bersorak karenanya.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 58, "text": "وَقَالُوۤا۟ ءَأَ ٰلِهَتُنَا خَیۡرٌ أَمۡ هُوَۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلَۢاۚ بَلۡ هُمۡ قَوۡمٌ خَصِمُونَ ۝٥٨", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "وقال مشركو قومك -أيها الرسول-: أآلهتنا التي نعبدها خير أم عيسى الذي يعبده قومه؟ فإذا كان عيسى في النار، فلنكن نحن وآلهتنا معه، ما ضربوا لك هذا المثل إلا جدلا بل هم قوم مخاصمون بالباطل.", "isBasmala": false, "translation_en": "They said, \"Are our gods better, or he?\" They cited him only for argument. In fact, they are a quarrelsome people.", "translation_id": "Dan mereka berkata: \"Manakah yang lebih baik tuhan-tuhan kami atau dia (Isa)?\" Mereka tidak memberikan perumpamaan itu kepadamu melainkan dengan maksud membantah saja, sebenarnya mereka adalah kaum yang suka bertengkar.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 59, "text": "إِنۡ هُوَ إِلَّا عَبۡدٌ أَنۡعَمۡنَا عَلَیۡهِ وَجَعَلۡنَـٰهُ مَثَلࣰا لِّبَنِیۤ إِسۡرَ ٰۤءِیلَ ۝٥٩", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "ما عيسى ابن مريم إلا عبد أنعمنا عليه بالنبوة، وجعلناه آية وعبرة لبني إسرائيل يُستدل بها على قدرتا.", "isBasmala": false, "translation_en": "He was just a servant whom We blessed, and We made him an example for the Children of Israel.", "translation_id": "Isa tidak lain hanyalah seorang hamba yang Kami berikan kepadanya nikmat (kenabian) dan Kami jadikan dia sebagai tanda bukti (kekuasaan Allah) untuk Bani lsrail", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 60, "text": "وَلَوۡ نَشَاۤءُ لَجَعَلۡنَا مِنكُم مَّلَـٰۤىِٕكَةࣰ فِی ٱلۡأَرۡضِ یَخۡلُفُونَ ۝٦٠", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "ولو نشاء لجعلنا بدلا منكم ملائكة يَخْلُف بعضهم بعضًا بدلا من بني آدم.", "isBasmala": false, "translation_en": "Had We willed, We would have made of you angels to be successors on earth.", "translation_id": "Dan kalau Kami kehendaki benar-benar Kami jadikan sebagai gantimu di muka bumi malaikat-malaikat yang turun temurun.", "manzil": 6, "manzil_display": ""}], "494": [{"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 61, "text": "وَإِنَّهُۥ لَعِلۡمࣱ لِّلسَّاعَةِ فَلَا تَمۡتَرُنَّ بِهَا وَٱتَّبِعُونِۚ هَـٰذَا صِرَ ٰطࣱ مُّسۡتَقِیمࣱ ۝٦١", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "وإن نزول عيسى عليه السلام قبل يوم القيامة لدليل على قُرْبِ، وقوع الساعة، فلا تشُكُّوا أنها واقعة لا محالة، واتبعون فيما أخبركم به عن الله تعالى، هذا طريق قويم إلى الجنة، لا اعوجاج فيه.", "isBasmala": false, "translation_en": "He is a portent of the Hour, so have no doubt about it, and follow Me. This is a straight way.", "translation_id": "Dan sesungguhnya Isa itu benar-benar memberikan pengetahuan tentang hari kiamat. Karena itu janganlah kamu ragu-ragu tentang kiamat itu dan ikutilah Aku. Inilah jalan yang lurus.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 62, "text": "وَلَا یَصُدَّنَّكُمُ ٱلشَّیۡطَـٰنُۖ إِنَّهُۥ لَكُمۡ عَدُوࣱّ مُّبِینࣱ ۝٦٢", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "ولا يصدَّنكم الشيطان بوساوسه عن طاعتي فيما آمركم به وأنهاكم عنه، إنه لكم عدو بيِّن العداوة.", "isBasmala": false, "translation_en": "And let not Satan divert you. He is an open enemy to you.", "translation_id": "Dan janganlah kamu sekali-kali dipalingkan oleh syaitan; sesungguhnya syaitan itu musuh yang nyata bagimu.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 63, "text": "وَلَمَّا جَاۤءَ عِیسَىٰ بِٱلۡبَیِّنَـٰتِ قَالَ قَدۡ جِئۡتُكُم بِٱلۡحِكۡمَةِ وَلِأُبَیِّنَ لَكُم بَعۡضَ ٱلَّذِی تَخۡتَلِفُونَ فِیهِۖ فَٱتَّقُوا۟ ٱللَّهَ وَأَطِیعُونِ ۝٦٣", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "ولما جاء عيسى بني إسرائيل بالبينات الواضحات من الأدلة قال: قد جئتكم بالنبوة، ولأبيِّن لكم بعض الذي تختلفون فيه من أمور الدين، فاتقوا الله بامتثال أوامره واجتناب نواهيه، وأطيعون فيما أمرتكم به من تقوى الله وطاعته.", "isBasmala": false, "translation_en": "When Jesus came with the clarifications, he said, \"I have come to you with wisdom, and to clarify for you some of what you differ about. So fear God, and obey me.", "translation_id": "Dan tatkala Isa datang membawa keterangan dia berkata: \"Sesungguhnya aku datang kepadamu dengan membawa hikmat dan untuk menjelaskan kepadamu sebagian dari apa yang kamu berselisih tentangnya, maka bertakwalah kepada Allah dan taatlah (kepada)ku\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 64, "text": "إِنَّ ٱللَّهَ هُوَ رَبِّی وَرَبُّكُمۡ فَٱعۡبُدُوهُۚ هَـٰذَا صِرَ ٰطࣱ مُّسۡتَقِیمࣱ ۝٦٤", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "إن الله سبحانه وتعالى هو ربي وربكم جميعًا فاعبدوه وحده، ولا تشركوا به شيئًا، هذا الذي أمرتكم به من تقوى الله وإفراده بالألوهية هو الطريق المستقيم، وهو دين الله الحق الذي لا يقبل من أحد سواه.", "isBasmala": false, "translation_en": "God is my Lord and your Lord, so worship Him-this is a straight path.\"", "translation_id": "Sesungguhnya Allah Dialah Tuhanku dan Tuhan kamu maka sembahlah Dia, ini adalah jalan yang lurus.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 65, "text": "فَٱخۡتَلَفَ ٱلۡأَحۡزَابُ مِنۢ بَیۡنِهِمۡۖ فَوَیۡلࣱ لِّلَّذِینَ ظَلَمُوا۟ مِنۡ عَذَابِ یَوۡمٍ أَلِیمٍ ۝٦٥", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "فاختلفت الفرق في أمر عيسى عليه السلام، وصاروا فيه شيعًا: منهم مَن يُقِرُّ بأنه عبد الله ورسوله، وهو الحق، ومنهم مَن يزعم أنه ابن الله، ومنهم مَن يقول: إنه الله، تعالى الله عن قولهم علوًا كبيرًا، فهلاك ودمار وعذاب أليم يوم القيامة لمن وصفوا عيسى بغير ما وصفه الله به.", "isBasmala": false, "translation_en": "But the factions differed among themselves. So woe to the wrongdoers from the suffering of a painful Day.", "translation_id": "Maka berselisihlah golongan-golongan (yang terdapat) di antara mereka, lalu kecelakaan yang besarlah bagi orang-orang yang zalim yakni siksaan hari yang pedih (kiamat).", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 66, "text": "هَلۡ یَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِیَهُم بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ ۝٦٦", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "هل ينتظر هؤلاء الأحزاب المختلفون في عيسى ابن مريم إلا الساعة أن تأتيهم فجأة، وهم لا يشعرون ولا يفطنون؟", "isBasmala": false, "translation_en": "Are they only waiting for the Hour to come upon them suddenly, while they are unaware?", "translation_id": "Mereka tidak menunggu kecuali kedatangan hari kiamat kepada mereka dengan tiba-tiba sedang mereka tidak menyadarinya.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 67, "text": "ٱلۡأَخِلَّاۤءُ یَوۡمَىِٕذِۭ بَعۡضُهُمۡ لِبَعۡضٍ عَدُوٌّ إِلَّا ٱلۡمُتَّقِینَ ۝٦٧", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "الأصدقاء على معاصي الله في الدنيا يتبرأ بعضهم من بعض يوم القيامة، لكن الذين تصادقوا على تقوى الله، فإن صداقتهم دائمة في الدنيا والآخرة.", "isBasmala": false, "translation_en": "On that Day, friends will be enemies of one another, except for the righteous.", "translation_id": "Teman-teman akrab pada hari itu sebagiannya menjadi musuh bagi sebagian yang lain kecuali orang-orang yang bertakwa.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 68, "text": "یَـٰعِبَادِ لَا خَوۡفٌ عَلَیۡكُمُ ٱلۡیَوۡمَ وَلَاۤ أَنتُمۡ تَحۡزَنُونَ ۝٦٨", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "يقال لهؤلاء المتقين: يا عبادي لا خوف عليكم اليوم من عقابي، ولا أنتم تحزنون على ما فاتكم مِن حظوظ الدنيا.", "isBasmala": false, "translation_en": "O My servants, you have nothing to fear on that Day, nor will you grieve.", "translation_id": "\"Hai hamba-hamba-Ku, tiada kekhawatiran terhadapmu pada hari ini dan tidak pula kamu bersedih hati.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 69, "text": "ٱلَّذِینَ ءَامَنُوا۟ بِـَٔایَـٰتِنَا وَكَانُوا۟ مُسۡلِمِینَ ۝٦٩", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "الذين آمنوا بآياتنا وعملوا بما جاءتهم به رسلهم، وكانوا منقادين لله ربِّ العالمين بقلوبهم وجوارحهم، يقال لهم: ادخلوا الجنة أنتم وقرناؤكم المؤمنون تُنَعَّمون وتُسَرُّون.", "isBasmala": false, "translation_en": "Those who believed in Our revelations, and were submissive.", "translation_id": "(Yaitu) orang-orang yang beriman kepada ayat-ayat Kami dan adalah mereka dahulu orang-orang yang berserah diri.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 70, "text": "ٱدۡخُلُوا۟ ٱلۡجَنَّةَ أَنتُمۡ وَأَزۡوَ ٰجُكُمۡ تُحۡبَرُونَ ۝٧٠", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "الذين آمنوا بآياتنا وعملوا بما جاءتهم به رسلهم، وكانوا منقادين لله ربِّ العالمين بقلوبهم وجوارحهم، يقال لهم: ادخلوا الجنة أنتم وقرناؤكم المؤمنون تُنَعَّمون وتُسَرُّون.", "isBasmala": false, "translation_en": "Enter the Garden, you and your spouses, Joyfully.", "translation_id": "Masuklah kamu ke dalam surga, kamu dan isteri-isteri kamu digembirakan\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 71, "text": "یُطَافُ عَلَیۡهِم بِصِحَافࣲ مِّن ذَهَبࣲ وَأَكۡوَابࣲۖ وَفِیهَا مَا تَشۡتَهِیهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡیُنُۖ وَأَنتُمۡ فِیهَا خَـٰلِدُونَ ۝٧١", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "يطاف على هؤلاء الذين آمنوا بالله ورسله في الجنة بالطعام في أوانٍ من ذهب، وبالشراب في أكواب من ذهب، وفيها لهم ما تشتهي أنفسهم وتلذه أعينهم، وهم ماكثون فيها أبدًا.", "isBasmala": false, "translation_en": "They will be served around with trays of gold, and cups. Therein is whatever the souls desire and delights the eyes. Therein you will stay forever.", "translation_id": "Diedarkan kepada mereka piring-piring dari emas, dan piala-piala dan di dalam surga itu terdapat segala apa yang diingini oleh hati dan sedap (dipandang) mata dan kamu kekal di dalamnya\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 72, "text": "وَتِلۡكَ ٱلۡجَنَّةُ ٱلَّتِیۤ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٧٢", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "وهذه الجنة التي أورثكم الله إياها؛ بسبب ما كنتم تعملون في الدنيا من الخيرات والأعمال الصالحات، وجعلها مِن فضله ورحمته جزاء لكم.", "isBasmala": false, "translation_en": "Such is the Garden you are made to inherit, because of what you used to do.", "translation_id": "Dan itulah surga yang diwariskan kepada kamu disebabkan amal-amal yang dahulu kamu kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 73, "text": "لَكُمۡ فِیهَا فَـٰكِهَةࣱ كَثِیرَةࣱ مِّنۡهَا تَأۡكُلُونَ ۝٧٣", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "لكم في الجنة فاكهة كثيرة من كل نوع منها تأكلون.", "isBasmala": false, "translation_en": "Therein you will have abundant fruit, from which you eat.", "translation_id": "Di dalam surga itu ada buah-buahan yang banyak untukmu yang sebahagiannya kamu makan.", "manzil": 6, "manzil_display": ""}], "495": [{"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 74, "text": "إِنَّ ٱلۡمُجۡرِمِینَ فِی عَذَابِ جَهَنَّمَ خَـٰلِدُونَ ۝٧٤", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "إن الذين اكتسبوا الذنوب بكفرهم، في عذاب جهنم ماكثون، لا يخفف عنهم، وهم فيه آيسون من رحمة الله، وما ظلمْنا هؤلاء المجرمين بالعذاب، ولكن كانوا هم الظالمين أنفسهم بشركهم وجحودهم أن الله هو الإله الحق وحده لا شريك له، وترك اتباعهم لرسل ربهم.", "isBasmala": false, "translation_en": "As for the sinners, they will be in the torment of Hell forever.", "translation_id": "Sesungguhnya orang-orang yang berdosa kekal di dalam azab neraka Jahannam.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 75, "text": "لَا یُفَتَّرُ عَنۡهُمۡ وَهُمۡ فِیهِ مُبۡلِسُونَ ۝٧٥", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "إن الذين اكتسبوا الذنوب بكفرهم، في عذاب جهنم ماكثون، لا يخفف عنهم، وهم فيه آيسون من رحمة الله، وما ظلمْنا هؤلاء المجرمين بالعذاب، ولكن كانوا هم الظالمين أنفسهم بشركهم وجحودهم أن الله هو الإله الحق وحده لا شريك له، وترك اتباعهم لرسل ربهم.", "isBasmala": false, "translation_en": "It will never be eased for them. In it, they will be devastated.", "translation_id": "Tidak diringankan azab itu dari mereka dan mereka di dalamnya berputus asa.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 76, "text": "وَمَا ظَلَمۡنَـٰهُمۡ وَلَـٰكِن كَانُوا۟ هُمُ ٱلظَّـٰلِمِینَ ۝٧٦", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "إن الذين اكتسبوا الذنوب بكفرهم، في عذاب جهنم ماكثون، لا يخفف عنهم، وهم فيه آيسون من رحمة الله، وما ظلمْنا هؤلاء المجرمين بالعذاب، ولكن كانوا هم الظالمين أنفسهم بشركهم وجحودهم أن الله هو الإله الحق وحده لا شريك له، وترك اتباعهم لرسل ربهم.", "isBasmala": false, "translation_en": "We did them no injustice, but it was they who were the unjust.", "translation_id": "Dan tidaklah Kami menganiaya mereka tetapi merekalah yang menganiaya diri mereka sendiri.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 77, "text": "وَنَادَوۡا۟ یَـٰمَـٰلِكُ لِیَقۡضِ عَلَیۡنَا رَبُّكَۖ قَالَ إِنَّكُم مَّـٰكِثُونَ ۝٧٧", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "ونادى هؤلاء المجرمون بعد أن أدخلهم الله جهنم \"مالكًا\" خازن جهنم: يا مالك لِيُمِتنا ربك، فنستريح ممَّا نحن فيه، فأجابهم مالكٌ: إنكم ماكثون، لا خروج لكم منها، ولا محيد لكم عنها، لقد جئناكم بالحق ووضحناه لكم، ولكن أكثركم لما جاء به الرسل من الحق كارهون.", "isBasmala": false, "translation_en": "And they will cry, \"O Malek, let your Lord finish us off.\" He will say, \"You are staying.\"", "translation_id": "Mereka berseru: \"Hai Malik biarlah Tuhanmu membunuh kami saja\". Dia menjawab: \"Kamu akan tetap tinggal (di neraka ini)\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 78, "text": "لَقَدۡ جِئۡنَـٰكُم بِٱلۡحَقِّ وَلَـٰكِنَّ أَكۡثَرَكُمۡ لِلۡحَقِّ كَـٰرِهُونَ ۝٧٨", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "ونادى هؤلاء المجرمون بعد أن أدخلهم الله جهنم \"مالكًا\" خازن جهنم: يا مالك لِيُمِتنا ربك، فنستريح ممَّا نحن فيه، فأجابهم مالكٌ: إنكم ماكثون، لا خروج لكم منها، ولا محيد لكم عنها، لقد جئناكم بالحق ووضحناه لكم، ولكن أكثركم لما جاء به الرسل من الحق كارهون.", "isBasmala": false, "translation_en": "We have given you the truth, but most of you hate the truth.", "translation_id": "Sesungguhnya Kami benar-benar telah memhawa kebenaran kepada kamu tetapi kebanyakan di antara kamu benci pada kebenaran itu.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 79, "text": "أَمۡ أَبۡرَمُوۤا۟ أَمۡرࣰا فَإِنَّا مُبۡرِمُونَ ۝٧٩", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "بل أأحْكمَ هؤلاء المشركون أمرًا يكيدون به الحق الذي جئناهم به؟ فإنا مدبِّرون لهم ما يجزيهم من العذاب والنكال.", "isBasmala": false, "translation_en": "Have they contrived some scheme? We too are contriving.", "translation_id": "Bahkan mereka telah menetapkan satu tipu daya (jahat), maka sesungguhnya Kami menetapkan pula.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 80, "text": "أَمۡ یَحۡسَبُونَ أَنَّا لَا نَسۡمَعُ سِرَّهُمۡ وَنَجۡوَىٰهُمۚ بَلَىٰ وَرُسُلُنَا لَدَیۡهِمۡ یَكۡتُبُونَ ۝٨٠", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "أم يظن هؤلاء المشركون بالله أنَّا لا نسمع ما يسرونه في أنفسهم، ويتناجون به بينهم؟ بلى نسمع ونعلم، ورسلنا الملائكة الكرام الحفظة يكتبون عليهم كل ما عملوا.", "isBasmala": false, "translation_en": "Or do they think that We cannot hear their secrets and their conspiracies? Yes indeed, Our messengers are by them, writing down.", "translation_id": "Apakah mereka mengira, bahwa Kami tidak mendengar rahasia dan bisikan-bisikan mereka? Sebenarnya (Kami mendengar), dan utusan-utusan (malaikat-malaikat) Kami selalu mencatat di sisi mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 81, "text": "قُلۡ إِن كَانَ لِلرَّحۡمَـٰنِ وَلَدࣱ فَأَنَا۠ أَوَّلُ ٱلۡعَـٰبِدِینَ ۝٨١", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "قل -أيها الرسول- لمشركي قومك الزاعمين أن الملائكة بنات الله: إن كان للرحمن ولد كما تزعمون، فأنا أول العابدين لهذا الولد الذي تزعمونه، ولكن هذا لم يكن ولا يكون، فتقدَّس الله عن الصاحبة والولد.", "isBasmala": false, "translation_en": "Say, \"If the Most Gracious had a son, I would be the first to worship.\"", "translation_id": "Katakanlah, jika benar Tuhan Yang Maha Pemurah mempunyai anak, maka akulah (Muhammad) orang yang mula-mula memuliakan (anak itu).", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 82, "text": "سُبۡحَـٰنَ رَبِّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ رَبِّ ٱلۡعَرۡشِ عَمَّا یَصِفُونَ ۝٨٢", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "تنزيهًا وتقديسًا لرب السموات والأرض رب العرش العظيم عما يصفون من الكذب والافتراء من نسبة المشركين الولد إلى الله، وغير ذلك مما يزعمون من الباطل.", "isBasmala": false, "translation_en": "Glorified be the Lord of the heavens and the earth, the Lord of the Throne, beyond what they describe.", "translation_id": "Maha Suci Tuhan Yang empunya langit dan bumi, Tuhan Yang empunya 'Arsy, dari apa yang mereka sifatkan itu.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 83, "text": "فَذَرۡهُمۡ یَخُوضُوا۟ وَیَلۡعَبُوا۟ حَتَّىٰ یُلَـٰقُوا۟ یَوۡمَهُمُ ٱلَّذِی یُوعَدُونَ ۝٨٣", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "فاترك -أيها الرسول- هؤلاء المفترين على الله يخوضوا في باطلهم، ويلعبوا في دنياهم، حتى يلاقوا يومهم الذي فيه يوعدون بالعذاب: إما في الدنيا وإما في الآخرة وإما فيهما معًا.", "isBasmala": false, "translation_en": "So leave them to blunder and play, until they encounter their Day which they are promised.", "translation_id": "Maka biarlah mereka tenggelam (dalam kesesatan) dan bermain-main sampai mereka menemui hari yang dijanjikan kepada mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 84, "text": "وَهُوَ ٱلَّذِی فِی ٱلسَّمَاۤءِ إِلَـٰهࣱ وَفِی ٱلۡأَرۡضِ إِلَـٰهࣱۚ وَهُوَ ٱلۡحَكِیمُ ٱلۡعَلِیمُ ۝٨٤", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "وهو الله وحده المعبود بحق في السماء وفي الأرض، وهو الحكيم الذي أحكم خَلْقَه، وأتقن شرعه، العليم بكل شيء من أحوال خلقه، لا يخفى عليه شيء منها.", "isBasmala": false, "translation_en": "It is He who is God in heaven, and God on earth. He is the Wise, the Knower.", "translation_id": "Dan Dialah Tuhan (Yang disembah) di langit dan Tuhan (Yang disembah) di bumi dan Dialah Yang Maha Bijaksana lagi Maha Mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 85, "text": "وَتَبَارَكَ ٱلَّذِی لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا وَعِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَإِلَیۡهِ تُرۡجَعُونَ ۝٨٥", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "وتكاثرت بركة الله، وكَثُر خيره، وعَظُم ملكه، الذي له وحده سلطان السموات السبع والأرضين السبع وما بينهما من الأشياء كلها، وعنده علم الساعة التي تقوم فيها القيامة، ويُحشر فيها الخلق من قبورهم لموقف الحساب، وإليه تُرَدُّون - أيها الناس- بعد مماتكم، فيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "And blessed is He Who has sovereignty over the heavens and the earth and what is between them. He alone has knowledge of the Hour, and to Him you will be returned.", "translation_id": "Dan Maha Suci Tuhan Yang mempunyai kerajaan langit dan bumi; dan apa yang ada di antara keduanya; dan di sisi-Nya-lah pengetahuan tentang hari kiamat dan hanya kepada-Nya-lah kamu dikembalikan.", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 86, "text": "وَلَا یَمۡلِكُ ٱلَّذِینَ یَدۡعُونَ مِن دُونِهِ ٱلشَّفَـٰعَةَ إِلَّا مَن شَهِدَ بِٱلۡحَقِّ وَهُمۡ یَعۡلَمُونَ ۝٨٦", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "ولا يملك الذين يعبدهم المشركون الشفاعة عنده لأحد إلا مَن شهد بالحق، وأقر بتوحيد الله وبنبوة محمد صلى الله عليه وسلم، وهم يعلمون حقيقة ما أقروا وشهدوا به.", "isBasmala": false, "translation_en": "Those they invoke besides Him are incapable of intercession; only those who testify to the truth and have knowledge.", "translation_id": "Dan sembahan-sembahan yang mereka sembah selain Allah tidak dapat memberi syafa'at; akan tetapi (orang yang dapat memberi syafa'at ialah) orang yang mengakui yang hak (tauhid) dan mereka meyakini(nya).", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 87, "text": "وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَهُمۡ لَیَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ یُؤۡفَكُونَ ۝٨٧", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "ولئن سألت -أيها الرسول- هؤلاء المشركين من قومك مَن خلقهم؟ ليقولُنَّ: الله خلقنا، فكيف ينقلبون وينصرفون عن عبادة الله، ويشركون به غيره؟", "isBasmala": false, "translation_en": "And if you asked them, \"Who created them?\", they would say, \"God.\" Why then do they deviate?", "translation_id": "Dan sungguh jika kamu bertanya kepada mereka: \"Siapakah yang menciptakan mereka, niscaya mereka menjawab: \"Allah\", maka bagaimanakah mereka dapat dipalingkan (dari menyembah Allah)?,", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 88, "text": "وَقِیلِهِۦ یَـٰرَبِّ إِنَّ هَـٰۤؤُلَاۤءِ قَوۡمࣱ لَّا یُؤۡمِنُونَ ۝٨٨", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "وقال محمد صلى الله عليه وسلم شاكيًا إلى ربه قومه الذين كذَّبوه: يا ربِّ إن هؤلاء قوم لا يؤمنون بك وبما أرسلتني به إليهم.", "isBasmala": false, "translation_en": "As for his statement: \"My Lord, these are a people who do not believe.\"", "translation_id": "dan (Allah mengetabui) ucapan Muhammad: \"Ya Tuhanku, sesungguhnya mereka itu adalah kaum yang tidak beriman\".", "manzil": 6, "manzil_display": ""}, {"sura": 43, "sura_name": "الزخرف", "revelation": "Makkiyah", "aya": 89, "text": "فَٱصۡفَحۡ عَنۡهُمۡ وَقُلۡ سَلَـٰمࣱۚ فَسَوۡفَ یَعۡلَمُونَ ۝٨٩", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "فاصفح -أيها الرسول- عنهم، وأعرض عن أذاهم، ولا يَبْدُر منك إلا السلام لهم الذي يقوله أولو الألباب والبصائر للجاهلين، فهم لا يسافهونهم ولا يعاملونهم بمثل أعمالهم السيئة، فسوف يعلمون ما يلقَوْنه من البلاء والنكال. وفي هذا تهديد ووعيد شديد لهؤلاء الكافرين المعاندين وأمثالهم.", "isBasmala": false, "translation_en": "Pardon them, and say, \"Peace.\" They will come to know.", "translation_id": "Maka berpalinglah (hai Muhammad) dari mereka dan katakanlah: \"Salam (selamat tinggal)\". Kelak mereka akan mengetahui (nasib mereka yang buruk).", "manzil": 6, "manzil_display": ""}], "496": [{"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 25, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 1, "text": "حمۤ ۝١", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "(حم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ha, Meem.", "translation_id": "Haa miim.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 2, "text": "وَٱلۡكِتَـٰبِ ٱلۡمُبِینِ ۝٢", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "أقسم الله تعالى بالقرآن الواضح لفظًا ومعنى. إنا أنزلناه في ليلة القدر المباركة كثيرة الخيرات، وهي في رمضان. إنا كنا منذرين الناس بما ينفعهم ويضرهم، وذلك بإرسال الرسل وإنزال الكتب؛ لتقوم حجة الله على عباده. فيها يُقضى ويُفصل من اللوح المحفوظ إلى الكتبة من الملائكة كلُّ أمر محكم من الآجال والأرزاق في تلك السنة، وغير ذلك مما يكون فيها إلى آخرها، لا يبدَّل ولا يغيَّر. هذا الأمر الحكيم أمر مِن عندنا، فجميع ما يكون ويقدره الله تعالى وما يوحيه فبأمره وإذنه وعلمه. إنا كنا مرسلين إلى الناس الرسل محمدًا ومن قبله؛ رحمة من ربك -أيها الرسول- بالمرسل إليهم. إنه هو السميع يسمع جميع الأصوات، العليم بجميع أمور خلقه الظاهرة والباطنة. خالق السموات والأرض وما بينهما من الأشياء كلها، إن كنتم موقنين بذلك فاعلموا أن رب المخلوقات هو إلهها الحق. لا إله يستحق العبادة إلا هو وحده لا شريك له، يحيي ويميت، ربكم ورب آبائكم الأولين، فاعبدوه دون آلهتكم التي لا تقدر على ضر ولا نفع.", "isBasmala": false, "translation_en": "By the Enlightening Scripture.", "translation_id": "Demi Kitab (Al Quran) yang menjelaskan,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 3, "text": "إِنَّاۤ أَنزَلۡنَـٰهُ فِی لَیۡلَةࣲ مُّبَـٰرَكَةٍۚ إِنَّا كُنَّا مُنذِرِینَ ۝٣", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "أقسم الله تعالى بالقرآن الواضح لفظًا ومعنى. إنا أنزلناه في ليلة القدر المباركة كثيرة الخيرات، وهي في رمضان. إنا كنا منذرين الناس بما ينفعهم ويضرهم، وذلك بإرسال الرسل وإنزال الكتب؛ لتقوم حجة الله على عباده. فيها يُقضى ويُفصل من اللوح المحفوظ إلى الكتبة من الملائكة كلُّ أمر محكم من الآجال والأرزاق في تلك السنة، وغير ذلك مما يكون فيها إلى آخرها، لا يبدَّل ولا يغيَّر. هذا الأمر الحكيم أمر مِن عندنا، فجميع ما يكون ويقدره الله تعالى وما يوحيه فبأمره وإذنه وعلمه. إنا كنا مرسلين إلى الناس الرسل محمدًا ومن قبله؛ رحمة من ربك -أيها الرسول- بالمرسل إليهم. إنه هو السميع يسمع جميع الأصوات، العليم بجميع أمور خلقه الظاهرة والباطنة. خالق السموات والأرض وما بينهما من الأشياء كلها، إن كنتم موقنين بذلك فاعلموا أن رب المخلوقات هو إلهها الحق. لا إله يستحق العبادة إلا هو وحده لا شريك له، يحيي ويميت، ربكم ورب آبائكم الأولين، فاعبدوه دون آلهتكم التي لا تقدر على ضر ولا نفع.", "isBasmala": false, "translation_en": "We have revealed it on a Blessed Night-We have warned.", "translation_id": "sesungguhnya Kami menurunkannya pada suatu malam yang diberkahi dan sesungguhnya Kami-lah yang memberi peringatan.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 4, "text": "فِیهَا یُفۡرَقُ كُلُّ أَمۡرٍ حَكِیمٍ ۝٤", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "أقسم الله تعالى بالقرآن الواضح لفظًا ومعنى. إنا أنزلناه في ليلة القدر المباركة كثيرة الخيرات، وهي في رمضان. إنا كنا منذرين الناس بما ينفعهم ويضرهم، وذلك بإرسال الرسل وإنزال الكتب؛ لتقوم حجة الله على عباده. فيها يُقضى ويُفصل من اللوح المحفوظ إلى الكتبة من الملائكة كلُّ أمر محكم من الآجال والأرزاق في تلك السنة، وغير ذلك مما يكون فيها إلى آخرها، لا يبدَّل ولا يغيَّر. هذا الأمر الحكيم أمر مِن عندنا، فجميع ما يكون ويقدره الله تعالى وما يوحيه فبأمره وإذنه وعلمه. إنا كنا مرسلين إلى الناس الرسل محمدًا ومن قبله؛ رحمة من ربك -أيها الرسول- بالمرسل إليهم. إنه هو السميع يسمع جميع الأصوات، العليم بجميع أمور خلقه الظاهرة والباطنة. خالق السموات والأرض وما بينهما من الأشياء كلها، إن كنتم موقنين بذلك فاعلموا أن رب المخلوقات هو إلهها الحق. لا إله يستحق العبادة إلا هو وحده لا شريك له، يحيي ويميت، ربكم ورب آبائكم الأولين، فاعبدوه دون آلهتكم التي لا تقدر على ضر ولا نفع.", "isBasmala": false, "translation_en": "In it is distinguished every wise command.", "translation_id": "Pada malam itu dijelaskan segala urusan yang penuh hikmah,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 5, "text": "أَمۡرࣰا مِّنۡ عِندِنَاۤۚ إِنَّا كُنَّا مُرۡسِلِینَ ۝٥", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "أقسم الله تعالى بالقرآن الواضح لفظًا ومعنى. إنا أنزلناه في ليلة القدر المباركة كثيرة الخيرات، وهي في رمضان. إنا كنا منذرين الناس بما ينفعهم ويضرهم، وذلك بإرسال الرسل وإنزال الكتب؛ لتقوم حجة الله على عباده. فيها يُقضى ويُفصل من اللوح المحفوظ إلى الكتبة من الملائكة كلُّ أمر محكم من الآجال والأرزاق في تلك السنة، وغير ذلك مما يكون فيها إلى آخرها، لا يبدَّل ولا يغيَّر. هذا الأمر الحكيم أمر مِن عندنا، فجميع ما يكون ويقدره الله تعالى وما يوحيه فبأمره وإذنه وعلمه. إنا كنا مرسلين إلى الناس الرسل محمدًا ومن قبله؛ رحمة من ربك -أيها الرسول- بالمرسل إليهم. إنه هو السميع يسمع جميع الأصوات، العليم بجميع أمور خلقه الظاهرة والباطنة. خالق السموات والأرض وما بينهما من الأشياء كلها، إن كنتم موقنين بذلك فاعلموا أن رب المخلوقات هو إلهها الحق. لا إله يستحق العبادة إلا هو وحده لا شريك له، يحيي ويميت، ربكم ورب آبائكم الأولين، فاعبدوه دون آلهتكم التي لا تقدر على ضر ولا نفع.", "isBasmala": false, "translation_en": "A decree from Us. We have been sending messages.", "translation_id": "(yaitu) urusan yang besar dari sisi Kami. Sesungguhnya Kami adalah Yang mengutus rasul-rasul,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 6, "text": "رَحۡمَةࣰ مِّن رَّبِّكَۚ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ ۝٦", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "أقسم الله تعالى بالقرآن الواضح لفظًا ومعنى. إنا أنزلناه في ليلة القدر المباركة كثيرة الخيرات، وهي في رمضان. إنا كنا منذرين الناس بما ينفعهم ويضرهم، وذلك بإرسال الرسل وإنزال الكتب؛ لتقوم حجة الله على عباده. فيها يُقضى ويُفصل من اللوح المحفوظ إلى الكتبة من الملائكة كلُّ أمر محكم من الآجال والأرزاق في تلك السنة، وغير ذلك مما يكون فيها إلى آخرها، لا يبدَّل ولا يغيَّر. هذا الأمر الحكيم أمر مِن عندنا، فجميع ما يكون ويقدره الله تعالى وما يوحيه فبأمره وإذنه وعلمه. إنا كنا مرسلين إلى الناس الرسل محمدًا ومن قبله؛ رحمة من ربك -أيها الرسول- بالمرسل إليهم. إنه هو السميع يسمع جميع الأصوات، العليم بجميع أمور خلقه الظاهرة والباطنة. خالق السموات والأرض وما بينهما من الأشياء كلها، إن كنتم موقنين بذلك فاعلموا أن رب المخلوقات هو إلهها الحق. لا إله يستحق العبادة إلا هو وحده لا شريك له، يحيي ويميت، ربكم ورب آبائكم الأولين، فاعبدوه دون آلهتكم التي لا تقدر على ضر ولا نفع.", "isBasmala": false, "translation_en": "As mercy from your Lord. He is the Hearer, the Knower.", "translation_id": "sebagai rahmat dari Tuhanmu. Sesungguhnya Dialah Yang Maha Mendengar lagi Maha Mengetahui,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 7, "text": "رَبِّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۤۖ إِن كُنتُم مُّوقِنِینَ ۝٧", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "أقسم الله تعالى بالقرآن الواضح لفظًا ومعنى. إنا أنزلناه في ليلة القدر المباركة كثيرة الخيرات، وهي في رمضان. إنا كنا منذرين الناس بما ينفعهم ويضرهم، وذلك بإرسال الرسل وإنزال الكتب؛ لتقوم حجة الله على عباده. فيها يُقضى ويُفصل من اللوح المحفوظ إلى الكتبة من الملائكة كلُّ أمر محكم من الآجال والأرزاق في تلك السنة، وغير ذلك مما يكون فيها إلى آخرها، لا يبدَّل ولا يغيَّر. هذا الأمر الحكيم أمر مِن عندنا، فجميع ما يكون ويقدره الله تعالى وما يوحيه فبأمره وإذنه وعلمه. إنا كنا مرسلين إلى الناس الرسل محمدًا ومن قبله؛ رحمة من ربك -أيها الرسول- بالمرسل إليهم. إنه هو السميع يسمع جميع الأصوات، العليم بجميع أمور خلقه الظاهرة والباطنة. خالق السموات والأرض وما بينهما من الأشياء كلها، إن كنتم موقنين بذلك فاعلموا أن رب المخلوقات هو إلهها الحق. لا إله يستحق العبادة إلا هو وحده لا شريك له، يحيي ويميت، ربكم ورب آبائكم الأولين، فاعبدوه دون آلهتكم التي لا تقدر على ضر ولا نفع.", "isBasmala": false, "translation_en": "Lord of the heavens and the earth and what is between them, if you know for sure.", "translation_id": "Tuhan Yang memelihara langit dan bumi dan apa yang ada di antara keduanya, jika kamu adalah orang yang meyakini.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 8, "text": "لَاۤ إِلَـٰهَ إِلَّا هُوَ یُحۡیِۦ وَیُمِیتُۖ رَبُّكُمۡ وَرَبُّ ءَابَاۤىِٕكُمُ ٱلۡأَوَّلِینَ ۝٨", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "أقسم الله تعالى بالقرآن الواضح لفظًا ومعنى. إنا أنزلناه في ليلة القدر المباركة كثيرة الخيرات، وهي في رمضان. إنا كنا منذرين الناس بما ينفعهم ويضرهم، وذلك بإرسال الرسل وإنزال الكتب؛ لتقوم حجة الله على عباده. فيها يُقضى ويُفصل من اللوح المحفوظ إلى الكتبة من الملائكة كلُّ أمر محكم من الآجال والأرزاق في تلك السنة، وغير ذلك مما يكون فيها إلى آخرها، لا يبدَّل ولا يغيَّر. هذا الأمر الحكيم أمر مِن عندنا، فجميع ما يكون ويقدره الله تعالى وما يوحيه فبأمره وإذنه وعلمه. إنا كنا مرسلين إلى الناس الرسل محمدًا ومن قبله؛ رحمة من ربك -أيها الرسول- بالمرسل إليهم. إنه هو السميع يسمع جميع الأصوات، العليم بجميع أمور خلقه الظاهرة والباطنة. خالق السموات والأرض وما بينهما من الأشياء كلها، إن كنتم موقنين بذلك فاعلموا أن رب المخلوقات هو إلهها الحق. لا إله يستحق العبادة إلا هو وحده لا شريك له، يحيي ويميت، ربكم ورب آبائكم الأولين، فاعبدوه دون آلهتكم التي لا تقدر على ضر ولا نفع.", "isBasmala": false, "translation_en": "There is no god but He. He gives life and causes death-your Lord and Lord of your ancestors of old.", "translation_id": "Tidak ada Tuhan (yang berhak disembah) melainkan Dia, Yang menghidupkan dan Yang mematikan (Dialah) Tuhanmu dan Tuhan bapak-bapakmu yang terdahulu.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 9, "text": "بَلۡ هُمۡ فِی شَكࣲّ یَلۡعَبُونَ ۝٩", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "بل هؤلاء المشركون في شك من الحق، فهم يلهون ويلعبون، ولا يصدقون به.", "isBasmala": false, "translation_en": "Yet they play around in doubt.", "translation_id": "Tetapi mereka bermain-main dalam keragu-raguan.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 10, "text": "فَٱرۡتَقِبۡ یَوۡمَ تَأۡتِی ٱلسَّمَاۤءُ بِدُخَانࣲ مُّبِینࣲ ۝١٠", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "فانتظر -أيها الرسول- بهؤلاء المشركين يوم تأتي السماء بدخان مبين واضح يعمُّ الناس، ويقال لهم: هذا عذاب مؤلم موجع، ثم يقولون سائلين رفعه وكشفه عنهم: ربنا اكشف عنا العذاب، فإن كشفته عنا فإنا مؤمنون بك.", "isBasmala": false, "translation_en": "So watch out for the Day when the sky produces a visible smoke.", "translation_id": "Maka tunggulah hari ketika langit membawa kabut yang nyata,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 11, "text": "یَغۡشَى ٱلنَّاسَۖ هَـٰذَا عَذَابٌ أَلِیمࣱ ۝١١", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "فانتظر -أيها الرسول- بهؤلاء المشركين يوم تأتي السماء بدخان مبين واضح يعمُّ الناس، ويقال لهم: هذا عذاب مؤلم موجع، ثم يقولون سائلين رفعه وكشفه عنهم: ربنا اكشف عنا العذاب، فإن كشفته عنا فإنا مؤمنون بك.", "isBasmala": false, "translation_en": "Enveloping mankind; this is a painful punishment.", "translation_id": "yang meliputi manusia. Inilah azab yang pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 12, "text": "رَّبَّنَا ٱكۡشِفۡ عَنَّا ٱلۡعَذَابَ إِنَّا مُؤۡمِنُونَ ۝١٢", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "فانتظر -أيها الرسول- بهؤلاء المشركين يوم تأتي السماء بدخان مبين واضح يعمُّ الناس، ويقال لهم: هذا عذاب مؤلم موجع، ثم يقولون سائلين رفعه وكشفه عنهم: ربنا اكشف عنا العذاب، فإن كشفته عنا فإنا مؤمنون بك.", "isBasmala": false, "translation_en": "\"Our Lord, lift the torment from us, we are believers.\"", "translation_id": "(Mereka berdoa): \"Ya Tuhan kami, lenyapkanlah dari kami azab itu. Sesungguhnya kami akan beriman\".", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 13, "text": "أَنَّىٰ لَهُمُ ٱلذِّكۡرَىٰ وَقَدۡ جَاۤءَهُمۡ رَسُولࣱ مُّبِینࣱ ۝١٣", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "كيف يكون لهم التذكر والاتعاظ بعد نزول العذاب بهم، وقد جاءهم رسول مبين، وهو محمد عليه الصلاة والسلام، ثم أعرضوا عنه وقالوا: علَّمه بشر أو الكهنة أو الشياطين، هو مجنون وليس برسول؟", "isBasmala": false, "translation_en": "But how can they be reminded? An enlightening messenger has already come to them.", "translation_id": "Bagaimanakah mereka dapat menerima peringatan, padahal telah datang kepada mereka seorang rasul yang memberi penjelasan,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 14, "text": "ثُمَّ تَوَلَّوۡا۟ عَنۡهُ وَقَالُوا۟ مُعَلَّمࣱ مَّجۡنُونٌ ۝١٤", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "كيف يكون لهم التذكر والاتعاظ بعد نزول العذاب بهم، وقد جاءهم رسول مبين، وهو محمد عليه الصلاة والسلام، ثم أعرضوا عنه وقالوا: علَّمه بشر أو الكهنة أو الشياطين، هو مجنون وليس برسول؟", "isBasmala": false, "translation_en": "But they turned away from him, and said, \"Educated, but crazy!\"", "translation_id": "kemudian mereka berpaling daripadanya dan berkata: \"Dia adalah seorang yang menerima ajaran (dari orang lain) lagi pula seorang yang gila\".", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 15, "text": "إِنَّا كَاشِفُوا۟ ٱلۡعَذَابِ قَلِیلًاۚ إِنَّكُمۡ عَاۤىِٕدُونَ ۝١٥", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "سنرفع عنكم العذاب قليلا، وسترون أنكم تعودون إلى ما كنتم فيه من الكفر والضلال والتكذيب، وأننا سنعاقبكم على ذلك.", "isBasmala": false, "translation_en": "We will ease the punishment a little, but you will revert.", "translation_id": "Sesungguhnya (kalau) Kami akan melenyapkan siksaan itu agak sedikit sesungguhnya kamu akan kembali (ingkar).", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 16, "text": "یَوۡمَ نَبۡطِشُ ٱلۡبَطۡشَةَ ٱلۡكُبۡرَىٰۤ إِنَّا مُنتَقِمُونَ ۝١٦", "juz": 25, "hizb": "(*¼ ح 50*)", "tafsir": "يوم نعذب جميع الكفار العذاب الأكبر يوم القيامة وهو يوم انتقامنا منهم.", "isBasmala": false, "translation_en": "The Day when We launch the Great Assault-We will avenge.", "translation_id": "(Ingatlah) hari (ketika) Kami menghantam mereka dengan hantaman yang keras. Sesungguhnya Kami adalah Pemberi balasan.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 17, "text": "۞ وَلَقَدۡ فَتَنَّا قَبۡلَهُمۡ قَوۡمَ فِرۡعَوۡنَ وَجَاۤءَهُمۡ رَسُولࣱ كَرِیمٌ ۝١٧", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "ولقد اختبرنا وابتلينا قبل هؤلاء المشركين قوم فرعون، وجاءهم رسول كريم، وهو موسى عليه السلام، فكذبوه فهلكوا، فهكذا نفعل بأعدائك أيها الرسول، إن لم يؤمنوا.", "isBasmala": false, "translation_en": "Before them We tested the people of Pharaoh; a noble messenger came to them.", "translation_id": "Sesungguhnya sebelum mereka telah Kami uji kaum Fir'aun dan telah datang kepada mereka seorang rasul yang mulia,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 18, "text": "أَنۡ أَدُّوۤا۟ إِلَیَّ عِبَادَ ٱللَّهِۖ إِنِّی لَكُمۡ رَسُولٌ أَمِینࣱ ۝١٨", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وقال لهم موسى: أن سلِّموا إليَّ عباد الله من بني إسرائيل وأرسلوهم معي؛ ليعبدوا الله وحده لا شريك له، إني لكم رسول أمين على وحيه ورسالته.", "isBasmala": false, "translation_en": "Saying, \"Hand over God's servants to me. I am an honest messenger to you.\"", "translation_id": "(dengan berkata): \"Serahkanlah kepadaku hamba-hamba Allah (Bani Israil yang kamu perbudak). Sesungguhnya aku adalah utusan (Allah) yang dipercaya kepadamu,", "manzil": 6, "manzil_display": ""}], "497": [{"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 19, "text": "وَأَن لَّا تَعۡلُوا۟ عَلَى ٱللَّهِۖ إِنِّیۤ ءَاتِیكُم بِسُلۡطَـٰنࣲ مُّبِینࣲ ۝١٩", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وألا تتكبروا على الله بتكذيب رسله، إني آتيكم ببرهان واضح على صدق رسالتي، إني استجرت بالله ربي وربكم أن تقتلوني رجمًا بالحجارة، وإن لم تصدقوني على ما جئتكم به فخلُّوا سبيلي، وكفُّوا عن أذاي.", "isBasmala": false, "translation_en": "And, \"Do not exalt yourselves above God. I come to you with clear authority.", "translation_id": "dan janganlah kamu menyombongkan diri terhadap Allah. Sesungguhnya aku datang kepadamu dengan membawa bukti yang nyata.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 20, "text": "وَإِنِّی عُذۡتُ بِرَبِّی وَرَبِّكُمۡ أَن تَرۡجُمُونِ ۝٢٠", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وألا تتكبروا على الله بتكذيب رسله، إني آتيكم ببرهان واضح على صدق رسالتي، إني استجرت بالله ربي وربكم أن تقتلوني رجمًا بالحجارة، وإن لم تصدقوني على ما جئتكم به فخلُّوا سبيلي، وكفُّوا عن أذاي.", "isBasmala": false, "translation_en": "I have taken refuge in my Lord and your Lord, lest you stone me.", "translation_id": "Dan sesungguhnya aku berlindung kepada Tuhanku dan Tuhanmu, dari keinginanmu merajamku,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 21, "text": "وَإِن لَّمۡ تُؤۡمِنُوا۟ لِی فَٱعۡتَزِلُونِ ۝٢١", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وألا تتكبروا على الله بتكذيب رسله، إني آتيكم ببرهان واضح على صدق رسالتي، إني استجرت بالله ربي وربكم أن تقتلوني رجمًا بالحجارة، وإن لم تصدقوني على ما جئتكم به فخلُّوا سبيلي، وكفُّوا عن أذاي.", "isBasmala": false, "translation_en": "But if you do not believe in me, keep away from me.\"", "translation_id": "dan jika kamu tidak beriman kepadaku maka biarkanlah aku (memimpin Bani Israil)\".", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 22, "text": "فَدَعَا رَبَّهُۥۤ أَنَّ هَـٰۤؤُلَاۤءِ قَوۡمࣱ مُّجۡرِمُونَ ۝٢٢", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "فدعا موسى ربه- حين كذبه فرعون وقومه ولم يؤمنوا به- قائلا إن هؤلاء قوم مشركون بالله كافرون.", "isBasmala": false, "translation_en": "He appealed to his Lord: \"These are a sinful people.\"", "translation_id": "Kemudian Musa berdoa kepada Tuhannya: \"Sesungguhnya mereka ini adalah kaum yang berdosa (segerakanlah azab kepada mereka)\".", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 23, "text": "فَأَسۡرِ بِعِبَادِی لَیۡلًا إِنَّكُم مُّتَّبَعُونَ ۝٢٣", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "فأَسْر- يا موسى- بعبادي- الذين صَدَّقوك، وآمنوا بك، واتبعوك، دون الذين كذبوك منهم- ليلا إنكم متبعون من فرعون وجنوده فتنجون، ويغرق فرعون وجنوده.", "isBasmala": false, "translation_en": "\"Set out with My servants by night-you will be followed.", "translation_id": "(Allah berfirman): \"Maka berjalanlah kamu dengan membawa hamba-hamba-Ku pada malam hari, sesungguhnya kamu akan dikejar,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 24, "text": "وَٱتۡرُكِ ٱلۡبَحۡرَ رَهۡوًاۖ إِنَّهُمۡ جُندࣱ مُّغۡرَقُونَ ۝٢٤", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "واترك البحر كما هو على حالته التي كان عليها حين سلكته، ساكنًا غير مضطرب، إن فرعون وجنوده مغرقون في البحر.", "isBasmala": false, "translation_en": "And cross the sea quickly; they are an army to be drowned.\"", "translation_id": "dan biarkanlah laut itu tetap terbelah. Sesungguhnya mereka adalah tentara yang akan ditenggelamkan\".", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 25, "text": "كَمۡ تَرَكُوا۟ مِن جَنَّـٰتࣲ وَعُیُونࣲ ۝٢٥", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "كم ترك فرعون وقومه بعد مهلكهم وإغراق الله إياهم من بساتين وجنات ناضرة، وعيون من الماء جارية، وزروع ومنازل جميلة، وعيشة كانوا فيها متنعمين مترفين.", "isBasmala": false, "translation_en": "How many gardens and fountains did they leave behind?", "translation_id": "Alangkah banyaknya taman dan mata air yang mereka tinggalkan,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 26, "text": "وَزُرُوعࣲ وَمَقَامࣲ كَرِیمࣲ ۝٢٦", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "كم ترك فرعون وقومه بعد مهلكهم وإغراق الله إياهم من بساتين وجنات ناضرة، وعيون من الماء جارية، وزروع ومنازل جميلة، وعيشة كانوا فيها متنعمين مترفين.", "isBasmala": false, "translation_en": "And plantations, and splendid buildings.", "translation_id": "dan kebun-kebun serta tempat-tempat yang indah-indah,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 27, "text": "وَنَعۡمَةࣲ كَانُوا۟ فِیهَا فَـٰكِهِینَ ۝٢٧", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "كم ترك فرعون وقومه بعد مهلكهم وإغراق الله إياهم من بساتين وجنات ناضرة، وعيون من الماء جارية، وزروع ومنازل جميلة، وعيشة كانوا فيها متنعمين مترفين.", "isBasmala": false, "translation_en": "And comforts they used to enjoy.", "translation_id": "dan kesenangan-kesenangan yang mereka menikmatinya,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 28, "text": "كَذَ ٰلِكَۖ وَأَوۡرَثۡنَـٰهَا قَوۡمًا ءَاخَرِینَ ۝٢٨", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "مثل ذلك العقاب يعاقب الله مَن كذَّب وبدَّل نعمة الله كفرًا، وأورثنا تلك النعم من بعد فرعون وقومه قومًا آخرين خلفوهم من بني إسرائيل.", "isBasmala": false, "translation_en": "So it was; and We passed it on to another people.", "translation_id": "demikianlah. Dan Kami wariskan semua itu kepada kaum yang lain.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 29, "text": "فَمَا بَكَتۡ عَلَیۡهِمُ ٱلسَّمَاۤءُ وَٱلۡأَرۡضُ وَمَا كَانُوا۟ مُنظَرِینَ ۝٢٩", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "فما بكت السماء والأرض حزنًا على فرعون وقومه، وما كانوا مؤخَّرين عن العقوبة التي حلَّت بهم.", "isBasmala": false, "translation_en": "Neither heaven nor earth wept over them, nor were they reprieved.", "translation_id": "Maka langit dan bumi tidak menangisi mereka dan merekapun tidak diberi tangguh.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 30, "text": "وَلَقَدۡ نَجَّیۡنَا بَنِیۤ إِسۡرَ ٰۤءِیلَ مِنَ ٱلۡعَذَابِ ٱلۡمُهِینِ ۝٣٠", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "ولقد نجَّينا بني إسرائيل من العذاب المُذلِّ لهم بقتل أبنائهم واستخدام نسائهم.", "isBasmala": false, "translation_en": "And We delivered the Children of Israel from the humiliating persecution.", "translation_id": "Dan sesungguhnya telah Kami selamatkan Bani Israil dari siksa yang menghinakan,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 31, "text": "مِن فِرۡعَوۡنَۚ إِنَّهُۥ كَانَ عَالِیࣰا مِّنَ ٱلۡمُسۡرِفِینَ ۝٣١", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "من فرعون، إنه كان جبارًا من المشركين، مسرفًا في العلو والتكبر على عباد الله.", "isBasmala": false, "translation_en": "From Pharaoh. He was a transgressing tyrant.", "translation_id": "dari (azab) Fir'aun. Sesungguhnya dia adalah orang yang sombong, salah seorang dari orang-orang yang melampaui batas.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 32, "text": "وَلَقَدِ ٱخۡتَرۡنَـٰهُمۡ عَلَىٰ عِلۡمٍ عَلَى ٱلۡعَـٰلَمِینَ ۝٣٢", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "ولقد اصطفينا بني إسرائيل على عِلْم منا بهم على عالمي زمانهم.", "isBasmala": false, "translation_en": "And We chose them knowingly over all other people.", "translation_id": "Dan sesungguhnya telah Kami pilih mereka dengan pengetahuan (Kami) atas bangsa-bangsa.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 33, "text": "وَءَاتَیۡنَـٰهُم مِّنَ ٱلۡـَٔایَـٰتِ مَا فِیهِ بَلَـٰۤؤࣱا۟ مُّبِینٌ ۝٣٣", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وآتيناهم من المعجزات على يد موسى ما فيه ابتلاؤهم واختبارهم رخاء وشدة.", "isBasmala": false, "translation_en": "And We gave them many signs, in which was an obvious test.", "translation_id": "Dan Kami telah memberikan kepada mereka di antara tanda-tanda kekuasaan (Kami) sesuatu yang di dalamnya terdapat nikmat yang nyata.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 34, "text": "إِنَّ هَـٰۤؤُلَاۤءِ لَیَقُولُونَ ۝٣٤", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "إن هؤلاء المشركين مِن قومك -أيها الرسول- ليقولون: ما هي إلا موتتنا التي نموتها، وهي الموتة الأولى والأخيرة، وما نحن بعد مماتنا بمبعوثين للحساب والثواب والعقاب.", "isBasmala": false, "translation_en": "These people say.", "translation_id": "Sesungguhnya mereka (kaum musyrik) itu benar-benar berkata,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 35, "text": "إِنۡ هِیَ إِلَّا مَوۡتَتُنَا ٱلۡأُولَىٰ وَمَا نَحۡنُ بِمُنشَرِینَ ۝٣٥", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "إن هؤلاء المشركين مِن قومك -أيها الرسول- ليقولون: ما هي إلا موتتنا التي نموتها، وهي الموتة الأولى والأخيرة، وما نحن بعد مماتنا بمبعوثين للحساب والثواب والعقاب.", "isBasmala": false, "translation_en": "\"There is nothing but our first death, and we will not be resurrected.", "translation_id": "\"tidak ada kematian selain kematian di dunia ini. Dan kami sekali-kali tidak akan dibangkitkan,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 36, "text": "فَأۡتُوا۟ بِـَٔابَاۤىِٕنَاۤ إِن كُنتُمۡ صَـٰدِقِینَ ۝٣٦", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "ويقولون أيضًا: فَأْتِ- يا محمد أنت ومَن معك- بآبائنا الذين قد ماتوا، إن كنتم صادقين في أن الله يبعث مَن في القبور أحياء.", "isBasmala": false, "translation_en": "Bring back our ancestors, if you are truthful.\"", "translation_id": "maka datangkanlah (kembali) bapak-bapak kami jika kamu memang orang-orang yang benar\".", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 37, "text": "أَهُمۡ خَیۡرٌ أَمۡ قَوۡمُ تُبَّعࣲ وَٱلَّذِینَ مِن قَبۡلِهِمۡ أَهۡلَكۡنَـٰهُمۡۚ إِنَّهُمۡ كَانُوا۟ مُجۡرِمِینَ ۝٣٧", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "أهؤلاء المشركون خير أم قوم تُبَّع الحِمْيَري والذين مِن قبلهم من الأمم الكافرة بربها؟ أهلكناهم لإجرامهم وكفرهم، ليس هؤلاء المشركون بخير مِن أولئكم فنصفح عنهم، ولا نهلكهم، وهم بالله كافرون.", "isBasmala": false, "translation_en": "Are they better, or the people of Tubba and those before them? We annihilated them. They were evildoers.", "translation_id": "Apakah mereka (kaum musyrikin) yang lebih baik ataukah kaum Tubba' dan orang-orang yang sebelum mereka. Kami telah membinasakan mereka karena sesungguhnya mereka adalah orang-orang yang berdosa.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 38, "text": "وَمَا خَلَقۡنَا ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا لَـٰعِبِینَ ۝٣٨", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وما خلقنا السماوات والأرض وبينهما لعبًا، ما خلقناهما إلا بالحق الذي هو سنة الله في خَلْقِه وتدبيرُه، ولكن أكثر هؤلاء المشركين لا يعلمون ذلك، فلهذا لم يتفكروا فيهما؛ لأنهم لا يرجون ثوابًا ولا يخافون عقابًا.", "isBasmala": false, "translation_en": "We did not create the heavens and the earth and what is between them to play.", "translation_id": "Dan Kami tidak menciptakan langit dan bumi dan apa yang ada antara keduanya dengan bermain-main.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 39, "text": "مَا خَلَقۡنَـٰهُمَاۤ إِلَّا بِٱلۡحَقِّ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ ۝٣٩", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وما خلقنا السماوات والأرض وبينهما لعبًا، ما خلقناهما إلا بالحق الذي هو سنة الله في خَلْقِه وتدبيرُه، ولكن أكثر هؤلاء المشركين لا يعلمون ذلك، فلهذا لم يتفكروا فيهما؛ لأنهم لا يرجون ثوابًا ولا يخافون عقابًا.", "isBasmala": false, "translation_en": "We created them only for a specific purpose, but most of them do not know.", "translation_id": "Kami tidak menciptakan keduanya melainkan dengan haq, tetapi kebanyakan mereka tidak mengetahui.", "manzil": 6, "manzil_display": ""}], "498": [{"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 40, "text": "إِنَّ یَوۡمَ ٱلۡفَصۡلِ مِیقَـٰتُهُمۡ أَجۡمَعِینَ ۝٤٠", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "إن يوم القضاء بين الخلق بما قدَّموا في دنياهم من خير أو شر هو ميقاتهم أجمعين.", "isBasmala": false, "translation_en": "The Day of Sorting Out is the appointed time for them all.", "translation_id": "Sesungguhnya hari keputusan (hari kiamat) itu adalah waktu yang dijanjikan bagi mereka semuanya,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 41, "text": "یَوۡمَ لَا یُغۡنِی مَوۡلًى عَن مَّوۡلࣰى شَیۡـࣰٔا وَلَا هُمۡ یُنصَرُونَ ۝٤١", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "يوم لا يدفع صاحب عن صاحبه شيئًا، ولا ينصر بعضهم بعضًا، إلا مَن رحم الله من المؤمنين، فإنه قد يشفع له عند ربه بعد إذن الله له. إن الله هو العزيز في انتقامه مِن أعدائه، الرحيم بأوليائه وأهل طاعته.", "isBasmala": false, "translation_en": "The Day when no friend will avail a friend in any way, and they will not be helped.", "translation_id": "yaitu hari yang seorang karib tidak dapat memberi manfaat kepada karibnya sedikitpun, dan mereka tidak akan mendapat pertolongan,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 42, "text": "إِلَّا مَن رَّحِمَ ٱللَّهُۚ إِنَّهُۥ هُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ ۝٤٢", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "يوم لا يدفع صاحب عن صاحبه شيئًا، ولا ينصر بعضهم بعضًا، إلا مَن رحم الله من المؤمنين، فإنه قد يشفع له عند ربه بعد إذن الله له. إن الله هو العزيز في انتقامه مِن أعدائه، الرحيم بأوليائه وأهل طاعته.", "isBasmala": false, "translation_en": "Except for him upon whom God has mercy. He is the Mighty, the Merciful.", "translation_id": "kecuali orang yang diberi rahmat oleh Allah. Sesungguhnya Dialah Yang Maha Perkasa lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 43, "text": "إِنَّ شَجَرَتَ ٱلزَّقُّومِ ۝٤٣", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "إن شجرة الزقوم التي تخرج في أصل الجحيم، ثمرها طعام صاحب الآثام الكثيرة، وأكبر الآثام الشرك بالله.", "isBasmala": false, "translation_en": "The Tree of Bitterness.", "translation_id": "Sesungguhnya pohon zaqqum itu,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 44, "text": "طَعَامُ ٱلۡأَثِیمِ ۝٤٤", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "إن شجرة الزقوم التي تخرج في أصل الجحيم، ثمرها طعام صاحب الآثام الكثيرة، وأكبر الآثام الشرك بالله.", "isBasmala": false, "translation_en": "The food of the sinner.", "translation_id": "makanan orang yang banyak berdosa.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 45, "text": "كَٱلۡمُهۡلِ یَغۡلِی فِی ٱلۡبُطُونِ ۝٤٥", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "ثمر شجرة الزقوم كالمَعْدِن المذاب يغلي في بطون المشركين، كغلي الماء الذي بلغ الغاية في الحرارة.", "isBasmala": false, "translation_en": "Like molten lead; boiling inside the bellies.", "translation_id": "(Ia) sebagai kotoran minyak yang mendidih di dalam perut,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 46, "text": "كَغَلۡیِ ٱلۡحَمِیمِ ۝٤٦", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "ثمر شجرة الزقوم كالمَعْدِن المذاب يغلي في بطون المشركين، كغلي الماء الذي بلغ الغاية في الحرارة.", "isBasmala": false, "translation_en": "Like the boiling of seething water.", "translation_id": "seperti mendidihnya air yang amat panas.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 47, "text": "خُذُوهُ فَٱعۡتِلُوهُ إِلَىٰ سَوَاۤءِ ٱلۡجَحِیمِ ۝٤٧", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "خذوا هذا الأثيم الفاجر فادفعوه، وسوقوه بعنف إلى وسط الجحيم يوم القيامة.", "isBasmala": false, "translation_en": "Seize him and drag him into the midst of Hell!", "translation_id": "Peganglah dia kemudian seretlah dia ke tengah-tengah neraka.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 48, "text": "ثُمَّ صُبُّوا۟ فَوۡقَ رَأۡسِهِۦ مِنۡ عَذَابِ ٱلۡحَمِیمِ ۝٤٨", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "ثم صبُّوا فوق رأس هذا الأثيم الماء الذي تناهت شدة حرارته، فلا يفارقه العذاب.", "isBasmala": false, "translation_en": "Then pour over his head the suffering of the Inferno!", "translation_id": "Kemudian tuangkanlah di atas kepalanya siksaan (dari) air yang amat panas.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 49, "text": "ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡكَرِیمُ ۝٤٩", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "يقال لهذا الأثيم الشقيِّ: ذق هذا العذاب الذي تعذَّب به اليوم، إنك أنت العزيز في قومك، الكريم عليهم. وفي هذا تهكم به وتوبيخ له.", "isBasmala": false, "translation_en": "Taste! You who were powerful and noble.", "translation_id": "Rasakanlah, sesungguhnya kamu orang yang perkasa lagi mulia.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 50, "text": "إِنَّ هَـٰذَا مَا كُنتُم بِهِۦ تَمۡتَرُونَ ۝٥٠", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "إن هذا العذاب الذي تعذَّبون به اليوم هو العذاب الذي كنتم تشكُّون فيه في الدنيا، ولا توقنون به.", "isBasmala": false, "translation_en": "This is what you used to doubt.", "translation_id": "Sesungguhnya ini adalah azab yang dahulu selalu kamu meragu-ragukannya.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 51, "text": "إِنَّ ٱلۡمُتَّقِینَ فِی مَقَامٍ أَمِینࣲ ۝٥١", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "إن الذين اتقوا الله بامتثال أوامره، واجتناب نواهيه في الدنيا في موضع إقامة آمنين من الآفات والأحزان وغير ذلك.", "isBasmala": false, "translation_en": "As for the righteous, they will be in a secure place.", "translation_id": "Sesungguhnya orang-orang yang bertakwa berada dalam tempat yang aman,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 52, "text": "فِی جَنَّـٰتࣲ وَعُیُونࣲ ۝٥٢", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "في جنات وعيون جارية.", "isBasmala": false, "translation_en": "Amidst gardens and springs.", "translation_id": "(yaitu) di dalam taman-taman dan mata-air-mata-air;", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 53, "text": "یَلۡبَسُونَ مِن سُندُسࣲ وَإِسۡتَبۡرَقࣲ مُّتَقَـٰبِلِینَ ۝٥٣", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "يَلْبَسون ما رَقَّ من الديباج وما غَلُظَ منه، يقابل بعضهم بعضًا بالوجوه، ولا ينظر بعضهم في قفا بعض، يدور بهم مجلسهم حيث داروا.", "isBasmala": false, "translation_en": "Dressed in silk and brocade, facing one another.", "translation_id": "mereka memakai sutera yang halus dan sutera yang tebal, (duduk) berhadap-hadapan,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 54, "text": "كَذَ ٰلِكَ وَزَوَّجۡنَـٰهُم بِحُورٍ عِینࣲ ۝٥٤", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "كما أعطينا هؤلاء المتقين في الآخرة من الكرامة بإدخالهم الجنات وإلباسهم فيها السندس والإستبرق، كذلك أكرمناهم بأن زوَّجناهم بالحسان من النساء واسعات الأعين جميلاتها.", "isBasmala": false, "translation_en": "So it is, and We will wed them to lovely companions.", "translation_id": "demikianlah. Dan Kami berikan kepada mereka bidadari.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 55, "text": "یَدۡعُونَ فِیهَا بِكُلِّ فَـٰكِهَةٍ ءَامِنِینَ ۝٥٥", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "يطلب هؤلاء المتقون في الجنة كل نوع من فواكه الجنة اشتهوه، آمنين من انقطاع ذلك عنهم وفنائه.", "isBasmala": false, "translation_en": "They will call therein for every kind of fruit, in peace and security.", "translation_id": "Di dalamnya mereka meminta segala macam buah-buahan dengan aman (dari segala kekhawatiran),", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 56, "text": "لَا یَذُوقُونَ فِیهَا ٱلۡمَوۡتَ إِلَّا ٱلۡمَوۡتَةَ ٱلۡأُولَىٰۖ وَوَقَىٰهُمۡ عَذَابَ ٱلۡجَحِیمِ ۝٥٦", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "لا يذوق هؤلاء المتقون في الجنة الموت بعد الموتة الأولى التي ذاقوها في الدنيا، ووقى الله هؤلاء التقين عذاب الجحيم؛ تفضلا وإحسانًا منه سبحانه وتعالى، هذا الذي أعطيناه المتقين في الآخرة من الكرامات هو الفوز العظيم الذي لا فوز بعده. فإنما سهَّلنا لفظ القرآن ومعناه بلغتك أيها الرسول؛ لعلهم يتعظون وينزجرون.", "isBasmala": false, "translation_en": "Therein they will not taste death, beyond the first death; and He will protect them from the torment of Hell.", "translation_id": "mereka tidak akan merasakan mati di dalamnya kecuali mati di dunia. Dan Allah memelihara mereka dari azab neraka,", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 57, "text": "فَضۡلࣰا مِّن رَّبِّكَۚ ذَ ٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝٥٧", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "لا يذوق هؤلاء المتقون في الجنة الموت بعد الموتة الأولى التي ذاقوها في الدنيا، ووقى الله هؤلاء التقين عذاب الجحيم؛ تفضلا وإحسانًا منه سبحانه وتعالى، هذا الذي أعطيناه المتقين في الآخرة من الكرامات هو الفوز العظيم الذي لا فوز بعده. فإنما سهَّلنا لفظ القرآن ومعناه بلغتك أيها الرسول؛ لعلهم يتعظون وينزجرون.", "isBasmala": false, "translation_en": "A favor from your Lord. That is the supreme salvation.", "translation_id": "sebagai karunia dari Tuhanmu. Yang demikian itu adalah keberuntungan yang besar.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 58, "text": "فَإِنَّمَا یَسَّرۡنَـٰهُ بِلِسَانِكَ لَعَلَّهُمۡ یَتَذَكَّرُونَ ۝٥٨", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "لا يذوق هؤلاء المتقون في الجنة الموت بعد الموتة الأولى التي ذاقوها في الدنيا، ووقى الله هؤلاء التقين عذاب الجحيم؛ تفضلا وإحسانًا منه سبحانه وتعالى، هذا الذي أعطيناه المتقين في الآخرة من الكرامات هو الفوز العظيم الذي لا فوز بعده. فإنما سهَّلنا لفظ القرآن ومعناه بلغتك أيها الرسول؛ لعلهم يتعظون وينزجرون.", "isBasmala": false, "translation_en": "We made it easy in your language, so that they may remember.", "translation_id": "Sesungguhnya Kami mudahkan Al Quran itu dengan bahasamu supaya mereka mendapat pelajaran.", "manzil": 6, "manzil_display": ""}, {"sura": 44, "sura_name": "الدخان", "revelation": "Makkiyah", "aya": 59, "text": "فَٱرۡتَقِبۡ إِنَّهُم مُّرۡتَقِبُونَ ۝٥٩", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "فانتظر -أيها الرسول- ما وعدتك من النصر على هؤلاء المشركين بالله، وما يحلُّ بهم من العقاب، إنهم منتظرون موتك وقهرك، سيعلمون لمن تكون النصرة والظَّفَر وعلو الكلمة في الدنيا والآخرة، إنها لك -أيها الرسول- ولمن اتبعك من المؤمنين.", "isBasmala": false, "translation_en": "So wait and watch. They too are waiting and watching.", "translation_id": "Maka tunggulah; sesungguhnya mereka itu menunggu (pula).", "manzil": 6, "manzil_display": ""}], "499": [{"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 25, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 1, "text": "حمۤ ۝١", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "(حم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ha, Meem.", "translation_id": "Haa Miim", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 2, "text": "تَنزِیلُ ٱلۡكِتَـٰبِ مِنَ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ ۝٢", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "هذا القرآن منزل من الله العزيز في انتقامه من أعدائه، الحكيم في تدبير أمور خلقه.", "isBasmala": false, "translation_en": "The revelation of the Book is from God, the Exalted in Might, the Wise.", "translation_id": "Kitab (ini) diturunkan dari Allah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 3, "text": "إِنَّ فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ لَـَٔایَـٰتࣲ لِّلۡمُؤۡمِنِینَ ۝٣", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "إن في السموات السبع، والأرض التي منها خروج الخلق، وما فيهما من المخلوقات المختلفة الأجناس والأنواع، لأدلة وحججًا للمؤمنين بها.", "isBasmala": false, "translation_en": "In the heavens and the earth are proofs for the believers.", "translation_id": "Sesungguhnya pada langit dan bumi benar-benar terdapat tanda-tanda (kekuasaan Allah) untuk orang-orang yang beriman.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 4, "text": "وَفِی خَلۡقِكُمۡ وَمَا یَبُثُّ مِن دَاۤبَّةٍ ءَایَـٰتࣱ لِّقَوۡمࣲ یُوقِنُونَ ۝٤", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وفي خَلْقكم -أيها الناس- وخلق ما تفرق في الأرض من دابة تَدِبُّ عليها، حجج وأدلة لقوم يوقنون بالله وشرعه.", "isBasmala": false, "translation_en": "And in your own creation, and in the creatures He scattered, are signs for people of firm faith.", "translation_id": "Dan pada penciptakan kamu dan pada binatang-binatang yang melata yang bertebaran (di muka bumi) terdapat tanda-tanda (kekuasaan Allah) untuk kaum yang meyakini,", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 5, "text": "وَٱخۡتِلَـٰفِ ٱلَّیۡلِ وَٱلنَّهَارِ وَمَاۤ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَاۤءِ مِن رِّزۡقࣲ فَأَحۡیَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَا وَتَصۡرِیفِ ٱلرِّیَـٰحِ ءَایَـٰتࣱ لِّقَوۡمࣲ یَعۡقِلُونَ ۝٥", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وفي اختلاف الليل والنار وتعاقبهما عليكم وما أنزل الله من السماء من مطر، فأحيا به الأرض بعد يُبْسها، فاهتزت بالنبات والزرع، وفي تصريف الرياح لكم من جميع الجهات وتصريفها لمنافعكم، أدلةٌ وحججٌ لقوم يعقلون عن الله حججه وأدلته.", "isBasmala": false, "translation_en": "And in the alternation of night and day, and in the sustenance God sends down from the sky, with which He revives the earth after its death, and in the circulation of the winds, are marvels for people who reason.", "translation_id": "dan pada pergantian malam dan siang dan hujan yang diturunkan Allah dari langit lalu dihidupkan-Nya dengan air hujan itu bumi sesudah matinya; dan pada perkisaran angin terdapat tanda-tanda (kekuasaan Allah) bagi kaum yang berakal.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 6, "text": "تِلۡكَ ءَایَـٰتُ ٱللَّهِ نَتۡلُوهَا عَلَیۡكَ بِٱلۡحَقِّۖ فَبِأَیِّ حَدِیثِۭ بَعۡدَ ٱللَّهِ وَءَایَـٰتِهِۦ یُؤۡمِنُونَ ۝٦", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "هذه الآيات والحجج نتلوها عليك -أيها الرسول- بالحق، فبأي حديث بعد الله وآياته وأدلته على أنه الإله الحق وحده لا شريك له يؤمنون ويصدقون ويعملون؟", "isBasmala": false, "translation_en": "These are God's Verses which We recite to you in truth. In which message, after God and His revelations, will they believe?", "translation_id": "Itulah ayat-ayat Allah yang Kami membacakannya kepadamu dengan sebenarnya; maka dengan perkataan manakah lagi mereka akan beriman sesudah (kalam) Allah dan keterangan-keterangan-Nya.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 7, "text": "وَیۡلࣱ لِّكُلِّ أَفَّاكٍ أَثِیمࣲ ۝٧", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "هلاك شديد ودمار لكل كذاب كثير الآثام.", "isBasmala": false, "translation_en": "Woe to every sinful liar.", "translation_id": "Kecelakaan besarlah bagi tiap-tiap orang yang banyak berdusta lagi banyak berdosa,", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 8, "text": "یَسۡمَعُ ءَایَـٰتِ ٱللَّهِ تُتۡلَىٰ عَلَیۡهِ ثُمَّ یُصِرُّ مُسۡتَكۡبِرࣰا كَأَن لَّمۡ یَسۡمَعۡهَاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِیمࣲ ۝٨", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "يسمع آيات كتاب الله تُقْرأ عليه، ثم يتمادى في كفره متعاليًا في نفسه عن الانقياد لله ورسوله، كأنه لم يسمع ما تُلي عليه من آيات الله، فبشر -أيها الرسول- هذا الأفاك الأثيم بعذاب مؤلم موجع في نار جهنم يوم القيامة.", "isBasmala": false, "translation_en": "Who hears God's revelations being recited to him, yet he persists arrogantly, as though he did not hear them. Announce to him a painful punishment.", "translation_id": "dia mendengar ayat-ayat Allah dibacakan kepadanya kemudian dia tetap menyombongkan diri seakan-akan dia tidak mendengarnya. Maka beri khabar gembiralah dia dengan azab yang pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 9, "text": "وَإِذَا عَلِمَ مِنۡ ءَایَـٰتِنَا شَیۡـًٔا ٱتَّخَذَهَا هُزُوًاۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مُّهِینࣱ ۝٩", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "وإذا علم هذا الأفاك الأثيم من آياتا شيئًا اتخذها هزوًا وسُخْرية، أولئك لهم عذاب يهينهم، ويخزيهم يوم القيامة؛ جزاء استهزائهم بالقرآن.", "isBasmala": false, "translation_en": "And when he learns something of Our revelations, he takes them in mockery. For such there is a shameful punishment.", "translation_id": "Dan apabila dia mengetahui barang sedikit tentang ayat-ayat Kami, maka ayat-ayat itu dijadikan olok-olok. Merekalah yang memperoleh azab yang menghinakan.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 10, "text": "مِّن وَرَاۤىِٕهِمۡ جَهَنَّمُۖ وَلَا یُغۡنِی عَنۡهُم مَّا كَسَبُوا۟ شَیۡـࣰٔا وَلَا مَا ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوۡلِیَاۤءَۖ وَلَهُمۡ عَذَابٌ عَظِیمٌ ۝١٠", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "مِن أمام هؤلاء المستهزئين بآيات الله جهنم، ولا يغني عنهم ما كسبوا شيئًا من المال والولد، ولا آلهتُهم التي عبدوها مِن دون الله، ولهم عذاب عظيم مؤلم.", "isBasmala": false, "translation_en": "Beyond them lies Hell. What they have earned will not benefit them at all, nor will those they adopted as lords instead of God. They will have a terrible punishment.", "translation_id": "Di hadapan mereka neraka Jahannam dan tidak akan berguna bagi mereka sedikitpun apa yang telah mereka kerjakan, dan tidak pula berguna apa yang mereka jadikan sebagai sembahan-sembahan (mereka) dari selain Allah. Dan bagi mereka azab yang besar.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 11, "text": "هَـٰذَا هُدࣰىۖ وَٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ رَبِّهِمۡ لَهُمۡ عَذَابࣱ مِّن رِّجۡزٍ أَلِیمٌ ۝١١", "juz": 25, "hizb": "(*½ ح 50*)", "tafsir": "هذا القرآن الذي أنزلناه عليك -أيها الرسول- هدى من الضلالة، ودليل على الحق، يهدي إلى طريق مستقيم مَن اتبعه وعمل به، والذين جحدوا بما في القرآن من الآيات الدالة على الحق ولم يُصَدِّقوا بها، لهم عذابٌ مِن أسوأ أنواع العذاب يوم القيامة، مؤلم موجع.", "isBasmala": false, "translation_en": "This is guidance. Those who blaspheme their Lord's revelations will have a punishment of agonizing pain.", "translation_id": "Ini (Al Quran) adalah petunjuk. Dan orang-orang yang kafir kepada ayat-ayat Tuhannya bagi mereka azab yaitu siksaan yang sangat pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 12, "text": "۞ ٱللَّهُ ٱلَّذِی سَخَّرَ لَكُمُ ٱلۡبَحۡرَ لِتَجۡرِیَ ٱلۡفُلۡكُ فِیهِ بِأَمۡرِهِۦ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ۝١٢", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "الله سبحانه وتعالى هو الذي سخَّر لكم البحر؛ لتجري السفن فيه بأمره، ولتبتغوا من فضله بأنواع التجارات والمكاسب، ولعلكم تشكرون ربكم على تسخيره ذلك لكم، فتعبدوه وحده، وتطيعوه فيما يأمركم به، وينهاكم عنه.", "isBasmala": false, "translation_en": "It is God who placed the sea at your service, so that ships may run through it by His command, and that you may seek of His bounty, and that you may give thanks.", "translation_id": "Allah-lah yang menundukkan lautan untukmu supaya kapal-kapal dapat berlayar padanya dengan seizin-Nya dan supaya kamu dapat mencari karunia -Nya dan mudah-mudahan kamu bersyukur.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 13, "text": "وَسَخَّرَ لَكُم مَّا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِ جَمِیعࣰا مِّنۡهُۚ إِنَّ فِی ذَ ٰلِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَفَكَّرُونَ ۝١٣", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وسخَّر لكم كل ما في السموات من شمس وقمر ونجوم، وكل ما في الأرض من دابة وشجر وسفن وغير ذلك لمنافعكم، جميع هذه النعم منة من الله وحده أنعم بها عليكم، وفضل منه تَفضَّل به، فإياه فاعبدوا، ولا تجعلوا له شريكًا. إنَّ فيما سخره الله لكم لعلامات ودلالات على وحدانية الله لقوم يتفكرون في آيات الله وحججه وأدلته، فيعتبرون بها.", "isBasmala": false, "translation_en": "And He placed at your service whatever is in the heavens and whatever is on earth-all is from Him. In that are signs for a people who think.", "translation_id": "Dan Dia telah menundukkan untukmu apa yang di langit dan apa yang di bumi semuanya, (sebagai rahmat) daripada-Nya. Sesungguhnya pada yang demikian itu benar-benar terdapat tanda-tanda (kekuasaan Allah) bagi kaum yang berfikir.", "manzil": 6, "manzil_display": ""}], "500": [{"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 14, "text": "قُل لِّلَّذِینَ ءَامَنُوا۟ یَغۡفِرُوا۟ لِلَّذِینَ لَا یَرۡجُونَ أَیَّامَ ٱللَّهِ لِیَجۡزِیَ قَوۡمَۢا بِمَا كَانُوا۟ یَكۡسِبُونَ ۝١٤", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "قل -أيها الرسول- للذين صدَّقوا بالله واتَّبَعوا رسله يعفوا، ويتجاوزوا عن الذين لا يرجون ثواب الله، ولا يخافون بأسه إذا هم نالوا الذين آمنوا بالأذى والمكروه؛ ليجزي الله هؤلاء المشركين بما كانوا يكسبون في الدنيا من الآثام وإيذاء المؤمنين.", "isBasmala": false, "translation_en": "Tell those who believe to forgive those who do not hope for the Days of God. He will fully recompense people for whatever they have earned.", "translation_id": "Katakanlah kepada orang-orang yang beriman hendaklah mereka memaafkan orang-orang yang tiada takut hari-hari Allah karena Dia akan membalas sesuatu kaum terhadap apa yang telah mereka kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 15, "text": "مَنۡ عَمِلَ صَـٰلِحࣰا فَلِنَفۡسِهِۦۖ وَمَنۡ أَسَاۤءَ فَعَلَیۡهَاۖ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ ۝١٥", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "من عمل مِن عباد الله بطاعته فلنفسه عمل، ومن أساء عمله في الدنيا بمعصية الله فعلى نفسه جنى، ثم إنكم - أيها الناس - إلى ربكم تصيرون بعد موتكم، فيجازي المحسن بإحسانه، والمسيء بإساءته.", "isBasmala": false, "translation_en": "Whoever does a good deed, it is for his soul; and whoever commits evil, it is against it; then to your Lord you will be returned.", "translation_id": "Barangsiapa yang mengerjakan amal saleh, maka itu adalah untuk dirinya sendiri, dan barangsiapa yang mengerjakan kejahatan, maka itu akan menimpa dirinya sendiri, kemudian kepada Tuhanmulah kamu dikembalikan.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 16, "text": "وَلَقَدۡ ءَاتَیۡنَا بَنِیۤ إِسۡرَ ٰۤءِیلَ ٱلۡكِتَـٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَ وَرَزَقۡنَـٰهُم مِّنَ ٱلطَّیِّبَـٰتِ وَفَضَّلۡنَـٰهُمۡ عَلَى ٱلۡعَـٰلَمِینَ ۝١٦", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "ولقد آتينا بني إسرائيل التوراة والإنجيل والحكم بما فيهما، وجعلنا أكثر الأنبياء من ذرية إبراهيم عليه السلام فيهم، ورزقناهم من الطيبات من الأقوات والثمار والأطعمة، وفضَّلناهم على عالمي زمانهم.", "isBasmala": false, "translation_en": "We gave the Children of Israel the Book, and wisdom, and prophecy; and We provided them with the good things; and We gave them advantage over all other people.", "translation_id": "Dan sesungguhnya telah Kami berikan kepada Bani Israil Al Kitab (Taurat), kekuasaan dan kenabian dan Kami berikan kepada mereka rezeki-rezeki yang baik dan Kami lebihkan mereka atas bangsa-bangsa (pada masanya).", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 17, "text": "وَءَاتَیۡنَـٰهُم بَیِّنَـٰتࣲ مِّنَ ٱلۡأَمۡرِۖ فَمَا ٱخۡتَلَفُوۤا۟ إِلَّا مِنۢ بَعۡدِ مَا جَاۤءَهُمُ ٱلۡعِلۡمُ بَغۡیَۢا بَیۡنَهُمۡۚ إِنَّ رَبَّكَ یَقۡضِی بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ ۝١٧", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وآتينا بني إسرائيل شرائع واضحات في الحلال والحرام، ودلالات تبين الحق من الباطل، فما اختلفوا إلا من بعد ما جاءهم العلم، وقامت الحجة عليهم، وإنما حَمَلهم على ذلك بَغْيُ بعضهم على بعض؛ طلبًا للرفعة والرئاسة، إن ربك -أيها الرسول- يحكم بين المختلفين من بني إسرائيل يوم القيامة فيما كانوا فيه يختلفون في الدنيا. وفي هذا تحذير لهذه الأمة أن تسلك مسلكهم.", "isBasmala": false, "translation_en": "And We gave them precise rulings. They fell into dispute only after knowledge came to them, out of mutual rivalry. Your Lord will judge between them on the Day of Resurrection regarding the things they differed about.", "translation_id": "Dan Kami berikan kepada mereka keterangan-keterangan yang nyata tentang urusan (agama); maka mereka tidak berselisih melainkan sesudah datang kepada mereka pengetahuan karena kedengkian yang ada di antara mereka. Sesungguhnya Tuhanmu akan memutuskan antara mereka pada hari kiamat terhadap apa yang mereka selalu berselisih padanya.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 18, "text": "ثُمَّ جَعَلۡنَـٰكَ عَلَىٰ شَرِیعَةࣲ مِّنَ ٱلۡأَمۡرِ فَٱتَّبِعۡهَا وَلَا تَتَّبِعۡ أَهۡوَاۤءَ ٱلَّذِینَ لَا یَعۡلَمُونَ ۝١٨", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "ثم جعلناك -أيها الرسول- على منهاج واضح من أمر الدين، فاتبع الشريعة التي جعلناك عليها، ولا تتبع أهواء الجاهلين بشرع الله الذين لا يعلمون الحق. وفي الآية دلالة عظيمة على كمال هذا الدين وشرفه، ووجوب الانقياد لحكمه، وعدم الميل إلى أهواء الكفرة والملحدين.", "isBasmala": false, "translation_en": "Then We set you upon a pathway of faith, so follow it, and do not follow the inclinations of those who do not know.", "translation_id": "Kemudian Kami jadikan kamu berada di atas suatu syariat (peraturan) dari urusan (agama itu), maka ikutilah syariat itu dan janganlah kamu ikuti hawa nafsu orang-orang yang tidak mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 19, "text": "إِنَّهُمۡ لَن یُغۡنُوا۟ عَنكَ مِنَ ٱللَّهِ شَیۡـࣰٔاۚ وَإِنَّ ٱلظَّـٰلِمِینَ بَعۡضُهُمۡ أَوۡلِیَاۤءُ بَعۡضࣲۖ وَٱللَّهُ وَلِیُّ ٱلۡمُتَّقِینَ ۝١٩", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "إن هؤلاء المشركين بربهم الذين يدعونك إلى اتباع أهوائهم لن يغنوا عنك -أيها الرسول- من عقاب الله شيئًا إن اتبعت أهواءهم، وإن الظالمين المتجاوزين حدود الله من المنافقين واليهود وغيرهم بعضهم أنصار بعض على المؤمنين بالله وأهل طاعته، والله ناصر المتقين ربَّهم بأداء فرائضه واجتناب نواهيه.", "isBasmala": false, "translation_en": "They will not help you against God in any way. The wrongdoers are allies of one another, while God is the Protector of the righteous.", "translation_id": "Sesungguhnya mereka sekali-kali tidak akan dapat menolak dari kamu sedikitpun dari siksaan Allah. Dan Sesungguhnya orang-orang yang zalim itu sebagian mereka menjadi penolong bagi sebagian yang lain, dan Allah adalah pelindung orang-orang yang bertakwa.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 20, "text": "هَـٰذَا بَصَـٰۤىِٕرُ لِلنَّاسِ وَهُدࣰى وَرَحۡمَةࣱ لِّقَوۡمࣲ یُوقِنُونَ ۝٢٠", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "هذا القرآن الذي أنزلناه إليك أيها الرسول بصائر يبصر به الناس الحق من الباطل، ويعرفون به سبيل الرشاد، وهدى ورحمةٌ لقوم يوقنون بحقيقة صحته، وأنه تنزيل من الله العزيز الحكيم.", "isBasmala": false, "translation_en": "This is an illumination for mankind, and guidance, and mercy for people who believe with certainty.", "translation_id": "Al Quran ini adalah pedoman bagi manusia, petunjuk dan rahmat bagi kaum yang meyakini.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 21, "text": "أَمۡ حَسِبَ ٱلَّذِینَ ٱجۡتَرَحُوا۟ ٱلسَّیِّـَٔاتِ أَن نَّجۡعَلَهُمۡ كَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ سَوَاۤءࣰ مَّحۡیَاهُمۡ وَمَمَاتُهُمۡۚ سَاۤءَ مَا یَحۡكُمُونَ ۝٢١", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "بل أظنَّ الذين اكتسبوا السيئات، وكذَّبوا رسل الله، وخالفوا أمر ربهم، وعبدوا غيره، أن نجعلهم كالذين آمنوا بالله، وصدقوا رسله وعملوا الصالحات، وأخلصوا له العبادة دون سواه، ونساويَهم بهم في الدنيا والآخرة؟ ساء حكمهم بالمساواة بين الفجار والأبرار في الآخرة.", "isBasmala": false, "translation_en": "Do those who perpetrate the evil deeds assume that We will regard them as equal to those who believe and do righteous deeds, whether in their life or their death? Evil is their judgment!", "translation_id": "Apakah orang-orang yang membuat kejahatan itu menyangka bahwa Kami akan menjadikan mereka seperti orang-orang yang beriman dan mengerjakan amal saleh, yaitu sama antara kehidupan dan kematian mereka? Amat buruklah apa yang mereka sangka itu.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 22, "text": "وَخَلَقَ ٱللَّهُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَلِتُجۡزَىٰ كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ وَهُمۡ لَا یُظۡلَمُونَ ۝٢٢", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وخَلَق الله السموات والأرض بالحق والعدل والحكمة؛ ولكي تجزى كل نفس في الآخرة بما كسبت مِن خير أو شر، وهم لا يُظْلمون جزاء أعمالهم.", "isBasmala": false, "translation_en": "God created the heavens and the earth with justice, so that every soul will be repaid for what it has earned. And they will not be wronged.", "translation_id": "Dan Allah menciptakan langit dan bumi dengan tujuan yang benar dan agar dibalasi tiap-tiap diri terhadap apa yang dikerjakannya, dan mereka tidak akan dirugikan.", "manzil": 6, "manzil_display": ""}], "501": [{"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 23, "text": "أَفَرَءَیۡتَ مَنِ ٱتَّخَذَ إِلَـٰهَهُۥ هَوَىٰهُ وَأَضَلَّهُ ٱللَّهُ عَلَىٰ عِلۡمࣲ وَخَتَمَ عَلَىٰ سَمۡعِهِۦ وَقَلۡبِهِۦ وَجَعَلَ عَلَىٰ بَصَرِهِۦ غِشَـٰوَةࣰ فَمَن یَهۡدِیهِ مِنۢ بَعۡدِ ٱللَّهِۚ أَفَلَا تَذَكَّرُونَ ۝٢٣", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "أفرأيت -أيها الرسول- من اتخذ هواه إلهًا له، فلا يهوى شيئًا إلا فَعَله، وأضلَّه الله بعد بلوغ العلم إليه وقيام الحجة عليه، فلا يسمع مواعظ الله، ولا يعتبر بها، وطبع على قلبه، فلا يعقل به شيئًا، وجعل على بصره غطاء، فلا يبصر به حجج الله؟ فمن يوفقه لإصابة الحق والرشد بعد إضلال الله إياه؟ أفلا تذكرون -أيها الناس- فتعلموا أنَّ مَن فَعَل الله به ذلك فلن يهتدي أبدًا، ولن يجد لنفسه وليًا مرشدًا؟ والآية أصل في التحذير من أن يكون الهوى هو الباعث للمؤمنين على أعمالهم.", "isBasmala": false, "translation_en": "Have you considered him who has taken his desire for his god? God has knowingly led him astray, and has sealed his hearing and his heart, and has placed a veil over his vision. Who will guide him after God? Will you not reflect?", "translation_id": "Maka pernahkah kamu melihat orang yang menjadikan hawa nafsunya sebagai tuhannya dan Allah membiarkannya berdasarkan ilmu-Nya dan Allah telah mengunci mati pendengaran dan hatinya dan meletakkan tutupan atas penglihatannya? Maka siapakah yang akan memberinya petunjuk sesudah Allah (membiarkannya sesat). Maka mengapa kamu tidak mengambil pelajaran?", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 24, "text": "وَقَالُوا۟ مَا هِیَ إِلَّا حَیَاتُنَا ٱلدُّنۡیَا نَمُوتُ وَنَحۡیَا وَمَا یُهۡلِكُنَاۤ إِلَّا ٱلدَّهۡرُۚ وَمَا لَهُم بِذَ ٰلِكَ مِنۡ عِلۡمٍۖ إِنۡ هُمۡ إِلَّا یَظُنُّونَ ۝٢٤", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وقال هؤلاء المشركون: ما الحياة إلا حياتنا الدنيا التي نحن فيها، لا حياة سواها؛ تكذيبا منهم بالبعث بعد الممات، وما يهلكنا إلا مرُّ الليالي والأيام وطول العمر؛ إنكارًا منهم أن يكون لهم رب يفنيهم ويهلكهم، وما لهؤلاء المشركين من علم بذلك، ما هم إلا يتكلمون بالظن والوهم والخيال.", "isBasmala": false, "translation_en": "And they say, \"There is nothing but this our present life; we die and we live, and nothing destroys us except time.\" But they have no knowledge of that; they are only guessing.", "translation_id": "Dan mereka berkata: \"Kehidupan ini tidak lain hanyalah kehidupan di dunia saja, kita mati dan kita hidup dan tidak ada yang akan membinasakan kita selain masa\", dan mereka sekali-kali tidak mempunyai pengetahuan tentang itu, mereka tidak lain hanyalah menduga-duga saja.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 25, "text": "وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ مَّا كَانَ حُجَّتَهُمۡ إِلَّاۤ أَن قَالُوا۟ ٱئۡتُوا۟ بِـَٔابَاۤىِٕنَاۤ إِن كُنتُمۡ صَـٰدِقِینَ ۝٢٥", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "إذا تتلى على هؤلاء المشركين المكذبين بالبعث آياتنا واضحات، لم يكن لهم حجة إلا قولهم للرسول محمد: أحْي أنت والمؤمنون معك آباءنا الذين قد هلكوا، إن كنتم صادقين فيما تقولون.", "isBasmala": false, "translation_en": "When Our clarifying Verses are recited to them, their only argument is to say, \"Bring back our ancestors, if you are truthful.\"", "translation_id": "Dan apabila dibacakan kepada mereka ayat-ayat Kami yang jelas, tidak ada bantahan mereka selain dari mengatakan: \"Datangkanlah nenek moyang kami jika kamu adalah orang-orang yang benar\".", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 26, "text": "قُلِ ٱللَّهُ یُحۡیِیكُمۡ ثُمَّ یُمِیتُكُمۡ ثُمَّ یَجۡمَعُكُمۡ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ لَا رَیۡبَ فِیهِ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ ۝٢٦", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين المكذبين بالبعث: الله سبحانه وتعالى يحييكم في الدنيا ما شاء لكم الحياة، ثم يميتكم فيها، ثم يجمعكم جميعا أحياء إلى يوم القيامة لا شك فيه، ولكن أكثر الناس لا يعلمون قدرة الله على إماتتهم ثم بعثهم يوم القيامة.", "isBasmala": false, "translation_en": "Say, \"God gives you life, then He makes you die; then He gathers you for the Day of Resurrection, about which there is no doubt. But most people do not know.\"", "translation_id": "Katakanlah: \"Allah-lah yang menghidupkan kamu kemudian mematikan kamu, setelah itu mengumpulkan kamu pada hari kiamat yang tidak ada keraguan padanya; akan tetapi kebanyakan manusia tidak mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 27, "text": "وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یَوۡمَىِٕذࣲ یَخۡسَرُ ٱلۡمُبۡطِلُونَ ۝٢٧", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "ولله سبحانه سلطان السموات السبع والأرض خَلْقًا ومُلْكًا وعبودية. ويوم تجيء الساعة التي يبعث فيها الموتى من قبورهم ويحاسبون، يخسر الكافرون بالله الجاحدون بما أنزله على رسوله من الآيات البينات والدلائل الواضحات.", "isBasmala": false, "translation_en": "To God belongs the kingship of the heavens and the earth. On the Day when the Hour takes place, on that Day the falsifiers will lose.", "translation_id": "Dan hanya kepunyaan Allah kerajaan langit dan bumi. Dan pada hari terjadinya kebangkitan, akan rugilah pada hari itu orang-orang yang mengerjakan kebathilan.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 28, "text": "وَتَرَىٰ كُلَّ أُمَّةࣲ جَاثِیَةࣰۚ كُلُّ أُمَّةࣲ تُدۡعَىٰۤ إِلَىٰ كِتَـٰبِهَا ٱلۡیَوۡمَ تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ۝٢٨", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وترى -أيها الرسول- يوم تقوم الساعة أهل كل ملة ودين جاثمين على رُكَبهم، كل أمة تُدْعى إلى كتاب أعمالها، ويقال لهم: اليوم تُجزون ما كنتم تعملون من خير أو شر.", "isBasmala": false, "translation_en": "You will see every community on its knees; every community will be called to its Book: \"Today you are being repaid for what you used to do.", "translation_id": "Dan (pada hari itu) kamu lihat tiap-tiap umat berlutut. Tiap-tiap umat dipanggil untuk (melihat) buku catatan amalnya. Pada hari itu kamu diberi balasan terhadap apa yang telah kamu kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 29, "text": "هَـٰذَا كِتَـٰبُنَا یَنطِقُ عَلَیۡكُم بِٱلۡحَقِّۚ إِنَّا كُنَّا نَسۡتَنسِخُ مَا كُنتُمۡ تَعۡمَلُونَ ۝٢٩", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "هذا كتابنا ينطق عليكم بجميع أعمالكم من غير زيادة ولا نقص، إنَّا كنا نأمر الحفظة أن تكتب أعمالكم عليكم.", "isBasmala": false, "translation_en": "This Book of Ours speaks about you in truth. We have been transcribing what you have been doing.\"", "translation_id": "(Allah berfirman): \"Inilah kitab (catatan) Kami yang menuturkan terhadapmu dengan benar. Sesungguhnya Kami telah menyuruh mencatat apa yang telah kamu kerjakan\".", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 30, "text": "فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَیُدۡخِلُهُمۡ رَبُّهُمۡ فِی رَحۡمَتِهِۦۚ ذَ ٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡمُبِینُ ۝٣٠", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "فأما الذين آمنوا بالله ورسوله في الدنيا، وامتثلوا أوامره واجتنبوا نواهيه، فيدخلهم ربهم في جنته برحمته، ذلك الدخول هو الفوز المبين الذي لا فوز بعده.", "isBasmala": false, "translation_en": "As for those who believed and did righteous deeds, their Lord will admit them into His mercy. That is the clear triumph.", "translation_id": "Adapun orang-orang yang beriman dan mengerjakan amal saleh maka Tuhan mereka memasukkan mereka ke dalam rahmat-Nya (surga). Itulah keberuntungan yang nyata.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 31, "text": "وَأَمَّا ٱلَّذِینَ كَفَرُوۤا۟ أَفَلَمۡ تَكُنۡ ءَایَـٰتِی تُتۡلَىٰ عَلَیۡكُمۡ فَٱسۡتَكۡبَرۡتُمۡ وَكُنتُمۡ قَوۡمࣰا مُّجۡرِمِینَ ۝٣١", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وأما الذين جحدوا أن الله هو الإله الحق وكذَّبوا رسله ولم يعملوا بشرعه، فيقال لهم تقريعًا وتوبيخًا: أفلم تكن آياتي في الدنيا تتلى عليكم، فاستكبرتم عن استماعها والإيمان بها، وكنتم قومًا مشركين تكسِبون المعاصي ولا تؤمنون بثواب ولا عقاب؟", "isBasmala": false, "translation_en": "But as for those who disbelieved: \"Were My revelations not recited to you? But you turned arrogant, and were guilty people.\"", "translation_id": "Dan adapun orang-orang yang kafir (kepada mereka dikatakan): \"Maka apakah belum ada ayat-ayat-Ku yang dibacakan kepadamu lalu kamu menyombongkan diri dan kamu jadi kaum yang berbuat dosa?\"", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 32, "text": "وَإِذَا قِیلَ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَٱلسَّاعَةُ لَا رَیۡبَ فِیهَا قُلۡتُم مَّا نَدۡرِی مَا ٱلسَّاعَةُ إِن نَّظُنُّ إِلَّا ظَنࣰّا وَمَا نَحۡنُ بِمُسۡتَیۡقِنِینَ ۝٣٢", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وإذا قيل لكم: إن وعد الله ببعث الناس من قبورهم حق، والساعة لا شك فيها، قلتم: ما ندري ما الساعة؟ وما نتوقع وقوعها إلا توهمًا، وما نحن بمتحققين أن الساعة آتية.", "isBasmala": false, "translation_en": "And when it was said, \"The promise of God is true, and of the Hour there is no doubt,\" you said, \"We do not know what the Hour is; we think it is only speculation; we are not convinced.\"", "translation_id": "Dan apabila dikatakan (kepadamu): \"Sesungguhnya janji Allah itu adalah benar dan hari berbangkit itu tidak ada keraguan padanya\", niscaya kamu menjawab: \"Kami tidak tahu apakah hari kiamat itu, kami sekali-kali tidak lain hanyalah menduga-duga saja dan kami sekali-kali tidak meyakini(nya)\".", "manzil": 6, "manzil_display": ""}], "502": [{"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 33, "text": "وَبَدَا لَهُمۡ سَیِّـَٔاتُ مَا عَمِلُوا۟ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٣٣", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وظهر لهؤلاء الذين كانوا يكذِّبون بآيات الله ما عملوا في الدنيا من الأعمال القبيحة، ونزل بهم من عذاب الله جزاء ما كانوا به يستهزئون.", "isBasmala": false, "translation_en": "The evils of what they did will become evident to them, and the very thing they ridiculed will haunt them.", "translation_id": "Dan nyatalah bagi mereka keburukan-keburukan dari apa yang mereka kerjakan dan mereka diliputi oleh (azab) yang mereka selalu memperolok-olokkannya.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 34, "text": "وَقِیلَ ٱلۡیَوۡمَ نَنسَىٰكُمۡ كَمَا نَسِیتُمۡ لِقَاۤءَ یَوۡمِكُمۡ هَـٰذَا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِینَ ۝٣٤", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وقيل لهؤلاء الكفرة: اليوم نترككم في عذاب جهنم، كما تركتم الإيمان بربكم والعمل للقاء يومكم هذا، ومسكنكم نار جهنم، وما لكم من ناصرين ينصرونكم من عذاب الله.", "isBasmala": false, "translation_en": "And it will be said, \"Today We forget you, as you forgot the encounter of this Day of yours. Your abode is the Fire, and there are no saviors for you.", "translation_id": "Dan dikatakan (kepada mereka): \"Pada hari ini Kami melupakan kamu sebagaimana kamu telah melupakan pertemuan (dengan) harimu ini dan tempat kembalimu ialah neraka dan kamu sekali-kali tidak memperoleh penolong\".", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 35, "text": "ذَ ٰلِكُم بِأَنَّكُمُ ٱتَّخَذۡتُمۡ ءَایَـٰتِ ٱللَّهِ هُزُوࣰا وَغَرَّتۡكُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۚ فَٱلۡیَوۡمَ لَا یُخۡرَجُونَ مِنۡهَا وَلَا هُمۡ یُسۡتَعۡتَبُونَ ۝٣٥", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "هذا الذي حلَّ بكم مِن عذاب الله؛ بسبب أنكم اتخذتم آيات الله وحججه هزوًا ولعبًا، وخدعتكم زينة الحياة الدنيا، فاليوم لا يُخرجون من النار، ولا هم يُرَدُّون إلى الدنيا؛ ليتوبوا ويعملوا صالحًا.", "isBasmala": false, "translation_en": "That is because you took God's revelations for a joke, and the worldly life lured you.\" So today they will not be brought out of it, and they will not be allowed to repent.", "translation_id": "Yang demikian itu, karena sesungguhnya kamu menjadikan ayat-ayat Allah sebagai olok-olokan dan kamu telah ditipu oleh kehidupan dunia, maka pada hari ini mereka tidak dikeluarkan dari neraka dan tidak pula mereka diberi kesempatan untuk bertaubat.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 36, "text": "فَلِلَّهِ ٱلۡحَمۡدُ رَبِّ ٱلسَّمَـٰوَ ٰتِ وَرَبِّ ٱلۡأَرۡضِ رَبِّ ٱلۡعَـٰلَمِینَ ۝٣٦", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "فلله سبحانه وتعالى وحده الحمد على نعمه التي لا تحصى على خلقه، رب السموات والأرض وخالقهما ومدبرهما، رب الخلائق أجمعين.", "isBasmala": false, "translation_en": "Praise belongs to God; Lord of the heavens, Lord of the earth, Lord of humanity.", "translation_id": "Maka bagi Allah-lah segala puji, Tuhan langit dan Tuhan bumi, Tuhan semesta alam.", "manzil": 6, "manzil_display": ""}, {"sura": 45, "sura_name": "الجاثية", "revelation": "Makkiyah", "aya": 37, "text": "وَلَهُ ٱلۡكِبۡرِیَاۤءُ فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٣٧", "juz": 25, "hizb": "(*¾ ح 50*)", "tafsir": "وله وحده سبحانه العظمة والجلال والكبرياء والسُّلْطان والقدرة والكمال في السموات والأرض، وهو العزيز الذي لا يغالَب، الحكيم في أقواله وأفعاله وقدره وشرعه، تعالى وتقدَّس، لا إله إلا هو.", "isBasmala": false, "translation_en": "To Him belongs all supremacy in the heavens and the earth. He is the Majestic, the Wise.", "translation_id": "Dan bagi-Nya-lah keagungan di langit dan bumi, Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 26, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 1, "text": "۞ حمۤ ۝١", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "(حم) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة.", "isBasmala": false, "translation_en": "Ha, Meem.", "translation_id": "Haa Miim.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 2, "text": "تَنزِیلُ ٱلۡكِتَـٰبِ مِنَ ٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ ۝٢", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "هذا القرآن تنزيل من الله العزيز الذي لا يغالَب، الحكيم في تدبيره وصنعه.", "isBasmala": false, "translation_en": "The sending down of the Scripture is from God, the Honorable, the Wise.", "translation_id": "Diturunkan Kitab ini dari Allah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 3, "text": "مَا خَلَقۡنَا ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَاۤ إِلَّا بِٱلۡحَقِّ وَأَجَلࣲ مُّسَمࣰّىۚ وَٱلَّذِینَ كَفَرُوا۟ عَمَّاۤ أُنذِرُوا۟ مُعۡرِضُونَ ۝٣", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "ما خلقنا السموات والأرض وما بينهما إلا بالحق، لا عبثًا ولا سدى؛ بل ليعرف العباد عظمة خالقهما فيعبدوه وحده، ويعلموا أنه قادر على أن يعيد العباد بعد موتهم، وليقيموا الحق والعدل فيما بينهم وإلى أجل معلوم عنده. والذين جحدوا أن الله هو الإله الحق، عما أنذرهم به القرآن معرضون، لا يتعظون ولا يتفكرون.", "isBasmala": false, "translation_en": "We did not create the heavens and the earth and what lies between them except with reason, and for a finite period. But the blasphemers continue to ignore the warnings they receive.", "translation_id": "Kami tiada menciptakan langit dan bumi dan apa yang ada antara keduanya melainkan dengan (tujuan) yang benar dan dalam waktu yang ditentukan. Dan orang-orang yang kafir berpaling dari apa yang diperingatkan kepada mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 4, "text": "قُلۡ أَرَءَیۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِی مَاذَا خَلَقُوا۟ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكࣱ فِی ٱلسَّمَـٰوَ ٰتِۖ ٱئۡتُونِی بِكِتَـٰبࣲ مِّن قَبۡلِ هَـٰذَاۤ أَوۡ أَثَـٰرَةࣲ مِّنۡ عِلۡمٍ إِن كُنتُمۡ صَـٰدِقِینَ ۝٤", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "قل -أيها الرسول- لهؤلاء الكفار: أرأيتم الآلهة، والأوثان التي تعبدونها من دون الله، أروني أيَّ شيء خلقوا من الأرض، أم لهم مع الله نصيب من خلق السموات؟ ائتوني بكتاب من عند الله من قبل هذا القرآن أو ببقيَّة من علم، إن كنتم صادقين فيما تزعمون.", "isBasmala": false, "translation_en": "Say, \"Have you considered those you worship instead of God? Show me which portion of the earth they have created. Or do they own a share of the heavens? Bring me a scripture prior to this one, or some trace of knowledge, if you are truthful.\"", "translation_id": "Katakanlah: \"Terangkanlah kepadaku tentang apa yang kamu sembah selain Allah; perlihatkan kepada-Ku apakah yang telah mereka ciptakan dari bumi ini atau adakah mereka berserikat (dengan Allah) dalam (penciptaan) langit? Bawalah kepada-Ku Kitab yang sebelum (Al Quran) ini atau peninggalan dari pengetahuan (orang-orang dahulu), jika kamu adalah orang-orang yang benar\"", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 5, "text": "وَمَنۡ أَضَلُّ مِمَّن یَدۡعُوا۟ مِن دُونِ ٱللَّهِ مَن لَّا یَسۡتَجِیبُ لَهُۥۤ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ وَهُمۡ عَن دُعَاۤىِٕهِمۡ غَـٰفِلُونَ ۝٥", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "لا أحد أضلُّ وأجهل ممن يدعو من دون الله آلهة لا تستجيب دعاءه أبدًا؛ لأنها من الأموات أو الأحجار والأشجار ونحوها، وهي غافلة عن دعاء مَن يعبدها، عاجزة عن نفعه أو ضره.", "isBasmala": false, "translation_en": "Who is more wrong than him who invokes, besides God, those who will not answer him until the Day of Resurrection, and are heedless of their prayers?", "translation_id": "Dan siapakah yang lebih sesat daripada orang yang menyembah sembahan-sembahan selain Allah yang tiada dapat memperkenankan (doa)nya sampai hari kiamat dan mereka lalai dari (memperhatikan) doa mereka?", "manzil": 6, "manzil_display": ""}], "503": [{"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 6, "text": "وَإِذَا حُشِرَ ٱلنَّاسُ كَانُوا۟ لَهُمۡ أَعۡدَاۤءࣰ وَكَانُوا۟ بِعِبَادَتِهِمۡ كَـٰفِرِینَ ۝٦", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "وإذا حُشر الناس يوم القيامة للحساب والجزاء كانت الآلهة التي يدعونها في الدنيا لهم أعداء، تلعنهم وتتبرأ منهم، وتنكر علمها بعبادتهم إياها.", "isBasmala": false, "translation_en": "And when humanity is gathered, they will be enemies to them, and will renounce their worship of them.", "translation_id": "Dan apabila manusia dikumpulkan (pada hari kiamat) niscaya sembahan-sembahan itu menjadi musuh mereka dan mengingkari pemujaan-pemujaan mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 7, "text": "وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ قَالَ ٱلَّذِینَ كَفَرُوا۟ لِلۡحَقِّ لَمَّا جَاۤءَهُمۡ هَـٰذَا سِحۡرࣱ مُّبِینٌ ۝٧", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "وإذا تتلى على هؤلاء المشركين آياتنا واضحات، قال الذين كفروا حين جاءهم القرآن: هذا سحر ظاهر.", "isBasmala": false, "translation_en": "When Our revelations are recited to them, plain and clear, those who disbelieve say of the truth when it has come to them, \"This is obviously magic.\"", "translation_id": "Dan apabila dibacakan kepada mereka ayat-ayat Kami yang menjelaskan, berkatalah orang-orang yang mengingkari kebenaran ketika kebenaran itu datang kepada mereka: \"Ini adalah sihir yang nyata\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 8, "text": "أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَیۡتُهُۥ فَلَا تَمۡلِكُونَ لِی مِنَ ٱللَّهِ شَیۡـًٔاۖ هُوَ أَعۡلَمُ بِمَا تُفِیضُونَ فِیهِۚ كَفَىٰ بِهِۦ شَهِیدَۢا بَیۡنِی وَبَیۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ ۝٨", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "بل أيقول هؤلاء المشركون: إن محمدًا اختلق هذا القرآن؟ قل لهم -أيها الرسول-: إن اختلقته على الله فإنكم لا تقدرون أن تدفعوا عني من عقاب الله شيئًا، إن عاقبني على ذلك. هو سبحانه أعلم من كل شيء سواه بما تقولون في هذا القرآن، كفى بالله شاهدًا عليَّ وعليكم، وهو الغفور لمن تاب إليه، الرحيم بعباده المؤمنين.", "isBasmala": false, "translation_en": "Or do they say, \"He invented it himself\"? Say, \"If I invented it myself, there is nothing you can do to protect me from God. He knows well what you are engaged in. He is sufficient witness between me and you. He is the Forgiver, the Merciful.\"", "translation_id": "Bahkan mereka mengatakan: \"Dia (Muhammad) telah mengada-adakannya (Al Quran)\". Katakanlah: \"Jika aku mengada-adakannya, maka kamu tiada mempunyai kuasa sedikitpun mempertahankan aku dari (azab) Allah itu. Dia lebih mengetahui apa-apa yang kamu percakapkan tentang Al Quran itu. Cukuplah Dia menjadi saksi antaraku dan antaramu dan Dialah Yang Maha Pengampun lagi Maha Penyayang\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 9, "text": "قُلۡ مَا كُنتُ بِدۡعࣰا مِّنَ ٱلرُّسُلِ وَمَاۤ أَدۡرِی مَا یُفۡعَلُ بِی وَلَا بِكُمۡۖ إِنۡ أَتَّبِعُ إِلَّا مَا یُوحَىٰۤ إِلَیَّ وَمَاۤ أَنَا۠ إِلَّا نَذِیرࣱ مُّبِینࣱ ۝٩", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "قل -أيها الرسول- لمشركي قومك: ما كنتُ أول رسل الله إلى خلقه، وما أدري ما يفعل الله بي ولا بكم في الدنيا، ما أتبع فيما آمركم به وفيما أفعله إلا وحي الله الذي يوحيه إليَّ، وما أنا إلا نذير بيِّن الإنذار.", "isBasmala": false, "translation_en": "Say, \"I am not different from the other messengers; and I do not know what will be done with me, or with you. I only follow what is inspired in me, and I am only a clear warner.\"", "translation_id": "Katakanlah: \"Aku bukanlah rasul yang pertama di antara rasul-rasul dan aku tidak mengetahui apa yang akan diperbuat terhadapku dan tidak (pula) terhadapmu. Aku tidak lain hanyalah mengikuti apa yang diwahyukan kepadaku dan aku tidak lain hanyalah seorang pemberi peringatan yang menjelaskan\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 10, "text": "قُلۡ أَرَءَیۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ وَكَفَرۡتُم بِهِۦ وَشَهِدَ شَاهِدࣱ مِّنۢ بَنِیۤ إِسۡرَ ٰۤءِیلَ عَلَىٰ مِثۡلِهِۦ فَـَٔامَنَ وَٱسۡتَكۡبَرۡتُمۡۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝١٠", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "قل -أيها الرسول- لمشركي قومك: أخبروني إن كان هذا القرآن من عند الله وكفرتم به، وشهد شاهد من بني إسرائيل كعبد الله بن سلام على مثل هذا القرآن، وهو ما في التوراة من التصديق بنبوة محمد صلى الله عليه وسلم، فصدَّق وعمل بما جاء في القرآن، وجحدتم ذلك استكبارًا، فهل هذا إلا أعظم الظلم وأشد الكفر؟ إن الله لا يوفِّق إلى الإسلام وإصابة الحق القوم الذين ظلموا أنفسهم بكفرهم بالله.", "isBasmala": false, "translation_en": "Say, \"Have you considered? What if it is from God and you disbelieve in it? A witness from the Children of Israel testified to its like, and has believed, while you turned arrogant. God does not guide the unjust people.\"", "translation_id": "Katakanlah: \"Terangkanlah kepadaku, bagaimanakah pendapatmu jika Al Quran itu datang dari sisi Allah, padahal kamu mengingkarinya dan seorang saksi dari Bani Israil mengakui (kebenaran) yang serupa dengan (yang tersebut dalam) Al Quran lalu dia beriman, sedang kamu menyombongkan diri. Sesungguhnya Allah tiada memberi petunjuk kepada orang-orang yang zalim\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 11, "text": "وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِلَّذِینَ ءَامَنُوا۟ لَوۡ كَانَ خَیۡرࣰا مَّا سَبَقُونَاۤ إِلَیۡهِۚ وَإِذۡ لَمۡ یَهۡتَدُوا۟ بِهِۦ فَسَیَقُولُونَ هَـٰذَاۤ إِفۡكࣱ قَدِیمࣱ ۝١١", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "وقال الذين جحدوا نبوة محمد صلى الله عليه وسلم للذين آمنوا به: لو كان تصديقكم محمدًا على ما جاء به خيرًا ما سبقتمونا إلى التصديق به، وإذ لم يهتدوا بالقرآن ولم ينتفعوا بما فيه من الحق فسيقولون: هذا كذب، مأثور عن الناس الأقدمين.", "isBasmala": false, "translation_en": "Those who disbelieve say to those who believe, \"If it were anything good, they would not have preceded us to it.\" And since they were not guided by it, they will say, \"This is an ancient lie.\"", "translation_id": "Dan orang-orang kafir berkata kepada orang-orang yang beriman: \"Kalau sekiranya di (Al Quran) adalah suatu yang baik, tentulah mereka tiada mendahului kami (beriman) kepadanya. Dan karena mereka tidak mendapat petunjuk dengannya maka mereka akan berkata: \"Ini adalah dusta yang lama\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 12, "text": "وَمِن قَبۡلِهِۦ كِتَـٰبُ مُوسَىٰۤ إِمَامࣰا وَرَحۡمَةࣰۚ وَهَـٰذَا كِتَـٰبࣱ مُّصَدِّقࣱ لِّسَانًا عَرَبِیࣰّا لِّیُنذِرَ ٱلَّذِینَ ظَلَمُوا۟ وَبُشۡرَىٰ لِلۡمُحۡسِنِینَ ۝١٢", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "ومن قبل هذا القرآن أنزلنا التوراة إمامًا لبني إسرائيل يقتدون بها، ورحمة لمن آمن بها وعمل بما فيها، وهذا القرآن مصدق لما قبله من الكتب، أنزلناه بلسان عربي؛ لينذر الذين ظلموا أنفسهم بالكفر والمعصية، وبشرى للذين أطاعوا الله، فأحسنوا في إيمانهم وطاعتهم في الدنيا.", "isBasmala": false, "translation_en": "And before it was the Book of Moses, a model and a mercy. And this is a confirming Book, in the Arabic language, to warn those who do wrong-and good news for the doers of good.", "translation_id": "Dan sebelum Al Quran itu telah ada kitab Musa sebagai petunjuk dan rahmat. Dan ini (Al Quran) adalah kitab yang membenarkannya dalam bahasa Arab untuk memberi peringatan kepada orang-orang yang zalim dan memberi kabar gembira kepada orang-orang yang berbuat baik.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 13, "text": "إِنَّ ٱلَّذِینَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَـٰمُوا۟ فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ ۝١٣", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "إن الذين قالوا: ربنا الله، ثم استقاموا على الإيمان به، فلا خوف عليهم من فزع يوم القيامة وأهواله، ولا هم يحزنون على ما خلَّفوا وراءهم بعد مماتهم من حظوظ الدنيا.", "isBasmala": false, "translation_en": "Those who say, \"Our Lord is God,\" then lead a righteous life-they have nothing to fear, nor shall they grieve.", "translation_id": "Sesungguhnya orang-orang yang mengatakan: \"Tuhan kami ialah Allah\", kemudian mereka tetap istiqamah maka tidak ada kekhawatiran terhadap mereka dan mereka tiada (pula) berduka cita.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 14, "text": "أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَنَّةِ خَـٰلِدِینَ فِیهَا جَزَاۤءَۢ بِمَا كَانُوا۟ یَعۡمَلُونَ ۝١٤", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "أولئك أهل الجنة ماكثين فيها أبدًا برحمة الله تعالى لهم، وبما قدَّموا من عمل صالح في دنياهم.", "isBasmala": false, "translation_en": "These are the inhabitants of Paradise, where they will dwell forever-a reward for what they used to do.", "translation_id": "Mereka itulah penghuni-penghuni surga, mereka kekal di dalamnya; sebagai balasan atas apa yang telah mereka kerjakan.", "manzil": 6, "manzil_display": ""}], "504": [{"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 15, "text": "وَوَصَّیۡنَا ٱلۡإِنسَـٰنَ بِوَ ٰلِدَیۡهِ إِحۡسَـٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهࣰا وَوَضَعَتۡهُ كُرۡهࣰاۖ وَحَمۡلُهُۥ وَفِصَـٰلُهُۥ ثَلَـٰثُونَ شَهۡرًاۚ حَتَّىٰۤ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِینَ سَنَةࣰ قَالَ رَبِّ أَوۡزِعۡنِیۤ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِیۤ أَنۡعَمۡتَ عَلَیَّ وَعَلَىٰ وَ ٰلِدَیَّ وَأَنۡ أَعۡمَلَ صَـٰلِحࣰا تَرۡضَىٰهُ وَأَصۡلِحۡ لِی فِی ذُرِّیَّتِیۤۖ إِنِّی تُبۡتُ إِلَیۡكَ وَإِنِّی مِنَ ٱلۡمُسۡلِمِینَ ۝١٥", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "ووصينا الإنسان أن يحسن في صحبته لوالديه بِرًّا بهما في حياتهما وبعد مماتهما، فقد حملته أمه جنينًا في بطنها على مشقة وتعب، وولدته على مشقة وتعب أيضًا، ومدة حمله وفطامه ثلاثون شهرًا. وفي ذكر هذه المشاق التي تتحملها الأم دون الأب، دليل على أن حقها على ولدها أعظم من حق الأب. حتى إذا بلغ هذا الإنسان نهاية قوته البدنية والعقلية، وبلغ أربعين سنة دعا ربه قائلا: ربي ألهمني أن أشكر نعمتك التي أنعمتها عليَّ وعلى والديَّ، واجعلني أعمل صالحًا ترضاه، وأصلح لي في ذريتي، إني تبت إليك من ذنوبي، وإني من الخاضعين لك بالطاعة والمستسلمين لأمرك ونهيك، المنقادين لحكمك.", "isBasmala": false, "translation_en": "We have enjoined upon man kindness to his parents. His mother carried him with difficulty, and delivered him with difficulty. His bearing and weaning takes thirty months. Until, when he has attained his maturity, and has reached forty years, he says, \"Lord, enable me to appreciate the blessings You have bestowed upon me and upon my parents, and to act with righteousness, pleasing You. And improve my children for me. I have sincerely repented to You, and I am of those who have surrendered.\"", "translation_id": "Kami perintahkan kepada manusia supaya berbuat baik kepada dua orang ibu bapaknya, ibunya mengandungnya dengan susah payah, dan melahirkannya dengan susah payah (pula). Mengandungnya sampai menyapihnya adalah tiga puluh bulan, sehingga apabila dia telah dewasa dan umurnya sampai empat puluh tahun ia berdoa: \"Ya Tuhanku, tunjukilah aku untuk mensyukuri nikmat Engkau yang telah Engkau berikan kepadaku dan kepada ibu bapakku dan supaya aku dapat berbuat amal yang saleh yang Engkau ridhai; berilah kebaikan kepadaku dengan (memberi kebaikan) kepada anak cucuku. Sesungguhnya aku bertaubat kepada Engkau dan sesungguhnya aku termasuk orang-orang yang berserah diri\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 16, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ نَتَقَبَّلُ عَنۡهُمۡ أَحۡسَنَ مَا عَمِلُوا۟ وَنَتَجَاوَزُ عَن سَیِّـَٔاتِهِمۡ فِیۤ أَصۡحَـٰبِ ٱلۡجَنَّةِۖ وَعۡدَ ٱلصِّدۡقِ ٱلَّذِی كَانُوا۟ یُوعَدُونَ ۝١٦", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "أولئك الذين نتقبل منهم أحسن ما عملوا من صالحات الأعمال، ونصفح عن سيئاتهم، في جملة أصحاب الجنة، هذا الوعد الذي وعدناهم به هو وعد الصدق الحق الذي لا شك فيه.", "isBasmala": false, "translation_en": "Those are they from whom We accept the best of their deeds, and We overlook their misdeeds, among the dwellers of Paradise-the promise of truth which they are promised.", "translation_id": "Mereka itulah orang-orang yang Kami terima dari mereka amal yang baik yang telah mereka kerjakan dan Kami ampuni kesalahan-kesalahan mereka, bersama penghuni-penghuni surga, sebagai janji yang benar yang telah dijanjikan kepada mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 17, "text": "وَٱلَّذِی قَالَ لِوَ ٰلِدَیۡهِ أُفࣲّ لَّكُمَاۤ أَتَعِدَانِنِیۤ أَنۡ أُخۡرَجَ وَقَدۡ خَلَتِ ٱلۡقُرُونُ مِن قَبۡلِی وَهُمَا یَسۡتَغِیثَانِ ٱللَّهَ وَیۡلَكَ ءَامِنۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّ فَیَقُولُ مَا هَـٰذَاۤ إِلَّاۤ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ۝١٧", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "والذي قال لوالديه إذ دعواه إلى الإيمان بالله والإقرار بالبعث: قبحًا لكما أتعِدانني أن أُخْرج من قبري حيًا، وقد مضت القرون من الأمم من قبلي، فهلكوا فلم يُبعث منهم أحد؟ ووالداه يسألان الله هدايته قائلَين له: ويلك، آمن وصدِّق واعمل صالحًا، إن وعد الله بالبعث حق لا شك فيه، فيقول لهما: ما هذا الذي تقولانه إلا ما سطَّره الأولون من الأباطيل، منقول من كتبهم.", "isBasmala": false, "translation_en": "As for him who says to his parents, \"Enough of you! Are you promising me that I will be raised up, when generations have passed away before me?\" While they cry for God's help, \"Woe to you! Believe! The promise of God is true!\" But he says, \"These are nothing but tales of the ancients.\"", "translation_id": "Dan orang yang berkata kepada dua orang ibu bapaknya: \"Cis bagi kamu keduanya, apakah kamu keduanya memperingatkan kepadaku bahwa aku akan dibangkitkan, padahal sungguh telah berlalu beberapa umat sebelumku? lalu kedua ibu bapaknya itu memohon pertolongan kepada Allah seraya mengatakan: \"Celaka kamu, berimanlah! Sesungguhnya janji Allah adalah benar\". Lalu dia berkata: \"Ini tidak lain hanyalah dongengan orang-orang dahulu belaka\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 18, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ حَقَّ عَلَیۡهِمُ ٱلۡقَوۡلُ فِیۤ أُمَمࣲ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُوا۟ خَـٰسِرِینَ ۝١٨", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "أولئك الذين هذه صفتهم وجب عليهم عذاب الله، وحلَّت بهم عقوبته وسخطه في جملة أمم مضت مِن قبلهم مِنَ الجن والإنس على الكفر والتكذيب، إنهم كانوا خاسرين ببيعهم الهدى بالضلال، والنعيم بالعذاب.", "isBasmala": false, "translation_en": "Those are they upon whom the sentence is justified, among the communities that have passed away before them, of jinn and humans. They are truly losers.", "translation_id": "Mereka itulah orang-orang yang telah pasti ketetapan (azab) atas mereka bersama umat-umat yang telah berlalu sebelum mereka dari jin dan manusia. Sesungguhnya mereka adalah orang-orang yang merugi.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 19, "text": "وَلِكُلࣲّ دَرَجَـٰتࣱ مِّمَّا عَمِلُوا۟ۖ وَلِیُوَفِّیَهُمۡ أَعۡمَـٰلَهُمۡ وَهُمۡ لَا یُظۡلَمُونَ ۝١٩", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "ولكل فريق من أهل الخير وأهل الشر منازل عند الله يوم القيمة؛ بأعمالهم التي عملوها في الدنيا، كل على وَفْق مرتبته؛ وليوفيهم الله جزاء أعمالهم، وهم لا يُظلمون بزيادة في سيئاتهم، ولا بنقص من حسناتهم.", "isBasmala": false, "translation_en": "There are degrees for everyone, according to what they have done, and He will repay them for their works in full, and they will not be wronged.", "translation_id": "Dan bagi masing-masing mereka derajat menurut apa yang telah mereka kerjakan dan agar Allah mencukupkan bagi mereka (balasan) pekerjaan-pekerjaan mereka sedang mereka tiada dirugikan.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 20, "text": "وَیَوۡمَ یُعۡرَضُ ٱلَّذِینَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَیِّبَـٰتِكُمۡ فِی حَیَاتِكُمُ ٱلدُّنۡیَا وَٱسۡتَمۡتَعۡتُم بِهَا فَٱلۡیَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَسۡتَكۡبِرُونَ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَفۡسُقُونَ ۝٢٠", "juz": 26, "hizb": "(* ح 51*)", "tafsir": "ويوم يعرض الذين كفروا على النار للعذاب، فيقال لهم توبيخًا: لقد أذهبتم طيباتكم في حياتكم الدنيا واستمتعتم بها، فاليوم - أيها الكفار- تُجْزَون عذاب الخزي والهوان في النار؛ بما كنتم تتكبرون في الأرض بغير الحق، وبما كنتم تخرجون عن طاعة الله.", "isBasmala": false, "translation_en": "On the Day when the faithless will be paraded before the Fire: \"You have squandered your good in your worldly life, and you took pleasure in them. So today you are being repaid with the torment of shame, because of your unjust arrogance on earth, and because you used to sin.\"", "translation_id": "Dan (ingatlah) hari (ketika) orang-orang kafir dihadapkan ke neraka (kepada mereka dikatakan): \"Kamu telah menghabiskan rezekimu yang baik dalam kehidupan duniawimu (saja) dan kamu telah bersenang-senang dengannya; maka pada hari ini kamu dibalasi dengan azab yang menghinakan karena kamu telah menyombongkan diri di muka bumi tanpa hak dan karena kamu telah fasik\".", "manzil": 6, "manzil_display": ""}], "505": [{"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 21, "text": "۞ وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَیۡنِ یَدَیۡهِ وَمِنۡ خَلۡفِهِۦۤ أَلَّا تَعۡبُدُوۤا۟ إِلَّا ٱللَّهَ إِنِّیۤ أَخَافُ عَلَیۡكُمۡ عَذَابَ یَوۡمٍ عَظِیمࣲ ۝٢١", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "واذكر -أيها الرسول- نبيَّ الله هودًا أخا عاد في النَّسب لا في الدين، حين أنذر قومه أن يحل بهم عقاب الله، وهم في منازلهم المعروفة بـ \"الأحقاف\"، وهي الرمال الكثيرة جنوب الجزيرة العربية، وقد مضت الرسل بإنذار قومها قبل هود وبعده: بأن لا تشركوا مع الله شيئًا في عبادتكم له، إني أخاف عليكم عذاب الله في يوم يَعْظُم هوله، وهو يوم القيامة.", "isBasmala": false, "translation_en": "And mention the brother of Aad, as he warned his people at the dunes. Warnings have passed away before him, and after him: \"Worship none but God; I fear for you the punishment of a tremendous Day.\"", "translation_id": "Dan ingatlah (Hud) saudara kaum 'Aad yaitu ketika dia memberi peringatan kepada kaumnya di Al Ahqaaf dan sesungguhnya telah terdahulu beberapa orang pemberi peringatan sebelumnya dan sesudahnya (dengan mengatakan): \"Janganlah kamu menyembah selain Allah, sesungguhnya aku khawatir kamu akan ditimpa azab hari yang besar\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 22, "text": "قَالُوۤا۟ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُنَاۤ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ ۝٢٢", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "قالوا: أجئتنا بدعوتك؛ لتصرفنا عن عبادة آلهتنا؟ فأتنا بما تعدنا به من العذاب، إن كنت من أهل الصدق في قولك ووعدك.", "isBasmala": false, "translation_en": "They said, \"Did you come to us to divert us from our gods? Then bring us what you threaten us with, if you are being truthful.\"", "translation_id": "Mereka menjawab: \"Apakah kamu datang kepada kami untuk memalingkan kami dari (menyembah) tuhan-tuhan kami? Maka datangkanlah kepada kami azab yang telah kamu ancamkan kepada kami jika kamu termasuk orang-orang yang benar\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 23, "text": "قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّاۤ أُرۡسِلۡتُ بِهِۦ وَلَـٰكِنِّیۤ أَرَىٰكُمۡ قَوۡمࣰا تَجۡهَلُونَ ۝٢٣", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "قال هود عليه السلام: إنما العلم بوقت مجيء ما وُعدتم به من العذاب عند الله، وإنما أنا رسول الله إليكم، أبلغكم عنه ما أرسلني به، ولكني أراكم قومًا تجهلون في استعجالكم العذاب، وجرأتكم على الله.", "isBasmala": false, "translation_en": "He said, \"The knowledge is only with God, and I inform you of what I was sent with; but I see you are an ignorant people.\"", "translation_id": "Ia berkata: \"Sesungguhnya pengetahuan (tentang itu) hanya pada sisi Allah dan aku (hanya) menyampaikan kepadamu apa yang aku diutus dengan membawanya tetapi aku lihat kamu adalah kaum yang bodoh\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 24, "text": "فَلَمَّا رَأَوۡهُ عَارِضࣰا مُّسۡتَقۡبِلَ أَوۡدِیَتِهِمۡ قَالُوا۟ هَـٰذَا عَارِضࣱ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِیحࣱ فِیهَا عَذَابٌ أَلِیمࣱ ۝٢٤", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "فلما رأوا العذاب الذي استعجلوه عارضًا في السماء متجهًا إلى أوديتهم قالوا: هذا سحاب ممطر لنا، فقال لهم هود عليه السلام: ليس هو بعارض غيث ورحمة كما ظننتم، بل هو عارض العذاب الذي استعجلتموه، فهو ريح فيها عذاب مؤلم موجع.", "isBasmala": false, "translation_en": "Then, when they saw a cloud approaching their valley, they said, \"This is a cloud that will bring us rain.\" \"In fact, it is what you were impatient for: a wind in which is grievous suffering.\"", "translation_id": "Maka tatkala mereka melihat azab itu berupa awan yang menuju ke lembah-lembah mereka, berkatalah mereka: \"Inilah awan yang akan menurunkan hujan kepada kami\". (Bukan!) bahkan itulah azab yang kamu minta supaya datang dengan segera (yaitu) angin yang mengandung azab yang pedih,", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 25, "text": "تُدَمِّرُ كُلَّ شَیۡءِۭ بِأَمۡرِ رَبِّهَا فَأَصۡبَحُوا۟ لَا یُرَىٰۤ إِلَّا مَسَـٰكِنُهُمۡۚ كَذَ ٰلِكَ نَجۡزِی ٱلۡقَوۡمَ ٱلۡمُجۡرِمِینَ ۝٢٥", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "تدمِّر كل شيء تمر به مما أُرسلت بهلاكه بأمر ربها ومشيئته، فأصبحوا لا يُرى في بلادهم شيء إلا مساكنهم التي كانوا يسكنونها، مثل هذا الجزاء نجزي القوم المجرمين؛ بسبب جرمهم وطغيانهم.", "isBasmala": false, "translation_en": "It will destroy everything by the command of its Lord. And when the morning came upon them, there was nothing to be seen except their dwellings. Thus We requite the guilty people.", "translation_id": "yang menghancurkan segala sesuatu dengan perintah Tuhannya, maka jadilah mereka tidak ada yang kelihatan lagi kecuali (bekas-bekas) tempat tinggal mereka. Demikianlah Kami memberi balasan kepada kaum yang berdosa.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 26, "text": "وَلَقَدۡ مَكَّنَّـٰهُمۡ فِیمَاۤ إِن مَّكَّنَّـٰكُمۡ فِیهِ وَجَعَلۡنَا لَهُمۡ سَمۡعࣰا وَأَبۡصَـٰرࣰا وَأَفۡـِٔدَةࣰ فَمَاۤ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَلَاۤ أَبۡصَـٰرُهُمۡ وَلَاۤ أَفۡـِٔدَتُهُم مِّن شَیۡءٍ إِذۡ كَانُوا۟ یَجۡحَدُونَ بِـَٔایَـٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ ۝٢٦", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "ولقد يسَّرنا لعاد أسباب التمكين في الدنيا على نحوٍ لم نمكنكم فيه معشر كفار قريش، وجعلنا لهم سمعًا يسمعون به، وأبصارًا يبصرون بها، وأفئدة يعقلون بها، فاستعملوها فيما يسخط الله عليهم، فلم تغن عنهم شيئًا إذ كانوا يكذِّبون بحجج الله، ونزل بهم من العذاب ما سخروا به واستعجلوه. وهذا وعيد من الله جل شأنه، وتحذير للكافرين.", "isBasmala": false, "translation_en": "We had empowered them in the same way as We empowered you; and We gave them the hearing, and the sight, and the minds. But neither their hearing, nor their sight, nor their minds availed them in any way. That is because they disregarded the revelations of God; and so they became surrounded by what they used to ridicule.", "translation_id": "Dan sesungguhnya Kami telah meneguhkan kedudukan mereka dalam hal-hal yang Kami belum pernah meneguhkan kedudukanmu dalam hal itu dan Kami telah memberikan kepada mereka pendengaran, penglihatan dan hati; tetapi pendengaran, penglihatan dan hati mereka itu tidak berguna sedikit juapun bagi mereka, karena mereka selalu mengingkari ayat-ayat Allah dan mereka telah diliputi oleh siksa yang dahulu selalu mereka memperolok-olokkannya.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 27, "text": "وَلَقَدۡ أَهۡلَكۡنَا مَا حَوۡلَكُم مِّنَ ٱلۡقُرَىٰ وَصَرَّفۡنَا ٱلۡـَٔایَـٰتِ لَعَلَّهُمۡ یَرۡجِعُونَ ۝٢٧", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "ولقد أهلكنا ما حولكم يا أهل \"مكة\" من القرى كعاد وثمود، فجعلناها خاوية على عروشها، وبيَّنَّا لهم أنواع الحجج والدلالات؛ لعلهم يرجعون عما كانوا عليه من الكفر بالله وآياته.", "isBasmala": false, "translation_en": "We have destroyed many townships around you, and diversified the signs, so that they may return.", "translation_id": "Dan sesungguhnya Kami telah membinasakan negeri-negeri di sekitarmu dan Kami telah mendatangkan tanda-tanda kebesaran Kami berulang-ulang supaya mereka kembali (bertaubat).", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 28, "text": "فَلَوۡلَا نَصَرَهُمُ ٱلَّذِینَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ قُرۡبَانًا ءَالِهَةَۢۖ بَلۡ ضَلُّوا۟ عَنۡهُمۡۚ وَذَ ٰلِكَ إِفۡكُهُمۡ وَمَا كَانُوا۟ یَفۡتَرُونَ ۝٢٨", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "فهلا نصر هؤلاء الذين أهلكناهم من الأمم الخالية آلهتُهم التي اتخذوا عبادتها قربانًا يتقربون بها إلى ربهم؛ لتشفع لهم عنده، بل ضلَّت عنهم آلهتهم، فلم يجيبوهم، ولا دافعوا عنهم، وذلك كذبهم وما كانوا يَفْتَرون في اتخاذهم إياهم آلهة.", "isBasmala": false, "translation_en": "Why then did the idols, whom they worshiped as means of nearness to God, not help them? In fact, they abandoned them. It was their lie, a fabrication of their own making.", "translation_id": "Maka mengapa yang mereka sembah selain Allah sebagai Tuhan untuk mendekatkan diri (kepada Allah) tidak dapat menolong mereka. Bahkan tuhan-tuhan itu telah lenyap dari mereka? Itulah akibat kebohongan mereka dan apa yang dahulu mereka ada-adakan.", "manzil": 6, "manzil_display": ""}], "506": [{"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 29, "text": "وَإِذۡ صَرَفۡنَاۤ إِلَیۡكَ نَفَرࣰا مِّنَ ٱلۡجِنِّ یَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا حَضَرُوهُ قَالُوۤا۟ أَنصِتُوا۟ۖ فَلَمَّا قُضِیَ وَلَّوۡا۟ إِلَىٰ قَوۡمِهِم مُّنذِرِینَ ۝٢٩", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "واذكر -أيها الرسول- حين بعثنا إليك، طائفة من الجن يستمعون منك القرآن، فلما حضروا، ورسول الله صلى الله عليه وسلم يقرأ، قال بعضهم لبعض: أنصتوا؛ لنستمع القرآن، فلما فرغ الرسول من تلاوة القرآن، وقد وعَوه وأثَّر فيهم، رجعوا إلى قومهم منذرين ومحذرين لهم بأس الله، إن لم يؤمنوا به.", "isBasmala": false, "translation_en": "Recall when We dispatched towards you a number of jinn, to listen to the Quran. When they came in its presence, they said, \"Pay attention!\" Then, when it was concluded, they rushed to their people, warning them.", "translation_id": "Dan (ingatlah) ketika Kami hadapkan serombongan jin kepadamu yang mendengarkan Al Quran, maka tatkala mereka menghadiri pembacaan(nya) lalu mereka berkata: \"Diamlah kamu (untuk mendengarkannya)\". Ketika pembacaan telah selesai mereka kembali kepada kaumnya (untuk) memberi peringatan.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 30, "text": "قَالُوا۟ یَـٰقَوۡمَنَاۤ إِنَّا سَمِعۡنَا كِتَـٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِ یَهۡدِیۤ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِیقࣲ مُّسۡتَقِیمࣲ ۝٣٠", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "قالوا: يا قومنا إنا سمعنا كتابًا أنزل من بعد موسى، مصدقًا لما قبله من كتب الله التي أنزلها على رسله، يهدي إلى الحق والصواب، وإلى طريق صحيح مستقيم.", "isBasmala": false, "translation_en": "They said, \"O our people, we have heard a Scripture, sent down after Moses, confirming what came before it. It guides to the truth, and to a straight path.", "translation_id": "Mereka berkata: \"Hai kaum kami, sesungguhnya kami telah mendengarkan kitab (Al Quran) yang telah diturunkan sesudah Musa yang membenarkan kitab-kitab yang sebelumnya lagi memimpin kepada kebenaran dan kepada jalan yang lurus.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 31, "text": "یَـٰقَوۡمَنَاۤ أَجِیبُوا۟ دَاعِیَ ٱللَّهِ وَءَامِنُوا۟ بِهِۦ یَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَیُجِرۡكُم مِّنۡ عَذَابٍ أَلِیمࣲ ۝٣١", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "يا قومنا أجيبوا رسول الله محمدًا إلى ما يدعوكم إليه، وصدِّقوه واعملوا بما جاءكم به، يغفر الله لكم من ذنوبكم وينقذكم من عذاب مؤلم موجع.", "isBasmala": false, "translation_en": "O our people! Answer the caller to God, and believe in Him; and He will forgive you your sins, and will save you from a painful punishment.\"", "translation_id": "Hai kaum kami, terimalah (seruan) orang yang menyeru kepada Allah dan berimanlah kepada-Nya, niscaya Allah akan mengampuni dosa-dosa kamu dan melepaskan kamu dari azab yang pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 32, "text": "وَمَن لَّا یُجِبۡ دَاعِیَ ٱللَّهِ فَلَیۡسَ بِمُعۡجِزࣲ فِی ٱلۡأَرۡضِ وَلَیۡسَ لَهُۥ مِن دُونِهِۦۤ أَوۡلِیَاۤءُۚ أُو۟لَـٰۤىِٕكَ فِی ضَلَـٰلࣲ مُّبِینٍ ۝٣٢", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "ومن لا يُجِبْ رسول الله إلى ما دعا إليه فليس بمعجز الله في الأرض إذا أراد عقوبته، وليس له من دون الله أنصار يمنعونه من عذابه، أولئك في ذَهاب واضح عن الحق.", "isBasmala": false, "translation_en": "He who does not answer the caller to God will not escape on earth, and has no protectors besides Him. Those are in obvious error.", "translation_id": "Dan orang yang tidak menerima (seruan) orang yang menyeru kepada Allah maka dia tidak akan melepaskan diri dari azab Allah di muka bumi dan tidak ada baginya pelindung selain Allah. Mereka itu dalam kesesatan yang nyata\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 33, "text": "أَوَ لَمۡ یَرَوۡا۟ أَنَّ ٱللَّهَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَلَمۡ یَعۡیَ بِخَلۡقِهِنَّ بِقَـٰدِرٍ عَلَىٰۤ أَن یُحۡـِۧیَ ٱلۡمَوۡتَىٰۚ بَلَىٰۤۚ إِنَّهُۥ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٣٣", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "أغَفَلوا ولم يعلموا أنَّ الله الذي خلق السموات والأرض على غير مثال سبق، ولم يعجز عن خلقهن، قادر على إحياء الموتى الذين خلقهم أوّلا؟ بلى، ذلك أمر يسير على الله تعالى الذي لا يعجزه شيء، إنه على كل شيء قدير.", "isBasmala": false, "translation_en": "Do they not realize that God, who created the heavens and the earth, and was never tired by creating them, is Able to revive the dead? Yes indeed; He is Capable of everything.", "translation_id": "Dan apakah mereka tidak memperhatikan bahwa sesungguhnya Allah yang menciptakan langit dan bumi dan Dia tidak merasa payah karena menciptakannya, kuasa menghidupkan orang-orang mati? Ya (bahkan) sesungguhnya Dia Maha Kuasa atas segala sesuatu.", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 34, "text": "وَیَوۡمَ یُعۡرَضُ ٱلَّذِینَ كَفَرُوا۟ عَلَى ٱلنَّارِ أَلَیۡسَ هَـٰذَا بِٱلۡحَقِّۖ قَالُوا۟ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُوا۟ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ۝٣٤", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "ويوم القيامة يُعْرَض الذين كفروا على نار جهنم للعذاب فيقال لهم: أليس هذا العذاب بالحق؟ فيجيبون قائلين: بلى وربنا هو الحق، فيقال لهم: فذوقوا العذاب بما كنتم تجحدون عذاب النار وتنكرونه في الدنيا.", "isBasmala": false, "translation_en": "On the Day when those who disbelieved are presented to the Fire: \"Is this not real?\" They will say, \"Yes, indeed, by our Lord.\" He will say, \"Then taste the suffering for having disbelieved.\"", "translation_id": "Dan (ingatlah) hari (ketika) orang-orang kafir dihadapkan kepada neraka, (dikatakan kepada mereka): \"Bukankah (azab) ini benar?\" Mereka menjawab: \"Ya benar, demi Tuhan kami\". Allah berfirman \"Maka rasakanlah azab ini disebabkan kamu selalu ingkar\".", "manzil": 6, "manzil_display": ""}, {"sura": 46, "sura_name": "الأحقاف", "revelation": "Makkiyah", "aya": 35, "text": "فَٱصۡبِرۡ كَمَا صَبَرَ أُو۟لُوا۟ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ یَوۡمَ یَرَوۡنَ مَا یُوعَدُونَ لَمۡ یَلۡبَثُوۤا۟ إِلَّا سَاعَةࣰ مِّن نَّهَارِۭۚ بَلَـٰغࣱۚ فَهَلۡ یُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَـٰسِقُونَ ۝٣٥", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "فاصبر -أيها الرسول- على ما أصابك مِن أذى قومك المكذبين لك، كما صبر أولو العزم من الرسل من قبلك- وهم، على المشهور: نوح وإبراهيم وموسى وعيسى وأنت منهم- ولا تستعجل لقومك العذاب؛ فحين يقع ويرونه كأنهم لم يمكثوا في الدنيا إلا ساعة من نهار، هذا بلاغ لهم ولغيرهم. ولا يُهْلَكُ بعذاب الله إلا القوم الخارجون عن أمره وطاعته.", "isBasmala": false, "translation_en": "So be patient, as the messengers with resolve were patient, and do not be hasty regarding them. On the Day when they witness what they are promised, it will seem as if they had lasted only for an hour of a day. A proclamation: Will any be destroyed except the sinful people?", "translation_id": "Maka bersabarlah kamu seperti orang-orang yang mempunyai keteguhan hati dari rasul-rasul telah bersabar dan janganlah kamu meminta disegerakan (azab) bagi mereka. Pada hari mereka melihat azab yang diancamkan kepada mereka (merasa) seolah-olah tidak tinggal (di dunia) melainkan sesaat pada siang hari. (Inilah) suatu pelajaran yang cukup, maka tidak dibinasakan melainkan kaum yang fasik.", "manzil": 6, "manzil_display": ""}], "507": [{"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 26, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 1, "text": "ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ أَضَلَّ أَعۡمَـٰلَهُمۡ ۝١", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "الذين جحدوا أن الله هو الإله الحق وحده لا شريك له، وصدوا الناس عن دينه، أَذْهَبَ الله أعمالهم، وأبطلها، وأشقاهم بسببها.", "isBasmala": false, "translation_en": "Those who disbelieve and repel from the path of God-He nullifies their works.", "translation_id": "Orang-orang yang kafir dan menghalangi (manusia) dari jalan Allah, Allah menyesatkan perbuatan-perbuatan mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 2, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَءَامَنُوا۟ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدࣲ وَهُوَ ٱلۡحَقُّ مِن رَّبِّهِمۡ كَفَّرَ عَنۡهُمۡ سَیِّـَٔاتِهِمۡ وَأَصۡلَحَ بَالَهُمۡ ۝٢", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "والذين صدَّقوا الله واتَّبَعوا شرعه وصدَّقوا بالكتاب الذي أنزل على محمد صلى الله عليه وسلم، وهو الحق الذي لا شك فيه من ربهم، عفا عنهم وستر عليهم ما عملوا من السيئات، فلم يعاقبهم عليها، وأصلح شأنهم في الدينا والآخرة.", "isBasmala": false, "translation_en": "While those who believe, and work righteousness, and believe in what was sent down to Muhammad-and it is the truth from their Lord-He remits their sins, and relieves their concerns.", "translation_id": "Dan orang-orang mukmin dan beramal soleh serta beriman kepada apa yang diturunkan kepada Muhammad dan itulah yang haq dari Tuhan mereka, Allah menghapuskan kesalahan-kesalahan mereka dan memperbaiki keadaan mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 3, "text": "ذَ ٰلِكَ بِأَنَّ ٱلَّذِینَ كَفَرُوا۟ ٱتَّبَعُوا۟ ٱلۡبَـٰطِلَ وَأَنَّ ٱلَّذِینَ ءَامَنُوا۟ ٱتَّبَعُوا۟ ٱلۡحَقَّ مِن رَّبِّهِمۡۚ كَذَ ٰلِكَ یَضۡرِبُ ٱللَّهُ لِلنَّاسِ أَمۡثَـٰلَهُمۡ ۝٣", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "ذلك الإضلال والهدى سببه أن الذين كفروا اتَّبَعوا الشيطان فأطاعوه، وأن الذين آمنوا اتَّبَعوا الرسول صلى الله عليه وسلم وما جاء به من النور والهدى، كما بيَّن الله تعالى فِعْلَه بالفريقين أهل الكفر وأهل الإيمان بما يستحقان يضرب سبحانه للناس أمثالهم، فيلحق بكل قوم من الأمثال والأشكال ما يناسبه.", "isBasmala": false, "translation_en": "That is because those who disbelieve follow falsehoods, while those who believe follow the truth from their Lord. God thus cites for the people their examples.", "translation_id": "Yang demikian adalah karena sesungguhnya orang-orang kafir mengikuti yang bathil dan sesungguhnya orang-orang mukmin mengikuti yang haq dari Tuhan mereka. Demikianlah Allah membuat untuk manusia perbandingan-perbandingan bagi mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 4, "text": "فَإِذَا لَقِیتُمُ ٱلَّذِینَ كَفَرُوا۟ فَضَرۡبَ ٱلرِّقَابِ حَتَّىٰۤ إِذَاۤ أَثۡخَنتُمُوهُمۡ فَشُدُّوا۟ ٱلۡوَثَاقَ فَإِمَّا مَنَّۢا بَعۡدُ وَإِمَّا فِدَاۤءً حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ ذَ ٰلِكَۖ وَلَوۡ یَشَاۤءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَـٰكِن لِّیَبۡلُوَا۟ بَعۡضَكُم بِبَعۡضࣲۗ وَٱلَّذِینَ قُتِلُوا۟ فِی سَبِیلِ ٱللَّهِ فَلَن یُضِلَّ أَعۡمَـٰلَهُمۡ ۝٤", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "فإذا لقيتم- أيها المؤمنون- الذين كفروا في ساحات الحرب فاصدقوهم القتال، واضربوا منهم الأعناق، حتى إذا أضعفتموهم بكثرة القتل، وكسرتم شوكتهم، فأحكموا قيد الأسرى: فإما أن تَمُنُّوا عليهم بفك أسرهم بغير عوض، وإما أن يفادوا أنفسهم بالمال أو غيره، وإما أن يُسْتَرَقُّوا أو يُقْتَلوا، واستمِرُّوا على ذلك حتى تنتهي الحرب. ذلك الحكم المذكور في ابتلاء المؤمنين بالكافرين ومداولة الأيام بينهم، ولو يشاء الله لانتصر للمؤمنين من الكافرين بغير قتال، ولكن جعل عقوبتهم على أيديكم، فشرع الجهاد؛ ليختبركم بهم، ولينصر بكم دينه. والذين قُتلوا في سبيل الله من المؤمنين فلن يُبْطِل الله ثواب أعمالهم، سيوفقهم أيام حياتهم في الدنيا إلى طاعته ومرضاته، ويُصْلح حالهم وأمورهم وثوابهم في الدنيا والآخرة، ويدخلهم الجنة، عرَّفهم بها ونعتها لهم، ووفقهم للقيام بما أمرهم به -ومن جملته الشهادة في سبيله-، ثم عرَّفهم إذا دخلوا الجنة منازلهم بها.", "isBasmala": false, "translation_en": "When you encounter those who disbelieve, strike at their necks. Then, when you have routed them, bind them firmly. Then, either release them by grace, or by ransom, until war lays down its burdens. Had God willed, He could have defeated them Himself, but He thus tests some of you by means of others. As for those who are killed in the way of God, He will not let their deeds go to waste.", "translation_id": "Apabila kamu bertemu dengan orang-orang kafir (di medan perang) maka pancunglah batang leher mereka. Sehingga apabila kamu telah mengalahkan mereka maka tawanlah mereka dan sesudah itu kamu boleh membebaskan mereka atau menerima tebusan sampai perang berakhir. Demikianlah apabila Allah menghendaki niscaya Allah akan membinasakan mereka tetapi Allah hendak menguji sebahagian kamu dengan sebahagian yang lain. Dan orang-orang yang syahid pada jalan Allah, Allah tidak akan menyia-nyiakan amal mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 5, "text": "سَیَهۡدِیهِمۡ وَیُصۡلِحُ بَالَهُمۡ ۝٥", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "فإذا لقيتم- أيها المؤمنون- الذين كفروا في ساحات الحرب فاصدقوهم القتال، واضربوا منهم الأعناق، حتى إذا أضعفتموهم بكثرة القتل، وكسرتم شوكتهم، فأحكموا قيد الأسرى: فإما أن تَمُنُّوا عليهم بفك أسرهم بغير عوض، وإما أن يفادوا أنفسهم بالمال أو غيره، وإما أن يُسْتَرَقُّوا أو يُقْتَلوا، واستمِرُّوا على ذلك حتى تنتهي الحرب. ذلك الحكم المذكور في ابتلاء المؤمنين بالكافرين ومداولة الأيام بينهم، ولو يشاء الله لانتصر للمؤمنين من الكافرين بغير قتال، ولكن جعل عقوبتهم على أيديكم، فشرع الجهاد؛ ليختبركم بهم، ولينصر بكم دينه. والذين قُتلوا في سبيل الله من المؤمنين فلن يُبْطِل الله ثواب أعمالهم، سيوفقهم أيام حياتهم في الدنيا إلى طاعته ومرضاته، ويُصْلح حالهم وأمورهم وثوابهم في الدنيا والآخرة، ويدخلهم الجنة، عرَّفهم بها ونعتها لهم، ووفقهم للقيام بما أمرهم به -ومن جملته الشهادة في سبيله-، ثم عرَّفهم إذا دخلوا الجنة منازلهم بها.", "isBasmala": false, "translation_en": "He will guide them, and will improve their state of mind.", "translation_id": "Allah akan memberi pimpinan kepada mereka dan memperbaiki keadaan mereka,", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 6, "text": "وَیُدۡخِلُهُمُ ٱلۡجَنَّةَ عَرَّفَهَا لَهُمۡ ۝٦", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "فإذا لقيتم- أيها المؤمنون- الذين كفروا في ساحات الحرب فاصدقوهم القتال، واضربوا منهم الأعناق، حتى إذا أضعفتموهم بكثرة القتل، وكسرتم شوكتهم، فأحكموا قيد الأسرى: فإما أن تَمُنُّوا عليهم بفك أسرهم بغير عوض، وإما أن يفادوا أنفسهم بالمال أو غيره، وإما أن يُسْتَرَقُّوا أو يُقْتَلوا، واستمِرُّوا على ذلك حتى تنتهي الحرب. ذلك الحكم المذكور في ابتلاء المؤمنين بالكافرين ومداولة الأيام بينهم، ولو يشاء الله لانتصر للمؤمنين من الكافرين بغير قتال، ولكن جعل عقوبتهم على أيديكم، فشرع الجهاد؛ ليختبركم بهم، ولينصر بكم دينه. والذين قُتلوا في سبيل الله من المؤمنين فلن يُبْطِل الله ثواب أعمالهم، سيوفقهم أيام حياتهم في الدنيا إلى طاعته ومرضاته، ويُصْلح حالهم وأمورهم وثوابهم في الدنيا والآخرة، ويدخلهم الجنة، عرَّفهم بها ونعتها لهم، ووفقهم للقيام بما أمرهم به -ومن جملته الشهادة في سبيله-، ثم عرَّفهم إذا دخلوا الجنة منازلهم بها.", "isBasmala": false, "translation_en": "And will admit them into Paradise, which He has identified for them.", "translation_id": "dan memasukkan mereka ke dalam jannah yang telah diperkenankan-Nya kepada mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 7, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن تَنصُرُوا۟ ٱللَّهَ یَنصُرۡكُمۡ وَیُثَبِّتۡ أَقۡدَامَكُمۡ ۝٧", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إن تنصروا دين الله بالجهاد في سبيله، والحكم بكتابه، وامتثال أوامره، واجتناب نواهيه، ينصركم الله على أعدائكم، ويثبت أقدامكم عند القتال.", "isBasmala": false, "translation_en": "O you who believe! If you support God, He will support you, and will strengthen your foothold.", "translation_id": "Hai orang-orang mukmin, jika kamu menolong (agama) Allah, niscaya Dia akan menolongmu dan meneguhkan kedudukanmu.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 8, "text": "وَٱلَّذِینَ كَفَرُوا۟ فَتَعۡسࣰا لَّهُمۡ وَأَضَلَّ أَعۡمَـٰلَهُمۡ ۝٨", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "والذين كفروا فهلاكًا لهم، وأذهب الله ثواب أعمالهم؛ ذلك بسبب أنهم كرهوا كتاب الله المنزل على نبيه محمد صلى الله عليه وسلم، فكذبوا به، فأبطل أعمالهم؛ لأنها كانت في طاعة الشيطان.", "isBasmala": false, "translation_en": "But as for those who disbelieve, for them is perdition, and He will waste their deeds.", "translation_id": "Dan orang-orang yang kafir, maka kecelakaanlah bagi mereka dan Allah menyesatkan amal-amal mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 9, "text": "ذَ ٰلِكَ بِأَنَّهُمۡ كَرِهُوا۟ مَاۤ أَنزَلَ ٱللَّهُ فَأَحۡبَطَ أَعۡمَـٰلَهُمۡ ۝٩", "juz": 26, "hizb": "(*¼ ح 51*)", "tafsir": "والذين كفروا فهلاكًا لهم، وأذهب الله ثواب أعمالهم؛ ذلك بسبب أنهم كرهوا كتاب الله المنزل على نبيه محمد صلى الله عليه وسلم، فكذبوا به، فأبطل أعمالهم؛ لأنها كانت في طاعة الشيطان.", "isBasmala": false, "translation_en": "That is because they hated what God revealed, so He nullified their deeds.", "translation_id": "Yang demikian itu adalah karena Sesungguhnya mereka benci kepada apa yang diturunkan Allah (Al Quran) lalu Allah menghapuskan (pahala-pahala) amal-amal mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 10, "text": "۞ أَفَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡۖ دَمَّرَ ٱللَّهُ عَلَیۡهِمۡۖ وَلِلۡكَـٰفِرِینَ أَمۡثَـٰلُهَا ۝١٠", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "أفلم يَسِرْ هؤلاء الكفار في أرض الله معتبرين بما حلَّ بالأمم المكذبة قبلهم من العقاب؟ دمَّر الله عليهم ديارهم، وللكافرين أمثال تلك العاقبة التي حلت بتلك الأمم.", "isBasmala": false, "translation_en": "Have they not journeyed through the earth and seen the consequences for those before them? God poured destruction upon them, and for the unbelievers is something comparable.", "translation_id": "Maka apakah mereka tidak mengadakan perjalanan di muka bumi sehingga mereka dapat memperhatikan bagaimana kesudahan orang-orang sebelum mereka; Allah telah menimpakan kebinasaan atas mereka dan orang-orang kafir akan menerima (akibat-akibat) seperti itu.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 11, "text": "ذَ ٰلِكَ بِأَنَّ ٱللَّهَ مَوۡلَى ٱلَّذِینَ ءَامَنُوا۟ وَأَنَّ ٱلۡكَـٰفِرِینَ لَا مَوۡلَىٰ لَهُمۡ ۝١١", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "ذلك الذي فعلناه بالفريقين فريق الإيمان وفريق الكفر؛ بسبب أن الله وليُّ المؤمنين ونصيرهم، وأن الكافرين لا وليَّ لهم ولا نصير.", "isBasmala": false, "translation_en": "That is because God is the Master of those who believe, while the disbelievers have no master.", "translation_id": "Yang demikian itu karena sesungguhnya Allah adalah pelindung orang-orang yang beriman dan karena sesungguhnya orang-orang kafir itu tidak mempunyai pelindung.", "manzil": 6, "manzil_display": ""}], "508": [{"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 12, "text": "إِنَّ ٱللَّهَ یُدۡخِلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ وَٱلَّذِینَ كَفَرُوا۟ یَتَمَتَّعُونَ وَیَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَـٰمُ وَٱلنَّارُ مَثۡوࣰى لَّهُمۡ ۝١٢", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "إن الله يدخل الذين آمنوا بالله ورسوله وعملوا الصالحات جنات تجري من تحت أشجارها الأنهار تَكْرِمَةً لهم، ومثل الذين كفروا في أكلهم وتمتعهم بالدنيا، كمثل الأنعام من البهائم التي لا همَّ لها إلا في الاعتلاف دون غيره، ونار جهنم مسكن لهم ومأوى.", "isBasmala": false, "translation_en": "God will admit those who believe and do good deeds into gardens beneath which rivers flow. As for those who disbelieve, they enjoy themselves, and eat as cattle eat, and the Fire will be their dwelling.", "translation_id": "Sesungguhnya Allah memasukkan orang-orang mukmin dan beramal saleh ke dalam jannah yang mengalir di bawahnya sungai-sungai. Dan orang-orang kafir bersenang-senang (di dunia) dan mereka makan seperti makannya binatang. Dan jahannam adalah tempat tinggal mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 13, "text": "وَكَأَیِّن مِّن قَرۡیَةٍ هِیَ أَشَدُّ قُوَّةࣰ مِّن قَرۡیَتِكَ ٱلَّتِیۤ أَخۡرَجَتۡكَ أَهۡلَكۡنَـٰهُمۡ فَلَا نَاصِرَ لَهُمۡ ۝١٣", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "وكثير من أهل قرى كانوا أشد بأسًا من أهل قريتك -أيها الرسول، وهي \"مكة\"- التي أخرجتك، دمَّرناهم بأنواع من العذاب، فلم يكن لهم نصير ينصرهم من عذاب الله.", "isBasmala": false, "translation_en": "How many a town was more powerful than your town which evicted you? We destroyed them, and there was no helper for them.", "translation_id": "Dan betapa banyaknya negeri yang (penduduknya) lebih kuat dari pada (penduduk) negerimu (Muhammad) yang telah mengusirmu itu. Kami telah membinasakan mereka, maka tidak ada seorang penolongpun bagi mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 14, "text": "أَفَمَن كَانَ عَلَىٰ بَیِّنَةࣲ مِّن رَّبِّهِۦ كَمَن زُیِّنَ لَهُۥ سُوۤءُ عَمَلِهِۦ وَٱتَّبَعُوۤا۟ أَهۡوَاۤءَهُم ۝١٤", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "أفمن كان على برهان واضح من ربه والعلم بوحدانيته، كمن حسَّن له الشيطان قبيح عمله، واتبع ما دعته إليه نفسه من معصية الله وعبادة غيره مِن غير حجة ولا برهان؟ لا يستوون.", "isBasmala": false, "translation_en": "Is he who stands upon evidence from his Lord, like someone whose evil deed is made to appear good to him? And they follow their own desires?", "translation_id": "Maka apakah orang yang berpegang pada keterangan yang datang dari Rabbnya sama dengan orang yang (shaitan) menjadikan dia memandang baik perbuatannya yang buruk itu dan mengikuti hawa nafsunya?", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 15, "text": "مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِی وُعِدَ ٱلۡمُتَّقُونَۖ فِیهَاۤ أَنۡهَـٰرࣱ مِّن مَّاۤءٍ غَیۡرِ ءَاسِنࣲ وَأَنۡهَـٰرࣱ مِّن لَّبَنࣲ لَّمۡ یَتَغَیَّرۡ طَعۡمُهُۥ وَأَنۡهَـٰرࣱ مِّنۡ خَمۡرࣲ لَّذَّةࣲ لِّلشَّـٰرِبِینَ وَأَنۡهَـٰرࣱ مِّنۡ عَسَلࣲ مُّصَفࣰّىۖ وَلَهُمۡ فِیهَا مِن كُلِّ ٱلثَّمَرَ ٰتِ وَمَغۡفِرَةࣱ مِّن رَّبِّهِمۡۖ كَمَنۡ هُوَ خَـٰلِدࣱ فِی ٱلنَّارِ وَسُقُوا۟ مَاۤءً حَمِیمࣰا فَقَطَّعَ أَمۡعَاۤءَهُمۡ ۝١٥", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "صفة الجنة التي وعدها الله المتقين: فيها أنهارٌ عظيمة من ماء غير متغيِّر، وأنهار من لبن لم يتغيَّر طعمه، وأنهار من خمر يتلذذ به الشاربون، وأنهار من عسل قد صُفِّي من القذى، ولهؤلاء المتقين في هذه الجنة جميع الثمرات من مختلف الفواكه وغيرها، وأعظم من ذلك السَّتر والتجاوزُ عن ذنوبهم، هل مَن هو في هذه الجنة كمَن هو ماكث في النار لا يخرج منها، وسُقوا ماء تناهى في شدة حره فقطَّع أمعاءهم؟", "isBasmala": false, "translation_en": "The likeness of the Garden promised to the righteous: in it are rivers of pure water, and rivers of milk forever fresh, and rivers of wine delightful to the drinkers, and rivers of strained honey. And therein they will have of every fruit, and forgiveness from their Lord. Like one abiding in the Fire forever, and are given to drink boiling water, that cuts-up their bowels?", "translation_id": "(Apakah) perumpamaan (penghuni) jannah yang dijanjikan kepada orang-orang yang bertakwa yang di dalamnya ada sungai-sungai dari air yang tiada berubah rasa dan baunya, sungai-sungai dari air susu yang tidak berubah rasanya, sungai-sungai dari khamar yang lezat rasanya bagi peminumnya dan sungai-sungai dari madu yang disaring; dan mereka memperoleh di dalamnya segala macam buah-buahan dan ampunan dari Rabb mereka, sama dengan orang yang kekal dalam jahannam dan diberi minuman dengan air yang mendidih sehingga memotong ususnya?", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 16, "text": "وَمِنۡهُم مَّن یَسۡتَمِعُ إِلَیۡكَ حَتَّىٰۤ إِذَا خَرَجُوا۟ مِنۡ عِندِكَ قَالُوا۟ لِلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ مَاذَا قَالَ ءَانِفًاۚ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَٱتَّبَعُوۤا۟ أَهۡوَاۤءَهُمۡ ۝١٦", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "ومن هؤلاء المنافقين مَن يستمع إليك -أيها النبي- بغير فهم؛ تهاونًا منهم واستخفافًا، حتى إذا انصرفوا من مجلسك قالوا لمن حضروا مجلسك من أهل العلم بكتاب الله على سبيل الاستهزاء: ماذا قال محمد الآن؟ أولئك الذين ختم الله على قلوبهم، فلا تفقه الحق ولا تهتدي إليه، واتبعوا أهواءهم في الكفر والضلال.", "isBasmala": false, "translation_en": "Among them are those who listen to you, but when they leave your presence, they say to those given knowledge, \"What did he say just now?\" Those are they whose hearts God has sealed, and they follow their own desires.", "translation_id": "Dan di antara mereka ada orang yang mendengarkan perkataanmu sehingga apabila mereka keluar dari sisimu orang-orang berkata kepada orang yang telah diberi ilmu pengetahuan (sahabat-sahabat Nabi): \"Apakah yang dikatakannya tadi?\" Mereka itulah orang-orang yang dikunci mati hati mereka oleh Allah dan mengikuti hawa nafsu mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 17, "text": "وَٱلَّذِینَ ٱهۡتَدَوۡا۟ زَادَهُمۡ هُدࣰى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ ۝١٧", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "والذين اهتدوا لاتِّباع الحق زادهم الله هدى، فقوي بذلك هداهم، ووفقهم للتقوى، ويسَّرها لهم.", "isBasmala": false, "translation_en": "As for those who are guided, He increases them in guidance, and He has granted them their righteousness.", "translation_id": "Dan orang-orang yang mau menerima petunjuk, Allah menambah petunjuk kepada mereka dan memberikan balasan ketakwaannya.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 18, "text": "فَهَلۡ یَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِیَهُم بَغۡتَةࣰۖ فَقَدۡ جَاۤءَ أَشۡرَاطُهَاۚ فَأَنَّىٰ لَهُمۡ إِذَا جَاۤءَتۡهُمۡ ذِكۡرَىٰهُمۡ ۝١٨", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "ما ينتظر هؤلاء المكذبون إلا الساعة التي وُعدوا بها أن تجيئهم فجأةً، فقد ظهرت علاماتها ولم ينتفعوا بذلك، فمن أين لهم التذكر إذا جاءتهم الساعة؟", "isBasmala": false, "translation_en": "Are they just waiting until the Hour comes to them suddenly? Its tokens have already come. But how will they be reminded when it has come to them?", "translation_id": "Maka tidaklah yang mereka tunggu-tunggu melainkan hari kiamat (yaitu) kedatangannya kepada mereka dengan tiba-tiba, karena sesungguhnya telah datang tanda-tandanya. Maka apakah faedahnya bagi mereka kesadaran mereka itu apabila Kiamat sudah datang?", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 19, "text": "فَٱعۡلَمۡ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِۗ وَٱللَّهُ یَعۡلَمُ مُتَقَلَّبَكُمۡ وَمَثۡوَىٰكُمۡ ۝١٩", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "فاعلم -أيها النبي- أنه لا معبود بحق إلا الله، واستغفر لذنبك، واستغفر للمؤمنين والمؤمنات. والله يعلم تصرفكم في يقظتكم نهارًا، ومستقركم في نومكم ليلا.", "isBasmala": false, "translation_en": "Know that there is no god but God, and ask forgiveness for your sin, and for the believing men and believing women. God knows your movements, and your resting-place.", "translation_id": "Maka ketahuilah, bahwa sesungguhnya tidak ada Ilah (sesembahan, tuhan) selain Allah dan mohonlah ampunan bagi dosamu dan bagi (dosa) orang-orang mukmin, laki-laki dan perempuan. Dan Allah mengetahui tempat kamu berusaha dan tempat kamu tinggal.", "manzil": 6, "manzil_display": ""}], "509": [{"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 20, "text": "وَیَقُولُ ٱلَّذِینَ ءَامَنُوا۟ لَوۡلَا نُزِّلَتۡ سُورَةࣱۖ فَإِذَاۤ أُنزِلَتۡ سُورَةࣱ مُّحۡكَمَةࣱ وَذُكِرَ فِیهَا ٱلۡقِتَالُ رَأَیۡتَ ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ یَنظُرُونَ إِلَیۡكَ نَظَرَ ٱلۡمَغۡشِیِّ عَلَیۡهِ مِنَ ٱلۡمَوۡتِۖ فَأَوۡلَىٰ لَهُمۡ ۝٢٠", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "ويقول الذين آمنوا بالله ورسوله: هلا نُزِّلت سورة من الله تأمرنا بجهاد الكفار، فإذا أُنزِلت سورة محكمة بالبيان والفرائض وذُكر فيها الجهاد، رأيت الذين في قلوبهم شك في دين الله ونفاق ينظرون إليك -أيها النبي- نظر الذي قد غُشِيَ عليه خوفَ الموت، فأولى لهؤلاء الذين في قلوبهم مرض أن يطيعوا الله، وأن يقولوا قولا موافقًا للشرع. فإذا وجب القتال وجاء أمر الله بِفَرْضه كره هؤلاء المنافقون ذلك، فلو صدقوا الله في الإيمان والعمل لكان خيرًا لهم من المعصية والمخالفة.", "isBasmala": false, "translation_en": "Those who believe say, \"If only a chapter is sent down.\" Yet when a decisive chapter is sent down, and fighting is mentioned in it, you see those in whose hearts is sickness looking at you with the look of someone fainting at death. So woe to them!", "translation_id": "Dan orang-orang yang beriman berkata: \"Mengapa tiada diturunkan suatu surat?\" Maka apabila diturunkan suatu surat yang jelas maksudnya dan disebutkan di dalamnya (perintah) perang, kamu lihat orang-orang yang ada penyakit di dalam hatinya memandang kepadamu seperti pandangan orang yang pingsan karena takut mati, dan kecelakaanlah bagi mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 21, "text": "طَاعَةࣱ وَقَوۡلࣱ مَّعۡرُوفࣱۚ فَإِذَا عَزَمَ ٱلۡأَمۡرُ فَلَوۡ صَدَقُوا۟ ٱللَّهَ لَكَانَ خَیۡرࣰا لَّهُمۡ ۝٢١", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "ويقول الذين آمنوا بالله ورسوله: هلا نُزِّلت سورة من الله تأمرنا بجهاد الكفار، فإذا أُنزِلت سورة محكمة بالبيان والفرائض وذُكر فيها الجهاد، رأيت الذين في قلوبهم شك في دين الله ونفاق ينظرون إليك -أيها النبي- نظر الذي قد غُشِيَ عليه خوفَ الموت، فأولى لهؤلاء الذين في قلوبهم مرض أن يطيعوا الله، وأن يقولوا قولا موافقًا للشرع. فإذا وجب القتال وجاء أمر الله بِفَرْضه كره هؤلاء المنافقون ذلك، فلو صدقوا الله في الإيمان والعمل لكان خيرًا لهم من المعصية والمخالفة.", "isBasmala": false, "translation_en": "Obedience and upright speech. Then, when the matter is settled, being true to God would have been better for them.", "translation_id": "Taat dan mengucapkan perkataan yang baik (adalah lebih baik bagi mereka). Apabila telah tetap perintah perang (mereka tidak menyukainya). Tetapi jikalau mereka benar (imannya) terhadap Allah, niscaya yang demikian itu lebih baik bagi mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 22, "text": "فَهَلۡ عَسَیۡتُمۡ إِن تَوَلَّیۡتُمۡ أَن تُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ وَتُقَطِّعُوۤا۟ أَرۡحَامَكُمۡ ۝٢٢", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "فلعلكم إن أعرضتم عن كتاب الله وسنة نبيه محمد صلى الله عليه وسلم أن تعصوا الله في الأرض، فتكفروا به وتسفكوا الدماء وتُقَطِّعوا أرحامكم.", "isBasmala": false, "translation_en": "If you turn away, you are likely to make mischief on earth, and sever your family ties.", "translation_id": "Maka apakah kiranya jika kamu berkuasa kamu akan membuat kerusakan di muka bumi dan memutuskan hubungan kekeluargaan?", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 23, "text": "أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰۤ أَبۡصَـٰرَهُمۡ ۝٢٣", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "أولئك الذين أبعدهم الله من رحمته، فجعلهم لا يسمعون ما ينفعهم ولا يبصرونه، فلم يتبينوا حجج الله مع كثرتها.", "isBasmala": false, "translation_en": "Those are they whom God has cursed. He made them deaf, and blinded their sight.", "translation_id": "Mereka itulah orang-orang yang dilaknati Allah dan ditulikan-Nya telinga mereka dan dibutakan-Nya penglihatan mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 24, "text": "أَفَلَا یَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَاۤ ۝٢٤", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "أفلا يتدبر هؤلاء المنافقون مواعظ القرآن ويتفكرون في حججه؟ بل هذه القلوب مغلَقة لا يصل إليها شيء من هذا القرآن، فلا تتدبر مواعظ الله وعبره.", "isBasmala": false, "translation_en": "Will they not ponder the Quran? Or are there locks upon their hearts?", "translation_id": "Maka apakah mereka tidak memperhatikan Al Quran ataukah hati mereka terkunci?", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 25, "text": "إِنَّ ٱلَّذِینَ ٱرۡتَدُّوا۟ عَلَىٰۤ أَدۡبَـٰرِهِم مِّنۢ بَعۡدِ مَا تَبَیَّنَ لَهُمُ ٱلۡهُدَى ٱلشَّیۡطَـٰنُ سَوَّلَ لَهُمۡ وَأَمۡلَىٰ لَهُمۡ ۝٢٥", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "إن الذين ارتدُّوا عن الهدى والإيمان، ورجعوا على أعقابهم كفارًا بالله من بعد ما وَضَح لهم الحق، الشيطان زيَّن لهم خطاياهم، ومدَّ لهم في الأمل.", "isBasmala": false, "translation_en": "Those who reverted after the guidance became clear to them-Satan has enticed them, and has given them latitude.", "translation_id": "Sesungguhnya orang-orang yang kembali ke belakang (kepada kekafiran) sesudah petunjuk itu jelas bagi mereka, syaitan telah menjadikan mereka mudah (berbuat dosa) dan memanjangkan angan-angan mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 26, "text": "ذَ ٰلِكَ بِأَنَّهُمۡ قَالُوا۟ لِلَّذِینَ كَرِهُوا۟ مَا نَزَّلَ ٱللَّهُ سَنُطِیعُكُمۡ فِی بَعۡضِ ٱلۡأَمۡرِۖ وَٱللَّهُ یَعۡلَمُ إِسۡرَارَهُمۡ ۝٢٦", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "ذلك الإمداد لهم حتى يتمادوا في الكفر؛ بسبب أنهم قالوا لليهود الذين كرهوا ما نزل الله: سنطيعكم في بعض الأمر الذي هو خلاف لأمر الله وأمر رسوله، والله تعالى يعلم ما يخفيه هؤلاء ويسرونه، فليحذر المسلم من طاعة غير الله فيما يخالف أمر الله سبحانه، وأمر رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "That is because they said to those who hated what God has revealed, \"We will obey you in certain matters.\" But God knows their secret thoughts.", "translation_id": "Yang demikian itu karena sesungguhnya mereka (orang-orang munafik) itu berkata kepada orang-orang yang benci kepada apa yang diturunkan Allah (orang-orang Yahudi): \"Kami akan mematuhi kamu dalam beberapa urusan\", sedang Allah mengetahui rahasia mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 27, "text": "فَكَیۡفَ إِذَا تَوَفَّتۡهُمُ ٱلۡمَلَـٰۤىِٕكَةُ یَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَـٰرَهُمۡ ۝٢٧", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "فكيف حالهم إذا قبضت الملائكة أرواحهم وهم يضربون وجوههم وأدبارهم؟", "isBasmala": false, "translation_en": "How about when the angels take them at death, beating their faces and their backs?", "translation_id": "Bagaimanakah (keadaan mereka) apabila malaikat mencabut nyawa mereka seraya memukul-mukul muka mereka dan punggung mereka?", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 28, "text": "ذَ ٰلِكَ بِأَنَّهُمُ ٱتَّبَعُوا۟ مَاۤ أَسۡخَطَ ٱللَّهَ وَكَرِهُوا۟ رِضۡوَ ٰنَهُۥ فَأَحۡبَطَ أَعۡمَـٰلَهُمۡ ۝٢٨", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "ذلك العذاب الذي استحقوه ونالوه؛ بسبب أنهم اتبعوا ما أسخط الله عليهم من طاعة الشيطان، وكرهوا ما يرضيه عنهم من العمل الصالح، ومنه قتال الكفار بعدما افترضه عليهم، فأبطل الله ثواب أعمالهم من صدقة وصلة رحم وغير ذلك.", "isBasmala": false, "translation_en": "That is because they pursued what displeases God, and they disliked His approval, so He nullified their works.", "translation_id": "Yang demikian itu adalah karena sesungguhnya mereka mengikuti apa yang menimbulkan kemurkaan Allah dan karena mereka membenci keridhaan-Nya, sebab itu Allah menghapus (pahala) amal-amal mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 29, "text": "أَمۡ حَسِبَ ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضٌ أَن لَّن یُخۡرِجَ ٱللَّهُ أَضۡغَـٰنَهُمۡ ۝٢٩", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "بل أظنَّ المنافقون أن الله لن يُخْرِج ما في قلوبهم من الحسد والحقد للإسلام وأهله؟ بلى فإن الله يميز الصادق من الكاذب.", "isBasmala": false, "translation_en": "Do those in whose hearts is sickness think that God will not expose their malice?", "translation_id": "Atau apakah orang-orang yang ada penyakit dalam hatinya mengira bahwa Allah tidak akan menampakkan kedengkian mereka?", "manzil": 6, "manzil_display": ""}], "510": [{"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 30, "text": "وَلَوۡ نَشَاۤءُ لَأَرَیۡنَـٰكَهُمۡ فَلَعَرَفۡتَهُم بِسِیمَـٰهُمۡۚ وَلَتَعۡرِفَنَّهُمۡ فِی لَحۡنِ ٱلۡقَوۡلِۚ وَٱللَّهُ یَعۡلَمُ أَعۡمَـٰلَكُمۡ ۝٣٠", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "ولو نشاء -أيها النبي- لأريناك أشخاصهم، فلعرفتهم بعلامات ظاهرة فيهم، ولتعرفنَّهم فيما يبدو من كلامهم الدال على مقاصدهم. والله تعالى لا تخفى عليه أعمال مَن أطاعه ولا أعمال من عصاه، وسيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "Had We willed, We could have shown them to you, and you would have recognized them by their marks. Yet you will recognize them by their tone of speech. And God knows your actions.", "translation_id": "Dan kalau Kami kehendaki, niscaya Kami tunjukkan mereka kepadamu sehingga kamu benar-benar dapat mengenal mereka dengan tanda-tandanya. Dan kamu benar-benar akan mengenal mereka dari kiasan-kiasan perkataan mereka dan Allah mengetahui perbuatan-perbuatan kamu.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 31, "text": "وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَـٰهِدِینَ مِنكُمۡ وَٱلصَّـٰبِرِینَ وَنَبۡلُوَا۟ أَخۡبَارَكُمۡ ۝٣١", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "ولنختبرنكم- أيها المؤمنون- بالقتال والجهاد لأعداء الله حتى يظهر ما علمه سبحانه في الأزل؛ لنميز أهل الجهاد منكم والصبر على قتال أعداء الله، ونختبر أقوالكم وأفعالكم، فيظهر الصادق منكم من الكاذب.", "isBasmala": false, "translation_en": "We will certainly test you, until We know those among you who strive, and those who are steadfast, and We will test your reactions.", "translation_id": "Dan sesungguhnya Kami benar-benar akan menguji kamu agar Kami mengetahui orang-orang yang berjihad dan bersabar di antara kamu, dan agar Kami menyatakan (baik buruknya) hal ihwalmu.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 32, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ وَشَاۤقُّوا۟ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَیَّنَ لَهُمُ ٱلۡهُدَىٰ لَن یَضُرُّوا۟ ٱللَّهَ شَیۡـࣰٔا وَسَیُحۡبِطُ أَعۡمَـٰلَهُمۡ ۝٣٢", "juz": 26, "hizb": "(*½ ح 51*)", "tafsir": "إن الذين جحدوا أن الله هو الإله الحق وحده لا شريك له، وصدوا الناس عن دينه، وخالفوا رسول الله صلى الله عليه وسلم، فحاربوه من بعد ما جاءتهم الحجج والآيات أنه نبي من عند الله، لن يضروا دين الله شيئًا، وسيُبْطِل ثواب أعمالهم التي عملوها في الدنيا؛ لأنهم لم يريدوا بها وجه الله تعالى.", "isBasmala": false, "translation_en": "Those who disbelieve, and hinder from the path of God, and oppose the Messenger after guidance has become clear to them-they will not hurt God in the least, but He will nullify their deeds.", "translation_id": "Sesungguhnya orang-orang kafir dan (yang) menghalangi manusia dari jalan Allah serta memusuhi Rasul setelah petunjuk itu jelas bagi mereka, mereka tidak dapat memberi mudharat kepada Allah sedikitpun. Dan Allah akan menghapuskan (pahala) amal-amal mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 33, "text": "۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ أَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَ وَلَا تُبۡطِلُوۤا۟ أَعۡمَـٰلَكُمۡ ۝٣٣", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه أطيعوا الله وأطيعوا الرسول في أمرهما ونهيهما، ولا تبطلوا ثواب أعمالكم بالكفر والمعاصي.", "isBasmala": false, "translation_en": "O you who believe! obey God, and obey the Messenger, and do not let your deeds go to waste.", "translation_id": "Hai orang-orang yang beriman, taatilah Allah dan taatilah Rasul dan janganlah kamu merusakkan (pahala) amal-amalmu.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 34, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ ثُمَّ مَاتُوا۟ وَهُمۡ كُفَّارࣱ فَلَن یَغۡفِرَ ٱللَّهُ لَهُمۡ ۝٣٤", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "إن الذين جحدوا أن الله هو الإله الحق وحده لا شريك له وصدُّوا الناس عن دينه، ثم ماتوا على ذلك، فلن يغفر الله لهم، وسيعذبهم عقابًا لهم على كفرهم، ويفضحهم على رؤوس الأشهاد.", "isBasmala": false, "translation_en": "Those who disbelieve, and hinder from God's path, and then die as disbelievers-God will not forgive them.", "translation_id": "Sesungguhnya orang-orang kafir dan (yang) menghalangi manusia dari jalan Allah kemudian mereka mati dalam keadaan kafir, maka sekali-kali Allah tidak akan memberi ampun kepada mereka.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 35, "text": "فَلَا تَهِنُوا۟ وَتَدۡعُوۤا۟ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ وَٱللَّهُ مَعَكُمۡ وَلَن یَتِرَكُمۡ أَعۡمَـٰلَكُمۡ ۝٣٥", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "فلا تضعفوا -أيها المؤمنون بالله ورسوله- عن جهاد المشركين، وتجْبُنوا عن قتالهم، وتدعوهم إلى الصلح والمسالمة، وأنتم القاهرون لهم والعالون عليهم، والله تعالى معكم بنصره وتأييده. وفي ذلك بشارة عظيمة بالنصر والظَّفَر على الأعداء. ولن يُنْقصكم الله ثواب أعمالكم.", "isBasmala": false, "translation_en": "So do not waver and call for peace while you have the upper hand. God is with you, and He will not waste your efforts.", "translation_id": "Janganlah kamu lemah dan minta damai padahal kamulah yang di atas dan Allah pun bersamamu dan Dia sekali-kali tidak akan mengurangi pahala amal-amalmu.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 36, "text": "إِنَّمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَا لَعِبࣱ وَلَهۡوࣱۚ وَإِن تُؤۡمِنُوا۟ وَتَتَّقُوا۟ یُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا یَسۡـَٔلۡكُمۡ أَمۡوَ ٰلَكُمۡ ۝٣٦", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "إنما الحياة الدنيا لعب وغرور. وإن تؤمنوا بالله ورسوله، وتتقوا الله بأداء فرائضه واجتناب معاصيه، يؤتكم ثواب أعمالكم، ولا يسألْكم إخراج أموالكم جميعها في الزكاة، بل يسألكم إخراج بعضها. إن يسألكم أموالكم، فيُلِحَّ عليكم ويجهدكم، تبخلوا بها وتمنعوه إياها، ويظهر ما في قلوبكم من الحقد إذا طلب منكم ما تكرهون بذله.", "isBasmala": false, "translation_en": "The life of this word is nothing but play and pastime. But if you have faith and lead a righteous life, He will grant you your rewards, and He will not ask you for your possessions.", "translation_id": "Sesungguhnya kehidupan dunia hanyalah permainan dan senda gurau. Dan jika kamu beriman dan bertakwa, Allah akan memberikan pahala kepadamu dan Dia tidak akan meminta harta-hartamu.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 37, "text": "إِن یَسۡـَٔلۡكُمُوهَا فَیُحۡفِكُمۡ تَبۡخَلُوا۟ وَیُخۡرِجۡ أَضۡغَـٰنَكُمۡ ۝٣٧", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "إنما الحياة الدنيا لعب وغرور. وإن تؤمنوا بالله ورسوله، وتتقوا الله بأداء فرائضه واجتناب معاصيه، يؤتكم ثواب أعمالكم، ولا يسألْكم إخراج أموالكم جميعها في الزكاة، بل يسألكم إخراج بعضها. إن يسألكم أموالكم، فيُلِحَّ عليكم ويجهدكم، تبخلوا بها وتمنعوه إياها، ويظهر ما في قلوبكم من الحقد إذا طلب منكم ما تكرهون بذله.", "isBasmala": false, "translation_en": "Were He to ask you for it, and press you, you would become tightfisted, and He would expose your unwillingness.", "translation_id": "Jika Dia meminta harta kepadamu lalu mendesak kamu (supaya memberikan semuanya) niscaya kamu akan kikir dan Dia akan menampakkan kedengkianmu.", "manzil": 6, "manzil_display": ""}, {"sura": 47, "sura_name": "محمد", "revelation": "Madaniyah", "aya": 38, "text": "هَـٰۤأَنتُمۡ هَـٰۤؤُلَاۤءِ تُدۡعَوۡنَ لِتُنفِقُوا۟ فِی سَبِیلِ ٱللَّهِ فَمِنكُم مَّن یَبۡخَلُۖ وَمَن یَبۡخَلۡ فَإِنَّمَا یَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِیُّ وَأَنتُمُ ٱلۡفُقَرَاۤءُۚ وَإِن تَتَوَلَّوۡا۟ یَسۡتَبۡدِلۡ قَوۡمًا غَیۡرَكُمۡ ثُمَّ لَا یَكُونُوۤا۟ أَمۡثَـٰلَكُم ۝٣٨", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "ها أنتم -أيها المؤمنون- تُدْعَون إلى النفقة في جهاد أعداء الله ونصرة دينه، فمنكم مَن يَبْخَلُ بالنفقة في سبيل الله، ومَن يَبْخَلْ فإنما يبخل عن نفسه، والله تعالى هو الغنيُّ عنكم وأنتم الفقراء إليه، وإن تتولوا عن الإيمان بالله وامتثال أمره يهلكُّم، ويأت بقوم آخرين، ثم لا يكونوا أمثالكم في التولي عن أمر الله، بل يطيعونه ويطيعون رسوله، ويجاهدون في سبيله بأموالهم وأنفسهم.", "isBasmala": false, "translation_en": "Here you are, being called to spend in the cause of God. Among you are those who withhold; but whoever withholds is withholding against his own soul. God is the Rich, while you are the needy. And if you turn away, He will replace you with another people, and they will not be like you.", "translation_id": "Ingatlah, kamu ini orang-orang yang diajak untuk menafkahkan (hartamu) pada jalan Allah. Maka di antara kamu ada yang kikir, dan siapa yang kikir sesungguhnya dia hanyalah kikir terhadap dirinya sendiri. Dan Allah-lah yang Maha Kaya sedangkan kamulah orang-orang yang berkehendak (kepada-Nya); dan jika kamu berpaling niscaya Dia akan mengganti (kamu) dengan kaum yang lain; dan mereka tidak akan seperti kamu ini.", "manzil": 6, "manzil_display": ""}], "511": [{"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 26, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 1, "text": "إِنَّا فَتَحۡنَا لَكَ فَتۡحࣰا مُّبِینࣰا ۝١", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "إنا فتحنا لك -أيها الرسول- فتحًا مبينًا، يظهر الله فيه دينك، وينصرك على عدوك، وهو هدنة \"الحديبية\" التي أمن الناس بسببها بعضهم بعضًا، فاتسعت دائرة الدعوة لدين الله، وتمكن من يريد الوقوف على حقيقة الإسلام مِن معرفته، فدخل الناس تلك المدة في دين الله أفواجًا؛ ولذلك سمَّاه الله فتحًا مبينًا، أي ظاهرًا جليًّا.", "isBasmala": false, "translation_en": "We have granted you a conspicuous victory.", "translation_id": "Sesungguhnya Kami telah memberikan kepadamu kemenangan yang nyata,", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 2, "text": "لِّیَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَیُتِمَّ نِعۡمَتَهُۥ عَلَیۡكَ وَیَهۡدِیَكَ صِرَ ٰطࣰا مُّسۡتَقِیمࣰا ۝٢", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "فتحنا لك ذلك الفتح، ويسَّرناه لك؛ ليغفر الله لك ما تقدم من ذنبك وما تأخر؛ بسبب ما حصل من هذا الفتح من الطاعات الكثيرة وبما تحملته من المشقات، ويتم نعمته عليك بإظهار دينك ونصرك على أعدائك، ويرشدك طريقًا مستقيمًا من الدين لا عوج فيه، وينصرك الله نصرًا قويًّا لا يَضْعُف فيه الإسلام.", "isBasmala": false, "translation_en": "That God may forgive you your sin, past and to come, and complete His favors upon you, and guide you in a straight path.", "translation_id": "supaya Allah memberi ampunan kepadamu terhadap dosamu yang telah lalu dan yang akan datang serta menyempurnakan nikmat-Nya atasmu dan memimpin kamu kepada jalan yang lurus,", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 3, "text": "وَیَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِیزًا ۝٣", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "فتحنا لك ذلك الفتح، ويسَّرناه لك؛ ليغفر الله لك ما تقدم من ذنبك وما تأخر؛ بسبب ما حصل من هذا الفتح من الطاعات الكثيرة وبما تحملته من المشقات، ويتم نعمته عليك بإظهار دينك ونصرك على أعدائك، ويرشدك طريقًا مستقيمًا من الدين لا عوج فيه، وينصرك الله نصرًا قويًّا لا يَضْعُف فيه الإسلام.", "isBasmala": false, "translation_en": "And help you with an unwavering support.", "translation_id": "dan supaya Allah menolongmu dengan pertolongan yang kuat (banyak).", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 4, "text": "هُوَ ٱلَّذِیۤ أَنزَلَ ٱلسَّكِینَةَ فِی قُلُوبِ ٱلۡمُؤۡمِنِینَ لِیَزۡدَادُوۤا۟ إِیمَـٰنࣰا مَّعَ إِیمَـٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِیمًا حَكِیمࣰا ۝٤", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "هو الله الذي أنزل الطمأنينة في قلوب المؤمنين بالله ورسوله يوم \"الحديبية\" فسكنت، ورسخ اليقين فيها؛ ليزدادوا تصديقًا لله واتباعًا لرسوله مع تصديقهم واتباعهم. ولله سبحانه وتعالى جنود السموات والأرض ينصر بهم عباده المؤمنين. وكان الله عليمًا بمصالح خلقه، حكيمًا في تدبيره وصنعه.", "isBasmala": false, "translation_en": "It is He who sent down tranquility into the hearts of the believers, to add faith to their faith. To God belong the forces of the heavens and the earth. God is Knowing and Wise.", "translation_id": "Dialah yang telah menurunkan ketenangan ke dalam hati orang-orang mukmin supaya keimanan mereka bertambah di samping keimanan mereka (yang telah ada). Dan kepunyaan Allah-lah tentara langit dan bumi dan adalah Allah Maha Mengetahui lagi Maha Bijaksana,", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 5, "text": "لِّیُدۡخِلَ ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَا وَیُكَفِّرَ عَنۡهُمۡ سَیِّـَٔاتِهِمۡۚ وَكَانَ ذَ ٰلِكَ عِندَ ٱللَّهِ فَوۡزًا عَظِیمࣰا ۝٥", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "ليدخل الله المؤمنين والمؤمنات جنات تجري مِن تحت أشجارها وقصورها الأنهار، ماكثين فيها أبدًا، ويمحو عنهم سيِّئ ما عملوا، فلا يعاقبهم عليه، وكان ذلك الجزاء عند الله نجاة من كل غم، وظَفَرًا بكل مطلوب.", "isBasmala": false, "translation_en": "He will admit the believers, male and female, into Gardens beneath which rivers flow, to abide therein forever, and He will remit their sins. That, with God, is a great triumph.", "translation_id": "supaya Dia memasukkan orang-orang mukmin laki-laki dan perempuan ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya dan supaya Dia menutupi kesalahan-kesalahan mereka. Dan yang demikian itu adalah keberuntungan yang besar di sisi Allah,", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 6, "text": "وَیُعَذِّبَ ٱلۡمُنَـٰفِقِینَ وَٱلۡمُنَـٰفِقَـٰتِ وَٱلۡمُشۡرِكِینَ وَٱلۡمُشۡرِكَـٰتِ ٱلظَّاۤنِّینَ بِٱللَّهِ ظَنَّ ٱلسَّوۡءِۚ عَلَیۡهِمۡ دَاۤىِٕرَةُ ٱلسَّوۡءِۖ وَغَضِبَ ٱللَّهُ عَلَیۡهِمۡ وَلَعَنَهُمۡ وَأَعَدَّ لَهُمۡ جَهَنَّمَۖ وَسَاۤءَتۡ مَصِیرࣰا ۝٦", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "ويعذب الله المنافقين والمنافقات والمشركين والمشركات الذين يظنون ظنًا سيئًا بالله أنه لن ينصر نبيه والمؤمنين معه على أعدائهم، ولن يُظهر دينه، فعلى هؤلاء تدور دائرة العذاب وكل ما يسوءهم، وغضب الله عليهم، وطردهم من رحمته، وأعدَّ لهم نار جهنم، وساءت منزلا يصيرون إليه.", "isBasmala": false, "translation_en": "And He will punish the hypocrites, male and female, and the idolaters, male and female, those who harbor evil thoughts about God. They are surrounded by evil; and God is angry with them, and has cursed them, and has prepared for them Hell-a miserable destination.", "translation_id": "dan supaya Dia mengazab orang-orang munafik laki-laki dan perempuan dan orang-orang musyrik laki-laki dan perempuan yang mereka itu berprasangka buruk terhadap Allah. Mereka akan mendapat giliran (kebinasaan) yang amat buruk dan Allah memurkai dan mengutuk mereka serta menyediakan bagi mereka neraka Jahannam. Dan (neraka Jahannam) itulah sejahat-jahat tempat kembali.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 7, "text": "وَلِلَّهِ جُنُودُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَزِیزًا حَكِیمًا ۝٧", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "ولله سبحانه وتعالى جنود السموات والأرض يؤيد بهم عباده المؤمنين. وكان الله عزيزًا على خلقه، حكيمًا في تدبير أمورهم.", "isBasmala": false, "translation_en": "To God belong the troops of the heavens and the earth. God is Mighty and Wise.", "translation_id": "Dan kepunyaan Allah-lah tentara langit dan bumi. Dan adalah Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 8, "text": "إِنَّاۤ أَرۡسَلۡنَـٰكَ شَـٰهِدࣰا وَمُبَشِّرࣰا وَنَذِیرࣰا ۝٨", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "إنا أرسلناك -أيها الرسول- شاهدًا على أمتك بالبلاغ، مبينًا لهم ما أرسلناك به إليهم، ومبشرًا لمن أطاعك بالجنة، ونذيرًا لمن عصاك بالعقاب العاجل والآجل؛ لتؤمنوا بالله ورسوله، وتنصروا الله بنصر دينه، وتعظموه، وتسبحوه أول النهار وآخره.", "isBasmala": false, "translation_en": "We sent you as a witness, and a bearer of good news, and a warner.", "translation_id": "Sesungguhnya Kami mengutus kamu sebagai saksi, pembawa berita gembira dan pemberi peringatan,", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 9, "text": "لِّتُؤۡمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۚ وَتُسَبِّحُوهُ بُكۡرَةࣰ وَأَصِیلًا ۝٩", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "إنا أرسلناك -أيها الرسول- شاهدًا على أمتك بالبلاغ، مبينًا لهم ما أرسلناك به إليهم، ومبشرًا لمن أطاعك بالجنة، ونذيرًا لمن عصاك بالعقاب العاجل والآجل؛ لتؤمنوا بالله ورسوله، وتنصروا الله بنصر دينه، وتعظموه، وتسبحوه أول النهار وآخره.", "isBasmala": false, "translation_en": "That you may believe in God and His Messenger, and support Him, and honor Him, and praise Him morning and evening.", "translation_id": "supaya kamu sekalian beriman kepada Allah dan Rasul-Nya, menguatkan (agama)Nya, membesarkan-Nya. Dan bertasbih kepada-Nya di waktu pagi dan petang.", "manzil": 6, "manzil_display": ""}], "512": [{"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 10, "text": "إِنَّ ٱلَّذِینَ یُبَایِعُونَكَ إِنَّمَا یُبَایِعُونَ ٱللَّهَ یَدُ ٱللَّهِ فَوۡقَ أَیۡدِیهِمۡۚ فَمَن نَّكَثَ فَإِنَّمَا یَنكُثُ عَلَىٰ نَفۡسِهِۦۖ وَمَنۡ أَوۡفَىٰ بِمَا عَـٰهَدَ عَلَیۡهُ ٱللَّهَ فَسَیُؤۡتِیهِ أَجۡرًا عَظِیمࣰا ۝١٠", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "إن الذين يبايعونك -أيها النبي- بـ \"الحديبية\" على القتال إنما يبايعون الله، ويعقدون العقد معه ابتغاء جنته ورضوانه، يد الله فوق أيديهم، فهو معهم يسمع أقوالهم، ويرى مكانهم، ويعلم ضمائرهم وظواهرهم، فمن نقض بيعته فإنما يعود وبال ذلك على نفسه، ومن أوفى بما عاهد الله عليه من الصبر عند لقاء العدو في سبيل الله ونصرة نبيه محمد صلى الله عليه وسلم، فسيعطيه الله ثوابًا جزيلا وهو الجنة. وفي الآية إثبات صفة اليد لله تعالى بما يليق به سبحانه، دون تشبيه ولا تكييف.", "isBasmala": false, "translation_en": "Those who pledge allegiance to you are pledging allegiance to God. The hand of God is over their hands. Whoever breaks his pledge breaks it to his own loss. And whoever fulfills his covenant with God, He will grant him a great reward.", "translation_id": "Bahwasanya orang-orang yang berjanji setia kepada kamu sesungguhnya mereka berjanji setia kepada Allah. Tangan Allah di atas tangan mereka, maka barangsiapa yang melanggar janjinya niscaya akibat ia melanggar janji itu akan menimpa dirinya sendiri dan barangsiapa menepati janjinya kepada Allah maka Allah akan memberinya pahala yang besar.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 11, "text": "سَیَقُولُ لَكَ ٱلۡمُخَلَّفُونَ مِنَ ٱلۡأَعۡرَابِ شَغَلَتۡنَاۤ أَمۡوَ ٰلُنَا وَأَهۡلُونَا فَٱسۡتَغۡفِرۡ لَنَاۚ یَقُولُونَ بِأَلۡسِنَتِهِم مَّا لَیۡسَ فِی قُلُوبِهِمۡۚ قُلۡ فَمَن یَمۡلِكُ لَكُم مِّنَ ٱللَّهِ شَیۡـًٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ نَفۡعَۢاۚ بَلۡ كَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرَۢا ۝١١", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "سيقول لك -أيها النبي- الذين تخلَّفوا من الأعراب عن الخروج معك إلى \"مكة\" إذا عاتبتهم: شغلتنا أموالنا وأهلونا، فاسأل ربك أن يغفر لنا تخلُّفنا، يقولون ذلك بألسنتهم، ولا حقيقة له في قلوبهم، قل لهم: فمن يملك لكم من الله شيئًا إن أراد بكم شرًا أو خيرًا؟ ليس الأمر كما ظن هؤلاء المنافقون أن الله لا يعلم ما انطوت عليه بواطنهم من النفاق، بل إنه سبحانه كان بما يعملون خبيرًا، لا يخفى عليه شيء من أعمال خلقه.", "isBasmala": false, "translation_en": "The Desert-Arabs who remained behind will say to you, \"Our belongings and our families have preoccupied us, so ask forgiveness for us.\" They say with their tongues what is not in their hearts. Say, \"Who can avail you anything against God, if He desires loss for you, or desires gain for you?\" In fact, God is Informed of what you do.", "translation_id": "Orang-orang Badwi yang tertinggal (tidak turut ke Hudaibiyah) akan mengatakan: \"Harta dan keluarga kami telah merintangi kami, maka mohonkanlah ampunan untuk kami\"; mereka mengucapkan dengan lidahnya apa yang tidak ada dalam hatinya. Katakanlah: \"Maka siapakah (gerangan) yang dapat menghalang-halangi kehendak Allah jika Dia menghendaki kemudharatan bagimu atau jika Dia menghendaki manfaat bagimu. Sebenarnya Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 12, "text": "بَلۡ ظَنَنتُمۡ أَن لَّن یَنقَلِبَ ٱلرَّسُولُ وَٱلۡمُؤۡمِنُونَ إِلَىٰۤ أَهۡلِیهِمۡ أَبَدࣰا وَزُیِّنَ ذَ ٰلِكَ فِی قُلُوبِكُمۡ وَظَنَنتُمۡ ظَنَّ ٱلسَّوۡءِ وَكُنتُمۡ قَوۡمَۢا بُورࣰا ۝١٢", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "وليس الأمر كما زعمتم من انشغالكم بالأموال والأهل، بل إنكم ظننتم أن رسول الله صلى الله عليه وسلم ومن معه من أصحابه سيَهْلكون، ولا يَرْجعون إليكم أبدًا، وحسَّن الشيطان ذلك في قلوبكم، وظننتم ظنًا سيئًا أن الله لن ينصر نبيه محمدًا صلى الله عليه وسلم وأصحابه على أعدائهم، وكنتم قومًا هَلْكى لا خير فيكم.", "isBasmala": false, "translation_en": "But you thought that the Messenger and the believers will never return to their families, and this seemed fine to your hearts; and you harbored evil thoughts, and were uncivilized people.", "translation_id": "Tetapi kamu menyangka bahwa Rasul dan orang-orang mukmin tidak sekali-kali akan kembali kepada keluarga mereka selama-lamanya dan syaitan telah menjadikan kamu memandang baik dalam hatimu persangkaan itu, dan kamu telah menyangka dengan sangkaan yang buruk dan kamu menjadi kaum yang binasa.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 13, "text": "وَمَن لَّمۡ یُؤۡمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّاۤ أَعۡتَدۡنَا لِلۡكَـٰفِرِینَ سَعِیرࣰا ۝١٣", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "ومن لم يصدِّق بالله وبما جاء به رسوله صلى الله عليه وسلم ويعمل بشرعه، فإنه كافر مستحق للعقاب، فإنا أعددنا للكافرين عذاب السعير في النار.", "isBasmala": false, "translation_en": "He who does not believe in God and His Messenger-We have prepared for the disbelievers a Blazing Fire.", "translation_id": "Dan barangsiapa yang tidak beriman kepada Allah dan Rasul-Nya maka sesungguhnya Kami menyediakan untuk orang-orang yang kafir neraka yang bernyala-nyala.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 14, "text": "وَلِلَّهِ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ یَغۡفِرُ لِمَن یَشَاۤءُ وَیُعَذِّبُ مَن یَشَاۤءُۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا ۝١٤", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "ولله ملك السموات والأرض وما فيهما، يتجاوز برحمته عمن يشاء فيستر ذنبه، ويعذِّب بعدله من يشاء. وكان الله سبحانه وتعالى غفورًا لمن تاب إليه، رحيمًا به.", "isBasmala": false, "translation_en": "To God belongs the kingdom of the heavens and the earth. He forgives whomever He wills, and He punishes whomever He wills. God is Forgiving and Merciful.", "translation_id": "Dan hanya kepunyaan Allah-lah kerajaan langit dan bumi. Dia memberikan ampun kepada siapa yang dikehendaki-Nya dan mengazab siapa yang dikehendaki-Nya. Dan Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 15, "text": "سَیَقُولُ ٱلۡمُخَلَّفُونَ إِذَا ٱنطَلَقۡتُمۡ إِلَىٰ مَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡۖ یُرِیدُونَ أَن یُبَدِّلُوا۟ كَلَـٰمَ ٱللَّهِۚ قُل لَّن تَتَّبِعُونَا كَذَ ٰلِكُمۡ قَالَ ٱللَّهُ مِن قَبۡلُۖ فَسَیَقُولُونَ بَلۡ تَحۡسُدُونَنَاۚ بَلۡ كَانُوا۟ لَا یَفۡقَهُونَ إِلَّا قَلِیلࣰا ۝١٥", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "سيقول المخلَّفون، إذا انطلقت -أيها النبي- أنت وأصحابك إلى غنائم \"خيبر\" التي وعدكم الله بها، اتركونا نذهب معكم إلى \"خيبر\"، يريدون أن يغيِّروا بذلك وعد الله لكم. قل لهم: لن تخرجوا معنا إلى \"خيبر\"؛ لأن الله تعالى قال لنا من قبل رجوعنا إلى \"المدينة\": إن غنائم \"خيبر\" هي لمن شهد \"الحديبية\" معنا، فسيقولون: ليس الأمر كما تقولون، إن الله لم يأمركم بهذا، إنكم تمنعوننا من الخروج معكم حسدًا منكم؛ لئلا نصيب معكم الغنيمة، وليس الأمر كما زعموا، بل كانوا لا يفقهون عن الله ما لهم وما عليهم من أمر الدين إلا يسيرًا.", "isBasmala": false, "translation_en": "Those who lagged behind will say when you depart to collect the gains, \"Let us follow you.\" They want to change the Word of God. Say, \"You will not follow us; God has said so before.\" Then they will say, \"But you are jealous of us.\" In fact, they understand only a little.", "translation_id": "Orang-orang Badwi yang tertinggal itu akan berkata apabila kamu berangkat untuk mengambil barang rampasan: \"Biarkanlah kami, niscaya kami mengikuti kamu\"; mereka hendak merubah janji Allah. Katakanlah: \"Kamu sekali-kali tidak (boleh) mengikuti kami; demikian Allah telah menetapkan sebelumnya\"; mereka akan mengatakan: \"Sebenarnya kamu dengki kepada kami\". Bahkan mereka tidak mengerti melainkan sedikit sekali.", "manzil": 6, "manzil_display": ""}], "513": [{"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 16, "text": "قُل لِّلۡمُخَلَّفِینَ مِنَ ٱلۡأَعۡرَابِ سَتُدۡعَوۡنَ إِلَىٰ قَوۡمٍ أُو۟لِی بَأۡسࣲ شَدِیدࣲ تُقَـٰتِلُونَهُمۡ أَوۡ یُسۡلِمُونَۖ فَإِن تُطِیعُوا۟ یُؤۡتِكُمُ ٱللَّهُ أَجۡرًا حَسَنࣰاۖ وَإِن تَتَوَلَّوۡا۟ كَمَا تَوَلَّیۡتُم مِّن قَبۡلُ یُعَذِّبۡكُمۡ عَذَابًا أَلِیمࣰا ۝١٦", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "قل للذين تخلَّفوا من الأعراب (وهم البدو) عن القتال: ستُدْعون إلى قتال قوم أصحاب بأس شديد في القتال، تقاتلونهم أو يسلمون من غير قتال، فإن تطيعوا الله فيما دعاكم إليه مِن قتال هؤلاء القوم يؤتكم الجنة، وإن تعصوه كما فعلتم حين تخلفتم عن السير مع رسول الله صلى الله عليه وسلم إلى \"مكة\"، يعذبكم عذابًا موجعًا.", "isBasmala": false, "translation_en": "Say to the Desert-Arabs who lagged behind, \"You will be called against a people of great might; you will fight them, unless they submit. If you obey, God will give you a fine reward. But if you turn away, as you turned away before, He will punish you with a painful punishment.\"", "translation_id": "Katakanlah kepada orang-orang Badwi yang tertinggal: \"Kamu akan diajak untuk (memerangi) kaum yang mempunyai kekuatan yang besar, kamu akan memerangi mereka atau mereka menyerah (masuk Islam). Maka jika kamu patuhi (ajakan itu) niscaya Allah akan memberikan kepadamu pahala yang baik dan jika kamu berpaling sebagaimana kamu telah berpaling sebelumnya, niscaya Dia akan mengazab kamu dengan azab yang pedih\".", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 17, "text": "لَّیۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجࣱ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجࣱ وَلَا عَلَى ٱلۡمَرِیضِ حَرَجࣱۗ وَمَن یُطِعِ ٱللَّهَ وَرَسُولَهُۥ یُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ وَمَن یَتَوَلَّ یُعَذِّبۡهُ عَذَابًا أَلِیمࣰا ۝١٧", "juz": 26, "hizb": "(*¾ ح 51*)", "tafsir": "ليس على الأعمى منكم- أيها الناس- إثم، ولا على الأعرج إثم، ولا على المريض إثم، في أن يتخلَّفوا عن الجهاد مع المؤمنين؛ لعدم استطاعتهم. ومن يطع الله ورسوله يدخله جنات تجري مِن تحت أشجارها وقصورها الأنهار، ومن يعص الله ورسوله، فيتخلَّف عن الجهاد مع المؤمنين، يعذبه عذابًا مؤلمًا موجعًا.", "isBasmala": false, "translation_en": "There is no blame on the blind, nor any blame on the lame, nor any blame on the sick. Whoever obeys God and His Messenger-He will admit him into gardens beneath which rivers flow; but whoever turns away-He will punish him with a painful punishment.", "translation_id": "Tiada dosa atas orang-orang yang buta dan atas orang yang pincang dan atas orang yang sakit (apabila tidak ikut berperang). Dan barangsiapa yang taat kepada Allah dan Rasul-Nya; niscaya Allah akan memasukkannya ke dalam surga yang mengalir di bawahnya sungai-sungai dan barang siapa yang berpaling niscaya akan diazab-Nya dengan azab yang pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 18, "text": "۞ لَّقَدۡ رَضِیَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِینَ إِذۡ یُبَایِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِی قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِینَةَ عَلَیۡهِمۡ وَأَثَـٰبَهُمۡ فَتۡحࣰا قَرِیبࣰا ۝١٨", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "لقد رضي الله عن المؤمنين حين بايعوك -أيها النبي- تحت الشجرة (وهذه هي بيعة الرضوان في \"الحديبية\") فعلم الله ما في قلوب هؤلاء المؤمنين من الإيمان والصدق والوفاء، فأنزل الله الطمأنينة عليهم وثبَّت قلوبهم، وعوَّضهم عمَّا فاتهم بصلح \"الحديبية\" فتحًا قريبًا، وهو فتح \"خيبر\"، ومغانم كثيرة تأخذونها من أموال يهود \"خيبر\". وكان الله عزيزًا في انتقامه من أعدائه، حكيمًا في تدبير أمور خلقه.", "isBasmala": false, "translation_en": "God was pleased with the believers, when they pledged allegiance to you under the tree. He knew what was in their hearts, and sent down serenity upon them, and rewarded them with an imminent conquest.", "translation_id": "Sesungguhnya Allah telah ridha terhadap orang-orang mukmin ketika mereka berjanji setia kepadamu di bawah pohon, maka Allah mengetahui apa yang ada dalam hati mereka lalu menurunkan ketenangan atas mereka dan memberi balasan kepada mereka dengan kemenangan yang dekat (waktunya).", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 19, "text": "وَمَغَانِمَ كَثِیرَةࣰ یَأۡخُذُونَهَاۗ وَكَانَ ٱللَّهُ عَزِیزًا حَكِیمࣰا ۝١٩", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "لقد رضي الله عن المؤمنين حين بايعوك -أيها النبي- تحت الشجرة (وهذه هي بيعة الرضوان في \"الحديبية\") فعلم الله ما في قلوب هؤلاء المؤمنين من الإيمان والصدق والوفاء، فأنزل الله الطمأنينة عليهم وثبَّت قلوبهم، وعوَّضهم عمَّا فاتهم بصلح \"الحديبية\" فتحًا قريبًا، وهو فتح \"خيبر\"، ومغانم كثيرة تأخذونها من أموال يهود \"خيبر\". وكان الله عزيزًا في انتقامه من أعدائه، حكيمًا في تدبير أمور خلقه.", "isBasmala": false, "translation_en": "And abundant gains for them to capture. God is Mighty and Wise.", "translation_id": "Serta harta rampasan yang banyak yang dapat mereka ambil. Dan adalah Allah Maha Perkasa lagi Maha Bijaksana.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 20, "text": "وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِیرَةࣰ تَأۡخُذُونَهَا فَعَجَّلَ لَكُمۡ هَـٰذِهِۦ وَكَفَّ أَیۡدِیَ ٱلنَّاسِ عَنكُمۡ وَلِتَكُونَ ءَایَةࣰ لِّلۡمُؤۡمِنِینَ وَیَهۡدِیَكُمۡ صِرَ ٰطࣰا مُّسۡتَقِیمࣰا ۝٢٠", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "وعدكم الله مغانم كثيرة تأخذونها في أوقاتها التي قدَّرها الله لكم فعجَّل لكم غنائم \"خيبر\"، وكفَّ أيدي الناس عنكم، فلم ينلكم سوء مما كان أعداؤكم أضمروه لكم من المحاربة والقتال، ومن أن ينالوا ممن تركتموهم وراءكم في \"المدينة\"، ولتكون هزيمتهم وسلامتكم وغنيمتكم علامة تعتبرون بها، وتستدلون على أن الله حافظكم وناصركم، ويرشدكم طريقا مستقيما لا اعوجاج فيه. وقد وعدكم الله غنيمة أخرى لم تقدروا عليها، الله سبحانه وتعالى قادر عليها، وهي تحت تدبيره وملكه، وقد وعدكموها، ولا بد مِن وقوع ما وعد به. وكان الله على كل شيء قديرًا لا يعجزه شيء. ولو قاتلكم كفار قريش بـ \"مكة\" لانهزموا عنكم وولوكم ظهورهم، كما يفعل المنهزم في القتال، ثم لا يجدون لهم من دون الله وليًا يواليهم على حربكم، ولا نصيرًا يعينهم على قتالكم.", "isBasmala": false, "translation_en": "God has promised you abundant gains, which you will capture. He has expedited this for you, and has restrained people's hands from you; that it may be a sign to the believers, and that He may guide you on a straight path.", "translation_id": "Allah menjanjikan kepada kamu harta rampasan yang banyak yang dapat kamu ambil, maka disegerakan-Nya harta rampasan ini untukmu dan Dia menahan tangan manusia dari (membinasakan)mu (agar kamu mensyukuri-Nya) dan agar hal itu menjadi bukti bagi orang-orang mukmin dan agar Dia menunjuki kamu kepada jalan yang lurus.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 21, "text": "وَأُخۡرَىٰ لَمۡ تَقۡدِرُوا۟ عَلَیۡهَا قَدۡ أَحَاطَ ٱللَّهُ بِهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣰا ۝٢١", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "وعدكم الله مغانم كثيرة تأخذونها في أوقاتها التي قدَّرها الله لكم فعجَّل لكم غنائم \"خيبر\"، وكفَّ أيدي الناس عنكم، فلم ينلكم سوء مما كان أعداؤكم أضمروه لكم من المحاربة والقتال، ومن أن ينالوا ممن تركتموهم وراءكم في \"المدينة\"، ولتكون هزيمتهم وسلامتكم وغنيمتكم علامة تعتبرون بها، وتستدلون على أن الله حافظكم وناصركم، ويرشدكم طريقا مستقيما لا اعوجاج فيه. وقد وعدكم الله غنيمة أخرى لم تقدروا عليها، الله سبحانه وتعالى قادر عليها، وهي تحت تدبيره وملكه، وقد وعدكموها، ولا بد مِن وقوع ما وعد به. وكان الله على كل شيء قديرًا لا يعجزه شيء. ولو قاتلكم كفار قريش بـ \"مكة\" لانهزموا عنكم وولوكم ظهورهم، كما يفعل المنهزم في القتال، ثم لا يجدون لهم من دون الله وليًا يواليهم على حربكم، ولا نصيرًا يعينهم على قتالكم.", "isBasmala": false, "translation_en": "And other things, of which you were incapable, but God has encompassed them. God is Capable of everything.", "translation_id": "Dan (telah menjanjikan pula kemenangan-kemenangan) yang lain (atas negeri-negeri) yang kamu belum dapat menguasainya yang sungguh Allah telah menentukan-Nya. Dan adalah Allah Maha Kuasa atas segala sesuatu.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 22, "text": "وَلَوۡ قَـٰتَلَكُمُ ٱلَّذِینَ كَفَرُوا۟ لَوَلَّوُا۟ ٱلۡأَدۡبَـٰرَ ثُمَّ لَا یَجِدُونَ وَلِیࣰّا وَلَا نَصِیرࣰا ۝٢٢", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "وعدكم الله مغانم كثيرة تأخذونها في أوقاتها التي قدَّرها الله لكم فعجَّل لكم غنائم \"خيبر\"، وكفَّ أيدي الناس عنكم، فلم ينلكم سوء مما كان أعداؤكم أضمروه لكم من المحاربة والقتال، ومن أن ينالوا ممن تركتموهم وراءكم في \"المدينة\"، ولتكون هزيمتهم وسلامتكم وغنيمتكم علامة تعتبرون بها، وتستدلون على أن الله حافظكم وناصركم، ويرشدكم طريقا مستقيما لا اعوجاج فيه. وقد وعدكم الله غنيمة أخرى لم تقدروا عليها، الله سبحانه وتعالى قادر عليها، وهي تحت تدبيره وملكه، وقد وعدكموها، ولا بد مِن وقوع ما وعد به. وكان الله على كل شيء قديرًا لا يعجزه شيء. ولو قاتلكم كفار قريش بـ \"مكة\" لانهزموا عنكم وولوكم ظهورهم، كما يفعل المنهزم في القتال، ثم لا يجدون لهم من دون الله وليًا يواليهم على حربكم، ولا نصيرًا يعينهم على قتالكم.", "isBasmala": false, "translation_en": "If those who disbelieve had fought you, they would have turned back and fled, then found neither protector nor helper.", "translation_id": "Dan sekiranya orang-orang kafir itu memerangi kamu pastilah mereka berbalik melarikan diri ke belakang (kalah) kemudian mereka tiada memperoleh pelindung dan tidak (pula) penolong.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 23, "text": "سُنَّةَ ٱللَّهِ ٱلَّتِی قَدۡ خَلَتۡ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِیلࣰا ۝٢٣", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "سنة الله التي سنَّها في خلقه من قبل بنصر جنده وهزيمة أعدائه، ولن تجد -أيها النبي- لسنة الله تغييرًا.", "isBasmala": false, "translation_en": "It is God's pattern, ongoing since the past. You will never find any change in God's pattern.", "translation_id": "Sebagai suatu sunnatullah yang telah berlaku sejak dahulu, kamu sekali-kali tiada akan menemukan perubahan bagi sunnatullah itu.", "manzil": 6, "manzil_display": ""}], "514": [{"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 24, "text": "وَهُوَ ٱلَّذِی كَفَّ أَیۡدِیَهُمۡ عَنكُمۡ وَأَیۡدِیَكُمۡ عَنۡهُم بِبَطۡنِ مَكَّةَ مِنۢ بَعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَیۡهِمۡۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرًا ۝٢٤", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "وهو الذي كفَّ أيدي المشركين عنكم، وأيديكم عنهم ببطن \"مكة\" من بعد ما قَدَرْتم عليهم، فصاروا تحت سلطانكم (وهؤلاء المشركون هم الذين خرجوا على عسكر رسول الله صلى الله عليه وسلم بـ\"الحديبية\"، فأمسكهم المسلمون ثم تركوهم ولم يقتلوهم، وكانوا نحو ثمانين رجلا) وكان الله بأعمالكم بصيرًا، لا تخفى عليه خافية.", "isBasmala": false, "translation_en": "It is He who withheld their hands from you, and your hands from them, in the valley of Mecca, after giving you advantage over them. God is Observer of what you do.", "translation_id": "Dan Dialah yang menahan tangan mereka dari (membinasakan) kamu dan (menahan) tangan kamu dari (membinasakan) mereka di tengah kota Mekah sesudah Allah memenangkan kamu atas mereka, dan adalah Allah Maha Melihat apa yang kamu kerjakan.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 25, "text": "هُمُ ٱلَّذِینَ كَفَرُوا۟ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَٱلۡهَدۡیَ مَعۡكُوفًا أَن یَبۡلُغَ مَحِلَّهُۥۚ وَلَوۡلَا رِجَالࣱ مُّؤۡمِنُونَ وَنِسَاۤءࣱ مُّؤۡمِنَـٰتࣱ لَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِیبَكُم مِّنۡهُم مَّعَرَّةُۢ بِغَیۡرِ عِلۡمࣲۖ لِّیُدۡخِلَ ٱللَّهُ فِی رَحۡمَتِهِۦ مَن یَشَاۤءُۚ لَوۡ تَزَیَّلُوا۟ لَعَذَّبۡنَا ٱلَّذِینَ كَفَرُوا۟ مِنۡهُمۡ عَذَابًا أَلِیمًا ۝٢٥", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "كفار قريش هم الذين جحدوا توحيد الله، وصدُّوكم يوم \"الحديبية\" عن دخول المسجد الحرام، ومنعوا الهدي، وحبسوه أن يبلغ محل نحره، وهو الحرم. ولولا رجال مؤمنون مستضعفون ونساء مؤمنات بين أظهر هؤلاء الكافرين بـ \"مكة\"، يكتمون إيمانهم خيفة على أنفسهم لم تعرفوهم؛ خشية أن تطؤوهم بجيشكم فتقتلوهم، فيصيبكم بذلك القتل إثم وعيب وغرامة بغير علم، لكنَّا سلَّطناكم عليهم؛ ليدخل الله في رحمته من يشاء فيَمُنَّ عليهم بالإيمان بعد الكفر، لو تميَّز هؤلاء المؤمنون والمؤمنات عن مشركي \"مكة\" وخرجوا من بينهم، لعذَّبنا الذين كفروا وكذَّبوا منهم عذابًا مؤلمًا موجعًا.", "isBasmala": false, "translation_en": "It is they who disbelieved, and barred you from the Sacred Mosque, and prevented the offering from reaching its destination. Were it not for faithful men and faithful women, whom you did not know, you were about to hurt them, and became guilty of an unintentional crime. Thus God admits into His mercy whomever He wills. Had they dispersed, We would have punished those who disbelieved among them with a painful penalty.", "translation_id": "Merekalah orang-orang yang kafir yang menghalangi kamu dari (masuk) Masjidil Haram dan menghalangi hewan korban sampai ke tempat (penyembelihan)nya. Dan kalau tidaklah karena laki-laki yang mukmin dan perempuan-perempuan yang mukmin yang tiada kamu ketahui, bahwa kamu akan membunuh mereka yang menyebabkan kamu ditimpa kesusahan tanpa pengetahuanmu (tentulah Allah tidak akan menahan tanganmu dari membinasakan mereka). Supaya Allah memasukkan siapa yang dikehendaki-Nya ke dalam rahmat-Nya. Sekiranya mereka tidak bercampur-baur, tentulah Kami akan mengazab orang-orang yag kafir di antara mereka dengan azab yang pedih.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 26, "text": "إِذۡ جَعَلَ ٱلَّذِینَ كَفَرُوا۟ فِی قُلُوبِهِمُ ٱلۡحَمِیَّةَ حَمِیَّةَ ٱلۡجَـٰهِلِیَّةِ فَأَنزَلَ ٱللَّهُ سَكِینَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِینَ وَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ وَكَانُوۤا۟ أَحَقَّ بِهَا وَأَهۡلَهَاۚ وَكَانَ ٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣰا ۝٢٦", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "إذ جعل الذين كفروا في قلوبهم الأنَفَة أنَفَة الجاهلية؛ لئلا يقروا برسالة محمد صلى الله عليه وسلم، ومن ذلك امتناعهم أن يكتبوا في صلح \"الحديبية\"بسم الله الرحمن الرحيم\" وأبوا أن يكتبوا \"هذا ما قاضى عليه محمد رسول الله\"، فأنزل الله الطمأنينة على رسوله وعلى المؤمنين معه، وألزمهم قول \"لا إله إلا الله\" التي هي رأس كل تقوى، وكان الرسول صلى الله عليه وسلم والمؤمنون معه أحق بكلمة التقوى من المشركين، وكانوا كذلك أهل هذه الكلمة دون المشركين. وكان الله بكل شيء عليمًا لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "Those who disbelieved filled their hearts with rage-the rage of the days of ignorance. But God sent His serenity down upon His Messenger, and upon the believers, and imposed on them the words of righteousness-of which they were most worthy and deserving. God is aware of everything.", "translation_id": "Ketika orang-orang kafir menanamkan dalam hati mereka kesombongan (yaitu) kesombongan jahiliyah lalu Allah menurunkan ketenangan kepada Rasul-Nya, dan kepada orang-orang mukmin dan Allah mewajibkan kepada mereka kalimat-takwa dan adalah mereka berhak dengan kalimat takwa itu dan patut memilikinya. Dan adalah Allah Maha Mengetahui segala sesuatu.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 27, "text": "لَّقَدۡ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡیَا بِٱلۡحَقِّۖ لَتَدۡخُلُنَّ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ إِن شَاۤءَ ٱللَّهُ ءَامِنِینَ مُحَلِّقِینَ رُءُوسَكُمۡ وَمُقَصِّرِینَ لَا تَخَافُونَۖ فَعَلِمَ مَا لَمۡ تَعۡلَمُوا۟ فَجَعَلَ مِن دُونِ ذَ ٰلِكَ فَتۡحࣰا قَرِیبًا ۝٢٧", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "لقد صدق الله رسوله محمدًا رؤياه التي أراها إياه بالحق أنه يدخل هو وأصحابه بيت الله الحرام آمنين، لا تخافون أهل الشرك، محلِّقين رؤوسكم ومقصِّرين، فعلم الله من الخير والمصلحة (في صرفكم عن \"مكة\" عامكم ذلك ودخولكم إليها فيما بعد) ما لم تعلموا أنتم، فجعل مِن دون دخولكم \"مكة\" الذي وعدتم به، فتحًا قريبًا، وهو هدنة \"الحديبية\" وفتح \"خيبر\".", "isBasmala": false, "translation_en": "God has fulfilled His Messenger's vision in truth: \"You will enter the Sacred Mosque, God willing, in security, heads shaven, or hair cut short, not fearing. He knew what you did not know, and has granted besides that an imminent victory.\"", "translation_id": "Sesungguhnya Allah akan membuktikan kepada Rasul-Nya, tentang kebenaran mimpinya dengan sebenarnya (yaitu) bahwa sesungguhnya kamu pasti akan memasuki Masjidil Haram, insya Allah dalam keadaan aman, dengan mencukur rambut kepala dan mengguntingnya, sedang kamu tidak merasa takut. Maka Allah mengetahui apa yang tiada kamu ketahui dan Dia memberikan sebelum itu kemenangan yang dekat.", "manzil": 6, "manzil_display": ""}, {"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 28, "text": "هُوَ ٱلَّذِیۤ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِینِ ٱلۡحَقِّ لِیُظۡهِرَهُۥ عَلَى ٱلدِّینِ كُلِّهِۦۚ وَكَفَىٰ بِٱللَّهِ شَهِیدࣰا ۝٢٨", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "هو الذي أرسل رسوله محمدًا صلى الله عليه وسلم، بالبيان الواضح ودين الإسلام؛ ليُعْليه على الملل كلها، وحسبك -أيها الرسول- بالله شاهدًا على أنه ناصرك ومظهر دينك على كل دين.", "isBasmala": false, "translation_en": "It is He who sent His Messenger with the guidance and the religion of truth, to make it prevail over all religions. God suffices as Witness.", "translation_id": "Dialah yang mengutus Rasul-Nya dengan membawa petunjuk dan agama yang hak agar dimenangkan-Nya terhadap semua agama. Dan cukuplah Allah sebagai saksi.", "manzil": 6, "manzil_display": ""}], "515": [{"sura": 48, "sura_name": "الفتح", "revelation": "Madaniyah", "aya": 29, "text": "مُّحَمَّدࣱ رَّسُولُ ٱللَّهِۚ وَٱلَّذِینَ مَعَهُۥۤ أَشِدَّاۤءُ عَلَى ٱلۡكُفَّارِ رُحَمَاۤءُ بَیۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعࣰا سُجَّدࣰا یَبۡتَغُونَ فَضۡلࣰا مِّنَ ٱللَّهِ وَرِضۡوَ ٰنࣰاۖ سِیمَاهُمۡ فِی وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَ ٰلِكَ مَثَلُهُمۡ فِی ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ فِی ٱلۡإِنجِیلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ عَلَىٰ سُوقِهِۦ یُعۡجِبُ ٱلزُّرَّاعَ لِیَغِیظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنۡهُم مَّغۡفِرَةࣰ وَأَجۡرًا عَظِیمَۢا ۝٢٩", "juz": 26, "hizb": "(* ح 52*)", "tafsir": "محمد رسول الله، والذين معه على دينه أشداء على الكفار، رحماء فيما بينهم، تراهم ركعًا سُجَّدًا لله في صلاتهم، يرجون ربهم أن يتفضل عليهم، فيدخلهم الجنة، ويرضى عنهم، علامة طاعتهم لله ظاهرة في وجوههم من أثر السجود والعبادة، هذه صفتهم في التوراة. وصفتهم في الإنجيل كصفة زرع أخرج ساقه وفرعه، ثم تكاثرت فروعه بعد ذلك، وشدت الزرع، فقوي واستوى قائمًا على سيقانه جميلا منظره، يعجب الزُّرَّاع؛ ليَغِيظ بهؤلاء المؤمنين في كثرتهم وجمال منظرهم الكفار. وفي هذا دليل على كفر من أبغض الصحابة -رضي الله عنهم-؛ لأن من غاظه الله بالصحابة، فقد وُجد في حقه موجِب ذاك، وهو الكفر. وعد الله الذين آمنوا منهم بالله ورسوله وعملوا ما أمرهم الله به، واجتنبوا ما نهاهم عنه، مغفرة لذنوبهم، وثوابًا جزيلا لا ينقطع، وهو الجنة. (ووعد الله حق مصدَّق لا يُخْلَف، وكل من اقتفى أثر الصحابة رضي الله عنهم فهو في حكمهم في استحقاق المغفرة والأجر العظيم، ولهم الفضل والسبق والكمال الذي لا يلحقهم فيه أحد من هذه الأمة، رضي الله عنهم وأرضاهم).", "isBasmala": false, "translation_en": "Muhammad is the Messenger of God. Those with him are stern against the disbelievers, yet compassionate amongst themselves. You see them kneeling, prostrating, seeking blessings from God and approval. Their marks are on their faces from the effects of prostration. Such is their description in the Torah, and their description in the Gospel: like a plant that sprouts, becomes strong, grows thick, and rests on its stem, impressing the farmers. Through them He enrages the disbelievers. God has promised those among them who believe and do good deeds forgiveness and a great reward.", "translation_id": "Muhammad itu adalah utusan Allah dan orang-orang yang bersama dengan dia adalah keras terhadap orang-orang kafir, tetapi berkasih sayang sesama mereka. Kamu lihat mereka ruku' dan sujud mencari karunia Allah dan keridhaan-Nya, tanda-tanda mereka tampak pada muka mereka dari bekas sujud. Demikianlah sifat-sifat mereka dalam Taurat dan sifat-sifat mereka dalam Injil, yaitu seperti tanaman yang mengeluarkan tunasnya maka tunas itu menjadikan tanaman itu kuat lalu menjadi besarlah dia dan tegak lurus di atas pokoknya; tanaman itu menyenangkan hati penanam-penanamnya karena Allah hendak menjengkelkan hati orang-orang kafir (dengan kekuatan orang-orang mukmin). Allah menjanjikan kepada orang-orang yang beriman dan mengerjakan amal yang saleh di antara mereka ampunan dan pahala yang besar.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 26, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 1, "text": "۞ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُقَدِّمُوا۟ بَیۡنَ یَدَیِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِیعٌ عَلِیمࣱ ۝١", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "يا أيها الذين آمنوا بالله ورسوله لا تقضوا أمرًا دون أمر الله ورسوله من شرائع دينكم فتبتدعوا، وخافوا الله في قولكم وفعلكم أن يخالَف أمر الله ورسوله، إن الله سميع لأقوالكم، عليم بنياتكم وأفعالكم. وفي هذا تحذير للمؤمنين أن يبتدعوا في الدين، أو يشرعوا ما لم يأذن به الله.", "isBasmala": false, "translation_en": "O you who believe! Do not place your opinions above that of God and His Messenger, and fear God. God is Hearing and Knowing.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu mendahului Allah dan Rasulnya dan bertakwalah kepada Allah. Sesungguhnya Allah Maha Mendengar lagi Maha Mengetahui.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 2, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَرۡفَعُوۤا۟ أَصۡوَ ٰتَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِیِّ وَلَا تَجۡهَرُوا۟ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ أَن تَحۡبَطَ أَعۡمَـٰلُكُمۡ وَأَنتُمۡ لَا تَشۡعُرُونَ ۝٢", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا ترفعوا أصواتكم فوق صوت النبي عند مخاطبتكم له، ولا تجهروا بمناداته كما يجهر بعضكم لبعض، وميِّزوه في خطابه كما تميَّز عن غيره في اصطفائه لحمل رسالة ربه، ووجوب الإيمان به، ومحبته وطاعته والاقتداء به؛ خشية أن تبطل أعمالكم، وأنتم لا تشعرون، ولا تُحِسُّون بذلك.", "isBasmala": false, "translation_en": "O you who believe! Do not raise your voices above the voice of the Prophet, and do not speak loudly to him, as you speak loudly to one another, lest your works be in vain without you realizing.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu meninggikan suaramu melebihi suara Nabi, dan janganlah kamu berkata kepadanya dengan suara yang keras, sebagaimana kerasnya suara sebagian kamu terhadap sebagian yang lain, supaya tidak hapus (pahala) amalanmu, sedangkan kamu tidak menyadari.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 3, "text": "إِنَّ ٱلَّذِینَ یَغُضُّونَ أَصۡوَ ٰتَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ٱمۡتَحَنَ ٱللَّهُ قُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةࣱ وَأَجۡرٌ عَظِیمٌ ۝٣", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "إن الذين يَخْفِضون أصواتهم عند رسول الله أولئك الذين اختبر الله قلوبهم، وأخلصها لتقواه، لهم من الله مغفرة لذنوبهم وثواب جزيل، وهو الجنة.", "isBasmala": false, "translation_en": "Those who lower their voices before God's Messenger-those are they whose hearts God has tested for piety. They will have forgiveness and a great reward.", "translation_id": "Sesungguhnya orang yang merendahkan suaranya di sisi Rasulullah mereka itulah orang-orang yang telah diuji hati mereka oleh Allah untuk bertakwa. Bagi mereka ampunan dan pahala yang besar.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 4, "text": "إِنَّ ٱلَّذِینَ یُنَادُونَكَ مِن وَرَاۤءِ ٱلۡحُجُرَ ٰتِ أَكۡثَرُهُمۡ لَا یَعۡقِلُونَ ۝٤", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "إن الذين ينادونك -أيها النبي- من وراء حجراتك بصوت مرتفع، أكثرهم ليس لهم من العقل ما يحملهم على حسن الأدب مع رسول الله صلى الله عليه وسلَّم، وتوقيره.", "isBasmala": false, "translation_en": "Those who call you from behind the chambers-most of them do not understand.", "translation_id": "Sesungguhnya orang-orang yang memanggil kamu dari luar kamar(mu) kebanyakan mereka tidak mengerti.", "manzil": 6, "manzil_display": ""}], "516": [{"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 5, "text": "وَلَوۡ أَنَّهُمۡ صَبَرُوا۟ حَتَّىٰ تَخۡرُجَ إِلَیۡهِمۡ لَكَانَ خَیۡرࣰا لَّهُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٥", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "ولو أنهم صبروا حتى تخرج إليهم لكان خيرًا لهم عند الله؛ لأن الله قد أمرهم بتوقيرك، والله غفور لما صدر عنهم جهلا منهم من الذنوب والإخلال بالآداب، رحيم بهم حيث لم يعاجلهم بالعقوبة.", "isBasmala": false, "translation_en": "Had they remained patient until you came out to them, it would have been better for them. But God is Forgiving and Merciful.", "translation_id": "Dan kalau sekiranya mereka bersabar sampai kamu keluar menemui mereka sesungguhnya itu lebih baik bagi mereka, dan Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 6, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِن جَاۤءَكُمۡ فَاسِقُۢ بِنَبَإࣲ فَتَبَیَّنُوۤا۟ أَن تُصِیبُوا۟ قَوۡمَۢا بِجَهَـٰلَةࣲ فَتُصۡبِحُوا۟ عَلَىٰ مَا فَعَلۡتُمۡ نَـٰدِمِینَ ۝٦", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إن جاءكم فاسق بخبر فتثبَّتوا من خبره قبل تصديقه ونقله حتى تعرفوا صحته؛ خشية أن تصيبوا قومًا برآء بجناية منكم، فتندموا على ذلك.", "isBasmala": false, "translation_en": "O you who believe! If a troublemaker brings you any news, investigate, lest you harm people out of ignorance, and you become regretful for what you have done.", "translation_id": "Hai orang-orang yang beriman, jika datang kepadamu orang fasik membawa suatu berita, maka periksalah dengan teliti agar kamu tidak menimpakan suatu musibah kepada suatu kaum tanpa mengetahui keadaannya yang menyebabkan kamu menyesal atas perbuatanmu itu.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 7, "text": "وَٱعۡلَمُوۤا۟ أَنَّ فِیكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ یُطِیعُكُمۡ فِی كَثِیرࣲ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ وَلَـٰكِنَّ ٱللَّهَ حَبَّبَ إِلَیۡكُمُ ٱلۡإِیمَـٰنَ وَزَیَّنَهُۥ فِی قُلُوبِكُمۡ وَكَرَّهَ إِلَیۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡیَانَۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلرَّ ٰشِدُونَ ۝٧", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "واعلموا أن بين أظهركم رسولَ الله فتأدبوا معه؛ فإنه أعلم منكم بما يصلح لكم، يريد بكم الخير، وقد تريدون لأنفسكم من الشر والمضرة ما لا يوافقكم الرسول عليه، لو يطيعكم في كثير من الأمر مما تختارونه لأدى ذلك إلى مشقتكم، ولكن الله حبب إليكم الإيمان وحسَّنه في قلوبكم، فآمنتم، وكرَّه إليكم الكفرَ بالله والخروجَ عن طاعته، ومعصيتَه، أولئك المتصفون بهذه الصفات هم الراشدون السالكون طريق الحق.", "isBasmala": false, "translation_en": "And know that among you is the Messenger of God. Had he obeyed you in many things, you would have suffered hardship. But God has given you the love of faith, and adorned it in your hearts, and made disbelief, mischief, and rebellion hateful to you. These are the rightly guided.", "translation_id": "Dan ketahuilah olehmu bahwa di kalanganmu ada Rasulullah. Kalau ia menuruti kemauanmu dalam beberapa urusan benar-benarlah kamu mendapat kesusahan, tetapi Allah menjadikan kamu \"cinta\" kepada keimanan dan menjadikan keimanan itu indah di dalam hatimu serta menjadikan kamu benci kepada kekafiran, kefasikan, dan kedurhakaan. Mereka itulah orang-orang yang mengikuti jalan yang lurus,", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 8, "text": "فَضۡلࣰا مِّنَ ٱللَّهِ وَنِعۡمَةࣰۚ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ ۝٨", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "وهذا الخير الذي حصل لهم فضل من الله عليهم ونعمة. والله عليم بمن يشكر نعمه، حكيم في تدبير أمور خلقه.", "isBasmala": false, "translation_en": "A Grace and Favor from God. God is Knowing and Wise.", "translation_id": "sebagai karunia dan nikmat dari Allah. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 9, "text": "وَإِن طَاۤىِٕفَتَانِ مِنَ ٱلۡمُؤۡمِنِینَ ٱقۡتَتَلُوا۟ فَأَصۡلِحُوا۟ بَیۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَـٰتِلُوا۟ ٱلَّتِی تَبۡغِی حَتَّىٰ تَفِیۤءَ إِلَىٰۤ أَمۡرِ ٱللَّهِۚ فَإِن فَاۤءَتۡ فَأَصۡلِحُوا۟ بَیۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوۤا۟ۖ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُقۡسِطِینَ ۝٩", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "وإن طائفتان من أهل الإيمان اقتتلوا فأصلحوا -أيها المؤمنون- بينهما بدعوتهما إلى الاحتكام إلى كتاب الله وسنة رسوله صلى الله عليه وسلم، والرضا بحكمهما، فإن اعتدت إحدى الطائفتين وأبت الإجابة إلى ذلك، فقاتلوها حتى ترجع إلى حكم الله ورسوله، فإن رجعت فأصلحوا بينهما بالإنصاف، واعدلوا في حكمكم بأن لا تتجاوزوا في أحكامكم حكم الله وحكم رسوله، إن الله يحب العادلين في أحكامهم القاضين بين خلقه بالقسط. وفي الآية إثبات صفة المحبة لله على الحقيقة، كما يليق بجلاله سبحانه.", "isBasmala": false, "translation_en": "If two groups of believers fight each other, reconcile between them. But if one group aggresses against the other, fight the aggressing group until it complies with God's command. Once it has complied, reconcile between them with justice, and be equitable. God loves the equitable.", "translation_id": "Dan kalau ada dua golongan dari mereka yang beriman itu berperang hendaklah kamu damaikan antara keduanya! Tapi kalau yang satu melanggar perjanjian terhadap yang lain, hendaklah yang melanggar perjanjian itu kamu perangi sampai surut kembali pada perintah Allah. Kalau dia telah surut, damaikanlah antara keduanya menurut keadilan, dan hendaklah kamu berlaku adil; sesungguhnya Allah mencintai orang-orang yang berlaku adil.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 10, "text": "إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةࣱ فَأَصۡلِحُوا۟ بَیۡنَ أَخَوَیۡكُمۡۚ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ ۝١٠", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "إنما المؤمنون إخوة في الدين، فأصلحوا بين أخويكم إذا اقتتلا وخافوا الله في جميع أموركم؛ رجاء أن تُرحموا.", "isBasmala": false, "translation_en": "The believers are brothers, so reconcile between your brothers, and remain conscious of God, so that you may receive mercy.", "translation_id": "Orang-orang beriman itu sesungguhnya bersaudara. Sebab itu damaikanlah (perbaikilah hubungan) antara kedua saudaramu itu dan takutlah terhadap Allah, supaya kamu mendapat rahmat.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 11, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا یَسۡخَرۡ قَوۡمࣱ مِّن قَوۡمٍ عَسَىٰۤ أَن یَكُونُوا۟ خَیۡرࣰا مِّنۡهُمۡ وَلَا نِسَاۤءࣱ مِّن نِّسَاۤءٍ عَسَىٰۤ أَن یَكُنَّ خَیۡرࣰا مِّنۡهُنَّۖ وَلَا تَلۡمِزُوۤا۟ أَنفُسَكُمۡ وَلَا تَنَابَزُوا۟ بِٱلۡأَلۡقَـٰبِۖ بِئۡسَ ٱلِٱسۡمُ ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِیمَـٰنِۚ وَمَن لَّمۡ یَتُبۡ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ ۝١١", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشريعته لا يهزأ قوم مؤمنون من قوم مؤمنين؛ عسى أن يكون المهزوء به منهم خيرًا من الهازئين، ولا يهزأ نساء مؤمنات من نساء مؤمنات؛ عسى أن يكون المهزوء به منهنَّ خيرًا من الهازئات، ولا يَعِبْ بعضكم بعضًا، ولا يَدْعُ بعضكم بعضًا بما يكره من الألقاب، بئس الصفة والاسم الفسوق، وهو السخرية واللمز والتنابز بالألقاب، بعد ما دخلتم في الإسلام وعقلتموه، ومن لم يتب من هذه السخرية واللمز والتنابز والفسوق فأولئك هم الذين ظلموا أنفسهم بارتكاب هذه المناهي.", "isBasmala": false, "translation_en": "O you who believe! No people shall ridicule other people, for they may be better than they. Nor shall any women ridicule other women, for they may be better than they. Nor shall you slander one another, nor shall you insult one another with names. Evil is the return to wickedness after having attained faith. Whoever does not repent-these are the wrongdoers.", "translation_id": "Hai orang-orang yang beriman, janganlah sekumpulan orang laki-laki merendahkan kumpulan yang lain, boleh jadi yang ditertawakan itu lebih baik dari mereka. Dan jangan pula sekumpulan perempuan merendahkan kumpulan lainnya, boleh jadi yang direndahkan itu lebih baik. Dan janganlah suka mencela dirimu sendiri dan jangan memanggil dengan gelaran yang mengandung ejekan. Seburuk-buruk panggilan adalah (panggilan) yang buruk sesudah iman dan barangsiapa yang tidak bertobat, maka mereka itulah orang-orang yang zalim.", "manzil": 6, "manzil_display": ""}], "517": [{"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 12, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱجۡتَنِبُوا۟ كَثِیرࣰا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمࣱۖ وَلَا تَجَسَّسُوا۟ وَلَا یَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَیُحِبُّ أَحَدُكُمۡ أَن یَأۡكُلَ لَحۡمَ أَخِیهِ مَیۡتࣰا فَكَرِهۡتُمُوهُۚ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابࣱ رَّحِیمࣱ ۝١٢", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه اجتنبوا كثيرًا من ظن السوء بالمؤمنين؛ إن بعض ذلك الظن إثم، ولا تُفَتِّشوا عن عورات المسلمين، ولا يقل بعضكم في بعضٍ بظهر الغيب ما يكره. أيحب أحدكم أكل لحم أخيه وهو ميت؟ فأنتم تكرهون ذلك، فاكرهوا اغتيابه. وخافوا الله فيما أمركم به ونهاكم عنه. إن الله تواب على عباده المؤمنين، رحيم بهم.", "isBasmala": false, "translation_en": "O you who believe! Avoid most suspicion-some suspicion is sinful. And do not spy on one another, nor backbite one another. Would any of you like to eat the flesh of his dead brother? You would detest it. So remain mindful of God. God is Most Relenting, Most Merciful.", "translation_id": "Hai orang-orang yang beriman, jauhilah kebanyakan purba-sangka (kecurigaan), karena sebagian dari purba-sangka itu dosa. Dan janganlah mencari-cari keburukan orang dan janganlah menggunjingkan satu sama lain. Adakah seorang diantara kamu yang suka memakan daging saudaranya yang sudah mati? Maka tentulah kamu merasa jijik kepadanya. Dan bertakwalah kepada Allah. Sesungguhnya Allah Maha Penerima Taubat lagi Maha Penyayang.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 13, "text": "یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَـٰكُم مِّن ذَكَرࣲ وَأُنثَىٰ وَجَعَلۡنَـٰكُمۡ شُعُوبࣰا وَقَبَاۤىِٕلَ لِتَعَارَفُوۤا۟ۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِیمٌ خَبِیرࣱ ۝١٣", "juz": 26, "hizb": "(*¼ ح 52*)", "tafsir": "يا أيها الناس إنَّا خلقناكم من أب واحد هو آدم، وأُم واحدة هي حواء، فلا تفاضل بينكم في النسب، وجعلناكم بالتناسل شعوبًا وقبائل متعددة؛ ليعرف بعضكم بعضًا، إن أكرمكم عند الله أشدكم اتقاءً له. إن الله عليم بالمتقين، خبير بهم.", "isBasmala": false, "translation_en": "O people! We created you from a male and a female, and made you races and tribes, that you may know one another. The best among you in the sight of God is the most righteous. God is All-Knowing, Well-Experienced.", "translation_id": "Hai manusia, sesungguhnya Kami menciptakan kamu dari seorang laki-laki dan seorang perempuan dan menjadikan kamu berbangsa-bangsa dan bersuku-suku supaya kamu saling kenal-mengenal. Sesungguhnya orang yang paling mulia diantara kamu disisi Allah ialah orang yang paling takwa diantara kamu. Sesungguhnya Allah Maha Mengetahui lagi Maha Mengenal.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 14, "text": "۞ قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُوا۟ وَلَـٰكِن قُولُوۤا۟ أَسۡلَمۡنَا وَلَمَّا یَدۡخُلِ ٱلۡإِیمَـٰنُ فِی قُلُوبِكُمۡۖ وَإِن تُطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥ لَا یَلِتۡكُم مِّنۡ أَعۡمَـٰلِكُمۡ شَیۡـًٔاۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ ۝١٤", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "قالت الأعراب (وهم البدو): آمنا بالله ورسوله إيمانًا كاملا قل لهم -أيها النبي-: لا تدَّعوا لأنفسكم الإيمان الكامل، ولكن قولوا: أسلمنا، ولم يدخل بعدُ الإيمان في قلوبكم، وإن تطيعوا الله ورسوله لا ينقصكم من ثواب أعمالكم شيئًا. إن الله غفور لمن تاب مِن ذنوبه، رحيم به. وفي الآية زجر لمن يُظهر الإيمان، ومتابعة السنة، وأعماله تشهد بخلاف ذلك.", "isBasmala": false, "translation_en": "The Desert-Arabs say, \"We have believed.\" Say, \"You have not believed; but say, 'We have submitted,' for faith has not yet entered into your hearts. But if you obey God and His Messenger, He will not diminish any of your deeds. God is Forgiving and Merciful.\"", "translation_id": "Orang-orang Arab Badui itu berkata: \"Kami telah beriman\". Katakanlah: \"Kamu belum beriman, tapi katakanlah 'kami telah tunduk', karena iman itu belum masuk ke dalam hatimu; dan jika kamu taat kepada Allah dan Rasul-Nya, Dia tidak akan mengurangi sedikitpun pahala amalanmu; sesungguhnya Allah Maha Pengampun lagi Maha Penyayang\".", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 15, "text": "إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ یَرۡتَابُوا۟ وَجَـٰهَدُوا۟ بِأَمۡوَ ٰلِهِمۡ وَأَنفُسِهِمۡ فِی سَبِیلِ ٱللَّهِۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلصَّـٰدِقُونَ ۝١٥", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "إنما المؤمنون الذين صدَّقوا بالله وبرسوله وعملوا بشرعه، ثم لم يرتابوا في إيمانهم، وبذلوا نفائس أموالهم وأرواحهم في الجهاد في سبيل الله وطاعته ورضوانه، أولئك هم الصادقون في إيمانهم.", "isBasmala": false, "translation_en": "The believers are those who believe in God and His Messenger, and then have not doubted, and strive for God's cause with their wealth and their persons. These are the sincere.", "translation_id": "Sesungguhnya orang-orang yang beriman itu hanyalah orang-orang yang percaya (beriman) kepada Allah dan Rasul-Nya, kemudian mereka tidak ragu-ragu dan mereka berjuang (berjihad) dengan harta dan jiwa mereka pada jalan Allah. Mereka itulah orang-orang yang benar.", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 16, "text": "قُلۡ أَتُعَلِّمُونَ ٱللَّهَ بِدِینِكُمۡ وَٱللَّهُ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۚ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ ۝١٦", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "قل -أيها النبي- لهؤلاء الأعراب: أتُخَبِّرون الله بدينكم وبما في ضمائركم، والله يعلم ما في السموات وما في الأرض؟ والله بكل شيء عليم، لا يخفى عليه ما في قلوبكم من الإيمان أو الكفر، والبر أو الفجور.", "isBasmala": false, "translation_en": "Say, \"Are you going to teach God about your religion, when God knows everything in the heavens and the earth, and God is aware of all things?\"", "translation_id": "Katakanlah: \"Apakah kamu akan memberitahukan kepada Allah tentang agamamu, padahal Allah mengetahui apa yang di langit dan apa yang di bumi dan Allah Maha Mengetahui segala sesuatu?\"", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 17, "text": "یَمُنُّونَ عَلَیۡكَ أَنۡ أَسۡلَمُوا۟ۖ قُل لَّا تَمُنُّوا۟ عَلَیَّ إِسۡلَـٰمَكُمۖ بَلِ ٱللَّهُ یَمُنُّ عَلَیۡكُمۡ أَنۡ هَدَىٰكُمۡ لِلۡإِیمَـٰنِ إِن كُنتُمۡ صَـٰدِقِینَ ۝١٧", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "يَمُنُّ هؤلاء الأعراب عليك -أيها النبي- بإسلامهم ومتابعتهم ونصرتهم لك، قل لهم: لا تَمُنُّوا عليَّ دخولكم في الإسلام؛ فإنَّ نفع ذلك إنما يعود عليكم، ولله المنة عليكم فيه أنْ وفقكم للإيمان به وبرسوله، إن كنتم صادقين في إيمانكم.", "isBasmala": false, "translation_en": "They regarded it a favor to you that they have submitted. Say, \"Do not consider your submission a favor to me; it is God who has done you a favor by guiding you to the faith, if you are sincere.\"", "translation_id": "Mereka merasa telah memberi nikmat kepadamu dengan keislaman mereka. Katakanlah: \"Janganlah kamu merasa telah memberi nikmat kepadaku dengan keislamanmu, sebenarnya Allah, Dialah yang melimpahkan nikmat kepadamu dengan menunjuki kamu kepada keimanan jika kamu adalah orang-orang yang benar\".", "manzil": 6, "manzil_display": ""}, {"sura": 49, "sura_name": "الحجرات", "revelation": "Madaniyah", "aya": 18, "text": "إِنَّ ٱللَّهَ یَعۡلَمُ غَیۡبَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ بَصِیرُۢ بِمَا تَعۡمَلُونَ ۝١٨", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "إن الله يعلم غيب السموات والأرض، لا يخفى عليه شيء من ذلك، والله بصير بأعمالكم وسيجازيكم عليها، إن خيرًا فخير، وإن شرًا فشر.", "isBasmala": false, "translation_en": "God knows the secrets of the heavens and the earth, and God is seeing of everything you do.", "translation_id": "Sesungguhnya Allah mengetahui apa yang ghaib di langit dan bumi. Dan Allah Maha Melihat apa yang kamu kerjakan.", "manzil": 6, "manzil_display": ""}], "518": [{"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 26, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 1, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 1, "text": "قۤۚ وَٱلۡقُرۡءَانِ ٱلۡمَجِیدِ ۝١", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "(ق) سبق الكلام على الحروف المقطَّعة في أول سورة البقرة. أقسم الله تعالى بالقرآن الكريم ذي المجد والشرف.", "isBasmala": false, "translation_en": "Qaf. By the Glorious Quran.", "translation_id": "Qaaf Demi Al Quran yang sangat mulia.", "manzil": 7, "manzil_display": "المنزل السابع (م ق 7)"}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 2, "text": "بَلۡ عَجِبُوۤا۟ أَن جَاۤءَهُم مُّنذِرࣱ مِّنۡهُمۡ فَقَالَ ٱلۡكَـٰفِرُونَ هَـٰذَا شَیۡءٌ عَجِیبٌ ۝٢", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "بل عجب المكذبون للرسول صلى الله عليه وسلم أن جاءهم منذر منهم ينذرهم عقاب الله، فقال الكافرون بالله ورسوله: هذا شيء مستغرب يتعجب منه.", "isBasmala": false, "translation_en": "They marveled that a warner has come to them from among them. The disbelievers say, \"This is something strange.", "translation_id": "(Mereka tidak menerimanya) bahkan mereka tercengang karena telah datang kepada mereka seorang pemberi peringatan dari (kalangan) mereka sendiri, maka berkatalah orang-orang kafir: \"Ini adalah suatu yang amat ajaib\".", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 3, "text": "أَءِذَا مِتۡنَا وَكُنَّا تُرَابࣰاۖ ذَ ٰلِكَ رَجۡعُۢ بَعِیدࣱ ۝٣", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "أإذا متنا وصِرْنا ترابًا، كيف يمكن الرجوع بعد ذلك إلى ما كنا عليه؟ ذلك رجع بعيد الوقوع.", "isBasmala": false, "translation_en": "When we have died and become dust? This is a farfetched return.\"", "translation_id": "Apakah kami setelah mati dan setelah menjadi tanah (kami akan kembali lagi)?, itu adalah suatu pengembalian yang tidak mungkin.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 4, "text": "قَدۡ عَلِمۡنَا مَا تَنقُصُ ٱلۡأَرۡضُ مِنۡهُمۡۖ وَعِندَنَا كِتَـٰبٌ حَفِیظُۢ ۝٤", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "قد علمنا ما تنقص الأرض وتُفني من أجسامهم، وعندنا كتاب محفوظ من التغيير والتبديل، بكل ما يجري عليهم في حياتهم وبعد مماتهم.", "isBasmala": false, "translation_en": "We know what the earth consumes of them, and with Us is a comprehensive book.", "translation_id": "Sesungguhnya Kami telah mengetahui apa yang dihancurkan oleh bumi dari (tubuh-tubuh) mereka, dan pada sisi Kamipun ada kitab yang memelihara (mencatat).", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 5, "text": "بَلۡ كَذَّبُوا۟ بِٱلۡحَقِّ لَمَّا جَاۤءَهُمۡ فَهُمۡ فِیۤ أَمۡرࣲ مَّرِیجٍ ۝٥", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "بل كذَّب هؤلاء المشركون بالقرآن حين جاءهم، فهم في أمر مضطرب مختلط، لا يثبتون على شيء، ولا يستقر لهم قرار.", "isBasmala": false, "translation_en": "But they denied the truth when it has come to them, so they are in a confused state.", "translation_id": "Sebenarnya, mereka telah mendustakan kebenaran tatkala kebenaran itu datang kepada mereka, maka mereka berada dalam keadaan kacau balau.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 6, "text": "أَفَلَمۡ یَنظُرُوۤا۟ إِلَى ٱلسَّمَاۤءِ فَوۡقَهُمۡ كَیۡفَ بَنَیۡنَـٰهَا وَزَیَّنَّـٰهَا وَمَا لَهَا مِن فُرُوجࣲ ۝٦", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "أغَفَلوا حين كفروا بالبعث، فلم ينظروا إلى السماء فوقهم، كيف بنيناها مستوية الأرجاء، ثابتة البناء، وزيناها بالنجوم، وما لها من شقوق وفتوق، فهي سليمة من التفاوت والعيوب؟", "isBasmala": false, "translation_en": "Have they not observed the sky above them, how We constructed it, and decorated it, and it has no cracks?", "translation_id": "Maka apakah mereka tidak melihat akan langit yang ada di atas mereka, bagaimana Kami meninggikannya dan menghiasinya dan langit itu tidak mempunyai retak-retak sedikitpun?", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 7, "text": "وَٱلۡأَرۡضَ مَدَدۡنَـٰهَا وَأَلۡقَیۡنَا فِیهَا رَوَ ٰسِیَ وَأَنۢبَتۡنَا فِیهَا مِن كُلِّ زَوۡجِۭ بَهِیجࣲ ۝٧", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "والأرض وسَّعْناها وفرشناها، وجعلنا فيها جبالا ثوابت؛ لئلا تميل بأهلها، وأنبتنا فيها من كل نوع حسن المنظر نافع، يَسُرُّ ويبهج الناظر إليه.", "isBasmala": false, "translation_en": "And the earth, how We spread it out, and set on it mountains, and grew in it all kinds of delightful pairs?", "translation_id": "Dan Kami hamparkan bumi itu dan Kami letakkan padanya gunung-gunung yang kokoh dan Kami tumbuhkan padanya segala macam tanaman yang indah dipandang mata,", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 8, "text": "تَبۡصِرَةࣰ وَذِكۡرَىٰ لِكُلِّ عَبۡدࣲ مُّنِیبࣲ ۝٨", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "خلق الله السموات والأرض وما فيهما من الآيات العظيمة عبرة يُتبصر بها مِن عمى الجهل، وذكرى لكل عبد خاضع خائف وَجِل، رجَّاع إلى الله عز وجل.", "isBasmala": false, "translation_en": "A lesson and a reminder for every penitent worshiper.", "translation_id": "untuk menjadi pelajaran dan peringatan bagi tiap-tiap hamba yang kembali (mengingat Allah).", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 9, "text": "وَنَزَّلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ مُّبَـٰرَكࣰا فَأَنۢبَتۡنَا بِهِۦ جَنَّـٰتࣲ وَحَبَّ ٱلۡحَصِیدِ ۝٩", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "ونزَّلنا من السماء مطرًا كثير المنافع، فأنبتنا به بساتين كثيرة الأشجار، وحب الزرع المحصود.", "isBasmala": false, "translation_en": "And We brought down from the sky blessed water, and produced with it gardens and grain to harvest.", "translation_id": "Dan Kami turunkan dari langit air yang banyak manfaatnya lalu Kami tumbuhkan dengan air itu pohon-pohon dan biji-biji tanaman yang diketam,", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 10, "text": "وَٱلنَّخۡلَ بَاسِقَـٰتࣲ لَّهَا طَلۡعࣱ نَّضِیدࣱ ۝١٠", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "وأنبتنا النخل طِوالا لها طلع متراكب بعضه فوق بعضٍ.", "isBasmala": false, "translation_en": "And the soaring palm trees, with clustered dates.", "translation_id": "dan pohon kurma yang tinggi-tinggi yang mempunyai mayang yang bersusun-susun,", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 11, "text": "رِّزۡقࣰا لِّلۡعِبَادِۖ وَأَحۡیَیۡنَا بِهِۦ بَلۡدَةࣰ مَّیۡتࣰاۚ كَذَ ٰلِكَ ٱلۡخُرُوجُ ۝١١", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "أنبتنا ذلك رزقًا للعباد يقتاتون به حسب حاجاتهم، وأحيينا بهذا الماء الذي أنزلناه من السماء بلدة قد أجدبت وقحطت، فلا زرع فيها ولا نبات، كما أحيينا بذلك الماء الأرض الميتة نخرجكم يوم القيامة أحياء بعد الموت.", "isBasmala": false, "translation_en": "As sustenance for the servants. And We revive thereby a dead town. Likewise is the resurrection.", "translation_id": "untuk menjadi rezeki bagi hamba-hamba (Kami), dan Kami hidupkan dengan air itu tanah yang mati (kering). Seperti itulah terjadinya kebangkitan.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 12, "text": "كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَأَصۡحَـٰبُ ٱلرَّسِّ وَثَمُودُ ۝١٢", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "كذَّبت قبل هؤلاء المشركين من قريش قومُ نوح وأصحاب البئر وثمود، وعاد وفرعون وقوم لوط، وأصحاب الأيكة قومُ شعيب، وقوم تُبَّع الحِمْيَري، كل هؤلاء الأقوام كذَّبوا رسلهم، فحق عليهم الوعيد الذي توعدهم الله به على كفرهم.", "isBasmala": false, "translation_en": "Before them the people of Noah denied the truth, and so did the dwellers of Russ, and Thamood.", "translation_id": "Sebelum mereka telah mendustakan (pula) kaum Nuh dan penduduk Rass dan Tsamud,", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 13, "text": "وَعَادࣱ وَفِرۡعَوۡنُ وَإِخۡوَ ٰنُ لُوطࣲ ۝١٣", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "كذَّبت قبل هؤلاء المشركين من قريش قومُ نوح وأصحاب البئر وثمود، وعاد وفرعون وقوم لوط، وأصحاب الأيكة قومُ شعيب، وقوم تُبَّع الحِمْيَري، كل هؤلاء الأقوام كذَّبوا رسلهم، فحق عليهم الوعيد الذي توعدهم الله به على كفرهم.", "isBasmala": false, "translation_en": "And Aad, and Pharaoh, and the brethren of Lot.", "translation_id": "dan kaum Aad, kaum Fir'aun dan kaum Luth,", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 14, "text": "وَأَصۡحَـٰبُ ٱلۡأَیۡكَةِ وَقَوۡمُ تُبَّعࣲۚ كُلࣱّ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِیدِ ۝١٤", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "كذَّبت قبل هؤلاء المشركين من قريش قومُ نوح وأصحاب البئر وثمود، وعاد وفرعون وقوم لوط، وأصحاب الأيكة قومُ شعيب، وقوم تُبَّع الحِمْيَري، كل هؤلاء الأقوام كذَّبوا رسلهم، فحق عليهم الوعيد الذي توعدهم الله به على كفرهم.", "isBasmala": false, "translation_en": "And the Dwellers of the Woods, and the people of Tubba. They all rejected the messengers, so My threat came true.", "translation_id": "dan penduduk Aikah serta kaum Tubba' semuanya telah mendustakan rasul-rasul maka sudah semestinyalah mereka mendapat hukuman yang sudah diancamkan.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 15, "text": "أَفَعَیِینَا بِٱلۡخَلۡقِ ٱلۡأَوَّلِۚ بَلۡ هُمۡ فِی لَبۡسࣲ مِّنۡ خَلۡقࣲ جَدِیدࣲ ۝١٥", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "أفَعَجَزْنا عن ابتداع الخلق الأول الذي خلقناه ولم يكن شيئًا، فنعجز عن إعادتهم خلقًا جديدًا بعد فنائهم؟ لا يعجزنا ذلك، بل نحن عليه قادرون، ولكنهم في حَيْرة وشك من أمر البعث والنشور.", "isBasmala": false, "translation_en": "Were We fatigued by the first creation? But they are in doubt of a new creation.", "translation_id": "Maka apakah Kami letih dengan penciptaan yang pertama? Sebenarnya mereka dalam keadaan ragu-ragu tentang penciptaan yang baru.", "manzil": 7, "manzil_display": ""}], "519": [{"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 16, "text": "وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَیۡهِ مِنۡ حَبۡلِ ٱلۡوَرِیدِ ۝١٦", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "ولقد خلقنا الإنسان، ونعلم ما تُحَدِّث به نفسه، ونحن أقرب إليه من حبل الوريد (وهو عِرْق في العنق متصل بالقلب).", "isBasmala": false, "translation_en": "We created the human being, and We know what his soul whispers to him. We are nearer to him than his jugular vein.", "translation_id": "Dan sesungguhnya Kami telah menciptakan manusia dan mengetahui apa yang dibisikkan oleh hatinya, dan Kami lebih dekat kepadanya daripada urat lehernya,", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 17, "text": "إِذۡ یَتَلَقَّى ٱلۡمُتَلَقِّیَانِ عَنِ ٱلۡیَمِینِ وَعَنِ ٱلشِّمَالِ قَعِیدࣱ ۝١٧", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "حين يكتب المَلَكان المترصدان عن يمينه وعن شماله أعماله. فالذي عن اليمين يكتب الحسنات، والذي عن الشمال يكتب السيئات.", "isBasmala": false, "translation_en": "As the two receivers receive, seated to the right and to the left.", "translation_id": "(yaitu) ketika dua orang malaikat mencatat amal perbuatannya, seorang duduk di sebelah kanan dan yang lain duduk di sebelah kiri.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 18, "text": "مَّا یَلۡفِظُ مِن قَوۡلٍ إِلَّا لَدَیۡهِ رَقِیبٌ عَتِیدࣱ ۝١٨", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "ما يلفظ من قول فيتكلم به إلا لديه مَلَك يرقب قوله، ويكتبه، وهو مَلَك حاضر مُعَدٌّ لذلك.", "isBasmala": false, "translation_en": "Not a word does he utter, but there is a watcher by him, ready.", "translation_id": "Tiada suatu ucapanpun yang diucapkannya melainkan ada di dekatnya malaikat pengawas yang selalu hadir.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 19, "text": "وَجَاۤءَتۡ سَكۡرَةُ ٱلۡمَوۡتِ بِٱلۡحَقِّۖ ذَ ٰلِكَ مَا كُنتَ مِنۡهُ تَحِیدُ ۝١٩", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "وجاءت شدة الموت وغَمْرته بالحق الذي لا مردَّ له ولا مناص، ذلك ما كنت منه - أيها الإنسان - تهرب وتروغ.", "isBasmala": false, "translation_en": "The daze of death has come in truth: \"This is what you tried to evade.\"", "translation_id": "Dan datanglah sakaratul maut dengan sebenar-benarnya. Itulah yang kamu selalu lari daripadanya.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 20, "text": "وَنُفِخَ فِی ٱلصُّورِۚ ذَ ٰلِكَ یَوۡمُ ٱلۡوَعِیدِ ۝٢٠", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "ونُفخ في \"القرن\" نفخة البعث الثانية، ذلك النفخ في يوم وقوع الوعيد الذي توعَّد الله به الكفار.", "isBasmala": false, "translation_en": "And the Trumpet is blown: \"This is the Promised Day.\"", "translation_id": "Dan ditiuplah sangkakala. Itulah hari terlaksananya ancaman.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 21, "text": "وَجَاۤءَتۡ كُلُّ نَفۡسࣲ مَّعَهَا سَاۤىِٕقࣱ وَشَهِیدࣱ ۝٢١", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "وجاءت كل نفس معها مَلَكان، أحدهما يسوقها إلى المحشر، والآخر يشهد عليها بما عملت في الدنيا من خير وشر.", "isBasmala": false, "translation_en": "And every soul will come forward, accompanied by a driver and a witness.", "translation_id": "Dan datanglah tiap-tiap diri, bersama dengan dia seorang malaikat penggiring dan seorang malaikat penyaksi.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 22, "text": "لَّقَدۡ كُنتَ فِی غَفۡلَةࣲ مِّنۡ هَـٰذَا فَكَشَفۡنَا عَنكَ غِطَاۤءَكَ فَبَصَرُكَ ٱلۡیَوۡمَ حَدِیدࣱ ۝٢٢", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "لقد كنت في غفلة من هذا الذي عاينت اليوم أيها الإنسان، فكشفنا عنك غطاءك الذي غطَّى قلبك، فزالت الغفلة عنك، فبصرك اليوم فيما تشهد قوي شديد.", "isBasmala": false, "translation_en": "\"You were in neglect of this, so We lifted your screen from you, and your vision today is keen.\"", "translation_id": "Sesungguhnya kamu berada dalam keadaan lalai dari (hal) ini, maka Kami singkapkan daripadamu tutup (yang menutupi) matamu, maka penglihatanmu pada hari itu amat tajam.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 23, "text": "وَقَالَ قَرِینُهُۥ هَـٰذَا مَا لَدَیَّ عَتِیدٌ ۝٢٣", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "وقال المَلَك الكاتب الشهيد عليه: هذا ما عندي من ديوان عمله، وهو لديَّ مُعَدٌّ محفوظ حاضر.", "isBasmala": false, "translation_en": "And His escort will say, \"This is what I have ready with me.\"", "translation_id": "Dan yang menyertai dia berkata: \"Inilah (catatan amalnya) yang tersedia pada sisiku\".", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 24, "text": "أَلۡقِیَا فِی جَهَنَّمَ كُلَّ كَفَّارٍ عَنِیدࣲ ۝٢٤", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "يقول الله للمَلَكين السائق والشهيد بعد أن يفصل بين الخلائق: ألقيا في جهنم كل جاحد أن الله هو الإلهُ الحقُّ، كثيرِ الكفر والتكذيب معاند للحق، منَّاع لأداء ما عليه من الحقوق في ماله، مُعْتدٍ على عباد الله وعلى حدوده، شاكٍّ في وعده ووعيده، الذي أشرك بالله، فعبد معه معبودًا آخر مِن خلقه، فألقياه في عذاب جهنم الشديد.", "isBasmala": false, "translation_en": "\"Throw into Hell every stubborn disbeliever.", "translation_id": "Allah berfirman: \"Lemparkanlah olehmu berdua ke dalam neraka semua orang yang sangat ingkar dan keras kepala,", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 25, "text": "مَّنَّاعࣲ لِّلۡخَیۡرِ مُعۡتَدࣲ مُّرِیبٍ ۝٢٥", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "يقول الله للمَلَكين السائق والشهيد بعد أن يفصل بين الخلائق: ألقيا في جهنم كل جاحد أن الله هو الإلهُ الحقُّ، كثيرِ الكفر والتكذيب معاند للحق، منَّاع لأداء ما عليه من الحقوق في ماله، مُعْتدٍ على عباد الله وعلى حدوده، شاكٍّ في وعده ووعيده، الذي أشرك بالله، فعبد معه معبودًا آخر مِن خلقه، فألقياه في عذاب جهنم الشديد.", "isBasmala": false, "translation_en": "Preventer of good, aggressor, doubter.", "translation_id": "yang sangat menghalangi kebajikan, melanggar batas lagi ragu-ragu,", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 26, "text": "ٱلَّذِی جَعَلَ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَأَلۡقِیَاهُ فِی ٱلۡعَذَابِ ٱلشَّدِیدِ ۝٢٦", "juz": 26, "hizb": "(*½ ح 52*)", "tafsir": "يقول الله للمَلَكين السائق والشهيد بعد أن يفصل بين الخلائق: ألقيا في جهنم كل جاحد أن الله هو الإلهُ الحقُّ، كثيرِ الكفر والتكذيب معاند للحق، منَّاع لأداء ما عليه من الحقوق في ماله، مُعْتدٍ على عباد الله وعلى حدوده، شاكٍّ في وعده ووعيده، الذي أشرك بالله، فعبد معه معبودًا آخر مِن خلقه، فألقياه في عذاب جهنم الشديد.", "isBasmala": false, "translation_en": "Who fabricated another god with God; toss him into the intense agony.\"", "translation_id": "yang menyembah sembahan yang lain beserta Allah maka lemparkanlah dia ke dalam siksaan yang sangat\".", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 27, "text": "۞ قَالَ قَرِینُهُۥ رَبَّنَا مَاۤ أَطۡغَیۡتُهُۥ وَلَـٰكِن كَانَ فِی ضَلَـٰلِۭ بَعِیدࣲ ۝٢٧", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "قال شيطانه الذي كان معه في الدنيا: ربنا ما أضللته، ولكن كان في طريق بعيد عن سبيل الهدى.", "isBasmala": false, "translation_en": "His escort will say, \"Our Lord, I did not make him rebel, but he was far astray.\"", "translation_id": "Yang menyertai dia berkata (pula): \"Ya Tuhan kami, aku tidak menyesatkannya tetapi dialah yang berada dalam kesesatan yang jauh\".", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 28, "text": "قَالَ لَا تَخۡتَصِمُوا۟ لَدَیَّ وَقَدۡ قَدَّمۡتُ إِلَیۡكُم بِٱلۡوَعِیدِ ۝٢٨", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "قال الله تعالى: لا تختصموا لديَّ اليوم في موقف الجزاء والحساب؛ إذ لا فائدة من ذلك، وقد قَدَّمْتُ إليكم في الدنيا بالوعيد لمن كفر بي وعصاني.", "isBasmala": false, "translation_en": "He will say, \"Do not feud in My presence-I had warned you in advance.", "translation_id": "Allah berfirman: \"Janganlah kamu bertengkar di hadapan-Ku, padahal sesungguhnya Aku dahulu telah memberikan ancaman kepadamu\".", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 29, "text": "مَا یُبَدَّلُ ٱلۡقَوۡلُ لَدَیَّ وَمَاۤ أَنَا۠ بِظَلَّـٰمࣲ لِّلۡعَبِیدِ ۝٢٩", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "ما يُغيَّر القول لديَّ، ولست أعذِّب أحدًا بذنب أحد، فلا أعذِّب أحدًا إلا بذنبه بعد قيام الحجة عليه.", "isBasmala": false, "translation_en": "The decree from Me will not be changed, and I am not unjust to the servants.\"", "translation_id": "Keputusan di sisi-Ku tidak dapat diubah dan Aku sekali-kali tidak menganiaya hamba-hamba-Ku", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 30, "text": "یَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِیدࣲ ۝٣٠", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "اذكر -أيها الرسول- لقومك يوم نقول لجهنم يوم القيامة: هل امتلأت؟ وتقول جهنم: هل من زيادة من الجن والإنس؟ فيضع الرب -جل جلاله- قدمه فيها، فينزوي بعضها على بعض، وتقول: قط، قط.", "isBasmala": false, "translation_en": "On the Day when We will say to Hell, \"Are you full?\" And it will say, \"Are there any more?\"", "translation_id": "(Dan ingatlah akan) hari (yang pada hari itu) Kami bertanya kepada jahannam: \"Apakah kamu sudah penuh?\" Dia menjawab: \"Masih ada tambahan?\"", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 31, "text": "وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِینَ غَیۡرَ بَعِیدٍ ۝٣١", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "وقُرِّبت الجنة للمتقين مكانًا غير بعيد منهم، فهم يشاهدونها زيادة في المسرَّة لهم.", "isBasmala": false, "translation_en": "And Paradise will be brought closer to the pious, not far away.", "translation_id": "Dan didekatkanlah surga itu kepada orang-orang yang bertakwa pada tempat yang tiada jauh (dari mereka).", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 32, "text": "هَـٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِیظࣲ ۝٣٢", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "يقال لهم: هذا الذي كنتم توعدون به - أيها المتقون - لكل تائب مِن ذنوبه، حافظ لكل ما قَرَّبه إلى ربه، من الفرائض والطاعات، مَن خاف الله في الدنيا ولقيه يوم القيامة بقلب تائب من ذنوبه.", "isBasmala": false, "translation_en": "\"This is what you were promised-for every careful penitent.", "translation_id": "Inilah yang dijanjikan kepadamu, (yaitu) kepada setiap hamba yang selalu kembali (kepada Allah) lagi memelihara (semua peraturan-peraturan-Nya)", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 33, "text": "مَّنۡ خَشِیَ ٱلرَّحۡمَـٰنَ بِٱلۡغَیۡبِ وَجَاۤءَ بِقَلۡبࣲ مُّنِیبٍ ۝٣٣", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "يقال لهم: هذا الذي كنتم توعدون به - أيها المتقون - لكل تائب مِن ذنوبه، حافظ لكل ما قَرَّبه إلى ربه، من الفرائض والطاعات، مَن خاف الله في الدنيا ولقيه يوم القيامة بقلب تائب من ذنوبه.", "isBasmala": false, "translation_en": "Who inwardly feared the Most Gracious, and came with a repentant heart.", "translation_id": "(Yaitu) orang yang takut kepada Tuhan Yang Maha Pemurah sedang Dia tidak kelihatan (olehnya) dan dia datang dengan hati yang bertaubat,", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 34, "text": "ٱدۡخُلُوهَا بِسَلَـٰمࣲۖ ذَ ٰلِكَ یَوۡمُ ٱلۡخُلُودِ ۝٣٤", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "ويقال لهؤلاء المؤمنين: ادخلوا الجنة دخولا مقرونًا بالسلامة من الآفات والشرور، مأمونًا فيه جميع المكاره، ذلك هو يوم الخلود بلا انقطاع.", "isBasmala": false, "translation_en": "Enter it in peace. This is the Day of Eternity.\"", "translation_id": "masukilah surga itu dengan aman, itulah hari kekekalan.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 35, "text": "لَهُم مَّا یَشَاۤءُونَ فِیهَا وَلَدَیۡنَا مَزِیدࣱ ۝٣٥", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "لهؤلاء المؤمنين في الجنة ما يريدون، ولدينا على ما أعطيناهم زيادة نعيم، أعظَمُه النظر إلى وجه الله الكريم.", "isBasmala": false, "translation_en": "Therein they will have whatever they desire-and We have even more.", "translation_id": "Mereka di dalamnya memperoleh apa yang mereka kehendaki; dan pada sisi Kami ada tambahannya.", "manzil": 7, "manzil_display": ""}], "520": [{"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 36, "text": "وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَشَدُّ مِنۡهُم بَطۡشࣰا فَنَقَّبُوا۟ فِی ٱلۡبِلَـٰدِ هَلۡ مِن مَّحِیصٍ ۝٣٦", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "وأهلكنا قبل هؤلاء المشركين من قريش أممًا كثيرة، كانوا أشد منهم قوة وسطوة، فطوَّفوا في البلاد وعمَّروا ودمَّروا فيها، هل من مهرب من عذاب الله حين جاءهم؟", "isBasmala": false, "translation_en": "How many generations before them, who were more powerful than they, did We destroy? They explored the lands-was there any escape?", "translation_id": "Dan berapa banyaknya umat-umat yang telah Kami binasakan sebelum mereka yang mereka itu lebih besar kekuatannya daripada mereka ini, maka mereka (yang telah dibinasakan itu) telah pernah menjelajah di beberapa negeri. Adakah (mereka) mendapat tempat lari (dari kebinasaan)?", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 37, "text": "إِنَّ فِی ذَ ٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِیدࣱ ۝٣٧", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "إن في إهلاك القرون الماضية لعبرة لمن كان له قلب يعقل به، أو أصغى السمع، وهو حاضر بقلبه، غير غافل ولا ساهٍ.", "isBasmala": false, "translation_en": "In that is a reminder for whoever possesses a heart, or cares to listen and witness.", "translation_id": "Sesungguhnya pada yang demikian itu benar-benar terdapat peringatan bagi orang-orang yang mempunyai akal atau yang menggunakan pendengarannya, sedang dia menyaksikannya.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 38, "text": "وَلَقَدۡ خَلَقۡنَا ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا فِی سِتَّةِ أَیَّامࣲ وَمَا مَسَّنَا مِن لُّغُوبࣲ ۝٣٨", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "ولقد خلقنا السموات السبع والأرض وما بينهما من أصناف المخلوقات في ستة أيام، وما أصابنا من ذلك الخلق تعب ولا نَصَب. وفي هذه القدرة العظيمة دليل على قدرته -سبحانه - على إحياء الموتى من باب أولى.", "isBasmala": false, "translation_en": "We created the heavens and the earth and what is between them in six days, and no fatigue touched Us.", "translation_id": "Dan sesungguhnya telah Kami ciptakan langit dan bumi dan apa yang ada antara keduanya dalam enam masa, dan Kami sedikitpun tidak ditimpa keletihan.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 39, "text": "فَٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ ۝٣٩", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "فاصبر -أيها الرسول- على ما يقوله المكذبون، فإن الله لهم بالمرصاد، وصلِّ لربك حامدًا له صلاة الصبح قبل طلوع الشمس وصلاة العصر قبل الغروب، وصلِّ من الليل، وسبِّحْ بحمد ربك عقب الصلوات.", "isBasmala": false, "translation_en": "So endure what they say, and proclaim the praises of your Lord before the rising of the sun, and before sunset.", "translation_id": "Maka bersabarlah kamu terhadap apa yang mereka katakan dan bertasbihlah sambil memuji Tuhanmu sebelum terbit matahari dan sebelum terbenam(nya).", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 40, "text": "وَمِنَ ٱلَّیۡلِ فَسَبِّحۡهُ وَأَدۡبَـٰرَ ٱلسُّجُودِ ۝٤٠", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "فاصبر -أيها الرسول- على ما يقوله المكذبون، فإن الله لهم بالمرصاد، وصلِّ لربك حامدًا له صلاة الصبح قبل طلوع الشمس وصلاة العصر قبل الغروب، وصلِّ من الليل، وسبِّحْ بحمد ربك عقب الصلوات.", "isBasmala": false, "translation_en": "And glorify Him during the night, and at the end of devotions.", "translation_id": "Dan bertasbihlah kamu kepada-Nya di malam hari dan setiap selesai sembahyang.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 41, "text": "وَٱسۡتَمِعۡ یَوۡمَ یُنَادِ ٱلۡمُنَادِ مِن مَّكَانࣲ قَرِیبࣲ ۝٤١", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "واستمع -أيها الرسول- يوم ينادي المَلَك بنفخه في \"القرن\" من مكان قريب، يوم يسمعون صيحة البعث بالحق الذي لا شك فيه ولا امتراء، ذلك يوم خروج أهل القبور من قبورهم.", "isBasmala": false, "translation_en": "And listen for the Day when the caller calls from a nearby place.", "translation_id": "Dan dengarkanlah (seruan) pada hari penyeru (malaikat) menyeru dari tempat yang dekat.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 42, "text": "یَوۡمَ یَسۡمَعُونَ ٱلصَّیۡحَةَ بِٱلۡحَقِّۚ ذَ ٰلِكَ یَوۡمُ ٱلۡخُرُوجِ ۝٤٢", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "واستمع -أيها الرسول- يوم ينادي المَلَك بنفخه في \"القرن\" من مكان قريب، يوم يسمعون صيحة البعث بالحق الذي لا شك فيه ولا امتراء، ذلك يوم خروج أهل القبور من قبورهم.", "isBasmala": false, "translation_en": "The Day when they will hear the Shout in all truth. That is the Day of Emergence.", "translation_id": "(Yaitu) pada hari mereka mendengar teriakan dengan sebenar-benarnya itulah hari ke luar (dari kubur).", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 43, "text": "إِنَّا نَحۡنُ نُحۡیِۦ وَنُمِیتُ وَإِلَیۡنَا ٱلۡمَصِیرُ ۝٤٣", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "إنَّا نحن نحيي الخلق ونميتهم في الدنيا، وإلينا مصيرهم جميعًا يوم القيامة للحساب والجزاء، يوم تتصدع الأرض عن الموتى المقبورين بها، فيخرجون مسرعين إلى الداعي، ذلك الجمع في موقف الحساب علينا سهل يسير.", "isBasmala": false, "translation_en": "It is We who control life and death, and to Us is the destination.", "translation_id": "Sesungguhnya Kami menghidupkan dan mematikan dan hanya kepada Kami-lah tempat kembali (semua makhluk).", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 44, "text": "یَوۡمَ تَشَقَّقُ ٱلۡأَرۡضُ عَنۡهُمۡ سِرَاعࣰاۚ ذَ ٰلِكَ حَشۡرٌ عَلَیۡنَا یَسِیرࣱ ۝٤٤", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "إنَّا نحن نحيي الخلق ونميتهم في الدنيا، وإلينا مصيرهم جميعًا يوم القيامة للحساب والجزاء، يوم تتصدع الأرض عن الموتى المقبورين بها، فيخرجون مسرعين إلى الداعي، ذلك الجمع في موقف الحساب علينا سهل يسير.", "isBasmala": false, "translation_en": "The Day when the earth will crack for them at once. That is an easy gathering for Us.", "translation_id": "(Yaitu) pada hari bumi terbelah-belah menampakkan mereka (lalu mereka ke luar) dengan cepat. Yang demikian itu adalah pengumpulan yang mudah bagi Kami.", "manzil": 7, "manzil_display": ""}, {"sura": 50, "sura_name": "ق", "revelation": "Makkiyah", "aya": 45, "text": "نَّحۡنُ أَعۡلَمُ بِمَا یَقُولُونَۖ وَمَاۤ أَنتَ عَلَیۡهِم بِجَبَّارࣲۖ فَذَكِّرۡ بِٱلۡقُرۡءَانِ مَن یَخَافُ وَعِیدِ ۝٤٥", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "نحن أعلم بما يقول هؤلاء المشركون مِن افتراء على الله وتكذيب بآياته، وما أنت -أيها الرسول- عليهم بمسلَّط؛ لتجبرهم على الإسلام، وإنما بُعِثْتَ مبلِّغًا، فذكِّر بالقرآن من يخشى وعيدي؛ لأن مَن لا يخاف الوعيد لا يذَّكر.", "isBasmala": false, "translation_en": "We are fully aware of what they say, and you are not a dictator over them. So remind by the Quran whoever fears My warning.", "translation_id": "Kami lebih mengetahui tentang apa yang mereka katakan, dan kamu sekali-kali bukanlah seorang pemaksa terhadap mereka. Maka beri peringatanlah dengan Al Quran orang yang takut dengan ancaman-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 27, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلذَّ ٰرِیَـٰتِ ذَرۡوࣰا ۝١", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "أقسم الله تعالى بالرياح المثيرات للتراب، فالسحب الحاملات ثقلا عظيمًا من الماء، فالسفن التي تجري في البحار جريًا ذا يسر وسهولة، فالملائكة التي تُقَسِّم أمر الله في خلقه. إن الذي توعدون به- أيها الناس- من البعث والحساب لكائن حق يقين، وإن الحساب والثواب على الأعمال لكائن لا محالة.", "isBasmala": false, "translation_en": "By the spreaders spreading.", "translation_id": "Demi (angin) yang menerbangkan debu dengan kuat.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 2, "text": "فَٱلۡحَـٰمِلَـٰتِ وِقۡرࣰا ۝٢", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "أقسم الله تعالى بالرياح المثيرات للتراب، فالسحب الحاملات ثقلا عظيمًا من الماء، فالسفن التي تجري في البحار جريًا ذا يسر وسهولة، فالملائكة التي تُقَسِّم أمر الله في خلقه. إن الذي توعدون به- أيها الناس- من البعث والحساب لكائن حق يقين، وإن الحساب والثواب على الأعمال لكائن لا محالة.", "isBasmala": false, "translation_en": "And those carrying loads.", "translation_id": "dan awan yang mengandung hujan,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 3, "text": "فَٱلۡجَـٰرِیَـٰتِ یُسۡرࣰا ۝٣", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "أقسم الله تعالى بالرياح المثيرات للتراب، فالسحب الحاملات ثقلا عظيمًا من الماء، فالسفن التي تجري في البحار جريًا ذا يسر وسهولة، فالملائكة التي تُقَسِّم أمر الله في خلقه. إن الذي توعدون به- أيها الناس- من البعث والحساب لكائن حق يقين، وإن الحساب والثواب على الأعمال لكائن لا محالة.", "isBasmala": false, "translation_en": "And those moving gently.", "translation_id": "dan kapal-kapal yang berlayar dengan mudah.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 4, "text": "فَٱلۡمُقَسِّمَـٰتِ أَمۡرًا ۝٤", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "أقسم الله تعالى بالرياح المثيرات للتراب، فالسحب الحاملات ثقلا عظيمًا من الماء، فالسفن التي تجري في البحار جريًا ذا يسر وسهولة، فالملائكة التي تُقَسِّم أمر الله في خلقه. إن الذي توعدون به- أيها الناس- من البعث والحساب لكائن حق يقين، وإن الحساب والثواب على الأعمال لكائن لا محالة.", "isBasmala": false, "translation_en": "And those distributing as commanded.", "translation_id": "dan (malaikat-malaikat) yang membagi-bagi urusan,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 5, "text": "إِنَّمَا تُوعَدُونَ لَصَادِقࣱ ۝٥", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "أقسم الله تعالى بالرياح المثيرات للتراب، فالسحب الحاملات ثقلا عظيمًا من الماء، فالسفن التي تجري في البحار جريًا ذا يسر وسهولة، فالملائكة التي تُقَسِّم أمر الله في خلقه. إن الذي توعدون به- أيها الناس- من البعث والحساب لكائن حق يقين، وإن الحساب والثواب على الأعمال لكائن لا محالة.", "isBasmala": false, "translation_en": "What you are promised is true.", "translation_id": "sesungguhnya apa yang dijanjikan kepadamu pasti benar.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 6, "text": "وَإِنَّ ٱلدِّینَ لَوَ ٰقِعࣱ ۝٦", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "أقسم الله تعالى بالرياح المثيرات للتراب، فالسحب الحاملات ثقلا عظيمًا من الماء، فالسفن التي تجري في البحار جريًا ذا يسر وسهولة، فالملائكة التي تُقَسِّم أمر الله في خلقه. إن الذي توعدون به- أيها الناس- من البعث والحساب لكائن حق يقين، وإن الحساب والثواب على الأعمال لكائن لا محالة.", "isBasmala": false, "translation_en": "Judgment will take place.", "translation_id": "dan sesungguhnya (hari) pembalasan pasti terjadi.", "manzil": 7, "manzil_display": ""}], "521": [{"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 7, "text": "وَٱلسَّمَاۤءِ ذَاتِ ٱلۡحُبُكِ ۝٧", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "وأقسم الله تعالى بالسماء ذات الخَلْق الحسن، إنكم- أيها المكذبون- لفي قول مضطرب في هذا القرآن، وفي الرسول صلى الله عليه وسلم. يُصرف عن القرآن والرسول صلى الله عليه وسلم مَن صُرف عن الإيمان بهما؛ لإعراضه عن أدلة الله وبراهينه اليقينية فلم يوفَّق إلى الخير.", "isBasmala": false, "translation_en": "By the sky that is woven.", "translation_id": "Demi langit yang mempunyai jalan-jalan,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 8, "text": "إِنَّكُمۡ لَفِی قَوۡلࣲ مُّخۡتَلِفࣲ ۝٨", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "وأقسم الله تعالى بالسماء ذات الخَلْق الحسن، إنكم- أيها المكذبون- لفي قول مضطرب في هذا القرآن، وفي الرسول صلى الله عليه وسلم. يُصرف عن القرآن والرسول صلى الله عليه وسلم مَن صُرف عن الإيمان بهما؛ لإعراضه عن أدلة الله وبراهينه اليقينية فلم يوفَّق إلى الخير.", "isBasmala": false, "translation_en": "You differ in what you say.", "translation_id": "sesungguhnya kamu benar-benar dalam keadaan berbeda pendapat,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 9, "text": "یُؤۡفَكُ عَنۡهُ مَنۡ أُفِكَ ۝٩", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "وأقسم الله تعالى بالسماء ذات الخَلْق الحسن، إنكم- أيها المكذبون- لفي قول مضطرب في هذا القرآن، وفي الرسول صلى الله عليه وسلم. يُصرف عن القرآن والرسول صلى الله عليه وسلم مَن صُرف عن الإيمان بهما؛ لإعراضه عن أدلة الله وبراهينه اليقينية فلم يوفَّق إلى الخير.", "isBasmala": false, "translation_en": "Averted from it is he who is averted.", "translation_id": "dipalingkan daripadanya (Rasul dan Al-Quran) orang yang dipalingkan.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 10, "text": "قُتِلَ ٱلۡخَرَّ ٰصُونَ ۝١٠", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "لُعِن الكذابون الظانون غير الحق، الذين هم في لُـجَّة من الكفر والضلالة غافلون متمادون.", "isBasmala": false, "translation_en": "Perish the imposters.", "translation_id": "Terkutuklah orang-orang yang banyak berdusta,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 11, "text": "ٱلَّذِینَ هُمۡ فِی غَمۡرَةࣲ سَاهُونَ ۝١١", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "لُعِن الكذابون الظانون غير الحق، الذين هم في لُـجَّة من الكفر والضلالة غافلون متمادون.", "isBasmala": false, "translation_en": "Those who are dazed in ignorance.", "translation_id": "(yaitu) orang-orang yang terbenam dalam kebodohan yang lalai,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 12, "text": "یَسۡـَٔلُونَ أَیَّانَ یَوۡمُ ٱلدِّینِ ۝١٢", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "يسأل هؤلاء الكذابون سؤال استبعاد وتكذيب: متى يوم الحساب والجزاء؟", "isBasmala": false, "translation_en": "They ask, \"When is the Day of Judgment?\"", "translation_id": "mereka bertanya: \"Bilakah hari pembalasan itu?\"", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 13, "text": "یَوۡمَ هُمۡ عَلَى ٱلنَّارِ یُفۡتَنُونَ ۝١٣", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "يوم الجزاء، يوم يُعذَّبون بالإحراق بالنار، ويقال لهم: ذوقوا عذابكم الذي كنتم به تستعجلون في الدنيا.", "isBasmala": false, "translation_en": "The Day they are presented to the Fire.", "translation_id": "(Hari pembalasan itu) ialah pada hari ketika mereka diazab di atas api neraka.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 14, "text": "ذُوقُوا۟ فِتۡنَتَكُمۡ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ ۝١٤", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "يوم الجزاء، يوم يُعذَّبون بالإحراق بالنار، ويقال لهم: ذوقوا عذابكم الذي كنتم به تستعجلون في الدنيا.", "isBasmala": false, "translation_en": "\"Taste your ordeal. This is what you used to challenge.\"", "translation_id": "(Dikatakan kepada mereka): \"Rasakanlah azabmu itu. Inilah azab yang dulu kamu minta untuk disegerakan\".", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 15, "text": "إِنَّ ٱلۡمُتَّقِینَ فِی جَنَّـٰتࣲ وَعُیُونٍ ۝١٥", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "إن الذين اتقوا الله في جنات عظيمة، وعيون ماء جارية، أعطاهم الله جميع مُناهم من أصناف النعيم، فأخذوا ذلك راضين به، فَرِحة به نفوسهم، إنهم كانوا قبل ذلك النعيم محسنين في الدنيا بأعمالهم الصالحة.", "isBasmala": false, "translation_en": "But the pious are amidst gardens and springs.", "translation_id": "Sesungguhnya orang-orang yang bertakwa itu berada dalam taman-taman (surga) dan mata air-mata air,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 16, "text": "ءَاخِذِینَ مَاۤ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُوا۟ قَبۡلَ ذَ ٰلِكَ مُحۡسِنِینَ ۝١٦", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "إن الذين اتقوا الله في جنات عظيمة، وعيون ماء جارية، أعطاهم الله جميع مُناهم من أصناف النعيم، فأخذوا ذلك راضين به، فَرِحة به نفوسهم، إنهم كانوا قبل ذلك النعيم محسنين في الدنيا بأعمالهم الصالحة.", "isBasmala": false, "translation_en": "Receiving what their Lord has given them. They were virtuous before that.", "translation_id": "sambil menerima segala pemberian Rabb mereka. Sesungguhnya mereka sebelum itu di dunia adalah orang-orang yang berbuat kebaikan.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 17, "text": "كَانُوا۟ قَلِیلࣰا مِّنَ ٱلَّیۡلِ مَا یَهۡجَعُونَ ۝١٧", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "كان هؤلاء المحسنون قليلا من الليل ما ينامون، يُصَلُّون لربهم قانتين له، وفي أواخر الليل قبيل الفجر يستغفرون الله من ذنوبهم.", "isBasmala": false, "translation_en": "They used to sleep a little at night.", "translation_id": "Di dunia mereka sedikit sekali tidur diwaktu malam.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 18, "text": "وَبِٱلۡأَسۡحَارِ هُمۡ یَسۡتَغۡفِرُونَ ۝١٨", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "كان هؤلاء المحسنون قليلا من الليل ما ينامون، يُصَلُّون لربهم قانتين له، وفي أواخر الليل قبيل الفجر يستغفرون الله من ذنوبهم.", "isBasmala": false, "translation_en": "And at dawn, they would pray for pardon.", "translation_id": "Dan selalu memohonkan ampunan diwaktu pagi sebelum fajar.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 19, "text": "وَفِیۤ أَمۡوَ ٰلِهِمۡ حَقࣱّ لِّلسَّاۤىِٕلِ وَٱلۡمَحۡرُومِ ۝١٩", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "وفي أموالهم حق واجب ومستحب للمحتاجين الذين يسألون الناس، والذين لا يسألونهم حياء.", "isBasmala": false, "translation_en": "And in their wealth, there was a share for the beggar and the deprived.", "translation_id": "Dan pada harta-harta mereka ada hak untuk orang miskin yang meminta dan orang miskin yang tidak mendapat bagian.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 20, "text": "وَفِی ٱلۡأَرۡضِ ءَایَـٰتࣱ لِّلۡمُوقِنِینَ ۝٢٠", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "وفي الأرض عبر ودلائل واضحة على قدرة خلقها لأهل اليقين بأن الله هو الإله الحق وحده لا شريك له، والمصدِّقين لرسوله صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "And on earth are signs for the convinced.", "translation_id": "Dan di bumi itu terdapat tanda-tanda (kekuasaan Allah) bagi orang-orang yang yakin.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 21, "text": "وَفِیۤ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ ۝٢١", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "وفي خلق أنفسكم دلائل على قدرة الله تعالى، وعبر تدلكم على وحدانية خالقكم، وأنه لا إله لكم يستحق العبادة سواه، أغَفَلتم عنها، فلا تبصرون ذلك، فتعتبرون به؟", "isBasmala": false, "translation_en": "And within yourselves. Do you not see?", "translation_id": "dan (juga) pada dirimu sendiri. Maka apakah kamu tidak memperhatikan?", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 22, "text": "وَفِی ٱلسَّمَاۤءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ ۝٢٢", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "وفي السماء رزقكم وما توعدون من الخير والشر والثواب والعقاب، وغير ذلك كله مكتوب مقدَّر.", "isBasmala": false, "translation_en": "And in the heaven is your livelihood, and what you are promised.", "translation_id": "Dan di langit terdapat (sebab-sebab) rezekimu dan terdapat (pula) apa yang dijanjikan kepadamu.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 23, "text": "فَوَرَبِّ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقࣱّ مِّثۡلَ مَاۤ أَنَّكُمۡ تَنطِقُونَ ۝٢٣", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "أقسم الله تعالى بنفسه الكريمة أنَّ ما وعدكم به حق، فلا تَشُكُّوا فيه كما لا تَشُكُّون في نطقكم.", "isBasmala": false, "translation_en": "By the Lord of the heaven and the earth, it is as true as the fact that you speak.", "translation_id": "Maka demi Tuhan langit dan bumi, sesungguhnya yang dijanjikan itu adalah benar-benar (akan terjadi) seperti perkataan yang kamu ucapkan.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 24, "text": "هَلۡ أَتَىٰكَ حَدِیثُ ضَیۡفِ إِبۡرَ ٰهِیمَ ٱلۡمُكۡرَمِینَ ۝٢٤", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "هل أتاك -أيها الرسول- حديث ضيف إبراهيم الذين أكرمهم- وكانوا من الملائكة الكرام- حين دخلوا عليه في بيته، فحيَّوه قائلين له: سلامًا، فردَّ عليهم التحية قائلا سلام عليكم، أنتم قوم غرباء لا نعرفكم.", "isBasmala": false, "translation_en": "Has the story of Abraham's honorable guests reached you?", "translation_id": "Sudahkah sampai kepadamu (Muhammad) cerita tentang tamu Ibrahim (yaitu malaikat-malaikat) yang dimuliakan?", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 25, "text": "إِذۡ دَخَلُوا۟ عَلَیۡهِ فَقَالُوا۟ سَلَـٰمࣰاۖ قَالَ سَلَـٰمࣱ قَوۡمࣱ مُّنكَرُونَ ۝٢٥", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "هل أتاك -أيها الرسول- حديث ضيف إبراهيم الذين أكرمهم- وكانوا من الملائكة الكرام- حين دخلوا عليه في بيته، فحيَّوه قائلين له: سلامًا، فردَّ عليهم التحية قائلا سلام عليكم، أنتم قوم غرباء لا نعرفكم.", "isBasmala": false, "translation_en": "When they entered upon him, they said, \"Peace.\" He said, \"Peace, strangers.\"", "translation_id": "(Ingatlah) ketika mereka masuk ke tempatnya lalu mengucapkan: \"Salaamun\". Ibrahim menjawab: \"Salaamun (kamu) adalah orang-orang yang tidak dikenal\".", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 26, "text": "فَرَاغَ إِلَىٰۤ أَهۡلِهِۦ فَجَاۤءَ بِعِجۡلࣲ سَمِینࣲ ۝٢٦", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "فعَدَلَ ومال خفية إلى أهله، فعمد إلى عجل سمين فذبحه، وشواه بالنار، ثم وضعه أمامهم، وتلَّطف في دعوتهم إلى الطعام قائلا ألا تأكلون؟", "isBasmala": false, "translation_en": "Then he slipped away to his family, and brought a fatted calf.", "translation_id": "Maka dia pergi dengan diam-diam menemui keluarganya, kemudian dibawanya daging anak sapi gemuk.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 27, "text": "فَقَرَّبَهُۥۤ إِلَیۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ ۝٢٧", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "فعَدَلَ ومال خفية إلى أهله، فعمد إلى عجل سمين فذبحه، وشواه بالنار، ثم وضعه أمامهم، وتلَّطف في دعوتهم إلى الطعام قائلا ألا تأكلون؟", "isBasmala": false, "translation_en": "He set it before them. He said, \"Will you not eat?\"", "translation_id": "Lalu dihidangkannya kepada mereka. Ibrahim lalu berkata: \"Silahkan anda makan\".", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 28, "text": "فَأَوۡجَسَ مِنۡهُمۡ خِیفَةࣰۖ قَالُوا۟ لَا تَخَفۡۖ وَبَشَّرُوهُ بِغُلَـٰمٍ عَلِیمࣲ ۝٢٨", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "فلما رآهم لا يأكلون أحسَّ في نفسه خوفًا منهم، قالوا له: لا تَخَفْ إنا رسل الله، وبشروه بأن زوجته \"سَارَةَ\" ستلد له ولدًا، سيكون من أهل العلم بالله وبدينه، وهو إسحاق عليه السلام.", "isBasmala": false, "translation_en": "And he harbored fear of them. They said, \"Do not fear,\" and they announced to him the good news of a knowledgeable boy.", "translation_id": "(Tetapi mereka tidak mau makan), karena itu Ibrahim merasa takut terhadap mereka. Mereka berkata: \"Janganlah kamu takut\", dan mereka memberi kabar gembira kepadanya dengan (kelahiran) seorang anak yang alim (Ishak).", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 29, "text": "فَأَقۡبَلَتِ ٱمۡرَأَتُهُۥ فِی صَرَّةࣲ فَصَكَّتۡ وَجۡهَهَا وَقَالَتۡ عَجُوزٌ عَقِیمࣱ ۝٢٩", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "فلما سمعت زوجة إبراهيم مقالة هؤلاء الملائكة بالبشارة أقبلت نحوهم في صيحة، فلطمت وجهها تعجبًا من هذا الأمر، وقالت: كيف ألد وأنا عجوز عقيم لا ألد؟", "isBasmala": false, "translation_en": "His wife came forward crying. She clasped her face, and said, \"A barren old woman?\"", "translation_id": "Kemudian isterinya datang memekik lalu menepuk mukanya sendiri seraya berkata: \"(Aku adalah) seorang perempuan tua yang mandul\".", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 30, "text": "قَالُوا۟ كَذَ ٰلِكِ قَالَ رَبُّكِۖ إِنَّهُۥ هُوَ ٱلۡحَكِیمُ ٱلۡعَلِیمُ ۝٣٠", "juz": 26, "hizb": "(*¾ ح 52*)", "tafsir": "قالت لها ملائكة الله: هكذا قال ربك كما أخبرناك، وهو القادر على ذلك، فلا عجب من قدرته. إنه سبحانه وتعالى هو الحكيم الذي يضع الأشياء مواضعها، العليم بمصالح عباده.", "isBasmala": false, "translation_en": "They said, \"Thus spoke your Lord. He is the Wise, the Knowing.\"", "translation_id": "Mereka berkata: \"Demikianlah Tuhanmu memfirmankan\" Sesungguhnya Dialah yang Maha Bijaksana lagi Maha Mengetahui.", "manzil": 7, "manzil_display": ""}], "522": [{"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 31, "text": "۞ قَالَ فَمَا خَطۡبُكُمۡ أَیُّهَا ٱلۡمُرۡسَلُونَ ۝٣١", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "قال إبراهيم عليه السلام، لملائكة الله: ما شأنكم وفيم أُرسلتم؟ قالوا: إن الله أرسلنا إلى قوم قد أجرموا لكفرهم بالله؛ لنهلكهم بحجارة من طين متحجِّر، معلَّمة عند ربك لهؤلاء المتجاوزين الحدَّ في الفجور والعصيان.", "isBasmala": false, "translation_en": "He said, \"What is your business, O envoys?\"", "translation_id": "Ibrahim bertanya: \"Apakah urusanmu hai para utusan?\"", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 32, "text": "قَالُوۤا۟ إِنَّاۤ أُرۡسِلۡنَاۤ إِلَىٰ قَوۡمࣲ مُّجۡرِمِینَ ۝٣٢", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "قال إبراهيم عليه السلام، لملائكة الله: ما شأنكم وفيم أُرسلتم؟ قالوا: إن الله أرسلنا إلى قوم قد أجرموا لكفرهم بالله؛ لنهلكهم بحجارة من طين متحجِّر، معلَّمة عند ربك لهؤلاء المتجاوزين الحدَّ في الفجور والعصيان.", "isBasmala": false, "translation_en": "They said, \"We are sent to a people guilty of sin.\"", "translation_id": "Mereka menjawab: \"Sesungguhnya kami diutus kepada kaum yang berdosa (kaum Luth),", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 33, "text": "لِنُرۡسِلَ عَلَیۡهِمۡ حِجَارَةࣰ مِّن طِینࣲ ۝٣٣", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "قال إبراهيم عليه السلام، لملائكة الله: ما شأنكم وفيم أُرسلتم؟ قالوا: إن الله أرسلنا إلى قوم قد أجرموا لكفرهم بالله؛ لنهلكهم بحجارة من طين متحجِّر، معلَّمة عند ربك لهؤلاء المتجاوزين الحدَّ في الفجور والعصيان.", "isBasmala": false, "translation_en": "\"To unleash upon them rocks of clay.\"", "translation_id": "agar kami timpakan kepada mereka batu-batu dari tanah,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 34, "text": "مُّسَوَّمَةً عِندَ رَبِّكَ لِلۡمُسۡرِفِینَ ۝٣٤", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "قال إبراهيم عليه السلام، لملائكة الله: ما شأنكم وفيم أُرسلتم؟ قالوا: إن الله أرسلنا إلى قوم قد أجرموا لكفرهم بالله؛ لنهلكهم بحجارة من طين متحجِّر، معلَّمة عند ربك لهؤلاء المتجاوزين الحدَّ في الفجور والعصيان.", "isBasmala": false, "translation_en": "\"Marked by your Lord for the excessive.\"", "translation_id": "yang ditandai di sisi Tuhanmu untuk membinasakan orang-orang yang melampaui batas\".", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 35, "text": "فَأَخۡرَجۡنَا مَن كَانَ فِیهَا مِنَ ٱلۡمُؤۡمِنِینَ ۝٣٥", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "فأخرجنا مَن كان في قرية قوم لوط من أهل الإيمان.", "isBasmala": false, "translation_en": "We evacuated all the believers who were in it.", "translation_id": "Lalu Kami keluarkan orang-orang yang beriman yang berada di negeri kaum Luth itu.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 36, "text": "فَمَا وَجَدۡنَا فِیهَا غَیۡرَ بَیۡتࣲ مِّنَ ٱلۡمُسۡلِمِینَ ۝٣٦", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "فما وجدنا في تلك القرية غير بيت من المسلمين، وهو بيت لوط عليه السلام.", "isBasmala": false, "translation_en": "But found in it only one household of Muslims.", "translation_id": "Dan Kami tidak mendapati negeri itu, kecuali sebuah rumah dari orang yang berserah diri.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 37, "text": "وَتَرَكۡنَا فِیهَاۤ ءَایَةࣰ لِّلَّذِینَ یَخَافُونَ ٱلۡعَذَابَ ٱلۡأَلِیمَ ۝٣٧", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وتركنا في القرية المذكورة أثرًا من العذاب باقيًا علامة على قدرة الله تعالى وانتقامه من الكفرة، وذلك عبرة لمن يخافون عذاب الله المؤلم الموجع.", "isBasmala": false, "translation_en": "And We left in it a sign for those who fear the painful punishment.", "translation_id": "Dan Kami tinggalkan pada negeri itu suatu tanda bagi orang-orang yang takut kepada siksa yang pedih.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 38, "text": "وَفِی مُوسَىٰۤ إِذۡ أَرۡسَلۡنَـٰهُ إِلَىٰ فِرۡعَوۡنَ بِسُلۡطَـٰنࣲ مُّبِینࣲ ۝٣٨", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وفي إرسالنا موسى إلى فرعون وملئه بالآيات والمعجزات الظاهرة آية للذين يخافون العذاب الأليم. فأعْرَضَ فرعون مغترًّا بقوته وجانبه، وقال عن موسى: إنه ساحر أو مجنون.", "isBasmala": false, "translation_en": "And in Moses. We sent him to Pharaoh with a clear authority.", "translation_id": "Dan juga pada Musa (terdapat tanda-tanda kekuasaan Allah) ketika Kami mengutusnya kepada Fir'aun dengan membawa mukjizat yang nyata.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 39, "text": "فَتَوَلَّىٰ بِرُكۡنِهِۦ وَقَالَ سَـٰحِرٌ أَوۡ مَجۡنُونࣱ ۝٣٩", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وفي إرسالنا موسى إلى فرعون وملئه بالآيات والمعجزات الظاهرة آية للذين يخافون العذاب الأليم. فأعْرَضَ فرعون مغترًّا بقوته وجانبه، وقال عن موسى: إنه ساحر أو مجنون.", "isBasmala": false, "translation_en": "But he turned away with his warlords, and said, \"A sorcerer or a madman.\"", "translation_id": "Maka dia (Fir'aun) berpaling (dari iman) bersama tentaranya dan berkata: \"Dia adalah seorang tukang sihir atau seorang gila\".", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 40, "text": "فَأَخَذۡنَـٰهُ وَجُنُودَهُۥ فَنَبَذۡنَـٰهُمۡ فِی ٱلۡیَمِّ وَهُوَ مُلِیمࣱ ۝٤٠", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "فأخذنا فرعون وجنوده، فطرحناهم في البحر، وهو آتٍ ما يلام عليه؛ بسبب كفره وجحوده وفجوره.", "isBasmala": false, "translation_en": "So We seized him and his troops, and threw them into the sea, and He was to blame.", "translation_id": "Maka Kami siksa dia dan tentaranya lalu Kami lemparkan mereka ke dalam laut, sedang dia melakukan pekerjaan yang tercela.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 41, "text": "وَفِی عَادٍ إِذۡ أَرۡسَلۡنَا عَلَیۡهِمُ ٱلرِّیحَ ٱلۡعَقِیمَ ۝٤١", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وفي شأن عاد وإهلاكهم آيات وعبر لمن تأمل، إذ أرسلنا عليهم الريح التي لا بركة فيها ولا تأتي بخير، ما تَدَعُ شيئًا مرَّت عليه إلا صيَّرته كالشيء البالي.", "isBasmala": false, "translation_en": "And in Aad. We unleashed against them the devastating wind.", "translation_id": "Dan juga pada (kisah) Aad ketika Kami kirimkan kepada mereka angin yang membinasakan,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 42, "text": "مَا تَذَرُ مِن شَیۡءٍ أَتَتۡ عَلَیۡهِ إِلَّا جَعَلَتۡهُ كَٱلرَّمِیمِ ۝٤٢", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وفي شأن عاد وإهلاكهم آيات وعبر لمن تأمل، إذ أرسلنا عليهم الريح التي لا بركة فيها ولا تأتي بخير، ما تَدَعُ شيئًا مرَّت عليه إلا صيَّرته كالشيء البالي.", "isBasmala": false, "translation_en": "It spared nothing it came upon, but rendered it like decayed ruins.", "translation_id": "angin itu tidak membiarkan satupun yang dilaluinya, melainkan dijadikannya seperti serbuk.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 43, "text": "وَفِی ثَمُودَ إِذۡ قِیلَ لَهُمۡ تَمَتَّعُوا۟ حَتَّىٰ حِینࣲ ۝٤٣", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وفي شأن ثمود وإهلاكهم آيات وعبر، إذ قيل لهم: انتفعوا بحياتكم حتى تنتهي آجالكم. فعصوا أمر ربهم، فأخذتهم صاعقة العذاب، وهم ينظرون إلى عقوبتهم بأعينهم.", "isBasmala": false, "translation_en": "And in Thamood. They were told, \"Enjoy yourselves for a while.\"", "translation_id": "Dan pada (kisah) kaum Tsamud ketika dikatakan kepada mereka: \"Bersenang-senanglah kalian sampai suatu waktu\".", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 44, "text": "فَعَتَوۡا۟ عَنۡ أَمۡرِ رَبِّهِمۡ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ وَهُمۡ یَنظُرُونَ ۝٤٤", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وفي شأن ثمود وإهلاكهم آيات وعبر، إذ قيل لهم: انتفعوا بحياتكم حتى تنتهي آجالكم. فعصوا أمر ربهم، فأخذتهم صاعقة العذاب، وهم ينظرون إلى عقوبتهم بأعينهم.", "isBasmala": false, "translation_en": "But they defied the command of their Lord, so the lightning struck them as they looked on.", "translation_id": "Maka mereka berlaku angkuh terhadap perintah Tuhannya, lalu mereka disambar petir dan mereka melihatnya.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 45, "text": "فَمَا ٱسۡتَطَـٰعُوا۟ مِن قِیَامࣲ وَمَا كَانُوا۟ مُنتَصِرِینَ ۝٤٥", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "فما أمكنهم الهرب ولا النهوض مما هم فيه من العذاب، وما كانوا منتصرين لأنفسهم.", "isBasmala": false, "translation_en": "They could not rise up, nor could they find help.", "translation_id": "Maka mereka sekali-kali tidak dapat bangun dan tidak pula mendapat pertolongan,", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 46, "text": "وَقَوۡمَ نُوحࣲ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ ۝٤٦", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وأهلكنا قوم نوح من قبل هؤلاء، إنهم كانوا قومًا مخالفين لأمر الله، خارجين عن طاعته.", "isBasmala": false, "translation_en": "And before that, the people of Noah. They were immoral people.", "translation_id": "dan (Kami membinasakan) kaum Nuh sebelum itu. Sesungguhnya mereka adalah kaum yang fasik.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 47, "text": "وَٱلسَّمَاۤءَ بَنَیۡنَـٰهَا بِأَیۡی۟دࣲ وَإِنَّا لَمُوسِعُونَ ۝٤٧", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "والسماء خلقناها وأتقناها، وجعلناها سَقْفًا للأرض بقوة وقدرة عظيمة، وإنا لموسعون لأرجائها وأنحائها.", "isBasmala": false, "translation_en": "We constructed the universe with power, and We are expanding it.", "translation_id": "Dan langit itu Kami bangun dengan kekuasaan (Kami) dan sesungguhnya Kami benar-benar berkuasa", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 48, "text": "وَٱلۡأَرۡضَ فَرَشۡنَـٰهَا فَنِعۡمَ ٱلۡمَـٰهِدُونَ ۝٤٨", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "والأرض جعلناها فراشًا للخلق للاستقرار عليها، فنعم الماهدون نحن.", "isBasmala": false, "translation_en": "And the earth-We spread it out-How well We prepared it!", "translation_id": "Dan bumi itu Kami hamparkan, maka sebaik-baik yang menghamparkan (adalah Kami).", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 49, "text": "وَمِن كُلِّ شَیۡءٍ خَلَقۡنَا زَوۡجَیۡنِ لَعَلَّكُمۡ تَذَكَّرُونَ ۝٤٩", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "ومن كل شيء من أجناس الموجودات خلقنا نوعين مختلفين؛ لكي تتذكروا قدرة الله، وتعتبروا.", "isBasmala": false, "translation_en": "We created all things in pairs, so that you may reflect and ponder.", "translation_id": "Dan segala sesuatu Kami ciptakan berpasang-pasangan supaya kamu mengingat kebesaran Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 50, "text": "فَفِرُّوۤا۟ إِلَى ٱللَّهِۖ إِنِّی لَكُم مِّنۡهُ نَذِیرࣱ مُّبِینࣱ ۝٥٠", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "ففروا-أيها الناس- من عقاب الله إلى رحمته بالإيمان به وبرسوله، واتباع أمره والعمل بطاعته، إني لكم نذير بيِّن الإنذار. وكان رسول الله صلى الله عليه وسلم إذا حزبه أمر، فزع إلى الصلاة، وهذا فرار إلى الله.", "isBasmala": false, "translation_en": "\"So flee towards God. I am to you from Him a clear warner.\"", "translation_id": "Maka segeralah kembali kepada (mentaati) Allah. Sesungguhnya aku seorang pemberi peringatan yang nyata dari Allah untukmu.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 51, "text": "وَلَا تَجۡعَلُوا۟ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَۖ إِنِّی لَكُم مِّنۡهُ نَذِیرࣱ مُّبِینࣱ ۝٥١", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "ولا تجعلوا مع الله معبودًا آخر، إني لكم من الله نذير بيِّن الإنذار.", "isBasmala": false, "translation_en": "\"And do not set up any other god with God. I am to you from Him a clear warner.\"", "translation_id": "Dan janganlah kamu mengadakan tuhan yang lain disamping Allah. Sesungguhnya aku seorang pemberi peringatan yang nyata dari Allah untukmu.", "manzil": 7, "manzil_display": ""}], "523": [{"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 52, "text": "كَذَ ٰلِكَ مَاۤ أَتَى ٱلَّذِینَ مِن قَبۡلِهِم مِّن رَّسُولٍ إِلَّا قَالُوا۟ سَاحِرٌ أَوۡ مَجۡنُونٌ ۝٥٢", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "كما كذبت قريش نبيَّها محمدًا صلى الله عليه وسلم، وقالوا: هو شاعر أو ساحر أو مجنون، فعلت الأمم المكذبة رسلها من قبل قريش، فأحلَّ الله بهم نقمته.", "isBasmala": false, "translation_en": "Likewise, no messenger came to those before them, but they said, \"A sorcerer or a madman.\"", "translation_id": "Demikianlah tidak seorang rasulpun yang datang kepada orang-orang yang sebelum mereka, melainkan mereka mengatakan: \"Dia adalah seorang tukang sihir atau seorang gila\".", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 53, "text": "أَتَوَاصَوۡا۟ بِهِۦۚ بَلۡ هُمۡ قَوۡمࣱ طَاغُونَ ۝٥٣", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "أتواصى الأولون والآخرون بالتكذيب بالرسول حين قالوا ذلك جميعًا؟ بل هم قوم طغاة تشابهت قلوبهم وأعمالهم بالكفر والطغيان، فقال متأخروهم ذلك، كما قاله متقدموهم.", "isBasmala": false, "translation_en": "Did they recommend it to one another? In fact, they are rebellious people.", "translation_id": "Apakah mereka saling berpesan tentang apa yang dikatakan itu. Sebenarnya mereka adalah kaum yang melampaui batas.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 54, "text": "فَتَوَلَّ عَنۡهُمۡ فَمَاۤ أَنتَ بِمَلُومࣲ ۝٥٤", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "فأعرضْ -أيها الرسول- عن المشركين حتى يأتيك فيهم أمر الله، فما أنت بملوم من أحد، فقد بلَّغت ما أُرسلت به.", "isBasmala": false, "translation_en": "So turn away from them; you are not to blame.", "translation_id": "Maka berpalinglah kamu dari mereka dan kamu sekali-kali tidak tercela.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 55, "text": "وَذَكِّرۡ فَإِنَّ ٱلذِّكۡرَىٰ تَنفَعُ ٱلۡمُؤۡمِنِینَ ۝٥٥", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "ومع إعراضك -أيها الرسول- عنهم، وعدم الالتفات إلى تخذيلهم، داوم على الدعوة إلى الله، وعلى وعظ من أُرسلتَ إليهم؛ فإن التذكير والموعظة ينتفع بهما أهل القلوب المؤمنة، وفيهما إقامة الحجة على المعرضين.", "isBasmala": false, "translation_en": "And remind, for the reminder benefits the believers.", "translation_id": "Dan tetaplah memberi peringatan, karena sesungguhnya peringatan itu bermanfaat bagi orang-orang yang beriman.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 56, "text": "وَمَا خَلَقۡتُ ٱلۡجِنَّ وَٱلۡإِنسَ إِلَّا لِیَعۡبُدُونِ ۝٥٦", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وما خلقت الجن والإنس وبعثت جميع الرسل إلا لغاية سامية، هي عبادتي وحدي دون مَن سواي.", "isBasmala": false, "translation_en": "I did not create the jinn and the humans except to worship Me.", "translation_id": "Dan aku tidak menciptakan jin dan manusia melainkan supaya mereka mengabdi kepada-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 57, "text": "مَاۤ أُرِیدُ مِنۡهُم مِّن رِّزۡقࣲ وَمَاۤ أُرِیدُ أَن یُطۡعِمُونِ ۝٥٧", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "ما أريد منهم من رزق وما أريد أن يطعمون، فأنا الرزاق المعطي. فهو سبحانه غير محتاج إلى الخلق، بل هم الفقراء إليه في جميع أحوالهم، فهو خالقهم ورازقهم والغني عنهم.", "isBasmala": false, "translation_en": "I need no livelihood from them, nor do I need them to feed Me.", "translation_id": "Aku tidak menghendaki rezeki sedikitpun dari mereka dan Aku tidak menghendaki supaya mereka memberi-Ku makan.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 58, "text": "إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِینُ ۝٥٨", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "إن الله وحده هو الرزاق لخلقه، المتكفل بأقواتهم، ذو القوة المتين، لا يُقْهَر ولا يغالَب، فله القدرة والقوة كلها.", "isBasmala": false, "translation_en": "God is the Provider, the One with Power, the Strong.", "translation_id": "Sesungguhnya Allah Dialah Maha Pemberi rezeki Yang mempunyai Kekuatan lagi Sangat Kokoh.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 59, "text": "فَإِنَّ لِلَّذِینَ ظَلَمُوا۟ ذَنُوبࣰا مِّثۡلَ ذَنُوبِ أَصۡحَـٰبِهِمۡ فَلَا یَسۡتَعۡجِلُونِ ۝٥٩", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "فإن للذين ظلموا بتكذيبهم الرسول محمدًا صلى الله عليه وسلم نصيبًا من عذاب الله نازلا بهم مثل نصيب أصحابهم الذين مضَوْا من قبلهم، فلا يستعجلون بالعذاب، فهو آتيهم لا محالة.", "isBasmala": false, "translation_en": "Those who do wrong will have their turn, like the turn of their counterparts, so let them not rush Me.", "translation_id": "Maka sesungguhnya untuk orang-orang zalim ada bagian (siksa) seperti bahagian teman mereka (dahulu); maka janganlah mereka meminta kepada-Ku untuk menyegerakannya.", "manzil": 7, "manzil_display": ""}, {"sura": 51, "sura_name": "الذاريات", "revelation": "Makkiyah", "aya": 60, "text": "فَوَیۡلࣱ لِّلَّذِینَ كَفَرُوا۟ مِن یَوۡمِهِمُ ٱلَّذِی یُوعَدُونَ ۝٦٠", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "فهلاك وشقاء للذين كفروا بالله ورسوله من يومهم الذي يوعدون فيه بنزول العذاب بهم، وهو يوم القيامة.", "isBasmala": false, "translation_en": "So woe to those who disbelieve because of that Day of theirs which they are promised.", "translation_id": "Maka kecelakaanlah bagi orang-orang yang kafir pada hari yang diancamkan kepada mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 27, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلطُّورِ ۝١", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "أقسم الله بالطور، وهو الجبل الذي كلَّم الله سبحانه وتعالى موسى عليه، وبكتاب مكتوب، وهو القرآن في صحف منشورة، وبالبيت المعمور في السماء بالملائكة الكرام الذين يطوفون به دائمًا، وبالسقف المرفوع وهو السماء الدنيا، وبالبحر المسجور المملوء بالمياه.", "isBasmala": false, "translation_en": "By the Mount.", "translation_id": "Demi bukit,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 2, "text": "وَكِتَـٰبࣲ مَّسۡطُورࣲ ۝٢", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "أقسم الله بالطور، وهو الجبل الذي كلَّم الله سبحانه وتعالى موسى عليه، وبكتاب مكتوب، وهو القرآن في صحف منشورة، وبالبيت المعمور في السماء بالملائكة الكرام الذين يطوفون به دائمًا، وبالسقف المرفوع وهو السماء الدنيا، وبالبحر المسجور المملوء بالمياه.", "isBasmala": false, "translation_en": "And a Book inscribed.", "translation_id": "dan Kitab yang ditulis,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 3, "text": "فِی رَقࣲّ مَّنشُورࣲ ۝٣", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "أقسم الله بالطور، وهو الجبل الذي كلَّم الله سبحانه وتعالى موسى عليه، وبكتاب مكتوب، وهو القرآن في صحف منشورة، وبالبيت المعمور في السماء بالملائكة الكرام الذين يطوفون به دائمًا، وبالسقف المرفوع وهو السماء الدنيا، وبالبحر المسجور المملوء بالمياه.", "isBasmala": false, "translation_en": "In a published scroll.", "translation_id": "pada lembaran yang terbuka,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 4, "text": "وَٱلۡبَیۡتِ ٱلۡمَعۡمُورِ ۝٤", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "أقسم الله بالطور، وهو الجبل الذي كلَّم الله سبحانه وتعالى موسى عليه، وبكتاب مكتوب، وهو القرآن في صحف منشورة، وبالبيت المعمور في السماء بالملائكة الكرام الذين يطوفون به دائمًا، وبالسقف المرفوع وهو السماء الدنيا، وبالبحر المسجور المملوء بالمياه.", "isBasmala": false, "translation_en": "And the frequented House.", "translation_id": "dan demi Baitul Ma'mur,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 5, "text": "وَٱلسَّقۡفِ ٱلۡمَرۡفُوعِ ۝٥", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "أقسم الله بالطور، وهو الجبل الذي كلَّم الله سبحانه وتعالى موسى عليه، وبكتاب مكتوب، وهو القرآن في صحف منشورة، وبالبيت المعمور في السماء بالملائكة الكرام الذين يطوفون به دائمًا، وبالسقف المرفوع وهو السماء الدنيا، وبالبحر المسجور المملوء بالمياه.", "isBasmala": false, "translation_en": "And the elevated roof.", "translation_id": "dan atap yang ditinggikan (langit),", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 6, "text": "وَٱلۡبَحۡرِ ٱلۡمَسۡجُورِ ۝٦", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "أقسم الله بالطور، وهو الجبل الذي كلَّم الله سبحانه وتعالى موسى عليه، وبكتاب مكتوب، وهو القرآن في صحف منشورة، وبالبيت المعمور في السماء بالملائكة الكرام الذين يطوفون به دائمًا، وبالسقف المرفوع وهو السماء الدنيا، وبالبحر المسجور المملوء بالمياه.", "isBasmala": false, "translation_en": "And the seething sea.", "translation_id": "dan laut yang di dalam tanahnya ada api,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 7, "text": "إِنَّ عَذَابَ رَبِّكَ لَوَ ٰقِعࣱ ۝٧", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "إن عذاب ربك -أيها الرسول- بالكفار لَواقع، ليس له مِن مانع يمنعه حين وقوعه، يوم تتحرك السماء فيختلُّ نظامها وتضطرب أجزاؤها، وذلك عند نهاية الحياة الدنيا، وتزول الجبال عن أماكنها، وتسير كسير السحاب.", "isBasmala": false, "translation_en": "The punishment of your Lord is coming.", "translation_id": "sesungguhnya azab Tuhanmu pasti terjadi,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 8, "text": "مَّا لَهُۥ مِن دَافِعࣲ ۝٨", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "إن عذاب ربك -أيها الرسول- بالكفار لَواقع، ليس له مِن مانع يمنعه حين وقوعه، يوم تتحرك السماء فيختلُّ نظامها وتضطرب أجزاؤها، وذلك عند نهاية الحياة الدنيا، وتزول الجبال عن أماكنها، وتسير كسير السحاب.", "isBasmala": false, "translation_en": "There is nothing to avert it.", "translation_id": "tidak seorangpun yang dapat menolaknya,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 9, "text": "یَوۡمَ تَمُورُ ٱلسَّمَاۤءُ مَوۡرࣰا ۝٩", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "إن عذاب ربك -أيها الرسول- بالكفار لَواقع، ليس له مِن مانع يمنعه حين وقوعه، يوم تتحرك السماء فيختلُّ نظامها وتضطرب أجزاؤها، وذلك عند نهاية الحياة الدنيا، وتزول الجبال عن أماكنها، وتسير كسير السحاب.", "isBasmala": false, "translation_en": "On the Day when the heaven sways in agitation.", "translation_id": "pada hari ketika langit benar-benar bergoncang,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 10, "text": "وَتَسِیرُ ٱلۡجِبَالُ سَیۡرࣰا ۝١٠", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "إن عذاب ربك -أيها الرسول- بالكفار لَواقع، ليس له مِن مانع يمنعه حين وقوعه، يوم تتحرك السماء فيختلُّ نظامها وتضطرب أجزاؤها، وذلك عند نهاية الحياة الدنيا، وتزول الجبال عن أماكنها، وتسير كسير السحاب.", "isBasmala": false, "translation_en": "And the mountains go into motion.", "translation_id": "dan gunung benar-benar berjalan.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 11, "text": "فَوَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝١١", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "فهلاك في هذا اليوم واقع بالمكذبين الذين هم في خوض بالباطل يلعبون به، ويتخذون دينهم هزوًا ولعبًا.", "isBasmala": false, "translation_en": "Woe on that Day to the deniers.", "translation_id": "Maka kecelakaan yang besarlah di hari itu bagi orang-orang yang mendustakan,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 12, "text": "ٱلَّذِینَ هُمۡ فِی خَوۡضࣲ یَلۡعَبُونَ ۝١٢", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "فهلاك في هذا اليوم واقع بالمكذبين الذين هم في خوض بالباطل يلعبون به، ويتخذون دينهم هزوًا ولعبًا.", "isBasmala": false, "translation_en": "Those who play with speculation.", "translation_id": "(yaitu) orang-orang yang bermain-main dalam kebathilan,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 13, "text": "یَوۡمَ یُدَعُّونَ إِلَىٰ نَارِ جَهَنَّمَ دَعًّا ۝١٣", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "يوم يُدْفَع هؤلاء المكذبون دفعًا بعنف ومَهانة إلى نار جهنم، ويقال توبيخًا لهم: هذه هي النار التي كنتم بها تكذِّبون.", "isBasmala": false, "translation_en": "The Day when they are shoved into the Fire of Hell forcefully.", "translation_id": "pada hari mereka didorong ke neraka Jahannam dengan sekuat-kuatnya.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 14, "text": "هَـٰذِهِ ٱلنَّارُ ٱلَّتِی كُنتُم بِهَا تُكَذِّبُونَ ۝١٤", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "يوم يُدْفَع هؤلاء المكذبون دفعًا بعنف ومَهانة إلى نار جهنم، ويقال توبيخًا لهم: هذه هي النار التي كنتم بها تكذِّبون.", "isBasmala": false, "translation_en": "\"This is the Fire which you used to deny.", "translation_id": "(Dikatakan kepada mereka): \"Inilah neraka yang dahulu kamu selalu mendustakannya\".", "manzil": 7, "manzil_display": ""}], "524": [{"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 15, "text": "أَفَسِحۡرٌ هَـٰذَاۤ أَمۡ أَنتُمۡ لَا تُبۡصِرُونَ ۝١٥", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "أفسحر ما تشاهدونه من العذاب أم أنتم لا تنظرون؟ ذوقوا حرَّ هذه النار، فاصبروا على ألمها وشدتها، أو لا تصبروا على ذلك، فلن يُخَفَّف عنكم العذاب، ولن تخرجوا منها، سواء عليكم صبرتم أم لم تصبروا، إنما تُجزون ما كنتم تعملون في الدنيا.", "isBasmala": false, "translation_en": "Is this magic, or do you not see?", "translation_id": "Maka apakah ini sihir? Ataukah kamu tidak melihat?", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 16, "text": "ٱصۡلَوۡهَا فَٱصۡبِرُوۤا۟ أَوۡ لَا تَصۡبِرُوا۟ سَوَاۤءٌ عَلَیۡكُمۡۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ۝١٦", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "أفسحر ما تشاهدونه من العذاب أم أنتم لا تنظرون؟ ذوقوا حرَّ هذه النار، فاصبروا على ألمها وشدتها، أو لا تصبروا على ذلك، فلن يُخَفَّف عنكم العذاب، ولن تخرجوا منها، سواء عليكم صبرتم أم لم تصبروا، إنما تُجزون ما كنتم تعملون في الدنيا.", "isBasmala": false, "translation_en": "Burn in it. Whether you are patient, or impatient, it is the same for you. You are only being repaid for what you used to do.\"", "translation_id": "Masukklah kamu ke dalamnya (rasakanlah panas apinya); maka baik kamu bersabar atau tidak, sama saja bagimu; kamu diberi balasan terhadap apa yang telah kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 17, "text": "إِنَّ ٱلۡمُتَّقِینَ فِی جَنَّـٰتࣲ وَنَعِیمࣲ ۝١٧", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "إن المتقين في جنات ونعيم عظيم، يتفكهون بما آتاهم الله من النعيم من أصناف الملاذِّ المختلفة، ونجَّاهم الله من عذاب النار.", "isBasmala": false, "translation_en": "But the righteous will be amid gardens and bliss.", "translation_id": "Sesungguhnya orang-orang yang bertakwa berada dalam surga dan kenikmatan,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 18, "text": "فَـٰكِهِینَ بِمَاۤ ءَاتَىٰهُمۡ رَبُّهُمۡ وَوَقَىٰهُمۡ رَبُّهُمۡ عَذَابَ ٱلۡجَحِیمِ ۝١٨", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "إن المتقين في جنات ونعيم عظيم، يتفكهون بما آتاهم الله من النعيم من أصناف الملاذِّ المختلفة، ونجَّاهم الله من عذاب النار.", "isBasmala": false, "translation_en": "Enjoying what their Lord has given them, and their Lord has spared them the suffering of Hell.", "translation_id": "mereka bersuka ria dengan apa yang diberikan kepada mereka oleh Tuhan mereka; dan Tuhan mereka memelihara mereka dari azab neraka.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 19, "text": "كُلُوا۟ وَٱشۡرَبُوا۟ هَنِیۤـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ ۝١٩", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "كلوا طعامًا هنيئًا، واشربوا شرابًا سائغًا؛ جزاء بما عملتم من أعمال صالحة في الدنيا. وهم متكئون على سرر متقابلة، وزوَّجناهم بنساء بيض واسعات العيون حسانهنَّ.", "isBasmala": false, "translation_en": "Eat and drink happily, for what you used to do.", "translation_id": "(Dikatakan kepada mereka): \"Makan dan minumlah dengan enak sebagai balasan dari apa yang telah kamu kerjakan\",", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 20, "text": "مُتَّكِـِٔینَ عَلَىٰ سُرُرࣲ مَّصۡفُوفَةࣲۖ وَزَوَّجۡنَـٰهُم بِحُورٍ عِینࣲ ۝٢٠", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "كلوا طعامًا هنيئًا، واشربوا شرابًا سائغًا؛ جزاء بما عملتم من أعمال صالحة في الدنيا. وهم متكئون على سرر متقابلة، وزوَّجناهم بنساء بيض واسعات العيون حسانهنَّ.", "isBasmala": false, "translation_en": "Relaxing on luxurious furnishings; and We will couple them with gorgeous spouses.", "translation_id": "mereka bertelekan di atas dipan-dipan berderetan dan Kami kawinkan mereka dengan bidadari-bidadari yang cantik bermata jeli.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 21, "text": "وَٱلَّذِینَ ءَامَنُوا۟ وَٱتَّبَعَتۡهُمۡ ذُرِّیَّتُهُم بِإِیمَـٰنٍ أَلۡحَقۡنَا بِهِمۡ ذُرِّیَّتَهُمۡ وَمَاۤ أَلَتۡنَـٰهُم مِّنۡ عَمَلِهِم مِّن شَیۡءࣲۚ كُلُّ ٱمۡرِىِٕۭ بِمَا كَسَبَ رَهِینࣱ ۝٢١", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "والذين آمنوا واتبعتهم ذريتهم في الإيمان، وألحقنا بهم ذريتهم في منزلتهم في الجنة، وإن لم يبلغوا عمل آبائهم؛ لتَقَرَّ أعين الآباء بالأبناء عندهم في منازلهم، فيُجْمَع بينهم على أحسن الأحوال، وما نقصناهم شيئًا من ثواب أعمالهم. كل إنسان مرهون بعمله، لا يحمل ذنب غيره من الناس.", "isBasmala": false, "translation_en": "Those who believed and their offspring followed them in faith-We will unite them with their offspring, and We will not deprive them of any of their works. Every person is hostage to what he has earned.", "translation_id": "Dan orang-oranng yang beriman, dan yang anak cucu mereka mengikuti mereka dalam keimanan, Kami hubungkan anak cucu mereka dengan mereka, dan Kami tiada mengurangi sedikitpun dari pahala amal mereka. Tiap-tiap manusia terikat dengan apa yang dikerjakannya.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 22, "text": "وَأَمۡدَدۡنَـٰهُم بِفَـٰكِهَةࣲ وَلَحۡمࣲ مِّمَّا یَشۡتَهُونَ ۝٢٢", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وزدناهم على ما ذُكر من النعيم فواكه ولحومًا مما يستطاب ويُشتهى، ومن هذا النعيم أنهم يتعاطَوْن في الجنة كأسًا من الخمر، يناول أحدهم صاحبه؛ ليتم بذلك سرورهم، وهذا الشراب مخالف لخمر الدنيا، فلا يزول به عقل صاحبه، ولا يحصل بسببه لغو، ولا كلام فيه إثم أو معصية.", "isBasmala": false, "translation_en": "And We will supply them with fruit, and meat; such as they desire.", "translation_id": "Dan Kami beri mereka tambahan dengan buah-buahan dan daging dari segala jenis yang mereka ingini.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 23, "text": "یَتَنَـٰزَعُونَ فِیهَا كَأۡسࣰا لَّا لَغۡوࣱ فِیهَا وَلَا تَأۡثِیمࣱ ۝٢٣", "juz": 27, "hizb": "(* ح 53*)", "tafsir": "وزدناهم على ما ذُكر من النعيم فواكه ولحومًا مما يستطاب ويُشتهى، ومن هذا النعيم أنهم يتعاطَوْن في الجنة كأسًا من الخمر، يناول أحدهم صاحبه؛ ليتم بذلك سرورهم، وهذا الشراب مخالف لخمر الدنيا، فلا يزول به عقل صاحبه، ولا يحصل بسببه لغو، ولا كلام فيه إثم أو معصية.", "isBasmala": false, "translation_en": "They will exchange therein a cup; wherein is neither harm, nor sin.", "translation_id": "Di dalam surga mereka saling memperebutkan piala (gelas) yang isinya tidak (menimbulkan) kata-kata yang tidak berfaedah dan tiada pula perbuatan dosa.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 24, "text": "۞ وَیَطُوفُ عَلَیۡهِمۡ غِلۡمَانࣱ لَّهُمۡ كَأَنَّهُمۡ لُؤۡلُؤࣱ مَّكۡنُونࣱ ۝٢٤", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "ويطوف عليهم غلمان مُعَدُّون لخدمتهم، كأنهم في الصفاء والبياض والتناسق لؤلؤ مصون في أصدافه.", "isBasmala": false, "translation_en": "Serving them will be youths like hidden pearls.", "translation_id": "Dan berkeliling di sekitar mereka anak-anak muda untuk (melayani) mereka, seakan-akan mereka itu mutiara yang tersimpan.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 25, "text": "وَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲ یَتَسَاۤءَلُونَ ۝٢٥", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "وأقبل أهل الجنة، يسأل بعضهم بعضًا عن عظيم ما هم فيه وسببه، قالوا: إنا كنا قبل في الدنيا- ونحن بين أهلينا- خائفين ربنا، مشفقين من عذابه وعقابه يوم القيامة. فمنَّ الله علينا بالهداية والتوفيق، ووقانا عذاب سموم جهنم، وهو نارها وحرارتها. إنا كنا من قبلُ نضرع إليه وحده لا نشرك معه غيره أن يقينا عذاب السَّموم ويوصلنا إلى النعيم، فاستجاب لنا وأعطانا سؤالنا، إنه هو البَرُّ الرحيم. فمن بِره ورحمته إيانا أنالنا رضاه والجنة، ووقانا مِن سخطه والنار.", "isBasmala": false, "translation_en": "And they will approach one another, inquiring.", "translation_id": "Dan sebahagian mereka menghadap kepada sebahagian yang lain saling tanya-menanya.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 26, "text": "قَالُوۤا۟ إِنَّا كُنَّا قَبۡلُ فِیۤ أَهۡلِنَا مُشۡفِقِینَ ۝٢٦", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "وأقبل أهل الجنة، يسأل بعضهم بعضًا عن عظيم ما هم فيه وسببه، قالوا: إنا كنا قبل في الدنيا- ونحن بين أهلينا- خائفين ربنا، مشفقين من عذابه وعقابه يوم القيامة. فمنَّ الله علينا بالهداية والتوفيق، ووقانا عذاب سموم جهنم، وهو نارها وحرارتها. إنا كنا من قبلُ نضرع إليه وحده لا نشرك معه غيره أن يقينا عذاب السَّموم ويوصلنا إلى النعيم، فاستجاب لنا وأعطانا سؤالنا، إنه هو البَرُّ الرحيم. فمن بِره ورحمته إيانا أنالنا رضاه والجنة، ووقانا مِن سخطه والنار.", "isBasmala": false, "translation_en": "They will say, \"Before this, we were fearful for our families.", "translation_id": "Mereka berkata: \"Sesungguhnya kami dahulu, sewaktu berada di tengah-tengah keluarga kami merasa takut (akan diazab)\".", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 27, "text": "فَمَنَّ ٱللَّهُ عَلَیۡنَا وَوَقَىٰنَا عَذَابَ ٱلسَّمُومِ ۝٢٧", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "وأقبل أهل الجنة، يسأل بعضهم بعضًا عن عظيم ما هم فيه وسببه، قالوا: إنا كنا قبل في الدنيا- ونحن بين أهلينا- خائفين ربنا، مشفقين من عذابه وعقابه يوم القيامة. فمنَّ الله علينا بالهداية والتوفيق، ووقانا عذاب سموم جهنم، وهو نارها وحرارتها. إنا كنا من قبلُ نضرع إليه وحده لا نشرك معه غيره أن يقينا عذاب السَّموم ويوصلنا إلى النعيم، فاستجاب لنا وأعطانا سؤالنا، إنه هو البَرُّ الرحيم. فمن بِره ورحمته إيانا أنالنا رضاه والجنة، ووقانا مِن سخطه والنار.", "isBasmala": false, "translation_en": "But God blessed us, and spared us the agony of the Fiery Winds.", "translation_id": "Maka Allah memberikan karunia kepada kami dan memelihara kami dari azab neraka.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 28, "text": "إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِیمُ ۝٢٨", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "وأقبل أهل الجنة، يسأل بعضهم بعضًا عن عظيم ما هم فيه وسببه، قالوا: إنا كنا قبل في الدنيا- ونحن بين أهلينا- خائفين ربنا، مشفقين من عذابه وعقابه يوم القيامة. فمنَّ الله علينا بالهداية والتوفيق، ووقانا عذاب سموم جهنم، وهو نارها وحرارتها. إنا كنا من قبلُ نضرع إليه وحده لا نشرك معه غيره أن يقينا عذاب السَّموم ويوصلنا إلى النعيم، فاستجاب لنا وأعطانا سؤالنا، إنه هو البَرُّ الرحيم. فمن بِره ورحمته إيانا أنالنا رضاه والجنة، ووقانا مِن سخطه والنار.", "isBasmala": false, "translation_en": "Before this, we used to pray to Him. He is the Good, the Compassionate.\"", "translation_id": "Sesungguhnya kami dahulu menyembah-Nya. Sesungguhnya Dialah yang melimpahkan kebaikan lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 29, "text": "فَذَكِّرۡ فَمَاۤ أَنتَ بِنِعۡمَتِ رَبِّكَ بِكَاهِنࣲ وَلَا مَجۡنُونٍ ۝٢٩", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "فذكِّر -أيها الرسول- مَن أُرسلت إليهم بالقرآن، فما أنت بإنعام الله عليك بالنبوة ورجاحة العقل بكاهن يخبر بالغيب دون علم، ولا مجنون لا يعقل ما يقول كما يَدَّعون.", "isBasmala": false, "translation_en": "So remind. By the grace of your Lord, you are neither a soothsayer, nor a madman.", "translation_id": "Maka tetaplah memberi peringatan, dan kamu disebabkan nikmat Tuhanmu bukanlah seorang tukang tenung dan bukan pula seorang gila.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 30, "text": "أَمۡ یَقُولُونَ شَاعِرࣱ نَّتَرَبَّصُ بِهِۦ رَیۡبَ ٱلۡمَنُونِ ۝٣٠", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أم يقول المشركون لك -أيها الرسول-: هو شاعر ننتظر به نزول الموت؟ قل لهم: انتظروا موتي فإني معكم من المنتظرين بكم العذاب، وسترون لمن تكون العاقبة.", "isBasmala": false, "translation_en": "Or do they say, \"A poet-we await for him a calamity of time\"?", "translation_id": "Bahkan mereka mengatakan: \"Dia adalah seorang penyair yang kami tunggu-tunggu kecelakaan menimpanya\".", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 31, "text": "قُلۡ تَرَبَّصُوا۟ فَإِنِّی مَعَكُم مِّنَ ٱلۡمُتَرَبِّصِینَ ۝٣١", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أم يقول المشركون لك -أيها الرسول-: هو شاعر ننتظر به نزول الموت؟ قل لهم: انتظروا موتي فإني معكم من المنتظرين بكم العذاب، وسترون لمن تكون العاقبة.", "isBasmala": false, "translation_en": "Say, \"Go on waiting; I will be waiting with you.\"", "translation_id": "Katakanlah: \"Tunggulah, maka sesungguhnya akupun termasuk orang yang menunggu (pula) bersama kamu\".", "manzil": 7, "manzil_display": ""}], "525": [{"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 32, "text": "أَمۡ تَأۡمُرُهُمۡ أَحۡلَـٰمُهُم بِهَـٰذَاۤۚ أَمۡ هُمۡ قَوۡمࣱ طَاغُونَ ۝٣٢", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "بل أتأمر هؤلاء المكذبين عقولهم بهذا القول المتناقض (ذلك أن صفات الكهانة والشعر والجنون لا يمكن اجتماعها في آن واحد)، بل هم قوم متجاوزون الحدَّ في الطغيان.", "isBasmala": false, "translation_en": "Or is it that their dreams compel them to this? Or are they aggressive people?", "translation_id": "Apakah mereka diperintah oleh fikiran-fikiran mereka untuk mengucapkan tuduhan-tuduhan ini ataukah mereka kaum yang melampaui batas?", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 33, "text": "أَمۡ یَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا یُؤۡمِنُونَ ۝٣٣", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "بل أيقول هؤلاء المشركون، اختلق محمد القرآن من تلقاء نفسه؟ بل هم لا يؤمنون، فلو آمنوا لم يقولوا ما قالوه.", "isBasmala": false, "translation_en": "Or do they say, \"He made it up\"? Rather, they do not believe.", "translation_id": "Ataukah mereka mengatakan: \"Dia (Muhammad) membuat-buatnya\". Sebenarnya mereka tidak beriman.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 34, "text": "فَلۡیَأۡتُوا۟ بِحَدِیثࣲ مِّثۡلِهِۦۤ إِن كَانُوا۟ صَـٰدِقِینَ ۝٣٤", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "فليأتوا بكلام مثل القرآن، إن كانوا صادقين- في زعمهم- أن محمدًا اختلقه.", "isBasmala": false, "translation_en": "So let them produce a discourse like it, if they are truthful.", "translation_id": "Maka hendaklah mereka mendatangkan kalimat yang semisal Al Quran itu jika mereka orang-orang yang benar.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 35, "text": "أَمۡ خُلِقُوا۟ مِنۡ غَیۡرِ شَیۡءٍ أَمۡ هُمُ ٱلۡخَـٰلِقُونَ ۝٣٥", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أخُلِق هؤلاء المشركون من غير خالق لهم وموجد، أم هم الخالقون لأنفسهم؟ وكلا الأمرين باطل ومستحيل. وبهذا يتعيَّن أن الله سبحانه هو الذي خلقهم، وهو وحده الذي لا تنبغي العبادة ولا تصلح إلا له.", "isBasmala": false, "translation_en": "Or were they created out of nothing? Or are they the creators?", "translation_id": "Apakah mereka diciptakan tanpa sesuatupun ataukah mereka yang menciptakan (diri mereka sendiri)?", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 36, "text": "أَمۡ خَلَقُوا۟ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَۚ بَل لَّا یُوقِنُونَ ۝٣٦", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أم خَلَقوا السموات والأرض على هذا الصنع البديع؟ بل هم لا يوقنون بعذاب الله، فهم مشركون.", "isBasmala": false, "translation_en": "Or did they create the heavens and the earth? In fact, they are not certain.", "translation_id": "Ataukah mereka telah menciptakan langit dan bumi itu?; sebenarnya mereka tidak meyakini (apa yang mereka katakan).", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 37, "text": "أَمۡ عِندَهُمۡ خَزَاۤىِٕنُ رَبِّكَ أَمۡ هُمُ ٱلۡمُصَۣیۡطِرُونَ ۝٣٧", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أم عندهم خزائن ربك يتصرفون فيها، أم هم الجبارون المتسلطون على خلق الله بالقهر والغلبة؟ ليس الأمر كذلك، بل هم العاجزون الضعفاء.", "isBasmala": false, "translation_en": "Or do they possess the treasuries of your Lord? Or are they the controllers?", "translation_id": "Ataukah di sisi mereka ada perbendaharaan Tuhanmu atau merekakah yang berkuasa?", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 38, "text": "أَمۡ لَهُمۡ سُلَّمࣱ یَسۡتَمِعُونَ فِیهِۖ فَلۡیَأۡتِ مُسۡتَمِعُهُم بِسُلۡطَـٰنࣲ مُّبِینٍ ۝٣٨", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أم لهم مصعد إلى السماء يستمعون فيه الوحي بأن الذي هم عليه حق؟ فليأت مَن يزعم أنه استمع ذلك بحجة بينة تصدِّق دعواه.", "isBasmala": false, "translation_en": "Or do they have a stairway by means of which they listen? Then let their listener produce a clear proof.", "translation_id": "Ataukah mereka mempunyai tangga (ke langit) untuk mendengarkan pada tangga itu (hal-hal yang gaib)? Maka hendaklah orang yang mendengarkan di antara mereka mendatangkan suatu keterangan yang nyata.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 39, "text": "أَمۡ لَهُ ٱلۡبَنَـٰتُ وَلَكُمُ ٱلۡبَنُونَ ۝٣٩", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "ألِلهِ سبحانه البنات ولكم البنون كما تزعمون افتراء وكذبًا؟", "isBasmala": false, "translation_en": "Or for Him the daughters, and for you the sons?", "translation_id": "Ataukah untuk Allah anak-anak perempuan dan untuk kamu anak-anak laki-laki?", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 40, "text": "أَمۡ تَسۡـَٔلُهُمۡ أَجۡرࣰا فَهُم مِّن مَّغۡرَمࣲ مُّثۡقَلُونَ ۝٤٠", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتسأل -أيها الرسول- هؤلاء المشركون أجرًا على تبليغ الرسالة، فهم في جهد ومشقة من التزام غرامة تطلبها منهم؟", "isBasmala": false, "translation_en": "Or do you demand a payment from them, and they are burdened by debt?", "translation_id": "Ataukah kamu meminta upah kepada mereka sehingga mereka dibebani dengan hutang?", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 41, "text": "أَمۡ عِندَهُمُ ٱلۡغَیۡبُ فَهُمۡ یَكۡتُبُونَ ۝٤١", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أم عندهم علم الغيب فهم يكتبونه للناس ويخبرونهم به؟ ليس الأمر كذلك؛ فإنه لا يعلم الغيب في السموات والأرض إلا الله.", "isBasmala": false, "translation_en": "Or do they know the future, and they are writing it down?", "translation_id": "Apakah ada pada sisi mereka pengetahuan tentang yang gaib lalu mereka menuliskannya?", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 42, "text": "أَمۡ یُرِیدُونَ كَیۡدࣰاۖ فَٱلَّذِینَ كَفَرُوا۟ هُمُ ٱلۡمَكِیدُونَ ۝٤٢", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "بل يريدون برسول الله وبالمؤمنين مكرًا، فالذين كفروا يرجع كيدهم ومكرهم على أنفسهم.", "isBasmala": false, "translation_en": "Or are they planning a conspiracy? The conspiracy will befall the disbelievers.", "translation_id": "Ataukah mereka hendak melakukan tipu daya? Maka orang-orang yang kafir itu merekalah yang kena tipu daya.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 43, "text": "أَمۡ لَهُمۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِۚ سُبۡحَـٰنَ ٱللَّهِ عَمَّا یُشۡرِكُونَ ۝٤٣", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أم لهم معبود يستحق العبادة غير الله؟ تنزَّه وتعالى عما يشركون، فليس له شريك فى الملك، ولا شريك في الوحدانية والعبادة.", "isBasmala": false, "translation_en": "Or do they have a god besides God? God transcends what they associate.", "translation_id": "Ataukah mereka mempunyai tuhan selain Allah. Maha Suci Allah dari apa yang mereka persekutukan.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 44, "text": "وَإِن یَرَوۡا۟ كِسۡفࣰا مِّنَ ٱلسَّمَاۤءِ سَاقِطࣰا یَقُولُوا۟ سَحَابࣱ مَّرۡكُومࣱ ۝٤٤", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "وإن ير هؤلاء المشركون قطعًا من السماء ساقطًا عليهم عذابًا لهم لم ينتقلوا عما هم عليه من التكذيب، ولقالوا: هذا سحاب متراكم بعضه فوق بعض.", "isBasmala": false, "translation_en": "Even if they were to see lumps of the sky falling down, they would say, \"A mass of clouds.\"", "translation_id": "Jika mereka melihat sebagian dari langit gugur, mereka akan mengatakan: \"Itu adalah awan yang bertindih-tindih\".", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 45, "text": "فَذَرۡهُمۡ حَتَّىٰ یُلَـٰقُوا۟ یَوۡمَهُمُ ٱلَّذِی فِیهِ یُصۡعَقُونَ ۝٤٥", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "فدع -أيها الرسول- هؤلاء المشركين حتى يلاقوا يومهم الذي فيه يُهْلكون، وهو يوم القيامة.", "isBasmala": false, "translation_en": "So leave them until they meet their Day in which they will be stunned.", "translation_id": "Maka biarkanlah mereka hingga mereka menemui hari (yang dijanjikan kepada) mereka yang pada hari itu mereka dibinasakan,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 46, "text": "یَوۡمَ لَا یُغۡنِی عَنۡهُمۡ كَیۡدُهُمۡ شَیۡـࣰٔا وَلَا هُمۡ یُنصَرُونَ ۝٤٦", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "وفي ذلك اليوم لا يَدْفع عنهم كيدهم من عذاب الله شيئًا، ولا ينصرهم ناصر من عذاب الله.", "isBasmala": false, "translation_en": "The Day when their ploys will avail them nothing; and they will not be helped.", "translation_id": "(yaitu) hari ketika tidak berguna bagi mereka sedikitpun tipu daya mereka dan mereka tidak ditolong.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 47, "text": "وَإِنَّ لِلَّذِینَ ظَلَمُوا۟ عَذَابࣰا دُونَ ذَ ٰلِكَ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ ۝٤٧", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "وإن لهؤلاء الظلمة عذابًا يلقونه في الدنيا قبل عذاب يوم القيامة من القتل والسبي وعذاب البرزخ وغير ذلك، ولكن أكثرهم لا يعلمون ذلك.", "isBasmala": false, "translation_en": "For those who do wrong, there is a punishment besides that; but most of them do not know.", "translation_id": "Dan sesungguhnya untuk orang-orang yang zalim ada azab selain daripada itu. Tetapi kebanyakan mereka tidak mengetahui.", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 48, "text": "وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡیُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِینَ تَقُومُ ۝٤٨", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "واصبر -أيها الرسول- لحكم ربك وأمره فيما حَمَّلك من الرسالة، وعلى ما يلحقك من أذى قومك، فإنك بمرأى منا وحفظ واعتناء، وسبِّح بحمد ربك حين تقوم إلى الصلاة، وحين تقوم من نومك، ومن الليل فسبِّح بحمد ربك وعظِّمه، وصلِّ له، وافعل ذلك عند صلاة الصبح وقت إدبار النجوم. وفي هذه الآية إثبات لصفة العينين لله تعالى بما يليق به، دون تشبيه بخلقه أو تكييف لذاته، سبحانه وبحمده، كما ثبت ذلك بالسنة، وأجمع عليه سلف الأمة، واللفظ ورد هنا بصيغة الجمع للتعظيم.", "isBasmala": false, "translation_en": "So patiently await the decision of your Lord, for you are before Our Eyes; and proclaim the praises of your Lord when you arise.", "translation_id": "Dan bersabarlah dalam menunggu ketetapan Tuhanmu, maka sesungguhnya kamu berada dalam penglihatan Kami, dan bertasbihlah dengan memuji Tuhanmu ketika kamu bangun berdiri,", "manzil": 7, "manzil_display": ""}, {"sura": 52, "sura_name": "الطور", "revelation": "Makkiyah", "aya": 49, "text": "وَمِنَ ٱلَّیۡلِ فَسَبِّحۡهُ وَإِدۡبَـٰرَ ٱلنُّجُومِ ۝٤٩", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "واصبر -أيها الرسول- لحكم ربك وأمره فيما حَمَّلك من الرسالة، وعلى ما يلحقك من أذى قومك، فإنك بمرأى منا وحفظ واعتناء، وسبِّح بحمد ربك حين تقوم إلى الصلاة، وحين تقوم من نومك، ومن الليل فسبِّح بحمد ربك وعظِّمه، وصلِّ له، وافعل ذلك عند صلاة الصبح وقت إدبار النجوم. وفي هذه الآية إثبات لصفة العينين لله تعالى بما يليق به، دون تشبيه بخلقه أو تكييف لذاته، سبحانه وبحمده، كما ثبت ذلك بالسنة، وأجمع عليه سلف الأمة، واللفظ ورد هنا بصيغة الجمع للتعظيم.", "isBasmala": false, "translation_en": "And glorify Him during the night, and at the receding of the stars.", "translation_id": "dan bertasbihlah kepada-Nya pada beberapa saat di malam hari dan di waktu terbenam bintang-bintang (di waktu fajar).", "manzil": 7, "manzil_display": ""}], "526": [{"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 27, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلنَّجۡمِ إِذَا هَوَىٰ ۝١", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أقسم الله تعالى بالنجوم إذا غابت، ما حاد محمد صلى الله عليه وسلم عن طريق الهداية والحق، وما خرج عن الرشاد، بل هو في غاية الاستقامة والاعتدال والسداد، وليس نطقه صادرًا عن هوى نفسه. ما القرآن وما السنة إلا وحي من الله إلى نبيه محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "By the star as it goes down.", "translation_id": "Demi bintang ketika terbenam.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 2, "text": "مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ ۝٢", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أقسم الله تعالى بالنجوم إذا غابت، ما حاد محمد صلى الله عليه وسلم عن طريق الهداية والحق، وما خرج عن الرشاد، بل هو في غاية الاستقامة والاعتدال والسداد، وليس نطقه صادرًا عن هوى نفسه. ما القرآن وما السنة إلا وحي من الله إلى نبيه محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Your friend has not gone astray, nor has he erred.", "translation_id": "kawanmu (Muhammad) tidak sesat dan tidak pula keliru.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 3, "text": "وَمَا یَنطِقُ عَنِ ٱلۡهَوَىٰۤ ۝٣", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أقسم الله تعالى بالنجوم إذا غابت، ما حاد محمد صلى الله عليه وسلم عن طريق الهداية والحق، وما خرج عن الرشاد، بل هو في غاية الاستقامة والاعتدال والسداد، وليس نطقه صادرًا عن هوى نفسه. ما القرآن وما السنة إلا وحي من الله إلى نبيه محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Nor does he speak out of desire.", "translation_id": "dan tiadalah yang diucapkannya itu (Al-Quran) menurut kemauan hawa nafsunya.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 4, "text": "إِنۡ هُوَ إِلَّا وَحۡیࣱ یُوحَىٰ ۝٤", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أقسم الله تعالى بالنجوم إذا غابت، ما حاد محمد صلى الله عليه وسلم عن طريق الهداية والحق، وما خرج عن الرشاد، بل هو في غاية الاستقامة والاعتدال والسداد، وليس نطقه صادرًا عن هوى نفسه. ما القرآن وما السنة إلا وحي من الله إلى نبيه محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "It is but a revelation revealed.", "translation_id": "Ucapannya itu tiada lain hanyalah wahyu yang diwahyukan (kepadanya).", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 5, "text": "عَلَّمَهُۥ شَدِیدُ ٱلۡقُوَىٰ ۝٥", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "علَّم محمدًا صلى الله عليه وسلم مَلَك شديد القوة، ذو منظر حسن، وهو جبريل عليه السلام، الذي ظهر واستوى على صورته الحقيقية للرسول صلى الله عليه وسلم في الأفق الأعلى، وهو أفق الشمس عند مطلعها، ثم دنا جبريل من الرسول صلى الله عليه وسلم، فزاد في القرب، فكان دنوُّه مقدار قوسين أو أقرب من ذلك. فأوحى الله سبحانه وتعالى إلى عبده محمد صلى الله عليه وسلم ما أوحى بواسطة جبريل عليه السلام. ما كذب قلب محمد صلى الله عليه وسلم ما رآه بصره.", "isBasmala": false, "translation_en": "Taught to him by the Extremely Powerful.", "translation_id": "yang diajarkan kepadanya oleh (Jibril) yang sangat kuat.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 6, "text": "ذُو مِرَّةࣲ فَٱسۡتَوَىٰ ۝٦", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "علَّم محمدًا صلى الله عليه وسلم مَلَك شديد القوة، ذو منظر حسن، وهو جبريل عليه السلام، الذي ظهر واستوى على صورته الحقيقية للرسول صلى الله عليه وسلم في الأفق الأعلى، وهو أفق الشمس عند مطلعها، ثم دنا جبريل من الرسول صلى الله عليه وسلم، فزاد في القرب، فكان دنوُّه مقدار قوسين أو أقرب من ذلك. فأوحى الله سبحانه وتعالى إلى عبده محمد صلى الله عليه وسلم ما أوحى بواسطة جبريل عليه السلام. ما كذب قلب محمد صلى الله عليه وسلم ما رآه بصره.", "isBasmala": false, "translation_en": "The one of vigor. He settled.", "translation_id": "yang mempunyai akal yang cerdas; dan (Jibril itu) menampakkan diri dengan rupa yang asli.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 7, "text": "وَهُوَ بِٱلۡأُفُقِ ٱلۡأَعۡلَىٰ ۝٧", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "علَّم محمدًا صلى الله عليه وسلم مَلَك شديد القوة، ذو منظر حسن، وهو جبريل عليه السلام، الذي ظهر واستوى على صورته الحقيقية للرسول صلى الله عليه وسلم في الأفق الأعلى، وهو أفق الشمس عند مطلعها، ثم دنا جبريل من الرسول صلى الله عليه وسلم، فزاد في القرب، فكان دنوُّه مقدار قوسين أو أقرب من ذلك. فأوحى الله سبحانه وتعالى إلى عبده محمد صلى الله عليه وسلم ما أوحى بواسطة جبريل عليه السلام. ما كذب قلب محمد صلى الله عليه وسلم ما رآه بصره.", "isBasmala": false, "translation_en": "While he was at the highest horizon.", "translation_id": "sedang dia berada di ufuk yang tinggi.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 8, "text": "ثُمَّ دَنَا فَتَدَلَّىٰ ۝٨", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "علَّم محمدًا صلى الله عليه وسلم مَلَك شديد القوة، ذو منظر حسن، وهو جبريل عليه السلام، الذي ظهر واستوى على صورته الحقيقية للرسول صلى الله عليه وسلم في الأفق الأعلى، وهو أفق الشمس عند مطلعها، ثم دنا جبريل من الرسول صلى الله عليه وسلم، فزاد في القرب، فكان دنوُّه مقدار قوسين أو أقرب من ذلك. فأوحى الله سبحانه وتعالى إلى عبده محمد صلى الله عليه وسلم ما أوحى بواسطة جبريل عليه السلام. ما كذب قلب محمد صلى الله عليه وسلم ما رآه بصره.", "isBasmala": false, "translation_en": "Then he came near, and hovered around.", "translation_id": "Kemudian dia mendekat, lalu bertambah dekat lagi.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 9, "text": "فَكَانَ قَابَ قَوۡسَیۡنِ أَوۡ أَدۡنَىٰ ۝٩", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "علَّم محمدًا صلى الله عليه وسلم مَلَك شديد القوة، ذو منظر حسن، وهو جبريل عليه السلام، الذي ظهر واستوى على صورته الحقيقية للرسول صلى الله عليه وسلم في الأفق الأعلى، وهو أفق الشمس عند مطلعها، ثم دنا جبريل من الرسول صلى الله عليه وسلم، فزاد في القرب، فكان دنوُّه مقدار قوسين أو أقرب من ذلك. فأوحى الله سبحانه وتعالى إلى عبده محمد صلى الله عليه وسلم ما أوحى بواسطة جبريل عليه السلام. ما كذب قلب محمد صلى الله عليه وسلم ما رآه بصره.", "isBasmala": false, "translation_en": "He was within two bows' length, or closer.", "translation_id": "maka jadilah dia dekat (pada Muhammad sejarak) dua ujung busur panah atau lebih dekat (lagi).", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 10, "text": "فَأَوۡحَىٰۤ إِلَىٰ عَبۡدِهِۦ مَاۤ أَوۡحَىٰ ۝١٠", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "علَّم محمدًا صلى الله عليه وسلم مَلَك شديد القوة، ذو منظر حسن، وهو جبريل عليه السلام، الذي ظهر واستوى على صورته الحقيقية للرسول صلى الله عليه وسلم في الأفق الأعلى، وهو أفق الشمس عند مطلعها، ثم دنا جبريل من الرسول صلى الله عليه وسلم، فزاد في القرب، فكان دنوُّه مقدار قوسين أو أقرب من ذلك. فأوحى الله سبحانه وتعالى إلى عبده محمد صلى الله عليه وسلم ما أوحى بواسطة جبريل عليه السلام. ما كذب قلب محمد صلى الله عليه وسلم ما رآه بصره.", "isBasmala": false, "translation_en": "Then He revealed to His servant what He revealed.", "translation_id": "Lalu dia menyampaikan kepada hamba-Nya (Muhammad) apa yang telah Allah wahyukan.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 11, "text": "مَا كَذَبَ ٱلۡفُؤَادُ مَا رَأَىٰۤ ۝١١", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "علَّم محمدًا صلى الله عليه وسلم مَلَك شديد القوة، ذو منظر حسن، وهو جبريل عليه السلام، الذي ظهر واستوى على صورته الحقيقية للرسول صلى الله عليه وسلم في الأفق الأعلى، وهو أفق الشمس عند مطلعها، ثم دنا جبريل من الرسول صلى الله عليه وسلم، فزاد في القرب، فكان دنوُّه مقدار قوسين أو أقرب من ذلك. فأوحى الله سبحانه وتعالى إلى عبده محمد صلى الله عليه وسلم ما أوحى بواسطة جبريل عليه السلام. ما كذب قلب محمد صلى الله عليه وسلم ما رآه بصره.", "isBasmala": false, "translation_en": "The heart did not lie about what it saw.", "translation_id": "Hatinya tidak mendustakan apa yang telah dilihatnya.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 12, "text": "أَفَتُمَـٰرُونَهُۥ عَلَىٰ مَا یَرَىٰ ۝١٢", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتُكذِّبون محمدًا صلى الله عليه وسلم، فتجادلونه على ما يراه ويشاهده من آيات ربه؟ ولقد رأى محمد صلى الله عليه وسلم جبريل على صورته الحقيقية مرة أخرى عند سدرة المنتهى- شجرة نَبْق- وهي في السماء السابعة، ينتهي إليها ما يُعْرَج به من الأرض، وينتهي إليها ما يُهْبَط به من فوقها، عندها جنة المأوى التي وُعِد بها المتقون. إذ يغشى السدرة من أمر الله شيء عظيم، لا يعلم وصفه إلا الله عز وجل. وكان النبي صلى الله عليه وسلم على صفة عظيمة من الثبات والطاعة، فما مال بصره يمينًا ولا شمالا ولا جاوز ما أُمِر برؤيته. لقد رأى محمد صلى الله عليه وسلم ليلة المعراج من آيات ربه الكبرى الدالة على قدرة الله وعظمته من الجنة والنار وغير ذلك.", "isBasmala": false, "translation_en": "Will you dispute with him concerning what he saw?", "translation_id": "Maka apakah kaum (musyrik Mekah) hendak membantahnya tentang apa yang telah dilihatnya?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 13, "text": "وَلَقَدۡ رَءَاهُ نَزۡلَةً أُخۡرَىٰ ۝١٣", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتُكذِّبون محمدًا صلى الله عليه وسلم، فتجادلونه على ما يراه ويشاهده من آيات ربه؟ ولقد رأى محمد صلى الله عليه وسلم جبريل على صورته الحقيقية مرة أخرى عند سدرة المنتهى- شجرة نَبْق- وهي في السماء السابعة، ينتهي إليها ما يُعْرَج به من الأرض، وينتهي إليها ما يُهْبَط به من فوقها، عندها جنة المأوى التي وُعِد بها المتقون. إذ يغشى السدرة من أمر الله شيء عظيم، لا يعلم وصفه إلا الله عز وجل. وكان النبي صلى الله عليه وسلم على صفة عظيمة من الثبات والطاعة، فما مال بصره يمينًا ولا شمالا ولا جاوز ما أُمِر برؤيته. لقد رأى محمد صلى الله عليه وسلم ليلة المعراج من آيات ربه الكبرى الدالة على قدرة الله وعظمته من الجنة والنار وغير ذلك.", "isBasmala": false, "translation_en": "He saw him on another descent.", "translation_id": "Dan sesungguhnya Muhammad telah melihat Jibril itu (dalam rupanya yang asli) pada waktu yang lain,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 14, "text": "عِندَ سِدۡرَةِ ٱلۡمُنتَهَىٰ ۝١٤", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتُكذِّبون محمدًا صلى الله عليه وسلم، فتجادلونه على ما يراه ويشاهده من آيات ربه؟ ولقد رأى محمد صلى الله عليه وسلم جبريل على صورته الحقيقية مرة أخرى عند سدرة المنتهى- شجرة نَبْق- وهي في السماء السابعة، ينتهي إليها ما يُعْرَج به من الأرض، وينتهي إليها ما يُهْبَط به من فوقها، عندها جنة المأوى التي وُعِد بها المتقون. إذ يغشى السدرة من أمر الله شيء عظيم، لا يعلم وصفه إلا الله عز وجل. وكان النبي صلى الله عليه وسلم على صفة عظيمة من الثبات والطاعة، فما مال بصره يمينًا ولا شمالا ولا جاوز ما أُمِر برؤيته. لقد رأى محمد صلى الله عليه وسلم ليلة المعراج من آيات ربه الكبرى الدالة على قدرة الله وعظمته من الجنة والنار وغير ذلك.", "isBasmala": false, "translation_en": "At the Lotus Tree of the Extremity.", "translation_id": "(yaitu) di Sidratil Muntaha.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 15, "text": "عِندَهَا جَنَّةُ ٱلۡمَأۡوَىٰۤ ۝١٥", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتُكذِّبون محمدًا صلى الله عليه وسلم، فتجادلونه على ما يراه ويشاهده من آيات ربه؟ ولقد رأى محمد صلى الله عليه وسلم جبريل على صورته الحقيقية مرة أخرى عند سدرة المنتهى- شجرة نَبْق- وهي في السماء السابعة، ينتهي إليها ما يُعْرَج به من الأرض، وينتهي إليها ما يُهْبَط به من فوقها، عندها جنة المأوى التي وُعِد بها المتقون. إذ يغشى السدرة من أمر الله شيء عظيم، لا يعلم وصفه إلا الله عز وجل. وكان النبي صلى الله عليه وسلم على صفة عظيمة من الثبات والطاعة، فما مال بصره يمينًا ولا شمالا ولا جاوز ما أُمِر برؤيته. لقد رأى محمد صلى الله عليه وسلم ليلة المعراج من آيات ربه الكبرى الدالة على قدرة الله وعظمته من الجنة والنار وغير ذلك.", "isBasmala": false, "translation_en": "Near which is the Garden of Repose.", "translation_id": "Di dekatnya ada surga tempat tinggal,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 16, "text": "إِذۡ یَغۡشَى ٱلسِّدۡرَةَ مَا یَغۡشَىٰ ۝١٦", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتُكذِّبون محمدًا صلى الله عليه وسلم، فتجادلونه على ما يراه ويشاهده من آيات ربه؟ ولقد رأى محمد صلى الله عليه وسلم جبريل على صورته الحقيقية مرة أخرى عند سدرة المنتهى- شجرة نَبْق- وهي في السماء السابعة، ينتهي إليها ما يُعْرَج به من الأرض، وينتهي إليها ما يُهْبَط به من فوقها، عندها جنة المأوى التي وُعِد بها المتقون. إذ يغشى السدرة من أمر الله شيء عظيم، لا يعلم وصفه إلا الله عز وجل. وكان النبي صلى الله عليه وسلم على صفة عظيمة من الثبات والطاعة، فما مال بصره يمينًا ولا شمالا ولا جاوز ما أُمِر برؤيته. لقد رأى محمد صلى الله عليه وسلم ليلة المعراج من آيات ربه الكبرى الدالة على قدرة الله وعظمته من الجنة والنار وغير ذلك.", "isBasmala": false, "translation_en": "As there covered the Lotus Tree what covered it.", "translation_id": "(Muhammad melihat Jibril) ketika Sidratil Muntaha diliputi oleh sesuatu yang meliputinya.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 17, "text": "مَا زَاغَ ٱلۡبَصَرُ وَمَا طَغَىٰ ۝١٧", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتُكذِّبون محمدًا صلى الله عليه وسلم، فتجادلونه على ما يراه ويشاهده من آيات ربه؟ ولقد رأى محمد صلى الله عليه وسلم جبريل على صورته الحقيقية مرة أخرى عند سدرة المنتهى- شجرة نَبْق- وهي في السماء السابعة، ينتهي إليها ما يُعْرَج به من الأرض، وينتهي إليها ما يُهْبَط به من فوقها، عندها جنة المأوى التي وُعِد بها المتقون. إذ يغشى السدرة من أمر الله شيء عظيم، لا يعلم وصفه إلا الله عز وجل. وكان النبي صلى الله عليه وسلم على صفة عظيمة من الثبات والطاعة، فما مال بصره يمينًا ولا شمالا ولا جاوز ما أُمِر برؤيته. لقد رأى محمد صلى الله عليه وسلم ليلة المعراج من آيات ربه الكبرى الدالة على قدرة الله وعظمته من الجنة والنار وغير ذلك.", "isBasmala": false, "translation_en": "The sight did not waver, nor did it exceed.", "translation_id": "Penglihatannya (muhammad) tidak berpaling dari yang dilihatnya itu dan tidak (pula) melampauinya.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 18, "text": "لَقَدۡ رَأَىٰ مِنۡ ءَایَـٰتِ رَبِّهِ ٱلۡكُبۡرَىٰۤ ۝١٨", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتُكذِّبون محمدًا صلى الله عليه وسلم، فتجادلونه على ما يراه ويشاهده من آيات ربه؟ ولقد رأى محمد صلى الله عليه وسلم جبريل على صورته الحقيقية مرة أخرى عند سدرة المنتهى- شجرة نَبْق- وهي في السماء السابعة، ينتهي إليها ما يُعْرَج به من الأرض، وينتهي إليها ما يُهْبَط به من فوقها، عندها جنة المأوى التي وُعِد بها المتقون. إذ يغشى السدرة من أمر الله شيء عظيم، لا يعلم وصفه إلا الله عز وجل. وكان النبي صلى الله عليه وسلم على صفة عظيمة من الثبات والطاعة، فما مال بصره يمينًا ولا شمالا ولا جاوز ما أُمِر برؤيته. لقد رأى محمد صلى الله عليه وسلم ليلة المعراج من آيات ربه الكبرى الدالة على قدرة الله وعظمته من الجنة والنار وغير ذلك.", "isBasmala": false, "translation_en": "He saw some of the Great Signs of his Lord.", "translation_id": "Sesungguhnya dia telah melihat sebahagian tanda-tanda (kekuasaan) Tuhannya yang paling besar.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 19, "text": "أَفَرَءَیۡتُمُ ٱللَّـٰتَ وَٱلۡعُزَّىٰ ۝١٩", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أفرأيتم- أيها المشركون- هذه الآلهة التي تعبدونها: اللات والعزَّى ومناة الثالثة الأخرى، هل نفعت أو ضرَّت حتى تكون شركاء لله؟", "isBasmala": false, "translation_en": "Have you considered al-Lat and al-Uzza?", "translation_id": "Maka apakah patut kamu (hai orang-orang musyrik) menganggap al Lata dan al Uzza,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 20, "text": "وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰۤ ۝٢٠", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أفرأيتم- أيها المشركون- هذه الآلهة التي تعبدونها: اللات والعزَّى ومناة الثالثة الأخرى، هل نفعت أو ضرَّت حتى تكون شركاء لله؟", "isBasmala": false, "translation_en": "And Manat, the third one, the other?", "translation_id": "dan Manah yang ketiga, yang paling terkemudian (sebagai anak perempuan Allah)?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 21, "text": "أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ ۝٢١", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتجعلون لكم الذَّكر الذي ترضونه، وتجعلون لله بزعمكم الأنثى التي لا ترضونها لأنفسكم؟ تلك إذًا قسمة جائرة. ما هذه الأوثان إلا أسماء ليس لها من أوصاف الكمال شيء، إنما هي أسماء سميتموها أنتم وآباؤكم بمقتضى أهوائكم الباطلة، ما أنزل الله بها مِن حجة تصدق دعواكم فيها. ما يتبع هؤلاء المشركون إلا الظن، وهوى أنفسهم المنحرفة عن الفطرة السليمة، ولقد جاءهم من ربهم على لسان النبي صلى الله عليه وسلم، ما فيه هدايتهم، فما انتفعوا به.", "isBasmala": false, "translation_en": "Are you to have the males, and He the females?", "translation_id": "Apakah (patut) untuk kamu (anak) laki-laki dan untuk Allah (anak) perempuan?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 22, "text": "تِلۡكَ إِذࣰا قِسۡمَةࣱ ضِیزَىٰۤ ۝٢٢", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتجعلون لكم الذَّكر الذي ترضونه، وتجعلون لله بزعمكم الأنثى التي لا ترضونها لأنفسكم؟ تلك إذًا قسمة جائرة. ما هذه الأوثان إلا أسماء ليس لها من أوصاف الكمال شيء، إنما هي أسماء سميتموها أنتم وآباؤكم بمقتضى أهوائكم الباطلة، ما أنزل الله بها مِن حجة تصدق دعواكم فيها. ما يتبع هؤلاء المشركون إلا الظن، وهوى أنفسهم المنحرفة عن الفطرة السليمة، ولقد جاءهم من ربهم على لسان النبي صلى الله عليه وسلم، ما فيه هدايتهم، فما انتفعوا به.", "isBasmala": false, "translation_en": "What a bizarre distribution.", "translation_id": "Yang demikian itu tentulah suatu pembagian yang tidak adil.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 23, "text": "إِنۡ هِیَ إِلَّاۤ أَسۡمَاۤءࣱ سَمَّیۡتُمُوهَاۤ أَنتُمۡ وَءَابَاۤؤُكُم مَّاۤ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَـٰنٍۚ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَمَا تَهۡوَى ٱلۡأَنفُسُۖ وَلَقَدۡ جَاۤءَهُم مِّن رَّبِّهِمُ ٱلۡهُدَىٰۤ ۝٢٣", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "أتجعلون لكم الذَّكر الذي ترضونه، وتجعلون لله بزعمكم الأنثى التي لا ترضونها لأنفسكم؟ تلك إذًا قسمة جائرة. ما هذه الأوثان إلا أسماء ليس لها من أوصاف الكمال شيء، إنما هي أسماء سميتموها أنتم وآباؤكم بمقتضى أهوائكم الباطلة، ما أنزل الله بها مِن حجة تصدق دعواكم فيها. ما يتبع هؤلاء المشركون إلا الظن، وهوى أنفسهم المنحرفة عن الفطرة السليمة، ولقد جاءهم من ربهم على لسان النبي صلى الله عليه وسلم، ما فيه هدايتهم، فما انتفعوا به.", "isBasmala": false, "translation_en": "These are nothing but names, which you have devised, you and your ancestors, for which God sent down no authority. They follow nothing but assumptions, and what the ego desires, even though guidance has come to them from their Lord.", "translation_id": "Itu tidak lain hanyalah nama-nama yang kamu dan bapak-bapak kamu mengadakannya; Allah tidak menurunkan suatu keteranganpun untuk (menyembah)nya. Mereka tidak lain hanyalah mengikuti sangkaan-sangkaan, dan apa yang diingini oleh hawa nafsu mereka dan sesungguhnya telah datang petunjuk kepada mereka dari Tuhan mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 24, "text": "أَمۡ لِلۡإِنسَـٰنِ مَا تَمَنَّىٰ ۝٢٤", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "ليس للإنسان ما تمناه من شفاعة هذه المعبودات أو غيرها مما تهواه نفسه، فلله أمر الدنيا والآخرة.", "isBasmala": false, "translation_en": "Or is the human being to have whatever he desires?", "translation_id": "Atau apakah manusia akan mendapat segala yang dicita-citakannya?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 25, "text": "فَلِلَّهِ ٱلۡـَٔاخِرَةُ وَٱلۡأُولَىٰ ۝٢٥", "juz": 27, "hizb": "(*¼ ح 53*)", "tafsir": "ليس للإنسان ما تمناه من شفاعة هذه المعبودات أو غيرها مما تهواه نفسه، فلله أمر الدنيا والآخرة.", "isBasmala": false, "translation_en": "To God belong the Last and the First.", "translation_id": "(Tidak), maka hanya bagi Allah kehidupan akhirat dan kehidupan dunia.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 26, "text": "۞ وَكَم مِّن مَّلَكࣲ فِی ٱلسَّمَـٰوَ ٰتِ لَا تُغۡنِی شَفَـٰعَتُهُمۡ شَیۡـًٔا إِلَّا مِنۢ بَعۡدِ أَن یَأۡذَنَ ٱللَّهُ لِمَن یَشَاۤءُ وَیَرۡضَىٰۤ ۝٢٦", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وكثير من الملائكة في السموات مع علوِّ منزلتهم، لا تنفع شفاعتهم شيئًا إلا من بعد أن يأذن الله لهم بالشفاعة، ويرضى عن المشفوع له.", "isBasmala": false, "translation_en": "How many an angel is there in the heavens whose intercession avails nothing, except after God gives permission to whomever He wills, and approves?", "translation_id": "Dan berapa banyaknya malaikat di langit, syafa'at mereka sedikitpun tidak berguna, kecuali sesudah Allah mengijinkan bagi orang yang dikehendaki dan diridhai (Nya).", "manzil": 7, "manzil_display": ""}], "527": [{"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 27, "text": "إِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ لَیُسَمُّونَ ٱلۡمَلَـٰۤىِٕكَةَ تَسۡمِیَةَ ٱلۡأُنثَىٰ ۝٢٧", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "إن الذين لا يصدِّقون بالحياة الآخرة من كفار العرب ولا يعملون لها ليسمُّون الملائكة تسمية الإناث؛ لاعتقادهم جهلا أن الملائكة إناث، وأنهم بنات الله. وما لهم بذلك من علم صحيح يصدِّق ما قالوه، ما يتبعون إلا الظن الذي لا يجدي شيئًا، ولا يقوم أبدًا مقام الحق.", "isBasmala": false, "translation_en": "Those who do not believe in the Hereafter give the angels the names of females.", "translation_id": "Sesungguhnya orang-orang yang tiada beriman kepada kehidupan akhirat, mereka benar-benar menamakan malaikat itu dengan nama perempuan.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 28, "text": "وَمَا لَهُم بِهِۦ مِنۡ عِلۡمٍۖ إِن یَتَّبِعُونَ إِلَّا ٱلظَّنَّۖ وَإِنَّ ٱلظَّنَّ لَا یُغۡنِی مِنَ ٱلۡحَقِّ شَیۡـࣰٔا ۝٢٨", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "إن الذين لا يصدِّقون بالحياة الآخرة من كفار العرب ولا يعملون لها ليسمُّون الملائكة تسمية الإناث؛ لاعتقادهم جهلا أن الملائكة إناث، وأنهم بنات الله. وما لهم بذلك من علم صحيح يصدِّق ما قالوه، ما يتبعون إلا الظن الذي لا يجدي شيئًا، ولا يقوم أبدًا مقام الحق.", "isBasmala": false, "translation_en": "They have no knowledge of that. They only follow assumptions, and assumptions are no substitute for the truth.", "translation_id": "Dan mereka tidak mempunyai sesuatu pengetahuanpun tentang itu. Mereka tidak lain hanyalah mengikuti persangkaan sedang sesungguhnya persangkaan itu tiada berfaedah sedikitpun terhadap kebenaran.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 29, "text": "فَأَعۡرِضۡ عَن مَّن تَوَلَّىٰ عَن ذِكۡرِنَا وَلَمۡ یُرِدۡ إِلَّا ٱلۡحَیَوٰةَ ٱلدُّنۡیَا ۝٢٩", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "فأعْرِضْ عمَّن تولى عن ذكرنا، وهو القرآن، ولم يُرِدْ إلا الحياة الدنيا. ذلك الذي هم عليه هو منتهى علمهم وغايتهم. إن ربك هو أعلم بمن حادَ عن طريق الهدى، وهو أعلم بمن اهتدى وسلك طريق الإسلام. وفي هذا إنذار شديد للعصاة المعرضين عن العمل بكتاب الله، وسنة رسوله صلى الله عليه وسلم، المؤثرين لهوى النفس وحظوظ الدنيا على الآخرة.", "isBasmala": false, "translation_en": "So avoid him who has turned away from Our remembrance, and desires nothing but the present life.", "translation_id": "Maka berpalinglah (hai Muhammad) dari orang yang berpaling dari peringatan Kami, dan tidak mengingini kecuali kehidupan duniawi.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 30, "text": "ذَ ٰلِكَ مَبۡلَغُهُم مِّنَ ٱلۡعِلۡمِۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِیلِهِۦ وَهُوَ أَعۡلَمُ بِمَنِ ٱهۡتَدَىٰ ۝٣٠", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "فأعْرِضْ عمَّن تولى عن ذكرنا، وهو القرآن، ولم يُرِدْ إلا الحياة الدنيا. ذلك الذي هم عليه هو منتهى علمهم وغايتهم. إن ربك هو أعلم بمن حادَ عن طريق الهدى، وهو أعلم بمن اهتدى وسلك طريق الإسلام. وفي هذا إنذار شديد للعصاة المعرضين عن العمل بكتاب الله، وسنة رسوله صلى الله عليه وسلم، المؤثرين لهوى النفس وحظوظ الدنيا على الآخرة.", "isBasmala": false, "translation_en": "That is the extent of their knowledge. Your Lord knows best who has strayed from His path, and He knows best who has accepted guidance.", "translation_id": "Itulah sejauh-jauh pengetahuan mereka. Sesungguhnya Tuhanmu, Dialah yang paling mengetahui siapa yang tersesat dari jalan-Nya dan Dia pulalah yang paling mengetahui siapa yang mendapat petunjuk.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 31, "text": "وَلِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِ لِیَجۡزِیَ ٱلَّذِینَ أَسَـٰۤـُٔوا۟ بِمَا عَمِلُوا۟ وَیَجۡزِیَ ٱلَّذِینَ أَحۡسَنُوا۟ بِٱلۡحُسۡنَى ۝٣١", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "والله سبحانه وتعالى ملك ما في السموات وما في الأرض؛ ليجزي الذين أساءوا بعقابهم على ما عملوا من السوء، ويجزي الذي أحسنوا بالجنة، وهم الذين يبتعدون عن كبائر الذنوب والفواحش إلا اللمم، وهي الذنوب الصغار التي لا يُصِرُّ صاحبها عليها، أو يلمُّ بها العبد على وجه الندرة، فإن هذه مع الإتيان بالواجبات وترك المحرمات، يغفرها الله لهم ويسترها عليهم، إن ربك واسع المغفرة، هو أعلم بأحوالكم حين خلق أباكم آدم من تراب، وحين أنتم أجنَّة في بطون أمهاتكم، فلا تزكُّوا أنفسكم فتمدحوها وتَصِفُوها بالتقوى، هو أعلم بمن اتقى عقابه فاجتنب معاصيه من عباده.", "isBasmala": false, "translation_en": "To God belongs whatever is in the heavens and whatever is on earth. He will repay those who do evil according to their deeds, and recompense those who do good with the best.", "translation_id": "Dan hanya kepunyaan Allah-lah apa yang ada di langit dan apa yang ada di bumi supaya Dia memberi balasan kepada orang-orang yang berbuat jahat terhadap apa yang telah mereka kerjakan dan memberi balasan kepada orang-orang yang berbuat baik dengan pahala yang lebih baik (surga).", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 32, "text": "ٱلَّذِینَ یَجۡتَنِبُونَ كَبَـٰۤىِٕرَ ٱلۡإِثۡمِ وَٱلۡفَوَ ٰحِشَ إِلَّا ٱللَّمَمَۚ إِنَّ رَبَّكَ وَ ٰسِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَإِذۡ أَنتُمۡ أَجِنَّةࣱ فِی بُطُونِ أُمَّهَـٰتِكُمۡۖ فَلَا تُزَكُّوۤا۟ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰۤ ۝٣٢", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "والله سبحانه وتعالى ملك ما في السموات وما في الأرض؛ ليجزي الذين أساءوا بعقابهم على ما عملوا من السوء، ويجزي الذي أحسنوا بالجنة، وهم الذين يبتعدون عن كبائر الذنوب والفواحش إلا اللمم، وهي الذنوب الصغار التي لا يُصِرُّ صاحبها عليها، أو يلمُّ بها العبد على وجه الندرة، فإن هذه مع الإتيان بالواجبات وترك المحرمات، يغفرها الله لهم ويسترها عليهم، إن ربك واسع المغفرة، هو أعلم بأحوالكم حين خلق أباكم آدم من تراب، وحين أنتم أجنَّة في بطون أمهاتكم، فلا تزكُّوا أنفسكم فتمدحوها وتَصِفُوها بالتقوى، هو أعلم بمن اتقى عقابه فاجتنب معاصيه من عباده.", "isBasmala": false, "translation_en": "Those who avoid gross sins and indecencies-except for minor lapses-your Lord is of Vast Forgiveness. He knows you well, ever since He created you from the earth, and ever since you were embryos in your mothers' wombs. So do not acclaim your own virtue; He is fully aware of the righteous.", "translation_id": "(Yaitu) orang-orang yang menjauhi dosa-dosa besar dan perbuatan keji yang selain dari kesalahan-kesalahan kecil. Sesungguhnya Tuhanmu maha luas ampunan-Nya. Dan Dia lebih mengetahui (tentang keadaan)mu ketika Dia menjadikan kamu dari tanah dan ketika kamu masih janin dalam perut ibumu; maka janganlah kamu mengatakan dirimu suci. Dialah yang paling mengetahui tentang orang yang bertakwa.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 33, "text": "أَفَرَءَیۡتَ ٱلَّذِی تَوَلَّىٰ ۝٣٣", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أفرأيت -أيها الرسول- الذي أعرض عن طاعة الله وأعطى قليلا مِن ماله، ثم توقف عن العطاء وقطع معروفه؟", "isBasmala": false, "translation_en": "Have you considered him who turned away?", "translation_id": "Maka apakah kamu melihat orang yang berpaling (dari Al-Quran)?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 34, "text": "وَأَعۡطَىٰ قَلِیلࣰا وَأَكۡدَىٰۤ ۝٣٤", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أفرأيت -أيها الرسول- الذي أعرض عن طاعة الله وأعطى قليلا مِن ماله، ثم توقف عن العطاء وقطع معروفه؟", "isBasmala": false, "translation_en": "And gave a little, and held back?", "translation_id": "serta memberi sedikit dan tidak mau memberi lagi?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 35, "text": "أَعِندَهُۥ عِلۡمُ ٱلۡغَیۡبِ فَهُوَ یَرَىٰۤ ۝٣٥", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أعند هذا الذي قطع عطاءه علم الغيب أنه سينفَد ما في يده حتى أمسك معروفه، فهو يرى ذلك عِيانًا؟ ليس الأمر كذلك، وإنما أمسك عن الصدقة والمعروف والبر والصلة؛ بخلا وشُحًّا.", "isBasmala": false, "translation_en": "Does he possess knowledge of the unseen, and can therefore foresee?", "translation_id": "Apakah dia mempunyai pengetahuan tentang yang ghaib, sehingga dia mengetahui (apa yang dikatakan)?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 36, "text": "أَمۡ لَمۡ یُنَبَّأۡ بِمَا فِی صُحُفِ مُوسَىٰ ۝٣٦", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أم لم يُخَبَّر بما جاء في أسفار التوراة وصحف إبراهيم الذي وفَّى ما أُمر به وبلَّغه؟", "isBasmala": false, "translation_en": "Or was he not informed of what is in the Scrolls of Moses?", "translation_id": "Ataukah belum diberitakan kepadanya apa yang ada dalam lembaran-lembaran Musa?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 37, "text": "وَإِبۡرَ ٰهِیمَ ٱلَّذِی وَفَّىٰۤ ۝٣٧", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أم لم يُخَبَّر بما جاء في أسفار التوراة وصحف إبراهيم الذي وفَّى ما أُمر به وبلَّغه؟", "isBasmala": false, "translation_en": "And of Abraham, who fulfilled?", "translation_id": "dan lembaran-lembaran Ibrahim yang selalu menyempurnakan janji?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 38, "text": "أَلَّا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰ ۝٣٨", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أنه لا تؤخذ نفس بمأثم غيرها، ووزرها لا يحمله عنها أحد، وأنه لا يحصل للإنسان من الأجر إلا ما كسب هو لنفسه بسعيه.", "isBasmala": false, "translation_en": "That no soul bears the burdens of another soul.", "translation_id": "(yaitu) bahwasanya seorang yang berdosa tidak akan memikul dosa orang lain,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 39, "text": "وَأَن لَّیۡسَ لِلۡإِنسَـٰنِ إِلَّا مَا سَعَىٰ ۝٣٩", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أنه لا تؤخذ نفس بمأثم غيرها، ووزرها لا يحمله عنها أحد، وأنه لا يحصل للإنسان من الأجر إلا ما كسب هو لنفسه بسعيه.", "isBasmala": false, "translation_en": "And that the human being attains only what he strives for.", "translation_id": "dan bahwasanya seorang manusia tiada memperoleh selain apa yang telah diusahakannya,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 40, "text": "وَأَنَّ سَعۡیَهُۥ سَوۡفَ یُرَىٰ ۝٤٠", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأن سعيه سوف يُرى في الآخرة، فيميَّز حَسَنه من سيئه؛ تشريفًا للمحسن وتوبيخًا للمسيء.", "isBasmala": false, "translation_en": "And that his efforts will be witnessed.", "translation_id": "dan bahwasanya usaha itu kelak akan diperlihatkan (kepadanya).", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 41, "text": "ثُمَّ یُجۡزَىٰهُ ٱلۡجَزَاۤءَ ٱلۡأَوۡفَىٰ ۝٤١", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "ثم يُجزى الإنسان على سعيه الجزاء المستكمل لجميع عمله، وأنَّ إلى ربك -أيها الرسول- انتهاء جميع خلقه يوم القيامة.", "isBasmala": false, "translation_en": "Then he will be rewarded for it the fullest reward.", "translation_id": "Kemudian akan diberi balasan kepadanya dengan balasan yang paling sempurna,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 42, "text": "وَأَنَّ إِلَىٰ رَبِّكَ ٱلۡمُنتَهَىٰ ۝٤٢", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "ثم يُجزى الإنسان على سعيه الجزاء المستكمل لجميع عمله، وأنَّ إلى ربك -أيها الرسول- انتهاء جميع خلقه يوم القيامة.", "isBasmala": false, "translation_en": "And that to your Lord is the finality.", "translation_id": "dan bahwasanya kepada Tuhanmulah kesudahan (segala sesuatu),", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 43, "text": "وَأَنَّهُۥ هُوَ أَضۡحَكَ وَأَبۡكَىٰ ۝٤٣", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه سبحانه وتعالى أضحك مَن شاء في الدنيا بأن سرَّه، وأبكى من شاء بأن غَمَّه.", "isBasmala": false, "translation_en": "And that it is He who causes laughter and weeping.", "translation_id": "dan bahwasanya Dialah yang menjadikan orang tertawa dan menangis,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 44, "text": "وَأَنَّهُۥ هُوَ أَمَاتَ وَأَحۡیَا ۝٤٤", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه سبحانه أمات مَن أراد موته مِن خلقه، وأحيا مَن أراد حياته منهم، فهو المتفرِّد سبحانه بالإحياء والإماتة.", "isBasmala": false, "translation_en": "And that it is He who gives death and life.", "translation_id": "dan bahwasanya Dialah yang mematikan dan menghidupkan,", "manzil": 7, "manzil_display": ""}], "528": [{"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 45, "text": "وَأَنَّهُۥ خَلَقَ ٱلزَّوۡجَیۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰ ۝٤٥", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه خلق الزوجين: الذكر والأنثى من الإنسان والحيوان، من نطفة تُصَبُّ في الرحم.", "isBasmala": false, "translation_en": "And that it is He who created the two kinds-the male and the female.", "translation_id": "dan bahwasanya Dialah yang menciptakan berpasang-pasangan pria dan wanita.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 46, "text": "مِن نُّطۡفَةٍ إِذَا تُمۡنَىٰ ۝٤٦", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه خلق الزوجين: الذكر والأنثى من الإنسان والحيوان، من نطفة تُصَبُّ في الرحم.", "isBasmala": false, "translation_en": "From a sperm drop, when emitted.", "translation_id": "dari air mani, apabila dipancarkan.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 47, "text": "وَأَنَّ عَلَیۡهِ ٱلنَّشۡأَةَ ٱلۡأُخۡرَىٰ ۝٤٧", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأن على ربك -أيها الرسول- إعادة خلقهم بعد مماتهم، وهي النشأة الأخرى يوم القيامة.", "isBasmala": false, "translation_en": "And that upon Him is the next existence.", "translation_id": "Dan bahwasanya Dialah yang menetapkan kejadian yang lain (kebangkitan sesudah mati),", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 48, "text": "وَأَنَّهُۥ هُوَ أَغۡنَىٰ وَأَقۡنَىٰ ۝٤٨", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه هو أغنى مَن شاء مِن خلقه بالمال، وملَّكه لهم وأرضاهم به.", "isBasmala": false, "translation_en": "And that it is He who enriches and impoverishes.", "translation_id": "dan bahwasanya Dia yang memberikan kekayaan dan memberikan kecukupan,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 49, "text": "وَأَنَّهُۥ هُوَ رَبُّ ٱلشِّعۡرَىٰ ۝٤٩", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه سبحانه وتعالى هو رب الشِّعْرى، وهو نجم مضيء، كان بعض أهل الجاهلية يعبدونه من دون الله.", "isBasmala": false, "translation_en": "And that it is He who is the Lord of Sirius.", "translation_id": "dan bahwasanya Dialah yang Tuhan (yang memiliki) bintang syi'ra,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 50, "text": "وَأَنَّهُۥۤ أَهۡلَكَ عَادًا ٱلۡأُولَىٰ ۝٥٠", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه سبحانه وتعالى أهلك عادًا الأولى، وهم قوم هود، وأهلك ثمود، وهم قوم صالح، فلم يُبْقِ منهم أحدًا، وأهلك قوم نوح قبلُ. هؤلاء كانوا أشد تمردًا وأعظم كفرًا من الذين جاؤوا من بعدهم. ومدائن قوم لوط قلبها الله عليهم، وجعل عاليها سافلها، فألبسها ما ألبسها من الحجارة.", "isBasmala": false, "translation_en": "And that it is He who destroyed the first Aad.", "translation_id": "dan bahwasanya Dia telah membinasakan kaum 'Aad yang pertama,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 51, "text": "وَثَمُودَا۟ فَمَاۤ أَبۡقَىٰ ۝٥١", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه سبحانه وتعالى أهلك عادًا الأولى، وهم قوم هود، وأهلك ثمود، وهم قوم صالح، فلم يُبْقِ منهم أحدًا، وأهلك قوم نوح قبلُ. هؤلاء كانوا أشد تمردًا وأعظم كفرًا من الذين جاؤوا من بعدهم. ومدائن قوم لوط قلبها الله عليهم، وجعل عاليها سافلها، فألبسها ما ألبسها من الحجارة.", "isBasmala": false, "translation_en": "And Thamood, sparing no one.", "translation_id": "dan kaum Tsamud. Maka tidak seorangpun yang ditinggalkan-Nya (hidup).", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 52, "text": "وَقَوۡمَ نُوحࣲ مِّن قَبۡلُۖ إِنَّهُمۡ كَانُوا۟ هُمۡ أَظۡلَمَ وَأَطۡغَىٰ ۝٥٢", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه سبحانه وتعالى أهلك عادًا الأولى، وهم قوم هود، وأهلك ثمود، وهم قوم صالح، فلم يُبْقِ منهم أحدًا، وأهلك قوم نوح قبلُ. هؤلاء كانوا أشد تمردًا وأعظم كفرًا من الذين جاؤوا من بعدهم. ومدائن قوم لوط قلبها الله عليهم، وجعل عاليها سافلها، فألبسها ما ألبسها من الحجارة.", "isBasmala": false, "translation_en": "And the people of Noah before that; for they were most unjust and most oppressive.", "translation_id": "Dan kaum Nuh sebelum itu. Sesungguhnya mereka adalah orang-orang yang paling zalim dan paling durhaka,", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 53, "text": "وَٱلۡمُؤۡتَفِكَةَ أَهۡوَىٰ ۝٥٣", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه سبحانه وتعالى أهلك عادًا الأولى، وهم قوم هود، وأهلك ثمود، وهم قوم صالح، فلم يُبْقِ منهم أحدًا، وأهلك قوم نوح قبلُ. هؤلاء كانوا أشد تمردًا وأعظم كفرًا من الذين جاؤوا من بعدهم. ومدائن قوم لوط قلبها الله عليهم، وجعل عاليها سافلها، فألبسها ما ألبسها من الحجارة.", "isBasmala": false, "translation_en": "And He toppled the ruined cities.", "translation_id": "dan negeri-negeri kaum Luth yang telah dihancurkan Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 54, "text": "فَغَشَّىٰهَا مَا غَشَّىٰ ۝٥٤", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وأنه سبحانه وتعالى أهلك عادًا الأولى، وهم قوم هود، وأهلك ثمود، وهم قوم صالح، فلم يُبْقِ منهم أحدًا، وأهلك قوم نوح قبلُ. هؤلاء كانوا أشد تمردًا وأعظم كفرًا من الذين جاؤوا من بعدهم. ومدائن قوم لوط قلبها الله عليهم، وجعل عاليها سافلها، فألبسها ما ألبسها من الحجارة.", "isBasmala": false, "translation_en": "And covered them with whatever covered them.", "translation_id": "lalu Allah menimpakan atas negeri itu azab besar yang menimpanya.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 55, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكَ تَتَمَارَىٰ ۝٥٥", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "فبأيِّ نعم ربك عليك- أيها الإنسان المكذب- تَشُك؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels can you deny?", "translation_id": "Maka terhadap nikmat Tuhanmu yang manakah kamu ragu-ragu?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 56, "text": "هَـٰذَا نَذِیرࣱ مِّنَ ٱلنُّذُرِ ٱلۡأُولَىٰۤ ۝٥٦", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "هذا محمد صلى الله عليه وسلم، نذير بالحق الذي أنذر به الأنبياء قبله، فليس ببدع من الرسل.", "isBasmala": false, "translation_en": "This is a warning, just like the first warnings.", "translation_id": "Ini (Muhammad) adalah seorang pemberi peringatan di antara pemberi-pemberi peringatan yang terdahulu.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 57, "text": "أَزِفَتِ ٱلۡـَٔازِفَةُ ۝٥٧", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "قربت القيامة ودنا وقتها، لا يدفعها إذًا من دون الله أحد، ولا يَطَّلِع على وقت وقوعها إلا الله.", "isBasmala": false, "translation_en": "The inevitable is imminent.", "translation_id": "Telah dekat terjadinya hari kiamat.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 58, "text": "لَیۡسَ لَهَا مِن دُونِ ٱللَّهِ كَاشِفَةٌ ۝٥٨", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "قربت القيامة ودنا وقتها، لا يدفعها إذًا من دون الله أحد، ولا يَطَّلِع على وقت وقوعها إلا الله.", "isBasmala": false, "translation_en": "None besides God can unveil it.", "translation_id": "Tidak ada yang akan menyatakan terjadinya hari itu selain Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 59, "text": "أَفَمِنۡ هَـٰذَا ٱلۡحَدِیثِ تَعۡجَبُونَ ۝٥٩", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أفمِن هذا القرآن تعجبون -أيها المشركون- من أن يكون صحيحًا، وتضحكون منه سخرية واستهزاءً، ولا تبكون خوفًا من وعيده، وأنتم لاهون معرضون عنه؟ فاسجدوا لله وأخلصوا العبادة له وحده، وسلِّموا له أموركم.", "isBasmala": false, "translation_en": "Do you marvel at this discourse?", "translation_id": "Maka apakah kamu merasa heran terhadap pemberitaan ini?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 60, "text": "وَتَضۡحَكُونَ وَلَا تَبۡكُونَ ۝٦٠", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أفمِن هذا القرآن تعجبون -أيها المشركون- من أن يكون صحيحًا، وتضحكون منه سخرية واستهزاءً، ولا تبكون خوفًا من وعيده، وأنتم لاهون معرضون عنه؟ فاسجدوا لله وأخلصوا العبادة له وحده، وسلِّموا له أموركم.", "isBasmala": false, "translation_en": "And laugh, and do not weep?", "translation_id": "Dan kamu mentertawakan dan tidak menangis?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 61, "text": "وَأَنتُمۡ سَـٰمِدُونَ ۝٦١", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أفمِن هذا القرآن تعجبون -أيها المشركون- من أن يكون صحيحًا، وتضحكون منه سخرية واستهزاءً، ولا تبكون خوفًا من وعيده، وأنتم لاهون معرضون عنه؟ فاسجدوا لله وأخلصوا العبادة له وحده، وسلِّموا له أموركم.", "isBasmala": false, "translation_en": "Lost in your frivolity?", "translation_id": "Sedang kamu melengahkan(nya)?", "manzil": 7, "manzil_display": ""}, {"sura": 53, "sura_name": "النجم", "revelation": "Makkiyah", "aya": 62, "text": "فَ̅ٱ̅سۡ̅جُ̅دُ̅و̅ا۟̅ لِلَّهِ وَٱعۡبُدُوا۟ ۝٦٢ ۩", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "أفمِن هذا القرآن تعجبون -أيها المشركون- من أن يكون صحيحًا، وتضحكون منه سخرية واستهزاءً، ولا تبكون خوفًا من وعيده، وأنتم لاهون معرضون عنه؟ فاسجدوا لله وأخلصوا العبادة له وحده، وسلِّموا له أموركم.", "isBasmala": false, "translation_en": "So bow down to God, and worship!", "translation_id": "Maka bersujudlah kepada Allah dan sembahlah (Dia).", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 27, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 1, "text": "ٱقۡتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلۡقَمَرُ ۝١", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "دنت القيامة، وانفلق القمر فلقتين، حين سأل كفار \"مكة\" النبي صلى الله عليه وسلم أن يريهم آية، فدعا الله، فأراهم تلك الآية.", "isBasmala": false, "translation_en": "The Hour has drawn near, and the moon has split.", "translation_id": "Telah dekat datangnya saat itu dan telah terbelah bulan.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 2, "text": "وَإِن یَرَوۡا۟ ءَایَةࣰ یُعۡرِضُوا۟ وَیَقُولُوا۟ سِحۡرࣱ مُّسۡتَمِرࣱّ ۝٢", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وإن ير المشركون دليلا وبرهانًا على صدق الرسول محمد صلى الله عليه وسلم، يُعرضوا عن الإيمان به وتصديقه مكذبين منكرين، ويقولوا بعد ظهور الدليل: هذا سحر باطل ذاهب مضمحل لا دوام له.", "isBasmala": false, "translation_en": "Yet whenever they see a miracle, they turn away, and say, \"Continuous magic.\"", "translation_id": "Dan jika mereka (orang-orang musyrikin) melihat suatu tanda (mukjizat), mereka berpaling dan berkata: \"(Ini adalah) sihir yang terus menerus\".", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 3, "text": "وَكَذَّبُوا۟ وَٱتَّبَعُوۤا۟ أَهۡوَاۤءَهُمۡۚ وَكُلُّ أَمۡرࣲ مُّسۡتَقِرࣱّ ۝٣", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "وكذَّبوا النبي صلى الله عليه وسلم، واتبعوا ضلالتهم وما دعتهم إليه أهواؤهم من التكذيب، وكلُّ أمر من خير أو شر واقع بأهله يوم القيامة عند ظهور الثواب والعقاب.", "isBasmala": false, "translation_en": "They lied, and followed their opinions, but everything has its time.", "translation_id": "Dan mereka mendutakan (Nabi) dan mengikuti hawa nafsu mereka, sedang tiap-tiap urusan telah ada ketetapannya", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 4, "text": "وَلَقَدۡ جَاۤءَهُم مِّنَ ٱلۡأَنۢبَاۤءِ مَا فِیهِ مُزۡدَجَرٌ ۝٤", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "ولقد جاء كفار قريش من أنباء الأمم المكذبة برسلها، وما حلَّ بها من العذاب، ما فيه كفاية لردعهم عن كفرهم وضلالهم.", "isBasmala": false, "translation_en": "And there came to them news containing a deterrent.", "translation_id": "Dan sesungguhnya telah datang kepada mereka beberapa kisah yang di dalamnya terdapat cegahan (dari kekafiran).", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 5, "text": "حِكۡمَةُۢ بَـٰلِغَةࣱۖ فَمَا تُغۡنِ ٱلنُّذُرُ ۝٥", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "هذا القرآن الذي جاءهم حكمة عظيمة بالغة غايتها، فأي شيء تغني النذر عن قوم أعرضوا وكذَّبوا بها؟", "isBasmala": false, "translation_en": "Profound wisdom-but warnings are of no avail.", "translation_id": "Itulah suatu hikmah yang sempurna maka peringatan-peringatan itu tidak berguna (bagi mereka).", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 6, "text": "فَتَوَلَّ عَنۡهُمۡۘ یَوۡمَ یَدۡعُ ٱلدَّاعِ إِلَىٰ شَیۡءࣲ نُّكُرٍ ۝٦", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "فأعرض -أيها الرسول- عنهم، وانتظر بهم يومًا عظيمًا. يوم يدعو الملك بنفخه في \"القرن\" إلى أمر فظيع منكر، وهو موقف الحساب.", "isBasmala": false, "translation_en": "So turn away from them. On the Day when the Caller calls to something terrible.", "translation_id": "Maka berpalinglah kamu dari mereka. (Ingatlah) hari (ketika) seorang penyeru (malaikat) menyeru kepada sesuatu yang tidak menyenangkan (hari pembalasan),", "manzil": 7, "manzil_display": ""}], "529": [{"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 7, "text": "خُشَّعًا أَبۡصَـٰرُهُمۡ یَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ كَأَنَّهُمۡ جَرَادࣱ مُّنتَشِرࣱ ۝٧", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "ذليلة أبصارهم يخرجون من القبور كأنهم في انتشارهم وسرعة سيرهم للحساب جرادٌ منتشر في الآفاق، مسرعين إلى ما دُعُوا إليه، يقول الكافرون: هذا يوم عسر شديد الهول.", "isBasmala": false, "translation_en": "Their eyes humiliated, they will emerge from the graves, as if they were swarming locusts.", "translation_id": "sambil menundukkan pandangan-pandangan mereka keluar dari kuburan seakan-akan mereka belalang yang beterbangan", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 8, "text": "مُّهۡطِعِینَ إِلَى ٱلدَّاعِۖ یَقُولُ ٱلۡكَـٰفِرُونَ هَـٰذَا یَوۡمٌ عَسِرࣱ ۝٨", "juz": 27, "hizb": "(*½ ح 53*)", "tafsir": "ذليلة أبصارهم يخرجون من القبور كأنهم في انتشارهم وسرعة سيرهم للحساب جرادٌ منتشر في الآفاق، مسرعين إلى ما دُعُوا إليه، يقول الكافرون: هذا يوم عسر شديد الهول.", "isBasmala": false, "translation_en": "Scrambling towards the Caller, the disbelievers will say, \"This is a difficult Day.\"", "translation_id": "mereka datang dengan cepat kepada penyeru itu. Orang-orang kafir berkata: \"Ini adalah hari yang berat\".", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 9, "text": "۞ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ فَكَذَّبُوا۟ عَبۡدَنَا وَقَالُوا۟ مَجۡنُونࣱ وَٱزۡدُجِرَ ۝٩", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "كذَّبت قبل قومك -أيها الرسول- قوم نوح فكذَّبوا عبدنا نوحًا، وقالوا: هو مجنون، وانتهروه متوعدين إياه بأنواع الأذى، إن لم ينته عن دعوته.", "isBasmala": false, "translation_en": "Before them the people of Noah disbelieved. They rejected Our servant, and said, \"Crazy,\" and he was rebuked.", "translation_id": "Sebelum mereka, telah mendustakan (pula) kamu Nuh, maka mereka mendustakan hamba Kami (Nuh) dan mengatakan: \"Dia seorang gila dan dia sudah pernah diberi ancaman).", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 10, "text": "فَدَعَا رَبَّهُۥۤ أَنِّی مَغۡلُوبࣱ فَٱنتَصِرۡ ۝١٠", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "فدعا نوح ربه أنِّي ضعيف عن مقاومة هؤلاء، فانتصر لي بعقاب من عندك على كفرهم بك.", "isBasmala": false, "translation_en": "So he appealed to his Lord, \"I am overwhelmed, so help me.\"", "translation_id": "Maka dia mengadu kepada Tuhannya: \"bahwasanya aku ini adalah orang yang dikalahkan, oleh sebab itu menangkanlah (aku)\".", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 11, "text": "فَفَتَحۡنَاۤ أَبۡوَ ٰبَ ٱلسَّمَاۤءِ بِمَاۤءࣲ مُّنۡهَمِرࣲ ۝١١", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "فأجبنا دعاءه، ففتحنا أبواب السماء بماء كثير متدفق، وشققنا الأرض عيونًا متفجرة بالماء، فالتقى ماء السماء وماء الأرض على إهلاكهم الذي قدَّره الله لهم؛ جزاء شركهم.", "isBasmala": false, "translation_en": "So We opened the floodgates of heaven with water pouring down.", "translation_id": "Maka Kami bukakan pintu-pintu langit dengan (menurunkan) air yang tercurah.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 12, "text": "وَفَجَّرۡنَا ٱلۡأَرۡضَ عُیُونࣰا فَٱلۡتَقَى ٱلۡمَاۤءُ عَلَىٰۤ أَمۡرࣲ قَدۡ قُدِرَ ۝١٢", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "فأجبنا دعاءه، ففتحنا أبواب السماء بماء كثير متدفق، وشققنا الأرض عيونًا متفجرة بالماء، فالتقى ماء السماء وماء الأرض على إهلاكهم الذي قدَّره الله لهم؛ جزاء شركهم.", "isBasmala": false, "translation_en": "And We made the earth burst with springs, and the waters met for a purpose already destined.", "translation_id": "Dan Kami jadikan bumi memancarkan mata air-mata air, maka bertemulah air-air itu untuk suatu urusan yang sungguh telah ditetapkan.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 13, "text": "وَحَمَلۡنَـٰهُ عَلَىٰ ذَاتِ أَلۡوَ ٰحࣲ وَدُسُرࣲ ۝١٣", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "وحملنا نوحًا ومَن معه على سفينة ذات ألواح ومسامير شُدَّت بها، تجري بمرأى منا وحفظ، وأغرقنا المكذبين؛ جزاء لهم على كفرهم وانتصارًا لنوح عليه السلام. وفي هذا دليل على إثبات صفة العينين لله سبحانه وتعالى، كما يليق به.", "isBasmala": false, "translation_en": "And We carried him on a craft of planks and nails.", "translation_id": "Dan Kami angkut Nuh ke atas (bahtera) yang terbuat dari papan dan paku,", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 14, "text": "تَجۡرِی بِأَعۡیُنِنَا جَزَاۤءࣰ لِّمَن كَانَ كُفِرَ ۝١٤", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "وحملنا نوحًا ومَن معه على سفينة ذات ألواح ومسامير شُدَّت بها، تجري بمرأى منا وحفظ، وأغرقنا المكذبين؛ جزاء لهم على كفرهم وانتصارًا لنوح عليه السلام. وفي هذا دليل على إثبات صفة العينين لله سبحانه وتعالى، كما يليق به.", "isBasmala": false, "translation_en": "Sailing before Our eyes; a reward for him who was rejected.", "translation_id": "Yang berlayar dengan pemeliharaan Kami sebagai belasan bagi orang-orang yang diingkari (Nuh).", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 15, "text": "وَلَقَد تَّرَكۡنَـٰهَاۤ ءَایَةࣰ فَهَلۡ مِن مُّدَّكِرࣲ ۝١٥", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد أبقينا قصة نوح مع قومه عبرة ودليلا على قدرتنا لمن بعد نوح؛ ليعتبروا ويتعظوا بما حلَّ بهذه الأمة التي كفرت بربها، فهل من متعظ يتعظ؟ فكيف كان عذابي ونذري لمن كفر بي وكذب رسلي، ولم يتعظ بما جاءت به؟ إنه كان عظيمًا مؤلمًا.", "isBasmala": false, "translation_en": "And We left it as a sign. Is there anyone who would take heed?", "translation_id": "Dan sesungguhnya telah Kami jadikan kapal itu sebagai pelajaran, maka adakah orang yang mau mengambil pelajaran?", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 16, "text": "فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ ۝١٦", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد أبقينا قصة نوح مع قومه عبرة ودليلا على قدرتنا لمن بعد نوح؛ ليعتبروا ويتعظوا بما حلَّ بهذه الأمة التي كفرت بربها، فهل من متعظ يتعظ؟ فكيف كان عذابي ونذري لمن كفر بي وكذب رسلي، ولم يتعظ بما جاءت به؟ إنه كان عظيمًا مؤلمًا.", "isBasmala": false, "translation_en": "So how were My punishment and My warnings?", "translation_id": "Maka alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 17, "text": "وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ ۝١٧", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد سَهَّلْنا لفظ القرآن للتلاوة والحفظ، ومعانيه للفهم والتدبر، لمن أراد أن يتذكر ويعتبر، فهل من متعظ به؟", "isBasmala": false, "translation_en": "We made the Quran easy to learn. Is there anyone who would learn?", "translation_id": "Dan sesungguhnya telah Kami mudahkan Al-Quran untuk pelajaran, maka adakah orang yang mengambil pelajaran?", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 18, "text": "كَذَّبَتۡ عَادࣱ فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ ۝١٨", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "كذبت عاد هودًا فعاقبناهم، فكيف كان عذابي لهم على كفرهم، ونذري على تكذيب رسولهم، وعدم الإيمان به؟ إنه كان عظيمًا مؤلمًا.", "isBasmala": false, "translation_en": "Aad denied the truth. So how were My punishment and My warnings?", "translation_id": "Kaum 'Aad pun mendustakan (pula). Maka alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 19, "text": "إِنَّاۤ أَرۡسَلۡنَا عَلَیۡهِمۡ رِیحࣰا صَرۡصَرࣰا فِی یَوۡمِ نَحۡسࣲ مُّسۡتَمِرࣲّ ۝١٩", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إنَّا أرسلنا عليهم ريحًا شديدة البرد، في يوم شؤم مستمر عليهم بالعذاب والهلاك، تقتلع الناس من مواضعهم على الأرض فترمي بهم على رؤوسهم، فتدق أعناقهم، ويفصل رؤوسهم عن أجسادهم، فتتركهم كالنخل المنقلع من أصله.", "isBasmala": false, "translation_en": "We unleashed upon them a screaming wind, on a day of unrelenting misery.", "translation_id": "Sesungguhnya Kami telah menghembuskan kepada mereka angin yang sangat kencang pada hari nahas yang terus menerus,", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 20, "text": "تَنزِعُ ٱلنَّاسَ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلࣲ مُّنقَعِرࣲ ۝٢٠", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إنَّا أرسلنا عليهم ريحًا شديدة البرد، في يوم شؤم مستمر عليهم بالعذاب والهلاك، تقتلع الناس من مواضعهم على الأرض فترمي بهم على رؤوسهم، فتدق أعناقهم، ويفصل رؤوسهم عن أجسادهم، فتتركهم كالنخل المنقلع من أصله.", "isBasmala": false, "translation_en": "Plucking the people away, as though they were trunks of uprooted palm-trees.", "translation_id": "yang menggelimpangkan manusia seakan-akan mereka pokok korma yang tumbang.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 21, "text": "فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ ۝٢١", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "فكيف كان عذابي ونذري لمن كفر بي، وكذَّب رسلي ولم يؤمن بهم؟ إنه كان عظيمًا مؤلمًا.", "isBasmala": false, "translation_en": "So how were My punishment and My warnings?", "translation_id": "Maka alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 22, "text": "وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ ۝٢٢", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد سَهَّلنا لفظ القرآن للتلاوة والحفظ، ومعانيه للفهم وللتدبر، لمن أراد أن يتذكر ويعتبر، فهل من متعظ به؟ وفي هذا حثٌّ على الاستكثار من تلاوة القرآن وتعلمه وتعليمه.", "isBasmala": false, "translation_en": "We made the Quran easy to remember. Is there anyone who would remember?", "translation_id": "Dan sesungguhnya telah Kami mudahkan Al Quran untuk pelajaran, maka adakah orang yang mengambil pelajaran?", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 23, "text": "كَذَّبَتۡ ثَمُودُ بِٱلنُّذُرِ ۝٢٣", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "كذبت ثمود -وهم قوم صالح- بالآيات التي أُنذرِوا بها، فقالوا: أبشرًا منا واحدًا نتبعه نحن الجماعة الكثيرة وهو واحد؟ إنا إذا لفي بُعْدٍ عن الصواب وجنون.", "isBasmala": false, "translation_en": "Thamood rejected the warnings.", "translation_id": "Kaum Tsamudpun telah mendustakan ancaman-ancaman (itu).", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 24, "text": "فَقَالُوۤا۟ أَبَشَرࣰا مِّنَّا وَ ٰحِدࣰا نَّتَّبِعُهُۥۤ إِنَّاۤ إِذࣰا لَّفِی ضَلَـٰلࣲ وَسُعُرٍ ۝٢٤", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "كذبت ثمود -وهم قوم صالح- بالآيات التي أُنذرِوا بها، فقالوا: أبشرًا منا واحدًا نتبعه نحن الجماعة الكثيرة وهو واحد؟ إنا إذا لفي بُعْدٍ عن الصواب وجنون.", "isBasmala": false, "translation_en": "They said, \"Are we to follow one of us, a human being? We would then go astray, and end up in Hell.", "translation_id": "Maka mereka berkata: \"Bagaimana kita akan mengikuti seorang manusia (biasa) di antara kita?\" Sesungguhnya kalau kita begitu benar-benar berada dalam keadaan sesat dan gila\".", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 25, "text": "أَءُلۡقِیَ ٱلذِّكۡرُ عَلَیۡهِ مِنۢ بَیۡنِنَا بَلۡ هُوَ كَذَّابٌ أَشِرࣱ ۝٢٥", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "أأُنزل عليه الوحي وخُصَّ بالنبوة مِن بيننا، وهو واحد منا؟ بل هو كثير الكذب والتجبر. سَيَرون عند نزول العذاب بهم في الدنيا ويوم القيامة مَنِ الكذاب المتجبر؟", "isBasmala": false, "translation_en": "Was the message given to him, out of all of us? In fact, he is a wicked liar.\"", "translation_id": "Apakah wahyu itu diturunkan kepadanya di antara kita? Sebenarnya dia adalah seorang yang amat pendusta lagi sombong.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 26, "text": "سَیَعۡلَمُونَ غَدࣰا مَّنِ ٱلۡكَذَّابُ ٱلۡأَشِرُ ۝٢٦", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "أأُنزل عليه الوحي وخُصَّ بالنبوة مِن بيننا، وهو واحد منا؟ بل هو كثير الكذب والتجبر. سَيَرون عند نزول العذاب بهم في الدنيا ويوم القيامة مَنِ الكذاب المتجبر؟", "isBasmala": false, "translation_en": "They will know tomorrow who the wicked liar is.", "translation_id": "Kelak mereka akan mengetahui siapakah yang sebenarnya amat pendusta lagi sombong.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 27, "text": "إِنَّا مُرۡسِلُوا۟ ٱلنَّاقَةِ فِتۡنَةࣰ لَّهُمۡ فَٱرۡتَقِبۡهُمۡ وَٱصۡطَبِرۡ ۝٢٧", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إنا مخرجو الناقة التي سألوها من الصخرة؛ اختبارًا لهم، فانتظر- يا صالح- ما يحلُّ بهم من العذاب، واصطبر على دعوتك إياهم وأذاهم لك.", "isBasmala": false, "translation_en": "We are sending the she-camel as a test for them; so watch them and be patient.", "translation_id": "Sesungguhnya Kami akan mengirimkan unta betina sebagai cobaan bagi mereka, maka tunggulah (tindakan) mereka dan bersabarlah.", "manzil": 7, "manzil_display": ""}], "530": [{"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 28, "text": "وَنَبِّئۡهُمۡ أَنَّ ٱلۡمَاۤءَ قِسۡمَةُۢ بَیۡنَهُمۡۖ كُلُّ شِرۡبࣲ مُّحۡتَضَرࣱ ۝٢٨", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "وأخبرهم أن الماء مقسوم بين قومك والناقة: للناقة يوم، ولهم يوم، كل شِرْب يحضره مَن كانت قسمته، ويُحظر على من ليس بقسمة له.", "isBasmala": false, "translation_en": "And inform them that the water is to be shared between them; each share of drink made available.", "translation_id": "Dan beritakanlah kepada mereka bahwa sesungguhnya air itu terbagi antara mereka (dengan unta betina itu); tiap-tiap giliran minum dihadiri (oleh yang punya giliran)", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 29, "text": "فَنَادَوۡا۟ صَاحِبَهُمۡ فَتَعَاطَىٰ فَعَقَرَ ۝٢٩", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "فنادوا صاحبهم بالحض على عقرها، فتناول الناقة بيده، فنحرها فعاقَبْتُهم، فكيف كان عقابي لهم على كفرهم، وإنذاري لمن عصى رسلي؟", "isBasmala": false, "translation_en": "But they called their friend, and he dared, and he slaughtered.", "translation_id": "Maka mereka memanggil kawannya, lalu kawannya menangkap (unta itu) dan membunuhnya.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 30, "text": "فَكَیۡفَ كَانَ عَذَابِی وَنُذُرِ ۝٣٠", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "فنادوا صاحبهم بالحض على عقرها، فتناول الناقة بيده، فنحرها فعاقَبْتُهم، فكيف كان عقابي لهم على كفرهم، وإنذاري لمن عصى رسلي؟", "isBasmala": false, "translation_en": "So how were My punishment and My warnings?", "translation_id": "Alangkah dahsyatnya azab-Ku dan ancaman-ancaman-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 31, "text": "إِنَّاۤ أَرۡسَلۡنَا عَلَیۡهِمۡ صَیۡحَةࣰ وَ ٰحِدَةࣰ فَكَانُوا۟ كَهَشِیمِ ٱلۡمُحۡتَظِرِ ۝٣١", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إنا أرسلنا عليهم جبريل، فصاح بهم صيحة واحدة، فبادوا عن آخرهم، فكانوا كالزرع اليابس الذي يُجْعل حِظارًا على الإبل والمواشي.", "isBasmala": false, "translation_en": "We sent against them a single Scream, and they became like crushed hay.", "translation_id": "Sesungguhnya Kami menimpakan atas mereka satu suara yang keras mengguntur, maka jadilah mereka seperti rumput kering (yang dikumpulkan oleh) yang punya kandang binatang.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 32, "text": "وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ ۝٣٢", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد سَهَّلْنا لفظ القرآن للتلاوة والحفظ، ومعانيه للفهم والتدبر لمن أراد أن يتذكر ويعتبر، فهل مِن متعظ به؟", "isBasmala": false, "translation_en": "We made the Quran easy to understand. Is there anyone who would understand?", "translation_id": "Dan sesungguhnya telah Kami mudahkan Al Quran untuk pelajaran, maka adakah orang yang mengambil pelajaran?", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 33, "text": "كَذَّبَتۡ قَوۡمُ لُوطِۭ بِٱلنُّذُرِ ۝٣٣", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "كذَّبت قوم لوط بآيات الله التي أنذِروا بها.", "isBasmala": false, "translation_en": "The people of Lot rejected the warnings.", "translation_id": "Kaum Luth-pun telah mendustakan ancaman-ancaman (nabinya).", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 34, "text": "إِنَّاۤ أَرۡسَلۡنَا عَلَیۡهِمۡ حَاصِبًا إِلَّاۤ ءَالَ لُوطࣲۖ نَّجَّیۡنَـٰهُم بِسَحَرࣲ ۝٣٤", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إنا أرسلنا عليهم حجارةً إلا آل لوط، نجَّيناهم من العذاب في آخر الليل، نعمة من عندنا عليهم، كما أثبنا لوطًا وآله وأنعمنا عليهم، فأنجيناهم مِن عذابنا، نُثيب مَن آمن بنا وشكرنا.", "isBasmala": false, "translation_en": "We unleashed upon them a shower of stones, except for the family of Lot; We rescued them at dawn.", "translation_id": "Sesungguhnya Kami telah menghembuskan kepada mereka angin yang membawa batu-batu (yang menimpa mereka), kecuali keluarga Luth. Mereka Kami selamatkan sebelum fajar menyingsing,", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 35, "text": "نِّعۡمَةࣰ مِّنۡ عِندِنَاۚ كَذَ ٰلِكَ نَجۡزِی مَن شَكَرَ ۝٣٥", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إنا أرسلنا عليهم حجارةً إلا آل لوط، نجَّيناهم من العذاب في آخر الليل، نعمة من عندنا عليهم، كما أثبنا لوطًا وآله وأنعمنا عليهم، فأنجيناهم مِن عذابنا، نُثيب مَن آمن بنا وشكرنا.", "isBasmala": false, "translation_en": "A blessing from Us. Thus We reward the thankful.", "translation_id": "sebagai nikmat dari Kami. Demikianlah Kami memberi balasan kepada orang-orang yang bersyukur,", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 36, "text": "وَلَقَدۡ أَنذَرَهُم بَطۡشَتَنَا فَتَمَارَوۡا۟ بِٱلنُّذُرِ ۝٣٦", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد خوَّف لوط قومه بأس الله وعذابه، فلم يسمعوا له، بل شكُّوا في ذلك، وكذَّبوه.", "isBasmala": false, "translation_en": "He had warned them of Our onslaught, but they dismissed the warnings.", "translation_id": "Dan sesungguhnya dia (Luth) telah memperingatkan mereka akan azab-azab Kami, maka mereka mendustakan ancaman-ancaman itu.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 37, "text": "وَلَقَدۡ رَ ٰوَدُوهُ عَن ضَیۡفِهِۦ فَطَمَسۡنَاۤ أَعۡیُنَهُمۡ فَذُوقُوا۟ عَذَابِی وَنُذُرِ ۝٣٧", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد طلبوا منه أن يفعلوا الفاحشة بضيوفه من الملائكة، فطمسنا أعينهم فلم يُبصروا شيئًا، فقيل لهم: ذوقوا عذابي وإنذاري الذي أنذركم به لوط عليه السلام.", "isBasmala": false, "translation_en": "They even lusted for his guest, so We obliterated their eyes. \"So taste My punishment and My warnings.\"", "translation_id": "Dan sesungguhnya mereka telah membujuknya (agar menyerahkan) tamunya (kepada mereka), lalu Kami butakan mata mereka, maka rasakanlah azab-Ku dan ancaman-ancaman-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 38, "text": "وَلَقَدۡ صَبَّحَهُم بُكۡرَةً عَذَابࣱ مُّسۡتَقِرࣱّ ۝٣٨", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد جاءهم وقت الصباح عذاب دائم استقر فيهم حتى يُفضي بهم إلى عذاب الآخرة، وذلك العذاب هو رجمهم بالحجارة وقلب قُراهم وجعل أعلاها أسفلها، فقيل لهم: ذوقوا عذابي الذي أنزلته بكم؛ لكفركم وتكذيبكم، وإنذاري الذي أنذركم به لوط عليه السلام.", "isBasmala": false, "translation_en": "Early morning brought upon them enduring punishment.", "translation_id": "Dan sesungguhnya pada esok harinya mereka ditimpa azab yang kekal.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 39, "text": "فَذُوقُوا۟ عَذَابِی وَنُذُرِ ۝٣٩", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد جاءهم وقت الصباح عذاب دائم استقر فيهم حتى يُفضي بهم إلى عذاب الآخرة، وذلك العذاب هو رجمهم بالحجارة وقلب قُراهم وجعل أعلاها أسفلها، فقيل لهم: ذوقوا عذابي الذي أنزلته بكم؛ لكفركم وتكذيبكم، وإنذاري الذي أنذركم به لوط عليه السلام.", "isBasmala": false, "translation_en": "So taste My punishment and My warnings.", "translation_id": "Maka rasakanlah azab-Ku dan ancaman-ancaman-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 40, "text": "وَلَقَدۡ یَسَّرۡنَا ٱلۡقُرۡءَانَ لِلذِّكۡرِ فَهَلۡ مِن مُّدَّكِرࣲ ۝٤٠", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد سَهَّلْنا لفظ القرآن للتلاوة والحفظ، ومعانيه للفهم والتدبر لمن أراد أن يتذكر، فهل مِن متعظ به؟", "isBasmala": false, "translation_en": "We made the Quran easy to memorize. Is there anyone who would memorize?", "translation_id": "Dan sesungguhnya telah Kami mudahkan Al Quran untuk pelajaran, maka adakah orang yang mengambil pelajaran?", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 41, "text": "وَلَقَدۡ جَاۤءَ ءَالَ فِرۡعَوۡنَ ٱلنُّذُرُ ۝٤١", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد جاء أتباعَ فرعون وقومَه إنذارُنا بالعقوبة لهم على كفرهم.", "isBasmala": false, "translation_en": "The warnings also came to the people of Pharaoh.", "translation_id": "Dan sesungguhnya telah datang kepada kaum Fir'aun ancaman-ancaman.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 42, "text": "كَذَّبُوا۟ بِـَٔایَـٰتِنَا كُلِّهَا فَأَخَذۡنَـٰهُمۡ أَخۡذَ عَزِیزࣲ مُّقۡتَدِرٍ ۝٤٢", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "كذَّبوا بأدلتنا كلها الدالة على وحدانيتنا ونبوة أنبيائنا، فعاقبناهم بالعذاب عقوبة عزيز لا يغالَب، مقتدر على ما يشاء.", "isBasmala": false, "translation_en": "They rejected Our signs, all of them, so We seized them-the seizure of an Almighty Omnipotent.", "translation_id": "Mereka mendustakan mukjizat Kami semuanya, lalu Kami azab mereka sebagai azab dari Yang Maha Perkasa lagi Maha Kuasa", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 43, "text": "أَكُفَّارُكُمۡ خَیۡرࣱ مِّنۡ أُو۟لَـٰۤىِٕكُمۡ أَمۡ لَكُم بَرَاۤءَةࣱ فِی ٱلزُّبُرِ ۝٤٣", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "أكفاركم- يا معشر قريش- خير مِنَ الذين تقدَّم ذكرهم ممن هلكوا بسبب تكذيبهم، أم لكم براءة مِن عقاب الله في الكتب المنزلة على الأنبياء بالسلامة من العقوبة؟", "isBasmala": false, "translation_en": "Are your unbelievers better than all those? Or do you have immunity in the scriptures?", "translation_id": "Apakah orang-orang kafirmu (hai kaum musyrikin) lebih baik dari mereka itu, atau apakah kamu telah mempunyai jaminan kebebasan (dari azab) dalam Kitab-kitab yang dahulu", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 44, "text": "أَمۡ یَقُولُونَ نَحۡنُ جَمِیعࣱ مُّنتَصِرࣱ ۝٤٤", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "بل أيقول كفار \"مكة\": نحن أولو حزم ورأي وأمرنا مجتمع، فنحن جماعة منتصرة لا يغلبنا من أرادنا بسوء؟", "isBasmala": false, "translation_en": "Or do they say, \"We are united, and we will be victorious\"?", "translation_id": "Atau apakah mereka mengatakan: \"Kami adalah satu golongan yang bersatu yang pasti menang\".", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 45, "text": "سَیُهۡزَمُ ٱلۡجَمۡعُ وَیُوَلُّونَ ٱلدُّبُرَ ۝٤٥", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "سيهزم جمع كفار \"مكة\" أمام المؤمنين، ويولُّون الأدبار، وقد حدث هذا يوم \"بدر\".", "isBasmala": false, "translation_en": "The multitude will be defeated, and they will turn their backs.", "translation_id": "Golongan itu pasti akan dikalahkan dan mereka akan mundur ke belakang.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 46, "text": "بَلِ ٱلسَّاعَةُ مَوۡعِدُهُمۡ وَٱلسَّاعَةُ أَدۡهَىٰ وَأَمَرُّ ۝٤٦", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "والساعة موعدهم الذي يُجازون فيه بما يستحقون، والساعة أعظم وأقسى مما لحقهم من العذاب يوم \"بدر\".", "isBasmala": false, "translation_en": "The Hour is their appointed time-the Hour is more disastrous, and most bitter.", "translation_id": "Sebenarnya hari kiamat itulah hari yang dijanjikan kepada mereka dan kiamat itu lebih dahsyat dan lebih pahit.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 47, "text": "إِنَّ ٱلۡمُجۡرِمِینَ فِی ضَلَـٰلࣲ وَسُعُرࣲ ۝٤٧", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إن المجرمين في تيه عن الحق وعناء وعذاب. يوم يُجرُّون في النار على وجوههم، ويقال لهم: ذوقوا شدة عذاب جهنم.", "isBasmala": false, "translation_en": "The wicked are in confusion and madness.", "translation_id": "Sesungguhnya orang-orang yang berdosa berada dalam kesesatan (di dunia) dan dalam neraka.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 48, "text": "یَوۡمَ یُسۡحَبُونَ فِی ٱلنَّارِ عَلَىٰ وُجُوهِهِمۡ ذُوقُوا۟ مَسَّ سَقَرَ ۝٤٨", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إن المجرمين في تيه عن الحق وعناء وعذاب. يوم يُجرُّون في النار على وجوههم، ويقال لهم: ذوقوا شدة عذاب جهنم.", "isBasmala": false, "translation_en": "The Day when they are dragged upon their faces into the Fire: \"Taste the touch of Saqar.\"", "translation_id": "(Ingatlah) pada hari mereka diseret ke neraka atas muka mereka. (Dikatakan kepada mereka): \"Rasakanlah sentuhan api neraka!\"", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 49, "text": "إِنَّا كُلَّ شَیۡءٍ خَلَقۡنَـٰهُ بِقَدَرࣲ ۝٤٩", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إنَّا كل شيء خلقناه بمقدار قدرناه وقضيناه، وسبق علمنا به، وكتابتنا له في اللوح المحفوظ.", "isBasmala": false, "translation_en": "Everything We created is precisely measured.", "translation_id": "Sesungguhnya Kami menciptakan segala sesuatu menurut ukuran.", "manzil": 7, "manzil_display": ""}], "531": [{"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 50, "text": "وَمَاۤ أَمۡرُنَاۤ إِلَّا وَ ٰحِدَةࣱ كَلَمۡحِۭ بِٱلۡبَصَرِ ۝٥٠", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "وما أمرنا للشيء إذا أردناه إلا أن نقول قولة واحدة وهي \"كن\"، فيكون كلمح البصر، لا يتأخر طرفة عين.", "isBasmala": false, "translation_en": "And Our command is but once, like the twinkling of an eye.", "translation_id": "Dan perintah Kami hanyalah satu perkataan seperti kejapan mata.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 51, "text": "وَلَقَدۡ أَهۡلَكۡنَاۤ أَشۡیَاعَكُمۡ فَهَلۡ مِن مُّدَّكِرࣲ ۝٥١", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "ولقد أهلكنا أشباهكم في الكفر من الأمم الخالية، فهل من متعظ بما حلَّ بهم من النَّكال والعذاب؟", "isBasmala": false, "translation_en": "We have destroyed your likes. Is there anyone who would ponder?", "translation_id": "Dan sesungguhnya telah Kami binasakan orang yang serupa dengan kamu. Maka adakah orang yang mau mengambil pelajaran?", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 52, "text": "وَكُلُّ شَیۡءࣲ فَعَلُوهُ فِی ٱلزُّبُرِ ۝٥٢", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "وكل شيء فعله أشباهكم الماضون من خير أو شرٍّ مكتوب في الكتب التي كتبتها الحفظة.", "isBasmala": false, "translation_en": "Everything they have done is in the Books.", "translation_id": "Dan segala sesuatu yang telah mereka perbuat tercatat dalam buku-buku catatan", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 53, "text": "وَكُلُّ صَغِیرࣲ وَكَبِیرࣲ مُّسۡتَطَرٌ ۝٥٣", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "وكل صغير وكبير من أعمالهم مُسَطَّر في صحائفهم، وسيجازون به.", "isBasmala": false, "translation_en": "Everything, small or large, is written down.", "translation_id": "Dan segala (urusan) yang kecil maupun yang besar adalah tertulis.", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 54, "text": "إِنَّ ٱلۡمُتَّقِینَ فِی جَنَّـٰتࣲ وَنَهَرࣲ ۝٥٤", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "إن المتقين في بساتين عظيمة، وأنهار واسعة يوم القيامة.", "isBasmala": false, "translation_en": "The righteous will be amidst gardens and rivers.", "translation_id": "Sesungguhnya orang-orang yang bertakwa itu di dalam taman-taman dan sungai-sungai,", "manzil": 7, "manzil_display": ""}, {"sura": 54, "sura_name": "القمر", "revelation": "Makkiyah", "aya": 55, "text": "فِی مَقۡعَدِ صِدۡقٍ عِندَ مَلِیكࣲ مُّقۡتَدِرِۭ ۝٥٥", "juz": 27, "hizb": "(*¾ ح 53*)", "tafsir": "في مجلس حق، لا لغو فيه ولا تأثيم عند الله المَلِك العظيم، الخالق للأشياء كلها، المقتدر على كل شيء تبارك وتعالى.", "isBasmala": false, "translation_en": "In an assembly of virtue, in the presence of an Omnipotent King.", "translation_id": "di tempat yang disenangi di sisi Tuhan Yang Berkuasa.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 27, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 1, "text": "۞ ٱلرَّحۡمَـٰنُ ۝١", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "الرحمن علَّم الإنسان القرآن؛ بتيسير تلاوته وحفظه وفهم معانيه.", "isBasmala": false, "translation_en": "The Compassionate.", "translation_id": "(Tuhan) Yang Maha Pemurah,", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 2, "text": "عَلَّمَ ٱلۡقُرۡءَانَ ۝٢", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "الرحمن علَّم الإنسان القرآن؛ بتيسير تلاوته وحفظه وفهم معانيه.", "isBasmala": false, "translation_en": "Has taught the Quran.", "translation_id": "Yang telah mengajarkan al Quran.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 3, "text": "خَلَقَ ٱلۡإِنسَـٰنَ ۝٣", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "خلق الإنسان، علَّمه البيان عمَّا في نفسه تمييزًا له عن غيره.", "isBasmala": false, "translation_en": "He created man.", "translation_id": "Dia menciptakan manusia.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 4, "text": "عَلَّمَهُ ٱلۡبَیَانَ ۝٤", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "خلق الإنسان، علَّمه البيان عمَّا في نفسه تمييزًا له عن غيره.", "isBasmala": false, "translation_en": "And taught him clear expression.", "translation_id": "Mengajarnya pandai berbicara.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 5, "text": "ٱلشَّمۡسُ وَٱلۡقَمَرُ بِحُسۡبَانࣲ ۝٥", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "الشمس والقمر يجريان متعاقبَين بحساب متقن، لا يختلف ولا يضطرب.", "isBasmala": false, "translation_en": "The sun and the moon move according to plan.", "translation_id": "Matahari dan bulan (beredar) menurut perhitungan.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 6, "text": "وَٱلنَّجۡمُ وَٱلشَّجَرُ یَسۡجُدَانِ ۝٦", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "والنجم الذي في السماء وأشجار الأرض، تعرف ربها وتسجد له، وتنقاد لما سخرَّها له مِن مصالح عباده ومنافعهم.", "isBasmala": false, "translation_en": "And the stars and the trees prostrate themselves.", "translation_id": "Dan tumbuh-tumbuhan dan pohon-pohonan kedua-duanya tunduk kepada-Nya.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 7, "text": "وَٱلسَّمَاۤءَ رَفَعَهَا وَوَضَعَ ٱلۡمِیزَانَ ۝٧", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "والسماء رفعها فوق الأرض، ووضع في الأرض العدل الذي أمر به وشرعه لعباده.", "isBasmala": false, "translation_en": "And the sky, He raised; and He set up the balance.", "translation_id": "Dan Allah telah meninggikan langit dan Dia meletakkan neraca (keadilan).", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 8, "text": "أَلَّا تَطۡغَوۡا۟ فِی ٱلۡمِیزَانِ ۝٨", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "لئلا تعتدوا وتخونوا مَن وَزَنتم له، وأقيموا الوزن بالعدل، ولا تُنْقِصوا الميزان إذا وَزَنتم للناس.", "isBasmala": false, "translation_en": "So do not transgress in the balance.", "translation_id": "Supaya kamu jangan melampaui batas tentang neraca itu.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 9, "text": "وَأَقِیمُوا۟ ٱلۡوَزۡنَ بِٱلۡقِسۡطِ وَلَا تُخۡسِرُوا۟ ٱلۡمِیزَانَ ۝٩", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "لئلا تعتدوا وتخونوا مَن وَزَنتم له، وأقيموا الوزن بالعدل، ولا تُنْقِصوا الميزان إذا وَزَنتم للناس.", "isBasmala": false, "translation_en": "But maintain the weights with justice, and do not violate the balance.", "translation_id": "Dan tegakkanlah timbangan itu dengan adil dan janganlah kamu mengurangi neraca itu.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 10, "text": "وَٱلۡأَرۡضَ وَضَعَهَا لِلۡأَنَامِ ۝١٠", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "والأرض وضعها ومهَّدها؛ ليستقر عليها الخلق. فيها فاكهة النخل ذات الأوعية التي يكون منها الثمر، وفيها الحب ذو القشر؛ رزقًا لكم ولأنعامكم، وفيها كل نبت طيب الرائحة.", "isBasmala": false, "translation_en": "And the earth; He set up for the creatures.", "translation_id": "Dan Allah telah meratakan bumi untuk makhluk(Nya).", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 11, "text": "فِیهَا فَـٰكِهَةࣱ وَٱلنَّخۡلُ ذَاتُ ٱلۡأَكۡمَامِ ۝١١", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "والأرض وضعها ومهَّدها؛ ليستقر عليها الخلق. فيها فاكهة النخل ذات الأوعية التي يكون منها الثمر، وفيها الحب ذو القشر؛ رزقًا لكم ولأنعامكم، وفيها كل نبت طيب الرائحة.", "isBasmala": false, "translation_en": "In it are fruits, and palms in clusters.", "translation_id": "Di bumi itu ada buah-buahan dan pohon kurma yang mempunyai kelopak mayang.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 12, "text": "وَٱلۡحَبُّ ذُو ٱلۡعَصۡفِ وَٱلرَّیۡحَانُ ۝١٢", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "والأرض وضعها ومهَّدها؛ ليستقر عليها الخلق. فيها فاكهة النخل ذات الأوعية التي يكون منها الثمر، وفيها الحب ذو القشر؛ رزقًا لكم ولأنعامكم، وفيها كل نبت طيب الرائحة.", "isBasmala": false, "translation_en": "And grains in the blades, and fragrant plants.", "translation_id": "Dan biji-bijian yang berkulit dan bunga-bunga yang harum baunya.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 13, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝١٣", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما الدينية والدنيوية- يا معشر الجن والإنس- تكذِّبان؟ وما أحسن جواب الجن حين تلا عليهم النبي صلى الله عليه وسلم هذه السورة، فكلما مر بهذه الآية، قالوا: \"ولا بشيء من آلائك ربَّنا نكذب، فلك الحمد\"، وهكذا ينبغي للعبد إذا تليت عليه نعم الله وآلاؤه، أن يُقرَّ بها، ويشكر الله ويحمده عليها.", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 14, "text": "خَلَقَ ٱلۡإِنسَـٰنَ مِن صَلۡصَـٰلࣲ كَٱلۡفَخَّارِ ۝١٤", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "خلق أبا الإنسان، وهو آدم من طين يابس كالفَخَّار، وخلق إبليس، وهو من الجن من لهب النار المختلط بعضه ببعض.", "isBasmala": false, "translation_en": "He created man from hard clay, like bricks.", "translation_id": "Dia menciptakan manusia dari tanah kering seperti tembikar,", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 15, "text": "وَخَلَقَ ٱلۡجَاۤنَّ مِن مَّارِجࣲ مِّن نَّارࣲ ۝١٥", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "خلق أبا الإنسان، وهو آدم من طين يابس كالفَخَّار، وخلق إبليس، وهو من الجن من لهب النار المختلط بعضه ببعض.", "isBasmala": false, "translation_en": "And created the jinn from a fusion of fire.", "translation_id": "dan Dia menciptakan jin dari nyala api.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 16, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝١٦", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما- يا معشر الإنس والجن- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}], "532": [{"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 17, "text": "رَبُّ ٱلۡمَشۡرِقَیۡنِ وَرَبُّ ٱلۡمَغۡرِبَیۡنِ ۝١٧", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "هو سبحانه وتعالى ربُّ مشرقَي الشمس في الشتاء والصيف، ورب مغربَيها فيهما، فالجميع تحت تدبيره وربوبيته.", "isBasmala": false, "translation_en": "Lord of the two Easts and Lord of the two Wests.", "translation_id": "Tuhan yang memelihara kedua tempat terbit matahari dan Tuhan yang memelihara kedua tempat terbenamnya", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 18, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝١٨", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما- أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 19, "text": "مَرَجَ ٱلۡبَحۡرَیۡنِ یَلۡتَقِیَانِ ۝١٩", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "خلط الله ماء البحرين - العذب والملح- يلتقيان. بينهما حاجز، فلا يطغى أحدهما على الآخر، ويذهب بخصائصه، بل يبقى العذب عذبًا، والملح ملحًا مع تلاقيهما.", "isBasmala": false, "translation_en": "He merged the two seas, converging together.", "translation_id": "Dia membiarkan dua lautan mengalir yang keduanya kemudian bertemu,", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 20, "text": "بَیۡنَهُمَا بَرۡزَخࣱ لَّا یَبۡغِیَانِ ۝٢٠", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "خلط الله ماء البحرين - العذب والملح- يلتقيان. بينهما حاجز، فلا يطغى أحدهما على الآخر، ويذهب بخصائصه، بل يبقى العذب عذبًا، والملح ملحًا مع تلاقيهما.", "isBasmala": false, "translation_en": "Between them is a barrier, which they do not overrun.", "translation_id": "antara keduanya ada batas yang tidak dilampaui masing-masing.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 21, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٢١", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما- أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 22, "text": "یَخۡرُجُ مِنۡهُمَا ٱللُّؤۡلُؤُ وَٱلۡمَرۡجَانُ ۝٢٢", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "يخرج من البحرين بقدرة الله اللؤلؤ والمَرْجان.", "isBasmala": false, "translation_en": "From them emerge pearls and coral.", "translation_id": "Dari keduanya keluar mutiara dan marjan.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 23, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٢٣", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما- أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 24, "text": "وَلَهُ ٱلۡجَوَارِ ٱلۡمُنشَـَٔاتُ فِی ٱلۡبَحۡرِ كَٱلۡأَعۡلَـٰمِ ۝٢٤", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "وله سبحانه وتعالى السفن الضخمة التي تجري في البحر بمنافع الناس، رافعة قلاعها وأشرعتها كالجبال.", "isBasmala": false, "translation_en": "His are the ships, raised above the sea like landmarks.", "translation_id": "Dan kepunyaan-Nya lah bahtera-bahtera yang tinggi layarnya di lautan laksana gunung-gunung.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 25, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٢٥", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما- أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 26, "text": "كُلُّ مَنۡ عَلَیۡهَا فَانࣲ ۝٢٦", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "كل مَن على وجه الأرض مِن الخلق هالك، ويبقى وجه ربك ذو العظمة والكبرياء والفضل والجود. وفي الآية إثبات صفة الوجه لله تعالى بما يليق به سبحانه، دون تشبيه ولا تكييف.", "isBasmala": false, "translation_en": "Everyone upon it is perishing.", "translation_id": "Semua yang ada di bumi itu akan binasa.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 27, "text": "وَیَبۡقَىٰ وَجۡهُ رَبِّكَ ذُو ٱلۡجَلَـٰلِ وَٱلۡإِكۡرَامِ ۝٢٧", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "كل مَن على وجه الأرض مِن الخلق هالك، ويبقى وجه ربك ذو العظمة والكبرياء والفضل والجود. وفي الآية إثبات صفة الوجه لله تعالى بما يليق به سبحانه، دون تشبيه ولا تكييف.", "isBasmala": false, "translation_en": "But will remain the Presence of your Lord, Full of Majesty and Splendor.", "translation_id": "Dan tetap kekal Dzat Tuhanmu yang mempunyai kebesaran dan kemuliaan.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 28, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٢٨", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 29, "text": "یَسۡـَٔلُهُۥ مَن فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ كُلَّ یَوۡمٍ هُوَ فِی شَأۡنࣲ ۝٢٩", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "يسأله مَن في السموات والأرض حاجاتهم، فلا غنى لأحد منهم عنه سبحانه. كل يوم هو في شأن: يُعِزُّ ويُذِلُّ، ويعطي ويَمْنع.", "isBasmala": false, "translation_en": "Everyone in the heavens and the earth asks Him. Every day He is managing.", "translation_id": "Semua yang ada di langit dan bumi selalu meminta kepada-Nya. Setiap waktu Dia dalam kesibukan.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 30, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٣٠", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Rabb-mu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 31, "text": "سَنَفۡرُغُ لَكُمۡ أَیُّهَ ٱلثَّقَلَانِ ۝٣١", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "سنفرُغ لحسابكم ومجازاتكم بأعمالكما التي عملتموهما في الدنيا، أيها الثقلان- الإنس والجن-، فنعاقب أهل المعاصي، ونُثيب أهل الطاعة.", "isBasmala": false, "translation_en": "We will attend to you, O prominent two.", "translation_id": "Kami akan memperhatikan sepenuhnya kepadamu hai manusia dan jin.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 32, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٣٢", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأيِّ نِعَم ربكما- أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 33, "text": "یَـٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ إِنِ ٱسۡتَطَعۡتُمۡ أَن تَنفُذُوا۟ مِنۡ أَقۡطَارِ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ فَٱنفُذُوا۟ۚ لَا تَنفُذُونَ إِلَّا بِسُلۡطَـٰنࣲ ۝٣٣", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "يا معشر الجن والإنس، إن قَدَرْتم على النفاذ من أمر الله وحكمه هاربين من أطراف السموات والأرض فافعلوا، ولستم قادرين على ذلك إلا بقوة وحجة، وأمر من الله تعالى (وأنَّى لكم ذلك وأنتم لا تملكون لأنفسكم نفعًا ولا ضرًا؟). فبأي نِعَم ربكما - أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "O society of jinn and humans! If you can pass through the bounds of the heavens and the earth, go ahead and pass. But you will not pass except with authorization.", "translation_id": "Hai jama'ah jin dan manusia, jika kamu sanggup menembus (melintasi) penjuru langit dan bumi, maka lintasilah, kamu tidak dapat menembusnya kecuali dengan kekuatan.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 34, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٣٤", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "يا معشر الجن والإنس، إن قَدَرْتم على النفاذ من أمر الله وحكمه هاربين من أطراف السموات والأرض فافعلوا، ولستم قادرين على ذلك إلا بقوة وحجة، وأمر من الله تعالى (وأنَّى لكم ذلك وأنتم لا تملكون لأنفسكم نفعًا ولا ضرًا؟). فبأي نِعَم ربكما - أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 35, "text": "یُرۡسَلُ عَلَیۡكُمَا شُوَاظࣱ مِّن نَّارࣲ وَنُحَاسࣱ فَلَا تَنتَصِرَانِ ۝٣٥", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "يُرْسَل عليكم لهب من نار، ونحاس مذاب يُصَبُّ على رؤوسكم، فلا ينصر بعضكم بعضًا يا معشر الجن والإنس. فبأي نِعَم ربكما- أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "You will be bombarded with flares of fire and brass, and you will not succeed.", "translation_id": "Kepada kamu, (jin dan manusia) dilepaskan nyala api dan cairan tembaga maka kamu tidak dapat menyelamatkan diri (dari padanya).", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 36, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٣٦", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "يُرْسَل عليكم لهب من نار، ونحاس مذاب يُصَبُّ على رؤوسكم، فلا ينصر بعضكم بعضًا يا معشر الجن والإنس. فبأي نِعَم ربكما- أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 37, "text": "فَإِذَا ٱنشَقَّتِ ٱلسَّمَاۤءُ فَكَانَتۡ وَرۡدَةࣰ كَٱلدِّهَانِ ۝٣٧", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فإذا انشقت السماء وتفطرت يوم القيامة، فكانت حمراء كلون الورد، وكالزيت المغلي والرصاص المذاب؛ من شدة الأمر وهول يوم القيامة.", "isBasmala": false, "translation_en": "When the sky splits apart, and becomes rose, like paint.", "translation_id": "Maka apabila langit telah terbelah dan menjadi merah mawar seperti (kilapan) minyak.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 38, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٣٨", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما- أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 39, "text": "فَیَوۡمَىِٕذࣲ لَّا یُسۡـَٔلُ عَن ذَنۢبِهِۦۤ إِنسࣱ وَلَا جَاۤنࣱّ ۝٣٩", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "ففي ذلك اليوم لا تسأل الملائكة المجرمين من الإنس والجن عن ذنوبهم.", "isBasmala": false, "translation_en": "On that Day, no human and no jinn will be asked about his sins.", "translation_id": "Pada waktu itu manusia dan jin tidak ditanya tentang dosanya.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 40, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٤٠", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}], "533": [{"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 41, "text": "یُعۡرَفُ ٱلۡمُجۡرِمُونَ بِسِیمَـٰهُمۡ فَیُؤۡخَذُ بِٱلنَّوَ ٰصِی وَٱلۡأَقۡدَامِ ۝٤١", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "تَعرِف الملائكة المجرمين بعلاماتهم، فتأخذهم بمقدمة رؤوسهم وبأقدامهم، فترميهم في النار.", "isBasmala": false, "translation_en": "The guilty will be recognized by their marks; they will be taken by the forelocks and the feet.", "translation_id": "Orang-orang yang berdosa dikenal dengan tanda-tandannya, lalu dipegang ubun-ubun dan kaki mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 42, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٤٢", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 43, "text": "هَـٰذِهِۦ جَهَنَّمُ ٱلَّتِی یُكَذِّبُ بِهَا ٱلۡمُجۡرِمُونَ ۝٤٣", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "يقال لهؤلاء المجرمين -توبيخًا وتحقيرًا لهم-: هذه جهنم التي يكذِّب بها المجرمون في الدنيا: تارة يُعذَّبون في الجحيم، وتارة يُسقون من الحميم، وهو شراب بلغ منتهى الحرارة، يقطِّع الأمعاء والأحشاء.", "isBasmala": false, "translation_en": "This is Hell that the guilty denied.", "translation_id": "Inilah neraka Jahannam yang didustakan oleh orang-orang berdosa.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 44, "text": "یَطُوفُونَ بَیۡنَهَا وَبَیۡنَ حَمِیمٍ ءَانࣲ ۝٤٤", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "يقال لهؤلاء المجرمين -توبيخًا وتحقيرًا لهم-: هذه جهنم التي يكذِّب بها المجرمون في الدنيا: تارة يُعذَّبون في الجحيم، وتارة يُسقون من الحميم، وهو شراب بلغ منتهى الحرارة، يقطِّع الأمعاء والأحشاء.", "isBasmala": false, "translation_en": "They circulate between it and between a seething bath.", "translation_id": "Mereka berkeliling di antaranya dan di antara air mendidih yang memuncak panasnya.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 45, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٤٥", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 46, "text": "وَلِمَنۡ خَافَ مَقَامَ رَبِّهِۦ جَنَّتَانِ ۝٤٦", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "ولمن اتقى الله من عباده من الإنس والجن، فخاف مقامه بين يديه، فأطاعه، وترك معاصيه، جنتان.", "isBasmala": false, "translation_en": "But for him who feared the standing of his Lord are two gardens.", "translation_id": "Dan bagi orang yang takut akan saat menghadap Tuhannya ada dua surga.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 47, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٤٧", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?,", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 48, "text": "ذَوَاتَاۤ أَفۡنَانࣲ ۝٤٨", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "الجنتان ذواتا أغصان نضرة من الفواكه والثمار.", "isBasmala": false, "translation_en": "Full of varieties.", "translation_id": "kedua surga itu mempunyai pohon-pohonan dan buah-buahan.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 49, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٤٩", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 50, "text": "فِیهِمَا عَیۡنَانِ تَجۡرِیَانِ ۝٥٠", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "في هاتين الجنتين عينان من الماء تجريان خلالهما.", "isBasmala": false, "translation_en": "In them are two flowing springs.", "translation_id": "Di dalam kedua surga itu ada dua buah mata air yang mengalir", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 51, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٥١", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 52, "text": "فِیهِمَا مِن كُلِّ فَـٰكِهَةࣲ زَوۡجَانِ ۝٥٢", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "في هاتين الجنتين من كل نوع من الفواكه صنفان.", "isBasmala": false, "translation_en": "In them are fruits of every kind, in pairs.", "translation_id": "Di dalam kedua surga itu terdapat segala macam buah-buahan yang berpasangan.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 53, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٥٣", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 54, "text": "مُتَّكِـِٔینَ عَلَىٰ فُرُشِۭ بَطَاۤىِٕنُهَا مِنۡ إِسۡتَبۡرَقࣲۚ وَجَنَى ٱلۡجَنَّتَیۡنِ دَانࣲ ۝٥٤", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "وللذين خافوا مقام ربهم جنتان يتنعمون فيهما، متكئين على فرش مبطَّنة من غليظ الديباج، وثمر الجنتين قريب إليهم.", "isBasmala": false, "translation_en": "Reclining on furnishings lined with brocade, and the fruits of the two gardens are near at hand.", "translation_id": "Mereka bertelekan di atas permadani yang sebelah dalamnya dari sutera. Dan buah-buahan di kedua surga itu dapat (dipetik) dari dekat.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 55, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٥٥", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 56, "text": "فِیهِنَّ قَـٰصِرَ ٰتُ ٱلطَّرۡفِ لَمۡ یَطۡمِثۡهُنَّ إِنسࣱ قَبۡلَهُمۡ وَلَا جَاۤنࣱّ ۝٥٦", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "في هذه الفرش زوجات قاصرات أبصارهن على أزواجهن، لا ينظرن إلى غيرهم متعلقات بهم، لم يطأهن إنس قبلهم ولا جان.", "isBasmala": false, "translation_en": "In them are maidens restraining their glances, untouched before by any man or jinn.", "translation_id": "Di dalam surga itu ada bidadari-bidadari yang sopan menundukkan pandangannya, tidak pernah disentuh oleh manusia sebelum mereka (penghuni-penghuni surga yang menjadi suami mereka), dan tidak pula oleh jin.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 57, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٥٧", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 58, "text": "كَأَنَّهُنَّ ٱلۡیَاقُوتُ وَٱلۡمَرۡجَانُ ۝٥٨", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "كأن هؤلاء الزوجاتِ من الحور الياقوتُ والمَرْجانُ في صفائهن وجمالهن.", "isBasmala": false, "translation_en": "As though they were rubies and corals.", "translation_id": "Seakan-akan bidadari itu permata yakut dan marjan.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 59, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٥٩", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 60, "text": "هَلۡ جَزَاۤءُ ٱلۡإِحۡسَـٰنِ إِلَّا ٱلۡإِحۡسَـٰنُ ۝٦٠", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "هل جزاء مَن أحسن بعمله في الدنيا إلا الإحسان إليه بالجنة في الآخرة؟ فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "Is the reward of goodness anything but goodness?", "translation_id": "Tidak ada balasan kebaikan kecuali kebaikan (pula).", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 61, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٦١", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "هل جزاء مَن أحسن بعمله في الدنيا إلا الإحسان إليه بالجنة في الآخرة؟ فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 62, "text": "وَمِن دُونِهِمَا جَنَّتَانِ ۝٦٢", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "ومن دون الجنتين السابقتين جنتان أخريان. فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "And beneath them are two gardens.", "translation_id": "Dan selain dari dua surga itu ada dua surga lagi", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 63, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٦٣", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "ومن دون الجنتين السابقتين جنتان أخريان. فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 64, "text": "مُدۡهَاۤمَّتَانِ ۝٦٤", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "هاتان الجنتان خضراوان، قد اشتدَّت خضرتهما حتى مالت إلى السواد. فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "Deep green.", "translation_id": "Kedua surga itu (kelihatan) hijau tua warnanya.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 65, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٦٥", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "هاتان الجنتان خضراوان، قد اشتدَّت خضرتهما حتى مالت إلى السواد. فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 66, "text": "فِیهِمَا عَیۡنَانِ نَضَّاخَتَانِ ۝٦٦", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فيهما عينان فوَّارتان بالماء لا تنقطعان. فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "In them are two gushing springs.", "translation_id": "Di dalam kedua surga itu ada dua buah mata air yang memancar.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 67, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٦٧", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فيهما عينان فوَّارتان بالماء لا تنقطعان. فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}], "534": [{"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 68, "text": "فِیهِمَا فَـٰكِهَةࣱ وَنَخۡلࣱ وَرُمَّانࣱ ۝٦٨", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "في هاتين الجنتين أنواع الفواكه ونخل ورمان.", "isBasmala": false, "translation_en": "In them are fruits, and date-palms, and pomegranates.", "translation_id": "Di dalam keduanya (ada macam-macam) buah-buahan dan kurma serta delima.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 69, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٦٩", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 70, "text": "فِیهِنَّ خَیۡرَ ٰتٌ حِسَانࣱ ۝٧٠", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "في هذه الجنان الأربع زوجات طيبات الأخلاق حسان الوجوه.", "isBasmala": false, "translation_en": "In them are good and beautiful ones.", "translation_id": "Di dalam surga itu ada bidadari-bidadari yang baik-baik lagi cantik-cantik.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 71, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٧١", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 72, "text": "حُورࣱ مَّقۡصُورَ ٰتࣱ فِی ٱلۡخِیَامِ ۝٧٢", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "حور مستورات مصونات في الخيام.", "isBasmala": false, "translation_en": "Companions, secluded in the tents.", "translation_id": "(Bidadari-bidadari) yang jelita, putih bersih, dipingit dalam rumah.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 73, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٧٣", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 74, "text": "لَمۡ یَطۡمِثۡهُنَّ إِنسࣱ قَبۡلَهُمۡ وَلَا جَاۤنࣱّ ۝٧٤", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "لم يطأ هؤلاء الحور إنس قبل أزواجهن ولا جان.", "isBasmala": false, "translation_en": "Whom no human has touched before, nor jinn.", "translation_id": "Mereka tidak pernah disentuh oleh manusia sebelum mereka (penghuni-penghuni surga yang menjadi suami mereka), dan tidak pula oleh jin.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 75, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٧٥", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 76, "text": "مُتَّكِـِٔینَ عَلَىٰ رَفۡرَفٍ خُضۡرࣲ وَعَبۡقَرِیٍّ حِسَانࣲ ۝٧٦", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "متكئين على وسائد ذوات أغطية خضر وفرش حسان.", "isBasmala": false, "translation_en": "Reclining on green cushions, and exquisite carpets.", "translation_id": "Mereka bertelekan pada bantal-bantal yang hijau dan permadani-permadani yang indah.", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 77, "text": "فَبِأَیِّ ءَالَاۤءِ رَبِّكُمَا تُكَذِّبَانِ ۝٧٧", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "فبأي نِعَم ربكما -أيها الثقلان- تكذِّبان؟", "isBasmala": false, "translation_en": "So which of your Lord's marvels will you deny?", "translation_id": "Maka nikmat Tuhan kamu yang manakah yang kamu dustakan?", "manzil": 7, "manzil_display": ""}, {"sura": 55, "sura_name": "الرحمن", "revelation": "Madaniyah", "aya": 78, "text": "تَبَـٰرَكَ ٱسۡمُ رَبِّكَ ذِی ٱلۡجَلَـٰلِ وَٱلۡإِكۡرَامِ ۝٧٨", "juz": 27, "hizb": "(* ح 54*)", "tafsir": "تكاثرت بركة اسم ربك وكثر خيره، ذي الجلال الباهر، والمجد الكامل، والإكرام لأوليائه.", "isBasmala": false, "translation_en": "Blessed be the name of your Lord, Full of Majesty and Splendor.", "translation_id": "Maha Agung nama Tuhanmu Yang Mempunyai Kebesaran dan Karunia.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 27, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 1, "text": "۞ إِذَا وَقَعَتِ ٱلۡوَاقِعَةُ ۝١", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إذا قامت القيامة، ليس لقيامها أحد يكذِّب به، هي خافضة لأعداء الله في النار، رافعة لأوليائه في الجنة.", "isBasmala": false, "translation_en": "When the inevitable occurs.", "translation_id": "Apabila terjadi hari kiamat,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 2, "text": "لَیۡسَ لِوَقۡعَتِهَا كَاذِبَةٌ ۝٢", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إذا قامت القيامة، ليس لقيامها أحد يكذِّب به، هي خافضة لأعداء الله في النار، رافعة لأوليائه في الجنة.", "isBasmala": false, "translation_en": "Of its occurrence, there is no denial.", "translation_id": "tidak seorangpun dapat berdusta tentang kejadiannya.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 3, "text": "خَافِضَةࣱ رَّافِعَةٌ ۝٣", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إذا قامت القيامة، ليس لقيامها أحد يكذِّب به، هي خافضة لأعداء الله في النار، رافعة لأوليائه في الجنة.", "isBasmala": false, "translation_en": "Bringing low, raising high.", "translation_id": "(Kejadian itu) merendahkan (satu golongan) dan meninggikan (golongan yang lain),", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 4, "text": "إِذَا رُجَّتِ ٱلۡأَرۡضُ رَجࣰّا ۝٤", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إذا حُرِّكت الأرض تحريكًا شديدًا، وفُتِّتت الجبال تفتيتًا دقيقًا، فصارت غبارًا متطايرًا في الجو قد ذَرَتْه الريح.", "isBasmala": false, "translation_en": "When the earth is shaken with a shock.", "translation_id": "apabila bumi digoncangkan sedahsyat-dahsyatnya,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 5, "text": "وَبُسَّتِ ٱلۡجِبَالُ بَسࣰّا ۝٥", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إذا حُرِّكت الأرض تحريكًا شديدًا، وفُتِّتت الجبال تفتيتًا دقيقًا، فصارت غبارًا متطايرًا في الجو قد ذَرَتْه الريح.", "isBasmala": false, "translation_en": "And the mountains are crushed and crumbled.", "translation_id": "dan gunung-gunung dihancur luluhkan seluluh-luluhnya,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 6, "text": "فَكَانَتۡ هَبَاۤءࣰ مُّنۢبَثࣰّا ۝٦", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إذا حُرِّكت الأرض تحريكًا شديدًا، وفُتِّتت الجبال تفتيتًا دقيقًا، فصارت غبارًا متطايرًا في الجو قد ذَرَتْه الريح.", "isBasmala": false, "translation_en": "And they become scattered dust.", "translation_id": "maka jadilah ia debu yang beterbangan,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 7, "text": "وَكُنتُمۡ أَزۡوَ ٰجࣰا ثَلَـٰثَةࣰ ۝٧", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وكنتم- أيها الخلق- أصنافًا ثلاثة:", "isBasmala": false, "translation_en": "And you become three classes.", "translation_id": "dan kamu menjadi tiga golongan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 8, "text": "فَأَصۡحَـٰبُ ٱلۡمَیۡمَنَةِ مَاۤ أَصۡحَـٰبُ ٱلۡمَیۡمَنَةِ ۝٨", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "فأصحاب اليمين، أهل المنزلة العالية، ما أعظم مكانتهم!! وأصحاب الشمال، أهل المنزلة الدنيئة، ما أسوأ حالهم!!", "isBasmala": false, "translation_en": "Those on the Right-what of those on the Right?", "translation_id": "Yaitu golongan kanan. Alangkah mulianya golongan kanan itu.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 9, "text": "وَأَصۡحَـٰبُ ٱلۡمَشۡـَٔمَةِ مَاۤ أَصۡحَـٰبُ ٱلۡمَشۡـَٔمَةِ ۝٩", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "فأصحاب اليمين، أهل المنزلة العالية، ما أعظم مكانتهم!! وأصحاب الشمال، أهل المنزلة الدنيئة، ما أسوأ حالهم!!", "isBasmala": false, "translation_en": "And those on the Left-what of those on the Left?", "translation_id": "Dan golongan kiri. Alangkah sengsaranya golongan kiri itu.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 10, "text": "وَٱلسَّـٰبِقُونَ ٱلسَّـٰبِقُونَ ۝١٠", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "والسابقون إلى الخيرات في الدنيا هم السابقون إلى الدرجات في الآخرة، أولئك هم المقربون عند الله، يُدْخلهم ربهم في جنات النعيم.", "isBasmala": false, "translation_en": "And the forerunners, the forerunners.", "translation_id": "Dan orang-orang yang beriman paling dahulu,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 11, "text": "أُو۟لَـٰۤىِٕكَ ٱلۡمُقَرَّبُونَ ۝١١", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "والسابقون إلى الخيرات في الدنيا هم السابقون إلى الدرجات في الآخرة، أولئك هم المقربون عند الله، يُدْخلهم ربهم في جنات النعيم.", "isBasmala": false, "translation_en": "Those are the nearest.", "translation_id": "Mereka itulah yang didekatkan kepada Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 12, "text": "فِی جَنَّـٰتِ ٱلنَّعِیمِ ۝١٢", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "والسابقون إلى الخيرات في الدنيا هم السابقون إلى الدرجات في الآخرة، أولئك هم المقربون عند الله، يُدْخلهم ربهم في جنات النعيم.", "isBasmala": false, "translation_en": "In the Gardens of Bliss.", "translation_id": "Berada dalam jannah kenikmatan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 13, "text": "ثُلَّةࣱ مِّنَ ٱلۡأَوَّلِینَ ۝١٣", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "يدخلها جماعة كثيرة من صدر هذه الأمة، وغيرهم من الأمم الأخرى، وقليل من آخر هذه الأمة على سرر منسوجة بالذهب، متكئين عليها يقابل بعضهم بعضًا.", "isBasmala": false, "translation_en": "A throng from the ancients.", "translation_id": "Segolongan besar dari orang-orang yang terdahulu,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 14, "text": "وَقَلِیلࣱ مِّنَ ٱلۡـَٔاخِرِینَ ۝١٤", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "يدخلها جماعة كثيرة من صدر هذه الأمة، وغيرهم من الأمم الأخرى، وقليل من آخر هذه الأمة على سرر منسوجة بالذهب، متكئين عليها يقابل بعضهم بعضًا.", "isBasmala": false, "translation_en": "And a small band from the latecomers.", "translation_id": "dan segolongan kecil dari orang-orang yang kemudian", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 15, "text": "عَلَىٰ سُرُرࣲ مَّوۡضُونَةࣲ ۝١٥", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "يدخلها جماعة كثيرة من صدر هذه الأمة، وغيرهم من الأمم الأخرى، وقليل من آخر هذه الأمة على سرر منسوجة بالذهب، متكئين عليها يقابل بعضهم بعضًا.", "isBasmala": false, "translation_en": "On luxurious furnishings.", "translation_id": "Mereka berada di atas dipan yang bertahta emas dan permata,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 16, "text": "مُّتَّكِـِٔینَ عَلَیۡهَا مُتَقَـٰبِلِینَ ۝١٦", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "يدخلها جماعة كثيرة من صدر هذه الأمة، وغيرهم من الأمم الأخرى، وقليل من آخر هذه الأمة على سرر منسوجة بالذهب، متكئين عليها يقابل بعضهم بعضًا.", "isBasmala": false, "translation_en": "Reclining on them, facing one another.", "translation_id": "seraya bertelekan di atasnya berhadap-hadapan.", "manzil": 7, "manzil_display": ""}], "535": [{"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 17, "text": "یَطُوفُ عَلَیۡهِمۡ وِلۡدَ ٰنࣱ مُّخَلَّدُونَ ۝١٧", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "يطوف عليهم لخدمتهم غلمان لا يهرمون ولا يموتون، بأقداح وأباريق وكأس من عين خمر جارية في الجنة، لا تُصَدَّعُ منها رؤوسهم، ولا تذهب بعقولهم.", "isBasmala": false, "translation_en": "Serving them will be immortalized youth.", "translation_id": "Mereka dikelilingi oleh anak-anak muda yang tetap muda,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 18, "text": "بِأَكۡوَابࣲ وَأَبَارِیقَ وَكَأۡسࣲ مِّن مَّعِینࣲ ۝١٨", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "يطوف عليهم لخدمتهم غلمان لا يهرمون ولا يموتون، بأقداح وأباريق وكأس من عين خمر جارية في الجنة، لا تُصَدَّعُ منها رؤوسهم، ولا تذهب بعقولهم.", "isBasmala": false, "translation_en": "With cups, pitchers, and sparkling drinks.", "translation_id": "dengan membawa gelas, cerek dan minuman yang diambil dari air yang mengalir,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 19, "text": "لَّا یُصَدَّعُونَ عَنۡهَا وَلَا یُنزِفُونَ ۝١٩", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "يطوف عليهم لخدمتهم غلمان لا يهرمون ولا يموتون، بأقداح وأباريق وكأس من عين خمر جارية في الجنة، لا تُصَدَّعُ منها رؤوسهم، ولا تذهب بعقولهم.", "isBasmala": false, "translation_en": "Causing them neither headache, nor intoxication.", "translation_id": "mereka tidak pening karenanya dan tidak pula mabuk,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 20, "text": "وَفَـٰكِهَةࣲ مِّمَّا یَتَخَیَّرُونَ ۝٢٠", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ويطوف عليهم الغلمان بما يتخيرون من الفواكه، وبلحم طير ممَّا ترغب فيه نفوسهم. ولهم نساء ذوات عيون واسعة، كأمثال اللؤلؤ المصون في أصدافه صفاءً وجمالا؛ جزاء لهم بما كانوا يعملون من الصالحات في الدنيا.", "isBasmala": false, "translation_en": "And fruits of their choice.", "translation_id": "dan buah-buahan dari apa yang mereka pilih,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 21, "text": "وَلَحۡمِ طَیۡرࣲ مِّمَّا یَشۡتَهُونَ ۝٢١", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ويطوف عليهم الغلمان بما يتخيرون من الفواكه، وبلحم طير ممَّا ترغب فيه نفوسهم. ولهم نساء ذوات عيون واسعة، كأمثال اللؤلؤ المصون في أصدافه صفاءً وجمالا؛ جزاء لهم بما كانوا يعملون من الصالحات في الدنيا.", "isBasmala": false, "translation_en": "And meat of birds that they may desire.", "translation_id": "dan daging burung dari apa yang mereka inginkan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 22, "text": "وَحُورٌ عِینࣱ ۝٢٢", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ويطوف عليهم الغلمان بما يتخيرون من الفواكه، وبلحم طير ممَّا ترغب فيه نفوسهم. ولهم نساء ذوات عيون واسعة، كأمثال اللؤلؤ المصون في أصدافه صفاءً وجمالا؛ جزاء لهم بما كانوا يعملون من الصالحات في الدنيا.", "isBasmala": false, "translation_en": "And lovely companions.", "translation_id": "Dan ada bidadari-bidadari bermata jeli,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 23, "text": "كَأَمۡثَـٰلِ ٱللُّؤۡلُوِٕ ٱلۡمَكۡنُونِ ۝٢٣", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ويطوف عليهم الغلمان بما يتخيرون من الفواكه، وبلحم طير ممَّا ترغب فيه نفوسهم. ولهم نساء ذوات عيون واسعة، كأمثال اللؤلؤ المصون في أصدافه صفاءً وجمالا؛ جزاء لهم بما كانوا يعملون من الصالحات في الدنيا.", "isBasmala": false, "translation_en": "The likenesses of treasured pearls.", "translation_id": "laksana mutiara yang tersimpan baik.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 24, "text": "جَزَاۤءَۢ بِمَا كَانُوا۟ یَعۡمَلُونَ ۝٢٤", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ويطوف عليهم الغلمان بما يتخيرون من الفواكه، وبلحم طير ممَّا ترغب فيه نفوسهم. ولهم نساء ذوات عيون واسعة، كأمثال اللؤلؤ المصون في أصدافه صفاءً وجمالا؛ جزاء لهم بما كانوا يعملون من الصالحات في الدنيا.", "isBasmala": false, "translation_en": "As a reward for what they used to do.", "translation_id": "Sebagai balasan bagi apa yang telah mereka kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 25, "text": "لَا یَسۡمَعُونَ فِیهَا لَغۡوࣰا وَلَا تَأۡثِیمًا ۝٢٥", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "لا يسمعون في الجنة باطلا ولا ما يتأثمون بسماعه، إلا قولا سالمًا من هذه العيوب، وتسليم بعضهم على بعض.", "isBasmala": false, "translation_en": "Therein they will hear no nonsense, and no accusations.", "translation_id": "Mereka tidak mendengar di dalamnya perkataan yang sia-sia dan tidak pula perkataan yang menimbulkan dosa,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 26, "text": "إِلَّا قِیلࣰا سَلَـٰمࣰا سَلَـٰمࣰا ۝٢٦", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "لا يسمعون في الجنة باطلا ولا ما يتأثمون بسماعه، إلا قولا سالمًا من هذه العيوب، وتسليم بعضهم على بعض.", "isBasmala": false, "translation_en": "But only the greeting: \"Peace, peace.\"", "translation_id": "akan tetapi mereka mendengar ucapan salam.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 27, "text": "وَأَصۡحَـٰبُ ٱلۡیَمِینِ مَاۤ أَصۡحَـٰبُ ٱلۡیَمِینِ ۝٢٧", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب اليمين، ما أعظم مكانتهم وجزاءهم!! هم في سِدْر لا شوك فيه، وموز متراكب بعضه على بعض، وظلٍّ دائم لا يزول، وماء جار لا ينقطع، وفاكهة كثيرة لا تنفَد ولا تنقطع عنهم، ولا يمنعهم منها مانع، وفرشٍ مرفوعة على السرر.", "isBasmala": false, "translation_en": "And those on the Right-what of those on the Right?", "translation_id": "Dan golongan kanan, alangkah bahagianya golongan kanan itu.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 28, "text": "فِی سِدۡرࣲ مَّخۡضُودࣲ ۝٢٨", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب اليمين، ما أعظم مكانتهم وجزاءهم!! هم في سِدْر لا شوك فيه، وموز متراكب بعضه على بعض، وظلٍّ دائم لا يزول، وماء جار لا ينقطع، وفاكهة كثيرة لا تنفَد ولا تنقطع عنهم، ولا يمنعهم منها مانع، وفرشٍ مرفوعة على السرر.", "isBasmala": false, "translation_en": "In lush orchards.", "translation_id": "Berada di antara pohon bidara yang tak berduri,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 29, "text": "وَطَلۡحࣲ مَّنضُودࣲ ۝٢٩", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب اليمين، ما أعظم مكانتهم وجزاءهم!! هم في سِدْر لا شوك فيه، وموز متراكب بعضه على بعض، وظلٍّ دائم لا يزول، وماء جار لا ينقطع، وفاكهة كثيرة لا تنفَد ولا تنقطع عنهم، ولا يمنعهم منها مانع، وفرشٍ مرفوعة على السرر.", "isBasmala": false, "translation_en": "And sweet-smelling plants.", "translation_id": "dan pohon pisang yang bersusun-susun (buahnya),", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 30, "text": "وَظِلࣲّ مَّمۡدُودࣲ ۝٣٠", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب اليمين، ما أعظم مكانتهم وجزاءهم!! هم في سِدْر لا شوك فيه، وموز متراكب بعضه على بعض، وظلٍّ دائم لا يزول، وماء جار لا ينقطع، وفاكهة كثيرة لا تنفَد ولا تنقطع عنهم، ولا يمنعهم منها مانع، وفرشٍ مرفوعة على السرر.", "isBasmala": false, "translation_en": "And extended shade.", "translation_id": "dan naungan yang terbentang luas,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 31, "text": "وَمَاۤءࣲ مَّسۡكُوبࣲ ۝٣١", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب اليمين، ما أعظم مكانتهم وجزاءهم!! هم في سِدْر لا شوك فيه، وموز متراكب بعضه على بعض، وظلٍّ دائم لا يزول، وماء جار لا ينقطع، وفاكهة كثيرة لا تنفَد ولا تنقطع عنهم، ولا يمنعهم منها مانع، وفرشٍ مرفوعة على السرر.", "isBasmala": false, "translation_en": "And outpouring water.", "translation_id": "dan air yang tercurah,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 32, "text": "وَفَـٰكِهَةࣲ كَثِیرَةࣲ ۝٣٢", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب اليمين، ما أعظم مكانتهم وجزاءهم!! هم في سِدْر لا شوك فيه، وموز متراكب بعضه على بعض، وظلٍّ دائم لا يزول، وماء جار لا ينقطع، وفاكهة كثيرة لا تنفَد ولا تنقطع عنهم، ولا يمنعهم منها مانع، وفرشٍ مرفوعة على السرر.", "isBasmala": false, "translation_en": "And abundant fruit.", "translation_id": "dan buah-buahan yang banyak,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 33, "text": "لَّا مَقۡطُوعَةࣲ وَلَا مَمۡنُوعَةࣲ ۝٣٣", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب اليمين، ما أعظم مكانتهم وجزاءهم!! هم في سِدْر لا شوك فيه، وموز متراكب بعضه على بعض، وظلٍّ دائم لا يزول، وماء جار لا ينقطع، وفاكهة كثيرة لا تنفَد ولا تنقطع عنهم، ولا يمنعهم منها مانع، وفرشٍ مرفوعة على السرر.", "isBasmala": false, "translation_en": "Neither withheld, nor forbidden.", "translation_id": "yang tidak berhenti (berbuah) dan tidak terlarang mengambilnya.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 34, "text": "وَفُرُشࣲ مَّرۡفُوعَةٍ ۝٣٤", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب اليمين، ما أعظم مكانتهم وجزاءهم!! هم في سِدْر لا شوك فيه، وموز متراكب بعضه على بعض، وظلٍّ دائم لا يزول، وماء جار لا ينقطع، وفاكهة كثيرة لا تنفَد ولا تنقطع عنهم، ولا يمنعهم منها مانع، وفرشٍ مرفوعة على السرر.", "isBasmala": false, "translation_en": "And uplifted mattresses.", "translation_id": "dan kasur-kasur yang tebal lagi empuk.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 35, "text": "إِنَّاۤ أَنشَأۡنَـٰهُنَّ إِنشَاۤءࣰ ۝٣٥", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إنا أنشأنا نساء أهل الجنة نشأة غير النشأة التي كانت في الدنيا، نشأة كاملة لا تقبل الفناء، فجعلناهن أبكارًا، متحببات إلى أزواجهن، في سنٍّ واحدة، خلقناهن لأصحاب اليمين.", "isBasmala": false, "translation_en": "We have created them of special creation.", "translation_id": "Sesungguhnya Kami menciptakan mereka (bidadari-bidadari) dengan langsung", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 36, "text": "فَجَعَلۡنَـٰهُنَّ أَبۡكَارًا ۝٣٦", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إنا أنشأنا نساء أهل الجنة نشأة غير النشأة التي كانت في الدنيا، نشأة كاملة لا تقبل الفناء، فجعلناهن أبكارًا، متحببات إلى أزواجهن، في سنٍّ واحدة، خلقناهن لأصحاب اليمين.", "isBasmala": false, "translation_en": "And made them virgins.", "translation_id": "dan Kami jadikan mereka gadis-gadis perawan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 37, "text": "عُرُبًا أَتۡرَابࣰا ۝٣٧", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إنا أنشأنا نساء أهل الجنة نشأة غير النشأة التي كانت في الدنيا، نشأة كاملة لا تقبل الفناء، فجعلناهن أبكارًا، متحببات إلى أزواجهن، في سنٍّ واحدة، خلقناهن لأصحاب اليمين.", "isBasmala": false, "translation_en": "Tender and un-aging.", "translation_id": "penuh cinta lagi sebaya umurnya.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 38, "text": "لِّأَصۡحَـٰبِ ٱلۡیَمِینِ ۝٣٨", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إنا أنشأنا نساء أهل الجنة نشأة غير النشأة التي كانت في الدنيا، نشأة كاملة لا تقبل الفناء، فجعلناهن أبكارًا، متحببات إلى أزواجهن، في سنٍّ واحدة، خلقناهن لأصحاب اليمين.", "isBasmala": false, "translation_en": "For those on the Right.", "translation_id": "(Kami ciptakan mereka) untuk golongan kanan,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 39, "text": "ثُلَّةࣱ مِّنَ ٱلۡأَوَّلِینَ ۝٣٩", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وهم جماعة كثيرة من الأولين، وجماعة كثيرة من الآخرين.", "isBasmala": false, "translation_en": "A throng from the ancients.", "translation_id": "(yaitu) segolongan besar dari orang-orang yang terdahulu.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 40, "text": "وَثُلَّةࣱ مِّنَ ٱلۡـَٔاخِرِینَ ۝٤٠", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وهم جماعة كثيرة من الأولين، وجماعة كثيرة من الآخرين.", "isBasmala": false, "translation_en": "And a throng from the latecomers.", "translation_id": "dan segolongan besar pula dari orang-orang yang kemudian.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 41, "text": "وَأَصۡحَـٰبُ ٱلشِّمَالِ مَاۤ أَصۡحَـٰبُ ٱلشِّمَالِ ۝٤١", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب الشمال ما أسوأ حالهم جزاءهم!! في ريح حارة من حَرِّ نار جهنم تأخذ بأنفاسهم، وماء حار يغلي، وظلٍّ من دخان شديد السواد، لا بارد المنزل، ولا كريم المنظر.", "isBasmala": false, "translation_en": "And those on the Left-what of those on the Left?", "translation_id": "Dan golongan kiri, siapakah golongan kiri itu?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 42, "text": "فِی سَمُومࣲ وَحَمِیمࣲ ۝٤٢", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب الشمال ما أسوأ حالهم جزاءهم!! في ريح حارة من حَرِّ نار جهنم تأخذ بأنفاسهم، وماء حار يغلي، وظلٍّ من دخان شديد السواد، لا بارد المنزل، ولا كريم المنظر.", "isBasmala": false, "translation_en": "Amid searing wind and boiling water.", "translation_id": "Dalam (siksaan) angin yang amat panas, dan air panas yang mendidih,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 43, "text": "وَظِلࣲّ مِّن یَحۡمُومࣲ ۝٤٣", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب الشمال ما أسوأ حالهم جزاءهم!! في ريح حارة من حَرِّ نار جهنم تأخذ بأنفاسهم، وماء حار يغلي، وظلٍّ من دخان شديد السواد، لا بارد المنزل، ولا كريم المنظر.", "isBasmala": false, "translation_en": "And a shadow of thick smoke.", "translation_id": "dan dalam naungan asap yang hitam.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 44, "text": "لَّا بَارِدࣲ وَلَا كَرِیمٍ ۝٤٤", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وأصحاب الشمال ما أسوأ حالهم جزاءهم!! في ريح حارة من حَرِّ نار جهنم تأخذ بأنفاسهم، وماء حار يغلي، وظلٍّ من دخان شديد السواد، لا بارد المنزل، ولا كريم المنظر.", "isBasmala": false, "translation_en": "Neither cool, nor refreshing.", "translation_id": "Tidak sejuk dan tidak menyenangkan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 45, "text": "إِنَّهُمۡ كَانُوا۟ قَبۡلَ ذَ ٰلِكَ مُتۡرَفِینَ ۝٤٥", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "إنهم كانوا في الدنيا متنعِّمين بالحرام، معرِضين عما جاءتهم به الرسل.", "isBasmala": false, "translation_en": "They had lived before that in luxury.", "translation_id": "Sesungguhnya mereka sebelum itu hidup bermewahan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 46, "text": "وَكَانُوا۟ یُصِرُّونَ عَلَى ٱلۡحِنثِ ٱلۡعَظِیمِ ۝٤٦", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وكانوا يقيمون على الكفر بالله والإشراك به ومعصيته، ولا ينوون التوبة من ذلك.", "isBasmala": false, "translation_en": "And they used to persist in immense wrongdoing.", "translation_id": "Dan mereka terus-menerus mengerjakan dosa besar.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 47, "text": "وَكَانُوا۟ یَقُولُونَ أَىِٕذَا مِتۡنَا وَكُنَّا تُرَابࣰا وَعِظَـٰمًا أَءِنَّا لَمَبۡعُوثُونَ ۝٤٧", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "وكانوا يقولون إنكارًا للبعث: أنُبعث إذا متنا وصرنا ترابًا وعظامًا بالية؟ وهذا استبعاد منهم لأمر البعث وتكذيب له.", "isBasmala": false, "translation_en": "And they used to say, \"When we are dead and turned into dust and bones, are we to be resurrected?", "translation_id": "Dan mereka selalu mengatakan: \"Apakah bila kami mati dan menjadi tanah dan tulang belulang, apakah sesungguhnya kami akan benar-benar dibangkitkan kembali?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 48, "text": "أَوَ ءَابَاۤؤُنَا ٱلۡأَوَّلُونَ ۝٤٨", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أنُبعث نحن وآبناؤنا الأقدمون الذين صاروا ترابًا، قد تفرَّق في الأرض؟", "isBasmala": false, "translation_en": "And our ancient ancestors too?\"", "translation_id": "apakah bapak-bapak kami yang terdahulu (juga)?\"", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 49, "text": "قُلۡ إِنَّ ٱلۡأَوَّلِینَ وَٱلۡـَٔاخِرِینَ ۝٤٩", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "قل لهم -أيها الرسول-: إن الأولين والآخرين من بني آدم سيُجمَعون في يوم مؤقت بوقت محدد، وهو يوم القيامة.", "isBasmala": false, "translation_en": "Say, \"The first and the last.", "translation_id": "Katakanlah: \"Sesungguhnya orang-orang yang terdahulu dan orang-orang yang terkemudian,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 50, "text": "لَمَجۡمُوعُونَ إِلَىٰ مِیقَـٰتِ یَوۡمࣲ مَّعۡلُومࣲ ۝٥٠", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "قل لهم -أيها الرسول-: إن الأولين والآخرين من بني آدم سيُجمَعون في يوم مؤقت بوقت محدد، وهو يوم القيامة.", "isBasmala": false, "translation_en": "Will be gathered for the appointment of a familiar Day.\"", "translation_id": "benar-benar akan dikumpulkan di waktu tertentu pada hari yang dikenal.", "manzil": 7, "manzil_display": ""}], "536": [{"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 51, "text": "ثُمَّ إِنَّكُمۡ أَیُّهَا ٱلضَّاۤلُّونَ ٱلۡمُكَذِّبُونَ ۝٥١", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ثم إنكم أيها الضالون عن طريق الهدى المكذبون بوعيد الله ووعده، لآكلون من شجر من زقوم، وهو من أقبح الشجر، فمالئون منها بطونكم؛ لشدة الجوع، فشاربون عليه ماء متناهيًا في الحرارة لا يَرْوي ظمأ، فشاربون منه بكثرة، كشرب الإبل العطاش التي لا تَرْوى لداء يصيبها.", "isBasmala": false, "translation_en": "Then you, you misguided, who deny the truth.", "translation_id": "Kemudian sesungguhnya kamu hai orang-orang yang sesat lagi mendustakan,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 52, "text": "لَـَٔاكِلُونَ مِن شَجَرࣲ مِّن زَقُّومࣲ ۝٥٢", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ثم إنكم أيها الضالون عن طريق الهدى المكذبون بوعيد الله ووعده، لآكلون من شجر من زقوم، وهو من أقبح الشجر، فمالئون منها بطونكم؛ لشدة الجوع، فشاربون عليه ماء متناهيًا في الحرارة لا يَرْوي ظمأ، فشاربون منه بكثرة، كشرب الإبل العطاش التي لا تَرْوى لداء يصيبها.", "isBasmala": false, "translation_en": "Will be eating from the Tree of Bitterness.", "translation_id": "benar-benar akan memakan pohon zaqqum,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 53, "text": "فَمَالِـُٔونَ مِنۡهَا ٱلۡبُطُونَ ۝٥٣", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ثم إنكم أيها الضالون عن طريق الهدى المكذبون بوعيد الله ووعده، لآكلون من شجر من زقوم، وهو من أقبح الشجر، فمالئون منها بطونكم؛ لشدة الجوع، فشاربون عليه ماء متناهيًا في الحرارة لا يَرْوي ظمأ، فشاربون منه بكثرة، كشرب الإبل العطاش التي لا تَرْوى لداء يصيبها.", "isBasmala": false, "translation_en": "Will be filling your bellies with it.", "translation_id": "dan akan memenuhi perutmu dengannya.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 54, "text": "فَشَـٰرِبُونَ عَلَیۡهِ مِنَ ٱلۡحَمِیمِ ۝٥٤", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ثم إنكم أيها الضالون عن طريق الهدى المكذبون بوعيد الله ووعده، لآكلون من شجر من زقوم، وهو من أقبح الشجر، فمالئون منها بطونكم؛ لشدة الجوع، فشاربون عليه ماء متناهيًا في الحرارة لا يَرْوي ظمأ، فشاربون منه بكثرة، كشرب الإبل العطاش التي لا تَرْوى لداء يصيبها.", "isBasmala": false, "translation_en": "Will be drinking on top of it boiling water.", "translation_id": "Sesudah itu kamu akan meminum air yang sangat panas.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 55, "text": "فَشَـٰرِبُونَ شُرۡبَ ٱلۡهِیمِ ۝٥٥", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ثم إنكم أيها الضالون عن طريق الهدى المكذبون بوعيد الله ووعده، لآكلون من شجر من زقوم، وهو من أقبح الشجر، فمالئون منها بطونكم؛ لشدة الجوع، فشاربون عليه ماء متناهيًا في الحرارة لا يَرْوي ظمأ، فشاربون منه بكثرة، كشرب الإبل العطاش التي لا تَرْوى لداء يصيبها.", "isBasmala": false, "translation_en": "Drinking like thirsty camels drink.", "translation_id": "Maka kamu minum seperti unta yang sangat haus minum.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 56, "text": "هَـٰذَا نُزُلُهُمۡ یَوۡمَ ٱلدِّینِ ۝٥٦", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "هذا الذي يلقونه من العذاب هو ما أُعدَّ لهم من الزاد يوم القيامة. وفي هذا توبيخ لهم وتهكُّم بهم.", "isBasmala": false, "translation_en": "That is their hospitality on the Day of Retribution.", "translation_id": "Itulah hidangan untuk mereka pada hari Pembalasan\".", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 57, "text": "نَحۡنُ خَلَقۡنَـٰكُمۡ فَلَوۡلَا تُصَدِّقُونَ ۝٥٧", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "نحن خلقناكم- أيها الناس- ولم تكونوا شيئًا، فهلا تصدِّقون بالبعث.", "isBasmala": false, "translation_en": "We created you-if only you would believe!", "translation_id": "Kami telah menciptakan kamu, maka mengapa kamu tidak membenarkan?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 58, "text": "أَفَرَءَیۡتُم مَّا تُمۡنُونَ ۝٥٨", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم النُّطَف التي تقذفونها في أرحام نسائكم، هل أنتم تخلقون ذلك بشرًا أم نحن الخالقون؟", "isBasmala": false, "translation_en": "Have you seen what you ejaculate?", "translation_id": "Maka terangkanlah kepadaku tentang nutfah yang kamu pancarkan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 59, "text": "ءَأَنتُمۡ تَخۡلُقُونَهُۥۤ أَمۡ نَحۡنُ ٱلۡخَـٰلِقُونَ ۝٥٩", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم النُّطَف التي تقذفونها في أرحام نسائكم، هل أنتم تخلقون ذلك بشرًا أم نحن الخالقون؟", "isBasmala": false, "translation_en": "Is it you who create it, or are We the Creator?", "translation_id": "Kamukah yang menciptakannya, atau Kamikah yang menciptakannya?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 60, "text": "نَحۡنُ قَدَّرۡنَا بَیۡنَكُمُ ٱلۡمَوۡتَ وَمَا نَحۡنُ بِمَسۡبُوقِینَ ۝٦٠", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "نحن قَدَّرنا بينكم الموت، وما نحن بعاجزين عن أن نغيِّر خلقكم يوم القيامة، وننشئكم فيما لا تعلمونه من الصفات والأحوال.", "isBasmala": false, "translation_en": "We have decreed death among you, and We will not be outstripped.", "translation_id": "Kami telah menentukan kematian di antara kamu dan Kami sekali-sekali tidak akan dapat dikalahkan,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 61, "text": "عَلَىٰۤ أَن نُّبَدِّلَ أَمۡثَـٰلَكُمۡ وَنُنشِئَكُمۡ فِی مَا لَا تَعۡلَمُونَ ۝٦١", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "نحن قَدَّرنا بينكم الموت، وما نحن بعاجزين عن أن نغيِّر خلقكم يوم القيامة، وننشئكم فيما لا تعلمونه من الصفات والأحوال.", "isBasmala": false, "translation_en": "In replacing you with your likes, and transforming you into what you do not know.", "translation_id": "untuk menggantikan kamu dengan orang-orang yang seperti kamu (dalam dunia) dan menciptakan kamu kelak (di akhirat) dalam keadaan yang tidak kamu ketahui.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 62, "text": "وَلَقَدۡ عَلِمۡتُمُ ٱلنَّشۡأَةَ ٱلۡأُولَىٰ فَلَوۡلَا تَذَكَّرُونَ ۝٦٢", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "ولقد علمتم أن الله أنشأكم النشأة الأولى ولم تكونوا شيئًا، فهلا تذكَّرون قدرة الله على إنشائكم مرة أخرى.", "isBasmala": false, "translation_en": "You have known the first formation; if only you would remember.", "translation_id": "Dan Sesungguhnya kamu telah mengetahui penciptaan yang pertama, maka mengapakah kamu tidak mengambil pelajaran (untuk penciptaan yang kedua)?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 63, "text": "أَفَرَءَیۡتُم مَّا تَحۡرُثُونَ ۝٦٣", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم الحرث الذي تحرثونه هل أنتم تُنبتونه في الأرض؟ بل نحن نُقِرُّ قراره وننبته في الأرض. لو نشاء لجعلنا ذلك الزرع هشيمًا، لا يُنتفع به في مطعم، فأصبحتم تتعجبون مما نزل بزرعكم، وتقولون: إنا لخاسرون معذَّبون، بل نحن محرومون من الرزق.", "isBasmala": false, "translation_en": "Have you seen what you cultivate?", "translation_id": "Maka terangkanlah kepadaku tentang yang kamu tanam.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 64, "text": "ءَأَنتُمۡ تَزۡرَعُونَهُۥۤ أَمۡ نَحۡنُ ٱلزَّ ٰرِعُونَ ۝٦٤", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم الحرث الذي تحرثونه هل أنتم تُنبتونه في الأرض؟ بل نحن نُقِرُّ قراره وننبته في الأرض. لو نشاء لجعلنا ذلك الزرع هشيمًا، لا يُنتفع به في مطعم، فأصبحتم تتعجبون مما نزل بزرعكم، وتقولون: إنا لخاسرون معذَّبون، بل نحن محرومون من الرزق.", "isBasmala": false, "translation_en": "Is it you who make it grow, or are We the Grower?", "translation_id": "Kamukah yang menumbuhkannya atau Kamikah yang menumbuhkannya?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 65, "text": "لَوۡ نَشَاۤءُ لَجَعَلۡنَـٰهُ حُطَـٰمࣰا فَظَلۡتُمۡ تَفَكَّهُونَ ۝٦٥", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم الحرث الذي تحرثونه هل أنتم تُنبتونه في الأرض؟ بل نحن نُقِرُّ قراره وننبته في الأرض. لو نشاء لجعلنا ذلك الزرع هشيمًا، لا يُنتفع به في مطعم، فأصبحتم تتعجبون مما نزل بزرعكم، وتقولون: إنا لخاسرون معذَّبون، بل نحن محرومون من الرزق.", "isBasmala": false, "translation_en": "If We will, We can turn it into rubble; then you will lament.", "translation_id": "Kalau Kami kehendaki, benar-benar Kami jadikan dia hancur dan kering, maka jadilah kamu heran dan tercengang.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 66, "text": "إِنَّا لَمُغۡرَمُونَ ۝٦٦", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم الحرث الذي تحرثونه هل أنتم تُنبتونه في الأرض؟ بل نحن نُقِرُّ قراره وننبته في الأرض. لو نشاء لجعلنا ذلك الزرع هشيمًا، لا يُنتفع به في مطعم، فأصبحتم تتعجبون مما نزل بزرعكم، وتقولون: إنا لخاسرون معذَّبون، بل نحن محرومون من الرزق.", "isBasmala": false, "translation_en": "\"We are penalized.", "translation_id": "(Sambil berkata): \"Sesungguhnya kami benar-benar menderita kerugian\",", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 67, "text": "بَلۡ نَحۡنُ مَحۡرُومُونَ ۝٦٧", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم الحرث الذي تحرثونه هل أنتم تُنبتونه في الأرض؟ بل نحن نُقِرُّ قراره وننبته في الأرض. لو نشاء لجعلنا ذلك الزرع هشيمًا، لا يُنتفع به في مطعم، فأصبحتم تتعجبون مما نزل بزرعكم، وتقولون: إنا لخاسرون معذَّبون، بل نحن محرومون من الرزق.", "isBasmala": false, "translation_en": "No, we are being deprived.\"", "translation_id": "bahkan kami menjadi orang-orang yang tidak mendapat hasil apa-apa.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 68, "text": "أَفَرَءَیۡتُمُ ٱلۡمَاۤءَ ٱلَّذِی تَشۡرَبُونَ ۝٦٨", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم الماء الذي تشربونه لتحْيَوا به، أأنتم أنزلتموه من السحاب إلى قرار الأرض، أم نحن الذين أنزلناه رحمة بكم؟", "isBasmala": false, "translation_en": "Have you seen the water you drink?", "translation_id": "Maka terangkanlah kepadaku tentang air yang kamu minum.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 69, "text": "ءَأَنتُمۡ أَنزَلۡتُمُوهُ مِنَ ٱلۡمُزۡنِ أَمۡ نَحۡنُ ٱلۡمُنزِلُونَ ۝٦٩", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم الماء الذي تشربونه لتحْيَوا به، أأنتم أنزلتموه من السحاب إلى قرار الأرض، أم نحن الذين أنزلناه رحمة بكم؟", "isBasmala": false, "translation_en": "Is it you who sent it down from the clouds, or are We the Sender?", "translation_id": "Kamukah yang menurunkannya atau Kamikah yang menurunkannya?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 70, "text": "لَوۡ نَشَاۤءُ جَعَلۡنَـٰهُ أُجَاجࣰا فَلَوۡلَا تَشۡكُرُونَ ۝٧٠", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "لو نشاء جعلنا هذا الماء شديد الملوحة، لا يُنتفع به في شرب ولا زرع، فهلا تشكرون ربكم على إنزال الماء العذب لنفعكم.", "isBasmala": false, "translation_en": "If We will, We can make it salty. Will you not be thankful?", "translation_id": "Kalau Kami kehendaki, niscaya Kami jadikan dia asin, maka mengapakah kamu tidak bersyukur?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 71, "text": "أَفَرَءَیۡتُمُ ٱلنَّارَ ٱلَّتِی تُورُونَ ۝٧١", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم النار التي توقدون، أأنتم أوجدتم شجرتها التي تقدح منها النار، أم نحن الموجدون لها؟", "isBasmala": false, "translation_en": "Have you seen the fire you kindle?", "translation_id": "Maka terangkanlah kepadaku tentang api yang kamu nyalakan (dengan menggosok-gosokkan kayu).", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 72, "text": "ءَأَنتُمۡ أَنشَأۡتُمۡ شَجَرَتَهَاۤ أَمۡ نَحۡنُ ٱلۡمُنشِـُٔونَ ۝٧٢", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "أفرأيتم النار التي توقدون، أأنتم أوجدتم شجرتها التي تقدح منها النار، أم نحن الموجدون لها؟", "isBasmala": false, "translation_en": "Is it you who produce its tree, or are We the Producer?", "translation_id": "Kamukah yang menjadikan kayu itu atau Kamikah yang menjadikannya?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 73, "text": "نَحۡنُ جَعَلۡنَـٰهَا تَذۡكِرَةࣰ وَمَتَـٰعࣰا لِّلۡمُقۡوِینَ ۝٧٣", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "نحن جعلنا ناركم التي توقدون تذكيرًا لكم بنار جهنم ومنفعة للمسافرين.", "isBasmala": false, "translation_en": "We have made it a reminder, and a comfort for the users.", "translation_id": "Kami jadikan api itu untuk peringatan dan bahan yang berguna bagi musafir di padang pasir.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 74, "text": "فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِیمِ ۝٧٤", "juz": 27, "hizb": "(*¼ ح 54*)", "tafsir": "فنزِّه -أيها النبي- ربك العظيم كامل الأسماء والصفات، كثير الإحسان والخيرات.", "isBasmala": false, "translation_en": "So glorify the Name of your Great Lord.", "translation_id": "Maka bertasbihlah dengan (menyebut) nama Rabbmu Yang Maha Besar.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 75, "text": "۞ فَلَاۤ أُقۡسِمُ بِمَوَ ٰقِعِ ٱلنُّجُومِ ۝٧٥", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "أقسم الله تعالى بمساقط النجوم في مغاربها في السماء، وإنه لَقَسم لو تعلمون قَدَره عظيم.", "isBasmala": false, "translation_en": "I swear by the locations of the stars.", "translation_id": "Maka Aku bersumpah dengan masa turunnya bagian-bagian Al-Quran.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 76, "text": "وَإِنَّهُۥ لَقَسَمࣱ لَّوۡ تَعۡلَمُونَ عَظِیمٌ ۝٧٦", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "أقسم الله تعالى بمساقط النجوم في مغاربها في السماء، وإنه لَقَسم لو تعلمون قَدَره عظيم.", "isBasmala": false, "translation_en": "It is an oath, if you only knew, that is tremendous.", "translation_id": "Sesungguhnya sumpah itu adalah sumpah yang besar kalau kamu mengetahui.", "manzil": 7, "manzil_display": ""}], "537": [{"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 77, "text": "إِنَّهُۥ لَقُرۡءَانࣱ كَرِیمࣱ ۝٧٧", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "إن هذا القرآن الذي نزل على محمد لقرآن عظيم المنافع، كثير الخير، غزير العلم، في كتاب مَصُون مستور عن أعين الخلق، وهو الكتاب الذي بأيدي الملائكة. لا يَمَسُّ القرآن إلا الملائكة الكرام الذين طهرهم الله من الآفات والذنوب، ولا يَمَسُّه أيضًا إلا المتطهرون من الشرك والجنابة والحدث.", "isBasmala": false, "translation_en": "It is a noble Quran.", "translation_id": "Sesungguhnya Al-Quran ini adalah bacaan yang sangat mulia,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 78, "text": "فِی كِتَـٰبࣲ مَّكۡنُونࣲ ۝٧٨", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "إن هذا القرآن الذي نزل على محمد لقرآن عظيم المنافع، كثير الخير، غزير العلم، في كتاب مَصُون مستور عن أعين الخلق، وهو الكتاب الذي بأيدي الملائكة. لا يَمَسُّ القرآن إلا الملائكة الكرام الذين طهرهم الله من الآفات والذنوب، ولا يَمَسُّه أيضًا إلا المتطهرون من الشرك والجنابة والحدث.", "isBasmala": false, "translation_en": "In a well-protected Book.", "translation_id": "pada kitab yang terpelihara (Lauhul Mahfuzh),", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 79, "text": "لَّا یَمَسُّهُۥۤ إِلَّا ٱلۡمُطَهَّرُونَ ۝٧٩", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "إن هذا القرآن الذي نزل على محمد لقرآن عظيم المنافع، كثير الخير، غزير العلم، في كتاب مَصُون مستور عن أعين الخلق، وهو الكتاب الذي بأيدي الملائكة. لا يَمَسُّ القرآن إلا الملائكة الكرام الذين طهرهم الله من الآفات والذنوب، ولا يَمَسُّه أيضًا إلا المتطهرون من الشرك والجنابة والحدث.", "isBasmala": false, "translation_en": "None can grasp it except the purified.", "translation_id": "tidak menyentuhnya kecuali orang-orang yang disucikan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 80, "text": "تَنزِیلࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ ۝٨٠", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وهذا القرآن الكريم منزل من رب العالمين، فهو الحق الذي لا مرية فيه.", "isBasmala": false, "translation_en": "A revelation from the Lord of the Worlds.", "translation_id": "Diturunkan dari Rabbil 'alamiin.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 81, "text": "أَفَبِهَـٰذَا ٱلۡحَدِیثِ أَنتُم مُّدۡهِنُونَ ۝٨١", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "أفبهذا القرآن أنتم -أيها المشركون- مكذِّبون؟", "isBasmala": false, "translation_en": "Is it this discourse that you take so lightly?", "translation_id": "Maka apakah kamu menganggap remeh saja Al-Quran ini?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 82, "text": "وَتَجۡعَلُونَ رِزۡقَكُمۡ أَنَّكُمۡ تُكَذِّبُونَ ۝٨٢", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وتجعلون شكركم لنعم الله عليكم أنكم تكذِّبون بها وتكفرون؟ وفي هذا إنكار على من يتهاون بأمر القرآن ولا يبالي بدعوته.", "isBasmala": false, "translation_en": "And you make it your livelihood to deny it?", "translation_id": "kamu mengganti rezeki (yang Allah berikan) dengan mendustakan Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 83, "text": "فَلَوۡلَاۤ إِذَا بَلَغَتِ ٱلۡحُلۡقُومَ ۝٨٣", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "فهل تستطيعون إذا بلغت نفس أحدكم الحلقوم عند النزع، وأنتم حضور تنظرون إليه، أن تمسكوا روحه في جسده؟ لن تستطيعوا ذلك، ونحن أقرب إليه منكم بملائكتنا، ولكنكم لا ترونهم.", "isBasmala": false, "translation_en": "So when it has reached the throat.", "translation_id": "Maka mengapa ketika nyawa sampai di kerongkongan,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 84, "text": "وَأَنتُمۡ حِینَىِٕذࣲ تَنظُرُونَ ۝٨٤", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "فهل تستطيعون إذا بلغت نفس أحدكم الحلقوم عند النزع، وأنتم حضور تنظرون إليه، أن تمسكوا روحه في جسده؟ لن تستطيعوا ذلك، ونحن أقرب إليه منكم بملائكتنا، ولكنكم لا ترونهم.", "isBasmala": false, "translation_en": "As you are looking on.", "translation_id": "padahal kamu ketika itu melihat,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 85, "text": "وَنَحۡنُ أَقۡرَبُ إِلَیۡهِ مِنكُمۡ وَلَـٰكِن لَّا تُبۡصِرُونَ ۝٨٥", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "فهل تستطيعون إذا بلغت نفس أحدكم الحلقوم عند النزع، وأنتم حضور تنظرون إليه، أن تمسكوا روحه في جسده؟ لن تستطيعوا ذلك، ونحن أقرب إليه منكم بملائكتنا، ولكنكم لا ترونهم.", "isBasmala": false, "translation_en": "We are nearer to it than you are, but you do not see.", "translation_id": "dan Kami lebih dekat kepadanya dari pada kamu. Tetapi kamu tidak melihat,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 86, "text": "فَلَوۡلَاۤ إِن كُنتُمۡ غَیۡرَ مَدِینِینَ ۝٨٦", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وهل تستطيعون إن كنتم غير محاسبين ولا مجزيين بأعمالكم أن تعيدوا الروح إلى الجسد، إن كنتم صادقين؟ لن ترجعوها.", "isBasmala": false, "translation_en": "If you are not held to account.", "translation_id": "maka mengapa jika kamu tidak dikuasai (oleh Allah)?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 87, "text": "تَرۡجِعُونَهَاۤ إِن كُنتُمۡ صَـٰدِقِینَ ۝٨٧", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وهل تستطيعون إن كنتم غير محاسبين ولا مجزيين بأعمالكم أن تعيدوا الروح إلى الجسد، إن كنتم صادقين؟ لن ترجعوها.", "isBasmala": false, "translation_en": "Then bring it back, if you are truthful.", "translation_id": "Kamu tidak mengembalikan nyawa itu (kepada tempatnya) jika kamu adalah orang-orang yang benar?", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 88, "text": "فَأَمَّاۤ إِن كَانَ مِنَ ٱلۡمُقَرَّبِینَ ۝٨٨", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "فأما إن كان الميت من السابقين المقربين، فله عند موته الرحمة الواسعة والفرح وما تطيب به نفسه، وله جنة النعيم في الآخرة.", "isBasmala": false, "translation_en": "But if he is one of those brought near.", "translation_id": "adapun jika dia (orang yang mati) termasuk orang-orang yang didekatkan (kepada Allah),", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 89, "text": "فَرَوۡحࣱ وَرَیۡحَانࣱ وَجَنَّتُ نَعِیمࣲ ۝٨٩", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "فأما إن كان الميت من السابقين المقربين، فله عند موته الرحمة الواسعة والفرح وما تطيب به نفسه، وله جنة النعيم في الآخرة.", "isBasmala": false, "translation_en": "Then happiness, and flowers, and Garden of Delights.", "translation_id": "maka dia memperoleh ketenteraman dan rezeki serta jannah kenikmatan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 90, "text": "وَأَمَّاۤ إِن كَانَ مِنۡ أَصۡحَـٰبِ ٱلۡیَمِینِ ۝٩٠", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وأما إن كان الميت من أصحاب اليمين، فيقال له: سلامة لك وأمن؛ لكونك من أصحاب اليمين.", "isBasmala": false, "translation_en": "And if he is one of those on the Right.", "translation_id": "Dan adapun jika dia termasuk golongan kanan,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 91, "text": "فَسَلَـٰمࣱ لَّكَ مِنۡ أَصۡحَـٰبِ ٱلۡیَمِینِ ۝٩١", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وأما إن كان الميت من أصحاب اليمين، فيقال له: سلامة لك وأمن؛ لكونك من أصحاب اليمين.", "isBasmala": false, "translation_en": "Then, \"Peace upon you,\" from those on the Right.", "translation_id": "maka keselamatanlah bagimu karena kamu dari golongan kanan.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 92, "text": "وَأَمَّاۤ إِن كَانَ مِنَ ٱلۡمُكَذِّبِینَ ٱلضَّاۤلِّینَ ۝٩٢", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وأما إن كان الميت من المكذبين بالبعث، الضالين عن الهدى، فله ضيافة من شراب جهنم المغلي المتناهي الحرارة، والنار يحرق بها، ويقاسي عذابها الشديد.", "isBasmala": false, "translation_en": "But if he is one of the deniers, the mistaken.", "translation_id": "Dan adapun jika dia termasuk golongan yang mendustakan lagi sesat,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 93, "text": "فَنُزُلࣱ مِّنۡ حَمِیمࣲ ۝٩٣", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وأما إن كان الميت من المكذبين بالبعث، الضالين عن الهدى، فله ضيافة من شراب جهنم المغلي المتناهي الحرارة، والنار يحرق بها، ويقاسي عذابها الشديد.", "isBasmala": false, "translation_en": "Then a welcome of Inferno.", "translation_id": "maka dia mendapat hidangan air yang mendidih,", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 94, "text": "وَتَصۡلِیَةُ جَحِیمٍ ۝٩٤", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وأما إن كان الميت من المكذبين بالبعث، الضالين عن الهدى، فله ضيافة من شراب جهنم المغلي المتناهي الحرارة، والنار يحرق بها، ويقاسي عذابها الشديد.", "isBasmala": false, "translation_en": "And burning in Hell.", "translation_id": "dan dibakar di dalam jahannam.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 95, "text": "إِنَّ هَـٰذَا لَهُوَ حَقُّ ٱلۡیَقِینِ ۝٩٥", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "إن هذا الذي قصصناه عليك -أيها الرسول- لهو حق اليقين الذي لا مرية فيه، فسبِّح باسم ربك العظيم، ونزِّهه عما يقول الظالمون والجاحدون، تعالى الله عما يقولون علوًا كبيرًا.", "isBasmala": false, "translation_en": "This is the certain truth.", "translation_id": "Sesungguhnya (yang disebutkan ini) adalah suatu keyakinan yang benar.", "manzil": 7, "manzil_display": ""}, {"sura": 56, "sura_name": "الواقعة", "revelation": "Makkiyah", "aya": 96, "text": "فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِیمِ ۝٩٦", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "إن هذا الذي قصصناه عليك -أيها الرسول- لهو حق اليقين الذي لا مرية فيه، فسبِّح باسم ربك العظيم، ونزِّهه عما يقول الظالمون والجاحدون، تعالى الله عما يقولون علوًا كبيرًا.", "isBasmala": false, "translation_en": "So glorify the Name of your Lord, the Magnificent", "translation_id": "Maka bertasbihlah dengan (menyebut) nama Rabbmu yang Maha Besar.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 27, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 1, "text": "سَبَّحَ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝١", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "نزَّه الله عن السوء كلُّ ما في السموات والأرض من جميع مخلوقاته، وهو العزيز على خلقه، الحكيم في تدبير أمورهم.", "isBasmala": false, "translation_en": "Glorifying God is everything in the heavens and the earth. He is the Almighty, the Wise.", "translation_id": "Semua yang berada di langit dan yang berada di bumi bertasbih kepada Allah (menyatakan kebesaran Allah). Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 2, "text": "لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ یُحۡیِۦ وَیُمِیتُۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝٢", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "له ملك السموات والأرض وما فيهما، فهو المالك المتصرف في خلقه، يحيي ويميت، وهو على كل شيء قدير، لا يتعذَّر عليه شيء أراده، فما شاءه كان، وما لم يشأ لم يكن.", "isBasmala": false, "translation_en": "To Him belongs the kingdom of the heavens and the earth. He gives life and causes death, and He has power over all things.", "translation_id": "Kepunyaan-Nya-lah kerajaan langit dan bumi, Dia menghidupkan dan mematikan, dan Dia Maha Kuasa atas segala sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 3, "text": "هُوَ ٱلۡأَوَّلُ وَٱلۡـَٔاخِرُ وَٱلظَّـٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَیۡءٍ عَلِیمٌ ۝٣", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "هو الأول الذي ليس قبله شيء، والآخر الذي ليس بعده شيء، والظاهر الذي ليس فوقه شيء، والباطن الذي ليس دونه شيء، ولا تخفى عليه خافية في الأرض ولا في السماء، وهو بكل شيء عليم.", "isBasmala": false, "translation_en": "He is the First and the Last, and the Outer and the Inner, and He has knowledge of all things.", "translation_id": "Dialah Yang Awal dan Yang Akhir Yang Zhahir dan Yang Bathin; dan Dia Maha Mengetahui segala sesuatu.", "manzil": 7, "manzil_display": ""}], "538": [{"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 4, "text": "هُوَ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ یَعۡلَمُ مَا یَلِجُ فِی ٱلۡأَرۡضِ وَمَا یَخۡرُجُ مِنۡهَا وَمَا یَنزِلُ مِنَ ٱلسَّمَاۤءِ وَمَا یَعۡرُجُ فِیهَاۖ وَهُوَ مَعَكُمۡ أَیۡنَ مَا كُنتُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ ۝٤", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "هو الذي خلق السموات والأرض وما بينهما في ستة أيام، ثم استوى -أي علا وارتفع- على عرشه فوق جميع خلقه استواء يليق بجلاله، يعلم ما يدخل في الأرض من حب ومطر وغير ذلك، وما يخرج منها من نبات وزرع وثمار، وما ينزل من السماء من مطر وغيره، وما يعرج فيها من الملائكة والأعمال، وهو سبحانه معكم بعلمه أينما كنتم، والله بصير بأعمالكم التي تعملونها، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "It is He who created the heavens and the earth in six days, then settled over the Throne. He knows what penetrates into the earth, and what comes out of it, and what descends from the sky, and what ascends to it. And He is with you wherever you may be. God is Seeing of everything you do.", "translation_id": "Dialah yang menciptakan langit dan bumi dalam enam masa: Kemudian Dia bersemayam di atas 'Arsy. Dia mengetahui apa yang masuk ke dalam bumi dan apa yang keluar daripadanya dan apa yang turun dari langit dan apa yang naik kepada-Nya. Dan Dia bersama kamu di mana saja kamu berada. Dan Allah Maha Melihat apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 5, "text": "لَّهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ ۝٥", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "له ملك السموات والأرض، وإلى الله مصير أمور الخلائق في الآخرة، وسيجازيهم على أعمالهم.", "isBasmala": false, "translation_en": "To Him belongs the kingship of the heavens and the earth, and to God all matters are referred.", "translation_id": "Kepunyaan-Nya-lah kerajaan langit dan bumi. Dan kepada Allah-lah dikembalikan segala urusan.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 6, "text": "یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِۚ وَهُوَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝٦", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "يُدْخِل ما نقص من ساعات الليل في النهار فيزيد النهار، ويُدْخِل ما نقص من ساعات النهار في الليل فيزيد الليل، وهو سبحانه عليم بما في صدور خلقه.", "isBasmala": false, "translation_en": "He merges the night into the day, and He merges the day into the night; and He knows what the hearts contains.", "translation_id": "Dialah yang memasukkan malam ke dalam siang dan memasukkan siang ke dalam malam. Dan Dia Maha Mengetahui segala isi hati.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 7, "text": "ءَامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَأَنفِقُوا۟ مِمَّا جَعَلَكُم مُّسۡتَخۡلَفِینَ فِیهِۖ فَٱلَّذِینَ ءَامَنُوا۟ مِنكُمۡ وَأَنفَقُوا۟ لَهُمۡ أَجۡرࣱ كَبِیرࣱ ۝٧", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "آمنوا بالله ورسوله محمد صلى الله عليه وسلم، وأنفقوا مما رزقكم الله من المال واستخلفكم فيه، فالذين آمنوا منكم أيها الناس، وأنفقوا من مالهم، لهم ثواب عظيم.", "isBasmala": false, "translation_en": "Believe in God and His Messenger, and spend from what He made you inherit. Those among you who believe and give will have a great reward.", "translation_id": "Berimanlah kamu kepada Allah dan Rasul-Nya dan nafkahkanlah sebagian dari hartamu yang Allah telah menjadikan kamu menguasainya. Maka orang-orang yang beriman di antara kamu dan menafkahkan (sebagian) dari hartanya memperoleh pahala yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 8, "text": "وَمَا لَكُمۡ لَا تُؤۡمِنُونَ بِٱللَّهِ وَٱلرَّسُولُ یَدۡعُوكُمۡ لِتُؤۡمِنُوا۟ بِرَبِّكُمۡ وَقَدۡ أَخَذَ مِیثَـٰقَكُمۡ إِن كُنتُم مُّؤۡمِنِینَ ۝٨", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وأيُّ عذر لكم في أن لا تصدقوا بوحدانية الله وتعملوا بشرعه، والرسول يدعوكم إلى ذلك، وقد أخذ الله ميثاقكم على ذلك، إن كنتم مؤمنين بالله خالقكم؟", "isBasmala": false, "translation_en": "What is the matter with you that you do not believe in God, when the Messenger calls you to believe in your Lord, and He has received a pledge from you, if you are believers?", "translation_id": "Dan mengapa kamu tidak beriman kepada Allah padahal Rasul menyeru kamu supaya kamu beriman kepada Tuhanmu. Dan sesungguhnya Dia telah mengambil perjanjianmu jika kamu adalah orang-orang yang beriman.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 9, "text": "هُوَ ٱلَّذِی یُنَزِّلُ عَلَىٰ عَبۡدِهِۦۤ ءَایَـٰتِۭ بَیِّنَـٰتࣲ لِّیُخۡرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَإِنَّ ٱللَّهَ بِكُمۡ لَرَءُوفࣱ رَّحِیمࣱ ۝٩", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "هو الذي ينزل على عبده محمد صلى الله عليه وسلم آيات مفصلات واضحات من القرآن؛ ليخرجكم بذلك من ظلمة الكفر إلى نور الإيمان، إن الله بكم في إخراجكم من الظلمات إلى النور لِيَرْحمكم رحمة واسعة في عاجلكم وآجلكم، فيجازيكم أحسن الجزاء.", "isBasmala": false, "translation_en": "It is He who sends down upon His servant clear revelations, to bring you out of darkness into the light. God is Gentle towards you, Most Compassionate.", "translation_id": "Dialah yang menurunkan kepada hamba-Nya ayat-ayat yang terang (Al-Quran) supaya Dia mengeluarkan kamu dari kegelapan kepada cahaya. Dan sesungguhnya Allah benar-benar Maha Penyantun lagi Maha Penyayang terhadapmu.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 10, "text": "وَمَا لَكُمۡ أَلَّا تُنفِقُوا۟ فِی سَبِیلِ ٱللَّهِ وَلِلَّهِ مِیرَ ٰثُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ لَا یَسۡتَوِی مِنكُم مَّنۡ أَنفَقَ مِن قَبۡلِ ٱلۡفَتۡحِ وَقَـٰتَلَۚ أُو۟لَـٰۤىِٕكَ أَعۡظَمُ دَرَجَةࣰ مِّنَ ٱلَّذِینَ أَنفَقُوا۟ مِنۢ بَعۡدُ وَقَـٰتَلُوا۟ۚ وَكُلࣰّا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ ۝١٠", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "وأيُّ شيء يمنعكم من الإنفاق في سبيل الله؟ ولله ميراث السموات والأرض يرث كلَّ ما فيهما، ولا يبقى أحد مالكًا لشيء فيهما. لا يستوي في الأجر والمثوبة منكم مَن أنفق من قبل فتح \"مكة\" وقاتل الكفار، أولئك أعظم درجة عند الله من الذين أنفقوا في سبيل الله من بعد الفتح وقاتلوا الكفار، وكلا من الفريقين وعد الله الجنة، والله بأعمالكم خبير لا يخفى عليه شيء منها، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "And why is it that you do not spend in the cause of God, when to God belongs the inheritance of the heavens and the earth? Not equal among you are those who contributed before the conquest, and fought. Those are higher in rank than those who contributed afterwards, and fought. But God promises both a good reward. God is Well Experienced in what you do.", "translation_id": "Dan mengapa kamu tidak menafkahkan (sebagian hartamu) pada jalan Allah, padahal Allah-lah yang mempusakai (mempunyai) langit dan bumi? Tidak sama di antara kamu orang yang menafkahkan (hartanya) dan berperang sebelum penaklukan (Mekah). Mereka lebih tingi derajatnya daripada orang-orang yang menafkahkan (hartanya) dan berperang sesudah itu. Allah menjanjikan kepada masing-masing mereka (balasan) yang lebih baik. Dan Allah mengetahui apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 11, "text": "مَّن ذَا ٱلَّذِی یُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنࣰا فَیُضَـٰعِفَهُۥ لَهُۥ وَلَهُۥۤ أَجۡرࣱ كَرِیمࣱ ۝١١", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "من ذا الذي ينفق في سبيل الله محتسبًا من قلبه بلا مَنٍّ ولا أذى، فيضاعف له ربه الأجر والثواب، وله جزاء كريم، وهو الجنة؟", "isBasmala": false, "translation_en": "Who is he who will lend God a loan of goodness, that He may double it for him, and will have a generous reward?", "translation_id": "Siapakah yang mau meminjamkan kepada Allah pinjaman yang baik, maka Allah akan melipat-gandakan (balasan) pinjaman itu untuknya, dan dia akan memperoleh pahala yang banyak.", "manzil": 7, "manzil_display": ""}], "539": [{"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 12, "text": "یَوۡمَ تَرَى ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ یَسۡعَىٰ نُورُهُم بَیۡنَ أَیۡدِیهِمۡ وَبِأَیۡمَـٰنِهِمۖ بُشۡرَىٰكُمُ ٱلۡیَوۡمَ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ ذَ ٰلِكَ هُوَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝١٢", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "يوم ترى المؤمنين والمؤمنات يسعى نورهم على الصراط بين أيديهم وعن أيمانهم، بقدر أعمالهم، ويقال لهم: بشراكم اليوم دخول جنات واسعة تجري من تحت أشجارها الأنهار، لا تخرجون منها أبدًا، ذلك الجزاء هو الفوز العظيم لكم في الآخرة.", "isBasmala": false, "translation_en": "On the Day when you see the believing men and believing women-their light radiating ahead of them, and to their right: \"Good news for you today: gardens beneath which rivers flow, dwelling therein forever. That is the great triumph.\"", "translation_id": "(yaitu) pada hari ketika kamu melihat orang mukmin laki-laki dan perempuan, sedang cahaya mereka bersinar di hadapan dan di sebelah kanan mereka, (dikatakan kepada mereka): \"Pada hari ini ada berita gembira untukmu, (yaitu) surga yang mengalir di bawahnya sungai-sungai, yang kamu kekal di dalamnya. Itulah keberuntungan yang besar\".", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 13, "text": "یَوۡمَ یَقُولُ ٱلۡمُنَـٰفِقُونَ وَٱلۡمُنَـٰفِقَـٰتُ لِلَّذِینَ ءَامَنُوا۟ ٱنظُرُونَا نَقۡتَبِسۡ مِن نُّورِكُمۡ قِیلَ ٱرۡجِعُوا۟ وَرَاۤءَكُمۡ فَٱلۡتَمِسُوا۟ نُورࣰاۖ فَضُرِبَ بَیۡنَهُم بِسُورࣲ لَّهُۥ بَابُۢ بَاطِنُهُۥ فِیهِ ٱلرَّحۡمَةُ وَظَـٰهِرُهُۥ مِن قِبَلِهِ ٱلۡعَذَابُ ۝١٣", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "يوم يقول المنافقون والمنافقات للذين آمنوا، وهم على الصراط: انتظرونا نستضئْ من نوركم، فتقول لهم الملائكة: ارجعوا وراءكم فاطلبوا نورًا (سخرية منهم)، فَفُصِل بينهم بسور له باب، باطنه مما يلي المؤمنين فيه الرحمة، وظاهره مما يلي المنافقين من جهته العذاب.", "isBasmala": false, "translation_en": "On the Day when the hypocritical men and hypocritical women will say to those who believed, \"Wait for us; let us absorb some of your light.\" It will be said, \"Go back behind you, and seek light.\" A wall will be raised between them, in which is a door; within it is mercy, and outside it is agony.", "translation_id": "Pada hari ketika orang-orang munafik laki-laki dan perempuan berkata kepada orang-orang yang beriman: \"Tunggulah kami supaya kami dapat mengambil sebahagian dari cahayamu\". Dikatakan (kepada mereka): \"Kembalilah kamu ke belakang dan carilah sendiri cahaya (untukmu)\". Lalu diadakan di antara mereka dinding yang mempunyai pintu. Di sebelah dalamnya ada rahmat dan di sebelah luarnya dari situ ada siksa.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 14, "text": "یُنَادُونَهُمۡ أَلَمۡ نَكُن مَّعَكُمۡۖ قَالُوا۟ بَلَىٰ وَلَـٰكِنَّكُمۡ فَتَنتُمۡ أَنفُسَكُمۡ وَتَرَبَّصۡتُمۡ وَٱرۡتَبۡتُمۡ وَغَرَّتۡكُمُ ٱلۡأَمَانِیُّ حَتَّىٰ جَاۤءَ أَمۡرُ ٱللَّهِ وَغَرَّكُم بِٱللَّهِ ٱلۡغَرُورُ ۝١٤", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "ينادي المنافقون المؤمنين قائلين: ألم نكن معكم في الدنيا، نؤدي شعائر الدين مثلكم؟ قال المؤمنون لهم: بلى قد كنتم معنا في الظاهر، ولكنكم أهلكتم أنفسكم بالنفاق والمعاصي، وتربصتم بالنبي الموت وبالمؤمنين الدوائر، وشككتم في البعث بعد الموت، وخدعتكم أمانيكم الباطلة، وبقيتم على ذلك حتى جاءكم الموت وخدعكم بالله الشيطان.", "isBasmala": false, "translation_en": "They will call to them, \"Were we not with you?\" They will say, \"Yes, but you cheated your souls, and waited, and doubted, and became deluded by wishful thinking, until the command of God arrived; and arrogance deceived you regarding God.\"", "translation_id": "Orang-orang munafik itu memanggil mereka (orang-orang mukmin) seraya berkata: \"Bukankah kami dahulu bersama-sama dengan kamu?\" Mereka menjawab: \"Benar, tetapi kamu mencelakakan dirimu sendiri dan menunggu (kehancuran kami) dan kamu ragu-ragu serta ditipu oleh angan-angan kosong sehingga datanglah ketetapan Allah; dan kamu telah ditipu terhadap Allah oleh (syaitan) yang amat penipu.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 15, "text": "فَٱلۡیَوۡمَ لَا یُؤۡخَذُ مِنكُمۡ فِدۡیَةࣱ وَلَا مِنَ ٱلَّذِینَ كَفَرُوا۟ۚ مَأۡوَىٰكُمُ ٱلنَّارُۖ هِیَ مَوۡلَىٰكُمۡۖ وَبِئۡسَ ٱلۡمَصِیرُ ۝١٥", "juz": 27, "hizb": "(*½ ح 54*)", "tafsir": "فاليوم لا يُقبل من أحد منكم أيها المنافقون عوض؛ ليفتدي به من عذاب الله، ولا من الذين كفروا بالله ورسوله، مصيركم جميعًا النار، هي أولى بكم من كل منزل، وبئس المصير هي.", "isBasmala": false, "translation_en": "\"Therefore, today no ransom will be accepted from you, nor from those who disbelieved. The Fire is your refuge. It is your companion-what an evil fate!\"", "translation_id": "Maka pada hari ini tidak diterima tebusan dari kamu dan tidak pula dari orang-orang kafir. Tempat kamu ialah neraka. Dialah tempat berlindungmu. Dan dia adalah sejahat-jahat tempat kembali\".", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 16, "text": "۞ أَلَمۡ یَأۡنِ لِلَّذِینَ ءَامَنُوۤا۟ أَن تَخۡشَعَ قُلُوبُهُمۡ لِذِكۡرِ ٱللَّهِ وَمَا نَزَلَ مِنَ ٱلۡحَقِّ وَلَا یَكُونُوا۟ كَٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ مِن قَبۡلُ فَطَالَ عَلَیۡهِمُ ٱلۡأَمَدُ فَقَسَتۡ قُلُوبُهُمۡۖ وَكَثِیرࣱ مِّنۡهُمۡ فَـٰسِقُونَ ۝١٦", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "ألم يحن الوقت للذين صدَّقوا الله ورسوله واتَّبَعوا هديه، أن تلين قلوبهم عند ذكر الله وسماع القرآن، ولا يكونوا في قسوة القلوب كالذين أوتوا الكتاب من قبلهم- من اليهود والنصارى- الذين طال عليهم الزمان فبدَّلوا كلام الله، فقست قلوبهم، وكثير منهم خارجون عن طاعة الله؟ وفي الآية الحث على الرقة والخشوع لله سبحانه عند سماع ما أنزله من الكتاب والحكمة، والحذر من التشبه باليهود والنصارى، في قسوة قلوبهم، وخروجهم عن طاعة الله.", "isBasmala": false, "translation_en": "Is it not time for those who believe to surrender their hearts to the remembrance of God, and to the truth that has come down, and not be like those who were given the Book previously, but time became prolonged for them, so their hearts hardened, and many of them are sinners?", "translation_id": "Belumkah datang waktunya bagi orang-orang yang beriman, untuk tunduk hati mereka mengingat Allah dan kepada kebenaran yang telah turun (kepada mereka), dan janganlah mereka seperti orang-orang yang sebelumnya telah diturunkan Al Kitab kepadanya, kemudian berlalulah masa yang panjang atas mereka lalu hati mereka menjadi keras. Dan kebanyakan di antara mereka adalah orang-orang yang fasik.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 17, "text": "ٱعۡلَمُوۤا۟ أَنَّ ٱللَّهَ یُحۡیِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ قَدۡ بَیَّنَّا لَكُمُ ٱلۡـَٔایَـٰتِ لَعَلَّكُمۡ تَعۡقِلُونَ ۝١٧", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "اعلموا أن الله سبحانه وتعالى يحيي الأرض بالمطر بعد موتها، فتُخرِج النبات، فكذلك الله قادر على إحياء الموتى يوم القيامة، وهو القادر على تليين القلوب بعد قسوتها. قد بينَّا لكم دلائل قدرتنا؛ لعلكم تعقلونها فتتعظوا.", "isBasmala": false, "translation_en": "Know that God revives the earth after its death. We thus explain the revelations for you, so that you may understand.", "translation_id": "Ketahuilah olehmu bahwa sesungguhnya Allah menghidupkan bumi sesudah matinya. Sesungguhnya Kami telah menjelaskan kepadamu tanda-tanda kebesaran (Kami) supaya kamu memikirkannya.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 18, "text": "إِنَّ ٱلۡمُصَّدِّقِینَ وَٱلۡمُصَّدِّقَـٰتِ وَأَقۡرَضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰا یُضَـٰعَفُ لَهُمۡ وَلَهُمۡ أَجۡرࣱ كَرِیمࣱ ۝١٨", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "إن المتصدتقين من أموالهم والمتصدقات، وأنفقوا في سبيل الله نفقات طيبة بها نفوسهم؛ ابتغاء وجه الله تعالى، يضاعف لهم ثواب ذلك، ولهم فوق ذلك ثواب جزيل، وهو الجنة.", "isBasmala": false, "translation_en": "The charitable men and charitable women, who have loaned God a loan of righteousness-it will be multiplied for them, and for them is a generous reward.", "translation_id": "Sesungguhnya orang-orang yang membenarkan (Allah dan Rasul-Nya) baik laki-laki maupun perempuan dan meminjamkan kepada Allah pinjaman yang baik, niscaya akan dilipatgandakan (pembayarannya) kepada mereka; dan bagi mereka pahala yang banyak.", "manzil": 7, "manzil_display": ""}], "540": [{"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 19, "text": "وَٱلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۤ أُو۟لَـٰۤىِٕكَ هُمُ ٱلصِّدِّیقُونَۖ وَٱلشُّهَدَاۤءُ عِندَ رَبِّهِمۡ لَهُمۡ أَجۡرُهُمۡ وَنُورُهُمۡۖ وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ ۝١٩", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "والذين آمنوا بالله ورسله ولم يفرِّقوا بين أحد منهم، أولئك هم الصديقون الذين كمُل تصديقهم بما جاءت به الرسل، اعتقادًا وقولا وعملا، والشهداء عند ربهم لهم ثوابهم الجزيل عند الله، ونورهم العظيم يوم القيامة، والذين كفروا وكذَّبوا بأدلتنا وحججنا أولئك أصحاب الجحيم، فلا أجر لهم، ولا نور.", "isBasmala": false, "translation_en": "Those who believe in God and His messengers-these are the sincere and the witnesses with their Lord; they will have their reward and their light. But as for those who disbelieve and deny Our revelations-these are the inmates of the Blaze.", "translation_id": "Dan orang-orang yang beriman kepada Allah dan Rasul-Nya, mereka itu orang-orang Shiddiqien dan orang-orang yang menjadi saksi di sisi Tuhan mereka. Bagi mereka pahala dan cahaya mereka. Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itulah penghuni-penghuni neraka.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 20, "text": "ٱعۡلَمُوۤا۟ أَنَّمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَا لَعِبࣱ وَلَهۡوࣱ وَزِینَةࣱ وَتَفَاخُرُۢ بَیۡنَكُمۡ وَتَكَاثُرࣱ فِی ٱلۡأَمۡوَ ٰلِ وَٱلۡأَوۡلَـٰدِۖ كَمَثَلِ غَیۡثٍ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ ثُمَّ یَهِیجُ فَتَرَىٰهُ مُصۡفَرࣰّا ثُمَّ یَكُونُ حُطَـٰمࣰاۖ وَفِی ٱلۡـَٔاخِرَةِ عَذَابࣱ شَدِیدࣱ وَمَغۡفِرَةࣱ مِّنَ ٱللَّهِ وَرِضۡوَ ٰنࣱۚ وَمَا ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا مَتَـٰعُ ٱلۡغُرُورِ ۝٢٠", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "اعلموا -أيها الناس- أنما الحياة الدنيا لعب ولهو، تلعب بها الأبدان وتلهو بها القلوب، وزينة تتزينون بها، وتفاخر بينكم بمتاعها، وتكاثر بالعدد في الأموال والأولاد، مثلها كمثل مطر أعجب الزُّرَّاع نباته، ثم يهيج هذا النبات فييبس، فتراه مصفرًا بعد خضرته، ثم يكون فُتاتًا يابسًا متهشمًا، وفي الآخرة عذاب شديد للكفار ومغفرة من الله ورضوان لأهل الإيمان. وما الحياة الدنيا لمن عمل لها ناسيًا آخرته إلا متاع الغرور.", "isBasmala": false, "translation_en": "Know that the worldly life is only play, and distraction, and glitter, and boasting among you, and rivalry in wealth and children. It is like a rainfall that produces plants, and delights the disbelievers. But then it withers, and you see it yellowing, and then it becomes debris. While in the Hereafter there is severe agony, and forgiveness from God, and acceptance. The life of this world is nothing but enjoyment of vanity.", "translation_id": "Ketahuilah, bahwa sesungguhnya kehidupan dunia ini hanyalah permainan dan suatu yang melalaikan, perhiasan dan bermegah-megah antara kamu serta berbangga-banggaan tentang banyaknya harta dan anak, seperti hujan yang tanam-tanamannya mengagumkan para petani; kemudian tanaman itu menjadi kering dan kamu lihat warnanya kuning kemudian menjadi hancur. Dan di akhirat (nanti) ada azab yang keras dan ampunan dari Allah serta keridhaan-Nya. Dan kehidupan dunia ini tidak lain hanyalah kesenangan yang menipu.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 21, "text": "سَابِقُوۤا۟ إِلَىٰ مَغۡفِرَةࣲ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِ أُعِدَّتۡ لِلَّذِینَ ءَامَنُوا۟ بِٱللَّهِ وَرُسُلِهِۦۚ ذَ ٰلِكَ فَضۡلُ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ ۝٢١", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "سابقوا -أيها الناس- في السعي إلى أسباب المغفرة من التوبة النصوح والابتعاد عن المعاصي؛ لِتُجْزَوْا مغفرة من ربكم وجنة عرضها كعرض السماء والأرض، وهي مُعَدَّة للذين وحَّدوا الله واتَّبَعوا رسله، ذلك فضل الله الذي يؤتيه مَن يشاء مِن خلقه، فالجنة لا تُنال إلا برحمة الله وفضله، والعمل الصالح. والله ذو الفضل العظيم على عباده المؤمنين.", "isBasmala": false, "translation_en": "Race towards forgiveness from your Lord; and a Garden as vast as the heavens and the earth, prepared for those who believe in God and His messengers. That is the grace of God; He bestows it on whomever He wills. God is the Possessor of Immense Grace.", "translation_id": "Berlomba-lombalah kamu kepada (mendapatkan) ampunan dari Tuhanmu dan surga yang luasnya seluas langit dan bumi, yang disediakan bagi orang-orang yang beriman kepada Allah dan Rasul-rasul-Nya. Itulah karunia Allah, diberikan-Nya kepada siapa yang dikehendaki-Nya. Dan Allah mempunyai karunia yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 22, "text": "مَاۤ أَصَابَ مِن مُّصِیبَةࣲ فِی ٱلۡأَرۡضِ وَلَا فِیۤ أَنفُسِكُمۡ إِلَّا فِی كِتَـٰبࣲ مِّن قَبۡلِ أَن نَّبۡرَأَهَاۤۚ إِنَّ ذَ ٰلِكَ عَلَى ٱللَّهِ یَسِیرࣱ ۝٢٢", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "ما أصابكم- أيها الناس- من مصيبة في الأرض ولا في أنفسكم من الأمراض والجوع والأسقام إلا هو مكتوب في اللوح المحفوظ من قبل أن تُخْلَق الخليقة. إن ذلك على الله تعالى يسير.", "isBasmala": false, "translation_en": "No calamity occurs on earth, or in your souls, but it is in a Book, even before We make it happen. That is easy for God.", "translation_id": "Tiada suatu bencanapun yang menimpa di bumi dan (tidak pula) pada dirimu sendiri melainkan telah tertulis dalam kitab (Lauhul Mahfuzh) sebelum Kami menciptakannya. Sesungguhnya yang demikian itu adalah mudah bagi Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 23, "text": "لِّكَیۡلَا تَأۡسَوۡا۟ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُوا۟ بِمَاۤ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا یُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورٍ ۝٢٣", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "لكي لا تحزنوا على ما فاتكم من الدنيا، ولا تفرحوا بما آتاكم فرحَ بطر وأشر. والله لا يحب كل متكبر بما أوتي من الدنيا فخور به على غيره. هؤلاء المتكبرون هم الذين يبخلون بمالهم، ولا ينفقونه في سبيل الله، ويأمرون الناس بالبخل بتحسينه لهم. ومن يتولَّ عن طاعة الله لا يضر إلا نفسه، ولن يضر الله شيئًا، فإن الله هو الغني عن خلقه، الحميد الذي له كل وصف حسن كامل، وفعل جميل يستحق أن يحمد عليه.", "isBasmala": false, "translation_en": "That you may not sorrow over what eludes you, nor exult over what He has given you. God does not love the proud snob.", "translation_id": "(Kami jelaskan yang demikian itu) supaya kamu jangan berduka cita terhadap apa yang luput dari kamu, dan supaya kamu jangan terlalu gembira terhadap apa yang diberikan-Nya kepadamu. Dan Allah tidak menyukai setiap orang yang sombong lagi membanggakan diri,", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 24, "text": "ٱلَّذِینَ یَبۡخَلُونَ وَیَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِۗ وَمَن یَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ ۝٢٤", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "لكي لا تحزنوا على ما فاتكم من الدنيا، ولا تفرحوا بما آتاكم فرحَ بطر وأشر. والله لا يحب كل متكبر بما أوتي من الدنيا فخور به على غيره. هؤلاء المتكبرون هم الذين يبخلون بمالهم، ولا ينفقونه في سبيل الله، ويأمرون الناس بالبخل بتحسينه لهم. ومن يتولَّ عن طاعة الله لا يضر إلا نفسه، ولن يضر الله شيئًا، فإن الله هو الغني عن خلقه، الحميد الذي له كل وصف حسن كامل، وفعل جميل يستحق أن يحمد عليه.", "isBasmala": false, "translation_en": "Those who are stingy, and induce people to be stingy. Whoever turns away-God is the Independent, the Praiseworthy.", "translation_id": "(yaitu) orang-orang yang kikir dan menyuruh manusia berbuat kikir. Dan barangsiapa yang berpaling (dari perintah-perintah Allah) maka sesungguhnya Allah Dialah Yang Maha Kaya lagi Maha Terpuji.", "manzil": 7, "manzil_display": ""}], "541": [{"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 25, "text": "لَقَدۡ أَرۡسَلۡنَا رُسُلَنَا بِٱلۡبَیِّنَـٰتِ وَأَنزَلۡنَا مَعَهُمُ ٱلۡكِتَـٰبَ وَٱلۡمِیزَانَ لِیَقُومَ ٱلنَّاسُ بِٱلۡقِسۡطِۖ وَأَنزَلۡنَا ٱلۡحَدِیدَ فِیهِ بَأۡسࣱ شَدِیدࣱ وَمَنَـٰفِعُ لِلنَّاسِ وَلِیَعۡلَمَ ٱللَّهُ مَن یَنصُرُهُۥ وَرُسُلَهُۥ بِٱلۡغَیۡبِۚ إِنَّ ٱللَّهَ قَوِیٌّ عَزِیزࣱ ۝٢٥", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "لقد أرسلنا رسلنا بالحجج الواضحات، وأنزلنا معهم الكتاب بالأحكام والشرائع، وأنزلنا الميزان؛ ليتعامل الناس بينهم بالعدل، وأنزلنا لهم الحديد، فيه قوة شديدة، ومنافع للناس متعددة، وليعلم الله علمًا ظاهرًا للخلق من ينصر دينه ورسله بالغيب. إن الله قوي لا يُقْهَر، عزيز لا يغالَب.", "isBasmala": false, "translation_en": "We sent Our messengers with the clear proofs, and We sent down with them the Book and the Balance, that humanity may uphold justice. And We sent down iron, in which is violent force, and benefits for humanity. That God may know who supports Him and His messengers invisibly. God is Strong and Powerful.", "translation_id": "Sesungguhnya Kami telah mengutus rasul-rasul Kami dengan membawa bukti-bukti yang nyata dan telah Kami turunkan bersama mereka Al Kitab dan neraca (keadilan) supaya manusia dapat melaksanakan keadilan. Dan Kami ciptakan besi yang padanya terdapat kekuatan yang hebat dan berbagai manfaat bagi manusia, (supaya mereka mempergunakan besi itu) dan supaya Allah mengetahui siapa yang menolong (agama)Nya dan rasul-rasul-Nya padahal Allah tidak dilihatnya. Sesungguhnya Allah Maha Kuat lagi Maha Perkasa.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 26, "text": "وَلَقَدۡ أَرۡسَلۡنَا نُوحࣰا وَإِبۡرَ ٰهِیمَ وَجَعَلۡنَا فِی ذُرِّیَّتِهِمَا ٱلنُّبُوَّةَ وَٱلۡكِتَـٰبَۖ فَمِنۡهُم مُّهۡتَدࣲۖ وَكَثِیرࣱ مِّنۡهُمۡ فَـٰسِقُونَ ۝٢٦", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "ولقد أرسلنا نوحًا وإبراهيم إلى قومهما، وجعلنا في ذريتهما النبوة والكتب المنزلة، فمِن ذريتهما مهتدٍ إلى الحق، وكثير منهم خارجون عن طاعة الله.", "isBasmala": false, "translation_en": "We sent Noah and Abraham, and established in their line Prophethood and the Scripture. Some of them are guided, but many of them are sinners.", "translation_id": "Dan sesungguhnya Kami telah mengutus Nuh dan Ibrahim dan Kami jadikan kepada keturunan keduanya kenabian dan Al Kitab, maka di antara mereka ada yang menerima petunjuk dan banyak di antara mereka fasik.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 27, "text": "ثُمَّ قَفَّیۡنَا عَلَىٰۤ ءَاثَـٰرِهِم بِرُسُلِنَا وَقَفَّیۡنَا بِعِیسَى ٱبۡنِ مَرۡیَمَ وَءَاتَیۡنَـٰهُ ٱلۡإِنجِیلَۖ وَجَعَلۡنَا فِی قُلُوبِ ٱلَّذِینَ ٱتَّبَعُوهُ رَأۡفَةࣰ وَرَحۡمَةࣰۚ وَرَهۡبَانِیَّةً ٱبۡتَدَعُوهَا مَا كَتَبۡنَـٰهَا عَلَیۡهِمۡ إِلَّا ٱبۡتِغَاۤءَ رِضۡوَ ٰنِ ٱللَّهِ فَمَا رَعَوۡهَا حَقَّ رِعَایَتِهَاۖ فَـَٔاتَیۡنَا ٱلَّذِینَ ءَامَنُوا۟ مِنۡهُمۡ أَجۡرَهُمۡۖ وَكَثِیرࣱ مِّنۡهُمۡ فَـٰسِقُونَ ۝٢٧", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "ثم أتبعنا على آثار نوح وإبراهيم برسلنا الذين أرسلناهم بالبينات، وقفَّينا بعيسى ابن مريم، وآتيناه الإنجيل، وجعلنا في قلوب الذين اتبعوه على دينه لينًا وشفقة، فكانوا متوادِّين فيما بينهم، وابتدعوا رهبانية بالغلوِّ في العبادة ما فرضناها عليهم، بل هم الذين التزموا بها من تلقاء أنفسهم، قَصْدُهم بذلك رضا الله، فما قاموا بها حق القيام، فآتينا الذين آمنوا منهم بالله ورسله أجرهم حسب إيمانهم، وكثير منهم خارجون عن طاعة الله مكذبون بنيه محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Then We sent in their wake Our messengers, and followed up with Jesus son of Mary, and We gave him the Gospel, and instilled in the hearts of those who followed him compassion and mercy. But as for the monasticism which they invented-We did not ordain it for them-only to seek God's approval. But they did not observe it with its due observance. So We gave those of them who believed their reward, but many of them are sinful.", "translation_id": "Kemudian Kami iringi di belakang mereka dengan rasul-rasul Kami dan Kami iringi (pula) dengan Isa putra Maryam; dan Kami berikan kepadanya Injil dan Kami jadikan dalam hati orang-orang yang mengikutinya rasa santun dan kasih sayang. Dan mereka mengada-adakan rahbaniyyah padahal kami tidak mewajibkannya kepada mereka tetapi (mereka sendirilah yang mengada-adakannya) untuk mencari keridhaan Allah, lalu mereka tidak memeliharanya dengan pemeliharaan yang semestinya. Maka Kami berikan kepada orang-orang yang beriman di antara mereka pahalanya dan banyak di antara mereka orang-orang fasik.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 28, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَءَامِنُوا۟ بِرَسُولِهِۦ یُؤۡتِكُمۡ كِفۡلَیۡنِ مِن رَّحۡمَتِهِۦ وَیَجۡعَل لَّكُمۡ نُورࣰا تَمۡشُونَ بِهِۦ وَیَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٢٨", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "يا أيها الذين آمنوا، امتثلوا أوامر الله واجتنبوا نواهيه وآمنوا برسوله، يؤتكم ضعفين من رحمته، ويجعل لكم نورًا تهتدون به، ويغفر لكم ذنوبكم، والله غفور لعباده، رحيم بهم.", "isBasmala": false, "translation_en": "O you who believe! Fear God, and believe in His Messenger: He will give you a double portion of His mercy, and will give you a light by which you walk, and will forgive you. God is Forgiving and Merciful.", "translation_id": "Hai orang-orang yang beriman (kepada para rasul), bertakwalah kepada Allah dan berimanlah kepada Rasul-Nya, niscaya Allah memberikan rahmat-Nya kepadamu dua bagian, dan menjadikan untukmu cahaya yang dengan cahaya itu kamu dapat berjalan dan Dia mengampuni kamu. Dan Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 57, "sura_name": "الحديد", "revelation": "Madaniyah", "aya": 29, "text": "لِّئَلَّا یَعۡلَمَ أَهۡلُ ٱلۡكِتَـٰبِ أَلَّا یَقۡدِرُونَ عَلَىٰ شَیۡءࣲ مِّن فَضۡلِ ٱللَّهِ وَأَنَّ ٱلۡفَضۡلَ بِیَدِ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ ۝٢٩", "juz": 27, "hizb": "(*¾ ح 54*)", "tafsir": "أعطاكم الله تعالى ذلك كله؛ ليعلم أهل الكتاب الذين لم يؤمنوا بمحمد صلى الله عليه وسلم، أنهم لا يقدرون على شيء مِن فضل الله يكسبونه لأنفسهم أو يمنحونه لغيرهم، وأن الفضل كله بيد الله وحده يؤتيه مَن يشاء من عباده، والله ذو الفضل العظيم على خلقه.", "isBasmala": false, "translation_en": "That the People of the Book may know that they have no power whatsoever over God's grace, and that all grace is in God's hand; He gives it to whomever He wills. God is Possessor of Great Grace.", "translation_id": "(Kami terangkan yang demikian itu) supaya ahli Kitab mengetahui bahwa mereka tiada mendapat sedikitpun akan karunia Allah (jika mereka tidak beriman kepada Muhammad), dan bahwasanya karunia itu adalah di tangan Allah. Dia berikan karunia itu kepada siapa yang dikehendaki-Nya. Dan Allah mempunyai karunia yang besar.", "manzil": 7, "manzil_display": ""}], "542": [{"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 28, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 1, "text": "۞ قَدۡ سَمِعَ ٱللَّهُ قَوۡلَ ٱلَّتِی تُجَـٰدِلُكَ فِی زَوۡجِهَا وَتَشۡتَكِیۤ إِلَى ٱللَّهِ وَٱللَّهُ یَسۡمَعُ تَحَاوُرَكُمَاۤۚ إِنَّ ٱللَّهَ سَمِیعُۢ بَصِیرٌ ۝١", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "قد سمع الله قول خولة بنت ثعلبة التي تراجعت في شأن زوجها أوس بن الصامت، وفيما صدر عنه في حقها من الظِّهار، وهو قوله لها: \"أنت عليَّ كظهر أمي\"، أي: في حرمة النكاح، وهي تتضرع إلى الله تعالى؛ لتفريج كربتها، والله يسمع تخاطبكما ومراجعتكما. إن الله سميع لكل قول، بصير بكل شيء، لا تخفى عليه خافية.", "isBasmala": false, "translation_en": "God has heard the statement of she who argued with you concerning her husband, as she complained to God. God heard your conversation. God is Hearing and Seeing.", "translation_id": "Sesungguhnya Allah telah mendengar perkataan wanita yang mengajukan gugatan kepada kamu tentang suaminya, dan mengadukan (halnya) kepada Allah. Dan Allah mendengar soal jawab antara kamu berdua. Sesungguhnya Allah Maha Mendengar lagi Maha Melihat.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 2, "text": "ٱلَّذِینَ یُظَـٰهِرُونَ مِنكُم مِّن نِّسَاۤىِٕهِم مَّا هُنَّ أُمَّهَـٰتِهِمۡۖ إِنۡ أُمَّهَـٰتُهُمۡ إِلَّا ٱلَّـٰۤـِٔی وَلَدۡنَهُمۡۚ وَإِنَّهُمۡ لَیَقُولُونَ مُنكَرࣰا مِّنَ ٱلۡقَوۡلِ وَزُورࣰاۚ وَإِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورࣱ ۝٢", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "الذين يُظاهرون منكم من نسائهم، فيقول الرجل منهم لزوجته: \"أنت عليَّ كظهر أمي\" -أي في حرمة النكاح- قد عصوا الله وخالفوا الشرع، ونساؤهم لَسْنَ في الحقيقة أمهاتهم، إنما هن زوجاتهم، ما أمهاتهم إلا اللائي ولدنهم. وإن هؤلاء المظاهِرين ليقولون قولا كاذبًا فظيعًا لا تُعرف صحته. وإن الله لعفو غفور عمَّن صدر منه بعض المخالفات، فتداركها بالتوبة النصوح.", "isBasmala": false, "translation_en": "Those of you who estrange their wives by equating them with their mothers-they are not their mothers. Their mothers are none else but those who gave birth to them. What they say is evil, and a blatant lie. But God is Pardoning and Forgiving.", "translation_id": "Orang-orang yang menzhihar isterinya di antara kamu, (menganggap isterinya sebagai ibunya, padahal) tiadalah isteri mereka itu ibu mereka. Ibu-ibu mereka tidak lain hanyalah wanita yang melahirkan mereka. Dan sesungguhnya mereka sungguh-sungguh mengucapkan suatu perkataan mungkar dan dusta. Dan sesungguhnya Allah Maha Pemaaf lagi Maha Pengampun.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 3, "text": "وَٱلَّذِینَ یُظَـٰهِرُونَ مِن نِّسَاۤىِٕهِمۡ ثُمَّ یَعُودُونَ لِمَا قَالُوا۟ فَتَحۡرِیرُ رَقَبَةࣲ مِّن قَبۡلِ أَن یَتَمَاۤسَّاۚ ذَ ٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ ۝٣", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "والذين يحرِّمون نساءهم على أنفسهم بالمظاهَرة منهن، ثم يرجعون عن قولهم ويعزمون على وطء نسائهم، فعلى الزوج المظاهِر- والحالة هذه- كفارة التحريم، وهي عتق رقبة مؤمنة عبد أو أمة قبل أن يطأ زوجته التي ظاهر منها، ذلكم هو حكم الله فيمن ظاهر مِن زوجته توعظون به، أيها المؤمنون؛ لكي لا تقعوا في الظهار وقول الزور، وتُكَفِّروا إن وقعتم فيه، ولكي لا تعودوا إليه، والله لا يخفى عليه شيء من أعمالكم، وهو مجازيكم عليها.", "isBasmala": false, "translation_en": "Those who estrange their wives by equating them with their mothers, then go back on what they said, must set free a slave before they may touch one another. To this you are exhorted, and God is well aware of what you do.", "translation_id": "Orang-orang yang menzhihar isteri mereka, kemudian mereka hendak menarik kembali apa yang mereka ucapkan, maka (wajib atasnya) memerdekakan seorang budak sebelum kedua suami isteri itu bercampur. Demikianlah yang diajarkan kepada kamu, dan Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 4, "text": "فَمَن لَّمۡ یَجِدۡ فَصِیَامُ شَهۡرَیۡنِ مُتَتَابِعَیۡنِ مِن قَبۡلِ أَن یَتَمَاۤسَّاۖ فَمَن لَّمۡ یَسۡتَطِعۡ فَإِطۡعَامُ سِتِّینَ مِسۡكِینࣰاۚ ذَ ٰلِكَ لِتُؤۡمِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَـٰفِرِینَ عَذَابٌ أَلِیمٌ ۝٤", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "فمن لم يجد رقبة يُعتقها، فالواجب عليه صيام شهرين متتاليين من قبل أن يطأ زوجه، فمن لم يستطع صيام الشهرين لعذر شرعي، فعليه أن يطعم ستين مسكينًا ما يشبعهم، ذلك الذي بينَّاه لكم من أحكام الظهار؛ من أجل أن تصدِّقوا بالله وتتبعوا رسوله وتعملوا بما شرعه الله، وتتركوا ما كنتم عليه في جاهليتكم، وتلك الأحكام المذكورة هي أوامر الله وحدوده فلا تتجاوزوها، وللجاحدين بها عذاب موجع.", "isBasmala": false, "translation_en": "But whoever cannot find the means must fast for two consecutive months before they may touch one another. And if he is unable, then the feeding of sixty needy people. This, in order that you affirm your faith in God and His Messenger. These are the ordinances of God. The unbelievers will have a painful punishment.", "translation_id": "Barangsiapa yang tidak mendapatkan (budak), maka (wajib atasnya) berpuasa dua bulan berturut-turut sebelum keduanya bercampur. Maka siapa yang tidak kuasa (wajiblah atasnya) memberi makan enam puluh orang miskin. Demikianlah supaya kamu beriman kepada Allah dan Rasul-Nya. Dan itulah hukum-hukum Allah, dan bagi orang kafir ada siksaan yang sangat pedih.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 5, "text": "إِنَّ ٱلَّذِینَ یُحَاۤدُّونَ ٱللَّهَ وَرَسُولَهُۥ كُبِتُوا۟ كَمَا كُبِتَ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ وَقَدۡ أَنزَلۡنَاۤ ءَایَـٰتِۭ بَیِّنَـٰتࣲۚ وَلِلۡكَـٰفِرِینَ عَذَابࣱ مُّهِینࣱ ۝٥", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "إن الذين يشاقون الله ورسوله ويخالفون أمرهما خُذِلوا وأُهينوا، كما خُذِل الذين من قبلهم من الأمم الذين حادُّوا الله ورسله، وقد أنزلنا آيات واضحات الحُجَّة تدل على أن شرع الله وحدوده حق، ولجاحدي تلك الآيات عذاب مُذلٌّ في جهنم.", "isBasmala": false, "translation_en": "Those who oppose God and His Messenger will be subdued, as those before them were subdued. We have revealed clear messages. The unbelievers will have a demeaning punishment.", "translation_id": "Sesungguhnya orang-orang yang yang menentang Allah dan Rasul-Nya, pasti mendapat kehinaan sebagaimana orang-orang yang sebelum mereka telah mendapat kehinaan. Sesungguhnya Kami telah menurunkan bukti-bukti nyata. Dan bagi orang-orang kafir ada siksa yang menghinakan.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 6, "text": "یَوۡمَ یَبۡعَثُهُمُ ٱللَّهُ جَمِیعࣰا فَیُنَبِّئُهُم بِمَا عَمِلُوۤا۟ۚ أَحۡصَىٰهُ ٱللَّهُ وَنَسُوهُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ ۝٦", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "واذكر -أيها الرسول- يوم القيامة، يوم يحيي الله الموتى جميعًا، ويجمع الأولين والآخرين في صعيد واحد، فيخبرهم بما عملوا من خير وشر، أحصاه الله وكتبه في اللوح المحفوظ، وحفظه عليهم في صحائف أعمالهم، وهم قد نسوه. والله على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "On the Day when God resurrects them all, and informs them of what they did. God has kept count of it, but they have forgotten it. God is Witness over everything.", "translation_id": "Pada hari ketika mereka dibangkitkan Allah semuanya, lalu diberitakan-Nya kepada mereka apa yang telah mereka kerjakan. Allah mengumpulkan (mencatat) amal perbuatan itu, padahal mereka telah melupakannya. Dan Allah Maha Menyaksikan segala sesuatu.", "manzil": 7, "manzil_display": ""}], "543": [{"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 7, "text": "أَلَمۡ تَرَ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۖ مَا یَكُونُ مِن نَّجۡوَىٰ ثَلَـٰثَةٍ إِلَّا هُوَ رَابِعُهُمۡ وَلَا خَمۡسَةٍ إِلَّا هُوَ سَادِسُهُمۡ وَلَاۤ أَدۡنَىٰ مِن ذَ ٰلِكَ وَلَاۤ أَكۡثَرَ إِلَّا هُوَ مَعَهُمۡ أَیۡنَ مَا كَانُوا۟ۖ ثُمَّ یُنَبِّئُهُم بِمَا عَمِلُوا۟ یَوۡمَ ٱلۡقِیَـٰمَةِۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمٌ ۝٧", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "ألم تعلم أن الله تعالى يعلم كل شيء في السموات والأرض؟ ما يتناجى ثلاثة مِن خلقه بحديث سرٍّ إلا هو رابعهم بعلمه وإحاطته، ولا خمسة إلا هو سادسهم، ولا أقلُّ من هذه الأعداد المذكورة ولا أكثرُ منها إلا هو معهم بعلمه في أيِّ مكان كانوا، لا يخفى عليه شيء من أمرهم، ثم يخبرهم تعالى يوم القيامة بما عملوا من خير وشر ويجازيهم عليه. إن الله بكل شيء عليم.", "isBasmala": false, "translation_en": "Do you not realize that God knows everything in the heavens and everything on earth? There is no secret counsel between three, but He is their fourth; nor between five, but He is their sixth; nor less than that, nor more, but He is with them wherever they may be. Then, on the Day of Resurrection, He will inform them of what they did. God has knowledge of everything.", "translation_id": "Tidakkah kamu perhatikan, bahwa sesungguhnya Allah mengetahui apa yang ada di langit dan di bumi? Tiada pembicaraan rahasia antara tiga orang, melainkan Dialah keempatnya. Dan tiada (pembicaraan antara) lima orang, melainkan Dialah keenamnya. Dan tiada (pula) pembicaraan antara jumlah yang kurang dari itu atau lebih banyak, melainkan Dia berada bersama mereka di manapun mereka berada. Kemudian Dia akan memberitahukan kepada mereka pada hari kiamat apa yang telah mereka kerjakan. Sesungguhnya Allah Maha mengetahui segala sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 8, "text": "أَلَمۡ تَرَ إِلَى ٱلَّذِینَ نُهُوا۟ عَنِ ٱلنَّجۡوَىٰ ثُمَّ یَعُودُونَ لِمَا نُهُوا۟ عَنۡهُ وَیَتَنَـٰجَوۡنَ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰنِ وَمَعۡصِیَتِ ٱلرَّسُولِۖ وَإِذَا جَاۤءُوكَ حَیَّوۡكَ بِمَا لَمۡ یُحَیِّكَ بِهِ ٱللَّهُ وَیَقُولُونَ فِیۤ أَنفُسِهِمۡ لَوۡلَا یُعَذِّبُنَا ٱللَّهُ بِمَا نَقُولُۚ حَسۡبُهُمۡ جَهَنَّمُ یَصۡلَوۡنَهَاۖ فَبِئۡسَ ٱلۡمَصِیرُ ۝٨", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "ألم تر -أيها الرسول- إلى اليهود الذين نُهوا عن الحديث سرًّا بما يثير الشك في نفوس المؤمنين، ثم يرجعون إلى ما نُهوا عنه، ويتحدثون سرًّا بما هو إثم وعدوان ومخالفة لأمر الرسول؟ وإذا جاءك -أيها الرسول- هؤلاء اليهود لأمر من الأمور حيَّوك بغير التحية التي جعلها الله لك تحية، فقالوا: (السام عليك) أي: الموت لك، ويقولون فيما بينهم: هلا يعاقبنا الله بما نقول لمحمد إن كان رسولا حقًا، تكفيهم جهنم يدخلونها، ويقاسون حرها، فبئس المرجع هي.", "isBasmala": false, "translation_en": "Have you noted those who were prohibited from conspiring secretly, but then reverted to what they were prohibited from? They conspire to commit sin, and aggression, and defiance of the Messenger. And when they come to you, they greet you with a greeting that God never greeted you with. And they say within themselves, \"Why does God not punish us for what we say?\" Hell is enough for them. They will roast in it. What a miserable destiny!", "translation_id": "Apakah tidak kamu perhatikan orang-orang yang telah dilarang mengadakan pembicaraan rahasia, kemudian mereka kembali (mengerjakan) larangan itu dan mereka mengadakan pembicaraan rahasia untuk berbuat dosa, permusuhan dan durhaka kepada Rasul. Dan apabila mereka datang kepadamu, mereka mengucapkan salam kepadamu dengan memberi salam yang bukan sebagai yang ditentukan Allah untukmu. Dan mereka mengatakan kepada diri mereka sendiri: \"Mengapa Allah tidak menyiksa kita disebabkan apa yang kita katakan itu?\" Cukuplah bagi mereka Jahannam yang akan mereka masuki. Dan neraka itu adalah seburuk-buruk tempat kembali.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 9, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا تَنَـٰجَیۡتُمۡ فَلَا تَتَنَـٰجَوۡا۟ بِٱلۡإِثۡمِ وَٱلۡعُدۡوَ ٰنِ وَمَعۡصِیَتِ ٱلرَّسُولِ وَتَنَـٰجَوۡا۟ بِٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ إِلَیۡهِ تُحۡشَرُونَ ۝٩", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا تحدثتم فيما بينكم سرًا، فلا تتحدثوا بما فيه إثم من القول، أو بما هو عدوان على غيركم، أو مخالفة لأمر الرسول، وتحدثوا بما فيه خير وطاعة وإحسان، وخافوا الله بامتثالكم أوامره واجتنابكم نواهيه، فإليه وحده مرجعكم بجميع أعمالكم وأقوالكم التي أحصاها عليكم، وسيجازيكم بها.", "isBasmala": false, "translation_en": "O you who believe! When you converse secretly, do not converse in sin, and aggression, and disobedience of the Messenger; but converse in virtue and piety; And fear God, to Whom you will be gathered.", "translation_id": "Hai orang-orang beriman, apabila kamu mengadakan pembicaraan rahasia, janganlah kamu membicarakan tentang membuat dosa, permusuhan dan berbuat durhaka kepada Rasul. Dan bicarakanlah tentang membuat kebajikan dan takwa. Dan bertakwalah kepada Allah yang kepada-Nya kamu akan dikembalikan.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 10, "text": "إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّیۡطَـٰنِ لِیَحۡزُنَ ٱلَّذِینَ ءَامَنُوا۟ وَلَیۡسَ بِضَاۤرِّهِمۡ شَیۡـًٔا إِلَّا بِإِذۡنِ ٱللَّهِۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ۝١٠", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "إنما التحدث خفية بالإثم والعدوان من وسوسة الشيطان، فهو المزيِّن لها، والحامل عليها؛ ليُدْخِل الحزن على قلوب المؤمنين، وليس ذلك بمؤذي المؤمنين شيئًا إلا بمشيئة الله تعالى وإرادته. وعلى الله وحده فليعتمد المؤمنون به.", "isBasmala": false, "translation_en": "Conspiracies are from Satan, that he may dishearten those who believe; but he will not harm them in the least, except by leave of God. So let the believers put their trust in God.", "translation_id": "Sesungguhnya pembicaraan rahasia itu adalah dari syaitan, supaya orang-orang yang beriman itu berduka cita, sedang pembicaraan itu tiadalah memberi mudharat sedikitpun kepada mereka, kecuali dengan izin Allah dan kepada Allah-lah hendaknya orang-orang yang beriman bertawakkal.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 11, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا قِیلَ لَكُمۡ تَفَسَّحُوا۟ فِی ٱلۡمَجَـٰلِسِ فَٱفۡسَحُوا۟ یَفۡسَحِ ٱللَّهُ لَكُمۡۖ وَإِذَا قِیلَ ٱنشُزُوا۟ فَٱنشُزُوا۟ یَرۡفَعِ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ مِنكُمۡ وَٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ دَرَجَـٰتࣲۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ ۝١١", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا طُلب منكم أن يوسع بعضكم لبعض المجالس فأوسعوا، يوسع الله عليكم في الدنيا والآخرة، وإذا طلب منكم- أيها المؤمنون- أن تقوموا من مجالسكم لأمر من الأمور التي يكون فيها خير لكم فقوموا، يرفع الله مكانة المؤمنين المخلصين منكم، ويرفع مكانة أهل العلم درجات كثيرة في الثواب ومراتب الرضوان، والله تعالى خبير بأعمالكم لا يخفى عليه شيء منها، وهو مجازيكم عليها. وفي الآية تنويه بمكانة العلماء وفضلهم، ورفع درجاتهم.", "isBasmala": false, "translation_en": "O you who believe! When you are told to make room in your gatherings, make room; God will make room for you. And when you are told to disperse, disperse. God elevates those among you who believe, and those given knowledge, many steps. God is Aware of what you do.", "translation_id": "Hai orang-orang beriman apabila dikatakan kepadamu: \"Berlapang-lapanglah dalam majlis\", maka lapangkanlah niscaya Allah akan memberi kelapangan untukmu. Dan apabila dikatakan: \"Berdirilah kamu\", maka berdirilah, niscaya Allah akan meninggikan orang-orang yang beriman di antaramu dan orang-orang yang diberi ilmu pengetahuan beberapa derajat. Dan Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}], "544": [{"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 12, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نَـٰجَیۡتُمُ ٱلرَّسُولَ فَقَدِّمُوا۟ بَیۡنَ یَدَیۡ نَجۡوَىٰكُمۡ صَدَقَةࣰۚ ذَ ٰلِكَ خَیۡرࣱ لَّكُمۡ وَأَطۡهَرُۚ فَإِن لَّمۡ تَجِدُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ ۝١٢", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا أردتم أن تُكلِّموا رسول الله صلى الله عليه وسلم سرًّا بينكم وبينه، فقدِّموا قبل ذلك صدقة لأهل الحاجة، ذلك خير لكم لما فيه من الثواب، وأزكى لقلوبكم من المآثم، فإن لم تجدوا ما تتصدقون به فلا حرج عليكم؛ فإن الله غفور لعباده المؤمنين، رحيم بهم.", "isBasmala": false, "translation_en": "O you who believe! When you converse privately with the Messenger, offer something in charity before your conversation. That is better for you, and purer. But if you do not find the means-God is Forgiving and Merciful.", "translation_id": "Hai orang-orang beriman, apabila kamu mengadakan pembicaraan khusus dengan Rasul hendaklah kamu mengeluarkan sedekah (kepada orang miskin) sebelum pembicaraan itu. Yang demikian itu lebih baik bagimu dan lebih bersih; jika kamu tidak memperoleh (yang akan disedekahkan) maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 13, "text": "ءَأَشۡفَقۡتُمۡ أَن تُقَدِّمُوا۟ بَیۡنَ یَدَیۡ نَجۡوَىٰكُمۡ صَدَقَـٰتࣲۚ فَإِذۡ لَمۡ تَفۡعَلُوا۟ وَتَابَ ٱللَّهُ عَلَیۡكُمۡ فَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَطِیعُوا۟ ٱللَّهَ وَرَسُولَهُۥۚ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ ۝١٣", "juz": 28, "hizb": "(* ح 55*)", "tafsir": "أخشيتم الفقر إذا قدَّمتم صدقة قبل مناجاتكم رسول الله؟ فإذْ لم تفعلوا ما أُمرتم به، وتاب الله عليكم، ورخَّص لكم في ألا تفعلوه، فاثبتوا وداوموا على إقام الصلاة وإيتاء الزكاة وطاعة الله ورسوله في كل ما أُمرتم به، والله سبحانه خبير بأعمالكم، ومجازيكم عليها.", "isBasmala": false, "translation_en": "Are you reluctant to offer charity before your conversation? If you do not do so, and God pardons you, then perform the prayer, and give alms, and obey God and His Messenger. God is Aware of what you do.", "translation_id": "Apakah kamu takut akan (menjadi miskin) karena kamu memberikan sedekah sebelum mengadakan pembicaraan dengan Rasul? Maka jika kamu tiada memperbuatnya dan Allah telah memberi taubat kepadamu maka dirikanlah shalat, tunaikanlah zakat, taatlah kepada Allah dan Rasul-Nya; dan Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 14, "text": "۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ تَوَلَّوۡا۟ قَوۡمًا غَضِبَ ٱللَّهُ عَلَیۡهِم مَّا هُم مِّنكُمۡ وَلَا مِنۡهُمۡ وَیَحۡلِفُونَ عَلَى ٱلۡكَذِبِ وَهُمۡ یَعۡلَمُونَ ۝١٤", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "ألم تر إلى المنافقين الذين اتخذوا اليهود أصدقاء ووالوهم؟ والمنافقون في الحقيقة ليسوا من المسلمين ولا من اليهود، ويحلفون كذبًا أنهم مسلمون، وأنك رسول الله، وهم يعلمون أنهم كاذبون فيما حلفوا عليه.", "isBasmala": false, "translation_en": "Have you considered those who befriended a people with whom God has become angry? They are not of you, nor of them. And they swear to a lie while they know.", "translation_id": "Tidakkah kamu perhatikan orang-orang yang menjadikan suatu kaum yang dimurkai Allah sebagai teman? Orang-orang itu bukan dari golongan kamu dan bukan (pula) dari golongan mereka. Dan mereka bersumpah untuk menguatkan kebohongan, sedang mereka mengetahui.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 15, "text": "أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابࣰا شَدِیدًاۖ إِنَّهُمۡ سَاۤءَ مَا كَانُوا۟ یَعۡمَلُونَ ۝١٥", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "أعدَّ الله لهؤلاء المنافقين عذابًا بالغ الشدة والألم، إنهم ساء ما كانوا يعملون من النفاق والحلف على الكذب.", "isBasmala": false, "translation_en": "God has prepared for them a terrible punishment. Evil is what they used to do.", "translation_id": "Allah telah menyediakan bagi mereka azab yang sangat keras, sesungguhnya amat buruklah apa yang telah mereka kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 16, "text": "ٱتَّخَذُوۤا۟ أَیۡمَـٰنَهُمۡ جُنَّةࣰ فَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِ فَلَهُمۡ عَذَابࣱ مُّهِینࣱ ۝١٦", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "اتخذ المنافقون أيمانهم الكاذبة وقاية لهم من القتل بسبب كفرهم، ولمنع المسلمين عن قتالهم وأخذ أموالهم، فبسبب ذلك صدُّوا أنفسهم وغيرهم عن سبيل الله وهو الإسلام، فلهم عذاب مُذلٌّ في النار؛ لاستكبارهم عن الإيمان بالله ورسوله وصدِّهم عن سبيله.", "isBasmala": false, "translation_en": "They took their oaths as a screen, and prevented others from God's path. They will have a shameful punishment.", "translation_id": "Mereka menjadikan sumpah-sumpah mereka sebagai perisai, lalu mereka halangi (manusia) dari jalan Allah; karena itu mereka mendapat azab yang menghinakan.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 17, "text": "لَّن تُغۡنِیَ عَنۡهُمۡ أَمۡوَ ٰلُهُمۡ وَلَاۤ أَوۡلَـٰدُهُم مِّنَ ٱللَّهِ شَیۡـًٔاۚ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ ۝١٧", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "لن تدفع عن المنافقين أموالهم ولا أولادهم مِن عذاب الله شيئًا، أولئك أهل النار يدخلونها فيبقون فيها أبدا، لا يخرجون منها. وهذا الجزاء يعم كلَّ من صدَّ عن دين الله بقوله أو فعله.", "isBasmala": false, "translation_en": "Neither their possessions nor their children will avail them anything against God. These are the inhabitants of the Fire, dwelling therein forever.", "translation_id": "Harta benda dan anak-anak mereka tiada berguna sedikitpun (untuk menolong) mereka dari azab Allah. Mereka itulah penghuni neraka, dan mereka kekal di dalamnya.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 18, "text": "یَوۡمَ یَبۡعَثُهُمُ ٱللَّهُ جَمِیعࣰا فَیَحۡلِفُونَ لَهُۥ كَمَا یَحۡلِفُونَ لَكُمۡ وَیَحۡسَبُونَ أَنَّهُمۡ عَلَىٰ شَیۡءٍۚ أَلَاۤ إِنَّهُمۡ هُمُ ٱلۡكَـٰذِبُونَ ۝١٨", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "يوم القيامة يبعث الله المنافقين جميعًا من قبورهم أحياء، فيحلفون له أنهم كانوا مؤمنين، كما كانوا يحلفون لكم- أيها المؤمنون- في الدنيا، ويعتقدون أن ذلك ينفعهم عند الله كما كان ينفعهم في الدنيا عند المسلمين، ألا إنهم هم البالغون في الكذب حدًا لم يبلغه غيرهم.", "isBasmala": false, "translation_en": "On the Day when God will resurrect them altogether-they will swear to Him, as they swear to you, thinking that they are upon something. Indeed, they themselves are the liars.", "translation_id": "(Ingatlah) hari (ketika) mereka semua dibangkitkan Allah lalu mereka bersumpah kepada-Nya (bahwa mereka bukan musyrikin) sebagaimana mereka bersumpah kepadamu; dan mereka menyangka bahwa mereka akan memperoleh suatu (manfaat). Ketahuilah, bahwa sesungguhnya merekalah orang-orang pendusta.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 19, "text": "ٱسۡتَحۡوَذَ عَلَیۡهِمُ ٱلشَّیۡطَـٰنُ فَأَنسَىٰهُمۡ ذِكۡرَ ٱللَّهِۚ أُو۟لَـٰۤىِٕكَ حِزۡبُ ٱلشَّیۡطَـٰنِۚ أَلَاۤ إِنَّ حِزۡبَ ٱلشَّیۡطَـٰنِ هُمُ ٱلۡخَـٰسِرُونَ ۝١٩", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "غلب عليهم الشيطان، واستولى عليهم، حتى تركوا أوامر الله والعمل بطاعته، أولئك حزب الشيطان وأتباعه. ألا إن حزب الشيطان هم الخاسرون في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Satan has taken hold of them, and so has caused them to forget the remembrance of God. These are the partisans of Satan. Indeed, it is Satan's partisans who are the losers.", "translation_id": "Syaitan telah menguasai mereka lalu menjadikan mereka lupa mengingat Allah; mereka itulah golongan syaitan. Ketahuilah, bahwa sesungguhnya golongan syaitan itulah golongan yang merugi.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 20, "text": "إِنَّ ٱلَّذِینَ یُحَاۤدُّونَ ٱللَّهَ وَرَسُولَهُۥۤ أُو۟لَـٰۤىِٕكَ فِی ٱلۡأَذَلِّینَ ۝٢٠", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "إن الذين يخالفون أمر الله ورسوله، أولئك من جملة الأذلاء المغلوبين المهانين في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Those who oppose God and His Messenger are among the lowliest.", "translation_id": "Sesungguhnya orang-orang yang menentang Allah dan Rasul-Nya, mereka termasuk orang-orang yang sangat hina.", "manzil": 7, "manzil_display": ""}, {"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 21, "text": "كَتَبَ ٱللَّهُ لَأَغۡلِبَنَّ أَنَا۠ وَرُسُلِیۤۚ إِنَّ ٱللَّهَ قَوِیٌّ عَزِیزࣱ ۝٢١", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "كتب الله في اللوح المحفوظ وحَكَم بأن النصرة له ولكتابه ورسله وعباده المؤمنين. إن الله سبحانه قوي لا يعجزه شيء، عزيز على خلقه.", "isBasmala": false, "translation_en": "God has written: \"I will certainly prevail, I and My messengers.\" God is Strong and Mighty.", "translation_id": "Allah telah menetapkan: \"Aku dan rasul-rasul-Ku pasti menang\". Sesungguhnya Allah Maha Kuat lagi Maha Perkasa.", "manzil": 7, "manzil_display": ""}], "545": [{"sura": 58, "sura_name": "المجادلة", "revelation": "Madaniyah", "aya": 22, "text": "لَّا تَجِدُ قَوۡمࣰا یُؤۡمِنُونَ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِ یُوَاۤدُّونَ مَنۡ حَاۤدَّ ٱللَّهَ وَرَسُولَهُۥ وَلَوۡ كَانُوۤا۟ ءَابَاۤءَهُمۡ أَوۡ أَبۡنَاۤءَهُمۡ أَوۡ إِخۡوَ ٰنَهُمۡ أَوۡ عَشِیرَتَهُمۡۚ أُو۟لَـٰۤىِٕكَ كَتَبَ فِی قُلُوبِهِمُ ٱلۡإِیمَـٰنَ وَأَیَّدَهُم بِرُوحࣲ مِّنۡهُۖ وَیُدۡخِلُهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ رَضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُۚ أُو۟لَـٰۤىِٕكَ حِزۡبُ ٱللَّهِۚ أَلَاۤ إِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡمُفۡلِحُونَ ۝٢٢", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "لا تجد -أيها الرسول- قومًا يصدِّقون بالله واليوم الآخر، ويعملون بما شرع الله لهم، يحبون ويوالون مَن عادى الله ورسوله وخالف أمرهما، ولو كانوا آباءهم أو أبناءهم أو إخوانهم أو أقرباءهم، أولئك الموالون في الله والمعادون فيه ثَبَّتَ في قلوبهم الإيمان، وقوَّاهم بنصر منه وتأييد على عدوهم في الدنيا، ويدخلهم في الآخرة جنات تجري من تحت أشجارها الأنهار، ماكثين فيها زمانًا ممتدًا لا ينقطع، أحلَّ الله عليهم رضوانه فلا يسخط عليهم، ورضوا عن ربهم بما أعطاهم من الكرامات ورفيع الدرجات، أولئك حزب الله وأولياؤه، وأولئك هم الفائزون بسعادة الدنيا والآخرة.", "isBasmala": false, "translation_en": "You will not find a people who believe in God and the Last Day, loving those who oppose God and His Messenger, even if they were their parents, or their children, or their siblings, or their close relatives. These-He has inscribed faith in their hearts, and has supported them with a spirit from Him. And He will admit them into Gardens beneath which rivers flow, wherein they will dwell forever. God is pleased with them, and they are pleased with Him. These are the partisans of God. Indeed, it is God's partisans who are the successful.", "translation_id": "Kamu tak akan mendapati kaum yang beriman pada Allah dan hari akhirat, saling berkasih-sayang dengan orang-orang yang menentang Allah dan Rasul-Nya, sekalipun orang-orang itu bapak-bapak, atau anak-anak atau saudara-saudara ataupun keluarga mereka. Mereka itulah orang-orang yang telah menanamkan keimanan dalam hati mereka dan menguatkan mereka dengan pertolongan yang datang daripada-Nya. Dan dimasukan-Nya mereka ke dalam surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Allah ridha terhadap mereka, dan merekapun merasa puas terhadap (limpahan rahmat)-Nya. Mereka itulah golongan Allah. Ketahuilah, bahwa sesungguhnya hizbullah itu adalah golongan yang beruntung.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 28, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 1, "text": "سَبَّحَ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝١", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "نزَّه الله عن كل ما لا يليق به كلُّ ما في السموات وما في الأرض، وهو العزيز الذي لا يغالَب، الحكيم في قَدَره وتدبيره وصنعه وتشريعه، يضع الأمور في مواضعها.", "isBasmala": false, "translation_en": "Glorifying God is all that exists in the heavens and the earth. He is the Almighty, the Most Wise.", "translation_id": "Telah bertasbih kepada Allah apa yang ada di langit dan bumi; dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 2, "text": "هُوَ ٱلَّذِیۤ أَخۡرَجَ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ مِن دِیَـٰرِهِمۡ لِأَوَّلِ ٱلۡحَشۡرِۚ مَا ظَنَنتُمۡ أَن یَخۡرُجُوا۟ۖ وَظَنُّوۤا۟ أَنَّهُم مَّانِعَتُهُمۡ حُصُونُهُم مِّنَ ٱللَّهِ فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَیۡثُ لَمۡ یَحۡتَسِبُوا۟ۖ وَقَذَفَ فِی قُلُوبِهِمُ ٱلرُّعۡبَۚ یُخۡرِبُونَ بُیُوتَهُم بِأَیۡدِیهِمۡ وَأَیۡدِی ٱلۡمُؤۡمِنِینَ فَٱعۡتَبِرُوا۟ یَـٰۤأُو۟لِی ٱلۡأَبۡصَـٰرِ ۝٢", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "هو- سبحانه- الذي أخرج الذين جحدوا نبوة محمد صلى الله عليه وسلم، من أهل الكتاب، وهم يهود بني النضير، من مساكنهم التي جاوروا بها المسلمين حول \"المدينة\"، وذلك أول إخراج لهم من \"جزيرة العرب\" إلى \"الشام\"، ما ظننتم- أيها المسلمون - أن يخرجوا من ديارهم بهذا الذل والهوان؛ لشدة بأسهم وقوة منعتهم، وظن اليهود أن حصونهم تدفع عنهم بأس الله ولا يقدر عليها أحد، فأتاهم الله من حيث لم يخطر لهم ببال، وألقى في قلوبهم الخوف والفزع الشديد، يُخْربون بيوتهم بأيديهم وأيدي المؤمنين، فاتعظوا يا أصحاب البصائر السليمة والعقول الراجحة بما جرى لهم.", "isBasmala": false, "translation_en": "It is He who evicted those who disbelieved among the People of the Book from their homes at the first mobilization. You did not think they would leave, and they thought their fortresses would protect them from God. But God came at them from where they never expected, and threw terror into their hearts. They wrecked their homes with their own hands, and by the hands of the believers. Therefore, take a lesson, O you who have insight.", "translation_id": "Dialah yang mengeluarkan orang-orang kafir di antara ahli kitab dari kampung-kampung mereka pada saat pengusiran yang pertama. Kamu tidak menyangka, bahwa mereka akan keluar dan merekapun yakin, bahwa benteng-benteng mereka dapat mempertahankan mereka dari (siksa) Allah; maka Allah mendatangkan kepada mereka (hukuman) dari arah yang tidak mereka sangka-sangka. Dan Allah melemparkan ketakutan dalam hati mereka; mereka memusnahkan rumah-rumah mereka dengan tangan mereka sendiri dan tangan orang-orang mukmin. Maka ambillah (kejadian itu) untuk menjadi pelajaran, hai orang-orang yang mempunyai wawasan.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 3, "text": "وَلَوۡلَاۤ أَن كَتَبَ ٱللَّهُ عَلَیۡهِمُ ٱلۡجَلَاۤءَ لَعَذَّبَهُمۡ فِی ٱلدُّنۡیَاۖ وَلَهُمۡ فِی ٱلۡـَٔاخِرَةِ عَذَابُ ٱلنَّارِ ۝٣", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "ولولا أن كتب الله عليهم الخروج مِن ديارهم وقضاه، لَعذَّبهم في الدنيا بالقتل والسبي، ولهم في الآخرة عذاب النار.", "isBasmala": false, "translation_en": "Had God not decreed exile for them, He would have punished them in this life. But in the Hereafter they will have the punishment of the Fire.", "translation_id": "Dan jika tidaklah karena Allah telah menetapkan pengusiran terhadap mereka, benar-benar Allah mengazab mereka di dunia. Dan bagi mereka di akhirat azab neraka.", "manzil": 7, "manzil_display": ""}], "546": [{"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 4, "text": "ذَ ٰلِكَ بِأَنَّهُمۡ شَاۤقُّوا۟ ٱللَّهَ وَرَسُولَهُۥۖ وَمَن یُشَاۤقِّ ٱللَّهَ فَإِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ ۝٤", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "ذلك- الذي أصاب اليهود في الدنيا وما ينتظرهم في الآخرة- لأنهم خالفوا أمر الله وأمر رسوله أشدَّ المخالفة، وحاربوهما وسعَوا في معصيتهما، ومن يخالف الله ورسوله فإن الله شديد العقاب له.", "isBasmala": false, "translation_en": "That is because they opposed God and His Messenger. Whoever opposes God-God is stern in retribution.", "translation_id": "Yang demikian itu adalah karena Sesungguhnya mereka menentang Allah dan Rasul-Nya. Barangsiapa menentang Allah dan Rasul-Nya, Sesungguhnya Allah sangat keras hukuman-Nya.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 5, "text": "مَا قَطَعۡتُم مِّن لِّینَةٍ أَوۡ تَرَكۡتُمُوهَا قَاۤىِٕمَةً عَلَىٰۤ أُصُولِهَا فَبِإِذۡنِ ٱللَّهِ وَلِیُخۡزِیَ ٱلۡفَـٰسِقِینَ ۝٥", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "ما قطعتم -أيها المؤمنون- من نخلة أو تركتموها قائمة على ساقها، من غير أن تتعرضوا لها، فبإذن الله وأمره؛ وليُذلَّ بذلك الخارجين عن طاعته المخالفين أمره ونهيه، حيث سلَّطكم على قطع نخيلهم وتحريقها.", "isBasmala": false, "translation_en": "Whether you cut down a tree, or leave it standing on its trunk, it is by God's will. He will surely disgrace the sinners.", "translation_id": "Apa saja yang kamu tebang dari pohon kurma (milik orang-orang kafir) atau yang kamu biarkan (tumbuh) berdiri di atas pokoknya, maka (semua itu) adalah dengan izin Allah; dan karena Dia hendak memberikan kehinaan kepada orang-orang fasik.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 6, "text": "وَمَاۤ أَفَاۤءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡهُمۡ فَمَاۤ أَوۡجَفۡتُمۡ عَلَیۡهِ مِنۡ خَیۡلࣲ وَلَا رِكَابࣲ وَلَـٰكِنَّ ٱللَّهَ یُسَلِّطُ رُسُلَهُۥ عَلَىٰ مَن یَشَاۤءُۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٦", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "وما أفاءه الله على رسوله من أموال يهود بني النضير، فلم تركبوا لتحصيله خيلا ولا إبلا ولكن الله يسلِّط رسله على مَن يشاء مِن أعدائه، فيستسلمون لهم بلا قتال، والفيء ما أُخذ من أموال الكفار بحق من غير قتال. والله على كل شيء قدير لا يعجزه شيء.", "isBasmala": false, "translation_en": "Whatever God has bestowed upon His Messenger from them; you spurred neither horse nor camel for them, but God gives authority to His messengers over whomever He will. God is Able to do all things.", "translation_id": "Dan apa saja harta rampasan (fai-i) yang diberikan Allah kepada Rasul-Nya (dari harta benda) mereka, maka untuk mendapatkan itu kamu tidak mengerahkan seekor kudapun dan (tidak pula) seekor untapun, tetapi Allah yang memberikan kekuasaan kepada Rasul-Nya terhadap apa saja yang dikehendaki-Nya. Dan Allah Maha Kuasa atas segala sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 7, "text": "مَّاۤ أَفَاۤءَ ٱللَّهُ عَلَىٰ رَسُولِهِۦ مِنۡ أَهۡلِ ٱلۡقُرَىٰ فَلِلَّهِ وَلِلرَّسُولِ وَلِذِی ٱلۡقُرۡبَىٰ وَٱلۡیَتَـٰمَىٰ وَٱلۡمَسَـٰكِینِ وَٱبۡنِ ٱلسَّبِیلِ كَیۡ لَا یَكُونَ دُولَةَۢ بَیۡنَ ٱلۡأَغۡنِیَاۤءِ مِنكُمۡۚ وَمَاۤ ءَاتَىٰكُمُ ٱلرَّسُولُ فَخُذُوهُ وَمَا نَهَىٰكُمۡ عَنۡهُ فَٱنتَهُوا۟ۚ وَٱتَّقُوا۟ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِیدُ ٱلۡعِقَابِ ۝٧", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "ما أفاءه الله على رسوله من أموال مشركي أهل القرى من غير ركوب خيل ولا إبل فلله ولرسوله، يُصْرف في مصالح المسلمين العامة، ولذي قرابة رسول الله صلى الله عليه وسلم، واليتامى، وهم الأطفال الفقراء الذين مات آباؤهم، والمساكين، وهم أهل الحاجة والفقر، وابن السبيل، وهو الغريب المسافر الذي نَفِدت نفقته وانقطع عنه ماله؛ وذلك حتى لا يكون المال ملكًا متداولا بين الأغنياء وحدهم، ويحرم منه الفقراء والمساكين. وما أعطاكم الرسول من مال، أو شرعه لكم مِن شرع، فخذوه، وما نهاكم عن أَخْذه أو فِعْله فانتهوا عنه، واتقوا الله بامتثال أوامره وترك نواهيه. إن الله شديد العقاب لمن عصاه وخالف أمره ونهيه. والآية أصل في وجوب العمل بالسنة: قولا أو فعلا أو تقريرًا.", "isBasmala": false, "translation_en": "Whatever God restored to His Messenger from the inhabitants of the villages belongs to God, and to the Messenger, and to the relatives, and to the orphans, and to the poor, and to the wayfarer; so that it may not circulate solely between the wealthy among you. Whatever the Messenger gives you, accept it; and whatever he forbids you, abstain from it. And fear God. God is severe in punishment.", "translation_id": "Apa saja harta rampasan (fai-i) yang diberikan Allah kepada Rasul-Nya (dari harta benda) yang berasal dari penduduk kota-kota maka adalah untuk Allah, untuk Rasul, kaum kerabat, anak-anak yatim, orang-orang miskin dan orang-orang yang dalam perjalanan, supaya harta itu jangan beredar di antara orang-orang kaya saja di antara kamu. Apa yang diberikan Rasul kepadamu, maka terimalah. Dan apa yang dilarangnya bagimu, maka tinggalkanlah. Dan bertakwalah kepada Allah. Sesungguhnya Allah amat keras hukumannya.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 8, "text": "لِلۡفُقَرَاۤءِ ٱلۡمُهَـٰجِرِینَ ٱلَّذِینَ أُخۡرِجُوا۟ مِن دِیَـٰرِهِمۡ وَأَمۡوَ ٰلِهِمۡ یَبۡتَغُونَ فَضۡلࣰا مِّنَ ٱللَّهِ وَرِضۡوَ ٰنࣰا وَیَنصُرُونَ ٱللَّهَ وَرَسُولَهُۥۤۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلصَّـٰدِقُونَ ۝٨", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "وكذلك يُعطى من المال الذي أفاءه الله على رسوله الفقراء المهاجرون، الذين اضطرهم كفار \"مكة\" إلى الخروج من ديارهم وأموالهم يطلبون من الله أن يتفضل عليهم بالرزق في الدنيا والرضوان في الآخرة، وينصرون دين الله ورسوله بالجهاد في سبيل الله، أولئك هم الصادقون الذين صدَّقوا قولهم بفعلهم.", "isBasmala": false, "translation_en": "To the poor refugees who were driven out of their homes and their possessions, as they sought the favor of God and His approval, and came to the aid of God and His Messenger. These are the sincere.", "translation_id": "(Juga) bagi orang fakir yang berhijrah yang diusir dari kampung halaman dan dari harta benda mereka (karena) mencari karunia dari Allah dan keridhaan-Nya dan mereka menolong Allah dan Rasul-Nya. Mereka itulah orang-orang yang benar.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 9, "text": "وَٱلَّذِینَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِیمَـٰنَ مِن قَبۡلِهِمۡ یُحِبُّونَ مَنۡ هَاجَرَ إِلَیۡهِمۡ وَلَا یَجِدُونَ فِی صُدُورِهِمۡ حَاجَةࣰ مِّمَّاۤ أُوتُوا۟ وَیُؤۡثِرُونَ عَلَىٰۤ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةࣱۚ وَمَن یُوقَ شُحَّ نَفۡسِهِۦ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝٩", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "والذين استوطنوا \"المدينة\"، وآمنوا من قبل هجرة المهاجرين -وهم الأنصار- يحبون المهاجرين، ويواسونهم بأموالهم، ولا يجدون في أنفسهم حسدًا لهم مما أُعْطوا من مال الفيء وغيره، ويُقَدِّمون المهاجرين وذوي الحاجة على أنفسهم، ولو كان بهم حاجة وفقر، ومن سَلِم من البخل ومَنْعِ الفضل من المال فأولئك هم الفائزون الذين فازوا بمطلوبهم.", "isBasmala": false, "translation_en": "And those who, before them, had settled in the homeland, and had accepted faith. They love those who emigrated to them, and find no hesitation in their hearts in helping them. They give them priority over themselves, even if they themselves are needy. Whoever is protected from his natural greed-it is they who are the successful.", "translation_id": "Dan orang-orang yang telah menempati kota Madinah dan telah beriman (Anshor) sebelum (kedatangan) mereka (Muhajirin), mereka (Anshor) 'mencintai' orang yang berhijrah kepada mereka (Muhajirin). Dan mereka (Anshor) tiada menaruh keinginan dalam hati mereka terhadap apa-apa yang diberikan kepada mereka (Muhajirin); dan mereka mengutamakan (orang-orang Muhajirin), atas diri mereka sendiri, sekalipun mereka dalam kesusahan. Dan siapa yang dipelihara dari kekikiran dirinya, mereka itulah orang orang yang beruntung", "manzil": 7, "manzil_display": ""}], "547": [{"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 10, "text": "وَٱلَّذِینَ جَاۤءُو مِنۢ بَعۡدِهِمۡ یَقُولُونَ رَبَّنَا ٱغۡفِرۡ لَنَا وَلِإِخۡوَ ٰنِنَا ٱلَّذِینَ سَبَقُونَا بِٱلۡإِیمَـٰنِ وَلَا تَجۡعَلۡ فِی قُلُوبِنَا غِلࣰّا لِّلَّذِینَ ءَامَنُوا۟ رَبَّنَاۤ إِنَّكَ رَءُوفࣱ رَّحِیمٌ ۝١٠", "juz": 28, "hizb": "(*¼ ح 55*)", "tafsir": "والذين جاؤوا من المؤمنين من بعد الأنصار والمهاجرين الأولين يقولون: ربنا اغفر لنا ذنوبنا، واغفر لإخواننا في الدين الذين سبقونا بالإيمان، ولا تجعل في قلوبنا حسدًا وحقدًا لأحد من أهل الإيمان، ربنا إنك رؤوف بعبادك، رحيم بهم. وفي الآية دلالة على أنه ينبغي للمسلم أن يذكر سلفه بخير، ويدعو لهم، وأن يحب صحابة رسول الله، صلى الله عليه وسلم، ويذكرهم بخير، ويترضى عنهم.", "isBasmala": false, "translation_en": "And those who came after them, saying, \"Our Lord, forgive us, and our brethren who preceded us in faith, and leave no malice in our hearts towards those who believe. Our Lord, You are Clement and Merciful.\"", "translation_id": "Dan orang-orang yang datang sesudah mereka (Muhajirin dan Anshor), mereka berdoa: \"Ya Rabb kami, beri ampunlah kami dan saudara-saudara kami yang telah beriman lebih dulu dari kami, dan janganlah Engkau membiarkan kedengkian dalam hati kami terhadap orang-orang yang beriman; Ya Rabb kami, Sesungguhnya Engkau Maha Penyantun lagi Maha Penyayang\".", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 11, "text": "۞ أَلَمۡ تَرَ إِلَى ٱلَّذِینَ نَافَقُوا۟ یَقُولُونَ لِإِخۡوَ ٰنِهِمُ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ لَىِٕنۡ أُخۡرِجۡتُمۡ لَنَخۡرُجَنَّ مَعَكُمۡ وَلَا نُطِیعُ فِیكُمۡ أَحَدًا أَبَدࣰا وَإِن قُوتِلۡتُمۡ لَنَنصُرَنَّكُمۡ وَٱللَّهُ یَشۡهَدُ إِنَّهُمۡ لَكَـٰذِبُونَ ۝١١", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "ألم تنظر إلى المنافقين، يقولون لإخوانهم في الكفر من يهود بني النضير: لئن أخرجكم محمد ومَن معه مِن منازلكم لنخرجن معكم، ولا نطيع فيكم أحدًا أبدًا سألَنا خِذْلانكم أو ترك الخروج معكم، ولئن قاتلوكم لنعاوننكم عليهم؟ والله يشهد إن المنافقين لكاذبون فيما وعدوا به يهود بني النضير.", "isBasmala": false, "translation_en": "Have you not considered those who act hypocritically? They say to their brethren who disbelieved among the People of the Book, \"If you are evicted, we will leave with you, and will not obey anyone against you; and should anyone fight you, we will certainly support you.\" But God bears witness that they are liars.", "translation_id": "Apakah kamu tidak memperhatikan orang-orang munafik yang berkata kepada saudara-saudara mereka yang kafir di antara ahli kitab: \"Sesungguhnya jika kamu diusir niscaya kamipun akan keluar bersamamu; dan kami selama-lamanya tidak akan patuh kepada siapapun untuk (menyusahkan) kamu, dan jika kamu diperangi pasti kami akan membantu kamu\". Dan Allah menyaksikan bahwa Sesungguhnya mereka benar-benar pendusta.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 12, "text": "لَىِٕنۡ أُخۡرِجُوا۟ لَا یَخۡرُجُونَ مَعَهُمۡ وَلَىِٕن قُوتِلُوا۟ لَا یَنصُرُونَهُمۡ وَلَىِٕن نَّصَرُوهُمۡ لَیُوَلُّنَّ ٱلۡأَدۡبَـٰرَ ثُمَّ لَا یُنصَرُونَ ۝١٢", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "لئن أُخرج اليهود من \"المدينة\" لا يخرج المنافقون معهم، ولئن قوتلوا لا يقاتلون معهم كما وَعَدوا، ولئن قاتلوا معهم ليولُنَّ الأدبار فرارًا منهزمين، ثم لا ينصرهم الله، بل يخذلهم، ويُذِلُّهم.", "isBasmala": false, "translation_en": "If they are evicted, they will not leave with them; and if anyone fights them, they will not support them; and if they go to their aid, they will turn their backs and flee; then they will receive no support.", "translation_id": "Sesungguhnya jika mereka diusir, orang-orang munafik itu tidak akan keluar bersama mereka, dan sesungguhnya jika mereka diperangi, niscaya mereka tidak akan menolongnya; sesungguhnya jika mereka menolongnya, niscaya mereka akan berpaling lari ke belakang; kemudian mereka tidak akan mendapat pertolongan.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 13, "text": "لَأَنتُمۡ أَشَدُّ رَهۡبَةࣰ فِی صُدُورِهِم مِّنَ ٱللَّهِۚ ذَ ٰلِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَفۡقَهُونَ ۝١٣", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "لَخوفُ المنافقين وخشيتهم إياكم- أيها المؤمنون- أعظم وأشد في صدورهم من خوفهم وخشيتهم من الله؛ وذلك بسبب أنهم قوم لا يفقهون عظمة الله والإيمان به، ولا يرهبون عقابه.", "isBasmala": false, "translation_en": "Fear of you is more intense in their hearts than fear of God. That is because they are a people who do not understand.", "translation_id": "Sesungguhnya kamu dalam hati mereka lebih ditakuti daripada Allah. Yang demikian itu karena mereka adalah kaum yang tidak mengerti.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 14, "text": "لَا یُقَـٰتِلُونَكُمۡ جَمِیعًا إِلَّا فِی قُرࣰى مُّحَصَّنَةٍ أَوۡ مِن وَرَاۤءِ جُدُرِۭۚ بَأۡسُهُم بَیۡنَهُمۡ شَدِیدࣱۚ تَحۡسَبُهُمۡ جَمِیعࣰا وَقُلُوبُهُمۡ شَتَّىٰۚ ذَ ٰلِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا یَعۡقِلُونَ ۝١٤", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "لا يواجهكم اليهود بقتال مجتمعين إلا في قرى محصنة بالأسوار والخنادق، أو من خلف الحيطان، عداوتهم فيما بينهم شديدة، تظن أنهم مجتمعون على كلمة واحدة، ولكن قلوبهم متفرقة؛ وذلك بسبب أنهم قوم لا يعقلون أمر الله ولا يتدبرون آياته.", "isBasmala": false, "translation_en": "They will not fight you all together except from fortified strongholds, or from behind walls. Their hostility towards each other is severe. You would think they are united, but their hearts are diverse. That is because they are a people who do not understand.", "translation_id": "Mereka tidak akan memerangi kamu dalam keadaan bersatu padu, kecuali dalam kampung-kampung yang berbenteng atau di balik tembok. Permusuhan antara sesama mereka adalah sangat hebat. Kamu kira mereka itu bersatu, sedang hati mereka berpecah belah. Yang demikian itu karena sesungguhnya mereka adalah kaum yang tidak mengerti.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 15, "text": "كَمَثَلِ ٱلَّذِینَ مِن قَبۡلِهِمۡ قَرِیبࣰاۖ ذَاقُوا۟ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمࣱ ۝١٥", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "مثل هؤلاء اليهود فيما حلَّ بهم من عقوبة الله كمثل كفار قريش يوم \"بدر\"، ويهود بني قينقاع، حيث ذاقوا سوء عاقبة كفرهم وعداوتهم لرسول الله صلى الله عليه وسلم في الدنيا، ولهم في الآخرة عذاب أليم موجع.", "isBasmala": false, "translation_en": "Like those shortly before them. They experienced the consequences of their decisions. For them is a painful punishment.", "translation_id": "(Mereka adalah) seperti orang-orang Yahudi yang belum lama sebelum mereka telah merasai akibat buruk dari perbuatan mereka, dan bagi mereka azab yang pedih.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 16, "text": "كَمَثَلِ ٱلشَّیۡطَـٰنِ إِذۡ قَالَ لِلۡإِنسَـٰنِ ٱكۡفُرۡ فَلَمَّا كَفَرَ قَالَ إِنِّی بَرِیۤءࣱ مِّنكَ إِنِّیۤ أَخَافُ ٱللَّهَ رَبَّ ٱلۡعَـٰلَمِینَ ۝١٦", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "ومثل هؤلاء المنافقين في إغراء اليهود على القتال ووَعْدهم بالنصر على رسول الله صلى الله عليه وسلم، كمثل الشيطان حين زيَّن للإنسان الكفر ودعاه إليه، فلما كفر قال: إني بريء منك، إني أخاف الله رب الخلق أجمعين.", "isBasmala": false, "translation_en": "Like the devil, when he says to the human being, \"Disbelieve.\" But when he has disbelieved, he says, \"I am innocent of you; I fear God, the Lord of the Worlds.\"", "translation_id": "(Bujukan orang-orang munafik itu adalah) seperti (bujukan) shaitan ketika dia berkata kepada manusia: \"Kafirlah kamu\", maka tatkala manusia itu telah kafir, maka ia berkata: \"Sesungguhnya aku berlepas diri dari kamu, karena sesungguhnya aku takut kepada Allah, Rabb semesta Alam\".", "manzil": 7, "manzil_display": ""}], "548": [{"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 17, "text": "فَكَانَ عَـٰقِبَتَهُمَاۤ أَنَّهُمَا فِی ٱلنَّارِ خَـٰلِدَیۡنِ فِیهَاۚ وَذَ ٰلِكَ جَزَ ٰۤؤُا۟ ٱلظَّـٰلِمِینَ ۝١٧", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "فكان عاقبة أمر الشيطان والإنسان الذي أطاعه فكفر، أنهما في النار، ماكثَيْن فيها أبدًا، وذلك جزاء المعتدين المتجاوزين حدود الله.", "isBasmala": false, "translation_en": "The ultimate end for both of them is the Fire, where they will dwell forever. Such is the requital for the wrongdoers.", "translation_id": "Maka adalah kesudahan keduanya, bahwa sesungguhnya keduanya (masuk) ke dalam neraka, mereka kekal di dalamnya. Demikianlah balasan orang-orang yang zalim.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 18, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَلۡتَنظُرۡ نَفۡسࣱ مَّا قَدَّمَتۡ لِغَدࣲۖ وَٱتَّقُوا۟ ٱللَّهَۚ إِنَّ ٱللَّهَ خَبِیرُۢ بِمَا تَعۡمَلُونَ ۝١٨", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، خافوا الله، واحذروا عقابه بفعل ما أمركم به وترك ما نهاكم عنه، ولتتدبر كل نفس ما قدمت من الأعمال ليوم القيامة، وخافوا الله في كل ما تأتون وما تَذَرون، إن الله سبحانه خبير بما تعملون، لا يخفى عليه شيء من أعمالكم، وهو مجازيكم عليها.", "isBasmala": false, "translation_en": "O you who believe! Fear God, and let every soul consider what it has forwarded for the morrow, and fear God. God is Aware of what you do.", "translation_id": "Hai orang-orang yang beriman, bertakwalah kepada Allah dan hendaklah setiap diri memperhatikan apa yang telah diperbuatnya untuk hari esok (akhirat); dan bertakwalah kepada Allah, sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 19, "text": "وَلَا تَكُونُوا۟ كَٱلَّذِینَ نَسُوا۟ ٱللَّهَ فَأَنسَىٰهُمۡ أَنفُسَهُمۡۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡفَـٰسِقُونَ ۝١٩", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "ولا تكونوا- أيها المؤمنون- كالذين تركوا أداء حق الله الذي أوجبه عليهم، فأنساهم بسبب ذلك حظوظ أنفسهم من الخيرات التي تنجيهم من عذاب يوم القيامة، أولئك هم الموصوفون بالفسق، الخارجون عن طاعة الله طاعة ورسوله.", "isBasmala": false, "translation_en": "And do not be like those who forgot God, so He made them forget themselves. These are the sinners.", "translation_id": "Dan janganlah kamu seperti orang-orang yang lupa kepada Allah, lalu Allah menjadikan mereka lupa kepada mereka sendiri. Mereka itulah orang-orang yang fasik.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 20, "text": "لَا یَسۡتَوِیۤ أَصۡحَـٰبُ ٱلنَّارِ وَأَصۡحَـٰبُ ٱلۡجَنَّةِۚ أَصۡحَـٰبُ ٱلۡجَنَّةِ هُمُ ٱلۡفَاۤىِٕزُونَ ۝٢٠", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "لا يستوي أصحاب النار المعذَّبون، وأصحاب الجنة المنعَّمون، أصحاب الجنة هم الظافرون بكل مطلوب، الناجون من كل مكروه.", "isBasmala": false, "translation_en": "Not equal are the inhabitants of the Fire and the inhabitants of Paradise. It is the inhabitants of Paradise who are the winners.", "translation_id": "Tidaklah sama penghuni-penghuni neraka dengan penghuni-penghuni jannah; penghuni-penghuni jannah itulah orang-orang yang beruntung.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 21, "text": "لَوۡ أَنزَلۡنَا هَـٰذَا ٱلۡقُرۡءَانَ عَلَىٰ جَبَلࣲ لَّرَأَیۡتَهُۥ خَـٰشِعࣰا مُّتَصَدِّعࣰا مِّنۡ خَشۡیَةِ ٱللَّهِۚ وَتِلۡكَ ٱلۡأَمۡثَـٰلُ نَضۡرِبُهَا لِلنَّاسِ لَعَلَّهُمۡ یَتَفَكَّرُونَ ۝٢١", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "لو أنزلنا هذا القرآن على جبل من الجبال، ففهم ما فيه مِن وعد ووعيد، لأبصَرْته على قوته وشدة صلابته وضخامته، خاضعًا ذليلا متشققًا من خشية الله تعالى. وتلك الأمثال نضربها، ونوضحها للناس؛ لعلهم يتفكرون في قدرة الله وعظمته. وفي الآية حث على تدبر القرآن، وتفهم معانيه، والعمل به.", "isBasmala": false, "translation_en": "Had We sent this Quran down on a mountain, you would have seen it trembling, crumbling in awe of God. These parables We cite for the people, so that they may reflect.", "translation_id": "Kalau sekiranya Kami turunkan Al-Quran ini kepada sebuah gunung, pasti kamu akan melihatnya tunduk terpecah belah disebabkan ketakutannya kepada Allah. Dan perumpamaan-perumpamaan itu Kami buat untuk manusia supaya mereka berfikir.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 22, "text": "هُوَ ٱللَّهُ ٱلَّذِی لَاۤ إِلَـٰهَ إِلَّا هُوَۖ عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِۖ هُوَ ٱلرَّحۡمَـٰنُ ٱلرَّحِیمُ ۝٢٢", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "هو الله سبحانه وتعالى المعبود بحق الذي لا إله سواه، عالم السر والعلن، يعلم ما غاب وما حضر، هو الرحمن الذي وسعت رحمته كل شيء، الرحيم بأهل الإيمان به.", "isBasmala": false, "translation_en": "He is God. There is no god but He, the Knower of secrets and declarations. He is the Compassionate, the Merciful.", "translation_id": "Dialah Allah Yang tiada Tuhan selain Dia, Yang Mengetahui yang ghaib dan yang nyata, Dialah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 23, "text": "هُوَ ٱللَّهُ ٱلَّذِی لَاۤ إِلَـٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَـٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَیۡمِنُ ٱلۡعَزِیزُ ٱلۡجَبَّارُ ٱلۡمُتَكَبِّرُۚ سُبۡحَـٰنَ ٱللَّهِ عَمَّا یُشۡرِكُونَ ۝٢٣", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "هو الله المعبود بحق، الذي لا إله إلا هو، الملك لجميع الأشياء، المتصرف فيها بلا ممانعة ولا مدافعة، المنزَّه عن كل نقص، الذي سلِم من كل عيب، المصدِّق رسله وأنبياءه بما ترسلهم به من الآيات البينات، الرقيب على كل خلقه في أعمالهم، العزيز الذي لا يغالَب، الجبار الذي قهر جميع العباد، وأذعن له سائر الخلق، المتكبِّر الذي له الكبرياء والعظمة. تنزَّه الله تعالى عن كل ما يشركونه به في عبادته.", "isBasmala": false, "translation_en": "He is God; besides Whom there is no god; the Sovereign, the Holy, the Peace-Giver, the Faith-Giver, the Overseer, the Almighty, the Omnipotent, the Overwhelming. Glory be to God, beyond what they associate.", "translation_id": "Dialah Allah Yang tiada Tuhan selain Dia, Raja, Yang Maha Suci, Yang Maha Sejahtera, Yang Mengaruniakan Keamanan, Yang Maha Memelihara, Yang Maha Perkasa, Yang Maha Kuasa, Yang Memiliki segala Keagungan, Maha Suci Allah dari apa yang mereka persekutukan.", "manzil": 7, "manzil_display": ""}, {"sura": 59, "sura_name": "الحشر", "revelation": "Madaniyah", "aya": 24, "text": "هُوَ ٱللَّهُ ٱلۡخَـٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَاۤءُ ٱلۡحُسۡنَىٰۚ یُسَبِّحُ لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٢٤", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "هو الله سبحانه وتعالى الخالق المقدر للخلق، البارئ المنشئ الموجد لهم على مقتضى حكمته، المصوِّر خلقه كيف يشاء، له سبحانه الأسماء الحسنى والصفات العلى، يسبِّح له جميع ما في السموات والأرض، وهو العزيز شديد الانتقام مِن أعدائه، الحكيم في تدبيره أمور خلقه.", "isBasmala": false, "translation_en": "He is God; the Creator, the Maker, the Designer. His are the Most Beautiful Names. Whatever is in the heavens and the earth glorifies Him. He is the Majestic, the Wise.", "translation_id": "Dialah Allah Yang Menciptakan, Yang Mengadakan, Yang Membentuk Rupa, Yang Mempunyai Asmaaul Husna. Bertasbih kepada-Nya apa yang di langit dan bumi. Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}], "549": [{"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 28, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 1, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَّخِذُوا۟ عَدُوِّی وَعَدُوَّكُمۡ أَوۡلِیَاۤءَ تُلۡقُونَ إِلَیۡهِم بِٱلۡمَوَدَّةِ وَقَدۡ كَفَرُوا۟ بِمَا جَاۤءَكُم مِّنَ ٱلۡحَقِّ یُخۡرِجُونَ ٱلرَّسُولَ وَإِیَّاكُمۡ أَن تُؤۡمِنُوا۟ بِٱللَّهِ رَبِّكُمۡ إِن كُنتُمۡ خَرَجۡتُمۡ جِهَـٰدࣰا فِی سَبِیلِی وَٱبۡتِغَاۤءَ مَرۡضَاتِیۚ تُسِرُّونَ إِلَیۡهِم بِٱلۡمَوَدَّةِ وَأَنَا۠ أَعۡلَمُ بِمَاۤ أَخۡفَیۡتُمۡ وَمَاۤ أَعۡلَنتُمۡۚ وَمَن یَفۡعَلۡهُ مِنكُمۡ فَقَدۡ ضَلَّ سَوَاۤءَ ٱلسَّبِیلِ ۝١", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تتخذوا عدوي وعدوكم خلصاء وأحباء، تُفْضون إليهم بالمودة، فتخبرونهم بأخبار الرسول صلى الله عليه وسلم، وسائر المسلمين، وهم قد كفروا بما جاءكم من الحق من الإيمان بالله ورسوله وما نزل عليه من القرآن، يخرجون الرسول ويخرجونكم- أيها المؤمنون- من \"مكة\"؛ لأنكم تصدقون بالله ربكم، وتوحدونه، إن كنتم- أيها المؤمنون- هاجرتم مجاهدين في سبيلي، طالبين مرضاتي عنكم، فلا توالوا أعدائي وأعداءكم، تُفْضون إليهم بالمودة سرًّا، وأنا أعلم بما أخفيتم وما أظهرتم، ومن يفعل ذلك منكم فقد أخطأ طريق الحق والصواب، وضلَّ عن قصد السبيل.", "isBasmala": false, "translation_en": "O you who believe! Do not take My enemies and your enemies for supporters, offering them affection, when they have disbelieved in what has come to you of the Truth. They have expelled the Messenger, and you, because you believed in God, your Lord. If you have mobilized to strive for My cause, seeking My approval, how can you secretly love them? I know what you conceal and what you reveal. Whoever among you does that has strayed from the right way.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu mengambil musuh-Ku dan musuhmu menjadi teman-teman setia yang kamu sampaikan kepada mereka (berita-berita Muhammad), karena rasa kasih sayang; padahal sesungguhnya mereka telah ingkar kepada kebenaran yang datang kepadamu, mereka mengusir Rasul dan (mengusir) kamu karena kamu beriman kepada Allah, Tuhanmu. Jika kamu benar-benar keluar untuk berjihad di jalan-Ku dan mencari keridhaan-Ku (janganlah kamu berbuat demikian). Kamu memberitahukan secara rahasia (berita-berita Muhammad) kepada mereka, karena rasa kasih sayang. Aku lebih mengetahui apa yang kamu sembunyikan dan apa yang kamu nyatakan. Dan barangsiapa di antara kamu yang melakukannya, maka sesungguhnya dia telah tersesat dari jalan yang lurus.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 2, "text": "إِن یَثۡقَفُوكُمۡ یَكُونُوا۟ لَكُمۡ أَعۡدَاۤءࣰ وَیَبۡسُطُوۤا۟ إِلَیۡكُمۡ أَیۡدِیَهُمۡ وَأَلۡسِنَتَهُم بِٱلسُّوۤءِ وَوَدُّوا۟ لَوۡ تَكۡفُرُونَ ۝٢", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "إن يظفر بكم هؤلاء الذين تُسرُّون إليهم بالمودة يكونوا حربًا عليكم، ويمدوا إليكم أيديهم بالقتل والسبي، وألسنتهم بالسب والشتم، وهم قد تمنَّوْا- على كل حال- لو تكفرون مثلهم.", "isBasmala": false, "translation_en": "Whenever they encounter you, they treat you as enemies, and they stretch their hands and tongues against you with malice. They wish that you would disbelieve.", "translation_id": "Jika mereka menangkap kamu, niscaya mereka bertindak sebagai musuh bagimu dan melepaskan tangan dan lidah mereka kepadamu dengan menyakiti(mu); dan mereka ingin supaya kamu (kembali) kafir.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 3, "text": "لَن تَنفَعَكُمۡ أَرۡحَامُكُمۡ وَلَاۤ أَوۡلَـٰدُكُمۡۚ یَوۡمَ ٱلۡقِیَـٰمَةِ یَفۡصِلُ بَیۡنَكُمۡۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرࣱ ۝٣", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "لن تنفعكم قراباتكم ولا أولادكم شيئًا حين توالون الكفار مِن أجلهم، يوم القيامة يفرق الله بينكم، فيُدْخل أهل طاعته الجنة، وأهل معصيته النار. والله بما تعملون بصير، لا يخفى عليه شيء من أقوالكم وأعمالكم.", "isBasmala": false, "translation_en": "Neither your relatives nor your children will benefit you on the Day of Resurrection. He will separate between you. God is Observant of what you do.", "translation_id": "Karib kerabat dan anak-anakmu sekali-sekali tiada bermanfaat bagimu pada Hari Kiamat. Dia akan memisahkan antara kamu. Dan Allah Maha Melihat apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 4, "text": "قَدۡ كَانَتۡ لَكُمۡ أُسۡوَةٌ حَسَنَةࣱ فِیۤ إِبۡرَ ٰهِیمَ وَٱلَّذِینَ مَعَهُۥۤ إِذۡ قَالُوا۟ لِقَوۡمِهِمۡ إِنَّا بُرَءَ ٰۤؤُا۟ مِنكُمۡ وَمِمَّا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ كَفَرۡنَا بِكُمۡ وَبَدَا بَیۡنَنَا وَبَیۡنَكُمُ ٱلۡعَدَ ٰوَةُ وَٱلۡبَغۡضَاۤءُ أَبَدًا حَتَّىٰ تُؤۡمِنُوا۟ بِٱللَّهِ وَحۡدَهُۥۤ إِلَّا قَوۡلَ إِبۡرَ ٰهِیمَ لِأَبِیهِ لَأَسۡتَغۡفِرَنَّ لَكَ وَمَاۤ أَمۡلِكُ لَكَ مِنَ ٱللَّهِ مِن شَیۡءࣲۖ رَّبَّنَا عَلَیۡكَ تَوَكَّلۡنَا وَإِلَیۡكَ أَنَبۡنَا وَإِلَیۡكَ ٱلۡمَصِیرُ ۝٤", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "قد كانت لكم-أيها المؤمنون- قدوة حسنة في إبراهيم عليه السلام والذين معه من المؤمنين، حين قالوا لقومهم الكافرين بالله: إنا بريئون منكم وممَّا تعبدون من دون الله من الآلهة والأنداد، كفرنا بكم، وأنكرنا ما أنتم عليه من الكفر، وظهر بيننا وبينكم العداوة والبغضاء أبدًا ما دمتم على كفركم، حتى تؤمنوا بالله وحده، لكن لا يدخل في الاقتداء استغفار إبراهيم لأبيه؛ فإن ذلك إنما كان قبل أن يتبين لإبراهيم أن أباه عدو لله، فلما تبين له أنه عدو لله تبرأ منه، ربنا عليك اعتمدنا، وإليك رجعنا بالتوبة، وإليك المرجع يوم القيامة.", "isBasmala": false, "translation_en": "You have had an excellent example in Abraham and those with him; when they said to their people, \"We are quit of you, and what you worship apart from God. We denounce you. Enmity and hatred has surfaced between us and you, forever, until you believe in God alone.\" Except for the words of Abraham to his father, \"I will ask forgiveness for you, though I have no power from God to do anything for you.\" \"Our Lord, in You we trust, and to You we repent, and to You is the ultimate resort.", "translation_id": "Sesungguhnya telah ada suri tauladan yang baik bagimu pada Ibrahim dan orang-orang yang bersama dengan dia; ketika mereka berkata kepada kaum mereka: \"Sesungguhnya kami berlepas diri daripada kamu dari daripada apa yang kamu sembah selain Allah, kami ingkari (kekafiran)mu dan telah nyata antara kami dan kamu permusuhan dan kebencian buat selama-lamanya sampai kamu beriman kepada Allah saja. Kecuali perkataan Ibrahim kepada bapaknya: \"Sesungguhnya aku akan memohonkan ampunan bagi kamu dan aku tiada dapat menolak sesuatupun dari kamu (siksaan) Allah\". (Ibrahim berkata): \"Ya Tuhan kami hanya kepada Engkaulah kami bertawakkal dan hanya kepada Engkaulah kami bertaubat dan hanya kepada Engkaulah kami kembali\".", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 5, "text": "رَبَّنَا لَا تَجۡعَلۡنَا فِتۡنَةࣰ لِّلَّذِینَ كَفَرُوا۟ وَٱغۡفِرۡ لَنَا رَبَّنَاۤۖ إِنَّكَ أَنتَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٥", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "ربنا لا تجعلنا فتنة للذين كفروا بعذابك لنا أو تسلط الكافرين علينا فيفتنونا عن ديننا، أو يظهروا علينا فيُفتنوا بذلك، ويقولوا: لو كان هؤلاء على حق، ما أصابهم هذا العذاب، فيزدادوا كفرًا، واستر علينا ذنوبنا بعفوك عنها ربنا، إنك أنت العزيز الذي لا يغالَب، الحكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "Our Lord, do not make us a target for those who disbelieve, and forgive us, our Lord. You are indeed the Mighty and Wise.\"", "translation_id": "\"Ya Tuhan kami, janganlah Engkau jadikan kami (sasaran) fitnah bagi orang-orang kafir. Dan ampunilah kami ya Tuhan kami. Sesungguhnya Engkaulah Yang Maha Perkasa lagi Maha Bijaksana\".", "manzil": 7, "manzil_display": ""}], "550": [{"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 6, "text": "لَقَدۡ كَانَ لَكُمۡ فِیهِمۡ أُسۡوَةٌ حَسَنَةࣱ لِّمَن كَانَ یَرۡجُوا۟ ٱللَّهَ وَٱلۡیَوۡمَ ٱلۡـَٔاخِرَۚ وَمَن یَتَوَلَّ فَإِنَّ ٱللَّهَ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ ۝٦", "juz": 28, "hizb": "(*½ ح 55*)", "tafsir": "لقد كان لكم- أيها المؤمنون- في إبراهيم عليه السلام والذين معه قدوة حميدة لمن يطمع في الخير من الله في الدنيا والآخرة، ومن يُعْرِض عما ندبه الله إليه من التأسي بأنبيائه، ويوال أعداء الله، فإن الله هو الغنيُّ عن عباده، الحميد في ذاته وصفاته، المحمود على كل حال.", "isBasmala": false, "translation_en": "There is an excellent example in them for you-for anyone who seeks God and the Last Day. But whoever turns away-God is the Self-Sufficient, the Most Praised.", "translation_id": "Sesungguhnya pada mereka itu (Ibrahim dan umatnya) ada teladan yang baik bagimu; (yaitu) bagi orang-orang yang mengharap (pahala) Allah dan (keselamatan pada) Hari Kemudian. Dan barangsiapa yang berpaling, maka sesungguhnya Allah Dialah yang Maha kaya lagi Maha Terpuji.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 7, "text": "۞ عَسَى ٱللَّهُ أَن یَجۡعَلَ بَیۡنَكُمۡ وَبَیۡنَ ٱلَّذِینَ عَادَیۡتُم مِّنۡهُم مَّوَدَّةࣰۚ وَٱللَّهُ قَدِیرࣱۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝٧", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "عسى الله أن يجعل بينكم- أيها المؤمنون- وبين الذين عاديتموهم من أقاربكم من المشركين محبة بعد البغضاء، وألفة بعد الشحناء بانشراح صدورهم للإسلام، والله قدير على كل شيء، والله غفور لعباده، رحيم بهم.", "isBasmala": false, "translation_en": "Perhaps God will plant affection between you and those of them you consider enemies. God is Capable. God is Forgiving and Merciful.", "translation_id": "Mudah-mudahan Allah menimbulkan kasih sayang antaramu dengan orang-orang yang kamu musuhi di antara mereka. Dan Allah adalah Maha Kuasa. Dan Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 8, "text": "لَّا یَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِینَ لَمۡ یُقَـٰتِلُوكُمۡ فِی ٱلدِّینِ وَلَمۡ یُخۡرِجُوكُم مِّن دِیَـٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوۤا۟ إِلَیۡهِمۡۚ إِنَّ ٱللَّهَ یُحِبُّ ٱلۡمُقۡسِطِینَ ۝٨", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "لا ينهاكم الله -أيها المؤمنون- عن الذين550 لم يقاتلوكم من الكفار بسبب الدين، ولم يخرجوكم من دياركم أن تكرموهم بالخير، وتعدلوا فيهم بإحسانكم إليهم وبرِّكم بهم. إن الله يحب الذين يعدلون في أقوالهم وأفعالهم.", "isBasmala": false, "translation_en": "As for those who have not fought against you for your religion, nor expelled you from your homes, God does not prohibit you from dealing with them kindly and equitably. God loves the equitable.", "translation_id": "Allah tidak melarang kamu untuk berbuat baik dan berlaku adil terhadap orang-orang yang tiada memerangimu karena agama dan tidak (pula) mengusir kamu dari negerimu. Sesungguhnya Allah menyukai orang-orang yang berlaku adil.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 9, "text": "إِنَّمَا یَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِینَ قَـٰتَلُوكُمۡ فِی ٱلدِّینِ وَأَخۡرَجُوكُم مِّن دِیَـٰرِكُمۡ وَظَـٰهَرُوا۟ عَلَىٰۤ إِخۡرَاجِكُمۡ أَن تَوَلَّوۡهُمۡۚ وَمَن یَتَوَلَّهُمۡ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلظَّـٰلِمُونَ ۝٩", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "إنما ينهاكم الله عن الذين قاتلوكم بسبب الدين وأخرجوكم من دياركم، وعاونوا الكفار على إخراجكم أن تولوهم بالنصرة والمودة، ومن يتخذهم أنصارًا على المؤمنين وأحبابًا، فأولئك هم الظالمون لأنفسهم، الخارجون عن حدود الله.", "isBasmala": false, "translation_en": "But God prohibits you from befriending those who fought against you over your religion, and expelled you from your homes, and aided in your expulsion. Whoever takes them for friends-these are the wrongdoers.", "translation_id": "Sesungguhnya Allah hanya melarang kamu menjadikan sebagai kawanmu orang-orang yang memerangimu karena agama dan mengusir kamu dari negerimu, dan membantu (orang lain) untuk mengusirmu. Dan barangsiapa menjadikan mereka sebagai kawan, maka mereka itulah orang-orang yang zalim.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 10, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا جَاۤءَكُمُ ٱلۡمُؤۡمِنَـٰتُ مُهَـٰجِرَ ٰتࣲ فَٱمۡتَحِنُوهُنَّۖ ٱللَّهُ أَعۡلَمُ بِإِیمَـٰنِهِنَّۖ فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَـٰتࣲ فَلَا تَرۡجِعُوهُنَّ إِلَى ٱلۡكُفَّارِۖ لَا هُنَّ حِلࣱّ لَّهُمۡ وَلَا هُمۡ یَحِلُّونَ لَهُنَّۖ وَءَاتُوهُم مَّاۤ أَنفَقُوا۟ۚ وَلَا جُنَاحَ عَلَیۡكُمۡ أَن تَنكِحُوهُنَّ إِذَاۤ ءَاتَیۡتُمُوهُنَّ أُجُورَهُنَّۚ وَلَا تُمۡسِكُوا۟ بِعِصَمِ ٱلۡكَوَافِرِ وَسۡـَٔلُوا۟ مَاۤ أَنفَقۡتُمۡ وَلۡیَسۡـَٔلُوا۟ مَاۤ أَنفَقُوا۟ۚ ذَ ٰلِكُمۡ حُكۡمُ ٱللَّهِ یَحۡكُمُ بَیۡنَكُمۡۖ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ ۝١٠", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا جاءكم النساء المؤمنات مهاجرات من دار الكفر إلى دار الإسلام، فاختبروهن؛ لتعلموا صدق إيمانهن، الله أعلم بحقيقة إيمانهن، فإن علمتموهن مؤمنات بحسب ما يظهر لكم من العلامات والبينات، فلا تردُّوهن إلى أزواجهن الكافرين، فالنساء المؤمنات لا يحلُّ لهن أن يتزوجن الكفار، ولا يحلُّ للكفار أن يتزوجوا المؤمنات، وأعطوا أزواج اللاتي أسلمن مثل ما أنفقوا عليهن من المهور، ولا إثم عليكم أن تتزوجوهن إذا دفعتم لهنَّ مهورهن. ولا تمسكوا بنكاح أزواجكم الكافرات، واطلبوا من المشركين ما أنفقتم من مهور نسائكم اللاتي ارتددن عن الإسلام ولحقن بهم، وليطلبوا هم ما أنفقوا من مهور نسائهم المسلمات اللاتي أسلمن ولحقن بكم، ذلكم الحكم المذكور في الآية هو حكم الله يحكم به بينكم فلا تخالفوه. والله عليم لا يخفى عليه شيء، حكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "O you who believe! When believing women come to you emigrating, test them. God is Aware of their faith. And if you find them to be faithful, do not send them back to the unbelievers. They are not lawful for them, nor are they lawful for them. But give them what they have spent. You are not at fault if you marry them, provided you give them their compensation. And do not hold on to ties with unbelieving women, but demand what you have spent, and let them demand what they have spent. This is the rule of God; He rules among you. God is Knowing and Wise.", "translation_id": "Hai orang-orang yang beriman, apabila datang berhijrah kepadamu perempuan-perempuan yang beriman, maka hendaklah kamu uji (keimanan) mereka. Allah lebih mengetahui tentang keimanan mereka; maka jika kamu telah mengetahui bahwa mereka (benar-benar) beriman maka janganlah kamu kembalikan mereka kepada (suami-suami mereka) orang-orang kafir. Mereka tiada halal bagi orang-orang kafir itu dan orang-orang kafir itu tiada halal pula bagi mereka. Dan berikanlah kepada (suami suami) mereka, mahar yang telah mereka bayar. Dan tiada dosa atasmu mengawini mereka apabila kamu bayar kepada mereka maharnya. Dan janganlah kamu tetap berpegang pada tali (perkawinan) dengan perempuan-perempuan kafir; dan hendaklah kamu minta mahar yang telah kamu bayar; dan hendaklah mereka meminta mahar yang telah mereka bayar. Demikianlah hukum Allah yang ditetapkan-Nya di antara kamu. Dan Allah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 11, "text": "وَإِن فَاتَكُمۡ شَیۡءࣱ مِّنۡ أَزۡوَ ٰجِكُمۡ إِلَى ٱلۡكُفَّارِ فَعَاقَبۡتُمۡ فَـَٔاتُوا۟ ٱلَّذِینَ ذَهَبَتۡ أَزۡوَ ٰجُهُم مِّثۡلَ مَاۤ أَنفَقُوا۟ۚ وَٱتَّقُوا۟ ٱللَّهَ ٱلَّذِیۤ أَنتُم بِهِۦ مُؤۡمِنُونَ ۝١١", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "وإن لحقت بعض زوجاتكم مرتدات إلى الكفار، ولم يعطكم الكفار مهورهن التي دفعتموها لهن، ثم ظَفِرتم بهؤلاء الكفار أو غيرهم وانتصرتم عليهم، فأعطوا الذين ذهبت أزواجهم من المسلمين من الغنائم أو غيرها مثل ما أعطوهن من المهور قبل ذلك، وخافوا الله الذي أنتم به مؤمنون.", "isBasmala": false, "translation_en": "If any of your wives desert you to the unbelievers, and you decide to penalize them, give those whose wives have gone away the equivalent of what they had spent. And fear God, in whom you are believers.", "translation_id": "Dan jika seseorang dari isteri-isterimu lari kepada orang-orang kafir, lalu kamu mengalahkan mereka maka bayarkanlah kepada orang-orang yang lari isterinya itu mahar sebanyak yang telah mereka bayar. Dan bertakwalah kepada Allah Yang kepada-Nya kamu beriman.", "manzil": 7, "manzil_display": ""}], "551": [{"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 12, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِذَا جَاۤءَكَ ٱلۡمُؤۡمِنَـٰتُ یُبَایِعۡنَكَ عَلَىٰۤ أَن لَّا یُشۡرِكۡنَ بِٱللَّهِ شَیۡـࣰٔا وَلَا یَسۡرِقۡنَ وَلَا یَزۡنِینَ وَلَا یَقۡتُلۡنَ أَوۡلَـٰدَهُنَّ وَلَا یَأۡتِینَ بِبُهۡتَـٰنࣲ یَفۡتَرِینَهُۥ بَیۡنَ أَیۡدِیهِنَّ وَأَرۡجُلِهِنَّ وَلَا یَعۡصِینَكَ فِی مَعۡرُوفࣲ فَبَایِعۡهُنَّ وَٱسۡتَغۡفِرۡ لَهُنَّ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمࣱ ۝١٢", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "يا أيها النبي إذا جاءك النساء المؤمنات بالله ورسوله يعاهدنك على ألا يجعلن مع الله شريكًا في عبادته، ولا يسرقن شيئًا، ولا يزنين، ولا يقتلن أولادهن بعد الولادة أو قبلها، ولا يُلحقن بأزواجهن أولادًا ليسوا منهم، ولا يخالفنك في معروف تأمرهن به، فعاهدهن على ذلك، واطلب لهن المغفرة من الله. إن الله غفور لذنوب عباده التائبين، رحيم بهم.", "isBasmala": false, "translation_en": "O prophet! If believing women come to you, pledging allegiance to you, on condition that they will not associate anything with God, nor steal, nor commit adultery, nor kill their children, nor commit perjury as to parenthood, nor disobey you in anything righteous, accept their allegiance and ask God's forgiveness for them. God is Forgiving and Merciful.", "translation_id": "Hai Nabi, apabila datang kepadamu perempuan-perempuan yang beriman untuk mengadakan janji setia, bahwa mereka tiada akan menyekutukan Allah, tidak akan mencuri, tidak akan berzina, tidak akan membunuh anak-anaknya, tidak akan berbuat dusta yang mereka ada-adakan antara tangan dan kaki mereka dan tidak akan mendurhakaimu dalam urusan yang baik, maka terimalah janji setia mereka dan mohonkanlah ampunan kepada Allah untuk mereka. Sesungguhnya Allah maha Pengampun lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 60, "sura_name": "الممتحنة", "revelation": "Madaniyah", "aya": 13, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَتَوَلَّوۡا۟ قَوۡمًا غَضِبَ ٱللَّهُ عَلَیۡهِمۡ قَدۡ یَىِٕسُوا۟ مِنَ ٱلۡـَٔاخِرَةِ كَمَا یَىِٕسَ ٱلۡكُفَّارُ مِنۡ أَصۡحَـٰبِ ٱلۡقُبُورِ ۝١٣", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "يا أيها الذين آمنوا بالله ورسوله، لا تتخذوا الذين غضب الله عليهم؛ لكفرهم أصدقاء وأخلاء، قد يئسوا من ثواب الله في الآخرة، كما يئس الكفار المقبورون، من رحمة الله في الآخرة؛ حين شاهدوا حقيقة الأمر، وعلموا علم اليقين أنهم لا نصيب لهم منها، أو كما يئس الكفار مِن بَعْث موتاهم -أصحاب القبور-؛ لاعتقادهم عدم البعث.", "isBasmala": false, "translation_en": "O you who believe! Do not befriend people with whom God has become angry, and have despaired of the Hereafter, as the faithless have despaired of the occupants of the graves.", "translation_id": "Hai orang-orang yang beriman, janganlah kamu jadikan penolongmu kaum yang dimurkai Allah. Sesungguhnya mereka telah putus asa terhadap negeri akhirat sebagaimana orang-orang kafir yang telah berada dalam kubur berputus asa.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 28, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 1, "text": "سَبَّحَ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝١", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "نزَّه الله عن كل ما لا يليق به كلُّ ما في السموات وما في الأرض، وهو العزيز الذي لا يغالَب، الحكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "Everything in the heavens and the earth praises God. He is the Almighty, the Wise.", "translation_id": "Telah bertasbih kepada Allah apa saja yang ada di langit dan apa saja yang ada di bumi; dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 2, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفۡعَلُونَ ۝٢", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لِمَ تَعِدون وعدًا، أو تقولون قولا ولا تفون به؟! وهذا إنكار على مَن يخالف فعلُه قولَه.", "isBasmala": false, "translation_en": "O you who believe! Why do you say what you do not do?", "translation_id": "Wahai orang-orang yang beriman, kenapakah kamu mengatakan sesuatu yang tidak kamu kerjakan?", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 3, "text": "كَبُرَ مَقۡتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفۡعَلُونَ ۝٣", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "عَظُم بغضًا عند الله أن تقولوا بألسنتكم ما لا تفعلونه.", "isBasmala": false, "translation_en": "It is most hateful to God that you say what you do not do.", "translation_id": "Amat besar kebencian di sisi Allah bahwa kamu mengatakan apa-apa yang tidak kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 4, "text": "إِنَّ ٱللَّهَ یُحِبُّ ٱلَّذِینَ یُقَـٰتِلُونَ فِی سَبِیلِهِۦ صَفࣰّا كَأَنَّهُم بُنۡیَـٰنࣱ مَّرۡصُوصࣱ ۝٤", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "إن الله يحب الذين يقاتلون في سبيله صفًا كأنهم بنيان متراص محكم لا ينفذ منه العدو. وفي الآية بيان فضل الجهاد والمجاهدين؛ لمحبة الله سبحانه لعباده المؤمنين إذا صفُّوا مواجهين لأعداء الله، يقاتلونهم في سبيله.", "isBasmala": false, "translation_en": "God loves those who fight in His cause, in ranks, as though they were a compact structure.", "translation_id": "Sesungguhnya Allah menyukai orang yang berperang dijalan-Nya dalam barisan yang teratur seakan-akan mereka seperti suatu bangunan yang tersusun kokoh.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 5, "text": "وَإِذۡ قَالَ مُوسَىٰ لِقَوۡمِهِۦ یَـٰقَوۡمِ لِمَ تُؤۡذُونَنِی وَقَد تَّعۡلَمُونَ أَنِّی رَسُولُ ٱللَّهِ إِلَیۡكُمۡۖ فَلَمَّا زَاغُوۤا۟ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ ۝٥", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "واذكر لقومك -أيها الرسول- حين قال نبي الله موسى عليه السلام لقومه: لِمَ تؤذونني بالقول والفعل، وأنتم تعلمون أني رسول الله إليكم؟ فلما عدلوا عن الحق مع علمهم به، وأصرُّوا على ذلك، صرف الله قلوبهم عن قَبول الهداية؛ عقوبة لهم على زيغهم الذي اختاروه لأنفسهم. والله لا يهدي القوم الخارجين عن الطاعة ومنهاج الحق.", "isBasmala": false, "translation_en": "When Moses said to his people, \"O my people, why do you hurt me, although you know that I am God's Messenger to you?\" And when they swerved, God swerved their hearts. God does not guide the sinful people.", "translation_id": "Dan (ingatlah) ketika Musa berkata kepada kaumnya: \"Hai kaumku, mengapa kamu menyakitiku, sedangkan kamu mengetahui bahwa sesungguhnya aku adalah utusan Allah kepadamu?\" Maka tatkala mereka berpaling (dari kebenaran), Allah memalingkan hati mereka; dan Allah tidak memberi petunjuk kepada kaum yang fasik.", "manzil": 7, "manzil_display": ""}], "552": [{"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 6, "text": "وَإِذۡ قَالَ عِیسَى ٱبۡنُ مَرۡیَمَ یَـٰبَنِیۤ إِسۡرَ ٰۤءِیلَ إِنِّی رَسُولُ ٱللَّهِ إِلَیۡكُم مُّصَدِّقࣰا لِّمَا بَیۡنَ یَدَیَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولࣲ یَأۡتِی مِنۢ بَعۡدِی ٱسۡمُهُۥۤ أَحۡمَدُۖ فَلَمَّا جَاۤءَهُم بِٱلۡبَیِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحۡرࣱ مُّبِینࣱ ۝٦", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "واذكر -أيها الرسول لقومك- حين قال عيسى ابن مريم لقومه: إني رسول الله إليكم، مصدِّقًا لما جاء قبلي من التوراة، وشاهدًا بصدق رسول يأتي من بعدي اسمه \"أحمد\"، وهو محمد صلى الله عليه وسلم، وداعيًا إلى التصديق به، فلما جاءهم محمد صلى الله عليه وسلم بالآيات الواضحات، قالوا: هـذا الذي جئتنا به سحر بيِّن.", "isBasmala": false, "translation_en": "And when Jesus son of Mary said, \"O Children of Israel, I am God's Messenger to you, confirming what preceded me of the Torah, and announcing good news of a messenger who will come after me, whose name is Ahmad.\" But when he showed them the miracles, they said, \"This is obvious sorcery.\"", "translation_id": "Dan (ingatlah) ketika Isa ibnu Maryam berkata: \"Hai Bani Israil, sesungguhnya aku adalah utusan Allah kepadamu, membenarkan kitab sebelumku, yaitu Taurat, dan memberi khabar gembira dengan (datangnya) seorang Rasul yang akan datang sesudahku, yang namanya Ahmad (Muhammad)\". Maka tatkala rasul itu datang kepada mereka dengan membawa bukti-bukti yang nyata, mereka berkata: \"Ini adalah sihir yang nyata\".", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 7, "text": "وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ ٱلۡكَذِبَ وَهُوَ یُدۡعَىٰۤ إِلَى ٱلۡإِسۡلَـٰمِۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝٧", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "ولا أحد أشد ظلمًا وعدوانًا ممن اختلق على الله الكذب، وجعل له شركاء في عبادته، وهو يُدعى إلى الدخول في الإسلام وإخلاص العبادة لله وحده. والله لا يوفِّق الذين ظلموا أنفسهم بالكفر والشرك، إلى ما فيه فلاحهم.", "isBasmala": false, "translation_en": "And who is a greater wrongdoer than he who attributes falsehoods to God, when he is being invited to Islam? God does not guide the wrongdoing people.", "translation_id": "Dan siapakah yang lebih zalim daripada orang yang mengada-adakan dusta terhadap Allah sedang dia diajak kepada Islam? Dan Allah tidak memberi petunjuk kepada orang-orang zalim.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 8, "text": "یُرِیدُونَ لِیُطۡفِـُٔوا۟ نُورَ ٱللَّهِ بِأَفۡوَ ٰهِهِمۡ وَٱللَّهُ مُتِمُّ نُورِهِۦ وَلَوۡ كَرِهَ ٱلۡكَـٰفِرُونَ ۝٨", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "يريد هؤلاء الظالمون أن يبطلوا الحق الذي بُعِثَ به محمد صلى الله عليه وسلم- وهو القرآن- بأقوالهم الكاذبة، والله مظهر الحق بإتمام دينه ولو كره الجاحدون المكذِّبون.", "isBasmala": false, "translation_en": "They want to extinguish God's Light with their mouths; but God will complete His Light, even though the disbelievers dislike it.", "translation_id": "Mereka ingin memadamkan cahaya Allah dengan mulut (tipu daya) mereka, tetapi Allah (justru) menyempurnakan cahaya-Nya, walau orang-orang kafir membencinya\".", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 9, "text": "هُوَ ٱلَّذِیۤ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِینِ ٱلۡحَقِّ لِیُظۡهِرَهُۥ عَلَى ٱلدِّینِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ ۝٩", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "الله هو الذي أرسل رسوله محمدًا بالقرآن ودين الإسلام؛ ليعليه على كل الأديان المخالفة له، ولو كره المشركون ذلك.", "isBasmala": false, "translation_en": "It is He who sent His Messenger with the guidance and the true religion, to make it prevail over all religions, even though the idolaters dislike it.", "translation_id": "Dialah yang mengutus Rasul-Nya dengan membawa petunjuk dan agama yang benar agar Dia memenangkannya di atas segala agama-agama meskipun orang musyrik membenci.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 10, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ هَلۡ أَدُلُّكُمۡ عَلَىٰ تِجَـٰرَةࣲ تُنجِیكُم مِّنۡ عَذَابٍ أَلِیمࣲ ۝١٠", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، هل أُرشِدكم إلى تجارة عظيمة الشأن تنجيكم من عذاب موجع؟", "isBasmala": false, "translation_en": "O you who believe! Shall I inform you of a trade that will save you from a painful torment?", "translation_id": "Hai orang-orang yang beriman, sukakah kamu aku tunjukkan suatu perniagaan yang dapat menyelamatkanmu dari azab yang pedih?", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 11, "text": "تُؤۡمِنُونَ بِٱللَّهِ وَرَسُولِهِۦ وَتُجَـٰهِدُونَ فِی سَبِیلِ ٱللَّهِ بِأَمۡوَ ٰلِكُمۡ وَأَنفُسِكُمۡۚ ذَ ٰلِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ۝١١", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "تداومون على إيمانكم بالله ورسوله، وتجاهدون في سبيل الله؛ لنصرة دينه بما تملكون من الأموال والأنفس، ذلك خير لكم من تجارة الدنيا، إن كنتم تعلمون مضارَّ الأشياء ومنافعها، فامتثلوا ذلك.", "isBasmala": false, "translation_en": "That you believe in God and His Messenger, and strive in the cause of God with your possessions and yourselves. That is best for you, if you only knew.", "translation_id": "(yaitu) kamu beriman kepada Allah dan Rasul-Nya dan berjihad di jalan Allah dengan harta dan jiwamu. Itulah yang lebih baik bagimu, jika kamu mengetahui.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 12, "text": "یَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡ وَیُدۡخِلۡكُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ وَمَسَـٰكِنَ طَیِّبَةࣰ فِی جَنَّـٰتِ عَدۡنࣲۚ ذَ ٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝١٢", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "إن فعلتم -أيها المؤمنون- ما أمركم الله به يستر عليكم ذنوبكم، ويدخلكم جنات تجري من تحت أشجارها الأنهار، ومساكن طاهرة زكية في جنات إقامة دائمة لا تنقطع، ذلك هو الفوز الذي لا فوز بعده. ونعمة أخرى لكم- أيها المؤمنون- تحبونها هي نصر من الله يأتيكم، وفتح عاجل يتم على أيديكم. وبشِّر المؤمنين -أيها النبي- بالنصر والفتح في الدنيا، والجنة في الآخرة.", "isBasmala": false, "translation_en": "He will forgive you your sins; and will admit you into gardens beneath which rivers flow, and into beautiful mansions in the Gardens of Eden. That is the supreme success.", "translation_id": "Niscaya Allah akan mengampuni dosa-dosamu dan memasukkanmu ke dalam jannah yang mengalir di bawahnya sungai-sungai; dan (memasukkan kamu) ke tempat tinggal yang baik di dalam jannah 'Adn. Itulah keberuntungan yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 13, "text": "وَأُخۡرَىٰ تُحِبُّونَهَاۖ نَصۡرࣱ مِّنَ ٱللَّهِ وَفَتۡحࣱ قَرِیبࣱۗ وَبَشِّرِ ٱلۡمُؤۡمِنِینَ ۝١٣", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "إن فعلتم -أيها المؤمنون- ما أمركم الله به يستر عليكم ذنوبكم، ويدخلكم جنات تجري من تحت أشجارها الأنهار، ومساكن طاهرة زكية في جنات إقامة دائمة لا تنقطع، ذلك هو الفوز الذي لا فوز بعده. ونعمة أخرى لكم- أيها المؤمنون- تحبونها هي نصر من الله يأتيكم، وفتح عاجل يتم على أيديكم. وبشِّر المؤمنين -أيها النبي- بالنصر والفتح في الدنيا، والجنة في الآخرة.", "isBasmala": false, "translation_en": "And something else you love: support from God, and imminent victory. So give good news to the believers.", "translation_id": "Dan (ada lagi) karunia yang lain yang kamu sukai (yaitu) pertolongan dari Allah dan kemenangan yang dekat (waktunya). Dan sampaikanlah berita gembira kepada orang-orang yang beriman.", "manzil": 7, "manzil_display": ""}, {"sura": 61, "sura_name": "الصف", "revelation": "Madaniyah", "aya": 14, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ كُونُوۤا۟ أَنصَارَ ٱللَّهِ كَمَا قَالَ عِیسَى ٱبۡنُ مَرۡیَمَ لِلۡحَوَارِیِّـۧنَ مَنۡ أَنصَارِیۤ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِیُّونَ نَحۡنُ أَنصَارُ ٱللَّهِۖ فَـَٔامَنَت طَّاۤىِٕفَةࣱ مِّنۢ بَنِیۤ إِسۡرَ ٰۤءِیلَ وَكَفَرَت طَّاۤىِٕفَةࣱۖ فَأَیَّدۡنَا ٱلَّذِینَ ءَامَنُوا۟ عَلَىٰ عَدُوِّهِمۡ فَأَصۡبَحُوا۟ ظَـٰهِرِینَ ۝١٤", "juz": 28, "hizb": "(*¾ ح 55*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، كونوا أنصارًا لدين الله، كما كان أصفياء عيسى أنصارًا لدين الله حين قال لهم عيسى: مَن يتولى منكم نصري وإعانتي فيما يُقرِّب إلى الله؟ قالوا: نحن أنصار دين الله، فاهتدت طائفة من بني إسرائيل، وضلَّت طائفة، فأيدنا الذين آمنوا بالله ورسوله، ونصرناهم على مَن عاداهم مِن فرق النصارى، فأصبحوا ظاهرين عليهم؛ وذلك ببعثة محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "O you who believe! Be supporters of God, as Jesus son of Mary said to the disciples, \"Who are my supporters towards God?\" The disciples said, \"We are God's supporters.\" So a group of the Children of Israel believed, while another group disbelieved. We supported those who believed against their foe, so they became dominant.", "translation_id": "Hai orang-orang yang beriman, jadilah kamu penolong (agama) Allah sebagaimana Isa ibnu Maryam telah berkata kepada pengikut-pengikutnya yang setia: \"Siapakah yang akan menjadi penolong-penolongku (untuk menegakkan agama) Allah?\" Pengikut-pengikut yang setia itu berkata: \"Kamilah penolong-penolong agama Allah\", lalu segolongan dari Bani Israil beriman dan segolongan lain kafir; maka Kami berikan kekuatan kepada orang-orang yang beriman terhadap musuh-musuh mereka, lalu mereka menjadi orang-orang yang menang.", "manzil": 7, "manzil_display": ""}], "553": [{"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 28, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 1, "text": "۞ یُسَبِّحُ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ ۝١", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "ينزِّه الله تعالى عن كل ما لا يليق به كلُّ ما في السموات وما في الأرض، وهو وحده المالك لكل شيء، المتصرف فيه بلا منازع، المنزَّه عن كل نقص، العزيز الذي لا يغالَب، الحكيم في تدبيره وصنعه.", "isBasmala": false, "translation_en": "Everything in the heavens and the earth glorifies God the Sovereign, the Holy, the Almighty, the Wise.", "translation_id": "Senantiasa bertasbih kepada Allah apa yang ada di langit dan apa yang ada di bumi. Raja, Yang Maha Suci, Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 2, "text": "هُوَ ٱلَّذِی بَعَثَ فِی ٱلۡأُمِّیِّـۧنَ رَسُولࣰا مِّنۡهُمۡ یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِهِۦ وَیُزَكِّیهِمۡ وَیُعَلِّمُهُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُوا۟ مِن قَبۡلُ لَفِی ضَلَـٰلࣲ مُّبِینࣲ ۝٢", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "الله سبحانه هو الذي أرسل في العرب الذين لا يقرؤون، ولا كتاب عندهم ولا أثر رسالة لديهم، رسولا منهم إلى الناس جميعًا، يقرأ عليهم القرآن، ويطهرهم من العقائد الفاسدة والأخلاق السيئة، ويعلِّمهم القرآن والسنة، إنهم كانوا من قبل بعثته لفي انحراف واضح عن الحق. وأرسله سبحانه إلى قوم آخرين لم يجيئوا بعدُ، وسيجيئون من العرب ومن غيرهم. والله تعالى- وحده- هو العزيز الغالب على كل شيء، الحكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "It is He who sent among the unlettered a messenger from themselves; reciting His revelations to them, and purifying them, and teaching them the Scripture and wisdom; although they were in obvious error before that.", "translation_id": "Dialah yang mengutus kepada kaum yang buta huruf seorang Rasul di antara mereka, yang membacakan ayat-ayat-Nya kepada mereka, mensucikan mereka dan mengajarkan mereka Kitab dan Hikmah (As Sunnah). Dan sesungguhnya mereka sebelumnya benar-benar dalam kesesatan yang nyata,", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 3, "text": "وَءَاخَرِینَ مِنۡهُمۡ لَمَّا یَلۡحَقُوا۟ بِهِمۡۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝٣", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "الله سبحانه هو الذي أرسل في العرب الذين لا يقرؤون، ولا كتاب عندهم ولا أثر رسالة لديهم، رسولا منهم إلى الناس جميعًا، يقرأ عليهم القرآن، ويطهرهم من العقائد الفاسدة والأخلاق السيئة، ويعلِّمهم القرآن والسنة، إنهم كانوا من قبل بعثته لفي انحراف واضح عن الحق. وأرسله سبحانه إلى قوم آخرين لم يجيئوا بعدُ، وسيجيئون من العرب ومن غيرهم. والله تعالى- وحده- هو العزيز الغالب على كل شيء، الحكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "And others from them, who have not yet joined them. He is the Glorious, the Wise.", "translation_id": "dan (juga) kepada kaum yang lain dari mereka yang belum berhubungan dengan mereka. Dan Dialah Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 4, "text": "ذَ ٰلِكَ فَضۡلُ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ ۝٤", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "ذلك البعث للرسول صلى الله عليه وسلم، في أمة العرب وغيرهم، فضل من الله، يعطيه مَن يشاء من عباده. وهو - وحده- ذو الإحسان والعطاء الجزيل.", "isBasmala": false, "translation_en": "That is God's grace, which He grants to whomever He wills. God is Possessor of limitless grace.", "translation_id": "Demikianlah karunia Allah, diberikan-Nya kepada siapa yang dikehendaki-Nya; dan Allah mempunyai karunia yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 5, "text": "مَثَلُ ٱلَّذِینَ حُمِّلُوا۟ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ یَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ یَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِ ٱللَّهِۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ ۝٥", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "شَبَهُ اليهود الذين كُلِّفوا العمل بالتوراة ثم لم يعملوا بها، كشَبه الحمار الذي يحمل كتبًا لا يدري ما فيها، قَبُحَ مَثَلُ القوم الذين كذَّبوا بآيات الله، ولم ينتفعوا بها، والله لا يوفِّق القوم الظالمين الذين يتجاوزون حدوده، ويخرجون عن طاعته.", "isBasmala": false, "translation_en": "The example of those who were entrusted with the Torah, but then failed to uphold it, is like the donkey carrying works of literature. Miserable is the example of the people who denounce God's revelations. God does not guide the wrongdoing people.", "translation_id": "Perumpamaan orang-orang yang dipikulkan kepadanya Taurat, kemudian mereka tiada memikulnya adalah seperti keledai yang membawa kitab-kitab yang tebal. Amatlah buruknya perumpamaan kaum yang mendustakan ayat-ayat Allah itu. Dan Allah tiada memberi petunjuk kepada kaum yang zalim.", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 6, "text": "قُلۡ یَـٰۤأَیُّهَا ٱلَّذِینَ هَادُوۤا۟ إِن زَعَمۡتُمۡ أَنَّكُمۡ أَوۡلِیَاۤءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلۡمَوۡتَ إِن كُنتُمۡ صَـٰدِقِینَ ۝٦", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "قل -أيها الرسول- للذين تمسكوا بالملة اليهودية المحرَّفة: إن ادَّعيتم- كذبًا- أنكم أحباء الله دون غيركم من الناس، فتمنَّوا الموت إن كنتم صادقين في ادِّعائكم حب الله لكم.", "isBasmala": false, "translation_en": "Say, \"O you who follow Judaism; if you claim to be the chosen of God, to the exclusion of the rest of mankind, then wish for death if you are sincere.\"", "translation_id": "Katakanlah: \"Hai orang-orang yang menganut agama Yahudi, jika kamu mendakwakan bahwa sesungguhnya kamu sajalah kekasih Allah bukan manusia-manusia yang lain, maka harapkanlah kematianmu, jika kamu adalah orang-orang yang benar\".", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 7, "text": "وَلَا یَتَمَنَّوۡنَهُۥۤ أَبَدَۢا بِمَا قَدَّمَتۡ أَیۡدِیهِمۡۚ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ ۝٧", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "ولا يتمنى هؤلاء اليهود الموت أبدًا إيثارًا للحياة الدنيا على الآخرة، وخوفًا من عقاب الله لهم؛ بسبب ما قدَّموه من الكفر وسوء الفعال. والله عليم بالظالمين، لا يخفى عليه من ظلمهم شيء.", "isBasmala": false, "translation_en": "But they will not wish for it, ever, due to what their hands have advanced. God knows well the wrongdoers.", "translation_id": "Mereka tiada akan mengharapkan kematian itu selama-lamanya disebabkan kejahatan yang telah mereka perbuat dengan tangan mereka sendiri. Dan Allah Maha Mengetahui akan orang-orang yang zalim.", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 8, "text": "قُلۡ إِنَّ ٱلۡمَوۡتَ ٱلَّذِی تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَـٰقِیكُمۡۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٨", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "قل: إن الموت الذي تهربون منه لا مفرَّ منه، فإنه آتٍ إليكم عند مجيء آجالكم، ثم ترجعون يوم البعث إلى الله العالم بما غاب وما حضر، فيخبركم بأعمالكم، وسيجازيكم عليها.", "isBasmala": false, "translation_en": "Say, \"The death from which you flee will catch up with you; then you will be returned to the Knower of the Invisible and the Visible, and He will inform you of what you used to do.\"", "translation_id": "Katakanlah: \"Sesungguhnya kematian yang kamu lari daripadanya, maka sesungguhnya kematian itu akan menemui kamu, kemudian kamu akan dikembalikan kepada (Allah), yang mengetahui yang ghaib dan yang nyata, lalu Dia beritakan kepadamu apa yang telah kamu kerjakan\".", "manzil": 7, "manzil_display": ""}], "554": [{"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 9, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نُودِیَ لِلصَّلَوٰةِ مِن یَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡا۟ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُوا۟ ٱلۡبَیۡعَۚ ذَ ٰلِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ ۝٩", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، إذا نادى المؤذن للصلاة في يوم الجمعة، فامضوا إلى سماع الخطبة وأداء الصلاة، واتركوا البيع، وكذلك الشراء وجميع ما يَشْغَلُكم عنها، ذلك الذي أُمرتم به خير لكم؛ لما فيه من غفران ذنوبكم ومثوبة الله لكم، إن كنتم تعلمون مصالح أنفسكم فافعلوا ذلك. وفي الآية دليل على وجوب حضور الجمعة واستماع الخطبة.", "isBasmala": false, "translation_en": "O you who believe! When the call is made for prayer on Congregation Day, hasten to the remembrance of God, and drop all business. That is better for you, if you only knew.", "translation_id": "Hai orang-orang beriman, apabila diseru untuk menunaikan shalat Jum'at, maka bersegeralah kamu kepada mengingat Allah dan tinggalkanlah jual beli. Yang demikian itu lebih baik bagimu jika kamu mengetahui.", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 10, "text": "فَإِذَا قُضِیَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِی ٱلۡأَرۡضِ وَٱبۡتَغُوا۟ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُوا۟ ٱللَّهَ كَثِیرࣰا لَّعَلَّكُمۡ تُفۡلِحُونَ ۝١٠", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "فإذا سمعتم الخطبة، وأدَّيتم الصلاة، فانتشروا في الأرض، واطلبوا من رزق الله بسعيكم، واذكروا الله كثيرًا في جميع أحوالكم؛ لعلكم تفوزون بخيري الدنيا والآخرة.", "isBasmala": false, "translation_en": "Then, when the prayer is concluded, disperse through the land, and seek God's bounty, and remember God much, so that you may prosper.", "translation_id": "Apabila telah ditunaikan shalat, maka bertebaranlah kamu di muka bumi; dan carilah karunia Allah dan ingatlah Allah banyak-banyak supaya kamu beruntung.", "manzil": 7, "manzil_display": ""}, {"sura": 62, "sura_name": "الجمعة", "revelation": "Madaniyah", "aya": 11, "text": "وَإِذَا رَأَوۡا۟ تِجَـٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوۤا۟ إِلَیۡهَا وَتَرَكُوكَ قَاۤىِٕمࣰاۚ قُلۡ مَا عِندَ ٱللَّهِ خَیۡرࣱ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَـٰرَةِۚ وَٱللَّهُ خَیۡرُ ٱلرَّ ٰزِقِینَ ۝١١", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "إذا رأى بعض المسلمين تجارة أو شيئًا مِن لهو الدنيا وزينتها تفرَّقوا إليها، وتركوك -أيها النبي- قائمًا على المنبر تخطب، قل لهم-أيها النبي-: ما عند الله من الثواب والنعيم أنفع لكم من اللهو ومن التجارة، والله- وحده- خير مَن رزق وأعطى، فاطلبوا منه، واستعينوا بطاعته على نيل ما عنده من خيري الدنيا والآخرة.", "isBasmala": false, "translation_en": "Yet whenever they come across some business, or some entertainment, they scramble towards it, and leave you standing. Say, \"What is with God is better than entertainment and business; and God is the Best of providers.\"", "translation_id": "Dan apabila mereka melihat perniagaan atau permainan, mereka bubar untuk menuju kepadanya dan mereka tinggalkan kamu sedang berdiri (berkhotbah). Katakanlah: \"Apa yang di sisi Allah lebih baik daripada permainan dan perniagaan\", dan Allah Sebaik-baik Pemberi rezeki.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 28, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 1, "text": "إِذَا جَاۤءَكَ ٱلۡمُنَـٰفِقُونَ قَالُوا۟ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ یَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ یَشۡهَدُ إِنَّ ٱلۡمُنَـٰفِقِینَ لَكَـٰذِبُونَ ۝١", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "إذا حضر مجلسك المنافقون -أيها الرسول- قالوا بألسنتهم، نشهد إنك لرسول الله، والله يعلم إنك لرسول الله، والله يشهد إن المنافقين لكاذبون فيما أظهروه من شهادتهم لك، وحلفوا عليه بألسنتهم، وأضمروا الكفر به.", "isBasmala": false, "translation_en": "When the hypocrites come to you, they say, \"We bear witness that you are God's Messenger.\" God knows that you are His Messenger, and God bears witness that the hypocrites are liars.", "translation_id": "Apabila orang-orang munafik datang kepadamu, mereka berkata: \"Kami mengakui, bahwa sesungguhnya kamu benar-benar Rasul Allah\". Dan Allah mengetahui bahwa sesungguhnya kamu benar-benar Rasul-Nya; dan Allah mengetahui bahwa sesungguhnya orang-orang munafik itu benar-benar orang pendusta.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 2, "text": "ٱتَّخَذُوۤا۟ أَیۡمَـٰنَهُمۡ جُنَّةࣰ فَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِۚ إِنَّهُمۡ سَاۤءَ مَا كَانُوا۟ یَعۡمَلُونَ ۝٢", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "إنما جعل المنافقون أيمانهم التي أقسموها سترة ووقاية لهم من المؤاخذة والعذاب، ومنعوا أنفسهم، ومنعوا الناس عن طريق الله المستقيم، إنهم بئس ما كانوا يعملون؛ ذلك لأنهم آمنوا في الظاهر، ثم كفروا في الباطن، فختم الله على قلوبهم بسبب كفرهم، فهم لا يفهمون ما فيه صلاحهم.", "isBasmala": false, "translation_en": "They treat their oaths as a cover, and so they repel others from God's path. Evil is what they do.", "translation_id": "Mereka itu menjadikan sumpah mereka sebagai perisai, lalu mereka menghalangi (manusia) dari jalan Allah. Sesungguhnya amat buruklah apa yang telah mereka kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 3, "text": "ذَ ٰلِكَ بِأَنَّهُمۡ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَفۡقَهُونَ ۝٣", "juz": 28, "hizb": "(* ح 56*)", "tafsir": "إنما جعل المنافقون أيمانهم التي أقسموها سترة ووقاية لهم من المؤاخذة والعذاب، ومنعوا أنفسهم، ومنعوا الناس عن طريق الله المستقيم، إنهم بئس ما كانوا يعملون؛ ذلك لأنهم آمنوا في الظاهر، ثم كفروا في الباطن، فختم الله على قلوبهم بسبب كفرهم، فهم لا يفهمون ما فيه صلاحهم.", "isBasmala": false, "translation_en": "That is because they believed, and then disbelieved; so their hearts were sealed, and they cannot understand.", "translation_id": "Yang demikian itu adalah karena bahwa sesungguhnya mereka telah beriman, kemudian menjadi kafir (lagi) lalu hati mereka dikunci mati; karena itu mereka tidak dapat mengerti.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 4, "text": "۞ وَإِذَا رَأَیۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن یَقُولُوا۟ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبࣱ مُّسَنَّدَةࣱۖ یَحۡسَبُونَ كُلَّ صَیۡحَةٍ عَلَیۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَـٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ یُؤۡفَكُونَ ۝٤", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "وإذا نظرت إلى هؤلاء المنافقين تعجبك هيئاتهم ومناظرهم، وإن يتحدثوا تسمع لحديثهم؛ لفصاحة ألسنتهم، وهم لفراغ قلوبهم من الإيمان، وعقولهم من الفهم والعلم النافع كالأخشاب الملقاة على الحائط، التي لا حياة فيها، يظنون كل صوت عال واقعًا عليهم وضارًا بهم؛ لعلمهم بحقيقة حالهم، ولفرط جبنهم، والرعب الذي تمكَّن من قلوبهم، هم الأعداء الحقيقيون شديدو العداوة لك وللمؤمنين، فخذ حذرك منهم، أخزاهم الله وطردهم من رحمته، كيف ينصرفون عن الحق إلى ما هم فيه من النفاق والضلال؟", "isBasmala": false, "translation_en": "When you see them, their appearance impresses you. And when they speak, you listen to what they say. They are like propped-up timber. They think every shout is aimed at them. They are the enemy, so beware of them. God condemns them; how deluded they are!", "translation_id": "Dan apabila kamu melihat mereka, tubuh-tubuh mereka menjadikan kamu kagum. Dan jika mereka berkata kamu mendengarkan perkataan mereka. Mereka adalah seakan-akan kayu yang tersandar. Mereka mengira bahwa tiap-tiap teriakan yang keras ditujukan kepada mereka. Mereka itulah musuh (yang sebenarnya) maka waspadalah terhadap mereka; semoga Allah membinasakan mereka. Bagaimanakah mereka sampai dipalingkan (dari kebenaran)?", "manzil": 7, "manzil_display": ""}], "555": [{"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 5, "text": "وَإِذَا قِیلَ لَهُمۡ تَعَالَوۡا۟ یَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡا۟ رُءُوسَهُمۡ وَرَأَیۡتَهُمۡ یَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ ۝٥", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "وإذا قيل لهؤلاء المنافقين: أقبلوا تائبين معتذرين عمَّا بدر منكم من سيِّئ القول وسفه الحديث، يستغفر لكم رسول الله ويسأل الله لكم المغفرة والعفو عن ذنوبكم، أمالوا رؤوسهم وحركوها استهزاءً واستكبارًا، وأبصرتهم -أيها الرسول- يعرضون عنك، وهم مستكبرون عن الامتثال لما طُلِب منهم.", "isBasmala": false, "translation_en": "And when it is said to them, \"Come, the Messenger of God will ask forgiveness for you,\" they bend their heads, and you see them turning away arrogantly.", "translation_id": "Dan apabila dikatakan kepada mereka: Marilah (beriman), agar Rasulullah memintakan ampunan bagimu, mereka membuang muka mereka dan kamu lihat mereka berpaling sedang mereka menyombongkan diri.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 6, "text": "سَوَاۤءٌ عَلَیۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن یَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ ۝٦", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "سواء على هؤلاء المنافقين أطلبت لهم المغفرة من الله -أيها الرسول- أم لم تطلب لهم، إن الله لن يصفح عن ذنوبهم أبدًا؛ لإصرارهم على الفسق ورسوخهم في الكفر. إن الله لا يوفِّق للإيمان القوم الكافرين به، الخارجين عن طاعته.", "isBasmala": false, "translation_en": "It is the same for them, whether you ask forgiveness for them, or do not ask forgiveness for them; God will not forgive them. God does not guide the sinful people.", "translation_id": "Sama saja bagi mereka, kamu mintakan ampunan atau tidak kamu mintakan ampunan bagi mereka. Sesungguhnya Allah tidak memberi petunjuk kepada orang-orang yang fasik.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 7, "text": "هُمُ ٱلَّذِینَ یَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ یَنفَضُّوا۟ۗ وَلِلَّهِ خَزَاۤىِٕنُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَلَـٰكِنَّ ٱلۡمُنَـٰفِقِینَ لَا یَفۡقَهُونَ ۝٧", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "هؤلاء المنافقون هم الذين يقولون لأهل \"المدينة\": لا تنفقوا على أصحاب رسول الله من المهاجرين حتى يتفرقوا عنه. ولله وحده خزائن السموات والأرض وما فيهما من أرزاق، يعطيها من يشاء ويمنعها عمَّن يشاء، ولكن المنافقين ليس لديهم فقه ولا ينفعهم ذلك.", "isBasmala": false, "translation_en": "It is they who say: \"Do not spend anything on those who side with God's Messenger, unless they have dispersed.\" To God belong the treasures of the heavens and the earth, but the hypocrites do not understand.", "translation_id": "Mereka orang-orang yang mengatakan (kepada orang-orang Anshar): \"Janganlah kamu memberikan perbelanjaan kepada orang-orang (Muhajirin) yang ada disisi Rasulullah supaya mereka bubar (meninggalkan Rasulullah)\". Padahal kepunyaan Allah-lah perbendaharaan langit dan bumi, tetapi orang-orang munafik itu tidak memahami.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 8, "text": "یَقُولُونَ لَىِٕن رَّجَعۡنَاۤ إِلَى ٱلۡمَدِینَةِ لَیُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِینَ وَلَـٰكِنَّ ٱلۡمُنَـٰفِقِینَ لَا یَعۡلَمُونَ ۝٨", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "يقول هؤلاء المنافقون: لئن عُدْنا إلى \"المدينة\" ليخرجنَّ فريقنا الأعزُّ منها فريق المؤمنين الأذل، ولله تعالى العزة ولرسوله صلى الله عليه وسلم، وللمؤمنين بالله ورسوله لا لغيرهم، ولكن المنافقين لا يعلمون ذلك؛ لفرط جهلهم.", "isBasmala": false, "translation_en": "They say, \"If we return to the City, the more powerful therein will evict the weak.\" But power belongs to God, and His Messenger, and the believers; but the hypocrites do not know.", "translation_id": "Mereka berkata: \"Sesungguhnya jika kita telah kembali ke Madinah, benar-benar orang yang kuat akan mengusir orang-orang yang lemah dari padanya\". Padahal kekuatan itu hanyalah bagi Allah, bagi Rasul-Nya dan bagi orang-orang mukmin, tetapi orang-orang munafik itu tiada mengetahui.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 9, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُلۡهِكُمۡ أَمۡوَ ٰلُكُمۡ وَلَاۤ أَوۡلَـٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن یَفۡعَلۡ ذَ ٰلِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ ۝٩", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، لا تَشْغَلْكم أموالكم ولا أولادكم عن عبادة الله وطاعته، ومن تشغَله أمواله وأولاده عن ذلك، فأولئك هم المغبونون حظوظهم من كرامة الله ورحمته.", "isBasmala": false, "translation_en": "O you who believe! Let neither your possessions nor your children distract you from the remembrance of God. Whoever does that-these are the losers.", "translation_id": "Hai orang-orang beriman, janganlah hartamu dan anak-anakmu melalaikan kamu dari mengingat Allah. Barangsiapa yang berbuat demikian maka mereka itulah orang-orang yang merugi.", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 10, "text": "وَأَنفِقُوا۟ مِن مَّا رَزَقۡنَـٰكُم مِّن قَبۡلِ أَن یَأۡتِیَ أَحَدَكُمُ ٱلۡمَوۡتُ فَیَقُولَ رَبِّ لَوۡلَاۤ أَخَّرۡتَنِیۤ إِلَىٰۤ أَجَلࣲ قَرِیبࣲ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِینَ ۝١٠", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "وأنفقوا -أيها المؤمنون- بالله ورسوله بعض ما أعطيناكم في طرق الخير، مبادرين بذلك من قبل أن يجيء أحدكم الموت، ويرى دلائله وعلاماته، فيقول نادمًا: ربِّ هلا أمهلتني، وأجَّلت موتي إلى وقت قصير، فأتصدق من مالي، وأكن من الصالحين الأتقياء.", "isBasmala": false, "translation_en": "And give from what We have provided for you, before death approaches one of you, and he says, \"My Lord, if only You would delay me for a short while, so that I may be charitable, and be one of the righteous.\"", "translation_id": "Dan belanjakanlah sebagian dari apa yang telah Kami berikan kepadamu sebelum datang kematian kepada salah seorang di antara kamu; lalu ia berkata: \"Ya Rabb-ku, mengapa Engkau tidak menangguhkan (kematian)ku sampai waktu yang dekat, yang menyebabkan aku dapat bersedekah dan aku termasuk orang-orang yang saleh?\"", "manzil": 7, "manzil_display": ""}, {"sura": 63, "sura_name": "المنافقون", "revelation": "Madaniyah", "aya": 11, "text": "وَلَن یُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَاۤءَ أَجَلُهَاۚ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ ۝١١", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "ولن يؤخر الله نفسًا إذا جاء وقت موتها، وانقضى عمرها، والله سبحانه خبير بالذي تعملونه من خير وشر، وسيجازيكم على ذلك.", "isBasmala": false, "translation_en": "But God will not delay a soul when its time has come. God is Informed of what you do.", "translation_id": "Dan Allah sekali-kali tidak akan menangguhkan (kematian) seseorang apabila telah datang waktu kematiannya. Dan Allah Maha Mengenal apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}], "556": [{"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 28, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 1, "text": "یُسَبِّحُ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَمَا فِی ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝١", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "ينزِّه الله عما لا يليق به كل ما في السموات وما في الأرض، له سبحانه التصرف المطلق في كل شيء، وله الثناء الحسن الجميل، وهو على كل شيء قدير.", "isBasmala": false, "translation_en": "Everything in the heavens and the earth praises God. To Him belongs the Kingdom, and to Him all praise is due, and He is Able to do all things.", "translation_id": "Bertasbih kepada Allah apa yang ada di langit dan apa yang ada di bumi; hanya Allah lah yang mempunyai semua kerajaan dan semua pujian, dan Dia Maha Kuasa atas segala sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 2, "text": "هُوَ ٱلَّذِی خَلَقَكُمۡ فَمِنكُمۡ كَافِرࣱ وَمِنكُم مُّؤۡمِنࣱۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرٌ ۝٢", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "الله هو الذي أوجدكم من العدم، فبعضكم جاحد لألوهيته، وبعضكم مصدِّق به عامل بشرعه، وهو سبحانه بصير بأعمالكم لا يخفى عليه شيء منها، وسيجازيكم بها.", "isBasmala": false, "translation_en": "It is He who created you. Some of you are unbelievers, and some of you are believers. And God perceives what you do.", "translation_id": "Dialah yang menciptakan kamu maka di antara kamu ada yang kafir dan di antaramu ada yang mukmin. Dan Allah Maha Melihat apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 3, "text": "خَلَقَ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَیۡهِ ٱلۡمَصِیرُ ۝٣", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "خلق الله السموات والأرض بالحكمة البالغة، وخلقكم في أحسن صورة، إليه المرجع يوم القيامة، فيجازي كلا بعمله.", "isBasmala": false, "translation_en": "He created the heavens and the earth with truth, and He designed you, and designed you well, and to Him is the final return.", "translation_id": "Dia menciptakan langit dan bumi dengan haq. Dia membentuk rupamu dan dibaguskan-Nya rupamu itu dan hanya kepada Allah-lah kembali(mu).", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 4, "text": "یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَیَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝٤", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "يعلم سبحانه وتعالى كل ما في السموات والأرض، ويعلم ما تخفونه -أيها الناس- فيما بينكم وما تظهرونه. والله عليم بما تضمره الصدور وما تخفيه النفوس.", "isBasmala": false, "translation_en": "He knows everything in the heavens and the earth, and He knows what you conceal and what you reveal. And God knows what is within the hearts.", "translation_id": "Dia mengetahui apa yang ada di langit dan di bumi dan mengetahui apa yang kamu rahasiakan dan yang kamu nyatakan. Dan Allah Maha Mengetahui segala isi hati.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 5, "text": "أَلَمۡ یَأۡتِكُمۡ نَبَؤُا۟ ٱلَّذِینَ كَفَرُوا۟ مِن قَبۡلُ فَذَاقُوا۟ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمࣱ ۝٥", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "ألم يأتكم- أيها المشركون- خبر الذين كفروا من الأمم الماضية قبلكم، إذ حلَّ بهم سوء عاقبة كفرهم وسوء أفعالهم في الدنيا، ولهم في الآخرة عذاب أليم موجع؟", "isBasmala": false, "translation_en": "Has the news not reached you, of those who disbelieved before? They tasted the ill consequences of their conduct, and a painful torment awaits them.", "translation_id": "Apakah belum datang kepadamu (hai orang-orang kafir) berita orang-orang kafir terdahulu. Maka mereka telah merasakan akibat yang buruk dari perbuatan mereka dan mereka memperoleh azab yang pedih.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 6, "text": "ذَ ٰلِكَ بِأَنَّهُۥ كَانَت تَّأۡتِیهِمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَقَالُوۤا۟ أَبَشَرࣱ یَهۡدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ۖ وَّٱسۡتَغۡنَى ٱللَّهُۚ وَٱللَّهُ غَنِیٌّ حَمِیدࣱ ۝٦", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "ذلك الذي أصابهم في الدنيا، وما يصيبهم في الآخرة؛ بسبب أنهم كانت تأتيهم رسل الله بالآيات البينات والمعجزات الواضحات، فقالوا منكرين: أبشر مثلنا يرشدوننا؟ فكفروا بالله وجحدوا رسالة رسله، وأعرضوا عن الحق فلم يقبلوه. واستغنى الله، والله غني، له الغنى التام المطلق، حميد في أقواله وأفعاله وصفاته لا يبالي بهم، ولا يضره ضلالهم شيئًا.", "isBasmala": false, "translation_en": "That is because their messengers came to them with clear explanations, but they said, \"Are human beings going to guide us?\" So they disbelieved and turned away. But God is in no need. God is Independent and Praiseworthy.", "translation_id": "Yang demikian itu adalah karena sesungguhnya telah datang kepada mereka Rasul-Rasul mereka membawa keterangan-keterangan lalu mereka berkata: \"Apakah manusia yang akan memberi petunjuk kepada kami?\" lalu mereka ingkar dan berpaling; dan Allah tidak memerlukan (mereka). Dan Allah Maha Kaya lagi Maha Terpuji.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 7, "text": "زَعَمَ ٱلَّذِینَ كَفَرُوۤا۟ أَن لَّن یُبۡعَثُوا۟ۚ قُلۡ بَلَىٰ وَرَبِّی لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَ ٰلِكَ عَلَى ٱللَّهِ یَسِیرࣱ ۝٧", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "ادَّعى الذين كفروا بالله باطلا أنهم لن يُخْرَجوا من قبورهم بعد الموت، قل لهم -أيها الرسول-: بلى وربي لتُخْرَجُنَّ من قبوركم أحياء، ثم لتُخْبَرُنَّ بالذي عملتم في الدنيا، وذلك على الله يسير هيِّن.", "isBasmala": false, "translation_en": "Those who disbelieve claim that they will not be resurrected. Say, \"Yes indeed, by my Lord, you will be resurrected; then you will be informed of everything you did; and that is easy for God.\"", "translation_id": "Orang-orang yang kafir mengatakan bahwa mereka sekali-kali tidak akan dibangkitkan. Katakanlah: \"Memang, demi Tuhanku, benar-benar kamu akan dibangkitkan, kemudian akan diberitakan kepadamu apa yang telah kamu kerjakan\". Yang demikian itu adalah mudah bagi Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 8, "text": "فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِیۤ أَنزَلۡنَاۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ ۝٨", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "فآمنوا بالله ورسوله- أيها المشركون- واهتدوا بالقرآن الذي أنزله على رسوله، والله بما تفعلون خبير لا يخفى عليه شيء من أعمالكم وأقوالكم، وهو مجازيكم عليها يوم القيامة.", "isBasmala": false, "translation_en": "So believe in God and His Messenger, and the Light which We sent down. God is Aware of everything you do.", "translation_id": "Maka berimanlah kamu kepada Allah dan Rasul-Nya dan kepada cahaya (Al-Quran) yang telah Kami turunkan. Dan Allah Maha Mengetahui apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 9, "text": "یَوۡمَ یَجۡمَعُكُمۡ لِیَوۡمِ ٱلۡجَمۡعِۖ ذَ ٰلِكَ یَوۡمُ ٱلتَّغَابُنِۗ وَمَن یُؤۡمِنۢ بِٱللَّهِ وَیَعۡمَلۡ صَـٰلِحࣰا یُكَفِّرۡ عَنۡهُ سَیِّـَٔاتِهِۦ وَیُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۚ ذَ ٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ ۝٩", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "اذكروا يوم الحشر الذي يحشر الله فيه الأولين والآخرين، ذلك اليوم الذي يظهر فيه الغُبْن والتفاوت بين الخلق، فيغبن المؤمنون الكفار والفاسقين: فأهل الإيمان يدخلون الجنة برحمة الله، وأهل الكفر يدخلون النار بعدل الله. ومن يؤمن بالله ويعمل بطاعته، يمح عنه ذنوبه، ويدخله جنات تجري من تحت قصورها الأنهار، خالدين فيها أبدًا، ذلك الخلود في الجنات هو الفوز العظيم الذي لا فوز بعده.", "isBasmala": false, "translation_en": "The Day when He gathers you for the Day of Gathering-that is the Day of Mutual Exchange. Whoever believes in God and acts with integrity, He will remit his misdeeds, and will admit him into gardens beneath which rivers flow, to dwell therein forever. That is the supreme achievement.", "translation_id": "(Ingatlah) hari (dimana) Allah mengumpulkan kamu pada hari pengumpulan, itulah hari dinampakkan kesalahan-kesalahan. Dan barangsiapa yang beriman kepada Allah dan beramal saleh, niscaya Allah akan menutupi kesalahan-kesalahannya dan memasukkannya ke dalam jannah yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya. Itulah keberuntungan yang besar.", "manzil": 7, "manzil_display": ""}], "557": [{"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 10, "text": "وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِ خَـٰلِدِینَ فِیهَاۖ وَبِئۡسَ ٱلۡمَصِیرُ ۝١٠", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "والذين جحدوا أن الله هو الإله الحق وكذَّبوا بدلائل ربوبيته وبراهين ألوهيته التي أرسل بها رسله، أولئك أهل النار ماكثين فيها أبدًا، وساء المرجع الذي صاروا إليه، وهو جهنم.", "isBasmala": false, "translation_en": "But as for those who disbelieve and denounce Our revelations-these are the inmates of the Fire, dwelling therein forever; and what a miserable fate!", "translation_id": "Dan orang-orang yang kafir dan mendustakan ayat-ayat Kami, mereka itulah penghuni-penghuni neraka, mereka kekal di dalamnya. Dan itulah seburuk-buruk tempat kembali.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 11, "text": "مَاۤ أَصَابَ مِن مُّصِیبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن یُؤۡمِنۢ بِٱللَّهِ یَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ ۝١١", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "ما أصاب أحدًا شيءٌ من مكروه يَحُلُّ به إلا بإذن الله وقضائه وقدره. ومَن يؤمن بالله يهد قلبه للتسليم بأمره والرضا بقضائه، ويهده لأحسن الأقوال والأفعال والأحوال؛ لأن أصل الهداية للقلب، والجوارح تبع. والله بكل شيء عليم، لا يخفى عليه شيء من ذلك.", "isBasmala": false, "translation_en": "No disaster occurs except by God's leave. Whoever believes in God, He guides his heart. God is Aware of everything.", "translation_id": "Tidak ada suatu musibah pun yang menimpa seseorang kecuali dengan ijin Allah; dan barangsiapa yang beriman kepada Allah niscaya Dia akan memberi petunjuk kepada hatinya. Dan Allah Maha Mengetahui segala sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 12, "text": "وَأَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَۚ فَإِن تَوَلَّیۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ ۝١٢", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "وأطيعوا الله -أيها الناس- وانقادوا إليه فيما أمر به ونهى عنه، وأطيعوا الرسول صلى الله عليه وسلم، فيما بلَّغكم به عن ربه، فإن أعرضتم عن طاعة الله ورسوله، فليس على رسولنا ضرر في إعراضكم، وإنما عليه أن يبلغكم ما أرسل به بلاغًا واضح البيان.", "isBasmala": false, "translation_en": "So obey God, and obey the Messenger. But if you turn away-it is only incumbent on Our Messenger to deliver the clear message.", "translation_id": "Dan taatlah kepada Allah dan taatlah kepada Rasul-Nya, jika kamu berpaling sesungguhnya kewajiban Rasul Kami hanyalah menyampaikan (amanat Allah) dengan terang.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 13, "text": "ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ ۝١٣", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "الله وحده لا معبود بحق سواه، وعلى الله فليعتمد المؤمنون بوحدانيته في كل أمورهم.", "isBasmala": false, "translation_en": "God, there is no god but He; and in God let the believers put their trust.", "translation_id": "(Dialah) Allah tidak ada Tuhan selain Dia. Dan hendaklah orang-orang mukmin bertawakkal kepada Allah saja.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 14, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ مِنۡ أَزۡوَ ٰجِكُمۡ وَأَوۡلَـٰدِكُمۡ عَدُوࣰّا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُوا۟ وَتَصۡفَحُوا۟ وَتَغۡفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ ۝١٤", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "يا أيها الذين آمنوا بالله ورسوله، إنَّ مِن أزواجكم وأولادكم أعداء لكم يصدونكم عن سبيل الله، ويثبطونكم عن طاعته، فكونوا منهم على حذر، ولا تطيعوهم، وإن تتجاوزوا عن سيئاتهم وتعرضوا عنها، وتستروها عليهم، فإن الله غفور رحيم، يغفر لكم ذنوبكم؛ لأنه سبحانه عظيم الغفران واسع الرحمة.", "isBasmala": false, "translation_en": "O you who believe! Among your wives and your children are enemies to you, so beware of them. But if you pardon, and overlook, and forgive-God is Forgiver and Merciful.", "translation_id": "Hai orang-orang mukmin, sesungguhnya di antara isteri-isterimu dan anak-anakmu ada yang menjadi musuh bagimu maka berhati-hatilah kamu terhadap mereka dan jika kamu memaafkan dan tidak memarahi serta mengampuni (mereka) maka sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 15, "text": "إِنَّمَاۤ أَمۡوَ ٰلُكُمۡ وَأَوۡلَـٰدُكُمۡ فِتۡنَةࣱۚ وَٱللَّهُ عِندَهُۥۤ أَجۡرٌ عَظِیمࣱ ۝١٥", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "ما أموالكم ولا أولادكم إلا بلاء واختبار لكم. والله عنده ثواب عظيم لمن آثر طاعته على طاعة غيره، وأدَّى حق الله في ماله.", "isBasmala": false, "translation_en": "Your possessions and your children are a test, but with God is a splendid reward.", "translation_id": "Sesungguhnya hartamu dan anak-anakmu hanyalah cobaan (bagimu), dan di sisi Allah-lah pahala yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 16, "text": "فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُوا۟ وَأَطِیعُوا۟ وَأَنفِقُوا۟ خَیۡرࣰا لِّأَنفُسِكُمۡۗ وَمَن یُوقَ شُحَّ نَفۡسِهِۦ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ ۝١٦", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "فابذلوا- أيها المؤمنون- في تقوى الله جهدكم وطاقتكم، واسمعوا لرسول الله صلى الله عليه وسلم سماع تدبُّر وتفكر، وأطيعوا أوامره واجتنبوا نواهيه، وأنفقوا مما رزقكم الله يكن خيرًا لكم. ومن سَلِم من البخل ومَنْعِ الفضل من المال، فأولئك هم الظافرون بكل خير، الفائزون بكل مطلب.", "isBasmala": false, "translation_en": "So be conscious of God as much as you can, and listen, and obey, and give for your own good. He who is protected from his stinginess-these are the prosperous.", "translation_id": "Maka bertakwalah kamu kepada Allah menurut kesanggupanmu dan dengarlah serta taatlah dan nafkahkanlah nafkah yang baik untuk dirimu. Dan barangsiapa yang dipelihara dari kekikiran dirinya, maka mereka itulah orang-orang yang beruntung.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 17, "text": "إِن تُقۡرِضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰا یُضَـٰعِفۡهُ لَكُمۡ وَیَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِیمٌ ۝١٧", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "إن تنفقوا أموالكم في سبيل الله بإخلاص وطيب نفس، يضاعف الله ثواب ما أنفقتم، ويغفر لكم ذنوبكم. والله شكور لأهل الإنفاق بحسن الجزاء على ما أنفقوا، حليم لا يعجل بالعقوبة على مَن عصاه.", "isBasmala": false, "translation_en": "If you lend God a good loan, He will multiply it for you, and will forgive you. God is Appreciative and Forbearing.", "translation_id": "Jika kamu meminjamkan kepada Allah pinjaman yang baik, niscaya Allah melipat gandakan balasannya kepadamu dan mengampuni kamu. Dan Allah Maha Pembalas Jasa lagi Maha Penyantun.", "manzil": 7, "manzil_display": ""}, {"sura": 64, "sura_name": "التغابن", "revelation": "Madaniyah", "aya": 18, "text": "عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ ٱلۡعَزِیزُ ٱلۡحَكِیمُ ۝١٨", "juz": 28, "hizb": "(*¼ ح 56*)", "tafsir": "وهو سبحانه العالم بكل ما غاب وما حضر، العزيز الذي لا يغالَب، الحكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "The Knower of the Unseen and the Seen, the Almighty, the Wise.", "translation_id": "Yang mengetahui yang ghaib dan yang nyata. Yang Maha Perkasa lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}], "558": [{"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 28, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 1, "text": "۞ یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَاۤءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُوا۟ ٱلۡعِدَّةَۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُیُوتِهِنَّ وَلَا یَخۡرُجۡنَ إِلَّاۤ أَن یَأۡتِینَ بِفَـٰحِشَةࣲ مُّبَیِّنَةࣲۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن یَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِی لَعَلَّ ٱللَّهَ یُحۡدِثُ بَعۡدَ ذَ ٰلِكَ أَمۡرࣰا ۝١", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "يا أيها النبي إذا أردتم- أنت والمؤمنون- أن تطلِّقوا نساءكم فطلقوهن مستقبلات لعدتهن -أي في طهر لم يقع فيه جماع، أو في حَمْل ظاهر- واحفظوا العدة؛ لتعلموا وقت الرجعة إن أردتم أن تراجعوهن، وخافوا الله ربكم، لا تخرجوا المطلقات من البيوت التي يسكنَّ فيها إلى أن تنقضي عدتهن، وهي ثلاث حيضات لغير الصغيرة والآيسة والحامل، ولا يجوز لهن الخروج منها بأنفسهن، إلا إذا فعلن فعلة منكرة ظاهرة كالزنى، وتلك أحكام الله التي شرعها لعباده، ومن يتجاوز أحكام الله فقد ظلم نفسه، وأوردها مورد الهلاك. لا تدري- أيها المطلِّق-: لعل الله يحدث بعد ذلك الطلاق أمرًا لا تتوقعه فتراجعها.", "isBasmala": false, "translation_en": "O Prophet! If any of you divorce women, divorce them during their period of purity, and calculate their term. And be pious before God, your Lord. And do not evict them from their homes, nor shall they leave, unless they have committed a proven adultery. These are the limits of God-whoever oversteps God's limits has wronged his own soul. You never know; God may afterwards bring about a new situation.", "translation_id": "Hai Nabi, apabila kamu menceraikan isteri-isterimu maka hendaklah kamu ceraikan mereka pada waktu mereka dapat (menghadapi) iddahnya (yang wajar) dan hitunglah waktu iddah itu serta bertakwalah kepada Allah Tuhanmu. Janganlah kamu keluarkan mereka dari rumah mereka dan janganlah mereka (diizinkan) ke luar kecuali mereka mengerjakan perbuatan keji yang terang. Itulah hukum-hukum Allah dan barangsiapa yang melanggar hukum-hukum Allah, maka sesungguhnya dia telah berbuat zalim terhadap dirinya sendiri. Kamu tidak mengetahui barangkali Allah mengadakan sesudah itu sesuatu hal yang baru.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 2, "text": "فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفࣲ وَأَشۡهِدُوا۟ ذَوَیۡ عَدۡلࣲ مِّنكُمۡ وَأَقِیمُوا۟ ٱلشَّهَـٰدَةَ لِلَّهِۚ ذَ ٰلِكُمۡ یُوعَظُ بِهِۦ مَن كَانَ یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ وَمَن یَتَّقِ ٱللَّهَ یَجۡعَل لَّهُۥ مَخۡرَجࣰا ۝٢", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "فإذا قاربت المطلقات نهاية عدتهن فراجعوهن مع حسن المعاشرة، والإنفاق عليهن، أو فارقوهن مع إيفاء حقهن، دون المضارَّة لهن، وأشهدوا على الرجعة أو المفارقة رجلين عدلين منكم، وأدُّوا- أيها الشهود- الشهادة خالصة لله لا لشيء آخر، ذلك الذي أمركم الله به يوعظ به مَن كان يؤمن بالله واليوم الآخر. ومن يخف الله فيعمل بما أمره به، ويجتنب ما نهاه عنه، يجعل له مخرجًا من كل ضيق، وييسِّر له أسباب الرزق من حيث لا يخطر على باله، ولا يكون في حسبانه. ومن يتوكل على الله فهو كافيه ما أهمَّه في جميع أموره. إن الله بالغ أمره، لا يفوته شيء، ولا يعجزه مطلوب، قد جعل الله لكل شيء أجلا ينتهي إليه، وتقديرًا لا يجاوزه.", "isBasmala": false, "translation_en": "Once they have reached their term, either retain them honorably, or separate from them honorably. And call to witness two just people from among you, and give upright testimony for God. By that is exhorted whoever believes in God and the Last Day. And whoever fears God-He will make a way out for him.", "translation_id": "Apabila mereka telah mendekati akhir iddahnya, maka rujukilah mereka dengan baik atau lepaskanlah mereka dengan baik dan persaksikanlah dengan dua orang saksi yang adil di antara kamu dan hendaklah kamu tegakkan kesaksian itu karena Allah. Demikianlah diberi pengajaran dengan itu orang yang beriman kepada Allah dan hari akhirat. Barangsiapa bertakwa kepada Allah niscaya Dia akan mengadakan baginya jalan keluar.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 3, "text": "وَیَرۡزُقۡهُ مِنۡ حَیۡثُ لَا یَحۡتَسِبُۚ وَمَن یَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥۤۚ إِنَّ ٱللَّهَ بَـٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَیۡءࣲ قَدۡرࣰا ۝٣", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "فإذا قاربت المطلقات نهاية عدتهن فراجعوهن مع حسن المعاشرة، والإنفاق عليهن، أو فارقوهن مع إيفاء حقهن، دون المضارَّة لهن، وأشهدوا على الرجعة أو المفارقة رجلين عدلين منكم، وأدُّوا- أيها الشهود- الشهادة خالصة لله لا لشيء آخر، ذلك الذي أمركم الله به يوعظ به مَن كان يؤمن بالله واليوم الآخر. ومن يخف الله فيعمل بما أمره به، ويجتنب ما نهاه عنه، يجعل له مخرجًا من كل ضيق، وييسِّر له أسباب الرزق من حيث لا يخطر على باله، ولا يكون في حسبانه. ومن يتوكل على الله فهو كافيه ما أهمَّه في جميع أموره. إن الله بالغ أمره، لا يفوته شيء، ولا يعجزه مطلوب، قد جعل الله لكل شيء أجلا ينتهي إليه، وتقديرًا لا يجاوزه.", "isBasmala": false, "translation_en": "And will provide for him from where he never expected. Whoever relies on God-He will suffice him. God will accomplish His purpose. God has set a measure to all things.", "translation_id": "Dan memberinya rezeki dari arah yang tiada disangka-sangkanya. Dan barangsiapa yang bertawakkal kepada Allah niscaya Allah akan mencukupkan (keperluan)nya. Sesungguhnya Allah melaksanakan urusan yang (dikehendaki)Nya. Sesungguhnya Allah telah mengadakan ketentuan bagi tiap-tiap sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 4, "text": "وَٱلَّـٰۤـِٔی یَىِٕسۡنَ مِنَ ٱلۡمَحِیضِ مِن نِّسَاۤىِٕكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَـٰثَةُ أَشۡهُرࣲ وَٱلَّـٰۤـِٔی لَمۡ یَحِضۡنَۚ وَأُو۟لَـٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن یَضَعۡنَ حَمۡلَهُنَّۚ وَمَن یَتَّقِ ٱللَّهَ یَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ یُسۡرࣰا ۝٤", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "والنساء المطلقات اللاتي انقطع عنهنَّ دم الحيض؛ لكبر سنهنَّ، إن شككتم فلم تدروا ما الحكم فيهنَّ؟ فعدَّتهنَّ ثلاثة أشهر، والصغيرات اللاتي لم يحضن، فعدتهن ثلاثة أشهر كذلك. وذوات الحَمْل من النساء عدتهن أن يضعن حَمْلهن. ومن يَخَفِ الله، فينفذ أحكامه، يجعل له من أمره يسرًا في الدنيا والآخرة.", "isBasmala": false, "translation_en": "As for those of your women who have reached menopause, if you have any doubts, their term shall be three months-and also for those who have not yet menstruated. As for those who are pregnant, their term shall be until they have delivered. Whoever fears God-He will make things easy for him.", "translation_id": "Dan perempuan-perempuan yang tidak haid lagi (monopause) di antara perempuan-perempuanmu jika kamu ragu-ragu (tentang masa iddahnya), maka masa iddah mereka adalah tiga bulan; dan begitu (pula) perempuan-perempuan yang tidak haid. Dan perempuan-perempuan yang hamil, waktu iddah mereka itu ialah sampai mereka melahirkan kandungannya. Dan barang -siapa yang bertakwa kepada Allah, niscaya Allah menjadikan baginya kemudahan dalam urusannya.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 5, "text": "ذَ ٰلِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥۤ إِلَیۡكُمۡۚ وَمَن یَتَّقِ ٱللَّهَ یُكَفِّرۡ عَنۡهُ سَیِّـَٔاتِهِۦ وَیُعۡظِمۡ لَهُۥۤ أَجۡرًا ۝٥", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "ذلك الذي ذُكِر من أمر الطلاق والعدة أمر الله الذي أنزله إليكم- أيها الناس-؛ لتعملوا به. ومن يَخَفِ الله فيتقه باجتناب معاصيه، وأداء فرائضه، يمح عنه ذنوبه، ويجزل له الثواب في الآخرة، ويدخله الجنة.", "isBasmala": false, "translation_en": "This is the ordinance of God, which He sent down to you. Whoever fears God-He will remit his sins, and will amplify his reward.", "translation_id": "Itulah perintah Allah yang diturunkan-Nya kepada kamu, dan barangsiapa yang bertakwa kepada Allah, niscaya Dia akan menghapus kesalahan-kesalahannya dan akan melipat gandakan pahala baginya.", "manzil": 7, "manzil_display": ""}], "559": [{"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 6, "text": "أَسۡكِنُوهُنَّ مِنۡ حَیۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَاۤرُّوهُنَّ لِتُضَیِّقُوا۟ عَلَیۡهِنَّۚ وَإِن كُنَّ أُو۟لَـٰتِ حَمۡلࣲ فَأَنفِقُوا۟ عَلَیۡهِنَّ حَتَّىٰ یَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُوا۟ بَیۡنَكُم بِمَعۡرُوفࣲۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥۤ أُخۡرَىٰ ۝٦", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "أسكنوا المطلقات من نسائكم في أثناء عدتهن مثل سكناكم على قدر سَعَتكم وطاقتكم، ولا تلحقوا بهن ضررًا؛ لتضيِّقوا عليهن في المسكن، إن كان نساؤكم المطلقات ذوات حَمْل، فأنفقوا عليهن في عدتهن حتى يضعن حَمْلهن، فإن أرضعن لكم أولادهن منكم بأجرة، فوفوهن أجورهن، وليأمر بعضكم بعضًا بما عرف من سماحة وطيب نفس، وإن لم تتفقوا على إرضاع الأم، فستُرضع للأب مرضعة أخرى غير الأم المطلقة.", "isBasmala": false, "translation_en": "Allow them to reside where you reside, according to your means, and do not harass them in order to make things difficult for them. If they are pregnant, spend on them until they give birth. And if they nurse your infant, give them their payment. And conduct your relation in amity. But if you disagree, then let another woman nurse him.", "translation_id": "Tempatkanlah mereka (para isteri) di mana kamu bertempat tinggal menurut kemampuanmu dan janganlah kamu menyusahkan mereka untuk menyempitkan (hati) mereka. Dan jika mereka (isteri-isteri yang sudah ditalaq) itu sedang hamil, maka berikanlah kepada mereka nafkahnya hingga mereka bersalin, kemudian jika mereka menyusukan (anak-anak)mu untukmu maka berikanlah kepada mereka upahnya, dan musyawarahkanlah di antara kamu (segala sesuatu) dengan baik; dan jika kamu menemui kesulitan maka perempuan lain boleh menyusukan (anak itu) untuknya.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 7, "text": "لِیُنفِقۡ ذُو سَعَةࣲ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَیۡهِ رِزۡقُهُۥ فَلۡیُنفِقۡ مِمَّاۤ ءَاتَىٰهُ ٱللَّهُۚ لَا یُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَاۤ ءَاتَىٰهَاۚ سَیَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرࣲ یُسۡرࣰا ۝٧", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "لينفق الزوج مما وسَّع الله عليه على زوجته المطلقة، وعلى ولده إذا كان الزوج ذا سَعَة في الرزق، ومن ضُيِّق عليه في الرزق وهو الفقير، فلينفق مما أعطاه الله من الرزق، لا يُكَلَّف الفقير مثل ما يُكَلَّف الغني، سيجعل الله بعد ضيق وشدة سَعَة وغنى.", "isBasmala": false, "translation_en": "The wealthy shall spend according to his means; and he whose resources are restricted shall spend according to what God has given him. God never burdens a soul beyond what He has given it. God will bring ease after hardship.", "translation_id": "Hendaklah orang yang mampu memberi nafkah menurut kemampuannya. Dan orang yang disempitkan rezekinya hendaklah memberi nafkah dari harta yang diberikan Allah kepadanya. Allah tidak memikulkan beban kepada seseorang melainkan sekedar apa yang Allah berikan kepadanya. Allah kelak akan memberikan kelapangan sesudah kesempitan.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 8, "text": "وَكَأَیِّن مِّن قَرۡیَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَـٰهَا حِسَابࣰا شَدِیدࣰا وَعَذَّبۡنَـٰهَا عَذَابࣰا نُّكۡرࣰا ۝٨", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "وكثير من القرى عصى أهلها أمر الله وأمر رسوله وتمادَوا في طغيانهم وكفرهم، فحاسبناهم على أعمالهم في الدنيا حسابًا شديدًا، وعذَّبناهم عذابًا عظيمًا منكرًا، فتجرَّعوا سوء عاقبة عتوهم وكفرهم، وكان عاقبة كفرهم هلاكًا وخسرانًا لا خسران بعده.", "isBasmala": false, "translation_en": "How many a town defied the command of its Lord and His messengers? So We held it strictly accountable, and We punished it with a dreadful punishment.", "translation_id": "Dan berapalah banyaknya (penduduk) negeri yang mendurhakai perintah Tuhan mereka dan Rasul-rasul-Nya, maka Kami hisab penduduk negeri itu dengan hisab yang keras, dan Kami azab mereka dengan azab yang mengerikan.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 9, "text": "فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَـٰقِبَةُ أَمۡرِهَا خُسۡرًا ۝٩", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "وكثير من القرى عصى أهلها أمر الله وأمر رسوله وتمادَوا في طغيانهم وكفرهم، فحاسبناهم على أعمالهم في الدنيا حسابًا شديدًا، وعذَّبناهم عذابًا عظيمًا منكرًا، فتجرَّعوا سوء عاقبة عتوهم وكفرهم، وكان عاقبة كفرهم هلاكًا وخسرانًا لا خسران بعده.", "isBasmala": false, "translation_en": "It tasted the result of its decisions, and the outcome of its decisions was perdition.", "translation_id": "Maka mereka merasakan akibat yang buruk dari perbuatannya, dan adalah akibat perbuatan mereka kerugian yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 10, "text": "أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابࣰا شَدِیدࣰاۖ فَٱتَّقُوا۟ ٱللَّهَ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ ٱلَّذِینَ ءَامَنُوا۟ۚ قَدۡ أَنزَلَ ٱللَّهُ إِلَیۡكُمۡ ذِكۡرࣰا ۝١٠", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "أعدَّ الله لهؤلاء القوم الذين طغَوا، وخالفوا أمره وأمر رسله، عذابًا بالغ الشدة، فخافوا الله واحذروا سخطه يا أصحاب العقول الراجحة الذين صدَّقوا الله ورسله وعملوا بشرعه. قد أنزل الله إليكم- أيها المؤمنون- ذكرًا يذكركم به، وينبهكم على حظكم من الإيمان بالله والعمل بطاعته. وهذا الذكر هو الرسول يقرأ عليكم آيات الله موضحات لكم الحق من الباطل؛ كي يخرج الذين صدقوا الله ورسوله، وعملوا بما أمرهم الله به وأطاعوه من ظلمات الكفر إلى نور الإيمان، ومن يؤمن بالله ويعمل عملا صالحًا، يدخله جنات تجري من تحت أشجارها الأنهار، ماكثين فيها ابدًا، قد أحسن الله للمؤمن الصالح رزقه في الجنة.", "isBasmala": false, "translation_en": "God has prepared for them a severe retribution. So beware of God, O you who possess intellect and have faith. God has sent down to you a Reminder.", "translation_id": "Allah menyediakan bagi mereka azab yang keras, maka bertakwalah kepada Allah hai orang-orang yang mempunyai akal; (yaitu) orang-orang yang beriman. Sesungguhnya Allah telah menurunkan peringatan kepadamu,", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 11, "text": "رَّسُولࣰا یَتۡلُوا۟ عَلَیۡكُمۡ ءَایَـٰتِ ٱللَّهِ مُبَیِّنَـٰتࣲ لِّیُخۡرِجَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَمَن یُؤۡمِنۢ بِٱللَّهِ وَیَعۡمَلۡ صَـٰلِحࣰا یُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا ۝١١", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "أعدَّ الله لهؤلاء القوم الذين طغَوا، وخالفوا أمره وأمر رسله، عذابًا بالغ الشدة، فخافوا الله واحذروا سخطه يا أصحاب العقول الراجحة الذين صدَّقوا الله ورسله وعملوا بشرعه. قد أنزل الله إليكم- أيها المؤمنون- ذكرًا يذكركم به، وينبهكم على حظكم من الإيمان بالله والعمل بطاعته. وهذا الذكر هو الرسول يقرأ عليكم آيات الله موضحات لكم الحق من الباطل؛ كي يخرج الذين صدقوا الله ورسوله، وعملوا بما أمرهم الله به وأطاعوه من ظلمات الكفر إلى نور الإيمان، ومن يؤمن بالله ويعمل عملا صالحًا، يدخله جنات تجري من تحت أشجارها الأنهار، ماكثين فيها ابدًا، قد أحسن الله للمؤمن الصالح رزقه في الجنة.", "isBasmala": false, "translation_en": "A messenger who recites to you God's Verses, clear and distinct, that he may bring those who believe and work righteousness from darkness into light. Whoever believes in God and acts with integrity, He will admit him into gardens beneath which rivers flow, therein to abide forever. God has given him an excellent provision.", "translation_id": "(Dan mengutus) seorang Rasul yang membacakan kepadamu ayat-ayat Allah yang menerangkan (bermacam-macam hukum) supaya Dia mengeluarkan orang-orang yang beriman dan beramal saleh dari kegelapan kepada cahaya. Dan barangsiapa beriman kepada Allah dan mengerjakan amal yang saleh niscaya Allah akan memasukkannya ke dalam surga-surga yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya selama-lamanya. Sesungguhnya Allah memberikan rezeki yang baik kepadanya.", "manzil": 7, "manzil_display": ""}, {"sura": 65, "sura_name": "الطلاق", "revelation": "Madaniyah", "aya": 12, "text": "ٱللَّهُ ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰتࣲ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ یَتَنَزَّلُ ٱلۡأَمۡرُ بَیۡنَهُنَّ لِتَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَیۡءٍ عِلۡمَۢا ۝١٢", "juz": 28, "hizb": "(*½ ح 56*)", "tafsir": "الله وحده هو الذي خلق سبع سموات، وخلق سبعًا من الأرَضين، وأنزل الأمر مما أوحاه الله إلى رسله وما يدبِّر به خلقه بين السموات والأرض؛ لتعلموا- أيها الناس- أن الله على كل شيء قدير لا يعجزه شيء، وأن الله قد أحاط بكل شيء علمًا، فلا يخرج شيء عن علمه وقدرته.", "isBasmala": false, "translation_en": "God is He Who created seven heavens, and their like of earth. The command descends through them, so that you may know that God is Capable of everything, and that God Encompasses everything in knowledge.", "translation_id": "Allah-lah yang menciptakan tujuh langit dan seperti itu pula bumi. Perintah Allah berlaku padanya, agar kamu mengetahui bahwasanya Allah Maha Kuasa atas segala sesuatu, dan sesungguhnya Allah ilmu-Nya benar-benar meliputi segala sesuatu.", "manzil": 7, "manzil_display": ""}], "560": [{"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 28, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 1, "text": "۞ یَـٰۤأَیُّهَا ٱلنَّبِیُّ لِمَ تُحَرِّمُ مَاۤ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِی مَرۡضَاتَ أَزۡوَ ٰجِكَۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ ۝١", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "يا أيها النبي لِمَ تمنع نفسك عن الحلال الذي أحله الله لك، تبتغي إرضاء زوجاتك؟ والله غفور لك، رحيم بك.", "isBasmala": false, "translation_en": "O prophet! Why do you prohibit what God has permitted for you, seeking to please your wives? God is Forgiving and Merciful.", "translation_id": "Hai Nabi, mengapa kamu mengharamkan apa yang Allah halalkan bagimu; kamu mencari kesenangan hati isteri-isterimu? Dan Allah Maha Pengampun lagi Maha Penyayang", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 2, "text": "قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَیۡمَـٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ ۝٢", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "قد شرع الله لكم -أيها المؤمنون- تحليل أيمانكم بأداء الكفارة عنها، وهي: إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة، فمن لم يجد فصيام ثلاثة أيام. والله ناصركم ومتولي أموركم، وهو العليم بما يصلحكم فيشرعه لكم، الحكيم في أقواله وأفعاله.", "isBasmala": false, "translation_en": "God has decreed for you the dissolution of your oaths. God is your Master. He is the All-Knowing, the Most Wise.", "translation_id": "Sesungguhnya Allah telah mewajibkan kepadamu sekalian membebaskan diri dari sumpahmu dan Allah adalah Pelindungmu dan Dia Maha Mengetahui lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 3, "text": "وَإِذۡ أَسَرَّ ٱلنَّبِیُّ إِلَىٰ بَعۡضِ أَزۡوَ ٰجِهِۦ حَدِیثࣰا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَیۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضࣲۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَـٰذَاۖ قَالَ نَبَّأَنِیَ ٱلۡعَلِیمُ ٱلۡخَبِیرُ ۝٣", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "وإذ أسرَّ النبي إلى زوجته حفصة - رضي الله عنها- حديثا، فلما أخبرت به عائشة رضي الله عنها، وأطلعه الله على إفشائها سرَّه، أعلم حفصة بعض ما أخبرت به، وأعرض عن إعلامها بعضه تكرما، فلما أخبرها بما أفشت من الحديث، قالت: مَن أخبرك بهذا؟ قال: أخبرني به الله العليم الخبير، الذي لا تخفى عليه خافية.", "isBasmala": false, "translation_en": "The Prophet told something in confidence to one of his wives. But when she disclosed it, and God made it known to him; he communicated part of it, and he avoided another part. Then, when he informed her of it, she said, \"Who informed you of this?\" He said, \"The All-Knowing, the All-Informed, informed me.\"", "translation_id": "Dan ingatlah ketika Nabi membicarakan secara rahasia kepada salah seorang isterinya (Hafsah) suatu peristiwa. Maka tatkala (Hafsah) menceritakan peristiwa itu (kepada Aisyah) dan Allah memberitahukan hal itu (pembicaraan Hafsah dan Aisyah) kepada Muhammad lalu Muhammad memberitahukan sebagian (yang diberitakan Allah kepadanya) dan menyembunyikan sebagian yang lain (kepada Hafsah). Maka tatkala (Muhammad) memberitahukan pembicaraan (antara Hafsah dan Aisyah) lalu (Hafsah) bertanya: \"Siapakah yang telah memberitahukan hal ini kepadamu?\" Nabi menjawab: \"Telah diberitahukan kepadaku oleh Allah yang Maha Mengetahui lagi Maha Mengenal\".", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 4, "text": "إِن تَتُوبَاۤ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَـٰهَرَا عَلَیۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِیلُ وَصَـٰلِحُ ٱلۡمُؤۡمِنِینَۖ وَٱلۡمَلَـٰۤىِٕكَةُ بَعۡدَ ذَ ٰلِكَ ظَهِیرٌ ۝٤", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "إن ترجعا (حفصة وعائشة) إلى الله فقد وُجد منكما ما يوجب التوبة حيث مالت قلوبكما إلى محبة ما كرهه رسول الله صلى الله عليه وسلم، من إفشاء سرِّه، وإن تتعاونا عليه بما يسوءه، فإن الله وليه وناصره، وجبريل وصالح المؤمنين، والملائكة بعد نصرة الله أعوان له ونصراء على مَن يؤذيه ويعاديه.", "isBasmala": false, "translation_en": "If you repent to God, then your hearts have listened. But if you band together against him, then God is his Ally, as is Gabriel, and the righteous believers. In addition, the angels will assist him.", "translation_id": "Jika kamu berdua bertaubat kepada Allah, maka sesungguhnya hati kamu berdua telah condong (untuk menerima kebaikan); dan jika kamu berdua bantu-membantu menyusahkan Nabi, maka sesungguhnya Allah adalah Pelindungnya dan (begitu pula) Jibril dan orang-orang mukmin yang baik; dan selain dari itu malaikat-malaikat adalah penolongnya pula.", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 5, "text": "عَسَىٰ رَبُّهُۥۤ إِن طَلَّقَكُنَّ أَن یُبۡدِلَهُۥۤ أَزۡوَ ٰجًا خَیۡرࣰا مِّنكُنَّ مُسۡلِمَـٰتࣲ مُّؤۡمِنَـٰتࣲ قَـٰنِتَـٰتࣲ تَـٰۤىِٕبَـٰتٍ عَـٰبِدَ ٰتࣲ سَـٰۤىِٕحَـٰتࣲ ثَیِّبَـٰتࣲ وَأَبۡكَارࣰا ۝٥", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "عسى ربُّه إن طلقكنَّ- أيتها الزوجات- أن يزوِّجه بدلا منكن زوجات خاضعات لله بالطاعة، مؤمنات بالله ورسوله، مطيعات لله، راجعات إلى ما يحبه الله مِن طاعته، كثيرات العبادة له، صائمات، منهنَّ الثيِّبات، ومنهن الأبكار.", "isBasmala": false, "translation_en": "Perhaps, if he divorces you, his Lord will give him in exchange wives better than you: submissive, believing, obedient, penitent, devout, fasting-previously married, or virgins.", "translation_id": "Jika Nabi menceraikan kamu, boleh jadi Tuhannya akan memberi ganti kepadanya dengan isteri yang lebih baik daripada kamu, yang patuh, yang beriman, yang taat, yang bertaubat, yang mengerjakan ibadat, yang berpuasa, yang janda dan yang perawan.", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 6, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ قُوۤا۟ أَنفُسَكُمۡ وَأَهۡلِیكُمۡ نَارࣰا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَیۡهَا مَلَـٰۤىِٕكَةٌ غِلَاظࣱ شِدَادࣱ لَّا یَعۡصُونَ ٱللَّهَ مَاۤ أَمَرَهُمۡ وَیَفۡعَلُونَ مَا یُؤۡمَرُونَ ۝٦", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، احفظوا أنفسكم بفعل ما أمركم الله به وترك ما نهاكم عنه، واحفظوا أهليكم بما تحفظون به أنفسكم من نار وقودها الناس والحجارة، يقوم على تعذيب أهلها ملائكة أقوياء قساة في معاملاتهم، لا يخالفون الله في أمره، وينفذون ما يؤمرون به.", "isBasmala": false, "translation_en": "O you who believe! Protect yourselves and your families from a Fire, whose fuel is people and stones. Over it are angels, fierce and powerful. They never disobey God in anything He commands them, and they carry out whatever they are commanded.", "translation_id": "Hai orang-orang yang beriman, peliharalah dirimu dan keluargamu dari api neraka yang bahan bakarnya adalah manusia dan batu; penjaganya malaikat-malaikat yang kasar, keras, dan tidak mendurhakai Allah terhadap apa yang diperintahkan-Nya kepada mereka dan selalu mengerjakan apa yang diperintahkan.", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 7, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ كَفَرُوا۟ لَا تَعۡتَذِرُوا۟ ٱلۡیَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ ۝٧", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "ويقال للذين جحدوا أن الله هو الإله الحق وكفروا به عند إدخالهم النار: لا تلتمسوا المعاذير في هذا اليوم؛ إنما تعطون جزاء الذي كنتم تعملونه في الدنيا.", "isBasmala": false, "translation_en": "O you who disbelieved! Make no excuses today. You are being repaid for what you used to do.", "translation_id": "Hai orang-orang kafir, janganlah kamu mengemukakan uzur pada hari ini. Sesungguhnya kamu hanya diberi balasan menurut apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}], "561": [{"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 8, "text": "یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ تُوبُوۤا۟ إِلَى ٱللَّهِ تَوۡبَةࣰ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن یُكَفِّرَ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَیُدۡخِلَكُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ یَوۡمَ لَا یُخۡزِی ٱللَّهُ ٱلنَّبِیَّ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥۖ نُورُهُمۡ یَسۡعَىٰ بَیۡنَ أَیۡدِیهِمۡ وَبِأَیۡمَـٰنِهِمۡ یَقُولُونَ رَبَّنَاۤ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَاۤۖ إِنَّكَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ ۝٨", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "يا أيها الذين صدَّقوا الله ورسوله وعملوا بشرعه، ارجعوا عن ذنوبكم إلى طاعة الله رجوعا لا معصية بعده، عسى ربكم أن يمحو عنكم سيئات أعمالكم، وأن يدخلكم جنات تجري من تحت قصورها الأنهار، يوم لا يخزي الله النبي والذين آمنوا معه، ولا يعذبهم، بل يُعلي شأنهم، نور هؤلاء يسير أمامهم وبأيمانهم، يقولون: ربنا أتمم لنا نورنا حتى نجوز الصراط، ونهتدي إلى الجنة، واعف عنَّا وتجاوز عن ذنوبنا واسترها علينا، إنك على كل شيء قدير.", "isBasmala": false, "translation_en": "O you who believe! Repent to God with sincere repentance. Perhaps your Lord will remit your sins, and admit you into gardens beneath which rivers flow, on the Day when God will not disappoint the Prophet and those who believed with him. Their light streaming before them, and to their right, they will say, \"Our Lord, complete our light for us, and forgive us; You are capable of all things.\"", "translation_id": "Hai orang-orang yang beriman, bertaubatlah kepada Allah dengan taubatan nasuhaa (taubat yang semurni-murninya). Mudah-mudahan Rabbmu akan menutupi kesalahan-kesalahanmu dan memasukkanmu ke dalam jannah yang mengalir di bawahnya sungai-sungai, pada hari ketika Allah tidak menghinakan Nabi dan orang-orang mukmin yang bersama dia; sedang cahaya mereka memancar di hadapan dan di sebelah kanan mereka, sambil mereka mengatakan: \"Ya Rabb kami, sempurnakanlah bagi kami cahaya kami dan ampunilah kami; Sesungguhnya Engkau Maha Kuasa atas segala sesuatu\".", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 9, "text": "یَـٰۤأَیُّهَا ٱلنَّبِیُّ جَـٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَـٰفِقِینَ وَٱغۡلُظۡ عَلَیۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ ۝٩", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "يا أيها النبي جاهد الذين أظهروا الكفر وأعلنوه، وقاتلهم بالسيف، وجاهد الذين أبطنوا الكفر وأخفوه بالحجة وإقامة الحدود وشعائر الدين، واستعمل مع الفريقين الشدة والخشونة في جهادهما، ومسكنهم الذي يصيرون إليه في الآخرة جهنم، وقَبُح ذلك المرجع الذي يرجعون إليه.", "isBasmala": false, "translation_en": "O prophet! Strive hard against the disbelievers and the hypocrites, and be stern with them. Their abode is Hell. What a miserable destination!", "translation_id": "Hai Nabi, perangilah orang-orang kafir dan orang-orang munafik dan bersikap keraslah terhadap mereka. Tempat mereka adalah jahannam dan itu adalah seburuk-buruknya tempat kembali.", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 10, "text": "ضَرَبَ ٱللَّهُ مَثَلࣰا لِّلَّذِینَ كَفَرُوا۟ ٱمۡرَأَتَ نُوحࣲ وَٱمۡرَأَتَ لُوطࣲۖ كَانَتَا تَحۡتَ عَبۡدَیۡنِ مِنۡ عِبَادِنَا صَـٰلِحَیۡنِ فَخَانَتَاهُمَا فَلَمۡ یُغۡنِیَا عَنۡهُمَا مِنَ ٱللَّهِ شَیۡـࣰٔا وَقِیلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّ ٰخِلِینَ ۝١٠", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "ضرب الله مثلا لحال الكفرة - في مخالطتهم المسلمين وقربهم منهم ومعاشرتهم لهم، وأن ذلك لا ينفعهم لكفرهم بالله- بحال زوجة نبي الله نوح، وزوجة نبي الله لوط: حيث كانتا في عصمة عبدَين من عبادنا صالحين، فوقعت منهما الخيانة لهما في الدين، فقد كانتا كافرتين، فلم يدفع هذان الرسولان عن زوجتيهما من عذاب الله شيئًا، وقيل للزوجتين: ادخلا النار مع الداخلين فيها. وفي ضرب هذا المثل دليل على أن القرب من الأنبياء، والصالحين، لا يفيد شيئا مع العمل السيِّئ.", "isBasmala": false, "translation_en": "God illustrates an example of those who disbelieve: the wife of Noah and the wife of Lot. They were under two of Our righteous servants, but they betrayed them. They availed them nothing against God, and it was said, \"Enter the Fire with those who are entering.\"", "translation_id": "Allah membuat isteri Nuh dan isteri Luth sebagai perumpamaan bagi orang-orang kafir. Keduanya berada di bawah pengawasan dua orang hamba yang saleh di antara hamba-hamba Kami; lalu kedua isteri itu berkhianat kepada suaminya (masing-masing), maka suaminya itu tiada dapat membantu mereka sedikitpun dari (siksa) Allah; dan dikatakan (kepada keduanya): \"Masuklah ke dalam jahannam bersama orang-orang yang masuk (jahannam)\".", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 11, "text": "وَضَرَبَ ٱللَّهُ مَثَلࣰا لِّلَّذِینَ ءَامَنُوا۟ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِی عِندَكَ بَیۡتࣰا فِی ٱلۡجَنَّةِ وَنَجِّنِی مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِی مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ ۝١١", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "وضرب الله مثلا لحال المؤمنين- الذين صدَّقوا الله، وعبدوه وحده، وعملوا بشرعه، وأنهم لا تضرهم مخالطة الكافرين في معاملتهم- بحال زوجة فرعون التي كانت في عصمة أشد الكافرين بالله، وهي مؤمنة بالله، حين قالت: رب ابْنِ لي دارًا عندك في الجنة، وأنقذني من سلطان فرعون وفتنته، ومما يصدر عنه من أعمال الشر، وأنقذني من القوم التابعين له في الظلم والضلال، ومن عذابهم.", "isBasmala": false, "translation_en": "And God illustrates an example of those who believe: the wife of Pharaoh, when she said, \"My Lord, build for me, with you, a house in Paradise, and save me from Pharaoh and his works, and save me from the wrongdoing people.\"", "translation_id": "Dan Allah membuat isteri Fir'aun perumpamaan bagi orang-orang yang beriman, ketika ia berkata: \"Ya Rabbku, bangunkanlah untukku sebuah rumah di sisi-Mu dalam firdaus, dan selamatkanlah aku dari Fir'aun dan perbuatannya, dan selamatkanlah aku dari kaum yang zhalim.", "manzil": 7, "manzil_display": ""}, {"sura": 66, "sura_name": "التحريم", "revelation": "Madaniyah", "aya": 12, "text": "وَمَرۡیَمَ ٱبۡنَتَ عِمۡرَ ٰنَ ٱلَّتِیۤ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِیهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَـٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَـٰنِتِینَ ۝١٢", "juz": 28, "hizb": "(*¾ ح 56*)", "tafsir": "وضرب الله مثلا للذين آمنوا مريم بنت عمران التي حفظت فرجها، وصانته عن الزنى، فأمر الله تعالى جبريل عليه السلام أن ينفخ في جيب قميصها، فوصلت النفخة إلى رحمها، فحملت بعيسى عليه السلام، وصدَّقت بكلمات ربها، وعملت بشرائعه التي شرعها لعباده، وكتبه المنزلة على رسله، وكانت من المطيعين له.", "isBasmala": false, "translation_en": "And Mary, the daughter of Imran, who guarded her womb, and so We breathed into her of Our Spirit; and she believed in the truth of her Lord's Words and His Books, and was one of the devout.", "translation_id": "dan (ingatlah) Maryam binti Imran yang memelihara kehormatannya, maka Kami tiupkan ke dalam rahimnya sebagian dari ruh (ciptaan) Kami, dan dia membenarkan kalimat Rabbnya dan Kitab-Kitab-Nya, dan dia adalah termasuk orang-orang yang taat.", "manzil": 7, "manzil_display": ""}], "562": [{"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 1, "text": "۞ تَبَـٰرَكَ ٱلَّذِی بِیَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ ۝١", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "تكاثر خير الله وبرُّه على جميع خلقه، الذي بيده مُلك الدنيا والآخرة وسلطانهما، نافذ فيهما أمره وقضاؤه، وهو على كل شيء قدير. ويستفاد من الآية ثبوت صفة اليد لله سبحانه وتعالى على ما يليق بجلاله.", "isBasmala": false, "translation_en": "Blessed is He in whose hand is the sovereignty, and Who has power over everything.", "translation_id": "Maha Suci Allah Yang di tangan-Nya-lah segala kerajaan, dan Dia Maha Kuasa atas segala sesuatu,", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 2, "text": "ٱلَّذِی خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَیَوٰةَ لِیَبۡلُوَكُمۡ أَیُّكُمۡ أَحۡسَنُ عَمَلࣰاۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡغَفُورُ ۝٢", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "الذي خلق الموت والحياة؛ ليختبركم - أيها الناس-: أيكم خيرٌ عملا وأخلصه؟ وهو العزيز الذي لا يعجزه شيء، الغفور لمن تاب من عباده. وفي الآية ترغيب في فعل الطاعات، وزجر عن اقتراف المعاصي.", "isBasmala": false, "translation_en": "He who created death and life-to test you-as to which of you is better in conduct. He is the Almighty, the Forgiving.", "translation_id": "Yang menjadikan mati dan hidup, supaya Dia menguji kamu, siapa di antara kamu yang lebih baik amalnya. Dan Dia Maha Perkasa lagi Maha Pengampun,", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 3, "text": "ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰتࣲ طِبَاقࣰاۖ مَّا تَرَىٰ فِی خَلۡقِ ٱلرَّحۡمَـٰنِ مِن تَفَـٰوُتࣲۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورࣲ ۝٣", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "الذي خلق سبع سموات متناسقة، بعضها فوق بعض، ما ترى في خلق الرحمن- أيها الناظر- من اختلاف ولا تباين، فأعد النظر إلى السماء: هل ترى فيها مِن شقوق أو صدوع؟", "isBasmala": false, "translation_en": "He who created seven heavens in layers. You see no discrepancy in the creation of the Compassionate. Look again. Can you see any cracks?", "translation_id": "Yang telah menciptakan tujuh langit berlapis-lapis. Kamu sekali-kali tidak melihat pada ciptaan Tuhan Yang Maha Pemurah sesuatu yang tidak seimbang. Maka lihatlah berulang-ulang, adakah kamu lihat sesuatu yang tidak seimbang?", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 4, "text": "ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَیۡنِ یَنقَلِبۡ إِلَیۡكَ ٱلۡبَصَرُ خَاسِئࣰا وَهُوَ حَسِیرࣱ ۝٤", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "ثم أعد النظر مرة بعد مرة، يرجع إليك البصر ذليلا صاغرًا عن أن يرى نقصًا، وهو متعب كليل.", "isBasmala": false, "translation_en": "Then look again, and again, and your sight will return to you dazzled and exhausted.", "translation_id": "Kemudian pandanglah sekali lagi niscaya penglihatanmu akan kembali kepadamu dengan tidak menemukan sesuatu cacat dan penglihatanmu itupun dalam keadaan payah.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 5, "text": "وَلَقَدۡ زَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِمَصَـٰبِیحَ وَجَعَلۡنَـٰهَا رُجُومࣰا لِّلشَّیَـٰطِینِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِیرِ ۝٥", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "ولقد زيَّنا السماء القريبة التي تراها العيون بنجوم عظيمة مضيئة، وجعلناها شهبًا محرقة لمسترقي السمع من الشياطين، وأعتدنا لهم في الآخرة عذاب النار الموقدة يقاسون حرها.", "isBasmala": false, "translation_en": "We have adorned the lower heaven with lanterns, and made them missiles against the devils; and We have prepared for them the punishment of the Blaze.", "translation_id": "Sesungguhnya Kami telah menghiasi langit yang dekat dengan bintang-bintang, dan Kami jadikan bintang-bintang itu alat-alat pelempar syaitan, dan Kami sediakan bagi mereka siksa neraka yang menyala-nyala.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 6, "text": "وَلِلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِیرُ ۝٦", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "وللكافرين بخالقهم عذاب جهنم، وساء المرجع لهم جهنم.", "isBasmala": false, "translation_en": "For those who reject their Lord, there is the torment of Hell. What an evil destination!", "translation_id": "Dan orang-orang yang kafir kepada Tuhannya, memperoleh azab Jahannam. Dan itulah seburuk-buruk tempat kembali.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 7, "text": "إِذَاۤ أُلۡقُوا۟ فِیهَا سَمِعُوا۟ لَهَا شَهِیقࣰا وَهِیَ تَفُورُ ۝٧", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "إذا طُرح هؤلاء الكافرون في جهنم سمعوا لها صوتًا شديدًا منكرًا، وهي تغلي غليانًا شديدًا.", "isBasmala": false, "translation_en": "When they are thrown into it, they will hear it roaring, as it seethes.", "translation_id": "Apabila mereka dilemparkan ke dalamnya mereka mendengar suara neraka yang mengerikan, sedang neraka itu menggelegak,", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 8, "text": "تَكَادُ تَمَیَّزُ مِنَ ٱلۡغَیۡظِۖ كُلَّمَاۤ أُلۡقِیَ فِیهَا فَوۡجࣱ سَأَلَهُمۡ خَزَنَتُهَاۤ أَلَمۡ یَأۡتِكُمۡ نَذِیرࣱ ۝٨", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "تكاد جهنم تتمزق مِن شدة غضبها على الكفار، كلما طُرح فيها جماعة من الناس سألهم الموكلون بأمرها على سبيل التوبيخ: ألم يأتكم في الدنيا رسول يحذركم هذا العذاب الذي أنتم فيه؟", "isBasmala": false, "translation_en": "It almost bursts with fury. Every time a batch is thrown into it, its keepers will ask them, \"Has no warner come to you?\"", "translation_id": "hampir-hampir (neraka) itu terpecah-pecah lantaran marah. Setiap kali dilemparkan ke dalamnya sekumpulan (orang-orang kafir), penjaga-penjaga (neraka itu) bertanya kepada mereka: \"Apakah belum pernah datang kepada kamu (di dunia) seorang pemberi peringatan?\"", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 9, "text": "قَالُوا۟ بَلَىٰ قَدۡ جَاۤءَنَا نَذِیرࣱ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَیۡءٍ إِنۡ أَنتُمۡ إِلَّا فِی ضَلَـٰلࣲ كَبِیرࣲ ۝٩", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "أجابوهم قائلين: بلى قد جاءنا رسول مِن عند الله وحذَّرنا، فكذَّبناه، وقلنا فيما جاء به من الآيات: ما نزَّل الله على أحد من البشر شيئًا، ما أنتم - أيها الرسل- إلا في ذهاب بعيد عن الحق.", "isBasmala": false, "translation_en": "They will say, \"Yes, a warner did come to us, but we disbelieved, and said, 'God did not send down anything; you are very much mistaken.'\"", "translation_id": "Mereka menjawab: \"Benar ada\", sesungguhnya telah datang kepada kami seorang pemberi peringatan, maka kami mendustakan(nya) dan kami katakan: \"Allah tidak menurunkan sesuatupun; kamu tidak lain hanyalah di dalam kesesatan yang besar\".", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 10, "text": "وَقَالُوا۟ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِیۤ أَصۡحَـٰبِ ٱلسَّعِیرِ ۝١٠", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "وقالوا معترفين: لو كنا نسمع سماع مَن يطلب الحق، أو نفكر فيما نُدْعى إليه، ما كنا في عداد أهل النار.", "isBasmala": false, "translation_en": "And they will say, \"Had we listened or reasoned, we would not have been among the inmates of the Blaze.\"", "translation_id": "Dan mereka berkata: \"Sekiranya kami mendengarkan atau memikirkan (peringatan itu) niscaya tidaklah kami termasuk penghuni-penghuni neraka yang menyala-nyala\".", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 11, "text": "فَٱعۡتَرَفُوا۟ بِذَنۢبِهِمۡ فَسُحۡقࣰا لِّأَصۡحَـٰبِ ٱلسَّعِیرِ ۝١١", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "فاعترفوا بتكذيبهم وكفرهم الذي استحقوا به عذاب النار، فبعدًا لأهل النار عن رحمة الله.", "isBasmala": false, "translation_en": "So they will acknowledge their sins. So away with the inmates of the Blaze.", "translation_id": "Mereka mengakui dosa mereka. Maka kebinasaanlah bagi penghuni-penghuni neraka yang menyala-nyala.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 12, "text": "إِنَّ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرࣱ ۝١٢", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "إن الذين يخافون ربهم، فيعبدونه، ولا يعصونه وهم غائبون عن أعين الناس، ويخشون العذاب في الآخرة قبل معاينته، لهم عفو من الله عن ذنوبهم، وثواب عظيم وهو الجنة.", "isBasmala": false, "translation_en": "As for those who fear their Lord in secret-for them is forgiveness and a great reward.", "translation_id": "Sesungguhnya orang-orang yang takut kepada Tuhannya Yang tidak nampak oleh mereka, mereka akan memperoleh ampunan dan pahala yang besar.", "manzil": 7, "manzil_display": ""}], "563": [{"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 13, "text": "وَأَسِرُّوا۟ قَوۡلَكُمۡ أَوِ ٱجۡهَرُوا۟ بِهِۦۤۖ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ ۝١٣", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "وأخفوا قولكم- أيها الناس- في أي أمر من أموركم أو أعلنوه، فهما عند الله سواء، إنه سبحانه عليم بمضمرات الصدور، فكيف تخفى عليه أقوالكم وأعمالكم؟", "isBasmala": false, "translation_en": "Whether you keep your words secret, or declare them-He is Aware of the inner thoughts.", "translation_id": "Dan rahasiakanlah perkataanmu atau lahirkanlah; sesungguhnya Dia Maha Mengetahui segala isi hati.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 14, "text": "أَلَا یَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِیفُ ٱلۡخَبِیرُ ۝١٤", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "ألا يعلم ربُّ العالمين خَلْقه وشؤونهم، وهو الذي خَلَقهم وأتقن خَلْقَهُمْ وأحسنه؟ وهو اللطيف بعباده، الخبير بهم وبأعمالهم.", "isBasmala": false, "translation_en": "Would He not know, He Who created? He is the Refined, the Expert.", "translation_id": "Apakah Allah Yang menciptakan itu tidak mengetahui (yang kamu lahirkan atau rahasiakan); dan Dia Maha Halus lagi Maha Mengetahui?", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 15, "text": "هُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولࣰا فَٱمۡشُوا۟ فِی مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزۡقِهِۦۖ وَإِلَیۡهِ ٱلنُّشُورُ ۝١٥", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "الله وحده هو الذي جعل لكم الأرض سهلة ممهدة تستقرون عليها، فامشوا في نواحيها وجوانبها، وكلوا من رزق الله الذي يخرجه لكم منها، وإليه وحده البعث من قبوركم للحساب والجزاء. وفي الآية إيماء إلى طلب الرزق والمكاسب، وفيها دلالة على أن الله هو الإله الحق وحده لا شريك له، وعلى قدرته، والتذكير بنعمه، والتحذير من الركون إلى الدنيا.", "isBasmala": false, "translation_en": "It is He who made the earth manageable for you, so travel its regions, and eat of His provisions. To Him is the Resurgence.", "translation_id": "Dialah Yang menjadikan bumi itu mudah bagi kamu, maka berjalanlah di segala penjurunya dan makanlah sebahagian dari rezeki-Nya. Dan hanya kepada-Nya-lah kamu (kembali setelah) dibangkitkan.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 16, "text": "ءَأَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِیَ تَمُورُ ۝١٦", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "هل أمنتم- يا كفار \"مكة\"- الله الذي فوق السماء أن يخسف بكم الأرض، فإذا هي تضطرب بكم حتى تهلكوا؟ هل أمنتم الله الذي فوق السماء أن يرسل عليكم ريحا ترجمكم بالحجارة الصغيرة، فستعلمون- أيها الكافرون- كيف تحذيري لكم إذا عاينتم العذاب؟ ولا ينفعكم العلم حين ذلك. وفي الآية إثبات العلو لله تعالى، كما يليق بجلاله سبحانه.", "isBasmala": false, "translation_en": "Are you confident that the One in heaven will not cause the earth to collapse beneath you as it spins?", "translation_id": "Apakah kamu merasa aman terhadap Allah yang (berkuasa) di langit bahwa Dia akan menjungkir balikkan bumi bersama kamu, sehingga dengan tiba-tiba bumi itu bergoncang?,", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 17, "text": "أَمۡ أَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یُرۡسِلَ عَلَیۡكُمۡ حَاصِبࣰاۖ فَسَتَعۡلَمُونَ كَیۡفَ نَذِیرِ ۝١٧", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "هل أمنتم- يا كفار \"مكة\"- الله الذي فوق السماء أن يخسف بكم الأرض، فإذا هي تضطرب بكم حتى تهلكوا؟ هل أمنتم الله الذي فوق السماء أن يرسل عليكم ريحا ترجمكم بالحجارة الصغيرة، فستعلمون- أيها الكافرون- كيف تحذيري لكم إذا عاينتم العذاب؟ ولا ينفعكم العلم حين ذلك. وفي الآية إثبات العلو لله تعالى، كما يليق بجلاله سبحانه.", "isBasmala": false, "translation_en": "Or are you confident that the One in Heaven will not unleash against you a violent storm? Then you will know what My warning is like.", "translation_id": "atau apakah kamu merasa aman terhadap Allah yang (berkuasa) di langit bahwa Dia akan mengirimkan badai yang berbatu. Maka kelak kamu akan mengetahui bagaimana (akibat mendustakan) peringatan-Ku?", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 18, "text": "وَلَقَدۡ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَكَیۡفَ كَانَ نَكِیرِ ۝١٨", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "ولقد كذَّب الذين كانوا قبل كفار \"مكة\" كقوم نوح وعاد وثمود رسلهم، فكيف كان إنكاري عليهم، وتغييري ما بهم من نعمة بإنزال العذاب بهم وإهلاكهم؟", "isBasmala": false, "translation_en": "Those before them also denied the truth; and how was My disapproval?", "translation_id": "Dan sesungguhnya orang-orang yang sebelum mereka telah mendustakan (rasul-rasul-Nya). Maka alangkah hebatnya kemurkaan-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 19, "text": "أَوَ لَمۡ یَرَوۡا۟ إِلَى ٱلطَّیۡرِ فَوۡقَهُمۡ صَـٰۤفَّـٰتࣲ وَیَقۡبِضۡنَۚ مَا یُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَـٰنُۚ إِنَّهُۥ بِكُلِّ شَیۡءِۭ بَصِیرٌ ۝١٩", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "أغَفَل هؤلاء الكافرون، ولم ينظروا إلى الطير فوقهم، باسطات أجنحتها عند طيرانها في الهواء، ويضممنها إلى جُنوبها أحيانًا؟ ما يحفظها من الوقوع عند ذلك إلا الرحمن. إنه بكل شيء بصير لا يُرى في خلقه نقص ولا تفاوت. بل مَن هذا الذي هو في زعمكم- أيها الكافرون- حزب لكم ينصركم من غير الرحمن، إن أراد بكم سوءًا؟ ما الكافرون في زعمهم هذا إلا في خداع وضلال من الشيطان. بل مَن هذا الرازق المزعوم الذي يرزقكم إن أمسك الله رزقه ومنعه عنكم؟ بل استمر الكافرون في طغيانهم وضلالهم في معاندة واستكبار ونفور عن الحق، لا يسمعون له، ولا يتبعونه.", "isBasmala": false, "translation_en": "Have they not seen the birds above them, spreading their wings, and folding them? None holds them except the Compassionate. He is Perceiver of everything.", "translation_id": "Dan apakah mereka tidak memperhatikan burung-burung yang mengembangkan dan mengatupkan sayapnya di atas mereka? Tidak ada yang menahannya (di udara) selain Yang Maha Pemurah. Sesungguhnya Dia Maha Melihat segala sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 20, "text": "أَمَّنۡ هَـٰذَا ٱلَّذِی هُوَ جُندࣱ لَّكُمۡ یَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَـٰنِۚ إِنِ ٱلۡكَـٰفِرُونَ إِلَّا فِی غُرُورٍ ۝٢٠", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "أغَفَل هؤلاء الكافرون، ولم ينظروا إلى الطير فوقهم، باسطات أجنحتها عند طيرانها في الهواء، ويضممنها إلى جُنوبها أحيانًا؟ ما يحفظها من الوقوع عند ذلك إلا الرحمن. إنه بكل شيء بصير لا يُرى في خلقه نقص ولا تفاوت. بل مَن هذا الذي هو في زعمكم- أيها الكافرون- حزب لكم ينصركم من غير الرحمن، إن أراد بكم سوءًا؟ ما الكافرون في زعمهم هذا إلا في خداع وضلال من الشيطان. بل مَن هذا الرازق المزعوم الذي يرزقكم إن أمسك الله رزقه ومنعه عنكم؟ بل استمر الكافرون في طغيانهم وضلالهم في معاندة واستكبار ونفور عن الحق، لا يسمعون له، ولا يتبعونه.", "isBasmala": false, "translation_en": "Or who is this who is a force for you to protect you against the Compassionate? The disbelievers are in nothing but delusion.", "translation_id": "Atau siapakah dia yang menjadi tentara bagimu yang akan menolongmu selain daripada Allah Yang Maha Pemurah? Orang-orang kafir itu tidak lain hanyalah dalam (keadaan) tertipu.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 21, "text": "أَمَّنۡ هَـٰذَا ٱلَّذِی یَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّوا۟ فِی عُتُوࣲّ وَنُفُورٍ ۝٢١", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "أغَفَل هؤلاء الكافرون، ولم ينظروا إلى الطير فوقهم، باسطات أجنحتها عند طيرانها في الهواء، ويضممنها إلى جُنوبها أحيانًا؟ ما يحفظها من الوقوع عند ذلك إلا الرحمن. إنه بكل شيء بصير لا يُرى في خلقه نقص ولا تفاوت. بل مَن هذا الذي هو في زعمكم- أيها الكافرون- حزب لكم ينصركم من غير الرحمن، إن أراد بكم سوءًا؟ ما الكافرون في زعمهم هذا إلا في خداع وضلال من الشيطان. بل مَن هذا الرازق المزعوم الذي يرزقكم إن أمسك الله رزقه ومنعه عنكم؟ بل استمر الكافرون في طغيانهم وضلالهم في معاندة واستكبار ونفور عن الحق، لا يسمعون له، ولا يتبعونه.", "isBasmala": false, "translation_en": "Or who is this that will provide for you, if He withholds His provision? Yet they persist in defiance and aversion.", "translation_id": "Atau siapakah dia yang memberi kamu rezeki jika Allah menahan rezeki-Nya? Sebenarnya mereka terus menerus dalam kesombongan dan menjauhkan diri?", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 22, "text": "أَفَمَن یَمۡشِی مُكِبًّا عَلَىٰ وَجۡهِهِۦۤ أَهۡدَىٰۤ أَمَّن یَمۡشِی سَوِیًّا عَلَىٰ صِرَ ٰطࣲ مُّسۡتَقِیمࣲ ۝٢٢", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "أفمن يمشي منكَّسًا على وجهه لا يدري أين يسلك ولا كيف يذهب، أشد استقامة على الطريق وأهدى، أَمَّن يمشي مستويًا منتصب القامة سالمًا على طريق واضح لا اعوجاج فيه؟ وهذا مثل ضربه الله للكافر والمؤمن.", "isBasmala": false, "translation_en": "Is he who walks bent on his own design better guided, or he who walks upright on a straight path?", "translation_id": "Maka apakah orang yang berjalan terjungkal di atas mukanya itu lebih banyak mendapatkan petunjuk ataukah orang yang berjalan tegap di atas jalan yang lurus?", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 23, "text": "قُلۡ هُوَ ٱلَّذِیۤ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ ۝٢٣", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "قل لهم -أيها الرسول-: الله هو الذي أوجدكم من العدم، وجعل لكم السمع لتسمعوا به، والأبصار لتبصروا بها، والقلوب لتعقلوا بها، قليلا- أيها الكافرون- ما تؤدون شكر هذه النعم لربكم الذي أنعم بها عليكم. قل لهم: الله هو الذي خلقكم ونشركم في الأرض، وإليه وحده تُجمعون بعد هذا التفرق للحساب والجزاء.", "isBasmala": false, "translation_en": "Say, \"It is He who produced you; and made for you the hearing, and the vision, and the organs. But rarely do you give thanks.\"", "translation_id": "Katakanlah: \"Dialah Yang menciptakan kamu dan menjadikan bagi kamu pendengaran, penglihatan dan hati\". (Tetapi) amat sedikit kamu bersyukur.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 24, "text": "قُلۡ هُوَ ٱلَّذِی ذَرَأَكُمۡ فِی ٱلۡأَرۡضِ وَإِلَیۡهِ تُحۡشَرُونَ ۝٢٤", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "قل لهم -أيها الرسول-: الله هو الذي أوجدكم من العدم، وجعل لكم السمع لتسمعوا به، والأبصار لتبصروا بها، والقلوب لتعقلوا بها، قليلا- أيها الكافرون- ما تؤدون شكر هذه النعم لربكم الذي أنعم بها عليكم. قل لهم: الله هو الذي خلقكم ونشركم في الأرض، وإليه وحده تُجمعون بعد هذا التفرق للحساب والجزاء.", "isBasmala": false, "translation_en": "Say, \"It is He who scattered you on earth, and to Him you will be rounded up.\"", "translation_id": "Katakanlah: \"Dialah Yang menjadikan kamu berkembang biak di muka bumi, dan hanya kepada-Nya-lah kamu kelak dikumpulkan\".", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 25, "text": "وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ ۝٢٥", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "ويقول الكافرون: متى يتحقق هذا الوعد بالحشر يا محمد؟ أخبرونا بزمانه أيها المؤمنون، إن كنتم صادقين فيما تدَّعون، قل -أيها الرسول- لهؤلاء: إن العلم بوقت قيام الساعة اختصَّ الله به، وإنما أنا نذير لكم أخوِّفكم عاقبة كفركم، وأبيِّن لكم ما أمرني الله ببيانه غاية البيان.", "isBasmala": false, "translation_en": "And they say, \"When will this promise be fulfilled, if you are truthful?\"", "translation_id": "Dan mereka berkata: \"Kapankah datangnya ancaman itu jika kamu adalah orang-orang yang benar?\"", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 26, "text": "قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینࣱ ۝٢٦", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "ويقول الكافرون: متى يتحقق هذا الوعد بالحشر يا محمد؟ أخبرونا بزمانه أيها المؤمنون، إن كنتم صادقين فيما تدَّعون، قل -أيها الرسول- لهؤلاء: إن العلم بوقت قيام الساعة اختصَّ الله به، وإنما أنا نذير لكم أخوِّفكم عاقبة كفركم، وأبيِّن لكم ما أمرني الله ببيانه غاية البيان.", "isBasmala": false, "translation_en": "Say, \"Knowledge is with God, and I am only a clear warner.\"", "translation_id": "Katakanlah: \"Sesungguhnya ilmu (tentang hari kiamat itu) hanya pada sisi Allah. Dan sesungguhnya aku hanyalah seorang pemberi peringatan yang menjelaskan\".", "manzil": 7, "manzil_display": ""}], "564": [{"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 27, "text": "فَلَمَّا رَأَوۡهُ زُلۡفَةࣰ سِیۤـَٔتۡ وُجُوهُ ٱلَّذِینَ كَفَرُوا۟ وَقِیلَ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تَدَّعُونَ ۝٢٧", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "فلما رأى الكفار عذاب الله قريبًا منهم وعاينوه، ظهرت الذلة والكآبة على وجوههم، وقيل توبيخًا لهم: هذا الذي كنتم تطلبون تعجيله في الدنيا.", "isBasmala": false, "translation_en": "But when they see it approaching, the faces of those who disbelieved will turn gloomy, and it will be said, \"This is what you used to call for.\"", "translation_id": "Ketika mereka melihat azab (pada hari kiamat) sudah dekat, muka orang-orang kafir itu menjadi muram. Dan dikatakan (kepada mereka) inilah (azab) yang dahulunya kamu selalu meminta-mintanya.", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 28, "text": "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَهۡلَكَنِیَ ٱللَّهُ وَمَن مَّعِیَ أَوۡ رَحِمَنَا فَمَن یُجِیرُ ٱلۡكَـٰفِرِینَ مِنۡ عَذَابٍ أَلِیمࣲ ۝٢٨", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "قل -أيها الرسول- لهؤلاء الكافرين: أخبروني إن أماتني الله ومَن معي من المؤمنين كما تتمنون، أو رحمنا فأخَّر آجالنا، وعافانا مِن عذابه، فمَن هذا الذي يحميكم، ويمنعكم من عذاب أليم موجع؟", "isBasmala": false, "translation_en": "Say, \"Have you considered? Should God make me perish, and those with me; or else He bestows His mercy on us; who will protect the disbelievers from an agonizing torment?\"", "translation_id": "Katakanlah: \"Terangkanlah kepadaku jika Allah mematikan aku dan orang-orang yang bersama dengan aku atau memberi rahmat kepada kami, (maka kami akan masuk surga), tetapi siapakah yang dapat melindungi orang-orang yang kafir dari siksa yang pedih?\"", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 29, "text": "قُلۡ هُوَ ٱلرَّحۡمَـٰنُ ءَامَنَّا بِهِۦ وَعَلَیۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِی ضَلَـٰلࣲ مُّبِینࣲ ۝٢٩", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "قل: الله هو الرحمن صدَّقنا به وعملنا بشرعه، وأطعناه، وعليه وحده اعتمدنا في كل أمورنا، فستعلمون- أيها الكافرون- إذا نزل العذاب: أيُّ الفريقين منا ومنكم في بُعْدٍ واضح عن صراط الله المستقيم؟", "isBasmala": false, "translation_en": "Say, \"He is the Compassionate. We have faith in Him, and in Him we trust. Soon you will know who is in evident error.\"", "translation_id": "Katakanlah: \"Dialah Allah Yang Maha Penyayang kami beriman kepada-Nya dan kepada-Nya-lah kami bertawakkal. Kelak kamu akan mengetahui siapakah yang berada dalam kesesatan yang nyata\".", "manzil": 7, "manzil_display": ""}, {"sura": 67, "sura_name": "الملك", "revelation": "Makkiyah", "aya": 30, "text": "قُلۡ أَرَءَیۡتُمۡ إِنۡ أَصۡبَحَ مَاۤؤُكُمۡ غَوۡرࣰا فَمَن یَأۡتِیكُم بِمَاۤءࣲ مَّعِینِۭ ۝٣٠", "juz": 29, "hizb": "(* ح 57*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: أخبروني إن صار ماؤكم الذي تشربون منه ذاهبًا في الأرض لا تصلون إليه بوسيلة، فمَن غير الله يجيئكم بماء جارٍ على وجه الأرض ظاهر للعيون؟", "isBasmala": false, "translation_en": "Say, \"Have you considered? If your water drains away, who will bring you pure running water?\"", "translation_id": "Katakanlah: \"Terangkanlah kepadaku jika sumber air kamu menjadi kering; maka siapakah yang akan mendatangkan air yang mengalir bagimu?\".", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 1, "text": "۞ نۤۚ وَٱلۡقَلَمِ وَمَا یَسۡطُرُونَ ۝١", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "(ن) سبق الكلام على الحروف المقطعة في أول سورة البقرة. أقسم الله بالقلم الذي يكتب به الملائكة والناس، وبما يكتبون من الخير والنفع والعلوم. ما أنت -أيها الرسول- بسبب نعمة الله عليك بالنبوة والرسالة بضعيف العقل، ولا سفيه الرأي، وإن لك على ما تلقاه من شدائد على تبليغ الرسالة لَثوابًا عظيمًا غير منقوص ولا مقطوع، وإنك -أيها الرسول- لعلى خلق عظيم، وهو ما اشتمل عليه القرآن من مكارم الأخلاق؛ فقد كان امتثال القرآن سجية له يأتمر بأمره، وينتهي عما ينهى عنه.", "isBasmala": false, "translation_en": "Noon. By the pen, and by what they inscribe.", "translation_id": "Nun, demi kalam dan apa yang mereka tulis,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 2, "text": "مَاۤ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونࣲ ۝٢", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "(ن) سبق الكلام على الحروف المقطعة في أول سورة البقرة. أقسم الله بالقلم الذي يكتب به الملائكة والناس، وبما يكتبون من الخير والنفع والعلوم. ما أنت -أيها الرسول- بسبب نعمة الله عليك بالنبوة والرسالة بضعيف العقل، ولا سفيه الرأي، وإن لك على ما تلقاه من شدائد على تبليغ الرسالة لَثوابًا عظيمًا غير منقوص ولا مقطوع، وإنك -أيها الرسول- لعلى خلق عظيم، وهو ما اشتمل عليه القرآن من مكارم الأخلاق؛ فقد كان امتثال القرآن سجية له يأتمر بأمره، وينتهي عما ينهى عنه.", "isBasmala": false, "translation_en": "By the grace of your Lord, you are not insane.", "translation_id": "berkat nikmat Tuhanmu kamu (Muhammad) sekali-kali bukan orang gila.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 3, "text": "وَإِنَّ لَكَ لَأَجۡرًا غَیۡرَ مَمۡنُونࣲ ۝٣", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "(ن) سبق الكلام على الحروف المقطعة في أول سورة البقرة. أقسم الله بالقلم الذي يكتب به الملائكة والناس، وبما يكتبون من الخير والنفع والعلوم. ما أنت -أيها الرسول- بسبب نعمة الله عليك بالنبوة والرسالة بضعيف العقل، ولا سفيه الرأي، وإن لك على ما تلقاه من شدائد على تبليغ الرسالة لَثوابًا عظيمًا غير منقوص ولا مقطوع، وإنك -أيها الرسول- لعلى خلق عظيم، وهو ما اشتمل عليه القرآن من مكارم الأخلاق؛ فقد كان امتثال القرآن سجية له يأتمر بأمره، وينتهي عما ينهى عنه.", "isBasmala": false, "translation_en": "In fact, you will have a reward that will never end.", "translation_id": "Dan sesungguhnya bagi kamu benar-benar pahala yang besar yang tidak putus-putusnya.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 4, "text": "وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِیمࣲ ۝٤", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "(ن) سبق الكلام على الحروف المقطعة في أول سورة البقرة. أقسم الله بالقلم الذي يكتب به الملائكة والناس، وبما يكتبون من الخير والنفع والعلوم. ما أنت -أيها الرسول- بسبب نعمة الله عليك بالنبوة والرسالة بضعيف العقل، ولا سفيه الرأي، وإن لك على ما تلقاه من شدائد على تبليغ الرسالة لَثوابًا عظيمًا غير منقوص ولا مقطوع، وإنك -أيها الرسول- لعلى خلق عظيم، وهو ما اشتمل عليه القرآن من مكارم الأخلاق؛ فقد كان امتثال القرآن سجية له يأتمر بأمره، وينتهي عما ينهى عنه.", "isBasmala": false, "translation_en": "And you are of a great moral character.", "translation_id": "Dan sesungguhnya kamu benar-benar berbudi pekerti yang agung.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 5, "text": "فَسَتُبۡصِرُ وَیُبۡصِرُونَ ۝٥", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فعن قريب سترى أيها الرسول، ويرى الكافرون في أيكم الفتنة والجنون؟", "isBasmala": false, "translation_en": "You will see, and they will see.", "translation_id": "Maka kelak kamu akan melihat dan mereka (orang-orang kafir)pun akan melihat,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 6, "text": "بِأَییِّكُمُ ٱلۡمَفۡتُونُ ۝٦", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فعن قريب سترى أيها الرسول، ويرى الكافرون في أيكم الفتنة والجنون؟", "isBasmala": false, "translation_en": "Which of you is the afflicted.", "translation_id": "siapa di antara kamu yang gila.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 7, "text": "إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِیلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ ۝٧", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "إن ربك- سبحانه- هو أعلم بالشقي المنحرف عن دين الله وطريق الهدى، وهو أعلم بالتقي المهتدي إلى دين الحق.", "isBasmala": false, "translation_en": "Your Lord knows best who has strayed from His path, and He knows best the well-guided.", "translation_id": "Sesungguhnya Tuhanmu, Dialah Yang Paling Mengetahui siapa yang sesat dari jalan-Nya; dan Dialah Yang Paling Mengetahui orang-orang yang mendapat petunjuk.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 8, "text": "فَلَا تُطِعِ ٱلۡمُكَذِّبِینَ ۝٨", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فاثبت على ما أنت عليه -أيها الرسول- من مخالفة المكذبين ولا تطعهم.", "isBasmala": false, "translation_en": "So do not obey the deniers.", "translation_id": "Maka janganlah kamu ikuti orang-orang yang mendustakan (ayat-ayat Allah).", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 9, "text": "وَدُّوا۟ لَوۡ تُدۡهِنُ فَیُدۡهِنُونَ ۝٩", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "تمنَّوا وأحبوا لو تلاينهم، وتصانعهم على بعض ما هم عليه، فيلينون لك.", "isBasmala": false, "translation_en": "They would like you to compromise, so they would compromise.", "translation_id": "Maka mereka menginginkan supaya kamu bersikap lunak lalu mereka bersikap lunak (pula kepadamu).", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 10, "text": "وَلَا تُطِعۡ كُلَّ حَلَّافࣲ مَّهِینٍ ۝١٠", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "ولا تطع -أيها الرسول- كلَّ إنسانٍ كثير الحلف كذاب حقير، مغتاب للناس، يمشي بينهم بالنميمة، وينقل حديث بعضهم إلى بعض على وجه الإفساد بينهم، بخيل بالمال ضنين به عن الحق، شديد المنع للخير، متجاوز حدَّه في العدوان على الناس وتناول المحرمات، كثير الآثام، شديد في كفره، فاحش لئيم، منسوب لغير أبيه. ومن أجل أنه كان صاحب مال وبنين طغى وتكبر عن الحق، فإذا قرأ عليه أحد آيات القرآن كذَّب بها، وقال: هذا أباطيل الأولين وخرافاتهم. وهذه الآيات وإن نزلت في بعض المشركين كالوليد بن المغيرة، إلا أن فيها تحذيرًا للمسلم من موافقة من اتصف بهذه الصفات الذميمة.", "isBasmala": false, "translation_en": "And do not obey any vile swearer.", "translation_id": "Dan janganlah kamu ikuti setiap orang yang banyak bersumpah lagi hina,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 11, "text": "هَمَّازࣲ مَّشَّاۤءِۭ بِنَمِیمࣲ ۝١١", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "ولا تطع -أيها الرسول- كلَّ إنسانٍ كثير الحلف كذاب حقير، مغتاب للناس، يمشي بينهم بالنميمة، وينقل حديث بعضهم إلى بعض على وجه الإفساد بينهم، بخيل بالمال ضنين به عن الحق، شديد المنع للخير، متجاوز حدَّه في العدوان على الناس وتناول المحرمات، كثير الآثام، شديد في كفره، فاحش لئيم، منسوب لغير أبيه. ومن أجل أنه كان صاحب مال وبنين طغى وتكبر عن الحق، فإذا قرأ عليه أحد آيات القرآن كذَّب بها، وقال: هذا أباطيل الأولين وخرافاتهم. وهذه الآيات وإن نزلت في بعض المشركين كالوليد بن المغيرة، إلا أن فيها تحذيرًا للمسلم من موافقة من اتصف بهذه الصفات الذميمة.", "isBasmala": false, "translation_en": "Backbiter, spreader of slander.", "translation_id": "yang banyak mencela, yang kian ke mari menghambur fitnah,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 12, "text": "مَّنَّاعࣲ لِّلۡخَیۡرِ مُعۡتَدٍ أَثِیمٍ ۝١٢", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "ولا تطع -أيها الرسول- كلَّ إنسانٍ كثير الحلف كذاب حقير، مغتاب للناس، يمشي بينهم بالنميمة، وينقل حديث بعضهم إلى بعض على وجه الإفساد بينهم، بخيل بالمال ضنين به عن الحق، شديد المنع للخير، متجاوز حدَّه في العدوان على الناس وتناول المحرمات، كثير الآثام، شديد في كفره، فاحش لئيم، منسوب لغير أبيه. ومن أجل أنه كان صاحب مال وبنين طغى وتكبر عن الحق، فإذا قرأ عليه أحد آيات القرآن كذَّب بها، وقال: هذا أباطيل الأولين وخرافاتهم. وهذه الآيات وإن نزلت في بعض المشركين كالوليد بن المغيرة، إلا أن فيها تحذيرًا للمسلم من موافقة من اتصف بهذه الصفات الذميمة.", "isBasmala": false, "translation_en": "Preventer of good, transgressor, sinner.", "translation_id": "yang banyak menghalangi perbuatan baik, yang melampaui batas lagi banyak dosa,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 13, "text": "عُتُلِّۭ بَعۡدَ ذَ ٰلِكَ زَنِیمٍ ۝١٣", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "ولا تطع -أيها الرسول- كلَّ إنسانٍ كثير الحلف كذاب حقير، مغتاب للناس، يمشي بينهم بالنميمة، وينقل حديث بعضهم إلى بعض على وجه الإفساد بينهم، بخيل بالمال ضنين به عن الحق، شديد المنع للخير، متجاوز حدَّه في العدوان على الناس وتناول المحرمات، كثير الآثام، شديد في كفره، فاحش لئيم، منسوب لغير أبيه. ومن أجل أنه كان صاحب مال وبنين طغى وتكبر عن الحق، فإذا قرأ عليه أحد آيات القرآن كذَّب بها، وقال: هذا أباطيل الأولين وخرافاتهم. وهذه الآيات وإن نزلت في بعض المشركين كالوليد بن المغيرة، إلا أن فيها تحذيرًا للمسلم من موافقة من اتصف بهذه الصفات الذميمة.", "isBasmala": false, "translation_en": "Rude and fake besides.", "translation_id": "yang kaku kasar, selain dari itu, yang terkenal kejahatannya,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 14, "text": "أَن كَانَ ذَا مَالࣲ وَبَنِینَ ۝١٤", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "ولا تطع -أيها الرسول- كلَّ إنسانٍ كثير الحلف كذاب حقير، مغتاب للناس، يمشي بينهم بالنميمة، وينقل حديث بعضهم إلى بعض على وجه الإفساد بينهم، بخيل بالمال ضنين به عن الحق، شديد المنع للخير، متجاوز حدَّه في العدوان على الناس وتناول المحرمات، كثير الآثام، شديد في كفره، فاحش لئيم، منسوب لغير أبيه. ومن أجل أنه كان صاحب مال وبنين طغى وتكبر عن الحق، فإذا قرأ عليه أحد آيات القرآن كذَّب بها، وقال: هذا أباطيل الأولين وخرافاتهم. وهذه الآيات وإن نزلت في بعض المشركين كالوليد بن المغيرة، إلا أن فيها تحذيرًا للمسلم من موافقة من اتصف بهذه الصفات الذميمة.", "isBasmala": false, "translation_en": "Just because he has money and children.", "translation_id": "karena dia mempunyai (banyak) harta dan anak.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 15, "text": "إِذَا تُتۡلَىٰ عَلَیۡهِ ءَایَـٰتُنَا قَالَ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ۝١٥", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "ولا تطع -أيها الرسول- كلَّ إنسانٍ كثير الحلف كذاب حقير، مغتاب للناس، يمشي بينهم بالنميمة، وينقل حديث بعضهم إلى بعض على وجه الإفساد بينهم، بخيل بالمال ضنين به عن الحق، شديد المنع للخير، متجاوز حدَّه في العدوان على الناس وتناول المحرمات، كثير الآثام، شديد في كفره، فاحش لئيم، منسوب لغير أبيه. ومن أجل أنه كان صاحب مال وبنين طغى وتكبر عن الحق، فإذا قرأ عليه أحد آيات القرآن كذَّب بها، وقال: هذا أباطيل الأولين وخرافاتهم. وهذه الآيات وإن نزلت في بعض المشركين كالوليد بن المغيرة، إلا أن فيها تحذيرًا للمسلم من موافقة من اتصف بهذه الصفات الذميمة.", "isBasmala": false, "translation_en": "When Our Verses are recited to him, he says, \"Myths of the ancients!\"", "translation_id": "Apabila dibacakan kepadanya ayat-ayat Kami, ia berkata: \"(Ini adalah) dongeng-dongengan orang-orang dahulu kala\".", "manzil": 7, "manzil_display": ""}], "565": [{"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 16, "text": "سَنَسِمُهُۥ عَلَى ٱلۡخُرۡطُومِ ۝١٦", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "سنجعل على أنفه علامة لازمة لا تفارقه عقوبة له؛ ليكون مفتضحًا بها أمام الناس.", "isBasmala": false, "translation_en": "We will brand him on the muzzle.", "translation_id": "Kelak akan Kami beri tanda dia di belalai(nya).", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 17, "text": "إِنَّا بَلَوۡنَـٰهُمۡ كَمَا بَلَوۡنَاۤ أَصۡحَـٰبَ ٱلۡجَنَّةِ إِذۡ أَقۡسَمُوا۟ لَیَصۡرِمُنَّهَا مُصۡبِحِینَ ۝١٧", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "إنا اختبرنا أهل \"مكة\" بالجوع والقحط، كما اختبرنا أصحاب الحديقة حين حلفوا فيما بينهم، ليقطعُنَّ ثمار حديقتهم مبكِّرين في الصباح، فلا يَطْعَم منها غيرهم من المساكين ونحوهم، ولم يقولوا: إن شاء الله.", "isBasmala": false, "translation_en": "We tested them, as We tested the owners of the garden, when they vowed to harvest it in the morning.", "translation_id": "Sesungguhnya Kami telah mencobai mereka (musyrikin Mekah) sebagaimana Kami telah mencobai pemilik-pemilik kebun, ketika mereka bersumpah bahwa mereka sungguh-sungguh akanmemetik (hasil)nya di pagi hari,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 18, "text": "وَلَا یَسۡتَثۡنُونَ ۝١٨", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "إنا اختبرنا أهل \"مكة\" بالجوع والقحط، كما اختبرنا أصحاب الحديقة حين حلفوا فيما بينهم، ليقطعُنَّ ثمار حديقتهم مبكِّرين في الصباح، فلا يَطْعَم منها غيرهم من المساكين ونحوهم، ولم يقولوا: إن شاء الله.", "isBasmala": false, "translation_en": "Without any reservation.", "translation_id": "dan mereka tidak menyisihkan (hak fakir miskin),", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 19, "text": "فَطَافَ عَلَیۡهَا طَاۤىِٕفࣱ مِّن رَّبِّكَ وَهُمۡ نَاۤىِٕمُونَ ۝١٩", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فأنزل الله عليها نارًا أحرقتها ليلا وهم نائمون، فأصبحت محترقة سوداء كالليل المظلم.", "isBasmala": false, "translation_en": "But a calamity from your Lord went around it while they slept.", "translation_id": "lalu kebun itu diliputi malapetaka (yang datang) dari Tuhanmu ketika mereka sedang tidur,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 20, "text": "فَأَصۡبَحَتۡ كَٱلصَّرِیمِ ۝٢٠", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فأنزل الله عليها نارًا أحرقتها ليلا وهم نائمون، فأصبحت محترقة سوداء كالليل المظلم.", "isBasmala": false, "translation_en": "And in the morning it was as if picked.", "translation_id": "maka jadilah kebun itu hitam seperti malam yang gelap gulita.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 21, "text": "فَتَنَادَوۡا۟ مُصۡبِحِینَ ۝٢١", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فنادى بعضهم بعضًا وقت الصباح: أن اذهبوا مبكرين إلى زرعكم، إن كنتم مصرِّين على قطع الثمار.", "isBasmala": false, "translation_en": "In the morning, they called to one another.", "translation_id": "lalu mereka panggil memanggil di pagi hari:", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 22, "text": "أَنِ ٱغۡدُوا۟ عَلَىٰ حَرۡثِكُمۡ إِن كُنتُمۡ صَـٰرِمِینَ ۝٢٢", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فنادى بعضهم بعضًا وقت الصباح: أن اذهبوا مبكرين إلى زرعكم، إن كنتم مصرِّين على قطع الثمار.", "isBasmala": false, "translation_en": "\"Go early to your plantation, if you are going to harvest.\"", "translation_id": "\"Pergilah diwaktu pagi (ini) ke kebunmu jika kamu hendak memetik buahnya\".", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 23, "text": "فَٱنطَلَقُوا۟ وَهُمۡ یَتَخَـٰفَتُونَ ۝٢٣", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فاندفعوا مسرعين، وهم يتسارُّون بالحديث فيما بينهم: بأن لا تمكِّنوا اليوم أحدا من المساكين من دخول حديقتكم.", "isBasmala": false, "translation_en": "So off they went, murmuring to one another.", "translation_id": "Maka pergilah mereka saling berbisik-bisik.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 24, "text": "أَن لَّا یَدۡخُلَنَّهَا ٱلۡیَوۡمَ عَلَیۡكُم مِّسۡكِینࣱ ۝٢٤", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فاندفعوا مسرعين، وهم يتسارُّون بالحديث فيما بينهم: بأن لا تمكِّنوا اليوم أحدا من المساكين من دخول حديقتكم.", "isBasmala": false, "translation_en": "\"No poor person is to enter it upon you today.\"", "translation_id": "\"Pada hari ini janganlah ada seorang miskinpun masuk ke dalam kebunmu\".", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 25, "text": "وَغَدَوۡا۟ عَلَىٰ حَرۡدࣲ قَـٰدِرِینَ ۝٢٥", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "وساروا في أول النهار إلى حديقتهم على قصدهم السيِّئ في منع المساكين من ثمار الحديقة، وهم في غاية القدرة على تنفيذه في زعمهم.", "isBasmala": false, "translation_en": "And early they went, resolved in intent.", "translation_id": "Dan berangkatlah mereka di pagi hari dengan niat menghalangi (orang-orang miskin) padahal mereka (menolongnya).", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 26, "text": "فَلَمَّا رَأَوۡهَا قَالُوۤا۟ إِنَّا لَضَاۤلُّونَ ۝٢٦", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فلما رأوا حديقتهم محترقة أنكروها، وقالوا: لقد أخطأنا الطريق إليها، فلما عرفوا أنها هي جنتهم، قالوا: بل نحن محرومون خيرها؛ بسبب عزمنا على البخل ومنع المساكين. قال أعدلهم: ألم أقل لكم هلا تستثنون وتقولون: إن شاء الله؟ قالوا بعد أن عادوا إلى رشدهم: تنزَّه الله ربنا عن الظلم فيما أصابنا، بل نحن كنا الظالمين لأنفسنا بترك الاستثناء وقصدنا السيِّئ. فأقبل بعضهم على بعض، يلوم كل منهم الآخر على تركهم الاستثناء وعلى قصدهم السيِّئ، قالوا: يا ويلنا إنَّا كنا متجاوزين الحد في منعنا الفقراء ومخالفة أمر الله، عسى ربنا أن يعطينا أفضل من حديقتنا؛ بسبب توبتنا واعترافنا بخطيئتنا. إنا إلى ربنا وحده راغبون، راجون العفو، طالبون الخير. مثل ذلك العقاب الذي عاقبنا به أهل الحديقة يكون عقابنا في الدنيا لكل مَن خالف أمر الله، وبخل بما آتاه الله من النعم فلم يؤدِّ حق الله فيها، ولَعذاب الآخرة أعظم وأشد مِن عذاب الدنيا، لو كانوا يعلمون لانزجروا عن كل سبب يوجب العقاب.", "isBasmala": false, "translation_en": "But when they saw it, they said, \"We were wrong.", "translation_id": "Tatkala mereka melihat kebun itu, mereka berkata: \"Sesungguhnya kita benar-benar orang-orang yang sesat (jalan),", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 27, "text": "بَلۡ نَحۡنُ مَحۡرُومُونَ ۝٢٧", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فلما رأوا حديقتهم محترقة أنكروها، وقالوا: لقد أخطأنا الطريق إليها، فلما عرفوا أنها هي جنتهم، قالوا: بل نحن محرومون خيرها؛ بسبب عزمنا على البخل ومنع المساكين. قال أعدلهم: ألم أقل لكم هلا تستثنون وتقولون: إن شاء الله؟ قالوا بعد أن عادوا إلى رشدهم: تنزَّه الله ربنا عن الظلم فيما أصابنا، بل نحن كنا الظالمين لأنفسنا بترك الاستثناء وقصدنا السيِّئ. فأقبل بعضهم على بعض، يلوم كل منهم الآخر على تركهم الاستثناء وعلى قصدهم السيِّئ، قالوا: يا ويلنا إنَّا كنا متجاوزين الحد في منعنا الفقراء ومخالفة أمر الله، عسى ربنا أن يعطينا أفضل من حديقتنا؛ بسبب توبتنا واعترافنا بخطيئتنا. إنا إلى ربنا وحده راغبون، راجون العفو، طالبون الخير. مثل ذلك العقاب الذي عاقبنا به أهل الحديقة يكون عقابنا في الدنيا لكل مَن خالف أمر الله، وبخل بما آتاه الله من النعم فلم يؤدِّ حق الله فيها، ولَعذاب الآخرة أعظم وأشد مِن عذاب الدنيا، لو كانوا يعلمون لانزجروا عن كل سبب يوجب العقاب.", "isBasmala": false, "translation_en": "We are now deprived.\"", "translation_id": "bahkan kita dihalangi (dari memperoleh hasilnya)\".", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 28, "text": "قَالَ أَوۡسَطُهُمۡ أَلَمۡ أَقُل لَّكُمۡ لَوۡلَا تُسَبِّحُونَ ۝٢٨", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فلما رأوا حديقتهم محترقة أنكروها، وقالوا: لقد أخطأنا الطريق إليها، فلما عرفوا أنها هي جنتهم، قالوا: بل نحن محرومون خيرها؛ بسبب عزمنا على البخل ومنع المساكين. قال أعدلهم: ألم أقل لكم هلا تستثنون وتقولون: إن شاء الله؟ قالوا بعد أن عادوا إلى رشدهم: تنزَّه الله ربنا عن الظلم فيما أصابنا، بل نحن كنا الظالمين لأنفسنا بترك الاستثناء وقصدنا السيِّئ. فأقبل بعضهم على بعض، يلوم كل منهم الآخر على تركهم الاستثناء وعلى قصدهم السيِّئ، قالوا: يا ويلنا إنَّا كنا متجاوزين الحد في منعنا الفقراء ومخالفة أمر الله، عسى ربنا أن يعطينا أفضل من حديقتنا؛ بسبب توبتنا واعترافنا بخطيئتنا. إنا إلى ربنا وحده راغبون، راجون العفو، طالبون الخير. مثل ذلك العقاب الذي عاقبنا به أهل الحديقة يكون عقابنا في الدنيا لكل مَن خالف أمر الله، وبخل بما آتاه الله من النعم فلم يؤدِّ حق الله فيها، ولَعذاب الآخرة أعظم وأشد مِن عذاب الدنيا، لو كانوا يعلمون لانزجروا عن كل سبب يوجب العقاب.", "isBasmala": false, "translation_en": "The most reasonable of them said, \"Did I not say to you, 'if only you would glorify?'\"", "translation_id": "Berkatalah seorang yang paling baik pikirannya di antara mereka: \"Bukankah aku telah mengatakan kepadamu, hendaklah kamu bertasbih (kepada Tuhanmu)?\"", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 29, "text": "قَالُوا۟ سُبۡحَـٰنَ رَبِّنَاۤ إِنَّا كُنَّا ظَـٰلِمِینَ ۝٢٩", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فلما رأوا حديقتهم محترقة أنكروها، وقالوا: لقد أخطأنا الطريق إليها، فلما عرفوا أنها هي جنتهم، قالوا: بل نحن محرومون خيرها؛ بسبب عزمنا على البخل ومنع المساكين. قال أعدلهم: ألم أقل لكم هلا تستثنون وتقولون: إن شاء الله؟ قالوا بعد أن عادوا إلى رشدهم: تنزَّه الله ربنا عن الظلم فيما أصابنا، بل نحن كنا الظالمين لأنفسنا بترك الاستثناء وقصدنا السيِّئ. فأقبل بعضهم على بعض، يلوم كل منهم الآخر على تركهم الاستثناء وعلى قصدهم السيِّئ، قالوا: يا ويلنا إنَّا كنا متجاوزين الحد في منعنا الفقراء ومخالفة أمر الله، عسى ربنا أن يعطينا أفضل من حديقتنا؛ بسبب توبتنا واعترافنا بخطيئتنا. إنا إلى ربنا وحده راغبون، راجون العفو، طالبون الخير. مثل ذلك العقاب الذي عاقبنا به أهل الحديقة يكون عقابنا في الدنيا لكل مَن خالف أمر الله، وبخل بما آتاه الله من النعم فلم يؤدِّ حق الله فيها، ولَعذاب الآخرة أعظم وأشد مِن عذاب الدنيا، لو كانوا يعلمون لانزجروا عن كل سبب يوجب العقاب.", "isBasmala": false, "translation_en": "They said, \"Glory to our Lord-We were indeed in the wrong.\"", "translation_id": "Mereka mengucapkan: \"Maha Suci Tuhan kami, sesungguhnya kami adalah orang-orang yang zalim\".", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 30, "text": "فَأَقۡبَلَ بَعۡضُهُمۡ عَلَىٰ بَعۡضࣲ یَتَلَـٰوَمُونَ ۝٣٠", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فلما رأوا حديقتهم محترقة أنكروها، وقالوا: لقد أخطأنا الطريق إليها، فلما عرفوا أنها هي جنتهم، قالوا: بل نحن محرومون خيرها؛ بسبب عزمنا على البخل ومنع المساكين. قال أعدلهم: ألم أقل لكم هلا تستثنون وتقولون: إن شاء الله؟ قالوا بعد أن عادوا إلى رشدهم: تنزَّه الله ربنا عن الظلم فيما أصابنا، بل نحن كنا الظالمين لأنفسنا بترك الاستثناء وقصدنا السيِّئ. فأقبل بعضهم على بعض، يلوم كل منهم الآخر على تركهم الاستثناء وعلى قصدهم السيِّئ، قالوا: يا ويلنا إنَّا كنا متجاوزين الحد في منعنا الفقراء ومخالفة أمر الله، عسى ربنا أن يعطينا أفضل من حديقتنا؛ بسبب توبتنا واعترافنا بخطيئتنا. إنا إلى ربنا وحده راغبون، راجون العفو، طالبون الخير. مثل ذلك العقاب الذي عاقبنا به أهل الحديقة يكون عقابنا في الدنيا لكل مَن خالف أمر الله، وبخل بما آتاه الله من النعم فلم يؤدِّ حق الله فيها، ولَعذاب الآخرة أعظم وأشد مِن عذاب الدنيا، لو كانوا يعلمون لانزجروا عن كل سبب يوجب العقاب.", "isBasmala": false, "translation_en": "Then they turned to one another, blaming one another.", "translation_id": "Lalu sebahagian mereka menghadapi sebahagian yang lain seraya cela mencela.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 31, "text": "قَالُوا۟ یَـٰوَیۡلَنَاۤ إِنَّا كُنَّا طَـٰغِینَ ۝٣١", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فلما رأوا حديقتهم محترقة أنكروها، وقالوا: لقد أخطأنا الطريق إليها، فلما عرفوا أنها هي جنتهم، قالوا: بل نحن محرومون خيرها؛ بسبب عزمنا على البخل ومنع المساكين. قال أعدلهم: ألم أقل لكم هلا تستثنون وتقولون: إن شاء الله؟ قالوا بعد أن عادوا إلى رشدهم: تنزَّه الله ربنا عن الظلم فيما أصابنا، بل نحن كنا الظالمين لأنفسنا بترك الاستثناء وقصدنا السيِّئ. فأقبل بعضهم على بعض، يلوم كل منهم الآخر على تركهم الاستثناء وعلى قصدهم السيِّئ، قالوا: يا ويلنا إنَّا كنا متجاوزين الحد في منعنا الفقراء ومخالفة أمر الله، عسى ربنا أن يعطينا أفضل من حديقتنا؛ بسبب توبتنا واعترافنا بخطيئتنا. إنا إلى ربنا وحده راغبون، راجون العفو، طالبون الخير. مثل ذلك العقاب الذي عاقبنا به أهل الحديقة يكون عقابنا في الدنيا لكل مَن خالف أمر الله، وبخل بما آتاه الله من النعم فلم يؤدِّ حق الله فيها، ولَعذاب الآخرة أعظم وأشد مِن عذاب الدنيا، لو كانوا يعلمون لانزجروا عن كل سبب يوجب العقاب.", "isBasmala": false, "translation_en": "They said, \"Woe to us-we were indeed domineering.", "translation_id": "Mereka berkata: \"Aduhai celakalah kita; sesungguhnya kita ini adalah orang-orang yang melampaui batas\".", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 32, "text": "عَسَىٰ رَبُّنَاۤ أَن یُبۡدِلَنَا خَیۡرࣰا مِّنۡهَاۤ إِنَّاۤ إِلَىٰ رَبِّنَا رَ ٰغِبُونَ ۝٣٢", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فلما رأوا حديقتهم محترقة أنكروها، وقالوا: لقد أخطأنا الطريق إليها، فلما عرفوا أنها هي جنتهم، قالوا: بل نحن محرومون خيرها؛ بسبب عزمنا على البخل ومنع المساكين. قال أعدلهم: ألم أقل لكم هلا تستثنون وتقولون: إن شاء الله؟ قالوا بعد أن عادوا إلى رشدهم: تنزَّه الله ربنا عن الظلم فيما أصابنا، بل نحن كنا الظالمين لأنفسنا بترك الاستثناء وقصدنا السيِّئ. فأقبل بعضهم على بعض، يلوم كل منهم الآخر على تركهم الاستثناء وعلى قصدهم السيِّئ، قالوا: يا ويلنا إنَّا كنا متجاوزين الحد في منعنا الفقراء ومخالفة أمر الله، عسى ربنا أن يعطينا أفضل من حديقتنا؛ بسبب توبتنا واعترافنا بخطيئتنا. إنا إلى ربنا وحده راغبون، راجون العفو، طالبون الخير. مثل ذلك العقاب الذي عاقبنا به أهل الحديقة يكون عقابنا في الدنيا لكل مَن خالف أمر الله، وبخل بما آتاه الله من النعم فلم يؤدِّ حق الله فيها، ولَعذاب الآخرة أعظم وأشد مِن عذاب الدنيا، لو كانوا يعلمون لانزجروا عن كل سبب يوجب العقاب.", "isBasmala": false, "translation_en": "Perhaps our Lord will give us a better substitute for it. We are turning to our Lord.\"", "translation_id": "Mudah-mudahan Tuhan kita memberikan ganti kepada kita dengan (kebun) yang lebih baik daripada itu; sesungguhnya kita mengharapkan ampunan dari Tuhan kita.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 33, "text": "كَذَ ٰلِكَ ٱلۡعَذَابُۖ وَلَعَذَابُ ٱلۡـَٔاخِرَةِ أَكۡبَرُۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ ۝٣٣", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فلما رأوا حديقتهم محترقة أنكروها، وقالوا: لقد أخطأنا الطريق إليها، فلما عرفوا أنها هي جنتهم، قالوا: بل نحن محرومون خيرها؛ بسبب عزمنا على البخل ومنع المساكين. قال أعدلهم: ألم أقل لكم هلا تستثنون وتقولون: إن شاء الله؟ قالوا بعد أن عادوا إلى رشدهم: تنزَّه الله ربنا عن الظلم فيما أصابنا، بل نحن كنا الظالمين لأنفسنا بترك الاستثناء وقصدنا السيِّئ. فأقبل بعضهم على بعض، يلوم كل منهم الآخر على تركهم الاستثناء وعلى قصدهم السيِّئ، قالوا: يا ويلنا إنَّا كنا متجاوزين الحد في منعنا الفقراء ومخالفة أمر الله، عسى ربنا أن يعطينا أفضل من حديقتنا؛ بسبب توبتنا واعترافنا بخطيئتنا. إنا إلى ربنا وحده راغبون، راجون العفو، طالبون الخير. مثل ذلك العقاب الذي عاقبنا به أهل الحديقة يكون عقابنا في الدنيا لكل مَن خالف أمر الله، وبخل بما آتاه الله من النعم فلم يؤدِّ حق الله فيها، ولَعذاب الآخرة أعظم وأشد مِن عذاب الدنيا، لو كانوا يعلمون لانزجروا عن كل سبب يوجب العقاب.", "isBasmala": false, "translation_en": "Such is the punishment; but the punishment of the Hereafter is greater, if they only knew.", "translation_id": "Seperti itulah azab (dunia). Dan sesungguhnya azab akhirat lebih besar jika mereka mengetahui.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 34, "text": "إِنَّ لِلۡمُتَّقِینَ عِندَ رَبِّهِمۡ جَنَّـٰتِ ٱلنَّعِیمِ ۝٣٤", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "إن الذين اتقوا عقاب الله بفعل ما أمرهم به وتَرْك ما نهاهم عنه، لهم عند ربهم في الآخرة جنات فيها النعيم المقيم.", "isBasmala": false, "translation_en": "For the righteous are Gardens of Delight with their Lord.", "translation_id": "Sesungguhnya bagi orang-orang yang bertakwa (disediakan) surga-surga yang penuh kenikmatan di sisi Tuhannya.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 35, "text": "أَفَنَجۡعَلُ ٱلۡمُسۡلِمِینَ كَٱلۡمُجۡرِمِینَ ۝٣٥", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "أفنجعل الخاضعين لله بالطاعة كالكافرين؟ ما لكم كيف حكمتم هذا الحكم الجائر، فساويتم بينهم في الثواب؟", "isBasmala": false, "translation_en": "Shall We treat the Muslims like the villains?", "translation_id": "Maka apakah patut Kami menjadikan orang-orang Islam itu sama dengan orang-orang yang berdosa (orang kafir)?", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 36, "text": "مَا لَكُمۡ كَیۡفَ تَحۡكُمُونَ ۝٣٦", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "أفنجعل الخاضعين لله بالطاعة كالكافرين؟ ما لكم كيف حكمتم هذا الحكم الجائر، فساويتم بينهم في الثواب؟", "isBasmala": false, "translation_en": "What is the matter with you? How do you judge?", "translation_id": "Atau adakah kamu (berbuat demikian): bagaimanakah kamu mengambil keputusan?", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 37, "text": "أَمۡ لَكُمۡ كِتَـٰبࣱ فِیهِ تَدۡرُسُونَ ۝٣٧", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "أم لكم كتاب منزل من السماء تجدون فيه المطيع كالعاصي، فأنتم تدرسون فيه ما تقولون؟ إن لكم في هذا الكتاب إذًا ما تشتهون، ليس لكم ذلك.", "isBasmala": false, "translation_en": "Or do you have a scripture in which you study.", "translation_id": "Atau adakah kamu mempunyai sebuah kitab (yang diturunkan Allah) yang kamu membacanya?,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 38, "text": "إِنَّ لَكُمۡ فِیهِ لَمَا تَخَیَّرُونَ ۝٣٨", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "أم لكم كتاب منزل من السماء تجدون فيه المطيع كالعاصي، فأنتم تدرسون فيه ما تقولون؟ إن لكم في هذا الكتاب إذًا ما تشتهون، ليس لكم ذلك.", "isBasmala": false, "translation_en": "Wherein there is whatever you choose?", "translation_id": "bahwa di dalamnya kamu benar-benar boleh memilih apa yang kamu sukai untukmu.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 39, "text": "أَمۡ لَكُمۡ أَیۡمَـٰنٌ عَلَیۡنَا بَـٰلِغَةٌ إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ إِنَّ لَكُمۡ لَمَا تَحۡكُمُونَ ۝٣٩", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "أم لكم عهود ومواثيق علينا في أنه سيحصل لكم ما تريدون وتشتهون؟", "isBasmala": false, "translation_en": "Or do you have oaths from Us, binding until the Day of Resurrection, that you will have whatever you demand?", "translation_id": "Atau apakah kamu memperoleh janji yang diperkuat dengan sumpah dari Kami, yang tetap berlaku sampai hari kiamat; sesungguhnya kamu benar-benar dapat mengambil keputusan (sekehendakmu)?", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 40, "text": "سَلۡهُمۡ أَیُّهُم بِذَ ٰلِكَ زَعِیمٌ ۝٤٠", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "سل المشركين -أيها الرسول-: أيهم بذلك الحكم كفيل وضامن بأن يكون له ذلك؟ أم لهم آلهة تكفُل لهم ما يقولون، وتعينهم على إدراك ما طلبوا، فليأتوا بها إن كانوا صادقين في دعواهم؟", "isBasmala": false, "translation_en": "Ask them, which of them will guarantee that.", "translation_id": "Tanyakanlah kepada mereka: \"Siapakah di antara mereka yang bertanggung jawab terhadap keputusan yang diambil itu?\"", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 41, "text": "أَمۡ لَهُمۡ شُرَكَاۤءُ فَلۡیَأۡتُوا۟ بِشُرَكَاۤىِٕهِمۡ إِن كَانُوا۟ صَـٰدِقِینَ ۝٤١", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "سل المشركين -أيها الرسول-: أيهم بذلك الحكم كفيل وضامن بأن يكون له ذلك؟ أم لهم آلهة تكفُل لهم ما يقولون، وتعينهم على إدراك ما طلبوا، فليأتوا بها إن كانوا صادقين في دعواهم؟", "isBasmala": false, "translation_en": "Or do they have partners? Then let them produce their partners, if they are truthful.", "translation_id": "Atau apakah mereka mempunyai sekutu-sekutu? Maka hendaklah mereka mendatangkan sekutu-sekutunya jika mereka adalah orang-orang yang benar.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 42, "text": "یَوۡمَ یُكۡشَفُ عَن سَاقࣲ وَیُدۡعَوۡنَ إِلَى ٱلسُّجُودِ فَلَا یَسۡتَطِیعُونَ ۝٤٢", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "يوم القيامة يشتد الأمر ويصعب هوله، ويأتي الله تعالى لفصل القضاء بين الخلائق، فيكشف عن ساقه الكريمة التي لا يشبهها شيء، قال صلى الله عليه وسلم: \"يكشف ربنا عن ساقه، فيسجد له كل مؤمن ومؤمنة، ويبقى مَن كان يسجد في الدنيا؛ رياء وسمعة، فيذهب ليسجد، فيعود ظهره طبقًا واحدًا\" رواه البخاري ومسلم.", "isBasmala": false, "translation_en": "On the Day when the Shin will be exposed, and they will be called to bow down, but they will be unable.", "translation_id": "Pada hari betis disingkapkan dan mereka dipanggil untuk bersujud; maka mereka tidak kuasa,", "manzil": 7, "manzil_display": ""}], "566": [{"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 43, "text": "خَـٰشِعَةً أَبۡصَـٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةࣱۖ وَقَدۡ كَانُوا۟ یُدۡعَوۡنَ إِلَى ٱلسُّجُودِ وَهُمۡ سَـٰلِمُونَ ۝٤٣", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "منكسرة أبصارهم لا يرفعونها، تغشاهم ذلة شديدة مِن عذاب الله، وقد كانوا في الدنيا يُدْعَون إلى الصلاة لله وعبادته، وهم أصحَّاء قادرون عليها فلا يسجدون؛ تعظُّمًا واستكبارًا.", "isBasmala": false, "translation_en": "Their eyes subdued, shame will cover them. They were invited to bow down when they were sound.", "translation_id": "(dalam keadaan) pandangan mereka tunduk ke bawah, lagi mereka diliputi kehinaan. Dan sesungguhnya mereka dahulu (di dunia) diseru untuk bersujud, dan mereka dalam keadaan sejahtera.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 44, "text": "فَذَرۡنِی وَمَن یُكَذِّبُ بِهَـٰذَا ٱلۡحَدِیثِۖ سَنَسۡتَدۡرِجُهُم مِّنۡ حَیۡثُ لَا یَعۡلَمُونَ ۝٤٤", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فذرني -أيها الرسول- ومَن يكذِّب بهذا القرآن، فإن عليَّ جزاءهم والانتقام منهم، سنمدهم بالأموال والأولاد والنعم؛ استدراجًا لهم من حيث لا يشعرون أنه سبب لإهلاكهم، وأُمهلهم وأُطيل أعمارهم؛ ليزدادوا إثمًا. إن كيدي بأهل الكفر قويٌّ شديد.", "isBasmala": false, "translation_en": "So leave Me to those who reject this discourse; We will proceed against them gradually, from where they do not know.", "translation_id": "Maka serahkanlah (ya Muhammad) kepada-Ku (urusan) orang-orang yang mendustakan perkataan ini (Al Quran). Nanti Kami akan menarik mereka dengan berangsur-angsur (ke arah kebinasaan) dari arah yang tidak mereka ketahui,", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 45, "text": "وَأُمۡلِی لَهُمۡۚ إِنَّ كَیۡدِی مَتِینٌ ۝٤٥", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فذرني -أيها الرسول- ومَن يكذِّب بهذا القرآن، فإن عليَّ جزاءهم والانتقام منهم، سنمدهم بالأموال والأولاد والنعم؛ استدراجًا لهم من حيث لا يشعرون أنه سبب لإهلاكهم، وأُمهلهم وأُطيل أعمارهم؛ ليزدادوا إثمًا. إن كيدي بأهل الكفر قويٌّ شديد.", "isBasmala": false, "translation_en": "And I will give them respite. My plan is firm.", "translation_id": "dan Aku memberi tangguh kepada mereka. Sesungguhnya rencana-Ku amat tangguh.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 46, "text": "أَمۡ تَسۡـَٔلُهُمۡ أَجۡرࣰا فَهُم مِّن مَّغۡرَمࣲ مُّثۡقَلُونَ ۝٤٦", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "أم تسأل -أيها الرسول- هؤلاء المشركين أجرا دنيويا على تبليغ الرسالة فهم مِن غرامة ذلك مكلَّفون حِمْلا ثقيلا؟ بل أعندهم علم الغيب، فهم يكتبون عنه ما يحكمون به لأنفسهم مِن أنهم أفضل منزلة عند الله مِن أهل الإيمان به؟", "isBasmala": false, "translation_en": "Or do you ask them for a fee, so they are burdened with debt?", "translation_id": "Apakah kamu meminta upah kepada mereka, lalu mereka diberati dengan hutang?", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 47, "text": "أَمۡ عِندَهُمُ ٱلۡغَیۡبُ فَهُمۡ یَكۡتُبُونَ ۝٤٧", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "أم تسأل -أيها الرسول- هؤلاء المشركين أجرا دنيويا على تبليغ الرسالة فهم مِن غرامة ذلك مكلَّفون حِمْلا ثقيلا؟ بل أعندهم علم الغيب، فهم يكتبون عنه ما يحكمون به لأنفسهم مِن أنهم أفضل منزلة عند الله مِن أهل الإيمان به؟", "isBasmala": false, "translation_en": "Or do they know the future, and so they write it down?", "translation_id": "Ataukah ada pada mereka ilmu tentang yang ghaib lalu mereka menulis (padanya apa yang mereka tetapkan)?", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 48, "text": "فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومࣱ ۝٤٨", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فاصبر -أيها الرسول- لما حكم به ربك وقضاه، ومن ذلك إمهالهم وتأخير نصرتك عليهم، ولا تكن كصاحب الحوت، وهو يونس -عليه السلام- في غضبه وعدم صبره على قومه، حين نادى ربه، وهو مملوء غمًّا طالبًا تعجيل العذاب لهم، لولا أن تداركه نعمة مِن ربه بتوفيقه للتوبة وقَبولها لَطُرِح مِن بطن الحوت بالأرض الفضاء المهلكة، وهو آتٍ بما يلام عليه، فاصطفاه ربه لرسالته، فجعله من الصالحين الذين صلحت نياتهم وأعمالهم وأقوالهم.", "isBasmala": false, "translation_en": "So wait patiently for the Decision of your Lord, and do not be like the Fellow of the Fish who cried out in despair.", "translation_id": "Maka bersabarlah kamu (hai Muhammad) terhadap ketetapan Tuhanmu, dan janganlah kamu seperti orang yang berada dalam (perut) ikan ketika ia berdoa sedang ia dalam keadaan marah (kepada kaumnya).", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 49, "text": "لَّوۡلَاۤ أَن تَدَ ٰرَكَهُۥ نِعۡمَةࣱ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَاۤءِ وَهُوَ مَذۡمُومࣱ ۝٤٩", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فاصبر -أيها الرسول- لما حكم به ربك وقضاه، ومن ذلك إمهالهم وتأخير نصرتك عليهم، ولا تكن كصاحب الحوت، وهو يونس -عليه السلام- في غضبه وعدم صبره على قومه، حين نادى ربه، وهو مملوء غمًّا طالبًا تعجيل العذاب لهم، لولا أن تداركه نعمة مِن ربه بتوفيقه للتوبة وقَبولها لَطُرِح مِن بطن الحوت بالأرض الفضاء المهلكة، وهو آتٍ بما يلام عليه، فاصطفاه ربه لرسالته، فجعله من الصالحين الذين صلحت نياتهم وأعمالهم وأقوالهم.", "isBasmala": false, "translation_en": "Were it not for his Lord's favor that reached him, he would have been thrown into the wilderness, fully despised.", "translation_id": "Kalau sekiranya ia tidak segera mendapat nikmat dari Tuhannya, benar-benar ia dicampakkan ke tanah tandus dalam keadaan tercela.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 50, "text": "فَٱجۡتَبَـٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّـٰلِحِینَ ۝٥٠", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "فاصبر -أيها الرسول- لما حكم به ربك وقضاه، ومن ذلك إمهالهم وتأخير نصرتك عليهم، ولا تكن كصاحب الحوت، وهو يونس -عليه السلام- في غضبه وعدم صبره على قومه، حين نادى ربه، وهو مملوء غمًّا طالبًا تعجيل العذاب لهم، لولا أن تداركه نعمة مِن ربه بتوفيقه للتوبة وقَبولها لَطُرِح مِن بطن الحوت بالأرض الفضاء المهلكة، وهو آتٍ بما يلام عليه، فاصطفاه ربه لرسالته، فجعله من الصالحين الذين صلحت نياتهم وأعمالهم وأقوالهم.", "isBasmala": false, "translation_en": "But his Lord chose him, and made him one of the righteous.", "translation_id": "Lalu Tuhannya memilihnya dan menjadikannya termasuk orang-orang yang saleh.", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 51, "text": "وَإِن یَكَادُ ٱلَّذِینَ كَفَرُوا۟ لَیُزۡلِقُونَكَ بِأَبۡصَـٰرِهِمۡ لَمَّا سَمِعُوا۟ ٱلذِّكۡرَ وَیَقُولُونَ إِنَّهُۥ لَمَجۡنُونࣱ ۝٥١", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "وإن يكاد الكفار حين سمعوا القرآن ليصيبونك -أيها الرسول- بالعين؛ لبغضهم إياك، لولا وقاية الله وحمايته لك، ويقولون: -حسب أهوائهم- إنه لمجنون.", "isBasmala": false, "translation_en": "Those who disbelieve almost stab you with their glances when they hear the message, and say, \"He is crazy!\"", "translation_id": "Dan sesungguhnya orang-orang kafir itu benar-benar hampir menggelincirkan kamu dengan pandangan mereka, tatkala mereka mendengar Al Quran dan mereka berkata: \"Sesungguhnya ia (Muhammad) benar-benar orang yang gila\".", "manzil": 7, "manzil_display": ""}, {"sura": 68, "sura_name": "القلم", "revelation": "Makkiyah", "aya": 52, "text": "وَمَا هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَـٰلَمِینَ ۝٥٢", "juz": 29, "hizb": "(*¼ ح 57*)", "tafsir": "وما القرآن إلا موعظة وتذكير للعالمين من الإنس والجن.", "isBasmala": false, "translation_en": "But it is no less than a reminder to all the Worlds.", "translation_id": "Dan Al Quran itu tidak lain hanyalah peringatan bagi seluruh umat.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 1, "text": "۞ ٱلۡحَاۤقَّةُ ۝١", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "القيامة الواقعة حقًّا التي يتحقق فيها الوعد والوعيد، ما القيامة الواقعة حقًّا في صفتها وحالها؟ وأي شيء أدراك -أيها الرسول- وعَرَّفك حقيقة القيامة، وصَوَّر لك هولها وشدتها؟", "isBasmala": false, "translation_en": "The Reality.", "translation_id": "Hari kiamat,", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 2, "text": "مَا ٱلۡحَاۤقَّةُ ۝٢", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "القيامة الواقعة حقًّا التي يتحقق فيها الوعد والوعيد، ما القيامة الواقعة حقًّا في صفتها وحالها؟ وأي شيء أدراك -أيها الرسول- وعَرَّفك حقيقة القيامة، وصَوَّر لك هولها وشدتها؟", "isBasmala": false, "translation_en": "What is the Reality?", "translation_id": "apakah hari kiamat itu?", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 3, "text": "وَمَاۤ أَدۡرَىٰكَ مَا ٱلۡحَاۤقَّةُ ۝٣", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "القيامة الواقعة حقًّا التي يتحقق فيها الوعد والوعيد، ما القيامة الواقعة حقًّا في صفتها وحالها؟ وأي شيء أدراك -أيها الرسول- وعَرَّفك حقيقة القيامة، وصَوَّر لك هولها وشدتها؟", "isBasmala": false, "translation_en": "What will make you understand what the Reality is?", "translation_id": "Dan tahukah kamu apakah hari kiamat itu?", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 4, "text": "كَذَّبَتۡ ثَمُودُ وَعَادُۢ بِٱلۡقَارِعَةِ ۝٤", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "كذَّبت ثمود، وهم قوم صالح، وعاد، وهم قوم هود بالقيامة التي تقرع القلوب بأهوالها.", "isBasmala": false, "translation_en": "Thamood and Aad denied the Catastrophe.", "translation_id": "Kaum Tsamud dan 'Aad telah mendustakan hari kiamat.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 5, "text": "فَأَمَّا ثَمُودُ فَأُهۡلِكُوا۟ بِٱلطَّاغِیَةِ ۝٥", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأما ثمود فأهلكوا بالصيحة العظيمة التي جاوزت الحد في شدتها، وأمَّا عاد فأُهلِكوا بريح باردة شديدة الهبوب، سلَّطها الله عليهم سبع ليال وثمانية أيام متتابعة، لا تَفْتُر ولا تنقطع، فترى القوم في تلك الليالي والأيام موتى كأنهم أصول نخل خَرِبة متآكلة الأجواف. فهل ترى لهؤلاء القوم مِن نفس باقية دون هلاك؟", "isBasmala": false, "translation_en": "As for Thamood, they were annihilated by the Overwhelming.", "translation_id": "Adapun kaum Tsamud, maka mereka telah dibinasakan dengan kejadian yang luar biasa.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 6, "text": "وَأَمَّا عَادࣱ فَأُهۡلِكُوا۟ بِرِیحࣲ صَرۡصَرٍ عَاتِیَةࣲ ۝٦", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأما ثمود فأهلكوا بالصيحة العظيمة التي جاوزت الحد في شدتها، وأمَّا عاد فأُهلِكوا بريح باردة شديدة الهبوب، سلَّطها الله عليهم سبع ليال وثمانية أيام متتابعة، لا تَفْتُر ولا تنقطع، فترى القوم في تلك الليالي والأيام موتى كأنهم أصول نخل خَرِبة متآكلة الأجواف. فهل ترى لهؤلاء القوم مِن نفس باقية دون هلاك؟", "isBasmala": false, "translation_en": "And as for Aad; they were annihilated by a furious, roaring wind.", "translation_id": "Adapun kaum 'Aad maka mereka telah dibinasakan dengan angin yang sangat dingin lagi amat kencang,", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 7, "text": "سَخَّرَهَا عَلَیۡهِمۡ سَبۡعَ لَیَالࣲ وَثَمَـٰنِیَةَ أَیَّامٍ حُسُومࣰاۖ فَتَرَى ٱلۡقَوۡمَ فِیهَا صَرۡعَىٰ كَأَنَّهُمۡ أَعۡجَازُ نَخۡلٍ خَاوِیَةࣲ ۝٧", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأما ثمود فأهلكوا بالصيحة العظيمة التي جاوزت الحد في شدتها، وأمَّا عاد فأُهلِكوا بريح باردة شديدة الهبوب، سلَّطها الله عليهم سبع ليال وثمانية أيام متتابعة، لا تَفْتُر ولا تنقطع، فترى القوم في تلك الليالي والأيام موتى كأنهم أصول نخل خَرِبة متآكلة الأجواف. فهل ترى لهؤلاء القوم مِن نفس باقية دون هلاك؟", "isBasmala": false, "translation_en": "He unleashed it upon them for seven nights and eight days, in succession. You could see the people tossed around, as though they were stumps of hollow palm-trees.", "translation_id": "yang Allah menimpakan angin itu kepada mereka selama tujuh malam dan delapan hari terus menerus; maka kamu lihat kaum 'Aad pada waktu itu mati bergelimpangan seakan-akan mereka tunggul pohon kurma yang telah kosong (lapuk).", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 8, "text": "فَهَلۡ تَرَىٰ لَهُم مِّنۢ بَاقِیَةࣲ ۝٨", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأما ثمود فأهلكوا بالصيحة العظيمة التي جاوزت الحد في شدتها، وأمَّا عاد فأُهلِكوا بريح باردة شديدة الهبوب، سلَّطها الله عليهم سبع ليال وثمانية أيام متتابعة، لا تَفْتُر ولا تنقطع، فترى القوم في تلك الليالي والأيام موتى كأنهم أصول نخل خَرِبة متآكلة الأجواف. فهل ترى لهؤلاء القوم مِن نفس باقية دون هلاك؟", "isBasmala": false, "translation_en": "Can you see any remnant of them?", "translation_id": "Maka kamu tidak melihat seorangpun yang tinggal di antara mereka.", "manzil": 7, "manzil_display": ""}], "567": [{"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 9, "text": "وَجَاۤءَ فِرۡعَوۡنُ وَمَن قَبۡلَهُۥ وَٱلۡمُؤۡتَفِكَـٰتُ بِٱلۡخَاطِئَةِ ۝٩", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "وجاء الطاغية فرعون، ومَن سبقه من الأمم التي كفرت برسلها، وأهل قرى قوم لوط الذين انقلبت بهم ديارهم بسبب الفعلة المنكرة من الكفر والشرك والفواحش، فعصت كل أمة منهم رسول ربهم الذي أرسله إليهم، فأخذهم الله أخذة بالغة في الشدة.", "isBasmala": false, "translation_en": "Then Pharaoh came, and those before him, and the Overturned Cities steeped in sin.", "translation_id": "Dan telah datang Fir'aun dan orang-orang yang sebelumnya dan (penduduk) negeri-negeri yang dijungkir balikkan karena kesalahan yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 10, "text": "فَعَصَوۡا۟ رَسُولَ رَبِّهِمۡ فَأَخَذَهُمۡ أَخۡذَةࣰ رَّابِیَةً ۝١٠", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "وجاء الطاغية فرعون، ومَن سبقه من الأمم التي كفرت برسلها، وأهل قرى قوم لوط الذين انقلبت بهم ديارهم بسبب الفعلة المنكرة من الكفر والشرك والفواحش، فعصت كل أمة منهم رسول ربهم الذي أرسله إليهم، فأخذهم الله أخذة بالغة في الشدة.", "isBasmala": false, "translation_en": "But they disobeyed the messenger of their Lord, so He seized them with an overpowering grip.", "translation_id": "Maka (masing-masing) mereka mendurhakai rasul Tuhan mereka, lalu Allah menyiksa mereka dengan siksaan yang sangat keras.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 11, "text": "إِنَّا لَمَّا طَغَا ٱلۡمَاۤءُ حَمَلۡنَـٰكُمۡ فِی ٱلۡجَارِیَةِ ۝١١", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "إنَّا لما جاوز الماء حدَّه، حتى علا وارتفع فوق كل شيء، حملنا أصولكم مع نوح في السفينة التي تجري في الماء؛ لنجعل الواقعة التي كان فيها نجاة المؤمنين وإغراق الكافرين عبرة وعظة، وتحفظها كل أذن مِن شأنها أن تحفظ، وتعقل عن الله ما سمعت.", "isBasmala": false, "translation_en": "When the waters overflowed, We carried you in the cruising ship.", "translation_id": "Sesungguhnya Kami, tatkala air telah naik (sampai ke gunung) Kami bawa (nenek moyang) kamu, ke dalam bahtera,", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 12, "text": "لِنَجۡعَلَهَا لَكُمۡ تَذۡكِرَةࣰ وَتَعِیَهَاۤ أُذُنࣱ وَ ٰعِیَةࣱ ۝١٢", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "إنَّا لما جاوز الماء حدَّه، حتى علا وارتفع فوق كل شيء، حملنا أصولكم مع نوح في السفينة التي تجري في الماء؛ لنجعل الواقعة التي كان فيها نجاة المؤمنين وإغراق الكافرين عبرة وعظة، وتحفظها كل أذن مِن شأنها أن تحفظ، وتعقل عن الله ما سمعت.", "isBasmala": false, "translation_en": "To make it a lesson for you-so that retaining ears may retain it.", "translation_id": "agar Kami jadikan peristiwa itu peringatan bagi kamu dan agar diperhatikan oleh telinga yang mau mendengar.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 13, "text": "فَإِذَا نُفِخَ فِی ٱلصُّورِ نَفۡخَةࣱ وَ ٰحِدَةࣱ ۝١٣", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فإذا نفخ المَلَك في \"القرن\" نفخة واحدة، وهي النفخة الأولى التي يكون عندها هلاك العالم، ورُفعت الأرض والجبال عن أماكنها فكُسِّرتا، ودُقَّتا دقة واحدة. ففي ذلك الحين قامت القيامة، وانصدعت السماء، فهي يومئذ ضعيفة مسترخية، لا تماسُك فيها ولا صلابة، والملائكة على جوانبها وأطرافها، ويحمل عرش ربك فوقهم يوم القيامة ثمانية من الملائكة العظام. في ذلك اليوم تُعرضون على الله- أيها الناس- للحساب والجزاء، لا يخفى عليه شيء من أسراركم.", "isBasmala": false, "translation_en": "Then, when the Trumpet is sounded a single time.", "translation_id": "Maka apabila sangkakala ditiup sekali tiup", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 14, "text": "وَحُمِلَتِ ٱلۡأَرۡضُ وَٱلۡجِبَالُ فَدُكَّتَا دَكَّةࣰ وَ ٰحِدَةࣰ ۝١٤", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فإذا نفخ المَلَك في \"القرن\" نفخة واحدة، وهي النفخة الأولى التي يكون عندها هلاك العالم، ورُفعت الأرض والجبال عن أماكنها فكُسِّرتا، ودُقَّتا دقة واحدة. ففي ذلك الحين قامت القيامة، وانصدعت السماء، فهي يومئذ ضعيفة مسترخية، لا تماسُك فيها ولا صلابة، والملائكة على جوانبها وأطرافها، ويحمل عرش ربك فوقهم يوم القيامة ثمانية من الملائكة العظام. في ذلك اليوم تُعرضون على الله- أيها الناس- للحساب والجزاء، لا يخفى عليه شيء من أسراركم.", "isBasmala": false, "translation_en": "And the earth and the mountains are lifted up, and crushed, with a single crush.", "translation_id": "dan diangkatlah bumi dan gunung-gunung, lalu dibenturkan keduanya sekali bentur.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 15, "text": "فَیَوۡمَىِٕذࣲ وَقَعَتِ ٱلۡوَاقِعَةُ ۝١٥", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فإذا نفخ المَلَك في \"القرن\" نفخة واحدة، وهي النفخة الأولى التي يكون عندها هلاك العالم، ورُفعت الأرض والجبال عن أماكنها فكُسِّرتا، ودُقَّتا دقة واحدة. ففي ذلك الحين قامت القيامة، وانصدعت السماء، فهي يومئذ ضعيفة مسترخية، لا تماسُك فيها ولا صلابة، والملائكة على جوانبها وأطرافها، ويحمل عرش ربك فوقهم يوم القيامة ثمانية من الملائكة العظام. في ذلك اليوم تُعرضون على الله- أيها الناس- للحساب والجزاء، لا يخفى عليه شيء من أسراركم.", "isBasmala": false, "translation_en": "On that Day, the Event will come to pass.", "translation_id": "Maka pada hari itu terjadilah hari kiamat,", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 16, "text": "وَٱنشَقَّتِ ٱلسَّمَاۤءُ فَهِیَ یَوۡمَىِٕذࣲ وَاهِیَةࣱ ۝١٦", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فإذا نفخ المَلَك في \"القرن\" نفخة واحدة، وهي النفخة الأولى التي يكون عندها هلاك العالم، ورُفعت الأرض والجبال عن أماكنها فكُسِّرتا، ودُقَّتا دقة واحدة. ففي ذلك الحين قامت القيامة، وانصدعت السماء، فهي يومئذ ضعيفة مسترخية، لا تماسُك فيها ولا صلابة، والملائكة على جوانبها وأطرافها، ويحمل عرش ربك فوقهم يوم القيامة ثمانية من الملائكة العظام. في ذلك اليوم تُعرضون على الله- أيها الناس- للحساب والجزاء، لا يخفى عليه شيء من أسراركم.", "isBasmala": false, "translation_en": "And the heaven will crack; so on that Day it will be frail.", "translation_id": "dan terbelahlah langit, karena pada hari itu langit menjadi lemah.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 17, "text": "وَٱلۡمَلَكُ عَلَىٰۤ أَرۡجَاۤىِٕهَاۚ وَیَحۡمِلُ عَرۡشَ رَبِّكَ فَوۡقَهُمۡ یَوۡمَىِٕذࣲ ثَمَـٰنِیَةࣱ ۝١٧", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فإذا نفخ المَلَك في \"القرن\" نفخة واحدة، وهي النفخة الأولى التي يكون عندها هلاك العالم، ورُفعت الأرض والجبال عن أماكنها فكُسِّرتا، ودُقَّتا دقة واحدة. ففي ذلك الحين قامت القيامة، وانصدعت السماء، فهي يومئذ ضعيفة مسترخية، لا تماسُك فيها ولا صلابة، والملائكة على جوانبها وأطرافها، ويحمل عرش ربك فوقهم يوم القيامة ثمانية من الملائكة العظام. في ذلك اليوم تُعرضون على الله- أيها الناس- للحساب والجزاء، لا يخفى عليه شيء من أسراركم.", "isBasmala": false, "translation_en": "And the angels will be ranged around its borders, while eight will be carrying the Throne of your Lord above them that Day.", "translation_id": "Dan malaikat-malaikat berada di penjuru-penjuru langit. Dan pada hari itu delapan orang malaikat menjunjung 'Arsy Tuhanmu di atas (kepala) mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 18, "text": "یَوۡمَىِٕذࣲ تُعۡرَضُونَ لَا تَخۡفَىٰ مِنكُمۡ خَافِیَةࣱ ۝١٨", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فإذا نفخ المَلَك في \"القرن\" نفخة واحدة، وهي النفخة الأولى التي يكون عندها هلاك العالم، ورُفعت الأرض والجبال عن أماكنها فكُسِّرتا، ودُقَّتا دقة واحدة. ففي ذلك الحين قامت القيامة، وانصدعت السماء، فهي يومئذ ضعيفة مسترخية، لا تماسُك فيها ولا صلابة، والملائكة على جوانبها وأطرافها، ويحمل عرش ربك فوقهم يوم القيامة ثمانية من الملائكة العظام. في ذلك اليوم تُعرضون على الله- أيها الناس- للحساب والجزاء، لا يخفى عليه شيء من أسراركم.", "isBasmala": false, "translation_en": "On that Day you will be exposed, and no secret of yours will remain hidden.", "translation_id": "Pada hari itu kamu dihadapkan (kepada Tuhanmu), tiada sesuatupun dari keadaanmu yang tersembunyi (bagi Allah).", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 19, "text": "فَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ بِیَمِینِهِۦ فَیَقُولُ هَاۤؤُمُ ٱقۡرَءُوا۟ كِتَـٰبِیَهۡ ۝١٩", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأمَّا من أُعطي كتاب أعماله بيمينه، فيقول ابتهاجًا وسرورًا: خذوا اقرؤوا كتابي، إني أيقنت في الدنيا بأني سألقى جزائي يوم القيامة، فأعددت له العدة من الإيمان والعمل الصالح، فهو في عيشة هنيئة مرضية، في جنة مرتفعة المكان والدرجات، ثمارها قريبة يتناولها القائم والقاعد والمضطجع. يقال لهم: كلوا أكلا واشربوا شربًا بعيدًا عن كل أذى، سالمين من كل مكروه؛ بسبب ما قدَّمتم من الأعمال الصالحة في أيام الدنيا الماضية.", "isBasmala": false, "translation_en": "As for him who is given his book in his right hand, he will say, \"Here, take my book and read it.", "translation_id": "Adapun orang-orang yang diberikan kepadanya kitabnya dari sebelah kanannya, maka dia berkata: \"Ambillah, bacalah kitabku (ini)\".", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 20, "text": "إِنِّی ظَنَنتُ أَنِّی مُلَـٰقٍ حِسَابِیَهۡ ۝٢٠", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأمَّا من أُعطي كتاب أعماله بيمينه، فيقول ابتهاجًا وسرورًا: خذوا اقرؤوا كتابي، إني أيقنت في الدنيا بأني سألقى جزائي يوم القيامة، فأعددت له العدة من الإيمان والعمل الصالح، فهو في عيشة هنيئة مرضية، في جنة مرتفعة المكان والدرجات، ثمارها قريبة يتناولها القائم والقاعد والمضطجع. يقال لهم: كلوا أكلا واشربوا شربًا بعيدًا عن كل أذى، سالمين من كل مكروه؛ بسبب ما قدَّمتم من الأعمال الصالحة في أيام الدنيا الماضية.", "isBasmala": false, "translation_en": "I knew I would be held accountable.\"", "translation_id": "Sesungguhnya aku yakin, bahwa sesungguhnya aku akan menemui hisab terhadap diriku.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 21, "text": "فَهُوَ فِی عِیشَةࣲ رَّاضِیَةࣲ ۝٢١", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأمَّا من أُعطي كتاب أعماله بيمينه، فيقول ابتهاجًا وسرورًا: خذوا اقرؤوا كتابي، إني أيقنت في الدنيا بأني سألقى جزائي يوم القيامة، فأعددت له العدة من الإيمان والعمل الصالح، فهو في عيشة هنيئة مرضية، في جنة مرتفعة المكان والدرجات، ثمارها قريبة يتناولها القائم والقاعد والمضطجع. يقال لهم: كلوا أكلا واشربوا شربًا بعيدًا عن كل أذى، سالمين من كل مكروه؛ بسبب ما قدَّمتم من الأعمال الصالحة في أيام الدنيا الماضية.", "isBasmala": false, "translation_en": "So he will be in pleasant living.", "translation_id": "Maka orang itu berada dalam kehidupan yang diridhai,", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 22, "text": "فِی جَنَّةٍ عَالِیَةࣲ ۝٢٢", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأمَّا من أُعطي كتاب أعماله بيمينه، فيقول ابتهاجًا وسرورًا: خذوا اقرؤوا كتابي، إني أيقنت في الدنيا بأني سألقى جزائي يوم القيامة، فأعددت له العدة من الإيمان والعمل الصالح، فهو في عيشة هنيئة مرضية، في جنة مرتفعة المكان والدرجات، ثمارها قريبة يتناولها القائم والقاعد والمضطجع. يقال لهم: كلوا أكلا واشربوا شربًا بعيدًا عن كل أذى، سالمين من كل مكروه؛ بسبب ما قدَّمتم من الأعمال الصالحة في أيام الدنيا الماضية.", "isBasmala": false, "translation_en": "In a lofty Garden.", "translation_id": "dalam surga yang tinggi,", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 23, "text": "قُطُوفُهَا دَانِیَةࣱ ۝٢٣", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأمَّا من أُعطي كتاب أعماله بيمينه، فيقول ابتهاجًا وسرورًا: خذوا اقرؤوا كتابي، إني أيقنت في الدنيا بأني سألقى جزائي يوم القيامة، فأعددت له العدة من الإيمان والعمل الصالح، فهو في عيشة هنيئة مرضية، في جنة مرتفعة المكان والدرجات، ثمارها قريبة يتناولها القائم والقاعد والمضطجع. يقال لهم: كلوا أكلا واشربوا شربًا بعيدًا عن كل أذى، سالمين من كل مكروه؛ بسبب ما قدَّمتم من الأعمال الصالحة في أيام الدنيا الماضية.", "isBasmala": false, "translation_en": "Its pickings are within reach.", "translation_id": "buah-buahannya dekat,", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 24, "text": "كُلُوا۟ وَٱشۡرَبُوا۟ هَنِیۤـَٔۢا بِمَاۤ أَسۡلَفۡتُمۡ فِی ٱلۡأَیَّامِ ٱلۡخَالِیَةِ ۝٢٤", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فأمَّا من أُعطي كتاب أعماله بيمينه، فيقول ابتهاجًا وسرورًا: خذوا اقرؤوا كتابي، إني أيقنت في الدنيا بأني سألقى جزائي يوم القيامة، فأعددت له العدة من الإيمان والعمل الصالح، فهو في عيشة هنيئة مرضية، في جنة مرتفعة المكان والدرجات، ثمارها قريبة يتناولها القائم والقاعد والمضطجع. يقال لهم: كلوا أكلا واشربوا شربًا بعيدًا عن كل أذى، سالمين من كل مكروه؛ بسبب ما قدَّمتم من الأعمال الصالحة في أيام الدنيا الماضية.", "isBasmala": false, "translation_en": "\"Eat and drink merrily for what you did in the days gone by.\"", "translation_id": "(kepada mereka dikatakan): \"Makan dan minumlah dengan sedap disebabkan amal yang telah kamu kerjakan pada hari-hari yang telah lalu\".", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 25, "text": "وَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ بِشِمَالِهِۦ فَیَقُولُ یَـٰلَیۡتَنِی لَمۡ أُوتَ كِتَـٰبِیَهۡ ۝٢٥", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "وَأمَّا من أعطي كتاب أعماله بشماله، فيقول نادمًا متحسرًا: يا ليتني لم أُعط كتابي، ولم أعلم ما جزائي؟ يا ليت الموتة التي متُّها في الدنيا كانت القاطعة لأمري، ولم أُبعث بعدها، ما نفعني مالي الذي جمعته في الدنيا، ذهبت عني حجتي، ولم يَعُدْ لي حجة أحتج بها.", "isBasmala": false, "translation_en": "But as for him who is given his book in his left hand, he will say, \"I wish I was never given my book.", "translation_id": "Adapun orang yang diberikan kepadanya kitabnya dari sebelah kirinya, maka dia berkata: \"Wahai alangkah baiknya kiranya tidak diberikan kepadaku kitabku (ini).", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 26, "text": "وَلَمۡ أَدۡرِ مَا حِسَابِیَهۡ ۝٢٦", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "وَأمَّا من أعطي كتاب أعماله بشماله، فيقول نادمًا متحسرًا: يا ليتني لم أُعط كتابي، ولم أعلم ما جزائي؟ يا ليت الموتة التي متُّها في الدنيا كانت القاطعة لأمري، ولم أُبعث بعدها، ما نفعني مالي الذي جمعته في الدنيا، ذهبت عني حجتي، ولم يَعُدْ لي حجة أحتج بها.", "isBasmala": false, "translation_en": "And never knew what my account was.", "translation_id": "Dan aku tidak mengetahui apa hisab terhadap diriku.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 27, "text": "یَـٰلَیۡتَهَا كَانَتِ ٱلۡقَاضِیَةَ ۝٢٧", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "وَأمَّا من أعطي كتاب أعماله بشماله، فيقول نادمًا متحسرًا: يا ليتني لم أُعط كتابي، ولم أعلم ما جزائي؟ يا ليت الموتة التي متُّها في الدنيا كانت القاطعة لأمري، ولم أُبعث بعدها، ما نفعني مالي الذي جمعته في الدنيا، ذهبت عني حجتي، ولم يَعُدْ لي حجة أحتج بها.", "isBasmala": false, "translation_en": "If only it was the end.", "translation_id": "Wahai kiranya kematian itulah yang menyelesaikan segala sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 28, "text": "مَاۤ أَغۡنَىٰ عَنِّی مَالِیَهۡۜ ۝٢٨", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "وَأمَّا من أعطي كتاب أعماله بشماله، فيقول نادمًا متحسرًا: يا ليتني لم أُعط كتابي، ولم أعلم ما جزائي؟ يا ليت الموتة التي متُّها في الدنيا كانت القاطعة لأمري، ولم أُبعث بعدها، ما نفعني مالي الذي جمعته في الدنيا، ذهبت عني حجتي، ولم يَعُدْ لي حجة أحتج بها.", "isBasmala": false, "translation_en": "My money cannot avail me.", "translation_id": "Hartaku sekali-kali tidak memberi manfaat kepadaku.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 29, "text": "هَلَكَ عَنِّی سُلۡطَـٰنِیَهۡ ۝٢٩", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "وَأمَّا من أعطي كتاب أعماله بشماله، فيقول نادمًا متحسرًا: يا ليتني لم أُعط كتابي، ولم أعلم ما جزائي؟ يا ليت الموتة التي متُّها في الدنيا كانت القاطعة لأمري، ولم أُبعث بعدها، ما نفعني مالي الذي جمعته في الدنيا، ذهبت عني حجتي، ولم يَعُدْ لي حجة أحتج بها.", "isBasmala": false, "translation_en": "My power has vanished from me.\"", "translation_id": "Telah hilang kekuasaanku daripadaku\".", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 30, "text": "خُذُوهُ فَغُلُّوهُ ۝٣٠", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يقال لخزنة جهنم: خذوا هذا المجرم الأثيم، فاجمعوا يديه إلى عنقه بالأغلال، ثم أدخلوه الجحيم ليقاسي حرها، ثم في سلسلة من حديد طولها سبعون ذراعًا فأدخلوه فيها؛ إنه كان لا يصدِّق بأن الله هو الإله الحق وحده لا شريك له، ولا يعمل بهديه، ولا يحث الناس في الدنيا على إطعام أهل الحاجة من المساكين وغيرهم.", "isBasmala": false, "translation_en": "\"Take him and shackle him.", "translation_id": "(Allah berfirman): \"Peganglah dia lalu belenggulah tangannya ke lehernya.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 31, "text": "ثُمَّ ٱلۡجَحِیمَ صَلُّوهُ ۝٣١", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يقال لخزنة جهنم: خذوا هذا المجرم الأثيم، فاجمعوا يديه إلى عنقه بالأغلال، ثم أدخلوه الجحيم ليقاسي حرها، ثم في سلسلة من حديد طولها سبعون ذراعًا فأدخلوه فيها؛ إنه كان لا يصدِّق بأن الله هو الإله الحق وحده لا شريك له، ولا يعمل بهديه، ولا يحث الناس في الدنيا على إطعام أهل الحاجة من المساكين وغيرهم.", "isBasmala": false, "translation_en": "Then scorch him in the Blaze.", "translation_id": "Kemudian masukkanlah dia ke dalam api neraka yang menyala-nyala.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 32, "text": "ثُمَّ فِی سِلۡسِلَةࣲ ذَرۡعُهَا سَبۡعُونَ ذِرَاعࣰا فَٱسۡلُكُوهُ ۝٣٢", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يقال لخزنة جهنم: خذوا هذا المجرم الأثيم، فاجمعوا يديه إلى عنقه بالأغلال، ثم أدخلوه الجحيم ليقاسي حرها، ثم في سلسلة من حديد طولها سبعون ذراعًا فأدخلوه فيها؛ إنه كان لا يصدِّق بأن الله هو الإله الحق وحده لا شريك له، ولا يعمل بهديه، ولا يحث الناس في الدنيا على إطعام أهل الحاجة من المساكين وغيرهم.", "isBasmala": false, "translation_en": "Then in a chain which length is seventy cubits tie him up.", "translation_id": "Kemudian belitlah dia dengan rantai yang panjangnya tujuh puluh hasta.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 33, "text": "إِنَّهُۥ كَانَ لَا یُؤۡمِنُ بِٱللَّهِ ٱلۡعَظِیمِ ۝٣٣", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يقال لخزنة جهنم: خذوا هذا المجرم الأثيم، فاجمعوا يديه إلى عنقه بالأغلال، ثم أدخلوه الجحيم ليقاسي حرها، ثم في سلسلة من حديد طولها سبعون ذراعًا فأدخلوه فيها؛ إنه كان لا يصدِّق بأن الله هو الإله الحق وحده لا شريك له، ولا يعمل بهديه، ولا يحث الناس في الدنيا على إطعام أهل الحاجة من المساكين وغيرهم.", "isBasmala": false, "translation_en": "For he would not believe in God the Great.", "translation_id": "Sesungguhnya dia dahulu tidak beriman kepada Allah Yang Maha Besar.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 34, "text": "وَلَا یَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِینِ ۝٣٤", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يقال لخزنة جهنم: خذوا هذا المجرم الأثيم، فاجمعوا يديه إلى عنقه بالأغلال، ثم أدخلوه الجحيم ليقاسي حرها، ثم في سلسلة من حديد طولها سبعون ذراعًا فأدخلوه فيها؛ إنه كان لا يصدِّق بأن الله هو الإله الحق وحده لا شريك له، ولا يعمل بهديه، ولا يحث الناس في الدنيا على إطعام أهل الحاجة من المساكين وغيرهم.", "isBasmala": false, "translation_en": "Nor would he advocate the feeding of the destitute.", "translation_id": "Dan juga dia tidak mendorong (orang lain) untuk memberi makan orang miskin.", "manzil": 7, "manzil_display": ""}], "568": [{"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 35, "text": "فَلَیۡسَ لَهُ ٱلۡیَوۡمَ هَـٰهُنَا حَمِیمࣱ ۝٣٥", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فليس لهذا الكافر يوم القيامة قريب يدفع عنه العذاب، وليس له طعام إلا مِن صديد أهل النار، لا يأكله إلا المذنبون المصرُّون على الكفر بالله.", "isBasmala": false, "translation_en": "So he has no friend here today.", "translation_id": "Maka tiada seorang temanpun baginya pada hari ini di sini.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 36, "text": "وَلَا طَعَامٌ إِلَّا مِنۡ غِسۡلِینࣲ ۝٣٦", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فليس لهذا الكافر يوم القيامة قريب يدفع عنه العذاب، وليس له طعام إلا مِن صديد أهل النار، لا يأكله إلا المذنبون المصرُّون على الكفر بالله.", "isBasmala": false, "translation_en": "And no food except scum.", "translation_id": "Dan tiada (pula) makanan sedikitpun (baginya) kecuali dari darah dan nanah.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 37, "text": "لَّا یَأۡكُلُهُۥۤ إِلَّا ٱلۡخَـٰطِـُٔونَ ۝٣٧", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فليس لهذا الكافر يوم القيامة قريب يدفع عنه العذاب، وليس له طعام إلا مِن صديد أهل النار، لا يأكله إلا المذنبون المصرُّون على الكفر بالله.", "isBasmala": false, "translation_en": "Which only the sinners eat.\"", "translation_id": "Tidak ada yang memakannya kecuali orang-orang yang berdosa.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 38, "text": "فَلَاۤ أُقۡسِمُ بِمَا تُبۡصِرُونَ ۝٣٨", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فلا أقسم بما تبصرون من المرئيات، وما لا تبصرون مما غاب عنكم، إن القرآن لَكَلام الله، يتلوه رسول عظيم الشرف والفضل، وليس بقول شاعر كما تزعمون، قليلا ما تؤمنون، وليس بسجع كسجع الكهان، قليلا ما يكون منكم تذكُّر وتأمُّل للفرق بينهما، ولكنه كلام رب العالمين الذي أنزله على رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Indeed, I swear by what you see.", "translation_id": "Maka Aku bersumpah dengan apa yang kamu lihat.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 39, "text": "وَمَا لَا تُبۡصِرُونَ ۝٣٩", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فلا أقسم بما تبصرون من المرئيات، وما لا تبصرون مما غاب عنكم، إن القرآن لَكَلام الله، يتلوه رسول عظيم الشرف والفضل، وليس بقول شاعر كما تزعمون، قليلا ما تؤمنون، وليس بسجع كسجع الكهان، قليلا ما يكون منكم تذكُّر وتأمُّل للفرق بينهما، ولكنه كلام رب العالمين الذي أنزله على رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "And by what you do not see.", "translation_id": "Dan dengan apa yang tidak kamu lihat.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 40, "text": "إِنَّهُۥ لَقَوۡلُ رَسُولࣲ كَرِیمࣲ ۝٤٠", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فلا أقسم بما تبصرون من المرئيات، وما لا تبصرون مما غاب عنكم، إن القرآن لَكَلام الله، يتلوه رسول عظيم الشرف والفضل، وليس بقول شاعر كما تزعمون، قليلا ما تؤمنون، وليس بسجع كسجع الكهان، قليلا ما يكون منكم تذكُّر وتأمُّل للفرق بينهما، ولكنه كلام رب العالمين الذي أنزله على رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "It is the speech of a noble messenger.", "translation_id": "Sesungguhnya Al Quran itu adalah benar-benar wahyu (Allah yang diturunkan kepada) Rasul yang mulia,", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 41, "text": "وَمَا هُوَ بِقَوۡلِ شَاعِرࣲۚ قَلِیلࣰا مَّا تُؤۡمِنُونَ ۝٤١", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فلا أقسم بما تبصرون من المرئيات، وما لا تبصرون مما غاب عنكم، إن القرآن لَكَلام الله، يتلوه رسول عظيم الشرف والفضل، وليس بقول شاعر كما تزعمون، قليلا ما تؤمنون، وليس بسجع كسجع الكهان، قليلا ما يكون منكم تذكُّر وتأمُّل للفرق بينهما، ولكنه كلام رب العالمين الذي أنزله على رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "And it is not the speech of a poet-little do you believe.", "translation_id": "dan Al Quran itu bukanlah perkataan seorang penyair. Sedikit sekali kamu beriman kepadanya.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 42, "text": "وَلَا بِقَوۡلِ كَاهِنࣲۚ قَلِیلࣰا مَّا تَذَكَّرُونَ ۝٤٢", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فلا أقسم بما تبصرون من المرئيات، وما لا تبصرون مما غاب عنكم، إن القرآن لَكَلام الله، يتلوه رسول عظيم الشرف والفضل، وليس بقول شاعر كما تزعمون، قليلا ما تؤمنون، وليس بسجع كسجع الكهان، قليلا ما يكون منكم تذكُّر وتأمُّل للفرق بينهما، ولكنه كلام رب العالمين الذي أنزله على رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Nor is it the speech of a soothsayer-little do you take heed.", "translation_id": "Dan bukan pula perkataan tukang tenung. Sedikit sekali kamu mengambil pelajaran daripadanya.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 43, "text": "تَنزِیلࣱ مِّن رَّبِّ ٱلۡعَـٰلَمِینَ ۝٤٣", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فلا أقسم بما تبصرون من المرئيات، وما لا تبصرون مما غاب عنكم، إن القرآن لَكَلام الله، يتلوه رسول عظيم الشرف والفضل، وليس بقول شاعر كما تزعمون، قليلا ما تؤمنون، وليس بسجع كسجع الكهان، قليلا ما يكون منكم تذكُّر وتأمُّل للفرق بينهما، ولكنه كلام رب العالمين الذي أنزله على رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "It is a revelation from the Lord of the Worlds.", "translation_id": "Ia adalah wahyu yang diturunkan dari Tuhan semesta alam.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 44, "text": "وَلَوۡ تَقَوَّلَ عَلَیۡنَا بَعۡضَ ٱلۡأَقَاوِیلِ ۝٤٤", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ولو ادَّعى محمد علينا شيئًا لم نقله، لانتقمنا وأخذنا منه باليمين، ثم لقطعنا منه نياط قلبه، فلا يقدر أحد منكم أن يحجز عنه عقابنا. إن هذا القرآن لعظة للمتقين الذين يمتثلون أوامر الله ويجتنبون نواهيه.", "isBasmala": false, "translation_en": "Had he falsely attributed some statements to Us.", "translation_id": "Seandainya dia (Muhammad) mengadakan sebagian perkataan atas (nama) Kami,", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 45, "text": "لَأَخَذۡنَا مِنۡهُ بِٱلۡیَمِینِ ۝٤٥", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ولو ادَّعى محمد علينا شيئًا لم نقله، لانتقمنا وأخذنا منه باليمين، ثم لقطعنا منه نياط قلبه، فلا يقدر أحد منكم أن يحجز عنه عقابنا. إن هذا القرآن لعظة للمتقين الذين يمتثلون أوامر الله ويجتنبون نواهيه.", "isBasmala": false, "translation_en": "We would have seized him by the right arm.", "translation_id": "niscaya benar-benar Kami pegang dia pada tangan kanannya.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 46, "text": "ثُمَّ لَقَطَعۡنَا مِنۡهُ ٱلۡوَتِینَ ۝٤٦", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ولو ادَّعى محمد علينا شيئًا لم نقله، لانتقمنا وأخذنا منه باليمين، ثم لقطعنا منه نياط قلبه، فلا يقدر أحد منكم أن يحجز عنه عقابنا. إن هذا القرآن لعظة للمتقين الذين يمتثلون أوامر الله ويجتنبون نواهيه.", "isBasmala": false, "translation_en": "Then slashed his lifeline.", "translation_id": "Kemudian benar-benar Kami potong urat tali jantungnya.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 47, "text": "فَمَا مِنكُم مِّنۡ أَحَدٍ عَنۡهُ حَـٰجِزِینَ ۝٤٧", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ولو ادَّعى محمد علينا شيئًا لم نقله، لانتقمنا وأخذنا منه باليمين، ثم لقطعنا منه نياط قلبه، فلا يقدر أحد منكم أن يحجز عنه عقابنا. إن هذا القرآن لعظة للمتقين الذين يمتثلون أوامر الله ويجتنبون نواهيه.", "isBasmala": false, "translation_en": "And none of you could have restrained Us from him.", "translation_id": "Maka sekali-kali tidak ada seorangpun dari kamu yang dapat menghalangi (Kami), dari pemotongan urat nadi itu.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 48, "text": "وَإِنَّهُۥ لَتَذۡكِرَةࣱ لِّلۡمُتَّقِینَ ۝٤٨", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ولو ادَّعى محمد علينا شيئًا لم نقله، لانتقمنا وأخذنا منه باليمين، ثم لقطعنا منه نياط قلبه، فلا يقدر أحد منكم أن يحجز عنه عقابنا. إن هذا القرآن لعظة للمتقين الذين يمتثلون أوامر الله ويجتنبون نواهيه.", "isBasmala": false, "translation_en": "Surely, it is a message for the righteous.", "translation_id": "Dan sesungguhnya Al Quran itu benar-benar suatu pelajaran bagi orang-orang yang bertakwa.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 49, "text": "وَإِنَّا لَنَعۡلَمُ أَنَّ مِنكُم مُّكَذِّبِینَ ۝٤٩", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "إنا لَنعلم أنَّ مِنكم مَن يكذِّب بهذا القرآن مع وضوح آياته، وإن التكذيب به لندامة عظيمة على الكافرين به حين يرون عذابهم ويرون نعيم المؤمنين به، وإنه لحق ثابت ويقين لا شك فيه. فنزِّه الله سبحانه عما لا يليق بجلاله، واذكره باسمه العظيم.", "isBasmala": false, "translation_en": "And We know that some of you will reject it.", "translation_id": "Dan sesungguhnya Kami benar-benar mengetahui bahwa di antara kamu ada orang yang mendustakan(nya).", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 50, "text": "وَإِنَّهُۥ لَحَسۡرَةٌ عَلَى ٱلۡكَـٰفِرِینَ ۝٥٠", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "إنا لَنعلم أنَّ مِنكم مَن يكذِّب بهذا القرآن مع وضوح آياته، وإن التكذيب به لندامة عظيمة على الكافرين به حين يرون عذابهم ويرون نعيم المؤمنين به، وإنه لحق ثابت ويقين لا شك فيه. فنزِّه الله سبحانه عما لا يليق بجلاله، واذكره باسمه العظيم.", "isBasmala": false, "translation_en": "And it is surely a source of grief for the unbelievers.", "translation_id": "Dan sesungguhnya Al Quran itu benar-benar menjadi penyesalan bagi orang-orang kafir (di akhirat).", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 51, "text": "وَإِنَّهُۥ لَحَقُّ ٱلۡیَقِینِ ۝٥١", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "إنا لَنعلم أنَّ مِنكم مَن يكذِّب بهذا القرآن مع وضوح آياته، وإن التكذيب به لندامة عظيمة على الكافرين به حين يرون عذابهم ويرون نعيم المؤمنين به، وإنه لحق ثابت ويقين لا شك فيه. فنزِّه الله سبحانه عما لا يليق بجلاله، واذكره باسمه العظيم.", "isBasmala": false, "translation_en": "Yet it is the absolute truth.", "translation_id": "Dan sesungguhnya Al Quran itu benar-benar kebenaran yang diyakini.", "manzil": 7, "manzil_display": ""}, {"sura": 69, "sura_name": "الحاقة", "revelation": "Makkiyah", "aya": 52, "text": "فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِیمِ ۝٥٢", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "إنا لَنعلم أنَّ مِنكم مَن يكذِّب بهذا القرآن مع وضوح آياته، وإن التكذيب به لندامة عظيمة على الكافرين به حين يرون عذابهم ويرون نعيم المؤمنين به، وإنه لحق ثابت ويقين لا شك فيه. فنزِّه الله سبحانه عما لا يليق بجلاله، واذكره باسمه العظيم.", "isBasmala": false, "translation_en": "So glorify the name of your Lord, the Magnificent.", "translation_id": "Maka bertasbihlah dengan (menyebut) nama Tuhanmu Yang Maha Besar.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 1, "text": "سَأَلَ سَاۤىِٕلُۢ بِعَذَابࣲ وَاقِعࣲ ۝١", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "دعا داع من المشركين على نفسه وقومه بنزول العذاب عليهم، وهو واقع بهم يوم القيامة لا محالة، ليس له مانع يمنعه من الله ذي العلو والجلال، تصعد الملائكة وجبريل إليه تعالى في يوم كان مقداره خمسين ألف سنة من سني الدنيا، وهو على المؤمن مثل صلاة مكتوبة.", "isBasmala": false, "translation_en": "A questioner questioned the imminent torment.", "translation_id": "Seseorang telah meminta kedatangan azab yang akan menimpa,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 2, "text": "لِّلۡكَـٰفِرِینَ لَیۡسَ لَهُۥ دَافِعࣱ ۝٢", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "دعا داع من المشركين على نفسه وقومه بنزول العذاب عليهم، وهو واقع بهم يوم القيامة لا محالة، ليس له مانع يمنعه من الله ذي العلو والجلال، تصعد الملائكة وجبريل إليه تعالى في يوم كان مقداره خمسين ألف سنة من سني الدنيا، وهو على المؤمن مثل صلاة مكتوبة.", "isBasmala": false, "translation_en": "For the disbelievers; none can repel it.", "translation_id": "orang-orang kafir, yang tidak seorangpun dapat menolaknya,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 3, "text": "مِّنَ ٱللَّهِ ذِی ٱلۡمَعَارِجِ ۝٣", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "دعا داع من المشركين على نفسه وقومه بنزول العذاب عليهم، وهو واقع بهم يوم القيامة لا محالة، ليس له مانع يمنعه من الله ذي العلو والجلال، تصعد الملائكة وجبريل إليه تعالى في يوم كان مقداره خمسين ألف سنة من سني الدنيا، وهو على المؤمن مثل صلاة مكتوبة.", "isBasmala": false, "translation_en": "From God, Lord of the Ways of Ascent.", "translation_id": "(yang datang) dari Allah, Yang mempunyai tempat-tempat naik.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 4, "text": "تَعۡرُجُ ٱلۡمَلَـٰۤىِٕكَةُ وَٱلرُّوحُ إِلَیۡهِ فِی یَوۡمࣲ كَانَ مِقۡدَارُهُۥ خَمۡسِینَ أَلۡفَ سَنَةࣲ ۝٤", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "دعا داع من المشركين على نفسه وقومه بنزول العذاب عليهم، وهو واقع بهم يوم القيامة لا محالة، ليس له مانع يمنعه من الله ذي العلو والجلال، تصعد الملائكة وجبريل إليه تعالى في يوم كان مقداره خمسين ألف سنة من سني الدنيا، وهو على المؤمن مثل صلاة مكتوبة.", "isBasmala": false, "translation_en": "Unto Him the angels and the Spirit ascend on a Day the duration of which is fifty thousand years.", "translation_id": "Malaikat-malaikat dan Jibril naik (menghadap) kepada Tuhan dalam sehari yang kadarnya limapuluh ribu tahun.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 5, "text": "فَٱصۡبِرۡ صَبۡرࣰا جَمِیلًا ۝٥", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "فاصبر -أيها الرسول- على استهزائهم واستعجالهم العذاب، صبرًا لا جزع فيه، ولا شكوى منه لغير الله.", "isBasmala": false, "translation_en": "So be patient, with sweet patience.", "translation_id": "Maka bersabarlah kamu dengan sabar yang baik.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 6, "text": "إِنَّهُمۡ یَرَوۡنَهُۥ بَعِیدࣰا ۝٦", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "إن الكافرين يستبعدون العذاب ويرونه غير واقع، ونحن نراه واقعًا قريبًا لا محالة.", "isBasmala": false, "translation_en": "They see it distant.", "translation_id": "Sesungguhnya mereka memandang siksaaan itu jauh (mustahil).", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 7, "text": "وَنَرَىٰهُ قَرِیبࣰا ۝٧", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "إن الكافرين يستبعدون العذاب ويرونه غير واقع، ونحن نراه واقعًا قريبًا لا محالة.", "isBasmala": false, "translation_en": "But We see it near.", "translation_id": "Sedangkan Kami memandangnya dekat (mungkin terjadi).", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 8, "text": "یَوۡمَ تَكُونُ ٱلسَّمَاۤءُ كَٱلۡمُهۡلِ ۝٨", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يوم تكون السماء سائلة مثل حُثالة الزيت، وتكون الجبال كالصوف المصبوغ المنفوش الذي ذَرَتْه الريح.", "isBasmala": false, "translation_en": "On the Day when the sky will be like molten brass.", "translation_id": "Pada hari ketika langit menjadi seperti luluhan perak,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 9, "text": "وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ۝٩", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يوم تكون السماء سائلة مثل حُثالة الزيت، وتكون الجبال كالصوف المصبوغ المنفوش الذي ذَرَتْه الريح.", "isBasmala": false, "translation_en": "And the mountains will be like tufted wool.", "translation_id": "dan gunung-gunung menjadi seperti bulu (yang berterbangan),", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 10, "text": "وَلَا یَسۡـَٔلُ حَمِیمٌ حَمِیمࣰا ۝١٠", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ولا يسأل قريب قريبه عن شأنه؛ لأن كل واحدٍ منهما مشغول بنفسه.", "isBasmala": false, "translation_en": "No friend will care about his friend.", "translation_id": "dan tidak ada seorang teman akrabpun menanyakan temannya,", "manzil": 7, "manzil_display": ""}], "569": [{"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 11, "text": "یُبَصَّرُونَهُمۡۚ یَوَدُّ ٱلۡمُجۡرِمُ لَوۡ یَفۡتَدِی مِنۡ عَذَابِ یَوۡمِىِٕذِۭ بِبَنِیهِ ۝١١", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يرونهم ويعرفونهم، ولا يستطيع أحد أن ينفع أحدًا. يتمنى الكافر لو يفدي نفسه من عذاب يوم القيامة بأبنائه، وزوجه وأخيه، وعشيرته التي تضمه وينتمي إليها في القرابة، وبجميع مَن في الأرض مِنَ البشر وغيرهم، ثم ينجو من عذاب الله.", "isBasmala": false, "translation_en": "They will be shown each other. The criminal wishes he would be redeemed from the punishment of that Day by his children.", "translation_id": "sedang mereka saling memandang. Orang kafir ingin kalau sekiranya dia dapat menebus (dirinya) dari azab hari itu dengan anak-anaknya,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 12, "text": "وَصَـٰحِبَتِهِۦ وَأَخِیهِ ۝١٢", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يرونهم ويعرفونهم، ولا يستطيع أحد أن ينفع أحدًا. يتمنى الكافر لو يفدي نفسه من عذاب يوم القيامة بأبنائه، وزوجه وأخيه، وعشيرته التي تضمه وينتمي إليها في القرابة، وبجميع مَن في الأرض مِنَ البشر وغيرهم، ثم ينجو من عذاب الله.", "isBasmala": false, "translation_en": "And his spouse, and his brother.", "translation_id": "dan isterinya dan saudaranya,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 13, "text": "وَفَصِیلَتِهِ ٱلَّتِی تُـٔۡوِیهِ ۝١٣", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يرونهم ويعرفونهم، ولا يستطيع أحد أن ينفع أحدًا. يتمنى الكافر لو يفدي نفسه من عذاب يوم القيامة بأبنائه، وزوجه وأخيه، وعشيرته التي تضمه وينتمي إليها في القرابة، وبجميع مَن في الأرض مِنَ البشر وغيرهم، ثم ينجو من عذاب الله.", "isBasmala": false, "translation_en": "And his family that sheltered him.", "translation_id": "dan kaum familinya yang melindunginya (di dunia).", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 14, "text": "وَمَن فِی ٱلۡأَرۡضِ جَمِیعࣰا ثُمَّ یُنجِیهِ ۝١٤", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "يرونهم ويعرفونهم، ولا يستطيع أحد أن ينفع أحدًا. يتمنى الكافر لو يفدي نفسه من عذاب يوم القيامة بأبنائه، وزوجه وأخيه، وعشيرته التي تضمه وينتمي إليها في القرابة، وبجميع مَن في الأرض مِنَ البشر وغيرهم، ثم ينجو من عذاب الله.", "isBasmala": false, "translation_en": "And everyone on earth, in order to save him.", "translation_id": "Dan orang-orang di atas bumi seluruhnya kemudian (mengharapkan) tebusan itu dapat menyelamatkannya.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 15, "text": "كَلَّاۤۖ إِنَّهَا لَظَىٰ ۝١٥", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ليس الأمر كما تتمناه- أيها الكافر- من الافتداء، إنها جهنم تتلظى نارها وتلتهب، تنزع بشدة حرها جلدة الرأس وسائر أطراف البدن، تنادي مَن أعرض عن الحق في الدنيا، وترك طاعة الله ورسوله، وجمع المال، فوضعه في خزائنه، ولم يؤدِّ حق الله فيه.", "isBasmala": false, "translation_en": "By no means! It is a Raging Fire.", "translation_id": "Sekali-kali tidak dapat, sesungguhnya neraka itu adalah api yang bergolak,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 16, "text": "نَزَّاعَةࣰ لِّلشَّوَىٰ ۝١٦", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ليس الأمر كما تتمناه- أيها الكافر- من الافتداء، إنها جهنم تتلظى نارها وتلتهب، تنزع بشدة حرها جلدة الرأس وسائر أطراف البدن، تنادي مَن أعرض عن الحق في الدنيا، وترك طاعة الله ورسوله، وجمع المال، فوضعه في خزائنه، ولم يؤدِّ حق الله فيه.", "isBasmala": false, "translation_en": "It strips away the scalps.", "translation_id": "yang mengelupas kulit kepala,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 17, "text": "تَدۡعُوا۟ مَنۡ أَدۡبَرَ وَتَوَلَّىٰ ۝١٧", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ليس الأمر كما تتمناه- أيها الكافر- من الافتداء، إنها جهنم تتلظى نارها وتلتهب، تنزع بشدة حرها جلدة الرأس وسائر أطراف البدن، تنادي مَن أعرض عن الحق في الدنيا، وترك طاعة الله ورسوله، وجمع المال، فوضعه في خزائنه، ولم يؤدِّ حق الله فيه.", "isBasmala": false, "translation_en": "It invites him who once turned his back and fled.", "translation_id": "yang memanggil orang yang membelakang dan yang berpaling (dari agama),", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 18, "text": "وَجَمَعَ فَأَوۡعَىٰۤ ۝١٨", "juz": 29, "hizb": "(*½ ح 57*)", "tafsir": "ليس الأمر كما تتمناه- أيها الكافر- من الافتداء، إنها جهنم تتلظى نارها وتلتهب، تنزع بشدة حرها جلدة الرأس وسائر أطراف البدن، تنادي مَن أعرض عن الحق في الدنيا، وترك طاعة الله ورسوله، وجمع المال، فوضعه في خزائنه، ولم يؤدِّ حق الله فيه.", "isBasmala": false, "translation_en": "And accumulated and hoarded.", "translation_id": "serta mengumpulkan (harta benda) lalu menyimpannya.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 19, "text": "۞ إِنَّ ٱلۡإِنسَـٰنَ خُلِقَ هَلُوعًا ۝١٩", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "Man was created restless.", "translation_id": "Sesungguhnya manusia diciptakan bersifat keluh kesah lagi kikir.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 20, "text": "إِذَا مَسَّهُ ٱلشَّرُّ جَزُوعࣰا ۝٢٠", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "Touched by adversity, he is fretful.", "translation_id": "Apabila ia ditimpa kesusahan ia berkeluh kesah,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 21, "text": "وَإِذَا مَسَّهُ ٱلۡخَیۡرُ مَنُوعًا ۝٢١", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "Touched by good, he is ungenerous.", "translation_id": "dan apabila ia mendapat kebaikan ia amat kikir,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 22, "text": "إِلَّا ٱلۡمُصَلِّینَ ۝٢٢", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "Except the prayerful.", "translation_id": "kecuali orang-orang yang mengerjakan shalat,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 23, "text": "ٱلَّذِینَ هُمۡ عَلَىٰ صَلَاتِهِمۡ دَاۤىِٕمُونَ ۝٢٣", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "Those who are constant at their prayers.", "translation_id": "yang mereka itu tetap mengerjakan shalatnya,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 24, "text": "وَٱلَّذِینَ فِیۤ أَمۡوَ ٰلِهِمۡ حَقࣱّ مَّعۡلُومࣱ ۝٢٤", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "And those in whose wealth is a rightful share.", "translation_id": "dan orang-orang yang dalam hartanya tersedia bagian tertentu,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 25, "text": "لِّلسَّاۤىِٕلِ وَٱلۡمَحۡرُومِ ۝٢٥", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "For the beggar and the deprived.", "translation_id": "bagi orang (miskin) yang meminta dan orang yang tidak mempunyai apa-apa (yang tidak mau meminta),", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 26, "text": "وَٱلَّذِینَ یُصَدِّقُونَ بِیَوۡمِ ٱلدِّینِ ۝٢٦", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "And those who affirm the Day of Judgment.", "translation_id": "dan orang-orang yang mempercayai hari pembalasan,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 27, "text": "وَٱلَّذِینَ هُم مِّنۡ عَذَابِ رَبِّهِم مُّشۡفِقُونَ ۝٢٧", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "And those who fear the punishment of their Lord.", "translation_id": "dan orang-orang yang takut terhadap azab Tuhannya.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 28, "text": "إِنَّ عَذَابَ رَبِّهِمۡ غَیۡرُ مَأۡمُونࣲ ۝٢٨", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "Their Lord's punishment is not to be taken for granted.", "translation_id": "Karena sesungguhnya azab Tuhan mereka tidak dapat orang merasa aman (dari kedatangannya).", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 29, "text": "وَٱلَّذِینَ هُمۡ لِفُرُوجِهِمۡ حَـٰفِظُونَ ۝٢٩", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "And those who guard their chastity.", "translation_id": "Dan orang-orang yang memelihara kemaluannya,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 30, "text": "إِلَّا عَلَىٰۤ أَزۡوَ ٰجِهِمۡ أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ فَإِنَّهُمۡ غَیۡرُ مَلُومِینَ ۝٣٠", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن الإنسان جُبِلَ على الجزع وشدة الحرص، إذا أصابه المكروه والعسر فهو كثير الجزع والأسى، وإذا أصابه الخير واليسر فهو كثير المنع والإمساك، إلا المقيمين للصلاة الذين يحافظون على أدائها في جميع الأوقات، ولا يَشْغَلهم عنها شاغل، والذين في أموالهم نصيب معيَّن فرضه الله عليهم، وهو الزكاة لمن يسألهم المعونة، ولمن يتعفف عن سؤالها، والذين يؤمنون بيوم الحساب والجزاء فيستعدون له بالأعمال الصالحة، والذين هم خائفون من عذاب الله. إن عذاب ربهم لا ينبغي أن يأمنه أحد. والذين هم حافظون لفروجهم عن كل ما حرَّم الله عليهم، إلا على أزواجهم وإمائهم، فإنهم غير مؤاخذين.", "isBasmala": false, "translation_en": "Except from their spouses or those living under their control, for then they are free of blame.", "translation_id": "kecuali terhadap isteri-isteri mereka atau budak-budak yang mereka miliki, maka sesungguhnya mereka dalam hal ini tiada tercela.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 31, "text": "فَمَنِ ٱبۡتَغَىٰ وَرَاۤءَ ذَ ٰلِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡعَادُونَ ۝٣١", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فمن طلب لقضاء شهوته غير الزوجات والمملوكات، فأولئك هم المتجاوزون الحلال إلى الحرام. والذين هم حافظون لأمانات الله، وأمانات العباد، وحافظون لعهودهم مع الله تعالى ومع العباد، والذين يؤدُّون شهاداتهم بالحق دون تغيير أو كتمان، والذين يحافظون على أداء الصلاة ولا يخلُّون بشيء من واجباتها. أولئك المتصفون بتلك الأوصاف الجليلة مستقرُّون في جنات النعيم، مكرمون فيها بكل أنواع التكريم.", "isBasmala": false, "translation_en": "But whoever seeks to go beyond that-these are the transgressors.", "translation_id": "Barangsiapa mencari yang di balik itu, maka mereka itulah orang-orang yang melampaui batas.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 32, "text": "وَٱلَّذِینَ هُمۡ لِأَمَـٰنَـٰتِهِمۡ وَعَهۡدِهِمۡ رَ ٰعُونَ ۝٣٢", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فمن طلب لقضاء شهوته غير الزوجات والمملوكات، فأولئك هم المتجاوزون الحلال إلى الحرام. والذين هم حافظون لأمانات الله، وأمانات العباد، وحافظون لعهودهم مع الله تعالى ومع العباد، والذين يؤدُّون شهاداتهم بالحق دون تغيير أو كتمان، والذين يحافظون على أداء الصلاة ولا يخلُّون بشيء من واجباتها. أولئك المتصفون بتلك الأوصاف الجليلة مستقرُّون في جنات النعيم، مكرمون فيها بكل أنواع التكريم.", "isBasmala": false, "translation_en": "And those who honor their trusts and their pledges.", "translation_id": "Dan orang-orang yang memelihara amanat-amanat (yang dipikulnya) dan janjinya.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 33, "text": "وَٱلَّذِینَ هُم بِشَهَـٰدَ ٰتِهِمۡ قَاۤىِٕمُونَ ۝٣٣", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فمن طلب لقضاء شهوته غير الزوجات والمملوكات، فأولئك هم المتجاوزون الحلال إلى الحرام. والذين هم حافظون لأمانات الله، وأمانات العباد، وحافظون لعهودهم مع الله تعالى ومع العباد، والذين يؤدُّون شهاداتهم بالحق دون تغيير أو كتمان، والذين يحافظون على أداء الصلاة ولا يخلُّون بشيء من واجباتها. أولئك المتصفون بتلك الأوصاف الجليلة مستقرُّون في جنات النعيم، مكرمون فيها بكل أنواع التكريم.", "isBasmala": false, "translation_en": "And those who stand by their testimonies.", "translation_id": "Dan orang-orang yang memberikan kesaksiannya.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 34, "text": "وَٱلَّذِینَ هُمۡ عَلَىٰ صَلَاتِهِمۡ یُحَافِظُونَ ۝٣٤", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فمن طلب لقضاء شهوته غير الزوجات والمملوكات، فأولئك هم المتجاوزون الحلال إلى الحرام. والذين هم حافظون لأمانات الله، وأمانات العباد، وحافظون لعهودهم مع الله تعالى ومع العباد، والذين يؤدُّون شهاداتهم بالحق دون تغيير أو كتمان، والذين يحافظون على أداء الصلاة ولا يخلُّون بشيء من واجباتها. أولئك المتصفون بتلك الأوصاف الجليلة مستقرُّون في جنات النعيم، مكرمون فيها بكل أنواع التكريم.", "isBasmala": false, "translation_en": "And those who are dedicated to their prayers.", "translation_id": "Dan orang-orang yang memelihara shalatnya.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 35, "text": "أُو۟لَـٰۤىِٕكَ فِی جَنَّـٰتࣲ مُّكۡرَمُونَ ۝٣٥", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فمن طلب لقضاء شهوته غير الزوجات والمملوكات، فأولئك هم المتجاوزون الحلال إلى الحرام. والذين هم حافظون لأمانات الله، وأمانات العباد، وحافظون لعهودهم مع الله تعالى ومع العباد، والذين يؤدُّون شهاداتهم بالحق دون تغيير أو كتمان، والذين يحافظون على أداء الصلاة ولا يخلُّون بشيء من واجباتها. أولئك المتصفون بتلك الأوصاف الجليلة مستقرُّون في جنات النعيم، مكرمون فيها بكل أنواع التكريم.", "isBasmala": false, "translation_en": "These will be honored in Gardens.", "translation_id": "Mereka itu (kekal) di surga lagi dimuliakan.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 36, "text": "فَمَالِ ٱلَّذِینَ كَفَرُوا۟ قِبَلَكَ مُهۡطِعِینَ ۝٣٦", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فأيُّ دافع دفع هؤلاء الكفرة إلى أن يسيروا نحوك -أيها الرسول- مسرعين، وقد مدُّوا أعناقهم إليك مقبلين بأبصارهم عليك، يتجمعون عن يمينك وعن شمالك حلقًا متعددة وجماعات متفرقة يتحدثون ويتعجبون؟ أيطمع كل واحد من هؤلاء الكفار أن يدخله الله جنة النعيم الدائم؟ ليس الأمر كما يطمعون، فإنهم لا يدخلونها أبدًا. إنَّا خلقناهم مما يعلمون مِن ماء مهين كغيرهم، فلم يؤمنوا، فمن أين يتشرفون بدخول جنة النعيم؟", "isBasmala": false, "translation_en": "What is with those who disbelieve, stretching their necks towards you.", "translation_id": "Mengapakah orang-orang kafir itu bersegera datang ke arahmu,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 37, "text": "عَنِ ٱلۡیَمِینِ وَعَنِ ٱلشِّمَالِ عِزِینَ ۝٣٧", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فأيُّ دافع دفع هؤلاء الكفرة إلى أن يسيروا نحوك -أيها الرسول- مسرعين، وقد مدُّوا أعناقهم إليك مقبلين بأبصارهم عليك، يتجمعون عن يمينك وعن شمالك حلقًا متعددة وجماعات متفرقة يتحدثون ويتعجبون؟ أيطمع كل واحد من هؤلاء الكفار أن يدخله الله جنة النعيم الدائم؟ ليس الأمر كما يطمعون، فإنهم لا يدخلونها أبدًا. إنَّا خلقناهم مما يعلمون مِن ماء مهين كغيرهم، فلم يؤمنوا، فمن أين يتشرفون بدخول جنة النعيم؟", "isBasmala": false, "translation_en": "From the right, and from the left, banding together?", "translation_id": "dari kanan dan dari kiri dengan berkelompok-kelompok.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 38, "text": "أَیَطۡمَعُ كُلُّ ٱمۡرِىࣲٕ مِّنۡهُمۡ أَن یُدۡخَلَ جَنَّةَ نَعِیمࣲ ۝٣٨", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فأيُّ دافع دفع هؤلاء الكفرة إلى أن يسيروا نحوك -أيها الرسول- مسرعين، وقد مدُّوا أعناقهم إليك مقبلين بأبصارهم عليك، يتجمعون عن يمينك وعن شمالك حلقًا متعددة وجماعات متفرقة يتحدثون ويتعجبون؟ أيطمع كل واحد من هؤلاء الكفار أن يدخله الله جنة النعيم الدائم؟ ليس الأمر كما يطمعون، فإنهم لا يدخلونها أبدًا. إنَّا خلقناهم مما يعلمون مِن ماء مهين كغيرهم، فلم يؤمنوا، فمن أين يتشرفون بدخول جنة النعيم؟", "isBasmala": false, "translation_en": "Is every one of them aspiring to be admitted into a Garden of Bliss?", "translation_id": "Adakah setiap orang dari orang-orang kafir itu ingin masuk ke dalam surga yang penuh kenikmatan?,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 39, "text": "كَلَّاۤۖ إِنَّا خَلَقۡنَـٰهُم مِّمَّا یَعۡلَمُونَ ۝٣٩", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فأيُّ دافع دفع هؤلاء الكفرة إلى أن يسيروا نحوك -أيها الرسول- مسرعين، وقد مدُّوا أعناقهم إليك مقبلين بأبصارهم عليك، يتجمعون عن يمينك وعن شمالك حلقًا متعددة وجماعات متفرقة يتحدثون ويتعجبون؟ أيطمع كل واحد من هؤلاء الكفار أن يدخله الله جنة النعيم الدائم؟ ليس الأمر كما يطمعون، فإنهم لا يدخلونها أبدًا. إنَّا خلقناهم مما يعلمون مِن ماء مهين كغيرهم، فلم يؤمنوا، فمن أين يتشرفون بدخول جنة النعيم؟", "isBasmala": false, "translation_en": "No indeed! We created them from what they know.", "translation_id": "sekali-kali tidak! Sesungguhnya Kami ciptakan mereka dari apa yang mereka ketahui (air mani).", "manzil": 7, "manzil_display": ""}], "570": [{"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 40, "text": "فَلَاۤ أُقۡسِمُ بِرَبِّ ٱلۡمَشَـٰرِقِ وَٱلۡمَغَـٰرِبِ إِنَّا لَقَـٰدِرُونَ ۝٤٠", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فلا أقسم برب مشارق الشمس والكواكب ومغاربها، إنا لقادرون على أن نستبدل بهم قومًا أفضل منهم وأطوع لله، وما أحد يسبقنا ويفوتنا ويعجزنا إذا أردنا أن نعيده.", "isBasmala": false, "translation_en": "I swear by the Lord of the Easts and the Wests, that We are Able.", "translation_id": "Maka aku bersumpah dengan Tuhan Yang memiliki timur dan barat, sesungguhnya Kami benar-benar Maha Kuasa.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 41, "text": "عَلَىٰۤ أَن نُّبَدِّلَ خَیۡرࣰا مِّنۡهُمۡ وَمَا نَحۡنُ بِمَسۡبُوقِینَ ۝٤١", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فلا أقسم برب مشارق الشمس والكواكب ومغاربها، إنا لقادرون على أن نستبدل بهم قومًا أفضل منهم وأطوع لله، وما أحد يسبقنا ويفوتنا ويعجزنا إذا أردنا أن نعيده.", "isBasmala": false, "translation_en": "To replace them with better than they, and We are not to be outdone.", "translation_id": "Untuk mengganti (mereka) dengan kaum yang lebih baik dari mereka, dan Kami sekali-kali tidak dapat dikalahkan.", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 42, "text": "فَذَرۡهُمۡ یَخُوضُوا۟ وَیَلۡعَبُوا۟ حَتَّىٰ یُلَـٰقُوا۟ یَوۡمَهُمُ ٱلَّذِی یُوعَدُونَ ۝٤٢", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فاتركهم يخوضوا في باطلهم، ويلعبوا في دنياهم حتى يلاقوا يوم القيامة الذي يوعدون فيه بالعذاب، يوم يخرجون من القبور مسرعين، كما كانوا في الدنيا يذهبون إلى آلهتهم التي اختلقوها للعبادة مِن دون الله، يهرولون ويسرعون، ذليلة أبصارهم منكسرة إلى الأرض، تغشاهم الحقارة والمهانة، ذلك هو اليوم الذي وعدوا به في الدنيا، وكانوا به يهزؤون ويُكَذِّبون.", "isBasmala": false, "translation_en": "So leave them to blunder and play, until they meet their Day which they are promised.", "translation_id": "Maka biarkanlah mereka tenggelam (dalam kebatilan) dan bermain-main sampai mereka menjumpai hari yang diancamkan kepada mereka,", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 43, "text": "یَوۡمَ یَخۡرُجُونَ مِنَ ٱلۡأَجۡدَاثِ سِرَاعࣰا كَأَنَّهُمۡ إِلَىٰ نُصُبࣲ یُوفِضُونَ ۝٤٣", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فاتركهم يخوضوا في باطلهم، ويلعبوا في دنياهم حتى يلاقوا يوم القيامة الذي يوعدون فيه بالعذاب، يوم يخرجون من القبور مسرعين، كما كانوا في الدنيا يذهبون إلى آلهتهم التي اختلقوها للعبادة مِن دون الله، يهرولون ويسرعون، ذليلة أبصارهم منكسرة إلى الأرض، تغشاهم الحقارة والمهانة، ذلك هو اليوم الذي وعدوا به في الدنيا، وكانوا به يهزؤون ويُكَذِّبون.", "isBasmala": false, "translation_en": "The Day when they will emerge from the tombs in a rush, as though they were hurrying towards a target.", "translation_id": "(yaitu) pada hari mereka keluar dari kubur dengan cepat seakan-akan mereka pergi dengan segera kepada berhala-berhala (sewaktu di dunia),", "manzil": 7, "manzil_display": ""}, {"sura": 70, "sura_name": "المعارج", "revelation": "Makkiyah", "aya": 44, "text": "خَـٰشِعَةً أَبۡصَـٰرُهُمۡ تَرۡهَقُهُمۡ ذِلَّةࣱۚ ذَ ٰلِكَ ٱلۡیَوۡمُ ٱلَّذِی كَانُوا۟ یُوعَدُونَ ۝٤٤", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "فاتركهم يخوضوا في باطلهم، ويلعبوا في دنياهم حتى يلاقوا يوم القيامة الذي يوعدون فيه بالعذاب، يوم يخرجون من القبور مسرعين، كما كانوا في الدنيا يذهبون إلى آلهتهم التي اختلقوها للعبادة مِن دون الله، يهرولون ويسرعون، ذليلة أبصارهم منكسرة إلى الأرض، تغشاهم الحقارة والمهانة، ذلك هو اليوم الذي وعدوا به في الدنيا، وكانوا به يهزؤون ويُكَذِّبون.", "isBasmala": false, "translation_en": "Their eyes cast down; overwhelmed by humiliation. This is the Day which they were promised.", "translation_id": "dalam keadaan mereka menekurkan pandangannya (serta) diliputi kehinaan. Itulah hari yang dahulunya diancamkan kepada mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 1, "text": "إِنَّاۤ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦۤ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن یَأۡتِیَهُمۡ عَذَابٌ أَلِیمࣱ ۝١", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إنا بعثنا نوحا إلى قومه، وقلنا له: حذِّر قومك من قبل أن يأتيهم عذاب موجع. قال نوح: يا قومي إني نذير لكم بيِّن الإنذار من عذاب الله إن عصيتموه، وإني رسول الله إليكم فاعبدوه وحده، وخافوا عقابه، وأطيعوني فيما آمركم به، وأنهاكم عنه، فإن أطعتموني واستجبتم لي يصفح الله عن ذنوبكم ويغفر لكم، ويُمدد في أعماركم إلى وقت مقدر في علم الله تعالى، إن الموت إذا جاء لا يؤخر أبدًا، لو كنتم تعلمون ذلك لسارعتم إلى الإيمان والطاعة.", "isBasmala": false, "translation_en": "We sent Noah to his people: \"Warn your people before there comes upon them a painful punishment.\"", "translation_id": "Sesungguhnya Kami telah mengutus Nuh kepada kaumnya (dengan memerintahkan): \"Berilah kaummu peringatan sebelum datang kepadanya azab yang pedih\",", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 2, "text": "قَالَ یَـٰقَوۡمِ إِنِّی لَكُمۡ نَذِیرࣱ مُّبِینٌ ۝٢", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إنا بعثنا نوحا إلى قومه، وقلنا له: حذِّر قومك من قبل أن يأتيهم عذاب موجع. قال نوح: يا قومي إني نذير لكم بيِّن الإنذار من عذاب الله إن عصيتموه، وإني رسول الله إليكم فاعبدوه وحده، وخافوا عقابه، وأطيعوني فيما آمركم به، وأنهاكم عنه، فإن أطعتموني واستجبتم لي يصفح الله عن ذنوبكم ويغفر لكم، ويُمدد في أعماركم إلى وقت مقدر في علم الله تعالى، إن الموت إذا جاء لا يؤخر أبدًا، لو كنتم تعلمون ذلك لسارعتم إلى الإيمان والطاعة.", "isBasmala": false, "translation_en": "He said, \"O my people, I am to you a clear warner.", "translation_id": "Nuh berkata: \"Hai kaumku, sesungguhnya aku adalah pemberi peringatan yang menjelaskan kepada kamu,", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 3, "text": "أَنِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُ وَأَطِیعُونِ ۝٣", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إنا بعثنا نوحا إلى قومه، وقلنا له: حذِّر قومك من قبل أن يأتيهم عذاب موجع. قال نوح: يا قومي إني نذير لكم بيِّن الإنذار من عذاب الله إن عصيتموه، وإني رسول الله إليكم فاعبدوه وحده، وخافوا عقابه، وأطيعوني فيما آمركم به، وأنهاكم عنه، فإن أطعتموني واستجبتم لي يصفح الله عن ذنوبكم ويغفر لكم، ويُمدد في أعماركم إلى وقت مقدر في علم الله تعالى، إن الموت إذا جاء لا يؤخر أبدًا، لو كنتم تعلمون ذلك لسارعتم إلى الإيمان والطاعة.", "isBasmala": false, "translation_en": "Worship God and reverence Him, and obey me.", "translation_id": "(yaitu) sembahlah olehmu Allah, bertakwalah kepada-Nya dan taatlah kepadaku,", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 4, "text": "یَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَیُؤَخِّرۡكُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَاۤءَ لَا یُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ ۝٤", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إنا بعثنا نوحا إلى قومه، وقلنا له: حذِّر قومك من قبل أن يأتيهم عذاب موجع. قال نوح: يا قومي إني نذير لكم بيِّن الإنذار من عذاب الله إن عصيتموه، وإني رسول الله إليكم فاعبدوه وحده، وخافوا عقابه، وأطيعوني فيما آمركم به، وأنهاكم عنه، فإن أطعتموني واستجبتم لي يصفح الله عن ذنوبكم ويغفر لكم، ويُمدد في أعماركم إلى وقت مقدر في علم الله تعالى، إن الموت إذا جاء لا يؤخر أبدًا، لو كنتم تعلمون ذلك لسارعتم إلى الإيمان والطاعة.", "isBasmala": false, "translation_en": "And He will forgive you of your sins, and reprieve you until a stated term. God's term cannot be deferred once it has arrived, if you only knew.\"", "translation_id": "niscaya Allah akan mengampuni sebagian dosa-dosamu dan menangguhkan kamu sampai kepada waktu yang ditentukan. Sesungguhnya ketetapan Allah apabila telah datang tidak dapat ditangguhkan, kalau kamu mengetahui\".", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 5, "text": "قَالَ رَبِّ إِنِّی دَعَوۡتُ قَوۡمِی لَیۡلࣰا وَنَهَارࣰا ۝٥", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: رب إني دعوت قومي إلى الإيمان بك وطاعتك في الليل والنهار، فلم يزدهم دعائي لهم إلى الإيمان إلا هربًا وإعراضًا عنه، وإني كلما دعوتهم إلى الإيمان بك؛ ليكون سببًا في غفرانك ذنوبهم، وضعوا أصابعهم في آذانهم؛ كي لا يسمعوا دعوة الحق، وتغطَّوا بثيابهم؛ كي لا يروني، وأقاموا على كفرهم، واستكبروا عن قَبول الإيمان استكبارًا شديدًا، ثم إني دعوتهم إلى الإيمان ظاهرًا علنًا في غير خفاء، ثم إني أعلنت لهم الدعوة بصوت مرتفع في حال، وأسررت بها بصوت خفيٍّ في حال أخرى، فقلت لقومي: سلوا ربكم غفران ذنوبكم، وتوبوا إليه من كفركم، إنه تعالى كان غفارًا لمن تاب من عباده ورجع إليه.", "isBasmala": false, "translation_en": "He said, \"My Lord, I have called my people night and day.", "translation_id": "Nuh berkata: \"Ya Tuhanku sesungguhnya aku telah menyeru kaumku malam dan siang,", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 6, "text": "فَلَمۡ یَزِدۡهُمۡ دُعَاۤءِیۤ إِلَّا فِرَارࣰا ۝٦", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: رب إني دعوت قومي إلى الإيمان بك وطاعتك في الليل والنهار، فلم يزدهم دعائي لهم إلى الإيمان إلا هربًا وإعراضًا عنه، وإني كلما دعوتهم إلى الإيمان بك؛ ليكون سببًا في غفرانك ذنوبهم، وضعوا أصابعهم في آذانهم؛ كي لا يسمعوا دعوة الحق، وتغطَّوا بثيابهم؛ كي لا يروني، وأقاموا على كفرهم، واستكبروا عن قَبول الإيمان استكبارًا شديدًا، ثم إني دعوتهم إلى الإيمان ظاهرًا علنًا في غير خفاء، ثم إني أعلنت لهم الدعوة بصوت مرتفع في حال، وأسررت بها بصوت خفيٍّ في حال أخرى، فقلت لقومي: سلوا ربكم غفران ذنوبكم، وتوبوا إليه من كفركم، إنه تعالى كان غفارًا لمن تاب من عباده ورجع إليه.", "isBasmala": false, "translation_en": "But my call added only to their flight.", "translation_id": "maka seruanku itu hanyalah menambah mereka lari (dari kebenaran).", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 7, "text": "وَإِنِّی كُلَّمَا دَعَوۡتُهُمۡ لِتَغۡفِرَ لَهُمۡ جَعَلُوۤا۟ أَصَـٰبِعَهُمۡ فِیۤ ءَاذَانِهِمۡ وَٱسۡتَغۡشَوۡا۟ ثِیَابَهُمۡ وَأَصَرُّوا۟ وَٱسۡتَكۡبَرُوا۟ ٱسۡتِكۡبَارࣰا ۝٧", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: رب إني دعوت قومي إلى الإيمان بك وطاعتك في الليل والنهار، فلم يزدهم دعائي لهم إلى الإيمان إلا هربًا وإعراضًا عنه، وإني كلما دعوتهم إلى الإيمان بك؛ ليكون سببًا في غفرانك ذنوبهم، وضعوا أصابعهم في آذانهم؛ كي لا يسمعوا دعوة الحق، وتغطَّوا بثيابهم؛ كي لا يروني، وأقاموا على كفرهم، واستكبروا عن قَبول الإيمان استكبارًا شديدًا، ثم إني دعوتهم إلى الإيمان ظاهرًا علنًا في غير خفاء، ثم إني أعلنت لهم الدعوة بصوت مرتفع في حال، وأسررت بها بصوت خفيٍّ في حال أخرى، فقلت لقومي: سلوا ربكم غفران ذنوبكم، وتوبوا إليه من كفركم، إنه تعالى كان غفارًا لمن تاب من عباده ورجع إليه.", "isBasmala": false, "translation_en": "Whenever I called them to Your forgiveness, they thrust their fingers into their ears, and wrapped themselves in their garments, and insisted, and became more and more arrogant.", "translation_id": "Dan sesungguhnya setiap kali aku menyeru mereka (kepada iman) agar Engkau mengampuni mereka, mereka memasukkan anak jari mereka ke dalam telinganya dan menutupkan bajunya (kemukanya) dan mereka tetap (mengingkari) dan menyombongkan diri dengan sangat.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 8, "text": "ثُمَّ إِنِّی دَعَوۡتُهُمۡ جِهَارࣰا ۝٨", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: رب إني دعوت قومي إلى الإيمان بك وطاعتك في الليل والنهار، فلم يزدهم دعائي لهم إلى الإيمان إلا هربًا وإعراضًا عنه، وإني كلما دعوتهم إلى الإيمان بك؛ ليكون سببًا في غفرانك ذنوبهم، وضعوا أصابعهم في آذانهم؛ كي لا يسمعوا دعوة الحق، وتغطَّوا بثيابهم؛ كي لا يروني، وأقاموا على كفرهم، واستكبروا عن قَبول الإيمان استكبارًا شديدًا، ثم إني دعوتهم إلى الإيمان ظاهرًا علنًا في غير خفاء، ثم إني أعلنت لهم الدعوة بصوت مرتفع في حال، وأسررت بها بصوت خفيٍّ في حال أخرى، فقلت لقومي: سلوا ربكم غفران ذنوبكم، وتوبوا إليه من كفركم، إنه تعالى كان غفارًا لمن تاب من عباده ورجع إليه.", "isBasmala": false, "translation_en": "Then I called them openly.", "translation_id": "Kemudian sesungguhnya aku telah menyeru mereka (kepada iman) dengan cara terang-terangan,", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 9, "text": "ثُمَّ إِنِّیۤ أَعۡلَنتُ لَهُمۡ وَأَسۡرَرۡتُ لَهُمۡ إِسۡرَارࣰا ۝٩", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: رب إني دعوت قومي إلى الإيمان بك وطاعتك في الليل والنهار، فلم يزدهم دعائي لهم إلى الإيمان إلا هربًا وإعراضًا عنه، وإني كلما دعوتهم إلى الإيمان بك؛ ليكون سببًا في غفرانك ذنوبهم، وضعوا أصابعهم في آذانهم؛ كي لا يسمعوا دعوة الحق، وتغطَّوا بثيابهم؛ كي لا يروني، وأقاموا على كفرهم، واستكبروا عن قَبول الإيمان استكبارًا شديدًا، ثم إني دعوتهم إلى الإيمان ظاهرًا علنًا في غير خفاء، ثم إني أعلنت لهم الدعوة بصوت مرتفع في حال، وأسررت بها بصوت خفيٍّ في حال أخرى، فقلت لقومي: سلوا ربكم غفران ذنوبكم، وتوبوا إليه من كفركم، إنه تعالى كان غفارًا لمن تاب من عباده ورجع إليه.", "isBasmala": false, "translation_en": "Then I appealed to them publicly, and I spoke to them privately.", "translation_id": "kemudian sesungguhnya aku (menyeru) mereka (lagi) dengan terang-terangan dan dengan diam-diam,", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 10, "text": "فَقُلۡتُ ٱسۡتَغۡفِرُوا۟ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارࣰا ۝١٠", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: رب إني دعوت قومي إلى الإيمان بك وطاعتك في الليل والنهار، فلم يزدهم دعائي لهم إلى الإيمان إلا هربًا وإعراضًا عنه، وإني كلما دعوتهم إلى الإيمان بك؛ ليكون سببًا في غفرانك ذنوبهم، وضعوا أصابعهم في آذانهم؛ كي لا يسمعوا دعوة الحق، وتغطَّوا بثيابهم؛ كي لا يروني، وأقاموا على كفرهم، واستكبروا عن قَبول الإيمان استكبارًا شديدًا، ثم إني دعوتهم إلى الإيمان ظاهرًا علنًا في غير خفاء، ثم إني أعلنت لهم الدعوة بصوت مرتفع في حال، وأسررت بها بصوت خفيٍّ في حال أخرى، فقلت لقومي: سلوا ربكم غفران ذنوبكم، وتوبوا إليه من كفركم، إنه تعالى كان غفارًا لمن تاب من عباده ورجع إليه.", "isBasmala": false, "translation_en": "I said, 'Ask your Lord for forgiveness; He is Forgiving.", "translation_id": "maka aku katakan kepada mereka: 'Mohonlah ampun kepada Tuhanmu, -sesungguhnya Dia adalah Maha Pengampun-,", "manzil": 7, "manzil_display": ""}], "571": [{"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 11, "text": "یُرۡسِلِ ٱلسَّمَاۤءَ عَلَیۡكُم مِّدۡرَارࣰا ۝١١", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن تتوبوا وتستغفروا يُنْزِلِ الله عليكم المطر غزيرًا متتابعًا، ويكثرْ أموالكم وأولادكم، ويجعلْ لكم حدائق تَنْعَمون بثمارها وجمالها، ويجعل لكم الأنهار التي تسقون منها زرعكم ومواشيكم. مالكم -أيها القوم- لا تخافون عظمة الله وسلطانه، وقد خلقكم في أطوار متدرجة: نطفة ثم علقة ثم مضغة ثم عظامًا ولحمًا؟ ألم تنظروا كيف خلق الله سبع سموات متطابقة بعضها فوق بعض، وجعل القمر في هذه السموات نورًا، وجعل الشمس مصباحًا مضيئًا يستضيء به أهل الأرض؟", "isBasmala": false, "translation_en": "He will let loose the sky upon you in torrents.", "translation_id": "niscaya Dia akan mengirimkan hujan kepadamu dengan lebat,", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 12, "text": "وَیُمۡدِدۡكُم بِأَمۡوَ ٰلࣲ وَبَنِینَ وَیَجۡعَل لَّكُمۡ جَنَّـٰتࣲ وَیَجۡعَل لَّكُمۡ أَنۡهَـٰرࣰا ۝١٢", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن تتوبوا وتستغفروا يُنْزِلِ الله عليكم المطر غزيرًا متتابعًا، ويكثرْ أموالكم وأولادكم، ويجعلْ لكم حدائق تَنْعَمون بثمارها وجمالها، ويجعل لكم الأنهار التي تسقون منها زرعكم ومواشيكم. مالكم -أيها القوم- لا تخافون عظمة الله وسلطانه، وقد خلقكم في أطوار متدرجة: نطفة ثم علقة ثم مضغة ثم عظامًا ولحمًا؟ ألم تنظروا كيف خلق الله سبع سموات متطابقة بعضها فوق بعض، وجعل القمر في هذه السموات نورًا، وجعل الشمس مصباحًا مضيئًا يستضيء به أهل الأرض؟", "isBasmala": false, "translation_en": "And provide you with wealth and children, and allot for you gardens, and allot for you rivers.", "translation_id": "dan membanyakkan harta dan anak-anakmu, dan mengadakan untukmu kebun-kebun dan mengadakan (pula di dalamnya) untukmu sungai-sungai.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 13, "text": "مَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارࣰا ۝١٣", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن تتوبوا وتستغفروا يُنْزِلِ الله عليكم المطر غزيرًا متتابعًا، ويكثرْ أموالكم وأولادكم، ويجعلْ لكم حدائق تَنْعَمون بثمارها وجمالها، ويجعل لكم الأنهار التي تسقون منها زرعكم ومواشيكم. مالكم -أيها القوم- لا تخافون عظمة الله وسلطانه، وقد خلقكم في أطوار متدرجة: نطفة ثم علقة ثم مضغة ثم عظامًا ولحمًا؟ ألم تنظروا كيف خلق الله سبع سموات متطابقة بعضها فوق بعض، وجعل القمر في هذه السموات نورًا، وجعل الشمس مصباحًا مضيئًا يستضيء به أهل الأرض؟", "isBasmala": false, "translation_en": "What is the matter with you, that you do not appreciate God's Greatness?", "translation_id": "Mengapa kamu tidak percaya akan kebesaran Allah?", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 14, "text": "وَقَدۡ خَلَقَكُمۡ أَطۡوَارًا ۝١٤", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن تتوبوا وتستغفروا يُنْزِلِ الله عليكم المطر غزيرًا متتابعًا، ويكثرْ أموالكم وأولادكم، ويجعلْ لكم حدائق تَنْعَمون بثمارها وجمالها، ويجعل لكم الأنهار التي تسقون منها زرعكم ومواشيكم. مالكم -أيها القوم- لا تخافون عظمة الله وسلطانه، وقد خلقكم في أطوار متدرجة: نطفة ثم علقة ثم مضغة ثم عظامًا ولحمًا؟ ألم تنظروا كيف خلق الله سبع سموات متطابقة بعضها فوق بعض، وجعل القمر في هذه السموات نورًا، وجعل الشمس مصباحًا مضيئًا يستضيء به أهل الأرض؟", "isBasmala": false, "translation_en": "Although He created you in stages.", "translation_id": "Padahal Dia sesungguhnya telah menciptakan kamu dalam beberapa tingkatan kejadian.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 15, "text": "أَلَمۡ تَرَوۡا۟ كَیۡفَ خَلَقَ ٱللَّهُ سَبۡعَ سَمَـٰوَ ٰتࣲ طِبَاقࣰا ۝١٥", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن تتوبوا وتستغفروا يُنْزِلِ الله عليكم المطر غزيرًا متتابعًا، ويكثرْ أموالكم وأولادكم، ويجعلْ لكم حدائق تَنْعَمون بثمارها وجمالها، ويجعل لكم الأنهار التي تسقون منها زرعكم ومواشيكم. مالكم -أيها القوم- لا تخافون عظمة الله وسلطانه، وقد خلقكم في أطوار متدرجة: نطفة ثم علقة ثم مضغة ثم عظامًا ولحمًا؟ ألم تنظروا كيف خلق الله سبع سموات متطابقة بعضها فوق بعض، وجعل القمر في هذه السموات نورًا، وجعل الشمس مصباحًا مضيئًا يستضيء به أهل الأرض؟", "isBasmala": false, "translation_en": "Do you not realize that God created seven heavens in layers?", "translation_id": "Tidakkah kamu perhatikan bagaimana Allah telah menciptakan tujuh langit bertingkat-tingkat?", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 16, "text": "وَجَعَلَ ٱلۡقَمَرَ فِیهِنَّ نُورࣰا وَجَعَلَ ٱلشَّمۡسَ سِرَاجࣰا ۝١٦", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "إن تتوبوا وتستغفروا يُنْزِلِ الله عليكم المطر غزيرًا متتابعًا، ويكثرْ أموالكم وأولادكم، ويجعلْ لكم حدائق تَنْعَمون بثمارها وجمالها، ويجعل لكم الأنهار التي تسقون منها زرعكم ومواشيكم. مالكم -أيها القوم- لا تخافون عظمة الله وسلطانه، وقد خلقكم في أطوار متدرجة: نطفة ثم علقة ثم مضغة ثم عظامًا ولحمًا؟ ألم تنظروا كيف خلق الله سبع سموات متطابقة بعضها فوق بعض، وجعل القمر في هذه السموات نورًا، وجعل الشمس مصباحًا مضيئًا يستضيء به أهل الأرض؟", "isBasmala": false, "translation_en": "And He set the moon in their midst for light, and He made the sun a lamp.", "translation_id": "Dan Allah menciptakan padanya bulan sebagai cahaya dan menjadikan matahari sebagai pelita?", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 17, "text": "وَٱللَّهُ أَنۢبَتَكُم مِّنَ ٱلۡأَرۡضِ نَبَاتࣰا ۝١٧", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "والله أنشأ أصلكم من الأرض إنشاء، ثم يعيدكم في الأرض بعد الموت، ويخرجكم يوم البعث إخراجًا محققًا. والله جعل لكم الأرض ممهدة كالبساط؛ لتسلكوا فيها طرقًا واسعة.", "isBasmala": false, "translation_en": "And God germinated you from the earth like plants.", "translation_id": "Dan Allah menumbuhkan kamu dari tanah dengan sebaik-baiknya,", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 18, "text": "ثُمَّ یُعِیدُكُمۡ فِیهَا وَیُخۡرِجُكُمۡ إِخۡرَاجࣰا ۝١٨", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "والله أنشأ أصلكم من الأرض إنشاء، ثم يعيدكم في الأرض بعد الموت، ويخرجكم يوم البعث إخراجًا محققًا. والله جعل لكم الأرض ممهدة كالبساط؛ لتسلكوا فيها طرقًا واسعة.", "isBasmala": false, "translation_en": "Then He will return you into it, and will bring you out again.", "translation_id": "kemudian Dia mengembalikan kamu ke dalam tanah dan mengeluarkan kamu (daripadanya pada hari kiamat) dengan sebenar-benarnya.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 19, "text": "وَٱللَّهُ جَعَلَ لَكُمُ ٱلۡأَرۡضَ بِسَاطࣰا ۝١٩", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "والله أنشأ أصلكم من الأرض إنشاء، ثم يعيدكم في الأرض بعد الموت، ويخرجكم يوم البعث إخراجًا محققًا. والله جعل لكم الأرض ممهدة كالبساط؛ لتسلكوا فيها طرقًا واسعة.", "isBasmala": false, "translation_en": "And God made the earth a spread for you.", "translation_id": "Dan Allah menjadikan bumi untukmu sebagai hamparan,", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 20, "text": "لِّتَسۡلُكُوا۟ مِنۡهَا سُبُلࣰا فِجَاجࣰا ۝٢٠", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "والله أنشأ أصلكم من الأرض إنشاء، ثم يعيدكم في الأرض بعد الموت، ويخرجكم يوم البعث إخراجًا محققًا. والله جعل لكم الأرض ممهدة كالبساط؛ لتسلكوا فيها طرقًا واسعة.", "isBasmala": false, "translation_en": "That you may travel its diverse roads.'\"", "translation_id": "supaya kamu menjalani jalan-jalan yang luas di bumi itu\".", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 21, "text": "قَالَ نُوحࣱ رَّبِّ إِنَّهُمۡ عَصَوۡنِی وَٱتَّبَعُوا۟ مَن لَّمۡ یَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥۤ إِلَّا خَسَارࣰا ۝٢١", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: ربِّ إن قومي بالغوا في عصياني وتكذيبي، واتبع الضعفاء منهم الرؤساء الضالين الذين لم تزدهم أموالهم وأولادهم إلا ضلالا في الدنيا وعقابًا في الآخرة، ومكر رؤساء الضلال بتابعيهم من الضعفاء مكرًا عظيمًا، وقالوا لهم: لا تتركوا عبادة آلهتكم إلى عبادة الله وحده، التي يدعو إليها نوح، ولا تتركوا وَدًّا ولا سُواعًا ولا يغوث ويعوق ونَسْرا - وهذه أسماء أصنامهم التي كانوا يعبدونها من دون الله، وكانت أسماء رجال صالحين، لما ماتوا أوحى الشيطان إلى قومهم أن يقيموا لهم التماثيل والصور؛ لينشطوا- بزعمهم- على الطاعة إذا رأوها، فلما ذهب هؤلاء القوم وطال الأمد، وخَلَفهم غيرهم، وسوس لهم الشيطان بأن أسلافهم كانوا يعبدون التماثيل والصور، ويتوسلون بها، وهذه هي الحكمة من تحريم التماثيل، وتحريم بناء القباب على القبور؛ لأنها تصير مع تطاول الزمن معبودة للجهال. وقد أضلَّ هؤلاء المتبوعون كثيرًا من الناس بما زيَّنوا لهم من طرق الغَواية والضلال. ثم قال نوح -عليه السلام-: ولا تزد- يا ربنا- هؤلاء الظالمين لأنفسهم بالكفر والعناد إلا بُعْدا عن الحق. فبسبب ذنوبهم وإصرارهم على الكفر والطغيان أُغرقوا بالطوفان، وأُدخلوا عقب الإغراق نارًا عظيمة اللهب والإحراق، فلم يجدوا من دون الله مَن ينصرهم، أو يدفع عنهم عذاب الله.", "isBasmala": false, "translation_en": "Noah said, \"My Lord, they have defied me, and followed him whose wealth and children increase him only in perdition.\"", "translation_id": "Nuh berkata: \"Ya Tuhanku, sesungguhnya mereka telah mendurhakaiku dan telah mengikuti orang-orang yang harta dan anak-anaknya tidak menambah kepadanya melainkan kerugian belaka,", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 22, "text": "وَمَكَرُوا۟ مَكۡرࣰا كُبَّارࣰا ۝٢٢", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: ربِّ إن قومي بالغوا في عصياني وتكذيبي، واتبع الضعفاء منهم الرؤساء الضالين الذين لم تزدهم أموالهم وأولادهم إلا ضلالا في الدنيا وعقابًا في الآخرة، ومكر رؤساء الضلال بتابعيهم من الضعفاء مكرًا عظيمًا، وقالوا لهم: لا تتركوا عبادة آلهتكم إلى عبادة الله وحده، التي يدعو إليها نوح، ولا تتركوا وَدًّا ولا سُواعًا ولا يغوث ويعوق ونَسْرا - وهذه أسماء أصنامهم التي كانوا يعبدونها من دون الله، وكانت أسماء رجال صالحين، لما ماتوا أوحى الشيطان إلى قومهم أن يقيموا لهم التماثيل والصور؛ لينشطوا- بزعمهم- على الطاعة إذا رأوها، فلما ذهب هؤلاء القوم وطال الأمد، وخَلَفهم غيرهم، وسوس لهم الشيطان بأن أسلافهم كانوا يعبدون التماثيل والصور، ويتوسلون بها، وهذه هي الحكمة من تحريم التماثيل، وتحريم بناء القباب على القبور؛ لأنها تصير مع تطاول الزمن معبودة للجهال. وقد أضلَّ هؤلاء المتبوعون كثيرًا من الناس بما زيَّنوا لهم من طرق الغَواية والضلال. ثم قال نوح -عليه السلام-: ولا تزد- يا ربنا- هؤلاء الظالمين لأنفسهم بالكفر والعناد إلا بُعْدا عن الحق. فبسبب ذنوبهم وإصرارهم على الكفر والطغيان أُغرقوا بالطوفان، وأُدخلوا عقب الإغراق نارًا عظيمة اللهب والإحراق، فلم يجدوا من دون الله مَن ينصرهم، أو يدفع عنهم عذاب الله.", "isBasmala": false, "translation_en": "And they schemed outrageous schemes.", "translation_id": "dan melakukan tipu-daya yang amat besar\".", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 23, "text": "وَقَالُوا۟ لَا تَذَرُنَّ ءَالِهَتَكُمۡ وَلَا تَذَرُنَّ وَدࣰّا وَلَا سُوَاعࣰا وَلَا یَغُوثَ وَیَعُوقَ وَنَسۡرࣰا ۝٢٣", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: ربِّ إن قومي بالغوا في عصياني وتكذيبي، واتبع الضعفاء منهم الرؤساء الضالين الذين لم تزدهم أموالهم وأولادهم إلا ضلالا في الدنيا وعقابًا في الآخرة، ومكر رؤساء الضلال بتابعيهم من الضعفاء مكرًا عظيمًا، وقالوا لهم: لا تتركوا عبادة آلهتكم إلى عبادة الله وحده، التي يدعو إليها نوح، ولا تتركوا وَدًّا ولا سُواعًا ولا يغوث ويعوق ونَسْرا - وهذه أسماء أصنامهم التي كانوا يعبدونها من دون الله، وكانت أسماء رجال صالحين، لما ماتوا أوحى الشيطان إلى قومهم أن يقيموا لهم التماثيل والصور؛ لينشطوا- بزعمهم- على الطاعة إذا رأوها، فلما ذهب هؤلاء القوم وطال الأمد، وخَلَفهم غيرهم، وسوس لهم الشيطان بأن أسلافهم كانوا يعبدون التماثيل والصور، ويتوسلون بها، وهذه هي الحكمة من تحريم التماثيل، وتحريم بناء القباب على القبور؛ لأنها تصير مع تطاول الزمن معبودة للجهال. وقد أضلَّ هؤلاء المتبوعون كثيرًا من الناس بما زيَّنوا لهم من طرق الغَواية والضلال. ثم قال نوح -عليه السلام-: ولا تزد- يا ربنا- هؤلاء الظالمين لأنفسهم بالكفر والعناد إلا بُعْدا عن الحق. فبسبب ذنوبهم وإصرارهم على الكفر والطغيان أُغرقوا بالطوفان، وأُدخلوا عقب الإغراق نارًا عظيمة اللهب والإحراق، فلم يجدوا من دون الله مَن ينصرهم، أو يدفع عنهم عذاب الله.", "isBasmala": false, "translation_en": "And they said, \"Do not give up your gods; do not give up Wadd, nor Souwa, nor Yaghoos, and Yaooq, and Nassr.", "translation_id": "Dan mereka berkata: \"Jangan sekali-kali kamu meninggalkan (penyembahan) tuhan-tuhan kamu dan jangan pula sekali-kali kamu meninggalkan (penyembahan) wadd, dan jangan pula suwwa', yaghuts, ya'uq dan nasr\".", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 24, "text": "وَقَدۡ أَضَلُّوا۟ كَثِیرࣰاۖ وَلَا تَزِدِ ٱلظَّـٰلِمِینَ إِلَّا ضَلَـٰلࣰا ۝٢٤", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: ربِّ إن قومي بالغوا في عصياني وتكذيبي، واتبع الضعفاء منهم الرؤساء الضالين الذين لم تزدهم أموالهم وأولادهم إلا ضلالا في الدنيا وعقابًا في الآخرة، ومكر رؤساء الضلال بتابعيهم من الضعفاء مكرًا عظيمًا، وقالوا لهم: لا تتركوا عبادة آلهتكم إلى عبادة الله وحده، التي يدعو إليها نوح، ولا تتركوا وَدًّا ولا سُواعًا ولا يغوث ويعوق ونَسْرا - وهذه أسماء أصنامهم التي كانوا يعبدونها من دون الله، وكانت أسماء رجال صالحين، لما ماتوا أوحى الشيطان إلى قومهم أن يقيموا لهم التماثيل والصور؛ لينشطوا- بزعمهم- على الطاعة إذا رأوها، فلما ذهب هؤلاء القوم وطال الأمد، وخَلَفهم غيرهم، وسوس لهم الشيطان بأن أسلافهم كانوا يعبدون التماثيل والصور، ويتوسلون بها، وهذه هي الحكمة من تحريم التماثيل، وتحريم بناء القباب على القبور؛ لأنها تصير مع تطاول الزمن معبودة للجهال. وقد أضلَّ هؤلاء المتبوعون كثيرًا من الناس بما زيَّنوا لهم من طرق الغَواية والضلال. ثم قال نوح -عليه السلام-: ولا تزد- يا ربنا- هؤلاء الظالمين لأنفسهم بالكفر والعناد إلا بُعْدا عن الحق. فبسبب ذنوبهم وإصرارهم على الكفر والطغيان أُغرقوا بالطوفان، وأُدخلوا عقب الإغراق نارًا عظيمة اللهب والإحراق، فلم يجدوا من دون الله مَن ينصرهم، أو يدفع عنهم عذاب الله.", "isBasmala": false, "translation_en": "They have misled many, so do not increase the wrongdoers except in confusion.\"", "translation_id": "Dan sesudahnya mereka menyesatkan kebanyakan (manusia); dan janganlah Engkau tambahkan bagi orang-orang yang zalim itu selain kesesatan.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 25, "text": "مِّمَّا خَطِیۤـَٔـٰتِهِمۡ أُغۡرِقُوا۟ فَأُدۡخِلُوا۟ نَارࣰا فَلَمۡ یَجِدُوا۟ لَهُم مِّن دُونِ ٱللَّهِ أَنصَارࣰا ۝٢٥", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "قال نوح: ربِّ إن قومي بالغوا في عصياني وتكذيبي، واتبع الضعفاء منهم الرؤساء الضالين الذين لم تزدهم أموالهم وأولادهم إلا ضلالا في الدنيا وعقابًا في الآخرة، ومكر رؤساء الضلال بتابعيهم من الضعفاء مكرًا عظيمًا، وقالوا لهم: لا تتركوا عبادة آلهتكم إلى عبادة الله وحده، التي يدعو إليها نوح، ولا تتركوا وَدًّا ولا سُواعًا ولا يغوث ويعوق ونَسْرا - وهذه أسماء أصنامهم التي كانوا يعبدونها من دون الله، وكانت أسماء رجال صالحين، لما ماتوا أوحى الشيطان إلى قومهم أن يقيموا لهم التماثيل والصور؛ لينشطوا- بزعمهم- على الطاعة إذا رأوها، فلما ذهب هؤلاء القوم وطال الأمد، وخَلَفهم غيرهم، وسوس لهم الشيطان بأن أسلافهم كانوا يعبدون التماثيل والصور، ويتوسلون بها، وهذه هي الحكمة من تحريم التماثيل، وتحريم بناء القباب على القبور؛ لأنها تصير مع تطاول الزمن معبودة للجهال. وقد أضلَّ هؤلاء المتبوعون كثيرًا من الناس بما زيَّنوا لهم من طرق الغَواية والضلال. ثم قال نوح -عليه السلام-: ولا تزد- يا ربنا- هؤلاء الظالمين لأنفسهم بالكفر والعناد إلا بُعْدا عن الحق. فبسبب ذنوبهم وإصرارهم على الكفر والطغيان أُغرقوا بالطوفان، وأُدخلوا عقب الإغراق نارًا عظيمة اللهب والإحراق، فلم يجدوا من دون الله مَن ينصرهم، أو يدفع عنهم عذاب الله.", "isBasmala": false, "translation_en": "Because of their wrongs, they were drowned, and were hurled into a Fire. They did not find apart from God any helpers.", "translation_id": "Disebabkan kesalahan-kesalahan mereka, mereka ditenggelamkan lalu dimasukkan ke neraka, maka mereka tidak mendapat penolong-penolong bagi mereka selain dari Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 26, "text": "وَقَالَ نُوحࣱ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَـٰفِرِینَ دَیَّارًا ۝٢٦", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "وقال نوح -عليه السلام- بعد يأسه من قومه: ربِّ لا تترك من الكافرين بك أحدًا حيًّا على الأرض يدور ويتحرك. إنك إن تتركهم دون إهلاك يُضلوا عبادك الذين قد آمنوا بك عن طريق الحق، ولا يأت من أصلابهم وأرحامهم إلا مائل عن الحق شديد الكفر بك والعصيان لك. ربِّ اغفر لي ولوالديَّ ولمن دخل بيتي مؤمنًا، وللمؤمنين والمؤمنات بك، ولا تزد الكافرين إلا هلاكًا وخسرانًا في الدنيا والآخرة.", "isBasmala": false, "translation_en": "Noah said, \"My Lord, do not leave of the unbelievers a single dweller on earth.", "translation_id": "Nuh berkata: \"Ya Tuhanku, janganlah Engkau biarkan seorangpun di antara orang-orang kafir itu tinggal di atas bumi.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 27, "text": "إِنَّكَ إِن تَذَرۡهُمۡ یُضِلُّوا۟ عِبَادَكَ وَلَا یَلِدُوۤا۟ إِلَّا فَاجِرࣰا كَفَّارࣰا ۝٢٧", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "وقال نوح -عليه السلام- بعد يأسه من قومه: ربِّ لا تترك من الكافرين بك أحدًا حيًّا على الأرض يدور ويتحرك. إنك إن تتركهم دون إهلاك يُضلوا عبادك الذين قد آمنوا بك عن طريق الحق، ولا يأت من أصلابهم وأرحامهم إلا مائل عن الحق شديد الكفر بك والعصيان لك. ربِّ اغفر لي ولوالديَّ ولمن دخل بيتي مؤمنًا، وللمؤمنين والمؤمنات بك، ولا تزد الكافرين إلا هلاكًا وخسرانًا في الدنيا والآخرة.", "isBasmala": false, "translation_en": "If You leave them, they will mislead your servants, and will breed only wicked unbelievers.", "translation_id": "Sesungguhnya jika Engkau biarkan mereka tinggal, niscaya mereka akan menyesatkan hamba-hamba-Mu, dan mereka tidak akan melahirkan selain anak yang berbuat maksiat lagi sangat kafir.", "manzil": 7, "manzil_display": ""}, {"sura": 71, "sura_name": "نوح", "revelation": "Makkiyah", "aya": 28, "text": "رَّبِّ ٱغۡفِرۡ لِی وَلِوَ ٰلِدَیَّ وَلِمَن دَخَلَ بَیۡتِیَ مُؤۡمِنࣰا وَلِلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِۖ وَلَا تَزِدِ ٱلظَّـٰلِمِینَ إِلَّا تَبَارَۢا ۝٢٨", "juz": 29, "hizb": "(*¾ ح 57*)", "tafsir": "وقال نوح -عليه السلام- بعد يأسه من قومه: ربِّ لا تترك من الكافرين بك أحدًا حيًّا على الأرض يدور ويتحرك. إنك إن تتركهم دون إهلاك يُضلوا عبادك الذين قد آمنوا بك عن طريق الحق، ولا يأت من أصلابهم وأرحامهم إلا مائل عن الحق شديد الكفر بك والعصيان لك. ربِّ اغفر لي ولوالديَّ ولمن دخل بيتي مؤمنًا، وللمؤمنين والمؤمنات بك، ولا تزد الكافرين إلا هلاكًا وخسرانًا في الدنيا والآخرة.", "isBasmala": false, "translation_en": "My Lord! Forgive me and my parents, and anyone who enters my home in faith, and all the believing men and believing women; and do not increase the wrongdoers except in perdition.\"", "translation_id": "Ya Tuhanku! Ampunilah aku, ibu bapakku, orang yang masuk ke rumahku dengan beriman dan semua orang yang beriman laki-laki dan perempuan. Dan janganlah Engkau tambahkan bagi orang-orang yang zalim itu selain kebinasaan\".", "manzil": 7, "manzil_display": ""}], "572": [{"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 1, "text": "۞ قُلۡ أُوحِیَ إِلَیَّ أَنَّهُ ٱسۡتَمَعَ نَفَرࣱ مِّنَ ٱلۡجِنِّ فَقَالُوۤا۟ إِنَّا سَمِعۡنَا قُرۡءَانًا عَجَبࣰا ۝١", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل -أيها الرسول-: أوحى الله إليَّ أنَّ جماعة من الجن قد استمعوا لتلاوتي للقرآن، فلما سمعوه قالوا لقومهم: إنا سمعنا قرآنًا بديعًا في بلاغته وفصاحته وحكمه وأحكامه وأخباره، يدعو إلى الحق والهدى، فصدَّقنا بهذا القرآن وعملنا به، ولن نشرك بربنا الذي خلقنا أحدًا في عبادته.", "isBasmala": false, "translation_en": "Say, \"It was revealed to me that a band of jinn listened in, and said, 'We have heard a wondrous Quran.", "translation_id": "Katakanlah (hai Muhammad): \"Telah diwahyukan kepadamu bahwasanya: telah mendengarkan sekumpulan jin (akan Al Quran), lalu mereka berkata: Sesungguhnya kami telah mendengarkan Al Quran yang menakjubkan,", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 2, "text": "یَهۡدِیۤ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَاۤ أَحَدࣰا ۝٢", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل -أيها الرسول-: أوحى الله إليَّ أنَّ جماعة من الجن قد استمعوا لتلاوتي للقرآن، فلما سمعوه قالوا لقومهم: إنا سمعنا قرآنًا بديعًا في بلاغته وفصاحته وحكمه وأحكامه وأخباره، يدعو إلى الحق والهدى، فصدَّقنا بهذا القرآن وعملنا به، ولن نشرك بربنا الذي خلقنا أحدًا في عبادته.", "isBasmala": false, "translation_en": "It guides to rectitude, so we have believed in it; and we will never associate anyone with our Lord.", "translation_id": "(yang) memberi petunjuk kapada jalan yang benar, lalu kami beriman kepadanya. Dan kami sekali-kali tidak akan mempersekutukan seseorangpun dengan Tuhan kami,", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 3, "text": "وَأَنَّهُۥ تَعَـٰلَىٰ جَدُّ رَبِّنَا مَا ٱتَّخَذَ صَـٰحِبَةࣰ وَلَا وَلَدࣰا ۝٣", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنه تعالَتْ عظمة ربنا وجلاله، ما اتخذ زوجة ولا ولدًا.", "isBasmala": false, "translation_en": "And Exalted is the Grandeur of our Lord-He never had a mate, nor a child.", "translation_id": "dan bahwasanya Maha Tinggi kebesaran Tuhan kami, Dia tidak beristeri dan tidak (pula) beranak.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 4, "text": "وَأَنَّهُۥ كَانَ یَقُولُ سَفِیهُنَا عَلَى ٱللَّهِ شَطَطࣰا ۝٤", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأن سفيهنا- وهو إبليس- كان يقول على الله تعالى قولا بعيدًا عن الحق والصواب، مِن دعوى الصاحبة والولد.", "isBasmala": false, "translation_en": "But the fools among us used to say nonsense about God.", "translation_id": "Dan bahwasanya: orang yang kurang akal daripada kami selalu mengatakan (perkataan) yang melampaui batas terhadap Allah,", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 5, "text": "وَأَنَّا ظَنَنَّاۤ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبࣰا ۝٥", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنَّا حَسِبْنا أن أحدًا لن يكذب على الله تعالى، لا من الإنس ولا من الجن في نسبة الصاحبة والولد إليه.", "isBasmala": false, "translation_en": "And we thought that humans and jinn would never utter lies about God.", "translation_id": "dan sesungguhnya kami mengira, bahwa manusia dan jin sekali-kali tidak akan mengatakan perkataan yang dusta terhadap Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 6, "text": "وَأَنَّهُۥ كَانَ رِجَالࣱ مِّنَ ٱلۡإِنسِ یَعُوذُونَ بِرِجَالࣲ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقࣰا ۝٦", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنه كان رجال من الإنس يستجيرون برجال من الجن، فزاد رجالُ الجنِّ الإنسَ باستعاذتهم بهم خوفًا وإرهابًا ورعبًا. وهذه الاستعاذة بغير الله، التي نعاها الله على أهل الجاهلية، من الشرك الأكبر، الذي لا يغفره الله إلا بالتوبة النصوح منه. وفي الآية تحذير شديد من اللجوء إلى السحرة والمشعوذين وأشباههم.", "isBasmala": false, "translation_en": "Some individual humans used to seek power through some individual jinn, but they only increased them in confusion.", "translation_id": "Dan bahwasanya ada beberapa orang laki-laki di antara manusia meminta perlindungan kepada beberapa laki-laki di antara jin, maka jin-jin itu menambah bagi mereka dosa dan kesalahan.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 7, "text": "وَأَنَّهُمۡ ظَنُّوا۟ كَمَا ظَنَنتُمۡ أَن لَّن یَبۡعَثَ ٱللَّهُ أَحَدࣰا ۝٧", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأن كفار الإنس حسبوا كما حسبتم- يا معشر الجن- أن الله تعالى لن يبعث أحدًا بعد الموت.", "isBasmala": false, "translation_en": "They thought, as you thought, that God would never resurrect anyone.", "translation_id": "Dan sesungguhnya mereka (jin) menyangka sebagaimana persangkaan kamu (orang-orang kafir Mekah), bahwa Allah sekali-kali tidak akan membangkitkan seorang (rasul)pun,", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 8, "text": "وَأَنَّا لَمَسۡنَا ٱلسَّمَاۤءَ فَوَجَدۡنَـٰهَا مُلِئَتۡ حَرَسࣰا شَدِیدࣰا وَشُهُبࣰا ۝٨", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنَّا- معشر الجن- طلبنا بلوغ السماء؛ لاستماع كلام أهلها، فوجدناها مُلئت بالملائكة الكثيرين الذين يحرسونها، وبالشهب المحرقة التي يُرمى بها مَن يقترب منها.", "isBasmala": false, "translation_en": "We probed the heaven, and found it filled with stern guards and projectiles.", "translation_id": "dan sesungguhnya kami telah mencoba mengetahui (rahasia) langit, maka kami mendapatinya penuh dengan penjagaan yang kuat dan panah-panah api,", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 9, "text": "وَأَنَّا كُنَّا نَقۡعُدُ مِنۡهَا مَقَـٰعِدَ لِلسَّمۡعِۖ فَمَن یَسۡتَمِعِ ٱلۡـَٔانَ یَجِدۡ لَهُۥ شِهَابࣰا رَّصَدࣰا ۝٩", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنا كنا قبل ذلك نتخذ من السماء مواضع؛ لنستمع إلى أخبارها، فمن يحاول الآن استراق السمع يجد له شهابًا بالمرصاد، يُحرقه ويهلكه. وفي هاتين الآيتين إبطال مزاعم السحرة والمشعوذين، الذين يدَّعون علم الغيب، ويغررون بضعفة العقول؛ بكذبهم وافترائهم.", "isBasmala": false, "translation_en": "We used to take up positions to listen in; but whoever listens now finds a projectile in wait for him.", "translation_id": "dan sesungguhnya kami dahulu dapat menduduki beberapa tempat di langit itu untuk mendengar-dengarkan (berita-beritanya). Tetapi sekarang barangsiapa yang (mencoba) mendengar-dengarkan (seperti itu) tentu akan menjumpai panah api yang mengintai (untuk membakarnya).", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 10, "text": "وَأَنَّا لَا نَدۡرِیۤ أَشَرٌّ أُرِیدَ بِمَن فِی ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدࣰا ۝١٠", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأننا معشر الجن- لا نعلم: أشرًّا أراد الله أن ينزله بأهل الأرض، أم أراد بهم خيرًا وهدى؟", "isBasmala": false, "translation_en": "We do not know whether ill is intended for those on earth, or if their Lord intends goodness for them.", "translation_id": "Dan sesungguhnya kami tidak mengetahui (dengan adanya penjagaan itu) apakah keburukan yang dikehendaki bagi orang yang di bumi ataukah Tuhan mereka menghendaki kebaikan bagi mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 11, "text": "وَأَنَّا مِنَّا ٱلصَّـٰلِحُونَ وَمِنَّا دُونَ ذَ ٰلِكَۖ كُنَّا طَرَاۤىِٕقَ قِدَدࣰا ۝١١", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنا منا الأبرار المتقون، ومنا قوم دون ذلك كفار وفساق، كنا فرقًا ومذاهب مختلفة.", "isBasmala": false, "translation_en": "Some of us are righteous, but some of us are less than that; we follow divergent paths.", "translation_id": "Dan sesungguhnya di antara kami ada orang-orang yang saleh dan di antara kami ada (pula) yang tidak demikian halnya. Adalah kami menempuh jalan yang berbeda-beda.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 12, "text": "وَأَنَّا ظَنَنَّاۤ أَن لَّن نُّعۡجِزَ ٱللَّهَ فِی ٱلۡأَرۡضِ وَلَن نُّعۡجِزَهُۥ هَرَبࣰا ۝١٢", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنا أيقنا أن الله قادر علينا، وأننا في قبضته وسلطانه، فلن نفوته إذا أراد بنا أمرًا أينما كنا، ولن نستطيع أن نُفْلِت مِن عقابه هربًا إلى السماء، إن أراد بنا سوءًا.", "isBasmala": false, "translation_en": "We realized that we cannot defeat God on earth, and that we cannot escape Him by fleeing.", "translation_id": "Dan sesungguhnya kami mengetahui bahwa kami sekali-kali tidak akan dapat melepaskan diri (dari kekuasaan) Allah di muka bumi dan sekali-kali tidak (pula) dapat melepaskan diri (daripada)Nya dengan lari.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 13, "text": "وَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰۤ ءَامَنَّا بِهِۦۖ فَمَن یُؤۡمِنۢ بِرَبِّهِۦ فَلَا یَخَافُ بَخۡسࣰا وَلَا رَهَقࣰا ۝١٣", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وإنا لما سمعنا القرآن آمنَّا به، وأقررنا أنه حق مِن عند الله، فمن يؤمن بربه، فإنه لا يخشى نقصانًا من حسناته، ولا ظلمًا يلحقه بزيادة في سيئاته.", "isBasmala": false, "translation_en": "And when we heard the guidance, we believed in it. Whoever believes in his Lord fears neither loss, nor burden.", "translation_id": "Dan sesungguhnya kami tatkala mendengar petunjuk (Al Quran), kami beriman kepadanya. Barangsiapa beriman kepada Tuhannya, maka ia tidak takut akan pengurangan pahala dan tidak (takut pula) akan penambahan dosa dan kesalahan.", "manzil": 7, "manzil_display": ""}], "573": [{"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 14, "text": "وَأَنَّا مِنَّا ٱلۡمُسۡلِمُونَ وَمِنَّا ٱلۡقَـٰسِطُونَۖ فَمَنۡ أَسۡلَمَ فَأُو۟لَـٰۤىِٕكَ تَحَرَّوۡا۟ رَشَدࣰا ۝١٤", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنا منا الخاضعون لله بالطاعة، ومنا الجائرون الظالمون الذين حادوا عن طريق الحق، فمن أسلم وخضع لله بالطاعة، فأولئك الذين قصدوا طريق الحق والصواب، واجتهدوا في اختياره فهداهم الله إليه، وأما الجائرون عن طريق الإسلام فكانوا وَقودًا لجهنم.", "isBasmala": false, "translation_en": "Among us are those who are submitting, and among us are the compromisers. As for those who have submitted-it is they who pursue rectitude.", "translation_id": "Dan sesungguhnya di antara kami ada orang-orang yang taat dan ada (pula) orang-orang yang menyimpang dari kebenaran. Barangsiapa yang yang taat, maka mereka itu benar-benar telah memilih jalan yang lurus.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 15, "text": "وَأَمَّا ٱلۡقَـٰسِطُونَ فَكَانُوا۟ لِجَهَنَّمَ حَطَبࣰا ۝١٥", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنا منا الخاضعون لله بالطاعة، ومنا الجائرون الظالمون الذين حادوا عن طريق الحق، فمن أسلم وخضع لله بالطاعة، فأولئك الذين قصدوا طريق الحق والصواب، واجتهدوا في اختياره فهداهم الله إليه، وأما الجائرون عن طريق الإسلام فكانوا وَقودًا لجهنم.", "isBasmala": false, "translation_en": "But as for the compromisers-they will be firewood for Hell.'\"", "translation_id": "Adapun orang-orang yang menyimpang dari kebenaran, maka mereka menjadi kayu api bagi neraka Jahannam.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 16, "text": "وَأَلَّوِ ٱسۡتَقَـٰمُوا۟ عَلَى ٱلطَّرِیقَةِ لَأَسۡقَیۡنَـٰهُم مَّاۤءً غَدَقࣰا ۝١٦", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنه لو سار الكفار من الإنس والجن على طريقة الإسلام، ولم يحيدوا عنها لأنزلنا عليهم ماءً كثيرًا، ولوسَّعنا عليهم الرزق في الدنيا؛ لنختبرهم: كيف يشكرون نعم الله عليهم؟ ومن يُعرض عن طاعة ربه واستماع القرآن وتدبره، والعمل به يدخله عذابًا شديدًا شاقًّا.", "isBasmala": false, "translation_en": "Had they kept true to the Path, We would have given them plenty water to drink.", "translation_id": "Dan bahwasanya: jikalau mereka tetap berjalan lurus di atas jalan itu (agama Islam), benar-benar Kami akan memberi minum kepada mereka air yang segar (rezeki yang banyak).", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 17, "text": "لِّنَفۡتِنَهُمۡ فِیهِۚ وَمَن یُعۡرِضۡ عَن ذِكۡرِ رَبِّهِۦ یَسۡلُكۡهُ عَذَابࣰا صَعَدࣰا ۝١٧", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنه لو سار الكفار من الإنس والجن على طريقة الإسلام، ولم يحيدوا عنها لأنزلنا عليهم ماءً كثيرًا، ولوسَّعنا عليهم الرزق في الدنيا؛ لنختبرهم: كيف يشكرون نعم الله عليهم؟ ومن يُعرض عن طاعة ربه واستماع القرآن وتدبره، والعمل به يدخله عذابًا شديدًا شاقًّا.", "isBasmala": false, "translation_en": "To test them with it. Whoever turns away from the remembrance of his Lord, He will direct him to torment ever mounting.", "translation_id": "Untuk Kami beri cobaan kepada mereka padanya. Dan barangsiapa yang berpaling dari peringatan Tuhannya, niscaya akan dimasukkan-Nya ke dalam azab yang amat berat.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 18, "text": "وَأَنَّ ٱلۡمَسَـٰجِدَ لِلَّهِ فَلَا تَدۡعُوا۟ مَعَ ٱللَّهِ أَحَدࣰا ۝١٨", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأن المساجد لعبادة الله وحده، فلا تعبدوا فيها غيره، وأخلصوا له الدعاء والعبادة فيها؛ فإن المساجد لم تُبْنَ إلا ليُعبَدَ اللهُ وحده فيها، دون من سواه، وفي هذا وجوب تنزيه المساجد من كل ما يشوب الإخلاص لله، ومتابعة رسوله محمد صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "The places of worship are for God. So do not call, besides God, upon anyone else.", "translation_id": "Dan sesungguhnya mesjid-mesjid itu adalah kepunyaan Allah. Maka janganlah kamu menyembah seseorangpun di dalamnya di samping (menyembah) Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 19, "text": "وَأَنَّهُۥ لَمَّا قَامَ عَبۡدُ ٱللَّهِ یَدۡعُوهُ كَادُوا۟ یَكُونُونَ عَلَیۡهِ لِبَدࣰا ۝١٩", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "وأنه لما قام محمد صلى الله عليه وسلم، يعبد ربه، كاد الجن يكونون عليه جماعات متراكمة، بعضها فوق بعض؛ مِن شدة ازدحامهم لسماع القرآن منه.", "isBasmala": false, "translation_en": "And when the servant of God got up calling on Him, they almost fell on him in a mass.", "translation_id": "Dan bahwasanya tatkala hamba Allah (Muhammad) berdiri menyembah-Nya (mengerjakan ibadat), hampir saja jin-jin itu desak mendesak mengerumuninya.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 20, "text": "قُلۡ إِنَّمَاۤ أَدۡعُوا۟ رَبِّی وَلَاۤ أُشۡرِكُ بِهِۦۤ أَحَدࣰا ۝٢٠", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل -أيها الرسول- لهؤلاء الكفار: إنما أعبد ربي وحده، ولا أشرك معه في العبادة أحدًا.", "isBasmala": false, "translation_en": "Say, \"I pray only to my Lord, and I never associate anyone with Him.\"", "translation_id": "Katakanlah: \"Sesungguhnya aku hanya menyembah Tuhanku dan aku tidak mempersekutukan sesuatupun dengan-Nya\".", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 21, "text": "قُلۡ إِنِّی لَاۤ أَمۡلِكُ لَكُمۡ ضَرࣰّا وَلَا رَشَدࣰا ۝٢١", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل- أيها الرسول- لهم: إني لا أقدر أن أدفع عنكم ضرًا، ولا أجلب لكم نفعًا، قل: إني لن ينقذني من عذاب الله أحد إن عصيته، ولن أجد من دونه ملجأ أفرُّ إليه مِن عذابه، لكن أملك أن أبلغكم عن الله ما أمرني بتبليغه لكم، ورسالتَه التي أرسلني بها إليكم. ومَن يعص الله ورسوله، ويُعرض عن دين الله، فإن جزاءه نار جهنم لا يخرج منها أبدًا.", "isBasmala": false, "translation_en": "Say, \"It is not in my power to harm you, nor to bring you to right conduct.\"", "translation_id": "Katakanlah: \"Sesungguhnya aku tidak kuasa mendatangkan sesuatu kemudharatanpun kepadamu dan tidak (pula) suatu kemanfaatan\".", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 22, "text": "قُلۡ إِنِّی لَن یُجِیرَنِی مِنَ ٱللَّهِ أَحَدࣱ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا ۝٢٢", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل- أيها الرسول- لهم: إني لا أقدر أن أدفع عنكم ضرًا، ولا أجلب لكم نفعًا، قل: إني لن ينقذني من عذاب الله أحد إن عصيته، ولن أجد من دونه ملجأ أفرُّ إليه مِن عذابه، لكن أملك أن أبلغكم عن الله ما أمرني بتبليغه لكم، ورسالتَه التي أرسلني بها إليكم. ومَن يعص الله ورسوله، ويُعرض عن دين الله، فإن جزاءه نار جهنم لا يخرج منها أبدًا.", "isBasmala": false, "translation_en": "Say, \"No one can protect me from God, and I will not find any refuge except with Him.", "translation_id": "Katakanlah: \"Sesungguhnya aku sekali-kali tiada seorangpun dapat melindungiku dari (azab) Allah dan sekali-kali aku tiada akan memperoleh tempat berlindung selain daripada-Nya\".", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 23, "text": "إِلَّا بَلَـٰغࣰا مِّنَ ٱللَّهِ وَرِسَـٰلَـٰتِهِۦۚ وَمَن یَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَإِنَّ لَهُۥ نَارَ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۤ أَبَدًا ۝٢٣", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل- أيها الرسول- لهم: إني لا أقدر أن أدفع عنكم ضرًا، ولا أجلب لكم نفعًا، قل: إني لن ينقذني من عذاب الله أحد إن عصيته، ولن أجد من دونه ملجأ أفرُّ إليه مِن عذابه، لكن أملك أن أبلغكم عن الله ما أمرني بتبليغه لكم، ورسالتَه التي أرسلني بها إليكم. ومَن يعص الله ورسوله، ويُعرض عن دين الله، فإن جزاءه نار جهنم لا يخرج منها أبدًا.", "isBasmala": false, "translation_en": "Except for a proclamation from God and His messages. He who defies God and His Messenger-for him is the Fire of Hell, in which they will dwell forever.\"", "translation_id": "Akan tetapi (aku hanya) menyampaikan (peringatan) dari Allah dan risalah-Nya. Dan barangsiapa yang mendurhakai Allah dan Rasul-Nya maka sesungguhnya baginyalah neraka Jahannam, mereka kekal di dalamnya selama-lamanya.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 24, "text": "حَتَّىٰۤ إِذَا رَأَوۡا۟ مَا یُوعَدُونَ فَسَیَعۡلَمُونَ مَنۡ أَضۡعَفُ نَاصِرࣰا وَأَقَلُّ عَدَدࣰا ۝٢٤", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "حتى إذا أبصر المشركون ما يوعدون به من العذاب، فسيعلمون عند حلوله بهم: مَن أضعف ناصرًا ومعينًا وأقل جندًا؟", "isBasmala": false, "translation_en": "Until, when they see what they were promised, they will know who is weaker in helpers, and fewer in numbers.", "translation_id": "Sehingga apabila mereka melihat azab yang diancamkan kepada mereka, maka mereka akan mengetahui siapakah yang lebih lemah penolongnya dan lebih sedikit bilangannya.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 25, "text": "قُلۡ إِنۡ أَدۡرِیۤ أَقَرِیبࣱ مَّا تُوعَدُونَ أَمۡ یَجۡعَلُ لَهُۥ رَبِّیۤ أَمَدًا ۝٢٥", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: ما أدري أهذا العذاب الذي وُعدتم به قريب زمنه، أم يجعل له ربي مدة طويلة؟ وهو سبحانه عالم بما غاب عن الأبصار، فلا يظهر على غيبه أحدًا من خلقه، إلا من اختاره الله لرسالته وارتضاه، فإنه يُطلعهم على بعض الغيب، ويرسل من أمام الرسول ومن خلفه ملائكة يحفظونه من الجن؛ لئلا يسترقوه ويهمسوا به إلى الكهنة؛ ليعلم الرسول صلى الله عليه وسلم، أن الرسل قبله كانوا على مثل حاله من التبليغ بالحق والصدق، وأنه حُفظ كما حُفظوا من الجن، وأن الله سبحانه أحاط علمه بما عندهم ظاهرًا وباطنًا من الشرائع والأحكام وغيرها، لا يفوته منها شيء، وأنه تعالى أحصى كل شيء عددًا، فلم يَخْفَ عليه منه شيء.", "isBasmala": false, "translation_en": "Say, \"I do not know whether what you are promised is near, or whether my Lord will extend it for a period.\"", "translation_id": "Katakanlah: \"Aku tidak mengetahui, apakah azab yang diancamkan kepadamu itu dekat ataukah Tuhanku menjadikan bagi (kedatangan) azab itu masa yang panjang?\".", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 26, "text": "عَـٰلِمُ ٱلۡغَیۡبِ فَلَا یُظۡهِرُ عَلَىٰ غَیۡبِهِۦۤ أَحَدًا ۝٢٦", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: ما أدري أهذا العذاب الذي وُعدتم به قريب زمنه، أم يجعل له ربي مدة طويلة؟ وهو سبحانه عالم بما غاب عن الأبصار، فلا يظهر على غيبه أحدًا من خلقه، إلا من اختاره الله لرسالته وارتضاه، فإنه يُطلعهم على بعض الغيب، ويرسل من أمام الرسول ومن خلفه ملائكة يحفظونه من الجن؛ لئلا يسترقوه ويهمسوا به إلى الكهنة؛ ليعلم الرسول صلى الله عليه وسلم، أن الرسل قبله كانوا على مثل حاله من التبليغ بالحق والصدق، وأنه حُفظ كما حُفظوا من الجن، وأن الله سبحانه أحاط علمه بما عندهم ظاهرًا وباطنًا من الشرائع والأحكام وغيرها، لا يفوته منها شيء، وأنه تعالى أحصى كل شيء عددًا، فلم يَخْفَ عليه منه شيء.", "isBasmala": false, "translation_en": "The Knower of the Invisible; He does not disclose His Invisible to anyone.", "translation_id": "(Dia adalah Tuhan) Yang Mengetahui yang ghaib, maka Dia tidak memperlihatkan kepada seorangpun tentang yang ghaib itu.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 27, "text": "إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولࣲ فَإِنَّهُۥ یَسۡلُكُ مِنۢ بَیۡنِ یَدَیۡهِ وَمِنۡ خَلۡفِهِۦ رَصَدࣰا ۝٢٧", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: ما أدري أهذا العذاب الذي وُعدتم به قريب زمنه، أم يجعل له ربي مدة طويلة؟ وهو سبحانه عالم بما غاب عن الأبصار، فلا يظهر على غيبه أحدًا من خلقه، إلا من اختاره الله لرسالته وارتضاه، فإنه يُطلعهم على بعض الغيب، ويرسل من أمام الرسول ومن خلفه ملائكة يحفظونه من الجن؛ لئلا يسترقوه ويهمسوا به إلى الكهنة؛ ليعلم الرسول صلى الله عليه وسلم، أن الرسل قبله كانوا على مثل حاله من التبليغ بالحق والصدق، وأنه حُفظ كما حُفظوا من الجن، وأن الله سبحانه أحاط علمه بما عندهم ظاهرًا وباطنًا من الشرائع والأحكام وغيرها، لا يفوته منها شيء، وأنه تعالى أحصى كل شيء عددًا، فلم يَخْفَ عليه منه شيء.", "isBasmala": false, "translation_en": "Except to a Messenger of His choosing. He then dispatches guards before him and behind him.", "translation_id": "Kecuali kepada rasul yang diridhai-Nya, maka sesungguhnya Dia mengadakan penjaga-penjaga (malaikat) di muka dan di belakangnya.", "manzil": 7, "manzil_display": ""}, {"sura": 72, "sura_name": "الجن", "revelation": "Makkiyah", "aya": 28, "text": "لِّیَعۡلَمَ أَن قَدۡ أَبۡلَغُوا۟ رِسَـٰلَـٰتِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَیۡهِمۡ وَأَحۡصَىٰ كُلَّ شَیۡءٍ عَدَدَۢا ۝٢٨", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "قل -أيها الرسول- لهؤلاء المشركين: ما أدري أهذا العذاب الذي وُعدتم به قريب زمنه، أم يجعل له ربي مدة طويلة؟ وهو سبحانه عالم بما غاب عن الأبصار، فلا يظهر على غيبه أحدًا من خلقه، إلا من اختاره الله لرسالته وارتضاه، فإنه يُطلعهم على بعض الغيب، ويرسل من أمام الرسول ومن خلفه ملائكة يحفظونه من الجن؛ لئلا يسترقوه ويهمسوا به إلى الكهنة؛ ليعلم الرسول صلى الله عليه وسلم، أن الرسل قبله كانوا على مثل حاله من التبليغ بالحق والصدق، وأنه حُفظ كما حُفظوا من الجن، وأن الله سبحانه أحاط علمه بما عندهم ظاهرًا وباطنًا من الشرائع والأحكام وغيرها، لا يفوته منها شيء، وأنه تعالى أحصى كل شيء عددًا، فلم يَخْفَ عليه منه شيء.", "isBasmala": false, "translation_en": "That He may know that they have conveyed the messages of their Lord. He encompasses what they have, and has tallied everything by number.", "translation_id": "Supaya Dia mengetahui, bahwa sesungguhnya rasul-rasul itu telah menyampaikan risalah-risalah Tuhannya, sedang (sebenarnya) ilmu-Nya meliputi apa yang ada pada mereka, dan Dia menghitung segala sesuatu satu persatu.", "manzil": 7, "manzil_display": ""}], "574": [{"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 1, "text": "یَـٰۤأَیُّهَا ٱلۡمُزَّمِّلُ ۝١", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم للصلاة في الليل إلا يسيرًا منه. قم نصف الليل أو انقص من النصف قليلا حتى تَصِلَ إلى الثلث، أو زد على النصف حتى تصل إلى الثلثين، واقرأ القرآن بتُؤَدَة وتمهُّلٍ مبيِّنًا الحروف والوقوف.", "isBasmala": false, "translation_en": "O you Enwrapped one.", "translation_id": "Hai orang yang berselimut (Muhammad),", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 2, "text": "قُمِ ٱلَّیۡلَ إِلَّا قَلِیلࣰا ۝٢", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم للصلاة في الليل إلا يسيرًا منه. قم نصف الليل أو انقص من النصف قليلا حتى تَصِلَ إلى الثلث، أو زد على النصف حتى تصل إلى الثلثين، واقرأ القرآن بتُؤَدَة وتمهُّلٍ مبيِّنًا الحروف والوقوف.", "isBasmala": false, "translation_en": "Stay up during the night, except a little.", "translation_id": "bangunlah (untuk sembahyang) di malam hari, kecuali sedikit (daripadanya),", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 3, "text": "نِّصۡفَهُۥۤ أَوِ ٱنقُصۡ مِنۡهُ قَلِیلًا ۝٣", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم للصلاة في الليل إلا يسيرًا منه. قم نصف الليل أو انقص من النصف قليلا حتى تَصِلَ إلى الثلث، أو زد على النصف حتى تصل إلى الثلثين، واقرأ القرآن بتُؤَدَة وتمهُّلٍ مبيِّنًا الحروف والوقوف.", "isBasmala": false, "translation_en": "For half of it, or reduce it a little.", "translation_id": "(yaitu) seperduanya atau kurangilah dari seperdua itu sedikit.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 4, "text": "أَوۡ زِدۡ عَلَیۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِیلًا ۝٤", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم للصلاة في الليل إلا يسيرًا منه. قم نصف الليل أو انقص من النصف قليلا حتى تَصِلَ إلى الثلث، أو زد على النصف حتى تصل إلى الثلثين، واقرأ القرآن بتُؤَدَة وتمهُّلٍ مبيِّنًا الحروف والوقوف.", "isBasmala": false, "translation_en": "Or add to it; and chant the Quran rhythmically.", "translation_id": "atau lebih dari seperdua itu. Dan bacalah Al Quran itu dengan perlahan-lahan.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 5, "text": "إِنَّا سَنُلۡقِی عَلَیۡكَ قَوۡلࣰا ثَقِیلًا ۝٥", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "إنا سننزل عليك -أيها النبي- قرآنًا عظيمًا مشتملا على الأوامر والنواهي والأحكام الشرعية.", "isBasmala": false, "translation_en": "We are about to give you a heavy message.", "translation_id": "Sesungguhnya Kami akan menurunkan kapadamu perkataan yang berat.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 6, "text": "إِنَّ نَاشِئَةَ ٱلَّیۡلِ هِیَ أَشَدُّ وَطۡـࣰٔا وَأَقۡوَمُ قِیلًا ۝٦", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "إن العبادة التي تنشأ في جوف الليل هي أشد تأثيرًا في القلب، وأبين قولا لفراغ القلب مِن مشاغل الدنيا.", "isBasmala": false, "translation_en": "The vigil of night is more effective, and better suited for recitation.", "translation_id": "Sesungguhnya bangun di waktu malam adalah lebih tepat (untuk khusyu') dan bacaan di waktu itu lebih berkesan.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 7, "text": "إِنَّ لَكَ فِی ٱلنَّهَارِ سَبۡحࣰا طَوِیلࣰا ۝٧", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "إن لك في النهار تصرفًا وتقلبًا في مصالحك، واشتغالا واسعًا بأمور الرسالة، ففرِّغْ نفسك ليلا لعبادة ربك.", "isBasmala": false, "translation_en": "In the daytime, you have lengthy work to do.", "translation_id": "Sesungguhnya kamu pada siang hari mempunyai urusan yang panjang (banyak).", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 8, "text": "وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَیۡهِ تَبۡتِیلࣰا ۝٨", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "واذكر -أيها النبي- اسم ربك، فادعه به، وانقطع إليه انقطاعًا تامًا في عبادتك، وتوكل عليه. هو مالك المشرق والمغرب لا معبود بحق إلا هو، فاعتمد عليه، وفوِّض أمورك إليه.", "isBasmala": false, "translation_en": "So remember the Name of your Lord, and devote yourself to Him wholeheartedly.", "translation_id": "Sebutlah nama Tuhanmu, dan beribadatlah kepada-Nya dengan penuh ketekunan.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 9, "text": "رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَاۤ إِلَـٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِیلࣰا ۝٩", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "واذكر -أيها النبي- اسم ربك، فادعه به، وانقطع إليه انقطاعًا تامًا في عبادتك، وتوكل عليه. هو مالك المشرق والمغرب لا معبود بحق إلا هو، فاعتمد عليه، وفوِّض أمورك إليه.", "isBasmala": false, "translation_en": "Lord of the East and the West. There is no god but He, so take Him as a Trustee.", "translation_id": "(Dialah) Tuhan masyrik dan maghrib, tiada Tuhan (yang berhak disembah) melainkan Dia, maka ambillah Dia sebagai pelindung.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 10, "text": "وَٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرࣰا جَمِیلࣰا ۝١٠", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "واصبر على ما يقوله المشركون فيك وفي دينك، وخالفهم في أفعالهم الباطلة، مع الإعراض عنهم، وترك الانتقام منهم.", "isBasmala": false, "translation_en": "And endure patiently what they say, and withdraw from them politely.", "translation_id": "Dan bersabarlah terhadap apa yang mereka ucapkan dan jauhilah mereka dengan cara yang baik.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 11, "text": "وَذَرۡنِی وَٱلۡمُكَذِّبِینَ أُو۟لِی ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِیلًا ۝١١", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "دعني -أيها الرسول- وهؤلاء المكذبين بآياتي أصحاب النعيم والترف في الدنيا، ومهِّلهم زمنًا قليلا بتأخير العذاب عنهم حتى يبلغ الكتاب أجله بعذابهم.", "isBasmala": false, "translation_en": "And leave Me to those who deny the truth, those of luxury, and give them a brief respite.", "translation_id": "Dan biarkanlah Aku (saja) bertindak terhadap orang-orang yang mendustakan itu, orang-orang yang mempunyai kemewahan dan beri tangguhlah mereka barang sebentar.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 12, "text": "إِنَّ لَدَیۡنَاۤ أَنكَالࣰا وَجَحِیمࣰا ۝١٢", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "إن لهم عندنا في الآخرة قيودًا ثقيلة ونارًا مستعرة يُحرقون بها، وطعامًا كريهًا ينشَب في الحلوق لا يستساغ، وعذابًا موجعًا.", "isBasmala": false, "translation_en": "With Us are shackles, and a Fierce Fire.", "translation_id": "Karena sesungguhnya pada sisi Kami ada belenggu-belenggu yang berat dan neraka yang menyala-nyala.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 13, "text": "وَطَعَامࣰا ذَا غُصَّةࣲ وَعَذَابًا أَلِیمࣰا ۝١٣", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "إن لهم عندنا في الآخرة قيودًا ثقيلة ونارًا مستعرة يُحرقون بها، وطعامًا كريهًا ينشَب في الحلوق لا يستساغ، وعذابًا موجعًا.", "isBasmala": false, "translation_en": "And food that chokes, and a painful punishment.", "translation_id": "Dan makanan yang menyumbat di kerongkongan dan azab yang pedih.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 14, "text": "یَوۡمَ تَرۡجُفُ ٱلۡأَرۡضُ وَٱلۡجِبَالُ وَكَانَتِ ٱلۡجِبَالُ كَثِیبࣰا مَّهِیلًا ۝١٤", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "يوم تضطرب الأرض والجبال وتتزلزل حتى تصير الجبال تَلا من الرمل سائلا متناثرًا، بعد أن كانت صُلبة جامدة.", "isBasmala": false, "translation_en": "On the Day when the earth and the mountains tremble, and the mountains become heaps of sand.", "translation_id": "Pada hari bumi dan gunung-gunung bergoncangan, dan menjadilah gunung-gunung itu tumpukan-tumpukan pasir yang berterbangan.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 15, "text": "إِنَّاۤ أَرۡسَلۡنَاۤ إِلَیۡكُمۡ رَسُولࣰا شَـٰهِدًا عَلَیۡكُمۡ كَمَاۤ أَرۡسَلۡنَاۤ إِلَىٰ فِرۡعَوۡنَ رَسُولࣰا ۝١٥", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "إنا أرسلنا إليكم- يا أهل \"مكة\"- محمدًا رسولا شاهدًا عليكم بما صدر منكم من الكفر والعصيان، كما أرسلنا موسى رسولا إلى الطاغية فرعون، فكذَّب فرعون بموسى، ولم يؤمن برسالته، وعصى أمره، فأهلكناه إهلاكًا شديدًا. وفي هذا تحذير من معصية الرسول محمد، صلى الله عليه وسلم؛ خشية أن يصيب العاصي مثل ما أصاب فرعون وقومه.", "isBasmala": false, "translation_en": "We have sent to you a messenger, a witness over you, as We sent to Pharaoh a messenger.", "translation_id": "Sesungguhnya Kami telah mengutus kepada kamu (hai orang kafir Mekah) seorang Rasul, yang menjadi saksi terhadapmu, sebagaimana Kami telah mengutus (dahulu) seorang Rasul kepada Fir'aun.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 16, "text": "فَعَصَىٰ فِرۡعَوۡنُ ٱلرَّسُولَ فَأَخَذۡنَـٰهُ أَخۡذࣰا وَبِیلࣰا ۝١٦", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "إنا أرسلنا إليكم- يا أهل \"مكة\"- محمدًا رسولا شاهدًا عليكم بما صدر منكم من الكفر والعصيان، كما أرسلنا موسى رسولا إلى الطاغية فرعون، فكذَّب فرعون بموسى، ولم يؤمن برسالته، وعصى أمره، فأهلكناه إهلاكًا شديدًا. وفي هذا تحذير من معصية الرسول محمد، صلى الله عليه وسلم؛ خشية أن يصيب العاصي مثل ما أصاب فرعون وقومه.", "isBasmala": false, "translation_en": "But Pharaoh defied the Messenger, so We seized him with a terrible seizing.", "translation_id": "Maka Fir'aun mendurhakai Rasul itu, lalu Kami siksa dia dengan siksaan yang berat.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 17, "text": "فَكَیۡفَ تَتَّقُونَ إِن كَفَرۡتُمۡ یَوۡمࣰا یَجۡعَلُ ٱلۡوِلۡدَ ٰنَ شِیبًا ۝١٧", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "فكيف تَقُون أنفسكم- إن كفرتم- عذاب يوم القيامة الذي يشيب فيه الولدان الصغار؛ مِن شدة هوله وكربه؟", "isBasmala": false, "translation_en": "So how will you, if you persist in unbelief, save yourself from a Day which will turn the children gray-haired?", "translation_id": "Maka bagaimanakah kamu akan dapat memelihara dirimu jika kamu tetap kafir kepada hari yang menjadikan anak-anak beruban.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 18, "text": "ٱلسَّمَاۤءُ مُنفَطِرُۢ بِهِۦۚ كَانَ وَعۡدُهُۥ مَفۡعُولًا ۝١٨", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "السماء متصدعة في ذلك اليوم؛ لشدة هوله، كان وعد الله تعالى بمجيء ذلك اليوم واقعًا لا محالة.", "isBasmala": false, "translation_en": "The heaven will shatter thereby. His promise is always fulfilled.", "translation_id": "Langit(pun) menjadi pecah belah pada hari itu. Adalah janji-Nya itu pasti terlaksana.", "manzil": 7, "manzil_display": ""}, {"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 19, "text": "إِنَّ هَـٰذِهِۦ تَذۡكِرَةࣱۖ فَمَن شَاۤءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِیلًا ۝١٩", "juz": 29, "hizb": "(* ح 58*)", "tafsir": "إن هذه الآيات المخوفة التي فيها القوارع والزواجر عظة وعبرة للناس، فمن أراد الاتعاظ والانتفاع بها اتخذ الطاعة والتقوى طريقًا توصله إلى رضوان ربه الذي خلقه وربَّاه.", "isBasmala": false, "translation_en": "This is a reminder. So whoever wills, let him take a path to his Lord.", "translation_id": "Sesungguhnya ini adalah suatu peringatan. Maka barangsiapa yang menghendaki niscaya ia menempuh jalan (yang menyampaikannya) kepada Tuhannya.", "manzil": 7, "manzil_display": ""}], "575": [{"sura": 73, "sura_name": "المزمل", "revelation": "Makkiyah", "aya": 20, "text": "۞ إِنَّ رَبَّكَ یَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَیِ ٱلَّیۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَاۤىِٕفَةࣱ مِّنَ ٱلَّذِینَ مَعَكَۚ وَٱللَّهُ یُقَدِّرُ ٱلَّیۡلَ وَٱلنَّهَارَۚ عَلِمَ أَن لَّن تُحۡصُوهُ فَتَابَ عَلَیۡكُمۡۖ فَٱقۡرَءُوا۟ مَا تَیَسَّرَ مِنَ ٱلۡقُرۡءَانِۚ عَلِمَ أَن سَیَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ یَضۡرِبُونَ فِی ٱلۡأَرۡضِ یَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ یُقَـٰتِلُونَ فِی سَبِیلِ ٱللَّهِۖ فَٱقۡرَءُوا۟ مَا تَیَسَّرَ مِنۡهُۚ وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَأَقۡرِضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰاۚ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنۡ خَیۡرࣲ تَجِدُوهُ عِندَ ٱللَّهِ هُوَ خَیۡرࣰا وَأَعۡظَمَ أَجۡرࣰاۚ وَٱسۡتَغۡفِرُوا۟ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمُۢ ۝٢٠", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "إن ربك -أيها النبي- يعلم أنك تقوم للتهجد من الليل أقل من ثلثيه حينًا، وتقوم نصفه حينًا، وتقوم ثلثه حينًا آخر، ويقوم معك طائفة من أصحابك. والله وحده هو الذي يقدِّر الليل والنهار، ويعلم مقاديرهما، وما يمضي ويبقى منهما، علم الله أنه لا يمكنكم قيام الليل كله، فخفَّف عليكم، فاقرؤوا في الصلاة بالليل ما تيسر لكم قراءته من القرآن، علم الله أنه سيوجد فيكم مَن يُعجزه المرض عن قيام الليل، ويوجد قوم آخرون يتنقَّلون في الأرض للتجارة والعمل يطلبون من رزق الله الحلال، وقوم آخرون يجاهدون في سبيل الله؛ لإعلاء كلمته ونشر دينه، فاقرؤوا في صلاتكم ما تيسَّر لكم من القرآن، وواظبوا على فرائض الصلاة، وأعطوا الزكاة الواجبة عليكم، وتصدَّقوا في وجوه البر والإحسان مِن أموالكم؛ ابتغاء وجه الله، وما تفعلوا مِن وجوه البر والخير وعمل الطاعات، تلقَوا أجره وثوابه عند الله يوم القيامة خيرًا مما قدَّمتم في الدنيا، وأعظم منه ثوابًا، واطلبوا مغفرة الله في جميع أحوالكم، إن الله غفور لكم رحيم بكم.", "isBasmala": false, "translation_en": "Your Lord knows that you stay up nearly two-thirds of the night, or half of it, or one-third of it, along with a group of those with you. God designed the night and the day. He knows that you are unable to sustain it, so He has pardoned you. So read of the Quran what is possible for you. He knows that some of you may be ill; and others travelling through the land, seeking God's bounty; and others fighting in God's cause. So read of it what is possible for you, and observe the prayers, and give regular charity, and lend God a generous loan. Whatever good you advance for yourselves, you will find it with God, better and generously rewarded. And seek God's forgiveness, for God is Forgiving and Merciful.", "translation_id": "Sesungguhnya Tuhanmu mengetahui bahwasanya kamu berdiri (sembahyang) kurang dari dua pertiga malam, atau seperdua malam atau sepertiganya dan (demikian pula) segolongan dari orang-orang yang bersama kamu. Dan Allah menetapkan ukuran malam dan siang. Allah mengetahui bahwa kamu sekali-kali tidak dapat menentukan batas-batas waktu-waktu itu, maka Dia memberi keringanan kepadamu, karena itu bacalah apa yang mudah (bagimu) dari Al Quran. Dia mengetahui bahwa akan ada di antara kamu orang-orang yang sakit dan orang-orang yang berjalan di muka bumi mencari sebagian karunia Allah; dan orang-orang yang lain lagi berperang di jalan Allah, maka bacalah apa yang mudah (bagimu) dari Al Quran dan dirikanlah sembahyang, tunaikanlah zakat dan berikanlah pinjaman kepada Allah pinjaman yang baik. Dan kebaikan apa saja yang kamu perbuat untuk dirimu niscaya kamu memperoleh (balasan)nya di sisi Allah sebagai balasan yang paling baik dan yang paling besar pahalanya. Dan mohonlah ampunan kepada Allah; sesungguhnya Allah Maha Pengampun lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 1, "text": "یَـٰۤأَیُّهَا ٱلۡمُدَّثِّرُ ۝١", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم مِن مضجعك، فحذِّر الناس من عذاب الله، وخُصَّ ربك وحده بالتعظيم والتوحيد والعبادة، وَطَهِّر ثيابك من النجاسات؛ فإن طهارة الظاهر من تمام طهارة الباطن، ودُمْ على هَجْر الأصنام والأوثان وأعمال الشرك كلها، فلا تقربها، ولا تُعط العطيَّة؛ كي تلتمس أكثر منها، ولمرضاة ربك فاصبر على الأوامر والنواهي.", "isBasmala": false, "translation_en": "O you Enrobed one.", "translation_id": "Hai orang yang berkemul (berselimut),", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 2, "text": "قُمۡ فَأَنذِرۡ ۝٢", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم مِن مضجعك، فحذِّر الناس من عذاب الله، وخُصَّ ربك وحده بالتعظيم والتوحيد والعبادة، وَطَهِّر ثيابك من النجاسات؛ فإن طهارة الظاهر من تمام طهارة الباطن، ودُمْ على هَجْر الأصنام والأوثان وأعمال الشرك كلها، فلا تقربها، ولا تُعط العطيَّة؛ كي تلتمس أكثر منها، ولمرضاة ربك فاصبر على الأوامر والنواهي.", "isBasmala": false, "translation_en": "Arise and warn.", "translation_id": "bangunlah, lalu berilah peringatan!", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 3, "text": "وَرَبَّكَ فَكَبِّرۡ ۝٣", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم مِن مضجعك، فحذِّر الناس من عذاب الله، وخُصَّ ربك وحده بالتعظيم والتوحيد والعبادة، وَطَهِّر ثيابك من النجاسات؛ فإن طهارة الظاهر من تمام طهارة الباطن، ودُمْ على هَجْر الأصنام والأوثان وأعمال الشرك كلها، فلا تقربها، ولا تُعط العطيَّة؛ كي تلتمس أكثر منها، ولمرضاة ربك فاصبر على الأوامر والنواهي.", "isBasmala": false, "translation_en": "And magnify your Lord.", "translation_id": "dan Tuhanmu agungkanlah!", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 4, "text": "وَثِیَابَكَ فَطَهِّرۡ ۝٤", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم مِن مضجعك، فحذِّر الناس من عذاب الله، وخُصَّ ربك وحده بالتعظيم والتوحيد والعبادة، وَطَهِّر ثيابك من النجاسات؛ فإن طهارة الظاهر من تمام طهارة الباطن، ودُمْ على هَجْر الأصنام والأوثان وأعمال الشرك كلها، فلا تقربها، ولا تُعط العطيَّة؛ كي تلتمس أكثر منها، ولمرضاة ربك فاصبر على الأوامر والنواهي.", "isBasmala": false, "translation_en": "And purify your clothes.", "translation_id": "dan pakaianmu bersihkanlah,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 5, "text": "وَٱلرُّجۡزَ فَٱهۡجُرۡ ۝٥", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم مِن مضجعك، فحذِّر الناس من عذاب الله، وخُصَّ ربك وحده بالتعظيم والتوحيد والعبادة، وَطَهِّر ثيابك من النجاسات؛ فإن طهارة الظاهر من تمام طهارة الباطن، ودُمْ على هَجْر الأصنام والأوثان وأعمال الشرك كلها، فلا تقربها، ولا تُعط العطيَّة؛ كي تلتمس أكثر منها، ولمرضاة ربك فاصبر على الأوامر والنواهي.", "isBasmala": false, "translation_en": "And abandon abominations.", "translation_id": "dan perbuatan dosa tinggalkanlah,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 6, "text": "وَلَا تَمۡنُن تَسۡتَكۡثِرُ ۝٦", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم مِن مضجعك، فحذِّر الناس من عذاب الله، وخُصَّ ربك وحده بالتعظيم والتوحيد والعبادة، وَطَهِّر ثيابك من النجاسات؛ فإن طهارة الظاهر من تمام طهارة الباطن، ودُمْ على هَجْر الأصنام والأوثان وأعمال الشرك كلها، فلا تقربها، ولا تُعط العطيَّة؛ كي تلتمس أكثر منها، ولمرضاة ربك فاصبر على الأوامر والنواهي.", "isBasmala": false, "translation_en": "And show no favor seeking gain.", "translation_id": "dan janganlah kamu memberi (dengan maksud) memperoleh (balasan) yang lebih banyak.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 7, "text": "وَلِرَبِّكَ فَٱصۡبِرۡ ۝٧", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "يا أيها المتغطي بثيابه، قم مِن مضجعك، فحذِّر الناس من عذاب الله، وخُصَّ ربك وحده بالتعظيم والتوحيد والعبادة، وَطَهِّر ثيابك من النجاسات؛ فإن طهارة الظاهر من تمام طهارة الباطن، ودُمْ على هَجْر الأصنام والأوثان وأعمال الشرك كلها، فلا تقربها، ولا تُعط العطيَّة؛ كي تلتمس أكثر منها، ولمرضاة ربك فاصبر على الأوامر والنواهي.", "isBasmala": false, "translation_en": "And be constant for your Lord.", "translation_id": "Dan untuk (memenuhi perintah) Tuhanmu, bersabarlah.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 8, "text": "فَإِذَا نُقِرَ فِی ٱلنَّاقُورِ ۝٨", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "فإذا نُفخ في \"القرن\" نفخة البعث والنشور، فذلك الوقت يومئذ شديد على الكافرين، غير سهل أن يخلصوا مما هم فيه من مناقشة الحساب وغيره من الأهوال.", "isBasmala": false, "translation_en": "When the Trumpet is blown.", "translation_id": "Apabila ditiup sangkakala,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 9, "text": "فَذَ ٰلِكَ یَوۡمَىِٕذࣲ یَوۡمٌ عَسِیرٌ ۝٩", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "فإذا نُفخ في \"القرن\" نفخة البعث والنشور، فذلك الوقت يومئذ شديد على الكافرين، غير سهل أن يخلصوا مما هم فيه من مناقشة الحساب وغيره من الأهوال.", "isBasmala": false, "translation_en": "That Day will be a difficult day.", "translation_id": "maka waktu itu adalah waktu (datangnya) hari yang sulit,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 10, "text": "عَلَى ٱلۡكَـٰفِرِینَ غَیۡرُ یَسِیرࣲ ۝١٠", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "فإذا نُفخ في \"القرن\" نفخة البعث والنشور، فذلك الوقت يومئذ شديد على الكافرين، غير سهل أن يخلصوا مما هم فيه من مناقشة الحساب وغيره من الأهوال.", "isBasmala": false, "translation_en": "For the disbelievers-not easy.", "translation_id": "bagi orang-orang kafir lagi tidak mudah.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 11, "text": "ذَرۡنِی وَمَنۡ خَلَقۡتُ وَحِیدࣰا ۝١١", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "دعني -أيها الرسول- أنا والذي خلقته في بطن أمه وحيدًا فريدًا لا مال له ولا ولد، وجعلت له مالا مبسوطًا واسعًا وأولادًا حضورًا معه في \"مكة\" لا يغيبون عنه، ويسَّرت له سبل العيش تيسيرًا، ثم يأمُل بعد هذا العطاء أن أزيد له في ماله وولده، وقد كفر بي. ليس الأمر كما يزعم هذا الفاجر الأثيم، لا أزيده على ذلك؛ إنه كان للقرآن وحجج الله على خلقه معاندًا مكذبًا، سأكلفه مشقة من العذاب والإرهاق لا راحة له منها. (والمراد به الوليد بن المغيرة المعاند للحق المبارز لله ولرسوله بالمحاربة، وهذا جزاء كلِّ من عاند الحق ونابذه).", "isBasmala": false, "translation_en": "Leave Me to him whom I created alone.", "translation_id": "Biarkanlah Aku bertindak terhadap orang yang Aku telah menciptakannya sendirian.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 12, "text": "وَجَعَلۡتُ لَهُۥ مَالࣰا مَّمۡدُودࣰا ۝١٢", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "دعني -أيها الرسول- أنا والذي خلقته في بطن أمه وحيدًا فريدًا لا مال له ولا ولد، وجعلت له مالا مبسوطًا واسعًا وأولادًا حضورًا معه في \"مكة\" لا يغيبون عنه، ويسَّرت له سبل العيش تيسيرًا، ثم يأمُل بعد هذا العطاء أن أزيد له في ماله وولده، وقد كفر بي. ليس الأمر كما يزعم هذا الفاجر الأثيم، لا أزيده على ذلك؛ إنه كان للقرآن وحجج الله على خلقه معاندًا مكذبًا، سأكلفه مشقة من العذاب والإرهاق لا راحة له منها. (والمراد به الوليد بن المغيرة المعاند للحق المبارز لله ولرسوله بالمحاربة، وهذا جزاء كلِّ من عاند الحق ونابذه).", "isBasmala": false, "translation_en": "And gave him vast wealth.", "translation_id": "Dan Aku jadikan baginya harta benda yang banyak,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 13, "text": "وَبَنِینَ شُهُودࣰا ۝١٣", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "دعني -أيها الرسول- أنا والذي خلقته في بطن أمه وحيدًا فريدًا لا مال له ولا ولد، وجعلت له مالا مبسوطًا واسعًا وأولادًا حضورًا معه في \"مكة\" لا يغيبون عنه، ويسَّرت له سبل العيش تيسيرًا، ثم يأمُل بعد هذا العطاء أن أزيد له في ماله وولده، وقد كفر بي. ليس الأمر كما يزعم هذا الفاجر الأثيم، لا أزيده على ذلك؛ إنه كان للقرآن وحجج الله على خلقه معاندًا مكذبًا، سأكلفه مشقة من العذاب والإرهاق لا راحة له منها. (والمراد به الوليد بن المغيرة المعاند للحق المبارز لله ولرسوله بالمحاربة، وهذا جزاء كلِّ من عاند الحق ونابذه).", "isBasmala": false, "translation_en": "And children as witnesses.", "translation_id": "dan anak-anak yang selalu bersama dia,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 14, "text": "وَمَهَّدتُّ لَهُۥ تَمۡهِیدࣰا ۝١٤", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "دعني -أيها الرسول- أنا والذي خلقته في بطن أمه وحيدًا فريدًا لا مال له ولا ولد، وجعلت له مالا مبسوطًا واسعًا وأولادًا حضورًا معه في \"مكة\" لا يغيبون عنه، ويسَّرت له سبل العيش تيسيرًا، ثم يأمُل بعد هذا العطاء أن أزيد له في ماله وولده، وقد كفر بي. ليس الأمر كما يزعم هذا الفاجر الأثيم، لا أزيده على ذلك؛ إنه كان للقرآن وحجج الله على خلقه معاندًا مكذبًا، سأكلفه مشقة من العذاب والإرهاق لا راحة له منها. (والمراد به الوليد بن المغيرة المعاند للحق المبارز لله ولرسوله بالمحاربة، وهذا جزاء كلِّ من عاند الحق ونابذه).", "isBasmala": false, "translation_en": "And smoothed things for him.", "translation_id": "dan Ku-lapangkan baginya (rezeki dan kekuasaan) dengan selapang-lapangnya,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 15, "text": "ثُمَّ یَطۡمَعُ أَنۡ أَزِیدَ ۝١٥", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "دعني -أيها الرسول- أنا والذي خلقته في بطن أمه وحيدًا فريدًا لا مال له ولا ولد، وجعلت له مالا مبسوطًا واسعًا وأولادًا حضورًا معه في \"مكة\" لا يغيبون عنه، ويسَّرت له سبل العيش تيسيرًا، ثم يأمُل بعد هذا العطاء أن أزيد له في ماله وولده، وقد كفر بي. ليس الأمر كما يزعم هذا الفاجر الأثيم، لا أزيده على ذلك؛ إنه كان للقرآن وحجج الله على خلقه معاندًا مكذبًا، سأكلفه مشقة من العذاب والإرهاق لا راحة له منها. (والمراد به الوليد بن المغيرة المعاند للحق المبارز لله ولرسوله بالمحاربة، وهذا جزاء كلِّ من عاند الحق ونابذه).", "isBasmala": false, "translation_en": "Then he wants Me to add yet more!", "translation_id": "kemudian dia ingin sekali supaya Aku menambahnya.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 16, "text": "كَلَّاۤۖ إِنَّهُۥ كَانَ لِـَٔایَـٰتِنَا عَنِیدࣰا ۝١٦", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "دعني -أيها الرسول- أنا والذي خلقته في بطن أمه وحيدًا فريدًا لا مال له ولا ولد، وجعلت له مالا مبسوطًا واسعًا وأولادًا حضورًا معه في \"مكة\" لا يغيبون عنه، ويسَّرت له سبل العيش تيسيرًا، ثم يأمُل بعد هذا العطاء أن أزيد له في ماله وولده، وقد كفر بي. ليس الأمر كما يزعم هذا الفاجر الأثيم، لا أزيده على ذلك؛ إنه كان للقرآن وحجج الله على خلقه معاندًا مكذبًا، سأكلفه مشقة من العذاب والإرهاق لا راحة له منها. (والمراد به الوليد بن المغيرة المعاند للحق المبارز لله ولرسوله بالمحاربة، وهذا جزاء كلِّ من عاند الحق ونابذه).", "isBasmala": false, "translation_en": "By no means! He was stubborn towards Our revelations.", "translation_id": "Sekali-kali tidak (akan Aku tambah), karena sesungguhnya dia menentang ayat-ayat Kami (Al Quran).", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 17, "text": "سَأُرۡهِقُهُۥ صَعُودًا ۝١٧", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "دعني -أيها الرسول- أنا والذي خلقته في بطن أمه وحيدًا فريدًا لا مال له ولا ولد، وجعلت له مالا مبسوطًا واسعًا وأولادًا حضورًا معه في \"مكة\" لا يغيبون عنه، ويسَّرت له سبل العيش تيسيرًا، ثم يأمُل بعد هذا العطاء أن أزيد له في ماله وولده، وقد كفر بي. ليس الأمر كما يزعم هذا الفاجر الأثيم، لا أزيده على ذلك؛ إنه كان للقرآن وحجج الله على خلقه معاندًا مكذبًا، سأكلفه مشقة من العذاب والإرهاق لا راحة له منها. (والمراد به الوليد بن المغيرة المعاند للحق المبارز لله ولرسوله بالمحاربة، وهذا جزاء كلِّ من عاند الحق ونابذه).", "isBasmala": false, "translation_en": "I will exhaust him increasingly.", "translation_id": "Aku akan membebaninya mendaki pendakian yang memayahkan.", "manzil": 7, "manzil_display": ""}], "576": [{"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 18, "text": "إِنَّهُۥ فَكَّرَ وَقَدَّرَ ۝١٨", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "إنه فكَّر في نفسه، وهيَّأ ما يقوله من الطعن في محمد والقرآن، فَلُعِن، واستحق بذلك الهلاك، كيف أعدَّ في نفسه هذا الطعن؟ ثم لُعِن كذلك، ثم تأمَّل فيما قدَّر وهيَّأ من الطعن في القرآن، ثم قطَّب وجهه، واشتدَّ في العبوس والكُلُوح لـمَّا ضاقت عليه الحيل، ولم يجد مطعنًا يطعن به في القرآن، ثم رجع معرضًا عن الحق، وتعاظم أن يعترف به، فقال عن القرآن: ما هذا الذي يقوله محمد إلا سحر يُنْقل عن الأولين، ما هذا إلا كلام المخلوقين تعلَّمه محمد منهم، ثم ادَّعى أنه من عند الله.", "isBasmala": false, "translation_en": "He thought and analyzed.", "translation_id": "Sesungguhnya dia telah memikirkan dan menetapkan (apa yang ditetapkannya),", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 19, "text": "فَقُتِلَ كَیۡفَ قَدَّرَ ۝١٩", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "إنه فكَّر في نفسه، وهيَّأ ما يقوله من الطعن في محمد والقرآن، فَلُعِن، واستحق بذلك الهلاك، كيف أعدَّ في نفسه هذا الطعن؟ ثم لُعِن كذلك، ثم تأمَّل فيما قدَّر وهيَّأ من الطعن في القرآن، ثم قطَّب وجهه، واشتدَّ في العبوس والكُلُوح لـمَّا ضاقت عليه الحيل، ولم يجد مطعنًا يطعن به في القرآن، ثم رجع معرضًا عن الحق، وتعاظم أن يعترف به، فقال عن القرآن: ما هذا الذي يقوله محمد إلا سحر يُنْقل عن الأولين، ما هذا إلا كلام المخلوقين تعلَّمه محمد منهم، ثم ادَّعى أنه من عند الله.", "isBasmala": false, "translation_en": "May he perish, how he analyzed.", "translation_id": "maka celakalah dia! Bagaimana dia menetapkan?,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 20, "text": "ثُمَّ قُتِلَ كَیۡفَ قَدَّرَ ۝٢٠", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "إنه فكَّر في نفسه، وهيَّأ ما يقوله من الطعن في محمد والقرآن، فَلُعِن، واستحق بذلك الهلاك، كيف أعدَّ في نفسه هذا الطعن؟ ثم لُعِن كذلك، ثم تأمَّل فيما قدَّر وهيَّأ من الطعن في القرآن، ثم قطَّب وجهه، واشتدَّ في العبوس والكُلُوح لـمَّا ضاقت عليه الحيل، ولم يجد مطعنًا يطعن به في القرآن، ثم رجع معرضًا عن الحق، وتعاظم أن يعترف به، فقال عن القرآن: ما هذا الذي يقوله محمد إلا سحر يُنْقل عن الأولين، ما هذا إلا كلام المخلوقين تعلَّمه محمد منهم، ثم ادَّعى أنه من عند الله.", "isBasmala": false, "translation_en": "Again: may he perish, how he analyzed.", "translation_id": "kemudian celakalah dia! Bagaimanakah dia menetapkan?,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 21, "text": "ثُمَّ نَظَرَ ۝٢١", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "إنه فكَّر في نفسه، وهيَّأ ما يقوله من الطعن في محمد والقرآن، فَلُعِن، واستحق بذلك الهلاك، كيف أعدَّ في نفسه هذا الطعن؟ ثم لُعِن كذلك، ثم تأمَّل فيما قدَّر وهيَّأ من الطعن في القرآن، ثم قطَّب وجهه، واشتدَّ في العبوس والكُلُوح لـمَّا ضاقت عليه الحيل، ولم يجد مطعنًا يطعن به في القرآن، ثم رجع معرضًا عن الحق، وتعاظم أن يعترف به، فقال عن القرآن: ما هذا الذي يقوله محمد إلا سحر يُنْقل عن الأولين، ما هذا إلا كلام المخلوقين تعلَّمه محمد منهم، ثم ادَّعى أنه من عند الله.", "isBasmala": false, "translation_en": "Then he looked.", "translation_id": "kemudian dia memikirkan,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 22, "text": "ثُمَّ عَبَسَ وَبَسَرَ ۝٢٢", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "إنه فكَّر في نفسه، وهيَّأ ما يقوله من الطعن في محمد والقرآن، فَلُعِن، واستحق بذلك الهلاك، كيف أعدَّ في نفسه هذا الطعن؟ ثم لُعِن كذلك، ثم تأمَّل فيما قدَّر وهيَّأ من الطعن في القرآن، ثم قطَّب وجهه، واشتدَّ في العبوس والكُلُوح لـمَّا ضاقت عليه الحيل، ولم يجد مطعنًا يطعن به في القرآن، ثم رجع معرضًا عن الحق، وتعاظم أن يعترف به، فقال عن القرآن: ما هذا الذي يقوله محمد إلا سحر يُنْقل عن الأولين، ما هذا إلا كلام المخلوقين تعلَّمه محمد منهم، ثم ادَّعى أنه من عند الله.", "isBasmala": false, "translation_en": "Then he frowned and whined.", "translation_id": "sesudah itu dia bermasam muka dan merengut,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 23, "text": "ثُمَّ أَدۡبَرَ وَٱسۡتَكۡبَرَ ۝٢٣", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "إنه فكَّر في نفسه، وهيَّأ ما يقوله من الطعن في محمد والقرآن، فَلُعِن، واستحق بذلك الهلاك، كيف أعدَّ في نفسه هذا الطعن؟ ثم لُعِن كذلك، ثم تأمَّل فيما قدَّر وهيَّأ من الطعن في القرآن، ثم قطَّب وجهه، واشتدَّ في العبوس والكُلُوح لـمَّا ضاقت عليه الحيل، ولم يجد مطعنًا يطعن به في القرآن، ثم رجع معرضًا عن الحق، وتعاظم أن يعترف به، فقال عن القرآن: ما هذا الذي يقوله محمد إلا سحر يُنْقل عن الأولين، ما هذا إلا كلام المخلوقين تعلَّمه محمد منهم، ثم ادَّعى أنه من عند الله.", "isBasmala": false, "translation_en": "Then he turned back and was proud.", "translation_id": "kemudian dia berpaling (dari kebenaran) dan menyombongkan diri,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 24, "text": "فَقَالَ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ یُؤۡثَرُ ۝٢٤", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "إنه فكَّر في نفسه، وهيَّأ ما يقوله من الطعن في محمد والقرآن، فَلُعِن، واستحق بذلك الهلاك، كيف أعدَّ في نفسه هذا الطعن؟ ثم لُعِن كذلك، ثم تأمَّل فيما قدَّر وهيَّأ من الطعن في القرآن، ثم قطَّب وجهه، واشتدَّ في العبوس والكُلُوح لـمَّا ضاقت عليه الحيل، ولم يجد مطعنًا يطعن به في القرآن، ثم رجع معرضًا عن الحق، وتعاظم أن يعترف به، فقال عن القرآن: ما هذا الذي يقوله محمد إلا سحر يُنْقل عن الأولين، ما هذا إلا كلام المخلوقين تعلَّمه محمد منهم، ثم ادَّعى أنه من عند الله.", "isBasmala": false, "translation_en": "And said, \"This is nothing but magic from the past.", "translation_id": "lalu dia berkata: \"(Al Quran) ini tidak lain hanyalah sihir yang dipelajari (dari orang-orang dahulu),", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 25, "text": "إِنۡ هَـٰذَاۤ إِلَّا قَوۡلُ ٱلۡبَشَرِ ۝٢٥", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "إنه فكَّر في نفسه، وهيَّأ ما يقوله من الطعن في محمد والقرآن، فَلُعِن، واستحق بذلك الهلاك، كيف أعدَّ في نفسه هذا الطعن؟ ثم لُعِن كذلك، ثم تأمَّل فيما قدَّر وهيَّأ من الطعن في القرآن، ثم قطَّب وجهه، واشتدَّ في العبوس والكُلُوح لـمَّا ضاقت عليه الحيل، ولم يجد مطعنًا يطعن به في القرآن، ثم رجع معرضًا عن الحق، وتعاظم أن يعترف به، فقال عن القرآن: ما هذا الذي يقوله محمد إلا سحر يُنْقل عن الأولين، ما هذا إلا كلام المخلوقين تعلَّمه محمد منهم، ثم ادَّعى أنه من عند الله.", "isBasmala": false, "translation_en": "This is nothing but the word of a mortal.\"", "translation_id": "ini tidak lain hanyalah perkataan manusia\".", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 26, "text": "سَأُصۡلِیهِ سَقَرَ ۝٢٦", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "سأدخله جهنم؛ كي يصلى حرَّها ويحترق بنارها وما أعلمك أيُّ شيء جهنم؟ لا تبقي لحمًا ولا تترك عظمًا إلا أحرقته، مغيِّرة للبشرة، مسوِّدة للجلود، محرقة لها، يلي أمرها ويتسلط على أهلها بالعذاب تسعة عشر ملكًا من الزبانية الأشداء.", "isBasmala": false, "translation_en": "I will roast him in Saqar.", "translation_id": "Aku akan memasukkannya ke dalam (neraka) Saqar.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 27, "text": "وَمَاۤ أَدۡرَىٰكَ مَا سَقَرُ ۝٢٧", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "سأدخله جهنم؛ كي يصلى حرَّها ويحترق بنارها وما أعلمك أيُّ شيء جهنم؟ لا تبقي لحمًا ولا تترك عظمًا إلا أحرقته، مغيِّرة للبشرة، مسوِّدة للجلود، محرقة لها، يلي أمرها ويتسلط على أهلها بالعذاب تسعة عشر ملكًا من الزبانية الأشداء.", "isBasmala": false, "translation_en": "But what will explain to you what Saqar is?", "translation_id": "Tahukah kamu apakah (neraka) Saqar itu?", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 28, "text": "لَا تُبۡقِی وَلَا تَذَرُ ۝٢٨", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "سأدخله جهنم؛ كي يصلى حرَّها ويحترق بنارها وما أعلمك أيُّ شيء جهنم؟ لا تبقي لحمًا ولا تترك عظمًا إلا أحرقته، مغيِّرة للبشرة، مسوِّدة للجلود، محرقة لها، يلي أمرها ويتسلط على أهلها بالعذاب تسعة عشر ملكًا من الزبانية الأشداء.", "isBasmala": false, "translation_en": "It neither leaves, nor spares.", "translation_id": "Saqar itu tidak meninggalkan dan tidak membiarkan.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 29, "text": "لَوَّاحَةࣱ لِّلۡبَشَرِ ۝٢٩", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "سأدخله جهنم؛ كي يصلى حرَّها ويحترق بنارها وما أعلمك أيُّ شيء جهنم؟ لا تبقي لحمًا ولا تترك عظمًا إلا أحرقته، مغيِّرة للبشرة، مسوِّدة للجلود، محرقة لها، يلي أمرها ويتسلط على أهلها بالعذاب تسعة عشر ملكًا من الزبانية الأشداء.", "isBasmala": false, "translation_en": "It scorches the flesh.", "translation_id": "(Neraka Saqar) adalah pembakar kulit manusia.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 30, "text": "عَلَیۡهَا تِسۡعَةَ عَشَرَ ۝٣٠", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "سأدخله جهنم؛ كي يصلى حرَّها ويحترق بنارها وما أعلمك أيُّ شيء جهنم؟ لا تبقي لحمًا ولا تترك عظمًا إلا أحرقته، مغيِّرة للبشرة، مسوِّدة للجلود، محرقة لها، يلي أمرها ويتسلط على أهلها بالعذاب تسعة عشر ملكًا من الزبانية الأشداء.", "isBasmala": false, "translation_en": "Over it are Nineteen.", "translation_id": "Dan di atasnya ada sembilan belas (malaikat penjaga).", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 31, "text": "وَمَا جَعَلۡنَاۤ أَصۡحَـٰبَ ٱلنَّارِ إِلَّا مَلَـٰۤىِٕكَةࣰۖ وَمَا جَعَلۡنَا عِدَّتَهُمۡ إِلَّا فِتۡنَةࣰ لِّلَّذِینَ كَفَرُوا۟ لِیَسۡتَیۡقِنَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ وَیَزۡدَادَ ٱلَّذِینَ ءَامَنُوۤا۟ إِیمَـٰنࣰا وَلَا یَرۡتَابَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ وَٱلۡمُؤۡمِنُونَ وَلِیَقُولَ ٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ وَٱلۡكَـٰفِرُونَ مَاذَاۤ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلࣰاۚ كَذَ ٰلِكَ یُضِلُّ ٱللَّهُ مَن یَشَاۤءُ وَیَهۡدِی مَن یَشَاۤءُۚ وَمَا یَعۡلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَۚ وَمَا هِیَ إِلَّا ذِكۡرَىٰ لِلۡبَشَرِ ۝٣١", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "وما جعلنا خزنة النار إلا من الملائكة الغلاظ، وما جعلنا ذلك العدد إلا اختبارًا للذين كفروا بالله؛ وليحصل اليقين للذين أُعطوا الكتاب من اليهود والنصارى بأنَّ ما جاء في القرآن عن خزنة جهنم إنما هو حق من الله تعالى، حيث وافق ذلك كتبهم، ويزداد المؤمنون تصديقًا بالله ورسوله وعملا بشرعه، ولا يشك في ذلك الذين أُعطوا الكتاب من اليهود والنصارى ولا المؤمنون بالله ورسوله؛ وليقول الذين في قلوبهم نفاق والكافرون: ما الذي أراده الله بهذا العدد المستغرب؟ بمثل ذلك الذي ذُكر يضلُّ الله من أراد إضلاله، ويهدي مَن أراد هدايته، وما يعلم عدد جنود ربك - ومنهم الملائكة- إلا الله وحده. وما النار إلا تذكرة وموعظة للناس.", "isBasmala": false, "translation_en": "We have appointed only angels to be wardens of the Fire, and caused their number to be a stumbling block for those who disbelieve; so that those given the Scripture may attain certainty; and those who believe may increase in faith; and those given the Scripture and the believers may not doubt; and those in whose hearts is sickness and the unbelievers may say, \"What did God intend by this parable?\" Thus God leads astray whom He wills, and guides whom He wills. None knows the soldiers of your Lord except He. This is nothing but a reminder for the mortals.", "translation_id": "Dan tiada Kami jadikan penjaga neraka itu melainkan dari malaikat: dan tidaklah Kami menjadikan bilangan mereka itu melainkan untuk jadi cobaan bagi orang-orang kafir, supaya orang-orang yang diberi Al-Kitab menjadi yakin dan supaya orang yang beriman bertambah imannya dan supaya orang-orang yang diberi Al Kitab dan orng-orang mukmin itu tidak ragu-ragu dan supaya orang-orang yang di dalam hatinya ada penyakit dan orang-orang kafir (mengatakan): \"Apakah yang dikehendaki Allah dengan bilangan ini sebagai suatu perumpamaan?\" Demikianlah Allah membiarkan sesat orang-orang yang dikehendaki-Nya dan memberi petunjuk kepada siapa yang dikehendaki-Nya. Dan tidak ada yang mengetahui tentara Tuhanmu melainkan Dia sendiri. Dan Saqar itu tiada lain hanyalah peringatan bagi manusia.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 32, "text": "كَلَّا وَٱلۡقَمَرِ ۝٣٢", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "ليس الأمر كما ذكروا من التكذيب للرسول فيما جاء به، أقسم الله سبحانه بالقمر، وبالليل إذ ولى وذهب، وبالصبح إذا أضاء وانكشف. إن النار لإحدى العظائم؛ إنذارًا وتخويفًا للناس، لمن أراد منكم أن يتقرَّب إلى ربه بفعل الطاعات، أو يتأخر بفعل المعاصي.", "isBasmala": false, "translation_en": "Nay! By the moon.", "translation_id": "Sekali-kali tidak, demi bulan,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 33, "text": "وَٱلَّیۡلِ إِذۡ أَدۡبَرَ ۝٣٣", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "ليس الأمر كما ذكروا من التكذيب للرسول فيما جاء به، أقسم الله سبحانه بالقمر، وبالليل إذ ولى وذهب، وبالصبح إذا أضاء وانكشف. إن النار لإحدى العظائم؛ إنذارًا وتخويفًا للناس، لمن أراد منكم أن يتقرَّب إلى ربه بفعل الطاعات، أو يتأخر بفعل المعاصي.", "isBasmala": false, "translation_en": "And the night as it retreats.", "translation_id": "dan malam ketika telah berlalu,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 34, "text": "وَٱلصُّبۡحِ إِذَاۤ أَسۡفَرَ ۝٣٤", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "ليس الأمر كما ذكروا من التكذيب للرسول فيما جاء به، أقسم الله سبحانه بالقمر، وبالليل إذ ولى وذهب، وبالصبح إذا أضاء وانكشف. إن النار لإحدى العظائم؛ إنذارًا وتخويفًا للناس، لمن أراد منكم أن يتقرَّب إلى ربه بفعل الطاعات، أو يتأخر بفعل المعاصي.", "isBasmala": false, "translation_en": "And the morning as it lights up.", "translation_id": "dan subuh apabila mulai terang.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 35, "text": "إِنَّهَا لَإِحۡدَى ٱلۡكُبَرِ ۝٣٥", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "ليس الأمر كما ذكروا من التكذيب للرسول فيما جاء به، أقسم الله سبحانه بالقمر، وبالليل إذ ولى وذهب، وبالصبح إذا أضاء وانكشف. إن النار لإحدى العظائم؛ إنذارًا وتخويفًا للناس، لمن أراد منكم أن يتقرَّب إلى ربه بفعل الطاعات، أو يتأخر بفعل المعاصي.", "isBasmala": false, "translation_en": "It is one of the greatest.", "translation_id": "Sesungguhnya Saqar itu adalah salah satu bencana yang amat besar,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 36, "text": "نَذِیرࣰا لِّلۡبَشَرِ ۝٣٦", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "ليس الأمر كما ذكروا من التكذيب للرسول فيما جاء به، أقسم الله سبحانه بالقمر، وبالليل إذ ولى وذهب، وبالصبح إذا أضاء وانكشف. إن النار لإحدى العظائم؛ إنذارًا وتخويفًا للناس، لمن أراد منكم أن يتقرَّب إلى ربه بفعل الطاعات، أو يتأخر بفعل المعاصي.", "isBasmala": false, "translation_en": "A warning to the mortals.", "translation_id": "sebagai ancaman bagi manusia.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 37, "text": "لِمَن شَاۤءَ مِنكُمۡ أَن یَتَقَدَّمَ أَوۡ یَتَأَخَّرَ ۝٣٧", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "ليس الأمر كما ذكروا من التكذيب للرسول فيما جاء به، أقسم الله سبحانه بالقمر، وبالليل إذ ولى وذهب، وبالصبح إذا أضاء وانكشف. إن النار لإحدى العظائم؛ إنذارًا وتخويفًا للناس، لمن أراد منكم أن يتقرَّب إلى ربه بفعل الطاعات، أو يتأخر بفعل المعاصي.", "isBasmala": false, "translation_en": "To whomever among you wishes to advance, or regress.", "translation_id": "(Yaitu) bagi siapa di antaramu yang berkehendak akan maju atau mundur.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 38, "text": "كُلُّ نَفۡسِۭ بِمَا كَسَبَتۡ رَهِینَةٌ ۝٣٨", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "Every soul is hostage to what it has earned.", "translation_id": "Tiap-tiap diri bertanggung jawab atas apa yang telah diperbuatnya,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 39, "text": "إِلَّاۤ أَصۡحَـٰبَ ٱلۡیَمِینِ ۝٣٩", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "Except for those on the Right.", "translation_id": "kecuali golongan kanan,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 40, "text": "فِی جَنَّـٰتࣲ یَتَسَاۤءَلُونَ ۝٤٠", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "In Gardens, inquiring.", "translation_id": "berada di dalam surga, mereka tanya menanya,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 41, "text": "عَنِ ٱلۡمُجۡرِمِینَ ۝٤١", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "About the guilty.", "translation_id": "tentang (keadaan) orang-orang yang berdosa,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 42, "text": "مَا سَلَكَكُمۡ فِی سَقَرَ ۝٤٢", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "\"What drove you into Saqar?\"", "translation_id": "\"Apakah yang memasukkan kamu ke dalam Saqar (neraka)?\"", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 43, "text": "قَالُوا۟ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّینَ ۝٤٣", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "They will say, \"We were not of those who prayed.", "translation_id": "Mereka menjawab: \"Kami dahulu tidak termasuk orang-orang yang mengerjakan shalat,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 44, "text": "وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِینَ ۝٤٤", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "Nor did we feed the destitute.", "translation_id": "dan kami tidak (pula) memberi makan orang miskin,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 45, "text": "وَكُنَّا نَخُوضُ مَعَ ٱلۡخَاۤىِٕضِینَ ۝٤٥", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "And we used to indulge with those who indulge.", "translation_id": "dan adalah kami membicarakan yang bathil, bersama dengan orang-orang yang membicarakannya,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 46, "text": "وَكُنَّا نُكَذِّبُ بِیَوۡمِ ٱلدِّینِ ۝٤٦", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "And we used to deny the Day of Judgment.", "translation_id": "dan adalah kami mendustakan hari pembalasan,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 47, "text": "حَتَّىٰۤ أَتَىٰنَا ٱلۡیَقِینُ ۝٤٧", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "كل نفس بما كسبت من أعمال الشر والسوء محبوسة مرهونة بكسبها، لا تُفَكُّ حتى تؤدي ما عليها من الحقوق والعقوبات، إلا المسلمين المخلصين أصحاب اليمين الذين فكُّوا رقابهم بالطاعة، هم في جنات لا يُدْرَك وصفها، يسأل بعضهم بعضًا عن الكافرين الذين أجرموا في حق أنفسهم: ما الذي أدخلكم جهنم، وجعلكم تذوقون سعيرها؟ قال المجرمون: لم نكن من المصلِّين في الدنيا، ولم نكن نتصدق ونحسن للفقراء والمساكين، وكنا نتحدث بالباطل مع أهل الغَواية والضلالة، وكنا نكذب بيوم الحساب والجزاء، حتى جاءنا الموت، ونحن في تلك الضلالات والمنكرات.", "isBasmala": false, "translation_en": "Until the Inevitable came upon us.\"", "translation_id": "hingga datang kepada kami kematian\".", "manzil": 7, "manzil_display": ""}], "577": [{"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 48, "text": "فَمَا تَنفَعُهُمۡ شَفَـٰعَةُ ٱلشَّـٰفِعِینَ ۝٤٨", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "فما تنفعهم شفاعة الشافعين جميعًا من الملائكة والنبيين وغيرهم؛ لأن الشفاعة إنما تكون لمن ارتضاه الله، وأذن لشفيعه.", "isBasmala": false, "translation_en": "But the intercession of intercessors will not help them.", "translation_id": "Maka tidak berguna lagi bagi mereka syafa'at dari orang-orang yang memberikan syafa'at.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 49, "text": "فَمَا لَهُمۡ عَنِ ٱلتَّذۡكِرَةِ مُعۡرِضِینَ ۝٤٩", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "فما لهؤلاء المشركين عن القرآن وما فيه من المواعظ منصرفين؟ كأنهم حمر وحشية شديدة النِّفار، فرَّت من أسد كاسر.", "isBasmala": false, "translation_en": "Why are they turning away from the Reminder?", "translation_id": "Maka mengapa mereka (orang-orang kafir) berpaling dari peringatan (Allah)?,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 50, "text": "كَأَنَّهُمۡ حُمُرࣱ مُّسۡتَنفِرَةࣱ ۝٥٠", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "فما لهؤلاء المشركين عن القرآن وما فيه من المواعظ منصرفين؟ كأنهم حمر وحشية شديدة النِّفار، فرَّت من أسد كاسر.", "isBasmala": false, "translation_en": "As though they were panicked donkeys.", "translation_id": "seakan-akan mereka itu keledai liar yang lari terkejut,", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 51, "text": "فَرَّتۡ مِن قَسۡوَرَةِۭ ۝٥١", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "فما لهؤلاء المشركين عن القرآن وما فيه من المواعظ منصرفين؟ كأنهم حمر وحشية شديدة النِّفار، فرَّت من أسد كاسر.", "isBasmala": false, "translation_en": "Fleeing from a lion?", "translation_id": "lari daripada singa.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 52, "text": "بَلۡ یُرِیدُ كُلُّ ٱمۡرِىࣲٕ مِّنۡهُمۡ أَن یُؤۡتَىٰ صُحُفࣰا مُّنَشَّرَةࣰ ۝٥٢", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "بل يطمع كل واحد من هؤلاء المشركين أن يُنزل الله عليه كتابًا من السماء منشورًا، كما أنزل على محمد صلى الله عليه وسلم. ليس الأمر كما زعموا، بل الحقيقة أنهم لا يخافون الآخرة، ولا يصدِّقون بالبعث والجزاء.", "isBasmala": false, "translation_en": "Yet every one of them desires to be given scrolls unrolled.", "translation_id": "Bahkan tiap-tiap orang dari mereka berkehendak supaya diberikan kepadanya lembaran-lembaran yang terbuka.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 53, "text": "كَلَّاۖ بَل لَّا یَخَافُونَ ٱلۡـَٔاخِرَةَ ۝٥٣", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "بل يطمع كل واحد من هؤلاء المشركين أن يُنزل الله عليه كتابًا من السماء منشورًا، كما أنزل على محمد صلى الله عليه وسلم. ليس الأمر كما زعموا، بل الحقيقة أنهم لا يخافون الآخرة، ولا يصدِّقون بالبعث والجزاء.", "isBasmala": false, "translation_en": "No indeed! But they do not fear the Hereafter.", "translation_id": "Sekali-kali tidak. Sebenarnya mereka tidak takut kepada negeri akhirat.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 54, "text": "كَلَّاۤ إِنَّهُۥ تَذۡكِرَةࣱ ۝٥٤", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "حقًّا أنَّ القرآن موعظة بليغة كافية لاتِّعاظهم، فمن أراد الاتعاظ اتعظ بما فيه وانتفع بهداه، وما يتعظون به إلا أن يشاء الله لهم الهدى. هو سبحانه أهلٌ لأن يُتقى ويطاع، وأهلٌ لأن يغفر لمن آمن به وأطاعه.", "isBasmala": false, "translation_en": "Nevertheless, it is a reminder.", "translation_id": "Sekali-kali tidak demikian halnya. Sesungguhnya Al Quran itu adalah peringatan.", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 55, "text": "فَمَن شَاۤءَ ذَكَرَهُۥ ۝٥٥", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "حقًّا أنَّ القرآن موعظة بليغة كافية لاتِّعاظهم، فمن أراد الاتعاظ اتعظ بما فيه وانتفع بهداه، وما يتعظون به إلا أن يشاء الله لهم الهدى. هو سبحانه أهلٌ لأن يُتقى ويطاع، وأهلٌ لأن يغفر لمن آمن به وأطاعه.", "isBasmala": false, "translation_en": "So whoever wills, shall remember it.", "translation_id": "Maka barangsiapa menghendaki, niscaya dia mengambil pelajaran daripadanya (Al Quran).", "manzil": 7, "manzil_display": ""}, {"sura": 74, "sura_name": "المدثر", "revelation": "Makkiyah", "aya": 56, "text": "وَمَا یَذۡكُرُونَ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُۚ هُوَ أَهۡلُ ٱلتَّقۡوَىٰ وَأَهۡلُ ٱلۡمَغۡفِرَةِ ۝٥٦", "juz": 29, "hizb": "(*¼ ح 58*)", "tafsir": "حقًّا أنَّ القرآن موعظة بليغة كافية لاتِّعاظهم، فمن أراد الاتعاظ اتعظ بما فيه وانتفع بهداه، وما يتعظون به إلا أن يشاء الله لهم الهدى. هو سبحانه أهلٌ لأن يُتقى ويطاع، وأهلٌ لأن يغفر لمن آمن به وأطاعه.", "isBasmala": false, "translation_en": "But they will not remember, unless God wills. He is the Source of Righteousness, and the Source of Forgiveness.", "translation_id": "Dan mereka tidak akan mengambil pelajaran daripadanya kecuali (jika) Allah menghendakinya. Dia (Allah) adalah Tuhan Yang patut (kita) bertakwa kepada-Nya dan berhak memberi ampun.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 1, "text": "۞ لَاۤ أُقۡسِمُ بِیَوۡمِ ٱلۡقِیَـٰمَةِ ۝١", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "أقسم الله سبحانه بيوم الحساب والجزاء، وأقسم بالنفس المؤمنة التقية التي تلوم صاحبها على ترك الطاعات وفِعْل الموبقات، أن الناس يبعثون. أيظنُّ هذا الإنسان الكافر أن لن نقدر على جَمْع عظامه بعد تفرقها؟ بلى سنجمعها، قادرين على أن نجعل أصابعه أو أنامله -بعد جمعها وتأليفها- خَلْقًا سويًّا، كما كانت قبل الموت.", "isBasmala": false, "translation_en": "I swear by the Day of Resurrection.", "translation_id": "Aku bersumpah demi hari kiamat,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 2, "text": "وَلَاۤ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ ۝٢", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "أقسم الله سبحانه بيوم الحساب والجزاء، وأقسم بالنفس المؤمنة التقية التي تلوم صاحبها على ترك الطاعات وفِعْل الموبقات، أن الناس يبعثون. أيظنُّ هذا الإنسان الكافر أن لن نقدر على جَمْع عظامه بعد تفرقها؟ بلى سنجمعها، قادرين على أن نجعل أصابعه أو أنامله -بعد جمعها وتأليفها- خَلْقًا سويًّا، كما كانت قبل الموت.", "isBasmala": false, "translation_en": "And I swear by the blaming soul.", "translation_id": "dan aku bersumpah dengan jiwa yang amat menyesali (dirinya sendiri).", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 3, "text": "أَیَحۡسَبُ ٱلۡإِنسَـٰنُ أَلَّن نَّجۡمَعَ عِظَامَهُۥ ۝٣", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "أقسم الله سبحانه بيوم الحساب والجزاء، وأقسم بالنفس المؤمنة التقية التي تلوم صاحبها على ترك الطاعات وفِعْل الموبقات، أن الناس يبعثون. أيظنُّ هذا الإنسان الكافر أن لن نقدر على جَمْع عظامه بعد تفرقها؟ بلى سنجمعها، قادرين على أن نجعل أصابعه أو أنامله -بعد جمعها وتأليفها- خَلْقًا سويًّا، كما كانت قبل الموت.", "isBasmala": false, "translation_en": "Does man think that We will not reassemble his bones?", "translation_id": "Apakah manusia mengira, bahwa Kami tidak akan mengumpulkan (kembali) tulang belulangnya?", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 4, "text": "بَلَىٰ قَـٰدِرِینَ عَلَىٰۤ أَن نُّسَوِّیَ بَنَانَهُۥ ۝٤", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "أقسم الله سبحانه بيوم الحساب والجزاء، وأقسم بالنفس المؤمنة التقية التي تلوم صاحبها على ترك الطاعات وفِعْل الموبقات، أن الناس يبعثون. أيظنُّ هذا الإنسان الكافر أن لن نقدر على جَمْع عظامه بعد تفرقها؟ بلى سنجمعها، قادرين على أن نجعل أصابعه أو أنامله -بعد جمعها وتأليفها- خَلْقًا سويًّا، كما كانت قبل الموت.", "isBasmala": false, "translation_en": "Yes indeed; We are Able to reconstruct his fingertips.", "translation_id": "Bukan demikian, sebenarnya Kami kuasa menyusun (kembali) jari jemarinya dengan sempurna.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 5, "text": "بَلۡ یُرِیدُ ٱلۡإِنسَـٰنُ لِیَفۡجُرَ أَمَامَهُۥ ۝٥", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "بل ينكر الإنسان البعث، يريد أن يبقى على الفجور فيما يستقبل من أيام عمره، يسأل هذا الكافر مستبعدًا قيام الساعة: متى يكون يوم القيامة؟", "isBasmala": false, "translation_en": "But man wants to deny what is ahead of him.", "translation_id": "Bahkan manusia itu hendak membuat maksiat terus menerus.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 6, "text": "یَسۡـَٔلُ أَیَّانَ یَوۡمُ ٱلۡقِیَـٰمَةِ ۝٦", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "بل ينكر الإنسان البعث، يريد أن يبقى على الفجور فيما يستقبل من أيام عمره، يسأل هذا الكافر مستبعدًا قيام الساعة: متى يكون يوم القيامة؟", "isBasmala": false, "translation_en": "He asks, \"When is the Day of Resurrection?\"", "translation_id": "Ia berkata: \"Bilakah hari kiamat itu?\"", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 7, "text": "فَإِذَا بَرِقَ ٱلۡبَصَرُ ۝٧", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فإذا تحيَّر البصر ودُهش فزعًا مما رأى من أهوال يوم القيامة، وذهب نور القمر، وجُمِع بين الشمس والقمر في ذهاب الضوء، فلا ضوء لواحد منهما، يقول الإنسان وقتها: أين المهرب من العذاب؟", "isBasmala": false, "translation_en": "When vision is dazzled.", "translation_id": "Maka apabila mata terbelalak (ketakutan),", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 8, "text": "وَخَسَفَ ٱلۡقَمَرُ ۝٨", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فإذا تحيَّر البصر ودُهش فزعًا مما رأى من أهوال يوم القيامة، وذهب نور القمر، وجُمِع بين الشمس والقمر في ذهاب الضوء، فلا ضوء لواحد منهما، يقول الإنسان وقتها: أين المهرب من العذاب؟", "isBasmala": false, "translation_en": "And the moon is eclipsed.", "translation_id": "dan apabila bulan telah hilang cahayanya,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 9, "text": "وَجُمِعَ ٱلشَّمۡسُ وَٱلۡقَمَرُ ۝٩", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فإذا تحيَّر البصر ودُهش فزعًا مما رأى من أهوال يوم القيامة، وذهب نور القمر، وجُمِع بين الشمس والقمر في ذهاب الضوء، فلا ضوء لواحد منهما، يقول الإنسان وقتها: أين المهرب من العذاب؟", "isBasmala": false, "translation_en": "And the sun and the moon are joined together.", "translation_id": "dan matahari dan bulan dikumpulkan,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 10, "text": "یَقُولُ ٱلۡإِنسَـٰنُ یَوۡمَىِٕذٍ أَیۡنَ ٱلۡمَفَرُّ ۝١٠", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فإذا تحيَّر البصر ودُهش فزعًا مما رأى من أهوال يوم القيامة، وذهب نور القمر، وجُمِع بين الشمس والقمر في ذهاب الضوء، فلا ضوء لواحد منهما، يقول الإنسان وقتها: أين المهرب من العذاب؟", "isBasmala": false, "translation_en": "On that Day, man will say, \"Where is the escape?\"", "translation_id": "pada hari itu manusia berkata: \"Ke mana tempat berlari?\"", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 11, "text": "كَلَّا لَا وَزَرَ ۝١١", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ليس الأمر كما تتمناه- أيها الإنسان- مِن طلب الفرار، لا ملجأ لك ولا منجى. إلى الله وحده مصير الخلائق يوم القيامة ومستقرهم، فيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "No indeed! There is no refuge.", "translation_id": "sekali-kali tidak! Tidak ada tempat berlindung!", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 12, "text": "إِلَىٰ رَبِّكَ یَوۡمَىِٕذٍ ٱلۡمُسۡتَقَرُّ ۝١٢", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ليس الأمر كما تتمناه- أيها الإنسان- مِن طلب الفرار، لا ملجأ لك ولا منجى. إلى الله وحده مصير الخلائق يوم القيامة ومستقرهم، فيجازي كلا بما يستحق.", "isBasmala": false, "translation_en": "To your Lord on that Day is the settlement.", "translation_id": "Hanya kepada Tuhanmu sajalah pada hari itu tempat kembali.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 13, "text": "یُنَبَّؤُا۟ ٱلۡإِنسَـٰنُ یَوۡمَىِٕذِۭ بِمَا قَدَّمَ وَأَخَّرَ ۝١٣", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "يُخَبَّر الإنسان في ذلك اليوم بجميع أعماله: من خير وشر، ما قدَّمه منها في حياته وما أخَّره.", "isBasmala": false, "translation_en": "On that Day man will be informed of everything he put forward, and everything he left behind.", "translation_id": "Pada hari itu diberitakan kepada manusia apa yang telah dikerjakannya dan apa yang dilalaikannya.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 14, "text": "بَلِ ٱلۡإِنسَـٰنُ عَلَىٰ نَفۡسِهِۦ بَصِیرَةࣱ ۝١٤", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "بل الإنسان حجة واضحة على نفسه تلزمه بما فعل أو ترك، ولو جاء بكل معذرة يعتذر بها عن إجرامه، فإنه لا ينفعه ذلك.", "isBasmala": false, "translation_en": "And man will be evidence against himself.", "translation_id": "Bahkan manusia itu menjadi saksi atas dirinya sendiri,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 15, "text": "وَلَوۡ أَلۡقَىٰ مَعَاذِیرَهُۥ ۝١٥", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "بل الإنسان حجة واضحة على نفسه تلزمه بما فعل أو ترك، ولو جاء بكل معذرة يعتذر بها عن إجرامه، فإنه لا ينفعه ذلك.", "isBasmala": false, "translation_en": "Even as he presents his excuses.", "translation_id": "meskipun dia mengemukakan alasan-alasannya.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 16, "text": "لَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦۤ ۝١٦", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "لا تحرك -أيها النبي- بالقرآن لسانك حين نزول الوحي؛ لأجل أن تتعجل بحفظه، مخافة أن يتفلَّت منك. إن علينا جَمْعه في صدرك، ثم أن تقرأه بلسانك متى شئت. فإذا قرأه عليك رسولنا جبريل فاستمِعْ لقراءته وأنصت له، ثم اقرأه كما أقرأك إياه، ثم إن علينا توضيح ما أشكل عليك فهمه من معانيه وأحكامه.", "isBasmala": false, "translation_en": "Do not wag your tongue with it, to hurry on with it.", "translation_id": "Janganlah kamu gerakkan lidahmu untuk (membaca) Al Quran karena hendak cepat-cepat (menguasai)nya.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 17, "text": "إِنَّ عَلَیۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ ۝١٧", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "لا تحرك -أيها النبي- بالقرآن لسانك حين نزول الوحي؛ لأجل أن تتعجل بحفظه، مخافة أن يتفلَّت منك. إن علينا جَمْعه في صدرك، ثم أن تقرأه بلسانك متى شئت. فإذا قرأه عليك رسولنا جبريل فاستمِعْ لقراءته وأنصت له، ثم اقرأه كما أقرأك إياه، ثم إن علينا توضيح ما أشكل عليك فهمه من معانيه وأحكامه.", "isBasmala": false, "translation_en": "Upon Us is its collection and its recitation.", "translation_id": "Sesungguhnya atas tanggungan Kamilah mengumpulkannya (di dadamu) dan (membuatmu pandai) membacanya.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 18, "text": "فَإِذَا قَرَأۡنَـٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ ۝١٨", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "لا تحرك -أيها النبي- بالقرآن لسانك حين نزول الوحي؛ لأجل أن تتعجل بحفظه، مخافة أن يتفلَّت منك. إن علينا جَمْعه في صدرك، ثم أن تقرأه بلسانك متى شئت. فإذا قرأه عليك رسولنا جبريل فاستمِعْ لقراءته وأنصت له، ثم اقرأه كما أقرأك إياه، ثم إن علينا توضيح ما أشكل عليك فهمه من معانيه وأحكامه.", "isBasmala": false, "translation_en": "Then, when We have recited it, follow its recitation.", "translation_id": "Apabila Kami telah selesai membacakannya maka ikutilah bacaannya itu.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 19, "text": "ثُمَّ إِنَّ عَلَیۡنَا بَیَانَهُۥ ۝١٩", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "لا تحرك -أيها النبي- بالقرآن لسانك حين نزول الوحي؛ لأجل أن تتعجل بحفظه، مخافة أن يتفلَّت منك. إن علينا جَمْعه في صدرك، ثم أن تقرأه بلسانك متى شئت. فإذا قرأه عليك رسولنا جبريل فاستمِعْ لقراءته وأنصت له، ثم اقرأه كما أقرأك إياه، ثم إن علينا توضيح ما أشكل عليك فهمه من معانيه وأحكامه.", "isBasmala": false, "translation_en": "Then upon Us is its explanation.", "translation_id": "Kemudian, sesungguhnya atas tanggungan Kamilah penjelasannya.", "manzil": 7, "manzil_display": ""}], "578": [{"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 20, "text": "كَلَّا بَلۡ تُحِبُّونَ ٱلۡعَاجِلَةَ ۝٢٠", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ليس الأمر كما زعمتم- يا معشر المشركين- أن لا بعث ولا جزاء، بل أنتم قوم تحبون الدنيا وزينتها، وتتركون الآخرة ونعيمها.", "isBasmala": false, "translation_en": "Alas, you love the fleeting life.", "translation_id": "Sekali-kali janganlah demikian. Sebenarnya kamu (hai manusia) mencintai kehidupan dunia,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 21, "text": "وَتَذَرُونَ ٱلۡـَٔاخِرَةَ ۝٢١", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ليس الأمر كما زعمتم- يا معشر المشركين- أن لا بعث ولا جزاء، بل أنتم قوم تحبون الدنيا وزينتها، وتتركون الآخرة ونعيمها.", "isBasmala": false, "translation_en": "And you disregard the Hereafter.", "translation_id": "dan meninggalkan (kehidupan) akhirat.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 22, "text": "وُجُوهࣱ یَوۡمَىِٕذࣲ نَّاضِرَةٌ ۝٢٢", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "وجوه أهل السعادة يوم القيامة مشرقة حسنة ناعمة، ترى خالقها ومالك أمرها، فتتمتع بذلك.", "isBasmala": false, "translation_en": "Faces on that Day will be radiant.", "translation_id": "Wajah-wajah (orang-orang mukmin) pada hari itu berseri-seri.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 23, "text": "إِلَىٰ رَبِّهَا نَاظِرَةࣱ ۝٢٣", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "وجوه أهل السعادة يوم القيامة مشرقة حسنة ناعمة، ترى خالقها ومالك أمرها، فتتمتع بذلك.", "isBasmala": false, "translation_en": "Looking towards their Lord.", "translation_id": "Kepada Tuhannyalah mereka melihat.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 24, "text": "وَوُجُوهࣱ یَوۡمَىِٕذِۭ بَاسِرَةࣱ ۝٢٤", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ووجوه الأشقياء يوم القيامة عابسة كالحة، تتوقع أن تنزل بها مصيبة عظيمة، تقصم فَقَار الظَّهْر.", "isBasmala": false, "translation_en": "And faces on that Day will be gloomy.", "translation_id": "Dan wajah-wajah (orang kafir) pada hari itu muram,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 25, "text": "تَظُنُّ أَن یُفۡعَلَ بِهَا فَاقِرَةࣱ ۝٢٥", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ووجوه الأشقياء يوم القيامة عابسة كالحة، تتوقع أن تنزل بها مصيبة عظيمة، تقصم فَقَار الظَّهْر.", "isBasmala": false, "translation_en": "Realizing that a back-breaker has befallen them.", "translation_id": "mereka yakin bahwa akan ditimpakan kepadanya malapetaka yang amat dahsyat.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 26, "text": "كَلَّاۤ إِذَا بَلَغَتِ ٱلتَّرَاقِیَ ۝٢٦", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "حقًّا إذا وصلت الروح إلى أعالي الصدر، وقال بعض الحاضرين لبعض: هل مِن راق يَرْقيه ويَشْفيه مما هو فيه؟ وأيقن المحتضر أنَّ الذي نزل به هو فراق الدنيا؛ لمعاينته ملائكة الموت، واتصلت شدة آخر الدنيا بشدة أول الآخرة، إلى الله تعالى مساق العباد يوم القيامة: إما إلى الجنة وإما إلى النار.", "isBasmala": false, "translation_en": "Indeed, when it has reached the breast-bones.", "translation_id": "Sekali-kali jangan. Apabila nafas (seseorang) telah (mendesak) sampai ke kerongkongan,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 27, "text": "وَقِیلَ مَنۡۜ رَاقࣲ ۝٢٧", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "حقًّا إذا وصلت الروح إلى أعالي الصدر، وقال بعض الحاضرين لبعض: هل مِن راق يَرْقيه ويَشْفيه مما هو فيه؟ وأيقن المحتضر أنَّ الذي نزل به هو فراق الدنيا؛ لمعاينته ملائكة الموت، واتصلت شدة آخر الدنيا بشدة أول الآخرة، إلى الله تعالى مساق العباد يوم القيامة: إما إلى الجنة وإما إلى النار.", "isBasmala": false, "translation_en": "And it is said, \"Who is the healer?\"", "translation_id": "dan dikatakan (kepadanya): \"Siapakah yang dapat menyembuhkan?\",", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 28, "text": "وَظَنَّ أَنَّهُ ٱلۡفِرَاقُ ۝٢٨", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "حقًّا إذا وصلت الروح إلى أعالي الصدر، وقال بعض الحاضرين لبعض: هل مِن راق يَرْقيه ويَشْفيه مما هو فيه؟ وأيقن المحتضر أنَّ الذي نزل به هو فراق الدنيا؛ لمعاينته ملائكة الموت، واتصلت شدة آخر الدنيا بشدة أول الآخرة، إلى الله تعالى مساق العباد يوم القيامة: إما إلى الجنة وإما إلى النار.", "isBasmala": false, "translation_en": "And He realizes that it is the parting.", "translation_id": "dan dia yakin bahwa sesungguhnya itulah waktu perpisahan (dengan dunia),", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 29, "text": "وَٱلۡتَفَّتِ ٱلسَّاقُ بِٱلسَّاقِ ۝٢٩", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "حقًّا إذا وصلت الروح إلى أعالي الصدر، وقال بعض الحاضرين لبعض: هل مِن راق يَرْقيه ويَشْفيه مما هو فيه؟ وأيقن المحتضر أنَّ الذي نزل به هو فراق الدنيا؛ لمعاينته ملائكة الموت، واتصلت شدة آخر الدنيا بشدة أول الآخرة، إلى الله تعالى مساق العباد يوم القيامة: إما إلى الجنة وإما إلى النار.", "isBasmala": false, "translation_en": "And leg is entwined with leg.", "translation_id": "dan bertaut betis (kiri) dan betis (kanan),", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 30, "text": "إِلَىٰ رَبِّكَ یَوۡمَىِٕذٍ ٱلۡمَسَاقُ ۝٣٠", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "حقًّا إذا وصلت الروح إلى أعالي الصدر، وقال بعض الحاضرين لبعض: هل مِن راق يَرْقيه ويَشْفيه مما هو فيه؟ وأيقن المحتضر أنَّ الذي نزل به هو فراق الدنيا؛ لمعاينته ملائكة الموت، واتصلت شدة آخر الدنيا بشدة أول الآخرة، إلى الله تعالى مساق العباد يوم القيامة: إما إلى الجنة وإما إلى النار.", "isBasmala": false, "translation_en": "To your Lord on that Day is the drive.", "translation_id": "kepada Tuhanmulah pada hari itu kamu dihalau.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 31, "text": "فَلَا صَدَّقَ وَلَا صَلَّىٰ ۝٣١", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فلا آمن الكافر بالرسول والقرآن، ولا أدَّى لله تعالى فرائض الصلاة، ولكن كذَّب بالقرآن، وأعرض عن الإيمان، ثم مضى إلى أهله يتبختر مختالا في مشيته. هلاك لك فهلاك، ثم هلاك لك فهلاك.", "isBasmala": false, "translation_en": "He neither believed nor prayed.", "translation_id": "Dan ia tidak mau membenarkan (Rasul dan Al Quran) dan tidak mau mengerjakan shalat,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 32, "text": "وَلَـٰكِن كَذَّبَ وَتَوَلَّىٰ ۝٣٢", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فلا آمن الكافر بالرسول والقرآن، ولا أدَّى لله تعالى فرائض الصلاة، ولكن كذَّب بالقرآن، وأعرض عن الإيمان، ثم مضى إلى أهله يتبختر مختالا في مشيته. هلاك لك فهلاك، ثم هلاك لك فهلاك.", "isBasmala": false, "translation_en": "But he denied and turned away.", "translation_id": "tetapi ia mendustakan (Rasul) dam berpaling (dari kebenaran),", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 33, "text": "ثُمَّ ذَهَبَ إِلَىٰۤ أَهۡلِهِۦ یَتَمَطَّىٰۤ ۝٣٣", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فلا آمن الكافر بالرسول والقرآن، ولا أدَّى لله تعالى فرائض الصلاة، ولكن كذَّب بالقرآن، وأعرض عن الإيمان، ثم مضى إلى أهله يتبختر مختالا في مشيته. هلاك لك فهلاك، ثم هلاك لك فهلاك.", "isBasmala": false, "translation_en": "Then he went to his family, full of pride.", "translation_id": "kemudian ia pergi kepada ahlinya dengan berlagak (sombong).", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 34, "text": "أَوۡلَىٰ لَكَ فَأَوۡلَىٰ ۝٣٤", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فلا آمن الكافر بالرسول والقرآن، ولا أدَّى لله تعالى فرائض الصلاة، ولكن كذَّب بالقرآن، وأعرض عن الإيمان، ثم مضى إلى أهله يتبختر مختالا في مشيته. هلاك لك فهلاك، ثم هلاك لك فهلاك.", "isBasmala": false, "translation_en": "Woe to you; and woe.", "translation_id": "Kecelakaanlah bagimu (hai orang kafir) dan kecelakaanlah bagimu,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 35, "text": "ثُمَّ أَوۡلَىٰ لَكَ فَأَوۡلَىٰۤ ۝٣٥", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فلا آمن الكافر بالرسول والقرآن، ولا أدَّى لله تعالى فرائض الصلاة، ولكن كذَّب بالقرآن، وأعرض عن الإيمان، ثم مضى إلى أهله يتبختر مختالا في مشيته. هلاك لك فهلاك، ثم هلاك لك فهلاك.", "isBasmala": false, "translation_en": "Then again: Woe to you; and woe.", "translation_id": "kemudian kecelakaanlah bagimu (hai orang kafir) dan kecelakaanlah bagimu.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 36, "text": "أَیَحۡسَبُ ٱلۡإِنسَـٰنُ أَن یُتۡرَكَ سُدًى ۝٣٦", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "أيظنُّ هذا الإنسان المنكر للبعث أن يُترك هَمَلا لا يُؤمر ولا يُنْهى، ولا يحاسب ولا يعاقب؟ ألم يك هذا الإنسان نطفة ضعيفة من ماء مهين يراق ويصب في الأرحام، ثم صار قطعة من دم جامد، فخلقه الله بقدرته وسوَّى صورته في أحسن تقويم؟ فجعل من هذا الإنسان الصنفين: الذكر والأنثى، أليس ذلك الإله الخالق لهذه الأشياء بقادر على إعادة الخلق بعد فنائهم؟ بلى إنه - سبحانه وتعالى- لقادر على ذلك.", "isBasmala": false, "translation_en": "Does man think that he will be left without purpose?", "translation_id": "Apakah manusia mengira, bahwa ia akan dibiarkan begitu saja (tanpa pertanggung jawaban)?", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 37, "text": "أَلَمۡ یَكُ نُطۡفَةࣰ مِّن مَّنِیࣲّ یُمۡنَىٰ ۝٣٧", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "أيظنُّ هذا الإنسان المنكر للبعث أن يُترك هَمَلا لا يُؤمر ولا يُنْهى، ولا يحاسب ولا يعاقب؟ ألم يك هذا الإنسان نطفة ضعيفة من ماء مهين يراق ويصب في الأرحام، ثم صار قطعة من دم جامد، فخلقه الله بقدرته وسوَّى صورته في أحسن تقويم؟ فجعل من هذا الإنسان الصنفين: الذكر والأنثى، أليس ذلك الإله الخالق لهذه الأشياء بقادر على إعادة الخلق بعد فنائهم؟ بلى إنه - سبحانه وتعالى- لقادر على ذلك.", "isBasmala": false, "translation_en": "Was he not a drop of ejaculated semen?", "translation_id": "Bukankah dia dahulu setetes mani yang ditumpahkan (ke dalam rahim),", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 38, "text": "ثُمَّ كَانَ عَلَقَةࣰ فَخَلَقَ فَسَوَّىٰ ۝٣٨", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "أيظنُّ هذا الإنسان المنكر للبعث أن يُترك هَمَلا لا يُؤمر ولا يُنْهى، ولا يحاسب ولا يعاقب؟ ألم يك هذا الإنسان نطفة ضعيفة من ماء مهين يراق ويصب في الأرحام، ثم صار قطعة من دم جامد، فخلقه الله بقدرته وسوَّى صورته في أحسن تقويم؟ فجعل من هذا الإنسان الصنفين: الذكر والأنثى، أليس ذلك الإله الخالق لهذه الأشياء بقادر على إعادة الخلق بعد فنائهم؟ بلى إنه - سبحانه وتعالى- لقادر على ذلك.", "isBasmala": false, "translation_en": "Then he became a clot. And He created and proportioned?", "translation_id": "kemudian mani itu menjadi segumpal darah, lalu Allah menciptakannya, dan menyempurnakannya,", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 39, "text": "فَجَعَلَ مِنۡهُ ٱلزَّوۡجَیۡنِ ٱلذَّكَرَ وَٱلۡأُنثَىٰۤ ۝٣٩", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "أيظنُّ هذا الإنسان المنكر للبعث أن يُترك هَمَلا لا يُؤمر ولا يُنْهى، ولا يحاسب ولا يعاقب؟ ألم يك هذا الإنسان نطفة ضعيفة من ماء مهين يراق ويصب في الأرحام، ثم صار قطعة من دم جامد، فخلقه الله بقدرته وسوَّى صورته في أحسن تقويم؟ فجعل من هذا الإنسان الصنفين: الذكر والأنثى، أليس ذلك الإله الخالق لهذه الأشياء بقادر على إعادة الخلق بعد فنائهم؟ بلى إنه - سبحانه وتعالى- لقادر على ذلك.", "isBasmala": false, "translation_en": "And made of him the two sexes, the male and the female?", "translation_id": "lalu Allah menjadikan daripadanya sepasang: laki-laki dan perempuan.", "manzil": 7, "manzil_display": ""}, {"sura": 75, "sura_name": "القيامة", "revelation": "Makkiyah", "aya": 40, "text": "أَلَیۡسَ ذَ ٰلِكَ بِقَـٰدِرٍ عَلَىٰۤ أَن یُحۡـِۧیَ ٱلۡمَوۡتَىٰ ۝٤٠", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "أيظنُّ هذا الإنسان المنكر للبعث أن يُترك هَمَلا لا يُؤمر ولا يُنْهى، ولا يحاسب ولا يعاقب؟ ألم يك هذا الإنسان نطفة ضعيفة من ماء مهين يراق ويصب في الأرحام، ثم صار قطعة من دم جامد، فخلقه الله بقدرته وسوَّى صورته في أحسن تقويم؟ فجعل من هذا الإنسان الصنفين: الذكر والأنثى، أليس ذلك الإله الخالق لهذه الأشياء بقادر على إعادة الخلق بعد فنائهم؟ بلى إنه - سبحانه وتعالى- لقادر على ذلك.", "isBasmala": false, "translation_en": "Is He not Able to revive the dead?", "translation_id": "Bukankah (Allah yang berbuat) demikian berkuasa (pula) menghidupkan orang mati?", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 1, "text": "هَلۡ أَتَىٰ عَلَى ٱلۡإِنسَـٰنِ حِینࣱ مِّنَ ٱلدَّهۡرِ لَمۡ یَكُن شَیۡـࣰٔا مَّذۡكُورًا ۝١", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "قد مضى على الإنسان وقت طويل من الزمان قبل أن تُنفَخ فيه الروح، لم يكن شيئا يُذكر، ولا يُعرف له أثر.", "isBasmala": false, "translation_en": "Has there come upon man a period of time when he was nothing to be mentioned?", "translation_id": "Bukankah telah datang atas manusia satu waktu dari masa, sedang dia ketika itu belum merupakan sesuatu yang dapat disebut?", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 2, "text": "إِنَّا خَلَقۡنَا ٱلۡإِنسَـٰنَ مِن نُّطۡفَةٍ أَمۡشَاجࣲ نَّبۡتَلِیهِ فَجَعَلۡنَـٰهُ سَمِیعَۢا بَصِیرًا ۝٢", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "إنا خلقنا الإنسان من نطفة مختلطة من ماء الرجل وماء المرأة، نختبره بالتكاليف الشرعية فيما بعد، فجعلناه من أجل ذلك ذا سمع وذا بصر؛ ليسمع الآيات، ويرى الدلائل، إنا بينَّا له وعرَّفناه طريق الهدى والضلال والخير والشر؛ ليكون إما مؤمنًا شاكرًا، وإما كفورًا جاحدًا.", "isBasmala": false, "translation_en": "We created man from a liquid mixture, to test him; and We made him hearing and seeing.", "translation_id": "Sesungguhnya Kami telah menciptakan manusia dari setetes mani yang bercampur yang Kami hendak mengujinya (dengan perintah dan larangan), karena itu Kami jadikan dia mendengar dan melihat.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 3, "text": "إِنَّا هَدَیۡنَـٰهُ ٱلسَّبِیلَ إِمَّا شَاكِرࣰا وَإِمَّا كَفُورًا ۝٣", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "إنا خلقنا الإنسان من نطفة مختلطة من ماء الرجل وماء المرأة، نختبره بالتكاليف الشرعية فيما بعد، فجعلناه من أجل ذلك ذا سمع وذا بصر؛ ليسمع الآيات، ويرى الدلائل، إنا بينَّا له وعرَّفناه طريق الهدى والضلال والخير والشر؛ ليكون إما مؤمنًا شاكرًا، وإما كفورًا جاحدًا.", "isBasmala": false, "translation_en": "We guided him to the way, be he appreciative or unappreciative.", "translation_id": "Sesungguhnya Kami telah menunjukinya jalan yang lurus; ada yang bersyukur dan ada pula yang kafir.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 4, "text": "إِنَّاۤ أَعۡتَدۡنَا لِلۡكَـٰفِرِینَ سَلَـٰسِلَا۟ وَأَغۡلَـٰلࣰا وَسَعِیرًا ۝٤", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "إنا أعتدنا للكافرين قيودًا من حديد تُشَدُّ بها أرجلهم، وأغلالا تُغلُّ بها أيديهم إلى أعناقهم، ونارًا يُحرقون بها.", "isBasmala": false, "translation_en": "We have prepared for the faithless chains, and yokes, and a Searing Fire.", "translation_id": "Sesungguhnya Kami menyediakan bagi orang-orang kafir rantai, belenggu dan neraka yang menyala-nyala.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 5, "text": "إِنَّ ٱلۡأَبۡرَارَ یَشۡرَبُونَ مِن كَأۡسࣲ كَانَ مِزَاجُهَا كَافُورًا ۝٥", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "إن أهل الطاعة والإخلاص الذين يؤدون حق الله، يشربون يوم القيامة مِن كأس فيها خمر ممزوجة بأحسن أنواع الطيب، وهو ماء الكافور.", "isBasmala": false, "translation_en": "But the righteous will drink from a cup whose mixture is aroma.", "translation_id": "Sesungguhnya orang-orang yang berbuat kebajikan minum dari gelas (berisi minuman) yang campurannya adalah air kafur,", "manzil": 7, "manzil_display": ""}], "579": [{"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 6, "text": "عَیۡنࣰا یَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ یُفَجِّرُونَهَا تَفۡجِیرࣰا ۝٦", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "هذا الشراب الذي مزج من الكافور هو عين يشرب منها عباد الله، يتصرفون فيها، ويُجْرونها حيث شاؤوا إجراءً سهلا. هؤلاء كانوا في الدنيا يوفون بما أوجبوا على أنفسهم من طاعة الله، ويخافون عقاب الله في يوم القيامة الذي يكون ضرره خطيرًا، وشره فاشيًا منتشرًا على الناس، إلا مَن رحم الله، ويُطْعِمون الطعام مع حبهم له وحاجتهم إليه، فقيرًا عاجزًا عن الكسب لا يملك من حطام الدنيا شيئًا، وطفلا مات أبوه ولا مال له، وأسيرًا أُسر في الحرب من المشركين وغيرهم، ويقولون في أنفسهم: إنما نحسن إليكم ابتغاء مرضاة الله، وطلب ثوابه، لا نبتغي عوضًا ولا نقصد حمدًا ولا ثناءً منكم. إنا نخاف من ربنا يومًا شديدًا تَعْبِس فيه الوجوه، وتتقطَّبُ الجباه مِن فظاعة أمره وشدة هوله.", "isBasmala": false, "translation_en": "A spring from which the servants of God will drink, making it gush abundantly.", "translation_id": "(yaitu) mata air (dalam surga) yang daripadanya hamba-hamba Allah minum, yang mereka dapat mengalirkannya dengan sebaik-baiknya.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 7, "text": "یُوفُونَ بِٱلنَّذۡرِ وَیَخَافُونَ یَوۡمࣰا كَانَ شَرُّهُۥ مُسۡتَطِیرࣰا ۝٧", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "هذا الشراب الذي مزج من الكافور هو عين يشرب منها عباد الله، يتصرفون فيها، ويُجْرونها حيث شاؤوا إجراءً سهلا. هؤلاء كانوا في الدنيا يوفون بما أوجبوا على أنفسهم من طاعة الله، ويخافون عقاب الله في يوم القيامة الذي يكون ضرره خطيرًا، وشره فاشيًا منتشرًا على الناس، إلا مَن رحم الله، ويُطْعِمون الطعام مع حبهم له وحاجتهم إليه، فقيرًا عاجزًا عن الكسب لا يملك من حطام الدنيا شيئًا، وطفلا مات أبوه ولا مال له، وأسيرًا أُسر في الحرب من المشركين وغيرهم، ويقولون في أنفسهم: إنما نحسن إليكم ابتغاء مرضاة الله، وطلب ثوابه، لا نبتغي عوضًا ولا نقصد حمدًا ولا ثناءً منكم. إنا نخاف من ربنا يومًا شديدًا تَعْبِس فيه الوجوه، وتتقطَّبُ الجباه مِن فظاعة أمره وشدة هوله.", "isBasmala": false, "translation_en": "They fulfill their vows, and dread a Day whose ill is widespread.", "translation_id": "Mereka menunaikan nazar dan takut akan suatu hari yang azabnya merata di mana-mana.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 8, "text": "وَیُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِینࣰا وَیَتِیمࣰا وَأَسِیرًا ۝٨", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "هذا الشراب الذي مزج من الكافور هو عين يشرب منها عباد الله، يتصرفون فيها، ويُجْرونها حيث شاؤوا إجراءً سهلا. هؤلاء كانوا في الدنيا يوفون بما أوجبوا على أنفسهم من طاعة الله، ويخافون عقاب الله في يوم القيامة الذي يكون ضرره خطيرًا، وشره فاشيًا منتشرًا على الناس، إلا مَن رحم الله، ويُطْعِمون الطعام مع حبهم له وحاجتهم إليه، فقيرًا عاجزًا عن الكسب لا يملك من حطام الدنيا شيئًا، وطفلا مات أبوه ولا مال له، وأسيرًا أُسر في الحرب من المشركين وغيرهم، ويقولون في أنفسهم: إنما نحسن إليكم ابتغاء مرضاة الله، وطلب ثوابه، لا نبتغي عوضًا ولا نقصد حمدًا ولا ثناءً منكم. إنا نخاف من ربنا يومًا شديدًا تَعْبِس فيه الوجوه، وتتقطَّبُ الجباه مِن فظاعة أمره وشدة هوله.", "isBasmala": false, "translation_en": "And they feed, for the love of Him, the poor, and the orphan, and the captive.", "translation_id": "Dan mereka memberikan makanan yang disukainya kepada orang miskin, anak yatim dan orang yang ditawan.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 9, "text": "إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِیدُ مِنكُمۡ جَزَاۤءࣰ وَلَا شُكُورًا ۝٩", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "هذا الشراب الذي مزج من الكافور هو عين يشرب منها عباد الله، يتصرفون فيها، ويُجْرونها حيث شاؤوا إجراءً سهلا. هؤلاء كانوا في الدنيا يوفون بما أوجبوا على أنفسهم من طاعة الله، ويخافون عقاب الله في يوم القيامة الذي يكون ضرره خطيرًا، وشره فاشيًا منتشرًا على الناس، إلا مَن رحم الله، ويُطْعِمون الطعام مع حبهم له وحاجتهم إليه، فقيرًا عاجزًا عن الكسب لا يملك من حطام الدنيا شيئًا، وطفلا مات أبوه ولا مال له، وأسيرًا أُسر في الحرب من المشركين وغيرهم، ويقولون في أنفسهم: إنما نحسن إليكم ابتغاء مرضاة الله، وطلب ثوابه، لا نبتغي عوضًا ولا نقصد حمدًا ولا ثناءً منكم. إنا نخاف من ربنا يومًا شديدًا تَعْبِس فيه الوجوه، وتتقطَّبُ الجباه مِن فظاعة أمره وشدة هوله.", "isBasmala": false, "translation_en": "\"We only feed you for the sake of God. We want from you neither compensation, nor gratitude.", "translation_id": "Sesungguhnya kami memberi makanan kepadamu hanyalah untuk mengharapkan keridhaan Allah, kami tidak menghendaki balasan dari kamu dan tidak pula (ucapan) terima kasih.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 10, "text": "إِنَّا نَخَافُ مِن رَّبِّنَا یَوۡمًا عَبُوسࣰا قَمۡطَرِیرࣰا ۝١٠", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "هذا الشراب الذي مزج من الكافور هو عين يشرب منها عباد الله، يتصرفون فيها، ويُجْرونها حيث شاؤوا إجراءً سهلا. هؤلاء كانوا في الدنيا يوفون بما أوجبوا على أنفسهم من طاعة الله، ويخافون عقاب الله في يوم القيامة الذي يكون ضرره خطيرًا، وشره فاشيًا منتشرًا على الناس، إلا مَن رحم الله، ويُطْعِمون الطعام مع حبهم له وحاجتهم إليه، فقيرًا عاجزًا عن الكسب لا يملك من حطام الدنيا شيئًا، وطفلا مات أبوه ولا مال له، وأسيرًا أُسر في الحرب من المشركين وغيرهم، ويقولون في أنفسهم: إنما نحسن إليكم ابتغاء مرضاة الله، وطلب ثوابه، لا نبتغي عوضًا ولا نقصد حمدًا ولا ثناءً منكم. إنا نخاف من ربنا يومًا شديدًا تَعْبِس فيه الوجوه، وتتقطَّبُ الجباه مِن فظاعة أمره وشدة هوله.", "isBasmala": false, "translation_en": "We dread from our Lord a frowning grim Day.\"", "translation_id": "Sesungguhnya kami takut akan (azab) Tuhan kami pada suatu hari yang (di hari itu) orang-orang bermuka masam penuh kesulitan.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 11, "text": "فَوَقَىٰهُمُ ٱللَّهُ شَرَّ ذَ ٰلِكَ ٱلۡیَوۡمِ وَلَقَّىٰهُمۡ نَضۡرَةࣰ وَسُرُورࣰا ۝١١", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فوقاهم الله من شدائد ذلك اليوم، وأعطاهم حسنًا ونورًا في وجوههم، وبهجة وفرحًا في قلوبهم، وأثابهم بصبرهم في الدنيا على الطاعة جنة عظيمة يأكلون منها ما شاؤوا، ويَلْبَسون فيها الحرير الناعم، متكئين فيها على الأسرَّة المزينة بفاخر الثياب والستور، لا يرون فيها حر شمس ولا شدة برد، وقريبة منهم أشجار الجنة مظللة عليهم، وسُهِّل لهم أَخْذُ ثمارها تسهيلا.", "isBasmala": false, "translation_en": "So God will protect them from the ills of that Day, and will grant them radiance and joy.", "translation_id": "Maka Tuhan memelihara mereka dari kesusahan hari itu, dan memberikan kepada mereka kejernihan (wajah) dan kegembiraan hati.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 12, "text": "وَجَزَىٰهُم بِمَا صَبَرُوا۟ جَنَّةࣰ وَحَرِیرࣰا ۝١٢", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فوقاهم الله من شدائد ذلك اليوم، وأعطاهم حسنًا ونورًا في وجوههم، وبهجة وفرحًا في قلوبهم، وأثابهم بصبرهم في الدنيا على الطاعة جنة عظيمة يأكلون منها ما شاؤوا، ويَلْبَسون فيها الحرير الناعم، متكئين فيها على الأسرَّة المزينة بفاخر الثياب والستور، لا يرون فيها حر شمس ولا شدة برد، وقريبة منهم أشجار الجنة مظللة عليهم، وسُهِّل لهم أَخْذُ ثمارها تسهيلا.", "isBasmala": false, "translation_en": "And will reward them for their patience with a Garden and silk.", "translation_id": "Dan Dia memberi balasan kepada mereka karena kesabaran mereka (dengan) surga dan (pakaian) sutera,", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 13, "text": "مُّتَّكِـِٔینَ فِیهَا عَلَى ٱلۡأَرَاۤىِٕكِۖ لَا یَرَوۡنَ فِیهَا شَمۡسࣰا وَلَا زَمۡهَرِیرࣰا ۝١٣", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فوقاهم الله من شدائد ذلك اليوم، وأعطاهم حسنًا ونورًا في وجوههم، وبهجة وفرحًا في قلوبهم، وأثابهم بصبرهم في الدنيا على الطاعة جنة عظيمة يأكلون منها ما شاؤوا، ويَلْبَسون فيها الحرير الناعم، متكئين فيها على الأسرَّة المزينة بفاخر الثياب والستور، لا يرون فيها حر شمس ولا شدة برد، وقريبة منهم أشجار الجنة مظللة عليهم، وسُهِّل لهم أَخْذُ ثمارها تسهيلا.", "isBasmala": false, "translation_en": "Reclining therein on the thrones; experiencing therein neither sun, nor frost.", "translation_id": "di dalamnya mereka duduk bertelakan di atas dipan, mereka tidak merasakan di dalamnya (teriknya) matahari dan tidak pula dingin yang bersangatan.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 14, "text": "وَدَانِیَةً عَلَیۡهِمۡ ظِلَـٰلُهَا وَذُلِّلَتۡ قُطُوفُهَا تَذۡلِیلࣰا ۝١٤", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "فوقاهم الله من شدائد ذلك اليوم، وأعطاهم حسنًا ونورًا في وجوههم، وبهجة وفرحًا في قلوبهم، وأثابهم بصبرهم في الدنيا على الطاعة جنة عظيمة يأكلون منها ما شاؤوا، ويَلْبَسون فيها الحرير الناعم، متكئين فيها على الأسرَّة المزينة بفاخر الثياب والستور، لا يرون فيها حر شمس ولا شدة برد، وقريبة منهم أشجار الجنة مظللة عليهم، وسُهِّل لهم أَخْذُ ثمارها تسهيلا.", "isBasmala": false, "translation_en": "Its shade hovering over them, and its fruit brought low within reach.", "translation_id": "Dan naungan (pohon-pohon surga itu) dekat di atas mereka dan buahnya dimudahkan memetiknya semudah-mudahnya.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 15, "text": "وَیُطَافُ عَلَیۡهِم بِـَٔانِیَةࣲ مِّن فِضَّةࣲ وَأَكۡوَابࣲ كَانَتۡ قَوَارِیرَا۠ ۝١٥", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ويدور عليهم الخدم بأواني الطعام الفضيَّة، وأكواب الشراب من الزجاج، زجاج من فضة، قدَّرها السقاة على مقدار ما يشتهي الشاربون لا تزيد ولا تنقص، ويُسْقَى هؤلاء الأبرار في الجنة كأسًا مملوءة خمرًا مزجت بالزنجبيل، يشربون مِن عينٍ في الجنة تسمى سلسبيلا؛ لسلامة شرابها وسهولة مساغه وطيبه.", "isBasmala": false, "translation_en": "Passing around them are vessels of silver, and cups of crystal.", "translation_id": "Dan diedarkan kepada mereka bejana-bejana dari perak dan piala-piala yang bening laksana kaca,", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 16, "text": "قَوَارِیرَا۟ مِن فِضَّةࣲ قَدَّرُوهَا تَقۡدِیرࣰا ۝١٦", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ويدور عليهم الخدم بأواني الطعام الفضيَّة، وأكواب الشراب من الزجاج، زجاج من فضة، قدَّرها السقاة على مقدار ما يشتهي الشاربون لا تزيد ولا تنقص، ويُسْقَى هؤلاء الأبرار في الجنة كأسًا مملوءة خمرًا مزجت بالزنجبيل، يشربون مِن عينٍ في الجنة تسمى سلسبيلا؛ لسلامة شرابها وسهولة مساغه وطيبه.", "isBasmala": false, "translation_en": "Crystal of silver-they measured them exactly.", "translation_id": "(yaitu) kaca-kaca (yang terbuat) dari perak yang telah diukur mereka dengan sebaik-baiknya.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 17, "text": "وَیُسۡقَوۡنَ فِیهَا كَأۡسࣰا كَانَ مِزَاجُهَا زَنجَبِیلًا ۝١٧", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ويدور عليهم الخدم بأواني الطعام الفضيَّة، وأكواب الشراب من الزجاج، زجاج من فضة، قدَّرها السقاة على مقدار ما يشتهي الشاربون لا تزيد ولا تنقص، ويُسْقَى هؤلاء الأبرار في الجنة كأسًا مملوءة خمرًا مزجت بالزنجبيل، يشربون مِن عينٍ في الجنة تسمى سلسبيلا؛ لسلامة شرابها وسهولة مساغه وطيبه.", "isBasmala": false, "translation_en": "They will be served therein with a cup whose flavor is Zanjabeel.", "translation_id": "Di dalam surga itu mereka diberi minum segelas (minuman) yang campurannya adalah jahe.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 18, "text": "عَیۡنࣰا فِیهَا تُسَمَّىٰ سَلۡسَبِیلࣰا ۝١٨", "juz": 29, "hizb": "(*½ ح 58*)", "tafsir": "ويدور عليهم الخدم بأواني الطعام الفضيَّة، وأكواب الشراب من الزجاج، زجاج من فضة، قدَّرها السقاة على مقدار ما يشتهي الشاربون لا تزيد ولا تنقص، ويُسْقَى هؤلاء الأبرار في الجنة كأسًا مملوءة خمرًا مزجت بالزنجبيل، يشربون مِن عينٍ في الجنة تسمى سلسبيلا؛ لسلامة شرابها وسهولة مساغه وطيبه.", "isBasmala": false, "translation_en": "A spring therein named Salsabeel.", "translation_id": "(Yang didatangkan dari) sebuah mata air surga yang dinamakan salsabil.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 19, "text": "۞ وَیَطُوفُ عَلَیۡهِمۡ وِلۡدَ ٰنࣱ مُّخَلَّدُونَ إِذَا رَأَیۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤࣰا مَّنثُورࣰا ۝١٩", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ويدور على هؤلاء الأبرار لخدمتهم غلمان دائمون على حالهم، إذا أبصرتهم ظننتهم- لحسنهم وصفاء ألوانهم وإشراق وجوههم- اللؤلؤ المفرَّق المضيء.", "isBasmala": false, "translation_en": "Passing among them are eternalized youths. If you see them, you would think them sprinkled pearls.", "translation_id": "Dan mereka dikelilingi oleh pelayan-pelayan muda yang tetap muda. Apabila kamu melihat mereka, kamu akan mengira mereka, mutiara yang bertaburan.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 20, "text": "وَإِذَا رَأَیۡتَ ثَمَّ رَأَیۡتَ نَعِیمࣰا وَمُلۡكࣰا كَبِیرًا ۝٢٠", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "وإذا أبصرت أيَّ مكان في الجنة رأيت فيه نعيمًا لا يُدْركه الوصف، ومُلْكا عظيمًا واسعًا لا غاية له.", "isBasmala": false, "translation_en": "Wherever you look, you see bliss, and a vast kingdom.", "translation_id": "Dan apabila kamu melihat di sana (surga), niscaya kamu akan melihat berbagai macam kenikmatan dan kerajaan yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 21, "text": "عَـٰلِیَهُمۡ ثِیَابُ سُندُسٍ خُضۡرࣱ وَإِسۡتَبۡرَقࣱۖ وَحُلُّوۤا۟ أَسَاوِرَ مِن فِضَّةࣲ وَسَقَىٰهُمۡ رَبُّهُمۡ شَرَابࣰا طَهُورًا ۝٢١", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "يعلوهم ويجمل أبدانهم ثياب بطائنها من الحرير الرقيق الأخضر، وظاهرها من الحرير الغليظ، ويُحَلَّون من الحليِّ بأساور من الفضة، وسقاهم ربهم فوق ذلك النعيم شرابًا لا رجس فيه ولا دنس.", "isBasmala": false, "translation_en": "Upon them are garments of green silk, and satin. And they will be adorned with bracelets of silver. And their Lord will offer them a pure drink.", "translation_id": "Mereka memakai pakaian sutera halus yang hijau dan sutera tebal dan dipakaikan kepada mereka gelang terbuat dari perak, dan Tuhan memberikan kepada mereka minuman yang bersih.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 22, "text": "إِنَّ هَـٰذَا كَانَ لَكُمۡ جَزَاۤءࣰ وَكَانَ سَعۡیُكُم مَّشۡكُورًا ۝٢٢", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ويقال لهم: إن هذا أُعِدَّ لكم مقابل أعمالكم الصالحة، وكان عملكم في الدنيا عند الله مرضيًا مقبولا.", "isBasmala": false, "translation_en": "\"This is a reward for you. Your efforts are well appreciated.\"", "translation_id": "Sesungguhnya ini adalah balasan untukmu, dan usahamu adalah disyukuri (diberi balasan).", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 23, "text": "إِنَّا نَحۡنُ نَزَّلۡنَا عَلَیۡكَ ٱلۡقُرۡءَانَ تَنزِیلࣰا ۝٢٣", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إنا نحن نَزَّلْنا عليك -أيها الرسول- القرآن تنزيلا من عندنا؛ لتذكر الناس بما فيه من الوعد والوعيد والثواب والعقاب.", "isBasmala": false, "translation_en": "It is We who sent down the Quran upon you-a gradual revelation.", "translation_id": "Sesungguhnya Kami telah menurunkan Al Quran kepadamu (hai Muhammad) dengan berangsur-angsur.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 24, "text": "فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورࣰا ۝٢٤", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فاصبر لحكم ربك القدري واقبله، ولحكمه الديني فامض عليه، ولا تطع من المشركين من كان منغمسًا في الشهوات أو مبالغًا في الكفر والضلال، وداوم على ذكر اسم ربك ودعائه في أول النهار وآخره.", "isBasmala": false, "translation_en": "So be patient for the decision of your Lord, and do not obey the sinner or the blasphemer among them.", "translation_id": "Maka bersabarlah kamu untuk (melaksanakan) ketetapan Tuhanmu, dan janganlah kamu ikuti orang yang berdosa dan orang yang kafir di antar mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 25, "text": "وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةࣰ وَأَصِیلࣰا ۝٢٥", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فاصبر لحكم ربك القدري واقبله، ولحكمه الديني فامض عليه، ولا تطع من المشركين من كان منغمسًا في الشهوات أو مبالغًا في الكفر والضلال، وداوم على ذكر اسم ربك ودعائه في أول النهار وآخره.", "isBasmala": false, "translation_en": "And mention the Name of your Lord, morning and evening.", "translation_id": "Dan sebutlah nama Tuhanmu pada (waktu) pagi dan petang.", "manzil": 7, "manzil_display": ""}], "580": [{"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 26, "text": "وَمِنَ ٱلَّیۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَیۡلࣰا طَوِیلًا ۝٢٦", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ومن الليل فاخضع لربك، وصَلِّ له، وتهجَّد له زمنًا طويلا فيه.", "isBasmala": false, "translation_en": "And for part of the night, prostrate yourself to Him, and glorify Him long into the night.", "translation_id": "Dan pada sebagian dari malam, maka sujudlah kepada-Nya dan bertasbihlah kepada-Nya pada bagian yang panjang dimalam hari.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 27, "text": "إِنَّ هَـٰۤؤُلَاۤءِ یُحِبُّونَ ٱلۡعَاجِلَةَ وَیَذَرُونَ وَرَاۤءَهُمۡ یَوۡمࣰا ثَقِیلࣰا ۝٢٧", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إن هؤلاء المشركين يحبون الدنيا، وينشغلون بها، ويتركون خلف ظهورهم العمل للآخرة، ولما فيه نجاتهم في يوم عظيم الشدائد.", "isBasmala": false, "translation_en": "As for these: they love the fleeting life, and leave behind a Heavy Day.", "translation_id": "Sesungguhnya mereka (orang kafir) menyukai kehidupan dunia dan mereka tidak memperdulikan kesudahan mereka, pada hari yang berat (hari akhirat).", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 28, "text": "نَّحۡنُ خَلَقۡنَـٰهُمۡ وَشَدَدۡنَاۤ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَاۤ أَمۡثَـٰلَهُمۡ تَبۡدِیلًا ۝٢٨", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "نحن خلقناهم، وأحكمنا خلقهم، وإذا شئنا أهلكناهم، وجئنا بقوم مطيعين ممتثلين لأوامر ربهم.", "isBasmala": false, "translation_en": "We created them, and strengthened their frame; and whenever We will, We can replace them with others like them.", "translation_id": "Kami telah menciptakan mereka dan menguatkan persendian tubuh mereka, apabila Kami menghendaki, Kami sungguh-sungguh mengganti (mereka) dengan orang-orang yang serupa dengan mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 29, "text": "إِنَّ هَـٰذِهِۦ تَذۡكِرَةࣱۖ فَمَن شَاۤءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِیلࣰا ۝٢٩", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إن هذه السورة عظة للعالمين، فمن أراد الخير لنفسه في الدنيا والآخرة اتخذ بالإيمان والتقوى طريقًا يوصله إلى مغفرة الله ورضوانه. وما تريدون أمرًا من الأمور إلا بتقدير الله ومشيئته. إن الله كان عليمًا بأحوال خلقه، حكيمًا في تدبيره وصنعه. يُدْخل مَن يشاء مِن عباده في رحمته ورضوانه، وهم المؤمنون، وأعدَّ للظالمين المتجاوزين حدود الله عذابًا موجعًا.", "isBasmala": false, "translation_en": "This is a reminder; so whoever wills, let him take a path to his Lord.", "translation_id": "Sesungguhnya (ayat-ayat) ini adalah suatu peringatan, maka barangsiapa menghendaki (kebaikan bagi dirinya) niscaya dia mengambil jalan kepada Tuhannya.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 30, "text": "وَمَا تَشَاۤءُونَ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا ۝٣٠", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إن هذه السورة عظة للعالمين، فمن أراد الخير لنفسه في الدنيا والآخرة اتخذ بالإيمان والتقوى طريقًا يوصله إلى مغفرة الله ورضوانه. وما تريدون أمرًا من الأمور إلا بتقدير الله ومشيئته. إن الله كان عليمًا بأحوال خلقه، حكيمًا في تدبيره وصنعه. يُدْخل مَن يشاء مِن عباده في رحمته ورضوانه، وهم المؤمنون، وأعدَّ للظالمين المتجاوزين حدود الله عذابًا موجعًا.", "isBasmala": false, "translation_en": "Yet you cannot will, unless God wills. God is Knowing and Wise.", "translation_id": "Dan kamu tidak mampu (menempuh jalan itu), kecuali bila dikehendaki Allah. Sesungguhnya Allah adalah Maha Mengetahui lagi Maha Bijaksana.", "manzil": 7, "manzil_display": ""}, {"sura": 76, "sura_name": "الإنسان", "revelation": "Madaniyah", "aya": 31, "text": "یُدۡخِلُ مَن یَشَاۤءُ فِی رَحۡمَتِهِۦۚ وَٱلظَّـٰلِمِینَ أَعَدَّ لَهُمۡ عَذَابًا أَلِیمَۢا ۝٣١", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إن هذه السورة عظة للعالمين، فمن أراد الخير لنفسه في الدنيا والآخرة اتخذ بالإيمان والتقوى طريقًا يوصله إلى مغفرة الله ورضوانه. وما تريدون أمرًا من الأمور إلا بتقدير الله ومشيئته. إن الله كان عليمًا بأحوال خلقه، حكيمًا في تدبيره وصنعه. يُدْخل مَن يشاء مِن عباده في رحمته ورضوانه، وهم المؤمنون، وأعدَّ للظالمين المتجاوزين حدود الله عذابًا موجعًا.", "isBasmala": false, "translation_en": "He admits into His mercy whomever He wills. But as for the wrongdoers, He has prepared for them a painful punishment.", "translation_id": "Dan memasukkan siapa yang dikehendaki-Nya ke dalam rahmat-Nya (surga). Dan bagi orang-orang zalim disediakan-Nya azab yang pedih.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 29, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلۡمُرۡسَلَـٰتِ عُرۡفࣰا ۝١", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "أقسم الله تعالى بالرياح حين تهب متتابعة يقفو بعضها بعضًا، وبالرياح الشديدة الهبوب المهلكة، وبالملائكة الموكلين بالسحب يسوقونها حيث شاء الله، وبالملائكة التي تنزل من عند الله بما يفرق بين الحق والباطل والحلال والحرام، وبالملائكة التي تتلقى الوحي من عند الله وتنزل به على أنبيائه؛ إعذارًا من الله إلى خلقه وإنذارًا منه إليهم؛ لئلا يكون لهم حجة. إن الذي توعدون به مِن أمر يوم القيامة وما فيه من حساب وجزاء لنازلٌ بكم لا محالة.", "isBasmala": false, "translation_en": "By those unleashed in succession.", "translation_id": "Demi malaikat-malaikat yang diutus untuk membawa kebaikan,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 2, "text": "فَٱلۡعَـٰصِفَـٰتِ عَصۡفࣰا ۝٢", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "أقسم الله تعالى بالرياح حين تهب متتابعة يقفو بعضها بعضًا، وبالرياح الشديدة الهبوب المهلكة، وبالملائكة الموكلين بالسحب يسوقونها حيث شاء الله، وبالملائكة التي تنزل من عند الله بما يفرق بين الحق والباطل والحلال والحرام، وبالملائكة التي تتلقى الوحي من عند الله وتنزل به على أنبيائه؛ إعذارًا من الله إلى خلقه وإنذارًا منه إليهم؛ لئلا يكون لهم حجة. إن الذي توعدون به مِن أمر يوم القيامة وما فيه من حساب وجزاء لنازلٌ بكم لا محالة.", "isBasmala": false, "translation_en": "Storming turbulently.", "translation_id": "dan (malaikat-malaikat) yang terbang dengan kencangnya,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 3, "text": "وَٱلنَّـٰشِرَ ٰتِ نَشۡرࣰا ۝٣", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "أقسم الله تعالى بالرياح حين تهب متتابعة يقفو بعضها بعضًا، وبالرياح الشديدة الهبوب المهلكة، وبالملائكة الموكلين بالسحب يسوقونها حيث شاء الله، وبالملائكة التي تنزل من عند الله بما يفرق بين الحق والباطل والحلال والحرام، وبالملائكة التي تتلقى الوحي من عند الله وتنزل به على أنبيائه؛ إعذارًا من الله إلى خلقه وإنذارًا منه إليهم؛ لئلا يكون لهم حجة. إن الذي توعدون به مِن أمر يوم القيامة وما فيه من حساب وجزاء لنازلٌ بكم لا محالة.", "isBasmala": false, "translation_en": "Scattering far and wide.", "translation_id": "dan (malaikat-malaikat) yang menyebarkan (rahmat Tuhannya) dengan seluas-luasnya,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 4, "text": "فَٱلۡفَـٰرِقَـٰتِ فَرۡقࣰا ۝٤", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "أقسم الله تعالى بالرياح حين تهب متتابعة يقفو بعضها بعضًا، وبالرياح الشديدة الهبوب المهلكة، وبالملائكة الموكلين بالسحب يسوقونها حيث شاء الله، وبالملائكة التي تنزل من عند الله بما يفرق بين الحق والباطل والحلال والحرام، وبالملائكة التي تتلقى الوحي من عند الله وتنزل به على أنبيائه؛ إعذارًا من الله إلى خلقه وإنذارًا منه إليهم؛ لئلا يكون لهم حجة. إن الذي توعدون به مِن أمر يوم القيامة وما فيه من حساب وجزاء لنازلٌ بكم لا محالة.", "isBasmala": false, "translation_en": "Separating decisively.", "translation_id": "dan (malaikat-malaikat) yang membedakan (antara yang hak dan yang bathil) dengan sejelas-jelasnya,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 5, "text": "فَٱلۡمُلۡقِیَـٰتِ ذِكۡرًا ۝٥", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "أقسم الله تعالى بالرياح حين تهب متتابعة يقفو بعضها بعضًا، وبالرياح الشديدة الهبوب المهلكة، وبالملائكة الموكلين بالسحب يسوقونها حيث شاء الله، وبالملائكة التي تنزل من عند الله بما يفرق بين الحق والباطل والحلال والحرام، وبالملائكة التي تتلقى الوحي من عند الله وتنزل به على أنبيائه؛ إعذارًا من الله إلى خلقه وإنذارًا منه إليهم؛ لئلا يكون لهم حجة. إن الذي توعدون به مِن أمر يوم القيامة وما فيه من حساب وجزاء لنازلٌ بكم لا محالة.", "isBasmala": false, "translation_en": "Delivering a message.", "translation_id": "dan (malaikat-malaikat) yang menyampaikan wahyu,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 6, "text": "عُذۡرًا أَوۡ نُذۡرًا ۝٦", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "أقسم الله تعالى بالرياح حين تهب متتابعة يقفو بعضها بعضًا، وبالرياح الشديدة الهبوب المهلكة، وبالملائكة الموكلين بالسحب يسوقونها حيث شاء الله، وبالملائكة التي تنزل من عند الله بما يفرق بين الحق والباطل والحلال والحرام، وبالملائكة التي تتلقى الوحي من عند الله وتنزل به على أنبيائه؛ إعذارًا من الله إلى خلقه وإنذارًا منه إليهم؛ لئلا يكون لهم حجة. إن الذي توعدون به مِن أمر يوم القيامة وما فيه من حساب وجزاء لنازلٌ بكم لا محالة.", "isBasmala": false, "translation_en": "Excusing or warning.", "translation_id": "untuk menolak alasan-alasan atau memberi peringatan,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 7, "text": "إِنَّمَا تُوعَدُونَ لَوَ ٰقِعࣱ ۝٧", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "أقسم الله تعالى بالرياح حين تهب متتابعة يقفو بعضها بعضًا، وبالرياح الشديدة الهبوب المهلكة، وبالملائكة الموكلين بالسحب يسوقونها حيث شاء الله، وبالملائكة التي تنزل من عند الله بما يفرق بين الحق والباطل والحلال والحرام، وبالملائكة التي تتلقى الوحي من عند الله وتنزل به على أنبيائه؛ إعذارًا من الله إلى خلقه وإنذارًا منه إليهم؛ لئلا يكون لهم حجة. إن الذي توعدون به مِن أمر يوم القيامة وما فيه من حساب وجزاء لنازلٌ بكم لا محالة.", "isBasmala": false, "translation_en": "Surely what you are promised will happen.", "translation_id": "sesungguhnya apa yang dijanjikan kepadamu itu pasti terjadi.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 8, "text": "فَإِذَا ٱلنُّجُومُ طُمِسَتۡ ۝٨", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فإذا النجوم طُمست وذهب ضياؤها، وإذا السماء تصدَّعت، وإذا الجبال تطايرت وتناثرت وصارت هباء تَذْروه الرياح، وإذا الرسل عُيِّن لهم وقت وأجل للفصل بينهم وبين الأمم، يقال: لأيِّ يوم عظيم أخِّرت الرسل؟ أخِّرت ليوم القضاء والفصل بين الخلائق. وما أعلمك -أيها الإنسان- أيُّ شيء هو يوم الفصل وشدته وهوله؟ هلاك عظيم في ذلك اليوم للمكذبين بهذا اليوم الموعود.", "isBasmala": false, "translation_en": "When the stars are obliterated.", "translation_id": "Maka apabila bintang-bintang telah dihapuskan,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 9, "text": "وَإِذَا ٱلسَّمَاۤءُ فُرِجَتۡ ۝٩", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فإذا النجوم طُمست وذهب ضياؤها، وإذا السماء تصدَّعت، وإذا الجبال تطايرت وتناثرت وصارت هباء تَذْروه الرياح، وإذا الرسل عُيِّن لهم وقت وأجل للفصل بينهم وبين الأمم، يقال: لأيِّ يوم عظيم أخِّرت الرسل؟ أخِّرت ليوم القضاء والفصل بين الخلائق. وما أعلمك -أيها الإنسان- أيُّ شيء هو يوم الفصل وشدته وهوله؟ هلاك عظيم في ذلك اليوم للمكذبين بهذا اليوم الموعود.", "isBasmala": false, "translation_en": "And the sky is fractured.", "translation_id": "dan apabila langit telah dibelah,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 10, "text": "وَإِذَا ٱلۡجِبَالُ نُسِفَتۡ ۝١٠", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فإذا النجوم طُمست وذهب ضياؤها، وإذا السماء تصدَّعت، وإذا الجبال تطايرت وتناثرت وصارت هباء تَذْروه الرياح، وإذا الرسل عُيِّن لهم وقت وأجل للفصل بينهم وبين الأمم، يقال: لأيِّ يوم عظيم أخِّرت الرسل؟ أخِّرت ليوم القضاء والفصل بين الخلائق. وما أعلمك -أيها الإنسان- أيُّ شيء هو يوم الفصل وشدته وهوله؟ هلاك عظيم في ذلك اليوم للمكذبين بهذا اليوم الموعود.", "isBasmala": false, "translation_en": "And the mountains are blown away.", "translation_id": "dan apabila gunung-gunung telah dihancurkan menjadi debu,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 11, "text": "وَإِذَا ٱلرُّسُلُ أُقِّتَتۡ ۝١١", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فإذا النجوم طُمست وذهب ضياؤها، وإذا السماء تصدَّعت، وإذا الجبال تطايرت وتناثرت وصارت هباء تَذْروه الرياح، وإذا الرسل عُيِّن لهم وقت وأجل للفصل بينهم وبين الأمم، يقال: لأيِّ يوم عظيم أخِّرت الرسل؟ أخِّرت ليوم القضاء والفصل بين الخلائق. وما أعلمك -أيها الإنسان- أيُّ شيء هو يوم الفصل وشدته وهوله؟ هلاك عظيم في ذلك اليوم للمكذبين بهذا اليوم الموعود.", "isBasmala": false, "translation_en": "And the messengers are alerted.", "translation_id": "dan apabila rasul-rasul telah ditetapkan waktu (mereka).", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 12, "text": "لِأَیِّ یَوۡمٍ أُجِّلَتۡ ۝١٢", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فإذا النجوم طُمست وذهب ضياؤها، وإذا السماء تصدَّعت، وإذا الجبال تطايرت وتناثرت وصارت هباء تَذْروه الرياح، وإذا الرسل عُيِّن لهم وقت وأجل للفصل بينهم وبين الأمم، يقال: لأيِّ يوم عظيم أخِّرت الرسل؟ أخِّرت ليوم القضاء والفصل بين الخلائق. وما أعلمك -أيها الإنسان- أيُّ شيء هو يوم الفصل وشدته وهوله؟ هلاك عظيم في ذلك اليوم للمكذبين بهذا اليوم الموعود.", "isBasmala": false, "translation_en": "Until which day is it deferred?", "translation_id": "(Niscaya dikatakan kepada mereka:) \"Sampai hari apakah ditangguhkan (mengazab orang-orang kafir itu)?\"", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 13, "text": "لِیَوۡمِ ٱلۡفَصۡلِ ۝١٣", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فإذا النجوم طُمست وذهب ضياؤها، وإذا السماء تصدَّعت، وإذا الجبال تطايرت وتناثرت وصارت هباء تَذْروه الرياح، وإذا الرسل عُيِّن لهم وقت وأجل للفصل بينهم وبين الأمم، يقال: لأيِّ يوم عظيم أخِّرت الرسل؟ أخِّرت ليوم القضاء والفصل بين الخلائق. وما أعلمك -أيها الإنسان- أيُّ شيء هو يوم الفصل وشدته وهوله؟ هلاك عظيم في ذلك اليوم للمكذبين بهذا اليوم الموعود.", "isBasmala": false, "translation_en": "Until the Day of Decision.", "translation_id": "Sampai hari keputusan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 14, "text": "وَمَاۤ أَدۡرَىٰكَ مَا یَوۡمُ ٱلۡفَصۡلِ ۝١٤", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فإذا النجوم طُمست وذهب ضياؤها، وإذا السماء تصدَّعت، وإذا الجبال تطايرت وتناثرت وصارت هباء تَذْروه الرياح، وإذا الرسل عُيِّن لهم وقت وأجل للفصل بينهم وبين الأمم، يقال: لأيِّ يوم عظيم أخِّرت الرسل؟ أخِّرت ليوم القضاء والفصل بين الخلائق. وما أعلمك -أيها الإنسان- أيُّ شيء هو يوم الفصل وشدته وهوله؟ هلاك عظيم في ذلك اليوم للمكذبين بهذا اليوم الموعود.", "isBasmala": false, "translation_en": "And what will teach you what the Day of Decision is?", "translation_id": "Dan tahukah kamu apakah hari keputusan itu?", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 15, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝١٥", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "فإذا النجوم طُمست وذهب ضياؤها، وإذا السماء تصدَّعت، وإذا الجبال تطايرت وتناثرت وصارت هباء تَذْروه الرياح، وإذا الرسل عُيِّن لهم وقت وأجل للفصل بينهم وبين الأمم، يقال: لأيِّ يوم عظيم أخِّرت الرسل؟ أخِّرت ليوم القضاء والفصل بين الخلائق. وما أعلمك -أيها الإنسان- أيُّ شيء هو يوم الفصل وشدته وهوله؟ هلاك عظيم في ذلك اليوم للمكذبين بهذا اليوم الموعود.", "isBasmala": false, "translation_en": "Woe on that Day to the liars.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 16, "text": "أَلَمۡ نُهۡلِكِ ٱلۡأَوَّلِینَ ۝١٦", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نهلك السابقين من الأمم الماضية؛ بتكذيبهم للرسل كقوم نوح وعاد وثمود؟ ثم نلحق بهم المتأخرين ممن كانوا مثلهم في التكذيب والعصيان. مِثل ذلك الإهلاك الفظيع نفعل بهؤلاء المجرمين من كفار \"مكة\"؛ لتكذيبهم الرسول صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Did We not destroy the ancients?", "translation_id": "Bukankah Kami telah membinasakan orang-orang yang dahulu?", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 17, "text": "ثُمَّ نُتۡبِعُهُمُ ٱلۡـَٔاخِرِینَ ۝١٧", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نهلك السابقين من الأمم الماضية؛ بتكذيبهم للرسل كقوم نوح وعاد وثمود؟ ثم نلحق بهم المتأخرين ممن كانوا مثلهم في التكذيب والعصيان. مِثل ذلك الإهلاك الفظيع نفعل بهؤلاء المجرمين من كفار \"مكة\"؛ لتكذيبهم الرسول صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "Then succeeded them with the others?", "translation_id": "Lalu Kami iringkan (azab Kami terhadap) mereka dengan (mengazab) orang-orang yang datang kemudian.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 18, "text": "كَذَ ٰلِكَ نَفۡعَلُ بِٱلۡمُجۡرِمِینَ ۝١٨", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نهلك السابقين من الأمم الماضية؛ بتكذيبهم للرسل كقوم نوح وعاد وثمود؟ ثم نلحق بهم المتأخرين ممن كانوا مثلهم في التكذيب والعصيان. مِثل ذلك الإهلاك الفظيع نفعل بهؤلاء المجرمين من كفار \"مكة\"؛ لتكذيبهم الرسول صلى الله عليه وسلم.", "isBasmala": false, "translation_en": "This is how We deal with the guilty.", "translation_id": "Demikianlah Kami berbuat terhadap orang-orang yang berdosa.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 19, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝١٩", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هلاك وعذاب شديد يوم القيامة لكل مكذِّب بأن الله هو الإله الحق وحده لا شريك له، والنبوةِ والبعث والحساب.", "isBasmala": false, "translation_en": "Woe on that Day to the rejecters.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}], "581": [{"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 20, "text": "أَلَمۡ نَخۡلُقكُّم مِّن مَّاۤءࣲ مَّهِینࣲ ۝٢٠", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نخلقكم- يا معشر الكفار- من ماء ضعيف حقير وهو النطفة، فجعلنا هذا الماء في مكان حصين، وهو رحم المرأة، إلى وقت محدود ومعلوم عند الله تعالى؟ فقدرنا على خلقه وتصويره وإخراجه، فنعم القادرون نحن.", "isBasmala": false, "translation_en": "Did We not create you from an insignificant fluid?", "translation_id": "Bukankah Kami menciptakan kamu dari air yang hina?", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 21, "text": "فَجَعَلۡنَـٰهُ فِی قَرَارࣲ مَّكِینٍ ۝٢١", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نخلقكم- يا معشر الكفار- من ماء ضعيف حقير وهو النطفة، فجعلنا هذا الماء في مكان حصين، وهو رحم المرأة، إلى وقت محدود ومعلوم عند الله تعالى؟ فقدرنا على خلقه وتصويره وإخراجه، فنعم القادرون نحن.", "isBasmala": false, "translation_en": "Then lodged it in a secure place?", "translation_id": "kemudian Kami letakkan dia dalam tempat yang kokoh (rahim),", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 22, "text": "إِلَىٰ قَدَرࣲ مَّعۡلُومࣲ ۝٢٢", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نخلقكم- يا معشر الكفار- من ماء ضعيف حقير وهو النطفة، فجعلنا هذا الماء في مكان حصين، وهو رحم المرأة، إلى وقت محدود ومعلوم عند الله تعالى؟ فقدرنا على خلقه وتصويره وإخراجه، فنعم القادرون نحن.", "isBasmala": false, "translation_en": "For a known term?", "translation_id": "sampai waktu yang ditentukan,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 23, "text": "فَقَدَرۡنَا فَنِعۡمَ ٱلۡقَـٰدِرُونَ ۝٢٣", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نخلقكم- يا معشر الكفار- من ماء ضعيف حقير وهو النطفة، فجعلنا هذا الماء في مكان حصين، وهو رحم المرأة، إلى وقت محدود ومعلوم عند الله تعالى؟ فقدرنا على خلقه وتصويره وإخراجه، فنعم القادرون نحن.", "isBasmala": false, "translation_en": "We measured precisely. We are the best to measure.", "translation_id": "lalu Kami tentukan (bentuknya), maka Kami-lah sebaik-baik yang menentukan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 24, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝٢٤", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هلاك وعذاب شديد يوم القيامة للمكذبين بقدرتنا.", "isBasmala": false, "translation_en": "Woe on that Day to the falsifiers.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 25, "text": "أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ كِفَاتًا ۝٢٥", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نجعل هذه الأرض التي تعيشون عليها، تضم على ظهرها أحياء لا يحصون، وفي بطنها أمواتًا لا يحصرون، وجعلنا فيها جبالا ثوابت عاليات؛ لئلا تضطرب بكم، وأسقيناكم ماءً عذبًا سائغًا؟", "isBasmala": false, "translation_en": "Did We not make the earth a homestead?", "translation_id": "Bukankah Kami menjadikan bumi (tempat) berkumpul,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 26, "text": "أَحۡیَاۤءࣰ وَأَمۡوَ ٰتࣰا ۝٢٦", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نجعل هذه الأرض التي تعيشون عليها، تضم على ظهرها أحياء لا يحصون، وفي بطنها أمواتًا لا يحصرون، وجعلنا فيها جبالا ثوابت عاليات؛ لئلا تضطرب بكم، وأسقيناكم ماءً عذبًا سائغًا؟", "isBasmala": false, "translation_en": "For the living and the dead?", "translation_id": "orang-orang hidup dan orang-orang mati?", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 27, "text": "وَجَعَلۡنَا فِیهَا رَوَ ٰسِیَ شَـٰمِخَـٰتࣲ وَأَسۡقَیۡنَـٰكُم مَّاۤءࣰ فُرَاتࣰا ۝٢٧", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ألم نجعل هذه الأرض التي تعيشون عليها، تضم على ظهرها أحياء لا يحصون، وفي بطنها أمواتًا لا يحصرون، وجعلنا فيها جبالا ثوابت عاليات؛ لئلا تضطرب بكم، وأسقيناكم ماءً عذبًا سائغًا؟", "isBasmala": false, "translation_en": "And set on it lofty mountains, and given you pure water to drink?", "translation_id": "dan Kami jadikan padanya gunung-gunung yang tinggi, dan Kami beri minum kamu dengan air tawar?", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 28, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝٢٨", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هلاك ودمار يوم القيامة للمكذبين بهذه النعم.", "isBasmala": false, "translation_en": "Woe on that Day to the deniers.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 29, "text": "ٱنطَلِقُوۤا۟ إِلَىٰ مَا كُنتُم بِهِۦ تُكَذِّبُونَ ۝٢٩", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "يقال للكافرين يوم القيامة: سيروا إلى عذاب جهنم الذي كنتم به تكذبون في الدنيا، سيروا، فاستظلوا بدخان جهنم يتفرع منه ثلاث قطع، لا يُظِل ذلك الظل من حر ذلك اليوم، ولا يدفع من حر اللهب شيئًا. إن جهنم تقذف من النار بشرر عظيم، كل شرارة منه كالبناء المشيد في العِظم والارتفاع. كأن شرر جهنم المتطاير منها إبل سود يميل لونها إلى الصُّفْرة.", "isBasmala": false, "translation_en": "\"Proceed to what you used to deny.\"", "translation_id": "(Dikatakan kepada mereka pada hari kiamat): \"Pergilah kamu mendapatkan azab yang dahulunya kamu mendustakannya.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 30, "text": "ٱنطَلِقُوۤا۟ إِلَىٰ ظِلࣲّ ذِی ثَلَـٰثِ شُعَبࣲ ۝٣٠", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "يقال للكافرين يوم القيامة: سيروا إلى عذاب جهنم الذي كنتم به تكذبون في الدنيا، سيروا، فاستظلوا بدخان جهنم يتفرع منه ثلاث قطع، لا يُظِل ذلك الظل من حر ذلك اليوم، ولا يدفع من حر اللهب شيئًا. إن جهنم تقذف من النار بشرر عظيم، كل شرارة منه كالبناء المشيد في العِظم والارتفاع. كأن شرر جهنم المتطاير منها إبل سود يميل لونها إلى الصُّفْرة.", "isBasmala": false, "translation_en": "\"Proceed to a shadow of three different masses.\"", "translation_id": "Pergilah kamu mendapatkan naungan yang mempunyai tiga cabang,", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 31, "text": "لَّا ظَلِیلࣲ وَلَا یُغۡنِی مِنَ ٱللَّهَبِ ۝٣١", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "يقال للكافرين يوم القيامة: سيروا إلى عذاب جهنم الذي كنتم به تكذبون في الدنيا، سيروا، فاستظلوا بدخان جهنم يتفرع منه ثلاث قطع، لا يُظِل ذلك الظل من حر ذلك اليوم، ولا يدفع من حر اللهب شيئًا. إن جهنم تقذف من النار بشرر عظيم، كل شرارة منه كالبناء المشيد في العِظم والارتفاع. كأن شرر جهنم المتطاير منها إبل سود يميل لونها إلى الصُّفْرة.", "isBasmala": false, "translation_en": "Offering no shade, and unavailing against the flames.", "translation_id": "yang tidak melindungi dan tidak pula menolak nyala api neraka\".", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 32, "text": "إِنَّهَا تَرۡمِی بِشَرَرࣲ كَٱلۡقَصۡرِ ۝٣٢", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "يقال للكافرين يوم القيامة: سيروا إلى عذاب جهنم الذي كنتم به تكذبون في الدنيا، سيروا، فاستظلوا بدخان جهنم يتفرع منه ثلاث قطع، لا يُظِل ذلك الظل من حر ذلك اليوم، ولا يدفع من حر اللهب شيئًا. إن جهنم تقذف من النار بشرر عظيم، كل شرارة منه كالبناء المشيد في العِظم والارتفاع. كأن شرر جهنم المتطاير منها إبل سود يميل لونها إلى الصُّفْرة.", "isBasmala": false, "translation_en": "It shoots sparks as castles.", "translation_id": "Sesungguhnya neraka itu melontarkan bunga api sebesar dan setinggi istana.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 33, "text": "كَأَنَّهُۥ جِمَـٰلَتࣱ صُفۡرࣱ ۝٣٣", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "يقال للكافرين يوم القيامة: سيروا إلى عذاب جهنم الذي كنتم به تكذبون في الدنيا، سيروا، فاستظلوا بدخان جهنم يتفرع منه ثلاث قطع، لا يُظِل ذلك الظل من حر ذلك اليوم، ولا يدفع من حر اللهب شيئًا. إن جهنم تقذف من النار بشرر عظيم، كل شرارة منه كالبناء المشيد في العِظم والارتفاع. كأن شرر جهنم المتطاير منها إبل سود يميل لونها إلى الصُّفْرة.", "isBasmala": false, "translation_en": "As if they were yellow camels.", "translation_id": "Seolah-olah ia iringan unta yang kuning.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 34, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝٣٤", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هلاك وعذاب شديد يوم القيامة للمكذبين بوعيد الله.", "isBasmala": false, "translation_en": "Woe on that Day to the liars.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 35, "text": "هَـٰذَا یَوۡمُ لَا یَنطِقُونَ ۝٣٥", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هذا يوم القيامة الذي لا ينطق فيه المكذبون بكلام ينفعهم، ولا يكون لهم إذن في الكلام فيعتذرون؛ لأنه لا عذر لهم.", "isBasmala": false, "translation_en": "This is a Day when they will not speak.", "translation_id": "Ini adalah hari, yang mereka tidak dapat berbicara (pada hari itu),", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 36, "text": "وَلَا یُؤۡذَنُ لَهُمۡ فَیَعۡتَذِرُونَ ۝٣٦", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هذا يوم القيامة الذي لا ينطق فيه المكذبون بكلام ينفعهم، ولا يكون لهم إذن في الكلام فيعتذرون؛ لأنه لا عذر لهم.", "isBasmala": false, "translation_en": "And they will not be allowed to apologize.", "translation_id": "dan tidak diizinkan kepada mereka minta uzur sehingga mereka (dapat) minta uzur.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 37, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝٣٧", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هلاك وعذاب شديد يومئذ للمكذبين بهذا اليوم وما فيه.", "isBasmala": false, "translation_en": "Woe on that Day to the rejecters.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 38, "text": "هَـٰذَا یَوۡمُ ٱلۡفَصۡلِۖ جَمَعۡنَـٰكُمۡ وَٱلۡأَوَّلِینَ ۝٣٨", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هذا يوم يفصل الله فيه بين الخلائق، ويتميز فيه الحق من الباطل، جمعناكم فيه -يا معشر كفار هذه الأمة- مع الكفار الأولين من الأمم الماضية، فإن كان لكم حيلة في الخلاص من العذاب فاحتالوا، وأنقذوا أنفسكم مِن بطش الله وانتقامه.", "isBasmala": false, "translation_en": "This is the Day of Separation; We have gathered you, together with the ancients.", "translation_id": "Ini adalah hari keputusan; (pada hari ini) Kami mengumpulkan kamu dan orang-orang terdahulu.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 39, "text": "فَإِن كَانَ لَكُمۡ كَیۡدࣱ فَكِیدُونِ ۝٣٩", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هذا يوم يفصل الله فيه بين الخلائق، ويتميز فيه الحق من الباطل، جمعناكم فيه -يا معشر كفار هذه الأمة- مع الكفار الأولين من الأمم الماضية، فإن كان لكم حيلة في الخلاص من العذاب فاحتالوا، وأنقذوا أنفسكم مِن بطش الله وانتقامه.", "isBasmala": false, "translation_en": "So if you have a strategy, use it against Me.", "translation_id": "Jika kamu mempunyai tipu daya, maka lakukanlah tipu dayamu itu terhadap-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 40, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝٤٠", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هلاك ودمار يوم القيامة للمكذبين بيوم القيامة.", "isBasmala": false, "translation_en": "Woe on that Day to the falsifiers.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 41, "text": "إِنَّ ٱلۡمُتَّقِینَ فِی ظِلَـٰلࣲ وَعُیُونࣲ ۝٤١", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إن الذين خافوا ربهم في الدنيا، واتقوا عذابه بامتثال أوامره واجتناب نواهيه، هم يوم القيامة في ظلال الأشجار الوارفة وعيون الماء الجارية، وفواكه كثيرة مما تشتهيه أنفسهم يتنعمون. يقال لهم: كلوا أكلا لذيذًا، واشربوا شربًا هنيئًا؛ بسبب ما قدمتم في الدنيا من صالح الأعمال. إنا بمثل ذلك الجزاء العظيم نجزي أهل الإحسان في أعمالهم وطاعتهم لنا. هلاك وعذاب شديد يوم القيامة للمكذبين بيوم الجزاء والحساب وما فيه من النعيم والعذاب.", "isBasmala": false, "translation_en": "The righteous will be amidst shades and fountains.", "translation_id": "Sesungguhnya orang-orang yang bertakwa berada dalam naungan (yang teduh) dan (di sekitar) mata-mata air.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 42, "text": "وَفَوَ ٰكِهَ مِمَّا یَشۡتَهُونَ ۝٤٢", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إن الذين خافوا ربهم في الدنيا، واتقوا عذابه بامتثال أوامره واجتناب نواهيه، هم يوم القيامة في ظلال الأشجار الوارفة وعيون الماء الجارية، وفواكه كثيرة مما تشتهيه أنفسهم يتنعمون. يقال لهم: كلوا أكلا لذيذًا، واشربوا شربًا هنيئًا؛ بسبب ما قدمتم في الدنيا من صالح الأعمال. إنا بمثل ذلك الجزاء العظيم نجزي أهل الإحسان في أعمالهم وطاعتهم لنا. هلاك وعذاب شديد يوم القيامة للمكذبين بيوم الجزاء والحساب وما فيه من النعيم والعذاب.", "isBasmala": false, "translation_en": "And fruits as they desire.", "translation_id": "Dan (mendapat) buah-buahan dari (macam-macam) yang mereka ingini.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 43, "text": "كُلُوا۟ وَٱشۡرَبُوا۟ هَنِیۤـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ ۝٤٣", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إن الذين خافوا ربهم في الدنيا، واتقوا عذابه بامتثال أوامره واجتناب نواهيه، هم يوم القيامة في ظلال الأشجار الوارفة وعيون الماء الجارية، وفواكه كثيرة مما تشتهيه أنفسهم يتنعمون. يقال لهم: كلوا أكلا لذيذًا، واشربوا شربًا هنيئًا؛ بسبب ما قدمتم في الدنيا من صالح الأعمال. إنا بمثل ذلك الجزاء العظيم نجزي أهل الإحسان في أعمالهم وطاعتهم لنا. هلاك وعذاب شديد يوم القيامة للمكذبين بيوم الجزاء والحساب وما فيه من النعيم والعذاب.", "isBasmala": false, "translation_en": "\"Eat and drink pleasantly, for what you used to do.\"", "translation_id": "(Dikatakan kepada mereka): \"Makan dan minumlah kamu dengan enak karena apa yang telah kamu kerjakan\".", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 44, "text": "إِنَّا كَذَ ٰلِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ ۝٤٤", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إن الذين خافوا ربهم في الدنيا، واتقوا عذابه بامتثال أوامره واجتناب نواهيه، هم يوم القيامة في ظلال الأشجار الوارفة وعيون الماء الجارية، وفواكه كثيرة مما تشتهيه أنفسهم يتنعمون. يقال لهم: كلوا أكلا لذيذًا، واشربوا شربًا هنيئًا؛ بسبب ما قدمتم في الدنيا من صالح الأعمال. إنا بمثل ذلك الجزاء العظيم نجزي أهل الإحسان في أعمالهم وطاعتهم لنا. هلاك وعذاب شديد يوم القيامة للمكذبين بيوم الجزاء والحساب وما فيه من النعيم والعذاب.", "isBasmala": false, "translation_en": "This is how We reward the doers of good.", "translation_id": "Sesungguhnya demikianlah Kami memberi balasan kepada orang-orang yang berbuat baik.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 45, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝٤٥", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "إن الذين خافوا ربهم في الدنيا، واتقوا عذابه بامتثال أوامره واجتناب نواهيه، هم يوم القيامة في ظلال الأشجار الوارفة وعيون الماء الجارية، وفواكه كثيرة مما تشتهيه أنفسهم يتنعمون. يقال لهم: كلوا أكلا لذيذًا، واشربوا شربًا هنيئًا؛ بسبب ما قدمتم في الدنيا من صالح الأعمال. إنا بمثل ذلك الجزاء العظيم نجزي أهل الإحسان في أعمالهم وطاعتهم لنا. هلاك وعذاب شديد يوم القيامة للمكذبين بيوم الجزاء والحساب وما فيه من النعيم والعذاب.", "isBasmala": false, "translation_en": "Woe on that Day to the deniers.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 46, "text": "كُلُوا۟ وَتَمَتَّعُوا۟ قَلِیلًا إِنَّكُم مُّجۡرِمُونَ ۝٤٦", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "ثم هدَّد الله الكافرين فقال: كلوا من لذائذ الدنيا، واستمتعوا بشهواتها الفانية زمنًا قليلا؛ إنكم مجرمون بإشراككم بالله.", "isBasmala": false, "translation_en": "\"Eat and enjoy yourselves a little; you are indeed criminals.\"", "translation_id": "(Dikatakan kepada orang-orang kafir): \"Makanlah dan bersenang-senanglah kamu (di dunia dalam waktu) yang pendek; sesungguhnya kamu adalah orang-orang yang berdosa\".", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 47, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝٤٧", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هلاك وعذاب شديد يوم القيامة للمكذبين بيوم الحساب والجزاء.", "isBasmala": false, "translation_en": "Woe on that Day to the liars.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 48, "text": "وَإِذَا قِیلَ لَهُمُ ٱرۡكَعُوا۟ لَا یَرۡكَعُونَ ۝٤٨", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "وإذا قيل لهؤلاء المشركين: صلُّوا لله، واخشعوا له، لا يخشعون ولا يصلُّون، بل يصرُّون على استكبارهم.", "isBasmala": false, "translation_en": "And when it is said to them, \"Kneel\", they do not kneel.", "translation_id": "Dan apabila dikatakan kepada mereka: \"Rukuklah, niscaya mereka tidak mau ruku'.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 49, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝٤٩", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هلاك وعذاب شديد يوم القيامة للمكذبين بآيات الله، إن لم يؤمنوا بهذا القرآن، فبأي كتاب وكلام بعده يؤمنون؟ وهو المبيِّن لكل شيء، الواضح في حكمه وأحكامه وأخباره، المعجز في ألفاظه ومعانيه.", "isBasmala": false, "translation_en": "Woe on that Day to the rejecters.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan.", "manzil": 7, "manzil_display": ""}, {"sura": 77, "sura_name": "المرسلات", "revelation": "Makkiyah", "aya": 50, "text": "فَبِأَیِّ حَدِیثِۭ بَعۡدَهُۥ یُؤۡمِنُونَ ۝٥٠", "juz": 29, "hizb": "(*¾ ح 58*)", "tafsir": "هلاك وعذاب شديد يوم القيامة للمكذبين بآيات الله، إن لم يؤمنوا بهذا القرآن، فبأي كتاب وكلام بعده يؤمنون؟ وهو المبيِّن لكل شيء، الواضح في حكمه وأحكامه وأخباره، المعجز في ألفاظه ومعانيه.", "isBasmala": false, "translation_en": "In what message, beyond this, will they believe?", "translation_id": "Maka kepada perkataan apakah selain Al Quran ini mereka akan beriman?", "manzil": 7, "manzil_display": ""}], "582": [{"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 1, "text": "۞ عَمَّ یَتَسَاۤءَلُونَ ۝١", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "عن أيِّ شيء يسأل بعض كفار قريش بعضا؟ يتساءلون عن الخبر العظيم الشأن، وهو القرآن العظيم الذي ينبئ عن البعث الذي شك فيه كفار قريش وكذَّبوا به.", "isBasmala": false, "translation_en": "What are they asking one another about?", "translation_id": "Tentang apakah mereka saling bertanya-tanya?", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 2, "text": "عَنِ ٱلنَّبَإِ ٱلۡعَظِیمِ ۝٢", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "عن أيِّ شيء يسأل بعض كفار قريش بعضا؟ يتساءلون عن الخبر العظيم الشأن، وهو القرآن العظيم الذي ينبئ عن البعث الذي شك فيه كفار قريش وكذَّبوا به.", "isBasmala": false, "translation_en": "About the Great Event.", "translation_id": "Tentang berita yang besar,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 3, "text": "ٱلَّذِی هُمۡ فِیهِ مُخۡتَلِفُونَ ۝٣", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "عن أيِّ شيء يسأل بعض كفار قريش بعضا؟ يتساءلون عن الخبر العظيم الشأن، وهو القرآن العظيم الذي ينبئ عن البعث الذي شك فيه كفار قريش وكذَّبوا به.", "isBasmala": false, "translation_en": "About which they disagree.", "translation_id": "yang mereka perselisihkan tentang ini.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 4, "text": "كَلَّا سَیَعۡلَمُونَ ۝٤", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "ما الأمر كما يزعم هؤلاء المشركون، سيعلم هؤلاء المشركون عاقبة تكذيبهم، ويظهر لهم ما الله فاعل بهم يوم القيامة، ثم سيتأكد لهم ذلك، ويتأكد لهم صدق ما جاء به محمد صلى الله عليه وسلم، من القرآن والبعث. وهذا تهديد ووعيد لهم.", "isBasmala": false, "translation_en": "Surely, they will find out.", "translation_id": "Sekali-kali tidak; kelak mereka akan mengetahui,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 5, "text": "ثُمَّ كَلَّا سَیَعۡلَمُونَ ۝٥", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "ما الأمر كما يزعم هؤلاء المشركون، سيعلم هؤلاء المشركون عاقبة تكذيبهم، ويظهر لهم ما الله فاعل بهم يوم القيامة، ثم سيتأكد لهم ذلك، ويتأكد لهم صدق ما جاء به محمد صلى الله عليه وسلم، من القرآن والبعث. وهذا تهديد ووعيد لهم.", "isBasmala": false, "translation_en": "Most certainly, they will find out.", "translation_id": "kemudian sekali-kali tidak; kelak mereka mengetahui.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 6, "text": "أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَـٰدࣰا ۝٦", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "ألم نجعل الأرض ممهدة لكم كالفراش؟", "isBasmala": false, "translation_en": "Did We not make the earth a cradle?", "translation_id": "Bukankah Kami telah menjadikan bumi itu sebagai hamparan?,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 7, "text": "وَٱلۡجِبَالَ أَوۡتَادࣰا ۝٧", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "والجبال رواسي؛ كي لا تتحرك بكم الأرض؟", "isBasmala": false, "translation_en": "And the mountains pegs?", "translation_id": "dan gunung-gunung sebagai pasak?,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 8, "text": "وَخَلَقۡنَـٰكُمۡ أَزۡوَ ٰجࣰا ۝٨", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وخلقناكم أصنافا ذكرا وأنثى؟", "isBasmala": false, "translation_en": "And created you in pairs?", "translation_id": "dan Kami jadikan kamu berpasang-pasangan,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 9, "text": "وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتࣰا ۝٩", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وجعلنا نومكم راحة لأبدانكم، فيه تهدؤون وتسكنون؟", "isBasmala": false, "translation_en": "And made your sleep for rest?", "translation_id": "dan Kami jadikan tidurmu untuk istirahat,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 10, "text": "وَجَعَلۡنَا ٱلَّیۡلَ لِبَاسࣰا ۝١٠", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وجعلنا الليل لباسًا تَلْبَسكم ظلمته وتغشاكم، كما يستر الثوب لابسه؟", "isBasmala": false, "translation_en": "And made the night a cover?", "translation_id": "dan Kami jadikan malam sebagai pakaian,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 11, "text": "وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشࣰا ۝١١", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وجعلنا النهار معاشا تنتشرون فيه لمعاشكم، وتسعَون فيه لمصالحكم؟", "isBasmala": false, "translation_en": "And made the day for livelihood?", "translation_id": "dan Kami jadikan siang untuk mencari penghidupan,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 12, "text": "وَبَنَیۡنَا فَوۡقَكُمۡ سَبۡعࣰا شِدَادࣰا ۝١٢", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وبنينا فوقكم سبع سموات متينة البناء محكمة الخلق، لا صدوع لها ولا فطور؟", "isBasmala": false, "translation_en": "And built above you seven strong ones?", "translation_id": "dan Kami bina di atas kamu tujuh buah (langit) yang kokoh,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 13, "text": "وَجَعَلۡنَا سِرَاجࣰا وَهَّاجࣰا ۝١٣", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وجعلنا الشمس سراجًا وقَّادًا مضيئًا؟", "isBasmala": false, "translation_en": "And placed a blazing lamp?", "translation_id": "dan Kami jadikan pelita yang amat terang (matahari),", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 14, "text": "وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَ ٰتِ مَاۤءࣰ ثَجَّاجࣰا ۝١٤", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وأنزلنا من السحب الممطرة ماء منصَبّا بكثرة، لنخرج به حبًا مما يقتات به الناس وحشائش مما تأكله الدَّواب، وبساتين ملتفة بعضها ببعض لتشعب أغصانها؟", "isBasmala": false, "translation_en": "And brought down from the clouds pouring water?", "translation_id": "dan Kami turunkan dari awan air yang banyak tercurah,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 15, "text": "لِّنُخۡرِجَ بِهِۦ حَبࣰّا وَنَبَاتࣰا ۝١٥", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وأنزلنا من السحب الممطرة ماء منصَبّا بكثرة، لنخرج به حبًا مما يقتات به الناس وحشائش مما تأكله الدَّواب، وبساتين ملتفة بعضها ببعض لتشعب أغصانها؟", "isBasmala": false, "translation_en": "To produce with it grains and vegetation?", "translation_id": "supaya Kami tumbuhkan dengan air itu biji-bijian dan tumbuh-tumbuhan,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 16, "text": "وَجَنَّـٰتٍ أَلۡفَافًا ۝١٦", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وأنزلنا من السحب الممطرة ماء منصَبّا بكثرة، لنخرج به حبًا مما يقتات به الناس وحشائش مما تأكله الدَّواب، وبساتين ملتفة بعضها ببعض لتشعب أغصانها؟", "isBasmala": false, "translation_en": "And luxuriant gardens?", "translation_id": "dan kebun-kebun yang lebat?", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 17, "text": "إِنَّ یَوۡمَ ٱلۡفَصۡلِ كَانَ مِیقَـٰتࣰا ۝١٧", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن يوم الفصل بين الخلق، وهو يوم القيامة، كان وقتًا وميعادًا محددًا للأولين والآخرين، يوم ينفخ المَلَك في \"القرن\" إيذانًا بالبعث فتأتون أممًا، كل أمة مع إمامهم.", "isBasmala": false, "translation_en": "The Day of Sorting has been appointed.", "translation_id": "Sesungguhnya Hari Keputusan adalah suatu waktu yang ditetapkan,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 18, "text": "یَوۡمَ یُنفَخُ فِی ٱلصُّورِ فَتَأۡتُونَ أَفۡوَاجࣰا ۝١٨", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن يوم الفصل بين الخلق، وهو يوم القيامة، كان وقتًا وميعادًا محددًا للأولين والآخرين، يوم ينفخ المَلَك في \"القرن\" إيذانًا بالبعث فتأتون أممًا، كل أمة مع إمامهم.", "isBasmala": false, "translation_en": "The Day when the Trumpet is blown, and you will come in droves.", "translation_id": "yaitu hari (yang pada waktu itu) ditiup sangkakala lalu kamu datang berkelompok-kelompok,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 19, "text": "وَفُتِحَتِ ٱلسَّمَاۤءُ فَكَانَتۡ أَبۡوَ ٰبࣰا ۝١٩", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وفُتحت السماء، فكانت ذات أبواب كثيرة لنزول الملائكة.", "isBasmala": false, "translation_en": "And the sky is opened up, and becomes gateways.", "translation_id": "dan dibukalah langit, maka terdapatlah beberapa pintu,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 20, "text": "وَسُیِّرَتِ ٱلۡجِبَالُ فَكَانَتۡ سَرَابًا ۝٢٠", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "ونسفت الجبال بعد ثبوتها، فكانت كالسراب.", "isBasmala": false, "translation_en": "And the mountains are set in motion, and become a mirage.", "translation_id": "dan dijalankanlah gunung-gunung maka menjadi fatamorganalah ia.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 21, "text": "إِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادࣰا ۝٢١", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن جهنم كانت يومئذ ترصد أهل الكفر الذين أُعِدَّت لهم، للكافرين مرجعًا، ماكثين فيها دهورًا متعاقبة لا تنقطع، لا يَطْعَمون فيها ما يُبْرد حرَّ السعير عنهم، ولا شرابًا يرويهم، إلا ماءً حارًا، وصديد أهل النار، يجازَون بذلك جزاء عادلا موافقًا لأعمالهم التي كانوا يعملونها في الدنيا.", "isBasmala": false, "translation_en": "Hell is lying in ambush.", "translation_id": "Sesungguhnya neraka Jahannam itu (padanya) ada tempat pengintai,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 22, "text": "لِّلطَّـٰغِینَ مَـَٔابࣰا ۝٢٢", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن جهنم كانت يومئذ ترصد أهل الكفر الذين أُعِدَّت لهم، للكافرين مرجعًا، ماكثين فيها دهورًا متعاقبة لا تنقطع، لا يَطْعَمون فيها ما يُبْرد حرَّ السعير عنهم، ولا شرابًا يرويهم، إلا ماءً حارًا، وصديد أهل النار، يجازَون بذلك جزاء عادلا موافقًا لأعمالهم التي كانوا يعملونها في الدنيا.", "isBasmala": false, "translation_en": "For the oppressors, a destination.", "translation_id": "lagi menjadi tempat kembali bagi orang-orang yang melampaui batas,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 23, "text": "لَّـٰبِثِینَ فِیهَاۤ أَحۡقَابࣰا ۝٢٣", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن جهنم كانت يومئذ ترصد أهل الكفر الذين أُعِدَّت لهم، للكافرين مرجعًا، ماكثين فيها دهورًا متعاقبة لا تنقطع، لا يَطْعَمون فيها ما يُبْرد حرَّ السعير عنهم، ولا شرابًا يرويهم، إلا ماءً حارًا، وصديد أهل النار، يجازَون بذلك جزاء عادلا موافقًا لأعمالهم التي كانوا يعملونها في الدنيا.", "isBasmala": false, "translation_en": "Where they will remain for eons.", "translation_id": "mereka tinggal di dalamnya berabad-abad lamanya,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 24, "text": "لَّا یَذُوقُونَ فِیهَا بَرۡدࣰا وَلَا شَرَابًا ۝٢٤", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن جهنم كانت يومئذ ترصد أهل الكفر الذين أُعِدَّت لهم، للكافرين مرجعًا، ماكثين فيها دهورًا متعاقبة لا تنقطع، لا يَطْعَمون فيها ما يُبْرد حرَّ السعير عنهم، ولا شرابًا يرويهم، إلا ماءً حارًا، وصديد أهل النار، يجازَون بذلك جزاء عادلا موافقًا لأعمالهم التي كانوا يعملونها في الدنيا.", "isBasmala": false, "translation_en": "They will taste therein neither coolness, nor drink.", "translation_id": "mereka tidak merasakan kesejukan di dalamnya dan tidak (pula mendapat) minuman,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 25, "text": "إِلَّا حَمِیمࣰا وَغَسَّاقࣰا ۝٢٥", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن جهنم كانت يومئذ ترصد أهل الكفر الذين أُعِدَّت لهم، للكافرين مرجعًا، ماكثين فيها دهورًا متعاقبة لا تنقطع، لا يَطْعَمون فيها ما يُبْرد حرَّ السعير عنهم، ولا شرابًا يرويهم، إلا ماءً حارًا، وصديد أهل النار، يجازَون بذلك جزاء عادلا موافقًا لأعمالهم التي كانوا يعملونها في الدنيا.", "isBasmala": false, "translation_en": "Except boiling water, and freezing hail.", "translation_id": "selain air yang mendidih dan nanah,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 26, "text": "جَزَاۤءࣰ وِفَاقًا ۝٢٦", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن جهنم كانت يومئذ ترصد أهل الكفر الذين أُعِدَّت لهم، للكافرين مرجعًا، ماكثين فيها دهورًا متعاقبة لا تنقطع، لا يَطْعَمون فيها ما يُبْرد حرَّ السعير عنهم، ولا شرابًا يرويهم، إلا ماءً حارًا، وصديد أهل النار، يجازَون بذلك جزاء عادلا موافقًا لأعمالهم التي كانوا يعملونها في الدنيا.", "isBasmala": false, "translation_en": "A fitting requital.", "translation_id": "sebagai pambalasan yang setimpal.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 27, "text": "إِنَّهُمۡ كَانُوا۟ لَا یَرۡجُونَ حِسَابࣰا ۝٢٧", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إنهم كانوا لا يخافون يوم الحساب فلم يعملوا له، وكذَّبوا بما جاءتهم به الرسل تكذيبا، وكلَّ شيء علمناه وكتبناه في اللوح المحفوظ، فذوقوا -أيها الكافرون- جزاء أعمالكم، فلن نزيدكم إلا عذابًا فوق عذابكم.", "isBasmala": false, "translation_en": "For they were not anticipating any reckoning.", "translation_id": "Sesungguhnya mereka tidak berharap (takut) kepada hisab,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 28, "text": "وَكَذَّبُوا۟ بِـَٔایَـٰتِنَا كِذَّابࣰا ۝٢٨", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إنهم كانوا لا يخافون يوم الحساب فلم يعملوا له، وكذَّبوا بما جاءتهم به الرسل تكذيبا، وكلَّ شيء علمناه وكتبناه في اللوح المحفوظ، فذوقوا -أيها الكافرون- جزاء أعمالكم، فلن نزيدكم إلا عذابًا فوق عذابكم.", "isBasmala": false, "translation_en": "And they denied Our signs utterly.", "translation_id": "dan mereka mendustakan ayat-ayat Kami dengan sesungguh-sungguhnya.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 29, "text": "وَكُلَّ شَیۡءٍ أَحۡصَیۡنَـٰهُ كِتَـٰبࣰا ۝٢٩", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إنهم كانوا لا يخافون يوم الحساب فلم يعملوا له، وكذَّبوا بما جاءتهم به الرسل تكذيبا، وكلَّ شيء علمناه وكتبناه في اللوح المحفوظ، فذوقوا -أيها الكافرون- جزاء أعمالكم، فلن نزيدكم إلا عذابًا فوق عذابكم.", "isBasmala": false, "translation_en": "But We have enumerated everything in writing.", "translation_id": "Dan segala sesuatu telah Kami catat dalam suatu kitab.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 30, "text": "فَذُوقُوا۟ فَلَن نَّزِیدَكُمۡ إِلَّا عَذَابًا ۝٣٠", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إنهم كانوا لا يخافون يوم الحساب فلم يعملوا له، وكذَّبوا بما جاءتهم به الرسل تكذيبا، وكلَّ شيء علمناه وكتبناه في اللوح المحفوظ، فذوقوا -أيها الكافرون- جزاء أعمالكم، فلن نزيدكم إلا عذابًا فوق عذابكم.", "isBasmala": false, "translation_en": "So taste! We will increase you only in suffering.", "translation_id": "Karena itu rasakanlah. Dan Kami sekali-kali tidak akan menambah kepada kamu selain daripada azab.", "manzil": 7, "manzil_display": ""}], "583": [{"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 31, "text": "إِنَّ لِلۡمُتَّقِینَ مَفَازًا ۝٣١", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن للذين يخافون ربهم ويعملون صالحًا، فوزًا بدخولهم الجنة. إن لهم بساتين عظيمة وأعنابًا، ولهم زوجات حديثات السن، نواهد مستويات في سن واحدة، ولهم كأس مملوءة خمرًا. لا يسمعون في هذه الجنة باطلا من القول، ولا يكذب بعضهم بعضًا.", "isBasmala": false, "translation_en": "But for the righteous there is triumph.", "translation_id": "Sesungguhnya orang-orang yang bertakwa mendapat kemenangan,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 32, "text": "حَدَاۤىِٕقَ وَأَعۡنَـٰبࣰا ۝٣٢", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن للذين يخافون ربهم ويعملون صالحًا، فوزًا بدخولهم الجنة. إن لهم بساتين عظيمة وأعنابًا، ولهم زوجات حديثات السن، نواهد مستويات في سن واحدة، ولهم كأس مملوءة خمرًا. لا يسمعون في هذه الجنة باطلا من القول، ولا يكذب بعضهم بعضًا.", "isBasmala": false, "translation_en": "Gardens and vineyards.", "translation_id": "(yaitu) kebun-kebun dan buah anggur,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 33, "text": "وَكَوَاعِبَ أَتۡرَابࣰا ۝٣٣", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن للذين يخافون ربهم ويعملون صالحًا، فوزًا بدخولهم الجنة. إن لهم بساتين عظيمة وأعنابًا، ولهم زوجات حديثات السن، نواهد مستويات في سن واحدة، ولهم كأس مملوءة خمرًا. لا يسمعون في هذه الجنة باطلا من القول، ولا يكذب بعضهم بعضًا.", "isBasmala": false, "translation_en": "And splendid spouses, well matched.", "translation_id": "dan gadis-gadis remaja yang sebaya,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 34, "text": "وَكَأۡسࣰا دِهَاقࣰا ۝٣٤", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن للذين يخافون ربهم ويعملون صالحًا، فوزًا بدخولهم الجنة. إن لهم بساتين عظيمة وأعنابًا، ولهم زوجات حديثات السن، نواهد مستويات في سن واحدة، ولهم كأس مملوءة خمرًا. لا يسمعون في هذه الجنة باطلا من القول، ولا يكذب بعضهم بعضًا.", "isBasmala": false, "translation_en": "And delicious drinks.", "translation_id": "dan gelas-gelas yang penuh (berisi minuman).", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 35, "text": "لَّا یَسۡمَعُونَ فِیهَا لَغۡوࣰا وَلَا كِذَّ ٰبࣰا ۝٣٥", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إن للذين يخافون ربهم ويعملون صالحًا، فوزًا بدخولهم الجنة. إن لهم بساتين عظيمة وأعنابًا، ولهم زوجات حديثات السن، نواهد مستويات في سن واحدة، ولهم كأس مملوءة خمرًا. لا يسمعون في هذه الجنة باطلا من القول، ولا يكذب بعضهم بعضًا.", "isBasmala": false, "translation_en": "They will hear therein neither gossip, nor lies.", "translation_id": "Di dalamnya mereka tidak mendengar perkataan yang sia-sia dan tidak (pula) perkataan dusta.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 36, "text": "جَزَاۤءࣰ مِّن رَّبِّكَ عَطَاۤءً حِسَابࣰا ۝٣٦", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "لهم كل ذلك جزاء ومنَّة من الله وعطاءً كثيرًا كافيًا لهم، ربِّ السموات والأرض وما بينهما، رحمنِ الدنيا والآخرة، لا يملكون أن يسألوه إلا فيما أذن لهم فيه، يوم يقوم جبريل عليه السلام والملائكة مصطفِّين، لا يشفعون إلا لمن أذن له الرحمن في الشفاعة، وقال حقًا وسدادًا. ذلك اليوم الحق الذي لا ريب في وقوعه، فمن شاء النجاة مِن أهواله فليتخذ إلى ربه مرجعًا بالعمل الصالح.", "isBasmala": false, "translation_en": "A reward from your Lord, a fitting gift.", "translation_id": "Sebagai pembalasan dari Tuhanmu dan pemberian yang cukup banyak,", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 37, "text": "رَّبِّ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا ٱلرَّحۡمَـٰنِۖ لَا یَمۡلِكُونَ مِنۡهُ خِطَابࣰا ۝٣٧", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "لهم كل ذلك جزاء ومنَّة من الله وعطاءً كثيرًا كافيًا لهم، ربِّ السموات والأرض وما بينهما، رحمنِ الدنيا والآخرة، لا يملكون أن يسألوه إلا فيما أذن لهم فيه، يوم يقوم جبريل عليه السلام والملائكة مصطفِّين، لا يشفعون إلا لمن أذن له الرحمن في الشفاعة، وقال حقًا وسدادًا. ذلك اليوم الحق الذي لا ريب في وقوعه، فمن شاء النجاة مِن أهواله فليتخذ إلى ربه مرجعًا بالعمل الصالح.", "isBasmala": false, "translation_en": "Lord of the heavens and the earth, and everything between them-The Most Merciful-none can argue with Him.", "translation_id": "Tuhan Yang memelihara langit dan bumi dan apa yang ada di antara keduanya; Yang Maha Pemurah. Mereka tidak dapat berbicara dengan Dia.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 38, "text": "یَوۡمَ یَقُومُ ٱلرُّوحُ وَٱلۡمَلَـٰۤىِٕكَةُ صَفࣰّاۖ لَّا یَتَكَلَّمُونَ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَـٰنُ وَقَالَ صَوَابࣰا ۝٣٨", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "لهم كل ذلك جزاء ومنَّة من الله وعطاءً كثيرًا كافيًا لهم، ربِّ السموات والأرض وما بينهما، رحمنِ الدنيا والآخرة، لا يملكون أن يسألوه إلا فيما أذن لهم فيه، يوم يقوم جبريل عليه السلام والملائكة مصطفِّين، لا يشفعون إلا لمن أذن له الرحمن في الشفاعة، وقال حقًا وسدادًا. ذلك اليوم الحق الذي لا ريب في وقوعه، فمن شاء النجاة مِن أهواله فليتخذ إلى ربه مرجعًا بالعمل الصالح.", "isBasmala": false, "translation_en": "On the Day when the Spirit and the angels stand in row. They will not speak, unless it be one permitted by the Most Merciful, and he will say what is right.", "translation_id": "Pada hari, ketika ruh dan para malaikat berdiri bershaf-shaf, mereka tidak berkata-kata, kecuali siapa yang telah diberi izin kepadanya oleh Tuhan Yang Maha Pemurah; dan ia mengucapkan kata yang benar.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 39, "text": "ذَ ٰلِكَ ٱلۡیَوۡمُ ٱلۡحَقُّۖ فَمَن شَاۤءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا ۝٣٩", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "لهم كل ذلك جزاء ومنَّة من الله وعطاءً كثيرًا كافيًا لهم، ربِّ السموات والأرض وما بينهما، رحمنِ الدنيا والآخرة، لا يملكون أن يسألوه إلا فيما أذن لهم فيه، يوم يقوم جبريل عليه السلام والملائكة مصطفِّين، لا يشفعون إلا لمن أذن له الرحمن في الشفاعة، وقال حقًا وسدادًا. ذلك اليوم الحق الذي لا ريب في وقوعه، فمن شاء النجاة مِن أهواله فليتخذ إلى ربه مرجعًا بالعمل الصالح.", "isBasmala": false, "translation_en": "That is the Day of Reality. So whoever wills, let him take a way back to his Lord.", "translation_id": "Itulah hari yang pasti terjadi. Maka barangsiapa yang menghendaki, niscaya ia menempuh jalan kembali kepada Tuhannya.", "manzil": 7, "manzil_display": ""}, {"sura": 78, "sura_name": "النبأ", "revelation": "Makkiyah", "aya": 40, "text": "إِنَّاۤ أَنذَرۡنَـٰكُمۡ عَذَابࣰا قَرِیبࣰا یَوۡمَ یَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ یَدَاهُ وَیَقُولُ ٱلۡكَافِرُ یَـٰلَیۡتَنِی كُنتُ تُرَ ٰبَۢا ۝٤٠", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "إنَّا حذَّرناكم عذاب يوم الآخرة القريب الذي يرى فيه كل امرئ ما عمل من خير أو اكتسب من إثم، ويقول الكافر من هول الحساب: يا ليتني كنت ترابًا فلم أُبعث.", "isBasmala": false, "translation_en": "We have warned you of a near punishment-the Day when a person will observe what his hands have produced, and the faithless will say, \"O, I wish I were dust.\"", "translation_id": "Sesungguhnya Kami telah memperingatkan kepadamu (hai orang kafir) siksa yang dekat, pada hari manusia melihat apa yang telah diperbuat oleh kedua tangannya; dan orang kafir berkata: \"Alangkah baiknya sekiranya aku dahulu adalah tanah\".", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلنَّـٰزِعَـٰتِ غَرۡقࣰا ۝١", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أقسم الله تعالى بالملائكة التي تنزع أرواح الكفار نزعا شديدا، والملائكة التي تقبض أرواح المؤمنين بنشاط ورفق، والملائكة التي تَسْبَح في نزولها من السماء وصعودها إليها، فالملائكة التي تسبق وتسارع إلى تنفيذ أمر الله، فالملائكة المنفذات أمر ربها فيما أوكل إليها تدبيره من شؤون الكون -ولا يجوز للمخلوق أن يقسم بغير خالقه، فإن فعل فقد أشرك- لتُبعثَنَّ الخلائق وتُحَاسَب، يوم تضطرب الأرض بالنفخة الأولى نفخة الإماتة، تتبعها نفخة أخرى للإحياء.", "isBasmala": false, "translation_en": "By those who snatch violently.", "translation_id": "Demi (malaikat-malaikat) yang mencabut (nyawa) dengan keras,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 2, "text": "وَٱلنَّـٰشِطَـٰتِ نَشۡطࣰا ۝٢", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أقسم الله تعالى بالملائكة التي تنزع أرواح الكفار نزعا شديدا، والملائكة التي تقبض أرواح المؤمنين بنشاط ورفق، والملائكة التي تَسْبَح في نزولها من السماء وصعودها إليها، فالملائكة التي تسبق وتسارع إلى تنفيذ أمر الله، فالملائكة المنفذات أمر ربها فيما أوكل إليها تدبيره من شؤون الكون -ولا يجوز للمخلوق أن يقسم بغير خالقه، فإن فعل فقد أشرك- لتُبعثَنَّ الخلائق وتُحَاسَب، يوم تضطرب الأرض بالنفخة الأولى نفخة الإماتة، تتبعها نفخة أخرى للإحياء.", "isBasmala": false, "translation_en": "And those who remove gently.", "translation_id": "dan (malaikat-malaikat) yang mencabut (nyawa) dengan lemah-lembut,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 3, "text": "وَٱلسَّـٰبِحَـٰتِ سَبۡحࣰا ۝٣", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أقسم الله تعالى بالملائكة التي تنزع أرواح الكفار نزعا شديدا، والملائكة التي تقبض أرواح المؤمنين بنشاط ورفق، والملائكة التي تَسْبَح في نزولها من السماء وصعودها إليها، فالملائكة التي تسبق وتسارع إلى تنفيذ أمر الله، فالملائكة المنفذات أمر ربها فيما أوكل إليها تدبيره من شؤون الكون -ولا يجوز للمخلوق أن يقسم بغير خالقه، فإن فعل فقد أشرك- لتُبعثَنَّ الخلائق وتُحَاسَب، يوم تضطرب الأرض بالنفخة الأولى نفخة الإماتة، تتبعها نفخة أخرى للإحياء.", "isBasmala": false, "translation_en": "And those who glide smoothly.", "translation_id": "dan (malaikat-malaikat) yang turun dari langit dengan cepat,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 4, "text": "فَٱلسَّـٰبِقَـٰتِ سَبۡقࣰا ۝٤", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أقسم الله تعالى بالملائكة التي تنزع أرواح الكفار نزعا شديدا، والملائكة التي تقبض أرواح المؤمنين بنشاط ورفق، والملائكة التي تَسْبَح في نزولها من السماء وصعودها إليها، فالملائكة التي تسبق وتسارع إلى تنفيذ أمر الله، فالملائكة المنفذات أمر ربها فيما أوكل إليها تدبيره من شؤون الكون -ولا يجوز للمخلوق أن يقسم بغير خالقه، فإن فعل فقد أشرك- لتُبعثَنَّ الخلائق وتُحَاسَب، يوم تضطرب الأرض بالنفخة الأولى نفخة الإماتة، تتبعها نفخة أخرى للإحياء.", "isBasmala": false, "translation_en": "And those who race swiftly.", "translation_id": "dan (malaikat-malaikat) yang mendahului dengan kencang,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 5, "text": "فَٱلۡمُدَبِّرَ ٰتِ أَمۡرࣰا ۝٥", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أقسم الله تعالى بالملائكة التي تنزع أرواح الكفار نزعا شديدا، والملائكة التي تقبض أرواح المؤمنين بنشاط ورفق، والملائكة التي تَسْبَح في نزولها من السماء وصعودها إليها، فالملائكة التي تسبق وتسارع إلى تنفيذ أمر الله، فالملائكة المنفذات أمر ربها فيما أوكل إليها تدبيره من شؤون الكون -ولا يجوز للمخلوق أن يقسم بغير خالقه، فإن فعل فقد أشرك- لتُبعثَنَّ الخلائق وتُحَاسَب، يوم تضطرب الأرض بالنفخة الأولى نفخة الإماتة، تتبعها نفخة أخرى للإحياء.", "isBasmala": false, "translation_en": "And those who regulate events.", "translation_id": "dan (malaikat-malaikat) yang mengatur urusan (dunia).", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 6, "text": "یَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ ۝٦", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أقسم الله تعالى بالملائكة التي تنزع أرواح الكفار نزعا شديدا، والملائكة التي تقبض أرواح المؤمنين بنشاط ورفق، والملائكة التي تَسْبَح في نزولها من السماء وصعودها إليها، فالملائكة التي تسبق وتسارع إلى تنفيذ أمر الله، فالملائكة المنفذات أمر ربها فيما أوكل إليها تدبيره من شؤون الكون -ولا يجوز للمخلوق أن يقسم بغير خالقه، فإن فعل فقد أشرك- لتُبعثَنَّ الخلائق وتُحَاسَب، يوم تضطرب الأرض بالنفخة الأولى نفخة الإماتة، تتبعها نفخة أخرى للإحياء.", "isBasmala": false, "translation_en": "On the Day when the Quake quakes.", "translation_id": "(Sesungguhnya kamu akan dibangkitkan) pada hari ketika tiupan pertama menggoncang alam,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 7, "text": "تَتۡبَعُهَا ٱلرَّادِفَةُ ۝٧", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أقسم الله تعالى بالملائكة التي تنزع أرواح الكفار نزعا شديدا، والملائكة التي تقبض أرواح المؤمنين بنشاط ورفق، والملائكة التي تَسْبَح في نزولها من السماء وصعودها إليها، فالملائكة التي تسبق وتسارع إلى تنفيذ أمر الله، فالملائكة المنفذات أمر ربها فيما أوكل إليها تدبيره من شؤون الكون -ولا يجوز للمخلوق أن يقسم بغير خالقه، فإن فعل فقد أشرك- لتُبعثَنَّ الخلائق وتُحَاسَب، يوم تضطرب الأرض بالنفخة الأولى نفخة الإماتة، تتبعها نفخة أخرى للإحياء.", "isBasmala": false, "translation_en": "And is followed by the Successor.", "translation_id": "tiupan pertama itu diiringi oleh tiupan kedua.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 8, "text": "قُلُوبࣱ یَوۡمَىِٕذࣲ وَاجِفَةٌ ۝٨", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "قلوب الكفار يومئذ مضطربة من شدة الخوف، أبصار أصحابها ذليلة من هول ما ترى.", "isBasmala": false, "translation_en": "Hearts on that Day will be pounding.", "translation_id": "Hati manusia pada waktu itu sangat takut,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 9, "text": "أَبۡصَـٰرُهَا خَـٰشِعَةࣱ ۝٩", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "قلوب الكفار يومئذ مضطربة من شدة الخوف، أبصار أصحابها ذليلة من هول ما ترى.", "isBasmala": false, "translation_en": "Their sights downcast.", "translation_id": "Pandangannya tunduk.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 10, "text": "یَقُولُونَ أَءِنَّا لَمَرۡدُودُونَ فِی ٱلۡحَافِرَةِ ۝١٠", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "يقول هؤلاء المكذبون بالبعث: أنُرَدُّ بعد موتنا إلى ما كنا عليه أحياء في الأرض؟ أنردُّ وقد صرنا عظامًا بالية؟ قالوا: رجعتنا تلك ستكون إذًا خائبة كاذبة.", "isBasmala": false, "translation_en": "They say, \"Are we to be restored to the original condition?", "translation_id": "(Orang-orang kafir) berkata: \"Apakah sesungguhnya kami benar-benar dikembalikan kepada kehidupan semula?", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 11, "text": "أَءِذَا كُنَّا عِظَـٰمࣰا نَّخِرَةࣰ ۝١١", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "يقول هؤلاء المكذبون بالبعث: أنُرَدُّ بعد موتنا إلى ما كنا عليه أحياء في الأرض؟ أنردُّ وقد صرنا عظامًا بالية؟ قالوا: رجعتنا تلك ستكون إذًا خائبة كاذبة.", "isBasmala": false, "translation_en": "When we have become hollow bones?\"", "translation_id": "Apakah (akan dibangkitkan juga) apabila kami telah menjadi tulang belulang yang hancur lumat?\"", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 12, "text": "قَالُوا۟ تِلۡكَ إِذࣰا كَرَّةٌ خَاسِرَةࣱ ۝١٢", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "يقول هؤلاء المكذبون بالبعث: أنُرَدُّ بعد موتنا إلى ما كنا عليه أحياء في الأرض؟ أنردُّ وقد صرنا عظامًا بالية؟ قالوا: رجعتنا تلك ستكون إذًا خائبة كاذبة.", "isBasmala": false, "translation_en": "They say, \"This is a losing proposition.\"", "translation_id": "Mereka berkata: \"Kalau demikian, itu adalah suatu pengembalian yang merugikan\".", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 13, "text": "فَإِنَّمَا هِیَ زَجۡرَةࣱ وَ ٰحِدَةࣱ ۝١٣", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فإنما هي نفخة واحدة، فإذا هم أحياء على وجه الأرض بعد أن كانوا في بطنها.", "isBasmala": false, "translation_en": "But it will be only a single nudge.", "translation_id": "Sesungguhnya pengembalian itu hanyalah satu kali tiupan saja,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 14, "text": "فَإِذَا هُم بِٱلسَّاهِرَةِ ۝١٤", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فإنما هي نفخة واحدة، فإذا هم أحياء على وجه الأرض بعد أن كانوا في بطنها.", "isBasmala": false, "translation_en": "And they will be awake.", "translation_id": "maka dengan serta merta mereka hidup kembali di permukaan bumi.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 15, "text": "هَلۡ أَتَىٰكَ حَدِیثُ مُوسَىٰۤ ۝١٥", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "هل أتاك -أيها الرسول- خبر موسى؟", "isBasmala": false, "translation_en": "Has the story of Moses reached you?", "translation_id": "Sudah sampaikah kepadamu (ya Muhammad) kisah Musa.", "manzil": 7, "manzil_display": ""}], "584": [{"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 16, "text": "إِذۡ نَادَىٰهُ رَبُّهُۥ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوًى ۝١٦", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "حين ناداه ربه بالوادي المطهَّر المبارك \"طوى\"، فقال له: اذهب إلى فرعون، إنه قد أفرط في العصيان، فقل له: أتودُّ أن تطهِّر نفسك من النقائص وتحليها بالإيمان، وأُرشدك إلى طاعة ربك، فتخشاه وتتقيه؟", "isBasmala": false, "translation_en": "When His Lord called out to him in the sacred valley of Tuwa.", "translation_id": "Tatkala Tuhannya memanggilnya di lembah suci ialah Lembah Thuwa;", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 17, "text": "ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ ۝١٧", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "حين ناداه ربه بالوادي المطهَّر المبارك \"طوى\"، فقال له: اذهب إلى فرعون، إنه قد أفرط في العصيان، فقل له: أتودُّ أن تطهِّر نفسك من النقائص وتحليها بالإيمان، وأُرشدك إلى طاعة ربك، فتخشاه وتتقيه؟", "isBasmala": false, "translation_en": "\"Go to Pharaoh-he has transgressed.\"", "translation_id": "\"Pergilah kamu kepada Fir'aun, sesungguhnya dia telah melampaui batas,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 18, "text": "فَقُلۡ هَل لَّكَ إِلَىٰۤ أَن تَزَكَّىٰ ۝١٨", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "حين ناداه ربه بالوادي المطهَّر المبارك \"طوى\"، فقال له: اذهب إلى فرعون، إنه قد أفرط في العصيان، فقل له: أتودُّ أن تطهِّر نفسك من النقائص وتحليها بالإيمان، وأُرشدك إلى طاعة ربك، فتخشاه وتتقيه؟", "isBasmala": false, "translation_en": "And say, \"Do you care to be cleansed?", "translation_id": "dan katakanlah (kepada Fir'aun): \"Adakah keinginan bagimu untuk membersihkan diri (dari kesesatan)\".", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 19, "text": "وَأَهۡدِیَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ ۝١٩", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "حين ناداه ربه بالوادي المطهَّر المبارك \"طوى\"، فقال له: اذهب إلى فرعون، إنه قد أفرط في العصيان، فقل له: أتودُّ أن تطهِّر نفسك من النقائص وتحليها بالإيمان، وأُرشدك إلى طاعة ربك، فتخشاه وتتقيه؟", "isBasmala": false, "translation_en": "And I will guide you to your Lord, and you will turn reverent.\"", "translation_id": "Dan kamu akan kupimpin ke jalan Tuhanmu agar supaya kamu takut kepada-Nya?\"", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 20, "text": "فَأَرَىٰهُ ٱلۡـَٔایَةَ ٱلۡكُبۡرَىٰ ۝٢٠", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فأرى موسى فرعونَ العلامة العظمى: العصا واليد، فكذب فرعون نبيَّ الله موسى عليه السلام، وعصى ربه عزَّ وجلَّ، ثم ولَّى معرضًا عن الإيمان مجتهدًا في معارضة موسى.", "isBasmala": false, "translation_en": "He showed him the Greatest Miracle.", "translation_id": "Lalu Musa memperlihatkan kepadanya mukjizat yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 21, "text": "فَكَذَّبَ وَعَصَىٰ ۝٢١", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فأرى موسى فرعونَ العلامة العظمى: العصا واليد، فكذب فرعون نبيَّ الله موسى عليه السلام، وعصى ربه عزَّ وجلَّ، ثم ولَّى معرضًا عن الإيمان مجتهدًا في معارضة موسى.", "isBasmala": false, "translation_en": "But he denied and defied.", "translation_id": "Tetapi Fir'aun mendustakan dan mendurhakai.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 22, "text": "ثُمَّ أَدۡبَرَ یَسۡعَىٰ ۝٢٢", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فأرى موسى فرعونَ العلامة العظمى: العصا واليد، فكذب فرعون نبيَّ الله موسى عليه السلام، وعصى ربه عزَّ وجلَّ، ثم ولَّى معرضًا عن الإيمان مجتهدًا في معارضة موسى.", "isBasmala": false, "translation_en": "Then turned his back, and tried.", "translation_id": "Kemudian dia berpaling seraya berusaha menantang (Musa).", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 23, "text": "فَحَشَرَ فَنَادَىٰ ۝٢٣", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فجمع أهل مملكته وناداهم، فقال: أنا ربكم الذي لا ربَّ فوقه، فانتقم الله منه بالعذاب في الدنيا والآخرة، وجعله عبرة ونكالا لأمثاله من المتمردين. إن في فرعون وما نزل به من العذاب لموعظةً لمن يتعظ وينزجر.", "isBasmala": false, "translation_en": "And gathered and proclaimed.", "translation_id": "Maka dia mengumpulkan (pembesar-pembesarnya) lalu berseru memanggil kaumnya.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 24, "text": "فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ ۝٢٤", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فجمع أهل مملكته وناداهم، فقال: أنا ربكم الذي لا ربَّ فوقه، فانتقم الله منه بالعذاب في الدنيا والآخرة، وجعله عبرة ونكالا لأمثاله من المتمردين. إن في فرعون وما نزل به من العذاب لموعظةً لمن يتعظ وينزجر.", "isBasmala": false, "translation_en": "He said, \"I am your Lord, the most high.\"", "translation_id": "(Seraya) berkata: \"Akulah tuhanmu yang paling tinggi\".", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 25, "text": "فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلۡـَٔاخِرَةِ وَٱلۡأُولَىٰۤ ۝٢٥", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فجمع أهل مملكته وناداهم، فقال: أنا ربكم الذي لا ربَّ فوقه، فانتقم الله منه بالعذاب في الدنيا والآخرة، وجعله عبرة ونكالا لأمثاله من المتمردين. إن في فرعون وما نزل به من العذاب لموعظةً لمن يتعظ وينزجر.", "isBasmala": false, "translation_en": "So God seized him with an exemplary punishment, in the last and in the first.", "translation_id": "Maka Allah mengazabnya dengan azab di akhirat dan azab di dunia.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 26, "text": "إِنَّ فِی ذَ ٰلِكَ لَعِبۡرَةࣰ لِّمَن یَخۡشَىٰۤ ۝٢٦", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فجمع أهل مملكته وناداهم، فقال: أنا ربكم الذي لا ربَّ فوقه، فانتقم الله منه بالعذاب في الدنيا والآخرة، وجعله عبرة ونكالا لأمثاله من المتمردين. إن في فرعون وما نزل به من العذاب لموعظةً لمن يتعظ وينزجر.", "isBasmala": false, "translation_en": "In this is a lesson for whoever fears.", "translation_id": "Sesungguhnya pada yang demikian itu terdapat pelajaran bagi orang yang takut (kepada Tuhannya).", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 27, "text": "ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَاۤءُۚ بَنَىٰهَا ۝٢٧", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أبَعْثُكم أيها الناس- بعد الموت أشد في تقديركم أم خلق السماء؟ رفعها فوقكم كالبناء، وأعلى سقفها في الهواء لا تفاوت فيها ولا فطور، وأظلم ليلها بغروب شمسها، وأبرز نهارها بشروقها. والأرض بعد خلق السماء بسطها، وأودع فيها منافعها، وفجَّر فيها عيون الماء، وأنبت فيها ما يُرعى من النباتات، وأثبت فيها الجبال أوتادًا لها. خلق سبحانه كل هذه النعم منفعة لكم ولأنعامكم. (إن إعادة خلقكم يوم القيامة أهون على الله من خلق هذه الأشياء، وكله على الله هين يسير).", "isBasmala": false, "translation_en": "Are you more difficult to create, or the heaven? He constructed it.", "translation_id": "Apakah kamu lebih sulit penciptaanya ataukah langit? Allah telah membinanya,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 28, "text": "رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا ۝٢٨", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أبَعْثُكم أيها الناس- بعد الموت أشد في تقديركم أم خلق السماء؟ رفعها فوقكم كالبناء، وأعلى سقفها في الهواء لا تفاوت فيها ولا فطور، وأظلم ليلها بغروب شمسها، وأبرز نهارها بشروقها. والأرض بعد خلق السماء بسطها، وأودع فيها منافعها، وفجَّر فيها عيون الماء، وأنبت فيها ما يُرعى من النباتات، وأثبت فيها الجبال أوتادًا لها. خلق سبحانه كل هذه النعم منفعة لكم ولأنعامكم. (إن إعادة خلقكم يوم القيامة أهون على الله من خلق هذه الأشياء، وكله على الله هين يسير).", "isBasmala": false, "translation_en": "He raised its masses, and proportioned it.", "translation_id": "Dia meninggikan bangunannya lalu menyempurnakannya,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 29, "text": "وَأَغۡطَشَ لَیۡلَهَا وَأَخۡرَجَ ضُحَىٰهَا ۝٢٩", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أبَعْثُكم أيها الناس- بعد الموت أشد في تقديركم أم خلق السماء؟ رفعها فوقكم كالبناء، وأعلى سقفها في الهواء لا تفاوت فيها ولا فطور، وأظلم ليلها بغروب شمسها، وأبرز نهارها بشروقها. والأرض بعد خلق السماء بسطها، وأودع فيها منافعها، وفجَّر فيها عيون الماء، وأنبت فيها ما يُرعى من النباتات، وأثبت فيها الجبال أوتادًا لها. خلق سبحانه كل هذه النعم منفعة لكم ولأنعامكم. (إن إعادة خلقكم يوم القيامة أهون على الله من خلق هذه الأشياء، وكله على الله هين يسير).", "isBasmala": false, "translation_en": "And He dimmed its night, and brought out its daylight.", "translation_id": "dan Dia menjadikan malamnya gelap gulita, dan menjadikan siangnya terang benderang.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 30, "text": "وَٱلۡأَرۡضَ بَعۡدَ ذَ ٰلِكَ دَحَىٰهَاۤ ۝٣٠", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أبَعْثُكم أيها الناس- بعد الموت أشد في تقديركم أم خلق السماء؟ رفعها فوقكم كالبناء، وأعلى سقفها في الهواء لا تفاوت فيها ولا فطور، وأظلم ليلها بغروب شمسها، وأبرز نهارها بشروقها. والأرض بعد خلق السماء بسطها، وأودع فيها منافعها، وفجَّر فيها عيون الماء، وأنبت فيها ما يُرعى من النباتات، وأثبت فيها الجبال أوتادًا لها. خلق سبحانه كل هذه النعم منفعة لكم ولأنعامكم. (إن إعادة خلقكم يوم القيامة أهون على الله من خلق هذه الأشياء، وكله على الله هين يسير).", "isBasmala": false, "translation_en": "And the earth after that He spread.", "translation_id": "Dan bumi sesudah itu dihamparkan-Nya.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 31, "text": "أَخۡرَجَ مِنۡهَا مَاۤءَهَا وَمَرۡعَىٰهَا ۝٣١", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أبَعْثُكم أيها الناس- بعد الموت أشد في تقديركم أم خلق السماء؟ رفعها فوقكم كالبناء، وأعلى سقفها في الهواء لا تفاوت فيها ولا فطور، وأظلم ليلها بغروب شمسها، وأبرز نهارها بشروقها. والأرض بعد خلق السماء بسطها، وأودع فيها منافعها، وفجَّر فيها عيون الماء، وأنبت فيها ما يُرعى من النباتات، وأثبت فيها الجبال أوتادًا لها. خلق سبحانه كل هذه النعم منفعة لكم ولأنعامكم. (إن إعادة خلقكم يوم القيامة أهون على الله من خلق هذه الأشياء، وكله على الله هين يسير).", "isBasmala": false, "translation_en": "And from it, He produced its water and its pasture.", "translation_id": "Ia memancarkan daripadanya mata airnya, dan (menumbuhkan) tumbuh-tumbuhannya.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 32, "text": "وَٱلۡجِبَالَ أَرۡسَىٰهَا ۝٣٢", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أبَعْثُكم أيها الناس- بعد الموت أشد في تقديركم أم خلق السماء؟ رفعها فوقكم كالبناء، وأعلى سقفها في الهواء لا تفاوت فيها ولا فطور، وأظلم ليلها بغروب شمسها، وأبرز نهارها بشروقها. والأرض بعد خلق السماء بسطها، وأودع فيها منافعها، وفجَّر فيها عيون الماء، وأنبت فيها ما يُرعى من النباتات، وأثبت فيها الجبال أوتادًا لها. خلق سبحانه كل هذه النعم منفعة لكم ولأنعامكم. (إن إعادة خلقكم يوم القيامة أهون على الله من خلق هذه الأشياء، وكله على الله هين يسير).", "isBasmala": false, "translation_en": "And the mountains, He anchored.", "translation_id": "Dan gunung-gunung dipancangkan-Nya dengan teguh,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 33, "text": "مَتَـٰعࣰا لَّكُمۡ وَلِأَنۡعَـٰمِكُمۡ ۝٣٣", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "أبَعْثُكم أيها الناس- بعد الموت أشد في تقديركم أم خلق السماء؟ رفعها فوقكم كالبناء، وأعلى سقفها في الهواء لا تفاوت فيها ولا فطور، وأظلم ليلها بغروب شمسها، وأبرز نهارها بشروقها. والأرض بعد خلق السماء بسطها، وأودع فيها منافعها، وفجَّر فيها عيون الماء، وأنبت فيها ما يُرعى من النباتات، وأثبت فيها الجبال أوتادًا لها. خلق سبحانه كل هذه النعم منفعة لكم ولأنعامكم. (إن إعادة خلقكم يوم القيامة أهون على الله من خلق هذه الأشياء، وكله على الله هين يسير).", "isBasmala": false, "translation_en": "A source of enjoyment for you and for your animals.", "translation_id": "(semua itu) untuk kesenanganmu dan untuk binatang-binatang ternakmu.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 34, "text": "فَإِذَا جَاۤءَتِ ٱلطَّاۤمَّةُ ٱلۡكُبۡرَىٰ ۝٣٤", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فإذا جاءت القيامة الكبرى والشدة العظمى وهي النفخة الثانية، عندئذ يُعْرَض على الإنسان كل عمله من خير وشر، فيتذكره ويعترف به، وأُظهرت جهنم لكل مُبْصِر تُرى عِيانًا.", "isBasmala": false, "translation_en": "But when the Great Cataclysm arrives.", "translation_id": "Maka apabila malapetaka yang sangat besar (hari kiamat) telah datang.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 35, "text": "یَوۡمَ یَتَذَكَّرُ ٱلۡإِنسَـٰنُ مَا سَعَىٰ ۝٣٥", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فإذا جاءت القيامة الكبرى والشدة العظمى وهي النفخة الثانية، عندئذ يُعْرَض على الإنسان كل عمله من خير وشر، فيتذكره ويعترف به، وأُظهرت جهنم لكل مُبْصِر تُرى عِيانًا.", "isBasmala": false, "translation_en": "A Day when man will remember what he has endeavored.", "translation_id": "Pada hari (ketika) manusia teringat akan apa yang telah dikerjakannya,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 36, "text": "وَبُرِّزَتِ ٱلۡجَحِیمُ لِمَن یَرَىٰ ۝٣٦", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فإذا جاءت القيامة الكبرى والشدة العظمى وهي النفخة الثانية، عندئذ يُعْرَض على الإنسان كل عمله من خير وشر، فيتذكره ويعترف به، وأُظهرت جهنم لكل مُبْصِر تُرى عِيانًا.", "isBasmala": false, "translation_en": "And Hell will be displayed to whoever sees.", "translation_id": "dan diperlihatkan neraka dengan jelas kepada setiap orang yang melihat.", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 37, "text": "فَأَمَّا مَن طَغَىٰ ۝٣٧", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فأمَّا مَن تمرد على أمر الله، وفضل الحياة الدنيا على الآخرة، فإن مصيره إلى النار.", "isBasmala": false, "translation_en": "As for him who was defiant.", "translation_id": "Adapun orang yang melampaui batas,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 38, "text": "وَءَاثَرَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا ۝٣٨", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فأمَّا مَن تمرد على أمر الله، وفضل الحياة الدنيا على الآخرة، فإن مصيره إلى النار.", "isBasmala": false, "translation_en": "And preferred the life of this world.", "translation_id": "dan lebih mengutamakan kehidupan dunia,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 39, "text": "فَإِنَّ ٱلۡجَحِیمَ هِیَ ٱلۡمَأۡوَىٰ ۝٣٩", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "فأمَّا مَن تمرد على أمر الله، وفضل الحياة الدنيا على الآخرة، فإن مصيره إلى النار.", "isBasmala": false, "translation_en": "Then Hell is the shelter.", "translation_id": "maka sesungguhnya nerakalah tempat tinggal(nya).", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 40, "text": "وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ ۝٤٠", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وأمَّا مَنْ خاف القيام بين يدي الله للحساب، ونهى النفس عن الأهواء الفاسدة، فإن الجنة هي مسكنه.", "isBasmala": false, "translation_en": "But as for him who feared the Standing of his Lord, and restrained the self from desires.", "translation_id": "Dan adapun orang-orang yang takut kepada kebesaran Tuhannya dan menahan diri dari keinginan hawa nafsunya,", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 41, "text": "فَإِنَّ ٱلۡجَنَّةَ هِیَ ٱلۡمَأۡوَىٰ ۝٤١", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "وأمَّا مَنْ خاف القيام بين يدي الله للحساب، ونهى النفس عن الأهواء الفاسدة، فإن الجنة هي مسكنه.", "isBasmala": false, "translation_en": "Then Paradise is the shelter.", "translation_id": "maka sesungguhnya surgalah tempat tinggal(nya).", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 42, "text": "یَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَیَّانَ مُرۡسَىٰهَا ۝٤٢", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "يسألك المشركون أيها الرسول- استخفافا- عن وقت حلول الساعة التي تتوعدهم بها. لستَ في شيء مِن علمها، بل مرد ذلك إلى الله عز وجل، وإنما شأنك في أمر الساعة أن تحذر منها مَن يخافها. كأنهم يوم يرون قيام الساعة لم يلبثوا في الحياة الدنيا؛ لهول الساعة إلا ما بين الظهر إلى غروب الشمس، أو ما بين طلوع الشمس إلى نصف النهار.", "isBasmala": false, "translation_en": "They ask you about the Hour, \"When will it take place?\"", "translation_id": "(Orang-orang kafir) bertanya kepadamu (Muhammad) tentang hari kebangkitan, kapankah terjadinya?", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 43, "text": "فِیمَ أَنتَ مِن ذِكۡرَىٰهَاۤ ۝٤٣", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "يسألك المشركون أيها الرسول- استخفافا- عن وقت حلول الساعة التي تتوعدهم بها. لستَ في شيء مِن علمها، بل مرد ذلك إلى الله عز وجل، وإنما شأنك في أمر الساعة أن تحذر منها مَن يخافها. كأنهم يوم يرون قيام الساعة لم يلبثوا في الحياة الدنيا؛ لهول الساعة إلا ما بين الظهر إلى غروب الشمس، أو ما بين طلوع الشمس إلى نصف النهار.", "isBasmala": false, "translation_en": "You have no knowledge of it.", "translation_id": "Siapakah kamu (maka) dapat menyebutkan (waktunya)?", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 44, "text": "إِلَىٰ رَبِّكَ مُنتَهَىٰهَاۤ ۝٤٤", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "يسألك المشركون أيها الرسول- استخفافا- عن وقت حلول الساعة التي تتوعدهم بها. لستَ في شيء مِن علمها، بل مرد ذلك إلى الله عز وجل، وإنما شأنك في أمر الساعة أن تحذر منها مَن يخافها. كأنهم يوم يرون قيام الساعة لم يلبثوا في الحياة الدنيا؛ لهول الساعة إلا ما بين الظهر إلى غروب الشمس، أو ما بين طلوع الشمس إلى نصف النهار.", "isBasmala": false, "translation_en": "To your Lord is its finality.", "translation_id": "Kepada Tuhanmulah dikembalikan kesudahannya (ketentuan waktunya).", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 45, "text": "إِنَّمَاۤ أَنتَ مُنذِرُ مَن یَخۡشَىٰهَا ۝٤٥", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "يسألك المشركون أيها الرسول- استخفافا- عن وقت حلول الساعة التي تتوعدهم بها. لستَ في شيء مِن علمها، بل مرد ذلك إلى الله عز وجل، وإنما شأنك في أمر الساعة أن تحذر منها مَن يخافها. كأنهم يوم يرون قيام الساعة لم يلبثوا في الحياة الدنيا؛ لهول الساعة إلا ما بين الظهر إلى غروب الشمس، أو ما بين طلوع الشمس إلى نصف النهار.", "isBasmala": false, "translation_en": "You are just a warner for whoever dreads it.", "translation_id": "Kamu hanyalah pemberi peringatan bagi siapa yang takut kepadanya (hari berbangkit)", "manzil": 7, "manzil_display": ""}, {"sura": 79, "sura_name": "النازعات", "revelation": "Makkiyah", "aya": 46, "text": "كَأَنَّهُمۡ یَوۡمَ یَرَوۡنَهَا لَمۡ یَلۡبَثُوۤا۟ إِلَّا عَشِیَّةً أَوۡ ضُحَىٰهَا ۝٤٦", "juz": 30, "hizb": "(* ح 59*)", "tafsir": "يسألك المشركون أيها الرسول- استخفافا- عن وقت حلول الساعة التي تتوعدهم بها. لستَ في شيء مِن علمها، بل مرد ذلك إلى الله عز وجل، وإنما شأنك في أمر الساعة أن تحذر منها مَن يخافها. كأنهم يوم يرون قيام الساعة لم يلبثوا في الحياة الدنيا؛ لهول الساعة إلا ما بين الظهر إلى غروب الشمس، أو ما بين طلوع الشمس إلى نصف النهار.", "isBasmala": false, "translation_en": "On the Day when they witness it-as though they only stayed an evening, or its morning.", "translation_id": "Pada hari mereka melihat hari berbangkit itu, mereka merasa seakan-akan tidak tinggal (di dunia) melainkan (sebentar saja) di waktu sore atau pagi hari.", "manzil": 7, "manzil_display": ""}], "585": [{"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 1, "text": "۞ عَبَسَ وَتَوَلَّىٰۤ ۝١", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "ظهر التغير والعبوس في وجه الرسول صلى الله عليه وسلم، وأعرض لأجل أن الأعمى عبد الله بن أم مكتوم جاءه مسترشدا، وكان الرسول صلى الله عليه وسلم منشغلا بدعوة كبار قريش إلى الإسلام.", "isBasmala": false, "translation_en": "He frowned and turned away.", "translation_id": "Dia (Muhammad) bermuka masam dan berpaling,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 2, "text": "أَن جَاۤءَهُ ٱلۡأَعۡمَىٰ ۝٢", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "ظهر التغير والعبوس في وجه الرسول صلى الله عليه وسلم، وأعرض لأجل أن الأعمى عبد الله بن أم مكتوم جاءه مسترشدا، وكان الرسول صلى الله عليه وسلم منشغلا بدعوة كبار قريش إلى الإسلام.", "isBasmala": false, "translation_en": "When the blind man approached him.", "translation_id": "karena telah datang seorang buta kepadanya.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 3, "text": "وَمَا یُدۡرِیكَ لَعَلَّهُۥ یَزَّكَّىٰۤ ۝٣", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأيُّ شيء يجعلك عالمًا بحقيقة أمره؟ لعله بسؤاله تزكو نفسه وتطهر، أو يحصل له المزيد من الاعتبار والازدجار.", "isBasmala": false, "translation_en": "But how do you know? Perhaps he was seeking to purify himself.", "translation_id": "Tahukah kamu barangkali ia ingin membersihkan dirinya (dari dosa),", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 4, "text": "أَوۡ یَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰۤ ۝٤", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأيُّ شيء يجعلك عالمًا بحقيقة أمره؟ لعله بسؤاله تزكو نفسه وتطهر، أو يحصل له المزيد من الاعتبار والازدجار.", "isBasmala": false, "translation_en": "Or be reminded, and the message would benefit him.", "translation_id": "atau dia (ingin) mendapatkan pengajaran, lalu pengajaran itu memberi manfaat kepadanya?", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 5, "text": "أَمَّا مَنِ ٱسۡتَغۡنَىٰ ۝٥", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أما مَن استغنى عن هديك، فأنت تتعرض له وتصغي لكلامه، وأي شيء عليك ألا يتطهر من كفره؟", "isBasmala": false, "translation_en": "But as for him who was indifferent.", "translation_id": "Adapun orang yang merasa dirinya serba cukup,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 6, "text": "فَأَنتَ لَهُۥ تَصَدَّىٰ ۝٦", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أما مَن استغنى عن هديك، فأنت تتعرض له وتصغي لكلامه، وأي شيء عليك ألا يتطهر من كفره؟", "isBasmala": false, "translation_en": "You gave him your attention.", "translation_id": "maka kamu melayaninya.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 7, "text": "وَمَا عَلَیۡكَ أَلَّا یَزَّكَّىٰ ۝٧", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أما مَن استغنى عن هديك، فأنت تتعرض له وتصغي لكلامه، وأي شيء عليك ألا يتطهر من كفره؟", "isBasmala": false, "translation_en": "Though you are not liable if he does not purify himself.", "translation_id": "Padahal tidak ada (celaan) atasmu kalau dia tidak membersihkan diri (beriman).", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 8, "text": "وَأَمَّا مَن جَاۤءَكَ یَسۡعَىٰ ۝٨", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأمَّا من كان حريصا على لقائك، وهو يخشى الله من التقصير في الاسترشاد، فأنت عنه تتشاغل. ليس الأمر كما فعلت أيها الرسول، إن هذه السورة موعظة لك ولكل من شاء الاتعاظ. فمن شاء ذكر الله وَأْتَمَّ بوحيه. هذا الوحي، وهو القرآن في صحف معظمة، موقرة، عالية القدر مطهرة من الدنس والزيادة والنقص، بأيدي ملائكة كتبة، سفراء بين الله وخلقه، كرام الخلق، أخلاقهم وأفعالهم بارة طاهرة.", "isBasmala": false, "translation_en": "But as for him who came to you seeking.", "translation_id": "Dan adapun orang yang datang kepadamu dengan bersegera (untuk mendapatkan pengajaran),", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 9, "text": "وَهُوَ یَخۡشَىٰ ۝٩", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأمَّا من كان حريصا على لقائك، وهو يخشى الله من التقصير في الاسترشاد، فأنت عنه تتشاغل. ليس الأمر كما فعلت أيها الرسول، إن هذه السورة موعظة لك ولكل من شاء الاتعاظ. فمن شاء ذكر الله وَأْتَمَّ بوحيه. هذا الوحي، وهو القرآن في صحف معظمة، موقرة، عالية القدر مطهرة من الدنس والزيادة والنقص، بأيدي ملائكة كتبة، سفراء بين الله وخلقه، كرام الخلق، أخلاقهم وأفعالهم بارة طاهرة.", "isBasmala": false, "translation_en": "In awe.", "translation_id": "sedang ia takut kepada (Allah),", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 10, "text": "فَأَنتَ عَنۡهُ تَلَهَّىٰ ۝١٠", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأمَّا من كان حريصا على لقائك، وهو يخشى الله من التقصير في الاسترشاد، فأنت عنه تتشاغل. ليس الأمر كما فعلت أيها الرسول، إن هذه السورة موعظة لك ولكل من شاء الاتعاظ. فمن شاء ذكر الله وَأْتَمَّ بوحيه. هذا الوحي، وهو القرآن في صحف معظمة، موقرة، عالية القدر مطهرة من الدنس والزيادة والنقص، بأيدي ملائكة كتبة، سفراء بين الله وخلقه، كرام الخلق، أخلاقهم وأفعالهم بارة طاهرة.", "isBasmala": false, "translation_en": "To him you were inattentive.", "translation_id": "maka kamu mengabaikannya.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 11, "text": "كَلَّاۤ إِنَّهَا تَذۡكِرَةࣱ ۝١١", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأمَّا من كان حريصا على لقائك، وهو يخشى الله من التقصير في الاسترشاد، فأنت عنه تتشاغل. ليس الأمر كما فعلت أيها الرسول، إن هذه السورة موعظة لك ولكل من شاء الاتعاظ. فمن شاء ذكر الله وَأْتَمَّ بوحيه. هذا الوحي، وهو القرآن في صحف معظمة، موقرة، عالية القدر مطهرة من الدنس والزيادة والنقص، بأيدي ملائكة كتبة، سفراء بين الله وخلقه، كرام الخلق، أخلاقهم وأفعالهم بارة طاهرة.", "isBasmala": false, "translation_en": "Do not. This is a Lesson.", "translation_id": "Sekali-kali jangan (demikian)! Sesungguhnya ajaran-ajaran Tuhan itu adalah suatu peringatan,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 12, "text": "فَمَن شَاۤءَ ذَكَرَهُۥ ۝١٢", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأمَّا من كان حريصا على لقائك، وهو يخشى الله من التقصير في الاسترشاد، فأنت عنه تتشاغل. ليس الأمر كما فعلت أيها الرسول، إن هذه السورة موعظة لك ولكل من شاء الاتعاظ. فمن شاء ذكر الله وَأْتَمَّ بوحيه. هذا الوحي، وهو القرآن في صحف معظمة، موقرة، عالية القدر مطهرة من الدنس والزيادة والنقص، بأيدي ملائكة كتبة، سفراء بين الله وخلقه، كرام الخلق، أخلاقهم وأفعالهم بارة طاهرة.", "isBasmala": false, "translation_en": "Whoever wills, shall remember it.", "translation_id": "maka barangsiapa yang menghendaki, tentulah ia memperhatikannya,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 13, "text": "فِی صُحُفࣲ مُّكَرَّمَةࣲ ۝١٣", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأمَّا من كان حريصا على لقائك، وهو يخشى الله من التقصير في الاسترشاد، فأنت عنه تتشاغل. ليس الأمر كما فعلت أيها الرسول، إن هذه السورة موعظة لك ولكل من شاء الاتعاظ. فمن شاء ذكر الله وَأْتَمَّ بوحيه. هذا الوحي، وهو القرآن في صحف معظمة، موقرة، عالية القدر مطهرة من الدنس والزيادة والنقص، بأيدي ملائكة كتبة، سفراء بين الله وخلقه، كرام الخلق، أخلاقهم وأفعالهم بارة طاهرة.", "isBasmala": false, "translation_en": "On honorable pages.", "translation_id": "di dalam kitab-kitab yang dimuliakan,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 14, "text": "مَّرۡفُوعَةࣲ مُّطَهَّرَةِۭ ۝١٤", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأمَّا من كان حريصا على لقائك، وهو يخشى الله من التقصير في الاسترشاد، فأنت عنه تتشاغل. ليس الأمر كما فعلت أيها الرسول، إن هذه السورة موعظة لك ولكل من شاء الاتعاظ. فمن شاء ذكر الله وَأْتَمَّ بوحيه. هذا الوحي، وهو القرآن في صحف معظمة، موقرة، عالية القدر مطهرة من الدنس والزيادة والنقص، بأيدي ملائكة كتبة، سفراء بين الله وخلقه، كرام الخلق، أخلاقهم وأفعالهم بارة طاهرة.", "isBasmala": false, "translation_en": "Exalted and purified.", "translation_id": "yang ditinggikan lagi disucikan,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 15, "text": "بِأَیۡدِی سَفَرَةࣲ ۝١٥", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأمَّا من كان حريصا على لقائك، وهو يخشى الله من التقصير في الاسترشاد، فأنت عنه تتشاغل. ليس الأمر كما فعلت أيها الرسول، إن هذه السورة موعظة لك ولكل من شاء الاتعاظ. فمن شاء ذكر الله وَأْتَمَّ بوحيه. هذا الوحي، وهو القرآن في صحف معظمة، موقرة، عالية القدر مطهرة من الدنس والزيادة والنقص، بأيدي ملائكة كتبة، سفراء بين الله وخلقه، كرام الخلق، أخلاقهم وأفعالهم بارة طاهرة.", "isBasmala": false, "translation_en": "By the hands of scribes.", "translation_id": "di tangan para penulis (malaikat),", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 16, "text": "كِرَامِۭ بَرَرَةࣲ ۝١٦", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وأمَّا من كان حريصا على لقائك، وهو يخشى الله من التقصير في الاسترشاد، فأنت عنه تتشاغل. ليس الأمر كما فعلت أيها الرسول، إن هذه السورة موعظة لك ولكل من شاء الاتعاظ. فمن شاء ذكر الله وَأْتَمَّ بوحيه. هذا الوحي، وهو القرآن في صحف معظمة، موقرة، عالية القدر مطهرة من الدنس والزيادة والنقص، بأيدي ملائكة كتبة، سفراء بين الله وخلقه، كرام الخلق، أخلاقهم وأفعالهم بارة طاهرة.", "isBasmala": false, "translation_en": "Noble and devoted.", "translation_id": "yang mulia lagi berbakti.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 17, "text": "قُتِلَ ٱلۡإِنسَـٰنُ مَاۤ أَكۡفَرَهُۥ ۝١٧", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "لُعِنَ الإنسان الكافر وعُذِّب، ما أشدَّ كفره بربه!! ألم ير مِن أيِّ شيء خلقه الله أول مرة؟ خلقه الله من ماء قليل- وهو المَنِيُّ- فقدَّره أطوارا، ثم بين له طريق الخير والشر، ثم أماته فجعل له مكانًا يُقبر فيه، ثم إذا شاء سبحانه أحياه، وبعثه بعد موته للحساب والجزاء. ليس الأمر كما يقول الكافر ويفعل، فلم يُؤَدِّ ما أمره الله به من الإيمان والعمل بطاعته.", "isBasmala": false, "translation_en": "Perish man! How thankless he is!", "translation_id": "Binasalah manusia; alangkah amat sangat kekafirannya?", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 18, "text": "مِنۡ أَیِّ شَیۡءٍ خَلَقَهُۥ ۝١٨", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "لُعِنَ الإنسان الكافر وعُذِّب، ما أشدَّ كفره بربه!! ألم ير مِن أيِّ شيء خلقه الله أول مرة؟ خلقه الله من ماء قليل- وهو المَنِيُّ- فقدَّره أطوارا، ثم بين له طريق الخير والشر، ثم أماته فجعل له مكانًا يُقبر فيه، ثم إذا شاء سبحانه أحياه، وبعثه بعد موته للحساب والجزاء. ليس الأمر كما يقول الكافر ويفعل، فلم يُؤَدِّ ما أمره الله به من الإيمان والعمل بطاعته.", "isBasmala": false, "translation_en": "From what did He create him?", "translation_id": "Dari apakah Allah menciptakannya?", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 19, "text": "مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ ۝١٩", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "لُعِنَ الإنسان الكافر وعُذِّب، ما أشدَّ كفره بربه!! ألم ير مِن أيِّ شيء خلقه الله أول مرة؟ خلقه الله من ماء قليل- وهو المَنِيُّ- فقدَّره أطوارا، ثم بين له طريق الخير والشر، ثم أماته فجعل له مكانًا يُقبر فيه، ثم إذا شاء سبحانه أحياه، وبعثه بعد موته للحساب والجزاء. ليس الأمر كما يقول الكافر ويفعل، فلم يُؤَدِّ ما أمره الله به من الإيمان والعمل بطاعته.", "isBasmala": false, "translation_en": "From a sperm drop He created him, and enabled him.", "translation_id": "Dari setetes mani, Allah menciptakannya lalu menentukannya.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 20, "text": "ثُمَّ ٱلسَّبِیلَ یَسَّرَهُۥ ۝٢٠", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "لُعِنَ الإنسان الكافر وعُذِّب، ما أشدَّ كفره بربه!! ألم ير مِن أيِّ شيء خلقه الله أول مرة؟ خلقه الله من ماء قليل- وهو المَنِيُّ- فقدَّره أطوارا، ثم بين له طريق الخير والشر، ثم أماته فجعل له مكانًا يُقبر فيه، ثم إذا شاء سبحانه أحياه، وبعثه بعد موته للحساب والجزاء. ليس الأمر كما يقول الكافر ويفعل، فلم يُؤَدِّ ما أمره الله به من الإيمان والعمل بطاعته.", "isBasmala": false, "translation_en": "Then He eased the way for him.", "translation_id": "Kemudian Dia memudahkan jalannya.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 21, "text": "ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ ۝٢١", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "لُعِنَ الإنسان الكافر وعُذِّب، ما أشدَّ كفره بربه!! ألم ير مِن أيِّ شيء خلقه الله أول مرة؟ خلقه الله من ماء قليل- وهو المَنِيُّ- فقدَّره أطوارا، ثم بين له طريق الخير والشر، ثم أماته فجعل له مكانًا يُقبر فيه، ثم إذا شاء سبحانه أحياه، وبعثه بعد موته للحساب والجزاء. ليس الأمر كما يقول الكافر ويفعل، فلم يُؤَدِّ ما أمره الله به من الإيمان والعمل بطاعته.", "isBasmala": false, "translation_en": "Then He puts him to death, and buries him.", "translation_id": "kemudian Dia mematikannya dan memasukkannya ke dalam kubur,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 22, "text": "ثُمَّ إِذَا شَاۤءَ أَنشَرَهُۥ ۝٢٢", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "لُعِنَ الإنسان الكافر وعُذِّب، ما أشدَّ كفره بربه!! ألم ير مِن أيِّ شيء خلقه الله أول مرة؟ خلقه الله من ماء قليل- وهو المَنِيُّ- فقدَّره أطوارا، ثم بين له طريق الخير والشر، ثم أماته فجعل له مكانًا يُقبر فيه، ثم إذا شاء سبحانه أحياه، وبعثه بعد موته للحساب والجزاء. ليس الأمر كما يقول الكافر ويفعل، فلم يُؤَدِّ ما أمره الله به من الإيمان والعمل بطاعته.", "isBasmala": false, "translation_en": "Then, when He wills, He will resurrect him.", "translation_id": "kemudian bila Dia menghendaki, Dia membangkitkannya kembali.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 23, "text": "كَلَّا لَمَّا یَقۡضِ مَاۤ أَمَرَهُۥ ۝٢٣", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "لُعِنَ الإنسان الكافر وعُذِّب، ما أشدَّ كفره بربه!! ألم ير مِن أيِّ شيء خلقه الله أول مرة؟ خلقه الله من ماء قليل- وهو المَنِيُّ- فقدَّره أطوارا، ثم بين له طريق الخير والشر، ثم أماته فجعل له مكانًا يُقبر فيه، ثم إذا شاء سبحانه أحياه، وبعثه بعد موته للحساب والجزاء. ليس الأمر كما يقول الكافر ويفعل، فلم يُؤَدِّ ما أمره الله به من الإيمان والعمل بطاعته.", "isBasmala": false, "translation_en": "But no, he did not fulfill what He has commanded him.", "translation_id": "Sekali-kali jangan; manusia itu belum melaksanakan apa yang diperintahkan Allah kepadanya,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 24, "text": "فَلۡیَنظُرِ ٱلۡإِنسَـٰنُ إِلَىٰ طَعَامِهِۦۤ ۝٢٤", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فليتدبر الإنسان: كيف خلق الله طعامه الذي هو قوام حياته؟ أنَّا صببنا الماء على الأرض صَبًّا، ثم شققناها بما أخرجنا منها من نبات شتى، فأنبتنا فيها حبًا، وعنبًا وعلفًا للدواب، وزيتونًا ونخلا وحدائق عظيمة الأشجار، وثمارًا وكلأ تَنْعَمون بها أنتم وأنعامكم.", "isBasmala": false, "translation_en": "Let man consider his food.", "translation_id": "maka hendaklah manusia itu memperhatikan makanannya.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 25, "text": "أَنَّا صَبَبۡنَا ٱلۡمَاۤءَ صَبࣰّا ۝٢٥", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فليتدبر الإنسان: كيف خلق الله طعامه الذي هو قوام حياته؟ أنَّا صببنا الماء على الأرض صَبًّا، ثم شققناها بما أخرجنا منها من نبات شتى، فأنبتنا فيها حبًا، وعنبًا وعلفًا للدواب، وزيتونًا ونخلا وحدائق عظيمة الأشجار، وثمارًا وكلأ تَنْعَمون بها أنتم وأنعامكم.", "isBasmala": false, "translation_en": "We pour down water in abundance.", "translation_id": "Sesungguhnya Kami benar-benar telah mencurahkan air (dari langit),", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 26, "text": "ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ شَقࣰّا ۝٢٦", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فليتدبر الإنسان: كيف خلق الله طعامه الذي هو قوام حياته؟ أنَّا صببنا الماء على الأرض صَبًّا، ثم شققناها بما أخرجنا منها من نبات شتى، فأنبتنا فيها حبًا، وعنبًا وعلفًا للدواب، وزيتونًا ونخلا وحدائق عظيمة الأشجار، وثمارًا وكلأ تَنْعَمون بها أنتم وأنعامكم.", "isBasmala": false, "translation_en": "Then crack the soil open.", "translation_id": "kemudian Kami belah bumi dengan sebaik-baiknya,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 27, "text": "فَأَنۢبَتۡنَا فِیهَا حَبࣰّا ۝٢٧", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فليتدبر الإنسان: كيف خلق الله طعامه الذي هو قوام حياته؟ أنَّا صببنا الماء على الأرض صَبًّا، ثم شققناها بما أخرجنا منها من نبات شتى، فأنبتنا فيها حبًا، وعنبًا وعلفًا للدواب، وزيتونًا ونخلا وحدائق عظيمة الأشجار، وثمارًا وكلأ تَنْعَمون بها أنتم وأنعامكم.", "isBasmala": false, "translation_en": "And grow in it grains.", "translation_id": "lalu Kami tumbuhkan biji-bijian di bumi itu,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 28, "text": "وَعِنَبࣰا وَقَضۡبࣰا ۝٢٨", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فليتدبر الإنسان: كيف خلق الله طعامه الذي هو قوام حياته؟ أنَّا صببنا الماء على الأرض صَبًّا، ثم شققناها بما أخرجنا منها من نبات شتى، فأنبتنا فيها حبًا، وعنبًا وعلفًا للدواب، وزيتونًا ونخلا وحدائق عظيمة الأشجار، وثمارًا وكلأ تَنْعَمون بها أنتم وأنعامكم.", "isBasmala": false, "translation_en": "And grapes and herbs.", "translation_id": "anggur dan sayur-sayuran,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 29, "text": "وَزَیۡتُونࣰا وَنَخۡلࣰا ۝٢٩", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فليتدبر الإنسان: كيف خلق الله طعامه الذي هو قوام حياته؟ أنَّا صببنا الماء على الأرض صَبًّا، ثم شققناها بما أخرجنا منها من نبات شتى، فأنبتنا فيها حبًا، وعنبًا وعلفًا للدواب، وزيتونًا ونخلا وحدائق عظيمة الأشجار، وثمارًا وكلأ تَنْعَمون بها أنتم وأنعامكم.", "isBasmala": false, "translation_en": "And olives and dates.", "translation_id": "zaitun dan kurma,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 30, "text": "وَحَدَاۤىِٕقَ غُلۡبࣰا ۝٣٠", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فليتدبر الإنسان: كيف خلق الله طعامه الذي هو قوام حياته؟ أنَّا صببنا الماء على الأرض صَبًّا، ثم شققناها بما أخرجنا منها من نبات شتى، فأنبتنا فيها حبًا، وعنبًا وعلفًا للدواب، وزيتونًا ونخلا وحدائق عظيمة الأشجار، وثمارًا وكلأ تَنْعَمون بها أنتم وأنعامكم.", "isBasmala": false, "translation_en": "And luscious gardens.", "translation_id": "kebun-kebun (yang) lebat,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 31, "text": "وَفَـٰكِهَةࣰ وَأَبࣰّا ۝٣١", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فليتدبر الإنسان: كيف خلق الله طعامه الذي هو قوام حياته؟ أنَّا صببنا الماء على الأرض صَبًّا، ثم شققناها بما أخرجنا منها من نبات شتى، فأنبتنا فيها حبًا، وعنبًا وعلفًا للدواب، وزيتونًا ونخلا وحدائق عظيمة الأشجار، وثمارًا وكلأ تَنْعَمون بها أنتم وأنعامكم.", "isBasmala": false, "translation_en": "And fruits and vegetables.", "translation_id": "dan buah-buahan serta rumput-rumputan,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 32, "text": "مَّتَـٰعࣰا لَّكُمۡ وَلِأَنۡعَـٰمِكُمۡ ۝٣٢", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فليتدبر الإنسان: كيف خلق الله طعامه الذي هو قوام حياته؟ أنَّا صببنا الماء على الأرض صَبًّا، ثم شققناها بما أخرجنا منها من نبات شتى، فأنبتنا فيها حبًا، وعنبًا وعلفًا للدواب، وزيتونًا ونخلا وحدائق عظيمة الأشجار، وثمارًا وكلأ تَنْعَمون بها أنتم وأنعامكم.", "isBasmala": false, "translation_en": "Enjoyment for you, and for your livestock.", "translation_id": "untuk kesenanganmu dan untuk binatang-binatang ternakmu.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 33, "text": "فَإِذَا جَاۤءَتِ ٱلصَّاۤخَّةُ ۝٣٣", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فإذا جاءت صيحة يوم القيامة التي تصمُّ مِن هولها الأسماع، يوم يفرُّ المرء لهول ذلك اليوم من أخيه، وأمه وأبيه، وزوجه وبنيه. لكل واحد منهم يومئذٍ أمر يشغله ويمنعه من الانشغال بغيره.", "isBasmala": false, "translation_en": "But when the Deafening Noise comes to pass.", "translation_id": "Dan apabila datang suara yang memekakkan (tiupan sangkakala yang kedua),", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 34, "text": "یَوۡمَ یَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِیهِ ۝٣٤", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فإذا جاءت صيحة يوم القيامة التي تصمُّ مِن هولها الأسماع، يوم يفرُّ المرء لهول ذلك اليوم من أخيه، وأمه وأبيه، وزوجه وبنيه. لكل واحد منهم يومئذٍ أمر يشغله ويمنعه من الانشغال بغيره.", "isBasmala": false, "translation_en": "The Day when a person will flee from his brother.", "translation_id": "pada hari ketika manusia lari dari saudaranya,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 35, "text": "وَأُمِّهِۦ وَأَبِیهِ ۝٣٥", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فإذا جاءت صيحة يوم القيامة التي تصمُّ مِن هولها الأسماع، يوم يفرُّ المرء لهول ذلك اليوم من أخيه، وأمه وأبيه، وزوجه وبنيه. لكل واحد منهم يومئذٍ أمر يشغله ويمنعه من الانشغال بغيره.", "isBasmala": false, "translation_en": "And his mother and his father.", "translation_id": "dari ibu dan bapaknya,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 36, "text": "وَصَـٰحِبَتِهِۦ وَبَنِیهِ ۝٣٦", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فإذا جاءت صيحة يوم القيامة التي تصمُّ مِن هولها الأسماع، يوم يفرُّ المرء لهول ذلك اليوم من أخيه، وأمه وأبيه، وزوجه وبنيه. لكل واحد منهم يومئذٍ أمر يشغله ويمنعه من الانشغال بغيره.", "isBasmala": false, "translation_en": "And his consort and his children.", "translation_id": "dari istri dan anak-anaknya.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 37, "text": "لِكُلِّ ٱمۡرِىࣲٕ مِّنۡهُمۡ یَوۡمَىِٕذࣲ شَأۡنࣱ یُغۡنِیهِ ۝٣٧", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فإذا جاءت صيحة يوم القيامة التي تصمُّ مِن هولها الأسماع، يوم يفرُّ المرء لهول ذلك اليوم من أخيه، وأمه وأبيه، وزوجه وبنيه. لكل واحد منهم يومئذٍ أمر يشغله ويمنعه من الانشغال بغيره.", "isBasmala": false, "translation_en": "Every one of them, on that Day, will have enough to preoccupy him.", "translation_id": "Setiap orang dari mereka pada hari itu mempunyai urusan yang cukup menyibukkannya.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 38, "text": "وُجُوهࣱ یَوۡمَىِٕذࣲ مُّسۡفِرَةࣱ ۝٣٨", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وجوه أهل النعيم في ذلك اليوم مستنيرة، مسرورة فرحة، ووجوه أهل الجحيم مظلمة مسودَّة، تغشاها ذلَّة. أولئك الموصوفون بهذا الوصف هم الذين كفروا بنعم الله وكذَّبوا بآياته، وتجرؤوا على محارمه بالفجور والطغيان.", "isBasmala": false, "translation_en": "Faces on that Day will be radiant.", "translation_id": "Banyak muka pada hari itu berseri-seri,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 39, "text": "ضَاحِكَةࣱ مُّسۡتَبۡشِرَةࣱ ۝٣٩", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وجوه أهل النعيم في ذلك اليوم مستنيرة، مسرورة فرحة، ووجوه أهل الجحيم مظلمة مسودَّة، تغشاها ذلَّة. أولئك الموصوفون بهذا الوصف هم الذين كفروا بنعم الله وكذَّبوا بآياته، وتجرؤوا على محارمه بالفجور والطغيان.", "isBasmala": false, "translation_en": "Laughing and rejoicing.", "translation_id": "tertawa dan bergembira ria,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 40, "text": "وَوُجُوهࣱ یَوۡمَىِٕذٍ عَلَیۡهَا غَبَرَةࣱ ۝٤٠", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وجوه أهل النعيم في ذلك اليوم مستنيرة، مسرورة فرحة، ووجوه أهل الجحيم مظلمة مسودَّة، تغشاها ذلَّة. أولئك الموصوفون بهذا الوصف هم الذين كفروا بنعم الله وكذَّبوا بآياته، وتجرؤوا على محارمه بالفجور والطغيان.", "isBasmala": false, "translation_en": "And Faces on that Day will be covered with misery.", "translation_id": "dan banyak (pula) muka pada hari itu tertutup debu,", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 41, "text": "تَرۡهَقُهَا قَتَرَةٌ ۝٤١", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وجوه أهل النعيم في ذلك اليوم مستنيرة، مسرورة فرحة، ووجوه أهل الجحيم مظلمة مسودَّة، تغشاها ذلَّة. أولئك الموصوفون بهذا الوصف هم الذين كفروا بنعم الله وكذَّبوا بآياته، وتجرؤوا على محارمه بالفجور والطغيان.", "isBasmala": false, "translation_en": "Overwhelmed by remorse.", "translation_id": "dan ditutup lagi oleh kegelapan.", "manzil": 7, "manzil_display": ""}, {"sura": 80, "sura_name": "عبس", "revelation": "Makkiyah", "aya": 42, "text": "أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ ۝٤٢", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وجوه أهل النعيم في ذلك اليوم مستنيرة، مسرورة فرحة، ووجوه أهل الجحيم مظلمة مسودَّة، تغشاها ذلَّة. أولئك الموصوفون بهذا الوصف هم الذين كفروا بنعم الله وكذَّبوا بآياته، وتجرؤوا على محارمه بالفجور والطغيان.", "isBasmala": false, "translation_en": "These are the faithless, the vicious.", "translation_id": "Mereka itulah orang-orang kafir lagi durhaka.", "manzil": 7, "manzil_display": ""}], "586": [{"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 1, "text": "إِذَا ٱلشَّمۡسُ كُوِّرَتۡ ۝١", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the sun is rolled up.", "translation_id": "Apabila matahari digulung,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 2, "text": "وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ ۝٢", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the stars are dimmed.", "translation_id": "dan apabila bintang-bintang berjatuhan,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 3, "text": "وَإِذَا ٱلۡجِبَالُ سُیِّرَتۡ ۝٣", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the mountains are set in motion.", "translation_id": "dan apabila gunung-gunung dihancurkan,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 4, "text": "وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ ۝٤", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the relationships are suspended.", "translation_id": "dan apabila unta-unta yang bunting ditinggalkan (tidak diperdulikan)", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 5, "text": "وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ ۝٥", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the beasts are gathered.", "translation_id": "dan apabila binatang-binatang liar dikumpulkan,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 6, "text": "وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ ۝٦", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the oceans are set aflame.", "translation_id": "dan apabila lautan dijadikan meluap", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 7, "text": "وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ ۝٧", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the souls are paired.", "translation_id": "dan apabila ruh-ruh dipertemukan (dengan tubuh)", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 8, "text": "وَإِذَا ٱلۡمَوۡءُۥدَةُ سُىِٕلَتۡ ۝٨", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the girl, buried alive, is asked:", "translation_id": "dan apabila bayi-bayi perempuan yang dikubur hidup-hidup ditanya,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 9, "text": "بِأَیِّ ذَنۢبࣲ قُتِلَتۡ ۝٩", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "For what crime was she killed?", "translation_id": "karena dosa apakah dia dibunuh,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 10, "text": "وَإِذَا ٱلصُّحُفُ نُشِرَتۡ ۝١٠", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the records are made public.", "translation_id": "dan apabila catatan-catatan (amal perbuatan manusia) dibuka,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 11, "text": "وَإِذَا ٱلسَّمَاۤءُ كُشِطَتۡ ۝١١", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the sky is peeled away.", "translation_id": "dan apabila langit dilenyapkan,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 12, "text": "وَإِذَا ٱلۡجَحِیمُ سُعِّرَتۡ ۝١٢", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When the Fire is set ablaze.", "translation_id": "dan apabila neraka Jahim dinyalakan,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 13, "text": "وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ ۝١٣", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "When Paradise is brought near.", "translation_id": "dan apabila surga didekatkan,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 14, "text": "عَلِمَتۡ نَفۡسࣱ مَّاۤ أَحۡضَرَتۡ ۝١٤", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "إذا الشمس لُفَّت وذهب ضَوْءُها، وإذا النجوم تناثرت، فذهب نورها، وإذا الجبال سيِّرت عن وجه الأرض فصارت هباءً منبثًا، وإذا النوق الحوامل تُركت وأهملت، وإذا الحيوانات الوحشية جُمعت واختلطت؛ ليقتصَّ الله من بعضها لبعض، وإذا البحار أوقدت، فصارت على عِظَمها نارًا تتوقد، وإذا النفوس قُرنت بأمثالها ونظائرها، وإذا الطفلة المدفونة حية سُئلت يوم القيامة سؤالَ تطييب لها وتبكيت لوائدها: بأيِّ ذنب كان دفنها؟ وإذا صحف الأعمال عُرضت، وإذا السماء قُلعت وأزيلت من مكانها، وإذا النار أوقدت فأضرِمت، وإذا الجنة دار النعيم قُرِّبت من أهلها المتقين، إذا وقع ذلك، تيقنتْ ووجدتْ كلُّ نفس ما قدَّمت من خير أو شر.", "isBasmala": false, "translation_en": "Each soul will know what it has readied.", "translation_id": "maka tiap-tiap jiwa akan mengetahui apa yang telah dikerjakannya.", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 15, "text": "فَلَاۤ أُقۡسِمُ بِٱلۡخُنَّسِ ۝١٥", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أقسم الله تعالى بالنجوم المختفية أنوارها نهارًا، الجارية والمستترة في أبراجها، والليل إذا أقبل بظلامه، والصبح إذا ظهر ضياؤه، إن القرآن لَتبليغ رسول كريم- هو جبريل عليه السلام-، ذِي قوة في تنفيذ ما يؤمر به، صاحبِ مكانة رفيعة عند الله، تطيعه الملائكة، مؤتمن على الوحي الذي ينزل به.", "isBasmala": false, "translation_en": "I swear by the galaxies.", "translation_id": "Sungguh, Aku bersumpah dengan bintang-bintang,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 16, "text": "ٱلۡجَوَارِ ٱلۡكُنَّسِ ۝١٦", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أقسم الله تعالى بالنجوم المختفية أنوارها نهارًا، الجارية والمستترة في أبراجها، والليل إذا أقبل بظلامه، والصبح إذا ظهر ضياؤه، إن القرآن لَتبليغ رسول كريم- هو جبريل عليه السلام-، ذِي قوة في تنفيذ ما يؤمر به، صاحبِ مكانة رفيعة عند الله، تطيعه الملائكة، مؤتمن على الوحي الذي ينزل به.", "isBasmala": false, "translation_en": "Precisely running their courses.", "translation_id": "yang beredar dan terbenam,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 17, "text": "وَٱلَّیۡلِ إِذَا عَسۡعَسَ ۝١٧", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أقسم الله تعالى بالنجوم المختفية أنوارها نهارًا، الجارية والمستترة في أبراجها، والليل إذا أقبل بظلامه، والصبح إذا ظهر ضياؤه، إن القرآن لَتبليغ رسول كريم- هو جبريل عليه السلام-، ذِي قوة في تنفيذ ما يؤمر به، صاحبِ مكانة رفيعة عند الله، تطيعه الملائكة، مؤتمن على الوحي الذي ينزل به.", "isBasmala": false, "translation_en": "And by the night as it recedes.", "translation_id": "demi malam apabila telah hampir meninggalkan gelapnya,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 18, "text": "وَٱلصُّبۡحِ إِذَا تَنَفَّسَ ۝١٨", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أقسم الله تعالى بالنجوم المختفية أنوارها نهارًا، الجارية والمستترة في أبراجها، والليل إذا أقبل بظلامه، والصبح إذا ظهر ضياؤه، إن القرآن لَتبليغ رسول كريم- هو جبريل عليه السلام-، ذِي قوة في تنفيذ ما يؤمر به، صاحبِ مكانة رفيعة عند الله، تطيعه الملائكة، مؤتمن على الوحي الذي ينزل به.", "isBasmala": false, "translation_en": "And by the morn as it breathes.", "translation_id": "dan demi subuh apabila fajarnya mulai menyingsing,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 19, "text": "إِنَّهُۥ لَقَوۡلُ رَسُولࣲ كَرِیمࣲ ۝١٩", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أقسم الله تعالى بالنجوم المختفية أنوارها نهارًا، الجارية والمستترة في أبراجها، والليل إذا أقبل بظلامه، والصبح إذا ظهر ضياؤه، إن القرآن لَتبليغ رسول كريم- هو جبريل عليه السلام-، ذِي قوة في تنفيذ ما يؤمر به، صاحبِ مكانة رفيعة عند الله، تطيعه الملائكة، مؤتمن على الوحي الذي ينزل به.", "isBasmala": false, "translation_en": "This is the speech of a noble messenger.", "translation_id": "sesungguhnya Al Quran itu benar-benar firman (Allah yang dibawa oleh) utusan yang mulia (Jibril),", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 20, "text": "ذِی قُوَّةٍ عِندَ ذِی ٱلۡعَرۡشِ مَكِینࣲ ۝٢٠", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أقسم الله تعالى بالنجوم المختفية أنوارها نهارًا، الجارية والمستترة في أبراجها، والليل إذا أقبل بظلامه، والصبح إذا ظهر ضياؤه، إن القرآن لَتبليغ رسول كريم- هو جبريل عليه السلام-، ذِي قوة في تنفيذ ما يؤمر به، صاحبِ مكانة رفيعة عند الله، تطيعه الملائكة، مؤتمن على الوحي الذي ينزل به.", "isBasmala": false, "translation_en": "Endowed with power, eminent with the Lord of the Throne.", "translation_id": "yang mempunyai kekuatan, yang mempunyai kedudukan tinggi di sisi Allah yang mempunyai 'Arsy,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 21, "text": "مُّطَاعࣲ ثَمَّ أَمِینࣲ ۝٢١", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "أقسم الله تعالى بالنجوم المختفية أنوارها نهارًا، الجارية والمستترة في أبراجها، والليل إذا أقبل بظلامه، والصبح إذا ظهر ضياؤه، إن القرآن لَتبليغ رسول كريم- هو جبريل عليه السلام-، ذِي قوة في تنفيذ ما يؤمر به، صاحبِ مكانة رفيعة عند الله، تطيعه الملائكة، مؤتمن على الوحي الذي ينزل به.", "isBasmala": false, "translation_en": "Obeyed and honest.", "translation_id": "yang ditaati di sana (di alam malaikat) lagi dipercaya.", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 22, "text": "وَمَا صَاحِبُكُم بِمَجۡنُونࣲ ۝٢٢", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وما محمد الذي تعرفونه بمجنون، ولقد رأى محمد جبريل الذي يأتيه بالرسالة في الأفق العظيم، وما هو ببخيل في تبليغ الوحي. وما هذا القرآن بقول شيطان رجيم، مطرود من رحمة الله، ولكنه كلام الله ووحيه.", "isBasmala": false, "translation_en": "Your friend is not possessed.", "translation_id": "Dan temanmu (Muhammad) itu bukanlah sekali-kali orang yang gila.", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 23, "text": "وَلَقَدۡ رَءَاهُ بِٱلۡأُفُقِ ٱلۡمُبِینِ ۝٢٣", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وما محمد الذي تعرفونه بمجنون، ولقد رأى محمد جبريل الذي يأتيه بالرسالة في الأفق العظيم، وما هو ببخيل في تبليغ الوحي. وما هذا القرآن بقول شيطان رجيم، مطرود من رحمة الله، ولكنه كلام الله ووحيه.", "isBasmala": false, "translation_en": "He saw him on the luminous horizon.", "translation_id": "Dan sesungguhnya Muhammad itu melihat Jibril di ufuk yang terang.", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 24, "text": "وَمَا هُوَ عَلَى ٱلۡغَیۡبِ بِضَنِینࣲ ۝٢٤", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وما محمد الذي تعرفونه بمجنون، ولقد رأى محمد جبريل الذي يأتيه بالرسالة في الأفق العظيم، وما هو ببخيل في تبليغ الوحي. وما هذا القرآن بقول شيطان رجيم، مطرود من رحمة الله، ولكنه كلام الله ووحيه.", "isBasmala": false, "translation_en": "And He does not withhold knowledge of the Unseen.", "translation_id": "Dan dia (Muhammad) bukanlah orang yang bakhil untuk menerangkan yang ghaib.", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 25, "text": "وَمَا هُوَ بِقَوۡلِ شَیۡطَـٰنࣲ رَّجِیمࣲ ۝٢٥", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "وما محمد الذي تعرفونه بمجنون، ولقد رأى محمد جبريل الذي يأتيه بالرسالة في الأفق العظيم، وما هو ببخيل في تبليغ الوحي. وما هذا القرآن بقول شيطان رجيم، مطرود من رحمة الله، ولكنه كلام الله ووحيه.", "isBasmala": false, "translation_en": "And it is not the word of an accursed devil.", "translation_id": "Dan Al Quran itu bukanlah perkataan syaitan yang terkutuk,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 26, "text": "فَأَیۡنَ تَذۡهَبُونَ ۝٢٦", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فأين تذهب بكم عقولكم في التكذيب بالقرآن بعد هذه الحجج القاطعة؟ ما هو إلا موعظة من الله لجميع الناس، لمن شاء منكم أن يستقيم على الحق والإيمان، وما تشاؤون الاستقامة، ولا تقدرون على ذلك، إلا بمشيئة الله رب الخلائق أجمعين.", "isBasmala": false, "translation_en": "So where are you heading?", "translation_id": "maka ke manakah kamu akan pergi?", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 27, "text": "إِنۡ هُوَ إِلَّا ذِكۡرࣱ لِّلۡعَـٰلَمِینَ ۝٢٧", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فأين تذهب بكم عقولكم في التكذيب بالقرآن بعد هذه الحجج القاطعة؟ ما هو إلا موعظة من الله لجميع الناس، لمن شاء منكم أن يستقيم على الحق والإيمان، وما تشاؤون الاستقامة، ولا تقدرون على ذلك، إلا بمشيئة الله رب الخلائق أجمعين.", "isBasmala": false, "translation_en": "It is only a Reminder to all mankind.", "translation_id": "Al Quran itu tiada lain hanyalah peringatan bagi semesta alam,", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 28, "text": "لِمَن شَاۤءَ مِنكُمۡ أَن یَسۡتَقِیمَ ۝٢٨", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فأين تذهب بكم عقولكم في التكذيب بالقرآن بعد هذه الحجج القاطعة؟ ما هو إلا موعظة من الله لجميع الناس، لمن شاء منكم أن يستقيم على الحق والإيمان، وما تشاؤون الاستقامة، ولا تقدرون على ذلك، إلا بمشيئة الله رب الخلائق أجمعين.", "isBasmala": false, "translation_en": "To whoever of you wills to go straight.", "translation_id": "(yaitu) bagi siapa di antara kamu yang mau menempuh jalan yang lurus.", "manzil": 7, "manzil_display": ""}, {"sura": 81, "sura_name": "التكوير", "revelation": "Makkiyah", "aya": 29, "text": "وَمَا تَشَاۤءُونَ إِلَّاۤ أَن یَشَاۤءَ ٱللَّهُ رَبُّ ٱلۡعَـٰلَمِینَ ۝٢٩", "juz": 30, "hizb": "(*¼ ح 59*)", "tafsir": "فأين تذهب بكم عقولكم في التكذيب بالقرآن بعد هذه الحجج القاطعة؟ ما هو إلا موعظة من الله لجميع الناس، لمن شاء منكم أن يستقيم على الحق والإيمان، وما تشاؤون الاستقامة، ولا تقدرون على ذلك، إلا بمشيئة الله رب الخلائق أجمعين.", "isBasmala": false, "translation_en": "But you cannot will, unless God wills-The Lord of the Worlds.", "translation_id": "Dan kamu tidak dapat menghendaki (menempuh jalan itu) kecuali apabila dikehendaki Allah, Tuhan semesta alam.", "manzil": 7, "manzil_display": ""}], "587": [{"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 1, "text": "۞ إِذَا ٱلسَّمَاۤءُ ٱنفَطَرَتۡ ۝١", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إذا السماء انشقت، واختلَّ نظامها، وإذا الكواكب تساقطت، وإذا البحار فجَّر الله بعضها في بعض، فذهب ماؤها، وإذا القبور قُلِبت ببعث مَن كان فيها، حينئذ تعلم كلُّ نفس جميع أعمالها، ما تقدَّم منها، وما تأخر، وجوزيت بها.", "isBasmala": false, "translation_en": "When the sky breaks apart.", "translation_id": "Apabila langit terbelah,", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 2, "text": "وَإِذَا ٱلۡكَوَاكِبُ ٱنتَثَرَتۡ ۝٢", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إذا السماء انشقت، واختلَّ نظامها، وإذا الكواكب تساقطت، وإذا البحار فجَّر الله بعضها في بعض، فذهب ماؤها، وإذا القبور قُلِبت ببعث مَن كان فيها، حينئذ تعلم كلُّ نفس جميع أعمالها، ما تقدَّم منها، وما تأخر، وجوزيت بها.", "isBasmala": false, "translation_en": "When the planets are scattered.", "translation_id": "dan apabila bintang-bintang jatuh berserakan,", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 3, "text": "وَإِذَا ٱلۡبِحَارُ فُجِّرَتۡ ۝٣", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إذا السماء انشقت، واختلَّ نظامها، وإذا الكواكب تساقطت، وإذا البحار فجَّر الله بعضها في بعض، فذهب ماؤها، وإذا القبور قُلِبت ببعث مَن كان فيها، حينئذ تعلم كلُّ نفس جميع أعمالها، ما تقدَّم منها، وما تأخر، وجوزيت بها.", "isBasmala": false, "translation_en": "When the oceans are exploded.", "translation_id": "dan apabila lautan menjadikan meluap,", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 4, "text": "وَإِذَا ٱلۡقُبُورُ بُعۡثِرَتۡ ۝٤", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إذا السماء انشقت، واختلَّ نظامها، وإذا الكواكب تساقطت، وإذا البحار فجَّر الله بعضها في بعض، فذهب ماؤها، وإذا القبور قُلِبت ببعث مَن كان فيها، حينئذ تعلم كلُّ نفس جميع أعمالها، ما تقدَّم منها، وما تأخر، وجوزيت بها.", "isBasmala": false, "translation_en": "When the tombs are strewn around.", "translation_id": "dan apabila kuburan-kuburan dibongkar,", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 5, "text": "عَلِمَتۡ نَفۡسࣱ مَّا قَدَّمَتۡ وَأَخَّرَتۡ ۝٥", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إذا السماء انشقت، واختلَّ نظامها، وإذا الكواكب تساقطت، وإذا البحار فجَّر الله بعضها في بعض، فذهب ماؤها، وإذا القبور قُلِبت ببعث مَن كان فيها، حينئذ تعلم كلُّ نفس جميع أعمالها، ما تقدَّم منها، وما تأخر، وجوزيت بها.", "isBasmala": false, "translation_en": "Each soul will know what it has advanced, and what it has deferred.", "translation_id": "maka tiap-tiap jiwa akan mengetahui apa yang telah dikerjakan dan yang dilalaikannya.", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 6, "text": "یَـٰۤأَیُّهَا ٱلۡإِنسَـٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِیمِ ۝٦", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "يا أيها الإنسان المنكر للبعث، ما الذي جعلك تغتَرُّ بربك الجواد كثير الخير الحقيق بالشكر والطاعة، أليس هو الذي خلقك فسوَّى خلقك فعَدَلك، وركَّبك لأداء وظائفك، في أيِّ صورة شاءها خلقك؟", "isBasmala": false, "translation_en": "O man! What deluded you concerning your Lord, the Most Generous?", "translation_id": "Hai manusia, apakah yang telah memperdayakan kamu (berbuat durhaka) terhadap Tuhanmu Yang Maha Pemurah.", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 7, "text": "ٱلَّذِی خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ ۝٧", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "يا أيها الإنسان المنكر للبعث، ما الذي جعلك تغتَرُّ بربك الجواد كثير الخير الحقيق بالشكر والطاعة، أليس هو الذي خلقك فسوَّى خلقك فعَدَلك، وركَّبك لأداء وظائفك، في أيِّ صورة شاءها خلقك؟", "isBasmala": false, "translation_en": "He Who created you, and formed you, and proportioned you?", "translation_id": "Yang telah menciptakan kamu lalu menyempurnakan kejadianmu dan menjadikan (susunan tubuh)mu seimbang,", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 8, "text": "فِیۤ أَیِّ صُورَةࣲ مَّا شَاۤءَ رَكَّبَكَ ۝٨", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "يا أيها الإنسان المنكر للبعث، ما الذي جعلك تغتَرُّ بربك الجواد كثير الخير الحقيق بالشكر والطاعة، أليس هو الذي خلقك فسوَّى خلقك فعَدَلك، وركَّبك لأداء وظائفك، في أيِّ صورة شاءها خلقك؟", "isBasmala": false, "translation_en": "In whatever shape He willed, He assembled you.", "translation_id": "dalam bentuk apa saja yang Dia kehendaki, Dia menyusun tubuhmu.", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 9, "text": "كَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّینِ ۝٩", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "ليس الأمر كما تقولون من أنكم في عبادتكم غير الله مُحِقون، بل تكذِّبون بيوم الحساب والجزاء. وإن عليكم لملائكة رقباء كراما على الله كاتبين لما وُكِّلوا بإحصائه، لا يفوتهم من أعمالكم وأسراركم شيء، يعلمون ما تفعلون من خير أو شر.", "isBasmala": false, "translation_en": "But you reject the religion.", "translation_id": "Bukan hanya durhaka saja, bahkan kamu mendustakan hari pembalasan.", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 10, "text": "وَإِنَّ عَلَیۡكُمۡ لَحَـٰفِظِینَ ۝١٠", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "ليس الأمر كما تقولون من أنكم في عبادتكم غير الله مُحِقون، بل تكذِّبون بيوم الحساب والجزاء. وإن عليكم لملائكة رقباء كراما على الله كاتبين لما وُكِّلوا بإحصائه، لا يفوتهم من أعمالكم وأسراركم شيء، يعلمون ما تفعلون من خير أو شر.", "isBasmala": false, "translation_en": "Though over you are watchers.", "translation_id": "Padahal sesungguhnya bagi kamu ada (malaikat-malaikat) yang mengawasi (pekerjaanmu),", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 11, "text": "كِرَامࣰا كَـٰتِبِینَ ۝١١", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "ليس الأمر كما تقولون من أنكم في عبادتكم غير الله مُحِقون، بل تكذِّبون بيوم الحساب والجزاء. وإن عليكم لملائكة رقباء كراما على الله كاتبين لما وُكِّلوا بإحصائه، لا يفوتهم من أعمالكم وأسراركم شيء، يعلمون ما تفعلون من خير أو شر.", "isBasmala": false, "translation_en": "Honest recorders.", "translation_id": "yang mulia (di sisi Allah) dan mencatat (pekerjaan-pekerjaanmu itu),", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 12, "text": "یَعۡلَمُونَ مَا تَفۡعَلُونَ ۝١٢", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "ليس الأمر كما تقولون من أنكم في عبادتكم غير الله مُحِقون، بل تكذِّبون بيوم الحساب والجزاء. وإن عليكم لملائكة رقباء كراما على الله كاتبين لما وُكِّلوا بإحصائه، لا يفوتهم من أعمالكم وأسراركم شيء، يعلمون ما تفعلون من خير أو شر.", "isBasmala": false, "translation_en": "They know everything you do.", "translation_id": "mereka mengetahui apa yang kamu kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 13, "text": "إِنَّ ٱلۡأَبۡرَارَ لَفِی نَعِیمࣲ ۝١٣", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن الأتقياء القائمين بحقوق الله وحقوق عباده لفي نعيم.", "isBasmala": false, "translation_en": "The virtuous will be in bliss.", "translation_id": "Sesungguhnya orang-orang yang banyak berbakti benar-benar berada dalam surga yang penuh kenikmatan,", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 14, "text": "وَإِنَّ ٱلۡفُجَّارَ لَفِی جَحِیمࣲ ۝١٤", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "وإن الفُجَّار الذين قَصَّروا في حقوق الله وحقوق عباده لفي جحيم، يصيبهم لهبها يوم الجزاء، وما هم عن عذاب جهنم بغائبين لا بخروج ولا بموت.", "isBasmala": false, "translation_en": "While the wicked will be in Hell.", "translation_id": "dan sesungguhnya orang-orang yang durhaka benar-benar berada dalam neraka.", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 15, "text": "یَصۡلَوۡنَهَا یَوۡمَ ٱلدِّینِ ۝١٥", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "وإن الفُجَّار الذين قَصَّروا في حقوق الله وحقوق عباده لفي جحيم، يصيبهم لهبها يوم الجزاء، وما هم عن عذاب جهنم بغائبين لا بخروج ولا بموت.", "isBasmala": false, "translation_en": "They will enter it on the Day of Justice.", "translation_id": "Mereka masuk ke dalamnya pada hari pembalasan.", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 16, "text": "وَمَا هُمۡ عَنۡهَا بِغَاۤىِٕبِینَ ۝١٦", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "وإن الفُجَّار الذين قَصَّروا في حقوق الله وحقوق عباده لفي جحيم، يصيبهم لهبها يوم الجزاء، وما هم عن عذاب جهنم بغائبين لا بخروج ولا بموت.", "isBasmala": false, "translation_en": "And they will not be absent from it.", "translation_id": "Dan mereka sekali-kali tidak dapat keluar dari neraka itu.", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 17, "text": "وَمَاۤ أَدۡرَىٰكَ مَا یَوۡمُ ٱلدِّینِ ۝١٧", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "وما أدراك ما عظمة يوم الحساب، ثم ما أدراك ما عظمةُ يوم الحساب؟ يوم الحساب لا يقدر أحد على نفع أحد، والأمر في ذلك اليوم لله وحده الذي لا يغلبه غالب، ولا يقهره قاهر، ولا ينازعه أحد.", "isBasmala": false, "translation_en": "But what will convey to you what the Day of Justice is?", "translation_id": "Tahukah kamu apakah hari pembalasan itu?", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 18, "text": "ثُمَّ مَاۤ أَدۡرَىٰكَ مَا یَوۡمُ ٱلدِّینِ ۝١٨", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "وما أدراك ما عظمة يوم الحساب، ثم ما أدراك ما عظمةُ يوم الحساب؟ يوم الحساب لا يقدر أحد على نفع أحد، والأمر في ذلك اليوم لله وحده الذي لا يغلبه غالب، ولا يقهره قاهر، ولا ينازعه أحد.", "isBasmala": false, "translation_en": "Then again, what will convey to you what the Day of Justice is?", "translation_id": "Sekali lagi, tahukah kamu apakah hari pembalasan itu?", "manzil": 7, "manzil_display": ""}, {"sura": 82, "sura_name": "الإنفطار", "revelation": "Makkiyah", "aya": 19, "text": "یَوۡمَ لَا تَمۡلِكُ نَفۡسࣱ لِّنَفۡسࣲ شَیۡـࣰٔاۖ وَٱلۡأَمۡرُ یَوۡمَىِٕذࣲ لِّلَّهِ ۝١٩", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "وما أدراك ما عظمة يوم الحساب، ثم ما أدراك ما عظمةُ يوم الحساب؟ يوم الحساب لا يقدر أحد على نفع أحد، والأمر في ذلك اليوم لله وحده الذي لا يغلبه غالب، ولا يقهره قاهر، ولا ينازعه أحد.", "isBasmala": false, "translation_en": "The Day when no soul will avail another soul anything; and the decision on that Day is God's.", "translation_id": "(Yaitu) hari (ketika) seseorang tidak berdaya sedikitpun untuk menolong orang lain. Dan segala urusan pada hari itu dalam kekuasaan Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 1, "text": "وَیۡلࣱ لِّلۡمُطَفِّفِینَ ۝١", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذابٌ شديد للذين يبخسون المكيال والميزان، الذين إذا اشتروا من الناس مكيلا أو موزونًا يوفون لأنفسهم، وإذا باعوا الناس مكيلا أو موزونًا يُنْقصون في المكيال والميزان، فكيف بحال من يسرقهما ويختلسهما، ويبخس الناس أشياءهم؟ إنه أولى بالوعيد من مطففي المكيال والميزان. ألا يعتقد أولئك المطففون أن الله تعالى باعثهم ومحاسبهم على أعمالهم في يوم عظيم الهول؟ يوم يقوم الناس بين يدي الله، فيحاسبهم على القليل والكثير، وهم فيه خاضعون لله رب العالمين.", "isBasmala": false, "translation_en": "Woe to the defrauders.", "translation_id": "Kecelakaan besarlah bagi orang-orang yang curang", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 2, "text": "ٱلَّذِینَ إِذَا ٱكۡتَالُوا۟ عَلَى ٱلنَّاسِ یَسۡتَوۡفُونَ ۝٢", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذابٌ شديد للذين يبخسون المكيال والميزان، الذين إذا اشتروا من الناس مكيلا أو موزونًا يوفون لأنفسهم، وإذا باعوا الناس مكيلا أو موزونًا يُنْقصون في المكيال والميزان، فكيف بحال من يسرقهما ويختلسهما، ويبخس الناس أشياءهم؟ إنه أولى بالوعيد من مطففي المكيال والميزان. ألا يعتقد أولئك المطففون أن الله تعالى باعثهم ومحاسبهم على أعمالهم في يوم عظيم الهول؟ يوم يقوم الناس بين يدي الله، فيحاسبهم على القليل والكثير، وهم فيه خاضعون لله رب العالمين.", "isBasmala": false, "translation_en": "Those who, when they take a measure from people, they take in full.", "translation_id": "(yaitu) orang-orang yang apabila menerima takaran dari orang lain mereka minta dipenuhi,", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 3, "text": "وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ یُخۡسِرُونَ ۝٣", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذابٌ شديد للذين يبخسون المكيال والميزان، الذين إذا اشتروا من الناس مكيلا أو موزونًا يوفون لأنفسهم، وإذا باعوا الناس مكيلا أو موزونًا يُنْقصون في المكيال والميزان، فكيف بحال من يسرقهما ويختلسهما، ويبخس الناس أشياءهم؟ إنه أولى بالوعيد من مطففي المكيال والميزان. ألا يعتقد أولئك المطففون أن الله تعالى باعثهم ومحاسبهم على أعمالهم في يوم عظيم الهول؟ يوم يقوم الناس بين يدي الله، فيحاسبهم على القليل والكثير، وهم فيه خاضعون لله رب العالمين.", "isBasmala": false, "translation_en": "But when they measure or weigh to others, they cheat.", "translation_id": "dan apabila mereka menakar atau menimbang untuk orang lain, mereka mengurangi.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 4, "text": "أَلَا یَظُنُّ أُو۟لَـٰۤىِٕكَ أَنَّهُم مَّبۡعُوثُونَ ۝٤", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذابٌ شديد للذين يبخسون المكيال والميزان، الذين إذا اشتروا من الناس مكيلا أو موزونًا يوفون لأنفسهم، وإذا باعوا الناس مكيلا أو موزونًا يُنْقصون في المكيال والميزان، فكيف بحال من يسرقهما ويختلسهما، ويبخس الناس أشياءهم؟ إنه أولى بالوعيد من مطففي المكيال والميزان. ألا يعتقد أولئك المطففون أن الله تعالى باعثهم ومحاسبهم على أعمالهم في يوم عظيم الهول؟ يوم يقوم الناس بين يدي الله، فيحاسبهم على القليل والكثير، وهم فيه خاضعون لله رب العالمين.", "isBasmala": false, "translation_en": "Do these not know that they will be resurrected?", "translation_id": "Tidaklah orang-orang itu menyangka, bahwa sesungguhnya mereka akan dibangkitkan,", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 5, "text": "لِیَوۡمٍ عَظِیمࣲ ۝٥", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذابٌ شديد للذين يبخسون المكيال والميزان، الذين إذا اشتروا من الناس مكيلا أو موزونًا يوفون لأنفسهم، وإذا باعوا الناس مكيلا أو موزونًا يُنْقصون في المكيال والميزان، فكيف بحال من يسرقهما ويختلسهما، ويبخس الناس أشياءهم؟ إنه أولى بالوعيد من مطففي المكيال والميزان. ألا يعتقد أولئك المطففون أن الله تعالى باعثهم ومحاسبهم على أعمالهم في يوم عظيم الهول؟ يوم يقوم الناس بين يدي الله، فيحاسبهم على القليل والكثير، وهم فيه خاضعون لله رب العالمين.", "isBasmala": false, "translation_en": "For a Great Day?", "translation_id": "pada suatu hari yang besar,", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 6, "text": "یَوۡمَ یَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَـٰلَمِینَ ۝٦", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذابٌ شديد للذين يبخسون المكيال والميزان، الذين إذا اشتروا من الناس مكيلا أو موزونًا يوفون لأنفسهم، وإذا باعوا الناس مكيلا أو موزونًا يُنْقصون في المكيال والميزان، فكيف بحال من يسرقهما ويختلسهما، ويبخس الناس أشياءهم؟ إنه أولى بالوعيد من مطففي المكيال والميزان. ألا يعتقد أولئك المطففون أن الله تعالى باعثهم ومحاسبهم على أعمالهم في يوم عظيم الهول؟ يوم يقوم الناس بين يدي الله، فيحاسبهم على القليل والكثير، وهم فيه خاضعون لله رب العالمين.", "isBasmala": false, "translation_en": "The Day when mankind will stand before the Lord of the Worlds?", "translation_id": "(yaitu) hari (ketika) manusia berdiri menghadap Tuhan semesta alam?", "manzil": 7, "manzil_display": ""}], "588": [{"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 7, "text": "كَلَّاۤ إِنَّ كِتَـٰبَ ٱلۡفُجَّارِ لَفِی سِجِّینࣲ ۝٧", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "حقا إن مصير الفُجَّار ومأواهم لفي ضيق، وما أدراك ما هذا الضيق؟ إنه سجن مقيم وعذاب أليم، وهو ما كتب لهم المصير إليه، مكتوب مفروغ منه، لا يزاد فيه ولا يُنقص.", "isBasmala": false, "translation_en": "Not at all. The record of the wicked is in Sijjeen.", "translation_id": "Sekali-kali jangan curang, karena sesungguhnya kitab orang yang durhaka tersimpan dalam sijjin.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 8, "text": "وَمَاۤ أَدۡرَىٰكَ مَا سِجِّینࣱ ۝٨", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "حقا إن مصير الفُجَّار ومأواهم لفي ضيق، وما أدراك ما هذا الضيق؟ إنه سجن مقيم وعذاب أليم، وهو ما كتب لهم المصير إليه، مكتوب مفروغ منه، لا يزاد فيه ولا يُنقص.", "isBasmala": false, "translation_en": "But how can you know what Sijjeen is?", "translation_id": "Tahukah kamu apakah sijjin itu?", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 9, "text": "كِتَـٰبࣱ مَّرۡقُومࣱ ۝٩", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "حقا إن مصير الفُجَّار ومأواهم لفي ضيق، وما أدراك ما هذا الضيق؟ إنه سجن مقيم وعذاب أليم، وهو ما كتب لهم المصير إليه، مكتوب مفروغ منه، لا يزاد فيه ولا يُنقص.", "isBasmala": false, "translation_en": "A numerical book.", "translation_id": "(Ialah) kitab yang bertulis.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 10, "text": "وَیۡلࣱ یَوۡمَىِٕذࣲ لِّلۡمُكَذِّبِینَ ۝١٠", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذاب شديد يومئذ للمكذبين، الذين يكذبون بوقوع يوم الجزاء، وما يكذِّب به إلا كل ظالم كثير الإثم، إذا تتلى عليه آيات القرآن قال: هذه أباطيل الأولين. ليس الأمر كما زعموا، بل هو كلام الله ووحيه إلى نبيه، وإنما حجب قلوبهم عن التصديق به ما غشاها من كثرة ما يرتكبون من الذنوب. ليس الأمر كما زعم الكفار، بل إنهم يوم القيامة عن رؤية ربهم- جل وعلا- لمحجوبون، (وفي هذه الآية دلالة على رؤية المؤمنين ربَّهم في الجنة) ثم إنهم لداخلو النار يقاسون حرها، ثم يقال لهم: هذا الجزاء الذي كنتم به تكذبون.", "isBasmala": false, "translation_en": "Woe on that Day to the deniers.", "translation_id": "Kecelakaan yang besarlah pada hari itu bagi orang-orang yang mendustakan,", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 11, "text": "ٱلَّذِینَ یُكَذِّبُونَ بِیَوۡمِ ٱلدِّینِ ۝١١", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذاب شديد يومئذ للمكذبين، الذين يكذبون بوقوع يوم الجزاء، وما يكذِّب به إلا كل ظالم كثير الإثم، إذا تتلى عليه آيات القرآن قال: هذه أباطيل الأولين. ليس الأمر كما زعموا، بل هو كلام الله ووحيه إلى نبيه، وإنما حجب قلوبهم عن التصديق به ما غشاها من كثرة ما يرتكبون من الذنوب. ليس الأمر كما زعم الكفار، بل إنهم يوم القيامة عن رؤية ربهم- جل وعلا- لمحجوبون، (وفي هذه الآية دلالة على رؤية المؤمنين ربَّهم في الجنة) ثم إنهم لداخلو النار يقاسون حرها، ثم يقال لهم: هذا الجزاء الذي كنتم به تكذبون.", "isBasmala": false, "translation_en": "Those who deny the Day of Reckoning.", "translation_id": "(yaitu) orang-orang yang mendustakan hari pembalasan.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 12, "text": "وَمَا یُكَذِّبُ بِهِۦۤ إِلَّا كُلُّ مُعۡتَدٍ أَثِیمٍ ۝١٢", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذاب شديد يومئذ للمكذبين، الذين يكذبون بوقوع يوم الجزاء، وما يكذِّب به إلا كل ظالم كثير الإثم، إذا تتلى عليه آيات القرآن قال: هذه أباطيل الأولين. ليس الأمر كما زعموا، بل هو كلام الله ووحيه إلى نبيه، وإنما حجب قلوبهم عن التصديق به ما غشاها من كثرة ما يرتكبون من الذنوب. ليس الأمر كما زعم الكفار، بل إنهم يوم القيامة عن رؤية ربهم- جل وعلا- لمحجوبون، (وفي هذه الآية دلالة على رؤية المؤمنين ربَّهم في الجنة) ثم إنهم لداخلو النار يقاسون حرها، ثم يقال لهم: هذا الجزاء الذي كنتم به تكذبون.", "isBasmala": false, "translation_en": "But none denies it except the sinful aggressor.", "translation_id": "Dan tidak ada yang mendustakan hari pembalasan itu melainkan setiap orang yang melampaui batas lagi berdosa,", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 13, "text": "إِذَا تُتۡلَىٰ عَلَیۡهِ ءَایَـٰتُنَا قَالَ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ ۝١٣", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذاب شديد يومئذ للمكذبين، الذين يكذبون بوقوع يوم الجزاء، وما يكذِّب به إلا كل ظالم كثير الإثم، إذا تتلى عليه آيات القرآن قال: هذه أباطيل الأولين. ليس الأمر كما زعموا، بل هو كلام الله ووحيه إلى نبيه، وإنما حجب قلوبهم عن التصديق به ما غشاها من كثرة ما يرتكبون من الذنوب. ليس الأمر كما زعم الكفار، بل إنهم يوم القيامة عن رؤية ربهم- جل وعلا- لمحجوبون، (وفي هذه الآية دلالة على رؤية المؤمنين ربَّهم في الجنة) ثم إنهم لداخلو النار يقاسون حرها، ثم يقال لهم: هذا الجزاء الذي كنتم به تكذبون.", "isBasmala": false, "translation_en": "When Our revelations are recited to him, he says, \"Legends of the ancients.\"", "translation_id": "yang apabila dibacakan kepadanya ayat-ayat Kami, ia berkata: \"Itu adalah dongengan orang-orang yang dahulu\"", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 14, "text": "كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُوا۟ یَكۡسِبُونَ ۝١٤", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذاب شديد يومئذ للمكذبين، الذين يكذبون بوقوع يوم الجزاء، وما يكذِّب به إلا كل ظالم كثير الإثم، إذا تتلى عليه آيات القرآن قال: هذه أباطيل الأولين. ليس الأمر كما زعموا، بل هو كلام الله ووحيه إلى نبيه، وإنما حجب قلوبهم عن التصديق به ما غشاها من كثرة ما يرتكبون من الذنوب. ليس الأمر كما زعم الكفار، بل إنهم يوم القيامة عن رؤية ربهم- جل وعلا- لمحجوبون، (وفي هذه الآية دلالة على رؤية المؤمنين ربَّهم في الجنة) ثم إنهم لداخلو النار يقاسون حرها، ثم يقال لهم: هذا الجزاء الذي كنتم به تكذبون.", "isBasmala": false, "translation_en": "Not at all. Their hearts have become corroded by what they used to earn.", "translation_id": "Sekali-kali tidak (demikian), sebenarnya apa yang selalu mereka usahakan itu menutupi hati mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 15, "text": "كَلَّاۤ إِنَّهُمۡ عَن رَّبِّهِمۡ یَوۡمَىِٕذࣲ لَّمَحۡجُوبُونَ ۝١٥", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذاب شديد يومئذ للمكذبين، الذين يكذبون بوقوع يوم الجزاء، وما يكذِّب به إلا كل ظالم كثير الإثم، إذا تتلى عليه آيات القرآن قال: هذه أباطيل الأولين. ليس الأمر كما زعموا، بل هو كلام الله ووحيه إلى نبيه، وإنما حجب قلوبهم عن التصديق به ما غشاها من كثرة ما يرتكبون من الذنوب. ليس الأمر كما زعم الكفار، بل إنهم يوم القيامة عن رؤية ربهم- جل وعلا- لمحجوبون، (وفي هذه الآية دلالة على رؤية المؤمنين ربَّهم في الجنة) ثم إنهم لداخلو النار يقاسون حرها، ثم يقال لهم: هذا الجزاء الذي كنتم به تكذبون.", "isBasmala": false, "translation_en": "Not at all. On that Day, they will be screened from their Lord.", "translation_id": "Sekali-kali tidak, sesungguhnya mereka pada hari itu benar-benar tertutup dari (rahmat) Tuhan mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 16, "text": "ثُمَّ إِنَّهُمۡ لَصَالُوا۟ ٱلۡجَحِیمِ ۝١٦", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذاب شديد يومئذ للمكذبين، الذين يكذبون بوقوع يوم الجزاء، وما يكذِّب به إلا كل ظالم كثير الإثم، إذا تتلى عليه آيات القرآن قال: هذه أباطيل الأولين. ليس الأمر كما زعموا، بل هو كلام الله ووحيه إلى نبيه، وإنما حجب قلوبهم عن التصديق به ما غشاها من كثرة ما يرتكبون من الذنوب. ليس الأمر كما زعم الكفار، بل إنهم يوم القيامة عن رؤية ربهم- جل وعلا- لمحجوبون، (وفي هذه الآية دلالة على رؤية المؤمنين ربَّهم في الجنة) ثم إنهم لداخلو النار يقاسون حرها، ثم يقال لهم: هذا الجزاء الذي كنتم به تكذبون.", "isBasmala": false, "translation_en": "Then they will roast in Hell.", "translation_id": "Kemudian, sesungguhnya mereka benar-benar masuk neraka.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 17, "text": "ثُمَّ یُقَالُ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تُكَذِّبُونَ ۝١٧", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "عذاب شديد يومئذ للمكذبين، الذين يكذبون بوقوع يوم الجزاء، وما يكذِّب به إلا كل ظالم كثير الإثم، إذا تتلى عليه آيات القرآن قال: هذه أباطيل الأولين. ليس الأمر كما زعموا، بل هو كلام الله ووحيه إلى نبيه، وإنما حجب قلوبهم عن التصديق به ما غشاها من كثرة ما يرتكبون من الذنوب. ليس الأمر كما زعم الكفار، بل إنهم يوم القيامة عن رؤية ربهم- جل وعلا- لمحجوبون، (وفي هذه الآية دلالة على رؤية المؤمنين ربَّهم في الجنة) ثم إنهم لداخلو النار يقاسون حرها، ثم يقال لهم: هذا الجزاء الذي كنتم به تكذبون.", "isBasmala": false, "translation_en": "Then it will be said, \"This is what you used to deny.\"", "translation_id": "Kemudian, dikatakan (kepada mereka): \"Inilah azab yang dahulu selalu kamu dustakan\".", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 18, "text": "كَلَّاۤ إِنَّ كِتَـٰبَ ٱلۡأَبۡرَارِ لَفِی عِلِّیِّینَ ۝١٨", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "حقا إن كتاب الأبرار -وهم المتقون- لفي المراتب العالية في الجنة. وما أدراك -أيها الرسول- ما هذه المراتب العالية؟ كتاب الأبرار مكتوب مفروغ منه، لا يزاد فيه ولا يُنقص، يَطَّلِع عليه المقربون من ملائكة كل سماء.", "isBasmala": false, "translation_en": "No indeed; the record of the righteous is in Elliyyeen.", "translation_id": "Sekali-kali tidak, sesungguhnya kitab orang-orang yang berbakti itu (tersimpan) dalam 'Illiyyin.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 19, "text": "وَمَاۤ أَدۡرَىٰكَ مَا عِلِّیُّونَ ۝١٩", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "حقا إن كتاب الأبرار -وهم المتقون- لفي المراتب العالية في الجنة. وما أدراك -أيها الرسول- ما هذه المراتب العالية؟ كتاب الأبرار مكتوب مفروغ منه، لا يزاد فيه ولا يُنقص، يَطَّلِع عليه المقربون من ملائكة كل سماء.", "isBasmala": false, "translation_en": "But how can you know what Elliyyoon is?", "translation_id": "Tahukah kamu apakah 'Illiyyin itu?", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 20, "text": "كِتَـٰبࣱ مَّرۡقُومࣱ ۝٢٠", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "حقا إن كتاب الأبرار -وهم المتقون- لفي المراتب العالية في الجنة. وما أدراك -أيها الرسول- ما هذه المراتب العالية؟ كتاب الأبرار مكتوب مفروغ منه، لا يزاد فيه ولا يُنقص، يَطَّلِع عليه المقربون من ملائكة كل سماء.", "isBasmala": false, "translation_en": "A numerical book.", "translation_id": "(Yaitu) kitab yang bertulis,", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 21, "text": "یَشۡهَدُهُ ٱلۡمُقَرَّبُونَ ۝٢١", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "حقا إن كتاب الأبرار -وهم المتقون- لفي المراتب العالية في الجنة. وما أدراك -أيها الرسول- ما هذه المراتب العالية؟ كتاب الأبرار مكتوب مفروغ منه، لا يزاد فيه ولا يُنقص، يَطَّلِع عليه المقربون من ملائكة كل سماء.", "isBasmala": false, "translation_en": "Witnessed by those brought near.", "translation_id": "yang disaksikan oleh malaikat-malaikat yang didekatkan (kepada Allah).", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 22, "text": "إِنَّ ٱلۡأَبۡرَارَ لَفِی نَعِیمٍ ۝٢٢", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن أهل الصدق والطاعة لفي الجنة يتنعمون، على الأسرَّة ينظرون إلى ربهم، وإلى ما أعدَّ لهم من خيرات، ترى في وجوههم بهجة النعيم، يُسْقَون من خمر صافية محكم إناؤها، آخره رائحة مسك، وفي ذلك النعيم المقيم فليتسابق المتسابقون. وهذا الشراب مزاجه وخلطه من عين في الجنة تُعْرَف لعلوها بـ \"تسنيم\"، عين أعدت؛ ليشرب منها المقربون، ويتلذذوا بها.", "isBasmala": false, "translation_en": "Indeed, the righteous will be amid bliss.", "translation_id": "Sesungguhnya orang yang berbakti itu benar-benar berada dalam kenikmatan yang besar (surga),", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 23, "text": "عَلَى ٱلۡأَرَاۤىِٕكِ یَنظُرُونَ ۝٢٣", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن أهل الصدق والطاعة لفي الجنة يتنعمون، على الأسرَّة ينظرون إلى ربهم، وإلى ما أعدَّ لهم من خيرات، ترى في وجوههم بهجة النعيم، يُسْقَون من خمر صافية محكم إناؤها، آخره رائحة مسك، وفي ذلك النعيم المقيم فليتسابق المتسابقون. وهذا الشراب مزاجه وخلطه من عين في الجنة تُعْرَف لعلوها بـ \"تسنيم\"، عين أعدت؛ ليشرب منها المقربون، ويتلذذوا بها.", "isBasmala": false, "translation_en": "On thrones, looking on.", "translation_id": "mereka (duduk) di atas dipan-dipan sambil memandang.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 24, "text": "تَعۡرِفُ فِی وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِیمِ ۝٢٤", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن أهل الصدق والطاعة لفي الجنة يتنعمون، على الأسرَّة ينظرون إلى ربهم، وإلى ما أعدَّ لهم من خيرات، ترى في وجوههم بهجة النعيم، يُسْقَون من خمر صافية محكم إناؤها، آخره رائحة مسك، وفي ذلك النعيم المقيم فليتسابق المتسابقون. وهذا الشراب مزاجه وخلطه من عين في الجنة تُعْرَف لعلوها بـ \"تسنيم\"، عين أعدت؛ ليشرب منها المقربون، ويتلذذوا بها.", "isBasmala": false, "translation_en": "You will recognize on their faces the radiance of bliss.", "translation_id": "Kamu dapat mengetahui dari wajah mereka kesenangan mereka yang penuh kenikmatan.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 25, "text": "یُسۡقَوۡنَ مِن رَّحِیقࣲ مَّخۡتُومٍ ۝٢٥", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن أهل الصدق والطاعة لفي الجنة يتنعمون، على الأسرَّة ينظرون إلى ربهم، وإلى ما أعدَّ لهم من خيرات، ترى في وجوههم بهجة النعيم، يُسْقَون من خمر صافية محكم إناؤها، آخره رائحة مسك، وفي ذلك النعيم المقيم فليتسابق المتسابقون. وهذا الشراب مزاجه وخلطه من عين في الجنة تُعْرَف لعلوها بـ \"تسنيم\"، عين أعدت؛ ليشرب منها المقربون، ويتلذذوا بها.", "isBasmala": false, "translation_en": "They will be given to drink a sealed wine.", "translation_id": "Mereka diberi minum dari khamar murni yang dilak (tempatnya),", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 26, "text": "خِتَـٰمُهُۥ مِسۡكࣱۚ وَفِی ذَ ٰلِكَ فَلۡیَتَنَافَسِ ٱلۡمُتَنَـٰفِسُونَ ۝٢٦", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن أهل الصدق والطاعة لفي الجنة يتنعمون، على الأسرَّة ينظرون إلى ربهم، وإلى ما أعدَّ لهم من خيرات، ترى في وجوههم بهجة النعيم، يُسْقَون من خمر صافية محكم إناؤها، آخره رائحة مسك، وفي ذلك النعيم المقيم فليتسابق المتسابقون. وهذا الشراب مزاجه وخلطه من عين في الجنة تُعْرَف لعلوها بـ \"تسنيم\"، عين أعدت؛ ليشرب منها المقربون، ويتلذذوا بها.", "isBasmala": false, "translation_en": "Whose seal is musk-this is what competitors should compete for.", "translation_id": "laknya adalah kesturi; dan untuk yang demikian itu hendaknya orang berlomba-lomba.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 27, "text": "وَمِزَاجُهُۥ مِن تَسۡنِیمٍ ۝٢٧", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن أهل الصدق والطاعة لفي الجنة يتنعمون، على الأسرَّة ينظرون إلى ربهم، وإلى ما أعدَّ لهم من خيرات، ترى في وجوههم بهجة النعيم، يُسْقَون من خمر صافية محكم إناؤها، آخره رائحة مسك، وفي ذلك النعيم المقيم فليتسابق المتسابقون. وهذا الشراب مزاجه وخلطه من عين في الجنة تُعْرَف لعلوها بـ \"تسنيم\"، عين أعدت؛ ليشرب منها المقربون، ويتلذذوا بها.", "isBasmala": false, "translation_en": "Its mixture is of Tasneem.", "translation_id": "Dan campuran khamar murni itu adalah dari tasnim,", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 28, "text": "عَیۡنࣰا یَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ ۝٢٨", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن أهل الصدق والطاعة لفي الجنة يتنعمون، على الأسرَّة ينظرون إلى ربهم، وإلى ما أعدَّ لهم من خيرات، ترى في وجوههم بهجة النعيم، يُسْقَون من خمر صافية محكم إناؤها، آخره رائحة مسك، وفي ذلك النعيم المقيم فليتسابق المتسابقون. وهذا الشراب مزاجه وخلطه من عين في الجنة تُعْرَف لعلوها بـ \"تسنيم\"، عين أعدت؛ ليشرب منها المقربون، ويتلذذوا بها.", "isBasmala": false, "translation_en": "A spring from which those brought near drink.", "translation_id": "(yaitu) mata air yang minum daripadanya orang-orang yang didekatkan kepada Allah.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 29, "text": "إِنَّ ٱلَّذِینَ أَجۡرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِینَ ءَامَنُوا۟ یَضۡحَكُونَ ۝٢٩", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن الذين أجرموا كانوا في الدنيا يستهزئون بالمؤمنين، وإذا مروا بهم يتغامزون سخرية بهم، وإذا رجع الذين أجرموا إلى أهلهم وذويهم تفكهوا معهم بالسخرية من المؤمنين. وإذا رأى هؤلاء الكفار أصحاب محمد صلى الله عليه وسلم، وقد اتبعوا الهدى قالوا: إن هؤلاء لتائهون في اتباعهم محمدًا صلى الله عليه وسلم، وما بُعث هؤلاء المجرمون رقباء على أصحاب محمد صلى الله عليه وسلم. فيوم القيامة يسخر الذين صدقوا الله ورسوله وعملوا بشرعه من الكفار، كما سخر الكافرون منهم في الدنيا.", "isBasmala": false, "translation_en": "Those who committed crimes used to laugh at those who believed.", "translation_id": "Sesungguhnya orang-orang yang berdosa, adalah mereka yang menertawakan orang-orang yang beriman.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 30, "text": "وَإِذَا مَرُّوا۟ بِهِمۡ یَتَغَامَزُونَ ۝٣٠", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن الذين أجرموا كانوا في الدنيا يستهزئون بالمؤمنين، وإذا مروا بهم يتغامزون سخرية بهم، وإذا رجع الذين أجرموا إلى أهلهم وذويهم تفكهوا معهم بالسخرية من المؤمنين. وإذا رأى هؤلاء الكفار أصحاب محمد صلى الله عليه وسلم، وقد اتبعوا الهدى قالوا: إن هؤلاء لتائهون في اتباعهم محمدًا صلى الله عليه وسلم، وما بُعث هؤلاء المجرمون رقباء على أصحاب محمد صلى الله عليه وسلم. فيوم القيامة يسخر الذين صدقوا الله ورسوله وعملوا بشرعه من الكفار، كما سخر الكافرون منهم في الدنيا.", "isBasmala": false, "translation_en": "And when they passed by them, they would wink at one another.", "translation_id": "Dan apabila orang-orang yang beriman lalu di hadapan mereka, mereka saling mengedip-ngedipkan matanya.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 31, "text": "وَإِذَا ٱنقَلَبُوۤا۟ إِلَىٰۤ أَهۡلِهِمُ ٱنقَلَبُوا۟ فَكِهِینَ ۝٣١", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن الذين أجرموا كانوا في الدنيا يستهزئون بالمؤمنين، وإذا مروا بهم يتغامزون سخرية بهم، وإذا رجع الذين أجرموا إلى أهلهم وذويهم تفكهوا معهم بالسخرية من المؤمنين. وإذا رأى هؤلاء الكفار أصحاب محمد صلى الله عليه وسلم، وقد اتبعوا الهدى قالوا: إن هؤلاء لتائهون في اتباعهم محمدًا صلى الله عليه وسلم، وما بُعث هؤلاء المجرمون رقباء على أصحاب محمد صلى الله عليه وسلم. فيوم القيامة يسخر الذين صدقوا الله ورسوله وعملوا بشرعه من الكفار، كما سخر الكافرون منهم في الدنيا.", "isBasmala": false, "translation_en": "And when they went back to their families, they would go back exulting.", "translation_id": "Dan apabila orang-orang yang berdosa itu kembali kepada kaumnya, mereka kembali dengan gembira.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 32, "text": "وَإِذَا رَأَوۡهُمۡ قَالُوۤا۟ إِنَّ هَـٰۤؤُلَاۤءِ لَضَاۤلُّونَ ۝٣٢", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن الذين أجرموا كانوا في الدنيا يستهزئون بالمؤمنين، وإذا مروا بهم يتغامزون سخرية بهم، وإذا رجع الذين أجرموا إلى أهلهم وذويهم تفكهوا معهم بالسخرية من المؤمنين. وإذا رأى هؤلاء الكفار أصحاب محمد صلى الله عليه وسلم، وقد اتبعوا الهدى قالوا: إن هؤلاء لتائهون في اتباعهم محمدًا صلى الله عليه وسلم، وما بُعث هؤلاء المجرمون رقباء على أصحاب محمد صلى الله عليه وسلم. فيوم القيامة يسخر الذين صدقوا الله ورسوله وعملوا بشرعه من الكفار، كما سخر الكافرون منهم في الدنيا.", "isBasmala": false, "translation_en": "And if they saw them, they would say, \"These people are lost.\"", "translation_id": "Dan apabila mereka melihat orang-orang mukmin, mereka mengatakan: \"Sesungguhnya mereka itu benar-benar orang-orang yang sesat\",", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 33, "text": "وَمَاۤ أُرۡسِلُوا۟ عَلَیۡهِمۡ حَـٰفِظِینَ ۝٣٣", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن الذين أجرموا كانوا في الدنيا يستهزئون بالمؤمنين، وإذا مروا بهم يتغامزون سخرية بهم، وإذا رجع الذين أجرموا إلى أهلهم وذويهم تفكهوا معهم بالسخرية من المؤمنين. وإذا رأى هؤلاء الكفار أصحاب محمد صلى الله عليه وسلم، وقد اتبعوا الهدى قالوا: إن هؤلاء لتائهون في اتباعهم محمدًا صلى الله عليه وسلم، وما بُعث هؤلاء المجرمون رقباء على أصحاب محمد صلى الله عليه وسلم. فيوم القيامة يسخر الذين صدقوا الله ورسوله وعملوا بشرعه من الكفار، كما سخر الكافرون منهم في الدنيا.", "isBasmala": false, "translation_en": "Yet they were not sent as guardians over them.", "translation_id": "padahal orang-orang yang berdosa itu tidak dikirim untuk penjaga bagi orang-orang mukmin.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 34, "text": "فَٱلۡیَوۡمَ ٱلَّذِینَ ءَامَنُوا۟ مِنَ ٱلۡكُفَّارِ یَضۡحَكُونَ ۝٣٤", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "إن الذين أجرموا كانوا في الدنيا يستهزئون بالمؤمنين، وإذا مروا بهم يتغامزون سخرية بهم، وإذا رجع الذين أجرموا إلى أهلهم وذويهم تفكهوا معهم بالسخرية من المؤمنين. وإذا رأى هؤلاء الكفار أصحاب محمد صلى الله عليه وسلم، وقد اتبعوا الهدى قالوا: إن هؤلاء لتائهون في اتباعهم محمدًا صلى الله عليه وسلم، وما بُعث هؤلاء المجرمون رقباء على أصحاب محمد صلى الله عليه وسلم. فيوم القيامة يسخر الذين صدقوا الله ورسوله وعملوا بشرعه من الكفار، كما سخر الكافرون منهم في الدنيا.", "isBasmala": false, "translation_en": "But on that Day, those who believed will laugh at the unbelievers.", "translation_id": "Maka pada hari ini, orang-orang yang beriman menertawakan orang-orang kafir,", "manzil": 7, "manzil_display": ""}], "589": [{"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 35, "text": "عَلَى ٱلۡأَرَاۤىِٕكِ یَنظُرُونَ ۝٣٥", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "على المجالس الفاخرة ينظر المؤمنون إلى ما أعطاهم الله من الكرامة والنعيم في الجنة، ومن أعظم ذلك النظر إلى وجه الله الكريم. هل جوزي الكفار - إذ فُعل بهم ذلك- جزاءً وفاق ما كانوا يفعلونه في الدنيا من الشرور والآثام؟", "isBasmala": false, "translation_en": "On luxurious furnishings, looking on.", "translation_id": "mereka (duduk) di atas dipan-dipan sambil memandang.", "manzil": 7, "manzil_display": ""}, {"sura": 83, "sura_name": "المطففين", "revelation": "Makkiyah", "aya": 36, "text": "هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُوا۟ یَفۡعَلُونَ ۝٣٦", "juz": 30, "hizb": "(*½ ح 59*)", "tafsir": "على المجالس الفاخرة ينظر المؤمنون إلى ما أعطاهم الله من الكرامة والنعيم في الجنة، ومن أعظم ذلك النظر إلى وجه الله الكريم. هل جوزي الكفار - إذ فُعل بهم ذلك- جزاءً وفاق ما كانوا يفعلونه في الدنيا من الشرور والآثام؟", "isBasmala": false, "translation_en": "Have the unbelievers been repaid for what they used to do?", "translation_id": "Sesungguhnya orang-orang kafir telah diberi ganjaran terhadap apa yang dahulu mereka kerjakan.", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 1, "text": "۞ إِذَا ٱلسَّمَاۤءُ ٱنشَقَّتۡ ۝١", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إذا السماء تصدَّعت، وتفطَّرت بالغمام يوم القيامة، وأطاعت أمر ربها فيما أمرها به من الانشقاق، وحُقَّ لها أن تنقاد لأمره. وإذا الأرض بُسطت وَوُسِّعت، ودكت جبالها في ذلك اليوم، وقذفت ما في بطنها من الأموات، وتخلَّتْ عنهم، وانقادت لربها فيما أمرها به، وحُقَّ لها أن تنقاد لأمره.", "isBasmala": false, "translation_en": "When the sky is ruptured.", "translation_id": "Apabila langit terbelah,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 2, "text": "وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ ۝٢", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إذا السماء تصدَّعت، وتفطَّرت بالغمام يوم القيامة، وأطاعت أمر ربها فيما أمرها به من الانشقاق، وحُقَّ لها أن تنقاد لأمره. وإذا الأرض بُسطت وَوُسِّعت، ودكت جبالها في ذلك اليوم، وقذفت ما في بطنها من الأموات، وتخلَّتْ عنهم، وانقادت لربها فيما أمرها به، وحُقَّ لها أن تنقاد لأمره.", "isBasmala": false, "translation_en": "And hearkens to its Lord, as it must.", "translation_id": "dan patuh kepada Tuhannya, dan sudah semestinya langit itu patuh,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 3, "text": "وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ ۝٣", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إذا السماء تصدَّعت، وتفطَّرت بالغمام يوم القيامة، وأطاعت أمر ربها فيما أمرها به من الانشقاق، وحُقَّ لها أن تنقاد لأمره. وإذا الأرض بُسطت وَوُسِّعت، ودكت جبالها في ذلك اليوم، وقذفت ما في بطنها من الأموات، وتخلَّتْ عنهم، وانقادت لربها فيما أمرها به، وحُقَّ لها أن تنقاد لأمره.", "isBasmala": false, "translation_en": "And when the earth is leveled out.", "translation_id": "dan apabila bumi diratakan,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 4, "text": "وَأَلۡقَتۡ مَا فِیهَا وَتَخَلَّتۡ ۝٤", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إذا السماء تصدَّعت، وتفطَّرت بالغمام يوم القيامة، وأطاعت أمر ربها فيما أمرها به من الانشقاق، وحُقَّ لها أن تنقاد لأمره. وإذا الأرض بُسطت وَوُسِّعت، ودكت جبالها في ذلك اليوم، وقذفت ما في بطنها من الأموات، وتخلَّتْ عنهم، وانقادت لربها فيما أمرها به، وحُقَّ لها أن تنقاد لأمره.", "isBasmala": false, "translation_en": "And casts out what is in it, and becomes empty.", "translation_id": "dan dilemparkan apa yang ada di dalamnya dan menjadi kosong,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 5, "text": "وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ ۝٥", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إذا السماء تصدَّعت، وتفطَّرت بالغمام يوم القيامة، وأطاعت أمر ربها فيما أمرها به من الانشقاق، وحُقَّ لها أن تنقاد لأمره. وإذا الأرض بُسطت وَوُسِّعت، ودكت جبالها في ذلك اليوم، وقذفت ما في بطنها من الأموات، وتخلَّتْ عنهم، وانقادت لربها فيما أمرها به، وحُقَّ لها أن تنقاد لأمره.", "isBasmala": false, "translation_en": "And hearkens to its Lord, as it must.", "translation_id": "dan patuh kepada Tuhannya, dan sudah semestinya bumi itu patuh, (pada waktu itu manusia akan mengetahui akibat perbuatannya).", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 6, "text": "یَـٰۤأَیُّهَا ٱلۡإِنسَـٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحࣰا فَمُلَـٰقِیهِ ۝٦", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "يا أيها الإنسان إنك ساعٍ إلى الله، وعامل أعمالا من خير أو شر، ثم تلاقي الله يوم القيامة، فيجازيك بعملك بفضله أو عدله.", "isBasmala": false, "translation_en": "O man! You are laboring towards your Lord, and you will meet Him.", "translation_id": "Hai manusia, sesungguhnya kamu telah bekerja dengan sungguh-sungguh menuju Tuhanmu, maka pasti kamu akan menemui-Nya.", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 7, "text": "فَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ بِیَمِینِهِۦ ۝٧", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فأما من أعطي صحيفة أعماله بيمينه، وهو مؤمن بربه، فسوف يحاسب حسابًا سهلا ويرجع إلى أهله في الجنة مسرورًا.", "isBasmala": false, "translation_en": "As for him who is given his book in his right hand.", "translation_id": "Adapun orang yang diberikan kitabnya dari sebelah kanannya,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 8, "text": "فَسَوۡفَ یُحَاسَبُ حِسَابࣰا یَسِیرࣰا ۝٨", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فأما من أعطي صحيفة أعماله بيمينه، وهو مؤمن بربه، فسوف يحاسب حسابًا سهلا ويرجع إلى أهله في الجنة مسرورًا.", "isBasmala": false, "translation_en": "He will have an easy settlement.", "translation_id": "maka dia akan diperiksa dengan pemeriksaan yang mudah,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 9, "text": "وَیَنقَلِبُ إِلَىٰۤ أَهۡلِهِۦ مَسۡرُورࣰا ۝٩", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فأما من أعطي صحيفة أعماله بيمينه، وهو مؤمن بربه، فسوف يحاسب حسابًا سهلا ويرجع إلى أهله في الجنة مسرورًا.", "isBasmala": false, "translation_en": "And will return to his family delighted.", "translation_id": "dan dia akan kembali kepada kaumnya (yang sama-sama beriman) dengan gembira.", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 10, "text": "وَأَمَّا مَنۡ أُوتِیَ كِتَـٰبَهُۥ وَرَاۤءَ ظَهۡرِهِۦ ۝١٠", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "وأمَّا مَن أُعطي صحيفة أعماله من وراء ظهره، وهو الكافر بالله، فسوف يدعو بالهلاك والثبور، ويدخل النار مقاسيًا حرها. إنه كان في أهله في الدنيا مسرورًا مغرورًا، لا يفكر في العواقب، إنه ظنَّ أن لن يرجع إلى خالقه حيا للحساب. بلى سيعيده الله كما بدأه ويجازيه على أعماله، إن ربه كان به بصيرًا عليمًا بحاله من يوم خلقه إلى أن بعثه.", "isBasmala": false, "translation_en": "But as for him who is given his book behind his back.", "translation_id": "Adapun orang-orang yang diberikan kitabnya dari belakang,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 11, "text": "فَسَوۡفَ یَدۡعُوا۟ ثُبُورࣰا ۝١١", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "وأمَّا مَن أُعطي صحيفة أعماله من وراء ظهره، وهو الكافر بالله، فسوف يدعو بالهلاك والثبور، ويدخل النار مقاسيًا حرها. إنه كان في أهله في الدنيا مسرورًا مغرورًا، لا يفكر في العواقب، إنه ظنَّ أن لن يرجع إلى خالقه حيا للحساب. بلى سيعيده الله كما بدأه ويجازيه على أعماله، إن ربه كان به بصيرًا عليمًا بحاله من يوم خلقه إلى أن بعثه.", "isBasmala": false, "translation_en": "He will call for death.", "translation_id": "maka dia akan berteriak: \"Celakalah aku\".", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 12, "text": "وَیَصۡلَىٰ سَعِیرًا ۝١٢", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "وأمَّا مَن أُعطي صحيفة أعماله من وراء ظهره، وهو الكافر بالله، فسوف يدعو بالهلاك والثبور، ويدخل النار مقاسيًا حرها. إنه كان في أهله في الدنيا مسرورًا مغرورًا، لا يفكر في العواقب، إنه ظنَّ أن لن يرجع إلى خالقه حيا للحساب. بلى سيعيده الله كما بدأه ويجازيه على أعماله، إن ربه كان به بصيرًا عليمًا بحاله من يوم خلقه إلى أن بعثه.", "isBasmala": false, "translation_en": "And will enter the Blaze.", "translation_id": "Dan dia akan masuk ke dalam api yang menyala-nyala (neraka).", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 13, "text": "إِنَّهُۥ كَانَ فِیۤ أَهۡلِهِۦ مَسۡرُورًا ۝١٣", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "وأمَّا مَن أُعطي صحيفة أعماله من وراء ظهره، وهو الكافر بالله، فسوف يدعو بالهلاك والثبور، ويدخل النار مقاسيًا حرها. إنه كان في أهله في الدنيا مسرورًا مغرورًا، لا يفكر في العواقب، إنه ظنَّ أن لن يرجع إلى خالقه حيا للحساب. بلى سيعيده الله كما بدأه ويجازيه على أعماله، إن ربه كان به بصيرًا عليمًا بحاله من يوم خلقه إلى أن بعثه.", "isBasmala": false, "translation_en": "He used to be happy among his family.", "translation_id": "Sesungguhnya dia dahulu (di dunia) bergembira di kalangan kaumnya (yang sama-sama kafir).", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 14, "text": "إِنَّهُۥ ظَنَّ أَن لَّن یَحُورَ ۝١٤", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "وأمَّا مَن أُعطي صحيفة أعماله من وراء ظهره، وهو الكافر بالله، فسوف يدعو بالهلاك والثبور، ويدخل النار مقاسيًا حرها. إنه كان في أهله في الدنيا مسرورًا مغرورًا، لا يفكر في العواقب، إنه ظنَّ أن لن يرجع إلى خالقه حيا للحساب. بلى سيعيده الله كما بدأه ويجازيه على أعماله، إن ربه كان به بصيرًا عليمًا بحاله من يوم خلقه إلى أن بعثه.", "isBasmala": false, "translation_en": "He thought he would never return.", "translation_id": "Sesungguhnya dia menyangka bahwa dia sekali-kali tidak akan kembali (kepada Tuhannya).", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 15, "text": "بَلَىٰۤۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِیرࣰا ۝١٥", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "وأمَّا مَن أُعطي صحيفة أعماله من وراء ظهره، وهو الكافر بالله، فسوف يدعو بالهلاك والثبور، ويدخل النار مقاسيًا حرها. إنه كان في أهله في الدنيا مسرورًا مغرورًا، لا يفكر في العواقب، إنه ظنَّ أن لن يرجع إلى خالقه حيا للحساب. بلى سيعيده الله كما بدأه ويجازيه على أعماله، إن ربه كان به بصيرًا عليمًا بحاله من يوم خلقه إلى أن بعثه.", "isBasmala": false, "translation_en": "In fact, his Lord was watching him.", "translation_id": "(Bukan demikian), yang benar, sesungguhnya Tuhannya selalu melihatnya.", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 16, "text": "فَلَاۤ أُقۡسِمُ بِٱلشَّفَقِ ۝١٦", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى باحمرار الأفق عند الغروب، وبالليل وما جمع من الدواب والحشرات والهوام وغير ذلك، وبالقمر إذا تكامل نوره، لتركبُنَّ- أيها الناس- أطوارا متعددة وأحوالا متباينة: من النطفة إلى العلقة إلى المضغة إلى نفخ الروح إلى الموت إلى البعث والنشور. ولا يجوز للمخلوق أن يقسم بغير الله، ولو فعل ذلك لأشرك.", "isBasmala": false, "translation_en": "I swear by the twilight.", "translation_id": "Maka sesungguhnya Aku bersumpah dengan cahaya merah di waktu senja,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 17, "text": "وَٱلَّیۡلِ وَمَا وَسَقَ ۝١٧", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى باحمرار الأفق عند الغروب، وبالليل وما جمع من الدواب والحشرات والهوام وغير ذلك، وبالقمر إذا تكامل نوره، لتركبُنَّ- أيها الناس- أطوارا متعددة وأحوالا متباينة: من النطفة إلى العلقة إلى المضغة إلى نفخ الروح إلى الموت إلى البعث والنشور. ولا يجوز للمخلوق أن يقسم بغير الله، ولو فعل ذلك لأشرك.", "isBasmala": false, "translation_en": "And by the night, and what it covers.", "translation_id": "dan dengan malam dan apa yang diselubunginya,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 18, "text": "وَٱلۡقَمَرِ إِذَا ٱتَّسَقَ ۝١٨", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى باحمرار الأفق عند الغروب، وبالليل وما جمع من الدواب والحشرات والهوام وغير ذلك، وبالقمر إذا تكامل نوره، لتركبُنَّ- أيها الناس- أطوارا متعددة وأحوالا متباينة: من النطفة إلى العلقة إلى المضغة إلى نفخ الروح إلى الموت إلى البعث والنشور. ولا يجوز للمخلوق أن يقسم بغير الله، ولو فعل ذلك لأشرك.", "isBasmala": false, "translation_en": "And by the moon, as it grows full.", "translation_id": "dan dengan bulan apabila jadi purnama,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 19, "text": "لَتَرۡكَبُنَّ طَبَقًا عَن طَبَقࣲ ۝١٩", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى باحمرار الأفق عند الغروب، وبالليل وما جمع من الدواب والحشرات والهوام وغير ذلك، وبالقمر إذا تكامل نوره، لتركبُنَّ- أيها الناس- أطوارا متعددة وأحوالا متباينة: من النطفة إلى العلقة إلى المضغة إلى نفخ الروح إلى الموت إلى البعث والنشور. ولا يجوز للمخلوق أن يقسم بغير الله، ولو فعل ذلك لأشرك.", "isBasmala": false, "translation_en": "You will mount stage by stage.", "translation_id": "sesungguhnya kamu melalui tingkat demi tingkat (dalam kehidupan),", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 20, "text": "فَمَا لَهُمۡ لَا یُؤۡمِنُونَ ۝٢٠", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فأيُّ شيء يمنعهم من الإيمان بالله واليوم الآخر بعد ما وُضِّحت لهم الآيات؟ وما لهم إذا قرئ عليهم القرآن لا يسجدون لله، ولا يسلِّمُون بما جاء فيه؟ إنما سجية الذين كفروا التكذيب ومخالفة الحق. والله أعلم بما يكتمون في صدورهم من العناد مع علمهم بأن ما جاء به القرآن حق، فبشرهم -أيها الرسول- بأن الله- عز وجل- قد أعدَّ لهم عذابًا موجعًا، لكن الذين آمنوا بالله ورسوله وأدَّوْا ما فرضه الله عليهم، لهم أجر في الآخرة غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "What is the matter with them that they do not believe?", "translation_id": "Mengapa mereka tidak mau beriman?", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 21, "text": "وَإِذَا قُرِئَ عَلَیۡهِمُ ٱلۡقُرۡءَانُ لَا یَ̅سۡ̅جُ̅دُ̅و̅نَ̅ ۝٢١ ۩", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فأيُّ شيء يمنعهم من الإيمان بالله واليوم الآخر بعد ما وُضِّحت لهم الآيات؟ وما لهم إذا قرئ عليهم القرآن لا يسجدون لله، ولا يسلِّمُون بما جاء فيه؟ إنما سجية الذين كفروا التكذيب ومخالفة الحق. والله أعلم بما يكتمون في صدورهم من العناد مع علمهم بأن ما جاء به القرآن حق، فبشرهم -أيها الرسول- بأن الله- عز وجل- قد أعدَّ لهم عذابًا موجعًا، لكن الذين آمنوا بالله ورسوله وأدَّوْا ما فرضه الله عليهم، لهم أجر في الآخرة غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "And when the Quran is read to them, they do not bow down?", "translation_id": "dan apabila Al Quran dibacakan kepada mereka, mereka tidak bersujud,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 22, "text": "بَلِ ٱلَّذِینَ كَفَرُوا۟ یُكَذِّبُونَ ۝٢٢", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فأيُّ شيء يمنعهم من الإيمان بالله واليوم الآخر بعد ما وُضِّحت لهم الآيات؟ وما لهم إذا قرئ عليهم القرآن لا يسجدون لله، ولا يسلِّمُون بما جاء فيه؟ إنما سجية الذين كفروا التكذيب ومخالفة الحق. والله أعلم بما يكتمون في صدورهم من العناد مع علمهم بأن ما جاء به القرآن حق، فبشرهم -أيها الرسول- بأن الله- عز وجل- قد أعدَّ لهم عذابًا موجعًا، لكن الذين آمنوا بالله ورسوله وأدَّوْا ما فرضه الله عليهم، لهم أجر في الآخرة غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "In fact, those who disbelieve are in denial.", "translation_id": "bahkan orang-orang kafir itu mendustakan(nya).", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 23, "text": "وَٱللَّهُ أَعۡلَمُ بِمَا یُوعُونَ ۝٢٣", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فأيُّ شيء يمنعهم من الإيمان بالله واليوم الآخر بعد ما وُضِّحت لهم الآيات؟ وما لهم إذا قرئ عليهم القرآن لا يسجدون لله، ولا يسلِّمُون بما جاء فيه؟ إنما سجية الذين كفروا التكذيب ومخالفة الحق. والله أعلم بما يكتمون في صدورهم من العناد مع علمهم بأن ما جاء به القرآن حق، فبشرهم -أيها الرسول- بأن الله- عز وجل- قد أعدَّ لهم عذابًا موجعًا، لكن الذين آمنوا بالله ورسوله وأدَّوْا ما فرضه الله عليهم، لهم أجر في الآخرة غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "But God knows what they hide inside.", "translation_id": "Padahal Allah mengetahui apa yang mereka sembunyikan (dalam hati mereka).", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 24, "text": "فَبَشِّرۡهُم بِعَذَابٍ أَلِیمٍ ۝٢٤", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فأيُّ شيء يمنعهم من الإيمان بالله واليوم الآخر بعد ما وُضِّحت لهم الآيات؟ وما لهم إذا قرئ عليهم القرآن لا يسجدون لله، ولا يسلِّمُون بما جاء فيه؟ إنما سجية الذين كفروا التكذيب ومخالفة الحق. والله أعلم بما يكتمون في صدورهم من العناد مع علمهم بأن ما جاء به القرآن حق، فبشرهم -أيها الرسول- بأن الله- عز وجل- قد أعدَّ لهم عذابًا موجعًا، لكن الذين آمنوا بالله ورسوله وأدَّوْا ما فرضه الله عليهم، لهم أجر في الآخرة غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "So inform them of a painful punishment.", "translation_id": "Maka beri kabar gembiralah mereka dengan azab yang pedih,", "manzil": 7, "manzil_display": ""}, {"sura": 84, "sura_name": "الإنشقاق", "revelation": "Makkiyah", "aya": 25, "text": "إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمۡ أَجۡرٌ غَیۡرُ مَمۡنُونِۭ ۝٢٥", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فأيُّ شيء يمنعهم من الإيمان بالله واليوم الآخر بعد ما وُضِّحت لهم الآيات؟ وما لهم إذا قرئ عليهم القرآن لا يسجدون لله، ولا يسلِّمُون بما جاء فيه؟ إنما سجية الذين كفروا التكذيب ومخالفة الحق. والله أعلم بما يكتمون في صدورهم من العناد مع علمهم بأن ما جاء به القرآن حق، فبشرهم -أيها الرسول- بأن الله- عز وجل- قد أعدَّ لهم عذابًا موجعًا، لكن الذين آمنوا بالله ورسوله وأدَّوْا ما فرضه الله عليهم، لهم أجر في الآخرة غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "Except those who believe and do good deeds; they will have an undiminished reward.", "translation_id": "tetapi orang-orang yang beriman dan beramal saleh, bagi mereka pahala yang tidak putus-putusnya.", "manzil": 7, "manzil_display": ""}], "590": [{"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلسَّمَاۤءِ ذَاتِ ٱلۡبُرُوجِ ۝١", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر، وبيوم القيامة الذي وعد الله الخلق أن يجمعهم فيه، وشاهد يشهد، ومشهود يشهد عليه. ويقسم الله- سبحانه- بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير الله، فإن القسم بغير الله شرك. لُعن الذين شَقُّوا في الأرض شقًا عظيمًا؛ لتعذيب المؤمنين، وأوقدوا النار الشديدة ذات الوَقود، إذ هم قعود على الأخدود ملازمون له، وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضورٌ. وما أخذوهم بمثل هذا العقاب الشديد إلا أن كانوا مؤمنين بالله العزيز الذي لا يغالَب، الحميد في أقواله وأفعاله وأوصافه، الذي له ملك السماوات والأرض، وهو- سبحانه- على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "By the sky with the constellations.", "translation_id": "Demi langit yang mempunyai gugusan bintang,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 2, "text": "وَٱلۡیَوۡمِ ٱلۡمَوۡعُودِ ۝٢", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر، وبيوم القيامة الذي وعد الله الخلق أن يجمعهم فيه، وشاهد يشهد، ومشهود يشهد عليه. ويقسم الله- سبحانه- بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير الله، فإن القسم بغير الله شرك. لُعن الذين شَقُّوا في الأرض شقًا عظيمًا؛ لتعذيب المؤمنين، وأوقدوا النار الشديدة ذات الوَقود، إذ هم قعود على الأخدود ملازمون له، وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضورٌ. وما أخذوهم بمثل هذا العقاب الشديد إلا أن كانوا مؤمنين بالله العزيز الذي لا يغالَب، الحميد في أقواله وأفعاله وأوصافه، الذي له ملك السماوات والأرض، وهو- سبحانه- على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "And by the Promised Day.", "translation_id": "dan hari yang dijanjikan,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 3, "text": "وَشَاهِدࣲ وَمَشۡهُودࣲ ۝٣", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر، وبيوم القيامة الذي وعد الله الخلق أن يجمعهم فيه، وشاهد يشهد، ومشهود يشهد عليه. ويقسم الله- سبحانه- بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير الله، فإن القسم بغير الله شرك. لُعن الذين شَقُّوا في الأرض شقًا عظيمًا؛ لتعذيب المؤمنين، وأوقدوا النار الشديدة ذات الوَقود، إذ هم قعود على الأخدود ملازمون له، وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضورٌ. وما أخذوهم بمثل هذا العقاب الشديد إلا أن كانوا مؤمنين بالله العزيز الذي لا يغالَب، الحميد في أقواله وأفعاله وأوصافه، الذي له ملك السماوات والأرض، وهو- سبحانه- على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "And by the witness and the witnessed.", "translation_id": "dan yang menyaksikan dan yang disaksikan.", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 4, "text": "قُتِلَ أَصۡحَـٰبُ ٱلۡأُخۡدُودِ ۝٤", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر، وبيوم القيامة الذي وعد الله الخلق أن يجمعهم فيه، وشاهد يشهد، ومشهود يشهد عليه. ويقسم الله- سبحانه- بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير الله، فإن القسم بغير الله شرك. لُعن الذين شَقُّوا في الأرض شقًا عظيمًا؛ لتعذيب المؤمنين، وأوقدوا النار الشديدة ذات الوَقود، إذ هم قعود على الأخدود ملازمون له، وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضورٌ. وما أخذوهم بمثل هذا العقاب الشديد إلا أن كانوا مؤمنين بالله العزيز الذي لا يغالَب، الحميد في أقواله وأفعاله وأوصافه، الذي له ملك السماوات والأرض، وهو- سبحانه- على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "Destroyed were the People of the Trench.", "translation_id": "Binasa dan terlaknatlah orang-orang yang membuat parit,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 5, "text": "ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ ۝٥", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر، وبيوم القيامة الذي وعد الله الخلق أن يجمعهم فيه، وشاهد يشهد، ومشهود يشهد عليه. ويقسم الله- سبحانه- بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير الله، فإن القسم بغير الله شرك. لُعن الذين شَقُّوا في الأرض شقًا عظيمًا؛ لتعذيب المؤمنين، وأوقدوا النار الشديدة ذات الوَقود، إذ هم قعود على الأخدود ملازمون له، وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضورٌ. وما أخذوهم بمثل هذا العقاب الشديد إلا أن كانوا مؤمنين بالله العزيز الذي لا يغالَب، الحميد في أقواله وأفعاله وأوصافه، الذي له ملك السماوات والأرض، وهو- سبحانه- على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "The fire supplied with fuel.", "translation_id": "yang berapi (dinyalakan dengan) kayu bakar,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 6, "text": "إِذۡ هُمۡ عَلَیۡهَا قُعُودࣱ ۝٦", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر، وبيوم القيامة الذي وعد الله الخلق أن يجمعهم فيه، وشاهد يشهد، ومشهود يشهد عليه. ويقسم الله- سبحانه- بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير الله، فإن القسم بغير الله شرك. لُعن الذين شَقُّوا في الأرض شقًا عظيمًا؛ لتعذيب المؤمنين، وأوقدوا النار الشديدة ذات الوَقود، إذ هم قعود على الأخدود ملازمون له، وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضورٌ. وما أخذوهم بمثل هذا العقاب الشديد إلا أن كانوا مؤمنين بالله العزيز الذي لا يغالَب، الحميد في أقواله وأفعاله وأوصافه، الذي له ملك السماوات والأرض، وهو- سبحانه- على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "While they sat around it.", "translation_id": "ketika mereka duduk di sekitarnya,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 7, "text": "وَهُمۡ عَلَىٰ مَا یَفۡعَلُونَ بِٱلۡمُؤۡمِنِینَ شُهُودࣱ ۝٧", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر، وبيوم القيامة الذي وعد الله الخلق أن يجمعهم فيه، وشاهد يشهد، ومشهود يشهد عليه. ويقسم الله- سبحانه- بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير الله، فإن القسم بغير الله شرك. لُعن الذين شَقُّوا في الأرض شقًا عظيمًا؛ لتعذيب المؤمنين، وأوقدوا النار الشديدة ذات الوَقود، إذ هم قعود على الأخدود ملازمون له، وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضورٌ. وما أخذوهم بمثل هذا العقاب الشديد إلا أن كانوا مؤمنين بالله العزيز الذي لا يغالَب، الحميد في أقواله وأفعاله وأوصافه، الذي له ملك السماوات والأرض، وهو- سبحانه- على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "And were witnessing what they did to the believers.", "translation_id": "sedang mereka menyaksikan apa yang mereka perbuat terhadap orang-orang yang beriman.", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 8, "text": "وَمَا نَقَمُوا۟ مِنۡهُمۡ إِلَّاۤ أَن یُؤۡمِنُوا۟ بِٱللَّهِ ٱلۡعَزِیزِ ٱلۡحَمِیدِ ۝٨", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر، وبيوم القيامة الذي وعد الله الخلق أن يجمعهم فيه، وشاهد يشهد، ومشهود يشهد عليه. ويقسم الله- سبحانه- بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير الله، فإن القسم بغير الله شرك. لُعن الذين شَقُّوا في الأرض شقًا عظيمًا؛ لتعذيب المؤمنين، وأوقدوا النار الشديدة ذات الوَقود، إذ هم قعود على الأخدود ملازمون له، وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضورٌ. وما أخذوهم بمثل هذا العقاب الشديد إلا أن كانوا مؤمنين بالله العزيز الذي لا يغالَب، الحميد في أقواله وأفعاله وأوصافه، الذي له ملك السماوات والأرض، وهو- سبحانه- على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "They begrudged them only because they believed in God the Almighty, the Praiseworthy.", "translation_id": "Dan mereka tidak menyiksa orang-orang mukmin itu melainkan karena orang-orang mukmin itu beriman kepada Allah Yang Maha Perkasa lagi Maha Terpuji,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 9, "text": "ٱلَّذِی لَهُۥ مُلۡكُ ٱلسَّمَـٰوَ ٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ ۝٩", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله تعالى بالسماء ذات المنازل التي تمر بها الشمس والقمر، وبيوم القيامة الذي وعد الله الخلق أن يجمعهم فيه، وشاهد يشهد، ومشهود يشهد عليه. ويقسم الله- سبحانه- بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير الله، فإن القسم بغير الله شرك. لُعن الذين شَقُّوا في الأرض شقًا عظيمًا؛ لتعذيب المؤمنين، وأوقدوا النار الشديدة ذات الوَقود، إذ هم قعود على الأخدود ملازمون له، وهم على ما يفعلون بالمؤمنين من تنكيل وتعذيب حضورٌ. وما أخذوهم بمثل هذا العقاب الشديد إلا أن كانوا مؤمنين بالله العزيز الذي لا يغالَب، الحميد في أقواله وأفعاله وأوصافه، الذي له ملك السماوات والأرض، وهو- سبحانه- على كل شيء شهيد، لا يخفى عليه شيء.", "isBasmala": false, "translation_en": "To Whom belongs the sovereignty of the heavens and the earth. God is witness over everything.", "translation_id": "Yang mempunyai kerajaan langit dan bumi; dan Allah Maha Menyaksikan segala sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 10, "text": "إِنَّ ٱلَّذِینَ فَتَنُوا۟ ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ ثُمَّ لَمۡ یَتُوبُوا۟ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِیقِ ۝١٠", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن الذين حرقوا المؤمنين والمؤمنات بالنار؛ ليصرفوهم عن دين الله، ثم لم يتوبوا، فلهم في الآخرة عذاب جهنم، ولهم العذاب الشديد المحرق.", "isBasmala": false, "translation_en": "Those who tempt the believers, men and women, then do not repent; for them is the punishment of Hell; for them is the punishment of Burning.", "translation_id": "Sesungguhnya orang-orang yang mendatangkan cobaan kepada orang-orang yang mukmin laki-laki dan perempuan kemudian mereka tidak bertaubat, maka bagi mereka azab Jahannam dan bagi mereka azab (neraka) yang membakar.", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 11, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمۡ جَنَّـٰتࣱ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۚ ذَ ٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِیرُ ۝١١", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن الذين صدَّقوا الله ورسوله وعملوا الأعمال الصالحات، لهم جنات تجري من تحت قصورها الأنهار، ذلك الفوز العظيم.", "isBasmala": false, "translation_en": "Those who believe and do righteous deeds will have Gardens beneath which rivers flow. That is the great triumph.", "translation_id": "Sesungguhnya orang-orang yang beriman dan mengerjakan amal-amal yang saleh bagi mereka surga yang mengalir di bawahnya sungai-sungai; itulah keberuntungan yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 12, "text": "إِنَّ بَطۡشَ رَبِّكَ لَشَدِیدٌ ۝١٢", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن انتقام ربك من أعدائه وعذابه لهم لَعظيم شديد، إنه هو يُبدئ الخلق ثم يعيده، وهو الغفور لمن تاب، كثير المودة والمحبة لأوليائه، صاحب العرشِ المجيدُ الذي بلغ المنتهى في الفضل والكرم، فَعَّال لما يريد، لا يمتنع عليه شيء يريده.", "isBasmala": false, "translation_en": "The onslaught of your Lord is severe.", "translation_id": "Sesungguhnya azab Tuhanmu benar-benar keras.", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 13, "text": "إِنَّهُۥ هُوَ یُبۡدِئُ وَیُعِیدُ ۝١٣", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن انتقام ربك من أعدائه وعذابه لهم لَعظيم شديد، إنه هو يُبدئ الخلق ثم يعيده، وهو الغفور لمن تاب، كثير المودة والمحبة لأوليائه، صاحب العرشِ المجيدُ الذي بلغ المنتهى في الفضل والكرم، فَعَّال لما يريد، لا يمتنع عليه شيء يريده.", "isBasmala": false, "translation_en": "It is He who begins and repeats.", "translation_id": "Sesungguhnya Dialah Yang menciptakan (makhluk) dari permulaan dan menghidupkannya (kembali).", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 14, "text": "وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ ۝١٤", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن انتقام ربك من أعدائه وعذابه لهم لَعظيم شديد، إنه هو يُبدئ الخلق ثم يعيده، وهو الغفور لمن تاب، كثير المودة والمحبة لأوليائه، صاحب العرشِ المجيدُ الذي بلغ المنتهى في الفضل والكرم، فَعَّال لما يريد، لا يمتنع عليه شيء يريده.", "isBasmala": false, "translation_en": "And He is the Forgiving, the Loving.", "translation_id": "Dialah Yang Maha Pengampun lagi Maha Pengasih,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 15, "text": "ذُو ٱلۡعَرۡشِ ٱلۡمَجِیدُ ۝١٥", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن انتقام ربك من أعدائه وعذابه لهم لَعظيم شديد، إنه هو يُبدئ الخلق ثم يعيده، وهو الغفور لمن تاب، كثير المودة والمحبة لأوليائه، صاحب العرشِ المجيدُ الذي بلغ المنتهى في الفضل والكرم، فَعَّال لما يريد، لا يمتنع عليه شيء يريده.", "isBasmala": false, "translation_en": "Possessor of the Glorious Throne.", "translation_id": "yang mempunyai 'Arsy, lagi Maha Mulia,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 16, "text": "فَعَّالࣱ لِّمَا یُرِیدُ ۝١٦", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن انتقام ربك من أعدائه وعذابه لهم لَعظيم شديد، إنه هو يُبدئ الخلق ثم يعيده، وهو الغفور لمن تاب، كثير المودة والمحبة لأوليائه، صاحب العرشِ المجيدُ الذي بلغ المنتهى في الفضل والكرم، فَعَّال لما يريد، لا يمتنع عليه شيء يريده.", "isBasmala": false, "translation_en": "Doer of whatever He wills.", "translation_id": "Maha Kuasa berbuat apa yang dikehendaki-Nya.", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 17, "text": "هَلۡ أَتَىٰكَ حَدِیثُ ٱلۡجُنُودِ ۝١٧", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "هل بلغك -أيها الرسول- خبر الجموع الكافرة المكذبة لأنبيائها، فرعون وثمود، وما حلَّ بهم من العذاب والنكال، لم يعتبر القوم بذلك، بل الذين كفروا في تكذيب متواصل كدأب مَن قبلهم، والله قد أحاط بهم علما وقدرة، لا يخفى عليه منهم ومن أعمالهم شيء. وليس القرآن كما زعم المكذبون المشركون بأنه شعر وسحر، فكذَّبوا به، بل هو قرآن عظيم كريم، في لوح محفوظ، لا يناله تبديل ولا تحريف.", "isBasmala": false, "translation_en": "Has there come to you the story of the legions?", "translation_id": "Sudahkah datang kepadamu berita kaum-kaum penentang,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 18, "text": "فِرۡعَوۡنَ وَثَمُودَ ۝١٨", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "هل بلغك -أيها الرسول- خبر الجموع الكافرة المكذبة لأنبيائها، فرعون وثمود، وما حلَّ بهم من العذاب والنكال، لم يعتبر القوم بذلك، بل الذين كفروا في تكذيب متواصل كدأب مَن قبلهم، والله قد أحاط بهم علما وقدرة، لا يخفى عليه منهم ومن أعمالهم شيء. وليس القرآن كما زعم المكذبون المشركون بأنه شعر وسحر، فكذَّبوا به، بل هو قرآن عظيم كريم، في لوح محفوظ، لا يناله تبديل ولا تحريف.", "isBasmala": false, "translation_en": "Of Pharaoh and Thamood?", "translation_id": "(yaitu kaum) Fir'aun dan (kaum) Tsamud?", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 19, "text": "بَلِ ٱلَّذِینَ كَفَرُوا۟ فِی تَكۡذِیبࣲ ۝١٩", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "هل بلغك -أيها الرسول- خبر الجموع الكافرة المكذبة لأنبيائها، فرعون وثمود، وما حلَّ بهم من العذاب والنكال، لم يعتبر القوم بذلك، بل الذين كفروا في تكذيب متواصل كدأب مَن قبلهم، والله قد أحاط بهم علما وقدرة، لا يخفى عليه منهم ومن أعمالهم شيء. وليس القرآن كما زعم المكذبون المشركون بأنه شعر وسحر، فكذَّبوا به، بل هو قرآن عظيم كريم، في لوح محفوظ، لا يناله تبديل ولا تحريف.", "isBasmala": false, "translation_en": "In fact, those who disbelieve are in denial.", "translation_id": "Sesungguhnya orang-orang kafir selalu mendustakan,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 20, "text": "وَٱللَّهُ مِن وَرَاۤىِٕهِم مُّحِیطُۢ ۝٢٠", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "هل بلغك -أيها الرسول- خبر الجموع الكافرة المكذبة لأنبيائها، فرعون وثمود، وما حلَّ بهم من العذاب والنكال، لم يعتبر القوم بذلك، بل الذين كفروا في تكذيب متواصل كدأب مَن قبلهم، والله قد أحاط بهم علما وقدرة، لا يخفى عليه منهم ومن أعمالهم شيء. وليس القرآن كما زعم المكذبون المشركون بأنه شعر وسحر، فكذَّبوا به، بل هو قرآن عظيم كريم، في لوح محفوظ، لا يناله تبديل ولا تحريف.", "isBasmala": false, "translation_en": "And God encloses them from beyond.", "translation_id": "padahal Allah mengepung mereka dari belakang mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 21, "text": "بَلۡ هُوَ قُرۡءَانࣱ مَّجِیدࣱ ۝٢١", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "هل بلغك -أيها الرسول- خبر الجموع الكافرة المكذبة لأنبيائها، فرعون وثمود، وما حلَّ بهم من العذاب والنكال، لم يعتبر القوم بذلك، بل الذين كفروا في تكذيب متواصل كدأب مَن قبلهم، والله قد أحاط بهم علما وقدرة، لا يخفى عليه منهم ومن أعمالهم شيء. وليس القرآن كما زعم المكذبون المشركون بأنه شعر وسحر، فكذَّبوا به، بل هو قرآن عظيم كريم، في لوح محفوظ، لا يناله تبديل ولا تحريف.", "isBasmala": false, "translation_en": "In fact, it is a Glorious Quran.", "translation_id": "Bahkan yang didustakan mereka itu ialah Al Quran yang mulia,", "manzil": 7, "manzil_display": ""}, {"sura": 85, "sura_name": "البروج", "revelation": "Makkiyah", "aya": 22, "text": "فِی لَوۡحࣲ مَّحۡفُوظِۭ ۝٢٢", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "هل بلغك -أيها الرسول- خبر الجموع الكافرة المكذبة لأنبيائها، فرعون وثمود، وما حلَّ بهم من العذاب والنكال، لم يعتبر القوم بذلك، بل الذين كفروا في تكذيب متواصل كدأب مَن قبلهم، والله قد أحاط بهم علما وقدرة، لا يخفى عليه منهم ومن أعمالهم شيء. وليس القرآن كما زعم المكذبون المشركون بأنه شعر وسحر، فكذَّبوا به، بل هو قرآن عظيم كريم، في لوح محفوظ، لا يناله تبديل ولا تحريف.", "isBasmala": false, "translation_en": "In a Preserved Tablet.", "translation_id": "yang (tersimpan) dalam Lauh Mahfuzh.", "manzil": 7, "manzil_display": ""}], "591": [{"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلسَّمَاۤءِ وَٱلطَّارِقِ ۝١", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله سبحانه بالسماء والنجم الذي يطرق ليلا وما أدراك ما عِظَمُ هذا النجم؟ هو النجم المضيء المتوهِّج. ما كل نفس إلا أوكل بها مَلَك رقيب يحفظ عليها أعمالها لتحاسب عليها يوم القيامة.", "isBasmala": false, "translation_en": "By the sky and at-Tariq.", "translation_id": "Demi langit dan yang datang pada malam hari,", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 2, "text": "وَمَاۤ أَدۡرَىٰكَ مَا ٱلطَّارِقُ ۝٢", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله سبحانه بالسماء والنجم الذي يطرق ليلا وما أدراك ما عِظَمُ هذا النجم؟ هو النجم المضيء المتوهِّج. ما كل نفس إلا أوكل بها مَلَك رقيب يحفظ عليها أعمالها لتحاسب عليها يوم القيامة.", "isBasmala": false, "translation_en": "But what will let you know what at-Tariq is?", "translation_id": "tahukah kamu apakah yang datang pada malam hari itu?", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 3, "text": "ٱلنَّجۡمُ ٱلثَّاقِبُ ۝٣", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله سبحانه بالسماء والنجم الذي يطرق ليلا وما أدراك ما عِظَمُ هذا النجم؟ هو النجم المضيء المتوهِّج. ما كل نفس إلا أوكل بها مَلَك رقيب يحفظ عليها أعمالها لتحاسب عليها يوم القيامة.", "isBasmala": false, "translation_en": "The Piercing Star.", "translation_id": "(yaitu) bintang yang cahayanya menembus,", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 4, "text": "إِن كُلُّ نَفۡسࣲ لَّمَّا عَلَیۡهَا حَافِظࣱ ۝٤", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "أقسم الله سبحانه بالسماء والنجم الذي يطرق ليلا وما أدراك ما عِظَمُ هذا النجم؟ هو النجم المضيء المتوهِّج. ما كل نفس إلا أوكل بها مَلَك رقيب يحفظ عليها أعمالها لتحاسب عليها يوم القيامة.", "isBasmala": false, "translation_en": "There is no soul without a Protector over it.", "translation_id": "tidak ada suatu jiwapun (diri) melainkan ada penjaganya.", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 5, "text": "فَلۡیَنظُرِ ٱلۡإِنسَـٰنُ مِمَّ خُلِقَ ۝٥", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فلينظر الإنسان المنكر للبعث مِمَّ خُلِقَ؟ ليعلم أن إعادة خلق الإنسان ليست أصعب من خلقه أوّلا خلق من منيٍّ منصبٍّ بسرعة في الرحم، يخرج من بين صلب الرجل وصدر المرأة. إن الذي خلق الإنسان من هذا الماء لَقادر على رجعه إلى الحياة بعد الموت.", "isBasmala": false, "translation_en": "Let man consider what he was created from.", "translation_id": "Maka hendaklah manusia memperhatikan dari apakah dia diciptakan?", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 6, "text": "خُلِقَ مِن مَّاۤءࣲ دَافِقࣲ ۝٦", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فلينظر الإنسان المنكر للبعث مِمَّ خُلِقَ؟ ليعلم أن إعادة خلق الإنسان ليست أصعب من خلقه أوّلا خلق من منيٍّ منصبٍّ بسرعة في الرحم، يخرج من بين صلب الرجل وصدر المرأة. إن الذي خلق الإنسان من هذا الماء لَقادر على رجعه إلى الحياة بعد الموت.", "isBasmala": false, "translation_en": "He was created from gushing liquid.", "translation_id": "Dia diciptakan dari air yang dipancarkan,", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 7, "text": "یَخۡرُجُ مِنۢ بَیۡنِ ٱلصُّلۡبِ وَٱلتَّرَاۤىِٕبِ ۝٧", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فلينظر الإنسان المنكر للبعث مِمَّ خُلِقَ؟ ليعلم أن إعادة خلق الإنسان ليست أصعب من خلقه أوّلا خلق من منيٍّ منصبٍّ بسرعة في الرحم، يخرج من بين صلب الرجل وصدر المرأة. إن الذي خلق الإنسان من هذا الماء لَقادر على رجعه إلى الحياة بعد الموت.", "isBasmala": false, "translation_en": "Issuing from between the backbone and the breastbones.", "translation_id": "yang keluar dari antara tulang sulbi laki-laki dan tulang dada perempuan.", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 8, "text": "إِنَّهُۥ عَلَىٰ رَجۡعِهِۦ لَقَادِرࣱ ۝٨", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "فلينظر الإنسان المنكر للبعث مِمَّ خُلِقَ؟ ليعلم أن إعادة خلق الإنسان ليست أصعب من خلقه أوّلا خلق من منيٍّ منصبٍّ بسرعة في الرحم، يخرج من بين صلب الرجل وصدر المرأة. إن الذي خلق الإنسان من هذا الماء لَقادر على رجعه إلى الحياة بعد الموت.", "isBasmala": false, "translation_en": "He is certainly able to return him.", "translation_id": "Sesungguhnya Allah benar-benar kuasa untuk mengembalikannya (hidup sesudah mati).", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 9, "text": "یَوۡمَ تُبۡلَى ٱلسَّرَاۤىِٕرُ ۝٩", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "يوم تُخْتَبر السرائر فيما أخفته، ويُمَيَّز الصالح منها من الفاسد، فما للإنسان من قوة يدفع بها عن نفسه، وما له من ناصر يدفع عنه عذاب الله.", "isBasmala": false, "translation_en": "On the Day when the secrets are disclosed.", "translation_id": "Pada hari dinampakkan segala rahasia,", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 10, "text": "فَمَا لَهُۥ مِن قُوَّةࣲ وَلَا نَاصِرࣲ ۝١٠", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "يوم تُخْتَبر السرائر فيما أخفته، ويُمَيَّز الصالح منها من الفاسد، فما للإنسان من قوة يدفع بها عن نفسه، وما له من ناصر يدفع عنه عذاب الله.", "isBasmala": false, "translation_en": "He will have no strength, and no supporter.", "translation_id": "maka sekali-kali tidak ada bagi manusia itu suatu kekuatanpun dan tidak (pula) seorang penolong.", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 11, "text": "وَٱلسَّمَاۤءِ ذَاتِ ٱلرَّجۡعِ ۝١١", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "والسماء ذات المطر المتكرر، والأرض ذات التشقق بما يتخللها من نبات، إن القرآن لقول فصل بَيْنَ الحق والباطل، وما هو بالهزل. ولا يجوز للمخلوق أن يقسم بغير الله، وإلا فقد أشرك.", "isBasmala": false, "translation_en": "By the sky that returns.", "translation_id": "Demi langit yang mengandung hujan", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 12, "text": "وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ ۝١٢", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "والسماء ذات المطر المتكرر، والأرض ذات التشقق بما يتخللها من نبات، إن القرآن لقول فصل بَيْنَ الحق والباطل، وما هو بالهزل. ولا يجوز للمخلوق أن يقسم بغير الله، وإلا فقد أشرك.", "isBasmala": false, "translation_en": "And the earth that cracks open.", "translation_id": "dan bumi yang mempunyai tumbuh-tumbuhan,", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 13, "text": "إِنَّهُۥ لَقَوۡلࣱ فَصۡلࣱ ۝١٣", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "والسماء ذات المطر المتكرر، والأرض ذات التشقق بما يتخللها من نبات، إن القرآن لقول فصل بَيْنَ الحق والباطل، وما هو بالهزل. ولا يجوز للمخلوق أن يقسم بغير الله، وإلا فقد أشرك.", "isBasmala": false, "translation_en": "It is a Decisive Word.", "translation_id": "sesungguhnya Al Quran itu benar-benar firman yang memisahkan antara yang hak dan yang bathil.", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 14, "text": "وَمَا هُوَ بِٱلۡهَزۡلِ ۝١٤", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "والسماء ذات المطر المتكرر، والأرض ذات التشقق بما يتخللها من نبات، إن القرآن لقول فصل بَيْنَ الحق والباطل، وما هو بالهزل. ولا يجوز للمخلوق أن يقسم بغير الله، وإلا فقد أشرك.", "isBasmala": false, "translation_en": "It is no joke.", "translation_id": "dan sekali-kali bukanlah dia senda gurau.", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 15, "text": "إِنَّهُمۡ یَكِیدُونَ كَیۡدࣰا ۝١٥", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن المكذبين للرسول صلى الله عليه وسلم، وللقرآن، يكيدون ويدبرون؛ ليدفعوا بكيدهم الحق ويؤيدوا الباطل، وأكيد كيدًا لإظهار الحق، ولو كره الكافرون، فلا تستعجل لهم -أيها الرسول- بطلب إنزال العقاب بهم، بل أمهلهم وأنظرهم قليلا ولا تستعجل لهم، وسترى ما يحلُّ بهم من العذاب والنكال والعقوبة والهلاك.", "isBasmala": false, "translation_en": "They plot and scheme.", "translation_id": "Sesungguhnya orang kafir itu merencanakan tipu daya yang jahat dengan sebenar-benarnya.", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 16, "text": "وَأَكِیدُ كَیۡدࣰا ۝١٦", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن المكذبين للرسول صلى الله عليه وسلم، وللقرآن، يكيدون ويدبرون؛ ليدفعوا بكيدهم الحق ويؤيدوا الباطل، وأكيد كيدًا لإظهار الحق، ولو كره الكافرون، فلا تستعجل لهم -أيها الرسول- بطلب إنزال العقاب بهم، بل أمهلهم وأنظرهم قليلا ولا تستعجل لهم، وسترى ما يحلُّ بهم من العذاب والنكال والعقوبة والهلاك.", "isBasmala": false, "translation_en": "But I plot and scheme.", "translation_id": "Dan Akupun membuat rencana (pula) dengan sebenar-benarnya.", "manzil": 7, "manzil_display": ""}, {"sura": 86, "sura_name": "الطارق", "revelation": "Makkiyah", "aya": 17, "text": "فَمَهِّلِ ٱلۡكَـٰفِرِینَ أَمۡهِلۡهُمۡ رُوَیۡدَۢا ۝١٧", "juz": 30, "hizb": "(*¾ ح 59*)", "tafsir": "إن المكذبين للرسول صلى الله عليه وسلم، وللقرآن، يكيدون ويدبرون؛ ليدفعوا بكيدهم الحق ويؤيدوا الباطل، وأكيد كيدًا لإظهار الحق، ولو كره الكافرون، فلا تستعجل لهم -أيها الرسول- بطلب إنزال العقاب بهم، بل أمهلهم وأنظرهم قليلا ولا تستعجل لهم، وسترى ما يحلُّ بهم من العذاب والنكال والعقوبة والهلاك.", "isBasmala": false, "translation_en": "Therefore, give the blasphemers respite, a brief respite.", "translation_id": "Karena itu beri tangguhlah orang-orang kafir itu yaitu beri tangguhlah mereka itu barang sebentar.", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 1, "text": "۞ سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى ۝١", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "نَزِّه اسم ربك الأعلى عن الشريك والنقائص تنزيهًا يليق بعظمته سبحانه، الذي خلق المخلوقات، فأتقن خلقها، وأحسنه، والذي قدَّر جميع المقدرات، فهدى كل خلق إلى ما يناسبه، والذي أنبت الكلأ الأخضر، فجعله بعد ذلك هشيمًا جافًا متغيرًا.", "isBasmala": false, "translation_en": "Praise the Name of your Lord, the Most High.", "translation_id": "Sucikanlah nama Tuhanmu Yang Maha Tingi,", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 2, "text": "ٱلَّذِی خَلَقَ فَسَوَّىٰ ۝٢", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "نَزِّه اسم ربك الأعلى عن الشريك والنقائص تنزيهًا يليق بعظمته سبحانه، الذي خلق المخلوقات، فأتقن خلقها، وأحسنه، والذي قدَّر جميع المقدرات، فهدى كل خلق إلى ما يناسبه، والذي أنبت الكلأ الأخضر، فجعله بعد ذلك هشيمًا جافًا متغيرًا.", "isBasmala": false, "translation_en": "He who creates and regulates.", "translation_id": "yang menciptakan, dan menyempurnakan (penciptaan-Nya),", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 3, "text": "وَٱلَّذِی قَدَّرَ فَهَدَىٰ ۝٣", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "نَزِّه اسم ربك الأعلى عن الشريك والنقائص تنزيهًا يليق بعظمته سبحانه، الذي خلق المخلوقات، فأتقن خلقها، وأحسنه، والذي قدَّر جميع المقدرات، فهدى كل خلق إلى ما يناسبه، والذي أنبت الكلأ الأخضر، فجعله بعد ذلك هشيمًا جافًا متغيرًا.", "isBasmala": false, "translation_en": "He who measures and guides.", "translation_id": "dan yang menentukan kadar (masing-masing) dan memberi petunjuk,", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 4, "text": "وَٱلَّذِیۤ أَخۡرَجَ ٱلۡمَرۡعَىٰ ۝٤", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "نَزِّه اسم ربك الأعلى عن الشريك والنقائص تنزيهًا يليق بعظمته سبحانه، الذي خلق المخلوقات، فأتقن خلقها، وأحسنه، والذي قدَّر جميع المقدرات، فهدى كل خلق إلى ما يناسبه، والذي أنبت الكلأ الأخضر، فجعله بعد ذلك هشيمًا جافًا متغيرًا.", "isBasmala": false, "translation_en": "He who produces the pasture.", "translation_id": "dan yang menumbuhkan rumput-rumputan,", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 5, "text": "فَجَعَلَهُۥ غُثَاۤءً أَحۡوَىٰ ۝٥", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "نَزِّه اسم ربك الأعلى عن الشريك والنقائص تنزيهًا يليق بعظمته سبحانه، الذي خلق المخلوقات، فأتقن خلقها، وأحسنه، والذي قدَّر جميع المقدرات، فهدى كل خلق إلى ما يناسبه، والذي أنبت الكلأ الأخضر، فجعله بعد ذلك هشيمًا جافًا متغيرًا.", "isBasmala": false, "translation_en": "And then turns it into light debris.", "translation_id": "lalu dijadikan-Nya rumput-rumput itu kering kehitam-hitaman.", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 6, "text": "سَنُقۡرِئُكَ فَلَا تَنسَىٰۤ ۝٦", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "سنقرئك -أيها الرسول- هذا القرآن قراءة لا تنساها، إلا ما شاء الله مما اقتضت حكمته أن ينسيه لمصلحة يعلمها. إنه - سبحانه- يعلم الجهر من القول والعمل، وما يخفى منهما.", "isBasmala": false, "translation_en": "We will make you read, so do not forget.", "translation_id": "Kami akan membacakan (Al Quran) kepadamu (Muhammad) maka kamu tidak akan lupa,", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 7, "text": "إِلَّا مَا شَاۤءَ ٱللَّهُۚ إِنَّهُۥ یَعۡلَمُ ٱلۡجَهۡرَ وَمَا یَخۡفَىٰ ۝٧", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "سنقرئك -أيها الرسول- هذا القرآن قراءة لا تنساها، إلا ما شاء الله مما اقتضت حكمته أن ينسيه لمصلحة يعلمها. إنه - سبحانه- يعلم الجهر من القول والعمل، وما يخفى منهما.", "isBasmala": false, "translation_en": "Except what God wills. He knows what is declared, and what is hidden.", "translation_id": "kecuali kalau Allah menghendaki. Sesungguhnya Dia mengetahui yang terang dan yang tersembunyi.", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 8, "text": "وَنُیَسِّرُكَ لِلۡیُسۡرَىٰ ۝٨", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ونيسرك لليسرى في جميع أمورك، ومن ذلك تسهيل تَلَقِّي أعباء الرسالة، وجعل دينك يسرًا لا عسر فيه.", "isBasmala": false, "translation_en": "We will ease you into the Easy Way.", "translation_id": "dan Kami akan memberi kamu taufik ke jalan yang mudah,", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 9, "text": "فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ ۝٩", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "فعظ قومك -أيها الرسول- حسبما يسرناه لك بما يوحى إليك، واهدهم إلى ما فيه خيرهم. وخُصَّ بالتذكير من يرجى منه التذكُّر، ولا تتعب نفسك في تذكير من لا يورثه التذكر إلا عتوًّا ونفورًا.", "isBasmala": false, "translation_en": "So remind, if reminding helps.", "translation_id": "oleh sebab itu berikanlah peringatan karena peringatan itu bermanfaat,", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 10, "text": "سَیَذَّكَّرُ مَن یَخۡشَىٰ ۝١٠", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "سيتعظ الذي يخاف ربه، ويبتعد عن الذكرى الأشقى الذي لا يخشى ربه، الذي سيدخل نار جهنم العظمى يقاسي حرَّها، ثم لا يموت فيها فيستريح، ولا يحيا حياة تنفعه.", "isBasmala": false, "translation_en": "The reverent will remember.", "translation_id": "orang yang takut (kepada Allah) akan mendapat pelajaran,", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 11, "text": "وَیَتَجَنَّبُهَا ٱلۡأَشۡقَى ۝١١", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "سيتعظ الذي يخاف ربه، ويبتعد عن الذكرى الأشقى الذي لا يخشى ربه، الذي سيدخل نار جهنم العظمى يقاسي حرَّها، ثم لا يموت فيها فيستريح، ولا يحيا حياة تنفعه.", "isBasmala": false, "translation_en": "But the wretched will avoid it.", "translation_id": "dan orang-orang yang celaka (kafir) akan menjauhinya.", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 12, "text": "ٱلَّذِی یَصۡلَى ٱلنَّارَ ٱلۡكُبۡرَىٰ ۝١٢", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "سيتعظ الذي يخاف ربه، ويبتعد عن الذكرى الأشقى الذي لا يخشى ربه، الذي سيدخل نار جهنم العظمى يقاسي حرَّها، ثم لا يموت فيها فيستريح، ولا يحيا حياة تنفعه.", "isBasmala": false, "translation_en": "He who will enter the Gigantic Fire.", "translation_id": "(Yaitu) orang yang akan memasuki api yang besar (neraka).", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 13, "text": "ثُمَّ لَا یَمُوتُ فِیهَا وَلَا یَحۡیَىٰ ۝١٣", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "سيتعظ الذي يخاف ربه، ويبتعد عن الذكرى الأشقى الذي لا يخشى ربه، الذي سيدخل نار جهنم العظمى يقاسي حرَّها، ثم لا يموت فيها فيستريح، ولا يحيا حياة تنفعه.", "isBasmala": false, "translation_en": "Where he will neither die, nor live.", "translation_id": "Kemudian dia tidak akan mati di dalamnya dan tidak (pula) hidup.", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 14, "text": "قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ ۝١٤", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "قد فاز مَن طهر نفسه من الأخلاق السيئة، وذكر الله، فوحَّده ودعاه وعمل بما يرضيه، وأقام الصلاة في أوقاتها؛ ابتغاء رضوان الله وامتثالا لشرعه.", "isBasmala": false, "translation_en": "Successful is he who purifies himself.", "translation_id": "Sesungguhnya beruntunglah orang yang membersihkan diri (dengan beriman),", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 15, "text": "وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ ۝١٥", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "قد فاز مَن طهر نفسه من الأخلاق السيئة، وذكر الله، فوحَّده ودعاه وعمل بما يرضيه، وأقام الصلاة في أوقاتها؛ ابتغاء رضوان الله وامتثالا لشرعه.", "isBasmala": false, "translation_en": "And mentions the name of his Lord, and prays.", "translation_id": "dan dia ingat nama Tuhannya, lalu dia sembahyang.", "manzil": 7, "manzil_display": ""}], "592": [{"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 16, "text": "بَلۡ تُؤۡثِرُونَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا ۝١٦", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "إنكم -أيها الناس- تفضِّلون زينة الحياة الدنيا على نعيم الآخرة.", "isBasmala": false, "translation_en": "But you prefer the present life.", "translation_id": "Tetapi kamu (orang-orang kafir) memilih kehidupan duniawi.", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 17, "text": "وَٱلۡـَٔاخِرَةُ خَیۡرࣱ وَأَبۡقَىٰۤ ۝١٧", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "والدار الآخرة بما فيها من النعيم المقيم، خير من الدنيا وأبقى.", "isBasmala": false, "translation_en": "Though the Hereafter is better, and more lasting.", "translation_id": "Sedang kehidupan akhirat adalah lebih baik dan lebih kekal.", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 18, "text": "إِنَّ هَـٰذَا لَفِی ٱلصُّحُفِ ٱلۡأُولَىٰ ۝١٨", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "إن ما أخبرتم به في هذه السورة هو مما ثبت معناه في الصُّحف التي أنزلت قبل القرآن، وهي صُحف إبراهيم وموسى عليهما السلام.", "isBasmala": false, "translation_en": "This is in the former scriptures.", "translation_id": "Sesungguhnya ini benar-benar terdapat dalam kitab-kitab yang dahulu,", "manzil": 7, "manzil_display": ""}, {"sura": 87, "sura_name": "الأعلى", "revelation": "Makkiyah", "aya": 19, "text": "صُحُفِ إِبۡرَ ٰهِیمَ وَمُوسَىٰ ۝١٩", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "إن ما أخبرتم به في هذه السورة هو مما ثبت معناه في الصُّحف التي أنزلت قبل القرآن، وهي صُحف إبراهيم وموسى عليهما السلام.", "isBasmala": false, "translation_en": "The Scriptures of Abraham and Moses.", "translation_id": "(yaitu) Kitab-kitab Ibrahim dan Musa", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 1, "text": "هَلۡ أَتَىٰكَ حَدِیثُ ٱلۡغَـٰشِیَةِ ۝١", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "هل أتاك -أيها الرسول- خبر القيامة التي تغشى الناس بأهوالها؟", "isBasmala": false, "translation_en": "Has there come to you the news of the overwhelming?", "translation_id": "Sudah datangkah kepadamu berita (tentang) hari pembalasan?", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 2, "text": "وُجُوهࣱ یَوۡمَىِٕذٍ خَـٰشِعَةٌ ۝٢", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه الكفار يومئذ ذليلة بالعذاب، مجهدة بالعمل متعبة، تصيبها نار شديدة التوهج، تُسقى من عين شديدة الحرارة. ليس لأصحاب النار طعام إلا من نبت ذي شوك لاصق بالأرض، وهو مِن شر الطعام وأخبثه، لا يُسْمن بدن صاحبه من الهُزال، ولا يسدُّ جوعه ورمقه.", "isBasmala": false, "translation_en": "Faces on that Day will be shamed.", "translation_id": "Banyak muka pada hari itu tunduk terhina,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 3, "text": "عَامِلَةࣱ نَّاصِبَةࣱ ۝٣", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه الكفار يومئذ ذليلة بالعذاب، مجهدة بالعمل متعبة، تصيبها نار شديدة التوهج، تُسقى من عين شديدة الحرارة. ليس لأصحاب النار طعام إلا من نبت ذي شوك لاصق بالأرض، وهو مِن شر الطعام وأخبثه، لا يُسْمن بدن صاحبه من الهُزال، ولا يسدُّ جوعه ورمقه.", "isBasmala": false, "translation_en": "Laboring and exhausted.", "translation_id": "bekerja keras lagi kepayahan,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 4, "text": "تَصۡلَىٰ نَارًا حَامِیَةࣰ ۝٤", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه الكفار يومئذ ذليلة بالعذاب، مجهدة بالعمل متعبة، تصيبها نار شديدة التوهج، تُسقى من عين شديدة الحرارة. ليس لأصحاب النار طعام إلا من نبت ذي شوك لاصق بالأرض، وهو مِن شر الطعام وأخبثه، لا يُسْمن بدن صاحبه من الهُزال، ولا يسدُّ جوعه ورمقه.", "isBasmala": false, "translation_en": "Roasting in a scorching Fire.", "translation_id": "memasuki api yang sangat panas (neraka),", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 5, "text": "تُسۡقَىٰ مِنۡ عَیۡنٍ ءَانِیَةࣲ ۝٥", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه الكفار يومئذ ذليلة بالعذاب، مجهدة بالعمل متعبة، تصيبها نار شديدة التوهج، تُسقى من عين شديدة الحرارة. ليس لأصحاب النار طعام إلا من نبت ذي شوك لاصق بالأرض، وهو مِن شر الطعام وأخبثه، لا يُسْمن بدن صاحبه من الهُزال، ولا يسدُّ جوعه ورمقه.", "isBasmala": false, "translation_en": "Given to drink from a flaming spring.", "translation_id": "diberi minum (dengan air) dari sumber yang sangat panas.", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 6, "text": "لَّیۡسَ لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِیعࣲ ۝٦", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه الكفار يومئذ ذليلة بالعذاب، مجهدة بالعمل متعبة، تصيبها نار شديدة التوهج، تُسقى من عين شديدة الحرارة. ليس لأصحاب النار طعام إلا من نبت ذي شوك لاصق بالأرض، وهو مِن شر الطعام وأخبثه، لا يُسْمن بدن صاحبه من الهُزال، ولا يسدُّ جوعه ورمقه.", "isBasmala": false, "translation_en": "They will have no food except thorns.", "translation_id": "Mereka tiada memperoleh makanan selain dari pohon yang berduri,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 7, "text": "لَّا یُسۡمِنُ وَلَا یُغۡنِی مِن جُوعࣲ ۝٧", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه الكفار يومئذ ذليلة بالعذاب، مجهدة بالعمل متعبة، تصيبها نار شديدة التوهج، تُسقى من عين شديدة الحرارة. ليس لأصحاب النار طعام إلا من نبت ذي شوك لاصق بالأرض، وهو مِن شر الطعام وأخبثه، لا يُسْمن بدن صاحبه من الهُزال، ولا يسدُّ جوعه ورمقه.", "isBasmala": false, "translation_en": "That neither nourishes, nor satisfies hunger.", "translation_id": "yang tidak menggemukkan dan tidak pula menghilangkan lapar.", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 8, "text": "وُجُوهࣱ یَوۡمَىِٕذࣲ نَّاعِمَةࣱ ۝٨", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه المؤمنين يوم القيامة ذات نعمة؛ لسعيها في الدنيا بالطاعات راضية في الآخرة، في جنة رفيعة المكان والمكانة، لا تسمع فيها كلمة لغو واحدة، فيها عين تتدفق مياهها، فيها سرر عالية وأكواب معدة للشاربين، ووسائد مصفوفة، الواحدة جنب الأخرى، وبُسُط كثيرة مفروشة.", "isBasmala": false, "translation_en": "Faces on that Day will be joyful.", "translation_id": "Banyak muka pada hari itu berseri-seri,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 9, "text": "لِّسَعۡیِهَا رَاضِیَةࣱ ۝٩", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه المؤمنين يوم القيامة ذات نعمة؛ لسعيها في الدنيا بالطاعات راضية في الآخرة، في جنة رفيعة المكان والمكانة، لا تسمع فيها كلمة لغو واحدة، فيها عين تتدفق مياهها، فيها سرر عالية وأكواب معدة للشاربين، ووسائد مصفوفة، الواحدة جنب الأخرى، وبُسُط كثيرة مفروشة.", "isBasmala": false, "translation_en": "Satisfied with their endeavor.", "translation_id": "merasa senang karena usahanya,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 10, "text": "فِی جَنَّةٍ عَالِیَةࣲ ۝١٠", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه المؤمنين يوم القيامة ذات نعمة؛ لسعيها في الدنيا بالطاعات راضية في الآخرة، في جنة رفيعة المكان والمكانة، لا تسمع فيها كلمة لغو واحدة، فيها عين تتدفق مياهها، فيها سرر عالية وأكواب معدة للشاربين، ووسائد مصفوفة، الواحدة جنب الأخرى، وبُسُط كثيرة مفروشة.", "isBasmala": false, "translation_en": "In a lofty Garden.", "translation_id": "dalam surga yang tinggi,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 11, "text": "لَّا تَسۡمَعُ فِیهَا لَـٰغِیَةࣰ ۝١١", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه المؤمنين يوم القيامة ذات نعمة؛ لسعيها في الدنيا بالطاعات راضية في الآخرة، في جنة رفيعة المكان والمكانة، لا تسمع فيها كلمة لغو واحدة، فيها عين تتدفق مياهها، فيها سرر عالية وأكواب معدة للشاربين، ووسائد مصفوفة، الواحدة جنب الأخرى، وبُسُط كثيرة مفروشة.", "isBasmala": false, "translation_en": "In it you will hear no nonsense.", "translation_id": "tidak kamu dengar di dalamnya perkataan yang tidak berguna.", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 12, "text": "فِیهَا عَیۡنࣱ جَارِیَةࣱ ۝١٢", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه المؤمنين يوم القيامة ذات نعمة؛ لسعيها في الدنيا بالطاعات راضية في الآخرة، في جنة رفيعة المكان والمكانة، لا تسمع فيها كلمة لغو واحدة، فيها عين تتدفق مياهها، فيها سرر عالية وأكواب معدة للشاربين، ووسائد مصفوفة، الواحدة جنب الأخرى، وبُسُط كثيرة مفروشة.", "isBasmala": false, "translation_en": "In it is a flowing spring.", "translation_id": "Di dalamnya ada mata air yang mengalir.", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 13, "text": "فِیهَا سُرُرࣱ مَّرۡفُوعَةࣱ ۝١٣", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه المؤمنين يوم القيامة ذات نعمة؛ لسعيها في الدنيا بالطاعات راضية في الآخرة، في جنة رفيعة المكان والمكانة، لا تسمع فيها كلمة لغو واحدة، فيها عين تتدفق مياهها، فيها سرر عالية وأكواب معدة للشاربين، ووسائد مصفوفة، الواحدة جنب الأخرى، وبُسُط كثيرة مفروشة.", "isBasmala": false, "translation_en": "In it are raised beds.", "translation_id": "Di dalamnya ada takhta-takhta yang ditinggikan,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 14, "text": "وَأَكۡوَابࣱ مَّوۡضُوعَةࣱ ۝١٤", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه المؤمنين يوم القيامة ذات نعمة؛ لسعيها في الدنيا بالطاعات راضية في الآخرة، في جنة رفيعة المكان والمكانة، لا تسمع فيها كلمة لغو واحدة، فيها عين تتدفق مياهها، فيها سرر عالية وأكواب معدة للشاربين، ووسائد مصفوفة، الواحدة جنب الأخرى، وبُسُط كثيرة مفروشة.", "isBasmala": false, "translation_en": "And cups set in place.", "translation_id": "dan gelas-gelas yang terletak (di dekatnya),", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 15, "text": "وَنَمَارِقُ مَصۡفُوفَةࣱ ۝١٥", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه المؤمنين يوم القيامة ذات نعمة؛ لسعيها في الدنيا بالطاعات راضية في الآخرة، في جنة رفيعة المكان والمكانة، لا تسمع فيها كلمة لغو واحدة، فيها عين تتدفق مياهها، فيها سرر عالية وأكواب معدة للشاربين، ووسائد مصفوفة، الواحدة جنب الأخرى، وبُسُط كثيرة مفروشة.", "isBasmala": false, "translation_en": "And cushions set in rows.", "translation_id": "dan bantal-bantal sandaran yang tersusun,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 16, "text": "وَزَرَابِیُّ مَبۡثُوثَةٌ ۝١٦", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وجوه المؤمنين يوم القيامة ذات نعمة؛ لسعيها في الدنيا بالطاعات راضية في الآخرة، في جنة رفيعة المكان والمكانة، لا تسمع فيها كلمة لغو واحدة، فيها عين تتدفق مياهها، فيها سرر عالية وأكواب معدة للشاربين، ووسائد مصفوفة، الواحدة جنب الأخرى، وبُسُط كثيرة مفروشة.", "isBasmala": false, "translation_en": "And carpets spread around.", "translation_id": "dan permadani-permadani yang terhampar.", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 17, "text": "أَفَلَا یَنظُرُونَ إِلَى ٱلۡإِبِلِ كَیۡفَ خُلِقَتۡ ۝١٧", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "أفلا ينظر الكافرون المكذِّبون إلى الإبل: كيف خُلِقَت هذا الخلق العجيب؟ وإلى السماء كيف رُفِعَت هذا الرَّفع البديع؟ وإلى الجبال كيف نُصبت، فحصل بها الثبات للأرض والاستقرار؟ وإلى الأرض كيف بُسِطت ومُهِّدت؟", "isBasmala": false, "translation_en": "Do they not look at the camels-how they are created?", "translation_id": "Maka apakah mereka tidak memperhatikan unta bagaimana dia diciptakan,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 18, "text": "وَإِلَى ٱلسَّمَاۤءِ كَیۡفَ رُفِعَتۡ ۝١٨", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "أفلا ينظر الكافرون المكذِّبون إلى الإبل: كيف خُلِقَت هذا الخلق العجيب؟ وإلى السماء كيف رُفِعَت هذا الرَّفع البديع؟ وإلى الجبال كيف نُصبت، فحصل بها الثبات للأرض والاستقرار؟ وإلى الأرض كيف بُسِطت ومُهِّدت؟", "isBasmala": false, "translation_en": "And at the sky-how it is raised?", "translation_id": "Dan langit, bagaimana ia ditinggikan?", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 19, "text": "وَإِلَى ٱلۡجِبَالِ كَیۡفَ نُصِبَتۡ ۝١٩", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "أفلا ينظر الكافرون المكذِّبون إلى الإبل: كيف خُلِقَت هذا الخلق العجيب؟ وإلى السماء كيف رُفِعَت هذا الرَّفع البديع؟ وإلى الجبال كيف نُصبت، فحصل بها الثبات للأرض والاستقرار؟ وإلى الأرض كيف بُسِطت ومُهِّدت؟", "isBasmala": false, "translation_en": "And at the mountains-how they are installed?", "translation_id": "Dan gunung-gunung bagaimana ia ditegakkan?", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 20, "text": "وَإِلَى ٱلۡأَرۡضِ كَیۡفَ سُطِحَتۡ ۝٢٠", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "أفلا ينظر الكافرون المكذِّبون إلى الإبل: كيف خُلِقَت هذا الخلق العجيب؟ وإلى السماء كيف رُفِعَت هذا الرَّفع البديع؟ وإلى الجبال كيف نُصبت، فحصل بها الثبات للأرض والاستقرار؟ وإلى الأرض كيف بُسِطت ومُهِّدت؟", "isBasmala": false, "translation_en": "And at the earth-how it is spread out?", "translation_id": "Dan bumi bagaimana ia dihamparkan?", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 21, "text": "فَذَكِّرۡ إِنَّمَاۤ أَنتَ مُذَكِّرࣱ ۝٢١", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "فعِظْ -أيها الرسول- المعرضين بما أُرْسِلْتَ به إليهم، ولا تحزن على إعراضهم، إنما أنت واعظ لهم، ليس عليك إكراههم على الإيمان.", "isBasmala": false, "translation_en": "So remind. You are only a reminder.", "translation_id": "Maka berilah peringatan, karena sesungguhnya kamu hanyalah orang yang memberi peringatan.", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 22, "text": "لَّسۡتَ عَلَیۡهِم بِمُصَۣیۡطِرٍ ۝٢٢", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "فعِظْ -أيها الرسول- المعرضين بما أُرْسِلْتَ به إليهم، ولا تحزن على إعراضهم، إنما أنت واعظ لهم، ليس عليك إكراههم على الإيمان.", "isBasmala": false, "translation_en": "You have no control over them.", "translation_id": "Kamu bukanlah orang yang berkuasa atas mereka,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 23, "text": "إِلَّا مَن تَوَلَّىٰ وَكَفَرَ ۝٢٣", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "لكن الذي أعرض عن التذكير والموعظة وأصرَّ على كفره، فيعذبه الله العذاب الشديد في النار.", "isBasmala": false, "translation_en": "But whoever turns away and disbelieves.", "translation_id": "tetapi orang yang berpaling dan kafir,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 24, "text": "فَیُعَذِّبُهُ ٱللَّهُ ٱلۡعَذَابَ ٱلۡأَكۡبَرَ ۝٢٤", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "لكن الذي أعرض عن التذكير والموعظة وأصرَّ على كفره، فيعذبه الله العذاب الشديد في النار.", "isBasmala": false, "translation_en": "God will punish him with the greatest punishment.", "translation_id": "maka Allah akan mengazabnya dengan azab yang besar.", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 25, "text": "إِنَّ إِلَیۡنَاۤ إِیَابَهُمۡ ۝٢٥", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "إنَّ إلينا مرجعهم بعد الموت، ثم إن علينا جزاءهم على ما عملوا.", "isBasmala": false, "translation_en": "To Us is their return.", "translation_id": "Sesungguhnya kepada Kami-lah kembali mereka,", "manzil": 7, "manzil_display": ""}, {"sura": 88, "sura_name": "الغاشية", "revelation": "Makkiyah", "aya": 26, "text": "ثُمَّ إِنَّ عَلَیۡنَا حِسَابَهُم ۝٢٦", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "إنَّ إلينا مرجعهم بعد الموت، ثم إن علينا جزاءهم على ما عملوا.", "isBasmala": false, "translation_en": "Then upon Us rests their reckoning.", "translation_id": "kemudian sesungguhnya kewajiban Kami-lah menghisab mereka.", "manzil": 7, "manzil_display": ""}], "593": [{"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلۡفَجۡرِ ۝١", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "أقسم الله سبحانه بوقت الفجر، والليالي العشر الأوَل من ذي الحجة وما شرفت به، وبكل شفع وفرد، وبالليل إذا يَسْري بظلامه، أليس في الأقسام المذكورة مَقْنَع لذي عقل؟", "isBasmala": false, "translation_en": "By the daybreak.", "translation_id": "Demi fajar,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 2, "text": "وَلَیَالٍ عَشۡرࣲ ۝٢", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "أقسم الله سبحانه بوقت الفجر، والليالي العشر الأوَل من ذي الحجة وما شرفت به، وبكل شفع وفرد، وبالليل إذا يَسْري بظلامه، أليس في الأقسام المذكورة مَقْنَع لذي عقل؟", "isBasmala": false, "translation_en": "And ten nights.", "translation_id": "dan malam yang sepuluh,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 3, "text": "وَٱلشَّفۡعِ وَٱلۡوَتۡرِ ۝٣", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "أقسم الله سبحانه بوقت الفجر، والليالي العشر الأوَل من ذي الحجة وما شرفت به، وبكل شفع وفرد، وبالليل إذا يَسْري بظلامه، أليس في الأقسام المذكورة مَقْنَع لذي عقل؟", "isBasmala": false, "translation_en": "And the even and the odd.", "translation_id": "dan yang genap dan yang ganjil,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 4, "text": "وَٱلَّیۡلِ إِذَا یَسۡرِ ۝٤", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "أقسم الله سبحانه بوقت الفجر، والليالي العشر الأوَل من ذي الحجة وما شرفت به، وبكل شفع وفرد، وبالليل إذا يَسْري بظلامه، أليس في الأقسام المذكورة مَقْنَع لذي عقل؟", "isBasmala": false, "translation_en": "And the night as it recedes.", "translation_id": "dan malam bila berlalu.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 5, "text": "هَلۡ فِی ذَ ٰلِكَ قَسَمࣱ لِّذِی حِجۡرٍ ۝٥", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "أقسم الله سبحانه بوقت الفجر، والليالي العشر الأوَل من ذي الحجة وما شرفت به، وبكل شفع وفرد، وبالليل إذا يَسْري بظلامه، أليس في الأقسام المذكورة مَقْنَع لذي عقل؟", "isBasmala": false, "translation_en": "Is there in this an oath for a rational person?", "translation_id": "Pada yang demikian itu terdapat sumpah (yang dapat diterima) oleh orang-orang yang berakal.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 6, "text": "أَلَمۡ تَرَ كَیۡفَ فَعَلَ رَبُّكَ بِعَادٍ ۝٦", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ألم تر -أيها الرسول- كيف فعل ربُّك بقوم عاد، قبيلة إرم، ذات القوة والأبنية المرفوعة على الأعمدة، التي لم يُخلق مثلها في البلاد في عِظَم الأجساد وقوة البأس؟", "isBasmala": false, "translation_en": "Have you not seen how your Lord dealt with Aad?", "translation_id": "Apakah kamu tidak memperhatikan bagaimana Tuhanmu berbuat terhadap kaum 'Aad?", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 7, "text": "إِرَمَ ذَاتِ ٱلۡعِمَادِ ۝٧", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ألم تر -أيها الرسول- كيف فعل ربُّك بقوم عاد، قبيلة إرم، ذات القوة والأبنية المرفوعة على الأعمدة، التي لم يُخلق مثلها في البلاد في عِظَم الأجساد وقوة البأس؟", "isBasmala": false, "translation_en": "Erum of the pillars.", "translation_id": "(yaitu) penduduk Iram yang mempunyai bangunan-bangunan yang tinggi,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 8, "text": "ٱلَّتِی لَمۡ یُخۡلَقۡ مِثۡلُهَا فِی ٱلۡبِلَـٰدِ ۝٨", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ألم تر -أيها الرسول- كيف فعل ربُّك بقوم عاد، قبيلة إرم، ذات القوة والأبنية المرفوعة على الأعمدة، التي لم يُخلق مثلها في البلاد في عِظَم الأجساد وقوة البأس؟", "isBasmala": false, "translation_en": "The like of which was never created in the land.", "translation_id": "yang belum pernah dibangun (suatu kota) seperti itu, di negeri-negeri lain,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 9, "text": "وَثَمُودَ ٱلَّذِینَ جَابُوا۟ ٱلصَّخۡرَ بِٱلۡوَادِ ۝٩", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وكيف فعل بثمود قوم صالح الذين قطعوا الصخر بالوادي واتخذوا منه بيوتًا؟", "isBasmala": false, "translation_en": "And Thamood-those who carved the rocks in the valley.", "translation_id": "dan kaum Tsamud yang memotong batu-batu besar di lembah,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 10, "text": "وَفِرۡعَوۡنَ ذِی ٱلۡأَوۡتَادِ ۝١٠", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وكيف فعل بفرعون مَلِك \"مصر\"، صاحب الجنود الذين ثبَّتوا مُلْكه، وقوَّوا له أمره؟", "isBasmala": false, "translation_en": "And Pharaoh of the Stakes.", "translation_id": "dan kaum Fir'aun yang mempunyai pasak-pasak (tentara yang banyak),", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 11, "text": "ٱلَّذِینَ طَغَوۡا۟ فِی ٱلۡبِلَـٰدِ ۝١١", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "هؤلاء الذين استبدُّوا، وظلموا في بلاد الله، فأكثروا فيها بظلمهم الفساد، فصب عليهم ربُّك عذابا شديدا. إنَّ ربك -أيها الرسول- لبالمرصاد لمن يعصيه، يمهله قليلا ثم يأخذه أخْذَ عزيز مقتدر.", "isBasmala": false, "translation_en": "Those who committed excesses in the lands.", "translation_id": "yang berbuat sewenang-wenang dalam negeri,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 12, "text": "فَأَكۡثَرُوا۟ فِیهَا ٱلۡفَسَادَ ۝١٢", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "هؤلاء الذين استبدُّوا، وظلموا في بلاد الله، فأكثروا فيها بظلمهم الفساد، فصب عليهم ربُّك عذابا شديدا. إنَّ ربك -أيها الرسول- لبالمرصاد لمن يعصيه، يمهله قليلا ثم يأخذه أخْذَ عزيز مقتدر.", "isBasmala": false, "translation_en": "And spread much corruption therein.", "translation_id": "lalu mereka berbuat banyak kerusakan dalam negeri itu,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 13, "text": "فَصَبَّ عَلَیۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ ۝١٣", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "هؤلاء الذين استبدُّوا، وظلموا في بلاد الله، فأكثروا فيها بظلمهم الفساد، فصب عليهم ربُّك عذابا شديدا. إنَّ ربك -أيها الرسول- لبالمرصاد لمن يعصيه، يمهله قليلا ثم يأخذه أخْذَ عزيز مقتدر.", "isBasmala": false, "translation_en": "So your Lord poured down upon them a scourge of punishment.", "translation_id": "karena itu Tuhanmu menimpakan kepada mereka cemeti azab,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 14, "text": "إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ ۝١٤", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "هؤلاء الذين استبدُّوا، وظلموا في بلاد الله، فأكثروا فيها بظلمهم الفساد، فصب عليهم ربُّك عذابا شديدا. إنَّ ربك -أيها الرسول- لبالمرصاد لمن يعصيه، يمهله قليلا ثم يأخذه أخْذَ عزيز مقتدر.", "isBasmala": false, "translation_en": "Your Lord is on the lookout.", "translation_id": "sesungguhnya Tuhanmu benar-benar mengawasi.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 15, "text": "فَأَمَّا ٱلۡإِنسَـٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَیَقُولُ رَبِّیۤ أَكۡرَمَنِ ۝١٥", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "فأما الإنسان إذا ما اختبره ربه بالنعمة، وبسط له رزقه، وجعله في أطيب عيش، فيظن أن ذلك لكرامته عند ربه، فيقول: ربي أكرمن.", "isBasmala": false, "translation_en": "As for man, whenever his Lord tests him, and honors him, and prospers him, he says, \"My Lord has honored me.\"", "translation_id": "Adapun manusia apabila Tuhannya mengujinya lalu dia dimuliakan-Nya dan diberi-Nya kesenangan, maka dia akan berkata: \"Tuhanku telah memuliakanku\".", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 16, "text": "وَأَمَّاۤ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَیۡهِ رِزۡقَهُۥ فَیَقُولُ رَبِّیۤ أَهَـٰنَنِ ۝١٦", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "وأما إذا ما اختبره، فضيَّق عليه رزقه، فيظن أن ذلك لهوانه على الله، فيقول: ربي أهانن.", "isBasmala": false, "translation_en": "But whenever He tests him, and restricts his livelihood for him, he says, \"My Lord has insulted me.\"", "translation_id": "Adapun bila Tuhannya mengujinya lalu membatasi rezekinya maka dia berkata: \"Tuhanku menghinakanku\".", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 17, "text": "كَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡیَتِیمَ ۝١٧", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ليس الأمر كما يظن هذا الإنسان، بل الإكرام بطاعة الله، والإهانة بمعصيته، وأنتم لا تكرمون اليتيم، ولا تحسنون معاملته، ولا يَحُثُّ بعضكم بعضًا على إطعام المسكين، وتأكلون حقوق الآخرين في الميراث أكلا شديدًا، وتحبون المال حبًا مفرطًا.", "isBasmala": false, "translation_en": "Not at all. But you do not honor the orphan.", "translation_id": "Sekali-kali tidak (demikian), sebenarnya kamu tidak memuliakan anak yatim,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 18, "text": "وَلَا تَحَـٰۤضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِینِ ۝١٨", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ليس الأمر كما يظن هذا الإنسان، بل الإكرام بطاعة الله، والإهانة بمعصيته، وأنتم لا تكرمون اليتيم، ولا تحسنون معاملته، ولا يَحُثُّ بعضكم بعضًا على إطعام المسكين، وتأكلون حقوق الآخرين في الميراث أكلا شديدًا، وتحبون المال حبًا مفرطًا.", "isBasmala": false, "translation_en": "And you do not urge the feeding of the poor.", "translation_id": "dan kamu tidak saling mengajak memberi makan orang miskin,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 19, "text": "وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلࣰا لَّمࣰّا ۝١٩", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ليس الأمر كما يظن هذا الإنسان، بل الإكرام بطاعة الله، والإهانة بمعصيته، وأنتم لا تكرمون اليتيم، ولا تحسنون معاملته، ولا يَحُثُّ بعضكم بعضًا على إطعام المسكين، وتأكلون حقوق الآخرين في الميراث أكلا شديدًا، وتحبون المال حبًا مفرطًا.", "isBasmala": false, "translation_en": "And you devour inheritance with all greed.", "translation_id": "dan kamu memakan harta pusaka dengan cara mencampur baurkan (yang halal dan yang bathil),", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 20, "text": "وَتُحِبُّونَ ٱلۡمَالَ حُبࣰّا جَمࣰّا ۝٢٠", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ليس الأمر كما يظن هذا الإنسان، بل الإكرام بطاعة الله، والإهانة بمعصيته، وأنتم لا تكرمون اليتيم، ولا تحسنون معاملته، ولا يَحُثُّ بعضكم بعضًا على إطعام المسكين، وتأكلون حقوق الآخرين في الميراث أكلا شديدًا، وتحبون المال حبًا مفرطًا.", "isBasmala": false, "translation_en": "And you love wealth with immense love.", "translation_id": "dan kamu mencintai harta benda dengan kecintaan yang berlebihan.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 21, "text": "كَلَّاۤۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكࣰّا دَكࣰّا ۝٢١", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ما هكذا ينبغي أن يكون حالكم. فإذا زلزلت الأرض وكَسَّر بعضُها بعضًا، وجاء ربُّك لفصل القضاء بين خلقه، والملائكة صفوفًا صفوفًا، وجيء في ذلك اليوم العظيم بجهنم، يومئذ يتعظ الكافر ويتوب، وكيف ينفعه الاتعاظ والتوبة، وقد فرَّط فيهما في الدنيا، وفات أوانهما؟", "isBasmala": false, "translation_en": "No-when the earth is leveled, pounded, and crushed.", "translation_id": "Jangan (berbuat demikian). Apabila bumi digoncangkan berturut-turut,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 22, "text": "وَجَاۤءَ رَبُّكَ وَٱلۡمَلَكُ صَفࣰّا صَفࣰّا ۝٢٢", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ما هكذا ينبغي أن يكون حالكم. فإذا زلزلت الأرض وكَسَّر بعضُها بعضًا، وجاء ربُّك لفصل القضاء بين خلقه، والملائكة صفوفًا صفوفًا، وجيء في ذلك اليوم العظيم بجهنم، يومئذ يتعظ الكافر ويتوب، وكيف ينفعه الاتعاظ والتوبة، وقد فرَّط فيهما في الدنيا، وفات أوانهما؟", "isBasmala": false, "translation_en": "And your Lord comes, with the angels, row after row.", "translation_id": "dan datanglah Tuhanmu; sedang malaikat berbaris-baris.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 23, "text": "وَجِا۟یۤءَ یَوۡمَىِٕذِۭ بِجَهَنَّمَۚ یَوۡمَىِٕذࣲ یَتَذَكَّرُ ٱلۡإِنسَـٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ ۝٢٣", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ما هكذا ينبغي أن يكون حالكم. فإذا زلزلت الأرض وكَسَّر بعضُها بعضًا، وجاء ربُّك لفصل القضاء بين خلقه، والملائكة صفوفًا صفوفًا، وجيء في ذلك اليوم العظيم بجهنم، يومئذ يتعظ الكافر ويتوب، وكيف ينفعه الاتعاظ والتوبة، وقد فرَّط فيهما في الدنيا، وفات أوانهما؟", "isBasmala": false, "translation_en": "And on that Day, Hell is brought forward. On that Day, man will remember, but how will remembrance avail him?", "translation_id": "Dan pada hari itu diperlihatkan neraka Jahannam; dan pada hari itu ingatlah manusia, akan tetapi tidak berguna lagi mengingat itu baginya.", "manzil": 7, "manzil_display": ""}], "594": [{"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 24, "text": "یَقُولُ یَـٰلَیۡتَنِی قَدَّمۡتُ لِحَیَاتِی ۝٢٤", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "يقول: يا ليتني قدَّمتُ في الدنيا من الأعمال ما ينفعني لحياتي في الآخرة.", "isBasmala": false, "translation_en": "He will say, \"If only I had forwarded for my life.\"", "translation_id": "Dia mengatakan: \"Alangkah baiknya kiranya aku dahulu mengerjakan (amal saleh) untuk hidupku ini\".", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 25, "text": "فَیَوۡمَىِٕذࣲ لَّا یُعَذِّبُ عَذَابَهُۥۤ أَحَدࣱ ۝٢٥", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ففي ذلك اليوم العصيب لا يستطيع أحدٌ ولا يقدر أن يُعذِّبَ مثل تعذيب الله من عصاه، ولا يستطيع أحد أن يوثِقَ مثل وثاق الله، ولا يبلغ أحدٌ مبلغه في ذلك.", "isBasmala": false, "translation_en": "On that Day, none will punish as He punishes.", "translation_id": "Maka pada hari itu tiada seorangpun yang menyiksa seperti siksa-Nya.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 26, "text": "وَلَا یُوثِقُ وَثَاقَهُۥۤ أَحَدࣱ ۝٢٦", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "ففي ذلك اليوم العصيب لا يستطيع أحدٌ ولا يقدر أن يُعذِّبَ مثل تعذيب الله من عصاه، ولا يستطيع أحد أن يوثِقَ مثل وثاق الله، ولا يبلغ أحدٌ مبلغه في ذلك.", "isBasmala": false, "translation_en": "And none will shackle as He shackles.", "translation_id": "dan tiada seorangpun yang mengikat seperti ikatan-Nya.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 27, "text": "یَـٰۤأَیَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَىِٕنَّةُ ۝٢٧", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "يا أيتها النفس المطمئنة إلى ذِكر الله والإيمان به، وبما أعدَّه من النعيم للمؤمنين، ارجعي إلى ربك راضية بإكرام الله لك، والله سبحانه قد رضي عنك، فادخلي في عداد عباد الله الصالحين، وادخلي معهم جنتي.", "isBasmala": false, "translation_en": "But as for you, O tranquil soul.", "translation_id": "Hai jiwa yang tenang.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 28, "text": "ٱرۡجِعِیۤ إِلَىٰ رَبِّكِ رَاضِیَةࣰ مَّرۡضِیَّةࣰ ۝٢٨", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "يا أيتها النفس المطمئنة إلى ذِكر الله والإيمان به، وبما أعدَّه من النعيم للمؤمنين، ارجعي إلى ربك راضية بإكرام الله لك، والله سبحانه قد رضي عنك، فادخلي في عداد عباد الله الصالحين، وادخلي معهم جنتي.", "isBasmala": false, "translation_en": "Return to your Lord, pleased and accepted.", "translation_id": "Kembalilah kepada Tuhanmu dengan hati yang puas lagi diridhai-Nya.", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 29, "text": "فَٱدۡخُلِی فِی عِبَـٰدِی ۝٢٩", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "يا أيتها النفس المطمئنة إلى ذِكر الله والإيمان به، وبما أعدَّه من النعيم للمؤمنين، ارجعي إلى ربك راضية بإكرام الله لك، والله سبحانه قد رضي عنك، فادخلي في عداد عباد الله الصالحين، وادخلي معهم جنتي.", "isBasmala": false, "translation_en": "Enter among My servants.", "translation_id": "Maka masuklah ke dalam jama'ah hamba-hamba-Ku,", "manzil": 7, "manzil_display": ""}, {"sura": 89, "sura_name": "الفجر", "revelation": "Makkiyah", "aya": 30, "text": "وَٱدۡخُلِی جَنَّتِی ۝٣٠", "juz": 30, "hizb": "(* ح 60*)", "tafsir": "يا أيتها النفس المطمئنة إلى ذِكر الله والإيمان به، وبما أعدَّه من النعيم للمؤمنين، ارجعي إلى ربك راضية بإكرام الله لك، والله سبحانه قد رضي عنك، فادخلي في عداد عباد الله الصالحين، وادخلي معهم جنتي.", "isBasmala": false, "translation_en": "Enter My Paradise.", "translation_id": "masuklah ke dalam surga-Ku.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 1, "text": "۞ لَاۤ أُقۡسِمُ بِهَـٰذَا ٱلۡبَلَدِ ۝١", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بهذا البلد الحرام، وهو \"مكة\"، وأنت -أيها النبي- مقيم في هذا \"البلد الحرام\"، وأقسم بوالد البشرية- وهو آدم عليه السلام- وما تناسل منه من ولد، لقد خلقنا الإنسان في شدة وعناء من مكابدة الدنيا.", "isBasmala": false, "translation_en": "I swear by this land.", "translation_id": "Aku benar-benar bersumpah dengan kota ini (Mekah),", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 2, "text": "وَأَنتَ حِلُّۢ بِهَـٰذَا ٱلۡبَلَدِ ۝٢", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بهذا البلد الحرام، وهو \"مكة\"، وأنت -أيها النبي- مقيم في هذا \"البلد الحرام\"، وأقسم بوالد البشرية- وهو آدم عليه السلام- وما تناسل منه من ولد، لقد خلقنا الإنسان في شدة وعناء من مكابدة الدنيا.", "isBasmala": false, "translation_en": "And you are a resident of this land.", "translation_id": "dan kamu (Muhammad) bertempat di kota Mekah ini,", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 3, "text": "وَوَالِدࣲ وَمَا وَلَدَ ۝٣", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بهذا البلد الحرام، وهو \"مكة\"، وأنت -أيها النبي- مقيم في هذا \"البلد الحرام\"، وأقسم بوالد البشرية- وهو آدم عليه السلام- وما تناسل منه من ولد، لقد خلقنا الإنسان في شدة وعناء من مكابدة الدنيا.", "isBasmala": false, "translation_en": "And by a father and what he fathered.", "translation_id": "dan demi bapak dan anaknya.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 4, "text": "لَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ فِی كَبَدٍ ۝٤", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بهذا البلد الحرام، وهو \"مكة\"، وأنت -أيها النبي- مقيم في هذا \"البلد الحرام\"، وأقسم بوالد البشرية- وهو آدم عليه السلام- وما تناسل منه من ولد، لقد خلقنا الإنسان في شدة وعناء من مكابدة الدنيا.", "isBasmala": false, "translation_en": "We created man in distress.", "translation_id": "Sesungguhnya Kami telah menciptakan manusia berada dalam susah payah.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 5, "text": "أَیَحۡسَبُ أَن لَّن یَقۡدِرَ عَلَیۡهِ أَحَدࣱ ۝٥", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أيظنُّ بما جمعه من مال أن الله لن يقدر عليه؟", "isBasmala": false, "translation_en": "Does he think that no one has power over him?", "translation_id": "Apakah manusia itu menyangka bahwa sekali-kali tiada seorangpun yang berkuasa atasnya?", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 6, "text": "یَقُولُ أَهۡلَكۡتُ مَالࣰا لُّبَدًا ۝٦", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "يقول متباهيًا: أنفقت مالا كثيرًا. أيظنُّ في فعله هذا أن الله عز وجل لا يراه، ولا يحاسبه على الصغير والكبير؟", "isBasmala": false, "translation_en": "He says, \"I have used up so much money.\"", "translation_id": "Dan mengatakan: \"Aku telah menghabiskan harta yang banyak\".", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 7, "text": "أَیَحۡسَبُ أَن لَّمۡ یَرَهُۥۤ أَحَدٌ ۝٧", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "يقول متباهيًا: أنفقت مالا كثيرًا. أيظنُّ في فعله هذا أن الله عز وجل لا يراه، ولا يحاسبه على الصغير والكبير؟", "isBasmala": false, "translation_en": "Does he think that no one sees him?", "translation_id": "Apakah dia menyangka bahwa tiada seorangpun yang melihatnya?", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 8, "text": "أَلَمۡ نَجۡعَل لَّهُۥ عَیۡنَیۡنِ ۝٨", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "ألم نجعل له عينين يبصر بهما، ولسانًا وشفتين ينطق بها، وبينَّا له سبيلَي الخير والشر؟", "isBasmala": false, "translation_en": "Did We not give him two eyes?", "translation_id": "Bukankah Kami telah memberikan kepadanya dua buah mata,", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 9, "text": "وَلِسَانࣰا وَشَفَتَیۡنِ ۝٩", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "ألم نجعل له عينين يبصر بهما، ولسانًا وشفتين ينطق بها، وبينَّا له سبيلَي الخير والشر؟", "isBasmala": false, "translation_en": "And a tongue, and two lips?", "translation_id": "lidah dan dua buah bibir.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 10, "text": "وَهَدَیۡنَـٰهُ ٱلنَّجۡدَیۡنِ ۝١٠", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "ألم نجعل له عينين يبصر بهما، ولسانًا وشفتين ينطق بها، وبينَّا له سبيلَي الخير والشر؟", "isBasmala": false, "translation_en": "And We showed him the two ways?", "translation_id": "Dan Kami telah menunjukkan kepadanya dua jalan,", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 11, "text": "فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ ۝١١", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "فهلا تجاوز مشقة الآخرة بإنفاق ماله، فيأمن.", "isBasmala": false, "translation_en": "But he did not brave the ascent.", "translation_id": "Tetapi dia tiada menempuh jalan yang mendaki lagi sukar.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 12, "text": "وَمَاۤ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ ۝١٢", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وأيُّ شيء أعلمك: ما مشقة الآخرة، وما يعين على تجاوزها؟", "isBasmala": false, "translation_en": "And what will explain to you what the ascent is?", "translation_id": "Tahukah kamu apakah jalan yang mendaki lagi sukar itu?", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 13, "text": "فَكُّ رَقَبَةٍ ۝١٣", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "إنه عتق رقبة مؤمنة من أسر الرِّق.", "isBasmala": false, "translation_en": "The freeing of a slave.", "translation_id": "(yaitu) melepaskan budak dari perbudakan,", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 14, "text": "أَوۡ إِطۡعَـٰمࣱ فِی یَوۡمࣲ ذِی مَسۡغَبَةࣲ ۝١٤", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أو إطعام في يوم ذي مجاعة شديدة، يتيمًا من ذوي القرابة يجتمع فيه فضل الصدقة وصلة الرحم، أو فقيرًا معدمًا لا شيء عنده.", "isBasmala": false, "translation_en": "Or the feeding on a day of hunger.", "translation_id": "atau memberi makan pada hari kelaparan,", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 15, "text": "یَتِیمࣰا ذَا مَقۡرَبَةٍ ۝١٥", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أو إطعام في يوم ذي مجاعة شديدة، يتيمًا من ذوي القرابة يجتمع فيه فضل الصدقة وصلة الرحم، أو فقيرًا معدمًا لا شيء عنده.", "isBasmala": false, "translation_en": "An orphan near of kin.", "translation_id": "(kepada) anak yatim yang ada hubungan kerabat,", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 16, "text": "أَوۡ مِسۡكِینࣰا ذَا مَتۡرَبَةࣲ ۝١٦", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أو إطعام في يوم ذي مجاعة شديدة، يتيمًا من ذوي القرابة يجتمع فيه فضل الصدقة وصلة الرحم، أو فقيرًا معدمًا لا شيء عنده.", "isBasmala": false, "translation_en": "Or a destitute in the dust.", "translation_id": "atau kepada orang miskin yang sangat fakir.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 17, "text": "ثُمَّ كَانَ مِنَ ٱلَّذِینَ ءَامَنُوا۟ وَتَوَاصَوۡا۟ بِٱلصَّبۡرِ وَتَوَاصَوۡا۟ بِٱلۡمَرۡحَمَةِ ۝١٧", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "ثم كان مع فِعْل ما ذُكر من أعمال الخير من الذين أخلصوا الإيمان لله، وأوصى بعضهم بعضًا بالصبر على طاعة الله وعن معاصيه، وتواصوا بالرحمة بالخلق.", "isBasmala": false, "translation_en": "Then he becomes of those who believe, and advise one another to patience, and advise one another to kindness.", "translation_id": "Dan dia (tidak pula) termasuk orang-orang yang beriman dan saling berpesan untuk bersabar dan saling berpesan untuk berkasih sayang.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 18, "text": "أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡمَیۡمَنَةِ ۝١٨", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "الذين فعلوا هذه الأفعال، هم أصحاب اليمين، الذين يؤخذ بهم يوم القيامة ذات اليمين إلى الجنة.", "isBasmala": false, "translation_en": "These are the people of happiness.", "translation_id": "Mereka (orang-orang yang beriman dan saling berpesan itu) adalah golongan kanan.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 19, "text": "وَٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِنَا هُمۡ أَصۡحَـٰبُ ٱلۡمَشۡـَٔمَةِ ۝١٩", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "والذين كفروا بالقرآن هم الذين يؤخذ بهم يوم القيامة ذات الشمال إلى النار.", "isBasmala": false, "translation_en": "But as for those who defy Our revelations-these are the people of misery.", "translation_id": "Dan orang-orang yang kafir kepada ayat-ayat Kami, mereka itu adalah golongan kiri.", "manzil": 7, "manzil_display": ""}, {"sura": 90, "sura_name": "البلد", "revelation": "Makkiyah", "aya": 20, "text": "عَلَیۡهِمۡ نَارࣱ مُّؤۡصَدَةُۢ ۝٢٠", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "جزاؤهم جهنم مطبَقةٌ مغلقة عليهم.", "isBasmala": false, "translation_en": "Upon them is a padlocked Fire.", "translation_id": "Mereka berada dalam neraka yang ditutup rapat.", "manzil": 7, "manzil_display": ""}], "595": [{"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلشَّمۡسِ وَضُحَىٰهَا ۝١", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "By the sun and its radiance.", "translation_id": "Demi matahari dan cahayanya di pagi hari,", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 2, "text": "وَٱلۡقَمَرِ إِذَا تَلَىٰهَا ۝٢", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "And the moon as it follows it.", "translation_id": "dan bulan apabila mengiringinya,", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 3, "text": "وَٱلنَّهَارِ إِذَا جَلَّىٰهَا ۝٣", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "And the day as it reveals it.", "translation_id": "dan siang apabila menampakkannya,", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 4, "text": "وَٱلَّیۡلِ إِذَا یَغۡشَىٰهَا ۝٤", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "And the night as it conceals it.", "translation_id": "dan malam apabila menutupinya,", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 5, "text": "وَٱلسَّمَاۤءِ وَمَا بَنَىٰهَا ۝٥", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "And the sky and He who built it.", "translation_id": "dan langit serta pembinaannya,", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 6, "text": "وَٱلۡأَرۡضِ وَمَا طَحَىٰهَا ۝٦", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "And the earth and He who spread it.", "translation_id": "dan bumi serta penghamparannya,", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 7, "text": "وَنَفۡسࣲ وَمَا سَوَّىٰهَا ۝٧", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "And the soul and He who proportioned it.", "translation_id": "dan jiwa serta penyempurnaannya (ciptaannya),", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 8, "text": "فَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا ۝٨", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "And inspired it with its wickedness and its righteousness.", "translation_id": "maka Allah mengilhamkan kepada jiwa itu (jalan) kefasikan dan ketakwaannya.", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 9, "text": "قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا ۝٩", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "Successful is he who purifies it.", "translation_id": "sesungguhnya beruntunglah orang yang mensucikan jiwa itu,", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 10, "text": "وَقَدۡ خَابَ مَن دَسَّىٰهَا ۝١٠", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بالشمس ونهارها وإشراقها ضحى، وبالقمر إذا تبعها في الطلوع والأفول، وبالنهار إذا جلَّى الظلمة وكشفها، وبالليل عندما يغطي الأرض فيكون ما عليها مظلمًا، وبالسماء وبنائها المحكم، وبالأرض وبَسْطها، وبكل نفس وإكمال الله خلقها لأداء مهمتها، فبيَّن لها طريق الشر وطريق الخير، قد فاز مَن طهَّرها ونمَّاها بالخير، وقد خسر مَن أخفى نفسه في المعاصي.", "isBasmala": false, "translation_en": "Failing is he who corrupts it.", "translation_id": "dan sesungguhnya merugilah orang yang mengotorinya.", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 11, "text": "كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَاۤ ۝١١", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "كذَّبت ثمود نبيها ببلوغها الغاية في العصيان، إذ نهض أكثر القبيلة شقاوة لعقر الناقة، فقال لهم رسول الله صالح عليه السلام: احذروا أن تمسوا الناقة بسوء؛ فإنها آية أرسلها الله إليكم، تدل على صدق نبيكم، واحذروا أن تعتدوا على سقيها، فإن لها شِرْب يوم ولكم شِرْب يوم معلوم. فشق عليهم ذلك، فكذبوه فيما توعَّدهم به فنحروها، فأطبق عليهم ربهم العقوبة بجرمهم، فجعلها عليهم على السواء فلم يُفْلِت منهم أحد. ولا يخاف- جلت قدرته- تبعة ما أنزله بهم من شديد العقاب.", "isBasmala": false, "translation_en": "Thamood denied in its pride.", "translation_id": "(Kaum) Tsamud telah mendustakan (rasulnya) karena mereka melampaui batas,", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 12, "text": "إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا ۝١٢", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "كذَّبت ثمود نبيها ببلوغها الغاية في العصيان، إذ نهض أكثر القبيلة شقاوة لعقر الناقة، فقال لهم رسول الله صالح عليه السلام: احذروا أن تمسوا الناقة بسوء؛ فإنها آية أرسلها الله إليكم، تدل على صدق نبيكم، واحذروا أن تعتدوا على سقيها، فإن لها شِرْب يوم ولكم شِرْب يوم معلوم. فشق عليهم ذلك، فكذبوه فيما توعَّدهم به فنحروها، فأطبق عليهم ربهم العقوبة بجرمهم، فجعلها عليهم على السواء فلم يُفْلِت منهم أحد. ولا يخاف- جلت قدرته- تبعة ما أنزله بهم من شديد العقاب.", "isBasmala": false, "translation_en": "When it followed its most wicked.", "translation_id": "ketika bangkit orang yang paling celaka di antara mereka,", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 13, "text": "فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡیَـٰهَا ۝١٣", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "كذَّبت ثمود نبيها ببلوغها الغاية في العصيان، إذ نهض أكثر القبيلة شقاوة لعقر الناقة، فقال لهم رسول الله صالح عليه السلام: احذروا أن تمسوا الناقة بسوء؛ فإنها آية أرسلها الله إليكم، تدل على صدق نبيكم، واحذروا أن تعتدوا على سقيها، فإن لها شِرْب يوم ولكم شِرْب يوم معلوم. فشق عليهم ذلك، فكذبوه فيما توعَّدهم به فنحروها، فأطبق عليهم ربهم العقوبة بجرمهم، فجعلها عليهم على السواء فلم يُفْلِت منهم أحد. ولا يخاف- جلت قدرته- تبعة ما أنزله بهم من شديد العقاب.", "isBasmala": false, "translation_en": "The messenger of God said to them, \"This is the she-camel of God, so let her drink.\"", "translation_id": "lalu Rasul Allah (Saleh) berkata kepada mereka: (\"Biarkanlah) unta betina Allah dan minumannya\".", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 14, "text": "فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَیۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا ۝١٤", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "كذَّبت ثمود نبيها ببلوغها الغاية في العصيان، إذ نهض أكثر القبيلة شقاوة لعقر الناقة، فقال لهم رسول الله صالح عليه السلام: احذروا أن تمسوا الناقة بسوء؛ فإنها آية أرسلها الله إليكم، تدل على صدق نبيكم، واحذروا أن تعتدوا على سقيها، فإن لها شِرْب يوم ولكم شِرْب يوم معلوم. فشق عليهم ذلك، فكذبوه فيما توعَّدهم به فنحروها، فأطبق عليهم ربهم العقوبة بجرمهم، فجعلها عليهم على السواء فلم يُفْلِت منهم أحد. ولا يخاف- جلت قدرته- تبعة ما أنزله بهم من شديد العقاب.", "isBasmala": false, "translation_en": "But they called him a liar, and hamstrung her. So their Lord crushed them for their sin, and leveled it.", "translation_id": "Lalu mereka mendustakannya dan menyembelih unta itu, maka Tuhan mereka membinasakan mereka disebabkan dosa mereka, lalu Allah menyama-ratakan mereka (dengan tanah),", "manzil": 7, "manzil_display": ""}, {"sura": 91, "sura_name": "الشمس", "revelation": "Makkiyah", "aya": 15, "text": "وَلَا یَخَافُ عُقۡبَـٰهَا ۝١٥", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "كذَّبت ثمود نبيها ببلوغها الغاية في العصيان، إذ نهض أكثر القبيلة شقاوة لعقر الناقة، فقال لهم رسول الله صالح عليه السلام: احذروا أن تمسوا الناقة بسوء؛ فإنها آية أرسلها الله إليكم، تدل على صدق نبيكم، واحذروا أن تعتدوا على سقيها، فإن لها شِرْب يوم ولكم شِرْب يوم معلوم. فشق عليهم ذلك، فكذبوه فيما توعَّدهم به فنحروها، فأطبق عليهم ربهم العقوبة بجرمهم، فجعلها عليهم على السواء فلم يُفْلِت منهم أحد. ولا يخاف- جلت قدرته- تبعة ما أنزله بهم من شديد العقاب.", "isBasmala": false, "translation_en": "And He does not fear its sequel.", "translation_id": "dan Allah tidak takut terhadap akibat tindakan-Nya itu.", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلَّیۡلِ إِذَا یَغۡشَىٰ ۝١", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله سبحانه بالليل عندما يغطي بظلامه الأرض وما عليها، وبالنهار إذا انكشف عن ظلام الليل بضيائه، وبخلق الزوجين: الذكر والأنثى. إن عملكم لمختلف بين عامل للدنيا وعامل للآخرة.", "isBasmala": false, "translation_en": "By the night as it covers.", "translation_id": "Demi malam apabila menutupi (cahaya siang),", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 2, "text": "وَٱلنَّهَارِ إِذَا تَجَلَّىٰ ۝٢", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله سبحانه بالليل عندما يغطي بظلامه الأرض وما عليها، وبالنهار إذا انكشف عن ظلام الليل بضيائه، وبخلق الزوجين: الذكر والأنثى. إن عملكم لمختلف بين عامل للدنيا وعامل للآخرة.", "isBasmala": false, "translation_en": "And the day as it reveals.", "translation_id": "dan siang apabila terang benderang,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 3, "text": "وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰۤ ۝٣", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله سبحانه بالليل عندما يغطي بظلامه الأرض وما عليها، وبالنهار إذا انكشف عن ظلام الليل بضيائه، وبخلق الزوجين: الذكر والأنثى. إن عملكم لمختلف بين عامل للدنيا وعامل للآخرة.", "isBasmala": false, "translation_en": "And He who created the male and the female.", "translation_id": "dan penciptaan laki-laki dan perempuan,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 4, "text": "إِنَّ سَعۡیَكُمۡ لَشَتَّىٰ ۝٤", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله سبحانه بالليل عندما يغطي بظلامه الأرض وما عليها، وبالنهار إذا انكشف عن ظلام الليل بضيائه، وبخلق الزوجين: الذكر والأنثى. إن عملكم لمختلف بين عامل للدنيا وعامل للآخرة.", "isBasmala": false, "translation_en": "Your endeavors are indeed diverse.", "translation_id": "sesungguhnya usaha kamu memang berbeda-beda.", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 5, "text": "فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ ۝٥", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "فأمَّا من بذل من ماله واتقى الله في ذلك، وصدَّق بـ\"لا إله إلا الله\" وما دلت عليه، وما ترتب عليها من الجزاء، فسنرشده ونوفقه إلى أسباب الخير والصلاح ونيسِّر له أموره.", "isBasmala": false, "translation_en": "As for him who gives and is righteous.", "translation_id": "Adapun orang yang memberikan (hartanya di jalan Allah) dan bertakwa,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 6, "text": "وَصَدَّقَ بِٱلۡحُسۡنَىٰ ۝٦", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "فأمَّا من بذل من ماله واتقى الله في ذلك، وصدَّق بـ\"لا إله إلا الله\" وما دلت عليه، وما ترتب عليها من الجزاء، فسنرشده ونوفقه إلى أسباب الخير والصلاح ونيسِّر له أموره.", "isBasmala": false, "translation_en": "And confirms goodness.", "translation_id": "dan membenarkan adanya pahala yang terbaik (surga),", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 7, "text": "فَسَنُیَسِّرُهُۥ لِلۡیُسۡرَىٰ ۝٧", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "فأمَّا من بذل من ماله واتقى الله في ذلك، وصدَّق بـ\"لا إله إلا الله\" وما دلت عليه، وما ترتب عليها من الجزاء، فسنرشده ونوفقه إلى أسباب الخير والصلاح ونيسِّر له أموره.", "isBasmala": false, "translation_en": "We will ease his way towards ease.", "translation_id": "maka Kami kelak akan menyiapkan baginya jalan yang mudah.", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 8, "text": "وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ ۝٨", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وأما مَن بخل بماله واستغنى عن جزاء ربه، وكذَّب بـ\"لا إله إلا الله\" وما دلت عليه، وما ترتب عليها من الجزاء، فسنُيَسِّر له أسباب الشقاء، ولا ينفعه ماله الذي بخل به إذا وقع في النار.", "isBasmala": false, "translation_en": "But as for him who is stingy and complacent.", "translation_id": "Dan adapun orang-orang yang bakhil dan merasa dirinya cukup,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 9, "text": "وَكَذَّبَ بِٱلۡحُسۡنَىٰ ۝٩", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وأما مَن بخل بماله واستغنى عن جزاء ربه، وكذَّب بـ\"لا إله إلا الله\" وما دلت عليه، وما ترتب عليها من الجزاء، فسنُيَسِّر له أسباب الشقاء، ولا ينفعه ماله الذي بخل به إذا وقع في النار.", "isBasmala": false, "translation_en": "And denies goodness.", "translation_id": "serta mendustakan pahala terbaik,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 10, "text": "فَسَنُیَسِّرُهُۥ لِلۡعُسۡرَىٰ ۝١٠", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وأما مَن بخل بماله واستغنى عن جزاء ربه، وكذَّب بـ\"لا إله إلا الله\" وما دلت عليه، وما ترتب عليها من الجزاء، فسنُيَسِّر له أسباب الشقاء، ولا ينفعه ماله الذي بخل به إذا وقع في النار.", "isBasmala": false, "translation_en": "We will ease his way towards difficulty.", "translation_id": "maka kelak Kami akan menyiapkan baginya (jalan) yang sukar.", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 11, "text": "وَمَا یُغۡنِی عَنۡهُ مَالُهُۥۤ إِذَا تَرَدَّىٰۤ ۝١١", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وأما مَن بخل بماله واستغنى عن جزاء ربه، وكذَّب بـ\"لا إله إلا الله\" وما دلت عليه، وما ترتب عليها من الجزاء، فسنُيَسِّر له أسباب الشقاء، ولا ينفعه ماله الذي بخل به إذا وقع في النار.", "isBasmala": false, "translation_en": "And his money will not avail him when he plummets.", "translation_id": "Dan hartanya tidak bermanfaat baginya apabila ia telah binasa.", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 12, "text": "إِنَّ عَلَیۡنَا لَلۡهُدَىٰ ۝١٢", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "إن علينا بفضلنا وحكمتنا أن نبيِّن طريق الهدى الموصل إلى الله وجنته من طريق الضلال، وإن لنا ملك الحياة الآخرة والحياة الدنيا.", "isBasmala": false, "translation_en": "It is upon Us to guide.", "translation_id": "Sesungguhnya kewajiban Kamilah memberi petunjuk,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 13, "text": "وَإِنَّ لَنَا لَلۡـَٔاخِرَةَ وَٱلۡأُولَىٰ ۝١٣", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "إن علينا بفضلنا وحكمتنا أن نبيِّن طريق الهدى الموصل إلى الله وجنته من طريق الضلال، وإن لنا ملك الحياة الآخرة والحياة الدنيا.", "isBasmala": false, "translation_en": "And to Us belong the Last and the First.", "translation_id": "dan sesungguhnya kepunyaan Kamilah akhirat dan dunia.", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 14, "text": "فَأَنذَرۡتُكُمۡ نَارࣰا تَلَظَّىٰ ۝١٤", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "فحذَّرتكم- أيها الناس- وخوَّفتكم نارًا تتوهج، وهي نار جهنم.", "isBasmala": false, "translation_en": "I have warned you of a Fierce Blaze.", "translation_id": "Maka, kami memperingatkan kamu dengan neraka yang menyala-nyala.", "manzil": 7, "manzil_display": ""}], "596": [{"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 15, "text": "لَا یَصۡلَىٰهَاۤ إِلَّا ٱلۡأَشۡقَى ۝١٥", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "لا يدخلها إلا مَن كان شديد الشقاء، الذي كذَّب نبي الله محمدًا صلى الله عليه وسلم، وأعرض عن الإيمان بالله ورسوله، وطاعتهما.", "isBasmala": false, "translation_en": "None will burn in it except the very wicked.", "translation_id": "Tidak ada yang masuk ke dalamnya kecuali orang yang paling celaka,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 16, "text": "ٱلَّذِی كَذَّبَ وَتَوَلَّىٰ ۝١٦", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "لا يدخلها إلا مَن كان شديد الشقاء، الذي كذَّب نبي الله محمدًا صلى الله عليه وسلم، وأعرض عن الإيمان بالله ورسوله، وطاعتهما.", "isBasmala": false, "translation_en": "He who denies and turns away.", "translation_id": "yang mendustakan (kebenaran) dan berpaling (dari iman).", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 17, "text": "وَسَیُجَنَّبُهَا ٱلۡأَتۡقَى ۝١٧", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وسيُزحزَح عنها شديد التقوى، الذي يبذل ماله ابتغاء المزيد من الخير. وليس إنفاقه ذاك مكافأة لمن أسدى إليه معروفا، لكنه يبتغي بذلك وجه ربه الأعلى ورضاه، ولسوف يعطيه الله في الجنة ما يرضى به.", "isBasmala": false, "translation_en": "But the devout will avoid it.", "translation_id": "Dan kelak akan dijauhkan orang yang paling takwa dari neraka itu,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 18, "text": "ٱلَّذِی یُؤۡتِی مَالَهُۥ یَتَزَكَّىٰ ۝١٨", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وسيُزحزَح عنها شديد التقوى، الذي يبذل ماله ابتغاء المزيد من الخير. وليس إنفاقه ذاك مكافأة لمن أسدى إليه معروفا، لكنه يبتغي بذلك وجه ربه الأعلى ورضاه، ولسوف يعطيه الله في الجنة ما يرضى به.", "isBasmala": false, "translation_en": "He who gives his money to become pure.", "translation_id": "yang menafkahkan hartanya (di jalan Allah) untuk membersihkannya,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 19, "text": "وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةࣲ تُجۡزَىٰۤ ۝١٩", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وسيُزحزَح عنها شديد التقوى، الذي يبذل ماله ابتغاء المزيد من الخير. وليس إنفاقه ذاك مكافأة لمن أسدى إليه معروفا، لكنه يبتغي بذلك وجه ربه الأعلى ورضاه، ولسوف يعطيه الله في الجنة ما يرضى به.", "isBasmala": false, "translation_en": "Seeking no favor in return.", "translation_id": "padahal tidak ada seseorangpun memberikan suatu nikmat kepadanya yang harus dibalasnya,", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 20, "text": "إِلَّا ٱبۡتِغَاۤءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ ۝٢٠", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وسيُزحزَح عنها شديد التقوى، الذي يبذل ماله ابتغاء المزيد من الخير. وليس إنفاقه ذاك مكافأة لمن أسدى إليه معروفا، لكنه يبتغي بذلك وجه ربه الأعلى ورضاه، ولسوف يعطيه الله في الجنة ما يرضى به.", "isBasmala": false, "translation_en": "Only seeking the acceptance of his Lord, the Most High.", "translation_id": "tetapi (dia memberikan itu semata-mata) karena mencari keridhaan Tuhannya yang Maha Tinggi.", "manzil": 7, "manzil_display": ""}, {"sura": 92, "sura_name": "الليل", "revelation": "Makkiyah", "aya": 21, "text": "وَلَسَوۡفَ یَرۡضَىٰ ۝٢١", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "وسيُزحزَح عنها شديد التقوى، الذي يبذل ماله ابتغاء المزيد من الخير. وليس إنفاقه ذاك مكافأة لمن أسدى إليه معروفا، لكنه يبتغي بذلك وجه ربه الأعلى ورضاه، ولسوف يعطيه الله في الجنة ما يرضى به.", "isBasmala": false, "translation_en": "And he will be satisfied.", "translation_id": "Dan kelak dia benar-benar mendapat kepuasan.", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلضُّحَىٰ ۝١", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بوقت الضحى، والمراد به النهار كله، وبالليل إذا سكن بالخلق واشتد ظلامه. ويقسم الله بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير خالقه، فإن القسم بغير الله شرك. ما تركك -أيها النبي- ربك، وما أبغضك بإبطاء الوحي عنك.", "isBasmala": false, "translation_en": "By the morning light.", "translation_id": "Demi waktu matahari sepenggalahan naik,", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 2, "text": "وَٱلَّیۡلِ إِذَا سَجَىٰ ۝٢", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بوقت الضحى، والمراد به النهار كله، وبالليل إذا سكن بالخلق واشتد ظلامه. ويقسم الله بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير خالقه، فإن القسم بغير الله شرك. ما تركك -أيها النبي- ربك، وما أبغضك بإبطاء الوحي عنك.", "isBasmala": false, "translation_en": "And the night as it settles.", "translation_id": "dan demi malam apabila telah sunyi (gelap),", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 3, "text": "مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ ۝٣", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "أقسم الله بوقت الضحى، والمراد به النهار كله، وبالليل إذا سكن بالخلق واشتد ظلامه. ويقسم الله بما يشاء من مخلوقاته، أما المخلوق فلا يجوز له أن يقسم بغير خالقه، فإن القسم بغير الله شرك. ما تركك -أيها النبي- ربك، وما أبغضك بإبطاء الوحي عنك.", "isBasmala": false, "translation_en": "Your Lord did not abandon you, nor did He forget.", "translation_id": "Tuhanmu tiada meninggalkan kamu dan tiada (pula) benci kepadamu.", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 4, "text": "وَلَلۡـَٔاخِرَةُ خَیۡرࣱ لَّكَ مِنَ ٱلۡأُولَىٰ ۝٤", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "ولَلدَّار الآخرة خير لك من دار الدنيا، ولسوف يعطيك ربك -أيها النبي- مِن أنواع الإنعام في الآخرة، فترضى بذلك.", "isBasmala": false, "translation_en": "The Hereafter is better for you than the First.", "translation_id": "Dan sesungguhnya hari kemudian itu lebih baik bagimu daripada yang sekarang (permulaan).", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 5, "text": "وَلَسَوۡفَ یُعۡطِیكَ رَبُّكَ فَتَرۡضَىٰۤ ۝٥", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "ولَلدَّار الآخرة خير لك من دار الدنيا، ولسوف يعطيك ربك -أيها النبي- مِن أنواع الإنعام في الآخرة، فترضى بذلك.", "isBasmala": false, "translation_en": "And your Lord will give you, and you will be satisfied.", "translation_id": "Dan kelak Tuhanmu pasti memberikan karunia-Nya kepadamu, lalu (hati) kamu menjadi puas.", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 6, "text": "أَلَمۡ یَجِدۡكَ یَتِیمࣰا فَـَٔاوَىٰ ۝٦", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "ألم يَجِدْك من قبلُ يتيمًا، فآواك ورعاك؟ ووجدك لا تدري ما الكتاب ولا الإيمان، فعلَّمك ما لم تكن تعلم، ووفقك لأحسن الأعمال؟ ووجدك فقيرًا، فساق لك رزقك، وأغنى نفسك بالقناعة والصبر؟", "isBasmala": false, "translation_en": "Did He not find you orphaned, and sheltered you?", "translation_id": "Bukankah Dia mendapatimu sebagai seorang yatim, lalu Dia melindungimu?", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 7, "text": "وَوَجَدَكَ ضَاۤلࣰّا فَهَدَىٰ ۝٧", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "ألم يَجِدْك من قبلُ يتيمًا، فآواك ورعاك؟ ووجدك لا تدري ما الكتاب ولا الإيمان، فعلَّمك ما لم تكن تعلم، ووفقك لأحسن الأعمال؟ ووجدك فقيرًا، فساق لك رزقك، وأغنى نفسك بالقناعة والصبر؟", "isBasmala": false, "translation_en": "And found you wandering, and guided you.", "translation_id": "Dan Dia mendapatimu sebagai seorang yang bingung, lalu Dia memberikan petunjuk.", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 8, "text": "وَوَجَدَكَ عَاۤىِٕلࣰا فَأَغۡنَىٰ ۝٨", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "ألم يَجِدْك من قبلُ يتيمًا، فآواك ورعاك؟ ووجدك لا تدري ما الكتاب ولا الإيمان، فعلَّمك ما لم تكن تعلم، ووفقك لأحسن الأعمال؟ ووجدك فقيرًا، فساق لك رزقك، وأغنى نفسك بالقناعة والصبر؟", "isBasmala": false, "translation_en": "And found you in need, and enriched you?", "translation_id": "Dan Dia mendapatimu sebagai seorang yang kekurangan, lalu Dia memberikan kecukupan.", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 9, "text": "فَأَمَّا ٱلۡیَتِیمَ فَلَا تَقۡهَرۡ ۝٩", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "فأما اليتيم فلا تُسِئْ معاملته، وأما السائل فلا تزجره، بل أطعمه، واقض حاجته، وأما بنعمة ربك التي أسبغها عليك فتحدث بها.", "isBasmala": false, "translation_en": "Therefore, do not mistreat the orphan.", "translation_id": "Sebab itu, terhadap anak yatim janganlah kamu berlaku sewenang-wenang.", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 10, "text": "وَأَمَّا ٱلسَّاۤىِٕلَ فَلَا تَنۡهَرۡ ۝١٠", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "فأما اليتيم فلا تُسِئْ معاملته، وأما السائل فلا تزجره، بل أطعمه، واقض حاجته، وأما بنعمة ربك التي أسبغها عليك فتحدث بها.", "isBasmala": false, "translation_en": "Nor rebuff the seeker.", "translation_id": "Dan terhadap orang yang minta-minta, janganlah kamu menghardiknya.", "manzil": 7, "manzil_display": ""}, {"sura": 93, "sura_name": "الضحى", "revelation": "Makkiyah", "aya": 11, "text": "وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ ۝١١", "juz": 30, "hizb": "(*¼ ح 60*)", "tafsir": "فأما اليتيم فلا تُسِئْ معاملته، وأما السائل فلا تزجره، بل أطعمه، واقض حاجته، وأما بنعمة ربك التي أسبغها عليك فتحدث بها.", "isBasmala": false, "translation_en": "But proclaim the blessings of your Lord.", "translation_id": "Dan terhadap nikmat Tuhanmu, maka hendaklah kamu siarkan.", "manzil": 7, "manzil_display": ""}, {"sura": 94, "sura_name": "الشرح", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 94, "sura_name": "الشرح", "revelation": "Makkiyah", "aya": 1, "text": "۞ أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ ۝١", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "ألم نوسع -أيها النبي- لك صدرك لشرائع الدين، والدعوة إلى الله، والاتصاف بمكارم الأخلاق، وحططنا عنك بذلك حِمْلك الذي أثقل ظهرك، وجعلناك -بما أنعمنا عليك من المكارم- في منزلة رفيعة عالية؟", "isBasmala": false, "translation_en": "Did We not soothe your heart?", "translation_id": "Bukankah Kami telah melapangkan untukmu dadamu?,", "manzil": 7, "manzil_display": ""}, {"sura": 94, "sura_name": "الشرح", "revelation": "Makkiyah", "aya": 2, "text": "وَوَضَعۡنَا عَنكَ وِزۡرَكَ ۝٢", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "ألم نوسع -أيها النبي- لك صدرك لشرائع الدين، والدعوة إلى الله، والاتصاف بمكارم الأخلاق، وحططنا عنك بذلك حِمْلك الذي أثقل ظهرك، وجعلناك -بما أنعمنا عليك من المكارم- في منزلة رفيعة عالية؟", "isBasmala": false, "translation_en": "And lift from you your burden.", "translation_id": "dan Kami telah menghilangkan daripadamu bebanmu,", "manzil": 7, "manzil_display": ""}, {"sura": 94, "sura_name": "الشرح", "revelation": "Makkiyah", "aya": 3, "text": "ٱلَّذِیۤ أَنقَضَ ظَهۡرَكَ ۝٣", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "ألم نوسع -أيها النبي- لك صدرك لشرائع الدين، والدعوة إلى الله، والاتصاف بمكارم الأخلاق، وحططنا عنك بذلك حِمْلك الذي أثقل ظهرك، وجعلناك -بما أنعمنا عليك من المكارم- في منزلة رفيعة عالية؟", "isBasmala": false, "translation_en": "Which weighed down your back?", "translation_id": "yang memberatkan punggungmu?", "manzil": 7, "manzil_display": ""}, {"sura": 94, "sura_name": "الشرح", "revelation": "Makkiyah", "aya": 4, "text": "وَرَفَعۡنَا لَكَ ذِكۡرَكَ ۝٤", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "ألم نوسع -أيها النبي- لك صدرك لشرائع الدين، والدعوة إلى الله، والاتصاف بمكارم الأخلاق، وحططنا عنك بذلك حِمْلك الذي أثقل ظهرك، وجعلناك -بما أنعمنا عليك من المكارم- في منزلة رفيعة عالية؟", "isBasmala": false, "translation_en": "And raised for you your reputation?", "translation_id": "Dan Kami tinggikan bagimu sebutan (nama)mu,", "manzil": 7, "manzil_display": ""}, {"sura": 94, "sura_name": "الشرح", "revelation": "Makkiyah", "aya": 5, "text": "فَإِنَّ مَعَ ٱلۡعُسۡرِ یُسۡرًا ۝٥", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فلا يثنك أذى أعدائك عن نشر الرسالة؛ فإن مع الضيق فرجًا، إن مع الضيق فرجًا.", "isBasmala": false, "translation_en": "With hardship comes ease.", "translation_id": "Karena sesungguhnya sesudah kesulitan itu ada kemudahan,", "manzil": 7, "manzil_display": ""}, {"sura": 94, "sura_name": "الشرح", "revelation": "Makkiyah", "aya": 6, "text": "إِنَّ مَعَ ٱلۡعُسۡرِ یُسۡرࣰا ۝٦", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فلا يثنك أذى أعدائك عن نشر الرسالة؛ فإن مع الضيق فرجًا، إن مع الضيق فرجًا.", "isBasmala": false, "translation_en": "With hardship comes ease.", "translation_id": "sesungguhnya sesudah kesulitan itu ada kemudahan.", "manzil": 7, "manzil_display": ""}, {"sura": 94, "sura_name": "الشرح", "revelation": "Makkiyah", "aya": 7, "text": "فَإِذَا فَرَغۡتَ فَٱنصَبۡ ۝٧", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فإذا فرغت من أمور الدنيا وأشغالها فَجِدَّ في العبادة، وإلى ربك وحده فارغب فيما عنده.", "isBasmala": false, "translation_en": "When your work is done, turn to devotion.", "translation_id": "Maka apabila kamu telah selesai (dari sesuatu urusan), kerjakanlah dengan sungguh-sungguh (urusan) yang lain,", "manzil": 7, "manzil_display": ""}, {"sura": 94, "sura_name": "الشرح", "revelation": "Makkiyah", "aya": 8, "text": "وَإِلَىٰ رَبِّكَ فَٱرۡغَب ۝٨", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فإذا فرغت من أمور الدنيا وأشغالها فَجِدَّ في العبادة، وإلى ربك وحده فارغب فيما عنده.", "isBasmala": false, "translation_en": "And to your Lord turn for everything.", "translation_id": "dan hanya kepada Tuhanmulah hendaknya kamu berharap.", "manzil": 7, "manzil_display": ""}], "597": [{"sura": 95, "sura_name": "التين", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 95, "sura_name": "التين", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلتِّینِ وَٱلزَّیۡتُونِ ۝١", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أَقْسم الله بالتين والزيتون، وهما من الثمار المشهورة، وأقسم بجبل \"طور سيناء\" الذي كلَّم الله عليه موسى تكليمًا، وأقسم بهذا البلد الأمين من كل خوف وهو \"مكة\" مهبط الإسلام. لقد خلقنا الإنسان في أحسن صورة، ثم رددناه إلى النار إن لم يطع الله، ويتبع الرسل، لكن الذين آمنوا وعملوا الأعمال الصالحة لهم أجر عظيم غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "By the fig and the olive.", "translation_id": "Demi (buah) Tin dan (buah) Zaitun,", "manzil": 7, "manzil_display": ""}, {"sura": 95, "sura_name": "التين", "revelation": "Makkiyah", "aya": 2, "text": "وَطُورِ سِینِینَ ۝٢", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أَقْسم الله بالتين والزيتون، وهما من الثمار المشهورة، وأقسم بجبل \"طور سيناء\" الذي كلَّم الله عليه موسى تكليمًا، وأقسم بهذا البلد الأمين من كل خوف وهو \"مكة\" مهبط الإسلام. لقد خلقنا الإنسان في أحسن صورة، ثم رددناه إلى النار إن لم يطع الله، ويتبع الرسل، لكن الذين آمنوا وعملوا الأعمال الصالحة لهم أجر عظيم غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "And Mount Sinai.", "translation_id": "dan demi bukit Sinai,", "manzil": 7, "manzil_display": ""}, {"sura": 95, "sura_name": "التين", "revelation": "Makkiyah", "aya": 3, "text": "وَهَـٰذَا ٱلۡبَلَدِ ٱلۡأَمِینِ ۝٣", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أَقْسم الله بالتين والزيتون، وهما من الثمار المشهورة، وأقسم بجبل \"طور سيناء\" الذي كلَّم الله عليه موسى تكليمًا، وأقسم بهذا البلد الأمين من كل خوف وهو \"مكة\" مهبط الإسلام. لقد خلقنا الإنسان في أحسن صورة، ثم رددناه إلى النار إن لم يطع الله، ويتبع الرسل، لكن الذين آمنوا وعملوا الأعمال الصالحة لهم أجر عظيم غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "And this safe land.", "translation_id": "dan demi kota (Mekah) ini yang aman,", "manzil": 7, "manzil_display": ""}, {"sura": 95, "sura_name": "التين", "revelation": "Makkiyah", "aya": 4, "text": "لَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ فِیۤ أَحۡسَنِ تَقۡوِیمࣲ ۝٤", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أَقْسم الله بالتين والزيتون، وهما من الثمار المشهورة، وأقسم بجبل \"طور سيناء\" الذي كلَّم الله عليه موسى تكليمًا، وأقسم بهذا البلد الأمين من كل خوف وهو \"مكة\" مهبط الإسلام. لقد خلقنا الإنسان في أحسن صورة، ثم رددناه إلى النار إن لم يطع الله، ويتبع الرسل، لكن الذين آمنوا وعملوا الأعمال الصالحة لهم أجر عظيم غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "We created man in the best design.", "translation_id": "sesungguhnya Kami telah menciptakan manusia dalam bentuk yang sebaik-baiknya.", "manzil": 7, "manzil_display": ""}, {"sura": 95, "sura_name": "التين", "revelation": "Makkiyah", "aya": 5, "text": "ثُمَّ رَدَدۡنَـٰهُ أَسۡفَلَ سَـٰفِلِینَ ۝٥", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أَقْسم الله بالتين والزيتون، وهما من الثمار المشهورة، وأقسم بجبل \"طور سيناء\" الذي كلَّم الله عليه موسى تكليمًا، وأقسم بهذا البلد الأمين من كل خوف وهو \"مكة\" مهبط الإسلام. لقد خلقنا الإنسان في أحسن صورة، ثم رددناه إلى النار إن لم يطع الله، ويتبع الرسل، لكن الذين آمنوا وعملوا الأعمال الصالحة لهم أجر عظيم غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "Then reduced him to the lowest of the low.", "translation_id": "Kemudian Kami kembalikan dia ke tempat yang serendah-rendahnya (neraka),", "manzil": 7, "manzil_display": ""}, {"sura": 95, "sura_name": "التين", "revelation": "Makkiyah", "aya": 6, "text": "إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمۡ أَجۡرٌ غَیۡرُ مَمۡنُونࣲ ۝٦", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أَقْسم الله بالتين والزيتون، وهما من الثمار المشهورة، وأقسم بجبل \"طور سيناء\" الذي كلَّم الله عليه موسى تكليمًا، وأقسم بهذا البلد الأمين من كل خوف وهو \"مكة\" مهبط الإسلام. لقد خلقنا الإنسان في أحسن صورة، ثم رددناه إلى النار إن لم يطع الله، ويتبع الرسل، لكن الذين آمنوا وعملوا الأعمال الصالحة لهم أجر عظيم غير مقطوع ولا منقوص.", "isBasmala": false, "translation_en": "Except those who believe and do righteous deeds; for them is a reward without end.", "translation_id": "kecuali orang-orang yang beriman dan mengerjakan amal saleh; maka bagi mereka pahala yang tiada putus-putusnya.", "manzil": 7, "manzil_display": ""}, {"sura": 95, "sura_name": "التين", "revelation": "Makkiyah", "aya": 7, "text": "فَمَا یُكَذِّبُكَ بَعۡدُ بِٱلدِّینِ ۝٧", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أيُّ شيء يحملك -أيها الإنسان- على أن تكذِّب بالبعث والجزاء مع وضوح الأدلة على قدرة الله تعالى على ذلك؟", "isBasmala": false, "translation_en": "So why do you still reject the religion?", "translation_id": "Maka apakah yang menyebabkan kamu mendustakan (hari) pembalasan sesudah (adanya keterangan-keterangan) itu?", "manzil": 7, "manzil_display": ""}, {"sura": 95, "sura_name": "التين", "revelation": "Makkiyah", "aya": 8, "text": "أَلَیۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَـٰكِمِینَ ۝٨", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أليس الله الذي جعل هذا اليوم للفصل بين الناس بأحكم الحاكمين في كل ما خلق؟ بلى. فهل يُترك الخلق سدى لا يؤمرون ولا يُنهون، ولا يثابون ولا يعاقبون؟ لا يصحُّ ذلك ولا يكون.", "isBasmala": false, "translation_en": "Is God not the Wisest of the wise?", "translation_id": "Bukankah Allah Hakim yang seadil-adilnya?", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 1, "text": "ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِی خَلَقَ ۝١", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "اقرأ -أيها النبي- ما أُنزل إليك من القرآن مُفْتَتِحًا باسم ربك المتفرد بالخلق، الذي خلق كل إنسان من قطعة دم غليظ أحمر. اقرأ -أيها النبي- ما أُنزل إليك، وإن ربك لكثير الإحسان واسع الجود، الذي علَّم خلقه الكتابة بالقلم، علَّم الإنسان ما لم يكن يعلم، ونقله من ظلمة الجهل إلى نور العلم.", "isBasmala": false, "translation_en": "Read: In the Name of your Lord who created.", "translation_id": "Bacalah dengan (menyebut) nama Tuhanmu Yang menciptakan,", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 2, "text": "خَلَقَ ٱلۡإِنسَـٰنَ مِنۡ عَلَقٍ ۝٢", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "اقرأ -أيها النبي- ما أُنزل إليك من القرآن مُفْتَتِحًا باسم ربك المتفرد بالخلق، الذي خلق كل إنسان من قطعة دم غليظ أحمر. اقرأ -أيها النبي- ما أُنزل إليك، وإن ربك لكثير الإحسان واسع الجود، الذي علَّم خلقه الكتابة بالقلم، علَّم الإنسان ما لم يكن يعلم، ونقله من ظلمة الجهل إلى نور العلم.", "isBasmala": false, "translation_en": "Created man from a clot.", "translation_id": "Dia telah menciptakan manusia dari segumpal darah.", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 3, "text": "ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ۝٣", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "اقرأ -أيها النبي- ما أُنزل إليك من القرآن مُفْتَتِحًا باسم ربك المتفرد بالخلق، الذي خلق كل إنسان من قطعة دم غليظ أحمر. اقرأ -أيها النبي- ما أُنزل إليك، وإن ربك لكثير الإحسان واسع الجود، الذي علَّم خلقه الكتابة بالقلم، علَّم الإنسان ما لم يكن يعلم، ونقله من ظلمة الجهل إلى نور العلم.", "isBasmala": false, "translation_en": "Read: And your Lord is the Most Generous.", "translation_id": "Bacalah, dan Tuhanmulah Yang Maha Pemurah,", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 4, "text": "ٱلَّذِی عَلَّمَ بِٱلۡقَلَمِ ۝٤", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "اقرأ -أيها النبي- ما أُنزل إليك من القرآن مُفْتَتِحًا باسم ربك المتفرد بالخلق، الذي خلق كل إنسان من قطعة دم غليظ أحمر. اقرأ -أيها النبي- ما أُنزل إليك، وإن ربك لكثير الإحسان واسع الجود، الذي علَّم خلقه الكتابة بالقلم، علَّم الإنسان ما لم يكن يعلم، ونقله من ظلمة الجهل إلى نور العلم.", "isBasmala": false, "translation_en": "He who taught by the pen.", "translation_id": "Yang mengajar (manusia) dengan perantaran kalam,", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 5, "text": "عَلَّمَ ٱلۡإِنسَـٰنَ مَا لَمۡ یَعۡلَمۡ ۝٥", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "اقرأ -أيها النبي- ما أُنزل إليك من القرآن مُفْتَتِحًا باسم ربك المتفرد بالخلق، الذي خلق كل إنسان من قطعة دم غليظ أحمر. اقرأ -أيها النبي- ما أُنزل إليك، وإن ربك لكثير الإحسان واسع الجود، الذي علَّم خلقه الكتابة بالقلم، علَّم الإنسان ما لم يكن يعلم، ونقله من ظلمة الجهل إلى نور العلم.", "isBasmala": false, "translation_en": "Taught man what he never knew.", "translation_id": "Dia mengajar kepada manusia apa yang tidak diketahuinya.", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 6, "text": "كَلَّاۤ إِنَّ ٱلۡإِنسَـٰنَ لَیَطۡغَىٰۤ ۝٦", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "حقًا إن الإنسان ليتجاوز حدود الله إذا أبطره الغنى، فليعلم كل طاغية أن المصير إلى الله، فيجازي كلَّ إنسان بعمله.", "isBasmala": false, "translation_en": "In fact, man oversteps all bounds.", "translation_id": "Ketahuilah! Sesungguhnya manusia benar-benar melampaui batas,", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 7, "text": "أَن رَّءَاهُ ٱسۡتَغۡنَىٰۤ ۝٧", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "حقًا إن الإنسان ليتجاوز حدود الله إذا أبطره الغنى، فليعلم كل طاغية أن المصير إلى الله، فيجازي كلَّ إنسان بعمله.", "isBasmala": false, "translation_en": "When he considers himself exempt.", "translation_id": "karena dia melihat dirinya serba cukup.", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 8, "text": "إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰۤ ۝٨", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "حقًا إن الإنسان ليتجاوز حدود الله إذا أبطره الغنى، فليعلم كل طاغية أن المصير إلى الله، فيجازي كلَّ إنسان بعمله.", "isBasmala": false, "translation_en": "But to your Lord is the return.", "translation_id": "Sesungguhnya hanya kepada Tuhanmulah kembali(mu).", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 9, "text": "أَرَءَیۡتَ ٱلَّذِی یَنۡهَىٰ ۝٩", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "Have you seen him who prevents?", "translation_id": "Bagaimana pendapatmu tentang orang yang melarang,", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 10, "text": "عَبۡدًا إِذَا صَلَّىٰۤ ۝١٠", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "A servant when he prays?", "translation_id": "seorang hamba ketika mengerjakan shalat,", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 11, "text": "أَرَءَیۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰۤ ۝١١", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "Do you think he is upon guidance?", "translation_id": "bagaimana pendapatmu jika orang yang melarang itu berada di atas kebenaran,", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 12, "text": "أَوۡ أَمَرَ بِٱلتَّقۡوَىٰۤ ۝١٢", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "Or advocates righteousness?", "translation_id": "atau dia menyuruh bertakwa (kepada Allah)?", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 13, "text": "أَرَءَیۡتَ إِن كَذَّبَ وَتَوَلَّىٰۤ ۝١٣", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "Do you see how he disbelieved and turned away?", "translation_id": "Bagaimana pendapatmu jika orang yang melarang itu mendustakan dan berpaling?", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 14, "text": "أَلَمۡ یَعۡلَم بِأَنَّ ٱللَّهَ یَرَىٰ ۝١٤", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "Does he not know that God sees?", "translation_id": "Tidaklah dia mengetahui bahwa sesungguhnya Allah melihat segala perbuatannya?", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 15, "text": "كَلَّا لَىِٕن لَّمۡ یَنتَهِ لَنَسۡفَعَۢا بِٱلنَّاصِیَةِ ۝١٥", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "No. If he does not desist, We will drag him by the forelock.", "translation_id": "Ketahuilah, sungguh jika dia tidak berhenti (berbuat demikian) niscaya Kami tarik ubun-ubunnya,", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 16, "text": "نَاصِیَةࣲ كَـٰذِبَةٍ خَاطِئَةࣲ ۝١٦", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "A deceitful, sinful forelock.", "translation_id": "(yaitu) ubun-ubun orang yang mendustakan lagi durhaka.", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 17, "text": "فَلۡیَدۡعُ نَادِیَهُۥ ۝١٧", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "Let him call on his gang.", "translation_id": "Maka biarlah dia memanggil golongannya (untuk menolongnya),", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 18, "text": "سَنَدۡعُ ٱلزَّبَانِیَةَ ۝١٨", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "We will call the Guards.", "translation_id": "kelak Kami akan memanggil malaikat Zabaniyah,", "manzil": 7, "manzil_display": ""}, {"sura": 96, "sura_name": "العلق", "revelation": "Makkiyah", "aya": 19, "text": "كَلَّا لَا تُطِعۡهُ وَ̅ٱ̅سۡ̅جُ̅دۡ̅ وَٱقۡتَرِب ۝١٩ ۩", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أرأيت أعجب مِن طغيان هذا الرجل (وهو أبو جهل) الذي ينهى عبدًا لنا إذا صلَّى لربه (وهو محمد صلى الله عليه وسلم)؟ أرأيت إن كان المنهي عن الصلاة على الهدى فكيف ينهاه؟ أو إن كان آمرًا غيره بالتقوى أينهاه عن ذلك؟ أرأيت إن كذَّب هذا الناهي بما يُدعى إليه، وأعرض عنه، ألم يعلم بأن الله يرى كل ما يفعل؟ ليس الأمر كما يزعم أبو جهل، لئن لم يرجع هذا عن شقاقه وأذاه لنأخذنَّ بمقدَّم رأسه أخذًا عنيفًا، ويُطرح في النار، ناصيته ناصية كاذبة في مقالها، خاطئة في أفعالها. فليُحْضِر هذا الطاغية أهل ناديه الذين يستنصر بهم، سندعو ملائكة العذاب. ليس الأمر على ما يظن أبو جهل، إنه لن ينالك -أيها الرسول- بسوء، فلا تطعه فيما دعاك إليه مِن تَرْك الصلاة، واسجد لربك واقترب منه بالتحبب إليه بطاعته.", "isBasmala": false, "translation_en": "No, do not obey him; but kneel down, and come near.", "translation_id": "sekali-kali jangan, janganlah kamu patuh kepadanya; dan sujudlah dan dekatkanlah (dirimu kepada Tuhan).", "manzil": 7, "manzil_display": ""}], "598": [{"sura": 97, "sura_name": "القدر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 97, "sura_name": "القدر", "revelation": "Makkiyah", "aya": 1, "text": "إِنَّاۤ أَنزَلۡنَـٰهُ فِی لَیۡلَةِ ٱلۡقَدۡرِ ۝١", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "إنا أنزلنا القرآن في ليلة الشرف والفضل، وهي إحدى ليالي شهر رمضان.", "isBasmala": false, "translation_en": "We sent it down on the Night of Decree.", "translation_id": "Sesungguhnya Kami telah menurunkannya (Al Quran) pada malam kemuliaan.", "manzil": 7, "manzil_display": ""}, {"sura": 97, "sura_name": "القدر", "revelation": "Makkiyah", "aya": 2, "text": "وَمَاۤ أَدۡرَىٰكَ مَا لَیۡلَةُ ٱلۡقَدۡرِ ۝٢", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "وما أدراك -أيها النبي- ما ليلة القدر والشرف؟", "isBasmala": false, "translation_en": "But what will convey to you what the Night of Decree is?", "translation_id": "Dan tahukah kamu apakah malam kemuliaan itu?", "manzil": 7, "manzil_display": ""}, {"sura": 97, "sura_name": "القدر", "revelation": "Makkiyah", "aya": 3, "text": "لَیۡلَةُ ٱلۡقَدۡرِ خَیۡرࣱ مِّنۡ أَلۡفِ شَهۡرࣲ ۝٣", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "ليلة القدر ليلة مباركة، فَضْلُها خير من فضل ألف شهر ليس فيها ليلة قدر.", "isBasmala": false, "translation_en": "The Night of Decree is better than a thousand months.", "translation_id": "Malam kemuliaan itu lebih baik dari seribu bulan.", "manzil": 7, "manzil_display": ""}, {"sura": 97, "sura_name": "القدر", "revelation": "Makkiyah", "aya": 4, "text": "تَنَزَّلُ ٱلۡمَلَـٰۤىِٕكَةُ وَٱلرُّوحُ فِیهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرࣲ ۝٤", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "يكثر نزول الملائكة وجبريل عليه السلام فيها، بإذن ربهم من كل أمر قضاه في تلك السنة.", "isBasmala": false, "translation_en": "In it descend the angels and the Spirit, by the leave of their Lord, with every command.", "translation_id": "Pada malam itu turun malaikat-malaikat dan malaikat Jibril dengan izin Tuhannya untuk mengatur segala urusan.", "manzil": 7, "manzil_display": ""}, {"sura": 97, "sura_name": "القدر", "revelation": "Makkiyah", "aya": 5, "text": "سَلَـٰمٌ هِیَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ ۝٥", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "هي أمن كلها، لا شرَّ فيها إلى مطلع الفجر.", "isBasmala": false, "translation_en": "Peace it is; until the rise of dawn.", "translation_id": "Malam itu (penuh) kesejahteraan sampai terbit fajar.", "manzil": 7, "manzil_display": ""}, {"sura": 98, "sura_name": "البينة", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 98, "sura_name": "البينة", "revelation": "Madaniyah", "aya": 1, "text": "لَمۡ یَكُنِ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ وَٱلۡمُشۡرِكِینَ مُنفَكِّینَ حَتَّىٰ تَأۡتِیَهُمُ ٱلۡبَیِّنَةُ ۝١", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "لم يكن الذين كفروا من اليهود والنصارى والمشركين تاركين كفرهم حتى تأتيهم العلامة التي وُعِدوا بها في الكتب السابقة.", "isBasmala": false, "translation_en": "Those who disbelieved among the People of the Scripture, and the Polytheists, were not apart, until the Clear Evidence came to them.", "translation_id": "Orang-orang kafir yakni ahli Kitab dan orang-orang musyrik (mengatakan bahwa mereka) tidak akan meninggalkan (agamanya) sebelum datang kepada mereka bukti yang nyata,", "manzil": 7, "manzil_display": ""}, {"sura": 98, "sura_name": "البينة", "revelation": "Madaniyah", "aya": 2, "text": "رَسُولࣱ مِّنَ ٱللَّهِ یَتۡلُوا۟ صُحُفࣰا مُّطَهَّرَةࣰ ۝٢", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "وهي رسول الله محمد صلى الله عليه وسلم، يتلو قرآنًا في صحف مطهرة.", "isBasmala": false, "translation_en": "A messenger from God reciting purified scripts.", "translation_id": "(yaitu) seorang Rasul dari Allah (Muhammad) yang membacakan lembaran-lembaran yang disucikan (Al Quran),", "manzil": 7, "manzil_display": ""}, {"sura": 98, "sura_name": "البينة", "revelation": "Madaniyah", "aya": 3, "text": "فِیهَا كُتُبࣱ قَیِّمَةࣱ ۝٣", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "في تلك الصحف أخبار صادقة وأوامر عادلة، تهدي إلى الحق وإلى صراط مستقيم.", "isBasmala": false, "translation_en": "In them are valuable writings.", "translation_id": "di dalamnya terdapat (isi) Kitab-kitab yang lurus.", "manzil": 7, "manzil_display": ""}, {"sura": 98, "sura_name": "البينة", "revelation": "Madaniyah", "aya": 4, "text": "وَمَا تَفَرَّقَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَاۤءَتۡهُمُ ٱلۡبَیِّنَةُ ۝٤", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "وما اختلف الذين أوتوا الكتاب من اليهود والنصارى في كون محمد صلى الله عليه وسلم رسولا حقًا؛ لما يجدونه من نعته في كتابهم، إلا مِن بعد ما تبينوا أنه النبي الذي وُعِدوا به في التوراة والإنجيل، فكانوا مجتمعين على صحة نبوته، فلما بُعِث جحدوها وتفرَّقوا.", "isBasmala": false, "translation_en": "Those who were given the Scripture did not splinter, except after the Clear Evidence came to them.", "translation_id": "Dan tidaklah berpecah belah orang-orang yang didatangkan Al Kitab (kepada mereka) melainkan sesudah datang kepada mereka bukti yang nyata.", "manzil": 7, "manzil_display": ""}, {"sura": 98, "sura_name": "البينة", "revelation": "Madaniyah", "aya": 5, "text": "وَمَاۤ أُمِرُوۤا۟ إِلَّا لِیَعۡبُدُوا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ حُنَفَاۤءَ وَیُقِیمُوا۟ ٱلصَّلَوٰةَ وَیُؤۡتُوا۟ ٱلزَّكَوٰةَۚ وَذَ ٰلِكَ دِینُ ٱلۡقَیِّمَةِ ۝٥", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "وما أمروا في سائر الشرائع إلا ليعبدوا الله وحده قاصدين بعبادتهم وجهه، مائلين عن الشرك إلى الإيمان، ويقيموا الصلاة، ويُؤَدُّوا الزكاة، وذلك هو دين الاستقامة، وهو الإسلام.", "isBasmala": false, "translation_en": "They were commanded only to worship God, devoting their faith to Him alone, and to practice regular prayer, and to give alms. That is the upright religion.", "translation_id": "Padahal mereka tidak disuruh kecuali supaya menyembah Allah dengan memurnikan ketaatan kepada-Nya dalam (menjalankan) agama yang lurus, dan supaya mereka mendirikan shalat dan menunaikan zakat; dan yang demikian itulah agama yang lurus.", "manzil": 7, "manzil_display": ""}, {"sura": 98, "sura_name": "البينة", "revelation": "Madaniyah", "aya": 6, "text": "إِنَّ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ وَٱلۡمُشۡرِكِینَ فِی نَارِ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۤۚ أُو۟لَـٰۤىِٕكَ هُمۡ شَرُّ ٱلۡبَرِیَّةِ ۝٦", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "إن الذين كفروا من اليهود والنصارى والمشركين عقابهم نار جهنم خالدين فيها، أولئك هم أشد الخليقة شرا.", "isBasmala": false, "translation_en": "Those who disbelieve among the People of the Scripture, and the Polytheists, will be in the Fire of Hell, where they will abide forever. These are the worst of creatures.", "translation_id": "Sesungguhnya orang-orang yang kafir yakni ahli Kitab dan orang-orang yang musyrik (akan masuk) ke neraka Jahannam; mereka kekal di dalamnya. Mereka itu adalah seburuk-buruk makhluk.", "manzil": 7, "manzil_display": ""}, {"sura": 98, "sura_name": "البينة", "revelation": "Madaniyah", "aya": 7, "text": "إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰۤىِٕكَ هُمۡ خَیۡرُ ٱلۡبَرِیَّةِ ۝٧", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "إن الذين صَدَّقوا الله واتبعوا رسوله وعملوا الصالحات، أولئك هم خير الخلق.", "isBasmala": false, "translation_en": "As for those who believe and lead a righteous life-these are the best of creatures.", "translation_id": "Sesungguhnya orang-orang yang beriman dan mengerjakan amal saleh, mereka itu adalah sebaik-baik makhluk.", "manzil": 7, "manzil_display": ""}], "599": [{"sura": 98, "sura_name": "البينة", "revelation": "Madaniyah", "aya": 8, "text": "جَزَاۤؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّـٰتُ عَدۡنࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ رَّضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُۚ ذَ ٰلِكَ لِمَنۡ خَشِیَ رَبَّهُۥ ۝٨", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "جزاؤهم عند ربهم يوم القيامة جنات إقامة واستقرار في منتهى الحسن، تجري من تحت قصورها الأنهار، خالدين فيها أبدًا، رضي الله عنهم فقبل أعمالهم الصالحة، ورضوا عنه بما أعدَّ لهم من أنواع الكرامات، ذلك الجزاء الحسن لمن خاف الله واجتنب معاصيه.", "isBasmala": false, "translation_en": "Their reward is with their Lord: Gardens of Eternity beneath which rivers flow, where they will abide forever. God is pleased with them, and they are pleased with Him. That is for whoever fears His Lord.", "translation_id": "Balasan mereka di sisi Tuhan mereka ialah surga 'Adn yang mengalir di bawahnya sungai-sungai; mereka kekal di dalamnya selama-lamanya. Allah ridha terhadap mereka dan merekapun ridha kepada-Nya. Yang demikian itu adalah (balasan) bagi orang yang takut kepada Tuhannya.", "manzil": 7, "manzil_display": ""}, {"sura": 99, "sura_name": "الزلزلة", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 99, "sura_name": "الزلزلة", "revelation": "Madaniyah", "aya": 1, "text": "إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا ۝١", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "إذا رُجَّت الأرض رجًّا شديدًا، وأخرجت ما في بطنها من موتى وكنوز، وتساءل الإنسان فزعًا: ما الذي حدث لها؟", "isBasmala": false, "translation_en": "When the earth is shaken with its quake.", "translation_id": "Apabila bumi digoncangkan dengan goncangan (yang dahsyat),", "manzil": 7, "manzil_display": ""}, {"sura": 99, "sura_name": "الزلزلة", "revelation": "Madaniyah", "aya": 2, "text": "وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا ۝٢", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "إذا رُجَّت الأرض رجًّا شديدًا، وأخرجت ما في بطنها من موتى وكنوز، وتساءل الإنسان فزعًا: ما الذي حدث لها؟", "isBasmala": false, "translation_en": "And the earth brings out its loads.", "translation_id": "dan bumi telah mengeluarkan beban-beban berat (yang dikandung)nya,", "manzil": 7, "manzil_display": ""}, {"sura": 99, "sura_name": "الزلزلة", "revelation": "Madaniyah", "aya": 3, "text": "وَقَالَ ٱلۡإِنسَـٰنُ مَا لَهَا ۝٣", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "إذا رُجَّت الأرض رجًّا شديدًا، وأخرجت ما في بطنها من موتى وكنوز، وتساءل الإنسان فزعًا: ما الذي حدث لها؟", "isBasmala": false, "translation_en": "And man says, \"What is the matter with it?\"", "translation_id": "dan manusia bertanya: \"Mengapa bumi (menjadi begini)?\",", "manzil": 7, "manzil_display": ""}, {"sura": 99, "sura_name": "الزلزلة", "revelation": "Madaniyah", "aya": 4, "text": "یَوۡمَىِٕذࣲ تُحَدِّثُ أَخۡبَارَهَا ۝٤", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "يوم القيامة تخبر الأرض بما عُمل عليها من خير أو شر، وبأن الله سبحانه وتعالى أمرها بأن تخبر بما عُمل عليها.", "isBasmala": false, "translation_en": "On that Day, it will tell its tales.", "translation_id": "pada hari itu bumi menceritakan beritanya,", "manzil": 7, "manzil_display": ""}, {"sura": 99, "sura_name": "الزلزلة", "revelation": "Madaniyah", "aya": 5, "text": "بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا ۝٥", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "يوم القيامة تخبر الأرض بما عُمل عليها من خير أو شر، وبأن الله سبحانه وتعالى أمرها بأن تخبر بما عُمل عليها.", "isBasmala": false, "translation_en": "For your Lord will have inspired it.", "translation_id": "karena sesungguhnya Tuhanmu telah memerintahkan (yang sedemikian itu) kepadanya.", "manzil": 7, "manzil_display": ""}, {"sura": 99, "sura_name": "الزلزلة", "revelation": "Madaniyah", "aya": 6, "text": "یَوۡمَىِٕذࣲ یَصۡدُرُ ٱلنَّاسُ أَشۡتَاتࣰا لِّیُرَوۡا۟ أَعۡمَـٰلَهُمۡ ۝٦", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "يومئذ يرجع الناس عن موقف الحساب أصنافًا متفرقين؛ ليريهم الله ما عملوا من السيئات والحسنات، ويجازيهم عليها.", "isBasmala": false, "translation_en": "On that Day, the people will emerge in droves, to be shown their works.", "translation_id": "Pada hari itu manusia ke luar dari kuburnya dalam keadaan bermacam-macam, supaya diperlihatkan kepada mereka (balasan) pekerjaan mereka,", "manzil": 7, "manzil_display": ""}, {"sura": 99, "sura_name": "الزلزلة", "revelation": "Madaniyah", "aya": 7, "text": "فَمَن یَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَیۡرࣰا یَرَهُۥ ۝٧", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فمن يعمل وزن نملة صغيرة خيرًا، ير ثوابه في الآخرة، ومن يعمل وزن نملة صغيرة شرًا، ير عقابه في الآخرة.", "isBasmala": false, "translation_en": "Whoever has done an atom's weight of good will see it.", "translation_id": "Barangsiapa yang mengerjakan kebaikan seberat dzarrahpun, niscaya dia akan melihat (balasan)nya.", "manzil": 7, "manzil_display": ""}, {"sura": 99, "sura_name": "الزلزلة", "revelation": "Madaniyah", "aya": 8, "text": "وَمَن یَعۡمَلۡ مِثۡقَالَ ذَرَّةࣲ شَرࣰّا یَرَهُۥ ۝٨", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فمن يعمل وزن نملة صغيرة خيرًا، ير ثوابه في الآخرة، ومن يعمل وزن نملة صغيرة شرًا، ير عقابه في الآخرة.", "isBasmala": false, "translation_en": "And whoever has done an atom's weight of evil will see it.", "translation_id": "Dan barangsiapa yang mengerjakan kejahatan sebesar dzarrahpun, niscaya dia akan melihat (balasan)nya pula.", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلۡعَـٰدِیَـٰتِ ضَبۡحࣰا ۝١", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "أقسم الله تعالى بالخيل الجاريات في سبيله نحو العدوِّ، حين يظهر صوتها من سرعة عَدْوِها. ولا يجوز للمخلوق أن يقسم إلا بالله، فإن القسم بغير الله شرك.", "isBasmala": false, "translation_en": "By the racers panting.", "translation_id": "Demi kuda perang yang berlari kencang dengan terengah-engah,", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 2, "text": "فَٱلۡمُورِیَـٰتِ قَدۡحࣰا ۝٢", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فالخيل اللاتي تنقدح النار من صلابة حوافرها؛ من شدَّة عَدْوها.", "isBasmala": false, "translation_en": "Igniting sparks.", "translation_id": "dan kuda yang mencetuskan api dengan pukulan (kuku kakinya),", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 3, "text": "فَٱلۡمُغِیرَ ٰتِ صُبۡحࣰا ۝٣", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فالمغيرات على الأعداء عند الصبح.", "isBasmala": false, "translation_en": "Raiding at dawn.", "translation_id": "dan kuda yang menyerang dengan tiba-tiba di waktu pagi,", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 4, "text": "فَأَثَرۡنَ بِهِۦ نَقۡعࣰا ۝٤", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فهيَّجْنَ بهذا العَدْو غبارًا.", "isBasmala": false, "translation_en": "Raising clouds of dust.", "translation_id": "maka ia menerbangkan debu,", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 5, "text": "فَوَسَطۡنَ بِهِۦ جَمۡعًا ۝٥", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "فتوسَّطن بركبانهن جموع الأعداء.", "isBasmala": false, "translation_en": "Storming into the midst.", "translation_id": "dan menyerbu ke tengah-tengah kumpulan musuh,", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 6, "text": "إِنَّ ٱلۡإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودࣱ ۝٦", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "إن الإنسان لِنعم ربه لَجحود، وإنه بجحوده ذلك لمقر. وإنه لحب المال لشديد.", "isBasmala": false, "translation_en": "Indeed, the human being is ungrateful to his Lord.", "translation_id": "sesungguhnya manusia itu sangat ingkar, tidak berterima kasih kepada Tuhannya,", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 7, "text": "وَإِنَّهُۥ عَلَىٰ ذَ ٰلِكَ لَشَهِیدࣱ ۝٧", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "إن الإنسان لِنعم ربه لَجحود، وإنه بجحوده ذلك لمقر. وإنه لحب المال لشديد.", "isBasmala": false, "translation_en": "And he bears witness to that.", "translation_id": "dan sesungguhnya manusia itu menyaksikan (sendiri) keingkarannya,", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 8, "text": "وَإِنَّهُۥ لِحُبِّ ٱلۡخَیۡرِ لَشَدِیدٌ ۝٨", "juz": 30, "hizb": "(*½ ح 60*)", "tafsir": "إن الإنسان لِنعم ربه لَجحود، وإنه بجحوده ذلك لمقر. وإنه لحب المال لشديد.", "isBasmala": false, "translation_en": "And he is fierce in his love of wealth.", "translation_id": "dan sesungguhnya dia sangat bakhil karena cintanya kepada harta.", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 9, "text": "۞ أَفَلَا یَعۡلَمُ إِذَا بُعۡثِرَ مَا فِی ٱلۡقُبُورِ ۝٩", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "أفلا يعلم الإنسان ما ينتظره إذا أخرج الله الأموات من القبور للحساب والجزاء؟", "isBasmala": false, "translation_en": "Does he not know? When the contents of the graves are scattered around.", "translation_id": "Maka apakah dia tidak mengetahui apabila dibangkitkan apa yang ada di dalam kubur,", "manzil": 7, "manzil_display": ""}], "600": [{"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 10, "text": "وَحُصِّلَ مَا فِی ٱلصُّدُورِ ۝١٠", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "واستُخرج ما استتر في الصدور من خير أو شر.", "isBasmala": false, "translation_en": "And the contents of the hearts are obtained.", "translation_id": "dan dilahirkan apa yang ada di dalam dada,", "manzil": 7, "manzil_display": ""}, {"sura": 100, "sura_name": "العاديات", "revelation": "Makkiyah", "aya": 11, "text": "إِنَّ رَبَّهُم بِهِمۡ یَوۡمَىِٕذࣲ لَّخَبِیرُۢ ۝١١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إن ربهم بهم وبأعمالهم يومئذ لخبير، لا يخفى عليه شيء من ذلك.", "isBasmala": false, "translation_en": "Their Lord, on that Day, is fully informed of them.", "translation_id": "sesungguhnya Tuhan mereka pada hari itu Maha Mengetahui keadaan mereka.", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 1, "text": "ٱلۡقَارِعَةُ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "الساعة التي تقرع قلوب الناس بأهوالها.", "isBasmala": false, "translation_en": "The Shocker.", "translation_id": "Hari Kiamat,", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 2, "text": "مَا ٱلۡقَارِعَةُ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "أيُّ شيء هذه القارعة؟", "isBasmala": false, "translation_en": "What is the Shocker?", "translation_id": "apakah hari Kiamat itu?", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 3, "text": "وَمَاۤ أَدۡرَىٰكَ مَا ٱلۡقَارِعَةُ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "وأيُّ شيء أعلمك بها؟", "isBasmala": false, "translation_en": "What will explain to you what the Shocker is?", "translation_id": "Tahukah kamu apakah hari Kiamat itu?", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 4, "text": "یَوۡمَ یَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "في ذلك اليوم يكون الناس في كثرتهم وتفرقهم وحركتهم كالفراش المنتشر، وهو الذي يتساقط في النار.", "isBasmala": false, "translation_en": "The Day when the people will be like scattered moths.", "translation_id": "Pada hari itu manusia adalah seperti anai-anai yang bertebaran,", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 5, "text": "وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٱلۡمَنفُوشِ ۝٥", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "وتكون الجبال كالصوف متعدد الألوان الذي يُنْفَش باليد، فيصير هباء ويزول.", "isBasmala": false, "translation_en": "And the mountains will be like tufted wool.", "translation_id": "dan gunung-gunung adalah seperti bulu yang dihambur-hamburkan.", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 6, "text": "فَأَمَّا مَن ثَقُلَتۡ مَوَ ٰزِینُهُۥ ۝٦", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "فأما من رجحت موازين حسناته، فهو في حياة مرضية في الجنة.", "isBasmala": false, "translation_en": "As for he whose scales are heavy.", "translation_id": "Dan adapun orang-orang yang berat timbangan (kebaikan)nya,", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 7, "text": "فَهُوَ فِی عِیشَةࣲ رَّاضِیَةࣲ ۝٧", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "فأما من رجحت موازين حسناته، فهو في حياة مرضية في الجنة.", "isBasmala": false, "translation_en": "He will be in a pleasant life.", "translation_id": "maka dia berada dalam kehidupan yang memuaskan.", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 8, "text": "وَأَمَّا مَنۡ خَفَّتۡ مَوَ ٰزِینُهُۥ ۝٨", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "وأما من خفت موازين حسناته، ورجحت موازين سيئاته، فمأواه جهنم.", "isBasmala": false, "translation_en": "But as for he whose scales are light.", "translation_id": "Dan adapun orang-orang yang ringan timbangan (kebaikan)nya,", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 9, "text": "فَأُمُّهُۥ هَاوِیَةࣱ ۝٩", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "وأما من خفت موازين حسناته، ورجحت موازين سيئاته، فمأواه جهنم.", "isBasmala": false, "translation_en": "His home is the Abyss.", "translation_id": "maka tempat kembalinya adalah neraka Hawiyah.", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 10, "text": "وَمَاۤ أَدۡرَىٰكَ مَا هِیَهۡ ۝١٠", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "وما أدراك -أيها الرسول- ما هذه الهاوية؟", "isBasmala": false, "translation_en": "Do you know what it is?", "translation_id": "Tahukah kamu apakah neraka Hawiyah itu?", "manzil": 7, "manzil_display": ""}, {"sura": 101, "sura_name": "القارعة", "revelation": "Makkiyah", "aya": 11, "text": "نَارٌ حَامِیَةُۢ ۝١١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إنها نار قد حَمِيت من الوقود عليها.", "isBasmala": false, "translation_en": "A Raging Fire.", "translation_id": "(Yaitu) api yang sangat panas.", "manzil": 7, "manzil_display": ""}, {"sura": 102, "sura_name": "التكاثر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 102, "sura_name": "التكاثر", "revelation": "Makkiyah", "aya": 1, "text": "أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "شغلكم عن طاعة الله التفاخر بكثرة الأموال والأولاد.", "isBasmala": false, "translation_en": "Abundance distracts you.", "translation_id": "Bermegah-megahan telah melalaikan kamu,", "manzil": 7, "manzil_display": ""}, {"sura": 102, "sura_name": "التكاثر", "revelation": "Makkiyah", "aya": 2, "text": "حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "واستمر اشتغالكم بذلك إلى أن صرتم إلى المقابر، ودُفنتم فيها.", "isBasmala": false, "translation_en": "Until you visit the graveyards.", "translation_id": "sampai kamu masuk ke dalam kubur.", "manzil": 7, "manzil_display": ""}, {"sura": 102, "sura_name": "التكاثر", "revelation": "Makkiyah", "aya": 3, "text": "كَلَّا سَوۡفَ تَعۡلَمُونَ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ما هكذا ينبغي أن يُلْهيكم التكاثر بالأموال، سوف تتبيَّنون أن الدار الآخرة خير لكم.", "isBasmala": false, "translation_en": "Indeed, you will know.", "translation_id": "Janganlah begitu, kelak kamu akan mengetahui (akibat perbuatanmu itu),", "manzil": 7, "manzil_display": ""}, {"sura": 102, "sura_name": "التكاثر", "revelation": "Makkiyah", "aya": 4, "text": "ثُمَّ كَلَّا سَوۡفَ تَعۡلَمُونَ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ثم احذروا سوف تعلمون سوء عاقبة انشغالكم عنها.", "isBasmala": false, "translation_en": "Certainly, you will know.", "translation_id": "dan janganlah begitu, kelak kamu akan mengetahui.", "manzil": 7, "manzil_display": ""}, {"sura": 102, "sura_name": "التكاثر", "revelation": "Makkiyah", "aya": 5, "text": "كَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡیَقِینِ ۝٥", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ما هكذا ينبغي أن يلهيكم التكاثر بالأموال، لو تعلمون حق العلم لانزجرتم، ولبادرتم إلى إنقاذ أنفسكم من الهلاك. لتبصرُنَّ الجحيم، ثم لتبصرُنَّها دون ريب، ثم لتسألُنَّ يوم القيامة عن كل أنواع النعيم.", "isBasmala": false, "translation_en": "If you knew with knowledge of certainty.", "translation_id": "Janganlah begitu, jika kamu mengetahui dengan pengetahuan yang yakin,", "manzil": 7, "manzil_display": ""}, {"sura": 102, "sura_name": "التكاثر", "revelation": "Makkiyah", "aya": 6, "text": "لَتَرَوُنَّ ٱلۡجَحِیمَ ۝٦", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ما هكذا ينبغي أن يلهيكم التكاثر بالأموال، لو تعلمون حق العلم لانزجرتم، ولبادرتم إلى إنقاذ أنفسكم من الهلاك. لتبصرُنَّ الجحيم، ثم لتبصرُنَّها دون ريب، ثم لتسألُنَّ يوم القيامة عن كل أنواع النعيم.", "isBasmala": false, "translation_en": "You would see the Inferno.", "translation_id": "niscaya kamu benar-benar akan melihat neraka Jahiim,", "manzil": 7, "manzil_display": ""}, {"sura": 102, "sura_name": "التكاثر", "revelation": "Makkiyah", "aya": 7, "text": "ثُمَّ لَتَرَوُنَّهَا عَیۡنَ ٱلۡیَقِینِ ۝٧", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ما هكذا ينبغي أن يلهيكم التكاثر بالأموال، لو تعلمون حق العلم لانزجرتم، ولبادرتم إلى إنقاذ أنفسكم من الهلاك. لتبصرُنَّ الجحيم، ثم لتبصرُنَّها دون ريب، ثم لتسألُنَّ يوم القيامة عن كل أنواع النعيم.", "isBasmala": false, "translation_en": "Then you will see it with the eye of certainty.", "translation_id": "dan sesungguhnya kamu benar-benar akan melihatnya dengan 'ainul yaqin.", "manzil": 7, "manzil_display": ""}, {"sura": 102, "sura_name": "التكاثر", "revelation": "Makkiyah", "aya": 8, "text": "ثُمَّ لَتُسۡـَٔلُنَّ یَوۡمَىِٕذٍ عَنِ ٱلنَّعِیمِ ۝٨", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ما هكذا ينبغي أن يلهيكم التكاثر بالأموال، لو تعلمون حق العلم لانزجرتم، ولبادرتم إلى إنقاذ أنفسكم من الهلاك. لتبصرُنَّ الجحيم، ثم لتبصرُنَّها دون ريب، ثم لتسألُنَّ يوم القيامة عن كل أنواع النعيم.", "isBasmala": false, "translation_en": "Then, on that Day, you will be questioned about the Bliss.", "translation_id": "kemudian kamu pasti akan ditanyai pada hari itu tentang kenikmatan (yang kamu megah-megahkan di dunia itu).", "manzil": 7, "manzil_display": ""}], "601": [{"sura": 103, "sura_name": "العصر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 103, "sura_name": "العصر", "revelation": "Makkiyah", "aya": 1, "text": "وَٱلۡعَصۡرِ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "أقسم الله بالدهر على أن بني آدم لفي هلكة ونقصان. ولا يجوز للعبد أن يقسم إلا بالله، فإن القسم بغير الله شرك.", "isBasmala": false, "translation_en": "By time.", "translation_id": "Demi masa.", "manzil": 7, "manzil_display": ""}, {"sura": 103, "sura_name": "العصر", "revelation": "Makkiyah", "aya": 2, "text": "إِنَّ ٱلۡإِنسَـٰنَ لَفِی خُسۡرٍ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "أقسم الله بالدهر على أن بني آدم لفي هلكة ونقصان. ولا يجوز للعبد أن يقسم إلا بالله، فإن القسم بغير الله شرك.", "isBasmala": false, "translation_en": "The human being is in loss.", "translation_id": "Sesungguhnya manusia itu benar-benar dalam kerugian,", "manzil": 7, "manzil_display": ""}, {"sura": 103, "sura_name": "العصر", "revelation": "Makkiyah", "aya": 3, "text": "إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَتَوَاصَوۡا۟ بِٱلۡحَقِّ وَتَوَاصَوۡا۟ بِٱلصَّبۡرِ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إلا الذين آمنوا بالله وعملوا عملا صالحًا، وأوصى بعضهم بعضًا بالاستمساك بالحق، والعمل بطاعة الله، والصبر على ذلك.", "isBasmala": false, "translation_en": "Except those who believe, and do good works, and encourage truth, and recommend patience.", "translation_id": "kecuali orang-orang yang beriman dan mengerjakan amal saleh dan nasehat menasehati supaya mentaati kebenaran dan nasehat menasehati supaya menetapi kesabaran.", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 1, "text": "وَیۡلࣱ لِّكُلِّ هُمَزَةࣲ لُّمَزَةٍ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "شر وهلاك لكل مغتاب للناس، طعان فيهم.", "isBasmala": false, "translation_en": "Woe to every slanderer backbiter.", "translation_id": "Kecelakaanlah bagi setiap pengumpat lagi pencela,", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 2, "text": "ٱلَّذِی جَمَعَ مَالࣰا وَعَدَّدَهُۥ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "الذي كان همُّه جمع المال وتعداده.", "isBasmala": false, "translation_en": "Who gathers wealth and counts it over.", "translation_id": "yang mengumpulkan harta dan menghitung-hitung,", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 3, "text": "یَحۡسَبُ أَنَّ مَالَهُۥۤ أَخۡلَدَهُۥ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "يظن أنه ضَمِنَ لنفسه بهذا المال الذي جمعه، الخلود في الدنيا والإفلات من الحساب.", "isBasmala": false, "translation_en": "Thinking that his wealth has made him immortal.", "translation_id": "dia mengira bahwa hartanya itu dapat mengkekalkannya,", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 4, "text": "كَلَّاۖ لَیُنۢبَذَنَّ فِی ٱلۡحُطَمَةِ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ليس الأمر كما ظن، ليُطرحنَّ في النار التي تهشم كل ما يُلْقى فيها.", "isBasmala": false, "translation_en": "By no means. He will be thrown into the Crusher.", "translation_id": "sekali-kali tidak! Sesungguhnya dia benar-benar akan dilemparkan ke dalam Huthamah.", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 5, "text": "وَمَاۤ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ ۝٥", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "وما أدراك -أيها الرسول- ما حقيقة النار؟", "isBasmala": false, "translation_en": "And what will make you realize what the Crusher is?", "translation_id": "Dan tahukah kamu apa Huthamah itu?", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 6, "text": "نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ ۝٦", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إنها نار الله الموقدة التي من شدتها تنفُذ من الأجسام إلى القلوب.", "isBasmala": false, "translation_en": "God's kindled Fire.", "translation_id": "(yaitu) api (yang disediakan) Allah yang dinyalakan,", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 7, "text": "ٱلَّتِی تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ ۝٧", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إنها نار الله الموقدة التي من شدتها تنفُذ من الأجسام إلى القلوب.", "isBasmala": false, "translation_en": "That laps to the hearts.", "translation_id": "yang (membakar) sampai ke hati.", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 8, "text": "إِنَّهَا عَلَیۡهِم مُّؤۡصَدَةࣱ ۝٨", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إنها عليهم مطبَقة في سلاسل وأغلال مطوَّلة؛ لئلا يخرجوا منها.", "isBasmala": false, "translation_en": "It closes in on them.", "translation_id": "Sesungguhnya api itu ditutup rapat atas mereka,", "manzil": 7, "manzil_display": ""}, {"sura": 104, "sura_name": "الهمزة", "revelation": "Makkiyah", "aya": 9, "text": "فِی عَمَدࣲ مُّمَدَّدَةِۭ ۝٩", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إنها عليهم مطبَقة في سلاسل وأغلال مطوَّلة؛ لئلا يخرجوا منها.", "isBasmala": false, "translation_en": "In extended columns.", "translation_id": "(sedang mereka itu) diikat pada tiang-tiang yang panjang.", "manzil": 7, "manzil_display": ""}, {"sura": 105, "sura_name": "الفيل", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 105, "sura_name": "الفيل", "revelation": "Makkiyah", "aya": 1, "text": "أَلَمۡ تَرَ كَیۡفَ فَعَلَ رَبُّكَ بِأَصۡحَـٰبِ ٱلۡفِیلِ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ألم تعلم -أيها الرسول- كيف فعل ربك بأصحاب الفيل: أبرهة الحبشي وجيشه الذين أرادوا تدمير الكعبة المباركة؟", "isBasmala": false, "translation_en": "Have you not considered how your Lord dealt with the People of the Elephant?", "translation_id": "Apakah kamu tidak memperhatikan bagaimana Tuhanmu telah bertindak terhadap tentara bergajah?", "manzil": 7, "manzil_display": ""}, {"sura": 105, "sura_name": "الفيل", "revelation": "Makkiyah", "aya": 2, "text": "أَلَمۡ یَجۡعَلۡ كَیۡدَهُمۡ فِی تَضۡلِیلࣲ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ألم يجعل ما دبَّروه من شر في إبطال وتضييع؟", "isBasmala": false, "translation_en": "Did He not make their plan go wrong?", "translation_id": "Bukankah Dia telah menjadikan tipu daya mereka (untuk menghancurkan Ka'bah) itu sia-sia?", "manzil": 7, "manzil_display": ""}, {"sura": 105, "sura_name": "الفيل", "revelation": "Makkiyah", "aya": 3, "text": "وَأَرۡسَلَ عَلَیۡهِمۡ طَیۡرًا أَبَابِیلَ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "وبعث عليهم طيرًا في جماعات متتابعة، تقذفهم بحجارة من طين متحجِّر.", "isBasmala": false, "translation_en": "He sent against them swarms of birds.", "translation_id": "dan Dia mengirimkan kapada mereka burung yang berbondong-bondong,", "manzil": 7, "manzil_display": ""}, {"sura": 105, "sura_name": "الفيل", "revelation": "Makkiyah", "aya": 4, "text": "تَرۡمِیهِم بِحِجَارَةࣲ مِّن سِجِّیلࣲ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "وبعث عليهم طيرًا في جماعات متتابعة، تقذفهم بحجارة من طين متحجِّر.", "isBasmala": false, "translation_en": "Throwing at them rocks of baked clay.", "translation_id": "yang melempari mereka dengan batu (berasal) dari tanah yang terbakar,", "manzil": 7, "manzil_display": ""}, {"sura": 105, "sura_name": "الفيل", "revelation": "Makkiyah", "aya": 5, "text": "فَجَعَلَهُمۡ كَعَصۡفࣲ مَّأۡكُولِۭ ۝٥", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "فجعلهم به محطمين كأوراق الزرع اليابسة التي أكلتها البهائم ثم رمت بها.", "isBasmala": false, "translation_en": "Leaving them like chewed-up leaves.", "translation_id": "lalu Dia menjadikan mereka seperti daun-daun yang dimakan (ulat).", "manzil": 7, "manzil_display": ""}], "602": [{"sura": 106, "sura_name": "قريش", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 106, "sura_name": "قريش", "revelation": "Makkiyah", "aya": 1, "text": "لِإِیلَـٰفِ قُرَیۡشٍ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "اعْجَبوا لإلف قريش، وأمنهم، واستقامة مصالحهم، وانتظام رحلتيهم في الشتاء إلى \"اليمن\"، وفي الصيف إلى \"الشام\"، وتيسير ذلك؛ لجلب ما يحتاجون إليه.", "isBasmala": false, "translation_en": "For the security of Quraish.", "translation_id": "Karena kebiasaan orang-orang Quraisy,", "manzil": 7, "manzil_display": ""}, {"sura": 106, "sura_name": "قريش", "revelation": "Makkiyah", "aya": 2, "text": "إِۦلَـٰفِهِمۡ رِحۡلَةَ ٱلشِّتَاۤءِ وَٱلصَّیۡفِ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "اعْجَبوا لإلف قريش، وأمنهم، واستقامة مصالحهم، وانتظام رحلتيهم في الشتاء إلى \"اليمن\"، وفي الصيف إلى \"الشام\"، وتيسير ذلك؛ لجلب ما يحتاجون إليه.", "isBasmala": false, "translation_en": "Their security during winter and summer journeys.", "translation_id": "(yaitu) kebiasaan mereka bepergian pada musim dingin dan musim panas.", "manzil": 7, "manzil_display": ""}, {"sura": 106, "sura_name": "قريش", "revelation": "Makkiyah", "aya": 3, "text": "فَلۡیَعۡبُدُوا۟ رَبَّ هَـٰذَا ٱلۡبَیۡتِ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "فليشكروا، وليعبدوا رب هذا البيت -وهو الكعبة- الذي شرفوا به، وليوحدوه ويخلصوا له العبادة.", "isBasmala": false, "translation_en": "Let them worship the Lord of this House.", "translation_id": "Maka hendaklah mereka menyembah Tuhan Pemilik rumah ini (Ka'bah).", "manzil": 7, "manzil_display": ""}, {"sura": 106, "sura_name": "قريش", "revelation": "Makkiyah", "aya": 4, "text": "ٱلَّذِیۤ أَطۡعَمَهُم مِّن جُوعࣲ وَءَامَنَهُم مِّنۡ خَوۡفِۭ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "الذي أطعمهم من جوع شديد، وآمنهم من فزع وخوف عظيم.", "isBasmala": false, "translation_en": "Who has fed them against hunger, and has secured them against fear.", "translation_id": "Yang telah memberi makanan kepada mereka untuk menghilangkan lapar dan mengamankan mereka dari ketakutan.", "manzil": 7, "manzil_display": ""}, {"sura": 107, "sura_name": "الماعون", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 107, "sura_name": "الماعون", "revelation": "Makkiyah", "aya": 1, "text": "أَرَءَیۡتَ ٱلَّذِی یُكَذِّبُ بِٱلدِّینِ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "أرأيت حال ذلك الذي يكذِّب بالبعث والجزاء؟", "isBasmala": false, "translation_en": "Have you considered him who denies the religion?", "translation_id": "Tahukah kamu (orang) yang mendustakan agama?", "manzil": 7, "manzil_display": ""}, {"sura": 107, "sura_name": "الماعون", "revelation": "Makkiyah", "aya": 2, "text": "فَذَ ٰلِكَ ٱلَّذِی یَدُعُّ ٱلۡیَتِیمَ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "فذلك الذي يدفع اليتيم بعنف وشدة عن حقه؛ لقساوة قلبه.", "isBasmala": false, "translation_en": "It is he who mistreats the orphan.", "translation_id": "Itulah orang yang menghardik anak yatim,", "manzil": 7, "manzil_display": ""}, {"sura": 107, "sura_name": "الماعون", "revelation": "Makkiyah", "aya": 3, "text": "وَلَا یَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِینِ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ولا يحضُّ غيره على إطعام المسكين، فكيف له أن يطعمه بنفسه؟", "isBasmala": false, "translation_en": "And does not encourage the feeding of the poor.", "translation_id": "dan tidak menganjurkan memberi makan orang miskin.", "manzil": 7, "manzil_display": ""}, {"sura": 107, "sura_name": "الماعون", "revelation": "Makkiyah", "aya": 4, "text": "فَوَیۡلࣱ لِّلۡمُصَلِّینَ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "فعذاب شديد للمصلين الذين هم عن صلاتهم لاهون، لا يقيمونها على وجهها، ولا يؤدونها في وقتها.", "isBasmala": false, "translation_en": "So woe to those who pray.", "translation_id": "Maka kecelakaanlah bagi orang-orang yang shalat,", "manzil": 7, "manzil_display": ""}, {"sura": 107, "sura_name": "الماعون", "revelation": "Makkiyah", "aya": 5, "text": "ٱلَّذِینَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ ۝٥", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "فعذاب شديد للمصلين الذين هم عن صلاتهم لاهون، لا يقيمونها على وجهها، ولا يؤدونها في وقتها.", "isBasmala": false, "translation_en": "Those who are heedless of their prayers.", "translation_id": "(yaitu) orang-orang yang lalai dari shalatnya,", "manzil": 7, "manzil_display": ""}, {"sura": 107, "sura_name": "الماعون", "revelation": "Makkiyah", "aya": 6, "text": "ٱلَّذِینَ هُمۡ یُرَاۤءُونَ ۝٦", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "الذين هم يتظاهرون بأعمال الخير مراءاة للناس.", "isBasmala": false, "translation_en": "Those who put on the appearance.", "translation_id": "orang-orang yang berbuat riya,", "manzil": 7, "manzil_display": ""}, {"sura": 107, "sura_name": "الماعون", "revelation": "Makkiyah", "aya": 7, "text": "وَیَمۡنَعُونَ ٱلۡمَاعُونَ ۝٧", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ويمنعون إعارة ما لا تضر إعارته من الآنية وغيرها، فلا هم أحسنوا عبادة ربهم، ولا هم أحسنوا إلى خلقه.", "isBasmala": false, "translation_en": "And withhold the assistance.", "translation_id": "dan enggan (menolong dengan) barang berguna.", "manzil": 7, "manzil_display": ""}, {"sura": 108, "sura_name": "الكوثر", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 108, "sura_name": "الكوثر", "revelation": "Makkiyah", "aya": 1, "text": "إِنَّاۤ أَعۡطَیۡنَـٰكَ ٱلۡكَوۡثَرَ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إنا أعطيناك -أيها النبي- الخير الكثير في الدنيا والآخرة، ومن ذلك نهر الكوثر في الجنة الذي حافتاه خيام اللؤلؤ المجوَّف، وطينه المسك.", "isBasmala": false, "translation_en": "We have given you plenty.", "translation_id": "Sesungguhnya Kami telah memberikan kepadamu nikmat yang banyak.", "manzil": 7, "manzil_display": ""}, {"sura": 108, "sura_name": "الكوثر", "revelation": "Makkiyah", "aya": 2, "text": "فَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "فأخلص لربك صلاتك كلها، واذبح ذبيحتك له وعلى اسمه وحده.", "isBasmala": false, "translation_en": "So pray to your Lord and sacrifice.", "translation_id": "Maka dirikanlah shalat karena Tuhanmu; dan berkorbanlah.", "manzil": 7, "manzil_display": ""}, {"sura": 108, "sura_name": "الكوثر", "revelation": "Makkiyah", "aya": 3, "text": "إِنَّ شَانِئَكَ هُوَ ٱلۡأَبۡتَرُ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إن مبغضك ومبغض ما جئت به من الهدى والنور، هو المنقطع أثره، المقطوع من كل خير.", "isBasmala": false, "translation_en": "He who hates you is the loser.", "translation_id": "Sesungguhnya orang-orang yang membenci kamu dialah yang terputus.", "manzil": 7, "manzil_display": ""}], "603": [{"sura": 109, "sura_name": "الكافرون", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 109, "sura_name": "الكافرون", "revelation": "Makkiyah", "aya": 1, "text": "قُلۡ یَـٰۤأَیُّهَا ٱلۡكَـٰفِرُونَ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "قل -أيها الرسول- للذين كفروا بالله ورسوله: يا أيها الكافرون بالله.", "isBasmala": false, "translation_en": "Say, \"O disbelievers.", "translation_id": "Katakanlah: \"Hai orang-orang kafir,", "manzil": 7, "manzil_display": ""}, {"sura": 109, "sura_name": "الكافرون", "revelation": "Makkiyah", "aya": 2, "text": "لَاۤ أَعۡبُدُ مَا تَعۡبُدُونَ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "لا أعبد ما تعبدون من الأصنام والآلهة الزائفة.", "isBasmala": false, "translation_en": "I do not worship what you worship.", "translation_id": "Aku tidak akan menyembah apa yang kamu sembah.", "manzil": 7, "manzil_display": ""}, {"sura": 109, "sura_name": "الكافرون", "revelation": "Makkiyah", "aya": 3, "text": "وَلَاۤ أَنتُمۡ عَـٰبِدُونَ مَاۤ أَعۡبُدُ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ولا أنتم عابدون ما أعبد من إله واحد، هو الله رب العالمين المستحق وحده للعبادة.", "isBasmala": false, "translation_en": "Nor do you worship what I worship.", "translation_id": "Dan kamu bukan penyembah Tuhan yang aku sembah.", "manzil": 7, "manzil_display": ""}, {"sura": 109, "sura_name": "الكافرون", "revelation": "Makkiyah", "aya": 4, "text": "وَلَاۤ أَنَا۠ عَابِدࣱ مَّا عَبَدتُّمۡ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ولا أنا عابد ما عبدتم من الأصنام والآلهة الباطلة.", "isBasmala": false, "translation_en": "Nor do I serve what you serve.", "translation_id": "Dan aku tidak pernah menjadi penyembah apa yang kamu sembah,", "manzil": 7, "manzil_display": ""}, {"sura": 109, "sura_name": "الكافرون", "revelation": "Makkiyah", "aya": 5, "text": "وَلَاۤ أَنتُمۡ عَـٰبِدُونَ مَاۤ أَعۡبُدُ ۝٥", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ولا أنتم عابدون مستقبلا ما أعبد. وهذه الآية نزلت في أشخاص بأعيانهم من المشركين، قد علم الله أنهم لا يؤمنون أبدًا.", "isBasmala": false, "translation_en": "Nor do you serve what I serve.", "translation_id": "dan kamu tidak pernah (pula) menjadi penyembah Tuhan yang aku sembah.", "manzil": 7, "manzil_display": ""}, {"sura": 109, "sura_name": "الكافرون", "revelation": "Makkiyah", "aya": 6, "text": "لَكُمۡ دِینُكُمۡ وَلِیَ دِینِ ۝٦", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "لكم دينكم الذي أصررتم على اتباعه، ولي ديني الذي لا أبغي غيره.", "isBasmala": false, "translation_en": "You have your way, and I have my way.\"", "translation_id": "Untukmu agamamu, dan untukkulah, agamaku\".", "manzil": 7, "manzil_display": ""}, {"sura": 110, "sura_name": "النصر", "revelation": "Madaniyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 110, "sura_name": "النصر", "revelation": "Madaniyah", "aya": 1, "text": "إِذَا جَاۤءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إذا تمَّ لك -أيها الرسول- النصر على كفار قريش، وتم لك فتح \"مكة\".", "isBasmala": false, "translation_en": "When there comes God's victory, and conquest.", "translation_id": "Apabila telah datang pertolongan Allah dan kemenangan,", "manzil": 7, "manzil_display": ""}, {"sura": 110, "sura_name": "النصر", "revelation": "Madaniyah", "aya": 2, "text": "وَرَأَیۡتَ ٱلنَّاسَ یَدۡخُلُونَ فِی دِینِ ٱللَّهِ أَفۡوَاجࣰا ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ورأيت الكثير من الناس يدخلون في الإسلام جماعات جماعات.", "isBasmala": false, "translation_en": "And you see the people entering God's religion in multitudes.", "translation_id": "dan kamu lihat manusia masuk agama Allah dengan berbondong-bondong,", "manzil": 7, "manzil_display": ""}, {"sura": 110, "sura_name": "النصر", "revelation": "Madaniyah", "aya": 3, "text": "فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إذا وقع ذلك فتهيأ للقاء ربك بالإكثار من التسبيح بحمده والإكثار من استغفاره، إنه كان توابًا على المسبحين والمستغفرين، يتوب عليهم ويرحمهم ويقبل توبتهم.", "isBasmala": false, "translation_en": "Then celebrate the praise of your Lord, and seek His forgiveness. He is the Accepter of Repentance.", "translation_id": "maka bertasbihlah dengan memuji Tuhanmu dan mohonlah ampun kepada-Nya. Sesungguhnya Dia adalah Maha Penerima taubat.", "manzil": 7, "manzil_display": ""}, {"sura": 111, "sura_name": "المسد", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 111, "sura_name": "المسد", "revelation": "Makkiyah", "aya": 1, "text": "تَبَّتۡ یَدَاۤ أَبِی لَهَبࣲ وَتَبَّ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "خسرت يدا أبي لهب وشقي بإيذائه رسول الله محمدا صلى الله عليه وسلم، وقد تحقق خسران أبي لهب.", "isBasmala": false, "translation_en": "Condemned are the hands of Abee Lahab, and he is condemned.", "translation_id": "Binasalah kedua tangan Abu Lahab dan sesungguhnya dia akan binasa.", "manzil": 7, "manzil_display": ""}, {"sura": 111, "sura_name": "المسد", "revelation": "Makkiyah", "aya": 2, "text": "مَاۤ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ما أغنى عنه ماله وولده، فلن يَرُدَّا عنه شيئًا من عذاب الله إذا نزل به.", "isBasmala": false, "translation_en": "His wealth did not avail him, nor did what he acquired.", "translation_id": "Tidaklah berfaedah kepadanya harta bendanya dan apa yang ia usahakan.", "manzil": 7, "manzil_display": ""}, {"sura": 111, "sura_name": "المسد", "revelation": "Makkiyah", "aya": 3, "text": "سَیَصۡلَىٰ نَارࣰا ذَاتَ لَهَبࣲ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "سيدخل نارًا متأججة، هو وامرأته التي كانت تحمل الشوك، فتطرحه في طريق النبي صلى الله عليه وسلم؛ لأذيَّته.", "isBasmala": false, "translation_en": "He will burn in a Flaming Fire.", "translation_id": "Kelak dia akan masuk ke dalam api yang bergejolak.", "manzil": 7, "manzil_display": ""}, {"sura": 111, "sura_name": "المسد", "revelation": "Makkiyah", "aya": 4, "text": "وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "سيدخل نارًا متأججة، هو وامرأته التي كانت تحمل الشوك، فتطرحه في طريق النبي صلى الله عليه وسلم؛ لأذيَّته.", "isBasmala": false, "translation_en": "And his wife-the firewood carrier.", "translation_id": "Dan (begitu pula) istrinya, pembawa kayu bakar.", "manzil": 7, "manzil_display": ""}, {"sura": 111, "sura_name": "المسد", "revelation": "Makkiyah", "aya": 5, "text": "فِی جِیدِهَا حَبۡلࣱ مِّن مَّسَدِۭ ۝٥", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "في عنقها حبل محكم الفَتْلِ مِن ليف شديد خشن، تُرْفَع به في نار جهنم، ثم تُرْمى إلى أسفلها.", "isBasmala": false, "translation_en": "Around her neck is a rope of thorns.", "translation_id": "Yang di lehernya ada tali dari sabut.", "manzil": 7, "manzil_display": ""}], "604": [{"sura": 112, "sura_name": "الإخلاص", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 112, "sura_name": "الإخلاص", "revelation": "Makkiyah", "aya": 1, "text": "قُلۡ هُوَ ٱللَّهُ أَحَدٌ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "قل -أيها الرسول-: هو الله المتفرد بالألوهية والربوبية والأسماء والصفات، لا يشاركه أحد فيها.", "isBasmala": false, "translation_en": "Say, \"He is God, the One.", "translation_id": "Katakanlah: \"Dialah Allah, Yang Maha Esa.", "manzil": 7, "manzil_display": ""}, {"sura": 112, "sura_name": "الإخلاص", "revelation": "Makkiyah", "aya": 2, "text": "ٱللَّهُ ٱلصَّمَدُ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "الله وحده المقصود في قضاء الحوائج والرغائب.", "isBasmala": false, "translation_en": "God, the Absolute.", "translation_id": "Allah adalah Tuhan yang bergantung kepada-Nya segala sesuatu.", "manzil": 7, "manzil_display": ""}, {"sura": 112, "sura_name": "الإخلاص", "revelation": "Makkiyah", "aya": 3, "text": "لَمۡ یَلِدۡ وَلَمۡ یُولَدۡ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ليس له ولد ولا والد ولا صاحبة.", "isBasmala": false, "translation_en": "He begets not, nor was He begotten.", "translation_id": "Dia tiada beranak dan tidak pula diperanakkan,", "manzil": 7, "manzil_display": ""}, {"sura": 112, "sura_name": "الإخلاص", "revelation": "Makkiyah", "aya": 4, "text": "وَلَمۡ یَكُن لَّهُۥ كُفُوًا أَحَدُۢ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ولم يكن له مماثلا ولا مشابهًا أحد من خلقه، لا في أسمائه ولا في صفاته، ولا في أفعاله، تبارك وتعالى وتقدَّس.", "isBasmala": false, "translation_en": "And there is nothing comparable to Him.\"", "translation_id": "dan tidak ada seorangpun yang setara dengan Dia\".", "manzil": 7, "manzil_display": ""}, {"sura": 113, "sura_name": "الفلق", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 113, "sura_name": "الفلق", "revelation": "Makkiyah", "aya": 1, "text": "قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "قل -أيها الرسول-: أعوذ وأعتصم برب الفلق، وهو الصبح.", "isBasmala": false, "translation_en": "Say, \"I take refuge with the Lord of Daybreak.", "translation_id": "Katakanlah: \"Aku berlindung kepada Tuhan Yang Menguasai subuh,", "manzil": 7, "manzil_display": ""}, {"sura": 113, "sura_name": "الفلق", "revelation": "Makkiyah", "aya": 2, "text": "مِن شَرِّ مَا خَلَقَ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "من شر جميع المخلوقات وأذاها.", "isBasmala": false, "translation_en": "From the evil of what He created.", "translation_id": "dari kejahatan makhluk-Nya,", "manzil": 7, "manzil_display": ""}, {"sura": 113, "sura_name": "الفلق", "revelation": "Makkiyah", "aya": 3, "text": "وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ومن شر ليل شديد الظلمة إذا دخل وتغلغل، وما فيه من الشرور والمؤذيات.", "isBasmala": false, "translation_en": "And from the evil of the darkness as it gathers.", "translation_id": "dan dari kejahatan malam apabila telah gelap gulita,", "manzil": 7, "manzil_display": ""}, {"sura": 113, "sura_name": "الفلق", "revelation": "Makkiyah", "aya": 4, "text": "وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِی ٱلۡعُقَدِ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ومن شر الساحرات اللاتي ينفخن فيما يعقدن من عُقَد بقصد السحر.", "isBasmala": false, "translation_en": "And from the evil of those who practice sorcery.", "translation_id": "dan dari kejahatan wanita-wanita tukang sihir yang menghembus pada buhul-buhul,", "manzil": 7, "manzil_display": ""}, {"sura": 113, "sura_name": "الفلق", "revelation": "Makkiyah", "aya": 5, "text": "وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ۝٥", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ومن شر حاسد مبغض للناس إذا حسدهم على ما وهبهم الله من نعم، وأراد زوالها عنهم، وإيقاع الأذى بهم.", "isBasmala": false, "translation_en": "And from the evil of an envious when he envies.\"", "translation_id": "dan dari kejahatan pendengki bila ia dengki\".", "manzil": 7, "manzil_display": ""}, {"sura": 114, "sura_name": "الناس", "revelation": "Makkiyah", "aya": 0, "text": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ", "juz": 30, "hizb": "", "tafsir": "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ - أبدأ قراءة القرآن باسم الله مستعيناً به.", "isBasmala": true, "translation_en": "In the name of God, the Gracious, the Merciful.", "translation_id": "Dengan menyebut nama Allah Yang Maha Pemurah lagi Maha Penyayang.", "manzil": 7, "manzil_display": ""}, {"sura": 114, "sura_name": "الناس", "revelation": "Makkiyah", "aya": 1, "text": "قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ ۝١", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "قل -أيها الرسول-: أعوذ وأعتصم برب الناس، القادر وحده على ردِّ شر الوسواس.", "isBasmala": false, "translation_en": "Say, \"I seek refuge in the Lord of mankind.", "translation_id": "Katakanlah: \"Aku berlindung kepada Tuhan (yang memelihara dan menguasai) manusia.", "manzil": 7, "manzil_display": ""}, {"sura": 114, "sura_name": "الناس", "revelation": "Makkiyah", "aya": 2, "text": "مَلِكِ ٱلنَّاسِ ۝٢", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "ملك الناس المتصرف في كل شؤونهم، الغنيِّ عنهم.", "isBasmala": false, "translation_en": "The King of mankind.", "translation_id": "Raja manusia.", "manzil": 7, "manzil_display": ""}, {"sura": 114, "sura_name": "الناس", "revelation": "Makkiyah", "aya": 3, "text": "إِلَـٰهِ ٱلنَّاسِ ۝٣", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "إله الناس الذي لا معبود بحق سواه.", "isBasmala": false, "translation_en": "The God of mankind.", "translation_id": "Sembahan manusia.", "manzil": 7, "manzil_display": ""}, {"sura": 114, "sura_name": "الناس", "revelation": "Makkiyah", "aya": 4, "text": "مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ ۝٤", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "من أذى الشيطان الذي يوسوس عند الغفلة، ويختفي عند ذكر الله.", "isBasmala": false, "translation_en": "From the evil of the sneaky whisperer.", "translation_id": "Dari kejahatan (bisikan) syaitan yang biasa bersembunyi,", "manzil": 7, "manzil_display": ""}, {"sura": 114, "sura_name": "الناس", "revelation": "Makkiyah", "aya": 5, "text": "ٱلَّذِی یُوَسۡوِسُ فِی صُدُورِ ٱلنَّاسِ ۝٥", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "الذي يبثُّ الشر والشكوك في صدور الناس.", "isBasmala": false, "translation_en": "Who whispers into the hearts of people.", "translation_id": "yang membisikkan (kejahatan) ke dalam dada manusia,", "manzil": 7, "manzil_display": ""}, {"sura": 114, "sura_name": "الناس", "revelation": "Makkiyah", "aya": 6, "text": "مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ ۝٦", "juz": 30, "hizb": "(*¾ ح 60*)", "tafsir": "من شياطين الجن والإنس.", "isBasmala": false, "translation_en": "From among jinn and among people.\"", "translation_id": "dari (golongan) jin dan manusia.", "manzil": 7, "manzil_display": ""}]};
